INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Am Anfang schuf Gott Himmel und Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Und die Erde war wüst und leer, und es war finster auf der Tiefe; und der Geist Gottes schwebete auf dem Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Und Gott sprach: Es werde Licht! Und es ward Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah, dati das Licht gut war. Da schied Gott das Licht von der Finsternis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'und nannte das Licht Tag und die Finsternis Nacht. Da ward aus Abend und Morgen der erste Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: Es werde eine Feste zwischen den Wassern, und die sei ein Unterschied zwischen den Wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Da machte Gott die Feste und schied das Wasser unter der Feste von dem Wasser über der Feste. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Feste Himmel. Da ward aus Abend und Morgen derandere Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: Es sammle sich das Wasser unter dem Himmel an sondere Oder, daß man das Trockene sehe. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Erde, und die Sammlung der Wasser nannte er Meer. Und Gott sah, daß es gut war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: Es lasse die Erde aufgehen Gras und Kraut, das sich besame, und fruchtbare Baume, da ein jeglicher nach seiner Art Frucht trage und habe seinen eigenen Samen bei ihm selbst auf Erden. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Und die Erde lieft aufgehen Gras und Kraut, das sich besamte, ein jegliches nach seiner Art, und Baume, die da Frucht trugen und ihren eigenen Samen bei sich selbst hatten, ein jeglicher nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Da ward aus Abend und Morgen der dritte Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: Eswerden Lichterander Feste des Himmels, die da scheiden Tag und Nacht und geben Zeichen, Zeiten, Tage und Jahre;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'und seien Lichter an der Feste des Himmels, daß sie scheinen auf Erden. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Und Gott machte zwei grofte Lichter: ein graft Licht, das den Tag regiere, und ein klein Licht, das die Nacht regiere, dazu auch Sterne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott setzte sie an die Feste des Himmels, daß sie schienen auf die Erde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'und den Tag und die Nacht regierten und schieden Licht und Finsternis. Und Gott sah, daß es gut war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Da ward aus Abend und Morgen der vierte Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: Es errege sich das Wasser mit webenden und lebendigen Tieren und mit Gevogel, das auf Erden unter der Feste des Himmels fliege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Und Gott schuf grofte Walfische und allerlei Tier, das da lebet und webet und vom Wasser erreget ward, ein jegliches nach seiner Art; und allerlei gefiedertes Gevogel, ein jegliches nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und erfüllet das Wasser im Meer; und das Gevogel mehre sich auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Da ward aus Abend und Morgen der funfte Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach: Die Erde bringe hervor lebendige Tiere, ein jegliches nach seiner Art: Vieh, Gewürm und Tier auf Erden, ein jegliches nach seiner Art. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Und Gott machte die Tiere auf Erden, ein jegliches nach seiner Art, und das Vieh nach seiner Art und allerlei Gewürm auf Erden nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach: Laftt uns Menschen machen, ein Bild, das uns gleich sei, die da herrschen über die Fische im Meer und über die Vogel unter dem Himmel und über das Vieh und über die ganze Erde und über alles Gewürm, das auf Erden kreucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen ihm zum Bilde, zum Bilde Gottes schuf er ihn; und schuf sie ein Mannlein und Fraulein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und macht sie euch untertan, und herrschet über Fische im Meer und über Vogel unter dem Himmel und über alles Tier, das auf Erden kreucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Sehet da, ich habe euch gegeben allerlei Kraut, das sich besamet, auf der ganzen Erde, und allerlei fruchtbare Baume und Baume, die sich besamen, zu eurer Speise,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'und allem Tier auf Erden und alien Vogeln unter dem Himmel und allem Gewürme, das da Leben hat auf Erden, daß sie allerlei grün Kraut essen. Und es geschah also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah an alles, was er gemacht hatte; und siehe da, es war sehr gut. Da ward aus Abend und Morgen der sechste Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Also ward vollendet Himmel und Erde mit ihrem ganzen Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Und also vollendete Gott am siebenten Tage seine Werke, die er machte, und ruhete am siebenten Tage von alien seinen Werken, die er machte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'und segnete den siebenten Tag und heiligte ihn, darum daß er an demselben geruht hatte von alien seinen Werken, die Gott schuf und machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Also ist Himmel und Erde worden, da sie geschaffen sind, zu der Zeit, da Gott der HERR Erde und Himmel machte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'und allerlei Baume auf dem Felde, die zuvor nie gewesen waren auf Erden, und allerlei Kraut auf dem Felde, das zuvor nie gewachsen war. Denn Gott der HERR hatte noch nicht regnen lassen auf Erden, und war kein Mensch, der das Land bauete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Aber ein Nebel ging auf von der Erde und feuchtete alles Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Und Gott der HERR machte den Menschen aus einem Erdenkloft, und er blies ihm ein den lebendigen Odem in seine Nase. Und also ward der Mensch eine lebendige Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Und Gott der HERR pflanzte einen Garten in Eden gegen Morgen und setzte den Menschen drein, den er gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Gott der HERR lieft aufwachsen aus der Erde allerlei Baume, lustig anzusehen und gutzu essen, und den Baum des Lebens mitten im Garten und den Baum des Erkenntnisses Gutes und Boses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und es ging aus von Eden ein Strom, zu wassern den Garten, und teilete sich daselbst in vier Hauptwasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Das erste heiftt Pison, das fleufit urn das ganze Land Hevila, und daselbst findet man Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Und das Gold des Landes ist kostlich, und da findet man Bedellion und den Edelstein Onyx.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Das andere Wasser heißt Gihon, das flieftt urn das ganze Mohrenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Das dritte Wasser heilit Hiddekel, das fleufit von Assyrien. Das vierte Wasser ist der Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Und Gott der HERR nahm den Menschen und setzte ihn in den Garten Eden, daß er ihn bauete und bewahrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Gott der HERR gebot dem Menschen und sprach: Du sollst essen von allerlei Baumen im Garten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'aber von dem Baum des Erkenntnisses Gutes und Boses sollst du nicht essen. Denn welches Tages du davon issest, wirst du des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Gott der HERR sprach: Es ist nicht gut, daß der Mensch allein sei; ich will ihm eine Gehilfin machen, die urn ihn sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Denn als Gott der HERR gemacht hatte von der Erde allerlei Tiere auf dem Felde und allerlei Vogel unter dem Himmel, brachte er sie zu dem Menschen, daß er sahe, wie er sie nennete; denn wie der Mensch allerlei lebendige Tiere nennen wurde, so sollten sie heiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Und der Mensch gab einem jeglichen Vieh und Vogel unter dem Himmel und Tier auf dem Felde seinen Namen; aber fur den Menschen ward keine Gehilfin gefunden, die urn ihn ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da lieft Gott der HERR einen tiefen Schlaf fallen auf den Menschen, und er entschlief. Und nahm seiner Rippen eine und schloft die Statte zu mit Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Und Gott der HERR bauete ein Weib aus der Rippe, die ervon dem Menschen nahm, und brachte sie zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sprach der Mensch: Das ist doch Bein von meinem Bein und Fleisch von meinem Fleisch. Man wird sie Mannin heiften, darum daß sie vom Manne genommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum wird ein Mann seinen Vater und seine Mutter verlassen und an seinem Weibe hangen, und sie werden Sein ein Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackend, der Mensch und sein Weib, und schameten sich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Und die Schlange war listiger denn alle Tiere auf dem Felde, die Gott der HERR gemacht hatte, und sprach zu dem Weibe: Ja, sollte Gott gesagt haben: Ihr sollt nicht essen von allerlei Baumen im Garten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Da sprach das Weib zu der Schlange: Wir essen von den Fruchten der Baume im Garten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'aber von den Fruchten des Baumes mitten im Garten hat Gott gesagt: Esset nicht davon, ruhret es auch nicht an, daß ihr nicht sterbet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da sprach die Schlange zum Weibe: Ihrwerdet mitnichten des Todes sterben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'sondern Gottweift, daß, welches Tages ihr davon esset, so werden eure Augen aufgetan, und werdet sein wie Gott und wissen, was gut und bose ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Und das Weib schauete an, daß von dem Baum gut zu essen ware und lieblich anzusehen, daß es ein lustiger Baum ware, weil er klug machte, und nahm von der Frucht und aft und gab ihrem Mann auch davon, und eraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da wurden ihrer beiden Augen aufgetan und wurden gewahr, daß sie nackend waren, und flochten Feigenblatter zusammen und machten ihnen Schurze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Und sie horeten die Stimme Gottes des HERRN, der im Garten ging, da der Tag kuhl worden war. Und Adam versteckte sich mit seinem Weibe vor dem Angesicht Gottes des HERRN unter die Baume im Garten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Und Gott der HERR rief Adam und sprach zu ihm: Wo bist du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Und er sprach: Ich horete deine Stimme im Garten und furchtete mich, denn ich bin nackend; darum versteckte ich mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Und er sprach: Wer hat dir\'s gesagt, daß du nackend bist? Hast du nicht gegessen von dem Baum, davon ich dir gebot, du solltest nicht davon essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Da sprach Adam: Das Weib, das du mir zugesellet hast, gab mir von dem Baum, und ich aft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sprach Gott der HERR zum Weibe: Warum hast du das getan? Das Weib sprach: Die Schlange betrog mich also, daß ich aft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sprach Gott der HERR zu der Schlange: Weil du solches getan hast, seiest du verflucht vor allem Vieh und vor alien Tieren auf dem Felde. Auf deinem Bauch sollst du gehen und Erde essen dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und ich will Feindschaft setzen zwischen dir und dem Weibe und zwischen deinem Samen und ihrem Samen. Der selbe soli dir den Kopf zertreten, und du wirst ihn in die Ferse stechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Und zum Weibe sprach er: Ich will dirviel Schmerzen schaffen, wenn du schwanger wirst; du sollst mit Schmerzen Kinder gebaren; und dein Wille soil deinem Mann unterworfen sein, und er soil dein Herrsein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zu Adam sprach er: Dieweil du hast gehorchet der Stimme deines Weibes und gegessen von dem Baume, davon ich dirgebot und sprach: Du sollst nicht davon essen; verflucht sei der Acker um deinetwillen; mit Kummer sollst du dich drauf nahren dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Dornen und Disteln soil erdirtragen, und sollst das Kraut auf dem Felde essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiß deines Angesichts sollst du dein Brat essen, bis daß du wieder zu Erde werdest, davon du genommen bist. Denn du bist Erde und sollst zu Erde werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und Adam hieß sein Weib Heva, darum daß sie eine Mutter ist aller Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Gott der HERR machte Adam und seinem Weibe Rocke von Fellen und zog sie ihnen an,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Gott der HERR sprach: Siehe, Adam ist worden als unsereiner und weiß, was gut und bose ist. Nun aber, daß er nicht ausstrecke seine Hand und breche auch von dem Baum des Lebens und esse und lebe ewiglich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'da ließ ihn Gott der HERR aus dem Garten Eden, dafi erdas Feld bauete, davon er genommen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'und trieb Adam aus und lagerte vor den Garten Eden den Cherub miteinem bloßen hauenden Schwert, zu bewahren den Weg zu dem Baum des Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Und Adam erkannte sein Weib Heva, und sie ward schwanger und gebar den Kain und sprach: Ich habe den Mann, des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und sie fuhr fort und gebar Habel, seinen Bruder. Und Habel ward ein Schafer, Kain aber ward ein Ackermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Es begab sich aber nach etlichen Tagen, daß Kain dem HERRN Opfer brachte von den Fruchten des Feldes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'und Habel brachte auch von den Erstlingen seiner Herde und von ihrem Fetten. Und der HERR sah gnadiglich an Habel und seine Opfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'aber Kain und sein Opfer sah er nicht gnadiglich an. Da ergrimmete Kain sehr, und seine Gebarde verstellte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Da sprach der HERR zu Kain: Warum ergrimmest du, und warum verstellet sich deine Gebarde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ist\'s nicht also? wenn du fromm bist, so bist du angenehm; bist du aber nicht fromm, so ruhet die Sünde vor der Tur. Aber laß du ihr nicht ihren Willen, sondern herrsche uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Da redete Kain mit seinem Bruder Habel. Und es begab sich, da sie auf dem Felde waren, erhub sich Kain wider seinen Bruder Habel und schlug ihn tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sprach der HERR zu Kain: Wo ist dein Bruder Habel? Er sprach: Ich weili nicht; soli ich meines Bruders Huter sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Er aber sprach: Was hast du getan? Die Stimme deines Bruders Bluts schreiet zu mir von der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun verflucht seiest du auf der Erde, die ihr Maul hat aufgetan und deines Bruders Blut von deinen Handen empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Acker bauen wirst, soli er dir fort sein Vermogen nicht geben. Unstet und fluchtig sollst du sein auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Kain aber sprach zu dem HERRN: Meine Sünde ist grofier, denn daß sie mir vergeben werden mdge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Siehe, du treibest mich heute aus dem Lande und muß mich vor deinem Angesicht verbergen und muß unstet und fluchtig sein auf Erden. So wird mir\'s gehen, daß mich totschlage, wer mich findet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Aber der HERR sprach zu ihm: Nein, sondern wer Kain totschlagt, das soil siebenfaltig gerochen werden. Und der HERR machte ein Zeichen an Kain, daß ihn niemand erschluge, wer ihn fande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Alsoging Kain von dem Angesicht des HERRN und wohnete im Lande Nod, jenseit Eden, gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain erkannte sein Weib, die ward schwanger und gebar den Hanoch. Und er bauete eine Stadt, die nannte er nach seines Sohnes Namen Hanoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Hanoch aberzeugete Irad, Irad zeugete Mahujael, Mahujael zeugete Methusael, Methusael zeugete Lamech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lamech aber nahm zwei Weiber; eine hieß Ada, die andere Zilla.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Ada gebar Jabal; von dem sind herkommen, die in Hutten wohneten und Vieh zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Und sein Bruder hieß Jubal; von dem sind herkommen die Geiger und Pfeifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Die Zilla aber gebar auch, namlich dem Thubalkain, den Meister in allerlei Erz und Eisenwerk. Und die Schwester des Thubalkain war Naema.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Und Lamech sprach zu seinen Weibern, Ada und Zilla: Ihr Weiber Lamechs, horet meine Rede und merket, was ich sage: Ich habe einen Mann erschlagen mirzur Wunde und einen Jungling mirzur Beule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Kain soil siebenmal gerochen werden, aber Lamech siebenundsiebenzigmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Adam erkannte abermal sein Weib, und sie gebar einen Sohn, den hieß sie Seth; denn Gott hat mir, sprach sie, einen andern Samen gesetzt fur Habel, den Kain erwurget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und Seth zeugete auch einen Sohn und hieß ihn Enos. Zu derselbigen Zeit fing man an zu predigen von des HERRN Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist das Buch von des Menschen Geschlecht. Da Gott den Menschen schuf, machte er ihn nach dem Gleichnis Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'und schuf sie ein Mannlein und Fraulein; und segnete sie und hied ihren Namen Mensch zur Zeit, da sie geschaffen wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Und Adam war hundertunddreidig Jahre alt und zeugete einen Sohn. der seinem Bilde ahnlich war, und hied ihn Seth;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'und lebte danach achthundert Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'dad sein ganzes Alter ward neunhundertunddreidig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Seth war hundertundfunf Jahre alt und zeugte Enos;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'und lebte danach achthundertundsieben Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'dad sein ganzes Alter ward neunhundertundzwolf Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos war neunzig Jahre alt und zeugete Kenan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'und lebte danach achthundertundfünfzehn Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'dad sein ganzes Alter ward neunhundertundfunf Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan warsiebenzig Jahre alt und zeugete Mahalaleel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'und lebte danach achthundertundvierzig Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'dad sein ganzes Alter ward neunhundertundzehn Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel war fünfundsechzig Jahre alt und zeugete Jared;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'und lebte danach achthundertunddreidig Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'dad sein ganzes Alter ward achthundertfunfundneunzig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared war hundertundzweiundsechzig Jahre alt und zeugete Henoch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'und lebte danach achthundert Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'dad sein ganzes Alter ward neunhundertzweiundsechzig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henoch war fünfundsechzig Jahre alt und zeugete Methusalah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Und nachdem er Methusalah gezeuget hatte, blieb er in einem gottlichen Leben dreihundert Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'dad sein ganzes Alter ward dreihundertfunfundsechzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und dieweil er ein gottlich Leben fuhrete, nahm ihn Gott hinweg, und ward nicht mehr gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Methusalah war hundertsiebenundachtzig Jahre alt und zeugete Lamech;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'und lebte danach siebenhundertzweiundachtzig Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'dad sein ganzes Alter ward neunhundertneunundsechzig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamech war hundertzweiundachtzig Jahre alt und zeugete einen Sohn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'und hied ihn Noah und sprach: Derwird uns trosten in unserer Mühe und Arbeit auf Erden, die der HERRverflucht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Danach lebte erfunfhundertfunfundneunzig Jahre und zeugete Sohne und Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'dad sein ganzes Alter ward siebenhundertsiebenundsiebenzig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noah war fünfhundert Jahre alt und zeugete Sem, Ham und Japheth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Da sich aber die Menschen begannen zu mehren auf Erden und zeugeten ihnen Tochter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'da sahen die Kinder Gottes nach den Tochtern der Menschen, wie sie schon waren und nahmen zu Weibern, welche sie wollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sprach der HERR: Die Menschen wollen sich von meinem Geist nicht mehr strafen lassen, denn sie sind Fleisch. Ich will ihnen noch Frist geben hundertundzwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Es waren auch zu den Zeiten Tyrannen auf Erden; denn da die Kinder Gottes die Tochter der Menschen beschliefen und ihnen Kinder zeugeten, wurden daraus Gewaltige in der Welt und beruhmte Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Da aber der HERR sah, daß der Menschen Bosheit grofi war auf Erden und alles Dichten und Trachten ihres Herzens nur bose war immerdar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'da reuete es ihn, daß er die Menschen gemacht hatte auf Erden, und es bekummerte ihn in seinem Herzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'und sprach: Ich will die Menschen, die ich geschaffen habe, vertilgen von der Erde, von den Menschen an bis auf das Vieh und bis auf das Gewurme und bis auf die Vogel unterdem Himmel; denn es reuet mich, dafi ich sie gemacht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Aber Noah fand Gnade vordem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies ist das Geschlecht Noahs: Noah war ein frommer Mann und ohne Wandel und fuhrete ein gottlich Leben zu seinen Zeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und zeugete drei Sohne, Sem, Ham, Japheth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Aber die Erde war verderbet vor Gottes Augen und voll Frevels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Da sah Gott auf Erden, und siehe, sie war verderbet; denn alles Fleisch hatte seinen Weg verderbet auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sprach Gott zu Noah: Alles Fleisches Ende ist vor mich kommen, denn die Erde ist voll Frevels von ihnen; und siehe da, ich will sie verderben mitder Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mache dir einen Kasten von Tannenholz und mache Kammern drinnen und verpiche sie mit Pech inwendig und auswendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und mache ihn also: Dreihundert Ellen sei die Lange, funfzig Ellen die Weite und dreüßig Ellen die Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ein Fenster sollst du dran machen, oben an, eine Elle graft. Die Tür sollst du mitten in seine Seite setzen. Und soil drei Boden haben, einen unten, den andem in der Mitte, den dritten in der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Denn siehe, ich will eine Sintflut mit Wasser kommen lassen auf Erden, zu verderben alles Fleisch, darin ein lebendiger Odem ist unter dem Himmel. Alles, was auf Erden ist, soil untergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will ich einen Bund aufrichten; und du sollst in den Kasten gehen mit deinen Sohnen, mit deinem Weibe und mit deiner Sohne Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und du sollst in den Kasten tun allerlei Tiere von allem Fleisch, je ein Paar, Mannlein und Fraulein, daß sie lebendig bleiben bei dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von den Vogeln nach ihrer Art, von dem Vieh nach seiner Art und von allerlei Gewürm auf Erden nach seiner Art: von den alien soli je ein Paar zu dir hineingehen, daß sie leben bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Und du sollst allerlei Speise zu dir nehmen, die man isset; und sollst sie bei dir sammeln, daß sie dir und ihnen zur Nahrung da seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noah tat alles, was ihm Gott gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Und der HERR sprach zu Noah: Gehe in den Kasten, du und dein ganz Haus; denn dich habe ich gerecht ersehen vor mir zu dieser Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Aus allerlei reinem Vieh nimm zu dir je sieben und sieben, das Mannlein und sein Fraulein; von dem unreinen Vieh aberje ein Paar, das Mannlein und sein Fraulein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Desselbengleichen von den Vogeln unter dem Himmel je sieben und sieben, das Mannlein und sein Fraulein, auf daß Same lebendig bleibe auf dem ganzen Erdboden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn noch uber sieben Tage will ich regnen lassen auf Erden vierzig Tage und vierzig Nachte und vertilgen von dem Erdboden alles, was das Wesen hat, das ich gemacht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noah tat alles, was ihm der HERR gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Er war aber sechshundert Jahre alt, da das Wasser der Sintflut auf Erden kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Und er ging in den Kasten mit seinen Sohnen, seinem Weibe und seiner Sohne Weibern vor dem Gewasser der Sintflut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von dem reinen Vieh und von dem unreinen, von den Vogeln und von allem Gewürm auf Erden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'gingen zu ihm in den Kasten bei Paaren, je ein Mannlein und Fraulein, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und da die sieben Tage vergangen waren, kam das Gewasser der Sintflut auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'In dem sechshundertsten Jahr des Alters Noah, am siebzehnten Tag des andem Monats, das ist der Tag, da aufbrachen alle Brunnen dergroften Tiefe, und taten sich auf die Fenster des Himmels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'und kam ein Regen auf Erden, vierzig Tage und vierzig Nachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Eben am selben Tage ging Noah in den Kasten mit Sem, Ham und Japheth, seinen Sohnen, und mit seinem Weibe und seiner Sohne dreien Weibern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'dazu allerlei Tier nach seiner Art, allerlei Vieh nach seiner Art, allerlei Gewurm, das auf Erden kreucht, nach seiner Art und allerlei Vogel nach ihrer Art alles, was fliegen konnte, und alles, was Fittiche hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Das ging alles zu Noah in den Kasten bei Paaren, von allem Fleisch, da ein lebendiger Geist innen war');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'und das waren Mannlein und Fraulein von allerlei Fleisch und gingen hinein, wie denn Gott ihm geboten hatte. Und der HERR schloft hinter ihm zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da kam die Sintflut vierzig Tage auf Erden; und die Wasser wuchsen und huben den Kasten auf und trugen ihn empor fiber der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Also nahm das Gewasser uberhand und wuchs sehr auf Erden, daß der Kasten auf dem Gewasser fuhr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und das Gewasser nahm uberhand und wuchs so sehr auf Erden, daß alle hohen Berge unter dem ganzen Himmel bedeckt wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen hoch ging das Gewasser fiber die Berge, die bedeckt wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da ging alles Fleisch unter, das auf Erden kreucht, an Vogeln, an Vieh, an Tieren und an allem, das sich reget auf Erden, und an alien Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alles, was einen lebendigen Odem hatte im Trocknen, das starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Also ward vertilget alles, was auf dem Erdboden war, vom Menschen an bis auf das Vieh und auf das Gewurm und auf die Vogel unter dem Himmel: das ward alles von der Erde vertilget. Allein Noah blieb fiber, und was mit ihm in dem Kasten war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und das Gewasser stund auf Erden hundertundfunfzig Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da gedachte Gott an Noah und an alle Tiere und alles Vieh, das mit ihm in dem Kasten war, und lieft Wind auf Erden kommen, und die Wasser fielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Und die Brunnen der Tiefe wurden verstopfet samt den Fenstern des Himmels, und dem Regen vom Himmel ward gewehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Und das Gewasser verlief sich von der Erde immer hin und nahm ab nach hundertundfunfzig Tagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Am siebzehnten Tage des siebenten Mondes lieft sich der Kasten nieder auf das Gebirge Ararat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Es verlief aber das Gewasser fortan und nahm ab bis auf den zehnten Mond. Am ersten Tage des zehnten Mondes sahen der Berge Spitzen hervor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Nach vierzig Tagen tat Noah das Fenster auf an dem Kasten, das er gemacht hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'und lieft einen Raben ausfliegen; der flog immer hin und wieder her, bis das Gewasser vertrocknete auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Danach ließ er eine Taube von sich ausfliegen, auf daß er erfuhre, ob das Gewasser gefallen ware auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Da aber die Taube nicht fand, da ihr Fuß ruhen konnte, kam sie wieder zu ihm in den Kasten; denn das Gewasser war noch auf dem ganzen Erdboden. Da tat er die Hand heraus und nahm sie zu sich in den Kasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Da harrete er noch andere sieben Tage und ließ abermals eine Taube fliegen aus dem Kasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Die kam zu ihm urn Vesperzeit, und siehe, ein Olblatt hatte sie abgebrochen und trug\'s in ihrem Munde. Da vernahm Noah, daß das Gewasser gefallen ware auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Aber er harrete noch andere sieben Tage und liefi eine Taube ausfliegen, die kam nicht wieder zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Im sechshundert und ersten Jahr des Alters Noahs, am ersten Tage des ersten Monden, vertrocknete das Gewasser auf Erden. Da tat Noah das Dach von dem Kasten und sah, daß der Erdboden trocken war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Also ward die Erde ganz trocken am siebenundzwanzigsten Tage des andern Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da redete Gott mit Noah und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gehe aus dem Kasten, du und dein Weib, deine Sohne und deiner Sohne Weiber mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Allerlei Tier, das bei dir ist, von allerlei Fleisch, an Vogeln, an Vieh und an allerlei Gewurm, das auf Erden kreucht, das gehe heraus mit dir; und reget euch auf Erden und seid fruchtbar und mehret euch auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Also ging Noah heraus mit seinen Sohnen und seinem Weibe und seiner Sohne Weibern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'dazu allerlei Tier, allerlei Gewurm, allerlei Vogel und alles, was auf Erden kreucht, das ging aus dem Kasten, ein jegliches zu seinesgleichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noah aber bauete dem HERRN einen Altar und nahm von allerlei reinem Vieh und von allerlei reinem Gevogel und opferte Brandopfer auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Und der HERR roch den lieblichen Geruch und sprach in seinem Herzen: Ich will hinfort nicht mehr die Erde verfluchen urn der Menschen willen; denn das Dichten des menschlichen Herzens ist bose von Jugend auf. Und ich will hinfort nicht mehr schlagen alles, was da lebet, wie ich getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Solange die Erde stehet, soil nicht aufhoren Samen und Ernte, Frost und Hitze, Sommer und Winter, Tag und Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Und Gott segnete Noah und seine Sohne und sprach: Seid fruchtbar und mehret euch und erfüllet die Erde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Eure Furcht und Schrecken sei uber alle Tiere auf Erden, uber alle Vogel unter dem Himmel und uber alles, was auf dem Erdboden kreucht; und alle Fische im Meer seien in eure Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles, was sich reget und lebet, das sei eure Speise; wie das grune Kraut habe ich\'s euch alles gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Allein esset das Fleisch nicht, das noch lebet in seinem Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Denn ich will auch eures Leibes Blut rachen und will\'s an alien Tieren rachen; und will des Menschen Leben rachen an einem jeglichen Menschen, als der sein Bruder ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer Menschenblut vergeußt, des Blut soil auch durch Menschen vergossen werden; denn Gott hat den Menschen zu seinem Bilde gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Seid fruchtbar und mehret euch und reget euch auf Erden, daß euerviel drauf werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Und Gott sagte zu Noah und seinen Sohnen mit ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Siehe, ich richte mit euch einen Bund auf und mit eurem Samen nach euch');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'und mit allem lebendigen Tier bei euch, an Vogeln, an Vieh und an alien Tieren auf Erden bei euch, von allem, das aus dem Kasten gegangen ist, was fur Tiere es sind auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Und richte meinen Bund also mit euch auf, daß hinfort nicht mehr alles Fleisch verderbet soil werden mit dem Wasser der Sintflut, und soil hinfort keine Sintflut mehr kommen, die die Erde verderbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Das ist das Zeichen des Bundes, den ich gemacht habe zwischen mir und euch und allem lebendigen Tier bei euch hinfort ewiglich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meinen Bogen habe ich gesetzt in die Wolken, der soil das Zeichen sein des Bundes zwischen mir und der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Und wenn es kommt, daß ich Wolken uber die Erde führe, so soil man meinen Bogen sehen in den Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Alsdann will ich gedenken an meinen Bund zwischen mir und euch und allem lebendigen Tier in allerlei Fleisch, daß nicht mehr hinfort eine Sintflut komme, die alles Fleisch verderbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Darum soil mein Bogen in den Wolken sein, daß ich ihn ansehe und gedenke an den ewigen Bund zwischen Gott und allem lebendigen Tier in allem Fleisch, das auf Erden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dasselbe sagte Gott auch zu Noah: Dies sei das Zeichen des Bundes, den ich aufgerichtet habe zwischen mir und allem Fleisch auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Die Sohne Noahs, die aus dem Kasten gingen, sind diese: Sem, Ham, Japheth. Ham aber ist der Vater Kanaans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Das sind die drei Sohne Noahs, von denen ist alles Land besetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Noah aber fing an und ward ein Ackermann und pflanzte Weinberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Und da er des Weins trank, ward er trunken und lag in der Hütte aufgedeckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Da nun Ham, Kanaans Vater, sah seines Vaters Scham, sagte er\'s seinen beiden Brudern drauißen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da nahm Sem und Japheth ein Kleid und legten es auf ihre beiden Schultern und gingen rücklings hinzu und deckten ihres Vaters Scham zu; und ihr Angesicht war abgewandt, dafi sie ihres Vaters Scham nichtsahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Als nun Noah erwachte von seinem Wein und erfuhr, was ihm sein kleiner Sohn getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'sprach er: Verflucht sei Kanaan und sei ein Knecht aller Knechte unter seinen Brudern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und sprach weiter: Gelobet sei Gott, der HERR des Sem; und Kanaan sei sein Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gott breite Japheth aus und lasse ihn wohnen in den Hutten des Sem: und Kanaan sei sein Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Noah aber lebte nach der Sintflut dreihundertundfünfzig Jahre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'daß sein ganzes Alter ward neunhundertundfünfzig Jahre, und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Dies ist das Geschlecht der Kinder Noahs: Sem, Ham, Japheth. Und sie zeugeten Kinder nach der Sintflut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Kinder Japheths sind diese: Gomer, Magog, Madai, Javan, Thubal, Mesech und Thiras.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Aber die Kinder von Gomer sind diese: Askenas, Riphath und Thogarma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Die Kinder von Javan sind diese: Elisa, Tharsis, Kittim und Dodanim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen sind ausgebreitet die Inseln der Heiden in ihren Landern, jegliche nach ihrerßprache, Geschlecht und Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Die Kinder von Ham sind diese: Chus, Mizraim, Put und Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Aber die Kinder von Chus sind diese. Seba, Hevila, Sabtha, Raema und Sabtecha. Aber die Kinder von Raema sind diese: Scheba und Dedan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Chus aber zeugete den Nimrod. Derfing an ein gewaltiger Herr zu sein auf Erden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'und war ein gewaltiger Jager vor dem HERRN. Daher spricht man: Das ist ein gewaltiger Jager vor dem HERRN, wie Nimrod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Und der Anfang seines Reichs war Babel, Erech, Ackad und Kalne im Lande Sinear.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von dem Land istdanach kommen der Assur und bauete Ninive und Rehoboth-lr und Kalah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'dazu Resen zwischen Ninive und Kalah. Dies ist eine grotße Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim zeugete Ludim, Anamim, Leabim, Naphthuhim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Pathrusim und Kasluhim. Von dannen sind kommen die Philistim und Kaphthorim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan aber zeugete Zidon, seinen ersten Sohn, und Heth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Jebusi, Emori, Girgasi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hivi, Arki, Sini,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvadi, Zemari und Hamathi. Daher sind ausgebreitet die Geschlechter der Kanaaniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Und ihre Grenzen waren von Zidon an durch Gerar bis gen Gasa, bis man kommt gen Sodoma, Gomorrha, Adama, Zeboim und bis gen Lasa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Das sind die Kinder Hams in ihren Geschlechtern, Sprachen, Landern und Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Sem aber, Japheths, des groliern, Bruder, zeugete auch Kinder, der ein Vater ist aller Kinder von Eber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Und dies sind seine Kinder: Elam, Assur, Arphachsad, Lud und Aram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Die Kinder aber von Aram sind diese: Uz, Hut, Gether und Mas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arphachsad aber zeugete Salah, Salah zeugete Eber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eber zeugete zween Sohne. Einer hiefi Peleg, darum dafi zu seiner Zeit die Welt zerteilet ward; des Bruder hiefi Jaketan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Jaketan zeugete Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Usal, Dikela,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Seba,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophir, Hevila und Jobab. Das sind alle Kinder von Jaketan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihre Wohnung war von Mesa an, bis man kommt gen Sephar, an den Berg gegen den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Das sind die Kinder von Sem in ihren Geschlechtern, Sprachen, Landern und Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Das sind nun die Nachkommen der Kinder Noahs in ihren Geschlechtern und Leuten. Von denen sind ausgebreitet die Leute auf Erden nach der Sintflut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Es hatte aber alle Welt einerlei Zunge und Sprache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Da sie nun zogen gen Morgen, fanden sie ein eben Land im Lande Sinear und wohneten daselbst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'und sprachen untereinander: Wohlauf, lafit uns Ziegel streichen und brennen! Und nahmen Ziegel zu Stein und Ton zu Kalk');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'und sprachen: Wohlauf, lafit uns eine Stadt und Turm bauen, des Spitze bis an den Himmel reiche, dafi wir uns einen Namen machen; denn wir werden vielleicht zerstreuet in alle Lander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da fuhr der HERR hernieder, dafi er sahe die Stadt und Turm, die die Menschenkinder baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und der HERR sprach: Siehe, es ist einerlei Volk und einerlei Sprache unter ihnen alien, und haben das angefangen zu tun; sie werden nicht ablassen von allem, das sie vorgenommen haben zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlauf, lafit uns herniederfahren und ihre Sprache daselbst verwirren, daß keiner des andern Sprache vernehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Also zerstreuete sie der HERR von dannen in alle Lander, dafi sie mul Men aufhoren, die Stadt zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Daher heißt ihr Name Babel, daß der HERR daselbst verwirret hatte aller Lander Sprache und sie zerstreuet von dannen in alle Lander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies sind die Geschlechter Sems: Sem war hundert Jahre alt und zeugete Arphachsad, zwei Jahre nach der Sintflut;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'und lebte danach fünfhundert Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arphachsad war funfunddreiftig Jahre alt und zeugete Salah;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'und lebte danach vierhundertunddrei Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Salah war dreiftig Jahre alt und zeugete Eber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'und lebte danach vierhundertunddrei Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber war vierunddreiftig Jahre alt und zeugete Peleg;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'und lebte danach vierhundertunddreiftig Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg war dreiftig Jahre alt und zeugete Regu;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'und lebte danach zweihundertundneun Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu warzweiunddreißig Jahre alt und zeugete Serug;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'und lebte danach zweihundertundsieben Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug war dreiftig Jahre alt und zeugete Nahor;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'und lebte danach zweihundert Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor war neunundzwanzig Jahre alt und zeugete Tharah;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'und lebte danach hundertundneunzehn Jahre und zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Tharah war siebenzig Jahre alt und zeugete Abram, Nahor und Haran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Dies sind die Geschlechter Tharahs: Tharah zeugete Abram, Nahor und Haran. Aber Haran zeugete Lot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Haran aber starb vor seinem Vater Tharah in seinem Vaterland zu Ur in Chaldaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Da nahmen Abram und Nahor Weiber. Abrams Weib hied Sarai und Nahors Weib Milka, Harans Tochter, der ein Vater war der Milka und der Jiska.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Aber Sarai war unfruchtbar und hatte kein Kind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Da nahm Tharah seinen Sohn Abram und Lot, seines Sohns Harans Sohn, und seine Schnur Sarai, seines Sohns Abrams Weib, und führete sie von Ur aus Chaldaa, dad er ins Land Kanaan zoge; und sie kamen gen Haran und wohneten daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Und Tharah ward zweihundertundfünf Jahre alt und starb in Haran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Und der HERR sprach zu Abram: Gehe aus deinem Vaterland und von deiner Freundschaft und aus deines Vaters Hause in ein Land, das ich dir zeigen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Und ich will dich zum groden Volk machen und will dich segnen und dir einen groden Namen machen, und sollst ein Segen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Ich will segnen, die dich segnen, und verfluchen, die dich verfluchen; und in dir sollen gesegnet werden alle Geschlechter auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Da zog Abram aus, wie der HERR zu ihm gesagt hatte; und Lot zog mit ihm. Abram aber war funfundsiebenzig Jahre alt, da er aus Haran zog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Also nahm Abram sein Weib Sarai und Lot, seines Bruders Sohn, mit aller ihrer Habe, die sie gewonnen hatten, und Seelen, die sie gezeuget hatten in Haran, und zogen aus, zu reisen in das Land Kanaan. Und als sie kommen waren in dasselbige Land,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'zog Abram durch bis an die Statte Sichem und an den Hain More. Denn es wohneten zu der Zeit die Kanaaniter im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da erschien der HERR Abram und sprach: Deinem Samen will ich dies Land geben. Und er bauete daselbst dem HERRN einen Altar, der ihm erschienen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Danach brach er auf von dannen an einen Berg, der lag gegen dem Morgen der Stadt Bethel, und richtete seine Hütte auf, daß er Bethel gegen Abend und Ai gegen dem Morgen hatte, und bauete daselbst dem HERRN einen Altar und predigte von dem Namen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Danach wich Abram ferner und zog aus gegen den Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Es kam aber eine Teurung in das Land. Da zog Abram hinab in Agypten, daß er sich daselbst als ein Fremdling enthielte; denn die Teurung war groß im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Und da er nahe bei Agypten kam, sprach er zu seinem Weibe Sarai: Siehe, ich weiß, daß du ein schon Weib von Angesicht bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Wenn dich nun die Agypter sehen werden, so werden sie sagen: Das ist sein Weib; und sie werden mich erwurgen und dich behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Lieber, sage doch, du seiest meine Schwester, auf daß mir\'s desto baß gehe urn deinetwillen, und meine Seele bei dem Leben bleibe urn deinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Als nun Abram nach Agypten kam, sahen die Agypter das Weib, daß sie fast schon war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und die Fursten des Pharao sahen sie und preiseten sie vor ihm. Da ward sie in des Pharao Haus gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Und er tat Abram Gutes urn ihretwillen. Und er hatte Schafe, Rinder, Esel, Knechte und Magde, Eselinnen und Kamele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Aber der HERR plagte den Pharao mit großen Plagen und sein Haus urn Sarais, Abrams Weibes, willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da rief Pharao Abram zu sich und sprach zu ihm: Warum hast du mir das getan? Warum sagtest du mir\'s nicht, daß sie dein Weib ware?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum sprachest du denn, sie ware deine Schwester? derhalben ich sie mir zum Weibe nehme wollte. Und nun siehe, da hast du dein Weib; nimm sie und zeuch hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und Pharao befahl seinen Leuten uber ihm, daß sie ihn geleiteten und sein Weib und alles, was er hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Also zog Abram herauf aus Agypten mit seinem Weibe und mit allem, das er hatte, und Lot auch mit ihm, gegen den Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram aber war sehr reich von Vieh, Silber und Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und erzog immer fort von Mittag bis gen Bethel, an die Statte da am ersten seine Hütte war, zwischen Bethel und Ai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'eben an den Ort, da er vorhin den Altar gemacht hatte. Und er predigte allda den Namen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Lot aber, der mit Abram zog, der hatte auch Schafe und Rinder und Hutten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Und das Land mochte es nicht ertragen, daß sie beieinander wohneten; denn ihre Habe war groß, und konnten nicht beieinander wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und war immer Zank zwischen den Hirten uber Abrams Vieh und zwischen den Hirten uber Lots Vieh. So wohneten auch zu der Zeit die Kanaaniter und Pheresiter im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sprach Abram zu Lot: Lieber, laß nicht Zank sein zwischen mir und dir und zwischen meinen und deinen Hirten; denn wirsind Gebruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Stehet dir nicht alles Land often? Lieber, scheide dich von mir! Willst du zur Linken, so will ich zur Rechten; Oder willst du zur Rechten, so will ich zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da hub Lot seine Augen auf und besah die ganze Gegend am Jordan. Denn ehe der HERR Sodoma und Gomorrha verderbete, war sie wasserreich, bis man gen Zoar kommt, als ein Garten des HERRN, gleichwie Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Da erwahlete ihm Lot die ganze Gegend am Jordan und zog gegen Morgen. Also schied sich ein Brudervon dem andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'daß Abram wohnete im Lande Kanaan und Lot in den Stadten der selben Gegend; und setzte seine Hutten gen Sodom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Aber die Leute zu Sodom waren bose und sundigten sehr wider den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Da nun Lot sich von Abram geschieden hatte, sprach der HERR zu Abram: Hebe deine Augen auf und siehe von der Statte an, da du wohnest, gegen Mitternacht, gegen den Mittag, gegen den Morgen und gegen den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn alle das Land, das du siehest, will ich dir geben und deinem Samen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und will deinen Samen machen wie den Staub auf Erden. Kann ein Mensch den Staub auf Erden zahlen, derwird auch deinen Samen zahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Darum so mach dich auf und zeuch durch das Land in die Lange und Breite; denn dir will ich\'s geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Also erhub Abram seine Hutten, kam und wohnete im Hain Mamre; der zu Hebron ist, und bauete daselbst dem HERRN einen Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Und es begab sich zu der Zeit des Konigs Amraphel von Sinear, Arioch, des Konigs von Elassar, Kedor-Laomor, des Konigs von Elam, und Thideal, des Konigs der Heiden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'daß sie kriegten mit Bera, dem Konige von Sodom, und mit Birsa, dem Konige von Gomorrha, und mit Sineab, dem Konige von Adama, und mit Semeber, dem Konige von Zeboim, und mit dem Konige von Bela, die heißt Zoar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Diese kamen alle zusammen in das Tal Siddim, da nun das Salzmeer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Denn sie waren zwolf Jahre unter dem Konige Kedor-Laomor gewesen und im dreizehnten Jahr waren sie von ihm abgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Darum kam Kedor-Laomor und die Konige, die mit ihm waren, im vierzehnten Jahr und schlugen die Riesen zu Astharoth-Karnaim und die Susim zu Ham und die Emim in dem Felde Kiriathaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'und die Horiter auf ihrem Gebirge Seir bis an die Breite Pharan, welche an die Wuste stoßet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Danach wandten sie urn und kamen an den Born Mispat, das ist, Kades, und schlugen das ganze Land der Amalekiter, dazu die Amoriter, die zu Hazezon-Thamar wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da zogen aus der Konig von Sodom, der Konig von Gomorrha, der Konig von Adama, der Konig von Zeboim und der Konig von Bela, die Zoar heißt, und rusteten sich, zu streiten im Tal Siddim');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'mit Kedor-Laomor, dem Konige von Elam, und mit Thideal, dem Konige der Heiden, und mit Amraphel, dem Konige von Sinear, und mit Arioch, dem Konige von Elassar, vier Konige mit funfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Und das Tal Siddim hatte viel Tongruben. Aber der Konig von Sodom und Gomorrha wurden daselbst in die Flucht geschlagen und niedergelegt, und was uberblieb, floh auf das Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Da nahmen sie alle Habe zu Sodom und Gomorrha und alle Speise und zogen davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Sie nahmen auch mit sich Lot, Abrams Bruders Sohn, und seine Habe, denn er wohnete zu Sodom, und zogen davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Da kam einer, der entronnen war, und sagte es Abram an, dem Auslander, der da wohnete im Hain Mamre, des Amoriters, welcher ein Bruder war Eskols und Aners. Diese waren mit Abram im Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Als nun Abram horete, daß sein Bruder gefangen war, wappnete er seine Knechte, dreihundertundachtzehn, in seinem Hause geboren, und jagte ihnen nach bis gen Dan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'und teilte sich, fiel des Nachts uber sie mit seinen Knechten und schlug sie und jagte sie bis gen Hoba, die zur Linken der Stadt Damaskus liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'und brachte alle Habe wieder, dazu auch Lot, seinen Bruder, mit seiner Habe, auch die Weiber und das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Als er nun wiederkam von der Schlacht des Kedor-Laomor und der Konige mit ihm, ging ihm entgegen der Konig von Sodom in das Feld, das Konigstal heiliet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Aber Melchisedek, der Konig von Salem, trug Brot und Wein hervor. Und erwar ein Priester Gottes des Hochsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und segnete ihn und sprach: Gesegnet seiest du, Abram, dem hochsten Gott, der Himmel und Erde besitzt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'und gelobet sei Gott der Hochste, der deine Feinde in deine Hand beschlossen hat. Und demselben gab Abram den Zehnten von allerlei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Da sprach der Konig von Sodom zu Abram: Gib mir die Leute, die Guter behalte dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Aber Abram sprach zu dem Konige von Sodom: Ich hebe meine Hande auf zu dem HERRN, dem hochsten Gott, der Himmel und Erde besitzt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'da(S ich von allem, das dein ist, nichteinen Faden noch einen Schuhriemen nehmen will, daß du nicht sagest, du habest Abram reich gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Ausgenommen, was die Junglinge verzehret haben, und die Manner Aner, Eskol und Mamre, die mit mir gezogen sind, die laß ihr Teil nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Geschichten begab sich\'s, daß zu Abram geschah das Wort des HERRN im Gesicht und sprach: Furchte dich nicht, Abram; ich bin dein Schild und dein sehr großer Lohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abram aber sprach: Herr HERR, was willst du mir geben? Ich gehe dahin ohne Kinder; und mein Hausvogt hat einen Sohn, dieser Elieser von Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach weiter: Mir hast du keinen Samen gegeben; und siehe, der Sohn meines Gesindes soil mein Erbe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Und siehe, der HERR sprach zu ihm: Er soil nicht dein Erbe sein, sondern der von deinem Leibe kommen wird, der soli dein Erbe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und er hiefi ihn hinausgehen und sprach: Siehe gen Himmel und zahle die Sterne, kannst du sie zahlen? Und sprach zu ihm: Also soil dein Same werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abram glaubte dem HERRN, und das rechnete er ihm zur Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und er sprach zu ihm: Ich bin der HERR, der dich von Ur aus Chaldaa geführet hat, daß ich dir dies Land zu besitzen gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Abram aber sprach: Herr HERR, wobei soil ich\'s merken, daß ich\'s besitzen werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Und er sprach zu ihm: Bringe mir eine dreijahrige Kuh und eine dreijahrige Ziege und einen dreijahrigen Widder und eine Turteltaube und eine junge Taube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Und er brachte ihm solches alles und zerteilte es mitten voneinander und legte ein Teil gegen das andere uber; aber die Vogel zerteilte er nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Und das Gevogel fiel auf die Aase; aber Abram scheuchte sie davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Da nun die Sonne untergegangen war, fiel ein tieferßchlaf auf Abram; und siehe, Schrecken und große Finsternis uberfiel ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Da sprach erzu Abram: Das sollstdu wissen, daß dein Same wird fremd sein in einem Lande, das nicht sein ist; und da wird man sie zu dienen zwingen und plagen vierhundert Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber ich will richten das Volk, dem sie dienen mussen. Danach sollen sie ausziehen mit qroßem Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Und du sollst fahren zu deinen Vatern mit Frieden und in gutem Alter begraben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Sie aber sollen nach vier Mannsleben wieder hieher kommen, denn die Missetat der Amoriter ist noch nicht alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Als nun die Sonne untergegangen und finster worden war, siehe, da rauchte ein Ofen, und eine Feuerflamme fuhr zwischen den Stricken hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An dem Tage machte der HERR einen Bund mit Abram und sprach: Deinem Samen will ich dies Land geben, von dem Wasser Agyptens an bis an das große Wasser Phrath:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'die Keniter, die Kinisiter, die Kadmoniter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'die Hethiter, die Pheresiter, die Riesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'die Amoriter, die Kanaaniter, die Gergesiter, die Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai, Abrams Weib, gebar ihm nichts. Sie hatte aber eine agyptische Magd, die hiefi Hagar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Und sie sprach zu Abram: Siehe, der HERR hat mich verschlossen, daß ich nicht gebaren kann. Lieber, lege dich zu meiner Magd, ob ich doch vielleicht aus ihr mich bauen moge. Abram, der gehorchte der Stimme Sarais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Da nahm Sarai, Abrams Weib, ihre agyptische Magd, Hagar, und gab sie Abram, ihrem Mann, zum Weibe, nachdem sie zehn Jahre im Lande Kanaan gewohnet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er legte sich zu Hagar, die ward schwanger. Als sie nun sah, daß sie schwanger war, achtete sie ihre Frau geringe gegen sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sprach Sarai zu Abram: Du tust unrecht an mir. Ich habe meine Magd dir beigelegt; nun sie aber siehet, daß sie schwanger worden ist, muß ich geringe geachtet sein gegen ihr. Der HERR sei Richter zwischen mir und dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram aber sprach zu Sarai: Siehe deine Magd ist unter deiner Gewalt; tue mit ihr, wie dir\'s gefallt. Da sie nun Sarai wollte demutigen, floh sie von ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Aber der Engel des HERRN fand sie bei einem Wasserbrunnen in der Wüste, namlich bei dem Brunnen am Wege zu Sur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Der sprach zu ihr: Hagar, Sarais Magd, wo kommst du her und wo willst du hin? Sie sprach: Ich bin von meiner Frau Sarai geflohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Und der Engel des HERRN sprach zu ihr: Kehre um wieder zu deiner Frau und demutige dich unter ihre Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und der Engel des HERRN sprach zu ihr: Ich will deinen Samen also mehren, da(2> er vor grower Menge nicht soil gezahlet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Weiter sprach der Engel des HERRN zu ihr: Siehe, du bist schwanger worden und wirst einen Sohn gebaren, des Namen sollstdu Ismael heilien, darum daß der HERR dein Elend erhoret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Er wird ein wilder Mensch sein, seine Hand wider jedermann und jedermanns Hand wider ihn; und wird gegen alien seinen Brudern wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Und sie hieli den Namen des HERRN, der mit ihr redete: Du, Gott, siehest mich. Denn sie sprach: Gewißlich hie habe ich gesehen den, der mich hernach angesehen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Darum hieli sie den Brunnen einen Brunnen des Lebendigen, der mich angesehen hat; welcher Brunnen istzwischen Kades und Bared.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar Abram einen Sohn; und Abram hiefi den Sohn, den ihm Hagar gebar, Ismael.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Und Abram war sechsundachtzig Jahre alt, da ihm Hagar den Ismael gebar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Als nun Abram neunundneunzig Jahre alt war, erschien ihm der HERR und sprach zu ihm: Ich bin der allmachtige Gott; wandle vor mir und sei fromm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Und ich will meinen Bund zwischen mir und dir machen und will dich fast sehr mehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da fiel Abram auf sein Angesicht. Und Gott redete weiter mit ihm und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Siehe, ich bin\'s und habe meinen Bund mit dir, und du sollst ein Vater vieler Volker werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Darum sollstdu nicht mehr Abram heilien, sondern Abraham soil dein Name sein; denn ich habe dich gemacht vieler Volker Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Und will dich fast sehr fruchtbar machen und will von dir Volker machen; und sollen auch Konige von dir kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und ich will aufrichten meinen Bund zwischen mir und dir und deinem Samen nach dir bei ihren Nachkommen, daß es ein ewiger Bund sei, also dafi ich dein Gott sei und deines Samens nach dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und will dir und deinem Samen nach dirgeben das Land, da du ein Fremdling innen bist, namlich das ganze Land Kanaan, zu ewiger Besitzung; und will ihr Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham: So halte nun meinen Bund, du und dein Same nach dir bei ihren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das ist aber mein Bund, den ihr halten sollt zwischen mir und euch und deinem Samen nach dir: Alles, was mannlich ist unter euch, soil beschnitten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ihr sollt aber die Vorhaut an eurem Fleisch beschneiden. Dasselbe soil ein Zeichen sein des Bundes zwischen mir und euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Ein jegliches Knablein, wenn es acht Tage alt ist, sollt ihr beschneiden bei euren Nachkommen; desselbengleichen auch alles was Gesindes daheim geboren Oder erkauft ist von allerlei Fremden, die nicht eures Samens sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Also soil mein Bund an eurem Fleisch sein zum ewigen Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Und wo ein Knablein nicht wird beschnitten an der Vorhaut seines Fleisches, des Seele soil ausgerottet werden aus seinem Volk, darum daß es meinen Bund unterlassen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach abermal zu Abraham: Du sollst dein Weib Sarai nicht mehr Sarai heilien, sondern Sara soil ihr Name sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Denn ich will sie segnen, und von ihr will ich dir einen Sohn geben; denn ich will sie segnen, und Volker sollen aus ihr werden und Konige uberviel Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da fiel Abraham auf sein Angesicht und lachte und sprach in seinem Herzen: Soil mir hundert Jahre alt, ein Kind geboren werden und Sara neunzig Jahre alt gebaren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Ach, daß Ismael leben sollte vor dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sprach Gott: Ja, Sara, dein Weib soli dir einen Sohn gebaren, den sollstdu Isaak heilien; denn mit ihm will ich meinen ewigen Bund aufrichten und mit seinem Samen nach ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Dazu um Ismael habe ich dich auch erhoret. Siehe, ich habe ihn gesegnet und will ihn fruchtbar machen und mehren fast sehr. Zwolf Fursten wird er zeugen, und will ihn zum grolien Volk machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Aber meinen Bund will ich aufrichten mit Isaak, den dir Sara gebaren soli um diese Zeit im andern Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und er horete auf mit ihm zu reden, Und Gott fuhr auf von Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Da nahm Abraham seinen Sohn Ismael und alle Knechte, die daheim geboren, und alle, die erkauft, und alles, was Mannsnamen war in seinem Hause, und beschnitt die Vorhaut an ihrem Fleisch eben desselben Tages, wie ihm Gott gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Und Abraham war neunundneunzig Jahre alt, da er die Vorhaut an seinem Fleische beschnitt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ismael aber, sein Sohn, war dreizehn Jahre alt, da seines Fleisches Vorhaut beschnitten ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Eben auf einen Tag wurden sie alle beschnitten, Abraham, sein Sohn Ismael,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'und was Mannsnamen in seinem Hause war, daheim geboren und erkauftvon Fremden; esward alles mit ihm beschnitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Und der HERR erschien ihm im Hain Mamre, da er saß an der Tur seiner Hutte, da der Tag am heißesten war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Und als er seine Augen aufhub und sah, siehe, da stunden drei Manner gegen ihm. Und da er sie sah, lief er ihnen entgegen von der Tur seiner Hutte und buckte sich nieder auf die Erde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'und sprach: HERR, habe ich Gnade funden vor deinen Augen, so gehe nicht vor deinem Knechte uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Man soil euch ein wenig Wassers bringen und eure Füfte waschen; und lehnet euch unter den Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Und ich will euch einen Bissen Brots bringen, dalj ihr euer Herz labet; danach sollt ihr fortgehen. Denn darum seid ihr zu eurem Knechte kommen. Sie sprachen: Tue, wie du gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Abraham eilete in die Hutte zu Sara und sprach: Eile und menge drei Mali Semmelmehl, knete und backe Kuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Er aber lief zu den Rindern und holete ein zart gut Kalb und gab\'s dem Knaben; der eilete und bereitete es zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Und er trug auf Butter und Milch und von dem Kalbe, das er zubereitet hatte, und setzte es ihnen vor und trat vor sie unter dem Baum, und sie alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sprachen sie zu ihm: Wo ist dein Weib Sara? Er antwortete: Drinnen in der Hutte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sprach er: Ich will wieder zu dir kommen, so ich lebe, siehe, so soli Sara, dein Weib, einen Sohn haben. Das horete Sara hinter ihm, hinter der Tur der Hutte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Und siewaren beide, Abraham und Sara, alt und wohl betagt, also daß es Sara nicht mehr ging nach der Weiber Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Darum lachte sie bei sich selbst und sprach: Nun ich alt bin, soil ich noch Wollust pflegen, und mein Herrauch alt ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sprach der HERR zu Abraham: Warum lachet des Sara und spricht: Meinest du, daß wahr sei, daß ich noch gebaren werde, so ich doch alt bin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Sollte dem HERRN etwas unmoglich sein? Urn diese Zeit will ich wieder zu dir kommen, so ich lebe, so soil Sara einen Sohn haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Da leugnete Sara und sprach: Ich habe nicht gelacht; denn sie furchtete sich. Aber er sprach: Es ist nicht also, du hast gelacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Da stunden die Manner auf von dannen und wandten sich gegen Sodom; und Abraham ging mit ihnen, dafi ersie geleitete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Da sprach der HERR: Wie kann ich Abraham verbergen, was ich tue,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'sintemal er ein groli und machtiges Volk soil werden, und alle Volker auf Erden in ihm gesegnet werden sollen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn ich weili, erwird befehlen seinen Kindern und seinem Hause nach ihm, daß sie des HERRN Wege halten und tun, was recht und gut ist; auf daß der HERR auf Abraham kommen lasse, was er ihm verheilien hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und der HERR sprach: Es ist ein Geschrei zu Sodom und Gomorrha, das ist groli, und ihre Sünden sind fast schwer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Darum will ich hinabfahren und sehen, ob sie alles getan haben nach dem Geschrei, das vor mich kommen ist; Oder ob\'s nicht also sei, daß ich\'s wisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Und die Manner wandten ihr Angesicht und gingen gen Sodom; aber Abraham blieb stehen vor dem HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'und trat zu ihm und sprach: Willst du denn den Gerechten mit dem Gottlosen umbringen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Es mochten vielleicht fünfzig Gerechte in der Stadt sein; wolltest du die umbringen und dem Ort nicht vergeben urn fünfzig Gerechter willen, die drinnen waren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Das sei feme von dir, daß du das tust und totest den Gerechten mit dem Gottlosen, daß der Gerechte sei gleich wie der Gottlose; das sei feme von dir, der du aller Welt Richter bist! Du wirst so nicht richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Der HERR sprach: Finde ich fünfzig Gerechte zu Sodom in der Stadt, so will ich urn ihretwillen all den Orten vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham antwortete und sprach: Ach siehe, ich habe mich unterwunden zu reden mit dem HERRN, wiewohl ich Erde und Asche bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Es mochten vielleicht fünf weniger denn fünfzig Gerechte drinnen sein; wolltest du denn die ganze Stadt verderben urn der fünfe willen? Er sprach: Finde ich drinnen fünfundvierzig, will ich sie nicht verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Und er fuhr weiter mit ihm zu reden, und sprach: Man mochte vielleicht vierzig drinnen finden. Er aber sprach: Ich will ihnen nichts tun urn der vierzig willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Abraham sprach: Zürne nicht, HERR, dafi ich noch mehr rede. Man mochte vielleicht dreilüg drinnen finden. Er aber sprach: Finde ich dreifüg drinnen, so will ich ihnen nichts tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Und er sprach: Ach siehe, ich habe mich unterwunden, mit dem HERRN zu reden. Man mochte vielleicht zwanzig drinnen finden. Er antwortete: Ich will sie nicht verderben urn der zwanzig willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Und er sprach: Ach zürne nicht, HERR, daß ich nur noch einmal rede. Man mochte vielleicht zehn drinnen finden. Er aber sprach: Ich will sie nicht verderben urn der zehn willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Und der HERR ging hin, da er mit Abraham ausgeredet hatte; und Abraham kehrte wieder hin an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Die zween Engel kamen gen Sodom des Abends. Lot aber sa(i zu Sodom unter dem Tor. Und da er sie sah, stund er auf ihnen entgegen und bückte sich mit seinem Angesicht auf die Erde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'und sprach: Siehe, HERR, kehret doch ein zum Hause eures Knechts und bleibet uber Nacht; lasset eure Fufie waschen, so stehet ihr morgens frühe auf und ziehet eure Straße. Aber sie sprachen: Nein, sondern wir wollen uber Nacht auf der Gasse bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Da notigte er sie fast; und sie kehrten zu ihm ein und kamen in sein Haus. Und er machte ihnen ein Mahl und buk ungesauerte Kuchen; und sie alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Aber ehe sie sich legten, kamen die Leute der Stadt Sodom und umgaben das Haus, jung und alt, das ganze Volk aus alien Enden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'und forderten Lot und sprachen zu ihm: Wo sind die Manner, die zu dir kommen sind diese Nacht? Fuhre sie heraus zu uns, daß wir sie erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot ging heraus zu ihnen vor die Tur und schloß die Tur hinter ihm zu');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'und sprach: Ach, lieben Bruder, tut nichtso libel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Siehe, ich habe zwo Tochter, die haben noch keinen Mann erkannt; die will ich herausgeben unter euch, und tut mit ihnen, was euch gefallt; alleine diesen Mannern tut nichts, denn darum sind sie unter die Schatten meines Dachs eingegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Sie aber sprachen: Komm hieher! Da sprachen sie: Du bist der einige Fremdling hie und willst regieren? Wohlan, wir wollen dich baß plagen denn jene! Und sie drangen hart auf den Mann Lot. Und da sie hinzuliefen und wollten die Tur aufbrechen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'griffen die Manner hinaus und zogen Lot hinein zu ihnen ins Haus und schlossen die Tur zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Und die Manner vor der Tur am Hause wurden mit Blindheit geschlagen, beide klein und grofi, bis sie müde wurden und die Tur nicht finden konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Und die Manner sprachen zu Lot: Hastdu noch irgend hie einen Eidam und Sohne und Tochter, und wer dir angehoret in der Stadt, den fuhre aus dieser Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wirwerden diese Statte verderben, darum daß ihr Geschrei groß ist vor dem HERRN; der hat uns gesandt, sie zu verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da ging Lot hinaus und redete mit seinen Eidamen, die seine Tochter nehmen sollten: Machet euch auf und gehet aus diesem Ort; denn der HERR wird diese Stadt verderben. Aber es war ihnen lacherlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Da nun die Morgenrote aufging, hießen die Engel den Lot eilen und sprachen: Mache dich auf, nimm dein Weib und deine zwo Tochter, die vorhanden sind, daß du nicht auch umkommest in der Missetat dieser Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Da er aber verzog, ergriffen die Manner ihn und sein Weib und seine zwo Tochter bei der Hand, darum daß der HERR sein verschonete, und fuhrten ihn hinaus und ließen ihn außen vor der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und als sie ihn hatten hinausgebracht, sprach er: Errette deine Seele und sieh nicht hinter dich; auch stehe nicht in dieser ganzen Gegend. Auf dem Berge errette dich, daß du nicht umkommest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Aber Lot sprach zu ihnen: Ach nein, HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Siehe, dieweil dein Knecht Gnade funden hat vor deinen Augen, so wollest du deine Barmherzigkeit groß machen, die du an mirgetan hast, daß du meine Seele bei dem Leben erhieltest. Ich kann mich nicht auf dem Berge erretten; es mochte mich ein Unfall ankommen, daß ich sturbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe, da isteine Stadt nahe, darein ich fliehen mag, und ist klein, daselbst will ich mich erretten; ist sie doch klein, daß meine Seele lebendig bleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da sprach erzu ihm: Siehe, ich habe auch in diesem Stuck dich angesehen, daß ich die Stadt nicht umkehre, davon du geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Eile und errette dich daselbst, denn ich kann nichts tun, bis daß du hinein kommest. Daher ist diese Stadt genannt Zoar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Und die Sonne war aufgegangen auf Erden, da Lot gen Zoar einkam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Da ließ der HERR Schwefel und Feuer regnen von dem HERRN vom Himmel herab auf Sodom und Gomorrha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Und kehrete die Stadte urn, die ganze Gegend und alle Einwohner der Stadte, und was auf dem Lande gewachsen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Und sein Weib sah hinter sich und ward zur Salzsaule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraham aber machte sich des Morgens frühe auf an den Ort, da er gestanden war vor dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'und wandte sein Angesicht gegen Sodom und Gomorrha und alles Land der Gegend und schauete; und siehe, da ging ein Rauch auf vom Lande, wie ein Rauch vom Ofen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Denn da Gott die Stadte in der Gegend verderbte, gedachte er an Abraham und geleitete Lot aus den Stadten, die er umkehrete, darin Lot wohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Und Lotzog aus Zoar und blieb auf dem Berge mit seinen beiden Tochtern; denn er furchtete sich, zu Zoar zu bleiben; und blieb also in einer Hohle mit seinen beiden Tochtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sprach die alteste zu der jungsten: Unser Vater ist alt, und ist kein Mann mehr auf Erden, der uns beschlafen moge nach aller Welt Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'So komm, laß uns unserm Vater Wein zu trinken geben und bei ihm schlafen, daß wir Samen von unserm Vater erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Also gaben sie ihrem Vater Wein zu trinken in derselben Nacht. Und die erste ging hinein und legte sich zu ihrem Vater; und er ward\'s nicht gewahr, da sie sich legte, noch da sie aufstund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Des Morgens sprach die alteste zu der jungsten: Siehe, ich habe gestern bei meinem Vater gelegen. Laß uns ihm diese Nacht auch Wein zu trinken geben, daß du hineingehest und legest dich zu ihm, daß wir Samen von unserm Vater erhalten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Also gaben sie ihrem Vater die Nacht auch Wein zu trinken. Und die jungste machte sich auch auf und legte sich zu ihm; und er ward\'s nicht gewahr, da sie sich legte, noch da sie aufstund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Also wurden die beiden Tochter Lots schwanger von ihrem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die alteste gebar einen Sohn, den hieli sie Moab. Von dem kommen her die Moabiter bis auf diesen heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Und die jungste gebar auch einen Sohn, den hieli sie das Kind Ammi. Von dem kommen die Kinder Ammon bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraham aber zog von dannen ins Land gegen Mittag und wohnete zwischen Kades und Sur und ward ein Fremdling zu Gerar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Und sprach von seinem Weibe Sara: Es ist meine Schwester. Da sandte Abimelech, der Konig zu Gerar, nach ihr und lieli sie holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Aber Gott kam zu Abimelech des Nachts im Traum und sprach zu ihm: Siehe da, du bist des Todes um des Weibes willen, das du genommen hast; denn sie ist eines Mannes Eheweib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber hatte sie nicht beruhret und sprach: HERR, willst du denn auch ein gerecht Volk erwurgen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Hat er nicht zu mir gesagt: Sie ist meine Schwester? Und sie hat auch gesagt: Er ist mein Bruder. Habe ich doch das getan mit einfaltigem Herzen und unschuldigen Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Und Gott sprach zu ihm im Traum: Ich weili auch, daß du mit einfaltigem Herzen das getan hast. Darum habe ich dich auch behutet, daü du nicht wider mich sündigtest, und habe dir\'s nicht zugegeben, daß du sie beruhrtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'So gib nun dem Mann sein Weib wieder, denn er ist ein Prophet, und lali ihn fur dich bitten, so wirst du lebendig bleiben. Wo du aber sie nicht wiedergibst, so wisse, da(5 du des Todes sterben mußt, und alles, was dein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Da stund Abimelech des Morgens frühe auf und rief alien seinen Knechten und sagte ihnen dieses alles vor ihren Ohren. Und die Leute furchteten sich sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Und Abimelech rief Abraham auch und sprach zu ihm: Warum hast du uns das getan, und was habe ich an dir gesundiget, dafi du so eine grolie Sünde wolltest auf mich und mein Reich bringen? Du hast mit mir gehandelt, nicht wie man handeln soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und Abimelech sprach weiterzu Abraham: Was hast du gesehen, daß du solches getan hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham sprach: Ich dachte, vielleicht ist keine Gottesfurcht an diesen Orten, und werden mich um meines Weibes willen erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Auch ist sie wahrhaftig meine Schwester, denn sie ist meines Vaters Tochter, aber nicht meiner Mutter Tochter, und ist mein Weib worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Da mich aber Gott aulier meines Vaters Hause wandern hieli, sprach ich zu ihr: Die Barmherzigkeit tu an mir, daß wo wir hinkommen, du von mir sagest, ich sei dein Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Da nahm Abimelech Schafe und Rinder, Knechte und Magde und gab sie Abraham; und gab ihm wieder sein Weib Sara');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'und sprach: Siehe da, mein Land stehet dir often; wohne, wo dir\'s wohlgefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Und sprach zu Sara: Siehe da, ich habe deinem Bruder tausend Silberlinge gegeben; siehe, das soli dir eine Decke der Augen sein vor alien, die bei dir sind, und allenthalben. Und das war ihre Strafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Abraham aber betete zu Gott; da heilete Gott Abimelech und sein Weib und seine Magde, daß sie Kinder gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Denn der HERR hatte zuvor hart verschlossen alle Mutter des Hauses Abimelech um Saras, Abrahams Weibes, willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Und der HERR suchte heim Sara wie er geredet hatte, und tat mit ihr, wie er geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sara ward schwanger und gebar Abraham einen Sohn in seinem Alter um die Zeit, die ihm Gott geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham hieli seinen Sohn, der ihm geboren war, Isaak, den ihm Sara gebar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'und beschnitt ihn am achten Tage, wie ihm Gott geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Hundert Jahre war Abraham alt, da ihm sein Sohn Isaak geboren ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Und Sara sprach: Gott hat mir ein lachen zugerichtet; denn wer es horen wird, der wird mein lachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sprach: Wer dürfte von Abraham sagen, daß Sara Kinder sauget und hatte ihm einen Sohn geboren in seinem Alter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind wuchs und ward entwohnet. Und Abraham machte ein groli Mahl am Tage, da Isaak entwohnet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Und Sara sah den Sohn Hagars, der Agyptischen, den sie Abraham geboren hatte, daß er ein Spotter war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'und sprach zu Abraham: Treibe diese Magd aus mit ihrem Sohn; denn dieser Magd Sohn soil nicht erben mit meinem Sohn Isaak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Das Wort gefiel Abraham sehr libel um seines Sohnes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Aber Gott sprach zu ihm: Lali dir\'s nicht ubel gefallen des Knaben und der Magd halben. Alles, was Sara dir gesagt hat, dem gehorche. Denn in Isaak soil dir der Same genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Auch will ich der Magd Sohn zum Volk machen, darum daß er deines Samens ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Da stund Abraham des Morgens fruhe auf und nahm Brot und eine Flasche mit Wasser und legte es Hagar auf ihre Schulter, und den Knaben mit, und liefi sie aus. Da zog sie hin und ging in der Wuste irre bei Bersaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Da nun das Wasser in der Flasche aus war, warf sie den Knaben unter einen Baum');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'und ging hin und setzte sich gegenübervon feme, eines Bogenschusses weit; denn sie sprach: Ich kann nichtzusehen des Knaben Sterben. Und sie setzte sich gegenüber und hub ihre Stimme auf und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Da erhorete Gott die Stimme des Knaben. Und der Engel Gottes rief vom Himmel der Hagar und sprach zu ihr: Was ist dir, Hagar? Furchte dich nicht; denn Gott hat erhoret die Stimme des Knaben, da er liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Stehe auf, nimm den Knaben und fuhre ihn an deiner Hand; denn ich will ihn zum grolien Volk machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott tat ihr die Augen auf, daß sie einen Wasserbrunnen sah. Da ging sie hin und fullete die Flasche mit Wasser und trankte den Knaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Knaben; der wuchs und wohnete in der Wuste und ward ein guter Schutze;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'und wohnete in der Wuste Pharan. Und seine Mutter nahm ihm ein Weib aus Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Zu derselbigen Zeit redete Abimelech und Phichol, sein Feldhauptmann, mit Abraham und sprach: Gott ist mit dir in allem, das du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'So schwore mir nun bei Gott, daß du mir, noch meinen Kindern, noch meinen Neffen keine Untreue erzeigen wollest, sondern die Barmherzigkeit, die ich an dir getan habe, an mir auch tust und an dem Lande, da du ein Fremdling innen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sprach Abraham: Ich will schworen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Und Abraham strafte Abimelech urn des Wasserbrunnens willen, den Abimelechs Knechte hatten mit Gewalt genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Da antwortete Abimelech: Ich hab\'s nicht gewuftt, wer das getan hat; auch hast du mir\'s nicht angesagt; dazu habe ich\'s nicht gehoret denn heute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da nahm Abraham Schafe und Rinder und gab sie Abimelech; und machten beide einen Bund miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Und Abraham stellete dar sieben Lammer besonders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Da sprach Abimelech zu Abraham: Was sollen die sieben Lammer, die du besonders dargestellt hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Er antwortete: Sieben Lammer sollst du von meiner Hand nehmen, daß sie mir zum Zeugnis seien, daß ich diesen Brunnen gegraben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher heiftt die Statte Bersaba, daß sie beide miteinander da geschworen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Und also machten sie den Bund zu Bersaba. Da machten sich auf Abimelech und Phichol, sein Feldhauptmann, und zogen wieder in der Philister Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham aber pflanzete Baume zu Bersaba und predigte daselbst von dem Namen des HERRN, des ewigen Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und war ein Fremdling in der Philister Lande eine lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nach diesen Geschichten versuchte Gott Abraham und sprach zu ihm: Abraham! Und er antwortete: Hier bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Und er sprach: Nimm Isaak, deinen einigen Sohn, den du lieb hast, und gehe hin in das Land Morija und opfere ihn daselbst zum Brandopfer auf einem Berge, den ich dir sagen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Da stund Abraham des Morgens fruhe auf und gurtete seinen Esel und nahm mit sich zween Knaben und seinen Sohn Isaak und spaltete Holz zum Brandopfer, machte sich auf und ging hin an den Ort, davon ihm Gott gesagt, hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage hub Abraham seine Augen auf und sah die Statte von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Und sprach zu seinen Knaben: Bleibet ihr hie mit dem Esel; ich und der Knabe wollen dorthin gehen; und wenn wir angebetet haben, wollen wir wieder zu euch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Und Abraham nahm das Holz zum Brandopfer und legte es auf seinen Sohn Isaak; er aber nahm das Feuer und Messer in seine Hand, und gingen die beiden miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da sprach Isaak zu seinem Vater Abraham: Mein Vater! Abraham antwortete: Hie bin ich, mein Sohn. Und er sprach: Siehe, hie ist Feuer und Holz; wo ist aber das Schaf zum Brandopfer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham antwortete: Mein Sohn, Gott wird ihm ersehen ein Schaf zum Brandopfer. Und gingen die beiden miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Und als sie kamen an die Statte, die ihm Gott sagte, bauete Abraham daselbst einen Altar und legte das Holz drauf und band seinen Sohn Isaak, legte ihn auf den Altar oben auf das Holz');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'und reckte seine Hand aus und fassete das Messer, daß er seinen Sohn schlachtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da rief ihm der Engel des HERRN vom Himmel und sprach: Abraham, Abraham! Er antwortete: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Er sprach: Lege deine Hand nicht an den Knaben und tu ihm nichts! Denn nun weift ich, daß du Gott furchtest und hast deines einigen Sohnes nicht verschonet urn meinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Da hub Abraham seine Augen auf und sah einen Widder hinter ihm in der Hecke mit seinen Hornern hangen; und ging hin und nahm den Widder und opferte ihn zum Brandopfer an seines Sohnes Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham hieft die Statte: Der HERR siehet. Daher man noch heutigestages saget: Auf dem Berge, da der HERR siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und der Engel des HERRN rief Abraham abermal vom Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'und sprach: Ich habe bei mirselbst geschworen, spricht der HERR, dieweil du solches getan hast und hast deines einigen Sohnes nicht verschonet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'daß ich deinen Samen segnen und mehren will wie die Sterne am Himmel und wie den Sand am Ufer des Meeres; und dein Same soil besitzen die Tore seiner Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Und durch deinen Samen sollen alle Volker auf Erden gesegnetwerden, darum daß du meiner Stimme gehorchet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Also kehrete Abraham wieder zu seinen Knaben; und machten sich auf und zogen miteinander gen Bersaba und wohnete daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nach diesen Geschichten begab sich\'s, daß Abraham angesagt ward: Siehe, Milka hat auch Kinder geboren deinem Bruder Nahor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'namlich Uz, den Erstgeborenen, und Bus, seinen Bruder, und Kemuel, von dem die Syrer kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'und Chesed und Haso und Pildas und Jedlaph und Bethuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Bethuel aber zeugete Rebekka. Diese acht gebar Milka dem Nahor, Abrahams Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Und sein Kebsweib, mit Namen Rehuma, gebar auch, namlich den Theba, Gaham, Thahas und Maacha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara war hundertsiebenundzwanzig Jahre alt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'und starb in der Hauptstadt, die heifit Hebron, im Lande Kanaan. Da kam Abraham, daß er sie klagete und beweinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Danach stund er auf von seiner Leiche und redete mit den Kindern Heths und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ich bin ein Fremder und Einwohner bei euch; gebet mirein Erbbegrabnis bei euch, daß ich meinen Toten begrabe, der vor mir liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Da antworteten Abraham die Kinder Heths und sprachen zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Hdre uns, lieber Herr! Du bist ein Furst Gottes unter uns; begrabe deinen Toten in unsern ehrlichsten Grabern; kein Mensch soli dir unter uns wehren, daß du in seinem Grabe nicht begrabest deinen Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da stund Abraham auf und bückte sich vor dem Volk des Landes, namlich vor den Kindern Heths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Und er redete mit ihnen und sprach: Gefallt es euch, daß ich meinen Toten, der vor mir liegt, begrabe, so horet mich und bittet fur mich gegen Ephron, dem Sohn Zoars,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'daß er mir gebe seine zwiefache Hohle, die er hat am Ende seines Ackers; er gebe mir sie urn Geld, soviel sie wert ist, unter euch zum Erbbegrabnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Denn Ephron wohnete unter den Kindern Heths. Da antwortete Ephron, der Hethiter, Abraham, daß zuhoreten die Kinder Heths, vor alien, die zu seiner Stadt Tor aus und ein gingen, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nein, mein Herr, sondern hore mir zu. Ich schenke dir den Acker, und die Hohle drinnen dazu, und ubergebe dir\'s vor den Augen der Kinder meines Volks, zu begraben deinen Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da bückte sich Abraham vor dem Volk des Landes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'und redete mit Ephron, daß zuhorete das Volk des Landes, und sprach: Willst du mir ihn lassen, so bitte ich, nimm von mir das Geld fur den Acker, das ich dir gebe, so will ich meinen Toten daselbst begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron antwortete Abraham und sprach zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mein Herr, hore doch mich! Das Feld ist vierhundert Sekel Silbers wert; was ist das aber zwischen mir und dir? Begrabe nur deinen Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham gehorchte Ephron und wog ihm das Geld dar, das ergesagt hatte, daß zuhoreten die Kinder Heths namlich vierhundert Sekel Silbers, das im Kauf gang und gabe war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Also ward Ephrons Acker, darin die zwiefache Hohle ist, gegen Mamre uber, Abraham zum eigenen Gut bestatiget, mit der Hohle darinnen und mit alien Baumen auf dem Acker umher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'daß die Kinder Heths zusahen und alle, die zu seiner Stadt Tor aus und ein gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Danach begrub Abraham Sara, sein Weib, in der Hohle des Ackers, die zwiefach ist, gegen Mamre uber, das ist, Hebron, im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Also ward bestatiget der Acker und die Hohle darinnen Abraham zum Erbbegrabnis von den Kindern Heths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham war alt und wohl betaget, und der HERR hatte ihn gesegnet allenthalben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Und sprach zu seinem altesten Knecht seines Hauses, der alien seinen Gütern vorstund: Lege deine Hand unter meine Hüfte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'und schwore mir bei dem HERRN, dem Gott des Himmels und der Erde, daß du meinem Sohn kein Weib nehmest von den Tochtem der Kanaaniter, unter welchen ich wohne;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'sondern daß du ziehest in mein Vaterland und zu meiner Freundschaft und nehmest meinem Sohn Isaak ein Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Der Knecht sprach: Wie, wenn das Weib mir nicht wollte folgen in dies Land? Soil ich dann deinen Sohn wiederbringen in jenes Land, daraus du gezogen bist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sprach zu ihm: Da hüte dich vor, daß du meinen Sohn nicht wieder dahin bringest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Der HERR, der Gott des Himmels, der mich von meines Vaters Hause genommen hat und von meiner Heimat, der mir geredet und mir auch geschworen hat und gesagt: Dies Land will ich deinem Samen geben, der wird seinen Engel vor dir her senden, daß du meinem Sohn daselbst ein Weib nehmest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'So aber das Weib dir nicht folgen will, so bist du dieses Eides quitt. Alleine bringe meinen Sohn nicht wieder dorthin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da legte der Knecht seine Hand unter die Hufte Abrahams, seines Herrn, und schwur ihm solches.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Also nahm der Knecht zehn Kamele von den Kamelen seines Herrn und zog hin und hatte mit sich allerlei Güter seines Herrn; und machte sich auf und zog gen Mesopotamien zu der Stadt Nahors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Da liefi er die Kamele sich lagern aulien vor der Stadt bei einem Wasserbrunnen, des Abends um die Zeit, wenn die Weiber pflegten herauszugehen und Wasser zu schopfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'und sprach: HERR, du Gott meines Herrn Abraham, begegne mir heute und tu Barmherzigkeit an meinem Herrn Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Siehe, ich stehe hie bei dem Wasserbrunnen, und der Leute Tochter in dieser Stadt werden herauskommen, Wasser zu schopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Wenn nun eine Dime kommt, zu der ich spreche: Neige deinen Krug und lal J mich trinken, und sie sprechen wird: Trinke, ich will deine Kamele auch tranken, dafi sie die sei, die du deinem Diener Isaak bescheret habest, und ich daran erkenne, daß du Barmherzigkeit an meinem Herrn getan hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Und ehe er ausgeredet hatte, siehe, da kam heraus Rebekka, Bethuels Tochter, der ein Sohn der Milka war, welche Nahors, Abrahams Bruders, Weib war, und trug einen Krug auf ihrer Achsel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Und sie war eine sehr schone Dime von Angesicht, noch eine Jungfrau, und kein Mann hatte sie erkannt. Die stieg hinab zum Brunnen und fullete den Krug und stieg herauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da lief ihr der Knecht entgegen und sprach: Lafi mich ein wenig Wassers aus deinem Kruge trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Und sie sprach: Trinke, mein Herr! Und eilend lieli sie den Krug hernieder auf ihre Hand und gab ihm zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und da sie ihm zu trinken gegeben hatte, sprach sie: Ich will deinen Kamelen auch schopfen, bis sie alle getrunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und eilete und gofi den Krug aus in die Tranke und lief aber zum Brunnen zu schopfen und schopfete alien seinen Kamelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Der Mann aber wunderte sich ihrer und schwieg stille, bis er erkennete, ob der HERR zu seiner Reise Gnade gegeben hatte, Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Da nun die Kamele alle getrunken hatten, nahm ereine güldene Spange, eines halben Sekels schwer, und zween Armringe an ihre Hande, zehn Sekel Goldes schwer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'und sprach: Meine Tochter, wem gehorest du an? Das sage mir doch. Haben wir auch Raum in deines Vaters Hause zu herbergen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Sie sprach zu ihm: Ich bin Bethuels Tochter, des Sohnes Milkas, den sie dem Nahor geboren hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Und sagte weiter zu ihm: Es ist auch viel Stroh und Futter bei uns und Raums genug zu herbergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da neigete sich der Mann und betete den HERRN an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'und sprach: Gelobet sei der HERR, der Gott meines Herrn Abraham, der seine Barmherzigkeit und seine Wahrheit nicht verlassen hat an meinem Herrn; denn der HERR hat mich den Weg gefuhret zu meines Herrn Bruders Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Und die Dime lief und sagte solches alles an in ihrer Mutter Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Und Rebekka hatte einen Bruder, der hieli Laban; und Laban liefzu dem Manne drautien bei dem Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Und als er sah die Spangen und Armringe an seiner Schwester Handen und horete die Worte Rebekkas, seiner Schwester, daß sie sprach: Also hat mir der Mann gesagt, kam er zu dem Manne, und siehe, erstund bei den Kamelen am Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Und er sprach: Komm herein, du Gesegneter des HERRN! Warum stehest du draulien? Ich habe das Haus geraumet und fur die Kamele auch Raum gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Also führete er den Mann ins Haus und zaumete die Kamele ab und gab ihnen Stroh und Futter und Wasser, zu waschen seine Fülie und der Manner, die mit ihm waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'und setzte ihm Essen vor. Er sprach aber: Ich will nicht essen, bis daß ich zuvor meine Sache geworben habe. Sie antworteten: Sage her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Er sprach: Ich bin Abrahams Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Und der HERR hat meinen Herrn reichlich gesegnet, und ist groli worden; und hat ihm Schafe und Ochsen, Silber und Gold, Knechte und Magde, Kamele und Esel gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Dazu hat Sara, meines Herrn Weib, einen Sohn geboren meinem Herrn in seinem Alter; dem hat er alles gegeben, was er hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Und mein Herr hat einen Eid von mir genommen und gesagt: Du sollst meinem Sohn kein Weib nehmen von den Tochtern der Kanaaniter, in deren Lande ich wohne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'sondern zeuch hin zu meines Vaters Hause und zu meinem Geschlecht; daselbst nimm meinem Sohn ein Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ich sprach aber zu meinem Herrn: Wie, wenn mir das Weib nicht folgen will?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Da sprach erzu mir: Der HERR, vor dem ich wandle, wird seinen Engel mit dir senden und Gnade zu deiner Reise geben, daß du meinem Sohn ein Weib nehmest von meiner Freundschaft und meines Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Alsdann sollst du meines Eides quitt sein, wenn du zu meiner Freundschaft kommst; geben sie dir nicht, so bist du meines Eides quitt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Also kam ich heute zum Brunnen und sprach: HERR, Gott meines Herrn Abraham, hast du Gnade zu meiner Reise gegeben, daher ich gereiset bin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'siehe, so stehe ich hie bei dem Wasserbrunnen. Wenn nun eine Jungfrau herauskommt zu schopfen, und ich zu ihr spreche: Gib mir ein wenig Wasser zu trinken aus deinem Krug,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'und sie wird sagen: Trinke du, ich will deinen Kamelen auch schopfen, daß die sei das Weib, das der HERR meines Herrn Sohne bescheret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ehe ich nun solche Worte ausgeredet hatte in meinem Herzen, siehe, da kommt Rebekka heraus mit einem Krug auf ihrer Achsel und gehet hinab zum Brunnen und schopfet. Da sprach ich zu ihr: Gib mir zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Und sie nahm eilend den Krug von ihrer Achsel und sprach: Trinke, und deine Kamele will ich auch tranken. Also trank ich, und sie trankte die Kamele auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Und ich fragte sie und sprach: Wes Tochter bist du? Sie antwortete: Ich bin Bethuels Tochter, des Sohnes Nahors, den ihm Milka geboren hat. Da hangete ich eine Spange an ihre Stirn und Armringe an ihre Hande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'und neigete mich und betete den HERRN an und lobte den HERRN, den Gott meines Herrn Abraham, der mich den rechten Weg gefuhret hat, daß ich seinem Sohn meines Herrn Bruders Tochter nehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Seid ihr nun die, so an meinem Herrn Freundschaft und Treue beweisen wollt, so saget mir\'s; wo nicht, so saget mir\'s aber, daß ich mich wende zur Rechten Oder zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da antwortete Laban und Bethuel und sprachen: Das kommt vom HERRN; darum konnen wir nichts wider dich reden, weder Boses noch Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Da ist Rebekka vor dir; nimm sie und zeuch hin, daß sie deines Herrn Sohnes Weib sei, wie der HERR geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Da diese Worte horete Abrahams Knecht, bückte er sich dem HERRN zu der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Und zog hervor silberne und guldene Kleinode und Kleider und gab sie Rebekka; aber ihrem Bruder und der Mutter gab er Würze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Da a(i und trank er samt den Mannern, die mit ihm waren, und blieb uber Nacht allda. Des Morgens aber stund er auf und sprach: Lasset mich ziehen zu meinem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Aber ihr Bruder und Mutter sprachen: Lali doch die Dime einen Tag Oder zehn bei uns bleiben, danach sollstdu ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Da sprach er zu ihnen: Haltet mich nicht auf, denn der HERR hat Gnade zu meiner Reise gegeben. Lasset mich, daß ich zu meinem Herrn ziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Da sprachen sie: Lasset uns die Dime rufen und fragen, was sie dazu sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Und riefen der Rebekka und sprachen zu ihr: Willst du mit diesem Manne ziehen? Sie antwortete: Ja, ich will mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Also liefien sie Rebekka, ihre Schwester, ziehen mit ihrer Amme, samt Abrahams Knecht und seinen Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekka und sprachen zu ihr: Du bist unsere Schwester; wachse in viel tausendmal tausend, und dein Same besitze die Tore seiner Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Also machte sich Rebekka auf mit ihren Dirnen, und setzten sich auf die Kamele und zogen dem Manne nach. Und der Knecht nahm Rebekka an und zog hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isaak aber kam vom Brunnen des Lebendigen und Sehenden (denn erwohnete im Lande aeqen Mittag)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'und war ausgegangen, zu beten auf dem Felde, urn den Abend, und hub seine Augen auf und sah, daß Kamele daherkamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Und Rebekka hub ihre Augen auf und sah Isaak; da fiel sie vom Kamel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'und sprach zu dem Knecht: Wer ist der Mann, der uns entgegenkommt auf dem Felde? Der Knecht sprach: Das ist mein Herr. Da nahm sie den Mantel und verhullete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Und der Knecht erzahlete Isaak alle Sache, die er ausgerichtet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Da fuhrete sie Isaak in die Hütte seiner Mutter Sara und nahm die Rebekka, und sie ward sein Weib, und gewann sie lieb. Also ward Isaak getrostet über seiner Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham nahm wieder ein Weib, die hiefi Ketura.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Die gebar ihm Simran und Jaksan, Medan und Midian, Jesbak und Suah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jaksan aber zeugete Seba und Dedan. Die Kinder aber von Dedan waren: Assurim, Letusim und Leumim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Die Kinder Midians waren: Epha, Epher, Hanoch, Abida und Eldaa. Diese sind alle Kinder der Ketura.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Und Abraham gab all sein Gut Isaak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Aber den Kindern, die er von den Kebsweibern hatte, gab er Geschenke und lieli sie von seinem Sohn Isaak ziehen, weil er noch lebte, gegen den Aufgang in das Morgenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Das ist aber Abrahams Alter, das er gelebet hat, hundertundfünfundsiebenzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und nahm ab und starb in einem ruhigen Alter, da er alt und lebenssatt war, und ward zu seinem Volk gesammelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und es begruben ihn seine Sohne Isaak und Ismael in der zwiefachen Hohle auf dem Acker Ephrons, des Sohnes Zoars, des Hethiters, die da liegt gegen Mamre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'in dem Felde, das Abraham von den Kindern Heths gekauft hatte. Da ist Abraham begraben mit Sara, seinem Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Und nach dem Tode Abrahams segnete Gott Isaak, seinen Sohn. Und erwohnete bei dem Brunnen des Lebendigen und Sehenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dies ist das Geschlecht Ismaels, Abrahams Sohns, den ihm Hagar gebar, die Magd Saras aus Agypten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'und das sind die Namen der Kinder. Ismaels, davon ihre Geschlechter genannt sind: Der erstgeborene Sohn Ismaels Nebajoth; Kedar, Adbeel, Mibsam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Masa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Thema, Jetur, Naphis und Kedma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dies sind die Kinder Ismaels mit ihren Namen in ihren Hofen und Stadten, zwolf Fursten uber ihre Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und das ist das Alter Ismaels: hundertundsiebenunddreißig Jahre; und nahm ab und starb und ward gesammelt zu seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Und sie wohneten von Hevila an bis gen Sur gegen Agypten, wenn man gen Assyrien gehet. Er fiel abervor alien seinen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dies ist das Geschlecht Isaaks, Abrahams Sohnes: Abraham zeugete Isaak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Isaak aber war vierzig Jahre alt, da er Rebekka zum Weibe nahm, die Tochter Bethuels, des Syrers, von Mesopotamien, Labans, des Syrers, Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaak aber bat den HERRN fur sein Weib, denn sie war unfruchtbar. Und der HERR ließ sich erbitten, und Rebekka, sein Weib, ward schwanger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Und die Kinder stießen sich miteinander in ihrem Leibe. Da sprach sie: Da mir\'s also sollte gehen, warum bin ich schwanger worden? Und sie ging hin, den HERRN zu fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Und der HERR sprach zu ihr: Zwei Volker sind in deinem Leibe, und zweierlei Leute werden sich scheiden aus deinem Leibe; und ein Volk wird dem andern überlegen sein, und der Großere wird dem Kleinem dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Da nun die Zeit kam, daß sie gebaren sollte, siehe, da waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Der erste, der herauskam, war rotlich, ganz rauch wie ein Fell; und sie nannten ihn Esau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Zuhand danach kam heraus sein Bruder, der hielt mit seiner Hand die Ferse des Esau; und hiefien ihn Jakob. Sechzig Jahre alt war Isaak, da sie geboren wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Und da nun die Knaben groß, wurden, ward Esau ein Jager und ein Ackermann, Jakob aber ein frommer Mann und blieb in den Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Und Isaak hatte Esau lieb und aß gem von seinem Weidwerk; Rebekka aber hatte Jakob lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Und Jakob kochte ein Gericht. Da kam Esau vom Felde und war mude');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'und sprach zu Jakob: Laß mich kosten das rote Gericht, denn ich bin mude. Daher heifit er Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Aber Jakob sprach: Verkaufe mir heute deine Erstgeburt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau antwortete: Siehe, ich muß doch sterben, was soil mirdann die Erstgeburt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jakob sprach: So schwore mir heute. Und er schwur ihm und verkaufte also Jakob seine Erstgeburt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Da gab ihm Jakob Brot und das Linsengericht, und er ali und trank; und stund auf und ging davon. Also verachtete Esau seine Erstgeburt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Es kam aber eine Teurung ins Land uber die vorige, so zu Abrahams Zeiten war. Und Isaak zog zu Abimelech, der Philister Konig, gen Gerar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da erschien ihm der HERR und sprach: Zeuch nicht hinab in Agypten, sondern bleibe in dem Lande, das ich dir sage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Sei ein Fremdling in diesem Lande, und ich will mit dir sein und dich segnen; denn dir und deinem Samen will ich alle diese Lander geben und will meinen Eid bestatigen, den ich deinem Vater Abraham geschworen habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'und will deinen Samen mehren wie die Sterne am Himmel und will deinem Samen alle diese Lander geben. Und durch deinen Samen sollen alle Volker auf Erden gesegnet werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'darum daß Abraham meiner Stimme gehorsam gewesen ist und hat gehalten meine Rechte, meine Gebote, meine Weise und meine Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Also wohnete Isaak zu Gerar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Und wenn die Leute am selben Orte fragten von seinem Weibe, so sprach er: Sie ist meine Schwester. Denn er furchtete sich zu sagen: Sie ist mein Weib; sie mochten mich erwurgen urn Rebekkas willen; denn sie war schon von Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Als er nun eine Zeitlang da war, sah Abimelech, der Philister Konig, durchs Fenster und ward gewahr, daß Isaak scherzte mit seinem Weibe Rebekka.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da rief Abimelech dem Isaak und sprach: Siehe, es ist dein Weib. Wie hast du denn gesagt: Sie ist meine Schwester? Isaak antwortete ihm: Ich gedachte, ich mochte vielleicht sterben mussen urn ihretwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelech sprach: Warum hast du denn uns das getan? Es ware leicht geschehen, daß jemand vom Volk sich zu deinem Weibe gelegt hatte, und flattest also eine Schuld auf uns gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Da gebot Abimelech allem Volk und sprach: Wer diesen Mann Oder sein Weib antastet, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Und Isaak saete in dem Lande und kriegte desselben Jahrs hundertfaltig; denn der HERR segnete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Und erward ein großer Mann, ging und nahm zu, bis erfastgroß ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'daß er viel Guts hatte an kleinem und großem Vieh und ein groß Gesinde. Darum neideten ihn die Philister');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'und verstopften alle Brunnen, die seines Vaters Knechte gegraben hatten, zur Zeit Abrahams, seines Vaters, und fulleten sie mit Erde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'daß auch Abimelech zu ihm sprach: Zeuch von uns, denn du bist uns zu machtig worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Da zog Isaak von dannen und schlug sein Gezelt auf im Grunde Gerar und wohnete allda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Und lielidie Wasserbrunnen wieder aufgraben, die sie zu Abrahams Zeiten, seines Vaters, gegraben hatten, welche die Philister verstopfet hatten nach Abrahams Tod, und nannte sie mit denselben Namen, da sie sein Vater mit genannt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Auch gruben Isaaks Knechte im Grunde und fanden daselbst einen Brunnen lebendigen Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Aber die Hirten von Gerar zankten mit den Hirten Isaaks und sprachen: Das Wasser ist unser. Da hieli er den Brunnen Esek, darum daß sie ihm da unrecht getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Da gruben sie einen andern Brunnen, da zankten sie auch uber; darum hieli er ihn Sitna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Da machte er sich von dannen und grub einen andern Brunnen, da zankten sie sich nicht uber; darum hieli er ihn Rehoboth und sprach: Nun hat uns der HERR Raum gemacht und uns wachsen lassen im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Danach zog er von dannen gen Bersaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und der HERR erschien ihm in derselben Nacht und sprach: Ich bin deines Vaters Abraham Gott. Furchte dich nicht, denn ich bin mit dir und will dich segnen und deinen Samen mehren urn meines Knechts Abrahams willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Da bauete er einen Altar daselbst und predigte von dem Namen des HERRN und richtete daselbst seine Hütte auf; und seine Knechte gruben daselbst einen Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Und Abimelech ging zu ihm von Gerar, und Ahusath, sein Freund, und Phichol, sein Feldhauptmann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Aber Isaak sprach zu ihnen: Warum kommt ihr zu mir? Hasset ihr mich doch und habt mich von euch getrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie sprachen: Wir sehen mit sehenden Augen, daß der HERR mit dir ist. Darum sprachen wir: Es soil ein Eid zwischen uns und dir sein, und wollen einen Bund mitdirmachen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'daß du uns keinen Schaden tust, gleichwie wir dich nicht angetastet haben, und wie wir dir nichts denn alles Gute getan haben und dich mit Frieden ziehen lassen. Du aber bist nun der Gesegnete des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Da machte er ihnen ein Mahl, und sie alien und tranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Und des Morgens fruhe stunden sie auf, und schwur einer dem andern; und Isaak lieli sie gehen, und sie zogen von ihm mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Desselben Tages kamen Isaaks Knechte und sagten ihm an von dem Brunnen, den sie gegraben hatten, und sprachen zu ihm: Wir haben Wasser funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Und er nannte ihn Saba; daher heilit die Stadt Bersaba bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Da Esau vierzig Jahre alt war, nahm er zum Weibe Judith, die Tochter Beris, des Hethiters; und Basmath, die Tochter Elons, des Hethiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Die machten beide Isaak und Rebekka eitel Herzeleid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Und es begab sich, da Isaak war alt worden, daß seine Augen dunkel wurden zu sehen, rief er Esau, seinem groliern Sohn, und sprach zu ihm: Mein Sohn! Er aber antwortete ihm: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Und er sprach: Siehe, ich bin alt worden und weili nicht, wann ich sterben soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'So nimm nun deinen Zeug, Kocher und Bogen, und gehe aufs Feld und fahe mir ein Wildbret');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'und mache mir ein Essen, wie ich\'s gerne habe, und bringe mir\'s herein, daß ich esse, daß dich meine Seele segne, ehe ich sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebekka aber horete solche Worte, die Isaak zu seinem Sohne Esau sagte. Und Esau ging hin aufs Feld, daß erein Wildbret jagte und heimbrachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Da sprach Rebekka zu Jakob, ihrem Sohn: Siehe, ich habe gehoret deinen Vater reden mit Esau, deinem Bruder, und sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Bringe mir ein Wildbret und mache mir ein Essen, daß ich esse und dich segne vor dem HERRN, ehe ich sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'So hore nun, mein Sohn, meine Stimme, was ich dich heilie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gehe hin zu der Herde und hole mir zwei gute Bocklein, daß ich deinem Vater ein Essen davon mache, wie er\'s gerne hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Das sollst du deinem Vater hineintragen, daß er esse, auf daß er dich segne vor seinem Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob aber sprach zu seiner Mutter Rebekka: Siehe, mein Bruder Esau ist rauch und ich glatt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'so mochte vielleicht mein Vater mich begreifen, und wurde vor ihm geachtet, als ob ich ihn betrugen wollte, und brachte uber mich einen Fluch und nicht einen Segen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sprach seine Mutter zu ihm: Der Fluch sei auf mir, mein Sohn; gehorche nur meiner Stimme, gehe und hole mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da ging er hin und holete und brachte seiner Mutter. Da machte seine Mutter ein Essen, wie sein Vater gerne hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'und nahm Esaus, ihres groliern Sohnes, kostliche Kleider, die sie bei sich im Hause hatte, und zog sie Jakob an, ihrem kleinem Sohn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'aber die Felle von den Bocklein tat sie ihm urn seine Hande, und wo er glatt war am Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Und gab also das Essen mit Brot, wie sie es gemacht hatte, in Jakobs Hand, ihres Sohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Und erging hinein zu seinem Vater und sprach: Mein Vater! Er antwortete: Hie bin ich. Wer bist du, mein Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob sprach zu seinem Vater: Ich bin Esau, dein erstgeborener Sohn; ich habe getan, wie du mir gesagt hast. Stehe auf, setze dich und ili von meinem Wildbret, auf daß mich deine Seele segne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Isaak aber sprach zu seinem Sohn: Mein Sohn, wie hast du so bald funden? Er antwortete: Der HERR, dein Gott, bescherte mir\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sprach Isaak zu Jakob: Tritt herzu, mein Sohn, da(S ich dich begreife, ob du seiest mein Sohn Esau, Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Also trat Jakob zu seinem Vater Isaak; und da er ihn begriffen hatte, sprach er: Die Stimme ist Jakobs Stimme, aber die Hande sind Esaus Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er kannte ihn nicht, denn seine Hande waren rauch, wie Esaus, seines Bruders, Hande, und segnete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Und er sprach zu ihm: Bist du mein Sohn Esau? Er antwortete: Ja, ich bin\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sprach er: So bringe mir her, mein Sohn, zu essen von deinem Wildbret, daß dich meine Seele segne. Da brachte er\'s ihm, und er ali; und trug ihm auch Wein hinein, und er trank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Und Isaak, sein Vater, sprach zu ihm: Komm her und kusse mich, mein Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Er trat hinzu und kussete ihn. Da roch er den Geruch seiner Kleider; und segnete ihn und sprach: Siehe, der Geruch meines Sohnes ist wie ein Geruch des Feldes, das der HERR gesegnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Gott gebe dir vom Tau des Himmels und von der Fettigkeit der Erde und Korn und Weins die Fülle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Volker müssen dir dienen, und Leute müssen dir zu Fulie fallen. Sei ein Herr uber deine Bruder, und deiner Mutter Kinder müssen dir zu Fulie fallen. Verflucht sei, wer dir fluchet; gesegnet sei, wer dich segnet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Als nun Isaak vollendet hatte den Segen uber Jakob, und Jakob kaum hinausgegangen war von seinem Vater Isaak, da kam Esau, sein Bruder, von seiner Jagd');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'und machte auch ein Essen; und trug\'s hinein zu seinem Vater und sprach zu ihm: Stehe auf, mein Vater, und ili von dem Wildbret deines Sohnes, daß mich deine Seele segne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Da antwortete ihm Isaak, sein Vater: Wer bist du? Er sprach: Ich bin Esau, dein erstgeborner Sohn:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da entsetzte sich Isaak uber die Malie sehr und sprach: Wer? wo ist denn der Jager, der mir gebracht hat, und ich habe von allem gegessen, ehe du kamst, und habe ihn gesegnet? Er wird auch gesegnet bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Als Esau diese Rede seines Vaters horte, schrie er laut und ward uber die Malie sehr betrubt; und sprach zu seinem Vater: Segne mich auch, mein Vater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Er aber sprach: Dein Bruder ist kommen mit List und hat deinen Segen hinweg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sprach er: Er heifit wohl Jakob; denn er hat mich nun zweimal untertreten. Meine Erstgeburt hat er dahin, und siehe, nun nimmt erauch meinen Segen. Und sprach: Hastdu mir denn keinen Segen vorbehalten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaak antwortete und sprach zu ihm: Ich habe ihn zum Herrn uber dich gesetzt, und alle seine Bruder habe ich ihm zu Knechten gemacht, mit Korn und Wein habe ich ihn versehen: was soli ich doch dir nun tun, mein Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esau sprach zu seinem Vater: Hast du denn nur einen Segen, mein Vater? Segne mich auch, mein Vater! Und hub auf seine Stimme und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da antwortete Isaak, sein Vater, und sprach zu ihm: Siehe da, du wirst eine fette Wohnung haben auf Erden und vom Tau des Himmels von oben her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Deines Schwerts wirst du dich nahren und deinem Bruder dienen. Und es wird geschehen, daß du auch ein Herr und sein Joch von deinem Halse reilien wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Und Esau war Jakob gram urn des Segens willen, damit ihn sein Vater gesegnet hatte, und sprach in seinem Herzen: Es wird die Zeit bald kommen, daß mein Vater Leid tragen muli; denn ich will meinen Bruder Jakob erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Da wurden Rebekka angesagt diese Worte ihres groliern Sohns Esau; und schickte hin und lieli Jakob, ihrem kleinern Sohn, rufen und sprach zu ihm: Siehe, dein Bruder Esau drauet dir, daß er dich erwurgen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Und nun hore meine Stimme, mein Sohn: Mach dich auf und fleuch zu meinem Bruder Laban in Haran,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'und bleib eine Weile bei ihm, bis sich der Grimm deines Bruders wende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'und bis sich sein Zorn wider dich von dir wende und vergesse, was du an ihm getan hast; so will ich danach schicken und dich von dannen holen lassen. Warum soilte ich euer beider beraubet werden auf einen Tag?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Und Rebekka sprach zu Isaak: Mich verdreulit zu leben vor den Tochtern Heths. Wo Jakob ein Weib nimmt von den Tochtern Heths, die da sind wie die Tochter dieses Landes, was soli mir das Leben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da rief Isaak seinem Sohn Jakob und segnete ihn; und gebot ihm und sprach zu ihm: Nimm nicht ein Weib von den Tochtern Kanaans;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'sondern mach dich auf und zeuch in Mesopotamien zu Bethuels, deiner Mutter Vaters, Haus und nimm dir ein Weib daselbst von den Tochtern Labans, deiner Mutter Bruders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Aber der allmachtige Gott segne dich und mache dich fruchtbar und mehre dich, daß du werdest ein Haufen Volker;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'und gebe dir den Segen Abrahams, dir und deinem Samen mit dir, daß du besitzest das Land, da du Fremdling innen bist, das Gott Abraham gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Also fertigte Isaak den Jakob, daß er nach Mesopotamien zog zu Laban, Bethuels Sohn, in Syrien, dem Bruder Rebekkas, seiner und Esaus Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Als nun Esau sah, daß Isaak Jakob gesegnet hatte und abgefertiget nach Mesopotamien, daß er daselbst ein Weib nahme, und daß, indem er ihn gesegnet, ihm gebot und sprach: Du sollst nicht ein Weib nehmen von den Tochtern Kanaans,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'und daß Jakob seinem Vater und seiner Mutter gehorchte und nach Mesopotamien zog,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'sah auch, dafi Isaak, sein Vater, nicht gerne sah die Tochter Kanaans:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'ging er hin zu Ismael und nahm uber die Weiber, die er zuvor hatte, Mahalath, die Tochter Ismaels, des Sohnes Abrahams, die Schwester Nebajoths, zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Aber Jakob zog aus von Bersaba und reisete gen Haran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Und kam an einen Ort, da blieb er uber Nacht, denn die Sonne war untergegangen. Und er nahm einen Stein des Orts und legte ihn zu seinen Haupten und legte sich an demselbigen Ort schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Und ihm traumete, und siehe, eine Leiter stund auf Erden, die ruhrete mit der Spitze an den Himmel; und siehe, die Engel Gottes stiegen daran auf und nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und der HERR stund oben drauf und sprach: Ich bin der HERR, Abrahams, deines Vaters, Gott und Isaaks Gott. Das Land, da du auf liegest, will ich dir und deinem Samen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und dein Same soil werden wie der Staub auf Erden, und du sollst ausgebreitet werden gegen den Abend, Morgen, Mitternacht und Mittag; und durch dich und deinen Samen sollen alle Geschlechter auf Erden gesegnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und siehe, ich bin mit dir und will dich behuten, wo du hinzeuchst, und will dich wieder herbringen in dies Land. Denn ich will dich nicht lassen, bis daß ich tue alles, was ich dir geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da nun Jakob von seinem Schlaf aufwachte, sprach er: Gewiftlich ist der HERR an diesem Ort, und ich wuftte es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und furchtete sich und sprach: Wie heilig ist diese Statte! Hie ist nichts anderes denn Gottes Haus, und hie ist die Pforte des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Und Jakob stund des Morgens fruhe auf und nahm den Stein, den er zu seinen Haupten geiegt hatte, und richtete ihn auf zu einem Mai und goft 01 oben drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Und hieft die Statte Bethel; vorhin hieft sonst die Stadt Lus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob tat ein Gelubde und sprach: So Gott wird mit mir sein und mich behuten auf dem Wege, den ich reise, und Brot zu essen geben und Kleider anzuziehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'und mich mit Frieden wieder heim zu meinem Vater bringen, so soli der HERR mein Gott sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'und dieser Stein, den ich aufgerichtet habe zu einem Mai, soil ein Gotteshaus werden; und alles, was du mir gibst, des will ich dir den Zehnten geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Da hub Jakob seine Füfte auf und ging in das Land, das gegen Morgen liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'und sah sich urn, und siehe, da war ein Brunnen auf dem Felde; und siehe, drei Herden Schafe lagen dabei, denn von dem Brunnen pflegten sie die Herden zu tranken, und lag ein grafter Stein vor dem Loch des Brunnens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und sie pflegten die Herden alle daselbst zu versammeln und den Stein von dem Brunnenloch zu walzen und die Schafe zu tranken, und taten alsdann den Stein wieder vor das Loch an seine Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Und Jakob sprach zu ihnen: Lieben Bruder, wo seid ihr her? Sie antworteten: Wir sind von Haran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Er sprach zu ihnen: Kennet ihr auch Laban, den Sohn Nahors? Sie antworteten: Wir kennen ihn wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Er sprach: Gehet es ihm auch wohl? Sie antworteten: Es gehet ihm wohl; und siehe, da kommt seine Tochter Rahel mit den Schafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Er sprach: Es ist noch hoch Tag und ist noch nicht Zeit, das Vieh einzutreiben; tranket die Schafe und gehet hin und weidet sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Sie antworteten: Wir konnen nicht, bis daß alle Herden zusammengebracht werden, und wir den Stein von des Brunnens Loch walzen und also die Schafe tranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Als er noch mit ihnen redete, kam Rahel mit den Schafen ihres Vaters, denn sie hütete der Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Da aber Jakob sah Rahel, die Tochter Labans, seiner Mutter Bruders, und die Schafe Labans, seiner Mutter Bruders, trat er hinzu und walzte den Stein von dem Loch des Brunnens und trankte die Schafe Labans, seiner Mutter Bruders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Und kussete Rahel und weinete laut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'und sagte ihr an, daß er ihres Vaters Bruder ware und Rebekkas Sohn. Da lief sie und sagte es ihrem Vater an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Da aber Laban horete von Jakob, seiner Schwester Sohn, lief er ihm entgegen und herzete und kussete ihn und führete ihn in sein Haus. Da erzahlete er dem Laban alle diese Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Da sprach Laban zu ihm: Wohlan, du bist mein Bein und Fleisch. Und da er nun einen Mond lang bei ihm gewesen war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'sprach Laban zu Jakob: Wiewohl du mein Bruder bist, solltest du mir darum umsonst dienen? Sage an, was soil dein Lohn sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Laban aber hatte zwo Tochter: die alteste hieft Lea, und die jungste hieft Rahel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Aber Lea hatte ein blodes Gesicht; Rahel war hubsch und schon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob gewann die Rahel lieb und sprach: Ich will dir sieben Jahre um Rahel, deine jungste Tochter, dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban antwortete: Es ist besser, ich gebe sie dir denn einem andern; bleibe bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Also dienete Jakob um Rahel sieben Jahre, und deuchten ihn, als waren es einzelne Tage, so lieb hatte er sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Und Jakob sprach zu Laban: Gib mir nun mein Weib; denn die Zeit ist hie, dad ich beiliege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da lud Laban alle Leute des Orts und machte ein Hochzeitsmahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Des Abends aber nahm er seine Tochter Lea und brachte sie zu ihm hinein; und er lag bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab seiner Tochter Lea seine Magd Silpa zur Magd.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Des Morgens aber siehe, da war es Lea. Und er sprach zu Laban: Warum hast du mir das getan? Habe ich dir nicht um Rahel gedienet? Warum hast du mich denn betrogen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban antwortete: Es ist nicht Sitte in unserm Lande, daü man die jungste ausgebe vor der altesten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Halte mit dieser die Woche aus, so will ich dir diese auch geben um den Dienst, den du bei mir noch andere sieben Jahre dienen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob tat also und hielt die Woche aus. Da gab ihm Laban Rahel, seine Tochter, zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und gab seiner Tochter Rahel seine Magd Bilha zur Magd.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Also lag er auch bei mit Rahel und hatte Rahel lieber denn Lea; und dienete bei ihm furder die andern sieben Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Da aber der HERR sah, dad Lea unwert war, machte er sie fruchtbar und Rahel unfruchtbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Und Lea ward schwanger und gebar einen Sohn; den hiefi sie Ruben und sprach: Der HERR hat angesehen mein Elend; nun wird mich mein Mann lieb haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Und ward abermal schwanger und gebar einen Sohn und sprach: Der HERR hat gehoret, dad ich unwert bin, und hat mirdiesen auch gegeben. Und hied ihn Simeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Abermal ward sie schwanger und gebar einen Sohn und sprach: Nun wird sich mein Mann wiederzu mir tun, denn ich habe ihm drei Sohne geboren. Darum hied sie ihn Levi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Zum vierten ward sie schwanger und gebar einen Sohn und sprach: Nun will ich dem HERRN danken. Darum hied sie ihn Juda. Und horte auf Kinder zu gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Da Rahel sah, daü sie dem Jakob nichts gebar, neidete sie ihre Schwester und sprach zu Jakob: Schaffe mir Kinder! Wo nicht, so sterbe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakob aber ward sehr zornig auf Rahel und sprach: Bin ich doch nicht Gott, der dir deines Leibes Frucht nicht geben will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Sie aber sprach: Siehe, da ist meine Magd Bilha; lege dich zu ihr, dafi sie auf meinem Schod gebare, und ich doch durch sie erbauet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Und sie gab ihm also Bilha, ihre Magd, zum Weibe; und Jakob legte sich zu ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Also ward Bilha schwanger und gebar Jakob einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sprach Rahel: Gott hat meine Sache gerichtet und meine Stimme erhoret und mir einen Sohn gegeben. Darum hied sie ihn Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Abermal ward Bilha, Rahels Magd, schwanger und gebar Jakob den andern Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sprach Rahel: Gott hat es gewandt mit mir und meiner Schwester, und ich werde es ihr zuvortun. Und hied ihn Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Da nun Lea sah, dad sie aufgehoret hatte zu gebaren, nahm sie ihre Magd Silpa und gab sie Jakob zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Also gebar Silpa, Leas Magd, Jakob einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sprach Lea: Rüstig! Und hied ihn Gad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Danach gebar Silpa, Leas Magd, Jakob den andern Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sprach Lea: Wohl mir, denn mich werden selig preisen die Tochter. Und hied ihn Asser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ruben ging aus zur Zeit der Weizenernte und fand Dudaim auf dem Felde und brachte sie heim seiner Mutter Lea. Da sprach Rahel zu Lea: Gib mir der Dudaim deines Sohnes ein Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Sie antwortete: Hastdu nicht genug, dad du mir meinen Mann genommen hast, und willst auch die Dudaim meines Sohnes nehmen? Rahel sprach: Wohlan, lad ihn diese Nacht bei dirschlafen um die Dudaim deines Sohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Da nun Jakob des Abends vom Felde kam, ging ihm Lea hinaus entgegen und sprach: Bei mir sollst du liegen; denn ich habe dich erkauft um die Dudaim meines Sohnes. Und erschlief die Nacht bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott erhorete Lea, und sie ward schwanger und gebar Jakob den funften Sohn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'und sprach: Gott hat mir gelohnet, dad ich meine Magd meinem Manne gegeben habe. Und hied ihn Isaschar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Abermal ward Lea schwanger und gebar Jakob den sechsten Sohn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'und sprach: Gott hat mich wohl beraten; nun wird mein Mann wieder bei mirwohnen, denn ich habe ihm sechs Sohne geboren. Und hied ihn Sebulon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Danach gebar sie eine Tochter, die hied sie Dina.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Der HERR gedachte aber an Rahel und erhorte sie und machte sie fruchtbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Da ward sie schwanger und gebar einen Sohn und sprach: Gott hat meine Schmach von mir genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und hieß ihn Joseph und sprach: Der HERR wolle mir noch einen Sohn dazu geben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Da nun Rahel den Joseph geboren hatte, sprach Jakob zu Laban: Laß mich ziehen und reisen an meinen Ort und in mein Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Weiber und meine Kinder, darum ich dir gedienet habe, daß ich ziehe; denn du weißest meinen Dienst, wie ich dir gedienet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban sprach zu ihm: Laß mich Gnade vor deinen Augen finden. Ich spüre, daß mich der HERR segnet urn deinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Stimme den Lohn, den ich dir geben soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Er aber sprach zu ihm: Du weißest, wie ich dir gedienet habe, und was du fur Vieh hattest unter mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Du hattest wenig, ehe ich herkam; nun aber ist\'s ausgebreitet in die Menge, und der HERR hat dich gesegnet durch meinen Fuß. Und nun, wann soil ich auch mein Haus versorgen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Er aber sprach: Was soli ich dir denn geben? Jakob sprach: Du sollst mir nichts uberall geben, sondern so du mir tun willst, das ich sage, so will ich wiederum weiden und hüten deiner Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich will heute durch alle deine Herde gehen und aussondern alle fleckichten und bunten Schafe und alle schwarzen Schafe unter den Lammern und die bunten und fleckichten Ziegen. Was nun bunt und fleckicht fallen wird, das soil mein Lohn sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'So wird mir meine Gerechtigkeit zeugen heute Oder morgen, wenn es kommt, daß ich meinen Lohn von dir nehmen soil, also daß, was nicht fleckicht Oder bunt Oder nicht schwarz sein wird unter den Lammern und Ziegen, das sei ein Diebstahl bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da sprach Laban: Siehe da, es sei, wie du gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und sonderte des Tages die sprenglichten und bunten Bocke und alle fleckichten und bunten Ziegen, wo nur was Weißes daran war, und alles, was schwarz war unter den Lammern, und tat\'s unter die Hand seiner Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und machte Raum dreier Tagereisen weit zwischen ihm und Jakob. Also weidete Jakob die ubrige Herde Labans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Jakob aber nahm Stabe von grunen Pappelbaumen, Haseln und Kastanien und schalete weiße Streifen daran, daß an den Staben das Weiße bloßward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'und legte die Stabe, die er geschalet hatte, in die Trankrinnen vor die Herden, die da kommen mußten zu trinken, daß sie empfangen sollten, wenn sie zu trinken kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Also empfingen die Herden uber den Staben und brachten sprenglichte, fleckichte und bunte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Da schied Jakob die Lammer und tat die abgesonderte Herde zu den fleckichten und schwarzen in der Herde Labans; und machte ihm eine eigene Herde, die tat er nicht zu der Herde Labans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Wenn aber der Lauf der Fruhlinger Herde war, legte er diese Stabe an die Rinnen vor die Augen der Herde, daß sie uber den Staben empfingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Aber in der Spatlinger Lauf legte er sie nicht hinein. Also wurden die Spatlinge des Laban, aber die Frühlinge des Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Daher ward der Mann uber die Maße reich, daß er viel Schafe, Magde und Knechte, Kamele und Esel hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Und es kamen vor ihn die Reden der Kinder Labans, daß sie sprachen: Jakob hat alle unsers Vaters Gut zu sich gebracht und von unsers Vaters Gut hat er solchen Reichtum zuwegegebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob sah an das Angesicht Labans; und siehe, es war nicht gegen ihn wie gestern und ehegestern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Und der HERR sprach zu Jakob: Zeuch wieder in deiner Vater Land und zu deiner Freundschaft; ich will mit dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sandte Jakob hin und ließ rufen Rahel und Lea aufs Feld bei seine Herde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'und sprach zu ihnen: Ich sehe eures Vaters Angesicht, daß es nicht gegen mich ist wie gestern und ehegestern; aber der Gott meines Vaters ist mit mirgewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Und ihrwisset, daß ich aus alien meinen Kraften eurem Vater gedienet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Und er hat mich getauschet und nun zehnmal meinen Lohn verandert; aber Gott hat ihm nicht gestattet, daß er mir Schaden tate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Wenn er sprach: Die bunten sollen dein Lohn sein, so trug die ganze Herde bunte. Wenn er aber sprach: Die sprenglichten sollen dein Lohn sein, so trug die ganze Herde sprenglichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Also hat Gott die Guter eures Vaters ihm entwandt und mir gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Denn wenn die Zeitdes Laufs kam, hub ich meine Augen auf und sah im Traum, und siehe, die Bocke sprangen auf die sprenglichte, fleckichte und bunte Herde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach zu mir im Traum: Jakob! Und ich antwortete: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Er aber sprach: Heb auf deine Augen und siehe, die Bocke springen auf die sprenglichte, fleckichte und bunte Herde; denn ich habe alles gesehen, was dir Laban tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott zu Bethel, da du den Stein gesalbet hast und mir daselbst ein Gelubde getan. Nun mach dich auf und zeuch aus diesem Lande und zeuch wieder in das Land deiner Freundschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da antwortete Rahel und Lea und sprachen zu ihm: Wir haben doch kein Teil noch Erbe mehr in unsers Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Hat eruns doch gehalten alsdie Fremden; denn er hat uns verkauft und unsern Lohn verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Darum hat Gott unserm Vater entwandt seinen Reichtum zu uns und unsern Kindern: Alles nun, was Gott dir gesagt hat, das tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Also machte sich Jakob auf und lud seine Kinder und Weiber auf Kamele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Und fuhrete weg all sein Vieh und alle seine Habe, die er in Mesopotamien erworben hatte, daß er kame zu Isaak, seinem Vater, ins Land Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, '(Laban aberwar gegangen, seine Herde zu scheren.) Und Rahel stahl ihres Vaters Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Also stahl Jakob dem Laban zu Syrien das Herz damit, daß er ihm nicht ansagte, daß er floh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Also floh er und alles, was sein war, machte sich auf und fuhr uber das Wasser und richtete sich nach dem Berge Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Am dritten Tage ward es Laban angesagt, daß Jakob flohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Und er nahm seine Bruder zu sich und jagte ihm nach sieben Tagereisen und ereilete ihn auf dem Berge Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Aber Gott kam zu Laban, dem Syrer, im Traum des Nachts und sprach zu ihm: Hüte dich, daß du mit Jakob nicht anders redest denn freundlich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Und Laban nahete zu Jakob. Jakob aber hatte seine Hütte aufgeschlagen auf dem Berge; und Laban mit seinen Brudern schlug seine Hütte auch auf auf dem Berge Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Da sprach Laban zu Jakob: Was hast du getan, daß du mein Herz gestohlen hast und hast meine Tochter entfuhret, als die durchs Schwert gefangen waren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich geflohen und hast dich weggestohlen und hast mir\'s nicht angesagt, daß ich dich hatte geleitet mit Freuden, mit Singen, mit Pauken und Harfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Und hast mich nicht lassen meine Kinder und Tochter küssen? Nun, du hast torlich getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Und ich hatte mit Gottes Hilfe wohl so viel Macht, daß ich euch konnte Ubels tun; aber eures Vaters Gott hat gestern zu mir gesagt: Hüte dich, daß du mit Jakob nicht anders denn freundlich redest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Und weil du denn ja wolltest ziehen und sehntest dich so fast nach deines Vaters Hause, warum hast du mir meine Gotter gestohlen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jakob antwortete und sprach zu Laban: Ich fürchtete mich und dachte, du würdest deine Tochter von, mirreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bei welchem aber du deine Gotter findest, der sterbe hie vor unsern Brudern. Suche das Deine bei mir und nimm\'s hin. Jakob wuftte aber nicht, daß sie Rahel gestohlen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da ging Laban in die Hütte Jakobs und Leas und der beiden Magde und fand nicht Und ging aus der Hütte Leas in die Hütte Rahels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Da nahm Rahel die Gotzen und legte sie unter die Streu der Kamele und setzte sich drauf. Laban aber betastete die ganze Hütte und fand nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Da sprach sie zu ihrem Vater: Mein Herr, zürne nicht, denn ich kann nicht aufstehen gegen dir; denn es gehet mir nach der Frauen Weise. Also fand er die Gotzen nicht wie fast er suchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Und Jakob ward zornig und schalt Laban und sprach zu ihm: Was habe ich miftgehandelt Oder gesündiget, daß du so auf mich erhitzt bist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hast alien meinen Hausrat betastet. Was hast du deines Hausrats funden? Lege das dar vor meinen und deinen Brüdern, daß sie zwischen uns beiden richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Diese zwanzig Jahre bin ich bei dirgewesen, deine Schafe und Ziegen sind nicht unfruchtbar gewesen; die Widder deiner Herde habe ich nie gegessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Was die Tiere zerrissen, brachte ich dir nicht, ich muftte es bezahlen; du fordertest es von meiner Hand, es ware mir des Tages Oder des Nachts gestohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Des Tages verschmachtete ich vor Hitze und des Nachts vor Frost, und kam kein Schlaf in meine Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Also habe ich diese zwanzig Jahre in deinem Hause gedienet, vierzehn urn deine Tochter und sechs urn deine Herde, und hast mir meinen Lohn zehnmal verandert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wo nicht der Gott meines Vaters, der Gott Abrahams, und die Furcht Isaaks auf meiner Seite gewesen ware, du flattest mich leer lassen ziehen. Aber Gott hat mein Elend und Mühe angesehen und hat dich gestern gestraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Laban antwortete und sprach zu Jakob: Die Tochter sind meine Tochter und die Kinder sind meine Kinder und die Herden sind meine Herden, und alles, was du siehest, ist mein, was kann ich meinen Tochtern heute Oder ihren Kindern tun, die sie geboren haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'So komm nun und laft uns einen Bund machen, ich und du, der ein Zeugnis sei zwischen mir und dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Da nahm Jakob einen Stein und richtete ihn auf zu einem Mai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Und sprach zu seinen Brudern: Leset Steine auf. Und sie nahmen Steine und machten einen Haufen und alien aufdemselben Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban hieft ihn Jegar-Sahadutha; Jakob aber hieft ihn Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Da sprach Laban: Der Haufe sei heute Zeuge zwischen mir und dir (daher heiftt man ihn Gilead)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'und sei eine Warte, denn er sprach: Der HERR sehe darein zwischen mir und dir, wenn wir voneinander kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'wo du meine Tochter beleidigest Oder andere Weiber dazu nimmst uber meine Tochter. Es ist hie kein Mensch mit uns; siehe aber, Gott ist der Zeuge zwischen mir und dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Und Laban sprach weiter zu Jakob: Siehe, das ist der Haufe und das ist das Mai, das ich aufgerichtet habe zwischen mir und dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Derselbe Haufe sei Zeuge, und das Mai sei auch Zeuge, wo ich herüberfahre zu dir, Oder du herüberfahrest zu mir uber diesen Haufen und Mai, zu beschadigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nahors und der Gott ihrer Vater sei Richter zwischen uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Und Jakob schwur ihm bei der Furcht seines Vaters Isaak. Und Jakob opferte auf dem Berge und lud seine Brüderzum Essen. Und da sie gegessen hatten, blieben sie auf dem Berge uber Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Des Morgens aber stund Laban frühe auf, küssete seine Kinder und Tochter und segnete sie; und zog hin und kam wieder an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Jakob aber zog seinen Weg; und es begegneten ihm die Engel Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Und da er sie sah, sprach er: Es sind Gottes Heere; und hiefi dieselbige Statte Mahanaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Jakob aber schickte Boten vor ihm her zu seinem Bruder Esau ins Land Seir, in der Gegend Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Und befahl ihnen und sprach: Also saget meinem Herrn Esau: Dein Knecht Jakob lafit dir sagen: Ich bin bis daher bei Laban lange aulien gewesen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'und habe Rinder und Esel, Schafe, Knechte und Magde; und habe ausgesandt dir, meinem Herrn, anzusagen, daß ich Gnade vordeinen Augen fande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Die Boten kamen wieder zu Jakob und sprachen: Wir kamen zu deinem Bruder Esau; und er zeucht dir auch entgegen mit vierhundert Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Da fürchtete sich Jakob sehr, und ihm ward bange; und teilete das Volk, das bei ihm war, und die Schafe und die Rinder und die Kamele in zwei Heere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Und sprach: So Esau kommt auf das eine Heer und schlagt es, so wird das übrige entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Weiter sprach Jakob: Gott meines Vaters Abraham und Gott meines Vaters Isaak, HERR, der du zu mir gesagt hast: Zeuch wieder in dein Land und zu deiner Freundschaft, ich will dir wohltun:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'ich bin geringe aller Barmherzigkeit und aller Treue, die du an deinem Knechte getan hast; denn ich hatte nicht mehr weder diesen Stab, da ich uber diesen Jordan ging, und nun bin ich zwei Heere worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Errette mich von der Hand meines Bruders, von der Hand Esaus; denn ich furchte mich vor ihm, daß er nicht komme und schlage mich, die Mutter samt den Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Du hast gesagt: Ich will dirwohltun und deinen Samen machen wie den Sand am Meer, den man nicht zahlen kann vor der Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Und er blieb die Nacht da und nahm von dem, das ervorhanden hatte, Geschenk seinem Bruder Esau:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'zweihundert Ziegen, zwanzig Bocke, zweihundert Schafe, zwanzig Widder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'und dreilüg saugende Kamele mit ihren Füllen, vierzig Kühe und zehn Farren, zwanzig Eselinnen mit zehn Fullen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'und tat sie unter die Hand seiner Knechte, je eine Herde besonders, und sprach zu ihnen: Gehet vor mir hin und lasset Raum zwischen einer Herde nach der andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Und gebot dem ersten und sprach: Wenn dir mein Bruder Esau begegnet und dich fraget: Wem gehorest du an? und wo willst du hin? und wes ist\'s, das du vor dir treibest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'sollst du sagen: Es gehoret deinem Knechte Jakob zu, der sendet Geschenk seinem Herrn Esau und zeucht hinter uns hernach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Also gebot er auch dem andern und dem dritten und alien, die den Herden nachgingen, und sprach: Wie ich euch gesagt habe, so saget zu Esau, wenn ihr ihm begegnet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'und saget ja auch: Siehe, dein Knecht Jakob ist hinter uns. Denn er gedachte, ich will ihn versohnen mit dem Geschenk, das vor mir hergehet; danach will ich ihn sehen, vielleicht wird er mich annehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Also ging das Geschenk vor ihm her, aber er blieb dieselbe Nacht beim Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Und stund auf in der Nacht und nahm seine zwei Weiber und die zwo Magde und seine elf Kinder und zog an die Furt Jabbok,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'nahm sie und fuhrete sie uber das Wasser, daß hinüberkam, was er hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'und blieb allein. Da rang ein Mann mit ihm, bis die Morgenrote anbrach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und da er sah, dafi er ihn nicht übermochte, ruhrete er das Gelenk seiner Hüfte an; und das Gelenk seiner Hüfte ward uber dem Ringen mit ihm verrenkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Und er sprach: Lali mich gehen, denn die Morgenrote bricht an. Aber er antwortete: Ich lasse dich nicht, du segnest mich denn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Er sprach: Wie heifiest du? Er antwortete: Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Er sprach: Du sollst nicht mehr Jakob heifien, sondern Israel. Denn du hast mit Gott und mit Menschen gekampft und bist obgelegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Und Jakob fragte ihn und sprach: Sage doch, wie heiliest du? Er aber sprach: Warum fragest du, wie ich heifie? Und er segnete ihn daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Und Jakob hiefi die Statte Pniel; denn ich habe Gott von Angesicht gesehen, und meine Seele ist genesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Und als er vor Pniel uberkam, ging ihm die Sonne auf; und er hinkte an seiner Hüfte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 33, 'Daher essen die Kinder Israel keine Spannader auf dem Gelenk der Hüfte bis auf den heutigen Tag, darum daß die Spannader an dem Gelenk der Hüfte Jakobs gerühret ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jakob hub seine Augen auf und sah seinen Bruder Esau kommen mit vierhundert Mann. Und teilete seine Kinder zu Lea und zu Rahel und zu beiden Magden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Und stellete die Magde mit ihren Kindern vorne an und Lea mit ihren Kindern hernach und Rahel mit Joseph zuletzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Und er ging vor ihnen her und neigete sich siebenmal auf die Erde, bis er zu seinem Bruder kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Esau aber lief ihm entgegen und herzete ihn und fiel ihm urn den Hals und kussete ihn; und sie weineten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Und hub seine Augen auf und sah die Weiber mit den Kindern und sprach: Wer sind diese bei dir? Er antwortete: Es sind Kinder, die Gott deinem Knechte bescheret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Und die Magde traten herzu mit ihren Kindern und neigeten sich vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Lea trat auch herzu mit ihren Kindern und neigeten sich vor ihm. Danach trat Joseph und Rahel herzu und neigeten sich auch vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Und er sprach: Was willst du mit all dem Heer, dem ich begegnet bin? Er antwortete: Dali ich Gnade fandevor meinem Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esau sprach: Ich habe genug, mein Bruder; behalt, was du hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob antwortete: Ach nicht! Habe ich Gnade funden vor dir, so nimm mein Geschenk von meiner Hand; denn ich sah dein Angesicht, als sahe ich Gottes Angesicht; und la(i dir\'s wohlgefallen von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch den Segen von mir an, den ich dir zugebracht habe; denn Gott hat mir\'s bescheret, und ich habe alles genug. Also notigte er ihn, daß er\'s nahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Und er sprach: Lali uns fortziehen und reisen; ich will mit dir ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Er aber sprach zu ihm: Mein Herr, du erkennest, daß ich zarte Kinder bei mir habe, dazu Vieh und saugende Kühe; wenn sie einen Tag ubertrieben würden, würde mir die ganze Herde sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Mein Herr ziehe vor seinem Knechte hin. Ich will mahlich hinnach treiben, danach das Vieh und die Kinder gehen konnen, bis daß ich komme zu meinem Herm in Seir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Esau sprach: So will ich doch bei dir lassen etliche vom Volk, das mit mir ist. Er antwortete: Was ist\'s vonnoten? Laü mich nur Gnade vor meinem Herm finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Also zog des Tages Esau wiederum seines Weges gen Seir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Und Jakob zog gen Suchoth und bauete ihm ein Haus und machte seinem Vieh Hütten; daher heüit die Statte Suchoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Danach zog Jakob gegen Salem, zu der Stadt des Sichem, die im Lande Kanaan liegt (nachdem er aus Mesopotamien kommen war), und machte sein Lager vor der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Und kaufte ein Stuck Ackers von den Kindern Hemors, des Vaters Sichems, urn hundert Groschen; daselbst richtete er seine Hütte auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Und richtete daselbst einen Altar zu und rief an den Namen des starken Gottes Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina aber, Leas Tochter, die sie Jakob geboren hatte, ging heraus, die Tochter des Landes zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Da die sah Sichem, Hemors Sohn, des Heviters, der des Landes Herr war, nahm er sie und beschlief sie und schwachte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Und sein Herz hing an ihr und hatte die Dime lieb und redete freundlich mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Sichem sprach zu seinem Vater Hemor: Nimm mir das Magdlein zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Und Jakob erfuhr, daß seine Tochter Dina geschandet war; und seine Sohne waren mit dem Vieh auf dem Felde, und Jakob schwieg, bis daß sie kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Da ging Hemor, Sichems Vater, heraus zu Jakob, mit ihm zu reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Indes kamen die Sohne Jakobs vom Felde. Und da sie es horeten, verdroß, es die Manner und wurden sehrzornig, dafi ereine Narrheit an Israel begangen und Jakobs Tochter beschlafen hatte; denn so sollte es nicht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Da redete Hemor mit ihnen und sprach: Meines Sohns Sichems Herz sehnet sich nach eurer Tochter; lieber, gebet sie ihm zum Weibe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Befreundet euch mit uns; gebet uns eure Tochter und nehmet ihr unsere Tochter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'und wohnet bei uns. Das Land soli euch offen sein; wohnet und werbet und gewinnet drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Sichem sprach zu ihrem Vater und Brudern: Lasset mich Gnade bei euch finden; was ihr mir saget, das will ich geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Fordert nur getrost von mir Morgengabe und Geschenk, ich will\'s geben, wie ihr heischet; gebt mir nur die Dime zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da antworteten Jakobs Sohne dem Sichem und seinem Vater Hemor betruglich, darum dafi ihre Schwester Dina geschandet war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'und sprachen zu ihnen: Wir konnen das nicht tun, daß wir unsere Schwester einem unbeschnittenen Mann geben; denn das ware uns eine Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Doch dann wollen wir euch zu Willen sein, so ihr uns gleich werdet und alles, was mannlich unter euch ist, beschnitten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Dann wollen wir unsere Tochter euch geben und eure Tochter uns nehmen und bei euch wohnen und ein Volk sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wo ihr aber nicht willigen wollet, euch zu beschneiden, so wollen wir unsere Tochter nehmen und davonziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Die Rede gefiel Hemor und seinem Sohn wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Und der Jungling verzog nicht, solches zu tun; denn er hatte Lust zu der Tochter Jakobs. Und er war herrlich gehalten uber alle in seines Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Da kamen sie nun, Hemor und sein Sohn Sichem, unter der Stadt Tor und redeten mit den Burgern der Stadt und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Leute sind friedsam bei uns und wollen im Lande wohnen und werben, so ist nun das Land weit genug fur sie; wir wollen uns ihre Tochter zu Weibern nehmen und ihnen unsere Tochter geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Aber dann wollen sie uns zu Willen sein, daß sie bei uns wohnen und ein Volk mit uns werden, wo wir alles, was mannlich unter uns ist, beschneiden, gleichwie sie beschnitten sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ihr Vieh und Güter und alles, was sie haben wird unser sein, so wir nur ihnen zu Willen werden, daß sie bei uns wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Und sie gehorchten dem Hemor und Sichem, seinem Sohn, alle, die zu seiner Stadt Tor aus und ein gingen, und beschnitten alles, was mannlich war, das zu seiner Stadt aus und ein ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Und am dritten Tage, da sie es schmerzete, nahmen die zween Sohne Jakobs, Simeon und Levi, der Dina Bruder, ein jeglicher sein Schwert und gingen in die Stadt turstiglich und erwurgeten alles, was mannlich war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Und erwurgeten auch Hemor und seinen Sohn Sichem mit der Scharfe des Schwerts; und nahmen ihre Schwester Dina aus dem Hause Sichems und gingen davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Da kamen die Sohne Jakobs uber die Erschlagenen und plunderten die Stadt, darum daß sie hatten ihre Schwester geschandet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'und nahmen ihre Schafe, Rinder, Esel und was in der Stadt und auf dem Felde war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'und alle ihre Habe, alle Kinder und Weiber nahmen sie gefangen und plunderten alles, was in den Hausern war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Und Jakob sprach zu Simeon und Levi: Ihr habt mir Ungluck zugerichtet, daß ich stinke vor den Einwohnern dieses Landes, den Kanaanitern und Pheresitern; und ich bin ein geringer Haufe. Wenn sie sich nun versammeln uber mich, so werden sie mich schlagen. Also werde ich vertilget samt meinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sie antworteten aber: Sollten sie denn mit unserer Schwester als mit einer Hure handeln?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Und Gott sprach zu Jakob: Mache dich auf und zeuch gen Bethel und wohne daselbst; und mache daselbst einen Altar dem Gott, der dir erschien, da du flohest vor deinem Bruder Esau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sprach Jakob zu seinem Hause und zu alien, die mit ihm waren: Tut von euch die fremden Gotter, so unter euch sind, und reiniget euch und andert eure Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Und lasset uns auf sein und gen Bethel ziehen, daß ich daselbst einen Altar mache dem Gott, der mich erhoret hat zur Zeit meiner Trubsal und ist mit mir gewesen auf dem Wege, den ich gezogen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da gaben sie ihm alle fremden Gotter, die unter ihren Handen waren, und ihre Ohrenspangen; und er vergrub sie unter eine Eiche, die neben Sichem stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Und sie zogen aus. Und es kam die Furcht Gottes uber die Stadte, die urn sie her lagen, daß sie den Sdhnen Jakobs nicht nachjagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Also kam Jakob gen Lus im Lande Kanaan, die da Bethel, heifit, samt all dem Volk, das mit ihm war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'und bauete daselbst einen Altar und hiefi die Statte El-Bethel, darum daß ihm daselbst Gott offenbaret war, da er floh vor seinem Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Da starb Debora, der Rebekka Amme, und ward begraben unter Bethel, unter der Eiche; und ward, genannt die Klageiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien Jakob abermal, nachdem er aus Mesopotamien kommen war, und segnete ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'und sprach zu ihm: Du heiliest Jakob; aber du sollst nicht mehr Jakob heilien, sondern Israel sollst du heilien. Und also man ihn Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: Ich bin der allmachtige Gott; sei fruchtbar und mehre dich; Volker und Volkerhaufen sollen von dir kommen, und Konige sollen aus deinen Lenden kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, das ich Abraham und Isaak gegeben habe, will ich dir geben und will\'s deinem Samen nach dir geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Alsofuhr Gott auf von ihm; von dem Ort, da er mit ihm geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jakob aber richtete ein steinern Mai auf an dem Ort, da er mit ihm geredet hatte, und goli Trankopfer drauf und begoli ihn mit 01.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob hieli den Ort, da Gott mit ihm geredet hatte, Bethel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Und sie zogen von Bethel. Und da noch ein Feldwegs war von Ephrath, da gebar Rahel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Und es kam sie hart an uber der Geburt. Daes ihr aber so sauer ward in der Geburt, sprach die Wehmutterzu ihr: Furchte dich nicht, denn diesen Sohn wirst du auch haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Da ihr aber die Seele ausging, daß sie sterben mulite, hieü sie ihn Benoni; aber sein Vater hieli ihn Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Also starb Rahel und ward begraben an dem Wege gen Ephrath, die nun heilit Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob richtete ein Mai auf uber ihrem Grabe; dasselbe ist das Grabmal Rahels bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Und Israel zog aus und richtete eine Hütte auf jenseits des Turns Eder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Und es begab sich, da Israel im Lande wohnete, ging Ruben hin und schlief bei Bilha, seines Vaters Kebsweibe; und das kam vor Israel. Es hatte aber Jakob zwolf Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Sohne Leas waren diese: Ruben, der erstgeborne Sohn Jakobs, Simeon, Levi, Juda, Isaschar und Sebulon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Die Sohne Rahels waren: Joseph und Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Die Sohne Bilhas, Rahels Magd: Dan und Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Die Sohne Silpas, Leas Magd: Gad und Asser. Das sind die Sohne Jakobs, die ihm geboren sind in Mesopotamien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob kam zu seinem Vater Isaak gen Mamre in die Hauptstadt, die da heißt Hebron, da Abraham und Isaak Fremdlinge innen gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Und Isaak ward hundertundachtzig Jahre alt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Und nahm ab und starb und ward versammelt zu seinem Volk, alt und des Lebens satt. Und seine Sohne Esau und Jakob begruben ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dies ist das Geschlecht Esaus, der da heißt Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau nahm Weiber von den Tochtern Kanaans: Ada, die Tochter Elons, des Hethiters; und Ahalibama, die Tochter des Ana, die Neffe Zibeons, des Heviters;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'und Basmath, Ismaels Tochter, Nebajoths Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Und Ada gebar dem Esau Eliphas, aber Basmath gebar Reguel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Ahalibama gebar Jehus, Jaelam und Korah. Das sind Esaus Kinder, die ihm geboren sind im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Weiber, Sohne und Tochter und alle Seelen seines Hauses, seine Habe und alles Vieh mit alien Gutern, so er im Lande Kanaan erworben hatte, und zog in ein Land von seinem Bruder Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihre Habe war zu groß, daß sie nicht konnten beieinanderwohnen; und das Land, darin sie Fremdlinge waren, mochte sie nicht ertragen vor der Menge ihres Viehes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Also wohnete Esau auf dem Gebirge Seir. Und Esau ist der Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Dies ist das Geschlecht Esaus, von dem die Edomiter herkommen, auf dem Gebirge Seir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Und so heißen die Kinder Esaus: Eliphas, der Sohn Adas, Esaus Weibes; Reguel, der Sohn Basmaths, Esaus Weibes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Eliphas Sohne aber waren diese: Theman, Omar, Zepho, Gaetham und Kenas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Thimna war ein Kebsweib Eliphas, Esaus Sohns, die gebar ihm Amalek. Das sind die Kinder von Ada, Esaus Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Die Kinder aber Reguels sind diese: Nahath, Serah, Samma, Missa. Das sind die Kinder von Basmath, Esaus Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Die Kinder aber von Ahalibama, Esaus Weib, der Tochter des Ana, der Neffe Zibeons, sind diese, die sie dem Esau gebar: Jehus, Jaelam und Korah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Das sind die Fursten unter den Kindern Esaus: Die Kinder Eliphas, des ersten Sohns Esaus, waren diese: der Furst Theman, der Furst Omar, der Fürst Zepho, der Furst Kenas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'der Fürst Korah, der Fürst Gaetham, der Fürst Amalek. Das sind die Fürsten von Eliphas, im Lande Edom, und sind Kinder von der Ada.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und das sind die Kinder Reguels, Esaus Sohns: der Furst Nahath, der Fürst Serah, der Fürst Samma, der Fürst Missa. Das sind die Fürsten von Reguel im Lande der Edomiter und sind Kinder von der Basmath, Esaus Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Das sind die Kinder Ahalibamas, Esaus Weibes: der Fürst Jehus, der Fürst Jaelam, der Fürst Korah. Das sind die Fürsten von Ahalibama, der Tochter des Ana, Esaus Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Das sind Esaus Kinder und ihre Fursten. Er ist der Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Die Kinder aber von Seir, dem Horiten, der im Lande wohnete, sind diese: Lothan, Sobal, Zibeon, Ana, Dison, Ezer und Disan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Das sind die Fürsten der Horiten, Kinder des Seir, im Lande Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Aber des Lothan Kinder waren diese: Hori und Heman; und Lothans Schwester hieß Thimna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Die Kinder von Sobal waren diese: Alwan, Manahath, Ebai, Sepho und Onam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Die Kinder von Zibeon waren: Aja und Ana. Das ist der Ana, der in der Wüste Maulpferde erfand, da er seines Vaters Zibeons Esel hütete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Die Kinder aber Anas waren: Dison und Ahalibama, das ist die Tochter Anas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Die Kinder Disons waren: Hemdan, Esban, Jethran und Charan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Die Kinder Ezers waren: Bilhan, Sawan und Akan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Die Kinder Disans waren: Uz und Man.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dies sind die Fursten der Horiten: der Furst Lothan, der Furst Sobal, der Furst Zibeon, der Furst Ana,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'der Fürst Dison, der Fürst Ezer, der Fürst Disan. Das sind die Fürsten der Horiten, die regieret haben im Lande Seir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Die Konige aber, die im Lande Edom regieret haben, ehe denn die Kinder Israel Konige hatten, sind diese:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela war Konig in Edom, ein Sohn Beors; und seine Stadt hieß Dinhaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Und da Bela starb, ward Konig an seiner Statt Jobab, ein Sohn Serahs von Bazra.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Da Jobab starb, ward an seiner Statt Konig Husam aus der Themaniter Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Da Husam starb, ward Konig an seiner Statt Hadad, ein Sohn Bedads, der die Midianiter schlug auf der Moabiter Feide; und seine Stadt hieß Awith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Da Hadad starb, regierete Sarnia von Masrek.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Da Sarnia starb, ward Saul Konig, von Rehoboth am Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Da Saul starb, ward an seiner Statt Konig Baal Hanan, der Sohn Achbors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Da Baal Hanan, Achbors Sohn, starb, ward an seiner Statt Konig Hadar, und seine Stadt hied Pagu; und sein Weib hieli Mehetabeel, eine Tochter Matreds, die Mesahabs Tochter war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Also heiden die Fursten von Esau in ihren Geschlechtern, Ortern und Namen: der Furst Thimna, der Furst Aiwa, der Furst Jetheth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'der Furst Ahalibama, der Furst Ela, der Furst Pinon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'der Furst Kenas, der Furst Theman, der Furst Mibzar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'der Furst Magdiel, der Furst Iram. Das sind die Fursten in Edom, wie sie gewohnet haben in ihrem Erblande. Und Esau ist der Vater der Edomiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob aber wohnete im Lande, da sein Vater ein Fremdling innen gewesen war, namlich im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Und das sind die Geschlechter Jakobs: Joseph war siebenzehn Jahre alt, da er ein Hide des Viehes ward mit seinen Brudern; und der Knabe war bei den Kindern Bilhas und Silpas, seines Vaters Weiber, und brachte vor ihren Vater, wo ein bos Geschrei wider sie war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Israel aber hatte Joseph lieber denn alle seine Kinder, darum daß er ihn im Alter gezeuget hatte; und machte ihm einen bunten Rock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Da nun seine Bruder sahen, dad ihn ihr Vater lieber hatte denn alle seine Bruder, waren sie ihm feind und konnten ihm kein freundlich Wort zusprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Dazu hatte Joseph einmal einen Traum und sagte seinen Brudern davon; da wurden sie ihm noch feinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Denn ersprach zu ihnen: Horet, lieber, was mir doch getraumet hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Mich deuchte, wir banden Garben auf dem Felde, und meine Garbe richtete sich auf und stund, und eure Garben umher neigeten sich gegen meine Garbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sprachen seine Bruder zu ihm: Solltestdu unser Konig werden und über uns herrschen? Und wurden ihm noch feinder urn seines Traums und seiner Rede willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Und er hatte noch einen andern Traum, den erzahite er seinen Brudern und sprach: Siehe, ich habe noch einen Traum gehabt. Mich deuchte, die Sonne und der Mond und elf Sterne neigeten sich vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Und da das seinem Vater und seinen Brudern gesagt ward, strafte ihn sein Vater und sprach zu ihm: Was ist das fur ein Traum, der dir getraumet hat? Soil ich und deine Mutter und deine Bruder kommen und dich anbeten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Und seine Bruder neideten ihn. Aber sein Vater behielt diese Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Da nun seine Bruder hingingen, zu weiden das Vieh ihres Vaters in Sichem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'sprach Israel zu Joseph: Huten nicht deine Bruder des Viehes in Sichem? Komm, ich will dich zu ihnen senden. Er aber sprach: Hie bin ich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Und er sprach: Gehe hin und sieh, ob es wohl stehe urn deine Bruder und urn das Vieh; und sage mir wieder, wie sich\'s halt. Und er sandte ihn aus dem Tal Hebron, daß ergen Sichem ginge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Dafand ihn ein Mann, daß er irre ging auf dem Felde; der fragte ihn und sprach: Wen suchest du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Er antwortete: ich suche meine Bruder; lieber, sage mir an, wo sie huten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Der Mann sprach: Sie sind von dannen gezogen; denn ich horte, dad sie sagten: Lasset uns gen Dothan gehen. Da folgte Joseph seinen Brudern nach und fand sie zu Dothan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Als sie ihn nun sahen von feme, ehe denn er nahe bei sie kam, schlugen sie an, dad sie ihn toteten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'und sprachen untereinander: Sehet, der Traumer kommt daher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'So kommt nun und lasset uns ihn erwurgen und in eine Grube werfen und sagen, ein boses Tier habe ihn gefressen, so wird man sehen, was seine Traume sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Da das Ruben horete, wollte er ihn aus ihren Handen erretten und sprach: Lasset uns ihn nicht toten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Und weiter sprach Ruben zu ihnen: Vergiefiet nicht Blut, sondern werfet ihn in die Grube, die in der Wüste ist, und leget die Hand nicht an ihn. Er wollte ihn aber aus ihrer Hand erretten, dafi er ihn seinem Vater wiederbrachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Als nun Joseph zu seinen Brudern kam, zogen sie ihm seinen Rock mit dem bunten Rock aus, den er anhatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'und nahmen ihn und warfen ihn in eine Grube; aber dieselbige Grube war leer und kein Wasser drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Und setzten sich nieder zu essen. Indes huben sie ihre Augen auf und sahen einen Haufen Ismaeliter kommen von Gilead mit ihren Kamelen; die trugen Würze, Balsam und Myrrhen, und zogen hinab nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sprach Juda zu seinen Brudern: Was hilft\'s uns, dad wir unsern Bruder erwurgen und sein Blut verbergen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt, lasset uns ihn den Ismaeliten verkaufen, dad sich unsere Hande nicht an ihm vergreifen; denn er ist unser Bruder, unser Fleisch und Biut. Und sie gehorchten ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Und da die Midianiter, die Kaufleute, voruberreiseten, zogen sie ihn heraus aus der Grube und verkauften ihn den Ismaeliten urn zwanzig Silberlinge; die brachten ihn nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Als nun Ruben wieder zur Grube kam und fand Joseph nicht darinnen, zerril J, ersein Kleid');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'und kam wieder zu seinen Brudern und sprach: Der Knabe ist nicht da, wo soil ich hin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Da nahmen sie Josephs Rock und schlachteten einen Ziegenbock und tunkten den Rock ins Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Und schickten den bunten Rock hin und lielien ihn ihrem Vater bringen und sagen: Diesen haben wir funden; siehe, ob es deines Sohnes Rock sei, Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Er kannte ihn aber und sprach: Es ist meines Sohnes Rock; ein boses Tier hat ihn gefressen, ein reißend Tier hat Joseph zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Kleider und legte einen Sack um seine Lenden und trug Leid um seinen Sohn lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Und alle seine Sohne und Tochter traten auf, daß sie ihn trosteten; aber erwollte sich nicht trosten lassen und sprach: Ich werde mit Leide hinunterfahren in die Grube zu meinem Sohne. Und sein Vater beweinete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Aber die Midianiter verkauften ihn in Agypten dem Potiphar, des Pharao Kammerer und Hofmeister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Es begab sich um dieselbige Zeit, daß Juda hinabzog von seinen Brudern und tat sich zu einem Mann von Odollam, der hieß Hira.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Und Juda sah daselbst eines Kanaaniter- Mannes Tochter, der hied Suah; und nahm sie. Und da er sie beschlief,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'ward sie schwanger und gebar einen Sohn, den hied er Ger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Und sie ward aber schwanger und gebar einen Sohn, den hied sie Onan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Sie gebar abermal einen Sohn, den hied sie Sela; und erwarzu Chesib, da sie ihn gebar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Und Juda gab seinem ersten Sohn Ger ein Weib, die hied Thamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Aber er war bose vor dem HERRN; darum totete ihn der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sprach Juda zu Onan: Lege dich zu deines Bruders Weib und nimm sie zur Ehe, dad du deinem Bruder Samen erweckest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Aber da Onan wudte, dad der Same nicht sein eigen sein sollte, wenn er sich zu seines Bruders Weib legte, lied er\'s auf die Erde fallen und verderbete es, auf dad er seinem Bruder nicht Samen gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Das gefiel dem HERRN ubel, das er tat, und totete ihn auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sprach Juda zu seiner Schnur Thamar: Bleibe eine Witwe in deines Vaters Hause, bis mein Sohn Sela grod wird. Denn ergedachte: Vielleicht mochte er auch sterben wie seine Bruder. Also ging Thamar hin und blieb in ihres Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Da nun viele Tage verlaufen waren, starb des Suah Tochter, Judas Weib. Und nachdem Juda ausgetrauert hatte, ging er hinauf, seine Schafe zu scheren, gen Thimnath mit seinem Hirten Hira von Odollam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Da ward der Thamar angesagt: Siehe, dein Schwaher gehet hinauf gen Thimnath, seine Schafe zu scheren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Da legte sie die Witwenkleider von sich, die sie trug, deckte sich mit einem Mantel und verhüllete sich und setzte sich vor die Tür heraus an dem Wege gen Thimnath; denn sie sah, dad Seia war grod worden, und sie ward ihm nicht zum Weibe gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Da sie nun Juda sah, meinete er, es ware eine Hure, denn sie hatte ihr Angesicht verdecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und machte sich zu ihr am Wege und sprach: Lieber, lad mich bei dir liegen. Denn er wudte nicht, dad sie seine Schnur ware. Sie antwortete: Was willst du mir geben, dad du bei mir liegest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Er sprach: Ich will dir einen Ziegenbock von der Herde senden. Sie antwortete: So gib mir ein Pfand, bis dad du mir\'s sendest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Er sprach: Was willst du fur ein Pfand, das ich dir gebe? Sie antwortete: Deinen Ring und deine Schnur und deinen Stab, den du in den Handen hast; Da gab er\'s ihr und lag bei ihr; und sie ward von ihm schwanger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Und sie machte sich auf und ging hin und legte den Mantel ab und zog ihre Witwenkleider an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda aber sandte den Ziegenbock durch seinen Hirten von Odoliam, daß erdas Pfand wieder holete von dem Weibe; und er fand sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Da fragte er die Leute desselbigen Orts und sprach: Wo ist die Hure, die auften am Wege saß? Sie antworteten: Es ist keine Hure dagewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Und er kam wieder zu Juda und sprach: Ich habe sie nicht funden; dazu sagen die Leute desselben Orts, es sei keine Hure dagewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juda sprach: Sie hab\'s ihr, sie kann uns doch ja nicht Schande nachsagen; denn ich habe den Bock gesandt, so hast du sie nicht funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Uber drei Monden ward Juda angesagt: Deine Schnur Thamar hat gehuret; dazu siehe, sie ist von Hurerei schwanger worden. Juda sprach: Bringet sie hervor, daß sie verbrannt werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Und da man sie hervorbrachte, schickte sie zu ihrem Schwaher und sprach: Von dem Manne bin ich schwanger, des dies ist. Und sprach: Kennest du auch, wes dieser Ring und diese Schnur und dieser Stab ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Juda erkannte es und sprach: Sie ist gerechter denn ich; denn ich habe sie nicht gegeben meinem Sohn Sela. Doch beschlief er sie nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Und da sie gebaren sollte, wurden Zwillinge in ihrem Leibe erfunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Und als sie jetzt gebar, tat sich eine Hand heraus. Da nahm die Wehmutter und band einen roten Faden darum und sprach: Der wird der erste herauskommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Da aber der seine Hand wieder hinein zog, kam sein Bruder heraus; und sie sprach: Warum hast du um deinetwillen solchen Rili gerissen? Und man hieli ihn Perez.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Danach kam sein Bruder heraus, der den roten Faden um seine Hand hatte. Und man hiefi ihn Serah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Joseph ward hinab in Agypten gefuhret; und Potiphar, ein agyptischer Mann, des Pharao Kammerer und Hofmeister, kaufte ihn von den Ismaeliten, die ihn hinabbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Und der HERR war mit Joseph, daß er ein gluckseliger Mann ward; und war in seines Herrn, des Agypters, Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Und sein Herr sah, daß der HERR mit ihm war; denn alles, was er tat, da gab der HERR Gluck zu durch ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'also daß er Gnade fand vor seinem Herrn und sein Diener ward. Der setzte ihn uber sein Haus, und alles, was er hatte, tat er unter seine Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und von der Zeit an, da er ihn uber sein Haus und alle seine Güter gesetzt hatte, segnete der HERR des Agypters Haus um Josephs willen, und war eitel Segen des HERRN in allem, was er hatte, zu Hause und zu Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Darum liefi er alles unter Josephs Handen, was er hatte; und er nahm sich keines Dinges an, weil er ihn hatte, denn daß er ali und trank. Und Joseph war schdn und hubsch von Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Und es begab sich nach dieser Geschichte, daß seines Herrn Weib ihre Augen auf Joseph warf und sprach: Schlafe bei mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er weigerte sich\'s aber und sprach zu ihr: Siehe, mein Herr nimmt sich nichts an vor mir, was im Hause ist; und alles, was er hat, das hat er unter meine Hande getan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'und hat nichts so grofi in dem Hause, das ervor mirverhohlen habe, ohne dich, indem du sein Weib bist. Wie sollt ich denn nun ein solch groli Obel tun und wider Gott sundigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und sie trieb solche Worte gegen Joseph taglich. Aber er gehorchte ihr nicht, daß er nahe bei ihr schlief noch um sie ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Es begab sich der Tage einen, daß Joseph in das Haus ging, sein Geschaft zu tun, und war kein Mensch vom Gesinde des Hauses dabei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Und sie erwischte ihn bei seinem Kleid und sprach: Schlafe bei mir! Aber er lieli das Kleid in ihrer Hand und floh und lief zum Hause hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Da sie nun sah, daß er sein Kleid in ihrer Hand lieli und hinaus entfloh,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'rief sie dem Gesinde im Hause und sprach zu ihnen: Sehet, er hat uns den ebraischen Mann hereingebracht, daß er uns zuschanden mache. Er kam zu mir herein und wollte bei mir schlafen; ich rief aber mit lauterßtimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Und da erhorete, daß ich ein Geschrei machte und rief, da lieli er sein Kleid bei mir und floh und lief hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie legte sein Kleid neben sich, bis sein Herr heim kam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'und sagte zu ihm eben dieselben Worte und sprach: Der ebraische Knecht, den du uns hereingebracht hast, kam zu mir herein und wollte mich zuschanden machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Da ich aber ein Geschrei machte und rief, da lieli er sein Kleid bei mir und floh hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Als sein Herr horete die Rede seines Weibes, die sie ihm sagte und sprach: Also hat mir dein Knecht getan, ward er sehr zornig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Da nahm ihn sein Herr und legte ihn ins Gefangnis, da des Konigs Gefangene innen lagen; und er lag allda im Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber der HERR war mit ihm und neigte seine Huld zu ihm und lieli ihn Gnade finden vor dem Amtmann uber das Gefangnis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'daß er ihm unter seine Hand befahl alle Gefangenen im Gefangnis, auf daß alles, was da geschah, durch ihn geschehen mulite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Denn der Amtmann uber das Gefangnis nahm sich keines Dinges an; denn der HERR war mit Joseph, und was er tat, da gab der HERR Gluck zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Und es begab sich danach, daß sich der Schenke des Konigs in Agypten und der Backer versundigten an ihrem Herrn, dem Konige in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Und Pharao ward zornig uber seine beiden Kammerer, uber den Amtmann uber die Schenken und uber den Amtmann uber die Backer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'und lieli sie setzen in des Hofmeisters Haus ins Gefangnis, da Joseph gefangen lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Hofmeister setzte Joseph uber sie, daß er ihnen dienete; und salien etliche Tage im Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Und es traumete ihnen beiden, dem Schenken und Backer des Konigs zu Agypten, in einer Nacht, einem jeglichen ein eigener Traum; und eines jeglichen Traum hatte seine Bedeutung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Da nun des Morgens Joseph zu ihnen hinein kam und sah, daß sie traurig waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'fragte er sie und sprach: Warum seid ihr heute so traurig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Sie antworteten: Es hat uns getraumet, und haben niemand, der es uns auslege. Joseph sprach: Auslegen gehoret Gott zu, doch erzahlet mir\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da erzahlete der oberste Schenke seinen Traum Joseph und sprach zu ihm: Mir hat getraumet, daß ein Weinstock vor mir ware,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'der hatte drei Reben, und er grunete, wuchs und bluhete, und seine Trauben wurden reif;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'und ich hatte den Becher Pharaos in meiner Hand und nahm die Beeren und zerdruckte sie in den Becher und gab den Becher Pharao in die Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Joseph sprach zu ihm: Das ist seine Deutung: Drei Reben sind drei Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Uber drei Tage wird Pharao dein Haupt erheben und dich wieder an dein Amt stellen, daß du ihm den Becher in die Hand gebest nach der vorigen Weise, da du sein Schenke warst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber gedenke meiner, wenn dir\'s wohlgehet, und tu Barmherzigkeit an mir, daß du Pharao erinnerst, daß er mich aus diesem Hause führe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn ich bin aus dem Lande der Ebraer heimlich gestohlen; dazu habe ich auch allhie nichts getan, daß sie mich eingesetzt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Da der oberste Backer sah, daß die Deutung gut war, sprach er zu Joseph: Mir hat auch getraumet, ich trüge drei weifte Korbe auf meinem Haupt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'und im obersten Korbe allerlei gebackene Speise dem Pharao; und die Vogel alien aus dem Korbe auf meinem Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joseph antwortete und sprach: Das ist seine Deutung: Drei Korbe sind drei Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Und nach dreien Tagen wird dir Pharao dein Haupt erheben und dich an den Galgen henken, und die Vogel werden dein Fleisch von dir essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und es geschah des dritten Tages, da beging Pharao seinen Jahrtag; und er machte eine Mahlzeit alien seinen Knechten und erhub das Haupt des obersten Schenken und das Haupt des obersten Backers unter seinen Knechten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'und setzte den obersten Schenken wieder zu seinem Schenkamt, daß er den Becher reichte in Pharaos Hand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'aber den obersten Backer lieft er henken, wie ihnen Joseph gedeutet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der oberste Schenke gedachte nicht an Joseph, sondern vergaft sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Und nach zweien Jahren hatte Pharao einen Traum, wie er stünde am Wasser');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'und sahe aus dem Wasser steigen sieben schone fette Kühe, und gingen an der Weide im Grase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Nach diesen sah er andere sieben Kühe aus dem Wasser aufsteigen; die waren haftlich und mager und traten neben die Kühe an das Ufer am Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Und die haftlichen und magern fraften die sieben schonen fetten Kühe. Da erwachte Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Und erschlief wieder ein, und ihm traumete abermal, und sah, daß sieben Ahren wuchsen aus einem Halm, voll und dick.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Danach sah er sieben dünne und versengete Ahren aufgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die sieben mageren Ahren verschlangen die sieben dicken und vollen Ahren. Da erwachte Pharao und merkte, daß es ein Traum war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Und da es Morgen ward, war sein Geist bekümmert, und schickte aus und lieft rufen alle Wahrsager in Agypten und alle Weisen und erzahlete ihnen seine Traume. Aber da war keiner, der sie dem Pharao deuten konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da redete der oberste Schenke zu Pharao und sprach: Ich gedenke heute an meine Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Da Pharao zornig ward fiber seine Knechte und mich mit dem obersten Backer ins Gefangnis legte, ins Hofmeisters Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'da traumete uns beiden in einer Nacht, einem jeglichen sein Traum, des Deutung ihn betraf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Da war bei uns ein ebraischer Jüngling, des Hofmeisters Knecht, dem erzahleten wifs. Und er deutete uns unsere Traume, einem jeglichen nach seinem Traum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und wie er uns deutete, so ist\'s ergangen; denn ich bin wieder an mein Amt gesetzt, und jener ist gehenkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sandte Pharao hin und lieft Joseph rufen; und lieften ihn eilend aus dem Loch. Und er lieft sich bescheren und zog andere Kleider an und kam hinein zu Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Da sprach Pharao zu ihm: Mir hat ein Traum getraumet, und ist niemand, der ihn deuten kann; ich hab aber gehort von dir sagen, wenn du einen T raum horest, so kannst du ihn deuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph antwortete Pharao und sprach: Das stehet bei mir nicht; Gott wird doch Pharao Gutes weissagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Pharao sagte an zu Joseph: Mir traumete, ich stund am Ufer bei dem Wasser');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'und sah aus dem Wasser steigen sieben schone fette Kühe, und gingen an der Weide im Grase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Und nach ihnen sah ich andere sieben dürre, sehr haftliche und magere Kühe heraussteigen. Ich habe in ganz Agyptenland nicht so haftliche gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Und die sieben mageren und haftlichen Kühe fraften auf die sieben ersten fetten Kühe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Und da sie die hineingefressen hatten, merkte man\'s nicht an ihnen, daß sie die gefressen hatten, und waren haftlich, gleichwie vorhin. Da wachte ich auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Und sah abermal in meinem Traum sieben Ahren auf einem Halm wachsen, voll und dick.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Danach gingen auf sieben dürre Ahren, dünne und versenget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Und die sieben dünnen Ahren verschlangen die sieben dicken Ahren. Und ich habe es den Wahrsagern gesagt, aber die konnen\'s mir nicht deuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Joseph antwortete Pharao: Beide Traume Pharaos sind einerlei. Denn Gott verkündigt Pharao, was er vorhat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben schonen Kühe sind sieben Jahre, und die sieben guten Ahren sind auch die sieben Jahre. Es ist einerlei Traum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Die sieben magern und haftlichen Kühe, die nach jenen aufgestiegen sind, das sind sieben Jahre; und die sieben mageren und versengeten Ahren sind sieben Jahre teure Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das ist nun, das ich gesagt habe zu Pharao, daß Gott Pharao zeiget, was er vorhat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Siehe, sieben reiche Jahre werden kommen in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Und nach denselben werden sieben Jahre teure Zeit kommen, daß man vergessen wird aller solcher Fulle in Agyptenland; und die teure Zeit wird das Land verzehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'daß man nichts wissen wird von der Fulle im Lande vor der teuren Zeit, die hernach kommt; denn sie wird fast schwer sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Daft aber dem Pharao zum andernmal getraumet hat, bedeutet, daß solches Gott gewiftlich und eilend tun wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nun sehe Pharao nach einem verstandigen und weisen Mann, den er uber Agyptenland setze,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'und schaffe, daß er Amtleute verordne im Lande und nehme den Funften in Agyptenland in den sieben reichen Jahren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'und sammle alle Speise der guten Jahre, die kommen werden, daß sie Getreide aufschutten in Pharaos Kornhauser zum Vorrat in den Stadten und verwahren es,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'auf daß man Speise verordnet finde dem Lande in den sieben teuren Jahren, die uber Agyptenland kommen werden, daß nicht das Land vor Hunger verderbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Die Rede gefiel Pharao und alien seinen Knechten wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und Pharao sprach zu seinen Knechten: Wie konnten wir einen solchen Mann finden, in dem der Geist Gottes sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Und sprach zu Joseph: Weil dir Gott solches alles hat kundgetan, ist keiner so verstandig und weise als du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst uber mein Haus sein, und deinem Wort soli all mein Volk gehorsam sein; alleine des koniglichen Stuhls will ich hoher sein denn du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Und weiter sprach Pharao zu Joseph: Siehe, ich habe dich uber ganz Agyptenland gesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Und tat seinen Ring von seiner Hand und gab ihn Joseph an seine Hand; und kleidete ihn mitweifter Seide und hing ihm eine guldene Kette an seinen Hals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Und lieft ihn auf seinem andern Wagen fahren und lieft vor ihm her ausrufen: Der ist des Landes Vater! Und setzte ihn uber ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und Pharao sprach zu Joseph: Ich bin Pharao; ohne deinen Willen soil niemand seine Hand Oder seinen Fuft regen in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und nannte ihn den heimlichen Rat. Und gab ihm ein Weib, Asnath, die Tochter Potipheras, des Priesters zu On. Also zog Joseph aus, das Land Agypten zu besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Und er war dreiftig Jahre alt, da er vor Pharao stund, dem Konige in Agypten; und fuhr aus von Pharao und zog durch ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Und das Land tat also die sieben reichen Jahre;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'und sammelten alle Speise der sieben Jahre, so im Lande Agypten waren, und taten sie in die Stadte. Was fur Speise auf dem Felde einer jeglichen Stadt umher wuchs, das taten sie hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Also schuttete Joseph das Getreide auf, uber die Mafte viel, wie Sand am Meer, also daß er aufhorete zu zahlen; denn man konnte es nicht zahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Und Joseph wurden zween Sohne geboren, ehe denn die teure Zeit kam, welche ihm gebar Asnath, Potipheras, des Priesters zu On Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und hieft den ersten Manasse; denn Gott, sprach er, hat mich lassen vergessen alles meines Unglucks und alles meines Vaters Hauses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Den andern hieft er Ephraim; denn Gott, sprach er, hat mich lassen wachsen in dem Lande meines Elends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Da nun die sieben reichen Jahre urn waren im Lande Agypten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'da fingen an die sieben teuren Jahre zu kommen, da Joseph von gesagt hatte. Und es ward eine Teurung in alien Landen, aber in ganz Agyptenland war Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Da nun das ganze Agyptenland auch Hunger litt, schrie das Volk zu Pharao urn Brot. Aber Pharao sprach zu alien Agyptern: Gehet hin zu Joseph; was euch der saget, das tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Als nun im ganzen Lande Teurung war, tat Joseph allenhalben Kornhauser auf und verkaufte den Agyptern. Denn die Teurung ward je langer je grafter im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Und alle Lande kamen in Agypten, zu kaufen bei Joseph; denn die Teurung war graft in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Da aber Jakob sah, daß Getreide in Agypten feil war, sprach er zu seinen Sohnen: Was sehet ihr euch lange urn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Siehe, ich hore, es sei in Agypten Getreide feil; ziehet hinab und kaufet uns Getreide, daß wir leben und nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Also zogen hinab zehn Bruder Josephs, daß sie in Agypten Getreide kauften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Aber Benjamin, Josephs Bruder, lieft Jakob nicht mit seinen Brudern ziehen; denn er sprach: Es mochte ihm ein Unfall begegnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Also kamen die Kinder Israels, Getreide zu kaufen, samt andern, die mit ihnen zogen, denn es war im Lande Kanaan auch teuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Aber Joseph war der Regent im Lande und verkaufte Getreide allem Volk im Lande. Da nun seine Bruder zu ihm kamen, fielen sie vor ihm nieder zur Erde auf ihr Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Und er sah sie an und kannte sie; und stellete sich fremd gegen sie und redete hart mit ihnen und sprach zu ihnen: Woher kommt ihr? Sie sprachen: Aus dem Lande Kanaan, Speise zu kaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Aberwiewohl ersie kannte, kannten sie ihn doch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Und Joseph gedachte an die Traume, die ihm von ihnen getraumet hatten, und sprach zu ihnen: Ihr, seid Kundschafter und seid kommen zu sehen, wo das Land often ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie antworteten ihm: Nein, mein Herr; deine Knechte sind kommen, Speise zu kaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir sind alle eines Mannes Sohne; wir sind redlich; und deine Knechte sind nie Kundschafter gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Er sprach zu ihnen: Nein, sondern ihr seid kommen zu besehen, wo das Land often ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie antworteten ihm: Wir, deine Knechte, sind zwolf Brüder, eines Mannes Sohne im Lande Kanaan, und derjungste ist noch bei unserm Vater; aberder eine ist nicht mehr vorhanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph sprach zu ihnen: Das ist\'s, das ich euch gesagt habe: Kundschafter seid ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran will ich euch prufen: bei dem Leben Pharaos, ihr sollt nicht von dannen kommen, es komme denn her euer jungster Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sendeteinen untereuch hin, dereuren Bruder hole; ihr aber sollt gefangen sein. Also will ich prufen eure Rede, ob ihr mit Wahrheit umgehet Oder nicht. Denn wo nicht, so seid ihr, bei dem Leben Pharaos, Kundschafter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und ließ sie beisammen verwahren drei Tage lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Am dritten Tage aber sprach er zu ihnen: Wollt ihr leben, so tut also; denn ich furchte Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Seid ihr redlich, so lasset eurer Bruder einen gebunden liegen in eurem Gefangnis; ihr aber ziehet hin und bringet heim, was ihr gekauft habt fur den Hunger,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'und bringet euren jungsten Bruder zu mir, so will ich euren Worten glauben, daß ihr nicht sterben müsset. Und sie taten also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Sie aber sprachen untereinander: Das haben wir an unserm Bruder verschuldet, dafi wir sahen die Angst seiner Seele, da er uns flehete, und wir wollten ihn nicht erhoren; darum kommt nun diese Trubsal uber uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben antwortete ihnen und sprach: Sagt\' ich\'s euch nicht, da ich sprach: Versundiget euch nicht an dem Knaben, und ihrwolltet nicht horen? Nun wird sein Blut gefordert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Sie wuliten aber nicht, daß es Joseph verstund; denn er redete mit ihnen durch einen Dolmetscher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Und er wandte sich von ihnen und weinete. Da er nun sich wieder zu ihnen wandte und mit ihnen redete, nahm eraus ihnen Simeon und band ihn vor ihren Augen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Und Joseph tat Befehl, daß man ihre Sacke mit Getreide fullete und ihr Geld wiedergabe, einem jeglichen in seinen Sack, dazu auch Zehrung auf den Weg. Und man tat ihnen also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Und sie luden ihre Ware auf ihre Esel und zogen von dannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Da aber einer seinen Sack auftat, daß er seinem Esel Futter gabe in der Herberge, ward er gewahr seines Geldes, das oben im Sacke lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Und sprach zu seinen Brudern: Mein Geld ist mir wieder worden; siehe, in meinem Sack ist es. Da entfiel ihnen ihr Herz und erschraken untereinander und sprachen: Warum hat uns Gott das getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Da sie nun heimkamen zu ihrem Vater Jakob ins Land Kanaan, sagten sie ihm alles, was ihnen begegnet war, und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Der Mann, der im Lande Herr ist, redete hart mit uns und hielt uns fur Kundschafter des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Und da wir ihm antworteten: Wir sind redlich und nie Kundschafter gewesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'sondern zwolf Bruder, unsers Vaters Sohne; einer ist nicht mehr vorhanden, und derjungste ist noch bei unserm Vater im Lande Kanaan:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'sprach der Herr im Lande zu uns: Daran will ich merken, ob ihr redlich seid: einen eurer Bruder lasset bei mir und nehmet die Notdurft fur euer Haus und ziehet hin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'und bringet euren jungsten Bruder zu mir, so merke ich, dafi ihr nicht Kundschafter, sondern redlich seid; so will ich euch auch euren Bruder geben, und moget im Lande werben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Und da sie die Sacke ausschutteten, fand ein jeglichersein Bundlein Geld in seinem Sacke. Und da sie sahen, daß es Bundlein ihres Geldes waren, erschraken sie samt ihrem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Da sprach Jakob, ihr Vater, zu ihnen: Ihr beraubet mich meiner Kinder: Joseph ist nicht mehr vorhanden, Simeon ist nicht mehr vorhanden, Benjamin wollt ihr hinnehmen; es gehet alles uber mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben antwortete seinem Vater und sprach: Wenn ich dir ihn nicht wiederbringe, so erwürge meine zween Sohne; gib ihn nur in meine Hand, ich will ihn dirwiederbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er sprach: Mein Sohn soil nicht mit euch hinabziehen, denn sein Bruder ist tot, und er ist allein uberblieben; wenn ihm ein Unfall auf dem Wege begegnete, da ihr auf reiset, wurdet ihr meine grauen Haare mit Herzeleid in die Grube bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Die Teurung aber drückte das Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Und da es verzehret war, was sie fur Getreide aus Agypten gebracht hatten, sprach ihr Vater zu ihnen: Ziehet wieder hin und kaufet uns ein wenig Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Da antwortete ihm Juda und sprach: Der Mann band uns das hart ein und sprach: Ihr sollt mein Angesicht nicht sehen, es sei denn euer Bruder mit euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ist\'s nun, dafi du unsern Bruder mit uns sendest, so wollen wir hinabziehen und dir zu essen kaufen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'ist\'s aber, daß du ihn nicht sendest, so ziehen wir nicht hinab. Denn der Mann hat gesagt zu uns: Ihr sollt mein Angesicht nicht sehen, euer Bruder sei denn mit euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sprach: Warum habt ihr so ubel an mir getan, daß ihr dem Manne angesagt, wie ihr noch einen Bruder habt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Sie antworteten: Der Mann forschete so genau nach uns und unserer Freundschaft und sprach: Lebet euer Vater noch? Habt ihr auch noch einen Bruder? Da sagten wir ihm, wie er uns fragte. Wie konnten wir soeben wissen, dafi er sagen würde: Bringet euren Bruder mit hernieder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Da sprach Juda zu Israel, seinem Vater: Laß, den Knaben mit mir ziehen, daß wir uns aufmachen und reisen, und leben und nicht sterben, beide wir und du und unsere Kindlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich will Burge fur ihn sein; von meinen Handen sollst du ihn fordern. Wenn ich dir ihn nicht wiederbringe und vor deine Augen stelle, so will ich mein Leben lang die Schuld tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Denn wo wir nicht hatten verzogen, waren wir schon wohi zweimal wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da sprach Israel, ihr Vater, zu ihnen: Muft es denn ja also sein, so tut\'s und nehmet von des Landes besten Fruchten in eure Sacke und bringet dem Manne Geschenke hinab, ein wenig Balsam und Honig und Wurze und Myrrhen und Datteln und Mandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Nehmet auch ander Geld mit euch; und das Geld, das euch oben in euren Sacken wieder worden ist, bringet auch wieder mit euch. Vielleicht ist ein Irrtum da geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Dazu nehmet euren Bruder, machet euch auf und kommet wieder zu dem Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Aber der allmachtige Gottgebe euch Barmherzigkeit vor dem Manne, dati er euch lasse euren andern Bruder und Benjamin. Ich aber muft sein wie einer, der seiner Kinder gar beraubt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Da nahmen sie diese Geschenke und das Geld zwiefaltig mit sich und Benjamin, machten sich auf, zogen nach Agypten und traten vor Joseph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Da sah sie Joseph mit Benjamin und sprach zu seinem Haushalter: Führe diese Manner zu Hause und schlachte und richte zu; denn sie sollen zu Mittag mit mir essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Und der Mann tat, wie ihm Joseph gesagt hatte, und fuhrete die Manner in Josephs Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Sie furchteten sich aber, daß sie in Josephs Haus gefuhrt wurden, und sprachen: Wir sind hereingefuhrt urn des Geldes willen, das wir in unsern Sacken vorhin wieder funden haben, dati er\'s auf uns bringe und falle ein Urteil uber uns, damit er uns nehme zu eigenen Knechten samt unsern Eseln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Darum traten sie zu Josephs Haushalter und redeten mit ihm vor der Haustur');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'und sprachen: Mein Herr, wir sind vorhin herabgezogen, Speise zu kaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Und da wir in die Herberge kamen und unsere Sacke auftaten, siehe, da war eines jeglichen Geld oben in seinem Sack mit volligem Gewicht; darum haben wir\'s wieder mit uns gebracht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'haben auch ander Geld mit uns herabgebracht, Speise zu kaufen; wir wissen aber nicht, wer uns unser Geld in unsere Sacke gesteckt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Er aber sprach: Gehabt euch wohi, furchtet euch nicht. Euer Gott und eures Vaters Gott hat euch einen Schatz gegeben in eure Sacke. Euer Geld ist mir worden. Und er fuhrete Simeon zu ihnen heraus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'und fuhrete sie in Josephs Haus, gab ihnen Wasser, daß sie ihre Füfte wuschen, und gab ihren Eseln Futter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Sie aber bereiteten das Geschenk zu, bis daß Joseph kam auf den Mittag; denn sie hatten gehoret, daß sie daselbst das Brot essen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Da nun Joseph zum Hause einging, brachten sie ihm zu Hause das Geschenk in ihren Handen und fielen vor ihm nieder zur Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Er aber grüftte sie freundlich und sprach: Gehet es eurem Vater, dem alten, wohi, von dem ihr mir sagtet? Lebet er noch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Sie antworteten: Es gehet deinem Knechte, unserm Vater, wohi und lebet noch. Und neigeten sich und fielen vor ihm nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Und er hub seine Augen auf und sah seinen Bruder Benjamin, seiner Mutter Sohn, und sprach: Ist das euer jungster Bruder, da ihr mir von sagtet? Und sprach weiter: Gott sei dir gnadig, mein Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Und Joseph eilete, denn sein Herz entbrannte ihm gegen seinen Bruder, und suchte, wo er weinete; und ging in seine Kammer und weinete daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Und da er sein Angesicht gewaschen hatte, ging er heraus und hielt sich fest und sprach: Leget Brot auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Und man trug ihm besonders auf und jenen auch besonders und den Agyptern, die mit ihm aften, auch besonders. Denn die Agypter dürfen nicht Brot essen mit den Ebraern, denn es ist ein Greuel vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Und man setzte sie gegen ihn, den Erstgebornen nach seiner Erstgeburt und den Jungsten nach seiner Jugend. Des verwunderten sie sich untereinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Und man trug ihnen Essen vor von seinem Tisch; aber dem Benjamin ward fünfmal mehr denn den andern. Und sie tranken und wurden trunken mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Und Joseph befahl seinem Haushalter und sprach: Fülle den Mannern ihre Sacke mit Speise, soviel sie führen mogen, und lege jeglichem sein Geld oben in seinen Sack.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Und meinen silbernen Becher lege oben in des Jungsten Sack mit dem Geld fur das Getreide. Der tat, wie ihm Joseph hatte gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Des Morgens, da es licht ward, liefien sie die Manner ziehen mit ihren Eseln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Da sie aber zur Stadt hinaus waren und nicht feme kommen, sprach Joseph zu seinem Haushalter: Auf, und jage den Mannern nach, und wenn du sie ergreifest, so sprich zu ihnen: Warum habt ihr Gutes mit Bosem vergolten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist\'s nicht das, da mein Herr aus trinket und damit er weissaget? Ihr habt ubel getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Und als er sie ergriff, redete er mit ihnen solche Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Sie antworteten ihm: Warum redet mein Herr solche Worte? Es sei feme von deinen Knechten, ein solches zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Siehe, das Geld, das wir fanden oben in unsern Sacken, haben wir wiedergebracht zu dir aus dem Lande Kanaan. Und wie sollten wir denn aus deines Herrn Hause gestohlen haben Silber Oder Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei welchem er funden wird unter deinen Knechten, der sei des Todes; dazu wollen auch wir meines Herrn Knechte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Er sprach: Ja, es sei, wie ihr geredet habt. Bei welchem er funden wird, der sei mein Knecht; ihr aber sollt iedig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Und sie eileten, und legte ein jeglicher seinen Sack ab auf die Erde und ein jeglicher tat seinen Sack auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Und er suchte und hub am Groliesten an bis auf den Jungsten; da fand sich der Becher in Benjamins Sack.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da zerrissen sie ihre Kleider; und lud ein jeglicher auf seinen Esel und zogen wieder in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und Juda ging mit seinen Brudern in Josephs Haus, denn er war noch daselbst; und sie Helen vor ihm nieder auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph aber sprach zu ihnen: Wie habt ihr das tun dürfen? Wisset ihr nicht, daß ein solcher Mann, wie ich bin, erraten konnte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juda sprach: Was sollen wirsagen meinem Herrn, Oder wie sollen wir reden, und was konnen wir uns rechtfertigen? Gott hat die Missetat deiner Knechte funden. Siehe da, wir und der, bei dem der Becher funden ist, sind meines Herrn Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Er aber sprach: Das sei feme von mir solches zu tun! Der Mann, bei dem der Becher funden ist, soil mein Knecht sein; ihr aber ziehet hinauf mit Frieden zu eurem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da trat Juda zu ihm und sprach: Mein Herr, laft deinen Knecht ein Wort reden vor deinen Ohren, mein Herr; und dein Zorn ergrimme nicht uber deinen Knecht; denn du bist wie ein Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herrfragte seine Knechte und sprach: Habt ihr auch einen Vater Oder Bruder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da antworteten wir: Wir haben einen Vater, der ist alt, und einen jungen Knaben, in seinem Alter geboren; und sein Bruder ist tot, und er ist allein uberblieben von seiner Mutter, und sein Vater hat ihn lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Da sprachst du zu deinen Knechten: Bringet ihn herab zu mir; ich will ihm Gnade erzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Wir aber antworteten meinem Herrn: Der Knabe kann nicht von seinem Vater kommen; wo er von ihm kame, würde er sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Da sprachst du zu deinen Knechten: Wo euer jungster Bruder nicht mit euch herkommt, sollt ihr mein Angesicht nicht mehr sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Da zogen wir hinauf zu deinem Knechte, meinem Vater, und sagten ihm an meines Herrn Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Da sprach unser Vater: Ziehet wieder hin und kaufet uns ein wenig Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Wir aber sprachen: Wir konnen nicht hinabziehen, es sei denn unser jungster Bruder mit uns, so wollen wir hinabziehen; denn wir konnen des Mannes Angesicht nicht sehen, wo unser jungster Bruder nicht mit uns ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Da sprach dein Knecht, mein Vater, zu uns: Ihr wisset, daß mir mein Weib zween Sohne geboren hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Einer ging hinaus von mir, und man sagte, er ist zerrissen; und habe ihn nicht gesehen bisher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Werdet ihr diesen auch von mir nehmen, und ihm ein Unfall widerfahret, so werdet ihr meine grauen Haare mit Jammer hinunter in die Grube bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Nun, so ich heimkame zu deinem Knechte, meinem Vater, und der Knabe ware nicht mit uns, weil seine Seele an dieses Seele hanget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'so wird\'s geschehen, wenn er siehet, daß der Knabe nicht da ist, daß er stirbt; so würden wir, deine Knechte, die grauen Haare deines Knechts; unsers Vaters, mit Herzeleid in die Grube bringen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn ich, dein Knecht, bin Burge worden fur den Knaben gegen meinen Vater und sprach: Bringe ich ihn dir nicht wieder, so will ich mein Leben lang die Schuld tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Darum laft deinen Knecht hie bleiben an des Knaben Statt, zum Knechte meines Herrn, und den Knaben mit seinen Brudern hinaufziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie soil ich hinaufziehen zu meinem Vater, wenn der Knabe nicht mit mir ist? Ich wurde den Jammer sehen müssen, der meinem Vater begegnen würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da konnte sich Joseph nicht langer enthalten vor alien, die urn ihn her stunden, und er rief: Lasset jedermann von mir hinausgehen! Und stund kein Mensch bei ihm, da sich Joseph mit seinen Brudern bekannte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Und er weinete laut, dal J es die Agypter und das Gesinde Pharaos horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'und sprach zu seinen Brudern: Ich bin Joseph. Lebet mein Vater noch? Und seine Brüder konnten ihm nicht antworten, so erschraken sie vor seinem Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Er sprach aber zu seinen Brudern: Tretet doch her zu mir! Und sie traten herzu. Und er sprach: ich bin Joseph, euer Bruder, den ihr in Agypten verkauft habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Und nun bekümmert euch nicht und denket nicht, daß ich darum zurne, dad ihr mich hieher verkauft habt; denn um eures Lebens wülen hat mich Gott vor euch hergesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Denn dies sind zwei Jahre, dad es teuer im Lande ist, und sind noch fünf Jahre, dad kein Pflugen noch Ernten sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Aber Gott hat mich vor euch hergesandt, dad er euch übrig behalte auf Erden und euer Leben errette durch eine grade Errettung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Und nun, ihr habt mich nicht hergesandt, sondern Gott, der hat mich Pharao zum Vater gesetzt und zum Herrn über all sein Haus und einen Fursten in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Eilet nun und ziehet hinauf zu meinem Vater und saget ihm: Das ladt dir Joseph, dein Sohn, sagen: Gott hat mich zum Herrn in ganz Agypten gesetzet; komm herab zu mir, saume dich nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du sollstim Lande Gosen wohnen und nahe bei mir sein, du und deine Kinder und deine Kindeskinder, dein klein und grod Vieh und alles, was du hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ich will dich daselbst versorgen; denn es sind noch fünf Jahre der Teurung; auf dad du nicht verderbest mit deinem Hause und allem, das du hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Siehe, eure Augen sehen, und die Augen meines Bruders Benjamin, dad ich mundlich mit euch rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Verkundiget meinem Vater alle meine Herrlichkeit in Agypten und alles, was ihr gesehen habt; eilet und kommt hernieder mit meinem Vater hieher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und erfiel seinem Bruder Benjamin um den Hals und weinete; und Benjamin weinete auch an seinem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Und küssete alle seine Bruder und weinete über sie. Danach redeten seine Brüder mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und da das Geschrei kam in Pharaos Haus, dad Josephs Bruder kommen waren, gefiel es Pharao wohl und alien seinen Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Und Pharao sprach zu Joseph: Sage deinen Brüdern: Tut ihm also, beladet eure Tiere, ziehet hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'und wenn ihr kommt ins Land Kanaan, so nehmet euren Vater und euer Gesinde und kommt zu mir; ich will euch Güter geben in Agyptenland, dad ihr essen sollt das Mark im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Und gebeut ihnen: Tut ihm also, nehmet zu euch aus Agyptenland Wagen zu euren Kindern und Weibern und führet euren Vater und kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Und sehet euren Hausrat nicht an, denn die Güter des ganzen Landes Agypten sollen euer sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Die Kinder Israels taten also. Und Joseph gab ihnen Wagen nach dem Befehl Pharaos und Zehrung auf den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Und gab ihnen alien, einem jeglichen, ein Feierkleid; aber Benjamin gab er dreihundert Silberlinge und fünf Feierkleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Und seinem Vater sandte er dabei zehn Esel, mit Gut aus Agypten beladen, und zehn Eselinnen mit Getreide und Brat und Speise seinem Vater auf den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Also ließ er seine Brüder, und sie zogen hin; und sprach zu ihnen: Zanket nicht auf dem Wege!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Also zogen sie hinauf von Agypten und kamen ins Land Kanaan zu ihrem Vater Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Und verkündigten ihm und sprachen: Joseph lebet noch und ist ein Herr im ganzen Agyptenlande. Aber sein Herz dachte gar viel anders, denn er glaubte ihnen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Da sagten sie ihm alle Worte Josephs, die er zu ihnen gesagt hatte. Und da er sah die Wagen, die ihm Joseph gesandt hatte, ihn zufuhren, ward der Geist Jakobs, ihres Vaters, lebendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Und Israel sprach: Ich habe genug, daß mein Sohn Joseph noch lebet; ich will hin und ihn sehen, ehe ich sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel zog hin mit allem, das er hatte. Und da er gen Bersaba kam, opferte er Opfer dem Gott seines Vaters Isaak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Und Gott sprach zu ihm des Nachts im Gesicht: Jakob, Jakob! Er sprach: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Und er sprach: Ich bin Gott, der Gott deines Vaters; furchte dich nicht, nach Agypten hinabzuziehen, denn daselbst will ich dich zum großen Volk machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich will mit dir hinab nach Agypten ziehen und will auch dich herauffuhren; und Joseph soil seine Hande auf deine Augen legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Da machte sich Jakob auf von Bersaba; und die Kinder Israels führeten Jakob, ihren Vater, mit ihren Kindlein und Weibern auf den Wagen, die Pharao gesandt hatte, ihn zu fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und nahmen ihr Vieh und Habe, die sie im Lande Kanaan erworben hatten, und kamen also in Agypten, Jakob und all sein Same mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Seine Kinder und seine Kindeskinder mit ihm, seine Tochter und seine Kindestochter und all sein Same, die brachte er mit sich nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Dies sind die Namen der Kinder Israels, die nach Agypten kamen: Jakob und seine Sohne. Der erstgeborne Jakobs Sohn, Ruben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Die Kinder Rubens: Hanoch, Pallu Hezron und Charmi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Die Kinder Simeons: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn von dem kanaanaischen Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Die Kinder Levis: Gerson, Kahath und Merari.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Die Kinder Judas: Ger, Onan, Sela, Perez und Serah. Aber Ger und Onan waren gestorben im Lande Kanaan. Die Kinder aber Perez: Hezron und Hamul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Die Kinder Isaschars: Thola, Phua, Job und Simron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Die Kinder Sebulons: Sered, Elon und Jahleel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Das sind die Kinder von Lea, diesie Jakob gebar in Mesopotamien, mit seiner Tochter Dina. Die machen aliesamt mit Sohnen und Tochtern dreiunddreüüg Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Die Kinder Gads: Ziphion, Haggi, Suni, Ezbon, Eri, Modi und Areli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Die Kinder Assers: Jemna, Jesua, Jesui, Bria und Serah, ihre Schwester. Aber die Kinder Brias: Heber und Malchiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Das sind die Kinder von Silpa, die Laban gab Lea, seiner Tochter, und gebar Jakob diese sechzehn Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Kinder Rahels, Jakobs Weibes: Joseph und Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Und Joseph wurden geboren in Agyptenland Manasse und Ephraim, die ihm gebar Asnath, die Tochter Potipheras, des Priesters zu On.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Die Kinder Benjamins: Bela, Becher, Asbel, Gera, Naaman, Ehi, Ros, Muppim, Huppim und Ard.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Das sind die Kinder von Rahel, die Jakob geboren sind; aliesamt vierzehn Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Die Kinder Dans: Husim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Die Kinder Naphthalis: Jahzeel, Guni, Jezer und Sillem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Das sind die Kinder Bilhas, die Laban seiner Tochter Rahel gab, und gebar Jakob die sieben Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle Seelen, die mit Jakob nach Agypten kamen, die aus seinen Lenden kommen waren (ausgenommen die Weiber seiner Kinder), sind alle zusammen sechsundsechzig Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und die Kinder Josephs, die in Agypten geboren sind, waren zwo Seelen, also daß alle Seelen des Hauses Jakobs, die nach Agypten kamen, waren siebenzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Und er sandte Juda vor ihm hin zu Joseph, dafi er ihn anweisete zu Gosen. Und kamen in das Land Gosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Da spannete Joseph seinen Wagen an und zog hinauf seinem Vater Israel entgegen gen Gosen. Und da er ihn sah, fiel er ihm urn seinen Hals und weinete lange an seinem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Da sprach Israel zu Joseph: Ich will nun gerne sterben, nachdem ich dein Angesicht gesehen habe, daß du noch lebest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Joseph sprach zu seinen Brudern und zu seines Vaters Hause: Ich will hinaufziehen und Pharao ansagen und zu ihm sprechen: Meine Bruder und meines Vaters Haus ist zu mir kommen aus dem Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Und sind Viehhirten, denn es sind Leute, die mit Vieh umgehen; ihr klein und groß Vieh und alles, was sie haben, haben sie mitgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Wenn euch nun Pharao wird rufen und sagen: Was ist eure Nahrung?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'so sollt ihr sagen: Deine Knechte sind Leute, die mit Vieh umgehen, von unserer Jugend auf bisher, beide wir und unsere Vater, auf daß ihr wohnen moget im Lande Gosen. Denn was Viehhirten sind, das ist den Agyptern ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Da kam Joseph und sagte es Pharao an und sprach: Mein Vater und meine Bruder, ihr klein und graft Vieh und alles, was sie haben, sind kommen aus dem Lande Kanaan; und siehe, sie sind im Lande Gosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Und er nahm seiner jungsten Bruder funf und stellete sie vor Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Da sprach Pharao zu seinen Brudern: Was ist eure Nahrung? Sie antworteten: Deine Knechte sind Viehhirten, wir und unsere Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Und sagten weiterzu Pharao: Wir sind kommen, bei euch zu wohnen im Lande; denn deine Knechte haben nicht Weide fur ihr Vieh, so hart drucket die Teurung das Land Kanaan; so lafi doch nun deine Knechte im Lande Gosen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Pharao sprach zu Joseph: Es ist dein Vater und sind deine Bruder, die sind zu dir kommen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'das Land Agypten stehet dir often; laft sie am besten Ort des Landes wohnen, laft sie im Lande Gosen wohnen; und so du weiftest, daß Leute unter ihnen sind, die tuchtig sind, so setze sie uber mein Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Joseph brachte auch seinen Vater Jakob hinein und stellete ihn vor Pharao. Und Jakob segnete den Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Pharao aber fragte Jakob: Wie alt bist du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob sprach zu Pharao: Die Zeit meiner Wallfahrt ist hundertunddreiftig Jahre; wenig und bose ist die Zeit meines Lebens und langet nicht an die Zeit meiner Vater in ihrer Wallfahrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Und Jakob segnete den Pharao und ging heraus von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Aber Joseph schaffte seinem Vater und seinen Brudern Wohnung und gab ihnen ein Gut in Agyptenland am besten Ort des Landes, namlich im Lande Raemses, wie Pharao geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und er versorgte seinen Vater und seine Bruder und das ganze Haus seines Vaters, einen jeglichen, nachdem er Kinder hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Es war aber kein Brot in alien Landen; denn die Teurung war fast schwer, daß das Land Agypten und Kanaan verschmachteten vor der Teurung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Und Joseph brachte alles Geld zusammen, das in Agypten und Kanaan funden ward um das Getreide, das sie kauften; und Joseph tat alles Geld in das Haus Pharaos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Da nun Geld gebrach im Lande Agypten und Kanaan, kamen alle Agypter zu Joseph und sprachen: Schaffe uns Brot! Warum lassest du uns vor dir sterben, darum daü wir ohne Geld sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sprach: Schaffet euer Vieh her, so will ich euch um das Vieh geben, weil ihr ohne Geld seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Da brachten sie Joseph ihr Vieh; und ergab ihnen Brot um ihre Pferde, Schafe, Rinder und Esel. Also ernahrete er sie mit Brot das Jahr um all ihr Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Da das Jahr um war, kamen sie zu ihm im andern Jahr und sprachen zu ihm: Wir wollen unserm Herrn nicht verbergen, daß nicht allein das Geld, sondern auch alles Vieh dahin ist zu unserm Herrn und ist nichts mehr ubrig vor unserm Herrn denn nur unsere Leiber und unser Feld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum lassest du uns vor dir sterben und unser Feld? Kaufe uns und unser Land urns Brot, daß wir und unser Land leibeigen seien dem Pharao; gib uns Samen, daß wir leben und nicht sterben, und das Feld nicht verwuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Also kaufte Joseph dem Pharao das ganze Agypten. Denn die Agypter verkauften ein jeglicher seinen Acker, denn die Teurung war zu stark uber sie. Und ward also das Land Pharao eigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Und er teilete das Volk aus in die Stadte, von einem Ort Agyptens bis ans andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Ausgenommen der Priester Feld, das kaufte er nicht; denn es war von Pharao fur die Priester verordnet, daß sie sich nahren sollten von dem Benannten, das er ihnen gegeben hatte; darum durften sie ihr Feld nicht verkaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Da sprach Joseph zu dem Volk: Siehe, ich habe heute gekauft euch und euer Feld dem Pharao; siehe, da habt ihr Samen und besaet das Feld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Und von dem Getreide sollt ihr den Funften Pharao geben; vier Teile sollen euer sein, zu besaen das Feld, zu eurer Speise und fur euer Haus und Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Sie sprachen: Laß uns nur leben und Gnade vor dir, unserm Herrn, finden; wir wollen gerne Pharao leibeigen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Also machte Joseph ihnen ein Gesetz bis auf diesen Tag uber der Agypter Feld, den Funften Pharao zu geben; ausgenommen der Priester Feld, das ward nicht eigen Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Also wohnete Israel in Agypten, im Lande Gosen, und hatten es inne und wuchsen und mehreten sich sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte siebenzehn Jahre in Agyptenland, daß sein ganzes Alter ward hundertundsiebenundvierzig Jahre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Da nun die Zeit herbeikam, daß Israel sterben sollte, rief er seinem Sohn Joseph und sprach zu ihm: Habe ich Gnade vor dir funden, so lege deine Hand unter meine Hufte, daß du die Liebe und Treue an mir tust und begrabest mich nicht, in Agypten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sondern ich will liegen bei meinen Vatern, und du sollst mich aus Agypten fuhren und in ihrem Begrabnis begraben. Er sprach: Ich will tun, wie du gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Er aber sprach: So schwore mir! Und er schwur ihm. Da neigete sich Israel auf dem Bette zu den Haupten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Danach ward Joseph gesagt: Siehe, dein Vater ist krank. Und er nahm mit sich seine beiden Sohne, Manasse und Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Da ward es Jakob angesagt: Siehe, dein Sohn Joseph kommt zu dir. Und Israel machte sich stark und setzte sich im Bette');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'und sprach zu Joseph: Der allmachtige Gott erschien mirzu Lus, im Lande Kanaan, und segnete mich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'und sprach zu mir: Siehe, ich will dich wachsen lassen und mehren und will dich zum Haufen Volks machen; und will dies Land zu eigen geben deinem Samen nach direwiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'So sollen nun deine zween Sohne, Ephraim und Manasse, die dirgeboren sind in Agyptenland, ehe ich hereinkommen bin zu dir, mein sein, gleichwie Ruben und Simeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Welche du aber nach ihnen zeugest, sollen dein sein und genannt werden wie ihre Bruder in ihrem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Und da ich aus Mesopotamien kam, starb mir Rahel im Lande Kanaan auf dem Wege, da noch ein Feldwegs war gen Ephrath; und ich begrub sie daselbst an dem Wege Ephrath, die nun Bethlehem heißt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Und Israel sah die Sohne Josephs und sprach: Wersind die?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joseph antwortete seinem Vater: Es sind meine Sohne, die mir Gott hie gegeben hat. Er sprach: Bringe sie her zu mir, daß ich sie segne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Denn die Augen Israels waren dunkel worden vor Alter und konnte nicht wohl sehen. Und er brachte sie zu ihm. Er aber kussete sie und herzete sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'und sprach zu Joseph: Siehe, ich habe dein Angesicht gesehen, des ich nicht gedacht hatte; und siehe, Gott hat mich auch deinen Samen sehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Und Joseph nahm sie von seinem Schoß und neigete sich zur Erde gegen sein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Da nahm sie Joseph beide, Ephraim in seine rechte Hand gegen Israels linke Hand und Manasse in seine linke Hand gegen Israels rechte Hand, und brachte siezu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Aber Israel streckte seine rechte Hand aus und legte sie auf Ephraims, des Jungsten, Haupt und seine linke auf Manasses Haupt; und tat wissend also mit seinen Handen, denn Manasse war der Erstgeborne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Und er segnete Joseph und sprach: Gott, vor dem meine Vater, Abraham und Isaak, gewandelt haben, Gott, der mich mein Leben lang ernahret hat bis auf diesen Tag,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'der Engel, der mich erloset hat von allem libel, der segne die Knaben, daß sie nach meinem und nach meiner Vater, Abrahams und Isaaks, Namen genannt werden, daß sie wachsen und viel werden auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Da aber Joseph sah, daß sein Vater die rechte Hand auf Ephraims Haupt legte, gefiel es ihm übel; und fassete seines Vaters Hand, daß er sie von Ephraims Haupt auf Manasses Haupt wendete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'und sprach zu ihm: Nicht so, mein Vater; dieser ist der Erstgeborene, lege deine rechte Hand auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Aber sein Vater weigerte sich und sprach: Ich weili wohl, mein Sohn, ich weift wohl. Dieser soil auch ein Volk werden und wird graft sein; aber sein jungster Bruderwird grafter, denn er, werden, und sein Same wird ein graft Volk werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Also segnete er sie des Tages und sprach: Wer in Israel will jemand segnen, der sage: Gott setze dich wie Ephraim und Manasse! Und setzte also Ephraim Manasse vor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Und Israel sprach zu Joseph: Siehe, ich sterbe; und Gott wird mit euch sein und wird euch wiederbringen in das Land eurer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ich habe dir ein Stuck Landes gegeben aufter deinen Brüdem, das ich mit meinem Schwert und Bogen aus der Hand der Amoriter genommen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Und Jakob berief seine Sohne und sprach: Versammelt euch, daß ich euch verkundige, was euch begegnen wird in kunftigen Zeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommt zuhauf und horet zu, ihr Kinder Jakobs, und horet euren Vater Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, mein erster Sohn, du bist meine Kraft und meine erste Macht, der Oberste im Opfer und der Oberste im Reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Er fuhr leichtfertig dahin wie Wasser. Du sollst nicht der Oberste sein; denn du bist auf deines Vaters Lager gestiegen, daselbst hast du mein Bett besudelt mit dem Aufsteigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Die Bruder Simeon und Levi ihre Schwerter sind morderische Waffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Meine Seele komme nicht in ihren Rat, und meine Ehre sei nicht in ihrer Kirche; denn in ihrem Zorn haben sie den Mann erwurget und in ihrem Mutwillen haben sie den Ochsen verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, daß er so heftig ist, und ihr Grimm, daß er so storrig ist! Ich will sie zerteilen in Jakob und zerstreuen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, du bist\'s, dich werden deine Bruder loben. Deine Hand wird deinen Feinden auf dem Halse sein; vor dir werden deines Vaters Kinder sich neigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juda ist ein junger Lowe. Du bist hoch kommen, mein Sohn, durch grofte Siege. Er hat niedergekniet und sich gelagert wie ein Lowe und wie eine Lowin; wer will sich wider ihn auflehnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Es wird das Zepter von Juda nicht entwendet werden, noch ein Meister von seinen Füften, bis daß der Held komme; und demselben werden die Volker anhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er wird sein Füllen an den Weinstock binden und seiner Eselin Sohn an den edlen Reben. Erwird sein Kleid in Wein waschen und seinen Mantel in Weinbeerblut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Seine Augen sind rotlicher denn Wein und seine Zahne weifter denn Milch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wird an der Anfurt des Meers wohnen und an der Anfurt der Schiffe und reichen an Sidon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isascharwird ein beinerner Esel sein und sich lagern zwischen die Grenzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Und ersah die Ruhe, daß sie gut ist, und das Land, daß es lustig ist; er hat aber seine Schultern geneiget zu tragen, und ist ein zinsbarer Knecht worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird Richter sein in seinem Volk, wie ein ander Geschlecht in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange werden auf dem Wege und eine Otter auf dem Steige und das Pferd in die Ferse beiften, daß sein Reiter zuruckfalle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'HERR, ich warte auf dein Heil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, gerustet, wird das Heer fuhren und wieder herumfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Von Asser kommt sein fett Brot, und erwird den Konigen zu Gefallen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali ist ein schneller Hirsch und gibt schone Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph wird wachsen, er wird wachsen wie an einer Quelle. Die Tochter treten einher im Regiment.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Und wiewohl ihn die Schutzen erzurnen und wider ihn kriegen und ihn verfolgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'so bleibt doch sein Bogen fest und die Arme seiner Hande stark durch die Hande des Machtigen in Jakob. Aus ihnen sind kommen Hirten und Steine in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Von deines Vaters Gott ist dir geholfen, und von dem Allmachtigen bist du gesegnet mit Segen oben vom Himmel herab, mit Segen von der Tiefe, die unten liegt, mit Segen an Brusten und Bauchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segen deines Vaters gehen starker denn die Segen meiner Voreltern, nach Wunsch der Hohen in der Welt; und sollen kommen auf das Haupt Josephs und auf die Scheitel des Nasir unter seinen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein reiftender Wolf; des Morgens wird er Raub fressen, aber des Abends wird er den Raub austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Das sind die zwolf Stamme Israels alle, und das ist\'s, das ihr Vater mit ihnen geredet hat, da er sie segnete, einen jeglichen mit einem sondern Segen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gebot ihnen und sprach zu ihnen: Ich werde versammelt zu meinem Volk; begrabet mich bei meine Vater in der Hohle auf dem Acker Ephrons, des Hethiters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'in der zwiefachen Hohle, die gegen Mamre liegt, im Lande Kanaan, die Abraham kaufte, samt dem Acker, von Ephron, dem Hethiter, zum Erbbegrabnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Daselbst haben sie Abraham begraben und Sara, sein Weib. Daselbst haben sie auch Isaak begraben und Rebekka, sein Weib. Daselbst habe ich auch Lea begraben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'in dem Acker und der Hohle, die von den Kindern Heths gekauft ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Und da Jakob vollendet hatte die Gebote an seine Kinder, tat er seine Fülte zusammen aufs Bett und verschied und ward versammelt zu seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Da fiel Joseph auf seines Vaters Angesicht und weinete uber ihm und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Und Joseph befahl seinen Knechten, den Arzten, daß sie seinen Vater salbeten. Und die Arzte salbeten Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'bis daß vierzig Tage urn waren; denn so lange wahren die Salbetage. Und die Agypter beweineten ihn siebenzig Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Da nun die Leidetage aus waren, redete Joseph mit Pharaos Gesinde und sprach: Habe ich Gnade vor euch funden, so redet mit Pharao und sprechet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat einen Eid von mir genommen und gesagt: Siehe, ich sterbe; begrabe mich in meinem Grabe, das ich mir im Lande Kanaan gegraben habe. So will ich nun hinaufziehen und meinen Vater begraben und wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Pharao sprach: Zeuch hinauf und begrabe deinen Vater, wie du ihm geschworen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Also zog Joseph hinauf, seinen Vater zu begraben. Und es zogen mit ihm alle Knechte Pharaos, die Altesten seines Hauses und alle Altesten des Landes Agypten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'dazu das ganze Gesinde Josephs und seine Bruder und das Gesinde seines Vaters. Alleine ihre Kinder, Schafe und Ochsen lief Jen sie im Lande Gosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Und zogen auch mit ihm hinauf Wagen und Reisige, und waren ein fast grolies Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Da sie nun an die Tenne Atad kamen, die jenseit des Jordans liegt, da hielten sie eine sehr grolie und bittere Klage; und er trug uber seinen Vater Leid sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Und da die Leute im Lande, die Kanaaniter, die Klage bei der Tenne Atad sahen, sprachen sie: Die Agypter halten da große Klage. Daher heü Jt man den Ort der Agypter Klage, welcher liegt jenseit des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Und seine Kinder taten, wie er ihnen befohlen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'und führeten ihn ins Land Kanaan und begruben ihn in der zwiefachen Hohle des Ackers, die Abraham erkauft hatte mit dem Acker zum Erbbegrabnis von Ephron, dem Hethiter, gegen Mamre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Als sie ihn nun begraben hatten, zog Joseph wieder nach Agypten mit seinen Brudern und mit alien, die mit ihm hinaufgezogen waren, seinen Vater zu begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Die Bruder Josephs aber furchteten sich, da ihr Vater gestorben war, und sprachen: Joseph mochte uns gram sein und vergelten alle Bosheit, die wir an ihm getan haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Darum liei Jen sie ihm sagen: Dein Vater befahl vor seinem Tode und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Also sollt ihr Joseph sagen: Lieber, vergib deinen Brudern die Missetat und ihre Sünde, dal J sie so ubel an dir getan haben. Lieber, so vergib nun die Missetat uns, den Dienern des Gottes deines Vaters! Aber Joseph weinete, da sie solches mit ihm redeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Und seine Bruder gingen hin und fielen vor ihm nieder und sprachen: Siehe, wir sind deine Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph sprach zu ihnen: Furchtet euch nicht, denn ich bin unter Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr gedachtet es bose mit mir zu machen; aber Gott gedachte es gut zu machen, daf J> er tate, wie es jetzt am Tage ist, zu erhalten viel Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'So furchtet euch nun nicht; ich will euch versorgen und eure Kinder. Und er trostete sie und redete freundlich mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Also wohnete Joseph in Agypten mit seines Vaters Hause und lebte hundertundzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und sah Ephraims Kinder bis ins dritte Glied. Desselbigengleichen die Kinder Machirs, Manasses Sohnes, zeugeten auch Kinder auf Josephs Schoi J.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Und Joseph sprach zu seinen Brudern: Ich sterbe, und Gott wird euch heimsuchen und aus diesem Lande fuhren in das Land, das er Abraham, Isaak und Jakob geschworen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Darum nahm er einen Eid von den Kindern Israels und sprach: Wenn euch Gott heimsuchen wird, so führet meine Gebeine von dannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Also starb Joseph, da erwar hundertundzehn Jahre alt. Und sie salbeten ihn und legten ihn in eine Lade in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Dies sind die Namen der Kinder Israels, die mit Jakob nach Agypten kamen; ein jeglicher kam mit seinem Hause hinein:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi, Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaschar, Sebulon, Benjamin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naphthali, Gad, Asser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Und aller Seelen, die aus den Lenden Jakobs kommen waren, der waren siebenzig. Joseph aber war zuvor in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Da nun Joseph gestorben war und alle seine Brüder und alle, die zu der Zeit gelebt hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'wuchsen die Kinder Israel und zeugeten Kinder und mehreten sich; und wurden ihrer sehr viel, daß ihrer das Land voll ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da kam ein neuer Konig auf in Agypten, der wuftte nichts von Joseph;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'und sprach zu seinem Volk: Siehe, des Volks der Kinder Israel ist viel und mehr denn wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, wirwollen sie mit Listen dampfen, daß ihrer nicht so viel werden. Denn wo sich ein Krieg erhübe, mochten sie sich auch zu unsern Feinden schlagen und wider uns streiten und zum Lande ausziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Und man setzte Fronvogte uber sie, die sie mit schweren Diensten drucken sollten; denn man bauete dem Pharao die Stadte Pithon und Raemses zu Schatzhausern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber je mehr sie das Volk druckten, je mehr sich es mehrete und ausbreitete. Und sie hielten die Kinder Israel wie einen Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Und die Agypter zwangen die Kinder Israel zu Dienst mit Unbarmherzigkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'und machten ihnen ihr Leben sauer mit schwerer Arbeit im Ton und Ziegeln und mit allerlei Fronen auf dem Felde und mit allerlei Arbeit, die sie ihnen auflegten mit Unbarmherzigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der Konig in Agypten sprach zu den ebraischen Wehmuttern, deren eine hieft Siphra und die andere Pua:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Wenn ihr den ebraischen Weibern helfet und auf dem Stuhl sehet, daß es ein Sohn ist, so totet ihn; ist\'s aber eine Tochter, so lasset sie leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Aber die Wehmutter furchteten Gott und taten nicht, wie der Konig in Agypten zu ihnen gesagt hatte, sondern lieften die Kinder leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da rief der Konig in Agypten den Wehmuttern und sprach zu ihnen: Warum tut ihr das, daß ihr die Kinder leben lasset?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Wehmutter antworteten Pharao: Die ebraischen Weiber sind nicht wie die agyptischen, denn sie sind harte Weiber; ehe die Wehmutter zu ihnen kommt, haben sie geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Darum tat Gott den Wehmuttern Gutes. Und das Volk mehrete sich und ward sehr viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und weil die Wehmutter Gott furchteten, bauete er ihnen Hauser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da gebot Pharao all seinem Volk und sprach: Alle Sohne, die geboren werden, werfet ins Wasser und alle Tochter lasset leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Und es ging hin ein Mann vom Hause Levi und nahm eine Tochter Levis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib ward schwanger und gebar einen Sohn. Und da sie sah, daß es ein fein Kind war, verbarg sie ihn drei Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Und da sie ihn nicht langer verbergen konnte, machte sie ein Kastlein von Rohr und verklebte es mit Ton und Pech und legte das Kind drein und legte ihn in das Schilf am Ufer des Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Aber seine Schwester stund von feme, daß sie erfahren wollte, wie es ihm gehen würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Und die Tochter Pharaos ging hernieder und wollte baden im Wasser; und ihre Jungfrauen gingen an dem Rande des Wassers. Und da sie das Kastlein im Schilf sah, sandte sie ihre Magd hin und lieft es holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Und da sie es auftat, sah sie das Kind; und siehe, das Knablein weinete. Da jammerte es sie, und sprach: Es ist der ebraischen Kindlein eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da sprach seine Schwester zu der Tochter Pharaos: Soil ich hingehen und der ebraischen Weiber eine rufen, die da sauget, daß sie dir das Kindlein sauge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Die Tochter Pharaos sprach zu ihr: Gehe hin! Die Jungfrau ging hin und rief des Kindes Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Da sprach Pharaos Tochter zu ihr: Nimm hin das Kindlein und sauge mir\'s, ich will dir lohnen. Das Weib nahm das Kind und saugete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Und da das Kind graft ward, brachte sie es der Tochter Pharaos, und es ward ihr Sohn; und hieft ihn Mose, denn sie sprach: Ich habe ihn aus dem Wasser gezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Zu den Zeiten, da Mose war graft worden, ging er aus zu seinen Brudern und sah ihre Last und ward gewahr, daß ein Agypter schlug seiner Bruder, der ebraischen, einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und erwandte sich hin und her, und da er sah, daß kein Mensch da war, erschlug er den Agypter und verscharrete ihn in den Sand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Auf einen andern Tag ging erauch aus und sah zween ebraische Manner sich miteinander zanken; und sprach zu dem Ungerechten: Warum schlagest du deinen Nachsten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Er aber sprach: Wer hat dich zum Obersten Oder Richter über uns gesetzt? Willst du mich auch erwürgen, wie du den Agypter erwürget hast? Da furchtete sich Mose und sprach: Wie ist das laut worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Und es kam vor Pharao, dertrachtete nach Mose, daß er ihn erwurgete. Aber Mose floh vor Pharao und hielt sich im Lande Midian und wohnete bei einem Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Der Priester aber in Midian hatte sieben Tochter, die kamen, Wasserzu schopfen, und fulleten die Rinnen, dall sie ihres Vaters Schafe tranketen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Da kamen die Hirten und stieüen sie davon. Aber Mose machte sich auf und half ihnen und trankte ihre Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Und da sie zu ihrem Vater Reguel kamen, sprach er: Wie seid ihr heute so bald kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Sie sprachen: Ein agyptischer Mann errettete uns von den Hirten und schopfte uns und trankte die Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Er sprach zu seinen Tochtern: Wo ist er? Warum habt ihr den Mann gelassen, daß ihr ihn nicht ludet, mit uns zu essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose bewilligte, bei dem Manne zu bleiben. Und er gab Mose seine Tochter Zipora.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Die gebar einen Sohn: und er hieß ihn Gersom; denn er sprach: Ich bin ein Fremdling worden im fremden Lande. (Und sie gebar noch einen Sohn, den hieli er Elieser, und sprach: Der Gott meines Vaters ist mein Heifer und hat mich von der Hand Pharaos errettet.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Lange Zeit aber danach starb der Konig in Agypten. Und die Kinder Israel seufzeten uber ihre Arbeit und schrieen; und ihr Schreien uber ihre Arbeit kam vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott erhorete ihr Wehklagen und gedachte an seinen Bund mit Abraham, Isaak und Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und er sah drein und nahm sich ihrer an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mose aber hütete die Schafe Jethros, seines Schwahers, des Priesters in Midian, und trieb die Schafe hinter in die Wüste und kam an den Berg Gottes Horeb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Und der Engel des HERRN erschien ihm in einer feurigen Flamme aus dem Busch. Und ersah, daß der Busch mit Feuer brannte, und ward doch nicht verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Und sprach: Ich will dahin und besehen dies grolie Gesicht, warum der Busch nicht verbrennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Da aber der HERR sah, daß er hinging zu sehen, rief ihm Gott aus dem Busch und sprach: Mose, Mose! Er antwortete: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Er sprach: Tritt nicht herzu! Zeuch deine Schuhe aus von deinen Fufien; denn der Ort, da du auf stehest, ist ein heilig Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Und sprach weiter: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Und Mose verhullete sein Angesicht, denn er fürchtete sich, Gott anzuschauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Und der HERR sprach: Ich habe gesehen das Elend meines Volks in Agypten und habe ihr Geschrei gehoret uber die, so sie treiben; ich habe ihr Leid erkannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Und bin herniedergefahren, daß ich sie errette von der Agypter Hand und sie ausführe aus diesem Lande in ein gut und weit Land, in ein Land, darinnen Milch und Honig fleußt, namlich an den Odder Kanaaniter, Hethiter, Amoriter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Weil denn nun das Geschrei der Kinder Israel vor mich kommen ist und habe auch dazu gesehen ihre Angst, wie sie die Agypter angsten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'so gehe nun hin, ich will dich zu Pharao senden, dafi du mein Volk, die Kinder Israel, aus Agypten führest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mose sprach zu Gott: Wer bin ich, dafi ich zu Pharao gehe und führe die Kinder Israel aus Agypten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Er sprach: Ich will mit dir sein. Und das soli dir das Zeichen sein, dafi ich dich gesandt habe: Wenn du mein Volk aus Agypten geführet hast, werdet ihr Gott opfern auf diesem Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mose sprach zu Gott: Siehe, wenn ich zu den Kindern Israel komme und spreche zu ihnen: Der Gott eurer Vater hat mich zu euch gesandt, und sie mir sagen werden: Wie heifit sein Name? was soil ich ihnen sagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Gott sprach zu Mose: Ich werde sein, der ich sein werde. Und sprach: Also sollstdu den Kindern Israel sagen: Ich werd\'s sein, der hat mich zu euch gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und Gott sprach weiter zu Mose: Also sollstdu zu den Kindern Israel sagen: Der HERR, eurer Vater Gott, der Gott Abrahams, der Gott Isaaks, der Gott Jakobs, hat mich zu euch gesandt. Das ist mein Name ewiglich, dabei soil man mein gedenken fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Darum so gehe hin und versammle die Altesten in Israel und sprich zu ihnen: Der HERR, eurer Vater Gott, ist mir er schienen, der Gott Abrahams, der Gott Isaaks, der Gott Jakobs, und hat gesagt: Ich habe euch heimgesucht und gesehen, was euch in Agypten widerfahren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Und habe gesagt: Ich will euch aus dem Elende Agyptens führen in das Land der Kanaaniter, Hethiter, Amoriter, Pheresiter, Heviter und Jebusiter, in das Land, darinnen Milch und Honig fleußt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und wenn sie deine Stimme horen, so sollst du und die Altesten in Israel hineingehen zum Konige in Agypten und zu ihm sagen: Der HERR, der Ebraer Gott, hat uns gerufen. So laß uns nun gehen drei Tagesreisen in die Wüste, daß wir opfern dem HERRN, unserm Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Aber ich weifi, daß euch der Konig in Agypten nicht wird ziehen lassen ohne durch eine starke Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Denn ich werde meine Hand aus strecken und Agypten schlagen mit allerlei Wundern, die ich drinnen tun werde. Danach wird er euch ziehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und ich will diesem Volk Gnade geben vor den Agyptern, daß, wenn ihr ausziehet, nicht leer ausziehet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'sondern ein jeglich Weib soli von ihrer Nachbarin und Hausgenossin fordern silberne und guldene Gefalie und Kleider; die sollt ihr auf eure Sohne und Tochter legen und den Agyptern entwenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mose antwortete und sprach: Siehe, sie werden mir nicht glauben noch meine Stimme horen, sondern werden sagen: Der HERR ist dir nicht erschienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Der HERR sprach zu ihm: Was ist, das du in deiner Hand hast? Er sprach: Ein Stab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Er sprach: Wirt ihn von dir auf die Erde! Und er warf ihn von sich; da ward er zur Schlange. Und Mose floh vor ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Aber der HERR sprach zu ihm: Strecke deine Hand aus und erhasche sie bei dem Schwanz. Da streckte er seine Hand aus und hielt sie; und sie ward zum Stab in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Darum werden sie glauben, daß dir erschienen sei der HERR, der Gott ihrer Vater, der Gott Abrahams, der Gott Isaaks, der Gott Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Und der HERR sprach weiter zu ihm: Stecke deine Hand in deinen Busen. Und er steckte sie in seinen Busen und zog sie heraus; siehe, da war sie aussatzig wie Schnee.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Und er sprach: Tu sie wieder in den Busen. Und er tat sie wieder in den Busen und zog sie heraus; siehe, da ward sie wieder wie sein ander Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Wenn sie dir nun nicht werden glauben noch deine Stimme horen bei einem Zeichen, so werden sie doch glauben deiner Stimme bei dem andern Zeichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Wenn sie aber diesen zweien Zeichen nicht glauben werden noch deine Stimme horen, so nimm des Wassers aus dem Strom und geufi es auf das trockne Land, so wird dasselbe Wasser, das du aus dem Strom genommen hast, Blut werden auf dem trocknen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Mose aber sprach zu dem HERRN: Ach, mein HERR, ich bin je und je nicht wohl beredt gewesen, seit der Zeit du mit deinem Knecht geredet hast; denn ich habe eine schwere Sprache und eine schwere Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Der HERR sprach zu ihm: Wer hat dem Menschen den Mund geschaffen Oder wer hat den Stummen Oder Tauben Oder Sehenden Oder Blinden gemacht? Habe ich\'s nicht getan, der HERR?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'So gehe nun hin: Ich will mit deinem Munde sein und dich lehren, was du sagen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mose sprach aber: Mein HERR, sende, welchen du senden willst!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da ward der HERR sehrzornig über Mose und sprach: Weift ich denn nicht, daß dein Bruder Aaron aus dem Stamm Levi beredt ist? Und siehe, er wird herausgehen dir entgegen, und wenn er dich siehet, wird er sich von Herzen freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Du sollst zu ihm reden und die Worte in seinen Mund legen. Und ich will mit deinem und seinem Munde sein und euch lehren; was ihr tun sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Und ersoll fur dich zum Volk reden; er soil dein Mund sein, und du sollst sein Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und diesen Stab nimm in deine Hand, damit du Zeichen tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Mose ging hin und kam wieder zu Jethro, seinem Schwaher, und sprach zu ihm: Lieber, laft mich gehen, dafi ich wieder zu meinen Brüdem komme, die in Agypten sind, und sehe, ob sie noch leben. Jethro sprach zu ihm: Gehe hin mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Auch sprach der HERRzu ihm in Midian: Gehe hin und zeuch wieder nach Agypten; denn die Leute sind tot, die nach deinem Leben stunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Also nahm Mose sein Weib und seine Sohne und fuhrete sie auf einem Esel und zog wieder nach Agyptenland; und nahm den Stab Gottes in seine Hand!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Und der HERR sprach zu Mose: Siehe zu, wenn du wieder nach Agypten kommst, daß du alle die Wunder tust vor Pharao, die ich dir in deine Hand gegeben habe; ich aber will sein Herz verstocken, daß er das Volk nicht lassen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Und sollst zu ihm sagen: So saget der HERR: Israel ist mein erstgeborner Sohn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'und ich gebiete dir, daß du meinen Sohn ziehen lassest, daß er mir diene. Wirst du dich des weigern, so will ich deinen erstgebornen Sohn erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Und als er unterwegen in der Herberge war, kam ihm der HERR entgegen und wollte ihn toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da nahm Zipora einen Stein und beschnitt ihrem Sohn die Vorhaut; und ruhrete ihm seine Füfte an und sprach: Du bist mir ein Blutbrautigam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Da lieft er von ihm ab. Sie sprach aber Blutbrautigam urn der Beschneidung willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und der HERR sprach zu Aaron: Gehe hin Mose entgegen in die Wüste. Und er ging hin und begegnete ihm am Berge Gottes und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose sagte Aaron alle Worte des HERRN, der ihn gesandt hatte, und alle Zeichen, die er ihm befohlen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Und sie gingen hin und versammelten alle Altesten von den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aaron redete alle Worte, die der HERR mit Mose geredet hatte, und tat die Zeichen vor dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Und das Volk glaubete. Und da sie horeten, daß der HERR die Kinder Israel heimgesucht und ihr Elend angesehen hatte, neigeten sie sich und beteten an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Danach gingen Mose und Aaron hinein und sprachen zu Pharao: So sagt der HERR, der Gott Israels: Laft mein Volk ziehen, daß mir\'s ein Fest halte in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Pharao antwortete: Wer ist der HERR, des Stimme ich horen müsse und Israel ziehen lassen? Ich weift nicht von dem HERRN, will auch Israel nicht lassen ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Sie sprachen: Der Ebraer Gott hat uns gerufen; so laft uns nun hinziehen drei Tagereisen in die Wüste und dem HERRN, unserm Gott, opfern, daß uns nicht widerfahre Pestilenz Oder Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Da sprach der Konig in Agypten zu ihnen: Du, Mose und Aaron, warum wollt ihr das Volk von seiner Arbeit frei machen? Gehet hin an eure Dienste!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Weiter sprach Pharao: Siehe, des Volks ist schon zu viel im Lande, und ihr wollt sie noch feiern heilien von ihrem Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Darum befahl Pharao desselben Tages den Vogten des Volks und ihren Amtleuten und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ihr sollt dem Volk nicht mehr Stroh sammeln und geben, dafi sie Ziegel brennen, wie bis anher; lasset sie selbst hingehen und Stroh zusammenlesen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'und die Zahl der Ziegel, die sie bisher gemacht haben, sollt ihr ihnen gleichwohl auflegen und nichts mindern; denn sie gehen mufüg, darum schreien sie und sprechen: Wirwollen hinziehen und unserm Gott opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Man drucke die Leute mit Arbeit, daß sie zu schaffen haben und sich nicht kehren an falsche Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gingen die Vogte des Volks und ihre Amtleute aus und sprachen zum Volk: So spricht Pharao: Man wird euch kein Stroh geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Gehet ihr selbst hin und sammelt euch Stroh, wo ihr\'s findet; aber von eurer Arbeit soil nichts gemindert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da zerstreute sich das Volk ins ganze Land Agypten, daß es Stoppeln sammelte, damit sie Stroh hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Und die Vogte trieben sie und sprachen: Erfullet euer Tagwerk, gleich als da ihr Stroh hattet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die Amtleute der Kinder Israel, welche die Vogte Pharaos uber sie gesetzet hatten, wurden geschlagen, und ward zu ihnen gesagt: Warum habt ihrweder heute noch gestern euer gesetzt Tagwerk getan, wievorhin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gingen hinein die Amtleute der Kinder Israel und schrieen zu Pharao: Warum willst du mit deinen Knechten also fahren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Man gibt deinen Knechten kein Stroh, und sollen die Ziegel machen, die uns bestimmt sind; und siehe, deine Knechte werden geschlagen, und dein Volk mufi Sunder sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Pharao sprach: Ihrseid mulüg, mulüg seid ihr; darum sprechet ihr: Wirwollen hinziehen und dem HERRN opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'So gehet nun hin und fronet! Stroh soil man euch nicht geben, aber die Anzahl der Ziegel sollt ihr reichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Da sahen die Amtleute der Kinder Israel, dafi es arger ward, weil man sagte: Ihr sollt nichts mindern von dem Tagwerk an den Ziegeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Und da sie von Pharao gingen, begegneten sie Mose und Aaron und traten gegen sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'und sprachen zu ihnen: Der HERR sehe auf euch und richte es, daß ihr unsern Geruch habt stinken gemacht vor Pharao und seinen Knechten und habt ihnen das Schwert in ihre Hande gegeben, uns zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Mose aber kam wieder zu dem HERRN und sprach: HERR, warum tust du so ubel an diesem Volk? Warum hast du mich hergesandt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Denn seitdem, daß ich hinein bin gegangen zu Pharao, mit ihm zu reden in deinem Namen, hat er das Volk noch harter geplagt; und du hast dein Volk nicht errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Der HERR sprach zu Mose: Nun sollst du sehen, was ich Pharao tun werde; denn durch eine starke Hand muli er sie lassen ziehen, er muli sie noch durch eine starke Hand aus seinem Lande von sich treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Und Gott redete mit Mose und sprach zu ihm: Ich bin der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'und bin erschienen Abraham, Isaak und Jakob, daß ich ihr allmachtiger Gott sein wollte; aber mein Name, HERR, ist ihnen nicht offenbaret worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Auch habe ich meinen Bund mit ihnen aufgerichtet, daß ich ihnen geben will das Land Kanaan, das Land ihrer Wallfahrt, darinnen sie Fremdlinge gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Auch habe ich gehoret die Wehklage der Kinder Israel, welche die Agypter mit Fronen beschweren, und habe an meinen Bund gedacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sage den Kindern Israel: Ich bin der HERR und will euch ausfuhren von euren Lasten in Agypten und will euch erretten von eurem Fronen und will euch erlosen durch einen ausgereckten Arm und grolie Gerichte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'und will euch annehmen zum Volk und will euer Gott sein, daß ihr\'s erfahren sollt, daß ich der HERR bin euer Gott, der euch ausgeführet habe von der Last Agyptens');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'und euch gebracht in das Land, daruber ich habe meine Hand gehoben, daß ich\'s gabe Abraham, Isaak und Jakob; das will ich euch geben zu eigen, ich, der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Mose sagte solches den Kindern Israel; aber sie horeten ihn nicht vor Seufzen und Angst und harter Arbeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da redete der HERR mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gehe hinein und rede mit Pharao, dem Konige in Agypten, daß er die Kinder Israel aus seinem Lande lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mose aber redete vor dem HERRN und sprach: Siehe, die Kinder Israel horen mich nicht, wie sollte mich denn Pharao horen? Dazu bin ich von unbeschnittenen Lippen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Also redete der HERR mit Mose und Aaron und tat ihnen Befehl an die Kinder Israel und Pharao, den Konig in Agypten, daß sie die Kinder Israel aus Agypten fuhreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dies sind die Haupter in jeglichem Geschlecht der Vater. Die Kinder Rubens, des ersten Sohnes Israels, sind diese: Hanoch, Pallu, Hezron, Charmi. Das sind die Geschlechter von Ruben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Die Kinder Simeons sind diese: Jemuel, Jamin, Ohad, Jachin, Zohar und Saul, der Sohn des kanaanaischen Weibes, das sind Simeons Geschlechter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Dies sind die Namen der Kinder Levis in ihren Geschlechtern: Gerson, Kahath, Merari. Aber Levi ward hundertundsiebenunddreifüg Jahre alt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Kinder Gersons sind diese: Libni und Simei in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Die Kinder Kahaths sind diese: Amram, Jezear, Hebron, Usiel. Kahath aber ward hundertunddreiunddreifüg Jahre alt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Die Kinder Meraris sind diese: Maheli und Musi. Das sind die Geschlechter Levis in ihren Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Und Amram nahm seine Muhme Jochebed zum Weibe, die gebar ihm Aaron und Mose. Aber Amram ward hundertundsiebenunddreifüg Jahre alt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Die Kinder Jezears sind diese: Korah, Nepheg, Sichri.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Die Kinder Usiels sind diese: Misael, Elzaphan, Sithri.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron nahm zum Weibe Eliseba, die Tochter Amminadabs, Nahassons Schwester; die gebar ihm Nadab, Abihu, Eleasar, Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Die Kinder Korahs sind diese: Assir, Elkana, Abiasaph. Das sind die Geschlechter der Korahiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar aber, Aarons Sohn, der nahm von den Tochtern Putiels ein Weib; die gebar ihm den Pinehas. Das sind die Haupter unter den Vatern der Levitengeschlechter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Das ist der Aaron und Mose, zu denen der HERR sprach: Fuhret die Kinder Israel aus Agyptenland mit ihrem Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Sie sind\'s, die mit Pharao, dem Konige in Agypten, redeten, daü sie die Kinder Israel aus Agypten fuhreten, namlich Mose und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Und des Tages redete der HERR mit Mose in Agyptenland');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'und sprach zu ihm: Ich bin der HERR; rede mit Pharao, dem Konige in Agypten, alles was ich mit dir rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Und erantwortete vordem HERRN: Siehe, ich bin von unbeschnittenen Lippen; wie wird mich denn Pharao horen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Der HERR sprach zu Mose: Siehe, ich habe dich einen Gott gesetzt uber Pharao; und Aaron, dein Bruder, soil dein Prophet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst reden alles, was ich dir gebieten werde; aber Aaron, dein Bruder, soil es vor Pharao reden, dafi er die Kinder Israel aus seinem Lande lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Aber ich will Pharaos Herz verharten, dafi ich meiner Zeichen und Wunder viel tue in Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Und Pharao wird euch nicht horen, auf dafi ich meine Hand in Agypten beweise und fuhre mein Heer, mein Volk, die Kinder Israel, aus Agyptenland durch groüe Gerichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Und die Agypter sollen\'s inne werden, daß ich der HERR bin, wenn ich nun meine Hand ausstrecke uber Agypten und die Kinder Israel von ihnen wegfuhren werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mose und Aaron taten, wie ihnen der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Und Mose war achtzig Jahre alt und Aaron dreiundachtzig Jahre alt, da sie mit Pharao redeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Und der HERR sprach zu Mose und Aaron:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Wenn Pharao zu euch sagen wird: Beweiset eure Wunder, so sollst du zu Aaron sagen: Nimm deinen Stab und wirf ihn vor Pharao, dad er zur Schlange werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Da gingen Mose und Aaron hinein zu Pharao und taten wie ihnen der HERR geboten hatte. Und Aaron wart seinen Stab vor Pharao und vor seinen Knechten; und er ward zur Schlange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Da forderte Pharao die Weisen und Zauberer. Und die agyptischen Zauberer taten auch also mit ihrem Beschworen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Ein jeglicher warf seinen Stab von sich, da wurden Schlangen draus; aber Aarons Stab verschlang ihre Stabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Also ward das Herz Pharaos verstockt und horete sie nicht, wie denn der HERR geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Und der HERR sprach zu Mose: Das Herz Pharaos ist hart; er weigert sich, das Volk zu lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gehe hin zu Pharao morgen. Siehe, erwird ans Wasser gehen; so tritt gegen ihm an das Ufer des Wassers und nimm den Stab in deine Hand, der zur Schlange ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'und sprich zu ihm: Der HERR, der Ebraer Gott, hat mich zu dir gesandt und lassen sagen: Laft mein Volk, daiß mir\'s diene in der Wuste! Aber du hast bisher nicht wollen horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Darum spricht der HERR also: Daran sollst du erfahren, daß ich der HERR bin. Siehe, ich will mit dem Stabe, den ich in meiner Hand habe, das Wasser schlagen, das in dem Strom ist, und es soil in Blut verwandelt werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'da(S die Fische im Strom sterben sollen und der Strom stinken, und den Agyptern wird ekeln, zu trinken des Wassers aus dem Strom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Und der HERR sprach zu Mose: Sage Aaron: Nimm deinen Stab und recke deine Hand aus uber die Wasser in Agypten, uber ihre Bache und Strome und Seen und uber alle Wassersumpfe, dafi sie Blut werden, und sei Blut in ganz Agyptenland, beide in holzernen und steinernen Gefaften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Mose und Aaron taten, wie ihnen der HERR geboten hatte, und hub den Stab auf und schlug ins Wasser, das im Strom war, vor Pharao und seinen Knechten. Und alles Wasser im Strom ward in Blut verwandelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Und die Fische im Strom starben, und der Strom ward stinkend, daß die Agypter nicht trinken konnten des Wassers aus dem Strom; und ward Blut in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Und die agyptischen Zauberer taten auch also mit ihrem Beschworen. Also ward das Herz Pharaos verstockt und horete sie nicht, wie denn der HERR geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Und Pharao wandte sich und ging heim und nahm\'s nicht zu Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Aber alle Agypter gruben nach Wasser urn den Strom her, zu trinken; denn des Wassers aus dem Strom konnten sie nicht trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Und das wahrete sieben Tage iang, daß der HERR den Strom schlug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 26, 'Der HERR sprach zu Mose: Gehe hinein zu Pharao und sprich zu ihm: So sagt der HERR: Laß mein Volk, daß mir\'s diene!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 27, 'Wo du dich des weigerst, siehe, so will ich alle deine Grenze mit Froschen plagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 28, 'daß der Strom soli von Froschen wimmeln; die sollen heraufkriechen und kommen in dein Haus, in deine Kammer, auf dein Lager, auf dein Bett; auch in die Hauser deiner Knechte, unter dein Volk, in deine Backofen und in deine Teige;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 29, 'und sollen die Frosche auf dich und auf dein Volk und auf alle deine Knechte kriechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und der HERR sprach zu Mose: Sage Aaron: Recke deine Hand aus mit deinem Stabe uber die Bache und Strome und Seen und laß Frosche uber Agyptenland kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Und Aaron reckte seine Hand uber die Wasser in Agypten; und kamen Frosche herauf, daß Agyptenland bedecktward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Da taten die Zauberer auch also mit ihrem Beschworen und ließen Frosche uber Agyptenland kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Da forderte Pharao Mose und Aaron und sprach: Bittet den HERRN fur mich, daß er die Frosche von mir und von meinem Volk nehme, so will ich das Volk lassen, daß es dem HERRN opfere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Mose sprach: Habe du die Ehre vor mir und stimme mir, wann ich fur dich, fur deine Knechte und fur dein Volk bitten soli, daß die Frosche von dir und von deinem Hause vertrieben werden und allein im Strom bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Er sprach: Morgen. Er sprach: Wie du gesagt hast. Auf daß du erfahrest, daß niemand ist wie der HERR, unser Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'so sollen die Frosche von dir, von deinem Hause von deinen Knechten und von deinem Volk genommen werden und allein im Strom bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Also ging Mose und Aaron von Pharao. Und Mose schrie zu dem HERRN der Frosche halben, wie er Pharao hatte zugesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Und der HERR tat, wie Mose gesagt hatte; und die Frosche starben in den Hausern, in den Hofen und auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Und sie hauften sie zusammen, hie einen Haufen und da einen Haufen; und das Land stank davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Da aber Pharao sah, daß er Luftgekriegt hatte, ward sein Herz verhartet und horete sie nicht, wie denn der HERR geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Und der HERR sprach zu Mose: Sage Aaron: Recke deinen Stab aus und schlag in den Staub auf Erden, daß Lause werden in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Sie taten also, und Aaron reckte seine Hand aus mitseinem Stabe und schlug in den Staub auf Erden; und es wurden Lause an den Menschen und an dem Vieh; aller Staub des Landes ward Lause in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Die Zauberer taten auch also mit ihrem Beschworen, daß sie Lause heraus brachten, aber sie konnten nicht. Und die Lause waren beide an Menschen und an Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Da sprachen die Zauberer zu Pharao: Das ist Gottes Finger. Aber das Herz Pharaos ward verstockt und horete sie nicht, wie denn der HERR gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Und der HERR sprach zu Mose: Mache dich morgen fruhe auf und tritt vor Pharao (siehe, er wird ans Wasser gehen) und sprich zu ihm: So sagt der HERR: Laß mein Volk, daß es mir diene;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'wo nicht, siehe, so will ich allerlei Ungeziefer lassen kommen uber dich, deine Knechte, dein Volk und dein Haus, daß ailer Agypter Hauser und das Feld und was drauf ist, voll Ungeziefer werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Und will des Tages ein Besonderes tun mit dem Lande Gosen, da sich mein Volk enthalt, daß kein Ungeziefer da sei, auf daß du inne werdest, daß ich der HERR bin auf Erden alienthalben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Und will eine Erlosung setzen zwischen meinem und deinem Volk: Morgen soil das Zeichen geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und der HERR tat also, und es kam viel Ungeziefers in Pharaos Haus, in seiner Knechte Hauser und uber ganz Agyptenland; und das Land ward verderbet von dem Ungeziefer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Da forderte Pharao Mose und Aaron und sprach: Gehet hin, opfert eurem Gott hie im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mose sprach: Das taugt nicht, daß wir also tun; denn wir wurden der Agypter Greuei opfern unserm Gott, dem HERRN; siehe, wenn wir denn der Agypter Greuei vor ihren Augen opferten, wurden sie uns nicht steinigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Drei Tagereisen wollen wir gehen in die Wüste und dem HERRN, unserm Gott, opfern, wie er uns gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Pharao sprach: Ich will euch lassen, daß ihr dem HERRN, eurem Gott opfert in der Wüste; allein; daß ihr nicht ferner ziehet, und bittet fur mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Mose sprach: Siehe, wenn ich hinaus von dir komme so will ich den HERRN bitten, daß dies Ungeziefer von Pharao und seinen Knechten und von seinem Volk genommen werde, morgen des Tages; allein tausche mich nicht mehr, daß du das Volk nicht lassest, dem HERRN zu opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Und Mose ging hinaus von Pharao und bat den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Und der HERR tat, wie Mose gesagt hatte, und schaffte das Ungeziefer weg von Pharao, von seinen Knechten und von seinem Volk, daß nicht eins uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Aber Pharao verhartete sein Herz auch dasselbe Mai und lieft das Volk nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Der HERR sprach zu Mose: Gehe hinein zu Pharao und sprich zu ihm: Also sagt der HERR, der Gott der Ebraer: Laft mein Volk, daß sie mir dienen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Wo du dich des weigerst und sie weiter aufhaltst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'siehe, so wird Hand des HERRN sein uber dein Vieh auf dem Felde, uber Pferde, uber Esel, uber Kamele, uber Ochsen, uber Schafe mit einer fast schweren Pestilenz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Und der HERR wird ein Besonderes tun zwischen dem Vieh der Israeliten und der Agypter, daß nichts sterbe aus allem, das die Kinder Israel haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Und der HERR bestimmte eine Zeit und sprach: Morgen wird der HERR solches auf Erden tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und der HERR tat solches des Morgens; und starb allerlei Vieh der Agypter; aber des Viehes der Kinder Israel starb nicht eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Und Pharao sandte danach, und siehe, es war des Viehes Israel nicht eins gestorben. Aber das Herz Pharaos ward verstockt und lieft das Volk nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Da sprach der HERR zu Mose und Aaron: Nehmet eure Fauste voll Ruft aus dem Ofen, und Mose sprenge ihn gen Himmel vor Pharao,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'daß uber ganz Agyptenland staube, und bose schwarze Blattern auffahren, beide an Menschen und an Vieh, in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Und sie nahmen Ruft aus dem Ofen und traten vor Pharao, und Mose sprengete ihn gen Himmel. Da fuhren auf bose schwarze Blattern, beide an Menschen und an Vieh,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'also daß die Zauberer nicht konnten vor Mose stehen vor den bosen Blattern; denn es waren an den Zauberern ebensowohl bose Blattern als an alien Agyptern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Aber der HERR verstockte das Herz Pharaos, daß er sie nicht horete, wie denn der HERR zu Mose gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Da sprach der HERR zu Mose: Mache dich morgen fruhe auf und tritt vor Pharao und sprich zu ihm: So sagt der HERR, der Ebraer Gott: Laft mein Volk, daß mir\'s diene!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Ich will anders diesmal alle meine Plagen uber dich selbst senden, fiber deine Knechte und uber dein Volk, daß du inne werden sollst, daß meinesgleichen nicht ist in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Denn ich will jetzt meine Hand ausrecken und dich und dein Volk mit Pestilenz schlagen, daß du von der Erde sollst vertilget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Und zwar darum habe ich dich erwecket, daß meine Kraft an dir erscheine, und mein Name verkundiget werde in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Du trittst mein Volk noch unter dich und willst es nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Siehe, ich will morgen urn diese Zeit einen sehr groften Hagel regnen lassen, desgleichen in Agypten nicht gewesen ist, seit der Zeit es gegründet ist, bisher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Und nun sende hin und verwahre dein Vieh und alles, was du auf dem Felde hast. Denn alle Menschen und Vieh, das auf dem Felde funden wird und nicht in die Hauser versammelt ist, so der Hagel auf sie fallt, werden sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer nun unter den Knechten Pharaos des HERRN Wort furchtete, der lieft seine Knechte und Vieh in die Hauser fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Welcher Herz aber sich nicht kehrete an des HERRN Wort, lieften ihre Knechte und Vieh auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da sprach der HERR zu Mose: Recke deine Hand gen Himmel, daß es hagele uber ganz Agyptenland, uber Menschen, uber Vieh und uber alles Kraut auf dem Felde in Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Also reckte Mose seinen Stab gen Himmel; und der HERR lieft donnern und hageln, daß das Feuer auf die Erde schoft. Also lieft der HERR Hagel regnen uber Agyptenland,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'daß Hagel und Feuer untereinander fuhren, so grausam, daß desgleichen in ganz Agyptenland nie gewesen war, seit der Zeit Leute drinnen gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel schlug in ganz Agyptenland alles, was auf dem Felde war, beide Menschen und Vieh, und schlug alles Kraut auf dem Felde und zerbrach alle Baume auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Ohne allein im Lande Gosen, da die Kinder Israel waren, da hagelte es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da schickte Pharao hin und lieft Mose und Aaron rufen und sprach zu ihnen: Ich habe dasmal mich versündiget; der HERR ist gerecht, ich aber und mein Volk sind Gottlose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Bittet aber den HERRN, daß aufhore solch Donnern und Hageln Gottes, so will ich euch lassen, daß ihr nicht langer hie bleibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mose sprach zu ihm: Wenn ich zur Stadt hinaus komme, will ich meine Hande ausbreiten gegen den HERRN, so wird der Donner aufhoren, und kein Hagel mehr sein, auf daß du inne werdest, daß die Erde des HERRN sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ich weift aber, daß du und deine Knechte euch noch nicht furchtet vor Gott dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Also ward geschlagen der Flachs und die Gerste; denn die Gerste hatte geschosset und der Flachs Knoten gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Aber der Weizen und Roggen ward nicht geschlagen, denn es war spat Getreide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'So ging nun Mose von Pharao zur Stadt hinaus und breitete seine Hande gegen den FIERRN, und der Donner und Hagel horeten auf, und der Regen troff nicht mehrauf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Da aber Pharao sah, daß der Regen und Donner und Hagel aufhorete, versündigte er sich weiter und verhartete sein Herz, er und seine Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Also ward des Pharao Herz verstockt, daü er die Kinder Israel nicht lieli, wie denn der HERR geredet hatte durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Und der HERR sprach zu Mose: Gehe hinein zu Pharao; denn ich habe sein und seiner Knechte Herz verhartet, auf daß ich diese meine Zeichen unter ihnen tue,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'und daß du verkündigest vor den Ohren deiner Kinder und deiner Kindeskinder, was ich in Agypten ausgerichtet habe und wie ich meine Zeichen unter ihnen beweiset habe, daß ihrwisset; ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Also gingen Mose und Aaron hinein zu Pharao und sprachen zu ihm: So spricht der HERR, der Ebraer Gott: Wie lange weigerst du, dich vor mir zu demütigen, daß du mein Volk lassest, mirzu dienen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Weigerst du dich, mein Volk zu lassen, siehe, so will ich morgen Heuschrecken kommen lassen an alien Orten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'daß sie das Land bedecken, also dafi man das Land nicht sehen konne; und sollen fressen, was euch ubrig und errettet istvon dem Hagel, und sollen alle eure grünenden Baume fressen auf dem Felde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'und sollen erfullen dein Haus, alter deiner Knechte Hauser und aller Agypter Hauser, desgleichen nicht gesehen haben deine Vater und deiner Vater Vater, seit der Zeit sie auf Erden gewesen, bis auf diesen Tag. Und er wandte sich und ging von Pharao hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sprachen die Knechte Pharaos zu ihm: Wie lange solien wir damit geplagt sein? Laü die Leute ziehen, daß sie dem HERRN, ihrem Gott, dienen! Willst du zu vor erfahren, daß Agypten untergegangen sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Mose und Aaron wurden wiederzu Pharao gebracht, der sprach zu ihnen: Gehet hin und dienet dem HERRN, eurem Gott. Welche sind sie aber, die hinziehen sollen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mose sprach: Wirwollen ziehen mitjung und alt, mit Sohnen und Tochtern, mit Schafen und Rindern; denn wir haben ein Fest des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Er sprach zu ihnen: Awe ja, der HERR sei mit euch! Sollte ich euch und eure Kinder dazu ziehen lassen? Sehet da, ob ihr nicht Boses vorhabt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nicht also, sondern ihr Manner ziehet hin und dienet dem HERRN; denn das habt ihr auch gesucht. Und man stieli sie heraus von Pharao.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da sprach der HERR zu Mose: Recke deine Hand uber Agyptenland urn die Heuschrecken, dafi sie auf Agyptenland kommen und fressen alles Kraut im Lande auf samt alle dem, das dem Hagel uberblieben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Mose reckte seinen Stab uber Agyptenland. Und der HERR trieb einen Ostwind ins Land den ganzen Tag und die ganze Nacht; und des Morgens führete der Ostwind die Heuschrecken her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Und sie kamen uber ganz Agyptenland und lielien sich nieder an alien Orten in Agypten, so sehr viel, daß zuvor des gleichen nie gewesen ist, noch hinfort sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Denn sie bedeckten das Land und verfinsterten es. Und sie fraüen alles Kraut im Lande auf und alle Fruchte auf den Baumen, die dem Hagel waren uberblieben, und lielien nichts Grünes ubrig an den Baumen und am Kraut auf dem Felde in ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da forderte Pharao eilend Mose und Aaron und sprach: Ich habe mich versundiget an dem HERRN, eurem Gott, und an euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Vergebet mir meine Sunde diesmal auch und bittet den HERRN, euren Gott, daß er doch nur diesen Tod von mirwegnehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Und erging aus von Pharao und bat den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Da wendete der HERR einen sehr starken Westwind und hub die Heuschrecken auf und warf sie ins Schilfmeer, dafi nicht eine ubrig blieb an alien Orten Agyptens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Aber der HERR verstockte Pharaos Herz, daß er die Kinder Israel nicht lieli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Der HERR sprach zu Mose: Recke deine Hand gen Himmel, dafi es so finster werde in Agyptenland, daß man\'s greifen mag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Und Mose reckte seine Hand gen Himmel; da ward eine dicke Finsternis in ganz Agyptenland drei Tage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'daß niemand den andern sah noch aufstund von dem Ort, da er war, in dreien Tagen. Aber bei alien Kindern Israel war es licht in ihren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da forderte Pharao Mose und sprach: Ziehet hin und dienet dem HERRN; allein eure Schafe und Rinder lasset hie; lasset auch eure Kindlein mit euch ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mose sprach: Du muüt uns auch Opfer und Brandopfer geben, das wir unserm Gott, dem HERRN, tun mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Unser Vieh soil mit uns gehen und nicht eine Klaue dahinten bleiben; denn von dem Unsern werden wir nehmen zum Dienst unsers Gottes, des HERRN. Denn wirwissen nicht, womit wir dem HERRN dienen sollen, bis wir dahin kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Aber der HERR verstockte das Herz Pharaos, dafi er sie nicht lassen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und Pharao sprach zu ihm: Gehe von mir und hute dich, dafi du nicht mehr vor meine Augen kommest; denn welches Tages du vor meine Augen kommst, sollst du sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mose antwortete: Wie du gesagt hast; ich will nicht mehr vor deine Augen kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Und der HERR sprach zu Mose: Ich will noch eine Plage über Pharao und Agypten kommen lassen, danach wird er euch lassen von hinnen, und wird nicht allein alles lassen, sondern euch auch von hinnen treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'So sage nun vor dem Volk, dafi ein jeglicher von seinem Nachsten und eine jegliche von ihrer Nachstin silberne und guldene Gefafte fordere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Denn der HERR wird dem Volk Gnade geben vor den Agyptern. Und Mose war ein sehr grafter Mann in Agyptenland vor den Knechten Pharaos und vor dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Und Mose sprach: So sagt der HERR: Ich will zur Mitternacht ausgehen in Agyptenland;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'und alle Erstgeburt in Agyptenland soli sterben, von dem ersten Sohn Pharaos an, der auf seinem Stuhl sitzt, bis an den ersten Sohn der Magd, die hinter der Mühle ist, und alle Erstgeburt unter dem Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Und wird ein graft Geschrei sein in ganz Agyptenland, desgleichen nie gewesen ist noch werden wird;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'aber bei alien Kindern Israel soil nicht ein Hund mucken, beide unter Menschen und Vieh, auf daß ihr erfahret, wie der HERR Agypten und Israel scheide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Dann werden zu mir herabkommen alle diese deine Knechte und mirzu Fufte fallen und sagen: Zeuch aus, du und alles Volk, das unter dir ist. Danach will ich ausziehen, und er ging von Pharao mit grimmigem Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Der HERR aber sprach zu Mose: Pharao horet euch nicht, auf daß viele Wunder geschehen in Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Und Mose und Aaron haben diese Wunder alle getan vor Pharao; aber der HERR verstockte ihm sein Herz, daß er die Kinder Israel nicht lassen wollte aus seinem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Der HERR aber sprach zu Mose und Aaron in Agyptenland:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Dieser Mond soil bei euch der erste Mond sein; und von ihm sollt ihr die Monde des Jahrs anheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Saget der ganzen Gemeine Israel und sprechet: Am zehnten Tage dieses Monden nehme ein jeglicher ein Lamm, wo ein Hausvater ist, je ein Lamm zu einem Hause!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Wo ihrer aber in einem Hause zum Lamm zu wenig sind, so nehme er\'s und sein nachster Nachbar an seinem Hause, bis ihrer so viel wird, daß sie das Lamm aufessen mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ihr sollt aber ein solch Lamm nehmen, da kein Fehl an ist, ein Mannlein und eines Jahrs alt; von den Lammern und Ziegen sollt ihr\'s nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Und sollt es behalten bis auf den vierzehnten Tag des Monden. Und ein jegliches Hauflein im ganzen Israel soil es schlachten zwischen Abends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und sollt seines Bluts nehmen und beide Pfosten an der Tur und die oberste Schwelle damit bestreichen an den Hausern, da sie es innen essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Und sollt also Fleisch essen in derselben Nacht, am Feuer gebraten, und ungesauert Brot, und sollt es mit bittern Salsen essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ihr sollt es nicht roh essen, noch mit Wasser gesotten, sondern am Feuer gebraten, sein Haupt mit seinen Schenkeln und Eingeweide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Und sollt nichts davon uberlassen bis morgen; wo aber etwas uberbleibet bis morgen, sollt ihr\'s mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Also sollt ihr\'s aber essen: Urn eure Lenden sollt ihr gegurtet sein und eure Schuhe an euren Fuften haben und Stabe in euren Handen, und sollt es essen, als die hinwegeilen; denn es ist des HERRN Passah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Denn ich will in derselbigen Nacht durch Agyptenland gehen und alle Erstgeburt schlagen in Agyptenland, beide unter Menschen und Vieh. Und will meine Strafe beweisen an alien Gottern der Agypter, ich, der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut soil euer Zeichen sein an den Hausern, darin ihr seid, daß, wenn ich das Blut sehe, vor euch übergehe, und euch nicht die Plage widerfahre, die euch verderbe, wenn ich Agyptenland schlage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und sollt diesen Tag haben zum Gedachtnis und sollt ihn feiern dem HERRN zum Fest, ihr und alle eure Nachkommen, zurewigen Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage sollt ihr ungesauert Brot essen; namlich am ersten Tage sollt ihr aufhoren mit gesauertem Brot in euren Hausern. Wergesauert Brot isset vom ersten Tage an, bis auf den siebenten, des Seele soil ausgerottet werden von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Der erste Tag soil heilig sein, daß ihr zusammenkommet; und der siebente soil auch heilig sein, daß ihr zusammenkommet. Keine Arbeit sollt ihr drinnen tun, ohne was zur Speise gehoret fur allerlei Seelen, dasselbe allein moget ihr fur euch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und haltetob dem ungesauerten Brot, denn eben an demselben Tage habe ich euer Heer aus Agyptenland gefuhret; darum sollt ihr diesen Tag halten und alle eure Nachkommen zurewigen Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Am vierzehnten Tage des ersten Monden, des Abends, sollt ihr ungesauert Brot essen, bis an den einundzwanzigsten Tag des Monden an dem Abend,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'daß man sieben Tage kein gesauert Brotfinde in euren Hausern. Denn wer gesauert Brot isset, des Seele soil ausgerottet werden von der Gemeinde Israel, es sei ein Fremdling Oder Einheimischer im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Darum so esset kein gesauert Brot, sondern eitel ungesauert Brot in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Und Mose forderte alle Altesten in Israel und sprach zu ihnen: Leset aus und nehmet Schafe jedermann fur sein Gesinde und schlachtet das Passah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Und nehmet ein Buschel Ysop und tunket in das Blut in dem Becken und beruhret damit die Uberschwelle und die zween Pfosten. Und gehe kein Mensch zu seiner Haustur heraus bis an den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Denn der, HERR wird umhergehen und die Agypter plagen. Und wenn er das Blut sehen wird an der Uberschwelle und an den zween Pfosten, wird er vor der Tur übergehen und den Verderber nicht in eure Hauser kommen lassen zu plagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Darum so halte diese Weise fur dich und deine Kinder ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und wenn ihr ins Land kommet, das euch der HERR geben wird, wie er geredet hat, so haltet diesen Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und wenn eure Kinder werden zu euch sagen: Was habt ihr da fur einen Dienst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'soilt ihr sagen: Es ist das Passahopfer des HERRN, der vor den Kindern Israel uberging in Agypten, da er die Agypter plagte und unsere Hauser errettete. Da neigte sich das Volk und bückte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Und die Kinder Israel gingen hin und taten, wie der HERR Mose und Aaron geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Und zur Mitternacht schlug der HERR alle Erstgeburt in Agyptenland, von dem ersten Sohn Pharaos an, der auf seinem Stuhl saß, bis auf den ersten Sohn des Gefangenen im Gefangnis, und alle Erstgeburt des Viehes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stand Pharao auf und alle seine Knechte in derselben Nacht und alle Agypter, und ward ein grofi Geschrei in Agypten; denn es war kein Haus, da nicht ein Toter innen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Und er forderte Mose und Aaron in der Nacht und sprach: Machet euch auf und ziehet aus von meinem Volk, ihr und die Kinder Israel; gehet hin und dienet dem HERRN, wie ihr gesagt habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Nehmet auch mit euch eure Schafe und Rinder, wie ihr gesagt habt; gehet hin und segnet mich auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Und die Agypter drungen das Volk, daß sie es eilend aus dem Lande trieben; denn sie sprachen: Wir sind alle des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Und das Volk trug den rohen Teig, ehe denn er versauert war, zu ihrer Speise, gebunden in ihren Kleidern, auf ihren Achseln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Und die Kinder Israel hatten getan, wie Mose gesagt hatte, und von den Agyptern gefordert silberne und guldene Gerate und Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Dazu hatte der HERR dem Volk Gnade gegeben vor den Agyptern, daß sie ihnen leiheten; und entwandten es den Agyptern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Also zogen aus die Kinder Israel von Raemses gen Suchoth, sechshunderttausend Mann zu Fuli ohne die Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Und zog auch mit ihnen viel Pdbelvolk und Schafe und Rinder und fast viel Viehes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Und sie buken aus dem rohen Teige, den sie aus Agypten brachten, ungesauerte Kuchen; denn es war nicht gesauert, weil sie aus Agypten gestolien wurden, und konnten nicht verziehen und hatten ihnen sonst keine Zehrung zubereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Die Zeit aber, die die Kinder Israel in Agypten gewohnet haben, istvierhundertunddreüüg Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Da dieselben urn waren, ging das ganze Heer des HERRN auf einen Tag aus Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Darum wird diese Nacht dem HERRN gehalten, daß er sie aus Agyptenland geführet hat; und die Kinder Israel sollen sie dem HERRN halten, sie und ihre Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und der HERR sprach zu Mose und Aaron: Dies ist die Weise, Passah zu halten: Kein Fremder soil davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Aber wer ein erkaufter Knecht ist, den beschneide man, und dann esse er davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Hausgenoü und Mietling sollen nicht davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soil man\'s essen; ihr soilt nichts von seinem Fleisch hinaus vor das Haus tragen; und soilt kein Bein an ihm zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeine Israel soil solches tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'So aber ein Fremdling bei dir wohnet und dem HERRN das Passah halten will, der beschneide alles, was mannlich ist; als dann mache ersich herzu, dad er solches tue, und sei wie ein Einheimischer des Landes; denn kein Unbeschnittener soil davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Einerlei Gesetz sei dem Einheimischen und dem Fremdling, der unter euch wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Und alle Kinder Israel taten, wie der HERR Mose und Aaron hatte geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Also fuhrete der HERR auf einen Tag die Kinder Israel aus Agyptenland mit ihrem Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Heilige mir alle Erstgeburt, die allerlei Mutter bricht, bei den Kindern Israel, beide unter den Menschen und dem Vieh; denn sie sind mein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Da sprach Mose zum Volk: Gedenket an diesen Tag, an dem ihr aus Agypten, aus dem Diensthause, gegangen seid, daß der HERR euch mit machtiger Hand von hinnen hat ausgefuhret; darum sollst du nicht Sauerteig essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute seid ihrausgegangen, in dem Mond Abib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Wenn dich nun der HERR bringen wird in das Land der Kanaaniter, Hethiter, Amoriter, Heviter und Jebusiter, das er deinen Vatern geschworen hat, dir zu geben, ein Land, da Milch und Honig innen fleußt, so sollst du diesen Dienst halten in diesem Mond.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage sollst du ungesauert Brot essen, und am siebenten Tage ist des HERRN Fest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Darum sollst du sieben Tage ungesauert Brot essen, daß bei dir kein Sauerteig noch gesauert Brot gesehen werde an alien deinen Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und sollt euren Sohnen sagen an dem selbigen Tage: Solches halten wir um deswillen, das uns der HERR getan hat, da wir aus Agypten zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Darum soil dir\'s sein ein Zeichen in deiner Hand und ein Denkmal vor deinen Augen, auf daß des HERRN Gesetz sei in deinem Munde, daß der HERR dich mit machtiger Hand aus Agypten gefuhret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Darum halte diese Weisezu seiner Zeit jahrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Wenn dich nun der HERR ins Land der Kanaaniter gebracht hat, wie er dir und deinen Vatern geschworen hat, und dir\'s gegeben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'so sollst du aussondern dem HERRN alles, was die Mutter bricht, und die Erstgeburt unter dem Vieh, das ein Mannlein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Die Erstgeburt vom Esel sollst du losen mit einem Schaf; wo du es aber nicht losest, so brich ihm das Genick. Aber alle erste Menschengeburt unter deinen Kindern sollst du losen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und wenn dich heute Oder morgen dein Kind wird fragen: Was ist das? sollst du ihm sagen: Der HERR hat uns mit machtiger Hand aus Agypten, von dem Diensthause, gefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Denn da Pharao hart war, uns loszulassen, erschlug der HERR alle Erstgeburt in Agyptenland, von der Menschen Erstgeburt an bis an die Erstgeburt des Viehes. Darum opfere ich dem HERRN alles, was die Mutter bricht, das ein Mannlein ist, und die Erstgeburt meiner Kinder lose ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und das soil direin Zeichen in deiner Hand sein und ein Denkmal vor deinen Augen, daß uns der HERR hat mit machtiger Hand aus Agypten gefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Da nun Pharao das Volk gelassen hatte, führete sie Gott nicht auf die Straße durch der Philister Land, die am nachsten war; denn Gott gedachte, es mochte das Volk gereuen, wenn sie den Streit sahen, und wieder nach Agypten umkehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Darum führete erdas Volk um auf die Straße durch die Wuste am Schilfmeer. Und die Kinder Israel zogen gerustet aus Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Mose nahm mitsich die Gebeine Josephs. Denn er hatte einen Eid von den Kindern Israel genommen und gesprochen: Gott wird euch heimsuchen; so führet meine Gebeine mit euch von hinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Also zogen sie aus von Suchoth und lagerten sich in Etham, vom an der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Und der HERR zog vor ihnen her, des Tages in einer Wolkensaule, daß er sie den rechten Weg führete, und des Nachts in einer Feuersaule, daß er ihnen leuchtete, zu reisen Tag und Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Die Wolkensaule wich nimmervon dem Volk des Tages, noch die Feuersaule des Nachts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Rede mit den Kindern Israel und sprich, daß sie sich herumlenken und sich lagern gegen dem Tal Hiroth, zwischen Migdol und dem Meer, gegen Baal- Zephon, und daselbst gegenüber sich lagern ans Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Denn Pharao wird sagen von den Kindern Israel: Sie sind verirret im Lande, die Wuste hat sie beschlossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Und ich will sein Herz verstocken, daß er ihnen nachjage, und will an Pharao und an aller seiner Macht Ehre einlegen, und die Agypter sollen inne werden, daß ich der HERR bin. Und sie taten also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Und da es dem Konige in Agypten ward angesagt, daß das Volk war geflohen, ward sein Herz verwandelt und seiner Knechte gegen das Volk, und sprachen: Warum haben wir das getan, daß wir Israel haben gelassen, daß sie uns nicht dieneten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und erspannte seinen Wagen an und nahm sein Volk mit ihm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'und nahm sechshundert auserlesene Wagen, und was sonst von Wagen in Agypten war, und die Hauptleute fiber all sein Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Denn der HERR verstockte das Herz Pharaos, des Konigs in Agypten, daß er den Kindern Israel nachjagete. Aber die Kinder Israel waren durch eine hohe Hand ausgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Und die Agypter jagten ihnen nach und ereileten sie (da sie sich gelagert hatten am Meer) mit Rossen und Wagen und Reitern und allem Heer des Pharao im Tal Hiroth, gegen Baal-Zephon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Und da Pharao nahe zu ihnen kam, huben die Kinder Israel ihre Augen auf, und siehe, die Agypter zogen hinter ihnen her; und sie furchteten sich sehr und schrieen zu dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Und sprachen zu Mose: Waren nicht Graber in Agypten, daß du uns mußtest wegfuhren, daß wir in der Wuste sterben? Warum hast du das getan, daß du uns aus Agypten gefuhret hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Ist\'s nicht das, das wir dir sagten in Agypten: Hore auf und laß uns den Agyptern dienen? Denn es ware uns ja besser, den Agyptern zu dienen, denn in der Wuste sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mose sprach zum Volk: Fürchtet euch nicht, stehet fest und sehet zu was fur ein Heil der HERR heute an euch tun wird. Denn diese Agypter, die ihr heute sehet, werdet ihr nimmermehr sehen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Der HERR wird fur euch streiten, und ihr werdet stille sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Der HERR sprach zu Mose: Was schreiest du zu mir? Sage den Kindern Israel, daß sie ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Du aber heb deinen Stab auf und recke deine Hand uber das Meer und teile es voneinander, daß die Kinder Israel hineingehen, mitten hindurch auf dem Trockenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Siehe, ich will das Herz der Agypter verstocken, dalj sie euch nachfolgen. So will ich Ehre einlegen an dem Pharao und an aller seiner Macht, an seinen Wagen und Reitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Und die Agypter sollen\'s inne werden, daß ich der HERR bin, wenn ich Ehre eingelegt habe an Pharao und an seinen Wagen und Reitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Da erhub sich der Engel Gottes, der vordem Heer Israels herzog, und machte sich hinter sie; und die Wolkensaule machte sich auch von ihrem Angesicht und trat hinter sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'und kam zwischen das Heer der Agypter und das Heer Israels. Es war aber eine finstere Wolke und erleuchtete die Nacht, daß sie die ganze Nacht, diese und jene, nicht zusammenkommen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Da nun Mose seine Hand reckte uber das Meer, lieli es der HERR hinwegfahren durch einen starken Ostwind die ganze Nacht und machte das Meer trocken; und die Wasser teilten sich voneinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Und die Kinder Israel gingen hinein, mitten ins Meer auf dem T rockenen; und das Wasser war ihnen fur Mauern zur Rechten und zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Und die Agypter folgten und gingen hinein ihnen nach, alle Rosse Pharaos und Wagen und Reiter, mitten ins Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Als nun die Morgenwache kam, schauete der HERR auf der Agypter Heer aus der Feuersaule und Wolke und machte ein Schrecken in ihrem Heer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'und stieli die Rader von ihren Wagen, sturzte sie mit Ungestum. Da sprachen die Agypter: Lasset uns fliehen von Israel! Der HERR streitet fur sie wider die Agypter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Aber der HERR sprach zu Mose: Recke deine Hand aus uber das Meer, daß das Wasser wieder herfalle uber die Agypter, uber ihre Wagen und Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Da reckte Mose seine Hand aus uber das Meer; und das Meer kam wieder vor Morgens in seinen Strom, und die Agypter flohen ihm entgegen. Also sturzte sie der HERR mitten ins Meer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'da($ das Wasser wiederkam und bedeckte Wagen und Reiter und alle Macht des Pharao, die ihnen nachgefolget waren ins Meer, daß nicht einer aus ihnen uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Aber die Kinder Israel gingen trocken mitten durchs Meer; und das Wasser war ihnen fur Mauern zur Rechten und zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Also half der HERR Israel an dem Tage von der Agypter Hand. Und sie sahen die Agypter tot am Ufer des Meers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'und die grolie Hand, die der HERR an den Agyptern erzeigt hatte. Und das Volk furchtete den HERRN, und glaubten ihm und seinem Knechte Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Da sang Mose und die Kinder Israel dies Lied dem HERRN und sprachen: Ich will dem HERRN singen; denn erhat eine herrliche Tat getan: Roü und Wagen hat er ins Meer gesturzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Der HERR ist meine Starke und Lobgesang und ist mein Heil. Das ist mein Gott, ich will ihn preisen; er ist meines Vaters Gott, ich will ihn erheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Der HERR ist der rechte Kriegsmann. HERR ist sein Name.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Wagen Pharaos und seine Macht warf er ins Meer, seine auserwahlten Hauptleute versanken im Schilfmeer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Die Tiefe hat sie bedeckt, sie fielen zu Grund wie die Steine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'HERR, deine rechte Hand tut grolie Wunder; HERR, deine rechte Hand hat die Feinde zerschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Und mit deiner grolien Herrlichkeit hast du deine Widerwartigen gesturzt; denn da du deinen Grimm auslieliest, verzehrte er sie wie Stoppeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Durch dein Biasen taten sich die Wasser auf, und die Fluten stunden auf Haufen; die Tiefe wallete voneinander mitten im Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Der Feind gedachte: Ich will ihnen nachjagen und erhaschen und den Raub austeilen und meinen Mut an ihnen kuhlen; ich will mein Schwert ausziehen, und meine Hand soil sie verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Da lieliest du deinen Wind biasen, und das Meer bedeckte sie, und sanken unter wie Blei im machtigen Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'HERR, wer ist dir gleich unter den Gottern? Wer ist dir gleich, der so machtig, heilig, schrecklich, loblich und wundertatig sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Da du deine rechte Hand ausrecktest, verschlang sie die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du hast geleitet durch deine Barmherzigkeit dein Volk, das du erloset hast, und hast sie gefuhret durch deine Starke zu deiner heiligen Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Da das die Volker horeten, erbebeten sie; Angst kam die Philister an;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'da erschraken die Fursten Edoms; Zittern kam die Gewaltigen Moabs an; alle Einwohner Kanaans wurden feig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Lali uber sie fallen Erschrecken und Furcht durch deinen groüen Arm, daß sie erstarren wie die Steine, bis dein Volk, HERR, hindurchkomme, bis das Volk hindurchkomme, das du erworben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Bringe sie hinein und pflanze sie auf dem Berge deines Erbteils, den du, HERR, dir zur Wohnung gemacht hast, zu deinem Heiligtum, HERR, das deine Hand bereitet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Der HERR wird Konig sein immer und ewig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn Pharao zog hinein ins Meer mit Rossen und Wagen und Reitern, und der HERR lieli das Meer wieder uber sie fallen. Aber die Kinder Israel gingen trocken mitten durchs Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Und Mirjam, die Prophetin, Aarons Schwester, nahm eine Pauke in ihre Hand; und alle Weiber folgten ihr nach hinaus mit Pauken am Reigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam sang ihnen vor: Lasset uns dem HERRN singen; denn er hat eine herrliche Tat getan, Mann und Ro IS hat er ins Meer gesturzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Mose liel J die Kinder Israel ziehen vom Schilfmeer hinaus zu der Wuste Sur. Und sie wanderten drei Tage in der Wuste, daß sie kein Wasser fanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Da kamen sie gen Mara; aber sie konnten des Wassers zu Mara nicht trinken, denn es war fast bitter. Daher hieü man den Ort Mara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da murrete das Volk wider Mose und sprach: Was sollen wir trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Er schrie zu dem HERRN; und der HERR weisete ihm einen Baum, den tat er ins Wasser; da ward es suß,. Daselbst stellete er ihnen ein Gesetz und ein Recht und versuchte sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'und sprach: Wirstdu derßtimme des HERRN, deines Gottes, gehorchen und tun, was recht ist vor ihm, und zu Ohren fassen seine Gebote und halten alle seine Gesetze, so will ich der Krankheit keine auf dich legen, die ich auf Agypten gelegt habe; denn ich bin der HERR, dein Arzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Und sie kamen nach Elim, da waren zwolf Wasserbrunnen und siebenzig Palmbaume; und lagerten sich daselbst ans Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Von Elim zogen sie, und kam die ganze Gemeine der Kinder Israel in die Wuste Sin, die da liegt zwischen Elim und Sinai, am funfzehnten Tage des andern Monden, nachdem sie aus Agypten gezogen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Und es murrete die ganze Gemeine der Kinder Israel wider Mose und Aaron in der Wuste');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'und sprachen: Wollte Gott, wir waren in Agypten gestorben durch des HERRN Hand, da wir bei den Fleischtopfen salien und hatten die Fulle Brot zu essen! Denn ihr habt uns darum ausgefuhret in diese Wuste, dafi ihr diese ganze Gemeine Hungers sterben lasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sprach der HERR zu Mose: Siehe, ich will euch Brot vom Himmel regnen lassen, und das Volk soli hinausgehen und sammeln taglich, was es des Tages bedarf, dafi ich\'s versuche, ob es in meinem Gesetz wandele Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Des sechsten Tages aber sollen sie sich schicken, daß sie zwiefaltig eintragen, weder sie sonst taglich sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Mose und Aaron sprachen zu alien Kindern Israel: Am Abend sollt ihr inne werden, daß euch der HERR aus Agyptenland gefuhret bat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'und des Morgens werdet ihr des HERRN Herrlichkeit sehen; denn er hat euer Murren wider den HERRN gehoret. Was sind wir, dafi ihr wider uns murret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Weiter sprach Mose: Der HERR wird euch am Abend Fleisch zu essen geben und am Morgen Brats die Fulle, darum daß der HERR euer Murren gehoret hat, das ihr wider ihn gemurret habt. Denn was sind wir? Euer Murren ist nicht wider uns, sondern wider den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Und Mose sprach zu Aaron: Sage der ganzen Gemeine der Kinder Israel: Kommt herbei vor den HERRN; denn er hat euer Murren gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Und da Aaron also redete zu der ganzen Gemeine der Kinder Israel, wandten sie sich gegen die Wuste; und siehe, die Herrlichkeit des HERRN erschien in einer Wolke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und der HERR sprach zu Mose:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe der Kinder Israel Murren gehoret. Sage ihnen: Zwischen Abend sollt ihr Fieisch zu essen haben und am Morgen Brats satt werden und inne werden, daß ich der HERR, euer Gott bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und am Abend kamen Wachteln herauf und bedeckten das Heer. Und am Morgen lag der Tau urn das Heer her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und als der Tau weg war, siehe, da lag es in der Wuste rund und klein, wie der Reif auf dem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Und da es die Kinder Israel sahen, sprachen sie untereinander: Das ist Man; denn sie wuliten nicht, was es war. Mose aber sprach zu ihnen: Es ist das Brot, das euch der HERR zu essen gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Das ist\'s aber, das der HERR geboten hat: Ein jeglicher sammle des, soviel er fur sich essen mag, und nehme ein Gomor auf ein jeglich Haupt, nach der Zahl der Seelen in seiner Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Kinder Israel taten also und sammelten, einer viel, der andere wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Aber da man\'s mit dem Gomor maß, fand der nicht drüber, der viel gesammelt hatte, und der nicht drunter, der wenig gesammelt hatte, sondern ein jeglicher hatte gesammelt, soviel er fur sich essen mochte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Und Mose sprach zu ihnen: Niemand lasse etwas davon uber bis morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Aber sie gehorchten Mose nicht. Und etliche ließen davon uber bis morgen; da wuchsen Wurmer drinnen, und ward stinkend. Und Mose ward zornig auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Sie sammelten aber desselben alle Morgen, soviel ein jeglicher fur sich essen mochte. Wenn aber die Sonne heiß. schien, zerschmolz es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Und des sechsten Tages sammelten sie des Brats zwiefaltig, je zwei Gomor fur einen. Und alle Obersten der Gemeine kamen hinein und verkundigten es Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Und er sprach zu ihnen: Das ist\'s, das der HERR gesagt hat: Morgen ist der Sabbat der heiligen Ruhe des HERRN; was ihr backen wollt, das backet, und was ihr kochen wollt, das kochet; was aber übrig ist, das lasset bleiben, dafi es behalten werde bis morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie ließen\'s bleiben bis morgen, wie Mose geboten hatte; da ward es nicht stinkend, und war auch kein Wurm drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sprach Mose: Esset das heute, denn es ist heute der Sabbat des HERRN; ihr werdet es heute nicht finden auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr sammeln, aber der siebente Tag ist der Sabbat, darinnen wird\'s nicht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Aber am siebenten Tage gingen etliche vom Volk hinaus zu sammeln, und fanden nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sprach der HERR zu Mose: Wie lange weigert ihreuch, zu halten meine Gebote und Gesetze?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Sehet, der HERR hat euch den Sabbat gegeben; darum gibt er euch am sechsten Tage zweier Tage Brot. So bleibe nun ein jeglicher in dem Seinen, und niemand gehe heraus von seinem Ort des siebenten Tages!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Also feierte das Volk des siebenten Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Und das Haus Israel hiefi es Man. Und es war wie Koriandersamen und weili, und hatte einen Schmackwie Semmel mit Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Mose sprach: Das ist\'s, das der HERR geboten hat: Fulle ein Gomor davon, zu behalten auf eure Nachkommen, auf dafi man sehe das Brot, damit ich euch gespeiset habe in der Wuste, da ich euch aus Agyptenland führte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Und Mose sprach zu Aaron: Nimm ein Kruglein und tu ein Gomor voll Man drein; und lali es vor dem HERRN, zu behalten auf eure Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Wie der HERR Mose geboten hat, also lieli es Aaron daselbst vor dem Zeugnis, zu behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Und die Kinder Israel alien Man vierzig Jahre, bis daß sie zu dem Lande kamen, da sie wohnen sollten; bis an die Grenze des Landes Kanaan alien sie Man.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ein Gomor aber ist das zehnte Teil eines Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Und die ganze Gemeine der Kinder Israel zog aus der Wuste Sin, ihre Tagereisen, wie ihnen der HERR befahl, und lagerten sich in Raphidim. Da hatte das Volk kein Wasser zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Und sie zankten mit Mose und sprachen: Gebet uns Wasser, daß wir trinken! Mose sprach zu ihnen: Was zanket ihr mit mir? Warum versuchet ihr den HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Da aber das Volk daselbst durstete nach Wasser, murreten sie wider Mose und sprachen: Warum hast du uns lassen aus Agypten ziehen, daß du uns, unsere Kinder und Vieh Durst sterben lieliest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Mose schrie zum HERRN und sprach: Wie soil ich mit dem Volk tun? Es fehlet nicht weit, sie werden mich noch steinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Der HERR sprach zu ihm: Gehe vorhin vor dem Volk und nimm etliche Alteste von Israel mit dir; und nimm deinen Stab in deine Hand, damit du das Wasser schlugest, und gehe hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Siehe, ich will daselbst stehen vor dir auf einem Fels in Horeb; da sollstdu den Felsen schlagen, so wird Wasser heraus laufen, daß das Volk trinke. Mose tat also vor den Altesten von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Da hieli man den Ort Massa und Meriba urn des Zanks willen der Kinder Israel, und daß sie den HERRN versucht und gesagt hatten: Ist der HERR unter uns Oder nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Da kam Amalek und stritt wider Israel in Raphidim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Mose sprach zu Josua: Erwahle uns Manner, zeuch aus und streite wider Amalek; morgen will ich auf des Hügels Spitze stehen und den Stab Gottes, in meiner Hand haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Josua tat, wie Mose ihm sagte, daß er wider Amalek stritte. Mose aber und Aaron und Hur gingen auf die Spitze des Hügels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Und dieweil Mose seine Hande emporhielt, siegte Israel; wenn er aber seine Hande niederliefi, siegte Amalek.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Aber die Hande Moses waren schwer; darum nahmen sie einen Stein und legten ihn unter ihn, daß er sich darauf setzte. Aaron aber und Hur unter hielten ihm seine Hande, auf jeglicher Seite einer. Also blieben seine Hande steif, bis die Sonne unterging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Und Josua dampfte den Amalek und sein Volk durch des Schwerts Scharfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Und der HERR sprach zu Mose: Schreibe das zum Gedachtnis in ein Buch und befiehl es in die Ohren Josuas; denn ich will den Amalek unter dem Himmel austilgen, daß man sein nicht mehr gedenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Mose bauete einen Altar und hieli ihn: Der HERR Nissi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Denn er sprach: Es ist ein Malzeichen bei dem Stuhl des HERRN, daß der HERR streiten wird wider Amalek von Kind zu Kindeskind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Und da Jethro, der Priester in Midian, Moses Schwiegervater, horete alles, was Gott getan hatte mit Mose und seinem Volk Israel, daß der HERR Israel hatte aus Agypten gefuhret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'nahm er Zipora, Moses Weib, die er hatte zurückgesandt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'samt ihren zween Sohnen, dereine hieli Gersom; denn er sprach: Ich bin ein Gast worden in fremdem Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'und der andere Elieser; denn er sprach: Der Gott meines Vaters ist meine Hilfe gewesen und hat mich errettet von dem Schwert Pharaos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Da nun Jethro, Moses Schwaher, und seine Sohne und sein Weib zu ihm kamen in die Wuste, an den Berg Gottes, da er sich gelagert hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'lieli er Mose sagen: Ich, Jethro, dein Schwaher, bin zu dir kommen, und dein Weib und ihre beiden Sohne mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da ging ihm Mose entgegen hinaus und neigte sich vor ihm und kussete ihn. Und da sie sich untereinander gegrüftet hatten, gingen sie in die Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Da erzahlete Mose seinem Schwaher alles, was der HERR Pharao und den Agyptern getan hatte Israels halben, und alle die Mühe, die ihnen auf dem Wege begegnet war, und dafi sie der HERR errettet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jethro aber freuete sich all des Guten, das der HERR Israel getan hatte, daß er sie errettet hatte von der Agypter Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gelobet sei der HERR, der euch errettet hat von der Agypter und Pharaos Hand, der weiß sein Volk von der Agypter Hand zu erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nunweiftich, daß der HERR grafter ist denn alle Gotter, darum daß sie Hochmut an ihnen geubet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Und Jethro, Moses Schwaher, nahm Brandopfer und opferte Gott. Da kam Aaron und alle Altesten in Israel, mit Moses Schwaher das Brot zu essen vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Des andern Morgens setzte sich Mose, das Volk zu richten; und das Volk stund um Mose her von Morgen an bis zu Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Da aber sein Schwaher sah alles, was er mit dem Volk tat, sprach er: Was ist, das du tust mit dem Volk? Warum sitzest du allein, und alles Volk stehet um dich her von Morgen an bis zu Abend?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mose antwortete ihm: Das Volk kommt zu mir und fragen Gott um Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Denn wo sie was zu schaffen haben, kommen sie zu mir, daß ich richte zwischen einem jeglichen und seinem Nachsten und zeige ihnen Gottes Rechte und seine Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Sein Schwaher sprach zu ihm: Es istnichtgut, das du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du machest dich zu mude, dazu das Volk auch, das mit dir ist. Das Geschaft ist dir zu schwer, du kannst es allein nicht ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Aber gehorche meiner Stimme; ich will dir raten, und Gott wird mit dir sein. Pflege du des Volks vor Gott und bringe die Geschafte vor Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'und stelle ihnen Rechte und Gesetze, daß du sie lehrest den Weg, darin sie wandeln, und die Werke, die sie tun sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Sieh dich aber um unter allem Volk nach redlichen Leuten, die Gott furchten, wahrhaftig und dem Geiz feind sind; die setze uber sie, etliche uber tausend, uberhundert, uber funfzig und uber zehn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'daß sie das Volk allezeit richten; wo aber eine grofte Sache ist, daß sie dieselbe an dich bringen, und sie alle geringen Sachen richten. So wird dir\'s leichter werden, und sie mit dir tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Wirst du das tun, so kannst du ausrichten, was dir Gott gebeut, und all dies Volk kann mit Frieden an seinen Ort kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Mose gehorchte seines Schwahers Wort und tat alles, was er sagte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'und redliche Leute aus dem ganzen Israel und machte sie zu Hauptern uber das Volk, etliche uber tausend, uber hundert, uber funfzig und uber zehn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'daß sie das Volk allezeit richteten, was aber schwere Sachen waren, zu Mose brachten, und die kleinen Sachen sie richteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Also lieft Mose seinen Schwaher in sein Land ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Mond nach dem Ausgang der Kinder Israel aus Agyptenland kamen sie dieses Tages in die Wuste Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Denn sie waren ausgezogen von Raphidim und wollten in die Wuste Sinai; und lagerten sich in der Wuste daselbst gegen dem Berg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Und Mose stieg hinauf zu Gott. Und der HERR rief ihm vom Berge und sprach: So sollst du sagen zu dem Hause Jakob und verkundigen den Kindern Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ihr habt gesehen, was ich den Agyptern getan habe, und wie ich euch getragen habe auf Adlersflugeln und habe euch zu mir gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Werdet ihr nun meiner Stimme gehorchen und meinen Bund halten, so sollt ihr mein Eigentum sein vor alien Volkern; denn die ganze Erde ist mein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Und ihr sollt mir ein priesterlich Konigreich und ein heiliges Volk sein. Das sind die Worte, die du den Kindern Israel sagen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Mose kam und forderte die Altesten im Volk und legte ihnen alle diese Worte vor, die der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Und alles Volk antwortete zugleich und sprachen: Alles, was der HERR geredet hat, wollen wir tun. Und Mose sagte die Rede des Volks dem HERRN wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Und der HERR sprach zu Mose: Siehe, ich will zu dir kommen in einer dicken Wolke, auf daß dies Volk meine Worte hore, die ich mit dir rede, und glaube direwiglich. Und Mose verkündigte dem HERRN die Rede des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Der HERR sprach zu Mose: Gehe hin zum Volk und heilige sie heute und morgen, daß sie ihre Kleider waschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'und bereitseien auf den dritten Tag. Denn am dritten Tage wird der HERR vor allem Volk herabfahren auf den Berg Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Und mache dem Volk ein Gehege umher und sprich zu ihnen: Hütet euch, daß ihr nicht auf den Berg steiget, noch sein Ende anruhret; denn wer den Berg anrühret, soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Keine Hand soil ihn anruhren, sondern ersoll gesteinigt Oder mit Geschoft erschossen werden; es sei ein Tier Oder Mensch, so soil er nicht leben. Wenn es aber lange tonen wird, dann sollen sie an den Berg gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Mose stieg vom Berge zum Volk und heiligte sie, und sie wuschen ihre Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und ersprach zu ihnen: Seid bereitaufden dritten Tag, und keiner nahe sich zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Als nun der dritte Tag kam und Morgen war, da hub sich ein Donnern und Blitzen und eine dicke Wolke auf dem Berge und ein Ton einer sehr starken Posaune. Das ganze Volk aber, das im Lager war, erschrak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Und Moseführete das Volk aus dem Lager Gott entgegen; und sie traten unten an den Berg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Der ganze Berg aber Sinai rauchte, darum dafi der HERR herab auf den Berg fuhr mit Feuer; und sein Rauch ging auf wie ein Rauch vom Ofen, daß der ganze Berg sehr bebete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und der Posaunen Ton ward immer starker. Mose redete, und Gott antwortete ihm laut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Als nun der HERR herniederkommen war auf den Berg Sinai, oben auf seine Spitze, forderte er Mose oben auf die Spitze des Berges, und Mose stieg hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Da sprach der HERR zu ihm: Steig hinab und zeuge dem Volk, daß sie nicht herzubrechen zum HERRN, daß sie sehen, und viele aus ihnen fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Dazu die Priester, die zum HERRN nahen, sollen sich heiligen, daß sie der HERR nicht zerschmettere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mose aber sprach zum HERRN: Das Volk kann nicht auf den Berg Sinai steigen; denn du hast uns bezeuget und gesagt: Mache ein Gehege urn den Berg und heilige ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Und der HERR sprach zu ihm: Gehe hin, steige hinab; du und Aaron mit dir soli heraufsteigen; aber die Priester und das Volk sollen nicht herzubrechen, daß sie hinaufsteigen zu dem HERRN, daß ersie nicht zerschmettere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Und Mose stieg herunterzum Volk und sagte es ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Und Gott redete alle diese Worte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin der HERR, dein Gott, der ich dich aus Agyptenland, aus dem Diensthause, gefuhret habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keine andern Gotter neben mir haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein Bildnis noch irgend ein Gleichnis machen weder des, das oben im Himmel, noch des, das unten auf Erden, Oder des, das im Wasser unter der Erde ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Bete sie nicht an und diene ihnen nicht. Denn ich, der HERR, dein Gott, bin ein eifriger Gott, der da heimsuchet der Vater Missetat an den Kindern bis in das dritte und vierte Glied, die mich hassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'und tue Barmherzigkeit an vielen Tausenden, die mich liebhaben und meine Gebote halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen des HERRN, deines Gottes, nicht miftbrauchen; denn der HERR wird den nicht ungestraft lassen, der seinen Namen miftbraucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbattages, daß du ihn heiligest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und alle deine Dinge beschicken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'aber am siebenten Tage ist der Sabbat des HERRN, deines Gottes. Da sollst du kein Werk tun, noch dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, noch dein Vieh, noch dein Fremdling, der in deinen Toren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat der HERR Himmel und Erde gemacht und das Meer und alles, was drinnen ist, und ruhete am siebenten Tage. Darum segnete der HERR den Sabbattag und heiligte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Du sollst deinen Vater und deine Mutter ehren, auf daß du lange lebest im Lande, das dir der HERR, dein Gott gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst kein falsch Zeugnis reden wider deinen Nachsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Laft dich nicht gelusten deines Nachsten Hauses. Laft dich nicht gelusten deines Nachsten Weibes, noch seines Knechts, noch seiner Magd, noch seines Ochsen, noch seines Esels, noch alles, das dein Nachster hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Und alles Volk sah den Donner und Blitz und den Ton der Posaune und den Berg rauchen. Da sie aber solches sahen, flohen sie und traten von feme;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'und sprachen zu Mose: Rede du mit uns, wir wollen gehorchen, und laft Gott nicht mit uns reden, wir mochten sonst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mose aber sprach zum Volk: Furchtet euch nicht; denn Gott ist kommen, daß er euch versuchte, und daß seine Furcht euch vor Augen ware, daß ihr nicht sundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Also trat das Volk von feme; aber Mose machte sich hinzu ins Dunkel, da Gott innen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Und der HERR sprach zu ihm: Also sollst du den Kindern Israel sagen: Ihr habt gesehen, daß ich mit euch vom Himmel geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Darum sollt ihr nichts neben mir machen, silberne und güldene Gotter sollt ihr nicht machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar von Erde mache mir, darauf du dein Brandopfer und Dankopfer, deine Schafe und Rinder opferst. Denn an welchem Ort ich meines Namens Gedachtnis stiften werde, da will ich zu dir kommen und dich segnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Und so du mir einen steinernen Altar willst machen, sollst du ihn nicht von gehauenen Steinen bauen; denn wo du mit deinem Messer daruber fahrest, so wirst du ihn entweihen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Du sollst auch nicht auf Stufen zu meinem Altar steigen, daß nicht deine Scham aufgedeckt werde vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Dies sind die Rechte, die du ihnen sollst vorlegen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'So du einen ebraischen Knecht kaufest, dersoll dir sechs Jahre dienen; im siebenten Jahr soil er frei ledig ausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, '1st er ohne Weib kommen, so, soil er auch ohne Weib ausgehen. 1st er aber mit Weib kommen, so soil sein Weib mit ihm ausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hat ihm aber sein Herr ein Weib gegeben und hat Sohne Oder Tochter gezeuget, so soli das Weib und die Kinder seines Herrn sein; er aber soil ohne Weib ausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Spricht aber der Knecht: Ich habe meinen Herrn lieb und mein Weib und Kind, ich will nicht frei werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'So bringe ihn sein Herr vor die Gotter und halte ihn an die Tur Oder Pfosten und bohre ihm mit einem Pfriemen durch sein Ohr; und er sei sein Knecht ewig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Verkauftjemand seine Tochter zur Magd, so soil sie nicht ausgehen wie die Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Gefallt sie aber ihrem Herrn nicht und will ihr nicht zur Ehe helfen, so soil er sie zu Ibsen geben. Aber unter ein fremd Volk sie zu verkaufen, hat er nicht Macht, weil er sie verschmahet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Vertrauet er sie aber seinem Sohn, so soil er Tochterrecht an ihr tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Gibt er ihm aber eine andere, so soil er ihr an ihrem Futter, Decke und Eheschuld nicht abbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Tut er diese drei nicht, so soli sie frei ausgehen ohne Losegeld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Menschen schlagt, dafi erstirbt, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er ihm aber nicht nachgestellet sondern Gott hat ihn lassen ohngefahr in seine Hande fallen, so will ich dir einen Ort bestimmen, dahin er fliehen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Wo aber jemand an seinem Nachsten frevelt und ihn mit List erwurget, so sollst du denselben von meinem Altar nehmen, daß man ihn tote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Wer seinen Vater Oder Mutter schlagt, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Wer einen Menschen stiehlt und verkaufet, dad man ihn bei ihm findet, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Wer Vater Oder Mutter flucht, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Wenn sich Manner miteinanderhadern, und einer schlagt den andern mit einem Stein Oder mit einer Faust, daß er nicht stirbt, sondern zu Bette liegt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'kommterauf, dati erausgehet an seinem Stabe so soil, der ihn schlug, unschuldig sein, ohne dafi er ihm bezahle, was er versaumet hat, und das Arztgeld gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Wer seinen Knecht Oder Magd schlagt mit einem Stabe, dati er stirbt unter seinen Handen, der, soli darum gestraft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Bleibt er aber einen Oder zween Tage, so soil er nicht darum gestraft werden; denn es ist sein Geld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Wenn sich Manner hadern und verletzen ein schwanger Weib, dati ihr die Frucht abgehet, und ihr kein Schade widerfahrt, so soil man ihn urn Geld strafen, wieviel des Weibes Mann ihm auflegt, und soil\'s geben nach der Teidingsleute Erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Kommt ihr aber ein Schade daraus, so soil er lassen Seele urn Seele,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge urn Auge, Zahn urn Zahn, Hand urn Hand, Fufi urn Fuß,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brand urn Brand, Wunde urn Wunde, Beule urn Beule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Wenn jemand seinen Knecht Oder seine Magd in ein Auge schlagt und verderbet es, der soil sie frei loslassen urn das Auge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Desselbigengleichen, wenn er seinem Knecht Oder Magd einen Zahn ausschlagt, soil er sie frei loslassen urn den Zahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Wenn ein Ochse einen Mann Oder Weib stoßet, daß er stirbt, so soil man den Ochsen steinigen und sein Fleisch nicht essen; so ist der Herr des Ochsen unschuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Ist aber der Ochse vorhin stoßig gewesen, und seinem Herrn ist\'s angesagt, und er ihn nicht verwahret hat, und totet daruber einen Mann Oder Weib, soil man den Ochsen steinigen, und sein Herr soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wird man aber ein Geld auf ihn legen, so soil er geben, sein Leben zu losen, was man ihm auflegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Desselbigengleichen soli man mit ihm handeln, wenn er Sohn Oder Tochter stoßet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stoßet er aber einen Knecht Oder Magd, so soil er ihrem Herrn dreißig silberne Sekel geben, und den Ochsen soli man steinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'so jemand eine Grube auftut, Oder grabt eine Grube und decket sie nicht zu, und fallt daruber ein Ochse Oder Esel hinein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'so soil\'s der Herr der Grube mit Geld dem andern wieder bezahlen; das Aas aber soil sein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Wenn jemandes Ochse eines andern Ochsen stoßet, daß er stirbt, so sollen sie den lebendigen Ochsen verkaufen und das Geld teilen und das Aas auch teilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ist\'s aber kund gewesen, daß der Ochse stoßig vorhin gewesen ist, und sein Herr hat ihn nicht verwahret, so soli er einen Ochsen urn den andern vergelten und das Aas haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 37, 'Wenn jemand einen Ochsen Oder Schaf stiehlt und schlachtet es Oder verkauft es, der soil fünf Ochsen fur einen Ochsen wiedergeben und vier Schafe fur ein Schaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wenn ein Dieb ergriffen wird, daß er einbricht, und wird drob geschlagen, daß er stirbt, so soil man kein Blutgericht uber jenen lassen gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ist aber die Sonne uber ihm aufgegangen, so soil man das Blutgericht gehen lassen. Es soil aber ein Dieb wiedererstatten. Hat er nichts, so verkaufe man ihn urn seinen Diebstahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Findet man aber bei ihm den Diebstahl lebendig, es sei Ochse, Esel Oder Schaf, so soil er\'s zwiefaltig wiedergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Wenn jemand einen Acker Oder Weinberg beschadiget, daß er sein Vieh lasset Schaden tun in eines andern Acker, der soil von dem Besten auf seinem Acker und Weinberge wiedererstatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Wenn ein Feuer auskommt und ergreift die Dornen und verbrennet die Garben Oder Getreide, das noch stehet, Oder den Acker, so soil der wiedererstatten, der das Feuer angezundet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn jemand seinem Nachsten Geld Oder Gerate zu behalten tut, und wird demselbigen aus seinem Hause gestohlen: findet man den Dieb, so soil er\'s zwiefaltig wiedergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Findet man aber den Dieb nicht, so soli man den Hauswirt vor die Gotter bringen, ob er nicht seine Hand habe an seines Nachsten Habe gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Wo einerden andern schuldiget urn einigerlei Unrecht, es sei urn Ochsen Oder Esel Oder Schaf Oder Kleider Oder allerlei, das verloren ist, so sollen beider Sachen vor die Gotter kommen. Welchen die Gotter verdammen, der soil\'s zwiefaltig seinem Nachsten wiedergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn jemand seinem Nachsten einen Esel Oder Ochsen Oder Schaf Oder irgend ein Vieh zu behalten tut, und stirbt ihm, Oder wird beschadiget, Oder wird ihm weggetrieben, daß es niemand siehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'so soil man\'s unter ihnen auf einen Eid bei dem HERRN kommen lassen, ob er nicht habe seine Hand an seines Nachsten Habe gelegt; und des Guts Herr soil\'s annehmen, daß jener nicht bezahlen musse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Stiehlt es ihm aber ein Dieb, so soil er\'s seinem Herm bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Wird es aberzerrissen, so soil er Zeugnis davon bringen und nicht bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Wenn es jemand von seinem Nachsten entlehnet, und wird beschadiget Oder stirbt, daß sein Herr nicht dabei ist, so soil er\'s bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Ist aber sein Herr dabei, so soil er\'s nicht bezahlen, so er\'s urn sein Geld gedinget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Wenn jemand eine Jungfrau beredet, die noch nicht vertrauet ist, und beschlaft sie, der soil ihr geben ihre Morgengabe und sie zum Weibe haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Weigertsich aber ihr Vater, sie ihm zu geben, so soil er Geld darwagen, wieviel einer Jungfrau zur Morgengabe gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Die Zauberinnen sollst du nicht leben lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Wer ein Vieh beschlaft, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wer den Gottern opfert, ohne dem HERRN allein, der sei verbannet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Die Fremdlinge sollst du nicht schinden noch unterdrucken; denn ihrseid auch Fremdlinge in Agyptenland gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Ihr sollt keine Witwen und Waisen beleidigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Wirst du sie beleidigen, so werden sie zu mir schreien, und ich werde ihr Schreien erhoren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'so wird mein Zorn ergrimmen, daß ich euch mit dem Schwert tote und eure Weiber Witwen und eure Kinder Waisen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wenn du Geld leihest meinem Volk, das arm ist bei dir, sollst du ihn nicht zu Schaden dringen und keinen Wucher auf ihn treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du von deinem Nachsten ein Kleid zum Pfande nimmst, sollst du es ihm wiedergeben, ehe die Sonne untergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Denn sein Kleid ist seine einige Decke seiner Haut, darin er schlaft. Wird er aber zu mir schreien, so werde ich, ihn erhoren; denn ich bin gnadig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Den Gottern sollst du nicht fluchen und den Obersten in deinem Volk sollst du nicht lastern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Deine Fulle und Tranen sollst du nicht verziehen. Deinen ersten Sohn sollst du mir geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'So sollstdu auch tun mit deinem Ochsen und Schaf. Sieben Tage laß, es bei seiner Mutter sein, am achten Tage sollst du mir\'s geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Ihr sollt heilige Leute vor mir sein: darum sollt ihr kein Fleisch essen, das auf dem Felde von Tieren zerrissen ist, sondern vor die Hunde werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du sollst falscher Anklage nicht glauben, daß du einem Gottlosen Beistand tust und ein falscher Zeuge seiest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Du sollst nicht folgen der Menge zum Bosen und nicht antworten vor Gericht, daß du der Menge nach vom Rechten weichest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Du sollst den Geringen nicht schmücken in seiner Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Wenn du deines Feindes Ochsen Oder Esel begegnest, daß er irret, so sollst du ihm denselben wieder zufuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du des, der dich hasset, Esel siehest unter seiner Last liegen, hute dich und lali ihn nicht, sondern versaume gerne das Deine, urn seinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht deines Armen nicht beugen in seiner Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Sei feme von falschen Sachen. Den Unschuldigen und Gerechten sollstdu nicht erwurgen; denn ich lasse den Gottlosen nicht recht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Du sollst nicht Geschenke nehmen; denn Geschenke machen die Sehenden blind und verkehren die Sachen der Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Die Fremdlinge sollt ihr nicht unter, drncken; denn ihrwisset urn der Fremdlinge Herz, dieweil ihr auch seid Fremdlinge in Agyptenland gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Sechs Jahre sollst du dein Land besaen und seine Fruchte einsammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Im siebenten Jahr sollst du es ruhen und liegen lassen, daß die Armen unter deinem Volk davon essen; und was uber bleibet, laft das Wild auf dem Felde essen. Also sollst du auch tun mit deinem Weinberge und Olberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du deine Arbeit tun, aberdes siebenten Tages sollst du feiern, auf daß dein Ochse und Esel ruhen und deiner Magd Sohn und Fremdling sich erquicken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Alles, was ich euch gesagt habe, das haltet. Und anderer Gotter Namen sollt ihr nicht gedenken, und aus eurem Munde sollen sie nicht gehoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal sollt ihr mir Fest halten im Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Namlich das Fest der ungesauerten Brote sollst du halten, daß du sieben Tage ungesauert Brot essest (wie ich dir geboten habe) um die Zeit des Monden Abib; denn in demselbigen bist du aus Agypten gezogen. Erscheinet aber nicht leer vor mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Und das Fest der ersten Ernte der Fruchte, die du auf dem Felde gesaet hast. Und das Fest der Einsammlung im Ausgang des Jahrs, wenn du deine Arbeit eingesammelt hast vom Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahr sollen erscheinen vor dem HERRN, dem Herrscher, alle deine Mannsbilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du sollst das Blut meines Opfers nicht neben dem Sauerteig opfern, und das Fette von meinem Fest soil nicht bleiben bis auf morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das Erstling von der ersten Frucht auf deinem Felde sollst du bringen in das Haus des HERRN, deines Gottes. Und sollst das Bocklein nicht kochen, dieweil es an seiner Mutter Milch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Siehe, ich sende einen Engel vor dir her, der dich behute auf dem Wege und bringe dich an den Ort, den ich bereitet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Darum hute dich vor seinem Angesicht und gehorche seiner Stimme und erbittere ihn nicht; denn er wird euer Ubertreten nicht vergeben, und mein Name ist in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Wirst du aber seine Stimme horen und tun alles, was ich dir sagen werde, so will ich deiner Feinde Feind und deiner Widerwartigen Widerwartiger sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Wenn nun mein Engel vor dir hergehet und dich bringet an die Amoriter, Hethiter, Pheresiter, Kanaaniter, Heviter und Jebusiter, und ich sie vertilge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'so sollst du ihre Gotter nicht anbeten noch ihnen dienen und nicht tun, wie sie tun, sondern du sollst ihre Gotzen umreiften und zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Aber dem HERRN, eurem Gott, sollt ihr dienen, so wird er dein Brot und dein Wasser segnen, und ich will alle Krankheit von dir wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Und soil nichts Untrachtiges noch Unfruchtbares sein in deinem Lande, und will dich lassen alt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Ich will mein Schrecken vor dir hersenden und alles Volk verzagt machen, dahin du kommst; und will dir geben alle deine Feinde in die Flucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ich will Hornissen vor dir hersenden, die vor dir her ausjagen die Heviter, Kanaaniter und Hethiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ich will sie nicht auf ein Jahr ausstoften vor dir, auf daß nicht das Land wuste werde, und sich wilde Tiere wider dich mehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Einzeln nacheinander will ich sie vor dir her ausstoften, bis daß du wachsest und das Land besitzest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und will deine Grenze setzen das Schilfmeer und das Philistermeer und die Wuste bis an das Wasser. Denn ich will dir in deine Hand geben die Einwohner des Landes, daß du sie sollst ausstoften vor dir her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du sollst mit ihnen Oder mit ihren Gottern keinen Bund machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'sondern laft sie nicht wohnen in deinem Lande, daß sie dich nicht verfuhren wider mich. Denn wo du ihren Gottern dienest, wird dir\'s zum Argernis geraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Und zu Mose sprach er: Steig herauf zum HERRN, du und Aaron, Nadab und Abihu, und die siebenzig Altesten Israels, und betet an von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Aber Mose alleine nahe sich zum HERRN, und laft jene sich nicht herzunahen; und das Volk komme auch nicht mit ihm herauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Mose kam und erzahlete dem Volk alle Worte des HERRN und alle Rechte. Da antwortete alles Volk mit einer Stimme und sprachen: Alle Worte, die der HERR gesagt hat, wollen wir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Da schrieb Mose alle Worte des HERRN und machte sich des Morgens fruhe auf und bauete einen Altar unten am Berge mit zwdlf Saulen nach den zwolf Stammen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Und sandte hin Junglinge aus den Kindern Israel, daß sie Brandopfer darauf opferten und Dankopferdem HERRN von Farren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Und Mose nahm die Halfte des Bluts und tat\'s in ein Becken; die andere Halfte sprengete er auf den Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Und nahm das Buch des Bundes und las es vor den Ohren des Volks. Und da sie sprachen: Alles, was der HERR gesagt hat, wollen wir tun und gehorchen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'da nahm Mose das Blut und sprengete das Volk damit und sprach: Sehet, das ist Blut des Bundes, den der HERR mit euch machte uber alien diesen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Da stiegen Mose und Aaron, Nadab und Abihu und die siebenzig Altesten Israels hinauf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'und sahen den Gott Israels. Unterseinen Fuften war es wie ein schoner Saphir und wie die Gestalt des Himmels, wenn es klar ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Und er lieft seine Hand nicht uber dieselben Obersten in Israel. Und da sie Gott geschaute hatten, aften und tranken sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Und der HERR sprach zu Mose: Komm herauf zu mir auf den Berg und bleibe daselbst, daß ich dir gebe steinerne Tafeln und Gesetze und Gebote, die ich geschrieben habe, die du sie lehren sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Da machte sich Mose auf und sein Diener Josua und stieg auf den Berg Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Und sprach zu den Altesten: Bleibet hie, bis wir wieder zu euch kommen. Siehe, Aaron und Hur sind bei euch; hat jemand eine Sache, der komme vor dieselben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Da nun Mose auf den Berg kam, bedeckte eine Wolke den Berg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit des HERRN wohnete auf dem Berge Sinai und deckte ihn mit der Wolke sechs Tage; und rief Mose am siebenten Tage aus der Wolke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Und das Ansehen der Herrlichkeit des HERRN war wie ein verzehrend Feuer auf der Spitze des Berges vor den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Und Mose ging mitten in die Wolke und stieg auf den Berg; und blieb auf dem Berge vierzig Tage und vierzig Nachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Sage den Kindern Israel, dafi sie mirein Hebopfer geben; und nehmet dasselbe von jedermann, der es williglich gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Das ist aber das Hebopfer, das ihr von ihnen nehmen sollt: Gold, Silber, Erz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'gelbe Seide, Scharlaken, Rosinrot, weifie Seide, Ziegenhaar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'rotliche Widderfelle, Dachsfelle, Fohrenholz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, '01 zur Lampe, Spezerei zur Salbe und gutem Rauchwerk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onyxsteine und eingefafite Steine zum Leibrock und zum Schildlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen mirein Heiligtum machen, dafi ich unter ihnen wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Wie ich direin Vorbild der Wohnung und alles seines Gerats zeigen werde, so sollt ihr\'s machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Machet eine Lade von Fohrenholz. Dritthalb Ellen soil die Lange sein, anderthalb Ellen die Breite und anderthalb Ellen die Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Und sollst sie mit feinem Golde uberziehen, inwendig und auswendig; und mache einen guldenen Kranz oben umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Und geufi vier guldene Rinken und mache sie an ihre vier Ecken, also daß zween Rinken seien auf einer Seite und zween auf der andern Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Und mache Stangen von Fohrenholz und uberzeuch sie mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Und stecke sie in die Rinken an der Lade Seiten, daß man sie dabei trage;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'und sollen in den Rinken bleiben und nicht herausgetan werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Und sollt in die Lade das Zeugnis legen, das ich dir geben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Du sollst auch einen Gnadenstuhl machen von feinem Golde; dritthalb Ellen soli seine Lange sein und anderthalb Ellen seine Breite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und sollst zween Cherubim machen von dichtem Golde, zu beiden Enden des Gnadenstuhls,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'daß ein Cherub sei an diesem Ende, der andere an dem andern Ende, und also zween Cherubim seien an des Gnadenstuhls Enden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Und die Cherubim sollen Flügel ausbreiten, oben uberher, daß sie mit ihren Flugeln den Gnadenstuhl bedecken, und eines jeglichen Antlitz gegen dem andern stehe; und ihre Antlitze sollen auf den Gnadenstuhl sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Und sollt den Gnadenstuhl oben auf die Lade tun und in die Lade das Zeugnis legen, das ich dir geben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Von dem Ort will ich dir zeugen und mit dir reden, namlich von dem Gnadenstuhl zwischen den zween Cherubim, der auf der Lade des Zeugnisses ist, alles, was ich dir gebieten will an die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Du sollst auch einen Tisch machen von Fbhrenholz; zwo Ellen soil seine Lange sein und eine Elle seine Breite und anderthalb Ellen seine Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Und sollst ihn uberziehen mit feinem Golde und einen guldenen Kranz umher machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'und eine Leiste umher, einer Hand breit hoch, und einen guldenen Kranz urn die Leiste her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Und sollst vier guldene Ringe dran machen an die vier Orte an seinen vier Fulien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Hart unter der Leiste sollen die Ringe sein, dafi man Stangen drein tue und den Tisch trage;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Und sollst die Stangen von Fbhrenholz machen und sie mit Golde uberziehen, daß der Tisch damit getragen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Du sollst auch seine Schüsseln, Becher, Kannen, Schalen aus feinem Golde machen, damit man aus- und einschenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und sollst auf den Tisch allezeit Schaubrote legen vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Du sollst auch einen Leuchter von feinem dichten Golde machen; daran soil der Schaft mit Rohren, Schalen, Knaufen und Blumen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Sechs Rohren sollen aus dem Leuchter zu den Seiten ausgehen, aus jeglicher Seite drei Rdhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Eine jegliche Rohre soil drei offene Schalen, Knaufe und Blumen haben; das sollen sein die sechs Rohren aus dem Leuchter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Aber der Schaft am Leuchter soil vier offene Schalen mit Knaufen und Blumen haben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'und je einen Knauf unter zwo Rohren, welcher sechs aus dem Leuchter gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Denn beide ihre Knaufe und Rohren sollen aus ihm gehen, alles ein dicht lauter Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Und sollst sieben Lampen machen obenauf, daß sie gegeneinander leuchten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'und Lichtschneuzen und Ldschnapfe von feinem Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Zentner feinen Goldes sollst du das machen mitallem diesem Gerate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und siehe zu, daß du es machest nach ihrem Bilde, das du auf dem Berge gesehen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Die Wohnung sollst du machen von zehn Teppichen, von weißer gezwirnter Seide, von gelber Seide, von Scharlaken und Rosinrot. Cherubim sollst du dran machen künstlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Lange eines Teppichs soil achtundzwanzig Ellen sein, die Breite vier Ellen; und sollen alle zehn gleich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Und sollen je fünf zusammengefuget sein; einer an den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Und sollst Schlauflein machen von gelber Seide an jeglichen Teppichs Orten, da sie sollen zusammengefuget sein, daü je zween und zween an ihren Orten zusammengeheftet werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'fünfzig Schlauflein an jeglichem Teppich, dafi einer den andern zusammenfasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Und sollst fünfzig guldene Hefte machen, damit man die Teppiche zusammenhefte, einen an den andern, auf daß es eine Wohnung werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Du sollst auch eine Decke aus Ziegenhaar machen zur Hutte fiber die Wohnung von elf Teppichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Lange eines Teppichs soli dreißig Ellen sein, die Breite aber vier Ellen; und sollen alle elf gleich grofi sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Fünf sollst du aneinanderfügen und sechs auch aneinander, daß du den sechsten Teppich zwiefaltig machest vorne an der Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Und sollst an einem jeglichen Teppich fünfzig Schlauflein machen, an ihren Orten, daß sie aneinander bei den Enden gefüget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Und sollst fünfzig eherne Hefte machen und die Hefte in die Schlauflein tun, daß die Hutte zusammengefuget und eine Hütte werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Aber das Uberlange an den Teppichen der Hütte sollst du die Halfte lassen uberhangen an der Hutte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'auf beiden Seiten eine Elle lang, daß das übrige sei an der Hutte Seiten und auf beiden Seiten sie bedecke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Ober diese Decke sollst du eine Decke machen von rdtlichen Widderfellen, dazu über sie eine Decke von Dachsfellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Du sollst auch Bretter machen zu der Wohnung von Fohrenholz, die stehen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Zehn Ellen lang soil ein Brett sein und anderthalb Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Zween Zapfen soil ein Brett haben, dafi eins an das andere moge gesetzt werden. Also sollst du alle Bretter der Wohnung machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Zwanzig sollen ihrer stehen gegen dem Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Die sollen vierzig silberne Füße unten haben, je zween Fulie unter jeglichem Brett an seinen zween Zapfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Also auf der andern Seite, gegen Mitternacht, sollen auch zwanzig Bretter stehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'und vierzig silberne Fülie, je zween Füße unter jeglichem Brett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Aber hinten an der Wohnung, gegen dem Abend, sollst du sechs Bretter machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Dazu zwei Bretter hinten an die zwo Ecken der Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'daß ein jegliches der beiden sich mit seinem Ortbrett von unten auf geselle und oben am Haupt gleich zusammenkomme mit einer Klammer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'daß acht Bretter seien mit ihren silbernen Fußen; deren sollen sechzehn sein, je zween unter einem Brett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Und, sollst Riegel machen von Fohrenholz, fünf zu den Brettern auf einer Seite der Wohnung');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'und fünf zu den Brettern auf der andern Seite der Wohnung und fünf zu den Brettern hinten an der Wohnung gegen dem Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Und sollst die Riegel mitten an den Brettern durchhinstoßen und alles zusammenfassen von einem Ort zu dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Und sollst die Bretter mit Golde überziehen und ihre Rinken von Golde machen, daß man die Riegel drein tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Und die Riegel sollst du mit Gold uberziehen. Und also sollst du denn die Wohnung aufrichten nach der Weise, wie du gesehen hast auf dem Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Und sollst einen Vorhang machen von gelber Seide, Scharlaken und Rosinrot und gezwirnter weißer Seide; und sollst Cherubim dran machen künstlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Und sollst ihn hangen an vier Saulen von Fohrenholz, die mit Gold überzogen sind und güldene Knaufe und vier silberne Fuße haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Und sollst den Vorhang mit Heften anheften und die Lade des Zeugnisses inwendig des Vorhangs setzen, daß ereuch ein Unterschied sei zwischen dem Heiligen und dem Allerheiligsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und sollst den Gnadenstuhl tun auf die Lade des Zeugnisses in dem Allerheiligsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Den Tisch aber setze außer dem Vorhange und den Leuchter gegen dem Tisch über, zu mittagwarts der Wohnung, daß der Tisch stehe gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Und sollst ein Tuch machen in die Tur der Hütte, gewirkt von gelber Seide, Rosinrot, Scharlaken und gezwirnter weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und sollst demselben Tuch fünf Saulen machen von Fohrenholz, mit Gold überzogen, mit güldenen Knaufen, und sollst ihnen fünf eherne Füße gießen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Und sollst einen Altar machen von Fohrenholz, fünf Ellen lang und breit, daß er gleich viereckig sei, und drei Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Horner sollst du auf seine vier Ecken machen, und sollst ihn mit Erz uberziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Mache auch Aschentopfe, Schaufeln, Becken, Kreuel, Kohlpfannen; alle seine Gerate sollst du von Erz machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Du sollst auch ein ehern Gitter machen wie ein Netz und vier eherne Ringe an seine vier Orte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Du sollst es aber von unten auf um den Altar machen, daß das Gitter reiche bis mitten an den Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Und sollst auch Stangen machen zu dem Altar von Fohrenholz, mit Erz uberzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Und sollst die Stangen in die Ringe tun, daß die Stangen seien an beiden Seiten des Altars, damit man ihn tragen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Und sollst ihn also von Brettern machen, daß er inwendig hohl sei, wie dir auf dem Berge gezeiget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Du sollst auch der Wohnung einen Hof machen, einen Umhang von gezwirnter weilier Seide, auf einer Seite hundert Ellen lang, gegen dem Mittag,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Und zwanzig Saulen auf zwanzig ehernen Fufien, und ihre Knaufe mit ihren Reifen von Silber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Also auch gegen Mitternacht soli sein ein Umhang, hundert Ellen lang; zwanzig Saulen auf zwanzig ehernen Fufien, und ihre Knaufe mit ihren Reifen von Silber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Aber gegen dem Abend soil die Breite des Hofes haben einen Umhang fünfzig Ellen lang, zehn Saulen auf zehn Fülien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Gegen dem Morgen aber soli die Breite des Hofes haben fünfzig Ellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'also daß der Umhang habe auf einer Seite funfzehn Ellen, dazu drei Saulen auf dreien Fülien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'und aber funfzehn Ellen aufderandern Seite, dazu drei Saulen auf dreien Fulien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Aber in dem Tor des Hofes soli ein Tuch sein, zwanzig Ellen breit, gewirket von gelber Seide, Scharlaken, Rosinrot und gezwirnter weilier Seide, dazu vier Saulen auf ihren vier Fulien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Saulen um den Hof her sollen silberne Reife und silberne Knaufe und eherne Fülie haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Und die Lange des Hofes soil hundert Ellen sein, die Breite fünfzig Ellen, die Hohe fünf Ellen, von gezwirnter weilier Seide; und seine Fulie sollen ehern sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Auch alle Gerate der Wohnung zu allerlei Amt und alle seine Nagel und alle Nagel des Hofes sollen ehern sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Gebeut den Kindern Israel, daß sie zu dir bringen das allerreinste lautere 01 von Olbaumen gestolien, zur Leuchte, das man allezeit oben in die Lampen tue');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'in der Hütte des Stifts auüer dem Vorhang, der vor dem Zeugnis hanget. Und Aaron und seine Sohne sollen sie zurichten, beide des Morgens und des Abends, vor dem HERRN. Das soil euch eine ewige Weise sein auf eure Nachkommen unter den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Und sollst Aaron, deinen Bruder, und seine Sohne zu dirnehmen aus den Kindern Israel, daß er mein Priester sei, namlich Aaron und seine Sohne, Nadab, Abihu, Eleasar und Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und sollst Aaron, deinem Bruder heilige Kleider machen, die herrlich und schon seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Und sollst reden mit alien, die eines weisen Herzens sind, die ich mit dem Geist der Weisheit erfullet habe, Aaron Kleider machen zu seiner Weihe, daß er mein Priester sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Das sind aber die Kleider, die sie machen sollen: das Schildlein, Leibrock, Seidenrock, engen Rock, Hut und Gürtel. Also sollen sie heilige Kleider machen deinem Bruder Aaron und seinen Sohnen, daß er mein Priester sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Dazu sollen sie nehmen Gold, gelbe Seide, Scharlaken, Rosinrot und weitie Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Den Leibrock sollen sie machen von Gold, gelber Seide, Scharlaken, Rosinrot und gezwirnter weilier Seide, kunstlich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'daß er auf beiden Achseln zusammengefüget und an beiden Seiten zusammengebunden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Und sein Gurt drauf soli derselben Kunst und Werks sein, von Gold, gelber Seide, Scharlaken, Rosinrot und gezwirnter weilier Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Und sollst zween Onyxsteine nehmen und drauf graben die Namen der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'auf jeglichen sechs Namen, nach der Ordnung ihres Alters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Das sollst du tun durch die Steinschneider, die da Siegel graben, also daß sie mit Gold umher gefasset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Und sollst sie auf die Schultern des Leibrocks heften, daß es Steine seien zum Gedachtnis fur die Kinder Israel, daß Aaron ihre Namen auf seinen beiden Schultern trage vor dem HERRN zum Gedachtnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Und sollst guldene Spangen machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'und zwo Ketten von feinem Golde mit zwei Enden, aber die Glieder ineinander hangend, und sollst sie an die Spangen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Das Amtsschildlein sollst du machen nach der Kunst wie den Leibrock, von Gold, gelber Seide, Scharlaken, Rosinrot und gezwirnter weilier Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Viereckig soil es sein und zwiefach; eine Hand breit soli seine Lange sein und eine Hand breit seine Breite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und sollst es fulien mit vier Riegen voll Steine. Die erste Riege sei ein Sarder, Topaser; Smaragd;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'die andere ein Rubin, Saphir, Demant;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'die dritte ein Lynkurer, Achat, Amethyst;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'die vierte ein Turkis, Onyx, Jaspis. In Gold sollen sie gefasset sein in alien Riegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und sollen nach den zwolf Namen der Kinder Israel stehen, gegraben vom Steinschneider, ein jeglicher seines Namens, nach den zwolf Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Und sollst Ketten zu dem Schildlein machen mit zwei Enden, aber die Glieder ineinander hangend, von feinem Golde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'und zween guldene Ringe an das Schildlein, also daß du dieselben zween Ringe heftest an zwo Ecken des Schildleins');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'und die zwo guldenen Ketten in die selben zween Ringe an den beiden Ecken des Schildleins tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Aber die zwei Enden der zwo Ketten sollst du in zwo Spangen tun und sie heften auf die Schultern am Leibrock, gegeneinander uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Und sollst zween andere guldene Ringe machen und an die zwo andern Ecken des Schildleins heften an seinem Ort, inwendig gegen dem Leibrock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Und sollst aber zween guldene Ringe machen und an die zwo Ecken unten am Leibrock gegeneinander heften, da der Leibrock zusammengehet, oben an dem Leibrock, kunstlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und man soil das Schildlein mitfeinen Ringen mit einer gelben Schnur an die Ringe des Leibrocks knüpfen, daß es auf dem kunstlich gemachten Leibrock hart anliege und das Schildlein sich nicht von dem Leibrock losmache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Also soil Aaron die Namen der Kinder Israel tragen in dem Amtsschildlein auf seinem Herzen, wenn er in das Heilige gehet, zum Gedachtnis vor dem HERRN allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Und sollst in das Amtsschildlein tun Licht und Recht, daß sie auf dem Herzen Aarons seien, wenn er eingehet vor den HERRN, und trage das Amt der Kinder Israel auf seinem Herzen vor dem HERRN allewege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Du sollst auch den Seidenrock unter den Leibrock machen, ganz von gelber Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Und oben mitten inne soil ein Loch sein und eine Borte urn das Loch her zusammengefaltet, daß es nicht zerreifte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Und unten an seinem Saum sollst du Granatapfel machen von gelber Seide, Scharlaken, Rosinrot urn und urn, und zwischen dieselben guldene Schellen, auch urn und urn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'daß eine guldene Schelle sei, danach ein Granatapfel und aber eine guldene Schelle und wiederein Granatapfel urn und urn an dem Saum desselben Seidenrocks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aaron soil ihn anhaben wenn er dienet, daß man seinen Klang hore, wenn er aus und ein gehet in das Heilige vor dem HERRN, auf daß er nicht sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Du sollst auch ein Stirnblatt machen von feinem Golde und ausgraben, wie man die Siegel ausgrabt: Die Heiligkeit des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Und sollst es heften an eine gelbe Schnur vorne an den Hut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'auf der Stirn Aarons, daß also Aaron trage die Missetat des Heiligen, das die Kinder Israel heiligen in alien Gaben ihrer Heiligung; und es soli allewege an seiner Stirn sein, daß er sie versohne vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Du sollst auch den engen Rock machen von weifter Seide und einen Hut von weifter Seide machen und einen gestickten Gürtel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Und den Sohnen Aarons sollst du Rocke, Gurtel und Hauben machen, die herrlich und schon seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und sollst sie deinem Bruder Aaron samt seinen Sohnen anziehen und sollst sie salben und ihre Hande fullen und sie weihen, daß sie meine Priester seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und sollst ihnen leinene Niederkleider machen, zu bedecken das Fleisch der Scham, von den Lenden bis an die Huften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aaron und seine Sohne sollen sie anhaben, wenn sie in die Hutte des Stiffs gehen Oder hinzutreten zum Altar, daß sie dienen in dem Heiligtum, daß sie nicht ihre Missetat tragen und sterben müssen. Das soli ihm und seinem Samen nach ihm eine ewige Weise sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Das ist\'s auch, das du ihnen tun sollst, daß sie mir zu Priestern geweihet werden: Nimm einen jungen Farren und zween Widder ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ungesauert Brot und ungesauerte Kuchen, mit 01 gemenget, und ungesauerte Fladen, mit 01 gesalbet. Von Weizenmehl sollst du solches alles machen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'und sollst es in einen Korb legen und in dem Korbe herzubringen samt dem Farren und den zween Widdern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Und sollst Aaron und seine Sohne vor die Tur der Hutte des Stiffs führen und mit Wasser waschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'und die Kleider nehmen und Aaron anziehen den engen Rock und den Seidenrock und den Leibrock und das Schildlein zu dem Leibrock; und sollst ihn gurten auften auf den Leibrock');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'und den Hut auf sein Haupt setzen und die heilige Krone an den Hut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Und sollst nehmen das Salbol und auf sein Haupt schutten und ihn salben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Und seine Sohne sollst du auch herzu fuhren und den engen Rock ihnen anziehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'und beide Aaron und auch sie mit Gurteln gurten und ihnen die Hauben aufbinden, daß sie das Priestertum haben zu ewiger Weise. Und sollst Aaron und seinen Sohnen die Hande fullen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'und den Farren herzufuhren vor die Hutte des Stifts; und Aaron samt seinen Sohnen sollen ihre Hande auf des Farren Haupt legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Und sollst den Farren schlachten vor dem HERRN, vor der Tur der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Und sollst seines Bluts nehmen und auf des Altars Horner tun mit deinem Finger und alles andere Blut an des Altars Boden schutten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Und sollst alles Fett nehmen am Eingeweide und das Netz uber der Leber und die zwo Nieren mit dem Fett, das druber liegt, und sollst es auf dem Altar anzünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Aberdes Farren Fleisch, Fell und Mist sollst du außen vor dem Lager mit Feuer verbrennen, denn es ist ein Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Aber den einen Widder sollst du nehmen, und Aaron samt seinen Sohnen sollen ihre Hande auf sein Haupt legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Dann sollst du ihn schlachten und seines Bluts nehmen und auf den Altar sprengen ringsherum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Aber den Widder sollst du zerlegen in Stucke und sein Eingeweide waschen und Schenkel; und sollst es auf seine Stucke und Haupt legen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'und den ganzen Widder anzunden auf dem Altar; denn es ist dem HERRN ein Brandopfer, ein sußer Geruch, ein Feuer des FIERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Den andern Widder aber sollst du nehmen und Aaron samt seinen Sohnen sollen ihre Hande auf sein Haupt legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Und sollst ihn schlachten und seines Bluts nehmen und Aaron und seinen Sohnen auf den rechten Ohrknorpel tun und auf den Daumen ihrer rechten Hand und auf den großen Zehen ihres rechten Fußes; und sollst das Blut auf den Altar sprengen ringsherum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Und sollst das Blut auf dem Altar nehmen und Salbol und Aaron und seine Kleider, seine Sohne und ihre Kleider besprengen, so wird er und seine Kleider, seine Sohne und ihre Kleider geweihet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Danach sollst du nehmen das Fett von dem Widder, den Schwanz und das Fett am Eingeweide, das Netz über der Leber und die zwo Nieren mit dem Fett drüber und die rechte Schulter (denn es ist ein Widder der Fulle)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'und ein Brot und einen Olkuchen und einen Fladen aus dem Korbe des ungesauerten Brots, der vor dem HERRN stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Und lege es alles auf die Hande Aarons und seiner Sohne und webe es dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Danach nimm\'s von ihren Handen und zunde es an auf dem Altar zum Brandopfer, zum sußen Geruch vor dem HERRN; denn das ist ein Feuer des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Und sollst die Brust nehmen vom Widder der Fulle Aarons und sollst es vor dem HERRN weben. Das soil dein Teil sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Und sollst also heiligen die Webebrust und die Hebeschulter, die gewebet und gehebet sind von dem Widder der Fulle Aarons und seiner Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Und soil Aarons und seiner Sohne sein ewiger Weise von den Kindern Israel; denn es ist ein Hebopfer. Und die Hebopfer sollen des HERRN sein von den Kindern Israel an ihren Dankopfern und Hebopfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aber die heiligen Kleider Aarons sollen seine Sohne haben nach ihm, daß sie darinnen gesalbet und ihre Hande gefullet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Welcher unter seinen Sohnen an seiner Statt Priester wird, der soil sie sieben Tage anziehen, daß ergehe in die Hutte des Stifts, zu dienen im Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Du sollst aber nehmen den Widder der Fullung und sein Fleisch an einem heiligen Ort kochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aaron mit seinen Sohnen soil desselben Widders Fleisch essen samt dem Brot im Korbe vor der Tur der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Denn es ist Versohnung damit geschehen, zu füllen ihre Hande, daß sie geweihet werden. Kein anderer soli es essen, denn es ist heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Wo aber etwas überbleibet von dem Fleisch der Fullung und von dem Brot bis an den Morgen, das sollst du mit Feuer verbrennen und nicht essen lassen; denn es ist heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Und sollst also mit Aaron und seinen Sohnen tun alles, was ich dirgeboten habe. Sieben Tage sollst du ihre Hande füllen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'und taglich einen Farren zum Sundopfer schlachten zur Versohnung. Und sollst den Altar entsundigen, wenn du ihn versohnest, und sollst ihn salben, daß er geweihet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage sollst du den Altar versohnen und ihn weihen, daß er sei ein Altar, das Allerheiligste. Wer den Altar anruhren will, der soli geweihet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Und das sollst du mit dem Altar tun. Zwei jahrige Lammer sollst du allewege des Tages drauf opfern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'ein Lamm des Morgens, das andere zwischen Abends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Und zu einem Lamm ein Zehnten Semmelmehls, gemenget mit einem Vierteil von einem Hin gestoßenen Ols und einem Vierteil vom Hin Weins zum Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Mit dem andern Lamm zwischen Abends sollst du tun wie mit dem Speisopfer und Trankopfer des Morgens, zu süßem Geruch, ein Feuer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Das ist das tagliche Brandopfer bei euren Nachkommen vor der Tur der Hutte des Stifts, vor dem HERRN, da ich euch zeugen und mit dir reden will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Daselbst will ich den Kindern Israel erkannt und geheiliget werden in meiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Und will die Hutte des Stifts mit dem Altar heiligen und Aaron und seine Sohne mir zu Priestern weihen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und will unter den Kindern Israel wohnen und ihr Gott sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'daß sie wissen sollen, ich sei der HERR, ihr Gott, der sie aus Agyptenland fuhrete, daß ich unter ihnen wohne, ich, der HERR, ihr Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Du sollst auch einen Rauchaltar machen zu rauchern, von Fohrenholz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'einer Eile lang und breit, gleich viereckig, und zwo Ellen hoch mit seinen Hornern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Und sollst ihn mit feinem Golde uberziehen, sein Dach und seine Wande rings umher und seine Horner. Und sollst einen Kranz von Gold umher machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'und zween guldene Ringe unter dem Kranz zu beiden Seiten, daß man Stangen drein tue und ihn damit trage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Die Stangen sollst du auch von Fohrenholz machen und mit Gold uberziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und sollst ihn setzen vor den Vorhang, der vor der Lade des Zeugnisses hanget, und vor dem Gnadenstuhl, der auf dem Zeugnis ist, von dannen ich dir werde zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und Aaron soil drauf rauchern gut Rauchwerk alle Morgen, wenn erdie Lampen zurichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Desselbigengleichen, wenn er die Lampen anzündet zwischen Abends, soil er solch Gerauch auch rauchern. Das soil das tagliche Gerauch sein vor dem HERRN bei euren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ihr sollt kein fremd Gerauch drauf tun, auch kein Brandopfer noch Speisopfer und kein Trankopfer drauf opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Und Aaron soil auf seinen Hornern versohnen einmal im Jahr mit dem Blut des Sundopfers zur Versohnung. Solche Versohnung soli jahrlich einmal geschehen bei euren Nachkommen; denn das ist dem HERRN das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Haupter der Kinder Israel zahlest, so soil ein jeglicher dem HERRN geben die Versohnung seiner Seele, auf daß ihnen nichteine Plage widerfahre, wenn sie gezahlet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Es soli aber ein, jeglicher, der mit in der Zahl ist, einen halben Sekel geben, nach dem Sekel des Heiligtums (ein Sekel gilt zwanzig Gera). Solcher halber Sekel soil das Hebopfer des HERRN sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Wer in der Zahl ist von zwanzig Jahren und druber, der soil solch Hebopfer dem HERRN geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche soil nicht mehr geben und der Arme nicht weniger als den halben Sekel, den man dem HERRN zur Hebe gibt fur die Versohnung ihrer Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und du sollst solch Geld der Versohnung nehmen von den Kindern Israel und an den Gottesdienst der Hütte des Stifts legen, daß es sei den Kindern Israel ein Gedachtnis vor dem HERRN, daß er sich über ihre Seelen versohnen lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du sollst auch ein ehern Handfali machen mit einem ehernen Fufi, zu waschen; und sollst es setzen zwischen der Hütte des Stifts und dem Altar und Wasser drein tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'daß Aaron und seine Sohne ihre Hande und Fulie draus waschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'wenn sie in die Hütte des Stifts gehen Oder zum Altar, daß sie dienen mit Rauchern, einem Feuer des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'auf daß sie nicht sterben. Das soil eine ewige Weise sein ihm und seinem Samen bei ihren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Und der HERR redete mit Mose und sprach:.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Nimm zu dir die besten Spezereien, die edelsten Myrrhen, fünfhundert (Sekel), und Zinnamet, die Halfte so viel, zweihundertundfünfzig, und Kalmus, auch zweihundertundfünfzig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'und Kassia, fünfhundert, nach dem Sekel des Heiligtums, und Ol vom Olbaum ein Hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'und mache ein heiliges Salbol nach der Apotheker Kunst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Und sollst damit salben die Hütte des Stifts und die Lade des Zeugnisses,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'den Tisch mit all seinem Gerate, den Leuchter mit seinem Gerate, den Rauchaltar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'den Brandopferaltar mit all seinem Gerate und das Handfali mit seinem Fuli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Und sollst sie also weihen, daß sie das Allerheiligste seien; denn wer sie anrühren will, der soil geweihet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aaron und seine Sohne sollst du auch salben und sie mir zu Priestern weihen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Und sollst mit den Kindern Israel reden und sprechen: Dies Ol soil mir eine heilige Salbe sein bei euren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf Menschen Leib soil\'s nicht gegossen werden, sollst auch seinesgleichen nicht machen; denn es ist heilig, darum soil\'s euch heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Wer ein solches macht Oder einem andern davon gibt, der soil von seinem Volk ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und der HERR sprach zu Mose: Nimm zu dir Spezerei, Balsam, Stakte, Galban und reinen Weihrauch, eines so viel als des andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'und mache Rauchwerk draus, nach Apothekerkunst gemenget, daß es rein und heilig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und sollst es zu Pulver stolien und sollst desselben tun vor das Zeugnis in der Hutte des Stifts, von dannen ich dir zeugen werde. Das soil euch das Allerheiligste sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Und desgleichen Raucherwerk sollt ihr euch nicht machen, sondern es soli dir heilig sein dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Wer ein solches machen wird daß er damit rauchere, der wird ausgerottet deswillen von seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Siehe, ich habe mit Namen berufen Bezaleel, den Sohn Uris, des Sohns Hurs, vom Stamm Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'und habe ihn erfullet mit dem Geist Gottes, mit Weisheit und Verstand und Erkenntnis und mit allerlei Werk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'kunstlich zu arbeiten am Gold, Silber, Erz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'kunstlich Stein zu schneiden und einzusetzen und kunstlich zu zimmern am Holz, zu machen allerlei Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Und siehe, ich habe ihm zugegeben Ahaliab, den Sohn Ahisamachs, vom Stamm Dan, und habe allerlei Weisen die Weisheit ins Herz gegeben, daß sie machen sollen alles, was ich dirgeboten habe:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'die Hütte des Stiffs, die Lade des Zeugnisses, den Gnadenstuhl drauf und alle Gerate der Hütte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'den Tisch und sein Gerat, den feinen Leuchter und all sein Gerat, den Rauchaltar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'den Brandopferaltar mit all seinem Gerate, das Handfaft mit seinem Fulie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'die Amtskleider und die heiligen Kleider des Priesters Aaron und die Kleider seiner Sohne, priesterlich zu dienen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'das Salbol und das Rauchwerk von Spezerei zum Heiligtum. Alles, was ich dirgeboten habe, werden sie machen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Sage den Kindern Israel und sprich: Haltet meinen Sabbat; denn derselbe istein Zeichen zwischen mir und euch auf eure Nachkommen, daß ihrwisset, daß ich der HERR bin, der euch heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Darum so haltet meinen Sabbat; denn ersoll euch heilig sein. Wer ihn entheiliget, der soil des Todes sterben, Denn wer eine Arbeit darinnen tut, des Seele soil ausgerottet werden von seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage soil man arbeiten; aber am siebenten Tage ist Sabbat, die heilige Ruhe des HERRN. Wer eine Arbeit tut am Sabbattage, soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Darum sollen die Kinder Israel den Sabbat halten, daß sie ihn auch bei ihren Nachkommen halten zum ewigen Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Er ist ein ewig Zeichen zwischen mir und den Kindern Israel. Denn in sechs Tagen machte der HERR Himmel und Erde; aber am siebenten Tage ruhete er und erquickte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Und da der HERR ausgeredet hatte mit Mose auf dem Berge Sinai, gab er ihm zwo Tafeln des Zeugnisses; die waren steinern und geschrieben mit dem Finger Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Da aber das Volk sah, daß Mose verzog, von dem Berge zu kommen, sammelte sich\'s wider Aaron und sprach zu ihm: Auf, und mach uns Gotter, die vor uns hergehen! Denn wirwissen nicht, was diesem Mann Mose widerfahren ist, der uns aus Agyptenland gefuhret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Aaron sprach zu ihnen: Reiftet ab die güldenen Ohrenringe an den Ohren eurer Weiber, eurer Sohne und eurer Tochter und bringet sie zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da rift alles Volk seine güldenen Ohrenringe von ihren Ohren und brachten sie zu Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Und er nahm sie von ihren Handen und entwarf es mit einem Griffel und machte ein gegossen Kalb. Und sie sprachen: Das sind deine Gotter, Israel, die dich aus Agyptenland gefuhret haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Da das Aaron sah, bauete er einen Altar vor ihm und lieft ausrufen und sprach: Morqen ist des HERRN Fest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Und stunden des Morgens fruhe auf und opferten Brandopfer und brachten dazu Dankopfer. Danach setzte sich das Volk zu essen und zu trinken, und stunden auf zu spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Der HERR aber sprach zu Mose: Gehe, steig hinab; denn dein Volk, das du aus Agyptenland gefuhret hast, hat\'s verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Sie sind schnell von dem Wege getreten, den ich ihnen geboten habe. Sie haben ihnen ein gegossen Kalb gemacht und haben\'s angebetet und ihm geopfert und gesagt: Das sind deine Gotter, Israel, die dich aus Agyptenland gefuhret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und den HERR sprach zu Mose: Ich sehe, daß es ein halsstarrig Volk ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Und nun laft mich, daß mein Zorn liber sie ergrimme und sie auffresse, so will ich dich zum groften Volk machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mose aber flehete von dem HERRN, seinem Gott, und sprach: Ach, HERR, war urn will dein Zorn ergrimmen liber dein Volk, das du mit grofter Kraft und starker Hand hast aus Agyptenland gefuhret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Agypter sagen und sprechen: Er hat sie zu ihrem Unglück ausgefuhrt, daß er sie erwlirgete im Gebirge und vertilgete sie von dem Erdboden? Kehre dich von dem Grimm deines Zorns und sei gnadig liber die Bosheit deines Volks!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenk an deine Diener, Abraham, Isaak und Israel, denen du bei dirselbst geschworen und ihnen verheiften hast: Ich will euren Samen mehren wie die Sterne am Himmel, und alles Land, das ich verheiften habe, will ich eurem Samen geben, und sollen es besitzen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Also gereuete den HERRN das Libel, das er drauete seinem Volk zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Mose wandte sich und stieg vom Berge und hatte zwo Tafeln des Zeugnisses in seiner Hand, die waren geschrieben auf beiden Seiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Und Gott hatte sie selbst gemacht und selbst die Schrift drein gegraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Da nun Josua horete des Volks Geschrei, daß sie jauchzeten, sprach er zu Mose: Es ist ein Geschrei im Lager wie im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Er antwortete: Es ist nicht ein Geschrei gegeneinander, deren, die obliegen und unterliegen, sondern ich hore ein Geschrei eines Singetanzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Als er aber nahe zum Lager kam und das Kalb und den Reigen sah, ergrimmete er mit Zorn und warf die Tafeln aus seiner Hand und zerbrach sie unten am Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Und nahm das Kalb, das sie gemacht hatten, und verbrannte es mit Feuer und zermalmete es zu Pulver und staubte es aufs Wasser und gab\'s den Kindern Israel zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Und sprach zu Aaron: Was hat dir das Volk getan, daß du eine so grofte Sünde üben sie gebracht hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron sprach: Mein Herr lasse seinen Zorn nicht ergrimmen. Du weiftt, daß dies Volk bose ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Sie sprachen zu mir: Mache uns Gotter, die vor uns hergehen; denn wirwissen nicht, wie es diesem Mann Mose gehet, der uns aus Agyptenland gefuhret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Ich sprach zu ihnen: Wer hat Gold, der reifte es ab und gebe es mir. Und ich warf es ins Feuer; daraus istdas Kalb geworden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Da nun Mose sah, dafi das Volk los worden war (denn Aaron hatte sie losgemacht durch ein Geschwatz, damit er sie fein wollte anrichten),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'trat er in das Tor des Lagers und sprach: Her zu mir, werdem HERRN angehoret! Da sammelten sich zu ihm alle Kinder Levi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Und er sprach zu ihnen: So spricht der HERR, der Gott Israels: Gurte ein jeglicher sein Schwert auf seine Lenden und durchgehet hin und wieder von einem Torzum andern im Lager und erwurge ein jeglicher seinen Bruder, Freund und Nachsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Die Kinder Levi taten, wie ihnen Mose gesagt hatte, und fiel des Tages vom Volk dreitausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Da sprach Mose: Fullet heute eure Hande dem HERRN, ein jeglicher an seinem Sohn und Bruder, daß heute uber euch der Segen gegeben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Des Morgens sprach Mose zum Volk: Ihr habt eine grofte Sunde getan; nun will ich hinaufsteigen zu dem HERRN, ob ich vielleicht eure Sunde versohnen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Als nun Mose wieder zum HERRN kam, sprach er: Ach, das Volk hat eine grofte Sunde getan und haben ihnen guldene Gotter gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nun vergib ihnen ihre Sunde! Wo nicht, so tilge mich auch aus deinem Buch, das du geschrieben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Der HERR sprach zu Mose: Was? Ich will den aus meinem Buch tilgen, der an mir sundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'So gehe nun hin und führe das Volk, dahin ich dir gesagt habe. Siehe, mein Engel soil vor dir hergehen. Ich werde ihre Sunde wohl heimsuchen, wenn meine Zeit kommt heimzusuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Also strafte der HERR das Volk, daß sie das Kalb hatten gemacht, welches Aaron gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Der HERR sprach zu Mose: Gehe, zeuch von dannen, du und das Volk, das du aus Agyptenland gefuhret hast, ins Land, das ich Abraham, Isaak und Jakob geschworen habe und gesagt: Deinem Samen will ich\'s geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ich will vor dir hersenden einen Engel und ausstoften die Kanaaniter, Amoriter, Hethiter, Pheresiter, Heviter und Jebusiter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'ins Land, da Milch und Honig innen fleuftt. Ich will nicht mit dir hinaufziehen; denn du bist ein halsstarrig Volk. Ich mochte dich unterwegen auffressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Da das Volk diese bose Rede horete, trugen sie Leide, und niemand trug seinen Schmuck an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Und der HERR sprach zu Mose: Sage zu den Kindern Israel: Ihr seid ein halsstarrig Volk. Ich werde einmal plotzlich uber dich kommen und dich vertilgen. Und nun lege deinen Schmuck von dir, daß ich wisse, was ich dir tun soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Also taten die Kinder Israel ihren Schmuck von sich vor dem Berge Horeb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mose aber nahm die Hutte und schlug sie auf, auften feme vor dem Lager, und hieft sie eine Hutte des Stifts. Und wer den HERRN fragen wollte, muftte herausgehen zur Hutte des Stifts vor das Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Und wenn Mose ausging zur Hutte, so stund alles Volk auf, und trat ein jeglicher in seiner Hutte Tür und sahen ihm nach, bis er in die Hutte kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Und wenn Mose in die Hutte kam, so kam die Wolkensaule hernieder und stund in der Hutte Tür und redete mit Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Und alles Volk sah die Wolkensaule in der Hutte Tur stehen, und stunden auf und neigten sich, ein jeglicher in seiner Hutte Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Der HERR aber redete mit Mose von Angesicht zu Angesicht, wie ein Mann mit seinem Freunde redet. Und wenn er wiederkehrete zum Lager, so wich sein Diener Josua, der Sohn Nuns, der Jungling, nicht aus der Hutte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Und Mose sprach zu dem HERRN: Siehe, du sprichst zu mir: Führe das Volk hinauf, und lassest mich nicht wissen, wen du mit mir senden willst, so du doch gesagt hast: Ich kenne dich mit Namen, und hast Gnade vor meinen Augen funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Habe ich denn Gnade vor deinen Augen funden, so laft mich deinen Weg wissen, damit ich dich kenne und Gnade vor deinen Augen finde. Und siehe doch, daß dies Volk dein Volk ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Er sprach: Mein Angesicht soil gehen, damit will ich dich leiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Er aber sprach zu ihm: Wo nicht dein Angesicht gehet, so führe uns nicht von dannen hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Denn wobei soil doch erkannt werden, daß ich und dein Volk vor deinen Augen Gnade funden haben, ohne wenn du mit uns gehest? auf daß ich und dein Volk geruhmet werden vor allem Volk, das auf dem Erdboden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Der HERR sprach zu Mose: Was du jetzt geredet hast, will ich auch tun: denn du hast Gnade vor meinen Augen funden, und ich kenne dich mit Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Er aber sprach: So laft mich deine Herrlichkeit sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und er sprach: Ich will vor deinem Angesicht her alle meine Güte gehen lassen und will lassen predigen des HERRN Namen vor dir. Wem ich aber gnadig bin, dem bin ich gnadig; und wes ich mich erbarme, des erbarme ich mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Und sprach weiter: Mein Angesicht kannst du nicht sehen; denn kein Mensch wird leben, der mich siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und der HERR sprach weiter: Siehe, es ist ein Raum bei mir, da sollst du auf dem Fels stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Wenn denn nun meine Herrlichkeit vorubergehet, will ich dich in der Felskluft lassen stehen, und meine Hand soil ob dir halten, bis ich vorubergehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Und wenn ich meine Hand von dir tue, wirst du mir hinten nachsehen; aber mein Angesicht kann man nicht sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Und der HERR sprach zu Mose: Haue dir zwo steinerne Tafeln, wie die ersten waren, dafi ich die Worte darauf schreibe, die in den ersten Tafeln waren, welche du zerbrochen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Und sei morgen bereit, daß du frühe auf den Berg Sinai steigest und daselbst zu mir tretest auf des Berges Spitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Und laft niemand mit dir hinaufsteigen, daß niemand gesehen werde urn den ganzen Berg her; auch kein Schaf noch Rind laft weiden gegen diesem Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Und Mose hieb zwo steinerne Tafeln, wie die ersten waren, und stund des Morgens frühe auf und stieg auf den Berg Sinai wie ihm der HERR geboten hatte, und nahm die zwo steinernen Tafeln in seine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Da kam der HERR hernieder in einer Wolke und trat daselbst bei ihn und predigte von des HERRN Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Und da der HERR vor seinem Angesicht uberging, rief er: HERR, HERR Gott, barmherzig und gnadig und geduldig und von grafter Gnade und Treue;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'der du beweisest Gnade in tausend Glied und vergibst Missetat, Ubertretung und Sunde, und vor welchem niemand unschuldig ist; der du die Missetat der Vater heimsuchest auf Kinder und Kindeskinder bis ins dritte und vierte Glied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Und Mose neigete sich eilend zu der Erde und betete ihn an,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'und sprach: Habe ich, HERR, Gnade vor deinen Augen funden, so gehe der HERR mit uns; denn es ist ein halsstarrig Volk, daß du unserer Missetat und Sunde gnadig seiest und lassest uns dein Erbe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Und er sprach: Siehe, ich will einen Bund machen vor all deinem Volk und will Wunder tun, dergleichen nicht geschaffen sind in alien Landen und unter alien Vdlkern; und alles Volk, darunter du bist, soil sehen des HERRN Werk; denn wunderbarüch soil es sein, das ich bei dir tun werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Halte, was ich dir heute gebiete. Siehe, ich will vor dir her ausstoften die Amoriter, Kanaaniter, Hethiter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hute dich, daß du nicht einen Bund machest mit den Einwohnern des Landes, da du einkommst, daß sie dir nicht ein Argernis unter dirwerden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'sondern ihre Altare solist du umstürzen und ihre Gotzen zerbrechen und ihre Haine ausrotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Denn du sollst keinen andern Gott anbeten. Denn der HERR heiftet ein Eiferer, darum daß er ein eifriger Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Auf daß, wo du einen Bund mit des Landes Einwohnern machest, und wenn sie huren ihren Gottern nach und opfern ihren Gottern, daß sie dich nicht laden, und du von ihrem Opferessest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'und nehmest deinen Sohnen ihre Tochter zu Weibern, und dieselben dann huren ihren Gottern nach und machen deine Sohne auch ihren Gottern nachhuren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Du sollst dir keine gegossenen Gotter machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest der ungesauerten Brote sollst du halten. Sieben Tage sollst du ungesauert Brot essen, wie ich dir geboten habe, urn die Zeit des Mondes Abib; denn in dem Mond Abib bist du aus Agypten gezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alles, was seine Mutter am ersten bricht, ist mein; was mannlich sein wird in deinem Vieh, das seine Mutter bricht, es sei Ochse Oder Schaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Aber den Erstling des Esels sollst du mit einem Schaf losen. Wo du es aber nicht losest, so brich ihm das Genick. Aile Erstgeburt deiner Sohne sollst du losen. Und daß niemand vor mir leer erscheine!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage sollst du arbeiten; am siebenten Tage sollst du feiern, beide mit Pflügen und mit Ernten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Das Fest der Wochen sollst du halten mit den Erstlingen der Weizenernte und das Fest der Einsammlung, wenn das Jahr urn ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal im Jahr sollen aile Mannsnamen erscheinen vor dem Herrscher, dem HERRN und Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Wenn ich die Heiden vor dir ausstoften und deine Grenze weitern werde, soil niemand deines Landes begehren, dieweil du hinaufgehest dreimal im Jahr, zu erscheinen vor dem HERRN, deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst das Blut meines Opfers nicht opfern auf dem gesauerten Brot; und das Opfer des Osterfestes bleiben bis an den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Das Erstling von den ersten Fruchten deines Ackers sollst du in das Haus des HERRN deines Gottes, bringen. Du sollst das Bocklein nicht kochen, wenn es noch an seiner Mutter Milch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und der HERR sprach zu Mose: Schreibe diese Worte; denn nach diesen Worten habe ich mit dir und mit Israel einen Bund gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er war allda bei dem HERRN vierzig Tage und vierzig Nachte und aft kein Brot und trank kein Wasser. Und erschrieb auf die Tafeln solchen Bund, die zehn Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Da nun Mose vom Berge Sinai ging, hatte er die zwo Tafeln des Zeugnisses in seiner Hand; und wuftte nicht, daß die Haut seines Angesichts glanzete davon, daß er mit ihm geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Und da Aaron und aile Kinder Israel sahen, daß die Haut seines Angesichts glanzete, furchteten sie sich, zu ihm zu nahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Da rief ihnen Mose; und sie wandten sich zu ihm, beide Aaron und alle Obersten der Gemeine; und er redete mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Danach naheten alle Kinder Israel zu ihm. Und er gebot ihnen alles, was der HERR mit ihm geredet hatte auf dem Berge Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Und wenn er solches alles mit ihnen redete, legte ereine Decke auf sein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Und wenn er hineinging vor den HERRN, mit ihm zu reden, tat er die Decke ab, bis er wieder herausging. Und wenn er herauskam und redete mit den Kindern Israel, was ihm geboten war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'so sahen dann die Kinder Israel sein Angesicht an, wie dafi die Haut seines Angesichts glanzete; so tat er die Decke wieder auf sein Angesicht, bis er wieder hineinging, mit ihm zu reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Und Mose versammelte die ganze Gemeine der Kinder Israel und sprach zu ihnen: Das ist\'s, das der HERR geboten hat, das ihr tun sollt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage sollt ihr arbeiten; den siebenten Tag aber sollt ihr heilig halten, einen Sabbat der Ruhe des HERRN. Werdarinnen arbeitet, soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ihr sollt kein Feuer anzünden am Sabbattage in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Und Mose sprach zu der ganzen Gemeine der Kinder Israel: Das ist\'s, das der HERR geboten hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Gebt unter euch Hebopfer dem HERRN, also daß das Hebopfer des HERRN ein jeglicher williglich bringe, Gold, Silber, Erz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'gelbe Seide, Scharlaken, Rosinrot, weilie Seide und Ziegenhaar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'rotlich Widderfell, Dachsfell und Fohrenholz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, '01 zur Lampe und Spezerei zur Salbe und zu gutem Rauchwerk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Onyx und eingefaßte Steine zum Leibrock und zum Schildlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und wer unter euch verstandig, ist, der komme und mache, was der HERR geboten hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'namlich die Wohnung mit ihrer Hutte und Decke, Rinken, Brettern, Riegeln, Saulen und Füßen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'die Lade mit ihren Stangen, den Gnadenstuhl und Vorhang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'den Tisch mit seinen Stangen und alle seinem Gerate und die Schaubrote;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'den Leuchter, zu leuchten, und sein Gerat und seine Lampen und das 01 zum Licht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'den Rauchaltar mit seinen Stangen, die Salbe und Spezerei zum Rauchwerk; das Tuch vor der Wohnung Tur;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'den Brandopferaltar mit seinem ehernen Gitter, Stangen und alle seinem Gerat; das Handfali mit seinem Fufie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'den Umhang des Vorhofs mit seinen Saulen und Füßen und das Tuch des Tors am Vorhof;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'die Nagel der Wohnung und des Vorhofs mit ihren Saulen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'die Kleider des Amts zum Dienst im Heiligen, die heiligen Kleider Aarons, des Priesters, mit den Kleidern seiner Sohne zum Priestertum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Da ging die ganze Gemeine der Kinder Israel aus von Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Und alle, die es gerne und williglich gaben, kamen und brachten das Hebopfer dem HERRN zum Werk der Hutte des Stifts und zu alle seinem Dienst und zu den heiligen Kleidern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Es brachten aber beide, Mann und Weib, wer es williglich tat, Hefte, Ohrenrinken, Ringe und Spangen und allerlei gulden Gerat. Dazu brachte jedermann Gold zur Webe dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und wer bei ihm fand gelbe Seide, Scharlaken, Rosinrot, weiße Seide, Ziegenhaar, rotlich Widderfell und Dachsfell, der brachte es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Und wer Silber und Erz hub, der brachte es zur Hebe dem HERRN. Und wer Fohrenholz bei ihm fand, der brachte es zu allerlei Werk des Gottesdienstes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und welche verstandige Weiber waren, die wirkten mit ihren Handen und brachten ihr Werk von gelber Seide, Scharlaken, Rosinrot und weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und welche Weiber solche Arbeit konnten und willig dazu waren, die wirkten Ziegenhaar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Die Fursten aber brachten Onyx und eingefalite Steine zum Leibrock und zum Schildlein');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'und Spezerei und 01 zu den Lichtern und zur Salbe und zu gutem Rauchwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Also brachten die Kinder Israel williglich, beide Mann und Weib, zu allerlei Werk, das der HERR geboten hatte durch Mose, daß man\'s machen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Und Mose sprach zu den Kindern Israel: Sehet, der HERR hat mit Namen berufen den Bezaleel, den Sohn Uris, des Sohns Hurs, vom Stamm Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'und hat ihn erfüllet mit dem Geist Gottes, dal J er weise, verstandig, geschickt sei zu allerlei Werk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'kunstlich zu arbeiten am Gold, Silber und Erz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Edelstein schneiden und einsetzen, Holz zimmern, zu machen allerlei kunstliche Arbeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Und hat ihm sein Herz unterweiset samt Ahaliab, dem Sohne Ahisamachs, vom Stamm Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat ihr Herz mit Weisheit erfüllet, zu machen allerlei Werk, zu schneiden, wirken und zu sticken mit gelber Seide, Scharlaken, Rosinrot und weifter Seide und mit Weben, daß sie machen allerlei Werk und kunstliche Arbeit erfinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Da arbeiteten Bezaleel und Ahaliab und alle weisen Manner, denen der HERR Weisheit und Verstand gegeben hatte, zu wissen, wie sie allerlei Werk machen sollten, zum Dienst des Heiligtums nach allem, das der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Und Mose rief dem Bezaleel und Ahaliab und alien weisen Mannern, denen der HERR Weisheit gegeben hatte in ihr Herz, namlich alien, die sich willig darerboten und hinzutraten, zu arbeiten an dem Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie nahmen zu sich von Mose alle Hebe, die die Kinder Israel brachten zu dem Werk des Dienstes des Heiligtums, daß es gemacht würde. Denn sie brachten alle Morgen ihre willige Gabe zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da kamen alle Weisen, die am Werk des Heiligtums arbeiteten, ein jeglicher seines Werks, das sie machten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'und sprachen zu Mose: Das Volk bringet zu viel, mehr denn zum Werk dieses Dienstes not ist, das der HERR zu machen geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da gebot Mose, daß man rufen ließ durchs Lager: Niemand tue mehrzur Hebe des Heiligtums! Da horete das Volk auf zu bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Denn des Dinges war genug zu allerlei Werk, das zu machen war, und noch übrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Also machten alle weisen Manner unter den Arbeitern am Werk die Wohnung, zehn Teppiche von gezwirnter weifier Seide, gelber Seide, Scharlaken, Rosinrot, Cherubim, kunstlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Lange eines Teppichs war achtundzwanzig Ellen und die Breite vier Ellen, und waren alle in einem Mali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Und er heftete je fünf Teppiche zusammen, einen an den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Und machte gelbe Schlauflein an eines jeglichen Teppichs Ort, da sie zusammengefuget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'je funfzig Schlauflein an einen Teppich, damit einer den andern fafite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Und machte funfzig guldene Haklein; und fugte die Teppiche mit den Haklein einen an den andern zusammen, daß es eine Wohnung wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Und er machte elf Teppiche von Ziegenhaaren zur Hütte üben die Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'dreißig Ellen lang und vier Ellen breit, alle in einem Mali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Und fugte ihrer fünf zusammen auf ein Teil und sechs zusammen aufs andere Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Und machte je funfzig Schlauflein an jeglichen Teppich am Ort, damit sie zusammengeheftet würden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Und machte je funfzig eherne Haklein, damit die Hutte zusammen in eins gefuget würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Und machte eine Decke uber die Hutte von rotlichen Widderfellen und uber die noch eine Decke von Dachsfellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Und machte Bretter zur Wohnung von Fohrenholz, die stehen sollten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'ein jegliches zehn Ellen lang und anderthalb Ellen breit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'und an jeglichem zween Zapfen, da mit eins an das andere gesetzt wurde. Also machte er alle Bretter zur Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'daß derselben Bretter zwanzig gegen Mittag stunden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'und machte vierzig silberne Fufie drunter, unter jeglich Brett zween Füße an seinen zween Zapfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Also zur andern Seite der Wohnung, gegen Mitternacht, machte er auch zwanzig Bretter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'mit vierzig silbernen Füßen, unter jeglich Brett zween Füße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Aber hinten an der Wohnung gegen den Abend machte er sechs Bretter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'und zwei andere hinten an den zwo Ecken der Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'daß ein jegliches der beiden sich mit seinem Ortbrett von unten auf gesellete und oben am Haupt zusammenkame mit einer Klammer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'daß der Bretter acht wurden und sechzehn silberne Füße, unter jeglichem zween Füße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Und er machte Riegel von Fohrenholz, fünf zu den Brettern auf der einen Seite der Wohnung');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'und fünf auf der andern Seite und funf hinten an, gegen den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Und machte die Riegel, daß sie mitten an den Brettern durchhingestoßen würden, von einem Ende zum andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Und überzog die Bretter mit Golde; aber ihre Rinken machte er von Gold zu den Riegeln und überzog die Riegel mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Und machte den Vorhang mit den Cherubim dran kunstlich mit gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und machte zu demselben vier Saulen von Fohrenholz und überzog sie mit Gold und ihre Kopfe von Golde; und goß dazu vier silberne Füße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Und machte ein Tuch in der Tür der Hütte; von gelber Seide, Scharlaken, Rosenrot und gezwirnter weißer Seide gestickt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'und fünf Saulen dazu mit ihren Kopfen und überzog ihre Kopfe und Reife mit Golde; und funf eherne Füße dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Und Bezaleel machte die Lade von Fohrenholz, dritthalb Ellen lang, anderthalb Ellen breit und hoch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'und überzog sie mitfeinem Golde, inwendig und auswendig; und machte ihr einen güldenen Kranz umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Und goß vier guldene Rinken an ihre vier Ecken, auf jeglicher Seite zween.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Und machte Stangen von Fohrenholz und überzog sie mit Golde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'und tat sie in die Rinken an der Lade Seiten, daß man sie tragen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Und machte den Gnadenstuhl von feinem Golde, dritthalb Ellen lang und anderthalb Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Und machte zween Cherubim von dichtem Golde an die zwei Enden des Gnadenstuhls,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'einen Cherub an diesem Ende, den andern an jenem Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Und die Cherubim breiteten ihre Flügel aus von oben her und deckten damit den Gnadenstuhl; und ihre Antlitze stunden gegeneinander und sahen auf den Gnadenstuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Und er machte den Tisch von Fohrenholz, zwo Ellen lang, eine Elle breit und anderthalb Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Und uberzog ihn mitfeinem Golde und machte ihm einen guldenen Kranz umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Und machte ihm eine Leiste umher, einer Hand breit hoch; und machte einen guldenen Kranz urn die Leiste her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Und goß dazu vierguldene Rinken und tatsie an die vier Orte an seinen vier Füßen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'hart an der Leiste, daß die Stangen drinnen waren, damit man den Tisch trüge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Und machte die Stangen von Fohrenholz und uberzog sie mit Gold, daß man den Tisch damit trüge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Und machte auch von feinem Golde das Gerate auf den Tisch: Schusseln, Becher, Kannen und Schalen, damit man aus- und einschenkte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Und machte den Leuchtervon feinem, dichtem Golde. Daran waren der Schaft mit Rohren, Schalen, Knaufen und Blumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Sechs Rohren gingen zu seinen Seiten aus, zu jeglicher Seite drei Rohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Drei Schalen waren an jeglichem Rohr mit Knaufen und Blumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'An dem Leuchter aber waren vier Schalen mit Knaufen und Blumen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'je unter zwo Rohren ein Knauf, daß also sechs Rohren aus ihm gingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'und ihre Knaufe und Rohren daran, und war alles aus dichtem, feinem Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Und machte die sieben Lampen mit ihren Lichtschneuzen und Loschnapfen von feinem Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Zentner feines Goldes machte er ihn und alle seine Gerate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Er machte auch den Rauchaltar von Fohrenholz, eine Elle lang und breit, gleich viereckig und zwo Ellen hoch, mit seinen Hdrnern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Und uberzog ihn mitfeinem Golde, sein Dach und seine Wande rings umher und seine Horner. Und machte ihm einen Kranz umher von Golde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'und zween güldene Rinken unter dem Kranz zu beiden Seiten, daß man Stangen drein tate und ihn damit trüge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Aber die Stangen machte er von Fohrenholz und uberzog sie mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Und machte die heilige Salbe und Rauchwerk von reiner Spezerei nach Apothekerkunst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Und machte den Brandopferaltar von Fohrenholz, fünf Ellen lang und, breit, gleich viereckig und drei Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Und machte vier Horner, die aus ihm gingen, auf seinen vier Ecken; und uber zog ihn mit Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Und machte allerlei Gerate zu dem Altar Aschentopfe, Schaufeln, Becken, Kreuel, Kohlpfannen: alles von Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Und machte am Altar ein Gitter, wie ein Netz, von Erz umher, von unten auf bis an die Halfte des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Und goß vier Rinken an die vier Orte des ehernen Gitters zu Stangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Dieselben machte er von Fohrenholz und uberzog sie mit Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Und tat sie in die Rinken an den Seiten des Altars, daß man ihn damit trüge; und machte ihn inwendig hohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Und machte das Handfaß von Erz und seinen Fuß auch von Erz, gegen den Weibern, die vor der Tür der Hütte des Stifts dieneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Und er machte einen Vorhof gegen Mittag mit einem Umhang hundert Ellen lang von gezwirnter weißer Seide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'mit ihren zwanzig Saulen und zwanzig Fußen von Erz, aber ihre Knaufe und Reife von Silber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'desselbengleichen gegen Mitternacht hundert Ellen mit zwanzig Saulen und zwanzig Fußen von Erz, aber ihre Knaufe und Reife von Silber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'gegen den Abend aber funfzig Ellen mitzehn Saulen und zehn Fußen, aber ihre Knaufe und Reife von Silber;:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'gegen den Morgen aber funfzig Ellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'funfzehn Ellen auf jeglicher Seite des Tors am Vorhof, je mit drei Saulen und drei Fußen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'und auf der andern Seite funfzehn Ellen, daß ihrer so viel war an der einen Seite des Tors am Vorhofe als auf der andern, mit drei Saulen und drei Fußen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'daß alle Umhange des Vorhofs waren von gezwirnter weißer Seide');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'und die Füße der Saulen von Erz und ihre Knaufe und Reife von Silber, also daß ihre Kopfe überzogen waren mit Silber; aber ihre Reife waren silbern an alien Saulen des Vorhofs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Und das Tuch in dem Tor des Vorhofs machte er gestickt, von gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide, zwanzig Ellen lang und fünf Ellen hoch, nach dem Maß der Umhange des Vorhofs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'dazu vier Saulen und vier Füße von Erz und ihre Knaufe von Silber und ihre Kopfe überzogen und ihre Reife silbern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Und alle Nagel der Wohnung und des Vorhofs ringsherum waren von Erz:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Das ist nun die Summa zu der Wohnung des Zeugnisses, die erzahlet ist, wie Mose gesagt hat, zum Gottesdienst der Leviten unter der Hand Ithamars, Aarons, des Priesters, Sohnes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'die Bezaleel, der Sohn Uris, des Sohns Hurs, vom Stamm Juda machte, alles, wie der HERR Mose geboten hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'und mit ihm Ahaliab, der Sohn Ahisamachs, vom Stamm Dan, ein Meister zu schneiden, zu wirken und zu sticken mit gelber Seide, Scharlaken, Rosinrot und weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, das verarbeitet ist in diesem ganzen Werk des Heiligtums, das zur Webe gegeben ward, ist neunundzwanzig Zentner, siebenhundertunddreil Jig Sekel nach dem Sekel des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Des Silbers aber, das von der Gemeine kam, war hundert Zentner, tausendsiebenhundertfunfundsiebenzig Sekel, nach dem Sekel des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'So manch Haupt, so mancher halber Sekel, nach dem Sekel des Heiligtums, von alien, die gezahlet wurden, von zwanzig Jahren an und druber, sechshundertmal tausend dreitausendfunfhundertundfünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Aus den hundert Zentnern Silbers goß man die Fufie des Heiligtums und die Fufie des Vorhangs, hundert Fuße aus hundert Zentnern, je einen Zentner zum Fuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Aber aus den tausend siebenhundertundfunfundsiebenzig Sekeln wurden gemacht der Saulen Knaufe, und ihre Kopfe uberzogen und ihre Reife.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Die Webe aber des Erzes war siebenzig Zentner, zweitausendundvierhundert Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Daraus wurden gemacht die Fuße in der Tur der Hütte des Stiffs und der eherne Altar und das eherne Gitter dran und alles Gerate des Altars,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'dazu die Füße des Vorhofs ringsherum und die Füße des Tors am Vorhof, alle Nagel der Wohnung und alle Nagel des Vorhofs ringsherum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Aber von der gelben Seide, Scharlaken und Rosinrot machten sie Aaron Kleider, zu dienen im Heiligtum, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und er machte den Leibrock mit Golde, gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Und schlug das Gold und schnitt\'s zu Faden, daß man\'s künstlich wirken konnte unter die gelbe Seide, Scharlaken, Rosinrot und weiße Seide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'daß man\'s auf beiden Achseln zusammenfügte und an beiden Seiten zusammenbande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Und sein Gurt war nach derselben Kunst und Werk von Gold, gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Und sie machten zween Onyxsteine, umher gefasset mit Gold, gegraben durch die Steinschneider, mit den Namen der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'und heftete sie auf die Schultern des Leibrocks, daß es Steine seien zum Gedachtnis der Kinder Israel, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Und sie machten das Schildlein nach der Kunst und Werk des Leibrocks von Gold, gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'daß es viereckig und zwiefach war, einer Hand lang und breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und fulleten es mit vier Riegen Steinen. Die erste Riege war ein Sarder, Topaser und Smaragd;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'die andere ein Rubin, Saphir und Demant;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'die dritte ein Lynkurer, Achat und Amethyst;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'die vierte ein Türkis, Onyx und Jaspis, umher gefasset mit Gold in alien Riegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Und die Steine stunden nach den zwolf Namen der Kinder Israel, gegraben durch die Steinschneider, ein jeglicher seines Namens, nach den zwolf Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Und sie machten am Schildlein Ketten mitzwei Enden von feinem Gold');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'und zwo guldene Spangen und zween guldene Ringe: und hefteten die zween Ringe auf die zwo Ecken des Schildleins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Und die zwo guldenen Ketten taten sie in die zween Ringe auf den Ecken des Schildleins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Aber die zwei Enden der Ketten taten sie an die zwo Spangen und hefteten sie auf die Ecken des Leibrocks gegeneinander uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Und machten zween andere guldene Ringe und hefteten sie an die zwo andern Ecken des Schildleins an seinen Ort, daß es fein anlage auf dem Leibrock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Und machten zween andere guldene Ringe, die taten sie an die zwo Ecken unten am Leibrock gegeneinander uber, da der Leibrock unten zusammengehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'daß das Schildlein mit seinen Ringen an die Ringe des Leibrocks geknupft wurde mit einer gelben Schnur, daß es auf dem Leibrock hart anlage und nicht von dem Leibrock los wurde, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Und er machte den Seidenrock zum Leibrock, gewirkt ganz von gelber Seide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'und sein Loch oben mitten inne und eine Borte urns Loch her gefaltet, daß er nicht zerrisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Und sie machten an seinem Saum Granatapfel von gelber Seide, Scharlaken, Rosinrot und gezwirnter weißer Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Und machten Schellen von feinem Golde; die taten sie zwischen die Granatapfel ringsumher am Saum des Seidenrocks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'je ein Granatapfel und eine Schelle urn und urn am Saum, darin zu dienen, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Und machten auch die engen Rocke, von weißer Seide gewirkt, Aaron und seinen Sohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'und den Hut von weißer Seide und die schonen Hauben von weißer Seide und Niederkleider von gezwirnter weißer Leinwand');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'und den gestickten Gürtel von gezwirnter weißer Seide, gelber Seide, Scharlaken, Rosinrot, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Sie machten auch das Stirnblatt, namlich die heilige Krone, von feinem Golde und gruben Schrift drein: Die Heiligkeit des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und banden eine gelbe Schnur dran daß sie an den Hut von oben her geheftet würde, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Also ward vollendet das ganze Werk der Wohnung der Hutte des Stitts. Und die Kinder Israel taten alles, was der HERR Mose geboten hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'und brachten die Wohnung zu Mose: die Hutte und alle ihre Gerate, Haklein, Bretter, Riegel, Saulen, Fufte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'die Decke von rotlichen Widderfellen, die Decke von Dachsfellen und den Vorhang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'die Lade des Zeugnisses mit ihren Stangen; den Gnadenstuhl;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'den Tisch und alle seine Gerate und die Schaubrote;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'den schonen Leuchter, mit den Lampen zubereitet, und alle seinem Gerate, und 01 zu Lichtern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'den guldenen Altar und die Salbe und gut Rauchwerk; das Tuch in der Hutte Tur;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'den ehernen Altar und sein ehern Gitter mit seinen Stangen und alle seinem Gerat; das Handfaft mit seinem Fuft;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'die Umhange des Vorhofs mit: seinen Saulen und Füften; das Tuch im Tor des Vorhofs mit seinen Seilen und Nageln und allem Gerate zum Dienst der Wohnung der Hutte des Stifts;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'die Amtskleider des Priesters Aaron, zu dienen im Heiligtum, und die Kleider seiner Sohne, daß sie Priesteramt taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Alles, wie der HERR Mose geboten hatte, taten die Kinder Israel an alle diesem Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Und Mose sah an alle dies Werk; und siehe, sie hatten es gemacht, wie der HERR geboten hatte. Und er segnete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Du sollst die Wohnung der Hutte des Stifts aufrichten am ersten Tage des ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Und sollst darein setzen die Lade des Zeugnisses und vor die Lade den Vorhang hangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Und sollst den Tisch darbringen und ihn zubereiten und den Leuchter darstellen und die Lampen drauf setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Und sollst den guldenen Rauchaltar setzen vor die Lade des Zeugnisses und das Tuch in der Tur der Wohnung aufhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Den Brandopferaltar aber sollst du setzen heraus vor die Tur der Wohnung der Hutte des Stifts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'und das Handfaft zwischen der Hutte des Stifts und dem Altar, und Wasser drein tun;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'und den Vorhof stellen umher und das Tuch in der Tur des Vorhofs aufhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Und sollst die Salbe nehmen und die Wohnung und alles, was drinnen ist, salben; und sollst sie weihen mit alle ihrem Gerate, daß sie heilig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Und sollst den Brandopferaltar salben mit alle seinem Gerate und weihen, daß erallerheiligst sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Sollst auch das Handfaft und seinen Fuft salben und weihen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Und sollst Aaron und seine Sohne vor die Tur der Hutte des Stifts führen und mit Wasser waschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'und Aaron die heiligen Kleider anziehen und salben und weihen, daß er mein Priester sei;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'und seine Sohne auch herzufuhren und ihnen die engen Rocke anziehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'und sie salben, wie du ihren Vater gesalbet hast, daß sie meine Priester seien. Und die Salbung sollen sie haben zum ewigen Priestertum bei ihren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose tat alles, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Also ward die Wohnung aufgerichtet im andern Jahr, am ersten Tage des ersten Monds.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Und da Mose sie aufrichtete, setzte er die Fufte und die Bretter und Riegel und richtete die Saulen auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Und breitete die Hutte aus zur Wohnung und legte die Decke der Hutte oben drauf, wie der HERR ihm geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Und nahm das Zeugnis und legte es in die Lade; und tat die Stangen an die Lade und tat den Gnadenstuhl oben auf die Lade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Und brachte die Lade in die Wohnung und hing den Vorhang vor die Lade des Zeugnisses, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Und setzte den Tisch in die Hutte des Stifts, in den Winkel der Wohnung gegen Mitternacht, auften vor dem Vorhang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Und bereitete Brot darauf vor dem HERRN, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Und setzte den Leuchter auch hinein gegen dem Tisch uber, in den Winkel der Wohnung gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Und tat Lampen drauf vor dem HERRN, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Und setzte den guldenen Altar hinein, vor den Vorhang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Und raucherte drauf mit gutem Rauchwerk, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Und hing das Tuch in die Tur der Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Aber den Brandopferaltar setzte er vor die Tur der Wohnung der Hutte des Stifts; und opferte drauf Brandopfer und Speisopfer, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Und das Handfaft setzte er zwischen die Hutte des Stifts und den Altar; und tat Wasser drein zu waschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Und Mose, Aaron und seine Sohne wuschen ihre Hande und Fufte draus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Denn sie müssen sich waschen, wenn sie in die Hutte des Stifts gehen Oder hinzutreten zum Altar, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Und er richtete den Vorhof auf, urn die Wohnung und urn den Altar her, und hing den Vorhang in das Tor des Vorhofs. Also vollendete Mose das ganze Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Da bedeckte eine Wolke die Hütte des Stiffs, und die Herrlichkeit des HERRN füllete die Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose konnte nicht in die Hütte des Stifts gehen, weil die Wolke drauf blieb, und die Herrlichkeit des HERRN die Wohnung füllete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Und wenn die Wolke sich aufhub von der Wohnung, so zogen die Kinder Israel, so oft sie reiseten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Wenn sich aber die Wolke nicht aufhub, so zogen sie nicht, bis an den Tag, da sie sich aufhub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn die Wolke des HERRN war des Tages auf der Wohnung, und des Nachts war sie feurig, vor den Augen des ganzen Hauses Israel, solange sie reiseten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Und der HERR rief Mose und redete mitihm von der Hütte des Stifts und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Welcher unter euch dem HERRN ein Opfer tun will, der tue es von dem Vieh, von Rindern und Schafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Will erein Brandopfer tun von Rindern, so opfere er ein Mannlein, das ohne Wandel sei, vor der Tür der Hütte des Stifts, daß es dem HERRN angenehm sei von ihm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'und lege seine Hand auf des Brandopfers Haupt, so wird es angenehm sein und ihn versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Und soil das junge Rind schlachten vor dem HERRN; und die Priester, Aarons Sohne, sollen das Blut herzubringen und auf den Altar umher sprengen, der vor der Tür der Hütte des Stifts ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Und man soil dem Brandopfer die Haut abziehen; und es soli in Stücke zerhauen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Und die Sohne Aarons, des Priesters, sollen ein Feuer auf den Altar machen und Holz oben drauf legen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Und sollen die Stücke, namlich den Kopf und das Fett, auf das Holz legen, das auf dem Feuer auf dem Altar liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Das Eingeweide aber und die Schenkel soil man mit Wasser waschen, und der Priester soli das alles anzünden auf dem Altar zum Brandopfer. Das ist ein Feuer zum sülien Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Will er aber von Schafen Oder Ziegen ein Brandopfer tun, so opfere er ein Mannlein, das ohne Wandel sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Und soil es schlachten zur Seite des Altars, gegen Mitternacht, vor dem HERRN. Und die Priester, Aarons Sohne, sollen sein Blut auf den Altar umher sprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Und man soli es in Stücke zerhauen. Und der Priester soli den Kopf und das Fett auf das Holz und Feuer, das auf dem Altar ist, legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Aber das Eingeweide und die Schenkel soil man mit Wasser waschen. Und der Priester soil es alles opfern und anzünden auf dem Altar zum Brandopfer. Das ist ein Feuer zum sülien Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Will er aber von Vogeln dem HERRN ein Brandopfer tun, so tue er\'s von Turteltauben Oder von jungen Tauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Und der Priester soil\'s zum Altar bringen und ihm den Kopf abkneipen, daß es auf dem Altar angezündet werde, und sein Blut ausbluten lassen an der Wand des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Und seinen Kropf mit seinen Federn soil man neben dem Altar gegen den Morgen auf den Aschenhaufen werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Und soil seine Flügel spalten, aber nicht abbrechen. Und also soil es der Priester auf dem Altar anzünden, auf dem Holz auf dem Feuer, zum Brandopfer. Das ist ein Feuer zum sutien Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Wenn eine See Lev dem HERRN ein Speisopfer tun will, so soil es von Semmelmehl sein; und soli 01 drauf giefien und Weihrauch drauf legen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'und also bringen zu den Priestern, Aarons Sohnen. Da soil der Priester seine Hand voll nehmen von demselben Semmelmehl und 01 samt dem ganzen Weihrauch und anzunden zum Gedachtnis auf dem Altar. Das ist ein Feuer zum sulien Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Das Ubrige aber vom Speisopfer soli Aarons und seiner Sohne sein. Das soil das Allerheiligste sein von den Feuern des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Will er aber kein Speisopfer tun vom Gebackenen im Ofen, so nehme er Kuchen von Semmelmehl ungesauert mit 01 gemenget, und ungesauerte Fladen, mit 01 bestrichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ist aber dein Speisopfer etwas vom Gebackenen in der Pfanne, so soli\'s von ungesauertem Semmelmehl, mit 01 gemenget, sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Und sollst es in Stucke zerteilen und 01 drauf gießen, so ist\'s ein Speisopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ist aber dein Speisopfer etwas auf dem Rost gerostet, so sollst du es von Semmelmehl mit 01 machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Und solist das Speisopfer, das du von solcherlei machen willst dem HERRN, zu dem Priester bringen; der soil\'s zu dem Altar bringen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'und desselben Speisopfer heben zum Gedachtnis und anzunden auf dem Altar. Das ist ein Feuer zum süßen Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Das Ubrige aber soil Aarons und seiner Sohne sein. Das soil das Allerheiligste sein von den Feuern des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'AILev Speisopfer, die ihr dem HERRN opfern wollt, sollt ihr ohne Sauerteig machen; denn kein Sauerteig noch Honig soil darunter dem HERRN zum Feuer angezundet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Aber zum Erstling sollt ihr sie dem HERRN bringen; aber auf keinen Altar sollen sie kommen zum sufien Geruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'AILev deine Speisopfer sollst du salzen, und dein Speisopfer soil nimmer ohne Salz des Bundes deines Gottes sein; denn in al Lev deinem Opfer sollst du Salz opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Willst du aber ein Speisopfer dem HERRN tun von den ersten Fruchten, sollst du die Sangen, am Feuer gedorret, klein zerstoßen und also das Speisopfer deiner ersten Früchte opfern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'und sollst 01 drauf tun und Weihrauch drauf legen, so ist\'s ein Speisopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Und der Priester soil von dem Zerstoftenen und vom 01 mit dem ganzen Weihrauch anzunden zum Gedachtnis. Das ist ein Feuer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Ist aber sein Opfer ein Dankopfer von Rindern, es sei ein Ochse Oder Kuh, soli er\'s opfern vor dem HERRN, das ohne Wandel sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Und soil seine Hand auf desselben Haupt legen und schlachten vor der Tur der Hutte des Stiffs. Und die Priester, Aarons Sohne, sollen das Blut auf den Altar umhersprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Und soil von dem Dankopfer dem HERRN opfern, namlich alles Fett am Eingeweide');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'und die Nieren mit dem Fett, das dran ist, an den Lenden, und das Netz urn die Leber, an den Nieren abgerissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Und Aarons Sohne sollen\'s anzunden auf dem Altar zum Brandopfer, auf dem Holz, das auf dem Feuer liegt. Das ist ein Feuer zum sülien Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Will er aber dem HERRN ein Dankopfer von kleinem Vieh tun, es sei ein Schops Oder Schaf, so soil\'s ohne Wandel sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ist\'s ein Lammlein soli er\'s vor den HERRN bringen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'und soil seine Hand auf desselben Haupt legen und schlachten vor der Hutte des Stiffs. Und die Sohne Aarons sollen sein Blut auf den Altar umher sprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Und soil also von dem Dankopfer dem HERRN opfern zum Feuer, namlich sein Fett, den ganzen Schwanz, von dem Rücken abgerissen, und alles Fett am Eingeweide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'die zwo Nieren mit dem Fett, das dran ist, an den Lenden, und das Netz urn die Leber, an den Nieren abgerissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Und der Priester soil\'s anzunden auf dem Altar zurßpeise des Feuersdem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ist aber sein Opfer eine Ziege, und bringet es vor den HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'soil er seine Hand auf ihr Haupt legen und sie schlachten vor der Hutte des Stiffs. Und die Sohne Aarons sollen das Blut auf den Altar umher sprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Und soil davon opfern ein Opfer dem HERRN, namlich das Fett am Eingeweide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'die Nieren mit dem Fett, das dran ist, an den Lenden, und das Netz uber der Leber, an den Nieren abgerissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Und der Priester soil\'s anzunden auf dem Altar zur Speise des Feuers, zum sülten Geruch. Alles Fett ist des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Das sei eine ewige Sitte bei euren Nachkommen in alien euren Wohnungen, daß ihr kein Fett noch Blut esset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Rede mit den Kindern Israel und sprich: Wenn eine See Lev sundigen würde aus Versehen an irgend einem Gebot des HERRN, das sie nicht tun sollte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'namlich so ein Priester, der gesalbet ist, sundigen wurde, daß er das Volk argerte: der soil fur seine Sünde, die er getan hat, einen jungen Farren bringen, der ohne Wandel sei, dem HERRN zum Sündopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Und soil den Farren vor die Tür der Hutte des Stitts bringen, vor den HERRN, und seine Hand auf desselben Haupt legen und schlachten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Und der Priester, der gesalbet ist, soil des Farren Bluts nehmen und in die Hutte des Stitts bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Und soil seinen Finger in das Blut tunken und damit siebenmal sprengen vor dem HERRN, vor dem Vorhang im Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Und soil desselben Biuts tun auf die Horner des Rauchaltars, der vor dem HERRN in der Hutte des Stifts stehet, und alles Blut gießen an den Boden des Brandopferaltars, der vor der Tür der Hutte des Stifts stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Und alles Fett des Sundopfers soil er heben, namlich das Fett am Eingeweide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'die zwo Nieren mit dem Fett, das dran ist, an den Lenden, und das Netz fiber der Leber, an den Nieren abgerissen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'gleichwie er\'s hebet vom Ochsen im Dankopfer; und soil\'s anzünden auf dem Brandopferaltar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Aber das Fell des Farren mit allem Fleisch, samt dem Kopf, und Schenkel und das Eingeweide und den Mist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'das soil er alles hinausführen außer dem Lager an eine reine Statte, da man die Asche hinschüttet, und soil\'s verbrennen auf dem Holz mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Wenn es eine ganze Gemeine in Israel versehen würde, und die Tat vor ihren Augen verborgen ware, daß sie irgend wider ein Gebot des HERRN getan flatten, das sie nicht tun sollten, und sich also verschuldeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'und danach ihrer Sünde inne würden, die sie getan flatten: sollen sie einen jungen Farren darbringen zum Sündopfer und vor die Tür der Hutte des Stifts stellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Und die Altesten von der Gemeine sollen ihre Hande auf sein Haupt legen vor dem HERRN und den Farren schlachten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Und der Priester, der gesalbet ist, soil des Bluts vom Farren in die Hütte des Stifts bringen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'und mit seinem Finger drein tunken und siebenmal sprengen vor dem HERRN, vor dem Vorhang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Und soil des Bluts auf die Horner des Altars tun, der vor dem HERRN stehet in der Hütte des Stifts, und alles andere Blut an den Boden des Brandopferaltars gießen, der vor der Tür der Hütte des Stifts stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Alles sein Fett aber soil er heben und auf dem Altar anzünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Und soil mit dem Farren tun, wie er mit dem Farren des Sundopfers getan hat. Und soil also der Priester sie versohnen, so wird\'s ihnen vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Und soil den Farren außer dem Lager führen und verbrennen wie er den vorigen Farren verbrannt hat. Das soil das Sündopfer der Gemeine sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Wenn aber ein Fürst sündiget und irgend wider des HERRN, seines Gottes, Gebot tut, das er nicht tun sollte, und versiehet es, daß er sich verschuldet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'und wird seiner Sünde inne, die er getan hat: der soil zum Opfer bringen einen Ziegenbock ohne Wandel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'und seine Hand auf des Bocks Haupt legen und ihn schlachten an der Statte, da man die Brandopfer schlachtet vor dem HERRN. Das sei ein Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Da soil denn der Priester des Bluts von dem Sündopfer nehmen mit seinem Finger und auf die Horner des Brandopferaltars tun und das andere Blut an den Boden des Brandopferaltars gießen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Aber alles sein Fett soil er auf dem Altar anzünden, gleichwie das Fett des Dankopfers. Und soil also der Priester seine Sünde versohnen, so wird\'s ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Wenn es aber eine See Lev vom gemeinen Volk versiehet und sündiget, daß sie irgend wider der Gebote des HERRN eines tut, das sie nicht tun sollte, und sich also verschuldet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'und ihrer Sünde inne wird, die sie getan hat: die soil zum Opfer eine Ziege bringen ohne Wandel für die Sünde, die sie getan hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'und soil ihre Hand auf des Sündopfers Haupt legen und schlachten an der Statte des Brandopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Und der Priester soil des Bluts mit seinem Finger nehmen und auf die Horner des Altars des Brandopfers tun und alles Blut an des Altars Boden gießen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'All sein Fett aber soil er abreißen, wie er das Fett des Dankopfers abgerissen hat, und soil\'s anzünden auf dem Altar zum süßen Geruch dem HERRN. Und soil also der Priester sie versohnen, so wird\'s ihr vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Wird er aber ein Schaf zum Sündopfer bringen, so bringe er, das eine Sie ist, ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'und lege seine Hand auf des Sündopfers Haupt und schlachte es zum Sündopfer an der Statte, da man die Brandopfer schlachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Und der Priester soil des Bluts mit seinem Finger nehmen und auf die Horner des Brandopferaltars tun und alles Blut an den Boden des Altars gießen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Aber all sein Fett soil er abreißen, wie er das Fett vom Schaf des Dankopfers abgerissen hat, und soil\'s auf dem Altar anzünden zum Feuer dem HERRN. Und soil also der Priester versohnen seine Sünde, die er getan hat, so wird\'s ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Wenn eine See Lev sundigen wurde, daß er einen Fluch horet, und er des Zeuge ist, Oder gesehen Oder erfahren hat und nicht angesagt, der ist einer Missetat schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Oder wenn eine See Lev etwas Unreines anruhret, es sei ein Aas eines unreinen Tieres Oder Viehes Oder Gewurmes, und wußte es nicht, der ist unrein und hat sich verschuldet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Oder wenn ereinen unreinen Menschen anruhret, in waserlei Unreinigkeit der Mensch unrein werden kann, und wufite es nicht, und wird\'s inne, der hat sich verschuldet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Oder wenn eine See Lev schworet, dafi ihm aus dem Munde entfahret, Schaden Oder Gutes zu tun (wie denn einem Menschen ein Schwur entfahren mag, ehe er\'s bedacht), und wird\'s inne, der hat sich an der einem verschuldet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Wenn es nun geschiehet, daß er sich der eines verschuldet und erkennet sich, dafi er daran gesundigt hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'so soil er fur seine Schuld dieser seiner Sunde, die ergetan hat, dem HERRN bringen von der Herde eine Schaf- Oder Ziegenmutter zum Sundopfer; so soil ihm der Priester seine Sunde versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Vermag er aber nicht ein Schaf, so bringe er dem HERRN fur seine Schuld, die er getan hat, zwo Turteltauben Oder zwo junge Tauben, die erste zum Sundopfer, die andere zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Und bringe sie dem Priester. Der soil die erste zum Sundopfer machen und ihr den Kopf abkneipen hinterdem Genick, und nicht abbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Und sprenge mit dem Blut des Sundopfers an die Seite des Altars und lasse das übrige Blut ausbluten an des Altars Boden. Das ist das Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Die andere aber soil er zum Brandopfer machen nach seinem Recht. Und soil also der Priester ihm seine Sunde versohnen, die er getan hat; so wird\'s ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Vermag er aber nicht zwo Turteltauben Oder zwo junge Tauben, so bringe er fur seine Sunde sein Opfer, einen zehnten Teil Epha Semmelmehl zum Sundopfer. Er soli aber kein 01 drauf legen noch Weihrauch drauf tun: denn es ist ein Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Und soil\'s zum Priester bringen. Der Priester aber soil eine Handvoll davon nehmen zum Gedachtnis und anzunden auf dem Altar zum Feuer dem HERRN. Das ist ein Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Und der Priester soil also seine Sunde, die er getan hat, ihm versohnen, so wird\'s ihm vergeben. Und soil des Priesters sein, wie ein Speisopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn sich eine See Lev vergreift, daß sie es versiehet, und sich versundiget an dem, das dem HERRN geweihet ist, soil sie ihr Schuldopfer dem HERRN bringen, einen Widder ohne Wandel von der Herde, der zween Sekel Silbers wert sei nach dem Sekel des Heiligtums, zum Schuldopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Dazu, was er gesundiget hat an dem Geweiheten, soil erwiedergeben und das funfte Teil daruber geben, und soil\'s dem Priester geben; der soil ihn versohnen mit dem Widder des Schuldopfers, so wird\'s ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Wenn eine See Lev sundiget und tut wider irgend ein Gebot des HERRN, das sie nicht tun sollte, und hat es nicht gewußt, die hat sich verschuldet und ist einer Missetat schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Und soil bringen einen Widder von der Herde ohne Wandel, der eines Schuldopfers wert ist, zum Priester; der soil ihm seine Unwissenheit versohnen, die er getan hat und wußte es nicht; so wird\'s ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Das ist das Schuldopfer, das erdem HERRN verfallen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 20, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 21, 'Wenn eine See Lev sundigen würde und sich an dem HERRN vergreifen, daß er seinem Nebenmenschen verleugnet, was er ihm befohlen hat, Oder das ihm zu treuer Hand getan ist, Oder das er mit Gewalt genommen, Oder mit Unrecht zu sich gebracht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 22, 'Oder, das verloren ist, funden hat, und leugnet solches mit einem falschen Eide, wie es der eines ist, darin ein Mensch wider seinen Nachsten Sunde tut:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 23, 'wenn\'s nun geschiehet, daß eralso sundiget und sich verschuldet, soli er wiedergeben, was er mit Gewalt genommen, Oder mit Unrecht zu sich gebracht, Oder was ihm befohlen ist, Oder was er funden hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 24, 'Oder worüberer den falschen Eid getan hat; das soil er alles ganz wiedergeben, dazu das funfte Teil druber geben dem, des es gewesen ist, des Tages, wenn er sein Schuldopfer gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 25, 'Aber fur seine Schuld soil er dem HERRN zu dem Priester einen Widder von der Herde ohne Wandel bringen, der eines Schuldopfers wert ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 26, 'So soil ihn der Priester versohnen vor dem HERRN; so wird ihm vergeben alles, was er getan hat, daran er sich verschuldet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Gebeut Aaron und seinen Sohnen und sprich: Dies ist das Gesetz des Brandopfers. Das Brandopfer soil brennen auf dem Altar die ganze Nacht bis an den Morgen. Es soil aber allein des Altars Feuer drauf brennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Und der Priester soil seinen leinenen Rock anziehen und die leinene Niederwand an seinen Leib; und soil die Asche aufheben, die das Feuer des Brandopfers auf dem Altar gemacht hat, und soli sie neben den Altar schutten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Und soli seine Kleider danach ausziehen und andere Kleider anziehen und die Asche hinaustragen aulier dem Lager an eine reine Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Das Feuer auf dem Altar soil brennen und nimmer verloschen; der Priester soil da al Lev Morgen Holz drauf anzunden und oben drauf das Brandopfer zurichten und das Fett der Dankopfer drauf anzunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Ewig soil das Feuer auf dem Altar brennen und nimmer verloschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Und das ist das Gesetz des Speisopfers, das Aarons Sohne opfern sollen vor dem HERRN auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Es soil einer heben seine Hand voll Semmelmehls vom Speisopfer und des Oles und den ganzen Weihrauch, der auf dem Speisopfer liegt und soil\'s anzunden auf dem Altar zum sülien Geruch, ein Gedachtnis dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Das übrige aber sollen Aaron und seine Sohne verzehren; und sollen es ungesauert essen an heiliger Statte, im Vorhof der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Sie sollen es nicht mit Sauerteig backen; denn es ist ihr Teil, das ich ihnen gegeben habe von meinem Opfer. Es soli ihnen das Allerheiligste sein, gleich wie das Sundopfer und Schuldopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Was mannlich ist unter den Kindern Aarons, sollen es essen. Das sei ein ewiges Recht euren Nachkommen an den Opfern des HERRN: Es soil sie niemand anruhren, er sei denn geweihet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Das soli das Opfer sein Aarons und seiner Sohne, das sie dem HERRN opfern sollen am Tage seiner Salbung: das zehnte Teil Epha vom Semmelmehl des taglichen Speisopfers, eine Halfte des Morgens, die andere Halfte des Abends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'In der Pfanne mit 01 sollstdu es machen und gerostet darbringen; und in Stricken gebacken sollst du solches opfern zum stiffen Geruch dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Und der Priester, der unter seinen Sohnen an seiner Statt gesalbet wird, soil solches tun. Das ist ein ewiges Recht dem HERRN; es soil ganz verbrannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Denn alles Speisopfer eines Priesters soli ganz verbrannt und nicht gegessen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Sage Aaron und seinen Sohnen und sprich: Dies ist das Gesetz des Sundopfers: An der Statte, da du das Brandopfer schlachtest, sollst du auch das Sundopfer schlachten vor dem HERRN; das ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der das Sundopfer tut, soil\'s essen an heiliger Statte, im Vorhof der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Niemand soli seines Fleisches anruhren, er sei denn geweihet. Und wer von seinem Blut ein Kleid besprenget, der soil das besprengte Stuck waschen an heiliger Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Und den Topf, darin es gekocht ist, soil man zerbrechen. Ist\'s aber ein eherner Topf, so soil man ihn scheuern und mit Wasser spülen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Was mannlich ist unter den Priestern, sollen davon essen; denn es ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Aber all das Sundopfer, des Blut in die Hutte des Stiffs gebracht wird, zu versohnen im Heiligen, soil man nicht essen, sondern mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies ist das Gesetz des Schuldopfers; und das ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'An der Statte, da man das Brandopfer schlachtet, soil man auch das Schuldopfer schlachten und seines Bluts auf den Altar umhersprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Und all sein Fett soil man opfern, den Schwanz und das Fett am Eingeweide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'die zwo Nieren mit dem Fett, das dran ist, an den Lenden, und das Netz uber der Leber, an den Nieren abgerissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester soil\'s auf dem Altar anzunden zum Feuer dem HERRN. Das ist ein Schuldopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Was mannlich ist unter den Priestern, sollen das essen an heiliger Statte; denn es ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie das Sundopfer, also soil auch das Schuldopfer sein; aller beider soil einerlei Gesetz sein; und soil des Priesters sein, der dadurch versohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Welcher Priester jemandes Brandopfer opfert, des soil desselben Brandopfers Fell sein, das er geopfert hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Und alles Speisopfer, das im Ofen Oder auf dem Rost Oder in der Pfanne gebacken ist, soil des Priesters sein, der es opfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Und alles Speisopfer, das mit Ol gemenget Oder trocken ist, soil aller Aarons Kinder sein, eines wie des andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und dies ist das Gesetz des Dankopfers, das man dem HERRN opfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wollen sie ein Lobopfertun, so sollen sie ungesauerte Kuchen opfern, mit Ol gemenget, und ungesauerte Fladen, mit Ol bestrichen, und gerostete Semmelkuchen, mit Ol gemenget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Sie sollen aber solches Opfer tun auf einem Kuchen von gesauertem Brot zum Lobopfer seines Dankopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und soil einen von den alien dem HERRN zur Hebe opfern; und soil des Priesters sein, der das Blut des Dankopfers sprenget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Und das Fleisch des Lobopfers in seinem Dankopfer soil desselben Tages gegessen werden, da es geopfert ist, und nichts übergelassen werden bis an den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Und es sei ein Gelubde Oder freiwillig Opfer, so soil es desselben Tages, da es geopfert ist, gegessen werden; so aber etwas überbleibet auf den andern Tag, soil man\'s doch essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Aber was von geopfertem Fleisch überbleibet am dritten Tag, soil mit Feuer verbrannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Und wo jemand am dritten Tage wird essen von dem geopferten Fleisch seines Dankopfers, so wird der nicht angenehm sein, der es geopfert hat; es wird ihm auch nicht zugerechnet werden, sondern es wird ein Greuel sein; und welche See Lev davon essen wird, die ist einer Missetat schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Und das Fleisch, das etwas Unreines anruhret, soil nicht gegessen, sondern mit Feuer verbrannt werden. Wer reines Leibes ist, soil des Fleisches essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Und welche See Lev essen wird von dem Fleisch des Dankopfers, das dem HERRN zugehoret, derselben Unreinigkeit sei auf ihr, und sie wird ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Und wenn eine See Lev etwas Unreines anruhret, es sei ein unreiner Mensch, Vieh, Oder was sonst greulich ist, und vom Fleisch des Dankopfers isset, das dem HERRN zugehoret, die wird ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Rede mit den Kindern Israel und sprich: Ihrsollt kein Fett essen von Ochsen, Lammern und Ziegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Aber das Fett vom Aas, und was vom Wild zerrissen ist, macht euch zu allerlei Nutz aber essen sollt ihr\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn wer das Fett isset vom Vieh, das dem HERRN zum Opfer gegeben ist, dieselbe See Lev soli ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ihr sollt auch kein Blut essen, weder vom Vieh noch von Vogeln, wo ihr wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Welche See Lev wurde irgend ein Blut essen, die soli ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Rede mit den Kindern Israel und sprich: Wer dem HERRN sein Dankopfer tun will, der soil auch mitbringen, was zum Dankopfer dem HERRN gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Er soli\'s aber mit seiner Hand herzubringen zum Opfer des HERRN; namlich das Fett an der Brust soil er bringen samt der Brust, daß sie eine Webe werden vordem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Und der Priester soli das Fett anzunden auf dem Altar; und die Brust soli Aarons und seiner Sohne sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Und die rechte Schulter sollen sie dem Priester geben zur Hebe von ihren Dankopfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Und welcher unter Aarons Sohnen das Blut der Dankopfer opfert und das Fett, des soil die rechte Schulter sein zu seinem Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn die Webebrust und die Hebeschulter habe ich genommen von den Kindern Israel von ihren Dankopfern und habe sie dem Priester Aaron und seinen Sohnen gegeben zum ewigen Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dies ist die Salbung Aarons und seiner Sohne von den Opfern des HERRN des Tages, da sie überantwortetwurden, Priester zu sein dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'da der HERR gebot am Tage, da er sie salbete, daß ihm gegeben werden sollte von den Kindern Israel zum ewigen Recht alien ihren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Und dies ist das Gesetz des Brandopfers, des Speisopfers, des Sundopfers, des Schuldopfers, der Fullopfer und der Dankopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'das der HERR Mose gebot auf dem Berge Sinai des Tages, da er ihm gebot an die Kinder Israel, zu opfern ihre Opfer dem HERRN in der Wuste Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aaron und seine Söhne mit ihm samt ihren Kleidern und das Salbol und einen Farren zum Sundopfer, zween Widder und einen Korb mit ungesauertem Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Und versamm Lev die ganze Gemeine vordie Tur der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Mose tat, wie ihm der HERR gebot, und versammelte die Gemeine vor die Tur der Hutte des Stifts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'und sprach zu ihnen: Das ist\'s, das der HERR geboten hat zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Und nahm Aaron und seine Sohne und wusch sie mit Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Und legte ihm den leinenen Rock an und gurtete ihn mit dem Gurtel und zog ihm den Seidenrock an und tat ihm den Leibrock an und gurtete ihn uber den Leibrock her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Und tat ihm das Schildlein an und in das Schildlein Licht und Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Und setzte ihm den Hut auf sein Haupt und setzte an den Hut, oben an seiner Stirn, das guldene Blatt der heiligen Krone, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Und Mose nahm das Salbol und salbete die Wohnung und alles, was drinnen war, und weihete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Und sprengete damit siebenmal auf den Altar und salbete den Altar mit al Lev seinem Gerate, das Handfaft mit seinem Fuli, daß es geweihet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Und goft des Salboles auf Aarons Haupt und salbete ihn, daß er geweihet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Und brachte herzu Aarons Sohne und zog ihnen leinene Rocke an und gurtete sie mit dem Gurtel und band ihnen Hauben auf, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Und lieft herzufuhren einen Farren zum Sundopfer. Und Aaron mit seinen Sohnen legten ihre Hande auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Da schlachtete man es. Und Mose nahm des Bluts und tat\'s auf die Horner des Altars umher mit seinem Finger und entsundigte den Altar; und goft das Blut an des Altars Boden und weihete ihn, daß er ihn versohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Und nahm alles Fett am Eingeweide, das Netz uber der Leber und die zwo Nieren mit dem Fett daran und zundete es an auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Aber den Farren mit seinem Fell, Fleisch und Mist verbrannte er mit Feuer aufter dem Lager, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Und brachte herzu einen Widder zum Brandopfer. Und Aaron mit seinen Sohnen legten ihre Hande auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Da schlachtete man ihn. Und Mose sprengete des Bluts auf den Altar umher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'zerhieb den Widder in Stucke und zundete an das Haupt, die Stucke und den Stumpf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Und wusch die Eingeweide und Schenkel mit Wasser und zundete also den ganzen Widder an auf dem Altar. Das war ein Brandopfer zum sußen Geruch, ein Feuer dem HERRN, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Er brachte auch herzu den andern Widder des Fullopfers. Und Aaron mit seinen Sohnen legten ihre Hande auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Da schlachtete man ihn. Und Mose nahm seines Bluts und tat\'s Aaron auf den Knorpel seines rechten Ohrs und auf den Daumen seiner rechten Hand und auf den grolien Zehen seines rechten Fui Jes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Und brachte herzu Aarons Sohne; und tat des Bluts auf den Knorpel ihres rechten Ohrs und auf den Daumen ihrer rechten Hand und auf den grofien Zehen ihres rechten Fußes; und sprengete das Blut auf den Altar umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Und nahm das Fett und den Schwanz und alles Fett am Eingeweide und das Netz fiber der Leber, die zwo Nieren mit dem Fett daran und die rechte Schulter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Dazu nahm er von dem Korbe des ungesauerten Brots vordem HERRN einen ungesauerten Kuchen und einen Kuchen geolten Brots und einen Fladen; und legte es auf das Fett und auf die rechte Schulter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Und gab das allesamt auf die Hande Aarons und seiner Sohne und webete es zur Webe vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Und nahm\'s alles wieder von ihren Handen und zundete es an auf dem Altar, oben auf dem Brandopfer; denn es ist ein Fullopfer zum sülien Geruch, ein Feuer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Und Mose nahm die Brust und webete eine Webe vor dem HERRN von dem Widder des Fullopfers. Die ward Mose zu einem Teil, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Und Mose nahm des Salboles und des Bluts auf dem Altar und sprengete auf Aaron und seine Kleider, auf seine Sohne und auf ihre Kleider; und weihete also Aaron und seine Kleider, seine Sohne und ihre Kleider mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Und sprach zu Aaron und seinen Sohnen: Kochet das Fleisch vor der Tür der Hütte des Stiffs und esset es daselbst, dazu, auch das Brot im Korbe des Fullopfers, wie mir geboten ist und gesagt, daß Aaron und seine Sohne sollen\'s essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Was aber überbleibt vom Fleisch und Brot, das sollt ihr mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Und sollt in sieben Tagen nicht ausgehen von der Tür der Hutte des Stiffs bis an den Tag, da die Tage eures Fullopfers aus sind; denn sieben Tage sind eure Hande gefüllet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'wie es an diesem Tage geschehen ist. Der HERR hat\'s geboten zu tun, auf daß ihr versohnet seiet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Und sollt vor der Tür der Hütte des Stiffs Tag und Nacht bleiben, sieben Tage lang, und sollt auf die Hut des HERRN warten, daß ihr nicht sterbet; denn also ist mir\'s geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Und Aaron mit seinen Sohnen taten alles, was der HERR geboten hatte durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Und am achten Tage rief Mose Aaron und seinen Sohnen und den Altesten in Israel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'und sprach zu Aaron: Nimm zu dir ein jung Kalb zum Sündopfer und einen Widder zum Brandopfer, beide ohne Wandel, und bringe sie vor den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Und rede mit den Kindern Israel und sprich: Nehmet einen Ziegenbock zum Sundopfer und ein Kalb und ein Schaf, beide eines Jahrs alt und ohne Wandel, zum Brandopfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'und einen Ochsen und einen Widder zum Dankopfer, daß wir vor dem HERRN opfern; und ein Speisopfer, mit 01 gemenget. Denn heute wird euch der HERR erscheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Und sie nahmen, was Mose geboten hatte, vor der Tür der Hütte des Stiffs. Und trat herzu die ganze Gemeine und stund vordem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Da sprach Mose: Das ist\'s, das der HERR geboten hat, daß ihr tun sollt, so wird euch des HERRN Herrlichkeit erscheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Und Mose sprach zu Aaron: Tritt zum Altar und mache dein Sundopfer und dein Brandopfer und versohne dich und das Volk; danach mache des Volks Opfer und versohne sie auch, wie der HERR geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Und Aaron trat zum Altar und schlachtete das Kalb zu seinem Sündopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Und seine Sohne brachten das Blutzu ihm; und er tunkte mit seinem Finger ins Blut und tat\'s auf die Horner des Altars und goli das Blut an des Altars Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Aber das Fett und die Nieren und das Netz von der Leber am Sündopfer zündete er an auf dem Altar, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Und das Fleisch und das Fell verbrannte er mit Feuer aulierdem Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Danach schlachtete er das Brandopfer; und Aarons Sohne brachten das Blut zu ihm, und er sprengete es auf den Altar umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Und sie brachten das Brandopfer zu ihm zerstücket, und den Kopf; und er zündete es an auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Und er wusch das Eingeweide und die Schenkel und zündete es an oben auf dem Brandopfer, auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Danach brachte er herzu des Volks Opfer; und nahm den Bock, das Sündopfer des Volks, und schlachtete ihn und machte ein Sündopfer draus, wie das vorige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Und brachte das Brandopfer herzu und tat ihm sein Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Und brachte herzu das Speisopfer und nahm seine Hand voll und zundete es an auf dem Altar, aufter des Morgens Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Danach schlachtete erden Ochsen und Widder zum Dankopfer des Volks. Und seine Sohne brachten ihm das Blut; das sprengete er auf den Altar umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Aber das Fett vom Ochsen und vom Widder, den Schwanz und das Fett am Eingeweide und die Nieren und das Netz uber der Leber,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'alles solches Fett legten sie auf die Brust; und er zundete das Fett an auf dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Aber die Brust und die rechte Schulter webete Aaron zur Webe vor dem HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Und Aaron hub seine Hand auf zum Volk und segnete sie; und stieg herab, da er das Sundopfer, Brandopfer und Dankopfer gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Und Mose und Aaron gingen in die Hütte des Stiffs; und da sie wieder herausgingen, segneten sie das Volk. Da erschien die Herrlichkeit des HERRN allem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Denn das Feuer kam aus von dem HERRN und verzehrete auf dem Altar das Brandopfer und das Fett. Da das alles Volk sah, frohlockten sie und fielen auf ihr Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Und die Sohne Aarons, Nadab und Abihu, nahmen ein jeglicher seinen Napf und taten Feuer drein und legten Rauchwerk drauf und brachten das fremde Feuer vor den HERRN, das er ihnen nicht geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da fuhr ein Feuer aus von dem HERRN und verzehrete sie, daß sie starben vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sprach Mose zu Aaron: Das ist\'s, das der HERR gesagt hat: Ich werde geheiliget werden an denen, die zu mir nahen, und vor allem Volk werde ich herrlich werden. Und Aaron schwieg stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mose aber rief Misael und Elzaphan, den Sohnen Usiels, Aarons Vettern, und sprach zu ihnen: Tretet hinzu und traget eure Bruder von dem Heiligtum hinausvordas Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Und sie traten hinzu und trugen sie hinaus mit ihren leinenen Rocken vor das Lager, wie Mose gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Da sprach Mose zu Aaron und seinen Sohnen, Eleazar und Ithamar: Ihr sollt eure Haupter nicht bidden, noch eure Kleider zerreiften, dad ihr nicht sterbet, und der Zorn uber die ganze Gemeine komme. Lasset eure Bruder des ganzen Hauses Israel weinen fiber diesen Brand, den der HERR getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ihr aber sollt nicht ausgehen von der Tür der Hütte des Stifts; ihr mochtet sterben. Denn das Salbol des HERRN ist auf euch. Und sie taten, wie Mose sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Der HERR aber redete mit Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Du und deine Sohne mit dir, sollt keinen Wein noch stark Getranke trinken, wenn ihr in die Hütte des Stifts gehet, auf dad ihr nicht sterbet. Das sei ein ewiges Recht alien euren Nachkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'auf dad ihr konnet unterscheiden, was heilig und unheilig, was unrein und rein ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'und dad ihr die Kinder Israel lehret al Lev Rechte, die der HERR zu euch geredet hat durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose redete mit Aaron und mit seinen übrigen Sohnen, Eleazar und Ithamar: Nehmet, das überblieben ist vom Speisopfer an den Opfern des HERRN und esset es ungesauert bei dem Altar; denn es ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Ihr sollt es aber an heiliger Statte essen; denn das ist dein Recht und deiner Sohne Recht an den Opfern des HERRN; denn so ist mir\'s geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Aber die Webebrust und die Hebeschulter sollst du und deine Sohne und deine Tochter mit dir essen an reiner Statte; denn solch Recht ist dir und deinen Kindern gegeben an den Dankopfern der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Denn die Hebeschulter und die Webebrust zu den Opfern des Fettes werden gebracht, daß sie zur Webe gewebet werden vor dem HERRN: darum ist\'s dein und deiner Kinder zum ewigen Recht, wie der HERR geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Und Mose suchte den Bock des Sundopfers und fand ihn verbrannt. Und er ward zomig fiber Eleazar und Ithamar, Aarons Sohne, die noch übrig waren, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr das Sundopfer nicht gegessen an heiliger Statte? denn es das Allerheiligste ist, und er hat\'s euch gegeben, daß ihr die Missetat der Gemeine tragen sollt, daß ihr sie versohnet vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Siehe, sein Blut ist nicht kommen in das Heilige hinein. Ihr solltet es im Heiligen gegessen haben, wie mir geboten ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Aaron aber sprach zu Mose: Siehe, heute haben sie ihr Sundopfer und ihr Brandopfer vor dem HERRN geopfert, und es ist mir also gegangen, wie du siehest; und ich sollte essen heute vom Sundopfer? Sollte das dem HERRN gefallen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Da das Mose horete, lieft er\'s ihm gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Und der HERR redete mit Mose und Aaron und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Redet mit den Kindern Israel und sprechet: Das sind die Tiere, die ihr essen sollt unter alien Tieren auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alles, was die Klauen spaltet und wiederkauet unter den Tieren, das sollt ihr essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Was aber wiederkauet und hat Klauen und spaltet sie doch nicht, als das Kamel, das ist euch unrein, und sollt es nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Die Kaninchen wiederkauen wohl, aber sie spalten die Klauen nicht; darum sind sie unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Der Hase wiederkauet auch, aber er spaltet die Klauen nicht; darum ist er euch unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Und ein Schwein spaltet wohl die Klauen, aber es wiederkauet nicht; darum soil es euch unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Von diesem Fleisch sollt ihr nicht essen, noch ihr Aas anruhren; denn sie sind euch unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Dies sollt ihr essen unter dem, das in Wassern ist: Alles, was Floßfedern und Schuppen hat in Wassern, im Meer und Bachen, sollt ihr essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Alles aber, was nicht Floßfedern und Schuppen hat im Meer und Bachen, unter allem, das sich reget in Wassern, und allem, was lebet im Wasser, soil euch eine Scheu sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'daß ihr von ihrem Fleisch nicht esset und vor ihrem Aas euch scheuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Denn alles, was nicht Flol Jfedern und Schuppen hat in Wassern, sollt ihr scheuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Und dies sollt ihr scheuen unter den Vogeln, daß ihr\'s nicht esset: den Adler, den FHabicht, den Fischaar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'den Geier, den Weihe und was seiner Art ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'und al Lev Raben mit ihrer Art,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'den Strauß, die Nachteule, den Kuckuck, den Sperber mit seiner Art,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'das Kauzlein, den Schwan, den Huhu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'die Fledermaus, die Rohrdommel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'den Storch, den Reiher, den FHeher mit seiner Art, den Wiedehopf und die Schwalbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alles auch, was sich reget unter den Vogeln und gehet auf vier Füßen, das soil euch eine Scheu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Doch das sollt ihr essen von Vogeln, das sich reget und gehet auf vier Fußen und nicht mitzweien Beinen auf Erden hupfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Von denselben moget ihr essen, als da ist: Arbe mit seiner Art und Selaam mit seiner Art und FHargol mit seiner Art und Hagab mit ihrer Art.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Alles aber, was sonst vier Fuße hat unter den Vogeln, soli euch eine Scheu sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'und sollt sie unrein achten. Wer solcher Aas anruhret, der wird unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Und wer dieser Aas eines tragen wird, der soil seine Kleider waschen und wird unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Darum alles Tier, das Klauen hat und spaltet sie nicht und wiederkauet nicht, das soil euch unrein sein; wer es anruhret, wird unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Und alles, was auf T appen gehet unter den Tieren, die auf vier Fülien gehen, soil euch unrein sein; wer ihr Aas anruhret, wird unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Und wer ihr Aas tragt, soil seine Kleider waschen und unrein sein bis auf den Abend; denn solche sind euch unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Diese sollen euch auch unrein sein unter den Tieren, die auf Erden kriechen: das Wiesel, die Maus, die Krote, ein jegliches mit seiner Art;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'der Igel, der Molch, die Eidechse, die Blindschleiche und der Maulwurf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Die sind euch unrein unter allem, das da kreucht wer ihr Aas anruhret, der wird unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Und alles, worauf ein solch tot Aas fallt, das wird unrein, es sei allerlei holzern Gefali, Oder Kleider, Oder Fell, Oder Sack; und alles Gerate, damit man etwas schaffet, soli man ins Wasser tun, und ist unrein bis auf den Abend; alsdann wird\'s rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Allerlei irden Gefaft, wo solcher Aas eines drein fallt, wird alles unrein, was drinnen ist; und sollt es zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Al Lev Speise, die man isset, so solches Wasser drein kommt, ist unrein; und aller Trank, den man trinket, in allerlei solchem Gefaß, ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Und alles, worauf ein solch Aas fallt, wird unrein, es sei Ofen Oder Kessel, so soli man\'s zerbrechen; denn es ist unrein, und soil euch unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Doch die Brunnen und Koike und Teiche sind rein. Wer aber ihr Aas anruhret, ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Und ob ein solch Aas fie Lev auf Samen, den man gesat hat, so ist er doch rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Wenn man aber Wasser über den Samen gosse, und fie Lev danach ein solch Aas darauf, so würde ereuch unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Wenn ein Tier stirbt, das ihr essen moget: wer das Aas anruhret, der ist unrein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Wer von solchem Aas isset, der soil sein Kleid waschen und wird unrein sein bis an den Abend. Also wer auch tragt ein solch Aas, soli sein Kleid waschen und wird unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Was auf Erden schleicht, das soil euch eine Scheu sein, und man soil\'s nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Und alles, was auf dem Bauch kreucht, und alles, was auf vier Oder mehr Fülien gehet, unter allem, das auf Erden schleicht, sollt ihr nicht essen; denn es soil euch eine Scheu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Machet eure See Lev nicht zum Scheusal und verunreiniget euch nicht an ihnen, daü ihr euch besudelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn ich bin der HERR, euer Gott. Darum sollt ihr euch heiligen, daß ihr heilig seid, denn ich bin heilig; und sollt nicht eure See Lev verunreinigen an irgend einem kriechenden Tier, das auf Erden schleicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn ich bin der HERR, der euch aus Agyptenland gefuhret hat, daß ich euer Gott sei. Darum sollt ihr heilig sein, denn ich bin heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dies ist das Gesetz von den Tieren und Vogeln und allerlei kriechenden Tieren im Wasser und allerlei Tieren, die auf Erden schleichen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'daß ihr unterscheiden konntet, was unrein und rein ist, und welches Tier man essen und welches man nicht essen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Rede mit den Kindern Israel und sprich: Wenn ein Weib besamet wird und gebiert ein Knablein, so soil sie sieben Tage unrein sein, solange sie ihre Krankheit leidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Und am achten Tage soli man das Fleisch seiner Vorhaut beschneiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Und sie soil daheim bleiben dreiunddreiftig Tage im Blut ihrer Reinigung. Kein Heiliges soli sie anruhren und zum Heiligtum soil sie nicht kommen, bis daß die Tage ihrer Reinigung aus sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Gebiert sie aber ein Magdlein, so soil sie zwo Wochen unrein sein, solange sie ihre Krankheit leidet, und soil sechsundsechzig Tage daheim bleiben in dem Blut ihrer Reinigung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Und wenn die Tage ihrer Reinigung aus sind fur den Sohn Oder fur die Tochter, soli sie ein jahrig Lamm bringen zum Brandopfer und eine junge Taube Oder Turteltaube zum Sundopfer dem Priester vor die Türder Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Der soil es opfern vor dem HERRN und sie versohnen; so wird sie rein von ihrem Biutgang. Das ist das Gesetz fur die, so ein Knablein Oder Magdlein gebiert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Vermag aber ihre Hand nicht ein Schaf, so nehme sie zwo Turteltauben Oder zwo junge Tauben, eine zum Brandopfer, die andere zum Sundopfer; so soil sie der Priester versohnen, daß sie rein werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Wenn einem Menschen an der Haut seines Fleisches etwas auffahret, Oder schabicht Oder eiterweift wird, als wollte ein Aussatz werden an der Haut seines Fleisches, soil man ihn zum Priester Aaron führen Oder zu seiner Sohne einem unter den Priestern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Und wenn der Priester das Mai an der Haut des Fleisches siehet, dafi die Haare in Weiß, verwandelt sind, und das Ansehen an dem Ort tiefer ist denn die andere Haut seines Fleisches, so ist\'s gewift der Aussatz. Darum soli ihn der Priester besehen und fur unrein urteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Wenn aber etwas eiterweiß ist an der Haut seines Fleisches, und doch das Ansehen nicht tiefer denn die andere Haut des Fleisches, und die Haare nicht in Weift verwandelt sind, so soil der Priester denselben verschließen sieben Tage');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'und am siebenten Tage besehen. Ist\'s, daß das Mai bleibt, wie er\'s zuvor gesehen hat, und hat nicht weiter gefressen an der Haut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'so soil ihn der Priester abermal sieben Tage verschlieften. Und wenn er ihn zum andernmal am siebenten Tage besiehet und findet, daß das Mai verschwunden ist und nicht weiter gefressen hat an der Haut, so soil er ihn rein urteilen, denn es ist Grind. Und er soil seine Kleider waschen, so ist er rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Wenn aber der Grind weiter frißt in der Haut, nachdem er vom Priester besehen und rein gesprochen ist, und wird nun zum andernmal vom Priester besehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'wenn denn da der Priester siehet, daß der Grind weiter gefressen hat in der Haut, soil er ihn unrein urteilen, denn es ist gewift Aussatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Wenn ein Mai des Aussatzes am Menschen sein wird, den soil man zum Priester bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Wenn derselbe siehet und findet, daß weift aufgefahren ist an der Haut, und die Haare in Weift verwandelt, und roh Fleisch im Geschwur ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'so ist\'s gewift ein alter Aussatz in der Haut seines Fleisches. Darum soil ihn der Priester unrein urteilen und nicht verschlieften; denn er ist schon unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Wenn aber der Aussatz bluhet in der Haut und bedeckt die ganze Haut, von dem Haupt an bis auf die Fufte, alles, was dem Priester vor Augen sein mag;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'wenn dann der Priester besiehet und findet, daß der Aussatz das ganze Fleisch bedeckt hat, so soil er denselben rein urteilen, dieweil es alles an ihm in Weift verwandelt ist; denn er ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Ist aber roh Fleisch da des Tages, wenn er besehen wird, so ist er unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und wenn der Priester das rohe Fleisch besiehet, soil er ihn unrein urteilen; denn er ist unrein, und es ist gewift Aussatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Verkehret sich aber das rohe Fleisch wieder und verwandelt sich in Weift, so soil er zum Priester kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Und wenn der Priester besiehet und findet, daß das Mai ist in Weift verwandelt, soil er ihn rein urteilen, denn er ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Wenn in jemandes Fleisch an der Haut eine Druse wird, und wieder heilet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'danach an demselben Ort etwas weift auffahret Oder rotlich Eiterweift wird, soil er vom Priester besehen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Wenn dann der Priester siehet, daß das Ansehen tiefer ist denn die andere Haut und das Haar in Weift verwandelt; so soil er ihn unrein urteilen; denn es ist gewift ein Aussatzmal aus der Druse worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Siehet aber der Priester und findet, daß die Haare nicht weift sind, und ist nicht tiefer denn die andere Haut, und ist verschwunden, so soli er ihn sieben Tage verschlieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Friftt es weiter in der Haut, so soil er ihn unrein urteilen; denn es ist gewift ein Aussatzmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Bleibt aber das Eiterweift also stehen und friftt nicht weiter, so ist\'s die Narbe von der Druse, und der Priester soil ihn rein urteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Wenn sich jemand an der Haut am Feuer brennet, und das Brandmal rotlich Oder weift, ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'und der Priester ihn besiehet und findet das Haar in Weili verwandelt an dem Brandmal und das Ansehen tiefer denn die andere Haut, so ist gewili Aussatz aus dem Brandmal worden. Darum soil ihn der Priester unrein urteilen; denn es ist ein Aussatzmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Siehet aber der Priester und findet, daß die Haare am Brandmal nicht in Weili verwandelt, und nicht tiefer ist denn die andere Haut, und ist dazu verschwunden, soil er ihn sieben Tage verschliefien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Und am siebenten Tage soil er ihn besehen. Hat\'s weiter gefressen an der Haut, so soil er ihn unrein urteilen; denn es ist Aussatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Ist\'s aber gestanden an dem Brandmal und nicht weiter gefressen an der Haut und ist dazu verschwunden, so ist\'s ein Geschwur des Brandmals. Und der Priester soil ihn rein urteilen; denn es ist eine Narbe des Brandmals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Wenn ein Mann Oder Weib auf dem Haupt Oder am Bart schabicht wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'und der Priester das Mai besiehet und findet, daß das Ansehen tiefer ist denn die andere Haut, und das Haar daselbst gulden und dünne, so soil er ihn unrein urteilen; denn es ist aussatziger Grind des Haupts Oder des Barts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Siehet aber der Priester, daß der Grind nicht tiefer anzusehen ist denn die Haut, und das Haar nicht falb ist, soil er denselben sieben Tage verschliefien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Und wenn er am siebenten Tage besiehet und findet, daß der Grind nicht weiter gefressen hat, und kein gulden Haar da ist, und das Ansehen des Grindes nicht tiefer ist denn die andere Haut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'soli er sich bescheren, doch daß er den Grind nicht beschere. Und soil ihn der Priester abermal sieben Tage verschliefien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Und wenn er ihn am siebenten Tage besiehet und findet, daß der Grind nicht weiter gefressen hat in der Haut, und das Ansehen ist nicht tiefer denn die andere Haut, so soil ihn der Priester rein sprechen; und er soil seine Kleider waschen, denn er ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Frilit aber der Grind weiter an der Haut, nachdem er rein gesprochen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'und der Priester besiehet und findet, daß der Grind also weiter gefressen hat an der Haut, so soli er nicht mehr danach fragen, ob die Haare gulden sind; denn er ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ist aber vor Augen der Grind still gestanden, und falb Haar daselbst aufgegangen, so ist der Grind heil und er rein. Darum soil ihn der Priester rein sprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Wenn einem Mann Oder Weib an der Haut ihres Fleisches etwas eiterweifi ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'und der Priester siehet daselbst, dafi das Eiterweili schwindet, das ist ein weifier Grind, in der Haut aufgegangen, und er ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Wenn einem Manne die Haupthaare ausfallen, daß er kahl wird, der ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Fallen sie ihm vorne am Haupt aus, und wird eine Glatze, so ist er rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Wird aber an der Glatze, Oder da er kahl ist, ein weili Oder rotlich Mai, so ist ihm Aussatz an der Glatze Oder am Kahlkopf aufgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Darum soli ihn der Priester besehen. Und wenn er findet, daß ein weili Oder rotlich Mai aufgelaufen an seiner Glatze Oder Kahlkopf, daß es siehet, wie sonst der Aussatz an der Haut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'so ist er aussatzig und unrein; und der Priester soil ihn unrein sprechen solches Mals halben auf seinem Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Wer nun aussatzig ist, des Kleider sollen zerrissen sein und das Haupt bloli und die Lippen verhullet und soli allerdinge unrein genannt werden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Und solange das Mai an ihm ist, soil er unrein sein, alleine wohnen, und seine Wohnung soil aulier dem Lager sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Wenn an einem Kleide eines Aussatzes Mai sein wird, es sei wollen Oder leinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'am Werft Oder am Eintracht, es sei leinen Oder wollen, Oder an einem Fell, Oder an allem, das aus Fellen gemachtwird;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'und wenn das Mai bleich Oder rotlich ist am Kleid, Oder am Fell, Oder am Werft, Oder am Eintracht, Oder an einigerlei Ding, das von Fellen gemacht ist: das ist gewili ein Mai des Aussatzes; darum soil\'s der Priester besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und wenn er das Mai siehet, soil er\'s einschlielien sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Und wenn er am siebenten Tage siehet, daß das Mai hat weiter gefressen am Kleid, am Werft Oder am Eintracht, am Fell Oder an allem, das man aus Fellen macht, so ist\'s ein fressend Mai des Aussatzes und ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Und soli das Kleid verbrennen, Oder den Werft, Oder den Eintracht, es sei wollen Oder leinen, Oder allerlei Fellwerk, darin solch Mai ist; denn es ist ein Mai des Aussatzes; und soil es mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Wird aber der Priester sehen, daß das Mai nicht weiter gefressen hat am Kleid, Oder am Werft, Oder am Eintracht, Oder an allerlei Fellwerk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'so soil ergebieten, daß man\'s wasche, darin das Mai ist; und soli es einschlielien andere sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Und wenn der Priester sehen wird, nachdem das Mai gewaschen ist, daß das Mai nicht verwandelt ist vor seinen Augen und auch nicht weiter gefressen hat, so ist\'s unrein, und sollst es mit Feuer verbrennen; denn es ist tief eingefressen und hat es beschabt gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Wenn aber der Priester siehet, daß das Mai verschwunden ist nach seinem Waschen, so soil er\'s abreilien vom Kleid, vom Fell, vom Werft Oder vom Eintracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Wird\'s aber noch gesehen am Kleid, am Werft, am Eintracht Oder allerlei Fellwerk, so ist\'s ein Fleck, und sollst es mit Feuer verbrennen, darin solch Mai ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Das Kleid aber, Oder Werft, Oder Eintracht, Oder allerlei Fellwerk, das gewaschen ist und das Mai von ihm gelassen hat, soli man zum andernmal waschen, so ist\'s rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Das ist das Gesetz uber die Ma Lev des Aussatzes an Kleidern, sie seien wollen Oder leinen, am Werft und am Eintracht und an allerlei Fellwerk, rein Oder unrein zu sprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Das ist das Gesetz uber den Aussatzigen, wenn er soil gereinigt werden. Er soil zum Priester kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'und der Priester soil aus dem Lager gehen und besehen, wie das Mai des Aussatzes am Aussatzigen heil worden ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'und soil gebieten dem, der zu reinigen ist, daß er zween lebendige Vogel nehme, die da rein sind, und Zedernholz und rosinfarbene Wol Lev und Ysop.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Und soil gebieten, den einen Vogel zu schlachten in einem irdenen Gefaß am fliefienden Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Und soil den lebendigen Vogel nehmen mit dem Zedernholz, rosinfarbener Wol Lev und Ysop und in des geschlachteten Vogels Blut tunken am fliefienden Wasser');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'und besprengen den, der vom Aussatz zu reinigen ist, siebenmal; und reinige ihn also und lasse den lebendigen Vogel ins freie Feld fliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Der Gereinigte aber soli seine Kleider waschen und al Lev seine Haare abscheren und sich mit Wasser baden, so ist er rein. Danach gehe er ins Lager; doch soli er außer seiner Hütte sieben Tage bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Und am siebenten Tage soil er al Lev seine Haare abscheren auf dem Haupt, am Barte, an den Augenbrauen, daß al Lev Haare abgeschoren seien, und soil seine Kleider waschen und sein Fleisch im Wasser baden, so ist er rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Und am achten Tage soil erzwei Lammer nehmen ohne Wandel und ein jahrig Schaf ohne Wandel und drei Zehnten Semmelmehl zum Speisopfer, mit 01 gemenget, und ein Log Ols.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Da soil der Priester denselben Gereinigten und diese Dinge stellen vor den HERRN vor der Tur der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Und soli das eine Lamm nehmen und zum Schuldopfer opfern mit dem Log 01; und soil solches vor dem HERRN weben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'und danach das Lamm schlachten, da man das Sundopfer und Brandopfer schlachtet, namlich an heiliger Statte; denn wie das Sundopfer, also ist auch das Schuldopfer des Priesters; denn es ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Und der Priester soil des Bluts nehmen vom Schuldopfer und dem Gereinigten auf den Knorpel des rechten Ohrs tun und auf den Daumen seiner rechten Hand und auf den großen Zehen seines rechten Fußes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Danach soli erdes Ols aus dem Log nehmen und in seine (des Priesters) linke Hand gießen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'und mit seinem rechten Finger in das 01 tunken, das in seiner linken Hand ist, und sprengen mit seinem Finger das 01 siebenmal vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Das übrige 01 aber in seiner Hand soil er dem Gereinigten auf den Knorpel des rechten Ohrs tun und auf den rechten Daumen und auf den großen Zehen seines rechten Fußes, oben auf das Blut des Schuldopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Das übrige 01 aber in seiner Hand soil er auf des Gereinigten Haupt tun und ihn versohnen vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Und soil das Sundopfer machen und den Gereinigten versohnen seiner Unreinigkeit halben; und soil danach das Brandopfer schlachten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'und soil es auf dem Altar opfern samt dem Speisopfer und ihn versohnen, so ist er rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ist er aber arm und mit seiner Hand nicht so viel erwirbt, so nehme er ein Lamm zum Schuldopfer zu weben, ihn zu versohnen, und einen Zehnten Semmelmehl, mit 01 gemenget, zum Speisopfer und ein Log 01');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'und zwo Turteltauben oderzwo junge Tauben, die er mit seiner Hand erwerben kann, daß eine sei ein Sundopfer, die andere ein Brandopfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'und bringe sie am achten Tage seiner Reinigung zum Priester vor der Tur der Hütte des Stifts, vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Da soli der Priester das Lamm zum Schuldopfer nehmen und das Log 01 und soil\'s alles weben vor dem HERRN;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'und das Lamm des Schuldopfers schlachten und des Bluts nehmen von demselben Schuldopfer und dem Gereinigten tun auf den Knorpel seines rechten Ohrs und auf den Daumen seiner rechten Hand und auf den großen Zehen seines rechten Fußes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'und des Ols in seine (des Priesters) linke Hand gießen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'und mit seinem rechten Finger das 01, das in seiner linken Hand ist, siebenmal sprengen vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Des ubrigen aber in seiner Hand soil er dem Gereinigten auf den Knorpel seines rechten Ohrs und auf den Daumen seiner rechten Hand und auf den großen Zehen seines rechten Fußes tun, oben auf das Blut des Schuldopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Das ubrige 01 aber in seiner Hand soli er dem Gereinigten auf das Haupt tun, ihn zu versohnen vor dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'und danach aus der einen Turteltaube Oder jungen Taube, wie seine Hand hat mogen erwerben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'ein Sundopfer, aus derandern ein Brandopfer machen samt dem Speisopfer. Und soil der Priester den Gereinigten also versohnen vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Das sei das Gesetz fur den Aussatzigen, der mit seiner Hand nicht erwerben kann, was zu seiner Reinigung gehort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihrins Land Kanaan kommt, das ich euch zur Besitzung gebe, und werde irgend in einem Hause eurer Besitzung ein Aussatzmal geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'so soil der kommen, des das Haus ist, dem Priester ansagen und sprechen: Es siehet mich an, als sei ein Aussatzmal an meinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Da soli der Priester heißen, daß sie das Haus ausraumen, ehe denn der Priester hineingehet, das Mai zu besehen, auf dafi nicht unrein werde alles, was im Hause ist; danach soil der Priester hineingehen, das Haus zu besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Wenn er nun das Mai besiehet und findet, daß an der Wand des Hauses gelbe Oder rotliche Grublein sind und ihr Ansehen tiefer, denn sonst die Wand ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'so soil er zum Hause zur Tur herausgehen und das Haus sieben Tage verschliefien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Und wenn eram siebenten Tage wiederkommt und siehet, daß das Mai weiter gefressen hat an des Hauses Wand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'so soil er die Steine heißen ausbrechen, darin das Mai ist, und hinaus vor die Stadt an einen unreinen Ort werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Und das Haus soil man inwendig ringsherum schaben, und soli den abgeschabten Leimen hinaus vor die Stadt an einen unreinen Ort schutten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'und andere Steine nehmen und an jener Statt tun und andern Leimen nehmen und das Haus bewerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn dann das Mai wiederkommt und ausbricht am Hause, nachdem man die Steine ausgerissen und das Haus anders beworfen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'so soil der Priester hineingehen. Und wenn er siehet, daß das Mai weiter gefressen hat am Hause, so ist\'s gewiß ein fressender Aussatz am Hause und ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Darum soil man das Haus abbrechen, Stein und Holz, und alien Leimen am Hause, und soil\'s hinausfuhren vor die Stadt an einen unreinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus gehet, solange es verschlossen ist, der ist unrein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Und wer drinnen liegt Oder drinnen isset, der soil seine Kleiderwaschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Wo aber der Priester, wenn er hineingehet, siehet, daß dies Mai nicht weiter am Hause gefressen hat, nachdem das Haus beworfen ist, so soil efs reinsprechen, denn das Mai ist heil worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Und soil zum Sundopfer fur das Haus nehmen zween Vogel, Zedernholz und rosinfarbne Wol Lev und Ysop');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'und den einen Vogel schlachten in einem irdenen Gefaß an einem fließenden Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Und soil nehmen das Zedernholz, die rosinfarbne Wolle, den Ysop und den lebendigen Vogel und in des geschlachteten Vogels Blut tunken an dem fließenden Wasser und das Haus siebenmal besprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Und soil also das Haus entsundigen mit dem Biut des Vogels und mit fließendem Wasser, mit dem lebendigen Vogel, mit dem Zedernholz, mit Ysop und mit rosinfarbner Wolle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Und soil den lebendigen Vogel lassen hinaus vor die Stadt ins freie Feld fliegen und das Haus versohnen, so ist\'s rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Das ist das Gesetz uber allerlei Mai des Aussatzes und Grindes:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'uber den Aussatz der Kleider und der Hauser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'uber die Beulen, Gnatze und Eiterweiß,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'auf daß man wisse, wenn etwas unrein Oder rein ist. Das ist das Gesetz vom Aussatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet mit den Kindern Israel und sprecht zu ihnen: Wenn ein Mann an seinem Fieisch einen Fluß hat, derselbe ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Dann aber ist er unrein an diesem Fluß, wenn sein Fieisch vom Fluß eitert Oder verstopft ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Alles Lager, darauf er liegt, und alles, daraufer sitzet, wird unrein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Und wer sein Lager anruhret; der soil seine Kleiderwaschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Und wer sich setzt, da er gesessen hat, der soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Wer sein Fieisch anruhret, der soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Wenn er seinen Speichel wirft auf den der rein ist, der soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Und der Sattel, darauf er reitet, wird unrein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Und wer anruhret irgend etwas, das er unter sich gehabt hat, der wird unrein sein bis auf den Abend. Und wer solches tragt, der soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und welchen er anruhret, ehe er die Hande waschet, der soli seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Wenn erein irden Gefaß anruhret, das soil man zerbrechen; aber das holzerne Gefaß soil man mit Wasser spulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Und wenn er rein wird von seinem Fluß, so soil er sieben Tage zahlen, nach dem er rein worden ist, und seine Kleider waschen und sein Fieisch mit fließendem Wasser baden, so ist er rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Und am achten Tage soli erzwo Turteltauben Oder zwo junge Tauben nehmen und vor den HERRN bringen vor der Tur der Hutte des Stiffs und dem Priester geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Und der Priester soil aus einer ein Sundopfer, aus derandern ein Brandopfer machen und ihn versohnen vor dem HERRN seines Flusses halben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Wenn einem Mann im Schlaf der Same entgehet, der soil sein ganzes Fleisch mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und das Kleid und alles Fell, das mitsolchem Samen beflecket ist, soil erwaschen mit Wasser und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Ein Weib, bei welchem ein solcher liegt, die soil sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Wenn ein Weib ihres Leibes Blutfluß hat, die soil sieben Tage beiseit getan werden; wer sie anruhret, der wird unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Und alles, worauf sie liegt, solange sie ihre Zeit hat, wird unrein sein; und worauf sie sitzt, wird unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und wer ihr Lager anruhret, der soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und wer anruhret irgendwas, darauf sie gesessen hat, soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Und wer etwas anruhret, das auf ihrem Lager, Oder wo sie gesessen, gelegen Oder gestanden, soil unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn ein Mann bei ihr liegt, und es kommt sie ihre Zeit an bei ihm; der wird sieben Tage unrein sein, und das Lager, darauf er gelegen ist, wird unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Wenn aber ein Weib ihren Blutfluß eine lange Zeit hat, nicht allein zur gewohnlichen Zeit, sondern auch fiber die gewohnliche Zeit, so wird sie unrein sein, solange sie fleußt; wie zur Zeit ihrer Absonderung, so soli sie auch hie unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Alles Lager, darauf sie liegt, die ganze Zeit ihres Flusses, soil sein wie das Lager ihrer Absonderung. Und alles, worauf sie sitzt, wird unrein sein, gieich der Unreinigkeit ihrer Absonderung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Wer der etwas anruhret, der wird unrein sein und soil seine Kleider waschen und sich mit Wasser baden und unrein sein bis auf den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Wird sie aber rein von ihrem Fluß, so soil sie sieben Tage zahlen; danach soil sie rein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage soil sie zwo Turteltauben oderzwo junge Tauben nehmen und zum Priester bringen vor die Tur der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Und der Priester soil aus einer machen ein Sundopfer, aus derandern ein Brandopfer und sie versohnen vor dem HERRN über dem Fluß ihrer Unreinigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'So sollt ihr die Kinder Israel warnen vor ihrer Unreinigkeit, daß sie nicht sterben in ihrer Unreinigkeit, wenn sie meine Wohnung verunreinigen, die unter euch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Das ist das Gesetz uber den, der einen Fluß hat, und dem der Same im Schlaf entgehet, daß er unrein davon wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'und fiber die, die ihren Blutfluß hat, und wer einen Fluß hat, es sei Mann Oder Weib, und wenn ein Mann bei einer Unreinen liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und der HERR redete mit Mose (nachdem die zween Sohne Aarons gestorben waren, da sie vor dem HERRN opferten)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'und sprach: Sage deinem Bruder Aaron, daß er nicht allerlei Zeit in das inwendige Heiligtum gehe hinter dem Vorhang vor dem Gnadenstuhl, der auf der Lade ist, daß er nicht sterbe; denn ich will in einer Wolke erscheinen auf dem Gnadenstuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Sondern damit soil er hineingehen: mit einem jungen Farren zum Sundopfer und mit einem Widder zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Und soil den heiligen leinenen Rock anlegen und ieinen Niederwand an seinem Fleisch haben und sich mit einem leinenen Gurtel gürten und den leinenen Hut aufhaben; denn das sind die heiligen Kleider; und soil sein Fleisch mit Wasser baden und sie anlegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Und soil von der Gemeine der Kinder Israel zween Ziegenbocke nehmen zum Sundopfer und einen Widder zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Und Aaron soil den Farren, sein Sundopfer, herzubringen und sich und sein Haus versohnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'und danach die zween Bocke nehmen und vor den HERRN stellen vor der Tur der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Und soil das Los werfen fiber die zween Bocke, ein Los dem HERRN und das andere dem ledigen Bock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Und soil den Bock, auf welchen des HERRN Los fallt, opfern zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Aber den Bock, auf welchen das Los des ledigen fallt, soil er lebendig vor den HERRN stellen, daß er ihn versohne, und lasse den ledigen Bock in die Wfiste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Und also soil er denn den Farren seines Sundopfers herzubringen und sich und sein Haus versohnen; und soli ihn schlachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Und soil einen Napf voll Glut vom Altar nehmen, der vor dem HERRN stehet, und die Hand voll zerstoßenes Rauchwerks und hinein hinter den Vorhang bringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'und das Rauchwerk aufs Feuer tun vor dem HERRN, daß der Nebel vom Rauchwerk den Gnadenstuhl bedecke, der auf dem Zeugnis ist, daß er nicht sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Und soil des Bluts vom Farren nehmen und mit seinem Finger gegen den Gnadenstuhl sprengen vorne an; siebenmal soil eralso vor dem Gnadenstuhl mit seinem Finger vom Blut sprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Danach soil erden Bock, des Volks Sundopfer, schlachten und seines Bluts hineinbringen hinter den Vorhang; und soil mit seinem Blut tun, wie er mit des Farren Blut getan hat, und damit auch sprengen vorne gegen den Gnadenstuhl;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'und soil also versohnen das Heiligtum von der Unreinigkeit der Kinder Israel und von ihrer Obertretung in alien ihren Sünden. Also soil er tun der Hutte des Stitts; denn sie sind unrein, die umher liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Kein Mensch soil in der Hutte des Stitts sein, wenn er hineingehet, zu versohnen im Heiligtum, bis er herausgehe; und soil also versohnen sich und sein Haus und die ganze Gemeine Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Und wenn er herausgehet zum Altar, der vor dem HERRN stehet, soil er ihn versohnen und soil des Bluts vom Farren und des Bluts vom Bock nehmen und auf des Altars Horner umher tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Und soil mit seinem Finger vom Blut darauf sprengen siebenmal und ihn reinigen und heiligen von der Unreinigkeit der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Und wenn er vollbracht hat das Versohnen des Heiligtums und der Hutte des Stitts und des Altars, so soil er den lebendigen Bock herzubringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Da soil denn Aaron seine beiden Hande auf sein Haupt legen und bekennen auf ihn al Lev Missetat der Kinder Israel und al Lev ihre Ubertretung in alien ihren Sunden; und soli sie dem Bock auf das Haupt legen und ihn durch einen Mann, dervorhanden ist, in die Wuste laufen lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'daß also der Bock al Lev ihre Missetat auf ihm in eine Wildnis trage; und lasse ihn in die Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Und Aaron soil in die Hutte des Stitts gehen und ausziehen die leinenen Kleider, die er anzog, da er in das Heiligtum ging, und soil sie daselbst lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Und soil sein Fleisch mit Wasser baden an heiliger Statte und seine eigenen Kleider antun; und herausgehen und sein Brandopfer und des Volks Brandopfer machen und beide sich und das Volk versohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'und das Fett vom Sündopfer auf dem Altar anzünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Der aber den ledigen Bock hat ausgeführet, soil seine Kleider waschen und sein Fleisch mit Wasser baden und danach ins Lager kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Den Farren des Sundopfers und den Bock des Sundopfers, welcher Blut in das Heiligtum zu versohnen gebracht wird, soil man hinausführen vor das Lager und mit Feuer verbrennen, beide ihre Haut, Fleisch und Mist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der sie verbrennet, soil seine Kleider waschen und sein Fleisch mit Wasser baden und danach ins Lager kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Auch soil euch das ein ewiges Recht sein: Am zehnten Tage des siebenten Monden sollt ihr euren Leib kasteien und kein Werk tun, er sei einheimisch oderfremd unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage geschieht eure Versohnung, daß ihr gereiniget werdet; von alien euren Sunden werdet ihr gereiniget vor dem Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Darum soil\'s euch der grolite Sabbat sein, und ihr sollt euren Leib demutigen. Ein ewig Recht sei das!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Es soli aber solche Versohnung tun ein Priester, den man geweihet, und des Hand man gefüllet hat zum Priester an seines Vaters Statt; und soli die leinenen Kleider antun, namlich die heiligen Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Und soil also versohnen das heilige Heiligtum und die Hutte des Stifts und den Altar und die Priester und alles Volk der Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Das soil euch ein ewiges Recht sein, daß ihr die Kinder Israel versohnet von alien ihren Sunden im Jahr einmal Und Mose tat, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Sage Aaron und seinen Sohnen und alien Kindern Israel und sprich zu ihnen: Das ist\'s, das der HERR geboten hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Welcher aus dem Hause Israel einen Ochsen Oder Lamm Oder Ziege schlachtet in dem Lager Oder aulien vor dem Lager');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'und nicht vor die Tür der Hutte des Stifts bringet, daß es dem HERRN zum Opfer gebracht werde vor der Wohnung des HERRN, der soli des Bluts schuldig sein, als der Blut vergossen hat, und solcher Mensch soil ausgerottet werden aus seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Darum sollen die Kinder Israel ihre Opfer, die sie auf dem freien Felde opfern wollen, vor den HERRN bringen, vor die Türe der Hutte des Stifts, zum Priester, und allda ihre Dankopfer dem HERRN opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester soil das Blut auf den Altar des HERRN sprengen vor der Tür der Hutte des Stifts und das Fett anzünden zum sülien Geruch dem HERRN;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'und mitnichten ihre Opfer hinfort den Feldteufeln opfern, mit denen sie huren. Das soil ihnen ein ewiges Recht sein bei ihren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Darum sollstdu zu ihnen sagen: Welcher Mensch aus dem Hause Israel, Oder auch ein Fremdling, der unter euch ist, der ein Opfer Oder Brandopfer tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'und bringt\'s nicht vor die Tür der Hutte des Stifts, daß er\'s dem HERRN tue, der soil ausgerottet werden von seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und welcher Mensch, er sei vom Hause Israel, Oder ein Fremdling unter euch, irgend Blut isset, wider den will ich mein Antlitz setzen und will ihn mitten aus seinem Volk rotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn des Leibes Leben istim Blut, und ich hab\'s euch zum Altar gegeben, daß eure Seelen damit versohnet werden. Denn das Blut ist die Versohnung fur das Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Darum hab ich gesagt den Kindern Israel: Keine See Lev unter euch soil Blut essen, auch kein Fremdling, der unter euch wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und welcher Mensch, ersei vom Hause Israel Oder ein Fremdling unter euch, der ein Tier Oder Vogel fahet auf der Jagd, das man isset, der soil desselben Blut vergieden und mit Erde zuscharren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn des Leibes Leben ist in seinem Blut, solange es lebet; und ich habe den Kindern Israel gesagt: Ihr sollt keines Leibes Blut essen. Denn des Leibes Leben ist in seinem Blut. Wer es isset, der soil ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und welche See Levein Aas, Oder was vom Wilde zerrissen ist, isset, er sei ein Einheimischer Oder Fremdling, der soil sein Kleid waschen und sich mit Wasser baden und unrein sein bis auf den Abend, so wird errein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Wo er seine Kleider nicht waschen noch sich baden wird, so soil er seiner Missetat schuldig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ihr sollt nicht tun nach den Werken des Landes Agypten, darinnen ihr gewohnet habt, auch nicht nach den Werken des Landes Kanaan, darein ich euch führen will; ihr sollt auch euch nach ihrer Weise nicht halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Sondern nach einen Rechten sollt ihr tun und meine Satzungen sollt ihr halten, daü ihr darinnen wandelt; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Darum sollt ihr meine Satzungen halten und meine Rechte. Denn welcher Mensch dieselben tut, der wird dadurch leben; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Niemand soil sich zu seiner nachsten Blutsfreundin tun, ihre Scham zu bidden; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Du sollst deines Vaters und deiner Mutter Scham nicht bidden; es ist deine Mutter, darum sollst du ihre Scham nicht blofien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Du sollst deines Vaters Weibes Scham nicht blofien; denn es ist deines Vaters Scham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Du sollst deiner Schwester Scham, die deines Vaters Oder deiner Mutter Tochter ist, daheim Oder drauden geboren, nicht bidden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Du sollst deines Sohns Oder deiner Tochter Tochter Scham nicht bloüen; denn es ist deine Scham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Du sollst der Tochter deines Vaters Weibes, die deinem Vater geboren ist und deine Schwester ist, Scham nicht bidden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Du sollst deines Vaters Schwester Scham nicht blofien; denn es ist deines Vaters nachste Blutsfreundin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du sollst deiner Mutter Schwester Scham nicht blofien denn es ist deiner Mutter nachste Blutsfreundin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du sollst deines Vaters Bruders Scham nicht blofien, dafi du sein Weib nehmest; denn sie ist deine Base.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du sollst deiner Schnur Scham nicht bidden; denn es ist deines Sohns Weib, darum sollst du ihre Scham nicht blofien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du sollst deines Bruders Weibes Scham nicht bidden; denn sie ist deines Bruders Scham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du sollst deines Weibes samt ihrer Tochter Scham nicht blofien, noch ihres Sohns Tochter Oder Tochter Tochter nehmen, ihre Scham zu bidden; denn es ist ihre nachste Blutsfreundin, und ist ein Laster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du sollst auch deines Weibes Schwester nicht nehmen neben ihr, ihre Scham zu bidden, ihrzuwider, weil sie noch lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Du sollst nicht zum Weibe gehen, weil sie ihre Krankheit hat, in ihrer Unreinigkeit ihre Scham zu bidden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Du sollst auch nicht bei deines nachsten Weib liegen, sie zu besamen, damit du dich an ihr verunreinigest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du sollst auch deines Samens nicht geben, dad es dem Molech verbrannt werde, dad du nicht entheiligest den Namen deines Gottes; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Du sollst nicht bei Knaben liegen wie beim Weibe; denn es ist ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du sollst auch bei keinem Tier liegen, dad du mit ihm verunreiniget werdest. Und kein Weib soli mit einem Tier zu schaffen haben; denn es ist ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ihr sollt euch in dieser keinem verunreinigen; denn in diesem allem haben sich verunreiniget die Heiden, die ich voreuch her will ausstoden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'und das Land dadurch verunreiniget ist. Und ich will ihre Missetat an ihnen heimsuchen, dad das Land seine Einwohner ausspeie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Darum haltet meine Satzungen und Rechte und tut dieser Greuel keine, weder der Einheimische noch der Fremdling unter euch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'denn al Lev solche Greuel haben die Leute dieses Landes getan, die voreuch waren, und haben das Land verunreiniget;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'auf dad euch nicht auch das Land ausspeie, wenn ihr es verunreiniget, gleichwie es die Heiden hat ausgespeiet, die vor euch waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn welche diese Greuel tun, deren Seelen sollen ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Darum haltet meine Satzung, dad ihr nicht tut nach den greulichen Sitten, die vor euch waren, dad ihr nicht damit verunreiniget werdet; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede mit der ganzen Gemeine der Kinder Israel und sprich zu ihnen: Ihr sollt heilig sein; denn ich bin heilig, der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Ein jeglicher furchte seine Mutter und seinen Vater. Haltet meine Feiertage; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ihr sollt euch nicht zu den Gotzen wenden und sollteuch keine gegossenen Gotter machen; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und wenn ihr dem HERRN wollt Dankopfer tun, so sollt ihropfern, das ihm gefallen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Aber ihr sollt es desselben Tages essen, da ihr\'s opfert, und des andern Tages; was aber auf den dritten Tag uberbleibet, soil man mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Wird aberjemand am dritten Tage davon essen, so ist er ein Greuel und wird nicht angenehm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Und derselbe Esserwird seine Missetat tragen, daß er das Heiligtum des HERRN entheiligte, und solche See Lev wird ausgerottet werden von ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Wenn, du dein Land einerntest, sollstdu es nicht an den Enden umher abschneiden, auch nicht alles genau aufsammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Also auch sollst du deinen Weinberg nicht genau lesen noch die abgefallenen Beeren auflesen, sondern dem Armen und Fremdling sollst du es lassen; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen, noch lugen, noch falschlich handeln, einer mit dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ihr sollt nicht falsch schworen bei meinem Namen und entheiligen den Namen deines Gottes; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinem Nachsten nicht unrecht tun noch berauben. Es soil des Taglohners Lohn nicht bei dir bleiben bis an den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du sollst dem Tauben nicht fluchen. Du sollst vor dem Blinden keinen Anstoü setzen; denn du sollst dich vor deinem Gott furchten; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt nicht unrecht handeln am Gericht, und sollst nicht vorziehen den Geringen, noch den Grotien ehren, sondern du sollst deinen Nachsten recht richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du sollst kein Verleumder sein unter deinem Volk. Du sollst auch nicht stehen wider deines Nachsten Blut; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst deinen Bruder nicht hassen in deinem Herzen sondern du sollst deinen Nachsten strafen, auf daß du nicht seinethalben Schuld tragen müssest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst nicht rachgierig sein, noch Zorn halten gegen die Kinder deines Volks. Du sollst deinen Nachsten lieben wie dich selbst; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollt ihr halten, daß du dein Vieh nicht lassest mit anderlei Tier zu schaffen haben und dein Feld nicht besaest mit mancherlei Samen, und kein Kleid an dich komme, das mit Wol Lev und Leinen gemenget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Wenn ein Mann bei einem Weibe liegt und sie beschlaft, die eine leibeigene Magd und von dem Manne verschmahet ist, doch nicht erloset, noch Freiheit erlanget hat: das soil gestraft werden; aber sie sollen nicht sterben, denn sie ist nicht frei gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Ersoll aber fur seine Schuld dem HERRN vor die Tur der Hütte des Stiffs einen Widder zum Schuldopfer bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Und der Priester soil ihn versohnen mit dem Schuldopfer vor dem HERRN uber der Sünde, die er getan hat, so wird ihm Gott gnadig sein uber seine Sünde, die er getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Wenn ihr ins Land kommt und allerlei Baume pflanzet, davon man isset, sollt ihr derselben Vorhaut beschneiden und ihre Fruchte. Drei Jahre sollt ihr sie unbeschnitten achten, dati ihr nicht esset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Im vierten Jahr aber sollen al Lev ihre Fruchte heilig, und gepreiset sein dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Im funften Jahr aber sollt ihr die Fruchte essen und sie einsammeln; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr sollt nichts mit Blut essen. Ihr sollt nicht auf Vogelgeschrei achten noch Tage wahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt euer Haar am Haupt nicht rund umher abschneiden, noch euren Bart gar abscheren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ihr sollt kein Mai urn eines Toten willen an eurem Leibe reifien, noch Buchstaben an euch pfetzen; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du sollst deine Tochter nicht zur Hurerei halten, daß nicht das Land Hurerei treibe und werde voll Lasters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Feier haltet und furchteteuch vor meinem Heiligtum; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ihr sollteuch nicht wenden zu den Wahrsagern und forschet nicht von den Zeichendeutern, daß ihr nicht an ihnen verunreiniget werdet; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem grauen Haupt sollst du aufstehen und die Alten ehren; denn du sollst dich furchten vor deinem Gott; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Wenn ein Fremdling bei dir in eurem Lande wohnen wird, den sollt ihr nicht schinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Ersoll bei euch wohnen wie ein Einheimischer unter euch, und sollst ihn lieben wie dich selbst; denn ihrseid auch Fremdlinge gewesen in Agyptenland. Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ihr sollt nicht ungleich handeln am Gericht mit der Elle, mit Gewicht, mit Mali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Rechte Waage, rechte Pfunde, rechte Scheffel, rechte Kannen sollen bei euch sein; denn ich bin der HERR, euer Gott, der euch aus Agyptenland gefuhret hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'daß ihr al Lev meine Satzungen und al Lev meine Rechte haltet und tut; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Sage den Kindern Israel: Welcher unter den Kindern Israel Oder ein Fremdling, der in Israel wohnet, seines Samens dem Molech gibt, der soli des Todes sterben; das Volk im Lande soil ihn steinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und ich will mein Antlitz setzen wider solchen Menschen und will ihn aus seinem Volk rotten, daß er dem Molech seines Samens gegeben und mein Heiligtum verunreiniget und meinen heiligen Namen entheiliget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wo das Volk im Lande durch die Finger sehen wurde dem Menschen, der seines Samens dem Molech gegeben hat, daß es ihn nicht totet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'so will doch ich mein Antlitz wider denselben Menschen Setzen und wider sein Geschlecht; und will ihn und alle, die ihm nachgehuret haben mit dem Molech, aus ihrem Volk rotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Wenn eine See Lev sich zu den Wahrsagern und Zeichendeutern wenden wird, daß sie ihnen nachhuret, so will ich mein Antlitz wider dieselbe See Lev setzen und will sie aus ihrem Volk rotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Darum heiliget euch und seid heilig; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Und haltet meine Satzungen und tut sie; denn ich bin der HERR, der euch heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Wer seinem Vater Oder seiner Mutter fluchet, der soli des Todes sterben. Sein Blut sei auf ihm, daß er seinem Vater Oder Mutter gefluchet hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Wer die Ehe bricht mitjemandes Weibe, der soil des Todes sterben, beide Ehebrecher und Ehebrecherin, darum daß er mit seines Nachsten Weibe die Ehe gebrochen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Wenn jemand bei seines Vaters Weibe schlaft, daß er seines Vaters Scham gebloßet hat, die sollen beide des Todes sterben. Ihr Blut sei auf ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Wenn jemand bei seiner Schnur schlaft, so sollen sie beide des Todes sterben; denn sie haben eine Schande begangen. Ihr Blut sei auf ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Wenn jemand beim Knaben schlaft wie beim Weibe, die haben einen Greuel getan und sollen beide des Todes sterben. Ihr Blut sei auf ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Wenn jemand ein Weib nimmt und ihre Mutter dazu, der hat ein Laster verwirkt; man soil ihn mit Feuerverbrennen, und sie beide auch, dafi kein Laster sei unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Wenn jemand beim Vieh liegt, der soli des Todes sterben, und das Vieh soil man erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Wenn ein Weib sich irgend zu einem Vieh tut, daß sie mit ihm zu schaffen hat, die sollst du toten, und das Vieh auch; des Todes sollen sie sterben. Ihr Blut sei auf ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Wenn jemand seine Schwester nimmt, seines Vaters Tochter Oder seiner Mutter Tochter, und ihre Scham beschauet, und sie wieder seine Scham: das ist eine Blutschande; die sollen ausgerottet wer den vor den Leuten ihres Volks, denn er hat seiner Schwester Scham entbloliet. Er soil seine Missetat tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Wenn ein Mann beim Weibe schlaft zur Zeit ihrer Krankheit und entbloßet ihre Scham und decket ihren Brunnen auf, und sie entbloliet den Brunnen ihres Bluts, die sollen beide aus ihrem Volk gerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Deiner Mutter Schwester Scham und deines Vaters Schwester Scham sollst du nicht bloßen; denn ein solcher hat seine nachste Blutsfreundin aufgedecket, und sie sollen ihre Missetat tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Wenn jemand bei seines Vaters Bruders Weibe schlaft, der hat seines Vetters Scham gebloißet; sie sollen ihre Sünde tragen: ohne Kinder sollen sie sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Wenn jemand seines Bruders Weib nimmt, das ist eine schandliche Tat; sie sollen ohne Kinder sein, darum daß er hat seines Bruders Scham gebldliet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'So haltet nun al Lev meine Satzungen und meine Rechte und tut danach, auf daü euch nicht das Land ausspeie, darein ich euch fuhre, dafi ihr drinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Und wandelt nicht in den Satzungen der Heiden, die ich vor euch herwerde ausstoßen. Denn solches alles haben sie getan, und ich habe einen Greuel an ihnen gehabt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Euch aber sage ich: Ihr sollt jener Land besitzen; denn ich will euch ein Land zum Erbe geben, darin Milch und Honig fleuüt. Ich bin der HERR, euer Gott, der euch von den Volkern abgesondert hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'dafi ihr auch absondern sollt das reine Vieh vom unreinen und unreine Vogel von den reinen, und eure Seelen nicht verunreiniget am Vieh, an Vogeln und an allem, das auf Erden kreucht, das ich euch abgesondert habe, dafi es unrein sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Darum sollt ihr mir heilig sein; denn ich, der HERR, bin heilig, der euch abgesondert hat von den Volkern, dafi ihr mein waret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Wenn ein Mann Oder Weib ein Wahrsager Oder Zeichendeuter sein wird, die sollen des Todes sterben, man soil sie steinigen. Ihr Blut sei auf ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und der HERR sprach zu Mose: Sage den Priestern, Aarons Sohnen, und sprich zu ihnen: Ein Priester soil sich an keinem Toten seines Volks verunreinigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'ohne an seinem Blutsfreunde, der ihm am nachsten angehoret, als an seiner Mutter, an seinem Vater, an seinem Sohne, an seiner Tochter, an seinem Bruder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'und an seiner Schwester, die noch eine Jungfrau und noch bei ihm ist und keines Mannes Weib gewesen ist; an der mag ersich verunreinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Sonst soil ersich nicht verunreinigen an irgend einem, der ihm zugehoret unter seinem Volk, dafi er sich entheilige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen auch keine Platte machen auf ihrem Haupte, noch ihren Bart abscheren, und an ihrem Leibe kein Mai pfetzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein und nicht entheiligen den Namen ihres Gottes. Denn sie opfern des HERRN Opfer, das Brot ihres Gottes; darum sollen sie heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Sie sollen keine Hure nehmen, noch keine Geschwachte, Oder die von ihrem Manne verstoften ist; denn er ist heilig seinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Darum sollstdu ihn heilig halten, denn eropfert das Brot deines Gottes; er soil dir heilig sein, denn ich bin heilig, der HERR, der euch heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Wenn eines Priesters Tochter anfahet zu huren, die soli man mit Feuerverbrennen; denn sie hat ihren Vater geschandet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Welcher Hoherpriester ist unter seinen Brudern, auf des Haupt das Salbol gegossen und seine Hand gefullet ist, daß er angezogen würde mit den Kleidern, der soil sein Haupt nicht bloften und seine Kleider nicht zerschneiden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'und soil zu keinem Toten kommen und soil sich weder uber Vater noch uber Mutter verunreinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Aus dem Heiligtum soil er nicht gehen, daß er nicht entheilige das Heiligtum seines Gottes; denn die heilige Krone, das Salbol seines Gottes, ist auf ihm. Ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Eine Jungfrau soli erzum Weibe nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Aber keine Witwe noch Verstoftene, noch Geschwachte, noch Hure, sondern eine Jungfrau seines Volks soil er zum Weibe nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'auf daß er nicht seinen Samen entheilige unter seinem Volk; denn ich bin der HERR, der ihn heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede mit Aaron und sprich: Wenn an jemand deines Samens in euren Geschlechtern ein Fehl ist, der soli nicht herzutreten, daß er das Brot seines Gottes opfere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Denn keiner, an dem ein Fehl ist, soli herzutreten. Er sei blind, lahm, mit einer seltsamen Nase, mit ungewbhnlichem Gliede,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Oder der an einem Fuft Oder Hand gebrechlich ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Oder hockericht ist, Oder ein Fell auf dem Auge hat, Oder scheel ist, Oder grindicht, Oder schabicht, Oder der gebrochen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Welcher nun von Aarons, des Priesters Samen einen Fehl an ihm hat, der soil nicht herzutreten, zu opfern die Opfer des HERRN; denn er hat einen Fehl, darum soil er zu den Broten seines Gottes nicht nahen, daß ersie opfere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Doch soil er das Brot seines Gottes essen, beide von dem heiligen und vom allerheiligsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Aber doch zum Vorhang soil er nicht kommen, noch zum Altar nahen, weil der Fehl an ihm ist, daß er nicht entheilige mein Heiligtum; denn ich bin der HERR, der sie heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Mose redete solches zu Aaron und zu seinen Sohnen und zu alien Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Sage Aaron und seinen Sohnen, daß sie sich enthalten von dem Heiligen der Kinder Israel, welches sie mir heiligen, und meinen heiligen Namen nicht entheiligen; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'So sage nun ihnen auf ihre Nachkommen: Welcher eures Samens herzutritt zu dem Heiligen, das die Kinder Israel dem HERRN heiligen, und verunreiniget sich also uber demselben, des See Lev soli ausgerottet werden von meinem Antlitz; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Welcher des Samens Aarons aussatzig ist Oder einen Fluft hat, der soil nicht essen von dem Heiligen, bis er rein werde. Wer etwa einen unreinen Leib anruhret, Oder welchem der Same entgehet im Schlaf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'und welcher irgend ein Gewurm anruhret, das ihm unrein ist, Oder einen Menschen, der ihm unrein ist, und alles, was ihn verunreiniget:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'welche See Lev der eines anruhret, die ist unrein bis auf den Abend und soli von dem Heiligen nicht essen, sondern soil zuvor seinen Leib mit Wasserbaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Und wenn die Sonne untergegangen, und er rein worden ist, dann mag er davon essen; denn es ist seine Nahrung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ein Aas, und was von wilden Tieren zerrissen ist, soli er nicht essen, auf daß er nicht unrein daran werde denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Darum sollen sie meine Satze halten, daß sie nicht Sünde auf sich laden und daran sterben, wenn sie sich entheiligen; denn ich bin der HERR, der sie heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Kein anderer soil von dem Heiligen essen, noch des Priesters Hausgenoft, noch Taglohner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Wenn aber der Priester eine See Lev urn sein Geld kaufet, der mag davon essen; und was ihm in seinem Hause geboren wird, das mag auch von seinem Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Wenn aber des Priesters Tochter eines Fremden Weib wird, die soil nicht von der heiligen Hebe essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Wird sie aber eine Witwe, Oder ausgestoften, und hat keinen Samen und kommt wieder zu ihres Vaters Hause, so soil sie essen von ihres Vaters Brot, als da sie noch eine Magd war. Aber kein Fremdling soli davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Wer\'s versiehet und sonstvon dem Heiligen isset, der soli das fünfte Teil dazu tun und dem Priester geben samt dem Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'auf daß sie nicht entheiligen das Heilige der Kinder Israel, das sie dem HERRN heben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'auf daß sie sich nicht mit Missetat und Schuld beladen, wenn sie ihr Geheiligtes essen; denn ich bin der HERR, der sie heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Sage Aaron und seinen Sohnen und alien Kindern Israel: Welcher Israeliter Oder Fremdling in Israel sein Opfer tun will, es sei irgend ihr Gelubde Oder von freiem Willen, daß sie dem HERRN ein Brandopfer tun wollen, das ihm von euch angenehm sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'das soil ein Mannlein und ohne Wandel sein, von Rindern Oder Lammern oder Ziegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Alles, was einen Fehl hat, sollt ihr nicht opfern; denn es wird fur euch nicht angenehm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wer ein Dankopfer dem HERRN tun will, ein sonderlich Gelubde Oder von freiem Willen, von Rindern Oder Schafen, das soil ohne Wandel sein, daß es angenehm sei; es soil keinen Fehl haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ist\'s blind, Oder gebrechlich, Oder geschlagen, Oder durre, Oder raudicht, Oder schabicht, so sollt ihr solches dem FIERRN nicht opfern und davon kein Opfer geben auf den Altar des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Einen Ochsen Oder Schaf, das ungewohnliche Glieder Oder wandelbare Glieder hat, magst du von freiem Willen opfern; aber angenehm mag\'s nicht sein zum Gelubde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Du sollst auch dem HERRN kein Zerstoftenes, Oder Zerriebenes, Oder Zerrissenes, Oder das verwundet ist, opfern, und sollt in eurem Lande solches nicht tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Du sollst auch solcher keins von eines Fremdlings Hand neben dem Brot eures Gottes opfern; denn es taugt nicht und hat einen Fehl, darum wird es nicht angenehm sein fur euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Wenn ein Ochse, Oder Lamm, Oder Ziege geboren ist, so soil es sieben Tage bei seiner Mutter sein, und am achten Tage und danach mag man\'s dem HERRN opfern, so ist\'s angenehm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Es sei ein Ochse Oder Lamm, so soil man\'s nicht mit seinem Jungen auf einen Tag schlachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Wenn ihr aber wollt dem HERRN ein Lobopfer tun, das fur euch angenehm sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'so sollt ihr\'s desselben Tages essen und sollt nichts übrig bis auf den Morgen behalten; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Darum haltet meine Gebote und tut danach; denn ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Dafi ihrmeinen heiligen Namen nicht entheiliget, und ich geheiliget werde unter den Kindern Israel; denn ich bin der HERR, der euch heiliget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'der euch aus Agyptenland gefuhret hat, daß ich euer Gott ware, ich der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Sage den Kindern Israel und sprich zu ihnen: Dies sind die Feste des HERRN, die ihr heilig und meine Feste heilien sollt, da ihr zusammenkommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage sollst du arbeiten; der siebente Tag aber ist der grolie heilige Sabbat, da ihr zusammenkommt. Keine Arbeit sollt ihr drinnen tun; denn es ist der Sabbat des HERRN in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind aber die Feste des HERRN, die ihr heilige Feste heilien sollt, da ihr zusammenkommt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Am vierzehnten Tage des ersten Monden zwischen Abend, ist des HERRN Passah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Und am funfzehnten desselben Monden ist das Fest der ungesauerten Brote des HERRN; da sollt ihr sieben Tage ungesauert Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Der erste Tag soil heilig unter euch heilien, da ihr zusammenkommt; da sollt ihr keine Dienstarbeit tun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'und dem HERRN opfern sieben Tage. Der siebente Tag soli auch heilig heilien, da ihr zusammenkommt; da sollt ihr auch keine Dienstarbeit tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Sage den Kindern Israel und sprich zu ihnen: Wenn ihr ins Land kommt, das ich euch geben werde, und werdet es ernten, so sollt ihr eine Garbe der Erstlinge eurer Ernte zu dem Priester bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Da soli die Garbe gewebet werden vor dem HERRN, daß es von euch angenehm sei; solches soil aber der Priester tun des andern Tages nach dem Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Und sollt des Tages, da eure Garbe gewebet wird, ein Brandopfer dem HERRN tun von einem Lamm, das ohne Wandel und jahrig sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'samt dem Speisopfer, zwo Zehnten Semmelmehl mit 01 gemenget, zum Opfer dem HERRN eines süfien Geruchs; dazu das Trankopfer, ein Viertel Hin Weins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Und sollt kein neu Brot, noch Sangen, noch Korn zuvor essen, bis auf den Tag, da ihr eurem Gott Opfer bringet. Das soil ein Recht sein euren Nachkommen in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Danach sollt ihr zahlen vom andern Tage des Sabbats, da ihr die Webegarbe brachtet, sieben ganzer Sabbate;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'bis an den andern Tag des siebenten Sabbats, namlich funfzig Tage sollt ihr zahlen, und neu Speisopfer dem HERRN opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Und sollt es aus alien euren Wohnungen opfern, namlich zwei Webebrote von zwo Zehnten Semmelmehl, gesauert und gebacken, zu Erstlingen dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und sollt herzubringen neben eurem Brot sieben jahrige Lammer ohne Wandel und einen jungen Farren und zween Widder. Das soil des HERRN Brandopfer, Speisopfer und Trankopfer sein; das ist ein Opfer eines sülien Geruchs dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Dazu sollt ihr machen einen Ziegenbock zum Sundopfer und zwei jahrige Lammer zum Dankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Und der Priester soil\'s weben samt dem Brot der Erstlinge vor dem HERRN und den zweien Lammern; und soil dem HERRN heilig und des Priesters sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und sollt diesen Tag ausrufen, denn er soli unter euch heilig heilien, da ihr zusammenkommt; keine Dienstarbeit sollt ihr tun. Ein ewiges Recht soli das sein bei euren Nachkommen in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Wenn ihr aber euer Land erntet, sollt ihr\'s nicht gar auf dem Felde einschneiden, auch nicht alles genau auflesen, sondern sollt es den Armen und Fremdlingen lassen. Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede mit den Kindern Israel und sprich: Am ersten Tage des siebenten Monden sollt ihr den heiligen Sabbat des Blasens zum Gedachtnis halten, da ihrzusammenkommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Da sollt ihr keine Dienstarbeit tun und sollt dem HERRN opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Des zehnten Tages in diesem siebenten Monden istder Versohnetag. Der soli bei euch heilig heißen, daß ihr zusammen kommt; da sollt ihr euren Leib kasteien und dem HERRN opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Und sollt keine Arbeit tun an diesem Tage; denn es, ist der Versohnetag, dad ihr versohnet werdet vor dem HERRN, eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn wer seinen Leib nicht kasteiet an diesem Tage, der soil aus seinem Volk gerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Und wer dieses Tages irgend eine Arbeit tut, den will ich vertilgen aus seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Darum sollt ihr keine Arbeit tun. Das soil ein ewiges Recht sein euren Nachkommen in alien euren Wohnungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Es ist euer grader Sabbat, dad ihr eure Leiber kasteiet. Am neunten Tage des Monden, zu Abend, sollt ihr diesen Sabbat halten, von Abend an bis wiederzu Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede mit den Kindern Israel und sprich: Am funfzehnten Tage dieses siebenten Monden ist das Fest der Laubhutten sieben Tage dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Der erste Tag soli heilig heiden, dad ihr zusammenkommt; keine Dienstarbeit sollt ihr tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage sollt ihr dem HERRN opfern. Der achte Tag soli auch heilig heiden, dad ihr zusammenkommt, und sollt euer Opfer dem HERRN tun; denn es ist der Versammlungstag; keine Dienstarbeit sollt ihr tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Das sind die Feste des HERRN, die ihr sollt fur heilig halten, dad ihrzusammenkommt und dem HERRN Opfer tut, Brandopfer, Speisopfer, Trankopfer und andere Opfer, ein jegliches nach seinem Tage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'ohne was der Sabbat des HERRN und eure Gaben und Gelubde und freiwillige Gaben sind, die ihr dem HERRN gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'So sollt ihr nun am funfzehnten Tage des siebenten Monden, wenn ihr das Einkommen vom Lande eingebracht habt, das Fest des HERRN halten sieben Tage lang. Am ersten Tage ist es Sabbat, und am achten Tage ist es auch Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Und sollt am ersten Tage Fruchte nehmen von schonen Baumen, Palmenzweige und Maien von dichten Baumen und Bachweiden und sieben Tage frohlich sein vor dem HERRN, eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Und sollt also dem HERRN des Jahrs das Fest halten sieben Tage. Das soil ein ewiges Recht sein bei euren Nachkommen, daß sie im siebenten Monden also feiern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Sieben Tage sollt ihr in Laubhutten wohnen; wer einheimisch ist in Israel, der soli in Laubhutten wohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'daß eure Nachkommen wissen, wie ich die Kinder Israel habe lassen in Hutten wohnen, da ich sie aus Agyptenland führete. Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose sagte den Kindern Israel solche Feste des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Gebeut den Kindern Israel, daß sie zu dir bringen gestolien lauter Baumol zu Lichtern, das oben in die Lampen taglich getan werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'aufien vor dem Vorhang des Zeugnisses in der Hutte des Stiffs. Und Aaron soil\'s zurichten des Abends und des Morgens vor dem HERRN taglich. Das sei ein ewiges Recht euren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Er soil aber die Lampen auf dem feinen Leuchter zurichten vor dem HERRN taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Und sollst Semmelmehl nehmen und davon zwolf Kuchen backen; zwo Zehnten soli ein Kuchen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Und sollst sie legen je sechs auf eine Schicht auf den feinen Tisch vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Und sollst auf dieselben legen reinen Weihrauch, daß es seien Denkbrote zum Feuer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'AILev Sabbate fur und fur soli er sie zurichten vor dem HERRN, von den Kindern Israel, zum ewigen Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und sollen Aarons und seiner Sohne sein, die sollen sie essen an heiliger Statte; denn das ist sein Allerheiligstes von den Opfern des HERRN zum ewigen Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Es ging aber aus eines israelitischen Weibes Sohn, der eines agyptischen Mannes Kind war, unter den Kindern Israel und zankte sich im Lager mit einem israelitischen Manne');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'und lasterte den Namen und fluchte. Da brachten sie ihn zu Mose (seine Mutter aber hieli Selomith, eine Tochter Dibris, vom Stamm Dan)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'und legten ihn gefangen, bis ihnen klare Antwortwurde durch den Mund des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Führe den Flucher hinaus vor das Lager und lali alle, die es gehort haben, ihre Hande auf sein Haupt legen und lali ihn die ganze Gemeine steinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Und sage den Kindern Israel: Welcher seinem Gott fluchet, der soli seine Sunde tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Welcher des HERRN Namen lasted, der soil des Todes sterben; die ganze Gemeine soil ihn steinigen. Wie der Fremdling, so soil auch der Einheimische sein: wenn er den Namen lasted, so soil er sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Wer irgend einen Menschen erschlagt, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Wer aber ein Vieh erschlagt, der soil\'s bezahlen, Leib um Leib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Und wer seinen Nachsten verletzet, dem soil man tun wie er getan hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Schade um Schade, Auge um Auge, Zahn um Zahn; wie er hat einen Menschen verletzet, so soil man ihmwiedertun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Also daß, wer ein Vieh erschlagt, der soil\'s bezahlen; wer aber einen Menschen erschlagt, der soli sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Es soli einerlei Recht unter euch sein, dem Fremdling wie dem Einheimischen; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Mose aber sagte es den Kindern Israel; und fuhreten den Flucher aus vor das Lager und steinigten ihn. Also taten die Kinder Israel, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und der HERR redete mit Mose auf dem Berge Sinai und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr ins Land kommt, das ich euch geben werde, so soil das Land seine Feier dem HERRN feiern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'daß du sechs Jahre dein Feld besaest und sechs Jahre deinen Weinberg beschneidest und sammelst die Fruchte ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber im siebenten Jahr soil das Land seine grofte Feier dem HERRN feiern, darin du dein Feld nicht besaen noch deinen Weinberg beschneiden sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Was aber von ihm selber nach deiner Ernte wachst, sollst du nicht ernten, und die Trauben, so ohne deine Arbeit wachsen, sollst du nicht lesen, dieweil es ein Feierjahr ist des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Sondern die Feier des Landes sollt ihr darum halten, daß du davon essest, dein Knecht, deine Magd, dein Taglohner, dein Hausgenoft, dein Fremdling bei dir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'dein Vieh und die Tiere in deinem Lande. AILev Fruchte sollen Speise sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Und du sollst zahlen solcher Feierjahre sieben, daß sieben Jahre siebenmal gezahlet werden und die Zeit der sieben Feierjahre mache neunundvierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Da sollst du die Posaune lassen blasen durch all euer Land am zehnten Tage des siebenten Monden, eben am Tage der Versohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Und ihr sollt das funfzigste Jahr heiligen und sollt es ein Erlaftjahr heiften im Lande alien, die drinnen wohnen; denn es ist euer Halljahr, da soil ein jeglicher bei euch wieder zu seiner Habe und zu seinem Geschlecht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Denn das funfzigste Jahr ist euer Halljahr; ihr sollt nicht saen, auch, was von ihm selber wachst, nicht ernten, auch was ohne Arbeit wachst im Weinberge, nicht lesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Denn das Halljahr soil unter euch heilig sein. Ihr sollt aber essen, was das Feld tragt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Das ist das Halljahr, da jedermann wieder zu dem Seinen kommen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Wenn du nun etwas deinem Nachsten verkaufst Oder ihm etwas abkaufst, soli keiner seinen Bruder ubervorteilen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'sondern nach der Zahl vom Halljahr an sollst du es von ihm kaufen; und was die Jahre hernach tragen mogen, so hoch soil er dir\'s verkaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Nach der Menge der Jahre sollst du den Kauf steigern und nach der Wenige der Jahre sollst du den Kauf ringern; denn er soli dir\'s, nachdem es tragen mag, verkaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'So ubervortei Lev nun keiner seinen Nachsten, sondern furchte dich vor deinem Gott; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Darum tut nach meinen Satzungen und haltet meine Rechte, daß ihr danach tut, auf daß ihr im Lande sicher wohnen moget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Denn das Land soil euch seine Fruchte geben, daß ihr zu essen genug habet und sicher darinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und ob du würdest sagen: Was sollen wir essen im siebenten Jahr? denn wir saen nicht, so sammeln wir auch kein Getreide ein:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'da will ich meinem Segen uber euch im sechsten Jahr gebieten, daß er soli dreier Jahre Getreide machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'daß ihr saet im achten Jahr und von dem alten Getreide esset bis in das neunte Jahr, daß ihr vom alten esset, bis wieder neu Getreide kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Darum sollt ihr das Land nicht verkaufen ewiglich; denn das Land ist mein, und ihr seid Fremdlinge und Gaste vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Und sollt in all eurem Lande das Land zu losen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Wenn dein Bruder verarmet und verkauft dir seine Habe, und sein nachster Freund kommt zu ihm, daß er\'s lose, so soli er\'s losen, was sein Bruder verkauft hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Wenn aber jemand keinen Loser hat und kann mit seiner Hand so viel zuwege bringen, daß er\'s ein Teil lose,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'so soil man rechnen von dem Jahr, da er\'s hat verkauft, und dem Verkaufer die übrigen Jahre wieder einraumen, daß er wieder zu seiner Habe komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Kann aber seine Hand nicht so viel finden, daß eines Teils ihm wieder werde, so soil, daß er verkauft hat, in der Hand des Kaufers sein bis zum Halljahr; in demselben soil es ausgehen, und er wieder zu seiner Habe kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Wer ein Wohnhaus verkauft inner der Stadtmauer, der hat ein ganz Jahr Frist, dasselbe wieder zu Ibsen; das soil die Zeit sein, darinnen er\'s Ibsen mag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wo er\'s aber nicht loset, ehe denn das ganze Jahr um ist, so soil\'s der Kaufer ewiglich behalten und seine Nachkommen, und soil nicht los ausgehen im Halljahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Ist\'s aber ein Haus auf dem Dorfe, da keine Mauer um ist, das soil man dem Felde des Landes gleich rechnen und soil loswerden und im Halljahr ledig ausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Die Stadte der Leviten und die Hauser in den Stadten, da ihre Habe innen ist, mogen immerdar geloset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Wer etwas von den Leviten loset, der soil\'s verlassen im Halljahr, es sei Haus Oder Stadt, das er besessen hat; denn die Hauser in Stadten der Leviten sind ihre Habe unter den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Aber das Feld vor ihren Stadten soil man nicht verkaufen; denn das ist ihr Eigentum ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Wenn dein Bruder verarmet und neben dir abnimmt, so sollst du ihn aufnehmen als einen Fremdling Oder Gast, daß er lebe neben dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Und sollst nicht Wucher von ihm nehmen noch Obersatz, sondern sollst dich vor deinem Gott furchten, auf daü dein Bruder neben dir leben konne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Denn du sollst ihm dein Geld nicht auf Wucher tun, noch deine Speise auf Ubersatz austun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Denn ich bin der HERR, euer Gott, der euch aus Agyptenland gefuhret hat, dad ich euch das Land Kanaan gabe und euer Gott ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Wenn dein Bruder verarmet neben dir und verkauft sich dir, so sollst du ihn nicht lassen dienen als einen Leibeigenen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'sondern wie ein Taglohner und Gast soil er bei dir sein und bis an das Halljahr bei dir dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Dann soil er von dir los ausgehen und seine Kinder mit ihm; und soil wiederkommen zu seinem Geschlecht und zu seiner Vater Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn sie sind meine Knechte, die ich aus Agyptenland gefuhret habe; darum soil man sie nicht auf leibeigene Weise verkaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Und sollst nicht mit der Strenge über sie herrschen, sondern dich furchten vor deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Willst du aber leibeigene Knechte und Magde haben, so sollst du sie kaufen von den Heiden, die um euch her sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'von den Gasten, die Fremdlinge unter euch sind, und von ihren Nachkommen, die sie bei euch in eurem Lande zeugen: dieselben sollt ihr zu eigen haben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'und sollt sie besitzen, und eure Kinder nach euch, zum Eigentum fur und fur; die sollt ihr leibeigene Knechte sein lassen. Aber uber eure Bruder, die Kinder Israel, soil keiner des andern herrschen mit der Strenge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Wenn irgend ein Fremdling Oder Gast bei dir zunimmt, und dein Bruder neben ihm verarmet und sich dem Fremdling Oder Gast bei dir Oder jemand von seinem Stamm verkauft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'so soil er nach seinem Verkaufen Recht haben, wieder los zu werden, und es mag ihn jemand unter seinen Brudern losen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Oder sein Vetter Oder Vetters Sohn, Oder sonst sein nachster Blutsfreund seines Geschlechts; Oder so seine selbst Hand so viel erwirbt, so soil er sich losen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Und soil mit seinem Kaufer rechnen vom Jahr an, da er sich verkauft hatte, bis aufs Halljahr; und das Geld soil nach der Zahl der Jahre seines Verkaufens gerechnet werden; und soil sein Taglohn der ganzen Zeitmiteinrechnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Sind noch viel Jahre bis an das Halljahr, so soil er nach denselben desto mehr zu losen geben, danach er gekauft ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Sind aber wenig Jahre ubrig bis an das Halljahr, so soil er auch danach wieder geben zu seiner Losung und soil sein Taglohn von Jahrzu Jahr mit einrechnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Und sollst nicht lassen mit der Strenge über ihn herrschen vor deinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Wird er aber auf diese Weise sich nicht Ibsen, so soil er im Halljahr los ausgehen und seine Kinder mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn die Kinder Israel sind meine Knechte, die ich aus Agyptenland gefuhret habe. Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ihr sollt euch keinen Gotzen machen noch Büd, und sollt euch keine Sau Lev aufrichten, noch keinen Malstein setzen in eurem Lande, daß ihrdavor anbetet; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Haltet meine Sabbate und furchtet euch vor meinem Heiligtum! Ich bin der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Werdet ihr in meinen Satzungen wandeln und meine Gebote halten und tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'so will, ich euch Regen geben zu seiner Zeit, und das Land soil sein Gewachs geben und die Baume auf dem Felde ihre Fruchte bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Und die Dreschzeit soil reichen bis zur Weinernte, und die Weinernte soil reichen bis zur Zeit der Saat. Und sollt Brots die Fül Lev haben und sollt sicher in eurem Lande wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Ich will Frieden geben in eurem Lande, daü ihr schlafet, und euch niemand schrecke. Ich will die bosen Here aus eurem Lande tun, und soli kein Schwert durch euer Land gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Ihr solit eure Feinde jagen, und sie sollen vor euch her ins Schwert fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Euer fünf solien hundert jagen, und euer hundert sollen zehntausend jagen; denn eure Feinde solien vor euch her fallen ins Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und ich will mich zu euch wenden und will euch wachsen und mehren lassen und will meinen Bund euch halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Und sollt von dem Firnen essen, und wenn das Neue kommt, das Firne wegtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ich will meine Wohnung unter euch haben, und meine See Lev soil euch nicht verwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Und will unter euch wandeln und will euer Gott sein; so sollt ihr mein Volk sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Denn ich bin der HERR, euer Gott, der euch aus Agyptenland gefuhret hat, daß ihr nicht ihre Knechte waret, und habe euer Joch zerbrochen und habe euch aufgerichtet wandeln lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Werdet ihr aber mir nicht gehorchen und nicht tun diese Gebote alle,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'und werdet meine Satzungen verachten, und eure See Lev meine Rechte verwerfen, daß ihr nicht tut al Lev meine Gebote, und werdet meinen Bund lassen anstehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'so will ich euch auch solches tun: Ich will euch heimsuchen mit Schrecken, Schwulst und Fieber, daß euch die Angesichte verfallen und der Leib verschmachte; ihr sollt umsonst euren Samen saen, und eure Feinde sollen ihn fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'und ich will mein Antlitz wider euch stellen, und sollt geschlagen werden vor euren Feinden; und die euch hassen, sollen uber euch herrschen; und sollt fliehen, da euch niemand jaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'So ihr aber uber das noch nicht mir gehorchet, so will ich\'s noch siebenmal mehr machen, euch zu strafen urn eure Sünde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'daß ich euren Stolz und Halsstarrigkeit breche; und will euren Himmel wie Eisen und eure Erde wie Erz machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Und eure Mühe und Arbeit soil verloren sein, daß euer Land sein Gewachs nicht gebe und die Baume im Lande ihre Fruchte nicht bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und wo ihr mir entgegen wandelt und mich nicht horen wollt, so will ich\'s noch siebenmal mehr machen, auf euch zu schlagen urn eurer Sunde willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Und will wilde Here unter euch senden, die sollen eure Kinder fressen und euer Vieh zerreiften und euerweniger machen; und eure Straften sollen wüste werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Werdet ihr euch aber damit noch nicht von mir zuchtigen lassen und mir entgegen wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'will ich euch auch entgegen wandeln und will euch noch siebenmal mehr schlagen urn eurer Sünde willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Und will ein Racheschwert fiber euch bringen, das meinen Bund rachen soil. Und ob ihr euch in eure Stadte versammelt, will ich doch die Pestilenz unter euch senden und will euch in eurer Feinde Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Dann will ich euch den Vorrat des Brots verderben, daß zehn Weiber sollen euer Brot in einem Ofen backen, und euer Brot soil man mit Gewicht auswagen, und wenn ihr esset, sollt ihr nicht satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Werdet ihr aber dadurch mir noch nicht gehorchen und mir entgegen wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'so will ich auch euch im Grimm entgegen wandeln und will euch siebenmal mehr strafen urn eure Sünde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'daß ihr sollt eurer Sohne und Tochter Fleisch fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Und will eure Hohen vertilgen und eure Bilder ausrotten; und will eure Leichname auf eure Gotzen werfen; und meine See Lev wird an euch Ekel haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Und will eure Stadte wüste machen und eures Heiligtums Kirchen einreiften; und will euren süften Geruch nicht riechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Also will ich das Land wüste machen, daß eure Feinde, so drinnen wohnen, sich davor entsetzen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Euch aber will ich unter die Heiden streuen und das Schwert ausziehen hinter euch her, daß euer Land soil wüste sein und eure Stadte verstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Alsdann wird das Land ihm seine Feier gefallen lassen, solange es wüste liegt, und ihr in der Feinde Land seid; ja, dann wird das Land feiern und ihm seine Feier gefallen lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'solange es wüste liegt, darum daß es nicht feiern konnte, da ihr\'s solltet feiern lassen, da ihr drinnen wohnetet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Und denen; die von euch überbleiben, will ich ein feig Herz machen in ihrer Feinde Land, daß sie soil ein rauschend Blattjagen; und sollen fliehen davor, als jagte sie ein Schwert, und fallen, da sie niemand jaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Und soil einer fiber den andern hinfallen, gleich als vor dem Schwert, und doch sie niemand jaget; und ihr sollt euch nicht auflehnen dürfen wider eure Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Und ihr sollt umkommen unter den Heiden, und eurer Feinde Land soil euch fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Welche aber von euch überbleiben, die sollen in ihrer Missetat verschmachten in der Feinde Land; auch in ihrer Vater Missetat sollen sie verschmachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Da werden sie denn bekennen ihre Missetat und ihrer Vater Missetat, damit sie sich an mir versundiget und mir entgegen gewandelt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Darum will ich auch ihnen entgegen wandeln und will sie in ihrer Feinde Land wegtreiben. Da wird sich ja ihr unbeschnittenes Herz demutigen, und dann werden sie ihnen die Strafe ihrer Missetat gefallen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Und ich werde gedenken an meinen Bund mit Jakob und an meinen Bund mit Isaak und an meinen Bund mit Abraham und werde an das Land gedenken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'das von ihnen verlassen ist und ihm seine Feier gefallen lasset, dieweil es wüste von ihnen liegt, und sie ihnen die Strafe ihrer Missetat gefallen lassen, darum daß sie meine Rechte verachtet, und ihre See Lev an meinen Satzungen Ekel gehabt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Auch wenn sie schon in der Feinde Land sind, habe ich sie gleichwohl nicht verworfen, und ekelt mich ihrer nicht also, daß es mit ihnen aus sein sollte, und mein Bund mit ihnen sollte nicht mehr gelten; denn ich bin der HERR, ihr Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Und will uber sie an meinen ersten Bund gedenken, da ich sie aus Agyptenland fuhrete vor den Augen der Heiden, daß ich ihr Gott ware, ich der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dies sind die Satzungen und Rechte und Gesetze, die der HERR zwischen ihm und den Kindern Israel gestellet hat auf dem Berge Sinai durch die Hand Moses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn jemand dem HERRN ein besonder Gelübde tut, daß er seinen Leib schatzet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'so soil das die Schatzung sein: Ein Mannsbild, zwanzig Jahre alt, bis ins sechzigste Jahr, sollst du schatzen auf funfzig silberne Sekel nach dem Sekel des Heiligtums;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'ein Weibsbild auf dreißig Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Von fünf Jahren bis auf zwanzig Jahre sollst du ihn schatzen auf zwanzig Sekel, wenn\'s ein Mannsbild ist; ein Weibsbild aber auf zehn Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Von einem Monden an bis auf fünf Jahre sollst du ihn schatzen auf funf silberne Sekel, wenn\'s ein Mannsbild ist; ein Weibsbild aber auf drei silberne Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ist er aber sechzig Jahre alt und drüber, so sollst du ihn schatzen auf funfzehn Sekel, wenn\'s ein Mannsbild ist; ein Weibsbild aber auf zehn Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ist er aber zu arm zu solcher Schatzung, so soil er sich vor den Priester stellen, und der Priester soil ihn schatzen; er soli ihn aber schatzen, nachdem seine Hand, des, dergelobet hat, erwerben kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ist\'s aber ein Vieh, das man dem HERRN opfern kann: alles, was man des dem HERRN gibt, ist heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man soli\'s nicht wechseln noch wandeln, ein gutes urn ein boses, Oder ein boses urn ein gutes. Wird\'s aber jemand wechseln; ein Vieh urn das andere, so sollen sie beide dem HERRN heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ist aber das Tier unrein, daß man\'s dem HERRN nicht opfern darf, so soli man\'s vor den Priester stellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Und der Priester soil es schatzen, ob\'s gut Oder bose sei; und es soil bei des Priesters Schatzen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Will\'s aber jemand losen, der soil den Fünften über die Schatzung geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Wenn jemand sein Haus heiliget, daß es dem HERRN heilig sei, das soil der Priester schatzen, ob\'s gut Oder bose sei; und danach es der Priester schatzet, so soil\'s bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'So es aber der, so es geheiliget hat, will losen, so soli er den fünften Teil des Geldes, über das es geschatzet ist, drauf geben, so soil\'s sein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Wenn jemand ein Stück Ackers von seinem Erbgut dem HERRN heiliget, so soil er geschatzet werden, nachdem er tragt. Tragt er ein Homor Gerste, so soli er funfzig Sekel Silbers gelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Heiliget er aber seinen Acker vom Halljahr an, so soli er nach seiner Würde gelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Hat er ihn aber nach dem Halljahr geheiliget, so soil ihn der Priester rechnen nach den ubrigen Jahren zum Halljahr und danach geringer schatzen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Will aber der, so ihn geheiliget hat, den Acker losen, so soil er den fünften Teil des Geldes, über das er geschatzet ist, drauf geben, so soil er sein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Will er ihn aber nicht losen, sondern verkauft ihn einem andern, so soli er ihn nicht mehr losen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'sondern derselbe Acker, wenn er im Halljahr los ausgehet, soil dem HERRN heilig sein, wie ein verbannter Acker; und soil des Priesters Erbgut sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Wenn aber jemand einen Acker dem HERRN heiliget, den er gekauft hat, und nicht sein Erbgut ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'so soil ihn der Priester rechnen, was er gilt, bis an das Halljahr; und er soil desselben Tages solche Schatzung geben, daß erdem HERRN heilig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Aber im Halljahr soil er wieder gelangen an denselben, von dem er ihn gekauft hat, daß er sein Erbgut im Lande sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'AILev Würderung soli geschehen nach dem Sekel des Heiligtums. Ein Sekel aber macht zwanzig Gera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Die Erstgeburt unter dem Vieh, die dem HERRN sonst gebuhret, soli niemand dem HERRN heiligen, es sei ein Ochse Oder Schaf; denn es ist des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Ist aber an dem Vieh etwas Unreines, so soil man\'s losen nach seiner Wurde und druber geben den Fünften. Will er\'s nicht losen, so verkaufe man\'s nach seiner Würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Man soli kein Verbanntes verkaufen, noch losen, das jemand dem HERRN verbannet von allem, das sein ist, es seien Menschen Vieh Oder Erbacker; denn alles Verbannte ist das Allerheiligste dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Man soli auch keinen verbannten Menschen losen, sondern er soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'AILev Zehnten im Lande, beide von Samen des Landes und von Früchten der Baume, sind des HERRN und sollen dem HERRN heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Will aber jemand seinen Zehnten losen, der soil den Fünften druber geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Und al Lev Zehnten von Rindern und Schafen, und was unter der Rute gehet, das ist ein heiliger Zehnte dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Man soli nicht fragen, ob\'s gut Oder bose sei; man soil\'s auch nicht wechseln. Wird es aber jemand wechseln, so soil beides heilig sein und nicht geloset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dies sind die Gebote, die der HERR gebot an die Kinder Israel auf dem Berge Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und der HERR redete mit Mose in der Wüste Sinai in der Hutte des Stiffs am ersten Tage des andern Monden im andern Jahr, da sie aus Agyptenland gegangen waren, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Nehmet die Summa der ganzen Gemeine der Kinder Israel nach ihren Geschlechtern und ihrer Vater Hausern und Namen: alles, was mannlich ist, von Haupt zu Haupt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'von zwanzig Jahren an und druber, was ins Heer zu ziehen taugt in Israel; und sollt sie zahlen nach ihren Heeren, du und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und sollt zu euch nehmen je vom Geschlecht einen Hauptmann uber seines Vaters Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Dies sind aber die Namen der Hauptleute, die neben euch stehen sollen: Von Ruben sei Elizur, der Sohn Sedeurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Von Simeon sei Selumiel, der Sohn Zuri-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Von Juda sei Nahesson, der Sohn Amminadabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Von Isaschar sei Nethaneel, der Sohn Zuars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Von Sebulon sei Eliab, der Sohn Helons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Von den Kindern Joseph: Von Ephraim sei Elisama, der Sohn Ammihuds. Von Manasse sei Gamliel, der Sohn Pedazurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Von Benjamin sei Abidan, der Sohn Gideonis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Von Dan sei Ahieser, der Sohn Ammi-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Von Asser sei Pagiel, der Sohn Ochrans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Von Gad sei Eliasaph, der Sohn Deguels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Von Naphthali sei Ahira, der Sohn Enans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das sind die Vornehmsten der Gemeine, die Hauptleute unter den Stammen ihrer Vater, die da Haupter und Fursten in Israel waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Und Mose und Aaron nahmen siezu sich, wie sie da mit Namen genannt sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'und sammelten auch die ganze Gemeine am ersten Tage des andern Monden und rechneten sie nach ihrer Geburt, nach ihren Geschlechtern und Vater Hausern und Namen, von zwanzig Jahren an und druber, von Haupt zu Haupt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'wie der HERR Mose geboten hatte, und zahleten sie in der Wüste Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Der Kinder Ruben, des ersten Sohns Israels, nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von Haupt zu Haupt, alles, was mannlich war, von zwanzig Jahren und druber, und ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'wurden gezahlet zum Stamm Ruben sechsundvierzigtausend und fünfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Der Kinder Simeon nach ihrer Geburt, Geschlecht, ihrer Vater Hausern, Zahl und Namen, von Haupt zu Haupt, alles, was mannlich war, von zwanzig Jahren und druber, und ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'wurden gezahlet zum Stamm Simeon neunundfünfzigtausend und dreihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Der Kinder Gad nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'wurden gezahlet vom Stamm Gad funfundvierzigtausend sechshundertundfünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Der Kinder Juda nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'wurden gezahlet vom Stamm Juda vierundsiebenzigtausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Der Kinder Isaschar nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'wurden gezahlet zum Stamm Isaschar vierundfunfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Der Kinder Sebulon nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'wurden gezahlet zum Stamm Sebulon siebenundfünfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Der Kinder Joseph von Ephraim nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'wurden gezahlet zum Stamm Ephraim vierzigtausend und fünfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Der Kinder Manasse nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'wurden zum Stamm Manasse gezahlet zweiunddreißigtausend und zweihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Der Kinder Benjamin nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'wurden zum Stamm Benjamin gezahlet funfunddreifügtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Der Kinder Dan nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'wurden gezahlet zum Stamm Dan zweiundsechzigtausend und siebenhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Der Kinder Asser nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'wurden zum Stamm Asser gezahlet einundvierzigtausend und fünfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Der Kinder Naphthali nach ihrer Geburt, Geschlecht, ihrer Vater Hausern und Namen, von zwanzig Jahren und druber, was ins Heer zu ziehen taugte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'wurden zum Stamm Naphthali gezahlet dreiundfünfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Dies sind, die Mose und Aaron zahleten, samt den zwolf Fursten Israels, deren je einer uber ein Haus ihrer Vater war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Und die Summa der Kinder Israel nach ihrer Vater Hausern, von zwanzig Jahren und drüber, was ins Heerzuziehen taugte in Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'deren war sechsmalhunderttausend und dreitausend funfhundertundfunzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Aber die Leviten nach ihrer Vater Stamm wurden nicht mit unter gezahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Den Stamm Levi sollstdu nicht zahlen, noch ihre Summa nehmen unter den Kindern Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'sondern du sollst sie ordnen zur Wohnung bei dem Zeugnis und zu allem Gerate und zu allem, was dazu gehoret. Und sie sollen die Wohnung tragen und alles Gerate; und sollen sein pflegen und urn die Wohnung her sich lagern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn man reisen soil, so sollen die Leviten die Wohnung abnehmen. Wenn aber das Heer zu lagern ist, sollen sie die Wohnung aufschlagen. Und wo ein Fremder sich dazu machet, der soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Die Kinder Israel sollen sich lagern, ein jeglicher in sein Lager und bei dem Panier seiner Schar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Aber die Leviten sollen sich urn die Wohnung des Zeugnisses her lagern, auf daß nicht ein Zorn uber die Gemeine der Kinder Israel komme; darum sollen die Leviten der Hut warten an der Wohnung des Zeugnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und die Kinder Israel taten alles, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Die Kinder Israel sollen vor der Hutte des Stiffs umher sich lagern, ein jeglicher unter seinem Panier und Zeichen nach ihrer Vater Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Gegen Morgen soil sich lagern Juda mit seinem Panier und Heer; ihr Hauptmann Nahesson, der Sohn Amminadabs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'und sein Heer an der Summa vierundsiebenzigtausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Neben ihm soil sich lagern der Stamm Isaschar; ihr Hauptmann Nethaneel, der Sohn Zuars;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'und sein Heer an der Summa vierundfunfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Dazu der Stamm Sebulon; ihr Hauptmann Eliab, der Sohn Helons;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'sein Heer an der Summa siebenundfünfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Dali alle, die ins Lager Judas gehoren, seien an der Summa hundertundsechsundachtzigtausend und vierhundert, die zu ihrem Heere gehoren; und sollen vornean ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Gegen Mittag soli liegen das Gezelt und Panier Rubens mit ihrem Heer; ihr Hauptmann Elizur, der Sohn Sedeurs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'und sein Heer an der Summa sechsundvierzigtausend funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Neben ihm soli sich lagern der Stamm Simeon; ihr Hauptmann Selumiel, der Sohn Zuri-Saddais;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'und sein Heer an der Summa neunundfunfzigtausend dreihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Dazu der Stamm Gad; ihr Hauptmann Eliasaph, der Sohn Reguels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'und sein Heer an der Summa funfundvierzigtausend sechshundertundfunfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Dali alle, die ins Lager Rubens gehoren, seien an der Summa hundertundeinundfünfzigtausend vierhundertundfünfzig, die zu ihrem Heer gehoren; und sollen die andern im Ausziehen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Danach soli die Hutte des Stitts ziehen mit dem Lager der Leviten mitten unter den Lagern; und wie sie sich lagern, so sollen sie auch ziehen, ein jeglicher an seinem Ort; unter seinem Panier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Gegen Abend soil liegen das Gezelt und Panier Ephraims mit ihrem Heer; ihr Hauptmann soil sein Elisama, der Sohn Ammihuds;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'und sein Heer an der Summa vierzigtausend und funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Neben ihm soli sich lagern der Stamm Manasse; ihr Hauptmann Gamliel, der Sohn Pedazurs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'sein Heer an der Summa zweiunddreilügtausend und zweihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Dazu der Stamm Benjamin; ihr Hauptmann Abidan, der Sohn Gideonis;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'sein Heer an der Summa funfunddreißigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Dali alle, die ins Lager Ephraims gehoren, seien an der Summa hundertundachttausend und einhundert, die zu seinem Heer gehoren; und sollen die dritten im Ausziehen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Gegen Mitternacht soil liegen das Gezelt und Panier Dans mit ihrem Heer; ihr Hauptmann Ahieser der Sohn Ammi-Saddais;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'sein Heer an der Summa zweiundsechzigtausend und siebenhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Neben ihm soli sich lagern der Stamm Asser; ihr Hauptmann Pagel, der Sohn Ochrans;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'sein Heer an der Summa einundvierzigtausend und funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Dazu der Stamm Naphthali; ihr Hauptmann Ahira, der Sohn Enans;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'sein Heer an der Summa dreiundfunfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Dali alle, die ins Lager Dan gehoren, seien an der Summa hundertundsiebenundfunfzigtausend und sechshundert; und sollen die letzten sein im Ausziehen mit ihrem Panier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das ist die Summa der Kinder Israel nach ihrer Vater Hausern und Lagern mit ihren Heeren: sechshunderttausend und dreitausend funfhundertundfunzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Aber die Leviten wurden nicht in die Summa unter die Kinder Israel gezahlet, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Kinder Israel taten alles, wie der HERR Mose geboten hatte, und lagerten sich unter ihre Paniere und zogen aus, ein jeglicher in seinem Geschlecht nach ihrer Vater Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dies ist das Geschlecht Aarons und Moses zu der Zeit, da der HERR mit Mose redete auf dem Berge Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Und dies sind die Namen der Sohne Aarons: Der Erstgeborne Nadab, danach Abihu, Eleazar und Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Das sind die Namen der Sohne Aarons, die zu Priestern gesalbet waren und ihre Hande gefullet zum Priestertum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Aber Nadab und Abihu starben vordem HERRN, da sie fremd Feuer opferten vor dem HERRN in der Wuste Sinai; und hatten keine Sohne. Eleazar aber und Ithamar pflegten des Priesteramts unter ihrem Vater Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Bringe den Stamm Levi herzu und stelle sie vor den Priester Aaron, dafi sie ihm dienen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'und seiner und der ganzen Gemeine Hut warten vor der Hütte des Stifts und dienen am Dienst der Wohnung;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'und warten alles Gerates der Hütte des Stifts und der Hut der Kinder Israel, zu dienen am Dienst der Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und sollst die Leviten Aaron und seinen Sohnen zuordnen zum Geschenk von den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aaron aber und seine Sohne sollst du setzen, daß sie ihres Priestertums warten. Wo ein Fremder sich herzutut, der soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Siehe, ich habe die Leviten genommen unter den Kindern Israel fur alle Erstgeburt, die da Mutter brechen unter den Kindern Israel, also daß die Leviten sollen mein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn die Erstgeburten sind mein, seit der Zeit ich alle Erstgeburt schlug in Agyptenland; da heiligte ich mir alle Erstgeburt in Israel, von Menschen an bis auf das Vieh, daß sie mein sein sollen, ich der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und der HERR redete mit Mose in der Wuste Sinai und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Zahle die Kinder Levi nach ihrer Vater Hausern und Geschlechtern, alles, was mannlich ist, eines Monden alt und druber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Also zahlete sie Mose nach dem Wort des HERRN, wie er geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und waren dies die Kinder Levi mit Namen: Gerson, Kahath, Merari.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Die Namen aber der Kinder Gersons in ihrem Geschlecht waren: Libni und Simei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Die Kinder Kahaths in ihrem Geschlecht waren: Amram, Jezehar, Hebron und Usiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Die Kinder Meraris in ihrem Geschlecht waren: Maheli und Musi. Dies sind die Geschlechter Levis nach, ihrer Vater Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Dies sind die Geschlechter von Gerson: Die Libniter und Simeiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Deren Summa war an der Zahl funden siebentausend und fünfhundert, alles, was mannlich war eines Monden alt und druber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Und dasselbe Geschlecht der Gersoniter sollen sich lagern hinter der Wohnung gegen den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Ihr Oberster sei Eliasaph, der Sohn Laels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Und sie sollen warten an der Hütte des Stifts, namlich der Wohnung und der Hütte und ihrer Decke und des Tuchs in der Tür der Hütte des Stifts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'des Umhangs am Vorhofe und des Tuchs in der Tür des Vorhofs, welcher urn die Wohnung und urn den Altar hergehet, und seiner Seile, und alles, was zu seinem Dienst gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Dies sind die Geschlechter von Kahath: Die Amramiten, die Jezehariten, die Hebroniten und Usieliten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'was mannlich war, eines Monden alt und druber, an der Zahl achttausend und sechshundert, die der Hut des Heiligtums warten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Und sollen sich lagern an die Seite der Wohnung gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Ihr Oberster sei Elizaphan, der Sohn Usiels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Und sie sollen warten der Lade, des Tisches, des Leuchters, des Altars und alles Gerates des Heiligtums, daran sie dienen, und des Tuchs, und was zu seinem Dienst gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Aber der Oberste fiber alle Obersten der Leviten soil Eleazar sein, Aarons Sohn, des Priesters, fiber die, so verordnet sind, zu warten der Hut des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Dies sind die Geschlechter Meraris: Die Maheliter und Musiter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'die an der Zahl waren sechstausend und zweihundert, alles, was mannlich war, eines Monden alt und druber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Ihr Oberster sei Zuriel, der Sohn Abihails. Und sollen sich lagern an die Seite der Wohnung gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Und ihr Amt soil sein, zu warten der Bretter und Riegel und Saulen und Füfte der Wohnung und alles seines Gerates und seines Dienstes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'dazu der Saulen urn den Vorhof her mit den Füften und Nageln und Seilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Aber vor der Wohnung und vor der Hütte des Stifts gegen Morgen sollen sich lagern Mose und Aaron und seine Sohne, daß sie des Heiligtums warten und der Kinder Israel. Wenn sich ein Fremder herzutut, der soli sterben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle Leviten in der Summa, die Mose und Aaron zahleten nach ihren Geschlechtern, nach dem Wort des HERRN, eitel Mannlein, eines Monden alt und druber, waren zweiundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und der HERR sprach zu Mose: Zahle alle Erstgeburt, was mannlich ist unter den Kindern Israel, eines Monden alt und druber, und nimm die Zahl ihrer Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Und sollst die Leviten mir, dem HERRN, aussondern fur alle Erstgeburt der Kinder Israel und der Leviten Vieh fur alle Erstgeburt unter dem Vieh der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose zahlete, wie ihm der HERR geboten hatte, alle Erstgeburt unter den Kindern Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'und fand sich an der Zahl der Namen aller Erstgeburt, was mannlich war, eines Monden alt und druber, in ihrer Summa zweiundzwanzigtausend zweihundertunddreiundsiebenzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten fur alle Erstgeburt unter den Kindern Israel und das Vieh der Leviten fur ihr Vieh, daß die Leviten mein, des HERRN, seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Aber das Losegeld von den zweihundertdreiundsiebenzig uberlangen Erstgeburten der Kinder Israel uber der Leviten Zahl');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'sollst du je fünf Sekel nehmen von Haupt zu Haupt, nach dem Sekel des Heiligtums (zwanzig Gera gilt ein Sekel),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'und sollst dasselbe Geld, das uberlang ist fiber ihre Zahl, geben Aaron und seinen Sohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Da nahm Mose das Losegeld, das uberlang war uber der Leviten Zahl,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'von den Erstgeburten der Kinder Israel, tausend dreihundertundfunfundsechzig Sekel, nach dem Sekel des Heiligtums,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'und gab\'s Aaron und seinen Sohnen nach dem Wort des HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Nimm die Summa der Kinder Kahath aus den Kindern Levi nach ihrem Geschlecht und Vater Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'von dreilüg Jahren an und druber, bis ins funfzigste Jahr, alle, die zum Heer taugen, daß sie tun die Werke in der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Das soli aber das Amt der Kinder Kahath in der Hutte des Stifts sein, das das Allerheiligste ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Wenn das Heer aufbricht, so soli Aaron und seine Sohne hineingehen und den Vorhang abnehmen und die Lade des Zeugnisses drein winden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'und drauf tun die Decke von Dachsfellen und oben drauf eine ganze gelbe Decke breiten und seine Stangen dazu legen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'und uber den Schautisch auch eine gelbe Decke breiten und dazu legen die Schusseln, Loffel, Schalen und Kannen, aus und ein zu gielien. Und das tagliche Brot soil dabei liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Und sollen druber breiten eine rosinrote Decke und dieselbe bedecken mit einer Decke von Dachsfellen und seine Stangen dazu legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Und sollen eine gelbe Decke nehmen und drein winden den Leuchter des Lichts und seine Lampen mit seinen Schneuzen und Napfen und alle Olgefalie, die zum Amt gehoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Und sollen urn das alles tun eine Decke von Dachsfellen, und sollen sie auf Stangen legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Also sollen sie auch uber den güldenen Altar eine gelbe Decke breiten und dieselbe bedecken mit der Decke von Dachsfellen und seine Stangen dazu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Alle Gerate, damit sie schaffen im Heiligtum, sollen sie nehmen und gelbe Decken druber tun und mit einer Decke von Dachsfellen decken und auf Stangen legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Sie sollen auch die Asche vom Altar fegen und eine scharlachene Decke druber breiten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'und alle seine Gerate dazu legen, damit sie drauf schaffen: Kohlpfannen, Kreuel, Schaufeln, Becken, mit allem Gerate des Altars; und sollen druber breiten eine Decke von Dachsfellen und seine Stangen dazu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Wenn nun Aaron und seine Sohne solches ausgerichtet haben und das Heiligtum und alle seine Gerate bedecket, wenn das Heer aufbricht, danach sollen die Kinder Kahath hineingehen, daß sie es tragen, und sollen das Heiligtum nicht anruhren, daß sie nicht sterben. Dies sind die Lasten der Kinder Kahath an der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Und Eleazar, Aarons, des Priesters, Sohn soil das Amt haben, daß er ordne das 01 zum Licht und die Spezerei zum Rauchwerk und das tagliche Speisopfer und das Salbol; daß er beschicke die ganze Wohnung und alles, was drinnen ist, im Heiligtum und seinem Gerate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und der HERR redete mit Mose und mit Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ihr sollt den Stamm des Geschlechts der Kahathiter nicht lassen sich verderben unter den Leviten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'sondern das sollt ihr mit ihnen tun, daß sie leben und nicht sterben, wo sie würden anruhren das Allerheiligste: Aaron und seine Sohne sollen hineingehen und einen jeglichen stellen zu seinem Amt und Last.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Sie aber sollen nicht hineingehen, zu schauen unbedeckt das Heiligtum, daß sie nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Nimm die Summa der Kinder Gerson auch nach ihrer Vater Hause und. Geschlecht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'von dreilüg Jahren an und druber bis ins funfzigste Jahr, und ordne sie alle, die da zum Heer tuchtig sind, daß sie ein Amt haben in der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Das soli aber des Geschlechts der Gersoniter Amt sein, daß sie schaffen und tragen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Sie sollen die Teppiche der Wohnung und der Hutte des Stifts tragen und seine Decke und die Decke von Dachsfellen, die oben druber ist, und das Tuch in der Tur der Hutte des Stifts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'und die Umhange des Vorhofs und das Tuch in der Tür des Tors am Vorhofe, welcher um die Wohnung und Altar hergehet, und ihre Seile und alle Gerate ihres Amts und alles, was zu ihrem Amt gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Wort Aarons und seiner Sohne soil alles Amt der Kinder Gerson gehen, alles, was sie tragen und schaffen sollen; und ihrsollt zusehen, daß sie aller ihrer Last warten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Das soil das Amt des Geschlechts der Kinder der Gersoniter sein in der Hutte des Stitts; und ihre Hut soil unter der Hand Ithamars sein, des Sohns Aarons, des Priesters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Die Kinder Merari nach ihrem Geschlecht und Vaterhause sollst du auch ordnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'von dreißig Jahren an und drüber bis ins funfzigste Jahr, alle, die zum Heer taugen, daß sie ein Amt haben in der Hutte des Stitts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Auf diese Last aber sollen sie warten nach all ihrem Amt in der Hutte des Stitts, daß sie tragen die Bretter der Wohnung und Riegel und Saulen und Fuße,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'dazu die Saulen des Vorhofs umher und Fuße und Nagel und Seile mit all ihrem Gerate nach all ihrem Amt; einem jeglichen sollt ihr sein Teil der Last am Gerate zu warten verordnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Das sei das Amt der Geschlechter der Kinder Merari, alles, das sie schaffen sollen in der Hutte des Stitts unter der Hand Ithamars, des Priesters, Aarons Sohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose und Aaron samt den Hauptleuten der Gemeine zahleten die Kinder der Kahathiter nach ihren Geschlechtern und Vater Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'von dreißig Jahren und drüber bis ins funfzigste, alle, die zum Heer taugten, daß sie Amt in der Hutte des Stitts hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und die Summa war zweitausend siebenhundertundfunfzig:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das ist die Summa der Geschlechter der Kahathiter, die alle zu schaffen hatten in der Hutte des Stiffs, die Mose und Aaron zahleten nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Die Kinder Gerson wurden auch gezahlet in ihren Geschlechtern und Vater Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'von dreißig Jahren und drüber bis ins funfzigste, alle, die zum Heer taugten, daß sie Amt in der Hutte des Stifts hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Und die Summa war zweitausend sechshundertunddreißig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das ist die Summa der Geschlechter der Kinder Gerson, die alle zu schaffen hatten in der Hütte des Stifts, welche Mose und Aaron zahleten nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Die Kinder Merari wurden auch gezahlet nach ihren Geschlechtern und Vater Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'von dreißig Jahren und drüber bis ins funfzigste, alle, die zum Heer taugten, daß sie Amt in der Hutte des Stifts hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Und die Summa war dreitausend und zweihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das ist die Summa der Geschlechter der Kinder Merari, die Mose und Aaron zahleten nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Die Summa aller Leviten, die Mose und Aaron samt den Hauptleuten Israels zahleten nach ihren Geschlechtern und Vater Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'von dreißig Jahren und drüber bis ins funfzigste, aller, die eingingen zu schaffen, ein jeglicher sein Amt, und zu tragen die Last in der Hütte des Stifts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'war achttausend fünfhundertundachtzig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'die gezahlet wurden nach dem Wort des HERRN durch Mose, ein jeglicher zu seinem Amt und Last, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Gebeut den Kindern Israel, daß sie aus dem Lager tun alle Aussatzigen und alle, die Eiterflüsse haben und die an den Toten unrein worden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Beide Mann und Weib sollen sie hinaustun vor das Lager, daß sie nicht ihre Lager verunreinigen, darinnen ich unter ihnen wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Kinder Israel taten also und taten sie hinaus vor das Lager, wie der HERR zu Mose geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Sage den Kindern Israel und sprich zu ihnen: Wenn ein Mann Oder Weib irgend eine Sünde wider einen Menschen tut und sich an dem HERRN damit versündiget, so hat die Seele eine Schuld auf ihr;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'und sie sollen ihre Sunde bekennen, die sie getan haben, und sollen ihre Schuld versohnen mit der Hauptsumma, und daruber das fünfte Teil dazu tun und dem geben, an dem sie sich verschuldiget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Ist aber niemand da, dem man\'s bezahlen sollte, so soil man\'s dem HERRN geben fur den Priester uber den Widder der Versohnung, damit er versohnet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Desgleichen soil alle Hebe von allem das die Kinder Israel heiligen und dem Priester opfern, sein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Und wer etwas heiliget, das soil auch sein sein; und wer etwas dem Priester gibt, das soil auch sein sein:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Sage den Kindern Israel und sprich zu ihnen: Wenn irgend eines Mannes Weib sich verliefe und sich an ihm versündigte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'undjemand sie fleischlich beschlaft, und würde doch dem Manne verborgen vor seinen Augen und würde verdeckt, daß sie unrein worden ist, und kann sie nicht überzeugen, denn sie ist nicht drinnen begriffen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'und der Eifergeist entzündet ihn, daß er um sein Weib eifert, sie sei unrein Oder nicht unrein:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'so soli er sie zum Priester bringen und ein Opfer über sie bringen, den Zehnten Epha Gerstenmehls, und soil kein 01 drauf gieften, noch Weihrauch drauf tun. Denn es ist ein Eiferopfer und Rugeopfer, das Missetat ruget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Da soil sieder Priester herzuführen und vorden HERRN stellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'und des heiligen Wassers nehmen in ein irden Gefali und Staub vom Boden der Wohnung ins Wasser tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'und soil das Weib vorden HERRN stellen und ihr Haupt entblofien und das Rugeopfer, das ein Eiferopfer ist, auf ihre Hand legen. Und der Priestersoll in seiner Hand bitter verflucht Wasser haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'und soil das Weib beschworen und zu ihrsagen: Hat kein Mann dich beschlafen, und hast dich nicht von deinem Manne verlaufen, dad du dich verunreiniget hast, so sollen dir diese bitteren verfluchten Wasser nicht schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Wo du dich aber von deinem Manne verlaufen hast, dad du unrein bist, und hat jemand dich beschlafen auder deinem Manne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'so soli der Priester das Weib beschworen mit solchem Fluche und soil zu ihrsagen: Der HERR setze dich zum Fluch und zum Schwur unter deinem Volk, dad der HERR deine Hüfte schwinden und deinen Bauch schwellen lasse!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'So gehe nun das verfluchte Wasser in deinen Leib, dad dein Bauch schwelle und deine Hufte schwinde! Und das Weib soil sagen: Amen, Amen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Also soil der Priester diese Fluche auf einen Zettel schreiben und mit dem bittern Wasser abwaschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'und soil dem Weibe von dem bittern verfluchten Wasser zu trinken geben. Und wenn das verfluchte bittere Wasser in sie gegangen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'soil der Priester von ihrer Hand das Eiferopfer nehmen und zum Speisopfer vor dem HERRN weben und auf dem Altar opfern, namlich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'soil er eine Handvoll des Speisopfers nehmen zu ihrem Rugeopfer und auf dem Altar anzünden und danach dem Weibe das Wasser zu trinken geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und wenn sie das Wasser getrunken hat: ist sie unrein und hat sich an ihrem Manne versundiget, so wird das verfluchte Wasser in sie gehen und ihr bitter sein, daß ihr der Bauch schwellen und die Hufte schwinden wird, und wird das Weib ein Fluch sein unter ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ist aber ein solch Weib nicht verunreiniget; sondern rein; so wird\'s, ihr nicht schaden, da(S sie kann schwangerwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dies ist das Eifergesetz, wenn ein Weib sich von ihrem Manne verlauft und unrein wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Oder wenn einen Mann der Eifergeist entzündet, daß er urn sein Weib eifert, da(S er\'s stelle vor den HERRN, und der Priester an ihr tue alles nach diesem Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Und der Mann soil unschuldig sein an der Missetat; aber das Weib soil ihre Missetat tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Sage den Kindern Israel und sprich zu ihnen: Wenn ein Mann Oder Weib ein sonderlich Gelübde tut dem HERRN, sich zu enthalten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'der soil sich Weins und starken Getranks enthalten, Weinessig Oder starken Getranks Essig soil er auch nicht trinken, auch nichts, das aus Weinbeeren gemacht wird; er soil weder frische noch dürre Weinbeeren essen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'solange solch sein Gelubde wahret; auch soil er nichts essen, das man vom Weinstock macht, weder Weinkern noch Hülsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Solange die Zeit solches seines Gelübdes wahret, soil kein Schermesser uber sein Haupt fahren, bis daß die Zeit aus sei, die er dem HERRN gelobet hat; denn er ist heilig und soil das Haar auf seinem Haupt lassen frei wachsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Die ganze Zeit über, die er dem HERRN gelobet hat, soil er zu keinem Toten gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Er soil sich auch nicht verunreinigen an dem Tod seines Vaters, seiner Mutter, seines Bruders Oder seiner Schwester; denn das Gelubde seines Gottes ist auf seinem Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Und die ganze Zeit über seines Gelübdes soli er dem HERRN heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Und wo jemand vor ihm unversehens pldtzlich stirbt, da wird das Haupt seines Gelubdes verunreiniget; darum soil er sein Haupt bescheren am Tage seiner Reinigung, das ist, am siebenten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Und am achten Tage soil er zwo Turteltauben bringen, Oder zwo junge Tauben, zum Priester vor die Tür der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Und der Priester soil eine zum Sündopfer und die andere zum Brandopfer machen und ihn versohnen, daß ersich an einem Toten versündiget hat, und also sein Haupt desselben Tages heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'daß er dem HERRN die Zeit seines Gelubdes aushalte. Und soil ein jahrig Lamm bringen zum Schuidopfer. Aber die vorigen Tage sollen umsonst sein, darum daü sein Gelubde verunreiniget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Dies ist das Gesetz des Verlobten: Wenn die Zeit seines Gelubdes aus ist, so soli man ihn bringen vor die Tür der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Und ersoll bringen sein Opfer dem HERRN, ein jahrig Lamm ohne Wandel zum Brandopfer und ein jahrig Schaf ohne Wandel zum Sündopfer und einen Widderohne Wandel zum Dankopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'und einen Korb mit ungesauerten Kuchen von Semmelmehl, mit 01 gemenget, und ungesauerte Fladen, mit 01 bestrichen, und ihre Speisopfer und Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester soil\'s vor den HERRN bringen und soil sein Sündopfer und sein Brandopfer machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Und den Widder soil er zum Dankopfer machen dem HERRN samt dem Korbe mit dem ungesauerten Brat; und soil auch sein Speisopfer und sein Trankopfer machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Und soil dem Verlobten das Haupt seines Gelubdes bescheren vor der Tur der Hütte des Stifts; und soli das Haupthaar seines Gelubdes nehmen und aufs Feuer werfen, das unter dem Dankopfer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Und soil den gekochten Bug nehmen von dem Widder und einen ungesauerten Kuchen aus dem Korbe und einen ungesauerten Fladen und soil\'s dem Verlobten auf seine Hande legen, nachdem ersein Gelubde abgeschoren hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'und soil\'s vor dem FIERRN weben. Das ist heilig dem Priester samt der Webebrust und der Hebeschulter. Danach mag der Verlobte Wein trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz des Verlobten, der sein Opfer dem HERRN gelobet, von wegen seines Gelubdes, aulier dem, was er sonst vermag; wie er gelobet hat, soli er tun nach dem Gesetz seines Gelubdes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Sage Aaron und seinen Sohnen und sprich: Also sollt ihr sagen zu den Kindern Israel, wenn ihr sie segnet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Der HERR segne dich und behüte dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Der HERR lasse sein Angesicht leuchten uber dir und sei dir gnadig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Der HERR hebe sein Angesicht uber dich und gebe dir Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Denn ihr sollt meinen Namen auf die Kinder Israel legen, dafi ich sie segne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Und da Mose die Wohnung aufgerichtet hatte und sie gesalbet und geheiliget mit all ihrem Gerate, dazu auch den Altar mit all seinem Gerate gesalbet und geheiliget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da opferten die Fursten Israels, die Haupter waren in ihrer Vater Hausern; denn sie waren die Obersten unter den Stammen und stunden obenan unter denen, die gezahlet waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Und sie brachten ihre Opfer vor den HERRN: sechs bedeckte Wagen und zwolf Rinder, je einen Wagen fur zween Fursten, und einen Ochsen fur einen, und brachten sie vor die Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Und der HERR sprach zu Mose:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm\'s von ihnen, daß es diene zum Dienst in der Hütte des Stifts, und gib\'s den Leviten, einem jeglichen nach seinem Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da nahm Mose die Wagen und Rinder und gab sie den Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zween Wagen und vier Rinder gab er den Kindern Gerson nach ihrem Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Und vier Wagen und acht Ochsen gab er den Kindern Merari nach ihrem Amt unter der Hand Ithamars, Aarons, des Priesters, Sohns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Den Kindern Kahath aber gab er nichts, darum daß sie ein heilig Amt auf ihnen hatten und auf ihren Achseln tragen muliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Und die Fursten opferten zur Einweihung des Altars an dem Tage, da er geweihet ward, und opferten ihre Gabe vor dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Und der HERR sprach zu Mose: Laü einen jeglichen Fursten an seinem Tage sein Opfer bringen zur Einweihung des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Am ersten Tage opferte seine Gabe Nahesson, der Sohn Amminadabs, des Stamms Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Und seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des Heiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'dazu einen guldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'einen Ziegenbock zum Sundopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'und zum Dankopfer zwei Rinder, funf Widder, funf Bocke und funf jahrige Lammer. Das ist die Gabe Nahessons, des Sohns Amminadabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am andern Tage opferte Nethaneel, der Sohn Zuars, der Furst Isaschars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des Heiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'dazu einen guldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'und zum Dankopfer zwei Rinder, funf Widder, funf Bocke und funf jahrige Lammer. Das ist die Gabe Nethaneels, des Sohns Zuars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage der Furst der Kinder Sebulon, Eliab, der Sohn Helons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des Heiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'einen guldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'einen Farren aus den Rindern, einen Widder; ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'und zum Dankopfer zwei Rinder, funf Widder, funf Bocke und funf jahrige Lammer. Das ist die Gabe Eliabs, des Sohns Helons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage der Furst der Kinder Ruhen, Elizur, der Sohn Sedeurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des Heiligtums, beide voll Semmelmehls, mit Ol gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'einen güldenen Loffel, zehn Sekel Goldeswert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'einen Ziegenbock zum Sündopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'und zum Dankopfer zwei Rinder, funf Widder, fünf Bocke und funf jahrige Lammer. Das ist die Gabe Elizurs, des Sohns Sedeurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage der Furst der Kinder Simeon, Selumiel, der Sohn Zuri-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'einen güldenen Loffel, zehn Sekel Goldeswert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'einen Farren ans den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'einen Ziegenbock zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke und fünf jahrige Lammer. Das ist die Gabe Selumiels, des Sohns Zuri-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Am sechsten Tage der Fürst der Kinder Gad, Eliasaph, der Sohn Deguels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Seine Gabe war eine silberne Schussel, hundertunddreißig Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'einen güldenen Loffel, zehn Sekel Goldeswert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'einen Ziegenbock zum Sündopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Eliasaphs, des Sohns Deguels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Am siebenten Tage der Fürst der Kinder Ephraim, Elisama, der Sohn Ammihuds.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Seine Gabe war eine silberne Schussel, hundertunddreißig Sekel wert, eine silberne Schale, siebenzig Sekel wert, nachdem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'einen güldenen Loffel, zehn Sekel Goldeswert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'einen Ziegenbock zum Sündopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Elisamas, des Sohns Ammihuds.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Am achten Tage der Fürst der Kinder Manasse, Gamliel, der Sohn Pedazurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Seine Gabe war eine silberne Schussel, hundertunddreißig Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'einen güldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Gamliels, des Sohns Pedazurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage der Furst der Kinder Benjamin, Abidan, der Sohn Gideonis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seine Gabe war eine silberne Schüssel, hundertunddreifüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'einen güldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Abidans, des Sohns Gideonis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Am zehnten Tage der Fürst der Kinder Dan, Ahi- Eser, der Sohn Ammi-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Seine Gabe war eine silberne Schüssel, hundertunddreifüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'einen güldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'und zum Dankopfer zwei Rinder funf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Ahi- Esers, des Sohns Ammi-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Am elften Tage der Fürst der Kinder Asser, Pagiel, der Sohn Ochrans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seine Gabe war eine silberne Schüssel, hundertunddreilüg Sekel wert, eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des FHeiligtums, beide voll Semmelmehls, mit Ol gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'einen güldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'und zum Dankopfer zwei Rinder, fünf Widder, fünf Bocke, fünf jahrige Lammer. Das ist die Gabe Pagiels, des Sohns Ochrans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Am zwolften Tage der Fürst der Kinder Naphthali, Ahira, der Sohn Enans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Seine Gabe war eine silberne Schussel, hundertunddreilüg Sekel wert; eine silberne Schale, siebenzig Sekel wert, nach dem Sekel des Heiligtums, beide voll Semmelmehls, mit 01 gemenget, zum Speisopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'einen guldenen Loffel, zehn Sekel Goldes wert, voll Rauchwerks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'einen Farren aus den Rindern, einen Widder, ein jahrig Lamm zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'einen Ziegenbock zum Sundopfer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'und zum, Dankopfer zwei Rinder, fünf Widder, fünf Bocke, funf jahrige Lammer. Das ist die Gabe Ahiras, des Sohns Enans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Das ist die Einweihung des Altars zur Zeit, da er geweihetward, dazu die Fürsten Israels opferten diese zwolf silberne Schusseln, zwolf silberne Schalen, zwolf güldene Loffel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'also dafi je eine Schussel hundertunddreilüg Sekel Silbers und je eine Schale siebenzig Sekel hatte, daß die Summa alles Silbers am Gefalie trug zweitausendvierhundert Sekel, nach dem Sekel des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Und der zwolf guldenen Loffel voll Rauchwerks hatte je einer zehn Sekel, nach dem Sekel des Heiligtums, dafi die Summa Goldes an den Loffeln trug hundertundzwanzig Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Die Summa der Rinder zum Brandopfer war zwolf Farren, zwolf Widder, zwolf jahrige Lammer samt ihren Speisopfern und zwolf Ziegenbocke zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Und die Summa der Rinder zum Dankopfer war vierundzwanzig Farren, sechzig Widder, sechzig Bocke, sechzig jahrige Lammer. Das ist die Einweihung des Altars, da er geweihet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Und wenn Mose in die Hütte des Stifts ging, daß mit ihm geredet wurde, so horete er die Stimme mit ihm reden von dem Gnadenstuhl, der auf der Lade des Zeugnisses war zwischen den zweien Cherubim; von dannen ward mit ihm geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Rede mit Aaron und sprich zu ihm: Wenn du die Lampen aufsetzest, sollst du sie also setzen, daß sie alle sieben vorwarts dem Leuchter scheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Und Aaron tat also. Und setzte die Lampen auf, vorwarts dem Leuchter zu scheinen, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Der Leuchter aber war dicht Gold, beide sein Schaft und seine Blumen; nach dem Gesicht, das der HERR Mose gezeiget hatte, also machte er den Leuchter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Nimm die Leviten aus den Kindern Israel und reinige sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Also sollst du aber mit ihnen tun, daß du sie reinigest: Du sollst Sündwasser auf sie sprengen, und sollen alle ihre Haare rein abscheren und ihre Kleider waschen, so sind sie rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Dann sollen sie nehmen einen jungen Farren und sein Speisopfer, Semmelmehl, mit 01 gemenget, und einen anderen jungen Farren sollst du zum Sundopfer nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Und sollst die Leviten vor die Hütte des Stifts bringen und die ganze Gemeine der Kinder Israel versammeln');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'und die Leviten vor den HERRN bringen; und die Kinder Israel sollen ihre Hande auf die Leviten legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Und Aaron soli die Leviten vor dem HERRN weben von den Kindern Israel, auf daß sie dienen mogen an dem Amt des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Und die Leviten sollen ihre Hande aufs Haupt der Farren legen; und einer soli zum Sundopfer, der andere zum Brandopfer dem HERRN gemacht werden, die Leviten zu versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Und sollst die Leviten vor Aaron und seine Sohne stellen und vor dem HERRN weben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Und sollst sie also sondern von den Kindern Israel, dafi sie mein seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Danach sollen sie hineingehen, dafi sie dienen in der Hütte des Stifts. Also sollst du sie reinigen und weben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Denn sie sind mein Geschenk von den Kindern Israel und habe sie mir genommen fur alles, das seine Mutter bricht, namlich fur die Erstgeburt alter Kinder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Denn alle Erstgeburt unter den Kindern Israel ist mein, beide der Menschen und des Viehes, seit der Zeit ich alle Erstgeburt in Agyptenland schlug, und heiligte sie mir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'und nahm die Leviten an fur alle Erstgeburt unter den Kindern Israel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'und gab sie zum Geschenk Aaron und seinen Sohnen aus den Kindern Israel, daß sie dienen am Amt der Kinder Israel in der Hütte des Stifts, die Kinder Israel zu versohnen, auf dafi nicht unter den Kindern Israel sei eine Plage, so sie sich nahen wollten zum Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Und Mose mit Aaron samt der ganzen Gemeine der Kinder Israel taten mit den Leviten alles, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Und die Leviten entsundigten sich und wuschen ihre Kleider, und Aaron webte sie vor dem HERRN und versohnete sie, dafi sie rein wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Danach gingen sie hinein, daß sie ihr Amt taten in der Hütte des Stifts vor Aaron und seinen Sohnen. Wie der HERR Mose geboten hatte uber die Leviten, also taten sie mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Das ist\'s, das den Leviten gebührt: Von fünfundzwanzig Jahren und drüber taugen sie zum Heer und Dienst in der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Aber von dem fünfzigsten Jahr an sollen sie ledig sein vom Amt des Dienstes und sollen nicht mehr dienen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'sondern auf den Dienst ihrer Bruderwarten in der Hütte des Stiffs; des Amts aber sollen sie nicht pflegen. Also sollst du mit den Leviten tun, daß ein jeglicher seiner Hut warte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Und der HERR redete mit Mose in der Wuste Sinai im andern Jahr, nachdem sie aus Agyptenland gezogen waren, im ersten Monden, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Lal J die Kinder Israel Passah halten zu seiner Zeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'am vierzehnten Tage dieses Monden zwischen Abends; zu seiner Zeit sollen sie es halten nach aller seiner Satzung und Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Und Mose redete mit den Kindern Israel, daß sie das Passah hielten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Und sie hielten Passah am vierzehnten Tage des ersten Monden zwischen Abends in der Wuste Sinai; alles, wie der HERR Mose geboten hatte, so taten die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Da waren etliche Manner unrein uber einem toten Menschen, daß sie nicht konnten Passah halten des Tages. Die traten vor Mose und Aaron desselbigen Tages');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'und sprachen zu ihm: Wir sind unrein uber einem toten Menschen; warum sollen wir geringer sein, daß wir unsere Gabe dem HERRN nicht bringen müssen zu seiner Zeit unter den Kindern Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Mose sprach zu ihnen: Harret, ich will horen, was euch der HERR gebeut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Sage den Kindern Israel und sprich: Wenn jemand unrein uber einem Toten, Oder feme von euch uber Feld ist, Oder unter euren Freunden, der soil dennoch dem HERRN Passah halten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'aber doch im andern Monden, am vierzehnten Tage zwischen Abends, und soil es neben ungesauertem Brot und Salsen essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Und sollen nichts dran uberlassen, bis morgen, auch kein Bein dran zerbrechen, und sollen\'s nach aller Weise des Passah halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Wer aber rein und nicht uber Feld ist und lafit anstehen, das Passah zu halten, des Seele soil ausgerottet werden von seinem Volk, darum daß er seine Gabe dem HERRN nicht gebracht hat zu seiner Zeit; er soil seine Sunde tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Und wenn ein Fremdling bei euch wohnet, der soil auch dem HERRN Passah halten und soil\'s halten nach der Satzung und Recht des Passah. Diese Satzung soil euch gleich sein, dem Fremden wie des Landes Einheimischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Und des Tages, da die Wohnung aufgerichtet ward, bedeckte sie eine Wolke auf der Hütte des Zeugnisses; und des Abends bis an den Morgen war uber der Wohnung eine Gestalt des Feuers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Also geschah es immerdar, daß die Wolke sie bedeckte und des Nachts die Gestalt des Feuers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Und nachdem sich die Wolke aufhub von der Hütte, so zogen die Kinder Israel; und an welchem Ort die Wolke blieb, da lagerten sich die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Nach dem Wort des HERRN zogen die Kinder Israel und nach seinem Wort lagerten sie sich. Solange die Wolke auf der Wohnung blieb, solange lagen sie stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Und wenn die Wolke viel Tage verzog auf der Wohnung, sowarteten die Kinder Israel auf die Hut des HERRN und zogen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Und wenn\'s war, daß die Wolke auf der Wohnung war etliche Anzahl der Tage, so lagerten sie sich nach dem Wort des HERRN und zogen nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Wenn die Wolke da war von Abend bis an den Morgen und sich dann erhub, so zogen sie; Oder wenn sie sich des Tages Oder des Nachts erhub, so zogen sie auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Wenn sie aber zween Tage, Oder einen Monden, Oder etwa lange auf der Wohnung blieb, so lagen die Kinder Israel und zogen nicht; und wenn sie sich dann erhub, so zogen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Denn nach des HERRN Mund lagen sie und nach des HERRN Mund zogen sie, daß sie auf des HERRN Hutwarteten nach des HERRN Wortdurch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Mache dir zwo Trommeten von dichtem Silber, daß du ihrer brauchest, die Gemeine zu berufen, und wenn das Heer aufbrechen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Wenn man mit beiden schlecht blaset, soli sich zu dir versammeln die ganze Gemeine vor die Tur der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Wenn man nur mit einer schlecht blaset, so sollen sich zu dir versammeln die Fursten und die Obersten uber die Tausende in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Wenn ihr aber trommetet, so sollen die Lager aufbrechen, die gegen Morgen liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Und wenn ihrzum andernmal trommetet, so sollen die Lager aufbrechen, die gegen Mittag liegen. Denn wenn sie reisen sollen, so sollt ihr trommeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Wenn aber die Gemeine zu versammeln ist, sollt ihr schlecht blasen und nicht trommeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Es sollen abersolch Blasen mit den Trommeten die Sohne Aarons, die Priester, tun; und soil euer Recht sein ewiglich bei euren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Wenn ihr in einen Streit ziehet in eurem Lande wider eure Feinde, die euch beleidigen, so sollt ihr trommeten mit den Trommeten, daß euer gedacht werde vor dem HERRN, eurem Gott, und erloset werdet von euren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Desselbigengleichen, wenn ihr frohlich seid an euren Festen und in euren Neumonden, sollt ihr mit den Trommeten blasen uber eure Brandopfer und Dankopfer, daß es sei euch zum Gedachtnis vor Ill eurem Gott. Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Am zwanzigsten Tage im andern Monden des andern Jahres erhub sich die Wolke von der Wohnung des Zeugnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Und die Kinder Israel brachen auf und zogen aus der Wüste Sinai, und die Wolke blieb in der Wfiste Paran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Es brachen aber auf die ersten nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Namlich das Panierdes Lagers der Kinder Juda zog am ersten mit ihrem Heer; und uber ihr Heer war Nahesson, der Sohn Amminadabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Und uber das Heer des Stamms der Kinder Isaschar war Nethaneel, der Sohn Zuars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Und uber das Heer des Stamms der Kinder Sebulon war Eliab, der Sohn Helons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Da zerlegte man die Wohnung, und zogen die Kinder Gerson und Merari und trugen die Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Danach zog das Panierdes Lagers Ruben mit ihrem Heer; und fiber ihr Heer war Elizur, der Sohn Sedeurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Und fiber das Heer des Stamms der Kinder Simeon war Selumiel, der Sohn Zuri-Saddais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Und Eliasaph, der Sohn Deguels, fiber das Heer des Stamms der Kinder Gad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Da zogen auch die Kahathiten und trugen das Heiligtum; und jene richteten die Wohnung auf, bis diese hernach kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Danach zog das Panier des Lagers der Kinder Ephraim mit ihrem Heer; und fiber ihr Heer war Elisama der Sohn Ammihuds.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Und Gamliel, der Sohn Pedazurs, fiber das Heer des Stamms der Kinder Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Und Abidan, der Sohn Gideonis, fiber das Heer des Stamms der Kinder Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Danach zog das Panier des Lagers der Kinder Dan mit ihrem Heer; und so waren die Lager alle auf. Und Ahi-Eser, der Sohn Ammi-Saddais, war fiber ihr Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Und Pagiel, der Sohn Ochrans, fiber das Heer des Stamms der Kinder Asser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Und Ahira, der Sohn Enans, fiber das Heer des Stamms der Kinder Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'So zogen die Kinder Israel mit ihrem Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Und Mose sprach zu seinem Schwager Hobab, dem Sohn Reguels, aus Midian: Wir ziehen dahin an die Statte, davon der HERR gesagt hat: Ich will sie euch geben; so komm nun mit uns, wollen wir das Beste bei dir tun denn der HERR hat Israel Gutes zugesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Er aber antwortete: Ich will nicht mit euch, sondern in mein Land zu meiner Freundschaft ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Er sprach: Lieber, verlafi uns nicht, denn du weifiest, wo wir in der Wfiste uns lagern sollen, und sollst unser Auge sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Und wenn du mit uns zeuchst: was der HERR Gutes an uns tut, das wollen wir an dir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Also zogen sie von dem Berge des HERRN drei Tagreisen, und die Lade des Bundes des HERRN zog vor ihnen her die drei Tagreisen, ihnen zu weisen, wo sie ruhen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Und die Wolke des HERRN war des Tages fiber ihnen; wenn sie aus dem Lager zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Und wenn die Lade zog, so sprach Mose: HERR, stehe auf, la($ deine Feinde zerstreuet, und die dich hassen, flfichtig werden vor dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Und wenn sie ruhete, so sprach er: Komm wieder, HERR, zu der Menge der Tausende Israels!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Und da sich das Volk ungeduldig machte, gefiel es fibel vor den Ohren des HERRN. Und als es der HERR horete, ergrimmete sein Zorn und zfindete das Feuer des HERRN unter ihnen an, das verzehrete die auliersten Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Da schrie das Volk zu Mose; und Mose bat den HERRN, da verschwand das Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Und man hieft die Statte Tabeera, darum daß sich unter ihnen des HERRN Feuer angezfindet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Denn das Pobelvolk unter ihnen war Ifistern worden und salien und weineten samt den Kindern Israel und sprachen: Wer will uns Fleisch zu essen geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wir gedenken der Fische, die wir in Agypten umsonst alien, und der Kfirbisse, Pfeben, Lauch, Zwiebeln und Knoblauch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Nun aber ist unsere Seele matt; denn unsere Augen sehen nichts denn das Man.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Es war aber Man wie Koriandersamen und anzusehen wie Bedellion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Und das Volk lief hin und her und sammelte und stiel? es mit Mfihlen und zerrieb\'s in Morsern und kochte es in Topfen und machte ihm Aschenkuchen draus; und es hatte einen Geschmack wie ein Olkuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Und wenn des Nachts der T au fiber die Lager fiel, so fiel das Man mit drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Da nun Mose das Volk horete weinen unter ihren Geschlechtern, einen jeglichen in seiner Hfitte Tfir, da ergrimmete der Zorn des HERRN sehr, und Mose ward auch bange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Und Mose sprach zu dem HERRN: Warum bekfimmerst du deinen Knecht, und warum finde ich nicht Gnade vor deinen Augen, daß du die Last dieses ganzen Volks auf mich legest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Hab ich nun alles Volk empfangen Oder geboren, daß du zu mir sagen magst: Trag es in deinen Armen (wie eine Amme ein Kind tragt) in das Land, das du ihren Vatern geschworen hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Woher soil ich Fleisch nehmen, daß ich all diesem Volk gebe? Sie weinen vor mir und sprechen: Gib uns Fleisch, daß wir essen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ich vermag das Volk nicht allein alles ertragen, denn es ist mir zu schwer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Und willstdu also mit mir tun, erwfirge mich lieber, habe ich anders Gnade vor deinen Augen funden, daß ich nicht mein Unglück so sehen müsse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Und der HERR sprach zu Mose: Sammle mir siebenzig Manner unter den Altesten Israels, die du weilit, daß die Altesten im Volk und seine Amtleute sind, und nimm sie vor die Hütte des Stifts und stelle sie daselbst vor dich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'so will ich herniederkommen und mit dir daselbst reden und deines Geistes, der auf dir ist, nehmen und auf sie legen, daß sie mit dir die Last des Volks tragen, daß du nicht allein tragest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Und zum Volk sollst du sagen: Heiliget euch auf morgen, daß ihr Fleisch esset! Denn euer Weinen ist vor die Ohren des HERRN kommen, die ihr sprecht: Wer gibt uns Fleisch zu essen, denn es ging uns wohl in Agypten? Darum wird euch der HERR Fleisch geben, daß ihr esset,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'nicht einen Tag, nicht zween, nicht fünf, nicht zehn, nicht zwanzig Tage lang,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'sondern einen Monden lang, bis daß es euch zur Nase ausgehe, und euch ein Ekel sei, darum daß ihr den HERRN verworfen habt, der unter euch ist, und vor ihm geweinet und gesagt: Warum sind wir aus Agypten gegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Und Mose sprach: Sechshunderttausend Mann Fufivolks ist des, darunter ich bin, und du sprichst: Ich will euch Fleisch geben, daß ihr esset einen Monden lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Soil man Schafe und Rinder schlachten, daß ihnen genug sei? Oderwerden sich alle Fische des Meeres herzu versammeln, daß ihnen genug sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Der HERR aber sprach zu Mose: Ist denn die Hand des HERRN verkürzt? Aber du sollst jetzt sehen, ob meine Worte dir konnen etwas gelten, Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Und Mose ging heraus und sagte dem Volk des HERRN Wort und versammelte die siebenzig Manner unter den Altesten des Volks und stellete sie urn die Hütte her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Da kam der HERR hernieder in der Wolke und redete mit ihm und nahm des Geistes, der auf ihm war, und legte ihn auf die siebenzig altesten Manner. Und da der Geist auf ihnen ruhete, weissagten sie und horeten nicht auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Es waren aber noch zween Manner im Lager geblieben, dereine hieli Eldad, derandere Medad, und der Geist ruhete auf ihnen; denn sie waren auch angeschrieben und doch nicht hinausgegangen zu der Hütte, und sie weissagten im Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Da lief ein Knabe hin und sagte es Mose an und sprach: Eldad und Medad weissagen im Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Da antwortete Josua, der Sohn Nuns Moses Diener, den er erwahlet hatte und sprach: Mein Herr Mose, wehre ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Aber Mose sprach zu ihm: Bist du der Eiferer fur mich? Wollte Gott, dad alle das Volk des HERRN weissagete, und der HERR seinen Geist Liber sie gabel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Also sammelte sich Mose zum Lager und die Altesten Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Da fuhr aus der Wind von dem HERRN und lieli Wachteln kommen vom Meer und streuete sie Liber das Lager, hie eine Tagreise lang, da eine Tagreise lang urn das Lager her, zwo Ellen hoch über der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Da machte sich das Volk auf denselben ganzen Tag und die ganze Nacht und den andern ganzen Tag und sammelten Wachteln, und welcher am wenigsten sammelte, der sammelte zehn Homer, und hangete sie auf urn das Lager her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Da aber das Fleisch noch unter ihren Zahnen war, und ehe es auf war, da ergrimmete der Zorn des HERRN unter dem Volk und schlug sie mit einer sehr groden Plage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Daher dieselbige Statte heidt Lustgraber, darum dad man daselbst begrub das lüsteme Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Von den Lustgrabern aber zog das Volk aus gen Hazeroth, und blieben zu Hazeroth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Und Mirjam und Aaron redeten wider Mose urn seines Weibes willen, der Mohrin, die er genommen hatte, darum dad er eine Mohrin zum Weibe genommen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'und sprachen: Redet denn der HERR allein durch Mose? Redet er nicht auch durch uns? Und der HERR horete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Aber Mose war ein sehr geplagter Mensch Liber alle Menschen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Und plotzlich sprach der HERR zu Mose und zu Aaron und zu Mirjam: Gehet heraus, ihr drei, zu der Hütte des Stifts! Und sie gingen alle drei heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Da kam der HERR hernieder in der Wolkensaule und trat in der Hütte Tür und rief Aaron und Mirjam; und die beiden gingen hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Und er sprach: Horet meine Worte! Istjemand unter euch ein Prophet des HERRN, dem will ich mich kundmachen in einem Gesicht, Oder will mit ihm reden in einem Traum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Aber nicht also mein Knecht Mose, der in meinem ganzen Hause treu ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Mündlich rede ich mit ihm, und er siehet den HERRN in seiner Gestalt, nicht durch dunkle Worte Oder Gieichnis. Warum habt ihr euch denn nicht gefurchtet, wider meinen Knecht Mose zu reden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Und der Zorn des HERRN ergrimmete Liber sie und wandte sich weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Dazu die Wolke wich auch von der Hütte. Und siehe, da war Mirjam aussatzig wie der Schnee. Und Aaron wandte sich zu Mirjam und wird gewahr, daß sie aussatzig ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'und sprach zu Mose: Ach, mein Herr, lali die SLinde nicht auf uns bleiben, damit wir narrisch getan und uns versündiget haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'daß diese nicht sei wie ein Totes, das von seiner Mutter Leib kommt; es hat schon die Halfte ihres Fleisches gefressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Mose aber schrie zu dem HERRN und sprach: Ach Gott, heile sie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Der HERR sprach zu Mose: Wenn ihr Vater ihr ins Angesicht gespeiet hatte, sollte sie nicht sieben Tage sich schamen? Laß sie verschließen sieben Tage außer dem Lager, danach laß sie wieder aufnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Also ward Mirjam sieben Tage verschlossen außer dem Lager. Und das Volk zog nicht fürder, bis Mirjam aufgenommen ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Danach zog das Volk von Hazeroth und lagerte sich in die Wüste Paran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Sende Manner aus, die das Land Kanaan erkunden, das ich den Kindern Israel geben will, aus jeglichem Stamm ihrer Vater einen vomehmlichen Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Mose, der sandte sie aus der Wuste Paran nach dem Wort des HERRN, die alle vomehmliche Manner waren unter den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Und hielien also: Sammua, der Sohn Zakurs, des Stamms Ruben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Saphat, der Sohn Horis, des Stamms Simeon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Kaleb, der Sohn Jephunnes, des Stamms Juda;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Igeal, der Sohn Josephs, des Stamms Isaschar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Hosea, der Sohn Nuns, des Stamms Ephraim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Palti, der Sohn Raphus, des Stamms Benjamin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Gadiel, der Sohn Sodis, des Stamms Sebulon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Gaddi, der Sohn Susis, des Stamms Joseph von Manasse;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Ammiel, der Sohn Gemallis, des Stamms Dan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Sethur, der Sohn Michaels, des Stamms Asser;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Nahebi, der Sohn Vaphsis, des Stamms Naphthali;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Guel, der Sohn Machis, des Stamms Gad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Das sind die Namen der Manner, die Mose aussandte, zu erkunden das Land. Aber den Hosea, den Sohn Nuns, nannte Mose Josua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Da sie nun Mose sandte, das Land Kanaan zu erkunden, sprach er zu ihnen: Ziehet hinauf an den Mittag und gehet auf das Gebirge;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'und besehet das Land, wie es ist, und das Volk, das drinnen wohnet, ob\'s stark Oder schwach, wenig Oder viel ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'und was fur ein Land ist, darinnen sie wohnen, ob\'s gut Oder bose sei; und was fur Stadte sind, darinnen sie wohnen, ob sie in Gezelten Oder Festungen wohnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'und was fur Land sei, ob\'s fett Oder mager sei, und ob Baume drinnen sind, Oder nicht. Seid getrost und nehmet der Fruchte des Landes. Es war aber eben urn die Zeit der ersten Weintrauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Sie gingen hinauf und erkundeten das Land von der Wüste Zin bis gen Rehob, da man gen Hamath gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Sie gingen auch hinauf gegen den Mittag und kamen bis gen Hebron; da war Ahiman, Sesai und Thalmai, die Kinder Enaks Hebron aber war sieben Jahre gebauet vor Zoan in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Und sie kamen bis an Bach Eskol und schnitten daselbst eine Rebe ab mit einer Weintraube und ließen sie zween auf einem Stecken tragen, dazu auch Granatapfel und Feigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Der Ort heißet Bach Eskol urn der T raube willen, die die Kinder Israel daselbst abschnitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Und sie kehreten urn, da sie das Land erkundet hatten, nach vierzig Tagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'gingen hin und kamen zu Mose und Aaron und zu der ganzen Gemeine der Kinder Israel in die Wüste Paran gen Kades; und sagten ihnen wieder und der ganzen Gemeine, wie es stünde, und ließen sie die Früchte des Landes sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Und erzahleten ihnen und sprachen: Wir sind ins Land kommen, dahin ihr uns sandtet, da Milch und Honig innen fleußt, und dies ist ihre Frucht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'ohne daß stark Volk drinnen wohnet, und sehr große und feste Stadte sind; und sahen auch Enaks Kinder daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'So wohnen die Amalekiter im Lande gegen Mittag, die Hethiter und Jebusiter und Amoriter wohnen auf dem Gebirge, die Kanaaniter aber wohnen am Meer und urn den Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Kaleb aber stillete das Volk gegen Mose und sprach: Laßt uns hinaufziehen und das Land einnehmen; denn wir mogen es überwaltigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Aber die Manner, die mit ihm waren hinaufgezogen, sprachen: Wirvermogen nicht hinaufzuziehen gegen das Volk, denn sie sind uns zu stark');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'und machten dem Lande, das sie erkundet hatten, ein bos Geschrei unter den Kindern Israel und sprachen: Das Land, dadurch wirgegangen sind zu erkunden, frisset seine Einwohner; und alles Volk, das wir drinnen sahen, sind Leute von großer Lange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Wir sahen auch Riesen daselbst, Enaks Kinder von den Riesen; und wir waren vor unsern Augen als die Heuschrecken, und also waren wir auch vor ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Da fuhrdie ganze Gemeine auf und schrie, und das Volk weinete die Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Und alle Kinder Israel murreten wider Mose und Aaron; und die ganze Gemeine sprach zu ihnen: Ach, daß wir in Agyptenland gestorben waren, Oder noch sturben in dieser Wüste!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'fuhret uns der HERR in dies Land, daß unsere Weiber durchs Schwert fallen und unsere Kinder ein Raub werden? Ist\'s nicht besser, wir ziehen wieder nach Agypten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Und einer sprach zu dem andern: Laßt uns einen Hauptmann aufwerfen und wieder nach Agypten ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Mose aber und Aaron fielen auf ihr Angesicht vor der ganzen Versammlung der Gemeine der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Und Josua, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, die auch das Land erkundet hatten, zerrissen ihre Kleider');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'und sprachen zu der ganzen Gemeine der Kinder Israel: Das Land, das wir durchwandelt haben, zu erkunden, istsehrgut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Wenn der HERR uns gnadig ist, so wird er uns in dasselbe Land bringen und uns geben, das ein Land ist, da Milch und Honig innen fleußt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Fallet nicht ab vom HERRN und furchtet euch vor dem Volk dieses Landes nicht; denn wir wollen sie wie Brot fressen. Es ist ihr Schutz von ihnen gewichen; der HERR aber ist mit uns. Furchtet euch nicht vor ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Da sprach das ganze Volk, man sollte sie steinigen. Da erschien die Herrlichkeit des HERRN in der Hütte des Stifts alien Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Und der HERR sprach zu Mose: Wie lange lasted mich das Volk, und wie lange wollen sie nicht an mich glauben durch allerlei Zeichen, die ich unter ihnen getan habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'So will ich sie mit Pestilenz schlagen und vertilgen und dich zum grofiern und machtigem Volk machen, denn dies ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Mose aber sprach zu dem HERRN: Sowerden es die Agypter horen; denn du hast dies Volk mit deiner Kraft mitten aus ihnen gefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Und man wird sagen zu den Einwohnern dieses Landes, die da gehoret haben, daß du, HERR, unter diesem Volk seiest, daß du von Angesicht gesehen werdest, und deine Wolke stehe uber ihnen, und du, HERR, gehest vor ihnen her in der Wolkensaule des Tages und Feuersaule des Nachts;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'und wurdest dies Volk toten wie einen Mann, so würden die Heiden sagen, die solch Geschrei von dir horeten, und sprechen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Der HERR konnte mitnichten das Volk ins Land bringen, das er ihnen geschworen hatte, darum hat er sie geschlachtet in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'So laß nun die Kraft des HERRN groß werden, wie du gesagt hast, und gesprochen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Der HERR istgeduldig und von großer Barmherzigkeit und vergibt Missetat und Ubertretung und laßt niemand ungestraft, sondern heimsucht die Missetat der Vater uber die Kinder ins dritte und vierte Glied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'So sei nun gnadig der Missetat dieses Volks nach deiner großen Barmherzigkeit, wie du auch vergeben hast diesem Volk aus Agypten bis hieher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Und der HERR sprach: Ich hab\'s vergeben, wie du gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Aber so wahr als ich lebe, so soil aile Welt der Herrlichkeit des HERRN voll werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Denn aile die Manner, die meine Herrlichkeit und meine Zeichen gesehen haben, die ich getan habe in Agypten und in der Wuste, und mich nun zehnmal versucht und meiner Stimme nicht gehorchet haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'deren soil keiner das Land sehen, das ich ihren Vatern geschworen habe; auch keiner soil es sehen; der mich verlastert hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Aber meinen Knecht Kaleb, darum daß ein anderer Geist mit ihm ist und hat mir treulich nachgefolget, den will ich in das Land bringen, darein er kommen ist, und sein Same soil es einnehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'dazu die Amalekiter und Kanaaniter, die im Grunde wohnen. Morgen wendet euch und ziehet in die Wuste auf dem Wege zum Schilfmeer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Wie lange murret diese bose Gemeine wider mich? Denn ich habe das Murren der Kinder Israel, das, sie wider mich gemurret haben, gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Darum sprich zu ihnen: So wahr ich lebe, spricht der HERR, ich will euch tun, wie ihr vor meinen Ohren gesagt habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Eure Leiber sollen in dieser Wuste verfallen; und aile, die ihr gezahlet seid von zwanzig Jahren und druber, die ihr wider mich gemurret habt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'sollt nicht in das Land kommen, daruber ich meine Hand gehoben habe, daß ich euch drinnen wohnen ließe, ohne Kaleb, der Sohn Jephunnes, und Josua, der Sohn Nuns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Eure Kinder, davon ihr sagtet: Sie werden ein Raub sein, die will ich hineinbringen, daß sie erkennen sollen das Land, das ihr verwerfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Aber ihr samt euren Leibern sollt in dieser Wuste verfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Und eure Kinder sollen Hirten sein in der Wuste vierzig Jahre und eure Hurerei tragen, bis daß eure Leiber aile werden in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Nach der Zahl der vierzig Tage, darin ihr das Land erkundet habet, je ein Tag soil ein Jahr gelten, daß sie vierzig Jahre eure Missetat tragen, daß ihr inne werdet, was es sei, wenn ich die Hand abziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ich, der HERR, hab\'s gesagt, das will ich auch tun alter dieser bosen Gemeine, die sich wider mich emporet hat. In dieser Wuste sollen sie aile werden und daselbst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Also starben durch die Plage vor dem HERRN aile die Manner, die Mose gesandt hatte, das Land zu erkunden, und wiederkommen waren und dawider murren machten die ganze Gemeine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'damit daß sie dem Lande ein Geschrei machten, daß es bose ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Aber Josua, der Sohn Nuns, und Kaleb, der Sohn Jephunnes, blieben lebendig aus den Mannern, die gegangen waren, das Land zu erkunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Und Mose redete diese Worte zu alien Kindern Israel. Da trauerte das Volk sehr,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'und machten sich des Morgens fruhe auf und zogen auf die Hohe des Gebirges und sprachen: Hie sind wir und wollen hinaufziehen an die Statte, davon der HERR gesagt hat; denn wir haben gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mose aber sprach: Warum ubergehet ihr also das Wort des HERRN? Es wird euch nicht gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ziehet nicht hinauf, denn der HERR ist nicht unter euch; daß ihr nicht geschiagen werdet vor euren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Denn die Amalekiter und Kanaaniter sind vor euch daselbst, und ihr werdet durchs Schwert fallen, darum daß ihr euch vom HERRN gekehret habt; und der HERR wird nicht mit euch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Aber sie waren storrig, hinaufzuziehen auf die Hohe des Gebirges. Aber die Lade des Bundes des HERRN und Mose kamen nicht aus dem Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Da kamen die Amalekiter und Kanaaniter, die auf dem Gebirge wohneten, herab, und schlugen und zerschmissen sie bis gen Horma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr ins Land eurer Wohnung kommt, das ich euch geben werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'und wollt dem HERRN Opfer tun, es sei ein Brandopfer Oder ein Opfer zum besondern Gelubde, Oder ein freiwillig Opfer, Oder euer Festopfer, auf daß ihr dem HERRN einen sußen Geruch machet von Rindern Oder von Schafen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'wer nun seine Gabe dem HERRN opfern will, der soil das Speisopfer tun, einen Zehnten Semmelmehls, gemenget mit 01, eines vierten Teils vom Hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'und Wein zum Trankopfer, auch eines vierten Teils vom Hin, zum Brandopfer, Oder sonst zum Opfer, da ein Lamm geopfert wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Da aber ein Widder geopfert wird, sollstdu das Speisopfer machen zween Zehnten Semmelmehls, mit 01 gemenget, eines dritten Teils vom Hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'und Wein zum Trankopfer, auch des dritten Teils vom Hin. Das sollst du dem HERRN zum sußen Geruch opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Willstdu aber ein Rind zum Brandopfer Oder zum besondern Gelubdopfer Oder zum Dankopfer dem HERRN machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'so sollst du zu dem Rinde ein Speisopfer tun, drei Zehnten Semmelmehls, gemenget mit 01, eines halben Hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'und Wein zum Trankopfer, auch ein halb Hin. Das ist ein Opfer dem HERRN zum sußen Geruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Also sollst du tun mit einem Ochsen, mit einem Widder, mit einem Schaf, von Lammern und Ziegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Danach die Zahl ist dieser Opfer, danach soil auch die Zahl der Speisopfer und Trankopfer sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Wer ein Einheimischer ist, der soil solches tun, dafi er dem HERRN opfere ein Opfer zum süßen Geruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Und ob ein Fremdling bei euch wohnet, Oder unter euch bei euren Freunden ist, und will dem HERRN ein Opfer zum sußen Geruch tun, der soil tun, wie sie tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Derganzen Gemeine sei eine Satzung, beide euch und den Fremdlingen. Eine ewige Satzung soil das sein euren Nachkommen, daß vor dem HERRN der Fremdling sei wie ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Ein Gesetz, ein Recht soil euch und dem Fremdling sein, der bei euch wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr ins Land kommt, darein ich euch bringen werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'daß ihresset des Brots im Lande, sollt ihr dem HERRN eine Hebe geben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'namlich eures Teiges Erstlinge sollt ihr einen Kuchen zur Hebe geben; wie die Hebe von der Scheune,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'also sollt ihr auch dem HERRN eures Teiges Erstlinge zur Hebe geben bei euren Nachkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Und wenn ihr durch Unwissenheit dieser Gebote irgend eins nicht tut, die der HERR zu Mose geredet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'und alles, was der HERR euch durch Mose geboten hat von dem Tage an, da er anting zu gebieten auf eure Nachkommen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'wenn nun die Gemeine etwas unwissend tate: so soil die ganze Gemeine einen jungen Farren aus den Rindern zum Brandopfer machen zum süßen Geruch dem HERRN, samt seinem Speisopfer und Trankopfer, wie es recht ist, und einen Ziegenbock zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Und der Priester soil also die ganze Gemeine der Kinder Israel versohnen, so wird\'s ihnen vergeben sein; denn es ist eine Unwissenheit. Und sie sollen bringen solche ihre Gabe zum Opfer dem HERRN und ihr Sundopfer vor den HERRN uber ihre Unwissenheit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'so wird\'s vergeben der ganzen Gemeine der Kinder Israel, dazu auch dem Fremdlinge, der unter euch wohnet, weil das ganze Volk ist in solcher Unwissenheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Wenn aber eine Seele durch Unwissenheit sundigen wird, die soil eine jahrige Ziege zum Sundopfer bringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'und der Priester soil versohnen solche unwissende Seele mit dem Sundopfer fur die Unwissenheit vor dem HERRN, daß er sie versohne; so wird\'s ihr vergeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Und es soil ein Gesetz sein, das ihr fur die Unwissenheit tun sollt, beide dem Einheimischen unter den Kindern Israel und dem Fremdlinge, der unter euch wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Wenn aber eine Seele aus Frevel etwas tut, es sei ein Einheimischer Oder Fremdling, der hat den HERRN geschmahet. Solche Seele soil ausgerottet werden aus ihrem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Denn sie hat des HERRN Wort verachtet und sein Gebot lassen fahren; sie soil schlecht ausgerottet werden; die Schuld sei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Als nun die Kinder Israel in der Wüste waren, fanden sie einen Mann Holz lesen am Sabbattage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Und die ihn drob funden hatten, da er Holz las, brachten ihn zu Mose und Aaron und vor die ganze Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Und sie legten ihn gefangen; denn es war nicht klar ausgedrückt, was man mit ihm tun sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Der HERR aber sprach zu Mose: Der Mann soil des Todes sterben, die ganze Gemeine soil ihn steinigen aufter dem Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Da führete die ganze Gemeine ihn hinaus vor das Lager und steinigten ihn, daß er starb, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Und der HERR sprach zu Mose:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Rede mit den Kindern Israel und sprich zu ihnen, daß sie ihnen Lapplein machen an den Fittichen ihrer Kleider unter alien euren Nachkommen und gelbe Schnurlein auf die Lapplein an die Fittiche tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Und sollen euch die Lapplein dazu dienen, daß ihr sie ansehet und gedenket alier Gebote des HERRN und tut sie, daß ihr nicht eures Herzens Dünken nach richtet, noch euren Augen nach huret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Darum sollt ihrgedenken und tun aile meine Gebote und heilig sein eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ich, der HERR, euer Gott, der euch aus Agyptenland gefuhret hat, daß ich euer Gott ware; ich, der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Und Korah, der Sohn Jezehars, des Sohns Kahaths, des Sohns Levis, samt Dathan und Abiram, den Sohnen Eliabs, und On, dem Sohne Peleths, den Sohnen Rubens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'die emporeten sich wider Mose, samt etlichen Mannern unter den Kindern Israel, zweihundertundfunfzig der Vornehmsten in der Gemeine, Ratsherren und ehrliche Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Und sie versammelten sich wider Mose und Aaron und sprachen zu ihnen: Ihr macht\'s zu viel! Denn die ganze Gemeine ist uberall heilig, und der HERR ist unter ihnen; warum erhebet ihr euch fiber die Gemeine des HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Da das Mose horete, fiel er auf sein Angesicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'und sprach zu Korah und zu seiner ganzen Rotte: Morgen wird der HERR kundtun, wer sein sei, wer heilig sei und ihm opfern soil; weichen er erwahlet, der soil ihm opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Das tut: Nehmet euch Pfannen, Korah und seine ganze Rotte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'und leget Feuer drein und tut Rauchwerk drauf vor dem HERRN morgen. Weichen der HERR erwahlet, der sei heilig. Ihr macht\'s zuviel, ihr Kinder Levis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Und Mose sprach zu Korah: Lieber, horet doch, ihr Kinder Levis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ist\'s euch zu wenig, daß euch der Gott Israels ausgesondert hat von der Gemeine Israel, daß ihr ihm opfern sollet, daß ihr dienet im Amt der Wohnung des HERRN und vor die Gemeine tretet, ihrzu dienen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Er hat dich und aile deine Bruder, die Kinder Levis, samt dir zu sich genommen; und ihr suchet nun auch das Priestertum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Du und deine ganze Rotte machet einen Aufruhr wider den HERRN. Was ist Aaron, daß ihr wider ihn murret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Und Mose schickte hin und lieft Dathan und Abiram rufen, die Sohne Eliabs. Sie aber sprachen: Wir kommen nicht hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ist\'s zu wenig, daß du uns aus dem Lande gefuhret hast, da Milch und Honig innen fleuftt, daß du uns totest in der Wuste? Du muftt auch noch uber uns herrschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Wie fein hast du uns gebracht in ein Land, da Milch und Honig innen fleuftt, und hast uns Acker und Weinberge zu Erbteil gegeben! Willst du den Leuten auch die Augen ausreiften? Wir kommen nicht hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Da ergrimmete Mose sehr und sprach zu dem HERRN: Wende dich nicht zu ihrem Speisopfer! Ich habe, nicht einen Esel von ihnen genommen und habe ihrer keinem nie kein Leid getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Und er sprach zu Korah: Du und deine ganze Rotte sollt morgen vor dem HERRN sein; du, sie auch und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Und ein jeglicher nehme seine Pfanne und lege Rauchwerk drauf, und tretet herzu vor den HERRN, ein jeglicher mit seiner Pfanne, das sind zweihundertundfunfzig Pfannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Und ein jeglicher nahm seine Pfanne und legte Feuer drein und tat Rauchwerk drauf und traten vor die Tur der Hutte des Stifts, und Mose und Aaron auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Und Korah versammelte wider sie die ganze Gemeine vor die Tur der Hutte des Stifts. Aber die Herrlichkeit des HERRN erschien vor der ganzen Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Scheidet euch von dieser Gemeine, daß ich sie plotzlich vertilge!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Sie fielen aber auf ihr Angesicht und sprachen: Ach Gott, der du bist ein Gott der Geister alles Fleisches, ob ein Mann gesundiget hat, willst du darum fiber die ganze Gemeine wuten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Sage der Gemeine und sprich: Weichet ringsherum von der Wohnung Korahs und Dathans und Abirams!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Und Mose stund auf und ging zu Dathan und Abiram, und die Altesten Israels folgten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Und redete mit der Gemeine und sprach: Weichet von den Hutten dieser gottlosen Menschen und ruhret nichts an, was ihr ist, daß ihr nicht vielleicht umkommet in irgend ihrer Sünden einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Und sie gingen herauf von der Wohnung Korahs, Dathans und Abirams. Dathan aber und Abiram gingen heraus, traten an die Tür ihrer Hütten mit ihren Weibern und Sohnen und Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Und Mose sprach: Dabei sollt ihr merken, daß mich der HERR gesandt hat, daß ich alle diese Werke tate, und nicht aus meinem Herzen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Werden sie sterben, wie alle Menschen sterben, Oder heimgesucht, wie alle Menschen heimgesucht werden, so hat mich der HERR nicht gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Wird aber der HERR etwas Neues schaffen, daß die Erde ihren Mund auftut und verschlinget sie mit allem, das sie haben, daß sie lebendig hinunter in die Holle fahren, so werdet ihr erkennen, daß diese Leute den HERRN gelastert haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Und als er diese Worte alle hatte ausgeredet, zerrift die Erde unter ihnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'und tat ihren Mund auf und verschlang sie mit ihren Hausern, mit alien Menschen, die bei Korah waren, und mit aller ihrer Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Und fuhren hinunter lebendig in die Holle mit allem, das sie hatten, und die Erde deckte sie zu, und kamen urn aus der Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Und ganz Israel, das urn sie her war, floh vor ihrem Geschrei; denn sie sprachen: Daft uns die Erde nicht auch verschlinge!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Dazu fuhr das Feuer aus von dem HERRN und fraft die zweihundertundfünfzig Manner, die das Rauchwerk opferten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Sage Eleasar, dem Sohn Aarons, des Priesters, daß er die Pfannen aufhebe aus dem Brande und streue das Feuer hin und her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Denn die Pfannen solcher Sunder sind geheiliget durch ihre Seele, daß man sie zu breiten Blechen schlage und den Altar damit behange; denn sie sind geopfert vor dem HERRN und geheiliget und sollen den Kindern Israel zum Zeichen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Und Eleasar, der Priester, nahm die ehernen Pfannen, die die Verbrannten geopfert hatten, und schlug sie zu Blechen, den Altar zu behangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'zum Gedachtnis der Kinder Israel, daß nicht jemand Fremdes sich herzumache, der nicht ist des Samens Aaron, zu opfern Rauchwerk vor dem HERRN, auf daß ihm nicht gehe wie Korah und seiner Rotte, wie der HERR ihm geredet hatte durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Des andern Morgens aber murrete die ganze Gemeine der Kinder Israel wider Mose und Aaron und sprachen: Ihr habt des HERRN Volk getotet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Und da sich die Gemeine versammelte wider Mose und Aaron, wandten sie sich zu der Hütte des Stiffs. Und siehe, da bedeckte es die Wolke, und die Herrlichkeit des HERRN erschien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Und Mose und Aaron gingen hinein zu der Hütte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Hebet euch aus dieser Gemeine; ich will sie plotzlich vertilgen. Und sie fielen auf ihr Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Und Mose sprach zu Aaron: Nimm die Pfanne und tue Feuer drein vom Altar und lege Rauchwerk drauf, und gehe eilend zu der Gemeine und versohne sie; denn das Wüten ist von dem HERRN ausgegangen, und die Plage ist angegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Und Aaron nahm, wie ihm Mose gesagt hatte, und lief mitten unter die Gemeine (und siehe, die Plage war angegangen unter dem Volk) und raucherte und versohnete das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Und stund zwischen den Toten und Lebendigen. Da ward der Plage gewehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 14, 'Derer aber, die an der Plage gestorben waren, war vierzehntausendundsiebenhundert, ohne die, so mit Korah starben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 15, 'Und Aaron kam wieder zu Mose vor die Tür der Hütte des Stifts, und der Piage ward gewehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 16, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 17, 'Sage den Kindern Israel und nimm von ihnen zwolf Stecken, von jeglichem Fürsten seines Vaters-Hauses einen, und schreibe eines jeglichen Namen auf seinen Stecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 18, 'Aber den Namen Aarons sollst du schreiben auf den Stecken Levis. Denn je fur ein Haupt ihrer Vater Hauses soil ein Stecken sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 19, 'Und lege sie in die Hütte des Stifts vor dem Zeugnis, da ich euch zeuge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 20, 'Und welchen ich erwahlen werde, des Stecken wird grünen, daß ich das Murren der Kinder Israel, das sie wider euch murren, stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 21, 'Mose redete mit den Kindern Israel; und alle ihre Fürsten gaben ihm zwolf Stecken, ein jeglicher Fürst einen Stecken, nach dem Hause ihrer Vater; und der Stecken Aarons war auch unter ihren Stecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 22, 'Und Mose legte die Stecken vor den HERRN in der Hütte des Zeugnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 23, 'Des Morgens aber, da Mose in die Hütte des Zeugnisses ging, fand er den Stecken Aarons, des Hauses Levi, grünen, und die Blüte aufgegangen und Mandeln tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 24, 'Und Mose trug die Stecken alle heraus von dem HERRN vor alle Kinder Israel, daß sie es sahen; und ein jeglicher nahm seinen Stecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 25, 'Der HERR sprach aberzu Mose: Trage den Stecken Aarons wieder vor das Zeugnis, daß er verwahret werde zum Zeichen den ungehorsamen Kindern, daß ihr Murren von mir aufhore, daß sie nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 26, 'Mose tat, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 27, 'Und die Kinder Israel sprachen zu Mose: Siehe, wir verderben und kommen um; wir werden alle vertilget und kommen um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 28, 'Wer sich nahet zu der Wohnung des HERRN, der stirbt. Sollen wir denn gar untergehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Und der HERR sprach zu Aaron: Du und deine Sohne und deines Vaters Haus mit dir sollt die Missetat des Heiligtums tragen; und du und deine Sohne mit dir sollt die Missetat eures Priestertums tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Aber deine Brüder des Stamms Levi, deines Vaters, sollst du zu dir nehmen, daß sie bei dir seien und dir dienen; du aber und deine Sohne mit dir vor der Hütte des Zeugnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Und sie sollen deines Dienstes und des Dienstes der ganzen Hütte warten. Doch zu dem Gerate des Heiligtums und zu dem Altar sollen sie sich nicht machen, daß nicht beide, sie und ihr, sterbet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'sondern sie sollen bei dirsein, daß sie des Dienstes warten an der Hütte des Stifts in allem Amt der Hütte. Und kein Fremder soil sich zu euch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'So wartet nun des Dienstes des Heiligtums und des Dienstes des Altars, daß fort nicht mehr ein Wüten komme fiber die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Denn siehe, ich habe die Leviten, eure Brüder, genommen aus den Kindern Israel und euch gegeben, dem HERRN zum Geschenk, daß sie des Amts pflegen an der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Du aber und deine Sohne mit dir sollt eures Priestertums warten, daß ihr dienet in allerlei Geschafte des Altars und inwendig hinter dem Vorhang; denn euer Priestertum gebe ich euch zum Amt, zum Geschenk. Wenn ein Fremder sich herzutut, der soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Und der HERR sagte zu Aaron: Siehe, ich habe dir gegeben meine Hebopfervon allem, das die Kinder Israel heiligen, für dein priesterlich Amt und deinen Sohnen zum ewigen Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Das sollst du haben von dem Allerheiligsten, das sie opfern: Alle ihre Gaben mit all ihrem Speisopfer und mit all ihrem Sündopfer und mit all ihrem Schuldopfer, das sie mir geben, das soil dir und deinen Sohnen das Allerheiligste sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Am allerheiligsten Ort sollst du es essen. Was mannlich ist, soil davon essen; denn es soil dir heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Ich habe auch das Hebopfer ihrer Gabe an alien Webeopfern der Kinder Israel dir und deinen Sohnen und deinen Tochtern gegeben samt dir zum ewigen Recht; wer rein ist in deinem Hause, soil davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alles beste 01 und alien besten Most und Korn ihrer Erstlinge, die sie dem HERRN geben, habe ich dir gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Die erste Frucht alles des, das in ihrem Lande ist, das sie dem HERRN bringen, soil dein sein; wer rein ist in deinem Hause, soli davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Alles Verbannete in Israel soil dein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Alles, das seine Mutter bricht unter allem Fleisch, das sie dem HERRN bringen, es sei Mensch Oder Vieh, soil dein sein; doch daß du die erste Menschenfrucht losen lassest und die erste Frucht eines unreinen Viehes auch Ibsen lassest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Sie sollen\'s aber Ibsen, wenn\'s eines Monden alt ist; und sollst es zu Ibsen geben um Geld, um fünf Sekel, nach dem Sekel des Heiligtums, der gilt zwanzig Gera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Aber die erste Frucht eines Ochsen Oder Lamms Oder Ziege sollst du nicht zu Ibsen geben, denn sie sind heilig; ihr Blut sollst du sprengen auf den Altar und ihr Fett sollst du anzunden zum Opfer des süften Geruchs dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ihr Fleisch soil dein sein, wie auch die Webebrust und die rechte Schulter dein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle Hebopfer, die die Kinder Israel heiligen dem HERRN, habe ich dir gegeben und deinen Sohnen und deinen Tochtern samt dir zum ewigen Recht. Das soli ein unverwesentlicher Bund sein ewig vor dem HERRN dir und deinem Samen samt dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Und der HERR sprach zu Aaron: Du sollst in ihrem Lande nichts besitzen, auch kein Teil unter ihnen haben; denn ich bin dein Teil und dein Erbgut unter den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Den Kindern aber Levis habe ich alle Zehnten gegeben in Israel zum Erbgut fur ihr Amt, das sie mir tun an der Hütte des Stifts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'daß hinfort die Kinder Israel nicht zur Hütte des Stifts sich tun, Sünde auf sich zu laden, und sterben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'sondern die Leviten sollen des Amts pflegen an der Hütte des Stifts, und sie sollen jener Missetat tragen zum ewigen Recht bei euren Nachkommen. Und sie sollen unter den Kindern Israel kein Erbgut besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Denn den Zehnten der Kinder Israel, den sie dem HERRN heben, habe ich den Leviten zum Erbgut gegeben; darum habe ich zu ihnen gesagt, daß sie unter den Kindern Israel kein Erbgut besitzen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Sage den Leviten und sprich zu ihnen: Wenn ihr den Zehnten nehmet von den Kindern Israel, den ich euch von ihnen gegeben habe zu eurem Erbgut, so sollt ihr davon ein Hebopfer dem HERRN tun, je den Zehnten von dem Zehnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Und sollt solch euer Hebopfer achten, als gabet ihr Korn aus der Scheune und Fulle aus der Kelter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Also sollt auch ihr das Hebopfer dem HERRN geben von alien euren Zehnten, die ihr nehmet von den Kindern Israel, daß ihr solches Hebopfer des HERRN dem Priester Aaron gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Von allem, das euch gegeben wird, sollt ihr dem HERRN allerlei Hebopfer geben, von allem Besten, das davon geheiliget wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Und sprich zu ihnen: Wenn ihr also das Beste davon hebet, so soil\'s den Leviten gerechnet werden wie ein Einkommen der Scheune und wie ein Einkommen der Kelter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Und moget es essen an alien Statten, ihr und eure Kinder; denn es ist euer Lohn fur euer Amt in der Hütte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'So werdet ihr nicht Sunde auf euch laden an demselben, wenn ihr das Beste davon hebet, und nicht entweihen das Geheiligte der Kinder Israel und nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Und der HERR redete mit Mose und Aaron und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Diese Weise soil ein Gesetz sein, das der HERR geboten hat und gesagt: Sage den Kindern Israel, daß sie zu dir fuhren eine rotliche Kuh ohne Wandel, an der kein Fehl sei, und auf die noch nie kein Joch kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Und gebet sie dem Priester Eleasar; der soil sie hinaus vor das Lager fuhren und daselbst vor ihm schlachten lassen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Und Eleasar, der Priester, soil ihres Bluts mit seinem Finger nehmen und stracks gegen die Hütte des Stifts sieben mal sprengen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'und die Kuh vor ihm verbrennen lassen, beide ihr Fell und ihr Fleisch, dazu ihr Blut samt ihrem Mist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Und der Priester soli Zedernholz und Ysop und rosinrote Wolle nehmen und auf die brennende Kuh werfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'und soil seine Kleider waschen und seinen Leib mit Wasser baden und danach ins Lager gehen und unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Und der sie verbrannt hat, soil auch seine Kleider mit Wasser waschen und seinen Leib in Wasser baden und unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Und ein reiner Mann soil die Asche von der Kuh aufraffen und sie schütten aulier dem Lager an eine reine Statte, dafi sie daselbst verwahret werde fur die Gemeine der Kinder Israel zum Sprengwasser; denn es ist ein Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Und derselbe, der die Asche der Kuh aufgeraffet hat, soil seine Kleider waschen und unrein sein bis an den Abend. Dies soil ein ewiges Recht sein den Kindern Israel und den Fremdlingen, die untereuch wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Wer nun irgend einen toten Menschen anruhret, der wird sieben Tage unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Der soil sich hiemit entsundigen am dritten Tage und am siebenten Tage, so wird er rein; und wo er sich nicht am dritten Tage und am siebenten Tage entsundiget, so wird er nicht rein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Wenn aberjemand irgend einen toten Menschen anruhret und sich nicht entsundigen wollte, der verunreiniget die Wohnung des HERRN, und solche Seele soli ausgerottet werden aus Israel. Darum daß das Sprengwasser nicht uber ihn gesprenget ist, so ist er unrein, solange er sich nicht davon reinigen lalit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Dies ist das Gesetz, wenn ein Mensch in der Hütte stirbt: Wer in die Hütte gehet; und alles, was in der Hütte ist, soil unrein sein sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Und alles offene Gerate, das keinen Deckel noch Band hat, ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Auch wer anruhret auf dem Felde einen Erschlagenen mit dem Schwert Oder einen Toten, eines Menschen Bein, Oder Grab, der ist unrein sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'So sollen sie nun fürden Unreinen nehmen der Asche dieses verbrannten Sündopfers und flietiend Wasser drauf tun in ein Gefali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Und ein reiner Mann soil Ysop nehmen und ins Wasser tunken und die Hütte besprengen und alle Gerate und alle Seelen, die drinnen sind; also auch den, der eines Toten Bein Oder Erschlagenen Oder Toten Oder Grab angerühret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Es soil aber der Reine den Unreinen am dritten Tage und am siebenten Tage besprengen und ihn am siebenten Tage entsundigen; und soil seine Kleider waschen und sich im Wasser baden, so wird er am Abend rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Welcher aber unrein sein wird und sich nicht entsundigen will, des Seele soil ausgerottet werden aus der Gemeine; denn er hat das Heiligtum des HERRN verunreiniget und ist mit Sprengwasser nicht besprenget; darum ist er unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Und dies soil ihnen ein ewiges Recht sein. Und der auch, der mit dem Sprengwasser gesprenget hat, soil seine Kleider waschen. Und wer das Sprengwasser anruhret, der soil unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Und alles, was er anruhret, wird unrein werden, und welche Seele er anruhren wird, soil unrein sein bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Und die Kinder Israel kamen mit der ganzen Gemeine in die Wüste Zin im ersten Monden, und das Volk lag zu Kades. Und Mirjam starb daselbst und ward daselbst begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Und die Gemeine hatte kein Wasser, und versammelten sich wider Mose und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Und das Volk haderte mit Mose und sprachen: Ach, daß wir umkommen waren, da unsere Brüder umkamen vor dem HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Warum habt ihr die Gemeine des HERRN in diese Wüste gebracht, daß wir hie sterben mit unserm Vieh?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Und warum habt ihr uns aus Agypten gefuhrt an diesen bosen Ort, da man nicht saen kann, da weder Feigen noch Weinstocke noch Granatapfel sind, und ist dazu kein Wasser zu trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mose und Aaron gingen von der Gemeine zur Tür der Hutte des Stifts und fielen auf ihr Angesicht; und die Herrlichkeit des Herrn erschien ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Nimm den Stab und versammle die Gemeine, du und dein Bruder Aaron, und redet mit dem Felsen vor ihren Augen; der wird sein Wasser geben. Also sollst du ihnen Wasser aus dem Felsen bringen und die Gemeine tranken und ihr Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Da nahm Mose den Stab vor dem HERRN, wie er ihm geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Und Mose und Aaron versammelten die Gemeine vor dem Felsen und sprach zu ihnen: Horet, ihr Ungehorsamen, werden wir euch auch Wasser bringen aus diesem Felsen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Und Mose hub seine Hand auf und schlug den Felsen mit dem Stabe zweimal. Da ging viel Wassers heraus, daß die Gemeine trank und ihr Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Der HERR aber sprach zu Mose und Aaron: Darum daß ihr nicht an mich geglaubet habt, daß ihr mich heiligtet vor den Kindern Israel, sollt ihr diese Gemeine nicht ins Land bringen, das ich ihnen geben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Das ist das Haderwasser, daruber die Kinder Israel mit dem HERRN haderten, und er geheiliget ward an ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Und Mose sandte Botschaft aus Kades zu dem Konige der Edomiter: Also latit dir dein Bruder Israel sagen: Du weilit alle die Mühe, die uns betreten hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'da(S unsere Vater nach Agypten hinabgezogen sind, und wir lange Zeit in Agypten gewohnet haben, und die Agypter handelten uns und unsere Vater libel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'und wirschrieen zu dem HERRN; der hat unsere Stimme erhoret und einen Engel gesandt und aus Agypten gefuhret. Und siehe, wir sind zu Kades in der Stadt an deinen Grenzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Laß uns durch dein Land ziehen. Wirwollen nicht durch Acker noch Weinberge gehen, auch nicht Wasser aus den Brunnen trinken; die Landstratße wollen wir ziehen, weder zur Rechten noch zur Linken weichen, bis wir durch deine Grenze kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Die Edomiter aber sprachen zu ihnen: Du sollst nicht durch mich ziehen, Oder ich will dir mit dem Schwert entgegenziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Die Kinder Israel sprachen zu ihm: Wirwollen auf der gebahnten Straße ziehen, und so wir deines Wassers trinken, wir und unser Vieh, so wollen wir\'s bezahlen; wirwollen nichts, denn nur zu Fuße hindurchziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Er aber sprach: Du sollst nicht herdurchziehen. Und die Edomiter zogen aus ihnen entgegen mit machtigem Volk und starker Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Also weigerten die Edomiter, Israel zu vergonnen, durch ihre Grenze zu ziehen. Und Israel wich von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Und die Kinder Israel brachen auf von Kades und kamen mit der ganzen Gemeine gen Hor am Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Und der HERR redete mit Mose und Aaron zu Hor am Gebirge an den Grenzen des Landes der Edomiter und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Lafi sich Aaron sammeln zu seinem Volk; denn er soil nicht in das Land kommen, das ich den Kindern Israel gegeben habe, darum daß ihr meinem Munde ungehorsam gewesen seid bei dem Haderwasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Nimm aber Aaron und seinen Sohn Eleasar und fuhre sie auf Hor am Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Und zeuch Aaron seine Kleider aus und zeuch sie Eleasar an, seinem Sohne. Und Aaron soil sich daselbst sammeln und sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Da tat Mose, wie ihm der HERR geboten hatte, und stiegen auf Hor am Gebirge vor der ganzen Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Und Mose zog Aaron seine Kleider aus und zog sie Eleasar an, seinem Sohne. Und Aaron starb daselbst oben auf dem Berge. Mose aber und Eleasar stiegen herab vom Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Und da die ganze Gemeine sah, daß Aaron dahin war, beweineten sie ihn dreitüg Tage, das ganze Haus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Und da der Kanaaniter, der Konig Arad, der gegen Mittag wohnete, horete, dati Israel hereinkommt durch den Weg der Kundschafter, stritt er wider Israel und fuhrete etliche gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Da gelobte Israel dem HERRN ein Gelubde und sprach: Wenn du dies Volk unter meine Hand gibst, so will ich ihre Stadte verbannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Und der HERR erhorete die Stimme Israels und gab die Kanaaniter und verbannete sie samt ihren Stadten; und hieli die Statte Horma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Da zogen sie von Hor am Gebirge auf dem Wege vom Schilfmeer, daß sie urn der Edomiter Land hinzogen. Und das Volk ward verdrossen auf dem Wege');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'und redete wider Gott und wider Mose: Warum hast du uns aus Agypten gefuhret, daß wir sterben in der Wüste? Denn es ist kein Brot noch Wasser hie, und unsere Seele ekelt uber dieser losen Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Da sandte der HERR feurige Schlangen unter das Volk; die bissen das Volk, daß ein groli Volk in Israel starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Da kamen sie zu Mose und sprachen: Wir haben gesundiget, daß wir wider den HERRN und wider dich geredet haben. Bitte den HERRN, daß erdie Schlangen von uns nehme! Mose bat fur das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Da sprach der HERR zu Mose: Mache dir eine eherne Schlange und richte sie zum Zeichen auf; wer gebissen ist und siehet sie an, der soil leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Da machte Mose eine eherne Schlange und richtete sie auf zum Zeichen; und wenn jemanden eine Schlange bili, so sah er die eherne Schlange an und blieb leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Und die Kinder Israel zogen aus und lagerten sich in Oboth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Und von Oboth zogen sie aus und lagerten sich in Ijim, am Gebirge Abarim, in der Wüste gegen Moab uber, gegen der Sonnen Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Von dannen zogen sie und lagerten sich am Bach Sared.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Von dannen zogen sie und lagerten sich diesseit am Arnon, welcher ist in der Wuste und herausreicht von der Grenze der Amoriter. Denn Arnon ist die Grenze Moabs zwischen Moab und den Amoritern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Daher spricht man in dem Buch von den Streiten des HERRN: Das Vaheb in Supha und die Bache am Arnon');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'und die Quelle der Bache, welche reichet hinan zu der Stadt Ar und lenket sich und ist die Grenze Moabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Und von dannen zogen sie zumßrunnen. Das ist der Brunnen, davon der HERR zu Mose sagte: Sammle das Volk, ich will ihnen Wasser geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Da sang Israel dieses Lied, und sangen umeinander über dem Brunnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Das ist der Brunnen, den die Fursten gegraben haben; die Edlen im Volk haben ihn gegraben durch den Lehrer und ihre Stabe. Und von dieser Wüste zogen sie gen Mathana;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'und von Mathana gen Nahaliel; und von Nahaliel gen Bamoth;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'und von Bamoth in das Tal, das im Felde Moab liegt, zu dem hohen Berge Pisga, der gegen die Wüste siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Und Israel sandte Boten zu Sihon, dem Konige der Amoriter, und lieft ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Laft mich durch dein Land ziehen; wirwollen nicht weichen in die Acker noch in die Weingarten, wollen auch des Brunnenwassers nicht trinken; die Landstrafte wollen wir ziehen, bis wir durch deine Grenze kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Aber Sihon gestattete den Kindern Israel den Zug nicht durch seine Grenze, sondern sammelte all sein Volk und zog aus Israel entgegen in die Wüste; und als er gen Jahza kam, stritt er wider Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Israel aber schlug ihn mit der Scharfe des Schwerts und nahm sein Land ein von Arnon an bis an den Jabbok und bis an die Kinder Ammon; denn die Grenzen der Kinder Ammon waren test.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Also nahm Israel alle diese Stadte und wohnete in alien Stadten der Amoriter, zu Hesbon und alien ihren Tochtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Denn Hesbon, die Stadt, war Sihons, des Konigs der Amoriter, und er hatte zuvor mit dem Konige der Moabiter gestritten und ihm all sein Land angewonnen bis gen Arnon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Daher sagt man im Sprichwort: Kommt gen Hesbon, dafi man die Stadt Sihon baue und aufrichte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'denn Feuer ist aus Hesbon gefahren, eine Flamme von der Stadt Sihon, die hat gefressen Ar der Moabiter und die Burger der Hohe Arnon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Wehe dir, Moab, du Volk Kamos bist verloren; man hat seine Sohne in die Flucht geschlagen und seine Tochter gefangen geführt Sihon, dem Konige der Amoriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Ihre Herrlichkeit ist zunichte worden, von Hesbon bis gen Dibon; sie ist verstoret bis gen Nophah, die da langet bis gen Medba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Also wohnete Israel im Lande der Amoriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Und Mose sandte aus Kundschafter gen Jaeser; und gewannen ihre Tochter und nahmen die Amoriter ein, die drinnen waren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'und wandten sich und zogen hinauf des Weges zu Basan. Da zog aus ihnen entgegen Og, der Konig zu Basan, mit all seinem Volk, zu streiten in Edrei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Und der HERR sprach zu Mose: Furchte dich nicht vor ihm; denn ich habe ihn in deine Hand gegeben mit Land und Leuten, und sollst mit ihm tun, wie du mit Sihon, dem Konige der Amoriter, getan hast, der zu Hesbon wohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Und sie schlugen ihn und seine Sohne und all sein Volk, bis daß keiner überblieb; und nahmen das Land ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Danach zogen die Kinder Israel und lagerten sich in das Gefilde Moab, jenseits des Jordans, gegen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Und da Balak, der Sohn Zipors, sah alles, was Israel getan hatte den Amoritern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'und daß sich die Moabiter sehr furchteten vor dem Volk, das so graft war, und daß den Moabitern grauete vor den Kindern Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'und sprachen zu den Altesten der Midianiter: Nun wird dieser Haufe auffretzen, was urn uns ist, wie ein Ochse Kraut auf dem Felde auffretzet. Balak aber, der Sohn Zipors, war zu der Zeit Konig der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Und er sandte Boten aus zu Bileam, dem Sohn Beors, gen Pethor, der wohnete an dem Wasser im Lande der Kinder seines Volks, daß sie ihn forderten, und lieft ihm sagen: Siehe, es ist ein Volk aus Agypten gezogen, das bedeckt das Angesicht der Erde und liegt gegen mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'So komm nun und verfluche mir das Volk, denn es ist mirzu machtig, ob ich\'s schlagen mochte und aus dem Lande vertreiben; denn ich weift, daß, weichen du segnest, der ist gesegnet, und weichen du verfluchest, der ist verflucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Und die Altesten der Moabiter gingen hin mit den Altesten der Midianiter und hatten den Lohn des Wahrsagens in ihren Handen; und gingen zu Bileam ein und sagten ihm die Worte Balaks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Und er sprach zu ihnen: Bleibet hie über Nacht, so will ich euch wieder sagen, wie mir der HERR sagen wird. Also blieben die Fursten der Moabiter bei Bileam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Und Gott kam zu Büeam und sprach: Wer sind die Leute, die bei dir sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam sprach zu Gott: Balak, der Sohn Zipors, der Moabiter Konig, hat zu mir gesandt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Siehe, ein Volk ist aus Agypten gezogen und bedeckt das Angesicht der Erde; so komm nun und fluche ihm, ob ich mit ihm streiten moge und sie vertreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Gott aber sprach zu Bileam: Gehe nicht mit ihnen; verfluche das Volk auch nicht; denn es ist gesegnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Da stund Bileam des Morgens auf und sprach zu den Fursten Balaks: Gehet hin in euer Land; denn der HERR will\'s nicht gestatten, daß ich mit euch ziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Und die Fursten der Moabiter machten sich auf, kamen zu Balak und sprachen: Bileam weigert sich, mit uns zu ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Da sandte Balak noch großere und herrlichere Fursten, denn jene waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Da die zu Bileam kamen, sprachen sie zu ihm: Also lafit dir sagen Balak, der Sohn Zipors: Lieber, wehre dich nicht, zu mir zu ziehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'denn ich will dich hoch ehren, und was du mir sagest, das will ich tun. Lieber, komm und fluche mir diesem Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Bileam antwortete und sprach zu den Dienern Balaks: Wenn mir Balak sein Haus voll Silbers und Goldes gabe, so konnte ich doch nicht ubergehen das Wort des HERRN, meines Gottes, Kleines Oder Großes zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'So bleibet doch nun hie auch ihr diese Nacht, daß ich erfahre, was der HERR weiter mit mir reden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Da kam Gott des Nachts zu Bileam und sprach zu ihm: Sind die Manner kommen, dirzu rufen, so mach dich auf und zeuch mit ihnen; doch was ich dir sagen werde, sollst du tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Da stund Bileam des Morgens auf und sattelte seine Eselin und zog mit den Fursten der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Aber der Zorn Gottes ergrimmete, dafi er hinzog. Und der Engel des HERRN trat in den Weg, daß er ihm widerstunde. Er aber ritt auf seiner Eselin, und zween Knaben waren mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Und die Eselin sah den Engel des HERRN im Wege stehen und ein bloß Schwert in seiner Hand. Und die Eselin wich aus dem Wege und ging auf dem Felde; Bileam aber schlug sie, daß sie in den Weg sollte gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Da trat der Engel des HERRN in den Pfad bei den Weinbergen, da auf beiden Seiten Wande waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Und da die Eselin den Engei des HERRN sah, drangte sie sich an die Wand und klemmete Bileam den Fuß an der Wand; und er schlug sie noch mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Da ging der Engel des HERRN weiter und trat an einen engen Ort, da kein Weg war zu weichen, weder zur Rechten noch zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Und da die Eselin den Engei des HERRN sah, fiel sie auf ihre Kniee unter dem Bileam. Da ergrimmete der Zorn Bileams und schlug die Eselin mit dem Stabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Da tat der HERR der Eselin den Mund auf, und sie sprach zu Bileam: Was habe ich dir getan, daß du mich geschlagen hast nun dreimal?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam sprach zur Eselin: Daü du mich hohnest! Ach, daß ich jetzt ein Schwert in der Hand hatte, ich wollte dich erwurgen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Die Eselin sprach zu Bileam: Bin ich nicht deine Eselin, darauf du geritten hast zu deiner Zeit bis auf diesen Tag? Habe ich auch je gepflegt, dir also zu tun? Er sprach: Nein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Da offnete der HERR Bileam die Augen, daß er den Engel des HERRN sah im Wege stehen und ein bloli Schwert in seiner Hand; und neigete und buckte sich mit seinem Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Und der Engel des HERRN sprach zu ihm: Warum hast du deine Eselin geschlagen nun dreimal? Siehe, ich bin ausgegangen, daü ich dir widerstehe; denn der Weg ist vor mir verkehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Und die Eselin hat mich gesehen und ist mir dreimal gewichen; sonst, wo sie nicht vor mir gewichen ware, so wollte ich dich auch jetzt erwurget und die Eselin lebendig behalten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Da sprach Bileam zu dem Engel des HERRN: Ich habe gesundiget; denn ich hab\'s nicht gewulit, daß du mirentgegenstundest im Wege; und nun, so dir\'s nicht gefallt, will ich wieder umkehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Der Engel des HERRN sprach zu ihm: Zeuch hin mit den Mannern; aber nichts anderes, denn was ich zu dir sagen werde, sollst du reden. Also zog Bileam mit den Fursten Balaks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Da Balak horete, daß Büeam kam, zog er aus ihm entgegen in die Stadt der Moabiter, die da liegt an der Grenze Arnons, welcher ist an der auliersten Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Und sprach zu ihm: Habe ich nicht zu dir gesandt und dich fordern lassen? Warum bist du denn nicht zu mir kommen? Meinest du, ich konnte nicht dich ehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Bileam antwortete ihm: Siehe, ich bin kommen zu dir; aber wie kann ich etwas anderes reden? Denn das mir Gott in den Mund gibt, das muli ich reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Also zog Bileam mit Balak, und kamen in die Gassenstadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Und Balak opferte Rinder und Schafe und sandte nach Bileam und nach den Fursten, die bei ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Und des Morgens nahm Balak den Bileam und fuhrete ihn hin auf die Hohe Baal, daß ervon dannen sehen konnte bis zu Ende des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Und Bileam sprach zu Balak: Baue mir hie sieben Altare und schaffe mir her sieben Farren und sieben Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak tat, wie ihm Bileam sagte; und beide, Balak und Bileam, opferten je auf einem Altar einen Farren und einen Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Und Bileam sprach zu Balak: Tritt bei dein Brandopfer; ich will hingehen, ob vielleicht mir der HERR begegne, daß ich dir ansage, was er mir zeiget. Und ging hin eilend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Und Gott begegnete Bileam; er aber sprach zu ihm: Sieben Altare habe ich zugerichtet und je auf einem Altar einen Farren und einen Widder geopfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Der HERR aber gab das Wort dem Bileam in den Mund und sprach: Gehe wiederzu Balak und rede also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Und da er wieder zu ihm kam, siehe, da stund er bei seinem Brandopfer samt alien Fursten der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Da hub er an seinen Spruch und sprach: Aus Syrien hat mich Balak, der Moabiter Konig, holen lassen von dem Gebirge gegen dem Aufgang: Komm, verfluche mir Jakob! Komm, schilt Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Wie soil ich fluchen, dem Gott nicht fluchet? Wie soil ich schelten, den der HERR nicht schilt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Denn von der Hohe der Felsen sehe ich ihn wohl und von den Hugeln schaue ich ihn. Siehe, das Volk wird besonders wohnen und nicht unter die Heiden gerechnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Wer kann zahlen den Staub Jakobs und die Zahl des vierten Teils Israels? Meine Seele müsse sterben des Todes der Gerechten, und mein Ende werde wie dieser Ende!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Da sprach Balak zu Bileam: Was tust du an mir? Ich habe dich holen lassen, zu fluchen meinen Feinden; und siehe, du segnest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Er antwortete und sprach: Muft ich nicht das halten und reden, das mir der HERR in den Mund gibt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balak sprach zu ihm: Komm doch mitmiran einen andern Ort, von dannen du sein Ende sehest und doch nicht ganz sehest; und fluche mir ihm daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Und er fuhrete ihn auf einen freien Platz auf der Hohe Pisga und bauete sieben Altare; und opferte je auf einem Altar einen Farren und einen Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Und sprach zu Balak: Tritt also bei dein Brandopfer; ich will dort warten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Und der HERR begegnete Bileam und gab ihm das Wort in seinen Mund und sprach: Gehe wieder zu Balak und rede also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Und da er wieder zu ihm kam, siehe, da stund er bei seinem Brandopfer samt den Fursten der Moabiter. Und Balak sprach zu ihm: Was hat der HERR gesagt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Und er hub an seinen Spruch und sprach: Stehe auf, Balak, und hore! Nimm zu Ohren, was ich sage, du Sohn Zipors!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Gott ist nicht ein Mensch, daß er luge, noch ein Menschenkind, daß ihn etwas gereue. Sollte er etwas sagen und nicht tun? Sollte er etwas reden und nicht halten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Siehe, zu segnen bin ich hergebracht; ich segne und kann\'s nicht wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Man siehet keine Muhe in Jakob und keine Arbeit in Israel. Der HERR, sein Gott; ist bei ihm, und das Trommeten des Konigs unter ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gott hat sie aus Agypten gefuhret; seine Freudigkeit ist wie eines Einhorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Denn es ist kein Zauberer in Jakob und kein Wahrsager in Israel. Zu seiner Zeit wird man von Jakob sagen und von Israel, welche Wunder Gott tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Siehe, das Volk wird aufstehen wie ein junger Lowe, und wird sich erheben wie ein Lowe; es wird sich nicht legen, bis es den Raub fresse und das Blut der Erschlagenen saufe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Da sprach Balak zu Bileam: Du sollst ihm weder fluchen noch segnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam antwortete und sprach zu Balak: Habe ich dir nicht gesagt, alles, was der HERR reden würde, das würde ich tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Balak sprach zu ihm: Komm doch, ich will dich an einen andern Ort führen, ob\'s vielleicht Gott gefalle, daß du daselbst mir sie verfluchest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Und er fuhrete ihn auf die Hohe des Berges Peor, welcher gegen die Wuste siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Und Bileam sprach zu Balak: Baue mir hie sieben Altare und schaffe mir sieben Farren und sieben Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak tat, wie Bileam sagte, und opferte je auf einem Altar einen Farren und einen Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Da nun Bileam sah, daß es dem HERRN gefiel, daß er Israel segnete, ging er nicht hin, wie vormals, nach den Zauberern, sondern richtete sein Angesicht stracks zu der Wuste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'hub auf seine Augen und sah Israel, wie sie lagen nach ihren Stammen. Und der Geist Gottes kam auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Und er hub an seinen Spruch und sprach: Es saget Bileam, der Sohn Beors; es saget der Mann, dem die Augen geoffnet sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'es saget der Horer gottlicher Rede, der des Allmachtigen Offenbarung siehet, dem die Augen geoffnet werden, wenn er niederknieet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Wie fein sind deine Hutten, Jakob, und deine Wohnungen, Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Wie sich die Bache ausbreiten, wie die Garten an den Wassern, wie die Hutten, die der HERR pflanzet, wie die Zedern an den Wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Es wird Wasser aus seinem Eimer flieften, und sein Same wird ein graft Wasser werden; sein Konig wird hoher werden denn Agag, und sein Reich wird sich erheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gott hat ihn aus Agypten gefuhret; seine Freudigkeit ist wie eines Einhorns. Erwird die Heiden, seine Verfolger, fressen und ihre Gebeine zermalmen und mit seinen Pfeilen zerschmettern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Er hat sich niedergelegt wie ein Lowe und wie ein junger Lowe; wer will sich wider ihn auflehnen? Geseqnet sei, der dich segnet, und verflucht, der dir flucht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Da ergrimmete Balak im Zorn wider Bileam und schlug die Hande zusammen und sprach zu ihm: Ich habe dich gefordert, dall du meinen Feinden fluchen solltest; und siehe, du hast sie nun dreimal gesegnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Und nun heb dich an deinen Ort. Ich gedachte, ich wollte dich ehren; aber der HERR hat dir die Ehre verwehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam antwortete ihm: Habe ich nicht auch zu deinen Boten gesagt, die du zu mir sandtest, und gesprochen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Wenn mir Balak sein Haus voll Silber und Gold gabe, so konnte ich doch vor des HERRN Wort nicht über, Boses Oder Gutes zu tun nach meinem Herzen, sondern was der HERR reden würde, das würde ich auch reden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Und nun siehe, wenn ich zu meinem Volk ziehe, so komm, so will ich dir raten, was dies Volk deinem Volk tun wird zur letzten Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Und erhub an seinen Spruch und sprach: Es saget Bileam, der Sohn Beors; es saget der Mann, dem die Augen geoffnet sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'es saget der Horer gottlicher Rede und der die Erkenntnis hat des Hochsten, der die Offenbarung des Allmachtigen siehet und dem die Augen geoffnet werden, wenn er niederknieet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ich werde ihn sehen, aber jetzt nicht; ich werde ihn schauen, aber nicht von nahe. Es wird ein Stern aus Jakob aufgehen, und ein Zepter aus Israel aufkommen und wird zerschmettern die Fürsten der Moabiter und verstoren alle Kinder Seths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Edom wird er einnehmen, und Seir wird seinen Feinden unterworfen sein; Israel aber wird Sieg haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Aus Jakob wird der Herrscher kommen und umbringen, was übrig ist von den Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Und da er sah die Amalekiter, hub er an seinen Spruch und sprach: Amalek, die ersten unter den Heiden; aber zuletzt wirst du gar umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Und da er sah die Keniter, hub er an seinen Spruch und sprach: Fest ist deine Wohnung, und hast dein Nest in einen Felsen gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Aber, o Kain, du wirst verbrannt werden, wenn Assur dich gefangen wegfuhren wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Und hub abermal an seinen Spruch und sprach: Ach, wer wird leben, wenn Gott solches tun wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Und Schiffe aus Chittim werden verderben den Assur und Eber; er aber wird auch umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Und Bileam machte sich auf und zog hin und kam wieder an seinen Ort; und Balak zog seinen Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Und Israel wohnte in Sittim. Und das Volk hub an zu huren mit der Moabiter Tochtern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'welche luden das Volk zum Opfer ihrer Gotten Und das Volk aft und betete ihre Gotter an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Und Israel hangete sich an den Baal Peor. Da ergrimmete des HERRN Zorn über Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'und sprach zu Mose: Nimm alle Obersten des Volks und hange sie dem HERRN an die Sonne, auf daß der grimmige Zorn des HERRN von Israel gewandt werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Und Mose sprach zu den Richtern Israels: Erwürge ein jeglicher seine Leute, die sich an den Baal-Peor gehanget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Und siehe, ein Mann aus den Kindern Israel kam und brachte unter seine Brüder eine Midianitin und lieft Mose zusehen und die ganze Gemeine der Kinder Israel, die da weineten vor der Tür der Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Da das sah der Sohn Eleasars, des Sohns Aarons, des Priesters, stund er auf aus der Gemeine und nahm einen Spieft in seine Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'und ging dem israelitischen Manne nach hinein in den Hurenwinkel und durchstach sie beide, den israelitischen Mann und das Weib, durch ihren Bauch. Da horete die Plage auf von den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Und es wurden getotet in der Plage vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, der Sohn Eleasars, des Sohns Aarons, des Priesters, hat meinen Grimm von den Kindern Israel gewendet durch seinen Eifer urn mich, daß ich nicht in meinem Eifer die Kinder Israel vertilgete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Darum sage: Siehe, ich gebe ihm meinen Bund des Friedens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'und ersoll haben, und sein Same nach ihm, den Bund eines ewigen Priestertums, darum daß er fur seinen Gott geeifert und die Kinder Israel versohnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Der israelitische Mann aber, der erschlagen ward mit der Midianitin, hieü Simri, der Sohn Salus, ein Fürst im Hause des Vaters der Simeoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Das midianitische Weib, das auch erschlagen ward, hieü Kasbi, eine Tochter Zurs, der ein Fürst war eines Geschlechts unter den Midianitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Tut den Midianitern Schaden und schlaget sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'denn sie haben euch Schaden getan mit ihrer List, die sie euch gestellet haben durch den Peor und durch ihre Schwester Kasbi, die Tochter des Fürsten der Midianiter, die erschlagen ist am Tage der Plage urn des Peors willen, und die Plage danach kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 19, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Und der HERR sprach zu Mose und Eleasar, dem Sohn des Priesters Aaron:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Nimm die Summa der ganzen Gemeine der Kinder Israel von zwanzig Jahren und drüber, nach ihrer Vater Hausern, alle, die ins Heer zu ziehen taugen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Und Mose redete mit ihnen samt Eleasar, dem Priester, in dem Gefilde der Moabiter, an dem Jordan gegen Jericho,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'die zwanzig Jahre alt waren und druber, wie der HERR Mose geboten hatte und den Kindern Israel, die aus Agpyten gezogen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, der Erstgeborne Israels. Die Kinder Rubens aber waren: Hanoch, von dem das Geschlecht der Hanochiter kommt; Pallu, von dem das Geschlecht der Palluiter kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hezron, von dem das Geschlecht der Hezroniter kommt; Charmi, von dem das Geschlecht der Charmiter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Das sind die Geschlechter von Ruben, und ihre Zahl war dreiundvierzigtausend siebenhundertunddreißig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Aber die Kinder Pallus waren Eliab;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Und die Kinder Eliabs waren Nemuel und Dathan und Abiram. Das istder Dathan und Abiram, die Vomehmlichen in der Gemeine, die sich wider Mose und Aaron auflehneten in der Rotte Korahs, da sie sich wider den HERRN auflehneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'und die Erde ihren Mund auftat und sie verschlang mit Korah, da die Rotte starb; da das Feuer zweihundertundfunfzig Manner frali, und wurden ein Zeichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Aber die Kinder Korahs starben nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Die Kinder Simeons in ihren Geschlechtern waren: Nemuel, daher kommt das Geschlecht der Nemueliter; Jamin, daher kommt das Geschlecht der Jaminiter; Jachin, daher das Geschlecht der Jachiniter kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Serah, daher das Geschlecht der Serahiter kommt; Saul, daher das Geschlecht der Sauliter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Das sind die Geschlechter von Simeon: zweiundzwanzigtausend und zweihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Die Kinder Gads in ihren Geschlechtern waren: Ziphon, daher das Geschlecht der Ziphoniter kommt; Haggi, daher das Geschlecht der Haggiter kommt; Suni, daher das Geschlecht der Suniter kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osni, daher das Geschlecht der Osniter kommt; Eri, daher das Geschlecht der Eriter kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, daher das Geschlecht der Aroditer kommt; Ariel, daher das Geschlecht der Arieliter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Das sind die Geschlechter der Kinder Gads, an ihrer Zahl vierzigtausend und funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Die Kinder Judas: Gerund Onan, welche beide starben im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Es waren aber die Kinder Judas in ihren Geschlechtern: Sela, daher das Geschlecht der Selaniter kommt; Perez, daher das Geschlecht der Pereziter kommt; Serah, daher das Geschlecht der Serahiter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Aber die Kinder Perez waren: Hezron, daher das Geschlecht der Hezroniter kommt; Hamul, daher das Geschlecht der Hamuliter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Das sind die Geschlechter Judas, an ihrer Zahl sechsundsiebenzigtausend und funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Die Kinder Isaschars in ihren Geschlechtern waren: Thola, daher das Geschlecht der Tholaiter kommt; Phuva, daher das Geschlecht der Phuvaniter kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, daher das Geschlecht der Jasubiter kommt; Simron, daher das Geschlecht der Simroniter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Das sind die Geschlechter Isaschars, an der Zahl vierundsechzigtausend und dreihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Die Kinder Sebulons in ihren Geschlechtern waren: Sered, daher das Geschlecht der Serediter kommt; Elon, daher das Geschlecht der Eloniter kommt; Jaheleel, daher das Geschlecht der Jaheleeliter kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Das sind die Geschlechter Sebulons, an ihrer Zahl sechzigtausend und funfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Die Kinder Josephs in ihren Geschlechtern waren: Manasse und Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Die Kinder aber Manasses waren: Machir, daher kommt das Geschlecht der Machiriter; Machir zeugete Gilead, daher kommt das Geschlecht der Gileaditer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Dies sind aber die Kinder Gileads: Hieser, daher kommt das Geschlecht der Hieseriter; Helek, daher kommt das Geschlecht der Helekiter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, daher kommt das Geschlecht der Asrieliter; Sichem, daher kommt das Geschlecht der Sichemiter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Smida, daher kommt das Geschlecht der Smidaiter; Hepher, daher kommt das Geschlecht der Hepheriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Zelaphehad aber war Hephers Sohn und hatte keine Sohne, sondern Tochter; die hiefien Mahela, Noa, Hagla, Milka und Thirza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Das sind die Geschlechter Manasses, an ihrer Zahl zweiundfunfzigtausend und siebenhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Die Kinder Ephraims in ihren Geschlechtern waren: Suthelah, daher kommt das Geschlecht der Suthelahiter; Becher, daher kommt das Geschlecht der Becheriter; Thahan, daher kommt das Geschlecht der Thahaniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Die Kinder aber Suthelahs waren: Eran, daher kommt das Geschlecht der Eraniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Das sind die Geschlechter der Kinder Ephraims, an ihrer Zahl zweiunddreilügtausend und funfhundert. Das sind die Kinder Josephs in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Die Kinder Benjamins in ihren Geschlechtern waren: Bela, daher kommt das Geschlecht der Belaiter; Asbel, daher kommt das Geschlecht der Asbeliter; Ahiram, daher kommt das Geschlecht der Ahiramiter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Supham, daher kommt das Geschlecht der Suphamiter; Hupham, daher kommt das Geschlecht der Huphamiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Die Kinder aber Belas waren: Ard und Naeman, daher kommt das Geschlecht der Arditer und Naemaniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Das sind die Kinder Benjamins in ihren Geschlechtern, an der Zahl fünfundvierzigtausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Die Kinder Dans in ihren Geschlechtern waren: Suham, daher kommt das Geschlecht der Suhamiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Das sind die Geschlechter Dans in ihren Geschlechtern, und waren allesamt an der Zahl vierundsechzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Die Kinder Assers in ihren Geschlechtern waren: Jemna, daher kommt das Geschlecht der Jemniter; Jeswi, daher kommt das Geschlecht der Jeswiter; Bria, daher kommt das Geschlecht der Brüter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Aber die Kinder Brias waren: Heber, daher kommt das Geschlecht der Hebriter; Melchiel, daher kommt das Geschlecht der Melchieliter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Und die Tochter Assers hieli Sara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Das sind die Geschlechter der Kinder Assers, an ihrer Zahl dreiundfunfzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Die Kinder Naphthalis in ihren Geschlechtern waren: Jaheziel, daher kommt das Geschlecht der Jahezieliter; Guni, daher kommt das Geschlecht der Guniter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jezer, daher kommt das Geschlecht der Jezeriter; Sillem, daher kommt das Geschlecht der Sillemiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Das sind die Geschlechter von Naphthali, an ihrer Zahl fünfundvierzigtausend und vierhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Das ist die Summa der Kinder Israel: sechsmal hunderttausend, eintausend siebenhundertunddreißig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Diesen sollst du das Land austeilen zum Erbe nach der Zahl der Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Vielen sollst du viel zum Erbe geben und wenigen wenig; jeglichen soil man geben nach ihrer Zahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Doch soli man das Land durchs Los teilen; nach den Namen der Stamme ihrer Vater sollen sie Erbe nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Denn nach dem Los sollst du ihr Erbe austeilen zwischen den vielen und wenigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Und das ist die Summa der Leviten in ihren Geschlechtern: Gerson, daher das Geschlecht der Gersoniter; Kahath, daher das Geschlecht der Kahathiter; Merari, daher das Geschlecht der Merariter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dies sind die Geschlechter Levis: Das Geschlecht der Libniter, das Geschlecht der Hebroniter, das Geschlecht der Maheliter, das Geschlecht der Musiter, das Geschlecht der Korahiter. Kahath zeugete Amram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Und Amrams Weib hiefi Jochebed, eine Tochter Levis, die ihm geboren ward in Agypten; und sie gebar dem Amram Aaron und Mose und ihre Schwester Mirjam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Dem Aaron aber ward geboren Nadab, Abihu, Eleasar und Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadab aber und Abihu starben, da sie fremd Feuer opferten vordem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Und ihre Summa war dreiundzwanzigtausend, alle Mannlein, von einem Monden an und drüber. Denn sie wurden nicht gezahlet unter die Kinder Israel; denn man gab ihnen kein Erbe unter den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Das ist die Summa der Kinder Israel, die Mose und Eleasar, der Priester, zahleten im Gefilde der Moabiter, an dem Jordan gegen Jericho;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'unter welchen war keiner aus der Summa, da Mose und Aaron, der Priester, die Kinder Israel zahleten in der Wuste Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Denn der HERR hatte ihnen gesagt, sie sollten des Todes sterben in der Wuste. Und blieb keiner übrig, ohne Kaleb, der Sohn Jephunnes, und Josua, der Sohn Nuns,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Und die Tochter Zelaphehads, des Sohns Hephers, des Sohns Gileads, des Sohns Machirs, des Sohns Manasses unter den Geschlechtern Manasses, des Sohns Josephs, mit Namen Mahela, Noa, Hagla, Milka und Thirza, kamen herzu');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'und traten vor Mose und vor Eleasar, den Priester, und vor die Fursten und ganze Gemeine vor der Tur der Hutte des Stiffs und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Unser Vater ist gestorben in der Wuste und war nicht mit unter der Gemeine, die sich wider den HERRN emporten in der Rotte Korahs, sondern ist an seiner Sünde gestorben und hatte keine Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Warum soli denn unsers Vaters Name unter seinem Geschlecht untergehen, ob erwohl keinen Sohn hat? Gebet uns auch ein Gut unter unsers Vaters Brudern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Mose brachte ihre Sache vor den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Und der HERR sprach zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Die Tochter Zelaphehads haben recht geredet; du sollst ihnen ein Erbgut unter ihres Vaters Brudern geben und sollst ihres Vaters Erbe ihnen zuwenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Und sage den Kindern Israel: Wenn jemand stirbt und hat nicht Sohne, so sollt ihr sein Erbe seiner Tochter zuwenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Hat er keine Tochter, sollt ihr\'s seinen Brudern geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Hat er keine Bruder, sollt ihr\'s seinen Vettern geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Hat er nicht Vettern, sollt ihr\'s seinen nachsten Freunden geben, die ihm angehoren in seinem Geschlecht, dafi sie es einnehmen. Das soil den Kindern Israel ein Gesetz und Recht sein, wie der HERR Mose geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Und der HERR sprach zu Mose: Steige auf dies Gebirge Abarim und besiehe das Land, das ich den Kindern Israel geben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Und wenn du es gesehen hast, sollst du dich sammeln zu deinem Volk, wie dein Bruder Aaron versammelt ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'dieweil ihr meinem Wort ungehorsam gewesen seid in der Wuste Zin uber dem Hader der Gemeine, da ihr mich heiligen solltet durch das Wasser vor ihnen. Das ist das Haderwasser zu Kades in der Wuste Zin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Und Mose redete mitdem HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Der HERR, der Gott uber alles lebendige Fleisch, wolle einen Mann setzen uber die Gemeine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'der vor ihnen her aus und ein gehe und sie aus und ein führe, daß die Gemeine des HERRN nicht sei wie die Schafe ohne Hirten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Und der HERR sprach zu Mose: Nimm Josua zu dir, den Sohn Nuns, der ein Mann ist, in dem der Geist ist, und lege deine Hande auf ihn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'und stelle ihn vor den Priester Eleasar und vor die ganze Gemeine und gebeut ihm vor ihren Augen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'und lege deine Herrlichkeit auf ihn, daß ihm gehorche die ganze Gemeine der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Und er soil treten vor den Priester Eleasar, der soil fur ihn ratfragen durch die Weise des Lichts vor dem HERRN. Nach desselben Mund sollen aus- und einziehen beide er und alle Kinder Israel mit ihm und die ganze Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Mose wie ihm der HERR geboten hatte, und nahm Josua und stellete ihn vor den Priester Eleasar und vor die ganze Gemeine;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'und legte seine Hand auf ihn und gebot ihm, wie der HERR mit Mose geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Gebeut den Kindern Israel und sprich zu ihnen: Die Opfer meines Brots, welches mein Opfer des sufien Geruchs ist, sollt ihr halten zu seinen Zeiten, daß ihr mir\'s opfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Und sprich zu ihnen: Das sind die Opfer, die ihr dem HERRN opfern sollt: jahrige Lammer, die ohne Wandel sind, taglich zwei zum taglichen Brandopfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'ein Lamm des Morgens, das andere zwischen Abends;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'dazu einen Zehnten Epha Semmelmehls zum Speisopfer, mit 01 gemenget, das gestolien ist, eines vierten Teils vom Hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Das ist ein taglich Brandopfer, das ihr am Berge Sinai opfertet zum sufien Geruch, ein Feuer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Dazu sein Trankopfer, je zu einem Lamm ein Vierteil vom Hin. Im Heiligtum soil man den Wein des Trankopfers opfern dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Das andere Lamm sollst du zwischen Abends machen, wie das Speisopfer des Morgens, und sein Trankopfer zum Opfer des sulien Geruchs dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Am Sabbattag aber zwei jahrige Lammer ohne Wandel und zwo zehnten Semmelmehls zum Speisopfer, mit 01 gemenget, und sein Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Das ist das Brandopfer eines jeglichen Sabbats uber das tagliche Brandopfer samt seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Aber des ersten Tages eurer Monden sollt ihr dem HERRN ein Brandopfer opfern: zween junge Farren, einen Widder, sieben jahrige Lammer ohne Wandel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'und je drei Zehnten Semmelmehls zum Speisopfer, mit 01 gemenget, zu einem Farren, und zwo Zehnten Semmel-mehls zum Speisopfer, mit 01 gemenget, zu einem Widder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'und je einen Zehnten Semmelmehls zum Speisopfer, mit 01 gemenget, zu einem Lamm. Das ist das Brandopfer des sulien Geruchs, ein Opfer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Und ihr Trankopfer soil sein: ein halb Hin Weins zum Farren, ein Dritteil Hin zum Widder, ein Vierteil Hin zum Lamm. Das ist das Brandopfer eines jeglichen Monden im Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Dazu soil man einen Ziegenbock zum Sundopfer dem HERRN machen uber das tagliche Brandopfer und sein Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Aber am vierzehnten Tage des ersten Monden ist das Passah dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Und am funfzehnten Tage desselben Monden ist Fest. Sieben Tage soil man ungesauert Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Dererste Tag soli heilig heilien, daß ihr zusammenkommet; keine Dienstarbeit sollt ihrdrinnen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Und sollt dem HERRN Brandopfer tun: zween junge Farren, einen Widder, sieben jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'samt ihren Speisopfern: drei Zehnten Semmelmehls, mit 01 gemenget, zu einem Farren, und zwo Zehnten zu dem Widder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'und je einen Zehnten auf ein Lamm unter den sieben Lammern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'dazu einen Bock zum Sundopfer, daß ihr versohnet werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Und sollt solches tun am Morgen uber das Brandopfer, welches ein taglich Brandopfer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Nach dieser Weise sollt ihr alle Tage, die sieben Tage lang, das Brot opfern, zum Opfer des sufien Geruchs dem HERRN, uber das tagliche Brandopfer, dazu sein Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Und der siebente Tag soil bei euch heilig heilien, daß ihr zusammenkommet; keine Dienstarbeit sollt ihrdrinnen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Und der Tag der Erstlinge, wenn ihr opfert das neue Speisopfer dem HERRN, wenn eure Wochen urn sind, soil heilig heilien, daß ihr zusammenkommet; keine Dienstarbeit sollt ihr drinnen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Und sollt dem HERRN Brandopfer tun zum sufien Geruch: zween junge Farren, einen Widder, sieben jahrige Lammer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'samt ihrem Speisopfer: drei Zehnten Semmelmehls, mit 01 gemenget, zu einem Farren, zwo Zehnten zu dem Widder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'und je einen Zehnten zu einem Lamm der sieben Lammer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'und einen Ziegenbock, euch zu versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Dies sollt ihr tun uber das tagliche Brandopfer mit seinem Speisopfer. Ohne Wandel soli\'s sein, dazu ihr Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Und der erste Tag des siebenten Monden soil bei euch heilig heilien, daß ihrzusammenkommet; keine Dienstarbeit sollt ihr drinnen tun. Es ist euer Trommetentag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Und sollt Brandopfer tun zum sutien Geruch dem HERRN: einen jungen Farren, einen Widder, sieben jahrige Lammer ohne Wandel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'dazu ihr Speisopfer: drei Zehnten Semmelmehls, mit 01 gemenget, zu dem Farren, zwo Zehnten zu dem Widder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'und einen Zehnten auf ein jeglich Lamm der sieben Lammer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'auch einen Ziegenbock zum Sundopfer, euch zu versohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'uber das Brandopfer des Monden und sein Speisopfer und uber das tagliche Brandopfer mit seinem Speisopfer und mit ihrem Trankopfer, nach ihrem Recht zum sufien Geruch. Das ist ein Opfer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Der zehnte Tag dieses siebenten Monden soli bei euch auch heilig heilien, dafi ihr zusammenkommet; und sollt eure Leiber kasteien und keine Arbeit drinnen tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'sondern Brandopfer dem HERRN zum sulien Geruch opfern: einen jungen Farren, einen Widder, sieben jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'mit ihren Speisopfern: drei Zehnten Semmelmehls, mit 01 gemenget, zu dem Farren, zwo Zehnten zu dem Widder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'und einen Zehnten je zu einem der sieben Lammer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'dazu einen Ziegenbock zum Sundopfer uber das Sundopfer der Versohnung und das tagliche Brandopfer mit seinem Speisopfer und mit ihrem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Der funfzehnte Tag des siebenten Monden soil bei euch heilig heilien, daß ihrzusammenkommet. Keine Dienstarbeit sollt ihr drinnen tun; und sollt dem HERRN sieben Tage feiern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Und sollt dem HERRN Brandopfer tun zum Opfer des sülien Geruchs dem HERRN: dreizehn junge Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'samt ihrem Speisopfer: drei Zehnten Semmelmehls, mit 01 gemenget, je zu einem der dreizehn Farren, zween Zehnten je zu einem der zween Widder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'und einen Zehnten je zu einem der vierzehn Lammer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'dazu einen Ziegenbock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Am andern Tage zwolf junge Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'mit ihrem Speisopfer und Trankopfer zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'dazu einen Ziegenbock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und mit ihrem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Am dritten Tage elf Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'mit ihren Speisopfern und Trankopfern zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'dazu einen Bock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Am vierten Tage zehn Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'samt ihren Speisopfern und Trankopfern zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'dazu einen Ziegenbock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Am fünften Tage neun Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'samt ihren Speisopfern und Trankopfern zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'dazu einen Bock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Am sechsten Tage acht Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'samt ihren Speisopfern und Trankopfern zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht; einen Bock zum Sundopfer uber');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'dazu das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Am siebenten Tage sieben Farren, zween Widder, vierzehn jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'samt ihren Speisopfern und Trankopfern zu den Farren, zu den Widdern und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'dazu einen Bock zum Sundopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Am achten soli der Tag der Versammlung sein; keine Dienstarbeit sollt ihr drinnen tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Und sollt Brandopfer opfern zum Opfer des sütien Geruchs dem HERRN: einen Farren, einen Widder, sieben jahrige Lammer ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'samt ihren Speisopfern und Trankopfern zu den Farren, zu dem Widder und zu den Lammern in ihrer Zahl nach dem Recht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'dazu einen Bock zum Sündopfer uber das tagliche Brandopfer mit seinem Speisopfer und seinem Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Solches sollt ihrdem HERRN tun auf eure Feste, ausgenommen, was ihr gelobet und freiwillig gebet zu Brandopfern, Speisopfern, Trankopfern und Dankopfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Und Mose sagte den Kindern Israel alles, was ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Und Mose redete mit den Fursten der Stamme der Kinder Israel und sprach: Das ist\'s, das der HERR geboten hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Wenn jemand dem HERRN ein Gelübde tut Oder einen Eid schwdret, daß er seine Seele verbindet, der soli sein Wort nicht schwachen, sondern alles tun, wie es zu seinem Munde ist ausgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Wenn ein Weibsbild dem HERRN ein Gelübde tut und sich verbindet, weil sie in ihres Vaters Hause und im Magdtum ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'und ihr Gelubde und Verbündnis, das sie tut uber ihre Seele, kommt vor ihren Vater, und er schweiget dazu: so gilt all ihr Gelubde und all ihr Verbündnis, des sie sich uber ihre Seele verbunden hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Wo aber ihr Vater wehret des Tages, wenn er\'s horet, so gilt kein Gelubde noch Verbündnis, dessen sie sich uber ihre Seele verbunden hat; und der HERR wird ihr gnadig sein, weil ihr Vater ihr gewehret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Hat sie aber einen Mann und hat ein Gelubde auf ihr, Oder entfahret ihr aus ihren Lippen ein Verbündnis über ihre Seele;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'und der Mann horet\'s und schweiget desselben Tages stille: so gilt ihr Gelübde und Verbündnis, dessen sie sich uber ihre Seele verbunden hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Wo aber ihr Mann wehret des Tages, wenn er\'s horet, so ist ihr Gelubde los, das sie auf ihr hat, und das Verbündnis, das ihr aus ihren Lippen entfahren ist über ihre Seele; und der HERR wird ihr gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Das Gelübde einer Witwe und Verstoftenen: alles, wes sie sich verbindet über ihre Seele, das gilt auf ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Wenn jemandes Gesinde gelobet Oder sich mit einem Eide verbindet über seine Seele;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'und der Hausherr horet\'s und schweiget dazu und wehret\'s nicht: so gilt all dasselbe Gelubde und alles, wes es sich verbunden hat über seine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Macht\'s aber der Hausherr des Tages los, wenn er\'s horet, so gilt\'s nicht, was aus seinen Lippen gegangen ist, das es gelobet Oder sich verbunden hat über seine Seele; denn der Hausherr hat\'s los gemacht; und der HERR wird ihm gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Und alle Gelubde und Eide, zu verbinden, den Leib zu kasteien, mag der Hausherr kraftigen Oder schwachen, also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Wenn er dazu schweiget von einem Tage zum andern, so bekraftiget er alle seine Gelübde und Verbündnisse, die es auf ihm hat, darum daß er geschwiegen hat des Tages, da er\'s horete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Wird er\'s aber schwachen, nachdem er\'s gehoret hat, so soli er die Missetat tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Das sind die Satzungen, die der HERR Mose geboten hat zwischen Mann und Weib, zwischen Vater und Tochter, weil sie noch eine Magd ist in ihres Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Rache die Kinder Israel an den Midianitern, dafi du danach dich sammelst zu deinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Da redete Mose mit dem Volk und sprach: Rüstet unter euch Leute zum Heer wider die Midianiter, daß sie den HERRN rachen an den Midianitern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'aus jeglichem Stamm tausend, daß ihr aus alien Stammen Israels in das Heer schicket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Und sie nahmen aus den Tausenden Israels, je tausend eines Stamms, zwolftausend gerustet zum Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Und Mose schickte sie mit Pinehas, dem Sohn Eleasars, des Priesters, ins Heer, und die heiligen Kleider und die Halltrommeten in seine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Und sie führeten das Heer wider die Midianiter, wie der HERR Mose geboten hatte, und erwürgeten alles, was mannlich war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Dazu die Konige der Midianiter erwürgeten sie samt ihren Erschlagenen, namlich Evi, Rekem, Zur, Hur und Reba, die fünf Konige der Midianiter. Bileam, den Sohn Beors, erwürgeten sie auch mit dem Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Und die Kinder Israel nahmen gefangen die Weiber der Midianiter und ihre Kinder; all ihr Vieh, alle ihre Habe und alle ihre Güter raubten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Und verbrannten mit Feuer alle ihre Stadte ihrer Wohnung und alle Burgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Und nahmen alien Raub und alles, was zu nehmen war, beide Menschen und Vieh,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'und brachten\'s zu Mose und zu Eleasar, dem Priester, und zu der Gemeine der Kinder Israel, namlich die Gefangenen und das genommene Vieh und das geraubte Gut ins Lager, auf der Moabiter Gefilde, das am Jordan liegt gegen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Und Mose und Eleasar, der Priester, und alle Fursten der Gemeine gingen ihnen entgegen hinaus vor das Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Und Mose ward zornig über die Hauptleute des Heers, die Hauptleute übertausend und uber hundert waren, die aus dem Heer und Streit kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'und sprach zu ihnen: Warum habt ihr alle Weiber leben lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Siehe, haben nicht dieselben die Kinder Israel durch Bileams Rat abgewendet, sich zu versundigen am HERRN uber dem Peor, und widerfuhr eine Plage der Gemeine des HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'So erwurget nun alles, was mannlich ist unter den Kindern, und alle Weiber, die Manner erkannt und beigelegen haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'aber alle Kinder, die Weibsbilde sind und nicht Manner erkannt noch beigelegen haben, die lasset fur euch leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Und lagert euch aulter dem Lager sieben Tage, alle, die jemand erwurget Oder die Erschlagenen angeruhret haben, daß ihr euch entsundiget am dritten und siebenten Tage samt denen, die ihr gefangengenommen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Und alle Kleider und alle Gerate von Fellen und alles Pelzwerk und alles holzerne Gefaft sollt ihr entsundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Und Eleasar, der Priester, sprach zu dem Kriegsvolk, das in Streit gezogen war: Das ist das Gesetz, welches der HERR Mose geboten hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Gold, Silber, Erz, Eisen, Zinn und Blei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'und alles, was das Feuer leidet, sollt ihr durchs Feuer lassen gehen und reinigen, daß es mit dem Sprengwasser entsundiget werde. Aber alles, was nicht Feuer leidet, sollt ihr durchs Wasser gehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Und sollt eure Kleider waschen am siebenten Tage, so werdet ihr rein; danach sollt ihr ins Lager kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Nimm die Summa des Raubes der Gefangenen, beide an Menschen und Vieh, du und Eleasar, der Priester, und die obersten Vater der Gemeine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'und gib die Halfte denen, die ins Heer ausgezogen sind und die Schlacht getan haben, und die andere Halfte der Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Und sollst dem HERRN heben von den Kriegsleuten, die ins Heer gezogen sind, je von funf Hunderten eine Seele, beide an Menschen, Rindern, Eseln und Schafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Von ihrer Halfte sollst du es nehmen und dem Priester Eleasar geben zur Hebe dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Aber von der Halfte der Kinder Israel sollst du je von funfzigen nehmen ein Stuck Guts, beide an Menschen, Rindern, Eseln und Schafen und von allem Vieh, und sollst es den Leviten geben, die der Hut warten der Wohnung des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Und Mose und Eleasar, der Priester, taten, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Und es war der übrigen Ausbeute, die das Kriegsvolk geraubet hatte, sechsmal hundert und funfundsiebenzigtausend Schafe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'zweiundsiebenzigtausend Rinder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'einundsechzigtausend Esel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'und der Weibsbilde, die nicht Manner erkannt, noch beigelegen hatten, zweiunddreilügtausend Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Und die Halfte, die denen, so ins Heer gezogen waren, gehorte, war an der Zahl dreihundertmal und siebenunddreilügtausend und funfhundert Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Davon wurden dem HERRN sechshundertundfunfundsiebenzig Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Item, sechsunddreißigtausend Rinder; davon wurden dem HERRN zweiundsiebenzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Item, dreifügtausend und funfhundert Esel; davon wurden dem HERRN einundsechzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Item, Menschenseelen, sechzehntausend Seelen; davon wurden dem HERRN zwounddreißig Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Und Mose gab solche Hebe des HERRN dem Priester Eleasar, wie ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Aber die andere Halfte, die Mose den Kindern Israel zuteilte von den Kriegsleuten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'namlich die Halfte der Gemeine zustandig, war auch dreihundertmal und siebenunddreilügtausend funfhundert Schafe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'sechsunddreilügtausend Rinder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'dreilügtausend und funfhundert Esel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'und sechzehntausend Menschenseelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Und Mose nahm von dieser Halfte der Kinder Israel je ein Stuck von funfzigen, beide des Viehes und der Menschen, und gab\'s den Leviten, die der Hut warteten an der Wohnung des HERRN, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Und es traten herzu die Hauptleute uber die Tausende des Kriegsvolks, namlich die übertausend und uber hundert waren, zu Mose');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'und sprachen zu ihm: Deine Knechte haben die Summa genommen der Kriegsleute; die unter unsern Handen gewesen sind, und fehlet nicht einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Darum bringen wirdem HERRN Geschenke, was ein jeglicher funden hat von güldenem Gerate, Ketten, Armgeschmeide, Ringe, Ohrenrinken und Spangen, daß unsere Seelen versohnetwerden vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Und Mose nahm von ihnen, samt dem Priester Eleasar das Gold allerlei Gerats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Und alles Goldes Hebe, das sie dem HERRN huben, war sechzehntausend und siebenhundertundfunfzig Sekel von den Hauptleuten fiber tausend und hundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Denn die Kriegsleute hatten geraubet ein jeglicher fur sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Und Mose mit Eleasar, dem Priester, nahm das Gold von den Hauptleuten übertausend und hundert und brachten es in die Hütte des Stiffs zum Gedachtnis der Kinder Israel vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Die Kinder Ruben und die Kinder Gad hatten sehr viel Vieh und sahen das Land Jaeser und Gilead an fur bequeme Statte zu ihrem Vieh;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'und kamen und sprachen zu Mose und zu dem Priester Eleasar und zu den Fursten der Gemeine:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Das Land Ataroth, Dibon, Jaeser, Nimra, Hesbon, Eleale, Sebam, Nebo und Beon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'das der HERR geschlagen hat vor der Gemeine Israel, ist bequem zum Vieh; und wir, deine Knechte, haben Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Und sprachen weiter: Haben wir Gnade vor dir funden, so gib dies Land deinen Knechten zu eigen, so wollen wir nicht über den Jordan ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mose sprach zu ihnen: Eure Bruder sollen in Streit ziehen, und ihr wollt hie bleiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Warum machet ihr der Kinder Israel Herzen wendig, daß sie nicht hinuberziehen in das Land, das ihnen der HERR geben wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Also taten auch eure Vater, da ich sie aussandte von Kades-Barnea, das Land zuschauen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'und da sie hinaufkommen waren bis an den Bach Eskol und sahen das Land, machten sie das Herz der Kinder Israel wendig, daß sie nicht in das Land wollten, das ihnen der HERR geben woilte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Und des HERRN Zorn ergrimmete zur selbigen Zeit und schwur und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Diese Leute, die aus Agypten gezogen sind, von zwanzig Jahren und drüber, sollen ja das Land nicht sehen, das ich Abraham, Isaak und Jakob geschworen habe, darum dafi sie mir nicht treulich nachgefolget haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'ausgenommen Kaleb, den Sohn Jephunnes, des Kenisiters, und Josua, den Sohn Nuns; denn sie haben dem HERRN treulich nachgefolget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Also ergrimmete des HERRN Zorn uber Israel und lieü sie hin und her in der Wuste ziehen vierzig Jahre, bis daß ein Ende ward all des Geschlechts, das ubel getan hatte vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Und siehe, ihr seid aufgetreten an eurer Vater Statt, daß der Sundiger desto mehr seien, und ihr auch den Zorn und Grimm des HERRN noch mehr machet wider Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Denn wo ihr euch von ihm wendet, so wird er auch noch langer sie lassen in der Wuste, und ihr werdet dies Volk alles verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Da traten sie herzu und sprachen: Wir wollen nur Schafhürden hie bauen fur unser Vieh und Stadte fur unsere Kinder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'wir aber wollen uns rüsten vorn an vor die Kinder Israel, bis daß wir sie bringen an ihren Ort. Unsere Kinder sollen in den verschlossenen Stadten bleiben urn der Einwohnerwillen des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Wir wollen nicht heimkehren, bis die Kinder Israel einnehmen ein jeglicher sein Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Denn wir wollen nicht mit ihnen erbenjenseit des Jordans, sondern unser Erbe soil uns diesseit des Jordans gegen dem Morgen gefallen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Mose sprach zu ihnen: Wenn ihr das tun wollt, daß ihr euch rustet zum Streit vor dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'so ziehet über den Jordan vor dem HERRN, wer unter euch gerustet ist, bis daß er seine Feinde austreibe von seinem Angesicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'und das Land untertan werde vor dem HERRN; danach sollt ihr umwenden und unschuldig sein dem HERRN und vor Israel, und sollt dies Land also haben zu eigen vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Wo ihr aber nicht also tun wollt, siehe, so werdet ihr, euch an dem HERRN versundigen und werdet eurer Sunde inne werden, wenn sie euch finden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'So bauet nun Stadte fur eure Kinder und Hürden fur euer Vieh und tut, was ihr geredet habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Die Kinder Gad und die Kinder Ruben sprachen zu Mose: Deine Knechte sollen tun, wie mein Herr geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Unsere Kinder, Weiber, Habe und all unser Vieh sollen in den Stadten Gileads sein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'wir aber, deine Knechte, wollen alle gerustet zum Heer in den Streit ziehen vor dem HERRN, wie mein Herr geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Da gebot Mose ihrethalben dem Priester Eleasar und Josua, dem Sohne Nuns, und den obersten Vatern der Stamme der Kinder Israel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'und sprach zu ihnen: Wenn die Kinder Gad und die Kinder Ruben mit euch über den Jordan ziehen, alle gerustet zum Streit vor dem HERRN, und das Land euch untertan ist, so gebet ihnen das Land Gilead zu eigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ziehen sie aber nicht mit euch gerustet, so sollen sie mit euch erben im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Die Kinder Gad und die Kinder Ruben antworteten und sprachen: Wie der HERR redete zu deinen Knechten, so wollen wir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Wir wollen gerustet ziehen vor dem HERRN ins Land Kanaan und unser Erbgut besitzen diesseit des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Also gab Mose den Kindern Gad und den Kindern Ruben und dem halben Stamm Manasse, des Sohns Josephs, das Konigreich Sihons, des Konigs der Amoriter, und das Konigreich Ogs, des Konigs zu Basan, das Land samt den Stadten in der ganzen Grenze umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Da baueten die Kinder Gad Dibon, Ataroth, Aroer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atroth, Sophan, Jaeser, Jegabeha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beth-Nimra und Beth-Haran, verschlossene Stadte und Schafhürden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Die Kinder Ruben baueten Hesbon, Eleale, Kiriathaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal-Meon, und anderten die Namen, und Sibama; und gaben den Stadten Namen, die sie baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Und die Kinder Machirs, des Sohns Manasses, gingen in Gilead und gewannen es und vertrieben die Amoriter, die drinnen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Da gab Mose dem Machir, dem Sohn Manasses, Gilead; und erwohnete drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair aber, der Sohn Manasses, ging hin und gewann ihre Dorfer und hieß, sie Havoth-Jair.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobah ging hin und gewann Knath mit ihren Tochtern und hiefi sie Nobah nach seinem Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Das sind die Reisen der Kinder Israel, die aus Agyptenland gezogen sind nach ihrem Heer durch Mose und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Und Mose beschrieb ihren Auszug, wie sie zogen, nach dem Befehl des HERRN, und sind namlich dies die Reisen ihres Zugs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Sie zogen aus von Raemses am funfzehnten Tage des ersten Monden, des andern Tages der Ostern, durch eine hohe Hand, daß alle Agypter sahen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'und begruben eben die Erstgeburt, die der HERR unter ihnen geschlagen hatte; denn der HERR hatte auch an ihren Gottern Gerichte geübt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Als sie von Raemses auszogen, lagerten sie sich in Suchoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Und zogen aus von Suchoth und lagerten in Etham, welches liegt an dem Ende der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Von Etham zogen sie aus und blieben im Grunde Hiroth, welches liegt gegen Baal-Zephon, und lagerten sich gegen Migdol.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Von Hiroth zogen sie aus und gingen mitten durchs Meer in die Wuste; und reiseten drei Tagereisen in der Wüste Etham und lagerten sich in Mara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Von Mara zogen sie aus und kamen gen Elim, darin waren zwolf Wasserbrunnen und siebenzig Palmen; und lagerten sich daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Von Elim zogen sie aus und lagerten sich an das Schilfmeer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Von dem Schilfmeer zogen sie aus und lagerten sich in der Wüste Sin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Von der Wuste Sin zogen sie aus und lagerten sich in Daphka.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Von Daphka zogen sie aus und lagerten sich in Alus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Von Alus zogen sie aus und lagerten sich in Raphidim; daselbst hatte das Volk kein Wasser zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Von Raphidim zogen sie aus und lagerten sich in der Wuste Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Von Sinai zogen sie aus und lagerten sich in die Lustgraber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Von den Lustgrabern zogen sie aus und lagerten sich in Hazeroth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Von Hazeroth zogen sie aus und lagerten sich in Rithma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Von Rithma zogen sie aus und lagerten sich in Rimon-Parez.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Von Rimon-Parez zogen sie aus und lagerten sich in Libna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Von Libna zogen sie aus und lagerten sich in Rissa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Von Rissa zogen sie aus und lagerten sich in Kehelatha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Von Kehelatha zogen sie aus und lagerten sich im Gebirge Sapher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Vom Gebirge Sapher zogen sie aus und lagerten sich in Harada.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Von Harada zogen sie aus und lagerten sich in Makeheloth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Von Makeheloth zogen sie aus und lagerten sich in Thahath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Von Thahath zogen sie aus und lagerten sich in Tharah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Von Tharah zogen sie aus und lagerten sich in Mithka.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Von Mithka zogen sie aus und lagerten sich in Hasmona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Von Hasmona zogen sie aus und lagerten sich in Moseroth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Von Moseroth zogen sie aus und lagerten sich in Bne-Jakan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Von Bne-Jakan zogen sie aus und lagerten sich in Horgidgad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Von Horgidgad zogen sie aus und lagerten sich in Jathbatha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Von Jathbatha zogen sie aus und lagerten sich in Abrona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Von Abrona zogen sie aus und lagerten sich in Ezeon-Gaber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Von Ezeon-Gaber zogen sie aus und lagerten sich in der Wüste Zin, das ist Kades.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Von Kades zogen sie aus und lagerten sich an dem Berge Hor, an der Grenze des Landes Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Da ging der Priester Aaron auf den Berg Hor nach dem Befehl des HERRN und starb daselbst im vierzigsten Jahr des Auszugs der Kinder Israel aus Agyptenland, am ersten Tage des funften Monden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'da er hundert und dreiundzwanzig Jahre alt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Und Arad der Konig der Kanaaniter, der da wohnete gegen Mittag des Landes Kanaan, horete, daß die Kinder Israel kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Und von dem Berge Hor zogen sie aus und lagerten sich in Zalmona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Von Zalmona zogen sie aus und lagerten sich in Phunon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Von Phunon zoqen sie aus und laqerten sich in Oboth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Von Oboth zogen sie aus und lagerten sich in Jgim, am Gebirge Abarim in der Moabiter Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Von Jgim zogen sie aus und lagerten sich in Dibon-Gad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Von Dibon-Gad zogen sie aus und lagerten sich in Almon-Diblathaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Von Almon-Diblathaim zogen sie aus und lagerten sich in dem Gebirge Abarim gegen Nebo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Von dem Gebirge Abarim zogen sie aus und lagerten sich in das Gefilde der Moabiter an dem Jordan gegen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Sie lagerten sich aber am Jordan von Beth- Jesimoth bis an die Breite Sittim, des Gefildes der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Und der HERR redete mit Mose in dem Gefilde der Moabiter an dem Jordan gegen Jericho und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr uber den Jordan gegangen seid in das Land Kanaan');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'so sollt ihr alle Einwohner vertreiben vor eurem Angesicht und alle ihre Saulen und alle ihre gegossenen Bilder umbringen und alle ihre Hohen vertilgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'daß ihr also das Land einnehmet und drinnen wohnet; denn euch habe ich das Land gegeben, daß ihr\'s einnehmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Und sollt das Land austeilen durchs Los unter eure Geschlechter. Denen, deren viel ist, sollt ihr desto mehr zuteilen, und denen, deren wenig ist, sollt ihr desto weniger zuteilen. Wie das Los einem jeglichen daselbst fallt, so soli er\'s haben, nach den Stammen ihrer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Werdet ihr aber die Einwohner des Landes nicht vertreiben vor eurem Angesicht, so werden euch die, so ihr überbleiben lasset, zu Dornen werden in euren Augen und zu Stacheln in euren Seiten und werden euch drangen auf dem Lande, da ihr innen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'So wird\'s denn gehen, daß ich euch gleich tun werde, was ich gedachte ihnen zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Gebeut den Kindern Israel und sprich zu ihnen: Wenn ihr ins Land Kanaan kommt, so soli das Land, das euch zum Erbteil fallt im Lande Kanaan, seine Grenze haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Die Ecke gegen Mittag soil anfahen an der Wüste Zin bei Edom, dafi eure Grenze gegen Mittag sei vom Ende des Salzmeers, das gegen Morgen liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'und dal L dieselbe Grenze sich lande vom Mittag hinauf gen Akrabbim und gehe durch Zinna, und sein Ende vom Mittag bis gen Kades-Barnea, und gelange am Dorf Adar und gehe durch Azmon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'und lande sich von Azmon an den Bach Agyptens, und sein Ende sei an dem Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Aber die Grenze gegen dem Abend soil diese sein: namlich das grofie Meer. Das sei eure Grenze gegen dem Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Die Grenze gegen Mitternacht soil diese sein: Ihr sollt messen von dem grolien Meer an den Berg Hor;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'und von dem Berge Hor messen, bis man kommt gen Hamath, daß sein Ausgang sei die Grenze Zedada;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'und desselben Grenze ende gen Siphron, und sei sein Ende am Dorf Enan. Das sei eure Grenze gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Und sollt euch messen die Grenze gegen Morgen vom Dorf Enan gen Sepham;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'und die Grenze gehe herab von Sepham gen Ribla zu Am von morgenwarts; danach gehe sie herab und lenke sich auf die Seiten des Meers Cinereth gegen dem Morgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'und komme herab an den Jordan, dafi ihr Ende sei das Salzmeer. Das sei euer Land mit seiner Grenze umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Und Mose gebot den Kindern Israel und sprach: Das ist das Land, das ihr durchs Los unter euch teilen sollt, das der HERR geboten hat, den neun Stammen und dem halben Stamm zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Denn der Stamm der Kinder Ruben, des Hauses ihres Vaters, und der Stamm der Kinder Gad, des Hauses ihres Vaters, und der halbe Stamm Manasse haben ihr Teilgenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Also haben die zween Stamme und der halbe Stamm ihr Erbteil dahin dies seit des Jordans gegen Jericho, gegen dem Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Das sind die Namen der Manner, die das Land unter euch teilen sollen: Der Priester Eleasar und Josua der Sohn Nuns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Dazu sollt ihr nehmen eines jeglichen Stamms Fursten, das Land auszuteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Und das sind der Manner Namen: Kaleb, der Sohn Jephunnes, des Stamms Juda;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Semuel, der Sohn Ammihuds, des Stamms Simeon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Elidad, der Sohn Chislons, des Stamms Benjamin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Buki, der Sohn Jaglis, Fürst des Stamms der Kinder Dan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Haniel, der Sohn Ephods, Furst des Stamms der Kinder Manasse von den Kindern Josephs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Kemuel, der Sohn Siphtans, Furst des Stamms der Kinder Ephraim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Elizaphan, der Sohn Parnachs, Furst des Stamms der Kinder Sebulon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Paltiel, der Sohn Asans, Fürst des Stamms der Kinder Isaschar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Ahihud, der Sohn Selomis, Furst des Stamms der Kinder Asser;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Pedahel, der Sohn Ammihuds Fürst des Stamms der Kinder Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Dies sind sie, denen der HERR gebot, dad sie den Kindern Israel Erbe austeileten im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Und der HERR redete mit Mose auf dem Gefilde der Moabiter am Jordan gegen Jericho und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Gebeut den Kindern Israel, daß sie den Leviten Stadte geben von ihren Erbgütem, da sie wohnen mogen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'dazu die Vorstadte urn die Stadte her sollt ihr den Leviten auch geben, daß sie in den Stadten wohnen und in den Vorstadten ihr Vieh und Gut und allerlei Tiere haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Die Weite aber der Vorstadte, die sie den Leviten geben, soil tausend Ellen außer der Stadtmauer umher haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'So sollt ihr nun messen außen an der Stadt von der Ecke gegen dem Morgen zweitausend Ellen und von der Ecke gegen Mittag zweitausend Ellen und von der Ecke gegen dem Abend zweitausend Ellen und von der Ecke gegen Mitternacht zweitausend Ellen, daß die Stadt im Mittel sei. Das sollen ihre Vorstadte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Und unter den Stadten, die ihr den Leviten geben werdet, sollt ihr sechs Freistadte geben, daß da hineinfliehe, wereinen Totschlag getan hat. Ober dieselben sollt ihr noch zwoundvierzig Stadte geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'daß alle Stadte, die ihr den Leviten gebet, seien achtundvierzig mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Und sollt derselben desto mehr geben von denen, die viel besitzen unter den Kindern Israel, und desto weniger von denen, die wenig besitzen; ein jeglicher nach seinem Erbteil, das ihm zugeteilet wird, soil Stadte den Leviten geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Und der HERR redete mit Mose und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Rede mit den Kindern Israel und sprich zu ihnen: Wenn ihr uber den Jordan ins Land Kanaan kommt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'sollt ihr Stadte auswahlen, daß Freistadte seien; dahin fliehe, dereinen Totschlag unversehens tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Und sollen unter euch solche Freistadte sein vor dem Blutracher, daß der nicht sterben müsse, der einen Totschlag getan hat, bis daß er vor der Gemeine vor Gericht gestanden sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Und der Stadte, die ihr geben werdet, sollen sechs Freistadte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Drei sollt ihr geben diesseit des Jordans und drei im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Das sind die sechs Freistadte, beide den Kindern Israel und den Fremdlingen und den Hausgenossen unter euch, daß dahin fliehe, wer einen Totschlag getan hat unversehens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Werjemand miteinem Eisen schlagt, daß er stirbt, der ist ein Totschlager und soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Wirft er ihn mit einem Stein, damit jemand mag getotet werden, daß er davon stirbt, so ist er ein Totschlager und soli des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Schlagt er ihn aber mit einem Holz, damit jemand mag totgeschlagen werden, daß er stirbt, so ist er ein Totschlager und soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Der Racher des Bluts soil den Totschlager zum Tode bringen; wie er geschlagen hat, soil man ihn wiedertoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Stolit er ihn aus Hali, Oder wirft etwas auf ihn aus List, daß er stirbt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Oder schlagt ihn durch Feindschaft mit seiner Hand, daß er stirbt, so soil der des Todes sterben, der ihn geschlagen hat; denn er ist ein Totschlager; der Racher des Bluts soil ihn zum Tode bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Wenn er ihn aber ohngefahr stolit ohne Feindschaft, Oder wirft irgend etwas auf ihn unversehens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Oder irgend einen Stein, davon man sterben mag, und hat\'s nicht gesehen, auf ihn wirft, daß er stirbt, und er ist nicht sein Feind, hat ihm auch kein Ubels gewollt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'so soil die Gemeine richten zwischen dem, der geschlagen hat, und dem Racher des Bluts in diesem Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Und die Gemeine soil den Totschlager erretten von der Hand des Blutrachers und soil ihn wiederkommen lassen zu der Freistadt, dahin er geflohen war; und soil daselbst bleiben, bis daß der Hohepriester sterbe, den man mit dem heiligen 01 gesalbet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Wird aber der Totschlager aus seiner Freistadt Grenze gehen, dahin er geflohen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'und der Blutracher findet ihn aulier der Grenze seiner Freistadt und schlagt ihn tot, der soil des Bluts nicht schuldig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Denn er sollte in seiner Freistadt bleiben bis an den Tod des Hohenpriesters, und nach des Hohenpriesters Tod wiederzum Lande seines Erbguts kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Das soil euch ein Recht sein bei euren Nachkommen, wo ihrwohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Den Totschlager soil man toten nach dem Mund zweier Zeugen. Ein Zeuge soil nicht antworten fiber eine Seele zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Und ihr sollt keine Versohnung nehmen fiber die Seele des Totschlagers; denn er ist des Todes schuldig, und er soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Und sollt keine Versohnung nehmen fiber dem, der zur Freistadt geflohen ist, daß er wiederkomme, zu wohnen im Lande, bis der Priester sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Und schandet das Land nicht, darinnen ihr wohnet. Denn wer Blut schuldig ist, der schandet das Land; und das Land kann vom Blut nicht versohnet werden, das darinnen vergossen wird, ohne durch das Blut des, der es vergossen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Verunreiniget das Land nicht, darinnen ihr wohnet, darinnen ich auch wohne; denn ich bin der HERR, der unter den Kindern Israel wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Und die obersten Vater der Geschlechter der Kinder Gileads, des Sohns Machirs, der Manasses Sohn war, von dem Geschlecht der Kinder Joseph, traten herzu und redeten vor Mose und vor den Fürsten der obersten Vater der Kinder Israel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'und sprachen: Lieber Herr, der HERR hat geboten, daß man das Land zum Erbteil geben sollte durchs Los den Kindern Israel; und du, mein Herr, hast geboten durch den HERRN, daß man das Erbteil Zelaphehads, unsers Bruders, seinen Tochtern geben soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Wenn sie jemand aus den Stammen der Kinder Israel zu Weibern nimmt, so wird unsers Vaters Erbteil weniger werden, und so viel sie haben, wird zu dem Erbteil kommen des Stamms, dahin sie kommen; also wird das Los unsers Erbteils geringert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Wenn denn nun das Halljahr der Kinder Israel kommt, so wird ihr Erbteil zu dem Erbteil des Stamms kommen, da sie sind; also wird unsers Vaters Erbteil geringert, soviel sie haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Mose gebot den Kindern Israel nach dem Befehl des HERRN und sprach: Der Stamm der Kinder Joseph hat recht geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Das ist\'s, das der HERR gebeut den Tochtern Zelaphehads und spricht: Lali sie freien, wie es ihnen gefallt, allein daß sie freien unter dem Geschlecht des Stamms ihres Vaters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'auf daß nicht die Erbteile der Kinder Israel fallen von einem Stamm zum andern; denn ein jeglicher unter den Kindern Israel soil anhangen an dem Erbe des Stamms seines Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Und alle Tochter, die Erbteil besitzen unter den Stammen der Kinder Israel, sollen freien einen von dem Geschlecht des Stamms ihres Vaters, auf daß ein jeglicher unter den Kindern Israel seines Vaters Erbe behalte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'und nicht ein Erbteil von einem Stamm falle auf den andern, sondern ein jeglicher hange an seinem Erbe unter den Stammen der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Wie der HERR Mose geboten hatte, so taten die Tochter Zelaphehads,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Mahela, Thirza, Hagla, Milka und Noa, und freieten die Kinder ihrer Vettern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'des Geschlechts der Kinder Manasses, des Sohns Josephs. Also blieb ihr Erbteil an dem Stamm des Geschlechts ihres Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Das sind die Gebote und Rechte, die der HERR gebot durch Mose den Kindern Israel auf dem Gefilde der Moabiter am Jordan gegen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Das sind die Worte, die Mose redete zum ganzen Israel jenseit des Jordans in der Wuste, auf dem Gefilde gegen dem Schilfmeer, zwischen Paran und Thophel, Laban, Hazeroth und Disahab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'elf Tagreisen von Horeb durch den Weg des Gebirges Seir bis gen Kades-Barnea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Und es geschah im vierzigsten Jahr, am ersten Tage des elften Monden, da redete Mose mit den Kindern Israel alles, wie ihm der HERR an sie geboten hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'nachdem er Sihon, den Konig der Amoriter, geschlagen hatte, derzu Hesbon wohnete, dazu Og, den Konig zu Basan, derzu Astharoth und zu Edrei wohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Jenseit des Jordans im Lande der Moabiter fing an Mose auszulegen dies Gesetz, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Der HERR, unser Gott, redete mit uns am Berge Horeb und sprach: Ihr seid lange genug an diesem Berge gewesen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'wendet euch und ziehet hin, daß ihr zu dem Gebirge der Amoriter kommet und zu alien ihren Nachbarn im Gefilde, auf Bergen und in Grunden, gegen Mittag und gegen die Anfurt des Meers im Lande Kanaan, und zum Berge Libanon bis an das grolie Wasser Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Siehe da, ich habe euch das Land, das da vor euch liegt, gegeben; gehet hinein und nehmet es ein, das der HERR euren Vatern, Abraham, Isaak und Jakob, geschworen hat, daß er\'s ihnen und ihrem Samen nach ihnen geben wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Da sprach ich zu derselben Zeit zu euch: Ich kann euch nicht allein ertragen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'denn der HERR euer Gott, hat euch gemehret, daß ihr heutigestages seid wie die Menge der Sterne am Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Der HERR, eurer Vater Gott, mache euer noch viel tausend mehr und segne euch, wie er euch geredet hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Wie kann ich allein solche Mühe und Last und Hader von euch ertragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Schaffet herweise, verstandige und erfahrene Leute unter euren Stammen, die will ich uber euch zu Hauptern setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Da antwortetet ihr mir und sprachet: Das istein gut Ding, davon du sagest, daß du es tun willst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Da nahm ich die Haupter eurer Stamme, weise und erfahrene Manner, und setzte sie uber euch zu Hauptern, uber tausend, uber hundert, uber fünfzig und uber zehn, und Amtleute unter euren Stammen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'und gebot euren Richtern zur selben Zeit und sprach: Verhoret eure Bruder und richtet recht zwischen jedermann und seinem Bruder und dem Fremdling.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Keine Person sollt ihr im Gericht ansehen, sondern sollt den Kleinen horen wie den Groften und vor niemandes Person euch scheuen. Denn das Gerichtamt ist Gottes. Wird aber euch eine Sache zu hart sein, die lasset an mich gelangen, daß ich sie hore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Also gebot ich euch zu der Zeit alles, was ihrtun solltet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Da zogen wir aus von Horeb und wandelten durch die ganze Wuste, die graft und grausam ist, wie ihr gesehen habt, auf der Strafte zum Gebirge der Amoriter, wie uns der HERR, unser Gott, geboten hatte, und kamen bis gen Kades-Barnea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Da sprach ich zu euch: Ihr seid an das Gebirge der Amoriter kommen, das uns der HERR, unser Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Siehe da das Land vor dir, das der HERR, dein Gott, dirgegeben hat; zeuch hinauf und nimm\'s ein, wie der HERR, deiner Vater Gott, dir geredet hat. Furchte dich nicht und laft dir nicht grauen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Da kamet ihr zu mir alle und sprachet: Laftt uns Manner vor uns hinsenden, die uns das Land erkunden und uns wieder sagen, durch welchen Weg wir hineinziehen sollen, und die Stadte, da wir einkommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Das gefiel mirwohl und nahm aus euch zwolf Manner, von jeglichem Stamm einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Da dieselbigen weggingen und hinaufzogen auf das Gebirge und an den Bach Eskol kamen, da besahen sie es');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'und nahmen der Fruchte des Landes mit sich und brachten sie herab zu uns; und sagten uns wieder und sprachen: Das Land ist gut, das der HERR, unser Gott, uns gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Aber ihr wolltet nicht hinaufziehen und wurdet ungehorsam dem Munde des HERRN, eures Gottes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'und murretet in euren Hutten und sprachet: Der HERR ist uns gram; darum hat er uns aus Agyptenland gefuhret, daß er uns in der Amoriter Hande gabe zu vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Wo sollen wir hinauf? Unsere Bruder haben unser Herz verzagt gemacht und gesagt, das Volk sei grafter und hoher denn wir; die Stadte seien graft und bis an den Himmel vermauert; dazu haben wir die Kinder Enakim daselbst gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Ich sprach aber zu euch: Entsetzet euch nicht und furchtet euch nicht vor ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Der HERR, euer Gott, zeucht vor euch hin und wird fur euch streiten, wie er mit euch getan hat in Agypten vor euren Augen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'und in der Wuste, da du gesehen hast, wie dich der HERR, dein Gott, getragen hat, wie ein Mann seinen Sohn tragt, durch alien Weg, daher ihr gewandelt habt, bis ihr an diesen Ort kommen seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Aber das gait nichts bei euch, daß ihr an den HERRN, euren Gott, hattet geglaubet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'der vor euch her ging, euch die Statte zu weisen, wo ihr euch lagern solltet, des Nachts im Feuer, daß ereuch den Weg zeigete, darinnen ihrgehen solltet, und des Tages in der Wolke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Als aber der HERR euer Geschrei horete, ward er zornig und schwur und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Es soil keiner dieses bosen Geschlechts das gute Land sehen, das ich ihren Vatern zu geben geschworen habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'ohne Kaleb, der Sohn Jephunnes, der soil es sehen, und ihm will ich geben das Land, darauf er getreten hat, und seinen Kindern, darum daß er treulich dem HERRN gefolget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Auch ward der HERR uber mich zornig urn euretwillen und sprach: Du sollst auch nicht hineinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Aber Josua, der Sohn Nuns, der dein Diener ist, der soil hineinkommen. Denselben starke; denn er soil Israel das Erbe austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Und eure Kinder, davon ihr sagtet, sie würden ein Raub werden, und eure Sohne, die heutigestages weder Gutes noch Boses verstehen, die sollen hineinkommen; denselben will ich\'s geben, und sie sollen es einnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ihr aber wendet euch und ziehet nach der Wuste den Weg zum Schilfmeer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Da antwortetet ihr und sprachet zu mir: Wir haben an dem HERRN gesundiget; wirwollen hinauf und streiten, wie uns der HERR, unser Gott, geboten hat. Da ihr euch nun rustetet, ein jeglicher mit seinem Harnisch, und waret an dem, daß ihr hinaufzoget aufs Gebirge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'sprach der HERR zu mir: Sage ihnen, daß sie nicht hinaufziehen, auch nicht streiten; denn ich bin nicht unter euch; auf daß ihr nicht geschlagen werdet vor euren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Da ich euch das sagte, gehorchtet ihr nicht und wurdet ungehorsam dem Munde des HERRN und waret vermessen und zoget hinauf aufs Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Da zogen die Amoriter aus, die auf dem Gebirge wohneten, euch entgegen, und jagten euch, wie die Bienen tun, und schlugen euch zu Seir bis gen Horma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Da ihr nun wiederkamet und weinetet vor dem HERRN, wollte der HERR eure Stimme nicht horen und neigete seine Ohren nicht zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Also bliebet ihr in Kades eine lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Da wandten wir uns und zogen aus zur Wuste auf der Strafte zum Schilfmeer, wie der HERR zu mir sagte, und umzogen das Gebirge Seir eine lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Und der HERR sprach zu mir:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Ihr habt dies Gebirge nun genug umzogen; wendet euch gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Und gebeut dem Volk und sprich: Ihr werdet durch die Grenze eurer Bruder, der Kinder Esau, ziehen, die da wohnen zu Seir; und sie werden sich vor euch furchten. Aber verwahret euch mit Fleift,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'daß ihr sie nicht bekrieget; denn ich werde euch ihres Landes nicht einen Fuftbreit geben; denn das Gebirge Seir habe ich den Kindern Esau zu besitzen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Speise sollt ihr urns Geld von ihnen kaufen, daß ihr esset, und Wasser sollt ihr urns Geld von ihnen kaufen, daß ihr trinket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Denn der HERR, dein Gott, hat dich gesegnet in alien Werken deiner Hande. Er hat dein Reisen zu Herzen genommen durch diese große Wuste und ist vierzig Jahre der HERR, dein Gott, bei dirgewesen, daß dir nichts gemangelt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Da wir nun durch unsere Bruder, die Kinder Esau, gezogen waren, die auf dem Gebirge Seir wohneten, auf dem Wege des Gefildes von Elath und Ezeon- Gaber, wandten wir uns und gingen durch den Weg der Wuste der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Da sprach der HERR zu mir: Du sollst die Moabiter nicht beleidigen noch bekriegen; denn ich will dir ihres Landes nichts zu besitzen geben, denn ich habe Ar den Kindern Lot zu besitzen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Die Emim haben vorzeiten drinnen gewohnet; das war ein groß, stark und hoch Volk wie die Enakim');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Man hielt sie auch fur Riesen, gleichwie Enakim; und die Moabiter heißen sie auch Emim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Auch wohneten vorzeiten in Seir die Horiter; und die Kinder Esau vertrieben und vertilgten sie von ihnen und wohneten an ihrer Statt, gleichwie Israel dem Lande seiner Besitzung tat, das ihnen der HERR gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'So macht euch nun auf und ziehet durch den Bach Sared. Und wir zogen herdurch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Die Zeitaber, die wir von Kades-Barnea zogen, bis wir durch den Bach Sared kamen, war achtunddreißig Jahre, auf daß alle die Kriegsleute sturben im Lager, wie der HERR ihnen geschworen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Dazu war auch die Hand des HERRN wider sie, daß sie umkamen aus dem Lager, bis daß ihrer ein Ende wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Und da alle der Kriegsleute ein Ende war, daß sie starben unter dem Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'redete der HERR mit mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Du wirst heute durch die Grenze der Moabiter ziehen bei Ar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'und wirst nahe kommen gegen die Kinder Ammon. Die sollst du nicht beleidigen noch bekriegen; denn ich will dir des Landes der Kinder Ammon nichts zu besitzen geben, denn ich hab\'s den Kindern Lot zu besitzen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Es ist auch geschatzt fur der Riesen Land, und haben auch vorzeiten Riesen drinnen gewohnet; und die Ammoniter heißen sie Sammesumim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Das war ein groß, stark und hoch Volk, wie die Enakim; und der HERR vertilgete sie vor ihnen und ließ sie dieselben besitzen, daß sie an ihrer Statt da wohneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'gleichwie er getan hat mit den Kindern Esau, die auf dem Gebirge Seir wohnen, da er die Horiter vor ihnen vertilgete, und ließ sie dieselben besitzen, daß sie da an ihren Statt wohneten bis auf diesen T ag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Und die Kaphthorim zogen aus Kaphthor und vertilgeten die Avim, die zu Hazerim wohneten bis gen Gaza, und wohneten an ihrer Statt daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Machet euch auf und ziehet aus und gehet uber den Bach bei Arnon. Siehe, ich habe Sihon, den Konig der Amoriter zu Hesbon, in deine Hande gegeben mit seinem Lande. Heb an einzunehmen, und streite wider ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Heutigestages will ich anheben, daß sich von dir furchten und erschrecken sollen alle Volker unter alien Himmeln, daß, wenn sie von dir horen, ihnen bange und wehe werden soil vor deiner Zukunft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Da sandte ich Boten aus der Wuste von morgenwarts zu Sihon, dem Konige zu Hesbon, mit friedlichen Worten und ließ ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Ich will durch dein Land ziehen, und wo die Straße gehet, will ich gehen; ich will weder zur Rechten noch zur Linken ausweichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Speise sollst du mir urns Geld verkaufen, daß ich esse, und Wasser sollst du mir urns Geld geben, daß ich trinke; ich will nurzu Fuß durchhin gehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'wie mir die Kinder Esau getan haben, die zu Seir wohnen, und die Moabiter, die zu Ar wohnen; bis daß ich komme uber den Jordan, in das Land, das uns der HERR, unser Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Aber Sihon, der Konig zu Hesbon, wollte uns nicht durchziehen lassen; denn der HERR, dein Gott, verhartete seinen Mut und verstockte ihm sein Herz, auf daß er ihn in deine Hande gabe, wie es jetzt ist am Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Und der HERR sprach zu mir: Siehe, ich habe angefangen, zu geben vor dir den Sihon mit seinem Lande; hebet an, einzunehmen und zu besitzen sein Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Und Sihon zog aus uns entgegen mit all seinem Volk zum Streit gen Jahza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Aber der HERR, unser Gott, gab ihn vor uns, daß wir ihn schlugen mit seinen Kindern und seinem ganzen Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Da gewannen wir zu den Zeit alle seine Stadte und verbanneten alle Stadte, beide Manner, Weiber und Kinder, und ließen niemand uber bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Ohne das Vieh raubten wir fur uns und die Ausbeute der Stadte, die wir gewannen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'von Aroer an, die am Ufer des Bachs bei Arnon liegt, und von der Stadt am Wasser bis gen Gilead. Es war keine Stadt, die sich vor uns schutzen konnte; der HERR, unser Gott, gab uns alles vor uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Ohne zu dem Lande der Kinder Ammon kamest du nicht, noch zu allem, das am Bach Jabbok war, noch zu den Stadten auf dem Gebirge, noch zu allem, das uns der HERR, unser Gott, verboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Und wir wandten uns und zogen hinauf den Weg zu Basan. Und Og, der Konig zu Basan, zog aus uns entgegen mit all seinem Volk, zu streiten bei Edrei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Aber der HERR sprach zu mir: Furchte dich nicht vor ihm, denn ich habe ihn und all sein Volk mit seinem Lande in deine Hande gegeben; und sollst mit ihm tun, wie du mit Sihon, dem Konige der Amoriter, getan hast, der zu Hesbon saft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Also gab der HERR unser Gott, auch den Konig Og zu Basan in unsere Hande mit all seinem Volk, daß wir ihn schlugen, bis daß ihm nichts uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Da gewannen wir zu der Zeit alle seine Stadte, und war keine Stadt, die wir ihm nicht nahmen; sechzig Stadte, die ganze Gegend Argob, im Konigreich Ogs zu Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Alle diese Stadte waren test, mit hohen Mauern, Toren und Riegeln, ohne andere sehrviel Flecken ohne Mauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Und verbanneten sie, gleichwie wir mit Sihon, dem Konige zu Hesbon, taten. Aile Stadte verbanneten wir, beide mit Mannern, Weibern und Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Aber alles Vieh und Raub der Stadte raubten wir fur uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Also nahmen wir zu der Zeit das Land aus der Hand der zween Konige der Amoriter jenseit des Jordans, von dem Bach bei Arnon an bis an den Berg Hermon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'welchen die Zidonier Sirion heifien, aber die Amoriter heiften ihn Senir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'alle Stadte auf der Ebene und das ganze Gilead und das ganze Basan bis gen Salcha und Edrei, die Stadte des Konigreichs Ogs zu Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Denn allein der Konig Og zu Basan war noch ubrig von den Riesen. Siehe, sein eisern Bette ist allhie zu Rabbath der Kinder Ammon, neun Ellen lang und vier Ellen breit nach eines Mannes Ellenbogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Solch Land nahmen wirein zu derselben Zeit, von Aroer an, die am Bach bei Arnon liegt. Und ich gab das halbe Gebirge Gilead mitseinen Stadten den Rubenitern und Gaditern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Aber das übrige Gilead und das ganze Basan des Konigreichs Ogs gab ich dem halben Stamm Manasse, die ganze Gegend Argob zum ganzen Basan; das heifit der Riesen Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, der Sohn Manasses, nahm die ganze Gegend Argob bis an die Grenze Gessuri und Maachathi; und hiefi das Basan nach seinem Namen Havoth-Jair bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Machir aber gab ich Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Und den Rubenitern und Gaditern gab ich des Gileads einen Teil bis an den Bach bei Arnon mitten im Bach, der die Grenze ist, und bis an den Bach Jabbok, der die Grenze ist der Kinder Ammon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'dazu das Gefilde und den Jordan, der die Grenze ist, von Cinnereth an bis an das Meer am Gefilde, namlich das Salzmeer, unten am Berge Pisga gegen dem Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Und gebot euch zu derselben Zeit und sprach: Der HERR, euer Gott, hat euch dies Land gegeben einzunehmen; ziehet nun gerustet vor euren Brüdem, den Kindern Israel, her, was streitbar ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'ohne eure Weiber und Kinder und Vieh (denn ich weift, daß ihr viel Vieh habt) lasset in euren Stadten bleiben, die ich euch gegeben habe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'bis daß den HERR eure Bruder auch zur Ruhe bringe, wie euch, daß sie auch das Land einnehmen, das ihnen der HERR, euer Gott, geben wird jenseit des Jordans; so sollt ihn dann wiederkehren zu euren Besitzung, die ich euch gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Und Josua gebot ich zur selben Zeit und sprach: Deine Augen haben gesehen alles, was der HERR, euer Gott, diesen zween Konigen getan hat. Also wird der HERR auch alien Konigreichen tun, da du hinzeuchst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Furchtet euch nicht vor ihnen; denn der HERR, euer Gott, streitet fur euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Und ich bat den HERRN zu derselben Zeit und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Herr, HERR, du hastangehoben zu erzeigen deinem Knechte deine Herrlichkeit und deine starke Hand. Denn wo ist ein Gott im Himmel und auf Erden, der es deinen Werken und deiner Macht konnte nachtun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Laü mich gehen und sehen das gute Land jenseit des Jordans, dies gute Gebirge und den Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Aber der HERR war erzurnet auf mich urn euretwillen und erhorete mich nicht, sondern sprach zu mir: Laü genug sein, sage mir davon nicht mehr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Steige auf die Hohe des Berges Pisga und hebe deine Augen auf gegen den Abend und gegen Mitternacht und gegen Mittag und gegen den Morgen, und sieh es mit Augen; denn du wirst nicht uber diesen Jordan gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Und gebeut dem Josua, daß er getrost und unverzagt sei; denn er soli uber den Jordan ziehen vor dem Volk her und soil ihnen das Land austeilen, das du sehen wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Also blieben wir im Tal gegen dem Hause Peor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Und nun hore, Israel, die Gebote und Rechte, die ich euch lehre, daß ihr sie tun sollt, auf daß ihr lebet und hineinkommet und das Land einnehmet, das euch der HERR, euer Vater Gott, gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ihr sollt nichts dazutun, das ich euch gebiete, und sollt auch nichts davontun, auf daß ihr bewahren moget die Gebote des HERRN, eures Gottes, die ich euch gebiete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Eure Augen haben gesehen, was der HERR getan hat wider den Baal-Peor; denn alle, die dem Baal-Peor folgeten, hat den HERR, dein Gott, vertilget unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Aber ihr, die ihr dem HERRN, eurem Gott, anhinget, lebet alle heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Siehe, ich habe euch gelehret Gebote und Rechte, wie mir den HERR, mein Gott, geboten hat, daß ihr also tun sollt im Lande, darein ihr kommen werdet, daß ihr\'s einnehmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'So behaltet es nun und tut\'s! Denn das wird eure Weisheit und Verstand sein bei alien Volkern, wenn sie horen werden alle diese Gebote, dafi sie mussen sagen: Ei, welch weise und verstandige Leute sind das, und ein herrlich Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Denn wo ist so ein herrlich Volk, zu dem Gotter also nahe sich tun, als der HERR, unser Gott, so oft wir ihn anrufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Und wo ist so ein herrlich Volk, das so gerechte Sitten und Gebote habe, als all dies Gesetz; das ich euch heutigestages vorlege?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Hute dich nur und bewahre deine Seele wohl, daß du nicht vergessest der Geschichten, die deine Augen gesehen haben, und daü sie nicht aus deinem Herzen kommen all dein Leben lang. Und sollst deinen Kindern und Kindeskindern kundtun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'den Tag, da du vor dem HERRN, deinem Gott, stundest an dem Berge Horeb, da der HERR zu mir sagte: Versammle mir das Volk, daü sie meine Worte horen und lernen mich furchten all ihre Lebetage auf Erden und lehren ihre Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Und ihr tratet herzu und stundet unten an dem Berge; der Berg brannte aber bis mitten an den Himmel; und war da Finsternis, Wolken und Dunkel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Und den HERR redete mit euch mitten aus dem Feuer. Die Stimme seiner Worte hortet ihr; aber kein Gleichnis sahet ihr außen der Stimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Und verkündigte euch seinen Bund, den er euch gebot zu tun, namlich die zehn Worte; und schrieb sie auf zwo steinerne Tafeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Und der HERR gebot mir zur selbigen Zeit, daü ich euch lehren sollte Gebote und Rechte, daß ihn danach tatet im Lande, darein ihr ziehet, daß ihr es einnehmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'So bewahret nun eure Seelen wohl; denn ihr habt kein Gleichnis gesehen des Tages, da der HERR mit euch redete aus dem Feuer auf dem Berge Horeb,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'auf daß ihr euch nicht verderbet und machet euch irqend ein Bild, das gleich sei einem Mann Oder Weib');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Oder Vieh auf Erden, Oder Vogel unter dem Himmel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Oder Gewurm auf dem Lande, Oder Fisch im Wasser unter der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Dafi du auch nicht deine Augen aufhebest gen Himmel und sehest die Sonne und den Mond und die Sterne, das ganze Heer des Himmels, und fallest ab und betest sie an und dienest ihnen, welche der HERR, dein Gott, verordnet hat alien Volkern unter dem ganzen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Euch aber hat den HERR angenommen und aus dem eisernen Ofen, namlich aus Agypten, gefuhret, daß ihr sein Erbvolk solltet sein, wie es ist an diesem Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Und der HERR war so erzurnet uber mich urn eures Tuns willen, daß er schwur, ich sollte nicht uber den Jordan gehen, noch in das gute Land kommen, das dir der HERR, dein Gott, zum Erbteil geben wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'sondern ich muß in diesem Lande sterben und werde nicht uber den Jordan gehen. Ihr aber werdet hinubergehen und solch gut Land einnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'So hutet euch nun, daß ihr des Bundes des HERRN, eures Gottes, nicht vergesset, den er mit euch gemacht hat, und nicht Bilder machet einigerlei Gleichnis, wie der HERR, dein Gott, geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Denn der HERR, dein Gott, ist ein verzehrend Feuer und ein eifriger Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Wenn ihr nun Kinder zeuget und Kindeskinder und im Lande wohnet und verderbet euch und machet euch Bilder einigerlei Gleichnis, daß ihr ubel tut vor dem HERRN, eurem Gott, und ihr ihn erzurnet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'so rufe ich heutigestages uber euch zu Zeugen Himmel und Erde, daß ihr werdet bald umkommen von dem Lande, in welches ihrgehet uber den Jordan, daß ihr\'s einnehmet; ihr werdet nicht lange drinnen bleiben, sondern werdet vertilget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Und der HERR wird euch zerstreuen unter die Vblker; und werdet ein geringer Pobel übrig sein unter den Heiden, dahin euch der HERR treiben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Daselbst wirst du dienen den Gottern, die Menschenhande Werk sind, Holz und Stein, die weder sehen, noch horen, noch essen, noch riechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Wenn du aber daselbst den HERRN, deinen Gott, suchen wirst, so wirst du ihn finden, wo du ihn wirst von ganzem Herzen und von ganzer Seele suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Wenn du geangstet sein wirst, und dich treffen werden alle diese Dinge in den letzten Tagen, so wirst du dich bekehren zu dem HERRN, deinem Gott, und seiner Stimme gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Denn der HERR, dein Gott, ist ein barmherziger Gott; erwird dich nicht lassen noch verderben, wird auch nicht vergessen des Bundes, den er deinen Vatern geschworen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Dann frage nach den vorigen Zeiten, die vor dir gewesen sind, von dem Tage an, da Gott den Menschen auf Erden geschaffen hat, von einem Ende des Himmels zum andern, ob je ein solch groß Ding geschehen, Oder des Gleichen je gehoret sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'daß ein Volk Gottes Stimme gehort habe aus dem Feuer reden, wie du gehort hast, und dennoch lebest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Oderob Gottversucht habe, hineinzugehen und ihm ein Volk mitten aus einem Volk zu nehmen durch Versuchung, durch Zeichen, durch Wunder, durch Streit und durch eine machtige Hand und durch einen ausgereckten Arm und durch sehr schreckliche Taten, wie das alles der HERR, euer Gott, fur euch getan hat in Agypten vor deinen Augen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Du hast\'s gesehen, auf daß du wissest, daß der HERR allein Gott ist, und keiner mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Vom Himmel hat er dich seine Stimme horen lassen, daß er dich züchtigte; und auf Erden hat er dir gezeiget sein grolies Feuer, und seine Worte hast du aus dem Feuer gehoret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'darum daß er deine Vater geliebet und ihren Samen nach ihnen erwahlet hat, und hat dich ausgeführet mit seinem Angesicht durch seine grofie Kraft aus Agypten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'daß er vertriebe vor dir her grolie Volker und starkere, denn du bist, und dich hineinbrachte, daß er dir ihr Land gabe zum Erbteil, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'So sollst du nun heutigestages wissen und zu Flerzen nehmen, daß der HERR ein Gott ist oben im Himmel und unten auf Erden, und keiner mehr;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'daß du haltest seine Rechte und Gebote, die ich dir heute gebiete; so wird dir\'s und deinen Kindern nach dirwohlgehen, daß dein Leben lange wahre in dem Lande, das dir der HERR, dein Gott, gibt ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Da sonderte Mose drei Stadte aus jenseits des Jordans gegen der Sonnen Aufgang,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'daß daselbst hinflohe, wer seinen Nachsten totschlagt unversehens und ihm vorhin nicht feind gewesen ist; der soil in der Stadte eine fliehen, daß er lebendig bleibe:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer in der Wüste im ebenen Lande unter den Rubenitern; und Ramoth in Gilead unter den Gaditern; und Golan in Basan unter den Manassitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Das ist das Gesetz, das Mose den Kindern Israel vorlegte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Das ist das Zeugnis und Gebot und Rechte, die Mose den Kindern Israel sagte, da sie aus Agypten gezogen waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'jenseit des Jordans im Tal gegen dem Hause Peor, im Lande Sihons, des Konigs der Amoriter, den zu Hesbon sali, den Mose und die Kinder Israel schlugen, da sie aus Agypten gezogen waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'und nahmen sein Land ein, dazu das Land Ogs, des Konigs zu Basan, der zween Konige der Amoriter, die jenseit des Jordans waren gegen der Sonnen Aufgang,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'von Aroer an, welche an dem Ufer liegt des Bachs bei Arnon, bis an den Berg Sion, das ist der Hermon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'und alles Blachfeld jenseits des Jordans, gegen den Aufgang der Sonne, bis an das Meer im Blachfelde, unten am Berge Pisga.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Und Mose rief das ganze Israel und sprach zu ihnen: Hore, Israel, die Gebote und Rechte, die ich heute vor euren Ohren rede, und lernet sie und behaltet sie, dafi ihr danach tut!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Der HERR, unser Gott, hat einen Bund mit uns gemachtzu Horeb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Und hat nicht mit unsern Vatern diesen Bund gemacht, sondern mit uns, die wir hie sind heutigestages und alle leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Er hat von Angesicht zu Angesicht mit uns aus dem Feuer auf dem Berge geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ich stund zu derselben Zeit zwischen dem HERRN und euch, daß ich euch ansagte des HERRN Wort; denn ihn furchtetet euch vor dem Feuer und ginget nicht auf den Berg. Und er sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ich bin der HERR, dein Gott, der dich aus Agyptenland gefuhret hat, aus dem Diensthause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du sollst keine andern Gotter haben vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du sollst dir kein Bildnis machen einigerlei Gleichnis, weder oben im Himmel, noch unten auf Erden, noch im Wasser unter der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du sollst sie nicht anbeten noch ihnen dienen. Denn ich bin der HERR, dein Gott, ein eifriger Gott, der die Missetat der Vater heimsucht über die Kinder ins dritte und vierte Glied, die mich hassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'und Barmherzigkeit erzeige in viel tausend, die mich lieben und meine Gebote halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du sollst den Namen des HERRN, deines Gottes, nicht mitibrauchen; denn der HERR wird den nicht ungestraft lassen, der seinen Namen mitibrauchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Den Sabbattag sollst du halten, daß du ihn heiligest, wie dir der HERR, dein Gott, geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sechs Tage solist du arbeiten und alle deine Werke tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Aber am siebenten Tage ist der Sabbat des HERRN, deines Gottes. Da sollst du keine Arbeit tun, noch dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, noch dein Ochse, noch dein Esel, noch all dein Vieh, noch der Fremdling, der in deinen Toren ist, auf daß dein Knecht und deine Magd ruhe, gleichwie du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Denn du sollst gedenken, daß du auch Knecht in Agyptenland warst, und der HERR, dein Gott, dich von dannen ausgeführet hat mit einer machtigen Hand und ausgerecktem Arm. Darum hat dir der HERR, dein Gott, geboten, daß du den Sabbattag halten sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Du sollst deinen Vater und deine Mutter ehren, wie dir der HERR, dein Gott, geboten hat, auf daß du lange lebest, und daß dir\'s wohlgehe in dem Lande, das dir der HERR, dein Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du sollst nicht toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Du sollst nicht ehebrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Du sollst nicht stehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Du sollst kein falsch Zeugnis reden wider deinen Nachsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Lali dich nicht gelusten deines Nachsten Weib. Du sollst nicht begehren deines Nachsten Haus, Acker, Knecht, Magd, Ochsen, Esel noch alles, was sein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Das sind die Worte, die der HERR redete zu euren ganzen Gemeine auf dem Berge aus dem Feuer und der Wolke und Dunkel mit grolier Stimme, und tat nichts dazu; und schrieb sie auf zwo steinerne Tafeln und gab sie mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Da ihr aber die Stimme aus der Finstemis horetet und den Berg mit Feuer brennen tratet ihr zu mir; alle Obersten unter euren Stammen und eure Altesten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'und sprachet: Siehe, der HERR, unser Gott, hat uns lassen sehen seine Herrlichkeit und seine Majestat; und wir haben seine Stimme aus dem Feuer gehoret. Heutigestages haben wir gesehen; daß Gott mit Menschen redet, und sie lebendig bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Und nun, warum sollen wir sterben, daß uns dies grofie Feuer verzehre? Wenn wir des HERRN, unsers Gottes, Stimme mehr horen, so müssen wir sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Denn was istalles Fleisch, daß es horen moge die Stimme des lebendigen Gottes aus dem Feuer reden, wie wir, und lebendig bleibe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Tritt du hinzu und hore alles, was der HERR, unser Gott, sagt, und sage es uns. Alles, was der HERR, unser Gott, mit dir reden wird, das wollen wir horen und tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Da aber der HERR eure Worte horete, die ihr mit mir redetet, sprach er zur mir: Ich habe gehoret die Worte dieses Volks, die sie mit dir geredet haben; es ist alles gut, was sie geredet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Ach, daü sie ein solch Herz hatten, mich zu furchten und zu halten alle meine Gebote ihr Leben lang, auf dafi es ihnen wohlginge und ihren Kindern ewiglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Gehe hin und sage ihnen: Gehet heim in eure Hutten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Du aber sollst hie vor mir stehen, daß ich mit dir rede alle Gesetze und Gebote und Rechte, die du sie lehren sollst, daß sie danach tun im Lande, das ich ihnen geben werde einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'So behaltet nun, daß ihr tut, wie euch der HERR, euer Gott, geboten hat, und weichet nicht, weder zur Rechten noch zur Linken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'sondern wandelt in alien Wegen, die euch der HERR, euer Gott, geboten hat, auf daß ihr leben moget, und euch wohlgehe, und lange lebet im Lande, das ihr einnehmen werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Dies sind aber die Gesetze und Gebote und Rechte, die der HERR, euer Gott, geboten hat, dati ihr sie lernen und tun sollt im Lande, dahin ihr ziehet, dasselbe einzunehmen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'daü du den HERRN, deinen Gott, fürchtest, und haltest alle seine Rechte und Gebote, die ich dir gebiete, du und deine Kinder und deine Kindeskinder, alle eure Lebtage, auf dati ihr lange lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Israel, du sollst horen und behalten, daß du es tust, dati dir\'s wohlgehe, und sehr vermehret werdest; wie der HERR, deiner Vater Gott, dir geredet hat, ein Land, da Milch und Honig innen fleulit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Hore, Israel, der HERR, unser Gott, ist ein einiger HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Und du sollst den HERRN, deinen Gott, liebhaben von ganzem Herzen, von ganzer Seele, von allem Vermogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Und diese Worte, die ich dir heute gebiete, sollst du zu Herzen nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Und sollst sie deinen Kindern scharfen und davon reden, wenn du in deinem Hause sitzest Oder auf dem Wege gehest, wenn du dich niederlegest Oder aufstehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Und sollst sie binden zum Zeichen auf deine Hand, und sollen direin Denkmal vor deinen Augen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Und sollst sie uber deines Hauses Pfosten schreiben und an die Tore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Wenn dich nun der HERR, dein Gott, in das Land bringen wird, das er deinen Vatern, Abraham, Isaak und Jakob, geschworen hat, dirzu geben, grolie und feine Stadte, die du nicht gebauet hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'und Hauser alles Guts voll, die du nicht gefullet hast, und ausgehauene Brunnen, die du nicht ausgehauen hast, und Weinberge und Olberge, die du nicht gepflanzt hast, dafi du essest und satt wirst:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'so hute dich, daß du nicht des HERRN vergessest, der dich aus Agyptenland, aus dem Diensthause, gefuhret hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'sondern sollst den HERRN, deinen Gott, furchten und ihm dienen und bei seinem Namen schworen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Und sollst nicht andern Gottern nachfolgen, der Volker, die urn euch her sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'denn der HERR, dein Gott, ist ein eifriger Gott unter dir; daß nicht der Zorn des HERRN, deines Gottes, uber dich ergrimme und vertilge dich von der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ihr sollt den HERRN, euren Gott, nicht versuchen, wie ihr ihn versuchtet zu Massa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'sondern sollt halten die Gebote des HERRN, eures Gottes, und seine Zeugnisse und seine Rechte, die er geboten hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'dati du tust, was recht und gut ist vor den Augen des HERRN, auf daß dir\'s wohlgehe, und eingehest und einnehmest das gute Land, das der HERR geschworen hat deinen Vatern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'dati er verjage alle deine Feinde vor dir, wie der HERR geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Wenn dich nun dein Sohn heute Oder morgen fragen wird und sagen: Was sind das fur Zeugnisse, Gebote und Rechte, die euch der HERR, unser Gott, geboten hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'so sollst du deinem Sohn sagen: Wirwaren Knechte des Pharao in Agypten, und der HERR führete uns aus Agypten mit machtiger Hand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'und der HERR tat grotie und bose Zeichen und Wunder uber Agypten und Pharao und all seinem Hause vor unsern Augen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'und führete uns von dannen, auf dati er uns einfuhrete und gabe uns das Land, das er unsern Vatern geschworen hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'und hat uns geboten, der HERR, zu tun nach alien diesen Rechten, daß wir den HERRN, unsern Gott, furchten, auf daß uns wohlgehe alle unsere Lebtage, wie es gehet heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Und es wird unsere Gerechtigkeit sein vor dem HERRN, unserm Gott, so wir halten und tun alle diese Gebote, wie er uns geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Wenn dich der HERR, dein Gott, ins Land bringet, darein du kommen wirst, dasselbe einzunehmen, und ausrottet viele Volker vor dir her: die Hethiter, Girgositer, Amoriter, Kanaaniter, Pheresiter, Heviter und Jebusiter, sieben Volker, die großer und starker sind denn du;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'und wenn sie der HERR, dein Gott, vor dir gibt, daß du sie schlagst: so sollst du sie verbannen, daß du keinen Bund mit ihnen machest noch ihnen Gunst erzeigest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Und sollst dich mit ihnen nicht befreunden. Eure Tochter sollt ihr nicht geben ihren Sohnen, und ihre Tochter sollt ihr nicht nehmen euren Sohnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'denn sie werden eure Sohne mir abfallig machen, daß sie andern Gottern dienen; so wird dann des HERRN Zorn ergrimmen uber euch und euch bald vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Sondern also sollt ihr mit ihnen tun: Ihre Altare sollt ihr zerreifien, ihre Saulen zerbrechen, ihre Haine abhauen und ihre Gotzen mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Denn du bist ein heilig Volk Gott, deinem HERRN. Dich hat Gott, dein HERR, erwahlet zum Volk des Eigentums aus alien Volkern, die auf Erden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nicht hat euch der HERR angenommen und euch erwahlet, daß euer mehr ware denn alle Volker; denn du bist das wenigste unter alien Volkern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'sondern daß ereuch geliebet hat, und daß er seinen Eid hielte, den er euren Vatern geschworen hat, hat er euch ausgefuhret mit machtiger Hand und hat dich erloset von dem Hause des Dienstes, aus der Hand Pharaos, des Konigs in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'So sollst du nun wissen, daß der HERR, dein Gott, ein Gott ist, ein treuer Gott, der den Bund und Barmherzigkeit halt denen, die ihn lieben und seine Gebote halten, in tausend Glied,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'und vergilt denen, die ihn hassen, vorseinem Angesicht, daß er sie umbringe, und saumet sich nicht, daß er denen vergelte vor seinem Angesicht, die ihn hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'So behalte nun die Gebote und Gesetze und Rechte, die ich dir heute gebiete, daß du danach tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Und wenn ihr diese Rechte horet und haltetsie und danach tut, so wird der HERR, dein Gott, auch halten den Bund und Barmherzigkeit, die er deinen Vatern geschworen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'und wird dich lieben und segnen und mehren und wird die Frucht deines Leibes segnen und die Frucht deines Landes, dein Getreide, Most und 01, die Fruchte deiner Kuhe und die Fruchte deiner Schafe auf dem Lande, das er deinen Vatern geschworen hat, dirzu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Gesegnet wirst du sein uber alle Volker. Es wird niemand unter dir unfruchtbar sein, noch unter deinem Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Der HERR wird von dir tun alle Krankheit und wird keine bose Seuche der Agypter dir auflegen, die du erfahren hast; und wird sie alien deinen Hassern auflegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Du wirst alle Volker fressen, die der HERR, dein Gott, dir geben wird. Du sollst ihrer nicht schonen und ihren Gottern nicht dienen; denn das wurde dir ein Strick sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Wirst du aber in deinem Herzen sagen: Dieses Volks ist mehr, denn ich bin; wie kann ich sie vertreiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'so furchte dich nicht vor ihnen. Gedenke, was der HERR, dein Gott, Pharao und alien Agyptern getan hat');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'durch große Versuchung, die du mit Augen gesehen hast, und durch Zeichen und Wunder, durch eine machtige Hand und ausgereckten Arm, damit dich der HERR, dein Gott, ausführete. Also wird der HERR, dein Gott, alien Volkern tun, vor denen du dich furchtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Dazu wird der HERR, dein Gott, Hornissen unter sie senden, bis umgebracht werde, was ubrig ist und sich verbirget vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Laß dir nicht grauen vor ihnen; denn der HERR, dein Gott, ist unter dir, der große und schreckliche Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Er, der HERR, dein Gott, wird diese Leute ausrotten vor dir, einzeln nacheinander. Du kannst sie nicht eilend vertilgen, auf daß sich nicht wider dich mehren die Tiere auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Der HERR, dein Gott, wird sie vor dir geben und wird sie mit großer Schlacht erschlagen, bis er sie vertilge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Und wird dir ihre Konige in deine Hande geben, und sollst ihren Namen umbringen unter dem Himmel. Es wird dir niemand widerstehen, bis du sie vertilgest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Die Bilder ihrer Gotter sollst du mit Feuer verbrennen und sollst nicht begehren des Silbers Oder Goldes, das dran ist, Oder zu dir nehmen, daß du dich nicht drinnen verfahest; denn solches ist dem HERRN, deinem Gott, ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Darum sollst du nicht in dein Haus den Greuel bringen, daß du nicht verbannet werdest, wie dasselbe ist, sondern du sollst einen Ekel und Greuel daran haben, denn es ist verbannet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Alle Gebote, die ich dir heute gebiete, sollt ihr halten, daß ihr danach tut, auf daß ihr lebet und gemehret werdet und einkommet und einnehmet das Land, das der HERR euren Vatern geschworen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Und gedenkest all des Weges, durch den dich der HERR, dein Gott, geleitet hat diese vierzig Jahre in der Wuste, auf daß er dich demutigte und versuchte, daß kund wurde, was in deinem Herzen ware, ob du seine Gebote halten würdest Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Er demutigte dich und ließ dich hungern, und speisete dich mit Man, das du und deine Vater nie erkannt hattest, auf daß er dir kundtate, daß der Mensch nicht lebe vom Brot ailein, sondern von allem, das aus dem Munde des HERRN gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Deine Kleider sind nicht veraltet an dir, und deine Fuße sind nicht geschwollen diese vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'So erkennest du ja in deinem Herzen, daß der HERR, dein Gott, dich gezogen hat, wie ein Mann seinen Sohn zeucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'So halte nun die Gebote des HERRN, deines Gottes, da(S du in seinen Wegen wandelst und furchtest ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Denn der HERR, dein Gott, fuhret dich in ein gut Land, ein Land, da Bache und Brunnen und Seen innen sind, die an den Bergen und in den Auen fließen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'ein Land, da Weizen, Gerste, Weinstocke, Feigenbaume und Granatapfel innen sind; ein Land, da Olbaume und Honig innen wachset;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'ein Land, da du Brot genug zu essen hast, da auch nichts mangelt; ein Land, dessen Steine Eisen sind, da du Erz aus den Bergen hauest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Und wenn du gegessen hast und satt bist, daß du den HERRN, deinen Gott, lobest fur das gute Land, das er dir gegeben hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'So hute dich nun, daß du des HERRN, deines Gottes, nicht vergessest damit, daß du seine Gebote und seine Gesetze und Rechte, die ich dir heute gebiete, nicht haltest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'da(S, wenn du nun gegessen hast und satt bist und schone Hauser erbauest und drinnen wohnest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'und deine Rinder und Schafe und Silber und Gold und alles, was du hast, sich mehret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'da(S dann dein Herz sich nicht erhebe, und vergessest des HERRN, deines Gottes, der dich aus Agyptenland gefuhret hat, aus dem Diensthause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'und hat dich geieitet durch die groiße und grausame Wuste, da feurige Schlangen und Skorpione und eitel Dürre und kein Wasser war, und ließ dir Wasser aus dem harten Felsen gehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'und speisete dich mit Man in der Wuste, von welchem deine Vater nichts gewuißt haben, auf daß er dich demutigte und versuchte, daß er dir hernach wohltate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Du mochtest sonst sagen in deinem Herzen: Meine Krafte und meiner Hande Starke haben mir dies Vermogen ausgerichtet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'sondern daß du gedachtest an den HERRN, deinen Gott; denn er ist\'s, der dir Krafte gibt, solch machtige Taten zu tun, auf daß er hielte seinen Bund, den er deinen Vatern geschworen hat, wie es gehet heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Wirstdu aberdes HERRN, deines Gottes, vergessen und andern Gottern nachfolgen und ihnen dienen und sie anbeten, so bezeuge ich heute uber euch, daß ihr umkommen werdet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'eben wie die Heiden, die der HERR umbringet vor eurem Angesicht, so werdet ihr auch umkommen, darum daß ihr nicht gehorsam seid der Stimme des HERRN, eures Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Hore, Israel, du wirst heute uber den Jordan gehen, daß du einkommest, einzunehmen die Volker, die groißer und starker sind denn du, groiße Stadte, vermauert bis in den Himmel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'ein groß, hoch Volk, die Kinder Enakim, die du erkannt hast, von denen du auch gehoret hast: Wer kann wider die Kinder Enaks bestehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So sollst du wissen heute, daß der HERR, dein Gott, gehet vor dir her, ein verzehrend Feuer. Erwird sie vertilgen und wird sie unterwerfen vor dir her und wird sie vertreiben und umbringen bald, wie dir der HERR geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Wenn nun der HERR, dein Gott, sie ausgestoißen hat vor dir her, so sprich nicht in deinem Herzen: Der HERR hat mich hereingeführet, das Land einzunehmen, urn meiner Gerechtigkeit willen, so doch der HERR diese Heiden vertreibet vor dir her urn ihres gottlosen Wesens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Denn du kommst nicht herein, ihr Land einzunehmen, urn deiner Gerechtigkeit und deines aufrichtigen Herzens willen, sondern der HERR, dein Gott, vertreibt diese Heiden urn ihres gottlosen Wesens willen, daß er das Wort halte, das der HERR geschworen hat deinen Vatern, Abraham, Isaak und Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'So wisse nun, daß der HERR, dein Gott, dir nicht urn deiner Gerechtigkeit willen dies gute Land gibt einzunehmen, sintemal du ein halsstarrig Volk bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Gedenke und vergüß nicht, wie du den HERRN, deinen Gott, erzurnetest in der Wuste. Von dem Tage an, da du aus Agyptenland zogest, bis ihr kommen seid an diesen Ort, seid ihr ungehorsam gewesen dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Denn in Horeb erzurnetet ihr den HERRN, also daß er vor Zorn euch vertilgen wollte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'da ich auf den Berg gegangen war, die steinernen Tafeln zu empfahen, die Tafeln des Bundes, den der HERR mit euch machte, und ich vierzig Tage und vierzig Nachte auf dem Berge blieb und kein Brot aß und kein Wasser trank,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'und mir der HERR die zwo steinernen Tafeln gab, mit dem Finger Gottes beschrieben, und darauf alle Worte, wie der HERR mit euch aus dem Feuer auf dem Berge geredet hatte am Tage der Versammlung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Und nach den vierzig Tagen und vierzig Nachten gab mir der HERR die zwo steinernen Tafeln des Bundes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'und sprach zu mir: Mache dich auf, gehe eilend hinab von hinnen; denn dein Volk, das du aus Agypten gefuhret hast, hat\'s verderbet. Sie sind schnell getreten von dem Wege, den ich ihnen geboten habe; sie haben ihnen ein gegossen Bild gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Und der HERR sprach zu mir: Ich sehe, daß dies Volk ein halsstarrig Volk ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laft ab von mir, dad ich sie vertilge und ihren Namen austilge unter dem Himmel; ich will aus dir ein starker und grader Volk machen, denn dies ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Und als ich mich wandte und von dem Berge ging, der mit Feuer brannte, und die zwo Tafeln des Bundes auf meinen beiden Handen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'da sah ich, und siehe, da hattet ihreuch an dem HERRN, eurem Gott, versundiget, dad ihreuch ein gegossen Kalb gemacht und bald von dem Wege getreten waret, den euch der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Da fadete ich beide Tafeln und warf sie aus beiden Handen und zerbrach sie vor euren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Und fiel vor dem HERRN, wie zuerst, vierzig Tage und vierzig Nachte und ad kein Brot und trank kein Wasser urn aller eurer Sunden willen, die ihr getan hattet, da ihr solches Ubel tatet vor dem HERRN, ihn zu erzurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Denn ich furchtete mich vor dem Zorn und Grimm, damit der HERR über euch erzürnet war, dad er euch vertilgen wollte. Aber der HERR erhorete mich dasmal auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Auch war der HERR sehr zornig uber Aaron, dad er ihn vertilgen wollte; aber ich bat auch fur Aaron zur selbigen Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Aber eure Sunde, das Kalb, das ihr gemacht hattet, nahm ich und verbrannte es mit Feuer und zerschlug es und zermalmete es, bis es Staub ward, und warf den Staub in den Bach, der vom Berge fleudt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Auch so erzurnetet ihr den HERRN zu Thabeera und zu Massa und bei den Lustgrabern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Und da ereuch aus Kades-Barnea sandte und sprach: Gehet hinauf und nehmet das Land ein, das ich euch gegeben habe, waret ihr ungehorsam des HERRN Mund, eures Gottes, und glaubtet an ihn nicht und gehorchtet seiner Stimme nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Denn ihrseid ungehorsam dem HERRN gewesen, solange ich euch gekannt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Da fiel ich vor dem HERRN vierzig Tage und vierzig Nachte, die ich da lag; denn der HERR sprach, er wollte euch vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Ich aber bat den HERRN und sprach: Herr, HERR, verderbe dein Volk und dein Erbteil nicht, das du durch deine groüe Kraft erloset und mit machtiger Hand aus Agypten gefuhret hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Gedenke an deine Knechte, Abraham, Isaak und Jakob. Sieh nicht an die Hartigkeit und das gottlose Wesen und Sunde dieses Volks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'daß nicht das Land sage, daraus du uns gefuhret hast: Der HERR konnte sie nicht ins Land bringen, das er ihnen geredet hatte, und hat sie darum ausgefuhret, daß er ihnen gram war, daß er sie totete in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Denn sie sind dein Volk und dein Erbteil, das du mit deinen groften Kraften und mit deinem ausgereckten Arm hast ausgefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Zu derselben Zeit sprach der HERR zu mir: Haue dir zwo steinerne Tafeln, wie die ersten, und komm zu mir auf den Berg und mache dir eine holzerne Lade,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'so will ich auf die Tafeln schreiben die Worte, die auf den ersten waren, die du zerbrochen hast; und sollst sie in die Lade legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Also machte ich eine Lade von Fohrenholz und hieb zwo steinerne Tafeln, wie die ersten waren, und ging auf den Berg und hatte die zwo Tafeln in meinen Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Da schrieb er auf die Tafeln, wie die erste Schrift war, die zehn Worte, die der HERR zu euch redete aus dem Feuer auf dem Berge, zur Zeit der Versammlung; und der HERR gab sie mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Und ich wandte mich und ging vom Berge; und legte die Tafeln in die Lade, die ich gemacht hatte, daß sie daselbst waren, wie mir der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Und die Kinder Israel zogen aus von Beroth- Bne-Jakan gen Moser. Daselbst starb Aaron und ist daselbst begraben; und sein Sohn Eleasar ward fur ihn Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Von dannen zogen sie aus gen Gudegoda; von Gudegoda gen Jathbath, ein Land, da Bache sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Zur selben Zeit sonderte der HERR den Stamm Levi aus, die Lade des Bundes des HERRN zu tragen und zu stehen vor dem HERRN, ihm zu dienen und seinen Namen zu loben, bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Darum sollen die Leviten, kein Teil noch Erbe haben mit ihren Brudern; denn der HERR ist ihr Erbe, wie der HERR, dein Gott, ihnen geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ich aber stund auf dem Berge, wie vorhin, vierzig Tage und vierzig Nachte; und der HERR erhorete mich auch dasmal und wollte dich nicht verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Er sprach aber zu mir: Mache dich auf und gehe hin, daß du vor dem Volk her ziehest, daß sie einkommen und das Land einnehmen, das ich ihren Vatern geschworen habe, ihnen zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nun, Israel, was fordert der HERR, dein Gott, von dir, denn daß du den HERRN, deinen Gott, furchtest, daß du in alien seinen Wegen wandelst und liebest ihn und dienest dem HERRN, deinem Gott, von ganzem Herzen und von ganzer Seele,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'daß du die Gebote des HERRN haltest und seine Rechte, die ich dir heute gebiete, auf daß dids wohlgehe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Siehe, Himmel und aller Himmel Himmel und Erde und alles, was drinnen ist, das ist des HERRN, deines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Noch hat er allein zu deinen Vatern Lust gehabt, dafi ersie liebete, und hat ihren Samen erwahlet nach ihnen, euch, uber alle Volker, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'So beschneidet nun eures Herzens Vorhaut und seid fürder nicht halsstarrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Denn der HERR, euer Gott, istein Gott aller Gotter und HERR uber alle Herren, ein grolier Gott, machtig und schrecklich, der keine Person achtet und kein Geschenk nimmt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'und schaffet Recht den Waisen und Witwen und hat die Fremdlinge lieb, daß er ihnen Speise und Kleider gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Darum solltihrauch die Fremdlinge lieben; denn ihrseid auch Fremdlinge gewesen in Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Den HERRN, deinen Gott, sollst du furchten, ihm sollst du dienen, ihm sollst du anhangen und bei seinem Namen schworen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Er ist dein Ruhm und dein Gott, der bei dir solche grolie und schreckliche Dinge getan hat, die deine Augen gesehen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Deine Vaterzogen hinab nach Agypten mit siebenzig Seelen; aber nun hat dich der HERR, dein Gott, gemehret wie die Sterne am Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'So sollst du nun den HERRN, deinen Gott, lieben und sein Gesetz, seine Weise, seine Rechte und seine Gebote halten dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Und erkennet heute, das eure Kinder nicht wissen noch gesehen haben, namlich die Zuchtigung des HERRN, eures Gottes, seine Herrlichkeit, dazu seine machtige Hand und ausgereckten Arm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'und seine Zeichen und Werke, die er getan hat unter den Agyptern, an Pharao, dem Konige in Agypten, und an all seinem Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'und was er an der Macht der Agypter getan hat, an ihren Rossen und Wagen, da er das Wasser des Schilfmeers uber sie fuhrete, da sie euch nachjagten, und sie der HERR umbrachte, bis auf diesen Tag;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'und was er euch getan hat in der Wuste, bis ihr an diesen Ort kommen seid;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'was er Dathan und Abiram getan hat, den Kindern Eliabs, des Sohnes Rubens, wie die Erde ihren Mund auftat und verschlang sie mit ihrem Gesinde und Hütten und all ihrem Gut, das sie erworben hatten mitten unter dem ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Denn eure Augen haben die grolien Werke des HERRN gesehen, die er getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Darum sollt ihr alle die Gebote halten, die ich dir heute gebiete, auf daß ihr gestarket werdet, einzukommen und das Land einzunehmen, dahin ihr ziehet, daß ihr\'s einnehmet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'und daß du lange lebest auf dem Lande, das der HERR euren Vatern geschworen hat, ihnen zu geben und ihrem Samen, ein Land, da Milch und Honig innen fleufit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Denn das Land, da du hinkommst, es einzunehmen, ist nicht wie Agyptenland, davon ihr ausgezogen seid, da du deinen Samen saen und selbst tranken mulitestwie einen Kohlgarten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'sondern es hat Berge und Auen, die der Regen vom Himmel tranken muli,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'auf welch Land der HERR, dein Gott, acht hat, und die Augen des HERRN, deines Gottes, immerdar drauf sehen von Anfang des Jahrs bis ans Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Werdet ihr nun meine Gebote horen, die ich euch heute gebiete, daß ihr den HERRN, euren Gott, liebet und ihm dienet von ganzem Herzen und von ganzer Seele,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'so will ich eurem Lande Regen geben zu seiner Zeit, Fruhregen und Spatregen, daß du einsammelst dein Getreide, deinen Most und dein Ol;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'und will deinem Vieh Gras geben auf deinem Felde, daß ihr esset und satt werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Hütet euch aber, daß sich euer Herz nicht uberreden lasse, daß ihr abtretet und dienet andern Gottern und betet sie an,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'und daß dann der Zorn des HERRN ergrimme uber euch und schlielie den Himmel zu, daß kein Regen komme, und die Erde ihr Gewachs nicht gebe, und bald umkommet von dem guten Lande, das euch der HERR gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'So fasset nun diese Worte zu Herzen und in eure Seele und bindet sie zum Zeichen auf eure Hand, daß sie ein Denkmal vor euren Augen seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Und lehret sie eure Kinder, daß du davon redest, wenn du in deinem Hause sitzest Oder auf dem Wege gehest, wenn du dich niederlegest und wenn du aufstehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Und schreibe sie an die Pfosten deines Hauses und an deine Tore,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'daß du und deine Kinder lange lebest auf dem Lande, das der HERR deinen Vatern geschworen hat, ihnen zu geben, solange die Tage vom Himmel auf Erden wahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Denn wo ihr diese Gebote alle werdet halten, die ich euch gebiete, daß ihr danach tut, daß ihr den HERRN, euren Gott, liebet und wandelt in alien seinen Wegen und ihm anhanget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'so wird der HERR alle diese Volker vor euch her vertreiben, daß ihr groliere und starkere Volker einnehmet, denn ihrseid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Alle Oder, darauf eure Fulisohle tritt, sollen euer sein; von der Wuste an und von dem Berge Libanon und von dem Wasser Phrath bis ans aulierste Meer soil eure Grenze sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Niemand wird euch widerstehen mogen. Eure Furcht und Schrecken wird der HERR uber alle Lande kommen lassen, darin ihr reiset, wie er euch geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Siehe, ich lege euch heute vor den Segen und den Fluch:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'den Segen, so ihr gehorchet den Geboten des HERRN, eures Gottes, die ich euch heute gebiete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'den Fluch aber, so ihr nicht gehorchen werdet den Geboten des HERRN, eures Gottes, und abtretet von dem Wege, den ich euch heute gebiete, dati ihr andern Gottern nachwandelt, die ihr nicht kennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Wenn dich der HERR, dein Gott, in das Land bringet, da du einkommst, dati du es einnehmest, so sollst du den Segen sprechen lassen auf dem Berge Grisim und den Fluch auf dem Berge Ebal,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'welche sind jenseit des Jordans, der Stralie nach gegen der Sonnen Niedergang, im Lande der Kanaaniter, die auf dem Blachfelde wohnen gegen Gilgal uber, bei dem Hain More.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Denn du wirst uber den Jordan gehen, daß du einkommest, das Land einzunehmen, das euch der HERR, euer Gott, gegeben hat, dati ihr\'s einnehmet und drinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'So haltet nun, daß ihr tut nach alien Geboten und Rechten, die ich euch heute vorlege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Das sind die Gebote und Rechte, die ihr halten sollt, da($ ihr danach tut im Lande, das der HERR, deiner Vater Gott, dir gegeben hat einzunehmen, solange ihr auf Erden lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Verstoret alle Orte, da die Heiden, die ihr einnehmen werdet, ihren Gottern gedienet haben, es sei auf hohen Bergen, auf Hugeln Oder unter grunen Baumen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'und reiliet urn ihre Altare und zerbrechet ihre Saulen und verbrennet mit Feuer ihre Haine; und die Gotzen ihrer Gotter tut ab und vertilget ihren Namen aus demselben Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ihr sollt dem HERRN, eurem Gott, nicht also tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'sondern an dem Ort, den der HERR, euer Gott, erwahlen wird aus alien euren Stammen, daü er seinen Namen daselbst lasset wohnen, sollt ihr forschen und dahin kommen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'und eure Brandopfer, und eure anderen Opfer und eure Zehnten und eurer Hande Hebe und eure Gelubde und eure freiwilligen Opfer und die Erstgeburt eurer Rinder und Schafe dahin bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Und soilt daselbst vor dem HERRN, eurem Gott, essen und frohlich sein uber allem, das ihr und euer Haus bringet, darinnen dich der HERR, dein Gott, gesegnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ihr sollt der keins tun, das wir heute allhie tun, ein jeglicher, was ihn recht dunket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Denn ihr seid bisher noch nicht zur Ruhe kommen noch zu dem Erbteil, das dir der HERR, dein Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Ihr werdet aber uber den Jordan gehen und im Lande wohnen, das euch der HERR, euer Gott, wird zum Erbe austeilen, und wird euch Ruhe geben von alien euren Feinden urn euch her, und werdet sicher wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Wenn nun der HERR, dein Gott, einen Ort erwahlet, daß sein Name daselbst wohne, sollt ihr daselbst hinbringen ailes, was ich euch gebiete: eure Brandopfer, eure anderen Opfer, eure Zehnten, eurer Hande Hebe und alle eure freien Gelubde, die ihr dem HERRN geloben werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Und sollt frohlich sein vor dem HERRN, eurem Gott, ihr und eure Sohne und eure Tochter und eure Knechte und eure Magde und die Leviten, die in euren Toren sind; denn sie haben kein Teil noch Erbe mit euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Hute dich, dafi du nicht deine Brandopfer opferst an alien Orten, die du siehest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'sondern an dem Ort, den der HERR erwahlet in irgendeinem deiner Stamme, da sollst du dein Brandopfer opfern und tun ailes, was ich dir gebiete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Doch magst du schlachten und Fleisch essen in alien deinen Toren nach alter Lust deiner Seele, nach dem Segen des HERRN, deines Gottes, den erdir gegeben hat; beide der Reine und der Unreine mogen\'s essen, wie ein Reh Oder Hirsch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Ohne das Blut sollst du nicht essen, sondern auf die Erde gielien, wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Du magst aber nicht essen in deinen Toren vom Zehnten deines Getreides, deines Mosts, deines Ols, noch von der Erstgeburt deiner Rinder, deiner Schafe Oder von irgend einem deiner Gelubde, die du gelobet hast, Oder von deinem freiwilligen Opfer, Oder von deiner Hand Hebe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'sondern vor dem HERRN, deinem Gott, sollst du solches essen an dem Ort, den der HERR, dein Gott, erwahlet, du und deine Sohne, deine Tochter, deine Knechte, deine Magde und der Levit, der in deinem Tor ist; und sollst frohlich sein vor dem HERRN, deinem Gott, uber ailem, das du bringest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Und hute dich, daß du den Leviten nicht verlassest, solange du auf Erden lebest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Wenn aber der HERR, dein Gott, deine Grenze weitern wird, wie er dir geredet hat, und sprichst: Ich will Fleisch essen, weil deine Seele Fleisch zu essen gelustet, so ili Fleisch nach aller Lust deiner Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ist aber die Statte feme von dir, die der HERR, dein Gott, erwahlet hat, dati er seinen Namen daselbst wohnen lasse, so schlachte von deinen Rindern Oder Schafen, die dir der HERR gegeben hat, wie ich dir geboten habe, und ili es in deinen Toren nach aller Lust deiner Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Wie man ein Reh Oder Hirsch isset, magst du es essen; beide der Reine und der Unreine mogen\'s zugleich essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Allein merke, daß du das Blut nicht essest; denn das Blut ist die Seele, darum sollst du die Seele nicht mit dem Fleisch essen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'sondern sollst es auf die Erde gielien, wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Und sollst es darum nicht essen, daß dir\'s wohlgehe und deinen Kindern nach dir, daß du getan hast, was recht ist vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Aberwenn du etwas heiligen willst von dem Deinen, Oder geloben, so sollst du es aufladen und bringen an den Ort, den der HERR erwahlet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'und dein Brandopfer mit Fleisch und Blut tun auf den Altar des HERRN, deines Gottes. Das Blut deines Opfers sollst du gieften auf den Altar des HERRN, deines Gottes, und das Fleisch essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Siehe zu und hore alle diese Worte, die ich dir gebiete, auf daß dir\'s wohlgehe und deinen Kindern nach dir ewiglich, daß du getan hast, was recht und gefallig ist vor dem HERRN, deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Wenn der HERR, dein Gott, vor dir her die Heiden ausrottet, daß du hinkommest, sie einzunehmen, und sie eingenommen hast und in ihrem Lande wohnest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'so hute dich, daß du nicht in den Strick tallest ihnen nach, nachdem sie vertilget sind vor dir, und nicht fragest nach ihren Gottern und sprechest: Wie diese Volker haben ihren Gottern gedienet, also will ich auch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Du sollst nicht also an dem HERRN, deinem Gott, tun; denn sie haben ihren Gottern getan alles, was dem HERRN ein Greuel ist, und das er hasset; denn sie haben auch ihre Sohne und Tochter mit Feuer verbrannt ihren Gottern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Alles, was ich euch gebiete, das sollt ihr halten, daß ihr danach tut. Ihr sollt nichts dazutun noch davontun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Wenn ein Prophet Oder Traumer unter euch wird aufstehen und gibt dir ein Zeichen Oder Wunder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'und das Zeichen Oder Wunder kommt, davon er dir gesagt hat, und spricht: Laft uns andern Gottern folgen, die ihr nicht kennet, und ihnen dienen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'so sollst du nicht gehorchen den Worten solches Propheten oder Traumers; denn der HERR, euer Gott, versucht euch, daß er erfahre, ob ihr ihn von ganzem Herzen und von ganzer Seele lieb habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Denn ihr sollt dem HERRN, eurem Gott, folgen und ihn furchten und seine Gebote halten und seiner Stimme gehorchen und ihm dienen und ihm anhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Der Prophet aber Oder der T raumer soli sterben, darum daß ereuch von dem HERRN, eurem Gott, der euch aus Agyptenland gefuhret und dich von dem Diensthause erloset hat, abzufallen gelehret und dich aus dem Wege verführet hat; den der HERR, dein Gott, geboten hat, drinnen zu wandeln, auf daß du den Bosen von dirtust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Wenn dich dein Bruder, deiner Mutter Sohn, Oder dein Sohn, oderdeine Tochter, Oder das Weib in deinen Armen, Oder dein Freund, der dir ist wie dein Herz, überreden würde heimlich und sagen: Laft uns gehen und andern Gottern dienen, die du nicht kennest, noch deine Vater,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'die unter den Volkern urn euch her sind, sie seien dir nahe Oder feme, von einem Ende der Erde bis an das andere:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'so bewillige nicht und gehorche ihm nicht. Auch soli dein Auge seiner nicht schonen, und sollst dich seiner nicht erbarmen noch ihn verbergen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'sondern solist ihn erwürgen. Deine Hand soil die erste fiber ihm sein, daß man ihn tote, und danach die Hand des ganzen Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Man soil ihn zu Tode steinigen, denn er hat dich wollen verfuhren von dem HERRN, deinem Gott, der dich aus Agyptenland Von dem Diensthause gefuhret hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'auf daß ganz Israel hore und furchte sich, und nicht mehr solch Ubel vornehme unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Wenn du horest von irgend einer Stadt, die dir der HERR, dein Gott, gegeben hat, drinnen zu wohnen, daß man sagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Es sind etliche Kinder Belials ausgegangen unter dir und haben die Burger ihrer Stadt verführt und gesagt: Laftt uns gehen und andern Gottern dienen, die ihr nicht kennet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'so sollst du fleiftig suchen, forschen und fragen. Und so sich findet die Wahrheit, daß gewift also ist, daß der Greuel unter euch geschehen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'so sollst du die Burger derselben Stadt schlagen mit des Schwerts Scharfe und sie verbannen mit allem, das drinnen ist, und ihr Vieh mit der Scharfe des Schwerts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Und alien ihren Raub sollst du sammeln mitten auf die Gassen und mit Feuer verbrennen, beide Stadt und alien ihren Raub miteinander dem HERRN, deinem Gott, daß sie auf einem Haufen liege ewiglich und nimmer gebauet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Und laft nichts von dem Bann an deiner Hand hangen, auf daß der HERR von dem Grimm seines Zorns abgewendet werde und gebe dir Barmherzigkeit und erbarme sich deiner und mehre dich, wie er deinen Vatern geschworen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 19, 'darum daß du der Stimme des HERRN, deines Gottes, gehorchet hast, zu halten alle seine Gebote, die ich dir heute gebiete, daß du tust, was recht ist vor den Augen des HERRN, deines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Ihr seid Kinder des HERRN, eures Gottes; ihr sollt euch nicht Male stechen noch kahl scheren fiber den Augen fiber einem Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Denn du bist ein heilig Volk dem HERRN, deinem Gott, und der HERR hat dich erwahlet, daß du sein Eigentum seiest aus alien Volkern, die auf Erden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du sollst keinen Greuel essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dies ist aber das Tier, das ihr essen sollt: Ochsen, Schafe, Ziegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Hirsch, Rehe, Büffel, Steinbock, Tendeln, Urochs und Elen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'und alles Tier, das seine Klauen spaltet und wiederkauet, sollt ihr essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Das sollt ihr aber nicht essen, das wiederkauet und die Klauen nicht spaltet. Das Kamel, der Hase und Kaninchen, die da wiederkauen und doch die Klauen nicht spalten, sollen euch unrein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Das Schwein, ob es wohl die Klauen spaltet, so wiederkauet es doch nicht, soil euch unrein sein. Ihres Fleisches sollt ihr nicht essen und ihr Aas sollt ihr nicht anruhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Das ist, das ihr essen sollt von allem, das in Wassern ist: alles, was Flofifedern und Schuppen hat, sollt ihr essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Was aber keine Flofifedern noch Schuppen hat, sollt ihr nicht essen; denn es ist euch unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reinen Vogel esset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Das sind sie aber, die ihr nicht essen sollt: der Adler, der Habicht, der Fischaar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'der Taucher, der Weihe, der Geier mit seiner Art');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'und alle Raben mit ihrer Art,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'der Strauü, die Nachteule, der Kuckuck, der Sperber mit seiner Art,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'das Kauzlein, der Uhu, die Fledermaus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'die Rohrdommel, der Storch, der Schwan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'der Reiher, der Haher mit seiner Art, der Wiedehopf, die Schwalbe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'und alles Gevogel, das kreucht, soli euch unrein sein, und sollt es nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Das reine Gevogel sollt ihr essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ihr sollt kein Aas essen; dem Fremdling in deinem Tor magst du es geben, daß er\'s esse, Oder verkaufe es einem Fremden; denn du bist ein heilig Volk dem HERRN, deinem Gott. Du sollst das Bocklein nicht kochen, weil es noch seine Mutter sauget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Du sollst alle Jahr den Zehnten absondern alles Einkommens deiner Saat, das aus deinem Acker kommt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'und sollst es essen vordem HERRN, deinem Gott, an dem Ort, den er erwahlet, daß sein Name daselbstwohne, namlich vom Zehnten deines Getreides, deines Mosts, deines Ols und der Erstgeburt deiner Rinder und deiner Schafe, auf dafi du lernest furchten den HERRN, deinen Gott, dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Wenn aber des Weges dir zu viel ist, daß du solches nicht hintragen kannst, darum daß der Ort dir zu feme ist, den der HERR, dein Gott, erwahlet hat, daß er seinen Namen daselbst wohnen lasse (denn der HERR, dein, Gott, hat dich gesegnet),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'so gib\'s urn Geld und fasse das Geld in deine Hand und gehe an den Ort, den der HERR, dein Gott, erwahlet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'und gib das Geld urn alles, was deine Seele gelustet, es sei urn Rinder, Schafe, Wein, starken Trank Oder urn alles, das deine Seele wünschet. Und ift daselbst vor dem HERRN, deinem Gott, und sei frdhlich, du und dein Haus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'und der Levit, der in deinem Tor ist; du sollst ihn nicht verlassen, denn er hat kein Teil noch Erbe mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Uber drei Jahre sollst du aussondern alle Zehnten deines Einkommens desselben Jahrs und sollst es lassen in deinem Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'So soil kommen der Levit, der kein Teil noch Erbe mit dir hat, und der Fremdling und der Waise und die Witwe, die in deinem Tor sind, und essen und sich sattigen, auf dafi dich der HERR, dein Gott, segne in alien Werken deiner Hand, die du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Uber sieben Jahre sollst du ein Erlafijahr halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Also soil\'s aber zugehen mit dem Erlaüjahr: Wenn einer seinem Nachsten etwas borget, der soil\'s ihm erlassen und soil\'s nicht einmahnen von seinem Nachsten Oder von seinem Bruder; denn es heiftt ein Erlafijahr dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Von einem Fremden magst du es einmahnen; aber dem, der dein Bruder ist, sollst du es erlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Es soil allerdinge kein Bettler untereuch sein; denn der HERR wird dich segnen im Lande, das dir der HERR, dein Gott, geben wird zum Erbe einzunehmen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'allein daß du der Stimme des HERRN, deines Gottes, gehorchest und haltest alle diese Gebote, die ich dir heute gebiete, daß du danach tust!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Denn der HERR, dein Gott, wird dich segnen, wie er dir geredet hat. So wirst du vielen Volkern leihen, und du wirst von niemand borgen. Du wirst uber viele Volker herrschen, und uber dich wird niemand herrschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Wenn deiner Bruder irgend einer arm ist in irgend einer Stadt in deinem Lande, das der HERR, dein Gott, dir geben wird, so sollst du dein Herz nicht verharten noch deine Hand zuhalten gegen deinen armen Bruder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'sondern sollst sie ihm auftun und ihm leihen, nach dem er mangelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Hute dich, daß nicht in deinem Herzen ein Belialstuck sei, das da spreche: Es nahet herzu das siebente Jahr, das Erlaftjahr, und sehest deinen armen Bruder unfreundlich an und gebest ihm nicht; so wird er uber dich zum HERRN rufen, so wirst du es Sünde haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'sondern du sollst ihm geben, und dein Herz nicht verdrieften lassen, daß du ihm gibst; denn urn solches willen wird dich der HERR, dein Gott, segnen in alien deinen Werken und was du vornimmst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Eswerden allezeit Arme sein im Lande; darum gebiete ich dir und sage, daß du deine Hand auftust deinem Bruder, der bedrangt und arm ist in deinem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Wenn sich dein Bruder, ein Ebraeroder Ebraerin, dir verkauft, so soil er dir sechs Jahre dienen; im siebenten Jahrsollstdu ihn frei losgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Und wenn du ihn frei losgibst, sollstdu ihn nicht leer von dir gehen lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'sondern sollst ihm auflegen von deinen Schafen, von deiner Tenne, von deiner Kelter, daß du gebest von dem, das dir der HERR, dein Gott, gesegnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Und gedenke, dafi du auch Knechtwarest in Agyptenland, und der HERR, dein Gott, dich erloset hat; darum gebiete ich dir solches heute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Wird eraberzurdirsprechen: Ich will nicht ausziehen von dir, denn ich habe dich und dein Haus lieb (weil ihm wohl bei dir ist),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'so nimm einen Pfriemen und bohre ihn durch sein Ohr an der Tur und laft ihn ewiglich deinen Knecht sein. Mit deiner Magd sollst du auch also tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Und lati dich\'s nicht schwer dunken, daß du ihn frei losgibst: denn er hat dir als ein zwiefaltiger Taglohner sechs Jahre gedienet; so wird der HERR, dein Gott, dich segnen in allem, was du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Alle Erstgeburt, die unter deinen Rindern und Schafen geboren wird, das ein Mannlein ist, sollst du dem HERRN, deinem Gott, heiligen. Du sollst nicht ackern mit dem Erstling deiner Ochsen und nicht bescheren die Erstlinge deiner Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Vor dem HERRN, deinem Gott, sollst du sie essen jahrlich an der Statte, die der HERR erwahlet, du und dein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Wenn es aber einen Fehl hat, daß es hinket, Oder blind ist, Oder sonst irgend einen bosen Fehl, so sollst du es nicht opfern dem HERRN, deinem Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'sondern in deinem Tor sollst du es essen, du seiest unrein Oder rein, wie ein Reh und Hirsch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'allein daß du seines Bluts nicht essest, sondern auf die Erde gieftest, wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Halte den Mond Abib, daß du Passah haitest dem HERRN, deinem Gott; denn im Mond Abib hat dich der HERR, dein Gott, aus Agypten gefuhret bei der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Und sollst dem HERRN, deinem Gott, das Passah schlachten, Schafe und Rinder, an der Statte, die der HERR erwahlen wird, daß sein Name daselbst wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du solist kein Gesauertes auf das Fest essen. Sieben Tage sollstdu ungesauert Brot des Elends essen; denn mit Furcht bist du aus Agyptenland gezogen, auf daß du des Tages deines Auszugs aus Agyptenland gedenkest dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Es soil in sieben Tagen kein Gesauertes gesehen werden in alien deinen Grenzen; und soil auch nichts vom Fleisch, das des Abends am ersten Tage geschlachtet ist uber Nacht bleiben bis an den Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du kannst nicht Passah schlachten in irgend deiner Tore einem, die dir der HERR, dein Gott, gegeben hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'sondern an der Statte, die der HERR, dein Gott, erwahlen wird, daß sein Name daselbst wohne, da sollst du das Passah schlachten des Abends, wenn die Sonne ist untergegangen, zu der Zeit, als du aus Agypten zogest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Und sollst es kochen und essen an der Statte, die der HERR, dein Gott, erwahlen wird, und danach dich wenden des Morgens und heimgehen in deine Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sechs Tage sollstdu Ungesauertes essen, und am siebenten Tag ist die Versammlung des HERRN, deines Gottes; da sollst du keine Arbeit tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sieben Wochen sollst du dir zahlen und anheben zu zahlen, wenn man anfahet mit der Sichel in der Saat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Und sollst halten das Fest der Wochen dem HERRN, deinem Gott, daß du eine freiwillige Gabe deiner Hand gebest, nachdem dich der HERR, dein Gott, gesegnet hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'und sollst frohlich sein vor Gott, deinem HERRN, du und dein Sohn, deine Tochter, dein Knecht; deine Magd und der Levit, der in deinem Tor ist, der Fremdling, der Waise und die Witwe, die unter dir sind, an der Statte, die der HERR, dein Gott, erwahlet hat, daß sein Name da wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Und gedenke, daß du Knecht in Agypten gewesen bist, daß du haitest und tust nach diesen Geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Das Fest der Laubhutten sollst du halten sieben Tage, wenn du hast eingesammelt von deiner Tenne und von deiner Kelter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'und sollst frohlich sein auf dein Fest, du und dein Sohn, deine Tochter, dein Knecht, deine Magd, der Levit, der Fremdling, der Waise und die Witwe, die in deinem Tor sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sieben Tage sollst du dem HERRN, deinem Gott, das Fest halten an der Statte, die der HERR erwahlen wird. Denn der HERR, dein Gott, wird dich segnen in all deinem Einkommen und in alien Werken deiner Hande; darum sollst du frohlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Dreimal des Jahrs soil alles, was mannlich ist unter dir, vor dem HERRN, deinem Gott, erscheinen an der Statte, die der HERR erwahlen wird: aufs Fest der ungesauerten Brote, aufs Fest der Wochen und aufs Fest der Laubhutten. Es soil aber nicht leer vor dem HERRN erscheinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'ein jeglicher nach der Gabe seiner Hand, nach dem Segen, den dir der HERR, dein Gott, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Richter und Amtleute sollst du dir setzen in alien deinen Toren, die dir der HERR, dein Gott, geben wird unter deinen Stammen, daß sie das Volk richten mit rechtem Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du sollst das Recht nicht beugen und sollst auch keine Person ansehen noch Geschenk nehmen; denn die Geschenke machen die Weisen blind und verkehren die Sachen der Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Was recht ist, dem sollst du nachjagen, auf daß du leben und einnehmen mogest das Land, das dir der HERR, dein Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Du sollst keinen Hain von Baumen pflanzen bei dem Altar des HERRN, deines Gottes, den du dir machest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Du sollst dir keine Saule aufrichten, welche der HERR, dein Gott, hasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du sollst dem HERRN, deinem Gott, keinen Ochsen Oder Schaf opfern, das einen Fehl Oder irgend etwas Boses an ihm hat; denn es ist dem HERRN, deinem Gott, ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Wenn unter dir in der Tore einem, die dir der HERR, dein Gott, geben wird, funden wird ein Mann Oder Weib, der da Ubels tut vor den Augen des HERRN, deines Gottes, daß erseinen Bund ubergehet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'und hingehet und dienet andern Gottern und betet sie an, es sei Sonne Oder Mond, Oder irgend ein Heer des Himmels, das ich nicht geboten habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'und wird dir angesagt und horest es, so sollst du wohl danach fragen. Und wenn du findest, dafi gewili wahr ist, daß solcher Greuel in Israel geschehen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'so sollst du denselben Mann Oder dasselbe Weib ausfuhren, die solches Ubel getan haben, zu deinem Tor und sollst sie zu Tod steinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Auf zweier Oder dreier Zeugen Mund soil sterben, wer des Todes wert ist; aber auf eines Zeugen Mund soil er nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Die Hand der Zeugen soil die erste sein, ihn zu toten, und danach die Hand alles Volks, daß du den Bosen von dir tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Wenn eine Sache vor Gericht dir zu schwer sein wird, zwischen Blut und Blut, zwischen Handel und Handel, zwischen Schaden und Schaden, und was zankische Sachen sind in deinen Toren, so sollst du dich aufmachen und hinaufgehen zu der Statte; die dir der HERR, dein Gott, erwahlen wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'und zu den Priestern, den Leviten und zu dem Richter, der zu der Zeit sein wird, kommen und fragen; die sollen dir das Urteil sprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Und du sollst tun nach dem, das sie dir sagen an der Statte, die der HERR erwahlet hat, und sollst es halten, daß du tust nach allem, das sie dich lehren werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Nach dem Gesetz, das sie dich lehren, und nach dem Recht, das sie dir sagen, sollst du dich halten, daß du von demselben nicht abweichest weder zur Rechten noch zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Und wo jemand vermessen handeln wurde, daß er dem Priester nicht gehorchte, der daselbst in des HERRN, deines Gottes, Amt stehet, Oder dem Richter, der soil sterben; und sollst den Bosen aus Israel tun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'daß alles Volk hore und sich furchte und nicht mehr vermessen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Wenn du ins Land kommst, das dir der HERR, dein Gott, geben wird, und nimmst es ein und wohnest drinnen, und wirst sagen: Ich will einen Konig uber mich setzen, wie alle Volker urn mich her haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'so sollst du den zum Konige uber dich setzen, den der HERR, dein Gott, erwahlen wird. Du sollst aber aus deinen Brudern einen zum Konige uber dich setzen. Du kannst nicht irgend einen Fremden, der nicht dein Bruder ist, uber dich setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Allein daß er nicht viele Rosse halte und führe das Volk nicht wieder in Agypten urn der Rosse Menge willen, weil der HERR euch gesagt hat, daß ihr fort nicht wieder durch diesen Weg kommen sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Ersoll auch nicht viele Weiber nehmen, daß sein Herz nicht abgewandt werde; und soil auch nicht viel Silber und Gold sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Und wenn ernun sitzen wird auf dem Stuhl seines Konigreichs, soil er dies andere Gesetz von den Priestern, den Leviten, nehmen und auf ein Buch schreiben lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Das soil bei ihm sein und soli drinnen lesen sein Leben lang, auf daß er lerne furchten den HERRN, seinen Gott, daß er halte alle Worte dieses Gesetzes und die Rechte, daß er danach tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Er soil sein Herz nicht erheben uber seine Bruder und soli nicht weichen von dem Gebot, weder zur Rechten noch zur Linken, auf daß er seine Tage verlangere auf seinem Konigreich, er und seine Kinder in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Die Priester, die Leviten des ganzen Stamms Levi, sollen nicht Teil noch Erbe haben mit Israel. Die Opfer des HERRN und sein Erbteil sollen sie essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Darum sollen sie kein Erbe unter ihren Brudern haben, daß der HERR ihr Erbe ist, wie er ihnen geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Das soil aber das Recht der Priester sein an dem Volk und an denen, die da opfern, es sei Ochse Oder Schaf, daß man dem Priester gebe den Arm und beide Backen und den Wanst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'und das Erstling deines Korns, deines Mosts und deines Ols und das Erstling von der Schur deiner Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Denn der HERR, dein Gott, hat ihn erwahlet aus alien deinen Stammen, daß er stehe am Dienst im Namen des HERRN, er und seine Sohne ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Wenn ein Levit kommt aus irgend einem deiner Tore Oder sonst irgend aus ganz Israel, da er ein Gast ist, und kommt nach aller Lust seiner Seele an den Ort, den der HERR erwahlet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'daß er diene im Namen des HERRN, seines Gottes, wie alle seine Bruder, die Leviten, die daselbst vor dem HERRN stehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'die sollen gleichen Teil zu essen haben, uber das er hat von dem verkauften Gut seiner Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Wenn du in das Land kommst, das dirder HERR, dein Gott, geben wird, so sollst du nicht lernen tun die Greuel dieser Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Dali nicht unter dir funden werde, derseinen Sohn Oder Tochter durchs Feuer gehen lasse, Oder ein Weissager Oder ein Tagewahler, Oder der auf Vogelgeschrei achte, Oder ein Zauberer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Oder Beschworer Oder Wahrsager Oder Zeichendeuter, Oder der die Toten frage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Denn wer solches tut, der ist dem HERRN ein Greuel, und um solcher Greuel willen vertreibt sie der HERR, dein Gott, vor dir her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Du aber sollst ohne Wandel sein mitdem HERRN, deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Denn diese Volker, die du einnehmen wirst, gehorchen den Tagewahlern und Weissagern; aber du sollst dich nicht also halten gegen den HERRN, deinen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Einen Propheten wie mich wird der HERR, dein Gott, dir erwecken aus dir und aus deinen Brudern, dem sollt ihr gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Wie du denn von dem HERRN, deinem Gott, gebeten hast zu Horeb am Tage der Versammlung und sprachest: Ich will fort nicht mehr horen die Stimme des HERRN, meines Gottes, und das grofie Feuer nicht mehr sehen, daß ich nicht sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Und der HERR sprach zu mir: Sie haben wohl geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Ich will ihnen einen Propheten, wie du bist, erwecken aus ihren Brudern und meine Worte in seinen Mund geben; der soil zu ihnen reden alles, was ich ihm gebieten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Und wer meine Worte nicht horen wird, die er in meinem Namen reden wird, von dem will ich\'s fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Doch wenn ein Prophet vermessen ist, zu reden in meinem Namen, das ich ihm nicht geboten habe zu reden, und welcher redet in dem Namen anderer Gotter, derselbe Prophet soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Ob du aber in deinem Herzen sagen wurdest: Wie kann ich merken, welches Wort der HERR nicht geredet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Wenn der Prophet redet in dem Namen des HERRN, und wird nichts draus und kommt nicht, das ist das Wort, das der HERR nicht geredet hat: der Prophet hat es aus Vermessenheit geredet, darum scheuedich nicht vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Wenn der HERR, dein Gott, die Volker ausgerottet hat, welcher Land dirder HERR, dein Gott, geben wird, daß du sie einnehmest, und in ihren Stadten und Hausern wohnest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'sollst du dirdrei Stadte aussondern im Lande, das dir der HERR, dein Gott, geben wird einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Und sollst gelegene Orte wahlen und die Grenze deines Landes, das dirder HERR, dein Gott, austeilen wird, in drei Kreise scheiden, daß dahin fliehe, wer einen Totschlag getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Und das soil die Sache sein, daß dahin fliehe, der einen Totschlag getan hat, daß er lebendig bleibe: Wenn jemand seinen Nachsten schlagt, nicht vorsatzlich, und hat vorhin keinen Haft auf ihn gehabt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'sondern als wenn jemand mitseinem Nachsten in den Wald ginge, Holz zu hauen, und holete mit der Hand die Axt aus, das Holz abzuhauen, und das Eisen führe vom Stiel und trafe seinen Nachsten, daß er stürbe, der soil in dieser Stadte eine fliehen, daß er lebendig bleibe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'auf daß nicht der Blutracher dem Totschlager nachjage, weil sein Herz erhitzt ist, und ergreife ihn, weil der Weg so feme ist, und schlage ihm seine Seele, so doch kein Urteil des Todes an ihm ist, weil er keinen Haft vorhin zu ihm getragen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Darum gebiete ich dir, daß du drei Stadte aussonderst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Und so der HERR, dein Gott, deine Grenze weitern wird, wie er deinen Vatern geschworen hat, und gibt dir alles Land, das er geredet hat, deinen Vatern zu geben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, '(so du anders alle diese Gebote halten wirst, daß du danach tust, die ich dir heute gebiete, daß du den HERRN, deinen Gott, liebest und in seinen Wegen wandelst dein Leben lang), so sollst du noch drei Stadte tun zu diesen dreien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'auf daß nicht unschuldig Blut in deinem Lande vergossen werde, das dir der HERR, dein Gott, gibt zum Erbe, und kommen Blutschulden auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Wenn aber jemand Haft tragt wider seinen Nachsten und lauert auf ihn und macht sich über ihn und schlagt ihm seine Seele tot und fleucht in dieser Stadte eine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'so sollen die Altesten in seiner Stadt hinschicken und ihn von dannen holen lassen und ihn in die Hande des Blutrachers geben, daß er sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Deine Augen sollen sein nicht verschonen, und sollst das unschuldige Blut aus Israel tun, daß dir\'s wohlgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du sollst deines Nachsten Grenze nicht zurücktreiben, die die Vorigen gesetzt haben in deinem Erbteil, das du erbest im Lande das dir der HERR, dein Gott, gegeben hat einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Es soil kein einzelner Zeuge wider jemand auftreten über irgend einer Missetat Oder Sünde, es sei, welcherlei Sünde es sei, die man tun kann, sondern in dem Munde zweier Oder dreier Zeugen soil die Sache bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Wenn ein freveler Zeuge wider jemand auftritt, über ihn zu bezeugen eine Ubertretung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'so sollen die beiden Manner, die eine Sache miteinander haben, vor dem HERRN, vor den Priestern und Richtern stehen, die zur selben Zeit sein werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'und die Richter sollen wohl forschen. Und wenn der falsche Zeuge hat ein falsch Zeugnis wider seinen Bruder gegeben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'so sollt ihr ihm tun, wie er gedachte seinem Bruder zu tun, dati du den Bosen von dirwegtust,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'auf dafi die andern horen, sich furchten und nicht mehr solche bose Stucke vornehmen zu tun unter dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Dein Auge soil sein nicht schonen. Seele um Seele, Auge um Auge, Zahn um Zahn, Hand um Hand, Full um Fud.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Wenn du in einen Krieg zeuchst wider deine Feinde und siehest Rosse und Wagen des Volks, das grader sei, denn du, so furchte dich nicht vor ihnen; denn der HERR, dein Gott, der dich aus Agyptenland gefuhret hat, ist mir dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Wenn ihr nun hinzukommt zum Streit, so soil der Priester herzutreten und mit dem Volk reden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'und zu ihnen sprechen: Israel, hore zu! Ihrgehet heute in den Streit wider eure Feinde. Euer Herz verzage nicht; furchtet euch nicht und erschrecket nicht und lasset euch nicht grauen vor ihnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'denn der HERR, euer Gott, gehet mit euch, dad er fur euch streite mit euren Feinden, euch zu helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Aber die Amtleute sollen mit dem Volk reden und sagen: Welcher ein neu Haus gebauet hat und hat\'s noch nicht eingeweihet, der gehe hin und bleibe in seinem Hause, auf dad er nicht sterbe im Krieg, und ein andererweihe es ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Welcher einen Weinberg gepfianzet hat und hat ihn noch nicht gemein gemacht, der gehe hin und bleibe daheim, dad er nicht im Kriege sterbe, und ein anderer mache ihn gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Welcher ein Weib ihm vertrauet hat und hat sie noch nicht heimgeholet, der gehe hin und bleibe daheim, dad er nicht im Kriege sterbe, und ein anderer hole sie heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Und die Amtleute sollen weiter mit dem Volk reden und sprechen: Welcher sich furchtet und ein verzagtes Herz hat, der gehe hin und bleibe daheim, auf dad er nicht auch seiner Bruder Herz feige mache, wie sein Herz ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Und wenn die Amtleute ausgeredet haben mit dem Volk, so sollen sie die Hauptleute vor das Volk an die Spitze stellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Wenn du vor eine Stadt zeuchst, sie zu bestreiten, so sollst du ihr den Frieden anbieten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Antwortet sie dir friedlich und tut dir auf, so soil all das Volk, das drinnen funden wird, dir zinsbar und untertan sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Will sie aber nicht friedlich mit dir handeln und will mit dir kriegen, so belagere sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Und wenn sie der HERR, dein Gott, dir in die Hand gibt, so sollst du alles; was mannlich drinnen ist, mit des Schwerts Scharfe schlagen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'ohne die Weiber, Kinder und Vieh und alles, was in der Stadt ist, und alien Raub sollst du unter dich austeilen; und sollst essen von der Ausbeute deiner Feinde, die dir der HERR, dein Gott, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Also sollst du alien Stadten tun, die sehr feme von dir liegen und nicht hie von den Stadten sind dieser Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Aber in den Stadten dieser Volker, die dir der HERR, dein Gott, zum Erbe geben wird, sollst du nichts leben lassen, was den Odem hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'sondern sollst sie verbannen, namlich die Hethiter, Amoriter, Kanaaniter, Pheresiter, Heviter und Jebusiter, wie dir der HERR, dein Gott, geboten hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'auf dad sie euch nicht lehren tun alle die Greuel, die sie ihren Gottern tun, und ihr euch versundiget an dem HERRN, eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Wenn du vor einer Stadt lange Zeit liegen mudt, wider die du streitest, sie zu erobern, so sollst du die Baume nicht verderben, dad du mit Axten dran fahrest; denn du kannst davon essen, darum sollst du sie nicht ausrotten. Ist\'s doch Holz auf dem Felde und nicht Mensch, dad es vor dir ein Bollwerk sein moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Welches aber Baume sind, die du weidt, dad man nicht davon isset, die sollst du verderben und ausrotten und Bollwerk draus bauen wider die Stadt, die mit dir krieget, bis dad du ihrer machtig werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Wenn man einen Erschlagenen findetim Lande, das dir der HERR, dein Gott, geben wird einzunehmen, und liegt im Felde, und man nicht weid, wer ihn erschlagen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'so sollen deine Altesten, und Richter hinausgehen und von dem Erschlagenen messen an die Stadte, die umher liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Welche Stadt die nachste ist, derselben Altesten sollen eine junge Kuh von den Rindern nehmen, damit man nicht gearbeitet noch am Joch gezogen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'und sollen sie hinabfuhren in einen kiesichten Grund, der weder gearbeitet noch besaet ist, und daselbst im Grunde ihr den Hals abhauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Da sollen herzukommen die Priester, die Kinder Levi; denn der HERR, dein Gott, hat sie erwahlet, dad sie ihm dienen und seinen Namen loben, und nach ihrem Munde sollen alle Sachen und alle Schaden gehandelt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Und alle Altesten derselben Stadt sollen herzutreten zu dem Erschlagenen und ihre Hande waschen uber die junge Kuh, der im Grunde der Hals abgehauen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'und sollen antworten und sagen: Unsere Hande haben dies Blut nicht vergossen, so haben\'s auch unsere Augen nicht gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Sei gnadig deinem Volk Israel, das du, der HERR, erloset hast; lege nicht das unschuldige Blut auf dein Volk Israel! So werden sie uber dem Blut versohnetsein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Also sollst du das unschuldige Blut von dir tun, dad du tust, was recht ist vor den Augen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Wenn du in einen Streit zeuchst wider deine Feinde, und der HERR, dein Gott, gibt dir sie in deine Hande, dad du ihre Gefangenen wegfuhrest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'und siehest unter den Gefangenen ein schon Weib und hast Lust zu ihr, dad du sie zum Weibe nehmest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'so fuhre sie in dein Haus und lad ihr das Haar abscheren und ihre Nagel beschneiden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'und die Kleider ablegen, darinnen sie gefangen ist, und lad sie sitzen in deinem Hause und beweinen einen Mond lang ihren Vater und ihre Mutter; danach schlaf bei ihr und nimm sie zur Ehe und lad sie dein Weib sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Wenn du aber nicht Lust zu ihr hast, so sollst du sie auslassen, wo sie hin will, und nicht um Geld verkaufen noch versetzen, darum dad du sie gedemutiget hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Wenn jemand zwei Weiber hat, eine, die er lieb hat, und eine, die er hasset, und sie ihm Kinder gebaren, beide die liebe und die feindselige, dad der Erstgeborene der feindseligen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'und die Zeit kommt, dad erseinen Kindern das Erbe austeile, so kann er nicht den Sohn der liebsten zum erstgeborenen Sohn machen fur den erstgeborenen Sohn der feindseligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'sondern er soil den Sohn der feindseligen fur den ersten Sohn erkennen, dad er ihm zwiefaltig gebe alles, das vorhanden ist; denn derselbe ist seine erste Kraft, und der Erstgeburt Recht ist sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Wenn jemand einen eigenwilligen und ungehorsamen Sohn hat, der seines Vaters und Mutter Stimme nicht gehorchet, und wenn sie ihn zuchtigen, ihnen nicht gehorchen will,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'so soil ihn sein Vater und Mutter greifen und zu den Altesten der Stadt fuhren und zu dem Tor desselben Orts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'und zu den Altesten der Stadt sagen: Dieser unser Sohn ist eigenwillig und ungehorsam und gehorcht unserer Stimme nicht und ist ein Schlemmer und Trunkenbold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'So sollen ihn steinigen alle Leute derselben Stadt, daß er sterbe, und sollst also den Bosen von dir tun, da(S es ganz Israel hore und sich furchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Wenn jemand eine Sunde getan hat, die des Todes würdig ist, und wird also getotet, daß man ihn an ein Holz hanget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'so soli sein Leichnam nicht uber Nacht an dem Holz bleiben, sondern sollst ihn desselben Tages begraben; denn ein Gehenkter ist verflucht bei Gott auf da(S du dein Land nicht verunreinigest, das dir der HERR, dein Gott, gibt zum Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Wenn du deines Bruders Ochsen Oder Schaf siehest irre gehen, so sollst du dich nicht entziehen von ihnen, sondern sollst sie wieder zu deinem Bruder fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Wenn aber dein Bruder dir nicht nahe ist und kennest ihn nicht, so sollst du sie in dein Haus nehmen, daß sie bei dir seien, bis sie dein Bruder suche, und dann ihm wiedergebest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Also sollst du tun mit seinem Esel, mit seinem Kleide und mit allem Verlorenen, das dein Bruder verlieret, und du es findest; du kannst dich nicht entziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Wenn du deines Bruders Esel Oder Ochsen siehest fallen auf dem Wege, so sollst du dich nicht von ihm entziehen, sondern sollst ihm aufhelfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ein Weib soli nicht Mannsgerate tragen, und ein Mann soli nicht Weiberkleider antun; denn wer solches tut, der ist dem HERRN, deinem Gott, ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Wenn du auf dem Wege findest ein Vogelnest auf einem Baum Oder auf der Erde mit Jungen Oder mit Eiern, und daß die Mutter auf den Jungen Oder auf den Eiern sitzet, so sollst du nicht die Mutter mit den Jungen nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'sondern sollst die Mutter fliegen lassen und die Jungen nehmen, auf daß dir\'s wohlgehe und lange lebest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Wenn du ein neu Haus bauest, so mache eine Lehne drum auf deinem Dache, auf daß du nicht Blut auf dein Haus ladest, wenn jemand herabfiele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Du sollst deinen Weinberg nicht mit mancherlei besaen, daß du nicht zur Fulle heiligest solchen Samen, den du gesaet hast neben dem Einkommen des Weinberges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du sollst nicht ackern zugleich mit einem Ochsen und Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du sollst nicht anziehen ein Kleid von Wolle und Leinen zugleich gemenget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Du sollst dir Lapplein machen an den vier Fittichen deines Mantels, damit du dich bedeckest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Wenn jemand ein Weib nimmt und wird ihr gram, wenn ersie beschlafen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'und legt ihr was Schandliches auf und bringet ein bos Geschrei uber sie aus und spricht: Das Weib habe ich genommen, und da ich mich zu ihr tat, fand ich sie nicht Jungfrau:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'so sollen der Vater und Mutter der Dime sie nehmen und vor die Altesten der Stadt in dem Tor hervorbringen der Dime Jungfrauschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Und der Dime Vater soil zu den Altesten sagen: Ich habe diesem Manne meine Tochter zum Weibe gegeben; nun ist er ihr gram worden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'und legt ein schandlich Ding auf sie und spricht: Ich habe deine Tochter nicht Jungfrau funden; hie ist die Jungfrauschaft meiner Tochter. Und sollen die Kleider vor den Altesten der Stadt ausbreiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'So sollen die Altesten der Stadt den Mann nehmen und zuchtigen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'und um hundert Sekel Silbers büften und dieselben der Dime Vater geben, darum daü er eine Jungfrau in Israel beruchtiget hat; und soli sie zum Weibe nehmen, daß ersie sein Leben lang nicht lassen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ist\'s aber die Wahrheit, daß die Dime nicht ist Jungfrau funden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'so soil man, sie heraus vor die Tur ihres Vaters Hauses fuhren, und die Leute der Stadt sollen sie zu Tod steinigen, darum daß sie eine Torheit in Israel begangen und in ihres Vaters Hause gehuret hat; und sollst das Bose von dir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Wenn jemand erfunden wird, der bei einem Weibe schlaft, die einen Ehemann hat, so sollen sie beide sterben, der Mann und das Weib, bei der er geschlafen hat; und sollst das Bose von Israel tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Wenn eine Dime jemand vertraut ist, und ein Mann kriegt sie in der Stadt und schlaft bei ihr,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'so sollt ihr sie alle beide zu der Stadt Tor ausfuhren und sollt sie beide steinigen, daß sie sterben: die Dime darum, daß sie nicht geschrieen hat, weil sie in der Stadt war; den Mann darum, daß er seines Nachsten Weib geschandet hat; und sollst das Bose von dir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Wenn aber jemand eine vertraute Dime auf dem Felde kriegt und ergreift sie und schlaft bei ihr, so soil der Mann allein sterben, der bei ihr geschlafen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Und der Dime sollst du nichts tun, denn sie hat keine Sunde des Todes wert getan, sondern gleichwie jemand sich wider seinen Nachsten erhübe und schlüge seine Seele tot, so ist dies auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Denn erfand sie auf dem Felde, und die vertraute Dime schrie, und war niemand, der ihr half.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Wenn jemand an eine Jungfrau kommt, die nicht vertrauet ist, und ergreift sie und schlaft bei ihr, und findet sich also,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'So soil, der sie beschlafen hat, ihrem Vater funfzig Sekel Silbers geben und soil sie zum Weibe haben, darum daß er sie geschwacht hat; er kann sie nicht lassen sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Niemand soil seines Vaters Weib nehmen und nicht aufdecken seines Vaters Decke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Es soil kein Zerstoftener noch Verschnittener in die Gemeine des FIERRN kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Es soil auch kein Hurenkind in die Gemeine des HERRN kommen, auch nach dem zehnten Glied, sondern soil schlecht nicht in die Gemeine des HERRN kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Die Ammoniter und Moabiter sollen nicht in die Gemeine des HERRN kommen, auch nach dem zehnten Glied, sondern sie sollen nimmermehr hineinkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'darum daß sie euch nicht zuvorkamen mit Brot und Wasser auf dem Wege, da ihr aus Agypten zoget, und dazu wider euch dingeten den Bileam den Sohn Beors von Pethor aus Mesopotamien, daß er dich verfluchen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Aber der HERR, dein Gott, wollte Bileam nicht horen und wandelte dir den Fluch in den Segen, darum daß dich der HERR, dein Gott, lieb hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Du sollst ihnen weder Gluck noch Gutes wunschen dein Leben lang ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Den Edomiter sollst du nicht fur Greuel halten; er ist dein Bruder. Den Agypter sollst du auch nicht fur Greuel halten; denn du bist ein Fremdling in seinem Lande gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Die Kinder, die sie im dritten Gliede zeugen, sollen in die Gemeine des HERRN kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Wenn du aus dem Lager gehest wider deine Feinde, so hute dich vor allem Bosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Wenn jemand unterdir ist, der nicht rein ist, daß ihm des Nachts was widerfahren ist, der soil hinaus vor das Lager gehen und nicht wieder hineinkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'bis er vor Abends sich mit Wasser bade. Und wenn die Sonne untergegangen ist, soil er wieder ins Lager gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Und du sollst auften vor dem Lager einen Ort haben, dahin du zur Not hinausgehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Und sollst ein Schauflein haben, und wenn du dich drauften setzen willst, sollst du damit graben; und wenn du gesessen bist, sollst du zuscharren, was von dir gegangen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Denn der HERR, dein Gott, wandelt unter deinem Lager, daß er dich errette, und gebe deine Feinde vor dir. Darum soil dein Lager heilig sein, daß keine Schande unter dir gesehen werde, und er sich von dir wende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Du sollst den Knecht nicht seinem Herrn überantworten, der von ihm zu dir sich entwandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Er soil bei dir bleiben an dem Ort, den er erwahlet in deiner Tore einem ihm zu gut; und sollst ihn nicht schinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Es soil keine Hure sein unter den Tochtem Israels, und kein Hurer unter den Sohnen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du sollst keinen Hurenlohn noch Hundgeld in das Haus Gottes, deines HERRN, bringen aus irgend einem Gelubde; denn das ist dem HERRN, deinem Gott, beides ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Du sollst an deinem Bruder nicht wuchern, weder mit Geld, noch mit Speise, noch mit allem, damit man wuchern kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'An dem Fremden magst du wuchern, aber nicht an deinem Bruder, auf daß dich der HERR, dein Gott, segne in allem, das du vornimmst im Lande, dahin du kommst, dasselbe einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Wenn du dem HERRN, deinem Gott, ein Gelubde tust, so sollst du es nicht verziehen zu halten; denn der HERR, dein Gott, wird\'s von dirfordern, und wird dir Stinde sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Wenn du das Geloben unterwegen lassest, so ist dir\'s keine Stinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Aber was zu deinen Lippen ausgegangen ist, sollst du halten und danach tun, wie du dem HERRN, deinem Gott, freiwillig gelobet hast, das du mit deinem Munde geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Wenn du in deines Nachsten Weinberg gehest, so magst du der Trauben essen nach deinem Willen, bis du satt habest; aber du sollst nichts in dein Gefad tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 26, 'Wenn du in die Saat deines Nachsten gehest, so magst du mit der Hand Ahren abrupfen; aber mit der Sichel sollst du nicht drinnen hin und her fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Wenn jemand ein Weib nimmt und ehelicht sie, und sie nicht Gnade findet vor seinen Augen urn etwa einer Unlust willen, so soil er einen Scheidebrief schreiben und ihr in die Hand geben und sie aus seinem Hause lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Wenn sie dann aus seinem Hause gegangen ist und hingehet und wird eines andern Weib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'und derselbe andere Mann ihr auch gram wird und einen Scheidebrief schreibt und ihr in die Hand gibt und sie aus seinem Hause lasset; Oder so derselbe andere Mann stirbt, der sie zum Weibe genommen hatte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'so kann sie ihr erster Mann, der sie auslied, nicht wiederum nehmen, dad sie sein Weib sei, nachdem sie ist unrein; denn solches ist ein Greuel vor dem HERRN, auf dad du das Land nicht zu Sünden machest, das dir der HERR, dein Gott, zum Erbe gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Wenn jemand neulich ein Weib genommen hat, der soil nicht in die Heerfahrt ziehen, und man soil ihm nichts auflegen. Er soil frei in seinem Hause sein ein Jahr lang, daß er frbhlich sei mit seinem Weibe, das er genommen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Du sollst nicht zu Pfande nehmen den untersten und obersten Muhlstein; denn er hat dir die Seele zu Pfand gesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Wenn jemand funden wird, der aus seinen Brndern eine Seele stiehlt aus den Kindern Israel und versetzt Oder verkauft sie, solcher Dieb soil sterben, daß du das Bose von dirtust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Hüte dich vor der Plage des Aussatzes, daß du mit Fleid haltest und tust alles, das dich die Priester, die Leviten, lehren; und wie sie euch gebieten, das sollt ihr halten und danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Bedenke, was der HERR, dein Gott, tat mit Mirjam auf dem Wege, da ihr aus Agypten zoget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Wenn du deinem Nachsten irgend eine Schuld borgest, so sollst du nicht in sein Haus gehen und ihm ein Pfand nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'sondern du sollst drauden stehen, und er, dem du borgest, soil sein Pfand zu dir herausbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Ist er aber ein Durftiger, so sollst du dich nicht schlafen legen uber seinem Pfande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'sondern sollst ihm sein Pfand wiedergeben, wenn die Sonne untergehet, dad er in seinem Kleide schlafe und segne dich. Das wird dir vor dem HERRN, deinem Gott, eine Gerechtigkeit sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du sollst dem Durftigen und Armen seinen Lohn nicht vorbehalten, ersei von deinen Brudern Oder Fremdling, der in deinem Lande und in deinen Toren ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'sondern sollst ihm seinen Lohn des Tages geben, dad die Sonne nicht drüber untergehe; denn er ist dürftig und erhalt seine Seele damit, auf dad er nicht wider dich den HERRN anrufe, und sei dir Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Die Vater sollen nicht fur die Kinder noch die Kinder fur die Vater sterben, sondern ein jeglicher soli fur seine Sünde sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du sollst das Recht des Fremdlings und des Waisen nicht beugen und sollst der Witwe nicht das Kleid zum Pfande nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Denn du sollst gedenken, dad du Knecht in Agypten gewesen bist, und der HERR, dein Gott, dich von dannen erloset hat. Darum gebiete ich dir, dad du solches tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Wenn du auf deinem Acker geerntet hast und einer Garbe vergessen hast auf dem Acker, so sollst du nicht umkehren, dieselbe zu holen, sondern sie soil des Fremdlings, des Waisen und der Witwe sein, auf dad dich der HERR, dein Gott, segne in alien Werken deiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Wenn du deine Olbaume hast geschuttelt, so sollst du nicht nachschütteln; es soil des Fremdlings, des Waisen und der Witwe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Wenn du deinen Weinberg gelesen hast, so sollst du nicht nachlesen; es soil des Fremdlings, des Waisen und der Witwe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Und sollst gedenken, dad du Knecht in Agyptenland gewesen bist; darum gebiete ich dir, dad du solches tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Wenn ein Hader ist zwischen Mannern, so soil man sie vor Gericht bringen und sie richten und den Gerechten rechtsprechen und den Gottlosen verdammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Und so der Gottlose Schlage verdienet hat, soil ihn der Richter heiden niederfallen, und sollen ihn vor ihm schlagen nach dem Mad und Zahl seiner Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Wenn man ihm vierzig Schlage gegeben hat, soil man ihn nicht mehr schlagen, auf dad nicht, so man mehr Schlage gibt, er zu viel geschlagen werde, und dein Bruder scheudlich vor deinen Augen sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du sollst dem Ochsen, der da drischet, nicht das Maul verbinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Wenn Bruder beieinanderwohnen, und einer stirbt ohne Kinder, so soil des Verstorbenen Weib nicht einen fremden Mann drauden nehmen, sondern ihr Schwager soil sie beschlafen und zum Weihe nehmen und sie ehelichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Und den ersten Sohn, den sie gebieret, soil er bestatigen nach dem Namen seines verstorbenen Bruders, daß, sein Name nicht vertilget werde aus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Gefallt es aber dem Manne nicht, daß er seine Schwagerin nehme, so soil sie, seine Schwagerin, hinaufgehen unter das Tor vor die Altesten und sagen: Mein Schwager weigert sich, seinem Bruder einen Namen zu erwecken in Israel, und will mich nicht ehelichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'So sollen ihn die Altesten der Stadt fordern und mit ihm reden. Wenn erdann stehet und spricht: Es gefallt mir nicht, sie zu nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'so soli seine Schwagerin zu ihm treten vor den Altesten und ihm einen Schuh ausziehen von seinen Fuften und ihn anspeien; und soil antworten und sprechen: Also soil man tun einem jeden Manne, der seines Bruders Haus nicht erbauen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Und sein Name soil in Israel heiften des Barfüfters Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Wenn sich zween Manner miteinander hadern, und des einen Weib lauft zu, daß sie ihren Mann errette von der Hand des, der ihn schlagt, und strecket ihre Hand aus und ergreifet ihn bei seiner Scham,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'so sollst du ihrdie Hand abhauen, und dein Auge soil ihrer nicht verschonen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du sollst nicht zweierlei Gewicht in deinem Sack, graft und klein, haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'und in deinem Hause soli nicht zweierlei Scheffel, graft und klein, sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Du sollst ein vollig und recht Gewicht und einen volligen und rechten Scheffel haben, auf daß dein Leben lange wahre in dem Lande, das dir der HERR, dein Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Denn wer solches tut, der ist dem HERRN, deinem Gott, ein Greuel, wie alle, die ubel tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Gedenke, was dir die Amalekiter taten auf dem Wege, da ihr aus Agypten zoget:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'wie sie dich angriffen auf dem Wege und schlugen deine Hintersten, alle die Schwachen, die dir hinten nachzogen, da du mude und mattwarst, und furchteten Gott nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Wenn nun der HERR, dein Gott, dich zur Ruhe bringet von alien deinen Feinden umher im Lande, das dir der HERR, dein Gott, gibt zum Erbe einzunehmen, so sollst du das Gedachtnis der Amalekiter austilgen unter dem Himmel. Das vergift nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Wenn du ins Land kommst, das dir der HERR, dein Gott, zum Erbe geben wird, und nimmst es ein und wohnest drinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'so sollst du nehmen allerlei erste Fruchte des Landes, die aus der Erde kommen, die der HERR, dein Gott, dir gibt, und sollst sie in einen Korb legen und hingehen an den Ort, den der HERR, dein Gott, erwahlen wird, daß sein Name daselbstwohne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'und sollst zu dem Priester kommen, der zu der Zeit da ist, und zu ihm sagen: Ich bekenne heute dem HERRN, deinem Gott, daß ich kommen bin in das Land, das der HERR unsern Vatern geschworen hat, uns zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Und der Priester soil den Korb nehmen von deiner Hand und vor dem Altar des HERRN, deines Gottes, niedersetzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Da sollst du antworten und sagen vor dem HERRN, deinem Gott: Die Syrerwollten meinen Vater umbringen; derzog hinab nach Agypten und war daselbst ein Fremdling mit geringem Volk und ward daselbst ein graft, stark und viel Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Aber die Agypter handelten uns ubel und zwangen uns und legten einen harten Dienst auf uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Da schrieen wirzu dem HERRN, dem Gott unserer Vater; und der HERR erhorete unser Schreien und sah unser Elend, Angst und Not');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'und fuhrete uns aus Agypten mit machtiger Hand und ausgerecktem Arm und mit groftem Schrecken, durch Zeichen und Wunder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'und brachte uns an diesen Ort und gab uns dies Land, da Milch und Honig innen fleuftt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Nun bringe ich die ersten Fruchte des Landes, die du, HERR, mir gegeben hast. Und sollst sie lassen vor dem HERRN, deinem Gott, und anbeten vor dem HERRN, deinem Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'und frohlich sein uber allem Gut, das dir der HERR, dein Gott, gegeben hat und deinem Hause, du und der Levit und der Fremdling, der bei dir ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Wenn du alle Zehnten deines Einkommens zusammengebracht hast im dritten Jahr, das ist ein Zehnten-Jahr, so sollst du dem Leviten, dem Fremdling, dem Waisen und der Witwe geben, daß sie essen in deinem Tor und satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Und sollst sprechen vor dem HERRN, deinem Gott: Ich habe gebracht, das geheiliget ist, aus meinem Hause; und habe es gegeben den Leviten, den Fremdlingen, den Waisen und den Witwen nach all deinem Gebot, das du mir geboten hast; ich habe deine Gebote nicht ubergangen noch vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ich habe nicht davon gegessen in meinem Leide und habe nicht davon getan in Unreinigkeit; ich habe nicht zu den Toten davon gegeben; ich bin der Stimme des HERRN, meines Gottes, gehorsam gewesen und habe getan alles, wie du mir geboten hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Sieh herab von deiner heiligen Wohnung vom Himmel und segne dein Volk Israel und das Land, das du uns gegeben hast, wie du unsern Vatern geschworen hast, ein Land, da Milch und Honiq innen fleuftt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Heutigestages gebeut dir der HERR, dein Gott, daß du tust nach alien diesen Geboten und Rechten, daß du sie haltest und danach tust von ganzem Herzen und von ganzer Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Dem HERRN hast du heute geredet, daß er dein Gott sei, daß du in alien seinen Wegen wandelst und haltest seine Gesetze, Gebote und Rechte und seiner Stimme gehorchest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Und der HERR hat dir heute geredet, daß du sein eigen Volk sein sollst, wie er dir geredet hat, daß du alle seine Gebote haltest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'und erdich das hochste mache, und du geruhmet, gepreiset und geehret werdest uber alle Vdlker, die er gemacht hat; daß du dem HERRN, deinem Gott, ein heilig Volk seiest, wie er geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Und Mose gebot samt den Altesten Israels dem Volk und sprach: Behaltet alle Gebote, die ich euch heute gebiete!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Und zu der Zeit, wenn ihr uber den Jordan gehet ins Land, das dir der HERR, dein Gott, geben wird, sollst du grolie Steine aufrichten und sie mit Kalk tunchen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'und drauf schreiben alle Worte dieses Gesetzes, wenn du hinuberkommst, auf daß du kommest ins Land, das der HERR, dein Gott, dir geben wird, ein Land, da Milch und Honig innen fleufit, wie der HERR, deiner Vater Gott, dir geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Wenn ihr nun uber den Jordan gehet, so sollt ihr solche Steine aufrichten (davon ich euch heute gebiete) auf dem Berge Ebal und mit Kalk tunchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Und sollst daselbst dem HERRN, deinem Gott, einen steinernen Altar bauen, daruber kein Eisen fahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Von ganzen Steinen sollst du diesen Altar dem HERRN, deinem Gott, bauen und Brandopfer drauf opfern dem HERRN, deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Und sollst Dankopfer opfern und daselbst essen und frohlich sein vordem HERRN, deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Und sollst auf die Steine alle Worte dieses Gesetzes schreiben, klar und deutlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Und Mose samt den Priestern, den Leviten, redeten mit dem ganzen Israel und sprachen: Merke und hore zu, Israel! Heute dieses Tages bistdu ein Volk worden des HERRN; deines Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'daß du der Stimme des HERRN, deines Gottes, gehorsam seiest und tust nach seinen Geboten und Rechten, die ich dir heute gebiete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Und Mose gebot dem Volk desselben Tages und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Diese sollen stehen auf dem Berge Grisim, zu segnen das Volk, wenn ihr uber den Jordan gegangen seid: Simeon, Levi, Juda, Isaschar, Joseph und Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Und diese sollen stehen auf dem Berge Ebal, zu fluchen: Ruben, Gad, Asser, Sebulon, Dan und Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Und die Leviten sollen anheben und sagen zu jedermann von Israel mit lauter Stimme:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Verflucht sei, wer einen Gotzen Oder gegossen Bild macht, einen Greuel des HERRN, ein Werkder Werkmeister Hande, und setzt es verborgen! Und alles Volk soil antworten und sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Verflucht sei, wer seinem Vater Oder Mutter fluchet! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Verflucht sei, wer seines Nachsten Grenze engert! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Verflucht sei, wer einen Blinden irren macht auf dem Wege! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Verflucht sei, wer das Recht des Fremdlings, des Waisen und der Witwe beuget! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Verflucht sei, wer bei seines Vaters Weib liegt, daß er aufdecke den Fittich seines Vaters! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Verflucht sei, wer irgend bei einem Vieh liegt! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Verflucht sei, wer bei seiner Schwester liegt, die seines Vaters Oder seiner Mutter Tochter ist! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Verflucht sei, wer bei seiner Schwieger liegt! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Verflucht sei, wer seinen Nachsten heimlich schlagt! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Verflucht sei, wer Geschenke nimmt, daß er die Seele des unschuldigen Bluts schlagt! Und alles Volk soil sagen: Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Verflucht sei, wer nicht alle Worte dieses Gesetzes erfüllet, daß er danach tue! Und alles Volk soil sagen; Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Und wenn du der Stimme des HERRN, deines Gottes, gehorchen wirst, daß du haltest und tust alle seine Gebote, die ich dir heute gebiete, so wird dich der HERR, dein Gott, das hochste machen uber alle Volkerauf Erden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'und werden uber dich kommen alle diese Segen und werden dich treffen, darum daß du der Stimme des HERRN, deines Gottes, bist gehorsam gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Gesegnet wirst du sein in der Stadt, gesegnet auf dem Acker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Gesegnet wird sein die Frucht deines Leibes, die Frucht deines Landes und die Frucht deines Viehes und die Fruchte deiner Ochsen und die Fruchte deiner Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Gesegnet wird sein, dein Korb und dein Ubriges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Gesegnet wirst du sein, wenn du ein gehest, gesegnet, wenn du ausgehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Und der HERR wird deine Feinde, die sich wider dich auflehnen, vor dir schlagen; durch einen Weg sollen sie ausziehen wider dich und durch sieben Wege vor dir fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Der HERR wird gebieten dem Segen, daß er mit dir sei in deinem Keller und in allem, das du vornimmst, und wird dich segnen in dem Lande, das dir der HERR, dein Gott, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Der HERR wird dich ihm zum heiligen Volk aufrichten, wie er dir geschworen hat, darum daß du die Gebote des HERRN, deines Gottes, haltst und wandelst in seinen Wegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'daß alle Volker auf Erden werden sehen, dad du nach dem Namen des HERRN genennet bist, und werden sich vor dir furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Und der HERR wird machen, dad du Uberflud an Gutern haben wirst, an der Frucht deines Leibes, an der Frucht deines Viehes, an der Frucht deines Ackers, auf dem Lande, das der HERR deinen Vatern geschworen hat, dirzu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Und der HERR wird dir seinen guten Schatz auftun, den Himmel, dad erdeinem Lande Regen gebe zu seiner Zeit, und dad er segne alle Werke deiner Hande. Und du wirst vielen Volkern leihen, du aber wirst von niemand borgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Und der HERR wird dich zum Haupt machen und nicht zum Schwanz, und wirst oben schweben und nicht unten liegen, darum dad du gehorsam bist den Geboten des HERRN, deines Gottes, die ich dir heute gebiete, zu halten und zu tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'und dad du nicht weichest von irgend einem Wort, das ich euch heute gebiete, weder zur Rechten noch zur Linken, damit du andern Gottern nachwandelst, ihnen zu dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Wenn du aber nicht gehorchen wirst der Stimme des HERRN, deines Gottes, dad du haltest und tust alle seine Gebote und Rechte, die ich dir heute gebiete, so werden alle diese Fluche uber dich kommen und dich treffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Verflucht wirst du sein in der Stadt, verflucht auf dem Acker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Verflucht wird sein dein Korb und dein ubriges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Verflucht wird sein die Frucht deines Leibes, die Frucht deines Landes, die Frucht deiner Ochsen und die Frucht deiner Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Verflucht wirst du sein, wenn du eingehest, verflucht, wenn du ausgehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Der HERR wird unter dich senden Unfall, Unrat und Unglück in allem, das du vor die Hand nimmst, daß du tust, bis du vertilget werdest und bald untergehest urn deines bosen Wesens willen, daß du mich verlassen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Der HERR wird dir die Sterbedruse anhangen, bis da(S er dich vertilge in dem Lande, dahin du kommst, dasselbe einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Der HERR wird dich schlagen mit Schwulst, Fieber, Hitze, Brunst, Durre, giftiger Luft und Gelbsucht und wird dich verfolgen, bis er dich umbringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Dein Himmel, der liber deinem Haupt ist, wird ehern sein, und die Erde unter dir eisern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Der HERR wird deinem Lande Staub und Asche fur Regen geben vom Himmel auf dich, bis du vertilget werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Der HERR wird dich vor deinen Feinden schlagen. Durch einen Weg wirst du zu ihnen ausziehen, und durch sieben Wege wirst du vor ihnen fliehen; und wirst zerstreuet werden unter alle Reiche auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Dein Leichnam wird eine Speise sein allem Gevogel des Himmels und allem Tier auf Erden; und niemand wird sein, der sie scheucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Der HERR wird dich schlagen mit Drusen Agyptens, mit Feigwarzen, mit Grind und Kratze, dafi du nicht kannst heil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Der HERR wird dich schlagen mit Wahnsinn, Blindheit und Rasen des Herzens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'und wirst tappen im Mittag, wie ein Blinder tappet im Dunkeln; und wirst auf deinem Wege kein Gluck haben und wirst Gewalt und Unrecht leiden müssen dein Leben lang; und niemand wird dir helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Ein Weib wirst du dir vertrauen lassen, aber ein andererwird bei ihrschlafen. Ein Haus wirst du bauen, aber du wirst nicht drinnen wohnen. Einen Weinberg wirst du pflanzen, aber du wirst ihn nicht gemein machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Dein Ochse wird vor deinen Augen geschlachtet werden, aber du wirst nicht davon essen. Dein Esel wird vor deinem Angesicht mit Gewalt genommen und dir nicht wiedergegeben werden. Dein Schaf wird deinen Feinden gegeben werden, und niemand wird dir helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Deine Sohne und deine Tochter werden einem andern Volk gegeben werden, daß deine Augen zusehen und verschmachten liber ihnen taglich, und wird keine Starke in deinen Handen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Die Früchte deines Landes und alle deine Arbeit wird ein Volk verzehren, das du nicht kennest; und wirst Unrecht leiden und zerstolien werden dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Und wirst unsinnig werden vor dem, das deine Augen sehen müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Der HERR wird dich schlagen mit einer bosen Drlise an den Knieen und Waden, daß du nicht kannst geheilet werden, von den Fufisohlen an bis auf die Scheitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Der HERR wird dich und deinen Konig, den du liber dich gesetzt hast, treiben unter ein Volk, das du nicht kennest noch deine Vater; und wirst daselbst dienen andern Gottern, Holz und Steinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Und wirst ein Scheusal und ein Sprichwort und Spott sein unter alien Volkern, da dich der HERR hingetrieben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Du wirst viel Samens ausflihren auf das Feld und wenig einsammeln; denn die Heuschrecken werden\'s abfressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Weinberge wirst du pflanzen und bauen, aber keinen Wein trinken noch lesen; denn die Wlirmer werden\'s verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Olbaume wirst du haben in alien deinen Grenzen, aber du wirst dich nicht salben mit 01; denn dein Olbaum wird ausgerissen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Sohne und Tochter wirst du zeugen und doch nicht haben; denn sie werden gefangen weggefuhrt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Alle deine Baume und Früchte deines Landes wird das Ungeziefer fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Der Fremdling, der bei dir ist, wird über dich steigen und immer oben schweben; du aber wirst heruntersteigen und immer unterliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Er wird dir leihen, du aber wirst ihm nicht leihen; er wird das Haupt sein, und du wirst der Schwanz sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Und werden alle diese Flüche uber dich kommen und dich verfolgen und treffen, bis du vertilget werdest, darum dafi du der Stimme des HERRN, deines Gottes, nicht gehorchet hast, daß du seine Gebote und Rechte hieltest, die er dir qeboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Darum werden Zeichen und Wunder an dir sein und an deinem Samen ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'daß du dem HERRN, deinem Gott, nicht gedienet hast mit Freude und Lust deines Herzens, da du allerlei genug hattest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Und wirst deinem Feinde, den dir der HERR zuschicken wird, dienen in Hunger und Durst, in Blofte und allerlei Mangel, und er wird ein eisern Joch auf deinen Hals legen, bis daß er dich vertilge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Der HERR wird ein Volk uber dich schicken von feme, von der Welt Ende, wie ein Adler fleugt, des Sprache du nicht verstehest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'ein frech Volk, das nicht ansiehet die Person des Alten noch schonet der Junglinge;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'und wird verzehren die Frucht deines Viehes und die Frucht deines Landes, bis du vertilget werdest; und wird dir nichts uberlassen an Korn, Most, 01, an Fruchten der Ochsen und Schafe, bis daß dich\'s umbringe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'und wird dich angsten in alien deinen Toren, bis daß es niederwerfe deine hohen und festen Mauern, darauf du dich verlassest, in all deinem Lande; und wirst geangstet werden in alien deinen Toren, in deinem ganzen Lande, das dir der HERR, dein Gott, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Du wirst die Frucht deines Leibes fressen, das Fleisch deiner Sohne und deiner Tochter, die dir der HERR, dein Gott, gegeben hat, in der Angst und Not, damit dich dein Feind drangen wird;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'daß ein Mann, der zuvor sehr zartlich und in Lusten gelebt hat unter euch, wird seinem Bruder und dem Weibe in seinen Armen und dem Sohn, der noch übrig ist von seinen Sohnen, vergonnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'zu geben jemand unter ihnen von dem Fleisch seiner Sohne, das er frisset, sintemal ihm nichts übrig ist von allem Gut, in der Angst und Not, damit dich dein Feind drangen wird in alien deinen Toren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Ein Weib unter euch, das zuvor zartlich und in Lusten gelebt hat, daß sie nicht versucht hat, ihre Fuftsohlen auf die Erde zu setzen vor Zartlichkeit und Wollust, die wird dem Mann in ihren Armen und ihrem Sohn und ihrer Tochter vergonnen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'die Aftergeburt, die zwischen ihren eigenen Beinen ist ausgegangen, dazu ihre Sohne, die sie geboren hat; denn sie werden sie vor allerlei Mangel heimlich essen, in der Angst und Not, damit dich dein Feind drangen wird in deinen Toren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Wo du nicht wirst halten, daß du tust alle Worte dieses Gesetzes, die in diesem Buch geschrieben sind, daß du furchtest diesen herrlichen und schrecklichen Namen, den HERRN, deinen Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'so wird der HERR wunderlich mit dir umgehen, mit Plagen auf dich und deinen Samen, mit groften und langwierigen Plagen, mit bosen und langwierigen Krankheiten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'und wird dir zuwenden alle Seuche Agyptens, davordu dich furchtest, und werden diranhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Dazu alle Krankheit und alle Plage, die nicht geschrieben sind in dem Buch dieses Gesetzes, wird der HERR uber dich kommen lassen, bis du vertilget werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Und wird euerwenig Pobels uberbleiben, die ihr vorhin gewesen seid wie die Sterne am Himmel nach der Menge, darum daß du nicht gehorchet hast der Stimme des HERRN, deines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Und wie sich der HERR uber euch zuvor freute, daß er euch Gutes tate und mehrete euch, also wird er sich uber euch freuen, daß er euch umbringe und vertilge; und werdet verstoret werden von dem Lande, da du jetzt einzeuchst, es einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Denn der HERR wird dich zerstreuen unter alle Volker, von einem Ende der Welt bis ans andere; und wirst daselbst andern Gottern dienen, die du nicht kennest noch deine Vater, Holz und Steinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Dazu wirst du unter denselben Volkern kein bleibend Wesen haben, und deine Fuftsohlen werden keine Ruhe haben. Denn der HERR wird dir daselbst ein bebendes Herz geben und verschmachtete Augen und verdorrete Seele,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'daß dein Leben wird vor dir schweben. Nacht und Tag wirst du dich furchten und deines Lebens nicht sicher sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Des Morgens wirst du sagen: Ach, daß ich den Abend erleben mochte! Des Abends wirst du sagen: Ach, daß ich den Morgen erleben mochte! vor Furcht deines Herzens, die dich schrecken wird, und vor dem, das du mit deinen Augen sehen wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Und der HERR wird dich mit Schiffen voll wieder nach Agypten führen durch den Weg, davon ich gesagt habe: Du sollst ihn nicht mehr sehen. Und ihr werdet daselbst euren Feinden zu Knechten und Magden verkauft werden, und wird kein Kaufer da sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 69, 'Dies sind die Worte des Bundes, den der HERR Mose geboten hat, zu machen mit den Kindern Israel in der Moabiter Lande, zum andernmal, nachdem er denselben mit ihnen gemacht hatte in Horeb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Und Mose rief dem ganzen Israel und sprach zu ihnen: Ihr habt gesehen alles, was der HERR getan hat in Agypten vor euren Augen dem Pharao mit alien seinen Knechten und seinem ganzen Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'die großen Versuchungen, die deine Augen gesehen haben, daß es große Zeichen und Wunderwaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Und der HERR hat euch bis auf diesen heutigen fag noch nicht gegeben ein Herz, das verstandig ware, Augen, die da sahen, und Ohren, die da horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Er hat euch vierzig Jahre in der Wüste lassen wandeln; eure Kleidersind an euch nicht veraltet, und dein Schuh ist nicht veraltet an deinen Füßen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Ihr habt kein Brot gegessen und keinen Wein getrunken noch stark Getranke, auf daß du wissest, daß ich der HERR, euer Gott, bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Und da ihr kamet an diesen Ort, zog aus der Konig Sihon zu Hesbon und der Konig Og zu Basan uns entgegen, mit uns zu streiten. Und wir haben sie geschlagen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'und ihr Land eingenommen und zum Erbteil gegeben den Rubenitern und Gaditern und dem halben Stamm der Manassiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'So haltet nun die Worte dieses Bundes und tut danach, auf daß ihrweislich handeln moget in all eurem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Ihr stehet heute alle vor dem HERRN, eurem Gott, die Obersten eurer Stamme, eure Altesten, eure Amtleute, ein jedermann in Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'eure Kinder, eure Weiber, dein Fremdling, der in deinem Lager ist, beide dein Holzhauer und dein Wasserschopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'daß du einhergehen sollst in dem Bunde des HERRN, deines Gottes, und in dem Eide, den der HERR, dein Gott, heute mit dir macht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'auf daß er dich heute ihm zum Volk aufrichte, und er dein Gott sei, wie er dir geredet hat und wie er deinen Vatern, Abraham, Isaak und Jakob, geschworen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Denn ich mache diesen Bund und diesen Eid nicht mit euch alleine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'sondern beide mit euch, die ihr heute hie seid und mit uns stehet vor dem HERRN, unserm Gott, und mit denen, die heute nicht mit uns sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Denn ihrwisset, wie wir in Agyptenland gewohnet haben und mitten durch die Heiden gezogen sind, durch welche ihrzoget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'und sahet ihre Greuel und ihre Gotzen, Holz und Stein, Silber und Gold, die bei ihnen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Daß nicht vielleicht ein Mann, Oder ein Weib, Oder ein Gesinde, Oder ein Stamm unter euch sei, des Herz heute sich von dem HERRN, unserm Gott, gewandt habe, daß es hingehe und diene den Gottern dieser Volker, und werde vielleicht eine Wurzel unter euch, die da Galle und Wermut trage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'und ob er schon hore die Worte dieses Fluchs, dennoch sich segne in seinem Herzen und spreche: Es gehet mir wohl, weil ich wandele, wie es mein Herz dunket; auf daß die T runkene mit der Durstigen dahinfahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Da wird der HERR dem nicht gnadig sein, sondern dann wird sein Zorn und Eifer rauchen uber solchen Mann, und werden sich auf ihn legen alle Fluche, die in diesem Buch geschrieben sind. Und der HERR wird seinen Namen austilgen unter dem Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'und wird ihn absondern zum Unglück aus alien Stammen Israels laut aller Fluche des Bundes, der in dem Buch dieses Gesetzes geschrieben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'So werden dann sagen die Nachkommen eurer Kinder, die nach euch aufkommen werden, und die Fremden, die aus fernen Landen kommen, so sie die Plagen dieses Landes sehen und die Krankheiten, damit sie der HERR beladen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'daß er all ihr Land mit Schwefel und Salz verbrannt hat, daß es nicht besaet werden mag, noch wachset, noch kein Kraut drinnen aufgehet, gleichwie Sodom und Gomorrha, Adama und Zeboim umgekehret sind, die der HERR in seinem Zorn und Grimm umgekehret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'So werden alle Volker sagen: Warum hat der HERR diesem Lande also getan? Was ist das fur so großer, grimmiger Zorn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'So wird man sagen: Darum daß sie den Bund des HERRN, ihrer Vater Gott, verlassen haben, den er mit ihnen machte, da er sie aus Agyptenland führete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'und sind hingegangen und haben andern Gottern gedienet und sie angebetet, solche Gotter, die sie nicht kennen, und die ihnen nichts gegeben haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'darum ist des HERRN Zorn ergrimmet über dies Land, daß er über sie hat kommen lassen alle Fluche, die in diesem Buch geschrieben stehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'und der HERR hat sie aus ihrem Lande gestoßen mit großem Zorn, Grimm und Ungnade und hat sie in ein ander Land geworfen, wie es stehet heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Das Geheimnis des HERRN, unsers Gottes, ist offenbaret uns und unsern Kindern ewiglich, daß wir tun sollen alle Worte dieses Gesetzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Wenn nun über dich kommt dies alles, es sei der Segen Oder der Fluch, die ich dirvorgelegt habe, und in dein Herz gehest, wo du unter den Heiden bist, da dich der HERR, dein Gott, hin verstoßen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'und bekehrest dich zu dem HERRN, deinem Gott, daß du seiner Stimme gehorchest, du und deine Kinder, von ganzem Herzen und von ganzer Seele in allem, das ich dir heute gebiete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'so wird der HERR, dein Gott, dein Gefangnis wenden und sich deiner erbarmen und wird dich wieder versammeln aus alien Volkern, dahin dich der HERR, dein Gott, verstreuet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Wenn du bis an der Himmel Ende verstoßen warest, so wird dich doch der HERR, dein Gott, von dannen sammeln und dich von dannen holen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'und wird dich in das Land bringen, das deine Vater besessen haben, und wirstes einnehmen, und wird dir Gutes tun und dich mehren über deine Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Und der HERR, dein Gott, wird dein Herz beschneiden und das Herz deines Samens, daß du den HERRN, deinen Gott, liebest von ganzem Herzen und von ganzer Seele, auf daß du leben mogest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Aber diese Fluche wird der HERR, dein Gott, alle auf deine Feinde legen und auf die, die dich hassen und verfolgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Du aber wirst dich bekehren und der Stimme des HERRN gehorchen, daß du tust alle seine Gebote, die ich dir heute gebiete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Und der HERR, dein Gott, wird dir Gluck geben in alien Werken deiner Hande, an der Frucht deines Leibes, an der Frucht deines Viehes, an der Frucht deines Landes, daß dir\'s zu gut komme. Denn der HERR wird sich wenden, daß er sich uber dir freue, dir zu gut, wie er sich über deinen Vatern gefreuet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'darum daß du der Stimme des HERRN, deines Gottes; gehorchest, zu halten seine Gebote und Rechte, die geschrieben stehen im Buch dieses Gesetzes, so du dich wirst bekehren zu dem HERRN, deinem Gott, von ganzem Herzen und von ganzer Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Denn das Gebot, das ich dir heute gebiete, ist dir nicht verborgen, noch zu feme,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'noch im Himmel, daß du mochtest sagen: Wer will uns in den Himmel fahren und uns holen, daß wir\'s horen und tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Es ist auch nicht jenseit des Meers, daß du mochtest sagen: Wer will uns über das Meer fahren und uns holen, daß wir\'s horen und tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Denn es ist das Wort fast nahe bei dir in deinem Munde und in deinem Herzen, daß du es tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Siehe, ich habe dir heute vorgelegt das Leben und das Gute, den Tod und das Bose;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'der ich dir heute gebiete, daß du den HERRN, deinen Gott, liebest und wandelst in seinen Wegen, und seine Gebote, Gesetze und Rechte haltest und leben mdgest und gemehret werdest, daß dich der HERR, dein Gott, segne im Lande, da du einzeuchst, dasselbe einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Wendest du aber dein Herz und gehorchest nicht, sondern lassest dich verführen, daß du andere Gotter anbetest und ihnen dienest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'so verkündige ich euch heute, daß ihr umkommen werdet und nicht lange in dem Lande bleiben, da du hineinzeuchst uber den Jordan, dasselbe einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Ich nehme Himmel und Erde heute über euch zu Zeugen. Ich habe euch Leben und Tod, Segen und Fluch vorgelegt, daß du das Leben erwahlest und du und dein Same leben mogest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'daß ihr den HERRN, euren Gott, liebet und seiner Stimme gehorchet und ihm anhanget. Denn das ist dein Leben und dein langes Alter, daß du im Lande wohnest, das der HERR deinen Vatern, Abraham, Isaak und Jakob, geschworen hat, ihnen zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Und Mose ging hin und redete diese Worte mit dem ganzen Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'und sprach zu ihnen: Ich bin heute hundertundzwanzig Jahre alt, ich kann nicht mehr aus und ein gehen; dazu hat der HERR zu mir gesagt: Du sollst nicht über diesen Jordan gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Der HERR, dein Gott, wird selber vordir hergehen; er wird selber diese Volker vor dir her vertilgen, daß du sie einnehmest. Josua, der soil vor dir hinübergehen, wie der HERR geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Und der HERR wird ihnen tun, wie er getan hat Sihon und Og, den Konigen der Amoriter, und ihrem Lande, welche er vertilget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Wenn sie nun der HERR vor euch geben wird, so sollt ihr ihnen tun nach allem Gebot, das ich euch geboten habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Seid getrost und unverzagt, fürchtet euch nicht und lasset euch nicht vor ihnen grauen; denn der HERR, dein Gott, wird selber mit dir wandeln und wird die Hand nicht abtun noch dich verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Und Mose rief Josua und sprach zu ihm vor den Augen des ganzen Israel: Sei getrost und unverzagt; denn du wirst dies Volk ins Land bringen, das der HERR ihren Vatern geschworen hat, ihnen zu geben, und du wirst es unter sie austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Der HERR aber, der selber vor euch hergehet, der wird mit dir sein und wird die Hand nicht abtun noch dich verlassen. Furchte dich nicht und erschrick nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Und Mose schrieb dies Gesetz und gab\'s den Priestern, den Kindern Levi, die die Lade des Bundes des HERRN trugen, und alien Altesten Israels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'und gebot ihnen und sprach: Je über sieben Jahre, zur Zeit des Erlaßjahrs, am Fest der Laubhütten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'wenn das ganze Israel kommt, zu erscheinen vor dem HERRN, deinem Gott, an dem Ort, den er erwahlen wird, sollst du dies Gesetz vor dem ganzen Israel ausrufen lassen vor ihren Ohren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'namlich vor der Versammlung des Volks, beide der Manner und Weiber, Kinder und deines Fremdlings, der in deinem Tor ist; auf daß sie horen und lernen, damit sie den HERRN, ihren Gott, furchten und halten, daß sie tun alle Worte dieses Gesetzes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'und daß ihre Kinder, die es nicht wissen, auch horen und lernen; damit sie den HERRN, euren Gott, furchten alle eure Lebtage, die ihr auf dem Lande lebet, darein ihr gehet uber den Jordan einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Und der HERR sprach zu Mose: Siehe, deine Zeit ist herbeikommen, daü du sterbest. Rufe Josua und tretet in die Hutte des Stifts, dafi ich ihm Befehl tue. Mose ging hin mit Josua, und traten in die Hutte des Stifts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Der HERR aber erschien in der Hutte in einer Wolkensaule; und dieselbe Wolkensaule stund in der Hutte Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Und der HERR sprach zu Mose: Siehe, du wirst schlafen mit deinen Vatern; und dies Volk wird aufkommen und wird fremden Gottern nachhuren, des Landes, darein sie kommen, und wird mich verlassen und den Bund fahren lassen, den ich mit ihm gemacht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'So wird mein Zorn ergrimmen uber sie zur selben Zeit und werde sie verlassen und mein Antlitz vor ihnen verbergen, daß sie verzehret werden. Und wenn sie dann viel Ungluck und Angst treffen wird, werden sie sagen: Hat mich nicht dies Libel alles betreten, weil mein Gott nicht mit mir ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ich aber werde mein Antlitz verbergen zu der Zeit urn alles Bosen willen, das sie getan haben, daß sie sich zu andern Gottern gewandt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'So schreibet euch nun dies Lied und lehret es die Kinder Israel und leget es in ihren Mund, dafi mir das Lied ein Zeuge sei unterden Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Denn ich will sie ins Land bringen, das ich ihren Vatern geschworen habe, da Milch und Honig innen fleulit. Und wenn sie essen und satt und fett werden, so werden sie sich wenden zu andern Gottern und ihnen dienen, und mich lastern und meinen Bund fahren lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Und wenn sie dann viel Ungluck und Angst betreten wird, so soil dies Lied ihnen antworten zum Zeugnis; denn es soil nicht vergessen werden aus dem Munde ihres Samens. Denn ich weifi ihre Gedanken, damit sie schon jetzt umgehen, ehe ich sie ins Land bringe, das ich geschworen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Also schrieb Mose dies Lied zurselbigen Zeit und lehrete es die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Und befahl Josua, dem Sohn Nuns, und sprach: Sei getrost und unverzagt; denn du sollst die Kinder Israel ins Land führen, das ich ihnen geschworen habe, und ich will mit dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Da nun Mose die Worte dieses Gesetzes ganz ausgeschrieben hatte in ein Buch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'gebot er den Leviten, die die Lade des Zeugnisses des HERRN trugen, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Nehmet das Buch dieses Gesetzes und leget es in die Seite der Lade des Bundes des HERRN, eures Gottes, daß es daselbst ein Zeuge sei wider dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Denn ich kenne deinen Ungehorsam und Halsstarrigkeit. Siehe, weil ich noch heute mit euch lebe, seid ihr ungehorsam gewesen wider den HERRN; wieviel mehr nach meinem Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'So versammelt nun vor mich alle Altesten eurer Stamme und eure Amtleute, daß ich diese Worte vor ihren Ohren rede und Himmel und Erde wider sie zu Zeugen nehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Denn ich weift, daß ihr\'s nach meinem Tode verderben werdet und aus dem Wege treten, den ich euch geboten habe. So wird euch dann Ungluck begegnen hernach; darum daß ihr ubel getan habt vor den Augen des HERRN, daß ihr ihn erzurnet durch eurer Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Also redete Mose die Worte dieses Liedes ganz aus vor den Ohren der ganzen Gemeine Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Merket auf, ihr Himmel, ich will reden; und die Erde hore die Rede meines Mundes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Meine Lehre triefe wie der Regen, und meine Rede fliefte wie Tau, wie der Regen auf das Gras und wie die Tropfen auf das Kraut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Denn ich will den Namen des HERRN preisen. Gebt unserm Gott allein die Ehre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Er ist ein Fels. Seine Werke sind unstraflich; denn alles, was er tut, das ist recht. Treu ist Gott und kein Boses an ihm; gerecht und fromm ist er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Die verkehrte und bose Art fallt von ihm ab; sie sind Schandflecken und nicht seine Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Dankest du also dem HERRN, deinem Gott, du toll und toricht Volk? Ist er nicht dein Vater und dein HERR? Ist\'s nicht er allein, der dich gemacht und bereitet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Gedenke der vorigen Zeit bis daher und betrachte, was er getan hat an den alten Vatern. Frage deinen Vater, der wird dir\'s verkundigen, deine Altesten, die werden dir\'s sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Da der Allerhochste die Volker zerteilete und zerstreuete der Menschen Kinder, da setzte er die Grenzen der Volker nach der Zahl der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Denn des HERRN Teil ist sein Volk; Jakob ist die Schnur seines Erbes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Erfand ihn in der Wuste, in der durren Einode, da es heulet. Er fuhrete ihn und gab ihm das Gesetz. Er behutete ihn wie seinen Augapfel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'wie ein Adler ausfuhret seine Jungen und uber ihnen schwebet. Er breitete seine Fittiche aus und nahm ihn und trug sie auf seinen Flugeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Der HERR allein leitete ihn, und war kein fremder Gott mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Erlieft ihn hoch herfahren auf Erden und nahrete ihn mit den Fruchten des Feldes, und lieft ihn Honig saugen aus den Felsen und 01 aus den harten Steinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Butter von den Kuhen und Milch von den Schafen, samt dem Fett von den Lammern, und feiste Widder und Bocke mit fetten Nieren, und Weizen, und trankte ihn mitgutem Traubenblut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Da er aber fett und satt ward, ward ergeil. Er ist fett und dick und stark worden und hat den Gott fahren lassen, der ihn gemacht hat Er hat den Fels seines Heils gering geachtet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'und hat ihn zu Eifer gereizet durch Fremde, durch die Greuel hat er ihn erzurnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Sie haben den Feldteufeln geopfert und nicht ihrem Gott, den Gottern, die sie nicht kannten, den neuen, die zuvor nicht gewesen sind, die eure Vater nicht geehret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Deinen Fels, der dich gezeuget hat, hast du aus der Acht gelassen und hast vergessen Gottes, der dich gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Und da es der HERR sah, ward er zornig uber seine Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Und er sprach: Ich will mein Antlitz vor ihnen verbergen, will sehen, was ihnen zuletzt widerfahren wird; denn es ist eine verkehrte Art, es sind untreue Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Sie haben mich gereizet an dem, das nicht Gott ist; mit ihrer Abgotterei haben sie mich erzurnet und ich will sie wieder reizen an dem, das nicht ein Volk ist; an einem narrischen Volk will ich sie erzurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Denn das Feuer ist angegangen durch meinen Zorn und wird brennen bis in die unterste Holle; und wird verzehren das Land mit seinem Gewachs und wird anzünden die Grundfeste der Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Ich will alles Ungluck uber sie haufen, ich will alle meine Pfeile in sie schieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Vor Plunger sollen sie verschmachten und verzehret werden vom Fieber und jahem Tode. Ich will der Tiere Zahne unter sie schicken und der Schlangen Gift.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Auswendig wird sie das Schwert berauben und inwendig das Schrecken; beide, Jünglinge und Jungfrauen, die Sauglinge mit dem grauen Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ich will sagen: Wo sind sie? Ich werde ihr Gedachtnis aufheben unter den Menschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'wenn ich nicht den Zorn der Feinde scheuete, daß nicht ihre Feinde stolz wurden und mochten sagen: Unsere Macht ist hoch, und der HERR hat nicht solches alles getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Denn es ist ein Volk, da kein Rat innen ist, und ist kein Verstand in ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, '0 daß sie weise waren und vernahmen solches, daß sie verstünden, was ihnen hernach begegnen wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Wie geht es zu, daß einer wird ihrer tausend jagen und zween werden zehntausend fluchtig machen? Ist\'s nicht daß sie ihr Fels verkauft hat, und der FIERR hat sie ubergeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Denn unser Fels ist nicht wie ihr Fels, des sind unsere Feinde selbst Richter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Denn ihr Weinstock ist des Weinstocks zu Sodom und von dem Acker Gomorrhas; ihre Trauben sind Galle, sie haben bittere Beeren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'ihr Wein ist Drachengift und wutiger Ottern Galle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ist solches nicht bei mir verborgen und versiegelt in meinen Schatzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Die Rache ist mein; ich will vergelten. Zu seiner Zeit soli ihr Fuft gleiten; denn die Zeit ihres Unglucks ist nahe, und ihr Künftiges eüet herzu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Denn der HERR wird sein Volk richten und uber seine Knechte wird er sich erbarmen. Denn er wird ansehen, daß ihre Macht dahin, ist, und beide das Verschlossene und Verlassene weg ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Und man wird sagen: Wo sind ihre Gotter, ihr Fels, daraufsie traueten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'von welcher Opfer sie Fett aften und tranken den Wein ihres Trankopfers? Lasset sie aufstehen und euch helfen und euch schutzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Sehet ihr nun, daß ich\'s allein bin, und ist kein Gott neben mir? Ich kann toten und lebendig machen; ich kann schlagen und kann heüen, und ist niemand, der aus meiner Hand errette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Denn ich will meine Hand in den Himmel heben und will sagen: Ich lebe ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Wenn ich den Blitz meines Schwerts wetzen werde, und meine Hand zur Strafe greifen wird, so will ich mich wieder rachen an meinen Feinden und denen, die mich hassen, vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Ich will meine Pfeile mit Blut trunken machen, und mein Schwert soil Fleisch fressen uber dem Blut der Erschlagenen und uber dem Gefangnis und uber dem entbloftten Haupt des Feindes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jauchzet alle die ihr sein Volk seid; denn er wird das Blut seiner Knechte rachen und wird sich an seinen Feinden rachen und gnadig sein dem Lande seines Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Und Mose kam und redete alle Worte dieses Liedes vor den Ohren des Volks, er und Josua, der Sohn Nuns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Da nun Mose solches alles ausgeredet hatte zum ganzen Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'sprach er zu ihnen: Nehmet zu Herzen alle Worte, die ich euch heute bezeuge, daß ihr euren Kindern befehlet, daß sie halten und tun alle Worte dieses Gesetzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Denn es ist nicht ein vergeblich Wort an euch, sondern es ist euer Leben; und solch Wort wird euer Leben verlangern auf dem Lande, da ihr hingehet über den Jordan, daß ihr\'s einnehmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Und der HERR redete mit Mose desselben Tages und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Gehe auf das Gebirge Abarim, auf den Berg Nebo, der da liegt im Moabiterlande gegen Jericho über, und besiehe das Land Kanaan, das ich den Kindern Israel zum Eigentum geben werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'und stirb auf dem Berge, wenn du hinaufkommen bist, und versammle dich zu deinem Volk, gleichwie dein Bruder Aaron starb auf dem Berge Hor und sich zu seinem Volk versammelte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'darum daß ihr euch an mir versundiget habt unter den Kindern Israel bei dem Haderwasser zu Kades in der Wüste Zin, daß ihr mich, nicht, heiligtet unter den Kindern Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'denn du sollst das Land gegen dir sehen, das ich den Kindern Israel gebe, aber du sollst nicht hineinkommen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Dies ist der Segen, damit Mose, der Mann Gottes, die Kinder Israel vorseinem Tode segnete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'und sprach: Der HERR ist von Sinai kommen und ist ihnen aufgegangen von Seir; er ist hervorgebrochen von dem Berge Paran und ist kommen mitviel tausend Heiligen; zu seiner rechten Hand ist ein feuriges Gesetz an sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Wie hat er die Leute so lieb! Alle seine Heiligen sind in deiner Hand; sie werden sich setzen zu deinen Fußen und werden lernen von deinen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mose hat uns das Gesetz geboten, dem Erbe der Gemeine Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Und er verwaltete das Amt eines Konigs und hielt zusammen die Haupter des Volks samt den Stammen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben lebe und sterbe nicht, und sein Pobel sei gering!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Dies ist der Segen Judas. Und er sprach: HERR, erhore die Stimme Judas, mache ihn zum Regenten in seinem Volk und laß seine Macht groß werden, und ihm müsse wider seine Feinde geholfen werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Und zu Levi sprach er: Dein Recht und dein Licht bleibe bei deinem heiligen Mann, den du versuchet hast zu Massa, da ihr hadertet am Haderwasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Wer zu seinem Vater und zu seiner Mutter spricht: Ich sehe ihn nicht, und zu seinem Bruder: Ich kenne ihn nicht, und zu seinem Sohn: Ich weiß nicht: die halten deine Rede und bewahren deinen Bund;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'die werden Jakob deine Rechte lehren und den Israel dein Gesetz; die werden Rauchwerk vor deine Nase legen und ganze Opfer auf deinen Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'HERR, segne sein Vermogen und laß dir gefallen die Werke seiner Hande; zerschlage den Rücken derer, die sich wider ihn auflehnen, und derer, die ihn hassen, daß sie nicht aufkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Und zu Benjamin sprach er: Das Liebliche des HERRN wird sicher wohnen; allezeit wird er uber ihm halten und wird zwischen seinen Schultern wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Und zu Joseph sprach er: Sein Land liegt im Segen des HERRN. Da sind edle Fruchte vom Himmel, vom Tau und von der Tiefe, die unten liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Da sind edle Fruchte von der Sonne und edle reife Fruchte der Monden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'und von den hohen Bergen gegen Morgen und von den Hügeln fur und fur');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'und edle Fruchte von der Erde, und was drinnen ist. Die Gnade des, der in dem Busch wohnete, komme auf das Haupt Josephs und auf den Scheitel des Nasir unter seinen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Seine Herrlichkeit ist wie ein erstgeborner Ochse, und seine Horner sind wie Einhorners Horner; mit denselben wird er die Volker stoßen zuhauf bis an des Landes Ende. Das sind die Tausende Ephraims und die Tausende Manasses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Und zu Sebulon sprach er: Sebulon, freue dich deines Auszugs! Aber, Isaschar, freue dich deiner Hutten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Sie werden die Volker auf den Berg rufen und daselbst opfern Opfer der Gerechtigkeit. Denn sie werden die Menge des Meers saugen und die versenkten Schatze im Sande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Und zu Gad sprach er: Gad sei gesegnet, der Raummacher; er liegt wie ein Lowe und raubet den Arm und die Scheitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Und er sah, daß ihm ein Haupt gegeben war, ein Lehrer, der verborgen ist, welcher kam mit den Obersten des Volks und verschaffte die Gerechtigkeit des HERRN und seine Rechte an Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Und zu Dan sprach er: Dan ein junger Lowe; er wird fließen von Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Und zu Naphthali sprach er: Naphthali wird genug haben, was er begehret, und wird voll Segens des HERRN sein; gegen Abend und Mittag wird sein Besitz sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Und zu Asser sprach er: Asser sei gesegnet mit Sohnen; ersei angenehm seinen Brudern und tunke seinen Fuß in 01!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Eisen und Erz sei an seinen Schuhen; dein Alter sei wie deine Jugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Es ist kein Gott als der Gott des Gerechten. Der im Himmel sitzt, der sei deine Hilfe, und des Herrlichkeit in Wolken ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Das ist die Wohnung Gottes von Anfang und unter den Armen ewiglich. Und er wird vor dir her deinen Feind austreiben und sagen: Sei vertilget!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israel wird sicher alleine wohnen; der Brunn Jakobs wird sein auf dem Lande, da Korn und Most ist; dazu sein Himmel wird mit Tau triefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Wohl dir, Israel, wer ist dir gleich? 0 Volk, das du durch den HERRN selig wirst, der deiner Hilfe Schild und das Schwert deines Sieges ist! Deinen Feinden wird\'s fehlen; aber du wirst auf ihrer Hohe einhertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Und Mose ging von dem Gefilde der Moabiter auf den Berg Nebo, auf die Spitze des Gebirges Pisga, gegen Jericho uber. Und der HERR zeigte ihm das ganze Land Gilead bis gen Dan');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'und das ganze Naphthali und das Land Ephraim und Manasse und das ganze Land Juda bis an das außerste Meer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'und gegen Mittag und die Gegend der Breite Jerichos, der Palmenstadt, bis gen Zoar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Und der HERR sprach zu ihm: Dies ist das Land, das ich Abraham, Isaak und Jakob geschworen habe, und gesagt: Ich will es deinem Samen geben. Du hast es mit deinen Augen gesehen, aber du sollst nicht hinubergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Also starb Mose, der Knecht des HERRN, daselbst im Lande der Moabiter nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Und er begrub ihn im Tal, im Lande der Moabiter, gegen dem Hause Peor. Und hat niemand sein Grab erfahren bis auf diesen heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Und Mose war hundertundzwanzig Jahre alt, da er starb. Seine Augen waren nicht dunkel worden, und seine Kraft war nicht verfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Und die Kinder Israel beweineten Mose im Gefilde der Moabiter dreiftig Tage. Und wurden vollendet die Tage des Weinens und Klagens uber Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Josua aber, der Sohn Nuns, ward erfullet mit dem Geist der Weisheit; denn Mose hatte seine Hande auf ihn gelegt. Und die Kinder Israel gehorchten ihm und taten, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Und es stund hinfort kein Prophet in Israel auf wie Mose, den der HERR erkannt hatte von Angesicht zu Angesicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'zu allerlei Zeichen und Wundern, dazu ihn der HERR sandte, daß er sie tate in Agyptenland, an Pharao und an alien seinen Knechten und an all seinem Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'und zu aller dieser machtigen Hand und groften Gesichten, die Mose tat vor den Augen des ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Nach dem Tode Moses, des Knechtes des HERRN, sprach der HERR zu Josua, dem Sohn Nuns, Moses Diener:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mein Knecht Mose ist gestorben; so mache dich nun auf und zeuch uber diesen Jordan, du und dies ganze Volk, in das Land, das ich ihnen, den Kindern Israel, gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Alle Statte, darauf eure Fuftsohlen treten werden, habe ich euch gegeben, wie ich Mose geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Von der Wüste an und diesem Libanon bis an das grofte Wasser Phrath, das ganze Land der Hethiter, bis an das grofte Meer gegen dem Abend, sollen eure Grenze sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Es soil dir niemand widerstehen dein Leben lang. Wie ich mit Mose gewesen bin, also will ich auch mit dir sein. Ich will dich nicht verlassen noch von dir weichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sei getrost und unverzagt; denn du sollst diesem Volk das Land austeilen, das ich ihren Vatern geschworen habe, daß ich\'s ihnen geben wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Sei nur getrost und sehr freudig, daß du haltest und tust allerdinge nach dem Gesetz, das dir Mose, mein Knecht, geboten hat. Weiche nicht davon, weder zur Rechten noch zur Linken, auf daß du weislich handeln mogest in allem, das du tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Und laft das Buch dieses Gesetzes nicht von deinem Munde kommen, sondern betrachte es Tag und Nacht, auf daß du haltest und tust allerdinge nach dem, das drinnen geschrieben stehet. Alsdann wird dir\'s gelingen in allem, das du tust, und wirst weislich handeln konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Siehe, ich habe dir geboten, daß du getrost und freudig seiest. Laft dir nicht grauen und entsetze dich nicht; denn der HERR, dein Gott, ist mit dir in allem, das du tun wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Da gebot Josua den Hauptleuten des Volks und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Gehet durch das Lager und gebietet dem Volk und sprechet: Schaffet euch Vorrat; denn uber drei Tage werdet ihr uber diesen Jordan gehen, daß ihr hineinkommet und das Land einnehmet, das euch der HERR, euer Gott, geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Und zu den Rubenitern, Gaditern und dem halben Stamm Manasse sprach Josua:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Gedenket an das Wort, das euch Mose, der Knecht des HERRN, sagte und sprach: Der HERR, euer Gott, hat euch zur Ruhe gebracht und dies Land gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Eure Weiber und Kinder und Vieh lasset im Lande bleiben, das euch Mose gegeben hat diesseit des Jordans; ihr aber solit vor euren Brudern herziehen gerustet, was streitbare Manner sind, und ihnen helfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'bis daß der HERR eure Bruder auch zur Ruhe bringt, wie euch, daß sie auch einnehmen das Land, das ihnen der HERR, euer Gott, geben wird. Alsdann sollt ihr wieder umkehren in euer Land, das euch Mose, der Knecht des HERRN, eingegeben hat zu besitzen, diesseit des Jordans, gegen der Sonnen Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Und sie antworteten Josua und sprachen: Alles, was du uns geboten hast, das wollen wir tun, und wo du uns hinsendest, da wollen wir hingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Wie wir Mose gehorsam sind gewesen, so wollen wir dir auch gehorsam sein, allein dafi der HERR, dein Gott, nur mit dir sei, wie er mit Mose war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Werdeinem Munde ungehorsam istund nicht gehorchet deinen Worten in allem, das du uns gebeutst, der soil sterben. Sei nur getrost und unverzagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Josua aber, der Sohn Nuns, hatte zween Kundschafter heimlich ausgesandt von Sittim und ihnen gesagt: Gehet hin, besehet das Land und Jericho. Die gingen hin und kamen in das Haus einer Hure, die hieli Rahab, und kehreten zu ihrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Da ward dem Konige zu Jericho gesagt: Siehe, es sind in dieser Nacht Manner hereinkommen von den Kindern Israel, das Land zu erkunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Da sandte der Konig zu Jericho zu Rahab und lied ihr sagen: Gib die Manner heraus, die zu dir in dein Haus kommen sind; denn sie sind kommen, das ganze Land zu erkunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Aber das Weib verbarg die zween Manner und sprach also: Es sind ja Manner zu mir hereinkommen, aber ich wullte nicht, von wannen sie waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Und da man die Tore wollte zuschlieden, da es finster war, gingen sie hinaus, dad ich nicht weid, wo sie hingegangen sind. Jaget ihnen eilend nach; denn ihrwerdet sie ergreifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sie aber lied sie auf das Dach steigen und verdeckte sie unter die Flachsstengel, die sie ihr auf dem Dache ausgebreitet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Aber die Manner jagten ihnen nach auf dem Wege zum Jordan bis an die Furt. Und man schlod das Tor zu, da die hinaus waren, die ihnen nachjagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Und ehe denn die Manner sich schlafen legten, stieg sie zu ihnen hinauf auf das Dach');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'und sprach zu ihnen: Ich weid, dad der HERR euch das Land gegeben hat; denn ein Schrecken ist über uns gefallen vor euch, und alle Einwohner des Landes sind vor eurer Zukunft feige worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Denn wir haben gehoret, wie der HERR hat das Wasser im Schüfmeer ausgetrocknet vor euch her, da ihr aus Agypten zoget, und was ihr den zween Konigen der Amoriter, Sihon und Og, jenseit des Jordans getan habt, wie ihr sie verbannet habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Und seit wir solches gehoret haben, ist unser Herz verzagt und ist kein Mut mehr in jemand vor eurer Zukunft; denn der HERR, euer Gott, ist ein Gott, beide oben im Himmel und unten auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'So schworet mir nun bei dem HERRN, daß, weil ich an euch Barmherzigkeit getan habe, daß ihr auch meines Vaters Hause Barmherzigkeit tut; und gebet mir ein gewili Zeichen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'daß ihr leben lasset meinen Vater, meine Mutter, meine Bruder und meine Schwestern und alles, was sie haben, und errettet unsere Seelen von dem Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Die Manner sprachen zu ihr: tun wir nicht Barmherzigkeit und Treue an dir, wenn uns der HERR das Land gibt, so soil unsere Seele fur euch des Todes sein, sofern du unser Geschaft nicht verratest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Da lieli sie dieselben am Seil durchs Fenster hernieder; denn ihr Haus war an der Stadtmauer, und sie wohnete auch auf der Mauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Und sie sprach zu ihnen: Gehet auf das Gebirge, daß euch nicht begegnen, die euch nachjagen, und verberget euch daselbst drei Tage, bis daß die wiederkommen, die euch nachjagen; danach gehet eure Straüe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Die Manner aber sprachen zu ihr: Wir wollen aber des Eides los sein, den du von uns genommen hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'wenn wir kommen ins Land, und du nicht dies rote Seil in das Fenster knupfest, damit du uns herniedergelassen hast und zur dir ins Haus versammelst deinen Vater, deine Mutter, deine Bruder und deines Vaters ganzes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Und wer zur Tür deines Hauses herausgehet, des Blut sei auf seinem Haupte, und wir unschuldig; aber aller, die in deinem Hause sind, so eine Hand an sie gelegt wird, so soli ihr Blut auf unserm Haupte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Und so du etwas von diesem unserm Geschafte wirst nachsagen, so wollen wir des Eides los sein, den du von uns genommen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Sie sprach: Es sei, wie ihr saget; und lieli sie gehen. Und sie gingen hin. Und sie knüpfte das rote Seil ins Fenster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Sie aber gingen hin und kamen aufs Gebirge und blieben drei Tage daselbst, bis daß die wiederkamen, die ihnen nachjagten. Denn sie hatten sie gesucht auf alien Strafien und doch nicht funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Also kehreten die zween Manner wieder und gingen vom Gebirge und fuhren über; und kamen zu Josua, dem Sohn Nuns, und erzahleten ihm alles, wie sie es funden hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'und sprachen zu Josua: Der HERR hat uns alles Land in unsere Hande gegeben; auch so sind alle Einwohner des Landes feige vor uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Und Josua machte sich frühe auf; und sie zogen aus Sittim und kamen an den Jordan, er und alle Kinder Israel, und blieben daselbst über Nacht, ehe sie hinüberzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Nach dreien Tagen aber gingen die Hauptleute durchs Lager');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'und geboten dem Volk und sprachen: Wenn ihr sehen werdet die Lade des, Bundes des HERRN, eures Gottes, und die Priester aus den Leviten sie tragen, so ziehet aus von eurem Ort und folget ihr nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Doch dafi zwischen euch und ihr Raum sei bei zweitausend Ellen. Ihr sollt nicht zu ihr nahen, auf dafi ihrwisset, auf welchem Wege ihrgehen sollet; denn ihr seid den Weg vorhin nicht gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Und Josua sprach zum Volk: Heiliget euch; denn morgen wird der HERR ein Wunder unter euch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Und zu den Priestern sprach er: Traget die Lade des Bundes und gehet vor dem Volk her. Da trugen sie die Lade des Bundes und gingen vor dem Volk her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Und der HERR sprach zu Josua: Heute will ich anfahen, dich graft zu machen vor dem ganzen Israel, daß sie wissen, wie ich mit Mose gewesen bin, also auch mit dir sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Und du gebeut den Priestern, die die Lade des Bundes tragen, und sprich: Wenn ihr kommt vorn ins Wasser des Jordans, so stehet stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Und Josua sprach zu den Kindern Israel: Herzu, und horet die Worte des HERRN, eures Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Und sprach: Dabei sollt ihr merken, daß ein lebendiger Gott unter euch ist, und daß er vor euch austreiben wird die Kanaaniter, Hethiter, Heviter, Pheresiter, Gergositer, Amoriter und Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Siehe, die Lade des Bundes des Herrschers uber alle Welt wird vor euch hergehen in den Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'So nehmet nun zwolf Manner aus den Stammen Israels, aus jeglichem Stamm einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Wenn dann die Fuftsohlen der Priester, die des HERRN Lade, des Herrschers über alle Welt, tragen, in des Jordans Wasser sich lassen, so wird sich das Wasser, das von oben herabfleuftt im Jordan, abreiften, daß es über einem Haufen stehen bleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Da nun das Volk auszog aus seinen Hütten, daß sie über den Jordan gingen, und die Priester die Lade des Bundes vor dem Volk her trugen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'und an den Jordan kamen und ihre Füfte vorn ins Wasser tunkten (der Jordan aber war voll an alien seinen Ufern, die ganze Zeit der Ernte),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'da stund das Wasser; das von oben herniederkam, aufgerichtet über einem Haufen, sehr feme von den Leuten der Stadt, die zur Seite Zarthans liegt; aber das Wasser, das zum Meer hinunterlief, zum Salzmeer, das nahm ab und verfloft. Also ging das Volk hinüber gegen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Und die Priester, die die Lade des Bundes des HERRN trugen, stunden also im Trocknen mitten im Jordan. Und ganz Israel ging trocken durch, bis das ganze Volk alles über den Jordan kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Und der HERR sprach zu Josua:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Nehmet euch zwolf Manner, aus jeglichem Stamm einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Und gebietet ihnen und sprecht: Hebet auf aus dem Jordan zwolf Steine von dem Ort, da die Füfte der Priester also stehen, und bringet sie mit euch hinüber, daß ihr sie in der Herberge lasset, da ihr diese Nacht herbergen werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Da rief Josua zwolf Manner, die verordnet waren von den Kindern Israel, aus jeglichem Stamm einen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'und sprach zu ihnen: Gehet hinüber vor die Lade des HERRN, eures Gottes, mitten in den Jordan, und hebe ein jeglicher einen Stein auf seine Achsel, nach der Zahl der Stamme der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'daß sie ein Zeichen seien unter euch. Wenn eure Kinder hernachmals ihre Vater fragen werden und sprachen: Was tun diese Steine da?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'daß ihr dann ihnen saget, wie das Wasser des Jordans abgerissen sei vor der Lade des Bundes des HERRN, da sie durch den Jordan ging, daß diese Steine den Kindern Israel ein ewig Gedachtnis seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Da taten die Kinder Israel, wie ihnen Josua geboten hatte, und trugen zwolf Steine mitten aus dem Jordan, wie der HERR zu Josua gesagt hatte, nach der Zahl der Stamme der Kinder Israel, und brachten sie mit sich hinüber in die Herberge und lieften sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Und Josua richtete zwolf Steine auf mitten im Jordan, da die Füfte der Priester gestanden waren, die die Lade des Bundes trugen; und sind noch daselbst bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Denn die Priester, die die Lade trugen, stunden mitten im Jordan, bis daß alles ausgerichtet ward, das der HERR Josua geboten hatte, dem Volk zu sagen; wie denn Mose Josua geboten hatte. Und das Volk eilete und ging hinüber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Da nun das Volk ganz hinübergegangen war, da ging die Lade des HERRN auch hinüber, und die Priester vor dem Volk her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Und die Rubeniter und Gaditer und der halbe Stamm Manasse gingen gerüstet vor den Kindern Israel her, wie Mose zu ihnen geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Bei vierzigtausend, gerüstet zum Heer, gingen vor dem HERRN zum Strait auf das Gefilde Jerichos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'An dem Tage machte der HERR Josua graft vor dem ganzen Israel; und furchteten ihn, wie sie Mose furchteten, sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Und der HERR sprach zu Josua:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Gebeut den Priestern, die die Lade des Zeugnisses tragen, daß sie aus dem Jordan heraufsteigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Also gebot Josua den Priestern und sprach: Steiget herauf aus dem Jordan!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Und da die Priester, die die Lade des Bundes des HERRN trugen, aus dem Jordan heraufstiegen und mit ihren Fuftsohlen aufs Trockene traten, kam das Wasser des Jordans wieder an seine Statte und floft, wie vorhin, an alien seinen Ufern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Es war aber der zehnte Tag des ersten Monden, da das Volk aus dem Jordan heraufstieg; und lagerten sich in Gilgal, gegen den Morgen der Stadt Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Und die zwolf Steine, die sie aus dem Jordan genommen hatten, richtete Josua auf zu Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Und sprach zu den Kindern Israel: Wenn eure Kinder hernachmals ihre Vater fragen werden und sagen: Was sollen diese Steine?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'so sollt ihfs ihnen kundtun und sagen: Israel ging trocken durch den Jordan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'da der HERR, euer Gott, das Wasser des Jordans vertrocknete, vor euch, bis ihr hinuberginget, gleichwie der HERR, euer Gott, tat in dem Schilfmeer, das er vor uns vertrocknete, bis wir hindurchgingen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'auf daß alle Volker auf Erden die Hand des HERRN erkennen, wie machtig sie ist; daß ihr den HERRN, euren Gott, furchtet allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Da nun alle Konige der Amoriter, die jenseit des Jordans gegen Abend wohneten, und alle Konige der Kanaaniter am Meer horeten, wie der HERR das Wasser des Jordans hatte ausgetrocknet vor den Kindern Israel, bis dafi sie hinubergingen, verzagte ihr Herz, und war kein Mut mehr in ihnen vor den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Zu der Zeit sprach der HERR zu Josua: Mache dir steinerne Messer und beschneide wieder die Kinder Israel zum andernmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Da machte ihm Josua steinerne Messer und beschnitt die Kinder Israel auf dem Hugel Araloth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Und das ist die Sache, darum Josua beschnitt alles Volk, das aus Agypten gezogen war, Mannsbilde; denn alle Kriegsleute waren gestorben in der Wuste auf dem Wege, da sie aus Agypten zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Denn alles Volk, das auszog, war beschnitten; aber alles Volk, das in der Wuste geboren war, auf dem Wege, da sie aus Agypten zogen, das war nicht beschnitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Denn die Kinder Israel wandelten vierzig Jahre in der Wuste; bis dafi das ganze Volk der Kriegsmanner, die aus Agypten gezogen waren, umkamen, darum daß sie der Stimme des HERRN nicht gehorchet hatten; wie denn der HERR ihnen geschworen hatte, daß sie das Land nicht sehen sollten, welches der HERR ihren Vatern geschworen hatte, uns zu geben, ein Land, da Milch und Honig innen fleulit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Derselben Kinder, die an ihrer Statt waren aufkommen, beschnitt Josua; denn sie hatten Vorhaut und waren auf dem Wege nicht beschnitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Und da das ganze Volk beschnitten war, blieben sie an ihrem Ort im Lager, bis sie heil wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Und der HERR sprach zu Josua: Heute habe ich die Schande Agyptens von euch gewendet Und dieselbe Statte ward Gilgal genannt bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Und als die Kinder Israel also in Gilgal das Lager hatten, hielten sie Passah am vierzehnten Tage des Monden am Abend auf dem Gefilde Jerichos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Und alien vom Getreide des Landes am andern Tage des Passah, namlich ungesauert Brot und Sangen, eben desselben Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Und das Man horete auf des andern Tages, da sie des Landes Getreide alien, daß die Kinder Israel kein Man mehr hatten, sondern sie alien des Getreides vom Lande Kanaan von demselben Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Und es begab sich, da Josua bei Jericho war, daß er seine Augen aufhub und ward gewahr, daß ein Mann gegen ihm stund und hatte ein bloli Schwert in seiner Hand. Und Josua ging zu ihm und sprach zu ihm: Gehorest du uns an, Oder unsern Feinden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Er sprach: Nein, sondern ich bin ein Furst uber das Heer des HERRN und bin jetzt kommen. Da fiel Josua auf sein Angesicht zur Erde und betete an und sprach zu ihm: Was saget mein Herr seinem Knechte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Und der Furst uber das Heer des HERRN sprach zu Josua: Zeuch deine Schuhe aus von deinen Fülien; denn die Statte, darauf du stehest, ist heilig. Und Josua tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jericho aber war verschlossen und verwahret vor den Kindern Israel, daß niemand aus Oder ein kommen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Aber der HERR sprach zu Josua: Siehe da, ich habe Jericho samt ihrem Konige und Kriegsleuten in deine Hand gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Lali alle Kriegsmanner rings urn die Stadt hergehen einmal; und tue sechs Tage also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Am siebenten Tage aber lali die Priester sieben Posaunen des Halljahrs nehmen vor der Lade her; und gehet desselben siebenten Tages siebenmal urn die Stadt und la(i die Priester die Posaunen blasen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Und wenn man des Halljahrs Horn blaset und tonet, daß ihr die Posaunen horet, so soil das ganze Volk ein groli Feldgeschrei machen, so werden der Stadt Mauern umfallen; und das Volk soli hineinfallen, ein jeglicher stracks vor sich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Da rief Josua, der Sohn Nuns, den Priestern und sprach zu ihnen: Traget die Lade des Bundes, und sieben Priester lasset sieben Halljahrsposaunen tragen vor der Lade des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Zum Volk aber sprach er: Ziehet hin und gehet urn die Stadt; und wer gerustet ist, gehe vor der Lade des HERRN her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Da Josua solches dem Volk gesagt hatte, trugen die sieben Priester sieben Halljahrsposaunen vor der Lade des HERRN her und gingen und bliesen die Posaunen; und die Lade des Bundes des HERRN folgte ihnen nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Und wer gerustet war, ging vor den Priestern her, die die Posaunen bliesen; und der Haufe folgte der Lade nach und blies Posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Josua aber gebot dem Volk und sprach: Ihr sollt kein Feldgeschrei machen, noch eure Stimme horen lassen, noch ein Wort aus eurem Munde gehen bis auf den Tag, wenn ich zu euch sagen werde: Machet ein Feldgeschrei! so machet dann ein Feldgeschrei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Also ging die Lade des HERRN rings um die Stadt einmal; und kamen in das Lager und blieben drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Denn Josua pflegte sich des Morgens fruhe aufzumachen; und die Priester trugen die Lade des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'So trugen die sieben Priester die sieben Halljahrsposaunen vor der Lade des HERRN her und gingen und bliesen Posaunen; und wer gerustet war, ging vor ihnen her, und der Haufe folgte der Lade des HERRN und blies Posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Des andern Tages gingen sie auch einmal um die Stadt und kamen wieder ins Lager. Also taten sie sechs Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Am siebenten Tage aber, da die Morgenrote aufging, machten sie sich fruhe auf und gingen nach derselben Weise siebenmal um die Stadt, daß sie desselben einigen Tages siebenmal um die Stadt kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Und am siebentenmal, da die Priester die Posaunen bliesen, sprach Josua zum Volk: Machet ein Feldgeschrei, denn der HERR hat euch die Stadt gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Aber diese Stadt und alles, was drinnen ist, soil dem HERRN verbannet sein. Allein die Hure Rahab soil leben bleiben und alle, die mit ihr im Hause sind; denn sie hat die Boten verborgen, die wir aussandten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Allein hutet euch vor dem Verbanneten, daß ihr euch nicht verbannet, so ihr des Verbanneten etwas nehmet und machet das Lager Israels verbannet und bringet es in Unglück.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Aber alles Silber und Gold samt dem ehernen und eisernen Gerate soil dem HERRN geheiliget sein, daß es zu des HERRN Schatz komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Da machte das Volk ein Feldgeschrei und bliesen Posaunen. Denn als das Volk den Hall der Posaunen horete, machte es ein graft Feldgeschrei. Und die Mauern fielen um, und das Volk erstieg die Stadt, ein jeglicher stracks vor sich. Also gewannen sie die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Und verbanneten alles, was in der Stadt war, mit der Scharfe des Schwerts, beide Mann und Weib, jung und alt, Ochsen, Schafe und Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Aber Josua sprach zu den zween Mannern, die das Land verkundschaftet hatten: Gehet in das Haus der Hure und führet das Weib von dannen heraus mit allem, das sie hat, wie ihr geschworen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Da gingen die Junglinge, die Kundschafter, hinein und fuhreten Rahab heraus samt ihrem Vater und Mutter und Brudern und alles, was sie hatte, und all ihr Geschlecht; und lieften sie drauften aufter dem Lager Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Aber die Stadt verbrannten sie mit Feuer und alles; was drinnen war. Allein das Silber und Gold und eherne und eiserne Gerate taten sie zum Schatz in das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Rahab aber; die Hure, samt dem Hause ihres Vaters und alles, was sie hatte, lieft Josua leben. Und sie wohnete in Israel bis auf diesen Tag, darum daß sie die Boten verborgen hatte, die Josua zu verkundschaften gesandt hatte gen Jericho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Zu der Zeit schwur Josua und sprach: Verflucht sei der Mann vor dem HERRN; der diese Stadt Jericho aufrichtet und bauet! Wenn er ihren Grund leget, das koste ihn seinen ersten Sohn; und wenn er ihre Tore setzet, das koste ihn seinen jungsten Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Also war der HERR mit Josua, daß man von ihm sagte in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Aber die Kinder Israel vergriffen sich an dem Verbanneten; denn Achan, der Sohn Charmis, des Sohns Sabdis, des Sohns Serahs, vom Stamm Juda nahm des Verbanneten etwas. Da ergrimmete der Zorn des HERRN uber die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Da nun Josua Manner aussandte von Jericho gen Ai, die bei Beth-Aven liegt, gegen dem Morgen vor Bethel, und sprach zu ihnen: Gehet hinauf und verkundschaftet das Land; und da sie hinaufgegangen waren und Ai verkundschaftet hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'kamen sie wieder zu Josua und sprachen zu ihm: Laft nicht das ganze Volk hinaufziehen, sondern bei zwei Oder dreitausend Mann, daß sie hinaufziehen und schlagen Ai, daß nicht das ganze Volk sich daselbst bemuhe, denn ihrer ist wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Also zogen hinauf des Volks bei dreitausend Mann, und die flohen vor den Mannern zu Ai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Und die von Ai schlugen ihrer bei sechsunddreiftig Mann und jagten sie vor dem Tor bis gen Sabarim und schlugen sie den Weg herab. Da ward dem Volk das Herz verzagt und ward zu Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Josua aber zerrift seine Kleider und fiel auf sein Angesicht zur Erde vor der Lade des HERRN bis auf den Abend, samt den Altesten Israels, und warfen Staub auf ihre Haupter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Und Josua sprach: Ach, Herr, HERR, warum hast du dies Volk uber den Jordan gefuhret, daß du uns in die Hande der Amoriter gabest, uns umzubringen? 0 daß wir waren jenseit des Jordans geblieben, wie wir angefangen hatten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Ach, mein HERR, was soil ich sagen, weil Israel seinen Feinden den Rücken kehret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Wenn das die Kanaaniter und alle Einwohner des Landes horen so werden sie uns umgeben und auch unsern Namen ausrotten von der Erde. Was willst du denn bei deinem groften Namen tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Da sprach der HERR zu Josua: Stehe auf! Warum liegst du also auf deinem Angesicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hat sich versundiget, und haben meinen Bund ubergangen, den ich ihnen geboten habe; dazu haben sie des Verbanneten genommen und gestohlen und verleugnet und unter ihre Gerate geleget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Die Kinder Israel mogen nicht stehen vor ihren Feinden, sondern müssen ihren Feinden den Rücken kehren; denn sie sind im Bann, Ich werde fort nicht mit euch sein, wo ihr nicht den Bann aus euch vertilget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Stehe auf und heilige das Volk und sprich: Heiliget euch auf morgen! Denn also sagt der HERR, der Gott Israels: Es ist ein Bann unter dir, Israel; darum kannst du nicht stehen vor deinen Feinden, bis daß ihr den Bann von euch tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Und sollt euch frith herzumachen, ein Stamm nach dem andern; und welchen Stamm der HERR treffen wird, der soil sich herzumachen, ein Geschlecht nach dem andern; und welches Geschlecht der HERR treffen wird, das soil sich herzumachen, ein Haus nach dem andern; und welch Haus der HERR treffen wird, das soil sich herzumachen, ein Hauswirt nach dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Und welcher erfunden wird im Bann, den soil man mit Feuer verbrennen mit allem, das er hat, darum dafi er den Bund des HERRN uberfahren und eine Torheit in Israel begangen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Da machte sich Josua des Morgens frühe auf und brachte Israel herzu, einen Stamm nach dem andern; und ward getroffen der Stamm Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Und da erdie Geschlechter in Juda herzubrachte, ward getroffen das Geschlecht der Serahiter. Und da er das Geschlecht der Serahiter herzubrachte, einen Hauswirt nach dem andern, ward Sabdi getroffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Und da ersein Haus herzubrachte, einen Wirt nach dem andern, ward getroffen Achan, der Sohn Charmis, des Sohns Sabdis, des Sohns Serahs, aus dem Stamm Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Und Josua sprach zu Achan: Mein Sohn, gib dem HERRN, dem Gott Israels, die Ehre und gib ihm das Lob; und sage mir an, was hast du getan? und leugne mirnichts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Da antwortete Achan Josua und sprach: Wahrlich, ich habe mich versundiget an dem HERRN, dem Gott Israels; also und also habe ich getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Ich sah unter dem Rauhe einen kostlichen babylonischen Mantel und zweihundert Sekel Silbers und eine guldene Zunge, fünfzig Sekel wert am Gewichte; des gelustete mich und nahm es. Und siehe, es ist verscharret in die Erde in meiner Hütte, und das Silber drunter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Da sandte Josua Boten hin, die liefen zur Hütte; und siehe, es war verscharret in seiner Hütte, und das Silber drunter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Und sie nahmen\'s aus der Hütte und brachten\'s zu Josua und zu alien Kindern Israel und schütteten\'s vor den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Da nahm Josua und das ganze Israel mit ihm Achan, den Sohn Serahs, samt dem Silber, Mantel und guldenen Zunge, seine Sohne und Tochter, seine Ochsen und Esel und Schafe, seine Hütte und alles, was er hatte, und führeten sie hinauf ins Tal Achor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Und Josua sprach: Weil du uns betrübet hast, so betrübe dich der HERR an diesem Tage! Und das ganze Israel steinigten ihn und verbrannten sie mit Feuer. Und da sie sie gesteiniget hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'machten sie fiber sie einen grolien Steinhaufen, der bleibet bis auf diesen Tag. Also kehrete sich der HERR von dem Grimm seines Zorns. Daher heiftt derselbe Ort das Tal Achor bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Und der HERR sprach zu Josua: Fürchte dich nicht und zage nicht! Nimm mit dir alles Kriegsvolk und mache dich auf und zeuch hinauf gen Ai! Siehe da, ich habe den Konig Als samt seinem Volk in seiner Stadt und Land in deine Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Und sollst mit Ai und ihrem Konige tun, wie du mit Jericho und ihrem Konige getan hast, ohne daß ihr ihren Raub ihr Vieh unter euch teilen sollt. Aber bestelle einen Hinterhalt hinter der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Da machte sich Josua auf und alles Kriegsvolk, hinaufzuziehen gen Ai. Und Josua erwahlte dreifügtausend streitbare Manner und sandte sie aus bei der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Und gebot ihnen und sprach: Sehet zu, ihr sollt der Hinterhalt sein hinter der Stadt; machet euch aber nicht allzu feme von der Stadt und seid allesamt bereit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ich aber und alles Volk, das mit mir ist, wollen uns zu der Stadt machen. Und wenn sie uns entgegen herausfahren wie vorhin, so wollen wir vor ihnen fliehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'daß sie uns nachfolgen heraus, bis daß wir sie heraus von der Stadt reifien. Denn sie werden gedenken, wir fliehen vor ihnen wie vorhin. Und weil wir vor ihnen fliehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'sollt ihr euch aufmachen aus dem Hinterhalt und die Stadt einnehmen; denn der HERR, eurer Gott, wird sie in eure Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Wenn ihr aber die Stadt eingenommen habt, so stecket sie an mit Feuer und tut nach dem Wort des HERRN. Siehe, ich hab\'s euch geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Also sandte sie Josua hin; und sie gingen hin auf den Hinterhalt und hielten zwischen Bethel und Ai gegen abendwarts an Ai. Josua aber blieb die Nacht unter dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Und machte sich des Morgens frühe auf und ordnete das Volk und zog hinauf mit den Altesten Israels vor dem Volk her gen Ai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Und alles Kriegsvolk, das bei ihm war, zog hinauf; und traten herzu und kamen gegen die Stadt und lagerten sich gegen Mitternacht vor Ai, daß nur ein Tal war zwischen ihm und Ai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Er hatte aber bei funftausend Mann genommen und auf den Hinterhalt gestellet zwischen Bethel und Ai gegen abendwarts der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Und sie stelleten das Volk des ganzen Lagers, das gegen Mitternacht der Stadt war, daß sein Letztes reichte gegen den Abend der Stadt. Also ging Josua hin in derselbigen Nacht mitten in das Tal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Als aber der Konig zu Ai das sah, eileten sie und machten sich fruhe auf, und die Manner der Stadt heraus, Israel zu begegnen zum Streit, mit all seinem Volk an einen bestimmten Ort vor dem Gefilde. Denn er wußte nicht, daß ein Hinterhalt auf ihn war hinter der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josua aber und ganz Israel stelleten sich, als wurden sie geschlagen vor ihnen, und flohen auf dem Wege zur Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Da schrie das ganze Volk in der Stadt, daß man ihnen sollte nachjagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Und siejagten auch Josua nach und rissen sich von der Stadt heraus, dafi nicht ein Mann uberblieb in Ai und Bethel, der nicht ausgezogen ware, Israel nachzujagen; und lielien die Stadt often stehen, daß sie Israel nachjagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Da sprach der HERR zu Josua: Recke aus die Lanze in deiner Hand gegen Ai, denn ich will sie in deine Hand geben. Und da Josua die Lanze in seiner Hand gegen die Stadt ausreckte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'da brach der Hinterhalt auf eilend aus seinem Ort, und liefen, nachdem er seine Hand ausstreckte, und kamen in die Stadt und gewannen sie; und eileten und steckten sie mit Feuer an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Und die Manner von Ai wandten sich und sahen hinter sich und sahen den Rauch der Stadt aufgehen gen Himmel und hatten nicht Raum zu fliehen, weder hin noch her. Und das Volk, das zur Wuste floh, kehrete sich urn, ihnen nachzujagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Denn da Josua und das ganze Israel sah, daü der Hinterhalt die Stadt gewonnen hatte, weil der Stadt Rauch aufging, kehreten sie wieder urn und schlugen die Manner von Ai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Und die in der Stadt kamen auch heraus ihnen entgegen, dad sie mitten unter Israel kamen von dorther und von hieher; und schlugen sie, bis dad niemand unter ihnen uberblieb noch entrinnen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Und griffen den Konig zu Ai lebendig und brachten ihn zu Josua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Und da Israel alle Einwohner zu Ai hatte erwurget auf dem Felde und in der Wuste, die ihnen nachgejagt hatten, und fielen alle durch die Scharfe des Schwerts, bis dad sie alle umkamen, da kehrete sich ganz Israel zu Ai und schlugen sie mit der Scharfe des Schwerts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Und alle, die des Tages fielen, beide Mann und Weiber, der waren zwolftausend, alles Leute von Ai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josua aber zog nicht wieder ab seine Hand, damit er die Lanze ausreckte, bis dad verbannet wurden alle Einwohner Ais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Ohne das Vieh und den Raub der Stadt teilete Israel aus unter sich nach dem Wort des HERRN, das er Josua geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Und Josua brannte Ai aus und machte einen Haufen daraus ewiglich, der noch heute da liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Und lied den Konig zu Ai an einen Baum hangen bis an den Abend. Da aber die Sonne war untergegangen, gebot er, dad man seinen Leichnam vom Baum tate; und warfen ihn unter der Stadt Tor und machten einen groden Steinhaufen auf ihn, der bis auf diesen Tag da ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Da bauete Josua dem HERRN, dem Gott Israels, einen Altar auf dem Berge Ebal');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, '(wie Mose, der Knecht des HERRN, geboten hatte den Kindern Israel, als geschrieben stehet im Gesetzbuch Moses, einen Altar von ganzen Steinen, die mit keinem Eisen behauen waren) und opferte dem HERRN drauf Brandopfer und Dankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Und schrieb daselbst auf die Steine das andere Gesetz, das Mose den Kindern Israel vorgeschrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Und das ganze Israel mit seinen Altesten und Amtleuten und Richtern stunden zu beiden Seiten der Lade gegen den Priestern aus Levi, die die Lade des Bundes des HERRN trugen, die Fremdlinge sowohl als die Einheimischen, eine Halfte neben dem Berge Grisim und die andere Halfte neben dem Berge Ebal, wie Mose, der Knecht des HERRN, vorhin geboten hatte, zu segnen das Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Danach lieft er ausrufen alle Worte des Gesetzes vom Segen und Fluch, wie es geschrieben stehet im Gesetzbuch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Es war kein Wort, das Mose geboten hatte, das Josua nicht hatte lassen ausrufen vor der ganzen Gemeine Israel und vor den Weibern und Kindern und Fremdlingen, die unter ihnen wandelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Da nun das horeten alle Konige, die jenseit des Jordans waren auf den Gebirgen und in den Grunden und an alien Anfurten des grolien Meers, auch die neben dem Berge Libanon waren, namlich die Hethiter, Amoriter, Kanaaniter, Pheresiter, Heviter und Jebusiter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'sammelten sie sich eintrachtiglich zuhauf, dafi sie wider Josua und wider Israel stritten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Aber die Burger zu Gibeon, da sie horeten, was Josua mit Jericho und Ai getan hatte, erdachten sie eine List;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'gingen hin und schickten eine Botschaft und nahmen alte Sacke auf ihre Esel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'und alte zerrissene, geflickte Weinschlauche und alte geflickte Schuhe an ihre Fulie und zogen alte Kleider an, und altes Brot, das sie mit sich nahmen, war hart und schimmlig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Und gingen zu Josua ins Lager gen Gilgal und sprachen zu ihm und zum ganzen Israel: Wir kommen aus fernen Landen, so machet nun einen Bund mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Da sprach das ganze Israel zu dem Heviter: Vielleicht mochtest du unter uns wohnend werden; wie konnte ich dann einen Bund mit dir machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Sie aber sprachen zu Josua: Wir sind deine Knechte. Josua sprach zu ihnen: Wer seid ihr und von wannen kommt ihr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Sie sprachen: Deine Knechte sind aus sehr fernen Landen kommen um des Namens willen des HERRN, deines Gottes; denn wir haben sein Gerucht gehoret und alles, was er in Agypten getan hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'und alles, was erden zweien Konigen der Amoriter jenseit des Jordans getan hat, Sihon, dem Konige zu Hesbon, und Og, dem Konige zu Basan, der zu Astharoth wohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Darum sprachen unsere Altesten und alle Einwohner unsers Landes: Nehmet Speise mit euch auf die Reise und gehet hin ihnen entgegen und sprechet zu ihnen: Wir sind eure Knechte. So machet nun einen Bund mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Dies unser Brot, das wir aus unsern Hausern zu unserer Speise nahmen, war noch frisch, da wir auszogen zu euch; nun aber, siehe, es ist hart und schimmlig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'und diese Weinschlauche fulleten wir neu, und siehe, sie sind zerrissen; und diese unsere Kleider und Schuhe sind alt worden über der sehr langen Reise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Da nahmen die Hauptleute ihre Speise an und fragten den Mund des HERRN nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Und Josua machte Frieden mit ihnen und richtete einen Bund mit ihnen auf, daß sie leben bleiben sollten. Und die Obersten der Gemeine schwuren ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Aber uber drei Tage, nachdem sie mit ihnen einen Bund gemacht hatten, kam es vorsie, daß jene nahe bei ihnen waren und würden unter ihnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Denn da die Kinder Israel fortzogen, kamen sie des dritten Tages zu ihren Stadten, die hiefien Gibeon, Kaphira, Beeroth und Kiriath-Jearim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Und schlugen sie nicht, darum daß ihnen die Obersten der Gemeine geschworen hatten bei dem HERRN, dem Gott Israels. Da aber die ganze Gemeine wider die Obersten murrete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'sprachen alle Obersten der ganzen Gemeine: Wir haben ihnen geschworen bei dem HERRN, dem Gott Israels; darum konnen wir sie nicht antasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Aber das wollen wir tun: Lasset sie leben, daß nicht ein Zorn uber uns komme um des Eides willen, den wir ihnen getan haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Und die Obersten sprachen zu ihnen: Lasset sie leben, daß sie Holzhauer und Wassertrager seien der ganzen Gemeine, wie ihnen die Obersten gesagt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Da rief ihnen Josua und redete mit ihnen und sprach: Warum habt ihr uns betrogen und gesagt, ihr seid sehr feme von uns, so ihr doch unter uns wohnet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Darum sollt ihr verflucht sein, daß unter euch nicht aufhoren Knechte, die Holz hauen und Wasser tragen zum Hause meines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Sie antworteten Josua und sprachen: Es ist deinen Knechten angesagt, daß der HERR, dein Gott, Mose, seinem Knechte, geboten habe, daß er euch das ganze Land geben und voreuch her alle Einwohner des Landes vertilgen wolle. Da furchteten wir unsers Lebens vor euch sehr und haben solches getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Nun aber, siehe, wir sind in deinen Handen; was dich gut und recht dunket, uns zu tun, das tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Und er tat ihnen also und errettete sie von der Kinder Israel Hand, daß sie sie nicht erwurgeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Also machte sie Josua desselben Tages zu Holzhauern und Wassertragern der Gemeine und zum Altar des HERRN bis auf diesen Tag an dem Ort, den er erwahlen wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Da aber Adoni-Zedek, der Konig zu Jerusalem, horete, daß Josua Ai gewonnen und sie verbannet hatte und Ai samt ihrem Konige getan hatte, gleichwie er Jericho und ihrem Konige getan hatte, und daß die zu Gibeon Frieden mit Israel gemacht hatten und unter sie kommen waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'furchteten sie sich sehr (denn Gibeon war eine grolie Stadt, wie eine konigliche Stadt, und grolier denn Ai, und alle ihr Burger streitbar).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Und er sandte zu Hoham, dem Konige zu Hebron, und zu Piream, dem Konige zu Jarmuth, und zu Japhia, dem Konige zu Lachis, und zu Debir, dem Konige zu Eglon, und lieli ihnen sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Kommt herauf zu mir und helfet mir, daß wir Gibeon schlagen; denn sie hat mit Josua und den Kindern Israel Frieden gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Da kamen zuhauf und zogen hinauf die funf Konige der Amoriter: der Konig zu Jerusalem, der Konig zu Hebron, der Konig zu Jarmuth, der Konig zu Lachis, der Konig zu Eglon, mit all ihrem Heerlager und belegten Gibeon und stritten wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Aber die zu Gibeon sandten zu Josua ins Lager gen Gilgal und lielien ihm sagen: Zeuch deine Hand nicht ab von deinen Knechten! Komm zu uns herauf eilend, rette und hilf uns; denn es haben sich wider uns zusammengeschlagen alle Konige der Amoriter, die auf dem Gebirge wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Josua zog hinauf von Gilgal, und alles Kriegsvolk mit ihm und alle streitbaren Manner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Und der HERR sprach zu Josua: Furchte dich nicht vor ihnen, denn ich habe sie in deine Hande gegeben; niemand unter ihnen wird vor dir stehen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Also kam Josua plotzlich uber sie, denn die ganze Nachtzog er herauf von Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Aber der HERR schreckte sie vor Israel, daß sie eine grolie Schlacht schlugen zu Gibeon, und jagten ihnen nach den Weg hinan zu Beth-Horon und schlugen sie bis gen Aseka und Makeda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Und da sie vor Israel flohen den Weg herab zu Beth-Horon, lieli der HERR einen grolien Hagel vom Himmel auf sie fallen bis gen Aseka, daß sie starben. Und viel mehr starben ihrer von dem Hagel, denn die Kinder Israel mit dem Schwert erwurgeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Da redete Josua mit dem HERRN des Tages, da der HERR die Amoriter ubergab vor den Kindern Israel, und sprach vor gegenwartigem Israel: Sonne, stehe still zu Gibeon, und Mond, im Tal Ajalon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Da stund die Sonne und der Mond stille, bis daß sich das Volk an seinen Feinden rachete. 1st dies nicht geschrieben im Buch des Frommen? Also stund die Sonne mitten am Himmel und verzog unterzugehen einen ganzen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Und war kein Tag diesem gleich, weder zuvor noch danach, da der HERR der Stimme eines Mannes gehorchte; denn der HERR stritt fur Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Josua aber zog wieder ins Lager gen Gilgal und das ganze Israel mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Aber die fünf Konige waren geflohen und hatten sich versteckt in die Hohle zu Makeda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Da ward Josua angesagt: Wir haben die fünf Konige gefunden, verborgen in der Hohle zu Makeda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Josua sprach: So walzet grofte Steine vor das Loch der Hohle und bestellet Manner davor, die ihrer huten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ihr aber stehet nicht stille, sondern jaget euren Feinden nach und schlaget ihre Hintersten; und lasset sie nicht in ihre Stadte kommen, denn der HERR, euer Gott, hat sie in eure Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Und da Josua und die Kinder Israel vollendet hatten diese sehr grofie Schlacht an ihnen und gar geschlagen: was uberblieb von ihnen, das kam in die festen Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Also kam alles Volk wieder ins Lager zu Josua gen Makeda mit Frieden, und durfte niemand vor den Kindern Israel seine Zunge regen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Josua aber sprach: Machet auf das Loch der Hohle und bringet hervor die fünf Konige zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Sie taten also und brachten die fünf Konige zu ihm aus der Hohle: den Konig zu Jerusalem, den Konig zu Hebron, den Konig zu Jarmuth, den Konig zu Lachis, den Konig zu Eglon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Da aber die fünf Konige zu ihm herausgebracht waren, rief Josua dem ganzen Israel und sprach zu den Obersten des Kriegsvolks, die mit ihm zogen: Kommt herzu und tretet diesen Konigen mit Füüen auf die Halse! Und sie kamen herzu und traten mit Füßen auf ihre Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Und Josua sprach zu ihnen: Fürchtet euch nicht und erschrecket nicht, seid getrost und unverzagt; denn also wird der HERR alien euren Feinden tun, wider die ihr streitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Und Josua schlug sie danach und totete sie und hing sie auf fünf Baume; und sie hingen an den Baumen bis zum Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Da aber die Sonne war untergegangen, gebot er, daß man sie von den Baumen nahme und würfe sie in die Hohle, darinnen sie sich verkrochen hatten; und legten große Steine vor der Hohle Loch. Die sind noch da auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Desselben Tages gewann Josua auch Makeda und schlug sie mit der Scharfe des Schwerts, dazu ihren Konig, und verbannete sie und alle Seelen, die drinnen waren, und liefi niemand überbleiben; und tat dem Konige zu Makeda, wie er dem Konige zu Jericho getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Da zog Josua und das ganze Israel mit ihm von Makeda gen Libna und stritt wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Und der HERR gab dieselbige auch in die Hand Israels mit ihrem Konige, und er schlug sie mit der Scharfe des Schwerts und alle Seelen, die drinnen waren, und liefi niemand drinnen uberbleiben; und tat ihrem Konige, wie erdem Konige zu Jericho getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Danach zog Josua und das ganze Israel mit ihm von Libna gen Lachis und belegten und bestritten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Und der HERR gab Lachis auch in die Hande Israels, daß sie sie des andern Tages gewannen, und schlugen sie mit der Scharfe des Schwerts und aile Seelen, die drinnen waren, allerdinge wie er Libna getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Zu derselbigen Zeit zog Horam, der Konig zu Geser, hinauf, Lachis zu helfen; aber Josua schlug ihn mit all seinem Volk, bis daß niemand drinnen uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Und Josua zog von Lachis samt dem ganzen Israel gen Eglon und belegte und bestritt sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Und gewann sie desselbigen Tages und schlug sie mit der Scharfe des Schwerts; und verbannete alle Seelen, die drinnen waren, desselbigen Tages, allerdinge wie er Lachis getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Danach zog Josua hinauf samt dem ganzen Israel von Eglon gen Hebron und bestritt sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Und gewann sie und schlug sie mit der Scharfe des Schwerts und ihren Konig mit alien ihren Stadten und alle Seelen, die drinnen waren; und ließ niemand uberbleiben, allerdinge wie er Eglon getan hatte, und verbannete sie und alle Seelen, die drinnen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Da kehrete Josua wieder urn samt dem ganzen Israel gen Debir und bestritt sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'und gewann sie samt ihrem Konige und alle ihre Stadte; und schlugen sie mit der Scharfe des Schwerts und verbanneten alle Seelen, die drinnen waren, und liefi niemand uberbleiben. Wie er Hebron getan hatte, so tat er auch Debir und ihrem Konige, und wie er Libna und ihrem Konige getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Also schlug Josua alles Land auf dem Gebirge und gegen Mittag und in den Grunden und an den Bachen mit alien ihren Konigen; und ließ niemand uberbleiben und verbannete alles, was Odem hatte,, wie der HERR, der Gott Israels, geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Und schlug sie von Kades-Barnea an bis gen Gasa und das ganze Land Gosen bis gen Gibeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Und gewann alle diese Konige mit ihrem Lande auf einmal; denn der HERR, der Gott Israels, stritt fur Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Und Josua zog wieder ins Lager gen Gilgal mit dem ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Da aber Jabin, der Konig zu Hazor, solches horete, sandte er zu Jobab, dem Konige zu Madon, und zum Konige zu Simron und zum Konige zu Achsaph');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'und zu den Konigen, die gegen Mitternacht auf dem Gebirge und auf dem Gefilde gegen Mittag Cinnereth und in den Grunden und in Naphoth-Dor am Meerwohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Die Kanaaniter gegen dem Morgen und Abend, die Amoriter, Hethiter, Pheresiter und Jebusiter auf dem Gebirge, dazu die Heviter unten am Berge Hermon, im Lande Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Diese zogen aus mit all ihrem Heer, ein groß Volk, so viel als des Sandes am Meer, und sehr viele Rosse und Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Alle diese Konige versammelten sich und kamen und lagerten sich zuhauf an das Wasser Merom, zu streiten mit Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Und der HERR sprach zu Josua: Furchte dich nicht vor ihnen, denn morgen urn diese Zeit will ich sie alle erschlagen geben vor den Kindern Israel; ihre Rosse sollst du verlahmen und ihre Wagen mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Und Josua kam plotzlich uber sie, und alles Kriegsvolk mit ihm, am Wasser Merom und fiberfielen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Und der HERR gab sie in die Hande Israels; und schlugen sie und jagten sie bis gen großen Zidon und bis an die warmen Wasser und bis an die Breite zu Mizpe gegen dem Morgen; und schlugen sie, bis daß niemand unter ihnen uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Da tat ihnen Josua, wie der HERR ihm gesagt hatte, und verlahmte ihre Rosse und verbrannte ihre Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Und kehrete urn zu derselben Zeit und gewann Hazor und schlug ihren Konig mit dem Schwert (denn Hazor war vorhin die Hauptstadt aller dieser Konigreiche).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Und schlugen alle Seelen; die drinnen waren, mit der Scharfe des Schwerts und verbanneten sie; und ließ nichts uberbleiben, das den Odem hatte; und verbrannte Hazor mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Dazu alle Stadte dieser Konige gewann Josua mit ihren Konigen; und schlug sie mit der Scharfe des Schwerts und verbannete sie, wie Mose, der Knecht des HERRN, geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Doch verbrannten die Kinder Israel keine Stadte, die auf Hfigeln stunden, sondern Hazor allein verbrannte Josua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Und alien Raub dieser Stadte und das Vieh teileten die Kinder Israel unter sich; aber alle Menschen schlugen sie mit der Scharfe des Schwerts, bis sie die vertilgeten, und ließen nichts uberbleiben, das den Odem hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Wie der HERR Mose, seinem Knechte, und Mose Josua geboten hatte, so tat Josua, daß nichts fehlete an allem, das der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Also nahm Josua all dies Land ein auf dem Gebirge und alles, was gegen Mittag liegt, und alles Land Gosen und die Grfinde und Felder und das Gebirge Israel mit seinen Grunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'von dem Gebirge an, das das Land hinauf gen Seir scheidet, bis gen Baal-Gad, in der Breite des Berges Libanon, unten am Berge Hermon. Alle ihre Konige gewann er und schlug sie und totete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Er stritt aber eine lange Zeit mit diesen Konigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Es war aber keine Stadt, die sich mit Frieden ergabe den Kindern Israel, ausgenommen die Heviter, die zu Gibeon wohneten, sondern sie gewannen sie aile mit Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Und das geschah also von dem HERRN, daß ihr Herz verstockt würde, mit Streit zu begegnen den Kindern Israel, auf daß sie verbannet würden, und ihnen keine Gnade widerfuhre, sondern vertilget wurden, wie der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Zu der Zeit kam Josua und rottete aus die Enakim von dem Gebirge, von Hebron, von Debir, von Anab, von allem Gebirge Juda und von allem Gebirge Israel, und verbannete sie mit ihren Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Und ließ keine Enakim uberbleiben im Lande der Kinder Israel, ohne zu Gasa, zu Gath, zu Asdod, da blieben ihrer übrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Also nahm Josua alles Land ein, allerdinge wie der HERR zu Mose geredet hatte, und gab sie Israel zum Erbe, einem jeglichen Stamm sein Teil. Und das Land horete auf zu kriegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Dies sind die Konige des Landes, die die Kinder Israel schlugen, und nahmen ihr Land ein jenseit des Jordans gegen der Sonnen Aufgang, von dem Wasser bei Arnon an bis an den Berg Hermon und das ganze Gefilde gegen dem Morgen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, der Konig der Amoriter, derzu Hesbon wohnete und herrschete von Aroer an, die am Ufer liegt des Wassers bei Arnon, und mitten im Wasser, und fiber das halbe Gilead bis an das Wasser Jabbok, der die Grenze ist der Kinder Ammon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'und fiber das Gefilde bis an das Meer Cinneroth gegen Morgen und bis an das Meer im Gefilde, namlich das Salzmeer gegen Morgen, des Weges gen Beth-Jesimoth, und von Mittag unten an den Bachen des Gebirges Pisga.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Dazu die Grenze des Konigs Og zu Basan, der noch von den Riesen ubrig war und wohnete zu Astharoth und Edrei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'und herrschete fiber den Berg Hermon, fiber Salcha und fiber ganz Basan bis an die Grenze Gesuri und Maachathi, und des halben Gilead, welches die Grenze war Sihons, des Konigs zu Hesbon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose, der Knecht des HERRN, und die Kinder Israel schlugen sie. Und Mose, der Knecht des HERRN, gab sie einzunehmen den Rubenitern, Gaditern und dem halben Stamm Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Dies sind die Konige des Landes, die Josua schlug und die Kinder Israel diesseit des Jordans gegen dem Abend, von Baal-Gad an auf der Breite des Berges Libanon bis an den Berg, der das Land hinauf gen Seir scheidet, und das Josua den Stammen Israels einzunehmen gab, einem jeglichen sein Teil,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'was auf den Gebirgen, Grunden, Gefilden, an Bachen, in der Wuste und gegen Mittag war: die Hethiter, Amoriter, Kanaaniter, Pheresiter, Heviter und Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Der Konig zu Jericho, der Konig zu Ai, die zur Seite an Bethel liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'der Konig zu Jerusalem, der Konig zu Hebron,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'der Konig zu Jarmuth, der Konig zu Lachis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'der Konig zu Eglon, der Konig zu Geser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'der Konig zu Debir, der Konig zu Geder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'der Konig zu Horma, der Konig zu Arad,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'der Konig zu Libna, der Konig zu Adullam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'der Konig zu Makeda, der Konig zu Bethel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'der Konig zu Tapuah, der Konig zu Hepher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'der Konig zu Aphek, der Konig zu Lasaron,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'der Konig zu Madon, der Konig zu Hazor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'der Konig zu Simron-Meron, der Konig zu Achsaph,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'der Konig zu Thaenach, der Konig zu Megiddo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'der Konig zu Kedes, der Konig zu Jakneam am Karmel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'der Konig zu Naphoth-Dor, der Konig der Heiden zu Gilgal,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'der Konig zu Thirza. Das sind einunddreißig Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Da nun Josua alt war und wohl betaget, sprach der HERR zu ihm: Du bist alt worden und wohl betaget, und des Landes ist noch fast viel ubrig einzunehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'namlich das ganze Galilaa der Philister und ganz Gessuri,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'vom Sihor an, dervor Agypten fleußt, bis an die Grenze Ekron gegen Mitternacht, die den Kanaanitern zugerechnet wird, funf Herren der Philister: namlich der Gasiter, Asdoditer, der Askloniter, der Gethiter, der Ekroniter und die Aviter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Von Mittag an aber ist das ganze Land der Kanaaniter und Meara der Zidonier bis gen Aphek, bis an die Grenze der Amoriter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'dazu das Land der Gibliter und der ganze Libanon gegen der Sonnen Aufgang, von Baal-Gad an unter dem Berge Hermon, bis man kommt gen Hamath:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'alle, die auf dem Gebirge wohnen, vom Libanon an bis an die warmen Wasser, und alle Zidonier. Ich will sie vertreiben vor den Kindern Israel. Lose nur drum, sie auszuteilen unter Israel, wie ich dir geboten habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'So teile nun dies Land zum Erbe unter die neun Stamme und unter den halben Stamm Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Denn die Rubeniter und Gaditer haben mit dem andern halben Manasse ihr Erbteil empfangen, das ihnen Mose gab jenseit des Jordans gegen dem Aufgang, wie ihnen dasselbe Mose, der Knecht des HERRN, gegeben hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'von Aroer an, die am Ufer des Wassers bei Arnon liegt, und von der Stadt mitten im Wasser und alle Gegend Medba bis gen Dibon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'und alle Stadte Sihons, des Konigs der Amoriter, der zu Hesbon saß, bis an die Grenze der Kinder Ammon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'dazu Gilead und die Grenze an Gessuri und Maachathi und den ganzen Berg Hermon und das ganze Basan bis gen Salcha;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'das ganze Reich Ogs zu Basan, derzu Astharoth und Edrei saß, welcher noch ein ubriger war von den Riesen. Mose aber schlug sie und vertrieb sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Die Kinder Israel vertrieben aber die zu Gessur und zu Maachath nicht, sondern es wohneten beide Gessur und Maachath unter den Kindern Israel bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Aber dem Stamm der Leviten gab er kein Erbteil; denn das Opfer des HERRN, des Gottes Israels, ist ihr Erbteil, wie er ihnen geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Also gab Mose dem Stamm der Kinder Ruben nach ihren Geschlechtern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'daß ihre Grenzen waren von Aroer, die am Ufer des Wassers bei Arnon liegt, und die Stadt mitten im Wasser mit allem ebenen Felde bis gen Medba;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon und alle ihre Stadte, die im ebenen Felde liegen; Dibon, Bamoth-Baal und Beth-Baal- Meon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahza, Kedemoth, Mephaath,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kiriathaim, Sibma, Zereth-Sahar auf dem Gebirge im Tal,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Beth-Peor, die Bache am Pisga und Beth- Jesimoth');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'und alle Stadte auf der Ebene und das ganze Reich Sihons, des Konigs der Amoriter, der zu Hesbon saß, den Mose schlug, samt den Fursten Midians, Evi, Rekem, Zur, Hur und Reba, die Gewaltigen des Konigs Sihon, die im Lande wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Dazu Bileam, den Sohn Beors, den Weissager, erwürgeten die Kinder Israel mit dem Schwert samt den Erschlagenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Und die Grenze der Kinder Ruben war der Jordan Das ist das Erbteil der Kinder Ruben unter ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Dem Stamm der Kinder Gad unter ihren Geschlechtern gab Mose,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'daß ihre Grenzen waren Jaeser und alle Stadte in Gilead und das halbe Land der Kinder Ammon bis gen Aroer, welche liegt vor Rabba;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'und von Hesbon bis gen Ramath-Mizpe und Betonim und von Mahanaim bis an die Grenze Debirs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'im Tal aber Beth-Haram, Beth-Nimra, Suchoth und Zaphon, die übrig war von dem Reich Sihons, des Konigs zu Hesbon, daß der Jordan die Grenze war, bis ans Ende des Meers Cinnereth, diesseit des Jordans gegen dem Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Das ist das Erbteil der Kinder Gad in ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Dem halben Stamm der Kinder Manasse nach ihren Geschlechtern gab Mose,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'daü ihre Grenzen waren von Mahanaim an, das ganze Basan, das ganze Reich Ogs, des Konigs zu Basan, und alle Flecken Jairs, die in Basan üegen, namlich sechzig Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Und das halbe Gilead, Astharoth, Edrei, die Stadte des Konigreichs Ogs zu Basan, gab er den Kindern Machirs, des Sohns Manasses, das ist, der Halfte der Kinder Machirs, nach ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Das ist\'s, das Mose ausgeteilet hat in dem Gefilde Moab jenseit des Jordans vor Jericho gegen dem Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Aber dem Stamm Levi gab Mose kein Erbteil; denn der HERR, der Gott Israels, ist ihr Erbteil, wie er ihnen geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Dies ist aber, das die Kinder Israel eingenommen haben im Lande Kanaan, das unter sie ausgeteilet haben der Priester Eleasar und Josua, der Sohn Nuns, und die obersten Vater unter den Stammen der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Sie teileten es aber durchs Los unter sie, wie der HERR durch Mose geboten hatte, zu geben den zehnthalb Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Denn den zweien und dem halben Stamm hatte Mose Erbteil gegeben jenseit des Jordans. Den Leviten aber hatte er kein Erbteil unter ihnen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Denn der Kinder Josephs wurden zween Stamme, Manasse und Ephraim; darum gaben sie den Leviten kein Teil im Lande, sondern Stadte, drinnen zu wohnen, und Vorstadte fur ihr Vieh und Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Wie der HERR Mose geboten hatte, so taten die Kinder Israel und teileten das Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Da traten herzu die Kinder Juda zu Josua zu Gilgal, und Kaleb, der Sohn Jephunnes, der Kenisiter, sprach zu ihm: Du weifiest, was der HERR zu Mose, dem Mann Gottes, sagte von meinet und deinetwegen in Kades-Barnea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Ich war vierzig Jahre alt, da mich Mose, der Knecht des HERRN, aussandte von Kades-Barnea, das Land zu verkundschaften, und ich ihm wieder sagte nach meinem Gewissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Aber meine Bruder, die mit mir hinaufgegangen waren, machten dem Volk das Herz verzagt; ich aber folgte dem HERRN, meinem Gott, treulich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Da schwur Mose desselben Tages und sprach: Das Land, darauf du mit deinem Fuß getreten hast, soil dein und deiner Kinder Erbteil sein ewiglich, darum daß du dem HERRN, meinem Gott, treulich gefolget hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Und nun siehe, der HERR hat mich leben lassen, wie er geredet hat. Es sind nun funfundvierzig Jahre, daß der HERR solches zu Moses sagte, die Israel in der Wüste gewandelt hat. Und nun siehe, ich bin heute funfundachtzig Jahre alt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'und bin noch heutigestages so stark, als ich war des Tages, da mich Mose aussandte; wie meine Kraft war dazumal, also ist sie auch jetzt, zu streiten und aus- und einzugehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'So gib mir nun dies Gebirge, davon der HERR geredet hat an jenem Tage; denn du hast es gehoret am selben Tage. Denn es wohnen die Enakim droben, und sind groüe und feste Stadte: ob der HERR mit mir sein wollte, daü ich sie vertriebe, wie der HERR geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Da segnete ihn Josua und gab also Hebron Kaleb, dem Sohn Jephunnes, zum Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Daherward Hebron Kalebs, des Sohns Jephunnes, des Kenisiters, Erbteil bis auf diesen Tag, darum dafi erdem HERRN, dem Gott Israels, treulich gefolget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Aber Hebron hieü vorzeiten Kiriath-Arba, der ein grolier Mensch war unter den Enakim. Und das Land hatte aufgehoret mit Kriegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Das Los des Stamms der Kinder Juda unter ihren Geschlechtern war die Grenze Edom an der Wuste Zin, die gegen Mittag stoliet an der Ecke der Mittagslander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'daü ihre Mittagsgrenzen waren von der Ecke an dem Salzmeer, das ist, von der Zunge, die gegen mittagwarts gehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'und kommt hinaus von dannen hinauf zu Akrabbim und gehet durch Zin; und gehet aber hinauf von mittagwarts gegen Kades-Barnea; und gehet durch Hezron und gehet hinauf gen Adar und lenket sich urn Karkaa;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'und gehet durch Azmon und kommt hinaus an den Bach Agyptens, daß das Ende der Grenze das Meer wird. Das sei eure Grenze gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Aber die Morgengrenze ist von dem Salzmeer an bis an des Jordans Ende. Die Grenze gegen Mitternacht ist von der Zunge des Meers, die am Ort des Jordans ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'und gehet herauf gen Beth-Hagla und zeucht sich von mitternachtwarts gen Beth-Araba und kommt herauf zum Stein Bohen, des Sohns Rubens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'und gehet herauf gen Debir, vom Tal Achorund von dem Mitternachtsort, der gegen Gilgal siehet, welche liegt gegenüber zu Adumim hinauf, die von mittagwarts am Wasser liegt. Danach gehet sie zu dem Wasser En-Semes und kommt hinaus zum Brunnen Rogel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Danach gehet sie herauf zum Tal des Sohns Hinnoms an der Seite her des Jebusiters, der von mittagwarts wohnet, das ist Jerusalem; und kommt herauf auf die Spitze des Berges, der vor dem Tal Hinnom liegt von abendwarts, welcher stofiet an die Ecke des Tals Raphaim gegen Mitternacht zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Danach kommt sie von desselben Berges Spitze zu dem Wasserbrunnen Nephthoah und kommt heraus zu den Stadten des Gebirges Ephron und neiget sich gen Baala, das ist Kiriath-Jearim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'und lenket sich herum von Baala gegen Abend zum Gebirge Seir und gehet an der Seite her des Gebirges Jearim von mitternachtwarts, das ist Chessalon, und kommt herab gen Beth-Semes und gehet durch Thimna;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'und bricht heraus an der Seite Ekron her gegen mitternachtwarts und zeucht sich gen Sichron; und gehet uber den Berg Baala und kommt heraus gen Jabneel, dafi ihr Letztes ist das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Die Grenze aber gegen Abend ist das grofie Meer. Das ist die Grenze der Kinder Juda umher in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kaleb aber, dem Sohn Jephunnes, wurde sein Teil gegeben unter den Kindern Juda, nach dem der HERR Josua befahl, namlich die Kiriath-Arba, des Vaters Enaks, das ist Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Und Kaleb vertrieb von dannen die drei Sohne Enaks: Sesai, Ahiman und Thalmai, geboren von Enak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Und zog von dannen hinauf, zu den Einwohnern Debirs. Debir aber hieü vor Zeiten Kiriath- Sepher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Und Kaleb sprach: Wer Kiriath-Sepher schlagt und gewinnet, dem will ich meine Tochter Achsa zum Weibe geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Da gewann sie Athniel, der Sohn Kenas, des Bruders Kalebs; und er gab ihm seine Tochter Achsa zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Und es begab sich, da sie einzog, ward ihr geraten, einen Acker zu fordern von ihrem Vater; und sie fiel vom Esel. Da sprach Kaleb zu ihr: Was ist dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Sie sprach: Gib mir einen Segen; denn du hast mirein Mittagsland gegeben, gib mir auch Wasserquellen. Da gab er ihr Quellen oben und unten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Dies ist das Erbteil des Stamms der Kinder Juda unter ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Und die Stadte des Stamms der Kinder Juda von einer Ecke zu der andern an der Grenze der Edomiter gegen Mittag waren diese: Kabzeel, Eder, Jagur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Ad-Ada,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hazor, Ithnan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hazor-Hadata, Kirioth-Hezron, das ist Hazor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Serna, Molada,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hazar-Gadda, Hesmon, Beth-Palet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hazar-Sual, Beer-Seba, Bisjoth-Ja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijim, Azem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'El-Tholad, Chesil, Horma,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziklag, Madmanna, Sansanna,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaoth, Silhim, Ain, Rimon. Das sind neunundzwanzig Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In den Grunden aber war Esthaol, Zarea, Asna,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Sanoah, En-Gannim, Thapuah, Enam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth, Adullam, Socho, Aseka,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Adithaim, Gedera, Gederothaim. Das sind vierzehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, Migdal-Gad,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Mizpe, Jakthiel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachis, Bazekath, Eglon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Chabon, Lahmam, Cithlis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederoth, Beth-Dagon, Naema, Makeda. Das sind sechzehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Ether, Asan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jephthah, Asna, Nezib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Achsib, Maresa. Das sind neun Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron mit ihren Tochtern und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Von Ekron und ans Meer alles, was an Asdod langet, und ihre Dorfer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod mit ihren Tochtern und Dorfern, Gasa mit ihren Tochtern und Dorfern bis an das Wasser Agyptens. Und das grofie Meer ist seine Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Auf dem Gebirge aber war Samir, Jattir, Socho,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kiriath-Sanna, das ist Debir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Esthemo, Anim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon, Gilo. Das sind elf Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esean,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, Beth-Thapuah, Apheka,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kiriath-Arba, das ist Hebron, Zior. Das sind neun Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Siph, Juta,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jesreel, Jakdeam, Sanoah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea, Thimna. Das sind zehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beth-Zur, Gedor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarath, Beth-Anoth, Elthekon. Das sind sechs Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kiriath-Baal, das ist Kiriath-Jearim, Harabba; zwo Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In der Wuste aber war Beth-Araba, Middin, Sechacha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan und die Salzstadt und Engeddi. Das sind sechs Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Die Jebusiter aber wohneten zu Jerusalem, und die Kinder Juda konnten sie nicht vertreiben. Also blieben die Jebusiter mit den Kindern Juda zu Jerusalem bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Und das Los fiel den Kindem Josephs vom Jordan gegen Jericho bis zum Wasser bei Jericho, von aufgangwarts, und die Wüste, die heraufgehet von Jericho durch das Gebirge Bethel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'und kommt von Bethel heraus gen Lus und gehet durch die Grenze Archi-Atharoths;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'und zeucht sich hernieder gegen abendwarts zu der Grenze Japhletis bis an die Grenze des niedern Beth-Horon und bis gen Gaser; und das Ende ist am Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Das haben zum Erbteil genommen die Kinder Josephs, Manasse und Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Die Grenze der Kinder Ephraims unter ihren Geschlechtern, ihres Erbteils von aufgangwarts, war Atharoth-Adar bis gen obern Beth-Horon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'und gehet aus gegen Abend bei Michmethath, die gegen Mitternacht liegt; daselbst lenket sie sich herum gegen den Aufgang der Stadt Thaenath-Silo und gehet da durch von aufgangwarts gen Janoha;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'und kommt herab von Janoha gen Atharoth und Naaratha und stoßt an Jericho und gehet aus am Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Von Thapuah gehet sie gegen abendwarts gen Nahal-Kana; und ihr Ende ist am Meer. Das ist das Erbteil des Stamms der Kinder Ephraims unter ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Und alle Grenzstadte samt ihren Dorfern der Kinder Ephraims waren gemenget unter dem Erbteil der Kinder Manasses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Und sie vertrieben die Kanaaniter nicht, die zu Gaser wohneten. Also blieben die Kanaaniter unter Ephraim bis auf diesen Tag und wurden zinsbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Und das Los fiel dem Stamm Manasse, denn er ist Josephs erster Sohn, und fiel auf Machir, den ersten Sohn Manasses, den Vater Gileads, denn er war ein streitbarer Mann; darum ward ihm Gilead und Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Den andern Kindem aber Manasses und ihren Geschlechtern fiel es auch, namlich den Kindem Abiesers, den Kindem Heleks, den Kindem Asriels, den Kindem Sechems, den Kindem Hephers und den Kindem Semidas. Das sind die Kinder Manasses, des Sohns Josephs, Mannsbilder unter ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Aber Zelaphehad, der Sohn Hephers, des Sohns Gileads, des Sohns Machirs, des Sohns Manasses, hatte keine Sohne, sondern Tochter; und ihre Namen sind diese: Mahela, Noa, Hagla, Milka, Thirza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Und traten vor den Priester Eleasar und vor Josua, den Sohn Nuns, und vor die Obersten und sprachen: Der HERR hat Mose geboten, daß eruns sollte Erbteil geben unter unsern Brudern. Und man gab ihnen Erbteil unter den Brudern ihres Vaters nach dem Befehl des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Es fielen aber auf Manasse zehn Schnure außer dem Lande Gilead und Basan, dasjenseit des Jordans liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Denn die Tochter Manasses nehmen Erbteil unter seinen Sohnen, und das Land Gilead ward den andern Kindern Manasses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Und die Grenze Manasses war von Asser an gen Michmethath, die vor Sechem lieget, und langet zur Rechten an die von En-Thapuah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Denn das Land Thapuah ward Manasse; und ist die Grenze Manasses an die Kinder Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Danach kommt sie herab gen Nahal-Kana gegen mittagwarts zu den Bachstadten, die Ephraims sind, unter den Stadten Manasses; aber von Mitternacht ist die Grenze Manasses am Bach und endet sich am Meer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'dem Ephraim gegen Mittag und dem Manasse gegen Mitternacht; und das Meer ist seine Grenze; und soil stoßen an Asser von Mitternacht und an Isascharvon Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'So hatte nun Manasse unter Isaschar und Asser Beth-Sean und ihre Tochter, Jeblaam und ihre Tochter und die zu Dor und ihre Tochter und die zu En-Dor und ihre Tochter und die zu Thaanach und ihre Tochter und die zu Megiddo und ihre Tochter und das dritte Teil Napheths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Und die Kinder Manasse konnten diese Stadte nicht einnehmen, sondern die Kanaaniter fingen an zu wohnen in demselbigen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Da aber die Kinder Israel machtig wurden, machten sie die Kanaaniter zinsbar und vertrieben sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Da redeten die Kinder Joseph mit Josua und sprachen: Warum hast du mir nur ein Los und eine Schnur des Erbteils gegeben? Und ich bin doch ein groß Volk, wie mich der HERR so gesegnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Da sprach Josua zu ihnen: Weil du ein groß Volk bist; so gehe hinauf in den Wald und haue urn daselbst im Lande der Pheresiter und Riesen, weil dir das Gebirge Ephraim zu enge ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Da sprachen die Kinder Joseph: Das Gebirge werden wir nicht erlangen; denn es sind eiserne Wagen bei alien Kanaanitern; die im Tal des Landes wohnen, bei welchen liegt Beth-Sean und ihre Tochter und Jesreel im Tal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Josua sprach zum Hause Josephs, zu Ephraim und Manasse: Du bist ein groß Volk, und weil du so groß bist, mußt du nicht ein Los haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'sondern das Gebirge soil dein sein, da der Wald ist; den haue urn, so wird er deines Loses Ende sein, wenn du die Kanaaniter vertreibest, die eiserne Wagen haben und machtig sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Und es versammelte sich die ganze Gemeine der Kinder Israel gen Silo und richteten daselbst auf die Hütte des Stifts. Und das Land war ihnen unterworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Und waren noch sieben Stamme der Kinder Israel, denen sie ihr Erbteil nicht ausgeteilet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Und Josua sprach zu den Kindern Israel: Wie lange seid ihr so lali, daß ihr nicht hingehet, das Land einzunehmen, das euch der HERR, eurer Vater Gott, gegeben hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Schaffet euch aus jeglichem Stamm drei Manner, dalf, ich sie sende, und sie sich aufmachen und durchs Land gehen und beschreiben es nach ihren Erbteilen und kommen zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Teilet das Land in sieben Teile. Juda soli bleiben auf seiner Grenze von Mittag her, und das Haus Joseph soil bleiben auf seiner Grenze von Mitternacht her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Ihr aber beschreibet das Land der sieben Teile und bringet sie zu mir hieher, so will ich euch das Los werfen vor dem HERRN, unserm Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Denn die Leviten haben kein Teil unter euch, sondern das Priestertum des HERRN ist ihr Erbteil. Gad aber und Ruben und der halbe Stamm Manasse haben ihr Teil genommen jenseit des Jordans gegen dem Morgen, das ihnen Mose, der Knecht des HERRN, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Da machten sich die Manner auf, daß sie hingingen. Und Josua gebot ihnen, da sie hin wollten gehen, das Land zu beschreiben, und sprach: Gehet hin und durchwandelt das Land und beschreibet es und kommt wieder zu mir, dafi ich euch hie das Los werfe vor dem HERRN zu Silo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Also gingen die Manner hin und durchzogen das Land und beschrieben es auf einen Brief nach den Stadten in sieben Teile; und kamen zu Josua ins Lager gen Silo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Da warf Josua das Los uber sie zu Silo vor dem HERRN und teilete daselbst das Land aus unter die Kinder Israel, einem jeglichen sein Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Und das Los des Stamms der Kinder Benjamin fiel nach ihren Geschlechtern, und die Grenze ihres Loses ging aus zwischen den Kindern Juda und den Kindern Joseph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Und ihre Grenze war an der Ecke gegen Mitternacht vom Jordan an und gehet herauf an der Seite Jerichos von mitternachtwarts; und kommt aufs Gebirge gegen abendwarts und gehet aus an der Wuste Beth-Aven;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'und gehet von dannen gen Lus, an der Seite her an Lus gegen mittagwarts, das ist Bethel, und kommt hinab gen Atharoth-Adar an dem Berge, der vom Mittag liegt an dem niedern Beth-Horon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Danach neiget sie sich und lenket sich urn zur Ecke des Abends gegen Mittag von dem Berge, der vor Beth-Horon gegen mittagwarts liegt, und endet sich an Kiriath-Baal, das ist Kiriath-Jearim, die Stadt der Kinder Juda; das ist die Ecke gegen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Aber die Ecke gegen Mittag ist von Kiriath- Jearim an und gehet aus gegen Abend und kommt hinaus zum Wasserbrunnen Nephthoah;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'und gehet herab an des Berges Ende, der vor dem Tal des Sohns Hinnoms liegt, welches im Grunde Raphaim gegen Mitternacht liegt; und gehet herab durchs Tal Hinnom an der Seite der Jebusiter am Mittag und kommt hinab zum Brunnen Rogel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'und zeucht sich von mitternachtwarts und kommt hinaus gen En-Semes und kommt hinaus zu den Haufen, die gegen Adumim hinauf liegen, und kommt herab zum Stein Bohen, des Sohns Rubens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'und gehet zur Seite hin neben dem Gefilde, das gegen Mitternacht liegt, und kommt hinab aufs Gefilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'und gehet an der Seite Beth-Haglas, die gegen Mitternacht liegt, und ist sein Ende an der Zunge des Salzmeers gegen Mitternacht an dem Ort des Jordans gegen Mittag. Das ist die Mittagsgrenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Aber die Ecke gegen Morgen soli der Jordan enden. Das ist das Erbteil der Kinder Benjamin in ihren Grenzen umher unter ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Die Stadte aber des Stamms der Kinder Benjamin, unter ihren Geschlechtern sind diese: Jericho, Beth-Hagla, Emek-Reziz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beth-Araba, Zemaraim, Bethel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Hapara, Ophra,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kaphar-Amonai, Aphni, Gaba. Das sind zwolf Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beeroth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mizpe, Kaphira, Moza,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jerpeel, Thareala,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Eleph und die Jebusiter, das ist Jerusalem, Gibeath, Kiriath: vierzehn Stadte und ihre Dorfer. Das ist das Erbteil der Kinder Benjamin in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Danach fiel das andere Los des Stamms der Kinder Simeon nach ihren Geschlechtern; und ihr Erbteil war unter dem Erbteil der Kinder Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Und es ward ihnen zum Erbteil Beer-Seba, Seba, Molada,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hazar-Sual, Bala, Azem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'El-Tholad, Bethul, Horma,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziklag, Beth-Markaboth, Hazar, Sussa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Beth-Lebaoth, Saruhen. Das sind dreizehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimon, Ether, Asan. Das sind vier Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Dazu alle Dorfer, die urn diese Stadte liegen, bis gen Baalath-Beer-Ramath gegen Mittag. Das ist das Erbteil des Stamms der Kinder Simeon in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Denn der Kinder Simeon Erbteil ist unter der Schnur der Kinder Juda. Weil das Erbteil der Kinder Juda ihnen zu groß war, darum erbeten die Kinder Simeon unter ihrem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Das dritte Los fiel auf die Kinder Sebulon nach ihren Geschlechtern; und die Grenze ihres Erbteils war bis gen Sarid;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'und gehet hinauf zu abendwarts gen Mareala und stoßet an Dabaseth und stoßet an den Bach, der vor Jakneam fleufit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'und wendet sich von Sarid gegen der Sonnen Aufgang bis an die Grenze Kisloth-Thabor; und kommt hinaus gen Dabrath und langet hinauf gen Japhia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Und von dannen gehet sie gegen den Aufgang durch Gitta-Hepher, Itha, Kazin und kommt hinaus gen Rimon-Mithoar und Nea;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'und lenket sich herum von Mitternacht gen Nathon und endet sich im Tal Jephthah-EI,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Katath, Nahalal, Simron, Jedeala und Bethlehem. Das sind zwolf Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Das ist das Erbteil der Kinder Sebulon in ihren Geschlechtern; das sind ihre Stadte und Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Das vierte Los fiel auf die Kinder Isaschar nach ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Und ihre Grenze war Jesreel, Chesulloth, Sunem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharaim, Sion, Anaharath,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabith, Kiseon, Abez,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remeth, En-Gannim, En-Hada, Beth-Pazez;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'und stoßet an Thabor, Sahazima, Beth-Semes; und ihr Ende ist am Jordan. Sechzehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Das ist das Erbteil des Stamms der Kinder Isaschar in ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Das fünfte Los fiel auf den Stamm der Kinder Asser nach ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Und ihre Grenze war Helkath, Hali, Beten, Achsaph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alamelech, Amead, Miseal; und stoßt an den Karmel am Meer und an Sihor-Libnath;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'und wendet sich gegen der Sonnen Aufgang gen Beth-Dagon und stoßet an Sebulon und an das Tal Jephthah-EI, an die Mitternacht Beth-Emek, Negiel; und kommt hinaus zu Kabul zur Linken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebron, Rehob, Hammon, Kana bis an groß Zidon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'und wendet sich gen Rama bis zu derfesten Stadt Zor; und wendet sich gen Hossa und endet sich am Meer der Schnur nach gen Achsib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Uma, Aphek, Rehob. Zwoundzwanzig Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Das ist das Erbteil des Stamms der Kinder Asser in ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Das sechste Los fiel auf die Kinder Naphthali in ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Und ihre Grenzen waren von Heleph, Eton, durch Zaenannim, Adami-Nekeb, Jabneel bis gen Lakum und endet sich am Jordan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'und wendet sich zum Abend gen Asnoth- Thabor und kommt von dannen hinaus gen Hukok; und stoßet an Sebulon gegen Mittag und an Asser gegen Abend und an Juda am Jordan gegen der Sonnen Aufgang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'und hatfeste Stadte: Zidim, Zer, Hamath, Rakath, Cinnereth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hazor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, En-Hazor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jereon, Migdal-EI, Harem, Beth-Anath, Beth- Sames. Neunzehn Stadte und ihre Dorfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Das ist das Erbteil des Stamms der Kinder Naphthali in ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Das siebente Los fiel auf den Stamm der Kinder Dan nach ihren Geschlechtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Und die Grenze ihres Erbteils waren Zarea, Esthaol, Irsames,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saelabin, Ajalon, Jethla,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Eton, Thimnatha, Ekron,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Eltheke, Gibethon, Baalath,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bne-Barak, Gath-Rimon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-Jarkon, Rakon mitden Grenzen gegen Japho.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Und an denselben endet sich die Grenze der Kinder Dan. Und die Kinder Dan zogen hinauf und stritten wider Lesem und gewannen und schlugen sie mit der Scharfe des Schwerts; und nahmen sie ein und wohneten drinnen; und nannten sie Dan nach ihres Vaters Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Das ist das Erbteil des Stamms der Kinder Dan in ihren Geschlechtern, Stadten und Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Und da sie das Land gar ausgeteilet hatten, mit seinen Grenzen, gaben die Kinder Israel Josua, dem Sohn Nuns, ein Erbteil unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Und gaben ihm nach dem Befehl des HERRN die Stadt, die er forderte, namlich Thimnath-Serah auf dem Gebirge Ephraim. Da bauete erdie Stadt und wohnete drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Das sind die Erbteile, die Eleasar, der Priester, und Josua, der Sohn Nuns, und die Obersten der Vater unter den Geschlechtern durchs Los den Kindern Israel austeileten zu Silo vor dem HERRN, vor der Tur der Hütte des Stiffs; und vollendeten also das Austeilen des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Und der HERR redete mit Josua und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Sage den Kindern Israel: Gebet unter euch Freistadte, davon ich durch Mose euch gesagt habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'dahin fliehen moge ein Totschlager, der eine Seele unversehens und unwissend schlagt, daß sie unter euch frei seien vor dem Blutracher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Und der da fleucht zu der Stadte einer, soil stehen außen vor der Stadt Tor und vor den Altesten der Stadt seine Sache ansagen; so sollen sie ihn zu sich in die Stadt nehmen und ihm Raum geben, daß er bei ihnen wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Und wenn der Blutracher ihm nachjagt, sollen sie den Totschlager nicht in seine Hande ubergeben, weil er unwissend seinen Nachsten geschlagen hat und ist ihm zuvor nicht feind gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'So soil er in der Stadt wohnen, bis daß er stehe vor der Gemeine vor Gericht, bis dafi der Hohepriester sterbe, der zur selben Zeit sein wird. Alsdann soil der Totschlager wiederkommen in seine Stadt und in sein Haus, zur Stadt, davon er geflohen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Da heiligten sie Kedes in Galilaa auf dem Gebirge Naphthali; und Sechem auf dem Gebirge Ephraim; und Kiriath-Arba, das ist Hebron, auf dem Gebirge Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Und jenseit des Jordans, da Jericho liegt, gegen dem Aufgang, gaben sie Bezer in der Wüste auf der Ebene aus dem Stamm Ruben; und Ramoth in Gilead aus dem Stamm Gad; und Golan in Basan aus dem Stamm Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Das waren die Stadte, bestimmt alien Kindern Israel und den Fremdlingen, die unter ihnen wohneten, daß dahin fliehe, wer eine Seele unversehens schlagt, daß er nicht sterbe durch den Blutracher, bis daß er vor der Gemeine gestanden sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Da traten herzu die obersten Vater unter den Leviten zu dem Priester Eleasar und Josua, dem Sohn Nuns, und zu den obersten Vatern unter den Stammen der Kinder Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'und redeten mit ihnen zu Silo im Lande Kanaan und sprachen: Der HERR hat geboten durch Mose, daß man uns Stadte geben solle, zu wohnen, und derselben Vorstadte zu unserm Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Da gaben die Kinder Israel den Leviten von ihren Erbteilen nach dem Befehl des HERRN diese Stadte und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Und das Los fiel auf das Geschlecht der Kahathiter, und wurden den Kindern Aarons, des Priesters, aus den Leviten durchs Los dreizehn Stadte: von dem Stamm Juda, von dem Stamm Simeon und von dem Stamm Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Den andern Kindern aber Kahaths, desselben Geschlechts, wurden durchs Los zehn Stadte: von dem Stamm Ephraim, von dem Stamm Dan und von dem halben Stamm Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Aber den Kindern Gersons, desselben Geschlechts, wurden durchs Los dreizehn Stadte: von dem Stamm Isaschar, von dem Stamm Asser und von dem Stamm Naphthali und von dem halben Stamm Manasse zu Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Den Kindern Meraris, ihres Geschlechts, wurden zwolf Stadte: von dem Stamm Ruben, von dem Stamm Gad und von dem Stamm Sebulon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Also gaben die Kinder Israel den Leviten durchs Los diese Stadte und ihre Vorstadte, wie der HERR durch Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Von dem Stamm der Kinder Juda und von dem Stamm der Kinder Simeon gaben sie diese Stadte, die sie mit ihren Namen nannten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'den Kindern Aarons, des Geschlechts der Kahathiter, aus den Kindern Levi; denn das erste Los war ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'So gaben sie ihnen nun Kiriath-Arba, die des Vaters Enaks war, das ist Hebron, auf dem Gebirge Juda, und ihre Vorstadte urn sie her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Aber den Acker der Stadt und ihre Dorfer gaben sie Kaleb, dem Sohn Jephunnes, zu seinem Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Also gaben sie den Kindern Aarons, des Priesters, die Freistadt der Totschlager, Hebron und ihre Vorstadte, Libna und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jathir und ihre Vorstadte, Esthemoa und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holon und ihre Vorstadte, Debir und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain und ihre Vorstadte, Juta und ihre Vorstadte, Beth-Semes und ihre Vorstadte; neun Stadte von diesen zween Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Von dem Stamm Benjamin aber gaben sie vier Stadte: Gibeon und ihre Vorstadte, Geba und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anathoth und ihre Vorstadte, Almon und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'daß alle Stadte der Kinder Aarons, des Priesters, waren dreizehn mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Den Geschlechtern aber der andern Kinder Kahaths, den Leviten, wurden durch ihr Los vier Stadte von dem Stamm Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Und gaben ihnen die Freistadt der Totschlager, Sechem und ihre Vorstadte auf dem Gebirge Ephraim, Geser und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibzaim und ihre Vorstadte, Beth-Horon und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Von dem Stamm Dan vier Stadte: Eltheke und ihre Vorstadte, Gibthon und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon und ihre Vorstadte, Gath-Rimon und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Von dem halben Stamm Manasse zwo Stadte: Thaenach und ihre Vorstadte, Gath-Rimon und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'daß alle Stadte der andern Kinder des Geschlechts Kahath waren zehn mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Den Kindern aber Gersons aus den Geschlechtern der Leviten wurden gegeben von dem halben Stamm Manasse zwo Stadte: die Freistadt fur die Totschlager, Golan in Basan und ihre Vorstadte, Beesthra und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Von dem Stamm Isaschar vier Stadte: Kision und ihre Vorstadte, Dabrath und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth und ihre Vorstadte, En-Gannim und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Von dem Stamm Asser vier Stadte: Miseal und ihre Vorstadte, Abdon und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkath und ihre Vorstadte, Rehob und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Von dem Stamm Naphthali drei Stadte: die Freistadt Kedes fur die Totschlager in Galilaa und ihre Vorstadte, Hammoth-Dor und ihre Vorstadte, Karthan und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'daß alle Stadte des Geschlechts der Gersoniter waren dreizehn mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Den Geschlechtern aber der Kinder Meraris, den andern Leviten, wurden gegeben von dem Stamm Sebulon vier Stadte: Jakneam und ihre Vorstadte, Kartha und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna und ihre Vorstadte, Nahalal und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Von dem Stamm Ruben vier Stadte: Bezer und ihre Vorstadte, Jahza und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth und ihre Vorstadte, Mephaath und ihre Vorstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Von dem Stamm Gad vier Stadte: die Freistadt fur die Totschlager, Ramoth in Gilead und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Mahanaim und ihre Vorstadte, Hesbon und ihre Vorstadte, Jaeser und ihre Vorstadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'da($ alter Stadte der Kinder Meraris unter ihren Geschlechtern, der andern Leviten, nach ihrem Los waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Aller Stadte der Leviten unter dem Erbe der Kinder Israel waren achtundvierzig mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Und eine jegliche dieser Stadte hatte ihre Vorstadt urn sich her, eine wie die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Also gab der HERR dem Israel alles Land, das ergeschworen hatte, ihren Vatern zu geben; und sie nahmen\'s ein und wohneten drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Und der HERR gab ihnen Ruhe von alien umher, wie er ihren Vatern geschworen hatte; und stund ihrer Feinde keiner wider sie, sondern alle ihre Feinde gab er in ihre Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Und es fehlte nichts an allem Guten, das der HERR dem Hause Israel geredet hatte. Es kam alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Da rief Josua die Rubeniter und Gaditer und den halben Stamm Manasse');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'und sprach zu ihnen: Ihr habt alles gehalten, was euch Mose, der Knecht des HERRN, geboten hat, und gehorchet meiner Stimme in allem, das ich euch geboten habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Ihr habt eure Bruder nicht verlassen eine lange Zeit her bis auf diesen Tag; und habt gehalten an dem Gebot des HERRN eures Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Weil nun der HERR, euer Gott, hat eure Bruder zur Ruhe gebracht; wie er ihnen geredet hat, so wendet euch nun und ziehet hin in eure Hütten im Lande eures Erbes, das euch Mose der Knecht des HERRN, gegeben hat jenseit des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Haltet aber nun an mit Fleifi, dafi ihr tut nach dem Gebot und Gesetz, das euch Mose, der Knecht des HERRN, geboten hat, daß ihr den HERRN, euren Gott, liebet und wandelt auf alien seinen Wegen und seine Gebote haltet und ihm anhanget und ihm dienet von ganzem Herzen und von ganzer Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Also segnete sie Josua und ließ sie gehen; und sie gingen zu ihren Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Dem halben Stamm Manasse hatte Mose gegeben zu Basan; der andern Halfte gab Josua unter ihren Brudern diesseit des Jordans gegen Abend. Und da er sie ließ gehen zu ihren Hütten und sie gesegnet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'sprach er zu ihnen: Ihr kommt wieder heim mit großem Gut zu euren Hütten mit sehr viel Vieh, Silber, Gold, Erz, Eisen und Kleidern; so teilet nun den Raub eurer Feinde aus unter eure Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Also kehreten urn die Rubeniter, Gaditer und der halbe Stamm Manasse und gingen von den Kindern Israel aus Silo, die im Lande Kanaan liegt, daß sie ins Land Gilead zogen, zum Lande ihres Erbes, das sie erbeten aus Befehl des HERRN durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Und da sie kamen an die Haufen am Jordan, die im Lande Kanaan liegen, baueten dieselben Rubeniter, Gaditer und der halbe Stamm Manasse daselbst am Jordan einen großen, schonen Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Da aber die Kinder Israel horeten sagen: Siehe, die Kinder Ruben, die Kinder Gad und der halbe Stamm Manasse haben einen Altar gebauet gegen das Land Kanaan, an den Haufen am Jordan, diesseit der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'da versammelten sie sich mit der ganzen Gemeine zu Silo, daß sie wider sie hinaufzogen mit einem Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Und sandten zu ihnen ins Land Gilead Pinehas, den Sohn Eleasars, des Priesters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'und mit ihm zehn oberste Fursten unter den Hausern ihrer Vater, aus jeglichem Stamm Israels einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Und da sie zu ihnen kamen ins Land Gilead, redeten sie mit ihnen und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'So laßt euch sagen die ganze Gemeine des HERRN: Wie versündiget ihr euch also an dem Gott Israels, daß ihr euch heute kehret von dem HERRN damit, daß ihr euch einen Altar bauet, daß ihr abfallet von dem HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ist\'s uns zu wenig an der Missetat Peors, von welcher wir noch auf diesen Tag nicht gereiniget sind, und kam eine Plage unter die Gemeine des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'und ihrwendeteuch heute von dem HERRN weg und seid heute abtrunnig worden von dem HERRN, daß er heute Oder morgen uber die ganze Gemeine Israel erzurne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Dunket euch das Land eures Erbes unrein, so kommt heruber ins Land, das der HERR hat, da die Wohnung des HERRN stehet, und erbet unter uns; und werdet nicht abtrunnig von dem HERRN und von uns, daß ihr euch einen Altar bauet außer dem Altar des HERRN, unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Versündigte sich nicht Achan, der Sohn Serahs, am Verbanneten, und der Zorn kam über die ganze Gemeine Israel, und erging nicht allein unter über seiner Missetat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Da antworteten die Kinder Ruben und die Kinder Gad und der halbe Stamm Manasse und sagten zu den Hauptern und Fursten Israels:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Der starke Gott, der HERR, der starke Gott, der HERR, weili, so weüi Israel auch: fallen wir ab Oder sundigen wider den HERRN, so helfe er uns heute nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Und so wir darum den Altar gebauet haben, daß wir uns von dem HERRN wenden wollten, Brandopfer Oder Speisopfer drauf opfern, Oder Dankopfer drauf tun dem HERRN, so fordere er es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Und so wir\'s nicht vielmehr aus Sorge des Dinges getan haben und sprachen: Heute Oder morgen mochten eure Kinder zu unsern Kindern sagen: Was gehet euch der HERR, der Gott Israels, an?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Der HERR hat den Jordan zur Grenze gesetzt zwischen uns und euch Kindern Ruben und Gad; ihr habt kein Teil am HERRN. Damitwurden eure Kinder unsere Kinder von der Furcht des HERRN weisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Darum sprachen wir: Lalit uns einen Altar bauen, nicht zum Opfer noch zum Brandopfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'sondern dafi er ein Zeuge sei zwischen uns und euch und unsern Nachkommen, daß wir dem HERRN Dienst tun mogen vor ihm mit unsern Brandopfern, Dankopfern und andern Opfern, und eure Kinder heute Oder morgen nicht sagen durfen zu unsern Kindern: Ihr habt kein Teil an dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Wenn sie aber also zu uns sagen wurden Oder zu unsern Nachkommen heute Oder morgen, so konnten sie sagen: Sehet das Gleichnis des Altars des HERRN, den unsere Vater gemacht haben, nicht zum Opfer noch zum Brandopfer, sondern zum Zeugen zwischen uns und euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Das sei feme von uns, dafi wir abtrunnig werden von dem HERRN, dafi wir uns heute wollten von ihm wenden und einen Altar bauen zum Brandopfer und zum Speisopfer und andern Opfern aulier dem Altar des HERRN, unsers Gottes, der vor seiner Wohnung stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Da aber Pinehas, der Priester, und die Obersten der Gemeine, die Fursten Israels, die mit ihm waren, horeten diese Worte, die die Kinder Ruben, Gad und Manasse sagten, gefielen sie ihnen wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Und Pinehas, der Sohn Eleasars, des Priesters, sprach zu den Kindern Ruben, Gad und Manasse: Heute erkennen wir, daß der HERR unter uns ist, daß ihr euch nicht an dem HERRN versundiget habt in dieser Tat. Nun habt ihr die Kinder Israel errettet aus der Hand des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Da zog Pinehas, der Sohn Eleasars, des Priesters, und die Obersten aus dem Lande Gilead von den Kindern Ruben und Gad wieder ins Land Kanaan zu den Kindern Israel und sagten es ihnen an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Das gefiel den Kindern Israel wohl und lobten den Gott der Kinder Israel und sagten nicht mehr, dafi sie hinauf wollten ziehen mit einem Heer wider sie, zu verderben das Land, da die Kinder Ruben und Gad innen wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Und die Kinder Ruben und Gad hiefien den Altar: Dali er Zeuge sei zwischen uns, und daß der HERR Gott sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Und nach langer Zeit, da der HERR hatte Israel zur Ruhe gebracht vor alien ihren Feinden umher, und Josua nun alt und wohl betaget war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'berief er das ganze Israel und ihre Altesten, Haupter, Richter und Amtleute und sprach zu ihnen: Ich bin alt und wohl betaget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'und ihr habt gesehen alles, was der HERR, euer Gott, getan hat an alien diesen Volkern vor euch her; denn der HERR, euer Gott, hat selber fur euch gestritten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Sehet, ich habe euch die ubrigen Volker durchs Los zugeteilet, einem jeglichen Stamm sein Erbteil, vom Jordan an, und alle Volker, die ich ausgerottet habe, und am grolien Meer gegen der Sonnen Untergang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Und der HERR, euer Gott, wird sie ausstofien vor euch und von euch vertreiben, dafi ihr ihr Land einnehmet, wie euch der HERR, euer Gott, geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So seid nun sehr getrost, daß ihr haltet und tut alles, was geschrieben stehet im Gesetzbuch Moses, daß ihr nicht davon weichet weder zur Rechten noch zur Linken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'auf dafi ihr nicht unter diese ubrigen Volker kommet, die mit euch sind, und nicht gedenket noch schworet bei dem Namen ihrer Gotter, noch ihnen dienet, noch sie anbetet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'sondern dem HERRN, eurem Gott, anhanget, wie ihr bis auf diesen Tag getan habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'So wird der HERR vor euch her vertreiben grolie und machtige Volker; und niemand hat euch widerstanden bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Euer einer wird tausend jagen; denn der HERR, euer Gott, streitet fur euch, wie er euch geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Darum, so behutet aufs fleifügste eure Seelen, daß ihr den HERRN, euren Gott, lieb habet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Wo ihr euch aber umwendet und diesen ubrigen Volkern anhanget und euch mit ihnen verheiratet, daß ihr unter sie und sie unter euch kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'so wisset, daß der HERR, euer Gott, wird nicht mehr alle diese Volker vor euch vertreiben, sondern sie werden euch zum Strick und Netz und zur Geiliel in euren Seiten werden und zum Stachel in euren Augen, bis daß er euch umbringe von dem guten Lande, das euch der HERR, euer Gott, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Siehe, ich gehe heute dahin wie alle Welt; und ihr sollt wissen von ganzem Herzen und von ganzer Seele, daß nicht ein Wort gefehlet hat an all dem Guten, das der HERR, euer Gott, euch geredet hat; es ist alles kommen und keins verblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Gieichwie nun alles Gute kommen ist, das der HERR, euer Gott, euch geredet hat, also wird der HERR auch tiber euch kommen lassen alles Bose, bis er euch vertilge von diesem guten Lande, das euch der HERR, euer Gott, gegeben hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'wenn ihr übertretet den Bund des HERRN, eures Gottes, den er euch geboten hat, und hingehet und andern Gottern dienet und sie anbetet, daß der Zorn des HERRN uber euch ergrimmet und euch bald umbringet von dem guten Lande, das er euch gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Josua versammelte alle Stamme Israels gen Sichem und berief die Altesten von Israel, die Haupter, Richter und Amtleute. Und da sie vor Gott getreten waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'sprach er zum ganzen Volk: So sagt der HERR, der Gott Israels: Eure Vater wohneten vorzeiten jenseit des Wassers, Tharah, Abrahams und Nahors Vater, und dieneten andern Gottern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Da nahm ich euren Vater Abraham jenseit des Wassers und lieft ihn wandern im ganzen Lande Kanaan; und mehrete ihm seinen Samen und gab ihm Isaak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Und Isaak gab ich Jakob und Esau; und gab Esau das Gebirge Seir zu besitzen. Jakob aber und seine Kinder zogen hinab nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Da sandte ich Mose und Aaron und plagte Agypten, wie ich unter ihnen getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Danach fuhrete ich euch und eure Vater aus Agypten. Und da ihr ans Meer kamet, und die Agypter euren Vatern nachjagten mit Wagen und Reitern ans Schilfmeer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'da schrieen sie zum HERRN; der setzte eine Finsternis zwischen euch und den Agyptern; und fuhrete das Meer uber sie und bedeckte sie. Und eure Augen haben gesehen, was ich in Agypten getan habe. Und ihr habt gewohnet in der Wuste eine lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Und ich habe euch gebracht in das Land der Amoriter, die jenseit des Jordans wohneten; und da sie wider euch stritten, gab ich sie in eure Hande, daß ihr ihr Land besaftet, und vertilgete sie vor euch her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Da machte sich auf Balak, der Sohn Zipors, der Moabiter Konig, und stritt wider Israel und sandte hin und lieft rufen Bileam, dem Sohn Beors, daß er euch verfluchete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Aber ich wollte ihn nicht horen. Und er segnete euch; und ich errettete euch aus seinen Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Und da ihr uber den Jordan ginget und gen Jericho kamet, stritten wider euch die Burger von Jericho, die Amoriter, Pheresiter, Kanaaniter, Hethiter, Girgositer, Heviter und Jebusiter; aber ich gab sie in eure Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Und sandte Hornissen vor euch her; die trieben sie aus vor euch her, die zween Konige der Amoriter, nicht durch dein Schwert noch durch deinen Bogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Und habe euch ein Land gegeben, daran ihr nicht gearbeitet habt, und Stadte, die ihr nicht gebauet habt, daß ihr drinnen wohnet und esset von Weinbergen und Olbergen, die ihr nicht gepflanzet habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'So furchtet nun den HERRN und dienet ihm treulich und rechtschaffen; und lasset fahren die Gotter, denen eure Vater gedienet haben jenseit des Wassers und in Agypten, und dienet dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Gefallt es euch aber nicht, daß ihr dem HERRN dienet, so erwahlet euch heute, welchem ihr dienen wollet: dem Gott, dem eure Vater gedienet haben jenseit des Wassers, Oder den Gottern der Amoriter, in welcher Land ihr wohnet. Ich aber und mein Haus wollen dem HERRN dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Da antwortete das Volk und sprach: Das sei feme von uns, daß wir den HERRN verlassen und andern Gottern dienen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Denn der HERR, unser Gott, hat uns und unsere Vater aus Agyptenland gefuhret, aus dem Diensthause, und hat vor unsern Augen solche grofte Zeichen getan und uns behutet auf dem ganzen Wege, den wir gezogen sind, und unter alien Volkern, durch welche wirgegangen sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'und hat ausgestoften vor uns her alle Volker der Amoriter, die im Lande wohneten. Darum wollen wir auch dem HERRN dienen; denn er ist unser Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Josua sprach zum Volk: Ihr konnet dem HERRN nicht dienen; denn er ist ein heiliger Gott, ein eifriger Gott, der eurer Ubertretung und Sunde nicht schonen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Wenn ihr aber den HERRN verlasset und einem fremden Gott dienet, so wird er sich wenden und euch plagen und euch umbringen, nachdem er euch Gutes getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Das Volk aber sprach zu Josua: Nicht also, sondern wir wollen dem HERRN dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Da sprach Josua zum Volk: Ihr seid Zeugen uber euch, daß ihr den HERRN euch erwahlet habt, daß ihr ihm dienet. Und sie sprachen: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'So tut nun von euch die fremden Gotter, die unter euch sind, und neiget euer Herz zu dem HERRN, dem Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Und das Volk sprach zu Josua: Wir wollen dem HERRN, unserm Gott, dienen und seiner Stimme gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Also machte Josua desselben Tages einen Bund mit dem Volk und legte ihnen Gesetze und Rechte vor zu Sichem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Und Josua schrieb dies alles ins Gesetzbuch Gottes; und nahm einen groften Stein und richtete ihn auf daselbst unter einer Eiche, die bei dem Heiligtum des HERRN war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Und sprach zum ganzen Volk: Siehe, dieser Stein soli Zeuge sein zwischen uns, denn er hat gehoret alle Rede des HERRN, die er mit uns geredet hat; und soil ein Zeuge uber euch sein, daß ihr euren Gott nicht verleugnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Also liefi Josua das Volk, einen jeglichen in sein Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Und es begab sich nach dieser Geschichte, daß Josua, der Sohn Nuns, der Knecht des HERRN, starb, da er hundertundzehn Jahre alt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Und man begrub ihn in der Grenze seines Erbteils, zu Thimnath Serah, die auf dem Gebirge Ephraim liegt von mitternachtwarts am Berge Gaas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Und Israel dienete dem HERRN, solange Josua lebte und die Altesten, welche lange Zeit lebten nach Josua, die alle Werke des HERRN wuftten, die er an Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Die Gebeine Josephs, welche die Kinder Israel hatten aus Agypten gebracht, begruben sie zu Sichem in dem Stuck Feldes, das Jakob kaufte von den Kindern Hemors, des Vaters Sichems, urn hundert Groschen, und ward der Kinder Josephs Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleasar, der Sohn Aarons, starb auch; und sie begruben ihn zu Gibea seines Sohns Pinehas, die ihm gegeben war auf dem Gebirge Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Nach dem Tod Josuas fragten die Kinder Israel den HERRN und sprachen: Wer soli unter uns den Krieg führen wider die Kanaaniter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Der HERR sprach: Juda soli ihn führen. Siehe, ich habe das Land in seine Hand gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Da sprach Juda zu seinem Bruder Simeon: Zeuch mit mir hinauf in meinem Los und laft uns wider die Kanaaniter streiten, so will ich wieder mit dir ziehen in deinem Los. Also zog Simeon mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Da nun Juda hinaufzog, gab ihm der HERR die Kanaaniter und Pheresiter in ihre Hande; und schlugen zu Besek zehntausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Und fanden den Adoni-Besek zu Besek und stritten wider ihn; und schlugen die Kanaaniter und Pheresiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Aber Adoni-Besek floh, und sie jagten ihm nach; und da sie ihn ergriffen, verhieben sie ihm die Daumen an seinen Handen und Fufien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Da sprach Adoni-Besek: Siebenzig Konige mit verhauenen Daumen ihrer Hande und Füfte lasen auf unter meinem Tisch. Wie ich nun getan habe, so hat mir Gott wieder vergolten: Und man brachte ihn gen Jerusalem; daselbst starb er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Aber die Kinder Juda stritten wider Jerusalem und gewannen sie und schlugen sie mit der Scharfe des Schwerts und zündeten die Stadt an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Danach zogen die Kinder Juda herab, zu streiten wider die Kanaaniter, die auf dem Gebirge und gegen Mittag und in den Grunden wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Und Juda zog hin wider die Kanaaniter, die zu Hebron wohneten (Hebron aber hiefi vorzeiten Kiriath- Arba), und schlugen den Sesai und Ahiman und Thalmai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Und zog von dannen wider die Einwohner zu Debir. Debir aber hiefi vorzeiten Kiriath-Sepher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Und Kaleb sprach: Wer Kiriath-Sepher schlagt und gewinnet, dem will ich meine Tochter Achsa zum Weibe geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Da gewann sie Athniel, derßohn Kenas\', des Kalebs jüngsten Bruders. Und ergab ihm seine Tochter Achsa zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Und es begab sich, da sie einzog, ward ihr geraten, daß sie fordern sollte einen Acker von ihrem Vater; und fiel vom Esel. Da sprach Kaleb zu ihr: Was ist dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Sie sprach: Gib mir einen Segen; denn du hast mir ein Mittagsland gegeben, gib mir auch ein wasseriges. Da gab er ihr ein wasseriges oben und unten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Und die Kinder des Keniters, Moses Schwagers, zogen herauf aus der Palmenstadt mit den Kindern Juda in die Wüste Juda, die da liegt gegen Mittag der Stadt Arad; und gingen hin und wohneten unter dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Und Juda zog hin mit seinem Bruder Simeon und schlugen die Kanaaniter zu Zephath und verbanneten sie; und nannten die Stadt Horma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Dazu gewann Juda Gaza mit ihrer Zugehor und Askion mit ihrer Zugehor und Ekron mit ihrer Zugehor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Und der HERR war mit Juda, daü er das Gebirge einnahm; denn er konnte die Einwohner im Grunde nicht einnehmen, darum daß sie eiserne Wagen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Und sie gaben dem Kaleb Hebron, wie Mose gesagt hatte; und er vertrieb daraus die drei Sohne des Enak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Aber die Kinder Benjamin vertrieben die Jebusiter nicht, die zu Jerusalem wohneten, sondern die Jebusiter wohneten bei den Kindern Benjamin zu Jerusalem bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Desselbengieichen zogen auch die Kinder Joseph hinauf gen Bethel; und der HERR war mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Und das Haus Joseph verkundschaftete Bethel, die vorhin Lus hieft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Und die Wachter sahen einen Mann aus der Stadt gehen und sprachen zu ihm: Weise uns, wo wir in die Stadt kommen, so wollen wir Barmherzigkeit an dir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Und da er ihnen zeigte, wo sie in die Stadt kamen, schlugen sie die Stadt mit der Scharfe des Schwerts; aber den Mann und all sein Geschlecht lieften sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Da zog derselbe Mann ins Land der Hethiter und bauete eine Stadt und hieft sie Lus; die heiftet noch heutigestages also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Und Manasse vertrieb nicht Beth-Sean mit ihren Tochtem, noch Thaenach mit ihren Tochtern, noch die Einwohner zu Dor mit ihren Tochtern, noch die Einwohner zu Jebieam mit ihren Tochtern, noch die Einwohner zu Megiddo mit ihren Tochtern; und die Kanaaniter fingen an zu wohnen in demselben Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Da aber Israel machtig ward, machte erdie Kanaaniter zinsbar und vertrieb sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Desgleichen vertrieb auch Ephraim die Kanaaniter nicht, die zu Gaser wohneten, sondern die Kanaaniter wohneten unter ihnen zu Gaser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon vertrieb auch nicht die Einwohner zu Kitron und Nahalal, sondern die Kanaaniter wohneten unter ihnen und waren zinsbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser vertrieb die Einwohner zu Acko nicht, noch die Einwohner zu Zidon, zu Ahelab, zu Achsib, zu Helba, zu Aphik und zu Rehob,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'sondern die Asseriter wohneten unter den Kanaanitern, die im Lande wohneten; denn sie vertrieben sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naphthali vertrieb die Einwohner nicht zu Beth- Semes noch zu Beth-Anath, sondern wohneten unter den Kanaanitern, die im Lande wohneten. Aber die zu Beth-Semes und zu Beth-Anath wurden zinsbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Und die Amoriter drungen die Kinder Dan aufs Gebirge und lieften nicht zu, daß sie herunter in den Grund kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Und die Amoriter fingen an zu wohnen auf dem Gebirge Heres, zu Ajalon und zu Saalbim. Doch ward ihnen die Hand des Hauses Joseph zu schwer, und wurden zinsbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Und die Grenze der Amoriter war, da man gen Akrabbim hinaufgehet, und von dem Fels und von der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Es kam aber der Engel des HERRN herauf von Gilgal gen Bochim und sprach: Ich habe euch aus Agypten heraufgeführet und ins Land gebracht, das ich euren Vatern geschworen habe, und sprach, ich wollte meinen Bund mit euch nicht nachlassen ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'daß ihr nicht solltet einen Bund machen mit den Einwohnern dieses Landes und ihre Altare zerbrechen. Aber ihr habt meiner Stimme nicht gehorchet. Warum habt ihr das getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Da sprach ich auch: Ich will sie nicht vertreiben vor euch, daß sie euch zum Stricke werden und ihre Gotter zum Netze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Und da der Engel des HERRN solche Worte geredet hatte zu alien Kindern Israel, hub das Volk seine Stimme auf und weineten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Und hieften die Statte Bochim; und opferten daselbst dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Denn als Josua das Volk von sich gelassen hatte, und die Kinder Israel hingezogen waren, ein jeglicher in sein Erbteil, das Land einzunehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'dienete das Volk dem HERRN, solange Josua lebte und die Altesten, die lange nach Josua lebten und alle die groften Werke des HERRN gesehen hatten, die er Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Da nun Josua, der Sohn Nuns, gestorben war, der Knecht des HERRN, als er hundertundzehn Jahre alt war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'begruben sie ihn in den Grenzen seines Erbteils zu Thimnath-Heres auf dem Gebirge Ephraim, von mitternachtwarts am Berge Gaas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Da auch alle, die zu der Zeit gelebt hatten, zu ihren Vatern versammelt worden, kam nach ihnen ein ander Geschlecht auf, das den HERRN nicht kannte, noch die Werke, die er an Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Da taten die Kinder Israel übel vor dem HERRN und dieneten Baalim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Und verlieften den HERRN, ihrer Vater Gott, der sie aus Agyptenland gefuhret hatte, und folgten andern Gottern nach, auch den Gottern der Volker, die urn sie her wohneten; und beteten sie an und erzümeten den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Denn sie verlieften je und je den HERRN und dieneten Baal und Astharoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'So ergrimmete dann der Zorn des HERRN uber Israel und gab sie in die Hand derer, die sie raubeten, daß sie sie beraubeten, und verkaufte sie in die Hande ihrer Feinde umher. Und sie konnten nicht mehr ihren Feinden widerstehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'sondern wo sie hinaus wollten, war des HERRN Hand wider sie zum Ungluck, wie denn der HERR ihnen gesagt und geschworen hatte; und wurden hart gedranget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Wenn denn der HERR Richter auferweckte, die ihnen halfen aus der Rauber Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'so gehorchten sie den Richtern auch nicht, sondern hureten andern Gottern nach und beteten sie an und wichen bald von dem Wege, da ihre Vater auf gegangen waren, des HERRN Geboten zu gehorchen, und taten nicht wie dieselben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Wenn aber der HERR ihnen Richter erweckte, so war der HERR mit dem Richter und half ihnen aus ihrer Feinde Hand, solange der Richter lebte. Denn es jammerte den HERRN ihr Wehklagen uber die, so sie zwangen und drangeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Wenn aber der Richter starb, so wandten sie sich und verderbeten es mehr denn ihre Vater, daß sie andern Gottern folgten, ihnen zu dienen und sie anzubeten; sie fielen nicht von ihrem Vornehmen noch von ihrem halsstarrigen Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Darum ergrimmete dann des HERRN Zorn uber Israel, daß er sprach: Weil dies Volk meinen Bund ubergangen hat, den ich ihren Vatern geboten habe, und gehorchen meiner Stimme nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'so will ich auch hinfort die Heiden nicht vertreiben, die Josua hat gelassen, da er starb,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'daß ich Israel an ihnen versuche, ob sie auf dem Wege des HERRN bleiben, daß sie drinnen wandeln, wie ihre Vater geblieben sind, Oder nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Also lieft der HERR diese Heiden, daß er sie nicht bald vertrieb, die er nicht hatte in Josuas Hand ubergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Dies sind die Heiden, die der HERR lieft bleiben, daß er an ihnen Israel versuchte, die nicht wuftten urn die Kriege Kanaans,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'und daß die Geschlechter der Kinder Israel wuftten und lerneten streiten, die vorhin nichts drum wuftten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'namlich die fünf Fursten der Philister und alle Kanaaniter und Zidonier und Heviter, die am Berge Libanon wohneten, von dem Berge Baal-Hermon an, bis man kommt gen Hemath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Dieselben blieben, Israel an denselben zu versuchen, daß es kund wtirde, ob sie den Geboten des HERRN gehorchten, die er ihren Vatern geboten hatte durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Da nun die Kinder Israel also wohneten unter den Kanaanitern, Hethitern, Amoritern, Pheresitern, Hevitern und Jebusitern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'nahmen sie jener Tochter zu Weibern und gaben ihre Tochter jener Sohnen und dieneten jener Gottern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'und taten übel vor dem HERRN und vergaften des HERRN, ihres Gottes, und dieneten Baalim und den Hainen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Da ergrimmete der Zorn des HERRN uber Israel und verkaufte sie unter die Hand Kusan-Risathaims, des Konigs zu Mesopotamien; und dieneten also die Kinder Israel dem Kusan-Risathaim acht Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Da schrieen die Kinder Israel zu dem HERRN; und der HERR erweckte ihnen einen Heiland, der sie erlosete, Athniel, den Sohn Kenas, Kalebs jungsten Bruders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Und der Geist des HERRN war in ihm; und ward Richter in Israel und zog aus zum Streit. Und der HERR gab den Konig zu Syrien, Kusan-Risathaim, in seine Hand, daß seine Hand uber ihn zu stark ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Da ward das Land stille vierzig Jahre. Und Athniel, der Sohn Kenas, starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Aber die Kinder Israel taten furder übels vor dem HERRN. Da starkte der HERR Eglon, den Konig der Moabiter, wider Israel, darum daß sie libels taten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Und sammelte zu ihm die Kinder Ammon und die Amalekiter. Und er zog hin und schlug Israel und nahm ein die Palmenstadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Und die Kinder Israel dieneten Eglon, der Moabiter Konige, achtzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Da schrieen sie zu dem HERRN; und der HERR erweckte ihnen einen Heiland, Ehud, den Sohn Geras, des Sohns Jeminis, der war link. Und da die Kinder Israel durch denselben Geschenk sandten Eglon, der Moabiter Konige,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'machte ihm Ehud ein zweischneidig Schwert einer Elle lang und gürtete es unter sein Kleid auf seine rechte Hüfte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'und brachte das Geschenk dem Eglon, der Moabiter Konige. Eglon aber war ein sehr fetter Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Und da erdas Geschenk hatte uberantwortet, liefi er das Volk, die das Geschenk getragen hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'und kehrete urn von den Gotzen zu Gilgal und lieli ansagen: Ich habe, o Konig, dir was Heimliches zu sagen. Er aber hiefi schweigen, und gingen aus von ihm alle, die urn ihn stunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Und Ehud kam zu ihm hinein. Er aber sa(i in der Sommerlaube, die fur ihn allein war. Und Ehud sprach: Ich habe Gottes Wort an dich. Da stund er auf vom Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Ehud aber reckte seine linke Hand aus und nahm das Schwert von seiner rechten Hüfte und stieli es ihm in seinen Bauch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'daß auch das Heft der Schneide nach hineinfuhr, und das Fett das Heft verschloli (denn er zog das Schwert nicht aus seinem Bauch), daß der Mist von ihm ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Aber Ehud ging den Saal hinaus und tat die Tür hinter ihm zu und verschloli sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Da er nun hinaus war, kamen seine Knechte hinein und sahen, daß die Tür der Sommerlaube verschlossen war, und sprachen: Er ist vielleicht zu Stuhl gegangen in der Kammer an der Sommerlaube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Da sie aber so lange harreten, bis sie sich schameten (denn niemand tat die Tür der Laube auf), nahmen sie den Schlüssel und schlossen auf; siehe, da lag ihr Herr auf der Erde tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud aber war entronnen, dieweil sie verzogen, und ging vor den Gotzen über und entrann bis gen Seirath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Und da er hineinkam, blies er die Posaune auf dem Gebirge Ephraim. Und die Kinder Israel zogen mit ihm vom Gebirge, und er vor ihnen her;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'und sprach zu ihnen: Jaget mir nach; denn der HERR hat euch die Moabiter, eure Feinde, in eure Hande gegeben. Und sie jagten ihm nach und gewannen die Furt am Jordan ein, die gen Moab gehet, und liefien niemand hinübergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Und schlugen die Moabiter zu der Zeit, bei zehntausend Mann, allzumal die besten und streitbare Manner, daß nicht einer entrann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Also wurden die Moabiter zu der Zeit unter die Hand der Kinder Israel gedampfet. Und das Land war stille achtzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Danach war Samgar, der Sohn Anaths; der schlug sechshundert Philister mit einem Ochsenstecken und erlosete auch Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Aber die Kinder Israel taten furder übel vor dem HERRN, da Ehud gestorben war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Und der HERR verkaufte sie in die Hand Jabins, der Kanaaniter Konig, der zu Hazor safi; und sein Feldhauptmann war Sissera, und er wohnete zu Haroseth der Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Und die Kinder Israel schrieen zum HERRN; denn er hatte neunhundert eiserne Wagen und zwang die Kinder Israel mit Gewalt zwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Zu derselbigen Zeit war Richterin in Israel die Prophetin Debora, ein Eheweib des Lapidoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Und sie wohnete unter der Palme Deboras, zwischen Rama und Bethel, auf dem Gebirge Ephraim. Und die Kinder Israel kamen zu ihr hinauf vor Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Dieselbige sandte hin und ließ rufen Barak, dem Sohn Abinoams, von Kedes-Naphthali, und liefi ihm sagen: Hat dir nicht der HERR, der Gott Israels, geboten: Gehe hin und zeuch auf den Berg Thabor und nimmt zehntausend Mann mit dir von den Kindern Naphthali und Sebulon?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Denn ich will Sissera, den Feldhauptmann Jabins, zu dir ziehen an das Wasser Kison mit seinen Wagen und mit seiner Menge und will ihn in deine Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Barak sprach zu ihr: Wenn du mit mir zeuchst, so will ich ziehen; zeuchst du aber nicht mit mir, so will ich nicht ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Sie sprach: Ich will mit dir ziehen, aber der Preis wird nicht dein sein auf dieser Reise, die du tust, sondern der HERR wird Sissera in eines Weibes Hand ubergeben. Also machte sich Debora auf und zog mit Barak gen Kedes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Da rief Barak Sebulon und Naphthali gen Kedes und zog zu Fuft mit zehntausend Mann. Debora zog auch mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Heber aber, der Keniter, war von den Kenitern, von den Kindern Hobabs, Moses Schwager, gezogen und hatte seine Hutte aufgeschlagen bei den Eichen Zaanaim neben Kedes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Da ward Sissera angesagt, daß Barak, der Sohn Abinoams, auf den Berg Thabor gezogen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Und er rief alle seine Wagen zusammen, neunhundert eiserne Wagen, und alles Volk, das mit ihm war, von Haroseth der Heiden an das Wasser Kison.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debora aber sprach zu Barak: Auf, das ist der Tag, da dir der HERR Sissera hat in deine Hand gegeben; denn der HERR wird vor dir herausziehen. Also zog Barak von dem Berge Thabor herab, und die zehntausend Mann ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Aber der HERR erschreckte den Sissera samt alien seinen Wagen und ganzem Heer vor der Scharfe des Schwerts Baraks daß Sissera von seinem Wagen sprang und floh zu Fuft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak aber jagte nach den Wagen und dem Heer bis gen Haroseth der Heiden. Und alles Heer Sisseras fiel vor der Scharfe des Schwerts, daß nicht einer uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sissera aber floh zu Fuft in die Hutte Jaels, des Weibes Hebers, des Keniters. Denn der Konig Jabin zu Hazor und das Haus Hebers, des Keniters, stunden miteinander im Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jael aber ging heraus Sissera entgegen und sprach zu ihm: Weiche, mein Herr, weiche zu mir und fürchte dich nicht! Und er wich zu ihr ein in ihre Hutte; und sie deckte ihn zu mit einem Mantel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Er aber sprach zu ihr: Lieber, gib mir ein wenig Wassers zu trinken, denn mich durstet. Da tat sie auf einen Milchtopf und gab ihm zu trinken und deckte ihn zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Und er sprach zu ihr: T ritt in der Hutte Tur, und wenn jemand kommt und fragt, ob jemand hie sei, so sprich: Niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Da nahm Jael, das Weib Hebers, einen Nagel von der Hutte und einen Hammer in ihre Hand und ging leise zu ihm hinein und schlug ihm den Nagel durch seinen Schlaf, daß er zur Erde sank. Er aber entschlummerte, ward ohnmachtig und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Da aber Barak Sissera nachjagte, ging ihm Jael entgegen heraus und sprach zu ihm: Gehe her, ich will dir den Mann zeigen, den du suchest. Und da er zu ihr hinein kam, lag Sissera tot, und der Nagel stak in seinem Schlaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Also dampfte Gott zu der Zeit Jabin, der Kanaaniter Konig, vor den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Und die Hand der Kinder Israel fuhr fort und ward stark wider Jabin, der Kanaaniter Konig, bis sie ihn ausrotteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Da sang Debora und Barak der Sohn Abinoams, zu der Zeit und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Lobetden HERRN, daß Israel wiederfrei ist worden, und das Volk willig dazu gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Horet zu, ihr Konige, und merket auf ihr Fursten! Ich will, dem HERRN will ich singen, dem HERRN, dem Gott Israels, will ich spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'HERR, da du von Seir auszogest und einhergingest vom Felde Edoms, da erzitterte die Erde, der Himmel troff, und die Wolken troffen mit Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Die Berge ergossen sich vor dem HERRN, der Sinai vor dem HERRN, dem Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Zu den Zeiten Samgars, des Sohns Anaths, zu den Zeiten Jaels, waren vergangen die Wege; und die da auf Pfaden gehen sollten, die wandelten durch krumme Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Es gebrach, an Bauern gebrach\'s in Israel, bis daß ich, Debora, aufkam, bis ich aufkam, eine Mutter in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Ein Neues hat Gott erwahlet, er hat die Tore bestritten. Es war kein Schild noch Spieft unter vierzigtausend in Israel zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mein Herz ist wohl an den Regenten Israels, die freiwillig sind unter dem Volk. Lobet den HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'die ihr auf schonen Eselinnen reitet, die ihr am Gericht sitzet und singet, die ihr auf dem Wege gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Da die Schutzen schrieen zwischen den Schopfern, da sage man von der Gerechtigkeit des HERRN, von der Gerechtigkeit seiner Bauern in Israel; da zog des HERRN Volk herab zu den Toren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Wohlauf, wohlauf, Debora, wohlauf, wohlauf, und singe ein Liedlein! Mache dich auf, Barak, und fange deine Fanger, du Sohn Abinoams!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Da herrschten die Verlassenen uber die machtigen Leute; der HERR hat geherrschet durch mich uber die Gewaltigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Aus Ephraim war ihre Wurzel wider Amalek und nach dir, Benjamin, in deinem Volk. Von Machir sind Regenten kommen, und von Sebulon sind Regierer worden durch die Schreibfeder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Und Fursten zu Isaschar waren mit Debora. Und Isaschar war wie Barak im Grunde, gesandt mit seinem Fuftvolk. Ruben hielt hoch von ihm und sonderte sich von uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Warum bleibest du zwischen den Hürden, zu horen das Bloken der Herde, und haltst graft von dir und sonderst dich von uns?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead blieb jenseit des Jordans. Und warum wohnete Dan unter den Schiffen? Asser saft an der Anfurt des Meers und blieb in seinen zerrissenen Flecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulons Volk aber wagte seine Seele in den Tod; Naphthali auch, in der Hohe des Feldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Die Konige kamen und stritten; da stritten die Konige der Kanaaniter zu Thaanach, am Wasser Megiddo; aber sie brachten keinen Gewinn davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vom Himmel ward wider sie gestritten, die Sterne in ihren Laufen stritten wider Sissera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Der Bach Kison walzte sie, der Bach Kedumim, der Bach Kison. Tritt, meine Seele, auf die Starken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Da rasselten der Pferde Fülie vor dem Zagen ihrer machtigen Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Fluchet der Stadt Meros, sprach der Engel des HERRN; fluchet ihren Burgern, daß sie nicht kamen dem HERRN zu Hilfe, zu Hilfe dem HERRN zu den Helden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Gesegnet sei unter den Weibern Jael, das Weib Hebers, des Keniters; gesegnet sei sie in der Hütte unter den Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Milch gab sie, da er Wasser forderte, und Butter brachte sie dar in einer herrlichen Schale.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Sie griff mit ihrer Hand den Nagel und mit ihrer Rechten den Schmiedehammer; und schlug Sissera durch sein Haupt und zerquetschte und durchbohrte seinen Schlaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Zu ihren Fufien krummete er sich, fiel nieder und legte sich; er krummete sich, fiel nieder zu ihren Fuf Jen; wie er sich krummete, so lag er verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Die Mutter Sisseras sah zum Fenster aus und heulete durchs Gitter: Warum verzeucht sein Wagen, daß er nicht kommt? Wie bleiben die Rader seiner Wagen so dahinten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Die weisesten unter seinen Frauen antworteten, da sie ihre Klageworte immer wiederholte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Sollen sie denn nicht finden und austeilen den Raub, einem jeglichen Mann eine Metze oderzwo zur Ausbeute, und Sissera bunte gestickte Kleider zur Ausbeute, gestickte bunte Kleider urn den Hals zur Ausbeute?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Also müssen umkommen, HERR, alle deine Feinde! Die ihn aber liebhaben, müssen sein, wie die Sonne aufgehet in ihrer Macht! Und das Land war stille vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Und da die Kinder Israel libels taten vor dem HERRN, gab sie der HERR unter die Hand der Midianiter sieben Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Und da der Midianiter Hand zu stark ward über Israel, machten die Kinder Israel fur sich Klüfte in den Gebirgen und Hohlen und Festungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Und wenn Israel etwas saete, so kamen die Midianiter und Amalekiter und die aus dem Morgenlande herauf über sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'und lagerten sich wider sie und verderbeten das Gewachs auf dem Lande bis hinan gen Gaza; und Men nichts übriges von Nahrung in Israel, weder Schaf noch Ochsen noch Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Denn sie kamen herauf mit ihrem Vieh und Hütten, wie eine grolie Menge Heuschrecken, daß weder sie noch ihre Kamele zu zahlen waren; und fielen ins Land, daß sie es verderbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Also ward Israel sehr geringe vor den Midianitern. Da schrieen die Kinder Israel zu dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Als sie aber zu dem HERRN schrieen urn der Midianiter willen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'sandte der HERR einen Propheten zu ihnen, der sprach zu ihnen: So spricht der HERR, der Gott Israels: Ich habe euch aus Agypten geführet und aus dem Diensthause gebracht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'und habe euch errettet von der Agypter Hand und von aller Hand, die euch drangeten, und habe sie vor euch ausgestolien und ihr Land euch gegeben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'und sprach zu euch: Ich bin der HERR, euer Gott; furchtet nicht der Amoriter Gotter, in welcher Lande ihr wohnet. Und ihr habt meiner Stimme nicht gehorchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Und ein Engel des HERRN kam und setzte sich unter eine Eiche zu Ophra, die war Joas\', des Vaters der Esriter, und sein Sohn Gideon drosch Weizen an der Kelter, daß er flohe vor den Midianitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Da erschien ihm der Engel des HERRN und sprach zu ihm: Der HERR mit dir, du streitbarer Held!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon aber sprach zu ihm: Mein Herr, ist der HERR mit uns, warum ist uns denn solches alles widerfahren? Und wo sind alle seine Wunder, die uns unsere Vater erzahleten und sprachen: Der HERR hat uns aus Agypten geführet? Nun aber hat uns der HERR verlassen und unter der Midianiter Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Der HERR aberwandte sich zu ihm und sprach: Gehe hin in dieser deiner Kraft; du sollst Israel erlosen aus der Midianiter Handen. Siehe, ich habe dich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Er aber sprach zu ihm: Mein Herr, womit soli ich Israel erlosen? Siehe, meine Freundschaft ist die geringste in Manasse und ich bin der Kleinste in meines Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Der HERR aber sprach zu ihm: Ich will mit dir sein, daß du die Midianiter schlagen sollst wie einen einzelnen Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Er aber sprach zu ihm: Lieber, habe ich Gnade vor dir funden, so mache mirein Zeichen, daß du es seiest, der mit mir redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Weiche nicht, bis ich zu dir komme und bringe mein Speisopfer, das ich vor dir lasse. Er sprach: Ich will bleiben, bis daß du wiederkommest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Und Gideon kam und schlachtete ein Ziegenbocklein; und nahm ein Epha ungesauerten Mehls und legte Fleisch in einen Korb und tat die Brühe in einen Topf; und brachte es zu ihm heraus unter die Eiche und trat herzu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Aber der Engel Gottes sprach zu ihm: Nimm das Fleisch und das Ungesauerte und lali es auf dem Fels, der hie ist, und geuli die Brühe aus. Und er tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Da reckte der Engel des HERRN den Stecken aus, den er in der Hand hatte, und rührete mit der Spitze das Fleisch und das ungesauerte Mehl an. Und das Feuer fuhr aus dem Fels und verzehrete das Fleisch und das ungesauerte Mehl. Und der Engel des HERRN verschwand aus seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Da nun Gideon sah, daß es ein Engel des HERRN war, sprach er: 0 Herr, HERR, habe ich also einen Engel des HERRN von Angesicht gesehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Aber der HERR sprach zu ihm: Friede sei mit dir! Furchte dich nicht; du wirst nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Da bauete Gideon daselbst dem HERRN einen Altar; und hieft ihn: Der HERR des Friedens. Der stehet noch bis auf den heutigen Tag zu Ophra, des Vaters der Esriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Und in derselben Nacht sprach der HERR zu ihm: Nimm einen Farren unterden Ochsen, die deines Vaters sind, und einen andern Farren, der siebenjahrig ist, und zerbrich den Altar Baals, der deines Vaters ist, und haue ab den Hain, der dabei stehet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'und baue dem HERRN, deinem Gott, oben auf der Hohe dieses Felsen einen Altar und rüste ihn zu; und nimm den andern Farren und opfre ein Brandopfer mit dem Holz des Hains, den du abgehauen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Da nahm Gideon zehn Manner aus seinen Knechten und tat, wie ihm der HERR gesagt hatte. Aber er furchtete sich, solches zu tun des Tages vor seines Vaters Haus und den Leuten in der Stadt, und tat es bei der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Da nun die Leute in der Stadt des Morgens frühe aufstunden, siehe, da war der Altar Baals zerbrochen, und der Hain dabei abgehauen; und derandere Farre, ein Brandopfer auf dem Altar, der gebauet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Und einer sprach zu dem andern: Wer hat das getan? Und da sie suchten und nachfragten, ward gesagt: Gideon, der Sohn Joas\', hat das getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Da sprachen die Leute der Stadt zu Joas: Gib deinen Sohn heraus! Er muft sterben, dafi er den Altar Baals zerbrochen und den Hain dabei abgehauen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joas aber sprach zu alien, die bei ihm stunden: Wollt ihr urn Baal hadern? Wollt ihr ihm helfen? Wer urn ihn hadert, der soli dieses Morgens sterben. Ist er Gott, so rechte er urn sich selbst, dafi sein Altar zerbrochen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Von dem Tage an hiefi man ihn Jerubbaal und sprach: Baal rechte urn sich selbst, daß sein Altar zerbrochen ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Da nun alle Midianiter und Amalekiter und die aus dem Morgenlande sich zu Haufe versammelt hatten und zogen herdurch und lagerten sich im Grunde Jesreel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'zog der Geist des HERRN Gideon an; und er lieft die Posaunen blasen und rief Abieser, daß sie ihm folgeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Und sandte Botschaft in ganz Manasse und rief ihn an, daß sie ihm auch nachfolgeten. Er sandte auch Botschaft zu Asser und Sebulon und Naphthali; die kamen herauf ihm entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Und Gideon sprach zu Gott: Willst du Israel durch meine Hand erlosen, wie du geredet hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'so will ich ein Fell mit der Wolle auf die Tenne legen. Wird der Tau auf dem Fell allein sein und auf der ganzen Erde trocken, so will ich merken, daß du Israel erlosen wirst durch meine Hand, wie du geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Und es geschah also. Und da er des andern Morgens früh aufstund, druckte er den Tau aus von dem Fell und fullete eine Schale voll des Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Und Gideon sprach zu Gott: Dein Zorn ergrimme nicht wider mich, daß ich noch einmal rede. Ich will\'s nur noch einmal versuchen mit dem Fell. Es sei allein auf dem Fell trocken und Tau auf der ganzen Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Und Gott tat also dieselbe Nacht, daß trocken war allein auf dem Fell und Tau auf der ganzen Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Da machte sich Jerubbaal, das ist, Gideon, frühe auf, und alles Volk, das mit ihm war, und lagerten sich an den Brunnen Harod, daß er das Heer der Midianiter hatte gegen Mitternacht, hinterden Hügeln der Warte im Grunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Der HERR aber sprach zu Gideon: Des Volks ist zu viel, das mit dir ist, daß ich sollte Midian in ihre Hande geben; Israel mochte sich rühmen wider mich und sagen: Meine Hand hat mich erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'So laft nun ausschreien vor den Ohren des Volks und sagen: Wer blode und verzagt ist, der kehre urn und hebe bald sich vom Gebirge Gilead. Da kehrete des Volks urn zweiundzwanzigtausend, daß nur zehntausend uberblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Und der HERR sprach zu Gideon: Des Volks ist noch zu viel. Führe sie hinab ans Wasser, daselbst will ich sie dir prufen; und von welchem ich dir sagen werde, daß er mit dir ziehen soil, der soli mit dir ziehen; von welchem aber ich sagen werde, daß er nicht mit dir ziehen soil, der soil nicht ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Und er fuhrete das Volk hinab ans Wasser. Und der HERR sprach zu Gideon: Welcher mit seiner Zunge des Wassers lecket, wie ein Hund lecket, den stelle besonders; desselbengleichen, welcher auf seine Kniee fallt zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Da war die Zahl derer, die geleckt hatten aus der Hand zum Munde, dreihundert Mann; das andere Volk alles hatte knieend getrunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Und der HERR sprach zu Gideon: Durch die dreihundert Mann, die geleckt haben, will ich euch erlosen und die Midianiter in deine Hande geben; aber das andere Volk laft alles gehen an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Und sie nahmen Futterung fur das Volk mit sich und ihre Posaunen. Aber die andern Israeliten lieft er alle gehen, einen jeglichen in seine Hutte; er aber starkte sich mit dreihundert Mann. Und das Heer der Midianiter lag unten vor ihm im Grunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Und der HERR sprach in derselben Nacht zu ihm: Stehe auf und gehe hinab zum Lager; denn ich habe es in deine Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Furchtest du dich aber hinabzugehen, so laft deinen Knaben Pura mitdirhinabgehen zum Lager,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'daß du horest, was sie reden. Danach sollst du mit der Macht hinabziehen zum Lager. Da ging Gideon mit seinem Knaben Pura hinab an den Ort der Schildwachter, die im Lager waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Und die Midianiter und Amalekiter und alle aus dem Morgenlande hatten sich niedergelegt im Grunde wie eine Menge Heuschrecken; und ihre Kamele waren nicht zu zahlen vor der Menge, wie der Sand am Ufer des Meers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Da nun Gideon kam, siehe, da er zahlete einer einem andern einen Traum und sprach: Siehe, mir hat getraumet, mich deuchte, ein gerostet Gerstenbrot walzte sich zum Heer der Midianiter, und da es kam an die Gezelte, schlug es dieselbigen und warf sie nieder und kehrete sie urn, das Oberste zu unterst, daß das Gezelt lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Da antwortete der andere: Das ist nichts anderes denn das Schwert Gideons, des Sohns Joas\', des Israelites Gott hat die Midianiter in seine Hande gegeben mit dem ganzen Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Da Gideon den horete solchen Traum erzahlen und seine Auslegung, betete er an und kam wieder ins Heer Israel und sprach: Machet euch auf, denn der HERR hat das Heer der Midianiter in eure Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Und er teilete die dreihundert Mann in drei Haufen und gab einem jeglichen eine Posaune in seine Hand und ledige Krüge und Fackeln drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Und sprach zu ihnen: Sehet auf mich und tut auch also; und siehe, wenn ich an den Ort des Heers komme: wie ich tue, so tut ihr auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Wenn ich die Posaune blase und alle, die mit mir sind, so sollt ihr auch die Posaunen blasen urns ganze Heer und sprechen: Hie HERR und Gideon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Also kam Gideon und hundert Mann mit ihm an den Ort des Heers, an die ersten Wachter, die da verordnet waren, und weckten sie auf und bliesen mit Posaunen und zerschlugen die Krüge in ihren Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Also bliesen alle drei Haufen mit Posaunen und zerbrachen die Krüge. Sie hielten aber die Fackeln in ihrer linken Hand und die Posaunen in ihrer rechten Hand, daß sie bliesen und riefen: Hie Schwert des HERRN und Gideon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Und ein jeglicher stund auf seinem Ort urn das Heer her. Da ward das ganze Heer laufend, und schrieen und flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Und indem die dreihundert Mann bliesen die Posaunen, schaffte der HERR, daß im ganzen Heer eines jeglichen Schwert wider den andern war. Und das Heer floh bis gen Beth-Sitta Zereratha, bis an die Grenze der Breite Mehola bei Tabath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Und die Manner Israels von Naphthali, von Asser und vom ganzen Manasse schrieen und jagten den Midianitern nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Und Gideon sandte Botschaft auf das ganze Gebirge Ephraim und lieft sagen: Kommt herab, den Midianitern entgegen, und verlaufet ihnen das Wasser bis gen Beth-Bara und den Jordan! Da schrieen alle, die von Ephraim waren, und verliefen ihnen das Wasser bis gen Beth-Bara und den Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Und fingen zween Fursten der Midianiter, Oreb und Seeb; und erwurgeten Oreb auf dem Fels Oreb und Seeb in der Kelter Seeb; und jagten die Midianiter und brachten die Haupter Orebs und Seebs zu Gideon uber den Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Und die Manner von Ephraim sprachen zu ihm: Warum hast du uns das getan, daß du uns nicht riefest, da du in Streit zogest wider die Midianiter? Und zankten sich mit ihm heftiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Er aber sprach zu ihnen: Was habe ich jetzt getan, das eurer Tat gleich sei? Ist nicht eine Rebe Ephraims besser denn die ganze Weinernte Abiesers?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Gott hat die Fursten der Midianiter, Oreb und Seeb, in eure Hande gegeben. Wie hatte ich konnen das tun, das ihr getan habt? Da er solches redete, lieft ihr Zorn von ihm ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Da nun Gideon an den Jordan kam, ging er hinuber mit den dreihundert Mann, die bei ihm waren; und waren müde und jagten nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Und er sprach zu den Leuten zu Suchoth: Lieber, gebet dem Volk, das unter mir ist, etliche Brote; denn sie sind müde, daß ich nachjage den Konigen der Midianiter, Sebah und Zalmuna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Aber die Obersten zu Suchoth sprachen: Sind die Fauste Sebahs und Zalmunas schon in deinen Handen, daß wir deinem Heer sollen Brot geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon sprach: Wohlan, wenn der HERR Sebah und Zalmuna in meine Hand gibt, will ich euer Fleisch mit Dornen aus der Wüste und mit Hecken zerdreschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Und erzog von dannen hinauf gen Pnuel und redete auch also zu ihnen. Und die Leute zu Pnuel antworteten ihm gleichwie die zu Suchoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Und er sprach auch zu den Leuten zu Pnuel: Komme ich mit Frieden wieder, so will ich diesen Turm zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Sebah aber und Zalmuna waren zu Karkor, und ihr Heer mit ihnen, bei funfzehntausend, die alle uberblieben waren vom ganzen Heer derer aus Morgenland. Denn hundertundzwanzigtausend waren gefallen, die das Schwert ausziehen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Und Gideon zog hinauf auf der Strafte, da man in Hutten wohnet, gegen Morgen, gen Nobah und Jagbeha, und schlug das Heer, denn das Heer war sicher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Und Sebah und Zalmuna flohen; abererjagte ihnen nach und fing die zween Konige der Midianiter, Sebah und Zalmuna, und zerschreckte das ganze Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Da nun Gideon, der Sohn Joas 1, wiederkam vom Streit, ehe die Sonne heraufkommen war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'fing ereinen Knaben ausden Leuten zu Suchoth und fragte ihn; der schrieb ihm auf die Obersten zu Suchoth und ihrer Altesten, siebenundsiebenzig Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Und er kam zu den Leuten zu Suchoth und sprach: Siehe, hie ist Sebah und Zalmuna, über welchen ihr mich spottetet und sprachet: Ist denn Sebahs und Zalmunas Faust schon in deinen Handen, daß wir deinen Leuten, die müde sind, Brot geben sollen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Und er nahm die Altesten der Stadt und Dornen aus der Wüste und Hecken und liefi es die Leute zu Suchoth fuhlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Und den Turm Pnuel zerbrach er und erwurgete die Leute der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Und er sprach zu Sebah und Zalmuna: Wie waren die Manner, die ihr erwürgetet zu Thabor? Sie sprachen: Sie waren wie du, und ein jeglicher schon wie eines Konigs Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Er aber sprach: Es sind meine Bruder, meiner Mutter Sohne, gewesen. So wahr der HERR lebet, wo ihr sie hattet leben lassen, wollte ich euch nicht erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Und sprach zu seinem erstgebornen Sohn Jether: Stehe auf und erwürge sie! Aber der Knabe zog sein Schwert nicht aus; denn er furchtete sich, weil er noch ein Knabe war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Sebah aber und Zalmuna sprachen: Stehe du auf und mache dich an uns; denn danach der Mann ist, ist auch seine Kraft. Also stund Gideon auf und erwurgete Sebah und Zalmuna; und nahm die Spangen, die an ihrer Kamele Halsen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Da sprachen zu Gideon etliche in Israel: Sei Herr uber uns, du und dein Sohn und deines Sohns Sohn, weil du uns von der Midianiter Hand erloset hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Aber Gideon sprach zu ihnen: Ich will nicht Herr sein über euch, und mein Sohn soil auch nicht Herr über euch sein, sondern der HERR soil Herr über euch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gideon aber sprach zu ihnen: Eins begehre ich von euch: ein jeglicher gebe mir die Stirnbander, die er geraubet hat; denn weil es Ismaeliter waren, hatten sie güldene Stirnbander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Sie sprachen: Die wollen wir geben. Und breiteten ein Kleid aus, und ein jeglicher warf die Stirnbander drauf, die er geraubet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Und die güldenen Stirnbander, die er forderte, machten am Gewicht tausend siebenhundert Sekel Goldes, ohne die Spangen und Ketten und scharlakenen Kleider, die der Midianiter Konige tragen, und ohne die Halsbander ihrer Kamele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Und Gideon machte einen Leibrock draus und setzte es in seine Stadt zu Ophra. Und ganz Israel verhurete sich daran daselbst, und geriet Gideon und seinem Hause zum Argernis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Also wurden die Midianiter gedemutiget vor den Kindern Israel und huben ihren Kopf nicht mehr empor. Und das Land war stille vierzig Jahre, solange Gideon lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Und Jerubbaal, der Sohn Joas\', ging hin und wohnete in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Und Gideon hatte siebenzig Sohne, die aus seiner Hüfte kommen waren; denn er hatte viele Weiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Und sein Kebsweib, das er zu Sichem hatte, gebar ihm auch einen Sohn; den nannte er Abimelech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Und Gideon, der Sohn Joas\', starb in gutem Alter und ward begraben in seines Vaters Joas\' Grab zu Ophra, des Vaters der Esriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Da aber Gideon gestorben war, kehrten sich die Kinder Israel urn und hureten den Baalim nach und machten ihnen Baal-Berith zum Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Und die Kinder Israel gedachten nicht an den HERRN, ihren Gott, der sie errettet hatte von der Hand aller ihrer Feinde umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Und taten nicht Barmherzigkeit an dem Hause Jerubbaal-Gideon, wie er alles Gute an Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelech aber, der Sohn Jerubbaals, ging hin gen Sichem zu den Brudern seiner Mutter und redete mit ihnen und mit dem ganzen Geschlecht des Hauses seiner Mutter Vaters und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Lieber, redet vor den Ohren aller Manner zu Sichem: Was ist euch besser, daü siebenzig Manner, alle Kinder Jerubbaals, über euch Herren seien, Oder daß ein Mann über euch Herr sei? Gedenket auch dabei, daß ich euer Gebein und Fleisch bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Da redeten die Brüder seiner Mutter von ihm alle diese Worte vor den Ohren aller Manner zu Sichem; und ihr Herz neigte sich Abimelech nach, denn sie gedachten: Er ist unser Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Und gaben ihm siebenzig Silberlinge aus dem Hause Baal-Beriths. Und Abimelech dingete damit lose, leichtfertige Manner, die ihm nachfolgeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Und er kam in seines Vaters Haus gen Ophra und erwürgete seine Brüder, die Kinder Jerubbaals, siebenzig Mann, auf einem Stein. Es blieb aber über Jotham, der jüngste Sohn Jerubbaals; denn erward versteckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Und es versammelten sich alle Manner von Sichem und das ganze Haus Müio, gingen hin und machten Abimelech zum Konige bei der hohen Eiche, die zu Sichem stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Da das angesagt ward dem Jotham, ging er hin und trat auf die Hohe des Berges Grisim und hub auf seine Stimme, rief und sprach zu ihnen: Horet mich, ihr Manner zu Sichem, daß euch Gott auch hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Die Baume gingen hin, daß sie einen Konig über sich salbeten, und sprachen zum Olbaum: Sei unser Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Aber der Olbaum antwortete ihnen: Soil ich meine Fettigkeit lassen, die beide, Gotter und Menschen, an mir preisen, und hingehen, daß ich schwebe uber die Baume?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Da sprachen die Baume zum Feigenbaum: Komm du und sei unser Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Aber der Feigenbaum sprach zu ihnen: Soil ich meine Süftigkeit und meine gute Frucht lassen und hingehen, daß ich uber den Baumen schwebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Da sprachen die Baume zum Weinstock: Komm du und sei unser Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Aber der Weinstock sprach zu ihnen: Soli ich meinen Most lassen, der Gotter und Menschen frohlich macht, und hingehen, daß ich uber den Baumen schwebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Da sprachen alle Baume zum Dornbusch: Komm du und sei unser Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Und der Dornbusch sprach zu den Baumen: Ist\'s wahr, daß ihr mich zum Konige salbet uber euch, so kommt und vertrauet euch unter meinen Schatten; wo nicht, so gehe Feuer aus dem Dornbusch und verzehre die Zedern Libanons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Habt ihr nun recht und redlich getan, daß ihr Abimelech zum Konige gemacht habt? Und habt ihr wohlgetan an Jerubbaal und an seinem Hause und habt ihm getan, wie er urn euch verdienet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'daß mein Vater urn euretwillen gestritten hat und seine Seele dahingeworfen von sich, daß er euch errettete von der Midianiter Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Und ihr lehnet euch auf heute wider meines Vaters Haus und erwurget seine Kinder, siebenzig Mann, auf einem Stein; und machet euch einen Konig, Abimelech, seiner Magd Sohn, uber die Manner zu Sichem, weil er euer Bruder ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Habt ihr nun recht und redlich gehandelt an Jerubbaal und an seinem Hause an diesem Tage, so seid frohlich uber dem Abimelech, und er sei frohlich uber euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Wo nicht, so gehe Feuer aus von Abimelech und verzehre die Manner zu Sichem und das Haus Millo; und gehe auch Feuer aus von den Mannern zu Sichem und vom Hause Millo und verzehre Abimelech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Und Jotham floh und entwich; und ging gen Ber und wohnte daselbst vor seinem Bruder Abimelech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Als nun Abimelech drei Jahre uber Israel geherrschet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'sandte Gott einen bosen Willen zwischen Abimelech und den Mannern zu Sichem. Denn die Manner zu Sichem versprachen Abimelech;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'und zogen an den Frevel, an den siebenzig Sohnen Jerubbaals begangen, und legten derselben Blut auf Abimelech, ihren Bruder, der sie erwurget hatte, und auf die Manner zu Sichem, die ihm seine Hand dazu gestarket hatten, daß er seine Bruder erwurgete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Und die Manner zu Sichem bestelleten einen Hinterhalt auf den Spitzen der Berge und raubten alle, die auf der Strafte zu ihnen wandelten. Und es ward Abimelech angesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Es kam aber Gaal, der Sohn Ebeds, und seine Bruder und gingen zu Sichem ein. Und die Manner zu Sichem verlieften sich auf ihn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'und zogen heraus aufs Feld und lasen ab ihre Weinberge und kelterten; und machten einen Tanz und gingen in ihres Gottes Haus und aften und tranken und fluchten dem Abimelech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Und Gaal, der Sohn Ebeds, sprach: Wer ist Abimelech? und was ist Sichem, daß wir ihm dienen sollten? Ist er nicht Jerubbaals Sohn und hat Sebul, seinen Knecht, hergesetzt uber die Leute Hemors, des Vaters Sichems? Warum sollten wir ihm dienen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Wollte Gott, das Volk ware unter meiner Hand, daß ich den Abimelech vertriebe! Und es ward Abimelech gesagt: Mehre dein Heer und zeuch aus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Denn Sebul, der Oberste in der Stadt, da er die Worte Gaals, des Sohns Ebeds, horete, ergrimmete er in seinem Zorn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'und sandte Botschaft zu Abimelech heimlich und lieft ihm sagen: Siehe, Gaal, der Sohn Ebeds, und seine Bruder sind gen Sichem kommen und machen dir die Stadt widerwartig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'So mache dich nun auf bei der Nacht, du und dein Volk, das bei dir ist, und mache einen Hinterhalt auf sie im Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Und des Morgens, wenn die Sonne aufgehet, so mache dich frühe auf und uberfalle die Stadt. Und wo er und das Volk, das bei ihm ist, zu dir hinauszeucht, so tue mit ihm, wie es deine Hand findet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Abimelech stund auf bei der Nacht und alles Volk, das bei ihm war, und hielt auf Sichem mit vier Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Und Gaal, der Sohn Ebeds, zog heraus und trat vor die Tur an der Stadt Tor. Aber Abimelech machte sich auf aus dem Hinterhalt samt dem Volk, das mit ihm war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Da nun Gaal das Volk sah, sprach er zu Sebul: Siehe, da kommt ein Volk von der Hohe des Gebirges hernieder. Sebul aber sprach zu ihm: Du siehest die Schatten der Berge fur Leute an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal redete noch mehr und sprach: Siehe, ein Volk kommt hernieder aus dem Mittel des Landes, und ein Haufe kommt auf dem Wege zur Zaubereiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Da sprach Sebul zu ihm: Wo ist nun hie dein Maul, das da sagte: Wer ist Abimelech, daß wir ihm dienen sollten? Ist das nicht das Volk, das du verachtet hast? Zeuch nun aus und streite mit ihm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal zog aus vor den Mannern zu Sichem her und stritt mit Abimelech.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Aber Abimelech jagte ihn, daß erfloh vor ihm; und fielen viele Erschlagene bis an die Tur des Tors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Und Abimelech blieb zu Aruma. Sebul aber verjagte den Gaal und seine Bruder, daß sie zu Sichem nicht muftten bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Auf den Morgen aber ging das Volk heraus aufs Feld. Da das Abimelech ward angesagt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'nahm er das Volk und teilete es in drei Haufen und machte einen Hinterhalt auf sie im Felde. Als er nun sah, daß das Volk aus der Stadt ging, erhub er sich über sie und schlug sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelech aber und die Haufen, die bei ihm waren, überfielen sie und traten an die Tur der Stadt Tor; und zween der Haufen uberfielen alle, die auf dem Felde waren, und schlugen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Da stritt Abimelech wider die Stadt denselben ganzen Tag und gewann sie; und erwurgete das Volk, das drinnen war, und zerbrach die Stadt und saete Salz drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Da das horeten alle Manner des Turms zu Sichem, gingen sie in die Festung des Hauses des Gottes Berith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Da das Abimelech horete, daß sich alle Manner des Turms zu Sichem versammelt hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'ging er auf den Berg Zalmon mit all seinem Volk, das bei ihm war, und nahm eine Axt in seine Hand und hieb einen Ast von Baumen und hub ihn auf und legte ihn auf seine Achsel und sprach zu allem Volk, das mit ihm war: Was ihr gesehen habt, daß ich tue, das tut auch ihr eilend, wie ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Da hieb alles Volk ein jeglicher einen Ast ab und folgten Abimelech nach; und legten sie an die Festung und steckten sie mit Feuer an, daß auch alle Manner des Turms zu Sichem starben, bei tausend Mann und Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Abimelech aber zog gen Thebez und belegte sie und gewann sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Es war aber ein starker Turm mitten in der Stadt, auf welchen flohen alle Manner und Weiber und alle Burger der Stadt; und schlossen hinter sich zu und stiegen auf das Dach des Turms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Da kam Abimelech zum Turm und stritt dawider; und nahete sich zur Tur des T urms, daß er ihn mit Feuer verbrennete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Aber ein Weib warf ein Stuck von einem Muhlstein Abimelech auf den Kopf und zerbrach ihm den Schadel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Da rief Abimelech eilend dem Knaben, der seine Waffen trug, und sprach zu ihm: Zeuch dein Schwert aus und tote mich, daß man nicht von mir sage: Ein Weib hat ihn erwürget. Da durchstach ihn sein Knabe, und er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Da aber die Israelites die mit ihm waren, sahen, daß Abimelech tot war, ging ein jeglicher an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Also bezahlte Gott Abimelech das Ubel, das er an seinem Vater getan hatte, da er seine siebenzig Bruder erwurgete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Desselbengleichen alles Ubel der Manner Sichems vergalt ihnen Gott auf ihren Kopf, und kam uber sie der Fluch Jothams, des Sohns Jerubbaals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Nach Abimelech machte sich auf zu helfen Israel Thola, ein Mann von Isaschar, ein Sohn Puas, des Sohns Dodos. Und erwohnete zu Samir auf dem Gebirge Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Und richtete Israel dreiundzwanzig Jahre; und starb und ward begraben zu Samir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Nach ihm machte sich auf Jair, ein Gileaditer, und richtete Israel zweiundzwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Und hatte dreißig Sohne auf dreißig Eselsfullen reiten; und hatte dreißig Stadte, die heißen Dorfer Jairs bis auf diesen Tag und liegen in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Und Jair starb und ward begraben zu Kamon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Aber die Kinder Israel taten fürder ubel vor dem HERRN und dieneten Baalim und Astharoth und den Gottern zu Syrien und den Gottern zu Zidon und den Gottern Moabs und den Gottern der Kinder Ammon und den Gottern der Philister; und verließen den HERRN und dieneten ihm nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Da ergrimmete der Zorn des HERRN über Israel und verkaufte sie unter die Hand der Philister und der Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Und sie zertraten und zerschlugen die Kinder Israel von dem Jahr an wohl achtzehn Jahre, namlich alle Kinder Israel jenseit des Jordans, im Lande der Amoriter, das in Gilead liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Dazu zogen die Kinder Ammon über den Jordan und stritten wider Juda, Benjamin und wider das Haus Ephraim, also daß Israel sehr geangstet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Da schrieen die Kinder Israel zu dem HERRN und sprachen: Wir haben an dir gesundiget; denn wir haben unsern Gott verlassen und Baalim gedienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Aber der HERR sprach zu den Kindern Israel: Haben euch nicht auch gezwungen die Agypter, die Amoriter, die Kinder Ammon, die Philister,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'die Zidonier, die Amalekiter und Maaniter; und ich half euch aus ihren Handen, da ihr zu mir schrieet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Noch habt ihr mich verlassen und andern Gottern gedienet; darum will ich euch nicht mehr helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Gehet hin und schreietdie Gotteran, die ihr erwahlet habt; lasset euch dieselben helfen zur Zeit eurer Trubsal!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Aber die Kinder Israel sprachen zu dem HERRN: Wir haben gesundiget; mache es nur du mit uns, wie dir\'s gefallt; allein errette uns zu dieser Zeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Und sie taten von sich die fremden Gotter und dieneten dem HERRN. Und esjammerte ihn, daß Israel so geplaget ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Und die Kinder Ammon schrieen und lagerten sich in Gilead; aber die Kinder Israel versammelten sich und lagerten sich zu Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Und das Volk der Obersten zu Gilead sprachen untereinander: Welcher anfahet zu streiten wider die Kinder Ammon, der soil das Haupt sein über alle, die in Gilead wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jephthah, ein Gileaditer, war ein streitbarer Held, aber ein Hurenkind. Gilead aber hatte Jephthah gezeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Da aber das Weib Gileads ihm Kinder gebar, und desselben Weibes Kinder grofi wurden, stießen sie Jephthah aus und sprachen zu ihm: Du sollst nicht erben in unsers Vaters Hause, denn du bist eines andern Weibes Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Da floh er vor seinen Brüdem und wohnete im Lande Tob. Und es sammelten sich zu ihm lose Leute und zogen aus mitihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Und uber etliche Zeit hernach stritten die Kinder Ammon mit Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Da nun die Kinder Ammon also stritten mit Israel, gingen die Altesten von Gilead hin, daß sie Jephthah holeten aus dem Lande Tob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Und sprachen zu ihm: Komm und sei unser Hauptmann, daß wir streiten wider die Kinder Ammon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Aber Jephthah sprach zu den Altesten von Gilead: Seid ihr nicht, die mich hassen und aus meines Vaters Hause gestoßen habt? Und nun kommt ihr zu mir, weil ihr in T rubsal seid?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Die Altesten von Gilead sprachen zu Jephthah: Darum kommen wir nun wieder zu dir, daß du mit uns ziehest und helfest uns streiten wider die Kinder Ammon und seiest unser Haupt uber alle, die in Gilead wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jephthah sprach zu den Altesten von Gilead: So ihr mich wieder holet, zu streiten wider die Kinder Ammon, und der HERR sie vor mir geben wird, soil ich dann euer Haupt sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Die Altesten von Gilead sprachen zu Jephthah: Der HERR sei Zuhorer zwischen uns, wo wir nicht tun, wie du gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Also ging Jephthah mit den Altesten von Gilead; und das Volk setzte ihn zum Haupt und Obersten uber sich. Und Jephthah redete solches alles vor dem HERRN zu Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Da sandte Jephthah Botschaft zum Konige der Kinder Ammon und ließ ihm sagen: Was hast du mit mir zu schaffen, daß du kommest zu mir, wider mein Land zu streiten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Der Konig der Kinder Ammon antwortete den Boten Jephthahs: Darum daß Israel mein Land genommen hat, da sie aus Agypten zogen, von Arnon an bis an Jabbok und bis an den Jordan. So gib mir\'s nun wieder mit Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jephthah aber sandte noch mehr Boten zum Konige der Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Die sprachen zu ihm: So spricht Jephthah: Israel hat kein Land genommen, weder den Moabitern noch den Kindern Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Denn da sie aus Agypten zogen, wandelte Israel durch die Wuste bis an das Schilfmeer und kam gen Kades;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'und sandte Boten zum Konige der Edomiter und sprach: Laß mich durch dein Land ziehen! Aber der Edomiter Konig erhorete sie nicht. Auch sandten sie zum Konige der Moabiter, der wollte auch nicht. Also blieb Israel in Kades');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'und wandelte in der Wuste; und umzogen das Land der Edomiter und Moabiter und kamen von der Sonnen Aufgang an der Moabiter Land und lagerten sich jenseit des Arnon; und kamen nicht in die Grenze der Moabiter, denn Arnon ist der Moabiter Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Und Israel sandte Boten zu Sihon, der Amoriter Konig zu Hesbon, und ließ ihm sagen: Laß uns durch dein Land ziehen bis an meinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Aber Sihon vertrauete Israel nicht, durch seine Grenze zu ziehen, sondern versammelte all sein Volk und lagerte sich zu Jahza und stritt mit Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Der HERR aber, der Gott Israels, gab den Sihon mit all seinem Volk in die Hande Israels, daß sie sie schlugen. Also nahm Israel ein alles Land der Amoriter, die in demselben Lande wohneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'und nahmen alle Grenze der Amoriter ein von Arnon an bis an Jabbok und von der Wuste an bis an den Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'So hat nun der HERR, der Gott Israels die Amoriter vertrieben vor seinem Volk Israel; und du willst sie einnehmen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Du solltest die einnehmen, die dein Gott Kamos vertriebe, und uns lassen einnehmen alie, die der HERR, unser Gott, vor uns vertrieben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Meinest du, daß du besser Recht habest denn Balak, der Sohn Zipors, der Moabiter Konig? Hat derselbe auch je gerechtet Oder gestritten wider Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'obwohl Israel nun dreihundert Jahre gewohnet hat in Hesbon und ihren Tochtem, in Aroer und ihren Tochtem und alien Stadten, die am Arnon liegen? Warum errettetet ihr\'s nicht zu derselben Zeit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Ich habe nichts an dir gesundiget; und du tust so ubel an mir, daß du wider mich streitest. Der HERR falle heute ein Urteil zwischen Israel und den Kindern Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Aber der Konig der Kinder Ammon erhorete die Rede Jephthahs nicht, die er zu ihm sandte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Da kam der Geist des HERRN auf Jephthah; und zog durch Gilead und Manasse und durch Mizpe, das in Gilead liegt, und von Mizpe, das in Gilead liegt, auf die Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Und Jephthah gelobte dem HERRN ein Gelubde und sprach: Gibst du die Kinder Ammon in meine Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'was zu meiner Haustur heraus mir entgegengehet, wenn ich mit Frieden wiederkomme von den Kindern Ammon, das soil des HERRN sein, und will\'s zum Brandopfer opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Also zog Jephthah auf die Kinder Ammon, wider sie zu streiten. Und der HERR gab sie in seine Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Und er schlug sie von Aroer an, bis man kommt gen Minnit, zwanzig Stadte, und bis an den Plan der Weinberge, eine sehr große Schlacht. Und wurden also die Kinder Ammon gedemutiget vor den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Da nun Jephthah kam gen Mizpa zu seinem Hause, siehe, da gehet seine Tochter heraus ihm entgegen mit Pauken und Reigen; und sie war ein einiges Kind, und er hatte sonst keinen Sohn noch Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Und da er sie sah, zerriß er seine Kleider und sprach: Ach, meine Tochter, wie beugest du mich und betrubest mich! Denn ich habe meinen Mund aufgetan gegen dem HERRN und kann\'s nichtwiderrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Sie aber sprach: Mein Vater, hast du deinen Mund aufgetan gegen dem HERRN, so tue mir, wie es aus deinem Munde gegangen ist, nachdem der HERR dich gerochen hat an deinen Feinden, den Kindern Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Und sie sprach zu ihrem Vater: Du wollest mir das tun, daß du mich lassestzween Monden, daß ich von hinnen hinabgehe auf die Berge und meine Jungfrauschaft beweine mit meinen Gespielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Er sprach: Gehe hin! Und ließ sie zween Monden gehen. Da ging sie hin mit ihren Gespielen und beweinete ihre Jungfrauschaft auf den Bergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Und nach zween Monden kam sie wieder zu ihrem Vater. Und er tat ihr, wie er gelobet hatte; und sie war nie keines Mannes schuldig worden. Und ward eine Gewohnheit in Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'daß die Tochter Israel jahrlich hingehen, zu klagen die Tochter Jephthahs, des Gileaditers, des Jahrsvier Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Und die von Ephraim schrieen und gingen zu mitternachtwarts und sprachen zu Jephthah: Warum bist du in den Streit gezogen wider die Kinder Ammon und hast uns nicht gerufen, daß wir mit dir zogen? Wir wollen dein Haus samt dir mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jephthah sprach zu ihnen: Ich und mein Volk hatten eine große Sache mit den Kindern Ammon; und ich schrie euch an, aber ihr halfet mir nicht aus ihren Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Da ich nun sah, daß ihr nicht helfen wolltet, stellete ich meine Seele in meine Hand und zog hin wider die Kinder Ammon, und der HERR gab sie in meine Hand. Warum kommt ihr nun zu mir herauf, wider mich zu streiten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Und Jephthah sammelte alle Manner in Gilead und stritt wider Ephraim. Und die Manner in Gilead schlugen Ephraim, darum daß sie sagten: Seid doch ihr Gileaditer unter Ephraim und Manasse als die Fluchtigen zu Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Und die Gileaditer nahmen ein die Furt des Jordans vor Ephraim. Wenn nun sprachen die Fluchtigen Ephraims: Laß mich hinubergehen, so sprachen die Manner von Gilead zu ihm: Bist du ein Ephraiter? Wenn er dann antwortete: Nein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'so hießen sie ihn sprechen: Schiboleth, so sprach er: Siboleth, und konnte es nicht recht reden. So griffen sie ihn und schlugen ihn an der Furt des Jordans, daß zu der Zeit von Ephraim fielen zweiu ndvierzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jephthah aber richtete Israel sechs Jahre. Und Jephthah, der Gileaditer, starb und ward begraben in den Stadten zu Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Nach diesem richtete Israel Ebzan von Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Der hatte dreißig Sohne, und dreißig Tochter setzte er aus und dreißig Tochter nahm er von außen seinen Sohnen; und richtete Israel sieben Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Und starb und ward begraben zu Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Nach diesem richtete Israel Elon, ein Sebuloniter; und richtete Israel zehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Und starb und ward begraben zu Ajalon im Lande Sebulon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Nach diesem richtete Israel Abdon, ein Sohn Hillels, ein Pireathoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Der hatte vierzig Sohne und dreißig Neffen, die auf siebenzig Eselsfullen ritten; und richtete Israel acht Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Und starb und ward begraben zu Pireathon im Lande Ephraim auf dem Gebirge der Amalekiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Und die Kinder Israel taten furder übel vor dem HERRN, und der HERR gab sie in die Hande der Philister vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Es war aber ein Mann zu Zarea von einem Geschlecht der Daniter mit Namen Manoah; und sein Weib war unfruchtbar und gebar nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Und der Engel des HERRN erschien dem Weibe und sprach zu ihr: Siehe, du bist unfruchtbar und gebierest nichts; aber du wirst schwanger werden und einen Sohn gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'So hute dich nun, daß du nicht Wein noch stark Getranke trinkest und nichts Unreines essest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Denn du wirst schwanger werden und einen Sohn gebaren, dem kein Schermesser soil aufs Haupt kommen. Denn der Knabe wird ein Verlobter Gottes sein von Mutterleibe; und er wird anfahen, Israel zu erlosen aus der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Da kam das Weib und sagte es ihrem Manne an und sprach: Es kam ein Mann Gottes zu mir, und seine Gestalt war anzusehen wie ein Engel Gottes, fast erschrecklich, daß ich ihn nicht fragte, woher Oder wohin; und er sagte mir nicht, wie er hieße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Er sprach aber zu mir: Siehe, du wirst schwanger werden und einen Sohn gebaren. So trinke nun keinen Wein noch stark Getranke und iß nichts Unreines; denn der Knabe soil ein Verlobter Gottes sein von Mutterleibe an bis in seinen Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Da bat Manoah den HERRN und sprach: Ach, HERR, laß den Mann Gottes wieder zu uns kommen, den du gesandt hast, daß er uns lehre, was wir mit dem Knaben tun sollen, der geboren soil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Und Gott erhorete die Stimme Manoahs; und der Engel Gottes kam wieder zum Weibe. Sie saß aber auf dem Felde, und ihr Mann Manoah war nicht bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Da lief sie eilend und sagte es ihrem Marine an und sprach zu ihm: Siehe, der Mann ist mir erschienen, der heute zu mir kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoah machte sich auf und ging seinem Weibe nach; und kam zu dem Manne und sprach zu ihm: Bist du der Mann, der mit dem Weibe geredet hat? Er sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Und Manoah sprach: Wenn nun kommen wird, das du geredet hast, welches soil des Knaben Weise und Werk sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Der Engel des HERRN sprach zu Manoah: Er soil sich hüten vor allem, das ich dem Weibe gesagt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Er soli nicht essen, das aus dem Weinstock kommt, und soli keinen Wein noch stark Getranke trinken und nichts Unreines essen; alles, was ich ihr geboten habe, soli er halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manoah sprach zum Engel des HERRN: Lieber, lali dich halten, wir wollen dir ein Ziegenbocklein zurichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Aber der Engel des HERRN antwortete Manoah: Wenn du gleich mich hie haltst, esse ich doch deiner Speise nicht. Willst du aber dem HERRN ein Brandopfer tun, so magst du es opfern. Denn Manoah wulite nicht, daß es ein Engel des HERRN war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Und Manoah sprach zum Engel des HERRN: Wie heiliest du? daß wir dich preisen, wenn nun kommt, was du geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Aber der Engel des HERRN sprach zu ihm: Warum fragest du nach meinem Namen, der doch wundersam ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Da nahm Manoah ein Ziegenbocklein und Speisopfer und opferte es auf einem Fels dem HERRN. Und er machte es wunderbarlich. Manoah aber und sein Weib sahen zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Und da die Lohe auffuhr vom Altar gen Himmel, fuhr der Engel des HERRN in der Lohe des Altars hinauf. Da das Manoah und sein Weib sahen, fielen sie zur Erde auf ihr Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Und der Engel des HERRN erschien nicht mehr Manoah und seinem Weibe. Da erkannte Manoah, daß es ein Engel des HERRN war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Und sprach zu seinem Weibe: Wir müssen des Todes sterben, daß wir Gott gesehen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Aber sein Weib antwortete ihm: Wenn der HERR Lust hatte, uns zu toten, so hatte er das Brandopfer und Speisopfer nicht genommen von unsern Handen; er hatte uns auch nicht solches alles erzeiget, noch uns solches horen lassen, wie jetzt geschehen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Und das Weib gebar einen Sohn und hieü ihn Simson. Und der Knabe wuchs, und der HERR segnete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Und der Geist des HERRN fing an ihn zu treiben im Lager Dan, zwischen Zarea und Esthaol.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Simson ging hinab gen Thimnath und sah ein Weib zu Thimnath unter den Tochtern der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Und da er heraufkam, sagte er\'s an seinem Vater und seiner Mutter und sprach: Ich habe ein Weib gesehen zu Thimnath unter den Tochtern der Philister; gebet mir nun dieselbige zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Sein Vater und seine Mutter sprachen zu ihm: Ist denn nun kein Weib unter den Tochtern deiner Bruder und in all deinem Volk, daß du hingehest und nimmst ein Weib bei den Philistern, die unbeschnitten sind? Simson sprach zu seinem Vater: Gib mir diese, denn sie gefallt meinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Aber sein Vater und seine Mutter wuliten nicht, daß es von dem HERRN ware; denn er suchte Ursache an die Philister. Die Philister aber herrscheten zu der Zeit uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Also ging Simson hinab mit seinem Vater und seiner Mutter gen Thimnath. Und als sie kamen an die Weinberge zu Thimnath, siehe, da kam ein junger Lowe brullend ihm entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Und der Geist des HERRN geriet fiber ihn; und zerrüi ihn, wie man ein Bocklein zerreiliet, und hatte doch gar nichts in seiner Hand. Und sagte es nicht an seinem Vater noch seiner Mutter, was er getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Da er nun hinabkam, redete er mit dem Weibe, und sie gefiel Simson in seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Und nach etlichen Tagen kam erwieder, dafi er sie nahme; und trat aus dem Wege, daß er das Aas des Lowen besahe. Siehe, da war ein Bienenschwarm in dem Aas des Lowen und Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Und er nahm\'s in seine Hand und ali davon unterwegen; und ging zu seinem Vater und zu seiner Mutter und gab ihnen, daß sie auch alien. Er sagte ihnen aber nicht an, daß er den Honig von des Lowen Aas genommen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Und da sein Vater hinabkam zu dem Weibe, machte Simson daselbst eine Hochzeit, wie die Junglinge zu tun pflegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Und da sie ihn sahen, gaben sie ihm dreilüg Gesellen zu, die bei ihm sein sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Simson aber sprach zu ihnen: Ich will euch ein Ratsel aufgeben. Wenn ihr mir das erratet und treffet diese sieben Tage der Hochzeit, so will ich euch dreilüg Hemden geben und dreilüg Feierkleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Konnet ihr\'s aber nicht erraten, so sollt ihr mir dreilüg Hemden und dreilüg Feierkleider geben. Und sie sprachen zu ihm: Gib dein Ratsel auf, lali uns horen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Er sprach zu ihnen: Speise ging von dem Fresser und Sulügkeit von dem Starken. Und sie konnten in dreien Tagen das Ratsel nicht erraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Am siebenten Tage sprachen sie zu Simsons Weibe: Uberrede deinen Mann, dafi er uns sage das Ratsel, Oder wir werden dich und deines Vaters Haus mit Feuer verbrennen. Habt ihr uns hieher geladen, daß ihr uns arm machet, Oder nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Da weinete Simsons Weib vor ihm und sprach: Du bist mir gram und hast mich nicht lieb. Du hast den Kindern meines Volks ein Ratsel aufgegeben und hast mir\'s nicht gesagt. Er aber sprach zu ihr: Siehe, ich habe es meinem Vater und meiner Mutter nicht gesagt und sollte dir\'s sagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Und sie weinete die sieben Tage vor ihm, weil sie Hochzeit hatten. Aber am siebenten Tage sagte er\'s ihr, denn sie trieb ihn ein. Und sie sagte das Ratsel ihres Volks Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Da sprachen die Manner der Stadt zu ihm am siebenten Tage, ehe die Sonne unterging: Was ist suffer denn Honig? Was ist starker denn der Lowe? Aber er sprach zu ihnen: Wenn ihr nicht hattet mit meinem Kalbe gepfluget, ihr hattet mein Ratsel nicht getroffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Und der Geist des HERRN geriet uber ihn; und ging hinab gen Asklon und schlug dreifüg Mann unter ihnen; und nahm ihr Gewand und gab Feierkleider denen, die das Ratsel erraten hatten. Und ergrimmete in seinem Zorn und ging herauf in seines Vaters Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Aber Simsons Weib ward einem seiner Gesellen gegeben, der ihm zugehorte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Es begab sich aber nach etlichen Tagen, urn die Weizenernte, dad Simson sein Weib besuchte mit einem Ziegenbocklein. Und als er gedachte, ich will zu meinem Weibe gehen in die Kammer, wollte ihn ihr Vater nicht hineinlassen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'und sprach: Ich meinte, du warest ihr gram worden, und habe sie deinem Freunde gegeben. Sie hat aber eine jungere Schwester, die ist schoner denn sie; die lad dein sein fur diese.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Da sprach Simson zu ihnen: Ich habe einmal eine rechte Sache wider die Philister; ich will euch Schaden tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Und Simson ging hin und fing dreihundert Fuchse; und nahm Brande und kehrete je einen Schwanz zum andern und tat einen Brand je zwischen zween Schwanze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Und zundete die an mit Feuer und lied sie unter das Korn der Philister; und zundete also an die Mandeln samt dem stehenden Korn und Weinberge und Olbaume.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Da sprachen die Philister: Wer hat das getan? Da sagte man: Simson, der Eidam des Thimniters, darum dad er ihm sein Weib genommen und seinem Freunde gegeben hat. Da zogen die Philister hinauf und verbrannten sie samt ihrem Vater mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Simson aber sprach zu ihnen: Ob ihrschon das getan habt, doch will ich mich an euch selbst rachen und danach aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Und schlug sie hart, beide an Schultern und Lenden. Und zog hinab und wohnete in der Steinkluft zu Etam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Da zogen die Philister hinauf und belagerten Juda und lieden sich nieder zu Lehi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Aber die von Juda sprachen: Warum seid ihr wider uns heraufgezogen? Sie antworteten: Wir sind heraufkommen, Simson zu binden, dad wir ihm tun, wie er uns getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Da zogen dreitausend Mann von Juda hinab in die Steinkluft zu Etam und sprachen zu Simson: Weidt du nicht, dad die Philister fiber uns herrschen? Warum hast du denn das an uns getan? Er sprach zu ihnen: Wie sie mir getan haben, so habe ich ihnen wieder getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Sie sprachen zu ihm: Wir sind herabkommen, dich zu binden und in der Philister Hande zu geben. Simson sprach zu ihnen: So schworet mir, dad ihr mir nicht wehren wollet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Sie antworteten ihm: Wirwollen dir nicht wehren, sondern wollen dich nur binden und in ihre Hande geben und wollen dich nicht toten. Und sie banden ihn mit zween neuen Stricken und fuhreten ihn herauf vom Felsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Und da er kam bis gen Lehi, jauchzeten die Philister zu ihm zu. Aber der Geist des HERRN geriet uber ihn, und die Stricke an seinen Armen wurden wie Faden, die das Feuer versenget hat, dad die Bande an seinen Handen zerschmolzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Und erfand einen faulen Eselskinnbacken; da reckte er seine Hand aus und nahm ihn und schlug damit tausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Und Simson sprach: Da liegen sie bei Haufen; durch eines Esels Kinnbacken habe ich tausend Mann geschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Und da er das ausgeredet hatte, warf er den Kinnbacken aus seiner Hand und hied die Statte Ramath-Lehi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Da ihn aber sehr durstete, rieferden HERRN an und sprach: Du hast solch grod Heil gegeben durch die Hand deines Knechts; nun aber mud ich Durstes sterben und in der Unbeschnittenen Hande fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Da spaltete Gott einen Backenzahn in dem Kinnbacken, dad Wasser heraus ging. Und als er trank, kam sein Geist wieder und ward erquicket. Darum heidt er noch heutigestages des Anrufers Brunnen, der im Kinnbacken ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Und er richtete Israel zu der Philister Zeit zwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Simson ging hin gen Gasa und sah daselbst eine Hure und lag bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Da ward den Gasitern gesagt: Simson ist hereinkommen. Und sie umgaben ihn und lieden auf ihn lauern die ganze Nacht in der Stadt Tor; und waren die ganze Nacht stille und sprachen: Harre! Morgen, wenn es licht wird, wollen wir ihn erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Simson aber lag bis zu Mitternacht. Da stund er auf zu Mitternacht und ergriff beide Türen an der Stadt Tor samt den beiden Pfosten und hub sie aus mit den Riegeln; und legte sie auf seine Schultern und trug sie hinauf auf die Hohe des Berges vor Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Danach gewann er ein Weib lieb am Bach Sorek, die hieli Delila.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Zu der kamen der Philister Fursten hinauf und sprachen zu ihr: Uberrede ihn und besiehe, worinnen er solche grolie Kraft hat, und womit wir ihn ubermogen, daß wir ihn binden und zwingen, so wollen wir dir geben ein jeglicher tausend und hundert Silberlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Und Delila sprach zu Simson: Lieber, sage mir, worinnen deine grolie Kraft sei, und womit man dich binden moge, daß man dich zwinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson sprach zu ihr: Wenn man mich bande mit sieben Seilen von frischem Bast, die noch nicht verdorret sind, so würde ich schwach und ware wie ein anderer Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Da brachten der Philister Fursten zu ihr hinauf sieben Seile von frischem Bast, die noch nicht verdorret waren; und sie band ihn damit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, '(Man hielt aber auf ihn bei ihr in der Kammer.) Und sie sprach zu ihm: Die Philister uber dir, Simson! Er aber zerrili die Seile, wie eine flachserne Schnur zerreifiet, wenn sie ans Feuer reucht; und war nicht kund, wo seine Kraft ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Da sprach Delila zu Simson: Siehe, du hast mich getauscht und mir gelogen; nun, so sage mir doch, womit kann man dich binden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Erantwortete ihr: Wenn sie mich banden mit neuen Stricken, damit nie keine Arbeit geschehen ist, so würde ich schwach und wie ein anderer Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Da nahm Delila neue Stricke und band ihn damit und sprach: Philister uber dir, Simson! (Man hielt aber auf ihn in der Kammer.) Und er zerrifi sie von seinen Armen wie einen Faden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Delila aber sprach zu ihm: Noch hastdu mich getauscht und mir gelogen. Lieber, sage mir doch, womit kann man dich binden? Er antwortete ihr: Wenn du sieben Locken meines Haupts flochtest mit einem Flechtbande und heftetest sie mit einem Nagel ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Und sie sprach zu ihm: Philister uber dir, Simson! Er aber wachte auf von seinem Schlaf und zog die geflochtenen Locken mit Nagel und Flechtband heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Da sprach sie zu ihm: Wie kannstdu sagen, du habest mich lieb, so dein Herz doch nicht mit mir ist? Dreimal hast du mich getauscht und mir nicht gesagt, worinnen deine grofie Kraft sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Da sie ihn aber trieb mit ihren Worten alle Tage und zerplagte ihn, ward seine Seele matt bis an den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Und sagte ihrsein ganzes Herz und sprach zu ihr: Es ist nie kein Schermesser auf mein Haupt kommen; denn ich bin ein Verlobter Gottes von Mutterleibe an. Wenn du mich beschorest, so wiche meine Kraft von mir, daß ich schwach würde und wie alle andern Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Da nun Delila sah, daß er ihr all sein Herz offenbaret hatte, sandte sie hin und liefi der Philister Fursten rufen und sagen: Kommt noch einmal herauf, denn er hat mir all sein Herz offenbaret. Da kamen der Philister Fursten zu ihr herauf und brachten das Geld mit sich in ihrer Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Und sie liefi ihn entschlafen auf ihrem Scholi und rief einem, der ihm die sieben Locken seines Hauptes abschore. Und sie fing an ihn zu zwingen. Da war seine Kraft von ihm gewichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Und sie sprach zu ihm: Philister uber dir, Simson! Da er nun von seinem Schlaf erwachte, gedachte er: Ich will ausgehen, wie ich mehrmals getan habe, ich will mich ausreilien; und wulite nicht, daß der HERR von ihm gewichen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Aber die Philister griffen ihn und stachen ihm die Augen aus; und führeten ihn hinab gen Gasa und banden ihn mit zwo ehernen Ketten; und er mufite mahlen im Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Aber das Haar seines Haupts fing an wieder zu wachsen, wo es beschoren war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Da aber der Philister Fursten sich versammelten, ihrem Gott Dagon ein grofi Opfer zu tun und sich zu freuen, sprachen sie: Unser Gott hat uns unsern Feind Simson in unsere Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Desselbengleichen, als ihn das Volk sah, lobten sie ihren Gott; denn sie sprachen: Unser Gott hat uns unsern Feind in unsere Hande gegeben, der unser Land verderbete und unser viel erschlug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Da nun ihr Herz guter Dinge war, sprachen sie: Lasset Simson holen, daß er vor uns spiele. Da holeten sie Simson aus dem Gefangnis, und er spielete vor ihnen; und sie stelleten ihn zwischen zwo Saulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Simson aber sprach zu dem Knaben, der ihn bei der Hand leitete: Lali mich, daß ich die Saulen taste, auf welchen das Haus stehet, daß ich mich dran lehne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Das Haus aber war voll Manner und Weiber. Es waren auch der Philister Fursten alle da und auf dem Dach bei dreitausend, Mann und Weib, die zusahen, wie Simson spielete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Simson aber rief den HERRN an und sprach: Herr, HERR, gedenke mein und starke mich doch, Gott, diesmal, daß ich fur meine beiden Augen mich einst rache an den Philistern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Und er fassete die zwo Mittelsaulen, auf welchen das Haus gesetzt war und drauf sich hielt, eine in seine rechte und die andere in seine linke Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'und sprach: Meine Seele sterbe mit den Philistern; und neigete sie kraftiglich. Da fiel das Haus auf die Fursten und auf alles Volk, das drinnen war, daß der Toten mehr war, die in seinem Tode starben, denn die bei seinem Leben starben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Da kamen seine Bruder hernieder und seines Vaters ganzes Haus und huben ihn auf und trugen ihn hinauf und begruben ihn in seines Vaters Manoah Grab, zwischen Zarea und Esthaol. Er richtete aber Israel zwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Eswaraberein Mann aufdem Gebirge Ephraim mit Namen Micha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Der sprach zu seiner Mutter: Die tausend und hundert Silberlinge, die du zu dir genommen hast und geschworen und gesagt vor meinen Ohren, siehe, dasselbe Geld ist bei mir, ich hab\'s zu mir genommen. Da sprach seine Mutter: Gesegnet sei mein Sohn dem HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Also gab er seiner Mutter die tausend und hundert Silberlinge wieder. Und seine Mutter sprach: Ich habe das Geld dem HERRN geheiliget von meiner Hand fur meinen Sohn, dafi man ein Bildnis und Abgott machen soil; darum so gebe ich\'s dir nun wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Aber er gab seiner Mutter das Geld wieder. Da nahm seine Mutter zweihundert Silberlinge und tatsie zu dem Goldschmied; der machte ihr ein Bild und Abgott, das war danach im Hause Michas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Und der Mann Micha hatte also ein Gotteshaus und machte einen Leibrock und Heiligtum; und fullete seiner Sohne einem die Hand, daü er sein Priester ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Zu der Zeit war kein Konig in Israel, und ein jeglicher tat, was ihn recht deuchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Es war aber ein Jungling von Bethlehem-Juda unter dem Geschlecht Judas; und er war ein Levit und war fremd daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Er zog aber aus der Stadt Bethlehem-Juda, zu wandern, wo er hin konnte. Und da er aufs Gebirge Ephraim kam zum Hause Michas, dad er seinen Weg ginge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'fragte ihn Micha: Wo kommst du her? Er antwortete ihm: Ich bin ein Levit von Bethlehem-Juda und wandere, wo ich hin kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Micha sprach zu ihm: Bleibe bei mir, du sollst mein Vater und mein Priester sein; ich will dir jahrlich zehn Silberlinge und benannte Kleider und deine Nahrung geben. Und der Levit ging hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Der Levit trat an, zu bleiben bei dem Mann; und er hielt den Knaben gleichwie einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Und Micha fullete dem Leviten die Hand, dad er sein Priester ward; und war also im Hause Michas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Und Micha sprach: Nun weid ich, dad mir der HERR wird wohltun, weil ich einen Leviten zum Priester habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Zu der Zeit war kein Konig in Israel. Und der Stamm der Daniter suchte ihm ein Erbteil, da sie wohnen mdchten; denn es war bis auf den Tag noch kein Erbe fur sie gefallen unter den Stammen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Und die Kinder Dan sandten aus ihren Geschlechtern von ihren Enden funf streitbare Manner von Zarea und Esthaol, das Land zu erkunden und zu erforschen, und sprachen zu ihnen: Ziehet hin und erforschet das Land. Und sie kamen auf das Gebirge Ephraim, ans Haus Michas, und blieben uber Nacht daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Und weil sie da bei dem Gesinde Michas waren, kannten sie die Stimme des Knaben, des Leviten; und sie wichen dahin und sprachen zu ihm: Wer hat dich hieher qebracht? Was machst du da und was hast du hie?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Er antwortete ihnen: So und so hat Micha an mir getan und hat mich gedinget, daü ich sein Priester sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Sie sprachen zu ihm: Lieber, frage Gott, dafi wir erfahren, ob unser Weg, den wirwandein, auch wohlgeraten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Der Priester antwortete ihnen: Ziehet hin mit Frieden; euer Weg ist recht vor dem HERRN, den ihr ziehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Da gingen die funf Manner hin und kamen gen Lais und sahen das Volk, das drinnen war, sicher wohnen, auf die Weise wie die Zidonier, stille und sicher; und war niemand, der ihnen Leid tate im Lande, Oder Herr uber sie ware; und waren feme von den Zidoniern und hatten nichts mit Leuten zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Und sie kamen zu ihren Brudern gen Zarea und Esthaol; und ihre Bruder sprachen zu ihnen: Wie stehet\'s mit euch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Sie sprachen: Auf, lafit uns zu ihnen hinaufziehen; denn wir haben das Land besehen, das ist fast gut. Darum eilet und seid nicht faul zu ziehen, daß ihr kommet, das Land einzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Wenn ihr kommet, werdet ihrzu einem sichern Volk kommen; und das Land ist weit und breit, denn Gott hat es in eure Hande gegeben, einen solchen Ort, da nichts gebricht, alles, das auf Erden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Da zogen von dannen aus den Geschlechtern Dan, von Zarea und Esthaol, sechshundert Mann gerustet mit ihren Waffen zum Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Und zogen hinauf und lagerten sich zu Kiriath- Jearim in Juda. Daher nannten sie die Statte das Lager Dan bis auf diesen Tag, das hinter Kiriath- Jearim ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Und von dannen gingen sie auf das Gebirge Ephraim und kamen zum Hause Michas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Da antworteten die funf Manner, die ausgegangen waren, das Land Lais zu erkunden, und sprachen zu ihren Brudern: Wisset ihr auch, dafi in diesen Hausern ein Leibrock, Heiligtum, Bildnis und Abgott sind? Nun moget ihr denken, was euch zu tun ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Sie kehreten da ein und kamen an das Haus des Knaben, des Leviten, in Michas Hause und grufiten ihn freundlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Aber die sechshundert Gerusteten mit ihrem Harnisch, die von den Kindern Dan waren, stunden vor dem Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Und die funf Manner, die das Land zu erkunden ausgezogen waren, gingen hinauf und kamen dahin; und nahmen das Bild, den Leibrock, das Heiligtum und Abgott. Dieweil stund der Priester vor dem Tor bei den sechshundert Gerusteten mit ihrem Harnisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Als nun jene ins Haus Michas kommen waren und nahmen das Bild, den Leibrock, das Heiligtum und Abgott, sprach der Priester zu ihnen: Was machet ihr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Sie antworteten ihm: Schweig und halte das Maul zu und zeuch mit uns, daß du unser Vater und Priester seiest. 1st dir\'s besser, daß du in des einigen Mannes Hause Priester seiest, Oder unter einem ganzen Stamm und Geschlecht in Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Dasgefiel dem Priester wohl, und nahm beide den Leibrock, das Heiligtum und Bild und kam mit unter das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Und da sie sich wandten und hinzogen, schickten sie die Kindlein und das Vieh und was sie Kostliches hatten, vor ihnen her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Da sie nun feme von Michas Haus kamen, schrieen die Manner, so in den Hausern waren bei Michas Hause, und folgten den Kindern Dan nach und riefen den Kindern Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Sie aber wandten ihr Antlitz urn und sprachen zu Micha: Was ist dir, daß du also ein Geschrei machest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Er antwortete: Ihr habt meine Gotter genommen, die ich gemacht hatte, und den Priester und ziehet hin, und was habe ich nun mehr? Und ihr fraget noch, was mirfehle?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Aber die Kinder Dan sprachen zu ihm: Lall deine Stimme nicht horen bei uns, dafi nicht auf dich stolen zornige Leute, und deine Seele und deines Hauses Seele nicht aufgeraumet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Also gingen die Kinder Dan ihres Weges. Und Micha, da er sah, daß sie ihm zu stark waren, wandte er sich und kam wieder zu seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Sie aber nahmen, das Micha gemacht hatte, und den Priester, den er hatte, und kamen an Lais, an ein still, sicher Volk, und schlugen sie mit der Scharfe des Schwerts und verbrannten die Stadt mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Und war niemand, der sie errettete, denn sie lag feme von Zidon, und hatten mit den Leuten nichts zu schaffen; und sie lag im Grunde, welcher an Beth- Rehob liegt. Da baueten sie die Stadt und wohneten drinnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'und nannten sie Dan nach dem Namen ihres Vaters Dan, der von Israel geboren war. Und die Stadt hieli vorzeiten Lais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Und die Kinder Dan richteten fur sich auf das Bild. Und Jonathan, der Sohn Gersons, des Sohns Manasses, und seine Sohne waren Priester unter dem Stamm der Daniter bis an die Zeit, da sie aus dem Lande gefangen gefuhret worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Und setzten also unter sich das Bild Michas, das er gemacht hatte, so lange, als das Haus Gottes war zu Silo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Zu der Zeit war kein Konig in Israel. Und ein levitischer Mann war Fremdling an der Seite des Gebirges Ephraim und hatte ihm ein Kebsweib zum Weibe genommen von Bethlehem-Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Und da sie hatte neben ihm gehuret, lief sie von ihm zu ihres Vaters Hause gen Bethlehem-Juda und war daselbst vier Monden lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Und ihr Mann machte sich auf und zog ihr nach, daß er freundlich mit ihr redete und sie wieder zu sich holete; und hatte einen Knaben und ein Paar Esel mit sich. Und sie fuhrete ihn in ihres Vaters Haus. Da ihn aber der Dime Vater sah, ward er froh und empfing ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Und sein Schwaher, der Dime Vater, hielt ihn, daß er drei Tage bei ihm blieb; alien und tranken und blieben des Nachts da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Des vierten Tages machten sie sich des Morgens fruhe auf; und er stund auf und wollte ziehen. Da sprach der Dime Vater zu seinem Eidam: Labe dein Herz zuvor mit einem Bissen Brots, danach sollt ihr ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Und sie setzen sich und alien beide miteinander und tranken. Da sprach der Dime Vater zu dem Mann: Lieber, bleib uber Nacht und lali dein Herz guter Dinge sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Da aber der Mann aufstund und wollte ziehen, notigte ihn sein Schwaher, daß er uber Nacht da blieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Des Morgens am funften Tage machte er sich fruh auf und wollte ziehen. Da sprach der Dime Vater: Lieber, labe dein Herz und lali uns verziehen, bis sich der Tag neiget. Und alien also die beiden miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Und der Mann machte sich auf und wollte ziehen mit seinem Kebsweibe und mit seinem Knaben. Aber sein Schwaher, der Dime Vater, sprach zu ihm: Siehe, der Tag lalit ab, und will Abend werden; bleib uber Nacht. Siehe, hie ist Herberge noch diesen Tag; bleib hie uber Nacht und lali dein Herz guter Dinge sein; morgen so stehet ihr fruh auf und ziehet eures Weges zu deiner Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Aber der Mann wollte nicht uber Nacht bleiben, sondern machte sich auf und zog hin und kam bis vor Jebus, das ist, Jerusalem, und sein Paar Esel beladen, und sein Kebsweib mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Da sie nun bei Jebus kamen, fiel der Tag fast dahin. Und der Knabe sprach zu seinem Herm: Lieber, zeuch und lali uns in diese Stadt der Jebusiter einkehren und uber Nacht drinnen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Aber sein Herr sprach zu ihm: Wirwollen nicht in der Fremden Stadt einkehren, die nicht sind von den Kindern Israel, sondern wollen hinuber gen Gibea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Und sprach zu seinem Knaben: Gehe fort, daß wir hinzukommen an einen Ort und uber Nacht zu Gibea Oder zu Rama bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Und sie zogen fort und wandelten, und die Sonne ging ihnen unter hart bei Gibea, die da liegt unter Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Und sie kehreten daselbst ein, daß sie hineinkamen und uber Nacht zu Gibea blieben. Da er aber hineinkam, setzte er sich in der Stadt Gasse; denn es war niemand, der sie die Nacht im Hause herbergen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Und siehe, da kam ein alter Mann von seiner Arbeit vom Felde am Abend; und er war auch vom Gebirge Ephraim und ein Fremdling zu Gibea; aber die Leute des Orts waren Kinder Jemini.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Und da er seine Augen aufhub und sah den Gast auf der Gasse, sprach er zu ihm: Wo willst du hin? und wo kommst du her?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Er aber antwortete ihm: Wir reisen von Bethlehem-Juda, bis wir kommen an die Seite des Gebirges Ephraim, daher ich bin; und bin gen Bethlehem-Juda gezogen und ziehe jetzt zum Hause des HERRN, und niemand will mich herbergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Wirhaben Stroh und Futter fur unsere Esel und Brat und Wein fur mich und deine Magd und fur den Knaben, der mit deinem Knechte ist, daß uns nichts gebricht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Der alte Mann sprach: Friede sei mit dir! Alles, was dir mangelt, findest du bei mir; bleibe nur nicht uber Nacht auf der Gasse!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Und fuhrete ihn in sein Haus und gab den Eseln Futter; und sie wuschen ihre Fülie und alien und tranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Und da ihr Herz nun guter Dinge war, siehe, da kamen die Leute der Stadt, bose Buben, und umgaben das Haus und pochten an die Tur und sprachen zu dem alten Manne, dem Hauswirt: Bringe den Mann heraus, der in dein Haus kommen ist, daß wir ihn erkennen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Aber der Mann, der Hauswirt, ging zu ihnen heraus und sprach zu ihnen: Nicht, meine Bruder, tut nicht so übel, nachdem dieser Mann in mein Haus kommen ist; tut nicht eine solche Torheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Siehe, ich habe eine Tochter, noch eine Jungfrau, und dieser ein Kebsweib; die will ich euch herausbringen, die moget ihrzuschanden machen und tut mit ihnen, was euch gefallt; aber an diesem Manne tut nicht eine solche Torheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Aber die Leute wollten ihm nicht gehorchen. Da fassete der Mann sein Kebsweib und brachte sie zu ihnen hinaus. Die erkannten sie und zerarbeiteten sich die ganze Nacht bis an den Morgen; und da die Morgenrote anbrach, lielien sie sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Da kam das Weib hart vor Morgens und fiel nieder vor der Tur am Hause des Mannes, da ihr Herr innen war, und lag da, bis es licht ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Da nun ihr Herr des Morgens aufstund und die Tur auftat am Hause und herausging, dais er seines Weges zoge, siehe, da lag sein Kebsweib vor der Tor des Hauses und ihre Hande auf der Schwelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Er aber sprach zu ihr: Stehe auf, lal J uns ziehen! Aber sie antwortete nicht. Da nahm er sie auf den Esel, machte sich auf und zog an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Als er nun heimkam, nahm er ein Messer und fassete sein Kebsweib und stockte sie mit Bein und mit allem in zwolf Stücke und sandte sie in alle Grenzen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Wer das sah, der sprach: Solches ist nicht geschehen noch gesehen, seit der Zeit die Kinder Israel aus Agyptenland gezogen sind, bis auf diesen Tag. Nun bedenket euch uber dem und gebet Rat und saget an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Da zogen die Kinder Israel aus und versammelten sich zuhauf wie ein Mann, von Dan bis gen Berseba und vom Lande Gilead, zu dem HERRN gen Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Und traten zuhauf die Obersten des ganzen Volks aller Stamme Israels in der Gemeine Gottes, vierhunderttausend Mann zu Fuß, die das Schwert auszogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Aber die Kinder Benjamin horeten, daß die Kinder Israel hinauf gen Mizpa gezogen waren. Und die Kinder Israel sprachen: Saget, wie ist das Ubel zugegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Da antwortete der Levit, des Weibes Mann, die erwurget war, und sprach: Ich kam gen Gibea in Benjamin mit meinem Kebsweibe, uber Nacht dazubleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Da machten sich wider mich auf die Burger zu Gibea und umgaben mich im Hause des Nachts und gedachten mich zu erwürgen; und haben mein Kebsweib geschandet, daß sie gestorben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Da fassete ich mein Kebsweib und zerstückte sie und sandte es in alle Felder des Erbes Israels; denn sie haben einen Mutwillen und Torheit getan in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Siehe, da seid ihr Kinder Israel alle; schaffet euch Rat und tut hiezu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Da machte sich alles Volk auf wie ein Mann und sprach: Es soil niemand in seine Hütte gehen noch in sein Haus kehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'sondern das wollen wir jetzt tun wider Gibea:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Lasset uns losen und nehmen zehn Mann von hundert und hundert von tausend und tausend von zehntausend aus alien Stammen Israels, daß sie Speise nehmen fur das Volk, daß sie kommen und tun mit Gibea-Benjamin nach all ihrer Torheit, die sie in Israel getan haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Also versammelten sich zu der Stadt alle Manner Israels wie ein Mann und verbanden sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Und die Stamme Israels sandten Manner zu alien Geschlechtern Benjamins und lielien ihnen sagen: Was ist das fur eine Bosheit, die bei euch geschehen ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'So gebet nun her die Manner, die bosen Buben zu Gibea, daü wir sie toten und das Ubel aus Israel tun. Aber die Kinder Benjamin wollten nicht gehorchen der Stimme ihrer Bruder, der Kinder Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'sondern sie versammelten sich aus den Stadten gen Gibea, auszuziehen in den Streit wider die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Und wurden des Tages gezahlet die Kinder Benjamin aus den Stadten sechsundzwanzigtausend Mann, die das Schwert auszogen, ohne die Burger zu Gibea, deren wurden siebenhundert gezahlet, auserlesene Manner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Und unterall diesem Volkwaren siebenhundert Mann auserlesen, die link waren und konnten mit der Schleuder ein Haar treffen, dafi sie nicht fehleten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Aberderervon Israel (ohne die von Benjamin) wurden gezahlet vierhunderttausend Mann, die das Schwert fuhreten, und alle streitbare Manner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Die machten sich auf und zogen hinauf zum Hause Gottes; und fragten Gott und sprachen: Wer soil vor uns hinaufziehen, den Streit anzufahen mit den Kindern Benjamin? Der HERR sprach: Juda soil anfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Also machten sich die Kinder Israel des Morgens auf und lagerten sich vor Gibea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Und ein jedermann von Israel ging heraus, zu streiten mit Benjamin, und schickten sich, zu streiten wider Gibea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Da fielen die Kinder Benjamin heraus aus Gibea und schlugen des Tages unter Israel zweiundzwanzigtausend zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Aber das Volk, der Mann von Israel, ermannete sich, und rusteten sich, noch weiterzu streiten am selben Ort, da sie sich des vorigen Tages gerustet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Und die Kinder Israel zogen hinauf und weineten vor dem HERRN bis an den Abend; und fragten den HERRN und sprachen: Sollen wir mehr nahen, zu streiten mit den Kindern Benjamin, unsern Brudern? Der HERR sprach: Ziehet hinauf zu ihnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Und da die Kinder Israel sich machten an die Kinder Benjamin des andern Tages,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'fielen die Benjaminiter heraus aus Gibea ihnen entgegen desselben Tages und schlugen von den Kindern Israel noch achtzehntausend zu Boden, die alle das Schwert fuhreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Da zogen alle Kinder Israel hinauf und alles Volk und kamen zum Hause Gottes und weineten; und blieben daselbst vor dem HERRN und fasteten den Tag bis zum Abend; und opferten Brandopfer und Dankopfer vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Und die Kinder Israel fragten den HERRN (es war aber daselbst die Lade des Bundes Gottes zu derselbigen Zeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'und Pinehas, der Sohn Eleasars, Aarons Sohn, stund vorihm zu derselbigen Zeit) und sprachen: Sollen wir mehr ausziehen, zu streiten mit den Kindern Benjamin, unsern Brudern, Oder soil ich ablassen? Der HERR sprach: Ziehet hinauf; morgen will ich sie in eure Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Und die Kinder Israel bestelleten einen Hinterhalt auf Gibea umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Und zogen also die Kinder Israel hinauf des dritten Tages an die Kinder Benjamin und rusteten sich an Gibea wie zuvor zweimal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Da fuhren die Kinder Benjamin heraus dem Volk entgegen und rissen sich von der Stadt und fingen an zu schlagen und zu verwunden vom Volk, wie zuvor zweimal, im Felde auf zwo Strafien, deren eine gen Bethel, die andere gen Gibea gehet, bei dreißig Mann in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Da gedachten die Kinder Benjamin: Sie sind geschlagen vor uns, wie vorhin. Aber die Kinder Israel sprachen: Lalit uns fliehen, dafi wir sie von der Stadt reifien auf die Stralie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Da machten sich auf alle Manner von Israel von ihrem Ort und rusteten sich zu Baal-Thamar. Und der Hinterhalt Israels brach hervor an seinem Ort von der Hohle Gaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Und kamen gen Gibea zehntausend Mann, auserlesen aus ganzem Israel, dafi der Streit hart ward; sie wußten aber nicht, dafi sie das Unglück treffen wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Also schlug der HERR Benjamin vor den Kindern Israel, daß die Kinder Israel auf den Tag verderbeten fünfundzwanzigtausend und hundert Mann in Benjamin, die alle das Schwert fuhreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Denn da die Kinder Benjamin sahen, dal J sie geschlagen waren, gaben ihnen die Manner Israel Raum; denn sie verliefien sich auf den Hinterhalt, den sie bei Gibea bestellet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Und der Hinterhalt eilete auch und brach hervor zu Gibea zu; und zog sich hinan und schlug die ganze Stadt mit der Scharfe des Schwerts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Sie hatten aber eine Losung miteinander, die Manner von Israel und der Hinterhalt, mit dem Schwert fiber sie zu fallen, wenn der Rauch von der Stadt sich erhübe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Da nun die Manner von Israel sich wandten im Streit, und Benjamin anfing zu schlagen, und verwundeten in Israel bei dreilüg Mann und gedachten, sie sind vor uns geschlagen, wie im vorigen Streit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'da fing an sich zu erheben von der Stadt ein Rauch stracks fiber sich. Und Benjamin wandte sich hinter sich, und siehe, da ging die Stadt ganz auf gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Und die Manner von Israel wandten sich auch urn und erschreckten die Manner Benjamins; denn sie sahen, dafi sie das Unglück treffen wollte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'und wandten sich vor den Mannern Israels auf den Weg zur Wüste. Aber der Streit folgte ihnen nach; dazu die von den Stadten hineinkommen waren, die verderbeten sie drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Und sie umringten Benjamin und jagten ihm nach bis gen Menuah und zertraten sie bis vor Gibea, gegen der Sonnen Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Und es fielen von Benjamin achtzehntausend Mann, die alle streitbare Manner waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Da wandten sie sich und flohen zu der Wüste, an den Fels Rimmon; aberauf derselben Strafte schlugen sie funftausend Mann; und folgten ihnen hinten nach bis gen Gideom und schlugen ihrer zweitausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Und also fielen des Tages von Benjamin fünfundzwanzigtausend Mann, die das Schwert führeten und alle streitbare Manner waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Nur sechshundert Mann wandten sich und flohen zur Wüste zum Fels Rimmon; und blieben im Fels Rimmon vier Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Und die Manner Israels kamen wieder zu den Kindern Benjamin und schlugen mit der Scharfe des Schwerts die in der Stadt, beide Leute und Vieh und alles, was man fand; und alle Stadte, die man fand, verbrannte man mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Die Manner aber Israels hatten zu Mizpa geschworen und gesagt: Niemand soil seine Tochter den Benjaminitern zum Weibe geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Und das Volk kam zu dem Hause Gottes und blieb da bis zu Abend vor Gott; und huben auf ihre Stimme und weineten sehr');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'und sprachen: 0 HERR, Gott von Israel, warum istdas geschehen in Israel, daß heute eines Stammes von Israel weniger worden ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Des andern Morgens machte sich das Volk frühe auf und bauete da einen Altar und opferten Brandopfer und Dankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Und die Kinder Israel sprachen: Wer ist irgend von den Stammen Israels, der nicht mit der Gemeine ist heraufkommen zum HERRN? Denn es war ein grofter Eid geschehen, daß, wer nicht hinaufkame zum HERRN gen Mizpa, der sollte des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Und es reuete die Kinder Israel uber Benjamin, ihre Bruder, und sprachen: Heute ist ein Stamm von Israel abgebrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Wie wollen wir ihnen tun, daß die ubrigen Weiber kriegen? Denn wir haben geschworen bei dem HERRN, daß wir ihnen von unsern Tochtern nicht Weiber geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Und sprachen: Wer ist irgend von den Stammen Israels, die nicht hinaufkommen sind zum HERRN gen Mizpa? Und siehe, da war niemand gewesen im Lager der Gemeine von Jabes in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Denn sie zahleten das Volk, und siehe, da war kein Burger da von Jabes in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Da sandte die Gemeine zwolftausend Mann dahin von streitbaren Mannern; und geboten ihnen und sprachen: Gehet hin und schlaget mit der Scharfe des Schwerts die Burger zu Jabes in Gilead mit Weib und Kind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Doch also sollt ihrtun: Alles, was mannlich ist, und alle Weiber, die beim Mann gelegen sind, verbannet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Und siefanden bei den Burgern zu Jabes in Gilead vierhundert Dirnen, die Jungfrauen und bei keinem Mann gelegen waren. Die brachten sie ins Lager gen Silo, die da liegt im Lande Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Da sandte die ganze Gemeine hin und lieft reden mit den Kindern Benjamin, die im Fels Rimmon waren, und riefen ihnen friedlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Also kamen die Kinder Benjamin wieder zu derselbigen Zeit; und sie gaben ihnen die Weiber, die sie hatten erhalten von den Weibern zu Jabes in Gilead; und sie fanden keine mehr also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Da reuete es das Volk uber Benjamin, daß der HERR einen Rift gemacht hatte in den Stammen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Und die Altesten der Gemeine sprachen: Was wollen wir tun, daß die ubrigen auch Weiber kriegen? Denn die Weiber in Benjamin sind vertilget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Und sprachen: Die ubrigen von Benjamin müssen ja ihr Erbe behalten, daß nicht ein Stamm ausgetilget werde von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Und wir konnen ihnen unsere Tochter nicht zu Weibern geben; denn die Kinder Israel haben geschworen und gesagt: Verflucht sei, der den Benjaminitern ein Weib gibt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Und sie sprachen: Siehe, es ist ein Jahrfestdes HERRN zu Silo, die zu mitternachtwarts liegt gegen Bethel, gegen der Sonnen Aufgang, auf der Strafte, da man hinaufgehet von Bethel gen Sichem; und von mittagwarts liegt sie gegen Libona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Und sie geboten den Kindern Benjamin und sprachen: Gehet hin und lauert in den Weinbergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Wenn ihr dann sehet, daß die Tochter Silos heraus mit Reigen zum Tanz gehen, so fahret hervor aus den Weinbergen, und nehme ein jeglicher ihm ein Weib von den Tochtern Silos und gehet hin ins Land Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Wenn aber ihre Vater Oder Bruder kommen, mit uns zu rechten, wollen wirzu ihnen sagen: Seid ihnen gnadig, denn wir haben sie nicht genommen mit Streit, sondern ihrwolltet sie ihnen nicht geben; die Schuld ist jetzt euer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Die Kinder Benjamin taten also und nahmen Weiber nach ihrer Zahl von den Reigen, die sie raubten; und zogen hin und wohneten in ihrem Erbteil; und baueten Stadte und wohneten drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Auch die Kinder Israel machten sich von dannen zu der Zeit, ein jeglicher zu seinem Stamm und zu seinem Geschlecht, und zogen von dannen aus, ein jeglicher zu seinem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Zu der Zeit war kein Konig in Israel; ein jeglicher tat, was ihn recht deuchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Zu der Zeit, da die Richter regierten, ward eine Teurung im Lande. Und ein Mann von Bethlehem- Juda zog wallen in der Moabiter Land mit seinem Weibe und zween Sohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Der hied Elimelech und sein Weib Naemi, und seine zween Sohne Mahlon und Chiljon, die waren Ephrather, von Bethlehem-Juda. Und da sie kamen ins Land der Moabiter, blieben sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Und Elimelech, der Naemi Mann, starb, und sie blieb übrig mit ihren zween Sohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Die nahmen moabitische Weiber. Eine hied Arpa, die andere Ruth. Und da sie daselbst gewohnet hatten bei zehn Jahren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'starben sie alle beide, Mahlon und Chiljon, dad das Weib uberblieb beiden Sohnen und ihrem Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Da machte sie sich auf mit ihren zwo Schnuren und zog wieder aus der Moabiter Lande; denn sie hatte erfahren im Moabiter Lande, dad der HERR sein Volk hatte heimgesucht und ihnen Brot gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Und ging aus von dem Ort, da sie gewesen war, und ihre beiden Schnure mit ihr. Und da sie ging auf dem Wege, dad sie wiederkame ins Land Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'sprach sie zu ihren beiden Schnuren: Gehet hin und kehret urn, eine jegliche zu ihrer Mutter Haus; der HERR tue an euch Barmherzigkeit, wie ihr an den Toten und an mir getan habt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Der HERR gebe euch, dad ihr Ruhe findet, eine jegliche in ihres Mannes Hause! Und kussete sie. Da huben sie ihre Stimme auf und weineten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Und sprachen zu ihr: Wirwollen mit dir zu deinem Volkgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Aber Naemi sprach: Kehret urn, meine Tochter; warum wollt ihr mit mir gehen? Wie kann ich furder Kinder in meinem Leibe haben, die eure Manner sein mochten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Kehret urn, meine Tochter, und gehet hin; denn ich bin nun zu alt, dad ich einen Mann nehme. Und wenn ich sprache: Es ist zu hoffen, dad ich diese Nacht einen Mann nehme und Kinder gebare,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'wie konnet ihr doch harren, bis sie grod wurden? Wie wollt ihr verziehen, dad ihr nicht Manner solltet nehmen? Nicht, meine Tochter; denn mich jammed euer sehr, denn des HERRN Hand ist über mich ausgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Da huben sie ihre Stimme auf und weineten noch mehr. Und Arpa kussete ihre Schwieger; Ruth aber blieb bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Sie aber sprach: Siehe, deine Schwagerin ist umgewandt zu ihrem Volk und zu ihrem Gott; kehre du auch urn, deiner Schwagerin nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruth antwortete: Rede mir nicht darein, dad ich dich verlassen sollte und von dir umkehren. Wo du hingehest, da will ich auch hingehen; wo du bleibest, da bleibe ich auch. Dein Volk ist mein Volk und dein Gott ist mein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Wo du stirbst, da sterbe ich auch; da will ich auch begraben werden. Der HERR tue mir dies und das: der Tod mud mich und dich scheiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Als sie nun sah, dad sie fest im Sinne war, mit ihr zu gehen, lied sie ab, mit ihr davon zu reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Also gingen die beiden miteinander bis sie gen Bethlehem kamen. Und da sie zu Bethlehem einkamen, regte sich die ganze Stadt über ihnen und sprach: Ist das die Naemi?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Sie aber sprach zu ihnen: Heidet mich nicht Naemi, sondern Mara; denn der Allmachtige hat mich sehr betrubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Voll zog ich aus, aber leer hat mich der HERR wieder heimgebracht. Warum heidet ihr mich denn Naemi, so mich doch der HERR gedemütiget und der Allmachtige betrubet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Es war aber urn die Zeit, dad die Gerstenernte anging, da Naemi und ihre Schnur Ruth, die Moabitin, wiederkamen vom Moabiter Lande gen Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Es war auch ein Mann, der Naemi Mannes Freund, von dem Geschlecht Elimelechs, mit Namen Boas, der war ein weidlicher Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Und Ruth, die Moabitin, sprach zu Naemi: Lad mich aufs Feld gehen und Ahren auflesen, dem nach, vor dem ich Gnade finde. Sie aber sprach zu ihr: Gehe hin, meine Tochter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Sie ging hin, kam und las auf, den Schnittern nach, auf dem Felde. Und es begab sich eben, dad dasselbe Feld war des Boas, der von dem Geschlecht Elimelechs war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Und siehe, Boas kam eben von Bethlehem und sprach zu den Schnittern: Der HERR mit euch! Sie antworteten: Der HERR segne dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Und Boas sprach zu seinem Knaben, der über die Schnitter gestellet war: Wes ist die Dime?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Der Knabe, der über die Schnitter gestellet war, antwortete und sprach: Es ist die Dime, die Moabitin, die mit Naemi wiederkommen ist von der Moabiter Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Denn sie sprach: Lieber, lad mich auflesen und sammeln unterden Garben, den Schnittern nach; und ist also kommen und da gestanden von Morgen an bis her und bleibt wenig daheim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Da sprach Boas zu Ruth: Horest du es, meine Tochter? Du solist nicht gehen auf einen andern Acker aufzulesen; und gehe auch nicht von hinnen, sondern halte dich zu meinen Dirnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'und siehe, wo sie schneiden im Felde, da gehe ihnen nach. Ich habe meinem Knaben geboten, dad dich niemand antaste. Und so dich durstet, so gehe hin zu dem Gefad und trinke, da meine Knaben schopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Da fiel sie auf ihr Angesicht und betete an zur Erde und sprach zu ihm: Womit habe ich die Gnade funden vor deinen Augen, daß du mich erkennest, die ich doch fremd bin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boas antwortete und sprach zu ihr: Es ist mir angesagt alles, was du getan hast an deiner Schwieger nach deines Mannes Tode: daß du verlassen hast deinen Vater und deine Mutter und dein Vaterland und bist zu einem Volk gezogen, das du zuvor nicht kanntest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Der HERR vergelte dir deine Tat; und müsse dein Lohn vollkommen sein bei dem HERRN, dem Gott Israels, zu welchem du kommen bist, dafi du unter seinen Flugeln Zuversicht hattest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Sie sprach: Laft mich Gnade vor deinen Augen finden, mein HERR; denn du hast mich getrostet und deine Magd freundlich angesprochen, so ich doch nicht bin als deiner Magde eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Boas sprach zu ihr: Wenn\'s Essenszeit ist, so mache dich hie herzu und ift des Brots und tunke deinen Bissen in den Essig. Und sie setzte sich zur Seite der Schnitter. Er aber legte ihr Sangen vor; und sie aft und ward satt und lieft uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Und da sie sich aufmachte zu lesen, gebot Boas seinen Knaben und sprach: Lasset sie auch zwischen den Garben lesen und beschamet sie nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Auch von den Haufen lasset uberbleiben und lasset liegen, daß sie es auflese; und niemand schelte sie drum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Also las sie auf dem Felde bis zum Abend und schlug es aus, was sie aufgelesen hatte; und es war bei einem Epha Gerste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Und sie hub es auf und kam in die Stadt. Und ihre Schwieger sah es, was sie gelesen hatte. Da zog sie hervor und gab ihr, was ihr ubriggeblieben war, davon sie satt war worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Da sprach ihre Schwieger zu ihr: Wo hast du heute gelesen, und wo hast du gearbeitet? Gesegnet sei, der dich erkannt hat! Sie aber sagte es ihrer Schwieger, bei wem sie gearbeitet hatte, und sprach: Der Mann, bei dem ich heute gearbeitet habe, heiftt Boas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Naemi aber sprach zu ihrer Schnur: Gesegnet sei er dem HERRN, denn er hat seine Barmherzigkeit nicht gelassen, beide an den Lebendigen und an den Toten. Und Naemi sprach zu ihr: Der Mann gehoret uns zu und ist unser Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Ruth, die Moabitin, sprach: Er sprach auch das zu mir: Du sollst dich zu meinen Knaben halten, bis sie mir alles eingeerntet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naemi sprach zu Ruth, ihrer Schnur: Es ist besser, meine Tochter, daß du mit seinen Dirnen ausgehest, auf daß nicht jemand dir dreinrede auf einem andern Acker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Also hielt sie sich zu den Dirnen Boas, daß sie las, bis daß die Gerstenernte und Weizenernte aus war. Und kam wieder zu ihrer Schwieger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Und Naemi, ihre Schwieger, sprach zu ihr: Meine Tochter, ich will dir Ruhe schaffen, daß dir\'s wohlgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Nun, der Boas, unser Freund, bei des Dirnen du gewesen bist, worfelt diese Nacht Gerste auf seiner Tenne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'So bade dich und salbe dich und lege dein Kleid an und gehe hinab auf die Tenne, daß dich niemand kenne, bis man ganz gegessen und getrunken hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Wenn er sich dann leget, so merke den Ort, da er sich hinlegt; und komm und decke auf zu seinen Fuften und lege dich, so wird erdirwohl sagen, was du tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Sie sprach zu ihr: Alles was du mir sagest, will ich tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Sie ging hinab zur Tenne und tat alles, wie ihre Schwieger geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Und da Boas gegessen und getrunken hatte, ward sein Herz guter Dinge; und kam und legte sich hinter eine Mandel. Und sie kam leise und deckte auf zu seinen Fuften und legte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Da es nun Mitternacht ward, erschrak der Mann und erschutterte; und siehe, ein Weib lag zu seinen Fuften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Und er sprach: Wer bist du? Sie antwortete: Ich bin Ruth, deine Magd. Breite deinen Flügel uber deine Magd, denn du bist der Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Er aber sprach: Gesegnet seiest du dem HERRN, meine Tochter! Du hast eine bessere Barmherzigkeit hernach getan denn vorhin, daß du nicht bist den Junglingen nachgegangen, weder reich noch arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Nun, meine Tochter, fürchte dich nicht! Alles, was du sagst, will ich dir tun; denn die ganze Stadt meines Volks weift, daß du ein tugendsam Weib bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Nun, es istwahr, daß ich der Erbe bin; aber es ist einer naher denn ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Bleib uber Nacht. Morgen, so er dich nimmt, wohl; gelustet\'s ihn aber nicht, dich zu nehmen, so will ich dich nehmen, sowahrder HERR lebt. Schlaf bis morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Und sie schlief bis morgen zu seinen Fuften. Und sie stund auf, ehe denn einer den andern, kennen mochte; und ergedachte, daß nur niemand inne werde, daß ein Weib in die Tenne kommen sei!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Und sprach: Lange her den Mantel, den du anhast, und halt ihn zu. Und sie hielt ihn zu. Und er maft sechs Maft Gerste und legte es auf sie. Und er kam in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Sie aber kam zu ihrer Schwieger, die sprach: Wie steht es mit dir, meine Tochter? Und sie sagte ihr alles, was ihr der Mann getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'und sprach: Diese sechs Maft Gerste gab er mir, denn er sprach: Du sollst nicht leer zu deiner Schwieger kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Sie aber sprach: Sei stille, meine Tochter, bis du erfahrest, wo es hinaus will; denn der Mann wird nicht ruhen, er bringe es denn heute zu Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boas ging hinauf ins Tor und setzte sich daselbst. Und siehe, da der Erbe voruberging, redete Boas mit ihm und sprach: Komm und setze dich etwa hie Oder da her. Und er kam und setzte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Und er nahm zehn Manner von den Altesten der Stadt und sprach: Setzet euch her! Und sie setzten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Da sprach erzu dem Erben: Naemi, die vom Land der Moabiter wiederkommen ist, beut feil das Stuck Feld, das unsers Bruders war, Elimelechs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Darum gedachte ich\'s vor deine Ohren zu bringen und zu sagen: Willst du es beerben, so kaufe es vor den Burgern und vor den Altesten meines Volks; willst du es aber nicht beerben, so sage mir\'s, daß ich\'s wisse; denn es ist kein Erbe ohne du und ich nach dir. Er sprach: Ich will\'s beerben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Boas sprach: Welches Tages du das Feld kaufst von der Hand Naemis, so muftt du auch Ruth, die Moabitin, des Verstorbenen Weib, nehmen, daß du dem Verstorbenen einen Namen erweckest auf sein Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Da sprach er: Ich mag es nicht beerben, daß ich nicht vielleicht mein Erbteil verderbe. Beerbe du, was ich beerben soil; denn ich mag es nicht beerben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Es war aber von alters her eine solche Gewohnheit in Israel: Wenn einer ein Gut nicht beerben noch erkaufen wollte, auf dad allerlei Sache bestunde, so zog er seinen Schuh aus und gab ihn dem andern; das war das Zeugnis in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Und der Erbe sprach zu Boas: Kaufe du es; und zog seinen Schuh aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Und Boas sprach zu den Altesten und zu allem Volk: Ihrseid heute Zeugen, dad ich alles gekauft habe, was Elimelechs gewesen ist, und alles, was Chiljons und Mahlons, von der Hand Naemis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Dazu auch Ruth, die Moabitin, Mahlons Weib, nehme ich zum Weibe, dad ich dem Verstorbenen einen Namen erwecke auf sein Erbteil, und sein Name nicht ausgerottet werde unter seinen Brudern und aus dem Tor seines Orts; Zeugen seid ihr des heute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Und alles Volk, das im Tor war, samt den Altesten sprachen: Wirsind Zeugen. Der HERR mache das Weib, das in dein Haus kommt, wie Rahel und Lea, die beide das Haus Israel gebauet haben; und wachse sehr in Ephratha und werde gepreiset zu Bethlehem!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Und dein Haus werde wie das Haus Perez, den Thamar Juda gebar, von dem Samen, den dir der HERR geben wird von dieser Dime.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Also nahm Boas die Ruth, daß sie sein Weib ward. Und da er bei ihr lag, gab ihr der HERR, daß sie schwanger ward, und gebar einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Da sprachen die Weiber zu Naemi: Gelobet sei der HERR, der dir nicht hat lassen abgehen einen Erben zu dieser Zeit, daß sein Name in Israel bliebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Der wird dich erquicken und dein Alter versorgen. Denn deine Schnur, die dich geliebet hat, hat ihn geboren, welche dir besser ist denn sieben Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Und Naemi nahm das Kind und legte es auf ihren Schoft und ward seine Warterin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Und ihre Nachbarinnen gaben ihm einen Namen und sprachen: Naemi ist ein Kind geboren; und hieften ihn Obed, der ist der Vater Isais, welcher ist Davids Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Dies ist das Geschlecht Perez: Perez zeugete Hezron;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezron zeugete Ram; Ram zeugete Amminadab;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab zeugete Nahesson; Nahesson zeugete Salma;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salma zeugete Boas; Boas zeugete Obed;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed zeugete Isai; Isai zeugete David. Das erste Buch Samuel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Es war ein Mann von Ramathaim-Zophim, vom Gebirge Ephraim, der hieli Elkana, ein Sohn Jerohams, des Sohns Elihus, des Sohns Thohus, des Sohns Zuphs, welcher von Ephrath war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Und er hatte zwei Weiber; eine hieli Hanna, die andere Peninna. Peninna aber hatte Kinder, und Hanna hatte keine Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Und derselbe Mann ging hinauf von seiner Stadt zu seiner Zeit, daß er anbetete und opferte dem HERRN Zebaoth zu Silo. Daselbstwaren aber Priester des HERRN Hophni und Pinehas, die zween Sohne Elis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Da es nun eines Tages kam, daß Elkana opferte, gab erseinem Weibe Peninna und alien ihren Sohnen und Tochtern Stücke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Aber Hanna gab er ein Stuck traurig; denn er hatte Hanna lieb; aber der HERR hatte ihren Leib verschlossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Und ihre Widerwartige betrubte sie und trotzte ihr sehr, daß der HERR ihren Leib verschlossen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Also ging es alle Jahre, wenn sie hinaufzog zu des HERRN Haus, und betrubte sie also; so weinete sie dann und ali nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Elkana aber, ihr Mann, sprach zu ihr: Hanna, warum weinest du, und warum issest du nichts, und warum gehabt sich dein Herz so libel? Bin ich dir nicht besserdenn zehn Sohne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Da stund Hanna auf, nachdem sie gegessen hatte zu Silo und getrunken. (Eli aber, der Priester, sali auf einem Stuhl an der Pfoste des Tempels des HERRN.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Und sie war von Herzen betrubt und betete zum HERRN und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Und gelobte ein Gelubde und sprach: HERR Zebaoth, wirst du deiner Magd Elend ansehen und an mich gedenken und deiner Magd nicht vergessen und wirst deiner Magd einen Sohn geben, so will ich ihn dem HERRN geben sein Leben lang, und soli kein Schermesser auf sein Haupt kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Und da sie lange betete vordem HERRN, hatte Eli acht auf ihren Mund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Denn Hanna redete in ihrem Herzen; allein ihre Lippen regten sich, und ihre Stimme horete man nicht. Da meinte Eli, sie ware trunken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'und sprach zu ihr: Wie lange willst du trunken sein? Lai?, den Wein von dir kommen, den du bei dir hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Hanna aber antwortete und sprach: Nein, mein Herr, ich bin ein betrubt Weib. Wein und stark Getranke hab ich nicht getrunken, sondern habe mein Herz vor dem HERRN ausgeschüttet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Du wollest deine Magd nicht achten wie ein loses Weib; denn ich habe aus meinem grolien Kummer und Traurigkeit geredet bisher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eli antwortete und sprach: Gehe hin mit Frieden! Der Gott Israels wird dir geben deine Bitte, die du von ihm gebeten hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Sie sprach: Laß deine Magd Gnade finden vor deinen Augen. Also ging das Weib hin ihres Weges und ali und sah nicht mehr so traurig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Und des Morgens frühe machten sie sich auf, und da sie angebetet hatten vor dem HERRN, kehreten sie wieder urn und kamen heim gen Ramath. Und Elkana erkannte sein Weib Hanna; und der HERR gedachte an sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Und da etliche Tage urn waren, ward sie schwanger und gebar einen Sohn und hieli ihn Samuel; denn ich habe ihn von dem HERRN gebeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Und da der Mann Elkana hinaufzog mit seinem ganzen Hause, daß er dem HERRN opferte das Opfer zur Zeit gewohnlich, und sein Gelubde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'zog Hanna nicht mit hinauf, sondern sprach zu ihrem Manne: Bis der Knabe entwohnet werde, so will ich ihn bringen, daß er vor dem HERRN erscheine und bleibe daselbst ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Elkana, ihr Mann, sprach zu ihr: So tue, wie dir\'s gefallt; bleibe, bis du ihn entwohnest; der HERR bestatige aber, was er geredet hat! Also blieb das Weib und saugete ihren Sohn, bis daß sie ihn entwohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Und brachte ihn mit ihr hinauf, nachdem sie ihn entwohnet hatte, mit drei Farren, mit einem Epha Mehl und einer Flasche Weins; und brachte ihn in das Haus des HERRN zu Silo. Der Knabe aber war noch jung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Und sie schlachteten einen Farren und brachten den Knaben zu Eli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Und sie sprach: Ach, mein Herr, so wahr deine Seele lebet, mein Herr, ich bin das Weib, das hie bei dir stund und bat den HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'da ich urn diesen Knaben bat. Nun hat der HERR meine Bitte gegeben, die ich von ihm bat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Darum gebe ich ihn dem HERRN wieder sein Leben lang, weil ervom HERRN erbeten ist. Und sie beteten daselbst den HERRN an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Und Hanna betete und sprach: Mein Herz ist frohlich in dem HERRN, mein Horn ist erhohet in dem HERRN. Mein Mund hat sich weit aufgetan fiber meine Feinde; denn ich freue mich deines Heils.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Es ist niemand heilig, wie der HERR; außer dir ist keiner; und ist kein Hort, wie unser Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Lasset euer grol? Ruhmen und Trotzen, lasset aus eurem Munde das Alte; denn der HERR ist ein Gott, der es merket, und lalit solch Vornehmen nicht gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Der Bogen der Starken ist zerbrochen, und die Schwachen sind umgürtet mit Starke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Die da satt waren, sind urns Brot verkauft worden, und die Hunger litten, hungert nicht mehr, bis daß die Unfruchtbare sieben gebar, und die viel Kinder hatte, abnahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Der HERR totet und machet lebendig, führet in die Holle und wieder heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Der HERR machet arm und machet reich; er niedriget und erhohet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Er hebet auf den Durftigen aus dem Staub und erhohet den Armen aus dem Kot, daß er ihn setze unter die Fursten und den Stuhl der Ehren erben lasse. Denn der Welt Ende sind des HERRN, und er hat den Erdboden drauf gesetzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Erwird behuten die Fufte seiner Heiligen; aber die Gottlosen müssen zunichte werden in Finsternis; denn viel Vermogen hilft doch niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Die mit dem HERRN hadern, müssen zugrunde gehen; über ihnen wird er donnern im Himmel. Der HERR wird richten der Welt Ende und wird Macht geben seinem Konige und erhohen das Horn seines Gesalbten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Elkana aber ging hin gen Ramath in sein Haus, und der Knabe war des HERRN Diener vor dem Priester Eli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Aber die Sohne Elis waren bose Buben; die fragten nicht nach dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'noch nach dem Recht der Priester an das Volk. Wenn jemand etwas opfern wollte, so kam des Priesters Knabe, weil das Fleisch kochte, und hatte eine Kreuel mit drei Zacken in seiner Hand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'und stieft in den Tiegel, Oder Kessel, Oder Pfanne, Oder Topf; und was er mit der Kreuel hervorzog, das nahm der Priester davon. Also taten sie dem ganzen Israel, die daselbst hinkamen zu Silo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Desselbengleichen, ehe denn sie das Fett anzundeten, kam des Priesters Knabe und sprach zu dem, der das Opfer brachte: Gib mir das Fleisch, dem Priester zu braten; denn er will nicht gekocht Fleisch von dir nehmen, sondern roh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Wenn dann jemand zu ihm sagte: Laft das Fett anzünden, wie sich\'s heute gebuhrt, und nimm danach, was dein Herz begehrt, so sprach er zu ihm: Du sollst mir\'s jetzt geben; wo nicht, so will ich\'s mit Gewalt nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Darum war die Sünde der Knaben sehr graft vor dem HERRN; denn die Leute lasterten das Speisopfer des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel aber war ein Diener vor dem HERRN; und der Knabe war umgürtet mit einem leinenen Leibrock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Dazu machte ihm seine Mutter einen kleinen Rock und brachte ihn ihm hinauf zu seiner Zeit, wenn sie mit ihrem Mann hinaufging, zu opfern die Opfer zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Und Eli segnete Elkana und sein Weib und sprach: Der HERR gebe dir Samen von diesem Weibe urn die Bitte, die sie vom HERRN gebeten hat. Und sie gingen an ihren Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Und der HERR suchte Hanna heim, daß sie schwangerward; und gebar drei Sohne und zwo Tochter. Aber Samuel, der Knabe, nahm zu bei dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli aber war sehr alt und erfuhr alles, was seine Sohne taten dem ganzen Israel, und daß sie schliefen bei den Weibern, die da dieneten vor der Tür der Hütte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Und er sprach zu ihnen: Warum tut ihr solches? Denn ich hore euer boses Wesen von diesem ganzen Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nicht, meine Kinder das ist nicht ein gut Geschrei, das ich hore. Ihr machet des HERRN Volk ubertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Wenn jemand wider einen Menschen sundiget, so kann\'s der Richter schlichten. Wenn aber jemand wider den HERRN sundiget, wer kann fur ihn bitten? Aber sie gehorchten ihres Vaters Stimme nicht, denn der HERR hatte Willen, sie zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Aber der Knabe Samuel ging und nahm zu; und war angenehm bei dem HERRN und bei den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Es kam aber ein Mann Gottes zu Eli und sprach zu ihm: So spricht der HERR: Ich habe mich offenbaret deines Vaters Hause, da sie noch in Agypten waren in Pharaos Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'und habe ihn daselbst mir erwahlet vor alien Stammen Israels zum Priestertum, daß er opfern sollte auf meinem Altar und Rauchwerk anzünden und den Leibrock vor mir tragen; und habe deines Vaters Hause gegeben alle Feuer der Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Warum lockest du denn wider meine Opfer und Speisopfer, die ich geboten habe in der Wohnung? Und du ehrest deine Sohne mehr denn mich, daß ihr euch mastet von dem Besten aller Speisopfer meines Volks Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Darum spricht der HERR, der Gott Israels: Ich habe geredet, dein Haus und deines Vaters Haus sollten wandeln vor mir ewiglich. Aber nun spricht der HERR: Es sei feme von mir, sondern wer mich ehret, den will ich auch ehren; wer aber mich verachtet, der soli wieder verachtet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Siehe, es wird die Zeit kommen, daß ich will entzweibrechen deinen Arm und den Arm deines Vaters Hauses, daß kein Alter sei in deinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Und wirst sehen deinen Widerwartigen in der Wohnung in allerlei Gut, das Israel geschehen wird; und wird kein Alter sein in deines Vaters Hause ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Doch will ich aus dir niemand von meinem Altar ausrotten, auf daß deine Augen verschmachten und deine Seele sich grame; und alle Menge deines Hauses sollen sterben, wenn sie Manner worden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Und das soli dir ein Zeichen sein, das uber deine zween Sohne, Hophni und Pinehas, kommen wird: auf einen Tag werden sie beide sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Ich aber will mir einen treuen Priester erwecken, der soil tun, wie es meinem Herzen und meiner Seele gefallt; dem will ich ein bestandig Haus bauen, daß er vor meinem Gesalbten wandele immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Und wer ubrig ist von deinem Hause, der wird kommen und vorjenem niederfallen urn einen silbernen Pfennig und Stuck Brats und wird sagen: Lieber, lafi mich zu einem Priesterteil, daß ich einen Bissen Brat esse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Und da Samuel, der Knabe, dem HERRN dienete unter Eli, war des HERRN Wort teuer zu derselbigen Zeit, und warwenig Weissagung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Und es begab sich, zur selben Zeit lag Eli an seinem Ort, und seine Augen fingen an dunkel zu werden, daß er nicht sehen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Und Samuel hatte sich geleget im Tempel des HERRN, da die Lade Gottes war, ehe denn die Lampe Gottes verlosch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Und der HERR rief Samuel. Er aber antwortete: Siehe, hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Und lief zu Eli und sprach: Siehe, hie bin ich, du hast mich gerufen. Er aber sprach: Ich habe dich nicht gerufen; gehe wieder hin und lege dich schlafen. Und er ging hin und legte sich schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Der HERR rief abermal: Samuel! Und Samuel stund auf und ging zu Eli und sprach: Siehe, hie bin ich, du hast mich gerufen. Er aber sprach: Ich habe dich nicht gerufen, mein Sohn; gehe wieder hin und lege dich schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Aber Samuel kannte den HERRN noch nicht, und des HERRN Wort war ihm noch nicht offenbaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Und der HERR rief Samuel aber zum drittenmal. Und er stund auf und ging zu Eli und sprach: Siehe, hie bin ich, du hast mich gerufen. Da merkte Eli, daß der HERR dem Knaben rief,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'und sprach zu ihm: Gehe wieder hin und lege dich schlafen; und so du gerufen wirst, so sprich: Rede, HERR; denn dein Knecht horet. Samuel ging hin und legte sich an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Da kam der HERR und tratdahin und riefwie vormals: Samuel, Samuel! Und Samuel sprach: Rede, denn dein Knecht horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Und der HERR sprach zu Samuel: Siehe, ich tue ein Ding in Israel, daß, wer das horen wird, dem werden seine beiden Ohren gellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'An dem Tage will ich erwecken über Eli, was ich wider sein Haus geredet habe; ich will\'s anfahen und vollenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Denn ich hab\'s ihm angesagt, dafi ich Richter sein will uber sein Haus ewiglich urn der Missetat willen, daß erwulite, wie seine Kinder sich schandlich hielten, und hatte nicht einmal sauer dazu gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Darum habe; ich dem Hause Eli geschworen, daß diese Missetat des Hauses Eli soil nicht versohnet werden weder mit Opfer noch mit Speisopfer ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Und Samuel lag bis an den Morgen; und tat die Türauf am Hause des HERRN. Samuel aber furchtete sich, das Gesicht Eli anzusagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Da rief ihm Eli und sprach: Samuel, mein Sohn! Er antwortete: Siehe, hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Er sprach: Was ist das Wort, das dir gesagt ist? Verschweige mir nichts. Gott tue dir dies und das, wo du mir etwas verschweigest, das dir gesagt ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Da sagte es ihm Samuel alles an und verschwieg ihm nichts. Er aber sprach: Es ist der HERR; er tue, was ihm wohlgefallt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel aber nahm zu, und der HERR war mit ihm; und fiel keines unter alien seinen Worten auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Und ganz Israel, von Dan an bis gen Berseba, erkannte, daß Samuel ein treuer Prophet des HERRN war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Und der HERR erschien hinfort zu Silo; denn der HERR war Samuel offenbaret worden zu Silo durch das Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Und Samuel fing an zu predigen dem ganzen Israel. Israel aber zog aus den Philistern entgegen in den Streit; und lagerten sich bei Eben-Ezer. Die Philister aber hatten sich gelagert zu Aphek');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'und rusteten sich gegen Israel. Und der Streit teilete sich weit. Und Israel ward vor den Philistern geschlagen, und schlugen in der Ordnung im Felde bei viertausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Und da das Volk ins Lager kam, sprachen die Altesten Israels: Warum hat uns der HERR heute schlagen lassen vor den Philistern? Lalit uns zu uns nehmen die Lade des Bundes des HERRN von Silo und lafit sie, unter uns kommen, daß sie uns helfe von der Hand unserer Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Und das Volk sandte gen Silo und liefi von dannen holen die Lade des Bundes des HERRN Zebaoth, der uber den Cherubim sitzet. Und waren da die zween Sohne Elis mit der Lade des Bundes Gottes, Hophni und Pinehas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Und da die Lade des Bundes des HERRN in das Lager kam, jauchzete das ganze Israel mit einem grolien Jauchzen, daß die Erde erschallete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Da aber die Philister horeten das Geschrei solches Jauchzens, sprachen sie: Was ist das Geschrei solches grolien Jauchzens in der Ebraer Lager? Und da sie erfuhren, daß die Lade des HERRN ins Lager kommen ware,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'fürchteten sie sich und sprachen: Gott ist ins Lager kommen; und sprachen weiter: Wehe uns! denn es ist vorhin nicht also gestanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Wehe uns! Wer will uns erretten von der Hand dieser machtigen Gotter? Das sind die Gotter, die Agypten schlugen mit allerlei Plage in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'So seid nun getrost und Manner, ihr Philister, daß ihr nicht dienen müsset den Ebraern, wie sie euch gedienet haben. Seid Manner und streitet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Da stritten die Philister, und Israel ward geschlagen, und ein jeglicher floh in seine Hütte. Und es war eine sehr grolie Schlacht, daß aus Israel fielen dreilügtausend Mann Fulivolks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Und die Lade Gottes ward genommen, und die zween Sohne Elis, Hophni und Pinehas, starben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Da lief einer von Benjamin ausdem Heer und kam gen Silo desselben Tages; und hatte seine Kleider zerrissen und hatte Erde auf sein Haupt gestreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Und siehe, als er hineinkam, saß Eli auf dem Stuhl, da($ er auf den Weg sahe; denn sein Herz war zaghaft uber der Lade Gottes. Und da der Mann in die Stadt kam, sagte er\'s an; und die ganze Stadt schrie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Und da Eli das laute Schreien horete, fragte er: Was ist das fur ein laut Getummel? Da kam der Mann eilend und sagte es Eli an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, '(Eli aber war achtundneunzig Jahre alt, und seine Augen waren dunkel, dais er nicht sehen konnte.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Der Mann abersprach zu Eli: Ich komme und bin heute aus dem Heer geflohen. Er aber sprach: Wie gehet es zu, mein Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Da antwortete der Verkundiger und sprach: Israel ist geflohen vor den Philistern, und isteine grolie Schlacht im Volk geschehen; und deine zween Sohne, Hophni und Pinehas, sind gestorben; dazu die Lade Gottes ist genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Da er aber der Lade Gottes gedachte, fiel er zurück vom Stuhl am Tor und brach seinen Hals entzwei und starb; denn er war alt und ein schwerer Mann. Er richtete aber Israel vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Seine Schnur aber, Pinehas Weib, war schwanger und sollte schier geliegen. Da sie das Gerucht horete, daß die Lade Gottes genommen und ihr Schwaher und Mann tot ware, krümmete sie sich und gebar, denn es kam sie ihr Wehe an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Und da sie jetzt starb, sprachen die Weiber, die neben ihrstunden: Fürchte dich nicht, du hasteinen jungen Sohn. Aber sie antwortete nichts und nahm\'s auch nicht zu Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Und sie hiefi den Knaben Ikabod und sprach: Die Herrlichkeit ist dahin von Israel; weil die Lade Gottes genommen war und ihr Schwaher und ihr Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Und sprach abermal: Die Herrlichkeit ist dahin von Israel; denn die Lade Gottes ist genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Die Philister aber nahmen die Lade Gottes und brachten sie von Eben-Ezer gen Asdod,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'in das Haus Dagons, und stelleten sie neben Dagon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Und da die von Asdod des andern Morgens frühe aufstunden, fanden sie Dagon auf seinem Antlitz liegen auf der Erde vor der Lade des HERRN. Aber sie nahmen den Dagon und setzten ihn wieder an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Da sie aber des andern Morgens fruhe aufstunden, fanden sie Dagon abermal auf seinem Antlitz liegen auf der Erde vor der Lade des HERRN, aber sein Haupt und seine beiden Hande abgehauen auf der Schwelle, dafi der Rumpf allein drauf lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Darum treten die Priester Dagons und alle, die in Dagons Haus gehen, nicht auf die Schwelle Dagons zu Asdod bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Aber die Hand des HERRN ward schwer uber die von Asdod und verderbete sie und schlug Asdod und aile ihre Grenzen an heimlichen Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Da aber die Leute zu Asdod sahen, daß es so zuging, sprachen sie: Laüt die Lade des Gottes Israels nicht bei uns bleiben; denn seine Hand istzu hart uber uns und unsern Gott Dagon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Und sandten hin und versammelten aile Fürsten der Philister zu sich und sprachen: Was sollen wir mit der Lade des Gottes Israels machen? Da antworteten sie: Lasset die von Gath die Lade des Gottes Israels umhertragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Und sie trugen die Lade des Gottes Israels umher. Da sie aber dieselbe umhertrugen, ward durch die Hand des HERRN in der Stadt ein sehr großer Rumor, und schlug die Leute in der Stadt, beide kiein und groli, und kriegten heimliche Plage an heimlichen Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Da sandten sie die Lade des HERRN gen Ekron. Da aber die Lade Gottes gen Ekron kam, schrieen die von Ekron: Sie haben die Lade Gottes umhergetragen zu mir, daß sie mich tote und mein Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Da sandten sie hin und versammelten aile Fursten der Philister und sprachen: Sendet die Lade des Gottes Israels wieder an ihren Ort, daß sie mich und mein Volk nicht tote. Denn die Hand Gottes machte einen sehr grolien Rumor mit Würgen in der ganzen Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Und welche Leute nicht starben, die wurden geschlagen an heimlichen Orten, daß das Geschrei der Stadt auf gen Himmel ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Also war die Lade des HERRN sieben Monde im Lande der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Und die Philister riefen ihren Priestern und Weissagern und sprachen: Was sollen wir mit der Lade des HERRN machen? Lehret uns, womit sollen wir sie an ihren Ort senden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Sie sprachen: Wollt ihr die Lade des Gottes Israels senden, so sendet sie nicht leer, sondern sollt ihr vergelten ein Schuldopfer, so werdet ihr gesund werden und wird euch kund werden, warum seine Hand nicht von euch lalit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Sie aber sprachen: Welches ist das Schuldopfer, das wir ihm geben sollen? Sie antworteten: Fünf güldene Arse und fünf güldene Mause nach der Zahl der fünf Fürsten der Philister; denn es ist einerlei Plage gewesen über euch aile und über eure Fürsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'So müsset ihr nun machen gleiche Gestalt euren Arsen und euren Mausen, die euer Land verderbet haben, daß ihr dem Gott Israels die Ehre gebet; vielleicht wird seine Hand leichter werden über euch und über euren Gott und über euer Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Warum verstocket ihr euer Herz, wie die Agypter und Pharao ihr Herz verstockten? Ist\'s nicht also, da er sich an ihnen beweisete, liefien sie sie fahren, dafi sie hingingen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'So nehmet nun und machet einen neuen Wagen und zwo junge saugende Kühe, auf die nie kein Joch kommen ist, und spannet sie an den Wagen und lasset ihre Kalber hinter ihnen daheim bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Und nehmet die Lade des HERRN und legt sie auf den Wagen; und die güldenen Kleinode, die ihr ihm zum Schuldopfer gebt, tut in ein Kastlein neben ihre Seiten und sendet sie hin und lasset sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Und sehet ihr zu. Gehet sie hinauf dem Wege ihrer Grenze gen Beth-Semes, so hat er uns all das grofie Ubel getan. Wo nicht, so werden wirwissen, daß seine Hand uns nicht gerührt hat, sondern es ist uns ohngefahr widerfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Die Leute taten also und nahmen zwo junge saugende Kühe und spanneten sie an einen Wagen und behielten ihre Kalber daheim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Und legten die Lade des HERRN auf den Wagen und das Kastlein mit den güldenen Mausen und mit den Bildern ihrer Arse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Und die Kühe gingen stracks Weges zu Beth- Semes zu auf einer Strafie; und gingen und bloketen und wichen nicht, weder zur Rechten noch zur Linken. Und die Fursten der Philister gingen ihnen nach bis an die Grenze Beth-Semes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Die Beth-Semiter aber schnitten eben in der Weizenernte im Grunde; und huben ihre Augen auf und sahen die Lade und freueten sich, dieselbe zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Der Wagen aber kam auf den Acker Josuas, des Beth-Semiters, und stund daselbst stille. Und war ein grower Stein daselbst. Und sie spalteten das Holz vom Wagen und opferten die Kühe dem HERRN zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Die Leviten aber huben die Lade des HERRN herab und das Kastlein, das neben dran war, darinnen die güldenen Kleinode waren, und setzten sie auf den grofien Stein. Aber die Leute zu Beth-Semes opferten dem HERRN desselben Tages Brandopfer und andere Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Da aber die fünf Fürsten der Philister zugesehen hatten, zogen sie wiederum gen Ekron desselben Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Dies sind aber die güldenen Arse, die die Philister dem HERRN zum Schuldopfer gaben: Asdod einen, Gasa einen, Asklon einen, Gath einen und Ekron einen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Und guldene Mause nach der Zahl aller Stadte der Philister unter den fünf Fürsten, beide der gemauerten Stadte und Dorfer, und bis an das groüe Abel, darauf sie die Lade des HERRN lielien, bis auf diesen Tag, auf dem Acker Josuas, des Beth- Semiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Und etliche zu Beth-Semes wurden geschlagen, darum dafi sie die Lade des HERRN gesehen hatten. Und er schlug des Volks funfzigtausend und siebenzig Mann. Da trug das Volk Leid, daß der HERR so eine grofie Schlacht im Volk getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Und die Leute zu Beth-Semes sprachen: Wer kann stehen vordem HERRN, solchem heiligen Gott? und zu wem soil er von uns ziehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Und sie sandten Boten zu den Burgern Kiriath- Jearims, und lielien ihnen sagen: Die Philister haben die Lade des HERRN wiedergebracht; kommt herab und holet sie zu euch hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Also kamen die Leute von Kiriath-Jearim und holeten die Lade des HERRN hinauf und brachten sie ins Haus Abinadabs zu Gibea; und seinen Sohn Eleasar heiligten sie, daß er der Lade des HERRN hütete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Und von dem Tage an, da die Lade des HERRN zu Kiriath-Jearim blieb, verzog sich die Zeit so lange, bis zwanzig Jahre wurden; und das ganze Haus Israel weinete vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Samuel abersprach zu dem ganzen Hause Israel: So ihr euch mit ganzem Herzen bekehret zu dem HERRN, so tut von euch die fremden Gotter und Astharoth und richtet euer Herz zu dem HERRN und dienet ihm allein, so wird er euch erretten aus der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Da taten die Kinder Israel von sich Baalim und Astharoth und dieneten dem HERRN allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Samuel aber sprach: Versammelt das ganze Israel gen Mizpa, dafi ich fur euch bitte zum HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Und sie kamen zusammen gen Mizpa und schopften Wasser und gossen es aus vor dem HERRN; und fasteten denselben Tag und sprachen daselbst: Wir haben dem HERRN gesundiget. Also richtete Samuel die Kinder Israel zu Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Da aber die Philister horeten, daß die Kinder Israel zusammenkommen waren gen Mizpa, zogen die Fursten der Philister hinauf wider Israel. Da das die Kinder Israel horeten, furchteten sie sich vor den Philistern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'und sprachen zu Samuel: Lali nicht ab, fur uns zu schreien zu dem HERRN, unserm Gott, daß er uns helfe aus der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel nahm ein Milchlammlein und opferte dem HERRN ein ganz Brandopfer und schrie zum HERRN fur Israel; und der HERR erhorete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Und indem Samuel das Brandopfer opferte, kamen die Philister herzu, zu streiten wider Israel. Aber der HERR liefi donnern einen grolien Donner über die Philister desselben Tages und schreckte sie, daß sie vor Israel geschlagen wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Da zogen die Manner Israels aus von Mizpa und jagten die Philister und schlugen sie bis unter Beth- Kar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Da nahm Samuel einen Stein und setzte ihn zwischen Mizpa und Sen; und hieli ihn Eben-Ezerund sprach: Bis hieher hat uns der HERR geholfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Also wurden die Philister gedampfet und kamen nicht mehr in die Grenze Israels; und die Hand des HERRN war wider die Philister, solange Samuel lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Also wurden Israel die Stadte wieder, die die Philister ihnen genommen hatten, von Ekron an bis gen Gath samt ihren Grenzen; die errettete Israel von der Hand der Philister; denn Israel hatte Frieden mit den Amoritern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel aber richtete Israel sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Und zog jahrlich umher zu Bethel und Gilgal und Mizpa. Und wenn er Israel an alien diesen Orten gerichtet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'kam er wieder gen Ramath, denn da war sein Haus; und richtete Israel daselbst und bauete dem HERRN daselbst einen Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Da aber Samuel alt ward, setzte er seine Sohne zu Richtern über Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Sein erstgeborner Sohn hieli Joel und der andere Abia; und waren Richter zu Berseba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Aber seine Sohne wandelten nicht in seinem Wege, sondern neigeten sich zum Geiz und nahmen Geschenk und beugeten das Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Da versammelten sich alle Altesten in Israel und kamen gen Ramath zu Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Und sprachen zu ihm: Siehe, du bist alt worden, und deine Sohne wandeln nicht in deinen Wegen; so setze nun einen Konig uber uns, der uns richte, wie alle Heiden haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Das gefiel Samuel libel, daß sie sagten: Gib uns einen Konig, der uns richte. Und Samuel betete vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Der HERR aber sprach zu Samuel: Gehorche der Stimme des Volks in allem, das sie zu dir gesagt haben; denn sie haben nicht dich, sondern mich verworfen, daß ich nicht soli Konig uber sie sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Sie tun dir, wie sie immer getan haben von dem Tage an, da ich sie aus Agypten führete; bis auf diesen Tag, und haben mich verlassen und andern Gottern gedienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'So gehorche nun ihrer Stimme. Doch bezeuge ihnen und verkundige ihnen das Recht des Konigs, der uber sie herrschen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Und Samuel sagte alle Worte des HERRN dem Volk, das von ihm einen Konig forderte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Das wird des Konigs Recht sein, der uber euch herrschen wird: Eure Sohne wird er nehmen zu seinem Wagen und Reitern, die vor seinem Wagen hertraben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'und zu Hauptleuten uber tausend und uber funfzig und zu Ackerleuten, die ihm seinen Acker bauen, und zu Schnittern in seiner Ernte, und daß sie seinen Harnisch, und was zu seinem Wagen gehoret, machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Eure Tochter aber wird er nehmen, daß sie Apothekerinnen, Kochinnen und Backerinnen seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Eure besten Acker und Weinberge und Olgarten wird er nehmen und seinen Knechten geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Dazu von eurer Saat und Weinbergen wird er den Zehnten nehmen und seinen Kammerern und Knechten geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Und eure Knechte und Magde und eure feinsten Junglinge und eure Esel wird er nehmen und seine Geschafte damit ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Von euren Herden wird erden Zehnten nehmen, und ihr müsset seine Knechte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Wenn ihr dann schreien werdet zu der Zeit über euren Konig, den ihr euch erwahlet habt; so wird euch der HERR zu derselbigen Zeit nicht erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Aber das Volk weigerte sich, zu gehorchen der Stimme Samuels, und sprachen: Mitnichten, sondern es soil ein Konig über uns sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'daß wir seien auch wie alle andern Heiden, daß uns unser Konig richte und vor uns her ausziehe, wenn wir unsere Kriege führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Da gehorchte Samuel alle dem, das das Volk sagte, und sagte es vor den Ohren des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Der HERR aber sprach zu Samuel: Gehorche ihrer Stimme und mache ihnen einen Konig! Und Samuel sprach zu den Mannern Israels: Gehet hin, ein jeglicher in seine Stadt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Es war aber ein Mann von Benjamin mit Namen Kis, ein Sohn Abiels, des Sohns Zerors, des Sohns Bechoraths, des Sohns Apiahs, des Sohns eines Mannes Jemini, ein weidlicher Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Der hatte einen Sohn mit Namen Saul; der war ein junger feiner Mann, und war kein feinerer unter den Kindern Israel, eines Hauptes lanqer denn alles Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Es hatte aber Kis, der Vater Sauls, seine Eselinnen verloren; und er sprach zu seinem Sohne Saul: Nimm der Knaben einen mit dir, mache dich auf, gehe hin und suche die Eselinnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Und er ging durch das Gebirge Ephraim und durch das Land Salisa, und fanden sie nicht; sie gingen durch das Land Saalim, und sie waren nicht da; sie gingen durchs Land Jemini und fanden sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Da sie aber kamen ins Land Zuph, sprach Saul zu dem Knaben, der mit ihm war: Komm, la(i uns wieder heimgehen; mein Vater mochte von den Eselinnen lassen und fur uns sorgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Er aber sprach: Siehe, es ist ein berühmter Mann Gottes in dieser Stadt; alles, was er sagt, das geschiehet. Nun lali uns dahin gehen; vielleicht sagt er uns unsern Weg, den wir gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul aber sprach zu seinem Knaben: Wenn wir schon hingehen, was bringen wir dem Manne? Denn das Brot ist dahin aus unserem Sack; so haben wir sonst keine Gabe, die wir dem Mann Gottes bringen. Was haben wir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Der Knabe antwortete Saul wieder und sprach: Siehe, ich habe ein Vierteil eines silbernen Sekels bei mir; den wollen wir dem Mann Gottes geben, daß er uns unsern Weg sage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Vorzeiten in Israel, wenn man ging, Gott zu fragen, sprach man: Kommt, laßt uns gehen zu dem Seher! Denn die man jetzt Propheten heißt, die hieß man vorzeiten Seher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul sprach zu seinem Knaben: Du hastwohl geredet; komm, laß uns gehen! Und da sie hingingen zu der Stadt, da der Mann Gottes war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'und zur Stadt hinaufkamen, fanden sie Dirnen, die herausgingen, Wasserzu schopfen. Zu denselben sprachen sie: Ist der Seher hie?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Sie antworteten ihnen und sprachen: Ja, siehe, da ist er; eile, denn er ist heute in die Stadt kommen, weil das Volk heute zu opfern hat auf der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Wenn ihr in die Stadt kommt, so werdet ihr ihn finden, ehe denn er hinaufgehet auf die Hohe zu essen. Denn das Volkwird nichtessen, bis er komme, sintemal er segnet das Opfer; danach essen die, so geladen sind. Darum so gehet hinauf, denn jetzt werdet ihr ihn eben antreffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Und da sie hinauf zur Stadt kamen und mitten in der Stadt waren, siehe, da ging Samuel heraus ihnen entgegen und wollte auf die Hohe gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Aber der HERR hatte Samuel seinen Ohren offenbaret einen Tag zuvor, ehe denn Saul kam, und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Morgen urn diese Zeitwill ich einen Mann zu dir senden aus dem Lande Benjamin; den sollstdu zum Fursten salben uber mein Volk Israel, daü er mein Volkerlose von der Philister Hand. Denn ich habe mein Volk angesehen, und sein Geschrei ist vor mich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Da nun Samuel Saul ansah, antwortete ihm der HERR: Siehe, das ist der Mann, davon ich dir gesagt habe, dafi er fiber mein Volk herrsche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Da trat Saul zu Samuel unter dem Tor und sprach: Sage mir, wo ist hie des Sehers Haus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel antwortete Saul und sprach: Ich bin der Seher; gehe vor mir hinauf auf die Hohe, denn ihr sollt heute mit mir essen: morgen will ich dich lassen gehen, und alles, was in deinem Herzen ist, will ich dir sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Und urn die Eselinnen, die du vor dreien Tagen verloren hast, bekümmere dich jetzt nicht; sie sind gefunden. Und wes wird sein alles, was das Beste ist in Israel? Wird\'s nicht dein und deines Vaters ganzen Hauses sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul antwortete: Bin ich nicht ein Sohn von Jemini und von den geringsten Stammen Israels, und mein Geschlecht das kleinste unter alien Geschlechtern der Stamme Benjamin? Warum sagst du denn mirsolches?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel aber nahm Saul und seinen Knaben und fuhrete sie in die EGlaube und setzte sie obenan unter die, so geladen waren, deren war bei dreißig Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Und Samuel sprach zu dem Koch: Gib her das Stuck, das ich dir gab und befahl, du solltest es bei dir behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Da trug der Koch eine Schulter auf, und das daran hing. Und er legte es Saul vor und sprach: Siehe, das ist uberblieben; lege vor dich und iß; denn es ist auf dich behalten eben auf diese Zeit, da ich das Volk lud. Also aß Saul mit Samuel des Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Und da sie hinabgingen von der Hohe zur Stadt, redete er mit Saul auf dem Dache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Und stunden fruhe auf; und da die Morgenrote aufging, rief Samuel dem Saul auf dem Dache und sprach: Auf! daß ich dich gehen lasse. Und Saul machte sich auf, und die beiden gingen miteinander hinaus, er und Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Und da sie kamen hinab an der Stadt Ende, sprach Samuel zu Saul: Sage dem Knaben, daß er vor uns hingehe (und er ging vorhin); du aber stehe jetzt stille, daß ich dir kundtue, was Gott gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Da nahm Samuel ein Olglas und goß auf sein Haupt und kussete ihn und sprach: Siehest du, daß dich der HERR zum Fursten uber sein Erbteil gesalbet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Wenn du jetzt von mir gehest, so wirst du zween Manner finden bei dem Grabe Rahels in der Grenze Benjamins zu Zelzah, die werden zu dir sagen: Die Eselinnen sind gefunden, die du zu suchen bist gegangen; und siehe, dein Vater hat die Esel aus der Acht gelassen und sorget urn euch und spricht: Was soil ich urn meinen Sohn tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Und wenn du dich von dannen fürbaß wendest, so wirst du kommen zu der Eiche Thabor; daselbst werden dich antreffen drei Manner, die hinaufgehen zu Gott gen Bethel. Einer tragt drei Bocklein, der andere drei Stücke Brots, der dritte eine Flasche mit Wein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Und sie werden dich freundlich grußen und dir zwei Brote geben. Die sollst du von ihren Handen nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Danach wirst du kommen auf den Huge! Gottes, da der Philister Lager ist; und wenn du daselbst in die Stadt kommst, wird dir begegnen ein Haufe Propheten von der Hohe herabkommend und vor ihnen her ein Psalter und Pauken und Pfeifen und Harfen, und sie weissagend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Und der Geist des HERRN wird fiber dich geraten, daß du mit ihnen weissagest; da wirst du ein anderer Mann werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Wenn dir nun diese Zeichen kommen, so tue, was dir unter Handen kommt; denn Gott ist mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Du sollst aber vor mir hinabgehen gen Gilgal; siehe, da will ich zu dir hinabkommen, zu opfern Brandopfer und Dankopfer. Sieben Tage sollst du harren, bis ich zu dir komme und dir kundtue, was du tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Und da er seine Schultern wandte, daß ervon Samuel ging, gab ihm Gott ein ander Herz; und kamen alle diese Zeichen auf denselben Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Und da sie kamen an den Hugel, siehe, da kam ihm ein Prophetenhaufe entgegen; und der Geist Gottes geriet uber ihn, daß er unter ihnen weissagete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Da ihn aber sahen alle, die ihn vorhin gekannt hatten, daß er mit den Propheten weissagete, sprachen sie alle untereinander: Was ist dem Sohne Kis geschehen? Ist Saul auch unter den Propheten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Und einer daselbst antwortete und sprach: Wer ist ihr Vater? Daher ist das Sprichwort kommen: Ist Saul auch unter den Propheten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Und da er ausgeweissaget hatte, kam er auf die Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Es sprach aber Sauls Vetter zu ihm und zu seinem Knaben: Wo seid ihr hingegangen? Sie antworteten: Die Eselinnen zu suchen; und da wir sahen, daß sie nicht da waren, kamen wir zu Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Da sprach der Vetter Sauls: Sage mir, was sagte euch Samuel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul antwortete seinem Vetter: Er sagte uns, daß die Eselinnen gefunden waren. Aber von dem Konigreich sagte er ihm nicht, was Samuel gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel aber berief das Volk zum HERRN gen Mizpa');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'und sprach zu den Kindern Israel: So sagt der HERR, der Gott Israels: Ich habe Israel aus Agypten gefuhret und euch von der Agypter Hand errettet und von der Hand aller Konigreiche, die euch zwangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Und ihr habt heute euren Gott verworfen, der euch aus all eurem Ungluck und Trubsal geholfen hat, und sprechet zu ihm: Setze einen Konig uber uns! Wohlan, so tretet nun vor den HERRN nach euren Stammen und Freundschaften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Da nun Samuel alle Stamme Israels herzubrachte, ward getroffen der Stamm Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Und da erden Stamm Benjamin herzubrachte mit seinen Geschlechtern, ward getroffen das Geschlecht Matris, und ward getroffen Saul, der Sohn Kis. Und sie suchten ihn, aber sie fanden ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Da fragten sie furder den HERRN: Wird er auch noch herkommen? Der HERR antwortete: Siehe, er hat sich unter die Fasser versteckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Da liefen sie hin und holeten ihn von dannen. Und da er unter das Volk trat, war er eines Haupts langer denn alles Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Und Samuel sprach zu allem Volk: Da sehet ihr, welchen der HERR erwahlet hat, denn ihm ist keiner gleich in allem Volk. Da jauchzte alles Volk und sprach: Gluck zu dem Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Samuel aber sagte dem Volk alle Rechte des Konigreichs und schrieb\'s in ein Buch und legte es vor den HERRN. Und Samuel lieli alles Volk gehen, einen jeglichen in sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Und Saul ging auch heim gen Gibea; und ging mit ihm des Heers ein Teil, welcher Herz Gott ruhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Aber etliche lose Leute sprachen: Was sollte uns dieser helfen? Und verachteten ihn und brachten ihm kein Geschenk. Aber er tat, als horete er\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Eszog aber herauf Nahas, der Ammoniter, und belagerte Jabes in Gilead. Und alle Manner zu Jabes sprachen zu Nahas: Mache einen Bund mit uns, so wollen wirdirdienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Aber Nahas, der Ammoniter, antwortete ihnen: Darin will ich mit euch einen Bund machen, dafi ich euch alien das rechte Auge aussteche und mache euch zuschanden unter dem ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Da sprachen zu ihm die Altesten zu Jabes: Gib uns sieben Tage, dafi wir Boten senden in alle Grenzen Israels; ist dann niemand, der uns errette, so wollen wir zu dir hinausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Da kamen die Boten gen Gibea zu Saul und redeten solches vor den Ohren des Volks. Da hub alles Volk seine Stimme auf und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Und siehe, da kam Saul vom Felde hinter den Rindern her und sprach: Was ist dem Volk, daß es weinet? Da erzahlten sie ihm die Sache der Manner von Jabes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Da geriet der Geist Gottes uber ihn, als er solche Worte horete, und sein Zorn ergrimmete sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Und nahm ein Paar Ochsen und zerstuckte sie und sandte in alle Grenzen Israels durch die Boten und lieli sagen: Wer nicht auszeucht, Saul und Samuel nach, des Rindern soil man also tun. Da fiel die Furcht des HERRN auf das Volk, daß sie auszogen, gleich als ein einiger Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Und machte die Ordnung zu Basek. Und der Kinder, Israel waren dreihundertmal tausend Mann, und der Kinder Juda dreifügtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Und sie sagten den Boten, die kommen waren: Also sagt den Mannern zu Jabes in Gilead: Morgen soil euch Hilfe geschehen, wenn die Sonne beginnet heili zu scheinen. Da die Boten kamen und verkundigten das den Mannern zu Jabes, wurden sie froh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Und die Manner Jabes sprachen: Morgen wollen wir zu euch hinausgehen, daß ihr uns tut alies, was euch gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Und des andern Morgens stellete Saul das Volk in drei Haufen; und kamen ins Lager urn die Morgenwache und schlugen die Ammoniter, bis der Tag heili ward; welche aber uberblieben, wurden also zerstreuet, daß ihrer nicht zween beieinander blieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Da sprach das Volk zu Samuel: Wer sind sie, die da sagten: Sollte Saul uber uns herrschen? Gebet sie her, die Manner, daß wir sie toten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Saul aber sprach: Es soli auf diesen Tag niemand sterben; denn der HERR hat heute Heil gegeben in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Samuel sprach zum Volk: Kommt, la&t uns gen Gilgal gehen und das Konigreich daselbst erneuern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Da ging alles Volk gen Gilgal; und machten daselbst Saul zum Konige vor dem HERRN zu Gilgal und opferten Dankopfer vor dem HERRN. Und Saul samt alien Mannern Israels freueten sich daselbst fast sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Da sprach Samuel zum ganzen Israel: Siehe, ich habe eurer Stimme gehorchet in allem, das ihr mir gesagt habt, und habe einen Konig fiber euch gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Und nun siehe, da zeucht euer Konig vor euch her. Ich aber bin alt und grau worden, und meine Sohne sind bei euch, und ich bin vor euch hergegangen von meiner Jugend auf bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Siehe, hie bin ich, antwortet wider mich vor dem HERRN und seinem Gesalbten, ob ich jemandes Ochsen Oder Esel genommen habe, ob ich jemand habe Gewalt Oder Unrecht getan, ob ich von jemandes Hand ein Geschenk genommen habe und mir die Augen blenden lassen? so will ich\'s euch wiedergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Sie sprachen: Du hast uns keine Gewalt noch Unrecht getan und von niemandes Hand etwas genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Er sprach zu ihnen: Der HERR sei Zeuge wider euch und sein Gesalbter heutiges Tages, daß ihr nichts in meiner Hand funden habt. Sie sprachen: Ja, Zeugen sollen sie sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Und Samuel sprach zum Volk: Ja, der HERR, der Mose und Aaron gemacht hat und eure Vater aus Agyptenland gefuhret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'So tretet nun her, dafi ich mit euch rechte vor dem HERRN uber aller Wohltat des HERRN, die er an euch und euren Vatern getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Als Jakob nach Agypten kommen war, schrieen eure Vater zu dem HERRN, und er sandte Mose und Aaron, dafi sie eure Vater aus Agypten fuhreten und sie an diesem Ort wohnen ließen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Aber da sie des HERRN, ihres Gottes, vergaßen, verkaufte er sie unter die Gewalt Sisseras, des Hauptmann zu Hazor, und unter die Gewalt der Philister und unter die Gewalt des Konigs der Moabiter, die stritten wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Und schrieen aber zum HERRN und sprachen: Wir haben gesundiget, daß wir den HERRN verlassen und Baalim und Astharoth gedienet haben; nun aber errette uns von der Hand unserer Feinde, so wollen wirdirdienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Da sandte der HERR Jerubbaal, Bedan, Jephthah und Samuel und errettete euch von eurer Feinde Handen umher und ließ euch sicher wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Da ihr aber sahet, daß Nahas, der Konig der Kinder Ammon, wider euch kam, sprachet ihr zu mir: Nichtdu, sondern ein Konig soil uber uns herrschen, so doch der HERR, euer Gott, euer Konig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Nun, da habt ihr euren Konig, den ihr erwahlet und gebeten habt; denn siehe, der HERR hat einen Konig uber euch gesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Werdet ihr nun den HERRN furchten und ihm dienen und seiner Stimme gehorchen und dem Munde des HERRN nicht ungehorsam sein, so werdet beide ihr und euer Konig, der uber euch herrschet, dem HERRN, eurem Gott, folgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Werdet ihr aber des HERRN Stimme nicht gehorchen, sondern seinem Munde ungehorsam sein, wird die Hand des HERRN wider euch und wider eure Vater sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Auch tretet nun her und sehet das große Ding, das der HERR vor euren Augen tun wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, '1st nicht jetzt die Weizenernte? Ich will aber den HERRN anrufen, daß er soil donnern und regnen lassen, daß ihr inne werdet und sehen sollt das große Ubel, das ihr vor des HERRN Augen getan habt, daß ihr euch einen Konig gebeten habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Und da Samuel den HERRN anrief, ließ der HERR donnern und regnen desselben Tages. Da furchtete das ganze Volk sehr den HERRN und Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Und sprachen alle zu Samuel: Bitte fur deine Knechte den HERRN, deinen Gott, daß wir nicht sterben; denn fiber alle unsere Sunde haben wir auch das Ubel getan, daß wir uns einen Konig gebeten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel aber sprach zum Volk: Furchtet euch nicht, ihr habt zwar das Ubel alles getan; doch weichet nicht hinter dem HERRN ab, sondern dienet dem HERRN von ganzem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Und weichet nicht dem Eiteln nach; denn es nützet nicht und kann nicht erretten, weil es ein eitel Ding ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Aber der HERR verlasset sein Volk nicht urn seines großen Namens willen; denn der HERR hat angefangen, euch ihm selbst zum Volk zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Es sei aber auch feme von mir, mich also an dem HERRN zu versundigen, daß ich sollte ablassen, fur euch zu beten und euch zu lehren den guten und richtigen Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Furchtet nur den HERRN und dienet ihm treulich von ganzem Herzen; denn ihr habt gesehen, wie große Dinge er mit euch tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Werdet ihr aber ubel handeln, so werdet beide, ihr und euer Konig verloren sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul war ein Jahr Konig gewesen; und da er zwei Jahre uber Israel regieret hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'erwahlte er ihm dreitausend Mann aus Israel. Zweitausend waren mit Saul zu Michmas und auf dem Gebirge Bethel und eintausend mit Jonathan zu Gibea-Benjamin; das andere Volk aber ließ er gehen, einen jeglichen in seine Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jonathan aber schlug die Philister in ihrem Lager, das zu Gibea war; das kam vor die Philister. Und Saul liefi die Posaune blasen im ganzen Lande und sagen: Das lassetdie Ebraer horen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Und ganz Israel horete sagen: Saul hat der Philister Lager geschlagen; denn Israel stank vor den Philistern. Und alles Volk schrie Saul nach gen Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Da versammelten sich die Philister, zu streiten mit Israel, dreißigtausend Wagen, sechstausend Reiter und sonst Volk, so viel wie Sand am Rande des Meers, und zogen herauf und lagerten sich zu Michmas, gegen Morgen vor Beth-Aven.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Da das sahen die Manner Israels, daß sie in Noten waren (denn dem Volk war bange), verkrochen sie sich in die Hohlen und Klüfte und Felsen und Locher und Gruben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Die Ebraer aber gingen uber den Jordan ins Land Gad und Gilead. Saul aber war noch zu Gilgal, und alles Volk ward hinter ihm zag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Da harrete er sieben Tage auf die Zeit, von Samuel bestimmt. Und da Samuel nicht kam gen Gilgal, zerstreuete sich das Volk von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Da sprach Saul: Bringet mir her Brandopfer und Dankopfer! Und er opferte Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Alser aber das Brandopfer vollendet hatte, siehe, da kam Samuel. Da ging Saul hinaus ihm entgegen, ihn zu segnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel aber sprach: Was hastdu gemacht? Saul antwortete: Ich sah, daß das Volk sich von mir zerstreuete, und du kamest nicht zu bestimmter Zeit, und die Philister waren versammelt zu Michmas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Da sprach ich: Nunwerden die Philister zu mir herabkommen gen Gilgal, und ich habe das Angesicht des HERRN nicht erbeten; da wagte ich\'s und opferte Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel aber sprach zu Saul: Du hasttoricht getan und nicht gehalten des HERRN, deines Gottes, Gebot, das er dir geboten hat; denn er hatte dein Reich bestatiget fiber Israel fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Aber nun wird dein Reich nicht bestehen. Der HERR hat ihm einen Mann ersucht nach seinem Herzen, dem hat der HERR geboten, Furstzu sein uber sein Volk; denn du hast des HERRN Gebot nicht gehalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Und Samuel machte sich auf und ging von Gilgal gen Gibea-Benjamin. Aber Saul zahlete das Volk, das bei ihm war, bei sechshundert Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul aber und sein Sohn Jonathan und das Volk, das bei ihm war, blieben auf dem Hügel Benjamin. Die Philister aber hatten sich gelagert zu Michmas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Und aus dem Lager der Philister zogen drei Haufen, das Land zu verheeren. Einer wandte sich auf die Strafie gen Ophra, ins Land Sual;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'der andere wandte sich auf die Stralie Beth- Horon; der dritte wandte sich auf die Stralie, die da langet an das Tal Zeboim, an der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Es ward aber kein Schmied im ganzen Lande Israel erfunden, denn die Philister gedachten, die Ebraer mochten Schwert und Spiel?, machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Und mußte ganz Israel hinabziehen zu den Philistern, wenn jemand hatte eine Pflugschar, Haue, Beil Oder Sense zu scharfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Und die Schneiden an den Sensen und Hauen und Gabeln und Beilen waren abgearbeitet und die Stacheln stumpf worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Da nun der Streittag kam, ward kein Schwert noch Spiel? funden in des ganzen Volks Hand, das mit Saul und Jonathan war; nur Saul und sein Sohn hatten Waffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Und der Philister Lager zog heraus vor Michmas fiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Es begab sich eines Tages, daß Jonathan, der Sohn Sauls, sprach zu seinem Knaben, der sein Waffentrager war: Komm, lal? uns hinubergehen zu der Philister Lager, das da drüben ist. Und sagte es seinem Vater nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul aber blieb zu Gibea am Ende unter einem Granatenbaum, der in der Vorstadt war; und des Volks, das bei ihm war, war bei sechshundert Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Und Ahia, der Sohn Ahitobs, Ikabods Bruder, Pinehas Sohn, des Sohns Elis, war Priesterdes HERRN zu Silo und trug den Leibrock an. Das Volk wul?te auch nicht, daß Jonathan war hingegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Es waren aber an dem Wege, da Jonathan suchte, hinuberzugehen zu der Philister Lager, zween spitze Felsen, einer diesseits, der andere jenseits; der eine hiel? Bozez, der andere Senne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Und einer sah von Mitternacht gegen Michmas und der andere von Mittag gegen Gaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Und Jonathan sprach zu seinem Waffentrager: Komm, Laß uns hinubergehen zu dem Lager dieser Unbeschnittenen, vielleicht wird der HERR etwas durch uns ausrichten; denn es ist dem HERRN nicht schwer, durch viel oderwenig helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Da antwortete ihm sein Waffentrager: Tue alles, was in deinem Herzen ist; fahre hin, siehe, ich bin mit dir, wie dein Herz will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonathan sprach: Wohlan, wenn wir hinuberkommen zu den Leuten und ihnen ins Gesicht kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'werden sie dann sagen: Stehet stille, bis wir an euch gelangen, so wollen wir an unserm Ort stehen bleiben und nicht zu ihnen hinaufgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Werden sie aber sagen: Kommt zu uns herauf, so wollen wir zu ihnen hinaufsteigen, so hat sie uns der HERR in unsere Hande gegeben. Und das soil uns zum Zeichen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Da sie nun der Philister Lager beide ins Gesicht kamen, sprachen die Philister: Siehe, die Ebraer sind aus den Lochern gegangen, darin sie sich verkrochen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Und die Manner im Lager antworteten Jonathan und seinem Waffentrager und sprachen: Kommt herauf zu uns, so wollen wir\'s euch wohl lehren. Da sprach Jonathan zu seinem Waffentrager: Steige mir nach; der HERR hat sie gegeben in die Hande Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Und Jonathan kletterte mit Handen und mit Fußen hinauf, und sein Waffentrager ihm nach. Da fielen sie vor Jonathan danieder, und sein Waffentrager würgete ihm immer nach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'also daß die erste Schlacht, die Jonathan und sein Waffentrager tat, war bei zwanzig Mann, beinahe eine halbe Hufe Ackers, die ein Joch treibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Und es kam ein Schrecken ins Lager auf dem Felde und im ganzen Volk des Lagers, und die streifenden Rotten erschraken auch, also daß das Land erbebete; denn es war ein Schrecken von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Und die Wachter Sauls zu Gibea-Benjamin sahen, daß der Haufe zerrann und verlief sich und ward zerschmissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Saul sprach zu dem Volk, das bei ihm war: Zahlet und besehet, wer von uns sei weggegangen. Und da sie zahleten, siehe, da war Jonathan und sein Waffentrager nicht da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Da sprach Saul zu Ahia: Bringe herzu die Lade Gottes (denn die Lade Gottes war zu der Zeit bei den Kindern Israel).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Und da Saul noch redete mit dem Priester, da ward das Getummel und das Laufen in der Philister Lager großer. Und Saul sprach zum Priester: Zeuch deine Hand ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Und Saul rief und alles Volk, das mit ihm war, und kamen zum Streit; und siehe, da ging eines jeglichen Schwert wider den andern, und war ein sehr groß Getummel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Auch die Ebraer, die vorhin bei den Philistern gewesen waren und mit ihnen im Lager hinaufgezogen waren umher, taten sich zu Israel, die mit Saul und Jonathan waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Und alle Manner von Israel, die sich auf dem Gebirge Ephraim verkrochen hatten, da sie horeten, daß die Philister flohen, strichen hinter ihnen her im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Also half der HERR zu der Zeit Israel. Und der Streit wahrete bis gen Beth-Aven.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Und da die Manner Israels matt waren desselben Tages, beschwor Saul das Volk und sprach: Verflucht sei jedermann, wer etwas isset bis zu Abend, daß ich mich an meinen Feinden rache! Da aß das ganze Volk nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Und das ganze Land kam in den Wald. Es war aber Honig im Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Und da das Volk hineinkam in den Wald, siehe, da floß der Honig. Aber niemand tat desselben mit der Hand zu seinem Munde; denn das Volk furchtete sich vor dem Eide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonathan aber hatte nicht gehoret, daß sein Vater das Volk beschworen hatte, und reckte seinen Stab aus, den er in seiner Hand hatte, und tunkte mit der Spitze in den Honigseim und wandte seine Hand zu seinem Munde; da wurden seine Augen wacker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Da antwortete einer des Volks und sprach: Dein Vater hat das Volk beschworen und gesagt: Verflucht sei jedermann, der heute etwas isset! Und das Volk war matt worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Da sprach Jonathan: Mein Vater hat das Land geirret; sehet, wie wacker sind meine Augen worden, daß ich ein wenig dieses Honigs gekostet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Weil aber das Volk heute nicht hat müssen essen von der Beute seiner Feinde, die es funden hat, so hat auch nun die Schlacht nicht großer werden konnen wider die Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Sie schlugen aber die Philister des Tages von Michmas bis gen Ajalon. Und das Volk ward sehr matt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Und das Volk richtete die Ausbeute zu und nahmen Schafe und Rinder und Kalber; und schlachteten\'s auf der Erde und aßen\'s so blutig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Da verkündigte man Saul: Siehe, das Volk versundiget sich an dem HERRN, daß es Blut isset. Er sprach: Ihr habt ubel getan; walzet herzu mirjetzt einen großen Stein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Und Saul sprach weiter: Zerstreuet euch unter das Volk und saget ihnen, daß ein jeglicher seinen Ochsen und seine Schafe zu mir bringe; und schlachtet es allhie, daß ihr\'s esset und euch nicht versundiget an dem HERRN mit dem Blut essen. Da brachte alles Volk ein jeglicher seinen Ochsen mit seiner Hand herzu des Nachts und schlachteten es daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Und Saul bauete dem HERRN einen Altar. Das ist der erste Altar, den er dem HERRN bauete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Und Saul sprach: Laßt uns hinabziehen den Philistern nach bei der Nacht und sie berauben, bis daß licht Morgen wird, daß wir niemand von ihnen überlassen. Sie antworteten: Tue alles, was dir gefallt. Aber der Priester sprach: Laßt uns hieher zu Gott nahen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Und Saul fragte Gott: Soil ich hinabziehen, den Philistern nach? und willst du sie geben in Israels Hande? Aber er antwortete ihm zu der Zeit nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Da sprach Saul: Laßt herzutreten alle Haufen es Volks, und erfahret und sehet, an welchem die Sünde sei zu dieser Zeit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'denn so wahr der HERR lebet, der Heiland Israels, und ob sie gleich an meinem Sohn Jonathan ware, so soli er sterben. Und niemand antwortete ihm aus dem ganzen Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Und er sprach zu dem ganzen Israel: Seid ihr auf jener Seite; ich und mein Sohn Jonathan wollen sein auf dieser Seite. Das Volk sprach zu Saul: Tue, was dir gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Und Saul sprach zu dem HERRN, dem Gott Israels: Schaffe Recht! Da ward Jonathan und Saul getroffen; aber das Volk ging frei aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sprach: Werfet über mich und meinen Sohn Jonathan. Da ward Jonathan getroffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Und Saul sprach zu Jonathan: Sage mir, was hast du getan? Jonathan sagte es ihm und sprach: Ich habe ein wenig Honigs gekostet mitdem Stabe, den ich in meiner Hand hatte; und siehe, ich muß darum sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Da sprach Saul: Gotttue mir dies und das, Jonathan, du mul Jt des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Aber das Volk sprach zu Saul: Sollte Jonathan sterben, der ein solch groß Heil in Israel getan hat? Das sei feme! So wahr der HERR lebet, es soil kein Haar von seinem Haupt auf die Erde fallen; denn Gott hat\'s heute durch ihn getan. Also erlosete das Volk Jonathan, daß er nicht sterben mußte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Da zog Saul herauf von den Philistern, und die Philister zogen an ihren Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Aber da Saul das Reich uber Israel eingenommen hatte, stritt er wider alle seine Feinde umher: wider die Moabiter, wider die Kinder Ammon, wider die Edomiter, wider die Konige Zobas, wider die Philister; und wo er sich hinwandte, da übte er Strafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Und machte ein Heer und schlug die Amalekiter und errettete Israel von der Hand aller, die sie zwackten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Saul aber hatte Sohne: Jonathan, Iswi, Malchisua. Und seine zwo Tochter hießen also: die erstgeborne Merob und die jungste Michal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Und das Weib Sauls hiefi Ahinoam, eine Tochter Ahimaaz. Und sein Feldhauptmann hieß Abner, ein Sohn Ners, Sauls Vetters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Kis aber war Sauls Vater; Ner aber, Abners Vater, war ein Sohn Abiels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Es war aber ein harter Streit wider die Philister, solange Saul iebte. Und wo Saul sah einen starken und rustigen Mann, den nahm erzu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel aber sprach zu Saul: Der HERR hat mich gesandt, daß ich dich zum Konig salbete uber sein Volk Israel; so hore nun die Stimme der Worte des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'So spricht der HERR Zebaoth: Ich habe bedacht, was Amalek Israel tat, und wie er ihm den Weg verlegte, da er aus Agypten zog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'So zeuch nun hin und schlage die Amalekiter und verbanne sie mit allem, das sie haben. Schone seiner nicht, sondern tote beide Mann und Weib, Kinder und Sauglinge, Ochsen und Schafe, Kamele und Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul ließ solches vor das Volk kommen; und er zahlete sie zu Thelaim, zweihunderttausend Fußvolks und zehntausend Mann aus Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Und da Saul kam zu der Amalekiter Stadt, machte er einen Hinterhalt am Bach');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'und ließ dem Keniter sagen: Gehet hin, weichet und ziehet herab von den Amalekitern, daß ich euch nicht mit ihnen aufraume; denn ihr tatet Barmherzigkeit an alien Kindern Israel, da sie aus Agypten zogen. Also machten sich die Keniter von den Amalekitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Da schlug Saul die Amalekiter von Hevila an bis gen Sur, die vor Agypten liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Und griff Agag, der Amalekiter Konig, lebendig, und alles Volk verbannete er mit des Schwerts Scharfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Aber Saul und das Volk schonte des Agag, und was gute Schafe und Rinder und gemastet war, und der Lammer und alles, was gut war, und wollten\'s nicht verbannen; was aber schnode und untuchtig war, das verbanneten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Da geschah des HERRN Wort zu Samuel und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Es reuet mich, daß ich Saul zum Konige gemacht habe; denn er hat sich hinter mir abgewandt und meine Worte nicht erfüllet. Des ward Samuel zornig und schrie zu dem HERRN die ganze Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Und Samuel machte sich frühe auf, daß er Saul am Morgen begegnete. Und ihm ward angesagt, daß Saul gen Karmel kommen ware und hatte ihm ein Siegeszeichen aufgerichtet und ware herumgezogen und gen Gilgal hinabkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Als nun Samuel zu Saul kam, sprach Saul zu ihm: Gesegnet seiest du dem HERRN! Ich habe des HERRN Wort erfüllet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel antwortete: Was istdenn das fur ein Bloken der Schafe in meinen Ohren und ein Brullen der Rinder, die ich hore?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul sprach: Von den Amalekitern haben sie sie gebracht; denn das Volk verschonete der besten Schafe und Rinder urn des Opfers willen des HERRN, deines Gottes; das andere haben wir verbannet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Samuel aber antwortete Saul: Laß dir sagen, was der HERR mit mir geredet hat diese Nacht. Er sprach: Sage her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sprach: Ist\'s nicht also, da du klein warest vor deinen Augen, wurdest du das Haupt unter den Stammen Israels, und der HERR salbte dich zum Konig uber Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Und der HERR sandte dich auf den Weg und sprach: Zeuch hin und verbanne die Sunder, die Amalekiter, und streite wider sie, bis du sie vertilgest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Warum hast du nicht gehorchet des HERRN Stimme, sondern hast dich zum Raube gewandt und ubel gehandelt vor den Augen des HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul antwortete Samuel: Habe ich doch der Stimme des HERRN gehorchet und bin hingezogen des Weges, den mich der HERR sandte; und habe Agag, der Amalekiter Konig, gebracht und die Amalekiter verbannet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Aber das Volk hat des Raubes genommen, Schafe und Rinder, das Beste unter dem Verbanneten, dem HERRN, deinem Gott, zu opfern in Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel aber sprach: Meinest du, daß der HERR Lust habe am Opfer und Brandopfer als am Gehorsam der Stimme des HERRN? Siehe, Gehorsam ist besser denn Opfer und Aufmerken besser denn das Fett von Widdern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'denn Ungehorsam isteine Zaubereisunde, und Widerstreben ist Abgotterei und Gotzendienst. Weil du nun des HERRN Wort verworfen hast, hat er dich auch verworfen, daß du nicht Konig seiest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Da sprach Saul zu Samuel: Ich habe gesundiget, daß ich des HERRN Befehl und deine Worte übergangen habe; denn ich furchtete das Volk und gehorchte ihrer Stimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Und nun vergib mirdie Sunde und kehre mit mir um, daß ich den HERRN anbete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sprach zu Saul: Ich will nicht mit dir umkehren; denn du hast des HERRN Wort verworfen, und der HERR hat dich auch verworfen, daß du nicht Konig seiest liber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Und als sich Samuel umwandte, daß er wegginge, ergriff er ihn bei einem Zipfel seines Rocks, und er zerrifi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Da sprach Samuel zu ihm: Der HERR hat das Konigreich Israels heute von dir gerissen und deinem Nachsten gegeben, der besser ist denn du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Auch lugt der Held in Israel nicht und gereuet ihn nicht; denn er ist nicht ein Mensch, daß ihn etwas gereuen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Er aber sprach: Ich habe gesundiget; aber ehre mich doch jetzt vor den Altesten meines Volks und vor Israel; und kehre mit mir um, daß ich den HERRN, deinen Gott, anbete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Also kehrete Samuel um und folgte Saul nach, daß Saul den HERRN anbetete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Samuel aber sprach: Lali her zu mir bringen Agag, der Amalekiter Konig! Und Agag ging zu ihm getrost und sprach: Also muli man des Todes Bitterkeit vertreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel sprach: Wie dein Schwert Weiber ihrer Kinder beraubet hat, also soil auch deine Mutter ihrer Kinder beraubet sein unter den Weibern. Also zerhieb Samuel den Agaq zu Stricken vor dem HERRN in Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Und Samuel ging hin gen Ramath; Saul aber zog hinauf zu seinem Hause zu Gibea-Saul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Und Samuel sah Saul furder nicht mehr bis an den Tag seines Todes. Aber doch trug Samuel Leid um Saul, daß den HERRN gereuet hatte, daß er Saul zum Konige uber Israel gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Und der HERR sprach zu Samuel: Wie lange tragst du Leid um Saul, den ich verworfen habe, daß er nicht Konig sei uber Israel? Fülle dein Horn mit 01 und gehe hin, ich will dich senden zu dem Bethlehemiter Isai; denn unter seinen Sdhnen habe ich mir einen Konig ersehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel aber sprach: Wie soil ich hingehen? Saul wird\'s erfahren und mich erwurgen. Der HERR sprach: Nimm ein Kalb von den Rindern zu dir und sprich: Ich bin kommen, dem HERRN zu opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Und sollst Isai zum Opfer laden; da will ich dir weisen, was du tun sollst, daß du mir salbest, welchen ich dirsagen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel tat, wie ihm der HERR gesagt hatte, und kam gen Bethlehem. Da entsetzten sich die Altesten der Stadt und gingen ihm entgegen und sprachen: Ist\'s Friede, daß du kommest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Er sprach: Ja, ich bin kommen, dem HERRN zu opfern; heiliget euch und kommet mit mir zum Opfer! Und er heiligte den Isai und seine Sohne und lud sie zum Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Da sie nun hereinkamen, sah er den Eliab an und gedachte, ob der vor dem HERRN sei sein Gesalbter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Aber der HERR sprach zu Samuel: Siehe nicht an seine Gestalt noch seine grolie Person; ich habe ihn verworfen. Denn es gehet nicht, wie ein Mensch siehet. Ein Mensch siehet, was vor Augen ist, der HERR aber siehet das Herz an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Da rief Isai dem Abinadab und lieli ihn vor Samuel ubergehen. Und er sprach: Diesen hat der HERR auch nicht erwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Da lieli Isai vorübergehen Samma. Er aber sprach: Diesen hat der HERR auch nicht erwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Da lieli Isai seine sieben Sohne vor Samuel ubergehen. Aber Samuel sprach zu Isai: Der HERR hat der keinen erwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Und Samuel sprach zu Isai: Sind das die Knaben alle? Er sprach: Es ist noch ubrig der Kleinste; und siehe, er hütet der Schafe. Da sprach Samuel zu Isai: Sende hin und lali ihn holen; denn wirwerden uns nicht setzen, bis er hieher komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Da sandte er hin und lieli ihn holen. Und erwar braunlich, mit schonen Augen und guter Gestalt. Und der HERR sprach: Auf! und salbe ihn; denn der ist\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Da nahm Samuel sein Olhorn und salbete ihn mitten unter seinen Brudern. Und der Geist des HERRN geriet uber David von dem Tage an und furder. Samuel aber machte sich auf und ging gen Rama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Der Geist aber des HERRN wich von Saul, und ein boser Geist vom HERRN machte ihn sehr unruhig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Da sprachen die Knechte Sauls zu ihm: Siehe, ein boser Geist von Gott macht dich sehr unruhig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Unser Herr sage seinen Knechten, die vor ihm stehen, daß sie einen Mann suchen, der auf der Harfe wohl spielen konne, auf daß, wenn der bose Geist Gottes uber dich kommt, er mit seiner Hand spiele, daß besser mit dir werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Da sprach Saul zu seinen Knechten: Sehet nach einem Manne, deres wohl kann auf Saitenspiel, und bringet ihn zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Da antwortete der Knaben einer und sprach: Siehe, ich habe gesehen einen Sohn Isais, des Bethlehemiten, der kann wohl auf Saitenspiel; ein rustiger Mann und streitbar und verstandig in Sachen und schon, und der HERR ist mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Da sandte Saul Boten zu Isai und lied ihm sagen: Sende deinen Sohn David zu mir, der bei den Schafen ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Da nahm Isai einen Esel mit Brot und ein Legel Weins und ein Ziegenbocklein und sandte es Saul durch seinen Sohn David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Also kam David zu Saul und dienete vor ihm, und er gewann ihn sehr lieb, und er ward sein Waffentrager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Und Saul sandte zu Isai und lied ihm sagen: Lad David vor mir bleiben, denn er hat Gnade funden vor meinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Wenn nun der Geist Gottes über Saul kam, so nahm David die Harfe und spielete mit seiner Hand; so erquickte sich Saul, und ward besser mit ihm, und der bose Geist wich von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Die Philister sammelten ihre Heere zum Streit und kamen zusammen zu Socho in Juda und lagerten sich zwischen Socho und Aseka, am Ende Damim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Aber Saul und die Manner Israels kamen zusammen und lagerten sich im Eichgrunde; und rusteten sich zum Streit gegen die Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Und die Philister stunden auf einem Berge jenseits und die Israeliten auf einem Berge diesseits, daß ein Tal zwischen ihnen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Da trat hervor aus den Lagern der Philister ein Riese mit Namen Goliath von Gath, sechs Ellen und einer Hand breit hoch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'und hatte einen ehernen Helm auf seinem Haupt und einen schuppichten Panzer an, und das Gewicht seines Panzers war fünftausend Sekel Erzes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'und hatte eherne Beinharnische an seinen Schenkeln und einen ehernen Schild auf seinen Schultern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Und der Schaft seines Spielies war wie ein Weberbaum und das Eisen seines Spielies hatte sechshundert Sekel Eisens und sein Schildtrager ging vor ihm her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Und er stund und rief zu dem Zeuge Israels und sprach zu ihnen: Was seid ihr ausgezogen, euch zu rüsten in einen Streit? Bin ich nicht ein Philister und ihr Sauls Knechte? Erwahlet einen unter euch, der zu mir herabkomme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Vermag er wider mich zu streiten, und schlagt mich, so wollen wir eure Knechte sein; vermag ich aber wider ihn und schlage ihn, so sollt ihr unsere Knechte sein, daß ihr uns dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Und der Philister sprach: Ich habe heutigestages dem Zeuge Israels Hohn gesprochen; gebt mir einen und lafit uns miteinander streiten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Da Saul und ganz Israel diese Rede des Phüisters horeten, entsetzten sie sich und furchteten sich sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David aber war eines ephrathischen Mannes Sohn, von Bethlehem-Juda, der hiefi Isai, der hatte acht Sohne und war ein alter Mann zu Sauls Zeiten und war betagt unter den Mannern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Und die drei groliten Sohne Isais waren mit Saul in Streit gezogen und hielien mit Namen: Eliab, der erstgeborne, Abinadab, der andere, und Samma, der dritte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David aber war der jungste. Da aber die drei altesten mit Saul in den Krieg zogen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'ging David wiederum von Saul, daß erder Schafe seines Vaters hütete zu Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Aber der Philister trat herzu fruhe morgens und abends und stellete sich dar vierzig Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Isai aber sprach zu seinem Sohn David: Nimm fur deine Bruder diese Epha Sangen und diese zehn Brote und lauf in das Heer zu deinen Brudern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'und diese zehn frischen Kase, und bringe sie dem Hauptmann; und besuche deine Bruder, ob\'s ihnen wohlgehe, und nimm, was sie dir befehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul aber und sie und alle Manner Israels waren im Eichgrunde und stritten wider die Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Da machte sich David des Morgens fruhe auf und lieli die Schafe dem Huter und trug und ging hin, wie ihm Isai geboten hatte, und kam zur Wagenburg. Und das Heer war ausgezogen und hatte sich gerustet, und schrieen im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Denn Israel hatte sich gerustet, so waren die Philister wider ihren Zeug auch gerustet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Da lieli David das Gefali, das er trug, unter dem Huter der Gefalie und lief zu dem Zeuge; und ging hinein und grulite seine Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Und da er noch mit ihnen redete, siehe, da trat herauf der Riese mit Namen Goliath, der Philister von Gath, aus der Philister Zeug und redete wie vorhin; und David horete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Aberjedermann in Israel, wenn erden Mann sah, floh er vor ihm und furchtete sich sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Und jedermann in Israel sprach: Habt ihr den Mann gesehen herauftreten? Denn er ist heraufgetreten, Israel Hohn zu sprechen. Und wer ihn schlagt, den will der Konig sehr reich machen und ihm seine Tochter geben und will seines Vaters Haus frei machen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Da sprach David zu den Mannern, die bei ihm stunden: Was wird man dem tun, derdiesen Philister schlagt und die Schande von Israel wendet? Denn wer ist der Philister, dieser Unbeschnittene, der den Zeug des lebendigen Gottes hohnet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Da sagte ihm das Volk wie vorhin: So wird man tun dem, der ihn schlagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Und Eliab, sein groliter Bruder horete ihn reden mit den Mannern und ergrimmete mit Zorn wider David und sprach: Warum bistdu herabkommen? und warum hast du die wenigen Schafe dort in der Wüste verlassen? Ich kenne deine Vermessenheitwohl und deines Herzens Bosheit. Denn du bist herabkommen, daß du den Streit sehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David antwortete: Was habe ich denn nun getan? 1st mir\'s nicht befohlen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Und wandte sich von ihm gegen einen andern und sprach, wie er vorhin gesagt hatte. Da antwortete ihm das Volk wie vorhin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Und da sie die Worte horeten, die David sagte, verkundigten sie es vor Saul, und er liefi ihn holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Und David sprach zu Saul: Es entfalle keinem Menschen das Herz um deswillen; dein Knecht soil hingehen und mit dem Philister streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul aber sprach zu David: Du kannst nicht hingehen wider diesen Philister, mit ihm zu streiten; denn du bist ein Knabe, dieser aber ist ein Kriegsmann von seiner Jugend auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'David aber sprach zu Saul: Dein Knecht hütete der Schafe seines Vaters, und es kam ein Lowe und ein Bar und trug ein Schaf weg von der Herde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Und ich lief ihm nach und schlug ihn und errettete es aus seinem Maul. Und da er sich uber mich machte, ergriff ich ihn bei seinem Bart und schlug ihn und totete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Also hat dein Knecht geschlagen beide den Lowen und den Baren. So soli nun dieser Philister, der Unbeschnittene, sein gleichwie deren einer, denn er hat geschandet den Zeug des lebendigen Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Und David sprach: Der HERR, der mich von dem Lowen und Baren errettet hat, der wird mich auch erretten von diesem Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Und Saul sprach zu David: Gehe hin, der HERR sei mit dir! Und Saul zog David seine Kleider an und setzte ihm einen ehernen Helm auf sein Haupt und legte ihm einen Panzer an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Und David gurtete sein Schwert uber seine Kleider und fing an zu gehen, denn er hatte es nie versucht. Da sprach David zu Saul: Ich kann nicht also gehen, denn ich bin\'s nicht gewohnt; und legte es von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Und nahm seinen Stab in seine Hand und erwahlte funf glatte Steine aus dem Bach und tat sie in die Hirtentasche, die er hatte, und in den Sack, und nahm die Schleuder in seine Hand und machte sich zu dem Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Und der Philister ging auch einher und machte sich zu David, und sein Schildtrager vor ihm her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Da nun der Philister sah und schauete David an, verachtete er ihn. Denn er war ein Knabe, braunlich und schon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Und der Philister sprach zu David: Bin ich denn ein Hund, daß du mit Stecken zu mir kommst? Und fluchte dem David bei seinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Und sprach zu David: Komm herzu mir, ich will dein Fleisch geben den Vogeln unterdem Himmel und den Tieren auf dem Felde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'David aber sprach zu dem Philister: Du kommst zu mir mit Schwert, Spieli und Schild; ich aber komme zu dir im Namen des HERRN Zebaoth, des Gottes des Zeuges Israels, den du gehohnet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Heutigestages wird dich der HERR in meine Hand überantworten, daß ich dich schlage und nehme dein Haupt von dir und gebe den Leichnam des Heers der Philister heute den Vogeln unterdem Himmel und dem Wild auf Erden, daß, alles Land inne werde, daü Israel einen Gott hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'und daß alle diese Gemeine inne werde, daß der HERR nicht durch Schwert noch Spieü hilft; denn der Streit ist des HERRN, und wird euch geben in unsere Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Da sich nun der Philister aufmachte, ging daher und nahete sich gegen David, eilete David und lief vom Zeuge gegen den Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Und David tat seine Hand in die Tasche und nahm einen Stein daraus und schleuderte und traf den Philister an seine Stirn, daü der Stein in seine Stirn fuhr, und er zur Erde fiel auf sein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Also überwand David den Philister mit der Schleuder und mit dem Stein; und schlug ihn und totete ihn. Und da David kein Schwert in seiner Hand hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'lief er und tratzu dem Philister und nahm sein Schwert und zog es aus der Scheide und totete ihn und hieb ihm den Kopf damit ab. Da aber die Philister sahen, daß ihr Starkster tot war, flohen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Und die Manner Israels und Judas machten sich auf und riefen und jagten den Philistern nach, bis man kommt ins Tal, und bis an die Tore Ekrons. Und die Philister Helen erschlagen auf dem Wege zu den Toren bis gen Gath und gen Ekron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Und die Kinder Israel kehreten um von dem Nachjagen der Philister und beraubten ihr Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David aber nahm des Philisters Haupt und brachte es gen Jerusalem; seine Waffen aber legte er in seine Hutte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Da aber Saul David sah ausgehen wider den Philister, sprach erzu Abner, seinem Feldhauptmann: Wes Sohn ist der Knabe? Abner aber sprach: So wahr deine Seele lebet, Konig, ich weili nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Der Konig sprach: So frage danach, wes Sohn der Jungling sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Da nun David wiederkam von der Schlacht des Philisters, nahm ihn Abner und brachte ihn vor Saul; und er hatte des Philisters Haupt in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Und Saul sprach zu ihm: Wes Sohn bist du, Knabe? David sprach: Ich bin ein Sohn deines Knechts Isai, des Bethlehemiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Und da er hatte ausgeredet mit Saul, verband sich das Herz Jonathans mit dem Herzen Davids; und Jonathan gewann ihn lieb wie sein eigen Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Und Saul nahm ihn des Tages und liefi ihn nicht wieder zu seines Vaters Haus kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Und Jonathan und David machten einen Bund miteinander; denn er hatte ihn lieb wie sein eigen Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Und Jonathan zog aus seinen Rock, den er anhatte, und gab ihn David, dazu seinen Mantel, sein Schwert, seinen Bogen und seinen Gurtel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Und David zog aus, wohin ihn Saul sandte, und hielt sich kluglich. Und Saul setzte ihn uber die Kriegsleute; und ergefiel wohl allem Volk, auch den Knechten Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Es begab sich aber, da erwiederkommen war von des Philisters Schlacht, daß die Weiber aus alien Stadten Israels waren gegangen mit Gesang und Reigen dem Konige Saul entgegen mit Pauken, mit Freuden und mit Geigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Und die Weiber sangen gegeneinander und spielten und sprachen: Saul hat tausend geschlagen, aber David zehntausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Da ergrimmete Saul sehr, und gefiel ihm das Wort ubel und sprach: Sie haben David zehntausend gegeben und mir tausend; das Konigreich will noch seinwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Und Saul sah David sauer an von dem Tage und fortan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Des andern Tages geriet der bose Geist von Gott uber Saul und weissagete daheim im Hause; David aber spielte auf den Saiten mit seiner Hand, wie er taglich pflegte. Und Saul hatte einen Spied in der Hand');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'und schoft ihn und gedachte: Ich will David an die Wand spieften. David aber wandte sich zweimal von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Und Saul furchtete sich vor David; denn der HERR war mit ihm und war von Saul gewichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Da tat ihn Saul von sich und setzte ihn zum Fursten uber tausend Mann; und erzog aus und ein vor dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Und David hielt sich kluglich in all seinem Tun; und der HERR war mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Da nun Saul sah, dad ersich so kluglich hielt, scheuete er sich vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Aberganz Israel und Juda hatte David lieb; denn er zog aus und ein vor ihnen her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Und Saul sprach zu David: Siehe, meine groftte Tochter Merob will ich dir zum Weibe geben; sei nur freudig und fuhre des HERRN Kriege! Denn Saul gedachte: Meine Hand soil nicht an ihm sein, sondern die Hand der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David aber antwortete Saul: Werbin ich, und was ist mein Leben und Geschlecht meines Vaters in Israel, dad ich des Konigs Eidam werden soli?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Da aber die Zeit kam, dad Merob, die Tochter Sauls, sollte David gegeben werden, ward sie Adriel, dem Meholathiter, zum Weibe gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Aber Michal, Sauls Tochter, hatte den David lieb. Da das Saul angesagt ward, sprach er: Das ist recht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Ich will sie ihm geben, dad sie ihm zum Fall gerate, und der Philister Hande uber ihn kommen. Und sprach zu David: Du sollst heute mit der andern mein Eidam werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Und Saul gebot seinen Knechten: Redet mit David heimlich und sprechet: Siehe, der Konig hat Lust zu dir, und alle seine Knechte lieben dich; so sei nun des Konigs Eidam!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Und die Knechte Sauls redeten solche Worte vor den Ohren Davids. David aber sprach: Dünket euch das ein Geringes sein, des Konigs Eidam zu sein? Ich aber bin ein armer, geringer Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Und die Knechte Sauls sagten ihm wieder und sprachen: Solche Worte hat David geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul sprach: So saget zu David: Der Konig begehret keine Morgengabe ohne hundert Vorhaute von den Philistern, daß man sich rache an des Konigs Feinden. Denn Saul trachtete, David zu fallen durch der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Da sagten seine Knechte David an solche Worte und deuchte David die Sache gut sein, daß er des Konigs Eidam wurde. Und die Zeit war noch nicht aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Da machte sich David auf und zog hin mit seinen Mannern und schlug unter den Philistern zweihundert Mann. Und David brachte ihre Vorhaute und vergnugte dem Konige die Zahl, daß er des Konigs Eidam wurde. Da gab ihm Saul seine Tochter Michal zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Und Saul sah und merkte, daß der HERR mit David war. Und Michal, Sauls Tochter, hatte ihn lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Da furchtete sich Saul noch mehr vor David und ward sein Feind sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Und da der Philister Fursten auszogen, handelte David kluglicher denn alle Knechte Sauls, wenn sie auszogen, daß sein Name hochgepreiset ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul aber redete mit seinem Sohn Jonathan und mit alien seinen Knechten, daß sie David sollten toten. Aber Jonathan, Sauls Sohn, hatte David sehr lieb;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'und verkundigte es ihm und sprach: Mein Vater Saul trachtet danach, daß er dich tote. Nun, so bewahre dich morgen und bleibe verborgen und verstecke dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ich aber will herausgehen und neben meinem Vater stehen auf dem Feide, da du bist, und von dir mit meinem Vater reden; und was ich sehe, will ich dir kund tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Und Jonathan redete das Beste von David mit seinem Vater Saul und sprach zu ihm: Es versundige sich der Konig nicht an seinem Knechte David; denn er hat keine Sünde wider dich getan, und sein Tun ist dir sehr nütze;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'und er hat sein Leben in seine Hand gesetzt und schlug den Philister, und der HERR tat ein graft Heil dem ganzen Israel. Das hast du gesehen und dich des gefreuet. Warum willst du dich denn an unschuldigem Blut versundigen, daß du David ohne Ursache totest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Da gehorchte Saul der Stimme Jonathans und schwur: So wahr der HERR lebet, er soil nicht sterben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Da rief Jonathan David und sagte ihm alle diese Worte; und brachte ihn zu Saul, daß er vor ihm war wie vorhin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Es erhub sich aber wieder ein Streit; und David zog aus und stritt wider die Philister und tat eine grofie Schlacht, daß sie vor ihm flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Aber der bose Geist vom HERRN kam uber Saul; und er sali in seinem Hause und hatte einen Spieti in seiner Hand; David aber spielte auf den Saiten mit der Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Und Saul trachtete, David mit dem Spieli an die Wand zu spietien. Er aber rili sich von Saul, und der Spieti fuhr in die Wand. David aber floh und entrann dieselbige Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Saul sandte aber Boten zu Davids Haus, dati sie ihn bewahreten und toteten am Morgen. Das verkundigte dem David sein Weib Michal und sprach: Wirst du nicht diese Nacht deine Seele erretten, so mulit du morgen sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Da liefi ihn Michal durchs Fenster hernieder, dati er hinging, entfloh und entrann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Und Michal nahm ein Bild und legte es ins Bett; und legte ein Ziegenfell zu seinen Haupten und deckte es mit Kleidern zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Da sandte Saul Boten, daß sie David holeten. Sie aber sprach: Er ist krank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Saul aber sandte Boten, David zu besehen, und sprach: Bringet ihn herauf zu mir mit dem Bette, daß er getotet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Da nun die Boten kamen, siehe, da lag das Bild im Bette und ein Ziegenfell zu seinen Haupten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Da sprach Saul zu Michal: Warum hast du mich betrogen und meinen Feind gelassen, daß er entrinne? Michal sprach zu Saul: Er sprach zu mir: Lali mich gehen, Oder ich tote dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David aber entfloh und entrann; und kam zu Samuel gen Rama und sagte ihm an alles, was ihm Saul getan hatte. Und er ging hin mit Samuel, und blieben zu Najoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Und es ward Saul angesagt: Siehe, David ist zu Najoth in Rama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Da sandte Saul Boten, daß sie David holeten. Und sie sahen zween Chore Propheten weissagen, und Samuel war ihr Aufseher. Da kam der Geist Gottes auf die Boten Sauls, daß sie auch weissagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Da das Saul ward angesagt, sandte erandere Boten, die weissagten auch. Da sandte er die dritten Boten, die weissagten auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Da ging er selbst auch gen Rama; und da er kam zum grolien Brunnen, der zu Seku ist, fragte er und sprach: Wo ist Samuel und David? Da ward ihm, gesagt: Siehe, zu Najoth in Rama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Und er ging daselbst hin gen Najoth in Rama. Und der Geist Gottes kam auch auf ihn; und ging einher und weissagte, bis er kam gen Najoth in Rama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Und er zog auch seine Kleider aus und weissagte auch vor Samuel; und fiel bloli nieder den ganzen Tag und die ganze Nacht. Daher spricht man: Ist Saul auch unter den Propheten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David aber floh von Najoth zu Rama; und kam und redete vor Jonathan: Was habe ich getan? Was habe ich miligehandelt? Was habe ich gesundiget vor deinem Vater, daß er nach meinem Leben stehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Er aber sprach zu ihm: Das sei feme, du sollst nicht sterben. Siehe, mein Vater tut nichts, weder Grolies noch Kleines, das er nicht meinen Ohren offenbare; warum sollte denn mein Vater dies vor mir verbergen? Es wird nicht so sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Da schwur David weiter und sprach: Dein Vater weili wohl, daß ich Gnade vor deinen Augen funden habe, darum wird erdenken: Jonathan soil solches nicht wissen, es mochte ihn bekummern. Wahrlich, so wahr der HERR lebet, und so wahr deine Seele lebet, es ist nur ein Schritt zwischen mir und dem Tode!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonathan sprach zu David: Ich will an dir tun, was dein Herz begehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David sprach zu ihm: Siehe, morgen ist der Neumond, da ich mit dem Konige zu Tische sitzen sollte; so lali mich, daß ich mich auf dem Felde verberge bis an den Abend des dritten Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Wird dein Vater nach mir fragen, so sprich: David bat mich, daß er gen Bethlehem, zu seiner Stadt, laufen mdchte; denn es ist ein jahrlich Opfer daselbst dem ganzen Geschlechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Wird er sagen: Es ist gut, so stehet es wohl urn deinen Knecht. Wird er aber ergrimmen, so wirst du merken, daß Boses bei ihm beschlossen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'So tue nun Barmherzigkeit an deinem Knechte; denn du hast mit mir, deinem Knechte, einen Bund im HERRN gemacht. Ist aber eine Missetat in mir, so tote du mich; denn warum wolltest du mich zu deinem Vater bringen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonathan sprach: Das sei feme von mir, daß ich sollte merken, daß Boses bei meinem Vater beschlossen ware, uber dich zu bringen, und sollte dir\'s nicht ansagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David aber sprach: Wer will mir\'s ansagen, so dir dein Vater etwas Hartes antwortet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonathan sprach zu David: Komm, lali uns hinaus aufs Feld gehen! Und gingen beide hinaus aufs Feld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Und Jonathan sprach zu David: HERR, Gott Israels, wenn ich erforsche an meinem Vater morgen und am dritten Tage, daß es wohlstehet mit David, und nicht hinsende zu dir und vor deinen Ohren offenbare,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'so tue der HERR Jonathan dies und jenes. Wenn aber das Bose meinem Vater gefallt wider dich, so will ich\'s auch vor deinen Ohren offenbaren und dich lassen, daß du mit Frieden weggehest. Und der HERR sei mit dir, wie er mit meinem Vater qewesen ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Tue ich\'s nicht, so tue keine Barmherzigkeit des HERRN an mir, weil ich lebe, auch nicht, so ich sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Und wenn der HERR die Feinde Davids ausrotten wird, einen jeglichen aus dem Lande, so reilie du deine Barmherzigkeit nicht von meinem Hause ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Also machte Jonathan einen Bund mit dem Hause Davids und sprach: Der HERR fordere es von der Hand der Feinde Davids!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Und Jonathan fuhrweiter und schwur David, so lieb hatte er ihn; denn er hatte ihn so lieb als seine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Und Jonathan sprach zu ihm: Morgen ist der Neumond, so wird man nach dir fragen; denn man wird dein vermissen, da du zu sitzen pflegest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Des dritten Tages aber komm bald hernieder und gehe an einen Ort, da du dich verbergest am Werkeltage, und setze dich bei den Stein Asel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'so will ich zu seiner Seite drei Pfeile schiel Jen, als ich zum Sichermal schosse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Und siehe, ich will den Knaben senden: Gehe hin, suche die Pfeile! Werde ich zum Knaben sagen: Siehe, die Pfeile liegen hierwarts hinter dir, hole sie! so komm, denn es ist Friede und hat keine Fahr, so wahr der HERR lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Sage ich aber zum Junglinge: Siehe, die Pfeile liegen dortwarts vor dir, so gehe hin, denn der HERR hat dich lassen gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Was aber du und ich miteinander geredet haben, da ist der HERR zwischen mir und dir ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David verbarg sich im Felde. Und da der Neumond kam, setzte sich der Konig zu Tische zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Da sich aber der Konig gesetzt hatte an seinen Ort, Wie er vorhin gewohnt war, an der Wand, stund Jonathan auf, Abner aber setzte sich an die Seite Sauls. Und man vermissete Davids an seinem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Und Saul redete des Tages nichts; denn er gedachte: Es ist ihm etwas widerfahren, daß er nicht rein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Des andern Tages des Neumonden, da man Davids vermissete an seinem Ort, sprach Saul zu seinem Sohn Jonathan: Warum ist der Sohn Isais nicht zu Tische kommen, weder gestern noch heute?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonathan antwortete Saul: Er bat mich, dafi er gen Bethlehem ginge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'und sprach: Laft mich gehen, denn unser Geschlecht hat zu opfern in der Stadt, und mein Bruder hat mir\'s selbst geboten; habe ich nun Gnade vor deinen Augen funden, so will ich hinweg und meine Bruder sehen. Darum ist er nicht kommen zu des Konigs Tisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Da ergrimmete der Zorn Sauls wider Jonathan und sprach zu ihm: Du ungehorsamer Bosewicht! Ich wei(J wohl, dall du den Sohn Isais auserkoren hast, dir und deiner unartigen Mutter zu Schanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Denn solange der Sohn Isais lebet auf Erden, wirst du, dazu auch dein Konigreich, nicht bestehen. So sende nun hin und lal J ihn herholen zu mir; denn er mu(J sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonathan antwortete seinem Vater Saul und sprach zu ihm: Warum soil er sterben? Was hat er getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Da schot J Saul den Spieli nach ihm, da(J er ihn spiet Jete. Da merkte Jonathan, da(J bei seinem Vater ganzlich beschlossen war, David zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Und stund auf vom Tisch mit grimmigem Zorn und al J desselben andern Tages des Neumonden kein Brot; denn er war bekummert urn David, daß ihn sein Vater also verdammte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Des Morgens ging Jonathan hinaus aufs Feld, dahin er David bestimmt hatte, und ein kleiner Knabe mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Und sprach zu dem Knaben: Lauf und suche mir die Pfeile, die ich schielie! Da aber der Knabe lief, scholi er einen Pfeil uber ihn hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Und als der Knabe kam an den Ort, dahin Jonathan den Pfeil geschossen hatte, rief ihm Jonathan nach und sprach: Der Pfeil liegt dortwarts vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Und rief abermal ihm nach: Eile rasch und stehe nicht stille! Da las der Knabe Jonathans die Pfeile auf und brachte sie zu seinem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Und der Knabe wul Jte nichts drum; allein Jonathan und David wul Jten urn die Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Da gab Jonathan seine Waffe seinem Knaben und sprach zu ihm: Gehe hin und trag\'s in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Da der Knabe hineinkam, stund David auf vom Ort gegen Mittag und fiel auf sein Antlitz zur Erde und betete dreimal an; und kusseten sich miteinander und weineten miteinander, David aber am allermeisten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Und Jonathan sprach zu David: Gehe hin mit Frieden! Was wir beide geschworen haben im Namen des HERRN und gesagt: Der HERR sei zwischen mir und dir, zwischen meinem Samen und deinem Samen, das bleibe ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Und Jonathan machte sich auf und kam in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David aber kam gen Nobezum Priester Ahimelech. Und Ahimelech entsetzte sich, da er David entgegenging, und sprach zu ihm: Warum kommst du allein und ist kein Mann mit dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'David sprach zu Ahimelech, dem Priester: Der Konig hat mir eine Sache befohlen und sprach zu mir: Lal J niemand wissen, warum ich dich gesandt habe und was ich dir befohlen habe. Denn ich habe auch meine Knaben etwa hie Oder daher beschieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Hastdu nun was unter deiner Hand, ein Brot Oder fünf, die gib mir in meine Hand, Oder was du findest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Der Priester antwortete David und sprach: Ich habe kein gemein Brot unter meiner Hand, sondern heilig Brot; wenn sich nur die Knaben von Weibern enthalten hatten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'David antwortete dem Priester und sprach zu ihm: Es sind die Weiber drei Tage uns versperret gewesen, da ich auszog, und der Knaben Zeug war heilig; ist aber dieser Weg unheilig, so wird er heute geheiliget werden an dem Zeuge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Da gab ihm der Priester des heiligen, weil kein ander Brot da war denn die Schaubrote, die man vordem HERRN aufhub, daß man ander frisch Brot auflegen sollte des Tages, da er die weggenommen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Es war aber des Tages ein Mann drinnen versperret vor dem HERRN aus den Knechten Sauls mit Namen Doeg, ein Edomiter, der machtigste unter den Hirten Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Und David sprach zu Ahimelech: Ist nicht hie unter deiner Hand ein Spieli Oder Schwert? Ich habe mein Schwert und Waffen nicht mit mir genommen; denn die Sache des Konigs war eilend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Der Priester sprach: Das Schwert des Philisters Goliath, den du schlugest im Eichgrunde, das ist hie, gewickelt in einen Mantel hinter dem Leibrock. Willstdu dasselbige, so nimm\'s hin, denn es ist hie kein anderes denn das. David sprach: Es ist seinesgleichen nicht; gib mir\'s!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Und David machte sich auf und floh vor Saul; und kam zu Achis, dem Konige zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Aber die Knechte Achis sprachen zu ihm: Das ist der David, des Landes Konig, von dem sie sangen am Reigen und sprachen: Saul schlug tausend, David aber zehntausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Und David nahm die Rede zu Herzen und furchtete sich sehr vor Achis, dem Konige zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Und verstellete seine Gebarde vor ihnen und kollerte unter ihren Handen und stiefi sich an die Türam Tor, und sein Geifer flofi ihm in den Bart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Da sprach Achis zu seinen Knechten: Siehe, ihr sehet, daß der Mann unsinnig ist; warum habt ihr ihn zu mir gebracht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 16, 'Habe ich der Unsinnigen zu wenig, daß ihr diesen herbrachtet, daß er neben mir rasete? Sollte der in mein Haus kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David ging von dannen und entrann in die Hohle Adullam. Da das seine Bruder horeten und das ganze Haus seines Vaters, kamen sie zu ihm hinab daselbst hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Und es versammelten sich zu ihm allerlei Manner, die in Not und Schuld und betrubtes Herzens waren; und erwar ihr Oberster, daß bei vierhundert Mann bei ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Und David ging von dannen gen Mizpe, in der Moabiter Land, und sprach zu der Moabiter Konig: Laß meinen Vater und meine Mutter bei euch aus und ein gehen, bis ich erfahre, was Gott mit mir tun wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Und er lieti sie vor dem Konige der Moabiter, da(S sie bei ihm blieben, solange David in der Burg war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Aber der Prophet Gad sprach zu David: Bleibe nicht in der Burg, sondern gehe hin und komm ins Land Juda. Da qinq David hin und kam in den Wald Hareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Und es kam vor Saul, daß David und die Manner, die bei ihm waren, waren hervorkommen. Als nun Saul wohnete zu Gibea unter einem Hain, in Rama, hatte er seinen Spiefi in der Hand und alle seine Knechte stunden neben ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Da sprach Saul zu seinen Knechten, die neben ihm stunden: Horet, ihr Kinder Jeminis, wird auch der Sohn Isais euch alle Acker und Weinberge geben und euch alle uber tausend und uber hundert zu Obersten machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'daß ihr euch alle verbunden habt wider mich, und ist niemand, der es meinen Ohren offenbarete, weil auch mein Sohn einen Bund gemacht hat mit dem Sohne Isais? Ist niemand unter euch, den es kranke meinethalben und meinen Ohren offenbare? Denn mein Sohn hat meinen Knecht wider mich auferwecket, da(S er mir nachstellet, wie es am Tage ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Da antwortete Doeg, der Edomiter, der neben den Knechten Sauls stund, und sprach: Ich sah den Sohn Isais, daß er gen Nobe kam zu Ahimelech, dem Sohn Ahitobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Derfragte den HERRN fur ihn und gab ihm Speise und das Schwert Goliaths, des Philisters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Da sandte der Konig hin und ließ rufen Ahimelech, den Priester, den Sohn Ahitobs, und seines Vaters ganzes Haus, die Priester, die zu Nobe waren. Und sie kamen alle zum Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Und Saul sprach: Hore, du Sohn Ahitobs! Er sprach: Hie bin ich, mein Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Und Saul sprach zu ihm: Warum habt ihr einen Bund wider mich gemacht, du und der Sohn Isais, daß du ihm Brot und Schwert gegeben und Gott fur ihn gefraget hast, daß du ihn erweckest, daß er mir nachstelle, wie es am Tage ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelech antwortete dem Konige und sprach: Und wer ist unter alien deinen Knechten als David, der getreu ist und des Konigs Eidam und gehet in deinem Gehorsam und ist herrlich gehalten in deinem Hause?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Habe ich denn heute erst angefangen, Gott fur ihn zu fragen? Das sei feme von mir! Der Konig lege solches seinem Knechte nicht auf in meines Vaters ganzem Hause; denn dein Knecht hat von all diesem nichts gewufit, weder Kleines noch Grolies.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Aber der Konig sprach: Ahimelech du mulit des Todes sterben, du und deines Vaters ganzes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Und der Konig sprach zu seinen Trabanten, die neben ihm stunden: Wendet euch und totet des HERRN Priester; denn ihre Hand ist auch mit David, und da sie wuliten, daß er floh, haben sie mir\'s nicht eroffnet. Aber die Knechte des Konigs wollten ihre Hande nicht an die Priester des HERRN legen, sie zu erschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Da sprach der Konig zu Doeg:. Wende du dich und erschlage die Priester. Doeg, der Edomiter, wandte sich und erschlug die Priester, daß des Tages starben funfundachtzig Manner, die leinene Leibrocke trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Und die Stadt der Priester, Nobe, schlug er mit der Scharfe des Schwerts, beide Mann und Weib, Kinder und Sauglinge, Ochsen und Esel und Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Es entrann aber ein Sohn Ahimelechs, des Sohns Ahitobs, der hieft Abjathar, und floh David nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Und verkündigte ihm, daß Saul die Priester des HERRN erwürget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'David aber sprach zu Abjathar: Ich wuftte es wohl an dem Tage, da der Edomiter Doeg da war, daß er\'s würde Saul ansagen; ich bin schuldig an alien Seelen deines Vaters Hauses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Bleibe bei mir und fürchte dich nicht! Wer nach meinem Leben stehet, der soil auch nach deinem Leben stehen, und sollst mit mir behalten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Und es ward David angesagt: Siehe, die Philister streiten wider Kegila und berauben die Tennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Da fragte David den HERRN und sprach: Soil ich hingehen und diese Philister schlagen? Und der HERR sprach zu David: Gehe hin, du wirst die Philister schlagen und Kegila erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Aber die Manner bei David sprachen zu ihm: Siehe, wir fürchten uns hie in Juda und wollen hingehen gen Kegila, zu der Philister Zeug?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Da fragte David wiederden HERRN; und der HERR antwortete ihm und sprach: Auf, zeuch hinab gen Kegila; denn ich will die Philister in deine Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Also zog David samt seinen Mannern gen Kegila und stritt wider die Philister und trieb ihnen ihr Vieh weg; und tat eine grofte Schlacht an ihnen. Also errettete David die zu Kegila.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Denn da Abjathar, der Sohn Ahimelechs, floh zu David gen Kegila, trug er den Leibrock mit sich hinab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Da ward Saul angesagt, daß David gen Kegila kommen ware, und sprach: Gott hat ihn in meine Hande übergeben, daß er verschlossen ist, nun er in eine Stadt kommen ist, mit Toren und Riegeln verwahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Und Saul lieft alles Volk rufen zum Streit hinnieder gen Kegila, daß sie David und seine Manner belegten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Da aber David merkte, daß Saul Boses über ihn gedachte, sprach erzu dem Priester Abjathar: Lange den Leibrock her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Und David sprach: HERR, Gott Israels, dein Knecht hat gehoret, daß Saul danach trachte, daß er gen Kegila komme, die Stadt zu verderben urn meinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Werden mich auch die Burger zu Kegila überantworten in seine Hande? Und wird aber Saul herab kommen, wie dein Knecht gehoret hat? Das verkündige, HERR, Gott Israels, deinem Knechte. Und der HERR sprach: Erwird herabkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'David sprach: Werden aber die Burger zu Kegila mich und meine Manner überantworten in die Hande Sauls? Der HERR sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Da machte sich David auf samt seinen Mannern, deren bei sechshundertwaren, und zogen aus von Kegila und wandelten, wo sie hin konnten. Da nun Saul angesagt ward, daß David von Kegila entronnen war, lieft ersein Ausziehen anstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David aber blieb in der Wüste, in der Burg, und blieb auf dem Berge in der Wüste Siph. Saul aber suchte ihn sein Leben lang; aber Gott gab ihn nicht in seine Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Und David sah, daß Saul ausgezogen war, sein Leben zu suchen. Aber David war in der Wüste Siph, in der Heide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Da machte sich Jonathan auf, der Sohn Sauls, und ging hin zu David in die Heide und starkte seine Hand in Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'und sprach zu ihm: Fürchte dich nicht; meines Vaters Sauls Hand wird dich nicht finden, und du wirst Konig werden uber Israel, so will ich der nachste urn dich sein; auch weift solches mein Vater wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Und sie machten beide einen Bund miteinander vordem HERRN. Und David blieb in der Heide, aber Jonathan zog wieder heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Aber die Siphiter zogen hinaufzu Saul gen Gibea und sprachen: Ist nicht David bei uns verborgen in der Burg, in der Heide, auf dem Hugel Hachila, der zur Rechten liegt an der Wüste?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'So komme nun der Konig hernieder nach all seines Herzens Begehr, so wollen wir ihn überantworten in des Konigs Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Da sprach Saul: Gesegnet seid ihr dem HERRN, daß ihr euch mein erbarmet habt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'So gehet nun hin und werdet es noch gewisser, daß ihrwisset und sehet, an welchem Ort seine Füfte gewesen sind, und wer ihn daselbst gesehen habe; denn mir ist gesagt, daß er listig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Besehet und erkundet alle Orter, da er sich verkreucht, und kommt wieder zu mir, wenn ihr\'s gewift seid, so will ich mit euch ziehen. Ist er im Lande, so will ich nach ihm forschen unter alien Tausenden in Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Da machten sie sich und gingen gen Siph vor Saul hin. David aber und seine Manner waren in der Wüste Maon, auf dem Gefilde zur Rechten der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Da nun Saul hinzog mit seinen Mannern zu suchen, ward es David angesagt; und er machte sich hinab in den Fels und blieb in der Wüste Maon. Da das Saul horete, jagte er David nach in der Wüste Maon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Und Saul mit seinen Mannern ging an einer Seite des Berges, David mit seinen Mannern an der andern Seite des Berges. Da David aber eilete, dem Saul zu entgehen, da umringete Saul samt seinen Mannern David und seine Manner, daß ersie griffe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Aber es kam ein Bote zu Saul und sprach: Eile und komm; denn die Philister sind ins Land gefallen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Da kehrete sich Saul von dem Nachjagen Davids und zog hin den Philistern entgegen; daher heißt man den Ort Sela-Mahelkoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Und David zog hinauf von dannen und blieb in der Burg Engedi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Da nun Saul wiederkam von den Philistern, ward ihm gesagt: Siehe, David ist in der Wuste Engedi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Und Saul nahm dreitausend junger Mannschaft aus ganz Israel und zog hin, David samt seinen Mannern zu suchen auf den Felsen der Gemsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Und da er kam zu den Schafhürden am Wege, war daselbst eine Hohle, und Saul ging hinein, seine Fulie zu decken. David aber und seine Manner saßen hinten in der Hohle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Da sprachen die Manner Davids zu ihm: Siehe, da ist der Tag, davon der HERR dir gesagt hat: Siehe, ich will deinen Feind in deine Hande geben, daß du mit ihm tust, was dir gefallt. Und David stund auf und schnitt leise einen Zipfel vom Rock Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Aber danach schlug ihm sein Herz, daß er den Zipfel Saul hatte abgeschnitten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'und sprach zu seinen Mannern: Das lasse der HERR feme von mir sein, daß ich das tun sollte und meine Hand legen an meinen Herm, den Gesalbten des HERRN; denn er ist der Gesalbte des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Und David weisete seine Manner von sich mit Worten und lieü sie nicht wider Saul sich auflehnen. Da aber Saul sich aufmachte aus der Hohle und ging auf dem Wege,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'machte sich danach David auch auf und ging aus der Hohle; und rief Saui hinten nach und sprach: Mein Herr Konig! Saul sah hinter sich. Und David neigte sein Antlitz zur Erde und betete an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Und sprach zu Saul: Warum gehorchest du Menschen Wort, die da sagen: David suchet dein Ungluck?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Siehe, heutigestages sehen deine Augen, daß dich der HERR heute hat in meine Hand gegeben in der Hohle, und es ward gesagt, daß ich dich sollte erwurgen. Aber es ward dein verschonet, denn ich sprach: Ich will meine Hand nicht an meinen Herm legen, denn er ist der Gesalbte des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Mein Vater, sieh doch den Zipfel von deinem Rock in meiner Hand, daß ich dich nicht erwurgen wollte, da ich den Zipfel von deinem Rock schnitt. Erkenne und sieh, daß nichts Boses in meiner Hand ist, noch keine Ubertretung. Ich habe auch an dir nicht gesundiget; und du jagest meine Seele, daß du sie wegnehmest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Der HERR wird Richter sein zwischen mir und dir und mich an dir rachen; aber meine Hand soil nicht uber dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Wie man sagt nach dem alten Sprichwort: Von Gottlosen kommt Untugend. Aber meine Hand soil nicht uber dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Wem zeuchst du nach, Konig von Israel? Wem jagest du nach? Einem toten Hunde, einem einigen Floh?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Der HERR sei Richter und richte zwischen mir und dir und sehe drein; und fuhre meine Sache aus und rette mich von deiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Ais nun David solche Worte zu Saul hatte ausgeredet, sprach Saul: Ist das nicht deine Stimme, mein Sohn David? Und Saul hub auf seine Stimme und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Und sprach zu David: Du bist gerechter denn ich. Du hast mir Gutes beweiset, ich aber habe dir Boses beweiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Und du hast mir heute angezeiget, wie du Gutes an mir getan hast, daß mich der HERR hatte in deine Hande beschlossen, und du mich doch nicht erwürget hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Wie sollte jemand seinen Feind finden und ihn lassen einen guten Weg gehen? Der HERR vergelte dir Gutes fur diesen Tag, dasdu an mir getan hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Nun siehe, ich weili, daß du Konig werden wirst, und das Konigreich Israels stehet in deiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'So schwore mir nun bei dem HERRN, daß du nicht ausrottest meinen Samen nach mir und meinen Namen nicht austilgest von meines Vaters Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'Und David schwur Saul. Da zog Saul heim; David aber mit seinen Mannern machten sich hinauf auf die Burg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Und Samuel starb; und das ganze Israel versammelte sich, trugen Leid urn ihn und begruben ihn in seinem Hause zu Rama. David aber machte sich auf und zog hinab in die Wuste Paran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Und es war ein Mann zu Maon, und sein Wesen zu Karmel; und der Mann war fast grolien Vermogens und hatte dreitausend Schafe und tausend Ziegen. Und begab sich eben, daß er seine Schafe beschor zu Karmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Und er hieli Nabal; sein Weib aber hieli Abigail und war ein Weib guter Vernunft und schon von Angesicht; der Mann aber war hart und boshaftig in seinem Tun und war einer von Kaleb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Da nun David in der Wuste horete, daß Nabal seine Schafe beschor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'sandte er aus zehn Jünglinge und sprach zu ihnen: Gehet hinauf gen Karmel, und wenn ihr zu Nabal kommt, so grufiet ihn von meinetwegen freundlich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'und sprechet: Gluck zu, Friede sei mit dir und deinem Hause und mit allem, das du hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Ich habe gehoret, dafi du Schafscherer hast. Nun, deine Hirten, die du hast, sind mit uns gewesen; wir haben sie nicht verhohnet, und hat ihnen nichts gefehlet an der Zahl, solange sie zu Karmel gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Frage deine Junglinge darum, die werden\'s dir sagen; und lali die Junglinge Gnade finden vor deinen Augen, denn wir sind auf einen guten Tag kommen. Gib deinen Knechten und deinem Sohn David, was deine Hand findet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Und da die Junglinge Davids hinkamen und von Davids wegen alle diese Worte mit Nabal geredet hatten, horeten sie auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Aber Nabal antwortete den Knechten Davids und sprach: Wer ist der David? und wer ist der Sohn Isais? Es werden jetzt der Knechte viel, die sich von ihren Herren reilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Sollte ich mein Brot, Wasser und Fleisch nehmen, das ich fur meine Scherer geschlachtet habe, und den Leuten geben, die ich nicht kenne, wo sie her sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Da kehreten sich die Junglinge Davids wieder auf ihren Weg; und da sie wieder zu ihm kamen, sagten sie ihm solches alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Da sprach David zu seinen Mannern: Gürte ein jeglicher sein Schwert urn sich! Und ein jeglicher gurtete sein Schwert urn sich, und David gurtete sein Schwert auch urn sich, und zogen ihm nach hinauf bei vierhundert Mann; aber zweihundert blieben bei dem Gerate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Aber der Abigail, Nabals Weibe, sagte an der Junglinge einer und sprach: Siehe, David hat Boten gesandt aus der Wuste, unsern Herm zu segnen; er aber schnaubte sie an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Und sie sind uns doch sehr nütze Leute gewesen und haben uns nicht verhohnet, und hat uns nichts gefehlet an der Zahl, solange wir bei ihnen gewandelt haben, wenn wir auf dem Felde waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'sondern sind unsere Mauern gewesen Tag und Nacht, solange wir der Schafe bei ihnen gehutet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'So merke nun und siehe, was du tust; denn es ist gewili ein Ungluck vorhanden über unsern Herrn und uber sein ganzes Haus; und er ist ein heilloser Mann, dem niemand etwas sagen darf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Da eilete Abigail und nahm zweihundert Brote und zwei Legel Weins und fünf gekochte Schafe und fünf Scheffel Mehl und hundert Stuck Rosinen und zweihundert Stuck Feigen und lud es auf Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Und sprach zu ihren Jünglingen: Gehet vor mir hin; siehe, ich will kommen hernach. Und sie sagte ihrem Manne Nabal nichts davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Und als sie auf dem Esel ritt und hinabzog im Dunkel des Berges, siehe, da begegnete ihr David und seine Manner hinab, daß sie auf sie stiefi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David aber hatte geredet: Wohlan, ich habe umsonst behütet alles, was dieser hat in der Wuste, daß nichts gefehlet hat an allem, was er hat; und er bezahlete mir Gutes mit Bosem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Gott tue dies und noch mehr den Feinden Davids, wo ich diesem bis licht Morgen überlasse einen, der an die Wand pisset, aus allem, das er hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Da nun Abigail David sah, stieg sie eilend vom Esel und fiel vor David auf ihr Antlitz und betete an zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Und fiel zu seinen Fufien und sprach: Ach, mein Herr, mein sei diese Missetat, und lali deine Magd reden vor deinen Ohren und hore die Worte deiner Magd!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Mein Herr setze nicht sein Herz wider diesen Nabal, den heillosen Mann; denn er ist ein Narr, wie sein Name heilit, und Narrheit ist bei ihm. Ich aber, deine Magd, habe die Junglinge meines Herrn nicht gesehen, die du gesandt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Nun aber, mein Herr, so wahr der HERR lebet, und so wahr deine Seele lebet, der HERR hat dich verhindert, daü du nicht kamest wider das Blut, und hat dir deine Hand erloset. So müssen nun werden wie Nabal deine Feinde, und die meinem Herrn übel wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Hie ist der Segen, den deine Magd meinem Herrn hergebracht hat; den gib den Jünglingen, die unter meinem Herrn wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Vergib deiner Magd die Ubertretung! Denn der HERR wird meinem Herrn ein bestandig Haus machen, denn du fuhrest des HERRN Kriege; und lali kein Boses an dir gefunden werden dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Und wenn sich ein Mensch erheben wird, dich zu verfolgen, und nach deiner Seele stehet, so wird die Seele meines Herrn eingebunden sein im Bündlein der Lebendigen bei dem HERRN, deinem Gott; aber die Seele deiner Feinde wird geschleudert werden mit der Schleuder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Wenn denn der HERR all das Gute meinem Herrn tun wird, das er dir geredet hat, und gebieten, daß du ein Herzog seiest über Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'so wird\'s dem Herzen meines Herrn nicht ein Stoli noch Argernis sein, daß du nicht Blut vergossen hast ohne Ursache und dir selber geholfen; so wird der HERR meinem Herrn wohltun, und wirst an deine Magd gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Da sprach David zu Abigail: Gelobet sei der HERR, der Gott Israels, der dich heutigestages hat mir entgegengesandt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Und gesegnet sei deine Rede und gesegnet seiest du, daß du mir heute erwehret hast, daß ich nicht wider Blut kommen bin und mich mit eigener Hand erloset habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Wahrlich, so wahr der HERR, der Gott Israels, lebet, der mich verhindert hat, daß ich nicht übel an dir tate, warest du nicht eilend mir begegnet, so ware dem Nabal nicht uberblieben auf diesen lichten Morgen einer, der an die Wand pisset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Also nahm David von ihrer Hand, was sie ihm gebracht hatte, und sprach zu ihr: Zeuch mit Frieden hinauf in dein Haus; siehe, ich habe deiner Stimme gehorchet und deine Person angesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Da aber Abigail zu Nabal kam, siehe, da hatte er ein Mahl zugerichtet in seinem Hause wie eines Konigs Mahl; und sein Herz warguter Dinge bei ihm selbst und er war sehr trunken. Sie aber sagte ihm nichts, weder Kleines noch Großes, bis an den lichten Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Da es aber Morgen ward, und der Wein von Nabal kommen war, sagte ihm sein Weib solches. Da erstarb sein Herz in seinem Leibe, dafi erward wie ein Stein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Und liber zehn Tage schlug ihn der HERR, daß er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Da das David horete, daß Nabal tot war, sprach er: Gelobet sei der HERR, der meine Schmach gerochen hat an dem Nabal und seinen Knecht enthalten hat vor dem Ubel, und der HERR hat dem Nabal das Ubel auf seinen Kopf vergolten. Und David sandte hin und lieü mit Abigail reden, daß er sie zum Weibe nahme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Und da die Knechte Davids zu Abigail kamen gen Karmel, redeten sie mit ihr und sprachen: David hat uns zu dir gesandt, daß er dich zum Weibe nehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Sie stund auf und betete an auf ihr Angesicht zur Erde und sprach: Siehe, hie ist deine Magd, daß sie diene den Knechten meines Herrn und ihre Füße wasche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Und Abigail eilete und machte sich auf; und ritt auf einem Esel und fünf Dirnen, die unter ihr waren; und zog den Boten Davids nach und ward sein Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Auch nahm David Ahinoam von Jesreel; und waren beide seine Weiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Saul aber gab Michal, seine Tochter, Davids Weib, Phalti, dem Sohn Lais von Gallim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Die aber von Siph kamen zu Saul gen Gibea und sprachen: Ist nicht David verborgen auf dem Hugel Hachila vor der Wuste?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Da machte sich Saul auf und zog herab zur Wuste Siph und mit ihm dreitausend junger Mannschaft in Israel, daß er David suchte in der Wuste Siph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Und lagerte sich auf dem Hugel Hachila, der vor der Wuste liegt am Wege. David aber blieb in der Wuste. Und da er sah, daß Saul kam ihm nach in die Wuste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'sandte er Kundschafter aus und erfuhr, daß Saul gewifilich kommen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Und David machte sich auf und kam an den Ort, da Saul sein Lager hielt, und sah die Statte, da Saul lag mit seinem Feldhauptmann Abner, dem Sohn Ners. Denn Saul lag in der Wagenburg und das Heervolk urn ihn her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Da antwortete David und sprach zu Ahimelech, dem Hethiter, und zu Abisai, dem Sohne Zerujas, dem Bruder Joabs: Wer will mit mir hinab zu Saul ins Lager? Abisai sprach: Ich will mit dir hinab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Also kam David und Abisai zum Volk des Nachts. Und siehe, Saul lag und schlief in der Wagenburg, und sein Spiefi steckte in der Erde zu seinen Haupten. Abner aber und das Volk lag urn ihn her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Da sprach Abisai zu David: Gott hat deinen Feind heute in deine Hand beschlossen; so will ich ihn nun mit dem Spiefi stechen in die Erde einmal, daß er es nicht mehr bedarf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'David aber sprach zu Abisai: Verderbe ihn nicht; denn wer will die Hand an den Gesalbten des HERRN legen und ungestraft bleiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Weiter sprach David: So wahr der HERR lebet, wo der HERR nicht ihn schlagt, Oder seine Zeit kommt, daß er sterbe, Oder in einen Streit ziehe und komme urn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'so lasse der HERR feme von mir sein, daß ich meine Hand sollte an den Gesalbten des HERRN legen. So nimm nun den Spieß zu seinen Haupten und den Wasserbecher und la(S uns gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Also nahm David den Spieiß und den Wasserbecher zu den Haupten Sauls und ging hin; und war niemand, der es sah noch merkte, noch erwachte, sondern sie schliefen alle. Denn es war ein tiefer Schlaf vom HERRN auf sie gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Da nun David hinuber auf jenseit kommen war, trat er auf des Berges Spitze von feme, daß ein weiter Raum war zwischen ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Und schrie das Volk an und Abner, den Sohn Ners, und sprach: Horestdu nicht, Abner? Und Abner antwortete und sprach: Wer bist du, daß du so schreiest gegen dem Konige?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Und David sprach zu Abner: Bist du nicht ein Mann? und wer ist dein gleich in Israel? Warum hast du denn nicht behütet deinen Herrn, den Konig? Denn es ist des Volks einer hineinkommen, deinen Herrn, den Konig, zu verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Es ist aber nicht fein, das du getan hast. So wahr der HERR lebet, ihr seid Kinder des Todes, daß ihreuren Herrn, den Gesalbten des HERRN, nicht behütet habt. Nun siehe, hie ist der Spieß des Konigs und der Wasserbecher, die zu seinen Haupten waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Da erkannte Saul die Stimme Davids und sprach: Ist das nicht deine Stimme, mein Sohn David? David sprach: Es ist meine Stimme, mein Herr Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Und sprach weiter: Warum verfolget mein Herr also seinen Knecht? Was habe ich getan, und was Ubels ist in meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'So hore doch nun mein Herr, der Konig, die Worte seines Knechts: Reizet dich der HERR wider mich, so lasse man ein Speisopfer riechen; tun es aber Menschenkinder, so seien sie verflucht vor dem HERRN, daß sie mich heute verstoften, dafi ich nicht hafte in des HERRN Erbteil, und sprechen: Gehe hin, diene andern Gottern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'So verfalle nun mein Blut nicht auf die Erde von dem Angesicht des HERRN. Denn der Konig Israels ist ausgezogen, zu suchen einen Floh, wie man ein Rebhuhn jagt auf den Bergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Und Saul sprach: Ich habe gesundiget; komm wieder, mein Sohn David! Ich will dir kein Leid fürder tun, darum daß meine Seele heutigestages teuer gewesen ist in deinen Augen. Siehe, ich habe toricht und sehr unweislich getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David antwortete und sprach: Siehe, hie ist der Spieft des Konigs; es gehe der Junglinge einer heruber und hole ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Der HERR aber wird einem jeglichen vergelten nach seiner Gerechtigkeit und Glauben. Denn der HERR hat dich heute in meine Hand gegeben, ich aber wollte meine Hand nicht an den Gesalbten des HERRN legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Und wie heute deine Seele in meinen Augen ist groli geachtet gewesen, so werde meine Seeie groli geachtet vor den Augen des HERRN und errette mich von aller Trubsal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sprach zu David: Gesegnet seiestdu, mein Sohn David; du wirst es tun und hinausfuhren. David aber ging seine Strafte, und Saul kehrete wieder an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David aber gedachte in seinem Herzen: Ich werde der Tage einen Saul in die Hande fallen; es ist mir nichts besser, denn daß ich entrinne in der Philister Land, daß Saul von mir ablasse, mich furder zu suchen in alien Grenzen Israels; so werde ich seinen Handen entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Und machte sich auf und ging hinuber, samt den sechshundert Mann, die bei ihm waren, zu Achis, dem Sohn Maochs, Konige zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Also blieb David bei Achis zu Gath, mit seinen Mannern, ein jeglicher mit seinem Hause; David auch mit seinen zweien Weibern, Ahinoam, der Jesreelitin, und Abigail, des Nabals Weibe, der Karmelitin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Und da Saul angesagt ward, daß David gen Gath geflohen ware, suchte er ihn nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Und David sprach zu Achis: Hab ich Gnade vor deinen Augen funden, so laft mir geben einen Raum in der Stadte einer auf dem Lande, daß ich drinnen wohne; was soil dein Knecht in der koniglichen Stadt bei dirwohnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Da gab ihm Achis des Tages Ziklag. Daher ist Ziklag der Konige Judas bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Die Zeit aber, die David in der Philister Lande wohnete, ist ein Jahr und vier Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David aber zog hinauf samt seinen Mannern und fiel ins Land der Gessuriter und Girsiter und Amalekiter; denn diese waren die Einwohner von alters her dieses Landes, als man kommt gen Sur, bis an Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Da aber David das Land schlug, lieft er weder Mann noch Weib leben, und nahm Schafe, Rinder, Esel, Kamele und Kleider; und kehrete wieder und kam zu Achis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Wenn denn Achis sprach: Seid ihr heute nicht eingefallen? so sprach David: Gegen den Mittag Judas und gegen den Mittag der Jerahmeeliter und gegen den Mittag der Keniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'David aber lieft weder Mann noch Weib lebendig gen Gath kommen, und gedachte, sie mochten wider uns reden und schwatzen. Also tat David, und das war seine Weise, solange er wohnete in der Philister Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Darum glaubte Achis David und gedachte: Er hat sich stinkend gemacht vor seinem Volk Israel, darum soil er immer mein Knecht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Und es begab sich zu derselben Zeit, daß die Philister ihr Heer versammelten, in Streit zu ziehen wider Israel. Und Achis sprach zu David: Du sollst wissen, daß du und deine Manner sollt mit mir ausziehen ins Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David sprach zu Achis: Wohlan, du sollst erfahren, was dein Knecht tun wird. Achis sprach zu David: Darum will ich dich zum Hitter meines Haupts setzen mein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel aber war gestorben, und ganz Israel hatte Leid urn ihn getragen und ihn begraben in seiner Stadt Rama. So hatte Saul aus dem Lande vertrieben die Wahrsager und Zeichendeuter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Da nun die Philister sich versammelten und kamen und lagerten sich zu Sunem, versammelte Saul auch das ganze Israel, und lagerten sich zu Gilboa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Da aber Saul der Philister Heer sah, furchtete er sich, und sein Herz verzagte sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Und er ratfragte den HERRN; aber der HERR antwortete ihm nicht, weder durch Traume, noch durchs Licht, noch durch Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Da sprach Saul zu seinen Knechten: Suchet mir ein Weib die einen Wahrsagergeist hat, daß ich zu ihr gehe und sie frage. Seine Knechte sprachen zu ihm: Siehe, zu Endor ist ein Weib, die hat einen Wahrsagergeist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Und Saul wechselte seine Kleider und zog andere an; und ging hin, und zween andere mit ihm, und kamen bei der Nacht zum Weibe; und sprach: Lieber, weissage mir durch den Wahrsagergeist und bringe mir herauf, den ich dir sage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Das Weib sprach zu ihm: Siehe, du weiftest wohl, was Saul getan hat, wie er die Wahrsager und Zeichendeuter ausgerottet hat vom Lande; warum willst du denn meine Seele in das Netz fuhren, daß ich ertotet werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul aber schwur ihr bei dem HERRN und sprach: So wahr der HERR lebet, es soil dir dies nicht zur Missetat geraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Da sprach das Weib: Wen soil ich dir denn heraufbringen? Er sprach: Bringe mir Samuel herauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Da nun das Weib Samuel sah, schrie sie laut und sprach zu Saul: Warum hast du mich betrogen? Du bist Saul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Und der Kdnig sprach zu ihr: Furchte dich nicht, was siehest du? Das Weib sprach zu Saul: Ich sehe Gotter heraufsteigen aus der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Er sprach: Wie ist er gestaltet? Sie sprach: Es kommt ein alter Mann herauf und ist bekleidet mit einem Seidenrock. Da vernahm Saul, daß es Samuel war, und neigte sich mit seinem Antlitz zur Erde und betete an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Samuel aber sprach zu Saul: Warum hast du mich unruhig gemacht, daß du mich heraufbringen lassest? Saul sprach: Ich bin sehr geangstet, die Philister streiten wider mich, und Gott ist von mir gewichen und antwortet mir nicht, weder durch Propheten noch durch Traume; darum habe ich dich lassen rufen, dafi du mir weisest, was ich tun solle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel sprach: Was willst du mich fragen, weil der HERR von dir qewichen und dein Feind worden ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Der HERR wird dir tun, wie er durch mich geredet hat, und wird das Reich von deiner Hand reiften und David, deinem Nachsten, geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'darum dafi du der Stimme des HERRN nicht gehorchet und den Grimm seines Zorns nicht ausgerichtet hast wider Amalek hat dir der HERR solches jetzt getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Dazu wird der HERR Israel mit dir auch geben in der Philister Hande. Morgen wirst du und deine Sohne mit mir sein. Auch wird der HERR das Heer Israels in der Philister Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Da fiel Saul zur Erde, so lang er war, und erschrak sehr vor den Worten Samuels, daß keine Kraft mehr in ihm war; denn er hatte nichts gegessen den ganzen Tag und die ganze Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Und das Weib ging hinein zu Saul und sah, daß er sehr erschrocken war, und sprach zu ihm: Siehe, deine Magd hat deiner Stimme gehorchet und habe meine Seele in meine Hand gesetzt, daß ich deinen Worten gehorchte, die du zu mir sagtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'So gehorche auch nun du deiner Magd Stimme. Ich will dir einen Bissen Brots vorsetzen, daß du essest, daß du zu Kraften kommest und deine Strafte gehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Er aber weigerte sich und sprach: Ich will nicht essen. Da notigten ihn seine Knechte und das Weib, daß er ihrer Stimme gehorchte. Und er stund auf von der Erde und setzte sich aufs Bett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Das Weib aber hatte daheim ein gemastet Kalb; da eilete sie und schlachtete es; und nahm Mehl und knetete es und buk es ungesauert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Und brachte es herzu vor Saul und vor seine Knechte. Und da sie gegessen hatten, stunden sie auf und gingen die Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Die Philister aber versammelten alle ihre Heere zu Aphek; und Israel lagerte sich zu Ain in Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Und die Fursten der Philister gingen daher mit Hunderten und mit Tausenden; David aber und seine Manner gingen hinten nach bei Achis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Da sprachen die Fursten der Philister: Was sollen diese Ebraer? Achis sprach zu ihnen: Ist nicht das David, der Knecht Sauls, des Konigs Israels, der nun bei mir gewesen ist Jahr und Tag, und habe nichts an ihm gefunden, seit der Zeit er abgefallen ist, bis her?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Aber die Fursten der Philister wurden zornig auf ihn und sprachen zu ihm: Laft den Mann umkehren und an seinem Ort bleiben, da du ihn hin bestellet hast, daß er nicht mit uns hinabziehe zum Streit und unser Widersacher werde im Streit. Denn woran konnte er seinem Herrn baft Gefallen tun denn an den Kopfen dieser Manner?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ist er nicht der David, von dem sie sangen am Reigen: Saul hat tausend geschlagen, David aber zehntausend?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Da rief Achis David und sprach zu ihm: So wahr der HERR lebet, ich halte dich fur redlich, und dein Ausgang und Eingang mit mir im Heer gefallt mir wohl, und habe nichts Arges an dir gespuret, seit der Zeit du zu mir kommen bist, bis her; aber du gefallst den Fursten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'So kehre nun urn und gehe hin mit Frieden, auf daß du nicht ubel tust vor den Augen der Fursten der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David aber sprach zu Achis: Was habe ich getan, und was hast du gespuret an deinem Knechte, seit der Zeit ich vor dir gewesen bin, bis her, daß ich nicht sollte kommen und streiten wider die Feinde meines Herrn, des Konigs?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Achis antwortete und sprach zu David: Ich weift wohl; denn du gefallst meinen Augen, als ein Engel Gottes. Aber der Philister Fursten haben gesagt: Laft ihn nicht mit uns hinauf in Streit ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'So mache dich nun morgen fruhe auf, und die Knechte deines Herrn, die mit dir kommen sind; und wenn ihr euch morgen fruhe aufgemacht habt, daß licht ist, so gehet hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Also machten sich David und seine Manner frühe auf, daß sie des Morgens hingingen und wieder in der Philister Land kamen. Die Philister aber zogen hinauf gen Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Da nun David des dritten Tages kam gen Ziklag mit seinen Mannern, waren die Amalekiter hereingefallen zum Mittag und zu Ziklag und hatten Ziklag geschlagen und mit Feuer verbrannt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'und hatten die Weiber draus weggefuhret, beide klein und groli; sie hatten aber niemand getotet, sondern weggetrieben und waren dahin ihres Weges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Da nun David samt seinen Mannern zur Stadt kam und sah, daß sie mit Feuer verbrannt war, und ihre Weiber, Sohne und Tochter gefangen waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'hub David und das Volk, das bei ihm war, ihre Stimme auf und weineten, bis sie nicht mehr weinen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Denn Davids zwei Weiber waren auch gefangen, Ahinoam, die Jesreelitin, und Abigail, Nabals Weib, des Karmeliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Und David war sehr geangstet; denn das Volk wollte ihn steinigen, denn des ganzen Volks Seele war unwillig, ein jeglicher uber seine Sohne und Tochter. David aber starkte sich in dem HERRN, seinem Gott');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'und sprach zu Abjathar, dem Priester, Ahimelechs Sohn: Bringe mir her den Leibrock. Und da Abjathar den Leibrock zu David gebracht hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'fragte David den HERRN und sprach: Soil ich den Kriegsleuten nachjagen und werde ich sie ergreifen? Er sprach: Jage ihnen nach, du wirst sie ergreifen und Rettung tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Da zog David hin und die sechshundert Mann, die bei ihm waren; und da sie kamen an den Bach Besor, blieben etliche stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'David aber und die vierhundert Mann jagten nach; die zweihundert Mann aber, die stehen blieben, waren zu mude, uber den Bach Besor zu gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Und sie fanden einen agyptischen Mann auf dem Felde, den fuhreten sie zu David und gaben ihm Brot, daß er aft, und trankten ihn mit Wasser;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'und gaben ihm ein Stuck Feigen und zwei Stuck Rosinen. Und da er gegessen hatte, kam sein Geist wieder zu ihm; denn er hatte in dreien Tagen und dreien Nachten nichts gegessen und kein Wasser getrunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'David sprach zu ihm: Wes bist du? und woher bist du? Er sprach: Ich bin ein agyptischer Knabe, eines Amalekiters Knecht; und mein Herr hat mich verlassen, denn ich war krank vor dreien Tagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Wirsind hereingefallen zum Mittag Krethi und auf Juda und zum Mittag Kaleb und haben Ziklag mit Feuer verbrannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David sprach zu ihm: Willst du mich hinabfuhren zu diesen Kriegsleuten? Er sprach: Schwore mir bei Gott, daß du mich nicht totest noch in meines Herm Hand überantwortest, so will ich dich hinabfuhren zu diesen Kriegsleuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Und erfuhrete sie hinab. Und siehe, sie hatten sich zerstreuet auf der ganzen Erde, aften und tranken und feierten uber all dem groften Raub, den sie genommen hatten aus der Philister und Judas Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Und David schlug sie von dem Morgen an bis an den Abend gegen den andern Tag, daß ihrer keiner entrann, ohne vierhundert Junglinge, die fielen auf die Kamele und flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Also errettete David alles, was die Amalekiter genommen hatten, und seine zwei Weiber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'und fehlete an keinem, weder klein noch graft, noch Sohne, noch Tochter, noch Raub, noch alles, das sie genommen hatten: David brachte es alles wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Und David nahm die Schafe und Rinder und trieb das Volk vor ihm her; und sie sprachen: Das ist Davids Raub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Und da David zu den zweihundert Mannern kam, die zu mude gewesen, David nachzufolgen, und am Bach Besor geblieben waren, gingen sie heraus, David entgegen und dem Volk, das mit ihm war. Und David trat zum Volk und gruftte sie freundlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Da antworteten, was bose und lose Leute waren unterdenen, die mit David gezogen waren, und sprachen: Weil sie nicht mit uns gezogen sind, soil man ihnen nichts geben von dem Raube, den wir errettet haben, sondern ein jeglicher führe sein Weib und seine Kinder und gehe hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Da sprach David: Ihr sollt nicht so tun, meine Bruder, mit dem, das uns der HERR gegeben hat, und hat uns behutet und diese Kriegsleute, die wider uns kommen waren, in unsere Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Wersollte euch darinnen gehorchen? Wie das Teil derjenigen, die in Streit hinabgezogen sind, so soli auch sein das Teil derjenigen, die bei dem Gerate geblieben sind, und soil gleich geteilet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Das ist seit der Zeit und forthin in Israel eine Sitte und Recht worden bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Und da David gen Ziklag kam, sandte er des Raubes den Altesten in Juda, seinen Freunden, und sprach: Siehe, da habt ihr den Segen aus dem Raub der Feinde des HERRN;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'namlich denen zu Bethel, denen zu Ramoth am Mittage, denen zu Jathir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'denen zu Aroer, denen zu Siphamoth, denen zu Esthemoa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'denen zu Rachal, denen in Stadten der Jerahmeeliter, denen in Stadten der Keniter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'denen zu Horma, denen zu Bor-Asan, denen zu Athach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'denen zu Hebron und alien Orten, da David gewandelt hatte mit seinen Mannern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Die Philister aber stritten wider Israel; und die Manner Israels flohen vor den Philistern und fielen erschlagen auf dem Gebirge Gilboa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Und die Philister hingen sich an Saul und seine Sohne und schlugen Jonathan und Abinadab und Malchisua, die Sohne Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Und der Streit ward hart wider Saul, und die Schutzen trafen auf ihn mit Bogen; und ward sehr verwundet von den Schutzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Da sprach Saul zu seinem Waffentrager: Zeuch dein Schwert aus und erstich mich damit, daß nicht diese Unbeschnittenen kommen und mich erstechen und treiben einen Spott aus mir. Aber sein Waffentrager wollte nicht; denn er furchtete sich sehr. Da nahm Saul das Schwert und fiel drein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Da nun sein Waffentrager sah, dais Saul tot war, fiel er auch in sein Schwert und starb mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Also starb Saul und seine drei Sohne und sein Waffentrager und alle seine Manner zugleich auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Da aber die Manner Israels, die jenseit des Grundes und jenseit des Jordans waren, sahen, daß die Manner Israels geflohen waren, und daß Saul und seine Sohne tot waren, verlieften sie die Stadte und flohen auch; so kamen die Philister und wohneten drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Des andern Tages kamen die Philister, die Erschlagenen auszuziehen, und fanden Saul und seine drei Sohne liegen auf dem Gebirge Gilboa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Und hieben ihm sein Haupt ab und zogen ihm seine Waffen ab und sandten sie in der Philister Land umher, zu verkundigen im Hause ihrer Gotzen und unterdem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Und legten seinen Harnisch in das Haus Astharoths, aber seinen Leichnam hingen sie auf die Mauerzu Bethsan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Da die zu Jabes in Gilead horeten, was die Philister Saul getan hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'machten sie sich auf, was streitbare Manner waren, und gingen die ganze Nacht und nahmen die Leichname Sauls und seiner Sohne von der Mauer Bethsans und brachten sie gen Jabes und verbrannten sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Und nahmen ihre Gebeine und begruben sie unterdem Baum zu Jabes; und fasteten sieben Tage. Das zweite Buch Samuel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Nach dem Tode Sauls, da David von der Amalekiter Schlacht wiederkommen und zween Tage zu Ziklag geblieben war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'siehe, da kam am dritten Tage ein Mann aus dem Heer von Saul mit zerrissenen Kleidern und Erde auf seinem Haupt. Und da erzu David kam, fiel erzur Erde und betete an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David aber sprach zu ihm: Wo kommst du her? Er sprach zu ihm: Aus dem Heer Israels bin ich entronnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David sprach zu ihm: Sage mir, wie gehet es zu? Er sprach: Das Volk ist geflohen vom Streit, und ist viel Volks gefallen; dazu ist auch Saul tot und sein Sohn Jonathan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David sprach zu dem Jungling, der ihm solches sagte: Woher weiftest du, dafi Saul und sein Sohn Jonathan tot sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Der Jungling, der ihm solches sagte, sprach: Ich kam ohngefahr aufs Gebirge Gilboa, und siehe, Saul lehnete sich auf seinen Spief J, und die Wagen und Reiter jagten hinter ihm her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Und erwandte sich urn und sah mich und rief mir. Und ich sprach: Hie bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Und er sprach zu mir: Wer bist du? Ich sprach zu ihm: Ich bin ein Amalekiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Und er sprach zu mir: T ritt zu mir und tote mich, denn ich bin bedranget umher, und mein Leben ist noch ganz in mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Da trat ich zu ihm und totete ihn, denn ich wuftte wohl, daß er nicht leben konnte nach seinem Fall; und nahm die Krone von seinem Haupt und das Armgeschmeide von seinem Arm und habe es hergebracht zu dir, meinem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Da fassete David seine Kleider und zerrift sie, und alle Manner, die bei ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Und trugen Leid und weineten und fasteten bis an den Abend uber Saul und Jonathan, seinen Sohn, und uber das Volk des HERRN und fiber das Haus Israels, daß sie durchs Schwert gefallen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Und David sprach zu dem Jungling, deres ihm ansagte: Wo bist du her? Er sprach: Ich bin eines Fremdlings, eines Amalekiters, Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David sprach zu ihm: Wie, daß du dich nicht geftirchtet hast, deine Hand zu legen an den Gesalbten des HERRN, ihn zu verderben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Und David sprach zu seiner Junglinge einem: Herzu und schlag ihn! Und er schlug ihn, daß er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Da sprach David zu ihm: Dein Blut sei fiber deinem Kopf; denn dein Mund hat wider dich selbst geredet und gesprochen: Ich habe den Gesalbten des HERRN getotet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Und David klagte diese Klage uber Saul und Jonathan, seinen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Und befahl, man sollte die Kinder Judas den Bogen lehren. Siehe, es stehet geschrieben im Buch der Redlichen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Die Edelsten in Israel sind auf deiner Hohe erschlagen. Wie sind die Helden gefallen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Saget es nicht an zu Gath, verkundet es nicht auf der Gasse zu Asklon, dafi sich nicht freuen die Tochter der Philister, daß nicht frohlocken die Tochter der Unbeschnittenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Ihr Berge zu Gilboa, es müsse weder tauen noch regnen auf euch, noch Acker sein, da Hebopfer von kommen; denn daselbst ist den Helden ihr Schild abgeschlagen, der Schild Sauls; als ware er nicht gesalbet mit 01.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Der Bogen Jonathans hat nie gefehlet, und das Schwert Sauls ist nie leerwiederkommen von dem Blut der Erschlagenen und vom Fett der Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul und Jonathan, holdselig und lieblich in ihrem Leben, sind auch im Tode nicht geschieden; leichter denn die Adler und starker denn die Lowen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Ihr Tochter Israels, weinet uber Saul, der euch kleidete mit Rosinfarbe sauberlich und schmuckte euch mit guldenen Kleinoden an euren Kleidern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Wie sind die Helden so gefallen im Streit! Jonathan istaufdeinen Hohen erschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Es ist mir leid um dich, mein Bruder Jonathan! Ich habe große Freude und Wonne an dir gehabt; deine Liebe ist mir sonderlicher gewesen, denn Frauenliebe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Wie sind die Helden gefallen und die Streitbaren umkommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Nach dieser Geschichte fragte David den HERRN und sprach: Soil ich hinauf in der Stadte Juda eine ziehen? Und der HERR sprach zu ihm: Zeuch hinauf! David sprach: Wohin? Er sprach: Gen Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Also zog David dahin mitseinen zweien Weibern, Ahinoam, der Jesreelitin, und mit Abigail, Nabals, des Karmeliten, Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Dazu die Manner, die bei ihm waren, fuhrete David hinauf, einen jeglichen mit seinem Hause, und wohneten in den Stadten Hebrons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Und die Manner Judas kamen und salbeten daselbst David zum Konige über das Haus Juda. Und da es David ward angesagt, daß die von Jabes in Gilead Saul begraben hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'sandte er Boten zu ihnen und liefi ihnen sagen: Gesegnet seid ihr dem HERRN, daß ihr solche Barmherzigkeit an eurem HERRN, Saul, getan und ihn begraben habt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'So tue nun an euch der HERR Barmherzigkeit und Treue; und ich will euch auch Gutes tun, daß ihr solches getan habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'So seien nun eure Hande getrost und seid freudig; denn euer Herr, Saul, ist tot, so hat mich das Haus Juda zum Konige gesalbet uber sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner aber, der Sohn Ners, der Sauls Feldhauptmann war, nahm Isboseth, Sauls Sohn, und fuhrete ihn gen Mahanaim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'und machte ihn zum Konige über Gilead, Assuri, Jesreel, Ephraim, Benjamin und fiber ganz Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Und Isboseth, Sauls Sohn, warvierzig Jahre alt, da er Konig ward uber Israel; und regierete zwei Jahre. Aber das Haus Juda hielt es mit David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Die Zeit aber, die David Konig war zu Hebron fiber das Haus Juda, war sieben Jahre und sechs Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Und Abner, der Sohn Ners, zog aus samt den Knechten Isboseths, des Sohns Sauls, aus dem Heer gen Gibeon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'und Joab, der Sohn Zerujas, zog aus samt den Knechten Davids; und stießen aufeinander am Teich zu Gibeon, und legten sich diese auf dieser Seite des Teiches, jene auf jener Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Und Abner sprach zu Joab: Laß sich die Knaben aufmachen und vor uns spielen. Joab sprach: Es gilt wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Da machten sich auf und gingen hin an der Zahl zwolf aus Benjamin, auf Isboseths, Sauls Sohns, Teil, und zwolf von den Knechten Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Und ein jeglicher ergriff den andern bei dem Kopf und stieß ihm sein Schwert in seine Seite, und fielen miteinander. Daher der Ort genannt wird: Helkath-Hazurim, der zu Gibeon ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Und es erhub sich ein sehr harter Streit des Tages. Abner aber und die Manner Israels wurden geschlagen vor den Knechten Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Es waren aber drei Sohne Zerujas daselbst: Joab, Abisai und Asahel. Asahel aber war von leichten Füßen, wie ein Reh auf dem Felde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'und jagte Abner nach und wich nicht weder zur Rechten noch zur Linken von Abner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Da wandte sich Abner um und sprach: Bist du Asahel? Er sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner sprach zu ihm: Heb dich entweder zur Rechten Oder zur Linken; und nimm fur dich der Knaben einen und nimm ihm seinen Harnisch. Aber Asahel wollte nicht von ihm ablassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Da sprach Abner weiter zu Asahel: Heb dich von mir! Warum willst du, daß ich dich zu Boden schlage? und wie dürfte ich mein Antlitz aufheben vor deinem Bruder Joab?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Aber er weigerte sich zu weichen. Da stach ihn Abner hinter sich mit einem Spieß in seinen Wanst, daß der Spieß hinten ausging; und er fiel daselbst und starb vor ihm. Und wer an den Ort kam, da Asahel tot lag, derstund stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Aber Joab und Abisai jagten Abner nach, bis die Sonne unterging. Und da sie kamen auf den Hügel Amma, der vor Giah lieget, auf dem Wege zur Wüste Gibeon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'versammelten sich die Kinder Benjamin hinter Abner her und wurden ein Hauflein und traten auf eines Hügels Spitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Und Abner rief zu Joab und sprach: Soli denn das Schwert ohne Ende fressen? Weiliest du nicht, daß hernach mdchte mehr Jammers werden? Wie lange willst du dem Volk nicht sagen, daß es ablasse von seinen Brudern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab sprach: So wahr Gott lebet, hattest du heute morgen so gesagt, das Volk hatte, ein jeglicher von seinem Bruder, abgelassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Und Joab blies die Posaune, und alles Volk stund stille und jagten nicht mehr Israel nach und stritten auch nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner aber und seine Manner gingen dieselbe ganze Nacht uber das Blachfeld und gingen uber den Jordan; und wandelten durch das ganze Bithron und kamen ins Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joab aber wandte sich von Abner und versammelte das ganze Volk; und es fehleten an den Knechten Davids neunzehn Mann und Asahel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Aber die Knechte Davids hatten geschlagen unter Benjamin und den Mannern Abners, daß dreihundertundsechzig Mann waren tot geblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Und sie huben Asahel auf und begruben ihn in seines Vaters Grabe zu Bethlehem. Und Joab mit seinen Mannern gingen die ganze Nacht, daß ihnen das Licht anbrach zu Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Und es war ein langer Streit zwischen dem Hause Sauls und dem Hause Davids. David aber ging und nahm zu; und das Haus Sauls ging und nahm ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Und es wurden David Kinder geboren zu Hebron: Sein erstgeborner Sohn Amnon von Ahinoam, der Jesreelitin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'der andere: Chileab von Abigail, Nabals Weib, des Karmeliten; der dritte: Absalom, der Sohn Maachas, der Tochter Thalmais, des Konigs zu Gesur;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'der vierte Adonia, der Sohn Hagiths; der funfte: Saphatja, der Sohn Abitals;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'der sechste: Jethream von Egla, dem Weibe Davids. Diese sind David geboren zu Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Als nun der Streit war zwischen dem Hause Sauls und dem Hause Davids, starkte Abner das Haus Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Und Saul hatte ein Kebsweib, die hiefi Rizpa, eine Tochter Ajas. Und Isboseth sprach zu Abner: Warum schlafst du bei meines Vaters Kebsweib?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Da ward Abner sehr zornig uber diese Worte Isboseths und sprach: Bin ich denn ein Hundskopf, der ich wider Juda an dem Hause Sauls, deines Vaters, und an seinen Brudern und Freunden Barmherzigkeit tue und habe dich nicht in Davids Hande gegeben? Und du rechnest mir heute eine Missetat zu urn ein Weib?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Gott tue Abner dies und das, wenn ich nicht tue, wie der HERR David geschworen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'dati das Konigreich vom Hause Sauls genommen werde, und der Stuhl Davids aufgerichtet werde uber Israel und Juda von Dan bis gen Berseba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Da konnte er furder ihm kein Wort mehr antworten, so furchtete er sich vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Und Abner sandte Boten zu David fur sich und ließ ihm sagen: Wes ist das Land? Und sprach: Mache deinen Bund mit mir; siehe, meine Hand soil mit dir sein, daß ich zu dir kehre das ganze Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Er sprach: Wohl, ich will einen Bund mit dir machen. Aber eins bitte ich von dir, daß du mein Angesicht nicht sehest, du bringest denn zuvor zu mir Michal, Sauls Tochter, wenn du kommst, mein Angesicht zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Auch sandte David Boten zu Isboseth, dem Sohn Sauls, und ließ ihm sagen: Gib mir mein Weib Michal, die ich mir vertrauet habe mit hundert Vorhauten der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboseth sandte hin und ließ sie nehmen von dem Manne Paltiel, dem Sohn Lais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Und ihr Mann ging mit ihr und weinete hinter ihr bis gen Bahurim. Da sprach Abner zu ihm: Kehre urn und gehe hin. Und er kehrete urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Und Abner hatte eine Rede mit den Altesten in Israel und sprach: Ihr habt vorhin langst nach David getrachtet, daß er Konig ware uber euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'So tut es nun; denn der HERR hat von David gesagt: Ich will mein Volk Israel erretten durch die Hand Davids, meines Knechts, von der Philister Hand und von aller ihrer Feinde Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Auch redete Abner vor den Ohren Benjamins; und ging auch hin zu reden vor den Ohren Davids zu Hebron alles, was Israel und dem ganzen Hause Benjamin wohlgefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Da nun Abner gen Hebron zu David kam, und mit ihm zwanzig Mann, machte ihnen David ein Mahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Und Abner sprach zu David: Ich will mich aufmachen und hingehen, daß ich das ganze Israel zu meinem Herm, dem Konige, sammle, und daß sie einen Bund mit dir machen, auf daß du Konig seiest, wie es deine Seele begehret. Also lieli David Abner von sich, daß er hinginge mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Und siehe, die Knechte Davids und Joab kamen von den Kriegsleuten und brachten mit sich einen groüen Raub. Abner aber war nun nicht bei David zu Hebron, sondern er hatte ihn von sich gelassen, daß er mit Frieden weggegangen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Da aber Joab und das ganze Heer mit ihm war kommen, ward ihm angesagt, daß Abner, der Sohn Ners, zum Konige kommen war, und er hatte ihn von sich gelassen, daß er mit Frieden war weggegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Da ging Joab zum Konige hinein und sprach: Was hast du getan? Siehe, Abner ist zu dir kommen; warum hast du ihn von dir gelassen, daß er ist weggegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Kennest du Abner, den Sohn Ners, nicht? Denn er ist kommen, dich zu uberreden, daß er erkennete deinen Ausgang und Eingang und erfuhre alles, was du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Und da Joab von David ausging, sandte er Boten Abner nach, daß sie ihn wiederum holeten von Borhasira; und David wußte nichts drum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Als nun Abner wieder gen Hebron kam, fuhrete ihn Joab mitten unter das Tor, daß er heimlich mit ihm redete; und stach ihn daselbst in den Wanst, daß er starb, um seines Bruders Asahel Bluts willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Da das David hernach erfuhr, sprach er: Ich bin unschuldig und mein Konigreich vordem HERRN ewiglich an dem Blute Abners, des Sohnes Ners.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Es falle aber auf den Kopf Joabs und auf seines Vaters ganzes Haus; und müsse nicht aufhoren im Hause Joabs, der einen Eiterflufi und Aussatz habe und am Stabe gehe und durch das Schwert falle und an Brot mangele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Also erwurgeten Joab und sein Bruder Abisai Abner, darum daß er ihren Bruder Asahel getotet hatte im Streit zu Gibeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'David aber sprach zu Joab und allem Volk, das mit ihm war: Zerreiftet eure Kleider und gürtet Sacke um euch und traget Leid um Abner! Und der Konig ging dem Sarge nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Und da sie Abner begruben zu Hebron, hub der Konig seine Stimme auf und weinete bei dem Grabe Abners, und weinete auch alies Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Und der Konig klagte Abner und sprach: Abner ist nicht gestorben, wie ein Tor stirbt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Deine Hande sind nicht gebunden, deine Fufte sind nicht in Fesseln gesetzt; du bist gefallen, wie man vor bosen Buben fallt. Da beweinete ihn alies Volk noch mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Da nun alies Volk hineinkam, mit David zu essen, da es noch hoch Tag war, schwur David und sprach: Gott tue mir dies und das, wo ich Brot Oder etwas koste, ehe die Sonne untergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Und alies Volk erkannte es, und gefiel ihnen auch wohl alies Gute, was der Konig tat vor den Augen des ganzen Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Und alies Volk und ganz Israel merkten des Tages, daß nicht vom Konige war, daß Abner, der Sohn Ners, getotet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Und der Konig sprach zu seinen Knechten: Wisset ihr nicht, daß auf diesen Tag ein Furst und Grolier gefallen ist in Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ich aber bin noch zart und ein gesalbter Konig. Aber die Manner, die Kinder Zerujas, sind mir verdrielilich. Der HERR vergelte dem, der Boses tut, nach seiner Bosheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Da aber der Sohn Sauls horete, daß Abner zu Hebron tot ware, wurden seine Hande lali, und ganz Israel erschrak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Es waren aber zween Manner, Hauptleute uber die Krieger, unter dem Sohn Sauls; einer hiefi Baena, der andere Rechob, Sohne Rimons, des Berothiters, aus den Kindern Benjamin. Denn Beroth ward auch unter Benjamin gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Und die Berothiter waren gefiohen gen Gethaim und daselbst Fremdlinge worden bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Auch hatte Jonathan, der Sohn Sauls, einen Sohn, der war lahm an Fülien; und war funf Jahre ait, da das Geschrei von Saul und Jonathan aus Jesreel kam und seine Amme ihn aufhub und floh; und indem sie eilete und floh, fiel er und ward hinkend: Und er hieli Mephiboseth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'So gingen nun hin die Sohne Rimons, des Berothiters, Rechob und Baena, und kamen zum Hause Isboseths, da der Tag am heiliesten war; und er lag auf seinem Lager im Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Und sie kamen ins Haus, Weizen zu holen; und stachen ihn in den Wanst und entrannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Denn da sie ins Haus kamen, lag er auf seinem Bette in seiner Schlafkammer; und stachen ihn tot und hieben ihm den Kopf ab; und nahmen seinen Kopf und gingen hin des Weges auf dem Blachfelde die ganze Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Und brachten das Haupt Isboseths zu David gen Hebron und sprachen zum Konige: Siehe, da ist das Haupt Isboseths, Sauls Sohns, deines Feindes, der nach deiner Seele stund; der HERR hat heute meinen Herm, den Konig, gerochen an Saul und an seinem Samen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Da antwortete ihnen David: So wahr der HERR lebet, der meine Seele aus aller Trubsal erloset hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'ich griff den, der mir verkundigte und sprach: Saul ist tot, und meinte, er ware ein guter Bote; und erwurgete ihn zu Ziklag, dem ich solite Botenlohn geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Und diese gottlosen Leute haben einen gerechten Mann in seinem Hause auf seinem Lager erwurget. Ja, solite ich das Blut nicht fordern von euren Handen und euch von der Erde tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Und David gebot seinen Junglingen; die erwurgeten sie und hieben ihnen Hande und Fuße ab und hingen sie auf am Teich zu Hebron. Aber das Haupt Isboseths nahmen sie und begruben es in Abners Grabe zu Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Und es kamen alle Stamme Israels zu David gen Hebron und sprachen: Siehe, wirsind deines Gebeins und deines Fleisches.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Dazu auch vorhin, da Saul uber uns Konig war, führtest du Israel aus und ein. So hat der HERR dir gesagt: Du sollst meines Volks Israel hüten und sollst ein Herzog sein uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Und es kamen alle Altesten in Israel zum Konige gen Hebron. Und der Konig David machte mit ihnen einen Bund zu Hebron vordem HERRN; und sie salbeten David zum Konige uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Dreiftig Jahre war David alt, da er Konig ward, und regierete vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Zu Hebron regierete er sieben Jahre und sechs Monden uber Juda; aberzu Jerusalem regierete er dreiunddreitüg Jahre uber ganz Israel und Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Und der Konig zog hin mit seinen Mannern zu Jerusalem wider die Jebusiter, die im Lande wohneten. Sie aber sprachen zu David: Du wirst nicht hie hereinkommen, sondem Blinde und Lahme werden dich abtreiben. Das meinten sie aber, dafi David nicht wurde da hineinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Aber David gewann die Burg Zion, das ist Davids Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Da sprach David desselben Tages: Wer die Jebusiter schlagt und erlanget die Dachrinnen, die Lahmen und Blinden, denen die Seele Davids feind ist. Daher spricht man: Laft keinen Blinden und Lahmen ins Haus kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Also wohnete David auf der Burg und hieft sie Davids Stadt. Und David bauete umher von Millo und inwendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Und David ging und nahm zu, und der HERR, der Gott Zebaoth, war mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Und Hiram, der Konig zu Tyrus, sandte Boten zu David und Zedernbaume zur Wand und Zimmerleute und Steinmetzen, daß sie David ein Haus baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Und David merkte, daß ihn der HERR zum Konige uber Israel bestatiget hatte und sein Konigreich erhohet urn seines Volks Israel willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Und David nahm noch mehr Weiber und Kebsweiber zu Jerusalem, nachdem er von Hebron kommen war; und wurden ihm noch mehr Sohne und Tochter geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Und das sind die Namen derer, die ihm zu Jerusalem geboren sind: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jebehar, Elisua, Nepheg, Japhia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eliada, Eliphalet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Und da die Philister horeten, daß man David zum Konige uber Israel gesalbet hatte, zogen sie alle herauf, David zu suchen. Da das David erfuhr, zog er hinab in eine Burg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Aber die Philister kamen und lieften sich nieder im Grunde Rephaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Und David fragte den HERRN und sprach: Soli ich hinaufziehen wider die Philister, und willst du sie in meine Hand geben? Der HERR sprach zu David: Zeuch hinauf, ich will die Philister in deine Hande geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Und David kam gen Baal-Prazim und schlug sie daselbst und sprach: Der HERR hat meine Feinde vor mir voneinander gerissen, wie die Wasser reiften. Daher hieft man denselben Ort Baal-Prazim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Und sie lieften ihren Gotzen daselbst. David aber und seine Manner huben sie auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Die Philister aber zogen abermal herauf und lieften sich nieder im Grunde Rephaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Und David fragte den HERRN; der sprach: Du sollst nicht hinaufziehen, sondem komm von hinten zu ihnen, daß du an sie kommest gegen den Maulbeerbaumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Und wenn du horen wirst das Rauschen auf den Wipfeln der Maulbeerbaume einhergehen, so zaue dich; denn der HERR ist dann ausgegangen vor dir her, zu schlagen das Heer der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David tat, wie der HERR ihm geboten hatte, und schlug die Philister von Geba an, bis man kommt gen Gaser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Und David sammelte abermal alle junge Mannschaft in Israel, dreiftigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Und machte sich auf und ging hin mit allem Volk, das bei ihm war aus den Burgern Judas, daß er die Lade Gottes von dannen heraufholete, welcher Name heiftt: Der Name des HERRN Zebaoth wohnet drauf uber den Cherubim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Und sie lieften die Lade Gottes fuhren auf einem neuen Wagen und holeten sie aus dem Hause Abinadabs, der zu Gibea wohnete. Usa aber und Ahio, die Sohne Abinadabs, trieben den neuen Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Und da sie ihn mit der Lade Gottes aus dem Hause Abinadabs fuhreten, der zu Gibea wohnete, und Ahio vor der Lade her ging,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'spielte David und das ganze Haus Israel vor dem HERRN her mit allerlei Saitenspiel von Tannenholz, mit Harfen und Psaltern und Pauken und Schellen und Zimbeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Und da sie kamen zur Tenne Nachon, griff Usa zu und hielt die Lade Gottes, denn die Rinder traten beiseit aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Da ergrimmete des HERRN Zorn uber Usa; und Gott schlug ihn daselbst urn seines Frevels willen, daß er daselbst starb bei der Lade Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Da ward David betrubt, daß der HERR einen solchen Rift an Usa tat; und hieft dieselbige Statte Perez-Usa bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Und David furchtete sich vor dem HERRN des Tages und sprach: Wie soil die Lade des HERRN zu mir kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Und wollte sie nicht lassen zu sich bringen in die Stadt Davids, sondem lieft sie bringen in das Haus Obed-Edoms, des Gathiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Und da die Lade des HERRN drei Monden blieb im Hause Obed-Edoms, des Gathiters, segnete ihn der HERR und sein ganzes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Und es ward dem Konige David angesagt, daß der HERR das Haus Obed-Edoms segnete und alles, was er hatte, urn der Lade Gottes willen. Da ging er hin und holte die Lade Gottes aus dem Hause Obed- Edoms herauf in die Stadt Davids mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Und da sie einhergingen mit der Lade des HERRN sechs Gange, opferte man einen Ochsen und ein fett Schaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Und David tanzte mit aller Macht vor dem HERRN her und war begurtet mit einem leinenen Leibrock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Und David samt dem ganzen Israel fuhreten die Lade des HERRN herauf mit Jauchzen und Posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Und da die Lade des HERRN in die Stadt Davids kam, guckte Michal, die Tochter Sauls, durchs Fenster und sah den Konig David springen und tanzen vordem HERRN, und verachtete ihn in ihrem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Da sie aber die Lade des HERRN hineinbrachten, stelleten sie die an ihren Ort mitten in der Hütte, die David fur sie hatte aufgeschlagen. Und David opferte Brandopfer und Dankopfer vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Und da David hatte ausgeopfert die Brandopfer und Dankopfer, segnete er das Volk in dem Namen des HERRN Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Und teilete aus allem Volk und der Menge Israels, beide Mann und Weib, einem jeglichen einen Brotkuchen und ein Stuck Fleisch und ein Noftel Wein. Da kehrete sich alles Volk hin, ein jeglicher in sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Da aber David wiederkam, sein Haus zu segnen, ging Michal, die Tochter Sauls, heraus ihm entgegen und sprach: Wie herrlich ist heute der Konig von Israel gewesen, der sich vor den Magden seiner Knechte entbloliet hat, wie sich die losen Leute entbloften!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'David aber sprach zu Michal: Ich will vor dem HERRN spielen, der mich erwahlet hat vor deinem Vater und vor all seinem Hause, dad er mir befohlen hat, ein Fürst zu sein uber das Volk des HERRN, uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Und will noch geringer werden denn also; und will niedrig sein in meinen Augen und mit den Magden, davon du geredet hast, zu Ehren werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Aber Michal, Sauls Tochter, hatte kein Kind bis an den Tag ihres Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Da nun der Konig in seinem Hause sali, und der HERR ihm Ruhe gegeben hatte von alien seinen Feinden umher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'sprach erzu dem Propheten Nathan: Siehe ich wohne in einem Zedernhause, und die Lade Gottes wohnet unter den Teppichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Nathan sprach zu dem Konige: Gehe hin; alles, was du in deinem Herzen hast, das tue; denn der HERR ist mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Des Nachts aber kam das Wort des HERRN zu Nathan und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Gehe hin und sage zu meinem Knechte David: So spricht der HERR: Solltest du mir ein Haus bauen, dad ich drinnen wohnete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Habe ich doch in keinem Hause gewohnet seit dem Tage, da ich die Kinder Israel aus Agypten fuhrete, bis auf diesen Tag, sondern ich habe gewandelt in der Hütte und Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Wo ich mit alien Kindern Israel hinwandelte, habe ich auch je geredet mit irgend der Stamme Israel einem, denen ich befohlen habe, mein Volk Israel zu weiden, und gesagt: Warum bauet ihr mir nicht ein Zedernhaus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'So sollst du nun so sagen meinem Knechte David: So spricht der HERR Zebaoth: Ich habe dich genommen von den Schafhürden, dad du sein solltest ein Fürst uber mein Volk Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'und bin mir dir gewesen, wo du hingegangen bist, und habe alle deine Feinde vor dir ausgerottet und habe dir einen groden Namen gemacht, wie der Name der Groden auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Und ich will meinem Volk Israel einen Ortsetzen und will es pflanzen, dad es daselbst wohne und es nicht mehr in der Irre gehe, und es die Kinder der Bosheit nicht mehr drangen, wie vorhin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'und seit der Zeit ich Richter über mein Volk Israel verordnet habe; und will dir Ruhe geben von alien deinen Feinden. Und der HERR verkundiget dir, dad der HERR dir ein Haus machen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Wenn nun deine Zeit hin ist, dad du mit deinen Vatern schlafen liegest, will ich deinen Samen nach dir erwecken, der von deinem Leibe kommen soil, dem will ich sein Reich bestatigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Der soil meinem Namen ein Haus bauen, und ich will den Stuhl seines Konigreichs bestatigen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ich will sein Vater sein, und ersoll mein Sohn sein. Wenn er eine Missetat tut, will ich ihn mit Menschenruten und mit der Menschenkinder Schlagen strafen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'aber meine Barmherzigkeit soil nicht von ihm entwandt werden, wie ich sie entwandt habe von Saul, den ich vor dir habe weggenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Aber dein Haus und dein Konigreich soli bestandig sein ewiglich vor dir, und dein Stuhl soil ewiglich bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Da Nathan alle diese Worte und all dies Gesicht David gesagt hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'kam David, der Konig, und blieb vordem HERRN und sprach: Wer bin ich, Herr, HERR, und was ist mein Haus, daß du mich bis hieher gebracht hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Dazu hast du das zu wenig geachtet, Herr, HERR, sondern hast dem Hause deines Knechts noch von fernem Zukünftigen geredet. Das ist eine Weise eines Menschen, der Gott der HERR ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Und was soli David mehr reden mit dir? Du erkennest deinen Knecht, Herr, HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Urn deines Worts willen und nach deinem Herzen hast du solche grofte Dinge alle getan, daß du sie deinem Knechte kundtatest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Darum bist du auch graft geachtet, HERR Gott; denn es ist keiner wie du, und ist kein Gott, denn du, nach allem, das wir mit unsern Ohren gehoret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Denn wo ist ein Volk auf Erden wie dein Volk Israel, urn welches willen Gott ist hingegangen, ihm ein Volk zu erlosen und ihm einen Namen zu machen und solch grofte und schreckliche Dinge zu tun auf demem Lande vor deinem Volk, welches du dir erloset hast von Agypten, von den Heiden und ihren Gottern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Und du hast dir dein Volk Israel zubereitet, dir zum Volk in Ewigkeit; und du, HERR, bist ihr Gott worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'So bekraftige nun, HERR Gott, das Wort in Ewigkeit, das du uber deinen Knecht und fiber sein Haus geredet hast, und tue, wie du geredet hast:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'so wird dein Name grofi werden in Ewigkeit, daß man wird sagen: Der HERR Zebaoth ist der Gott uber Israel. Und das Haus deines Knechts David wird bestehen vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Denn du, HERR Zebaoth, du Gott Israels, hast das Ohr deines Knechts geoffnet und gesagt: Ich will dir ein Haus bauen. Darum hat dein Knecht sein Herz funden, daß er dies Gebet zu dir betet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Nun, Herr, HERR, du bist Gott, und deine Worte werden Wahrheit sein. Du hast solches Gut uber deinen Knecht geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'So hebe nun an und segne das Haus deines Knechts, daß es ewiglich vor dir sei; denn du, Herr, HERR, hast\'s geredet, und mit deinem Segen wird deines Knechts Haus gesegnet werden ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Und es begab sich danach, daß David die Philister schiug und schwachte sie; und nahm den Dienstzaum von der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Er schiug auch die Moabiter also zu Boden, daß er zwei Teile zum Tode brachte und ein Teil beim Leben lieft. Also wurden die Moabiter David untertanig, daß sie ihm Geschenke zutrugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David schiug auch Hadadeser, den Sohn Rehobs, Konig zu Zoba, da er hinzog, seine Macht wieder zu holen an dem Wasser Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Und David fing aus ihnen tausend und siebenhundert Reiter und zwanzigtausend Fuftvolks; und verlahmte alle Wagen und behielt ubrig hundert Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Es kamen aber die Syrer von Damaskus, zu helfen Hadadeser, dem Konige zu Zoba; und David schiug der Syrer zweiundzwanzigtausend Mann');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'und legte Volk gen Damaskus in Syrien. Also ward Syrien David untertanig, daß sie ihm Geschenke zutrugen. Denn der HERR half David, wo er hinzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Und David nahm die guldenen Schilde, die Hadadesers Knechten waren, und brachte sie gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Aber von Betah und Berothai, den Stadten Hadadesers, nahm der Konig David fast viel Erzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Da aber Thoi, der Konig zu Hemath, horete, daß David hatte alle Macht des Hadadeser geschlagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'sandte er Joram, seinen Sohn, zu David, ihn freundlich zu grüften und ihn zu segnen, daß er wider Hadadeser gestritten und ihn geschlagen hatte (denn Thoi hatte einen Streit mit Hadadeser), und er hatte mit sich silberne, guldene und eherne Kleinode,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'weiche der Konig David auch dem HERRN heiligte samt dem Silber und Golde, das er dem HERRN heiligte von alien Heiden, die er unter sich brachte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'von Syrien, von Moab, von den Kindern Ammon, von den Philistern, von Amalek, vom Raube Hadadesers, des Sohns Rehobs, Konigs zu Zoba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Auch machte ihm David einen Namen, da er wiederkam und die Syrer schiug im Salztai, achtzehntausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Und er legte Volk in ganz Edomaa, und ganz Edom war David unterworfen; denn der HERR half David, wo er hinzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Also ward David Konig uber ganz Israel, und er schaffte Recht und Gerechtigkeit allem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab, der Sohn Zerujas, war uber das Heer; Josaphat aber, der Sohn Ahiluds, war Kanzler;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, der Sohn Ahitobs, und Ahimelech, der Sohn Abjathars, waren Priester; Seraja war Schreiber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, der Sohn Jojodas, war uber die Krethi und Plethi; und die Sohne Davids waren Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Und David sprach: Ist auch noch jemand uberblieben von dem Hause Sauls, daß ich Barmherzigkeit an ihm tue urn Jonathans willen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Es war aber ein Knecht vom Hause Sauls, der hieft Ziba, den riefen sie zu David. Und der Konig sprach zu ihm: Bist du Ziba? Er sprach: Ja, dein Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Der Konig sprach: Ist noch jemand vom Hause Sauls, daß ich Gottes Barmherzigkeit an ihm tue? Ziba sprach zum Konige: Es ist noch da ein Sohn Jonathans, lahm an Fuften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Der Konig sprach zu ihm: Wo ist er? Ziba sprach zum Konige: Siehe, eristzu Lodabar, im Hause Machirs, des Sohns Ammiels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Da sandte der Konig David hin und lieft ihn holen von Lodabar aus dem Hause Machirs, des Sohns Ammiels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Da nun Mephiboseth, der Sohn Jonathans, des Sohns Sauls, zu David kam, fiel er auf sein Angesicht und betete an. David aber sprach: Mephiboseth! Er sprach: Hie bin ich, dein Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David sprach zu ihm: Furchte dich nicht; denn ich will Barmherzigkeit an dir tun urn Jonathans, deines Vaters, willen und will dir alien Acker deines Vaters Saul wiedergeben; du aber sollst taglich auf meinem Tisch das Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Er aber betete an und sprach: Wer bin ich, dein Knecht, daß du dich wendest zu einem toten Hunde, wie ich bin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Da rief der Konig Ziba, dem Knaben Sauls, und sprach zu ihm: Alles, was Sauls gewesen ist und seines ganzen Hauses, habe ich dem Sohn deines Herm gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'So arbeite ihm nun seinen Acker, du und deine Kinder und Knechte, und bringe es ein, daß es deines Herrn Sohnes Brot sei, daß er sich nahre; aber Mephiboseth, deines Herrn Sohn, soli taglich das Brot essen auf meinem Tisch. Ziba aber hatte funfzehn Sohne und zwanzig Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Und Ziba sprach zum Konige: Alles, wie mein Herr, der Konig, seinem Knechte geboten hat, so soil sein Knecht tun. Und Mephiboseth esse auf meinem Tisch, wie des Konigs Kinder eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Und Mephiboseth hatte einen kleinen Sohn, der hieli Micha. Aber alles, was im Hause Zibas wohnete, das dienete Mephiboseth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Mephiboseth aber wohnete zu Jerusalem, denn er ali taglich auf des Konigs Tisch; und hinkte mit seinen beiden Füfien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Und es begab sich danach, daß der Konig der Kinder Ammon starb; und sein Sohn Hanon ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Da sprach David: Ich will Barmherzigkeit tun an Hanon, dem Sohn Nahas, wie sein Vater an mir Barmherzigkeit getan hat. Und sandte hin und lieli ihn trosten durch seine Knechte uber seinen Vater. Da nun die Knechte Davids ins Land der Kinder Ammon kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'sprachen die Gewaltigen der Kinder Ammon zu ihrem Herrn Hanon: Meinest du, daß David deinen Vater ehre vor deinen Augen, daß er Troster zu dir gesandt hat? Meinest du nicht, daß er darum hat seine Knechte zu dir gesandt, daß er die Stadt erforsche und erkunde und umkehre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Da nahm Hanon die Knechte Davids und beschor ihnen den Bart halb und schnitt ihnen die Kleider halb ab bis an den Gurtel und lieli sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Da das David ward angesagt, sandte er ihnen entgegen; denn die Manner waren sehr geschandet. Und der Konig lieli ihnen sagen: Bleibetzu Jericho, bis euer Bart gewachsen, so kommt dann wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Da aber die Kinder Ammon sahen, daß sie vor David stinkend waren worden, sandten sie hin und dingeten die Syrer des Hauses Rehob und die Syrer zu Zoba, zwanzigtausend Mann Fulivolks, und von dem Konig Maacha tausend Mann und von Istob zwolftausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Da das David horete, sandte er Joab mit dem ganzen Heerder Kriegsleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Und die Kinder Ammon zogen aus und rusteten sich zum Streit vor der Tür des Tors. Die Syrer aber von Zoba, von Rehob, von Istob und von Maacha waren allein im Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Da Joab nun sah, daß der Streit auf ihn gestellet war, vorne und hinten, erwahlete eraus aller jungen Mannschaft in Israel und rustete sich wider die Syrer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Und das ubrige Volk tat er unter die Hand seines Bruders Abisai, daß er sich rustete wider die Kinder Ammon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'und sprach: Werden mir die Syrer uberlegen sein, so komm mir zu Hilfe; werden aber die Kinder Ammon dir uberlegen sein, so will ich dir zu Hilfe kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sei getrost und lali uns stark sein fur unser Volk und fur die Stadte unsers Gottes; der HERR aber tue, was ihm gefallt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Und Joab machte sich herzu mit dem Volk, das bei ihm war, zu streiten wider die Syrer; und sie flohen vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Und da die Kinder Ammon sahen, daß die Syrer flohen, flohen sie auch vor Abisai und zogen in die Stadt. Also kehrete Joab urn von den Kindern Ammon und kam gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Und da die Syrer sahen, daß sie geschlagen waren vor Israel, kamen sie zuhauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Und Hadadeser sandte hin und brachte heraus die Syrer jenseit des Wassers und fuhrete herein ihre Macht; und Sobach, der Feldhauptmann Hadadesers, zog vor ihnen her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Da das David ward angesagt, sammelte er zuhauf das ganze Israel und zog uber den Jordan und kam gen Helam. Und die Syrer rusteten sich wider David, mit ihm zu streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Aber die Syrer flohen vor Israel; und David erwürgete der Syrer siebenhundert Wagen und vierzigtausend Reiter; dazu Sobach, den Feldhauptmann, schlug er, daß er daselbst starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Da aber die Konige, die unter Hadadeser waren, sahen, daß sie geschlagen waren vor Israel, machten sie Frieden mit Israel und wurden ihnen untertan. Und die Syrer furchteten sich, den Kindern Ammon mehrzu helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Und da das Jahr urn kam, zur Zeit wenn die Konige pflegen auszuziehen, sandte David Joab und seine Knechte mit ihm und das ganze Israel, daß sie die Kinder Ammon verderbeten und belegten Rabba, David aber blieb zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Und es begab sich, daß David urn den Abend aufstund von seinem Lager und ging auf dem Dach des Konigshauses und sah vom Dach ein Weib sich waschen; und das Weib war sehr schoner Gestalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Und David sandte hin und lieli nach dem Weibe fragen und sagen: 1st das nicht Bathseba, die Tochter Eliams, das Weib Urias, des Hethiters?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Und David sandte Boten hin und lieli sie holen. Und da sie zu ihm hineinkam, schlief er bei ihr. Sie aber reinigte sich von ihrer Unreinigkeit und kehrete wieder zu ihrem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Und das Weib ward schwanger und sandte hin und lieli David verkündigen und sagen: Ich bin schwanger worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'David aber sandte zu Joab: Sende zu mir Uria, den Hethiter. Und Joab sandte Uria zu David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Und da Uria zu ihm kam, fragte David, ob es mit Joab und mit dem Volk und mit dem Streit wohl zustünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Und David sprach zu Uria: Gehe hinab in dein Haus und wasche deine Fufie. Und da Uria zu des Konigs Haus hinausging, folgte ihm nach des Konigs Geschenk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Und Uria legte sich schlafen vor der Tur des Konigshauses, da alle Knechte seines Herm lagen, und ging nicht hinab in sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Da man aber David ansagte: Uria ist nicht hinab in sein Haus gegangen, sprach David zu ihm: Bist du nicht uber Feld herkommen? Warum bist du nicht hinab in dein Haus gegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Uria aber sprach zu David: Die Lade und Israel und Juda bleiben in Zelten, und Joab, mein Herr, und meines Herm Knechte liegen zu Felde; und ich sollte in mein Haus gehen, daü ich alie und tranke und bei meinem Weibe lage? So wahr du lebest und deine Seele lebet, ich tue solches nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'David sprach zu Uria: So bleib heute auch hie, morgen will ich dich lassen gehen. So blieb Uria zu Jerusalem des Tages und des andern dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Und David lud ihn, daß er vor ihm ali und trank; und machte ihn trunken. Und des Abends ging eraus, dafi er sich schlafen legte auf sein Lager mit seines Herm Knechten; und ging nicht hinab in sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Des Morgens schrieb David einen Brief zu Joab und sandte ihn durch Uria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Er schrieb aber also in den Brief: Stellet Uria an den Streit, da er am hartesten ist, und wendet euch hinter ihm ab, daü er erschlagen werde und sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Als nun Joab urn die Stadt lag, stellete er Uria an den Ort, da er wuüte, daß streitbare Manner waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Und da die Manner der Stadt herausfielen und stritten wider Joab, fielen etliche des Volks von den Knechten Davids, und Uria, der Hethiter, starb auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Da sandte Joab hin und lieli David ansagen alien Handel des Streits.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Und gebot dem Boten und sprach: Wenn du alien Handel des Streits hast ausgeredet mit dem Konige');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'und siehest, daü der Konig erzurnet und zu dir spricht: Warum habt ihr euch so nahe zur Stadt gemacht mit dem Streit? Wisset ihr nicht, wie man pflegt von der Mauer zu schielien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Werschlug Abimelech, den Sohn Jerubbeseths? Warf nicht ein Weib ein Stuck von einer Muhle auf ihn von der Mauer, daü er starb zu Thebez? Warum habt ihr euch so nahe zur Mauer gemacht? so sollst du sagen: Dein Knecht Uria, der Hethiter, ist auch tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Der Bote ging hin und kam und sagte an David alles, darum ihn Joab gesandt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Und der Bote sprach zu David: Die Manner nahmen uberhand wider uns und fielen zu uns heraus aufs Feld wir aber waren an ihnen bis vor die Tur des Tors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Und die Schützen schossen von der Mauer auf deine Knechte und toteten etliche von des Konigs Knechten; dazu ist Uria, dein Knecht, der Hethiter, auch tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David sprach zum Boten: So sollst du zu Joab sagen: Lafi dir das nicht ubel gefalien; denn das Schwert frilit jetzt diesen, jetzt jenen. Haltet an mit dem Streit wider die Stadt, daß du sie zerbrechest, und seid getrost!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Und da Urias Weib horete, daß ihr Mann Uria tot war, trug sie Leid urn ihren Hauswirt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Da sie aber ausgetrauert hatte, sandte David hin und lieli sie in sein Haus holen; und sie ward sein Weib und gebar ihm einen Sohn. Aber die Tat gefiel dem HERRN ubel, die David tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Und der HERR sandte Nathan zu David. Da der zu ihm kam, sprach er zu ihm: Es waren zween Manner in einer Stadt, einer reich, der andere arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Der Reiche hatte sehr viele Schafe und Rinder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'aber der Arme hatte nichts denn ein einiges kleines Schaflein, das er gekauft hatte; und er nahrete es, daß es groli ward bei ihm und bei seinen Kindern zugleich; es ali von seinem Bissen und trank von seinem Becher und schlief in seinem Scholi, und er hielt\'s wie eine Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Da aber dem reichen Mann ein Gast kam, schonete er, zu nehmen von seinen Schafen und Rindern, daü er dem Gast etwas zurichtete, der zu ihm kommen war, und nahm das Schaf des armen Mannes und richtete es zu dem Manne, der zu ihm kommen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Da ergrimmete David mit groliem Zorn wider den Mann und sprach zu Nathan: So wahr der HERR lebt, der Mann ist ein Kind des Todes, der das getan hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Dazu soli er das Schaf vierfaltig bezahlen, darum daß er solches getan und nicht geschonet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Da sprach Nathan zu David: Du bist der Mann. So spricht der HERR, der Gott Israels: Ich habe dich zum Konige gesalbet uber Israel und habe dich errettet aus der Hand Sauls;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'und habe dirdeines Herrn Haus gegeben, dazu seine Weiber in deinen Scholi, und habe dir das Haus Israel und Juda gegeben; und ist das zu wenig, will ich noch dies und das dazu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Warum hast du denn das Wort des HERRN verachtet, daß du solches Ubel vor seinen Augen tatest? Uria, den Hethiter, hast du erschlagen mit dem Schwert; sein Weib hast du dir zum Weib genommen, ihn aber hast du erwürget mit dem Schwert der Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Nun, so soil von deinem Hause das Schwert nicht lassen ewiglich, darum daß du mich verachtet hast und das Weib Urias, des Hethiters, genommen hast, daß sie dein Weib sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'So spricht der HERR: Siehe, ich will Ungluck über dich erwecken aus deinem eigenen Hause und will deine Weiber nehmen vor deinen Augen und will sie deinem Nachsten geben, daß er bei deinen Weibern schlafen soil an der lichten Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Denn du hast\'s heimlich getan; ich aber will dies tun vor dem ganzen Israel und an der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Da sprach David zu Nathan: Ich habe gesundiget wider den HERRN. Nathan sprach zu David: So hat auch der HERR deine Sunde weggenommen, du wirst nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Aberweil du die Feinde des HERRN hast durch diese Geschichte lastern gemacht, wird der Sohn, der dir geboren ist, des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Und Nathan ging heim. Und der HERR schlug das Kind, das Urias Weib David geboren hatte, daß es todkrank ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Und David ersuchte Gott um das Knablein und fastete; und ging hinein und lag uber Nacht auf der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Da stunden auf die Altesten seines Hauses und wollten ihn aufrichten von der Erde; erwollte aber nicht und ali auch nicht mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Am siebenten Tage aberstarb das Kind. Und die Knechte Davids furchteten sich, ihm anzusagen, daß das Kind tot ware. Denn sie gedachten: Siehe, da das Kind noch lebendig war, redeten wir mit ihm, und er gehorchte unserer Stimme nicht; wie viel mehr wird es ihm wehe tun, so wir sagen: Das Kind ist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Da aber David sah, dafi seine Knechte leise redeten, und merkte, daß das Kind tot ware, sprach er zu seinen Knechten: Ist das Kind tot? Sie sprachen: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Da stund David auf von der Erde und wusch sich und salbete sich und tat andere Kleider an; und ging in das Haus des HERRN und betete an. Und da er wieder heimkam, hieli er ihm Brot auftraqen und ali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Da sprachen seine Knechte zu ihm: Was ist das fur ein Ding, das du tust? Da das Kind lebte, fastetest du und weinetest; nun es aber gestorben ist, stehest du auf und issest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Er sprach: Um das Kind fastete ich und weinete, da es lebte; denn ich gedachte: Werweili, ob mir der HERR gnadig wird, daß das Kind lebendig bleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Nun es aber tot ist, was soil ich fasten? Kann ich es auch wiederum holen? Ich werde wohl zu ihm fahren, es kommt aber nicht wieder zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Und da David sein Weib Bathseba getrostet hatte, ging er zu ihr hinein und schlief bei ihr. Und sie gebar einen Sohn, den hieli er Salomo. Und der HERR liebte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Und er tat ihn unter die Hand Nathans, des Propheten; der hieli ihn Jedidja um des HERRN willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'So stritt nun Joab wider Rabba der Kinder Ammon und gewann die konigliche Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Und sandte Boten zu David und lieli ihm sagen: Ich habe gestritten wider Rabba und habe auch gewonnen die Wasserstadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'So nimm nun zuhauf das ubrige Volk und belagere die Stadt und gewinne sie, auf daß ich sie nicht gewinne und ich den Namen davon habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Also nahm David alles Volk zuhauf und zog hin und stritt wider Rabba und gewann sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Und nahm die Krone ihres Konigs von seinem Haupt, die am Gewicht einen Zentner Goldes hatte und Edelgesteine, und ward David auf sein Haupt gesetzt; und fuhrete aus der Stadt sehr viel Raubs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Aber das Volk drinnen fuhrete er heraus und legte sie unter eiserne Sagen und Zacken und eiserne Keile und verbrannte sie in Ziegelofen. So tat er alien Stadten der Kinder Ammon. Da kehrete David und alies Volk wieder gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Und es begab sich danach, daß Absalom, der Sohn Davids, hatte eine schone Schwester, die hieli Thamar; und Amnon, der Sohn Davids, gewann sie lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Und Amnon stellete sich krank um Thamars, seiner Schwester, willen. Denn sie war eine Jungfrau, und deuchte Amnon schwer sein, dati er ihr etwas sollte tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Amnon aber hatte einen Freund, der hieli Jonadab, ein Sohn Simeas, Davids Bruders; und derselbe Jonadab war ein sehr weiser Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Der sprach zu ihm: Warum wirst du so mager, du Konigssohn, von Tage zu Tage? Magst du mir\'s nicht ansagen? Da sprach Amnon zu ihm: Ich habe Thamar, meines Bruders Absalom Schwester, lieb gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab sprach zu ihm: Lege dich auf dein Bett und mache dich krank. Wenn dann dein Vater kommt, dich zu besehen, so sprich zu ihm: Lieber, lali meine Schwester Thamar kommen, daß sie mich atze und mache vor mir ein Essen, daß ich zusehe und von ihrer Hand esse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Also legte sich Amnon und machte sich krank. Da nun der Konig kam, ihn zu besehen, sprach Amnon zum Konige: Lieber, lati meine Schwester Thamar kommen, daß sie vor mir ein Gemuse Oder zwei mache, und ich von ihrer Hand esse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Da sandte David nach Thamar ins Haus und lieli ihr sagen: Gehe hin in das Haus deines Bruders Amnon und mache ihm eine Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Thamar ging hin ins Haus ihres Bruders Amnon; er aber lag zu Bette. Und sie nahm einen Teig und knetete und sott es vor seinen Augen und kochte ihm ein Gemuse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Und sie nahm das Gericht und schuttete es vor ihm aus; aber erweigerte sich zu essen. Und Amnon sprach: Laüt jedermann von mir hinausgehen! Und es ging jedermann von ihm hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Da sprach Amnon zu Thamar: Bringe das Essen in die Kammer, dafi ich von deiner Hand esse. Da nahm Thamar das Gemüse, das sie gemacht hatte, und brachte es zu Amnon, ihrem Bruder, in die Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Und da sieeszu ihm brachte, dafi er afie, ergriff er sie und sprach zu ihr: Komm her, meine Schwester, schlaf bei mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Sie aber sprach zu ihm: Nicht, mein Bruder, schwache mich nicht, denn so tut man nicht in Israel; tu nicht eine solche Torheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Wo will ich mit meiner Schande hin? Und du wirst sein wie die Toren in Israel. Rede aber mit dem Konige, der wird mich dir nicht versagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Abererwollte ihr nicht gehorchen und überwaltigte sie und schwachte sie und schlief bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Und Amnon ward ihr überaus gram, dafi der Haß grower war, denn vorhin die Liebe war. Und Amnon sprach zu ihr: Mache dich auf und hebe dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Sie aber sprach zu ihm: Das libel ist grofier denn das andere, das du an mir getan hast, dafi du mich ausstoßest. Aber er gehorchte ihrer Stimme nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'sondern rief seinem Knaben, der sein Diener war, und sprach: Treib diese von mir hinaus und schleuß die Tur hinter ihr zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Und sie hatte einen bunten Rock an; denn solche Rocke trugen des Konigs Tochter, weil sie Jungfrauen waren. Und da sie sein Diener hinausgetrieben und die Tur hinter ihr zugeschlossen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'warf Thamar Asche auf ihr Haupt und zerrifi den bunten Rock, den sie anhatte, und legte ihre Hand auf das Haupt und ging daher und schrie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Und ihr Bruder Absalom sprach zu ihr: Ist dein Bruder Amnon bei dirgewesen? Nun, meine Schwester, schweig stille, es ist dein Bruder, und nimm die Sache nicht so zu Herzen. Also blieb Thamar ledig in Absaloms, ihres Bruders, Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Und da der Konig David solches alles horete, ward er sehr zornig. Aber Absalom redete nicht mit Amnon, weder Boses noch Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Aber Absalom ward Amnon gram, darum daß er seine Schwester Thamar geschwacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Uber zwei Jahre aber hatte Absalom Schafscherer zu Baal-Hazor, die unter Ephraim liegt; und Absalom lud alle Kinder des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Und kam zum Konige und sprach: Siehe, dein Knecht hat Schafscherer; der Konig wolle samt seinen Knechten mit seinem Knechte gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Der Konig aber sprach zu Absalom: Nicht, mein Sohn, laß uns nicht alle gehen, daß wir dich nicht beschweren. Und da er ihn notigte, wollte er doch nicht gehen, sondern segnete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Absalom sprach: Soli denn nicht mein Bruder Amnon mit uns gehen? Der Konig sprach zu ihm: Warum soli er mit dir gehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Da notigte ihn Absalom, daß er mit ihm ließ Amnon und aile Kinder des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom aber gebot seinen Knaben und sprach: Sehet drauf, wenn Amnon guter Dinge wird von dem Wein, und ich zu euch spreche: Schlaget Amnon und totet ihn, daß ihr euch nicht furchtet, denn ich hab\'s euch geheißen; seid getrost und frisch dran!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Also taten die Knaben Absaloms dem Amnon, wie ihnen Absalom geboten hatte. Da stunden alle Kinder des Konigs auf, und ein jeglicher saß auf sein Maul und flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Und da sie noch auf dem Wege waren, kam das Gerucht vor David, daß Absalom hatte alle Kinder des Konigs erschlagen, daß nicht einer von ihnen übrig ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Da stund der Konig auf und zerriß seine Kleider und legte sich auf die Erde; und alle seine Knechte, die urn ihn her stunden, zerrissen ihre Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Da antwortete Jonadab, der Sohn Simeas, des Bruders Davids, und sprach: Mein Herr denke nicht, daß alle Knaben, die Kinder des Konigs, tot sind, sondern Amnon ist allein tot. Denn Absalom hat es bei sich behalten von dem Tage an, da er seine Schwester Thamar schwachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'So nehme nun mein Herr, der Konig, solches nicht zu Herzen, daß alle Kinder des Konigs tot seien, sondern Amnon ist allein tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalom aber floh. Und der Knabe auf der Warte hub seine Augen auf und sah, und siehe, ein groß Volk kam auf dem Wege nacheinander an der Seite des Berges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Da sprach Jonadab zum Konige: Siehe, die Kinder des Konigs kommen; wie dein Knecht gesagt hat, so ist\'s ergangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Und da er hatte ausgeredet, siehe, da kamen die Kinder des Konigs und huben ihre Stimme auf und weineten. Der Konig und alle seine Knechte weineten auch fast sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom aber floh und zog zu Thalmai, dem Sohn Ammihuds, dem Konige zu Gesur. Erabertrug Leid fiber seinen Sohn alle Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Da aber Absalom floh und gen Gesur zog, war er daselbst drei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Und der Konig David horete auf, auszuziehen wider Absalom; denn er hatte sich getrostet uber Amnon, daß er tot war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joab aber, der Sohn Zerujas, merkte, daß des Konigs Herz war wider Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Und sandte hin gen Thekoa und ließ holen von dannen ein kluges Weib und sprach zu ihr: Trage Leid und zeuch Leidekleider an und salbe dich nicht mit 01, sondern stelle dich wie ein Weib, das eine lange Zeit Leid getragen hat fiber einen Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Und sollstzum Konige hineingehen und mit ihm reden so und so. Und Joab gab ihr ein, was sie reden sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Und da das Weib von Thekoa mit dem Konige reden wollte, fiel sie auf ihr Antlitz zur Erde und betete an und sprach: Hilf mir, Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Der Konig sprach zu ihr: Was ist dir? Sie sprach: Ich bin eine Witwe, ein Weib, das Leid tragt, und mein Mann istgestorben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'und deine Magd hatte zween Sohne, die zankten miteinanderauf dem Felde, und da kein Retter war, schlug einer den andern und totete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Und siehe, nun stehet auf die ganze Freundschaft wider deine Magd und sagen: Gib her den, der seinen Bruder erschlagen hat, daß wir ihn toten fur die Seele seines Bruders, den er erwurget hat, und auch den Erben vertilgen; und wollen meinen Funken ausloschen, der noch übrig ist, daß meinem Manne kein Name und nichts ubrig bleibe auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Der Konig sprach zum Weibe: Gehe heim ich will fur dich gebieten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Und das Weib von Thekoa sprach zum Konige: Mein Herr Konig, die Missetat sei auf mir und auf meines Vaters Hause; der Konig aber und sein Stuhl sei unschuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Der Konig sprach: Wer wider dich redet, den bringe zu mir; so soil er nicht mehr dich antasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Sie sprach: der Konig gedenke an den HERRN, deinen Gott, daß der Blutracher nicht zu viel werden, zu verderben, und meinen Sohn nicht vertilgen. Er sprach: So wahr der HERR lebt, es soil kein Haar von deinem Sohn auf die Erde fallen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Und das Weib sprach: Laß, deine Magd meinem Herrn Konige etwas sagen. Er sprach: Sage her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Das Weib sprach: Warum hast du ein solches gedacht wider Gottes Volk, daß der Konig ein solches geredet hat, daß er sich verschuldige und seinen Verstoßenen nicht wieder holen lasset?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Denn wirsterben des Todes, undwiedas Wasser in die Erde verschleifet, das man nicht aufhalt; und Gott will nicht das Leben wegnehmen, sondern bedenket sich, daß nicht das Verstoßene auch von ihm verstoßen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'So bin ich nun kommen, mit meinem Herrn Konige solches zu reden; denn das Volk machte mir bange. Denn deine Magd gedachte: Ich will mit dem Konige reden; vielleicht wird er tun, was seine Magd sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Denn erwird seine Magd erhoren, daß er mich errette von der Hand aller, die mich samt meinem Sohn vertilgen wollen vom Erbe Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Und deine Magd gedachte: Meines Herrn, des Konigs, Wort soil mir ein T rest sein; denn mein Herr, der Konig, ist wie ein Engel Gottes, dafi er Gutes und Boses horen kann. Darum wird der HERR, dein Gott, mit dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Der Konig antwortete und sprach zum Weibe: Leugne mir nicht, was ich dich frage. Das Weib sprach: Mein Herr, der Konig, rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Der Konig sprach: Ist nicht die Hand Joabs mit dir in diesem allem? Das Weib antwortete und sprach: So wahr deine Seele lebt, mein Herr Konig, es ist niemand anders, weder zur Rechten noch zur Linken, denn wie mein Herr, der Konig, geredet hat. Denn dein Knecht Joab hat mir\'s geboten, und er hat solches alles deiner Magd eingegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Daß ich diese Sache also wenden sollte, das hat dein Knecht Joab gemacht. Aber mein Herr ist weise, wie die Weisheit eines Engels Gottes, daß er merket alles auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Da sprach der Konig zu Joab: Siehe, ich habe solches getan; so gehe hin und bringe den Knaben Absalom wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Da fiel Joab auf sein Antlitz zur Erde und betete an und dankte dem Konige und sprach: Heute merket dein Knecht, daß ich Gnade gefunden habe vor deinen Augen, mein Herr Konig, daß der Konig tut, was sein Knecht sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Also machte sich Joab auf und zog gen Gesur und brachte Absalom gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Aber der Konig sprach: Laß ihn wieder in sein Haus gehen und mein Angesicht nicht sehen. Also kam Absalom wieder in sein Haus und sah des Konigs Angesicht nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Es war aber in ganz Israel kein Mann so schon als Absalom, und hatte dieses Lob vor alien; von seiner Fußsohle an bis auf seine Scheitel war nicht ein Fehl an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Und wenn man sein Haupt beschor (das geschah gemeiniglich alle Jahre, denn es war ihm zu schwer, daß man\'s abscheren mußte), so wog sein Haupthaarzweihundertßekel nach dem koniglichen Gewicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Und Absalom wurden drei Sohne geboren und eine Tochter, die hieß Thamar, und war ein Weib schon von Gestalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Also blieb Absalom zwei Jahre zu Jerusalem, daß er des Konigs Angesicht nicht sah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Und Absalom sandte nach Joab, daß er ihn zum Konige sendete, und er wollte nicht zu ihm kommen. Er aber sandte zum andermal, noch wollte er nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Da sprach er zu seinen Knechten: Sehet das Stuck Ackers Joabs neben meinem, und er hat Gerste drauf; so gehet hin und stecket es mit Feuer an. Da steckten die Knechte Absaloms das Stuck mit Feuer an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Da machte sich Joab auf und kam zu Absalom ins Haus und sprach zu ihm: Warum haben deine Knechte mein Stuck mit Feuer angesteckt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom sprach zu Joab: Siehe, ich sandte nach dir und ließ dir sagen: Komm her, daß ich dich zum Konige sende und sagen lasse: Warum bin ich von Gesur kommen? Es ware mir besser, daß ich noch da ware. So laß mich nun das Angesicht des Konigs sehen; ist aber eine Missetat an mir, so tote mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Und Joab ging hinein zum Konige und sagte es ihm an. Und er rief dem Absalom, daß er hinein zum Konige kam; und er betete an auf sein Antlitz zur Erde vor dem Konige; und der Konig kussete Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Und es begab sich danach, daß Absalom lieli ihm machen Wagen und Rosse und funfzig Mann, die seine Trabanten waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Und Absalom machte sich also des Morgens fruhe auf und trat an den Weg bei dem Tor. Und wenn jemand einen Handel hatte, daß er zum Konige vor Gericht kommen sollte, rief ihn Absalom zu sich und sprach: Aus welcher Stadt bist du? Wenn dann der sprach: Dein Knecht ist aus der Stamme Israels einem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'so sprach Absalom zu ihm: Siehe, deine Sache ist recht und schlecht; aber du hast keinen Verhorer vom Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Und Absalom sprach: 0 wer setzet mich zum Richter im Lande, daß jedermann zu mir kame, der eine Sache und Gericht hat, daß ich ihm zum Rechten hulfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Und wenn jemand sich zu ihm tat, dafi er ihn wollte anbeten, so reckte er seine Hand aus und ergriff ihn und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Auf die Weise tat Absalom dem ganzen Israel, wenn sie kamen vor Gericht zum Konige, und stahl also das Herz der Manner Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Nach vierzig Jahren sprach Absalom zum Konige: Ich will hingehen und mein Gelubde zu Hebron ausrichten, das ich dem HERRN gelobt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Denn dein Knecht tat ein Gelubde, da ich zu Gesur in Syrien wohnete, und sprach: Wenn mich der HERR wieder gen Jerusalem bringet, so will ich dem HERRN einen Gottesdienst tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Der Konig sprach zu ihm: Gehe hin mit Frieden! Und er machte sich auf und ging gen Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Absalom aber hatte Kundschafter ausgesandt in alle Stamme Israels und lassen sagen: Wenn ihr der Posaunen Schall horen werdet, so sprechet: Absalom ist Konig worden zu Hebron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Es gingen aber mit Absalom zweihundert Mann, von Jerusalem berufen; aber sie gingen in ihrer Einfalt und wuliten nichts urn die Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Absalom aber sandte auch nach Ahitophel, dem Giloniten, Davids Rat, aus seiner Stadt Gilo. Da er nun die Opfer tat, ward der Bund stark; und das Volk lief zu und mehrete sich mit Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Da kam einer, dersagte es David an und sprach: Das Herz jedermanns in Israel folget Absalom nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'David sprach aber zu alien seinen Knechten, die bei ihm waren zu Jerusalem: Auf, I a lit uns fliehen, denn hie wird kein Entrinnen sein vor Absalom; eilet, daß wir gehen, daß er uns nicht ubereile und ergreife uns und treibe ein Ungluck auf uns und schlage die Stadt mit der Scharfe des Schwerts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Da sprachen die Knechte des Konigs zu ihm: Was mein Herr, der Konig, erwahlet, siehe, hie sind deine Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Und der Konig ging zu Fuli hinaus mit seinem ganzen Hause. Er lieli aber zehn Kebsweiber, das Haus zu bewahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Und da der Konig und alles Volkzu Fulie hinauskamen, traten sie feme vom Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Und alle seine Knechte gingen neben ihm her, dazu alle Krethi und Plethi und alle Gethiter, sechshundert Mann, die von Gath zu Fulie kommen waren, gingen vor dem Konige her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Und der Konig sprach zu Ithai, dem Gethiter: Warum gehest du auch mit uns? Kehre urn und bleibe bei dem Konige; denn du bist fremd und von deinem Ort gezogen hieher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Gestern bist du kommen und heute wagest du dich, mit uns zu gehen. Ich aber will gehen, wo ich hin kann gehen. Kehre urn, und deinen Brudern mit dir widerfahre Barmherzigkeit und Treue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Ithai antwortete und sprach: So wahr der HERR lebt, und so wahr mein Herr Konig lebt, an welchem Ort mein Herr, der Konig, sein wird, es gerate zum Tod Oder zum Leben, da wird dein Knecht auch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David sprach zu Ithai: So komm und gehe mit! Also ging Ithai, der Gethiter, und alle seine Manner und der ganze Haufe Kinder, die mit ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Und das ganze Land weinete mit lauter Stimme, und alles Volk ging mit. Und der Konig ging uber den Bach Kidron, und alles Volk ging vor auf dem Wege, derzur Wuste gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Und siehe, Zadok war auch da und alle Leviten, die bei ihm waren; und trugen die Lade des Bundes Gottes und stelleten sie dahin. Und Abjathar trat empor, bis daß alles Volk zur Stadt aus kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Aber der Konig sprach zu Zadok: Bringe die Lade Gottes wieder in die Stadt! Werde ich Gnade finden vor dem HERRN, so wird er mich wieder holen und wird mich sie sehen lassen und sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Spricht er aber also: Ich habe nicht Lust zu dir, siehe, hie bin ich, er mache es mit mir, wie es ihm wohlgefallet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Und der Konig sprach zu dem Priester Zadok: O du Seher, kehre urn wieder in die Stadt mit Frieden und miteuch eure beiden Sohne, Ahimaaz, dein Sohn, und Jonathan, der Sohn Abjathars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Siehe, ich will verziehen auf dem blachen Felde in der Wüste, bis daü Botschaft von euch komme und sage mir an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Also brachte Zadok und Abjathar die Lade Gottes wieder gen Jerusalem und blieben daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David aber ging den Olberg hinan und weinete, und sein Haupt war verhullet, und erging barfuli. Dazu alles Volk, das bei ihm war, hatte ein jeglicher sein Haupt verhullet, und gingen hinan und weineten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Und da es David angesagtward, daß Ahitophel im Bunde mit Absalom war, sprach er: HERR, mache den Ratschlag Ahitophels zur Narrheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Und da David aufdie Hohe kam, da man Gott pflegte anzubeten, siehe; da begegnete ihm Husai, der Arachiter, mit zerrissenem Rock und Erde auf seinem Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Und David sprach zu ihm: Wenn du mit mir gehest, wirst du mir eine Last sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Wenn du aberwieder in die Stadt gingest und sprachest zu Absalom: Ich bin dein Knecht, ich will des Konigs sein; der ich deines Vaters Knecht war zu der Zeit, will nun dein Knecht sein: so würdest du mir zu gut den Ratschlag Ahitophels zunichte machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'So ist Zadok und Abjathar, die Priester, mit dir. Alles, was du horetest aus des Konigs Hause, sagest du an den Priestern Zadok und Abjathar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Siehe, es sind bei ihnen ihre zween Sohne: Ahimaaz, Zadoks und Jonathan, Abjathars Sohn. Durch dieselbigen kannst du mir entbieten, was du horen wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Also kam Husai, der Freund Davids, in die Stadt; und Absalom kam gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Und da David ein wenig von der Hohe gegangen war, siehe, da begegnete ihm Ziba, der Knabe Mephiboseths, mit einem Paar Esel gesattelt; darauf waren zweihundert Brote und hundert Stuck Rosinen und hundert Stuck Feigen und ein Legel Weins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Da sprach der Konig zu Ziba: Was willst du damit machen? Ziba sprach: Die Esel sollen fur das Gesinde des Konigs, drauf zu reiten, und die Brote und Feigen fur die Knaben, zu essen, und der Wein, zu trinken, wenn sie müde werden in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Der Konig sprach: Wo ist der Sohn deines Herrn? Ziba sprach zum Konige: Siehe, er blieb zu Jerusalem; denn er sprach: Heute wird mir das Haus Israel meines Vaters Reich wiedergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Der Konig sprach zu Ziba: Siehe, es soil dein sein alles, was Mephiboseth hat. Ziba sprach: Ich bete an; lali mich Gnade finden vor dir, mein Herr Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Da aber der Konig David bis gen Bahurim kam, siehe, da ging ein Mann daselbst heraus vom Geschlecht des Hauses Sauls, der hiefi Simei, der Sohn Geras, der ging heraus und fluchte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'und warf David mit Steinen und alle Knechte des Konigs David. Denn alles Volk und alle Gewaltigen waren zu seiner Rechten und zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'So sprach aber Simei, da er fluchte: Heraus, heraus, du Bluthund, du loser Mann!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Der HERR hat dir vergolten alles Blut des Hauses Sauls, daß du an seiner Statt bist Konig worden. Nun hat der HERR das Reich gegeben in die Hand deines Sohns Absalom; und siehe, nun steckest du in deinem Ungluck, denn du bist ein Bluthund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Aber Abisai, der Sohn Zerujas, sprach zu dem Konige: Sollte diesertote Hund meinem Herrn, dem Konige, fluchen? Ich will hingehen und ihm den Kopf abreilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Der Konig sprach: Ihr Kinder Zerujas, was habe ich mit euch zu schaffen? Lalit ihn fluchen; denn der HERR hat es ihn geheilien: Fluche David! Wer kann nun sagen: Warum tust du also?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Und David sprach zu Abisai und zu alien seinen Knechten: Siehe, mein Sohn, der von meinem Leibe kommen ist, stehet mir nach meinem Leben, warum nicht auch jetzt der Sohn Jeminis? Lalit ihn bezahmen, daß er fluche; denn der HERR hat es ihn geheilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Vielleicht wird der HERR mein Elend ansehen und mir mit Güte vergelten sein heutiges Fluchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Also ging David mit seinen Leuten des Weges; aber Simei ging an des Berges Seite neben ihm her und fluchte und warf mit Steinen zu ihm und sprengete mit Erdenklolien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Und der Konig kam hinein mit allem Volk, das bei ihm war, mude, und erquickte sich daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Aber Absalom und alles Volk der Manner Israels kamen gen Jerusalem, und Ahitophel mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Da aber Husai, der Arachiter, Davids Freund, zu Absalom hineinkam, sprach er zu Absalom: Gluck zu, er Konig! Gluck zu, er Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom aber sprach zu Husai: Ist das deine Barmherzigkeit an deinem Freunde? Warum bistdu nicht mit deinem Freunde gezogen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husai aber sprach zu Absalom: Nicht also, sondern welchen der HERR erwahlet und dies Volk und alle Manner in Israel, des will ich sein und bei ihm bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Zum andern, wem sollte ich dienen? Sollte ich nicht vor seinem Sohn dienen? Wie ich vor deinem Vater gedienet habe, so will ich auch vor dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Und Absalom sprach zu Ahitophel: Ratet zu, was sollen wirtun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitophel sprach zu Absalom: Beschlaf die Kebsweiber deines Vaters, die er gelassen hat, das Haus zu bewahren, so wird das ganze Israel horen, daß du deinen Vater hast stinkend gemacht, und wird aller Hand, die bei dir sind, desto kuhner werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Da machten sie Absalom eine Hütte auf dem Dache; und Absalom beschlief die Kebsweiber seines Vaters vor den Augen des ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Zu der Zeit, wenn Ahitophel einen Rat gab, das war, als wenn man Gott urn etwas hatte gefragt; also waren alle Ratschlage Ahitophels beide bei David und bei Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Und Ahitophel sprach zu Absalom: Ich will zwolftausend Mann auslesen und mich aufmachen und David nachjagen bei der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Und will ihn überfallen, weil er matt und lali ist. Wenn ich ihn dann erschrecke, daß alles Volk, so bei ihm ist, fleucht, will ich den Konig alleine schlagen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'und alles Volk wieder zu dir bringen. Wenn dann jedermann zu dir gebracht ist, wie du begehrest, so bleibet alles Volk mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Das deuchte Absalom gut sein und alle Altesten in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Aber Absalom sprach: Lieber, lasset Husai, den Arachiten, auch rufen und horen, was er dazu sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Und da Husai hinein zu Absalom kam, sprach Absalom zu ihm: Solches hat Ahitophel geredet; sage du, sollen wir\'s tun Oder nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Da sprach Husai zu Absalom: Es ist nicht ein guter Rat, den Ahitophel auf diesmal gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Und Husai sprach weiter: Du kennestdeinen Vater wohl und seine Leute, daß sie stark sind und zorniges Gemüts, wie ein Bar, dem die Jungen auf einem Felde geraubt sind; dazu ist dein Vater ein Kriegsmann und wird sich nicht saumen mit dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Siehe, er hat sich jetzt vielleicht verkrochen irgend in einer Grube, Oder sonst an einem Ort. Wenn es dann geschahe, daß das erste Mai libel geriete, und kame ein Geschrei und sprache: Es ist eine Schlacht geschehen in dem Volk, das Absalom nachfolget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'so würde jedermann verzagt werden, derauch sonst ein Krieger ist und ein Herz hat wie ein Lowe. Denn es weift ganz Israel, daß dein Vater stark ist, und Krieger, die bei ihm sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Aber das rate ich, daß du zu dir versammelst ganz Israel, von Dan an bis gen Berseba, so viel als der Sand am Meer; und deine Person ziehe unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'So wollen wir ihn uberfallen, an welchem Ort wir ihn finden, und wollen über ihn kommen, wie der Tau auf die Erde fallt, daß wir an ihm und alien seinen Mannern nicht einen übrig lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Wird ersich aber in eine Stadt versammeln, so soil das ganze Israel Stricke an dieselbe Stadt werfen und sie in den Bach reiften, daß man nicht ein Kieselein dran finde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Da sprach Absalom und jedermann in Israel: Der Rat Husais, des Arachiten, ist besser denn Ahitophels Rat. Aber der HERR schickte es also, daß der gute Rat Ahitophels verhindert wurde, auf daß der HERR Unglück über Absalom brachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Und Husai sprach zu Zadok und Abjathar, den Priestern: So und so hat Ahitophel Absalom und den Altesten in Israel geraten; ich aber habe so und so geraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'So sendet nun eilend hin und lasset David ansagen und sprechet: Bleibe nicht über Nacht auf dem blachen Felde der Wüste, sondern mache dich hinüber, daß der Konig nicht verschlungen werde und alles Volk, das bei ihm ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonathan aber und Ahimaaz stunden bei dem Brunnen Rogel, und eine Magd ging hin und sagte es ihnen an. Sie aber gingen hin und sagten\'s dem Konige David an; denn sie durften sich nicht sehen lassen, daß sie in die Stadt kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Es sah sie aber ein Knabe und sagte es Absalom an. Aber die beiden gingen eilend hin und kamen in eines Mannes Haus zu Bahurim; der hatte einen Brunnen in seinem Hofe, dahinein stiegen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Und das Weib nahm und breitete eine Decke über des Brunnen Loch und breitete Grütze drüber, daß man es nicht merkte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Da nun die Knechte Absaloms zum Weibe ins Haus kamen, sprachen sie: Wo ist Ahimaaz und Jonathan? Das Weib sprach zu ihnen: Sie gingen über das Wasserlein. Und da sie suchten und nicht fanden, gingen sie wieder gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Und da sie weg waren, stiegen sie aus dem Brunnen und gingen hin und sagten\'s David, dem Konige, an und sprachen zu David: Machet euch auf und gehet eilend über das Wasser; denn so und so hat Ahitophel wider euch Rat gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Da machte sich David auf und alles Volk, das bei ihm war, und gingen über den Jordan, bis licht Morgen ward, und fehlete nicht an einem, der nicht über den Jordan gegangen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Als aber Ahitophel sah, daß sein Rat nicht fortgegangen war, sattelte er seinen Esel, machte sich auf und zog heim in seine Stadt; und beschickte sein Haus und hing sich und starb; und ward begraben in seines Vaters Grab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Und David kam gen Mahanaim. Und Absalom zog über den Jordan, und alle Manner Israels mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Und Absalom hatte Amasa an Joabs Statt gesetzt über das Heer. Es war aber Amasa eines Mannes Sohn, der hieft Jethra, ein Israelites welcher lag bei Abigail, der Tochter Nahas, der Schwester Zerujas, Joabs Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Israel aber und Absalom lagerten sich in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Da David gen Mahanaim kommen war, da brachten Sobi, der Sohn Nahas, von Rabbath der Kinder Ammon, und Machir, der Sohn Ammiels, von Lodabar, und Barsillai, ein Giladiter von Roglim');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Bettwerk, Becken, irden Gefaft, Weizen, Gerste, Mehl, Sangen, Bohnen, Linsen, Grütze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Honig, Butter, Schafe und Rinderkase zu David und zu dem Volk, das bei ihm war, zu essen. Denn sie gedachten, das Volk wird hungrig, müde und durstig sein in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Und David ordnete das Volk, das bei ihm war, und setzte über sie Hauptleute über tausend und über hundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Und sandte aus des Volks einen dritten Teil unter Joab und einen dritten Teil unter Abisai, dem Sohn Zerujas, Joabs Bruder, und einen dritten Teil unter Ithai, dem Gethiter. Und der Konig sprach zum Volk: Ich will auch mit euch ausziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Aber das Volk sprach: Du sollst nicht ausziehen; denn ob wir gleich fliehen Oder die Halfte sterben, so werden sie sich unser nicht annehmen; denn du bist, als wenn unser zehntausend waren; so ist\'s nun besser, dafi du uns aus der Stadt helfen mogest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Der Konig sprach zu ihnen: Was euch gefallt, das will ich tun. Und der Konig trat ans Tor, und alles Volk zog aus bei Hunderten und bei Tausenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Und der Konig gebot Joab und Abisai und Ithai und sprach: Fahret mir sauberlich mit dem Knaben Absalom! Und alles Volk horete es, da der Konig gebot alien Hauptleuten urn Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Und da das Volk hinauskam aufs Feld Israel entgegen, hub sich der Streit im Walde Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Und das Volk Israel ward daselbst geschlagen vor den Knechten Davids, daß desselben Tages eine grolie Schlacht geschah, zwanzigtausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Und war daselbst der Streit zerstreuet auf allem Lande; und der Wald frali viel mehr Volks des Tages, denn das Schwert frali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Und Absalom begegnete den Knechten Davids und ritt auf einem Maul. Und da das Maul unter eine grolie dicke Eiche kam, behing sein Haupt an der Eiche und schwebte zwischen FHimmel und Erde; aber sein Maul lief unter ihm weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Da das ein Mann sah, sagte er\'s Joab an und sprach: Siehe, ich sah Absalom an einer Eiche hangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Und Joab sprach zu dem Manne, der es ihm hatte angesagt: Siehe, sahest du das? Warum schlugest du ihn nicht daselbst zur Erde? so wollte ich dir von meinetwegen zehn Silberlinge und einen Gürtel gegeben haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Der Mann sprach zu Joab: Wenn du mir tausend Silberlinge in meine FHand gewogen hattest, so wollte ich dennoch meine Hand nicht an des Konigs Sohn gelegt haben. Denn der Konig gebot dir und Abisai und Ithai vorunsern Ohren und sprach: Hutet euch, daß nicht jemand dem Knaben Absalom (Leid tue)!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Oder wenn ich etwas Falsches getan hatte auf meiner Seele Fahr, weil dem Konige nichts verhohlen wird, wurdest du selbst wider mich gestanden sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Joab sprach: Ich kann nicht so lange bei dir verziehen. Da nahm Joab drei Spielie in seine Hand und stiefi sie Absalom ins Herz, da er noch lebte an der Eiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Und zehn Knaben, Joabs Waffentrager, machten sich umher und schlugen ihn zu Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Da blies Joab die Posaune und brachte das Volk wieder, da(S es nicht weiter Israel nachjagte; denn Joab wollte des Volks verschonen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Und sie nahmen Absalom und warfen ihn in den Wald in eine grolie Grube und legten einen sehr grolien Haufen Steine auf ihn. Und das ganze Israel floh, ein jeglicher in seine Hutte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom aber hatte ihm eine Saule aufgerichtet, da er noch lebte, die stehet im Kdnigsgrunde. Denn er sprach: Ich habe keinen Sohn, darum soil dies meines Namens Gedachtnis sein; und hiefi die Saule nach seinem Namen und heilit auch bis auf diesen Tag Absaloms Raum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaaz, der Sohn Zadoks, sprach: Lieber, lali mich laufen und dem Konige verkundigen, daß der HERR ihm Recht verschafft hat von seiner Feinde Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joab aber sprach zu ihm: Du bringest heute keine gute Botschaft. Einen andern Tag sollst du Botschaft bringen, und heute nicht; denn des Konigs Sohn ist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Aber zu Chusi sprach Joab: Gehe hin und sage dem Konige an, was du gesehen hast. Und Chusi betete Joab an und lief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Ahimaaz aber, der Sohn Zadoks, sprach abermal zu Joab: Wie, wenn ich auch liefe dem Chusi nach? Joab sprach: Was willst du laufen, mein Sohn? Komm her, du wirst nicht eine gute Botschaft bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Wie, wenn ich liefe? Er sprach zu ihm: So laufe doch! Also lief Ahimaaz strackswegs und kam Chusi vor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David aber sali zwischen zweien Toren. Und der Wachter ging aufs Dach des Tors an der Mauer und hub seine Augen auf und sah einen Mann laufen allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Und rief und sagte es dem Konige an. Der Konig aber sprach: Ist er alleine, so ist eine gute Botschaft in seinem Munde. Und da derselbige ging und herzukam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'sah der Wachter einen andern Mann laufen und rief in das Tor und sprach: Siehe, ein Mann lauft alleine. Der Konig aber sprach: Der ist auch ein guter Bote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Der Wachter sprach: Ich sehe des ersten Lauf als den Lauf Ahimaaz, des Sohns Zadoks. Und der Konig sprach: Es ist ein guter Mann und bringet eine gute Botschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaaz aber rief und sprach zum Konige: Friede! Und betete an vor dem Konige auf sein Antlitz zur Erde und sprach: Gelobt sei der HERR, dein Gott, der die Leute, die ihre Hand wider meinen Herrn, den Konig, aufhuben, ubergeben hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Der Konig aber sprach: Gehet es auch wohl dem Knaben Absalom? Ahimaaz sprach: Ich sah ein grol J Getümmel, da des Konigs Knecht Joab mich, deinen Knecht, sandte, und weili nicht, was es war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Der Konig sprach: Gehe herum und tritt daher! Und er ging herum und stund allda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Siehe, da kam Chusi und sprach: Hie gute Botschaft, mein Herr Konig! Der HERR hat dir heute Recht verschafft von der Hand aller, die sich wider dich auflehnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Der Konig aber sprach zu Chusi: Gehet es dem Knaben Absalom auch wohl? Chusi sprach: Es müsse alien Feinden meines Herrn Konigs gehen, wie es dem Knaben gehet, und alien, die sich wider dich auflehnen, ubel zu tun. Da ward der Konig traurig und ging hin auf den Saal im Tor und weinete; und im Gehen sprach er also: Mein Sohn Absalom, mein Sohn, mein Sohn Absalom! Wollte Gott, ich mußte fur dich sterben! 0 Absalom, mein Sohn, mein Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Und es ward Joab angesagt: Siehe, der Konig weinet und tragt Leid um Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Und ward aus dem Siege des Tages ein Leid unter dem ganzen Volk; denn das Volk hatte gehoret des Tages, daß sich der Konig um seinen Sohn bekümmerte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Und das Volk verstahl sich weg an dem Tage, dafi es nicht in die Stadt kam, wie sich ein Volk verstiehlet, das zuschanden worden ist, wenn\'s im Streit geflohen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Der Konig aber hatte sein Angesicht verhüllet und schrie laut: Ach, mein Sohn Absalom! Absalom, mein Sohn, mein Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Joab aber kam zum Konige ins Haus und sprach: Du hast heute schamrot gemacht alle deine Knechte, die heute deine, deiner Sohne, deiner Tochter, deiner Weiber und deiner Kebsweiber Seelen errettet haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'da(S du liebhabest, die dich hassen, und hassest, die dich liebhaben. Denn du lassest dich heute merken, daß dir\'s nicht gelegen ist an den Hauptleuten und Knechten. Denn ich merke heute wohi, wenn dir nur Absalom lebte, und wir heute alle tot waren, das deuchte dich recht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'So mache dich nun auf und gehe heraus und rede mit deinen Knechten freundlich. Denn ich schwore dir bei dem HERRN: Wirst du nicht herausgehen, es wird kein Mann an dir bleiben diese Nacht fiber. Das wird dir arger sein denn alles Ubel, das uber dich kommen ist von deiner Jugend auf bis hieher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Da machte sich der Konig auf und setzte sich ins Tor. Und man sagte es allem Volk: Siehe, der Konig sitzet im Tor. Da kam alles Volk vor den Konig. Aber Israel war geflohen, ein jeglicher in seine Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Und es zankte sich alles Volk in alien Stammen Israels und sprachen: Der Konig hat uns errettet von der Hand unserer Feinde und erlosete uns von der Philister Hand und hat müssen aus dem Lande fliehen vor Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'So ist Absalom gestorben im Streit, den wir uber uns gesalbet hatten. Warum seid ihr nun so stille, daß ihr den Konig nicht wieder holet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Der Konig aber sandte zu Zadok und Abjathar, den Priestern, und lieft ihnen sagen: Redet mit den Altesten in Juda und sprechet: Warum wollt ihr die letzten sein, den Konig wieder zu holen in sein Haus? (Denn die Rede des ganzen Israel war vor den Konig kommen in sein Haus.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Ihr seid meine Brüder, mein Bein und mein Fleisch; warum wollt ihr denn die letzten sein, den Konig wieder zu holen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Und zu Amasa sprechet: Bist du nicht mein Bein und mein Fleisch? Gott tue mir dies und das, wo du nicht sollst sein Feldhauptmann vor mir dein Leben lang an Joabs Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Und er neigete das Herz aller Manner Judas wie eines Mannes. Und sie sandten hin zum Konige: Komm wieder, du und alle deine Knechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Also kam der Konig wieder. Und da eran den Jordan kam, waren die Manner Judas gen Gilgal kommen, hinabzuziehen dem Konige entgegen, dafi sie den Konig fiber den Jordan fuhreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Und Simei, der Sohn Geras, des Sohns Jeminis, derzu Bahurim wohnete, eilete und zog mit den Mannern Judas hinab dem Konige David entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Und waren tausend Mann mit ihm von Benjamin, dazu auch Ziba, der Knabe aus dem Hause Sauls mit seinen funfzehn Sohnen und zwanzig Knechten, und fertigten sich durch den Jordan vor dem Konige her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Und machten die Furt, daß sie das Gesinde des Konigs hinuberfuhreten und taten, was ihm gefiele. Simei aber, der Sohn Geras, fiel vor dem Konige nieder, da er uber den Jordan fuhr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Und sprach zum Konige: Mein Herr, rechne mir nicht zu die Missetat und gedenke nicht, daß dein Knecht dich beleidigte des Tages, da mein Herr Konig aus Jerusalem ging, und der Konig nehme es nicht zu Herzen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'denn dein Knecht erkennet, daß ich gesundiget habe. Und siehe, ich bin heute der erste kommen unter dem ganzen Hause Josephs, daß ich meinem Herm Konige entgegen herabzoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Aber Abisai, der Sohn Zerujas, antwortete und sprach: Und Simei sollte darum nicht sterben, so er doch dem Gesalbten des HERRN geflucht hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'David aber sprach: Was habe ich mit euch zu schaffen, ihr Kinder Zerujas, daß ihr mir heute wollt zum Satan werden? Sollte heute jemand sterben in Israel? Meinest du, ich wisse nicht, daß ich heute ein Konig bin worden fiber Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Und der Konig sprach zu Simei: Du sollst nicht sterben. Und der Konig schwur ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mephiboseth, der Sohn Sauls, kam auch herab dem Konige entgegen. Und er hatte seine Fülie noch seinen Bart nicht gereiniget und seine Kleider nicht gewaschen von dem Tage an, da der Konig weggegangen war, bis an den Tag, da er mit Frieden kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Da er nun gen Jerusalem kam, dem Konige zu begegnen, sprach der Konig zu ihm: Warum bist du nicht mit mirgezogen, Mephiboseth?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Und er sprach: Mein Herr Konig, mein Knecht hat mich betrogen. Denn dein Knecht gedachte, ich will einen Esel satteln und drauf reiten und zum Konige ziehen; denn dein Knecht ist lahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Dazu hat er deinen Knecht angegeben vor meinem Herm Konige. Aber mein Herr Konig ist wie ein Engel Gottes; tue, was dir wohlgefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Denn all meines Vaters Haus ist nichts gewesen denn Leute des Todes vor meinem Herrn Konige; so hast du deinen Knecht gesetzt unter die, so auf deinem Tisch essen. Was habe ich weiter Gerechtigkeit, Oder weiter zu schreien an den Konig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Der Konig sprach zu ihm: Was redest du noch weiter von deinem Dinge? Ich habe es gesagt: Du und Ziba teilet den Acker miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Mephiboseth sprach zum Konige: Er nehme es auch gar dahin, nachdem mein Herr Konig mit Frieden heimkommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Und Barsillai, der Gileaditer, kam herab von Rogüm und fuhrete den Konig uber den Jordan, daß er ihn im Jordan geleitete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Und Barsillai war fast alt, wohl achtzig Jahre; der hatte den Konig versorget, weil er zu Mahanaim war, denn er war ein sehr trefflicher Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Und der Konig sprach zu Barsillai: Du sollst mit mir hinuberziehen, ich will dich versorgen bei mirzu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Aber Barsillai sprach zum Konige: Was ist\'s noch, das ich zu leben habe, daß ich mit dem Konige sollte hinauf gen Jerusalem ziehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Ich bin heute achtzig Jahre alt. Wie sollte ich kennen, was gut Oder bose ist, Oder schmecken, was ich esse Oder trinke, Oder horen, was die Sanger Oder Sangerinnen singen? Warum sollte dein Knecht meinen Herrn Konig fürder beschweren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Dein Knecht soli ein wenig gehen mit dem Konige uber den Jordan. Warum will mir der Konig eine solche Vergeltung tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Laft deinen Knecht umkehren, daß ich sterbe in meiner Stadt bei meines Vaters und meiner Mutter Grab. Siehe, da ist dein Knecht Chimeham, den laft mit meinem Herrn Konige hinuberziehen und tue ihm, was dir wohlgefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Der Konig sprach: Chimeham soli mit mir hinuberziehen, und ich will ihm tun, was dir wohlgefallt; auch alles, was du an mir erwahlest, will ich dir tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Und da alles Volk uber den Jordan war gegangen und der Konig auch, kussete der Konig den Barsillai und segnete ihn; und er kehrete wieder an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Und der Konig zog hinubergen Gilgal, und Chimeham zog mit ihm. Und alles Volk Juda hatte den Konig hinubergefuhret; aber des Volks Israel war nur die Halfte da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Und siehe, da kamen alle Manner Israels zum Konige und sprachen zu ihm: Warum haben dich unsere Bruder, die Manner Judas, gestohlen und haben den Konig und sein Haus uber den Jordan gefuhret und alle Manner Davids mit ihm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Da antworteten die von Juda denen von Israel: Der Konig gehoret uns nahe zu; was zurnet ihr darum? Meinet ihr, daß wir von dem Konige Nahrung Oder Geschenke empfangen haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'So antworteten dann die von Israel denen von Juda und sprachen: Wir haben zehnmal mehr bei dem Konige, dazu auch bei David denn ihr. Warum hast du mich denn so gering geachtet, daß das Unsere nicht das erste gewesen ist, unsern Konig zu holen? Aber die von Juda redeten harter denn die von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 44, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Und es war daselbst ein beruhmter heilloser Mann, der hieft Seba, ein Sohn Bichris, eines Mannes von Jemini; der blies die Posaune und sprach: Wir haben kein Teil an David noch Erbe am Sohne Isais. Ein jeglicher hebe sich zu seiner Hütte, o Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Da fiel von David jedermann in Israel und folgten Seba, dem Sohn Bichris. Aber die Manner Judas hingen an ihrem Konige, vom Jordan an bis gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Da aber der Konig David heimkam gen Jerusalem, nahm er die zehn Kebsweiber, die er hatte gelassen, das Haus zu bewahren, und tat sie in eine Verwahrung und versorgte sie; aber er beschlief sie nicht. Und sie waren also verschlossen bis an ihren Tod und lebten als Witwen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Und der Konig sprach zu Amasa: Berufe mir alle Manner in Juda auf den dritten Tag; und du sollst auch hie stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Und Amasa ging hin, Juda zu berufen; aber er verzog die Zeit, die er ihm bestimmte hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Da sprach David zu Abisai: Nun wird uns Seba, der Sohn Bichris, mehr Leides tun denn Absalom. Nimm du die Knechte deines Herrn und jage ihm nach, daß er nicht etwa fur sich feste Stadte finde und entrinne aus unsern Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Da zogen aus ihm nach die Manner Joabs, dazu die Krethi und Plethi und alle Starken. Sie zogen aber aus von Jerusalem, nachzujagen Seba, dem Sohn Bichris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Da sie aber bei dem groften Stein waren zu Gibeon, kam Amasa vor ihnen her. Joab aber war gegurtet uber seinem Kleide, das er anhatte, und hatte daruber ein Schwert gegurtet, das hing an seiner Hufte in der Scheide, das ging gerne aus und ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Und Joab sprach zu Amasa: Friede mit dir, mein Bruder! Und Joab fassete mit seiner rechten Hand Amasa bei dem Bart, daß er ihn kussete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Und Amasa hatte nicht acht auf das Schwert in der Hand Joabs; und er stach ihn damit in den Wanst, daß sein Eingeweide sich auf die Erde schuttete; und gab ihm keinen Stich mehr; und er starb. Joab aber und sein Bruder Abisai jagten nach Seba, dem Sohn Bichris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Und es trat einer von den Knaben Joabs neben ihn und sprach: Trotz, und mache sich einer an Joab und tue sich bei David nach Joab!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa aber lag im Blut gewalzet mitten auf der Strafte. Da aber einer sah, daß alles Volk da stehen blieb, wendete er Amasa von der Strafte auf den Acker und warf Kleider auf ihn, weil er sah, daß, wer an ihn kam, stehen blieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Da er nun aus der Straße getan war, folgte jedermann Joab nach, Seba, dem Sohn Bichris, nachzujagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Und erzog durch alle Stamme Israels gen Abel und Beth-Maacha und ganz Haberim; und sie versammelten sich und folgten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Und kamen und belegten ihn zu Abel und Beth- Maacha; und schutteten einen Schutt um die Stadt und traten an die Mauer; und alles Volk, das mit Joab war, stürmete und wollte die Mauer niederwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Da rief eine weise Frau aus der Stadt: Horet! Horet! Sprechet zu Joab, dafi er hie herzukomme; ich will mit ihm reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Und da erzu ihr kam, sprach die Frau: Bistdu Joab? Er sprach: Ja. Sie sprach zu ihm: Hore die Rede deiner Magd! Er sprach: Ich hore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Sie sprach: Vorzeiten sprach man: Werfragen will, der frage zu Abel; und so ging\'s wohl aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Ich bin eine von den friedsamen und treuen Stadten in Israel; und du willst die Stadt toten und die Mutter in Israel? Warum willst du das Erbteil des HERRN verschlingen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joab antwortete und sprach: Das sei feme, das sei feme von mir, daß ich verschlingen und verderben sollte! Es hat sich nicht also;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'sondern ein Mann vom Gebirge Ephraim, mit Namen Seba, der Sohn Bichris, hat sich emporet wider den Konig David. Gebet denselbigen her allein, so will ich von der Stadt ziehen. Die Frau sprach zu Joab: Siehe, sein Haupt soil zu dir uber die Mauer geworfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Und die Frau kam hinein zu allem Volk mit ihrer Weisheit. Und sie hieben Seba, dem Sohn Bichris, den Kopf ab und warfen ihn zu Joab. Da blies er die Posaune, und sie zerstreueten sich von der Stadt, ein jeglicher in seine Hutte. Joab aber kam wieder gen Jerusalem zum Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joab aber war uber das ganze Heer Israels. Benaja, der Sohn Jojadas, war uber die Krethi und Plethi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram war Rentmeister. Josaphat, der Sohn Ahiluds, war Kanzler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja war Schreiber. Zadok und Abjatharwaren Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Dazu war Ira, der Jairiter, Davids Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Es war auch eine Teurung zu Davids Zeiten, drei Jahre aneinander; und David suchte das Angesicht des HERRN. Und der HERR sprach: Um Sauls willen und um des Bluthauses willen, daß erdie Gibeoniter getotet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Da lieli der Konig die Gibeoniter rufen und sprach zu ihnen. (Die Gibeoniter aber waren nicht von den Kindern Israel, sondern ubrig von den Amoritern; aber die Kinder Israel hatten ihnen geschworen, und Saul suchte sie zu schlagen in seinem Eifer fur die Kinder Israel und Juda.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'So sprach nun David zu den Gibeonitern: Was soil ich euch tun, und womit soil ich suhnen, dafi ihr das Erbteil des HERRN segnet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Die Gibeoniter sprachen zu ihm: Es ist uns nicht um Gold noch Silberzu tun an Saul und seinem Hause und ist uns nicht zu tun, um jemand zu toten in Israel. Er sprach: Was sprechet ihr denn, daß ich euch tun soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Sie sprachen zum Konige: Den Mann, der uns verderbet und zunichte gemacht hat, sollen wir vertilgen, daß, ihm nichts bleibe in alien Grenzen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Gebet uns sieben Manner aus seinem Hause, dafi wir sie aufhangen dem HERRN zu Gibea Sauls, des Erwahlten des HERRN. Der Konig sprach: Ich will sie geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Aber der Konig verschonete Mephiboseths, des Sohns Jonathans, des Sohns Sauls, um des Eides willen des HERRN, der zwischen ihnen war, namlich zwischen David und Jonathan, dem Sohn Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Aber die zween Sohne Rizpas, der Tochter Ajas, die sie Saul geboren hatte, Armoni und Mephiboseth; dazu die fünf Sohne Michals, der Tochter Sauls, die sie dem Adriel geboren hatte, dem Sohn Barsillais, des Mahalothiters, nahm der Konig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'und gab sie in die Hand der Gibeoniter; die hingen sie aufdem Berge vordem HERRN. Also fielen diese sieben auf einmal und starben zur Zeit der ersten Ernte, wenn die Gerstenernte angehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Da nahm Rizpa, die Tochter Ajas, einen Sack und breitete ihn auf den Fels am Anfang der Ernte, bis das Wasser vom Himmel uber sie troff; und ließ des Tages die Vogel des Himmels nicht auf ihnen ruhen; noch des Nachts die Tiere des Feldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Und es ward David angesagt, was Rizpa, die Tochter Ajas, Sauls Kebsweib, getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Und David ging hin und nahm die Gebeine Sauls und die Gebeine Jonathans, seines Sohns, von den Bürgem zu Jabes in Gilead, die sie von der Gasse Beth-San gestohlen hatten, dahin sie die Philister gehanget hatten zu der Zeit, da die Philister Saul schlugen auf dem Berge Gilboa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Und brachte sie von dannen herauf; und sammelten sie zu Haufen mit den Gebeinen der Gehenkten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Und begruben die Gebeine Sauls und seines Sohns Jonathan im Lande Benjamin, zu Zela, im Grabe seines Vaters Kis; und taten alles, wie der Konig geboten hatte. Also ward Gott nach diesem dem Lande wieder versohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Eserhub sich aber wieder ein Krieg von den Philistern wider Israel; und David zog hinab und seine Knechte mit ihm und stritten wider die Philister. Und David ward mude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Und Jesbi zu Nob (welcher war der Kinder Raphas einer, und das Gewicht seines Speers war dreihundert Gewicht Erz und hatte neue Waffen), der gedachte David zu schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Aber Abisai, derßohn Zerujas, half ihm und schlug den Philister tot. Da schwuren ihm die Manner Davids und sprachen: Du sollst nicht mehr mit uns ausziehen in den Streit, dafi nicht die Leuchte in Israel verlosche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Danach erhub sich noch ein Krieg zu Nob mit den Philistern. Da schlug Sibechai, der Husathiter, den Saph, welcher auch der Kinder Raphas einerwar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Und es erhub sich noch ein Krieg zu Gob mit den Philistern. Da schlug Elhanan, der Sohn Jaere- Orgims, ein Bethlehemiter, den Goliath, den Gethiter, welcher hatte einen Spieli, des Stange war wie ein Weberbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Und es erhub sich noch ein Krieg zu Gath. Da war ein langer Mann, der hatte sechs Finger an seinen Handen und sechs Zehen an seinen Fufien, das ist vierundzwanzig an der Zahl; und er war auch geboren von Rapha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Und da er Israel Hohn sprach, schlug ihn Jonathan, der Sohn Simeas, des Bruders Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Diese vier waren geboren dem Rapha zu Gath und fielen durch die Hand Davids und seiner Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Und David redete vor dem HERRN die Worte dieses Liedes zur Zeit, da ihn der HERR errettet hatte von der Hand aller seiner Feinde und von der Hand Sauls, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Der HERR ist mein Fels und meine Burg und mein Erretter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Gott ist mein Hort, auf den ich traue, mein Schild und Horn meines Heils, mein Schutz und meine Zuflucht, mein Heiland, der du mir hilfst vom Frevel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Ich will den HERRN loben und anrufen, so werde ich von meinen Feinden erloset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Denn es hatten mich umfangen die Schmerzen des Todes, und die Bache Belials erschreckten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Der Hollen Bande umfingen mich, und des Todes Stricke überwaltigten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Wenn mir angst ist, so rufe ich den HERRN an und schreie zu meinem Gott, so erhoret er meine Stimme von seinem Tempel, und mein Geschrei kommt vor ihn zu seinen Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Die Erde bebete und ward bewegt, die Grundfesten des Himmels regten sich und bebeten, da erzornig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Dampf ging auf von seiner Nase und verzehrend Feuer von seinem Munde, daß es davon blitzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Er neigete den Himmel und fuhr herab, und Dunkel war unter seinen Fufien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Und er fuhr auf dem Cherub und flog daher; und er schwebete auf den Fittichen des Windes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Sein Gezelt urn ihn her war finster und schwarze dicke Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Von dem Glanz vor ihm brannte es mit Blitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Der HERR donnerte vom Himmel, und der Hochste lieft seinen Donner aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Erschoft seine Strahlen und zerstreuete sie; er lieft blitzen und schreckte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Da sah man Wassergusse, und des Erdbodens Grund ward aufgedeckt von dem Schelten des HERRN, von dem Odem und Schnauben seiner Nase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Erschickte aus von der Hohe und holte mich und zog mich aus groften Wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Ererrettete mich von meinen starken Feinden, von meinen Hassern, die mir zu machtig waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'die mich überwaltigten zur Zeit meines Unfalls. Und der HERR ward meine Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Er führete mich aus in den Raum; er rifi mich heraus, denn er hatte Lust zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Der HERR tut wohl an mir nach meiner Gerechtigkeit; er vergilt mir nach der Reinigkeit meiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Denn ich halte die Wege des HERRN und bin nicht gottlos wider meinen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Denn alle seine Rechte habe ich vor Augen und seine Gebote werfe ich nicht von mir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'sondern ich bin ohne Wandel vor ihm und hüte mich vor Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Darum vergilt mir der HERR nach meiner Gerechtigkeit, nach meiner Reinigkeit vor seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Bei den Heiligen bist du heilig, bei den Frommen bist du fromm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'bei den Reinen bist du rein und bei den Verkehrten bist du verkehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Denn du hilfst dem elenden Volk und mit deinen Augen niedrigest du die Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Denn du, HERR, bist meine Leuchte. Der HERR machet meine Finstemis licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Denn mit dir kann ich Kriegsvolk zerschmeiften und mit meinem Gott über die Mauern springen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Gottes Wege sind ohne Wandel, des HERRN Reden sind durchlautert; er ist ein Schild alien, die ihm vertrauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Denn ist ein Gott ohne den HERRN? Und wo ist ein Hort, ohne unser Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Gott starket mich mit Kraft und weiset mir einen Weg ohne Wandel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Er machet meine Fulie gleich den Hirschen und stellet mich auf meine Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Er lehret meine Hande streiten und lehret meinen Arm den ehernen Bogen spannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Und gibst mir den Schild deines Heils. Und wenn du mich demutigest, machst du mich graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Du machst unter mir Raum zu gehen, daß meine Knochel nicht gleiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Ich will meinen Feinden nachjagen und sie vertilgen; und will nicht umkehren, bis ich sie umgebracht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Ich will sie umbringen und zerschmeiften, und sollen mir nicht widerstehen; sie müssen unter meine Fufte fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Du kannst mich rüsten mit Starke zum Streit; du kannst unter mich werfen, die sich wider mich setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Du gibst mir meine Feinde in die Flucht, daß ich verstore, die mich hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Sie lieben sich zu, aber da ist kein Heifer; zum HERRN, aber er antwortet ihnen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Ich will sie zerstolien wie Staub auf der Erde; wie Kot auf der Gasse will ich sie verstauben und zerstreuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Du hilfst mir von dem zankischen Volk und behutest mich zum Haupt unter den Heiden; ein Volk, das ich nicht kannte, dienet mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Den fremden Kindern hat es wider mich gefehlet, und gehorchen mir mit gehorsamen Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Die fremden Kinder sind verschmachtet und zappeln in ihren Bander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Der HERR lebet; und gelobet sei mein Hort, und Gott, der Hort meines Heils, müsse erhaben werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'der Gott, der mir die Rache gibt und wirft die Volker unter mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Er hilft mir aus von meinen Feinden. Du erhohest mich aus denen, die sich wider mich setzen; du hilfst mir von den Frevlern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Darum will ich dir danken, HERR, unter den Heiden und deinem Namen lobsingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'der seinem Konige grofi Heil beweiset und wohltut seinem Gesalbten David und seinem Samen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Dies sind die letzten Worte Davids: Es sprach David, der Sohn Isais; es sprach der Mann, der versichert ist von dem Messias des Gottes Jakobs, lieblich mit Psalmen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Der Geist des HERRN hat durch mich geredet, und seine Rede ist durch meine Zunge geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Es hat der Gott Israels zu mir gesprochen; der Hort Israels hat geredet, der gerechte Herrscher unter den Menschen, der Herrscher in der Furcht Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Und wie das Licht des Morgens, wenn die Sonne aufgehet des Morgens ohne Wolken, da vom Glanz nach dem Regen das Gras aus der Erde wachst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Denn mein Haus ist nicht also bei Gott; denn er hat mir einen Bund gesetzt, der ewig, und alles wohl geordnet und gehalten wird. Denn all mein Heil und Tun ist, daß nichts wachst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Aber Belial sind allesamt wie die ausgeworfenen Disteln, die man nicht mit Handen fassen kann;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'sondern wer sie angreifen soil, muli Eisen und Spietistangen in der Hand haben; und werden mit Feuer verbrannt werden in der Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Dies sind die Namen der Heiden Davids: Jasabeam, der Sohn Hachmonis, der Vornehmste unter dreien; er hub seinen Spieli auf und schlug achthundertaufeinmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Nach ihm war Eleasar, der Sohn Dodos, des Sohns Ahohis, unter den dreien Heiden mit David. Da sie Hohn sprachen den Philistern und daselbst versammelt waren zum Streit, und die Manner Israels hinaufzogen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'da stund er und schlug die Philister, bis daß seine Hand mude am Schwert erstarrete. Und der HERR gab ein grofi Heil zu der Zeit, daß das Volk umwandte ihm nach, zu rauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Nach ihm war Samma, der Sohn Agas, des Harariters. Da die Philister sich versammelten in eine Rotte, und war daselbst ein Stuck Ackers voll Linsen, und das Volk floh vor den Philistern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'da trater mitten auf das Stuck und errettete es und schlug die Philister; und Gott gab ein grofi Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Und diese drei Vornehmsten unter dreilügen kamen hinab in der Ernte zu David in der Hohle Adullam, und die Rotte der Philister lag im Grunde Rephaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David aber war dazumal in der Burg; aber der Philister Volk lag zu Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Und David ward lustern und sprach: Wer will mirzu trinken holen des Wassers aus dem Brunnen zu Bethlehem unter dem Tor?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Da rissen die drei Heiden ins Lager der Philister und schopfeten des Wassers aus dem Brunnen zu Bethlehem unter dem Tor; und trugen\'s und brachten\'s David. Aber er wollte es nicht trinken, sondern goli es dem HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'und sprach: Das lasseder HERR feme von mir sein, daß ich das tue! Ist\'s nicht das Blut der Manner, die ihr Leben gewagt haben und dahingegangen sind? Und wollte es nicht trinken. Das taten die drei Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, Joabs Bruder, der Sohn Zerujas, war auch ein Vornehmster unter dreien. Er hub seinen Spieli auf und schlug dreihundert; und war auch beruhmt unter dreien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'und der Herrlichste unter dreien und war ihr Oberster; aber er kam nicht bis an die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Und Benaja, der Sohn Jojadas, des Sohns Ishails, von grolien Taten, von Kabzeel. Der schlug zween Lowen der Moabiter; und ging hinab und schlug einen Lowen im Brunnen zur Schneezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Und schlug auch einen agyptischen greulichen Mann, der hatte einen Spieli in seiner Hand. Er aber ging zu ihm hinab mit einem Stecken und rili dem Agypter den Spieli aus der Hand und erwurgete ihn mit seinem eigenen Spieli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Das tat Benaja, der Sohn Jojadas; und war beruhmt unter den dreien Heiden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'und herrlicher denn die dreilüg; aber er kam nicht bis an die drei. Und David machte ihn zum heimlichen Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, der Bruder Joabs, ist unter den dreilügen. Elhanan, der Sohn Dodos, zu Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma, der Haraditer. Elika, der Haraditer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez, der Paltiter. Ira, der Sohn Ikes, des Thekoiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser, der Anthothiter. Mebunai, der Husathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon, der Ahohiter. Maherai, der Netophathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, der Sohn Baenas, der Netophathiter. Ithai, der Sohn Ribais, von Gibea der Kinder Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja, der Pirgathoniter. Hidai, von den Bachen Gaas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon, der Arbathiter. Asmaveth, der Barhumiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljaheba, der Saalboniter. Die Kinder Jasen und Jonathan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma, der Harariter. Ahiam, der Sohn Sarars, der Harariter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet, der Sohn Ahasbais, des Sohns Maechathis. Eliam, der Sohn Ahitophels, des Giloniters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai, der Karmeliter Paerai, der Arbiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jegeal, der Sohn Nathans von Zoba. Bani, der Gaditer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek, der Ammoniter. Naharai, der Beerothiter, der Waffentrager Joabs, des Sohns Zerujas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, der Jethriter. Gareb, der Jethriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uria, der Hethiter. Derer ist allesamt siebenunddreifüg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Und der Zorn des HERRN ergrimmete abermal wider Israel und reizte David unter ihnen, daß er sprach: Gehe hin, zahle Israel und Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Und der Konig sprach zu Joab, seinem Feldhauptmann: Gehe umher in alien Stammen Israels von Dan an bis gen Berseba und zahle das Volk, dafi ich wisse, wieviel sein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab sprach zu dem Konige: Der HERR, dein Gott, tue zu diesem Volk, wie es jetzt ist, noch hundertmal so viel, daß mein Herr, der Konig, seiner Augen Lust dran sehe; aber was hat mein Herr Konig zu dieser Sache Lust?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Aber des Konigs Wort ging vor wider Joab und die Hauptleute des Heers. Also zog Joab aus und die Hauptleute des Heers von dem Konige, daß sie das Volk Israel zahleten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Und gingen liber den Jordan und lagerten sich zu Aroer zur Rechten der Stadt, die im Bach Gad liegt, und zu Jaeser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Und kamen gen Gilead und ins Niederland Hadsi; und kamen gen Dan-Jaan und urn Zidon her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Und kamen zu der festen Stadt Tyrus und alien Stadten der Heviter und Kanaaniter; und kamen hinaus an den Mittag Judas gen Berseba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Und zogen das ganze Land urn; und kamen nach neun Monden und zwanzig Tagen gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Und Joab gab dem Konige die Summa des Volks, das gezahlet war. Und es war in Israel achthundertmal tausend starker Manner, die das Schwert auszogen, und in Juda funfhundertmal tausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Und das Herz schlug David, nachdem das Volk gezahlet war. Und David sprach zum HERRN: Ich habe schwerlich gesundiget, daß ich das getan habe; und nun, HERR, nimm weg die Missetat deines Knechts; denn ich habe sehrtoricht getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Und da David des Morgens aufstund, kam des HERRN Wort zu Gad, dem Propheten, Davids Seher, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Gehe hin und rede mit David: So spricht der HERR: Dreierlei bringe ich zu dir; erwahle dir der eines, das ich dir tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad kam zu David und sagte es ihm an und sprach zu ihm: Willst du, daß sieben Jahre Teurung in dein Land komme, Oder daß du drei Monden vor deinen Widersachern fliehen mussest, und sie dich verfolgen, Oder daß drei Tage Pestilenz in deinem Lande sei? So merke nun und siehe, was ich wieder sagen soil dem, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David sprach zu Gad: Es ist mir fast angst; aber lali uns in die Hand des HERRN fallen, denn seine Barmherzigkeit ist groli; ich will nicht in der Menschen Hand fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Also lieli der HERR Pestilenz in Israel kommen von Morgen an bis zur bestimmten Zeit, daß des Volks starb von Dan an bis gen Berseba siebenzigtausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Und da der Engel seine Hand ausstreckte uber Jerusalem, daß er sie verderbete, reuete es den HERRN uber dem Ubel und sprach zum Engel, zu dem Verderber im Volk: Es ist genug, lali nun deine Hand ab! Der Engel aber des HERRN war bei der Tenne Arafnas, des Jebusiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'David aber, da er den Engel sah, der das Volk schlug, sprach erzum HERRN: Siehe, ich habe gesundiget, ich habe die Missetat getan; was haben diese Schafe getan? Lali deine Hand wider mich und meines Vaters Haus sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Und Gad kam zu David zurselben Zeit und sprach zu ihm: Gehe hinauf und richte dem HERRN einen Altar auf in der Tenne Arafnas, des Jebusiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Also ging David hinauf, wie Gad gesagt und der HERRgeboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Und da Arafna sich wandte, sah er den Konig mit seinen Knechten zu ihm gehen; und betete an auf sein Angesicht zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Und sprach: Warum kommt mein Herr, der Konig, zu seinem Knechte? David sprach: Zu kaufen von dir die Tenne und zu bauen dem HERRN einen Altar, daß die Plage vom Volk aufhore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Aber Arafna sprach zu David: Mein Herr, der Konig, nehme und opfere, wie es ihm gefallt; siehe, da ist ein Rind zum Brandopfer und Schleifen und Geschirr vom Ochsen zu Holz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Alles gab Arafna, der Konig, dem Konige. Und Arafna sprach zum Konige: Der HERR, dein Gott, lasse dich ihm angenehm sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Aber der Konig sprach zu Arafna: Nicht also, sondern ich will dir\'s abkaufen um sein Geld; denn ich will dem HERRN, meinem Gott, nicht Brandopfer tun, das ich umsonst habe. Also kaufte David die Tenne und das Rind um funfzig Sekel Silbers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Und bauete daselbst dem HERRN einen Altar und opferte Brandopfer und Dankopfer. Und der HERR ward dem Lande versohnet; und die Plage horete auf von dem Volk Israel. Das erste Buch von den Konigen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Und da der Konig David alt war und wohl betagt, konnte er nicht warm werden, ob man ihn gleich mit Kleidern bedeckte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Da sprachen seine Knechte zu ihm: Laftt sie meinem Herm Konige eine Dime, eine Jungfrau, suchen, die vordem Konige stehe und sein pflege und schlafe in seinen Armen und warme meinen Herm, den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Und sie suchten eine schone Dime in alien Grenzen Israels; und fanden Abisag von Sunem und brachten sie dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Und sie war eine sehr schone Dime; und pflegte des Konigs und dienete ihm. Aber der Konig erkannte sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Adonia aber, derßohn Hagiths, erhub sich und sprach: Ich will Konig werden! Und machte ihm Wagen und Reiter und funfzig Mann zu Trabanten vor ihm her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Und sein Vaterwollte ihn nicht bekümmem bei seiner Zeit, daß er hatte gesagt: Warum tust du also? Und erwar auch ein sehr schoner Mann, und er hatte ihn gezeuget nachst nach Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Und hatte seinen Rat mit Joab, dem Sohne Zerujas, und mit Abjathar, dem Priester; die halfen Adonia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Aber Zadok, der Priester, und Benaja, der Sohn Jojodas, und Nathan, der Prophet, und Simei und Rei und die Helden Davids waren nicht mit Adonia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Und da Adonia Schafe und Rinder und gemastet Vieh opferte bei dem Stein Soheleth, der neben dem Brunnen Rogel liegt, lud er alle seine Bruder, des Konigs Sohne, und alle Manner Judas, des Konigs Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Aber den Propheten Nathan und Benaja und die Helden und Salomo, seinen Bruder, lud er nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Da sprach Nathan zu Bathseba, Salomos Mutter: Hast du nicht gehoret, daß Adonia, der Sohn Hagiths, ist Konig worden, und unser Herr, David, weili nichts drum?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'So komm nun, ich will dir einen Ratgeben, daß du deine Seele und deines Sohns Salomo Seele errettest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Hin, und gehe zum Konige David hinein und sprich zu ihm: Hast du nicht, mein Herr Konig, deiner Magd geschworen und geredet: Dein Sohn Salomo soil nach mir Konig sein, und er soil auf meinem Stuhl sitzen? Warum ist denn Adonia Konig worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Siehe, weil du noch da bist und mit dem Kdnige redest, will ich dir nach hineinkommen und vollends dein Wort ausreden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Und Bathseba ging hinein zum Konige in die Kammer. Und der Konig war sehr alt, und Abisag von Sunem dienete dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Und Bathseba neigete sich und betete den Konig an. Der Konig aber sprach: Was ist dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Sie sprach zu ihm: Mein Herr, du hast deiner Magd geschworen bei dem HERRN, deinem Gott: Dein Sohn Saiomo soli Konig sein nach mir und auf meinem Stuhl sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Nun aber siehe, Adonia ist Konig worden; und mein Herr Konig, du weidt nichts darum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Er hat Ochsen und gemastet Vieh und viel Schafe geopfert; und hat geladen alle Sohne des Konigs, dazu Abjathar, den Priester, und Joab, den Feldhauptmann; aber deinen Knecht Saiomo hat er nicht geladen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Du bist aber mein Herr Konig; die Augen des ganzen Israel sehen auf dich, dad du ihn anzeigest, wer auf dem Stuhl meines Herrn Konigs nach ihm sitzen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Wenn aber mein Herr Konig mit seinen Vatern entschlafen ist, so werden ich und mein Sohn Saiomo müssen Sunder sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Weil sie aber noch redete mit dem Konige, kam der Prophet Nathan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Und sie sagten es dem Konige an: Siehe, da ist der Prophet Nathan. Und als er hinein vor den Konig kam, betete er an den Konig auf sein Angesicht zur Erde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'und sprach: Mein Herr Konig, hast du gesagt: Adonia soil nach mir Konig sein und auf meinem Stuhl sitzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Denn er ist heute hinabgegangen und hat geopfert Ochsen und Mastvieh und viel Schafe und hat alle Sohne des Konigs geladen und die Hauptleute, dazu den Priester Abjathar. Und siehe, sie essen und trinken vor ihm und sagen: Gluck zu dem Konige Adonia!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Aber mich, deinen Knecht, und Zadok, den Priester, und Benaja, den Sohn Jojadas, und deinen Knecht Saiomo hat er nicht geladen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Ist das von meinem Herrn Konige befohlen, und hast es deine Knechte nicht wissen lassen, wer auf dem Stuhl meines Herrn Konigs nach ihm sitzen soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Der Konig David antwortete und sprach: Rufet mir Bathseba! Und sie kam hinein vor den Konig. Und da sie vor dem Konige stund,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'schwur der Konig und sprach: So wahr der HERR lebt, der meine Seele erloset hat aus aller Not,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'ich will heute tun, wie ich dir geschworen habe bei dem HERRN, dem Gott Israels, und geredet, daß Saiomo, dein Sohn, soil nach mir Konig sein; und er soil auf meinem Stuhl sitzen fur mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Da neigte sich Bathseba mit ihrem Antlitz zur Erde und betete den Konig an und sprach: Gluck meinem Herrn Konige David ewiglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Und der Konig David sprach: Rufet mir den Priester Zadok und den Propheten Nathan und Benaja, den Sohn Jojadas! Und da sie hineinkamen vor den Konig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'sprach der Konig zu ihnen: Nehmet mit euch eures Herrn Knechte und setzet meinen Sohn Saiomo auf mein Maul und führet ihn hinab gen Gihon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Und der Priester Zadok samt dem Propheten Nathan salbe ihn daselbst zum Konige über Israel. Und blaset mit den Posaunen und sprechet: Gluck dem Konige Saiomo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Und ziehet ihm nach herauf und kommt, so soil er sitzen auf meinem Stuhl und Konig sein fur mich; und ich will ihm gebieten, daß er Fürst sei über Israel und Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Da antwortete Benaja, der Sohn Jojadas, dem Konige und sprach: Amen, es sage der HERR, der Gott meines Herrn Konigs, auch also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Wie der HERR mit meinem Herrn Konige gewesen ist, so sei er auch mit Saiomo, daß sein Stuhl grader werde denn der Stuhl meines Herrn Konigs David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Da gingen hinab der Priester Zadok und der Prophet Nathan und Benaja, der Sohn Jojodas, und Krethi und Plethi und setzten Saiomo auf das Maul des Konigs David und fuhreten ihn gen Gihon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Und der Priester Zadok nahm das Olhorn aus der Hütte und salbete Saiomo. Und sie bliesen mit der Posaune, und alles Volk sprach: Gluck dem Konige Saiomo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Und alles Volk zog ihm nach herauf, und das Volk pfiff mit Pfeifen und war sehr frohlich, daß die Erde von ihrem Geschrei erscholl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Und Adonia horete es, und alle, die er geladen hatte, die bei ihm waren; und sie hatten schon gegessen. Und da Joab der Posaunen Schall horete, sprach er: Was will das Geschrei und Getummel der Stadt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Da er aber noch redete, siehe, da kam Jonathan, der Sohn Abjathars, des Priesters. Und Adonia sprach: Komm herein, denn du bist ein redlicher Mann und bringest gute Botschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonathan antwortete und sprach zu Adonia: Ja, unser Herr, der Konig David, hat Saiomo zum Konige gemacht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'und hat mit ihm gesandt den Priester Zadok und den Propheten Nathan und Benaja, den Sohn Jojadas, und Krethi und Plethi; und sie haben ihn auf des Konigs Maul gesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Und Zadok, der Priester, samt dem Propheten Nathan hat ihn gesalbet zum Konige zu Gihon, und sind von dannen heraufgezogen mit Freuden, dad die Stadt tummelt. Das ist das Geschrei, das ihr gehoret habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Dazu sitzt Saiomo auf dem koniglichen Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Und die Knechte des Konigs sind hineingegangen, zu segnen unsern Herrn, den Konig David, und haben gesagt: Dein Gott mache Saiomo einen bessern Namen, denn dein Name ist, und mache seinen Stuhl grader denn deinen Stuhl! Und der Konig hat angebetet auf dem Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Auch hat der Konig also gesagt: Gelobet sei der HERR, der Gott Israels, der heute hat lassen einen sitzen auf meinem Stuhl, dad meine Augen gesehen haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Da erschraken und machten sich auf alle, die bei Adonia geladen waren, und gingen hin, ein jeglicher seinen Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Aber Adonia fürchtete sich vor Salomo; und machte sich auf, ging hin und fassete die Horner des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Und es ward Salomo angesagt: Siehe, Adonia furchtet den Konig Salomo; und siehe, er fasset die Horner des Altars und spricht: Der Konig Salomo schwore mir heute, daß er seinen Knecht nicht tote mit dem Schwert!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomo sprach: Wird er redlich sein, soil kein Haar von ihm auf die Erde fallen; wird aber Boses an ihm funden, so soli er sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Und der Konig Salomo sandte hin und lieli ihn herab vom Altar holen. Und da er kam, betete er den Konig Salomo an. Salomo aber sprach zu ihm: Gehe in dein Haus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Als nun die Zeit herbeikam, daß David sterben sollte, gebot er seinem Sohn Salomo und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Ich gehe hin den Weg aller Welt; so sei getrost und sei ein Mann!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Und warte auf die Hut des HERRN, deines Gottes, dafi du wandelst in seinen Wegen und haltest seine Sitten, Gebote, Rechte, Zeugnisse, wie geschrieben steht im Gesetz Moses, auf daß du klug seiest in allem, was du tust, und wo du dich hinwendest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'auf dafi der HERR sein Wort erwecke, das er uber mich geredet hat und gesagt: Werden deine Kinder ihre Wege behuten, daß sie vor mir treulich und von ganzem Herzen und von ganzer Seele wandeln, so soil von dir nimmer gebrechen ein Mann auf dem Stuhl Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Auch weifit du wohl, was mir getan hat Joab, der Sohn Zerujas, was er tat den zweien Feldhauptmannern Israels, Abner, dem Sohn Ners, und Amasa, dem Sohn Jethers, die er erwurget hat, und vergol L Kriegsblut im Frieden und tat Kriegsblut an seinen Gürtel, der urn seine Lenden war, und an seine Schuhe, die an seinen Fufien waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tue nach deiner Weisheit, dal J du seine grauen Haare nicht mit Frieden hinunter zur Holle bringest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Auch den Kindern Barsillais, des Gileaditers, sollst du Barmherzigkeit beweisen, daß sie auf deinem Tisch essen. Denn also taten sie sich zu mir, da ich vor Absalom, deinem Bruder, floh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Und siehe, du hast bei dir Simei, den Sohn Geras, des Sohns Jeminis von Bahurim, der mir schandlich fluchte zur Zeit, da ich gen Mahanaim ging. Er aber kam herab mir entgegen am Jordan. Da schwur ich ihm bei dem HERRN und sprach: Ich will dich nicht toten mit dem Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Du aber lafi ihn nicht unschuldig sein; denn du bist ein weiser Mann und wirst wohl wissen, was du ihm tun sollst, daß du seine grauen Haare mit Blut hinunter in die Hdlle bringest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Also entschlief David mit seinen Vatern und ward begraben in der Stadt Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Die Zeit aber, die David Konig gewesen ist uber Israel, ist vierzig Jahre. Sieben Jahre war er Konig zu Hebron und dreiunddreifüg Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Und Salomo sali auf dem Stuhl seines Vaters David, und sein Konigreich ward sehr bestandig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Aber Adonia, der Sohn Hagiths, kam hinein zu Bathseba, der Mutter Salomos. Und sie sprach: Kommst du auch mit Frieden? Er sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Und sprach: Ich habe mit dir zu reden. Sie sprach: Sage her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Er sprach: Du weißest, daß das Konigreich mein war, und ganz Israel hatte sich auf mich gerichtet, daß ich Konig sein sollte; aber nun ist das Konigreich gewandt und meines Bruders worden; von dem HERRN ist\'s ihm worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nun bitte ich eine Bitte von dir, du wollest mein Angesicht nicht beschamen. Sie sprach zu ihm: Sage her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Er sprach: Rede mit dem Konige Salomo (denn er wird dein Angesicht nicht beschamen), daß er mir gebe Abisag von Sunem zum Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Bathseba sprach: Wohl, ich will mit dem Konige deinethalben reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Und Bathseba kam hinein zum Konige Salomo, mit ihm zu reden Adonias halben. Und der Kdnig stund auf und ging ihr entgegen und betete sie an; und setzte sich auf seinen Stuhl. Und es ward des Konigs Mutter ein Stuhl gesetzt, daß sie sich setzte zu seiner Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Und sie sprach: Ich bitte eine kleine Bitte von dir, du wollest mein Angesicht nicht beschamen. Der Konig sprach zu ihr: Bitte, meine Mutter, ich will dein Angesicht nicht beschamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Sie sprach: Lali Abisag von Sunem deinem Bruder Adonia zum Weibe geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Da antwortete der Konig Salomo und sprach zu seiner Mutter: Warum bittest du urn Abisag von Sunem dem Adonia? Bitte ihm das Konigreich auch; denn er ist mein groliter Bruder und hat den Priester Abjathar und Joab, den Sohn Zerujas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Und der Konig Salomo schwur bei dem HERRN und sprach: Gott tue mir dies und das, Adonia soil das wider sein Leben geredet haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Und nun, so wahr der HERR lebt, der mich bestatigt hat und sitzen lassen auf dem Stuhl meines Vaters David, und der mir ein Haus gemacht hat, wie er geredet hat: heute soil Adonia sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Und der Konig Salomo sandte hin durch Benaja, den Sohn Jojadas; der schlug ihn, daß, er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Und zu dem Priester Abjathar sprach der Konig: Gehe hin gen Anathoth zu deinem Acker; denn du bist des Todes. Aber ich will dich heute nicht toten; denn du hast die Lade des Herrn HERRN vor meinem Vater David getragen und hast mitgelitten, wo mein Vater gelitten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Also verstieft Salomo den Abjathar, daß er nicht muftte Priester des HERRN sein, auf daß erfullet wurde des HERRN Wort, das er über das Haus Elis geredet hatte zu Silo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Und dies Gerucht kam vor Joab; denn Joab hatte an Adonia gehangen, wiewohl nicht an Absalom. Da floh Joab in die Hütte des HERRN und fassete die Horner des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Und es ward dem Konige Salomo angesagt, daß Joab zur Hütte des HERRN geflohen ware; und siehe, er stehet am Altar. Da sandte Salomo hin Benaja, den Sohn Jojadas, und sprach: Gehe, schlage ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Und da Benaja zur Hütte des HERRN kam, sprach er zu ihm: So sagt der Konig, gehe heraus! Er sprach: Nein, hie will ich sterben. Und Benaja sagte solches dem Konige wieder und sprach: So hat Joab geredet und so hat er mir geantwortet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Der Konig sprach zu ihm: Tue, wie er geredet hat, und schlage ihn und begrabe ihn, daß du das Blut, das Joab umsonst vergossen hat, von mir tust und von meines Vaters Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'und der HERR ihm bezahle sein Blut auf seinen Kopf, daß er zween Manner geschlagen hat, die gerechter und besserwaren denn er, und hat sie erwurget mit dem Schwert, daß mein Vater David nichts drum wuftte, namlich Abner, den Sohn Ners, den Feldhauptmann über Israel, und Amasa, den Sohn Jethers, den Feldhauptmann über Juda;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'daß ihr Blut bezahlet werde auf den Kopf Joabs und seines Samens ewiglich, aber David und sein Same, sein Haus und sein Stuhl Frieden habe ewiglich vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Und Benaja, der Sohn Jojadas, ging hinauf und schlug ihn und totete ihn. Und er ward begraben in seinem Hause in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Und der Konig setzte Benaja, den Sohn Jojadas, an seiner Statt über das Heer; und Zadok, den Priester, setzte der Konig an die Statt Abjathars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Und der Konig sandte hin und lieft Simei rufen und sprach zu ihm: Baue dir ein Haus zu Jerusalem und wohne daselbst; und gehe von dannen nicht heraus, weder hie noch daher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Welches Tages du wirst hinausgehen und über den Bach Kidron gehen, so wisse, daß du des Todes sterben muftt; dein Blut sei auf deinem Kopf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei sprach zum Konige: Das ist eine gute Meinung; wie mein Herr, der Konig, geredet hat, so soil dein Knecht tun. Also wohnete Simei zu Jerusalem lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Es begab sich aber über drei Jahre, daß zween Knechte dem Simei entliefen zu Achis, dem Sohn Maechas, dem Konige zu Gath. Und es ward Simei angesagt: Siehe, deine Knechte sind zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Da machte sich Simei auf und sattelte seinen Esel und zog hin gen Gath zu Achis, daß er seine Knechte suchte. Und da er hinkam, brachte er seine Knechte von Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Und es ward Salomo angesagt, daß Simei hingezogen ware von Jerusalem gen Gath und wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Da sandte der Konig hin und lieft Simei rufen und sprach zu ihm: Habe ich dir nicht geschworen bei dem HERRN und dir bezeuget und gesagt, welches Tages du wurdest ausziehen und hie Oder dahin gehen, daß du wissen solltest, du mufttest des Todes sterben? Und du sprachst zu mir: Ich habe eine gute Meinung gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Warum hast du denn nicht dich gehalten nach dem Eide des HERRN und Gebot, das ich dirgeboten habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Und der Konig sprach zu Simei: Du weiftt alle die Bosheit, der dir dein Herz bewuftt ist, die du meinem Vater David getan hast; der HERR hat deine Bosheit bezahlet auf deinen Kopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Und der Konig Salomo ist gesegnet, und der Stuhl Davids wird bestandig sein vor dem HERRN ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Und der Konig gebot Benaja, dem Sohn Jojadas; der ging hinaus und schlug ihn, daß er starb. Und das Konigreich ward bestatiget durch Salomos Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Und Salomo befreundete sich mit Pharao, dem Konig in Agypten; und nahm Pharaos Tochter und brachte sie in die Stadt Davids, bis er ausbauete sein Haus und des HERRN Haus und die Mauern urn Jerusalem her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Aber das Volk opferte noch auf den Hohen; denn es war noch kein Haus gebauet dem Namen des HERRN bis auf die Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomo aber hatte den HERRN lieb und wandelte nach den Sitten seines Vaters David, ohne daß er auf den Hohen opferte und raucherte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Und der Konig ging hin gen Gibeon, daselbst zu opfern; denn das war eine herrliche Hohe. Und Salomo opferte tausend Brandopfer auf demselben Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Und der HERR erschien Salomo zu Gibeon im Traum des Nachts; und Gott sprach: Bitte, was ich dir geben soil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo sprach: Du hast an meinem Vater David, deinem Knechte, grofte Barmherzigkeit getan, wie er denn vor dir gewandelt hat in Wahrheit und Gerechtigkeit und mit richtigem Herzen vor dir; und hast ihm diese grofte Barmherzigkeit gehalten und ihm einen Sohn gegeben, der auf seinem Stuhl safte, wie es denn jetzt gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Nun, HERR, mein Gott, du hast deinen Knecht zum Konige gemacht an meines Vaters Davids Statt. So bin ich ein kleiner Knabe, weift nicht weder meinen Ausgang noch Eingang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Und dein Knecht ist unter dem Volk, das du erwahlet hast, so grot?,, daß es niemand zahlen noch beschreiben kann vor der Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'So wollest du deinem Knechte geben ein gehorsam Herz, daß er dein Volk richten moge und verstehen, was gut und bose ist. Denn wer vermag dies dein machtig Volk zu richten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Das gefiel dem HERRN wohl, daß Salomo um ein solches bat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Und Gott sprach zu ihm: Weil du solches bittest und bittest nicht um langes Leben, noch um Reichtum, noch um deiner Feinde Seele, sondern um Verstand, Gericht zu horen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'siehe, so habe ich getan nach deinen Worten. Siehe, ich habe dir ein weises und verstandiges Herz gegeben, daß deinesgleichen vor dir nicht gewesen ist und nach dir nicht aufkommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Dazu, daß du nicht gebeten hast, habe ich dir auch gegeben, namlich Reichtum und Ehre, daß deinesgleichen keiner unter den Konigen ist zu deinen Zeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Und so du wirst in meinen Wegen wandeln, daß du haltst meine Sitten und Gebote, wie dein Vater David gewandelt hat, so will ich dir geben ein langes Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Und da Salomo erwachte, siehe, da wares ein Traum. Und kam gen Jerusalem und trat vor die Lade des Bundes des HERRN und opferte Brandopfer und Dankopfer; und machte ein graft Mahl alien seinen Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Zu der Zeit kamen zwo Huren zum Konige und traten vor ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Und das eine Weib sprach: Ach, mein Herr, ich und dies Weib wohneten in einem Hause; und ich gelag bei ihr im Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Und über drei Tage, da ich geboren hatte, gebar sie auch. Und wirwaren beieinander, daß kein Fremder mit uns war im Hause, ohne wir beide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Und dieses Weibes Sohn starb in der Nacht; denn sie hatte ihn im Schlaf erdruckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Und sie stund in der Nacht auf und nahm meinen Sohn von meiner Seite, da deine Magd schlief, und legte ihn an ihren Arm und ihren toten Sohn legte sie an meinen Arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Und da ich des Morgens aufstund, meinen Sohn zu saugen, siehe, da war er tot. Aber am Morgen sah ich ihn eben an, und siehe, es war nicht mein Sohn, den ich geboren hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Das andere Weib sprach: Nicht also, mein Sohn lebt und dein Sohn ist tot. Jene aber sprach: Nicht also, dein Sohn ist tot und mein Sohn lebt. Und redeten also vor dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Und der Konig sprach: Diese spricht: Mein Sohn lebet und dein Sohn ist tot; jene spricht: Nicht also, dein Sohn ist tot und mein Sohn lebt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Und der Konig sprach: Holet mir ein Schwert her! Und da das Schwert vor den Konig gebracht ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'sprach der Konig: Teilet das lebendige Kind in zwei Teile und gebet dieser die Halfte und jener die Halfte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Da sprach das Weib, des Sohn lebete, zum Konige (denn ihr mutterlich Herz entbrannte über ihren Sohn): Ach, mein Herr, gebt ihr das Kind lebendig und totet es nicht! Jene aber sprach: Es sei weder mein noch dein, laftt es teilen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Da antwortete der Konig und sprach: Gebt dieser das Kind lebendig und totet es nicht; die ist seine Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Und das Urteil erscholl vor dem ganzen Israel, das der Konig gefallet hatte, und furchteten sich vor dem Konige; denn sie sahen, daß die Weisheit Gottes in ihm war, Gericht zuhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Also war Salomo Konig uber ganz Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Und dies waren seine Fursten: Asarja, der Sohn Zadoks, des Priesters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph und Ahija, die Sohne Sisas, waren Schreiber. Josaphat, der Sohn Ahiluds, war Kanzler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja der Sohn Jojadas, war Feldhauptmann. Zadok und Abjathar waren Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Asarja, der Sohn Nathans, war über die Amtleute. Sabud, der Sohn Nathans, des Priesters, war des Konigs Freund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar war Hofmeister: Adoniram, der Sohn Abdas, war Rentmeister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Und Salomo hatte zwolf Amtleute über ganz Israel, die den Konig und sein Haus versorgten. Einer hatte des Jahrs einen Monden lang zu versorgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Und hieften also: Der Sohn Hurs auf dem Gebirge Ephraim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'der Sohn Dekers zu Makaz und zu Saalbim und zu Beth-Semes und zu Elon und Beth-Hanan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'der Sohn Heseds zu Aruboth, und hatte dazu Socho und das ganze Land Hepher;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'der Sohn Abinadabs: die ganze Herrschaft zu Dor; und hatte Taphath, Salomos Tochter, zum Weibe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baena, der Sohn Ahiluds, zu Thaenach und zu Megiddo und über ganz Beth-Sean, welches liegt neben Zarthana unter Jesreel, von Beth-Sean bis an den Plan Mehola, bisjenseit Jakmeam;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'der Sohn Gebers zu Ramoth in Gilead, und hatte die Flecken Jairs, des Sohns Manasses, in Gilead, und hatte die Gegend Argob, die in Basan liegt, sechzig grafter Stadte, vermauert und mit ehernen Riegeln;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, der Sohn Iddos, zu Mahanaim;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaaz in Naphthali; und der nahm auch Salomos Tochter, Basmath, zum Weibe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baena, der Sohn Husais, in Asser und zu Aloth;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat, der Sohn Paruahs, in Isaschar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, der Sohn Elas, in Benjamin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, der Sohn Uris, im Lande Gilead, im Lande Sihons, des Konigs der Amoriter und Ogs, des Konigs in Basan; ein Amtmann war in demselben Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda aber und Israel, des war viel, wie der Sand am Meer; und alien und tranken und waren frohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Also war Salomo ein Herr über alle Konigreiche, von dem Wasseran in der Philister Lande bis an die Grenze Agyptens, die ihm Geschenke zubrachten und dieneten ihm sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Und Salomo muftte taglich zur Speisung haben dreiftig Kor Semmelmehl und sechzig Kor ander Mehl,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'zehn gemastete Rinder und zwanzig Weiderinder und hundert Schafe, ausgenommen Hirsche und Rehe und Gemsen und gemastet Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Denn er herrschete im ganzen Lande diesseit des Wassers, von Tiphsah bis gen Gasa, uber alle Konige diesseit des Wassers, und hatte Frieden von alien seinen Untertanen umher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'daß Juda und Israel sicherwohneten, ein jeglicher unter seinem Weinstock und unter seinem Feigenbaum, von Dan bis gen Berseba, solange Salomo lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Und Salomo hatte vierzigtausend Wagenpferde und zwolftausend Reisige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Und die Amtleute versorgten den Konig Salomo und alles, was zum Tisch des Konigs gehorte, ein jeglicher in seinem Monden, und lieften nichts fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Auch Gerste und Stroh fur die Rosse und Laufer brachten sie an den Ort, da er war, ein jeglicher nach seinem Befehl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Und Gott gab Salomo sehr grolie Weisheit und Verstand und getrost Herz wie Sand, der am Ufer des Meeres liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'daß die Weisheit Salomos grafter war denn aller Kinder gegen Morgen und aller Agypter Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Und war weiser denn alle Menschen, auch weiser denn die Dichter, Ethan, der Esrahiter, Heman, Chalkol und Darda; und war berfihmt unter alien Heiden umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Und erredete dreitausend Spruche, und seiner Lieder waren tausend und fünf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Und erredete von Baumen, von der Zeder an zu Libanon bis an den Ysop, der aus der Wand wachst. Auch redete er von Vieh, von Vogeln, von Gewürm, von Fischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Und es kamen aus alien Volkern, zu horen die Weisheit Salomos, von alien Konigen auf Erden, die von seiner Weisheit gehoret hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Und Hiram, der Konig zu Tyrus, sandte seine Knechte zu Salomo; denn er hatte gehoret, daß sie ihn zum Konige gesalbet hatten an seines Vaters Statt. Denn Hiram liebte David sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Und Salomo sandte zu Hiram und lieft ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Du weiftt, daß mein Vater David nicht konnte bauen ein Haus dem Namen des HERRN, seines Gottes, urn des Kriegs willen, der urn ihn her war, bis sie der HERR unter seine Fuftsohlen gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Nun aber hat mirder HERR, mein Gott, Ruhe gegeben umher, daß kein Widersacher noch boses Hindernis mehr ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 19, 'Siehe, so habe ich gedacht, ein Haus zu bauen dem Namen des HERRN, meines Gottes, wie der HERR geredet hat zu meinem Vater David und gesagt: Dein Sohn, den ich an deine Statt setzen werde auf deinen Stuhl, der soil meinem Namen ein Haus bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 20, 'So befiehl nun, daß man mir Zedern aus Libanon haue, und daß deine Knechte mit meinen Knechten seien. Und den Lohn deiner Knechte will ich dirgeben, alles, wie du sagest. Denn du weiftt, daß bei uns niemand ist, der Holz zu hauen wisse wie die Zidonier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 21, 'Da Hiram aber horete die Worte Salomos, freuete er sich hoch und sprach: Gelobet sei der HERR heute, der David einen weisen Sohn gegeben hat uber dies grofte Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 22, 'Und Hiram sandte zu Salomo und lieft ihm sagen: Ich habe gehoret, was du zu mir gesandt hast. Ich will tun nach all deinem Begehr mit Zedern und Tannenholz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 23, 'Meine Knechte sollen sie von Libanon hinabbringen ans Meer; und will sie in Floften legen lassen auf dem Meer bis an den Ort, den du mir wirst ansagen lassen; und will sie daselbst abbinden, und du sollst es holen lassen. Aber du sollst auch mein Begehr tun und Speise geben meinem Gesinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 24, 'Also gab Hiram Salomo Zedern und Tannenholz nach all seinem Begehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 25, 'Salomo aber gab Hiram zwanzigtausend Kor Weizen zu essen fur sein Gesinde und zwanzig Kor gestoften Ol. Solches gab Salomo jahrlich dem Hiram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 26, 'Und der HERR gab Salomo Weisheit, wie er ihm geredet hatte. Und war Friede zwischen Hiram und Salomo; und sie machten beide einen Bund miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 27, 'Und Salomo legte einen Anzahl auf das ganze Israel, und der Anzahl war dreiftigtausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 28, 'Und sandte sie auf den Libanon, je einen Monden zehntausend, daß sie einen Monden auf dem Libanon waren und zween Monden daheim. Und Adoniram war uber solchen Anzahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 29, 'Und Salomo hatte siebenzigtausend, die Last trugen, und achtzigtausend, die da zimmerten auf dem Berge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 30, 'ohne die obersten Amtleute Salomos, die fiber das Werk gesetzt waren, namlich dreitausend und dreihundert, welche fiber das Volk herrscheten, das da am Werk arbeitete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 31, 'Und der Konig gebot, dafi sie grofie und kostliche Steine ausbrachen, namlich gehauene Steine zum Grund des Hauses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 32, 'Und die Bauleute Salomos und die Bauleute Hirams und die Giblim hieben aus, und bereiteten zu Holz und Steine, zu bauen das Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Im vierhundertundachtzigsten Jahr nach dem Ausgang der Kinder Israel aus Agyptenland, im vierten Jahr des Konigreichs Salomo uber Israel, im Monden Sif, das ist der andere Mond, ward das Haus dem HERRN gebauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Das Haus aber, das der Konig Salomo dem HERRN bauete, warsechzig Ellen lang und zwanzig Ellen breit und dreilüg Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Und bauete eine Halle vor dem Tempel, zwanzig Ellen lang, nach der Breite des Hauses, und zehn Ellen breit vor dem Hause her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Und er machte an das Haus Fenster, inwendig weit, auswendig enge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Und er bauete einen Umgang an der Wand des Hauses rings umher, daß er beide urn den Tempel und Chor herging; und machte seine auliere Wand umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Der unterste Gang war fünf Ellen weit und der mittelste sechs Ellen weit und der dritte sieben Ellen weit; denn er legte Tramen aulien am Hause umher, daß sie nicht an der Wand des Hauses sich hielten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Und da das Haus gesetzt ward, waren die Steine zuvor ganz zugerichtet, daß man keinen Hammer noch Beil, noch irgend ein Eisenzeug im Bauen horete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Eine Tür aber war zur rechten Seite mitten am Hause, daß man durch Wendelsteine hinaufging auf den Mittelgang und vom Mittelgang auf den dritten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Also bauete er das Haus und vollendete es; und spundete das Haus mit Zedern, beide oben und an Wanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Er bauete auch einen Gang oben auf dem ganzen Hause herum, fünf Ellen hoch, und deckte das Haus mit Zedernholz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Und es geschah des HERRN Wort zu Salomo und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Das sei das Haus, das du bauest. Wirst du in meinen Geboten wandeln und nach meinen Rechten tun und alle meine Gebote halten, drinnen zu wandeln, will ich mein Wort mit dir bestatigen, wie ich deinem Vater David geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Und will wohnen unter den Kindern Israel und will mein Volk Israel nicht verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Also bauete Salomo das Haus und vollendete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Und bauete die Wande des Hauses inwendig an den Seiten von Zedern, von des Hauses Boden an bis an die Decke; und spundete es mit Holz inwendig und tafelte den Boden des Hauses mit tannenen Brettern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Und er bauete hinten im Hause zwanzig Ellen lang eine zederne Wand vom Boden an bis an die Decke; und bauete daselbst inwendig den Chor und das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Aber das Haus des Tempels (vor dem Chor) war vierzig Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Inwendig war das ganze Haus eitel Zedern, mit gedrehten Knoten und Blumenwerk, das man keinen Stein sah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Aber den Chor bereitete er inwendig im Hause, daß man die Lade des Bundes des HERRN daselbst hin fate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Und vor dem Chor, der zwanzig Ellen lang, zwanzig Ellen weit und zwanzig Ellen hoch war und überzogen mit lauterm Golde, spundete er den Altar mit Zedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Und Salomo überzog das Haus inwendig mit lauterm Golde und zog guldene Riegel vor dem Chor her, den er mit Golde überzogen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'also daß das ganze Haus gar mit Golde überzogen war; dazu auch den ganzen Altar vor dem Chor uberzog er mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Er machte auch im Chor zween Cherubim, zehn Ellen hoch, von Olbaumholz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Fünf Ellen hatte ein Flügel eines jeglichen Cherubs, daß zehn Ellen waren von dem Ende seines einen Flügels zum Ende seines andern Flügels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Also hatte der andere Cherub auch zehn Ellen, und war einerlei Mali und einerlei Raum beider Cherubim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'daß also ein jeglicher Cherub zehn Ellen hoch war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Und er tat die Cherubim inwendig ins Haus. Und die Cherubim breiteten ihre Flügel aus, daß eines Flügel rührete an diese Wand und des andern Cherub Flügel rührete an die andere Wand; aber mitten im Hause rührete ein Flügel den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Und er überzog die Cherubim mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Und an alien Wanden des Hauses urn und urn lieli er Schnitzwerk machen von ausgehohlten Cherubim, Palmen und Blumenwerk, inwendig und auswendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Auch überzog er den Boden des Hauses mit güldenen Blechen, inwendig und auswendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Und im Eingange des Chors machte er zwo Türen von Olbaumholz mit funfeckigen Pfosten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Und lieli Schnitzwerk darauf machen von Cherubim, Palmen und Blumenwerk; und überzog sie mit güldenen Blechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Also machte er auch im Eingang des Tempels viereckige Pfosten von Olbaumholz');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'und zwo Türen von Tannenholz, daß eine jegliche Tür zwei Blatt hatte aneinander hangen in ihren Angeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Und machte Schnitzwerk drauf von Cherubim, Palmen und Blumenwerk; und uberzog sie mit Golde, rechtwie es befohlen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Und er bauete auch einen Hof drinnen von dreien Riegen gehauener Steine und von einer Riege gehofelter Zedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Im vierten Jahr, im Monden Sif, ward der Grund gelegt am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Und im elften Jahr, im Monden Bui (das ist der achte Mond), ward das Haus bereitet, wie es sein sollte, daß sie sieben Jahre dran baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Aber an seinem Hause bauete Salomo dreizehn Jahre, dafi er\'s ganz ausbauete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Namlich er bauete ein Haus vom Wald Libanon, hundert Ellen lang, funfzig Ellen weit und dreiftig Ellen hoch. Auf dasselbige Gevierte legte er den Boden von zedernen Brettern, auf zedernen Saulen, nach den Riegen hin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'und oben drauf ein Gezimmer von Zedern auf dieselben Saulen, welcher waren funfundvierzig, je funfzehn in einer Riege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Und waren Fenstergegen die drei Riegen gegeneinander uber, drei gegen drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Und waren in ihren Pfosten viereckig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Er bauete auch eine Halle von Saulen, funfzig Ellen lang und dreiftig Ellen breit; und noch eine Halle vor diese, mit Saulen und dicken Balken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Und bauete auch eine Halle zum Richtstuhl, darin man Gericht hielt; und tafelte beide Boden mit Zedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Dazu sein Haus, darinnen erwohnete, im Hinterhof, hinten an der Halle, gemacht wie die andern; und machte auch ein Haus, wie die Halle, der Tochter Pharaos, die Salomo zum Weibe genommen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Solches alles waren kostliche Steine, nach dem Winkeleisen gehauen, mit Sagen geschnitten von alien Seiten, vom Grund bis an das Dach, dazu auch auften der grofte Hof.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Die Grundfeste aber waren auch kostliche und grofte Steine, zehn und acht Ellen graft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'und darauf kostliche gehauene Steine nach dem Winkeleisen und Zedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Aber der grofte Hof umher hatte drei Riegen gehauene Steine und eine Riege von zedernen Brettern; also auch der Hof am Hause des HERRN inwendig und die Halle am Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Und der Konig Salomo sandte hin und lieft holen Hiram von Tyrus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'einer Witwe Sohn aus dem Stamm Naphthali, und sein Vater war ein Mann von Tyrus gewesen; der war ein Meister im Erz, voll Weisheit, Verstand und Kunst, zu arbeiten allerlei Erzwerk. Da der zum Konige Salomo kam, machte er alle seine Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Und machte zwo eherne Saulen, eine jegliche achtzehn Ellen hoch; und ein Faden von zwolf Ellen war das Maft urn jegliche Saule her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Und machte zween Knaufe von Erz gegossen, oben auf die Saulen zu setzen, und ein jeglicher Knauf war funf Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Und es waren an jeglichem Knauf oben auf der Saule sieben geflochtene Reife, wie Ketten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Und machte an jeglichem Knauf zwo Riegen Granatapfel umher an einem Reife, damit der Knauf bedecktward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Und die Knaufe waren wie die Rosen vor der Halle, vier Ellen graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Und der Granatapfel in den Riegen umher waren zweihundert, oben und unten an dem Reife, der um den Bauch des Knaufs herging, an jeglichem Knauf auf beiden Saulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Und er richtete die Saulen auf vor der Halle des Tempels. Und die er zur rechten Hand setzte, hieft er Jachin; und die er zur linken Hand setzte, hieft er Boas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Und es stund also oben auf den Saulen wie Rosen. Also ward vollendet das Werk der Saulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Und er machte ein Meer, gegossen, zehn Ellen weit, von einem Rand zum andern, rund umher, und funf Ellen hoch, und eine Schnur dreiftig Ellen lang war das Maft ringsum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Und um dasselbe Meer, das zehn Ellen weit war, gingen Knoten an seinem Rande rings urns Meer her; der Knoten aber waren zwo Riegen gegossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Und es stund auf zwolf Rindern, welcher drei gegen Mitternacht gewandt waren, drei gegen Abend, drei gegen Mittag und drei gegen Morgen, und das Meer oben drauf, daß alle ihr Hinterteil inwendig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Seine Dicke aber war eine Hand breit, und sein Rand war wie eines Bechers Rand, wie eine aufgegangene Rose; und ging drein zweitausend Bath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Er machte auch zehn eherne Gestuhle, ein jegliches vier Ellen lang und breit und drei Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Es war aber das Gestuhle also gemacht, daß es Seiten hatte zwischen den Leisten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Und an den Seiten zwischen den Leisten waren Lowen, Ochsen und Cherubim. Und die Seiten, daran die Lowen und Ochsen waren, hatten Leisten oben und unten und Fuftlein dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Und ein jeglich Gestuhle hatte vier eherne Rader mit ehernem Gestell. Und auf den vier Ecken waren Achseln gegossen, eine jegliche gegen der andern uber, unten an den Kessel gelehnt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Aber der Hals mitten auf dem Gestuhle war eine Elle hoch und rund anderthalb Ellen weit; und waren Buckeln an dem Hals in Feldern, die viereckig waren und nicht rund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Die vier Rader aber stunden unten an den Seiten, und die Achsen der Rader waren am Gestuhle. Ein jeglich Rad war anderthalb Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Und waren Rader wie Wagenrader, und ihre Achsen, Naben, Speichen und Felgen war alles gegossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Und die vier Achseln auf den vier Ecken eines jeglichen Gestühls waren auch am Gestuhle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Und am Hals oben auf dem Gestuhle, einer halben Elle hoch, rund umher, waren Leisten und Seiten am Gestühle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Und er lieli auf die Flache derselben Seiten und Leisten graben Cherubim, Lowen und Palmenbaume; ein jegliches am andern, rings umher dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Auf die Weise machte er zehn Gestühle, gegossen; einerlei Mali und Raum war an alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Und er machte zehn eherne Kessel, daß vierzig Bath in einen Kessel gingen; und war vier Ellen groli, und auf jeglichem Gestühle war ein Kessel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Und setzte fünf Gestühle an die rechte Ecke des Hauses und die andern funf an die linke Ecke; aber das Meer setzte er zur Rechten vorn an gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Und Hiram machte auch Topfe, Schaufeln, Becken; und vollendete also alle Werke, die der Konig Salomo am Hause des HERRN machen lieli,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'namlich: die zwo Saulen und die keulichen Knaufe oben auf den zwo Saulen und die zween geflochtenen Reife, zu bedecken die zween keulichen Knaufe auf den Saulen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'und die vierhundert Granatapfel an den zween geflochtenen Reifen, je zwo Riegen Granatapfel an einem Reife, zu bedecken die zween keulichen Knaufe auf den Saulen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'dazu die zehn Gestühle und zehn Kessel oben drauf;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'und das Meer und zwolf Rinder unter dem Meer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'und die Topfe, Schaufeln und Becken. Und alle diese Gefalie, die Hiram dem Konige Salomo machte zum Hause des HERRN, waren von lauterm Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'In der Gegend am Jordan lieli sie der Konig gielien, in dicker Erde, zwischen Suchoth und Zarthan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Und Salomo lieli alle Gefalie ungewogen vor der sehr grolien Menge des Erzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Auch machte Salomo alien Gezeug, der zum Hause des HERRN gehoret, namlich: einen güldenen Altar, einen güldenen Tisch, darauf die Schaubrote liegen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'fünf Leuchter zur rechten Hand und fünf Leuchter zur linken vor dem Chor von lauterm Golde mit güldenen Blumen, Lampen und Schneuzen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'dazu Schalen, Schüsseln, Becken, Loffel und Pfannen von lauterm Golde. Auch waren die Angeln an der Tür am Hause inwendig im Allerheiligsten und an der Tür des Hauses des Tempels gulden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Also ward vollendet alles Werk, das der Konig Salomo machte am Hause des HERRN. Und Salomo brachte hinein was sein Vater David geheiliget hatte, von Silber und Gold und Gefalien, und legte es in den Schatz des Hauses des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Da versammelte der Konig Salomo zu sich die Altesten in Israel, alle Obersten der Stamme und Fürsten der Vater unter den Kindern Israel, gen Jerusalem, die Lade des Bundes des HERRN heraufzubringen aus der Stadt Davids, das ist Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Und es versammelten sich zum Konige Salomo alle Manner in Israel im Monden Ethanim, am Fest, das ist der siebente Mond.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Und da alle Altesten Israels kamen, huben die Priester die Lade des HERRN auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Und brachten sie hinauf, dazu die Hütte des Stiffs und alles Gerat des Heiligtums, das in der Hütte war. Das taten die Priester und Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Und der Konig Salomo und die ganze Gemeine Israels, die zu ihm sich versammelt hatte, gingen mit ihm vor der Lade her und opferten Schafe und Rinder, so viel, dal$ man\'s nicht zahlen noch rechnen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Also brachten die Priester die Lade des Bundes des HERRN an ihren Ort, in den Chor des Hauses, in das Allerheiligste, unter die Flügel der Cherubim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Denn die Cherubim breiteten die Flügel aus an dem Ort, da die Lade stund, und bedeckten die Lade und ihre Stangen von oben her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Und die Stangen waren so lang, daß ihre Knaufe gesehen wurden in dem Heiligtum vor dem Chor, aber aulien wurden sie nicht gesehen; und waren daselbst bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Und war nichts in der Lade denn nur die zwo steinernen Tafeln Moses, die er daselbst lieli in Horeb, da der HERR mit den Kindern Israel einen Bund machte, da sie aus Agyptenland gezogen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Da aber die Priester aus dem Heiligtum gingen, erfüllete eine Wolke das Haus des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'daß die Priester nicht konnten stehen und Amts pflegen vor der Wolke. Denn die Herrlichkeit des HERRN erfullete das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Da sprach Salomo: Der HERR hat geredet, er wolle im Dunkel wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Ich habe zwarein Haus gebauet, dir zur Wohnung, einen Sitz, daß du ewiglich da wohnest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Und der Konig wandte sein Angesicht und segnete die ganze Gemeine Israels; und die ganze Gemeine Israels stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Und er sprach: Gelobetsei der HERR, derßott Israels, der durch seinen Mund meinem Vater David geredet und durch seine Hand erfullet hat und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Von dem Tage an, da ich mein Volk Israel aus Agypten fuhrete, habe ich nie keine Stadt erwahlet unter irgend einem Stamm Israels, daß mir ein Haus gebauet würde, daß mein Name da ware; David aber habe ich erwahlet, daß er uber mein Volk Israel sein sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Und mein Vater David hatte es zwar im Sinn, daß er ein Haus bauete dem Namen des HERRN, des Gottes Israels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'aber der HERR sprach zu meinem Vater David: Dali du im Sinn hast, meinem Namen ein Haus zu bauen, hast du wohl getan, daß du solches vornahmest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'doch du sollst nicht das Haus bauen, sondern dein Sohn, der aus deinen Lenden kommen wird, der soil meinem Namen ein Haus bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Und der HERR hat sein Wort bestatiget, das er geredet hat. Denn ich bin aufkommen an meines Vaters Davids Statt und sitze auf dem Stuhl Israels, wie der HERR geredet hat; und habe gebauet ein Haus dem Namen des HERRN, des Gottes Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Und habe daselbst eine Statte zugerichtet der Lade, darin der Bund des HERRN ist, den ergemacht hat mit unsern Vatern, da er sie aus Agyptenland fuhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Und Salomo trat vor den Altar des HERRN gegen der ganzen Gemeine Israels und breitete seine Hande aus gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Und sprach: HERR, Gott Israels, es ist kein Gott, weder droben im Himmel noch unten auf Erden, dir gleich, derdu haltst den Bund und Barmherzigkeit deinen Knechten, die vor dir wandeln von ganzem Herzen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'der du hast gehalten deinem Knechte, meinem Vater David, was du ihm geredet hast. Mit deinem Munde hast du es geredet und mit deiner Hand hast du es erfullet, wie es stehet an diesem Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Nun, HERR, Gott Israels, halte deinem Knechte, meinem Vater David, was du ihm geredet hast und gesagt: Es soil dir nicht gebrechen an einem Manne vor mir der da sitze auf dem Stuhl Israels, so doch, daß deine Kinder ihren Weg bewahren, daß sie vor mir wandeln, wie du vor mir gewandelt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nun, Gott Israels, lali deine Worte wahrwerden, die du deinem Knechte, meinem Vater David, geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Denn meinest du auch, daß Gott auf Erden wohne? Siehe, der Himmel und aller Himmel Himmel mogen dich nicht versorgen. Wie sollte es denn dies Haus tun, das ich gebauet habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Wende dich aber zum Gebet deines Knechts und zu seinem Flehen, HERR, mein Gott, auf daß du horest das Lob und Gebet, das dein Knecht heute vor dir tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'daß deine Augen often stehen uber dies Haus Nacht und Tag, uber die Statte, davon du gesagt hast: Mein Name soil da sein. Du wollest horen das Gebet, das dein Knecht an dieser Statte tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'und wollest erhoren das Flehen deines Knechts und deines Volks Israel, das sie hie tun werden an dieser Statte deiner Wohnung, im Himmel, und wenn du es horest, gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Wenn jemand wider seinen Nachsten sundiget und nimmt des einen Eid auf sich, damit er sich verpflichtet, und der Eid kommt vor deinen Altar in diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'so wollest du horen im Himmel und Recht schaffen deinen Knechten, den Gottlosen zu verdammen und seinen Weg auf seinen Kopf bringen und den Gerechten recht zu sprechen, ihm zu geben nach seiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Wenn dein Volk Israel vor seinen Feinden geschlagen wird, weil sie an dir gesundiget haben, und bekehren sich zu dir, und bekennen deinen Namen und beten und flehen zu dir, in diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'so wollest du horen im Himmel und der Sunde deines Volks Israel gnadig sein und sie wiederbringen ins Land, das du ihren Vatern gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Wenn der Himmel verschlossen wird, daß nicht regnet, weil sie an dir gesundiget haben, und werden beten an diesem Ort und deinen Namen bekennen und sich von ihren Sunden bekehren, weil du sie drangest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'so wollest du horen im Himmel und gnadig sein der Sunde deiner Knechte und deines Volks Israel, daß du ihnen den guten Weg weisest, darinnen sie wandeln, und lassest regnen auf das Land, das du deinem Volk zum Erbe gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Wenn eine Teurung, Oder Pestilenz, Oder Durre, Oder Brand, Oder Heuschrecken, Oder Raupen im Lande sein werden, Oder sein Feind im Lande seine Tore belagert, Oder irgend eine Plage Oder Krankheit:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'wer dann bittet und flehet, es seien sonst Menschen Oder dein Volk Israel, die da gewahr werden ihrer Plage, ein jeglicher in seinem Herzen, und breitet seine Hande aus zu diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'so wollest du horen im Himmel, in dem Sitz, da du wohnest, und gnadig sein und schaffen, daß du gebest einem jeglichen, wie er gewandelt hat, wie du sein Herz erkennest; denn du allein kennest das Herz aller Kinder der Menschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'auf daß sie dich furchten allezeit, solange sie auf dem Lande leben, das du unsern Vatern gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Wenn auch ein Fremder, der nicht deines Volks Israel ist, kommt aus fernem Lande urn deines Namens willen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(denn sie werden horen von deinem grolien Namen und von deiner machtigen Hand und von deinem ausgereckten Arm), und kommt, daß er bete vor diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'so wollest du horen im Himmel, im Sitz deiner Wohnung, und tun alles, darum der Fremde dich anruft, auf daß alle Volker auf Erden deinen Namen erkennen, daß sie auch dich furchten, wie dein Volk Israel, und daß sie inne werden, wie dies Haus nach deinem Namen genannt sei, das ich gebauet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Wenn dein Volk auszeucht in Streit wider seine Feinde des Weges, den du sie senden wirst, und werden beten zum HERRN gegen den Weg zur Stadt, die du erwahlet hast, und zum Hause, das ich deinem Namen gebauet habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'so wollest du ihr Gebet und Flehen horen im Himmel und Recht schaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Wenn sie an dir sundigen werden (denn es ist kein Mensch, der nicht sundiget), und du erzurnest und gibst sie vor ihren Feinden, daß sie sie gefangen führen in der Feinde Land, fern Oder nahe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'und sie in ihr Herz schlagen im Lande, da sie gefangen sind, und bekehren sich und flehen dir im Lande ihres Gefangnisses und sprechen: Wir haben gesundiget und missetan und sind gottlos gewesen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'und bekehren sich also zu dir von ganzem Herzen und von ganzer Seele in ihrer Feinde Lande, die sie weggefuhret haben, und beten zu dir gegen den Weg zu ihrem Lande, das du ihren Vatern gegeben hast, zur Stadt, die du erwahlet hast, und zum Hause, das ich deinem Namen gebauet habe:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'so wollest du ihr Gebet und Flehen horen im Himmel, vom Sitz deiner Wohnung, und Recht schaffen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'und deinem Volk gnadig sein, das an dir gesundiget hat, und alien ihren Ubertretungen, damit sie wider dich ubertreten haben, und Barmherzigkeit geben vordenen, die sie gefangen halten, und dich ihrer erbarmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Denn sie sind dein Volk und dein Erbe, die du aus Agypten, aus dem eisernen Ofen, gefuhret hast;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'daß deine Augen often seien auf das Flehen deines Knechts und deines Volks Israel, daü du sie horest in allem, darum sie dich anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Denn du hast sie dir abgesondert zum Erbe aus alien Volkern auf Erden, wie du geredet hast durch Mose, deinen Knecht, da du unsere Vater aus Agypten fuhretest, Herr, HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Und da Salomo all dies Gebet und Flehen hatte vor dem HERRN ausgebetet, stund er auf von dem Altar des HERRN und lieft ab von Knieen und Handeausbreiten gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Und trat dahin und segnete die ganze Gemeine Israels mit lauter Stimme und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Gelobet sei der HERR, der seinem Volk Israel Ruhe gegeben hat, wie er geredet hat! Es ist nicht eins verfallen aus alien seinen guten Worten, die er geredet hat durch seinen Knecht Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Der HERR, unser Gott, sei mit uns, wie er gewesen ist mit unsern Vatern! Er verlasse uns nicht und ziehe die Hand nicht ab von uns,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'zu neigen unser Herz zu ihm, daß wir wandeln in alien seinen Wegen und halten seine Gebote, Sitten und Rechte, die er unsern Vatern geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Und diese Worte, die ich vor dem HERRN geflehet habe, müssen nahe kommen dem HERRN, unserm Gott, Tag und Nacht, da(3> er Recht schaffe seinem Knecht und seinem Volk Israel, ein jegliches zu seiner Zeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'auf dafi alle Volker auf Erden erkennen, daß der HERR Gott ist, und keiner mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Und euer Herz sei rechtschaffen mit dem HERRN, unserm Gott, zu wandeln in seinen Sitten und zu halten seine Gebote, wie es heute gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Und der Konig samt dem ganzen Israel opferten vor dem HERRN Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Und Salomo opferte Dankopfer, die er dem HERRN opferte, zweiundzwanzigtausend Ochsen und hundertundzwanzigtausend Schafe. Also weiheten sie das Haus des HERRN ein, der Konig und alle Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Desselbigen Tages weihete der Konig den Mittelhof, der vor dem Hause des HERRN war, damit, daß er Brandopfer, Speisopfer und das Fett der Dankopfer daselbst ausrichtete. Denn der eherne Altar, der vor dem HERRN stund, war zu klein zu dem Brandopfer; Speisopfer und zum Fetten der Dankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Und Salomo machte zu der Zeit ein Fest, und alles Israel mit ihm, eine grofte Versammlung, von der Grenze Hemaths an bis an den Bach Agyptens, vor dem HERRN, unserm Gott, sieben Tage und aber sieben Tage; das waren vierzehn Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Und lieft das Volk des achten Tages gehen. Und sie segneten den Konig und gingen hin zu ihren Hütten frohlich und guten Muts uber all dem Guten, das der HERR an David, seinem Knecht, und an seinem Volk Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Und da Salomo hatte ausgebauet des HERRN Haus und des Konigs Haus und alles, was er begehrete und Lust hatte zu machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'erschien ihm der HERR zum andernmal, wie er ihm erschienen war zu Gibeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Und der HERR sprach zu ihm: Ich habe dein Gebet und Flehen gehoret, das du vor mir geflehet hast, und habe dies Haus geheiliget, das du gebauet hast, daß ich meinen Namen daselbst hinsetze ewiglich, und meine Augen und mein Herz sollen da sein allewege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Und du, so du vor mir wandelst, wie dein Vater David gewandelt hat, mit rechtschaffenem Herzen und aufrichtig, daß du tust alles, was ich dir geboten habe, und meine Gebote und meine Rechte haltst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'so will ich bestatigen den Stuhl deines Konigreichs uber Israel ewiglich, wie ich deinem Vater David geredet habe und gesagt: Es soil dir nicht gebrechen an einem Manne vom Stuhl Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Werdet ihr euch aber von mir hinten abwenden, ihr und eure Kinder, und nicht halten meine Gebote und Rechte, die ich euch vorgelegt habe, und hingehet und andern Gottern dienet, und sie anbetet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'so werde ich Israel ausrotten von dem Lande, das ich ihnen gegeben habe; und das Haus, das ich geheiliget habe meinem Namen, will ich verlassen von meinem Angesicht; und Israel wird ein Sprichwort und Fabel sein unter alien Volkern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'und das Haus wird eingerissen werden, daß alle, die vorubergehen, werden sich entsetzen und blasen und sagen: Warum hat der HERR diesem Lande und diesem Hause also getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'So wird man antworten: Darum, daß sie den HERRN, ihren Gott, verlassen haben, der ihre Vater aus Agyptenland fuhrete, und haben angenommen andere Gotter und sie angebetet und ihnen gedienet; darum hat der HERR all dies Obel uber sie gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Da nun die zwanzig Jahre urn waren, in welchen Salomo die zwei Hauser bauete, des HERRN Haus und des Konigs Haus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'dazu Hiram, der Konig zu Tyrus, Salomo Zedernbaume und Tannenbaume und Gold nach all seinem Begehr brachte, da gab der Konig Salomo Hiram zwanzig Stadte im Lande Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Und Hiram zog aus von Tyrus, die Stadte zu besehen, die ihm Salomo gegeben hatte, und sie gefielen ihm nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Und sprach: Was sind das fur Stadte, mein Bruder, die du mir gegeben hast? Und hiefi sie das Land Kabul bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Und Hiram hatte dem Konige gesandt hundertundzwanzig Zentner Goldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Und dasselbe ist die Summa der Zinse, die der Konig Salomo aufhub, zu bauen des HERRN Haus und sein Haus und Millo und die Mauern Jerusalems und Hazor und Megiddo und Gaser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Denn Pharao, der Konig in Agypten, war heraufkommen und hatte Gaser gewonnen und mit Feuer verbrannt und die Kanaaniter erwurget, die in dem Stadt wohneten, und hatte sie seiner Tochter, Salomos Weibe, zum Geschenk gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Also bauete Salomo Gaser und das niedere Beth-Horon');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'und Baelath und Thamar in der Wüste im Lande');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'und alle Stadte der Kornhauser, die Salomo hatte, und alle Stadte der Wagen und die Stadte der Reiter, und wozu er Lust hatte zu bauen, zu Jerusalem, im Libanon und im ganzen Lande seiner Herrschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Und alles übrige Volk von den Amoritern, Hethitern, Pheresitern, Hevitern und Jebusitern, die nicht von den Kindern Israel waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'derselben Kinder, die sie hinter sich uberbleiben Men im Lande, die die Kinder Israel nicht konnten verbannen, die machte Salomo zinsbar bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Aber von den Kindern Israel machte er nicht Knechte, sondern IM sie Kriegsleute und seine Knechte und Fursten und Ritter und uber seine Wagen und Reiter sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Und der Amtleute, die uber Salomos Geschafte waren, der waren funfhundertundfunfzig, die uber das Volk herrscheten und die Geschafte ausrichteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Und die Tochter Pharaos zog herauf von der Stadt Davids in ihr Haus, das er fur sie gebauet hatte. Da bauete er auch Millo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Und Salomo opferte des Jahrs dreimal Brandopfer und Dankopfer auf dem Altar, den er dem HERRN gebauet hatte, und raucherte uber ihm vor dem HERRN. Und ward also das Haus fertig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Und Salomo machte auch Schiffe zu Ezeon- Geber, die bei Eloth liegt, am Ufer des Schilfmeers, im Lande der Edomiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Und Hiram sandte seine Knechte im Schiff, die gute Schiffsleute und auf dem Meer erfahren waren, mit den Knechten Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Und kamen gen Ophir und holeten daselbst vierhundertundzwanzig Zentner Goldes und brachten es dem Konige Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Und da das Gerucht Salomos von dem Namen des HERRN kam vor die Konigin von Reicharabien, kam sie, ihn zu versuchen mit Ratseln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Und sie kam gen Jerusalem mit einem sehr großen Zeug, mit Kamelen, die Spezerei trugen und viel Goldes und Edelgesteine. Und da sie zum Konige Salomo hineinkam, redete sie mit ihm alles, was sie vorgenommen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Und Salomo sagte ihr alles, und war dem Konige nichts verborgen, das er ihr nicht sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Da aber die Konigin von Reicharabien sah alle Weisheit Salomos und das Haus, das er gebauet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'und die Speise fur seinen Tisch und seiner Knechte Wohnung und seiner Diener Amt und ihre Kleider und seine Schenken und seine Brandopfer, die er in dem Hause des HERRN opferte, konnte sie sich nicht mehr enthalten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'und sprach zum Konige: Es istwahr, was ich in meinem Lande gehoret habe von deinem Wesen und von deiner Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Und ich habe es nicht wollen glauben, bis ich kommen bin und habe es mit meinen Augen gesehen. Und siehe, es ist mir nicht die Halfte gesagt. Du hast mehr Weisheit und Gutes denn das Gerucht, das ich gehoret habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Selig sind deine Leute und deine Knechte, die allezeit vor dir stehen und deine Weisheit horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Gelobet sei der HERR, dein Gott, der zu dir Lust hat, daß er dich auf den Stuhl Israels gesetzet hat, darum dafi der HERR Israel liebhat ewiglich und dich zum Konige gesetzet hat, daß du Gericht und Recht haitest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Und sie gab dem Konige hundertundzwanzig Zentner Goldes und sehr viel Spezerei und Edelgesteine. Es kam nicht mehr so viel Spezerei, als die Konigin von Reicharabien dem Konige Salomo gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Dazu die Schiffe Hirams, die Gold aus Ophir führeten, brachten sehr viel Ebenholz und Edelgesteine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Und der Konig IM machen von Ebenholz Pfeiler im Hause des HERRN und im Hause des Konigs und Harfen und Psalter fur die Sanger. Es kam nicht mehr solch Ebenholz, ward auch nicht gesehen bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Und der Konig Salomo gab der Konigin von Reicharabien alles, was sie begehrete und bat, ohne was er ihr gab von ihm selbst. Und sie wandte sich und zog in ihr Land samt ihren Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Des Goldes aber, das Salomo in einem Jahr kam, war am Gewicht sechshundertundsechsundsechzig Zentner,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'ohne was von Kramern und Kaufleuten und Apothekern und von alien Konigen Arabiens und von den Gewaltigen in Landern kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Und der Konig Salomo lieft machen zweihundert Schilde vom besten Golde; sechshundert Stuck Goldes tat er zu einem Schilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'und dreihundert Tartschen vom besten Golde, je drei Pfund Goldes zu einer Tartsche. Und der Konig tat sie in das Haus vom Walde Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Und der Konig machte einen groften Stuhl von Elfenbein und uberzog ihn mitdem edelsten Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Und der Stuhl hatte sechs Stufen, und das Haupt am Stuhl war hinten rund. Und waren Lehnen auf beiden Seiten urn das Gesaft, und zween Lowen stunden an den Lehnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Und zwolf Lowen stunden auf den sechs Stufen auf beiden Seiten. Solches ist nie gemacht in keinen Konigreichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Alle Trinkgefafte des Konigs Salomo waren gulden, und alle Gefafte im Hause vom Walde Libanon waren auch lauter Gold; denn des Silbers achtete man zu den Zeiten Salomos nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Denn das Meerschiff des Konigs, das auf dem Meer mit dem Schiff Hirams fuhr, kam in dreien Jahren einmal und brachte Gold, Silber, Elfenbein, Affen und Pfauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Also ward der Konig Salomo grbfter mit Reichtum und Weisheit denn alle Konige auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Und alle Welt begehrete, Salomo zu sehen, daß sie die Weisheit horeten, die ihm Gott in sein Herz gegeben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Und jedermann brachte ihm Geschenke, silberne und guldene Gerate, Kleider und Harnische, Wurze, Rosse, Mauler jahrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Und Salomo brachte zuhauf Wagen und Reiter, daß er hatte tausend und vierhundert Wagen und zwolftausend Reiter, und lieft sie in den Wagenstadten und bei dem Konige zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Und der Konig machte, daß des Silbers zu Jerusalem so viel warwie die Steine, und Zedernholz so viel wie die wilden Feigenbaume in den Grunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Und man brachte dem Salomo Pferde aus Agypten und allerlei Ware, und die Kaufleute des Konigs kauften dieselbige Ware');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'und brachten\'s aus Agypten heraus, je einen Wagen urn sechshundert Silberlinge, und ein Pferd urn hundertundfunfzig. Also brachte man sie auch alien Konigen der Hethiter und den Konigen zu Syrien durch ihre Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Aber der Konig Salomo liebte viel auslandischer Weiber: die Tochter Pharaos und moabitische, ammonitische, edomitische, zidonitische und hethitische,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'von solchen Vblkern, davon der HERR gesagt hatte den Kindern Israel: Gehet nicht zu ihnen und lasset sie nicht zu euch kommen; sie werden gewift eure Herzen neigen ihren Gottern nach. An diesen hing Salomo mit Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Und er hatte siebenhundert Weiber zu Frauen und dreihundert Kebsweiber; und seine Weiber neigeten sein Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Und da er nun alt war, neigeten seine Weiber sein Herz fremden Gottern nach, daß sein Herz nicht ganzwar mitdem HERRN, seinem Gott, wie das Herz seines Vaters David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Also wandelte Salomo Asthoreth, dem Gott derer von Zidon nach, und Milkom, dem Greuel der Ammoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Und Salomo tat, das dem HERRN ubel gefiel, und folgte nicht ganzlich dem HERRN wie sein Vater David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Da bauete Salomo eine Hohe Kamos, dem Greuel der Moabiter, auf dem Berge, der vor Jerusalem liegt, und Molech, dem Greuel der Ammoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Also tat Salomo alien seinen auslandischen Weibern, die ihren Gottern raucherten und opferten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Der HERR aber ward zornig über Salomo, daß sein Herz von dem HERRN, dem Gott Israels, geneiget war, der ihm zweimal erschienen war');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'und ihm solches geboten hatte, daß er nicht andern Gottern nachwandelte, und doch er nicht gehalten hatte, was ihm der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Darum sprach der HERR zu Salomo: Weil solches bei dir geschehen ist und hast meinen Bund und meine Gebote nicht gehalten, die ich dir geboten habe, so will ich auch das Konigreich von dir reiften und deinem Knechte geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Doch bei deiner Zeit will ich\'s nicht tun urn deines Vaters David willen, sondern von der Hand deines Sohnes will ich\'s reiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Doch will ich nicht das ganze Reich abreiften. Einen Stamm will ich deinem Sohne gehen urn Davids willen, meines Knechts, und urn Jerusalems willen, die ich erwahlet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Und der HERR erweckte Salomo einen Widersacher, Hadad, den Edomiter, von koniglichem Samen, welcherwar in Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Denn da David in Edom war und Joab, der Feldhauptmann, hinaufzog, die Erschlagenen zu begraben, schlug er, was Mannsbilde war, in Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Denn Joab blieb sechs Monden daselbstund das ganze Israel, bis er ausrottete alles, was Mannsbilde war in Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Da floh Hadad und mit ihm etliche Manner der Edomiter von seines Vaters Knechten, daß sie nach Agypten kamen. Hadad aber war ein junger Knabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Und sie machten sich auf von Midian und kamen gen Paran; und nahmen Leute mit sich aus Paran und kamen nach Agypten zu Pharao, dem Konige in Agypten; der gab ihm ein Haus und Nahrung und gab ihm ein Land ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Und Hadad fand grofte Gnade vor dem Pharao, daß er ihm auch seines Weibes Thachpenes, der Konigin, Schwesterzum Weibe gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Und die Schwester Thachpenes gebar ihm Genubath, seinen Sohn; und Thachpenes zog ihn auf im Hause Pharaos, daß Genubath war im Hause Pharaos unter den Kindern Pharaos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Da nun Hadad horete in Agypten, daß David entschlafen war mit seinen Vatern, und daß Joab, der Feldhauptmann, tot war, sprach erzu Pharao: Lali mich in mein Land ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Pharao sprach zu ihm: Was fehlet dir bei mir, daß du willst in dein Land ziehen? Er sprach: Nichts; aber lali mich ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Auch erweckte ihm Gott einen Widersacher, Reson, den Sohn Eljadas, der von seinem Herm Hadadeser, dem Kdnige zu Zoba, geflohen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Und sammelte wider ihn Manner und ward ein Hauptmann der Kriegsknechte, da sie David erwurgete; und zogen gen Damaskus und wohneten daselbst und regierten zu Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Und er war Israels Widersacher, solange Salomo lebte. Das ist der Schade, den Hadad litt; darum hatte er einen Ekel wider Israel und ward Konig uber Syrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Dazu Jerobeam, der Sohn Nebats, ein Ephrater von Zareda, Salomos Knecht (und seine Mutter hieli Zeruga, eine Witwe), der hub auch die Hand auf wider den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Und das ist die Sache, darum er die Hand wider den Konig aufhub: Da Salomo Millo bauete, verschloli er eine Lucke an der Stadt Davids, seines Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Und Jerobeam war ein streitbarer Mann. Und da Salomo sah, daß der Knabe aufrichtig war, setzte er ihn uber alle Last des Hauses Josephs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Es begab sich aber zu der Zeit, daß Jerobeam ausging von Jerusalem, und es traf ihn an der Prophet Ahia von Silo auf dem Wege, und hatte einen neuen Mantel an; und waren die beiden allein im Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Und Ahia fassete den neuen Mantel, den er anhatte, und rili ihn in zwolf Stucke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Und sprach zu Jerobeam: Nimm zehn Stucke zu dir. Denn so spricht der HERR, der Gott Israels: Siehe, ich will das Konigreich von der Hand Salomos reilien und dir zehn Stamme geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Einen Stamm soil er haben urn meines Knechts David willen und urn der Stadt Jerusalem willen, die ich erwahlet habe aus alien Stammen Israels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'darum daß sie mich verlassen und angebetet haben Asthoreth, den Gott der Zidonier, Kamos, den Gott der Moabiter, und Milkom, den Gott der Kinder Ammon, und nicht gewandelt haben in meinen Wegen, daß sie taten, was mir wohlgefallt, meine Gebote und Rechte, wie David, sein Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Ich will auch nicht das ganze Reich aus seiner Hand nehmen, sondern ich will ihn zum Fursten machen sein Leben lang urn David, meines Knechts, willen, den ich erwahlet habe, der meine Gebote und Rechte gehalten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Aus der Hand seines Sohns will ich das Konigreich nehmen; und will dir zehn Stamme');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'und seinem Sohn einen Stamm geben, auf daß David, mein Knecht, vor mir eine Leuchte habe ailewege in der Stadt Jerusalem, die ich mir erwahlet habe, daß ich meinen Namen dahin stelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'So will ich nun dich nehmen, daß du regierest liber alles, was dein Herz begehret, und sollst Konig sein uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Wirstdu nun gehorchen allem, das ich dir gebieten werde, und in meinen Wegen wandeln und tun, was mir gefallt, daß du haltest meine Rechte und Gebote, wie mein Knecht David getan hat, so will ich mit dir sein und dir ein bestandig Haus bauen, wie ich David gebauet habe, und will dir Israel geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Und will den Samen Davids urn deswillen demutigen, doch nicht ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomo aber trachtete, Jerobeam zu toten. Da machte sich Jerobeam auf und floh nach Agypten zu Sisak, dem Konige in Agypten; und blieb in Agypten, bis daß Salomo starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Was mehr von Salomo zu sagen ist, und alles, was er getan hat, und seine Weisheit, das ist geschrieben in der Chronik von Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Die Zeit aber, die Salomo Konig war zu Jerusalem uber ganz Israel, ist vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Und Salomo entschlief mit seinen Vatern und ward begraben in der Stadt Davids, seines Vaters. Und sein Sohn Rehabeam ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Und Rehabeam zog gen Sichem; denn das ganze Israel war gen Sichem kommen, ihn zum Konige zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Und Jerobeam, der Sohn Nebats, horete das, da er noch in Agypten war, dahin er vor dem Kdnige Salomo geflohen war; und blieb in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Und sie sandten hin und Men ihn rufen. Und Jerobeam samt der ganzen Gemeine Israels kamen und redeten mit Rehabeam und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Dein Vater hat unser Joch zu hart gemacht; so mache du nun den harten Dienst und das schwere Joch leichter, das er uns aufgelegt hat, so wollen wir dir untertanig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Er aber sprach zu ihnen: Gehet hin bis an den dritten Tag, so kommt wieder zu mir. Und das Volk ging hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Und der Konig Rehabeam hielt einen Rat mit den Altesten, die vor seinem Vater Salomo stunden, da er lebte, und sprach: Wie ratet ihr, daß wir diesem Volk eine Antwort geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Sie sprachen zu ihm: Wirst du heute diesem Volk einen Dienst tun und ihnen zu Willen sein und sie erhoren und ihnen gute Worte geben, so werden sie dir untertanig sein dein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Aber er verliefi der Altesten Rat, den sie ihm gegeben hatten, und hielt einen Rat mit den Jungen, die mit ihm aufgewachsen waren und vor ihm stunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Und er sprach zu ihnen: Was ratet ihr, daß wir antworten diesem Volk, die zu mir gesagt haben: Mache das Joch leichter, das dein Vater auf uns geleget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Und die Jungen, die mit ihm aufgewachsen waren, sprachen zu ihm: Du sollst zu dem Volk, das zu dir sagt: Dein Vater hat unser Joch zu schwer gemacht, mache du es uns leichter, also sagen: Mein kleinster Finger soil dicker sein denn meines Vaters Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Nun, mein Vater hat auf euch ein schwer Joch geladen, ich aber will\'s noch mehr uber euch machen; mein Vater hat euch mit Peitschen gezüchtigt, ich will euch mit Skorpionen zuchtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Also kam Jerobeam samt dem ganzen Volk zu Rehabeam am dritten Tage, wie der Konig gesagt hatte und gesprochen: Kommt wieder zu mir am dritten Tage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Und der Konig gab dem Volk eine harte Antwort und verlieft den Rat, den ihm die Altesten gegeben hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'und redete mit ihnen nach dem Rat der Jungen und sprach: Mein Vater hat euer Joch schwer gemacht, ich aber will es noch mehr uber euch machen; mein Vater hat euch mit Peitschen gezuchtiget, ich aber will euch mit Skorpionen zuchtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Also gehorchte der Konig dem Volk nicht; denn es war also gewandt von dem HERRN, auf da(5 er sein Wort bekraftigte, das er durch Ahia von Silo geredet hatte zu Jerobeam, dem Sohn Nebats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Da aber das ganze Israel sah, daü der Konig sie nicht horen wollte, gab das Volk dem Konige eine Antwort und sprach: Was haben wir denn Teils an David, Oder Erbe am Sohn Isais? Israel, hebe dich zu deinen Hütten! So siehe nun du zu deinem Hause, David! Also ging Israel in seine Hutten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'dad Rehabeam regierete nur uber die Kinder Israel, die in den Stadten Judas wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Und da der Konig Rehabeam hinsandte Adoram, den Rentmeister, warf ihn ganz Israel mit Steinen zu Tode. Aber der Konig Rehabeam stieg frisch auf einen Wagen, dad er flohe gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Also fiel Israel ab vom Hause Davids bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Da nun ganz Israel horete, dad Jerobeam war wiederkommen, sandten sie hin und lieden ihn rufen zu der ganzen Gemeine und machten ihn zum Konige uber das ganze Israel. Und folgte niemand dem Hause David ohne der Stamm Juda alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Und da Rehabeam gen Jerusalem kam, sammelte er das ganze Haus Juda und den Stamm Benjamin, hundertundachtzigtausend junge streitbare Mannschaft, wider das Haus Israel zu streiten und das Konigreich wieder an Rehabeam, den Sohn Salomos, zu bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Es kam aber Gottes Wort zu Semaja, dem Mann Gottes, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Sage Rehabeam, dem Sohn Salomos, dem Konig Judas, und zum ganzen Hause Juda und Benjamin und dem andern Volk und sprich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'So spricht der HERR: Ihr sollt nicht hinaufziehen und streiten wider eure Bruder, die Kinder Israel; ein jeder Mann gehe wieder heim: denn solches istvon mirgeschehen. Und sie gehorchten dem Wort des HERRN und kehreten urn, dafi sie hingingen, wie der HERR gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Jerobeam aber bauete Sichem auf dem Gebirge Ephraim und wohnete drinnen, und zog von dannen heraus und bauete Pnuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jerobeam abergedachte in seinem Herzen: Das Konigreich wird nun wieder zum Hause Davids fallen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'so dies Volk soil hinaufgehen, Opfer zu tun in des HERRN Hause zu Jerusalem; und wird sich das Herz dieses Volks wenden zu ihrem Herrn Rehabeam, dem Konige Judas, und wird mich erwurgen und wieder zu Rehabeam, dem Konige Judas, fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Und der Konig hielt einen Rat; und machte zwei güldene Kalber und sprach zu ihnen: Es ist euch zu viel, hinauf gen Jerusalem zu gehen; siehe, da sind deine Gotter, Israel, die dich aus Agyptenland gefuhret haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Und setzte eins zu Bethel und das andere tat er gen Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Und das geriet zur Sunde; denn das Volk ging hin Vordem einen bis gen Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Er machte auch ein Haus der Hohen; und machte Priester von den Geringsten im Volk, die nicht von den Kindern Levi waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Und er machte ein Fest am funfzehnten Tage des achten Monden, wie das Fest in Juda, und opferte auf dem Altar. So tat er zu Bethel, daß man den Kalbern opferte, die er gemacht hatte; und stiftete zu Bethel die Priester der Hohen, die er gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Und opferte auf dem Altar, den er gemacht hatte zu Bethel, am funfzehnten Tage des achten Monden, welchen eraus seinem Herzen erdacht hatte; und machte den Kindern Israel Feste; und opferte auf dem Altar, daü man rauchern sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Und siehe, ein Mann Gottes kam von Juda durch das Wort des HERRN gen Bethel; und Jerobeam stund bei dem Altar zu rauchern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Und er rief wider den Altar durch das Wort des HERRN und sprach: Altar, Altar! so spricht der HERR: Siehe, es wird ein Sohn dem Hause Davids geboren werden mit Namen Josia, der wird aufdiropfern die Priester der Hohe, die auf dir rauchern, und wird Menschenbeine auf dir verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Und er gab des Tages ein Wunder und sprach: Das ist das Wunder, daß solches der HERR geredet hat: Siehe, der Altar wird reiften und die Asche verschuttet werden, die drauf ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Da aber der Konig das Wort von dem Mann Gottes horete, der wider den Altar zu Bethel rief, reckte er seine Hand aus bei dem Altar und sprach: Greifet ihn! Und seine Hand verdorrete, die er wider ihn ausgereckt hatte, und konnte sie nicht wieder zu sich ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Und der Altar rift, und die Asche ward verschuttet vom Altar, nach dem Wunder, das der Mann Gottes gegeben hatte durch das Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Und der Konig antwortete und sprach zu dem Mann Gottes: Bitte das Angesicht des HERRN, deines Gottes, und bitte fur mich, daß meine Hand wieder zu mir komme. Da bat der Mann Gottes das Angesicht des HERRN; und dem Konige ward seine Hand wieder zu ihm gebracht und ward, wie sie vorhin war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Und der Konig redete mit dem Mann Gottes: Komm mit mir heim und labe dich; ich will dir ein Geschenk geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Aber der Mann Gottes sprach zum Konige: Wenn du mir auch dein halbes Haus gabest, so kame ich doch nicht mit dir; denn ich will an diesem Ort kein Brot essen noch Wasser trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Denn also ist mir geboten durch des HERRN Wort und gesagt: Du sollst kein Brot essen und kein Wasser trinken und nicht wieder durch den Weg kommen, den du gegangen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Und erging weg durch einen andern Weg und kam nicht wieder durch den Weg, den er gen Bethel kommen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Es wohnete aber ein alter Prophet zu Bethel; zu dem kam sein Sohn und erzahlete ihm alle Werke, die der Mann Gottes getan hatte des Tages zu Bethel, und die Worte, die er zum Konige geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Und ihr Vater sprach zu ihnen: Wo ist der Weg den er gezogen ist? Und seine Sohne zeigten ihm den Weg, den der Mann Gottes gezogen war, der von Juda kommen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Er aber sprach zuseinen Sohnen: Satteltmir den Esel! Und da sie ihm den Esel sattelten, ritt er drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Und erzog dem Mann Gottes nach und fand ihn untereiner Eiche sitzen; und sprach zu ihm: Bist du der Mann Gottes, der von Juda kommen ist? Er sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Er sprach zu ihm: Komm mit mir heim und ift Brot!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Er aber sprach: Ich kann nicht mit dir umkehren und mit dir kommen; ich will auch nicht Brot essen noch Wasser trinken mit dir an diesem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Denn es ist mit mir geredet worden durch das Wort des HERRN: Du sollst daselbst weder Brot essen noch Wasser trinken; du sollst nicht wieder durch den Weg gehen, den du gegangen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Er sprach zu ihm: Ich bin auch ein Prophet wie du, und ein Engel hat mit mir geredet durch des HERRN Wort und gesagt: Fuhre ihn wieder mit dir heim, daß er Brot esse und Wasser trinke. Er log ihm aber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Und fuhrete ihn wieder urn, daß er Brot aft und Wasser trank in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Und da sie zu Tisch saften, kam das Wort des HERRN zum Propheten, der ihn wieder umgefuhret hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'und schrie den Mann Gottes an, der von Juda kommen war, und sprach: So spricht der HERR: Darum daß du dem Munde des HERRN bist ungehorsam gewesen und hast nicht gehalten das Gebot, das dir der HERR, dein Gott, geboten hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'und bist umgekehret, hast Brot gegessen und Wasser getrunken an dem Ort, davon er dir sagte: Du sollst weder Brot essen noch Wasser trinken, so soli dein Leichnam nicht in deiner Vater Grab kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Und nachdem er Brot gegessen und getrunken hatte, sattelte man den Esel dem Propheten, den er wieder umgefuhret hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Und da erwegzog, fand ihn ein Lowe auf dem Wege und totete ihn; und sein Leichnam lag geworfen in dem Wege und der Esel stund neben ihm, und der Lowe stund neben dem Leichnam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Und da Leute vorubergingen, sahen sie den Leichnam in den Weg geworfen und den Lowen bei dem Leichnam stehen; und kamen und sagten es in der Stadt, da der alte Prophet innen wohnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Da das der Prophet horete, der ihn wieder umgefuhret hatte, sprach er: Es ist der Mann Gottes, der dem Munde des HERRN ist ungehorsam gewesen; darum hat ihn der HERR dem Lowen gegeben, der hat ihn zerbrochen und getotet nach dem Wort, das ihm der HERR gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Und sprach zu seinen Sohnen: Sattelt mir den Esel! Und da sie ihn gesattelt hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'zog er hin und fand seinen Leichnam in den Weg geworfen, und den Esel und den Lowen neben dem Leichnam stehen Der Lowe hatte nichts gefressen vom Leichnam und den Esel nicht zerbrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Da hub der Prophet den Leichnam des Mannes Gottes auf und legte ihn auf den Esel und fuhrete ihn wieder urn; und kam in die Stadt des alten Propheten, daß sie ihn klageten und begruben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Und er legte den Leichnam in sein Grab; und sie klagten ihn: Ach, Bruder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Und da sie ihn begraben hatten, sprach er zu seinen Sohnen: Wenn ich sterbe, so begrabet mich in dem Grabe, da der Mann Gottes innen begraben ist, und leget meine Beine neben seine Beine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Denn es wird geschehen, was er geschrieen hat wider den Altar zu Bethel durch das Wort des HERRN und wider alle Hauser der Hohen, die in den Stadten Samarias sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Aber nach dieser Geschichte kehrete sich Jerobeam nicht von seinem bosen Wege, sondern verkehrete sich und machte Priester der Hohen von den Geringsten des Volks: Zu wem er Lust hatte, des Hand fullete er, und der ward Priester der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Und dies geriet zur Sunde dem Hause Jerobeams, daß er verderbet und von der Erde vertilget ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Zu der Zeit war Abia, derßohn Jerobeams, krank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Und Jerobeam sprach zu seinem Weibe: Mache dich auf und verstelle dich, daß niemand merke, daß du Jerobeams Weib seiest, und gehe hin gen Silo. Siehe, daselbst ist der Prophet Ahia, der mir geredet hat, daß ich sollte Konig sein uber dies Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Und nimm mitdirzehn Brote und Kuchen und einen Krug mit Honig; und komm zu ihm, daß erdir sage, wie es dem Knaben gehen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Und das Weib Jerobeams tat also; und machte sich auf und ging hin gen Silo und kam ins Haus Ahias. Ahia aber konnte nicht sehen; denn seine Augen starreten vor Alter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Aber der HERR sprach zu Ahia: Siehe, das Weib Jerobeams kommt, daß sie von dir eine Sache frage urn ihren Sohn; denn er ist krank. So rede nun mit ihr so und so. Da sie nun hineinkam, stellete sie sich fremd.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Als aber Ahia horete das Rauschen ihrer Fülie zur Tur hineingehen, sprach er: Komm herein, du Weib Jerobeams, warum stellest du dich so fremd? Ich bin zu dir gesandt ein harter Bote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Gehe hin und sage Jerobeam: So spricht der HERR, der Gott Israels: Ich habe dich erhaben aus dem Volk und zum Fursten uber mein Volk Israel gesetzt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'und habe das Konigreich von Davids Hause gerissen und dir gegeben. Du aber bist nicht gewesen wie mein Knecht David, der meine Gebote hielt und wandelte mir nach von ganzem Herzen, daß er tat, was mir nur wohlgefiel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'und hast übel getan uber alle, die vor dir gewesen sind, bist hingegangen und hast dir andere Gotter gemacht und gegossene Bilder, daß du mich zu Zorn reizetest, und hast mich hinter deinen Rücken geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Darum siehe, ich will Unglück liber das Haus Jerobeams führen und ausrotten an dem Jerobeam auch den, der an die Wand pisset, den Verschlossenen und Verlassenen in Israel; und will die Nachkommen des Hauses Jerobeam ausfegen, wie man Kot ausfeget, bis ganz mit ihm aus sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Wer von Jerobeam stirbt in der Stadt, den sollen die Hunde fressen; wer aber auf dem Felde stirbt, den sollen die Vogel des Himmels fressen; denn der HERR hat es geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'So mache du dich auf und gehe heim. Und wenn dein Fufi zur Stadt eintritt, wird das Kind sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Und es wird ihn das ganze Israel klagen und werden ihn begraben. Denn dieser allein von Jerobeam wird zu Grabe kommen, darum daß etwas Gutes an ihm erfunden ist vor dem HERRN, dem Gott Israels, im Hause Jerobeams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Der HERR aber wird ihm einen Konig uber Israel erwecken, der wird das Haus Jerobeams ausrotten des Tages. Und was ist nun gemacht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Und der HERR wird Israel schlagen, gleichwie das Rohr im Wasser beweget wird, und wird Israel ausreilien von diesem guten Lande, das er ihren Vatern gegeben hat, und wird sie streuen uber das Wasser, darum daß sie ihre Haine gemacht haben, den HERRN zu erzurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Und wird Israel ubergeben urn der Sünden willen Jerobeams, der da gesundiget hat und Israel hat sundigen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Und das Weib Jerobeams machte sich auf, ging hin und kam gen Thirza. Und da sie auf die Schwelle des Hauses kam, starb der Knabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Und sie begruben ihn, und ganz Israel klagte ihn nach dem Wort des HERRN, das er geredet hatte durch seinen Knecht Ahia, den Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Was mehrvon Jerobeam zu sagen ist, wie er gestritten und regieret hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Die Zeit aber, die Jerobeam regierte, sind zweiundzwanzig Jahre. Und entschlief mit seinen Vatern; und sein Sohn Nadab ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'So war Rehabeam, der Sohn Salomos, Konig in Juda. Einundvierzig Jahre alt war Rehabeam, da er Konig ward und regierete siebenzehn Jahre zu Jerusalem, in der Stadt, die der HERR erwahlet hatte aus alien Stammen Israels, daß er seinen Namen daselbst hinstellete. Seine Mutter hieli Naema, eine Ammonitin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Und Juda tat, das dem HERRN libel gefiel; und reizten ihn zu Eifer, mehr denn alles, das ihre Vater getan hatten mit ihren Sünden, die sie taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Denn sie baueten ihnen auch Hohen, Saulen und Haine auf alien hohen Hügeln und unter alien grünen Baumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Es waren auch Hurer im Lande; und sie taten alle die Greuel der Heiden, die der HERR vor den Kindern Israel vertrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Aber im fünften Jahr des Konigs Rehabeam zog Sisak, der Konig in Agypten, herauf wider Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Und nahm die Schatze aus dem Hause des HERRN und aus dem Hause des Konigs und alles, was zu nehmen war, und nahm alle güldenen Schilde, die Salomo hatte lassen machen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'an welcher Statt lieli der Konig Rehabeam eherne Schilde machen und befahl sie unter die Hand der obersten Trabanten, die der Tür hüteten am Hause des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Und so oft der Konig in das Haus des HERRN ging, trugen sie die Trabanten und brachten sie wieder in der Trabanten Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Was aber mehr von Rehabeam zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Es war aber Krieg zwischen Rehabeam und Jerobeam ihr Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Und Rehabeam entschlief mit seinen Vatern und ward begraben mit seinen Vatern in der Stadt Davids. Und seine Mutter hieß Naema, eine Ammonitin. Und sein Sohn Abiam ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Im achtzehnten Jahrdes Konigs Jerobeam, des Sohns Nebats, ward Abiam Konig in Juda;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'und regierte drei Jahre zu Jerusalem. Seine Mutter hiefi Maecha, eine Tochter Abisaloms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Und erwandelte in alien Sunden seines Vaters, die er vor ihm getan hatte und sein Herz war nicht rechtschaffen an dem HERRN, seinem Gott, wie das Herz seines Vaters David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Denn urn Davids willen gab der HERR, sein Gott, ihm eine Leuchte zu Jerusalem, daß er seinen Sohn nach ihm erweckte und erhielt zu Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'darum daß David getan hatte, das dem HERRN wohlgefiel, und nicht gewichen war von allem, das er ihm gebot sein Leben lang, ohne in dem Handel mit Uria, dem Hethiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Es war aber ein Krieg zwischen Rehabeam und Jerobeam sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Was aber mehr von Abiam zu sagen ist, und alles, was er getan hat; siehe, das ist geschrieben in der Chronik der Konige Judas. Es war aber Krieg zwischen Abiam und Jerobeam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Und Abiam entschlief mit seinen Vatern, und sie begruben ihn in der Stadt Davids. Und Assa, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Im zwanzigsten Jahrdes Konigs Jerobeam uber Israel ward Assa Konig in Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Und regierte einundvierzig Jahre zu Jerusalem. Seine Mutter hiefi Maecha, eine Tochter Abisaloms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Und Assa tat, das dem HERRN wohlgefiel, wie sein Vater David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Und tat die Hurer aus dem Lande und tat ab alle Gotzen, die seine Vater gemacht hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Dazu setzte er auch seine Mutter Maecha ab vom Amt, das sie dem Miplezeth gemacht hatte im Haine. Und Assa rottete aus ihren Miplezeth und verbrannte ihn im Bach Kidron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Aber die Hohen taten sie nicht ab. Doch war das Herz Assas rechtschaffen an dem HERRN sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Und das Silber und Gold und Gefal J, das sein Vater geheiliget hatte, und was geheiliget war zum Hause des HERRN brachte erein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Und es war Streit zwischen Assa und Baesa, dem Konige Israels, ihr Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baesa aber, der Konig Israels, zog herauf wider Juda und bauete Rama, daß niemand sollte aus und einziehen auf Assas Seiten, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Da nahm Assa alles Silber und Gold, das ubrig war im Schatz des Hauses des HERRN und im Schatz des Hauses des Konigs, und gab\'s in seiner Knechte Hande; und sandte sie zu Benhadad, dem Sohn Tabrimons, des Sohns Hesions, dem Konige in Syrien, der zu Damaskus wohnete, und lieli ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Es ist ein Bund zwischen mir und dir und zwischen meinem Vater und deinem Vater; darum schicke ich dir ein Geschenk, Silber und Gold, dafj du fahren lassest den Bund, den du mit Baesa, dem Konige Israels, hast, daß er von mir abziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Benhadad gehorchte dem Konige Assa und sandte seine Hauptleute wider die Stadte Israels und schlug Ijon und Dan und Abel-Beth-Maecha, das ganze Cinneroth, an dem ganzen Lande Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Da das Baesa horete, lieli er ab, zu bauen Rama, und zog wieder gen Thirza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Der Konig Assa aber lieli erschallen im ganzen Juda: Hie sei niemand ausgenommen! Und sie nahmen die Steine und Holz von Rama weg, damit Baesa gebauet hatte; und der Konig Assa bauete damit Geba-Benjamin und Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Was aber mehr von Assa zu sagen ist, und alle seine Macht und alles, was er getan hat, und die Stadte, die er gebauet hat, siehe, das ist geschrieben in der Chronik der Konige Judas; ohne daß er in seinem Alter an seinen Fülien krank war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Und Assa entschlief mit seinen Vatern und ward begraben mit seinen Vatern in der Stadt Davids, seines Vaters. Und Josaphat, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab aber, der Sohn Jerobeams, ward Konig uber Israel im andern Jahr Assas, des Konigs Judas, und regierte uber Israel zwei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Und tat, das dem HERRN übel gefiel, und wandelte in dem Wege seines Vaters und in seiner Sünde, damit er Israel hatte sundigen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Aber Baesa, der Sohn Ahias, aus dem Hause Isaschar, machte einen Bund wider ihn und schlug ihn zu Gibethon, welche war der Philister. Denn Nadab und das ganze Israel belagerten Gibethon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Also totete ihn Baesa im dritten Jahr Assas, des Konigs Judas, und ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Als er nun Konig war, schlug er das ganze Haus Jerobeams und lieli nicht uber etwas, das den Odem hatte von Jerobeam, bis er ihn vertilgte; nach dem Wort des HERRN, das er geredet hatte durch seinen Knecht Ahia von Silo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'urn der Sünde willen Jerobeams, die er tat und damit Israel sundigen machte, mit dem Reizen, damit er den HERRN, den Gott Israels, erzümete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Was aber mehr von Nadab zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Und es war Krieg zwischen Assa und Baesa, dem Konige Israels, ihr Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Im dritten Jahr Assas, des Konigs Judas, ward Baesa, der Sohn Ahias, Konig uber das ganze Israel zu Thirza vierundzwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Und tat, das dem HERRN ubel gefiel, und wandelte in dem Wege Jerobeams und in seiner Sünde, damit er Israel hatte sundigen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Es kam aberdas Wort des HERRN zu Jehu, dem Sohn Hananis, wider Baesa und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Darum, dafi ich dich aus dem Staube erhoben habe und zum Fursten gemacht uber mein Volk Israel, und du wandelst in dem Wege Jerobeams und machest mein Volk Israel sundigen, daß du mich erzümest durch ihre Sünde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'siehe, so will ich die Nachkommen Baesas und die Nachkommen seines Hauses wegnehmen und will dein Haus setzen wie das Haus Jerobeams, des Sohns Nebats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Wer von Baesa stirbt in der Stadt, den sollen die Hunde fressen; und wer von ihm stirbt auf dem Felde, den soilen die Vogel des Himmels fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Was aber mehrvon Baesa zu sagen ist, und was er getan hat, und seine Macht, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Und Baesa entschlief mit seinen Vatern und ward begraben zu Thirza. Und sein Sohn Ela ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Auch das Wort des HERRN kam durch den Propheten Jehu, den Sohn Hananis, uber Baesa und über sein Haus und wider alles Libel, das er tat vor dem HERRN, ihn zu erzürnen durch die Werke seiner Hande, daß es würde wie das Haus Jerobeams, und darum daß er diesen erschlagen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Im sechsundzwanzigsten Jahr Assas, des Konigs Judas, ward Ela, der Sohn Baesas, Konig über Israel zu Thirza zwei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Aber sein Knecht Simri, der Oberste über die Halfte der Wagen, machte einen Bund wider ihn. Er aber war zu Thirza, trank und ward trunken im Hause Arzas, des Vogts zu Thirza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Und Simri kam hinein und schlug ihn tot im siebenundzwanzigsten Jahr Assas, des Konigs Judas, und ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Und da er Konig war und auf seinem Stuhl safi, schlug er das ganze Haus Baesas und lieü nicht über auch den, der an die Wand pisset, dazu seine Erben und seine Freunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Also vertilgte Simri das ganze Haus Baesas nach dem Wort des HERRN, das er über Baesa geredet hatte durch den Propheten Jehu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'urn aller Sünden willen Baesas und seines Sohns Ela, die sie taten und Israel sündigen machten, den HERRN, den Gott Israels, zu erzürnen durch ihre Abgotterei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Was aber mehr von Ela zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Im siebenundzwanzigsten Jahr Assas, des Konigs Judas, ward Simri Konig sieben Tage zu Thirza. Denn das Volk lag vor Gibethon der Philister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Da aber das Volk im Lager horete sagen, dafi Simri einen Bund gemacht und auch den Konig erschlagen hatte, da machte ganz Israel desseiben Tages Amri, den Feldhauptmann, zum Konige über Israel im Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Und Amri zog herauf und das ganze Israel mit ihm von Gibethon und belagerten Thirza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Da aber Simri sah, daß die Stadt sollte gewonnen werden, ging er in den Palast im Hause des Konigs und verbrannte sich mit dem Hause des Konigs und starb');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'urn seiner Sünden willen, die er getan hatte, daß er tat, das dem HERRN übel gefiel, und wandelte in dem Wege Jerobeams und in seiner Sünde, die er tat, daß er Israel sündigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Was aber mehr von Simri zu sagen ist, und wie er einen Bund machte, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Dazumal teilte sich das Volk Israel in zwei Teile. Eine Halfte hing an Thibni, dem Sohn Ginaths, daß sie ihn zum Konige machten; die andere Halfte aber hing an Amri.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Aber das Volk, das an Amri hing, ward starker denn das Volk, das an Thibni hing, dem Sohn Ginaths. Und Thibni starb; da ward Amri Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Im einunddreilügsten Jahr Assas, des Konigs Judas, ward Amri Konig über Israel zwolf Jahre und regierete zu Thirza sechs Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Er kaufte den Berg Samaria von Semer urn zween Zentnerßilbers und bauete auf den Berg; und hieli die Stadt, die er bauete, nach dem Namen Semers, des Berges Herm, Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Und Amri tat, das dem HERRN übel gefiel, und war arger denn alle, die vor ihm gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Und wandelte in alien Wegen Jerobeams, des Sohns Nebats, und in seinen Sünden, damit er Israel sundigen machte, daß sie den HERRN, den Gott Israels, erzurneten in ihrer Abgotterei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Was aber mehr von Amri zu sagen ist, und alles, was er getan hat, und seine Macht, die er geübet hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Und Amri entschlief mit seinen Vatern und ward begraben zu Samaria. Und Ahab, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Im achtunddreilügsten Jahr Assas, des Konigs Judas, ward Ahab, der Sohn Amris, Konig über Israel und regierte über Israel zu Samaria zweiundzwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Und tat, das dem HERRN übel gefiel, über alle, die vor ihm gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Und war ihm ein Geringes, daß er wandelte in der Sunde Jerobeams, des Sohns Nebats, und nahm dazu Isebel, die Tochter Ethbaals, des Konigs zu Zidon, zum Weibe; und ging hin und dienete Baal und betete ihn an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Und richtete Baal einen Altar auf im Hause Baals, das er ihm bauete zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Und machte einen Hain, daü Ahab mehrtat, den HERRN, den Gott Israels, zu erzurnen, denn alle Konige Israels, die vor ihm gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Zur selben Zeit bauete Hiel von Bethel Jericho. Es kostete ihn seinen ersten Sohn Abiram, da er den Grund legte, und seinen jungsten Sohn Segub, da er die Turen setzte, nach dem Wort des HERRN, das er geredet hatte durch Josua, den Sohn Nuns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Und es sprach Elia, der Thisbiter, aus den Burgern Gileads, zu Ahab: So wahrder HERR, der Gott Israels, lebet, vor dem ich stehe, es soil diese Jahre weder Tau noch Regen kommen, ich sage es denn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Und das Wort des HERRN kam zu ihm und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Gehe weg von hinnen und wende dich gegen Morgen und verbirg dich am Bach Krith, der gegen den Jordan fleulit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Und sollstvom Bach trinken; und ich habe den Raben geboten, daü sie dich daselbst sollen versorgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Er aber ging hin und tat nach dem Wort des HERRN; und ging weg und setzte sich am Bach Krith, der gegen den Jordan fleulit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Und die Raben brachten ihm Brot und Fleisch des Morgens und des Abends; und er trank des Bachs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Und es geschah nach etlichen Tagen, daß der Bach vertrocknete; denn es war kein Regen im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Da kam das Wort des HERRN zu ihm und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Mache dich auf und gehe gen Zarpath, welche bei Zidon liegt, und bleibe daselbst; denn ich habe daselbst einer Witwe geboten, daß sie dich versorge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Und er machte sich auf und ging gen Zarpath. Und da er kam an die Tur der Stadt, siehe, da war eine Witwe und las Holz auf. Und er rief ihr und sprach: Hole mir ein wenig Wasser im Gefaüe, daß ich trinke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Da sie, aber hinging zu holen, rief er ihr und sprach: Bringe mir auch einen Bissen Brots mit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Sie sprach: So wahr der HERR, dein Gott, lebet, ich habe nichts Gebackenes ohne eine Handvoll Mehls im Kad und ein wenig 01 im Kruge. Und siehe, ich habe ein Holz Oder zwei aufgelesen und gehe hinein und will mir und meinem Sohn zurichten, daü wiressen und sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elia sprach zu ihr: Furchte dich nicht! Gehe hin und mache es, wie du gesagt hast; doch mache mir am ersten ein kleines Gebacknes davon und bringe mir\'s heraus; dir aber und deinem Sohn sollst du danach auch machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Denn also spricht der HERR, der Gott Israels: Das Mehl im Kad soil nicht verzehret werden, und dem Olkrug soil nichts mangeln bis auf den Tag, da der HERR regnen lassen wird auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Sie ging hin und machte, wie Elia gesagt hatte. Und er ali, und sie auch und ihr Haus eine Zeitlang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Das Mehl im Kad ward nicht verzehret, und dem Olkrug mangelte nichts, nach dem Wort des HERRN, das er geredet hatte durch Elia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Und nach diesen Geschichten ward des Weibes, seiner Hauswirtin, Sohn krank, und seine Krankheit war so sehr hart, daß kein Odem mehr in ihm blieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Und sie sprach zu Elia: Was habe ich mit dir zu schaffen, du Mann Gottes? Du bist zu mir hereinkommen, daß meiner Missetat gedacht und mein Sohn getotet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Er sprach zu ihr: Gib mirherdeinen Sohn! Und er nahm ihn von ihrem Scholi und ging hinauf auf den Saal, da erwohnete, und legte ihn auf sein Bett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Und rief den HERRN an und sprach: HERR, mein Gott, hast du auch der Witwe, bei der ich ein Gast bin, so ubel getan, daß du ihren Sohn totest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Und er maü sich uber dem Kinde dreimal und rief den HERRN an und sprach: HERR, mein Gott, la(i die Seele dieses Kindes wiederzu ihm kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Und der HERR erhorete die Stimme Elias; und die Seele des Kindes kam wieder zu ihm und ward lebendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Und Elia nahm das Kind und brachte es hinab vom Saal ins Haus; und gab es seiner Mutter und sprach: Siehe da, dein Sohn lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Und das Weib sprach zu Elia: Nun erkenne ich, daß du ein Mann Gottes bist, und des HERRN Wort in deinem Munde ist Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Und uber eine lange Zeit kam das Wort des HERRN zu Elia, im dritten Jahr, und sprach: Gehe hin und zeige dich Ahab, daß ich regnen lasse auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Und Elia ging hin, daß er sich Ahab zeigete. Es war aber eine grolie Teurung zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Und Ahab rief Obadja, seinem Hof meister. (Obadja aber furchtete den HERRN sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Denn da Isebel die Propheten des HERRN ausrottete, nahm Obadja hundert Propheten und versteckte sie in der Hohle, hie funfzig und da funfzig, und versorgete sie mit Brot und Wasser.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'So sprach nun Ahab zu Obadja: Zeuch durchs Land zu alien Wasserbrunnen und Bachen, ob wir mochten Heu finden und die Rosse und Mauler erhalten, daß nicht das Vieh alies umkomme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Und sie teilten sich ins Land, daß sie es durchzogen. Ahab zog allein auf einem Weg und Obadja auch allein den andern Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Da nun Obadja auf dem Wege war, siehe, da begegnete ihm Elia; und da er ihn kannte, fiel er auf sein Antlitz und sprach: Bist du nicht mein Herr Elia?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Er sprach: Ja; gehe hin, sage deinem Herm: Siehe, Elia isthie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Er aber sprach: Was habe ich gesundiget, dad du deinen Knecht willst in die Hande Ahabs geben, dad er mich tote?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'So wahr der HERR, dein Gott, lebet, es ist kein Volk noch Konigreich, dahin mein Herr nicht gesandt hat, dich zu suchen. Und wenn sie sprachen: Er ist nicht hie, nahm ereinen Eid von dem Konigreich und Volk, dad man dich nicht funden hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Und du sprichst nun: Gehe hin, sage deinem Herm: Siehe, Elia isthie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Wenn ich nun hinginge von dir, so wurde dich der Geistdes HERRN wegnehmen, weid nicht wohin; und ich dann kame und sagte es Ahab an und fande dich nicht, so erwurgete er mich. Aber dein Knecht furchtet den HERRN von seiner Jugend auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Ist\'s meinem Herm nicht angesagt, was ich getan habe, da Isebel die Propheten des HERRN erwurgete, dad ich der Propheten des HERRN hundert versteckte, hie funfzig und da fünfzig in der Hbhle, und versorgete sie mit Brot und Wasser?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Und du sprichst nun: Gehe hin, sage deinem Herm: Elia ist hie; dad er mich erwurge!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elia sprach: So wahr der HERR Zebaoth lebet, vor dem ich stehe, ich will mich ihm heute zeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Da ging Obadja hin Ahab entgegen und sagte es ihm an. Und Ahab ging hin Elia entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Und da Ahab Elia sah, sprach Ahab zu ihm: Bist du, der Israel verwirret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Er aber sprach: Ich verwirre Israel nicht, sondern du und deines Vaters Haus, damit dad ihr des HERRN Gebote verlassen habt und wandelt Baalim nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Wohlan, so sende nun hin und versammle zu mir das ganze Israel auf den Berg Karmel und die vierhundertundfunfzig Propheten Baals, auch die vierhundert Propheten des Hains, die vom Tisch Isebels essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Also sandte Ahab hinunter alle Kinder Israel und versammelte die Propheten auf den Berg Karmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Da trat Elia zu allem Volk und sprach: Wie lange hinket ihr auf beiden Seiten? Ist der HERR Gott, so wandelt ihm nach; ist\'s aber Baal, so wandelt ihm nach! Und das Volk antwortete ihm nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Da sprach Elia zum Volk: Ich bin allein uberblieben ein Prophet des HERRN, aber der Propheten Baals sind vierhundertundfunfzig Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'So gebet uns nun zween Farren und lasset sie erwahlen einen Farren und ihn zerstucken und aufs Holz legen und kein Feuer dran legen, so will ich den andern Farren nehmen und aufs Holz legen und auch kein Feuer dran legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'So rufet ihr an den Namen eures Gottes, und ich will den Namen des HERRN anrufen. Welcher Gott nun mit Feuer antworten wird, der sei Gott. Und das ganze Volk antwortete und sprach: Das ist recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Und Elia sprach zu den Propheten Baals: Erwahlet ihr einen Farren und machet am ersten, denn euer ist viel; und rufet eures Gottes Namen an und legetkein Feuer dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Und sie nahmen den Farren, den er ihnen gab, und richteten zu und riefen an den Namen Baals von Morgen an bis an den Mittag und sprachen: Baal, erhore uns! Aber es war da keine Stimme noch Antwort. Und sie hinkten urn den Altar, den sie gemacht hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Da es nun Mittag ward, spottete ihrer Elia und sprach: Rufet laut; denn er ist ein Gott, er dichtet, Oder hat zu schaffen, Oder ist uber Feld, Oder schlaft vielleicht, dad er aufwache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Und sie riefen laut und ritzten sich mit Messern und Pfriemen nach ihrer Weise, bis dafi ihr Blut hernach ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Da aber der Mittag vergangen war, weissagten sie, bis daß man das Speisopfer tun sollte; und war da keine Stimme, noch Antwort, noch Aufmerken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Da sprach Elia zu allem Volk: Kommt her, alles Volk, zu mir! Und da alles Volk zu ihm trat, heilete er den Altar des HERRN, der zerbrochen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Und nahm zwolf Steine nach der Zahl der Stamme der Kinder Jakobs (zu welchem das Wort des HERRN redete und sprach: Du sollst Israel heiden).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Und bauete von den Steinen einen Altar im Namen des HERRN und machte urn den Altar her eine Grube, zwei Kornmad weit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Und richtete das Holz zu und zerstuckte den Farren und legte ihn aufs Holz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Und sprach: Holet vier Kad Wasser voll und giedet es auf das Brandopfer und auf das Holz. Und sprach: Tut es noch einmal. Und sie taten es noch einmal. Und er sprach: Tut es zum drittenmal. Und sie taten es zum drittenmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Und das Wasser lief urn den Altar her, und die Grube ward auch voll Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Und da die Zeit war, Speisopfer zu opfern, trat Elia, der Prophet, herzu und sprach: HERR, Gott Abrahams, Isaaks und Israels, lad heute kund werden, dad du Gott in Israel bist und ich dein Knecht, und dad ich solches alles nach deinem Wort getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Erhore mich, HERR, erhore mich, dad dies Volk wisse, dad du, HERR, Gott bist, dad du ihr Herz danach bekehrest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Da fiel das Feuer des HERRN herab und frad Brandopfer, Holz, Steine und Erde und leckte das Wasser auf in der Grube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Da das alles Volk sah, fiel es auf sein Angesicht und sprachen: Der HERR ist Gott, der HERR ist Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elia aber sprach zu ihnen: Greifet die Propheten Baals, dad ihrer keinerentrinne! Und sie griffen sie. Und Elia fuhrete sie hinab an den Bach Kison und schlachtete sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Und Elia sprach zu Ahab: Zeuch hinauf, ift und trink; denn es rauschet, als wollte es sehr regnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Und da Ahab hinaufzog zu essen und zu trinken, ging Elia auf des Karmels Spitze und bückte sich zur Erde und tat sein Haupt zwischen seine Kniee.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Und sprach zu seinem Knaben: Gehe hinauf und schaue zum Meer zu! Er ging hinauf und schauete und sprach: Es ist nichts da. Er sprach: Gehe wieder hin siebenmal!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Und im siebentenmal sprach er: Siehe, es gehet eine kieine Wolke auf aus dem Meer wie eines Mannes Hand. Er sprach: Gehe hinauf und sage Ahab: Spanne an und fahre hinab, daß dich der Regen nicht ergreife.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Und ehe man zusah, ward der Himmel schwarz von Wolken und Wind, und kam ein grower Regen. Ahab aber fuhr und zog gen Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Und die Hand des HERRN kam uber Elia; und ergurtete seine Lenden und lief vor Ahab hin, bis er kam gen Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Und Ahab sagte Isebel an alles was Elia getan hatte, und wie er hatte alle Propheten Baals mit dem Schwert erwurget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Da sandte Isebel einen Boten zu Elia und lieft ihm sagen: Die Gotter tun mirdies und das, wo ich nicht morgen urn diese Zeit deiner Seele tue wie dieser Seelen einer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Da er das sah, machte er sich auf und ging, wo er hin wollte, und kam gen Berseba in Juda und lieft seinen Knaben daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Er aber ging hin in die Wuste eine Tagreise; und kam hinein und setzte sich unter einen Wacholder und bat, da(S seine Seele stürbe, und sprach: Es ist genug; nimm nun, HERR, meine Seele! Ich bin nicht besser denn meine Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Und legte sich und schlief unter dem Wacholder. Und siehe, der Engel ruhrete ihn und sprach zu ihm: Stehe auf und ift!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Und er sah sich um, und siehe, zu seinen Haupten lag ein gerostet Brot und eine Kanne mit Wasser. Und da ergegessen und getrunken hatte, legte er sich wieder schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Und der Engel des HERRN kam zum andernmal wieder und ruhrete ihn und sprach: Stehe auf und ift; denn du hast einen groften Weg vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Und er stund auf und aft und trank; und ging durch Kraft derselben Speise vierzig Tage und vierzig Nachte bis an den Berg Gottes Horeb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Und kam daselbst in eine Hohle und blieb daselbst über Nacht. Und siehe, das Wort des HERRN kam zu ihm und sprach zu ihm: Was machst du hie, Elia?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Er sprach: Ich habe geeifert um den HERRN, den Gott Zebaoth; denn die Kinder Israel haben deinen Bund verlassen und deine Altare zerbrochen und deine Propheten mit dem Schwert erwurget; und ich bin allein uberblieben, und sie stehen danach, dafi sie mir mein Leben nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Er sprach: Gehe heraus und trittaufden Berg vor den HERRN. Und siehe, der HERR ging voruber, und ein grofter, starker Wind, der die Berge zerrifi und die Felsen zerbrach, vor dem HERRN her; der HERR aber war nicht im Winde. Nach dem Winde aber kam ein Erdbeben; aber der HERR war nicht im Erdbeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Und nach dem Erdbeben kam ein Feuer; aber der HERR war nicht im Feuer. Und nach dem Feuer kam ein still sanftes Sausen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Da das Elia horete, verhullete ersein Antlitz mit seinem Mantel und ging heraus und trat in die Tur der Hohle. Und siehe, da kam eine Stimme zu ihm und sprach: Was hast du hie zu tun, Elia?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Er sprach: Ich habe um den HERRN, den Gott Zebaoth, geeifert; denn die Kinder Israel haben deinen Bund verlassen, deine Altare zerbrochen, deine Propheten mit dem Schwert erwurget; und ich bin allein uberblieben, und sie stehen danach, dafi sie mir das Leben nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Aber der HERR sprach zu ihm: Gehe wiederum deines Weges durch die Wuste gen Damaskus; und geh hinein und salbe Hasael zum Konige uber Syrien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'und Jehu, den Sohn Nimsis, zum Konige fiber Israel und Elisa, den Sohn Saphats, von Abel-Mehola, zum Propheten an deiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Und soil geschehen, dafi, wer dem Schwert Hasaels entrinnet, den soli Jehu toten, und wer dem Schwert Jehus entrinnet den soli Elisa toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Und ich will lassen überbleiben siebentausend in Israel, namlich alle Kniee, die sich nicht gebeuget haben vor Baal, und alien Mund, der ihn nicht geküsset hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Und er ging von dannen und fand Elisa, den Sohn Saphats, daß er pflugete mit zwolf Jochen vor sich hin; und er war selbst unter den Zwolfen. Und Elia ging zu ihm und warf seinen Mantel auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Er aber lieft die Rinder und lief Elia nach und sprach: Laft mich meinen Vater und meine Mutter küssen, so will ich dir nachfolgen. Er sprach zu ihm: Gehe hin und komm wieder; denn ich habe etwas mit dirzu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Und er lief wieder von ihm und nahm ein Joch Rinder und opferte es; und kochte das Fleisch mit dem Holzwerk an den Rindern und gab\'s dem Volk, daß sie alien. Und machte sich auf und folgte Elia nach und dienete ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Und Benhadad, der Konig zu Syrien, versammelte alle seine Macht, und waren zweiunddreiftig Konige mit ihm, und Roft und Wagen; und zog herauf und belagerte Samaria und stritt wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Und sandte Boten zu Ahab, dem Konige Israels, in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Und lieft ihm sagen: So spricht Benhadad: Dein Silber und dein Gold ist mein, und deine Weiber und deine besten Kinder sind auch mein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Der Konig Israels antwortete und sprach: Mein Herr Konig, wie du geredet hast; ich bin dein und alles, was ich habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Und die Boten kamen wieder und sprachen: So spricht Benhadad: Weil ich zu dir gesandt habe und lassen sagen: Dein Silber und dein Gold, deine Weiber und deine Kinder sollst du mir geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'so will ich morgen urn diese Zeit meine Knechte zu dir senden, dafi sie dein Haus und deiner Untertanen Hauser besuchen; und was dir lieblich ist, sollen sie in ihre Hande nehmen und wegtragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Da rief der Konig Israels alien Altesten des Landes und sprach: Merket und sehet, wie bose er\'s vornimmt! Er hat zu mir gesandt urn meine Weiber und Kinder, Silber und Gold, und ich habe ihm des nicht gewehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Da sprachen zu ihm alle Alten und alles Volk: Du sollst nicht gehorchen noch bewilligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Und er sprach zu den Boten Benhadad: Saget meinem Herrn, dem Konige: Alles, was du am ersten deinem Knecht entboten hast, will ich tun; aber dies kann ich nicht tun. Und die Boten gingen hin und sagten solches wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Da sandte Benhadad zu ihm und lieft ihm sagen: Die Gotter tun mir dies und das, wo der Staub Samarias genug sein soil, daß alles Volk unter mir eine Handvoll davon bringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Aber der Konig Israels antwortete und sprach: Saget: Der den Harnisch anlegt, soil sich nicht rühmen, als der ihn hat abgelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Da das Benhadad horete und ereben trank mit den Konigen in den Gezelten, sprach er zu seinen Knechten: Schicket euch! Und sie schickten sich wider die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Und siehe, ein Prophet trat zu Ahab, dem Konige Israels, und sprach: So spricht der HERR: Du hast je gesehen all diesen grofien Haufen. Siehe, ich will ihn heute in deine Hand geben, daß du wissen sollst, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab sprach: Durch wen? Er sprach: So spricht der HERR: Durch die Knaben der Landvogte. Er sprach: Wer soil den Streit anspannen? Er sprach: Du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Da zahlete er die Knaben der Landvogte, und ihrer waren zweihundert und zweiunddreiftig. Und zahlete nach ihnen das ganze Volk aller Kinder Israel: siebentausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Und zogen aus im Mittage. Benhadad aber trank und war trunken im Gezelt samt den zweiunddreiftig Konigen, die ihm zu Hilfe kommen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Und die Knaben der Landvogte zogen am ersten aus. Benhadad aber sandte aus, und die sagten ihm an und sprachen: Es ziehen Manner aus Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Er sprach: Greifetsie lebendig, sie seien urn Friede Oder urn Streits willen ausgezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Da aber die Knaben der Landvogte waren ausgezogen und das Heer ihnen nach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'schlug ein jeglicher, wer ihm vorkam. Und die Syrerflohen, und Israel jagte ihnen nach. Und Benhadad, der Konig zu Syrien, entrann mit Rossen und Reitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Und der Konig Israels zog aus und schlug Roft und Wagen, daß er an den Syrern eine grofte Schlacht tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Da trat ein Prophet zum Konige Israels und sprach zu ihm: Gehe hin und starke dich; und merke und siehe, was du tust! Denn der Konig zu Syrien wird wider dich heraufziehen, wenn das Jahr urn ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Denn die Knechte des Konigs zu Syrien sprachen zu ihm: Ihre Gotter sind Berggotter; darum haben sie uns angewonnen. O daß wir mit ihnen auf der Ebene streiten muftten! Was gilt\'s, wir wollten ihnen angewinnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Tu ihm also: Tu die Konige weg, einen jeglichen von seinem Ort, und stelle Herren an ihre Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Und ordne dir ein Heer, wie das Heer war, das du verloren hast, und Roft und Wagen, wie jene waren, und laft uns wider sie streiten auf der Ebene. Was gilt\'s wirwollen ihnen obliegen? Er gehorchte ihrer Stimme und tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Als nun das Jahr urn war, ordnete Benhadad die Syrer und zog herauf gen Aphek, wider Israel zu streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Und die Kinder Israel ordneten sich auch und versorgeten sich; und zogen hin ihnen entgegen und lagerten sich gegen sie wie zwo kleine Herden Ziegen. Der Syrer aber war das Land voll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Und es trat ein Mann Gottes herzu und sprach zum Konige Israels: So spricht der HERR: Darum, daß die Syrer haben gesagt, der HERR sei ein Gott der Berge und nicht ein Gott der Grunde, so habe ich all diesen groften Haufen in deine Hand gegeben, daß ihr wisset, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Und sie lagerten sich stracks gegen jene, sieben Tage. Am siebenten Tage zogen sie zuhauf in Streit; und die Kinder Israel schlugen der Syrer hunderttausend Fuftvolks auf einen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Und die ubrigen flohen gen Aphek in die Stadt; und die Mauer fiel auf die ubrigen siebenundzwanzigtausend Mann. Und Benhadad floh auch in die Stadt, von einer Kammer in die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Da sprachen seine Knechte zu ihm: Siehe, wir haben gehoret, daß die Konige des Hauses Israel barmherzige Konige sind; so laftt uns Sacke urn unsere Lenden tun und Stricke urn unsere Haupter und zum Konige Israels hinausgehen; vielleicht laftt er deine Seele leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Und sie gurteten Sacke urn ihre Lenden und Stricke um ihre Haupter und kamen zum Konige Israels und sprachen: Benhadad, dein Knecht, laftt dir sagen: Lieber, laft meine Seele leben! Erabersprach: Lebt er noch, so ist er mein Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Und die Manner nahmen eilend das Wort von ihm und deuteten es fur sich und sprachen: Ja, dein Bruder Benhadad. Er sprach: Kommt und bringet ihn! Da ging Benhadad zu ihm heraus. Und lieft ihn auf den Wagen sitzen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'und sprach zu ihm: Die Stadte, die mein Vater deinem Vater genommen hat, will ich dirwiedergeben; und mache dir Gassen zu Damaskus, wie mein Vater zu Samaria getan hat, so will ich miteinem Bunde dich lassen. Und er machte mit ihm einen Bund und liefi ihn ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Da sprach ein Mann unter den Kindern der Propheten zu seinem Nachsten durch das Wort des HERRN: Lieber, schlage mich! Er aber weigerte sich, ihn zu schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Da sprach er zu ihm: Darum, daß du der Stimme des HERRN nicht hast gehorchet, siehe, so wird dich ein Lowe schlagen, wenn du von mir gehest. Und da er von ihm abging, fand ihn ein Lowe und schlug ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Und erfand einen andern Mann und sprach: Lieber, schlage mich! Und der Mann schlug ihn wund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Da ging der Prophet hin und trat zum Konige an den Weg und verstellete sein Angesicht mit Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Und da der Konig voruberzog, schrie er den Konig an und sprach: Dein Knecht war ausgezogen mitten im Streit. Und siehe, ein Mann war gewichen und brachte einen Mann zu mir und sprach: Verwahre diesen Mann; wo man sein wird missen, so soil deine Seele anstatt seiner Seele sein, Oder sollst einen Zentner Silbers darwagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Und da dein Knecht hie und da zu tun hatte, war der nicht mehr da. Der Konig Israels sprach zu ihm: Das ist dein Urteil, du hast es selbst gefallet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Da tat er eilend die Asche von seinem Angesicht; und der Konig Israels kannte ihn, daß er der Propheten einer war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Und er sprach zu ihm: So spricht der HERR: Darum, dafi du hast den verbannten Mann von dir gelassen, wird deine Seele fur seine Seele sein und dein Volk fur sein Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Aber der Konig Israels zog hin Unmuts und zornig in sein Haus und kam gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Nach diesen Geschichten begab sich\'s, dafi Naboth, ein Jesreeliter, einen Weinberg hatte zu Jesreel, bei dem Palast Ahabs, des Konigs zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Und Ahab redete mit Naboth und sprach: Gib mir deinen Weinberg, ich will mir einen Kohlgarten draus machen, weil erso nahe an meinem Hause liegt. Ich will dir einen bessern Weinberg dafur geben; Oder, so dir\'s gefallt, will ich dir Silber dafur geben, so viel er gilt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Aber Naboth sprach zu Ahab: Das lasse der HERR feme von mir sein, daß ich dir meiner Vater Erbe sollte geben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Da kam Ahab heim Unmuts und zornig um des Worts willen, das Naboth, der Jesreeliter, zu ihm hatte gesagt und gesprochen: Ich will dir meiner Vater Erbe nicht geben. Und er legte sich auf sein Bett und wandte sein Antlitz und aft kein Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Da kam zu ihm hinein Isebel, sein Weib, und redete mit ihm: Was ist\'s, daß dein Geist so Unmuts ist und daü du nicht Brot issest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Er sprach zu ihr: Ich habe mit Naboth, dem Jesreeliten, geredet und gesagt: Gib mir deinen Weinberg um Geld; Oder, so du Lust dazu hast, will ich dir einen andern dafur geben. Er aber sprach: Ich will dir meinen Weinberg nicht geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Da sprach Isebel, sein Weib, zu ihm: Was ware fur ein Konigreich in Israel, wenn du so tatest? Stehe auf und ili Brot und sei gutes Muts! Ich will dir den Weinberg Naboths, des Jesreeliten, verschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Und sie schrieb Briefe unter Ahabs Namen und versiegeite sie mit seinem Petschier; und sandte sie zu den Altesten und Obersten in seiner Stadt, die um Naboth wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Und schrieb also in den Briefen: Lasset ein Fasten ausschreien und setzet Naboth oben an im Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Und stelletzween loser Buben vor ihn, die da zeugen und sprechen: Du hast Gott und dem Konige gesegnet. Und fuhret ihn hinaus und steiniget ihn, daü er sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Und die Altesten und Obersten seiner Stadt, die in seiner Stadt wohneten, taten, wie ihnen Isebel entboten hatte, wie sie in den Briefen geschrieben hatte, die sie zu ihnen sandte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Und lieften ein Fasten ausschreien und lieften Naboth obenan unter dem Volk sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Da kamen die zween losen Buben und stelleten sich vor ihn und zeugten wider Naboth vor dem Volk und sprachen: Naboth hat Gott und dem Konige gesegnet. Da fuhreten sie ihn vor die Stadt hinaus und steinigten ihn, daß erstarb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Und sie entboten Isebel und lieften ihr sagen: Naboth ist gesteiniget und tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Da aber Isebel horete, daß Naboth gesteiniget und tot war, sprach sie zu Anab: Stehe auf und nimm ein den Weinberg Naboths, des Jesreeliten, welchen er sich weigerte, dir um Geld zu geben. Denn Naboth lebt nimmer, sondern ist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Da Ahab horete, daß Naboth tot war, stund er auf, daß er hinabginge zum Weinberge Naboths, des Jesreeliten, und ihn einnahme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Aber das Wort des HERRN kam zu Elia, dem Thisbiten, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Mache dich auf und gehe hinab Ahab, dem Konige Israels, entgegen, der zu Samaria ist. (Siehe, er ist im Weinberge Naboths, dahin er ist hinabgegangen, da(5 er ihn einnehme.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Und rede mitihm und sprich: So sprichtder HERR: Du hast totgeschlagen, dazu auch eingenommen. Und sollst mit ihm reden und sagen: So spricht der HERR: An der Statte, da Hunde das Blut Naboths geleckt haben, sollen auch Hunde dein Blut lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Und Ahab sprach zu Elia: Hast du mich je deinen Feind erfunden? Er aber sprach: Ja, ich habe dich funden, darum daß du verkauft bist, nur Ubels zu tun vordem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Siehe, ich will Unglück über dich bringen und deine Nachkommen wegnehmen; und will von Ahab ausrotten auch den, der an die Wand pisset und der verschlossen und ubergelassen ist in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Und will dein Haus machen wie das Haus Jerobeams, des Sohns Nebats, und wie das Haus Baesas, des Sohns Ahias, um des Reizens willen, damit du erzurnet und Israel sundigen gemacht hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Und liber Isebel redete der HERR auch und sprach: Die Hunde sollen Isebel fressen an der Mauer Jesreels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Wer von Ahab stirbt in der Stadt, den sollen die Hunde fressen; und wer auf dem Felde stirbt, den sollen die Vogel unter dem Himmel fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Also war niemand, der so gar verkauft ware, ubel zu tun vor dem HERRN, als Ahab; denn sein Weib Isebel überredete ihn also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Und er machte sich zum groften Greuel, daß er den Gotzen nachwandelte, allerdinge, wie die Amoriter getan hatten, die der HERR vor den Kindern Israel vertrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Da aber Ahab solche Worte horete, zerrift er seine Kleider und legte einen Sack an seinen Leib und fastete und schlief im Sack und ging jammerlich einher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Und das Wort des HERRN kam zu Elia, dem Thisbiten, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Hast du nicht gesehen, wie sich Ahab vor mir bückete? Weil er sich nun vor mir bückete, will ich das Unglück nicht einfuhren bei seinem Leben; aber bei seines Sohnes Leben will ich Unglück über sein Haus führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Und es kamen drei Jahre um, daß kein Krieg war zwischen den Syrern und Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Im dritten Jahr aber zog Josaphat, der Konig Judas, hinab zum Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Und der Konig Israels sprach zu seinen Knechten: Wisset ihr nicht, daß Ramoth in Gilead unser ist; und wir sitzen stille und nehmen sie nicht von der Hand des Konigs zu Syrien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Und sprach zu Josaphat: Willst du mit mir ziehen in den Streit gen Ramoth in Gilead? Josaphat sprach zum Konige Israels: Ich will sein wie du und mein Volk wie dein Volk und meine Rosse wie deine Rosse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Und Josaphat sprach zum Konige Israels: Frage doch heute um das Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Da sammelte der Konig Israels Propheten bei vierhundert Mann und sprach zu ihnen: Soil ich gen Ramoth in Gilead ziehen zu streiten, Oder soil ich\'s lassen anstehen? Sie sprachen: Zeuch hinauf, der HERR wird\'s in die Hand des Konigs geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Josaphat aber sprach: Ist hie kein Prophet mehr des HERRN, daß wir von ihm fragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Der Konig Israels sprach zu Josaphat: Es ist noch ein Mann, Micha, der Sohn Jemlas, von dem man den HERRN fragen mag. Aber ich bin ihm gram; denn erweissaget mir kein Gutes, sondern eitel Boses. Josaphat sprach: Der Konig rede nicht also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Da rief der Konig Israels einem Kammerer und sprach: Bringe eilend her Micha, den Sohn Jemlas!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Der Konig aber Israels und Josaphat, der Konig Judas, saften ein jeglicher auf seinem Stuhl, angezogen mit Kleidern, auf dem Platz vor der Tur am Tor Samarias; und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Und Zedekia, der Sohn Knaenas, hatte ihm eiserne Horner gemacht und sprach: So spricht der HERR: Hiemit wirst du die Syrer stoften, bis du sie aufraumest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Und alle Propheten weissagten also und sprachen: Zeuch hinauf gen Ramoth in Gilead und fahre gluckselig; der HERR wird\'s in die Hand des Konigs geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Und der Bote, der hingegangen war, Micha zu rufen, sprach zu ihm: Siehe, der Propheten Reden sind eintrachtiglich gut fur den Konig; so laft nun dein Wort auch sein wie das Wort derselben und rede Gutes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micha sprach: So wahr der HERR lebet, ich will reden, was der HERR mir sagen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Und da erzum Konige kam, sprach der Konig zu ihm: Micha, sollen wir gen Ramoth in Gilead ziehen zu streiten, Oder sollen wir\'s lassen anstehen? Er sprach zu ihm: Ja, zeuch hinauf und fahre gluckselig; der HERR wird\'s in die Hand des Konigs geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Der Konig sprach abermal zu ihm: Ich beschwore dich, daß du mir nicht anders sagest denn die Wahrheit im Namen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Er sprach: Ich sah ganz Israel zerstreuet auf den Bergen wie die Schafe, die keinen Hirten haben. Und der HERR sprach: Haben diese keinen Herrn? Ein jeglicher kehre wieder heim mit Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Da sprach der Konig Israels zu Josaphat: Habe ich dir nicht gesagt, daß er mir nichts Gutes weissaget, sondern eitel Boses?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Er sprach: Darum hore nun das Wort des HERRN. Ich sah den HERRN sitzen auf seinem Stuhl und alles himmlische Heer neben ihm stehen zu seiner Rechten und Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Und der HERR sprach: Wer will Ahab überreden, daß er hinaufziehe und falle zu Ramoth in Gilead? Und einer sagte dies, der andere das.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Da ging ein Geist heraus und trat vor den HERRN und sprach: Ich will ihn uberreden. Der HERR sprach zu ihm: Womit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Er sprach: Ich will ausgehen und will ein falscher Geist sein in aller seiner Propheten Munde. Er sprach: Du sollst ihn uberreden und sollst es ausrichten; gehe aus und tue also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Nun siehe, der HERR hat einen falschen Geist gegeben in aller dieser deiner Propheten Mund; und der HERR hat Boses uber dich geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Da trat herzu Zedekia, der Sohn Knaenas, und schlug Micha auf den Backen und sprach: Wie? 1st der Geist des HERRN von mir gewichen, daß er mit dir redet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micha sprach: Siehe, du wirst\'s sehen an dem Tage, wenn du von einer Kammer in die andere gehen wirst, daß du dich verkriechest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Der Konig Israels sprach: Nimm Micha und laß ihn bleiben bei Amon, dem Burgermeister, und bei Joas, dem Sohn des Konigs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'und sprich: So spricht der Konig: Diesen setzet ein in den Kerker und speiset ihn mit Brot und Wasser der Trubsal, bis ich mit Frieden wiederkomme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Micha sprach: Kommst du mit Frieden wieder, so hat der HERR nicht durch mich geredet. Und sprach: Horet zu, alles Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Also zog der Konig Israels und Josaphat, der Konig Judas, hinauf gen Ramoth in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Und der Konig Israels sprach zu Josaphat: Verstelle dich und komm in den Streit mit deinen Kleidern angetan. Der Konig Israels aber verstellete sich auch und zog in den Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Aber der Konig zu Syrien gebot den Obersten uber seine Wagen, der waren zweiunddreifüg, und sprach: Ihr sollt nicht streiten wider Kleine noch Grolie, sondern wider den Konig Israels allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Und da die Obersten der Wagen Josaphat sahen, meineten sie, er ware der Konig Israels, und fielen auf ihn mit Streiten; aber Josaphat schrie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Da aber die Obersten der Wagen sahen, daß er nicht der Konig Israels war, wandten sie sich hinten von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Ein Mann aber spannete den Bogen ohngefahr und scholi den Konig Israels zwischen den Panzer und Hengel. Und er sprach zu seinem Fuhrmann: Wende deine Hand und fuhre mich aus dem Heer, denn ich bin wund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Und der Streit nahm uberhand desselben Tages; und der Konig stund auf dem Wagen gegen die Syrer und starb des Abends. Und das Blut floli von den Wunden mitten in den Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Und man lieli ausrufen im Heer, da die Sonne unterging, und sagen: Ein jeglicher gehe in seine Stadt und in sein Land!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Also starb der Konig und ward gen Samaria gebracht. Und sie begruben ihn zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Und da sie den Wagen wuschen bei dem Teiche Samarias, leckten die Hunde sein Blut (es wuschen ihn aber die Huren) nach dem Wort des HERRN, das er geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Was mehr von Ahab zu sagen ist, und alles, was er getan hat, und das elfenbeinerne Haus, das er bauete, und alle Stadte, die er gebauet hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Also entschlief Ahab mit seinen Vatern; und sein Sohn Ahasja ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Und Josaphat, der Sohn Assas, ward Konig uber Juda im vierten Jahr Ahabs, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Und war funfunddreifüg Jahre alt, da er Konig ward, und regierte fünfundzwanzig Jahre zu Jerusalem. Seine Mutter hiefi Asuba, eine Tochter Silhis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Und wandelte in allem Wege seines Vaters Assa und wich nicht davon; und er tat, das dem HERRN wohlgefiel. Doch tat er die Hohen nicht weg, und das Volk opferte und raucherte noch auf den Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Und hatte Frieden mit dem Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Was aber mehr von Josaphat zu sagen ist, und die Macht, was er getan, und wie er gestritten hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Auch tat er aus dem Lande, was noch übriger Hurer waren, die zu der Zeit seines Vaters Assa waren uberblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Und es war kein Konig in Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Und Josaphat hatte Schiffe lassen machen aufs Meer, die in Ophir gehen sollten, Gold zu holen. Aber sie gingen nicht; denn sie wurden zerbrochen zu Ezeon-Geber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Dazumal sprach Ahasja, der Sohn Ahabs, zu Josaphat: Lafi meine Knechte mit deinen Knechten in Schiffen fahren. Josaphat aber wollte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Und Josaphat entschlief mit seinen Vatern und ward begraben mit seinen Vatern in der Stadt Davids, seines Vaters; und Joram, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Ahasja, der Sohn Ahabs, ward Konig uber Israel zu Samaria im siebenzehnten Jahr Josaphats, des Konigs Judas, und regierte uber Israel zwei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Und tat, das dem HERRN übel gefiel, und wandelte in dem Wege seines Vaters und seiner Mutter und in dem Wege Jerobeams, des Sohns Nebats, der Israel sündigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Und dienete Baal und betete ihn an; und erzürnete den HERRN, den Gott Israels, wie sein Vater tat. Das zweite Buch von den Konigen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Auch fielen die Moabiter ab von Israel, da Ahab tot war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Und Ahasja fiel durchs Gitter in seinem Saal zu Samaria und ward krank; und sandte Boten und sprach zu ihnen: Gehet hin und fraget Baal-Sebub, den Gott zu Ekron, ob ich von dieser Krankheit genesen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Aber der Engel des HERRN redete mit Elia, dem Thisbiten: Auf! und begegne den Boten des Konigs zu Samaria und sprich zu ihnen: 1st denn nun kein Gott in Israel, dail ihr hingehet zu fragen Baal-Sebub, den Gott zu Ekron?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Darum so spricht der HERR: Du sollst nicht von dem Bette kommen, darauf du dich geleget hast, sondern sollst des Todes sterben. Und Elia ging weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Und da die Boten wiederzu ihm kamen, sprach er zu ihnen: Warum kommt ihr wieder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Sie sprachen zu ihm: Es kam uns ein Mann herauf entgegen und sprach zu uns: Gehet wiederum hin zu dem Konige, dereuch gesandt hat, und sprechet zu ihm: So spricht der HERR: 1st denn kein Gott in Israel, dafi du hinsendest, zu fragen Baal- Sebub, den Gott zu Ekron? Darum sollst du nicht kommen von dem Bette, darauf du dich geleget hast, sondern sollst des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Er sprach zu ihnen: Wie war der Mann gestaltet, der euch begegnete und solches zu euch sagte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Sie sprachen zu ihm: Er hatte eine rauche Haut an und einen ledernen Gürtel urn seine Lenden. Er aber sprach: Es ist Elia, der Thisbiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Und er sandte hin zu ihm einen Hauptmann uber funfzig samt denselben Funfzigen. Und da der zu ihm hinaufkam, siehe, da safi eroben auf dem Berge. Er aber sprach zu ihm: Du Mann Gottes, der Konig sagt: Du sollst herabkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elia antwortete dem Hauptmann uber funfzig und sprach zu ihm: Bin ich ein Mann Gottes, so falle Feuervom Himmel und fresse dich und deine Funfzig. Da fiel Feuer vom Himmel und frafi ihn und seine Funfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Und er sandte wiederum einen andern Hauptmann uber funfzig zu ihm samt seinen Funfzigen. Der antwortete und sprach zu ihm: Du Mann Gottes, so spricht der Konig: Komm eilends herab!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elia antwortete und sprach: Bin ich ein Mann Gottes, so falle Feuer vom Himmel und fresse dich und deine Funfzig. Da fiel das Feuer Gottes vom Himmel und frail ihn und seine Funfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Da sandte er wiederum den dritten Hauptmann uber funfzig samt seinen Funfzigen. Da derzu ihm hinaufkam, beugte er seine Kniee gegen Elia und flehete ihm und sprach zu ihm: Du Mann Gottes, lail meine Seele und die Seele deiner Knechte, dieser Funfzig, vor dir etwas gelten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Siehe, das Feuer ist vom Himmel gefallen und hat die ersten zween Hauptmanner uber funfzig mit ihren Funfzigen gefressen; nun aber lail meine Seele etwas gelten vor dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Da sprach der Engel des HERRN zu Elia: Gehe mit ihm hinab und furchte dich nicht vor ihm! Und er machte sich auf und ging mit ihm hinab zum Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Und er sprach zu ihm: So spricht der HERR: Darum, dad du hast Boten hingesandt und lassen fragen Baal-Sebub, den Gott zu Ekron, als ware kein Gott in Israel, des Wort man fragen mochte, so sollst du von dem Bette nicht kommen, darauf du dich geleget hast, sondern sollst des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Also starb er nach dem Wort des H ERRN, das Elia geredet hatte. Und Joram ward Konig an seiner Statt im andern Jahr Jorams, des Sohns Josaphats, des Konigs Judas; denn er hatte keinen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Was aber mehr von Ahasja zu sagen ist, das er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Da aber der HERR wollte Elia im Wetter gen Himmel holen, ging Elia und Elisa von Gilgal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Und Elia sprach zu Elisa: Lieber, bleib hie; denn der HERR hat mich gen Bethel gesandt. Elisa aber sprach: So wahr der HERR lebet und deine Seele, ich verlasse dich nicht. Und da sie hinab gen Bethel kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'gingen der Propheten Kinder, die zu Bethel waren, heraus zu Elisa und sprachen zu ihm: Weillest du auch, dail der HERR wird deinen HERRN heute von deinen Haupten nehmen? Eraber sprach: Ich weifi es auch wohl; schweiget nur stille!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Und Elia sprach zu ihm: Elisa, Lieber, bleib hie; denn der HERR hat mich gen Jericho gesandt. Er aber sprach: So wahr der HERR lebet und deine Seele, ich verlasse dich nicht. Und da sie gen Jericho kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'traten der Propheten Kinder, die zu Jericho waren, zu Elisa und sprachen zu ihm: Weillest du auch, dail der HERR wird deinen Herrn heute von deinen Haupten nehmen? Er aber sprach: Ich weill es auch wohl; schweiget nur stille!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Und Elia sprach zu ihm: Lieber, bleib hie; denn der HERR hat mich gesandt an den Jordan. Er aber sprach: So wahr der HERR lebet und deine Seele, ich verlasse dich nicht. Und gingen die beiden miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Aber funfzig Manner unter der Propheten Kindern gingen hin und traten gegenuber von feme; aber die beiden stunden am Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Da nahm Elia seinen Mantel und wickelte ihn zusammen und schlug ins Wasser; das teilete sich auf beiden Seiten, dail die beiden trocken durchhin gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Und da sie hinüberkamen, sprach Elia zu Elisa: Bitte, was ich dir tun soil, ehe ich von dir genommen werde. Elisa sprach: Dali dein Geist bei mir sei zwiefaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Er sprach: Du hastein Hartes gebeten; doch so du mich sehen wirst, wenn ich von dir genommen werde, so wird\'s ja sein; wo nicht, so wird\'s nicht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Und da sie miteinander gingen, und er redete, siehe, da kam ein feuriger Wagen mit feurigen Rossen, und schieden die beiden voneinander; und Elia fuhr also im Wetter gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Elisa aber sah es und schrie: Mein Vater, mein Vater, Wagen Israels und seine Reiter! Und sah ihn nicht mehr. Und er fassete seine Kleider und zerrifi sie in zwei Stucke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Und hub auf den Mantel Elias, der ihm entfallen war; und kehrete um und trat an das Ufer des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Und nahm denselben Mantel Elias, der ihm entfallen war, und schlug ins Wasser und sprach: Wo ist nun der HERR, der Gott Elias? Und schlug ins Wasser; da teilete sich\'s auf beiden Seiten; und Elisa ging hindurch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Und da ihn sahen der Propheten Kinder, die zu Jericho gegen ihm waren, sprachen sie: Der Geist Elias ruhet auf Elisa; und gingen ihm entgegen und beteten an zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Und sprachen zu ihm: Siehe, es sind unter deinen Knechten funfzig Manner, starke Leute, die lad gehen und deinen Herrn suchen; vielleicht hat ihn der Geist des HERRN genommen und irgend aufeinen Berg, Oder irgend in ein Tal geworfen. Er aber sprach: Lasset nicht gehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Aber sie notigten ihn, bis daü ersich ungebardig stellete und sprach: Lasset hingehen! Und sie sandten hin funfzig Manner und suchten ihn drei Tage; aber sie fanden ihn nicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'und kamen wiederzu ihm. Und er blieb zu Jericho und sprach zu ihnen: Sagte ich euch nicht, ihr solltet nicht hingehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Und die Manner der Stadt sprachen zu Elisa: Siehe, es ist gut wohnen in dieser Stadt, wie mein Herr siehet; aber es ist boses Wasser und das Land unfruchtbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Er sprach: Bringet mir her eine neue Schale und tut Saiz drein. Und sie brachten es ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Da ging er hinaus zu der Wasserquelle und warf das Saiz drein und sprach: So spricht der HERR: Ich habe dies Wasser gesund gemacht; es soil hinfort kein Tod noch Unfruchtbarkeit daher kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Also ward das Wasser gesund bis auf diesen Tag nach dem Wort Elisas, das er redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Und er ging hinauf gen Bethel. Und als er auf dem Wege hinanging, kamen kleine Knaben zur Stadt heraus und spotteten ihn und sprachen zu ihm: Kahlkopf, komm herauf! Kahlkopf, komm herauf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Und er wandte sich um, und da er sie sah, fluchte er ihnen im Namen des HERRN. Da kamen zween Baren aus dem Walde und zerrissen der Kinder zweiundvierzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Von dannen ging er auf den Berg Karmel und kehrete um von dannen gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram, der Sohn Ahabs, ward Konig fiber Israel zu Samaria im achtzehnten Jahr Josaphats, des Konigs Judas; und regierte zwolf Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Und tat, das dem HERRN übel gefiel, doch nicht wie sein Vater und seine Mutter. Denn er tat weg die Saule Baals, die sein Vater machen liefi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Aber er blieb hangen an den Sünden Jerobeams, des Sohns Nebats, der Israel sundigen machte, und lied nicht davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mesa aber, der Moabiter Konig, hatte viel Schafe und zinsete dem Konige Israels Wolle von hunderttausend Lammern und von hunderttausend Widdern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Da aber Ahab tot war, fiel der Moabiter Konig ab vom Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Da zog zu derselben Zeit aus der Konig Joram von Samaria und ordnete das ganze Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Und sandte hin zu Josaphat, dem Konige Judas, und lied ihm sagen: Der Moabiter Konig ist von mir abgefallen; komm mit mir, zu streiten wider die Moabiter! Er sprach: Ich will hinaufkommen; ich bin wie du und mein Volk wie dein Volk und meine Rosse wie deine Rosse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Und sprach: Durch welchen Weg wollen wir hinaufziehen? Er sprach: Durch den Weg in der Wüste Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Also zog hin der Konig Israels, der Konig Judas und der Konig Edoms. Und da sie sieben Tagreisen zogen, hatte das Heer und das Vieh, das unter ihnen war, kein Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Da sprach der Konig Israels: O wehe! Der HERR hat diese drei Konige geladen, daß er sie in der Moabiter Hande gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Josaphat aber sprach: Ist kein Prophet des HERRN hie, dadwirden HERRN durch ihn ratfragten? Da antwortete einer unter den Knechten des Konigs Israels und sprach: Hie ist Elisa, der Sohn Saphats, der Elia Wasser auf die Hande god.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat sprach: Des HERRN Wort ist bei ihm. Also zogen zu ihm hinab der Konig Israels und Josaphat und der Konig Edoms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Elisa aber sprach zum Konige Israels: Was hast du mit mir zu schaffen? Gehe hin zu den Propheten deines Vaters und zu den Propheten deiner Mutter! Der Konig Israels sprach zu ihm: Nein; denn der HERR hat diese drei Konige geladen, dad er sie in der Moabiter Hande gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sprach: So wahr der HERR Zebaoth lebet, vor dem ich stehe, wenn ich nicht Josaphat, den Konig Judas, ansahe, ich wollte dich nicht ansehen noch achten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'So bringet mir nun einen Spielmann. Und da der Spielmann auf der Saite spielte, kam die Hand des HERRN auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Und ersprach: So spricht der HERR: Machet hie und da Graben an diesem Bach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Denn so spricht der HERR: Ihr werdet keinen Wind noch Regen sehen; dennoch soil der Bach voll Wassers werden, daß ihr und euer Gesinde und euer Vieh trinket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Dazu istdas ein Geringes vor dem HERRN, er wird auch die Moabiter in eure Hande geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'dafi ihr schlagen werdet alle festen Stadte und alle auserwahlten Stadte; und werdet fallen alle guten Baume und werdet verstopfen alle Wasserbrunnen und werdet alien guten Acker mit Steinen verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Des Morgens aber, wenn man Speisopfer opfert, siehe, da kam ein Gewasser des Weges von Edom und füllete das Land mit Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Da aber alle Moabiter horeten, dafi die Konige heraufzogen, wider sie zu streiten, beriefen sie alle, die zur Rustung alt genug und druber waren, und traten an die Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Und da sie sich des Morgens frühe aufmachten, und die Sonne aufging auf das Gewasser, deuchte die Moabiter das Gewasser gegen ihnen rot sein wie Blut;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'und sprachen: Es ist Blut; die Konige haben sich mit dem Schwert verderbet, und einer wird den andern geschlagen haben. Hui, Moab, mache dich nun zur Ausbeute!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Aber da sie zum Lager Israels kamen, machte sich Israel auf und schlugen die Moabiter; und sie flohen vor ihnen. Aber sie kamen hinein und schlugen Moab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Die Stadte zerbrachen sie, und ein jeglicher warf seine Steine auf alle guten Acker und machten sie voll; und verstopften alle Wasserbrunnen und falleten alle guten Baume, bis daß nur die Steine an den Ziegelmauern uberblieben; und sie umgaben sie mit Schleudern und schlugen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Da aber der Moabiter Konig sah, dafi ihm der Streit zu stark war, nahm er siebenhundert Mann zu sich, die das Schwert auszogen, herauszureißen wider den Konig Edoms; aber sie konnten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Da nahm er seinen ersten Sohn, der an seiner Statt sollte Konig werden, und opferte ihn zum Brandopfer auf der Mauer. Da ward Israel sehr zornig, daß sie von ihm abzogen, und kehreten wieder zu Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Und es schrie ein Weib unter den Weibern der Kinder der Propheten zu Elisa und sprach: Dein Knecht, mein Mann, ist gestorben; so weifit du, daß er, dein Knecht, den HERRN furchtete; nun kommt der Schuldherr und will meine beiden Kinder nehmen zu eigenen Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sprach zu ihr: Was soil ich dir tun? Sage mir, was hast du im Hause? Sie sprach: Deine Magd hat nichts im Hause denn einen Olkrug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Er sprach: Gehe hin und bitte draulien von alien deinen Nachbarinnen leere Gefalie, und derselben nicht wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Und gehe hinein und schleuli die Tur hinter dir zu mit deinen Sohnen und geuli in alle Gefalie; und wenn du sie gefullet hast, so gib sie hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Sie ging hin und schloli die Tur hinter ihr zu samt ihren Sohnen; die brachten ihr die Gefalie zu, so gofi sie ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Und da die Gefalie voll waren, sprach sie zu ihrem Sohn: Lange mir noch ein Gefali her! Ersprach zu ihr: Es ist kein Gefali mehr hie. Da stund das 01.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Und sie ging hin und sagte es dem Mann Gottes an. Er sprach: Gehe hin, verkaufe das 01 und bezahle deinen Schuldherm; du aber und deine Sohne nahret euch von dem ubrigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Und es begab sich zu der Zeit, daß Elisa ging gen Sunem. Daselbst war eine reiche Frau; die hielt ihn, daß er bei ihr ali. Und als er nun oft daselbst durchzog, ging erzu ihr ein und ali bei ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Und sie sprach zu ihrem Manne: Siehe, ich merke, daß dieser Mann Gottes heilig ist, der immerdar hie durchgehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Lafi uns ihm eine kleine bretterne Kammer oben machen und ein Bett, Tisch, Stuhl und Leuchter hineinsetzen, auf daß, wenn er zu uns kommt, dahin sich tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Und es begab sich zu der Zeit, daß er hineinkam und legte sich oben in die Kammer und schlief drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Und sprach zu seinem Knaben Gehasi: Rufe der Sunamitin! Und da er ihr rief, trat sie vor ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Er sprach zu ihm: Sage ihr: Siehe, du hast uns all diesen Dienst getan; was soil ich dir tun? Hast du eine Sache an den Konig Oder an den Feldhauptmann? Sie sprach: Ich wohne unter meinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Er sprach: Was ist ihr denn zu tun? Gehasi sprach: Ach, sie hat keinen Sohn, und ihr Mann ist alt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Ersprach: Rufe ihr! Und da er ihr rief, trat sie in die Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Und ersprach: Urn diese Zeit uber ein Jahrsollst du einen Sohn herzen. Sie sprach: Ach nicht, mein Herr, du Mann Gottes, luge deiner Magd nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Und die Frau ward schwanger und gebar einen Sohn urn dieselbe Zeit uber ein Jahr, wie ihr Elisa geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Da aber das Kind groli ward, begab sich\'s, daß es hinaus zu seinem Vater zu den Schnittern ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Und sprach zu seinem Vater: 0 mein Haupt, mein Haupt! Er sprach zu seinem Knaben: Bringe ihn zu seiner Mutter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Und er nahm ihn und brachte ihn hinein zu seiner Mutter; und sie setzte ihn auf ihren Scholi bis an den Mittag; da starb er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Und sie ging hinauf und legte ihn aufs Bett des Mannes Gottes, schlofi zu und ging hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Und rief ihrem Mann und sprach: Sende mir der Knaben einen und eine Eselin; ich will zu dem Mann Gottes und wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Er sprach: Warum willst du zu ihm? 1st doch heute nicht Neumond noch Sabbat. Sie sprach: Es ist gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Und sie sattelte die Eselin und sprach zum Knaben: Treibe fort und saume mich nicht mit dem Reiten, wie ich dir sage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Also zog sie hin und kam zu dem Mann Gottes auf den Berg Karmel. Als aber der Mann Gottes sie gegen ihm sah, sprach erzu seinem Knaben Gehasi: Siehe, die Sunamitin ist da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'So lauf ihr nun entgegen und frage sie, ob\'s ihr und ihrem Mann und Sohn wohlgehe? Sie sprach: Wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Da sie aber zu dem Mann Gottes auf den Berg kam, hielt sie ihn bei seinen Fufien; Gehasi aber trat herzu, daß er sie abstiefte. Aber der Mann Gottes sprach: Laft sie, denn ihre Seele ist betrubt; und der HERR hat mir\'s verborgen und nicht angezeiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Sie sprach: Wann habe ich einen Sohn gebeten von meinem Herrn? Sagte ich nicht, du solltest mich nicht tauschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Er sprach zu Gehasi: Gurte deine Lenden und nimm meinen Stab in deine Hand und gehe hin (so dir jemand begegnet, so grufte ihn nicht, und gruftet dich jemand, so danke ihm nicht) und lege meinen Stab auf des Knaben Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Die Mutter aber des Knaben sprach: So wahr der HERR lebet und deine Seele, ich lasse nicht von dir. Da machte er sich auf und ging ihr nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehasi aber ging vor ihnen hin und legte den Stab dem Knaben aufs Antlitz; da war aber keine Stimme noch Fuhlen. Und erging wiederum ihm entgegen und zeigte ihm an und sprach: Der Knabe ist nicht aufgewacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Und da Elisa ins Haus kam, siehe, da lag der Knabe tot auf seinem Bette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Und er ging hinein und schloft die Tur zu fur sie beide und betete zu dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Und stieg hinauf und legte sich auf das Kind und legte seinen Mund auf des Kindes Mund und seine Augen auf seine Augen und seine Hande auf seine Hande; und breitete sich also über ihn, daß des Kindes Leib warm ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Er aber stund wieder auf und ging im Hause einmal hieher und daher; und stieg hinauf und breitete sich uber ihn. Da schnaubte der Knabe siebenmal; danach tat der Knabe seine Augen auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Und er rief Gehasi und sprach: Rufe der Sunamitin. Und da er ihr rief, kam sie hinein zu ihm. Er sprach: Da nimm hin deinen Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Da kam sie und fiel zu seinen Fuften und betete an zur Erde; und nahm ihren Sohn und ging hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Da aber Elisa wieder gen Gilgal kam, ward Teurung im Lande, und die Kinder der Propheten wohneten vor ihm. Und er sprach zu seinem Knaben: Setze zu einen groften Topf und koche ein Gemüse fur die Kinder der Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Da ging einer aufs Feld, daß er Kraut lase, und fand wilde Ranken, und las davon Koloquinten, sein Kleid voll; und da er kam, schnitt er\'s in den Topf zum Gemuse, denn sie kannten es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Und da sie es ausschutteten fur die Manner zu essen, und sie von dem Gemuse aften, schrieen sie und sprachen: 0 Mann Gottes, der Tod im Topf! Denn sie konnten\'s nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Er aber sprach: Bringet Mehl her! Und ertat\'s in den Topf und sprach: Schutte es dem Volk vor, daß sie essen. Da war nichts Boses in dem Topf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Es kam aber ein Mann von Baal-Salisa und brachte dem Mann Gottes Erstlingsbrot, namlich zwanzig Brote, und neu Getreide in seinem Kleid. Er aber sprach: Gib\'s dem Volk, daß sie essen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Sein Diener sprach: Was soil ich hundert Mann an dem geben? Er sprach: Gib dem Volk, daß sie essen! Denn so spricht der HERR: Man wird essen, und wird uberbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Und er legte es ihnen vor, daß sie aften; und blieb noch uber nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naeman, der Feldhauptmann des Konigs zu Syrien, war ein trefflicher Mann vor seinem Herrn und hoch gehalten; denn durch ihn gab der HERR Heil in Syrien. Und erwar ein gewaltiger Mann, und aussatzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Die Kriegsleute aber in Syrien waren herausgefallen und hatten eine kleine Dime weggefuhret aus dem Lande Israel; die war am Dienst des Weibes Naemans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Die sprach zu ihrer Frau: Ach, daß mein Herr ware bei dem Propheten zu Samaria, der wurde ihn von seinem Aussatz losmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Da ging er hinein zu seinem Herrn und sagte es ihm und sprach: So und so hat die Dime aus dem Lande Israel geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Der Konig zu Syrien sprach: So zeuch hin, ich will dem Konig Israels einen Brief schreiben. Und erzog hin und nahm mit sich zehn Zentner Silbers und sechstausend Gulden und zehn Feierkleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Und brachte den Brief dem Konige Israels, der lautete also: Wenn dieser Brief zu dir kommt, siehe, so wisse, ich habe meinen Knecht Naeman zu dir gesandt, daß du ihn von seinem Aussatz losmachest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Und da der Konig Israels den Brief las, zerrift er seine Kleider und sprach: Bin ich denn Gott, daß ich toten und lebendig machen konnte, daß erzu mir schicket, daß ich den Mann von seinem Aussatz losmache? Merket und sehet, wie suchet er Ursache zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Da das Elisa, der Mann Gottes, horete, daß der Konig Israels seine Kleider zerrissen hatte, sandte er zu ihm und lied, ihm sagen: Warum hast du deine Kleider zerrissen? Lad ihn zu mir kommen, dad er inne werde, dad ein Prophet in Israel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Also kam Naeman mit Rossen und Wagen und hielt vor der Tur am Hause Elisas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Da sandte Elisa einen Boten zu ihm und lied ihm sagen: Gehe hin und wasche dich siebenmal im Jordan, so wird dir dein Fleisch wiedererstattet und rein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Da erzurnete Naeman und zog weg und sprach: Ich meinte, er sollte zu mir herauskommen und hertreten und den Namen des HERRN, seines Gottes, anrufen und mit seiner Hand uber die Statte fahren und den Aussatz also abtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Sind nicht die Wasser Amanas und Pharphars zu Damaskus besser denn alle Wasser in Israel, dad ich mich drinnen wusche und rein würde? Und wandte sich und zog weg mit Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Da machten sich seine Knechte zu ihm, redeten mit ihm und sprachen: Lieber Vater, wenn dich der Prophet etwas Groftes hatte geheiden, solltest du es nicht tun? Wie viel mehr, so er zu dir sagt: Wasche dich, so wirstdu rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Da stieg er ab und taufte sich im Jordan siebenmal, wie der Mann Gottes geredet hatte; und sein Fleisch ward wiedererstattet, wie ein Fleisch eines jungen Knaben, und ward rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Und er kehrete wieder zu dem Mann Gottes samt seinem ganzen Heer. Und da er hineinkam, trat er vor ihn und sprach: Siehe, ich weid, dad kein Gott ist in alien Landen ohne in Israel; so nimm nun den Segen von deinem Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Er aber sprach: So warder HERR lebet, vor dem ich stehe, ich nehme es nicht. Und er notigte ihn, dad er\'s nahme; abererwollte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Da sprach Naeman: Mochte denn deinem Knechte nicht gegeben werden dieser Erde eine Last, so viel zwei Mauler tragen? Denn dein Knecht will nicht mehr andern Gottern opfern und Brandopfer tun, sondern dem HERRN;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'dad der HERR deinem Knechte darinnen wolle gnadig sein, wo ich anbete im Hause Rimons, wenn mein Herr ins Haus Rimons gehet, daselbst anzubeten, und ersich an meine Hand lehnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Er sprach zu ihm: Zeuch hin mit Frieden! Und als er von ihm weggezogen war, ein Feld Weges auf dem Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'gedachte Gehasi, der Knabe Elisas, des Mannes Gottes: Siehe, mein Herr hat diesen Syrer Naeman verschonet, dad er nichts von ihm hat genommen, das er gebracht hat. So wahr der HERR lebet, ich will ihm nachlaufen und etwas von ihm nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Also jagte Gehasi dem Naeman nach. Und da Naeman sah, daß er ihm nachlief, stieg er vom Wagen ihm entgegen und sprach: Gehet es rechtzu?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Er sprach: Ja. Aber mein Herr hat mich gesandt und laftt dir sagen: Siehe, jetzt sind zu mir kommen vom Gebirge Ephraim zween Knaben aus der Propheten Kindern; gib ihnen einen Zentner Silbers und zwei Feierkleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naeman sprach: Lieber, nimm zween Zentner: Und er notigte ihn und band zween Zentner Silbers in zween Beutel und zwei Feierkleider und gab\'s seinen zweien Knaben, die trugen es vor ihm her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Und da er kam gen Ophel, nahm er\'s von ihren Handen und legte es beiseit im Hause und lieft die Manner gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Und da sie weg waren, trat er vor seinen Herm. Und Elisa sprach zu ihm: Woher, Gehasi? Er sprach: Dein Knecht ist weder hieher noch daher gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Er aber sprach zu ihm: Wandelte nicht mein Herz, da der Mann umkehrete von seinem Wagen dir entgegen? War das die Zeit, Silber und Kleider zu nehmen, Olgarten, Weinberge, Schafe, Rinder, Knechte und Magde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Aber der Aussatz Naemans wird dir anhangen und deinem Samen ewiglich. Da ging ervon ihm hinaus, aussatzig wie Schnee.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Die Kinder der Propheten sprachen zu Elisa: Siehe, der Raum, da wir vor dir wohnen, ist uns zu enge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Lafi uns an den Jordan gehen und einen jeglichen daselbst Holz holen, daü wir uns daselbst eine Statte bauen, da wir wohnen. Er sprach: Gehet hin!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Und einer sprach: Lieber, gehe mit deinen Knechten! Er sprach: Ich will mitgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Und er ging mit ihnen. Und da sie an den Jordan kamen, hieben sie Holz ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Und da einer ein Holz fallete, fiel das Eisen ins Wasser. Und erschrie und sprach: Awe, mein Herr! Dazu ist\'s entlehnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Aber der Mann Gottes sprach: Wo ist\'s entfallen? Und da er ihm den Ort zeigte, schnitt er ein Holz ab und stiefi daselbst hin. Da schwamm das Eisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Und er sprach: Hebe es auf! Da reckte er seine Hand aus und nahm\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Und der Konig aus Syrien führete einen Krieg wider Israel und beratschlagte sich mit seinen Knechten und sprach: Wir wollen uns lagern da und da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Aber der Mann Gottes sandte zum Konige Israels und lieft ihm sagen: Hute dich, daß du nicht an den Ort ziehest; denn die Syrer ruhen daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'So sandte denn der Konig Israels hin an den Ort, den ihm der Mann Gottes sagte, verwahrete ihn und hütete daselbst; und tat das nicht einmal Oder zweimal allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Da ward das Herz des Konigs zu Syrien Unmuts darüber und rief seinen Knechten und sprach zu ihnen: Wollt ihr mir denn nicht ansagen, wer ist aus den Unsern zu dem Konige Israels geflohen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Da sprach seiner Knechte einer: Nicht also, mein Herr Konig; sondern Elisa, der Prophet in Israel, sagt es alles dem Konige Israels, was du in der Kammer redest, da dein Lager ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Ersprach: So gehet hin und sehet, wo er ist, daß ich hinsende und lasse ihn holen. Und sie zeigten ihm an und sprachen: Siehe, er ist zu Dothan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Da sandte er hin Rosse und Wagen und eine grolie Macht. Und da sie bei der Nacht hinkamen, umgaben sie die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Und der Diener des Mannes Gottes stund frühe auf, da($ er sich aufmachte und auszoge; und siehe, da lag eine Macht um die Stadt mit Rossen und Wagen. Da sprach sein Knabe zu ihm: Awe, mein Herr! Wie wollen wir nun tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Ersprach: Furchte dich nicht; denn derer ist mehr, die bei uns sind, denn derer, die bei ihnen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Und Elisa betete und sprach: HERR, offne ihm die Augen, daß er sehe! Da offnete der HERR dem Knaben seine Augen, daß er sah; und siehe, da war der Berg voll feuriger Rosse und Wagen um Elisa her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Und da sie zu ihm hinabkamen, bat Elisa und sprach: HERR, schlage dies Volk mit Blindheit! Und er schlug sie mit Blindheit nach dem Wort Elisas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Und Elisa sprach zu ihnen: Dies ist nicht der Weg noch die Stadt. Folget mir nach; ich will euch führen zu dem Mann, den ihr suchet. Und fuhrete sie gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Und da sie gen Samaria kamen, sprach Elisa: HERR, offne diesen die Augen, daß sie sehen! Und der HERR offnete ihnen die Augen, dafi sie sahen; und siehe, da waren sie mitten in Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Und der Konig Israels, da er sie sah, sprach er zu Elisa: Mein Vater, soil ich sie schiagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Er sprach: Du sollst sie nicht schiagen. Welche du mit deinem Schwert und Bogen fahest, die schlage. Setze ihnen Brot und Wasser vor, daß sie essen und trinken; und lali sie zu ihrem Herrn ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Da ward ein groli Mahl zugerichtet. Und da sie gegessen und getrunken hatten, lieli er sie gehen, daß sie zu ihrem Herrn zogen. Seitdem kamen die Kriegsleute der Syrer nicht mehr ins Land Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Nach diesem begab sich\'s, daß Benhadad, der Konig zu Syrien, all sein Heer versammelte und zog herauf und belagerte Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Und es war eine grolie Teurung zu Samaria. Sie aber belagerten die Stadt, bis daß ein Eselskopf achtzig Silberlinge und ein Vierteil Kad Taubenmist funf Silberlinge gait.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Und da der Konig Israels zur Mauer ging, schrie ihn ein Weib an und sprach: Hilf mir, mein Herr Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Er sprach: Hilft dir der HERR nicht, woher soil ich dir helfen? Von der Tenne Oder von der Kelter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Und der Konig sprach zu ihr: Was ist dir? Sie sprach: Dies Weib sprach zu mir: Gib deinen Sohn her, daß wir heute essen; morgen wollen wir meinen Sohn essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'So haben wir meinen Sohn gekocht und gegessen. Und ich sprach zu ihr am andern Tage: Gib deinen Sohn her und lali uns essen! Aber sie hat ihren Sohn versteckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Da der Konig die Worte des Weibes horete, zerrüi er seine Kleider, indem er zur Mauer ging. Da sah alles Volk, daü er einen Sack unten am Leibe anhatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Und er sprach: Gott tue mir dies und das, wo das Haupt Elisas, des Sohns Saphats, heute auf ihm stehen wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, '(Elisa aber sali in seinem Hause, und die Altesten saüen bei ihm.) Und er sandte einen Mann vor ihm her. Aber ehe der Bote zu ihm kam, sprach er zu den Altesten: Habt ihr gesehen, wie dies Mordkind hat hergesandt, daü er mein Haupt abreüie? Sehet zu, wenn der Bote kommt, daü ihr die Tür zuschlieüet und stoliet ihn mit der Tür weg; siehe, das Rauschen seines Herrn Fulie folget ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Da er noch also mit ihnen redete, siehe, da kam der Bote zu ihm herab und sprach: Siehe, solch Ubel kommt von dem HERRN; was soli ich mehr von dem HERRN gewarten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Elisa aber sprach: Horet des HERRN Wort! So spricht der HERR: Morgen um diese Zeit wird ein Scheffel Semmelmehl einen Sekel gelten und zween Scheffel Gerste einen Sekel unter dem Tor zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Da antwortete der Ritter, auf welches Hand sich der Konig lehnte, dem Mann Gottes und sprach: Und wenn der HERR Fenster am Himmel machte, wie konnte solches geschehen? Er sprach: Siehe da, mit deinen Augen wirst du es sehen und nicht davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Und es waren vier aussatzige Manner an der Tür vor dem Tor; und einer sprach zum andern: Was wollen wir hie bleiben, bis wir sterben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Wenn wir gleich gedachten, in die Stadt zu kommen, so ist Teurung in der Stadt, und mufiten doch daselbst sterben; bleiben wir aber hie, so müssen wir auch sterben. So lafit uns nun hingehen und zu dem Heer der Syrer fallen. Lassen sie uns leben, so leben wir; toten sie uns, so sind wir tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Und machten sich in der Fruhe auf, daß sie zum Heer der Syrer kamen. Und da sie vorne an den Ort des Heers kamen, siehe, da war niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Denn der HERR hatte die Syrer lassen horen ein Geschrei von Rossen, Wagen und groüer Heerkraft, daß sie untereinander sprachen: Siehe, der Konig Israels hat wider uns gedinget die Konige der Hethiter und die Konige der Agypter, daü sie uber uns kommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Und machten sich auf und flohen in der Fruhe; und lielien ihre Hütten, Rosse und Esel im Lager, wie es stund, und flohen mit ihrem Leben davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Als nun die Aussatzigen an den Ort des Lagers kamen, gingen sie in der Hütten eine, alien und tranken und nahmen Silber, Gold und Kleider und gingen hin und verbargen es; und kamen wieder und gingen in eine andere Hutte und nahmen draus und gingen hin und verbargen es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Aber einer sprach zum andern: Laißt uns nicht also tun! Dieser Tag ist ein Tag guter Botschaft. Wo wirdas verschweigen und harren, bis dafi licht Morgen wird, wird unsere Missetat funden werden; so lalit uns nun hingehen, daß wir kommen und ansagen dem Hause des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Und da sie kamen, riefen sie am Tor der Stadt und sagten es ihnen an und sprachen: Wir sind zum Lager der Syrer kommen, und siehe, es ist niemand da, noch keine Menschenstimme, sondern Rosse und Esei angebunden und die Hutten, wie sie stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Da rief man den Torhutern, daß sie es drinnen ansagten im Hause des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Und der Konig stand auf in der Nacht und sprach zu seinen Knechten: Lalit euch sagen, wie die Syrer mit uns umgehen. Sie wissen, dati wir Hunger leiden, und sind aus dem Lager gegangen, dafi sie sich im Felde verkrochen, und denken: Wenn sie aus der Stadt gehen, wollen wir sie lebendig greifen und in die Stadt kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Da antwortete seiner Knechte einer und sprach: Man nehme die fünf ubrigen Rosse, die noch drinnen sind uberblieben (siehe, die sind drinnen uberblieben von aller Menge in Israel, welche alle dahin ist), die lalit uns senden und besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Da nahmen sie zween Wagen mit Rossen; und der Konig sandte sie dem Lager der Syrer nach und sprach: Ziehet hin und besehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Und da sie ihnen nachzogen bis an den Jordan, siehe, da lag der Weg voll Kleider und Gerate, welche die Syrer von sich geworfen hatten, da sie eileten. Und da die Boten wiederkamen und sagten es dem Konige an,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'ging das Volk hinaus und beraubte das Lager der Syrer. Und es gait ein Scheffel Semmelmehl einen Sekel und zween Scheffel Gerste auch einen Sekel nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Aber der Konig bestellete den Ritter, auf des Hand er sich lehnte, unter das Tor. Und das Volk zertrat ihn im Tor, dafi er starb, wie der Mann Gottes geredet hatte, da der Konig zu ihm hinabkam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Und geschah, wie der Mann Gottes dem Konige sagte, da er sprach: Morgen urn diese Zeit werden zween Scheffel Gerste einen Sekel gelten und ein Scheffel Semmelmehl einen Sekel unter dem Tor zu Samaria;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'und der Ritter antwortete dem Mann Gottes und sprach: Siehe, wenn der HERR Fenster am Himmel machte, wie mdchte solches geschehen? Er aber sprach: Siehe, mit deinen Augen wirst du es sehen und nicht davon essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Und es ging ihm eben also; denn das Volk zertrat ihn im Tor, dafi er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Elisa redete mit dem Weibe, des Sohn er hatte lebendig gemacht, und sprach: Mache dich auf und gehe hin mitdeinem Hause und sei Fremdling, wo du kannst; denn der HERR wird eine Teurung rufen, die wird ins Land kommen sieben Jahre lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Das Weib machte sich auf und tat, wie der Mann Gottes sagte, und zog hin mit ihrem Hause und war Fremdling in der Philister Lande sieben Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Da aber die sieben Jahre urn waren, kam das Weib wieder aus der Philister Lande; und sie ging aus, den Konig anzuschreien urn ihr Haus und Acker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Der Konig aber redete mit Gehasi, dem Knaben des Mannes Gottes, und sprach: Erzahle mir alle grofien Taten, die Elisa getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Und indem er dem Konig erzahlte, wie er hatte einen Toten lebendig gemacht, siehe, da kam eben dazu das Weib, des Sohn er hatte lebendig gemacht, und schrie den Konig an urn ihr Haus und Acker. Da sprach Gehasi: Mein Herr Konig, dies ist das Weib, und dies ist ihr Sohn, den Elisa hat lebendig gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Und der Konig fragte das Weib; und sie erzahlte es ihm. Da gab ihr der Konig einen Kammerer und sprach: Schaffe ihr wieder alles, das ihr ist; dazu alles Einkommen des Ackers, seit der Zeit sie das Land verlassen hat, bis hieher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Und Elisa kam gen Damaskus. Da lag Benhadad, der Konig zu Syrien, krank; und man sagte es ihm an und sprach: Der Mann Gottes ist herkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Da sprach der Konig zu Hasael: Nimm Geschenk mit dir und gehe dem Mann Gottes entgegen; und frage den HERRN durch ihn und sprich, ob ich von dieser Krankheit moge genesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hasael ging ihm entgegen und nahm Geschenk mit sich und allerlei Guter zu Damaskus, vierzig Kamelen Last. Und da er kam, trat ervor ihn und sprach:. Dein Sohn Benhadad, der Konig zu Syrien, hat mich zu dir gesandt und lalit dir sagen: Kann ich auch von dieser Krankheit genesen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sprach zu ihm: Gehe hin und sage ihm: Du wirst genesen; aber der HERR hat mir gezeiget, dafi er des Todes sterben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Und der Mann Gottes sah ernst und stellete sich ungebardig und weinete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Da sprach Hasael: Warum weinet mein Herr? Er sprach: Ich weili, was Libels du den Kindern Israel tun wirst. Du wirst ihre festen Stadte mit Feuer verbrennen und ihre junge Mannschaft mit dem Schwert erwürgen und ihre jungen Kinder toten und ihre schwangeren Weiberzerhauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sprach: Was ist dein Knecht, der Hund, daß er solch groli Ding tun sollte? Elisa sprach: Der HERR hat mir gezeiget, dafi du Konig zu Syrien sein wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Und erging weg von Elisa und kam zu seinem HERRN, der sprach zu ihm: Was sagte dir Elisa? Er sprach: Er sagte mir: Du wirst genesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Des andern Tages aber nahm erden Kolter und tunkte ihn in Wasser und breitete ihn über sich her; da starb er. Und Hasael ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Im funften Jahr Jorams, des Sohns Ahabs, des Konigs Israels, ward Joram, der Sohn Josaphats, Konig in Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Zweiunddreilüg Jahre alt war er, da er Konig ward; und regierete acht Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Und wandelte auf dem Wege der Konige Israels, wie das Haus Ahabs tat; denn Ahabs Tochter war sein Weib; und ertat, das dem HERRN libel gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Aber der HERR wollte Juda nicht verderben urn seines Knechts David willen; wie er ihm geredet hatte, ihm zu geben eine Leuchte unter seinen Kindern immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Zu seiner Zeit fielen die Edomiter ab von Juda und machten einen Konig uber sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Denn Joram war durch Zair gezogen und alle Wagen mit ihm; und hatte sich des Nachts aufgemacht und die Edomiter geschlagen, die urn ihn her waren, dazu die Obersten uber die Wagen, daß das Volk floh in seine Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Darum fielen die Edomiter ab von Juda bis auf diesen Tag. Auch fiel zu derselben Zeit ab Libna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Was aber mehr von Joram zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Und Joram entschlief mit seinen Vatern und ward begraben mit seinen Vatern in der Stadt Davids. Und Ahasja sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Im zwolften Jahr Jorams, des Sohns Ahabs, des Konigs Israels, ward Ahasja, der Sohn Jorams, Konig in Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Zweiundzwanzig Jahre alt war Ahasja, da er Konig ward, und regierte ein Jahr zu Jerusalem. Seine Mutter hieti Athalja, eine Tochter Amris, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Und wandelte auf dem Wege des Hauses Ahabs und tat, das dem HERRN ubel gefiel, wie das Haus Ahabs, denn erwar Schwager im Hause Ahabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Und er zog mit Joram, dem Sohn Ahabs, in Streit wider Hasael, den Konig zu Syrien, gen Ramoth in Gilead; aber die Syrer schlugen Joram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Da kehrete Joram, der Konig, urn, daß er sich heilen lietie zu Jesreel von den Schlagen, die, ihm die Syrer geschlagen hatten zu Rama, da er mit Hasael, dem Konige zu Syrien, stritt. Und Ahasja, der Sohn Jorams, der Konig Judas, kam hinab, zu besehen Joram, den Sohn Ahabs, zu Jesreel; denn er lag krank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Elisa aber, der Prophet, rief der Propheten Kinder einem und sprach zu ihm: Gürte deine Lenden und nimm diesen Olkrug mit dir und gehe hin gen Ramoth in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Und wenn du dahin kommst, wirst du daselbst sehen Jehu, den Sohn Josaphats, des Sohns Nimsis. Und gehe hinein und heifi ihn aufstehen unter seinen Brudern und führe ihn in die innerste Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Und nimm den Olkrug und schütte es auf sein Haupt und sprich: So sagt der HERR: Ich habe dich zum Konige über Israel gesalbet. Und sollst die Tur auftun und fliehen und nicht verziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Und der Jüngling des Propheten, der Knabe, ging hin gen Ramoth in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Und da er hineinkam, siehe, da salien die Hauptleute des Heers. Und er sprach: Ich habe dir, Hauptmann, was zu sagen. Jehu sprach: Welchem unter uns alien? Er sprach: Dir, Hauptmann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Da stund er auf und ging hinein. Er aber schuttete das 01 auf sein Haupt und sprach zu ihm: So sagt der HERR, der Gott Israels: Ich habe dich zum Konige gesalbet über des HERRN Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Und du sollst das Haus Ahabs, deines Herrn, schlagen, daß ich das Blut der Propheten, meiner Knechte, und das Blut aller Knechte des HERRN rache von der Hand Isebels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'daß das ganze Haus Ahabs umkomme. Und ich will von Ahab ausrotten den, der an die Wand pisset, und den Verschlossenen und Verlassenen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Und will das Haus Ahabs machen wie das Haus Jerobeams, des Sohns Nebats, und wie das Haus Baesas, des Sohns Ahias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Und die Hunde sollen Isebel fressen auf dem Acker zu Jesreel, und soli sie niemand begraben. Und ertat die Tür auf und floh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Und da Jehu herausging zu den Knechten seines Herrn, sprach man zu ihm: Stehet es wohl? Warum ist dieser Rasende zu dir kommen? Er sprach zu ihnen: Ihr kennet doch den Mann wohl, und was er sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Sie sprachen: Das ist nicht wahr; sage es uns aber an. Er sprach: So und so hat er mit mir geredet und gesagt: So spricht der HERR: Ich habe dich zum Konige über Israel gesalbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Da eileten sie, und nahm ein jeglicher sein Kleid und legte es unter ihn auf die hohen Stufen, und bliesen mit der Posaune und sprachen: Jehu ist Konig worden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Also machte Jehu, der Sohn Josaphats, des Sohns Nimsis, einen Bund wider Joram. Joram aber lag vor Ramoth in Gilead mit dem ganzen Israel wider Hasael, den Konig zu Syrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Joram aber, der Konig, war wiederkommen, dafi er sich heilen liefie zu Jesreel von den Schlagen, die ihm die Syrer geschlagen hatten, da er stritt mit Hasael dem Konige zu Syrien. Und Jehu sprach: Ist\'s euer Gernüt, so soil niemand entrinnen aus der Stadt, daß er hingehe und ansage zu Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Und er lieti sich führen und zog gen Jesreel, denn Joram lag daselbst; so war Ahasja, der Konig Judas, hinabgezogen, Joram zu besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Der Wachter aber, der auf dem Turm zu Jesreel stund, sah den Haufen Jehus kommen und sprach: Ich sehe einen Haufen. Da sprach Joram: Nimm einen Reiter und sende ihnen entgegen und sprich: Ist\'s Friede?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Und der Reiter ritt hin ihm entgegen und sprach: So sagt der Konig: Ist\'s Friede? Jehu sprach: Was gehet dich der Friede an? Wende dich hinter mich! Der Wachter verkundigte und sprach: Der Bote ist zu ihnen kommen und kommt nichtwieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Da sandte er einen andern Reiter. Da der zu ihm kam, sprach er: So sprichtder Konig: Ist\'s Friede? Jehu sprach: Was gehet dich der Friede an? Wende dich hinter mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Das verkundigte der Wachter und sprach: Er ist zu ihnen kommen und kommt nichtwieder. Und es ist ein Treiben, wie das Treiben Jehus, des Sohns Nimsis; denn er treibt, wie er unsinnig ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Da sprach Joram: Spannet an! Und man spannete seinen Wagen an; und sie zogen aus, Joram, der Konig Israels, und Ahasja, der Konig Judas, ein jeglicher auf seinem Wagen, daß sie Jehu entgegenkamen; und sie trafen ihn an auf dem Acker Naboths, des Jesreeliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Und da Joram Jehu sah, sprach er: Jehu, ist\'s Friede? Er aber sprach: Was Friede? Deiner Mutter Isebel Hurerei und Zauberei wird immer großer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Da wandte Joram seine Hand und floh und sprach zu Ahasja: Es ist Verraterei, Ahasja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Aber Jehu fassete den Bogen und schoß Joram zwischen die Arme, daß der Pfeil durch sein Herz ausfuhr; und fiel in seinen Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Und er sprach zum Ritter Bidekar: Nimm und wirf ihn aufs Stuck Acker Naboths, des Jesreeliten. Denn ich gedenke, daß du mit mir auf einem Wagen seinem Vater Ahab nachfuhrest, daß der HERR solche Last uber ihn hub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Was gilt\'s, sprach der HERR, ich will dir das Blut Naboths und seiner Kinder, das ich gestern sah, vergelten auf diesem Acker. So nimm nun und wirf ihn auf den Acker nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Da das Ahasja, der Konig Judas, sah, floh er des Weges zum Hause des Gartens. Jehu aber jagte ihm nach und hieß ihn auch schlagen auf dem Wagen gen Gur hinan, die bei Jeblaam liegt. Und erfloh gen Megiddo und starb daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Und seine Knechte ließen ihn führen gen Jerusalem und begruben ihn in seinem Grabe mit seinen Vatern in der Stadt Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ahasja aber regierete fiber Juda im elften Jahr Jorams, des Sohns Ahabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Und da Jehu gen Jesreel kam, und Isebel das erfuhr, schminkte sie ihr Angesicht und schmückte ihr Haupt und guckte zum Fenster aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Und da Jehu unter das Tor kam, sprach sie: Ist\'s Simri wohl gegangen, der seinen Herrn erwürgete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Und er hub sein Angesicht auf zum Fenster und sprach: Wer ist bei mir hie? Da wandten sich zween oderdrei Kammererzu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Er sprach: Sturzet sie herab! Und sie stürzten sie herab, daß die Wand und die Rosse mit ihrem Blut besprenget wurden; und sie ward zertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Und da er hineinkam und gegessen und getrunken hatte, sprach er: Besehet doch die Verfluchte und begrabet sie; denn sie ist eines Konigs Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Da sie aber hingingen, sie zu begraben, fanden sie nichts von ihr denn den Schadel und Fuße und ihre flachen Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Und kamen wieder und sagten\'s ihm an. Eraber sprach: Es ist\'s, das der HERR geredet hat durch seinen Knecht Elia, den Thisbiten, und gesagt: Auf dem Acker Jesreels sollen die Hunde der Isebel Fleisch fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Also war das Aas Isebels wie Kot auf dem Felde im Acker Jesreels, daß man nicht sagen konnte: Das ist Isebel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Ahab aber hatte siebenzig Sohne zu Samaria. Und Jehu schrieb Briefe und sandte sie gen Samaria zu den Obersten der Stadt Jesreel, zu den Altesten und Vormundern Ahabs, die lauteten also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Wenn dieser Brief zu euch kommt, bei denen eures Herrn Sohne sind, Wagen, Rosse, feste Stadte und Rustung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'so sehet, welcher der beste und geschickteste sei unter den Sohnen eures Herrn und setzet ihn auf seines Vaters Stuhl und streitet fur eures Herrn Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Sie aber furchteten sich fast sehr und sprachen: Siehe, zween Konige sind nicht gestanden vor ihm, wie wollen wir denn stehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Und die fiber das Haus und fiber die Stadt waren, und die Altesten und Vormunder sandten hin zu Jehu und ließen ihm sagen: Wir sind deine Knechte; wir wollen alles tun, was du uns sagst; wir wollen niemand zum Konige machen. Tue, was dir gefallt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Da schrieb er den andern Brief zu ihnen, der lautete also: So ihr mein seid und meiner Stimme gehorchet, so nehmet die Haupter von den Mannern, eures Herrn Sohnen, und bringet sie zu mir morgen urn diese Zeit gen Jesreel. (Der Sohne aber des Konigs waren siebenzig Mann, und die Großten der Stadt zogen sie auf.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Da nun der Brief zu ihnen kam, nahmen sie des Konigs Sohne und schlachteten siebenzig Mann; und legten ihre Haupter in Korbe und schickten sie zu ihm gen Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Und da der Bote kam und sagte es ihm an und sprach: Sie haben die Haupter des Konigs Kinder gebracht, sprach er: Legt sie auf zween Haufen vor der Tür am Tor bis morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Und des Morgens, da er ausging, trat er dahin und sprach zu allem Volk: Ihrwolltja recht haben. Siehe, habe ich wider meinen Herrn einen Bund gemacht und ihn erwürget? Wer hat denn diese alle geschlagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'So erkennet ihr ja, daß kein Wort des HERRN ist auf die Erde gefallen, das der HERR geredet hat wider das Haus Ahabs; und der HERR hat getan, wie er geredet hat durch seinen Knecht Elia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Also schlug Jehu alle ubrigen vom Hause Ahabs zu Jesreel, alle seine Großen, seine Verwandten und seine Priester, bis daß ihm nicht einer uberblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Und machte sich auf, zog hin und kam gen Samaria. Unterwegen aberwarein Hirtenhaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Da traf Jehu an die Bruder Ahasjas, des Konigs Judas, und sprach: Wer seid ihr? Sie sprachen: Wir sind Bruder Ahasjas und ziehen hinab, zu grußen des Konigs Kinder und der Konigin Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Eraber sprach: Greifetsie lebendig! Und sie griffen sie lebendig und schlachteten sie bei dem Brunnen am Hirtenhaus, zweiundvierzig Mann, und liefi nicht einen von ihnen ubrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Und da ervon dannen zog, fand er Jonadab, den Sohn Rechabs, der ihm begegnete, und grußte ihn und sprach zu ihm: Ist dein Herz richtig, wie mein Herz mit deinem Herzen? Jonadab sprach: Ja. Ist\'s also, so gib mir deine Hand. Und er gab ihm seine Hand. Und er liefi ihn zu ihm auf den Wagen sitzen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'und sprach: Komm mit mir und sieh meinen Eifer urn den HERRN. Und sie fuhreten ihn mit ihm auf seinen Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Und da ergen Samaria kam, schlug eralies, was ubrig war von Ahab, zu Samaria, bis daß er ihn vertilgete, nach dem Wort des HERRN, das erzu Elia geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Und Jehu versammelte alles Volk und ließ zu ihnen sagen: Ahab hat Baal wenig gedienet, Jehu will ihm baß dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'So laßt nun rufen alle Propheten Baals, alle seine Knechte und alle seine Priester zu mir, daß man niemands vermisse; denn ich habe ein groß Opfer dem Baal zu tun. Wes man vermissen wird, der soil nicht leben. Aber Jehu tat solches zu untertreten, daß er die Diener Baals umbrachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Und Jehu sprach: Heiliget dem Baal das Fest und laßtes ausrufen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Auch sandte Jehu in ganz Israel und ließ alle Diener Baals kommen, daß niemand ubrig war, der nicht kame. Und sie kamen in das Haus Baals, daß das Haus Baals voll ward an alien Enden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Da sprach er zu denen, die uber das Kleiderhaus waren: Bringet alien Dienern Baals Kleider heraus! Und sie brachten die Kleider heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Und Jehu ging in die Kirche Baals mit Jonadab, dem Sohn Rechabs, und sprach zu den Dienern Baals: Forschet und sehet zu, daß nicht hie unter euch sei des HERRN Diener jemand, sondern Baals Diener alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Und da sie hineinkamen, Opfer und Brandopfer zu tun, bestellete ihm Jehu außen achtzig Mann und sprach: Wenn der Manner jemand entrinnet, die ich unter eure Hande gebe, so soil fur seine Seele desselben Seele sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Da er nun die Brandopfer vollendet hatte, sprach Jehu zu den Trabanten und Rittern: Gehet hinein und schlaget jedermann; lasset niemand herausgehen! Und sie schlugen sie mit der Scharfe des Schwerts. Und die Trabanten und Ritter warfen sie weg und gingen zur Stadt der Kirche Baals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Und brachten heraus die Saulen in der Kirche Baals und verbrannten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Und zerbrachen die Saule Baals samt der Kirche Baals und machten ein heimlich Gemach draus bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Also vertilgete Jehu den Baal aus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Aber von den Sünden Jerobeams, des Sohns Nebats, der Israel sündigen machte, ließ Jehu nicht, von den güldenen Kalbern zu Bethel und zu Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Und der HERR sprach zu Jehu: Darum, daß du willig gewesen bist zu tun, was mir gefallen hat, und hast am Hause Ahabs getan alles, was in meinem Herzen war, sollen dir. auf deinem Stuhl Israels sitzen deine Kinder ins vierte Glied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Aber doch hielt Jehu nicht, daß er im Gesetz des HERRN, des Gottes Israels, wandelte von ganzem Herzen; denn er ließ nicht von den Sunden Jerobeams, der Israel hatte sundigen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Zur selbigen Zeit fing der HERR an, überdrussig zu werden uber Israel; denn Hasael schlug sie in alien Grenzen Israels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'vom Jordan gegen derßonnen Aufgang und das ganze Land Gilead der Gaditer, Rubeniter und Manassiter, von Aroer an, die am Bach bei Arnon liegt, und Gilead und Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Was aber mehr von Jehu zu sagen ist, und alles, was er getan hat, und alle seine Macht, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Und Jehu entschlief mit seinen Vatern, und sie begruben ihn zu Samaria. Und Joahas, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Die Zeit aber, die Jehu uber Israel regieret hat zu Samaria, sind achtundzwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Athalja aber, Ahasjas Mutter, da sie sah, daß ihr Sohn tot war, machte sie sich auf und brachte urn alien koniglichen Samen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Aber Joseba, die Tochter des Konigs Joram, Ahasjas Schwester, nahm Joas, den Sohn Ahasjas, und stahl ihn aus des Konigs Kindern, die getotet wurden, mit seiner Amme in der Schlafkammer; und sie verbargen ihn vor Athalja, daß er nicht getotet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Und er war mit ihr versteckt im Hause des HERRN sechs Jahre. Athalja aber war Konigin im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Im siebenten Jahr aber sandte hin Jojada und nahm die Obersten fiber hundert mit den Hauptleuten und die Trabanten und lieft sie zu sich ins Haus des HERRN kommen; und machte einen Bund mit ihnen und nahm einen Eid von ihnen im Hause des HERRN; und zeigte ihnen des Kdnigs Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Und gebot ihnen und sprach: Das ist\'s, das ihr tun sollt: Euer ein dritter Teil, die ihr des Sabbats angehet, sollen der Hut warten im Hause des Konigs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'und ein dritter Teil soil sein am Tor Sur und ein dritter Teil am Tor, das hinterden Trabanten ist; und sollt der Hut warten am Hause Massa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Aber zwei Teile euer aller, die ihr des Sabbats abgehet, sollen der Hut warten im Hause des HERRN urn den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Und sollt rings urn den Konig euch machen, und ein jeglicher mit seiner Wehr in der Hand; und wer herein zwischen die Wand kommt, der sterbe, daß ihr bei dem Konige seid, wenn er aus und ein gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Und die Obersten uber hundert taten alles, wie ihnen Jojada, der Priester, geboten hatte, und nahmen zu sich ihre Manner, die des Sabbats angingen, mit denen, die des Sabbats abgingen, und kamen zu dem Priester Jojada.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Und der Priester gab den Hauptleuten Spiefte und Schilde, die des Konigs Davids gewesen waren und in dem Hause des HERRN waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Und die Trabanten stunden urn den Konig her, ein jeglicher mit seiner Wehr in der Hand, von dem Winkel des Hauses zur Rechten bis zum Winkel zur Linken, zum Altar zu und zum Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Und er lieft des Konigs Sohn hervorkommen und setzte ihm eine Krone auf und gab ihm das Zeugnis; und machten ihn zum Konige und salbeten ihn und schlugen die Hande zusammen und sprachen: Gluck zu dem Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Und da Athalja horete das Geschrei des Volks, das zulief, kam sie zum Volk in das Haus des HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'und sah, siehe, da stund der Konig an der Saule, wie es Gewohnheit war, und die Sanger und Trommeten bei dem Konige; und alles Volk des Landes war frohlich und bliesen mit Trommeten. Athalja aber zerrili ihre Kleider und sprach: Aufruhr, Aufruhr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Aber der Priester Jojada gebot den Obersten uber hundert, die uber das Heer gesetzt waren, und sprach zu ihnen: Führet sie zum Hause hinaus in den Hof; und wer ihr folget, der sterbe des Schwerts! Denn der Priester hatte gesagt, sie sollte nicht im Hause des HERRN sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Und sie legten die Hande an sie; und sie ging hinein des Weges, da die Rosse zum Hause des Konigs gehen, und ward daselbst getotet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Da machte Jojada einen Bund zwischen dem HERRN und dem Konige und dem Volk, daß sie des HERRN Volk sein sollten; also auch zwischen dem Konige und dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Da ging alles Volk des Landes in die Kirche Baals und brachen seine Altare ab und zerbrachen seine Bildnisse rechtwohl; und Mathan, den Priester Baals, erwürgeten sie vor den Altaren. Der Priester aber bestellete die Amter im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Und nahm die Obersten uber hundert und die Hauptleute und die Trabanten und alles Volk des Landes und führeten den Konig hinab vom Hause des HERRN; und kamen auf dem Wege von dem Tor der Trabanten zum Kdnigshause; und er setzte sich auf der Konige Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Und alles Volk im Lande war frohlich, und die Stadt war stille. Athalja aber toteten sie mit dem Schwert in des Konigs Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Und Joas war sieben Jahre alt, da er Konig ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Im siebenten Jahr Jehus ward Joas Konig und regierete vierzig Jahre zu Jerusalem. Seine Mutter hieft Zibea von Bersaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Und Joas tat, was rechtwar und dem HERRN wohlgefiel, solange ihn der Priester Jojada lehrete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'ohne daß sie die Hohen nicht abtaten; denn das Volk opferte und raucherte noch auf den Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Und Joas sprach zu den Priestern: Alles Geld, das geheiliget wird, daß es in das Haus des HERRN gebracht werde, das gang und gabe ist, das Geld, so jedermann gibt in der Schatzung seiner Seele, und alles Geld, das jedermann von freiem Herzen opfert, daß es in des HERRN Haus gebracht werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'das lafttdie Priester zu sich nehmen, einen jeglichen von seinem Bekannten. Davon sollen sie bessern, was baufallig ist am Hause des HERRN, wo siefinden, das baufallig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Da aber die Priester bis ins dreiundzwanzigste Jahr des Konigs Joas nicht besserten, was baufallig war am Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'rief der Konig Joas dem Priester Jojada samt den Priestern und sprach zu ihnen: Warum bessert ihr nicht, was baufallig ist am Hause? So sollt ihr nun nicht zu euch nehmen das Geld, ein jeglicher von seinen Bekannten, sondern sollt es geben zu dem, das baufallig ist am Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Und die Priester bewilligten vom Volk nicht Geld zu nehmen und das Baufallige am Hause zu bessern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Da nahm der Priester Jojada eine Lade und bohrte oben ein Loch drein und setzte sie zur rechten Hand neben den Altar, da man in das Haus des HERRN gehet. Und die Priester, die an der Schwelle huteten, taten drein alles Geld, das zu des HERRN Haus gebracht ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Wenn sie dann sahen, daß viel Geld in der Lade war, so kam des Konigs Schreiber herauf mit dem Hohenpriester und banden das Geld zusammen und zahlten es, was fur des HERRN Haus funden ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Und man gab das Geld bar über denen, die da arbeiteten und bestellet waren zum Hause des HERRN; und sie gaben\'s heraus den Zimmerleuten, die da baueten und arbeiteten am Hause des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'namlich den Maurern und Steinmetzen, und die da Holz und gehauene Steine kauften, daß das Baufallige am Hause des HERRN gebessert wurde, und alles, was sie fanden am Hause zu bessern not sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Doch liefi man nicht machen silberne Schalen, Psalter, Becken, Trommeten noch irgend ein gulden Oder silbern Gerat im Hause des HERRN von solchem Gelde, das zu des HERRN Hause gebracht ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'sondern man gab\'s den Arbeitern, daß sie damit das Baufallige am Hause des HERRN besserten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Auch durften die Manner nicht berechnen, denen man das Geld tat, daü sie es den Arbeitern gaben, sondern sie handelten auf Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Aber das Geld von Schuldopfern und Sundopfern ward nicht zum Hause des HERRN gebracht; denn es war der Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Zu der Zeit zog Hasael, der Konig zu Syrien, herauf und stritt wider Gath und gewann sie. Und da Hasael sein Angesicht stellete, zu Jerusalem hinaufzuziehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'nahm Joas, der Konig Judas, all das Geheiligte, das seine Vater, Josaphat, Joram und Ahasja, die Konige Judas, geheiliget hatten, und was ergeheiliget hatte, dazu alles Gold, das man fand im Schatz in des HERRN Hause und in des Konigs Hause, und schickte es Hasael, dem Konige zu Syrien. Da zog er ab von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Was aber mehr von Joas zu sagen ist, und alles, was er getan hat, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Und seine Knechte emporten sich und machten einen Bund und schlugen ihn im Hause Millo, da man hinabgehet zu Silla.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 22, 'Denn Josabar, derßohn Simeaths, und Josabad, der Sohn Somers, seine Knechte, schlugen ihn tot. Und man begrub ihn mit seinen Vatern in der Stadt Davids. Und Amazia, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Im dreiundzwanzigsten Jahr Joas des Sohns Ahasjas, des Konigs Judas, ward Joahas, der Sohn Jehus, Konig uber Israel zu Samaria siebenzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Und tat, das dem HERRN übel gefiel, und wandelte den Sünden nach Jerobeams, des Sohns Nebats, der Israel sündigen machte, und lieft nicht davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Und des HERRN Zorn ergrimmete über Israel und gab sie unter die Hand Hasaels, des Konigs zu Syrien, und Benhadads, des Sohns Hasaels, ihr Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Aber Joahas bat des HERRN Angesicht. Und der HERR erhorete ihn; denn er sah den Jammer Israels an, wie sie der Konig zu Syrien drangete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Und der HERR gab Israel einen Heiland, der sie aus der Gewalt der Syrer führete, daß die Kinder Israel in ihren Hütten wohneten, wie vorhin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Doch lieften sie nicht von der Sünde des Hauses Jerobeams, der Israel sündigen machte, sondern wandelten drinnen. Auch blieb stehen der Hain zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Denn es war des Volks Joahas nicht mehr überblieben denn funfzig Reiter, zehn Wagen und zehntausend Fufivolks. Denn der Konig zu Syrien hatte sie umgebracht und hatte sie gemacht wie Drescherstaub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Was aber mehr von Joahas zu sagen ist, und alles, was er getan hat, und seine Macht, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Und Joahas entschlief mit seinen Vatern, und man begrub ihn zu Samaria. Und sein Sohn Joas ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Im siebenunddreifügsten Jahr Joas des Konigs Judas, ward Joas, der Sohn Joahas Konig über Israel zu Samaria sechzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Und tat, das dem HERRN übel gefiel, und lieft nicht von alien Sünden Jerobeams, des Sohns Nebats, der Israel sündigen machte, sondern wandelte drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Was aber mehr von Joas zu sagen ist, und was er getan hat, und seine Macht, wie er mit Amazia, dem Konige Judas, gestritten hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Und Joas entschlief mit seinen Vatern, und Jerobeam saft auf seinem Stuhl. Joas aber ward begraben zu Samaria bei den Konigen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Elisa aber ward krank, daran erauch starb. Und Joas, der Konig Israels, kam zu ihm hinab und weinete vor ihm und sprach: Mein Vater, mein Vater, Wagen Israels, und seine Reiter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa aber sprach zu ihm: Nimm den Bogen und Pfeile! Und da er den Bogen und die Pfeile nahm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'sprach erzum Konige Israels: Spanne mit deiner Hand den Bogen! Und er spannete mit seiner Hand. Und Elisa legte seine Hand auf des Konigs Hand');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'und sprach: Tue das Fenster auf gegen Morgen! Und er tat es auf. Und Elisa sprach: Schiefte! Und er schoft. Er aber sprach: Ein Pfeil des Heils vom HERRN, ein Pfeil des Heils wider die Syrer; und du wirst die Syrer schlagen zu Aphek, bis sie aufgerieben sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Und er sprach: Nimm die Pfeile! Und da ersie nahm, sprach erzum Konige Israels: Schlage die Erde! Und er schlug dreimal und stund stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Da ward der Mann Gottes zornig auf ihn und sprach: Hattest du fünf- Oder sechsmal geschlagen, so wurdest du die Syrer geschlagen haben, bis sie aufgerieben waren; nun aber wirst du sie dreimal schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Da aber Elisa gestorben war, und man ihn begraben hatte, Helen die Kriegsleute der Moabiter ins Land desselben Jahres.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Und es begab sich, daß sie einen Mann begruben; da sie aber die Kriegsleute sahen, warfen sie den Mann in Elisas Grab. Und da er hin kam und die Gebeine Elisas anruhrete, ward er lebendig und trat auf seine Füße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Also zwang nun Hasael, der Konig zu Syrien, Israel, solange Joahas lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Aber der HERR tat ihnen Gnade und erbarmete sich ihrer und wandte sich zu ihnen um seines Bundes willen mit Abraham, Isaak und Jakob; und wollte sie nicht verderben, verwarf sie auch nicht von seinem Angesicht bis auf diese Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Und Hasael, der Konig zu Syrien, starb, und sein Sohn Benhadad ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Joas aber kehrete um und nahm die Stadte aus der Hand Benhadads, des Sohns Hasaels, die er aus der Hand seines Vaters Joahas genommen hatte mit Streit. Dreimal schlug ihn Joas und brachte die Stadte Israels wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Im andern Jahr Joas, des Sohns Joahas, des Konigs Israels, ward Ahazia Konig, der Sohn Joas, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Fünfundzwanzig Jahre alt war er, da er Konig ward, und regierete neunundzwanzig Jahre zu Jerusalem. Seine Mutter hiefi Joadan von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Und ertat, was dem HERRN wohlgefiel, doch nicht wie sein Vater David, sondern wie sein Vater Joas tat er auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Denn die Hohen wurden nicht abgetan, sondern das Volk opferte und raucherte noch auf den Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Da er nun des Konigsreichs machtig ward, schlug er seine Knechte, die seinen Vater, den Konig, geschlagen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Aber die Kinder der Totschlager totete er nicht; wie es denn geschrieben stehet im Gesetzbuch Moses, da der HERR geboten hat und gesagt: Die Vater sollen nicht um der Kinder willen sterben, und die Kinder sollen nicht um der Vater willen sterben, sondern ein jeglicher soil um seiner Sünde willen sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Er schlug auch der Edomiter im Salztal zehntausend und gewann die Stadt Sela mit Streit; und hiefi sie Jaktheel bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Da sandte Amazia Boten zu Joas, dem Sohn Joahas des Sohns Jehus, dem Konige Israels, und lieli ihm sagen: Komm her, lali uns miteinander besehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Aber Joas, der Konig Israels, sandte zu Amazia, dem Konige Judas, und lieli ihm sagen: Der Dornstrauch, der im Libanon ist, sandte zur Zeder im Libanon und lieli ihr sagen: Gib deine Tochter meinem Sohn zum Weibe! Aber das Wild auf dem Felde im Libanon lief uber den Dornstrauch und zertrat ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Du hast die Edomiter geschlagen, des uberhebt sich dein Herz. Habe den Ruhm und bleibe daheim; warum ringest du nach Ungluck, daß du fallest und Juda mit dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Aber Amazia gehorchte nicht. Da zog Joas, der Konig Israels, herauf; und sie besahen sich miteinander, er und Amazia, der Konig Judas, zu Beth-Semes, die in Juda liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Aber Juda ward geschlagen vor Israel, daß ein jeglicher floh in seine Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Und Joas, der Konig Israels, griff Amazia, den Konig Judas, den Sohn Joas des Sohns Ahasjas, zu Beth-Semes; und kam gen Jerusalem und zerrili die Mauern Jerusalems von dem Tor Ephraim an bis an das Ecktor, vierhundert Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Und nahm alles Gold und Silber und Gerate, das funden ward im Hause des HERRN und im Schatz des Konigshauses, dazu die Kinder zu Pfande; und zog wieder gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Was aber mehr von Joas zu sagen ist, das er getan hat, und seine Macht, und wie er mit Amazia, dem Konige Judas, gestritten hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Und Joas entschlief mit seinen Vatern und ward begraben zu Samaria unter den Konigen Israels. Und sein Sohn Jerobeam ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amazia aber, der Sohn Joas des Konigs Judas, lebte nach dem Tode Joas des Sohns Joahas des Konigs Israels, funfzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Was aber mehr von Amazia zu sagen ist, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Und sie machten einen Bund wider ihn zu Jerusalem; er aber floh gen Lachis. Und sie sandten hin ihm nach gen Lachis und toteten ihn daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Und sie brachten ihn auf Rossen; und erward begraben zu Jerusalem bei seinen Vatern in der Stadt Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Und das ganze Volk Judas nahm Asarja in seinem sechzehnten Jahr und machten ihn zum Konige anstatt seines Vaters Amazia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Er bauete Elath und brachte sie wieder zu Juda, nachdem der Konig mit seinen Vatern entschlafen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Im funfzehnten Jahr Amazias, des Sohns Joas des Konigs Judas, ward Jerobeam, der Sohn Joas Konig fiber Israel zu Samaria einundvierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Und tat, das dem HERRN libel gefiel, und lieü nicht ab von alien Sunden Jerobeams, des Sohns Nebats, der Israel sündigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Er aber brachte wieder herzu die Grenze Israels von Hemath an bis ans Meer, das im blachen Felde liegt, nach dem Wort des HERRN, des Gottes Israels, das er geredet hatte durch seinen Knecht Jona, den Sohn Amithais, den Propheten, der von Gath-Hepher war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Denn der HERR sah an den elenden Jammer Israels, dal J, auch die Verschlossenen und Verlassenen dahin waren, und kein Heifer war in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Und der HERR hatte nicht geredet, daß er wollte den Namen Israels austilgen unter dem Himmel, und half ihnen durch Jerobeam, den Sohn Joas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Was aber mehr von Jerobeam zu sagen ist, und alles, was er getan hat, und seine Macht, wie er gestritten hat, und wie er Damaskus und Hemath wiedergebracht an Juda in Israel, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Und Jerobeam entschlief mit seinen Vatern, mit den Konigen Israels. Und sein Sohn Sacharja ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Im siebenundzwanzigsten Jahr Jerobeams, des Konigs Israels, ward Konig Asarja, der Sohn Amazias, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Und war sechzehn Jahre alt, da er Konig ward, und regierete zweiundfünfzig Jahre zu Jerusalem. Seine Mutter hieli Jechalja von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Und tat, das dem HERRN wohlgefiel, allerdinge wie sein Vater Amazia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'ohne dafi sie die Hohen nicht abtaten; denn das Volk opferte und raucherte noch auf den Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Der HERR plagte aber den Konig, dafi er aussatzig war bis an seinen Tod, und wohnete in einem sondern Hause. Jotham aber, des Konigs Sohn, regierete das Haus und richtete das Volk im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Was aber mehr von Asarja zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Und Asarja entschlief mit seinen Vatern; und man begrub ihn bei seinen Vatern in der Stadt Davids. Und sein Sohn Jotham ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Im achtunddreilügsten Jahr Asarjas, des Konigs Judas, ward Konig Sacharja, der Sohn Jerobeams, über Israel zu Samaria sechs Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Und tat, das dem HERRN ubel gefiel, wie seine Vater getan hatten. Er lieli nicht ab von den Sunden Jerobeams, des Sohns Nebats, der Israel sundigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Und Sallum, der Sohn Jabes, machte einen Bund wider ihn und schlug ihn vor dem Volk und totete ihn; und ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Was aber mehr von Sacharja zu sagen ist, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Und das ist\'s, das der HERR Jehu geredet hatte: Dir sollen Kinder ins vierte Glied sitzen auf dem Stuhl Israels; und ist also geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum aber, der Sohn Jabes ward Konig im neununddreilügsten Jahr Asarjas, des Konigs Judas, und regierete einen Monden zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Denn Menahem, der Sohn Gadis, zog herauf von Thirza und kam gen Samaria und schlug Sallum, den Sohn Jabes zu Samaria und totete ihn; und ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Was aber mehr von Sallum zu sagen ist und seinem Bund, den er anrichtete, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Dazumal schlug Menahem Tiphsah und alle, die drinnen waren, und ihre Grenze von Thirza, darum daß sie ihn nicht wollten einlassen; und schlug alle ihre Schwangeren und zerrüi sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Im neununddreilügsten Jahr Asarjas, des Konigs Judas, ward Konig Menahem, der Sohn Gadis, liber Israel zehn Jahre zu Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Und tat, das dem HERRN ubel gefiel. Er lieli sein Leben lang nicht von den Sunden Jerobeams, des Sohns Nebats, der Israel sundigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Und es kam Phul, der Konig von Assyrien, ins Land. Und Menahem gab dem Phul tausend Zentner Silbers, daß er\'s mit ihm hielte, und bekraftigte ihm das Konigreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Und Menahem setzte ein Geld in Israel auf die Reichsten, funfzig Sekel Silbers auf einen jeglichen Mann, das er dem Konige von Assyrien gabe. Also zog der Konig von Assyrien wieder heim und blieb nicht im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Was aber mehr von Menahem zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Und Menahem entschlief mit seinen Vatern; und Pekahja, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Im funfzigsten Jahr Asarjas, des Konigs Judas, ward Konig Pekahja, der Sohn Menahems, über Israel zu Samaria zwei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Und tat, das dem HERRN ubel gefiel, denn er lieli nicht von der Sünde Jerobeams, des Sohns Nebats, der Israel sundigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Und es machte Pekah, der Sohn Remaljas, seines Ritters, einen Bund wider ihn und schlug ihn zu Samaria im Palast des Konigshauses, mit Argob und Arne und funfzig Mann mit ihm von den Kindern Gileads, und totete ihn; und ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Was aber mehr von Pekahja zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Im zweiundfunfzigsten Jahr Asarjas, des Konigs Judas, ward Konig Pekah, der Sohn Remaljas, über Israel zu Samaria zwanzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Und tat, das dem HERRN ubel gefiel; denn er lieli nicht von der Sünde Jerobeams, des Sohns Nebats, der Israel sündigen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Zu den Zeiten Pekahs, des Konigs Israels, kam Thiglath-Pilesser, der Konig zu Assyrien, und nahm Ijon, Abel-Beth-Maecha, Janoah, Kedes, Hazor, Gilead, Galilaa und das ganze Land Naphthali und fuhrete sie weg nach Assyrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Und Hosea, der Sohn Elas, machte einen Bund wider Pekah, den Sohn Remaljas, und schlug ihn tot; und ward Konig an seiner Statt im zwanzigsten Jahr Jothams, des Sohns Usias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Was aber mehr von Pekah zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Im andern Jahr Pekahs, des Sohns Remaljas, des Konigs Israels, ward Konig Jotham, der Sohn Usias, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Und war funfundzwanzig Jahre alt, da er Konig ward, und regierete sechzehn Jahre zu Jerusalem. Seine Mutter hiel J Jerusa, eine Tochter Zadoks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Und tat, das dem HERRN wohlgefiel, allerdinge wie sein Vater Usia getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'ohne daß sie die Hohen nicht abtaten; denn das Volk opferte und raucherte noch auf den Hohen. Er bauete das hohe Tor am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Was aber mehr von Jotham zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Zu der Zeit hub der HERR an zu senden in Juda Rezin, den Konig zu Syrien, und Pekah, den Sohn Remaljas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Und Jotham entschlief mit seinen Vatern und ward begraben bei seinen Vatern in der Stadt Davids, seines Vaters; und Ahas, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 39, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Im siebenzehnten Jahr Pekahs, des Sohns Remaljas, ward Konig Ahas, der Sohn Jothams, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Zwanzig Jahre war Ahas alt, da er Konig ward, und regierete sechzehn Jahre zu Jerusalem; und tat nicht, was dem HERRN, seinem Gott wohlgefiel, wie sein Vater David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Denn er wandelte auf dem Wege der Konige Israels. Dazu liefi er seinen Sohn durchs Feuergehen nach den Greueln der Heiden, die der HERR vor den Kindern Israel vertrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Und tat Opferund raucherte auf den Hohen und auf den Hugeln und unter alien grunen Baumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Dazumal zog Rezin, der Konig zu Syrien, und Pekah, der Sohn Remaljas, Konig in Israel, hinaufgen Jerusalem, zu streiten, und belagerten Ahas; aber sie konnten sie nicht gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Zurselbigen Zeit brachte Rezin, Konig in Syrien, Elath wieder an Syrien und stieft die Juden aus Elath; aber die Syrer kamen und wohneten drinnen bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Aber Ahas sandte Boten zu Thiglath-Pilesser, dem Konige zu Assyrien, und lieli ihm sagen: Ich bin dein Knecht und dein Sohn; komm herauf und hilf mir aus der Hand des Konigs zu Syrien und des Konigs Israels, die sich wider mich haben aufgemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Und Ahas nahm das Silber und Gold, das in dem Hause des HERRN und in den Schatzen des Konigshauses funden ward, und sandte dem Konige zu Assyrien Geschenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Und der Konig zu Assyrien gehorchte ihm und zog herauf gen Damaskus und gewann sie; und fuhrete sie weg gen Kir und totete Rezin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Und der Konig Ahas zog entgegen Thiglath- Pilesser, dem Konige zu Assyrien, gen Damaskus. Und da er einen Altar sah, der zu Damaskus war, sandte der Konig Ahas desselben Altars Ebenbild und Gleichnis zum Priester Uria, wie derselbe gemacht war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Und Uria, der Priester, bauete einen Altar und machte ihn, wie der Konig Ahas zu ihm gesandt hatte von Damaskus, bis der Konig Ahas von Damaskus kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Und da der Konig von Damaskus kam und den Altar sah, opferte er drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Und zundete drauf an sein Brandopfer, Speisopfer und goß drauf seine Trankopfer und lieü das Blut der Dankopfer, die er opferte, auf den Altar sprengen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Aber den ehernen Altar, der vor dem HERRN stund, tat er weg, daß er nicht stünde zwischen dem Altar und dem Hause des HERRN, sondern setzte ihn an die Ecke des Altars gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Und der Konig Ahas gebot Uria, dem Priester, und sprach: Auf dem grolien Altar sollst du anzünden die Brandopfer des Morgens und die Speisopfer des Abends und die Brandopfer des Konigs und sein Speisopfer und die Brandopfer alles Volks im Lande samt ihrem Speisopfer und Trankopfer und alles Blut der Brandopfer, und das Blut aller andern Opfer sollst du drauf sprengen; aber mit dem ehernen Altar will ich denken, was ich mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Uria, der Priester, tat alles, was ihn der Konig Ahas hieli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Und der Konig Ahas brach ab die Seiten an den Gestühlen und tat die Kessel oben davon; und das Meer tat er von den ehernen Ochsen, die drunter waren, und setzte es auf das steinerne Pflaster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Dazu die Decke des Sabbats, die sie am Hause gebauet hatten, und den Gang des Konigs aulien wandte er zum Hause des HERRN, dem Konige zu Assyrien zu Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Was aber mehr von Ahas zu sagen ist, das er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Und Ahas entschlief mit seinen Vatern und ward begraben bei seinen Vatern in der Stadt Davids. Und Hiskia, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Im zwolften Jahr Ahas, des Konigs Judas, ward Konig uber Israel zu Samaria Hosea, der Sohn Elas, neun Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Und tat, das dem HERRN ubel gefiel, doch nicht wie die Konige Israels, die vor ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Wider denselben zog herauf Salmanasser, der Konig zu Assyrien. Und Hosea ward ihm untertan, daß er ihm Geschenke gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Da aber der Konig zu Assyrien inne ward, daß Hosea einen Bund anrichtete und Boten hatte zu So, dem Konige in Agypten, gesandt, und nicht darreichte Geschenke dem Konige zu Assyrien alle Jahre, belagerte er ihn und legte ihn ins Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Und der Konig zu Assyrien zog aufs ganze Land und gen Samaria und belagerte sie drei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Und im neunten Jahr Hoseas gewann der Konig zu Assyrien Samaria und fuhrete Israel weg nach Assyrien und setzte sie zu Halah und zu Habor, am Wasser Gosan, und in den Stadten der Meder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Denn da die Kinder Israel wider den HERRN, ihren Gott, sundigten (der sie aus Agyptenland gefuhret hatte, aus der Hand Pharaos, des Konigs in Agypten) und andere Gotter furchteten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'und wandelten nach der Heiden Weise, die der HERR vor den Kindern Israel vertrieben hatte, und wie die Konige Israels taten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'und die Kinder Israel schmückten ihre Sachen wider den HERRN, ihren Gott, die doch nicht gut waren, namlich daü sie ihnen Hohen baueten in alien Stadten, beide in Schlossern und festen Stadten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'und richteten Saulen auf und Haine auf alien hohen Hügeln und unter alien grünen Baumen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'und raucherten daselbst auf alien Hohen, wie die Heiden, die der HERR vor ihnen weggetrieben hatte, und trieben bose Stucke, damit sie den HERRN erzümeten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'und dieneten den Gotzen, davon der HERRzu ihnen gesagt hatte: Ihr sollt solches nicht tun;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'und wenn der HERR bezeugte in Israel und Juda durch alle Propheten und Schauer und lieli ihnen sagen: Kehret um von euren bosen Wegen und haltet meine Gebote und Rechte nach allem Gesetz, das ich euren Vatern geboten habe und das ich zu euch gesandt habe durch meine Knechte, die Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'so gehorchten sie nicht, sondern harteten ihren Nacken, wie der Nacken ihrer Vater, die nicht glaubeten an den HERRN ihren Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'dazu verachteten sie seine Gebote und seinen Bund, den er mit ihren Vatern gemacht hatte, und seine Zeugnisse, die er unter ihnen tat, sondern wandelten ihrer Eitelkeit nach und wurden eitel den Heiden nach, die um sie herwohneten, von welchen ihnen der HERR geboten hatte, sie sollten nicht wie sie tun;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'aber sie verlielien alle Gebote des HERRN, ihres Gottes, und machten ihnen zwei gegossene Kalber und Haine; und beteten an alle Heere des Himmels und dieneten Baal;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'und lielien ihre Sohne und Tochter durchs Feuergehen und gingen mit Weissagen und Zaubern um; und ubergaben sich zu tun, das dem HERRN ubel gefiel, ihn zu erzürnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'da ward der HERR sehrzornig uber Israel und tat sie von seinem Angesicht, daß nichts uberblieb denn der Stamm Juda alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Dazu hieltauch Juda nicht die Gebote des HERRN, ihres Gottes, und wandelten nach den Sitten Israels, die sie getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Darum verwarf der HERR alien Samen Israels und drangete sie und gab sie in die Hande der Rauber, bis daß er sie verwarf von seinem Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Denn Israel ward gerissen vom Hause Davids; und sie machten zum Konige Jerobeam, den Sohn Nebats. Derselbe wandte Israel hinten ab vom HERRN und machte, daß sie schwerlich sundigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Also wandelten die Kinder Israel in alien Sunden Jerobeams, die er angerichtet hatte, und lielien nicht davon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'bis der HERR Israel von seinem Angesicht tat, wie er geredet hatte durch alle seine Knechte, die Propheten. Also ward Israel aus seinem Lande weggefuhret nach Assyrien bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Der Konig aberzu Assyrien lieli kommen von Babel, von Kutha, von Ava, von Hemath und Sepharvaim und besetzte die Stadte in Samaria anstatt der Kinder Israel. Und sie nahmen Samaria ein und wohneten in derselben Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Da sie aber anhuben, daselbst zu wohnen, und den HERRN nicht furchteten, sandte der HERR Lowen unter sie, die erwürgeten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Und sie lielien dem Konige zu Assyrien sagen: Die Heiden, die du hast hergebracht und die Stadte Samarias damit besetzt, wissen nichts von der Weise des Gottes im Lande; darum hat er Lowen unter sie gesandt, und siehe, dieselben toten sie, weil sie nicht wissen um die Weise des Gottes im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Der Konig zu Assyrien gebot und sprach: Bringet dahin der Priester einen, die von dannen sind weggefuhret, und ziehet hin und wohnet daselbst; und er lehre sie die Weise des Gottes im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Da kam der Priester einer, die von Samaria weggefuhret waren, und setzte sich zu Bethel und lehrete sie, wie sie den HERRN furchten sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Aber ein jeglich Volk machte seinen Gott und taten sie in die Hauser auf den Hohen, die die Samariter machten, ein jeglich Volk in ihren Stadten, darinnen sie wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Die von Babel machten Suchoth-Benoth. Die von Chuth machten Nergel. Die von Hemath machten Asima.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Die von Ava machten Nibehas und Tharthak. Die von Sepharvaim verbrannten ihre Sohne dem Adramelech und Anamelech, den Gottern derer von Sepharvaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Und weil sie den HERRN auch furchteten, machten sie ihnen Priester auf den Hohen aus den Untersten unter ihnen und taten sie in die Hauser auf den Hohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Also furchteten sie den HERRN und dieneten auch den Gottern nach eines jeglichen Volks Weise, von dannen sie hergebracht waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Und bis auf diesen Tag tun sie nach der alten Weise, daß sie weder den HERRN furchten noch ihre Sitten und Rechte tun nach dem Gesetz und Gebot, das der HERR geboten hat den Kindern Jakobs, welchem er den Namen Israel gab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'und machte einen Bund mit ihnen und gebot ihnen und sprach: Furchtet keine andern Gotter und betet sie nicht an und dienet ihnen nicht und opfert ihnen nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'sondern den HERRN, der euch aus Agyptenland gefuhret hat mit grower Kraft und ausgerecktem Arm, den furchtet, den betet an und dem opfert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'und die Sitten, Rechte, Gesetze und Gebote, die er euch hat beschreiben lassen, die haltet, daß ihr danach tut allewege und nicht andere Gotter furchtet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'und des Bundes, den er mit euch gemacht hat, vergesset nicht, daß ihr nicht andere Gotter furchtet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'sondern furchtet den HERRN, euren Gott, der wird euch erretten von alien euren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Aber diese gehorchten nicht, sondern taten nach ihrer vorigen Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Also furchteten diese Heiden den HERRN und dieneten auch ihren Gotzen. Also taten auch ihre Kinder und Kindeskinder, wie ihre Vater getan haben, bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Im dritten Jahr Hoseas, des Sohns Elas, des Konigs Israels, ward Konig Hiskia, der Sohn Ahas des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Und war funfundzwanzig Jahre alt, da er Konig ward, und regierete neunundzwanzig Jahre zu Jerusalem. Seine Mutter hieft Abi, eine Tochter Sacharjas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Und tat, was dem HERRN wohlgefiel, wie sein Vater David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Er tat ab die Hohen und zerbrach die Saulen und rottete die Haine aus und zerstieft die eherne Schlange, die Mose gemacht hatte; denn bis zu der Zeit hatten ihr die Kinder Israel gerauchert, und man hieft sie Nehusthan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Ervertrauete dem HERRN, dem Gott Israels, daß nach ihm seinesgleichen nicht war unter alien Konigen Judas, noch vor ihm gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Er hing dem HERRN an und wich nicht hinten von ihm ab und hielt seine Gebote, die der HERR Mose geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Und der HERR war mit ihm; und wo erauszog, handelte er kluglich. Dazu ward er abtrunnig vom Konige zu Assyrien und war ihm nicht untertan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Er schlug auch die Philister bis gen Gasa und ihre Grenze, von den Schlossern an bis an die festen Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Im vierten Jahr Hiskias, des Konigs Judas (das war das siebente Jahr Hoseas, des Sohns Elas, des Konigs Israels), da zog Salmanesser, der Konig zu Assyrien, herauf wider Samaria und belagerte sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'und gewann sie nach dreien Jahren, im sechsten Jahr Hiskias; das ist, im neunten Jahr Hoseas, des Konigs Israels, da ward Samaria gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Und der Konig zu Assyrien fuhrete Israel weg gen Assyrien und setzte sie zu Halah und Habor, am Wasser Gosan, und in die Stadte der Meder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'darum daß sie nicht gehorchet hatten der Stimme des HERRN, ihres Gottes, und ubergangen hatten seinen Bund und alies, was Mose, der Knecht des HERRN, geboten hatte; der hatten sie keinem gehorchet noch getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Im vierzehnten Jahr aber des Konigs Hiskia zog herauf Sanherib, der Konig zu Assyrien, wider alle festen Stadte Judas und nahm sie ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Da sandte Hiskia, der Konig Judas, zum Konige von Assyrien gen Lachis und lieft ihm sagen: Ich habe mich versundiget, kehre urn von mir; was du mir auflegest, will ich tragen. Da legte der Konig von Assyrien auf Hiskia, dem Konige Judas, dreihundert Zentner Silbers und dreiftig Zentner Goldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Also gab Hiskia all das Silber, das im Hause des HERRN und in den Schatzen des Konigshauses funden ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Zur selbigen Zeit zerbrach Hiskia, der Konig Judas, die Türen am Tempel des HERRN und die Bleche, die er selbst hatte uberziehen lassen, und gab sie dem Konige von Assyrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Und der Konig von Assyrien sandte Tharthan und den Erzkammerer und den Rabsake von Lachis zum Konige Hiskia mit grafter Macht gen Jerusalem; und sie zogen herauf. Und da sie hinkamen, hielten sie an der Wassergrube bei dem obern Teich, der da liegt an der Strafte auf dem Acker des Walkmüllers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Und rief dem Konige. Da kam heraus zu ihnen Eliakim, der Sohn Hilkias, der Hofmeister, und Sebena, der Schreiber, und Joah, der Sohn Assaphs, der Kanzler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Und der Erzschenke sprach zu ihnen: Lieber, sagt dem Konige Hiskia: So spricht der grofte Konig, der Konig von Assyrien: Was ist das fur ein Trotz, darauf du dich verlassest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Meinest du, es sei noch Rat und Macht zu streiten? Worauf verlassest du denn nun dich, daß du abtrunnig von mir bist worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Siehe, verlassest du dich auf diesen zerstoftenen Rohrstab, auf Agypten? welcher, so sich jemand drauf lehnet, wird er ihm in die Hand gehen und sie durchbohren. Also ist Pharao, der Konig in Agypten, alien, die sich auf ihn verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Ob ihr aber wolltet zu mir sagen: Wir verlassen uns auf den HERRN, unsern Gott, ist\'s denn nicht der, des Hohen und Altare Hiskia hat abgetan und gesagt zu Juda und Jerusalem: Vor diesem Altar, der zu Jerusalem ist, sollt ihr anbeten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Nun gelobe meinem Herrn, dem Konige von Assyrien; ich will dir zweitausend Rosse geben, daß du mogest Reiter dazu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Wie willst du denn bleiben vor dem geringsten Herrn, einem meines Herrn Untertanen, und verlassest dich auf Agypten urn der Wagen und Reiter willen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Meinest du aber, ich sei ohne den HERRN heraufgezogen, daß ich diese Statte verderbete? Der HERR hat mich\'s geheilien: Zeuch hinauf in dies Land und verderbe es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Da sprach Eliakim, derßohn Hilkias, und Sebena und Joah zum Erzschenken: Rede mit deinen Knechten auf syrisch, denn wir verstehen es; und rede nicht mit uns auf judisch vor den Ohren des Volks, das auf der Mauer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Aber der Erzschenke sprach zu ihnen: Hat mich denn mein Herrzu deinem Herrn oderzu dirgesandt, daß ich solche Worte rede? Ja zu den Mannern, die auf der Mauer sitzen, daß sie mit euch ihren eigenen Mist fressen und ihren Ham saufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Also stund der Erzschenke und rief mit lauter Stimme auf judisch; und redete und sprach: Horet das Wort des grolien Konigs, des Konigs von Assyrien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'So spricht der Konig: Lalit euch Hiskia nicht aufsetzen; denn ervermag euch nicht zu erretten von meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Und lalit euch Hiskia nicht vertrosten auf den HERRN, daß er saget Der HERR wird uns erretten, und diese Stadt wird nicht in die Hande des Konigs von Assyrien gegeben werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Gehorchet Hiskia nicht! Denn so spricht der Konig von Assyrien: Nehmet an meine Gnade und kommet zu mir heraus, so soil jedermann seines Weinstocks und seines Feigenbaums essen und seines Brunnens trinken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'bis ich komme und hole euch in ein Land, das eurem Lande gleich ist, da Korn, Most, Brot, Weinberge, Olbaume, 01 und Honig innen ist; so werdet ihr leben bleiben und nicht sterben. Gehorchet Hiskia nicht; denn er verfuhret euch, daß er spricht: Der HERR wird uns erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Haben auch die Gotter der Heiden ein jeglicher sein Land errettet von der Hand des Konigs von Assyrien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Wo sind die Gotter zu Hemath und Arphad? Wo sind die Gotter zu Sepharvaim, Hena und Iwa? Haben sie auch Samaria errettet von meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Wo ist ein Gott unter aller Lande Gottern, die ihr Land haben von meiner Hand errettet, daß der HERR sollte Jerusalem von meiner Hand erretten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Das Volk aber schwieg stille und antwortete ihm nichts; denn der Konig hatte geboten und gesagt: Antwortet ihm nichts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Da kam Eliakim, derßohn Hilkias, der Hofmeister, und Sebena, der Schreiber, und Joah, der Sohn Assaphs, der Kanzler, zu Hiskia mit zerrissenen Kleidern und sagten ihm an die Worte des Erzschenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Da der Konig Hiskia das horete, zerrift er seine Kleider und legte einen Sack an und ging in das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Und sandte Eliakim, den Hofmeister, und Sebena, den Schreiber, samt den altesten Priestern, mit Sacken angetan, zu dem Propheten Jesaja, dem Sohn Amoz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Und sie sprachen zu ihm: So sagt Hiskia: Das ist ein Tag der Not und Scheltens und Lasterns; die Kinder sind kommen an die Geburt, und ist keine Kraft da zu gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Ob vielleicht der HERR, dein Gott, horen wollte alle Worte des Erzschenken, den sein Herr, der Konig von Assyrien, gesandt hat, Hohn zu sprechen dem lebendigen Gott und zu schelten mit Worten, die der HERR, dein Gott, gehoret hat. So hebe dein Gebet auf fur die ubrigen, die noch vorhanden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Und da die Knechte des Konigs Hiskia zu Jesaja kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'sprach Jesaja zu ihnen: So saget eurem Herrn: So spricht der HERR: Furchte dich nicht vor den Worten, die du gehoret hast, damit mich die Knaben des Konigs von Assyrien gelastert haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Siehe, ich will ihm einen Geist geben, daß er ein Gerucht horen wird und wieder in sein Land ziehen; und will ihn durchs Schwert fallen in seinem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Und da der Erzschenke wiederkam, fand er den Konig von Assyrien streiten wider Libna; denn er hatte gehoret, daß er von Lachis gezogen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Und da er horete von Thirhaka, dem Konige der Mohren: Siehe, er ist ausgezogen, mit dir zu streiten, wandte er urn und sandte Boten zu Hiskia und lieft ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'So saget Hiskia, dem Konige Judas: Laft dich deinen Gott nicht aufsetzen, auf den du dich verlassest, und sprichst: Jerusalem wird nicht in die Hande des Konigs von Assyrien gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Siehe, du hast gehoret, was die Konige von Assyrien getan haben alien Landen und sie verbannet; und du solltest errettet werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Haben der Heiden Gotter auch sie errettet, welche meine Vater haben verderbet: Gosan, Haran, Rezeph und die Kinder Edens, die zu Thelassar waren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Wo ist der Konig zu Hemath, der Konig zu Arphad und der Konig der Stadt Sepharvaim, Hena und Iwa?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Und da Hiskia die Briefe von den Boten empfangen und gelesen hatte, ging er hinauf zum Hause des HERRN und breitete sie aus vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Und betete vor dem HERRN und sprach: HERR, Gott Israels, derdu uber Cherubim sitzest, du bist allein Gott unter alien Konigreichen auf Erden, du hast Himmel und Erde gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'HERR, neige deine Ohren und hore, tu deine Augen auf und siehe, und hore die Worte Sanheribs, der hergesandt hat, Hohn zu sprechen dem lebendigen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Es istwahr, HERR, die Konige von Assyrien haben die Heiden mitdem Schwert umgebracht und ihr Land');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'und haben ihre Gotter ins Feuer geworfen. Denn es waren nicht Gotter, sondern Menschenhande Werk, Holz und Steine; darum haben sie sie umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Nun aber, HERR, unserßott, hilfunsaus seiner Hand, auf daß alle Konigreiche auf Erden erkennen, daß du, HERR, allein Gott bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Da sandte Jesaja, der Sohn Amoz, zu Hiskia und liefi ihm sagen: So spricht der HERR, der Gott Israels: Was du zu mir gebetet hast urn Sanherib, den Konig von Assyrien, das habe ich gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Das ist\'s, das der HERR wider ihn geredet hat: Die Jungfrau, die Tochter Zion, verachtet dich und spottet dein; die Tochter Jerusalem schuttelt ihr Haupt dir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Wen hast du gehohnet und gelastert? Uber wen hast du deine Stimme erhoben? Du hast deine Augen erhoben wider den Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Du hast den HERRN durch deine Boten gehohnet und gesagt: Ich bin durch die Menge meiner Wagen auf die Hohe der Berge gestiegen, auf den Seiten des Libanon; ich habe seine hohen Zedern und auserlesenen Tannen abgehauen und bin kommen an die aufterste Herberge des Waldes seines Karmels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'ich habe gegraben und ausgetrunken die fremden Wasser und habe vertrocknet mit meinen Fuftsohlen die Seen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Hast du aber nicht gehoret, daß ich solches lange zuvor getan habe, und von Anfang habe ich\'s bereitet? Nun, jetzt aber habe ich\'s kommen lassen, daß feste Stadte würden fallen in einen wüsten Steinhaufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'und die drinnen wohnen, mattwerden und sich furchten und schamen müftten und werden wie das Gras auf dem Felde und wie das grune Kraut zum Heu auf den Dachern, das verdorret, ehe denn es reif wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Ich weift dein Wohnen, dein Aus- und Einziehen, und daß du tobest wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Weil du denn wider mich tobest, und dein Gbermut vor meine Ohren heraufkommen ist, so will ich dir einen Ring an deine Nase legen und ein Gebift in dein Maui und will dich den Weg wiederum fuhren, da du herkommen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Und sei dir ein Zeichen: In diesem Jahr ift, was zertreten ist; im andern Jahr, was selber wachst; im dritten Jahr saet und erntet und pflanzet Weinberge und esset ihre Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Und die Tochter Juda, die errettet und uberblieben ist, wird fürder unter sich wurzeln und uber sich Frucht tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Denn von Jerusalem werden ausgehen, die uberblieben sind, und die Erretteten vom Berge Zion. Der Eifer des HERRN Zebaoth wird solches tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Darum spricht der HERR vom Konige zu Assyrien also: Er soil nicht in diese Stadt kommen und keinen Pfeil drein schieften und kein Schild davor kommen und soli keinen Wall drum schütten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'sondern ersoll den Weg wiederum ziehen, den er kommen ist, und soil in diese Stadt nicht kommen; der HERR sagtes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Und ich will diese Stadt beschirmen, daß ich ihr helfe urn meinetwillen und urn Davids, meines Knechts, willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Und in derselben Nacht fuhr aus der Engel des HERRN und schlug im Lager von Assyrien hundertundfunfundachtzigtausend Mann. Und da sie sich des Morgens fruhe aufmachten, siehe, da lag es alles eitel tote Leichname.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Also brach Sanherib, der Konig von Assyrien, auf und zog weg und kehrete urn; und blieb zu Ninive.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Und da eranbetete im Hause Nisrochs, seines Gottes, schlugen ihn mit dem Schwert Adramelech und Sarezer, seine Sohne; und sie entrannen ins Land Ararat. Und sein Sohn Assar-Haddon ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Zu der Zeit ward Hiskia todkrank. Und der Prophet Jesaja, der Sohn Amoz, kam zu ihm und sprach zu ihm: So spricht der HERR: Beschicke dein Haus; denn du wirst sterben und nicht leben bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Er aber wandte sein Antlitz zur Wand und betete zum HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ach, HERR, gedenke doch, daß ich vor dir treulich gewandelt habe und mit rechtschaffenem Herzen und habe getan, das dirwohlgefallt. Und Hiskia weinete sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Da aber Jesaja noch nicht zur Stadt halb hinausgegangen war, kam des HERRN Wort zu ihm und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Kehre urn und sage Hiskia, dem Fursten meines Volks: So spricht der HERR, der Gott deines Vaters David: Ich habe dein Gebet gehoret und deine Tranen gesehen. Siehe, ich. will dich gesund machen; am dritten Tage wirst du hinauf in das Haus des HERRN gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Und will funfzehn Jahre zu deinem Leben tun und dich und diese Stadt erretten von dem Konige zu Assyrien und diese Stadt beschirmen urn meinetwillen und urn meines Knechts David willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Und Jesaja sprach: Bringet herein Stuck Feigen! Und da sie die brachten, legten sie sie auf die Druse; und erward gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hiskia aber sprach zu Jesaja: Welches ist das Zeichen, dad mich der HERR wird gesund machen, und ich in des HERRN Haus hinaufgehen werde am dritten Tage?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaja sprach: Das Zeichen wirst du haben vom HERRN, daß der HERR tun wird, was er geredet hat. Soil der Schatten zehn Stufen fürder gehen, Oder zehn Stufen zuruckgehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia sprach: Es ist leicht, dad der Schatten zehn Stufen niederwarts gehe; das will ich nicht, sondern dad er zehn Stufen hinter sich zuruckgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Da riefder Prophet Jesaja den HERRN an; und der Schatten ging hinter sich zuruck zehn Stufen am Zeiger Ahas die erwar niederwarts gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Zu der Zeit sandte Brodach, der Sohn Baledans, des Sohns Baledans, Konigs zu Babel, Briefe und Geschenke zu Hiskia; denn er hatte gehoret, daß Hiskia krank war gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Hiskia aber war frohlich mit ihnen und zeigte ihnen das ganze Schatzhaus, Silber, Gold, Spezerei und das beste Ol und die Harnischkammer und alles, was in seinen Schatzen vorhanden war. Es war nichts in seinem Hause und in seiner ganzen Herrschaft, das ihnen Hiskia nicht zeigete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Da kam Jesaja, der Prophet, zu dem Konige Hiskia und sprach zu ihm: Was haben diese Leute gesagt und woher sind sie zu dir kommen? Hiskia sprach: Sie sind aus fernen Landen zu mir kommen, von Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Er sprach: Was haben sie gesehen in deinem Hause? Hiskia sprach: Sie haben alles gesehen, was in meinem Hause ist; und ist nichts in meinen Schatzen, das ich nicht ihnen gezeiget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Da sprach Jesaja zu Hiskia: Hore des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Siehe, es kommt die Zeit, dad alles wird gen Babel weggefuhret werden aus deinem Hause, und was deine Vater gesammelt haben bis auf diesen Tag; und wird nichts übergelassen werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Dazu der Kinder, die von dir kommen, die du zeugen wirst, werden genommen werden, dad sie Kammerer seien im Palast des Konigs zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia aber sprach zu Jesaja: Das ist gut, das der HERR geredet hat. Und sprach weiter: Es wird doch Friede und Treue sein zu meinen Zeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Was mehr von Hiskia zu sagen ist, und alle seine Macht, und was ergetan hat, und der Teich und die Wasserrohren, damit er Wasser in die Stadt geleitet hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Und Hiskia entschlief mit seinen Vatern. Und Manasse, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse war zwolf Jahre alt, da er Konig ward, und regierete funfundfunfzig Jahre zu Jerusalem. Seine Mutter hiefi Hephzi-Bah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Und ertat, das dem HERRN ubel gefiel, nach den Greueln der Heiden, die der HERR vor den Kindern Israel vertrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Und verkehrete sich und bauete die Hohen, die sein Vater Hiskia hatte abgebracht, und richtete Baal Altare auf und machte Haine, wie Ahab, der Konig Israels, getan hatte, und betete an alierlei Heer am Himmel und dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Und bauete Altare im Hause des HERRN, davon der HERR gesagt hatte: Ich will meinen Namen zu Jerusalem setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Und er bauete alien Heeren am Himmel Altare, in beiden Hofen am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Und lied seinen Sohn durchs Feuer gehen und achtete auf Vogelgeschrei und Zeichen und hielt Wahrsager und Zeichendeuter; und tat des viel, das dem HERRN ubel gefiel, damit er ihn erzurnete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Er setzte auch einen Haingotzen, den er gemacht hatte, in das Haus, von welchem der HERR zu David und zu Salomo, seinem Sohn, gesagt hatte: In diesem Hause und zu Jerusalem, die ich erwahlet habe aus alien Stammen Israels, will ich meinen Namen setzen ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'und will den Fud Israels nicht mehr bewegen lassen vom Lande, das ich ihren Vatern gegeben habe, so doch, so sie halten und tun nach allem, das ich geboten habe, und nach allem Gesetz, das mein Knecht Mose ihnen geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Aber sie gehorchten nicht, sondern Manasse verfuhrete sie, daü sie arger taten denn die Heiden, die der HERR vor den Kindern Israel vertilget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Da redete der HERR durch seine Knechte, die Propheten und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Darum dad Manasse, der Konig Judas, hat diese Greuel getan, die arger sind denn alle Greuel, so die Amoriter getan haben, die vor ihm gewesen sind, und hat auch Juda sundigen gemacht mit seinen Gotzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'darum spricht der HERR, der Gott Israels, also: Siehe, ich will Ungluck uber Jerusalem und Juda bringen, dad, wer es horen wird, dem sollen seine beiden Ohren gellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Und will uber Jerusalem die Medschnur Samarias ziehen und das Gewicht des Hauses Ahab; und will Jerusalem ausschutten, wie man Schusseln ausschuttet, und will sie umsturzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Und ich will etliche meines Erbteils uberbleiben lassen und sie geben in die Hande ihrer Feinde, dad sie ein Raub und Reiden werden aller ihrer Feinde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'darum dad sie getan haben, das mir ubel gefallt, und haben mich erzurnet von dem Tage an, da ihre Vater aus Agypten gezogen sind, bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Auch vergod Manasse sehrviel unschuldig Biut, bis dad Jerusalem hie und da voll ward; ohne die Sunde, damit er Juda sundigen machte, dad sie taten, das dem HERRN ubel gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Was aber mehr von Manasse zu sagen ist, und alles, was er getan hat, und seine Sunde, die er tat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Und Manasse entschlief mitseinen Vatern und ward begraben im Garten an seinem Hause, namlich im Garten Usas. Und sein Sohn Amon ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Zweiundzwanzig Jahre alt war Amon, da er Konig ward, und regierete zwei Jahre zu Jerusalem. Seine Mutter hieti Mesulemeth, eine Tochter Haruz von Jatba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Und tat, das dem HERRN ubel gefiel, wie sein Vater Manasse getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'und wandelte in allem Wege, den sein Vater gewandelt hatte, und dienete den Gotzen, welchen sein Vater gedienet hatte, und betete sie an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Und verlieft den HERRN, seiner Vater Gott, und wandelte nicht im Wege des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Und seine Knechte machten einen Bund wider Amon und toteten den Konig in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Aber das Volk im Lande schlug alle, die den Bund gemacht hatten wider den Konig Amon. Und das Volk im Lande machte Josia, seinen Sohn, zum Konige an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Was aber Amon mehr getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Und man begrub ihn in seinem Grabe, im Garten Usas. Und sein Sohn Josia ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josia war acht Jahre alt, da er Konig ward, und regierete einundddreitüg Jahre zu Jerusalem. Seine Mutter hiefi Jedida, eine Tochter Adajas von Bazkath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Und tat, das dem HERRN wohlgefiel; und wandelte in allem Wege seines Vaters David und wich nicht weder zur Rechten noch zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Und im achtzehnten Jahrdes Konigs Josia sandte der Konig hin Saphan, den Sohn Azaljas, des Sohns Mesuliams, den Schreiber, in das Haus des HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Gehe hinauf zu dem Hohenpriester Hilkia, daß man ihnen gebe das Geld, das zum Hause des HERRN gebracht ist, das die Huter an der Schwelle gesammelt haben vom Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'daü sie es geben den Arbeitern, die bestellet sind im Hause des HERRN, und geben es den Arbeitern am Hause des HERRN, daß sie bessern, was baufallig ist am Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'namlich den Zimmerleuten und Bauleuten und Maurern, und die da Holz und gehauene Steine kaufen sollen, das Haus zu bessern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'doch daß man keine Rechnung von ihnen nehme vom Gelde, das unter ihre Hand getan wird, sondern daß sie es auf Glauben handeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Und der Hohepriester Hilkia sprach zu dem Schreiber Saphan: Ich habe das Gesetzbuch gefunden im Hause des HERRN. Und Hilkia gab das Buch Saphan, daß er\'s lase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Und Saphan, der Schreiber, brachte es dem Konige und sagte es ihm wieder und sprach: Deine Knechte haben das Geld zusammengestoppelt, das im Hause gefunden ist, und haben es den Arbeitern gegeben, die bestellet sind am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Auch sagte Saphan, der Schreiber, dem Konige und sprach: Hilkia, der Priester, gab mir ein Buch. Und Saphan las es vor dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Da aber der Konig horete die Worte im Gesetzbuch, zerriti er seine Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Und der Konig gebot Hilkia, dem Priester, und Ahikam, dem Sohn Saphans, und Achbor, dem Sohn Michajas, und Saphan, dem Schreiber, und Asaja, dem Knechte des Konigs, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Gehet hin und fraget den HERRN fur mich, fur das Volk und fur ganz Juda urn die Worte dieses Buchs, das gefunden ist; denn es ist ein grafter Grimm des HERRN, der über uns entbrannt ist, darum daß unsere Vater nicht gehorchet haben den Worten dieses Buchs, daß sie taten alles, was drinnen geschrieben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Da ging hin Hilkia, der Priester, Ahikam, Achbor, Saphan und Asaja zu der Prophetin Hulda, dem Weibe Sallums, des Sohns Thikwas, des Sohns Harhams, des Huters der Kleider, und sie wohnete zu Jerusalem im andern Teil; und sie redeten mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Sie aber sprach zu ihnen: So sprichtder HERR, der Gott Israels: Saget dem Mann, der euch zu mir gesandt hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'So spricht der HERR: Siehe, ich will Ungluck über diese Statte und ihre Einwohner bringen, alle Worte des Gesetzes, die der Konig Juda hat lassen lesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'darum daß sie mich verlassen und andern Gottern gerauchert haben, daß sie mich erzurneten mit alien Werken ihrer Hande; darum wird mein Grimm sich wider diese Statte anzünden und nicht ausgeloschet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Aber dem Konige Judas, der euch gesandt hat, den HERRN zu fragen, sollt ihr so sagen: So spricht der HERR, der Gott Israels:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Darum daß dein Herz erweichet ist über den Worten, die du gehoret hast, und hast dich gedemütiget vor dem HERRN, da du horetest was ich geredet habe wider diese Statte und ihre Einwohner, daß sie sollen eine Verwüstung und Fluch sein, und hast deine Kleider zerrissen und hast geweinet vor mir, so habe ich\'s auch erhoret, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Darum will ich dich zu deinen Vatern sammeln, daß du mit Frieden in dein Grab versammelt werdest, und deine Augen nicht sehen all das Unglück, das ich über diese Statte bringen will. Und sie sagten es dem Konige wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Und der Konig sandte hin, und es versammelten sich zu ihm alle Altesten in Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Und der Konig ging hinauf ins Haus des HERRN, und alle Manner von Juda und alle Einwohner zu Jerusalem mit ihm, Priester und Propheten und alles Volk, beide klein und groli; und man las vor ihren Ohren alle Worte des Buchs vom Bunde, das im Hause des HERRN gefunden war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Und der Konig trat an eine Saule und machte einen Bund vor dem HERRN, daß sie sollten wandeln dem HERRN nach und halten seine Gebote, Zeugnisse und Rechte von ganzem Herzen und von ganzer Seele, dafi sie aufrichteten die Worte dieses Bundes, die geschrieben stunden in diesem Buch. Und alles Volk trat in den Bund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Und der Konig gebot dem Hohenpriester Hilkia und den Priestern der andern Ordnung und den Hütern an der Schwelle, daß sie sollten aus dem Tempel des HERRN tun alles Gezeug, das dem Baal und dem Hain und allem Heerdes Himmels gemacht war. Und verbrannten sie auften vor Jerusalem im Tal Kidron; und ihr Staub ward getragen gen Bethel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Und er tat ab die Kamarim, welche die Konige Judas hatten gestiftet, zu rauchern aufden Hohen in den Stadten Judas und urn Jerusalem her, auch die Raucherer des Baal und der Sonne und des Mondes und der Planeten und alles Heers am Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Und lieft den Hain aus dem Hause des HERRN führen hinaus vor Jerusalem in den Bach Kidron, und verbrannten ihn im Bach Kidron und machte ihn zu Staub; und warf den Staub auf die Graber der gemeinen Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Und er brach ab die Hauser der Hurer, die an dem Hause des HERRN waren, darinnen die Weiber wirkten Hauser zum Hain.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Und er lieft kommen alle Priester aus den Stadten Judas und verunreinigte die Hohen, da die Priester raucherten, von Geba an bis gen Berseba; und brach ab die Hohen in den Toren, die in der Tur des Tors waren Josuas, des Stadtvogts, welches war zur Linken, wenn man zum Tor der Stadt gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Doch hatten die Priester der Hohen nie geopfert auf dem Altar des HERRN zu Jerusalem, sondern alien des ungesauerten Brots unter ihren Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Er verunreinigte auch das Thopheth im Tal der Kinder Hinnom, daß niemand seinen Sohn Oder seine Tochterdem Molech durchs Feuer liefte gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Und tat ab die Rosse, welche die Konige Judas hatten der Sonne gesetzt im Eingange des HERRN Hauses an der Kammer Nethan-Melechs, des Kammerers, der zu Parwarim war; und die Wagen der Sonne verbrannte er mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Und die Altare auf dem Dache im Saal Ahas, die die Konige Judas gemacht hatten, und die Altare, die Manasse gemacht hatte in den zweien Hofen des HERRN Hauses, brach der Konig ab; und lief von dannen und warf ihren Staub in den Bach Kidron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Auch die Hohen, die vor Jerusalem waren, zur Rechten am Berge Mashith, die Salomo, der Konig Israels, gebauet hatte Asthoreth, dem Greuel von Zidon, und Kamos, dem Greuel von Moab, und Milkom, dem Greuel der Kinder Ammon, verunreinigte der Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Und zerbrach die Saulen und rottete aus die Haine und fullete ihre Statte mit Menschenknochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Auch den Altar zu Bethel, die Hohe, die Jerobeam gemacht hatte, der Sohn Nebats, der Israel sundigen machte, denselben Altar brach er ab und die Hohe; und verbrannte die Hohe und machte sie zu Staub und verbrannte den Hain.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Und Josia wandte sich und sah die Graber, die da waren auf dem Berge; und sandte hin und liefi die Knochen aus den Grabern holen und verbrannte sie auf dem Altar und verunreinigte ihn nach dem Wort des HERRN, das der Mann Gottes ausgerufen hatte, der solches ausrief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Und ersprach: Was istdas fur ein Grabmal, das ich sehe? Und die Leute in der Stadt sprachen zu ihm: Es ist das Grab des Mannes Gottes, der von Juda kam und rief solches aus, das du getan hast, wider den Altar zu Bethel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Und ersprach: Lalit ihn liegen; niemand bewege seine Gebeine! Also wurden seine Gebeine errettet mit den Gebeinen des Propheten, der von Samaria kommen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Er tat auch weg alle Hauser der Hohen in den Stadten Samarias, welche die Konige Israels gemacht hatten zu erzürnen; und tat mit ihnen allerdinge, wie er zu Bethel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Und er opferte alle Priester der Hohen, die daselbst waren, auf den Altaren; und verbrannte also Menschenbeine drauf. Und kam wiedergen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Und der Konig gebot dem Volk und sprach: Haltet dem HERRN, eurem Gott, Passah, wie geschrieben stehet im Buch dieses Bundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Denn es war kein Passah so gehalten, als dieses, von der Richter Zeit an, die Israel gerichtet haben, und in alien Zeiten der Konige Israels und der Konige Judas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'sondern im achtzehnten Jahr des Konigs Josia ward dies Passah gehalten dem HERRN zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Auch fegte Josia aus alle Wahrsager, Zeichendeuter, Bilder und Gotzen und alle Greuel, die im Lande Juda und zu Jerusalem ersehen wurden, auf daß er aufrichtete die Worte des Gesetzes, die geschrieben stunden im Buch, das Hilkia, der Priester, fand im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Sein gleichen war vor ihm kein Konig gewesen, der so von ganzem Herzen, von ganzer Seele, von alien Kraften sich zum HERRN bekehrete nach allem Gesetz Moses; und nach ihm kam sein gleichen nicht auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Doch kehrete sich der HERR nicht von dem Grimm seines groften Zorns, damit er uber Juda erzumet war um aller der Reizungen willen, damit ihn Manasse gereizet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Und der HERR sprach: Ich will Juda auch von meinem Angesicht tun, wie ich Israel weggetan habe; und will diese Stadt verwerfen, die ich erwahlet hatte, namlich Jerusalem und das Haus, davon ich gesagt habe: Mein Name soil daselbst sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Was aber mehr von Josia zu sagen ist, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Zu seiner Zeit zog Pharao-Necho, der Konig in Agypten, herauf wider den Konig von Assyrien an das Wasser Phrath. Aber der Konig Josia zog ihm entgegen und starb zu Megiddo, da er ihn gesehen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Und seine Knechte fuhreten ihn tot von Megiddo und brachten ihn gen Jerusalem und begruben ihn in seinem Grabe. Und das Volk im Lande nahm Joahas, den Sohn Josias, und salbeten ihn und machten ihn zum Konige an seines Vaters Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Dreiundzwanzig Jahre war Joahas alt, da er Konig ward, und regierete drei Monden zu Jerusalem. Seine Mutter hiefi Hamutal, eine Tochter Jeremias von Libna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Und tat, das dem HERRN libel gefiel, wie seine Vater getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Aber Pharao-Necho ting ihn zu Riblath im Lande Hemath, dall er nicht regieren sollte zu Jerusalem; und legte eine Schatzung aufs Land, hundert Zentner Silbers und einen Zentner Goldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Und Pharao-Necho machte zum Konige Eliakim, den Sohn Josias, anstatt seines Vaters Josia und wandte seinen Namen Jojakim. Aber Joahas nahm er und brachte ihn nach Agypten; daselbst starb er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Und Jojakim gab das Silber und Gold Pharao; doch schatzte er das Land, daß er solch Silber gabe nach Befehl Pharaos; einen jeglichen nach seinem Vermogen schatzte er am Silber und Gold unter dem Volk im Lande, daß er dem Pharao-Necho gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Fünfundzwanzig Jahre alt war Jojakim, da er Konig ward, und regierete elf Jahre zu Jerusalem. Seine Mutter hiefi Sebuda, eine Tochter Pedajas von Ruma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Und tat, das dem HERRN ubel gefiei, wie seine Vater getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Zu seiner Zeit zog herauf Nebukadnezar der Konig zu Babel; und Jojakim ward ihm untertanig drei Jahre. Und er wandte sich und ward abtrunnig von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Und der HERR liel J auf ihn Kriegsknechte kommen aus Chaldaa, aus Syrien, aus Moab, aus den Kindern Ammon und lieli sie in Juda kommen, daß sie ihn umbrachten, nach dem Wort des HERRN, das er geredet hatte durch seine Knechte, die Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Es geschah aber Juda also nach dem Wort des HERRN, daß er sie von seinem Angesicht tate, um der Sünde willen Manasses, die er getan hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'auch um des unschuldigen Bluts willen, das er vergoß, und machte Jerusalem voll mit unschuldigem Blut, wollte der HERR nicht vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Was mehr zu sagen ist von Jojakim, und alles, was er getan hat, siehe, das ist geschrieben in der Chronik der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Und Jojakim entschlief mit seinen Vatern; und sein Sohn Jojachin ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Und der Konig in Agypten zog nicht mehr aus seinem Lande; denn der Konig zu Babel hatte ihm genommen alles, was des Konigs in Agypten war, vom Bach Agyptens an bis an das Wasser Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Achtzehn Jahre alt war Jojachin, da er Konig ward, und regierete drei Monden zu Jerusalem. Seine Mutter hiefi Nehustha, eine Tochter Elnathans von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Und tat, das dem HERRN ubel gefiel, wie sein Vater getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Zu der Zeit zogen herauf die Knechte Nebukadnezars, des Konigs zu Babel, gen Jerusalem und kamen an die Stadt mit Bollwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Und da Nebukadnezar zur Stadt kam und seine Knechte, belagerte er sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Aber Jojachin, der Konig Judas, ging heraus zum Konige von Babel mit seiner Mutter, mit seinen Knechten, mit seinen Obersten und Kammerern; und der Konig von Babel nahm ihn auf im achten Jahr seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Und nahm von dannen heraus alle Schatze im Hause des HERRN und im Hause des Konigs und zerschlug alle güldenen Gefaße, die Salomo, der Konig Israels, gemacht hatte im Tempel des HERRN wie denn der HERR geredet hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'und fuhrete weg das ganze Jerusalem, alle Obersten, alle Gewaltigen, zehntausend Gefangene und alle Zimmerleute und alle Schmiede; und lieli nichts übrig, denn gering Volk des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Und fuhrete weg Jojachin gen Babel, die Mutter des Konigs, die Weiber des Konigs und seine Kammerer; dazu die Machtigen im Lande fuhrete er auch gefangen von Jerusalem gen Babel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'und was der besten Leute waren, siebentausend, und die Zimmerleute und Schmiede, tausend, alle starken Kriegsmanner; und der Konig von Babel brachte sie gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Und der Konig von Babel machte Mathanja, seinen Vetter, zum Konige an seiner Statt und wandelte seinen Namen Zidekia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Einundzwanzig Jahre alt war Zidekia, da er Konig ward, und regierete elf Jahre zu Jerusalem. Seine Mutter hieli Hamital, eine Tochter Jeremias von Libna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Und ertat, das dem HERRN ubel gefiel, wie Jojakim getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Denn es geschah also mit Jerusalem und Juda aus dem Zorn des HERRN, bis daß er sie von seinem Angesicht wurfe. Und Zidekia ward abtrunnig vom Konige zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Und es begab sich im neunten Jahr seines Konigreichs, am zehnten Tage des zehnten Monden, kam Nebukadnezar, der Konig zu Babel, mit aller seiner Macht wider Jerusalem; und sie lagerten sich wider sie und baueten einen Schutt urn sie her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Also ward die Stadt belagert bis ins elfte Jahr des Konigs Zidekia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Aber im neunten des Monden ward der Hunger stark in der Stadt, daß das Volk des Landes nichts zu essen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Da brach man in die Stadt; und alle Kriegsmanner flohen bei der Nacht des Weges von dem Tor zwischen den zwo Mauern, der zu des Konigs Garten gehet. Aber die Chaldaer lagen urn die Stadt. Und erfloh des Weges zum blachen Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Aber die Macht der Chaldaer jagten dem Konige nach und ergriffen ihn im blachen Felde zu Jericho; und alle Kriegsleute, die bei ihm waren, wurden von ihm zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Sie aber griffen den Konig und fuhreten ihn hinauf zum Konige von Babel gen Riblath; und sie sprachen ein Urteil uber ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Und sie schlachteten die Kinder Zidekias vor seinen Augen und blendeten Zidekia seine Augen und banden ihn mit Ketten und fuhreten ihn gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Am siebenten Tage des funften Monden, das ist das neunzehnte Jahr Nebukadnezars, des Konigs zu Babel, kam Nebusar-Adan, der Hofmeister, des Konigs zu Babel Knecht, gen Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'und verbrannte das Haus des HERRN und das Haus des Konigs und alle Hauser zu Jerusalem und alle großen Hauser verbrannte er mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Und die ganze Macht der Chaldaer, die mit dem Hofmeister war, zerbrach die Mauern urn Jerusalem her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Das andere Volk aber, das ubrig war in der Stadt und die zum Konige von Babel fielen, und den andern Pobel fuhrete Nebusar-Adan, der Hofmeister, weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Und von den Geringsten im Lande ließ der Hofmeister Weingartner und Ackerleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Aber die ehernen Saulen am Hause des HERRN und die Gestuhle und das eherne Meer, das am Hause des HERRN war, zerbrachen die Chaldaer und fuhreten das Erz gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Und die Topfe, Schaufeln, Messer, Loffel und alle ehernen Gefaße, damit man dienete, nahmen sie weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Dazu nahm der Hofmeister die Pfannen und Becken, und was gulden und silbern war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'zwo Saulen, ein Meer und die Gestuhle, die Salomo gemacht hatte zum Hause des HERRN. Es war nicht zu wagen das Erz aller dieser Gefalie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Achtzehn Ellen hoch war eine Saule, und ihr Knauf drauf war auch ehern und drei Ellen hoch, und die Reife und Granatapfel an dem Knauf umherwar alles ehern. Auf die Weise war auch die andere Saule mit den Reifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Und der Hofmeister nahm den Priester Seraja der ersten Ordnung und den Priester Zephanja der andern Ordnung und drei Turhuter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'und einen Kammerer aus der Stadt, der gesetzt war uber die Kriegsmanner, und fünf Manner, die stets vor dem Konige waren, die in der Stadt funden wurden, und Sopher, den Feldhauptmann, der das Volk im Lande kriegen lehrete, und sechzig Mann vom Volk auf dem Lande, die in der Stadt funden wurden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'diese nahm Nebusar-Adan, der Hofmeister, und brachte sie zum Konige von Babel gen Riblath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Und der Konig von Babel schlug sie tot zu Riblath im Lande Hemath. Also ward Juda weggefuhret aus seinem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Aber uber das ubrige Volk im Lande Juda, das Nebukadnezar, der Konig von Babel, uberliefi, setzte er Gedalja, den Sohn Ahikams, des Sohns Saphans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Da nun all das Kriegsvolk, Hauptleute und die Manner horeten, daß der Konig von Babel Gedalja gesetzt hatte, kamen sie zu Gedalja gen Mizpa, namlich Ismael, der Sohn Nethanjas, und Johanan, der Sohn Kareahs, und Seraja, der Sohn Thanhumeths, der Netophathiter, und Jaesanja, der Sohn Maechathis, samt ihren Mannern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Und Gedalja schwur ihnen und ihren Mannern und sprach zu ihnen: Furchtet euch nicht, untertan zu sein den Chaldaern; bleibet im Lande und seid untertanig dem Konige von Babel, so wird\'s euch wohlgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Aber im siebenten Monden kam Ismael, der Sohn Nethanjas, des Sohns Elisamas, von koniglichem Geschlecht, und zehn Manner mit ihm und schlugen Gedalja tot, dazu die Juden und Chaldaer, die bei ihm waren zu Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Da machten sich auf alles Volk, beide klein und groß, und die Obersten des Krieges, und kamen nach Agypten; denn sie furchteten sich vor den Chaldaern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Aber im siebenunddreißigsten Jahr, nachdem Jojachin, der Konig Judas, weggefuhret war, am siebenundzwanzigsten Tage des zwolften Monden, hub Evil-Merodach, der Konig zu Babel, im ersten Jahr seines Konigreichs, das Haupt Jojachins, des Konigs Judas, aus dem Kerker hervor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Und redete freundlich mit ihm und setzte seinen Stuhl uber die Stühle der Konige, die bei ihm waren zu Babel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'und wandelte die Kleider seines Gefangnisses; und er aß allewege vor ihm sein Leben lang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'und bestimmte ihm sein Teil, das man ihm allewege gab vom Konige, auf einen jeglichen Tag sein ganz Leben lang. Das erste Buch der Chronik');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Seth, Enos,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalaleel, Jared,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henoch, Methusalah, Lamech,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noah, Sem, Ham, Japheth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Die Kinder Japheths sind diese: Gomer, Magog, Madai, Javan, Thubal, Mesech, Thiras.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Die Kinder aber Gomers sind: Askenas, Riphath, Thogarma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Die Kinder Javans sind: Elisa, Tharsisa, Chitim, Dodanim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Die Kinder Hams sind: Chus, Mizraim, Put, Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Die Kinder aber Chus sind: Seba, Hevila, Sabtha, Ragema, Sabthecha. Die Kinder aber Ragemas sind: Scheba und Dedan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Chus aberzeugete Nimrod; der ting an gewaltig zu sein auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim zeugete Ludim, Anamim, Lehabim, Naphthuhim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Pathrusim, Kasluhim (von welchen sind auskommen die Philistim) und Kaphthorim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan aber zeugete Zidon, seinen ersten Sohn, und Heth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Jebusi, Amori, Girgosi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hevi, Arki, Sini,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arwadi, Zemari und Hemathi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Die Kinder Sems sind diese: Elam, Assur, Arphachsad, Lud, Aram, Uz, Hul, Gether und Maseeh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arphachsad aber zeugete Salah; Salah zeugete Eber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eber aber wurden zween Sohne geboren; der eine hieli Peleg, darum daß zu seiner Zeit das Land zerteilet ward; und sein Bruder hieli Jaktan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Jaktan aber zeugete Almodad, Saleph, Hazarmaveth, Jarah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Usal, Dikla,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Scheba,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophir, Hevila und Jobab. Das sind alle Kinder Jaktans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphachsad, Salah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tharah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, das ist Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Die Kinder aber Abrahams sind: Isaak und Ismael.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Dies ist ihr Geschlecht: der erste Sohn Ismaels Nebajoth, Kedar, Adbeel, Mibsam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Masa, Hadad, Thema,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jethur, Naphis, Kedma. Das sind die Kinder Ismaels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Die Kinder aber Keturas, des Kebsweibes Abrahams: die gebar Simran, Jaksan, Medan, Midian, Jesbak, Suah. Aber die Kinder Jaksans sind: Scheba und Dedan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Und die Kinder Midians sind: Epha, Epher, Henoch, Abida, Eldaa. Dies sind alle Kinder der Ketura.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraham zeugete Isaak. Die Kinder aber Isaaks sind: Esau und Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Die Kinder Esaus sind: Eliphas, Reguel, Jeus, Jaelam, Korah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Die Kinder Eliphas sind: Theman, Omar, Zephi, Gaetham, Kenas, Thimna, Amalek.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Die Kinder Reguels sind: Nahath, Serah, Samma und Misa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Die Kinder Seirs sind: Lothan, Sobal, Zibeon, Ana, Dison, Ezer, Disan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Die Kinder Lothans sind: Hori, Homam; und Thimna war eine Schwester Lothans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Die Kinder Sobals sind: Alian, Manahath, Ebal, Sephi, Onam. Die Kinder Zibeons sind: Aja und Ana.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Die Kinder Anas: Dison. Die Kinder Disons sind: Hamran, Esban, Jethran, Cheran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Die Kinder Ezers sind: Bilhan, Saewan, Jaekan. Die Kinder Disans sind: Uz und Aran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Dies sind die Konige, die regieret haben im Lande Edom, ehe denn ein Konig regierete unter den Kindern Israel: Bela, der Sohn Beors; und seine Stadt hieli Dinhaba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Und da Bela starb, ward Konig an seiner Statt Jobab, der Sohn Serahs, von Bazra.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Und da Jobab starb, ward Konig an seiner Statt Husam aus der Themaniter Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Da Husam starb, ward Konig an seiner Statt Hadad, der Sohn Bedads, der die Midianiter schlug in der Moabiter Felde; und seine Stadt hieft Awith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Da Hadad starb, ward Konig an seiner Statt Sarnia von Masrek.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Da Sarnia starb, ward Konig an seiner Statt Saul von Rehoboth am Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Da Saul starb, ward Konig an seiner Statt Baal- Hanan, der Sohn Achbors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Da Baal-Hanan starb, ward Konig an seiner Statt Hadad, und seine Stadt hied Pagi; und sein Weib hied Mehetabeel, eine Tochter Matreds, die Mesahabs Tochterwar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Da aber Hadad starb, wurden Fursten zu Edom: Furst Thimna, Furst Aiwa, Furst Jetheth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Furst Ahalibama, Furst Ela, Furst Pinon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Furst Kenas, Furst Theman, Furst Mibzar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Furst Magdiel, Furst Iram. Das sind die Fursten zu Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Dies sind die Kinder Israels: Ruben, Simeon, Levi, Juda, Isaschar, Sebulon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph, Benjamin, Naphthali, Gad, Asser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Die Kinder Judas sind: Ger, Onan, Sela. Die drei wurden ihm geboren von der Kanaanitin, der Tochter Suas. Ger aber, der erste Sohn Judas, war bose vor dem HERRN, darum totete er ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Thamar aber, seine Schnur, gebar ihm Perez und Serah, daß aller Kinder Judas waren fünf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Die Kinder Perez sind: Hezron und Hamul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Die Kinder aber Serahs sind: Simri, Ethan, Heman, Chalkol, Dara. Der aller sind funf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Die Kinder Charmis sind Achan, welcher betrubete Israel, da er sich am Verbanneten vergriff.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Die Kinder Ethans sind Asarja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Die Kinder aber Hezrons, die ihm geboren, sind: Jerahmeel, Ram, Chalubai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram aber zeugete Amminadab. Amminadab zeugete Nahesson, den Fursten der Kinder Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahesson zeugete Salma. Salma zeugete Boas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boas zeugete Obed. Obed zeugete Isai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai zeugete seinen ersten Sohn Eliab, Abinadab den andern, Simea den dritten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Nethaneel den vierten, Raddai den funften,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozem den sechsten, David den siebenten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Und ihre Schwestern waren: Zerujas und Abigail. Die Kinder Zerujas sind: Abisai, Joab, Asahel, die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail aber gebar Amasa. Der Vater aber Amasas war Jether, ein Ismaeliter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb, der Sohn Hezrons, zeugete mit Asuba, seiner Frau, und Jerigoth; und dies sind derselben Kinder: Jeser, Sobab und Ardon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Da aber Asuba starb, nahm Kaleb Ephrath; die gebar ihm Hur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur gebar Uri. Uri gebar Bezaleel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Danach beschlief Hezron die Tochter Machirs, des Vaters Gileads; und er nahm sie, da er war sechzig Jahre alt; und sie gebar ihm Segub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Segub aber zeugete Jair, der hatte dreiundzwanzig Stadte im Lande Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Und er kriegte aus denselben Gesur und Aram, die Flecken Jairs, dazu Kenath mit ihren Tochtern, sechzig Stadte. Das sind alle Kinder Machirs, des Vaters Gileads.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Nach dem Tode Hezrons in Kaleb-Ephratha liefi Hezron, Abia, sein Weib, die gebar ihm Ashur, den Vater Thekoas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Jerahmeel, der erste Sohn Hezrons, hatte Kinder: den ersten Ram, Buna, Oren und Ozem und Ahia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Und Jerahmeel hatte noch ein ander Weib, die hieß Atara, die ist die Mutter Onams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Die Kinder aber Rams, des ersten Sohns Jerahmeels, sind: Maaz, Jamin und Eker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Aber Onam hatte Kinder: Samai und Jada. Die Kinder aber Samais sind: Nadab und Abisur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Das Weib aber Abisurs hiefi Abihail, die ihm gebar Achban und Molid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Die Kinder aber Nadabs sind: Seled und Appaim; und Seled starb ohne Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Die Kinder Appaims sind Jesei. Die Kinder Jeseis sind Sesan. Die Kinder Sesans sind Ahelai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Die Kinder aber Jadas, des Bruders Samais, sind: Jether und Jonathan; Jether aber starb ohne Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Die Kinder aber Jonathans sind: Peleth und Sasa. Das sind die Kinder Jerahmeels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesan aber hatte nicht Sohne, sondern Tochter. Und Sesan hatte einen agyptischen Knecht, der hieli Jarha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Und Sesan gab Jarha, seinem Knechte, seine Tochter zum Weibe, die gebar ihm Athai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Athai zeugete Nathan. Nathan zeugete Sabad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Sabad zeugete Ephlal. Ephlal zeugete Obed.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed zeugete Jehu. Jehu zeugete Asarja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asarja zeugete Halez. Halez zeugete Eleasa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasa zeugete Sissemai. Sissemai zeugete Sallum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum zeugete Jekamia. Jekamia zeugete Elisama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Die Kinder Kalebs, des Bruders Jerahmeels, sind: Mesa, sein erster Sohn, der ist der Vater Siphs, und der Kinder Maresas, des Vaters Hebrons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Die Kinder aber Hebrons sind: Korah, Thapuah, Rekem und Sama.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sama aber zeugete Raham, den Vater Jarkaams. Rekem zeugete Samai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Der Sohn aberßamais hieß Maon, und Maon war der Vater Bethzurs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Epha aber, das Kebsweib Kalebs, gebar Haran, Moza und Gases. Haran aber zeugete Gases.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Die Kinder aber Jahdais sind: Regem, Jotham, Gesan, Pelet, Epha und Saaph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Aber Maecha, das Kebsweib Kalebs, gebar Seber und Thirhena;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'und gebar auch Saaph, den Vater Madmannas, und Sewa, den Vater Machbenas, und den Vater Gibeas. Aber Achsa war Kalebs Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Dies waren die Kinder Kalebs: Hur, der erste Sohn von Ephratha; Sobal, der Vater Kiriath-Jearims;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, der Vater Bethlehems; Hareph, der Vater Beth-Gaders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Und Sobal, der Vater Kiriath-Jearims, hatte Sohne, dersah die Halfte Manuhoths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Die Freundschaften aber zu Kiriath-Jearim waren die Jethriter, Puthiter, Sumathiter und Misraiter. Von diesen sind auskommen die Zaregathiter und Esthaoliter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Die Kinder Salmas sind Bethlehem und die Netophathiter, die Krone des Hauses Joabs, und die Halfte der Manahthiter von dem Zareither.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Und die Freundschaften der Schreiber, die zu Jabezwohneten, sind die Thireathiter, Simeathiter, Suchathiter. Das sind die Kiniter, die da kommen sind von Hamath, des Vaters Beth-Rechabs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Dies sind die Kinder Davids, die ihm zu Hebron geboren sind: der erste Amnon, von Ahinoam, der Jesreelitin; derandere Daniel, von Abigail, der Karmelitin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'der dritte Absalom, der Sohn Maechas, der Tochter Thalmais, des Konigs zu Gesur; der vierte Adonia, der Sohn Haggiths;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'der funfte Saphatja, von Abital; der sechste Jethream, von seinem Weibe Egla.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Diese sechs sind ihm geboren zu Hebron; denn er regierete daselbst sieben Jahre und sechs Monden; aber zu Jerusalem regierete er dreiunddreißig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Und diese sind ihm geboren zu, Jerusalem: Simea, Sobab, Nathan, Salomo, die vier, von der Tochter Suas, der Tochter Ammiels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'dazu Jebehar, Elisama, Eliphalet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noga, Nepheg, Japia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliada, Eliphalet, die neun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Das sind alles Kinder Davids, ohne was der Kebsweiber Kinder waren. Und Thamar war ihre Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomos Sohn war Rehabeam; des Sohn war Abia; des Sohn war Assa; des Sohn war Josaphat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'des Sohn war Joram; des Sohn war Ahasja; des Sohn war Joas;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'des Sohn war Amazia; des Sohn war Asarja; des Sohn war Jotham;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'des Sohn war Ahas; des Sohn war Hiskia; des Sohn war Manasse;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'des Sohn war Amon; des Sohn war Josia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Josias Sohne aber waren: der erste Johanan, der andere Jojakim, der dritte Zidekia, der vierte Sallum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Aber die Kinder Jojakims waren Jechanja; des Sohn war Zidekia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Die Kinder aber Jechanias, der gefangen ward, waren: Sealthiel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malchiram, Phadaja, Senneazar, Jekamja, Hosama, Nedabja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Die Kinder Phadajas waren: Zerubabel und Simei. Die Kinder Zerubabels waren: Mesullam und Hananja und ihre Schwester Selomith;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'dazu Hasuba, Ohel, Berechja, Hasadja, Jusab- Hesed, die fünf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Die Kinder aber Hananjas waren: Platja und Jesaja; des Sohn war Rephaja, des Sohn war Arnan; des Sohn War Obadja; des Sohn war Sachanja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Die Kinder aber Sachanjas waren Semaja. Die Kinder Semajas waren: Hattus, Jegeal, Bariah, Nearja, Saphat, die sechs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Die Kinder aber Nearjas waren: Elioenai, Hiskja, Asrikam, die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Die Kinder aber Elioenais waren: Hodaja, Eliasib, Plaja, Akub, Johanan, Delaja, Anani, die sieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Die Kinder Judas waren: Perez, Hezron, Karmi, Hur und Sobal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reaja aber, der Sohn Sobals, zeugete Jahath. Jahath zeugete Ahumai und Lahad. Das sind die Freundschaften der Zaregathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Und dies ist der Stamm des Vaters Etam: Jesreel, Jesma, Jedbas; und ihre Schwester hieli Hazlelponi;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'und Pnuel, der Vater Gedors, und Eser, der Vater Husas. Das sind die Kinder Hurs, des ersten Sohns Ephrathas, des Vaters Bethlehems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashur aber, der Vater Thekoas, hatte zwei Weiber: Hellea und Naera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Und Naera gebar ihm Ahusam, Hepher, Themni, Ahastari. Das sind die Kinder Naeras.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Aber die Kinder Helleas waren: Zereth, Jezohar und Ethnan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Koz aber zeugete Anub und Hazobeba und die Freundschaft Aharhels, des Sohns Harums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jaebez aber war herrlicher denn seine Bruder; und seine Mutter hieli ihn Jaebez, denn sie sprach: Ich habe ihn mit Kummer geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Und Jaebez rief den Gott Israels an und sprach: Wo du mich segnen wirst und meine Grenze mehren, und deine Hand mit mir sein wird und wirst mit dem Ubel schaffen, daß mich\'s nicht bekummere. Und Gott lieü kommen, das er bat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Kalub aber, der Bruder Suhas, zeugete Mehir; der ist der Vater Esthons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Esthon aber zeugete Beth-Rapha, Paseah und Thehinna, den Vater der Stadt Nahas; das sind die Manner von Recha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Die Kinder Kenas waren: Athniel und Seraja. Die Kinder aber Athniels waren Hathath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Und Meonothai zeugete Ophra. Und Seraja zeugete Joab, den Vater des Tals der Zimmerleute, denn sie waren Zimmerleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Die Kinder aber Kalebs, des Sohns Jephunnes, waren: Jru, Ela und Naam. Die Kinder Elas waren Kenas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Die Kinder aber Jehaleleels waren: Siph, Sipha, Thirja und Asareel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Die Kinder aber Esras waren: Jether, Mered, Epher und Jalon, und Thahar mit Mirjam, Samai, Jesbah, dem Vater Esthemoas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Und sein Weib Judija gebar Jered, den Vater Gedors, Heber, den Vater Sochos, Jekuthiel, den Vater Sanoahs. Das sind die Kinder Bithjas, der Tochter Pharaos, die der Mared nahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Die Kinder des Weibes Hodijas, der Schwester Nahams, des Vaters Kegilas, waren: Garmi und Esthemoa, der Maechathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Die Kinder Simons waren: Amnon, Rinna und Ben-Hanan, Thilon. Die Kinder Jeseis waren: Soheth und der Ben-Soheth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Die Kinder aber Selas, des Sohns Judas, waren: Er, der Vater Lechas, Laeda, der Vater Maresas, und die Freundschaft der Leinweber unter dem Hause Asbea;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Dazu Jokim und die Manner von Koseba, Joas und Saraph, die Hausvater wurden in Moab, und Jasubi zu Lahem; wie die alte Rede lautet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Sie waren Topfer und wohneten unter Pflanzen und Zaunen bei dem Konige zu seinem Geschafte; und kamen und blieben daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Die Kinder Simeons waren: Nemuel, Jamin, Jarib, Serah, Saul;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'des Sohn war Sallum; des Sohn war Mibsam; des Sohn war Misma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Die Kinder aber Mismas waren Hamuel; des Sohn war Zachur; des Sohn war Simei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei aber hatte sechzehn Sohne und sechs Tochter; und seine Bruder hatten nicht viel Kinder; aber alle ihre Freundschaften mehreten sich nicht als die Kinder Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Sie wohneten aber zu Berseba, Molada, Hazar- Sual,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilha, Ezem, Tholad,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Bethuel, Harma, Ziklag,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Beth-Marchaboth, Hazar-Susim, Beth-Birei, Saaraim. Dies waren ihre Stadte, bis auf den Konig David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Dazu ihre Dorfer bei Etam, Ain, Rimmon, Thochen, Asan, die fünf Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Und alle Dorfer, die urn diese Stadte her waren, bis gen Baal, das ist ihre Wohnung und ihre Sippschaft unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Und Mesobab, Jamlech, Josa, der Sohn Amazias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jehu, der Sohn Josibjas; des Sohns Serajas, des Sohns Asiels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Elioenai, Jaekoba, Jesohaja, Asaja, Adiel, Ismeel und Benaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Sisa, der Sohn Sipheis, des Sohns Allons, des Sohns Jedajas, des Sohns Simris, des Sohns Semajas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Diese wurden namhaftige Fursten in ihren Geschlechtern des Hauses ihrer Vater und teileten sich nach der Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Und sie zogen hin, dafi sie gen Gedor kamen, bis gegen Morgen des Tals, daß sie Weide suchten fur ihre Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Und fanden fette und gute Weide und ein Land weit von Raum, still und reich; denn vorhin wohneten daselbst die von Ham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Und die jetzt mit Namen beschrieben sind, kamen zur Zeit Hiskias, des Konigs Judas, und schlugen jener Hütten und Wohnungen, die daselbst funden wurden, und verbanneten sie bis auf diesen Tag und wohneten an ihrer Statt; denn es war Weide daselbst fur Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Auch gingen aus ihnen, aus den Kindern Simeons, funfhundert Manner zu dem Gebirge Seir mit ihren Obersten, Platja, Nearja, Rephaja und Usiel, den Kindern Jeseis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'und schlugen die ubrigen Entronnenen der Amalekiter; und wohneten daselbst bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Die Kinder Rubens, des ersten Sohns Israels (denn er war der erste Sohn, aber damit, dafi er seines Vaters Bett verunreinigte, ward seine Erstgeburt gegeben den Kindern Josephs, des Sohns Israels; und er ward nicht gerechnet zur Erstgeburt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'denn Juda, der machtig war unter seinen Brudern, dem ward das Furstentum vor ihm gegeben und Joseph die Erstgeburt).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'So sind nun die Kinder Rubens, des ersten Sohns Israels: Hanoch, Pallu, Hezron und Charmi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Die Kinder aber Joels waren Semaja; des Sohn war Gog; des Sohn war Simei;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'des Sohn war Micha; des Sohn wer Reaja; des Sohn war Baal;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'des Sohn war Beera, welchen fuhrete weg gefangen Thiglath-Pilneser, der Konig von Assyrien; er aber war ein Fürst unter den Rubenitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Aber seine Bruder unter seinen Geschlechtern, da sie unter ihre Geburt gerechnet wurden, hatten zu Hauptern Jeiel und Sacharja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Und Bela, der Sohn Asans, des Sohns Sernas, des Sohns Joels, der wohnete zu Aroer und bis gen Nebo und Baal-Meon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'und wohnete gegen dem Aufgang, bis man kommt an die Wüste ans Wasser Phrath; denn ihres Viehes warviel im Lande Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Und zur Zeit Sauls fuhreten sie Krieg wider die Hagariter, daü jene fielen durch ihre Hand, und wohneten in jener Hütten gegen dem ganzen Morgenort Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Die Kinder Gads aber wohneten gegen ihnen im Lande Basan bis gen Salcha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel der vornehmste und Sapham der andere, Jaenai und Saphatzu Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Und ihre Bruder des Hauses ihrer Vater waren: Michael, Mesullam, Seba, Jorai, Jaekan, Sia und Eber, die sieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Dies sind die Kinder Abihails, des Sohns Huris, des Sohns Jaroahs, des Sohns Gileads, des Sohns Michaels, des Sohns Jesisais, des Sohns Jahdos, des Sohns Bus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, der Sohn Abdiels, des Sohns Gunis, war ein Oberster im Hause ihrer Vater;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'und wohneten zu Gilead in Basan und in ihren Tochtern und in alien Vorstadten Sarons bis an ihr Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Diese wurden alle gerechnet zur Zeit Jothams, des Konigs Judas, und Jerobeams, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Die Kinder Ruben, der Gaditer und des halben Stamms Manasse, was streitbare Manner waren, die Schild und Schwert führen und Bogen spannen konnten und streitkundig waren, der waren vierundvierzigtausend und siebenhundertundsechzig, die ins Heer zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Und da sie stritten mit den Hagaritern, halfen ihnen Jetur, Naphes und Nodab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Und die Hagariter wurden gegeben in ihre Hande, und alles, das mit ihnen war. Denn sie schrieen zu Gott im Streit; und er liel J sich erbitten, denn sie vertraueten ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Und sie fuhreten weg ihr Vieh, funftausend Kamele, zweihundertundfünfzigtausend Schafe, zweitausend Esel und hunderttausend Menschenseelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Denn es fielen viel Verwundete; denn der Streit war von Gott. Und sie wohneten an ihrer Statt bis zur Zeit, da sie gefangen wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Die Kinder aber des halben Stamms Manasse wohneten im Lande, von Basan an bis gen Baal- Hermon und Senir und den Berg Hermon; und ihrer war viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Und diese waren die Haupter des Hauses ihrer Vater: Epher, Jesei, Eliel, Asriel, Jeremia, Hodawja, Jahdiel; gewaltige, redliche Manner und berühmte Haupter im Haus ihrer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Und da sie sich an dem Gott ihrer Vater versundigten und hureten den Gotzen nach der Volker im Lande, die Gott vor ihnen vertilget hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'erweckte der Gott Israels den Geist Phuls, des Konigs von Assyrien, und den Geist Thiglath- Pilnesers, des Konigs von Assyrien, und fuhrete weg die Rubeniter, Gaditer und den halben Stamm Manasse und brachte sie gen Halah und Habor und Hara und an das Wasser Gosan bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 27, 'Die Kinder Levis waren: Gersom, Kahath und Merari.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 28, 'Die Kinder aber Kahaths waren: Amram, Jezehar, Hebron und Usiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 29, 'Die Kinder Amrams waren: Aaron, Mose und Mirjam. Die Kinder Aarons waren: Nadab, Abihu, Eleasar und Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 30, 'Eleasar zeugete Pinehas. Pinehas zeugete Abisua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 31, 'Abisua zeugete Buki. Buki zeugete Usi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 32, 'Usi zeugete Seraja. Seraja zeugete Merajoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 33, 'Merajoth zeugete Amarja. Amarja zeugete Ahitob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 34, 'Ahitob zeugete Zadok. Zadok zeugete Ahimaaz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 35, 'Ahimaaz zeugete Asarja. Asarja zeugete Johanan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 36, 'Johanan zeugete Asarja, den, der Priester war im Hause, das Salomo bauete zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 37, 'Asarja zeugete Amarja. Amarja zeugete Ahitob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 38, 'Ahitob zeugete Zadok. Zadok zeugete Sallum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 39, 'Sallum zeugte Hilkija. Hilkija zeugete Asarja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 40, 'Asarja zeugete Seraja. Seraja zeugete Jozadak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 41, 'Jozadak aber ward mitweggefuhret, da der HERR Juda und Jerusalem durch Nebukadnezar liefi gefangen wegführen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'So sind nun die Kinder Levis diese: Gersom, Kahath, Merari.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'So heilien aber die Kinder Gersoms: Libni und Simei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Aber die Kinder Kahaths heifien: Amram, Jezehar, Hebron und Usiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Die Kinder Meraris heilien: Maheli und Musi. Das sind die Geschlechter der Leviten unter ihren Vatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Gersoms Sohn war Libni; des Sohn war Jahath; des Sohn war Sima;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'des Sohn war Joah; des Sohn war Iddo; des Sohn war Serah; des Sohn war Jeathrai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Kahaths Sohn aber war Amminadab; des Sohn war Korah; des Sohn war Assir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'des Sohn war Elkana; des Sohn war Abiassaph; des Sohn war Assir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'des Sohn war Thahath; des Sohn war Uriel; des Sohn war Usija; des Sohn war Saul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Die Kinder Elkanas waren Amasai und Ahimoth;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'des Sohn war Elkana; des Sohn war Elkana von Zoph; des Sohn war Nahath;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'des Sohn war Eliab; des Sohn war Jeroham; des Sohn war Elkana;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'des Sohn war Samuel; des Erstgeborner war Vasni, und Abija.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Meraris Sohn war Maheli; des Sohn war Libni; des Sohn war Simei; des Sohn war Usa;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'des Sohn war Simea; des Sohn war Haggija; des Sohn war Asaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Dies sind aber, die David stellete, zu singen im Hause des HERRN, da die Lade ruhete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'und dieneten vor der Wohnung der Hutte des Stiffs mit Singen, bis daü Salomo das Haus des HERRN bauete zu Jerusalem; und stunden nach ihrer Weise an ihrem Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Und dies sind sie, die da stunden, und ihre Kinder. Von den Kindern Kahaths war Heman, der Sanger, der Sohn Joels, des Sohns Samuels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'des Sohns Elkanas, des Sohns Jerohams, des Sohns Eliels, des Sohns Thoahs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'des Sohns Zuphs, des Sohns Elkanas, des Sohns Mahaths, des Sohns Amasais,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'des Sohns Elkanas, des Sohns Joels, des Sohns Asarja, des Sohns Zephanjas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'des Sohns Thahaths, des Sohns Assirs, des Sohns Abiasaphs, des Sohns Korahs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'des Sohns Jezehars, des Sohns Kahaths, des Sohns Levis, des Sohns Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Und sein Bruder Assaph stund zu seiner Rechten. Und er, der Assaph, war ein Sohn Berechjas, des Sohns Simeas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'des Sohns Michaels, des Sohns Baesejas, des Sohns Malchijas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'des Sohns Athnis, des Sohns Serahs, des Sohns Adajas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'des Sohns Ethans, des Sohns Simas, des Sohns Simeis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'des Sohns Jahaths, des Sohns Gersoms, des Sohns Levis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Ihre Bruder aber, die Kinder Meraris, stunden zur Linken: namlich Ethan, der Sohn Kusis, des Sohns Abdis, des Sohns Malluchs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'des Sohns Hasabjas, des Sohns Amazias, des Sohns Hilkias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'des Sohns Amzis, des Sohns Banis, des Sohns Samers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'des Sohns Mahelis, des Sohns Musis, des Sohns Meraris, des Sohns Levis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ihre Bruder aber, die Leviten, waren gegeben zu allerlei Amt an der Wohnung des Hauses des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Aaron aber und seine Sohne waren im Amt, anzuzunden aufdem Brandopferaltar und auf dem Rauchaltar und zu allem Geschafte im Allerheiligsten und zu versohnen Israel, wie Mose, der Knecht Gottes, geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Dies sind aber die Kinder Aarons: Eleasar, sein Sohn; des Sohn war Pinehas; des Sohn war Abisua;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'des Sohn war Buki; des Sohn war Usi; des Sohn war Serahja;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'des Sohn war Merajoth; des Sohn war Amarja; des Sohn war Ahitob;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'des Sohn war Zadok; des Sohn war Ahimaaz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Und dies ist ihre Wohnung und Sitz in ihren Grenzen, namlich der Kinder Aarons, des Geschlechts der Kahathiter; denn das Los fiel ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Und sie gaben ihnen Hebron im Lande Juda und derselben Vorstadte umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Aber das Feld der Stadt und ihre Dorfer gaben sie Kaleb, dem Sohn Jephunnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'So gaben sie nun den Kindern Aarons die Freistadte, Hebron und Libna samt ihren Vorstadten, Jather und Esthemoa mit ihren Vorstadten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Hilen, Debir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Asan und Beth-Semes mit ihren Vorstadten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'und aus dem Stamm Benjamin Geba, Alemeth und Anathoth mit ihren Vorstadten; daü aller Stadte in ihrem Geschlecht waren dreizehn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Aber den andern Kindern Kahaths ihres Geschlechts, aus dem halben Stamm Manasse, wurden durchs Los zehn Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Den Kindern Gersoms ihres Geschlechts wurden aus dem Stamm Isaschar und aus dem Stamm Asser und aus dem Stamm Naphthali und aus dem Stamm Manasse in Basan dreizehn Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Den Kindern Meraris ihres Geschlechts wurden durchs Los aus dem Stamm Ruben und aus dem Stamm Gad und aus dem Stamm Sebulon zwolf Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Und die Kinder Israel gaben den Leviten auch Stadte mit ihren Vorstadten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'namlich durchs Los aus dem Stamm der Kinder Juda und aus dem Stamm der Kinder Simeon und aus dem Stamm der Kinder Benjamin die Stadte, die sie mit Namen bestimmten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Aber den Geschlechtern der Kinder Kahaths wurden Stadte ihrer Grenze aus dem Stamm Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'So gaben sie nun ihnen, dem Geschlecht der andern Kinder Kahaths, die freien Stadte: Sichem auf dem Gebirge Ephraim, Geser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Jakmeam, Beth-Horon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ajalon und Gath-Rimon mit ihren Vorstadten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'dazu aus dem halben Stamm Manasse: Aner und Bileam mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Aber den Kindern Gersoms gaben sie aus dem Geschlecht des halben Stamms Manasse: Golan in Basan und Astharoth mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Aus dem Stamm Isaschar: Kedes, Dabrath,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Ramoth und Anem mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Aus dem Stamm Asser: Masai, Abdon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Hukok und Rehob mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Aus dem Stamm Naphthali: Kedes in Galilaa, Hammon und Kiriathaim mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Den andern Kindern Meraris gaben sie aus dem Stamm Sebulon: Rimmono und Thabor mit ihren Vorstadten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'und jenseit des Jordans gegen Jericho, gegen der Sonnen Aufgang am Jordan, aus dem Stamm Ruben: Bezer in der Wüste, Jahza,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Kedemoth und Mepaath mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Aus dem Stamm Gad: Ramoth in Gilead, Mahanaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Hesbon und Jaeser mit ihren Vorstadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Die Kinder Isaschars waren: Thola, Pua, Jasub und Simron, die vier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Die Kinder aber Tholas waren: Usi, Rephaja, Jeriel, Jahemai, Jebsam und Samuel, Haupter im Hause ihrer Vater von Thola und gewaltige Leute in ihrem Geschlecht, an der Zahl zu Davids Zeiten zweiundzwanzigtausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Die Kinder Usis waren Jesraja. Aber die Kinder Jesrajas waren: Michael, Obadja, Joel und Jesia, die fünf, und waren alle Haupter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Und mit ihnen unter ihrem Geschlecht im Hause ihrer Vater waren gerustet Heervolk zum Streit sechsunddreißigtausend; denn sie hatten viele Weiber und Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Und ihre Brüder in alien Geschlechtern Isaschars, gewaltige Leute, waren siebenundachtzigtausend, und wurden alle gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Die Kinder Benjamins waren: Bela, Becher und Jediael, die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Aber die Kinder Belas waren: Ezbon, Usi, Usiel, Jerimoth und Iri, die fünf, Haupter im Hause der Vater, gewaltige Leute. Und wurden gerechnet zweiundzwanzigtausend und vierunddreilüg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Die Kinder Bechers waren: Semira, Joas, Elieser, Elioenai, Amri, Jerimoth, Abia, Anathoth und Alameth; die waren alle Kinder des Becher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Und wurden gerechnet in ihren Geschlechtern nach den Hauptern im Hause ihrer Vater, gewaltige Leute, zwanzigtausend und zweihundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Die Kinder aber Jediaels waren Bilhan. Bilhans Kinder aber waren: Jeus, Benjamin, Ehud, Knaena, Sethan, Tharsis und Ahisahar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Die waren alle Kinder Jediaels, Haupter der Vater, gewaltige Leute, siebenzehntausend zweihundert, die ins Heer auszogen zu streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Und Supim und Hupim waren Kinder Irs; Husim aber waren Kinder Ahers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Die Kinder Naphthalis waren: Jahziel, Guni, Jezer und Sallum, Kinder von Bilha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Die Kinder Manasses sind diese: Esriel, welchen gebar Aramja, sein Kebsweib; er zeugete aber Machir, den Vater Gileads.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Und Machir gab Hupim und Supim Weiber; und seine Schwester hieli Maecha. Sein anderer Sohn hieli Zelaphehad; und Zelaphehad hatte Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Und Maecha, das Weib Machirs, gebar einen Sohn, den hieli sie Peres; und sein Bruder hieli Sares, und desselben Sohne waren Ulam und Rakem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Ulams Sohn aber war Bedan. Das sind die Kinder Gileads, des Sohns Machirs, des Sohns Manasses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Und seine Schwester Molecheth gebar Ishud, Abieser und Mahela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Und Semida hatte diese Kinder: Ahjan, Sichem, Likhi und Aniam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Die Kinder Ephraims waren diese: Suthelah; des Sohn war Bered; des Sohn war Thahath; des Sohn war Eleada; des Sohn war Thahath;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'des Sohn war Sabad; des Sohn war Suthelah; des Sohn war Eser und Elead. Und die Manner zu Gath, die Einheimischen im Lande, erwürgeten sie, darum daß sie hinabgezogen waren, ihr Vieh zu nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Und ihr Vater Ephraim trug lange Zeit Leid; und seine Bruder kamen, ihn zu trosten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Und er beschlief sein Weib, die ward schwanger und gebar einen Sohn, den hied er Bria, darum daß es in seinem Hause ubel zuging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Seine Tochter aber war Seera, die bauete das niedere und obere Beth-Horon, und Usen-Seera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Des Sohn war Rephah und Reseph; des Sohn war Thelah; des Sohn war Thahan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'des Sohn war Laedan; des Sohn war Ammihud; des Sohn war Elisama;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'des Sohn war Nun; des Sohn war Josua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Und ihre Habe und Wohnung war Bethel und ihre Tochter und gegen dem Aufgang Naeran und gegen Abend Geser und ihre Tochter, Sechem und ihre Tochter bis gen Azza und ihre Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'und an den Kindern Manasse Beth-Sean und ihre Tochter, Thaenach und ihre Tochter, Megiddo und ihre Tochter, Dor und ihre Tochter. In diesen wohneten die Kinder Josephs, des Sohns Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Die Kinder Assers waren diese: Jemna, Jeswa, Jeswi, Bria und Serah, ihre Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Die Kinder Brias waren: Heber und Malchiel, das ist der Vater Birsawiths.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Heber aberzeugete Japhlet, Somer, Hotham und Sua, ihre Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Die Kinder Japhlets waren: Passah, Bimehal und Aswath; das waren die Kinder Japhlets.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Die Kinder Somers waren: Ahi, Rahga, Jehuba und Aram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Und die Kinder seines Bruders Helem waren: Jophah, Jemna, Seles und Amal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Die Kinder Zophahs waren: Suah, Harnepher, Sual, Beri, Jemra,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hod, Sama, Silsa, Jethran und Beera.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Die Kinder Jethers waren: Jephunne, Phispa und Ara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Die Kinder Ullas waren: Arah, Haniel und Rizja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Diese waren alle Kinder Assers, Haupter im Hause ihrer Vater, auserlesene, gewaltige Leute und Haupter über Fursten. Und wurden gerechnet ins Heer zum Streit an ihrer Zahl sechsundzwanzigtausend Manner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin aber zeugete Bela, seinen ersten Sohn, Asbal den andern, Ahrah den dritten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noha den vierten, Rapha den fünften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Und Bela hatte Kinder: Addar, Gera, Abihud,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naeman, Ahoah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephuphan und Huram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Dies sind die Kinder Ehuds, die da Haupter waren der Vater unter den Bürgem zu Geba und zogen weg gen Manahath:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'namlich Naeman, Ahia und Gera, derselbe fuhrete sie weg; und er zeugete Usa und Ahihud.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Und Saharaim zeugete im Lande Moab (da er jene von sich gelassen hatte) von Husim und Baera, seinen Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Und er zeugete von Hodes, seinem Weibe: Jobab, Zibja, Mesa, Malcham,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeuz, Sachja und Mirma. Das sind seine Kinder, Haupter der Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Von Husim aber zeugete er Abitob und Elpaal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Die Kinder aber Elpaals waren: Eber, Miseam und Samed. Derselbe bauete Ono und Lod und ihre Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Und Bria und Sama waren Haupter der Vater unter den Bürgem zu Ajalon; sie verjagten die zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Ahjo aber, Sasak, Jeremoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadja, Arad, Ader,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Michael, Jespa und Joha; das sind Kinder Brias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Sebadja, Mesullam, Hiski, Heber,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jesmerai, Jeslia, Jobab; das sind Kinder Elpaals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Sichri, Sabdi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elioenai, Zilthai, Eliel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Braja und Simrath; das sind die Kinder Simeis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jespan, Eber, Eliel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sichri, Hanan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Elam, Anthothja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jephdeja und Pnuel; das sind die Kinder Sasaks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharja, Athalja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaeresja, Elia und Sichri; das sind Kinder Jerohams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Das sind die Haupter der Vater ihrer Geschlechter, die wohneten zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Aber zu Gibeon wohnete der Vater Gibeons; und sein Weib hiefi Maecha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Und sein erster Sohn war Abdon, Zur, Kis, Baal, Nadab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahjo und Secher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Mikloth aber zeugete Simea; und sie wohneten gegen ihren Brudern zu Jerusalem mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner zeugete Kis. Kis zeugete Saul. Saul zeugete Jonathan, Malchisua, Abinadab und Esbaal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Der Sohn aber Jonathans war Meribaal. Meribaal zeugete Micha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Die Kinder Michas waren: Pithon, Melech, Thaerea und Ahas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahas aber zeugete Joadda. Joadda zeugete Alemeth, Asmaveth und Simri. Simri zeugete Moza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza zeugete Binea; des Sohn war Rapha; des Sohn war Eleasa; des Sohn war Azel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Azel aber hatte sechs Sohne, die hieüen: Esrikam, Bochru, Jesmael, Searja, Obadja, Hanan. Die waren alle Sohne Azels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Die Kinder Eseks, seines Bruders, waren: Ulam, sein erster Sohn, Jeus der andere, Eliphelet der dritte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Die Kinder aber Ulams waren gewaltige Leute und geschickt mit Bogen; und hatten viele Sohne und Sohnes Sohne, hundertundfunfzig. Die sind alle von den Kindern Benjamins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Und das ganze Israel ward gerechnet, und siehe, sie sind angeschrieben im Buch der Konige Israels und Judas, und nun weggefuhret gen Babel urn ihrer Missetat willen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'die zuvor wohneten auf ihren Gutern und Stadten, namlich Israel, Priester, Leviten und Nethinim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Aber zu Jerusalem wohneten etliche der Kinder Juda, etliche der Kinder Benjamin, etliche der Kinder Ephraim und Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Namlich aus den Kindern Perez, des Sohns Judas, war Uthai, der Sohn Ammihuds, des Sohns Amris, des Sohns Imris, des, Sohns Banis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Von Siloni aber Asaja, der erste Sohn, und seine andern Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Von den Kindern Serahs: Jeguel und seine Bruder, sechshundertundneunzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Von den Kindern Benjamin: Sallu, der Sohn Mesullams, des Sohns Hodawjas, des Sohns Hasnuas;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'und Jebneja, der Sohn Jerohams; und Ela, der Sohn Usis, des Sohns Michris; und Mesullam, der Sohn Sephatjas, des Sohns Reguels, des Sohns Jebnejas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Dazu ihre Bruder in ihren Geschlechtern, neunhundertundsechsundfünfzig. Alle diese Manner waren Haupter der Vater im Hause ihrer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Von den Priestern aber: Jedaja, Jojarib, Jachin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'und Asaria, der Sohn Hilkias, des Sohns Mesullams, des Sohns Zadoks, des Sohns Merajoths, des Sohns Ahitobs, ein Furst im Hause Gottes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'und Adaja, der Sohn Jerohams, des Sohns Pashurs, des Sohns Malchias; und Maesai, der Sohn Adiels, des Sohns Jachseras, des Sohns Mesullams, des Sohns Mesillemiths, des Sohns Immers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Dazu ihre Bruder, Haupter im Hause ihrer Vater, tausend siebenhundertundsechzig fleiftige Leute am Geschafte des Amts im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Von den Leviten aber aus den Kindern Meraris: Semaja, der Sohn Hasubs, des Sohns Asrikams, des Sohns Hasabjas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Und Bakbakar, der Zimmermann, und Galal und Mathanja, der Sohn Michas, des Sohns Sichris, des Sohns Assaphs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Und Obadja, der Sohn Semajas, des Sohns Galals, des Sohns Jeduthuns; und Berechja, der Sohn Assas, des Sohns Elkanas, der in den Dorfern wohnete der Netophathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Die Pfortner aber waren: Sallum, Akub, Talmon, Ahiman mit ihren Brüdem und Sallum, der Oberste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Denn bisher hatten am Tor des Konigs gegen dem Aufgang gewartet die Kinder Levi mit Lagern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Und Sallum, der Sohn Kores, des Sohns Abiassaphs, des Sohns Korahs, und seine Bruder aus dem Hause seines Vaters, die Korhiter am Geschafte des Amts, dafi sie warteten an der Schwelle der Hutte; und ihre Vater im Lager des HERRN, daß sie warteten des Eingangs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Pinehas aber, der Sohn Eleasars, war Furst uber sie, darum daß der HERR zuvor mit ihm gewesen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Sacharja aber, der Sohn Meselemjas, war Hüter am Tor der Hutte des Stiffs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Alle diese waren auserlesen zu Hutern an der Schwelle, zweihundertundzwolf, die waren gerechnet in ihren Dorfern. Und David und Samuel, der Seher, stifteten sie durch ihren Glauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'dafi sie und ihre Kinder huten sollten am Hause des HERRN, namlich an dem Hause der Hutte, daß sie sein warteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Es waren aber solche Torwarter gegen die vier Winde gestellet: gegen Morgen, gegen Abend, gegen Mitternacht, gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Ihre Bruder aber waren auf ihren Dorfern, daß sie hereinkamen, je des siebenten Tages, allezeit bei ihnen zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Denn die Leviten waren diesen viererlei obersten Torhutern vertrauet, und sie waren uber die Kasten und Schatze im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Auch blieben sie uber Nacht urn das Haus Gottes; denn es gebuhrete ihnen die Hut, daß sie alle Morgen auftaten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Und etliche aus ihnen waren uber das Gerate des Amts; denn sie trugen es gezahlet aus und ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Und ihrer etliche waren bestellet uber die Gefalie und uber alles heilige Gerate, uber Semmelmehl, uber Wein, uber 01, uber Weihrauch uber Rauchwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Aber der Priester Kinder machten etliche das Rauchwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Mathithja aus den Leviten, dem ersten Sohn Sallums, des Korhiters, waren vertrauet die Pfannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Aus den Kahathitern aber, ihren Brudern, waren uber die Schaubrote zuzurichten, daß sie sie alle Sabbat bereiteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Das sind die Sanger, die Haupter unter den Vatern der Leviten, uber die Kasten ausgesondert; denn Tag und Nacht waren sie drob im Geschafte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Das sind die Haupter der Vater unter den Leviten in ihren Geschlechtern. Diese wohneten zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Zu Gibeon wohneten Jeiel, der Vater Gibeons, sein Weib hieli Maecha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'und sein erster Sohn Abdon, Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahjo, Sacharja, Mikloth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Mikloth aber zeugete Simeam; und sie wohneten auch urn ihre Bruder zu Jerusalem unter den Ihren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner aber zeugete Kis. Kis zeugete Saul. Saul zeugete Jonathan, Malchisua, Abinadab, Esbaal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Der Sohn aber Jonathans war Meribaal. Meribaal aber zeugete Micha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Die Kinder Michas waren: Pithon, Melech und Thaherea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahas zeugete Jaera. Jaera zeugete Alemeth, Asmaveth und Simri. Simri zeugete Moza.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza zeugete Binea; des Sohn war Raphaja; des Sohn war Eleasa; des Sohn war Azel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel aber hatte sechs Sohne, die hielien: Asrikam, Bochru, Jismael, Searja, Obadja, Hanan; das sind die Kinder Azels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Die Philister stritten wider Israel. Und die von Israel flohen vor den Philistern, und fielen die Erschlagenen auf dem Berge Gilboa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Aber die Philister hingen sich an Saul und seine Sohne hinter ihnen her und schlugen Jonathan, Abinadab und Malchisua, die Sohne Sauls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Und der Streit ward hart wider Saul; und die Bogenschutzen kamen an ihn, dafi ervon den Schutzen verwundet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Da sprach Saul zu seinem Waffentrager: Zeuch dein Schwert aus und erstich mich damit, daß diese Unbeschnittenen nicht kommen und schandlich mit mir umgehen. Aber sein Waffentrager wollte nicht; denn er furchtete sich sehr. Da nahm Saul sein Schwert und fiel drein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Da aber sein Waffentrager sah, dafi Saul tot war, fiel er auch ins Schwert und starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Also starb Saul und seine drei Sohne und sein ganzes Haus zugleich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Da aber die Manner Israels, die im Grunde waren, sahen, daß sie geflohen waren, und daß Saul und seine Sohne tot waren, verlieüen sie ihre Stadte und flohen; und die Philister kamen und wohneten drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Des andern Morgens kamen die Philister, die Erschlagenen auszuziehen, und fanden Saul und seine Sohne liegen auf dem Berge Gilboa;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'und zogen ihn aus und huben auf sein Haupt und seine Waffen und sandten es ins Land der Philister umher und lielien\'s verkündigen vor ihren Gotzen und dem Volk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'und legten seine Waffen ins Haus ihres Gottes, und seinen Schadel hefteten sie an das Haus Dagons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Da aber alle die zu Jabes in Gilead horeten alles, was die Philister Saul getan hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'machten sie sich auf, alle streitbaren Manner, und nahmen den Leichnam Sauls und seiner Sohne und brachten sie gen Jabes und begruben ihre Gebeine unter der Eiche zu Jabes; und fasteten sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Also starb Saul in seiner Missetat, die er wider den HERRN getan hatte an dem Wort des HERRN, das er nicht hielt, auch daß er die Wahrsagerin fragte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'und fragte den HERRN nicht; darum totete er ihn und wandte das Konigreich zu David, dem Sohn Isais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Und ganz Israel sammelte sich zu David gen Hebron und sprach: Siehe, wir sind dein Bein und dein Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Auch vorhin, da Saul Konig war, fuhretestdu Israel aus und ein. So hat der HERR, dein Gott, dir geredet: Du sollst mein Volk Israel weiden, und du sollst Fürst sein uber mein Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Auch kamen alle Altesten Israels zum Konige gen Hebron. Und David machte einen Bund mit ihnen zu Hebron vor dem HERRN. Und sie salbeten David zum Konige uber Israel nach dem Wort des HERRN durch Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Und David zog hin und das ganze Israel gen Jerusalem, das ist Jebus; denn die Jebusiter wohneten im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Und die Burger zu Jebus sprachen zu David: Du sollst nicht hereinkommen! David aber gewann die Burg Zion, das ist, Davids Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Und David sprach: Wer die Jebusiter am ersten schlagt, der soil ein Haupt und Oberster sein. Da erstieg sie am ersten Joab, der Sohn Zerujas, und ward Hauptmann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'David aber wohnete auf der Burg; daher heifit man sie Davids Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Und er bauete die Stadt umher, von Millo an bis gar umher. Joab aber liefi leben die übrigen in der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Und David fuhr fort und nahm zu; und der HERR Zebaoth war mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Dies sind die Obersten unter den Helden Davids, die sich redlich mit ihm hielten in seinem Konigreich bei dem ganzen Israel, daß man ihn zum Konige machte nach dem Wort des HERRN fiber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Und dies ist die Zahl der Helden Davids: Jasabeam, der Sohn Hachmonis, der Vornehmste unter dreifügen; er hub seinen Spieli auf und schlug dreihundert aufeinmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Nach ihm war Eleasar, der Sohn Dodos, der Ahohiter; und er war unter den dreien Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Dieserwar mit David, da sie Hohn sprachen, und die Philister sich daselbst versammelt hatten zum Streit. Und war ein Stuck Ackers voll Gerste; und das Volk floh vor den Philistern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Und sie traten mitten auf das Stuck und erretteten es und schlugen die Philister. Und der HERR gab ein groli Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Und die drei aus den dreüüg Vornehmsten zogen hinab zum Felsen, zu David, in die Hohle Adullam. Aber der Philister Lager lag im Grunde Rephaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'David aber war in der Burg; und der Philister Volk war dazumal zu Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Und David ward lüstern und sprach: Wer will mirzu trinken geben des Wassers aus dem Brunnen zu Bethlehem unter dem Tor?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Da rissen die drei in der Philister Lager und schopften des Wassers aus dem Brunnen zu Bethlehem unter dem Tor; und trugen\'s und brachten\'s zu David. Er aber wolite es nicht trinken, sondern goli es dem HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'und sprach: Das lasse Gott feme von mir sein, daß ich solches tue und trinke das Blut dieser Manner in ihres Lebens Fahr; denn sie haben\'s mit ihres Lebens Fahr hergebracht. Darum wollte er\'s nicht trinken. Das taten die drei Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai, der Bruder Joabs, der war der Vornehmste unter dreien; und er hub seinen Spieü auf und schlug dreihundert. Und erwar unter dreien beruhmt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'und er der dritte, herrlicher denn die zween, und war ihr Oberster, aber bis an die drei kam er nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, der Sohn Jojadas, des Sohns Ishails, von groi Jen Taten, von Kabzeel. Erschlug zween Lowen der Moabiter; und ging hinab und schlug einen Lowen mitten im Brunnen zur Schneezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Er schlug auch einen agyptischen Mann, der war fünf Ellen groiß und hatte einen Spieli in der Hand wie ein Weberbaum. Aber er ging zu ihm hinab mit einem Stecken und nahm ihm den Spieli aus der Hand und erwurgete ihn mit seinem eigenen Spieü.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Das tat Benaja, der Sohn Jojadas, und war berühmt unter dreien Helden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'und war der herrlichste unter dreifügen, aber an die drei kam er nicht. David aber machte ihn zum heimlichen Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Die streitbaren Helden sind diese: Asahel, der Bruder Joabs. Elhanan, der Sohn Dodos von Bethlehem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samoth, der Haroriter. Helez, der Peloniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, der Sohn Ekes, der Thekoiter. Abieser, der Anthothiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibechai, der Husathiter. Ilai, der Ahohiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maherai, der Netophathiter. Heled, der Sohn Baenas, der Netophathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ithai, der Sohn Ribais, von Gibea der Kinder Benjamin. Benaja, der Pirgathoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai, von den Bachen Gaas. Abiel, der Arbathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmaveth, der Baherumiter. Eljahba, der Saaiboniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Die Kinder Hasems, des Gisoniters. Jonathan, der Sohn Sages, der Harariter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, der Sohn Sachars, der Harariter. Eliphal, der Sohn Urs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher, der Macherathiter. Ahia, der Peloniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro, der Karmeliter. Naerai, der Sohn Asbais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, der Bruder Nathans. Mibehar, der Sohn Hagris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek, der Ammoniter. Naherai, der Berothiter, Waffentrager Joabs, des Sohns Zerujas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, der Jethriter. Gareb, der Jethriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria, der Hethiter. Sabad, der Sohn Aheiais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, der Sohn Sisas, der Rubeniter, ein Hauptmann der Rubeniter, und dreißig waren unter ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, der Sohn Maechas. Josaphat, der Mathoniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Usia, der Asthrathiter. Sama und Jaiel, die Sohne Hothams, des Aroeriters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, der Sohn Simris. Joha, sein Bruder, der Thiziter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel, der Maheviter. Jeribai und Josawja, die Sohne Elnaams. Jethma, der Moabiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed, Jaesiel von Mezobaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Auch kamen diese zu David gen Ziklag, da er noch verschlossen war vor Saul, dem Sohn Kis. Und sie waren auch unter den Helden, die zum Streit halfen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'und mit Bogen geschickt waren zu beiden Handen, auf Steine, Pfeile und Bogen. Von den Brudern Sauls, die aus Benjamin waren:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'der Vornehmste Ahieser und Joas, die Kinder Samaas, des Gibeathiters; Jesiel und Peiet, die Kinder Asmaveths; Baracha und Jehu, der Anthothiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jesmaja, der Gibeoniter, gewaltig unter dreifügen und uber dreifüg. Jeremia, Jahesiel, Johanan, Josabad, der Gederathiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eleusai, Jerimoth, Bealja, Samarja, Saphatja, der Harophiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jesija, Asareel, Joeser, Jasabeam, die Korhiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela und Sabadja, die Kinder Jerohams von Gedor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Von den Gaditern sonderten sich aus zu David in die Burg in der Wuste starke Helden und Kriegsleute, die Schild und Spiefi fuhreten, und ihr Angesicht wie der Lowen und schnell wie die Rehe auf den Bergen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Der erste Eser, der andere Obadja, der dritte Eliab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'der vierte Masmanna, der funfte Jeremja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'der sechste Athai, der siebente Eliel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'der achte Johanan, der neunte Elsabad,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'der zehnte Jeremja, der elfte Machbanai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Diese waren von den Kindern Gad, Haupter im Heer; der Kleinste uber hundert und der Grofite uber tausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Die sind\'s, die uber den Jordan gingen im ersten Monden, da ervoli war an beiden Ufern, dafi alle Gründe eben waren, beide gegen Morgen und gegen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Es kamen aber auch von den Kindern Benjamin und Juda zu der Burg Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'David aber ging heraus zu ihnen und antwortete und sprach zu ihnen: So ihr kommt im Frieden zu mir und mir zu helfen, so soil mein Herz mit euch sein; so ihr aber kommt auf List und mir wider zu sein, so doch kein Frevel an mir ist, so sehe der Gott unserer Vater drein und strafe es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Aber der Geist zog an Amasai, den Hauptmann unter dreifügen: Dein sind wir, David, und mit dir halten wifs, du Sohn Isais. Friede, Friede sei mit dir! Friede sei mit deinen Helfern! denn dein Gott hilft dir. Da nahm sie David an und setzte sie zu Hauptern uber die Kriegsleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Und von Manasse fielen zu David, da er kam mit den Philistern wider Saul zum Streit und half ihnen nicht. Denn die Fursten der Philister liefien ihn mit Rat von sich und sprachen: Wenn er zu seinem Herrn Saul fiele, so mochte es uns unsern Hals kosten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Da er nun gen Ziklag zog, fielen zu ihm von Manasse Adna, Josabad, Jediael, Michael, Josabad, Elihu, Zilthai, Haupter uber tausend in Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Und sie halfen David wider die Kriegsleute; denn sie waren alle redliche Heiden und wurden Hauptieute uber das Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Auch kamen alle Tage etliche zu David, ihm zu helfen, bis daü ein groli Heer ward, wie ein Heer Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Und dies ist die Zahl der Haupter, gerustet zum Heer, die zu David gen Hebron kamen, das Konigreich Sauls zu ihm zu wenden, nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Der Kinder Juda, die Schild und Spiefi trugen, waren sechstausend und achthundert, gerustet zum Heer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'der Kinder Simeon, redliche Heiden zum Heer, siebentausend und hundert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'der Kinder Levi viertausend und sechshundert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'und Jojada, der Fürst unter denen von Aaron, mit dreitausend und siebenhundert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Zadok, der Knabe, ein redlicher Held, mit seines Vaters Hause, zweiundzwanzig Obersten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'der Kinder Benjamin, Sauls Bruder, dreitausend; denn bis auf die Zeit hielten ihrer noch viele an dem Hause Sauls;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'der Kinder Ephraim zwanzigtausend und achthundert, redliche Heiden und berühmte Manner im Hause ihrer Vater;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'des halben Stamms Manasse achtzehntausend, die mit Namen genannt wurden, daß sie kamen und machten David zum Konige;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'der Kinder Isaschar, die verstandig waren und rieten, was zu jeder Zeit Israel tun sollte, zweihundert Hauptieute; und alle ihre Bruder folgten ihrem Wort;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'von Sebulon, die ins Heer zogen zum Streit, gerustet mit allerlei Waffen zum Streit, fünfzigtausend, sich in die Ordnung zu schicken eintrachtiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'von Naphthali tausend Hauptieute und mit ihnen, die Schild und Spiefi fuhreten, siebenunddreitügtausend;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'von Dan zum Streit gerustet achtundzwanzigtausend sechshundert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'von Asser, die ins Heer zogen, gerustet zum Streit, vierzigtausend;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'von jenseit des Jordans, von den Rubenitern, Gaditern und halben Stamm Manasse mit allerlei Waffen zum Streit hundertundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Alle diese Kriegsleute, den Zeug zu ordnen, kamen von ganzem Herzen gen Hebron, David zum Konige zu machen uber ganz Israel. Auch war alles andere Israel eines Herzens, daü man David zum Konige machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Und waren daselbst bei David drei Tage, alien und tranken; denn ihre Bruder flatten fur sie zubereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Auch welche die nachsten urn sie waren, bis hin an Isaschar, Sebulon und Naphthali, die brachten Brot auf Eseln, Kamelen, Maulern und Rindern zu essen, Mehl, Feigen, Rosinen, Wein, 01 Rinder, Schafe die Menge; denn es war eine Freude in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 41, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Und David hielt einen Rat mit den Hauptleuten über tausend und über hundert und mit alien Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Und sprach zu der ganzen Gemeine Israels: Gefallt es euch und ist\'s von dem HERRN, unserm Gott, so laüt uns allenthalben ausschicken zu den andern, unsern Brudern in alien Landen Israels, und mit ihnen die Priester und Leviten in den Stadten, da sie Vorstadte haben, daß sie zu uns versammelt werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'und laüt uns die Lade unsers Gottes zu uns wieder holen, denn bei den Zeiten Sauls fragten wir nicht nach ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Da sprach die ganze Gemeine, man sollte also tun; denn solches gefiel allem Volk wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Also versammelte David das ganze Israel, von Sihor Agyptens an, bis man kommt gen Hemath, die Lade Gottes zu holen von Kiriath-Jearim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Und David zog hinauf mit dem ganzen Israel zu Kiriath-Jearim, welche liegt in Juda, daß er von dannen heraufbrachte die Lade Gottes, des HERRN, der auf den Cherubim sitzet, da der Name angerufen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Und sie Men die Lade Gottes auf einem neuen Wagen führen, aus dem Hause Abinadabs. Usa aber und sein Bruder trieben den Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'David aber und das ganze Israel spielten vor Gott her aus ganzer Macht mit Liedern, mit Harfen, mit Psaltern, mit Pauken, mit Zimbeln und mit Posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Da sie aber kamen auf den Platz Chidon, reckte Usa seine Hand aus, die Lade zu halten; denn die Rinder schritten beiseit aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Da erzurnete der Grimm des HERRN über Usa und schlug ihn, daß er seine Hand hatte ausgereckt an die Lade, daß er daselbst starb vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Da ward David traurig, daß der HERR einen solchen Rili tat an Usa; und hieli die Statte Perez-Usa bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Und David fürchtete sich vor Gott des Tages und sprach: Wie soil ich die Lade Gottes zu mir bringen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Darum lieli er die Lade Gottes nicht zu sich bringen in die Stadt Davids, sondern lenkte sie hin ins Haus Obed-Edoms, des Githiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Also blieb die Lade Gottes bei Obed-Edom in seinem Hause drei Monden. Und der HERR segnete das Haus Obed-Edoms und alles, was er hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Und Huram, der Konig zu Tyrus, sandte Boten zu David und Zedernholz, Maurer und Zimmerleute, daß sie ihm ein Haus baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Und David merkte, daß ihn der HERR zum Konige uber Israel bestatiget hatte; denn sein Konigreich stieg auf um seines Volks Israel willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Und David nahm noch mehr Weiber zu Jerusalem und zeugete noch mehr Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Und die ihm zu Jerusalem geboren wurden, hielien also: Sammua, Sobab, Nathan, Salomo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jebehar, Elisua, Elpalet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogah, Nepheg, Japhia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Baeljada, Eliphalet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Und da die Philister horeten, daü David zum Konige gesalbet war uber ganz Israel, zogen sie alle herauf, David zu suchen. Da das David horete, zog er aus gegen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Und die Philister kamen und lielien sich nieder im Grunde Rephaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'David aber fragte Gott und sprach: Soil ich hinaufziehen wider die Philister, und willst du sie in meine Hand geben? Der HERR sprach zu ihm: Zeuch hinauf, ich habe sie in deine Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Und da sie hinaufzogen gen Baal-Prazim, schlug sie David daselbst. Und David sprach: Gott hat meine Feinde durch meine Hand zertrennet, wie sich das Wasser trennet. Daher hiefien sie die Statte Baal- Prazim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Und sie liefien ihre Gotter daselbst; da hiefi sie David mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Aber die Philister machten sich wieder daran und taten sich nieder im Grunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Und David fragte abermal Gott; und Gott sprach zu ihm: Du sollst nicht hinaufziehen hinter ihnen her, sondern lenke dich von ihnen, dafi du an sie kommest gegen den Maulbeerbaumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Wenn du dann wirst horen das Rauschen oben auf den Maulbeerbaumen einhergehen, so fahre heraus zum Streit; denn Gott ist da vor dir ausgezogen; zu schlagen der Philister Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Und David tat, wie ihm Gott geboten hatte; und sie schlugen das Heer der Philister von Gibeon an bis gen Gaser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Und Davids Name brach aus in alien Landen, und der HERR liefi seine Furcht uber alle Heiden kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Und er bauete ihm Hauser in der Stadt Davids und bereitete der Lade Gottes eine Statte und breitete eine Hütte uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Dazumal sprach David: Die Lade Gottes soil niemand tragen ohne die Leviten; denn dieselbigen hat der HERR erwahlet, daß sie die Lade des HERRN tragen und ihm dienen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Darum versammelte David das ganze Israel gen Jerusalem, dafi sie die Lade des HERRN hinaufbrachten an die Statte, die er dazu bereitet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Und David brachte zuhauf die Kinder Aaron und die Leviten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Aus den Kindern Kahath: Uriel, den Obersten, samt seinen Brüdern, hundertundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'aus den Kindern Merari: Asaja, den Obersten, samt seinen Brudern, zweihundertundzwanzig;,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'aus den Kindern Gersom: Joel, den Obersten, samt seinen Brudern, hundertunddreifüg;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'aus den Kindern Elizaphan: Semaja, den Obersten, samt seinen Brudern, zweihundert;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'aus den Kindern Hebron: Eliel, den Obersten, samt seinen Brudern, achtzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'aus den Kindern Usiel: Amminadab, den Obersten, samt seinen Brudern, hundertundzwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Und David rief Zadok und Abjathar, den Priestern, und den Leviten, namlich Uriel, Asaja, Joel, Semaja, Eliel, Amminadab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'und sprach zu ihnen: Ihrseid die Haupterder Vater unter den Leviten; so heiliget nun euch und eure Brüder, dafi ihrdie Lade des HERRN, des Gottes Israels, heraufbringet, dahin ich ihr bereitet habe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'denn vorhin, da ihr nicht da waret, tat der HERR, unser Gott, einen Rili unter uns, darum dafi wir ihn nicht suchten, wie sich\'s gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Also heiligten sich die Priester und Leviten, dafi sie die Lade des HERRN, des Gottes Israels, heraufbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Und die Kinder Levi trugen die Lade Gottes (des HERRN) auf ihren Achseln mit den Stangen dran, wie Mose geboten hatte nach dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Und David sprach zu den Obersten der Leviten, dafi sie ihre Brüder zu Sangern stellen sollten mit Saitenspielen, mit Psaltern, Harfen und hellen Zimbeln, dafi sie laut sangen und mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Da bestelleten die Leviten Heman, den Sohn Joels; und aus seinen Brudern Assaph, den Sohn Berechjas; und: aus den Kindern Merari, ihren Brudern, Ethan, den Sohn Kusajas;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'und mit ihnen ihre Brüder des andern Teils; namlich Sacharja, Ben, Jaesiel, Semiramoth, Jehiel, Unni, Eliab, Benaja, Maeseja, Mathithja, Elipheleja, Mikneja, Obed-Edom, Jeiel, die Torhüter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Denn Heman, Assaph und Ethan waren Sanger, mitehernen Zimbeln helle zu klingen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Sacharja aber, Asiel, Semiramoth, Jehiel, Unni, Eliab, Maeseja und Benaja, mit Psaltern nachzusingen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Mathithja aber, Elipheleja, Mikneja, Obed- Edom, Jeiel und Asasja mit Harfen von acht Saiten, ihnen vorzusingen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Chenanja aber, der Leviten Oberster, der Sangmeister, dafi er sie unterweisete zu singen; denn er war verstandig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Und Berechja und Elkana waren Torhüter der Lade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Aberßebanja, Josaphat, Nethaneel, Amasai, Sacharja, Benaja, Elieser, die Priester, bliesen mit Trommeten vor der Lade Gottes; und Obed-Edom und Jehia waren Torhüter der Lade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Also gingen hin David und die Altesten in Israel und die Obersten liber die Tausende, heraufzuholen die Lade des Bundes des HERRN aus dem Hause Obed-Edoms mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Und da Gott den Leviten half, die die Lade des Bundes des HERRN trugen, opferte man sieben Farren und sieben Widder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Und David hatte einen leinenen Rock an, dazu alle Leviten, die die Lade trugen, und die Sanger und Chenanja, der Sangmeister, mit den Sangern; auch hatte David einen leinenen Leibrock an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Also brachte das ganze Israel die Lade des Bundes des HERRN hinauf mit Jauchzen, Posaunen, Trommeten und hellen Zimbeln, mit Psaltern und Harfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Da nun die Lade des Bundes des HERRN in die Stadt Davids kam, sah Michal, die Tochter Sauls, zum Fenster aus. Und da sie den Konig David sah hüpfen und spielen, verachtete sie ihn in ihrem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Und da sie die Lade Gottes hineinbrachten, setzten sie sie in die Hütte, die ihr David aufgerichtet hatte, und opferten Brandopfer und Dankopfer vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Und da David die Brandopfer und Dankopfer ausqerichtet hatte, seqnete er das Volk im Namen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Und teilete aus jedermann in Israel, beide Mannern und Weibern, ein Laib Brots und ein Stuck Fleisches und ein Nol Lel Weins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Und er stellete vor die Lade des HERRN etliche Leviten zu Dienern, daß sie preiseten, danketen und lobeten den HERRN, den Gott Israels:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'namlich Assaph, den ersten; Sacharja, den andern; Jeiel, Semiramoth, Jehiel, Mathithja, Eliab, Benaja, Obed-Edom und Jeiel mit Psaltern und Harfen; Assaph aber mit hellen Zimbeln;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Benaja aber und Jehasiel, die Priester, mit Trommeten allezeit vor der Lade des Bundes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Zu der Zeit bestellete David zum ersten, dem HERRN zu danken, durch Assaph und seine Bruder:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Danket dem HERRN, prediget seinen Namen, tut kund unter den Volkern sein Tun!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Singet, spielet und dichtet ihm von alien seinen Wundern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Rühmet seinen heiligen Namen! Es freue sich das Herz derer, die den HERRN suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Fraget nach dem HERRN und nach seiner Macht; suchet sein Angesicht allezeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Gedenket seiner Wunder, dieergetan hat, seiner Wunder und seines Worts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'ihr, der Same Israels, seines Knechts, ihr Kinder Jakobs, seine Auserwahlten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Er istder HERR, unser Gott; er richtetin aller Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Gedenket ewiglich seines Bundes, was er verheißen hat in tausend Geschlechter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'den ergemacht hat mit Abraham, und seines Eides mit Isaak;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'und stellete dasselbe Jakob zum Recht und Israel zum ewigen Bunde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'und sprach: Dirwill ich das Land Kanaan geben, das Los eures Erbteils,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'da sie wenig und gering waren und Fremdlinge drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Und sie zogen von einem Volk zum andern und aus einem Konigreich zum andern Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Er liefi niemand ihnen Schaden tun und strafte Konige urn ihretwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Tastet meine Gesalbten nicht an und tut meinen Propheten kein Leid!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Singet dem HERRN, alle Lande, verkundiget taglich sein Heil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Erzahlet unter den Heiden seine Herrlichkeit und unter den Volkern seine Wunder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Denn der HERR ist grol L und fast loblich und herrlich uber alle Gotten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Denn aller Heiden Gotter sind Gotzen; der HERR aber hat den Himmel gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Es stehet herrlich und prachtig vor ihm, und gehet gewaltiglich und frohlich zu an seinem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Bringet her dem HERRN, ihr Vdlker, bringet her dem HERRN Ehre und Macht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Bringet her des HERRN Namen die Ehre; bringet Geschenke und kommt vor ihn und betet den HERRN an in heiligem Schmuck!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Es furchte ihn alle Welt! Er hat den Erdboden bereitet, dafi er nicht bewegt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Es freue sich der Himmel, und die Erde sei frohlich und man sage unter den Heiden, daß der HERR regieret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Das Meer brause, und was drinnen ist; und das Feld sei frohlich und alles, was drauf ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Und lasset jauchzen alle Baume im Walde vor dem HERRN; denn er kommt, zu richten die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Danket dem HERRN; denn eristfreundlich, und seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Und sprechet: Hilf uns, Gott, unser Heiland, und sammle uns und errette uns aus den Heiden, daß wirdeinem heiligen Namen danken und dir Lob sagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Gelobet sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit; und alles Volk sage: Amen! und lobe den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Also ließ er daselbst vor der Lade des Bundes des HERRN Assaph und seine Bruder, zu dienen vor der Lade allezeit, einen jeglichen Tag sein Tagwerk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'aber Obed-Edom und ihre Bruder, achtundsechzig, und Obed-Edom, den Sohn Jedithuns, und Hossa zu Torhutern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Und Zadok, den Priester, und seine Bruder, die Priester, liefi er vor der Wohnung des HERRN auf der Hohe zu Gibeon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'daß sie dem HERRN taglich Brandopfer taten auf dem Brandopferaltar des Morgens und des Abends, wie geschrieben stehet im Gesetz des HERRN, das eran Israel geboten hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'und mit ihnen Heman und Jedithun und die andern Erwahlten, die mit Namen benanntwaren, zu danken dem HERRN, daß seine Gute wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'und mit ihnen Heman und Jedithun, mit Trommeten und Zimbeln zu klingen und mit Saitenspielen Gottes. Die Kinder aber Jedithuns machte er zu Torhutern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Also zog alles Volk hin, ein jeglicher in sein Haus; und David kehrete auch hin, sein Haus zu segnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Es begab sich, da David in seinem Hause wohnete, sprach erzu dem Propheten Nathan: Siehe, ich wohne in einem Zedernhause, und die Lade des Bundes des HERRN ist unter den Teppichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Nathan sprach zu David: Alles, was in deinem Herzen ist, das tue; denn Gott ist mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Aber in derselben Nacht kam das Wort Gottes zu Nathan und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Gehe hin und sage David, meinem Knechte: So spricht der HERR: Du sollst mir nicht ein Haus bauen zur Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Denn ich habe in keinem Hause gewohnet von dem Tage an, da ich die Kinder Israel ausfuhrete, bis auf diesen Tag, sondern ich bin gewesen, wo die Hütte gewesen ist und die Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Wo ich gewandelt habe im ganzen Israel, habe ich auch zu der Richter einem in Israel je gesagt, denen ich gebot, zu weiden mein Volk, und gesprochen: Warum bauet ihr mir nicht ein Zedernhaus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'So sprich nun also zu meinem Knechte David: So spricht der HERR Zebaoth: Ich habe dich genommen von der Weide hinter den Schafen, daß du solltest sein ein Fürst uber mein Volk Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'und bin mit dir gewesen, wo du hingegangen bist, und habe deine Feinde ausgerottet vor dir und habe direinen Namen gemacht, wie die Groften auf Erden Namen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Ich will aber meinem Volk Israel eine Statte setzen und will es pflanzen, daß es daselbst wohnen soil und nicht mehr bewegt werde; und die bosen Leute sollen es nicht mehr schwachen, wie vorhin');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'und zu den Zeiten, da ich den Richtern gebot uber mein Volk Israel; und ich will alle deine Feinde demutigen; und verkündige dir, daß der HERR direin Haus bauen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Wenn aber deine Tage aussind, daß du hingehest zu deinen Vatern, so will ich deinen Samen nach dir erwecken, der deiner Sohne einer sein soil, dem will ich sein Konigreich bestatigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Der soil mir ein Haus bauen, und ich will seinen Stuhl bestatigen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ich will sein Vatersein, und er soil mein Sohn sein. Und ich will meine Barmherzigkeit nicht von ihm wenden, wie ich sie von dem gewandt habe, der vor dir war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'sondern ich will ihn setzen in mein Haus und in mein Konigreich ewiglich, daß sein Stuhl bestandig sei ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Und da Nathan nach alien diesen Worten und Gesicht mit David redete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'kam der Konig David und blieb vor dem HERRN und sprach: Wer bin ich, HERR Gott, und was ist mein Haus, daß du mich bis hieher gebracht hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Und das hat dich noch zu wenig gedeucht, Gott, sondern hast uber das Haus deines Knechts noch von femem Zukunftigen geredet; und du hast angesehen mich, als in der Gestalt eines Menschen, der in der Hohe Gott der HERR ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Was soil David mehr sagen zu dir, daß du deinen Knecht herrlich machest? Du erkennest deinen Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'HERR, urn deines Knechts willen, nach deinem Herzen hast du all solch grofte Dinge getan, daß du kundtatest alle Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'HERR, es ist dein gleichen nicht, und ist kein Gott denn du, von welchem wir mit unsern Ohren gehoret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Und wo ist ein Volk auf Erden, wie dein Volk Israel, da ein Gott hingegangen sei, ihm ein Volk zu erlosen und ihm selbst einen Namen zu machen von groften und schrecklichen Dingen, Heiden auszustoften vor deinem Volk her, das du aus Agypten erloset hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Und hast dir dein Volk Israel zum Volke gemacht ewiglich; und du, HERR, bist ihr Gott worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nun, HERR, das Wort, das du geredet hast uber deinen Knecht und uber sein Haus, werde wahr ewiglich, und tue, wie du geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Und dein Name werde wahr und graft ewiglich, daß man sage: Der HERR Zebaoth, der Gott Israels, ist Gott in Israel. Und das Haus deines Knechts David sei bestandig vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Denn du, HERR, hast das Ohr deines Knechts geoffnet, daß du ihm ein Haus bauen willst; darum hat dein Knecht funden, daß er vor dir betet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nun, HERR, du bist Gott und hast solch Gutes deinem Knechte geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Nun hebe an zu segnen das Haus deines Knechts, daß es ewiglich sei vor dir; denn was du, HERR, segnest, das ist gesegnet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Nach diesem schlug David die Philister und demutigte sie und nahm Gath und ihre Tochter aus der Philister Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Auch schlug erdie Moabiter, daß die Moabiter David untertanig wurden und Geschenke brachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Erschlug auch Hadadeser, den Konig zu Zoba in Hemath, da er hinzog, sein Zeichen aufzurichten am Wasser Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Und David gewann ihm ab tausend Wagen, siebentausend Reiter und zwanzigtausend Mann zu Fuf J. Und David verlahmete alle Wagen und behielt hundert Wagen übrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Und die Syrervon Damaskus kamen, dem Hadadeser, dem Konige zu Zoba, zu helfen. Aber David schlug derselben Syrer zweiundzwanzigtausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Und legte Volk gen Damaskus in Syrien, daß die Syrer David untertanig wurden und brachten ihm Geschenke. Denn der HERR half David, wo er hinzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Und David nahm die güldenen Schilde, die Hadadesers Knechte hatten, und brachte sie gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Auch nahm David aus den Stadten Hadadesers, Tibehath und Chun, sehrviel Erzes, davon Salomo das eherne Meer und Saulen und eherne Gefafte machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Und da Thogu, der Konig zu Hemath, horete, daß David alle Macht Hadadesers, des Konigs zu Zoba, geschlagen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'sandte er seinen Sohn Hadoramzum Konige David und lieft ihn gruften und segnen, daß er mit Hadadeser gestritten und ihn geschlagen hatte. Denn Thogu hatte einen Streit mit Hadadeser. Auch alle güldenen, silbernen und ehernen Gefafte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'heiligte der Konig David dem HERRN mit dem Silber und Golde, das er den Heiden genommen hatte, namlich den Edomitern, Moabitern, Ammonitern, Philistern und Amalekitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Und Abisai, der Sohn Zerujas, schlug der Edomiter im Salztal achtzehntausend;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'und legte Volk in Edomaa, daß alle Edomiter David untertanig waren. Denn der HERR half David, wo er hinzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Also regierete David fiber das ganze Israel und handhabete Gericht und Gerechtigkeit all seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab, der Sohn Zerujas, war über das Heer, Josaphat, der Sohn Ahiluds, war Kanzler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadok, der Sohn Ahitobs, und Abimelech, der Sohn Abjathars, waren Priester. Sausa war Schreiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, der Sohn Jojadas, war fiber die Krethi und Plethi. Und die ersten Sohne Davids waren dem Konige zur Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Und nach diesem starb Nahas, der Konig der Kinder Ammon, und sein Sohn ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Da gedachte David: Ich will Barmherzigkeit tun an Hanon, dem Sohne Nahas; denn sein Vater hat an mir Barmherzigkeit getan. Und sandte Boten hin, ihn zu trosten fiber seinen Vater. Und da die Knechte Davids ins Land der Kinder Ammon kamen zu Hanon, ihn zu trosten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'sprachen die Fürsten der Kinder Ammon zu Hanon: Meinest du, daß David deinen Vater ehre vor deinen Augen, daß er Trosterzu dirgesandt hat? Ja, seine Knechte sind kommen zu dir, zu forschen und umzukehren und zu verkundschaften das Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Da nahm Hanon die Knechte Davids und beschor sie und schnitt ihre Kleider halb ab bis an die Lenden; und lieft sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Und sie gingen weg und lieften\'s David ansagen durch Manner. Er aber sandte ihnen entgegen (denn die Manner waren sehrgeschandet). Und der Konig sprach: Bleibet zu Jericho, bis euer Bart wachse; so kommt dann wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Da aber die Kinder Ammon sahen, daß sie stanken vor David, sandten sie hin, beide Hanon und die Kinder Ammon, tausend Zentner Silbers, Wagen und Reiter zu dingen aus Mesopotamia, und Maecha und aus Zoba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Und dingeten zweiunddreiftigtausend Wagen und den Konig Maecha mit seinem Volk; die kamen und lagerten sich vor Medba. Und die Kinder Ammon sammelten sich auch aus ihren Stadten und kamen zum Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Da das David horete, sandte er hin Joab mit dem ganzen Heer der Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Die Kinder Ammon aber waren ausgezogen und rusteten sich zum Streit vor der Stadt Tor. Die Konige aber, die kommen waren, hielten im Felde besonders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Da nun Joab sah, daß vorne und hinter ihm Streit wider ihn war, erwahlete er aus aller jungen Mannschaft in Israel und rustete sich gegen die Syrer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Das übrige Volk aber tat er unter die Hand Abisais, seines Bruders, daß sie sich rusteten wider die Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Und sprach: Wenn mir die Syrer zu stark werden, so komm mirzu Hilfe; wo aber die Kinder Ammon dir zu stark werden, will ich dir helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sei getrost und laft uns getrost handeln fur unser Volk und fur die Stadte unsers Gottes! Der HERR tue, was ihm gefallt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Und Joab machte sich herzu mit dem Volk, das bei ihm war, gegen die Syrer zu streiten; und sie flohen vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Da aber die Kinder Ammon sahen, daß die Syrer flohen, flohen sie auch vor Abisai, seinem Bruder, und zogen in die Stadt. Joab aber kam gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Da aber die Syrer sahen, daß sie vor Israel geschlagen waren, sandten sie Boten hin und brachten heraus die Syrer jenseit des Wassers. Und Sophach, der Feldhauptmann Hadadesers, zog vor ihnen her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Da das David angesagt ward, sammelte er zuhauf das ganze Israel und zog über den Jordan; und da er an sie kam, rustete er sich an sie. Und David rustete sich gegen die Syrer zum Streit, und sie stritten mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Aber die Syrer flohen vor Israel. Und David erwurgete der Syrer siebentausend Wagen und vierzigtausend Mann zu Fuft; dazu totete er Sophach, den Feldhauptmann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Und da die Knechte Hadadesers sahen, dafi sie vor Israel geschlagen waren, machten sie Frieden mit David und seinen Knechten. Und die Syrer wollten den Kindern Ammon nicht mehr helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Und da das Jahr urn war, zur Zeit, wenn die Konige ausziehen, fuhrete Joab die Fleermacht und verderbete der Kinder Ammon Land, kam und belagerte Rabba. David aber blieb zu Jerusalem. Und Joab schlug Rabba und zerbrach sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Und David nahm die Krone ihres Konigs von seinem Haupt und fand daran einen Zentner Goldes schwer und Edelgesteine; und sie ward David auf sein Haupt gesetzt. Auch fuhrete er aus der Stadt sehr viel Raubs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Aber das Volk drinnen fuhrete er heraus und teilte sie mit Sagen und eisernen Haken und Keilen. Also tat David alien Stadten der Kinder Ammon. Und David zog samt dem Volk wieder gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Danach erhub sich ein Streit zu Gaser mit den Philistern. Dazumal schlug Sibechai, der Husathiter, den Sibai, der aus den Kindern der Riesen war, und demutigte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Und es erhub sich noch ein Streit mit den Philistern. Da schlug Elhanan, der Sohn Jairs, den Lahemi, den Bruder Goliaths, den Gathiter, welcher hatte eine Spieftstange wie ein Weberbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Abermal ward ein Streit zu Gath. Da war ein grower Mann, der hatte je sechs Finger und sechs Zehen, die machen vierundzwanzig, und erwar auch von den Riesen geboren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'und hohnete Israel. Aber Jonathan, der Sohn Simeas, des Bruders Davids, schlug ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Diese waren geboren von den Riesen zu Gath und fielen durch die Hand Davids und seiner Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Und der Satan stund wider Israel und gab David ein, daß er Israel zahlen lieft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Und David sprach zu Joab und zu des Volks Obersten: Gehet hin, zahlet Israel, von Berseba an bis gen Dan; und bringet\'s zu mir, daß ich wisse, wieviel ihrer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab sprach: Der HERR tue zu seinem Volk, wie sie jetzt sind, hundertmal soviel; aber, mein Herr Konig, sind sie nicht alle meines Herrn Knechte? Warum fraget denn mein Herr danach? Warum soil eine Schuld auf Israel kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Aber des Konigs Wort ging fort wider Joab. Und Joab zog aus und wandelte durch das ganze Israel und kam gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Und gab die Zahl des gezahlten Volks David. Und es war des ganzen Israel elfhundertmal tausend Mann, die das Schwert auszogen, und Juda vierhundertmal und siebenzigtausend Mann, die das Schwert auszogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Levi aber und Benjamin zahlete er nicht unter diese; denn es war dem Joab des Konigs Wort ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Abersolches gefiel Gott ubel; denn er schlug Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Und David sprach zu Gott: Ich habe schwerlich gesundiget, daß ich das getan habe; nun aber nimm weg die Missetat deines Knechts, denn ich habe fast toricht getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Und der HERR redete mit Gad, dem Schauer Davids, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Gehe hin und rede mit David und sprich: So spricht der HERR: Dreierlei lege ich dir vor; erwahle dir der eins, das ich dir tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Und da Gad zu David kam, sprach erzu ihm: So spricht der HERR: Erwahle dir');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'entwederdrei Jahre Teurung, oderdrei Monden Flucht vor deinen Widersachern und vor dem Schwert deiner Feinde, daß dich\'s ergreife, Oder drei Tage das Schwert des HERRN und Pestilenz im Lande, daß der Engel des HERRN verderbe in alien Grenzen Israels. So siehe nun zu, was ich antworten soil dem, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David sprach zu Gad: Mir ist fast angst; doch ich will in die Hand des HERRN fallen, denn seine Barmherzigkeit ist sehr graft, und will nicht in Menschenhande fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Da lieft der HERR Pestilenz in Israel kommen, daß siebenzigtausend Mann fielen aus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Und Gott sandte den Engel gen Jerusalem, sie zu verderben. Und im Verderben sah der HERR drein, und reuete ihn das Ubel und sprach zum Engel, dem Verderber: Es ist genug, laft deine Hand ab! Der Engel aber des HERRN stund bei der Tenne Arnans, des Jebusiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Und David hub seine Augen auf und sah den Engel des HERRN stehen zwischen Himmel und Erde, und ein bloft Schwert in seiner Hand ausgereckt uber Jerusalem. Da fiel David und die Altesten, mit Sacken bedeckt, auf ihr Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Und David sprach zu Gott: Bin ich\'s nicht, der das Volk zahlen hieft? Ich bin, der gesundiget und das Ubel getan hat; diese Schafe aber, was haben sie getan? HERR, mein Gott, laft deine Hand wider mich und meines Vaters Haus und nicht wider dein Volk sein zu plagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Und der Engel sprach zu Gad, daß er David sollte sagen, daß David hinaufgehen und dem HERRN einen Altar aufrichten sollte in der Tenne Arnans, des Jebusiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Also ging David hinauf nach dem Worte Gads, das er geredet hatte in des HERRN Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Arnan aber, da er sich wandte und sah den Engel, und seine vier Sohne mit ihm, versteckten sie sich; denn Arnan drosch Weizen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Als nun David zu Arnan ging, sah Arnan und ward Davids gewahr; und ging heraus aus der Tenne und betete David an mit seinem Antlitz zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Und David sprach zu Arnan: Gib mir Raum in der Tenne, dafi ich einen Altar dem HERRN drauf baue; um voll Geld sollst du mir ihn geben, auf daß die Plage vom Volk aufhore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Arnan aber sprach zu David: Nimm dir und mache, mein Herr Konig, wie dir\'s gefallt; siehe, ich gebe das Rind zum Brandopfer und das Geschirr zu Holz und Weizen zum Speisopfer: alles gebe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Aber der Konig David sprach zu Arnan: Nicht also, sondern um voll Geld will ich\'s kaufen; denn ich will nicht, das dein ist, nehmen vordem HERRN und will\'s nicht umsonst haben zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Also gab David Arnan um den Raum Gold am Gewicht sechshundert Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Und David bauete daselbst dem HERRN einen Altar und opferte Brandopfer und Dankopfer. Und da er den HERRN anrief, erhorete er ihn durchs Feuer vom Himmel auf dem Altar des Brandopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Und der HERR sprach zum Engel, daß er sein Schwert in seine Scheide kehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Zur selbigen Zeit, da David sah, daß ihn der HERR erhoret hatte auf dem Platz Arnans, des Jebusiters, pflegte er daselbst zu opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Denn die Wohnung des HERRN, die Mose in der Wüste gemacht hatte, und der Brandopferaltar war zu der Zeit in der Hohe zu Gibeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'David aber konnte nicht hingehen vor denselben, Gott zu suchen, so war er erschrocken vor dem Schwert des Engels des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Und David sprach: Hie soil das Haus Gottes des HERRN sein und dies der Altar zum Brandopfer Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Und David hiefi versammeln die Fremdlinge, die im Lande Israel waren, und bestellete Steinmetzen, Steine zu hauen, das Haus Gottes zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Und David bereitete viel Eisens zu Nageln an die Turen in den Toren, und was zu nageln ware, und so viel Erzes, daß nicht zu wagen war;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'auch Zedernholz ohne Zahl; denn die von Zidon und Tyrus brachten viel Zedernholz zu David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Denn David gedachte: Mein Sohn Salomo ist ein Knabe und zart; das Haus aber, das dem HERRN soil gebauet werden, soli groli sein, daß sein Name und Ruhm erhaben werde in alien Landen; darum will ich ihm Vorrat schaffen. Also schaffte David viel Vorrats vor seinem Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Und er rief seinem Sohn Salomo und gebot ihm, zu bauen das Haus des HERRN, des Gottes Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Und sprach zu ihm: Mein Sohn, ich hatte es im Sinn, dem Namen des HERRN, meines Gottes, ein Haus zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Aber das Wort des HERRN kam zu mir und sprach: Du hast viel Bluts vergossen und grolie Kriege geführt, darum sollst du meinem Namen nicht ein Haus bauen, weil du so viel Bluts auf die Erde vergossen hast vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Siehe, der Sohn, der dir geboren soil werden, der wird ein ruhiger Mann sein; denn ich will ihn ruhen lassen von alien seinen Feinden umher; denn er soil Salomo heilien; denn ich will Frieden und Ruhe geben uber Israel sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Der soil meinem Namen ein Haus bauen. Er soil mein Sohn sein, und ich will sein Vater sein. Und ich will seinen koniglichen Stuhl uber Israel bestatigen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'So wird nun, mein Sohn, der HERR mit dir sein, und wirst gluckselig sein, daß du dem HERRN, deinem Gott, ein Haus bauest, wie er von dir qeredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Auch wird der HERR dir geben Klugheit und Verstand und wird dir Israel befehlen, daß du haltest das Gesetz des HERRN, deines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Dann aber wirst du gluckselig sein, wenn du dich haltst, daß du tuest nach den Geboten und Rechten, die der HERR Mose geboten hat an Israel. Sei getrost und unverzagt; furchte dich nicht und zage nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Siehe, ich habe in meiner Armut verschafft zum Hause des HERRN hunderttausend Zentner Goldes und tausendmal tausend Zentner Silbers, dazu Erz und Eisen ohne Zahl, denn es ist sein zu viel. Auch Holz und Steine habe ich geschickt; des magst du noch mehrmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'So hast du viel Arbeiter, Steinmetzen und Zimmerleute an Stein und Holz und allerlei Weisen auf allerlei Arbeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'an Gold, Silber, Erz und Eisen ohne Zahl. So mache dich auf und richte es aus; der HERR wird mit dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Und David gebot alien Obersten Israels, daß sie seinem Sohn Salomo hulfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Ist nicht der HERR, euer Gott, miteuch und hat euch Ruhe gegeben umher? Denn er hat die Einwohner des Landes in eure Hande gegeben, und das Land ist untergebracht vor dem HERRN und vor seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'So gebet nun euer Herz und eure Seele, den HERRN, euren Gott, zu suchen. Und machet euch auf und bauet Gott dem HERRN ein Heiligtum, daß man die Lade des Bundes des HERRN und die heiligen Gefalie Gottes ins Haus bringe, das dem Namen des HERRN gebauet soil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Also machte David seinen Sohn Salomo zum Konige uber Israel, da er alt und des Lebens satt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Und David versammelte alle Obersten in Israel und die Priester und Leviten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'daß man die Leviten zahlete von dreißig Jahren und druber; und ihre Zahl war von Haupt zu Haupt, das starke Manner waren, achtunddreitügtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Aus welchen wurden vierundzwanzigtausend verordnet, die das Werk am Hause des HERRN trieben, und sechstausend Amtleute und Richter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'und viertausend Torhuter und viertausend Lobsanger des HERRN mit Saitenspielen, die ich gemacht habe, Lob zu singen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Und David machte die Ordnung unterden Kindern Levi, namlich unter Gerson, Kahath und Merari.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Die Gersoniten waren: Laedan und Simei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Die Kinder Laedan: der erste Jehiel, Setham und Joel, die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Die Kinder aber Simeis waren: Salomith, Hasiel und Haran, die drei. Diese waren die Vornehmsten unterden Vatern von Laedan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Auch waren diese Simeis Kinder: Jahath, Sina, Jeus und Bria. Diese vier waren auch Simeis Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahath aber war der erste, Sina der andere. Aber Jeus und Bria hatten nicht viel Kinder, darum wurden sie fur eines Vaters Haus gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Die Kinder Kahaths waren: Amram, Jezehar, Hebron und Usiel, die vier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Die Kinder Amrams waren: Aaron und Mose. Aaron aber ward abgesondert, dafi er geheiliget wurde zum Allerheiligsten, er und seine Sohne ewiglich, zu rauchern vordem HERRN und zu dienen und zu segnen in dem Namen des HERRN ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Und Moses, des Mannes Gottes, Kinder wurden genannt unter der Leviten Stamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Die Kinder aber Moses waren Gersom und Elieser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Die Kinder Gersoms: der erste war Sebuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Die Kinder Eliesers: der erste war Rehabja. Und Elieser hatte keine andern Kinder. Aber der Kinder Rehabjas waren viel druber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Die Kinder Jezehars waren: Salomith der erste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Die Kinder Hebrons waren: Jeria der erste, Amarja der andere, Jehasiel der dritte und Jakmeam der vierte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Die Kinder Usiels waren: Micha der erste und Jesia der andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Die Kinder Meraris waren: Maheli und Musi. Die Kinder Mahelis waren: Eleasar und Kis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleasar aber starb und hatte keine Sohne, sondern Tochter; und die Kinder Kis, ihre Bruder, nahmen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Die Kinder Musis waren: Maheli, Eder und Jeremoth, die drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Das sind die Kinder Levi unter ihrer Vater Hausern und Vornehmste der Vater, die gerechnet wurden nach der Namen Zahl bei den Hauptern, welche taten das Geschaft des Amts im Hause des HERRN, von zwanzig Jahren und druber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Denn David sprach: Der HERR, der Gott Israels, hat seinem Volk Ruhe gegeben und wird zu Jerusalem wohnen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Auch unter den Leviten wurden gezahlet der Kinder Levi von zwanzig Jahren und druber, daß sie die Wohnung nicht tragen durften mit all ihrem Gerate ihres Amts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'sondern nach den letzten Worten Davids,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'daß sie stehen sollten unter der Hand der Kinder Aaron, zu dienen im Hause des HERRN im Hofe, und zu den Kasten und zur Reinigung und zu allerlei Heiligtum und zu allem Werk des Amts im Hause Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'und zum Schaubrot, zum Semmelmehl, zum Speisopfer, zu ungesauerten Fladen, zur Pfanne, zu Rosten und zu allem Gewicht und Ma(J;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'und zu stehen des Morgens, zu danken und zu loben den HERRN; des Abends auch also;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'und alle Brandopfer dem HERRN zu opfern auf die Sabbate, Neumonden und Feste nach der Zahl und Gebuhr allewege vordem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'daß sie warten der Hut an der Hutte des Stiffs und des Heiligtums und der Kinder Aaron, ihrer Bruder, zu dienen im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Aber dies war die Ordnung der Kinder Aaron. Die Kinder Aarons waren: Nadab, Abihu, Eleasar und Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Aber Nadab und Abihu starben vor ihrem Vater und hatten keine Kinder. Und Eleasar und Ithamar wurden Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Und David ordnete sie also: Zadok aus den Kindern Eleasars und Ahimelech aus den Kindern Ithamars nach ihrer Zahl und Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Und wurden der Kinder Eleasars mehr funden zu vornehmsten starken Mannern denn der Kinder Ithamars. Und er ordnete sie also: namlich sechzehn aus den Kindern Eleasars zu Obersten unter ihrer Vater Haus und acht aus den Kindern Ithamars unter ihrer Vater Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Er ordnete sie aber durchs Los darum, daß beide aus Eleasars und Ithamars Kindern Oberste waren im Heiligtum und Oberste vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Und der Schreiber Semaja, der Sohn Nethaneels, aus den Leviten, beschrieb sie vor dem Konige und vor den Obersten und vor Zadok, dem Priester, und vor Ahimelech, dem Sohne Abjathars, und vor den obersten Vatern unter den Priestern und Leviten; namlich ein Vaterhaus fur Eleasar und das andere fur Ithamar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Und das erste Los fiel auf Jojarib, das andere auf Jedaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'das dritte auf Harim, das vierte auf Seorim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'das funfte auf Malchija, das sechste auf Mejamin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'das siebente auf Hakoz, das achte auf Abia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'das neunte auf Jesua, das zehnte auf Sechanja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'das elfte auf Eliasib, das zwolfte auf Jakim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'das dreizehnte auf Hupa, das vierzehnte auf Jesebeab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'das funfzehnte auf Bilga, das sechzehnte auf Immer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'das siebenzehnte auf Hesir, das achtzehnte auf Hapizez,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'das neunzehnte auf Pethahja, das zwanzigste auf Jeheskel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'das einundzwanzigste auf Jachin, das zweiundzwanzigste auf Gamul,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'das dreiundzwanzigste auf Delaja, das vierundzwanzigste auf Maasia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Das ist ihre Ordnung nach ihrem Amt, zu gehen in das Haus des HERRN, nach ihrer Weise unter ihrem Vater Aaron, wie ihnen der HERR, der Gott Israels, geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Aber unter den andern Kindern Levi war unter den Kindern Amrams Subael. Unter den Kindern Subaels war Jehdea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Unter den Kindern Rehabjas war der erste Jesia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Aber unter den Jezeharitern war Slomoth. Unter den Kindern Slomoths war Jahath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Die Kinder Hebrons waren: Jeria der erste, Amarja der andere, Jahesiel der dritte, Jakmeam der vierte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Die Kinder Usiels waren Micha. Unter den Kindern Michas war Samir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Der Bruder Michas war Jesia. Unter den Kindern Jesia war Sacharja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Die Kinder Meraris waren: Maheli und Musi, des Sohn war Jaesia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Die Kinder Meraris von Jaesia, seinem Sohn, waren: Soham, Sakur und Ibri.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Maheli aber hatte Eleasar; denn er hatte keine Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Von Kis. Die Kinder Kis waren: Jerahmeel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Die Kinder Musis waren: Maheli, Eder und Jerimoth. Das sind die Kinder der Leviten unter ihrer Vater Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Und man warf fur sie auch das Los neben ihren Brüdem, den Kindern Aaron, vordem Konige David und Zadok und Ahimelech und vor den obersten Vatern unter den Priestern und Leviten, dem kleinsten Bruder ebensowohl als dem Obersten unter den Vatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Und David samt den Feldhauptleuten sonderte ab zu Amtern unter den Kindern Assaphs, Hemans und Jedithuns, die Propheten, mit Harfen, Psaltern und Zimbeln; und sie wurden gezahlet zum Werk nach ihrem Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Unter den Kindern Assaphs war: Sakur, Joseph, Nethanja, Asarela, Kinder Assaphs, unter Assaph, der da weissagte bei dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Von Jedithun. Die Kinder Jedithuns waren: Gedalja, Zori, Jesaja, Hasabja, Mathithja, die sechse unter ihrem Vater Jedithun, mit Harfen, die da weissageten, zu danken und zu loben den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Von Heman. Die Kinder Hemans waren: Bukia, Mathanja, Usiel, Sebuel, Jerimoth, Hananja, Hanani, Eliatha, Gidalthi, Romamthi-Eser, Jasbekasa, Mallothi, Hothir und Mahesioth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Diese waren alie Kinder Hemans, des Schauers des Konigs in den Worten Gottes, das Horn zu erheben; denn Gott hatte Heman vierzehn Sohne und drei Tochter gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Diese waren alie unter ihren Vatern Assaph, Jedithun und Heman, zu singen im Hause des HERRN mit Zimbeln, Psaltern und Harfen, nach dem Amt im Hause Gottes bei dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Und es war ihre Zahl samt ihren Brüdem, die im Gesang des HERRN gelehrt waren, allesamt Meister, zweihundertundachtundachtzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Und sie warfen Los über ihr Amt zugleich, dem Kleinsten wie dem Groi Jten, dem Lehrer wie dem Schuler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Und das erste Los fiel unter Assaph auf Joseph. Das andere auf Gedalja samt seinen Brüdem und Sohnen, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Das dritte auf Sakur samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Das vierte auf Jezri samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Das fünfte auf Nethanja samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Das sechste auf Bukia samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Das siebente auf Jesreela samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Das achte auf Jesaja samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Das neunte auf Mathanja samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Daszehnte auf Simei samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Das elfte auf Asareel samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Das zwolfte auf Hasabja samt seinen Sohnen und Brüdem; der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Das dreizehnte auf Subael samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Das vierzehnte auf Mathithja samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Das fünfzehnte auf Jeremoth samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Das sechzehnte auf Hananja samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Das siebenzehnte auf Jasbekasa samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Das achtzehnte auf Hanani samt seinen Sohnen und Brüdem, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Das neunzehnte auf Mallothi samt seinen Sohnen und Brudern, derwaren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Das zwanzigste auf Eliatha samt seinen Sohnen und Brudern, derwaren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Das einundzwanzigste auf Hothir samt seinen Sohnen und Brudern, derwaren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Das zweiundzwanzigste auf Gidalthi samt seinen Sohnen und Brudern, derwaren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Das dreiundzwanzigste auf Mahesioth samt seinen Sohnen und Brudern, derwaren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Das vierundzwanzigste auf Romamthi-Eser samt seinen Sohnen und Brudern, der waren zwolf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Von der Ordnung der Torhuter. Unter den Korhitern war Meselemja, der Sohn Kores, aus den Kindern Assaphs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Die Kinder aber Meselemjas waren diese: der erstgeborne Sacharja, der andere Jediael, der dritte Sebadja, der vierte Jathniel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'der funfte Elam, der sechste Johanan, der siebente Elioenai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Die Kinder aber Obed-Edoms waren diese: der erstgeborne Semaja, der andere Josabad, der dritte Joah, der vierte Sachar, der funfte Nethaneel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'der sechste Ammiel, der siebente Isaschar, der achte Pegulthai; denn Gott hatte ihn gesegnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Und seinem Sohn Semaja wurden auch Sohne geboren, die im Hause ihrer Vater herrscheten; denn es waren starke Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'So waren nun die Kinder Semajas: Athni, Rephael, Obed und Elsabad, des Bruder fleillige Leute waren, Elihu und Samachja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Diese waren alle aus den Kindern Obed-Edoms; sie samt ihren Kindern und Brudern, fleifüge Leute, geschickt zu Amtern, waren zweiundsechzig von Obed-Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemja hatte Kinder und Bruder, fleilüge Manner, achtzehn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Hossa aber aus den Kindern Meraris hatte Kinder: den vornehmsten Simri (denn es war der Erstgeborne nicht da, darum setzte ihn sein Vater zum Vornehmsten),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'den andern Hilkia, den dritten Tebalja, den vierten Sacharja. Aller Kinder und Bruder Hossas waren dreizehn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Dies ist die Ordnung der Torhuter unter den Hauptern der Helden am Amt neben ihren Brudern, zu dienen im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Und das Los ward geworfen, dem Kleinen wie dem Grolien, unter ihrer Vater Hause, zu einem jeglichen Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Das Losgegen Morgen fiel auf Meselemja; aber seinem Sohn Sacharja, der ein kluger Rat war, warf man das Los, und fiel ihm gegen Mitternacht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obed-Edom aber gegen Mittag und seinen Sohnen bei dem Hause Esupim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Und Supim und Hossa gegen Abend bei dem Tor, da man gehet auf der Stralie der Brandopfer, da die Hut neben andern stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Gegen den Morgen waren der Leviten sechs, gegen Mitternacht des Tages vier, gegen Mittag des Tages vier; bei Esupim aber je zween und zween;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'an Parbar aber gegen Abend vier an der Straße und zween an Parbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Dies sind die Ordnungen der Torhuter unter den Kindern der Korhiter und den Kindern Meraris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Von den Leviten aber war Ahia uber die Schatze des Hauses Gottes und uber die Schatze, die geheiliget wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Von den Kindern Laedans, der Kinder der Gersoniten. Von Laedan waren Haupter der Vater, namlich die Jehieliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Die Kinder der Jehieliten waren: Setham und sein Bruder Joel fiber die Schatze des Hauses des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Unter den Amramiten, Jezehariten, Hebroniten und Usieliten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'war Sebuel, der Sohn Gersoms, des Sohns Moses, Fürst uber die Schatze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Aber sein Bruder Elieser hatte einen Sohn Rehabja, des Sohn war Jesaja, des Sohn war Joram, des Sohn war Sichri, des Sohn war Selomith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Derselbe Selomith und seine Bruder waren fiber alle Schatze der Geheiligten, welche der Konig David heiligte, und die obersten Vater unter den Obersten fiber tausend und uber hundert und die Obersten im Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Von Streiten und Rauben hatten sie es geheiliget, zu bessern das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Auch alles, was Samuel, der Seher, und Saul, der Sohn Kis, und Abner, der Sohn Ners, und Joab, der Sohn Zerujas, geheiliget hatten, alles Geheiligte war unter der Hand Selomiths und seiner Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Unter den Jezehariten war Chenanja mit seinen Sohnen zum Werk draulien fiber Israel, Amtleute und Richter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Unter den Hebroniten aber war Hasabja und seine Bruder, fleißige Leute, tausend und siebenhundert, fiber das Amt Israels diesseit des Jordans, gegen Abend, zu allerlei Geschaft des HERRN und zu dienen dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Item, unter den Hebroniten war Jeria, der Vornehmste unter den Hebroniten seines Geschlechts unter den Vatern. Es wurden aber unter ihnen gesucht und funden im vierzigsten Jahrdes Konigreichs Davids fleißige Manner zu Jaeser in Gilead,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'und ihre Brüder, fleißige Manner, zweitausend und siebenhundert oberste Vater. Und David setzte sie fiber die Rubeniter, Gaditerund den halben Stamm Manasse zu alien Handeln Gottes und des Koniges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Die Kinder Israel aber nach ihrer Zahl waren Haupter der Vater und uber tausend und uber hundert und Amtleute, die auf den Konig warteten, nach ihrer Ordnung, ab und zuzuziehen, einen jeglichen Monden einer, in alien Monden des Jahrs. Eine jegliche Ordnung aber hatte vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Uber die erste Ordnung des ersten Monden war Jasabeam, der Sohn Abdiels; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Aus den Kindern aber Perez war der Oberste uber alle Hauptleute der Heere im ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Uber die Ordnung des andern Monden war Dodai, der Ahohiter, und Mikloth war Furst uber seine Ordnung; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Derdritte Feldhauptmann des dritten Monden, der Oberste war Benaja, der Sohn Jojadas, des Priesters; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Das ist der Benaja, der Field unter dreifügen und uber dreitßig; und seine Ordnung war unter seinem Sohn Ammisabad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Der vierte im vierten Monden war Asahel, Joabs Bruder, und nach ihm Sabadja, sein Sohn; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Der funfte im funften Monden war Samehuth, der Jesrahiter; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Der sechste im sechsten Monden war Ira, der Sohn Ikes, der Thekoiter; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Der siebente im siebenten Monden war Helez, der Peloniter, aus den Kindern Ephraim; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Der achte im achten Monden war Sibechai, der FHusathiter, aus den Sarehitern; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Der neunte im neunten Monden war Abieser, der Anthothiter, aus den Kindern Jemini; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Der zehnte im zehnten Monden war Maherai, der Netophathiter, aus den Serahitern; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Der elfte im elften Monden war Benaja, der Pirgathoniter, aus den Kindern Ephraim; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Der zwolfte im zwolften Monden war Heldai, der Netophathiter, aus Athniel; und unter seiner Ordnung waren vierundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Uber die Stamme Israels aber waren diese: Unter den Rubenitern war Furst Elieser, der Sohn Sichris. Unter den Simeonitern war Sephatja, der Sohn Maechas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Unter den Leviten war Hasabja, der Sohn Kemuels. Unter den Aaronitern war Zadok.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Unter Juda war Elihu aus den Brudern Davids. Unter Isaschar war Amri, der Sohn Michaels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Unter Sebulon war Jesmaja, der Sohn Obadjas. Unter Naphthali war Jerimoth, der Sohn Asriels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Unter den Kindern Ephraim war Hosea, der Sohn Asasjas. Unter dem halben Stamm Manasse war Joel, der Sohn Pedajas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Unter dem halben Stamm Manasse in Gilead war Iddo, der Sohn Sacharjas. Unter Benjamin war Jaesiel, der Sohn Abners.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Unter Dan war Asareel, der Sohn Jerohams. Das sind die Fursten der Stamme Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Aber David nahm die Zahl nicht derer, die von zwanzig Jahren und drunter waren; denn der FHERR hatte geredet, Israel zu mehren wie die Sterne am Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab aber, der Sohn Zerujas, der hatte angefangen zu zahlen, und vollendete es nicht, denn es kam darum ein Zorn uber Israel; darum kam die Zahl nicht in die Chronik des Konigs David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Uber den Schatz des Konigs war Asmaveth, der Sohn Adiels; und uber die Schatze auf dem Lande in Stadten Dorfern und Schldssem war Jonathan, der Sohn Usias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Uber die Ackerleute, das Land zu bauen, war Esri, der Sohn Chelubs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Uber die Weinberge war Simei, der Ramathiter. Uber die Weinkeller und Schatze des Weins war Sabdi, der Siphimiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Uber die Olgarten und Maulbeerbaume in den Auen war Baal-Hanan, der Gaderiter. Uber den Olschatz war Joas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Ober die Weiderinder zu Saron war Sitrai, der Saroniter. Aber uber die Rinder in Grunden war Saphat, der Sohn Adlais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Uber die Kamele war Obil, der Ismaeliter. Uber die Esel war Jehedja, der Meronothiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Uber die Schafe war Jasis, der FHagariter. Diese waren alle Oberste uber die Güter des Konigs David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jonathan aber, Davids Vetter, war der Rat und Hofmeister und Kanzler. Und Jehiel, der Sohn Hachmonis, war bei den Kindern des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitophel war auch Rat des Konigs. Husai, der Arachiter, war des Konigs Freund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Nach Ahitophel war Jojada, der Sohn Benajas, und Abjathar. Joab aber war Feldhauptmann des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Und David versammelte gen Jerusalem alle Obersten Israels, namlich die Fursten der Stamme, die Fursten der Ordnungen, die auf den Konig warteten, die Fursten uber tausend und uber hundert, die Fursten uber die Guter und Vieh des Konigs und seiner Sohne, mit den Kammerern, die Kriegsmanner und alle tapferen Manner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Und David, der Konig, stund auf seinen Fufien und sprach: Floret mirzu, meine Bruder und mein Volk! Ich hatte mirvorgenommen, ein Flaus zu bauen, da ruhen sollte die Lade des Bundes des HERRN, und ein Fulischemel den Fulien unsers Gottes, und hatte mich geschicktzu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Aber Gott lieli mir sagen: Du sollst meinem Namen nicht ein Haus bauen; denn du bist ein Kriegsmann und hast Blut vergossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Nun hat der HERR, der Gott Israels, mich erwahlet aus meines Vaters ganzem Hause, daß ich Konig über Israel sein sollte ewiglich. Denn er hat Juda erwahlet zum Fürstentum und im Hause Judas meines Vaters Haus und unter meines Vaters Kindern hat er Gefallen gehabt an mir, daß er mich uber ganz Israel zum Konige machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Und unter alien meinen Sohnen (denn der HERR hat mir viel Sohne gegeben) hat er meinen Sohn Salomo erwahlet, daß er sitzen soil auf dem Stuhl des Konigreichs des HERRN uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Und hat mir geredet: Dein Sohn Salomo soil mein Haus und Hof bauen; denn ich habe ihn mir erwahlet zum Sohn, und ich will sein Vater sein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'und will sein Konigreich bestatigen ewiglich, so erwird anhalten, daß ertue nach meinen Geboten und Rechten, wie es heute stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nun vor dem ganzen Israel, der Gemeine des HERRN, und vor den Ohren unsers Gottes: So haltet und suchet alle Gebote des HERRN, eures Gottes, auf daß ihr besitzet das gute Land und beerbet auf eure Kinder nach euch ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Und du, mein Sohn Salomo, erkenne den Gott deines Vaters und diene ihm mit ganzem Herzen und mit williger Seele! Denn der HERR suchet alle Herzen und verstehet alter Gedanken Dichten. Wirst du ihn suchen, so wirst du ihn finden; wirst du ihn aber verlassen, so wird er dich verwerfen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'So siehe nun zu, denn der HERR hat dich erwahlet, daß du ein Haus bauestzum Heiligtum; sei getrost und mache es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Und David gab seinem Sohn Salomo ein Vorbild der Halle und seines Hauses und der Gemacher und Sale und Kammern inwendig und des Hauses des Gnadenstuhls;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'dazu Vorbilder alles, was bei ihm in seinem Gemüte war, namlich des Hofes am Hause des HERRN und aller Gemacher umher, des Schatzes im Hause Gottes und des Schatzes der Geheiligten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'die Ordnung der Priester und Leviten und aller Geschafte des Amts im Hause des HERRN;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Gold nach dem Goldgewicht zu allerlei Gefalien eines jeglichen Amts und allerlei silbern Gezeug nach dem Gewicht zu allerlei Gefalien eines jeglichen Amts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'und Gold zu guldenen Leuchtern und guldenen Lampen, einem jeglichen Leuchter und seiner Lampe sein Gewicht; also auch zu silbernen Leuchtern gab er das Silber zum Leuchter und seiner Lampe nach dem Amt eines jeglichen Leuchters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Auch gab erzu Tischen der Schaubrote Gold, zu jeglichem Tisch sein Gewicht, also auch Silber zu silbernen Tischen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'und lauter Gold zu Kreueln, Becken und Kandeln und zu guldenen Bechern, einem jeglichen Bechersein Gewicht, und zu silbernen Bechern, einem jeglichen Becher sein Gewicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'und zum Rauchaltar das allerlauterste Gold, sein Gewicht; auch ein Vorbild des Wagens der guldenen Cherubim, daß sie sich ausbreiteten und bedeckten oben die Lade des Bundes des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Alles ist mir beschrieben gegeben von der Hand des HERRN, daß mich\'s unterweisete alle Werke des Vorbildes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Und David sprach zu seinem Sohn Salomo: Sei getrost und unverzagt und mache es; furchte dich nicht und zage nicht! Gott der HERR, mein Gott, wird mit dir sein und wird die Hand nicht abziehen noch dich verlassen, bis du alle Werke zum Amt im Hause des HERRN vollendest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Siehe da, die Ordnung der Priester und Leviten zu alien Amtern im Hause Gottes sind mit dir zu allem Geschafte und sind willig und weise zu alien Amtern, dazu die Fursten und alles Volk zu alien deinen Handeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Und der Konig David sprach zu der ganzen Gemeine: Gott hat Salomo, meiner Sohne einen, erwahlet, der noch jung und zart ist; das Werk aber ist grofi, denn es ist nicht eines Menschen Wohnung, sondern Gottes des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Ich aber habe aus alien meinen Kraften geschickt zum Hause Gottes, Gold zu güldenem, Silber zu silbernem, Erz zu ehernem, Eisen zu eisernem, Holz zu hdlzernem Gerate, Onyxsteine, eingefalite Rubine und bunte Steine und allerlei Edelgesteine und Marmelsteine die Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Uber das, aus Wohlgefallen am Hause meines Gottes, habe ich eigenes Guts, Gold und Silber,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'dreitausend Zentner Goldes von Ophir und siebentausend Zentner lauteren Silbers; das gebe ich zum heiligen Hause Gottes uber alles, das ich geschickt habe, die Wande der Hauser zu uberziehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'daß gulden werde, was gulden, und silbern, was silbern sein soil, und zu allerlei Werk durch die Hand der Werkmeister. Und wer ist nun freiwillig, seine Hand heute dem HERRN zu fulien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Da waren die Fursten der Vater, die Fursten der Stamme Israels, die Fursten über tausend und über hundert und die Fürsten über des Konigs Geschafte freiwillig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'und gaben zum Amt im Hause Gottes fünftausend Zentner Goldes und zehntausend Gulden und zehntausend Zentner Silbers, achtzehntausend Zentner Erzes und hunderttausend Zentner Eisens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Und bei welchem Steine funden wurden, die gaben sie zum Schatz des Hauses des HERRN unter die Hand Jehiels, des Gersoniten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Und das Volk ward frohlich, daß sie freiwillig waren; denn sie gaben\'s von ganzem Herzen dem HERRN freiwillig. Und David, der Konig, freuete sich auch hoch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'und lobete Gott und sprach vorderganzen Gemeine: Gelobet seiest du, HERR, Gott Israels, unsers Vaters, ewiglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Dir gebuhrt die Majestat und Gewalt, Herrlichkeit, Sieg und Dank. Denn alles, was im Himmel und auf Erden ist, das ist dein. Dein ist das Reich, und du bist erhohet liber alles zum Obersten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Dein ist Reichtum und Ehre vordir; du herrschest liber alles; in deiner Hand stehet Kraft und Macht; in deiner Hand stehet es, jedermann graft und stark zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Nun, unserßott, wirdanken dir und rühmen den Namen deiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Denn was bin ich? Was ist mein Volk, daß wir sollten vermogen Kraft, freiwillig zu geben, wie dies gehet? Denn von dir ist\'s alles kommen, und von deiner Hand haben wir dir\'s gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Denn wirsind Fremdlinge und Gaste vordir, wie unsere Vater alle. Unser Leben auf Erden ist wie ein Schatten, und ist kein Aufhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'HERR, unser Gott, all dieser Haufe, den wir geschickt haben, dir ein Haus zu bauen, deinem heiligen Namen, ist von deiner Hand kommen, und ist alles dein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Ich weift, mein Gott, daß du das Herz prlifest, und Aufrichtigkeit ist dir angenehm. Darum habe ich dies alles aus aufrichtigem Herzen freiwillig gegeben und habe jetzt mit Freuden gesehen dein Volk, das hie vorhanden ist, daß es dir freiwillig gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'HERR, Gott unserer Vater, Abrahams, Isaaks und Israels, bewahre ewiglich solchen Sinn und Gedanken im Herzen deines Volks und schicke ihre Herzen zu dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Und meinem Sohn Salomo gib ein rechtschaffen Herz, daß er halte deine Gebote, Zeugnisse und Rechte, daß er\'s alles tue und baue diese Wohnung, die ich geschickt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Und David sprach zur ganzen Gemeine: Lobet den HERRN, euren Gott! Und die ganze Gemeine lobte den HERRN, den Gott ihrer Vater, und neigeten sich und beteten an den HERRN und den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Und opferten dem HERRN Opfer. Und des andern Morgens opferten sie Brandopfer, tausend Farren, tausend Widder, tausend Lammer, mit ihren Trankopfern; und opferten die Menge unter dem ganzen Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Und aften und tranken desselben Tages vor dem HERRN mit groften Freuden. Und machten das andere Mai Salomo, den Sohn Davids, zum Konige und salbten ihn dem HERRN zum Fursten und Zadok zum Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Also saft Salomo auf dem Stuhl des HERRN, ein Konig an seines Vaters Davids Statt, und ward glückselig; und ganz Israel war ihm gehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Und alle Obersten und Gewaltigen, auch alle Kinder des Konigs David, taten sich unter den Konig Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Und der HERR machte Salomo immergrofter vor dem ganzen Israel und gab ihm ein loblich Konigreich, das keiner vor ihm uber Israel gehabt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'So ist nun David, der Sohn Isais, Konig gewesen uber ganz Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Die Zeit aber, die er Konig uber Israel gewesen ist, ist vierzig Jahre. Zu Hebron regierete er sieben Jahre und zu Jerusalem dreiunddreiftig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Und starb in gutem Alter, voll Lebens, Reichtums und Ehre. Und sein Sohn Salomo ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Die Geschichten aber des Konigs David, beide die ersten und letzten, siehe, die sind geschrieben unter den Geschichten Samuels, des Sehers, und unter den Geschichten des Propheten Nathan und unter den Geschichten Gads, des Schauers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'mit all seinem Konigreich, Gewalt und Zeiten, die unter ihm ergangen sind, beide uber Israel und alle Konigreiche in Landen. Das zweite Buch der Chronik');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Und Salomo, der Sohn Davids, ward in seinem Reich bekraftiget; und der HERR, sein Gott, war mit ihm und machte ihn immer grolier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Und Salomo redete mit dem ganzen Israel, mit den Obersten uber tausend und hundert, mit den Richtern und mit alien Fursten in Israel, mit den obersten Vatern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'daß sie hingingen, Salomo und die ganze Gemeine mit ihm, zu der Hohe, die zu Gibeon war; denn daselbst war die Hütte des Stifts Gottes, die Mose, der Knecht des HERRN, gemacht hatte in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Denn die Lade Gottes hatte David heraufgebracht von Kiriath-Jearim, dahin er ihr bereitet hatte; denn er hatte ihr eine Hütte aufgeschlagen zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Aber der eherne Altar, den Bezaleel, der Sohn Uris, des Sohns Hurs, gemacht hatte, war daselbst vor der Wohnung des HERRN; und Salomo und die Gemeine pflegten ihn zu suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Und Salomo opferte auf dem ehernen Altar vor dem HERRN, der vor der Hütte des Stifts stund, tausend Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'In derselben Nacht aber erschien Gott Salomo und sprach zu ihm: Bitte, was soil ich dirgeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Und Salomo sprach zu Gott: Du hast grofte Barmherzigkeit an meinem Vater David getan und hast mich an seiner Statt zum Konige gemacht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'so laft nun, HERR Gott, deine Worte wahrwerden an meinem Vater David; denn du hast mich zum Konige gemacht fiber ein Volk, des so viel ist als Staub auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'So gib mir nun Weisheit und Erkenntnis, daß ich vor diesem Volk aus und ein gehe; denn wer kann dies dein groftes Volk richten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Da sprach Gott zu Salomo: Weil du das im Sinne hast und hast nicht urn Reichtum, noch urn Gut, noch urn Ehre, noch urn deiner Feinde Seelen, noch urn langes Leben gebeten, sondern hast urn Weisheit und Erkenntnis gebeten, daß du mein Volk richten mogest, darüber ich dich zum Konige gemacht habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'so sei dir Weisheit und Erkenntnis gegeben; dazu will ich dir Reichtum und Gut und Ehre geben, daß deinesgleichen unter den Konigen vor dir, nicht gewesen ist noch werden soil nach dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Also kam Salomo von der Hohe, die zu Gibeon war, gen Jerusalem von der Hütte des Stifts; und regierete uber Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Und Salomo sammelte ihm Wagen und Reiter, daß er zuwegebrachte tausend und vierhundert Wagen und zwolftausend Reiter; und lieft sie in den Wagenstadten und bei dem Konige zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Und der Konig machte des Silbers und des Goldes zu Jerusalem so viel wie die Steine und der Zedern wie die Maulbeerbaume in den Gründen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Und man brachte Salomo Rosse aus Agypten und allerlei Ware. Und die Kaufleute des Konigs kauften dieselbige Ware');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'und brachten\'s aus Agypten heraus, je einen Wagen urn sechshundert Silberlinge, ein Roft urn hundertundfunfzig. Also brachten sie auch alien Konigen der Hethiter und den Konigen zu Syrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 18, 'Und Salomo gedachte zu bauen ein Haus dem Namen des HERRN und ein Haus seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Und zahlte ab siebenzigtausend Mann zur Last und achtzigtausend Zimmerleute auf dem Berge und dreitausend und sechshundert Amtleute uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Und Salomo sandte zu Huram, dem Konige zu Tyrus, und lieft ihm sagen: Wie du mit meinem Vater David tatest und ihm sandtest Zedern, daß er ihm ein Haus bauete, darinnen er wohnete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'siehe, ich will dem Namen des HERRN, meines Gottes, ein Haus bauen, das ihm geheiliget werde, gut Rauchwerk vor ihm zu rauchern, und Schaubrote allewege zuzurichten und Brandopfer des Morgens und des Abends auf die Sabbate und Neumonden und auf die Feste des HERRN, unsers Gottes, ewiglich fur Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Und das Haus, das ich bauen will, soil graft sein; denn unser Gott ist grafter denn alle Gotten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Aber wer vermag\'s, daß er ihm ein Haus baue? Denn der Himmel und aller Himmel Himmel mogen ihn nicht versorgen; wer sollte ich denn sein, daß ich ihm ein Haus bauete? Sondern daß man vor ihm rauchere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'So sende mir nun einen weisen Mann, zu arbeiten mit Gold, Silber, Erz, Eisen, Scharlaken, Rosinrot, gelber Seide und der da wisse auszugraben mit den Weisen, die bei mir sind in Juda und Jerusalem, welche mein Vater David geschickt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Und sende mir Zedern, Tannen und Ebenholz vom Libanon; denn ich weift, daß deine Knechte das Holz zu hauen wissen auf dem Libanon. Und siehe, meine Knechte sollen mitdeinen Knechten sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'daß man mir viel Holz zubereite; denn das Haus, das ich bauen will, soil graft und sonderlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Und siehe, ich will den Zimmerleuten, deinen Knechten, die das Holz hauen, zwanzigtausend Kor gestoftenen Weizen und zwanzigtausend Kor Gerste und zwanzigtausend Bath Weins und zwanzigtausend Bath Ols geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Da sprach Huram, der Konig zu Tyrus, durch Schrift, und sandte zu Salomo: Darum daß der HERR sein Volk liebet, hat er dich fiber sie zum Konige gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Und Huram sprach weiter: Gelobet sei der HERR, der Gott Israels, der Himmel und Erde gemacht hat, da(3> er dem Konige David hat einen weisen, klugen und verstandigen Sohn gegeben, der dem HERRN ein Haus baue und ein Haus seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'So sende ich nun einen weisen Mann, der Verstand hat, Huram-Abif,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'der ein Sohn ist eines Weibes aus den Tochtern Dan, und sein Vater ein Tyrer gewesen ist, der weili zu arbeiten an Gold, Silber, Erz, Eisen, Stein, Holz, Scharlaken, gelber Seide, Leinen, Rosinrot und zu graben allerlei und allerlei kunstlich zu machen, was man ihm vorgibt, mit deinen Weisen und mit den Weisen meines Herrn Konigs David, deines Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'So sende nun mein Herr Weizen, Gerste, 01 und Wein seinen Knechten, wie er geredet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'so wollen wirdas Holz hauen auf dem Libanon, wieviel es not ist, und wollen es auf Flofien bringen im Meer gen Japho; von dannen magst du es hinauf gen Jerusalem bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Und Salomo zahlete alle Fremdlinge im Lande Israel nach der Zahl, da sie David, sein Vater, zahlete; und wurden funden hundertundfunfzigtausend, dreitausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Und ermachte aus denselben siebenzigtausend Trager und achtzigtausend Hauer auf dem Berge und dreitausendsechshundert Aufseher, die das Volk zum Dienst anhielten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Und Salomo fing an zu bauen das Haus des HERRN zu Jerusalem, auf dem Berge Morija, der David, seinem Vater, gezeiget war, welchen David zubereitet hatte zum Raum auf dem Platz Arnans, des Jebusiters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Er fing aber an zu bauen im andern Monden des andern Tages im vierten Jahr seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Und also legte Salomo den Grund, zu bauen das Haus Gottes; am ersten die Lange sechzig Ellen, die Weite zwanzig Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Und die Halle vor der Weite des Hauses her war zwanzig Ellen lang, die Hohe aber war hundertundzwanzig Ellen; und uberzog es inwendig mit lauterm Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Das grolie Haus aber spundete er mit Tannenholz und uberzog es mit dem besten Golde; und machte drauf Palmen und Kettenwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Und uberzog das Haus mit edlen Steinen zum Schmuck; das Gold aber war Parwaim-Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Und uberzog die Balken obenan und die Wande und die Turen mit Golde; und lieti Cherubim schnitzen an die Wande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Er machte auch das Haus des Allerheiligsten, des Lange war zwanzig Ellen nach der Weite des Hauses, und seine Weite war auch zwanzig Ellen; und uberzog es mit dem besten Golde, bei sechshundert Zentner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Und gab auch zu Nageln funfzig Sekel Goldes am Gewicht; und uberzog die Sale mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Er machte auch im Hause des Allerheiligsten zween Cherubim nach der Bildner Kunst und uberzog sie mit Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Und die Lange am Flügel an den Cherubim war zwanzig Ellen, dati ein Flugel funf Ellen hatte und ruhrete an die Wand des Hauses, und derandere Flugel auch funf Ellen hatte und ruhrete an den Flugel des andern Cherub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Also hatte auch des andern Cherub ein Flugel funf Ellen und ruhrete an die Wand des Hauses, und sein anderer Flugel auch funf Ellen und hing am Flugel des andern Cherub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'daß diese Flugel der Cherubim waren ausgebreitet zwanzig Ellen weit; und sie stunden auf ihren Futien, und ihr Antlitz war gewandt zum Hause warts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Er machte auch einen Vorhang von Gelbwerk, Scharlaken, Rosinrot und Leinwerk; und machte Cherubim drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Und ermachte vor dem Hause zwo Saulen, funfunddreifüg Ellen lang; und der Knauf oben drauf funf Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Und machte Kettenwerk zum Chor und tat sie oben an die Saulen; und machte hundert Granatapfel und tat sie an das Kettenwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Und richtete die Saulen auf vor dem Tempel, eine zur Rechten und die andere zur Linken; und hieli die zur Rechten Jachin und die zur Linken Boas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Er machte auch einen ehernen Altar, zwanzig Ellen lang und breit und zehn Ellen hoch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Und er machte ein gegossen Meer, zehn Ellen weit von einem Rande an den andern rund umher und funf Ellen hoch; und ein Mali von dreitüg Ellen mochte es umher begreifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Und Ochsenbilder waren unter ihm umher; und es waren zwo Riegen Knoten urn das Meer her (das zehn Ellen weit war), die mit angegossen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Es stund aber also auf den zwolf Ochsen, daß drei gewandt waren gegen Mitternacht, drei gegen Abend, drei gegen Mittag und drei gegen Morgen und das Meer oben auf ihnen; und all ihr Hinterstes war inwendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Seine Dicke war eine Hand breit, und sein Rand war wie eines Bechers Rand und eine aufgegangene Rose; und es fatite dreitausend Bath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Und er machte zehn Kessel; der setzte er funf zur Rechten und funf zur Linken, drinnen zu waschen, was zum Brandopfer gehoret, daß sie es hineinstietien; das Meer aber, daß sich die Priester drinnen wuschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Er machte auch zehn güldene Leuchter, wie sie sein sollten, und setzte sie in den Tempel, funf zur Rechten und funf zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Und machte zehn Tische und tat sie in den Tempel, funf zur Rechten und funf zur Linken. Und machte hundert guldene Becken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Er machte auch einen Hof fur die Priester und grofie Schranken und Turen in die Schranken; und uberzog die Turen mit Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Und setzte das Meer auf der rechten Ecke gegen Morgen zu Mittag warts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Und Huram machte Topfe, Schaufeln und Becken. Also vollendete Huram die Arbeit, die er dem Konige Salomo tat am Hause Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'namlich die zwo Saulen mit den Bauchen und Knaufen oben auf beiden Saulen und beide gewundene Reife, zu bedecken beide Bauche der Knaufe oben auf den Saulen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'und die vierhundert Granatapfel an den beiden gewundenen Reifen; zwo Riegen Granatapfel an jeglichem Reif, zu bedecken beide Bauche der Knaufe, so oben auf den Saulen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Auch machte er die Gestuhle und die Kessel auf den Gestuhlen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'und ein Meer und zwolf Ochsen drunter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'dazu Topfe, Schaufeln, Kreuel und alle ihre Gefafte machte Huram-Abif dem Konige Salomo zum Hause des HERRN aus lauterm Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'In der Gegend des Jordans lieft sie der Konig gieften in dicker Erde, zwischen Suchoth und Zaredatha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Und Salomo machte aller dieser Gefafte sehr viel, daß des Erzes Gewicht nicht zu forschen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Und Salomo machte alles Gerat zum Hause Gottes: namlich den güldenen Altar, Tisch und Schaubrotdrauf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'die Leuchter mit ihren Lampen von lauterm Golde, daß sie brenneten vor dem Chor, wie sich\'s gebührt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'und die Blumen an den Lampen und die Schneuzen waren gulden, das war alles vdllig Gold;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'dazu die Messer, Becken, Loffel und Napfe waren lauter Gold. Und der Eingang und seine Tur inwendig zu dem Allerheiligsten und die Tur am Hause des Tempels waren gulden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Also ward alle Arbeit vollbracht, die Salomo tat am Hause des HERRN. Und Salomo brachte hinein alles, was sein Vater David geheiliget hatte, namlich Silber und Gold und allerlei Gerat, und legte es in den Schatz im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Da versammelte Salomo alle Altesten in Israel, alle Hauptleute der Stamme, Fursten der Vater unter den Kindern Israel gen Jerusalem, daß sie die Lade des Bundes des HERRN hinaufbrachten aus derßtadt Davids, das ist, Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Und es versammelten sich zum Konige alle Manner Israels aufs Fest, das ist, im siebenten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Und kamen alle Altesten Israels. Und die Leviten huben die Lade auf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'und brachten sie hinauf samt der Hutte des Stiffs und allem heiligen Gerate, das in der Hutte war; und brachten sie mit hinauf die Priester, die Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Aber der Konig Salomo und die ganze Gemeine Israel, zu ihm versammelt vor der Lade, opferten Schafe und Ochsen, soviel, daß niemand zahlen noch rechnen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Also brachten die Priester die Lade des Bundes des HERRN an ihre Statte, den Chor des Hauses, in das Allerheiligste unter die Flugel der Cherubim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'daß die Cherubim ihre Flugel ausbreiteten uber die Statte der Lade; und die Cherubim bedeckten die Lade und ihre Stangen von oben her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Die Stangen aber waren so lang, daß man ihre Knaufe sah von der Lade vor dem Chor; aber auften sah man sie nicht. Und sie war daselbst bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Und war nichts in der Lade, ohne die zwo Tafeln, die Mose in Horeb drein getan hatte, da der HERR einen Bund machte mit den Kindern Israel, da sie aus Agypten zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Und da die Priester herausgingen aus dem Heiligen (denn alle Priester, die vorhanden waren, heiligten sich, daß auch die Ordnungen nicht gehalten wurden),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'und die Leviten mit alien, die unter Assaph, Heman, Jedithun und ihren Kindern und Brüdem waren, angezogen mit Leinwand, sangen mit Zimbeln, Psaltern und Harfen und stunden gegen Morgen des Altars, und bei ihnen hundertundzwanzig Priester, die mit Trommeten bliesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Und es war, als ware es einer, der trommetete und sange, als horete man eine Stimme, zu loben und zu danken dem HERRN. Und da die Stimme sich erhub von den Trommeten, Zimbeln und andern Saitenspielen und von dem Loben des HERRN, daß er gutig ist und seine Barmherzigkeit ewig wahret, da ward das Haus des HERRN erfullet mit einer Wolke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'daß die Priester nicht stehen konnten, zu dienen, vor der Wolke; denn die Herrlichkeit des HERRN erfullete das Haus Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Da sprach Salomo: Der HERR hat geredet, zu wohnen im Dunkel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Ich habe zwar ein Haus gebauet dir zur Wohnung und einen Sitz, da du ewiglich wohnest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Und der Konig wandte sein Antlitz und segnete die ganze Gemeine Israel; denn die ganze Gemeine Israel stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Und er sprach: Gelobet sei der HERR, der Gott Israels, derdurch seinen Mund meinem Vater David geredet und mit seiner Hand erfullet hat, da er sagte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Seit der Zeit ich mein Volk aus Agyptenland gefuhret habe, habe ich keine Stadt erwahlet in alien Stammen Israels, ein Haus zu bauen, daß mein Name daselbst ware, und habe auch keinen Mann erwahlet, daß er Furst ware uber mein Volk Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'aber Jerusalem habe ich erwahlet, daß mein Name daselbst sei, und David habe ich erwahlet, daß er uber mein Volk Israel sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Und da es mein Vater David im Sinn hatte, ein Haus zu bauen dem Namen des HERRN, des Gottes Israels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'sprach der HERR zu meinem Vater David: Du hastwohl getan, daß du im Sinn hast, meinem Namen ein Haus zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Doch du sollst das Haus nicht bauen, sondern dein Sohn, der aus deinen Lenden kommen wird, soil meinem Namen das Haus bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'So hat nun der HERR sein Wort bestatiget, das er geredet hat; denn ich bin aufkommen an meines Vaters David Statt und sitze auf dem Stuhl Israels, wie der HERR geredet hat, und habe ein Haus gebauet dem Namen des HERRN, des Gottes Israels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'und habe drein getan die Lade, darinnen der Bund des HERRN ist, den er mit den Kindern Israel gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Und er trat vorden Altar des HERRN vor der ganzen Gemeine Israel und breitete seine Hande aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Denn Salomo hatte eine eherne Kanzel gemacht und gesetzt mitten in die Schranken, funf Ellen lang und breit und drei Ellen hoch; auf dieselbe trat er und del nieder auf seine Kniee vor der ganzen Gemeine Israel; und breitete seine Hande aus gen Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'und sprach: HERR, Gott Israels, es ist kein Gott dir gleich, weder im Himmel noch auf Erden; der du haltst den Bund und Barmherzigkeit deinen Knechten, die vor dir wandeln aus ganzem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Du hast gehalten deinem Knechte David, meinem Vater, was du ihm geredet hast; mit deinem Munde hast du es geredet und mit deiner Hand hast du es erfullet, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nun, HERR, Gott Israels, halte deinem Knechte David, meinem Vater, was du ihm geredet hast und gesagt: Es soil dir nicht gebrechen an einem Manne vor mir, der auf dem Stuhl Israels sitze, doch sofern deine Kinder ihren Weg bewahren, daß sie wandeln in meinem Gesetz, wie du vor mir gewandelt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nun, HERR, Gott Israels, lali dein Wortwahr werden, das du deinem Knechte David geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Denn meinest du auch, daß Gott bei den Menschen auf Erden wohne? Siehe, der Himmel und alter Himmel Himmel kann dich nicht versorgen; wie sollte es denn das Haus tun, das ich gebauet habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Wende dich aber, HERR, mein Gott, zu dem Gebet deines Knechts und zu seinem Flehen, daß du erhorest das Bitten und Beten, das dein Knecht vor dir tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'daß deine Augen often seien uber dies Haus Tag und Nacht, uber die Statte, dahin du deinen Namen zu stellen geredet hast, daß du horest das Gebet, das dein Knecht an dieser Statte tun wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'So hore nun das Flehen deines Knechts und deines Volks Israel, das sie bitten werden an dieser Statte; hore es aber von der Statte deiner Wohnung vom Himmel, und wenn du es horest, wollest du gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Wenn jemand wider seinen Nachsten sundigen wird, und wird ihm ein Eid aufgeleget, den er schworen soli, und der Eid kommt vor deinen Altar in diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'so wollest du horen vom Himmel und deinem Knechte Recht verschaffen, daß du dem Gottlosen vergeltest und gebest seinen Weg auf seinem Kopf und rechtfertigest den Gerechten und gebest ihm nach seiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Wenn dein Volk Israel vor seinen Feinden geschlagen wird, weil sie an dir gesundiget haben, und bekehren sich und bekennen deinen Namen, bitten und flehen vor dir in diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'so wollest du horen vom Himmel und gnadig sein der Sunde deines Volks Israel und sie wieder in das Land bringen; das du ihnen und ihren Vatern gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Wenn der Himmel zugeschlossen wird, daß nicht regnet, weil sie an dir gesundiget haben, und bitten an dieser Statte und bekennen deinen Namen und bekehren sich von ihren Sunden, weil du sie gedemutiget hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'so wollest du horen im Himmel und gnadig sein der Sunde deiner Knechte und deines Volks Israel, daß du sie den guten Weg lehrest, darinnen sie wandeln sollen, und regnen lassest auf dein Land, das du deinem Volk gegeben hast zu besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Wenn eine Teurung im Lande wird Oder Pestilenz Oder Durre, Brand, Heuschrecken, Raupen; Oder wenn sein Feind im Lande seine Tore belagert, Oder irgend eine Plage Oder Krankheit:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'wer dann bittet Oder flehet unter allerlei Menschen und unter all deinem Volk Israel, so jemand seine Plage und Schmerzen fuhlet und seine Hande ausbreitet zu diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'so wollest du horen vom Himmel, vom Sitz deiner Wohnung, und gnadig sein und jedermann geben nach all seinem Wege, nach dem du sein Herz erkennest (denn du allein erkennest das Herz der Menschenkinder),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'auf daß sie dich furchten und wandeln in deinen Wegen alle Tage, solange sie leben auf dem Lande, das du unsern Vatern gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Wenn auch ein Fremder, der nicht von deinem Volk Israel ist, kommt aus fernen Landen urn deines grofien Namens und machtiger Hand und ausgereckten Arms willen und betet zu diesem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'so wollest du horen vom Himmel, vom Sitz deiner Wohnung, und tun alles, warum er dich anrufet, auf daß alle Volker auf Erden deinen Namen erkennen und dich furchten, wie dein Volk Israel, und inne werden, daß dies Haus, das ich gebauet habe, nach deinem Namen genannt sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Wenn dein Volk auszeucht in Streit wider seine Feinde des Weges, den du sie senden wirst, und zu dir bitten gegen dem Wege zu dieser Stadt, die du erwahlet hast, und zum Hause, das ich deinem Namen gebauet habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'so wollest du ihr Gebet und Flehen horen vom Himmel und ihnen zu ihrem Recht helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Wenn sie an dir sundigen werden (sintemal kein Mensch ist, der nicht sundige), und du uber sie erzürnest und gibst sie vor ihren Feinden, daß sie sie gefangen wegfuhren in ein femes Oder nahes Land,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'und sie sich in ihrem Herzen bekehren im Lande, da sie gefangen innen sind, und bekehren sich und flehen dir im Lande ihres Gefangnisses und sprechen: Wirhaben gesundiget, missetan und sind gottlos gewesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'und sich also von ganzem Herzen und von ganzer Seele zu dir bekehren im Lande ihres Gefangnisses, da man sie gefangen halt, und sie beten gegen dem Wege zu ihrem Lande, das du ihren Vatern gegeben hast, und zur Stadt, die du erwahlet hast, und zum Hause, das ich deinem Namen gebauet habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'so wollest du ihr Gebet und Flehen horen vom Himmel, vom Sitz deiner Wohnung, und ihnen zu ihrem Recht helfen und deinem Volk gnadig sein, das an dir gesundiget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'So laft nun, mein Gott, deine Augen often sein und deine Ohren aufmerken auf das Gebet an dieser Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'So mache dich nun auf, HERR Gott, zu deiner Ruhe, du und die Lade deiner Macht! Laft deine Priester, HERR Gott, mit Heil angetan werden, und deine Heiligen sich freuen uber dem Guten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Du, HERR Gott, wende nicht weg das Antlitz deines Gesalbten; gedenke an die Gnade, deinem Knechte David verheiften!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Und da Salomo ausgebetet hatte, fiel ein Feuer vom Himmel und verzehrete das Brandopfer und andere Opfer. Und die Herrlichkeit des HERRN erfullete das Haus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'daß die Priester nicht konnten hineingehen ins Haus des HERRN, weil die Herrlichkeit des HERRN fullete des HERRN Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Auch sahen alle Kinder Israel das Feuer herabfallen und die Herrlichkeit des HERRN uber dem Hause; und fielen auf ihre Kniee mit dem Antlitz zur Erde aufs Pflaster und beteten an und dankten dem HERRN, daß er gutig ist und seine Barmherzigkeit ewiglich wahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Der Konig aber und alles Volk opferten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Denn der Konig Salomo opferte zweiundzwanzigtausend Ochsen und hundertundzwanzigtausend Schafe; und weiheten also das Haus Gottes ein, beide der Konig und alles Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Aber die Priester stunden in ihrer Hut und die Leviten mit den Saitenspielen des HERRN, die der Konig David hatte lassen machen, dem HERRN zu danken, daß seine Barmherzigkeit ewiglich wahret, mit den Psalmen Davids durch ihre Hand; und die Priester bliesen Trommeten gegen ihnen, und das ganze Israel stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Und Salomo heiligte den Mittelhof, der vor dem Hause des HERRN war; denn er hatte daselbst Brandopfer und das Fett der Dankopfer ausgerichtet. Denn der eherne Altar, den Salomo hatte machen lassen, konnte nicht alle Brandopfer, Speisopfer und das Fettfassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Und Salomo hielt zu derselben Zeit ein Fest sieben Tage lang, und das ganze Israel mit ihm, eine sehr große Gemeine, von Hemath an bis an den Bach Agyptens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Und hielt am achten Tage eine Versammlung; denn die Einweihung des Altars hielten sie sieben Tage und das Fest auch sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Aber am dreiundzwanzigsten Tage des siebenten Monden lieli erdas Volk in ihre Hutten frohlich und gutes Muts uber allem Guten, das der HERR an David, Salomo und seinem Volk Israel getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Also vollendete Salomo das Haus des HERRN und das Haus des Konigs und alles, was in sein Herz kommen war, zu machen im Hause des HERRN und in seinem Hause, gluckseliglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Und der HERR erschien Salomo des Nachts und sprach zu ihm: Ich habe dein Gebet erhoret und diese Statte mir erwahlet zum Opferhause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Siehe, wenn ich den Himmel zuschliefte, daß nicht regnet, Oder heifie die Heuschrecken das Land fressen, Oder lasse eine Pestilenz unter mein Volk kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'daß sie mein Volk demutigen, das nach meinem Namen genannt ist, und sie beten und mein Angesicht suchen und sich von ihren bosen Wegen bekehren werden, so will ich vom Himmel horen und ihre Sunde vergeben und ihr Land heilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'So sollen nun meine Augen often sein und meine Ohren aufmerken auf das Gebet an dieser Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'So habe ich nun dies Haus erwahlet und geheiliget, daß mein Name daselbst sein soli ewiglich, und meine Augen und mein Herz soli da sein allewege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Und so du wirst vor mir wandeln, wie dein Vater David gewandelt hat, daß du tust alles, was ich dich heifte, und haltst meine Gebote und Rechte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'so will ich den Stuhl deines Konigreichs bestatigen, wie ich mich deinem Vater David verbunden habe und gesagt: Es soil dir nicht gebrechen an einem Manne, der uber Israel Herr sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Werdet ihreuch aber umkehren und meine Rechte und Gebote, die ich euch vorgelegt habe, verlassen und hingehen und andern Gottern dienen und sie anbeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'so werde ich sie auswurzeln aus meinem Lande, das ich ihnen gegeben habe; und dies Haus, das ich meinem Namen geheiliget habe, werde ich von meinem Angesicht werfen und werde es zum Sprichwort geben und zur Fabel unter alien Volkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Und vor diesem Hause, das das hochste worden ist, werden sich entsetzen alle, die vorubergehen, und sagen: Warum hatder HERR diesem Lande und diesem Hause also mitgefahren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'So wird man sagen: Darum daß sie den HERRN, ihrer Vater Gott, verlassen haben, der sie aus Agyptenland gefuhret hat, und haben sich an andere Gotter gehanget und sie angebetet und ihnen gedienet; darum hat er all dies Ungluck uber sie gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Und nach zwanzig Jahren, in welchen Salomo des HERRN Haus und sein Haus bauete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'bauete erauch die Stadte, die Huram Salomo gab, und ließ die Kinder Israel drinnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Und Salomo zog gen Hemath-Zoba und befestigte sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'und bauete Thadmor in der Wüste und alle Kornstadte, die er bauete in Hemath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Er bauete auch Ober- und Nieder-Beth-Horon, das feste Stadte waren mit Mauern, Türen und Riegeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'auch Baelath und alle Kornstadte, die Salomo hatte, und alle Wagenstadte und Reiter, und alles, wozu Salomo Lust hatte zu bauen, beide zu Jerusalem und auf dem Libanon und im ganzen Lande seiner Herrschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Alles ubrige Volk von den Hethitern, Amoritern, Pheresitern, Hevitern und Jebusitern, die nicht von den Kindern Israel waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'und ihre Kinder, die sie hinter sich gelassen hatten im Lande, die die Kinder Israel nicht vertilget hatten, machte Salomo zinsbar bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Aber von den Kindern Israel machte Salomo nicht Knechte zu seiner Arbeit, sondern sie waren Kriegsleute und uber seine Fursten und fiber seine Wagen und Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Und der obersten Amtleute des Konigs Salomo waren zweihundertundfunfzig, die über das Volk herrscheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Und die Tochter Pharaos ließ Salomo heraufholen aus der Stadt Davids ins Haus, das er fur sie gebauet hatte. Denn er sprach: Mein Weib soil mir nicht wohnen im Hause Davids, des Konigs Israels; denn es ist geheiliget, weil die Lade des HERRN drein kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Von dem an opferte Salomo dem HERRN Brandopfer auf dem Altar des HERRN, den er gebauet hatte vor der Halle,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'ein jegliches auf seinen Tag zu opfern, nach dem Gebot Moses, auf die Sabbate, Neumonden und bestimmten Zeiten des Jahrs dreimal, namlich aufs Fest der ungesauerten Brote, aufs Fest der Wochen und aufs Fest der Laubhutten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Und erstellete die Priester in ihrer Ordnung zu ihrem Amt, wie es David, sein Vater, gesetzt hatte; und die Leviten auf ihre Hut, zu loben und zu dienen vor den Priestern, jegliche auf ihren Tag; und die Torhuter in ihrer Ordnung, jegliche auf ihr Tor. Denn also hatte es David, der Mann Gottes, befohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Und es ward nicht gewichen vom Gebot des Konigs uber die Priester und Leviten an allerlei Sachen und an den Schatzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Also ward bereitet alles Geschaft Salomos von dem Tage an, da des HERRN Haus gegrundetward, bis er\'s vollendete, daß des HERRN Haus ganz bereitet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Da zog Salomo gen Ezeon-Geber und gen Eloth an dem Ufer des Meers im Lande Edomaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Und Huram sandte ihm Schiffe durch seine Knechte, die des Meers kundig waren; und fuhren mit den Knechten Salomos nach Ophir und holten von dannen vierhundertundfünfzig Zentner Goldes und brachten es dem Konige Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Und da die Konigin von Reicharabien das Gerucht Salomos horete, kam sie mit sehr großem Zeuge gen Jerusalem, mit Kamelen, die Wurze und Goldes die Menge trugen und Edelsteine, Salomo mit Ratseln zu versuchen. Und da sie zu Salomo kam, redete sie mit ihm alles, was sie im Sinne hatte vorgenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Und der Konig sagte ihr alles, was sie fragte, und war Salomo nichts verborgen, das er ihr nicht gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Und da die Konigin von Reicharabien sah die Weisheit Salomos und das Haus, das er gebauet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'die Speise fur seinen Tisch, die Wohnung fur seine Knechte, die Amter seiner Diener und ihre Kleider, seine Schenken mit ihren Kleidern und seinen Saal, da man hinaufging ins Haus des HERRN, konnte sie sich nicht mehr enthalten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'und sie sprach zum Konige: Es ist wahr, was ich gehoret habe in meinem Lande von deinem Wesen und von deiner Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Ich wollte aber ihren Worten nicht glauben, bis ich kommen bin und habe es mit meinen Augen gesehen. Und siehe, es ist mir nicht die Halfte gesagt deiner großen Weisheit. Es ist mehr an dir denn das Gerucht, das ich gehoret habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Selig sind deine Manner und selig diese deine Knechte, die allewege vor dir stehen und deine Weisheit horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Der HERR, dein Gott, sei gelobet, der dich liebhat, daß er dich auf seinen Stuhl zum Konige gesetzt hat dem HERRN, deinem Gott! Es macht, daß dein Gott hat Israel lieb, daß er ihn ewiglich aufrichte, darum hat er dich über sie zum Konige gesetzt, daß du Recht und Redlichkeit handhabest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Und sie gab dem Konige hundertundzwanzig Zentner Goldes und sehr viel Würze und Edelgesteine. Es waren keine Würze als diese, die die Konigin von Reicharabien dem Konige Salomo gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Dazu die Knechte Hurams und die Knechte Salomos, die Gold aus Ophir brachten, die brachten auch Ebenholz und Edelgesteine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Und Salomo lieft aus dem Ebenholz Treppen im Hause des HERRN und im Hause des Konigs machen und Harfen und Psalter fur die Sanger. Es waren vorhin nie gesehen solche Hdlzer im Lande Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Und der Konig Salomo gab der Konigin von Reicharabien alles, was sie begehrete und bat, ohne was sie zum Konige gebracht hatte. Und sie wandte sich und zog in ihr Land mit ihren Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Des Goldes aber, das Salomo in einem Jahr gebracht ward, war sechshundertundsechsundsechzig Zentner,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'ohne was die Kramer und Kaufleute brachten. Und alle Konige der Araber und die Herren in Landen brachten Gold und Silberzu Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Daher machte der Konig Salomo zweihundert Schilde vom besten Golde, daß sechshundert Stuck Goldes auf einen Schild kam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'und dreihundert Tartschen vom besten Golde, daß dreihundert Stuck Goldes zu einer Tartsche kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Und der Konig tat sie ins Haus vom Walde Libanon. Und der Konig machte einen groften elfenbeinernen Stuhl und uberzog ihn mit lauterm Golde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Und der Stuhl hatte sechs Stufen und einen guldenen Fuftschemel am Stuhl und hatte zwo Lehnen auf beiden Seiten urn das Gesali; und zween Lowen stunden neben den Lehnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'und zwolf Lowen stunden daselbst auf den sechs Stufen zu beiden Seiten. Ein solches ist nicht gemacht in alien Konigreichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Und alle Trinkgefafte des Konigs Salomo waren gulden; und alle Gefafte des Hauses vom Walde Libanon waren lauter Gold. Denn das Silber ward nichts gerechnet zur Zeit Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Denn die Schiffe des Konigs fuhren auf dem Meer mit den Knechten Hurams und kamen in drei Jahren einmal und brachten Gold, Süber, Elfenbein, Affen und Pfauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Also ward der Konig Salomo grofier denn alle Konige auf Erden mit Reichtum und Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Und alle Konige auf Erden begehrten das Angesicht Salomos, seine Weisheit zu horen, die ihm Gott in sein Herz gegeben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Und sie brachten ihm ein jeglicher sein Geschenk, silberne und guldene Gefafte, Kleider, Harnische, Wurze, Rosse und Mauler jahrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Und Salomo hatte viertausend Wagenpferde und zwolftausend Reisige; und man tat sie in die Wagenstadte und bei dem Konige zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Und er war ein Herr über alle Konige vom Wasser an bis an der Philister Land und bis an die Grenze Agyptens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Und der Konig machte des Silbers so viel zu Jerusalem wie der Steine und der Zedern, so viel wie der Maulbeerbaume in den Gründen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Und man brachte ihm Rosse aus Agypten und aus alien Landern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Was aber mehr von Salomo zu sagen ist, beide sein Erstes und sein Letztes, siehe, das ist geschrieben in der Chronik des Propheten Nathan und in den Prophezeiungen Ahias von Silo und in den Gesichten Jeddis, des Schauers, wider Jerobeam, den Sohn Nebats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Und Salomo regierete zu Jerusalem fiber ganz Israel vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Und Salomo entschlief mit seinen Vatern, und man begrub ihn in der Stadt Davids, seines Vaters. Und Rehabeam, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam zog gen Sichem; denn ganz Israel war gen Sichem kommen, ihn zum Konige zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Und da das Jerobeam horete, der Sohn Nebats, der in Agypten war, dahin er vor dem Konige Salomo geflohen war, kam er wieder aus Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Und sie sandten hin und lielien ihn rufen. Und Jerobeam kam mit dem ganzen Israel und redete mit Rehabeam und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Dein Vater hat unser Joch zu hart gemacht. So leichtere nun du den harten Dienst deines Vaters und das schwere Joch, das er auf uns gelegt hat, so wollen wir dir untertanig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Er sprach zu ihnen: Uber drei Tage kommt wieder zu mir. Und das Volk ging hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Und der Konig Rehabeam ratfragte die Altesten, die vor seinem Vater Salomo gestanden waren, da er beim Leben war, und sprach: Wie ratet ihr, daß ich diesem Volk Antwort gebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Sie redeten mit ihm und sprachen: Wirst du diesem Volk freundlich sein und wirst sie handeln gütiglich und ihnen gute Worte geben, so werden sie dir untertanig sein allewege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Er aber verlieft den Rat der Altesten, den sie ihm gegeben hatten, und ratschlagte mit den Jungen, die mit ihm aufgewachsen waren und vor ihm stunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'und sprach zu ihnen: Was ratet ihr, daß wir diesem Volk antworten, die mit mir geredet haben und sagen: Leichtere das Joch, das dein Vater auf uns gelegt hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Die Jungen aber, die mit ihm aufgewachsen waren, redeten mit ihm und sprachen: So sollst du sagen zu dem Volk, das mit dir geredet hat und spricht: Dein Vater hat unser Joch zu schwer gemacht, mache du unser Joch leichter; und sprich zu ihnen: Mein kleinster Finger soil dicker sein denn meines Vaters Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Hat nun mein Vater auf euch zu schweres Joch geladen, so will ich eures Jochs mehr machen. Mein Vater hat euch mit Peitschen gezuchtiget, ich aber mit Skorpionen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Als nun Jerobeam und alles Volk zu Rehabeam kam am dritten Tage, wie denn der Konig gesagt hatte: Kommt wieder zu mir am dritten Tage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'antwortete ihnen der Konig hart. Und der Konig Rehabeam verließ, den Rat der Altesten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'und redete mit ihnen nach dem Rat der Jungen und sprach: Hat mein Vater euer Joch zu schwer gemacht, so will ich\'s mehr dazu machen. Mein Vater hat euch mit Peitschen gezuchtiget, ich aber mit Skorpionen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Also gehorchte der Konig dem Volk nicht. Denn es war also von Gott gewandt, auf daß der HERR sein Wort bestatigte, daß er geredet hatte durch Ahia von Silo zu Jerobeam, dem Sohn Nebats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Da aber das ganze Israel sah, daß ihnen der Konig nicht gehorchte, antwortete das Volk dem Konige und sprach: Was haben wir Teils an David Oder Erbe am Sohn Isais? Jedermann von Israel zu seiner Hütte! So siehe nun du zu deinem Hause, David! Und das ganze Israel ging in seine Hütten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'daß Rehabeam nur fiber die Kinder Israel regierete, die in den Stadten Judas wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Aber der Konig Rehabeam sandte Hadoram, den Rentmeister; aber die Kinder Israel steinigten ihn zu Tode. Und der Konig Rehabeam stieg frisch auf seinen Wagen, daß er flohe gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Also fiel Israel ab vom Hause Davids bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Und da Rehabeam gen Jerusalem kam, versammelte er das Haus Juda und Benjamin, hundertundachtzigtausend junger Mannschaft, die streitbar waren, wider Israel zu streiten, daß sie das Konigreich wieder an Rehabeam brachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Aber des HERRN Wort kam zu Semaja, dem Mann Gottes, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Sage Rehabeam, dem Sohn Salomos, dem Konige Judas, und dem ganzen Israel, das unter Juda und Benjamin ist, und sprich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'So spricht der HERR: Ihr sollt nicht hinaufziehen, noch wider eure Bruder streiten; ein jeglicher gehe wieder heim, denn das ist von mir geschehen. Sie gehorchten den Worten des HERRN und lieften ab von dem Zug wider Jerobeam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Rehabeam aber wohnete zu Jerusalem und baute die Stadte fest in Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'namlich: Bethlehem, Etam, Thekoa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Beth-Zur, Socho, Adullam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gath, Maresa, Siph,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lachis, Aseka,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zarea, Ajalon und Hebron, welche waren die festesten Stadte in Juda und Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Und machte sie feste und setzte Fursten drein und Vorrat von Speise, Ol und Wein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Und in alien Stadten schaffte er Schilde und Spiefte und machte sie sehr feste. Und Juda und Benjamin waren unter ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Auch machten sichzu ihm die Priester und Leviten aus dem ganzen Israel und alien ihren Grenzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Und sie verlieften ihre Vorstadte und Habe und kamen zu Juda gen Jerusalem. Denn Jerobeam und seine Sohne verstieften sie, daß sie dem HERRN nicht Priesteramts pflegen muftten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Er stiftete ihm aber Priester zu den Hohen und zu den Feldteufeln und Kalbern, die er machen lieft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Und nach ihnen kamen aus alien Stammen Israels, die ihr Herz gaben, daß sie nach dem HERRN, dem Gott Israels, fragten, gen Jerusalem, daß sie opferten dem HERRN, dem Gott ihrer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Und starkten also das Konigreich Juda und bestatigten Rehabeam, den Sohn Salomos, drei Jahre lang. Denn sie wandelten in dem Wege Davids und Salomos drei Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Und Rehabeam nahm Mahelath, die Tochter Jerimoths, des Sohns Davids, zum Weibe und Abihail, die Tochter Eliabs, des Sohns Isais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Die gebar ihm diese Sohne: Jeus, Semarja und Saham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Nach der nahm er Maecha, die Tochter Absaloms; die gebar ihm Abia, Athai, Sisa und Selomith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Aber Rehabeam hatte Maecha, die Tochter Absaloms, lieber denn alle seine Weiber und Kebsweiber; denn er hatte achtzehn Weiber und sechzig Kebsweiber; und zeugete achtundzwanzig Sohne und sechzig Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Und Rehabeam setzte Abia, den Sohn Maechas, zum Haupt und Fursten unter seinen Brudern; denn er gedachte ihn zum Konige zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Und er nahm zu und brach aus vor alien seinen Sohnen in Landen Juda und Benjamin in alien festen Stadten; und er gab ihnen Futterung die Menge und nahm viel Weiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Da aber das Konigreich Rehabeams bestatiget und bekraftiget ward, verlieft er das Gesetz des HERRN, und ganz Israel mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Aber im funften Jahr des Konigs Rehabeam zog herauf Sisak, der Konig in Agypten, wider Jerusalem (denn sie hatten sich versundiget am HERRN)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'mittausend und zweihundert Wagen und mit sechzigtausend Reitern, und das Volk war nicht zu zahlen, das mit ihm kam aus Agypten, Libyen, Suchim und Mohren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Und er gewann die festen Stadte, die in Juda waren, und kam bis gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Da kam Semaja, der Prophet, zu Rehabeam und zu den Obersten Judas, die sich gen Jerusalem versammelt hatten vor Sisak, und sprach zu ihnen: So spricht der HERR: Ihr habt mich verlassen, darum habe ich euch auch verlassen in Sisaks Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Da demutigten sich die Obersten in Israel mit dem Konige und sprachen: Der HERR ist gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Als aber der HERR sah, daß sie sich demutigten, kam das Wort des HERRN zu Semaja und sprach: Sie haben sich gedemütiget, darum will ich sie nicht verderben, sondern ich will ihnen ein wenig Errettung geben, daß mein Grimm nicht triefe auf Jerusalem durch Sisak.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Doch sollen sie ihm untertan sein, daß sie inne werden, was es sei, mir dienen und den Konigreichen in Landen dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Also zog Sisak, der Konig von Agypten, herauf gen Jerusalem und nahm die Schatze im Hause des HERRN und die Schatze im Hause des Konigs und nahm es alles weg; und nahm auch die guldenen Schilde, die Salomo machen lieli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'An welcher Statt liefi der Konig Rehabeam eherne Schilde machen und befahl sie den Obersten der Trabanten, die an der Tur des Konigshauses huteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Und so oft der Konig in des HERRN Haus ging, kamen die Trabanten und trugen sie und brachten sie wieder in der Trabanten Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Und weil er sich demutigte, wandte sich des HERRN Zorn von ihm, daß nicht alles verderbet ward. Denn es war in Juda noch was Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Also ward Rehabeam, der Konig, bekraftiget in Jerusalem und regierete. Einundvierzig Jahre alt war Rehabeam, da er Konig ward, und regierete siebenzehn Jahre zu Jerusalem, in der Stadt, die der HERR erwahlet hatte aus alien Stammen Israels, daß er seinen Namen dahin stellete. Seine Mutter hieli Naema, eine Ammonitin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Und er handelte libel und schickte sein Herz nicht, daß erden HERRN suchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Die Geschichten aber Rehabeams, beide die ersten und die letzten, sind geschrieben in den Geschichten Semajas, des Propheten, und Iddos, des Schauers, und aufgezeichnet, dazu die Kriege Rehabeams und Jerobeams ihr Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Und Rehabeam entschlief mit seinen Vatern und ward begraben in der Stadt Davids. Und sein Sohn Abia ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Im achtzehnten Jahr des Konigs Jerobeam ward Abia Konig in Juda');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'und regierete drei Jahre zu Jerusalem. Seine Mutter hiefi Michaja, eine Tochter Uriels von Gibea. Und es erhub sich ein Streit zwischen Abia und Jerobeam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Und Abia rustete sich zu dem Streit mit vierhunderttausend junger Mannschaft, starke Leute zum Kriege. Jerobeam aber rustete sich, mit ihm zu streiten mit achthunderttausend junger Mannschaft, starke Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Und Abia machte sich auf oben auf den Berg Zemaraim, welcher liegtauf dem Gebirge Ephraim, und sprach: Horet mir zu, Jerobeam, und das ganze Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Wisset ihr nicht, daß der HERR, der Gott Israels, hat das Konigreich zu Israel David gegeben ewiglich, ihm und seinen Sohnen einen Salzbund?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Aber Jerobeam, der Sohn Nebats, der Knecht Salomos, Davids Sohns, warf sich auf und ward seinem Herrn abtrunnig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Und haben sich zu ihm geschlagen lose Leute und Kinder Belials und haben sich gestarket wider Rehabeam, den Sohn Salomos. Denn Rehabeam war jung und eines bidden Herzens, daß ersich vor ihnen nicht wehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Nun denket ihr euch zu setzen wider das Reich des HERRN unter den Sohnen Davids, weil euer ein grolier Haufe ist, und habt güldene Kalber, die euch Jerobeam fur Gotter gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Habt ihr nicht die Priesterdes HERRN, die Kinder Aarons und die Leviten, ausgestolien und habt euch eigene Priester gemacht, wie die Volker in Landen? Wer da kommt, seine Hand zu füllen mit einem jungen Farren und sieben Widdern, derwird Priester derer, die nicht Gotter sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mituns aber ist der HERR, unser Gott, den wir nicht verlassen; und die Priester, die dem HERRN dienen, die Kinder Aarons und die Leviten in ihrem Geschaft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'und anzunden dem HERRN alle Morgen Brandopfer und alle Abend, dazu das gute Rauchwerk und bereitete Brote auf dem reinen Tisch; und der güldene Leuchter mit seinen Lampen, daß sie alle Abend angezündet werden. Denn wir behalten die Hut des HERRN, unsers Gottes; ihr aber habt ihn verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Siehe, mit uns ist an der Spitze Gott und seine Priester und die Trommeten, zu trommeten, daß man wider euch trommete. Ihr Kinder Israel, streitet nicht wider den HERRN, eurer Vater Gott; denn es wird euch nicht gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Aber Jerobeam machte einen Hinterhalt umher, daß er von hinten an sie kame, daß sie vor Juda waren und der Hinterhalt hinter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Da sich nun Juda umwandte, siehe, da war vorne und hinten Streit. Da schrieen sie zum HERRN, und die Priester trommeteten mit Trommeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Und jedermann in Juda tonete. Und da jedermann in Juda tonete, plagte Gott Jerobeam und das ganze Israel vor Abia und Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Und die Kinder Israel flohen vor Juda, und Gott gab sie in ihre Hande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'da(S Abia mit seinem Volk eine grofte Schlacht an ihnen tat, und fielen aus Israel Erschlagene fünfhunderttausend junger Mannschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Also wurden die Kinder Israel gedemütiget zu der Zeit; aber die Kinder Judas wurden getrost, denn sie verlieften sich auf den HERRN, ihrer Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Und Abia jagte Jerobeam nach und gewann ihm Stadte an: Bethel mit ihren Tochtern, Jesana mit ihren Tochtern und Ephron mit ihren Tochtern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'da(S Jerobeam furder nicht zu Kraften kam, weil Abia lebte. Und der HERR plagte ihn, daß er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Da nun Abia gestarket war, nahm er vierzehn Weiber und zeugete zweiundzwanzig Sohne und sechzehn Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Was aber mehr von Abia zu sagen ist, und seine Wege und sein Tun, das ist geschrieben in der Historia des Propheten Iddo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 23, 'Und Abia entschlief mit seinen Vatern, und sie begruben ihn in der Stadt Davids; und Assa, sein Sohn, ward Konig an seiner Statt. Zu des Zeiten war das Land stille zehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Und Assa tat, das recht war und dem HERRN, seinem Gott, wohlgefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Und tatweg diefremden Altare und die Hohen und zerbrach die Saulen und hieb die Haine ab;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'und ließ Juda sagen, daß sie den HERRN, den Gott ihrer Vater, suchten und taten nach dem Gesetz und Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Und er tatweg aus alien Stadten Judas die Hohen und die Gotzen. Denn das Konigreich war stilie vorihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Und er bauete feste Stadte in Juda, weil das Land stille und kein Streit wider ihn war in denselben Jahren; denn der HERR gab ihm Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Und ersprach zu Juda: Lasset unsdiese Stadte bauen und Mauern darum her führen und Türme, Turen und Riegel, weil das Land noch vor uns ist; denn wir haben den HERRN, unsern Gott, gesucht, und er hat uns Ruhe gegeben umher. Also baueten sie, und ging glucklich vonstatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Und Assa hatte eine Heerkraft, die Schild und Spiefi trugen: aus Juda dreihunderttausend und aus Benjamin, die Schilde trugen und mit den Bogen konnten, zweihundertundachtzigtausend; und diese waren alle starken Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Eszog aber wider sie aus Serah, der Mohr, mit einer Heereskraft, tausendmal tausend, dazu dreihundert Wagen, und kamen bis gen Maresa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Und Assa zog aus gegen ihn; und sie rusteten sich zum Streit im Tal Zephatha bei Maresa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Und Assa rief an den HERRN, seinen Gott, und sprach: HERR, es ist bei dir kein Unterschied, helfen unter vielen, Oder da keine Kraft ist. Hilf uns, HERR, unser Gott; denn wir veriassen uns auf dich, und in deinem Namen sind wir kommen wider diese Menge. HERR, unser Gott, wider dich vermag kein Mensch etwas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Und der HERR plagte die Mohren vor Assa und vor Juda, daß sie flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Und Assa samt dem Volk, das bei ihm war, jagte ihnen nach bis gen Gerar. Und die Mohren fielen, daß ihrer keiner lebendig blieb, sondern sie wurden geschlagen vor dem HERRN und vor seinem Heerlager. Und sie trugen sehr viel Raubs davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Und erschlug alle Stadte urn Gerar her; denn die Furcht des HERRN kam uber sie. Und sie beraubten alle Stadte; denn es war viel Raubs drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Auch schlugen sie die Hütten des Viehes und brachten Schafe die Menge und Kamele; und kamen wiedergen Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Und auf Asarja, den Sohn Odeds, kam der Geist Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Der ging hinaus Assa entgegen und sprach zu ihm: Horet mirzu, Assa und ganz Juda und Benjamin! Der HERR ist mit euch, weil ihr mit ihm seid; und wenn ihr ihn suchet, wird er sich von euch finden lassen; werdet ihr aber ihn veriassen, so wird er euch auch veriassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Eswerden aber viel Tage sein in Israel, dafi kein rechter Gott, kein Priester, der da lehret, und kein Gesetz sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Und wenn sie sich bekehren in ihrer Not zu dem HERRN, dem Gott Israels, und werden ihn suchen, so wird ersich finden lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Zu der Zeit wird\'s nicht wohlgehen dem, der aus- und eingehet. Denn es werden grofte Getummel sein uber alle, die auf Erden wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Denn ein Volk wird das andere zerschmeiften und eine Stadt die andere; denn Gott wird sie erschrecken mit allerlei Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Ihr aber seid getrost und tut eure Hande nicht ab, denn euer Werk hat seinen Lohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Da aber Assa horete diese Worte und die Weissagung Odeds, des Propheten, ward er getrost und tat weg die Greuel aus dem ganzen Lande Juda und Benjamin und aus den Stadten, die er gewonnen hatte auf dem Gebirge Ephraim, und erneuerte den Altar des HERRN, der vor der Halle des HERRN stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Und versammelte das ganze Juda und Benjamin und die Fremdlinge bei ihnen aus Ephraim, Manasse und Simeon. Denn es fielen zu ihm aus Israel die Menge, als sie sahen, daß der HERR, sein Gott, mit ihm war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Und sie versammelten sich gen Jerusalem des dritten Monden, im funfzehnten Jahr des Konigreichs Assa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'und opferten desselben Tages dem HERRN von dem Raube, den sie gebracht hatten, siebenhundert Ochsen und siebentausend Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Und sie traten in den Bund, daß sie suchten den HERRN, ihrer Vater Gott, von ganzem Herzen und von ganzer Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Und wer nicht wurde den HERRN, den Gott Israels, suchen, sollte sterben, beide klein und groß, beide Mann und Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Und sie schwuren dem HERRN mit lauter Stimme, mit Tonen, mit Trommeten und Posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Und das ganze Juda war frohlich über dem Eide; denn sie hatten geschworen von ganzem Herzen und sie suchten ihn von ganzem Willen, und er ließ sich von ihnen finden; und der HERR gab ihnen Ruhe umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Auch setzte Assa, der Konig, ab Maecha, seine Mutter, vom Amt, das sie gestiftet hatte im Hain Miplezeth. Und Assa rottete ihren Miplezeth aus und zerstieß ihn und verbrannte ihn im Bach Kidron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Aber die Hohen in Israel wurden nicht abgetan; doch war das Herz Assas rechtschaffen sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Und er brachte ein, was sein Vater geheiliget und was er geheiliget hatte, ins Haus Gottes, Silber, Gold und Gefaße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Und es war kein Streit bis in das fünfunddreißigste Jahr des Konigreichs Assas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Im sechsunddreißigsten Jahr des Konigreichs Assas zog herauf Baesa, der Konig Israels, wider Juda und bauete Rama, daß er Assa, dem Konige Judas, wehrete aus- und einzuziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Aber Assa nahm aus dem Schatz im Hause des HERRN und im Hause des Konigs Silber und Gold und sandte zu Benhadad, dem Konige zu Syrien, der zu Damaskus wohnete, und ließ ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Es ist ein Bund zwischen mir und dir, zwischen meinem und deinem Vater; darum habe ich dir Silber und Gold gesandt, daß du den Bund mit Baesa, dem Konige Israels, fahren lassest, daß er von mir abziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad gehorchte dem Konige Assa und sandte seine Heerfursten wider die Stadte Israels; die schlugen Ejon, Dan und Abel-Maim und alle Kornstadte Naphthalis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Da Baesa das horete, ließ erab, Rama zu bauen, und horete auf von seinem Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Aber der Konig Assa nahm zu sich das ganze Juda, und sie trugen die Steine und das Holz von Rama, damit Baesa bauete; und er bauete damit Geba und Mizpa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Zu der Zeit kam Hanani, der Seher, zu Assa, dem Konige Judas, und sprach zu ihm: Daß du dich auf den Konig zu Syrien verlassen hast und hast dich nicht auf den HERRN, deinen Gott, verlassen, darum ist die Macht des Konigs zu Syrien deiner Hand entronnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Waren nicht die Mohren und Libyer eine große Menge, mit sehr viel Wagen und Reitern? Doch gab sie der HERR in deine Hand, da du dich auf ihn verließest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Denn des HERRN Augen schauen alle Lande, daß er starke die, so von ganzem Herzen an ihm sind. Du hast toricht getan; darum wirst du auch von nun an Krieg haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Aber Assa ward zornig über den Seher und legte ihn ins Gefangnis; denn er murrete mit ihm über diesem Stück. Und Assa unterdrückte etliche des Volks zu der Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Die Geschichten aber Assas, beide die ersten und die letzten, siehe, die sind geschrieben im Buch von den Konigen Judas und Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Und Assa ward krank an seinen Füßen im neununddreißigsten Jahr seines Konigreichs, und seine Krankheit nahm sehrzu; und suchte auch in seiner Krankheit den HERRN nicht, sondern die Arzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Also entschlief Assa mit seinen Vatern und starb im einundvierzigsten Jahr seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Und man begrub ihn in seinem Grabe, das er ihm hatte lassen graben in der Stadt Davids. Und sie legten ihn auf sein Lager, welches man gefullet hatte mit gutem Rauchwerk und allerlei Spezerei, nach Apothekerkunst gemacht, und machten ein sehr groß Brennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Und sein Sohn Josaphatward Konig an seiner Statt und ward machtig wider Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Und er legte Kriegsvolk in alle festen Stadte Judas und setzte Amtleute im Lande Juda und in den Stadten Ephraims, die sein Vater Assa aewonnen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Und der HERR war mit Josaphat; denn er wandelte in den vorigen Wegen seines Vaters David und suchte nicht Baalim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'sondern den Gott seines Vaters, und wandelte in seinen Geboten und nicht nach den Werken Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Darum bestatigte ihm der HERR das Konigreich, und ganz Juda gab Josaphat Geschenke; und er hatte Reichtum und Ehre die Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Und da sein Herz mutig ward in den Wegen des HERRN, tat er furder ab die Hohen und Haine aus Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Im dritten Jahr seines Konigreichs sandte er seine Fursten Ben-Hail, Obadja, Sacharja, Nethaneel und Michaja, daß sie lehren sollten in den Stadten Judas;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'und mit ihnen die Leviten Semaja, Nethanja, Sebadja, Asael, Semiramoth, Jonathan, Adonia, Tobia und Tob-Adonia; und mit ihnen die Priester Elisama und Joram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Und sie lehreten in Juda und hatten das Gesetzbuch des HERRN mit sich; und zogen umher in alien Stadten Judas und lehreten das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Und es kam die Furchtdes HERRN uber alle Konigreiche in den Landen, die um Juda her lagen, daß sie nicht stritten wider Josaphat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Und die Philister brachten Josaphat Geschenke, eine Last Silbers. Und die Araber brachten ihm siebentausend und siebenhundert Widder und siebentausend und siebenhundert Bocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Also nahm Josaphat zu und ward immer grolier; und er bauete in Juda Schlosser und Kornstadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Und hatte viel Vorrats in den Stadten Judas und streitbare Manner und gewaltige Leute zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Und dies war die Ordnung unter ihrer Vater Haus, die in Juda uber die tausend Obersten waren: Adna, ein Oberster, und mit ihm waren dreihunderttausend gewaltige Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Neben ihm war Johanan, der Oberste; und mit ihm waren zweihundertundachtzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Neben ihm war Amasja, derßohn Sichris, der Freiwillige des HERRN; und mit ihm waren zweihunderttausend gewaltige Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Von den Kindern Benjamin war Eljada, ein gewaltiger Mann; und mit ihm waren zweihunderttausend, die mit Bogen und Schilden gerustet waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Neben ihm war Josabad; und mit ihm waren hundertundachtzigtausend, gerustet zum Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Diese warteten alle auf den Konig, ohne was der Konig noch gelegt hatte in die festen Stadte im ganzen Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Und Josaphat hatte grolien Reichtum und Ehre und befreundete sich mit Ahab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Und nach zweien Jahren zog er hinab zu Ahab gen Samaria. Und Ahab lieli fur ihn und fur das Volk, das bei ihm war, viel Schafe und Ochsen schlachten. Und er beredete ihn, daß er hinauf gen Ramoth in Gilead zoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Und Ahab, der Konig Israels, sprach zu Josaphat, dem Konige Judas: Zeuch mit mirgen Ramoth in Gilead! Er sprach zu ihm: Ich bin wie du, und mein Volk wie dein Volk, wir wollen mit dir in den Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Aber Josaphat sprach zum Konige Israels: Lieber, frage heute des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Und der Konig Israels sammelte der Propheten vierhundert Mann und sprach zu ihnen: Sollen wir gen Ramoth in Gilead ziehen in Streit, Oder soil ich\'s lassen anstehen? Sie sprachen: Zeuch hinauf, Gott wird sie in des Konigs Hand geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Josaphat aber sprach: 1st nicht irgend noch ein Prophet des HERRN hie, daß wir von ihm fragten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Der Konig Israels sprach zu Josaphat: Es ist noch ein Mann, daß man den HERRN von ihm frage; aber ich bin ihm gram, denn er weissaget uber mich kein Gutes, sondern allewege Boses, namlich Micha, der Sohn Jemlas. Josaphat sprach: Der Konig rede nicht also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Und der Konig Israels rief seiner Kammerer einen und sprach: Bringe eilend her Micha, den Sohn Jemlas!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Und der Konig Israels und Josaphat, der Konig Judas, salien ein jeglicher auf seinem Stuhl, mit Kleidern angezogen; sie salien aber auf dem Platz vor der Tur, am Tor zu Samaria; und alle Propheten weissagten vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Und Zidekia, der Sohn Knaenas, machte ihm eiserne Horner und sprach: So spricht der HERR: Hiemit wirst du die Syrer stolen, bis du sie aufreibest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Und alle Propheten weissagten auch also und sprachen: Zeuch hinauf, eswird dirgelingen; der HERR wird sie geben in des Konigs Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Und der Bote, der hingegangen war, Micha zu rufen, redete mit ihm und sprach: Siehe, der Propheten Reden sind eintrachtig gut fur den Konig; Lieber, lali dein Wort auch sein wie der einen, und rede Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micha aber sprach: So wahr der HERR lebet, was mein Gott sagen wird, das will ich reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Und da erzum Konige kam, sprach der Konig zu ihm: Micha, sollen wir gen Ramoth in Gilead in Streit ziehen, Oder soli ich\'s lassen anstehen? Er sprach: Ja, ziehet hinauf, es wird euch gelingen; es wird euch in eure Hande gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Aber der Konig sprach zu ihm: Ich beschwore dich noch einmal, dati du mir nichts sagest denn die Wahrheit im Namen des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Da sprach er: Ich sah das ganze Israel zerstreuet auf den Bergen wie Schafe, die keinen Hirten haben. Und der HERR sprach: Haben diese keine Herren? Es kehre ein jeglicher wieder heim mit Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Da sprach der Konig Israels zu Josaphat: Sagte ich dir nicht, er weissaget uber mich kein Gutes, sondern Boses?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Er aber sprach: Darum horetdes HERRN Wort: Ich sah den HERRN sitzen auf seinem Stuhl, und alles himmlische Heer stund zu seiner Rechten und zu seiner Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Und der HERR sprach: Wer will Ahab, den Konig Israels, uberreden, daß er hinaufziehe und falle zu Ramoth in Gilead? Und da dieser so und jener sonst sagte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'kam ein Geist hervor und trat vor den HERRN und sprach: Ich will ihn uberreden. Der HERR aber sprach zu ihm: Womit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Er sprach: Ich will ausfahren und ein falscher Geist sein in aller seiner Propheten Munde. Und er sprach: Du wirst ihn uberreden und wirst\'s ausrichten; fahre hin und tue also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nun siehe, der HERR hat einen falschen Geist gegeben in dieser deiner Propheten Mund, und der HERR hat Boses wider dich geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Da trat herzu Zidekia, der Sohn Knaenas, und schlug Micha auf den Backen und sprach: Durch welchen Weg ist der Geist des HERRN von mir gegangen, dad er durch dich redet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micha sprach: Siehe, du wirst\'s sehen, wenn du in die innerste Kammer kommest, dad du dich versteckest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Aber der Konig Israels sprach: Nehmet Micha und lasset ihn bleiben bei Amon, dem Stadtvogt, und bei Joas, dem Sohn des Konigs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'und saget: So spricht der Konig: Leget diesen ins Gefangnis und speiset ihn mit Brot und Wasser der Trubsal, bis ich wiederkomme mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Micha sprach: Kommst du mit Frieden wieder, so hat der HERR nicht durch mich geredet. Und er sprach: Horet, ihr Volker alle!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Also zog hinauf der Konig Israels und Josaphat, der Konig Judas, gen Ramoth in Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Und der Konig Israels sprach zu Josaphat: Ich will mich verkleiden und in Streit kommen; du aber habe deine Kleider an. Und der Konig Israels verkleidete sich, und sie kamen in den Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Aber der Konig zu Syrien hatte seinen obersten Reitern geboten: Ihr sollt nicht streiten weder gegen klein noch gegen grofi, sondern gegen den Konig Israels alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Da nun die obersten Reiter Josaphat sahen, dachten sie, es ist der Konig Israels, und zogen umher, auf ihn zu streiten. Aber Josaphat schrie; und der HERR half ihm, und Gott wandte sie von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Denn da die obersten Reiter sahen, daß er nicht der Konig Israels war, wandten sie sich von ihm ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Es spannete aber ein Mann seinen Bogen ohngefahr und schoft den Konig Israels zwischen den Panzer und Hengel. Da sprach er zu seinem Fuhrmann: Wende deine Hand und führe mich aus dem Heer; denn ich bin wund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Und der Streit nahm zu des Tages. Und der Konig Israels stund auf seinem Wagen gegen die Syrer bis an den Abend und starb, da die Sonne unterging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Josaphat aber, der Konig Judas, kam wieder heim mit Frieden gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Und es ging ihm entgegen hinaus Jehu, der Sohn Hananis, der Schauer, und sprach zum Konige Josaphat: Sollst du so dem Gottlosen helfen und lieben, die den HERRN hassen? Und urn deswillen ist uber dir der Zorn vom HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Aberdoch ist was Gutes an dirfunden, daßdu die Haine hast ausgefeget aus dem Lande und hast dein Herz gerichtet, Gott zu suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Also blieb Josaphat zu Jerusalem. Under zog wiederum aus unter das Volk, von Berseba an bis auf das Gebirge Ephraim, und brachte sie wieder zu dem HERRN, ihrer Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Und er bestellete Richter im Lande in alien festen Stadten Judas, in einer jeglichen Stadt etliche,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'und sprach zu den Richtern: Sehet zu, was ihr tut; denn ihr haltet das Gericht nicht den Menschen, sondern dem HERRN; und er ist mit euch im Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Darum lalit die Furchtdes HERRN bei euch sein und hütet euch und tutes; denn bei dem HERRN, unserm Gott, ist kein Unrecht, noch Ansehen der Person, noch Annehmen des Geschenks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Auch bestellete Josaphat zu Jerusalem aus den Leviten und Priestern und aus den obersten Vatern unter Israel fiber das Gericht des HERRN und uber die Sachen und ließ sie zu Jerusalem wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Und gebot ihnen und sprach: Tut also in der Furcht des HERRN, treulich und mit rechtem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'In alien Sachen, die zu euch kommen von euren Brudern, die in ihren Stadten wohnen, zwischen Blut und Blut, zwischen Gesetz und Gebot, zwischen Sitten und Rechten, sollt ihr sie unterrichten, dafi sie sich nicht verschuldigen am HERRN, und ein Zorn uber euch und eure Bruder komme. Tut ihm also, so werdet ihr euch nicht verschuldigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Siehe, Amarja, der Priester, ist der Oberste uber euch in alien Sachen des HERRN. So ist Sabadja, der Sohn Ismaels, Fürst im Hause Juda, in alien Sachen des Konigs. So habt ihr Amtleute, die Leviten, vor euch. Seid getrost und tut es; und der HERR wird mit dem Guten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Nach diesem kamen die Kinder Moab, die Kinder Ammon und mit ihnen von den Amunim, wider Josaphat zu streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Und man kam und sagte es Josaphat an und sprach: Es kommt wider dich eine groüe Menge von jenseit des Meers, von Syrien; und siehe, sie sind zu Hazezon-Thamar, das ist, Engeddi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Josaphat aber furchtete sich und stellete sein Angesicht, zu suchen den HERRN, und lied ein Fasten ausrufen unter ganz Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Und Juda kam zusammen, den HERRN zu suchen; auch kamen aus alien Stadten Judas, den HERRN zu suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Und Josaphat trat unter die Gemeine Judas und Jerusalems im Hause des HERRN vor dem neuen Hofe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'und sprach: HERR, unserer Vater Gott, bist du nicht Gott im Himmel und Herrscher in alien Konigreichen der Heiden? Und in deiner Hand ist Kraft und Macht; und ist niemand, der wider dich stehen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Hast du, unser Gott, nicht die Einwohner dieses Landes vertrieben vor deinem Volk Israel und hast es gegeben dem Samen Abrahams, deines Liebhabers, ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'daß sie drinnen gewohnet und dir ein Heiligtum zu deinem Namen drinnen gebauet haben, und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Wenn ein Ungluck, Schwert, Strafe, Pestilenz Oder Teurung uber uns kommt, sollen wir stehen vor diesem Hause vor dir (denn dein Name ist in diesem Hause) und schreien zu dir in unserer Not, so wolltest du horen und helfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Nun siehe, die Kinder Ammon, Moab und die vom Gebirge Seir, uberwelche du die Kinder Israel nicht ziehen lieliest, da sie aus Agyptenland zogen, sondern muliten von ihnen weichen und sie nicht vertilgen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'und siehe, sie lassen uns des entgelten und kommen, uns auszustolien aus deinem Erbe, das du uns hasteingegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Unser Gott, willstdu sie nicht richten? Denn in uns ist nicht Kraft gegen diesen grolien Haufen, der wider uns kommt. Wir wissen nicht, was wir tun sollen, sondern unsere Augen sehen nach dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Und das ganze Juda stund vordem HERRN mit ihren Kindern, Weibern und Sohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Aberauf Jehasiel, den Sohn Sacharjas, des Sohns Benajas, des Sohns Jehiels, des Sohns Mathanjas, den Leviten, aus den Kindern Assaph, kam der Geist des HERRN mitten in der Gemeine;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'und sprach: Merket auf, ganz Juda, und ihr Einwohner zu Jerusalem, und der Konig Josaphat! So spricht der HERR zu euch: Ihr sollt euch nicht furchten noch zagen vor diesem grolien Haufen; denn ihr streitet nicht, sondern Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Morgen sollt ihr zu ihnen hinabziehen; und siehe, sie ziehen an Ziz herauf, und ihrwerdet an sie treffen am Schilf im Bach vor der Wüste Jeruel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Denn ihr werdet nicht streiten in dieser Sache. Tretet nur hin und stehet und sehet das Heil des HERRN, der mit euch ist, Juda und Jerusalem! Furchtet euch nicht und zaget nicht; morgen ziehet aus wider sie, der HERR ist mit euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Da beugte sich Josaphat mit seinem Antlitz zur Erde; und ganz Juda und die Einwohner zu Jerusalem fielen vordem HERRN und beteten den HERRN an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Und die Leviten aus den Kindern der Kahathiter und aus den Kindern der Korhiter machten sich auf, zu loben den HERRN, den Gott Israels, mitgroliem Geschrei gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Und sie machten sich des Morgens frühe auf und zogen aus zur Wüste Thekoa. Und da sie auszogen, stund Josaphat und sprach: Horet mir zu, Juda, und ihr Einwohner zu Jerusalem! Glaubet an den HERRN, euren Gott, so werdet ihr sicher sein; und glaubet seinen Propheten, so werdet ihr Gluck haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Und er unterweisete das Volk und stellete die Sanger dem HERRN, daß sie lobeten in heiligem Schmuck und vor den Gerusteten herzogen und sprachen: Danket dem HERRN, denn seine Barmherzigkeit wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Und da sie anfingen mit Danken und Loben, ließ der HERR den Hinterhalt, der wider Juda kommen war, uber die Kinder Ammon, Moab und die vom Gebirge Seir kommen; und schlugen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Da stunden die Kinder Ammon und Moab wider die vom Gebirge Seir, sie zu verbannen und zu vertilgen. Und da sie die vom Gebirge Seir hatten alle aufgerieben, half einer dem andern, daß sie sich auch verderbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Da aber Juda gen Mizpe kam an der Wüste, wandten sie sich gegen den Haufen; und siehe, da lagen die toten Leichname auf der Erde, dafi keiner entronnen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Und Josaphat kam mit seinem Volk, ihren Raub auszuteilen, und fanden unter ihnen so viel Güter und Kleider und kostlich Gerat und entwandten es ihnen, daß auch nicht zu tragen war; und teilten drei Tage den Raub aus, denn es war sein viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Am vierten Tage aber kamen sie zusammen im Lobetal; denn daselbst lobten sie den HERRN. Daher heifiet die Statte Lobetal bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Also kehrete jedermann von Juda und Jerusalem wieder urn, und Josaphat an der Spitze, daß sie gen Jerusalem zogen mit Freuden. Denn der HERR hatte ihnen eine Freude gegeben an ihren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Und zogen gen Jerusalem ein mit Psaltern, Harfen und Trommeten zum Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Und die Furcht Gottes kam über alle Konigreiche in Landen, da sie horeten, daß der HERR wider die Feinde Israels gestritten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Also ward das Konigreich Josaphats stille, und Gott gab ihm Ruhe umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Und Josaphat regierete über Juda, und war funfunddreifüg Jahre alt, da er Konig ward, und regierete fünfundzwanzig Jahre zu Jerusalem. Seine Mutter hieli Asuba, eine Tochter Silhis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Und er wandelte in dem Wege seines Vaters Assa und lieti nicht davon, daß ertat, was dem HERRN wohlgefiel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'ohne die Hohen wurden nicht abgetan; denn das Volk hatte sein Herz noch nicht geschickt zu dem Gott ihrer Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Was aber mehr von Josaphat zu sagen ist, beide das Erste und das Letzte, siehe, das ist geschrieben in den Geschichten Jehus, des Sohns Hananis, die er aufgezeichnet hat ins Buch der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Danach vereinigte sich Josaphat, der Konig Judas, mit Ahasja, dem Konige Israels, welcherwar gottlos mit seinem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Und er vereinigte sich mit ihm, Schiffe zu machen, dafi sie aufs Meer fuhren; und sie machten die Schiffe zu Ezeon-Gaber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Aber Elieser, der Sohn Dodavas, von Maresa, weissagte wider Josaphat und sprach: Darum daß du dich mit Ahasja vereiniget hast, hat der HERR deine Werke zerrissen. Und die Schiffe wurden zerbrochen und mochten nicht aufs Meer fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Und Josaphat entschlief mit seinen Vatern und ward begraben bei seinen Vatern in der Stadt Davids; und sein Sohn Joram ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Und er hatte Bruder, Josaphats Sohne, Asarja, Jehiel, Sacharja, Asarja, Michael und Sephatja; diese waren alle Kinder Josaphats, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Und ihr Vater gab ihnen viel Gaben von Silber, Gold und Kleinod mit festen Stadten in Juda; aber das Konigreich gab er Joram, denn der war der Erstgeborne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Da aber Joram aufkam uber das Konigreich seines Vaters und sein machtig ward, erwurgete er seine Bruder alle mit dem Schwert, dazu auch etliche Oberste in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Zweiunddreiftig Jahre alt war Joram, da er Konig ward, und regierete acht Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Und wandelte in dem Wege der Konige Israels, wie das Haus Ahab getan hatte, denn Ahabs Tochter war sein Weib; und tat, das dem HERRN ubel gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Aber der HERR wollte das Haus David nicht verderben urn des Bundes willen, den er mit David gemacht hatte, und wie er geredet hatte, ihm eine Leuchte zu geben und seinen Kindern immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Zu seiner Zeit fielen die Edomiter ab von Juda und machten uber sich einen Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Denn Joram war hinübergezogen mit seinen Obersten, und alle Wagen mit ihm, und hatte sich des Nachts aufgemacht und die Edomiter urn ihn her und die Obersten der Wagen geschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Darum fielen die Edomiter ab von Juda bis auf diesen Tag. Zurselben Zeitfiel Libna auch von ihm ab. Denn erverlieft den HERRN, seiner Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Auch machte er Hohen auf den Bergen in Juda und machte die zu Jerusalem huren und verfuhrete Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Es kam aber Schrift zu ihm von dem Propheten Elia, die lautete also: So spricht der HERR, der Gott deines Vaters David: Darum daß du nicht gewandelt hast in den Wegen deines Vaters Josaphat noch in den Wegen Assas, des Konigs Judas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'sondern wandelst in dem Wege der Konige Israels und machest, daß Juda und die zu Jerusalem huren nach der Hurerei des Hauses Ahab, und hast dazu deine Bruder deines Vaters Hauses erwurget, die besser waren denn du,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'siehe, so wird dich der HERR mit einer groften Plage schlagen an deinem Volk, an deinen Kindern, an deinen Weibern und an all deiner Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Du aber wirst viel Krankheit haben in deinem Eingeweide, bis daß dein Eingeweide vor Krankheit herausgehe von Tage zu Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Also erweckte der HERR wider Joram den Geist der Philister und Araber, die neben den Mohren liegen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'und zogen herauf nach Juda und zerrissen sie und fuhreten weg alle Habe, die vorhanden war im Hause des Konigs, dazu seine Sohne und seine Weiber, daß ihm kein Sohn uberblieb, ohne Joahas, sein jungster Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Und nach dem allem plagte ihn der HERR in seinem Eingeweide mit solcher Krankheit, die nicht zu heilen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Und da das wahrete von Tage zu Tage, alsdie Zeit zweier Jahre urn war, ging sein Eingeweide von ihm mit seiner Krankheit, und er starb an bosen Krankheiten. Und sie machten nicht uber ihm einen Brand, wie sie seinen Vatern getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Zweiunddreiftig Jahre alt war er, da er Konig ward, und regierete acht Jahre zu Jerusalem und wandelte, daß nicht fein war. Und sie begruben ihn in der Stadt Davids, aber nicht unter der Konige Graber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Und die zu Jerusalem machten zum Konig Ahasja, seinen jungsten Sohn, an seiner Statt. Denn die Kriegsleute, die aus den Arabern mit dem Heer kamen, hatten die ersten alle erwurget; darum ward Konig Ahasja, der Sohn Jorams, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Zweiundvierzig Jahre alt war Ahasja, da er Konig ward, und regierete ein Jahr zu Jerusalem. Seine Mutter hieft Athalja, die Tochter Amris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Und er wandelte auch in den Wegen des Hauses Ahab; denn seine Mutter hielt ihn dazu, daß er gottlos war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Darum tat er, das dem HERRN ubel gefiel, wie das Haus Ahab. Denn sie waren seine Ratgeber nach seines Vaters Tode, daß sie ihn verderbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Und er wandelte nach ihrem Rat. Und erzog hin mit Joram, dem Sohn Ahabs, dem Konige Israels, in den Streit gen Ramoth in Gilead wider Hasael, den Konig zu Syrien. Aber die Syrer schlugen Joram,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'daß er umkehrete, sich heilen zu lassen zu Jesreel; denn er hatte Wunden, die ihm geschlagen waren zu Rama, da er stritt mit Hasael, dem Konige zu Syrien. Und Asarja, der Sohn Jorams, der Konig Judas, zog hinab, zu besehen Joram, den Sohn Ahabs, zu Jesreel, der krank lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Denn es war von Gott Ahasja der Unfall zugefuget, daß erzu Joram kame und also mit Joram auszoge wider Jehu, den Sohn Nimsis, welchen der HERR gesalbet hatte, auszurotten das Haus Ahab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Da nun Jehu Strafe übte am Hause Ahab, fand er etliche Oberste aus Juda und die Kinder der Bruder Ahasjas, die Ahasja dieneten, und erwurgete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Und er suchte Ahasja und gewann ihn, da er sich versteckt hatte zu Samaria. Und erward zu Jehu gebracht; der totete ihn, und man begrub ihn. Denn sie sprachen: Er ist Josaphats Sohn, der nach dem HERRN trachtete von ganzem Herzen. Und es war niemand mehr aus dem Hause Ahasjas, der Konig würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Da aber Athalja, die Mutter Ahasjas, sah, dad ihr Sohn tot war, machte sie sich auf und brachte um alien koniglichen Samen im Hause Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Aber Josabeath, des Konigs Schwester, nahm Joas, den Sohn Ahasjas, und stahl ihn unter den Kindern des Konigs, die getotetwurden, und tat ihn mit seiner Amme in eine Schlafkammer. Also verbarg ihn Josabeath, die Tochter des Konigs Joram, des Priesters Jojada Weib (denn sie war Ahasjas Schwester) vor Athalja, dad er nicht getotet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Und erward mit ihnen im Hause Gottes versteckt sechs Jahre, weil Athalja Konigin war im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Aber im siebenten Jahr nahm Jojada einen Mut und nahm die Obersten uber hundert, namlich Asarja, den Sohn Jerohams, Ismael, den Sohn Johanans, Asarja, den Sohn Obeds, Maeseja, den Sohn Adajas, und Elisaphat, den Sohn Sichris, mit ihm zum Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Die zogen umher in Juda und brachten die Leviten zuhauf aus alien Stadten Judas und die obersten Vater unter Israel, dad sie kamen gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Und die ganze Gemeine machte einen Bund im Hause Gottes mit dem Konige. Und er sprach zu ihnen: Siehe, des Konigs Sohn soil Konig sein, wie der HERR geredet hat uber die Kinder Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'So sollt ihr nun also tun: Euer das dritte Teil, die des Sabbats antreten, soli sein unter den Priestern und Leviten, die Torhuter sind an der Schwelle,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'und das dritte Teil im Hause des Konigs und das dritte Teil am Grundtor; aber alles Volk soil sein im Hofe am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Und daß niemand in das Haus des HERRN gehe, ohne die Priester und Leviten, die da dienen, die sollen hineingehen, denn sie sind Heiligtum; und alles Volk warte der Hut des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Und die Leviten sollen sich rings um den Konig her machen, ein jeglicher mit seiner Wehre in der Hand. Und wer ins Haus gehet, der sei des Todes! Und sie sollen bei dem Konige sein, wenn er aus- und eingehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Und die Leviten und ganz Juda taten, wie der Priester Jojada geboten hatte, und nahm ein jeglicher seine Leute, die des Sabbats antraten, mit denen, die des Sabbats abtraten. Denn Jojada, der Priester, lieft die zween Haufen nicht voneinander kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Und Jojada, der Priester, gab den Obersten uber hundert Spiefte und Schilde und Waffen des Konigs David, die im Hause Gottes waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Und stellete alles Volk, einen jeglichen mit seinen Waffen in der Hand, vor dem rechten Winkel des Hauses bis zum linken Winkel, zum Altar und zum Hause warts, um den Konig her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Und sie brachten des Konigs Sohn hervor und setzten ihm die Krone auf, und das Zeugnis, und machten ihn zum Konige. Und Jojada samt seinen Sohnen salbeten ihn und sprachen: Gluck zu dem Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Da aber Athalja horete das Geschrei des Volks, das zulief und den Konig lobte, ging sie zum Volk im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Und sie sah, und siehe, der Konig stund an seiner Statte im Eingang, und die Obersten und Trommeter um den Konig; und alles Landvolkwar frohlich und blies die Trommeten, und die Sanger mit allerlei Saitenspiel, geschickt zu loben. Da zerrift sie ihre Kleider und sprach: Aufruhr, Aufruhr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Aber Jojada, der Priester, machte sich heraus mit den Obersten uber hundert, die uber das Heer waren, und sprach zu ihnen: Führet sie vom Hause uber den Hof hinaus; und wer ihr nachfolget, den soil man mit dem Schwert toten. Denn der Priester hatte befohlen, man sollte sie nicht toten im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Und sie legten die Hande an sie; und da sie kam zum Eingang des Rotitors am Hause des Konigs, toteten sie sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Und Jojada machte einen Bund zwischen ihm und allem Volk und dem Konige, daß sie des HERRN Volk sein sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Da ging alles Volk ins Haus Baals und brachen ihn ab, und seine Altare und Bilder zerbrachen sie und erwurgeten Mathan, den Priester Baals, vor den Altaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Und Jojada bestellete die Amter im Hause des HERRN unter den Priestern und den Leviten, die David verordnet hatte zum Hause des HERRN; Brandopfer zu tun dem HERRN, wie es geschrieben stehet im Gesetz Mose, mit Freuden und Liedern, durch David gedichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Und stellete Torhuter in die Tore am Hause des HERRN, daß nichts Unreines hineinkame an irgendeinem Dinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Und er nahm die Obersten uber hundert und die Machtigen und Herren im Volk und alles Landvolk und fuhrete den Konig hinab vom Hause des HERRN und brachten ihn durch das hohe Tor am Hause des Konigs; und lieften den Konig sich auf den koniglichen Stuhl setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Und alles Landvolk war frohlich, und die Stadt war stille; aber Athalja ward mit dem Schwert erwurget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas war sieben Jahre alt, da er Konig ward, und regierete vierzig Jahre zu Jerusalem. Seine Mutter hieft Zibja von Berseba.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Und Joas tat, was dem HERRN wohlgefiel, solange der Priester Jojada lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Und Jojada gab ihm zwei Weiber, und er zeugete Sohne und Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Danach nahm Joas vor, das Haus des HERRN zu erneuern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Und versammelte die Priester und Leviten und sprach zu ihnen: Ziehet aus zu alien Stadten Judas und sammelt Geld aus dem ganzen Israel, das Haus eures Gottes zu bessern jahrlich; und eilet, solches zu tun! Aber die Leviten eileten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Da rief der Konig Jojada, dem Vornehmsten, und sprach zu ihm: Warum hast du nicht acht auf die Leviten, daß sie einbringen von Juda und Jerusalem die Steuer, die Mose, der Knecht des HERRN, gesetzt hat, die man sammelte unter Israel zu der Hutte des Stitts?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Denn die gottlose Athalja und ihre Sohne haben das Haus Gottes zerrissen und alles, was zum Hause des HERRN geheiliget war, haben sie an Baalim vermacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Da befahl der Konig, daß man ein Lade machte und setzte sie außen ins Tor am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Und liefi ausrufen in Juda und zu Jerusalem, daß man dem HERRN einbringen sollte die Steuer von Mose, dem Knechte Gottes, auf Israel gelegt in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Da freueten sich alle Obersten und alles Volk und brachten es und warfen es in die Lade, bis sie voll ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Und wenn\'s Zeit war, daß man die Lade herbringen sollte durch die Leviten nach des Konigs Befehl (wenn sie sahen daß viel Geld drinnen war), so kam der Schreiber des Konigs, und wer vom vornehmsten Priester Befehl hatte, und schutteten die Lade aus und trugen sie wieder hin an ihren Ort. So taten sie alle Tage, daß sie Geldes die Menge zuhauf brachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Und der Konig und Jojada gaben es den Arbeitern, die da schafften am Hause des HERRN; dieselben dingeten Steinmetzen und Zimmerleute, zu erneuern das Haus des HERRN; auch den Meistern an Eisen und Erz, zu bessern das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Und die Arbeiter arbeiteten, daß die Besserung im Werkzunahm durch ihre Hand; und machten das Haus Gottes ganz fertig und wohl zugerichtet; und machten es fest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Und da sie es vollendet hatten, brachten sie das ubrige Geld vor den Konig und Jojada; davon machte man Gefaße zum Hause des HERRN, Gefaße zum Dienst und zu Brandopfern, Loffel und guldene und silberne Gerate. Und sie opferten Brandopfer, bei dem Hause des HERRN allewege, solange Jojada lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Und Jojada ward alt und des Lebens satt und starb; und war hundertunddreißig Jahre alt, da er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Und sie begruben ihn in der Stadt Davids unter die Konige, darum daß er hatte wohlgetan an Israel und an Gott und seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Und nach dem Tode Jojadas kamen die Obersten in Juda und beteten den Konig an; da gehorchte ihnen der Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Und sie verlielien das Haus des HERRN, des Gottes ihrer Vater, und dieneten den Hainen und Gotzen. Da kam der Zorn uber Juda und Jerusalem urn dieser ihrer Schuld willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Ersandte aber Propheten zu ihnen, daß sie sich zu dem HERRN bekehren sollten; und die bezeugten sie; aber sie nahmen es nicht zu Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Und der Geist Gottes zog an Sacharja, den Sohn Jojadas, des Priesters. Der trat oben uber das Volk und sprach zu ihnen: So spricht Gott: Warum übertretet ihrdie Gebote des HERRN, das euch nicht gelingen wird? Denn ihr habt den HERRN verlassen, so wird er euch wieder verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Aber sie machten einen Bund wider ihn und steinigten ihn nach dem Gebot des Konigs im Hofe am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Und der Konig Joas gedachte nicht an die Barmherzigkeit, die Jojada sein Vater, an ihm getan hatte, sondern erwurgete seinen Sohn. Da eraber starb, sprach er: Der HERR wird\'s sehen und suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Und da das Jahr urn war, zog herauf das Heer der Syrer, und kamen nach Juda und Jerusalem und verderbeten alle Obersten im Volk; und alien ihren Raub sandten sie dem Konige zu Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Denn der Syrer Macht kam mit wenig Mannern, noch gab der HERR in ihre Hand eine sehr große Macht, darum daß sie den HERRN, ihrer Vater Gott, verlassen hatten. Auch übten sie an Joas Strafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Und da sie von ihm zogen, ließen sie ihn in großen Krankheiten. Es machten aber seine Knechte einen Bund wider ihn urn des Bluts willen der Kinder Jojadas, des Priesters, und erwurgeten ihn auf seinem Bette; und er starb. Und man begrub ihn in der Stadt Davids, aber nicht unter der Konige Graber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Die aber den Bund wider ihn machten, waren diese: Sabad, der Sohn Simeaths, der Ammonitin, und Josabad, der Sohn Simriths, der Moabitin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Aber seine Sohne und die Summa, die unter ihm versammelt war, und der Bau des Hauses Gottes, siehe, die sind beschrieben in der Historia im Buch der Konige. Und sein Sohn Amazia ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Funfundzwanzig Jahre alt war Amazia, da er Konig ward, und regierete neunundzwanzig Jahre zu Jerusalem. Seine Mutter hieß Joadan von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Und er tat, was dem HERRN wohlgefiel, doch nicht von ganzem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Da nun sein Konigreich bekraftiget war, erwurgete er seine Knechte, die den Konig, seinen Vater, geschlagen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Aber ihre Kinder totete er nicht. Denn also stehet es geschrieben im Gesetz, im Buch Moses, da der HERR gebeut und spricht: Die Vater solien nicht sterben fur die Kinder, noch die Kinder fur die Vater, sondern ein jeglicher, soil urn seiner Sunde willen sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Und Amazia brachte zuhauf Juda und stellete sie nach der Vater Hausern, nach den Obersten uber tausend und uber hundert, unter ganz Juda und Benjamin; und zahlete sie von zwanzig Jahren und druber und fand ihrer dreihunderttausend auserlesen, die ins Heer ziehen mochten und Spieß und Schild führen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Dazu nahm eran aus Israel hunderttausend starke Kriegsleute um hundert Zentner Silbers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Es kam aber ein Mann Gottes zu ihm und sprach: Konig, lafi nicht das Heer Israels mit dir kommen; denn der HERR ist nicht mit Israel noch mit alien Kindern Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Denn so du kommst, daß du eine Kühnheit beweisest im Streit, wird Gott dich fallen lassen, vor deinen Feinden. Denn bei Gott stehet die Kraft, zu helfen und fallen zu lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amazia sprach zu dem Mann Gottes. Was soil man denn tun mit den hundert Zentnern, die ich den Kriegsknechten von Israel gegeben habe? Der Mann Gottes sprach: Der HERR hat noch mehr, denn des ist, das erdirgeben kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Da sonderte Amazia die Kriegsknechte ab, die zu ihm aus Ephraim kommen waren, daß sie an ihren Ort hingingen. Da ergrimmete ihr Zorn wider Juda sehr, und zogen wieder an ihren Ort mit grimmigem Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Und ward getrost und fuhrete sein Volk aus und zog aus ins Salztal und schlug der Kinder von Seir zehntausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Und die Kinder Juda fingen ihrer zehntausend lebendig; die fuhreten sie auf die Spitze eines Felsen und stürzten sie von der Spitze des Felsen, daß sie alle zerborsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Aber die Kriegsknechte, die Amazia hatte wiederum lassen ziehen, daü sie nicht mit seinem Volk zum Streit zogen, taten sich nieder in den Stadten Judas, von Samaria an bis gen Beth-Horon, und schlugen ihrer dreitausend und nahmen viel Raubes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Und da Amazia wiederkam von der Edomiter Schlacht, brachte er die Gotter der Kinder von Seir und stellete sie ihm zu Gottern; und betete an vor ihnen und raucherte ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Da ergrimmete der Zorn des HERRN uber Amazia und sandte einen Propheten zu ihm, der sprach zu ihm: Warum suchest du die Gotter des Volks, die ihr Volk nicht konnten erretten von deiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Und da er mit ihm redete, sprach erzu ihm: Hat man dich zu des Konigs Rat gemacht? Hore auf, warum willst du geschlagen sein? Da horete der Prophet auf und sprach: Ich merke wohl, daü Gott sich beraten hat, dich zu verderben, daß du solches getan hast und gehorchest meinem Rat nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Und Amazia, der Konig Judas, ward Rats und sandte hin zu Joas, dem Sohn Joahas, des Sohns Jehus, dem Konige Israels, und lieü ihm sagen: Komm, lali uns miteinander besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Aber Joas, der Konig Israels, sandte zu Amazia, dem Konige Judas, und lieü ihm sagen: Der Dornstrauch im Libanon sandte zu der Zeder im Libanon und lieü ihr sagen: Gib deine Tochter meinem Sohn zum Weibe; aber das Wild im Libanon lief uber den Dornstrauch und zertrat ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Du gedenkest: Siehe, ich habe die Edomiter geschlagen; des erhebet sich dein Herz und suchest Ruhm. Nun bleibe daheim! Warum ringest du nach Ungluck, daß du fallest und Juda mit dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Aber Amazia gehorchte nicht; denn es geschah von Gott, daü sie gegeben wurden in die Hand, darum daß sie die Gotter der Edomiter gesucht hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Da zog Joas, der Konig Israels, herauf, und besahen sich miteinander, er und Amazia, der Konig Judas, zu Beth-Semes, die in Juda liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Aber Juda ward geschlagen vor Israel, und flohen ein jeglicher in seine Hütte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Aber Amazia, den Konig Judas, den Sohn Joas, griff Joas, der Sohn Joahas, der Konig Israels, zu Beth-Semes und brachte ihn gen Jerusalem und rili ein die Mauern zu Jerusalem vom Tor Ephraim an bis an das Ecktor, vierhundert Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Und alles Gold und Silber und alle Gefalie, die vorhanden waren im Hause Gottes bei Obed-Edom und in dem Schatz im Hause des Konigs, und die Kinder zu Pfande nahm er mit sich gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Und Amazia, der Sohn Joas, der Konig Judas, lebte nach dem Tode Joas, des Sohns Joahas, des Konigs Israels, funfzehn Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Was aber mehr von Amazia zu sagen ist, beide das Erste und das Letzte, siehe, das ist geschrieben im Buch der Konige Judas und Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Und von der Zeit an, da Amazia von dem HERRN abwich, machten sie einen Bund wider ihn zu Jerusalem; er aber floh gen Lachis. Da sandten sie ihm nach gen Lachis und toteten ihn daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Und sie brachten ihn auf Rossen und begruben ihn bei seinen Vatern in der Stadt Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Da nahm das ganze Volk Juda Usia, der war sechzehn Jahre alt, und machten ihn zum Konige an seines Vaters Amazia Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Derselbe bauete Eloth und brachte sie wieder an Juda, nachdem der Konig entschlafen war mit seinen Vatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Sechzehn Jahre alt war Usia, da er Konig ward, und regierete zweiundfunfzig Jahre zu Jerusalem. Seine Mutter hieft Jechalja von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Und er tat, das dem HERRN wohlgefiel, wie sein Vater Amazia getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Und er suchte Gott, solange Sacharja lebte, der Lehrer in den Gesichten Gottes; und solange er den HERRN suchte, ließ ihm Gott gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Denn er zog aus und stritt wider die Philister; und zerriß die Mauern zu Gath und die Mauern zu Jabne und die Mauern zu Asdod; und bauete Stadte um Asdod und unter den Philistern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Denn Gott half ihm wider die Philister, wider die Araber, wider die zu Gur-Baal und wider die Meuniter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Und die Ammoniter gaben Usia Geschenke, und er ward berühmt, bis man kommt nach Agypten, denn er ward immer starker und starker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Und Usia bauete Turme zu Jerusalem am Ecktor und am Taltor und an andern Ecken und befestigte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Er bauete auch Schlosser in der Wuste und grub viel Brunnen; denn er hatte viel Viehes, beide in den Auen und auf den Ebenen; auch Ackerleute und Weingartner an den Bergen und am Karmel, denn er hatte Lust zu Ackerwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Und Usia hatte eine Macht zum Streit, die ins Heer zogen, von Kriegsknechten, in der Zahl gerechnet, unter der Hand Jeiels, des Schreibers, und Maesejas, des Amtmanns, unter der Hand Hananjas aus den Obersten des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Und die Zahl der vornehmsten Vater unter den starken Kriegern war zweitausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Und unter ihrer Hand die Heersmacht dreihunderttausend und siebentausend und funfhundert zum Streit geschickt in Heereskraft, zu helfen dem Konige wider die Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Und Usia schickte ihnen fur das ganze Heer Schilde, Spieße, Helme, Panzer, Bogen und Schleudersteine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Und machte zu Jerusalem Brustwehren kunstlich, die auf den Türmen und Ecken sein sollten, zu schielien mit Pfeilen und graven Steinen. Und sein Gerucht kam weit aus, darum daß ihm sonderlich geholfen ward, bis er machtig ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Und da er machtig worden war, erhub sich sein Herz zu seinem Verderben. Denn er vergriff sich an dem HERRN, seinem Gott, und ging in den Tempel des HERRN, zu rauchern auf dem Rauchaltar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Aber Asarja, der Priester, ging ihm nach und achtzig Priester des HERRN mit ihm, redliche Leute,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'und stunden wider Usia, den Konig, und sprachen zu ihm: Es gebuhrt dir, Usia, nicht, zu rauchern dem HERRN, sondern den Priestern, Aarons Kindern, die zu rauchern geheiliget sind. Gehe heraus aus dem Heiligtum, denn du vergreifest dich; und es wird dir keine Ehre sein vor Gott dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Aber Usia ward zornig; und hatte ein Rauchfati in der Hand. Und da er mit den Priestern murrete, fuhr der Aussatz aus an seiner Stirn vor den Priestern im Hause des HERRN vor dem Rauchaltar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Und Asarja, der oberste Priester, wandte das Haupt zu ihm, und alle Priester, und siehe, da war er aussatzig an seiner Stirn; und sie stieüen ihn von dannen. Ereilete auch selbst, herauszugehen, denn seine Plage warvom HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Also war Usia, der Konig, aussatzig bis an seinen Tod und wohnete in einem sondern Hause aussatzig; denn erward verstolien vom Hause des HERRN. Jotham aber, sein Sohn, stund des Konigs Hause vor und richtete das Volk im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Was aber mehr von Usia zu sagen ist, beide das Erste und das Letzte, hat beschrieben der Prophet Jesaja, der Sohn Amoz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Und Usia entschlief mit seinen Vatern, und sie begruben ihn bei seinen Vatern im Acker bei dem Begrabnis der Konige; denn sie sprachen: Er ist aussatzig. Und Jotham, sein Sohn, ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotham war funfundzwanzig Jahre alt, da er Konig ward, und regierete sechzehn Jahre zu Jerusalem. Seine Mutter hieß Jerusa, eine Tochter Zadoks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Und tat, das dem HERRN wohlgefiel, wie sein Vater Usia getan hatte, ohne daß er nicht in den Tempel des HERRN ging, und das Volk sich noch verderbete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Er bauete das hohe Tor am Hause des HERRN, und an der Mauer Ophel bauete er viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Und bauete die Stadte auf dem Gebirge Juda, und in den Waldern bauete er Schlosser und Turme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Und er stritt mit dem Konige der Kinder Ammon, und er ward ihrer machtig, daß ihm die Kinder Ammon dasselbe Jahr gaben hundert Zentner Silbers, zehntausend Kor Weizen und zehntausend Gerste. So viel gaben ihm die Kinder Ammon auch im andern und im dritten Jahrs');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Also ward Jotham machtig; denn er richtete seine Wege vor dem HERRN, seinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Was aber mehr von Jotham zu sagen ist, und alle seine Streite und seine Wege, siehe, das ist geschrieben im Buch der Konige Israels und Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Funfundzwanzig Jahre alt war er, da er Konig ward, und regierete sechzehn Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Und Jotham entschlief mit seinen Vatern, und sie begruben ihn in der Stadt Davids. Und sein Sohn Ahas ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahas war zwanzig Jahre alt, da er Konig ward, und regierete sechzehn Jahre zu Jerusalem; und tat nicht, das dem HERRN wohlgefiel, wie sein Vater David,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'sondern wandelte in den Wegen der Konige Israels. Dazu machte ergegossene Bilder Baalim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Und raucherte im Tal der Kinder Hinnom und verbrannte seine Sohne mit Feuer nach dem Greuel der Heiden, die der HERR vor den Kindern Israel vertrieben hatte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'und opferte und raucherte auf den Hohen und auf den Hugeln und unter alien grunen Baumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Darum gab ihn der HERR, sein Gott, in die Hand des Konigs zu Syrien, daß sie ihn schlugen und einen groften Haufen von den Seinen gefangen wegfuhreten und gen Damaskus brachten. Auch ward er gegeben unter die Hand des Konigs Israels, daß er eine grofte Schlacht an ihm tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Denn Pekah, der Sohn Remaljas, schlug in Juda hundertundzwanzigtausend auf einen Tag, die alle redliche Leute waren, darum daß sie den HERRN, ihrer Vater Gott, verlieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Und Sichri, ein Gewaltiger in Ephraim, erwurgete Maeseja, den Sohn des Konigs, und Asrikam, den Hausfürsten, und Elkana, den Nachsten nach dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Und die Kinder Israel fuhreten gefangen weg von ihren Brudern zweihunderttausend Weiber, Sohne und Tochter; und nahmen dazu groften Raub von ihnen und brachten den Raub gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Es war aber daselbst ein Prophet des HERRN, der hieft Oded, der ging heraus dem Heer entgegen, das gen Samaria kam, und sprach zu ihnen: Siehe, weil der HERR, eurer Vater Gott, uber Juda zornig ist, hat er sie in eure Hande gegeben; ihr aber habt sie erwurget, so greulich, daß es in den Himmel reichet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Nun gedenket ihr die Kinder Judas und Jerusalems euch zu unterwerfen zu Knechten und Magden. Ist das denn nicht Schuld bei euch wider den HERRN, euren Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'So gehorchet mir nun und bringet die Gefangenen wieder hin, die ihr habt weggefuhret aus euren Brudern; denn des HERRN Zorn ist uber euch ergrimmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Da machten sich aufetliche unter den Vornehmsten der Kinder Ephraim: Asarja, der Sohn Johanans, Berechja, der Sohn Mesillemoths, Jehiskia, der Sohn Sallums, und Amasa, der Sohn Hadlais, wider die, so aus dem Heer kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'und sprachen zu ihnen: Ihr sollt die Gefangenen nicht hereinbringen; denn ihr gedenket nur Schuld vor dem HERRN uber uns, auf daß ihr unserer Sünde und Schuld desto mehr machet; denn es ist zuvor der Schuld zu viel und der Zorn uber Israel ergrimmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Da lieften die Geharnischten die Gefangenen und den Raub vor den Obersten und vor der ganzen Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Da stunden auf die Manner, die jetzt mit Namen genannt sind, und nahmen die Gefangenen und alle die bloft unter ihnen waren, zogen sie an von dem Geraubten und kleideten sie und zogen ihnen Schuhe an; und gaben ihnen zu essen und zu trinken und salbeten sie; und fuhreten sie auf Eseln alle, die schwach waren, und brachten sie gen Jericho, zur Palmenstadt, zu ihren Brudern. Und kamen wieder gen Samaria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Zu derselben Zeit sandte der Konig Ahas zu den Konigen von Assur, daß sie ihm hülfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Und es kamen abermal die Edomiter und schlugen Juda und fuhreten etliche weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Auch taten sich die Philister nieder in den Stadten, in der Aue und gegen Mittag Juda und gewannen Beth-Semes, Ajalon, Gederoth und Socho mit ihren Tochtern und Thimna mit ihren Tochtern und Gimso mit ihren Tochtern; und wohneten drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Denn der HERR demutigte Juda urn Ahas willen, des Konigs Judas, darum daß er Juda bloft machte und vergriff sich am HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Und es kam wider ihn Thiglath-Pilneser, der Konig von Assur, der belagerte ihn; aber er konnte ihn nicht gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Denn Ahas teilte das Haus des HERRN und das Haus des Konigs und der Obersten, das er dem Konige zu Assur gab; aber es half ihm nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Dazu in seiner Not machte der Konig Ahas des Vergreifens am HERRN noch mehr');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'und opferte den Gottern zu Damaskus, die ihn geschlagen batten, und sprach: Die Gotter der Konige zu Syrien helfen ihnen; darum will ich ihnen opfern, daß sie mir auch helfen; so doch dieselben ihm und dem ganzen Israel ein Fall waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Und Ahas brachte zuhauf die Gefafte des Hauses Gottes und sammelte die Gefafte im Hause Gottes und schloft die Türen zu am Hause des HERRN; und machte ihm Altare in alien Winkeln zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Und in den Stadten Judas hin und her machte er Hohen, zu rauchern andern Gottern; und reizte den HERRN, seiner Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Was aber mehr von ihm zu sagen ist, und alle seine Wege, beide die ersten und letzten, siehe, das ist geschrieben im Buch der Konige Judas und Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Und Ahas entschlief mit seinen Vatern, und sie begruben ihn in der Stadt zu Jerusalem; denn sie brachten ihn nicht unter die Graber der Konige Israels. Und sein Sohn Jehiskia ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Jehiskia war funfundzwanzig Jahre alt, da er Konig ward, und regierete neunundzwanzig Jahre zu Jerusalem. Seine Mutter hieft Abia, eine Tochter Sacharjas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Und er tat, das dem HERRN wohlgefiel, wie sein Vater David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Er tat auf die Türen am Hause des HERRN im ersten Monden des ersten Jahrs seines Konigreichs und befestigte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Und brachte hinein die Priester und Leviten und versammelte sie auf der breiten Gasse gegen Morgen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'und sprach zu ihnen: Horet mir zu, ihr Leviten! Heiliget euch nun, daß ihr heiliget das Haus des HERRN, eurer Vater Gottes, und tut heraus den Unflat aus dem Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Denn unsere Vater haben sich vergriffen und getan, das dem HERRN, unserm Gott, ubel gefallt, und haben ihn verlassen. Denn sie haben ihr Angesicht von der Wohnung des HERRN gewandt und den Rücken zugekehret;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'und haben die Tur an der Halle zugeschlossen und die Lampen ausgeloschet und kein Rauchwerk gerauchert und kein Brandopfer getan im Heiligtum dem Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Daher ist der Zorn des HERRN liber Juda und Jerusalem kommen und hat sie gegeben in Zerstreuung und Verwüstung, daß man sie anpfeifet, wie ihr mit euren Augen sehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Denn siehe, um desselben willen sind unsere Vater gefallen durchs Schwert, unsere Sohne, Tochter und Weibersind weggefuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nun habe ich\'s im Sinn, einen Bund zu machen mit dem HERRN, dem Gott Israels, daß sein Zorn und Grimm sich von uns wende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nun, meine Sohne, seid nicht hinlassig; denn euch hat der HERR erwahlet, daß ihr vor ihm stehen sollet, und daß ihr seine Diener und Raucherer seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Da machten sich auf die Leviten: Mahath, der Sohn Amasais, und Joel, der Sohn Asarjas, aus den Kindern der Kahathiter; aus den Kindern aber Merari: Kis, der Sohn Abdis, und Asarja, der Sohn Jehaleleels; aber aus den Kindern der Gersoniter: Joab, der Sohn Simmas, und Eden, der Sohn Joahs;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'und aus den Kindern Elizaphan: Simri und Jeiel; und aus den Kindern Assaph: Sacharja und Mathanja;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'und aus den Kindern Heman: Jehiel und Simei; und aus den Kindern Jeduthun: Semaja und Usiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Und sie versammelten ihre Bruder und heiligten sich; und gingen hinein nach dem Gebot des Konigs aus dem Wort des HERRN, zu reinigen das Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Die Priester aber gingen hinein inwendig ins Haus des HERRN, zu reinigen; und taten alle Unreinigkeit, die im Tempel des HERRN funden ward, auf den Hof am Hause des HERRN; und die Leviten nahmen sie auf und trugen sie hinaus in den Bach Kidron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Sie fingen aber an am ersten Tage des ersten Monden, sich zu heiligen, und am achten Tage des Monden gingen sie in die Halle des HERRN und heiligten das Haus des HERRN acht Tage; und vollendeten es am sechzehnten Tage des ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Und sie gingen hinein zum Konige Hiskia und sprachen: Wir haben gereiniget das ganze Haus des HERRN, den Brandopferaltar und all sein Gerate, den Tisch der Schaubrote und all sein Gerate');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'und alle Gefalie, die der Konig Ahas, da er Konig war, weggeworfen hatte, da er sich versündigte, die haben wir zugerichtet und geheiliget; siehe, sie sind vor dem Altar des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Da machte sich der Konig Hiskia frühe auf und versammelte die Obersten der Stadt und ging hinauf zum Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Und brachten herzu sieben Farren, sieben Widder, sieben Lammer und sieben Ziegenbocke zum Sundopfer fur das Konigreich, fur das Heiligtum und fur Juda. Und er sprach zu den Priestern, den Kindern Aaron, daß sie opfern sollten auf dem Altar des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Da schlachteten sie die Rinder, und die Priester nahmen das Blut und sprengeten es auf den Altar; und schlachteten die Widder und sprengeten das Blut auf den Altar; und schlachteten die Lammer und sprengeten das Blut auf den Altar');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'und brachten die Bocke zum Sundopfer vor den Konig und die Gemeine und legten ihre Hande auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Und die Priester schlachteten sie und entsundigten ihr Blut auf dem Altar, zu versohnen das ganze Israel. Denn der Konig hatte befohlen, Brandopfer und Sundopfer zu tun fur das ganze Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Und er stellete die Leviten im Hause des HERRN mit Zimbeln, Psaltern und Harfen, wiees David befohlen hatte und Gad, der Schauer des Konigs, und der Prophet Nathan; denn es war des HERRN Gebot durch seine Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Und die Leviten stunden mit den Saitenspielen Davids und die Priester mit den Trommeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Und Hiskia hiefi sie Brandopfer tun auf dem Altar. Und um die Zeit, da man anting das Brandopfer, fing auch an der Gesang des HERRN und die Trommeten und auf mancherlei Saitenspiel Davids, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Und die ganze Gemeine betete an; und der Gesang der Sanger und das Trommeten der Trommeterwahrete alles, bis das Brandopfer ausgerichtet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Da nun das Brandopfer ausgerichtet war, beugte sich der Konig und alle, die bei ihm vorhanden waren, und beteten an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Und der Konig Hiskia samtden Obersten hiefi die Leviten den HERRN loben mit dem Gedicht Davids und Assaphs, des Schauers. Und sie lobten mit Freuden und neigeten sich und beteten an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Und Hiskia antwortete und sprach: Nun habt ihr eure Hande gefullet dem HERRN; tretet hinzu und bringet her die Opfer und Lobopfer zum Hause des HERRN. Und die Gemeine brachte herzu Opfer und Lobopfer und jedermann freiwilliges Herzens Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Und die Zahl der Brandopfer, so die Gemeine herzubrachte, war siebenzig Rinder, hundert Widder und zweihundert Lammer, und solches alles zu Brandopfer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Und sie heiligten sechshundert Rinder und dreitausend Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Aber der Priester waren zu wenig und konnten nicht alien Brandopfern die Haut abziehen; darum nahmen sie ihre Bruder, die Leviten, bis das Werk ausgerichtet ward, und bis sich die Priester heiligten. Denn die Leviten sind leichter zu heiligen als die Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Auch war der Brandopfer viel mit dem Fett der Dankopfer und Trankopfer zu den Brandopfern. Also ward das Amt am Hause des HERRN fertig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Und Hiskia freuete sich samt allem Volk, daß man mit Gott bereit war worden; denn es geschah eilend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Und Hiskia sandte hin zum ganzen Israel und Juda und schrieb Briefe an Ephraim und Manasse, daß sie kamen zum Hause des HERRN gen Jerusalem, Passah zu halten dem HERRN, dem Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Und der Konig hielt einen Rat mit seinen Obersten und der ganzen Gemeine zu Jerusalem, das Passah zu halten im andern Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Denn sie konnten\'s nicht halten zur selbigen Zeit, darum daß der Priester nicht genug geheiliget waren, und das Volk noch nicht zuhauf kommen war gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Und es gefiel dem Konige wohl und der ganzen Gemeine,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'und bestelleten, daß solches ausgerufen wurde durch ganz Israel, von Berseba an bis gen Dan, daß sie kamen, Passah zu halten dem HERRN, dem Gott Israels, zu Jerusalem; denn es war lange nicht gehalten, wie es geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Und die Laufer gingen hin mit den Briefen von der Hand des Konigs und seiner Obersten durch ganz Israel und Juda aus dem Befehl des Konigs und sprachen: Ihr Kinder Israel, bekehret euch zu dem HERRN, dem Gott Abrahams, Isaaks und Israels, so wird er sich kehren zu den ubrigen, die noch ubrig unter euch sind aus der Hand der Konige zu Assur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Und seid nicht wie eure Vater und Bruder, die sich am HERRN, ihrer Vater Gott, vergriffen, und er sie gab in eine Verwustung, wie ihr selber sehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'So seid nun nicht halsstarrig, wie eure Vater, sondern gebet eure Hand dem HERRN und kommt zu seinem Heiligtum, das er geheiliget hat ewiglich, und dienet dem HERRN, eurem Gott, so wird sich der Grimm seines Zorns von euch wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Denn so ihr euch bekehret zu dem HERRN, so werden eure Bruder und Kinder Barmherzigkeit haben vor denen, die sie gefangen halten, daß sie wieder in dies Land kommen. Denn der HERR, euer Gott, ist gnadig und barmherzig und wird sein Angesicht nicht von euch wenden, so ihr euch zu ihm bekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Und die Laufer gingen von einer Stadt zur andern im Lande Ephraim und Manasse und bis gen Sebulon; aber sie verlachten sie und spotteten ihrer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Doch etliche von Asser und Manasse und Sebulon demutigten sich und kamen gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Auch kam Gottes Hand in Juda, daß erihnen gab einerlei Herz, zu tun nach des Konigs und der Obersten Gebot aus dem Wort des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Und es kam zuhauf gen Jerusalem ein groli Volk, zu halten das Fest der ungesauerten Brote im andern Monden, eine sehr grolie Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Und sie machten sich auf und taten ab die Altare, die zu Jerusalem waren, und aile Rauchwerke taten sie weg und warfen sie in den Bach Kidron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Und schlachteten das Passah am vierzehnten Tage des andern Monden. Und die Priester und Leviten bekannten ihre Schande und heiligten sich und brachten die Brandopfer zum Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Und stunden in ihrer Ordnung, wie sich\'s gebuhrt, nach dem Gesetz Moses, des Mannes Gottes. Und die Priester sprengeten das Blut von der Hand der Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Denn ihrer waren viel in der Gemeine, die sich nicht geheiliget hatten; darum schlachteten die Leviten das Passah fur aile, die nicht rein waren, daß sie dem HERRN geheiliget wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Auch war des Volks viel von Ephraim, Manasse, Isaschar und Sebulon, die nicht rein waren, sondern alien das Osterlamm nicht, wie geschrieben stehet. Denn Hiskia bat fur sie und sprach: Der HERR, der gutig ist, wird gnadig sein');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'alien, die ihr Herz schicken, Gottzu suchen, den HERRN, den Gott ihrer Vater, und nicht urn der heiligen Reinigkeit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Und der HERR erhorete Hiskia und heilete das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Also hielten die Kinder Israel, die zu Jerusalem funden wurden, das Fest der ungesauerten Brote sieben Tage mit grafter Freude. Und die Leviten und Priester iobeten den HERRN aile Tage mit starken Saitenspielen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Und Hiskia redete herzlich mit alien Leviten, die einen guten Verstand hatten am HERRN. Und sie alien das Fest uber, sieben Tage; und opferten Dankopfer und danketen dem HERRN, ihrer Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Und die ganze Gemeine ward Rats, noch andere sieben Tage zu halten; und hielten auch die sieben Tage mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Denn Hiskia, der Konig Judas, gab eine Hebe fur die Gemeine, tausend Farren und siebentausend Schafe. Die Obersten aber gaben eine Hebe fur die Gemeine, tausend Farren und zehntausend Schafe. Also heiligten sich der Priester viele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Und es freuten sich die ganze Gemeine Juda, die Priester und Leviten und die ganze Gemeine, die aus Israel kommen waren, und die Fremdlinge, die aus dem Lande Israel kommen waren und die in Juda wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Und war eine grofte Freude zu Jerusalem. Denn seit der Zeit Salomos, des Sohns Davids, des Konigs Israels, war solches zu Jerusalem nicht gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Und die Priester und die Leviten stunden auf und segneten das Volk, und ihre Stimme ward erhoret, und ihr Gebet kam hinein vor seine heilige Wohnung im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Und da dies alles war ausgerichtet, zogen hinaus alle Israeliten, die unter den Stadten Judas funden wurden, und zerbrachen die Saulen und hieben die Haine ab und brachen ab die Hohen und Altare aus dem ganzen Juda, Benjamin, Ephraim und Manasse, bis sie sie gar aufraumten. Und die Kinder Israel zogen alle wieder zu ihrem Gut in ihre Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Hiskia aber stellete die Priester und Leviten in ihre Ordnung, einen jeglichen nach seinem Amt, beide der Priester und Leviten, zu Brandopfern und Dankopfern, daß sie dieneten, danketen und lobeten in den Toren des Lagers des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Und der Konig gab sein Teil von seiner Habe zu Brandopfern des Morgens und des Abends und zu Brandopfern des Sabbats und Neumonden und Festen, wie es geschrieben stehet im Gesetz des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Und er sprach zum Volk, das zu Jerusalem wohnete, daß sie Teil gaben den Priestern und Leviten, auf dafi sie konnten desto harter anhalten am Gesetz des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Und da das Wort auskam, gaben die Kinder Israel viel Erstlinge von Getreide, Most, 01, Honig und allerlei Einkommens vom Felde; und allerlei Zehnten brachten sie viel hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Und die Kinder Israel und Juda, die in den Stadten Judas wohneten, brachten auch Zehnten von Rindern und Schafen und Zehnten von dem Geheiligten, das sie dem HERRN, ihrem Gott, geheiliget hatten, und machten hie einen Haufen und da einen Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Im dritten Monden fingen sie an, Haufen zu legen, und im siebenten Monden richteten sie es aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Und da Hiskia mit den Obersten hineinging und sahen die Haufen, lobeten sie den HERRN und sein Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Und Hiskia fragte die Priester und Leviten urn die Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Und Asarja, der Priester, der Vornehmste im Hause Zadok, sprach zu ihm: Seit der Zeit man angefangen hat, die Hebe zu bringen ins Haus des HERRN, haben wirgegessen und sind satt worden, und ist noch viel uberblieben; denn der HERR hat sein Volk gesegnet, darum ist dieser Haufe uberblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Da befahl der Konig, dafi man Kasten zubereiten sollte am Hause des HERRN. Und sie bereiteten sie zu');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'und taten hinein die Hebe, die Zehnten und das Geheiligte treulich. Und uber dasselbe war Furst Chananja, der Levit, und Simei, sein Bruder, der andere,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'und Jehiel, Asasja, Nahath, Asahel, Jerimoth, Josabad, Eliel, Jesmachja, Mahath und Benaja, verordnet von der Hand Chananjas und Simeis, seines Bruders, nach dem Befehl des Konigs Hiskia. Aber Asarja war Furst im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Und Kore, der Sohn Jemnas, der Levit, der Torhüter gegen Morgen, war uber die freiwilligen Gaben Gottes, die dem HERRN zur Hebe gegeben wurden, und fiber die allerheiligsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Und unter seiner Hand waren: Eden, Minjamin, Jesua, Semaja, Amarja und Sachanja in den Stadten der Priester, auf Glauben, daß sie geben sollten ihren Brudern nach ihrer Ordnung, dem Kleinsten wie dem Großen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'dazu denen, die gerechnet wurden fur Mannsbilde von drei Jahren alt und druber, unter alien, die in das Haus des HERRN gingen, ein jeglicher an seinem Tage zu ihrem Amt in ihrer Hut nach ihrer Ordnung;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'auch die fur Priester gerechnet wurden im Hause ihrer Vater, und die Leviten, von zwanzig Jahren und druber, in ihrer Hut nach ihrer Ordnung;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'dazu die gerechnet wurden unter ihre Kinder, Weiber, Sohne und Tochter, unter der ganzen Gemeine. Denn sie heiligten treulich das Geheiligte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Auch waren Manner mit Namen benannt unter den Kindern Aaron, den Priestern, auf den Feldern der Vorstadte in alien Stadten, daß sie Teil gaben alien Mannsbildern unter den Priestern und alien, die unter die Leviten gerechnet wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Also tat Hiskia im ganzen Juda und tat, was gut, recht und wahrhaftig warvordem HERRN, seinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Und in allem Tun, das eranfing, am Dienstdes Hauses Gottes nach dem Gesetz und Gebot, zu suchen seinen Gott, das tat er von ganzem Herzen; darum hatte er auch Gluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Nach diesen Geschichten und Treue kam Sanherib, der Konig zu Assur, und zog nach Juda und lagerte sich vor die festen Stadte und gedachte, sie zu sich zu reißen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Und da Hiskia sah, daß Sanherib kam und sein Angesicht stund, zu streiten wider Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'ward er Rats mit seinen Obersten und Gewaltigen, zuzudecken die Wasservon den Brunnen, die draußen vor der Stadt waren; und sie halfen ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Und es versammelte sich ein groß Volk und deckten zu alle Brunnen und fließenden Wasser mitten im Lande und sprachen: Daß die Konige von Assur nicht viel Wassers finden, wenn sie kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Und er ward getrost und bauete alle Mauern, wo sie luckicht waren, und machte Turme drauf; und bauete draußen noch eine andere Mauer und befestigte Millo an der Stadt Davids; und machte viel Waffen und Schilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Und stellete die Hauptleute zum Streit neben das Volk; und sammelte sie zu sich auf die breite Gasse am Tor der Stadt und redete herzlich mit ihnen und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Seid getrost und frisch, furchtet euch nicht und zaget nicht vor dem Konige von Assur, noch vor all dem Haufen, der bei ihm ist; denn es ist ein grolierer mit unsalsmitihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Mit ihm ist ein fleischlicher Arm; mit uns aber ist der HERR, unser Gott, daß er uns helfe und fuhre unsern Streit. Und das Volk verlieü sich auf die Worte Hiskias, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Danach sandte Sanherib, der Konig zu Assur, seine Knechte gen Jerusalem (denn er lag vor Lachis und alle seine Herrschaft mit ihm) zu Hiskia, dem Konige Judas, und zum ganzen Juda, das zu Jerusalem war, und lieli ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'So spricht Sanherib, der Konig zu Assur: Wes vertrostet ihr euch, die ihr wohnet in dem belagerten Jerusalem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Hiskia beredet euch, daß er euch gebe in den Tod, Hunger und Durst, und spricht: Der HERR, unser Gott, wird uns erretten von der Hand des Konigs zu Assur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Ist er nicht der Hiskia, der seine Hohen und Altare weggetan hat und gesagt zu Juda und Jerusalem: Vor einem Altar sollt ihr anbeten und drauf rauchern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Wisset ihr nicht, was ich und meine Vater getan haben alien Vdlkern in Landern? Haben auch die Gotter der Heiden in Landern mogen ihre Lander erretten von meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Wer ist unter alien Gottern dieser Heiden, die meine Vater verbannet haben, der sein Volk habe mogen erretten von meiner Hand, daß euer Gott euch sollte mogen erretten aus meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'So lafit euch nun Hiskia nicht aufsetzen und laßt euch solches nicht bereden und glaubet ihm nicht. Denn so kein Gott aller Heiden und Konigreiche hat sein Volk mogen von meiner und meiner Vater Hand erretten, so werden auch euch eure Gotter nicht erretten von meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Dazu redeten seine Knechte noch mehr wider den HERRN, den Gott, und wider seinen Knecht Hiskia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Auch schrieb er Briefe, Hohn zu sprechen dem HERRN, dem Gott Israels, und redete von ihm und sprach: Wie die Gotter der Heiden in Landern ihr Volk nicht haben errettet von meiner Hand, so wird auch der Gott Hiskias sein Volk nicht erretten von meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Und sie riefen mit lauter Stimme auf judisch zum Volk zu Jerusalem, das auf der Mauer war, sie furchtsam zu machen und zu erschrecken, dafi sie die Stadt gewonnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'und redeten wider den Gott Jerusalems wie wider die Gotter der Volker auf Erden, die Menschenhande-Werk waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Aber der Konig Hiskia und der Prophet Jesaja, der Sohn Amoz, beteten dawider und schrieen gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Und der HERR sandte einen Engel, der vertilgete alle Gewaltigen des Heers und Fursten und Obersten im Lager des Konigs zu Assur, daß er mit Schanden wieder in sein Land zog. Und da er in seines Gottes Haus ging, falleten ihn daselbst durchs Schwert, die von seinem eigenen Leibe kommen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Also half der HERR Hiskia und denen zu Jerusalem aus der Hand Sanheribs, des Konigs zu Assur, und aller anderen und enthielt sie vor alien umher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'daß viele dem HERRN Geschenke brachten gen Jerusalem und Kleinode Hiskia, dem Konige Judas. Und erward danach erhaben vor alien Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Zu der Zeit ward Hiskia todkrank; und er bat den HERRN. Der redete ihm und gab ihm ein Wunder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Aber Hiskia vergalt nicht, wie ihm gegeben war; denn sein Herz erhub sich. Darum kam der Zorn uber ihn und uber Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Aber Hiskia demutigte sich, daß sein Herz sich erhoben hatte, samt denen zu Jerusalem; darum kam der Zorn des HERRN nicht uber sie, weil Hiskia lebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Und Hiskia hatte sehrgrolien Reichtum und Ehre und machte ihm Schatze von Silber, Gold, Edelsteinen, Würze, Schilden und allerlei kostlichem Gerate');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'und Kornhauserzu dem Einkommen des Getreides, Mosts und Oles und Stalle fur allerlei Vieh und Hurden fur die Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Und bauete ihm Stadte und hatte Vieh an Schafen und Rindern die Menge; denn Gott gab ihm sehr groli Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Er ist der Hiskia, der die hohe Wasserquelle in Gihon zudeckte und leitete sie hinunter von abendwarts zur Stadt Davids; denn Hiskia war gluckselig in alien seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Da aber die Botschaften der Fursten von Babel zu ihm gesandt waren, zu fragen nach dem Wunder, das im Lande geschehen war, verlieli ihn Gott also, daß er ihn versuchte, auf daß kund wurde alles, was in seinem Herzen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Was aber mehr von Hiskia zu sagen ist, und seine Barmherzigkeit, siehe, das ist geschrieben in dem Gesicht des Propheten Jesaja, des Sohns Amoz, im Buch der Konige Judas und Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Und Hiskia entschlief mit seinen Vatern, und sie begruben ihn uber die Graber der Kinder Davids. Und ganz Juda und die zu Jerusalem taten ihm Ehre in seinem Tode. Und sein Sohn Manasse ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse war zwolf Jahre alt, da er Konig ward, und regierete funfundfunfzig Jahre zu Jerusalem;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'und tat, das dem HERRN ubel gefiel, nach den Greueln der Heiden, die der HERR vor den Kindern Israel vertrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Und kehrete sich um und bauete die Hohen die sein Vater Hiskia abgebrochen hatte, und stiftete Baalim Altare und machte Haine und betete an allerlei Heeram Himmel und dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Er bauete auch Altare im Hause des HERRN, davon der HERR geredet hat: Zu Jerusalem soil mein Name sein ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Und bauete Altare allerlei Heer am Himmel in beiden Hofen am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Und er lieft seine Sohne durchs Feuer gehen im Tal des Sohns Hinnoms und wahlte Tage und achtete auf Vogelgeschrei und zauberte und stiftete Wahrsager und Zeichendeuter und tat viel, das dem HERRN ubel gefiel, ihn zu erzurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Er setzte auch Bilder und Gotzen, die er machen lieli, ins Haus Gottes, davon der HERR David geredet hatte und Salomo, seinem Sohn: In diesem Hause zu Jerusalem, die ich erwahlet habe vor alien Stammen Israels, will ich meinen Namen setzen ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'und will nicht mehr den Fuß Israels lassen weichen vom Lande, das ich ihren Vatern bestellet habe, sofern sie sich halten, dafi sie tun alles, was ich ihnen geboten habe, in alien Gesetzen, Geboten und Rechten durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Aber Manasse verführete Juda und die zu Jerusalem, dafi sie arger taten denn die Heiden, die der HERR vor den Kindern Israel vertilget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Und wenn der HERR mit Manasse und seinem Volk reden ließ, merkten sie nichts drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Darum lieli der HERR über sie kommen die Fursten des Heers des Konigs zu Assur; die nahmen Manasse gefangen mit Fesseln und banden ihn mit Ketten und brachten ihn gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Und da er in der Angst war, flehete er vor dem HERRN, seinem Gott, und demutigte sich sehr vor dem Gott seiner Vater,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'und bat und flehete ihn. Da erhorete er sein Flehen und brachte ihn wieder gen Jerusalem zu seinem Konigreich. Da erkannte Manasse, dati der HERR Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Danach bauete er die auliersten Mauern an der Stadt Davids von abendwarts an Gihon im Bach, und da man zum Fischtor eingehet, und umher an Ophel und machte sie sehr hoch; und, legte Hauptleute in die festen Stadte Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Und tat weg die fremden Gotter und die Gotzen aus dem Hause des HERRN und alle Altare, die er gebauet hatte auf dem Berge des Hauses des HERRN und zu Jerusalem; und warf sie hinaus vor die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Und richtete zu den Altar des HERRN und opferte drauf Dankopfer und Lobopfer; und befahl Juda, daß sie dem HERRN, dem Gott Israels, dienen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Doch opferte das Volk auf den Hohen, wiewohl dem HERRN, ihrem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Was aber mehr von Manasse zu sagen ist, und sein Gebet zu seinem Gott, und die Rede der Schauer, die mit ihm redeten im Namen des HERRN, des Gottes Israels, siehe, die sind unter den Geschichten der Konige Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Und sein Gebet und Flehen und alle seine Sunde und Missetat und die Statte, darauf er die Hohen bauete und Haine und Gotzen stiftete, ehe denn ergedemütigetward, siehe, die sind geschrieben, unter den Geschichten der Schauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Und Manasse entschlief mit seinen Vatern, und sie begruben ihn in seinem Hause. Und sein Sohn Amon ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Zweiundzwanzig Jahre alt war Amon, da er Konig ward, und regierete zwei Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Und tat, das dem HERRN ubel gefiel, wie sein Vater Manasse getan hatte. Und Amon opferte alien Gdtzen, die sein Vater Manasse gemacht hatte, und dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Aber er demutigte sich nicht vor dem HERRN, wie sich sein Vater Manasse gedemutiget hatte; denn er, Amon, machte der Schuld viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Und seine Knechte machten einen Bund wider ihn und toteten ihn in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Da schlug das Volk im Lande alle, die den Bund wider den Konig Amon gemacht hatten. Und das Volk im Lande machte Josia, seinen Sohn, zum Konige an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Acht Jahre alt war Josia, da er Konig ward, und regierete einunddreilüg Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Und tat, das dem HERRN wohlgefiel, und wandelte in den Wegen seines Vaters David und wich weder zur Rechten noch zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Denn im achten Jahr seines Konigreichs, da er noch ein Knabe war, fing er an, zu suchen den Gott seines Vaters David, und im zwolften Jahr fing er an, zu reinigen Juda und Jerusalem von den Hohen und Hainen und Gotzen und gegossenen Bildern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Und liefi vor ihm abbrechen die Altare Baalim und die Bilder oben drauf hieb er oben herab; und die Haine und Gotzen und Bilder zerbrach er und machte sie zu Staub und streuete sie auf die Graber derer, die ihnen geopfert hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Und verbrannte die Gebeine der Priester auf den Altaren und reinigte also Juda und Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'dazu in den Stadten Manasses, Ephraims, Simeons und bis an Naphthali, in ihren Wüsten umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Und da er die Altare und Haine abgebrochen und die Gotzen klein zermalmet und alle Bilder abgehauen hatte im ganzen Lande Israel, kam er wieder gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Im achtzehnten Jahr seines Konigreichs, da er das Land und das Haus gereiniget hatte, sandte er Saphan, den Sohn Azaljas, und Maeseja, den Stadtvogt, und Joah, den Sohn Joahas, den Kanzler, zu bessern das Haus des HERRN, seines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Und sie kamen zu dem Hohenpriester Hilkia. Und man gab ihnen das Geld, das zum Hause Gottes gebracht war, welches die Leviten, die an der Schwelle huteten, gesammelt hatten von Manasse, Ephraim und von alien ubrigen in Israel und vom ganzen Juda und Benjamin und von denen, die zu Jerusalem wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Und gaben\'s unter die Hande den Arbeitern, die bestellet waren am Hause des HERRN. Und sie gaben\'s denen, die da arbeiteten am Hause des HERRN, und wo es baufallig war, dad sie das Haus besserten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Dieselben gaben\'s fort den Zimmerleuten und Bauleuten, gehauene Steine und gehofelt Holz zu kaufen, zu den Balken an den Hausern, welche die Konige Judas verderbet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Und die Manner arbeiteten am Werk treulich. Und es waren uber sie verordnet Jahath und Obadja, die Leviten aus den Kindern Merari; Sacharja und Mesullam aus den Kindern der Kahathiten, das Werk zu treiben; und waren alle Leviten, die auf Saitenspiel konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Aber uber die Lasttrager und Treiber zu allerlei Arbeit in alien Amtern waren aus den Leviten die Schreiber, Amtleute und Torhuter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Und da sie das Geld herausnahmen, das zum Hause des HERRN eingelegt war, fand Hilkia, der Priester, das Buch des Gesetzes des HERRN, durch Mose gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Und Hilkia antwortete und sprach zu Saphan, dem Schreiber: Ich habe das Gesetzbuch funden im Hause des HERRN. Und Hilkia gab das Buch Saphan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Saphan aber brachte es zum Konige und sagte dem Konige wieder und sprach: Alles, was unter die Hande deiner Knechte gegeben ist, das machen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Und sie haben das Geld zuhauf geschuttet, das im Hause des HERRN funden ist, und haben\'s gegeben denen, die verordnet sind, und den Arbeitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Und Saphan, der Schreiber, sagte dem Konige an und sprach: Hilkia, der Priester, hat mir ein Buch gegeben. Und Saphan las drinnen vor dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Und da der Konig die Worte des Gesetzes horete, zerrift er seine Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Und der Konig gebot Hilkia und Ahikam, dem Sohn Saphans, und Abdon, dem Sohn Michas, und Saphan, dem Schreiber, und Asaja, dem Knechte des Konigs, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Gehet hin, fraget den HERRN fur mich und fur die ubrigen in Israel und fur Juda uber den Worten des Buchs, das funden ist; denn der Grimm des HERRN ist graft, der uber uns entbrannt ist, daß unsere Vater nicht gehalten haben das Wort des HERRN, dafi sie taten, wie geschrieben stehet in diesem Buch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Da ging Hilkia hin, samt den andern vom Konige gesandt, zu der Prophetin Hulda, dem Weibe Sallums, des Sohns Takehaths, des Sohns Hasras, des Kleiderhüters, die zu Jerusalem wohnete im andern Teil, und redeten solches mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Und sie sprach zu ihnen: So spricht der HERR, der Gott Israels: Saget dem Manne, der euch zu mir gesandt hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'So spricht der HERR: Siehe, ich will Ungluck bringen uber diesen Ort und die Einwohner, alle die Fluche, die geschrieben stehen im Buch, das man vor dem Konige Judas gelesen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'darum daß sie mich verlassen haben und andern Gottern gerauchert, daß sie mich erzurneten mit allerlei Werken ihrer Hande. Und mein Grimm soli angezundet werden uber diesen Ort und nicht ausgeloschetwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Und zum Konige Judas, der euch gesandt hat, den HERRN zu fragen, sollt ihr also sagen: So spricht der HERR, der Gott Israels, von den Worten, die du gehoret hast:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Darum daß dein Herz weich worden ist und hast dich gedemutigt vor Gott, da du seine Worte horetest wider diesen Ort und wider die Einwohner, und hast dich vor mir gedemutiget und deine Kleider zerrissen und vor mir geweinet, so habe ich dich auch erhoret, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Siehe, ich will dich sammeln zu deinen Vatern, daß du in dein Grab mit Frieden gesammelt werdest, daß deine Augen nicht sehen all das Ungluck, das ich uber diesen Ort und die Einwohner bringen will. Und sie sagten\'s dem Konige wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Da sandte der Konig hin und lieft zuhauf kommen alle Altesten in Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Und der Konig ging hinauf ins Haus des HERRN und alle Manner Judas und Einwohner zu Jerusalem, die Priester, die Leviten und alles Volk, beide klein und graft; und wurden vor ihren Ohren gelesen alle Worte im Buch des Bundes, das im Hause des HERRN funden war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Und der Konig trat an seinen Ort und machte einen Bund vor dem HERRN, daß man dem HERRN nachwandeln sollte, zu halten seine Gebote, Zeugnisse und Rechte von ganzem Herzen und von ganzer Seele, zu tun nach alien Worten des Bundes, die geschrieben stunden in diesem Buch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Und stunden da alle, die zu Jerusalem und in Benjamin vorhanden waren. Und die Einwohner zu Jerusalem taten nach dem Bunde Gottes, ihrer Vater Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Und Josia tat weg alle Greuel aus alien Landen, die der Kinder Israel waren, und schaffte, daß alle, die in Israel funden wurden, dem HERRN, ihrem Gott, dieneten. Solange Josia lebte, wichen sie nicht von dem HERRN, ihrer Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Und Josia hielt dem HERRN Passah zu Jerusalem und schlachtete das Passah am vierzehnten Tage des ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Und er stellete die Priester in ihre Hut und starkte sie zu ihrem Amt im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Und sprach zu den Leviten, die ganz Israel lehreten und dem HERRN geheiligetwaren: Tut die heilige Lade ins Haus, das Salomo, der Sohn Davids, der Konig Israels, gebauet hat. Ihr sollt sie nicht auf den Schultern tragen. So dienet nun dem HERRN, eurem Gott, und seinem Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Und, schicket das Haus eurer Vater in eurer Ordnung, wie sie beschrieben ist von David, dem Konige Israels, und seinem Sohn Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Und stehet im Heiligtum nach der Ordnung der Vater Hauser unter euren Brudern, vom Volk geboren, auch die Ordnung der Vater Hauser unter den Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Und schlachtet das Passah und heiliget euch; und schicket eure Bruder, daß sie tun nach dem Wort des HERRN durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Und Josia gab zur Hebe fur den gemeinen Mann Lammer und junge Ziegen (alles zu dem Passah fur alle, die vorhanden waren), an der Zahl dreiftigtausend, und dreitausend Rinder, und alles von dem Gut des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Seine Fursten aber gaben zur Hebe freiwillig fur das Volk und fur die Priester und Leviten (namlich Hilkia, Sacharja und Jehiel, die Fursten im Hause Gottes unter den Priestern) zum Passah zweitausend und sechshundert Lammer und Ziegen, dazu dreihundert Rinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Aber Chananja, Semaja, Nethaneel und seine Bruder, Hasabja, Jeiel und Josabad, der Leviten Oberste, gaben zur Hebe den Leviten zum Passah fünftausend Lammer und Ziegen und dazu fünfhundert Rinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Also ward der Gottesdienst beschickt; und die Priester stunden an ihrer Statte und die Leviten in ihrer Ordnung nach dem Gebot des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Und sie schlachteten das Passah; und die Priester nahmen von ihren Handen und sprengeten, und die Leviten zogen ihnen die Haut ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Und taten die Brandopfer davon, daß sie es gaben unter die Teile der Vater Hauser in ihrem gemeinen Haufen, dem HERRN zu opfern, wie es geschrieben stehet im Buch Mose. So taten sie mit den Rindern auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Und sie kochten das Passah am Feuer, wie sich\'s gebuhrt. Aber was geheiliget war, kochten sie in Topfen, Kesseln und Pfannen; und sie machten\'s eilend fur den gemeinen Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Danach aber bereiteten sie auch fur sich und fur die Priester. Denn die Priester, die Kinder Aaron, schafften an dem Brandopfer und Fetten bis in die Nacht. Darum muftten die Leviten fur sich und fur die Priester, die Kinder Aaron, zubereiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Und die Sanger, die Kinder Assaph, stunden an ihrer Statte nach dem Gebot Davids und Assaphs und Hemans und Jedithuns, des Schauers des Konigs, und die Torhuter an alien Toren, und sie wichen nicht von ihrem Amt, denn die Leviten, ihre Bruder, bereiteten zu fur sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Also ward beschickt aller Gottesdienst des HERRN des Tages, daß man Passah hielt und Brandopfer tat auf dem Altar des HERRN nach dem Gebot des Konigs Josia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Also hielten die Kinder Israel, die vorhanden waren, Passah zu der Zeit und das Fest der ungesauerten Brote sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Es war aber kein Passah gehalten in Israel wie das, von der Zeit an Samuels, des Propheten, und kein Konig in Israel hatte solch Passah gehalten, wie Josia Passah hielt, und die Priester, Leviten, ganz Juda, und was von Israel vorhanden war, und die Einwohner zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Im achtzehnten Jahrdes Konigreichs Josias ward dies Passah gehalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Nach diesem, da Josia das Haus zugerichtet hatte, zog Necho, der Konig in Agypten, herauf, zu streiten wider Karchemis am Phrath. Und Josia zog aus ihm entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Aber er sandte Boten zu ihm und lieft ihm sagen: Was habe ich mit dir zu tun, Konig Judas? Ich komme jetzt nicht wider dich, sondern ich streite wider ein Haus, und Gott hat gesagt, ich soil eilen. Hore auf von Gott, der mit mir ist, daß er dich nicht verderbe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Aber Josia wendete sein Angesicht nicht von ihm, sondern stellete sich, mit ihm zu streiten, und gehorchte nicht den Worten Nechos aus dem Munde Gottes; und kam, mit ihm zu streiten auf der Ebene bei Megiddo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Aber die Schutzen schossen den Konig Josia. Und der Konig sprach zu seinen Knechten: Führet mich hinuber, denn ich bin sehrwund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Und seine Knechte taten ihn von dem Wagen und fuhreten ihn auf seinem andern Wagen und brachten ihn gen Jerusalem; und er starb und ward begraben unter den Grabern seiner Vater. Und ganz Juda und Jerusalem trugen Leid urn Josia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Und Jeremia klagte Josia; und alle Sanger und Sangerinnen redeten ihre Klagelieder uber Josia bis auf diesen Tag und machten eine Gewohnheit draus in Israel. Siehe, es ist geschrieben unter den Klageliedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Was aber mehr von Josia zu sagen ist, und seine Barmherzigkeit nach der Schrift im Gesetz des HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'und seine Geschichten, beide die ersten und letzten, siehe, das ist geschrieben im Buch der Konige Israels und Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Und das Volk im Lande nahm Joahas, den Sohn Josias, und machten ihn zum Konige an seines Vaters Statt zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Dreiundzwanzig Jahre alt war Joahas, da er Konig ward, und regierete drei Monden zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Denn der Konig in Agypten setzte ihn ab zu Jerusalem und büftte das Land urn hundert Zentner Silbers und einen Zentner Goldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Und der Konig in Agypten machte Eljakim, seinen Bruder, zum Konige uber Juda und Jerusalem und wandelte seinen Namen Jojakim. Aber seinen Bruder Joahas nahm Necho und brachte ihn nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Funfundzwanzig Jahre alt war Jojakim, da er Konig ward, und regierete elf Jahre zu Jerusalem; und tat, das dem HERRN, seinem Gott, ubel gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Und Nebukadnezar, der Konig zu Babel, zog wider ihn herauf und band ihn mit Ketten, dafi er ihn gen Babel führete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Audi brachte Nebukadnezar etliche Gefalie des Hauses des HERRN gen Babel und tat sie in seinen Tempel zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Was aber mehr von Jojakim zu sagen ist, und seine Greuel, die ertat, und die an ihm funden wurden, siehe, die sind geschrieben im Buch der Konige Israels und Judas. Und sein Sohn Jojachin ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Acht Jahre alt war Jojachin da er Konig ward, und regierete drei Monden und zehn Tage zu Jerusalem; und tat, das dem HERRN ubel gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Da aber das Jahr umkam, sandte hin Nebukadnezar und lieli ihn gen Babel holen mit den kostlichen Gefalien im Hause des HERRN und machte Zidekia, seinen Bruder, zum Konige uber Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Einundzwanzig Jahre alt war Zidekia, da er Konig ward, und regierete elf Jahre zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Und tat, das dem HERRN, seinem Gott, ubel gefiel, und demutigte sich nicht vor dem Propheten Jeremia, der da redete aus dem Munde des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Dazu ward er abtrunnig von Nebukadnezar, dem Konige zu Babel, der einen Eid bei Gott von ihm genommen hatte und ward halsstarrig und verstockte sein Herz, daß er sich nicht bekehrete zu dem HERRN, dem Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Auch alle Obersten unter den Priestern samt dem Volk machten des Sundigens viel nach allerlei Greueln der Heiden und verunreinigten das Haus des HERRN, das er geheiliget hatte zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Und der HERR, ihrer Vater Gott, sandte zu ihnen durch seine Boten fruhe. Denn er schonete seines Volks und seiner Wohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Aber sie spotteten der Boten Gottes und verachteten seine Worte und affeten seine Propheten, bis der Grimm des HERRN uber sein Volk wuchs, dafi kein Heilen mehr da war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Denn er fuhrete uber sie den Konig der Chaldaer und lieli erwurgen ihre junge Mannschaft mit dem Schwert im Hause ihres Heiligtums und verschonete weder der Junglinge noch Jungfrauen, weder der Alten noch der Grolivater: alle gab er sie in seine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Und alle Gefalie im Hause Gottes, groli und klein, die Schatze im Hause des HERRN und die Schatze des Konigs und seiner Fursten, alles lieli er gen Babel führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Und sie verbrannten das Haus Gottes und brachen ab die Mauern zu Jerusalem, und alle ihre Palaste brannten sie mit Feuer aus, daß alle ihre kostlichen Gerate verderbet wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Und fuhrete weg gen Babel, wer vom Schwert uberblieben war; und wurden seine und seiner Sohne Knechte, bis das Konigreich der Perser regierete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'daß erfüllet wurde das Wort des HERRN durch den Mund Jeremias, bis das Land an seinen Sabbaten genug hatte. Denn die ganze Zeit uber der Verstorung war Sabbat, bis daß siebenzig Jahre voll wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Aber im ersten Jahr Kores, des Konigs in Persien, daß erfüllet wurde das Wort des HERRN durch den Mund Jeremias geredet, erweckte der HERR den Geist Kores, des Konigs in Persien, daß er lieli ausschreien durch sein ganzes Konigreich, auch durch Schrift, und sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'So spricht Kores, der Konig in Persien: Der HERR, der Gott vom Himmel, hat mir alle Konigreiche in Landen gegeben und hat mir befohlen, ihm ein Haus zu bauen zu Jerusalem in Juda. Wer nun unter euch seines Volks ist, mit dem sei der HERR, sein Gott, und ziehe hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Im ersten Jahr Kores, des Konigs in Persien, dafi erfullet würde das Wort des HERRN durch den Mund Jeremias geredet, erweckte der HERR den Geist Kores, des Konigs in Persien, daß er lieli ausschreien durch sein ganzes Konigreich, auch durch Schrift, und sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'So spricht Kores, der Konig in Persien: Der HERR, der Gott vom Himmel, hat mir alle Konigreiche in Landen gegeben; und er hat mir befohlen, ihm ein Haus zu bauen zu Jerusalem in Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Wer nun unter euch seines Volks ist, mit dem sei sein Gott, und er ziehe hinauf gen Jerusalem in Juda und baue das Haus des HERRN, des Gottes Israels. Er ist der Gott, der zu Jerusalem ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Und wer noch ubrig ist an alien Orten, da er Fremdling ist, dem helfen die Leute seines Orts mit Silber und Gold, Gut und Vieh aus freiem Willen zum Hause Gottes zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Da machten sich auf die obersten Vater aus Juda und Benjamin und die Priester und Leviten, alle, deren Geist Gott erweckte, hinaufzuziehen und zu bauen das Haus des HERRN zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Und aile, die urn sie herwaren, starkten ihre Hand mit silbernem und guldenem Gerate, mit Gut und Vieh und Kleinoden, ohne was sie freiwillig gaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Und der Konig Kores tat heraus die Gefalie des Hauses des HERRN, die Nebukadnezar aus Jerusalem genommen und in seines Gottes Haus getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Aber Kores, der Konig in Persien, tat sie heraus durch Mithredath, den Schatzmeister, und zahlete sie dar Sesbazar, dem Fursten Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Und dies ist ihre Zahl: dreiftig guldene Becken und tausend silberne Becken, neunundzwanzig Messer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'dreifüg guldene Becher und der andern silbernen Becher vierhundertundzehn und anderer Gefaße tausend,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'daß aller Gefafte, beide guldene und silberne, waren funftausend und vierhundert. Alle brachte sie Sesbazar herauf mit denen, die aus dem Gefangnis von Babel heraufzogen gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Dies sind die Kinder aus den Landen, die heraufzogen aus dem Gefangnis, die Nebukadnezar, der Konig zu Babel, hatte gen Babel gefuhret, und wiedergen Jerusalem und nach Juda kamen, ein jeglicher in seine Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Und kamen mitßerubabel, Jesua, Nehemia, Seraja, Reelja, Mardochai, Bilsan, Mispar, Bigevai, Rehum und Baena. Dies ist nun die Zahl der Manner des Volks Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'der Kinder Pareos zweitausend hundert und zweiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'der Kinder Sephatja dreihundert und zweiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'der Kinder Arah, siebenhundert und funfundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'der Kinder Pahath-Moab, unter der Kindern Jesua, Joab, zweitausend achthundert und zwolf;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'der Kinder Elam tausend zweihundert und vierundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'der Kinder Sathu neunhundert und funfundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'der Kinder Sakai siebenhundert und sechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'der Kinder Bani sechshundert und zweiundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'der Kinder Bebai sechshundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'der Kinder Asgad tausend zweihundert und zweiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'der Kinder Adonikam sechshundert und sechsundsechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'der Kinder Bigevai zweitausend und sechsundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'der Kinder Adin vierhundert und vierundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'der Kinder Ater von Hiskia achtundneunzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'der Kinder Bezai dreihundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'der Kinder Jorah hundert und zwolf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'der Kinder Hasum zweihundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'der Kinder Gibbar funfundneunzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'der Kinder Beth-Lehem hundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'der Manner Netopha sechsundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'der Manner von Anathoth hundert und achtundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'der Kinder Asmaveth zweiundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'der Kinder von Kiriath-Arim, Kaphira und Beeroth siebenhundert und dreiundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'der Kinder von Rama und Gaba sechshundert und einundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'der Manner von Michmas hundert und zweiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'der Manner von Bethel und Ai zweihundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'der Kinder Nebo zweiundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'der Manner von Magbis hundert und sechsundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'der Kinder des andern Elam tausend zweihundert und vierundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'der Kinder Harim dreihundert und zwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'der Kinder Lod, Hadid und Ono siebenhundert und funfundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'der Kinder Jereho dreihundert und funfundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'der Kinder Senaa dreitausend sechshundert und dreilüg;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'der Priester: der Kinder Jedaja vom Hause Jesua neunhundert und dreiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'der Kinder Immer tausend und zweiundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'der Kinder Pashur tausend zweihundert und siebenundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'der Kinder Harim tausend und siebenzehn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'der Leviten: der Kinder Jesua und Kadmiel von den Kindern Hodavja vierundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'der Sanger: der Kinder Assaph hundert und achtundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'der Kinder der Torhuter: die Kinder Sallum, die Kinder Ater, die Kinder Talmon, die Kinder Akub, die Kinder Hatita und die Kinder Sobai, allesamt hundert und neununddreißig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'der Nethinim: die Kinder Ziha, die Kinder Hasupha, die Kinder Tabaoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'die Kinder Keros, die Kinder Sieha, die Kinder Padon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'die Kinder Lebana, die Kinder Hagaba, die Kinder Akub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'die Kinder Hagab, die Kinder Samlai, die Kinder Hanan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'die Kinder Giddel, die Kinder Gahar, die Kinder Reaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'die Kinder Rezin, die Kinder Nekoda, die Kinder Gasam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'die Kinder Usa, die Kinder Paseah, die Kinder Besai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'die Kinder Asna, die Kinder Meunim, die Kinder Nephusim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'die Kinder Bakbuk, die Kinder Hakupha, die Kinder Harhur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'die Kinder Bazeluth, die Kinder Mehida, die Kinder Harsa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'die Kinder Barkom, die Kinder Sissera, die Kinder Thamah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'die Kinder Neziah, die Kinder Hatipha;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'die Kinder der Knechte Salomos: die Kinder Sotai, die Kinder Sophereth, die Kinder Pruda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'die Kinder Jaela, die Kinder Darkon, die Kinder Giddel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'die Kinder Sephatja, die Kinder Hattil, die Kinder Pochereth von Zebaim, die Kinder Ami.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Aller Nethinim und Kinder der Knechte Salomos waren zusammen dreihundert und zweiundneunzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Und diese zogen auch mit herauf: Mithel, Melah, Thel-Harsa, Cherub-Addon und Immer; aber sie konnten nicht anzeigen ihrer Vater Haus, noch ihren Samen, ob sie aus Israel waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Die Kinder Delaja, die Kinder Tobia, die Kinder Nekoda: sechshundert und zweiundfünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Und von den Kindern der Priester: die Kinder Habaja, die Kinder Hakoz, die Kinder Barsillai, der aus den Tochtern Barsillais, des Gileaditers, ein Weib nahm und ward unter derselben Namen genannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Dieselben suchten ihre Geburtsregister und fanden keine; darum wurden sie vom Priestertum los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Und Hathirsatha sprach zu ihnen, sie sollten nicht essen vom Allerheiligsten, bis ein Priester stunde mit dem Licht und Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Der ganzen Gemeine, wie ein Mann, war zweiundvierzigtausend dreihundert und sechzig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'ausgenommen ihre Knechte und Magde, der waren siebentausend dreihundert, und siebenunddreilüg. Und hatten zweihundert Sanger und Sangerinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'siebenhundert und sechsunddreilüg Rosse, zweihundert und funfundvierzig Mauler,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'vierhundert und fünfunddreißig Kamele und sechstausend siebenhundert und zwanzig Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Und etliche der obersten Vater, da sie kamen zum Hause des HERRN zu Jerusalem, wurden sie freiwillig zum Hause Gottes, daß man es setzte auf seine Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Und gaben nach ihrem Vermogen zum Schatz ans Werk einundsechzigtausend Gulden und fünftausend Pfund Silbers und hundert Priesterrocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Also setzten sich die Priester und die Leviten und etliche des Volks und die Sanger und die Torhuter und die Nethinim in ihre Stadte und alles Israel in seine Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Und da man erlanget hatte den siebenten Monden, und die Kinder Israel nun in ihren Stadten waren, kam das Volk zusammen wie ein Mann gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Und es machte sich auf Jesua, der Sohn Jozadaks, und seine Bruder, die Priester, und der Sohn Sealthiels, und seine Bruder, und baueten den Altar des Gottes Israels, Brandopfer drauf zu opfern, wie es geschrieben stehet im Gesetz Moses, des Mannes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Und richteten zu den Altar auf sein Gestuhle (denn es war ein Schrecken unter ihnen von den Volkern in Landern) und opferten dem HERRN Brandopfer drauf des Morgens und des Abends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Und hielten der Laubhutten Fest, wie geschrieben stehet; und taten Brandopfer alle Tage nach der Zahl, wie sich\'s gebührt, einen jeglichen Tag sein Opfer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'danach auch die taglichen Brandopfer und der Neumonden und aller Festtage des HERRN, die geheiliget waren, und allerlei freiwillige Opfer, die sie dem HERRN freiwillig taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Am ersten Tage des siebenten Monden fingen sie an, dem HERRN Brandopfer zu tun. Aber der Grund des Tempels des HERRN war noch nicht gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Sie gaben aber Geld den Steinmetzen und Zimmerleuten und Speise und Trank und Ol denen zu Zidon und zu Tyrus, daß sie Zedernholz vom Libanon aufs Meer gen Japho brachten nach dem Befehl Kores, des Konigs in Persien, an sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Im andern Jahr ihrer Zukunft zum Hause Gottes gen Jerusalem, des andern Monden, fingen an Serubabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, und die ubrigen ihrer Bruder, Priester und Leviten, und alle, die vom Gefangnis kommen waren gen Jerusalem, und stelleten die Leviten von zwanzig Jahren und druber, zu treiben das Werk am Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Und Jesua stund mit seinen Sohnen und Brudern und Kadmiel mit seinen Sohnen und die Kinder Juda wie ein Mann, zu treiben die Arbeiter am Hause Gottes, namlich die Kinder Henadad mit ihren Kindern und ihren Brudern, die Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Und da die Bauleute den Grund legten am Tempel des HERRN, stunden die Priester, angezogen, mit Trommeten und die Leviten, die Kinder Assaph, mit Zimbeln, zu loben den HERRN mit dem Gedicht Davids, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Und sangen umeinander mit Loben und Danken dem HERRN, daß er gutig ist und seine Barmherzigkeit ewiglich wahret uber Israel. Und alles Volktonete laut mit Loben den HERRN, daß der Grund am Hause des HERRN gelegt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Aber viele der alten Priester und Leviten und obersten Vater, die das vorige Haus gesehen hatten und nun dies Haus vor ihren Augen gegrundet ward, weineten sie laut. Viele aber toneten mit Freuden, daß das Geschrei hoch erscholl,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'dafi das Volk nicht erkennen konnte das Tonen mit Freuden vor dem Geschrei des Weinens im Volk; denn das Volk tonete laut, dafi man das Geschrei feme horete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Da aber die Widersacher Judas und Benjamins horeten, daß die Kinder des Gefangnisses dem HERRN, dem Gott Israels, den Tempel baueten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'kamen sie zu Serubabel und zu den obersten Vatern und sprachen zu ihnen: Wir wollen mit euch bauen, denn wir suchen euren Gott, gleichwie ihr; und wir haben nicht geopfert, seit der Zeit Assar-Haddon, der Konig zu Assur, uns hat heraufgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Aber Serubabel und Jesua und die andern obersten Vater unter Israel antworteten ihnen: Es ziemet sich nicht uns und euch, das Haus unsers Gottes zu bauen, sondern wir wollen allein bauen dem HERRN, dem Gott Israels, wie uns Kores, der Konig in Persien, geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Da hinderte das Volk im Lande die Hand des Volks Juda und schreckten sie ab im Bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Und dingeten Ratgeber wider sie und verhinderten ihren Rat, solange Kores, der Konig in Persien, lebte, bis an das Konigreich Darü, des Konigs in Persien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Denn da Ahasveros Konig ward, im Anfange seines Konigreichs, schrieben sie eine Anklage wider die von Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Und zu den Zeiten Arthahsasthas schrieb Bislam, Mithredath, Tabeel und die andern ihres Rats zu Arthahsastha, dem Konige in Persien. Die Schrift aber des Briefes war auf syrisch geschrieben und ward auf syrisch ausgelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum, der Kanzler, und Simsai, der Schreiber, schrieben diesen Brief wider Jerusalem zu Arthahsastha, dem Konige:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Wir, Rehum, der Kanzler, und Simsai, der Schreiber, und andere des Rats von Dina, von Apharsach, von Tarplat, von Persien, von Arach, von Babel, von Susan, von Deha und von Elam');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'und die andern Volker, welche der große und beruhmte Asnaphar herubergebracht und sie gesetzt hat in die Stadte Samarias und andere diesseit des Wassers und in Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Und dies ist der Inhalt des Briefes, den sie zu dem Konige Arthahsastha sandten: Deine Knechte, die Manner diesseit des Wassers und in Kanaan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Es sei kund dem Konige, daß die Juden, die von dirzu uns heraufkommen sind gen Jerusalem, in die aufruhrerische und bose Stadt, bauen dieselbige und machen ihre Mauern und fuhren sie aus dem Grunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'So sei nun dem Konige kund, wo diese Stadt gebauet wird und die Mauern wieder gemacht, so werden sie Schoß, Zoll und jahrliche Zinsen nicht geben, und ihr Vornehmen wird den Konigen Schaden bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Nun wir aber alle dabei sind, die wir den Tempel zerstoret haben, haben wir die Schmach des Konigs nicht langer wollen sehen; darum schicken wir hin und lassen\'s dem Konige zu wissen tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'daß man lasse suchen in den Chroniken deiner Vater, so wirst du finden in denselbigen Chroniken und erfahren, daß diese Stadt aufruhrerisch und schadlich ist den Konigen und Landen, und machen, daß andere auch abfallen, von alters her, darum die Stadt auch zerstoret ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Darum tun wir dem Konige zu wissen, daß, wo diese Stadt gebauet wird und ihre Mauern gemacht, so wirst du von ihr nichts behalten diesseit des Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Da sandte der Konig eine Antwort zu Rehum, dem Kanzler, und Simsai, dem Schreiber, und den andern ihres Rats, die in Samaria wohneten, und den andern jenseit des Wassers; Friede und Gruß!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Der Brief, den ihr uns zugeschickt habt, ist offentlich vor mir gelesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Und ist von mir befohlen, daß man suchen sollte. Und man hat funden, daß diese Stadt von alters her wider die Konige sich emporet hat, und Aufruhr und Abfall drinnen geschieht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Auch sind machtige Konige zu Jerusalem gewesen, die geherrschet haben uber alles, das jenseit des Wassers ist, daß ihnen Zoll, Schoß und jahrliche Zinsen gegeben worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'So tut nun nach diesem Befehl: Wehret denselben Mannern, daß die Stadt nicht gebauet werde, bis daß von mir der Befehl gegeben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'So sehet nun zu, daß ihr nicht hinlassig hierinnen seid; damit nicht Schaden entstehe dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Da nun der Brief des Konigs Arthahsastha gelesen ward vor Rehum und Simsai, dem Schreiber, und ihrem Rat, zogen sie eilend hinauf gen Jerusalem zu den Juden und wehreten ihnen mit dem Arm und Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Da horete auf das Werk am Hause Gottes zu Jerusalem und blieb nach bis ins andere Jahr Darü, des Konigs in Persien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Es weissagten aber die Propheten Haggai und Sacharja, der Sohn Iddos, zu den Juden, die in Juda und Jerusalem waren, im Namen des Gottes Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Da machten sich auf Serubabel, der Sohn Sealthiels, und Jesua, der Sohn Jozadaks, und fingen an zu bauen das Haus Gottes zu Jerusalem, und mit ihnen die Propheten Gottes, die sie starkten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Zu der Zeit kam zu ihnen Thathnai, der Landpfleger diesseit des Wassers, und Sthar-Bosnai und ihr Rat und sprachen also zu ihnen: Wer hat euch befohlen, dies Haus zu bauen und seine Mauern zu machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Da sagten wir ihnen wie die Manner hielien, die diesen Bau taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Aber das Auge ihres Gottes kam auf die Altesten der Juden, daß ihnen nicht gewehret ward, bis daß man die Sache an Darium gelangen lielie und daruber eine Schrift wiederkame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Dies ist aber der Inhalt des Briefes Thathnais, des Landpflegers diesseit des Wassers, und Sthar- Bosnais und ihres Rats von Apharsach, die diesseit des Wassers waren, an den Konig Darium.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Und die Worte, die sie zu ihm sandten, lauten also: Dem Konige Dario alien Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Es sei kund dem Konige, daß wir ins judische Land kommen sind zu dem Hause des grolien Gottes, welches man bauet mit allerlei Steinen, und Balken leget man in die Wande, und das Werk gehet frisch vonstatten unter ihrer Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Wir aber haben die Altesten gefragt und zu ihnen gesagt also: Wer hat euch befohlen, dies Haus zu bauen und seine Mauern zu machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Auch fragten wir, wie sie hielien, auf daß wir sie dir kundtaten, und haben die Namen beschrieben der Manner, die ihre Obersten waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Sie aber gaben uns solche Worte zur Antwort und sprachen: Wir sind Knechte des Gottes Himmels und der Erde und bauen das Haus, das vorhin vor vielen Jahren gebauet war, das ein grolier Konig Israels gebauet hat und aufgerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Aber da unsere Vater den Gottvom Himmel erzümeten, gab ersie in die Hand Nebukadnezars, des Konigs zu Babel, des Chaldaers; der zerbrach dies Haus und fuhrete das Volk weg gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Aber im ersten Jahr Kores, des Konigs zu Babel, befahl derselbe Konig Kores, dies Haus Gottes zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Denn auch die güldenen und silbernen Gefalie im Hause Gottes, die Nebukadnezar aus dem Tempel zu Jerusalem nahm und brachte sie in den Tempel zu Babel, nahm der Konig Kores aus dem Tempel zu Babel und gab sie Sesbazar mit Namen, den er zum Landpfleger setzte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'und sprach zu ihm: Diese Gefalie nimm, zeuch hin und bringe sie in den Tempel zu Jerusalem und lali das Haus Gottes bauen an seiner Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Da kam derselbe Sesbazar und legte den Grund am Hause Gottes zu Jerusalem. Seit der Zeit bauet man, und ist noch nicht vollendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Gefallt es nun dem Konige, so lasse er suchen in dem Schatzhause des Konigs, das zu Babel ist, ob\'s von dem Konige Kores befohlen sei, das Haus Gottes zu Jerusalem zu bauen, und sende zu uns des Konigs Meinung uber diesem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Da befahl der Konig Darius, daß man suchen sollte in der Kanzlei, im Schatzhause des Konigs, die zu Babel lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Da fand man zu Ahmetha im Schloli, das in Medien liegt, ein Buch, und stund also drinnen eine Geschichte geschrieben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Im ersten Jahr des Konigs Kores befahl der Konig Kores, das Haus Gottes zu Jerusalem zu bauen an der Statte, da man opfert, und den Grund zu legen, zur Hohe sechzig Ellen und zur Weite auch sechzig Ellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'und drei Wande von allerlei Steinen und eine Wand von Holz; und die Kost soil vom Hause des Konigs gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Dazu die güldenen und silbernen Gefalie des Hauses Gottes, die Nebukadnezar aus dem Tempel zu Jerusalem genommen und gen Babel gebracht hat, soil man wiedergeben, daß sie wiedergebracht werden in den Tempel zu Jerusalem an ihre Statt im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'So machet euch nun feme von ihnen, du, Thathnai, Landpfleger jenseit des Wassers und Sthar- Bosnai, und, ihr Rat von Apharsach, die ihr jenseit des Wassers seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Lasset sie arbeiten am Hause Gottes, dafi der Juden Landpfleger und ihre Altesten das Haus Gottes bauen an seiner Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Auch ist von mir befohlen, was man den Altesten Judas tun soli, zu bauen das Haus Gottes, namlich, daß man aus des Konigs Gutern von den Renten jenseit des Wassers mit Fleili nehme und gebe es den Leuten, und daß man ihnen nicht wehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Und ob sie bedurften Kalber, Lammer Oder Bocke zum Brandopfer dem Gott vom Himmel, Weizen, Salz, Wein und 01 nach der Weise der Priester zu Jerusalem, soli man ihnen geben taglich ihre Gebuhr (und daß solches nicht hinlassig geschehel),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'daß sie opfern, zum sufien Geruch dem Gott vom Himmel und bitten fur des Konigs Leben und seiner Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Von mir ist solcher Befehl geschehen. Und welcher Mensch diese Worte verandert, von des Hause soil man einen Balken nehmen und aufrichten und ihn dran hangen, und sein Haus soil dem Gericht verfallen sein um der Tat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Der Gott aber, der im Himmel wohnet, bringe um alle Konige und Volk, das seine Hand ausrecket, zu andern und zu brechen das Haus Gottes zu Jerusalem! Ich, Darius, habe dies befohlen, daß es mit Fleifi getan werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Das taten mit Fleiß Thathnai, der Landpfleger jenseit des Wassers, und Sthar-Bosnai mit ihrem Rat, zu welchen der Konig Darius gesandt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Und die Altesten der Juden baueten; und es ging vonstatten durch die Weissagung der Propheten Haggai und Sacharja, des Sohns Iddos; und baueten und richteten auf nach dem Befehl des Gottes Israels und nach dem Befehl Kores, Darü und Arthahsasthas, der Konige in Persien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'und vollbrachten das Haus bis an den dritten Tag des Monden Adar, das war das sechste Jahr des Konigreichs des Konigs Darü.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Und die Kinder Israel, die Priester, die Leviten und die andern Kinder des Gefangnisses hielten Einweihung des Hauses Gottes mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Und opferten auf die Einweihung des Hauses Gottes hundert Kalber, zweihundert Lammer, vierhundert Bocke und zum Sundopfer fur das ganze Israel zwolf Ziegenbocke, nach der Zahl der Stamme Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Und stelleten die Priester in ihre Ordnung und die Leviten in ihre Hut, zu dienen Gott, der in Israel ist, wie es geschrieben stehet im Buch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Und die Kinder des Gefangnisses hielten Passah am vierzehnten Tage des ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Denn die Priester und Leviten hatten sich gereiniget, daß sie alle rein waren wie ein Mann; und schlachteten das Passah fur alle Kinder des Gefangnisses und fur ihre Bruder, die Priester, und fur sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Und die Kinder Israel, die aus dem Gefangnis waren wiederkommen, und alle, die sich zu ihnen abgesondert hatten von der Unreinigkeit der Heiden im Lande, zu suchen den HERRN, den Gott Israels, alien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'und hielten das Fest der ungesauerten Brote sieben Tage mit Freuden; denn der HERR hatte sie frohlich gemacht und das Herz des Konigs zu Assur zu ihnen gewandt, daß sie gestarkt wurden im Werk am Hause Gottes, der Gott Israels ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Nach diesen Geschichten im Konigreich Arthahsasthas, des Konigs in Persien, zog herauf von Babel Esra, der Sohn Serajas, des Sohns Asarjas, des Sohns Hilkias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'des Sohns Sallums, des Sohns Zadoks, des Sohns Ahitobs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'des Sohns Amarjas, des Sohns Asarjas, des Sohns Merajoths,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'des Sohns Serajas, des Sohns Usis, des Sohns Bukis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'des Sohns Abisuas, des Sohns Pinehas, des Sohns Eleasars, des Sohns Aarons, des obersten Priesters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'welcher war ein geschickter Schriftgelehrter im Gesetz Mose, das der HERR, der Gott Israels, gegeben hatte. Und der Konig gab ihm alles was er forderte, nach der Hand des HERRN, seines Gottes, uber ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Und es zogen herauf etliche der Kinder Israel und der Priester und der Leviten, der Sanger, der Torhuter und der Nethinim gen Jerusalem im siebenten Jahr Arthahsasthas, des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Und sie kamen gen Jerusalem im funften Monden, das ist das siebente Jahr des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Denn am ersten Tage des ersten Monden ward er Rats, heraufzuziehen von Babel, und am ersten Tage des funften Monden kam er gen Jerusalem nach der guten Hand Gottes uber ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Denn Esra schickte sein Herz, zu suchen das Gesetz des HERRN und zu tun und zu lehren in Israel Gebote und Rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Und dies ist der Inhalt des Briefes, den der Konig Arthahsastha gab Esra, dem Priester, dem Schriftgelehrten, der ein Lehrer war in den Worten des HERRN und seiner Gebote uber Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Arthahsastha, Konig aller Konige, Esra, dem Priester und Schriftgelehrten im Gesetz des Gottes vom Himmel, Friede und Grufi!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Von mir ist befohlen, daß alle, die da freiwillig sind in meinem Reich, des Volks Israel und der Priester und Leviten, gen Jerusalem zu ziehen, daß die mit dir ziehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'vom Konige und den sieben Ratsherren gesandt, zu besuchen Juda und Jerusalem nach dem Gesetz Gottes, das unter deiner Hand ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'und mitnehmest Silber und Gold, das der Konig und seine Ratsherren freiwillig geben dem Gott Israels, des Wohnung zu Jerusalem ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'und allerlei Silber und Gold, das du finden kannst in der ganzen Landschaft zu Babel, mit dem, das das Volk und die Priester freiwillig geben zum Hause Gottes zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'All dasselbe nimm und kaufe mit Fleili von demselben Gelde Kalber, Lammer, Bocke und Speisopfer und Trankopfer, daß man opfere auf dem Altare bei dem Hause eures Gottes zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Dazu was dir und deinen Brudern mit dem übrigen Gelde zu tun gefallt, das tut nach dem Willen eures Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Und die Gefafte, die dir gegeben sind zum Amt im Hause deines Gottes, uberantworte vor Gott zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Audi was mehr not sein wird zum Hause deines Gottes, das dir vorfallt auszugeben, das laft geben aus der Kammer des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Ich, Konig Arthahsastha, habe dies befohlen den Schatzmeistern jenseit des Wassers, da(3>, was Esra von euch fordern wird, der Priester und Schriftgelehrte im Gesetz Gottes vom Himmel, daß ihr das fleiftig tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'bis auf hundert Zentner Silbers und auf hundert Kor Weizen und auf hundert Bath Weins und auf hundert Bath Ols und Salzes ohne Maft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Alles, was gehoret zum Gesetz Gottes vom Himmel, daß man dasselbe fleiftig tue zum Hause Gottes vom Himmel, daß nicht ein Zorn komme über des Konigs Konigreich und seine Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Und euch sei kund, daß ihr nicht Macht habt, Zins, Zoll und jahrliche Rente zu legen auf irgend einen Priester, Leviten, Sanger, Torhuter, Nethinim und Diener im Hause dieses Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Du aber, Esra, nach der Weisheit deines Gottes, die unter deiner Hand ist, setze Richter und Pfleger, die alles Volk richten, das jenseit des Wassers ist, alle, die das Gesetz deines Gottes wissen; und welche es nicht wissen, die lehret es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Und alle, die nicht mit Fleift tun werden das Gesetz deines Gottes und das Gesetz des Konigs, der soil sein Urteil urn der Tat willen haben, es sei zum Tode, Oder in die Acht, Oder zur Bufte am Gut, Oder ins Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Geiobet sei der HERR, unserer Vater Gott, der solches hat dem Konige eingegeben, daß er das Haus Gottes zu Jerusalem zierete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'und hat zu mir Barmherzigkeit geneiget vor dem Konige und seinen Ratsherren und alien Gewaltigen des Konigs. Und ich ward getrost, nach der Hand des HERRN, meines Gottes, uber mir, und versammelte die Haupter aus Israel, daß sie mit mir hinaufzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Dies sind die Haupter ihrer Vater, die gerechnet wurden, die mit mir heraufzogen von Babel zu den Zeiten, da der Konig Arthahsastha regierete:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Von den Kindern Pinehas: Gersom von den Kindern Ithamar: Daniel; von den Kindern David: Hattus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'von den Kindern Sechanja, der Kinder Pareos: Sacharja und mit ihm Mannsbilde gerechnet hundertundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'von den Kindern Pahath-Moab: Elioenai, der Sohn Serahjas, und mit ihm zweihundert Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'von den Kindern Sechanja: der Sohn Jehasiel und mit ihm dreihundert Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'von den Kindern Adin-Ebed: der Sohn Jonathans und mit ihm fünfzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'von den Kindern Elam: Jesaia, der Sohn Athaljas, und mit ihm siebenzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'von den Kindern Sephatja: Sebadja, der Sohn Michaels, und mit ihm achtzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'von den Kindern Joab: Obadja, der Sohn Jehiels, und mit ihm zweihundertundachtzehn Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'von den Kindern Selomith: der Sohn Josiphjas und mit ihm hundertundsechzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'von den Kindern Bebai: Sacharja, der Sohn Bebais, und mit ihm achtundzwanzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'von den Kindern Asgad: Johanan, der jungste Sohn, und mit ihm hundertundzehn Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'von den letzten Kindern Adonikam, und hieften also: Eliphelet, Jeiel und Semaja, und mit ihnen sechzig Mannsbilde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'von den Kindern Bigevai: Uthai und Sabud und mit ihnen siebenzig Mannsbilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Und ich versammelte sie ans Wasser, das gen Aheva kommt; und blieben drei Tage daselbst. Und da ich acht hatte aufs Volk und die Priester, fand ich keine Leviten daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Da sandte ich hin Elieser, Ariel, Semaja, Elnathan, Jarib, Elnathan, Nathan, Sacharja und Mesullam, die Obersten, und Jojarib und Elnathan, die Lehrer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'und sandte sie aus zu Iddo, dem Obersten, gen Kasphia, daß sie uns holeten Diener im Hause unsers Gottes. Und ich gab ihnen ein, was sie reden sollten mit Iddo und seinen Brudern, den Nethinim, zu Kasphia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Und sie brachten uns, nach der guten Hand unsers Gottes uber uns, einen klugen Mann aus den Kindern Maheli, des Sohns Levi, des Sohns Israels, Serebja, mit seinen Sohnen und Brudern, achtzehn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'und Hasabja und mit ihm Jesaja von den Kindern Merari mit seinen Brudern und ihren Sohnen, zwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'und von den Nethinim, die David und die Fursten gaben, zu dienen den Leviten, zweihundertundzwanzig, alle mit Namen genannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Und ich lieft daselbst am Wasser bei Aheva ein Fasten ausrufen, daß wir uns demutigten vor unserm Gott, zu suchen von ihm einen richtigen Weg fur uns und unsere Kinder und alle unsere Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Denn ich schamte mich, vom Konige Geleit und Reiter zu fordern, uns wider die Feinde zu helfen auf dem Wege. Denn wir hatten dem Konige gesagt: Die Hand unsers Gottes ist zum besten uber alle, die ihn suchen, und seine Starke und Zorn uber alle, die ihn verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Also fasteten wir und suchten solches an unserm Gott; und er horete uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Und ich sonderte zwolf aus den obersten Priestern: Serebja und Hasabja, und mit ihnen ihrer Bruder zehn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Und wog ihnen dar, das Silber und Gold und Gefafte zur Hebe dem Hause unsers Gottes, welche der Konig und seine Ratsherren und Fursten und ganz Israel, das vorhanden war, zur Hebe gegeben hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Und wog ihnen dar unter ihre Hand sechshundertundfunfzig Zentner Silbers und an silbernen Gefaften hundert Zentner und an Golde hundert Zentner,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'zwanzig guldene Becher, die hatten tausend Gulden, und zwei gute eherne kostliche Gefaße, lauter wie Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Und sprach zu ihnen: Ihrseid heilig dem HERRN, so sind die Gefaße auch heilig, dazu das frei gegebene Silber und Gold dem HERRN, eurer Vater Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'So wachet und bewahret es, bis daß ihr\'s darwaget vor den obersten Priestern und Leviten und obersten Vatern unter Israel zu Jerusalem in den Kasten des Hauses des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Da nahmen die Priester und Leviten das gewogene Silber und Gold und Gefaße, daß sie es brachten gen Jerusalem zum Hause unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Also brachen wir auf von dem Wasser Aheva am zwolften Tage des ersten Monden, daß wir gen Jerusalem zogen. Und die Hand unsers Gottes war uber uns und errettete uns von der Hand der Feinde und die auf uns hielten auf dem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Und kamen gen Jerusalem und blieben daselbst drei Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Aber am vierten Tage ward gewogen das Silber und Gold und Gefaße ins Haus unsers Gottes unter die Hand Meremoths; des Sohns Urias, des Priesters; und mit ihm Eleasar, dem Sohn Pinehas, und mit ihnen Josabad, dem Sohn Jesuas, und Noadja, dem Sohn Benuis, dem Leviten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'nach der Zahl und Gewicht eines jeglichen; und das Gewicht ward zu der Zeit alles beschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Und die Kinder des Gefangnisses, die aus dem Gefangnis kommen waren, opferten Brandopfer dem Gott Israels: zwolf Farren fur das ganze Israel, sechsundneunzig Widder, siebenundsiebenzig Lammer, zwolf Bocke zum Sundopfer, alles zum Brandopfer dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Und sie überantworteten des Konigs Befehl den Amtleuten des Konigs und den Landpflegern diesseit des Wassers. Und sie erhuben das Volk und das Haus Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Da das alles war ausgerichtet, traten zu mir die Obersten und sprachen: Das Volk Israel und die Priester und Leviten sind nicht abgesondert von den Vdlkern in Landern nach ihren Greueln, namlich der Kanaaniter, Hethiter, Pheresiter, Jebusiter, Ammoniter, Moabiter, Agypter und Amoriter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'denn sie haben derselben Tochter genommen sich und ihren Sohnen und den heiligen Samen gemein gemacht mit den Volkern in Landern. Und die Hand der Obersten und Ratherren war die vornehmste in dieser Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Da ich solches horete, zerriß ich meine Kleider und meinen Rock und raufte mein Haupthaar und Bart aus und saß einsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Und es versammelten sich zu mir alle, die des HERRN Wort, des Gottes Israels, furchteten urn der großen Vergreifung willen; und ich saß einsam bis an das Abendopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Und urn das Abendopfer stund ich auf von meinem Elend und zerriß meine Kleider und meinen Rock; und fiel auf meine Kniee und breitete meine Hande aus zu dem HERRN, meinem Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'und sprach: Mein Gott, ich schame mich und scheue mich, meine Augen aufzuheben zu dir, mein Gott; denn unsere Missetat ist uber unser Haupt gewachsen, und unsere Schuld ist groß bis in den Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Von der Zeit unserer Vater an sind wir in großer Schuld gewesen bis auf diesen Tag und urn unserer Missetat willen sind wir und unsere Konige und Priester gegeben in die Hand der Konige in Landern, ins Schwert, ins Gefangnis, in Raub und in Scham des Angesichts, wie es heutigestages gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Nun aber ist ein wenig und plotzlich Gnade von dem HERRN, unserm Gott, geschehen, daß uns noch etwas Ubriges ist entronnen, daß er uns gabe einen Nagel an seiner heiligen Statte, daß unser Gott unsere Augen erleuchtete und gabe uns ein wenig Leben, da wir Knechte sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Denn wir sind Knechte, und unser Gott hat uns nicht verlassen, ob wir Knechte sind, und hat Barmherzigkeit zu uns geneiget vor den Konigen in Persien, daß sie uns das Leben lassen und erhohen das Haus unsers Gottes und aufrichten seine Verstorung und gebe uns einen Zaun in Juda und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Nun, was sollen wir sagen, unser Gott, nach diesem, daß wirdeine Gebote verlassen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'die du durch deine Knechte, die Propheten, geboten hast und gesagt: Das Land, darein ihr kommt zu erben, ist ein unrein Land, durch die Unreinigkeit der Volker in Landern in ihren Greueln, damit sie es hie und da voll Unreinigkeit gemacht haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'So sollt ihr nun eure Tochter nicht geben ihren Sohnen und ihre Tochter sollt ihr euren Sohnen nicht nehmen und suchet nicht ihren Frieden noch Gutes ewiglich, auf daß ihr machtig werdet und esset das Gut im Lande und beerbet es auf eure Kinder ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Und nach dem allem, das uber uns kommen ist urn unserer bosen Werke und großer Schuld willen, hast du, unser Gott, unserer Missetat verschonet und hast uns eine Rettung gegeben, wie es da stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Wir aber haben uns umgekehret und deine Gebote lassen fahren, daß wir uns mit den Volkern dieser Greuel befreundet haben. Willst du denn uber uns zurnen, bis daß es gar aus sei, daß nichts Gbriges noch keine Errettung sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'HERR, Gott Israels, du bist gerecht; denn wir sind uberblieben, eine Errettung, wie es heutigestages stehet. Siehe, wir sind vor dir in unserer Schuld, denn urn deswillen ist nicht zu stehen vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Und da Esra also betete und bekannte, weinete und vordem Hause Gottes lag, sammelten sich zu ihm aus Israel eine sehr große Gemeine von Mannern und Weibern und Kindern; denn das Volk weinete sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Und Sachanja, der Sohn Jehiels, aus den Kindern Elam, antwortete und sprach zu Esra: Wohlan, wir haben uns an unserm Gott vergriffen, daß wir fremde Weiber aus den Volkern des Landes genommen haben. Nun, es ist noch Hoffnung in Israel uber dem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'So lal Jt uns nun einen Bund machen mit unserm Gott, daß wir alle Weiber, und die von ihnen geboren sind, hinaustun nach dem Rat des HERRN und derer, die die Gebote unsers Gottes furchten, daß man tue nach dem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'So mache dich auf, denn dir gebuhrt es; wir wollen mit dir sein. Sei getrost und tu es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Da stund Esra auf und nahm einen Eid von den obersten Priestern und Leviten und dem ganzen Israel, daü sie nach diesem Wort tun sollten. Und sie schwuren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Und Esra stund auf vordem Hause Gottes und ging in die Kammer Johanans, des Sohns Eliasibs. Und da er daselbst hinkam, ait, er kein Brot und trank kein Wasser; denn er trug Leid urn die Vergreifung derer, die gefangen gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Und sie liel Len ausrufen durch Juda und Jerusalem zu alien Kindern, die gefangen waren gewesen, daß sie sich gen Jerusalem versammelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Und welcher nicht kame in dreien Tagen nach dem Rat der Obersten und Altesten, des Habe sollte alle verbannet sein und er abgesondert von der Gemeine der Gefangenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Da versammelten sich alle Manner Judas und Benjamins gen Jerusalem in dreien Tagen, das ist, im zwanzigsten Tage des neunten Monden. Und alles Volk saß auf der Strafie vor dem Hause Gottes und zitterten urn der Sache willen und vom Regen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Und Esra, der Priester, stund auf und sprach zu ihnen: Ihr habt euch vergriffen, dafi ihr fremde Weiber genommen habt, daß ihr der Schuld Israels noch mehr machtet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'So bekennet nun dem HERRN, eurer Vater Gott, und tut sein Wohlgefallen und scheidet euch von den Volkern des Landes und von den fremden Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Da antwortete die ganze Gemeine und sprach mit lauter Stimme: Es geschehe, wie du uns gesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Aber des Volks ist viel und regnerisch Wetter und kann nicht draußen stehen; so ist\'s auch nicht eines Oder zweier Tage Werk, denn wir haben\'s viel gemacht solcher Ubertretung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Laßt uns unsere Obersten bestellen in der ganzen Gemeine, dai?, alle, die in unsern Stadten fremde Weiber genommen haben, zu bestimmten Zeiten kommen, und die Altesten einer jeglichen Stadt und ihre Richter mit, bis daß von uns gewendet werde der Zorn unsers Gottes urn dieser Sache willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Da wurden bestellet Jonathan, der Sohn Asahels, und Jehasja, der Sohn Thikwas, über diese Sachen, und Mesullam und Habthai, die Leviten, halfen ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Und die Kinder des Gefangnisses taten also. Und der Priester Esra und die vornehmsten Vater unter ihrer Vater Hause und alle jetzt Benannten schieden sie; und setzten sich am ersten Tage des zehnten Monden, zu forschen diese Sachen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'und sie richteten\'s aus an alien Mannern, die fremde Weiber hatten, am ersten Tage des ersten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Und es wurden funden unter den Kindern der Priester, die fremde Weiber genommen hatten, namlich unter den Kindern Jesuas, des Sohns Jozadaks, und seinen Brudern: Maesaja, Elieser, Jarib und Gedalja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Und sie gaben ihre Hand drauf, daß sie die Weiber wollten ausstolien und zu ihrem Schuldopfer einen Widder fur ihre Schuld geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Unter den Kindern Immer: Hanani und Sebadja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Unter den Kindern Harim: Maeseja, Elia, Semaja, Jehiel und Usia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Unter den Kindern Pashur: Elioenai, Maeseja, Ismael, Nethaneel Josabad und Eleasa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Unter den Leviten: Josabad, Simei und Kelaja (er ist der Klita), Pethahja, Juda und Elieser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Unter den Sangern: Eliasib. Unter den Torhutern: Sallum, Telem und Uri.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Von Israel unter den Kindern Pareos: Ramaja, Jesia, Malchia, Mejamin, Eleasar, Malchia und Benaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Unter den Kindern Elam: Mathanja, Sacharja, Jehiel, Abdi, Jeremoth und Elia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Unter den Kindern Sathu: Elioenai, Eliasib, Mathanja, Jeremoth, Sabad und Asisa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Unter den Kindern Bebai: Johanan, Hananja, Sabai und Athlai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Unter den Kindern Bani: Mesullam, Malluch, Adaja, Jasub, Seal und Jeramoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Unter den Kindern Pahath-Moab: Adna, Chelal, Benaja, Maeseja, Mathanja, Bezaleel, Benui und Manasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Unter den Kindern Harim: Elieser, Jesia, Malchias, Semaja, Simeon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluch und Semarja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Unter den Kindern Hasum: Mathnai, Mathatha, Sabad, Eliphelet, Jeremai, Manasse und Simei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Unter den Kindern Bani: Maedai, Amram, Huel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedja, Chelui,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Naja, Meremoth, Eliasib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mathanja, Mathnai, Jaesan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Benui, Simei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemja, Nathan, Adaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbai, Sasai, Sarai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asareel, Selemja, Samarja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja und Joseph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Unterden Kindern Nebo: Jeiel, Mathithja, Sabad, Sebina, Jaddai, Joel und Benaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Diese hatten alle fremde Weibergenommen; und waren etliche unter denselben Weibern, die Kinder getragen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Dies sind die Geschichten Nehemias, des Sohns Hachaljas. Es geschah im Monden Chisleu des zwanzigsten Jahrs, daß ich war zu Susan auf dem Schloli,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'da kam Hanani, einer meiner Bruder, mit etlichen Mannern aus Juda. Und ich fragte sie, wie es den Juden ginge, die errettet und ubrig waren von dem Gefangnis, und wie es zu Jerusalem ginge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Und sie sprachen zu mir: Die ubrigen von dem Gefangnis sind daselbst im Lande in groliem Ungluck und Schmach; die Mauern Jerusalems sind zerbrochen und ihre Tore mit Feuer verbrannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Da ich aber solche Worte horete, sali ich und weinete und trug Leid zween Tage; und fastete und betete vordem Gottvom Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'und sprach: Ach, HERR, Gottvom Himmel, grower und schrecklicher Gott, der da halt den Bund und Barmherzigkeit denen, die ihn lieben und seine Gebote halten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'laü doch deine Ohren aufmerken und deine Augen often sein, dafi du horest das Gebet deines Knechts, das ich nun vor dir bete Tag und Nacht fur die Kinder Israel, deine Knechte, und bekenne die Sunden der Kinder Israel, die wir an dir getan haben; und ich und meines Vaters Haus haben auch gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Wir sind verruckt worden, daß wir nicht gehaiten haben die Gebote, Befehle und Rechte, die du geboten hast deinem Knechte Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Gedenke aber doch des Worts, das du deinem Knechte Mose gebotest und sprachest: Wenn ihreuch vergreifet, so will ich euch unter die Volker streuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Wo ihr euch aber bekehret zu mir und haltet meine Gebote und tut sie, und ob ihr verstolien waret bis an der Himmel Ende, so will ich euch doch von dannen versammeln und will euch bringen an den Ort, den ich erwahlet habe, daß mein Name daselbst wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Sie sind doch ja deine Knechte und dein Volk, die du erloset hast durch deine groüe Kraft und machtige Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ach, HERR, laü deine Ohren aufmerken auf das Gebet deines Knechts und auf das Gebet deiner Knechte, die da begehren, deinen Namen zu furchten; und. lali deinem Knechte heute gelingen und gib ihm Barmherzigkeit vor diesem Manne! Denn ich war des Konigs Schenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Im Monden Nisan, des zwanzigsten Jahrs des Konigs Arthahsastha, da Wein vor ihm stund, hub ich den Wein auf und gab dem Konige; und ich sah trauriglich vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Da sprach der Konig zu mir: Warum siehest du so ubel? Du bist ja nicht krank? Das ist\'s nicht, sondern du bist schwermütig. Ich aber furchtete mich fast sehr');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'und sprach zum Konige: Der Konig lebe ewiglich! Sollte ich nicht ubel sehen? Die Stadt, da das Haus des Begrabnisses meiner Vater ist, liegt wüste und ihre Tore sind mit Feuer verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Da sprach der Konig zu mir: Was forderst du denn? Da bat ich den Gott vom Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'und sprach zum Konige: Gefallt es dem Konige und deinen Knechten vor dir, daß du mich sendest nach Juda zu der Stadt des Begrabnisses meiner Vater, dafj ich sie baue?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Und der Konig sprach zu mir und die Konigin, die neben ihm safi: Wie lange wird deine Reise wahren? und wann wirst du wiederkommen? Und es gefiel dem Konige, dafi er mich hinsendete. Und ich setzte ihm eine bestimmte Zeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'und sprach zum Konige: Gefallt es dem Konige, so gebe er mir Briefe an die Landpfleger jenseit des Wassers, daß sie mich hinubergeleiten, bis ich komme nach Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'und Briefe an Assaph, den Holzfursten des Konigs, dafi er mir Holz gebe zu Balken der Pforten am Palast, die im Hause und an der Stadtmauer sind, und zum Hause, da ich einziehen soil. Und der Konig gab mir nach der guten Hand meines Gottes uber mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Und da ich kam zu den Landpflegern jenseit des Wassers, gab ich ihnen des Konigs Briefe. Und der Konig sandte mit mir die Hauptleute und Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Da aber das horete Saneballat, der Horoniter, und Tobia, ein ammonitischer Knecht, verdroft es sie sehr, da(5 ein Mensch kommen ware, der Gutes suchte fur die Kinder Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Und da ich gen Jerusalem kam und drei Tage dagewesen war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'machte ich mich des Nachts auf und wenig Manner mit mir; denn ich sagte keinem Menschen, was mir mein Gott eingegeben hatte, zu tun an Jerusalem; und war kein Tier mit mir, ohne da ich auf ritt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Und ich ritt zum Taltoraus bei der Nacht, vor dem Drachenbrunnen und an das Misttor; und tat mir wehe, daß die Mauern Jerusalems zerrissen waren und die Tore mit Feuer verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Und ging hinuber zu dem Brunnentor und zu des Konigs Teich; und war da nicht Raum meinem Tier, daß es unter mir hatte gehen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Da zog ich bei Nacht den Bach hinan, und tat mir wehe, die Mauern also zu sehen; und kehrete urn und kam zum Taltorwieder heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Und die Obersten wuftten nicht, wo ich hinging, Oder was ich machte; denn ich hatte bis daher den Juden und den Priestern, den Ratsherren und den Obersten und den andern, die am Werk arbeiteten, nichts gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Und sprach zu ihnen: Ihrsehet das Ungluck, darinnen wirsind, daß Jerusalem wüste liegt, und ihre Tore sind mit Feuer verbrannt; kommt, laftt uns die Mauern Jerusalems bauen, daß wir nicht mehr eine Schmach seien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Und sagte ihnen an die Hand meines Gottes, die gut uber mir war, dazu die Worte des Konigs, die er mir geredet hatte. Und sie sprachen: So laftt uns auf sein! Und wir baueten, und ihre Hande wurden gestarkt zum Guten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Da aber das Saneballat, der Horoniter, und Tobia, der ammonitische Knecht, und Gosem, der Araber, horeten, spotteten sie unser und verachteten uns und sprachen: Was ist das, das ihr tut? Wollt ihr wieder von dem Konige abfallen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Da antwortete ich ihnen und sprach: Der Gott vom Himmel wird uns gelingen lassen; denn wir, seine Knechte, haben uns aufgemacht und bauen; ihr aber habt kein Teil noch Recht noch Gedachtnis in Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Und Eliasib, der Hohepriester, macht sich auf mit seinen Brudern, den Priestern, und baueten das Schaftor; sie heiligten es und setzten seine Türen ein; sie heiligten es aber bis an den Turm Mea, namlich bis an den Turm Hananeel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Neben ihm baueten die Manner von Jericho; auch bauete neben ihm Sachur, der Sohn Imris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Aber das Fischtor baueten die Kinder Senaa; sie deckten es und setzten seine Türen ein, Schlosser und Riegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Neben ihnen bauete Meremoth, der Sohn Urias, des Sohns Hakoz. Neben ihnen bauete Mesullam, der Sohn Berechjas, des Sohns Mesesabeels. Neben ihnen bauete Zadok, der Sohn Baenas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Neben ihnen baueten die von Thekoa, aber ihre Gewaltigen brachten ihren Hals nicht zum Dienst ihrer Herren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Das alte Tor bauete Jojada, der Sohn Passeahs, und Mesullam, der Sohn Besodjas; sie deckten es und setzten ein seine Türen und Schlosser und Riegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Neben ihnen baueten Melatja von Gibeon und Jadon von Merono, Manner von Gibeon und von Mizpa, am Stuhl des Landpflegers diesseit des Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Neben ihm bauete Usiel, der Sohn Harhajas, der Goldschmied. Neben ihm bauete Hananja, der Sohn der Apotheker; und sie baueten aus zu Jerusalem bis an die breite Mauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Neben ihm bauete Rephaja, der Sohn Hurs, der Oberste des halben Vierteils zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Neben ihm bauete Jedaja, der Sohn Harumaphs, gegen seinem Hause uber. Neben ihm bauete Hattus, der Sohn Hasabenjas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Aber Malchia, der Sohn Harims, und Hassub, der Sohn Pahath-Moabs, baueten zwei Stücke und den Turm bei dem Ofen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Neben ihm bauete Sallum der Sohn Halohes, der Oberste des halben Vierteils zu Jerusalem, er und seine Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Das Taltor bauete Hanun und die Burger von Sanoah; sie baueten es und setzten ein seine Turen, Schlosser und Riegel und tausend Ellen an der Mauer bis an das Misttor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Das Misttor aber bauete Malchia, der Sohn Rechabs, der Oberste des Vierteils der Weingartner; er bauete es und setzte ein seine Turen, Schlosser und Riegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Aber das Brunnentor bauete Sailum, der Sohn Chal-Hoses, der Oberste des Vierteils zu Mizpa; er bauete es und deckte es und setzte ein seine Turen, Schlosser und Riegel, dazu die Mauer am Teich Seloah bei dem Garten des Konigs bis an die Stufen, die von der Stadt Davids herabgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Nach ihm bauete Nehemia, der Sohn Asbuks, der Oberste des halben Vierteils zu Beth-Zur, bis gegen die Graber Davids uber und bis an den Teich Asuja und bis an das Haus der Helden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Nach ihm baueten die Leviten, Rehum, der Sohn Banis. Neben ihm bauete Hasabja, der Oberste des halben Vierteils zu Kegila, in seinem Vierteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Nach ihm baueten ihre Brüder Bavai, der Sohn Henadads, der Oberste des halben Vierteils zu Kegila.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Neben ihm bauete Eser, der Sohn Jesuas, der Oberste zu Mizpa, zwei Stucke den Winkel hinan gegen dem Harnischhause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Nach ihm auf dem Berge bauete Baruch, der Sohn Sabbais, zwei Stucke vom Winkel bis an die Haustur Eliasibs, des Hohenpriesters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Nach ihm bauete Meremoth, der Sohn Urias, des Sohns Hakoz, zwei Stucke von der Haustur Eliasibs bis ans Ende des Hauses Eliasibs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Nach ihm baueten die Priester, die Manner aus den Gegenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Nach dem bauete Benjamin und Hasub gegen ihrem Hause uber. Nach dem bauete Asarja, der Sohn Maesejas, des Sohns Ananjas, neben seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Nach ihm bauete Benui, der Sohn Henadads, zwei Stucke vom Hause Asarjas bis an den Winkel und bis an die Ecke;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, der Sohn Usais, gegen dem Winkel und dem hohen Turm, der vom Konigshause heraussiehet, bei dem Kerkerhofe. Nach ihm Pedaja, der Sohn Pareos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Die Nethinim aber wohneten an Ophel bis an das Wassertor gegen Morgen, da der Turm heraussiehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Nach dem, baueten die von Thekoa zwei Stucke gegen dem grofien Turm, der heraussiehet, und bis an die Mauer Ophel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Aber von dem Rofitor an baueten die Priester, ein jeglicher gegen seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Nach dem bauete Zadok, der Sohn Immers, gegen seinem Hause. Nach ihm bauete Semaja, der Sohn Sechanjas, der Torhuter, gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Nach ihm bauete Hananja, der Sohn Selemjas, und Hanun, der Sohn Zalaphs, der sechste, zwei Stucke. Nach ihm bauete Mesullam, der Sohn Berechjas, gegen seinem Kasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Nach ihm bauete Malchia, der Sohn des Goldschmieds, bis an das Haus der Nethinim und der Kramer, gegen dem Ratstor und bis an den Saal an der Ecke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Und zwischen dem Saal an der Ecke zum Schaftor baueten die Goldschmiede und die Kramer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 33, 'Da aber Saneballat horete, daß wir die Mauern baueten, ward er zornig und sehr entrustet; und spottete der Juden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 34, 'und sprach vor seinen Brudern und den Machtigen zu Samaria: Was machen die ohnmachtigen Juden? Wird man sie so lassen? Werden sie opfern? Werden sie es einen Tag vollenden? Werden sie die Steine lebendig machen, die Staubhaufen und verbrannt sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 35, 'Aber Tobia, der Ammoniter, neben ihm sprach: Lai J, sie nur bauen! Wenn Fuchse hinaufzogen, die zerrissen wohl ihre steinerne Mauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 36, 'Hore, unser Gott, wie verachtet sind wir! Kehre ihre Schmach auf ihren Kopf, dad du sie gebest in Verachtung im Lande ihres Gefangnisses!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 37, 'Decke ihre Missetat nicht zu und ihre Sünde vertilge nicht vor dir; denn sie haben die Bauleute gereizet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 38, 'Aber wir baueten die Mauern und fugten sie ganz aneinander bis an die halbe Hohe. Und das Volk gewann ein Herz zu arbeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Da aber Saneballat und Tobia und die Araber und Ammoniter und Asdoditer horeten, dad die Mauern zu Jerusalem zugemacht waren, und dad sie die Lucken angefangen hatten zu buden, wurden sie sehr zornig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Und machten allesamt einen Bund zu Haufen, dad sie kamen und stritten wider Jerusalem und machten drin einen Irrtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Wir aber beteten zu unserm Gott und stelleten Hut uber sie Tag und Nacht gegen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Und Juda sprach: Die Kraft der Trager istzu schwach, und des Staubs ist zu viel; wir konnen an der Mauer nicht bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Unsere Widersacher aber gedachten: Sie sollen\'s nicht wissen noch sehen, bis wir mitten unter sie kommen und sie erwürgen und das Werk hindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Da aber die Juden, die neben ihnen wohneten, kamen und sagten es uns wohl zehnmal, aus alien Orten, da sie urn uns wohneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'da stellete ich unten an die Orter hinter der Mauer in die Graben das Volk nach ihren Geschlechtern mit ihren Schwertern, Spielien und Bogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Und besah es und machte mich auf und sprach zu den Ratsherren und Obersten und dem andern Volk: Furchtet euch nicht vor ihnen! Gedenket an den grolien, schrecklichen HERRN und streitet fur eure Bruder, Sohne, Tochter, Weiber und Hauser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Da aber unsere Feinde horeten, daß es uns war kund worden, machte Gott ihren Rat zunichte. Und wir kehrten alle wieder zur Mauer; ein jeglicher zu seiner Arbeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Und es geschah hinfurder, daß der Junglinge die Halfte taten die Arbeit, die andere Halfte hielten Spiefie, Schilde, Bogen und Panzer; und die Obersten stunden hinter dem ganzen Hause Juda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'die da baueten an der Mauer und trugen Last von denen, die ihnen aufluden; mit einer Hand taten sie die Arbeit und mit der andern hielten sie die Waffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Und ein jeglicher, der da bauete, hattesein Schwert an seine Lenden gegurtet und bauete also; und der mit der Posaune blies, war neben mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Und ich sprach zu den Ratsherren und Obersten und zum andern Volk. Das Werk ist grofi und weit, und wirsind zerstreuet aufder Mauer, feme voneinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'An welchem Ort ihr nun die Posaune lauten horet, dahin versammelt euch zu uns. Unser Gott wird fur uns streiten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'so wollen wir am Werk arbeiten. Und ihre Halfte hielt die Spiefie von dem Aufgang der Morgenrote, bis die Sterne hervorkamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Auch sprach ich zu der Zeit zum Volk: Ein jeglicher bleibe mit seinem Knaben uber Nacht zu Jerusalem, daß wir des Nachts der Hut und des Tages der Arbeit warten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Aber ich und meine Bruder und meine Knaben und die Manner an der Hut hinter mir, wir zogen unsere Kleider nicht aus; ein jeglicher lieli das Baden anstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Und es erhub sich ein groli Geschrei des Volks und ihrer Weiber wider ihre Bruder, die Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Und waren etliche, die da sprachen: Unserer Sohne und Tochter sind viel; I a lit uns Getreide nehmen und essen, daß wir leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Aber etliche sprachen: Laüt uns unsere Acker, Weinberge und Hauser versetzen und Getreide nehmen in der Teurung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Etliche aber sprachen: Laüt uns Geld entlehnen auf Zinsen dem Konige auf unsere Acker und Weinberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Denn unserer Bruder Leib ist wie unser Leib und ihre Kinder wie unsere Kinder; sonstwurden wir unsere Sohne und Tochter unterwerfen dem Dienst, und sind schon unserer Tochter etliche unterworfen, und ist kein Vermogen in unsern Handen; auch würden unsere Acker und Weinberge der andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Da ich aber ihr Schreien und solche Worte horete, ward ich sehr zornig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Und mein Herz ward Rats mit mir, daß ich schalt die Ratsherren und die Obersten, und sprach zu ihnen: Wollt ihr einer auf den andern Wucher treiben? Und ich brachte eine groüe Gemeine wider sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'und sprach zu ihnen: Wir haben unsere Bruder, die Juden, erkauft, die den Heiden verkauft waren, nach unserm Vermogen; und ihr wollt auch eure Bruder verkaufen, die wir zu uns gekauft haben? Da schwiegen sie und fanden nichts zu antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Und ich sprach: Es ist nicht gut, das ihr tut. Solltet ihr nicht in der Furcht Gottes wandeln urn der Schmach willen der Heiden, unserer Feinde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Ich und meine Bruder und meine Knaben haben ihnen auch Geld getan und Getreide; den Wucher aber haben wir nachgelassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'So gebt ihnen nun heutigestages wieder ihre Acker, Weinberge, Olgarten und Hauser und den Hundertsten am Gelde, am Getreide, am Most und am Ole, das ihr an ihnen gewuchert habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Da sprachen sie: Wir wollen\'s wiedergeben und wollen nichts von ihnen fordern und wollen tun, wie du gesagt hast. Und ich rief den Priestern und nahm einen Eid von ihnen, daß sie also tun sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Auch schuttelte ich meinen Busen aus und sprach: Also schuttele Gott aus jedermann von seinem Hause und von seiner Arbeit, der dies Wort nicht handhabet, daß er sei ausgeschuttelt und leer. Und die ganze Gemeine sprach: Amen! und lobeten den HERRN. Und das Volk tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Auch von der Zeit an, da mirbefohlen ward, ein Landpfleger zu sein im Lande Juda, namlich vom zwanzigsten Jahr an bis in das zweiunddreilügste Jahr des Konigs Arthahsastha, das sind zwolf Jahre, nahrete ich mich und meine Bruder nicht von der Landpfleger Kost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Denn die vorigen Landpfleger, die vor mir gewesen waren, hatten das Volk beschweret und hatten von ihnen genommen Brot und Wein, dazu auch vierzig Sekel Silbers; auch hatten ihre Knaben mit Gewalt gefahren uber das Volk. Ich tat aber nicht also urn der Furcht Gottes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Auch arbeitete ich an der Mauer Arbeit und kaufte keinen Acker; und alle meine Knaben muliten daselbst an die Arbeit zuhauf kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Dazu waren der Juden und Obersten hundertundfunfzig an meinem Tische, die zu mir kommen waren aus den Heiden, die urn uns her sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Und man machte mir des Tages einen Ochsen und sechs erwahlte Schafe und Vogel und je inwendig zehn Tagen allerlei Wein die Menge. Noch forderte ich nicht der Landpfleger Kost, denn der Dienst war schwer auf dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Gedenke mir, mein Gott, zum besten alles, das ich diesem Volk getan habe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Und da Saneballat, Tobia und Gosem, der Araber, und andere unserer Feinde erfuhren, daß ich die Mauer gebauet hatte, und keine Lucke mehr dran ware, wiewohl ich die Turen zu der Zeit noch nicht gehanget hatte in den Toren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'sandte Saneballat und Gosem zu mir und lielien mir sagen: Komm und la(S uns zusammenkommen in den Dorfern, in der Flache Ono. Sie gedachten mir aber Boses zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Ich aber sandte Boten zu ihnen und lied ihn sagen: Ich habe ein graft Geschaft auszurichten, ich kann nicht hinabkommen; es mochte das Werk nachbleiben, wo ich die Hand abtate und zu euch hinabzoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Sie sandten aber wohl viermal zu mir auf die Weise, und ich antwortete ihnen auf diese Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Da sandte Saneballat zum funftenmal zu mir seinen Knaben mit einem offenen Briefe in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Darinnen war geschrieben: Es ist vor die Heiden kommen, und Gosem hat es gesagt, dad du und die Juden gedenket abzufallen, darum du die Mauer bauest, und du wollest ihr Konig sein in diesen Sachen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'und du habest dir Propheten bestellet, die von dir ausschreien sollen zu Jerusalem und sagen: Er ist der Konig Judas. Nun, solches wird vor den Konig kommen. So komm nun und lad uns miteinander ratschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Ich aber sandte zu ihm und lied ihm sagen: Solches ist nicht geschehen, das du sagest; du hast es aus deinem Herzen erdacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Denn sie alle wollten uns furchtsam machen und gedachten: Sie sollen die Hand abtun vom Geschafte, dad sie nicht arbeiten. Aber ich starkte desto mehr meine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Und ich kam ins Haus Semajas, des Sohns Delajas, des Sohns Mehetabeels; und er hatte sich verschlossen und sprach: Lad uns zusammenkommen im Hause Gottes mitten im Tempel und die Turen des Tempels zuschlieden; denn sie werden kommen, dich zu erwürgen, und werden bei der Nacht kommen, dad sie dich erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Ich aber sprach: Sollte ein solcher Mann fliehen? Sollte ein solcher Mann, wie ich bin, in den Tempel gehen, dad er lebendig bliebe? Ich will nicht hineingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Denn ich merkte, dad ihn Gott nicht gesandt hatte. Denn er sagte wohl Weissagung auf mich, aber Tobia und Saneballat hatten ihm Geld gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Darum nahm er Geld, auf dad ich mich furchten sollte und also tun und sundigen, dad sie ein bos Geschrei hatten, damit sie mich lastern mochten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Gedenke, mein Gott, des Tobia und Saneballat nach diesen seinen Werken; auch der Prophetin Noadja und der andern Propheten, die mich wollten abschrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Und die Mauer ward fertig am fünfundzwanzigsten Tage des Monden Elul, in zweiundfunfzig Tagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Und da alle unsere Feinde das horeten, furchteten sich alle Heiden, die urn uns her waren, und der Mut entfiel ihnen; denn sie merkten, dad dies Werk von Gott war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Auch zu derselben Zeit waren viel der Obersten Judas, deren Briefe gingen zu Tobia und von Tobia zu ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Denn ihrer waren viel in Juda, die ihm geschworen waren; denn er war ein Schwager Sachanjas, des Sohns Arahs, und sein Sohn Johanan hatte die Tochter Mesullams, des Sohns Berechjas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Und sagten Gutes von ihm vor mir und brachten meine Rede aus zu ihm. So sandte denn Tobia Briefe, mich abzuschrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Da wir nun die Mauer gebauet hatten, hangete ich die Turen; und wurden bestellet die Torhuter, Sanger und Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Und ich gebot meinem Bruder Hanani und Hananja, dem Palastvogt zu Jerusalem (denn er war ein treuer Mann und gottesfurchtig vor vielen andern),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'und sprach zu ihnen: Man soil die Tore zu Jerusalem nicht auftun, bis daß die Sonne heift wird; und wenn man noch arbeitet, soil man die Turen zuschlagen und verriegeln. Und es wurden Hüter bestellet aus den Burgern Jerusalems, ein jeglicher auf seine Hut und urn sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Die Stadt aber war weit von Raum und groli, aber wenig Volks drinnen, und die Hauser waren nicht gebauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Und mein Gott gab mir ins Herz, daß ich versammelte die Ratsherren und die Obersten und das Volk, sie zu rechnen. Und ich fand ein Register ihrer Rechnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'die vorhin heraufkommen waren aus dem Gefangnis, die Nebukadnezar, der Konig zu Babel, hatte weggefuhret, und zu Jerusalem wohneten und in Juda, ein jeglicher in seiner Stadt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'und waren kommen mit Serubabel, Jesua, Nehemia, Asarja, Raamja, Nahemani, Mardachai, Bilsan, Mispereth, Bigevai, Nehum und Baena. Dies ist die Zahl der Manner vom Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Der Kinder Pareos waren zweitausend hundert und zweiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'der Kinder Sephatja dreihundert und zweiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'der Kinder Arah sechshundert und zweiundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'der Kinder Pahath-Moab, unter den Kindern Jesua und Joab, zweitausend achthundertundachtzehn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'der Kinder Elam tausend zweihundert und vierundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'der Kinder Sathu achthundert und funfundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'der Kinder Sakai siebenhundert und sechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'der Kinder Benui sechshundert und achtundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'der Kinder Bebai sechshundert und achtundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'der Kinder Asgad zweitausend dreihundert und zweiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'der Kinder Adonikam sechshundert und siebenundsechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'der Kinder Bigevai zweitausend und siebenundsechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'der Kinder Adin sechshundert und funfundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'der Kinder Ater von Hiskia achtundneunzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'der Kinder Hasum dreihundert und achtundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'der Kinder Bezai dreihundert und vierundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'der Kinder Hariph hundert und zwolf;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'der Kinder Gibeon funfundneunzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'der Manner von Bethlehem und Netopha hundert und achtundachtzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'der Manner von Anathoth hundert und achtundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'der Manner von Beth-Asmaveth zweiundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'der Manner von Kiriath-Jearim, Kaphira und Beeroth siebenhundert und dreiundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'der Manner von Rama und Gaba sechshundert und einundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'der Manner von Michmas hundert und zweiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'der Manner von Bethel und Ai hundert und dreiundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'der Manner vom andern Nebo zweiundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'der Kinder des andern Elam tausend zweihundert und vierundfunfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'der Kinder Harim, dreihundert und zwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'der Kinder Jereho dreihundert und funfundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'der Kinder Lod, Hadid und Ono siebenhundert und einundzwanzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'der Kinder Senaa dreitausend neunhundert und dreiftig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Die Priester: Der Kinder Jedaja, vom Hause Jesua neunhundert und dreiundsiebenzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'der Kinder Immer tausend und zweiundfünfzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'der Kinder Pashur tausend zweihundert und siebenundvierzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'der Kinder Harim tausend und siebenzehn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Die Leviten: Der Kinder Jesua von Kadmiel, unter den Kindern Hodua, vierundsiebenzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Die Sanger: Der Kinder Assaph hundert und achtundvierzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Die Torhüterwaren: Die Kinder Sallum, die Kinder Ater, die Kinder Thalmon, die Kinder Akub, die Kinder Hatita, die Kinder Sobai, allesamt hundert und achtunddreifüg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Die Nethinim: Die Kinder Ziha, die Kinder Hasupha, die Kinder Tabaoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'die Kinder Keros, die Kinder Sia, die Kinder Pad on,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'die Kinder Libana, die Kinder Hagaba, die Kinder Salmai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'die Kinder Hanan, die Kinder Giddel, die Kinder Gahar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'die Kinder Reaja, die Kinder Rezin, die Kinder Nekoda,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'die Kinder Gasam, die Kinder Usa, die Kinder Passeah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'die Kinder Besai, die Kinder Megunim, die Kinder Nephussim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'die Kinder Bakbuk, die Kinder Hakupha, die Kinder Harhur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'die Kinder Bazlith, die Kinder Mehida, die Kinder Harsa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'die Kinder Barkos, die Kinder Sissera, die Kinder Thamah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'die Kinder Neziah, die Kinder Hatipha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Die Kinder der Knechte Salomos waren: Die Kinder Sotai, die Kinder Sophereth, die Kinder Prida,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'die Kinder Jaela, die Kinder Darkon, die Kinder Giddel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'die Kinder Sephatja, die Kinder Hatil, die Kinder Pochereth von Zebaim, die Kinder Amon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Aller Nethinim und Kinder der Knechte Salomos waren dreihundert und zweiundneunzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Und diese zogen auch mit herauf: Mithel, Melah, Thel-Harsa, Cherub-Addon und Immer; aber sie konnten nicht anzeigen ihrer Vater Haus noch ihren Samen, ob sie aus Israel waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Die Kinder Delaja, die Kinder Tobia und die Kinder Nekoda waren sechshundert und zweiundvierzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Und von den Priestern waren die Kinder Habaja, die Kinder Hakoz, die Kinder Barsillai, der aus den Tochtern Barsillais, des Gileaditers, ein Weib nahm, und ward nach derselben Namen genannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Diese suchten ihr Geburtsregister; und da sie es nicht fanden, wurden sie los vom Priestertum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Und Hathirsatha sprach zu ihnen, sie sollten nicht essen vom Allerheiligsten, bis daß ein Priester aufkame mit dem Licht und Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Der ganzen Gemeine wie ein Mann war zweiundvierzigtausend dreihundert und sechzig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'ausgenommen ihre Knechte und Magde, der waren siebentausend dreihundert und siebenunddreiftig; und hatten zweihundert und funfundvierzig Sanger und Sangerinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'siebenhundert und sechsunddreiftig Rosse, zweihundert und funfundvierzig Mauler,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'vierhundert und funfunddreiftig Kamele, sechstausend siebenhundert und zwanzig Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Und etliche der obersten Vater gaben zum Werke. Hathirsatha gab zum Schatz tausend Gulden, funfzig Becken, funfhundert und dreiftig Priesterrocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Und etliche oberste Vater gaben zum Schatz ans Werk zwanzigtausend Gulden, zweitausend und zweihundert Pfund Silbers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Und das andere Volk gab zwanzigtausend Gulden und zweitausend Pfund Silbers und siebenundsechzig Priesterrocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Und die Priester und die Leviten, die Torhuter, die Sanger und etliche des Volks und die Nethinim und ganz Israel setzten sich in ihre Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Da nun herzukam der siebente Mond, und die Kinder Israel in ihren Stadten waren, versammelte sich das ganze Volk wie ein Mann auf die breite Gasse vor dem Wassertor und sprachen zu Esra, dem Schriftgelehrten, daß er das Gesetzbuch Mose holete, das der HERR Israel geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Und Esra, der Priester, brachte das Gesetz vor die Gemeine, beide Manner und Weiber, und alle, die es vernehmen konnten, am ersten Tage des siebenten Monden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'und las drinnen auf der breiten Gasse, die vor dem Wassertor ist, von licht Morgen an bis auf den Mittag, vor Mann und Weib und wer es vernehmen konnte. Und des ganzen Volks Ohren waren zu dem Gesetzbuch gekehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Und Esra, der Schriftgelehrte, stund auf einem holzernen hohen Stuhl, den sie gemacht hatten zu predigen; und stund neben ihm Mathithja, Sema, Anaja, Uria, Hilkia und Maeseja zu seiner Rechten; aberzu seiner Linken Pedaja, Misael, Malchia, Hasum, Hasbadana, Sacharja und Mesullam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Und Esra tat das Buch auf vor dem ganzen Volk, denn er ragte uber alles Volk; und da er\'s auftat, stund alles Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Und Esra lobete den HERRN, den grolien Gott. Und alles Volk antwortete: Amen, Amen! mit ihren Handen empor; und neigeten sich und beteten den HERRN an mit dem Antlitz zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Und Jesua, Bani, Serebja, Jamin, Akub, Sabthai, Hodia, Maeseja, Klita, Asarja, Josabad, Hanan, Plaja und die Leviten machten das Volk, daß es aufs Gesetz merkete; und das Volk stund auf seiner Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Und sie lasen im Gesetzbuch Gottes klar und verstandlich, daß man\'s verstund, da man\'s las.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Und Nehemia, der da ist Hathirsatha, und Esra, der Priester, der Schriftgelehrte, und die Leviten, die das Volk aufmerken machten, sprachen zu allem Volk: Dieser Tag ist heilig dem HERRN, eurem Gott; darum seid nicht traurig und weinet nicht. Denn alles Volk weinete, da sie die Worte des Gesetzes horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Darum sprach erzu ihnen: Gehet hin und esset das Fette und trinket das Süüe; und sendet denen auch Teil, die nichts fur sich bereitet haben; denn dieser Tag ist heilig unserm HERRN; darum bekümmert euch nicht, denn die Freude am HERRN ist eure Starke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Und die Leviten stilleten alles Volk und sprachen: Seid stille, denn der Tag ist heilig; bekümmert euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Und alles Volk ging hin, daß es aüe, tranke und Teil sendete und eine groüe Freude machte; denn sie hatten die Worte verstanden, die man ihnen hatte kundgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Und des andern Tages versammelten sich die obersten Vater unter dem ganzen Volk und die Priester und Leviten zu Esra, dem Schriftgelehrten, daß er sie die Worte des Gesetzes unterrichtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Und sie fanden geschrieben im Gesetz, daü der HERR durch Mose geboten hatte, daü die Kinder Israel in Laubhutten wohnen sollten auf das Fest im siebenten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Und sie lielien es lautwerden und ausrufen in alien ihren Stadten und zu Jerusalem und sagen: Gehet hinaus auf die Berge und holet Olzweige, Balsamzweige, Myrtenzweige, Palmenzweige und Zweige von dichten Baumen, daü man Laubhutten mache, wie es geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Und das Volk ging hinaus und holeten und machten ihnen Laubhutten, ein jeglicher auf seinem Dach und in ihren Hofen und in den Hofen am Hause Gottes und auf der breiten Gasse am Wassertor und auf der breiten Gasse am Tor Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Und die ganze Gemeine derer, die aus dem Gefangnis waren wiederkommen, machten Laubhutten und wohneten drinnen. Denn die Kinder Israel hatten seit der Zeit Josuas, des Sohns Nuns, bis auf diesen Tag nicht also getan; und war eine sehr groüe Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Und ward im Gesetzbuch Gottes gelesen alle Tage, vom ersten Tage an bis auf den letzten, und hielten das Fest sieben Tage, und am achten Tage die Versammlung, wie sich’s gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Am vierundzwanzigsten Tage dieses Monden kamen die Kinder Israel zusammen mit Fasten und Sacken und Erde auf ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Und sonderten den Samen Israels von alien fremden Kindern und traten hin und bekannten ihre Sünden und ihrer Vater Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Und stunden auf an ihrer Statte; und man las im Gesetzbuch des HERRN, ihres Gottes, viermal des Tages; und sie bekannten und beteten an den HERRN, ihren Gott, viermal des Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Und die Leviten stunden auf in die Hohe, namlich Jesua, Bani, Kadmiel, Sebanja, Buni, Serebja, Bani und Chenani, und schrieen laut zu dem HERRN, ihrem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Und die Leviten, Jesua, Kadmiel, Bani, Hasabenja, Serebja, Hodia, Sebanja, Pethahja, sprachen: Stehet auf, lobet den HERRN, euren Gott, von Ewigkeit zu Ewigkeit; und man lobe den Namen deiner Herrlichkeit, der erhohet ist, mit allem Segen und Lobe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'HERR, du bist\'s allein; du hast gemacht den Himmel und alter Himmel Himmel mit all ihrem Heer, die Erde und alles, was drauf ist, die Meere und alles, was drinnen ist; du machest alles lebendig, und das himmlische Heer betet dich an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Du bist der HERR Gott, der du Abram erwahlet hast und ihn von Ur in Chaldaa ausgeführt und Abraham genannt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'und sein Herz treu vor dir funden und einen Bund mit ihm gemacht, seinem Samen zu geben das Land der Kanaaniter, Hethiter, Amoriter, Pheresiter, Jebusiter und Girgositer; und hast dein Wort gehalten, denn du bist gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Und du hast angesehen das Elend unserer Vater in Agypten und ihr Schreien erhoret am Schilfmeer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'und Zeichen und Wunder getan an Pharao und an alien seinen Knechten und an allem Volk seines Landes; denn du erkanntest, daß sie stolz wider sie waren; und hast dir einen Namen gemacht, wie es heute gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Und hast das Meer vor ihnen zerrissen, daß sie mitten im Meer trocken hindurchgingen, und ihre Verfolger in die Tiefe verworfen, wie Steine in machtigen Wassern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'und sie gefuhret des Tages in einer Wolkensaule und des Nachts in einer Feuersaule, ihnen zu leuchten auf dem Wege, den sie zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Und bist herabgestiegen auf den Berg Sinai und hast mit ihnen vom Himmel geredet und gegeben ein wahrhaftig Recht und ein recht Gesetz und gute Gebote und Sitten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'und deinen heiligen Sabbat ihnen kundgetan; und Gebote, Sitten und Gesetze ihnen geboten durch deinen Knecht Mose;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'und ihnen Brot vom Himmel gegeben, da sie hungerte, und Wasser aus dem Felsen lassen gehen, da sie durstete; und ihnen geredet, sie sollten hineingehen und das Land einnehmen, daruber du deine Hand hubest, ihnen zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Aber unsere Vater wurden stolz und halsstarrig, daß sie deinen Geboten nicht gehorchten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'und weigerten sich zu horen, und gedachten auch nicht an deine Wunder, die du an ihnen tatest, sondern sie wurden halsstarrig und warfen ein Haupt auf, da($ sie sich wendeten zu ihrer Dienstbarkeit in ihrer Ungeduld. Aber du, mein Gott, vergabest und warest gnadig, barmherzig, geduldig und von grolter Barmherzigkeit und verlieftest sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Und ob sie wohl ein gegossen Kalb machten und sprachen: Das ist dein Gott, der dich aus Agyptenland gefuhret hat, und taten grofte Lasterungen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'noch verlieftest du sie nicht in der Wuste nach deiner groften Barmherzigkeit, und die Wolkensaule wich nicht von ihnen des Tages, sie zu fuhren auf dem Wege, noch die Feuersaule des Nachts, ihnen zu leuchten auf dem Wege, den sie zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Und du gabest ihnen deinen guten Geist, sie zu unterweisen; und dein Man wandtest du nicht von ihrem Munde; und gabest ihnen Wasser, da sie durstete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Vierzig Jahre versorgtest du sie in der Wuste, daß ihnen nichts mangelte. Ihre Kleider veralteten nicht, und ihre Fufte zerschwollen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Und gabest ihnen Konigreiche und Volker und teiltest sie hie und daher, daß sie einnahmen das Land Sihons, des Konigs zu Hesbon und das Land Ogs, des Konigs in Basan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Und vermehrtest ihre Kinder wie die Sterne am Himmel und brachtest sie ins Land, das du ihren Vatern geredet hattest, daß sie einziehen und es einnehmen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Und die Kinder zogen hinein und nahmen das Land ein. Und du demutigtest vor ihnen die Einwohner des Landes, die Kanaaniter, und gabest sie in ihre Hande, und ihre Konige und Volker im Lande, daß sie mit ihnen taten nach ihrem Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Und sie gewannen feste Stadte und ein fett Land und nahmen Hauser ein, voll allerlei Guter, ausgehauene Brunnen, Weinberge, Olgarten und Baume, davon man isset, die Menge; und alien und wurden satt und fett und lebten in Wollust durch deine grofte Gute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Aber sie wurden ungehorsam und widerstrebten dir und warfen dein Gesetz hinter sich zuruck; und erwurgeten deine Propheten, die sie bezeugten, daß sie sollten sich zu dir bekehren; und taten grofte Lasterungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Darum gabest du sie in die Hand ihrer Feinde, die sie angsteten. Und zur Zeit ihrer Angst schrieen sie zu dir; und du erhoretest sie vom Himmel, und durch deine grofte Barmherzigkeit gabest du ihnen Heilande, die ihnen halfen aus ihrer Feinde Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Wenn sie aber zur Ruhe kamen, verkehreten sie sich, ubel zu tun vor dir. So verlieftest du sie in ihrer Feinde Hand, daß sie uber sie herrscheten. So bekehreten sie sich dann und schrieen zu dir; und du erhoretest sie vom Himmel und errettetest sie nach deiner groften Barmherzigkeit vielmal');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'und lieftest sie bezeugen, daß sie sich bekehren sollten zu deinem Gesetz. Aber sie waren stolz und gehorchten deinen Geboten nicht; und sundigten an deinen Rechten (welche so ein Mensch tut, lebet er darinnen) und wandten ihre Schulterweg und wurden halsstarrig und gehorchten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Und du hieltest viele Jahre über ihnen und lieftest sie bezeugen durch deinen Geist in deinen Propheten; aber sie nahmen\'s nicht zu Ohren. Darum hast du sie gegeben in die Hand der Volker in Landern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Aber nach deiner groften Barmherzigkeit hast du es nicht gar aus mit ihnen gemacht noch sie verlassen; denn du bist ein gnadiger und barmherziger Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nun, unser Gott, du grafter Gott, machtig und schrecklich, derdu haltst Bund und Barmherzigkeit, achte nicht gering alle die Muhe, die uns getroffen hat und unsere Konige, Fursten, Priester, Propheten, Vater und dein ganzes Volk von der Zeit an der Konige zu Assur bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Du bist gerecht an allem, das du uber uns gebracht hast; denn du hast recht getan; wir aber sind gottlos gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Und unsere Konige, Fursten, Priester und Vater haben nicht nach deinem Gesetz getan und nicht acht gehabt auf deine Gebote und Zeugnisse, die du ihnen hast lassen zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Und sie haben dir nicht gedienet in ihrem Konigreich und in deinen groüen Gutern, die du ihnen gabest, und in dem weiten und fetten Lande, das du ihnen dargelegt hast, und haben sich nicht bekehret von ihrem bosen Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Siehe, wir sind heutigestages Knechte; und im Lande, das du unsern Vatern gegeben hast, zu essen seine Fruchte und Guter, siehe, da sind wir Knechte innen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Und sein Einkommen mehret sich den Konigen, die du uber uns gesetzt hast, um unserer Sünden willen; und sie herrschen uber unsere Leiber und Vieh nach ihrem Willen, und wir sind in grofier Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Und in diesem allem machen wireinen festen Bund und schreiben und lassen\'s unsere Fursten, Leviten und Priester versiegeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Die Versiegeler aber waren: Nehemia- Hathirsatha, der Sohn Hachaljas, und Zidekia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Seraja, Asarja, Jeremia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Pashur, Amarja, Malchia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Hattus, Sebanja, Mailuch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Harim, Meremoth, Obadja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Daniel, Ginthon, Baruch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Mesullam, Abia, Mejamin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Maasja, Bilgai und Semaja; das waren die Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Die Leviten aber waren: Jesua, der Sohn Asanjas, Binui unter den Kindern Henadads, Kadmiel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'und ihre Brüder: Sechanja, Hodia, Klita, Plaja, Hanan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Micha, Rehob, Hasabja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Sachur, Serebja, Sebanja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Hodia, Bani und Beninu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Die Haupter im Volk waren: Pareos, Pahath-Moab, Elam, Sathu, Bani,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Buni, Asgad, Bebai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Adonia, Bigvai, Adin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Ater, Hiskia, Asur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hodia, Hasum, Bezai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Hariph, Anathoth, Neubai,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Magpias, Mesullam, Hesir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Mesesabeel, Zadok, Jaddua,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Platja, Hanan, Anaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Hosea, Hananja, Hasub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Halohes, Pilha, Sobek,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Rehum, Hasabna, Maeseja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Ahia, Hanan, Anan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Mailuch, Harim und Baena.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Und das andere Volk, Priester, Leviten, Torhüter, Sanger, Nethinim und alle, die sich von den Vdlkern in Landen gesondert hatten zum Gesetz Gottes, samt ihren Weibern, Sohnen und Tochtern, alle, die es verstehen konnten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'und ihre Machtigen nahmen\'s an fur ihre Bruder. Und sie kamen, dafi sie schwuren und sich mit Eide verpflichteten, zu wandeln im Gesetz Gottes, das durch Mose, den Knecht Gottes, gegeben ist, dafi sie hielten und tun wollten nach alien Geboten, Rechten und Sitten des HERRN, unsers Herrschers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'und dafi wir den Volkern im Lande unsere Tochter nicht geben, noch ihre Tochter unsern Sohnen nehmen wollten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'auch wenn die Volker im Lande am Sabbattage bringen Ware und allerlei Futterung zu verkaufen, dafi wir\'s nicht von ihnen nehmen wollten auf den Sabbat und heiligen Tagen; und daß wir das siebente Jahr allerhand Beschwerung frei lassen wollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Und legten ein Gebot auf uns, dafi wir jahrlich einen dritten Teil eines Sekels gaben zum Dienst im Hause unsers Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'namlich zu Schaubrot, zu taglichem Speisopfer, zu taglichem Brandopfer des Sabbats, der Neumonden und Festtage und zu dem Geheiligten und zu Sundopfer, damit Israel versohnet werde, und zu allem Geschafte im Hause unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Und wirwarfen das Los unter den Priestern, Leviten und dem Volk um das Opfer des Holzes, das man zum Hause unsers Gottes bringen sollte jahrlich, nach den Hausern unserer Vater, auf bestimmte Zeit, zu brennen auf dem Altar des HERRN, unsers Gottes, wie es im Gesetz geschrieben stehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'und jahrlich zu bringen die Erstlinge unsers Landes und die Erstlinge alter Fruchte auf alien Baumen zum Hause des HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'und die Erstlinge unserer Sohne und unsers Viehes, wie es im Gesetz geschrieben stehet, und die Erstlinge unserer Rinder und unserer Schafe; daß wir das alles zum Hause unsers Gottes bringen sollen den Priestern, die im Hause unsers Gottes dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Auch sollen wir bringen die Erstlinge unsers Teiges und unserer Hebe und die Fruchte allerlei Baume, Most und Ol den Priestern in die Kasten am Hause unsers Gottes und den Zehnten unsers Landes den Leviten, daß die Leviten den Zehnten haben in alien Stadten unsers Ackerwerks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Und der Priester, der Sohn Aarons, soil mit den Leviten auch an dem Zehnten der Leviten haben, daß die Leviten den Zehnten ihrer Zehnten heraufbringen zum Hause unsers Gottes in die Kasten im Schatzhause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 40, 'Denn die Kinder Israel und die Kinder Levi sollen die Hebe des Getreides, Mosts und Ols herauf in die Kasten bringen. Daselbst sind die Gefalie des Heiligtums und die Priester, die da dienen, und die Torhuter und Sanger, daß wir das Haus unsers Gottes nicht verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Und die Obersten des Volks wohneten zu Jerusalem. Das andere Volk aber warfen das Los darum, da(5 unter zehn ein Teil gen Jerusalem in die heilige Stadt zogen, zu wohnen, und neun Teile in den Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Und das Volk segnete alle die Manner, die freiwillig waren, zu Jerusalem zu wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Dies sind die Haupter in der Landschaft, die zu Jerusalem wohneten. In den Stadten Judas aber wohnete ein jeglicher in seinem Gut, das in ihren Stadten war, namlich Israel, Priester, Leviten, Nethinim und die Kinder der Knechte Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Und zu Jerusalem wohneten etliche der Kinder Juda und Benjamin. Von den Kindern Juda: Athaja, der Sohn Usias, des Sohns Sacharjas, des Sohns Amarjas, des Sohns Sephatjas, des Sohns Mahelaleels, aus den Kindern Parez;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'und Maeseja, der Sohn Baruchs, des Sohns Chal-Hoses, des Sohns Hasajas, des Sohns Adajas, des Sohns Jojaribs, des Sohns Sacharjas, des Sohns Silonis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Aller Kinder Parez, die zu Jerusalem wohneten, waren vierhundertundachtundsechzig, redliche Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Dies sind die Kinder Benjamin: Sallu, der Sohn Mesullams, des Sohns Joeds, des Sohns Pedajas, des Sohns Kolajahs, des Sohns Maesejas, des Sohns Ithiels, des Sohns Jesaias;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'und nach ihm Gabai, Sallai, neunhundertundachtundzwanzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Und Joel, der Sohn Sichris, war ihr Vorsteher, und Juda, der Sohn Hasnuas, uber das andere Teil der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Von den Priestern wohneten Jedaja, der Sohn Jojaribs, Jachin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, der Sohn Hilkias, des Sohns Mesullams, des Sohns Zadoks, des Sohns Merajoth, des Sohns Ahitobs, war Fürst im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Und seine Bruder, die im Hause schafften, der waren achthundertundzweiundzwanzig. Und Adaja, der Sohn Jerohams, des Sohns Plaljas, des Sohns Amzis, des Sohns Sacharjas, des Sohns Pashurs, des Sohns Malchias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'und seine Bruder, Obersten unter den Vatern, waren zweihundertundzweiundvierzig. Und Amassai, der Sohn Asareels, des Sohns Ahusais, des Sohns Mesillemoths, des Sohns Immers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'und seine Bruder, gewaltige Leute, waren hundertundachtundzwanzig. Und ihr Vorsteher war Sabdiel, der Sohn Gedolims.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Von den Leviten: Semaja, der Sohn Hasubs, des Sohns Asrikams, des Sohns Hasabjas, des Sohns Bunnis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'und Sabthai und Josabad aus der Leviten Obersten an den aufierlichen Geschaften im Hause Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'und Mathanja, der Sohn Michas, des Sohns Sabdis, des Sohns Assaphs, der das Haupt war, Dank anzuheben zum Gebet, und Bakbukja, der andere unter seinen Brudern, und Abda, der Sohn Sammuas, des Sohns Galals, des Sohns Jedithuns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Aller Leviten in der heiligen Stadt waren zweihundertundvierundachtzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Und die Torhuter, Akub und Talmon und ihre Bruder, die in den Toren huteten, waren hundertundzweiundsiebenzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Das andere Israel aber, Priester und Leviten, waren in alien Stadten Judas, ein jeglicher in seinem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Und die Nethinim wohneten an Ophel. Und Ziha und Gispa gehorten zu den Nethinim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Der Vorsteher aber uber die Leviten zu Jerusalem war Usi, der Sohn Banis, des Sohns Hasabjas, des Sohns Mathanjas, des Sohns Michas. Aus den Kindern Assaphs waren Sanger urn das Geschaft im Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Denn es war des Konigs Gebot uber sie, daß die Sanger treulich handelten, einen jeglichen Tag seine Gebühr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Und Pethahja, der Sohn Mesesabeels, aus den Kindern Serahs, des Sohns Judas, war Befehlshaber des Konigs zu alien Geschaften an das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Und der Kinder Juda, die auften auf den Dorfern auf ihrem Lande waren, wohneten etliche zu Kiriath-Arba und in ihren Tochtem und zu Dibon und in ihren Tochtem und zu Kabzeel und in ihren Dorfern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'und zu Jesua, Molada, Beth-Palet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Hazar-Sual, Berseba und ihren Tochtern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'und zu Ziklag und Mochona und ihren Tochtern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'und zu En-Rimmon, Zarega, Jeremuth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Sanoah, Adullam und ihren Dorfern, zu Lachis und auf ihrem Felde, zu Aseka und in ihren Tochtern. Und lagerten sich von Berseba an bis ans Tal Hinnom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Die Kinder Benjamin aber von Gaba wohneten zu Michmas, Aja, Bethel und ihren Tochtern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'und zu Anathoth, Nob, Ananja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Rama, Githaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadid, Ziboim, Neballat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lod, Ono und im Zimmertal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Und etliche Leviten, die Teil in Juda hatten, wohneten unter Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Dies sind die Priester und Leviten, die mit Serubabel, dem Sohn Sealthiels, und Jesua heraufzogen: Seraja, Jeremia, Esra,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluch, Hattus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechanja, Rehum, Meremoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginthoi, Abia,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mejamin, Maadja, Bilga,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkia und Jedaja. Dies waren die Haupter unter den Priestern und ihren Brudern zu den Zeiten Jesuas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Die Leviten aber waren diese: Jesua, Benui, Kadmiel, Serebja, Juda und Mathanja, uber das Dankamt, er und seine Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Bakbukja und Unni, ihre Bruder, waren urn sie zur Hut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua zeugete Jojakim, Jojakim zeugete Eliasib, Eliasib zeugete Jojada.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada zeugete Jonathan, Jonathan zeugete Jaddua.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Und zu den Zeiten Jojakims waren diese oberste Vater unter den Priestern: namlich von Seraja war Meraja; von Jeremia war Hananja;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'von Esra war Mesullam; von Amarja war Johanan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'von Malluch war Jonathan; von Sebanja war Joseph;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'von Harim war Adna; von Merajoth war Helkai;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'von Iddo war Sacharja; von Ginthon war Mesullam');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'von Abia war Sichri; von Mejamin-Moadja war Piltai;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'von Bilga war Sammua; von Semaja war Jonathan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'von Jojarib war Mathnai; von Jedaja war Usi;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'von Sallai war Kallai; von Amok war Eber;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'von Hilkia war Hasabja; von Jedaja war Nethaneel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Und zu den Zeiten Eliasibs, Jojadas, Johanans und Jadduas wurden die obersten Vater unter den Leviten und die Priester beschrieben unter dem Konigreich Darü, des Persers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Es wurden aber die Kinder Levi, die obersten Vater, beschrieben in die Chronik bis zur Zeit Johanans, des Sohns Eliasibs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Und dies waren die Obersten unter den Leviten: Hasabja, Serebja und Jesua, der Sohn Kadmiels, und ihre Bruder neben ihnen, zu loben und zu danken, wie es David, der Mann Gottes, geboten hatte, eine Hut urn die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mathanja, Bakbukja, Obadja, Mesulam, Talmon und Akub waren Torhuter an der Hut, an den Schwellen in den Toren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Diese waren zu den Zeiten Jojakims, des Sohns Jesuas, des Sohns Jozadaks, und zu den Zeiten Nehemias, des Landpflegers, und des Priesters Esra, des Schriftgelehrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Und in der Einweihung der Mauern zu Jerusalem suchte man die Leviten aus alien ihren Orten, daß man sie gen Jerusalem brachte, zu halten Einweihung in Freuden mit Danken, mit Singen, Zimbeln, Psaltern und Harfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Und es versammelten sich die Kinder der Sanger und von der Gegend urn Jerusalem her und von den Hofen Netophathis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'und vom Hause Gilgal und von den Ackern zu Gibea und Asmaveth; denn die Sanger hatten ihnen Hdfe gebauet urn Jerusalem her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Und die Priester und Leviten reinigten sich und reinigten das Volk, die Tore und die Mauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Und ich liefi die Fursten Judas oben auf die Mauer steigen und bestellete zween große Dankchore, die gingen hin zur Rechten oben auf die Mauer zum Misttor warts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Und ihnen ging nach Hosaja und die Halfte der Fursten Judas');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'und Asarja, Esra, Mesullam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Semaja und Jeremia');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'und etliche der Priesterkinder mit Trommeten: namlich Sacharja, der Sohn Jonathans, des Sohns Semajas, des Sohns Mathanjas, des Sohns Michajas, des Sohns Sachurs, des Sohns Assaphs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'und seine Bruder, Semaja, Asareel, Milalai, Gilalai, Maai, Nethaneel und Juda, Hanani, mit den Saitenspielen Davids, des Mannes Gottes; Esra aber, der Schriftgelehrte, vor ihnen her,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'zum Brunnentor warts. Und gingen neben ihnen auf den Stufen zur Stadt Davids, die Mauer hinauf zu dem Hause Davids hinan, bis an das Wassertor gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Der andere Dankchorging gegen ihnen uber, und ich ihm nach, und die Halfte des Volks die Mauer hinan zum Ofenturm hinauf, bis an die breite Mauer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'und zum Tor Ephraim hinan und zum alten Tor und zum Fischtor und zum Turm Hananeel und zum Turm Mea bis an das Schaftor, und blieben stehen im Kerkertor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Und stunden also die zween Dankchore im Hause Gottes, und ich und die Halfte der Obersten mit mir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'und die Priester, namlich Eljakim, Maeseja, Minjamin, Michaja, Elioenai, Sacharja, Hananja mit Trommeten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'und Maeseja, Semaja, Eleasar, Usi, Johanan, Malchia, Elam und Asar. Und die Sanger sangen laut, und Jesrahja war der Vorsteher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Und es wurden desselben Tages große Opfer geopfert, und waren frohlich; denn Gott hatte ihnen eine große Freude gemacht, daß sich beide Weiber und Kinder freueten; und man horete die Freude Jerusalems feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Zu der Zeit wurden verordnet Manner uber die Schatzkasten, da die Heben, Erstlinge und Zehnten innen waren, daß sie sammeln sollten von den Ackern und urn die Stadte, auszuteilen nach dem Gesetz fur die Priester und Leviten; denn Juda hatte eine Freude an den Priestern und Leviten, daß sie stunden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'und warteten der Hut ihres Gottes und der Hut der Reinigung. Und die Sanger und Torhuter stunden nach dem Gebot Davids und seines Sohns Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Denn zu den Zeiten Davids und Assaphs wurden gestiftet die obersten Sanger und Loblieder und Dank zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Aber ganz Israel gab den Sangern und Torhutern Teil zu den Zeiten Serubabels und Nehemias, einen jeglichen Tag sein Teil; und sie gaben Geheiligtes fur die Leviten, die Leviten aber gaben Geheiligtes fur die Kinder Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Und es ward zu der Zeit gelesen das Buch Mose vor den Ohren des Volks; und ward funden drinnen geschrieben, daß die Ammoniter und Moabiter sollen nimmermehr in die Gemeine Gottes kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'darum daß sie den Kindern Israel nicht zuvorkamen mit Brot und Wasser und dingeten wider sie Bileam, daß er sie verfluchen sollte; aber unser Gott wandte den Fluch in einen Segen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Da sie nun dies Gesetz horeten, schieden sie alle Fremdlinge von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Und vor dem hatte der Priester Eliasib in den Kasten am Hause unsers Gottes geleget das Opfer Tobias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Denn er hatte ihm einen grolien Kasten gemacht; und dahin hatten sie zuvor gelegt Speisopfer, Weihrauch, Gerate und die Zehnten vom Getreide, Most und 01 nach dem Gebot der Leviten, Sanger und Torhuter, dazu die FHebe der Priester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Aber in diesem allem war ich nicht zu Jerusalem. Denn im zweiunddreilügsten Jahr Arthahsasthas, des Konigs zu Babel, kam ich zum Konige, und nach etlichen Tagen erwarb ich vom Konige,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'daß ich gen Jerusalem zog. Und ich merkte, daß nicht gut war, das Eliasib an Tobia getan hatte, daß er ihm einen Kasten machte im Hofe am Hause Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Und verdroli mich sehr und warf alle Gerate vom Hause Tobias hinaus vor den Kasten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'und hieli, daß sie die Kasten reinigten; und ich brachte wieder daselbst hin das Gerat des Hauses Gottes, das Speisopfer und Weihrauch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Und ich erfuhr, daß der Leviten Teil ihnen nicht gegeben war, derhalben die Leviten und Sanger geflohen waren, ein jeglicher zu seinem Acker, zu arbeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Da schalt ich die Obersten und sprach: Warum verlassen wir das Haus Gottes? Aber ich versammelte sie und stellete sie an ihre Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Da brachte ganz Juda die Zehnten vom Getreide, Most und 01 zum Schatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Und ich setzte über die Schatze Selemja, den Priester, und Zadok, den Schriftgelehrten, und aus den Leviten Pedaja, und unter ihre Hand Hanan, den Sohn Sachurs, des Sohns Mathanjas; denn sie wurden furtreu gehalten, und ihnen ward befohlen, ihren Brudern auszuteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Gedenke, mein Gott, mir daran und tilge nicht aus meine Barmherzigkeit, die ich an meines Gottes Hause und an seiner Hut getan habe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Zur selben Zeit sah ich in Juda Kelter treten auf den Sabbat und Garben hereinbringen und Esel beladen mit Wein, Trauben, Feigen und allerlei Last zu Jerusalem bringen auf den Sabbattag. Und ich bezeugte sie des Tages, da sie die Futterung verkauften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Eswohneten auch Tyrer drinnen; die brachten Fische und allerlei Ware und verkauften es auf den Sabbat den Kindern Judas und Jerusalems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Da schalt ich die Obersten in Juda und sprach zu ihnen: Was ist das fur ein boses Ding, das ihr tut, und brechet den Sabbattag?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Taten nicht unsere Vater also, und unser Gott führete all dieses Unglück über uns und fiber diese Stadt? Und ihr machet des Zorns fiber Israel noch mehr, daß ihr den Sabbat brechet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Und da die Tore zu Jerusalem aufgezogen waren vor dem Sabbat, hieli ich die Türen zuschlielien und befahl, man sollte sie nicht auftun bis nach dem Sabbat. Und ich bestellete meiner Knaben etliche an die Tore, daß man keine Last hereinbrachte am Sabbattage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Da blieben die Kramer und Verkaufer mit allerlei Ware über Nacht draulien vor Jerusalem, einmal oderzwei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Da zeugete ich ihnen und sprach zu ihnen: Warum bleibet ihr über Nacht urn die Mauer? Werdet ihr es noch einmal tun, so will ich die Hand an euch legen. Von der Zeit an kamen sie des Sabbats nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Und ich sprach zu den Leviten, die rein waren, daß sie kamen und hüteten der Tore, zu heiligen den Sabbattag. Mein Gott, gedenke mir des auch und schone mein nach deiner grolien Barmherzigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Ich sah auch zu der Zeit Juden, die Weiber nahmen von Asdod, Ammon und Moab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Und ihre Kinder redeten die Halfte asdodisch und konnten nicht judisch reden, sondern nach der Sprache eines jeglichen Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Und ich schalt sie und fluchte ihnen; und schlug etliche Manner und raufte sie; und nahm einen Eid von ihnen bei Gott: Ihr sollt eure Tochter nicht geben ihren Sohnen, noch ihre Tochter nehmen euren Sohnen, Oder euch selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Hat nicht Salomo, der Konig Israels, daran gesundiget? Und war doch in vielen Heiden kein Konig ihm gleich, und er war seinem Gott lieb, und Gott setzte ihn zum Konige über ganz Israel; dennoch machten ihn die auslandischen Weiber zu sündigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Habt ihr das nicht gehoret, daß ihr solch groli Ubel tut, euch an unserm Gott zu vergreifen und auslandische Weiber zu nehmen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Und einer aus den Kindern Jojadas, des Sohns Eliasibs, des Hohenpriesters, hatte sich befreundet mit Saneballat, dem Horoniten; aber ich jagte ihn von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Gedenk an sie, mein Gott, die des Priestertums los sind worden und des Bundes des Priestertums und der Leviten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Also reinigte ich sie von alien Auslandischen und stellete die Hut der Priester und Leviten, einen jeglichen nach seinem Geschafte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'und zu opfern das Holz zu bestimmten Zeiten und die Erstünge. Gedenke meiner, mein Gott, im Besten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Zu den Zeiten Ahasveros, der da Konig war von Indien bis an die Mohren, über hundertundsiebenundzwanzig Lander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'und da er auf seinem koniglichen Stuhl saß zu Schloß Susan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'im dritten Jahr seines Konigreichs, machte er bei ihm ein Mahl alien seinen Fursten und Knechten, namlich den Gewaltigen in Persien und Medien, den Landpflegern und Obersten in seinen Landern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'daß er sehen ließe den herrlichen Reichtum seines Konigreichs und die kostliche Pracht seiner Majestat viel Tage lang, namlich hundertundachtzig Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Und da die Tage aus waren, machte der Konig ein Mahl allem Volk, das zu Schloß Susan war, beide Großen und Kleinen, sieben Tage lang im Hofe des Gartens am Hause des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Da hingen weiße, rote und gelbe Tucher, mit leinenen und scharlakenen Seilen gefasset in silbernen Ringen auf Marmelsaulen. Die Banke waren gulden und silbern, auf Pflastervon grunen, weißen, gelben und schwarzen Marmeln gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Und das Getrank trug man in guldenen Gefaßen, und immer andern und andern Gefaßen, und koniglichen Wein die Menge, wie denn der Konig vermochte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Und man setzte niemand, was ertrinken sollte; denn der Konig hatte alien Vorstehern in seinem Hause befohlen, daß ein jeglicher sollte tun, wie es ihm wohlgefiele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Und die Konigin Vasthi machte auch ein Mahl fur die Weiber im koniglichen Hause des Konigs Ahasveros.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Und am siebenten Tage, da der Konig gutes Muts war vom Wein, hieß er Mehuman, Bistha, Harbona, Bigtha, Abagtha, Sethar und Charkas, die sieben Kammerer, die vor dem Konige Ahasveros dieneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'daß sie die Konigin Vasthi holeten vor den Konig mit der koniglichen Krone, daß er den Volkern und Fursten zeigete ihre Schone; denn sie war schon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Aberdie Konigin Vasthi wollte nicht kommen nach dem Wort des Konigs durch seine Kammerer. Da ward der Konig sehr zornig, und sein Grimm entbrannte in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Und der Konig sprach zu den Weisen, die sich auf Landes Sitten verstunden (denn des Konigs Sachen mußten geschehen vor alien Verstandigen auf Recht und Handel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'die Nachsten aber bei ihm waren Charsena, Sethar, Admatha, Tharsis, Meres, Marsena und Memuchan, die sieben Fursten der Perser und Meder, die das Angesicht des Konigs sahen und saßen obenan im Konigreich),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'was fur ein Recht man an der Konigin Vasthi tun sollte, darum daß sie nicht getan hatte nach dem Wort des Konigs durch seine Kammerer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Da sprach Memuchan vordem Konige und Fursten: Die Konigin Vasthi hat nicht allein an dem Konige ubel getan, sondern auch an alien Fursten und an alien Volkern in alien Landen des Konigs Ahasveros.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Denn eswird solche Tat der Konigin auskommen zu alien Weibern, daß sie ihre Manner verachten vor ihren Augen und werden sagen: Der Konig Ahasveros hiefi die Konigin Vasthi vor sich kommen; aber sie wollte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'So werden nun die Fürstinnen in Persien und Medien auch so sagen zu alien Fursten des Konigs, wenn sie solche Tat der Konigin horen; so wird sich Verachtens und Zorns genug heben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Gefallt es dem Konige, so lasse man ein koniglich Gebot von ihm ausgehen und schreiben nach der Perser und Meder Gesetz, welches man nicht dart ubertreten, daß Vasthi nicht mehr vor den Konig Ahasveros komme; und der Konig gebe ihr Konigreich ihrer Nachsten, die besser ist denn sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'und daß dieser Brief des Konigs, der gemacht wird, in sein ganz Reich (welches grofi ist) erschalle, daß alle Weiber ihre Manner in Ehren halten, beide unter Grolien und Kleinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Das gefiel dem Konige und den Fursten; und der Konig tat nach dem Wort Memuchans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Da wurden Briefe ausgesandt in alle Lander des Konigs, in ein jeglich Land nach seiner Schrift und zu jeglichem Volk nach seiner Sprache, dafi ein jeglicher Mann der Oberherr in seinem Hause sei; und lieli reden nach der Sprache seines Volks');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Nach diesen Geschichten, da der Grimm des Konigs Ahasveros sich gelegt hatte, gedachte er an Vasthi, was sie getan hatte, und was über sie beschlossen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Da sprachen die Knaben des Konigs, die ihm dieneten: Man suche dem Konige junge schone Jungfrauen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'und der Konig bestelle Schauer in alien Landen seines Konigreichs, dafi sie allerlei junge schone Jungfrauen zusammenbringen gen Schloli Susan, ins Frauenzimmer, unter die Hand Hegais, des Konigs Kammerers, der der Weiber wartet, und gebe ihnen ihren Schmuck;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'und welche Dime dem Konige gefallt, die werde Konigin an Vasthis Statt. Das gefiel dem Konige und tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Es war aber ein judischer Mann zu Schloli Susan, der hiefi Mardachai, ein Sohn Jairs, des Sohns Simeis, des Sohns Kis, des Sohns Jeminis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'der mit weggefuhret war von Jerusalem, da Jechanja, der Konig Judas, weggefuhret ward, welchen Nebukadnezar, der Konig zu Babel, wegfuhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Und er war ein Vormund Hadassas, die ist Esther, eine Tochter seines Vetters; denn sie hatte weder Vater noch Mutter. Und sie war eine schone und feine Dime. Und da ihr Vater und Mutter starb, nahm sie Mardachai auf zur Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Da nun das Gebot und Gesetz des Konigs laut ward, und viel Dirnen zu Hause gebracht wurden gen Schloli Susan unter die Hand Hegais, ward Esther auch genommen zu des Konigs Haus unter die Hand Hegais, des Hitters der Weiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Und die Dime gefiel ihm, und sie fand Barmherzigkeit vor ihm. Und er eilete mit ihrem Schmuck, daß er ihr ihren Teil gabe, und sieben feine Dirnen von des Konigs Hause dazu. Und ertat sie mit ihren Dirnen an den besten Ort im Frauenzimmer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Und Esther sagte ihm nicht an ihr Volk und ihre Freundschaft; denn Mardachai hatte ihr geboten, sie sollte es nicht ansagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Und Mardachai wandelte alle Tage vor dem Hofe am Frauenzimmer, daß er erfuhre, ob es Esther wohlginge, und was ihrgeschehen würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Wenn aber die bestimmte Zeiteinerjeglichen Dime kam, daß sie zum Konige Ahasveros kommen sollte, nachdem sie zwolf Monden im Frauenschmucken gewesen war (denn ihr Schmücken mulite so viel Zeit haben, namlich sechs Monden mit Balsam und Myrrhen und sechs Monden mit guter Spezerei, so waren denn die Weiber geschmuckt),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'alsdann ging eine Dime zum Konige, und welche sie wollte, mulite man ihr geben, die mit ihr vom Frauenzimmer zu des Konigs Hause ginge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Und wenn eine des Abends hineinkam, die ging des Morgens von ihm in das andere Frauenzimmer unter die Hand Saasgas, des Konigs Kammerers, der Kebsweiber Huters. Und sie mulite nicht wieder zum Konige kommen, es lustete denn den Konig und lielie sie mit Namen rufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Da nun die Zeit Esthers herzukam, der Tochter Abihails, des Vetters Mardachais (die er zur Tochter hatte aufgenommen), daß sie zum Konige kommen sollte, begehrete sie nichts, denn was Hegai, des Konigs Kammerer, der Weiber Hüter, sprach. Und Esther fand Gnade vor alien, die sie ansahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Es ward aber Esther genommen zum Konige Ahasveros ins konigliche Haus im zehnten Monden, der da heiliet Tebeth, im siebenten Jahr seines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Und der Konig gewann Esther lieb fiber alle Weiber, und sie fand Gnade und Barmherzigkeit vor ihm vor alien Jungfrauen. Und er setzte die konigliche Krone auf ihr Haupt und machte sie zur Konigin an Vasthis Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Und der Konig machte ein groli Mahl alien seinen Fursten und Knechten (das war ein Mahl urn Esthers willen) und lieli die Lander ruhen und gab konigliche Geschenke aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Und da man das andere Mai Jungfrauen versammelte, sali Mardachai im Tordes Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Und Esther hatte noch nicht angesagt ihre Freundschaft noch ihr Volk, wie ihrdenn Mardachai geboten hatte. Denn Esther tat nach dem Wort Mardachais, gleich als da er ihr Vormund war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Zur selbigen Zeit, da Mardachai im Tor des Konigs safi, wurden zween Kammerer des Konigs, Bigthan und Theres, die der Tur huteten, zornig und trachteten, ihre Hande an den Konig Ahasveros zu legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Das ward Mardachai kund, und er sagte es an der Konigin Esther, und Esther sagte es dem Konige in Mardachais Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Und da man solches forschete, ward es funden. Und sie wurden beide an Baume gehangt, und ward geschrieben in die Chronik vor dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Nach diesen Geschichten machte der Konig Ahasveros Haman groli, den Sohn Medathas, den Agagiter, und erhohete ihn und setzte seinen Stuhl uber alle Fursten, die bei ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Und alle Knechte des Konigs, die im Tor des Konigs waren, beugten die Kniee und beteten Haman an; denn der Konig hatte es also geboten. Aber Mardachai beugete die Kniee nicht und betete nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Da sprachen des Konigs Knechte, die im Tor des Konigs waren, zu Mardachai: Warum ubertrittst du des Konigs Gebot?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Und da sie solches taglich zu ihm sagten, und er ihnen nicht gehorchte, sagten sie es Haman an, daß sie sahen, ob solch Tun Mardachais bestehen wurde; denn er hatte ihnen gesagt, dafi er ein Jude ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Und da Haman sah, daß Mardachai ihm nicht die Kniee beugete noch ihn anbetete, ward er voll Grimms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Und verachtete es, daß er an Mardachai allein sollte die Hand legen, denn sie hatten ihm das Volk Mardachais angesagt; sondern er trachtete, das Volk Mardachais, alle Juden, so im ganzen Konigreich Ahasveros waren, zu vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Im ersten Monden, das ist der Mond Nisan, im zwolften Jahr des Konigs Ahasveros, ward das Los geworfen vor Haman, von einem Tage auf den andern und vom Monden bis auf den zwolften Monden, das ist der Mond Adar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Und Haman sprach zum Konige Ahasveros: Es ist ein Volk zerstreuet und teilet sich unter alle Volker in alien Landen deines Konigreichs, und ihr Gesetz ist anders denn alter Volker, und tun nicht nach des Konigs Gesetzen; und ist dem Konige nicht zu leiden, sie also zu lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Gefallt es dem Konige, so schreibe er, daß man es umbringe; so will ich zehntausend Zentner Silbers darwagen unter die Hand der Amtleute, daß man es bringe in die Kammer des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Da tat der Konig seinen Ring von der Hand und gab ihn Haman, dem Sohne Medathas, dem Agagiter, der Juden Feind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Und der Konig sprach zu Haman: Das Silber sei dir qegeben, dazu das Volk, daß du damit tust, was dir gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Da rief man den Schreibern des Konigs am dreizehnten Tage des ersten Monden; und ward geschrieben, wie Haman befahl, an die Fursten des Konigs und zu den Landpflegern hin und her in den Landern und zu den Hauptleuten eines jeglichen Volks in den Landern hin und her nach der Schrift eines jeglichen Volks und nach ihrer Sprache, im Namen des Konigs Ahasveros und mit des Konigs Ringe versiegelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Und die Briefe wurden gesandt durch die Laufer in alle Lander des Konigs, zu vertilgen, zu erwürgen und umzubringen alle Juden, beide jung und alt, Kinder und Weiber, auf einen Tag, namlich auf den dreizehnten Tag des zwolften Monden, das ist der Mond Adar, und ihr Gut zu rauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Also war der Inhalt der Schrift, daß ein Gebot gegeben ware in alien Landern, alien Volkern zu eroffnen, daß sie auf denselben Tag geschickt waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Und die Laufer gingen aus eilend nach des Konigs Gebot. Und zu Schloli Susan ward angeschlagen ein Gebot. Und der Konig und Haman alien und tranken; aber die Stadt Susan ward irre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Da Mardachai erfuhr alles, was geschehen war, zerrili er seine Kleider und legte einen Sack an und Asche; und ging hinaus mitten in die Stadt und schrie laut und klaglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Und kam vor das Tor des Konigs. Denn es mulite niemand zu des Konigs Tor eingehen, der einen Sack anhatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Und in alien Landern, an welchen Ort des Konigs Wort und Gebot gelangete, war ein groli Klagen unter den Juden, und viele fasteten, weineten, trugen Leid und lagen in Sacken und in der Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Da kamen die Dirnen Esthers und ihre Kammerer und sagten\'s ihr an. Da erschrak die Konigin sehr. Und sie sandte Kleider, daß Mardachai anzoge und den Sack von ihm ablegte; er aber nahm sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Da rief Esther Hathach unter des Konigs Kammerern, der vor ihr stund, und befahl ihm an Mardachai, daß sie erfuhre, was das ware, und warum er so tate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Da ging Hathach hinaus zu Mardachai an die Gasse in der Stadt, die vor dem Tor des Konigs war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Und Mardachai sagte ihm alles, was ihm begegnet ware, und die Summa des Silbers, das Haman geredet hatte in des Konigs Kammer darzuwagen urn der Juden willen, sie zu vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Und gab ihm die Abschrift des Gebots, das zu Susan angeschlagen war, sie zu vertilgen, daß er es Esther zeigete und ihr ansagete und gebote ihr, daß sie zum Konige hineinginge und tate eine Bitte an ihn um ihr Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Und da Hathach hineinkam und sagte Esther die Worte Mardachais,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'sprach Esther zu Hathach und gebot ihm an Mardachai:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Es wissen alle Knechte des Konigs und das Volk in den Landen des Konigs, daß, werzum Konige hineingehet inwendig in den Hof, ersei Mann Oder Weib, der nicht gerufen ist, der soil stracks Gebots sterben, es sei denn, daß der Konig den guldenen Zepter gegen ihn reiche, damit er lebendig bleibe. Ich aber bin nun in dreilüg Tagen nicht gerufen, zum Konige hineinzukommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Und da die Worte der Esther wurden Mardachai angesagt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'hieli Mardachai Esther wieder sagen: Gedenke nicht, daß du dein Leben errettest, weil du im Hause des Konigs bist, vor alien Juden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'denn wo du wirst zu dieser Zeit schweigen, so wird eine Hilfe und Errettung aus einem andern Ort den Juden entstehen, und du und deines Vaters Haus werdet umkommen. Und wer weili, ob du um dieser Zeit willen zum Konigreich kommen bist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Esther hieti Mardachai antworten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'So gehe hin und versammle alle Juden, die zu Susan vorhanden sind, und fastet fur mich, daß ihr nicht esset und trinket in dreien Tagen weder Tag noch Nacht; ich und meine Dirnen wollen auch also fasten. Und also will ich zum Konige hineingehen wider das Gebot; komme ich um, so komme ich um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mardachai ging hin und tat alles, was ihm Esther geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Und am dritten Tage zog sich Esther koniglich an und trat in den Hof am Hause des Konigs inwendig gegen dem Hause des Konigs. Und der Konig sali auf seinem koniglichen Stuhl im koniglichen Hause, gegen der Tür des Hauses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Und da der Konig sah Esther, die Konigin, stehen im Hofe, fand sie Gnade vor seinen Augen. Und der Konig reckte den guldenen Zepter in seiner Hand gegen Esther. Da trat Esther herzu und ruhrete die Spitze des Zepters an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Da sprach der Konig zu ihr: Was ist dir, Esther, Konigin? und was forderst du? Auch die Halfte des Konigreichs soil dir gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Esther sprach: Gefallt es dem Konige, so komme der Konig und Haman heute zu dem Mahl, das ich zugerichtet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Der Konig sprach: Eilet, daß Haman tue, was Esther gesagt hat! Da nun der Konig und Haman zu dem Mahl kamen, das Esther zugerichtet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'sprach der Konig zu Esther, da er Wein getrunken hatte: Was bittest du, Esther? Es soil dir gegeben werden. Und was forderst du? Auch die Halfte des Konigreichs, es soil geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Da antwortete Esther und sprach: Meine Bitte und Begehr ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Habe ich Gnade gefunden vor dem Konige, und so es dem Konige gefallt, mirzu geben meine Bitte und zu tun mein Begehr, so komme der Konig und Haman zu dem Mahl, das ich fur sie zurichten will, so will ich morgen tun, was der Konig gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Da ging Haman des Tages hinaus frohlich und gutes Muts. Und da er sah Mardachai im Tor des Konigs, daß er nicht aufstund, noch sich vor ihm bewegte, ward er voll Zorns über Mardachai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Aber er enthielt sich. Und da er heim kam, sandte er hin und lieft holen seine Freunde und sein Weib Seres.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Und erzahlete ihnen die Herrlichkeit seines Reichtums und die Menge seiner Kinder und alles, wie ihn der Konig so graft gemacht hatte, und daß er fiber die Fursten und Knechte des Konigs erhaben ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Auch sprach Haman: Und die Konigin Esther hat niemand lassen kommen mit dem Konige zum Mahl, das sie zugerichtet hat, ohne mich; und bin auch morgen zu ihr geladen mit dem Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Aber an dem allem habe ich keine Genüge, solange ich sehe den Juden Mardachai am Konigstor sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Da sprach zu ihm sein Weib Seres und alle seine Freunde: Man mache einen Baum fünfzig Ellen hoch und sage morgen dem Konige, daß man Mardachai daran hange; so kommst du mit dem Konige frohlich zum Mahl. Das gefiel Haman wohl und lieft einen Baum zurichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'In derselben Nacht konnte der Konig nicht schlafen und hieft die Chronik und die Historien bringen. Da die wurden vor dem Konige gelesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'traf sich\'s, da geschrieben war, wie Mardachai hatte angesagt, daß die zween Kammerer des Konigs, Bigthan und Theres, die an der Schwelle huteten, getrachtet hatten, die Hand an den Konig Ahasveros zu legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Und der Konig sprach: Was haben wir Mardachai Ehre und Gutes dafür getan? Da sprachen die Knaben des Konigs, die ihm dieneten: Es ist ihm nichts geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Und der Konig sprach: Wer ist im Hofe? (Denn Haman war in den Hof gegangen, drauften vor des Konigs Hause, daß erdem Konige sagte, Mardachai zu hangen an den Baum, den er ihm zubereitet hatte.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Und des Konigs Knaben sprachen zu ihm: Siehe, Haman stehet im Hofe. Der Konig sprach: Laftt ihn hereingehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Und da Haman hineinkam, sprach der Konig zu ihm: Was soil man dem Manne tun, den der Konig gerne wollte ehren? Haman aber gedachte in seinem Herzen: Wem sollte der Konig anders gerne wollen Ehre tun denn mir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Und Haman sprach zum Konige: Den Mann, den der Konig gerne wollte ehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'soil man herbringen, daß man ihm konigliche Kleider anziehe, die der Konig pflegt zu tragen, und das Roß, da der Konig auf reitet, und daß man die konigliche Krone auf sein Haupt setze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Und man soli solch Kleid und Roß geben in die Hand eines Fursten des Konigs, daß derselbe den Mann anziehe, den der Konig gerne ehren wollte, und führe ihn auf dem Roß in der Stadt Gassen und lasse rufen vor ihm her: So wird man tun dem Manne, den der Konig gerne ehren wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Der Konig sprach zu Haman: Eile und nimm das Kleid und Roß, wie du gesagt hast, und tue also mit Mardachai, dem Juden, der vor dem Tor des Konigs sitzet; und laß nichts fehlen an allem, das du geredet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Da nahm Haman das Kleid und Roß, und zog Mardachai an und fuhrete ihn auf der Stadt Gassen und rief vor ihm her: So wird man tun dem Manne, den der Konig gerne ehren wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Und Mardachai kam wieder an das Tor des Konigs. Haman aber eilete nach Hause, trug Leid mit verhulletem Kopfe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'und erzahlete seinem Weibe Seres und seinen Freunden alien alles, was ihm begegnet war. Da sprachen zu ihm seine Weisen und sein Weib Seres: 1st Mardachai vom Samen der Juden, vor dem du zu fallen angehoben hast, so vermagst du nichts an ihm, sondern du wirst vor ihm fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Da sie aber noch mit ihm redeten, kamen herbei des Konigs Kammerer und trieben Haman, zum Mahl zu kommen, das Esther zugerichtet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Und da der Konig mit Haman kam zum Mahl, das die Konigin Esther zugerichtet hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'sprach der Konig zu Esther des andern Tages, da er Wein getrunken hatte: Was bittest du, Konigin Esther, daß man dir\'s gebe? Und was forderst du? Auch das halbe Konigreich, es soli geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Esther, die Konigin, antwortete und sprach: Habe ich Gnade vor dir funden, o Konig, und gefallt es dem Konige, so gib mir mein Leben urn meiner Bitte willen und mein Volk urn meines Begehrens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Denn wir sind verkauft, ich und mein Volk, daß wir vertilget, erwurget und umgebrachtwerden; und wollte Gott, wirwurden doch zu Knechten und Magden verkauft, so wollte ich schweigen, so würde der Feind doch dem Konige nicht schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Der Konig Ahasveros redete und sprach zu der Konigin Esther: Wer ist der? Oder wo ist der, der solches in seinen Sinn nehmen durfte, also zu tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Esther sprach: Der Feind und Widersacher ist dieser bose Haman. Haman entsetzte sich vor dem Konige und der Konigin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Und der Konig stund auf vom Mahl und vom Wein in seinem Grimm und ging in den Garten am Hause. Und Haman stund auf und bat die Konigin Esther urn sein Leben; denn er sah, daß ihm ein Ungluck vom Konige schon bereitet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Und da der Konig wieder aus dem Garten am Hause in den Saal, da man gegessen hatte, kam, lag Haman an der Bank, da Esther auf saß. Da sprach der Konig: Will er die Konigin wurgen bei mir im Hause? Da das Wort aus des Konigs Munde ging, verhulleten sie Haman das Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Und Harbona, der Kammerer einer vor dem Konige, sprach: Siehe, es stehet ein Baum im Hause Hamans fünfzig Ellen hoch, den er Mardachai gemacht hatte, der Gutes fur den Konig geredet hat. Der Konig sprach: Laßt ihn daran hangen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Also hangte man Haman an den Baum, den er Mardachai gemacht hatte. Da legte sich des Konigs Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'An dem Tage gab der Konig Ahasveros der Konigin Esther das Haus Hamans, des Judenfeindes. Und Mardachai kam vor den Konig; denn Esther sagte an, wie er ihrzugehorete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Und der Konig tat ab seinen Fingerreif, den er von Haman hatte genommen; und gab ihn Mardachai. Und Esther setzte Mardachai uber das Haus Hamans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Und Esther redete weiter vor dem Konig und fiel ihm zu den Fußen und flehete ihn, daß erwegtate die Bosheit Hamans, des Agagiters, und seine Anschlage, die er wider die Juden erdacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Und der Konig reckte das guldene Zepter zu Esther. Da stund Esther auf und trat vor den Konig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'und sprach: Gefallt es dem Konige, und habe ich Gnade funden vor ihm, und ist\'s gelegen dem Konige, und ich ihm gefalle, so schreibe man, daß die Briefe der Anschlage Hamans, des Sohns Medathas, des Agagiters, widerrufen werden, die ergeschrieben hat, die Juden umzubringen in alien Landen des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Denn wie kann ich zusehen dem Ubel, das mein Volk treffen würde? Und wie kann ich zusehen, daß mein Geschlecht umkomme?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Da sprach der Konig Ahasveros zur Konigin Esther und zu Mardachai, dem Juden: Siehe, ich habe Esther das Haus Hamans gegeben, und ihn hat man an einen Baum gehanget, darum daß er seine Hand hat an die Juden gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'So schreibet nun ihr fur die Juden, wie es euch gefallt, in des Konigs Namen und versiegelt es mit des Konigs Ringe. Denn die Schrift, die in des Konigs Namen geschrieben und mit des Konigs Ringe versiegelt worden, mußte niemand widerrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Da wurden gerufen des Konigs Schreiber zu der Zeit im dritten Monden, das ist der Mond Sivan, am dreiundzwanzigsten Tage; und wurde geschrieben, wie Mardachai gebot zu den Juden und zu den Fursten, Landpflegern und Hauptleuten in Landen von Indien an bis an die Mohren, namlich hundertundsiebenundzwanzig Lander, einem jeglichen Lande nach seinen Schriften, einem jeglichen Volk nach seiner Sprache und den Juden nach ihrer Schrift und Sprache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Und esward geschrieben in des Konigs Ahasveros Namen und mit des Konigs Ringe versiegelt. Und er sandte die Briefe durch die reitenden Boten auf jungen Maulern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'darinnen der Konig den Juden gab, wo sie in Stadten waren, sich zu versammeln und zu stehen fur ihr Leben und zu vertilgen, zu erwurgen und umzubringen alle Macht des Volks und Landes, die sie angsteten, samt den Kindern und Weibern, und ihr Gut zu rauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'auf einen Tag in alien Landern des Konigs Ahasveros, namlich am dreizehnten Tage des zwolften Monden, das ist der Mond Adar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Der Inhalt aber der Schrift war, dafi ein Gebot gegeben ware in alien Landen, zu offnen alien Volkern, daß die Juden auf den Tag geschickt sein sollten, sich zu rachen an ihren Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Und die reitenden Boten auf den Maulern ritten aus schnell und eilend nach dem Wort des Konigs, und das Gebot ward zu Schloft Susan angeschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mardachai aber ging aus, von dem Konige in koniglichen Kleidern, gelb und weift, und mit einer groften guldenen Krone, angetan mit einem Leinen- und Purpurmantel; und die Stadt Susan jauchzete und war frohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Den Juden aber war ein Lichtund Freude und Wonne und Ehre kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Und in alien Landen und Stadten, an welchen Ort des Konigs Wort und Gebot gelangete, da ward Freude und Wonne unter den Juden, Wohlleben und gute Tage, daß viele der Volker im Lande Juden wurden; denn die Furcht der Juden kam fiber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Im zwolften Monden, das ist der Mond Adar, am dreizehnten Tage, den des Konigs Wort und Gebot bestimmt hatte, daß man\'s tun sollte, eben desselben Tages, da die Feinde der Juden hofften, sie zu uberwaltigen, wandte sich\'s, daß die Juden ihre Feinde uberwaltigen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Da versammelten sich die Juden in ihren Stadten, in alien Landen des Konigs Ahasveros, daß sie die Hand legten an die, so ihnen übel wollten. Und niemand konnte ihnen widerstehen; denn Furcht war fiber alle Volker kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Auch alle Obersten in Landen und Fursten und Landpfleger und Amtleute des Konigs erhuben die Juden; denn die Furcht Mardachais kam fiber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Denn Mardachai war graft im Hause des Konigs, und sein Gerficht erscholl in alien Landern, wie er zunahme und graft wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Also schlugen die Juden an alien ihren Feinden mit der Schwertschlacht und würgeten und brachten urn und taten nach ihrem Willen an denen, die ihnen feind waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Und zu Schloft Susan erwurgeten die Juden und brachten urn fünfhundert Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Dazu erwurgeten sie Parsandatha, Dalphon, Aspatha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratha, Adalja, Aridatha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastha, Arisai, Aridai, Vajesatha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'die zehn Sohne Hamans, des Sohns Medathas, des Judenfeindes; aber an seine Gfiter legten sie ihre Hande nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Zu derselbigen Zeit kam die Zahl der Erwurgten gen Schloft Susan vor den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Und der Konig sprach zu der Konigin Esther: Die Juden haben zu Schloft Susan fünfhundert Mann erwürget und umgebracht und die zehn Sohne Hamans; was werden sie tun in den andern Landern des Konigs? Was bittest du, daß man dir gebe? und was forderst du mehr, daß man tue?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Esther sprach: Gefallt es dem Konige, so lasse er auch morgen die Juden zu Susan tun nach dem heutigen Gebot, daß sie die zehn Sohne Hamans an den Baum hangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Und der Konig hieft also tun. Und das Gebot ward zu Susan angeschlagen, und die zehn Sohne Hamans wurden gehanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Und die Juden versammelten sich zu Susan am vierzehnten Tage des Monden Adar und erwurgeten zu Susan dreihundert Mann; aber an ihre Guter legten sie ihre Hande nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Aber die andern Juden in den Landern des Konigs kamen zusammen und stunden fur ihr Leben, daß sie Ruhe schaffeten vor ihren Feinden; und erwurgeten ihrer Feinde funfundsiebenzigtausend; aber an ihre Guter legten sie ihre Hande nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Das geschah am dreizehnten Tage des Monden Adar, und ruheten am vierzehnten Tage desselben Monden; den machte man zum Tage des Wohllebens und Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Aber die Juden zu Susan waren zusammenkommen, beide am dreizehnten und vierzehnten Tage, und ruheten am funfzehnten Tage; und den Tag machte man zum Tage des Wohllebens und Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Darum machten die Juden, die auf den Dorfern und Flecken wohneten, den vierzehnten Tag des Monden Adar zum Tage des Wohllebens und Freuden, und sandte einer dem andern Geschenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Und Mardachai beschrieb diese Geschichte und sandte die Briefe zu alien Juden, die in alien Landern des Konigs Ahasveros waren, beide nahen und fernen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'daß sie annahmen und hielten den vierzehnten und funfzehnten Tag des Monden Adar jahrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'nach den Tagen, darinnen die Juden zur Ruhe kommen waren von ihren Feinden, und nach dem Monden, darinnen ihre Schmerzen in Freude und ihr Leid in gute Tage verkehret war, daß sie dieselben halten sollten fur Tage des Wohllebens und Freuden, und einer dem andern Geschenke schicken und den Armen mitteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Und die Juden nahmen\'s an, das sie angefangen hatten zu tun, und das Mardachai zu ihnen schrieb:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'wie Haman, derßohn Medathas, der Agagiter, aller Juden Feind, gedacht hatte, alle Juden umzubringen, und das Los werfen lassen, sie zu schrecken und umzubringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'und wie Esther zum Konige gegangen war und geredet, daß durch Briefe seine bosen Anschlage, die er wider die Juden gedacht, auf seinen Kopf gekehret würden; und wie man ihn und seine Sohne an den Baum gehanget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Daher sie diese Tage Purim nannten nach dem Namen des Loses, nach alien Worten dieses Briefes, und was sie selbst gesehen hatten, und was an sie gelanget war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Und die Juden richteten es auf und nahmen es auf sich und auf ihren Samen und auf alle, die sich zu ihnen taten, daß sie nicht ubergehen wollten, zu halten diese zween Tage jahrlich, wie die beschrieben und bestimmt wurden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'da(S diese Tage nicht zu vergessen, sondern zu halten seien bei Kindeskindern, bei alien Geschlechtern in alien Landern und Stadten. Es sind die Tage Purim, welche nicht sollen übergangen werden unter den Juden, und ihr Gedachtnis nicht umkommen bei ihrem Samen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Und die Konigin Esther, die Tochter Abihails, und Mardachai, der Jude, schrieben mit ganzer Gewalt, zu bestatigen diesen andern Brief von Purim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Und sandte die Briefe zu alien Juden in den hundertundsiebenundzwanzig Landern des Konigreichs Ahasveros mit freundlichen und treuen Worten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'da(S sie bestatigten diese Tage Purim auf ihre bestimmte Zeit, wie Mardachai, der Jude, uber sie bestatiget hatte, und die Konigin Esther; wie sie auf ihre Seele und auf ihren Samen bestatiget hatten die Geschichte der Fasten und ihres Schreiens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Und Esther befahl, die Geschichte dieser Purim zu bestatigen und in ein Buch zu schreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Und der Konig Ahasveros legte Zins auf das Land und auf die Inseln im Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Aber alle Werke seiner Gewalt und Macht und die große Herrlichkeit Mardachais, die ihm der Konig gab, siehe, das ist geschrieben in der Chronik der Konige in Medien und Persien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Denn Mardachai, der Jude, war der andere nach dem Konige Ahasveros und groß unter den Juden und angenehm unter der Menge seiner Bruder, der fur sein Volk Gutes suchte und redete das Beste fur alien seinen Samen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Es war ein Mann im Lande Uz, der hieli Hiob. Derselbe war schlecht und recht, gottesfurchtig und meidete das Bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Und zeugete sieben Sohne und drei Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Und seines Viehes waren siebentausend Schafe, dreitausend Kamele, funfhundert Joch Rinder und funfhundert Eselinnen und sehr viel Gesindes; und er war herrlicher denn alle, die gegen Morgen wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Und seine Sohne gingen hin und machten Wohlleben, ein jeglicher in seinem Hause auf seinen Tag; und sandten hin und luden ihre drei Schwestern, mit ihnen zu essen und zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Und wenn ein Tag des Wohllebens um war, sandte Hiob hin und heiligte sie; und machte sich des Morgens frühe auf und opferte Brandopfer nach ihrer aller Zahl. Denn Hiob gedachte: Meine Sohne mochten gesundiget und Gott gesegnet haben in ihrem Herzen. Also tat Hiob alle Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Es begab sich aber auf einen Tag, da die Kinder Gottes kamen und vor den HERRN traten, kam der Satan auch unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Der HERR aber sprach zu dem Satan: Wo kommst du her? Satan antwortete dem HERRN und sprach: Ich habe das Land umher durchzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Der HERR sprach zu Satan: Hast du nicht achtgehabt auf meinen Knecht Hiob? Denn es ist seinesgleichen nicht im Lande, schlecht und recht, gottesfurchtig und meidet das Bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Satan antwortete dem HERRN und sprach: Meinest du, daß Hiob umsonst Gott furchtet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Hastdu doch ihn, sein Haus und alles, waser hat, rings umher verwahret. Du hast das Werk seiner Hande gesegnet, und sein Gut hat sich ausgebreitet im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Aber recke deine Hand aus und taste an alles, was er hat; was gilt\'s, er wird dich ins Angesicht segnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Der HERR sprach zu Satan: Siehe, alles, was er hat, sei in deiner Hand; ohne allein an ihn selbst lege deine Hand nicht. Da ging Satan aus von dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Des Tages aber, da seine Sohne und Tochter alien und tranken Wein in ihres Bruders Hause, des Erstgeborenen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'kam ein Bote zu Hiob und sprach: Die Rinder pflugeten, und die Eselinnen gingen neben ihnen an der Weide;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'da fielen die aus Reicharabien herein und nahmen sie und schlugen die Knaben mit der Scharfe des Schwerts; und ich bin allein entronnen, daß ich dir\'s ansagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Da der noch redete, kam ein anderer und sprach: Das Feuer Gottes fiel vom Himmel und verbrannte Schafe und Knaben und verzehrete sie; und ich bin allein entronnen, daß ich dir\'s ansagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Da der noch redete, kam einer und sprach: Die Chaldaer machten drei Spitzen und uberfielen die Kamele und nahmen sie und schlugen die Knaben mit der Scharfe des Schwerts; und ich bin allein entronnen, daß ich dir\'s ansagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Da der noch redete, kam einer und sprach: Deine Sohne und Tochter alien und tranken im Hause ihres Bruders, des Erstgebornen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'und siehe, da kam ein grofier Wind von der Wüste her und stieli auf die vier Ecken des Hauses und warfs auf die Knaben, daß sie starben; und ich bin allein entronnen, daß ich dir\'s ansagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Da stund Hiob auf und zerrifi sein Kleid und raufte sein Haupt; und fiel auf die Erde und betete an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'und sprach: Ich bin nackend von meiner Mutter Leibe kommen, nackend werde ich wieder dahinfahren. Der HERR hat\'s gegeben, der HERR hat\'s genommen; der Name des HERRN sei gelobt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'In diesem allem sundigte Hiob nicht und tat nichts Torichtes wider Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Es begab sich aber des Tages, da die Kinder Gottes kamen und traten vor den HERRN, daß Satan auch unter ihnen kam und vor den HERRN trat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Da sprach der HERR zu dem Satan: Wo kommst du her? Satan antwortete dem HERRN und sprach: Ich habe das Land umher durchzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Der HERR sprach zu dem Satan: Hast du nicht acht auf meinen Knecht Hiob gehabt? Denn es ist seinesgleichen im Lande nicht, schlecht und recht, gottesfurchtig und meidet das Bose und halt noch fest an seiner Frommigkeit; du aber hast mich bewegt, daß ich ihn ohne Ursache verderbet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satan antwortete dem HERRN und sprach: Haut fur Haut; und alles, was ein Mann hat, lalit er fur sein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Aber recke deine Hand aus und taste sein Gebein und Fleisch an; was gilt\'s, er wird dich ins Angesicht segnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Der HERR sprach zu dem Satan: Siehe da, er sei in deiner Hand; doch schone seines Lebens!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Da fuhr der Satan aus vom Angesicht des HERRN und schlug Hiob mit bosen Schwaren von der Fulisohle an bis auf seine Scheitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Und er nahm einen Scherben und schabte sich und sali in der Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Und sein Weib sprach zu ihm: Haltst du noch fest an deiner Frommigkeit? Ja, segne Gott und stirb!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Er aber sprach zu ihr: Du redest, wie die narrischen Weiber reden. Haben wir Gutes empfangen von Gott und sollten das Bose nicht auch annehmen? In diesem allem versundigte sich Hiob nicht mit seinen Lippen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Da aber die drei Freunde Hiobs horeten all das Ungluck, das fiber ihn kommen war, kamen sie, ein jeglicher aus seinem Ort: Eliphas von Theman, Bildad von Suah und Zophar von Naema. Denn sie wurden eins, daß sie kamen, ihn zu klagen und zu trosten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Und da sie ihre Augen aufhuben von feme, kannten sie ihn nicht und huben auf ihre Stimme und weineten; und ein jeglicher zerriß sein Kleid und sprengeten Erde auf ihr Haupt gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Und saßen mitihm auf der Erde sieben Tage und sieben Nachte und redeten nichts mit ihm; denn sie sahen, daß der Schmerz sehr groß war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Danach tat Hiob seinen Mund auf und verfluchte seinen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Und Hiob sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Der Tag müsse verloren sein, darinnen ich geboren bin, und die Nacht, da man sprach: Es ist ein Mannlein empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Derselbe Tag müsse finster sein, und Gott von oben herab musse nicht nach ihm fragen; kein Glanz müsse über ihn scheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Finsternis und Dunkel müssen ihn überwaltigen, und dicke Wolken müssen über ihm bleiben, und der Dampf am Tage mache ihn graßlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Die Nacht müsse ein Dunkel einnehmen, und müsse sich nicht unter den Tagen des Jahres freuen, noch in die Zahl der Monden kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Siehe, die Nacht müsse einsam sein und kein Jauchzen drinnen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Es verfluchen sie die Verflucher des Tages, und die da bereit sind, zu erwecken den Leviathan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Ihre Sterne müssen finster sein in ihrer Dammerung; sie hoffe aufs Licht und komme nicht und müsse nicht sehen die Augenbrauen der Morgenrote,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'daß sie nicht verschlossen hat die Tür meines Leibes und nicht verborgen das Unglück vor meinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Warum bin ich nicht gestorben von Mutterleib an? Warum bin ich nicht umkommen, da ich aus dem Leibe kam?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Warum hat man mich auf den Schoß gesetzet? Warum bin ich mit Brüsten gesauget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'So lage ich doch nun und ware stille, schliefe und hatte Ruhe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'mit den Konigen und Ratsherren auf Erden, die das Wüste bauen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Oder mit den Fürsten, die Gold haben und ihre Hauser voll Silbers sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'oderwieeine unzeitige Geburt verborgen und nichts ware, wie die jungen Kinder, die das Licht nie gesehen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Daselbst müssen doch aufhoren die Gottlosen mit Toben; daselbst ruhen doch, die viel Mühe gehabt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Da haben doch miteinander Frieden die Gefangenen und horen nicht die Stimme des Drangers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Da sind beide klein und groß, Knecht und der von seinem Herm frei gelassen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Warum ist das Licht gegeben dem Muhseligen und das Leben den betrubten Herzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, '(die des Todes warten und kommt nicht, und grüben ihn wohl aus dem Verborgenen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'die sich fast freuen und sind frohlich, daß sie das Grab bekommen,)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'und dem Manne, des Weg verborgen ist, und Gott vor ihm denselben bedecket?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Denn wenn ich essen soil, muß ich seufzen, und mein Heulen fahret heraus wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Denn das ich gefurchtet habe, ist uber mich kommen, und das ich sorgte, hat mich getroffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'War ich nicht gluckselig? War ich nicht fein stille? Hatte ich nicht gute Ruhe? Und kommt solche Unruhe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Da antwortete Eliphas von Theman und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Du hast\'s vielleicht nicht gerne, so man versucht, mit dir zu reden; aber wer kann sich\'s enthalten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Siehe, du hast viele unterweiset und lasse Hande gestarkt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'deine Rede hat die Gefallenen aufgerichtet, und die bebenden Kniee hast du bekraftiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Nun es aber an dich kommt, wirst du weich; und nun es dich trifft, erschrickst du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ist das deine (Gottes-)Furcht, dein Trost, deine Hoffnung und deine Frommigkeit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Lieber, gedenke, wo ist ein Unschuldiger umkommen, Oder wo sind die Gerechten je vertilget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Wie ich wohl gesehen habe, die da Muhe pflugten und Unglück saeten und ernten sie auch ein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'daß sie durch den Odem Gottes sind umkommen und vom Geist seines Zorns vertilget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Das Brullen der Lowen und die Stimme der großen Lowen und die Zahne der jungen Lowen sind zerbrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Der Lowe ist umkommen, daß er nicht mehr raubet, und die Jungen der Lowin sind zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Und zu mir ist kommen ein heimlich Wort, und mein Ohr hat ein Wortlein aus demselben empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Da ich Gesichte betrachtete in der Nacht, wenn der Schlaf auf die Leute fallt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'da kam mich Furcht und Zittern an, und alle meine Gebeine erschraken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Und da der Geist vor mir uberging, stunden mir die Haare zu Berge an meinem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Da stund ein Bild vor meinen Augen, und ich kannte seine Gestalt nicht; es war stille, und ich horete eine Stimme:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Wie mag ein Mensch gerechter sein denn Gott, Oder ein Mann reiner sein, denn der ihn gemacht hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Siehe, unter seinen Knechten ist keiner ohne Tadel, und in seinen Boten findet er Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Wie viel mehr, die in den leimenen Hausern wohnen und welche auf Erden gegrundet sind, werden von den Wurmern gefressen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Es wahret von Morgen bis an den Abend, so werden sie ausgehauen; und ehe sie es gewahr werden, sind sie gar dahin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'und ihre Ubrigen vergehen und sterben auch unversehens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Nenne mir einen; was gilt\'s, ob du einen findest? Und siehe dich um irgend nach einem Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Einen Tollen aber erwurget wohl der Zorn, und den Albernen totet der Eifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Ich sah einen Tollen eingewurzelt, und ich fluchte plotzlich seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Seine Kinder werden feme sein vom Heil und werden zerschlagen werden im Tor, da kein Erretter seinwird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Seine Ernte wird essen der Hungrige, und die Gewappneten werden ihn holen, und sein Gut werden die Durstigen aussaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Denn Mühe aus der Erde nicht gehet, und Unglück aus dem Acker nicht wachset,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'sondern der Mensch wird zu Unglück geboren, wie die Vogel schweben, emporzufliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Doch ich will jetzt von Gott reden und von ihm handeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'der grate Dinge tut, die nicht zu forschen sind, und Wunder, die nicht zu zahlen sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'der den Regen aufs Land gibt und lasset Wasser kommen auf die Straiten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'der die Niedrigen erhohet und den Betrübten emporhilft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Er macht zunichte die Anschlage der Listigen, daß es ihre Hand nicht ausfuhren kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Er fahet die Weisen in ihrer Listigkeit und sturzet der Verkehrten Rat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'daß sie des Tages in Finsternis laufen und tappen im Mittag wie in der Nacht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'und hilftdem Armen von dem Schwert und von ihrem Munde und von der Hand des Machtigen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'und ist des Armen Hoffnung, daü die Bosheit wird ihren Mund mussen zuhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Siehe, selig ist der Mensch, den Gott strafet; darum weigere dich der Zuchtigung des Allmachtigen nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Denn erverletzet und verbindet; er zerschmeitet, und seine Hand heilet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Aus sechs Trubsalen wird er dich erretten, und in der siebenten wird dich kein Ubel ruhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'In der Teurung wird er dich vom Tode erlosen und im Kriege von des Schwerts Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Er wird dich verbergen vor der Geitel der Zunge, daß du dich nicht furchtest vor dem Verderben, wenn es kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Im Verderben und Hunger wirst du lachen und dich vor den wilden Tieren im Lande nicht furchten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'sondern dein Bund wird sein mit den Steinen auf dem Felde, und die wilden Tiere auf dem Lande werden Frieden mit dir halten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'und wirst erfahren, daß deine Hutte Frieden hat; und wirst deine Behausung versorgen und nicht sundigen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'und wirst erfahren, daß deines Samens wird viel werden und deine Nachkommen wie das Gras auf Erden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'und wirst im Alter zu Grabe kommen, wie Garben eingefuhret werden zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Siehe, das haben wir erforschet, und ist also; dem gehorche und merke du dir\'s!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Wenn man meinen Jammer woge und mein Leiden zusammen in eine Waage legte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'so würde es schwerer sein denn Sand am Meer; darum ist\'s umsonst, was ich rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Denn die Pfeile des Allmachtigen stecken in mir, derselben Grimm sauft aus meinen Geist, und die Schrecknisse Gottes sind auf mich gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Das Wild schreiet nicht, wenn es Gras hat; der Ochse bloket nicht, wenn er sein Futter hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Kann man auch essen, das ungesalzen ist? Oder wer mag kosten das Weite um den Dotter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Was meiner Seele widerte anzuruhren, das ist meine Speise vor Schmerzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O daß meine Bitte geschahe, und Gott gabe mir, wes ich hoffe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Dali Gott anfinge und zerschluge mich und liete seine Hand gehen und zerscheiterte mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'So hatte ich noch Trost und wollte bitten in meiner Krankheit, daß er nur nicht schonete. Habe ich doch nicht verleugnet die Rede des Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Was ist meine Kraft, daß ich moge beharren? und welch ist mein Ende, daß meine Seele geduldig sollte sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Ist doch meine Kraft nicht steinern, so ist mein Fleisch nicht ehern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Habe ich doch nirgend keine Hilfe, und mein Vermogen istweg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Wer Barmherzigkeit seinem Nachsten weigert, der verlasset des Allmachtigen Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Meine Bruder gehen verachtlich vor mir uber, wie ein Bach, wie die Wasserstrome vorüberflielien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Doch, welche sich vor dem Reif scheuen, uber die wird der Schnee fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Zur Zeit, wenn sie die Hitze drucken wird, werden sie verschmachten, und wenn es heili wird, werden sie vergehen von ihrer Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Ihr Weg gehet beiseit aus; sie treten auf das Ungebahnte und werden umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Sie sehen auf die Wege Themas; auf die Pfade Reicharabias warten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Aber sie werden zuschanden werden, wenn\'s am sichersten ist, und sich schamen müssen, wenn sie dahin kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Denn ihr seid nun zu mir kommen; und weil ihr Jammer sehet, furchtet ihr euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Habe ich auch gesagt: Bringet her und von eurem Vermogen schenket mir');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'und errettet mich aus der Hand des Feindes und erloset mich von der Hand der Tyrannen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Lehret mich, ich will schweigen; und was ich nicht weiß, das unterweiset mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Warum tadelt ihr die rechte Rede? Wer ist unter euch, der sie strafen konnte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Ihr erdenket Worte, daß ihr nur strafet, und daß ihr nur paustet Worte, die mich verzagt machen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Ihr fallet uber einen armen Waisen und grabet eurem Nachsten Gruben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Doch weil ihr habt angehoben, sehet auf mich, ob ich vor euch mit Lügen bestehen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Antwortet, was recht ist; meine Antwort wird noch recht bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Was gilt\'s, ob meine Zunge unrecht habe und mein Mund Boses vorgebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Muß nicht der Mensch immer im Streit sein auf Erden, und seine Tage sind wie eines Taglohners?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Wie ein Knecht sich sehnet nach dem Schatten und ein Taglohner, daß seine Arbeit aus sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'also habe ich wohl ganze Monden vergeblich gearbeitet, und elende Nachte sind mirviel worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Wenn ich mich legte, sprach ich: Wann werde ich aufstehen? Und danach rechnete ich, wenn es Abend wollte werden; denn ich war ganz ein Scheusal jedermann, bis es finster ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Mein Fleisch ist urn und urn wurmig und kotig: meine Haut ist verschrumpft und zunichte worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Meine Tage sind leichter dahingeflogen denn eine Weberspule und sind vergangen, daß kein Aufhalten dagewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Gedenke, daß mein Leben ein Wind ist, und meine Augen nicht wiederkommen, zu sehen das Gute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Und kein lebendig Auge wird mich mehr sehen. Deine Augen sehen mich an; daruber vergehe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Eine Wolke vergehet und fahret dahin; also, wer in die Holle hinunterfahrt, kommt nicht wieder herauf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'und kommt nicht wieder in sein Haus, und sein Ort kennet ihn nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Darum will auch ich meinem Munde nicht wehren; ich will reden von der Angst meines Herzens und will heraussagen von der Betrubnis meiner Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Bin ich denn ein Meer Oder ein Walfisch, daß du mich so verwahrest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Wenn ich gedachte, mein Bett soil mich trosten, mein Lager soil mir\'s leichtern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'wenn ich mit mir selbst rede, so erschreckst du mich mit Traumen und machst mir Grauen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'daß meine Seele wünschet erhangen zu sein, und meine Gebeine den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Ich begehre nicht mehrzu leben. Hore auf von mir, denn meine Tage sind vergeblich gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Was ist ein Mensch, daß du ihn groß achtest und bekümmerst dich mit ihm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Du suchest ihn taglich heim und versuchest ihn alle Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Warum tustdu dich nicht von mir und lassest nicht ab, bis ich meinen Speichel schlinge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Habe ich gesundiget, was soil ich dir tun, o du Menschenhuter? Warum machst du mich, daß ich auf dich stoße und bin mir selbst eine Last?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Und warum vergibst du mir meine Missetat nicht und nimmst nicht weg meine Sunde? Denn nun werde ich mich in die Erde legen; und wenn man mich morgen suchet, werde ich nicht da sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Da antwortete Bildad von Suah und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Wie lange willst du solches reden und die Rede deines Mundes so einen stolzen Mut haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Meinest du, daß Gott unrecht richte, Oder der Allmachtige das Recht verkehre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Haben deine Sohne vor ihm gesundiget, so hat er sie verstoßen urn ihrer Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'So du aber dich beizeiten zu Gott tust und dem Allmachtigen flehest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'und du so rein und fromm bist, so wird er aufwachen zu dir und wird wieder aufrichten die Wohnung urn deiner Gerechtigkeit willen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'und was du zuerst wenig gehabt hast, wird hernach fast zunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Denn frage die vorigen Geschlechter und nimm dir vor, zu forschen ihre Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(Denn wir sind von gestern her und wissen nichts; unser Leben ist ein Schatten auf Erden.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Sie werden dich\'s lehren und dirsagen und ihre Rede aus ihrem Herzen hervorbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Kann auch das Schilf aufwachsen, wo es nicht feucht stehet, Oder Gras wachsen ohne Wasser?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Sonst wenn\'s noch in der Blute ist, ehe es abgehauen wird, verdorret es, ehe denn man Heu machet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'So geht es alien denen, die Gottes vergessen, und die Hoffnung der Heuchler wird verloren sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Denn seine Zuversicht vergehet, und seine Hoffnung ist eine Spinnwebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Erverlasset sich auf sein Haus und wird doch nicht bestehen; erwird sich dran halten, aber doch nicht stehen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Es hat wohl Fruchte, ehe denn die Sonne kommt; und Reiser wachsen hervor in seinem Garten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Seine Saat stehet dicke bei den Quellen und sein Haus auf Steinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Wenn er ihn aber verschlinget von seinem Ort, wird er sich gegen ihn stellen, als kennete er ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Siehe, das ist die Freude seines Wesens; und werden andere aus dem Staube wachsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Darum siehe, daß Gott nicht verwirft die Frommen und erhalt nicht die Hand der Boshaftigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'bis daß dein Mund voll Lachens werde und deine Lippen voll Jauchzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Die dich aber hassen; werden zuschanden werden, und der Gottlosen Hütte wird nicht bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Ja, ich weiß fast wohl, daß also ist, daß ein Mensch nicht rechtfertig bestehen mag gegen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Hat er Lust, mit ihm zu hadern, so kann er ihm auf tausend nicht eins antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Er istweise und machtig wem ist\'s je gelungen, der sich wider ihn gelegt hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Er versetzt Berge, ehe sie es inne werden, die er in seinem Zorn umkehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Er weget ein Land aus seinem Ort, daß seine Pfeiler zittern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Er spricht zur Sonne, so gehet sie nicht auf, und versiegelt die Sterne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Er breitet den Himmel aus allein und gehet auf den Wogen des Meers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Er machet den Wagen am Himmel und Orion und die Glucke und die Sterne gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Er tut grolie Dinge, die nicht zu forschen sind, und Wunder, deren keine Zahl ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Siehe, er gehet vor mir uber, ehe ich\'s gewahr werde, und verwandelt sich, ehe ich\'s merke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Siehe, wenn ergeschwind hinfahret, werwill ihn wiederholen? Wer will zu ihm sagen: Was machst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Er ist Gott, seinen Zorn kann niemand stillen; unter ihm müssen sich beugen die stolzen Herren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Wie sollt ich denn ihm antworten und Worte finden gegen ihn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Wenn ich auch gleich recht habe, kann ich ihm dennoch nicht antworten sondern ich mülite urn mein Recht flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Wenn ich ihn schon anrufe, und er mich erhoret, so glaube ich doch nicht, daß er meine Stimme hore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Denn erfahret uber mich mit Ungestüm und macht mir der Wunden viel ohne Ursache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Er lalit meinen Geist sich nicht erquicken, sondern macht mich voll Betrubnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Will man Macht; so isterzu machtig; will man Recht, werwill mein Zeuge sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Sage ich, daß ich gerecht bin; so verdammet er mich doch; bin ich fromm, so macht er mich doch zu Un recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Bin ich denn fromm, so darf sich’s meine Seele nicht annehmen. Ich begehre keines Lebens mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Das ist das Eine, das ich gesagt habe: Er bringet urn beide den Frommen und Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Wenn er anhebt zu geitieln, so dringet er fort bald zum Tode und spottet der Anfechtung der Unschuldigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Das Land aber wird gegeben unter die Hand des Gottlosen, daß er ihre Richter unterdrucke. Ist\'s nicht also? Wie sollte es anders sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Meine Tage sind schneller gewesen denn ein Laufer; sie sind geflohen und haben nichts Gutes erlebt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Sie sind vergangen wie die starken Schiffe, wie ein Adler fleugt zur Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Wenn ich gedenke, ich will meiner Klage vergessen und meine Gebarde lassen fahren und mich erquicken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'so furchte ich alle meine Schmerzen, weil ich weili, daß du mich nicht unschuldig sein lassest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Bin ich denn gottlos, warum leide ich denn solche vergebliche Plage?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Wenn ich mich gleich mit Schneewasser wunsche und reinigte meine Hande mit dem Brunnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'so wirst du mich doch tunken in Kot, und werden mir meine Kleider scheulilich anstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Denn er ist nicht meinesgleichen, dem ich antworten mochte, daü wir vor Gericht miteinander kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Es ist unter uns kein Schiedsmann, noch der seine Hand zwischen uns beide lege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Er nehme von mir seine Rute und lasse sein Schrecken von mir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'daß ich moge reden und mich nicht vor ihm furchten durfe; sonst kann ich nichts tun, das fur mich sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Meine Seele verdreulit mein Leben; ich will meine Klage bei mir gehen lassen und reden von Betrubnis meiner Seele');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'und zu Gott sagen: Verdamme mich nicht; lali mich wissen, warum du mit mir haderst!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Gefallt dir\'s, daß du Gewalt tust und mich verwirfst, den deine Hande gemacht haben, und machest der Gottlosen Vornehmen zu Ehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Hastdu denn auch fleischliche Augen, Oder siehest du, wie ein Mensch siehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Oder ist deine Zeit wie eines Menschen Zeit, Oder deine Jahre wie eines Mannes Jahre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'daß du nach meiner Missetat fragest und suchest meine Sunde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'So du doch weifit, wie ich nicht gottlos sei; so doch niemand ist, der aus deiner Hand erretten moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Deine Hande haben mich gearbeitet und gemacht alles, was ich urn und urn bin; und versenkest mich sogar!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Gedenke doch, daß du mich aus Leimen gemacht hast, und wirst mich wieder zu Erden machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Hastdu mich nicht wie Milch gemolken und wie Kase lassen gerinnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Du hast mir Hautund Fleisch angezogen, mit Beinen und Adern hast du mich zusammengefuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Leben und Wohltat hast du an mir getan, und dein Aufsehen bewahret meinen Odem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Und wiewohl du solches in deinem Herzen verbirgest, so weift ich doch, daß du des gedenkest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Wenn ich sundige, so merkest du es bald und lassest meine Missetat nicht ungestraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Bin ich gottlos, so ist mir aber wehe; bin ich gerecht, so darf ich doch mein Haupt nicht aufheben, als der ich voll Schmach bin und sehe mein Elend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Und wie ein aufgereckter Lowe jagest du mich und handelst wiederum greulich mit mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Du erneuest deine Zeugen wider mich und machst deines Zorns viel auf mich; es zerplagt mich eins über das andere mit Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Warum hast du mich aus Mutterleibe kommen lassen? Ach, daß ich ware umkommen, und mich nie kein Auge gesehen hatte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'So ware ich, als die nie gewesen sind, von Mutterleibe zum Grabe gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Will denn nicht ein Ende haben mein kurzes Leben, und von mir lassen, daß ich ein wenig erquickt würde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'ehe denn ich hingehe und komme nicht wieder, namlich ins Land der Finsternis und des Dunkels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'ins Land, da es stockdick finster ist, und da keine Ordnung ist, da es scheinet wie das Dunkel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Da antwortete Zophar von Naema und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Wenn einer lange geredet, muft er nicht auch horen? Muft denn ein Wascher immer recht haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Mussen die Leute deinem groften Schwatzen Schweigen, daß du spottest, und niemand dich beschame?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Du sprichst: Meine Rede ist rein, und lauter bin ich vordeinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ach, daß Gott mit dir redete und tate seine Lippen auf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'und zeigete die heimliche Weisheit! Denn er hatte wohl noch mehr an dir zu tun, auf daß du wissest, daß er deiner Sünden nicht aller gedenkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Meinest du, daß du so viel wissest, als Gott weift, und wollest alles so vollkommen treffen als der Allmachtige?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Er ist hoher denn der Himmel; was willst du tun? tiefer denn die Holle; was kannst du wissen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Langer denn die Erde und breiter denn das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'So er sie umkehrete Oder verburge Oder in einen Haufen wurfe, wer will\'s ihm wehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Denn er kennet die losen Leute, er siehet die Untugend, und sollte es nicht merken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Ein unnutzer Mann blahet sich; und ein geborener Mensch will sein wie ein junges Wild.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Wenn du dein Herz hattest gerichtet und deine Hande zu ihm ausgebreitet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'wenn du die Untugend, die in deiner Hand ist, hattest feme von dir getan, daß in deiner Hütte kein Unrecht bliebe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'so mochtestdu dein Antlitz aufheben ohne Tadel und wurdest test sein und dich nicht furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Dann wurdest du der Muhe vergessen und so wenig gedenken als des Wassers, das vorubergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Und die Zeit deines Lebens würde aufgehen wie der Mittag, und das Finstere würde ein lichter Morgen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Und dürftest dich des trosten, daß Hoffnung da sei; du würdest mit Ruhe ins Grab kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Und würdest dich legen, und niemand würde dich aufschrecken; und viele würden vor dir flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Aber die Augen der Gottlosen werden verschmachten, und werden nicht entrinnen mogen; denn ihre Hoffnung wird ihrer Seele fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Da antwortete Hiob und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Ja, ihr seid die Leute; mit euch wird die Weisheit sterben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Ich habe so wohl ein Herz als ihr und bin nicht geringer denn ihr; und wer ist, der solches nicht wisse?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Wer von seinem Nachsten verlachet wird, der wird Gott anrufen, der wird ihn erhoren. Der Gerechte und Fromme muft verlachet sein');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'und ist ein verachtet Lichtlein vor den Gedanken der Stolzen, stehet aber, daß sie sich dran argern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Der Verstorer Hütten haben die Fülle und toben wider Gott turstiglich, wiewohl es ihnen Gott in ihre Hande gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Frage doch das Vieh, das wird dich’s lehren, und die Vogel unter dem Himmel, die werden dir\'s sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Oder rede mit der Erde, die wird dich\'s lehren, und die Fische im Meer werden dir\'s erzahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Wer weift solches alles nicht, daß des HERRN Hand das gemacht hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'daß in seiner Hand ist die Seele alles des, das da lebet, und der Geist alles Fleisches eines jeglichen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Prüfet nicht das Ohr die Rede; und der Mund schmecket die Speise?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Ja, bei den Groftvatem ist die Weisheit und der Verstand bei den Alten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Bei ihm ist Weisheit und Gewalt, Rat und Verstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Siehe, wenn erzerbricht, so hilft kein Bauen; wenn erjemand verschleuftt, kann niemand aufmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Siehe, wenn erdas Wasser verschleuftt, so wird\'s alles durre; und wenn er\'s auslaftt, so kehret es das Land urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Er ist stark und führet es aus. Sein ist, der da irret, und der da verfuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Er fuhret die Klugen wie einen Raub und machet die Richter toll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Er loset auf der Konige Zwang und gurtet mit einem Gürtel ihre Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Er fuhret die Priesterwie einen Raub und lasset es fehlen den Festen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Er wendet weg die Lippen der Wahrhaftigen und nimmtweg die Sitten der Alten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Er schuttet Verachtung auf die Fursten und macht den Bund der Gewaltigen los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Er offnet die finstern Gründe und bringet heraus das Dunkel an das Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Er macht etliche zum großen Volk und bringet sie wieder um. Er breitet ein Volk aus und treibet es wieder weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Er nimmt weg den Mut der Obersten des Volks im Lande und macht sie irre auf einem Umwege, da kein Weg ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'dais sie in der Finsternis tappen ohne Licht; und macht sie irre wie die Trunkenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Siehe, das hat alles mein Auge gesehen und mein Ohrgehoret, und habe es verstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Was ihrwisset, das weiß ich auch, und bin nicht geringer denn ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Doch wollte ich gerne wider den Allmachtigen reden und wollte gerne mit Gott rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Denn ihr deutet es falschlich und seid alle unnutze Arzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Wollte Gott, ihr schwieget; so würdet ihr weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Horet doch meine Strafe und merket auf die Sache, davon ich rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Wollt ihr Gott verteidigen mit Unrecht und fur ihn List brauchen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Wollt ihr seine Person ansehen? Wollt ihr Gott vertreten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Wird\'s euch auch wohlgehen, wenn er euch richten wird? Meinet ihr, daß ihr ihn tauschen werdet, wie man einen Menschen tauschet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Erwird euch strafen, wo ihr Person ansehet heimlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Wird ereuch nicht erschrecken, wenn ersich wird hervortun, und seine Furcht wird uber euch fallen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Euer Gedachtnis wird verglichen werden der Asche, und euer Rucken wird wie ein Leimenhaufe sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Schweiget mir, daü ich rede; es soil mir nichts fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Was soil ich mein Fleisch mit meinen Zahnen beißen und meine Seele in meine Hande legen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Siehe, erwird mich doch erwurgen, und ich kann\'s nicht erwarten; doch will ich meine Wege vor ihm strafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Erwird ja mein Heil sein; denn es kommt kein Heuchler vor ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Floret meine Rede und meine Auslegung vor euren Ohren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Siehe, ich habe das Urteil schon gefallet; ich weili, daß ich werde gerecht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Wer ist, der mit mir rechten will? Aber nun muli ich schweigen und verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Zweierlei tu mir nur nicht, so will ich mich vor dir nicht verbergen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Lalideine Hand feme von mir sein, und dein Schrecken erschrecke mich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Rufe mir, ich will dirantworten; Oder ich will reden, antworte du mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Wie viel ist meiner Missetat und Sünden? Laß, mich wissen meine Ubertretung und Sünde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Warum verbirgest du dein Antlitz und haltst mich fur deinen Feind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Willst du wider ein fliegend Blatt so ernst sein und einen dürren Halm verfolgen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Denn du schreibest mir an Betrubnis und willst mich umbringen um der Sünden willen meiner Jugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Du hast meinen Fuß in Stock gelegt und hast acht auf alle meine Pfade und siehest auf die Fußtapfen meiner Fuße,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'der ich doch wie ein faul Aas vergehe und wie ein Kleid, das die Motten fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Der Mensch, vom Weibe geboren, lebt kurze Zeit und ist voll Unruhe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'gehet auf wie eine Blume und fallt ab, fleucht wie ein Schatten und bleibet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Und du tust deine Augen uber solchem auf, daß du mich vor dir in das Gericht ziehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Wer will einen Reinen finden bei denen, da keiner rein ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Er hat seine bestimmte Zeit, die Zahl seiner Monden stehet bei dir; du hast ein Ziel gesetzt, das wird er nicht ubergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Tue dich von ihm, daß er Ruhe habe, bis daß seine Zeit komme, deren er wie ein Taglohner wartet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Ein Baum hat Hoffnung, wenn er schon abgehauen ist, daß er sich wieder verandere, und seine Schoftlinge horen nicht auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ob seine Wurzel in der Erde veraltet und sein Stamm in dem Staube erstirbt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'grünet er doch wieder vom Geruch des Wassers und wachst daher, als ware er gepflanzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Wo ist aber ein Mensch, wenn ertot und umkommen und dahin ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Wie ein Wasser auslauft aus dem See und wie ein Strom versieget und vertrocknet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'so ist ein Mensch, wenn er sich legt, und wird nicht aufstehen und wird nicht aufwachen, solange der Himmel bleibt, noch von seinem Schlaf erweckt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ach, daß du mich in der Holle verdecktest und verbargest, bis dein Zorn sich lege, und setztest mir ein Ziel, daß du an mich denkest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Meinest du, ein toter Mensch werde wieder leben? Ich harre taglich; dieweil ich streite, bis daß meine Veranderung komme,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'daß du wollest mir rufen, und ich dirantworten, und wollest das Werk deiner Hande nicht ausschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Denn du hast schon meine Gange gezahlet; aber du wollest ja nicht achthaben auf meine Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Du hast meine Ubertretung ineinem Bundlein versiegelt und meine Missetat zusammengefasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Zerfallt doch ein Berg und vergehet, und ein Fels wird von seinem Ort versetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Wasser waschet Steine weg, und die Tropfen floften die Erde weg; aber des Menschen Hoffnung ist verloren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Denn du stoftest ihn gar urn, daß er dahinfahret, veranderst sein Wesen und lassest ihn fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Sind seine Kinder in Ehren, das weift er nicht; Oder ob sie geringe sind, des wird er nicht gewahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Weil er das Fleisch an sich tragt, muft er Schmerzen haben, und weil seine Seele noch bei ihm ist, muft er Leid tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Da antwortete Eliphas von Theman und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Soli ein weiser Mann so aufgeblasene Worte reden und seinen Bauch so blahen mit losen Reden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Du strafest mit Worten, die nicht taugen, und dein Reden ist kein nütze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Du hast die Furcht fahren lassen und redest zu verachtlich vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Denn deine Missetat lehret deinen Mund also, und hast erwahlet eine schalkhafte Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Dein Mund wird dich verdammen, und nicht ich; deine Lippen sollen dir antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Bist du der erste Mensch geboren? Bist du vor alien Hugeln empfangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Hast du Gottes heimlichen Rat gehoret? und ist die Weisheit selbst geringer denn du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Was weiftt du, das wir nicht wissen? Was verstehest du, das nicht bei uns sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Es sind Graue und Alte unter uns, die langer gelebt haben denn deine Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Sollten Gottes Trostungen so geringe vor dir gelten? Aber du hast irgend noch ein heimlich Stuck bei dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Was nimmt dein Herz vor? Was siehest du so stolz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Was setztsich dein Mut wider Gott, daß du solche Rede aus deinem Munde lassest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Was ist ein Mensch, daß er sollte rein sein, und daß der sollte gerecht sein, der vom Weibe geboren ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Siehe, unter seinen Heiligen ist keiner ohne Tadel, und die Himmel sind nicht rein vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Wie viel mehr ein Mensch, der ein Greuel und schnode ist, der Unrecht sauft wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Ich will dir\'szeigen, hore mirzu; und will dir erzahlen was ich gesehen habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'was die Weisen gesagt haben, und ihren Vatern nicht verhohlen gewesen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'welchen allein das Land gegeben ist, daß kein Fremder durch sie gehen muft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Der Gottlose bebet sein Leben lang; und dem Tyrannen ist die Zahl seiner Jahre verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Was er horet, das schrecket ihn; und wenn\'s gleich Friede ist, furchtet er sich, der Verderber komme;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'glaubt nicht, daß er moge dem Unglück entrinnen, und versiehet sich immer des Schwerts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Erzeucht hin und hernach Brot und dunket ihn immer, die Zeit seines Unglucks sei vorhanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Angst und Not schrecken ihn und schlagen ihn nieder als ein Konig mit einem Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Denn er hat seine Hand wider Gott gestrecket und wider den Allmachtigen sich gestraubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Er lauft mit dem Kopf an ihn und ficht halsstarriglich wider ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Er brustet sich wie ein fetter Wanst und macht sich fett und dick.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Erwird aberwohnen in verstdrten Stadten, da keine Haupter sind, sondern auf einem Haufen liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Erwird nicht reich bleiben, und sein Gut wird nicht bestehen, und sein Gluck wird sich nicht ausbreiten im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Unfall wird nicht von ihm lassen. Die Flamme wird seine Zweige verdorren und durch den Odem ihres Mundes ihn wegfressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Erwird nicht bestehen, denn er ist in seinem eiteln Dunkel betrogen, und eitel wird sein Lohn werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Erwird ein Ende nehmen, wenn\'s ihm uneben ist, und sein Zweig wird nicht grunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Erwird abgerissen werden wie eine unzeitige Traube vom Weinstock, und wie ein Olbaum seine Blüte abwirft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Denn der Heuchler Versammlung wird einsam bleiben, und das Feuerwird die Hütten fressen, die Geschenke nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Er gehet schwanger mit Unglück und gebiert Mühe, und ihr Bauch bringet Fehl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Ich habe solches oft gehoret. Ihr seid allzumal leidige T roster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Wollen die losen Worte kein Ende haben? Oder was macht dich so frech, also zu reden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Ich konnte auch wohl reden wie ihr. Wollte Gott, eure Seele ware an meiner Seele Statt! Ich wollte auch mit Worten an euch setzen und mein Haupt also uber euch schütteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Ich wollte euch starken mit dem Munde und mit meinen Lippen trosten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Aber wenn ich schon rede, so schonet mein der Schmerz nicht; lasse ich\'s anstehen, so gehet er nicht von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Nun aber macht er mich mude und verstoret alles, was ich bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Er hat mich runzlicht gemacht und zeuget wider mich; und mein Widersprecher lehnet sich wider mich auf und antwortet wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Sein Grimm reiliet, und der mir gram ist, beißet die Zahne uber mich zusammen; mein Widersacher funkelt mit seinen Augen auf mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Sie haben ihren Mund aufgesperret wider mich und haben mich schmahlich auf meine Backen geschlagen; sie haben ihren Mut miteinander an mir gekuhlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Gott hat mich ubergeben dem Ungerechten und hat mich in der Gottlosen Hande lassen kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Ich war reich, aber er hat mich zunichte gemacht; er hat mich beim Hals genommen und zerstoßen und hat mich ihm zum Ziel aufgerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Er hat mich umgeben mit seinen Schutzen; er hat meine Nieren gespalten und nicht verschonet; er hat meine Galle auf die Erde geschuttet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'er hat mir eine Wunde uber die andere gemacht; er ist an mich gelaufen wie ein Gewaltiger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Ich habe einen Sack urn meine Hautgenahet und habe mein Horn in den Staub gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Mein Antlitz ist geschwollen von Weinen, und meine Augenlider sind verdunkelt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'wiewohl kein Frevel in meiner Hand ist, und mein Gebet ist rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Ach, Erde, verdecke mein Blut nicht! und mein Geschrei müsse nicht Raum finden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Auch siehe da, mein Zeuge istim Himmel; und der mich kennet, ist in der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Meine Freunde sind meine Spotter; aber mein Auge tranet zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Wenn ein Mann konnte mit Gott rechten wie ein Menschenkind mit seinem Freunde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Aber die bestimmten Jahre sind kommen, und ich gehe hin des Weges, den ich nicht wiederkommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Mein Odem istschwach, und meine Tage sind abgekurzt, das Grab ist da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Niemand ist von mir getauschet, noch muß mein Auge darum bleiben in Betrubnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Ob du gleich einen Bürgen fur mich wolltest, wer will fur mich geloben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Du hast ihrem Herzen den Verstand verborgen, darum wirst du sie nicht erhohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Er rühmet wohl seinen Freunden die Ausbeute; aber seiner Kinder Augen werden verschmachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Er hat mich zum Sprichwort unter den Leuten gesetzt, und muß ein Wunder unter ihnen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Meine Gestalt istdunkel worden vor Trauern, und alle meine Glieder sind wie ein Schatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Daruber werden die Gerechten libel sehen, und die Unschuldigen werden sich setzen wider die Heuchler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Der Gerechte wird seinen Weg behalten, und der von reinen Handen wird stark bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Wohlan, so kehret euch alle her und kommt; ich werde doch keinen Weisen unter euch finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Meine Tage sind vergangen, meine Anschlage sind zertrennet, die mein Herz besessen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'und haben aus der Nacht Tag gemacht und aus dem Tage Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Wenn ich gleich lange harre, so ist doch die Holle mein Haus, und in Finsternis ist mein Bett gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Die Verwesung heiße ich meinen Vater und die Würmer meine Mutter und meine Schwester.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Was soil ich harren? und wer achtet mein Hoffen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Hinunter in die Holle wird es fahren und wird mit mirim Staube liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Da antwortete Bildad von Suah und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Wann wollt ihrder Rede ein Ende machen? Merket doch, danach wollen wir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Warum werden wir geachtet wie Vieh und sind so unrein vor euren Augen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Willst du vor Bosheit bersten? Meinest du, daß urn deinetwillen die Erde verlassen werde, und der Fels von seinem Ort versetzt werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Auch wird das Licht der Gottlosen verloschen, und der Funke seines Feuers wird nicht leuchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Das Licht wird finster werden in seiner Hutte und seine Leuchte fiber ihm verloschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Die Zugange seiner Habe werden schmal werden, und sein Anschlag wird ihn fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Denn er ist mit seinen Fußen in Strick gebracht und wandelt im Netze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Der Strick wird seine Fersen halten, und die Türstigen werden ihn erhaschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Sein Strick ist gelegt in die Erde und seine Falle auf seinen Gang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Urn und urn wird ihn schrecken plotzliche Furcht, daß er nicht weiß, wo er hinaus soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Hunger wird seine Habe sein, und Ungluck wird ihm bereitet sein und anhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Die Starke seiner Haut wird verzehret werden, und seine Starke wird verzehren der Fürst des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Seine Hoffnung wird aus seiner Hutte gerottet werden, und sie werden ihn treiben zum Konige des Schreckens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'In seiner Hutte wird nichts bleiben; fiber seine Hutte wird Schwefel gestreuet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Von unten werden verdorren seine Wurzeln und von oben abgeschnitten seine Ernte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sein Gedachtnis wird vergehen im Lande, und wird keinen Namen haben auf der Gasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Er wird vom Licht in die Finsternis vertrieben werden und vom Erdboden verstoßen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Er wird keine Kinder haben und keine Neffen unter seinem Volk; es wird ihm keiner überbleiben in seinen Gütern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Die nach ihm kommen, werden sich über seinen Tag entsetzen; und die vor ihm sind, wird eine Furcht ankommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Das ist die Wohnung des Ungerechten, und dies ist die Statte des, der Gott nicht achtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Was plaget ihrdoch meine Seele und peiniget mich mit Worten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Ihr habt mich nun zehnmal gehohnet und schamet euch nicht, daß ihr mich also umtreibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Irre ich, so irre ich mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Aber ihr erhebet euch wahrlich wider mich und scheltet mich zu meiner Schmach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Merket doch einst, daß mir Gott unrecht tut und hat mich mit seinem Jagestrick umgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Siehe, ob ich schon schreie uber Frevel, so werde ich doch nicht erhoret; ich rufe, und ist kein Recht da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Er hat meinen Weg verzaunet, daß ich nicht kann hinubergehen, und hat Finsternis auf meinen Steig gestellet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Er hat meine Ehre mir ausgezogen und die Krone von meinem Haupt genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Er hat mich zerbrochen urn und urn und laßt mich gehen, und hat ausgerissen meine Hoffnung wie einen Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Sein Zorn ist über mich ergrimmet, und er achtet mich fur seinen Feind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Seine Kriegsleute sind miteinander kommen und haben ihren Weg über mich gepflastert und haben sich urn meine Hütte her gelagert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Er hat meine Brüder feme von mir getan, und meine Verwandten sind mirfremd worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Meine Nachsten haben sich entzogen, und meine Freunde haben mein vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Meine Hausgenossen und meine Magde achten mich fürfremd, ich bin unbekannt worden vor ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Ich rief meinem Knecht, und er antwortete mir nicht; ich mußte ihm flehen mit eigenem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Mein Weib stellet sich fremd, wenn ich ihr rufe; ich muß flehen den Kindern meines Leibes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Auch die jungen Kinder geben nichts auf mich; wenn ich mich wider sie setze, so geben sie mir bose Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Alle meine Getreuen haben Greuel an mir; und die ich liebhatte, haben sich wider mich gekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Mein Gebein hanget an meiner Haut und Fleisch, und kann meine Zahne mit der Haut nicht bedecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Erbarmet euch mein, erbarmet euch mein, ihr, meine Freunde; denn die Hand Gottes hat mich geruhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Warum verfolget ihr mich gleich so wohl als Gott und konnet meines Fleisches nicht satt werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ach, daß meine Reden geschrieben wurden! Ach, daß sie in ein Buch gestellet wurden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'mit einem eisernen Griffel auf Blei und zu ewigem Gedachtnis in einen Fels gehauen wurden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Aber ich weiß, daß mein Erloser lebet; und er wird mich hernach aus der Erde auferwecken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'und werde danach mit dieser meiner Haut umgeben werden und werde in meinem Fleisch Gott sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Denselben werde ich mir sehen, und meine Augen werden ihn schauen, und kein Fremder. Meine Nieren sind verzehret in meinem Schoß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Denn ihr sprechet: Wie wollen wir ihn verfolgen und eine Sache zu ihm finden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Furchtet euch vor dem Schwert; denn das Schwert ist der Zorn uber die Missetat, auf daß ihr wisset, daß ein Gericht sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Da antwortete Zophar von Naema und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Darauf muß ich antworten und kann nicht harren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Und will gerne horen, wer mir das soil strafen und tadeln; denn der Geist meines Verstandes soil fur mich antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Weißt du nicht, daß es allezeit so gegangen ist, seit daß Menschen auf Erden gewesen sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'daß der Ruhm der Gottlosen stehet nicht lange, und die Freude des Heuchlers wahret einen Augenblick?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Wenn gleich seine Hohe in den Himmel reichet und sein Haupt an die Wolken rühret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'so wird er doch zuletzt umkommen wie ein Kot, daß die, vor denen er ist angesehen, werden sagen: Wo ist er?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Wie ein Traum vergehet, so wird er auch nicht funden werden, und wie ein Gesicht in der Nacht verschwindet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Welch Auge ihn gesehen hat, wird ihn nicht mehr sehen, und seine Statte wird ihn nicht mehr schauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Seine Kinder werden betteln gehen, und seine Hand wird ihm Mühe zu Lohn geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Seine Beine werden seine heimliche Sünde wohl bezahlen und werden sich mit ihm in die Erde legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Wenn ihm die Bosheit gleich in seinem Munde wohl schmeckt, wird sie doch ihm in seiner Zunge fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Sie wird aufgehalten und ihm nicht gestattet, und wird ihm gewehret werden in seinem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Seine Speise inwendig im Leibe wird sich verwandeln in Otterngalle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Die Güter, die er verschlungen hat, muft er wieder ausspeien; und Gott wird sie aus seinem Bauch stolen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Erwird der Ottern Galle saugen, und die Zunge der Schlange wird ihn toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Er wird nicht sehen die Strome noch die Wasserbache, die mit Honig und Butter flieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Erwird arbeiten und des nicht genietien; und seine Güter werden andern, daß er deren nicht froh wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Denn er hat unterdruckt und verlassen den Armen; er hat Hauser zu sich gerissen, die er nicht erbauet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Denn sein Wanst konnte nicht voll werden, und wird durch sein kostlich Gut nicht entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Es wird seiner Speise nicht uberbleiben; darum wird sein gut Leben keinen Bestand haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Wenn er gleich die Fülle und genug hat, wird ihm doch angst werden; allerhand Mühe wird über ihn kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Es wird ihm der Wanst einmal voll werden, und er wird den Grimm seines Zornes über ihn senden; er wird uber ihn regnen lassen seinen Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Erwird fliehen vordem eisernen Harnisch, und der eherne Bogen wird ihn verjagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Ein blofi Schwert wird durch ihn ausgehen, und des Schwerts Blitz, der ihm bitter sein wird, wird mit Schrecken uber ihn fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Es ist keine Finsternis da, die ihn verdecken mochte. Eswird ihn ein Feuerverzehren, das nicht aufgeblasen ist; und wer ubrig ist in seiner Hutte, dem wird\'s ubel gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Der Himmel wird seine Missetat eroffnen, und die Erde wird sich wider ihn setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Das Getreide in seinem Hause wird weggeführet werden, zerstreuet am Tage seines Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Das ist der Lohn eines gottlosen Menschen bei Gott und das Erbe seiner Rede bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Horet doch zu meiner Rede und lasset euch raten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Vertraget mich, dati ich auch rede, und spottet danach mein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Handele ich denn miteinem Menschen, daß mein Mut hierin nicht sollte unwillig sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Kehret euch her zu mir; ihr werdet sauer sehen und die Hand aufs Maul legen müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Wenn ich daran gedenke, so erschrecke ich, und Zittern kommt mein Fleisch an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Warum leben denn die Gottlosen, werden alt und nehmen zu mit Gutern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Ihr Same ist sicher urn sie her, und ihre Nachkommlinge sind bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Ihr Haus hat Frieden vorder Furcht, und Gottes Rute ist nicht über ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Seine Ochsen lasset man zu, und miftrat ihm nicht; seine Kuh kalbet und ist nicht unfruchtbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Ihre jungen Kinder gehen aus wie eine Herde, und ihre Kinder lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Sie jauchzen mit Pauken und Harfen und sind frohlich mit Pfeifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Sie werden alt bei guten Tagen und erschrecken kaum einen Augenblick vorder Holle,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'die doch sagen zu Gott: Hebe dich von uns, wir wollen von deinen Wegen nicht wissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Wer ist der Allmachtige, daß wir ihm dienen sollten, Oder was sind wir gebessert, so wir ihn anrufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Aber siehe, ihr Gut stehet nicht in ihren Handen; darum soil der Gottlosen Sinn feme von mir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Wie wird die Leuchte der Gottlosen verloschen und ihr Ungluck über sie kommen! Er wird Herzeleid austeilen in seinem Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Sie werden sein wie Stoppeln vor dem Winde und wie Spreu, die der Sturmwind wegführet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Gott behalt desselben Ungluck auf seine Kinder. Wenn er\'s ihm vergelten wird, so wird man\'s inne werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Seine Augen werden sein Verderben sehen, und vom Grimm des Allmachtigen wird er trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Denn wer wird Gefallen haben an seinem Hause nach ihm? Und die Zahl seiner Monden wird kaum halb bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Wer will Gott lehren, der auch die Hohen richtet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Dieser stirbt frisch und gesund in allem Reichtum und voller Genüge;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'sein Melkfaft ist voll Milch, und seine Gebeine werden gemastet mit Mark;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'jener aber stirbt mit betrubter Seele und hat nie mit Freuden gegessen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'und liegen gleich miteinander in der Erde, und Würmer decken sie zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Siehe, ich kenne eure Gedanken wohl und euer frevel Vornehmen wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Denn ihr sprechet: Wo ist das Haus des Fursten, und wo ist die Hutte, da die Gottlosen wohneten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Redet ihr doch davon wie der gemeine Pobel und merket nicht, was jener Wesen bedeutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Denn der Bose wird behalten auf den Tag des Verderbens, und auf den Tag des Grimms bleibet er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Wer will sagen, was erverdienet, wenn man\'s aufterlich ansiehet? Wer will ihm vergelten, was er tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Aber erwird zum Grabe gerissen und muft bleiben bei dem Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Es gefiel ihm wohl der Schlamm des Bachs, und alle Menschen werden ihm nachgezogen; und derer, die vor ihm gewesen sind, ist keine Zahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Wie trostet ihr mich so vergeblich, und eure Antwort findet sich unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Da antwortete Eliphas von Theman und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Was darf Gott eines Starken, und was nützt ihm ein Kluger?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Meinest du, dafi dem Allmachtigen gefalle, da(3> du dich so fromm machest? Oder was hilft\'s ihm, ob du deine Wege gleich ohne Wandel achtest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Meinest du, erwird sich vor dir furchten, dich zu strafen, und mit dir vor Gericht treten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ja, deine Bosheit ist zu groß, und deiner Missetat ist kein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Du hast etwa deinem Bruder ein Pfand genommen ohne Ursache, du hast den Nackenden die Kleider ausgezogen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'du hast die Muden nicht getranket mit Wasser und hast dem Hungrigen dein Brot versagt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'du hast Gewalt im Lande geubet und prachtig drinnen gesessen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'die Witwen hast du leer lassen gehen und die Arme der Waisen zerbrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Darum bist du mit Stricken umgeben, und Furcht hat dich plotzlich erschrecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Solltest du denn nicht die Finsternis sehen, und die Wasserflut dich nicht bedecken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Siehe, Gott ist hoch droben im Himmel und siehet die Sterne droben in der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Und du sprichst: Was weifi Gott? Soilt er, das im Dunkeln ist, richten konnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Die Wolken sind seine Vordecke, und siehet nicht, und wandelt im Umgang des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Willstdu der Welt Lauf achten, darinnen die Ungerechten gegangen sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'die vergangen sind, ehe denn es Zeitwar, und das Wasser hat ihren Grund weggewaschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'die zu Gott sprachen: Heb dich von uns, was sollte der Allmachtige ihnen tun konnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'soerdoch ihr Haus mit Gütern füllete? Aber der Gottlosen Rat sei feme von mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Die Gerechten werden sehen und sich freuen, und der Unschuldige wird ihrer spotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Was gilt\'s, ihr Wesen wird verschwinden und ihr Ubriges das Feuer verzehren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'So vertrage dich nun mit ihm und habe Frieden; daraus wird dir viel Gutes kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Hore das Gesetz von seinem Munde und fasse seine Rede in dein Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Wirstdu dich bekehren zu dem Allmachtigen, so wirst du gebauet werden und Unrecht feme von deiner Hütte tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'so wirst du fur Erde Gold geben und fur die Felsen guldene Bache;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'und der Allmachtige wird dein Gold sein, und Silber wird dir zugehauft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Dann wirst du deine Lust haben an dem Allmachtigen und dein Antlitz zu Gott aufheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'So wirst du ihn bitten, und er wird dich horen; und wirst deine Gelubde bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Was du wirst vornehmen, wird er dir lassen gelingen; und das Lichtwird auf deinem Wege scheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Denn die sich demutigen, die erhohet er; und wer seine Augen niederschlagt, der wird genesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Und der Unschuldige wird errettet werden; er wird aber errettet urn seiner Hande Reinigkeit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Meine Rede bleibet noch betrubt; meine Macht ist schwach uber meinem Seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ach, dall ich wüßte, wie ich ihn finden und zu seinem Stuhl kommen mochte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'und das Recht vor ihm sollte vorlegen und den Mund voll Strafe fassen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'und erfahren die Rede, die er mir antworten, und vernehmen, was er mir sagen wurde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Will er mit grofier Macht mit mir rechten? Er stelle sich nicht so gegen mich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'sondern lege mir\'s gleich vor, so will ich mein Recht wohl gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Aber gehe ich nun stracks vor mich, so ist er nicht da; gehe ich zurück, so spüre ich ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Ist er zur Linken, so ergreife ich ihn nicht; verbirget er sich zur Rechten, so sehe ich ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Er aber kennet meinen Weg wohl. Erversuche mich, so will ich erfunden werden wie das Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Denn ich setze meinen Fuli auf seine Bahn und halte seinen Weg und weiche nicht ab');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'und trete nicht von dem Gebot seiner Lippen; und bewahre die Rede seines Mundes mehr, denn ich schuldig bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Er ist einig, wer will ihm antworten? Und er macht es, wie er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Und wenn er mir gleich vergilt, was ich verdienet habe, so ist sein noch mehr dahinten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Darum erschrecke ich vor ihm; und wenn ich\'s merke, so furchte ich mich vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Gott hat mein Herz blode gemacht, und der Allmachtige hat mich erschrecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Denn die Finsternis macht kein Ende mit mir, und das Dunkel will vor mir nicht verdeckt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Warum sollten die Zeiten dem Allmachtigen nicht verborgen sein? Und die ihn kennen, sehen seine Tage nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Sie treiben die Grenzen zurück; sie rauben die Herden und weiden sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Sie treiben der Waisen Esel weg und nehmen der Witwen Ochsen zu Pfande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Die Armen müssen ihnen weichen, und die Durfligen im Lande müssen sich verkriechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Siehe, das Wild in der Wuste gehet heraus, wie sie pflegen, frühe zum Raub, daß sie Speise bereiten fur die Jungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Sie ernten auf dem Acker alles, was er tragt, und lesen den Weinberg, den sie mit Unrecht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Die Nackenden lassen sie liegen und lassen ihnen keine Decke im Frost, denen sie die Kleider genommen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'daß sie sich müssen zu den Felsen halten, wenn ein Platzregen von den Bergen auf sie giefit, weil sie sonst keinen Trost haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Sie reilien das Kind von den Brüsten und machen\'s zum Waisen und machen die Leute arm mit Pfanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Den Nackenden lassen sie ohne Kleider gehen und den Hungrigen nehmen sie die Garben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Sie zwingen sie, 01 zu machen auf ihrer eigenen Mühle und ihre eigene Kelterzu treten, und lassen sie doch Durst leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Sie machen die Leute in der Stadt seufzend und die Seelen der Erschlagenen schreiend; und Gott stürzet sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Darum sind sie abtrünnig worden vom Licht und kennen seinen Weg nicht und kehren nicht wieder zu seiner Stralie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Wenn der Tag anbricht, stehetauf der Morder und erwürget den Armen und Dürftigen; und des Nachts ist er wie ein Dieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Das Auge des Ehebrechers hat acht auf das Dunkel und spricht: Mich siehet kein Auge; und verdecket sein Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Im Finstern brichterzu den Hausern ein. Des Tages verbergen sie sich miteinander und scheuen das Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Denn wo ihnen der Morgen kommt, ist\'s ihnen wie eine Finsternis; denn er fühlet das Schrecken der Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Er fahret leichtfertig wie aufeinem Wasser dahin; seine Habe wird geringe im Lande, und bauet seinen Weinberg nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Die Holle nimmt weg, die da sündigen, wie die Hitze und Dürre das Schneewasser verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Es werden sein vergessen die Barmherzigen; seine Lust wird wurmig werden; sein wird nicht mehr gedacht; er wird zerbrochen werden wie ein fauler Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Er hat beleidiget die Einsame, die nicht gebiert, und hat der Witwe kein Gutes getan');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'und die Machtigen unter sich gezogen mit seiner Kraft. Wenn er stehet, wird er seines Lebens nicht gewifi sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Er macht ihm wohl selbst eine Sicherheit, darauf er sich verlasse; doch sehen seine Augen auf ihr Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Sie sind eine kleine Zeit erhaben und werden zunichte und unterdruckt und ganz und gar ausgetilget werden, und wie die erste Blute an den Ahren werden sie abgeschlagen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Ist\'s nicht also? Wohlan, wer will mich Lugen strafen und bewahren, dafi meine Rede nichts sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Da antwortete Bildad von Suah und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Ist nicht die Herrschaft und Furcht bei ihm, der den Frieden macht unter seinen Hochsten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Wer will seine Kriegsleute zahlen? Und fiber weichen gehet nicht auf sein Licht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Und wie mag ein Mensch gerecht vor Gott sein? Und wie mag rein sein eines Weibes Kind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Siehe, der Mond scheinet noch nicht, und die Sterne sind noch nicht rein vor seinen Augen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'wieviel wenigerein Mensch, die Made, und ein Menschenkind, der Wurm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Hiob antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Wem stehest du bei? Dem, der keine Kraft hat? Hilfst du dem, der keine Starke in Armen hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Wem gibst du Rat? Dem, der keine Weisheit hat? und zeigest einem Machtigen, wie er\'s ausfuhren soli?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Fur wen redest du, und fur wen gehet der Odem von dir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Die Riesen angsten sich unter den Wassern und die bei ihnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Die Holle ist aufgedeckt vor ihm, und das Verderben hat keine Decke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Er breitet aus die Mitternacht nirgend an und hanget die Erde an nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Er fasset das Wasser zusammen in seine Wolken, und die Wolken zerreifien drunter nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Er halt seinen Stuhl und breitet seine Wolken davor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Er hat urn das Wasser ein Ziel gesetzt, bis das Licht samt der Finsternis vergehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Die Saulen des Himmels zittern und entsetzen sich vorseinem Schelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Vor seiner Kraft wird das Meer plotzlich ungestüm, und vor seinem Verstand erhebet sich die Hohe des Meers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Am Himmel wird\'s schon durch seinen Wind, und seine Hand bereitet die gerade Schlange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Siehe, also gehet sein Tun, aber davon haben wir ein gering Wortlein vernommen. Wer will aber den Donner seiner Macht verstehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Und Hiob fuhrfort und hub an seine Spruche und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'So wahr Gott lebt, der mir mein Recht nicht gehen lasset, und der Allmachtige, der meine Seele betrubet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'solange mein Odem in mir ist, und das Schnauben von Gott in meiner Nase ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'meine Lippen sollen nichts Unrechts reden, und meine Zunge soil keinen Betrug sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Das sei feme von mir, daß ich euch recht gebe; bis da(S mein Ende kommt, will ich nicht weichen von meiner Frommigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Von meiner Gerechtigkeit, die ich habe, will ich nicht lassen; mein Gewissen beißt mich nicht meines ganzen Lebens halber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Aber mein Feind wird erfunden werden ein Gottloser, und der sich wider mich auflehnet, ein Ungerechter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Denn was ist die FHoffnung des FHeuchlers, daß er so geizig ist, und Gott doch seine Seele hinreüßet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Meinest du, da(S Gott sein Schreien horen wird, wenn die Angst über ihn kommt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Wie kann eran dem Allmachtigen Lust haben und Gott etwa anrufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Ich will euch lehren von der FHand Gottes; und was bei dem Allmachtigen gilt, will ich nicht verhehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Siehe, ihr haltet euch alle fur klug. Warum gebt ihr denn solch unnutze Dinge vor?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Das ist der Lohn eines gottlosen Menschen bei Gott und das Erbe der Tyrannen, das sie von dem Allmachtigen nehmen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Wird erviel Kinder haben, so werden sie des Schwerts sein; und seine Nachkommlinge werden des Brats nicht satt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Seine Ubrigen werden im Tode begraben werden, und seine Witwen werden nicht weinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Wenn erßeld zusammenbringetwie Erde und sammelt Kleider wie Leimen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'so wird ereswohl bereiten; aber der Gerechte wird es anziehen, und der Unschuldige wird das Geld austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Er bauet sein Haus wie eine Spinne, und wie ein Hüter einen Schauer machet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Der Reiche, wenn er sich legt, wird er\'s nicht mitraffen; er wird seine Augen auftun, und da wird nichts sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Es wird ihn Schrecken uberfallen wie Wasser; des Nachts wird ihn das Ungewitter wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Der Ostwind wird ihn wegfuhren, daß er dahinfahret, und Ungestum wird ihn von seinem Ort treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Er wird solches uber ihn führen und wird sein nicht schonen; es wird ihm alles aus seinen Handen entfliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Man wird über ihn mit den Flanden klappen und über ihn zischen, da er gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Es hat das Silber seine Gange und das Gold seinen Ort, da man es schmelzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Eisen bringet man aus der Erde, und aus den Steinen schmelzt man Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Es wird je des Finstern etwa ein Ende, und jemand findet ja zuletzt den Schiefer tief verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Es bricht ein solcher Bach hervor, dafi, die darum wohnen, den Weg daselbst verlieren; und fallt wieder und schief M dahin von den Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Man bringet auch Feuer unten aus der Erde, da doch oben Speise auf wachst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Man findet Saphir an etlichen Orten und Erdenklofie, da Gold ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Den Steig kein Vogel erkannt hat und kein Geiersauge gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Es haben die stolzen Kinder nicht drauf getreten, und ist kein Lowe drauf gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Auch legt man die FHand an die Felsen und grabet die Berge urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Man reißet Bache aus den Felsen; und alles, was kostlich ist, siehet das Auge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Man wehret dem Strom des Wassers und bringet, das verborgen drinnen ist, ans Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Wo will man aber Weisheit finden, und wo ist die Statte des Verstandes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Niemand weifi, wo sie liegt, und wird nicht funden im Lande der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Der Abgrund spricht: Sie ist in mir nicht; und das Meer spricht: Sie ist nicht bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Man kann nicht Gold urn sie geben, noch Silber darwagen, sie zu bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Es gilt ihr nicht gleich ophirisch Gold Oder kostlicher Onyx und Saphir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Gold und Demant mag ihr nicht gleichen, noch urn sie gulden Kleinod wechseln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Ramoth und Gabis achtet man nicht. Die Weisheit ist hoher zu wagen denn Perlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topasius aus Mohrenland wird ihr nicht gleich geschatzt, und das reinste Gold gilt ihr nicht gleich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Woher kommt denn die Weisheit, und wo ist die Statte des Verstandes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Sie ist verhohlen vor den Augen aller Lebendigen, auch verborgen den Vogeln unter dem Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Die Verdammnis und der Tod sprechen: Wir haben mit unsern Ohren ihr Gerucht gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Gott weili den Weg dazu und kennet ihre Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Denn er siehet die Enden der Erde und schauet alles, was unter dem Himmel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Da er dem Winde sein Gewicht machte und setzte dem Wasser sein gewisses Mali,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'da er dem Regen ein Ziel machte und dem Blitz und Donner den Weg,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'da sah er sie und erzahlete sie, bereitete sie und erfand sie;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'und sprach zum Menschen: Siehe, die Furcht des HERRN, das ist Weisheit, und meiden das Bose, das ist Verstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Und Hiob hub abermal an seine Spruche und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'O daß ich ware wie in den vorigen Monden, in den Tagen, da mich Gott behutete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'da seine Leuchte uber meinem Haupte schien, und ich bei seinem Licht in der Finsternis ging;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'wie ich war zur Zeit meiner Jugend, da Gottes Geheimnis uber meiner Hutte war;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'da der Allmachtige noch mit mir war und meine Kinder um mich her;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'da ich meine Tritte wusch in Butter, und die Felsen mir Olbache gossen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'da ich ausging zum Tor in der Stadt und lieft meinen Stuhl auf der Gasse bereiten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'da mich die Jungen sahen und sich versteckten, und die Alten vor mir aufstunden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'da die Obersten aufhoreten zu reden, und legten ihre Hand auf ihren Mund;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'da die Stimme der Fursten sich verkroch, und ihre Zunge an ihrem Gaumen klebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Denn welches Ohr mich horete, der preisete mich selig, und welches Auge mich sah, der ruhmte mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Denn ich errettete den Armen, der da schrie, und den Waisen, der keinen Heifer hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Der Segen des, der verderben sollte, kam uber mich; und ich erfreuete das Herz der Witwe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Gerechtigkeit war mein Kleid, das ich anzog wie einen Rock; und mein Rechtwar mein fürstlicher Hut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Ich war des Blinden Auge und des Lahmen Fufie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Ich war ein Vater der Armen; und welche Sache ich nicht wuftte, die erforschete ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Ich zerbrach die Backenzahne des Ungerechten und rift den Raub aus seinen Zahnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Ich gedachte: Ich will in meinem Nest ersterben und meiner Tage viel machen wie Sand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Meine Saat ging auf am Wasser; und der Tau blieb uber meiner Ernte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Meine Herrlichkeit erneuerte sich immer an mir; und mein Bogen besserte sich in meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Man horete mirzu, und schwiegen und warteten auf meinen Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Nach meinen Worten redete niemand mehr; und meine Rede troff auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Sie warteten auf mich wie auf den Regen und sperreten ihren Mund auf als nach dem Abendregen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Wenn ich sie anlachte, wurden sie nicht zu kühn darauf, und das Licht meines Angesichts machte mich nicht geringer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Wenn ich zu ihrem Geschafte wollte kommen, so muftte ich obenan sitzen und wohnete wie ein Konig unter Kriegsknechten, da ich trostete, die Leid trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Nun aber lachen mein, die jünger sind denn ich, welcher Vater ich verachtet hatte, zu stellen unter meine Schafhunde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'welcher Vermogen ich fur nichts hielt, die nicht zum Alter kommen konnten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'die vor Hunger und Kummer einsam flohen in die Einode, neulich verdorben und elend worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'die da Nesseln ausrauften um die Busche, und Wacholderwurzel war ihre Speise;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'und wenn sie die herausrissen, jauchzeten sie druber wie ein Dieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'An den grausamen Bachen wohneten sie, in den Lochern der Erde und Steinritzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Zwischen den Buschen riefen sie und unter den Disteln sammelten sie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'die Kinder loser und verachteter Leute, die die Geringsten im Lande waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Nun bin ich ihr Saitenspiel worden und muft ihr Marlein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Sie haben einen Greuel an mir und machen sich feme von mir und schonen nicht, vor meinem Angesicht zu speien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Sie haben mein Seil ausgespannet und mich zunichte gemacht und das Meine abgezaumet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Zur Rechten, da ich grünete, haben sie sich wieder mich gesetzt und haben meinen Fuft ausgestoften; und haben uber mich einen Weg gemacht, mich zu verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Sie haben meine Steige zerbrochen; eswar ihnen so leicht, mich zu beschadigen, daß sie keiner Hilfe dazu bedurften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Sie sind kommen, wie zurweiten Lücke herein, und sind ohne Ordnung dahergefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Schrecken hat sich gegen mich gekehret und hat verfolget wie der Wind meine Herrlichkeit und wie eine laufende Wolke meinen glückseligen Stand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Nun aber gieftt sich aus meine Seele uber mich, und mich hat ergriffen die elende Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Des Nachts wird mein Gebein durchbohret allenthalben, und die mich jagen, legen sich nicht schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Durch die Menge der Kraft werde ich anders und anders gekleidet; und man gurtet mich damit wie mit dem Loch meines Rocks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Man hat mich in Kot getreten und gleich geachtet dem Staub und Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Schreie ich zu dir, so antwortest du mir nicht; trete ich hervor, so achtest du nicht auf mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Du bist mir verwandelt in einen Grausamen und zeigest deinen Gram an mir mit der Starke deiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Du hebest mich auf und lassest mich auf dem Winde fahren und zerschmelzest mich kraftiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Denn ich weift, du wirst mich dem Tode überantworten; da istdas bestimmte Haus aller Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Doch wird er nicht die Hand ausstrecken ins Beinhaus, und werden nicht schreien vor seinem Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Ich weinete ja in der harten Zeit, und meine Seele jammerte der Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Ich wartete des Guten, und kommt das Bose; ich hoffte aufs Licht, und kommt Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Meine Eingeweide sieden und horen nicht auf; mich hat uberfallen die elende Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Ich gehe schwarz einher, und brennet mich doch keine Sonne nicht; ich stehe auf in der Gemeine und schreie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Ich bin ein Bruder der Schlangen und ein Geselle derßtraulien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Meine Haut über mir ist schwarz worden, und meine Gebeine sind verdorret vor Hitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Meine Harfe ist eine Klage worden und meine Pfeife ein Weinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Ich habe einen Bund gemacht mit meinen Augen, daß ich nicht achtete auf eine Jungfrau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Was gibt mir aber Gott zu Lohn von oben? und was fur ein Erbe der Allmachtige von der Hohe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Sollte nicht billiger der Ungerechte solch Unglück haben, und ein Ubeltater so verstolien werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Siehet er nicht meine Wege und zahlet alle meine Gange?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Hab ich gewandelt in Eitelkeit? Oder hat mein Fußgeeiletzum Betrug?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'So wage man mich auf rechter Waage, so wird Gott erfahren meine Frommigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Hat mein Gang gewichen aus dem Wege und mein Herz meinen Augen nachgefolget, und ist etwas in meinen Handen beklebet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'so musse ich saen, und ein anderer fresse es, und mein Geschlecht musse ausgewurzelt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Hat sich mein Herz lassen reizen zum Weibe, und habe an meines Nachsten Turgelauert,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'so musse mein Weib von einem andern geschandet werden, und andere mussen sie beschlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Denn das ist ein Laster und eine Missetat fur die Richter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Denn das ware ein Feuer, das bis ins Verderben verzehrete und all mein Einkommen auswurzelte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Hab ich verachtet das Recht meines Knechts Oder meiner Magd, wenn sie eine Sache wider mich hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'was wollte ich tun, wenn Gott sich aufmachte, und was würde ich antworten, wenn er heimsuchte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Hat ihn nicht auch der gemacht, der mich in Mutterleibe machte, und hat ihn im Leibe ebensowohl bereitet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Hab ich den Durftigen ihre Begierde versagt und die Augen der Witwen lassen verschmachten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Hab ich meinen Bissen allein gegessen, und nicht der Waise auch davon gegessen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Denn ich habe mich von Jugend auf gehalten wie ein Vater; und von meiner Mutter Leibe an hab ich gerne getrostet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Hab ich jemand sehen umkommen, daß er kein Kleid hatte, und den Armen ohne Decke gehen lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Haben mich nicht gesegnet seine Seiten, da er von den Fellen meiner Lammer erwarmet ward?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Hab ich meine Hand an den Waisen gelegt, weil ich mich sah im Tor Macht zu helfen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'so falle meine Schulter von der Achsel, und mein Arm breche von der Rohre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Denn ich furchte Gott, wie einen Unfall über mich, und konnte seine Last nicht ertragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Hab ich das Gold zu meiner Zuversicht gestellet und zu dem Goldklumpen gesagt: Mein Trost?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Hab ich mich gefreuet, daß ich grol J, Gut hatte und meine Hand allerlei erworben hatte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Hab ich das Licht angesehen, wenn es helle leuchtete, und den Mond, wenn er voll ging?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Hat sich mein Herz heimlich bereden lassen, daß meine Hand meinen Mund kusse?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Welches ist auch eine Missetat fur die Richter; denn damit hatte ich verleugnet Gott von oben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Hab ich mich gefreuet, wenn\'s meinem Feinde ubel ging, und habe mich erhoben, daß ihn Unglück betreten hatte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Denn ich liel? meinen Mund nicht sundigen, daß er wünschte einen Fluch seiner Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Haben nicht die Manner in meiner Hütte mussen sagen: O wollte Gott, daß wirvon seinem Fleisch nicht gesattiget würden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Draulien mulite der Gast nicht bleiben, sondern meine Tür tat ich dem Wanderer auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Hab ich meine Schalkheit wie ein Mensch gedeckt, daß ich heimlich meine Missetat verbarge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Hab ich mir grauen lassen vor der grolien Menge, und hat die Verachtung der Freundschaften mich abgeschreckt? Ich blieb stille und ging nicht zur Tür aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Wer gibt mir einen Verhorer, daß meine Begierde der Allmachtige erhore, daß jemand ein Buch schriebe von meiner Sache?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'So wollt ich\'s auf meine Achseln nehmen und mir wie eine Krone umbinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Ich wollte die Zahl meiner Gange ansagen und wie ein Fürst wollte ich sie darbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Wird mein Land wider mich schreien und miteinander seine Furchen weinen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'hab ich seine Fruchte unbezahlt gegessen und das Leben der Ackerleute sauer gemacht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'so wachsen mir Disteln fur Weizen und Dornen fur Gerste. Die Worte Hiobs haben ein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Da horeten die drei Manner auf, Hiob zu antworten, weil er sich fur gerecht hielt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Aber Elihu, der Sohn Baracheels, von Bus, des Geschlechts Ram, ward zornig uber Hiob, daß er seine Seele gerechter hielt denn Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Auch ward er zornig uber seine drei Freunde, daß sie keine Antwort fanden und doch Hiob verdammeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Denn Elihu hatte geharret, bis daß sie mit Hiob geredet hatten, weil sie alter waren denn er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Darum, da er sah, daß keine Antwort war im Munde der drei Manner, ward er zornig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Und so antwortete Elihu, der Sohn Baracheels, von Bus, und sprach: Ich bin jung, ihr aber seid alt; darum hab ich mich gescheuet und gefürchtet, meine Kunst an euch zu beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Ich dachte: Lali die Jahre reden, und die Menge des Alters lali Weisheit beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Aber der Geist ist in den Leuten, und der Odem des Allmachtigen macht sie verstandig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Die Grolien sind nicht die Weisesten, und die Alten verstehen nicht das Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Darum will ich auch reden; hore mirzu! Ich will meine Kunst auch sehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Siehe, ich habe geharret, daß ihr geredet habt; ich habe aufgemerkt auf euren Verstand, bis ihr trafet die rechte Rede,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'und habe achtgehabt auf euch; aber siehe, da ist keiner unter euch, der Hiob strafe Oder seiner Rede antworte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ihr werdet vielleicht sagen: Wir haben die Weisheit getroffen, daß Gott ihn verstolien hat, und sonst niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Die Rede tut mir nicht genug; ich will ihm nicht so nach eurer Rede antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Ach! sie sind verzagt, konnen nicht mehr antworten, sie konnen nicht mehr reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Weil ich denn geharret habe, und sie konnten nicht reden (denn sie stehen still und antworten nicht mehr),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'will doch ich mein Teil antworten und will meine Kunst beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Denn ich bin der Rede so voll, daß mich der Odem in meinem Bauche angstet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Siehe, mein Bauch istwie der Most, der zugestopfet ist, der die neuen Fasser zerreiliet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Ich muli reden, daß ich Odem hole; ich muli meine Lippen auftun und antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Ich will niemandes Person ansehen und will keinen Menschen rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Denn ich weifi nicht, wo ich\'s tate, ob mich mein Schopfer uber ein kleines hinnehmen wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Hore doch, Hiob, meine Rede und merke auf alle meine Worte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Siehe, ich tue meinen Mund auf, und meine Zunge redet in meinem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Mein Herz soil recht reden, und meine Lippen sollen den reinen Verstand sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Der Geist Gottes hat mich gemacht, und der Odem des Allmachtigen hat mir das Leben gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Kannst du, so antworte mir; schicke dich gegen mich und stelle dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Siehe ich bin Gottes ebensowohl als du, und aus Leimen bin ich auch gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Doch du darfst vor mir nicht erschrecken, und meine Hand soli dir nicht zu schwer sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Du hast geredet vor meinen Ohren, die Stimme deiner Rede mulite ich horen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Ich bin rein, ohne Missetat, unschuldig und habe keine Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Siehe, er hat eine Sache wider mich funden, darum achtet er mich fur seinen Feind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Er hat meinen Fuli in Stock gelegt und hat alle meine Wege verwahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Siehe, eben daraus schlielie ich wider dich, daß du nicht recht bist; denn Gott ist mehr weder ein Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Warum willstdu mit ihm zanken, daß erdir nicht Rechenschaft gibt alles seines Tuns?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Denn wenn Gott einmal etwas beschlielit, so bedenket er\'s nicht erst her nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Im Traum des Gesichts in der Nacht, wenn der Schlaf auf die Leute fallt, wenn sie schlafen auf dem Bette,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'da offnet er das Ohr der Leute und schreckt sie und zuchtiget sie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'daß er den Menschen von seinem Vorhaben wende und beschirme ihn vor Hoffart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Und verschonet seiner Seele vor dem Verderben und seines Lebens, daß es nicht ins Schwert falle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Er straft ihn mit Schmerzen auf seinem Bette und alle seine Gebeine heftig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'und richtet ihm sein Leben so zu, daß ihm vor der Speise ekelt, und seine Seele, daß sie nicht Lust zu essen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sein Fleisch verschwindet, daß er nicht wohl sehen mag, und seine Beine werden zerschlagen, daß man sie nicht gerne ansiehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'daß seine Seele nahet zum Verderben und sein Leben zu den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'So dann ein Engel, einer aus tausend, mit ihm redet, zu verkundigen dem Menschen, wie er solle recht tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'so wird er ihm gnadig sein und sagen: Er soil erloset werden, daß er nicht hinunterfahre ins Verderben; denn ich habe eine Versohnung funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Sein Fleisch grüne wieder wie in der Jugend, und lali ihn wieder jung werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Er wird Gott bitten; der wird ihm Gnade erzeigen und wird sein Antlitz sehen lassen mit Freuden und wird dem Menschen nach seiner Gerechtigkeit vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Er wird vor den Leuten bekennen und sagen: Ich wollte gesundiget und das Recht verkehret haben, aber es hatte mir nichts genutzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Er hat meine Seele erloset, daß sie nicht fuhre ins Verderben, sondern mein Leben das Licht sahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Siehe, das alles tut Gott zwei Oder dreimal mit einem jeglichen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'daß er seine Seele herumhole aus dem Verderben und erleuchte ihn mit dem Licht der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Merke auf, Hiob, und hore mirzu, und schweige, daß ich rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Hast du aber was zu sagen, so antworte mir; sage her, bist du recht, ich will\'s gerne horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Hast du aber nichts, so hore mir zu und schweige, ich will dich die Weisheit lehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Und Elihu antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Horet, ihr Weisen, meine Rede, und ihr Verstandigen, merket auf mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Denn das Ohr prufet die Rede, und der Mund schmecket die Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Lafit uns ein Urteil erwahlen, daß wir erkennen unter uns, was gut sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Denn Hiob hat gesagt: Ich bin gerecht, und Gott weigertmir mein Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Ich muft lugen, ob ich wohl recht habe, und bin gequalet von meinen Pfeilen, ob ich wohl nichts verschuldet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Wer ist ein solcher wie Hiob, der da Spotterei trinket wie Wasser');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'und auf dem Wege gehet mit den Ubeltatern und wandelt mit den gottlosen Leuten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Denn er hat gesagt: Wenn jemand schon fromm ist, so gilt er doch nichts bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Darum horet mirzu, ihr weisen Leute: Es sei feme, daß Gott sollte gottlos sein und der Allmachtige ungerecht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'sondern er vergilt dem Menschen, danach er verdienet hat, und trifft einen jeglichen nach seinem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Ohne Zweifel, Gott verdammet niemand mit Unrecht, und der Allmachtige beuget das Recht nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Wer hat, das auf Erden ist, verordnet, und wer hat den ganzen Erdboden gesetzt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'So ersich\'s wurde unterwinden, so wurde er ailer Geist und Odem zu sich sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Alles Fleisch wurde miteinander vergehen, und der Mensch wurde wieder zu Asche werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Hast du nun Verstand, so hore das und merke auf die Stimme meiner Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Sollte einer darum das Recht zwingen, daß er\'s hasset? Und daß du stolz bist, solltest du darum den Gerechten verdammen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Sollt einer zum Konige sagen: Du loser Mann! und zu den Fursten: Ihr Gottlosen!?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Der doch nicht ansiehet die Person der Fursten und kennet den Herrlichen nicht mehr denn den Armen; denn sie sind alle seiner Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Plotzlich müssen die Leute sterben und zu Mitternacht erschrecken und vergehen; die Machtigen werden kraftlosweggenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Denn seine Augen sehen auf eines jeglichen Wege, und er schaut alle ihre Gange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Es ist kein Finsternis noch Dunkel, daß sich da mochten verbergen die Ubeltater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Denn es wird niemand gestattet, daß er mit Gott rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Er bringet der Stolzen viel urn, die nicht zu zahlen sind, und stellet andere an ihre Statt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'darum daß er kennet ihre Werke und kehret sie urn des Nachts, daß sie zerschlagen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Er wirft die Gottlosen über einen Haufen, da man\'s gerne siehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'darum daß sie von ihm weggewichen sind und verstunden seiner Wege keinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'daß das Schreien der Armen muftte vor ihn kommen, und er das Schreien der Elenden horete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Wenn er Frieden gibt, wer will verdammen? und wenn er das Antlitz verbirget, wer will ihn schauen unter den Volkern und Leuten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Und laftt uber sie regieren einen Heuchler, das Volkzu drangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Ich muft fur Gott reden und kann\'s nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Hab ich\'s nicht getroffen, so lehre du mich\'s besser; hab ich unrecht gehandelt, ich will\'s nicht mehr tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Man wartet der Antwort von dir, denn du verwirfst alles; und du hast\'s angefangen und nicht ich. Weiftest du nun was, so sage an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Weise Leute lasse ich mir sagen, und ein weiser Mann gehorchet mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Aber Hiob redete mit Unverstand, und seine Worte sind nicht klug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Mein Vater! laft Hiob versucht werden bis ans Ende, darum daß er sich zu unrechten Leuten kehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Er hat uber seine Sunde dazu noch gelastert; darum laft Ihn zwischen uns geschlagen werden und danach viel wider Gott plaudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Und Elihu antwortete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Achtest du das fur recht, daß du sprichst: Ich bin gerechter denn Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Denn du sprichst: Wer gilt bei dir etwas? Was hilft\'s, ob ich mich ohne Sunde mache?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ich will dir antworten ein Wort und deinen Freunden mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Schaue gen Himmel und siehe, und schaue an die Wolken, daß sie dir zu hoch sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Sundigest du, was kannst du mit ihm machen? Und ob deiner Missetat viel ist, was kannst du ihm tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Und ob du gerecht seiest, was kannst du ihm geben, Oder was wird ervon deinen Handen nehmen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Einem Menschen, wie du bist, mag wohl etwas tun deine Bosheit und einem Menschenkinde deine Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Dieselbigen mogen schreien, wenn ihnen viel Gewalt geschieht, und rufen uber den Arm der Großen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'die nicht danach fragen, wo ist Gott, mein Schopfer, der das Gesange macht in der Nacht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'der uns gelehrter macht denn das Vieh auf Erden und weiser denn die Vogel unter dem Himmel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Aber sie werden da auch schreien uber den Hochmut der Bosen, und erwird sie nicht erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Denn Gott wird das Eitle nicht erhoren, und der Allmachtige wird es nicht ansehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Dazu sprichst du, du werdest ihn nicht sehen. Aber es ist ein Gericht vor ihm; harre sein nur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'ob sein Zorn bald nicht heimsucht, und sich nicht annimmt, daß so viel Laster da sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Darum hat Hiob seinen Mund umsonst aufgesperrt und gibt stolze Teiding vor mit Unverstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu redete weiter und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Harre mir noch ein wenig, ich will dir\'s zeigen; denn ich habe noch von Gottes wegen was zu sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Ich will meinen Verstand weit holen und meinen Schopfer beweisen, daß er recht sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Meine Reden sollen ohne Zweifel nicht falsch sein, mein Verstand soil ohne Wandel vor dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Siehe, Gott verwirft die Machtigen nicht; denn er ist auch machtig von Kraft des Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Den Gottlosen erhalt er nicht, sondern hilft dem Elenden zum Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Er wendet seine Augen nicht von dem Gerechten und die Konige lalit er sitzen auf dem Thron immerdar, daß sie hoch bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Und wo Gefangene liegen in Stocken und gebunden mit Stricken elendiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'so verkundiget er ihnen, was sie getan haben, und ihre Untugend, daü sie mit Gewalt gefahren haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Und offnet ihnen das Ohr zur Zucht und sagt ihnen, daü sie sich von dem Unrechten bekehren sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Gehorchen sie und dienen ihm, so werden sie bei guten Tagen alt werden und mit Lust leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Gehorchen sie nicht, so werden sie ins Schwert fallen und vergehen, ehe sie es gewahr werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Die Heuchler, wenn sie der Zorn trifft, schreien sie nicht, wenn sie gefangen liegen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'so wird ihre Seele mit Qual sterben und ihr Leben unter den Hurern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Aber den Elenden wird er aus seinem Elend erretten und dem Armen das Ohr offnen in Trubsal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Erwird dich reißen aus dem weiten Rachen der Angst, die keinen Boden hat; und dein Tisch wird Ruhe haben, voll alles Guten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Du aber machst die Sache der Gottlosen gut, dafi ihre Sache und Recht erhalten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Siehe zu, dafi dich nicht vielleicht Zorn beweget habe, jemand zu plagen, Oder grofi Geschenk dich nicht gebeuget habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Meinest du, dafi er deine Gewalt achte, Oder Gold, Oder irgend eine Starke Oder Vermogen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Du darfst der Nacht nicht begehren, die Leute an ihrem Ortzu überfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Hüte dich und kehre dich nicht zum Unrecht, wie du denn vor Elend angefangen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Siehe, Gott ist zu hoch in seiner Kraft; wo ist ein Lehrer, wie er ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Werwill fiber ihn heimsuchen seinen Weg, und wer will zu ihm sagen: Du tust unrecht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Gedenke, dafi du sein Werk nicht wissest, wie die Leute singen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Denn alle Menschen sehen das, die Leute schauen\'s von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Siehe, Gott ist groli und unbekannt; seiner Jahre Zahl kann niemand forschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Er macht das Wasser zu kleinen Tropfen und treibt seine Wolken zusammen zum Regen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'daß die Wolken fließen und triefen sehr auf die Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Wenn er vornimmt, die Wolken auszubreiten, wie sein hoch Gezelt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'siehe, so breitet er aus seinen Blitz fiber dieselben und bedecket alle Enden des Meers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Denn damit schreckt er die Leute und gibt doch Speise die Fülle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Er decket den Blitz wie mit Handen und heilit es doch wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Davon zeuget sein Geselle, namlich des Donners Zorn in Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Des entsetzt sich mein Herz und bebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Lieber, horet doch, wie sein Donner zfirnet, und was für Gesprach von seinem Munde ausgehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Er siehet unter alien Himmeln, und sein Blitz scheinet auf die Enden der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Dem nach brullet der Donner, und er donnert mit seinem graven Schall, und wenn sein Donner gehoret wird, kann man\'s nicht aufhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Gott donnert mit seinem Donner greulich und tut große Dinge, und wird doch nicht erkannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Er spricht zum Schnee, so ist er bald auf Erden, und zum Platzregen, so ist der Platzregen da mit Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Alle Menschen hat er in der Hand als verschlossen, daß die Leute lernen, was er tun kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Das wilde Tier gehet in die Hohle und bleibt an seinem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Von Mittag her kommt Wetter und von Mitternacht Kalte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Vom Odem Gottes kommt Frost, und grofie Wasser, wenn er auftauen lalit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Die dicken Wolken scheiden sich, daß es helle werde, und durch den Nebel bricht sein Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Er kehret die Wolken, wo er hin will, daß sie schaffen alles, was er ihnen gebeut, auf dem Erdboden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'essei liber ein Geschlecht Oder uber ein Land, so man ihn barmherzig findet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Da merke auf, Hiob; stehe, und vernimm die Wunder Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Weilit du, wenn Gott solches uber sie bringt und wenn er das Licht seiner Wolken lalit hervorbrechen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Weilit du, wie sich die Wolken ausstreuen? Welche Wunder die Vollkommenen wissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Dali deine Kleiderwarm sind, wenn das Land stille ist vom Mittagswind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ja, du wirst mit ihm die Wolken ausbreiten, die test stehen wie ein gegossener Spiegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Zeige uns, was wir ihm sagen sollen; denn wir werden nicht dahin reichen vor Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Werwird ihm erzahlen, daß ich rede? So jemand redet, derwird verschlungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Jetzt siehet man das Licht nicht, das in den Wolken helle leuchtet; wenn aber der Wind wehet, so wird\'s klar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Von Mitternacht kommt Gold zu Lob vor dem schrecklichen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Den Allmachtigen aber mogen sie nicht begreifen, der so groli ist von Kraft; denn er wird von seinem Recht und guter Sache nicht Rechenschaft geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Darum müssen ihn furchten die Leute; und er furchtet sich vor keinem, wie weise sie sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Und der HERR antwortete Hiob aus einem Wetter und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Wer ist der, der so fehlet in der Weisheit und redet so mit Unverstand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Gurte deine Lenden wie ein Mann; ich will dich fragen, lehre mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Wo warest du, da ich die Erde grundete? Sage mir\'s, bist du so klug?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Weilit du, wer ihr das Mali gesetzt hat, Oder wer uber sie eine Richtschnur gezogen hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Oder worauf stehen ihre Fulie versenket? Oder wer hat ihr einen Eckstein gelegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'da mich die Morgensterne miteinander lobeten, und jauchzeten alle Kinder Gottes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Werhatdas Meermitseinen Turen verschlossen, da es herausbrach wie aus Mutterleibe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'da ich\'s mit Wolken kleidete und in Dunkel einwickelte, wie in Windeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'da ich ihm den Lauf brach mit meinem Damm und setzte ihm Riegel und Tur');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'und sprach: Bis hieher sollst du kommen und nicht weiter; hie sollen sich legen deine stolzen Wellenl?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Hastdu bei deiner Zeit dem Morgen geboten und der Morgenrote ihren Ort gezeiget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'daß die Ecken der Erde gefasset und die Gottlosen herausgeschuttelt würden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Das Siegel wird sich wandeln wie Leimen, und sie stehen wie ein Kleid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Und den Gottlosen wird ihr Licht genommen werden; und der Arm der Hoffartigen wird zerbrochen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Bist du in den Grund des Meers kommen und hast in den Fulitapfen der Tiefen gewandelt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Haben sich dir des Todes fore jeaufgetan? Oder hast du gesehen die Tore der Finsternis?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Hastdu vernommen, wie breitdie Erde sei? Sage an, weilit du solches alles?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Welches ist der Weg, da das Licht wohnet, und welches sei der Finsternis Statte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'daß du mdgest abnehmen seine Grenze und merken den Pfad zu seinem Hause?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Wulitest du, daß du zu der Zeit solltest geboren werden und wieviel deiner Tage sein würden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Bist du gewesen, da der Schnee herkommt, Oder hast du gesehen, wo der Hagel herkommt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'die ich habe verhalten bis auf die Zeit der Trubsal und auf den Tag des Streits und Kriegs?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Durch welchen Weg teilet sich das Licht, und auffahret der Ostwind auf Erden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Wer hat dem Platzregen seinen Lauf ausgeteilet und den Weg dem Blitze und Donner,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'daß es regnet aufs Land, da niemand ist, in der Wuste, da kein Mensch ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'daß er füllet die Einoden und Wildnis und macht, daß Gras wachset?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Wer ist des Regens Vater? Wer hat die Tropfen des Taues gezeuget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Aus wes Leibe ist das Eis gegangen? Und wer hat den Reif unter dem Himmel gezeuget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'daß das Wasser verborgen wird wie unter Steinen und die Tiefe oben gestehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Kannst du die Bande der sieben Sterne zusammenbinden, Oder das Band des Orion auflosen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Kannst du den Morgenstern hervorbringen zu seiner Zeit, Oder den Wagen am Himmel uber seine Kinder führen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Weilit du, wie der Himmel zu regieren ist? Oder kannst du ihn meistern auf Erden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Kannst du deinen Donner in der Wolke hoch herführen? Oder wird dich die Menge des Wassers verdecken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Kannst du die Blitze auslassen, daß sie hinfahren und sprechen: Hie sind wir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Wer gibt die Weisheit ins Verborgene? Wer gibt verstandige Gedanken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Wer ist so weise, der die Wolken erzahlen konnte? Wer kann die Wasserschlauche am Himmel verstopfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'wenn der Staub begossen wird, daß er zuhaufe lauft und die Klolie aneinander kleben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Kannst du der Lowin ihren Raub zu jagen geben und die jungen Lowen sattigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'daß sie sich legen in ihre Statte und ruhen in der Hbhle, da sie lauern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Wer bereitet dem Raben die Speise, wenn seine Jungen zu Gott rufen und fliegen irre, wenn sie nicht zu essen haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Weilit du die Zeit, wann die Gemsen auf den Felsen gebaren? Oder hast du gemerkt, wann die Hirsche schwanger gehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Hast du erzahlet ihre Monden, wann sie voll werden? Oder weifit du die Zeit, wann sie gebaren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Sie beugen sich, wenn sie gebaren, und reitien sich und lassen aus ihre Jungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Ihre Jungen werden feist und mehren sich im Getreide; und gehen aus und kommen nicht wieder zu ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Wer hat das Wild so frei lassen gehen? Wer hat die Bande des Wildes aufgeloset,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'dem ich das Feld zum Hause gegeben habe und die Wuste zur Wohnung?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Es verlacht das Getummel der Stadt; das Pochen des Treibers horet es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Es schauet nach den Bergen, da seine Weide ist, und suchet, wo es gain ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Meinestdu, das Einhorn werde dirdienen und werde bleiben an deiner Krippe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Kannst du ihm dein Joch anknupfen, die Furchen zu machen, daß es hinter dir brache in Grunden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Magst du dich auf es verlassen, daß es so stark ist, und wirst es dir lassen arbeiten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Magst du ihm trauen, dati es deinen Samen dir wiederbringe und in deine Scheune sammle?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Die Federn des Pfauen sind schonerdenn die Flugel und Federn des Storchs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'der seine Eier auf der Erde lassetund lalitsie die heilie Erde ausbruten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Ervergisset, daß sie mochten zertreten werden und ein wild Tier sie zerbreche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Erwird so hartgegen seine Jungen, alswaren sie nicht sein, achtet es nicht, daß er umsonst arbeitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Denn Gott hat ihm die Weisheit genommen und hat ihm keinen Verstand mitgeteilet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Zu der Zeit, wenn er hoch fahret, erhohet er sich und verlachet beide Roli und Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Kannst du dem Roli Krafte geben, Oder seinen Hals zieren mit seinem Geschrei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Kannst du es schrecken wie die Heuschrecken? Das ist Preis seiner Nase, was schrecklich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Es stampfet auf den Boden und istfreudig mit Kraft und zeucht aus den Geharnischten entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Es spottet der Furcht und erschrickt nicht und fleucht vor dem Schwert nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'wenngleich wider es klinget der Kocher und glanzet beide Spieli und Lanze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Es zittert und tobet und scharret in die Erde und achtet nicht der Trommeten Hall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Wenn die Trommete fast klinget, spricht es: Hui! und riecht den Streit von feme, das Schreien der Fursten und Jauchzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Fleuget der Habicht durch deinen Verstand und breitet seine Flugel gegen Mittag?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Fleuget der Adler auf deinen Befehl so hoch, daß er sein Nest in der Hohe macht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'In Felsen wohnet er und bleibt auf den Klippen an Felsen und in festen Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Von dannen schauet er nach der Speise, und seine Augen sehen feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Seine Jungen saufen Blut; und wo ein Aas ist, da ist er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Und der HERR antwortete Hiob und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Wer mit dem Allmachtigen hadern will, soil\'s ihm der nicht beibringen? Und wer Gott tadelt, soil\'s der nicht verantworten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Hiob aber antwortete dem HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Siehe, ich bin zu leichtfertig gewesen, was soil ich antworten? Ich will meine Hand auf meinen Mund legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Ich habe einmal geredet, darum will ich nicht mehr antworten; hernach will ich\'s nicht mehr tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Und der HERR antwortete Hiob aus einem Wetter und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Gurte wie ein Mann deine Lenden; ich will dich fragen, lehre mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Solltest du mein Urteil zunichte machen und mich verdammen, daß du gerecht seiest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Hast du einen Arm wie Gott und kannst mit gleicher Stimme donnern, als er tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Schmücke dich mit Pracht und erhebe dich; zeuch dich loblich und herrlich an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Streue aus den Zorn deines Grimms; schaue an die Hochmutigen, wo sie sind, und demutige sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Ja, schaue die Hochmutigen, wo sie sind, und beuge sie und mache die Gottlosen dunne, wo sie sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Verscharre sie miteinander in der Erde und versenke ihre Pracht ins Verborgene,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'so will ich dirauch bekennen, daß dir deine rechte Hand helfen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Siehe, der Behemoth, den ich neben dir gemacht habe, frilit Heu wie ein Ochse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Siehe, seine Kraft ist in seinen Lenden und sein Vermdgen im Nabel seines Bauchs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Sein Schwanz strecket sich wie eine Zeder, die Adern seiner Scham starren wie ein Ast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Seine Knochen sind wie fest Erz, seine Gebeine sind wie eiserne Stabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Er ist der Anfang der Wege Gottes; der ihn gemacht hat, der greift ihn an mit seinem Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Die Berge tragen ihm Krauter, und alle wilden Tiere spielen daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Er liegt gern im Schatten, im Rohr und im Schlamm verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Das Gebusch bedeckt ihn mit seinem Schatten, und die Bachweiden bedecken ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Siehe, erschluckt in sich den Strom und achtet es nicht gro(J; laftt sich dunken, erwolle den Jordan mit seinem Munde ausschopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Noch fahet man ihn mit seinen eigenen Augen, und durch Fallstricke durchbohret man ihm seine Nase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Kannst du den Leviathan ziehen mit dem Hamen und seine Zunge mit einem Strick fassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Kannst du ihm eine Angel in die Nase legen und mit einem Stachel ihm die Backen durchbohren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Meinestdu, erwerde dirviel Flehens machen Oder dir heucheln?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Meinest du, dafi er einen Bund mit dir machen werde, daß du ihn immerzum Knecht habest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 29, 'Kannst du mit ihm spielen wie mit einem Vogel, Oder ihn deinen Dirnen binden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 30, 'Meinest du, die Gesellschaften werden ihn zerschneiden, daß er unter die Kaufleute zerteilet wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 31, 'Kannst du das Netz fullen mit seiner Flaut und die Fischreusen mit seinem Kopf?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 32, 'Wenn du deine FHand an ihn legst, so gedenke, daß ein Streit sei, den du nicht ausfuhren wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Siehe, seine FHoffnung wird ihm fehlen; und wenn er sein ansichtig wird, schwinget er sich dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Niemand ist so kuhn, der ihn reizen darf; wer ist denn, der vor mir stehen konne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Wer hat mir was zuvor getan, daß ich\'s ihm vergelte? Es ist mein, was unter alien Flimmeln ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Dazu muft ich nun sagen, wie graft, wie machtig und wohl geschaffen er ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Wer kann ihm sein Kleid aufdecken? Und wer darf es wagen, ihm zwischen die Zahne zu greifen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Wer kann die Kinnbacken seines Antlitzes auftun? Schrecklich stehen seine Zahne umher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Seine stolzen Schuppen sind wie feste Schilde, fest und enge ineinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Eine ruhrt an die andere, daß nicht ein Luftlein dazwischengehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Es hangt eine an der andern, und halten sich zusammen, daß sie sich nicht voneinander trennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Sein Niesen glanzet wie ein Licht; seine Augen sind wie die Augenlider der Morgenrote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Aus seinem Munde fahren Fackeln, und feurige Funken schieften heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Aus seiner Nase gehet Rauch wie von heiften Topfen und Kessel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Sein Odem ist wie lichte Lohe, und aus seinem Munde gehen Flammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Er hat einen starken Hals; und ist seine Lust, wo er etwas verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Die Gliedmaften seines Fleisches hangen aneinander und halten hart an ihm, daß er nicht zerfallen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Sein Herz ist so hart wie ein Stein und so fest wie ein Stuck vom untersten Muhlstein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Wenn er sich erhebt, so entsetzen sich die Starken; und wenn er daherbricht, so ist keine Gnade da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Wenn man zu ihm will mit dem Schwert, so regt er sich nicht; Oder mit Spieft, Geschoft und Panzer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Er achtet Eisen wie Stroh und Erz wie faul Holz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Kein Pfeil wird ihn verjagen; die Schleudersteine sind wie Stoppeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Den Hammer achtet erwie Stoppeln; er spottet der bebenden Lanze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Unter ihm liegen scharfe Steine und fahrt fiber die scharfen Felsen wie uber Kot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Er macht, daß das tiefe Meer siedet wie ein Topf, und ruhrt es ineinander, wie man eine Salbe menget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Nach ihm leuchtet der Weg, er macht die Tiefe ganz grau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Auf Erden ist ihm niemand zu gleichen; er ist gemacht ohne Furcht zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Erverachtet alles, was hoch ist; er ist ein Konig uber alle Stolzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Und Hiob antwortete dem HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'ich erkenne, daß du alles vermagst, und kein Gedanke ist dir verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Es ist ein unbesonnener Mann, der seinen Rat meinet zu verbergen. Darum bekenne ich, daß ich habe unweislich geredet, das mir zu hoch ist und nicht verstehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'So erhore nun, laft mich reden; ich will dich fragen, lehre mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Ich habe dich mit den Ohren gehoret, und mein Auge siehet dich auch nun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Darum schuldige ich mich und tue Bufte in Staub und Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Da nun der HERR diese Worte mit Hiob geredet hatte; sprach erzu Eliphas von Theman: Mein Zorn ist ergrimmet über dich und über deine zween Freunde; denn ihr habt nicht recht von mir geredet wie mein Knecht Hiob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'So nehmet nun sieben Farren und sieben Widder und gehet hin zu meinem Knechte Hiob und opfert Brandopfer fur euch und lalit meinen Knecht Hiob fur euch bitten. Denn ihn will ich ansehen, dati ich euch nicht sehen lasse, wie ihr Torheit begangen habt; denn ihr habt nicht recht von mir geredet wie mein Knecht Hiob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Da gingen hin Eliphas von Theman, Bildad von Suah und Zophar von Naema und taten, wie der HERR ihnen gesagt hatte. Und der HERR sah an Hiob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Und der HERR wendete das Gefangnis Hiobs, da er bat fur seine Freunde. Und der HERR gab Hiob zwiefaltig so viel, als er gehabt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Und es kamen zu ihm alle seine Bruder und alle seine Schwestern und alle, die ihn vorhin kannten, und alien mit ihm in seinem Hause und kehreten sich zu ihm und trosteten ihn über allem Obel, das der HERR über ihn hatte kommen lassen. Und ein jeglichergab ihm einen schonen Groschen und ein gulden Stirnband.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Und der HERR segnete hernach Hiob mehr denn vorhin, daß er kriegte vierzehntausend Schafe und sechstausend Kamele und tausend Joch Rinder und tausend Esel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Und kriegte sieben Sohne und drei Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Und hieli die erste Jemima, die andere Kezia und die dritte Keren-Hapuch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Und wurden nicht so schone Weiber funden in alien Landen als die Tochter Hiobs. Und ihr Vater gab ihnen Erbteil unter ihren Brüdem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Und Hiob lebte nach diesem hundertundvierzig Jahre, daß er sah Kinder und Kindeskinder bis in das vierte Glied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Und Hiob starb alt und lebenssatt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Wohl dem, der nicht wandelt im Rat der Gottlosen, noch tritt auf den Weg der Sunder, noch sitzt, da die Spotter sitzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'sondern hat Lust zum Gesetz des HERRN und redet von seinem Gesetz Tag und Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Der ist wie ein Baum, gepflanzet an den Wasserbachen, der seine Frucht bringet zu seiner Zeit, und seine Blatter verwelken nicht, und was er macht, das gerat wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Aber so sind die Gottlosen nicht, sondern wie Spreu, die der Wind verstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Darum bleiben die Gottlosen nicht im Gerichte, noch die Sunder in der Gemeine der Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Denn der HERR kennet den Weg der Gerechten, aber der Gottlosen Weg vergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Warum toben die Heiden, und die Leute reden so vergeblich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Die Konige im Lande lehnen sich auf, und die Herren ratschlagen miteinander wider den HERRN und seinen Gesalbten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Lasset uns zerreilien ihre Bande und von uns werfen ihre Seile!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Aber der im Himmel wohnet, lachet ihrer, und der HERR spottet ihrer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Er wird einst mit ihnen reden in seinem Zorn, und mit seinem Grimm wird er sie schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Aber ich habe meinen Konig eingesetzt auf meinem heiligen Berg Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Ich will von einer solchen Weise predigen, daß der HERR zu mir gesagt hat: Du bist mein Sohn, heute hab ich dich gezeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Heische von mir, so will ich dir die Heiden zum Erbe geben und der Welt Ende zum Eigentum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Du sollst sie mit einem eisernen Zepter zerschlagen; wie Topfe sollst du sie zerschmeilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'So lalit euch nun weisen, ihr Konige, und lalit euch zuchtigen, ihr Richter auf Erden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Dienet dem HERRN mit Furcht und freuet euch mit Zittern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Küssetden Sohn, daß er nicht zurne und ihr umkommet auf dem Wege; denn sein Zorn wird bald anbrennen. Aber wohl alien, die auf ihn trauen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein Psalm Davids, da er floh vor seinem Sohn Absalom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Ach, HERR, wie ist meiner Feinde so viel, und setzen sich so viele wider mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Viele sagen von meiner Seele: Sie hat keine Hilfe bei Gott. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Aber du, HERR, bist der Schild fur mich, und der mich zu Ehren setzet und mein Haupt aufrichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ich rufe an mit meiner Stimme den HERRN, so erhoret er mich von seinem heiligen Berge. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ich liege und schlafe und erwache; denn der HERR halt mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Ich furchte mich nicht vor viel Hunderttausenden, die sich umher wider mich legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Auf HERR, und hilf mir, mein Gott; denn du schlagst alle meine Feinde auf den Backen und zerschmetterst der Gottlosen Zahne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, 'Bei dem HERRN findet man Hilfe und deinen Segen uber dein Volk. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Ein Psalm Davids, vorzusingen auf Saitenspielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Erhore mich, wenn ich rufe, Gott meiner Gerechtigkeit, der du mich trostest in Angst; sei mir gnadig und erhore mein Gebet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Liebe Herren, wie lange soil meine Ehre geschandet werden? Wie habt ihr das Eitle so lieb und die Lügen so gerne! Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Erkennet doch daß der HERR seine Heiligen wunderlich fuhret! Der HERR horet, wenn ich ihn anrufe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Zürnet ihr, sundiget nicht! Redet mit eurem Herzen auf eurem Lager und harret. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Opfert Gerechtigkeit und hoffet auf den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Viele sagen: Wie sollt uns dieser weisen, was gut ist? Aber, HERR, erhebe uber uns das Licht deines Antlitzes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Du erfreuest mein Herz, ob jene gleich viel Wein und Korn haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, 'Ich liege und schlafe ganz mit Frieden; denn allein du, HERR, hilfst mir, daß ich sicher wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Ein Psalm Davids, vorzusingen fur das Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'HERR, hore meine Worte, merke auf meine Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Vernimm mein Schreien, mein Konig und mein Gott; denn ich will vor dir beten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'HERR, frühe wollest du meine Stimme horen; fruhe will ich mich zu dir schicken und drauf merken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Denn du bist nicht ein Gott, dem gottlos Wesen gefallt; wer bose ist, bleibet nicht vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Die Ruhmredigen bestehen nicht vor deinen Augen; du bistfeind alien Ubeltatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Du bringest die Lugner urn; der HERR hat Greuel an den Blutgierigen und Falschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Ich aber will in dein Haus gehen auf deine grofte Gute und anbeten gegen deinem heiligen Tempel in deiner Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'HERR, leite mich in deiner Gerechtigkeit urn meiner Feinde willen; richte deinen Weg vor mir her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Denn in ihrem Munde ist nichts Gewisses, ihr Inwendiges ist Herzeleid, ihr Rachen ist ein offenes Grab, mit ihren Zungen heucheln sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Schuldige sie, Gott, daß sie fallen von ihrem Vornehmen! Stofte sie aus urn ihrergroften Ubertretung willen; denn sie sind dirwiderspenstig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Laft sich freuen alle, die auf dich trauen; ewiglich laft sie ruhmen, denn du beschirmest sie; frohlich laft sein in dir, die deinen Namen lieben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, 'Denn du, HERR, segnest die Gerechten; du kronest sie mit Gnade wie mit einem Schilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Ein Psalm Davids, vorzusingen auf acht Saiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Ach, HERR, strafe mich nicht in deinem Zorn und zuchtige mich nicht in deinem Grimm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'HERR, sei mir gnadig, denn ich bin schwach; heile mich, HERR, denn meine Gebeine sind erschrocken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'und meine Seele ist sehr erschrocken. Ach, du HERR, wie lange!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Wende dich, HERR, und errette meine Seele; hilf mir urn deiner Gute willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Denn im Tode gedenkt man dein nicht; wer will dir in der Holle danken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Ich bin so mude vom Seufzen, ich schwemme mein Bette die ganze Nacht und netze mit meinen Tranen mein Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Meine Gestalt ist verfallen vor Trauern und ist alt worden; denn ich allenthalben geangstet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Weichet von mir, alle Ubeltater; denn der HERR horet mein Weinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'der HERR horet mein Flehen, mein Gebet nimmt der HERR an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, 'Es mussen alle meine Feinde zuschanden werden und sehr erschrecken, sich zuruckkehren und zuschanden werden plotzlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Die Unschuld Davids, davon ersang dem HERRN von wegen der Worte des Mohren, des Jeminiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Auf dich, HERR, traue ich, mein Gott! Hilf mir von alien meinen Verfolgern und errette mich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'daß sie nicht wie Lowen meine Seele erhaschen und zerreiften, weil kein Erretter da ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'HERR, mein Gott, hab ich solches getan, und ist Unrecht in meinen Handen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'hab ich Boses vergolten denen, so friedlich mit mir lebten, Oder die, so mir ohne Ursache feind waren, beschadiget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'so verfolge mein Feind meine Seele und ergreife sie und trete mein Leben zu Boden und lege meine Ehre in den Staub. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'auf, HERR, in deinem Zorn, erhebe dich uber den Grimm meiner Feinde und hilf mir wieder in das Amt, das du mir befohlen hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'daß sich die Leute wieder zu dir sammeln; und um derselben willen komm wieder empor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Der HERR ist Richter fiber die Leute. Richte mich, HERR, nach meiner Gerechtigkeit und Frommigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Lali der Gottlosen Bosheit ein Ende werden und fordere die Gerechten; denn du, gerechter Gott, prufest Herzen und Nieren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Mein Schild ist bei Gott, der den frommen Herzen hilft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gott ist ein rechter Richter und ein Gott, der taglich drauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Will man sich nicht bekehren, so hatersein Schwert gewetzt und seinen Bogen gespannet und zielet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'und hat drauf gelegt todlich Geschoü; seine Pfeile hat er zugerichtet zu verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Siehe, der hat Boses im Sinn, mit Ungluck ist er schwanger; erwird aber einen Fehl gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Er hat eine Grube gegraben und ausgefuhrt und ist in die Grube gefallen, die er gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Sein Ungluck wird auf seinen Kopf kommen und sein Frevel auf seine Scheitel fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, 'Ich danke dem HERRN um seiner Gerechtigkeit willen und will loben den Namen des HERRN, des Allerhochsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Ein Psalm Davids, vorzusingen auf der Githith.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'HERR, unser Herrscher, wie herrlich ist dein Name in alien Landen, da man dir danket im Himmel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'dem Munde der jungen Kinder und Sauglinge hast du eine Macht zugerichtet um deiner Feinde willen, dafi du vertilgest den Feind und den Rachgierigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Denn ich werde sehen die Himmel, deiner Finger Werk, den Mond und die Sterne, die du bereitest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Was ist der Mensch, dafi du sein gedenkest; und des Menschen Kind, dafi du dich sein annimmst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Du wirst ihn lassen eine kleine Zeit von Gott verlassen sein. Aber mit Ehren und Schmuck wirst du ihn kronen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Du wirst ihn zum Herrn machen uber deiner Hande Werk; alles hast du unter seine Fülie getan:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Schafe und Ochsen allzumal, dazu auch die wilden Tiere,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'die Vogel unter dem Himmel und die Fische im Meer und was im Meer gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, 'HERR, unser Herrscher, wie herrlich ist dein Name in alien Landen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Ein Psalm Davids von der schonen Jugend, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Ich danke dem HERRN von ganzem Herzen und erzahle alle deine Wunder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ich freue mich und bin frohlich in dir und lobe deinen Namen, du Allerhochster,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'dafi du meine Feinde hinter sich getrieben hast; sie sind gefallen und umkommen vordir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Denn du fuhrest mein Recht und Sache aus; du sitzest auf dem Stuhl ein rechter Richter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Du schiltst die Heiden und bringest die Gottlosen um; ihren Namen vertilgest du immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Die Schwerter des Feindes haben ein Ende; die Stadte hast du umgekehret; ihr Gedachtnis ist umkommen samt ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Der HERR aber bleibt ewiglich; er hat seinen Stuhl bereitet zum Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Und er wird den Erdboden recht richten und die Leute regieren rechtschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Und der HERR ist des Armen Schutz, ein Schutz in der Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Darum hoffen auf dich, die deinen Namen kennen; denn du verlassest nicht, die dich, HERR, suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Lobetden HERRN, der zu Zion wohnet; verkundiget unter den Leuten sein Tun!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Denn ergedenkt und fragt nach ihrem Blut; er vergisset nicht des Schreiens der Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'HERR, sei mir gnadig; siehe an mein Elend unter den Feinden, der du mich erhebest aus den Toren des Todes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'auf dafi ich erzahle all deinen Preis in den Toren der Tochter Zion, dafi ich frohlich sei uber deine Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Die Heiden sind versunken in der Grube, die sie zugerichtet hatten; ihr Fuli ist gefangen im Netz, das sie gestellet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'So erkennet man, daß der HERR Recht schaffet. Der Gottlose ist verstrickt in dem Werk seiner Hande durchs Wort. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Ach, dafi die Gottlosen müfiten zur Holle gekehret werden, alle Heiden, die Gottes vergessen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Denn erwird des Armen nicht so ganz vergessen, und die Hoffnung der Elenden wird nicht verloren sein ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'HERR, stehe auf, daü Menschen nicht Uberhand kriegen; lali alle Heiden vor dir gerichtet werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, 'Gib ihnen, HERR, einen Meister, dafi die Heiden erkennen dafi sie Menschen sind. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'HERR, warum trittst du so feme, verbirgest dich zur Zeit der Not?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Weil der Gottlose Ubermut treibet, mufi der Elende leiden. Sie hangen sich aneinander und erdenken bose Tücke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Denn der Gottlose ruhmet sich seines Mutwillens, und der Geizige segnet sich und lasted den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Der Gottlose ist so stolz und zornig, daü er nach niemand fraget; in alien seinen Tücken halt er Gott fur nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Er fahret fort mit seinem Tun immerdar; deine Gerichte sind feme von ihm; er handelt trotzig mit alien seinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Er spricht in seinem Herzen: Ich werde nimmermehr daniederliegen; es wird fur und fur keine Not haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sein Mund ist voll Fluchens, Falsches und Trugs; seine Zunge richtet Mühe und Arbeit an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Er sitzt und lauert in den Hofen; er erwurget die Unschuldigen heimlich; seine Augen halten auf die Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Er lauert im Verborgenen, wie ein Lowe in der Hohle; er lauert, daß er den Elenden erhasche, und erhaschet ihn, wenn er ihn in sein Netz zeucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Er zerschlagt und drucket nieder und stofit zu Boden den Armen mit Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Er spricht in seinem Herzen: Gott hat\'s vergessen; er hat sein Antlitz verborgen, erwird\'s nimmermehr sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Stehe auf, HERR Gott, erhebe deine Hand; vergili der Elenden nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Warum soil der Gottlose Gott lastern und in seinem Herzen sprechen: Du fragst nicht danach?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du siehest ja, denn du schauestdas Elend und Jammer; es stehet in deinen Handen. Die Armen befehlen\'s dir; du bist der Waisen Heifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zerbrich den Arm des Gottlosen und suche das Bose, so wird man sein gottlos Wesen nimmer finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Der HERR ist Konig immer und ewiglich; die Heiden mussen aus seinem Land umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Das Verlangen der Elenden horestdu, HERR; ihr Herz ist gewifi, daß dein Ohr drauf merket,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'daß du Recht schaffest dem Waisen und Armen, daß der Mensch nicht mehr trotze auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Ein Psalm Davids, vorzusingen. Ich traue auf den HERRN. Wie saget ihr denn zu meiner Seele, sie soil fliegen wie ein Vogel auf eure Berge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Denn siehe, die Gottlosen spannen den Bogen und legen ihre Pfeile auf die Sehne, damit heimlich zu schielien die Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Denn sie reilien den Grund urn; was soil der Gerechte ausrichten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Der HERR ist in seinem heiligen Tempel, des HERRN Stuhl ist im Himmel; seine Augen sehen drauf, seine Augenlider prufen die Menschenkinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Der HERR prufet den Gerechten; seine Seele hasset den Gottlosen und die gerne freveln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Er wird regnen lassen uber die Gottlosen Blitz, Feuer und Schwefel und wird ihnen ein Wetter zu Lohn geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Der HERR ist gerecht und hat Gerechtigkeit lieb, darum daß ihre Angesichte schauen auf das da recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Ein Psalm Davids, vorzusingen auf acht Saiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Hilf, HERR, die Heiligen haben abgenommen, und der Glaubigen istwenig unterden Menschenkindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Einer redet mit dem andern unnutze Dinge und heucheln und lehren aus uneinigem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Der HERR wolle ausrotten alle Heuchelei und die Zunge, die da stolz redet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'die da sagen: Unsere Zunge soil uberhand haben, uns gebuhrt zu reden; wer ist unser HERR?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Weil denn die Elenden verstoret werden und die Armen seufzen, will ich auf, spricht der HERR; ich will eine Hilfe schaffen, daß man getrost lehren soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Die Rede des HERRN ist lauter, wie durchlautert Silber im irdenen Tiegel, bewahret siebenmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Du, HERR, wollest sie bewahren und uns behuten vor diesem Geschlecht ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, 'Denn es wird allenthalben voll Gottloser, wo solche lose Leute unterden Menschen herrschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'HERR, wie lange willst du mein so gar vergessen? Wie lange verbirgest du dein Antlitz vor mir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Wie lange soil ich sorgen in meiner Seele und mich angsten in meinem Herzen taglich? Wie lange soil sich mein Feind uber mich erheben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Schaue doch und erhore mich, HERR, mein Gott! Erleuchte meine Augen, daß ich nicht im Tode entschlafe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'daß nicht mein Feind rühme, ersei mein machtig worden, und meine Widersacher sich nicht freuen, daß ich niederliege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Ich hoffe aber darauf, daß du so gnadig bist; mein Herz freuet sich, daß du so gerne hilfest. Ich will dem HERRN singen, daß er so wohl an mir tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Ein Psalm Davids, vorzusingen. Die Toren sprechen in ihrem Herzen: Es ist kein Gott. Sie taugen nichts und sind ein Greuel mit ihrem Wesen. Da ist keiner, der Gutes tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Der HERR schauet vom Himmel auf der Menschen Kinder, daß er sehe, ob jemand klug sei und nach Gott frage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Aber sie sind alle abgewichen und allesamt unttichtig; da ist keiner, der Gutes tue, auch nicht einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Will denn der Ubeltater keiner das merken, die mein Volk fressen, daß sie sich nahren, aber den HERRN rufen sie nicht an?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Daselbst furchten sie sich; aber Gott ist bei dem Geschlecht der Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Ihr schandet des Armen Rat; aber Gott ist seine Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ach, daß die Hilfe aus Zion uber Israel kame, und der HERR sein gefangen Volk erlosete! So würde Jakob frohlich sein und Israel sich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Ein Psalm Davids. HERR, wer wird wohnen in deiner Hütte? Wer wird bleiben auf deinem heiligen Berge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Wer ohne Wandel einhergehet und recht tut und redet die Wahrheit von Herzen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'wer mit seiner Zunge nicht verleumdet und seinem Nachsten kein Arges tut und seinen Nachsten nicht schmahet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'wer die Gottlosen nichts achtet, sondern ehret die Gottesfurchtigen; wer seinem Nachsten schworet und halt es;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'wer sein Geld nicht auf Wucher gibt und nimmt nicht Geschenke uber den Unschuldigen: wer das tut, der wird wohl bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Ein gulden Kleinod Davids. Bewahre mich, Gott; denn ich traue auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Ich habe gesagtzu dem HERRN: Du bistja der HERR, ich muft urn deinetwillen leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Fur die Heiligen, so auf Erden sind, und fur die Herrlichen; an denen habe ich all mein Gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Aber jene, die einem andern nacheilen, werden graft Herzeleid haben. Ich will ihres Trankopfers mit dem Blut nicht opfern, noch ihren Namen in meinem Munde führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Der HERR aber ist mein Gut und mein Teil; du erhaltst mein Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Das Los ist mir gefallen aufs Liebliche; mir ist ein schon Erbteil worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Ich lobe den HERRN, der mir geraten hat; auch zuchtigen mich meine Nieren des Nachts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Ich habe den HERRN allezeit vor Augen; denn er ist mir zur Rechten, darum werde ich wohl bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Darum freuet sich mein Herz, und meine Ehre ist frohlich, auch mein Fleisch wird sicher liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Denn du wirst meine Seele nicht in der Holle lassen und nicht zugeben, daß dein Heiliger verwese.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du tust mir kund den Weg zum Leben; vor dir ist Freude die Fülle und lieblich Wesen zu deiner Rechten ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ein Gebet Davids. HERR, erhore die Gerechtigkeit, merke auf mein Geschrei, vernimm mein Gebet, das nicht aus falschem Munde gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Sprich du in meiner Sache und schaue du aufs Recht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Du prufest mein Herz und besuchest es des Nachts und lauterst mich und findest nichts. Ich habe mir vorgesetzt, daß mein Mund nicht soil ubertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Ich bewahre mich in dem Wort deiner Lippen vor Menschenwerk auf dem Wege des Morders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Erhalte meinen Gang auf deinen Fuftsteigen, daß meine Tritte nicht gleiten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ich rufe zu dir, daß du, Gott, wollest mich erhoren; neige deine Ohren zu mir, hore meine Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Beweise deine wunderliche Güte, du Heiland derer, die dir vertrauen, wider die, so sich wider deine rechte Hand setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Behüte mich wie einen Augapfel im Auge; beschirme mich unter dem Schatten deiner Flugel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'vor den Gottlosen, die mich verstoren, vor meinen Feinden, die urn und urn nach meiner Seele stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Ihre Fetten halten zusammen; sie reden mit ihrem Munde stolz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Wowirgehen so umgeben sie uns; ihre Augen richten sie dahin, daß sie uns zur Erde sturzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'gleichwie ein Lowe, der des Raubes begehrt, wie ein junger Lowe, der in der Hohle sitzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'HERR, mache dich auf, überwaltige ihn und demutige ihn; errette meine Seele von dem Gottlosen mit deinem Schwert,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'von den Leuten deiner Hand, HERR, von den Leuten dieser Welt, welche ihr Teil haben in ihrem Leben, welchen du den Bauch fullest mit deinem Schatz, die da Kinder die Fülle haben und lassen ihr übriges ihren Jungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ich aber will schauen dein Antlitz in Gerechtigkeit; ich will satt werden, wenn ich erwache nach deinem Bilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Ein Psalm vorzusingen, Davids, des HERRN Knechts, welcher hat dem HERRN die Worte dieses Liedes geredet zur Zeit, da ihn der HERR errettet hatte von der Hand seiner Feinde und von der Hand Sauls,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'und sprach: Herzlich lieb habe ich dich, HERR, meine Starke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'HERR, mein Fels, meine Burg, mein Erretter, mein Gott, mein Hort, auf den ich traue, mein Schild und Horn meines Heils, und mein Schutz!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Ich will den HERRN loben und anrufen, so werde ich von meinen Feinden erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Denn es umfingen mich des Todes Bande, und die Bache Belials erschreckten mich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'der Hollen Bande umfingen mich, und des Todes Stricke uberwaltigten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Wenn mir angst ist, so rufe ich den HERRN an und schreie zu meinem Gott, so erhoret er meine Stimme von seinem Tempel, und mein Geschrei kommt vor ihn zu seinen Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Die Erde bebete und ward bewegt, und die Grundfesten der Berge regeten sich und bebeten, da er zornig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Dampf ging auf von seiner Nase und verzehrend Feuer von seinem Munde, daß es davon blitzete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Er neigete den Himmel und fuhr herab, und Dunkel war unterseinen Füften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Und erfuhr auf dem Cherub und flog daher; er schwebete auf den Fittichen des Windes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Sein Gezeltum ihn herwarfinsterund schwarze dicke Wolken, darin er verborgen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Vom Glanz vor ihm trenneten sich die Wolken mit Hagel und Blitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Und der HERR donnerte im Himmel, und der Hochste lieft seinen Donner aus mit Hagel und Blitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Er schofi seine Strahlen und zerstreuete sie; er lieli sehr blitzen und schreckte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Da sah man Wassergusse, und des Erdbodens Grund ward aufgedeckt, HERR, von deinem Schelten, von dem Odem und Schnauben deiner Nase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Er schickte aus von der Hohe und holete mich und zog mich aus grolien Wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Er errettete mich von meinen starken Feinden, von meinen Hassern, die mirzu machtig waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Die mich überwaltigten zur Zeit meines Unfalls; und der HERR ward meine Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Und er fuhrete mich aus in den Raum, errüi mich heraus; denn er hatte Lust zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Der HERR tutwohl an mir nach meiner Gerechtigkeit; er vergilt mir nach der Reinigkeit meiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Denn ich halte die Wege des HERRN und bin nicht gottlos wider meinen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Denn alle seine Rechte hab ich vor Augen und seine Gebote werfe ich nicht von mir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'sondern ich bin ohne Wandel vor ihm und hute mich vorßunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Darum vergilt mir der HERR nach meiner Gerechtigkeit, nach der Reinigkeit meiner Hande vor seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Beiden Heiligen bistdu heilig und bei den Frommen bist du fromm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'und bei den Reinen bist du rein und bei den Verkehrten bist du verkehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Denn du hilfst dem elenden Volk und die hohen Augen niedrigest du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Denn du erleuchtest meine Leuchte; der HERR, mein Gott, macht meine Finsternis licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Denn mit dir kann ich Kriegsvolk zerschmeilien und mit meinem Gott fiber die Mauern springen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Gottes Wege sind ohne Wandel; die Reden des HERRN sind durchlautert. Er istein Schild alien, die ihm vertrauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Denn wo istein Gott ohne dem HERRN? Oder ein Hort ohne unsern Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Gott rustet mich mit Kraft und macht meine Wege ohne Wandel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Er macht meine Fülie gleich den Hirschen und stellet mich auf meine Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Er lehret meine Hand streiten und lehret meinen Arm einen ehernen Bogen spannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Und gibst mir den Schild deines Heils, und deine Rechte starket mich; und wenn du mich demutigest, machst du mich graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Du machst unter mir Raum zu gehen, daß meine Knochel nicht gleiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Ich will meinen Feinden nachjagen und sie ergreifen und nicht umkehren, bis ich sie umgebracht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Ich will sie zerschmeilien, und sollen mir nicht widerstehen; sie mussen unter meine Fülie fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Du kannst mich rüsten mit Starke zum Streit; du kannst unter mich werfen, die sich wider mich setzen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Du gibst mir meine Feinde in die Flucht, daß ich meine Hasser verstore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Sie rufen, aber da ist kein Heifer; zum HERRN, aber er antwortet ihnen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Ich will sie zerstoften wie Staub vor dem Winde; ich will sie wegraumen wie den Kot auf der Gasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du hilfst mir von dem zankischen Volk und machst mich ein Haupt unter den Heiden; ein Volk, das ich nicht kannte, dienet mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Es gehorchet mir mit gehorsamen Ohren; ja, den fremden Kindern hat\'s wider mich gefehlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Die fremden Kinder verschmachten und zappeln in ihren Banden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Der HERR lebet, und gelobet sei mein Hort; und der Gott meines Heils müsse erhaben werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'der Gott, der mir Rache gibt und zwinget die Volker unter mich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'der mich errettet von meinen Feinden und erhohet mich aus denen, die sich wider mich setzen. Du hilfst mir von den Frevlern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Darum will ich dir danken, HERR, unter den Heiden und deinem Namen lobsingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, 'der seinem Konige graft Heil beweiset und wohltut seinem Gesalbten, David, und seinem Samen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Die Himmel erzahlen die Ehre Gottes, und die Feste verkundiget seiner Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ein Tag sagt\'s dem andern, und eine Nacht tut\'s kund der andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Es ist keine Sprache noch Rede, da man nicht ihre Stimme hore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Ihre Schnur gehet aus in alle Lande und ihre Rede an der Welt Ende; er hat der Sonne eine Hütte in denselben gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Und dieselbe gehet heraus, wie ein Brautigam aus seiner Kammer, und freuet sich wie ein Held, zu laufen den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Sie gehet auf an einem Ende des Himmels und lauft urn bis wieder an dasselbe Ende; und bleibt nichts vor ihrer Hitze verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Das Gesetz des HERRN ist ohne Wandel und erquicket die Seele. Das Zeugnis des HERRN ist gewiß und macht die Albernen weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Die Befehle des HERRN sind richtig und erfreuen das Herz. Die Gebote des HERRN sind lauter und erleuchten die Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Die Furchtdes HERRN ist rein und bleibt ewiglich. Die Rechte des HERRN sind wahrhaftig, allesamt gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Sie sind kostlicher denn Gold und viel feines Gold; sie sind sußerdenn Honig und Honigseim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Auch wird dein Knecht durch sie erinnert; und wer sie halt, der hat großen Lohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Wer kann merken, wie ofterfehlet? Verzeihe mir die verborgenen Fehle!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Bewahre auch deinen Knecht vor den Stolzen, daß sie nicht uber mich herrschen; so werde ich ohne Wandel sein und unschuidig bleiben großer Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, 'Laß dir wohlgefallen die Rede meines Mundes und das Gesprach meines Herzens vor dir, HERR, mein Hort und mein Erloser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Der HERR erhore dich in der Not; der Name des Gottes Jakobs schutze dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Er sende dir Hilfe vom Heiligtum und starke dich aus Zion!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Er gedenke all deines Speisopfers, und dein Brandopfer musse fett sein. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Er gebe dir, was dein Herz begehret, und erfülle alle deine Anschlage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Wir rühmen, daß du uns hilfst; und im Namen unsers Gottes werfen wir Panier auf. Der HERR gewahre dir alle deine Bitte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nun merke ich, daß der HERR seinem Gesalbten hilft und erhoret ihn in seinem heiligen Himmel; seine rechte Hand hilft gewaltiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Jene verlassen sich auf Wagen und Rosse; wir aber denken an den Namen des HERRN, unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Sie sind niedergesturzt und gefallen; wir aber stehen aufgerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, 'Hilf, HERR! Der Konig erhore uns, wenn wir rufen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'HERR, der Konig freuet sich in deiner Kraft, und wie sehrfrohlich ist er uber deine Hilfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Du gibst ihm seines Herzens Wunsch und weigerst nicht, was sein Mund bittet. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Denn du uberschuttest ihn mit gutem Segen; du setzest eine güldene Krone auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Er bittet dich urns Leben, so gibst du ihm langes Leben immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Er hatgroße Ehre an deiner Hilfe; du legest Lob und Schmuck auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Denn du setzest ihn zum Segen ewiglich, du erfreuest ihn mit Freuden deines Antlitzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Denn der Konig hoffet auf den HERRN und wird durch die Gute des Hochsten festbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Deine Hand wird finden alle deine Feinde; deine Rechte wird finden, die dich hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Du wirstsie machen wie einen Feuerofen, wenn du dreinsehen wirst; der HERR wird sie verschlingen in seinem Zorn; Feuerwird sie fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Ihre Frucht wirst du umbringen vom Erdboden und ihren Samen von den Menschenkindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Denn siegedachten dir Ubelszu tun, und machten Anschlage, die sie; nicht konnten ausfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Denn du wirst sie zur Schulter machen; mit deiner Sehne wirst du gegen ihr Antlitz zielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, 'HERR, erhebe dich in deiner Kraft, sowollen wirsingen und loben deine Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Ein Psalm Davids, vorzusingen, von der Hindin, die fruhe gejagt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mein Gott, mein Gott, warum hast du mich verlassen? Ich heule, aber meine Hilfe ist feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mein Gott, des Tages rufe ich, so antwortest du nicht; und des Nachts schweige ich auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Aber du bist heilig, der du wohnest unter dem Lob Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Unsere Vater hofften auf dich, und da sie hofften, halfest du ihnen aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Zu dir schrieen sie und wurden errettet; sie hofften auf dich und nicht zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Ich aber bin ein Wurm und kein Mensch, ein Spott der Leute und Verachtung des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Alle, die mich sehen, spotten mein, sperren das Maul auf und schutteln den Kopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Er klage es dem HERRN, der helfe ihm aus und errette ihn, hat er Lust zu ihm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Denn du hast mich aus meiner Mutter Leibe gezogen; du warest meine Zuversicht, da ich, noch an meiner Mutter Brusten war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Auf dich bin ich geworfen aus Mutterleibe; du bist mein Gott von meiner Mutter Leib an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Sei nicht feme von mir, denn Angst ist nahe; denn es ist hie kein Heifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Große Farren haben mich umgeben, fette Ochsen haben mich umringet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'ihren Rachen sperren sie auf wider mich wie ein brullender und reißender Lowe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Ich bin ausgeschuttet wie Wasser; alle meine Gebeine haben sich zertrennet; mein Herz ist in meinem Leibe wie zerschmolzen Wachs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Meine Krafte sind vertrocknet wie ein Scherben, und meine Zunge klebet an meinem Gaumen; und du legest mich in des Todes Staub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Denn Hunde haben mich umgeben, und der Bosen Rotte hat sich urn mich gemacht; sie haben meine Hande und Fulie durchgraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ich mochte alle meine Beine zahlen. Sie aber schauen und sehen ihre Lust an mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Sie teilen meine Kleider unter sich und werfen das Los um mein Gewand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Aber du, HERR, sei nicht feme; meine Starke, eile, mirzu helfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Errette meine Seele vom Schwert, meine Einsame von den Hunden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Hilf mir aus dem Rachen des Lowen und errette mich von den Einhomem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Ich will deinen Namen predigen meinen Brüdern, ich will dich in der Gemeine rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Rühmet den HERRN, die ihr ihn furchtet; es ehre ihn aller Same Jakobs, und vor ihm scheue sich aller Same Israels!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Denn er hat nicht verachtet noch verschmahet das Elend des Armen und sein Antlitz vor ihm nicht verborgen, und da er zu ihm schrie horete er\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Dich will ich preisen in der groften Gemeine; ich will meine Gelubde bezahlen vor denen, die ihn fürchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Die Elenden sollen essen, daß sie satt werden, und die nach dem HERRN fragen, werden ihn preisen; euer Herz soil ewiglich leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Es werde gedacht aller Welt Ende, daß sie sich zum HERRN bekehren, und vor ihm anbeten alle Geschlechter der Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Denn der HERR hat ein Reich, und er herrschet unter den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Alle Fetten auf Erden werden essen und anbeten; vor ihm werden Kniee beugen alle, die im Staube liegen, und die, so kümmerlich leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Er wird einen Samen haben, der ihm dienet; vom HERRN wird man verkündigen zu Kindeskind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, 'Sie werden kommen und seine Gerechtigkeit predigen dem Volk, das geboren wird, daß er\'s tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Ein Psalm Davids. Der HERR ist mein Hide; mir wird nichts mangeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Er weidet mich auf einer grünen Aue und fuhret mich zum frischen Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Er erquicket meine Seele; er fuhret mich auf rechter Strafte um seines Namens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Und ob ich schon wanderte im finstern Tal, furchte ich kein Unglück; denn du bist bei mir, dein Stecken und Stab trosten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du bereitest vor mir einen Tisch gegen meine Feinde. Du salbest mein Haupt mit 01 und schenkest mirvoll ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Gutes und Barmherzigkeit werden mir folgen mein Leben lang, und ich werde bleiben im Hause des HERRN immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Ein Psalm Davids. Die Erde ist des HERRN, und was drinnen ist, der Erdboden, und was drauf wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Denn er hat ihn an die Meere gegrundet und an den Wassern bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Wer wird auf des HERRN Berg gehen? und wer wird stehen an seiner heiligen Statte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Der unschuldige Hande hat und reines Herzens ist; der nicht Lust hat zu loser Lehre und schworet nicht falschlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Der wird den Segen vom HERRN empfahen und Gerechtigkeit von dem Gott seines Heils.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Das ist das Geschlecht, das nach ihm fraget, das da suchet dein Antlitz, Jakob. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Machet die Tore weit und die Türen in der Welt hoch, daß der Konig der Ehren einziehe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Wer ist derselbe Konig der Ehren? Es ist der HERR, stark und machtig, der HERR, machtig im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Machet die Tore weit und die Türen in der Welt hoch, daß der Konig der Ehren einziehe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Wer ist derselbe Konig der Ehren? Es ist der HERR Zebaoth, er ist der Konig der Ehren. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Ein Psalm Davids. Nach dir, HERR, verlanget mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mein Gott, ich hoffe auf dich. Laft mich nicht zuschanden werden, daß sich meine Feinde nicht freuen über mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Denn keinerwird zuschanden, der dein harret; aber zuschanden müssen sie werden, die losen Verachter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'HERR, zeige mirdeine Wege und lehre mich deine Steige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Leite mich in deiner Wahrheit und lehre mich; denn du bist der Gott, der mir hilft; taglich harre ich dein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Gedenke, HERR, an deine Barmherzigkeit und an deine Güte, die von der Welt her gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Gedenke nicht der Sunden meiner Jugend und meiner Ubertretung; gedenke aber mein nach deiner Barmherzigkeit um deiner Güte willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Der HERR ist gut und fromm, darum unterweiset er die Sunder auf dem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Er leitet die Elenden recht und lehret die Elenden seinen Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Die Wege des HERRN sind eitel Güte und Wahrheit denen, die seinen Bund und Zeugnis halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Um deines Namens willen, HERR, sei gnadig meiner Missetat, die da graft ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Wer ist der, der den HERRN fürchtet? Er wird ihn unterweisen den besten Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Seine Seele wird im Guten wohnen, und sein Same wird das Land besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Das Geheimnis des HERRN ist unter denen, die ihn furchten, und seinen Bund laftt er sie wissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meine Augen sehen stets zu dem HERRN denn er wird meinen Fuß aus dem Netze ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Wende dich zu mir und sei mir gnadig; denn ich bin einsam und elend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Die Angst meines Herzens ist groß; führe mich aus meinen Noten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Siehe an meinen Jammer und Elend und vergib miralle meine Sunde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Siehe, daß meiner Feinde so viel ist und hassen mich aus Frevel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Bewahre meine Seele und errette mich; laß mich nicht zuschanden werden, denn ich traue auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Schlecht und recht, das behute mich; denn ich harre dein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Gott, erlose Israel aus aller, seiner Not!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Ein Psalm Davids. HERR, schaffe mir Recht, denn ich bin unschuldig. Ich hoffe auf den HERRN, darum werde ich nicht fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Prüfe mich, HERR, und versuche mich; lautere meine Nieren und mein Herz!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Denn deine Güte ist vor meinen Augen, und ich wandele in deiner Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Ich sitze nicht bei den eiteln Leuten und habe nicht Gemeinschaft mit den Falschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Ich hasse die Versammlung der Boshaftigen und sitze nicht bei den Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Ich wasche meine Hande mit Unschuld und halte mich, HERR, zu deinem Altar,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'da man horet die Stimme des Dankens und da man prediget alle deine Wunder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'HERR, ich habe lieb die Statte deines Hauses und den Ort, da deine Ehre wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Raffe meine Seele nicht hin mit den Sundern, noch mein Leben mit den Blutdurstigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'welche mit bosen Tucken umgehen und nehmen gerne Geschenke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ich aber wandele unschuldig. Erlose mich und sei mir gnadig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mein Fuß gehet richtig. Ich will dich loben, HERR, in den Versammlungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Ein Psalm Davids. Der HERR ist mein Licht und mein Heil; vorwem sollt ich mich fürchten? Der HERR ist meines Lebens Kraft; vorwem sollte mirgrauen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Darum, so die Bosen, meine Widersacher und Feinde, an mich wollen, mein Fleisch zu fressen, müssen sie anlaufen und fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Wenn sich schon ein Heer wider mich legt, so furchtet sich dennoch mein Herz nicht; Wenn sich Krieg wider mich erhebt, so verlasse ich mich auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eins bitte ich vom HERRN, das hatte ich gerne, daß ich im Hause des HERRN bleiben moge mein Leben lang, zu schauen die schonen Gottesdienste des HERRN und seinen Tempel zu besuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Denn er deckt mich in seiner Hütte zur bosen Zeit, erverbirget mich heimlich in seinem Gezelt und erhohet mich auf einem Felsen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'und wird nun erhohen mein Haupt über meine Feinde, die urn mich sind; so will ich in seiner Hütte Lob opfern, ich will singen und lobsagen dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'HERR, hore meine Stimme, wenn ich rufe; sei mir gnadig und erhore mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Mein Herz halt dir vor dein Wort: Ihr sollt mein Antlitz suchen. Darum suche ich auch, HERR, dein Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Verbirg dein Antlitz nicht vor mir und verstofte nicht im Zorn deinen Knecht; denn du bist meine Hilfe. Laft mich nicht und tu nicht von mir die Hand ab, Gott, mein Heil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Denn mein Vater und meine Mutter verlassen mich; aber der HERR nimmt mich auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'HERR weise mir deinen Weg und leite mich auf richtiger Bahn urn meiner Feinde willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gib mich nicht in den Willen meiner Feinde; denn es stehen falsche Zeugen wider mich und tun mir unrecht ohne Scheu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Ich glaube aber doch, daß ich sehen werde das Gute des HERRN im Lande der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Harre des HERRN! Sei getrost und unverzagt und harre des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Ein Psalm Davids. Wenn ich rufe zur dir, HERR, mein Hort, so schweige mir nicht, auf daß nicht, wo du schweigest, ich gleich werde denen, die in die Holle fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Hore die Stimme meines Flehens, wenn ich zu dirschreie, wenn ich meine Hande aufhebe zu deinem heiligen Chor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Zeuch mich nicht hin unter den Gottlosen und unter den Ubeltatern, die freundlich reden mit ihrem Nachsten und haben Boses im Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Gib ihnen nach ihrer Tat und nach ihrem bosen Wesen; gib ihnen, nach den Werken ihrer Hande; vergilt ihnen, was sie verdienet haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Denn sie wollen nicht achten auf das Tun des HERRN noch auf die Werke seiner Hande; darum wird er sie zerbrechen und nicht bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Gelobet sei der HERR; denn er hat erhoret die Stimme meines Flehens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Der HERR ist meine Starke und mein Schild; auf ihn hoffet mein Herz, und mir ist geholfen; und mein Herz istfrohlich, und ich will ihm danken mit meinem Liede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Der HERR ist ihre Starke; er ist die Starke, die seinem Gesalbten hilft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Hilf deinem Volk und segne dein Erbe; und weide sie und erhohe sie ewiglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Ein Psalm Davids. Bringet her dem HERRN, ihr Gewaltigen bringet her dem HERRN Ehre und Starke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Bringet dem HERRN Ehre seines Namens; betet an den HERRN in heiligem Schmuck!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Die Stimme des HERRN gehet auf den Wassern; der Gott der Ehren donnert, der HERR auf großen Wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Die Stimme des HERRN gehet mit Macht; die Stimme des HERRN gehet herrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Die Stimme des HERRN zerbricht die Zedern; der HERR zerbricht die Zedern im Libanon');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'und machet sie locken wie ein Kalb, Libanon und Sirion wie ein junges Einhorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Die Stimme des HERRN hauet wie Feuerflammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Die Stimme des HERRN erreget die Wüste; die Stimme des HERRN erreget die Wuste Kades.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Die Stimme des HERRN erreget die Hindinnen und entblofiet die Walder. Und in seinem Tempel wird ihm jedermann Ehre sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Der HERR sitzt, eine Sintflut anzurichten. Und der HERR bleibt ein Konig in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Der HERR wird seinem Volk Kraft geben; der HERR wird sein Volk segnen mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein Psalm, zu singen von der Einweihung des Hauses Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Ich preise dich, HERR, denn du hast mich erhohet und lassest meine Feinde sich nicht fiber mich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'HERR, mein Gott, da ich schrie zu dir, machtest du mich gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'HERR, du hast meine Seele aus der Holle gefuhret; du hast mich lebendig behalten, da die in die Holle fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Ihr Heiligen, lobsinget dem HERRN; danket und preiset seine Heiligkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Denn sein Zorn wahret einen Augenblick, und er hat Lust zum Leben; den Abend lang wahret das Weinen, aber des Morgens die Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ich aber sprach, da mir\'s wohl ging: Ich werde nimmermehr daniederliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Denn, HERR, durch dein Wohlgefallen hast du meinen Berg stark gemacht. Aber da du dein Antlitz verbargest, erschrak ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Ich will, HERR, rufen zu dir; dem HERRN will ich flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Was ist nütze an meinem Blut, wenn ich tot bin? Wird dir auch der Staub danken und deine Treue verkundigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'HERR, hore und sei mir gnadig; HERR, sei mein Heifer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Du hast mir meine Klage verwandelt in einen Reigen; du hast meinen Sack ausgezogen und mich mit Freuden gegurtet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, 'auf daß dir lobsinge meine Ehre und nicht stille werde. HERR, mein Gott, ich will dir danken in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'HERR, auf dich traue ich. Lafi mich nimmermehr zuschanden werden; errette mich durch deine Gerechtigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Neige deine Ohren zu mir, eilend hilf mir! Sei mir ein starker Fels und eine Burg, daß du mir helfest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Denn du bist mein Fels und meine Burg, und urn deines Namens willen wollest du mich leiten und fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Du wollest mich aus dem Netze ziehen, das sie mir gestellet haben; denn du bist meine Starke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'In deine Hande befehle ich meinen Geist; du hast mich erloset, HERR, du treuer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Ich hasse, die da halten auf lose Lehre; ich hoffe aber auf den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Ich freue mich und bin frohlich uber deiner Güte, daß du mein Elend ansiehest und erkennest meine Seele in der Not');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'und übergibst mich nicht in die Hande des Feindes; du stellest meine Fulie auf weiten Raum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'HERR, sei mir gnadig, denn mir ist angst; meine Gestalt ist verfallen vor Trauern, dazu meine Seele und mein Bauch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Denn mein Leben hat abgenommen vor Trubnis und meine Zeit vor Seufzen; meine Kraft ist verfallen vor meiner Missetat, und meine Gebeine sind verschmachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Es gehet mir so libel, daß ich bin eine grofie Schmach worden meinen Nachbarn und eine Scheu meinen Verwandten; die mich sehen auf der Gasse, fliehen vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Mein ist vergessen im Herzen wie eines Toten; ich bin worden wie ein zerbrochen Gefali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Denn viele schelten mich libel, daß jedermann sich vor mir scheuet; sie ratschlagen miteinander fiber mich und denken mir das Leben zu nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Ich aber, HERR, hoffe auf dich und spreche: Du bist mein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Meine Zeit stehet in deinen Handen. Errette mich von der Hand meiner Feinde und von denen, die mich verfolgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Lali leuchten dein Antlitz liber deinen Knecht; hilf mir durch deine Güte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'HERR, lali mich nicht zuschanden werden; denn ich rufe dich an. Die Gottlosen müssen zuschanden und geschweiget werden in der Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Verstummen müssen falsche Mauler, die da reden wider den Gerechten, steif, stolz und hohnisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Wie grofi ist deine Güte, die du verborgen hast denen, die dich fürchten, und erzeigest denen, die vor den Leuten auf dich trauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Du verbirgest sie heimlich bei dir vor jedermanns Trotz; du verdeckest sie in der Hutte vor den zankischen Zungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Gelobet sei der HERR, daü er hat eine wunderliche Gute mir bewiesen in einer festen Stadt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Denn ich sprach in meinem Zagen: Ich bin von deinen Augen verstoften; dennoch horetest du meines Flehens Stimme, da ich zu dir schrie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Liebet den HERRN, alle seine Heiligen! Die Glaubigen behutet der HERR und vergilt reichlich dem, der Hochmut übet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, 'Seid getrost und unverzagt, alle, die ihrdes HERRN harret!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Eine Unterweisung Davids. Wohl dem, dem die Gbertretungen vergeben sind, dem die Sunde bedecket ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Wohl dem Menschen, dem der HERR die Missetat nicht zurechnet, in des Geist kein Falsch ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Denn da ich\'s wollte verschweigen, verschmachteten meine Gebeine durch mein taglich Heuien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Denn deine Hand war Tag und Nacht schwer auf mir, daß mein Saft vertrocknete, wie es im Sommer dürre wird. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Darum bekenne ich dir meine Sunde und verhehle meine Missetat nicht. Ich sprach: Ich will dem HERRN meine Ubertretung bekennen. Da vergabest du mir die Missetat meiner Sunde. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Dafür werden dich alle Heiligen bitten zur rechten Zeit; darum, wenn grofte Wasserfluten kommen, werden sie nicht an dieselbigen gelangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du bist mein Schirm; du wollest mich vor Angst behüten, daü ich errettet, ganz frohlich rühmen konnte. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Ich will dich unterweisen und dir den Weg zeigen, den du wandeln sollst; ich will dich mit meinen Augen leiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Seid nicht wie Rosse und Mauler, die nicht verstandig sind, welchen man Zaum und Gebift muft ins Maul legen, wenn sie nicht zu dirwoilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Der Gottlose hat viel Plage; wer aber auf den HERRN hoffet, den wird die Gute umfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Freuet euch des HERRN und seid frohlich, ihr Gerechten, und ruhmet, alle ihr Frommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Freuet euch des HERRN, ihr Gerechten! Die Frommen sollen ihn schon preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Danket dem HERRN mit Harfen und lobsinget ihm auf dem Psalter von zehn Saiten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Singet ihm ein neues Lied; machet es gut auf Saitenspielen mit Schalle!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Denn des HERRN Wort ist wahrhaftig, und was er zusagt, das halt er gewift.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Er liebet Gerechtigkeit und Gericht. Die Erde ist vollder Gute des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Der Himmel ist durchs Wort des HERRN gemacht und all sein Heer durch den Geist seines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Er halt das Wasser im Meer zusammen wie in einem Schlauch und legt die Tiefe ins Verborgene.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Alle Welt furchte den HERRN, und vor ihm scheue sich alles, was auf dem Erdboden wohnet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Denn er spricht, so geschieht\'s; so er gebeut, so stehet\'s da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Der HERR macht zunichte der Heiden Rat und wendet die Gedanken der Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Aber der Rat des HERRN bleibet ewiglich, seines Herzens Gedanken fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Wohl dem Volk, des der HERR ein Gott ist, das Volk, das er zum Erbe erwahlet hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Der HERR schauet vom Himmel und siehet aller Menschen Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Von seinem festen Thron siehet er auf alle, die auf Erden wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Er lenket ihnen alien das Herz, er merket auf alle ihre Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Einem Konige hilft nicht seine grolie Macht; ein Riese wird nicht errettet durch seine grolie Kraft;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Rosse helfen auch nicht, und ihre grolie Starke errettet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Siehe, des HERRN Auge siehet auf die, so ihn furchten, die auf seine Gute hoffen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'daß er ihre Seele errette vom Tode und ernahre sie in der Teurung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Unsere Seele harret auf den HERRN; er ist unsere Hilfe und Schild.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Denn unser Herz freuet sich sein, und wir trauen auf seinen heiligen Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Deine Güte, HERR, sei über uns, wie wir auf dich hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Ein Psalm Davids, da er seine Gebarde verstellete vor Abimelech, der ihn von sich trieb, und erwegging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Ich will den HERRN loben allezeit; sein Lob soil immerdar in meinem Munde sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Meine Seele soil sich rühmen des HERRN, daß die Elenden horen und sich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Preiset mit mir den HERRN und lalit uns miteinander seinen Namen erhohen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Da ich den HERRN suchte, antwortete er mir und errettete mich aus aller meiner Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Welche ihn ansehen und aniaufen, deren Angesicht wird nicht zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Da dieser Elende rief, horete der HERR und half ihm aus alien seinen Noten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Der Engel des HERRN lagert sich urn die her, so ihn furchten, und hilft ihnen aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Schmecket und sehet, wie freundlich der HERR ist! Wohl dem, der auf ihn trauet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Furchtet den HERRN, ihr seine Heiligen; denn die ihn furchten, haben keinen Mangel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Die Reichen müssen darben und hungern; aber die den HERRN suchen, haben keinen Mangel an irgendeinem Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kommt her, Kinder, horetmirzu! Ich will euch die Furcht des HERRN lehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Wer ist, der gut Leben begehrt und gerne gute Tage hatte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Behute deine Zunge vor Bosem und deine Lippen, daß sie nicht falsch reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Laß vom Bosen und tue Gutes, suche Frieden und jage ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Die Augen des HERRN sehen auf die Gerechten und seine Ohren auf ihr Schreien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Das Antlitz aber des HERRN stehet uber die, so Boses tun, daß er ihr Gedachtnis ausrotte von der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Wenn die (Gerechten) schreien, so horet der HERR und errettet sie aus all ihrer Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Der HERR ist nahe bei denen, die zerbrochenes Herzens sind, und hilft denen, die zerschlagen Gemüt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Der Gerechte muß viel leiden; aber der HERR hilft ihm aus dem allem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Er bewahret ihm alle seine Gebeine, daß deren nicht eins zerbrochen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Den Gottlosen wird das Ungluck toten, und die den Gerechten hassen, werden Schuld haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, 'Der HERR erloset die Seele seiner Knechte, und alle, die auf ihn trauen, werden keine Schuld haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Ein Psalm Davids. HERR, hadere mit meinen Haderern; streite wider meine Bestreiter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Ergreife den Schild und Waffen und mache dich auf, mir zu helfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Zucke den Spieß und schütze mich wider meine Verfolger! Sprich zu meiner Seele: Ich bin deine Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Es mussen sich schamen und gehohnet werden, die nach meiner Seele stehen; es mussen zurückkehren und zuschanden werden, die mir ubelwollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Sie mussen werden wie Spreu vor dem Winde, und der Engel des HERRN stolie sie weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Ihr Weg müsse finster und schlupfrig werden, und der Engel des HERRN verfolge sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Denn sie haben mir ohne Ursache gestellet ihre Netze, zu verderben, und haben ohne Ursache meiner Seele Gruben zugerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Er müsse unversehens uberfallen werden, und sein Netz, das er gestellet hat, müsse ihn fahen und müsse drinnen uberfallen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Aber meine Seele müsse sich freuen des HERRN und frohlich sein auf seine Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Alle meine Gebeine müssen sagen: HERR, wer ist deinesgleichen? Der du den Elenden errettest von dem, der ihm zu stark ist, und den Elenden und Armen von seinen Raubern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Es treten frevele Zeugen auf, die zeihen mich, des ich nicht schuldig bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Sie tun mir Arges urn Gutes, mich in Herzeleid zu bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Ich aber, wenn sie krankwaren, zog einen Sack an, tat mir wehe mit Fasten und betete von Herzen stets.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Ich hielt mich, als ware es mein Freund und Bruder; ich ging traurig wie einer, der Leid tragt über seine Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Sie aber freuen sich über meinen Schaden und rotten sich; es rotten sich die Hinkenden wider mich ohne meine Schuld; sie reißen und horen nicht auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Mit denen, die da heucheln und spotten urn des Bauchs willen, beilien sie ihre Zahne zusammen über mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'HERR, wie lange willst du zusehen? Errette doch meine Seele aus ihrem Getümmel und meine Einsame von den jungen Lowen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Ich will dir danken in der großen Gemeine und unter viel Volks will ich dich rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Laß sich nicht fiber mich freuen, die mir unbillig feind sind, noch mit den Augen spotten, die mich ohne Ursache hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Denn sie trachten, Schaden zu tun und suchen falsche Sachen wider die Stillen im Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'und sperren ihr Maul weit auf wider mich und sprechen: Da, da! das sehen wir gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'HERR, du siehest es, schweige nicht; HERR, sei nicht feme von mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Erwecke dich und wache auf zu meinem Recht und zu meiner Sache, mein Gott und HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'HERR, mein Gott, richte mich nach deiner Gerechtigkeit, daß sie sich über mich nicht freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Laß sie nicht sagen in ihrem Herzen: Da, da! das wollten wir. Laß sie nicht sagen: Wir haben ihn verschlungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Sie mussen sich schamen und zu Schanden werden, alle, die sich meines libels freuen; sie mussen mit Schande und Scham gekleidet werden, die sich wider mich rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Rühmen und freuen müssen sich, die mir gonnen, daß ich recht behalte, und immer sagen: Der HERR müsse hoch gelobet sein, der seinem Knechte wohl will!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Und meine Zunge soli reden von deiner Gerechtigkeit und dich taglich preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Ein Psalm Davids, des HERRN Knechts, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Es ist von Grund meines Herzens von der Gottlosen Wesen gesprochen, daß keine Gottesfurcht bei ihnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Sie schmücken sich untereinander selbst, daß sie ihre bose Sache fordern und andere verunglimpfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Alle ihre Lehre ist schadlich und erlogen; sie lassen sich auch nicht weisen, daß sie Gutes taten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'sondern sie trachten auf ihrem Lager nach Schaden und stehen test auf dem bosen Wege und scheuen kein Arges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'HERR, deine Gute reicht, soweit der Himmel ist, und deine Wahrheit, soweit die Wolken gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Deine Gerechtigkeit stehet wie die Berge Gottes und dein Rechtwie grolie Tiefe. HERR, du hilfst Menschen und Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Wie teuer ist deine Gute, Gott, daß Menschenkinder unter dem Schatten deiner Flugel trauen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sie werden trunken von den reichen Gütern deines Hauses, und du trankest sie mit Wollust als mit einem Strom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Denn bei dir ist die lebendige Quelle, und in deinem Licht sehen wir das Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Breite deine Gute uber die, die dich kennen, und deine Gerechtigkeit uber die Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Laß mich nicht von den Stolzen untertreten werden, und die Hand der Gottlosen sturze mich nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, 'sondern laßsie, die Ubeltater, daselbst fallen, daß sie verstoßen werden und nicht bleiben mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Ein Psalm Davids. Erzurne dich nicht uber die Bosen; sei nicht neidisch uber die Ubeltater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Denn wie das Gras werden sie bald abgehauen und wie das grüne Kraut werden sie verwelken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Hoffe auf den HERRN und tue Gutes; bleibe im Lande und nahre dich redlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Habe deine Lust am HERRN; der wird dir geben, was dein Herz wunschet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befiehl dem HERRN deine Wege und hoffe auf ihn; erwird\'swohl machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'und wird deine Gerechtigkeit hervor bringen wie das Licht und dein Recht wie den Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Sei stille dem HERRN und warte auf ihn! Erzurne dich nicht uber den, dem sein Mutwille glücklich fortgehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Stehe ab vom Zorn und laß den Grimm; erzurne dich nicht, daß du auch ubel tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Denn die Bosen werden ausgerottet; die aber des HERRN harren, werden das Land erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Es ist noch urn ein kleines, so ist der Gottlose nimmer; und wenn du nach seiner Statte sehen wirst, wird erweg sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Aber die Elenden werden das Land erben und Lust haben in großem Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Der Gottlose drauet dem Gerechten und beifiet seine Zahne zusammen uber ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Aber der HERR lachet sein; denn er siehet, daß sein Tag kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Die Gottlosen ziehen das Schwert aus und spannen ihren Bogen, dafi sie fallen den Elenden und Armen und schlachten die Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Aber ihr Schwert wird in ihr Herz gehen, und ihr Bogen wird zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Das Wenige, das ein Gerechter hat, ist besser denn das grolie Gut vieler Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Denn der Gottlosen Arm wird zerbrechen; aber der HERR erhalt die Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Der HERR kennet die Tage der Frommen, und ihr Gut wird ewiglich bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Sie werden nicht zuschanden in der bosen Zeit, und in der Teurung werden sie genug haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Denn die Gottlosen werden umkommen, und die Feinde des HERRN, wenn sie gleich sind wie eine kostliche Aue, werden sie doch vergehen, wie der Rauch vergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Der Gottlose borget und bezahlet nicht; der Gerechte aber ist barmherzig und milde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Denn seine Gesegneten erben das Land; aber seine Verfluchten werden ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Von dem HERRN wird solches Mannes Gang gefordert und hat Lust an seinem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Fallt er, so wird er nicht weggeworfen; denn der HERR erhalt ihn bei der Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Ich bin jung gewesen und alt worden und habe noch nie gesehen den Gerechten verlassen Oder seinen Samen nach Brot gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Er ist allezeit barmherzig und leihet gerne; und sein Same wird gesegnet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Lali vom Bosen und tue Gutes, und bleibe immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Denn der HERR hat das Recht lieb und verlalit seine Heiligen nicht; ewiglich werden sie bewahret; aber der Gottlosen Same wird ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Die Gerechten erben das Land und bleiben ewiglich drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Der Mund des Gerechten redet die Weisheit, und seine Zunge lehret das Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Das Gesetz seines Gottes ist, in seinem Herzen, seine Tritte gleiten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Der Gottlose lauert auf den Gerechten und gedenkt ihn zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Aber der HERR lalit ihn nicht in seinen Handen und verdammt ihn nicht, wenn er verurteilt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Harre auf den HERRN und halte seiner Weg, so wird er dich erhohen, dafi du das Land erbest; du wirst\'s sehen, daß die Gottlosen ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Ich habe gesehen einen Gottlosen, der war trotzig und breitete sich aus und grunete wie ein Lorbeerbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Da man voruberging, siehe, da war er dahin; ich fragte nach ihm, da ward er nirgend funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Bleibe fromm und halte dich recht, denn solchem wird\'s zuletzt wohlgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Die Ubertreter aber werden vertilget miteinander, und die Gottlosen werden zuletzt ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Aber der HERR hilft den Gerechten; der ist ihre Starke in der Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Und der HERR wird ihnen beistehen und wird sie erretten; erwird sie von den Gottlosen erretten und ihnen helfen; denn sie trauen auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein Psalm Davids zum Gedachtnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'HERR, strafe mich nicht in deinem Zorn und zuchtige mich nicht in deinem Grimm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Denn deine Pfeile stecken in mir, und deine Hand drucket mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Es ist nichts Gesundes an meinem Leibe vor deinem Drauen, und ist kein Friede in meinen Gebeinen vor meiner Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Denn meine Sünden gehen uber mein Haupt, wie eine schwere Last sind sie mir zu schwer worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Meine Wunden stinken und eitern vor meiner Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Ich gehe krumm und sehr gebuckt; den ganzen Tag gehe ich traurig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Denn meine Lenden verdorren ganz, und ist nichts Gesundes an meinem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Es ist mit mir gar anders und bin sehr zerstoden. Ich heule vor Unruhe meines Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'HERR, vor dir ist alle meine Begierde und mein Seufzen ist dir nicht verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mein Herz bebet, meine Kraft hat mich verlassen, und das Licht meiner Augen ist nicht bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Meine Lieben und Freunde stehen gegen mich und scheuen meine Plage, und meine Nachsten treten feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Und die mir nach der Seele stehen, stellen mir; und die mir ubel wollen, reden, wie sie Schaden tun wollen, und gehen mit eitel Listen urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Ich aber mud sein wie ein Tauber und nicht horen, und wie ein Stummer, derseinen Mund nicht auftut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Und mud sein wie einer, der nicht horet und der keine Widerrede in seinem Munde hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Aber ich harre, HERR, auf dich; du, HERR, mein Gott, wirst erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Denn ich denke, daß sieja sich nicht uber mich freuen. Wenn mein Fufi wankete; würden sie sich hoch rühmen wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Denn ich bin zu Leiden gemacht, und mein Schmerz ist immer vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Denn ich zeige meine Missetat an und sorge fur meine Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Aber meine Feinde leben und sind machtig; die mich unbillig hassen, sind grod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Und die mir Arges tun urn Gutes, setzen sich wider mich, darum dad ich ob dem Guten halte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Verlafi mich nicht, HERR, mein Gott; sei nicht feme von mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, 'Eile mir beizustehen, HERR, meine Hilfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Ein Psalm Davids, vorzusingen, fur Jeduthun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Ich habe mir vorgesetzt, ich will mich hüten, daß ich nicht sundige mit meiner Zunge. Ich will meinen Mund zaumen, weil ich mud den Gottlosen so vor mir sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Ich bin verstummet und still und schweige der Freuden und mull mein Leid in mich fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mein Herz ist entbrannt in meinem Leibe, und wenn ich dran gedenke, werde ich entzundet; ich rede mit meiner Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Aber, HERR, lehre doch mich, daß es ein Ende mit mir haben mud, und mein Leben ein Ziel hat und ich davon mud.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Siehe, meine Tage sind einer Hand breit bei dir, und mein Leben ist wie nichts vor dir. Wie gar nichts sind alle Menschen, die doch so sicher leben! Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Sie gehen daher wie ein Schemen und machen ihnen viel vergeblicher Unruhe; sie sammeln und wissen nicht, wer es kriegen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Nun, HERR, wes soil ich mich trdsten? Ich hoffe auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Errette mich von alter meiner Sunde und lad mich nicht den Narren ein Spott werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Ich will schweigen und meinen Mund nicht auftun; du wirst\'s wohlmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Wende deine Plage von mir; denn ich bin verschmachtet von der Strafe deiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Wenn du einen zuchtigest urn der Sunde willen, so wird seine Schdne verzehret wie von Motten. Ach, wie gar nichts sind doch alle Menschen! Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Hore mein Gebet, HERR, und vernimm mein Schreien und schweige nicht uber meinen Tranen; denn ich bin beides, dein Pilgrim und dein Burger, wie alle meine Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, 'Lad ab von mir, dad ich mich erquicke, ehe denn ich hinfahre und nicht mehr hie sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Ich harrete des HERRN; und er neigete sich zu mir und horete mein Schreien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'und zog mich aus der grausamen Grube und aus dem Schlamm und stellete meine Füde auf einen Fels, dad ich gewid treten kann;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'und hat mir ein neu Lied in meinen Mund gegeben, zu loben unsern Gott. Das werden viele sehen und den HERRN furchten und auf ihn hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Wohl dem, der seine Hoffnung setzt auf den HERRN und sich nicht wendet zu den Hoffartigen, und die mit Lugen umgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'HERR, mein Gott, grod sind deine Wunder und deine Gedanken, die du an uns beweisest. Dir ist nichts gleich. Ich will sie verkundigen und davon sagen, wiewohl sie nicht zu zahlen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Opfer und Speisopfer gefallen dir nicht; aber die Ohren hast du mir aufgetan. Du willst weder Brandopfer noch Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Da sprach ich: Siehe, ich komme; im Buch ist von mir geschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Deinen Willen, mein Gott, tu ich gerne und dein Gesetz hab ich in meinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Ich will predigen die Gerechtigkeit in der grolien Gemeine; siehe, ich will mirmeinen Mund nicht stopfen lassen, HERR, das weiliest du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Deine Gerechtigkeit verberge ich nicht in meinem Herzen; von deiner Wahrheit und von deinem Heil rede ich; ich verhehle deine Gute und Treue nicht vor der grol Len Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Du aber, HERR, wollest deine Barmherzigkeit von mir nicht wenden; laft deine Gute und Treue allewege mich behuten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Denn es hat mich umgeben Leiden ohne Zahl; es haben mich meine Sünden ergriffen, daß ich nicht sehen kann; ihrer ist mehr denn Haare auf meinem Haupt, und mein Herz hat mich verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Laß dir\'s gefallen, HERR, da(S du mich errettest; eile, HERR, mirzu helfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Schamen müssen sich und zuschanden werden, die mir nach meiner Seele stehen, daß sie die umbringen; zurück müssen sie fallen und zuschanden werden, die mir Ubels gonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Sie müssen in ihrer Schande erschrecken, die über mich schreien: Da, da!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Es müssen sich freuen und frohlich sein alle, die nach dirfragen; und die dein Heil lieben, müssen sagen allewege: Der HERR sei hochgelobt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, 'Denn ich bin arm und elend; der HERR aber sorget fur mich. Du bist mein Heifer und Erretter; mein Gott, verzeuch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Wohi dem, der sich des Durftigen annimmt! Den wird der HERR erretten zur bosen Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Der HERR wird ihn bewahren und beim Leben erhalten und ihm lassen wohlgehen auf Erden und nicht geben in seiner Feinde Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Der HERR wird ihn erquicken auf seinem Siechbette; du hilfst ihm von aller seiner Krankheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Ich sprach: HERR, sei mir gnadig, heile meine Seele; denn ich habe an dir gesündiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Meine Feinde reden Arges wider mich: Wann wird er sterben und sein Name vergehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Sie kommen, daß sie schauen, und meinen\'s doch nicht von Herzen, sondern suchen etwas, daß sie lastern mogen, gehen hin und tragen\'s aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Alle, die mich hassen, raunen miteinander wider mich und denken Boses über mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Sie haben ein Bubenstuck über mich beschlossen: Wenn er liegt, soli er nicht wieder aufstehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Auch mein Freund, dem ich mich vertrauete, der mein Brot ali, tritt mich unter die Futie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Du aber, HERR, sei mir gnadig und hilf mir auf, so will ich sie bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Dabei merke ich, dati du Gefallen an mir hast, daß mein Feind über mich nicht jauchzen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Mich aber erhaltst du urn meiner Frommigkeit willen und stellest mich vor dein Angesicht ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, 'Gelobtsei der HERR, der Gott Israels, von nun an bis in Ewigkeit! Amen, Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Eine Unterweisung der Kinder Korah, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Wie der Hirsch schreiet nach frischem Wasser, so schreiet meine Seele, Gott, zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Meine Seele dürstet nach Gott, nach dem lebendigen Gott. Wann werde ich dahin kommen, daß ich Gottes Angesicht schaue?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Meine Tranen sind meine Speise Tag und Nacht, weil man taglich zu mir sagt: Wo ist nun dein Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Wenn ich denn des inne werde, so schutte ich mein Herz heraus bei mir selbst; denn ich wollte gerne hingehen mitdem Haufen und mit ihnen wallen zum Hause Gottes mit Frohlocken und Danken unter dem Haufen, die dafeiern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Was betrubest du dich, meine Seele, und bist so unruhig in mir? Harre auf Gott; denn ich werde ihm noch danken, daß er mir hilft mit seinem Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Mein Gott, betrubt ist meine Seele in mir; darum gedenke ich an dich im Lande am Jordan und Hermonim, auf dem kleinen Berg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Deine Fluten rauschen daher, daß hie eine Tiefe und da eine Tiefe brausen; alle deine Wasserwogen und Wellen gehen über mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Der HERR hat des Tages verheifien seine Gute, und des Nachts singe ich ihm und bete zu Gott meines Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Ich sage zu Gott, meinem Fels: Warum hast du mein vergessen? Warum muü ich so traurig gehen, wenn mein Feind mich dranget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Es ist als ein Mord in meinen Beinen, daß mich meine Feinde schmahen, wenn sie taglich zu mir sagen: Wo ist nun dein Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, 'Was betrubest du dich, meine Seele, und bist so unruhig in mir? Harre auf Gott; denn ich werde ihm noch danken, daß er meines Angesichts Hilfe und mein Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Richte mich, Gott, und führe meine Sache wider das unheilige Volk und errette mich von den falschen und bosen Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Denn du bist der Gott meiner Starke; warum verstofiest du mich? Warum lassest du mich so traurig gehen, wenn mich mein Feind dranget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sende dein Licht und deine Wahrheit, daß sie mich leiten und bringen zu deinem heiligen Berg und zu deiner Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'daß ich hineingehe zum Altar Gottes, zu dem Gott, der meine Freude und Wonne ist, und dir, Gott; auf der Harfe danke, mein Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Was betrubest du dich, meine Seele, und bistso unruhig in mir? Harre auf Gott; denn ich werde ihm noch danken, daß er meines Angesichts Hilfe und mein Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Eine Unterweisung der Kinder Korah, vorzusingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Gott, wir haben mit unsern Ohren gehoret, unsere Vater haben uns erzahlet, was du getan hast zu ihren Zeiten vor alters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Du hast mit deiner Hand die Heiden vertrieben, aber sie hast du eingesetzt; du hast die Volker verderbet, aber sie hast du ausgebreitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Denn sie haben das Land nicht eingenommen durch ihr Schwert, und ihr Arm half ihnen nicht, sondern deine Rechte, dein Arm und das Licht deines Angesichts; denn du hattest Wohlgefallen an ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Gott, du bist derselbe mein Konig, der du Jakob Hilfe verheiftest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Durch dich wollen wir unsere Feinde zerstoften; in deinem Namen wollen wir untertreten, die sich wider uns setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Denn ich verlasse mich nicht auf meinen Bogen, und mein Schwert kann mir nicht helfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'sondern du hilfst uns von unsern Feinden und machest zuschanden, die uns hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Wir wollen taglich rühmen von Gott und deinem Namen danken ewiglich. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Warum verstoftest du uns denn nun und lassest uns zuschanden werden und zeuchst nicht aus unter unserm Heer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Du lassest uns fliehen vor unserm Feinde, daß uns berauben, die uns hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Du lassest uns auffressen wie Schafe und zerstreuest uns unter die Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Du verkaufest dein Volk umsonst und nimmst nichts drum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Du machst uns zur Schmach unsern Nachbarn, zum Spott und Hohn denen, die urn uns her sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Du machst uns zum Beispiel unter den Heiden, und daß die Volker das Haupt uber uns schutteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Taglich ist meine Schmach vor mir, und mein Antlitz ist voller Schande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'daß ich die Schander und Lasterer horen und die Feinde und Rachgierigen sehen muft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Dies alles ist uber uns kommen, und haben doch dein nicht vergessen, noch untreulich in deinem Bunde gehandelt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'unser Herz ist nicht abgefallen, noch unser Gang gewichen von deinem Wege,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'daß du uns so zerschlagest unter den Drachen und bedeckest uns mit Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Wenn wir des Namens unsers Gottes vergessen hatten und unsere Hande aufgehoben zum fremden Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'das mochte Gottwohl finden; nun kenneterja unsers Herzens Grund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Denn wir werden ja urn deinetwillen taglich erwürget und sind geachtet wie Schlachtschafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Erwecke dich, HERR, warum schlafst du? Wache auf und verstofte uns nicht so gar!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Warum verbirgest du dein Antlitz, vergissest unsers Elends und Dranges?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Denn unsere Seele ist gebeuget zur Erde; unser Bauch klebet am Erdboden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, 'Mache dich auf, hilf uns und erlose uns urn deiner Gutewillen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Ein Brautlied und Unterweisung der Kinder Korah von den Rosen, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mein Herz dichtet ein feines Lied ich will singen von einem Konige; meine Zunge ist ein Griffel eines guten Schreibers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Du bist der Schonste unter den Menschenkindern; holdselig sind deine Lippen; darum segnet dich Gott ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Gurte dein Schwert an deine Seite, du Held, und schmucke dich schon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Es musse dir gelingen, in deinem Schmuck. Zeuch einher der Wahrheit zu gut, und die Elenden bei Recht zu behalten, so wird deine rechte Hand Wunder beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Scharf sind deine Pfeile, daß die Volker vor dir niederfallen mitten unter den Feinden des Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'dein Stuhl bleibt immer und ewig; das Zepter deines Reichs ist ein gerades Zepter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du liebest Gerechtigkeit und hassest gottlos Wesen; darum hat dich, Gott, dein Gott gesalbet mit Freudenole, mehr denn deine Gesellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Deine Kleider sind eitel Myrrhen, Aloe und Kezia, wenn du aus den elfenbeinernen Palasten dahertrittst in deiner schonen Pracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'In deinem Schmuck gehen der Konige Tochter; die Braut stehet zu deiner Rechten in eitel kostlichem Goide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Hore, Tochter, schaue drauf und neige deine Ohren; vergift deines Volks und deines Vaters Haus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'so wird der Konig Lust an deiner Schone haben; denn er ist dein HERR, und solist ihn anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Die Tochter Zor wird mit Geschenk da sein, die Reichen im Volk werden vor dir flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Des Konigs Tochter ist ganz herrlich inwendig; sie ist mit guldenen Stricken gekleidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Man fuhret sie in gestickten Kleidern zum Konig; und ihre Gespielen, die Jungfrauen, die ihr nachgehen, führet man zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Man führet sie mit Freuden und Wonne, und gehen in des Konigs Palast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Anstatt deiner Vater wirst du Kinder kriegen; die wirst du zu Fursten setzen in aller Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, 'Ich will deines Namens gedenken von Kind zu Kindeskind; darum werden dir danken die Volker immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Ein Lied der Kinder Korah von der Jugend, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gott ist unsere Zuversicht und Starke, eine Hilfe in den grolien Noten, die uns getroffen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Darum furchten wir uns nicht, wenngleich die Welt unterginge und die Berge mitten ins Meer sanken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'wenngleich das Meer wütete und wallete und von seinem Ungestum die Berge einfielen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Dennoch soil die Stadt Gottes fein lustig bleiben mit ihren Brunnlein, da die heiligen Wohnungen des Hochsten sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Gott ist bei ihr drinnen, darum wird sie wohl bleiben; Gott hilft ihr fruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Die Heiden müssen verzagen und die Konigreiche fallen; das Erdreich muli vergehen, wenn er sich horen lafit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Der HERR Zebaoth ist mit uns, der Gott Jakobs ist unser Schutz. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kommt her und schauet die Werke des HERRN, der auf Erden solch Zerstoren anrichtet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'der den Kriegen steuert in aller Welt, der Bogen zerbricht, Spielie zerschlagt und Wagen mit Feuer verbrennt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Seid stille und erkennet, daü ich Gott bin! Ich will Ehre einlegen unter den Heiden, ich will Ehre einlegen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, 'Der HERR Zebaoth ist mit uns, der Gott Jakobs ist unser Schutz. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Ein Psalm, vorzusingen, der Kinder Korah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Frohlocket mit Handen, alle Volker, und jauchzet Gott mit frbhlichem Schall!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Denn der HERR, der Allerhochste, ist erschrecklich, ein grower Konig auf dem ganzen Erdboden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Er wird die Volker unter uns zwingen und die Leute unter unsere Fülie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Er erwahlet uns zum Erbteil, die Herrlichkeit Jakobs, den er liebet. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Gott fahret auf mit Jauchzen und der HERR mit heller Posaune.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Lobsinget, lobsinget Gott; lobsinget, lobsinget unserm Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Denn Gott ist Konig auf dem ganzen Erdboden; lobsinget ihm kluglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Gott ist Konig uber die Heiden; Gott sitzt auf seinem heiligen Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, 'Die Fursten unter den Volkern sind versammelt zu einem Volk dem Gott Abrahams; denn Gott ist sehr erhohet bei den Schilden auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein Psalmlied der Kinder Korah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Groli ist der HERR und hoch beruhmt in der Stadt unsers Gottes, auf seinem heiligen Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Der Berg Zion ist wie ein schon Zweiglein, des sich das ganze Land trostet; an der Seite gegen Mitternacht liegt die Stadt des grolien Konigs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Gott ist in ihren Palasten bekannt, daß er der Schutz sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Denn siehe, Konige sind versammelt und miteinander vorübergezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Sie haben sich verwundert, da sie solches sahen; sie haben sich entsetzt und sind gesturzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Zittern ist sie daselbst angekommen, Angst wie eine Gebarerin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Du zerbrichst Schiffe im Meer durch den Ostwind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Wie wir gehoret haben, so sehen wir\'s an der Stadt des HERRN Zebaoth, an der Stadt unsers Gottes; Gott erhalt dieselbige ewiglich. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Gott, wir warten deiner Güte in deinem Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Gott, wie dein Name, so ist auch dein Ruhm, bis an der Welt Ende; deine Rechte ist voll Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Es freue sich der Berg Zion, und die Tochter Judas seien frohlich urn deiner Rechte willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Macht euch urn Zion und umfahet sie; zahlet ihre Turme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Leget Fleili an ihre Mauern und erhohet ihre Palaste, auf daß man davon verkundige bei den Nachkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, 'daß dieser Gott sei unser Gott immer und ewiglich. Er führet uns wie die Jugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Ein Psalm der Kinder Korah, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Horet zu, alle Volker; merket auf, alle, die in dieser Zeit leben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'beide gemein Mann und Herren, beide reich und arm miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Mein Mund soli von Weisheit reden und mein Herz von Verstand sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Wirwollen einen guten Spruch horen und ein fein Gedicht auf der Harfe spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Warum sollt ich mich furchten in bosen Tagen, wenn mich die Missetat meiner Ubertreter umgibt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Die sich verlassen auf ihr Gut und trotzen auf ihren grolien Reichtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Kann doch ein Bruder niemand erlosen noch Gott jemand versohnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'denn es kostet zu viel, ihre Seele zu erlosen, daß er\'s muß lassen anstehen ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'ob er auch gleich lange lebet und die Grube nicht siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Denn man wird sehen, daß solche Weisen doch sterben, sowohl als die Toren und Narren umkommen, und mussen ihr Gut andern lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Das ist ihr Herz, daß ihre Hauser wahren immerdar, ihre Wohnungen bleiben fur und fur und haben große Ehre auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Dennoch konnen sie nicht bleiben in solcher Wurde, sondern müssen davon wie ein Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Dies ihr Tun isteitel Torheit; noch loben\'s ihre Nachkommen mit ihrem Munde Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Sie liegen in der Holle wie Schafe, der Tod naget sie; aber die Frommen werden gar bald uber sie herrschen, und ihr Trotz muß vergehen, in der Holle mussen sie bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Aber Gott wird meine Seele erlosen aus der Holle Gewalt; denn er hat mich angenommen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Laü dich\'s nicht irren, ob einer reich wird, ob die Herrlichkeit seines Hauses groß wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Denn erwird nichts in seinem Sterben mitnehmen, und seine Herrlichkeit wird ihm nicht nachfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'sondern er trostet sich dieses guten Lebens und preisetes, wenn einer nach guten Tagen trachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'So fahren sie ihren Vatern nach und sehen das Licht nimmermehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, 'Kurz, wenn ein Mensch in der Wurde ist und hat keinen Verstand, so fahret er davon wie ein Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Psalm Assaphs. Gott der HERR, der Machtige, redet und ruft der Welt von Aufgang der Sonne bis zum Niedergang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Aus Zion bricht an der schone Glanz Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Unser Gott kommt und schweiget nicht. Fressend Feuer gehet vor ihm her und urn ihn her ein groß Wetter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Er ruft Himmel und Erde, daß er sein Volk richte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Versammelt mir meine Heiligen, die den Bund mehr achten denn Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Und die Himmel werden seine Gerechtigkeit verkundigen; denn Gott ist Richter. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Hore, mein Volk, laß mich reden, Israel; laß mich unterdirzeugen: Ich, Gott, bin dein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Deines Opfers halben strafe ich dich nicht; sind doch deine Brandopfer sonst immer vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Ich will nicht von deinem Hause Farren nehmen, noch Bocke aus deinen Stallen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'denn alle Tiere im Walde sind mein und Vieh auf den Bergen, da sie bei tausend gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ich kenne alles Gevogel auf den Bergen, und allerlei Tier auf dem Felde ist vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Wo mich hungerte, wollt ich dir nicht davon sagen; denn der Erdboden ist mein und alles, was drinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Meinest du, daß ich Ochsenfleisch essen wolle, Oder Bocksblut trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Opfere Gott Dank und bezahle dem Hochsten deine Gelubde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Und rufe mich an in der Not, so will ich dich erretten, so sollst du mich preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Aber zum Gottlosen spricht Gott: Was verkundigest du meine Rechte und nimmst meinen Bund in deinen Mund,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'so du doch Zucht hassest und wirfst meine Worte hinter dich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Wenn du einen Dieb siehest, so laufst du mit ihm und hast Gemeinschaft mit den Ehebrechern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Dein Maul lassestdu Boses reden, und deine Zunge treibet Falschheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Du sitzest und redest wider deinen Bruder, deiner Mutter Sohn verleumdest du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Das tust du, und ich schweige. Da meinest du, ich werde sein gleich wie du. Aber ich will dich strafen und will dir\'s unter Augen stellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Merket doch das, die ihr Gottes vergesset, daß ich nicht einmal hinreiße, und sei kein Retter mehr da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Wer Dank opfert, der preiset mich; und da ist der Weg, daß ich ihm zeige das Heil Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Ein Psalm Davids, vorzusingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'da der Prophet Nathan zu ihm kam, als er war zu Bathseba eingegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Gott, sei mir gnadig nach deiner Gute und tilge meine Sünden nach deiner großen Barmherzigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Wasche mich wohl von meiner Missetat und reinige mich von meiner Sünde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Denn ich erkenne meine Missetat, und meine Sunde ist immer vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'An dir allein hab ich gesundiget und übel vor dir getan, auf daß du recht behaltest in deinen Worten und rein bleibest, wenn du gerichtet wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Siehe, ich bin aus sundlichem Samen gezeuget, und meine Mutter hat mich in Sünden empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Siehe, du hast Lust zur Wahrheit, die im Verborgenen liegt; du lassest mich wissen die heimliche Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Entsündige mich mit Ysopen, daß ich rein werde; wasche mich, daß ich schneeweiß werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Laß mich horen Freude und Wonne, daß die Gebeine frohlich werden, die du zerschlagen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Verbirg dein Antlitzvon meinen Sünden und tilge alle meine Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Schaffe in mir, Gott, ein rein Herz und gib mir einen neuen, gewissen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Verwirf mich nicht von deinem Angesichte und nimm deinen Heiligen Geist nicht von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Troste mich wieder mit deiner Hilfe, und der freudige Geist enthalte mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Denn ich will die Ubertreter deine Wege lehren, daß sich die Sunder zu dir bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Errette mich von den Blutschulden, Gott, der du mein Gott und Heiland bist, daß meine Zunge deine Gerechtigkeit rühme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'HERR, tue meine Lippen auf, daß mein Mund deinen Ruhm verkundige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Denn du hast nicht Lust zum Opfer, ich wollte dir\'s sonst wohl geben; und Brandopfer gefallen dir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Die Opfer, die Gott gefallen, sind ein geangsteter Geist; ein geangstet und zerschlagen Herz wirst du, Gott, nicht verachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, 'Tue wohl an Zion nach deiner Gnade; baue die Mauern zu Jerusalem!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, 'Dann werden dir gefallen die Opfer der Gerechtigkeit, die Brandopfer und ganzen Opfer; dann wird man Farren auf deinem Altar opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Eine Unterweisung Davids, vorzusingen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'da Doeg, der Edomiter, kam und sagte Saul an und sprach: David ist in Ahimelechs Haus kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Was trotzest du denn, du Tyrann, daß du kannst Schaden tun, so doch Gottes Güte noch taglich wahret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Deine Zunge trachtet nach Schaden und schneidet mit Lugen wie ein scharf Schermesser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du redest lieber Boses denn Gutes und falsch denn recht. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du redest gem alles, was zu Verderben dienet, mit falscher Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Darum wird dich Gott auch ganz und gar zerstoren und zerschlagen und aus der Hütte reilien und aus dem Lande der Lebendigen ausrotten. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Und die Gerechten werden\'s sehen und sich furchten und werden sein lachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Siehe, das ist der Mann, der Gott nicht fur seinen Trost hielt, sondern verliefi sich auf seinen grolien Reichtum und war machtig, Schaden zutun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, 'Ich aber werde bleiben wie ein gruner Olbaum im Hause Gottes, verlasse mich auf Gottes Güte immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, 'Ich danke dir ewiglich, denn du kannst\'s wohl machen; und will harren auf deinen Namen, denn deine Heiligen haben Freude dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Eine Unterweisung Davids, im Chor umeinander vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Die Toren sprechen in ihrem Herzen: Es ist kein Gott. Sie taugen nichts und sind ein Greuel worden in ihrem bosen Wesen. Da ist keiner, der Gutes tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Gott schauet vom Himmel auf der Menschen Kinder, daß er sehe, ob jemand klug sei, der nach Gott frage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Aber sie sind alle abgefallen und allesamt untuchtig. Da ist keiner, der Gutes tue, auch nicht einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Wollen denn die Ubeltater ihnen nicht sagen lassen, die mein Volk fressen, daß sie sich nahren? Gott rufen sie nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Da furchten sie sich aber, da nicht zu furchten ist; denn Gott zerstreuet die Gebeine der Treiber. Du machst sie zuschanden; denn Gott verschmahet sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, 'Ach, daß die Hilfe aus Zion liber Israel kame, und Gott sein gefangen Volk erlosete! So würde sich Jakob freuen und Israel frohlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Eine Unterweisung Davids, vorzusingen auf Saitenspielen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'da die von Siph kamen und sprachen zu Saul: David hat sich bei uns verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Hilf mir, Gott, durch deinen Namen und schaffe mir Recht durch deine Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Gott, erhore mein Gebet; vernimm die Rede meines Mundes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Denn Stolze setzen sich wider mich, und Trotzige stehen mir nach meiner Seele und haben Gott nicht vor Augen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Siehe, Gott stehet mir bei; der HERR erhalt meine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Erwird die Bosheit meinen Feinden bezahlen. Zerstore sie durch deine Treue!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, 'So will ich dir ein Freudenopfer tun und deinem Namen, HERR, danken, dad er so trostlich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, 'Denn du errettest mich aus aller meiner Not, daß mein Auge an meinen Feinden Lust siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Eine Unterweisung Davids, vorzusingen auf Saitenspielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Gott, hore mein Gebet und verbirg dich nicht vor meinem Flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Merke auf mich und erhore mich, wie ich so klaglich zage und heule,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'daß der Feind so schreiet, und der Gottlose dranget; denn sie wollen mir einen Tuck beweisen und sind mirheftig gram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mein Herz angstet sich in meinem Leibe, und des Todes Furcht ist auf mich gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Furcht und Zittern ist mich ankommen, und Grauen hat mich uberfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Ich sprach: 0, hatte ich Flugel wie Tauben, daß ich floge und etwa bliebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Siehe, so wollt ich mich feme weg machen und in der Wüste bleiben. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Ich wollt eilen, daß ich entronne vor dem Sturmwind und Wetter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Mache ihre Zunge uneins, HERR, und lali sie untergehen; denn ich sehe Frevel und Hader in der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Solches gehet Tag und Nacht um und um in ihren Mauern; es ist Muhe und Arbeit drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Schadentun regieret drinnen, Lugen und Trugen laftt nicht von ihrer Gasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Wenn mich doch mein Feind schandete, wollt ich\'s leiden, und wenn mir mein FHasser pochte, wollt ich mich vor ihm verbergen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'du aber bist mein Geselle, mein Pfleger und mein Verwandter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'diewirfreundlich miteinander waren unteruns; wirwandelten im Hause Gottes zu Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Der Tod ubereile sie, und müssen lebendig in die Holle fahren; denn es ist eitel Bosheit unter ihrem Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ich aber will zu Gott rufen, und der HERRwird mirhelfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Des Abends, Morgens und Mittags will ich klagen und heulen, so wird er meine Stimme horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Er erloset meine Seele von denen, die an mich wollen, und schaffet ihr Ruhe; denn ihrer ist viel wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gott wird horen und sie demutigen, der allwege bleibt. Sela. Denn sie werden nicht anders und furchten Gott nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Denn sie legen ihre Hande an seine Friedsamen und entheiligen seinen Bund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Ihr Mund ist glatter denn Butter und haben doch Krieg im Sinn; ihre Worte sind gelinder denn 01 und sind doch blofte Schwerter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Wirf dein Anliegen aufden HERRN! Der wird dich versorgen und wird den Gerechten nicht ewiglich in Unruhe lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, 'Aber, Gott, du wirst sie hinunterstoften in die tiefe Grube. Die Blutgierigen und Falschen werden ihr Leben nicht zur Halfte bringen. Ich aber hoffe auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Ein gulden Kleinod Davids von der stummen Taube unter den Fremden, da ihn die Philister griffen zu Gath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Gott, sei mir gnadig, denn Menschen wollen mich versenken; taglich streiten sie und angsten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Meine Feinde versenken mich taglich; denn viele streiten wider mich stolziglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Wenn ich mich furchte, hoffe ich auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Ich will Gottes Wort ruhmen; auf Gott will ich hoffen und mich nicht furchten; was sollte mir Fleisch tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Taglich fechten sie meine Worte an; all ihre Gedanken sind, daß sie mir ubel tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Sie halten zuhauf und lauern und haben acht auf meine Fersen, wie sie meine Seeie erhaschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Was sie Boses tun, das ist schon vergeben. Gott, stofte solche Leute ohne alle Gnade hinunter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Zahle meine Flucht, fasse meine Tranen in deinen Sack! Ohne Zweifel, du zahlest sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Dann werden sich meine Feinde müssen zuruckkehren, wenn ich rufe; so werde ich inne, daß du mein Gott bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Ich will ruhmen Gottes Wort, ich will ruhmen des HERRN Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Auf Gott hoffe ich und furchte mich nicht; was konnen mir die Menschen tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ich habe dir, Gott, gelobet, daß ich dir danken will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, 'Denn du hast meine Seele vom Tode errettet, meine Füfte vom Gleiten, daß ich wandeln mag vor Gott im Licht der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Ein gulden Kleinod Davids, vorzusingen, daß er nicht umkame, da er vor Saul floh in die Hdhle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Sei mir gnadig, Gott, sei mir gnadig! Denn auf dich trauet meine Seele und unter dem Schatten deiner Flugel habe ich Zuflucht, bis daß das Unglück vorubergehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Ich rufe zu Gott, dem Allerhochsten, zu Gott, der meines Jammers ein Ende macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Er sendet vom Himmel und hilft mir von der Schmach meines Versenkers. Sela. Gott sendet seine Gute und Treue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Ich liege mit meiner Seele unter den Lowen. Die Menschenkindersind Flammen; ihre Zahne sind Spiefte und Pfeile und ihre Zungen scharfe Schwerter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Erhebe dich, Gott, uber den Himmel und deine Ehre uber alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Sie stellen meinem Gange Netze und drucken meine Seele nieder; sie graben vor mir eine Grube und fallen selbst drein. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mein Herz ist bereit, Gott, mein Herz ist bereit, daß ich singe und lobe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Wach auf, meine Ehre, wach auf, Psalter und Harfe! Fruhe will ich aufwachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'HERR, ich will dir danken unter den Volkern, ich will dir lobsingen unter den Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Denn deine Gute ist, soweit der Himmel ist, und deine Wahrheit, soweit die Wolken gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, 'Erhebe dich, Gott, uber den Himmel und deine Ehre uber alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Ein gulden Kleinod Davids, vorzusingen, daß er nicht umkame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Seid ihr denn stumm, daß ihr nicht reden wollt, was recht ist; und richten, was gleich ist, ihr Menschenkinder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Ja, mutwillig tut ihr unrecht im Lande und gehet stracks durch mit euren Handen zu freveln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Die Gottlosen sind verkehrt von Mutterleibe an; die Lugner irren von Mutterleib an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Ihr Wüten ist gleich wie das Wüten einer Schlange, wie eine taube Otter, die ihr Ohr zustopft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'daß sie nicht hore die Stimme des Zauberers, des Beschworers, der wohl beschworen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Gott, zerbrich ihre Zahne in ihrem Maul; zerstofte, HERR, die Backenzahne der jungen Lowen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Sie werden zergehen wie Wasser, das dahinfleuftt. Sie zielen mit ihren Pfeilen, aber dieselben zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Sie vergehen, wie eine Schnecke verschmachtet; wie eine unzeitige Geburt eines Weibes sehen sie die Sonne nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Ehe eure Dornen reif werden am Dornstrauche, wird sie ein Zorn so frisch wegreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Der Gerechte wird sich freuen, wenn er solche Rache siehet, und wird seine Füfte baden in des Gottlosen Blut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, 'daß die Leute werden sagen: Der Gerechte wird sein ja genieften; es ist ja noch Gott Richter auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Ein gulden Kleinod Davids, daß er nicht umkame, da Saul hinsandte und lieft sein Haus bewahren, daß er ihn totete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Errette mich, mein Gott, von meinen Feinden und schutze mich vor denen, so sich wider mich setzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Errette mich von den Ubeltatern und hilf mir von den Blutgierigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Denn siehe, HERR, sie lauern auf meine Seele; die Starken sammeln sich wider mich ohne meine Schuld und Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Sie laufen ohne meine Schuld und bereiten sich. Erwache und begegne mir und siehe drein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Du, HERR, Gott Zebaoth, Gott Israels, wache auf und suche heim alle Heiden; sei der keinem gnadig, die so verwegene Ubeltater sind! Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Des Abends laft sie wiederum auch heulen wie die Hunde und in der Stadt umherlaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Siehe, sie plaudern miteinander; Schwerter sind in ihren Lippen: Wer sollt es horen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Aber du, HERR, wirst ihrer lachen und aller Heiden spotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Vor ihrer Macht halt ich mich zu dir; denn Gott ist mein Schutz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Gott erzeigt mir reichlich seine Gute; Gott laftt mich meine Lust sehen an meinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Erwürge sie nicht, daß es mein Volk nicht vergesse; zerstreue sie aber mitdeiner Macht, HERR, unser Schild, und stofte sie hinunter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Ihre Lehre ist eitel Sünde, und verharren in ihrer Hoffart und predigen eitel Fluchen und Widersprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Vertilge sie ohne alle Gnade! Vertilge sie, daß sie nichts seien und inne werden, daß Gott Herrscher sei in Jakob, in aller Welt. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Des Abends laft sie wiederum auch heulen wie die Hunde und in der Stadt umherlaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Laft sie hin und herlaufen urn Speise und murren, wenn sie nicht satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ich aber will von deiner Macht singen und des Morgens ruhmen deine Gute; denn du bist mein Schutz und Zuflucht in meiner Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, 'Ich will dir, mein Hort, lobsingen; denn du, Gott, bist mein Schutz und mein gnadiger Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Ein gulden Kleinod Davids, vorzusingen, von einem güldenen Rosenspan zu lehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'da er gestritten hatte mit den Syrern zu Mesopotamien und mit den Syrern von Zoba; da Joab umkehrete und schlug der Edomiter im Salztal zwolftausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gott, der du uns verstoften und zerstreuet hast und zornig warest, troste uns wieder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Der du die Erde bewegt und zerrissen hast, heile ihre Bruche, die so zerschellet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Denn du hast deinem Volk ein Hartes erzeigt; du hast uns einen Trunk Weins gegeben, daß wir taumelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Du hast aber doch ein Zeichen gegeben denen, die dich furchten, welches sie aufwarfen und sie sicher machte. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Auf daß deine Lieben erledigt werden, so hilf nun mit deiner Rechten und erhore uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gott redet in seinem Heiligtum, des bin ich froh, und will teilen Sichem und abmessen das Tal Suchoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Gilead ist mein, mein ist Manasse, Ephraim ist die Macht meines Haupts, Juda ist mein Fürst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab ist mein Waschtopfen, meinen Schuh strecke ich uber Edom, Philistaa jauchzet zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Wer will mich führen in eine feste Stadt? Wer geleitet mich bis nach Edom?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Wirst du es nicht tun, Gott, der du uns verstoftest und zeuchst nicht aus, Gott, auf unser Heer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, 'Schaff uns Beistand in der Not; denn Menschenhilfe ist kein nutze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, 'Mit Gott wollen wir Taten tun. Er wird unsere Feinde untertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Ein Psalm Davids, vorzusingen auf einem Saitenspiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Hore, Gott, mein Geschrei und merke auf mein Gebet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Hienieden auf Erden rufe ich zu dir, wenn mein Herz in Angst ist, du wollest mich fuhren auf einen hohen Felsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Denn du bist meine Zuversicht, ein starker Turm vor meinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Ich will wohnen in deiner Hütte ewiglich und trauen unter deinen Fittichen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Denn du, Gott, horest meine Gelubde; du belohnest die wohl, die deinen Namen furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Du gibsteinem Konige langes Leben, dafi seine Jahre wahren immer fur und fur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'daß er immer sitzen bleibet vor Gott. Erzeige ihm Gute und Treue, die ihn behuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, 'So will ich deinem Namen lobsingen ewiglich, daß ich meine Gelubde bezahle taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Ein Psalm Davids fur Jeduthun, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Meine Seele ist stille zu Gott, der mir hilft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Denn er ist mein Hort, meine Hilfe, mein Schutz, daß mich kein Fall sturzen wird, wie graft er ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Wie lange stellet ihr alle einem nach, daß ihr ihn erwurget, als eine hangende Wand und zerrissene Mauer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Sie denken nur, wie sie ihn dampfen, fleiftigen sich der Luge, geben gute Worte, aber im Herzen fluchen sie. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Aber meine Seele harret nur auf Gott; denn er ist meine Hoffnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Er ist mein Hort, meine Hilfe und mein Schutz, daß ich nicht fallen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Bei Gott ist mein Heil, meine Ehre, der Fels meiner Starke; meine Zuversicht ist auf Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Hoffet auf ihn allezeit, lieben Leute, schuttet euer Herz vor ihm aus! Gott ist unsere Zuversicht. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Aber Menschen sind doch ja nichts, grofte Leute fehlen auch; sie wagen weniger denn nichts, soviel ihrer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Verlasset euch nicht auf Unrecht und Frevel; haltet euch nicht zu solchem, das nichts ist. Fallt euch Reichtum zu, so hanget das Herz nicht dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Gott hat ein Wort geredet, das habe ich etlichemal gehoret, daß Gott allein machtig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, 'Und du, HERR, bistgnadig und bezahlest einem jeglichen, wie er\'s verdienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein Psalm Davids, da er war in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Gott, du bist mein Gott; frühe wache ich zu dir. Es durstet meine Seele nach dir, mein Fleisch verlanget nach dir, in einem trockenen und durren Lande, da kein Wasser ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Daselbst sehe ich nach dir in deinem Heiligtum, wollte gerne schauen deine Macht und Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Denn deine Gute ist besser denn Leben. Meine Lippen preisen dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Daselbst wollte ich dich gerne loben mein Leben lang und meine Hande in deinem Namen aufheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Das ware meines Herzens Freude und Wonne, wenn ich dich mit frohlichem Munde loben sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Wenn ich mich zu Bette lege, so denke ich an dich; wenn ich erwache, so rede ich von dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Denn du bist mein Heifer, und unter dem Schatten deiner Flügel ruhme ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Meine Seele hanget dir an; deine rechte Hand erhalt mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Sie aberstehen nach meiner Seele, michzu uberfallen; sie werden unter die Erde hinunterfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Sie werden ins Schwert fallen und den Fuchsen zuteil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, 'Aber der Konig freuet sich in Gott. Wer bei ihm schworet, wird geruhmet werden; denn die Lügenmauler sollen verstopft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Hore, Gott, meine Stimme in meiner Klage; behute mein Leben vor dem grausamen Feinde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Verbirg mich vor der Sammlung der Bosen, vor dem Haufen der Ubeltater,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'welche ihre Zunge scharfen wie ein Schwert, die mit ihren giftigen Worten zielen wie mit Pfeilen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'daß sie heimlich schieften den Frommen; plotzlich schieften sie auf ihn ohne alle Scheu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Sie sind kuhn mit ihren bosen Anschlagen und sagen, wie sie Stricke legen wollen, und sprechen: Wer kann sie sehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Sie erdichten Schalkheit und halten\'s heimlich, sind verschlagen und haben geschwinde Ranke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Aber Gott wird sie plotzlich schieften, daß ihnen wehe tun wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Ihre eigene Zunge wird sie fallen, daß ihrer spotten wird, wer sie siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Und alle Menschen, die es sehen, werden sagen: Das hat Gott getan, und merken, daß es sein Werk sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, 'Die Gerechten werden sich des HERRN freuen und auf ihn trauen und alle frommen Herzen werden sich des rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Ein Psalm Davids, zum Lied vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Gott, man lobet dich in der Stille zu Zion und dir bezahlt man Gelubde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Du erhorest Gebet, darum kommt alles Fleisch zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Unsere Missetat drucket uns hart; du wollest unsere Sunde vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Wohl dem, den du erwahlest und zu dir lassest, daß er wohne in deinen Hofen! Der hat reichen Trost von deinem Hause, deinem heiligen Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Erhore uns nach derwunderlichen Gerechtigkeit, Gott, unser Heil, der du bist Zuversicht aller auf Erden und feme am Meer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'der die Berge fest setzt in seiner Kraft und gerustet ist mit Macht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'der du stillest das Brausen des Meers, das Brausen seiner Wellen, und das Toben der Volker,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'daß sich entsetzen, die an denselben Enden wohnen, vor deinen Zeichen. Du machst frohlich, was da webet, beide des Morgens und Abends.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du suchest das Land heim und wasserst es und machest es sehr reich. Gottes Brunnlein hat Wassers die Fulle. Du lassest ihr Getreide wohlgeraten, denn also bauest du das Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Du trankest seine Furchen und feuchtest sein Gepflugtes; mit Regen machst du es weich und segnest sein Gewachs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du kronest das Jahr mit deinem Gut und deine Fulitapfen triefen von Fett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Die Wohnungen in der Wuste sind auch fett, daß sie triefen, und die Füigel sind umher lustig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, 'Die Anger sind voll Schafe, und die Auen stehen dick mit Korn, daß man jauchzet und singet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Ein Psalmlied, vorzusingen. Jauchzet Gott, alle Lande!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Lobsinget zu Ehren seinem Namen; ruhmet ihn herrlich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sprechet zu Gott: Wie wunderlich sind deine Werke! Es wird deinen Feinden fehlen vor deiner grolien Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Alles Land bete dich an und lobsinge dir, lobsinge deinem Namen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kommt her und sehet an die Werke Gottes, der so wunderlich ist mit seinem Tun unter den Menschenkindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Er verwandelt das Meer ins Trockne, daß man zu Fuli uber das Wasser gehet; des freuen wir uns in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Er herrschet mit seiner Gewalt ewiglich; seine Augen schauen auf die Volker. Die Abtrunnigen werden sich nicht erhohen konnen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Lobet, ihr Volker, unsern Gott; lasset seinen Ruhm weit erschallen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'der unsere Seelen im Leben behalt und lalit unsere Fulie nicht gleiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Denn, Gott, du hast uns versucht und gelautert, wie das Silber gelautert wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Du hast uns lassen in den Turm werfen; du hast auf unsere Lenden eine Last gelegt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'du hast Menschen lassen uber unser Haupt fahren; wir sind in Feuer und Wasser kommen; aber du hast uns ausgefuhrt und erquicket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Darum will ich mit Brandopfern gehen in dein Haus und dir meine Gelubde bezahlen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'wie ich meine Lippen habe aufgetan und mein Mund geredet hat in meiner Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Ich will dir feiste Brandopfer tun von gebrannten Widdern; ich will opfern Rinder mit Bocken. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kommt her, horet zu, alle, die ihr Gott furchtet; ich will erzahlen, was er an meiner Seele getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Zu ihm rief ich mitmeinem Munde und preisete ihn mit meiner Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Wo ich Unrechts vorhatte in meinem Herzen, so wurde der HERR nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Darum erhoret mich Gott und merket auf mein Flehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Gelobt sei Gott, der mein Gebet nicht verwirft noch seine Gute von mir wendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Ein Psalmlied, vorzusingen auf Saitenspielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gott sei uns gnadig und segne uns; er lasse uns sein Antlitz leuchten, Sela,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'daß wir auf Erden erkennen seinen Weg, unter alien Heiden sein Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Es danken dir; Gott, die Volker; es danken dir alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Die Volker freuen sich und jauchzen, daß du die Leute recht richtest und regierest die Leute auf Erden. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Es danken dir, Gott, die Volker; es danken dir alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Das Land gibt sein Gewachs. Es segne uns Gott, unser Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, 'Es segne uns Gott, und alle Welt furchte ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Ein Psalmlied Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Es stehe Gott auf, daü seine Feinde zerstreuet werden, und die ihn hassen, vor ihm fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Vertreibe sie, wie der Rauch vertrieben wird; wie das Wachs zerschmilzt vom Feuer, so müssen umkommen die Gottlosen vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Die Gerechten aber müssen sich freuen und frohlich sein vor Gott und von Herzen sich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Singet Gott, lobsinget seinem Namen! Machet Bahn dem, der da sanft herfahrt! Er heifit HERR; und freuet euch vor ihm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'der ein Vater ist der Waisen und ein Richter der Witwen. Er ist Gott in seiner heiligen Wohnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'ein Gott, der den Einsamen das Haus voll Kinder gibt, der die Gefangenen ausfuhret zu rechter Zeit und lalit die Abtrunnigen bleiben in der Durre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Gott, da du vor deinem Volk herzogest, da du einhergingest in der Wuste, Sela,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'da bebete die Erde, und die Himmel troffen vor diesem Gott in Sinai, vor dem Gott, der Israels Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Nun aber gibst du, Gott, einen gnadigen Regen, und dein Erbe, das durre ist, erquickestdu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'daß deine Tiere drinnen wohnen konnen. Gott, du labest die Elenden mit deinen Gutern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Der HERR gibt das Wort mit grolien Scharen Evangelisten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Die Konige der Heerscharen sind untereinander Freunde, und die Hausehre teilet den Raub aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Wenn ihr zu Felde lieget, so glanzet es als der Tauben Flügel, die wie Silber und Gold schimmern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Wenn der Allmachtige hin und wieder unter ihnen Konige setzet, so wird es helle, wo es dunkel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Der Berg Gottes ist ein fruchtbarer Berg, ein groß und fruchtbar Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Was hüpfet ihr grotien Gebirge? Gott hat Lust, auf diesem Berge zu wohnen, und der HERR bleibt auch immer daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Der Wagen Gottes ist viel tausendmal tausend; der HERR ist unter ihnen im heiligen Sinai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du bist in die Hohe gefahren und hast das Gefangnis gefangen; du hast Gaben empfangen fur die Menschen, auch die Abtrunnigen, daß Gott der HERR dennoch daselbst bleiben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gelobet sei der HERR taglich! Gott legt uns eine Last auf, aber er hilft uns auch. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Wir haben einen Gott, der da hilft, und den HERRN Herrn, dervom Tode errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Aber Gott wird den Kopf seiner Feinde zerschmeiften samt ihrem Haarschadel, die da fortfahren in ihrer Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Doch spricht der HERR: Ich will unter den Fetten etliche holen; aus der Tiefe des Meers will ich etliche holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Darum wird dein Fuft in der Feinde Blut gefarbet werden, und deine Hunde werden es lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Man siehet, Gott, wie du einherzeuchst, wie du, mein Gott und Konig, einherzeuchst im Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Die Sanger gehen vorher, danach die Spielleute unter den Magden, die da pauken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Lobet Gott den HERRN in den Versammlungen fur den Brunn Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Da herrschet unter ihnen der kleine Benjamin, die Fursten Judas mit ihren Haufen, die Fursten Sebulons, die Fursten Naphthalis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Dein Gott hat dein Reich aufgerichtet. Dasselbe wollest du, Gott, uns starken; denn es ist dein Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Um deines Tempels willen zu Jerusalem werden dir die Konige Geschenke zuführen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Schilt das Tier im Rohr, die Rotte der Ochsen unter ihren Kalbern, die da zertreten um Geldes willen. Er zerstreuet die Volker, die da gerne kriegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Die Fursten aus Agypten werden kommen, Mohrenland wird seine Hande ausstrecken zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Ihr Konigreiche auf Erden, singet Gott, lobsinget dem HERRN, Sela,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'dem, der da fahrt im Himmel allenthalben von Anbeginn. Siehe, erwird seinem Donner Kraft geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Gebt Gott die Macht! Seine Herrlichkeit ist in Israel und seine Macht in den Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, 'Gott istwundersam in seinem Heiligtum. Er ist Gott Israels; er wird dem Volk Macht und Kraft geben. Gelobt sei Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Ein Psalm Davids von den Rosen, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Gott, hilf mir; denn das Wasser gehet mir bis an die Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Ich versinke in tiefem Schlamm, da kein Grund ist; ich bin im tiefen Wasser, und die Flut will mich ersaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Ich habe mich müde geschrieen, mein Hals ist heisch; das Gesicht vergehet mir, daß ich so lange muft harren auf meinen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Die mich ohne Ursache hassen, der ist mehr, denn ich Haare auf dem Haupt habe. Die mir unbillig feind sind und mich verderben, sind machtig. Ich muft bezahlen, das ich nicht geraubt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Gott, du weiftest meine Torheit, und meine Schulden sind dir nicht verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'La(S nicht zuschanden werden an mir, die dein harren, Herr, HERR Zebaoth! Laft nicht schamrot werden an mir, die dich suchen, Gott Israels!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Denn um deinetwillen trage ich Schmach, mein Angesicht ist voller Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Ich bin fremd worden meinen Brudern und unbekannt meiner Mutter Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Denn ich eifere mich schierzu Tod um dein Haus; und die Schmach derer, die dich schmahen, fallen auf mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Und ich weine und faste bitterlich; und man spottet mein dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Ich hab einen Sack angezogen; aber sie treiben das Gespott draus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Die im Tor sitzen, waschen von mir, und in den Zechen singet man von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ich aber bete, HERR, zu dirzur angenehmen Zeit. Gott, durch deine grofte Gute, erhore mich mit deiner treuen Hilfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Errette mich aus dem Kot, daß ich nicht versinke, daß ich errettet werde von meinen Hassern und aus dem tiefen Wasser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'daß mich die Wasserflut nicht ersaufe und die Tiefe nicht verschlinge und das Loch der Grube nicht uber mir zusammengehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Erhore mich, HERR, denn deine Gute ist trostlich; wende dich zu mir nach deiner groften Barmherzigkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'und verbirg dein Angesicht nicht vor deinem Knechte; denn mir ist angst; erhore mich eilend!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Mache dich zu meiner Seele und erlose sie; erlose mich um meiner Feinde willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du weiftest meine Schmach, Schande und Scham; meine Widersacher sind alle vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Die Schmach bricht mir mein Herz und kranket mich. Ich warte, ob es jemand jammerte, aber da ist niemand; und auf Troster, aber ich finde keine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Und sie geben mir Galle zu essen und Essig zu trinken in meinem groften Durst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Ihr Tisch rnüsse vor ihnen zum Strick werden, zur Vergeltung und zu einer Falle!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Ihre Augen müssen finster werden, daß sie nicht sehen; und ihre Lenden laft immer wanken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Geuft deine Ungnade auf sie, und dein grimmiger Zorn ergreife sie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Ihre Wohnung müsse wüste werden, und sei niemand, der in ihren Hütten wohne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Denn sie verfolgen, den du geschlagen hast, und rühmen, daß du die Deinen libel schlagest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'La(J sie in eine Sunde über die andere fallen, daß sie nicht kommen zu deiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Tilge sie aus dem Buch der Lebendigen, daß sie mit den Gerechten nicht angeschrieben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Ich aber bin elend, und mir istwehe. Gott, deine Hilfe schütze mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Ich will den Namen Gottes loben mit einem Liede und will ihn hoch ehren mit Dank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Daswird dem HERRN bad gefallen denn ein Farr, der Horner und Klauen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Die Elenden sehen und freuen sich; und die Gott suchen, denen wird das Herz leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Denn der HERR horet die Armen und verachtet seine Gefangenen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Es lobe ihn Himmel, Erde und Meer und alles, was sich drinnen reget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Denn Gott wird Zion helfen und die Stadte Judas bauen, daß man daselbst wohne und sie besitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, 'Und der Same seiner Knechte wird sie ererben, und die seinen Namen lieben, werden drinnen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Ein Psalm Davids, vorzusingen zum Gedachtnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Eile, Gott, mich zu erretten, HERR, mirzu helfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Es müssen sich schamen und zuschanden werden, die nach meiner Seele stehen; sie müssen zurückkehren und gehohnet werden, die mir übels wünschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'daß sie müssen wiederum zu Schanden werden, die da über mich schreien: Da, da!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Freuen und frohlich müssen sein an dir, die nach dir fragen; und die dein Heil lieben, immersagen: Hochgelobt sei Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, 'Ich aber bin elend und arm. Gott, eile zu mir, denn du bist mein Heifer und Erretter; mein Gott, verzeuch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'HERR, ich traue auf dich; laft mich nimmermehr zuschanden werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Errette mich durch deine Gerechtigkeit und hilf mir aus; neige deine Ohren zu mir und hilf mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sei mir ein starker Hort, dahin ich immerfliehen moge, derdu zugesagt hast, mirzu helfen; denn du bist mein Fels und meine Burg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mein Gott, hilf mir aus der Hand des Gottlosen, aus der Hand des Ungerechten und Tyrannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Denn du bist meine Zuversicht, Herr HERR, meine Hoffnung von meiner Jugend an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Auf dich habe ich mich verlassen von Mutterleibe an; du hast mich aus meiner Mutter Leibe gezogen. Mein Ruhm ist immer von dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Ich bin vor vielen wie ein Wunder; aber du bist meine starke Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Laft meinen Mund deines Ruhmes und deines Preises voll sein taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Verwirfmich nicht in meinem Alter; verlaft mich nicht, wenn ich schwach werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Denn meine Feinde reden wider mich, und die auf meine Seele halten, beraten sich miteinander');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'und sprechen: Gott hat ihn verlassen; jaget nach und ergreifet ihn, denn da ist kein Erretter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Gott, sei nicht feme von mir; mein Gott, eile mir zu helfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Schamen müssen sich und umkommen, die meiner Seele wider sind; mit Schande und Hohn müssen sie überschüttet werden, die mein Unglück suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ich aber will immer harren und will immer deines Ruhmes mehr machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mein Mund soil verkündigen deine Gerechtigkeit, taglich dein Heil, die ich nicht alle zahlen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Ich gehe einher in der Kraft des Herrn HERRN; ich preise deine Gerechtigkeit allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Gott, du hast mich von Jugend auf gelehret; darum verkündige ich deine Wunder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Auch verlaft mich nicht, Gott, im Alter, wenn ich grau werde, bis ich deinen Arm verkündige Kindeskindern und deine Kraft alien, die noch kommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Gott, deine Gerechtigkeit ist hoch, der du grofte Dinge tust. Gott, wer ist dir gleich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Denn du lassest mich erfahren viel und grofte Angst und machst mich wieder lebendig und holest mich wieder aus der Tiefe der Erde herauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Du machst mich sehr graft und trostest mich wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'So danke ich auch dir mit Psalterspiel fur deine Treue, mein Gott; ich lobsinge dir auf der Harfe, du Heiliger in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Meine Lippen und meine Seele, die du erloset hast, sind frohlich und lobsingen dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Auch dichtet meine Zunge taglich von deiner Gerechtigkeit. Denn schamen müssen sich und zuschanden werden, die mein Unglück suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Des Salomo. Gott, gib dein Gericht dem Konige und deine Gerechtigkeit des Konigs Sohne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'daß er dein Volk bringe zur Gerechtigkeit und deine Elenden rette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Laft die Berge den Frieden bringen unter das Volk und die Hügel die Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Er wird das elende Volk bei Recht erhalten und den Armen helfen und die Lasterer zerschmeiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Man wird dich furchten, solange die Sonne und der Mond wahret, von Kind zu Kindeskindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Er wird herabfahren, wie der Regen auf das Fell, wie die Tropfen, die das Land feuchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Zu seinen Zeiten wird bluhen der Gerechte und großer Friede, bis dafi der Mond nimmer sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Er wird herrschen von einem Meer bis ans andere und von dem Wasser an bis zur Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Vor ihm werden sich neigen die in der Wüste; und seine Feinde werden Staub lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Die Konige am Meer und in den Inseln werden Geschenke bringen; die Konige aus Reicharabien und Seba werden Gaben zufuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Alle Konige werden ihn anbeten, alle Heiden werden ihm dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Denn erwird den Armen erretten, der da schreiet, und den Elenden, der keinen FHelfer hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Erwird gnadig sein den Geringen und Armen, und den Seelen der Armen wird er helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Er wird ihre Seele aus dem Trug und Frevel erlosen, und ihr Blut wird teuer geachtet werden vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Er wird leben, und man wird ihm vom Gold aus Reicharabien geben. Und man wird immerdar vor ihm beten, taglich wird man ihn loben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Auf Erden, oben auf den Bergen, wird das Getreide dick stehen; seine Frucht wird beben wie Libanon und wird grünen in den Stadten wie Gras auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sein Name wird ewiglich bleiben; solange die Sonne wahret, wird sein Name auf die Nachkommen reichen, und werden durch denselben gesegnet sein; alle Heiden werden ihn preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Gelobet sei Gottder HERR, der Gott Israels, der alleine Wunder tut;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'und gelobet sei sein herrlicher Name ewiglich; und alle Lande mussen seiner Ehre voll werden! Amen, Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Ein Ende haben die Gebete Davids, des Sohns Isais.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Ein Psalm Assaphs. Israel hat dennoch Gott zum Trost, wer nur reines Herzens ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ich aber hatte schier gestrauchelt mit meinen Fußen, mein Tritt hatte beinahe geglitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Denn es verdroß mich auf die Ruhmredigen, da ich sah, daß es den Gottlosen so wohl ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Denn sie sind in keiner Fahr des Todes, sondern stehen fest wie ein Palast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Sie sind nicht in Ungluck wie andere Leute und werden nicht wie andere Menschen geplagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Darum muß ihr Trotzen kostlich Ding sein, und ihr Frevel muß wohlgetan heißen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Ihre Person brustet sich wie ein fetter Wanst; sie tun, was sie nur gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Sie vemichten alles und reden übel davon, und reden und lastern hoch her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Was sie reden, das muß vom Himmel herab geredet sein; was sie sagen, das muß gelten auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Darum fallt ihnen ihr Pobel zu und laufen ihnen zu mit Haufen wie Wasser');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'und sprechen: Was sollte Gott nach jenen fragen? Was sollte der Hochste ihrer achten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Siehe, das sind die Gottlosen; die sind gluckselig in der Welt und werden reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Soil\'s denn umsonst sein, daß mein Herz unstraflich lebt und ich meine Hande in Unschuld wasche');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'und bin geplagt taglich, und meine Strafe ist alle Morgen da?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Ich hatte auch schier so gesagt wie sie; aber siehe, damit hatte ich verdammt alle deine Kinder, die je gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Ich gedacht ihm nach, daß ich\'s begreifen mochte; aber es war mir zu schwer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'bis daß ich ging in das Heiligtum Gottes und merkte auf ihr Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Aberdu setzest sie aufs Schlupfrige und sturzestsie zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie werden sie so plotzlich zunichte! Sie gehen unter und nehmen ein Ende mit Schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie ein Traum, wenn einer erwachet, so machst du, HERR, ihr Bild in der Stadt verschmahet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Aber es tut mirwehe im Herzen und sticht mich in meinen Nieren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'daß ich muß ein Narr sein und nichts wissen und muß wie ein Tier sein vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Dennoch bleibe ich stets an dir; denn du haltst mich bei meiner rechten Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'du leitest mich nach deinem Rat und nimmst mich endlich mit Ehren an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wenn ich nur dich habe, so frage ich nichts nach Himmel und Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Wenn mirgleich Leib und Seele verschmachtet, so bist du doch, Gott, allezeit meines Herzens Trost und mein Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Denn, siehe, die von dirweichen, werden umkommen; du bringest urn alle, die wider dich huren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Aber das ist meine Freude, daß ich mich zu Gott halte und meine Zuversicht setze auf den Herm HERRN, daß ich verkundige all dein Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Eine Unterweisung Assaphs. Gott, warum verstoßest du uns so gar und bist so grimmig zornig über die Schafe deiner Weide?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Gedenk an deine Gemeine, die du vor alters erworben und dir zum Erbteil erloset hast, an den Berg Zion, da du auf wohnest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Tritt auf sie mit Fußen und stoße sie gar zu Boden. Der Feind hat alles verderbet im Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Deine Widerwartigen brullen in deinen Hausern und setzen ihre Gotzen drein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Man siehet die Axte oben her blicken, wie man in einen Wald hauet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'und zerhauen alle seine Tafelwerke mit Beil und Barten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Sie verbrennen dein Heiligtum, sie entweihen die Wohnung deines Namens zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Sie sprechen in ihrem Herzen: Lal Jt uns sie plundern! Sie verbrennen alle Hauser Gottes im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Unsere Zeichen sehen wir nicht, und kein Prophet predigt mehr, und kein Lehrer lehret uns mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Ach, Gott, wie lange soil der Widerwartige schmahen und der Feind deinen Namen so gar verlastern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Warum wendest du deine Hand ab und deine Rechte von deinem Schol L so gar?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Aber Gott ist mein Konig von alters her, der alle Hilfe tut, so auf Erden geschieht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du zertrennest das Meer durch deine Kraft und zerbrichst die Kopfe der Drachen im Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Du zerschlagst die Kopfe der Walfische und gibst sie zur Speise dem Volk in der Einode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du lassest quellen Brunnen und Bache; du lassest versiegen starke Strome.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tag und Nacht ist dein; du machest, dafi beide Sonn und Gestirn ihren gewissen Lauf haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du setzest einem jeglichen Lande seine Grenze; Sommer und Winter machest du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'So gedenke doch des, daß der Feind den HERRN schmahet, und ein toricht Volk lasted deinen Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Du wollest nicht dem Tier geben die Seele deiner Tudeltaube und deiner elenden Tiere nicht so garvergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Gedenk an den Bund; denn das Land ist allenthalben jammerlich verheeret, und die Hauser sind zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Laß den Geringen nicht mit Schanden davongehen, denn die Armen und Elenden rühmen deinen Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Mache dich auf, Gott, und führe aus deine Sache; gedenk an die Schmach, die dir taglich von den Toren widerfahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Vergili nicht des Geschreies deiner Feinde; das Toben deiner Widerwartigen wird je langer je grolier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Ein Psalm und Lied Assaphs, daß er nicht umkame, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Wir danken dir, Gott, wir danken dir und verkündigen deine Wunder, daß dein Name so nahe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Denn zu seiner Zeit so werde ich recht richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Das Land zittert und alle, die drinnen wohnen; aber ich halte seine Saulen test. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ich sprach zu den Ruhmredigen: Rühmet nicht so! und zu den Gottlosen: Pochet nicht auf Gewalt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Pochet nicht so hoch auf eure Gewalt, redet nicht halsstarrig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'es habe keine Not, weder von Aufgang noch von Niedergang, noch von dem Gebirge in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Denn Gott ist Richter, der diesen niedriget und jenen erhohet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Denn der HERR hat einen Becher in der Hand und mit starkem Wein voll eingeschenkt und schenkt aus demselben; aber die Gottlosen müssen alle trinken und die Hefen aussaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ich aber will verkundigen ewiglich und lobsingen dem Gott Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, 'Und will alle Gewalt der Gottlosen zerbrechen, daß die Gewalt des Gerechten erhohet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Ein Psalmlied Assaphs, auf Saitenspiel vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Gott ist in Juda bekannt, in Israel ist sein Name herrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Zu Salem ist sein Gezelt und seine Wohnung zu Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Daselbst zerbricht er die Pfeile des Bogens, Schild, Schwert und Streit. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Du bist herrlicher und machtiger denn die Raubeberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Die Stolzen müssen beraubet werden und entschlafen, und alle Krieger müssen die Hande lassen sinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Von deinem Schelten, Gott Jakobs, sinkt in Schlaf beide Roß und Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du bist erschrecklich. Wer kann vor dir stehen, wenn du zümest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Wenn du das Urteil lassest horen vom Himmel, so erschrickt das Erdreich und wird still,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'wenn Gott sich aufmacht, zu richten, dafi er helfe alien Elenden auf Erden. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Wenn Menschen wider dich wüten, so legest du Ehre ein; und wenn sie noch mehr wüten, bist du auch noch gerüstet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Gelobet und haltet dem HERRN eurem Gott, alle, die ihr urn ihn her seid; bringet Geschenke dem Schrecklichen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, 'der den Fürsten den Mut nimmt und schrecklich ist unter den Konigen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Ein Psalm Assaphs fur Jeduthun, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Ich schreie mit meiner Stimme zu Gott; zu Gott schreie ich, und er erhoret mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'In der Zeit meiner Not suche ich den HERRN; meine Hand ist des Nachts ausgereckt und lafit nicht ab; denn meine Seele will sich nicht trosten lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Wenn ich betrübt bin, so denke ich an Gott; wenn mein Herz in Angsten ist; so rede ich. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Meine Augen haltstdu, daß sie wachen; ich bin so ohnmachtig, daß ich nicht reden kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ich denke der alten Zeit, der vorigen Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Ich denke des Nachts an mein Saitenspiel und rede mit meinem Herzen; mein Geist muli forschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Wird denn der HERR ewiglich verstolien und keine Gnade mehr erzeigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Ist\'s denn ganz und gar aus mit seiner Gute? und hat die Verheitiung ein Ende?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hat denn Gott vergessen, gnadig zu sein, und seine Barmherzigkeit vor Zorn verschlossen? Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Aber doch sprach ich: Ich muli das leiden; die rechte Hand des Hochsten kann alles andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Darum gedenk ich an die Taten des HERRN; ja, ich gedenke an deine vorigen Wunder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'und rede von alien deinen Werken und sage von deinem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Gott dein Weg istheilig. Wo ist so ein machtiger Gott, als du, Gott, hist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du hist der Gott, der Wunder tut; du hast deine Macht beweiset unter den Volkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Du hast dein Volk erloset gewaltiglich, die Kinder Jakobs und Josephs. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Die Wasser sahen dich, Gott; die Wasser sahen dich und angsteten sich, und die Tiefen tobeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Die dicken Wolken gossen Wasser; die Wolken donnerten, und die Strahlen führen daher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Es donnerte im Himmel; deine Blitze leuchteten auf dem Erdboden; das Erdreich regte sich und bebete davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Dein Weg war im Meer und dein Pfad in grofien Wassern, und man spurete doch deinen Fufi nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, 'Du fuhretest dein Volk wie eine Herde Schafe durch Mose und Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Eine Unterweisung Assaphs. Hore, mein Volk, mein Gesetz; neiget eure Ohren zu der Rede meines Mundes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Ich will meinen Mund auftun zu Spruchen und alte Geschichte aussprechen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'die wir gehoret haben und wissen und unsere Vater uns erzahlet haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'daß wir\'s nicht verhalten sollen ihren Kindern, die hernach kommen, und verkundigen den Ruhm des HERRN und seine Macht und Wunder, die er qetan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Er richtete ein Zeugnis auf in Jakob und gab ein Gesetz in Israel, das er unsern Vatern gebot, zu lehren ihre Kinder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'auf daß die Nachkommen lerneten und die Kinder, die noch sollten geboren werden, wenn sie aufkamen, daß sie es auch ihren Kindern verkundigten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'daß sie setzten auf Gott ihre Hoffnung und nicht vergalien der Taten Gottes und seine Gebote hielten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'und nicht wurden wie ihre Vater, eine abtrunnige und ungehorsame Art, welchen ihr Herz nicht test war, und ihr Geist nicht treulich hielt an Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'wie die Kinder Ephraim, so geharnischt den Bogen führeten, abfielen zur Zeit des Streits.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Sie hielten den Bund Gottes nicht und wollten nicht in seinem Gesetz wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'und vergalien seiner Taten und seiner Wunder, die er ihnen erzeiget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Vor ihren Vatern tat er Wunder in Agyptenland, im Felde Zoan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Er zerteilete das Meer und lieli sie durchhin gehen; und stellete das Wasser wie eine Mauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Er leitete sie des Tages miteiner Wolke und des Nachts mit einem hellen Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Er rili die Felsen in der Wuste und trankete sie mit Wasser die Fulle;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'und lieli Bache aus dem Felsen flielien, daß sie hinabflossen wie Wasserstrome.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Noch sündigten sie weiter wider ihn und erzurneten den hochsten in der Wuste;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'und versuchten Gott in ihrem Herzen, daß sie Speise forderten fur ihre Seelen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'und redeten wider Gott und sprachen: Ja, Gott sollte wohl konnen einen Tisch bereiten in der Wuste!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Siehe, er hat wohl den Felsen geschlagen, daß Wasser flossen und Bache sich ergossen; aber wie kann er Brot geben und seinem Volk Fleisch verschaffen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Da nun das der HERR horete, entbrannte er, und Feuer ging an in Jakob und Zorn kam uber Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'daß sie nicht glaubeten an Gott und hoffeten nicht auf seine Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Und er gebot den Wolken droben und tat auf die Türen des Himmels;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'und lieli das Man auf sie regnen, zu essen, und gab ihnen Himmelbrot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Sie alien Enqelbrot; ersandte ihnen Speise die Fulle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Er lieli weben den Ostwind unter dem Himmel und erregte durch seine Starke den Sudwind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Und lieli Fleisch auf sie regnen wie Staub und Vogel wie Sand am Meer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'und lieli sie fallen unter ihr Lager allenthalben, da siewohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Da alien sie und wurden allzu satt; er lieli sie ihre Lust bulien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Da sie nun ihre Lust gebuliet hatten und sie noch davon alien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'da kam der Zorn Gottes uber sie und erwürgete die Vornehmsten unter ihnen und schlug danieder die Besten in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Aber fiber das alles sündigten sie noch mehr und glaubten nicht an seine Wunder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Darum lieli er sie dahinsterben, daß sie nichts erlangeten, und muliten ihr Leben lang geplaget sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Wenn er sie erwürgete, suchten sie ihn und kehreten sich fruhe zu Gott');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'und gedachten, daß Gott ihr Hort ist und Gott der Hochste ihr Erloser ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'und heuchelten ihm mit ihrem Munde und logen ihm mit ihrer Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Aber ihr Herz war nicht test an ihm und hielten nicht treulich an seinem Bunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Er aber war barmherzig und vergab die Missetat und vertilgte sie nicht; und wendete oft seinen Zorn ab und liefi nicht seinen ganzen Zorn gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Denn ergedachte, dafi sie Fleisch sind, ein Wind, der dahinfahret und nicht wiederkommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Sie erzurneten ihn gar oft in der Wuste und entrusteten ihn in der Einode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Sie versuchten Gott immer wieder und meisterten den Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Sie dachten nicht an seine Hand des Tages, da er sie erlosete von den Feinden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'wie er denn seine Zeichen in Agypten getan hatte und seine Wunder im Lande Zoan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'da er ihr Wasser in Blut wandelte, daß sie ihre Bache nicht trinken konnten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'da er Ungeziefer unter sie schickte, die sie fraßen, und Kroten, die sie verderbeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'und gab ihr Gewachs den Raupen und ihre Saat den Heuschrecken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'da er ihre Weinstocke mit Hagel schlug und ihre Maulbeerbaume mit Schlotien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'da er ihr Vieh schlug mit Hagel und ihre Herden mit Strahlen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'da er bose Engel unter sie sandte in seinem grimmigen Zorn und lieti sie toben und wuten und Leid tun;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'da er seinen Zorn lieti fortgehen und ihre Seelen vor dem Tode nicht verschonete und lieli ihr Vieh an der Pestilenz sterben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'da er alle Erstgeburt in Agypten schlug, die ersten Erben in den Hütten Hams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Und lieli sein Volk ausziehen wie Schafe und fuhrete sie wie eine Herde in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Und er leitete sie sicher, dafi sie sich nicht furchteten; aber ihre Feinde bedeckte das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Und brachte sie in seine heilige Grenze, zu diesem Berge, den seine Rechte erworben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Und vor ihnen her die Volker und liefi ihnen das Erbe austeilen und lieli in jener Hutten die Stamme Israels wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Aber sie versuchten und erzurneten Gott, den Hochsten, und hielten seine Zeugnisse nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'und fielen zurück und verachteten alles, wie ihre Vater, und hielten nicht, gleichwie ein loser Bogen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'und erzurneten ihn mit ihren Hohen und reizeten ihn mit ihren Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Und da das Gott horete, entbrannte er und verwarf Israel sehr,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'daß er Seine Wohnung zu Silo ließ fahren, die Hutte, da er unter Menschen wohnete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'und gab ihre Macht ins Gefangnis und ihre Herrlichkeit in die Hand des Feindes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'und ubergab sein Volk ins Schwert und entbrannte uber sein Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ihre junge Mannschaft fra IS das Feuer, und ihre Jungfrauen muliten ungefreiet bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Ihre Priester fielen durchs Schwert, und waren keine Witwen, die da weinen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Und der HERR erwachte wie ein Schlafender, wie ein Starker jauchzet, der vom Wein kommt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'und schlug seine Feinde von hinten und hangete ihnen eine ewige Schande an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Und verwarf die Hutte Josephs und erwahlte nicht den Stamm Ephraim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'sondern erwahlete den Stamm Juda, den Berg Zion, welchen er liebte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Und bauete sein Heiligtum hoch, wie ein Land, das ewiglich fest stehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Und erwahlete seinen Knecht David und nahm ihn von den Schafstallen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'von den saugenden Schafen holte er ihn, daß er sein Volk Jakob weiden sollte und sein Erbe Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Und er weidete sie auch mit aller Treue und regierte sie mit allem Fleiß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Ein Psalm Assaphs. HERR, es sind Heiden in dein Erbe gefallen, die haben deinen heiligen Tempel verunreiniget und aus Jerusalem Steinhaufen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Sie haben die Leichname deiner Knechte den Vogeln unter dem Himmel zu fressen gegeben und das Fleisch deiner Heiligen den Tieren im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Sie haben Blut vergossen urn Jerusalem her wie Wasser; und war niemand, der begrub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Wir sind unsern Nachbarn eine Schmach worden, ein Spott und Hohn denen, die urn uns sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'HERR, wie lange willst du so gar zurnen und deinen Eifer wie Feuer brennen lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Schutte deinen Grimm auf die Heiden, die dich nicht kennen, und auf die Konigreiche, die deinen Namen nicht anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Denn sie haben Jakob aufgefressen und seine Hauser verwustet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Gedenke nicht unserer vorigen Missetat; erbarm dich unser bald, denn wir sind fast dünne worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Hilf du uns, Gott, unser Heifer, urn deines Namens Ehre willen; errette uns und vergib uns unsere Sunde urn deines Namens willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Warum lassest du die Heiden sagen: Wo ist nun ihr Gott? Laß, unter den Heiden vor unsern Augen kund werden die Rache des Bluts deiner Knechte, das vergossen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Lafi vor dich kommen das Seufzen der Gefangenen; nach deinem grolien Arm behalte die Kinder des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Und vergilt unsern Nachbarn siebenfaltig in ihren Busen ihre Schmach, damit sie dich, HERR, geschmahet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Wir aber, dein Volk und Schafe deiner Weide, danken direwiglich und verkundigen deinen Ruhm fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Ein Psalm Assaphs von den Spanrosen, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Du Hirte Israels, hore, der du Joseph hütest wie der Schafe; erscheine, der du sitzest liber Cherubim!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Erwecke deine Gewalt, der du vor Ephraim, Benjamin und Manasse bist, und komm uns zu Hilfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Gott, troste uns und lali leuchten dein Antlitz, so genesen wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'HERR, Gott Zebaoth, wie lange willst du zlirnen uber dem Gebet deines Volks?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du speisest sie mit Tranenbrot und trankest sie mit groliem Mali voll Tranen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Du setzest uns unsern Nachbarn zum Zank, und unsere Feinde spotten unser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Gott Zebaoth, troste uns! Lali leuchten dein Antlitz, so genesen wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Du hast einen Weinstock aus Agypten geholet und hast vertrieben die Heiden und denselben gepflanzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Du hast vor ihm die Bahn gemacht und hast ihn lassen einwurzeln, daß erdas Land erfullet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Berge sind mit seinem Schatten bedeckt und mit seinen Reben die Zedern Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Du hast sein Gewachs ausgebreitet bis ans Meer und seine Zweige bis ans Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Warum hast du denn seinen Zaun zerbrochen, daß ihn zerreiliet alles, das vorubergehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Es haben ihn zerwühlet die wilden Saue, und die wilden Tiere haben ihn verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Gott Zebaoth, wende dich doch, schaue vom Himmel und siehe an und suche heim diesen Weinstock');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'und halt ihn im Bau, den deine Rechte gepflanzet hat, und den du dir festiglich erwahlet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Siehe drein und schilt, daß des Brennens und Reiliens ein Ende werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Deine Hand schutze das Volk deiner Rechten und die Leute, die du dir festiglich erwahlet hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'so wollen wir nichtvon dirweichen. Lali uns leben, so wollen wir deinen Namen anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, 'HERR, Gott Zebaoth, troste uns! Lali dein Antlitz leuchten, so genesen wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Auf der Githith vorzusingen: Assaph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Singet frdhlich Gott, der unsere Starke ist; jauchzet dem Gott Jakobs!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Nehmet die Psalmen und gebet her die Pauken, liebliche Harfen mit Psalter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Blaset im Neumonden die Posaunen, in unserm Fest der Laubruste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Denn solches isteine Weise in Israel und ein Recht des Gottes Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Solches hat er zum Zeugnis gesetzt unter Joseph, da sie aus Agyptenland zogen, und fremde Sprache gehoret hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'da ich ihre Schulter von der Last entlediget hatte, und ihre Hande der Topfe los wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Da du mich in der Not anriefest, half ich dir aus; und erhorete dich, da dich das Wetter überfiel, und versuchte dich am Haderwasser. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Hore, mein Volk, ich will unter dir zeugen; Israel, du sollst mich horen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'daß unter dir kein anderer Gott sei, und du keinen fremden Gott anbetest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ich bin der HERR, dein Gott, der dich aus Agyptenland gefuhret hat. Tue deinen Mund weit auf, lali mich ihn fullen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Aber mein Volk gehorcht nicht meiner Stimme, und Israel will mein nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'So hab ich sie gelassen in ihres Herzens Dünkel, daß sie wandeln nach ihrem Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Wollte mein Volk mirgehorsam sein und Israel auf meinem Wege gehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'so wollte ich ihre Feinde bald dampfen und meine Hand liber ihre Widerwartigen wenden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'und die den HERRN hassen, müliten an ihm fehlen; ihre Zeit aber würde ewiglich wahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, 'Und ich würde sie mit dem besten Weizen speisen und mit Honig aus dem Felsen sattigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Ein Psalm Assaphs. Gott stehet in der Gemeine Gottes und ist Richter unter den Gottern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Wie lange wollt ihr unrecht richten und die Person der Gottlosen vorziehen? Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Schaffet Recht dem Armen und dem Waisen und helfet dem Elenden und Durftigen zum Recht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'den Geringen und Armen und erloset ihn aus der Gottlosen Gewalt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Aber sie lassen ihnen nicht sagen und achten\'s nicht; sie gehen immer hin im Finstern; darum müssen alle Grundfesten des Landes fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Ich habe wohl gesagt: Ihr seid Gotter und allzumal Kinder des Hochsten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'aber ihrwerdet sterben wie Menschen und wie ein Tyrann zugrunde gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Gott, mache dich auf und richte das Land; denn du bist Erbherr fiber alle Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein Psalmlied Assaphs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Gott, schweige doch nicht also und sei doch nicht so stille; Gott, halte doch nicht so inne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Denn siehe, deine Feinde toben, und die dich hassen, richten den Kopf auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Sie machen listige Anschlage wider dein Volk und ratschlagen wider deine Verborgenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Wohl her! sprechen sie, ladt uns sie ausrotten, dad sie kein Volk seien, daß des Namens Israel nicht mehr gedacht werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Denn sie haben sich miteinander vereiniget und einen Bund wider dich gemacht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'die Hütten der Edomiter und Ismaeliter, der Moabiter und Hagariter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'der Gebaliter, Ammoniter und Amalekiter, die Phüister, samt denen zu Tyrus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Assur hat sich auch zu ihnen geschlagen und helfen den Kindern Lot. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Tu ihnen wie den Midianitern, wie Sissera, wie Jabin am Bach Kison,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'die vertilget wurden bei Endor und wurden zu Kot auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Mache ihre Fürsten wie Oreb und Seeb, alle ihre Obersten wie Sebah und Zalmuna,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'die da sagen: Wirwollen die Hauser Gottes einnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Gott, mache sie wie einen Wirbel, wie Stoppeln vor dem Winde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Wie ein Feuer den Wald verbrennet, und wie eine Flamme, die Berge anzundet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'also verfolge sie mit deinem Wetter und erschrecke sie mit deinem Ungewitter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Mache ihr Angesicht voll Schande, daß sie nach deinem Namen fragen müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Schamen müssen sie sich und erschrecken immer mehr und mehr und zuschanden werden und umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, 'So werden sie erkennen, dad du mit deinem Namen heidest HERR alleine und der Hochste in aller Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Ein Psalm der Kinder Korah, auf der Githith vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Wie lieblich sind deine Wohnungen, HERR Zebaoth!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Meine Seele verlanget und sehnet sich nach den Vorhofen des HERRN; mein Leib und Seele freuen sich in dem lebendigen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Denn der Vogel hat ein Haus funden und die Schwalbe ihr Nest, da sie Junge hecken, namlich deine Altare, HERR Zebaoth, mein Konig und mein Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Wohl denen, die in deinem Hause wohnen; die loben dich immerdar. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Wohl den Menschen, die dich fur ihre Starke halten und von Herzen dir nach wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'die durch das Jammertal gehen und machen daselbst Brunnen. Und die Lehrer werden mit viel Segen geschmuckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Sie erhalten einen Sieg nach dem andern, daß man sehen muli, der rechte Gott sei zu Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'HERR, Gott Zebaoth, hore mein Gebet; vernimm es, Gott Jakobs! Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Gott, unser Schild, schaue doch; siehe an das Reich deines Gesalbten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Denn ein Tag in deinen Vorhofen ist besser denn sonst tausend. Ich will lieber der Tur hüten in meines Gottes Hause, denn lange wohnen in der Gottlosen Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Denn Gott der HERR ist Sonne und Schild, der HERRgibt Gnade und Ehre; erwird kein Gutes mangeln lassen den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, 'HERR Zebaoth, wohl dem Menschen, der sich auf dich verladt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Ein Psalm der Kinder Korah, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'HERR, der du bist vormals gnadig gewesen deinem Lande und hast die Gefangenen Jakobs erloset;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'der du die Missetat vormals vergeben hast deinem Volk und alle ihre Sünde bedecket, Sela;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'der du vormals hast all deinen Zorn aufgehoben und dich gewendet von dem Grimm deines Zorns;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'troste uns, Gott, unser Heiland, und lad ab von deiner Ungnade uber uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Willst du denn ewiglich uber uns zurnen und deinen Zorn gehen lassen immer fur und fur?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Willst du uns denn nicht wieder erquicken, dad sich dein Volk uber dir freuen moge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'HERR, erzeige uns deine Gnade und hilf uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ach, dad ich horen sollte, das Gott der HERR redet, dad er Frieden zusagte seinem Volk und seinen Heiligen, auf dad sie nicht auf eine Torheit geraten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Doch istja seine Hilfe nahe denen, die ihn furchten, dad in unserm Lande Ehre wohne;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'dad Gute und Treue einander begegnen, Gerechtigkeit und Friede sich kussen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'dad Treue auf der Erde wachse, und Gerechtigkeit vom Himmel schaue;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'dad uns auch der HERR Gutes tue, damit unser Land sein Gewachs gebe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, 'dad Gerechtigkeit dennoch vor ihm bleibe und im Schwange gehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Ein Gebet Davids. HERR, neige deine Ohren und erhore mich; denn ich bin elend und arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Bewahre meine Seele; denn ich bin heilig. Hilf du, mein Gott, deinem Knechte, der sich verladt auf dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'HERR, sei mir gnadig; denn ich rufe taglich zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Erfreue die Seele deines Knechts; denn nach dir, HERR, verlanget mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Denn du, HERR, bist gut und gnadig, von großer Gute alien, die dich anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Vernimm, HERR, mein Gebet und merke auf die Stimme meines Flehens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'In der Not rufe ich dich an; du wollest mich erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'HERR, es ist dir keiner gleich unter den Gottern und ist niemand, der tun kann wie du.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle Heiden, die du gemacht hast, werden kommen und vor dir anbeten, HERR, und deinen Namen ehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'daß du so graft bist und Wunder tust und alleine Gott bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Weise mir, HERR, deinen Weg, daß ich wandele in deiner Wahrheit; erhalte mein Herz bei dem Einigen, daß ich deinen Namen furchte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Ich danke dir, HERR, mein Gott, von ganzem Herzen und ehre deinen Namen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Denn deine Gute ist graft uber mich, und hast meine Seele errettet aus der tiefen Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Gott, es setzen sich die Stolzen wider mich, und der Haute der Tyrannen stehet mir nach meiner Seele und haben dich nichtvor Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Du aber, HERR Gott, bist barmherzig und gnadig, geduldig und von großer Gute und Treue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wende dich zu mir, sei mir gnadig; starke deinen Knecht mit deiner Macht und hilt dem Sohn deiner Magd!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tu ein Zeichen an mir, daß mifs wohlgehe, daß es sehen, die mich hassen, und sich schamen müssen, daß du mir beistehest, HERR, und trostest mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Ein Psalmlied der Kinder Korah. Sie ist test gegrundet auf den heiligen Bergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Der HERR liebet die Tore Zions uber alle Wohnungen Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Herrliche Dinge werden in dir geprediget, du Stadt Gottes. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Ich will predigen lassen Rahab und Babel, daß sie mich kennen soilen. Siehe, die Philister und Tyrer samt den Mohren werden daselbst geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Man wird zu Zion sagen, daß allerlei Leute drinnen geboren werden, und daß er, der Hochste, sie baue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Der HERR wird predigen lassen in allerlei Sprachen, daß deren etliche auch daselbst geboren werden. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Und die Sanger, wie am Reigen, werden alle in dir singen, eins urns andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein Psalmlied der Kinder Korah, vorzusingen, von der Schwachheit der Elenden. Eine Unterweisung Hemans, des Esrahiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'HERR Gott, mein Heiland, ich schreie Tag und Nachtvordir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Laft mein Gebet vor dich kommen; neige deine Ohren zu meinem Geschrei!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Denn meine Seele istvoll Jammers, und mein Leben ist nahe bei der Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Ich bin geachtet gleich denen, die zur Holle fahren; ich bin wie ein Mann, der keine Hilfe hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Ich liege unter den Toten verlassen, wie die Erschlagenen, die im Grabe liegen, deren du nicht mehr gedenkest, und sie von deiner Hand abgesondert sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du hast mich in die Grube hinuntergelegt, in die Finsternis und in die Tiefe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Dein Grimm drucket mich, und drangest mich mit alien deinen Fluten. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Meine Freunde hast du feme von mir getan; du hast mich ihnen zum Greuel gemacht. Ich liege gefangen und kann nicht auskommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Meine Gestalt ist jammerlich vor Elend. HERR, ich rufe dich an taglich; ich breite meine Hande aus zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Wirst du denn unter den Toten Wunder tun, Oder werden die Verstorbenen aufstehen und dir danken? Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Wird man in Grabern erzahlen deine Gute und deine Treue im Verderben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Mogen denn deine Wunder in Finsternis erkannt werden, Oder deine Gerechtigkeit im Lande, da man nichts gedenket?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Aber ich schreie zu dir, HERR, und mein Gebet kommt fruhe vor dich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Warum verstoftest du, HERR, meine Seele und verbirgest dein Antlitz vor mir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Ich bin elend und ohnmachtig, daß ich so verstoften bin, und leide dein Schrecken, daß ich schier verzage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Dein Grimm gehet uber mich, dein Schrecken drucket mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Sie umgeben mich taglich wie Wasser und umringen mich miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, 'Du machest, daß meine Freunde und Nachsten und meine Verwandten sich feme von mir tun urn solches Elendes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Eine Unterweisung Ethans, des Esrahiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Ich will singen von der Gnade des HERRN ewiglich und seine Wahrheit verkundigen mit meinem Munde fur und fur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'und sage also: Daft eine ewige Gnade wird aufgehen, und du wirst deine Wahrheit treulich halten im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Ich habe einen Bund gemacht mit meinem Auserwahlten, ich habe David, meinem Knechte, geschworen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Ich will dir ewiglich Samen verschaffen und deinen Stuhl bauen fur und fur. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Und die Himmel werden, HERR, deine Wunder preisen und deine Wahrheit in der Gemeine der Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Denn wer mag in den Wolken dem HERRN gleich gelten und gleich sein unter den Kindern der Gotter dem HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Gott istfast machtig in der Sammlung der Heiligen und wunderbarlich uber alle, die um ihn sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'HERR, Gott, Zebaoth, wer istwie du, ein machtiger Gott? Und deine Wahrheit ist um dich her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du herrschest uber das ungestume Meer; du stillest seine Wellen, wenn sie sich erheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Du schlagst Rahab zu Tode; du zerstreuest deine Feinde mit deinem starken Arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Himmel und Erde ist dein; du hastgegrundet den Erdboden, und was drinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Mitternacht und Mittag hast du geschaffen; Thabor und Hermon jauchzen in deinem Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Du hast einen gewaltigen Arm; stark ist deine Hand und hoch ist deine Rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Gerechtigkeit und Gericht ist deines Stuhls Festung; Gnade und Wahrheit sind vor deinem Angesichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Wohl dem Volk, das jauchzen kann! HERR, sie werden im Licht deines Antlitzes wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Sie werden uber deinem Namen taglich frohlich sein und in deiner Gerechtigkeit herrlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Denn du bistder Ruhm ihrer Starke und durch deine Gnade wirst du unser Horn erhohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Denn der HERR ist unser Schild, und der Heilige in Israel ist unser Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Dazumal redetest du im Gesichte zu deinem Heiligen und sprachest: Ich habe einen Held erwecket, der helfen soli; ich habe erhohet einen Auserwahlten aus dem Volk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'ich habe funden meinen Knecht David, ich habe ihn gesalbet mit meinem heiligen Ole.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Meine Hand soil ihn erhalten, und mein Arm soil ihn starken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Die Feinde sollen ihn nicht uberwaltigen, und die Ungerechten sollen ihn nicht dampfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'sondern ich will seine Widersacher schlagen vor ihm her, und die ihn hassen, will ich plagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Aber meine Wahrheit und Gnade soil bei ihm sein, und sein Horn soli in meinem Namen erhaben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Ich will seine Hand ins Meer stellen und seine Rechte in die Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Erwird mich nennen also: Du bist mein Vater, mein Gott und Hort, der mir hilft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Und ich will ihn zum ersten Sohn machen, allerhochst unter den Konigen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Ich will ihm ewiglich behalten meine Gnade, und mein Bund soil ihm fest bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ich will ihm ewiglich Samen geben und seinen Stuhl, solange der Himmel wahret, erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Wo aber seine Kinder mein Gesetz verlassen und in meinen Rechten nicht wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'so sie meine Ordnungen entheiligen und meine Gebote nicht halten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'will ich ihre Sünde mit der Rute heimsuchen und ihre Missetat mit Plagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Aber meine Gnade will ich nicht von ihm wenden und meine Wahrheit nicht lassen fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Ich will meinen Bund nicht entheiligen und nicht andern, was aus meinem Munde gegangen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Ich habe einst geschworen bei meiner Heiligkeit: Ich will David nicht lugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Sein Same soil ewig sein und sein Stuhl vor mir wie die Sonne;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'wie der Mond soil er ewiglich erhalten sein und gleichwie der Zeuge in den Wolken gewüi sein. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Aber nun verstoßest du und verwirfest und zürnest mit deinem Gesalbten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Du verstorest den Bund deines Knechtes und trittst seine Krone zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Du zerreißest alle seine Mauern und lassest seine Festen zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Es rauben ihn alle, die vorübergehen; er ist seinen Nachbarn ein Spott worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du erhohest die Rechte seiner Widerwartigen und erfreuest alle seine Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Auch hast du die Kraft seines Schwerts weggenommen und lassest ihn nicht siegen im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Du zerstorest seine Reinigkeit und widest seinen Stuhl zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Du verkurzest die Zeit seiner Jugend und bedeckest ihn mit Hohn. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'HERR, wie lange willst du dich so gar verbergen und deinen Grimm wie Feuer brennen lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Gedenke, wie kurz mein Leben ist! Warum willst du alle Menschen umsonst geschaffen haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Wo istjemand, der da lebet und den Tod nicht sehe, der seine Seele errette aus der Holle Hand? Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'HERR, wo ist deine vorige Gnade, die du David geschworen hast in deiner Wahrheit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Gedenke, HERR, an die Schmach deiner Knechte, die ich trage in meinem Schoß von so vielen Volkern alien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'damit dich, HERR, deine Feinde schmahen, damit sie schmahen die Fußtapfen deines Gesalbten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, 'Gelobet sei der HERR ewiglich! Amen, Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Ein Gebet Moses, des Mannes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'HERR Gott, du bist unsere Zuflucht fur und fur. Ehe denn die Berge worden und die Erde und die Welt geschaffen worden, bist du, Gott, von Ewigkeit zu Ewigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'der du die Menschen lassest sterben und sprichst: Kommt wieder, Menschenkinder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Denn tausend Jahre sind vor dir wie der Tag, der gestern vergangen ist, und wie eine Nachtwache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du lassest sie dahinfahren wie einen Strom, und sind wie ein Schlaf, gleichwie ein Gras, das doch bald welkwird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'das da frühe blühet und bald welk wird und des Abends abgehauen wird und verdorret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Das macht dein Zorn, daß wir so vergehen, und dein Grimm, daß wir so plotzlich dahin müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Denn unsere Missetat stellest du vor dich, unsere unerkannte Sunde ins Licht vor deinem Angesichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Darum fahren alle unsere Tage dahin durch deinen Zorn; wir bringen unsere Jahre zu wie ein Geschwatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Unser Leben wahret siebenzig Jahre, und wenn\'s hoch kommt, so sind\'s achtzig Jahre; und wenn\'s kostlich gewesen ist, so ist\'s Mühe und Arbeit gewesen; denn es fahret schnell dahin, als flogen wir davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Wer glaubt es aber, daß du so sehr zurnest? und wer furchtet sich vor solchem deinem Grimm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Lehre uns bedenken, daß wir sterben müssen, auf daß wir klug werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'HERR, kehre dich doch wiederzu uns und sei deinen Knechten gnadig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Fulle uns frühe mit deiner Gnade, so wollen wir rühmen und frohlich sein unser Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Erfreue uns nun wieder, nachdem du uns so lange plagest, nachdem wir so lange Unglück leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Zeige deinen Knechten deine Werke und deine Ehre ihren Kindern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Und der HERR, unser Gott, sei uns freundlich und fordere das Werk unserer Hande bei uns; ja das Werk unserer Hande wolle er fordern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Wer unter dem Schirm des Hochsten sitzt und unter dem Schatten des Allmachtigen bleibt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'der spricht zu dem HERRN: Meine Zuversicht und meine Burg, mein Gott, auf den ich hoffe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Denn er errettet mich vom Strick des Jagers und von der schadlichen Pestilenz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Er wird dich mit seinen Fittichen decken, und deine Zuversicht wird sein unter seinen Flügeln. Seine Wahrheit ist Schirm und Schild,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'daß du nicht erschrecken müssest vor dem Grauen des Nachts, vor den Pfeilen, die des Tages fliegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'vor der Pestilenz, die im Finstern schleicht, vor der Seuche, die im Mittag verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ob tausend fallen zu deiner Seite und zehntausend zu deiner Rechten, so wird es doch dich nicht treffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Ja, du wirst mit deinen Augen deine Lust sehen und schauen, wie es den Gottlosen vergolten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Denn der HERR ist deine Zuversicht, der Hochste ist deine Zuflucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Es wird dir kein Ubels begegnen, und keine Plage wird zu deiner Hutte sich nahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Denn er hat seinen Engeln befohlen uber dir, daß sie dich behuten auf alien deinen Wegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'daß sie dich auf den Handen tragen und du deinen Fuft nicht an einen Stein stoftest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Auf den Lowen und Ottern wirst du gehen und treten auf den jungen Lowen und Drachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Er begehrt mein, so will ich ihm aushelfen; er kennet meinen Namen, darum will ich ihn schützen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'er rufet mich an, so will ich ihn erhoren. Ich bin bei ihm in der Not; ich will ihn herausreiften und zu Ehren machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Ich will ihn sattigen mit langem Leben und ihm zeigen mein Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein Psalmlied auf den Sabbattag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Das ist ein kostlich Ding, dem HERRN danken und lobsingen deinem Namen, du Hdchster,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'des Morgens deine Gnade und des Nachts deine Wahrheit verkundigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'auf den zehn Saiten und Psalter, mit Spielen auf der Harfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Denn, HERR, du lassest mich frohlich singen von deinen Werken, und ich rühme die Geschafte deiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'HERR, wie sind deine Werke so graft! Deine Gedanken sind so sehr tief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Ein Torichter glaubt das nicht, und ein Narr achtet solches nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Die Gottlosen grunen wie das Gras, und die Ubeltater blühen alle, bis sie vertilget werden immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Aberdu, HERR, bistder Hochste und bleibest ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Denn siehe, deine Feinde, HERR, siehe, deine Feinde werden umkommen; und alle Ubeltater müssen zerstreuet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Aber mein Horn wird erhohet werden wie eines Einhorns, und werde gesalbet mit frischem Ole.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Und mein Auge wird seine Lust sehen an meinen Feinden; und mein Ohrwird seine Lust horen an den Boshaftigen, die sich wider mich setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Der Gerechte wird grunen wie ein Palmbaum; er wird wachsen wie eine Zeder auf Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Die gepflanzt sind in dem Hause des HERRN, werden in den Vorhofen unsers Gottes grunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Und wenn sie gleich alt werden, werden sie dennoch blühen, fruchtbar und frisch sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, 'daß sie verkundigen, daß der HERR so fromm ist, mein Hort, und ist kein Unrecht an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Der HERR ist Konig und herrlich geschmuckt; der HERR ist geschmückt und hat ein Reich angefangen, soweit die Welt ist, und zugerichtet, daß es bleiben soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Von dem an stehet dein Stuhl test; du bist ewig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'HERR, die Wasserstrome erheben sich, die Wasserstrbme erheben ihr Brausen, die Wasserstrome heben empor die Wellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Die Wasserwogen im Meer sind grofi und brausen greulich; der HERR aber ist noch grower in der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Dein Wort ist eine rechte Lehre. Heiligkeit ist die Zierde deines Hauses ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'HERR Gott, des die Rache ist, Gott, des die Rache ist, erscheine!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Erhebe dich, du Richter der Welt; vergilt den Hoffartigen, was sie verdienen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'HERR, wie lange sollen die Gottlosen, wie lange sollen die Gottlosen prahlen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'und so trotziglich reden, und alle Ubeltater sich so rühmen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'HERR, sie zerschlagen dein Volk und plagen dein Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Witwen und Fremdlinge erwurgen sie und tdten die Waisen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'und sagen: Der HERR siehet\'s nicht und der Gott Jakobs achtet\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Merket doch, ihr Narren unter dem Volk, und ihr Toren, wann wollt ihr klug werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Der das Ohr gepflanzet hat, sollte der nicht horen? Der das Auge gemacht hat, sollte der nicht sehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Der die Heiden zuchtiget, sollte der nicht strafen? der die Menschen lehret, was sie wissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Aber der HERR weiß die Gedanken der Menschen, daß sie eitel sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Wohl dem, den du, HERR, zuchtigest und lehrest ihn durch dein Gesetz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'daß er Geduld habe, wenn\'s ubel gehet, bis dem Gottlosen die Grube bereitet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Denn der HERR wird sein Voik nicht verstoßen noch sein Erbe verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Denn Recht muß doch Recht bleiben, und dem werden alle frommen Herzen zufallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Wer stehet bei mir wider die Boshaftigen? Wer tritt zu mir wider die Ubeltater?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Wo der HERR mir nicht hulfe, so lage meine Seele schier in der Stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Ich sprach: Mein Fuß hat gestrauchelt; aber deine Gnade, HERR, hielt mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Ich hatte viel Bekümmernisse in meinem Herzen; aber deine Trostungen ergotzeten meine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Du wirst ja nimmer eins mit dem schadlichen Stuhl, der das Gesetz ubel deutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Sie rüsten sich wider die Seele des Gerechten und verdammen unschuldig Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Aber der HERR ist mein Schutz; mein Gott ist der Hort meiner Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Und er wird ihnen ihr Unrecht vergelten und wird sie um ihre Bosheit vertilgen; der HERR, unser Gott, wird sie vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kommt herzu, lafit uns dem HERRN frohlocken und jauchzen dem Hort unsers Heils!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Lasset uns mit Danken vor sein Angesicht kommen und mit Psalmen ihm jauchzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Denn der HERR ist ein grower Gott und ein großer Konig uber alle Gotter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Denn in seiner Hand ist, was die Erde bringet; und die Hohen der Berge sind auch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Denn sein ist das Meer, und er hat\'s gemacht; und seine Hande haben das Trockne bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kommt, laßt uns anbeten und knieen und niederfallen vor dem HERRN, der uns gemacht hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Denn er ist unser Gott, und wir das Volk seiner Weide und Schafe seiner Hand. Heute, so ihr seine Stimme horet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'so verstocket euer Herz nicht, wie zu Meriba geschah, wie zu Massa in der Wuste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'da mich eure Vater versuchten, fühleten und sahen mein Werk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'daß ich vierzig Jahre Mühe hatte mit diesem Volk und sprach: Es sind Leute, deren Herz immer den Irrweg will, und die meine Wege nicht lernen wollen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'daß ich schwur in meinem Zorn: Sie sollen nicht zu meiner Ruhe kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Singet dem HERRN ein neues Lied; singet dem HERRN, alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Singet dem HERRN und lobet seinen Namen; prediget einen Tag am andern sein Heil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Erzahlet unter den Heiden seine Ehre, unter alien Volkern seine Wunder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Denn der HERR ist groß und hoch zu loben, wunderbarlich uber alle Gotter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Denn alle Gotter der Vdlker sind Gotzen; aber der HERR hat den Himmel gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Es stehet herrlich und prachtig vor ihm und gehet gewaltiglich und loblich zu in seinem Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Ihr Volker, bringet her dem HERRN, bringet her dem HERRN Ehre und Macht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Bringet her dem HERRN die Ehre seinem Namen; bringet Geschenke und kommt in seine Vorhofe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Betet an den HERRN in heiligem Schmuck; es furchte ihn alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sagt unter den Heiden, daß der HERR Konig sei und habe sein Reich, soweit die Welt ist, bereitet, dafi es bleiben soil, und richtet die Volker recht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Himmel freue sich, und Erde sei frohlich; das Meer brause, und was drinnen ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'das Feld sei frohlich und alles, was drauf ist; und lasset ruhmen alle Baume im Walde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'vor dem HERRN; denn er kommt, denn er kommt, zu richten das Erdreich. Erwird den Erdboden richten mit Gerechtigkeit und die Volker mit seiner Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Der HERR ist Konig; des freue sich das Erdreich, und seien frohlich die Inseln, soviel ihrer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Wolken und Dunkel ist um ihn her. Gerechtigkeit und Gericht ist seines Stuhles Festung:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Feuer gehet vor ihm her und zündet an umher seine Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Seine Blitze leuchten auf den Erdboden; das Erdreich siehet und erschrickt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Berge zerschmelzen wie Wachs vor dem HERRN, vor dem Herrscher des ganzen Erdbodens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Die Himmel verkundigen seine Gerechtigkeit, und alle Volker sehen seine Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Schamen mussen sich alle, die den Bildern dienen und sich der Gotzen ruhmen. Betet ihn an, alle Gotter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion horetes und istfroh; und die Tochter Judas sind frohlich, HERR über deinem Regiment.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Denn du, HERR, bist der Hochste in alien Landen; du bist sehr erhohet über alle Gotter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Die ihrden HERRN liebet, hasset das Arge! Der HERR bewahret die Seelen seiner Heiligen; von der Gottlosen Hand wird er sie erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Dem Gerechten muß das Licht immer wieder aufgehen und Freude den frommen Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Ihr Gerechten, freuet euch des HERRN; und danket ihm und preiset seine Heiligkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein Psalm. Singet dem HERRN ein neues Lied; denn er tut Wunder. Er sieget mit seiner Rechten und mit seinem heiligen Arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Der HERR laßt sein Heil verkundigen, vor den Volkern laßt er seine Gerechtigkeit offenbaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Er gedenket an seine Gnade und Wahrheit dem Hause Israel. Aller Welt Enden sehen das Heil unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Jauchzet dem HERRN, alle Welt; singet, rühmet und lobet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Lobet den HERRN mit Harfen, mit Harfen und mit Psalmen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'mit Trommeten und Posaunen jauchzet vor dem HERRN, dem Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Das Meer brause, und was drinnen ist, der Erdboden, und die drauf wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Die Wasserstrome frohlocken, und alle Berge seien frohlich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'vor dem HERRN; denn er kommt, das Erdreich zu richten. Er wird den Erdboden richten mit Gerechtigkeit und die Volker mit Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Der HERR ist Konig, darum toben die Volker; er sitzet auf Cherubim, darum reget sich die Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Der HERR ist groß zu Zion und hoch über alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Man danke deinem großen und wunderbarlichen Namen, der da heilig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Im Reich dieses Konigs hat man das Recht lieb. Du gibst Frommigkeit; du schaffest Gericht und Gerechtigkeit in Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Erhebet den HERRN, unsern Gott, betet an zu seinem Fußschemel; denn er ist heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mose und Aaron unter seinen Priestern und Samuel unter denen, die seinen Namen anrufen; sie riefen an den HERRN, und ererhorete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Er redete mit ihnen durch eine Wolkensaule. Sie hielten seine Zeugnisse und Gebote, die er ihnen gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'HERR, du bist unser Gott, du erhoretest sie; du, Gott, vergabest ihnen und straftest ihr Tun:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Erhohet den HERRN, unsern Gott, und betet an zu seinem heiligen Berge; denn der HERR, unser Gott, ist heilig:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Dankpsalm. Jauchzet dem HERRN, alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Dienet dem HERRN mit Freuden; kommt vor sein Angesicht mit Frohlocken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Erkennet, daß der HERR Gott ist! Er hat uns gemacht, und nicht wir selbst zu seinem Volk und zu Schafen seiner Weide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Gehet zu seinen Toren ein mit Danken, zu seinen Vorhofen mit Loben; danket ihm, lobet seinen Namen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Denn der HERR istfreundlich, und seine Gnade wahret ewig und seine Wahrheit fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Ein Psalm Davids. Von Gnade und Recht will ich singen und dir, HERR, lobsagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Ich handle vorsichtig und redlich bei denen, die mirzugehoren, und wandle treulich in meinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Ich nehme mir keine bose Sache vor. Ich hasse den Ubertreter und lasse ihn nicht bei mir bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ein verkehret Herz muß von mirweichen; den Bosen leide ich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Der seinen Nachsten heimlich verleumdet, den vertilge ich. Ich mag des nicht, der stolze Gebarden und hohen Mut hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meine Augen sehen nach den Treuen im Lande, dafi sie bei mirwohnen, und habe gerne fromme Diener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Falsche Leute halte ich nicht in meinem Hause; die Lugner gedeihen nicht bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Fruhe vertilge ich alle Gottlosen im Lande, daß ich alle Ubeltater ausrotte aus der Stadt des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Ein Gebet des Elenden, so er betrubt ist und seine Klage vor dem HERRN ausschuttet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'HERR, hore mein Gebet und laß mein Schreien zudirkommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Verbirg dein Antlitz nicht vor mir in der Not; neige deine Ohren zu mir; wenn ich dich anrufe, so erhore mich bald!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Denn meine Tage sind vergangen wie ein Rauch, und meine Gebeine sind verbrannt wie ein Brand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Mein Herz ist geschlagen und verdorret wie Gras, daß ich auch vergesse, mein Brot zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Mein Gebein klebt an meinem Fleisch vor Heulen und Seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Ich bin gleich wie eine Rohrdommel in der Wüste; ich bin gleich wie ein Kauzlein in den verstorten Statten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Ich wache und bin wie ein einsamer Vogel auf dem Dache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Taglich schmahen mich meine Feinde; und die mich spotten, schworen bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Denn ich esse Asche wie Brot und mische meinen Trank mit Weinen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'vordeinem Drauen und Zorn, daß du mich aufgehoben und zu Boden gestoßen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Meine Tage sind dahin wie ein Schatten; und ich verdorre wie Gras.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Du aber, HERR, bleibest ewiglich und dein Gedachtnis fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Du wollest dich aufmachen und fiber Zion erbarmen; denn es ist Zeit, daß du ihrgnadig seiest, und die Stunde ist kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Denn deine Knechte wollten gerne, daß sie gebauet wurde, und sahen gerne, daß ihre Steine und Kalk zugerichtet würden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'daß die Heiden den Namen des HERRN furchten und alle Konige auf Erden deine Ehre;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'daß der HERR Zion bauet und erscheinet in seiner Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Er wendet sich zum Gebet der Verlassenen und verschmahet ihr Gebet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Daswerde geschrieben auf die Nachkommen; und das Volk, das geschaffen soil werden, wird den HERRN loben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Denn er schauet von seiner heiligen Hohe, und der HERR siehet vom Himmel auf Erden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'daß er das Seufzen des Gefangenen hore und losmache die Kinder des Todes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'auf daß sie zu Zion predigen den Namen des HERRN und sein Lob zu Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'wenn die Volkerzusammenkommen und die Konigreiche, dem HERRN zu dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Er demutiget auf dem Wege meine Kraft; er verkürzet meine Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Ich sage: Mein Gott, nimm mich nicht weg in der Halfte meiner Tage! Deine Jahre wahren fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Du hast vorhin die Erde gegrundet, und die Himmel sind deiner Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Sie werden vergehen, aber du bleibest. Sie werden alle veralten wie ein Gewand; sie werden verwandelt wie ein Kleid, wenn du sie verwandeln wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Du aber bleibest, wie du bist, und deine Jahre nehmen kein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, 'Die Kinder deiner Knechte werden bleiben, und ihr Same wird vor dir gedeihen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Ein Psalm Davids. Lobe den HERRN, meine Seele, und was in mir ist, seinen heiligen Namen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Lobe den HERRN, meine Seele, und vergiß nicht, was er dir Gutes getan hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'der dir alle deine Sünden vergibt und heilet alle deine Gebrechen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'der dein Leben vom Verderben erloset, der dich kronet mit Gnade und Barmherzigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'der deinen Mund frohlich machet, und du wieder jung wirst wie ein Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Der HERR schaffet Gerechtigkeit und Gericht alien, die Unrecht leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Er hat seine Wege Mose wissen lassen, die Kinder Israel sein Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Barmherzig und gnadig ist der HERR, geduldig und von großer Gute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Erwird nicht immerhadern, noch ewiglich Zorn halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Er handelt nicht mit uns nach unsern Sunden und vergilt uns nicht nach unserer Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Denn so hoch der Himmel uber der Erde ist, laßt er seine Gnade walten uber die, so ihn furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'So feme der Morgen ist vom Abend, lasset er unsere Ubertretung von uns sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Wie sich ein Vater uber Kinder erbarmet, so erbarmet sich der HERR uber die, so ihn furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Denn er kennet, was fur ein Gemachte wir sind; er gedenket daran, daß wir Staub sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Ein Mensch ist in seinem Leben wie Gras; er bluhet wie eine Blume auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Wenn der Wind daruber geht, so ist sie nimmer da, und ihre Statte kennet sie nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Die Gnade aber des HERRN wahretvon Ewigkeit zu Ewigkeit uber die, so ihn furchten, und seine Gerechtigkeit auf Kindeskind');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'bei denen, die seinen Bund halten und gedenken an seine Gebote, daß sie danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Der HERR hat seinen Stuhl im Himmel bereitet, und sein Reich herrschet uber alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Lobet den HERRN, ihr seine Engel, ihr starken Helden, die ihr seinen Befehl ausrichtet, daß man hore die Stimme seines Worts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Lobet den HERRN, alle seine Heerscharen, seine Diener, die ihr seinen Willen tut!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Lobet den HERRN, alle seine Werke, an alien Orten seiner Herrschaft! Lobe den HERRN, meine Seele!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Lobe den HERRN, meine Seele! HERR, mein Gott, du bist sehr herrlich; du bist schon und prachtig geschmuckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Licht ist dein Kleid, das du anhast. Du breitest aus den Himmel wie einen Teppich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'du wdlbest es oben mit Wasser; du fahrest auf den Wolken wie auf einem Wagen und gehest auf den Fittichen des Windes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'der du machest deine Engel zu Winden und deine Diener zu Feuerflammen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'derdu das Erdreich grundest auf seinen Boden, dafi es bleibt immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Mit der Tiefe deckest du es wie mit einem Kleid, und Wasser stehen uber den Bergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Aber von deinem Schelten fliehen sie, von deinem Donnerfahren sie dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Die Berge gehen hoch hervor, und die Breiten setzen sich herunter zum Ort, den du ihnen gegrundet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Du hast eine Grenze gesetzt, daruber kommen sie nicht, und müssen nicht wiederum das Erdreich bedecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Du lassest Brunnen quellen in den Grunden, daß die Wasser zwischen den Bergen hinflieften,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'daß alle Tiere auf dem Felde trinken und das Wild seinen Durst losche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'An denselben sitzen die Vogel des Himmels und singen unter den Zweigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Du feuchtest die Berge von oben her; du machest das Land voll Fruchte, die du schaffest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Du lassest Gras wachsen fur das Vieh und Saat zu Nutz den Menschen, daß du Brot aus der Erde bringest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'und daß der Wein erfreue des Menschen Herz und seine Gestalt schon werde von Ol, und das Brot des Menschen Herz starke;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'daß die Baume des HERRN voll Safts stehen, die Zedern Libanons, die er gepflanzet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Daselbst nisten die Vogel, und die Reiher wohnen auf den Tannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Die hohen Berge sind der Gemsen Zuflucht und die Steinklufte der Kaninchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Du machest den Mond, das Jahrdanach zu teilen; die Sonne weift ihren Niedergang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du machest Finsternis, daß Nacht wird; da regen sich alle wilden Tiere,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'die jungen Lowen, die da brüllen nach dem Raub und ihre Speise suchen von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Wenn aber die Sonne aufgehet, heben sie sich davon und legen sich in ihre Locher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'So gehet denn der Mensch aus an seine Arbeit und an sein Ackerwerk bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'HERR, wie sind deine Werke so graft und viel! Du hast sie alle weislich geordnet und die Erde ist voll deiner Guter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Das Meer, das so graft und weit ist, da wimmelt\'s ohne Zahl, beide grofte und kleine Tiere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Daselbst gehen die Schiffe; da sind Walfische, die du gemacht hast, daß sie drinnen scherzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Es wartet alles auf dich, daß du ihnen Speise gebest zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Wenn du ihnen gibst, so sammeln sie; wenn du deine Hand auftust, so werden sie mit Gut gesattiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Verbirgest du dein Angesicht, so erschrecken sie; du nimmst weg ihren Odem, so vergehen sie und werden wieder zu Staub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Du lassest aus deinen Odem, so werden sie geschaffen, und verneuerst die Gestalt der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Die Ehre des HERRN ist ewig; der HERR hat Wohlgefallen an seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Er schauet die Erde an, so bebet sie; er rühret die Berge an, so rauchen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Ich will dem HERRN singen mein Leben lang und meinen Gott loben, solange ich bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Meine Rede musse ihm wohlgefallen. Ich freue mich des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Der Sunder musse ein Ende werden auf Erden, und die Gottlosen nicht mehr sein! Lobe den HERRN, meine Seele! Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Danket dem HERRN und prediget seinen Namen; verkundiget sein Tun unter den Volkern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'singet von ihm und lobet ihn; redet von alien seinen Wundern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'ruhmet seinen heiligen Namen; es freue sich das Herz derer, die den HERRN suchen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Fraget nach dem HERRN und nach seiner Macht; suchet sein Antlitz allewege!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Gedenket seiner Wunderwerke, die er getan hat, seiner Wunder und seines Worts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'ihr, der Same Abrahams, seines Knechts, ihr Kinder Jakobs, seine Auserwahlten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Er ist der HERR, unser Gott; er richtet in aller Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Er gedenket ewiglich an seinen Bund, des Worts, das erverheiften hat auf viel tausend fur und fur');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'den er gemacht hat mit Abraham, und des Eides mit Isaak,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'und stellete dasselbige Jakob zu einem Recht und Israel zum ewigen Bunde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'und sprach: Dir will ich das Land Kanaan geben, das Los eures Erbes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'da siewenig und geringewaren und Fremdlinge drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Und sie zogen von Volk zu Volk, von einem Konigreiche zum andern Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Er liefi keinen Menschen ihnen Schaden tun und strafte Konige um ihretwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Tastet meine Gesalbten nichtan und tut meinen Propheten kein Leid!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Und er ließ eine Teurung ins Land kommen und entzog alien Vorrat des Brots.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Er sandte einen Mann vor ihnen hin; Joseph ward zum Knechte verkauft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Sie zwangen seine Fufie im Stock, sein Leib mußte in Eisen liegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'bis daß sein Wort kam und die Rede des HERRN ihn durchlauterte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Da sandte der Konig hin und lieli ihn losgeben, der Herr über Vblker hieß ihn auslassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ersetzte ihn zum Herrn uber sein Haus, zum Herrscher uber alle seine Güter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'daß er seine Fursten unterweisete nach seiner Weise und seine Altesten Weisheit lehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Und Israel zog nach Agypten, und Jakob ward ein Fremdling im Lande Hams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Und er lieli sein Volk sehr wachsen und machte sie machtiger denn ihre Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Er verkehrete jener Herz, daß sie seinem Volk gram wurden und dachten seine Knechte mit List zu dampfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Er sandte seinen Knecht Mose, Aaron, den er hatte erwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Dieselben taten seine Zeichen unter ihnen und seine Wunder im Lande Hams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Er lieli Finsternis kommen und machte es finster; und waren nicht ungehorsam seinen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Er verwandelte ihre Wasser in Blut und totete ihre Fische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Ihr Land wimmelte Kroten heraus in den Kammern ihrer Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Er sprach, da kam Ungeziefer, Lause, in alien ihren Grenzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Er gab ihnen Hagel zum Regen, Feuerflammen in ihrem Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'und schlug ihre Weinstocke und Feigenbaume und zerbrach die Baume in ihren Grenzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Er sprach, da kamen Heuschrecken und Kafer ohne Zahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Und sie fralien alles Gras in ihrem Lande und fraßen die Fruchte auf ihrem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Und schlug alle Erstgeburt in Agypten, alle ihre ersten Erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Und fuhrete sie aus mit Silber und Golde; und war kein Gebrechlicher unter ihren Stammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Agypten ward froh, dafi sie auszogen; denn ihre Furcht war auf sie gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Er breitete eine Wolke aus zur Decke und ein Feuer des Nachts zu leuchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Sie baten, da liefi er Wachteln kommen; und er sattigte sie mit Himmelbrot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Er offnete den Felsen, dafiossen Wasser aus, daß Bache liefen in der dürren Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Denn er gedachte an sein heiliges Wort, Abraham, seinem Knechte, geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Also fuhrete er sein Volk aus mit Freuden und seine Auserwahlten mit Wonne');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'und gab ihnen die Lander der Heiden, dafi sie die Güter der Volker einnahmen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'auf daü sie halten sollten seine Rechte und seine Gesetze bewahren. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja! Danket dem HERRN; denn er ist freundlich, und seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Wer kann die graven Taten des HERRN ausreden und alle seine loblichen Werke preisen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Wohl denen, die das Gebot halten und tun immerdar recht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'HERR, gedenke mein nach der Gnade, die du deinem Volk verheilien hast; beweise uns deine Hilfe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'dafi wir sehen mogen die Wohlfahrt deiner Auserwahlten und uns freuen, daü es deinem Volk wohlgehet, und uns rühmen mit deinem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Wir haben gesundiget samt unsern Vatern; wir haben mifigehandelt und sind gottlos gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Unsere Vater in Agypten wollten deine Wunder nicht verstehen; sie gedachten nicht an deine grolie Güte und waren ungehorsam am Meer, namlich am Schilfmeer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Er half ihnen aber um seines Namens willen, dafi er seine Macht beweisete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Und er schalt das Schilfmeer, da ward\'s trocken; und fuhrete sie durch die Tiefe wie in einer Wuste;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'und half ihnen von der Hand des, der, sie hassete, und erlosete sie von der Hand des Feindes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Und die Wasser ersauften ihre Widersacher, dafi nicht einer überblieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Da glaubten sie an seine Worte und sangen sein Lob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Aber sie vergafien bald seiner Werke; sie warteten nicht seines Rats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Und sie wurden lüstem in der Wuste und versuchten Gott in der Einode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Er aber gab ihnen ihre Bitte und sandte ihnen genug, bis ihnen davor ekelte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Und sie emporten sich wider Mose im Lager, wider Aaron, den Heiligen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Die Erde tat sich auf und verschlang Dathan und deckte zu die Rotte Abirams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Und Feuer ward unter ihrer Rotte angezündet; die Flamme verbrannte die Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Sie machten ein Kalb in Horeb und beteten an das gegossene Bild;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'und verwandelten ihre Ehre in ein Gleichnis eines Ochsen, der Gras isset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Sie vergaüen Gottes, ihres Heilandes, der so grofie Dinge in Agypten getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Wunder im Lande Hams und schreckliche Werke am Schilfmeer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Und er sprach, er wollte sie vertilgen, wo nicht Mose, sein Auserwahlter, den Rili aufgehalten hatte, seinen Grimm abzuwenden, auf dafi er sie nicht gar verderbete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Und sie verachteten das liebe Land; sie glaubten seinem Wort nicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'und murreten in ihren Hutten; sie gehorchten der Stimme des HERRN nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Und er hub auf seine Hand wider sie, daß er sie niederschlüge in der Wüste');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'und wurfe ihren Samen unterdie Heiden und streuete sie in die Lander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Und sie hingen sich an den Baal Peor und alien von den Opfern der toten Gotzen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'und erzurneten ihn mit ihrem Tun; da rili auch die Plage unter sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Da tratzu Pinehas und schlichtete die Sache; da ward der Plage gesteuert,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'und ward ihm gerechnet zur Gerechtigkeit fur und fur ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Und sie erzurneten ihn am Haderwasser; und sie zerplagten den Mose ubel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Denn sie betrubten ihm sein Herz, daß ihm etliche Worte entfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Auch vertilgten sie die Volker nicht, wie sie doch der HERR geheifien hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'sondern sie mengeten sich unter die Heiden und lernten derselben Werke');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'und dieneten ihren Gotzen, die gerieten ihnen zum Argernis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Und sie opferten ihre Sohne und ihre Tochter den Teufeln');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'und vergossen unschuldig Blut, das Blut ihrer Sohne und ihrer Tochter, die sie opferten den Gotzen Kanaans, daü das Land mit Blutschulden befleckt ward;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'und verunreinigten sich mit ihren Werken und hureten mit ihrem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Da ergrimmete der Zorn des HERRN fiber sein Volk und gewann einen Greuel an seinem Erbe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'und gab sie in die Hand der Heiden, daü über sie herrscheten, die ihnen gram waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Und ihre Feinde angsteten sie; und wurden gedemütiget unter ihre Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Er errettete sie oftmals; aber sie erzurneten ihn mit ihrem Vornehmen und wurden wenig urn ihrer Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Und er sah ihre Not an, da er ihre Klage horete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'und gedachte an seinen Bund, mit ihnen gemacht. Und reuete ihn nach seiner grofien Gute');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'und liefi sie zur Barmherzigkeit kommen vor alien, die sie gefangen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Hilf uns, HERR, unser Gott, und bringe uns zusammen aus den Heiden, daß wir danken deinem heiligen Namen und rühmen dein Lob!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Gelobet sei der HERR, der Gott Israels, von Ewigkeit zu Ewigkeit, und alles Volk spreche: Amen, Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Danketdem HERRN; denn eristfreundlich, und seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Saget, die ihr erloset seid durch den HERRN, die er aus der Not erloset hat');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'und die er aus den Landern zusammengebracht hat vom Aufgang, vom Niedergang, von Mitternacht und vom Meer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'die irregingen in der Wüste, in ungebahntem Wege, und fanden keine Stadt, da sie wohnen konnten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'hungrig und durstig und ihre Seele verschmachtet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'und sie zum HERRN riefen in ihrer Not, und er sie errettete aus ihren Angsten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'und fuhrete sie einen richtigen Weg, daü sie gingen zur Stadt, da sie wohnen konnten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'die sollen dem HERRN danken urn seine Gute und urn seine Wunder, die er an den Menschenkindern tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'daß er sattiget die durstige Seele und füllet die hungrige Seele mit Gutem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Die da sitzen muüten in Finsternis und Dunkel, gefangen im Zwang und Eisen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'darum daß sie Gottes Geboten ungehorsam gewesen waren und das Gesetz des Hochsten geschandet hatten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'darum mulite ihr Herz mit Unglück geplagt werden, daß sie dalagen, und ihnen niemand half;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'und sie zum HERRN riefen in ihrer Not, und er ihnen half aus ihren Angsten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'und sie aus der Finsternis und Dunkel fuhrete und ihre Bande zerrili:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'die sollen dem HERRN danken urn seine Gute und urn seine Wunder, die er an den Menschenkindern tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'daü er zerbricht eherne Türen und zerschlagt eiserne Riegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Die Narren, so geplaget waren urn ihrer Ubertretung willen und urn ihrer Sunde wilien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'daü ihnen ekelte vor aller Speise und wurden todkrank;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'und sie zum HERRN riefen in ihrer Not, und er ihnen half aus ihren Angsten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'er sandte sein Wort und machte sie gesund und errettete sie, daü sie nicht starben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'die sollen dem HERRN danken urn seine Gute und urn seine Wunder, die er an den Menschenkindern tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'und Dank opfern und erzahlen seine Werke mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Die mit Schiffen aufdem Meer fuhren und trieben ihren Handel in groften Wassern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'die des HERRN Werke erfahren haben und seine Wunder im Meer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'wenn ersprach und einen Sturmwind erregte, der die Wellen erhub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'und sie gen Himmel fuhren und in den Abgrund fuhren, daß ihre Seele vor Angst verzagte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'daß sie taumelten und wankten wie ein Trunkener und wuftten keinen Rat mehr;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'und sie zum HERRN schrieen in ihrer Not, und er sie aus ihren Angsten führete');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'und stillete das Ungewitter, daß die Wellen sich legten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'und sie froh wurden, daß es stille worden war, und er sie zu Lande brachte nach ihrem Wunsch:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'die sollen dem HERRN danken um seine Gute und um seine Wunder, die er an den Menschenkindern tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'und ihn bei der Gemeine preisen und bei den Alten rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Die, weichen ihre Bache vertrocknet und die Wasserquellen versieget waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'daß ein fruchtbar Land nichts trug um der Bosheit willen derer, die drinnen wohneten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'und er das Trockne wiederum wasserreich machte und im durren Lande Wasserquellen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'und die Hungrigen dahin gesetzt hat, daß sie eine Stadt zurichteten, da sie wohnen konnten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'und Acker besaen und Weinberge pflanzen mochten und die jahrlichen Fruchte kriegten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'und er sie segnete, daß sie sich fast mehreten, und ihnen viel Viehes gab;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'die, welch niedergedruckt und geschwacht waren von dem Bosen, der sie gezwungen und gedrungen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'da Verachtung auf die Fürsten geschuttet war, daß alles irrig und wüste stund;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'und erden Armen schutzte vor Elend und sein Geschlecht wie eine Herde mehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Solches werden die Frommen sehen und sich freuen; und aller Bosheit wird das Maul gestopft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Wer ist weise und behalt dies? So werden sie merken, wieviel Wohltat der HERR erzeiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein Psalmlied Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Gott, es ist mein rechter Ernst; ich will singen und dichten, meine Ehre auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Wohlauf, Psalter und Harfen! Ich will früh auf sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Ich will dir danken, HERR, unter den Vblkern, ich will dir lobsingen unter den Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Denn deine Gnade reicht, soweit der Himmel ist, und deine Wahrheit, soweit die Wolken gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Erhebe dich, Gott, uber den Himmel und deine Ehre uber alle Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'auf daß deine lieben Freunde erlediget werden. Hilf mit deiner Rechten und erhore mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gott redet in seinem Heiligtum; des bin ich froh und will Sichem teilen und das Tal Suchoth abmessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Gilead ist mein, Manasse ist auch mein und Ephraim ist die Macht meines Haupts, Juda ist mein Fürst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab ist mein Waschtopfen; ich will meinen Schuh uber Edom strecken; fiber die Philister will ich jauchzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Wer will mich fuhren in eine feste Stadt? Wer wird mich leiten nach Edom?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Wirst du es nicht tun, Gott, der du uns verstoftest und zeuchst nicht aus, Gott, mit unserm Heer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Schaffe uns Beistand in der Not, denn Menschenhilfe ist kein nutze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, 'Mit Gott wollen wir Taten tun. Erwird unsere Feinde untertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Ein Psalm Davids, vorzusingen. Gott, mein Ruhm, schweige nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Denn sie haben ihr gottloses und falsches Maul wider mich aufgetan und reden wider mich mit falscher Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Und sie reden giftig wider mich allenthalben und streiten wider mich ohne Ursache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Dafür, daß ich sie liebe, sind sie wider mich; ich aber bete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Sie beweisen mir Boses um Gutes und Haft um Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Setze Gottlose fiber ihn; und der Satan müsse stehen zu seiner Rechten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Wer sich denselben lehren laftt, des Leben müsse gottlos sein, und sein Gebet müsse Sünde sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Seiner Tage müssen wenig werden, und sein Amt müsse ein anderer empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Seine Kinder müssen Waisen werden und sein Weib eine Witwe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Seine Kinder müssen in der Irre gehen und betteln und suchen, als die verdorben sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Es müsse der Wucherer aussaugen alles, was er hat; und Fremde müssen seine Güter rauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Und niemand müsse ihm Gutes tun, und niemand erbarme sich seiner Waisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Seine Nachkommen müssen ausgerottet werden; ihr Name müsse im andern Glied vertilget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Seiner Vater Missetat müsse gedacht werden vordem HERRN, und seiner Mutter Sunde musse nicht ausgetilget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Der HERR musse sie nimmer aus den Augen lassen, und ihr Gedachtnis musse ausgerottet werden auf Erden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'darum daß er so gar keine Barmherzigkeit hatte, sondern verfolgte den Elenden und Armen und den Betrubten, daß er ihn totete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Und erwollte den Fluch haben, derwird ihm auch kommen; erwollte des Segens nicht, so wird er auch feme von ihm bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Und zog an den Fluch wie sein Hemd; und ist in sein Inwendiges gegangen wie Wasser und wie 01 in seine Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'So werde er ihm wie ein Kleid, das eranhabe, und wie ein Gürtel, da er sich aliewege mit gurte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'So geschehe denen vorn HERRN, die mir wider sind, und reden Boses wider meine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Aberdu, HERR Herr, sei du mit mir urn deines Namens willen; denn deine Gnade ist mein Trost; errette mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Denn ich bin arm und eiend; mein Herz ist erschlagen in mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Ich fahre dahin wie ein Schatten, der vertrieben wird, und werde verjaget wie die Heuschrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Meine Kniee sind schwach von Fasten; und mein Fleisch ist mager und hat kein Fett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Und ich muft ihr Spott sein; wenn sie mich sehen, schutteln sie ihren Kopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Stehe mir bei, HERR, mein Gott; hilf mir nach deiner Gnade,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'daß sie inne werden, dad dies sei deine Hand, daß du, HERR, solches tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Fluchen sie, so segne du. Setzen sie sich wider mich, so müssen sie zuschanden werden; aber dein Knecht musse sich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Meine Widersacher müssen mit Schmach angezogen werden und mit ihrer Schande bekleidet werden wie mit einem Rock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Ich will dem HERRN sehrdanken mit meinem Munde und ihn rühmen untervielen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'denn er stehet dem Armen zur Rechten, dad er ihm helfe von denen, die sein Leben verurteilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Ein Psalm Davids. Der HERR sprach zu meinem HERRN: Setze dich zu meiner Rechten, bis ich deine Feinde zum Schemel deiner Füde lege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Der HERR wird das Zepter deines Reichs senden aus Zion. Herrsche unterdeinen Feinden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Nach deinem Sieg wird dir dein Volk williglich opfern in heiligem, Schmuck. Deine Kinder werden dir geboren wie der Tau aus der Morgenrote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Der HERR hat geschworen, und wird ihn nicht gereuen; Du bist ein Priester ewiglich nach der Weise Melchisedechs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der HERR zu deiner Rechten wird zerschmeiften die Konige zur Zeit seines Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Er wird richten unter den Heiden; er wird grofte Schlacht tun; erwird zerschmeiften das Haupt fiber grotie Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Er wird trinken vom Bach auf dem Wege; darum wird er das Haupt emporheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Segen. Ich danke dem HERRN von ganzem Herzen im Rat der Frommen und in der Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Groß sind die Werke des HERRN; wer ihrer achtet, der hat eitel Lust daran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Was er ordnet, das ist loblich und herrlich, und seine Gerechtigkeit bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Er hat ein Gedachtnis gestiftet seiner Wunder, der gnadige und barmherzige HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Er gibt Speise denen, so ihn furchten; er gedenket ewiglich an seinen Bund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Er laftt verkundigen seine gewaltigen Taten seinem Volk, daß er ihnen gebe das Erbe der Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Die Werke seiner Hande sind Wahrheit und Recht; alle seine Gebote sind rechtschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Sie werden erhalten immer und ewiglich und geschehen treulich und redlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Er sendet eine Erlosung seinem Volk; er verheiftet, daß sein Bund ewiglich bleiben soli. Heilig und hehr ist sein Name.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Die Furchtdes HERRN ist der Weisheit Anfang; das ist eine feine Klugheit; wer danach tut, des Lob bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Wohl dem, der den HERRN furchtet, der grofte Lust hat zu seinen Geboten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Des Same wird gewaltig sein auf Erden; das Geschlecht der Frommen wird gesegnet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Reichtum und die Fulle wird in ihrem Hause sein, und ihre Gerechtigkeit bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Den Frommen gehet das Licht auf in der Finsternis von dem Gnadigen, Barmherzigen und Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Wohl dem, der barmherzig ist und gerne leihet und richtet seine Sachen aus, daß er niemand unrecht tue!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Denn erwird ewiglich bleiben; des Gerechten wird nimmermehr vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Wenn eine Plage kommen will, so furchtet er sich nicht; sein Herz hoffet unverzagt auf den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Sein Herz ist getrost und furchtet sich nicht, bis er seine Lust an seinen Feinden siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Er streuet aus und gibt den Armen; seine Gerechtigkeit bleibet ewiglich; sein Horn wird erhohet mit Ehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Der Gottlose wird\'s sehen, und wird ihn verdriefien; seine Zahne wird erzusammenbeißen und vergehen. Denn was die Gottlosen gerne wollten, das ist verloren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Lobet, ihr Knechte des HERRN, lobet den Namen des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Gelobet sei des HERRN Name von nun an bis in Ewigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobet der Name des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Der HERR ist hoch über alle Heiden; seine Ehre gehet, soweit der Himmel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Wer ist, wie der HERR, unser Gott? Der sich so hoch gesetzt hat');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'und auf das Niedrige siehet im Himmel und auf Erden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'der den Geringen aufrichtet aus dem Staube und erhohet den Armen aus dem Kot,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'dati er ihn setze neben die Fursten, neben die Fursten seines Volks;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'der die Unfruchtbare im Hause wohnen macht, dalj sie eine frohliche Kindermutter wird. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Da Israel aus Agypten zog, das Haus Jakob aus dem fremden Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'da ward Juda sein Heiligtum, Israel seine Herrschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Das Meer sah und floh; der Jordan wandte sich zuruck;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'die Berge hupfeten wie die Lammer, die Hugel wie die jungen Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Was war dir, du Meer, dati du flohest, und du Jordan, daß du dich zurückwandtest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'ihr Berge, daß ihr hupfetet wie die Lammer, ihr Hugel, wie die jungen Schafe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Vor dem HERRN bebete die Erde, vor dem Gott Jakobs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'der den Fels wandelte in Wassersee und die Steine in Wasserbrunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nicht uns, HERR, nichtuns, sondern deinem Namen gib Ehre urn deine Gnade und Wahrheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Warum sollen die Heiden sagen: Wo ist nun ihr Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Aber unser Gott ist im Himmel; er kann schaffen, was er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Jenerßotzen abersind Silberund Gold, von Menschenhanden gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Sie haben Mauler und reden nicht; sie haben Augen und sehen nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'sie haben Ohren und horen nicht; sie haben Nasen und riechen nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'sie haben Hande und greifen nicht; Fütße haben sie und gehen nicht und reden nicht durch ihren Hals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Die solche machen, sind gleich also, und alle, die auf sie hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Aber Israel hoffe auf den HERRN; der ist ihre Hilfe und Schild.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Das Haus Aaron hoffe auf den HERRN; der ist ihre Hüfe und Schild.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Die den HERRN furchten, hoffen auch auf den HERRN; der ist ihre Hilfe und Schild.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Der HERR denketan uns und segnetuns. Er segnet das Haus Israel; er segnet das Haus Aaron;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'er segnet, die den HERRN furchten, beide Kleine und Grolie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Der HERR segne euch je mehr und mehr, euch und eure Kinder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Ihrseid die Gesegneten des HERRN, der Himmel und Erde gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Der Himmel allenthalben ist des HERRN; aber die Erde hat er den Menschenkindern gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Die Totenwerden dich, HERR, nicht loben, noch die hinunterfahren in die Stille,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'sondern wir loben den HERRN von nun an bis in Ewigkeit. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Das ist mir lieb, daß der HERR meine Stimme und mein Flehen horet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'daß er sein Ohr zu mir neiget; darum will ich mein Leben lang ihn anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Stricke des Todes hatten mich umfangen, und Angst der Holle hatte mich getroffen; ich kam in Jammer und Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Aber ich rief an den Namen des HERRN: 0 HERR, errette meine Seele!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Der HERR ist gnadig und gerecht, und unser Gott ist barmherzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Der HERR behutet die Einfaltigen. Wenn ich unterliege, so hilft er mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Sei nun wiederzufrieden, meine Seele; denn der HERR tut dir Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Denn du hast meine Seele aus dem Tode gerissen, mein Auge von den Tranen, meinen Fu(i vom Gleiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Ich will wandeln vor dem HERRN im Lande der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Ich glaube, darum rede ich. Ich werde aber sehrgeplagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Ich sprach in meinem Zagen: Alle Menschen sind Lügner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Wie soil ich dem HERRN vergelten alle seine Wohltat, die er an mir tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Ich will den heilsamen Kelch nehmen und des HERRN Namen predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Ich will meine Gelubde dem HERRN bezahlen vor all seinem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Der Tod seiner Heiligen ist wert gehalten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, '0 HERR, ich bin dein Knecht; ich bin dein Knecht, deiner Magd Sohn. Du hast meine Bande zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Dir will ich Dankopfern und des HERRN Namen predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Ich will meine Gelubde dem HERRN bezahlen vor all seinem Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'in den Hofen am Hause des HERRN, in dir, Jerusalem. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lobetden HERRN, alle Heiden; preisetihn, alle Volker!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Denn seine Gnade und Wahrheit waltet uber uns in Ewigkeit. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Danketdem HERRN; denn eristfreundlich, und seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Es sage nun Israel: Seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Es sage nun das Haus Aaron: Seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Es sagen nun, die den HERRN furchten: Seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'In der Angst rief ich den HERRN an, und der HERR erhorete mich und trostete mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Der HERR ist mit mir, darum furchte ich mich nicht; was konnen mir Menschen tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Der HERR ist mit mir, mirzu helfen; und ich will meine Lust sehen an meinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Es ist gut auf den HERRN vertrauen und sich nicht verlassen auf Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Es ist gut auf den HERRN vertrauen und sich nicht verlassen auf Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Alle Heiden umgeben mich; aber im Namen des HERRN will ich sie zerhauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Sie umgeben mich allenthalben; aber im Namen des HERRN will ich sie zerhauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Sie umgeben mich wie Bienen, siedampfen wie ein Feuer in Dornen; aber im Namen des HERRN will ich sie zerhauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Man stofiet mich, daß ich fallen soil; aber der HERR hilft mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Der HERR ist meine Macht und mein Psalm und ist mein Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Man singt mit Freuden vom Sieg in den Hütten der Gerechten. Die Rechte des HERRN behalt den Sieg;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'die Rechte des HERRN isterhohet; die Rechte des HERRN behalt den Sieg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ich werde nicht sterben, sondern ieben und des HERRN Werk verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Der HERR zuchtiget mich wohl, aberergibt mich dem Tode nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Tut mir auf die Tore der Gerechtigkeit, dafi ich dahin eingehe und dem HERRN danke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Das ist das Tor des HERRN; die Gerechten werden dahin eingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Ich danke dir, daß du mich demutigest und hilfst mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, den die Bauleute verworfen, ist zum Eckstein worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Das ist vom HERRN geschehen und ist ein Wunder vor unsern Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, den der HERR macht; lalit uns freuen und frohlich drinnen sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, '0 HERR, hilf, o HERR, lafi wohlgelingen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gelobet sei, der da kommt im Namen des HERRN! Wir segnen euch, die ihr vom Hause des HERRN seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Der HERR ist Gott, der uns erleuchtet. Schmucket das Fest mit Maien bis an die Horner des Altars;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du hist mein Gott, und ich danke dir; mein Gott, ich will dich preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Danketdem HERRN; denn eristfreundlich, und seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Wohl denen, die ohne Wandel Ieben, die im Gesetz des HERRN wandeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Wohl denen, die seine Zeugnisse halten, die ihn von ganzem Herzen suchen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Denn welche auf seinen Wegen wandeln, die tun kein Ubels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du hast geboten, fleifüg zu halten deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O daß mein Leben deine Rechte mit ganzem Ernst hielte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Wenn ich schaue allein auf deine Gebote, so werde ich nicht zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Ich danke dir von rechtem Herzen, daß du mich lehrest die Rechte deiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Deine Rechte will ich halten; verlafi mich nimmermehr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Wie wird ein Jungling seinen Weg unstraflich gehen? Wenn er sich halt nach deinen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Ich suchedich von ganzem Herzen; lali mich nicht fehlen deiner Gebote!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Ich behalte dein Wort in meinem Herzen, auf daß ich nicht wider dich sundige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Gelobet seiestdu, HERR! Lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Ich will mit meinen Lippen erzahlen alle Rechte deines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Ich freue mich des Weges deiner Zeugnisse als uber allerlei Reichtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Ich rede, was du befohlen hast, und schaue auf deine Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Ich habe Lustzu deinen Rechten und vergesse deine Worte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tu wohl deinem Knechte, dafi ich lebe und dein Wort halte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Offne mir die Augen, daß ich sehe die Wunder an deinem Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ich bin ein Gast auf Erden; verbirg deine Gebote nicht vor mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Meine Seele ist zermalmet vor Verlangen nach deinen Rechten allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Du schiltstdie Stolzen; verflucht sind, die deiner Gebote fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Wende von mir Schmach und Verachtung; denn ich halte deine Zeugnisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Es sitzen auch die Fursten und reden wider mich; aber dein Knecht redet von deinen Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Ich habe Lust zu deinen Zeugnissen; die sind meine Ratsleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Meine Seele liegt im Staube; erquicke mich nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Ich erzahle meine Wege, und du erhorest mich; lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Unterweise mich den Weg deiner Befehle, so will ich reden von deinen Wundern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Ich grame mich, daß mir das Herz verschmachtet; starke mich nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Wende von mir den falschen Weg und gonne mir dein Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Ich habe den Weg der Wahrheit erwahlet; deine Rechte hab ich vor mich gestellet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'ich hange an deinen Zeugnissen; HERR, laft mich nicht zuschanden werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Wenn du mein Herz trostest, so laufe ich den Weg deiner Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Zeige mir, HERR, den Weg deiner Rechte, daß ich sie bewahre bis ans Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Unterweise mich, daß ich bewahre dein Gesetz und halte es von ganzem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Führe mich auf dem Steige deiner Gebote; denn ich habe Lustdazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Neige mein Herz zu deinen Zeugnissen und nicht zum Geiz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Wende meine Augen ab, daß sie nicht sehen nach unnutzer Lehre, sondern erquicke mich auf deinem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Laft deinen Knecht dein Gebot festiglich fur dein Wort halten, daß ich dich furchte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Wende von mir die Schmach, die ich scheue; denn deine Rechte sind lieblich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Siehe, ich begehre deiner Befehle; erquicke mich mit deiner Gerechtigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'HERR, laft mir deine Gnade widerfahren, deine Hilfe nach deinem Wort,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'daß ich antworten moge meinem Lasterer; denn ich verlasse mich auf dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Und nimm ja nicht von meinem Munde das Wort der Wahrheit; denn ich hoffe auf deine Rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Ich will dein Gesetz halten allewege, immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Und ich wandle frohlich; denn ich suche deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Ich rede von deinen Zeugnissen vor Konigen und schame mich nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'und habe Lust an deinen Geboten, und sind mirlieb;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'und hebe meine Hande auf zu deinen Geboten, die mir lieb sind, und rede von deinen Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Gedenke deinem Knechte an dein Wort, auf welches du mich lassest hoffen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Das ist mein T rost in meinem Elende; denn dein Wort erquicket mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Die Stolzen haben ihren Spottan mir; dennoch weiche ich nicht von deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'HERR, wenn ich gedenke, wie du von der Welt her gerichtet hast, so werde ich getrostet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Ich bin entbrannt uber die Gottlosen, die dein Gesetz verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Deine Rechte sind mein Lied in dem Hause meiner Wallfahrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'HERR, ich gedenke des Nachts an deinen Namen und halte dein Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Das ist mein Schatz, daß ich deine Befehle halte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Ich habe gesagt, HERR, das soil mein Erbe sein, daß ich deine Wege halte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Ich flehe vor deinem Angesichte von ganzem Herzen; sei mir gnadig nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Ich betrachte meine Wege und kehre meine Füfte zu deinen Zeugnissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Ich eile und saume mich nicht, zu halten deine Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Der Gottlosen Rotte beraubet mich; aber ich vergesse deines Gesetzes nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Zur Mitternacht stehe ich auf, dirzu danken fur die Rechte deiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Ich halte mich zu denen, die dich fürchten und deine Befehle halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'HERR, die Erde ist voll deiner Güte; lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Du tust Gutes deinem Knechte, HERR, nach deinem Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Lehre mich heilsame Sitten und Erkenntnis; denn ich glaube deinen Geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Ehe ich gedemutiget ward, irrete ich; nun aber halte ich dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Du bistgütig und freundlich; lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Die Stolzen erdichten Lugen uber mich; ich aber halte von ganzem Herzen deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Ihr Herz ist dick wie Schmeer; ich aber habe Lust an deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Es ist mir lieb, daß du mich gedemutiget hast, daß ich deine Rechte lerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Das Gesetz deines Mundes ist mir lieber denn viel tausend Stuck Gold und Silber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Deine Hand hat mich gemacht und bereitet; unterweise mich, daß ich deine Gebote lerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Die dich furchten, sehen mich und freuen sich; denn ich hoffe auf dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'HERR, ich weift, daß deine Gerichte recht sind und hast mich treulich gedemütiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Deine Gnade müsse mein T rest sein, wie du deinem Knechte zugesagt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Laft mir deine Barmherzigkeit widerfahren, daß ich lebe; denn ich habe Lustzu deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Ach, daß die Stolzen mußten zuschanden werden, die mich mit Lugen niederdrucken! Ich aber rede von deinem Befehl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Ach, daß sich müliten zu mir halten, die dich furchten und deine Zeugnisse kennen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Mein Herz bleibe rechtschaffen in deinen Rechten, daß ich nicht zuschanden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Meine Seele verlanget nach deinem Heil; ich hoffe auf dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Meine Augen sehnen sich nach deinem Wort und sagen: Wann trostest du mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Denn ich bin wie eine Haut im Rauch; deiner Rechte vergesse ich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wie lange soil dein Knecht warten? Wann willst du Gericht halten uber meine Verfolger?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Die Stolzen graben mir Gruben, die nicht sind nach deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Deine Gebote sind eitel Wahrheit. Sie verfolgen mich mit Lugen; hilf mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Sie haben mich schier umgebracht auf Erden; ich aberverlasse deine Befehle nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Erquicke mich durch deine Gnade, daß ich halte die Zeugnisse deines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'HERR, dein Wort bleibt ewiglich, soweit der Himmel ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'deine Wahrheit wahret fur und fur. Du hast die Erde zugerichtet, und sie bleibt stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Es bleibet taglich nach deinem Wort; denn es muß dir alles dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Wo dein Gesetz nicht mein T rost gewesen ware, so ware ich vergangen in meinem Elende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Ich will deine Befehle nimmermehrvergessen; denn du erquickest mich damit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Ich bin dein, hilf mir; denn ich suche deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Die Gottlosen warten auf mich, daß sie mich umbringen; ich aber merke auf deine Zeugnisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Ich habe alles Dinges ein Ende gesehen; aber dein Gebot wahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Wie habe ich dein Gesetz so lieb! Taglich rede ich davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Du machst mich mit deinem Gebot weiser, denn meine Feinde sind; denn es ist ewiglich mein Schatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Ich bin gelehrter denn alle meine Lehrer; denn deine Zeugnisse sind meine Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Ich bin klugerdenn die Alten; denn ich halte deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Ich wehre meinem Fuft alle bosen Wege, daß ich dein Wort halte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Ich weiche nicht von deinen Rechten; denn du lehrest mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Dein Wort ist meinem Munde sulierdenn Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Dein Wort macht mich klug; darum hasse ich alle falschen Wege,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Dein Wort istmeines Fußes Leuchte und ein Licht auf meinem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Ich schwore und will\'s halten, daß ich die Rechte deiner Gerechtigkeit halten will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ich bin sehr gedemütiget; HERR, erquicke mich nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Laft dir gefallen, HERR, das willige Opfer meines Mundes und lehre mich deine Rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Ich trage meine Seele immer in meinen Handen und ich vergesse deines Gesetzes nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Die Gottlosen legen mirßtricke; ich aberirre nicht von deinem Befehl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Deine Zeugnisse sind mein ewiges Erbe; denn sie sind meines Herzens Wonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Ich neige mein Herz, zu tun nach deinen Rechten immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Ich hasse die Flattergeister und liebedein Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Du bist mein Schirm und Schild; ich hoffe auf dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Weichet von mir, ihr Boshaftigen; ich will halten die Gebote meines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Erhalte mich durch dein Wort, daß ich lebe, und laft mich nicht zuschanden werden uber meiner Hoffnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Starke mich, daß ich genese, so will ich stets meine Lust haben an deinen Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Du zertrittst alle, die deiner Rechte fehlen; denn ihre Trugerei ist eitel Luge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Du wirfst alle Gottlosen auf Erden weg wie Schlacken; darum liebe ich deine Zeugnisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Ich furchte mich vor dir, daß mir die Haut schauert, und entsetze mich vor deinen Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Ich halte überdem Recht und Gerechtigkeit; ubergib mich nicht denen, die mir wollen Gewalt tun!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Vertritt du deinen Knecht und troste ihn, daß mir die Stolzen nicht Gewalt tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Meine Augen sehnen sich nach deinem Heil und nach dem Wort deiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Handle mit deinem Knechte nach deiner Gnade und lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Ich bin dein Knecht; unterweise mich, daß ich erkenne deine Zeugnisse!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Es ist Zeit, daß der HERR dazu tue; sie haben dein Gesetz zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Darum liebe ich dein Gebot uber Gold und uber fein Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Darum halte ich stracks alle deine Befehle; ich hasse alien falschen Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Deine Zeugnisse sind wunderbarlich; darum halt sie meine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Wenn dein Wort offenbar wird, so erfreuet es und macht klug die Einfaltigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Ich tue meinen Mund auf und begehre deine Gebote; denn mich verlanget danach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wende dich zu mir und sei mir gnadig, wie du pflegst zu tun denen, die deinen Namen lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Laß, meinen Gang gewiß sein in deinem Wort und laß kein Unrecht uber mich herrschen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Erlose mich von der Menschen Frevel, so will ich halten deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Laß dein Antlitz leuchten uber deinen Knecht und lehre mich deine Rechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Meine Augen fließen mit Wasser, daß man dein Gesetz nicht halt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'HERR, du bistgerecht und dein Wort ist recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Du hast die Zeugnisse deiner Gerechtigkeit und die Wahrheit hart geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Ich habe mich schierzu Tode geeifert, daß meine Widersacher deiner Worte vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Dein Wort ist wohl gelautert, und dein Knecht hat es lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Ich bin gering und verachtet, ich vergesse aber nicht deines Befehls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Deine Gerechtigkeit ist eine ewige Gerechtigkeit, und dein Gesetz ist Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Angst und Not haben mich getroffen; ich habe aber Lust an deinen Geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Die Gerechtigkeit deiner Zeugnisse ist ewig; unterweise mich, so lebe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Ich rufe von ganzem Herzen; erhore mich, HERR, daß ich deine Rechte halte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Ich rufe zu dir; hilf mir, daß ich deine Zeugnisse halte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Ich komme frühe und schreie; auf dein Wort hoffe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Ich wache frühe auf, daß ich rede von deinem Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Hore meine Stimme nach deiner Gnade; HERR, erquicke mich nach deinen Rechten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Meine boshaftigen Verfolger wollen mirzu und sind feme von deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'HERR, du bist nahe, und deine Gebote sind eitel Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Zuvor weiß ich aber, daß du deine Zeugnisse ewiglich gegrundet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Siehe mein Elend und errette mich; hilf mir aus, denn ich vergesse deines Gesetzes nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Führe meine Sache und erlose mich; erquicke mich durch dein Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Das Heil ist feme von den Gottlosen; denn sie achten deine Rechte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'HERR, deine Barmherzigkeit ist groß; erquicke mich nach deinen Rechten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Meiner Verfolger und Widersacher ist viel; ich weiche aber nicht von deinen Zeugnissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Ich sehe die Verachter, und tut mirwehe, daß sie dein Wort nicht halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Siehe, ich liebe deine Befehle; HERR, erquicke mich nach deiner Gnade!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Dein Wort ist nichts denn Wahrheit; alle Rechte deiner Gerechtigkeit wahren ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Die Fursten verfolgen mich ohne Ursache und mein Herz furchtet sich vor deinen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'ich freue mich uber dein Wort wie einer, der eine große Beute kriegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Lugen bin ich gram und habe Greuel daran; aber dein Gesetz habe ich lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Ich lobe dich des Tages siebenmal urn der Rechte willen deiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Großen Frieden haben, die dein Gesetz lieben, und werden nicht straucheln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'HERR, ich warte auf dein Heil und tue nach deinen Geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Meine Seele halt deine Zeugnisse und liebet sie fast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Ich halte deine Befehle und deine Zeugnisse; denn alle meine Wege sind vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'HERR, laß meine Klage vor, dich kommen; unterweise mich nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Laß mein Flehen vor dich kommen; errette mich nach deinem Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Meine Lippen sollen toben, wenn du mich deine Rechte lehrest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Meine Zunge soil ihrßesprach haben von deinem Wort; denn alle deine Gebote sind recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Laß mir deine Hand beistehen; denn ich habe erwahlet deine Befehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'HERR, mich verlanget nach deinem Heil und habe Lust an deinem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Laß meine Seele leben, daßsie dich lobe, und deine Rechte mir helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Ich bin wie ein verirret und verloren Schaf; suche deinen Knecht; denn ich vergesse deiner Gebote nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ein Lied im hohern Chor. Ich rufe zu dem HERRN in meiner Not, und ererhoret mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'HERR, errette meine Seele von den Lugenmaulern und von den falschen Zungen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Was kann dir die falsche Zunge tun? und was kann sie ausrichten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Sie ist wie scharfe Pfeile eines Starken, wie Feuer in Wacholdern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Wehe mir, daß ich ein Fremdling bin unter Mesech! Ich muß wohnen unter den Hütten Kedars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Es wird meiner Seele lange, zu wohnen bei denen, die den Frieden hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich halte Frieden; aber wenn ich rede, sofahen sie Krieg an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ein Lied im hohern Chor. Ich hebe meine Augen auf zu den Bergen, von welchen mir Hilfe kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Meine Hilfe kommt vom HERRN, der Himmel und Erde gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Erwird deinen Fuß nichtgleiten lassen; und der dich behutet, schlaft nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Siehe, der Hüter Israels schlaft noch schlummert nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Der HERR behutet dich; der HERR ist dein Schatten uber deiner rechten Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'daß dich des Tages die Sonne nicht steche, noch der Mond des Nachts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Der HERR behute dich vorallem Ubel; er behute deine Seele!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Der HERR behute deinen Ausgang und Eingang von nun an bis in Ewigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ein Lied Davids im hohern Chor. Ich freue mich des, das mir geredet ist, daß wir werden ins Haus des HERRN gehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'und daß unsere Füße werden stehen in deinen Toren, Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'ist gebauet, daß es eine Stadt sei, da man zusammenkommen soli,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'da die Stamme hinaufgehen sollen, namlich die Stamme des HERRN, zu predigen dem Volk Israel, zu danken dem Namen des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Denn daselbst sitzen die Stühle zum Gericht, die Stühle des Hauses David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Wünschet Jerusalem Gluck! Es müsse wohlgehen denen, die dich lieben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Es müsse Friede sein inwendig in deinen Mauern und Glück in deinen Palasten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Urn meiner Brüder und Freunde willen will ich dir Frieden wünschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Urn des Hauses willen des HERRN, unsers Gottes, will ich dein Bestes suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ein Lied im hohern Chor. Ich hebe meine Augen auf zu dir, derdu im Himmel sitzest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Siehe, wie die Augen der Knechte auf die Hande ihrer Herren sehen, wie die Augen der Magd auf die Hande ihrer Frauen, also sehen unsere Augen auf den HERRN, unsern Gott, bis er uns gnadig werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Sei uns gnadig, HERR, sei uns gnadig; denn wir sind sehr voll Verachtung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Sehr voll ist unsere Seele der Stolzen Spott und der Hoffartigen Verachtung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Ein Lied Davids im hohern Chor. Wo der HERR nicht bei uns ware, so sage Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'wo der HERR nicht bei uns ware, wenn die Menschen sich wider uns setzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'so verschlangen sie uns lebendig, wenn ihr Zorn fiber uns ergrimmete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'so ersaufte uns Wasser, Strome gingen fiber unsere Seele;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'es gingen Wasser allzu hoch fiber unsere Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Gelobet sei der HERR, daß er uns nicht gibt zum Raube in ihre Zahne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Unsere Seele ist entronnen wie ein Vogel dem Stricke des Voglers. Der Strick ist zerrissen, und wir sind los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Unsere Hilfe stehet im Namen des HERRN, der Himmel und Erde gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ein Lied im hohern Chor. Die auf den HERRN hoffen, die werden nicht fallen, sondern ewiglich bleiben wie der Berg Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Urn Jerusalem her sind Berge; und der HERR ist urn sein Volk her von nun an bis in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Denn der Gottlosen Zepter wird nicht bleiben fiber dem Hauflein der Gerechten, auf dafi die Gerechten ihre Hand nicht ausstrecken zur Ungerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'HERR, tu wohl den guten und frommen Herzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Die aber abweichen auf ihre krummen Wege, wird der HERR wegtreiben mit den Ubeltatern. Aber Friede sei fiber Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Ein Lied im hohern Chor. Wenn der HERR die Gefangenen Zions erlosen wird, so werden wir sein wie die Traumenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Dann wird unser Mund voll Lachens und unsere Zunge voll Rühmens sein. Da wird man sagen unterden Heiden: Der HERR hat Großes an ihnen getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Der HERR hat Großes an uns getan; des sind wirfrohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'HERR, wende unser Gefangnis, wie du die Wasser gegen Mittag trocknest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Die mit Tranen saen, werden mit Freuden ernten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Sie gehen hin und weinen und tragen edlen Samen und kommen mit Freuden und bringen ihre Garben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ein Lied Salomos im hohern Chor. Wo der HERR nicht das Haus bauet, so arbeiten umsonst, die dran bauen. Wo der HERR nicht die Stadt behutet, so wachet der Wachter umsonst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Es istumsonst, daß ihrfruhe aufstehet und hernach lange sitzet und esset euer Brot mit Sorgen; denn seinen Freunden gibt er\'s schlafend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Siehe, Kinder sind eine Gabe des HERRN, und Leibesfrucht ist ein Geschenk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Wie die Pfeile in der Hand eines Starken, also geraten diejungen Knaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Wohl dem, der seinen Kocher derselben voll hat! Sie werden nicht zuschanden, wenn sie mit ihren Feinden handeln im Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Ein Lied im hohern Chor. Wohl dem, der den HERRN furchtet und auf seinen Wegen gehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Du wirst dich nahren deiner Hande Arbeit; wohl dir, du hast\'s gut!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Dein Weib wird sein wie ein fruchtbarer Weinstock urn dein Haus herum, deine Kinder wie die Olzweige um deinen Tisch her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Siehe, also wird gesegnet der Mann, der den HERRN furchtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Der HERR wird dich segnen aus Zion, daß du sehest das Gluck Jerusalems dein Leben lang');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'und sehest deiner Kinder Kinder. Friede uber Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Ein Lied im hohern Chor. Sie haben mich oft gedranget von meiner Jugend auf, so sage Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'sie haben mich oft gedranget von meiner Jugend auf; aber sie haben mich nicht ubermocht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Die Pfluger haben auf meinem Rucken geackert und ihre Furchen lang gezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Der HERR, der gerecht ist, hat der Gottlosen Seile abgehauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Ach; daß müliten zuschanden werden und zurückkehren alle, die Zion gram sind!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Ach, daß sie müßten sein wie das Gras auf den Dachern, welches verdorret, ehe man es ausrauft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'von welchem der Schnitter seine Hand nicht fullet, noch der Garbenbinder seinen Arm voll,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'und die vorubergehen, nicht sprechen: Der Segen des HERRN sei uber euch; wir segnen euch im Namen des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Ein Lied im hohern Chor. Aus der Tiefe rufe ich, HERR, zu dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'HERR, hore meine Stimme; lali deine Ohren merken auf die Stimme meines Flehens!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'So du willst, HERR, Sünde zurechnen, HERR, wer wird bestehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Denn bei dir ist die Vergebung, daß man dich furchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Ich harre des HERRN; meine Seele harret, und ich hoffe auf sein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Meine Seele wartet auf den HERRN von einer Morgenwache bis zur andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israel hoffe auf den HERRN; denn bei dem HERRN ist die Gnade und viel Erlosung bei ihm;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'und erwird Israel erlosen aus alien seinen Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Ein Lied Davids im hohern Chor. HERR, mein Herz ist nicht hoffartig, und meine Augen sind nicht stolz, und wandle nicht in graven Dingen, die mir zu hoch sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Wenn ich meine Seele nicht setzte und stillete, so ward meine Seele entwohnet, wie einer von seiner Mutter entwohnet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel hoffe auf den HERRN von nun an bis in Ewigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Ein Lied im hohern Chor. Gedenke, HERR, an David und an all sein Leiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'der dem HERRN schwur und gelobte dem Machtigen Jakobs:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Ich will nicht in die Hütte meines Hauses gehen, noch mich aufs Lager meines Bettes legen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'ich will meine Augen nicht schlafen lassen, noch meine Augenlider schlummern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'bis ich eine Statte finde fur den HERRN; zur Wohnung dem Machtigen Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Siehe, wir horen von ihr in Ephratha, wir haben sie funden auf dem Felde des Waldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Wirwollen in seine Wohnung gehen und anbeten vor seinem Fußschemel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'HERR, mache dich auf zu deiner Ruhe, du und die Lade deiner Macht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Deine Priester laß, sich kleiden mit Gerechtigkeit und deine Heiligen sich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Nimm nicht weg das Regiment deines Gesaibten um deines Knechts Davids willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Der HERR hat David einen wahren Eid geschworen, davon wird er sich nicht wenden: Ich will dir auf deinen Stuhl setzen die Frucht deines Leibes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Werden deine Kinder meinen Bund halten und mein Zeugnis, das ich sie lehren werde, so sollen auch ihre Kinder auf deinem Stuhl sitzen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Denn der HERR hat Zion erwahlet und hat Lust, daselbst zu wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Dies ist meine Ruhe ewiglich, hie will ich wohnen, denn es gefallt mir wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Ich will ihre Speise segnen und ihren Armen Brots genug geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Ihre Priester will ich mit Heil kleiden, und ihre Heiligen sollen frdhlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Daselbst soil aufgehen das Horn Davids; ich habe meinem Gesaibten eine Leuchte zugerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Seine Feinde will ich mit Schanden kleiden; aber uber ihm soil bluhen seine Krone.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Ein Lied Davids im hohern Chor. Siehe, wie fein und lieblich ist\'s, daß Brüder eintrachtig beieinanderwohnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Wie der kostliche Balsam ist, dervom Haupt Aarons herabfleuüt in seinen ganzen Bart, der herabfleufit in sein Kleid,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'wie der Tau, der von Hermon herabfallt auf die Berge Zion. Denn daselbst verheilit der HERR Segen und Leben immerund ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Ein Lied im hohern Chor. Siehe, lobet den HERRN, alle Knechte des HERRN, die ihr stehet des Nachts im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Hebet eure Hande auf im Heiligtum und lobet den HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Der HERR segne dich aus Zion, der Himmel und Erde gemacht hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Lobet den Namen des HERRN, lobet, ihr Knechte des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'die ihr stehet im Hause des HERRN, in den Hdfen des Hauses unsers Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Lobet den HERRN, denn der HERR ist freundlich; lobsinget seinem Namen, denn er ist lieblich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Denn der HERR hat ihm Jakob erwahlet, Israel zu seinem Eigentum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Denn ich weili, daß der HERR groli ist und unser HERR vor alien Gottern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Alles, was er will, das tuter, im Himmel, auf Erden, im Meer und in alien Tiefen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'der die Wolken lalit aufgehen vom Ende der Erde, der die Blitze samt dem Regen macht, der den Wind aus heimlichen Ortern kommen lalit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'der die Erstgeburten schlug in Agypten, beide der Menschen und des Viehes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'und lieli seine Zeichen und Wunder kommen uber dich, Agyptenland, uber Pharao und alle seine Knechte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'der viel Vdlker schlug und totete machtige Konige,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'der Amoriter Konig, und Og, den Konig zu Basan, und alle Konigreiche in Kanaan;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'und gab ihr Land zum Erbe, zum Erbe seinem Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'HERR, dein Name wahret ewiglich; dein Gedachtnis, HERR, wahret fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Denn der HERR wird sein Volk richten und seinen Knechten gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Der Heiden Gotzen sind Silber und Gold, von Menschenhanden gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Sie haben Mauler und reden nicht; sie haben Augen und sehen nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'sie haben Ohren und horen nicht; auch ist kein Odem in ihrem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Die solche machen, sind gleich also, alle, die auf solche hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Das Haus Israel lobe den HERRN. Lobet den HERRN, ihr vom Hause Aaron;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'ihr vom Hause Levi, lobet den HERRN; die ihr den HERRN furchtet, lobet den HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Gelobet sei der HERR aus Zion, der zu Jerusalem wohnet! Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Danketdem HERRN, denn er ist freundlich; denn seine Güte wahret ewig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Danket dem Gott aller Gotter; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Danket dem HERRN aller Herren; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Der grolie Wunder tut alleine; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Der die Himmel ordentlich gemacht hat; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Der die Erde auf Wasser ausgebreitet hat; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Der grolie Lichter gemacht hat; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'die Sonne, dem Tage vorzustehen; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'den Mond und Sterne, der Nacht vorzustehen; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Der Agypten schlug an ihren Erstgeburten; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'und fuhrete Israel heraus; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'durch machtige Hand und ausgereckten Arm; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Der das Schilfmeer teilete in zwei Teile; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'und lieli Israel hindurchgehen; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Der Pharao und sein Heer ins Schilfmeer stieli; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Der sein Volk fuhrete durch die Wüste; denn seine Güte wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Der grolie Konige schlug; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'und erwürgete machtige Konige; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihon, der Amoriter Konig; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'und Og, den Konig zu Basan; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'und gab ihr Land zum Erbe; denn seine Güte wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'zum Erbe seinem Knechte Israel; denn seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Denn er dachte an uns, da wir untergedrückt waren; denn seine Gute wahret ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'und erlosete uns von unsern Feinden; denn seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Der allem Fleisch Speise gibt; denn seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Danket dem Gott vom Himmel; denn seine Gute wahret ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'An den Wassern zu Babel saften wir und weineten, wenn wir an Zion gedachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Unsere FHarfen hingen wir an die Weiden, die drinnen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Denn daselbst hieften uns singen, die uns gefangen hielten, und in unserm Heulen frohlich sein: Lieber, singet uns ein Lied von Zion!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Wie sollten wir des HERRN Lied singen in fremden Landen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Vergesse ich dein, Jerusalem, so werde meiner Rechten vergessen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Meine Zunge musse an meinem Gaumen kleben, wo ich dein nicht gedenke, wo ich nicht lasse Jerusalem meine hochste Freude sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'HERR, gedenke der Kinder Edom am Tage Jerusalems, die da sagen: Rein ab, rein ab, bis auf ihren Boden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Du verstorte Tochter Babel, wohl dem, der dir vergelte, wie du uns getan hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Wohl dem, der deine jungen Kinder nimmt und zerschmettert sie an den Stein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davids. Ich danke dir von ganzem Flerzen; vor den Gottern will ich dir lobsingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Ich will anbeten zu deinem heiligen Tempel und deinem Namen danken um deine Gute und Treue; denn du hast deinen Namen uber alles herrlich gemacht durch dein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Wenn ich dich anrufe, so erhore mich und gib meiner Seele grofte Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Es danken dir, HERR, alle Konige auf Erden, daß sie horen das Wort deines Mundes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'und singen auf den Wegen des HERRN, da(5 die Ehre des HERRN grofi sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Denn der HERR ist hoch und siehet auf das Niedrige und kennet den Stolzen von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Wenn ich mitten in der Angst wandle, so erquickest du mich und streckest deine Hand uber den Zorn meiner Feinde und hilfst mir mit deiner Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Der HERR wird\'s ein Ende machen um meinetwillen. HERR, deine Güte istewig. Das Werk deiner Hande wollest du nicht lassen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Ein Psalm Davids, vorzusingen. HERR, du erforschest mich und kennest mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ich sitze Oder stehe auf, so weiftest du es: du verstehest meine Gedanken von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Ich gehe Oder liege, so bist du um mich und siehest alle meine Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Denn siehe, es ist kein Wort auf meiner Zunge, das du, HERR, nicht ailes wissest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Du schaffest es, was ich vor Oder hernach tue, und haltst deine Hand uber mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Solche Erkenntnis ist mir zu wunderlich und zu hoch; ich kann\'s nicht begreifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Wo soil ich hingehen vor deinem Geist und wo soli ich hinfliehen vor deinem Angesicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Fuhre ich gen Himmel, so bist du da. Bettete ich mir in die Holle, siehe, so bist du auch da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Nahme ich Flügel der Morgenrote und bliebe am auftersten Meer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'so würde mich doch deine Hand daselbst fuhren und deine Rechte mich halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Sprache ich: Finsternis moge mich decken, so muft die Nacht auch Licht um mich sein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'denn auch Finsternis nicht finster ist bei dir, und die Nacht leuchtet wie der Tag, Finsternis ist wie das Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Denn du hast meine Nieren in deiner Gewalt, du warest uber mir in Mutterleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Ich danke dir daruber, daß ich wunderbarlich gemacht bin; wunderbarlich sind deine Werke, und das erkennet meine Seele wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Es war dir mein Gebein nicht verhohlen, da ich im Verborgenen gemacht ward, da ich gebildet ward unten in der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Deine Augen sahen mich, da ich noch unbereitet war, und waren alle Tage auf dein Buch geschrieben, die noch werden sollten, und derselben keiner da war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Aberwie kostlich sind vor mir, Gott, deine Gedanken! Wie ist ihrer so eine grofte Summa!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Sollt ich sie zahlen, so würde ihrer mehr sein denn des Sandes. Wenn ich aufwache, bin ich noch bei dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Ach, Gott, daß du totetest die Gottlosen, und die Blutgierigen von mirweichen muftten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Denn sie reden von dir lasterlich, und deine Feinde erheben sich ohne Ursache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Ich hasse ja, HERR, die dich hassen, und verdreuftt mich auf sie, daß sie sich wider dich setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Ich hasse sie in rechtem Ernst; darum sind sie mirfeind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Erforsche mich, Gott, und erfahre mein Herz; prufe mich und erfahre, wie ich\'s meine;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'und siehe, ob ich auf bosem Wege bin, und leite mich auf ewigem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Ein Psalm Davids, vorzusingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Errette mich, HERR, von den bosen Menschen; behüte mich vor den freveln Leuten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'die Boses gedenken in ihrem Herzen und taglich Krieg erregen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Sie scharfen ihre Zunge wie eine Schlange; Otterngift ist unter ihren Lippen. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Bewahre mich, HERR, vorder Hand der Gottlosen; behüte mich vor den freveln Leuten, die meinen Gang gedenken umzustoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Die Hoffartigen legen mir Stricke und breiten mir Seile aus zum Netz und stellen mir Fallen an den Weg. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ich aber sage zum HERRN: Du bist mein Gott; HERR, vernimm die Stimme meines Flehens!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'HERR Herr, meine starke Hilfe, du beschirmest mein Haupt zur Zeit des Streits.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'HERR, laft dem Gottlosen seine Begierde nicht; starke seinen Mutwillen nicht; sie mochten sich\'s erheben. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Das Ungluck, davon meine Feinde ratschlagen, müsse auf ihren Kopf fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Erwird Strahlen über sie schütten; erwird sie mit Feuer tief in die Erde schlagen, daß sie nimmer nicht aufstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Ein boses Maul wird kein Gluck haben auf Erden; ein frevelboser Mensch wird verjagt und gestürzt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Denn ich weift, dafi der HERR wird des Elenden Sache und der Armen Recht ausfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, 'Auch werden die Gerechten deinem Namen danken, und die Frommen werden vor deinem Angesichte bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Ein Psalm Davids. HERR, ich rufe zu dir; eile zu mir, vernimm meine Stimme, wenn ich dich anrufe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Mein Gebet müsse vor dir taugen wie ein Rauchopfer, mein Handeaufheben wie ein Abendopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'HERR, behute meinen Mund und bewahre meine Lippen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Neige mein Herz nicht auf etwas Boses, ein gottlos Wesen zu führen mit den Ubeltatern, dafi ich nicht esse von dem, das ihnen geliebt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Der Gerechte schlage mich freundlich und strafe mich; das wird mir so wohl tun als ein Balsam auf meinem Haupt. Denn ich bete stets, daß sie mir nicht Schaden tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Ihre Lehrer müssen gesturzt werden über einen Fels; so wird man denn meine Lehre horen, daß sie lieblich sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Unsere Gebeine sind zerstreuet bis zur Holle, wie einer das Land zerreiftt und zerwuhlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Denn auf dich, HERR Herr, sehen meine Augen; ich traue auf dich; verstofte meine Seele nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Bewahre mich vor dem Stricke, den sie mir gelegt haben, und vor der Falle der Ubeltater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Die Gottlosen mussen in ihr eigen Netz fallen miteinander, ich aber immervorübergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Eine Unterweisung Davids zu beten, da er in der Hohle war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Ich schreie zum HERRN mit meiner Stimme; ich flehe dem HERRN mit meiner Stimme;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'ich schutte meine Rede vor ihm aus und zeige an vor ihm meine Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Wenn mein Geist in Angsten ist, so nimmst du dich meiner an. Sie legen mir Stricke auf dem Wege, da ich auf gehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Schaue zur Rechten, und siehe, da will mich niemand kennen. Ich kann nicht entfliehen; niemand nimmt sich meiner Seele an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'HERR, zu dir schreie ich und sage: Du bist meine Zuversicht, mein Teil im Lande der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Merke auf meine Klage, denn ich werde sehr geplagt; errette mich von meinen Verfolgern, denn sie sind mirzu machtig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, 'Führe meine Seele aus dem Kerker, daß ich danke deinem Namen. Die Gerechten werden sich zu mirsammeln, wenn du mirwohltust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Ein Psalm Davids. HERR, erhore mein Gebet; vernimm mein Flehen urn deiner Wahrheit willen, erhore mich urn deiner Gerechtigkeit willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Und gehe nicht ins Gericht mit deinem Knechte; denn vor dir ist kein Lebendiger gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Denn der Feind verfolget meine Seele und zerschlagt mein Leben zu Boden; er legt mich ins Finstere, wie die Toten in der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Und mein Geist ist in mir geangstet; mein Herz ist mir in meinem Leibe verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Ich gedenke an die vorigen Zeiten; ich rede von alien deinen Taten und sage von den Werken deiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Ich breite meine Hande aus zu dir; meine Seele durstet nach dir wie ein dürres Land. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'HERR, erhore mich bald, mein Geist vergehet; verbirg dein Antlitz nicht von mir, daß ich nicht gleich werde denen, die in die Grube fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Laß mich frühe horen deine Gnade; denn ich hoffe auf dich. Tu mir kund den Weg, darauf ich gehen soil; denn mich verlanget nach dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Errette mich, mein Gott, von meinen Feinden; zu dir hab ich Zuflucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lehre mich tun nach deinem Wohlgefallen, denn du bist mein Gott; dein guter Geist führe mich auf ebener Bahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'HERR, erquicke mich urn deines Namens willen führe meine Seele aus der Not um deiner Gerechtigkeit willen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'und verstore meine Feinde um deiner Güte willen und bringe um alle, die meine Seele angsten; denn ich bin dein Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Ein Psalm Davids. Gelobet sei der HERR, mein Hort, der meine Hande lehret streiten und meine Fauste kriegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'meine Güte und meine Burg, mein Schutz und mein Erretter, mein Schild, auf den ich traue, der mein Volk unter mich zwinget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'HERR, was istder Mensch, dafi du dich sein so annimmst, und des Menschen Kind, daß du ihn so achtest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, '1st doch der Mensch gleichwie nichts; seine Zeit fahret dahin wie ein Schatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'HERR, neige deine Himmel und fahre herab; taste die Berge an, daß sie rauchen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Laß blitzen und zerstreue sie; schiefie deine Strahlen und schrecke sie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Sende deine Hand von der Hohe und erlose mich und errette mich von großen Wassern, von der Hand derfremden Kinder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'welcher Lehre ist kein nutze, und ihre Werke sind falsch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Gott, ich will direin neues Lied singen; ich will dir spielen auf dem Psalter von zehn Saiten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'der du den Konigen Sieg gibst und erlosest deinen Knecht David vom morderischen Schwert des Bosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Erlose mich auch und errette mich von der Hand der fremden Kinder, welcher Lehre ist kein nutze, und ihre Werke sind falsch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'daß unsere Sohne aufwachsen in ihrer Jugend wie die Pflanzen und unsere Tochterwie die ausgehauenen Erker, gleichwie die Palaste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'und unsere Kammern voll seien, die herausgeben konnen einen Vorrat nach dem andern; daß unsere Schafe tragen tausend und hunderttausend auf unsern Dorfern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'daß unsere Ochsen viel erarbeiten; daß kein Schade, kein Verlust noch Klage auf unsern Gassen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Wohl dem Volk, dem es also gehet! Aber wohl dem Volk, des der HERR ein Gott ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Ein Lob Davids. Ich will dich erhohen, mein Gott, du Konig, und deinen Namen loben immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Ich will dich taglich loben und deinen Namen ruhmen immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Der HERR ist groß und sehr loblich, und seine Große ist unaussprechlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Kindeskinder werden deine Werke preisen und von deiner Gewalt sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Ich will reden von deiner herrlichen, schonen Pracht und von deinen Wundern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'daß man solle reden von deinen herrlichen Taten und daß man erzahle deine Herrlichkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'daß man preise deine große Güte und deine Gerechtigkeit ruhme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gnadig und barmherzig ist der HERR, geduldig und von großer Güte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Der HERR ist alien gütig und erbarmet sich aller seiner Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Es sollen dir danken, HERR, alle deine Werke, und deine Heiligen dich loben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'und die Ehre deines Konigreichs ruhmen und von deiner Gewalt reden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'daß den Menschenkindern deine Gewalt kund werde und die ehrliche Pracht deines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ein ewiges Reich, und deine Herrschaft wahret fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Der HERR erhalt alle, die da fallen, und richtet auf alle, die niedergeschlagen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Aller Augen warten auf dich, und du gibst ihnen ihre Speise zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du tust deine Hand auf und erfüllest alles, was lebet, mit Wohlgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Der HERR ist gerecht in alien seinen Wegen und heilig in alien seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Der HERR ist nahe alien, die ihn anrufen, alien, die ihn mit Ernst anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Ertut, was die Gottesfu rchtige n begehren, und horet ihrßchreien und hilft ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Der HERR behutet alle, die ihn lieben, und wird vertilgen alle Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Mein Mund soil des HERRN Lob sagen, und alles Fleisch lobe seinen heiligen Namen immer und ewiglich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Lobe den HERRN, meine Seele!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Ich will den HERRN loben, so lange ich lebe, und meinem Gott lobsingen, weil ich hie bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Verlasset euch nicht auf Fursten; sie sind Menschen, die konnen ja nicht helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Denn des Menschen Geist muß davon, und er muß wieder zu Erde werden; alsdann sind verloren alle seine Anschlage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Wohl dem, des Hilfe der Gott Jakobs ist, des Hoffnung auf dem HERRN, seinem Gott, stehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'der Himmel, Erde, Meer und alles, was drinnen ist, gemacht hat; der Glauben halt ewiglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'der Recht schaffet denen, so Gewalt leiden; der die Hungrigen speiset. Der HERR loset die Gefangenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Der HERR macht die Blinden sehend. Der HERR richtet auf, die niedergeschlagen sind. Der HERR liebet die Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Der HERR behutet Fremdlinge und Waisen und erhalt die Witwen; und kehret zuruck den Weg der Gottlosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Der HERR ist Konig ewiglich, dein Gott, Zion, fur und fur. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Lobet den HERRN; denn unsern Gott loben, das ist ein kostlich Ding; solch Lob ist lieblich und schon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Der HERR bauet Jerusalem und bringet zusammen die Verjagten in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Er heilet, die zerbrochenes Herzens sind, und verbindet ihre Schmerzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Er zahlet die Sterne und nennet sie alle mit Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Unser HERR ist graft und von grafter Kraft; und ist unbegreiflich, wie er regieret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Der HERR richtet auf die Elenden und stoftet die Gottlosen zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Singet umeinander dem HERRN mit Dank und lobet unsern Gott mit Harfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'der den Himmel mit Wolken bedeckt und gibt Regen auf Erden; der Gras auf Bergen wachsen laftt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'der dem Vieh sein Futtergibt, den jungen Raben, die ihn anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Er hat nicht Lust an der Starke des Rosses noch Gefallen an jemandes Beinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Der HERR hat Gefallen an denen, die ihn furchten, die auf seine Güte hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Praise, Jerusalem, den HERRN; lobe, Zion, deinen Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Denn er macht fest die Riegel deiner Tore und segnet deine Kinder drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Er schaffet deinen Grenzen Frieden und sattiget dich mit dem besten Weizen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Er sendet seine Rede auf Erden; sein Wort lauft schnell.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Ergibt Schnee wie Wolle, er streuet Reifwie Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Er wirft seine Schloften wie Bissen; wer kann bleiben vor seinem Frost?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Erspricht, so zerschmilzt es; er laftt seinen Wind wehen, so tauet\'s auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Er zeiget Jakob sein Wort, Israel seine Sitten und Rechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'So tut er keinen Heiden, noch laftt sie wissen seine Rechte. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Lobet, ihr Himmel, den HERRN; lobet ihn in der Hohe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lobet ihn, alle seine Engel; lobet ihn, all sein Heer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lobet ihn, Sonne und Mond; lobet ihn, alle leuchtenden Sterne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lobet ihn, ihr Himmel allenthalben, und die Wasser, die oben am Himmel sind!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Die sollen loben den Namen des HERRN; denn er gebeut, so wird\'s geschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Er halt sie immer und ewiglich; er ordnet sie, daß sie nicht anders gehen müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lobet den HERRN auf Erden, ihr Walfische und alle Tiefen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Feuer, Hagel, Schnee und Dampf, Sturmwinde, die sein Wort ausrichten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Berge und alle Hügel, fruchtbare Baume und alle Zedern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Tier und alles Vieh, Gewürm und Vogel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'ihr Konige auf Erden und alle Leute, Fursten und alle Richter auf Erden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Junglinge und Jungfrauen, Alte mit den Jungen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'sollen loben den Namen des HERRN; denn sein Name allein ist hoch; sein Lob gehet, soweit Himmel und Erde ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Und ererhohet das Horn seines Volks. Alle seine Heiligen sollen loben, die Kinder Israel, das Volk, das ihm dienet, Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Singet dem HERRN ein neues Lied! Die Gemeine der Heiligen soil ihn loben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israel freue sich des, der ihn gemacht hat; die Kinder Zion seien frohlich, uber ihrem Konige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Sie sollen loben seinen Namen im Reigen, mit Pauken und Harfen sollen sie ihm spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Denn der HERR hat Wohlgefallen an seinem Volk; er hilft den Elenden herrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Die Heiligen sollen frohlich sein und preisen und rühmen auf ihren Lagern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Ihr Mund soli Gott erhohen, und sollen scharfe Schwerter in ihren Handen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'daß sie Rache üben unterden Heiden, Strafe unter den Volkern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'ihre Konige zu binden mit Ketten und ihre Edlen mit eisernen Fesseln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'daß sie ihnen tun das Recht, davon geschrieben ist. Solche Ehre werden alle seine Heiligen haben. Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Lobet den HERRN in seinem Heiligtum; lobet ihn in der Feste seiner Macht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lobet ihn in seinen Taten; lobet ihn in seiner groften Herrlichkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lobet ihn mit Posaunen; lobet ihn mit Psalter und Harfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lobet ihn mit Pauken und Reigen; lobet ihn mit Saiten und Pfeifen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lobet ihn mit hellen Zimbeln; lobet ihn mit wohlklingenden Zimbeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Alles, was Odem hat, lobe den HERRN! Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Dies sind die Sprüche Salomos, des Konigs Israels, Davids Sohns,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'zu lernen Weisheit und Zucht, Verstand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Klugheit, Gerechtigkeit, Recht und Schlecht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'daß die Albernen witzig und die Jünglinge vernunftig und vorsichtig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Wer weise ist, der horet zu und bessert sich; und wer verstandig ist, der laftt ihm raten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'daß ervernehme die Sprüche und ihre Deutung, die Lehre der Weisen und ihre Beispiele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Des HERRN Furcht ist Anfang zu lernen. Die Ruchlosen verachten Weisheit und Zucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Mein Kind gehorche der Zucht deines Vaters und verlaft nicht das Gebot deiner Mutter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Denn solches ist ein schoner Schmuck deinem Haupt und eine Kette an deinem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Mein Kind, wenn dich die bosen Buben locken, so folge nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Wenn sie sagen: Gehe mit uns, wir wollen auf Blut lauern und den Unschuldigen ohne Ursache nachstellen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'wir wollen sie lebendig verschlingen wie die Holle, und die Frommen, als die hinunter in die Grube fahren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'wir wollen graft Gutfinden; wir wollen unsere Hauser mit Raube füllen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'wage es mit uns; es soil unser aller ein Beutel sein:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'mein Kind, wandle den Weg nicht mit ihnen; wehre deinem Fuft von ihrem Pfad!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Denn ihre Fufte laufen zum Bosen und eilen, Blut zu vergieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Denn es ist vergeblich, das Netz auswerfen vor den Augen der Vogel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Auch lauern sie selbst untereinander auf ihr Blut, und stellet einer dem andern nach dem Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Also tun alle Geizigen, daß einer dem andern das Leben nimmt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Die Weisheit klagt drauften und laftt sich horen auf den Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Sie ruft in der Tur am Tor vorne unter dem Volk; sie redet ihre Worte in der Stadt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Wie lange wollt ihr Albernen albern sein und die Spotter Lust zu Spotterei haben und die Ruchlosen die Lehre hassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Kehret euch zu meiner Strafe! Siehe, ich will euch heraussagen meinen Geist und euch meine Worte kundtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Weil ich denn rufe, und ihr weigert euch; ich recke meine Hand aus, und niemand achtet drauf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'und laftt fahren alien meinen Rat und wollt meiner Strafe nicht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'so will ich auch lachen in eurem Unfall und euer spotten, wenn da kommt, das ihr furchtet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'wenn uber euch kommtwie ein Sturm, das ihr fürchtet, und euer Unfall als ein Wetter, wenn uber euch Angst und Not kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Dann werden sie mir rufen, aber ich werde nicht antworten; sie werden mich fruhe suchen und nicht finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Darum dafi sie hasseten die Lehre und wollten des HERRN Furcht nicht haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'wollten meines Rats nicht und lasterten alle meine Strafe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'so sollen sie essen von den Fruchten ihres Wesens und ihres Rats satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Das die Albernen gelustet, totetsie, und der Ruchlosen Gluck bringt sie um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Wer aber mir gehorchet, wird sicher bleiben und genug haben und kein Ungluck furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Mein Kind, willst du meine Rede annehmen und meine Gebote bei dir behalten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'so laft dein Ohr auf Weisheit achthaben und neige dein Herz mit Fleifi dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Denn so du mit Fleifi danach rufest und darum betest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'so du sie suchest wie Silber und forschest sie wie die Schatze,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'alsdann wirst du die Furcht des FIERRN vernehmen und Gottes Erkenntnis finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Denn der HERR gibt Weisheit, und aus seinem Munde kommt Erkenntnis und Verstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Er last\'s den Aufrichtigen gelingen und beschirmet die Frommen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'und behutet die, so recht tun, und bewahret den Weg seiner Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Dann wirst du verstehen Gerechtigkeit und Recht und Frommigkeit und alien guten Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Wo die Weisheit dir zu Herzen gehet, dafi du gerne lernest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'so wird dich guter Rat bewahren und Verstand wird dich behuten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'daß du nicht geratest auf den Weg der Bosen noch unter die verkehrten Schwatzer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'die da verlassen die rechte Bahn und gehen finstere Wege,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'die sich freuen, Boses zu tun, und sind frohlich in ihrem bosen, verkehrten Wesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'welche ihren Weg verkehren und folgen ihrem Abwege;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'daß du nicht geratest an eines andern Weib, und die nicht dein ist, die glatte Worte gibt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'und verlafttden Herrn ihrer Jugend und vergisset den Bund ihres Gottes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'denn ihr Haus neigetsich zum Tode und ihre Gange zu den Verlornen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'alle, die zu ihr eingehen, kommen nicht wieder und ergreifen den Weg des Lebens nicht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'auf daß du wandelst auf gutem Wege und bleibest auf der rechten Bahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Denn die Gerechten werden im Lande wohnen, und die Frommen werden drinnen bleiben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'aber die Gottlosen werden aus dem Lande gerottet, und die Verachter werden draus vertilget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Mein Kind, vergift meines Gesetzes nicht, und dein Herz behalte meine Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Denn sie werden dir langes Leben und gute Jahre und Frieden bringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Gnade und Treue werden dich nicht lassen. Hange sie an deinen Hals und schreibe sie in die Tafel deines Herzens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'so wirst du Gunst und Klugheit finden, die Gott und Menschen gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Verlaft dich auf den HERRN von ganzem Herzen und verlaft dich nicht auf deinen Verstand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'sondern gedenke an ihn in alien deinen Wegen, so wird er dich recht fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Dunke dich nicht weise zu sein, sondern furchte den HERRN und weiche vom Bosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Das wird deinem Nabel gesund sein und deine Gebeine erquicken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Ehre den HERRN von deinem Gut und von den Erstlingen all deines Einkommens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'so werden deine Scheunen voll werden und deine Kelter mit Most ubergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Mein Kind, verwirf die Zucht des HERRN nicht und sei nicht ungeduldig uber seiner Strafe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Denn welchen der HERR liebet, den straft er, und hat Wohlgefallen an ihm wie ein Vater am Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Wohl dem Menschen, der Weisheit findet, und dem Menschen, der Verstand bekommt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Denn es ist besser, um sie hantieren, weder um Silber, und ihr Einkommen ist besser denn Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Sie ist edler denn Perlen; und alles, was du wünschen magst, ist ihr nicht zu gleichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Langes Leben istzu ihrer rechten Hand; zu ihrer Linken ist Reichtum und Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Ihre Wege sind liebliche Wege, und alle ihre Steige sind Friede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Sie ist ein Baum des Lebens alien, die sie ergreifen; und selig sind, die sie halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Denn der HERR hat die Erde durch Weisheit gegrundet und durch seinen Rat die Himmel bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Durch seine Weisheit sind die Tiefen zerteilet und die Wolken mit Tau triefend gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Mein Kind, laft sie nicht von deinen Augen weichen, so wirst du gluckselig und klug werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Das wird deiner Seele Leben sein, und dein Mund wird holdselig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Dann wirst du sicher wandeln auf deinem Wege, daß dein Fuft sich nicht stoften wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Legest du dich, so wirst du dich nicht furchten, sondern süft schlafen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'daß du dich nicht furchten darfst vor plotzlichem Schrecken noch vor dem Sturm der Gottlosen, wenn er kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Denn der HERR ist dein Trotz; der behutet deinen Fuß, daß er nicht gefangen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Weigere dich nicht, dem Durftigen Gutes zu tun, so deine Hand von Gott hat, solches zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Sprich nicht zu deinem Freunde: Gehe hin und komm wieder, morgen will ich dir geben, so du es doch wohl hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Trachte nicht Boses wider deinen Freund, der auf Treue bei dirwohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Hadre nicht mit jemand ohne Ursache, so er dir kein Leid getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Eifre nicht einem Freveln nach und erwahle seiner Wege keinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Denn der HERR hat Greuel an dem Abtrunnigen und sein Geheimnis ist bei den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Im Hause des Gottlosen ist der Fluch des HERRN; aber das Haus der Gerechten wird gesegnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Er wird der Spotter spotten; aber den Elenden wird er Gnade geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Die Weisen werden Ehre erben; aber wenn die Narren hoch kommen, werden sie doch zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Horet, meine Kinder, die Zucht eures Vaters; merkt auf, daß ihr lernet und klug werdet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Denn ich gebe euch eine gute Lehre; veriasset mein Gesetz nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Denn ich war meines Vaters Sohn, ein zarter und ein einiger vor meiner Mutter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'und er lehrete mich und sprach: Laß dein Herz meine Worte aufnehmen; halte meine Gebote, sowirst du leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Nimm an Weisheit, nimm an Verstand; vergiß nicht und weiche nicht von der Rede meines Mundes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Verlaß sie nicht, so wird sie dich behalten; liebe sie, so wird sie dich behuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Denn der Weisheit Anfang ist, wenn man sie gerne horet und die Klugheit lieber hat denn alle Güter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Achte sie hoch, so wird sie dich erhohen und wird dich zu Ehren machen, wo du sie herzest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Sie wird dein Haupt schon schmucken und wird dich zieren mit einer hubschen Krone.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'So hore, mein Kind, und nimm an meine Rede, so werden deiner Jahre viel werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Ich will dich den Weg der Weisheit fuhren, ich will dich auf rechter Bahn leiten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'daß, wenn du gehest, dein Gang dir nicht sauer werde, und wenn du laufst, daß du dich nicht anstoßest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Fasse die Zucht, laß nicht davon; bewahre sie, denn sie ist dein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Komm nicht auf der Gottlosen Pfad und tritt nicht auf den Weg der Bosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Laß ihn fahren und gehe nicht drinnen; weiche von ihm und gehe voruber!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Denn sie schlafen nicht, sie haben denn ubel getan; und sie ruhen nicht, sie haben denn Schaden getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Denn sie nahren sich von gottlosem Brot und trinken vom Wein des Frevels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Aber der Gerechten Pfad glanzet wie ein Licht, das dafortgeht, und leuchtet bis auf den vollen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Der Gottlosen Weg aber ist wie Dunkel und wissen nicht, wo sie fallen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Mein Sohn, merke auf mein Wort und neige dein Ohr zu meiner Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Laß sie nicht von deinen Augen fahren; behalte sie in deinem Herzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Denn sie sind das Leben denen, die sie finden, und gesund ihrem ganzen Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Behute dein Herz mit allem Fleiß; denn daraus gehet das Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Tu von dir den verkehrten Mund und laß das Lastermaul feme von dir sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Laß deine Augen stracks vor sich sehen und deine Augenlider richtig vor dir hinsehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Laß deinen Fuß gleich vor sich gehen, so gehest du gewiß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Wanke weder zur Rechten noch zur Linken; wende deinen Fuß vom Bosen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Mein Kind, merke auf meine Weisheit; neige dein Ohr zu meiner Lehre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'daß du behaltest guten Rat und dein Mund wisse Unterschied zu haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Denn die Lippen der Hure sind süß wie Honigseim, und ihre Kehle ist glatter denn 01,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'aber hernach bitter wie Wermut und scharf wie ein zweischneidig Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ihre Füße laufen zum Tod hinunter, ihre Gange erlangen die Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Sie gehet nicht stracks auf dem Wege des Lebens; unstet sind ihre Tritte, daß sie nicht weiß, wo sie gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'So gehorchet mir nun, meine Kinder, und weichet nicht von der Rede meines Mundes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Laß deine Wege feme von ihr sein und nahe nicht zur Tur ihres Hauses,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'daß du nicht den Fremden gebest deine Ehre und deine Jahre dem Grausamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'daß sich nicht Fremde von deinem Vermogen sattigen, und deine Arbeit nicht sei in eines andern Haus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'und mussest hernach seufzen, wenn du dein Leib und Gut verzehret hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'und sprechen: Ach, wie habe ich die Zucht gehasset, und mein Herz die Strafe verschmahet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'und habe nicht gehorchet der Stimme meiner Lehrer und mein Ohr nicht geneigt zu denen, die mich lehreten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Ich bin schier in all Ungluck kommen vor alien Leuten und allem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Trinke Wasser aus deiner Grube und Flusse aus deinem Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'La(3> deine Brunnen herausfließen und die Wasserbache auf die Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Habe du aber sie alleine und kein Fremder mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Dein Born sei gesegnet, und freue dich des Weibes deiner Jugend!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Sie ist lieblich wie eine Hindin und holdselig wie ein Reh. Laß dich ihre Liebe allezeit sattigen, und ergotze dich allewege in ihrer Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Mein Kind, warum willst du dich an der Fremden ergotzen und herzest dich mit einer andern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Denn jedermanns Wege sind stracks vor dem HERRN, und er misset gleich alle ihre Gange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Die Missetat des Gottlosen wird ihn fahen, und er wird mit dem Strick seiner Sunde gehalten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Er wird sterben, dati er sich nicht will ziehen lassen, und urn seiner großen Torheit willen wird\'s ihm nicht wohlgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Mein Kind, wirst du Burge fur deinen Nachsten und hast deine Hand bei einem Fremden verhaftet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'so bist du verknupft mit der Rede deines Mundes und gefangen mit den Reden deines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'So tu doch, mein Kind, also und errette dich; denn du bist deinem Nachsten in die Hande kommen; eile, drange und treibe deinen Nachsten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Laß deine Augen nicht schlafen noch deine Augenlider schlummern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Errette dich wie ein Reh von der Hand und wie ein Vogel aus der Hand des Voglers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Gehe hin zur Ameise, du Fauler, siehe ihre Weise an und lerne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Ob sie wohl keinen Fursten noch Hauptmann noch Herrn hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'bereitet sie doch ihr Brot im Sommer und sammeit ihre Speise in der Ernte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Wie lange, liegst du, Fauler? Wann willst du aufstehen von deinem Schlaf?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Ja, schlaf noch ein wenig, schlummere ein wenig, schlage die Hande ineinanderein wenig, daß du schlafest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'so wird dich die Armut ubereilen wie ein Fußganger und der Mangel wie ein gewappneter Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Ein loser Mensch, ein schadlicher Mann, gehet mit verkehrtem Munde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'winket mit Augen, deutet mit Fußen, zeiget mit Fingern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'trachtet allezeit Boses und Verkehrtes in seinem Herzen und richtet Hader an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Darum wird ihm plotzlich sein Unfall kommen und wird schnell zerbrochen werden, daß keine Hilfe da sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Diese sechs Stücke hasset der HERR, und am siebenten hat ereinen Greuel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'hohe Augen, falsche Zungen, Hande, die unschuldig Blutvergießen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Herz, das mit bosen Tucken umgehet; Fuße, die behende sind, Schaden zu tun;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'falscher Zeuge, derfrech Lugen redet, und der Hader zwischen Brudern anrichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Mein Kind, bewahre die Gebote deines Vaters und laß nicht fahren das Gesetz deiner Mutter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Binde sie zusammen auf dein Herz allewege und hange sie an deinen Hals:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'wenn du gehest, daß sie dich geleiten; wenn du dich legest, daß sie dich bewahren; wenn du aufwachest, dafi sie dein Gesprach seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Denn das Gebot ist eine Leuchte und das Gesetz ein Licht; und die Strafe der Zucht ist ein Weg des Lebens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'auf daß du bewahret werdest vor dem bosen Weibe, vor der glatten Zunge der Fremden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Lafi dich ihre Schone nicht gelusten in deinem Herzen und verfahe dich nicht an ihren Augenlidern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Denn eine Hure bringet einen urns Brot; aber ein Eheweib fahet das edle Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Kann auch jemand ein Feuer im Busen behalten, daß seine Kleider nicht brennen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Wie sollte jemand auf Kohlen gehen, daß seine Fuße nicht verbrannt wurden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Also gehet es, wer zu seines Nachsten Weib gehet; es bleibt keiner ungestraft, der sie beruhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Es ist einem Diebe nicht so große Schmach, ob er stiehlt, seine Seele zu sattigen, weil ihn hungert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Und ob er begriffen wird, gibt er\'s siebenfaltig wieder und legt dar alles Gut in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Aber der mit einem Weibe die Ehe bricht, der ist ein Narr, der bringet sein Leben ins Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Dazu trifft ihn Plage und Schande, und seine Schande wird nicht ausgetilget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Denn der Grimm des Mannes eifert und schonet nicht zur Zeit der Rache');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'und siehet keine Person an, die da versohne, und nimmt\'s nicht an, ob du viel schenken wolltest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Mein Kind, behalte meine Rede und verbirg meine Gebote bei dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Behalte meine Gebote, so wirst du leben, und mein Gesetz wie deinen Augapfel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Binde sie an deine Finger, schreibe sie auf die Tafel deines Herzens!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sprich zur Weisheit: Du bist meine Schwester, und nenne die Klugheit deine Freundin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'daß du behutet werdest vor dem fremden Weibe, vor einer andern, die glatte Worte gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Denn am Fenster meines Hauses guckte ich durchs Gitter und sah unter den Albernen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'und ward gewahr unter den Kindern eines narrischen Junglings,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'der ging auf der Gasse an einer Ecke und trat daher auf dem Wege an ihrem Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'in der Dammerung, am Abend des Tages, da es Nacht ward und dunkel war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Und siehe, da begegnete ihm ein Weib im Hurenschmuck, listig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'wild und unbandig, daß ihre Fuße in ihrem Hause nicht bleiben konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Jetzt ist sie draulien, jetzt auf der Gasse und lauert an alien Ecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Und erwischte ihn und kussete ihn unverschamt und sprach zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Ich habe Dankopfer fur mich heute bezahlet, fur meine Geiubde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Darum bin ich herausgegangen, dirzu begegnen, dein Angesicht fruhe zu suchen, und habe dich funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Ich habe mein Bett schon geschmückt mit bunten Teppichen aus Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Ich habe mein Lager mit Myrrhen, Aloes und Zinnamen besprengt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Komm, lali uns genug buhlen bis an den Morgen und lali uns der Liebe pflegen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'denn der Mann ist nicht daheim, er isteinen fernen Weg gezogen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'er hat den Geldsack mit sich genommen; er wird erst aufs Fest wieder heimkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Sie uberredete ihn mit vielen Worten und gewann ihn ein mit ihrem glatten Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Er folgte ihr bald nach; wie ein Ochs zur Fleischbank gefuhrt wird, und wie zur Fessel, da man die Narren zuchtiget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'bis sie ihm mit dem Pfeil die Leber spaltete, wie ein Vogel zum Strick eilet und weili nicht, daß ihm das Leben gilt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'So gehorchet mir nun, meine Kinder, und merket auf die Rede meines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Lali dein Herz nicht weichen auf ihren Weg und lali dich nicht verführen auf ihre Bahn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Denn sie hat viele verwundet und gefallet, und sind allerlei Machtige von ihr erwurget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Ihr Haus sind Wege zur Holle, da man hinunterfahrt in des Todes Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Rufet nicht die Weisheit und die Klugheit lalit sich horen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Offentlich am Wege und an der Strafie stehet sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'An den Toren bei der Stadt, da man zur Tür eingehet, schreiet sie:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'O ihr Manner, ich schreie zu euch und rufe den Leuten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Merket, ihr Albernen, den Witz; und ihr Toren, nehmet es zu Herzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Horet, denn ich will reden, was furstlich ist, und lehren, was recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Denn mein Mund soil die Wahrheit reden, und meine Lippen sollen hassen, das gottios ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Alle Reden meines Mundes sind gerecht; es ist nichts Verkehrtes noch Falsches drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Sie sind alle gleichaus denen, die sie vernehmen, und richtig denen, die es annehmen wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Nehmet an meine Zucht lieber denn Silber und die Lehre achtet hoher denn kostlich Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Denn Weisheit ist besser denn Perlen, und alles, was man wunschen mag, kann ihr nicht gleichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ich, Weisheit, wohne bei dem Witz und ich weili guten Rat zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Die Furcht des HERRN hasset das Arge, die Hoffart, den Hochmut und bosen Weg, und bin feind dem verkehrten Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Mein ist beides, Rat und Tat; ich habe Verstand und Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Durch mich regieren die Konige und die Ratsherren setzen das Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Durch mich herrschen die Fürsten und alle Regenten auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ich liebe, die mich lieben; und die mich fruhe suchen, finden mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Reichtum und Ehre ist bei mir, wahrhaftig Gut und Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Meine Frucht ist besser denn Gold und fein Gold und mein Einkommen besser denn auserlesen Silber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Ich wandle auf dem rechten Wege, auf der Stralie des Rechts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'daß ich wohl berate, die mich lieben und ihre Schatze voll mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Der HERR hat mich gehabt im Anfang seiner Wege; ehe erwas machte, war ich da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Ich bin eingesetzt von Ewigkeit, von Anfang vor der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Da die Tiefen noch nicht waren, da war ich schon bereitet, da die Brunnen noch nicht mit Wasser quollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Ehe denn die Berge eingesenkt waren, vor den Hügeln war ich bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Er hatte die Erde noch nicht gemacht, und was dran ist, noch die Berge des Erdbodens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Da er die Himmel bereitete, war ich daselbst; da er die Tiefe mit seinem Ziel verfassete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'da er die Wolken droben festete, da er festigte die Brunnen der Tiefe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'da er dem Meer das Ziel setzte und den Wassern, daß sie nicht ubergehen seinen Befehl, da er den Grund der Erde legte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'da war ich der Werkmeister bei ihm und hatte meine Lust taglich und spielte vor ihm allezeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'und spielte auf seinem Erdboden; und meine Lust ist bei den Menschenkindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'So gehorchet mir nun, meine Kinder! Wohl denen, die meine Wege behalten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Horet die Zucht und werdet weise, und lalit sie nicht fahren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Wohl dem Menschen, der mir gehorchet, daß er wache an meiner Tur taglich, daß er warte an den Pfosten meiner Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Wer mich findet, der findet das Leben und wird Wohlgefailen vom HERRN bekommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Wer aber an mir sundiget, der verletzt seine Seele. Alle, die mich hassen, lieben den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Die Weisheit bauete ihr Haus und hieb sieben Saulen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'schlachtete ihr Vieh und trug ihren Wein auf und bereitete ihren Tisch');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'und sandte ihre Dirnen aus, zu laden oben auf die Palaste der Stadt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Wer albern ist, der mache sich hieher! Und zum Narren sprach sie:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Kommt, zehret von meinem Brot und trinket des Weins, den ich schenke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Verlasset das alberne Wesen, so werdet ihr leben; und gehet auf dem Wege des Verstandes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Wer den Spotter züchtiget, der muß Schande auf sich nehmen; und wer den Gottlosen straft, der muß gehohnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Strafe den Spotter nicht, er hasset dich; strafe den Weisen, der wird dich lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Gib dem Weisen, so wird er noch weiser werden; lehre den Gerechten, so wird er in der Lehre zunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Der Weisheit Anfang ist des HERRN Furcht; und der Verstand lehret, was heilig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Denn durch mich wird deiner Tage viel werden, und werden dir der Jahre des Lebens mehr werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Bistdu weise, so bistdu dirweise; bistdu ein Spotter, so wirst du es allein tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Es ist aber ein toricht, wild Weib, voll Schwatzens und weiß nichts;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'die sitzt in der Tur ihres Hauses auf dem Stuhl, oben in der Stadt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'zu laden alle, die vorubergehen und richtig auf ihrem Wege wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Wer ist albern, der mache sich hieher! Und zum Narren spricht sie:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Die verstohlenen Wassersind süß und das verborgene Brot ist niedlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Er weiß aber nicht, daß daselbst Tote sind und ihre Gaste in dertiefen Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Dies sind die Spruche Salomos. Ein weiser Sohn ist seines Vaters Freude; aber ein torichter Sohn ist seiner Mutter Gramen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Unrecht Gut hilft nicht; aber Gerechtigkeit errettet vom Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Der HERR laßt die Seele des Gerechten nicht Hunger leiden; er stürzt aber der Gottlosen Schinderei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Lassige Hand macht arm; aber der Fleißigen Hand macht reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Wer im Sommer sammelt, der ist klug; wer aber in der Ernte schlaft, wird zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Den Segen hat das Haupt des Gerechten; aber den Mund der Gottlosen wird ihr Frevel uberfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Das Gedachtnis der Gerechten bleibt im Segen; aber der Gottlosen Name wird verwesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Wer weise von Herzen ist, nimmtdie Gebote an; der aber ein Narrenmaul hat, wird geschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Wer unschuldig lebet, der lebet sicher; wer aber verkehrt ist auf seinen Wegen, wird offenbar werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Wer mit Augen winket, wird Muhe anrichten; und der ein Narrenmaul hat, wird geschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Des Gerechten Mund ist ein lebendiger Brunn; aber den Mund der Gottlosen wird ihr Frevel uberfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Haß erreget Hader; aber Liebe deckt zu alle Gbertretungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'In den Lippen des Verstandigen findet man Weisheit; aber auf den Rücken des Narren gehort eine Rute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Die Weisen bewahren die Lehre; aber der Narren Mund ist nahe dem Schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Das Gut des Reichen ist seine feste Stadt; aber die Armen macht die Armut blode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Der Gerechte braucht seines Guts zum Leben; aber der Gottlose braucht seines Einkommens zur Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Die Zucht halten, ist der Weg zum Leben; wer aber die Strafe verlaßt, der bleibt irrig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Falsche Mauler decken Haß; und wer verleumdet, der ist ein Narr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Wo viel Worte sind, da geht es ohne Sünde nicht ab; wer aber seine Lippen halt, ist klug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Des Gerechten Zunge ist kostlich Silber; aber der Gottlosen Herz ist nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Des Gerechten Lippen weiden viele; aber die Narren werden in ihrer Torheit sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Der Segen des HERRN macht reich ohne Muhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Ein Narrtreibt Mutwillen und hat\'s noch dazu seinen Spott; aber der Mann ist weise, der drauf merkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Was der Gottlose furchtet, das wird ihm begegnen; und was die Gerechten begehren, wird ihnen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Der Gottlose ist wie ein Wetter, das überhin geht und nicht mehr ist; der Gerechte aber bestehet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Wie der Essig den Zahnen und der Rauch den Augen tut, so tut der Faule denen, die ihn senden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Die Furcht des HERRN mehret die Tage; aber die Jahre der Gottlosen werden verkürzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Das Warten der Gerechten wird Freude werden; aber der Gottlosen Hoffnung wird verloren sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Der Weg des HERRN ist des Frommen Trotz; aber die Ubeltater sind blode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Der Gerechte wird nimmermehr umgestoßen; aber die Gottlosen werden nicht im Lande bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Der Mund des Gerechten bringt Weisheit; aber das Maul der Verkehrten wird ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Die Lippen der Gerechten lehren heilsam Ding; aber der Gottlosen Mund ist verkehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Falsche Waage ist dem HERRN ein Greuel; aber ein vollig Gewicht ist sein Wohlgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Wo Stolz ist, da ist auch Schmach; aber Weisheit ist bei den Demutigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Unschuld wird die Frommen leiten; aber die Bosheit wird die Verachter verstoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Gut hilft nicht am T age des Zorns; aber Gerechtigkeit errettet vom Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Die Gerechtigkeit des Frommen macht seinen Weg eben; aber der Gottlose wird fallen durch sein gottlos Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Die Gerechtigkeit der Frommen wird sie erretten; aber die Verachter werden gefangen in ihrer Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Wenn der gottlose Mensch stirbt, ist Hoffnung verloren; und das Harren der Ungerechten wird zunichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Der Gerechte wird aus der Not erloset und der Gottlose kommt an seine Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Durch den Mund des Heuchlers wird sein Nachster verderbet; aber die Gerechten merken\'s und werden erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Eine Stadt freuet sich, wenn\'s den Gerechten wohlgehet; und wenn die Gottlosen umkommen, wird man froh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Durch den Segen der Frommen wird eine Stadt erhaben; aber durch den Mund der Gottlosen wird sie zerbrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Wer seinen Nachsten schandet, ist ein Narr; aber ein verstandiger Mann stillet es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Ein Verleumderverrat, was er heimlich weiß; aber wer eines getreuen Herzens ist, verbirgt dasselbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Wo nicht Rat ist, da gehet das Volk unter; wo aber viel Ratgeber sind, da gehet es wohl zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Wer fur einen andern Burge wird, der wird Schaden haben; wer sich aber vor Geloben hutet, ist sicher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Ein holdselig Weib erhalt die Ehre; aber die Tyrannen erhalten den Reichtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Ein barmherziger Mann tut seinem Leibe Gutes; aber ein unbarmherziger betrubet auch sein Fleisch und Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Der Gottlosen Arbeit wird fehlen; aber wer Gerechtigkeit saet, das ist gewiti Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Denn Gerechtigkeit fordert zum Leben; aber dem Ubel nachjagen fordert zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Der HERR hat Greuel an den verkehrten Herzen und Wohlgefallen an den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Den Bosen hilft nichts, wenn sie auch alle Hande zusammentaten; aber der Gerechten Same wird errettet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Ein schon Weib ohne Zucht ist wie eine Sau mit einem guldenen Haarband.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Der Gerechten Wunsch muß doch wohl geraten; und der Gottlosen Hoffen wird Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Einer teilt aus und hat immer mehr; ein anderer karget, da er nicht soil, und wird doch armer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Die Seele, die da reichlich segnet, wird fett; und wer trunken macht, der wird auch trunken werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Wer Korn inhalt, dem fluchen die Leute; aber Segen kommt uber den, so es verkauft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Wer da Gutes sucht, dem widerfahrt Gutes; wer aber nach Ungluck ringet, dem wird\'s begegnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Wer sich auf seinen Reichtum verlafit, der wird untergehen; aber die Gerechten werden grünen wie ein Blatt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Wer sein eigen Haus betrubt, der wird Wind zu Erbteil haben; und ein Narr muß ein Knecht des Weisen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Die Frucht des Gerechten ist ein Baum des Lebens; und ein Weiser nimmt sich der Leute herzlich an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'So der Gerechte auf Erden leiden muß, wie viel mehr der Gottlose und Sunder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Wer sich gerne laßt strafen, der wird klug werden; wer aber ungestraft sein will, der bleibt ein Narr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Werfromm ist, derbekommt Trostvom HERRN; aber ein Ruchloser verdammt sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ein gottlos Wesen fordert den Menschen nicht; aber die Wurzel der Gerechten wird bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ein fleißig Weib ist eine Krone ihres Mannes; aber eine Unfleißige ist ein Eiter in seinem Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Die Gedanken der Gerechten sind redlich; aber die Anschlage der Gottlosen sind Trugerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Der Gottlosen Predigt richtet Blutvergießen an; aber der Frommen Mund errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Die Gottlosen werden umgesturzt und nicht mehr sein; aber das Haus der Gerechten bleibt stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Eines weisen Mannes Rat wird gelobt; aber die Tücken werden zuschanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Wer gering ist und wartet des Seinen, der ist besser, denn der groß sein will, dem des Brots mangelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Der Gerechte erbarmet sich seines Viehes; aber das Herz der Gottlosen ist unbarmherzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Wer seinen Acker bauet, der wird Brots die Fulle haben; wer aber unnotigen Sachen nachgehet, der ist ein Narr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Des Gottlosen Lust ist, Schaden zu tun; aber die Wurzel der Gerechten wird Frucht bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Der Bose wird gefangen in seinen eigenen falschen Worten; aber der Gerechte entgehet der Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Viel Gutes kommt einem durch die Frucht des Mundes; und dem Menschen wird vergolten, nachdem seine Hande verdienet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Dem Narren gefallt seine Weise wohl; aberwer Rat gehorcht; der ist weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Ein Narr zeigt seinen Zorn bald; aberwer die Schmach birget, ist witzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Werwahrhaftig ist, der sagtfrei, was recht ist; aber ein falscher Zeuge betrugt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Wer unvorsichtig herausfahrt, sticht wie ein Schwert; aber die Zunge der Weisen ist heilsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Wahrhaftiger Mund bestehet ewiglich; aber die falsche Zunge bestehet nicht lange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Die, so Boses raten, betrugen; aber die zum Frieden raten, machen Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Es wird dem Gerechten kein Leid geschehen; aber die Gottlosen werden voll Unglucks sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Falsche Mauler sind dem FIERRN ein Greuel; die aber treulich handeln, gefallen ihm wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Ein witziger Mann gibt nicht Klugheit vor; aber das Herz der Narren ruft seine Narrheit aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Fleüüge Hand wird herrschen; die aber lassig ist, wird müssen zinsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Sorge im Herzen kranket; aber ein freundlich Wort erfreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Der Gerechte hat\'s besser denn sein Nachster; aber der Gottlosen Weg verfuhret sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Einem Lassigen gerat sein Handel nicht; aber ein fleißiger Mensch wird reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Auf dem rechten Wege ist Leben, und auf dem gebahnten Pfad ist kein Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Ein weiser Sohn laßt sich den Vater zuchtigen; aber ein Spotter gehorchet der Strafe nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Der Frucht des Mundes geneußt man; aber die Verachter denken nur zu freveln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Wer seinen Mund bewahret, der bewahret sein Leben; wer aber mit seinem Maul herausfahrt, der kommt in Schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Der Faule begehrt und kriegt\'s doch nicht; aber die Fleißigen kriegen genug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Der Gerechte ist der Luge feind; aber der Gottlose schandet und schmahet sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Die Gerechtigkeit behutet den Unschuldigen; aber das gottlose Wesen bringet einen zu der Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Mancher ist arm bei großem Gut; und mancher ist reich bei seiner Armut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Mit Reichtum kann einer sein Leben erretten; aber ein Armer horet das Schelten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Das Licht der Gerechten macht frohlich; aber die Leuchte der Gottlosen wird ausloschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Unter den Stolzen ist immer Hader; aber Weisheit macht vemunftige Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Reichtum wird wenig, wo man\'s vergeudet; was man aber zusammenhalt, das wird groß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Die Hoffnung, die sich verzeucht, angstet das Herz; wenn\'s aber kommt, das man begehret, das ist ein Baum des Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Wer das Wort verachtet, der verderbet sich selbst; wer aber das Gebot furchtet, dem wird\'s vergolten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Die Lehre des Weisen isteine lebendige Quelle, zu meiden die Stricke des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Ein guter Rat tut sanft; aber der Verachter Weg bringt Wehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Ein Kluger tut alles mit Vernunft; ein Narr aber breitet Narrheit aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Ein gottloser Bote bringt Ungluck; aber ein treuer Werber ist heilsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Wer Zucht laßt fahren, der hat Armut und Schande; wer sich gerne strafen laßt, wird zu Ehren kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Wenn\'s kommt, das man begehret, das tut dem Herzen wohl; aber der das Bose meidet, ist den Toren ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Wer mit den Weisen umgehet, der wird weise; wer aber der Narren Geselle ist, der wird Ungluck haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Ungluck verfolget die Sunder; aber den Gerechten wird Gutes vergolten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Der Gute wird erben auf Kindeskind aber des Sunders Gut wird dem Gerechten vorgesparet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Es ist viel Speise in den Furchen der Armen; aber die unrecht tun, verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Wer seiner Rute schonet, der hasset seinen Sohn; wer ihn aber liebhat, der zuchtiget ihn bald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Der Gerechte isset, daß seine Seele satt wird; der Gottlosen Bauch aber hat nimmer genug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Durch weise Weiberwird das Hauserbauet; eine Narrin aber zerbricht es mit ihrem Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Wer den HERRN furchtet, der gehet auf rechter Bahn; wer ihn aber verachtet, der weicht aus seinem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Narren reden tyrannisch; aber die Weisen bewahren ihren Mund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Wo nicht Ochsen sind, da ist die Krippe rein; aber wo der Ochse geschaftig ist, da ist viel Einkommens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Ein treuer Zeuge luget nicht; aber ein falscher Zeuge redet türstiglich Lugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Der Spotter suchet Weisheit und findet sie nicht; aber dem Verstandigen ist die Erkenntnis leicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Gehe von dem Narren; denn du lernest nichts von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Das ist des Klugen Weisheit, daß er auf seinen Weg merkt; aber das ist der Narren Torheit, daß es eitel Trug mit ihnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Die Narren treiben das Gespott mit der Sunde; aber die Frommen haben Lust an den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Wenn das Herz traurig ist, so hilft keine außerliche Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Das Flaus der Gottlosen wird vertilget; aber die Hutte der Frommen wird grunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Es gefallt manchem ein Weg wohl; aber endlich bringt er ihnzum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nach dem Lachen kommt Trauern, und nach der Freude kommt Leid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Einem losen Menschen wird\'s gehen, wie er handelt; aber ein Frommer wird uber ihn sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Ein Alberner glaubt alles; aber ein Witziger merkt auf seinen Gang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Ein Weiserfurchtet sich und meidet das Arge; ein Narr aber fahrt hindurch türstiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Ein Ungeduldiger tut narrisch; aber ein Bedachtiger hasset es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Die Albernen erben Narrheit; aber es ist der Witzigen Krone, vorsichtiglich handeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Die Bosen müssen sich bücken vorden Guten und die Gottlosen in den Toren des Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Einen Armen hassen auch seine Nachsten; aber die Reichen haben viel Freunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Der Sunder verachtet seinen Nachsten; aber wohl dem, der sich der Elenden erbarmet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Die mit bosen Ranken umgehen, werden fehlen; die aber Gutes denken, denen wird Treue und Güte widerfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Wo man arbeitet, da ist genug; wo man aber mit Worten umgeht, da ist Mangel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Den Weisen ist ihr Reichtum eine Krone; aber die Torheit der Narren bleibt Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Ein treuer Zeuge errettet das Leben; aber ein falscher Zeuge betrugt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Wer den FIERRN furchtet, der hat eine sichere Festung, und seine Kinder werden auch beschirmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Die Furcht des FIERRN ist eine Quelle des Lebens, dafi man meide die Stricke des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Wo ein Konig viel Volks hat, das ist seine FHerrlichkeit; wo aber, wenig Volks ist, das macht einen FHerrn blode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Wer geduldig ist, der ist weise; wer aber ungeduldig ist, der offenbart seine Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Ein gutiges FHerz ist des Leibes Leben; aber Neid ist Eiter in Beinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Wer dem Geringen Gewalt tut, der lasted desselben Schdpfer; aber wer sich des Armen erbarmet, der ehret Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Der Gottlose bestehet nicht in seinem Ungluck; aber der Gerechte ist auch in seinem Tode getrost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Im Flerzen des Verstandigen ruhet Weisheit und wird offenbar unter den Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Gerechtigkeit erhohet ein Volk; aber die Sünde ist der Leute Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Ein kluger Knecht gefallt dem Konige wohl; aber einem schandlichen Knechte ist er feind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Eine linde Antwort stillet den Zorn; aber ein hart Wort richtet Grimm an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Der Weisen Zunge macht die Lehre lieblich; der Narren Mund speiet eitel Narrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Die Augen des FIERRN schauen an alien Orten beide, die Bosen und Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Eine heilsame Zunge ist ein Baum des Lebens; aber eine lugenhaftige macht Herzeleid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Der Narr lasted die Zucht seines Vaters; wer aber Strafe annimmt, der wird klug werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'In des Gerechten Flause ist Guts genug aber in dem Einkommen des Gottlosen ist Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Der Weisen Mund streuet guten Rat; aber der Narren FHerz ist nicht also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Der Gottlosen Opfer ist dem FIERRN ein Greuel; aber das Gebet der Frommen ist ihm angenehm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Des Gottlosen Weg ist dem FIERRN ein Greuel; wer aber der Gerechtigkeit nachjagt, der wird geliebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Das ist eine bose Zucht, den Weg verlassen; und wer die Strafe hasset, der muß, sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Holle und Verderbnis istvordem FIERRN; wie viel mehr der Menschen Flerzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Der Spotter liebt nicht, der ihn straft, und gehet nicht zu den Weisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Ein frohlich Herz macht ein frohlich Angesicht; aber wenn das Herz bekummert ist, so fallt auch der Mut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Ein kluges Herz handelt bedachtiglich; aber die kuhnen Narren regieren narrisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Ein Betrubter hat nimmer keinen guten Tag; aber ein guter Mut ist ein taglich Wohlleben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Es ist besser ein wenig mit der Furcht des FIERRN denn großer Schatz, darin Unruhe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Es ist besser ein Gericht Kraut mit Liebe denn ein gemasteter Ochse mit Haß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Ein zorniger Mann richtet Hader an; ein Geduldiger aber stillet den Zank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Der Weg des Faulen istdornig; aber der Weg der Frommen ist wohl gebahnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Ein weiser Sohn erfreuet den Vater; und ein narrischer Mensch ist seiner Mutter Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Dem Toren ist die Torheit eine Freude; aber ein verstandiger Mann bleibt auf dem rechten Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Die Anschlage werden zunichte, wo nicht Rat ist; wo aber viel Ratgeber sind, bestehen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Es ist einem eine Freude, wo man ihm richtig antwortet; und ein Wort zu seiner Zeit ist sehr lieblich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Der Weg des Lebens gehet uberwarts klug zu machen, auf daß man meide die Holle unterwarts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Der HERR wird das Flaus der Hoffartigen zerbrechen und die Grenze der Witwen bestatigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Die Anschlage des Argen sind dem FIERRN ein Greuel; aber trostlich reden die Reinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Der Geizige verstoret sein eigen Flaus; wer aber Geschenk hasset, der wird leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Das Herz des Gerechten dichtet, was zu antworten ist; aber der Mund der Gottlosen schaumet Boses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Der HERR ist feme von den Gottlosen; aber der Gerechten Gebet erhoret er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Freundlicher Anblick erfreuet das Herz; ein gut Gerucht macht das Gebeine fett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Das Ohr, das da horet die Strafe des Lebens, wird unter den Weisen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Wer sich nicht ziehen laßt, der macht sich selbst zunichte; wer aber Strafe horet, der wird klug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Die Furcht des HERRN ist Zucht zur Weisheit; und ehe man zu Ehren kommt, muß man zuvor leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Der Mensch setzt ihm wohl vor im Herzen; aber vom HERRN kommt, was die Zunge reden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Einen jeglichen dünken seine Wege rein sein; aber allein der HERR macht das Herz gewiß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Befiehl dem HERRN deine Werke, so werden deine Anschlage fortgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Der HERR macht alles urn sein selbst willen, auch den Gottlosen zum bosen Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Ein stolz Herz ist dem HERRN ein Greuel und wird nicht ungestraft bleiben, wenn sie sich gleich alle aneinander hangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Durch Güte und Treue wird Missetat versohnet; und durch die Furcht des HERRN meidet man das Bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Wenn jemands Wege dem HERRN wohlgefallen, so macht er auch seine Feinde mit ihm zufrieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Es ist besser wenig mit Gerechtigkeit denn viel Einkommens mit Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Des Menschen Herz schlagt seinen Weg an, aber der HERR allein gibt, daß erfortgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Weissagung ist in dem Munde des Konigs; sein Mund fehlet nicht im Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Rechte Waage und Gewicht ist vom HERRN; und alle Pfunde im Sack sind seine Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Vor den Konigen unrecht tun, ist ein Greuel; denn durch Gerechtigkeit wird der Thron bestatiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Recht raten gefallt den Konigen; und wer gleich zu rat, wird geliebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Des Konigs Grimm ist ein Bote des Todes; aber ein weiser Mann wird ihn versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Wenn des Konigs Angesicht freundlich ist, das ist Leben; und seine Gnade ist wie ein Abendregen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Nimm an die Weisheit, denn sie ist besser weder Gold, und Verstand haben ist edler denn Silber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Der Frommen Weg meidet das Arge; und wer seinen Weg bewahret, der behalt sein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Werzugrund gehen soil, der wird zuvor stolz; und stolzer Mut kommt vor dem Fall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Es ist besser niedriges Gemüts sein mit den Elenden, denn Raub austeilen mit den Hoffartigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Wereine Sache kluglich führet, der findet Gluck; und wohl dem, der sich auf den HERRN verlaßt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Ein Verstandiger wird geruhmet fur einen weisen Mann, und liebliche Reden lehren wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Klugheit ist ein lebendiger Brunn dem, der sie hat; aber die Zucht der Narren ist Narrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Ein weises Herz redet kluglich und lehret wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Die Reden des Freundlichen sind Honigseim, trosten die Seele und erfrischen die Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Manchem gefallt ein Weg wohl; aber sein Letztes reicht zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Mancher kommt zu großem Ungluck durch sein eigen Maul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Ein loser Mensch grabt nach Ungluck, und in seinem Maul brennet Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Ein verkehrter Mensch richtet Hader an, und ein Verleumder macht Fursten uneins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Ein Frevler locket seinen Nachsten und fuhret ihn auf keinen guten Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Wer mit den Augen winkt, denkt nicht Gutes; und wer mit den Lippen deutet, vollbringet Boses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Graue Haare sind eine Krone der Ehren, die auf dem Wege der Gerechtigkeit funden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Ein Geduldiger ist besser denn ein Starker, und der seines Muts Herr ist, denn der Stadte gewinnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Los wird geworfen in den Schoß; aber es fallet, wie der HERR will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Es ist ein trockner Bissen, daran man sich genugen laßt, besser denn ein Haus voll Geschlachtetes mit Hader.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Ein kluger Knechtwird herrschen uber unfleißige Erben und wird unter den Brudern das Erbe austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Wie das Feuer Silber und der Ofen Gold, also prufet der HERR die Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Ein Boser achtet auf bose Mauler, und ein Falscher gehorcht gerne schadlichen Zungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Wer des Durftigen spottet, der hohnet desselben Schopfer; und wer sich seines Unfalls freuet, wird nicht ungestraft bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Der Alten Krone sind Kindeskinder, und der Kinder Ehre sind ihre Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Esstehet einem Narren nicht wohl an, von hohen Dingen reden, viel weniger einem Fursten, daß er gerne lüget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Wer zu schenken hat, dem ist\'s wie ein Edelstein; wo er sich hinkehret, ist er klug geachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Wer Sunde zudeckt, der macht Freundschaft; wer aber die Sache aufrührt, der macht Fursten uneins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Schelten schreckt mehr an dem Verstandigen denn hundert Schlage an dem Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Ein bitterer Mensch trachtet Schaden zu tun; aber es wird ein grausamer Engel uber ihn kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Es ist besser, einem Baren begegnen, dem die Jungen geraubet sind, denn einem Narren in seiner Narrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Wer Gutes mit Bosem vergilt, von des Hause wird Boses nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Wer Hader anfahet, istgleich, alsder dem Wasser den Damm aufreißt. Laß du vom Hader, ehe du drein gemenget wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Wer den Gottlosen recht spricht und den Gerechten verdammet, die sind beide dem HERRN ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Was soil dem Narren Geld in der Hand, Weisheit zu kaufen, so er doch ein Narr ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Ein Freund liebet allezeit, und ein Bruderwird in der Not erfunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Es ist ein Narr, der an die Hand gelobet und Burge wird fur seinen Nachsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Wer Zank liebt, der liebt Sunde; und wer seine Tur hoch macht, ringet nach Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Ein verkehrt Herz findet nichts Gutes, und der verkehrter Zunge ist, wird in Ungluck fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Wer einen Narren zeuget, der hat Gramen, und eines Narren Vater hat keine Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Ein frohlich Herz macht das Leben lustig; aber ein betrubter Mut vertrocknet das Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Der Gottlose nimmt heimlich gem Geschenke, zu beugen den Weg des Rechts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Ein Verstandiger gebardet weislich; ein Narr wirft die Augen hin und her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Ein narrischer Sohn ist seines Vaters Trauern und Betrubnis seiner Mutter, die ihn geboren hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Es ist nicht gut, daß man den Gerechten schindet, den Fursten zu schlagen, der recht regieret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Ein Vernunftiger maßiget seine Rede, und ein verstandiger Mann ist eine teure Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Ein Narr, wenn er schwiege, wurde auch weise gerechnet und verstandig, wenn er das Maul hielte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Wer sich absondert, der sucht, was ihn gelustet, und setzt sich wider alles, was gut ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Ein Narr hat nicht Lust am Verstand, sondern was in seinem Herzen steckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Wo der Gottlose hinkommt, da kommt Verachtung und Schmach mit Hohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Die Worte in eines Munde sind wie tiefe Wasser, und die Quelle der Weisheit ist ein voller Strom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Es ist nicht gut, die Person des Gottlosen achten, zu beugen den Gerechten im Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Die Lippen des Narren bringen Zank, und sein Mund ringet nach Schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Der Mund des Narren schadet ihm selbst, und seine Lippen fahen seine eigene Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Die Worte des Verleumders sind Schlage und gehen einem durchs Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Wer laß ist in seiner Arbeit, der ist ein Bruder des, der das Seine umbringet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Der Name des HERRN ist ein festes Schloß; der Gerechte lauft dahin und wird beschirmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Das Gut des Reichen ist ihm eine feste Stadt und wie eine hohe Mauer urn ihn her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Wenn einer zugrund gehen soil, wird sein Herz zuvor stolz; und ehe man zu Ehren kommt, muß man zuvor leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Wer antwortet, ehe er horet, dem ist\'s Narrheit und Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Wer ein frohlich Herz hat, derweiß sich in seinem Leiden zu halten; wenn aber der Mut liegt, wer kann\'s tragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Ein verstandig Herz weiß sich vernunftiglich zu halten, und die Weisen horen gem, daß man vernunftiglich handelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Das Geschenk des Menschen macht ihm Raum und bringt ihn vor die großen Herren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Der Gerechte ist seiner Sache zuvor gewiß; kommt sein Nachster, so findet er ihn also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Das Los stillet den Hader und scheidet zwischen den Machtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Ein verletzter Bruder halt harter denn eine feste Stadt; und Zank halt harter denn Riegel am Palast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Einem Mann wird vergolten, danach sein Mund geredet hat, und wird gesattiget von der Frucht seiner Lippen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Tod und Leben steht in der Zunge Gewalt; wer sie liebet, der wird von ihrer Frucht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Wer eine Ehefrau findet, der findet was Gutes und bekommt Wohlgefallen vom HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Ein Armer redet mit Flehen; ein Reicher antwortet stolz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ein treuer Freund liebet mehr und steht fester bei denn ein Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Ein Armer, der in seiner Frommigkeit wandelt, ist besser denn ein Verkehrter mit seinen Lippen, der doch ein Narr ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Wo man nicht mit Vernunft handelt, da geht es nicht wohl zu; und wer schnell ist mit Füßen, der tut Schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Die Torheit eines Menschen verleitet seinen Weg; da sein Herz wider den HERRN tobet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Gut macht viel Freunde; aber der Arme wird von seinen Freunden verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ein falscher Zeuge bleibt nicht ungestraft, und wer Lugen frech redet, wird nicht entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Viele warten auf die Person des Fursten und sind alle Freunde des, der Geschenke gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Den Armen hassen alle seine Bruder, ja auch seine Freunde fernen sich von ihm; und wer sich auf Worte verlaßt, dem wird nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Wer klug ist, liebet sein Leben; und der Verstandige findet Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Ein falscher Zeuge bleibt nicht ungestraft, und wer frech Lugen redet, wird umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Dem Narren stehet nicht wohl an, gute Tage haben, viel weniger einem Knechte, zu herrschen uber Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Wergeduldig ist, der ist ein kluger Mensch, und ist ihm ehrlich, daß er Untugend uberhoren kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Die Ungnade des Konigs istwie das Brüllen eines jungen Lowen; aber seine Gnade ist wie Tau auf dem Grase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Ein narrischer Sohn ist seines Vaters Herzeleid und ein zankisch Weib ein stetiges Triefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Haus und Güter erben die Eltern; aber ein vernunftig Weib kommt vom HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Faulheit bringt Schlafen, und eine lassige Seele wird Hunger leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Wer das Gebot bewahret, der bewahret sein Leben; wer aber seinen Weg verachtet, wird sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Wer sich des Armen erbarmet, der leihet dem HERRN; der wird ihm wieder Gutes vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Zuchtige deinen Sohn, weil Hoffnung da ist; aber lali deine Seele nicht bewegt werden, ihn zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Denn grolier Grimm bringt Schaden; darum lali ihn los, so kannst du ihn mehr zuchtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Gehorche dem Rat und nimm Zucht an, daß du hernach weise seiest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Es sind viel Anschlage in eines Mannes Herzen; aber der Rat des HERRN bleibet stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Einen Menschen lustet seine Wohltat; und ein Armer ist besser denn ein Lugner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Die Furchtdes HERRN fordertzum Leben und wird satt bleiben, daß kein Ubel sie heimsuchen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Der Faule verbirgt seine Hand im Topf und bringt sie nicht wieder zum Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Schlagt man den Spotter, so wird der Alberne witzig; straft man einen Verstandigen, so wird er vernunftig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Wer Vater verstoret und Mutter verjaget, der ist ein schandlich und verflucht Kind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Lali ab, mein Sohn, zu horen die Zucht, die da abfuhret von vernunftiger Lehre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Ein loser Zeuge spottet des Rechts, und der Gottlosen Mund verschlinget das Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Den Spottern sind Strafen bereitet und Schlage auf der Narren Rücken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Der Wein macht lose Leute und stark Getrank macht wild; wer dazu Lust hat, wird nimmer weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Das Schrecken des Konigs ist wie das Brüllen eines jungen Lowen; wer ihn erzurnet, der sundiget wider sein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Es ist dem Mann eine Ehre, vom Hader bleiben; aber die gerne hadern, sind allzumal Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Urn der Kalte willen will der Faule nicht pflugen; so muli er in der Ernte betteln und nichts kriegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Der Rat im Herzen eines Mannes ist wie tiefe Wasser; aber ein Verstandiger kann\'s merken, was er meinet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Viele Menschen werden fromm geruhmet; aber wer will finden einen, der rechtschaffen fromm sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Ein Gerechter, der in seiner Frommigkeit wandelt, des Kindern wird\'s wohlgehen nach ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Ein Konig, der auf dem Stuhl sitzt zu richten, zerstreuet alles Arge mit seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Wer kann sagen: Ich bin rein in meinem Herzen und lauter von meiner Sunde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Mancherlei Gewicht und Mali ist beides Greuel dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Auch kennet man einen Knaben an seinem Wesen, ob er fromm und redlich werden will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ein horend Ohr und sehend Auge, die macht beide der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Liebe den Schlaf nicht, daß du nicht arm werdest; lali deine Augen wacker sein, so wirst du Brots genug haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Bose, bose! spricht man, wenn man\'s hat; aber wenn\'s weg ist, so rühmet man es denn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Es ist Gold und viel Perlen; aber ein vernunftiger Mund ist ein edel Kleinod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Nimm dem sein Kleid, der fur einen anderen Burge wird, und pfande ihn urn des Unbekannten willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Das gestohlene Brot schmecktjedermann wohl; aber hernach wird ihm der Mund voll Kieseling werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Anschlage bestehen, wenn man sie mit Rat führet; und Krieg soli man mit Vernunft führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Sei unverworren mit dem, der Heimlichkeit offenbart, und mit dem Verleumder und mit dem falschen Maul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Wer seinem Vater und seiner Mutter flucht, des Leuchte wird verloschen mitten in Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Das Erbe, danach man zuerst sehr eilet, wird zuletzt nicht gesegnet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Sprich nicht: Ich will Boses vergelten. Harre des HERRN, der wird dir helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Mancherlei Gewicht ist ein Greuel dem HERRN, und eine falsche Waage ist nicht gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Jedermanns Gange kommen vom HERRN. Welcher Mensch verstehet seinen Weg?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Es ist dem Menschen ein Strick, das Heilige lastern und danach Gelubde suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Ein weiser Konig zerstreuet die Gottlosen und bringet das Rad liber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Die Leuchte des HERRN ist des Menschen Odem; die gehet durchs ganze Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Fromm und wahrhaftig sein behuten den Konig, und sein Thron bestehet durch Frommigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Der Junglinge Starke ist ihr Preis; und grau Haar ist der Alten Schmuck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Man muli dem Bosen wehren mit harter Strafe und miternsten Schlagen, die man fuhlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Des Konigs Herz ist in der Hand des HERRN wie Wasserbache, und er neiget es, wohin er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Einen jeglichen dünkt sein Weg recht sein; aber allein der HERR macht die Herzen gewili.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Wohl und recht tun ist dem HERRN lieber denn Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Hoffartige Augen und stolzer Mut und die Leuchte der Gottlosen ist Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Die Anschlage eines Endelichen bringen Uberfluli; wer aber allzu jach ist, wird mangeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Wer Schatze sammelt mit Lügen, der wird fehlen und fallen unter die den Tod suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Der Gottlosen Rauben wird sie schrecken; denn sie wollten nicht tun, was recht war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Wer einen andern Weg gehet, der ist verkehrt; wer aber in seinem Befehl gehet, des Werk ist recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Es ist besser wohnen im Winkel auf dem Dach, denn bei einem zankischen Weibe in einem Hause beisammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Die Seele des Gottlosen wünschet Arges und gonnet seinem Nachsten nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Wenn der Spotter gestraft wird, sowerden die Albernen weise; und wenn man einen Weisen unterrichtet, so wird er vernünftig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Der Gerechte halt sich weislich gegen des Gottlosen Haus; aber die Gottlosen denken nur Schaden zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Wer seine Ohren verstopft vor dem Schreien des Armen, der wird auch rufen und nicht erhoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Eine heimliche Gabe stillet den Zorn und ein Geschenk im Scholi den heftigen Grimm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Es ist dem Gerechten eine Freude zu tun, was recht ist, aber eine Furcht den Ubeltatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ein Mensch, der vom Wege der Klugheit irret, der wird bleiben in der Toten Gemeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Wer gem in Wollust lebt, wird mangeln; und wer Wein und 01 liebet, wird nicht reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Derßottlose muli fur den Gerechten gegeben werden und der Verachter fur die Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Es ist besser wohnen im wüsten Lande denn, bei einem zankischen und zornigen Weibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Im Hause des Weisen ist ein lieblicher Schatz und 01 aber ein Narr verschlemmt es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Wer der Barmherzigkeit und Güte nachjagt, der findet das Leben, Barmherzigkeit und Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Ein Weisergewinnet die Stadt der Starken und sturzet ihre Macht durch ihre Sicherheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Wer seinen Mund und Zunge bewahret, der bewahret seine Seele vor Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Der stolz und vermessen ist, heilit ein loser Mensch, der im Zorn Stolz beweiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Der Faule stirbt über seinem Wunschen; denn seine Hande wollen nichts tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Er wünscht taglich; aber der Gerechte gibt und versagt nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Der Gottlosen Opfer ist ein Greuel; denn sie werden in Sunden geopfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Ein lugenhaftiger Zeuge wird umkommen; aber wer gehorchet, den lalit man auch allezeit wiederum reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Der Gottlose fahrt mit dem Kopf hindurch; aber wer fromm ist, des Weg wird bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Es hilft keine Weisheit, kein Verstand, kein Rat wider den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Rosse werden zum Streittage bereitet; aber der Sieg kommt vom HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Das Gerucht ist kostlicher denn grower Reichtum und Gunst besser denn Silber und Gold.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Reiche und Arme müssen untereinander sein; der HERR hat sie alle gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Der Witzige siehet das Ungluck und verbirgt sich; die Albernen gehen durchhin und werden beschadigt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Wo man leidet in des HERRN Furcht, da ist Reichtum, Ehre und Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Stacheln und Stricke sind auf dem Wege des Verkehrten; wer aber sich davon fernet, bewahret sein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Wie man einen Knaben gewohnt, so lalit er nicht davon, wenn eralt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Der Reiche herrschet uber die Armen, und wer borget, ist des Lehners Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Wer Unrecht saet, der wird Muhe ernten und wird durch die Rute seiner Bosheit umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Ein gut Auge wird gesegnet; denn er gibt seines Brots den Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Treibe den Spotter aus, so gehet der Zank weg, so horet auf Hader und Schmach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Wer ein treu Herz und liebliche Rede hat, des Freund ist der Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Die Augen des HERRN behuten guten Rat; aber die Worte des Verachters verkehret er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Der Faule spricht: Es ist ein Lowe draulien, ich mochte erwurget werden auf der Gasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Der Huren Mund ist eine tiefe Grube; wem der HERR ungnadig ist, der fallet drein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Torheitstecktdem Knaben im Herzen; aber die Rute der Zucht wird sie feme von ihm treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Wer dem Armen unrecht tut, daß seines Guts viel werde, der wird auch einem Reichen geben und mangeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Neige deine Ohren und hore die Worte der Weisen und nimm zu Herzen meine Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Denn es wird dir sanft tun, wo du sie wirst bei dir behalten, und werden miteinander durch deinen Mund wohl geraten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'daß deine Hoffnung sei auf den HERRN. Ich muli dich solches taglich erinnern dir zu gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Hab ich dir\'s nicht mannigfaltiglich vorgeschrieben mit Raten und Lehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'daß ich dir zeigete einen gewissen Grund der Wahrheit, daß du recht antworten konntest denen, die dich senden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Beraube den Armen nicht, ob erwohl arm ist, und unterdrucke den Elenden nicht im Tor;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'denn der HERR wird ihre Sache handeln und wird ihre Untertreter untertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Geselle dich nicht zum zornigen Mann und halte dich nicht zu einem grimmigen Mann;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'du mochtest seinen Weg lernen und deiner Seele Argernis empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Sei nicht bei denen, die ihre Hand verhaften und fur Schuld Burge werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'denn wo du es nicht hast zu bezahlen, so wird man dir dein Bett unter dir wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Treibe nicht zuruck die vorigen Grenzen, die deine Vater gemacht haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Siehest du einen Mann endelich in seinem Geschafte, der wird vor den Konigen stehen und wird nicht vor den Unedlen stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Wenn du sitzest und issest mit einem Herrn, so merke, wen du vor dir hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'und setze ein Messer an deine Kehle, willst du das Leben behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Wünsche dir nicht seiner Speise, denn es ist falsch Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Bemühe dich nicht, reich zu werden, und Laß ab von deinen Fundlein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'laß deine Augen nicht fliegen dahin, das du nicht haben kannst; denn dasselbe macht ihm Flugel wie ein Adler und fleugt gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, '18 nicht Brot bei einem Neidischen und wünsche dir seiner Speise nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Denn wie ein Gespenst ist er inwendig. Er spricht: 18 und trink! und sein Herz ist doch nicht an dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Deine Bissen, die du gegessen hattest mußt du ausspeien und mußt deine freundlichen Worte verloren haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Rede nicht vor des Narren Ohren; denn er verachtet die Klugheit deiner Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Treibe nicht zuruck die vorigen Grenzen und gehe nicht auf der Waisen Acker!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Denn ihr Erloser ist machtig; der wird ihre Sache wider dich ausführen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Gib dein Herzzur Zucht und deine Ohren zu vernunftiger Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'laß nicht ab, den Knaben zu zuchtigen; denn wo du ihn mit der Rute hauest, so darf man ihn nicht toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Du hauest ihn mit der Rute; aber du errettest seine Seele von der Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Mein Sohn, so du weise bist, so freuet sich auch mein Herz;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'und meine Nieren sind froh, wenn deine Lippen reden, was recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Dein Herz folge nicht den Sundern, sondern sei taglich in der Furcht des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Denn es wird dir hernach gut sein und dein Warten wird nicht fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Hore, mein Sohn, und sei weise und richte dein Herz in den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Sei nicht unter den Saufern und Schlemmern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'denn die Saufer und Schlemmer verarmen, und ein Schlafer mu8 zerrissene Kleider tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Gehorche deinem Vater, der dich gezeugt hat, und verachte deine Mutter nicht, wenn sie alt wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kaufe Wahrheit und verkaufe sie nicht, Weisheit, Zucht und Verstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Ein Vater des Gerechten freuet sich, und wer einen Weisen gezeugt hat, ist frohlich daruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Laß sich deinen Vater und deine Mutter freuen und frohlich sein, die dich gezeuget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Gib mir, mein Sohn, dein Herz und Laß deinen Augen meine Wege wohlgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Denn eine Hure ist eine tiefe Grube, und die Ehebrecherin ist eine enge Grube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Auch lauert sie wie ein Rauber und die Frechen unter den Menschen sammelt sie zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Wo ist Weh? Wo ist Leid? Wo ist Zank? Wo ist Klagen? Wo sind Wunden ohne Ursache? Wo sind rote Augen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Namlich, wo man beim Wein liegt und kommt auszusaufen, was eingeschenkt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Siehe den Wein nicht an, daß er so rot ist und im Glase so schon stehet. Er gehet glatt ein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'aber danach beißt er wie eine Schlange und sticht wie eine Otter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'So werden deine Augen nach andern Weibern sehen, und dein Herz wird verkehrte Dinge reden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'und wirst sein wie einer, der mitten im Meer schlaft, und wie einer schlaft oben auf dem Mastbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Sie schlagen mich, aber es tut mir nicht weh; sie klopfen mich, aber ich fühle es nicht. Wann will ich aufwachen, daß ich\'s mehr treibe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Folge nicht bosen Leuten und wünsche nicht, bei ihnen zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Denn ihr Herz trachtet nach Schaden, und ihre Lippen raten zu Unglück.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Durch Weisheit wird ein Haus gebauet und durch Verstand erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Durch ordentlich Haushalten werden die Kammern voll aller kostlichen, lieblichen Reichtumer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Ein weiser Mann ist stark und ein vernunftiger Mann ist machtig von Kraften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Denn mit Rat muß man Krieg fuhren; und wo viel Ratgeber sind, da ist der Sieg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Weisheit ist dem Narren zu hoch; er darf seinen Mund im Tor nicht auftun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Wer ihm selbst Schaden tut, den heißt man billig einen Erzbosewicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Des Narren Tücke ist Sünde; und der Spotter ist ein Greuel vor den Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Der ist nicht stark, der in der Not nicht fest ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Errette die, so man toten will, und entzieh dich nicht von denen, die man würgen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Sprichst du: Siehe, wir verstehen\'s nicht; meinest du nicht, der die Herzen weiß, merket es, und der auf die Seele acht hat, kennet es und vergilt dem Menschen nach seinem Werk?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Iß, mein Sohn, Honig, denn es ist gut, und Honigseim ist süß in deinem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Also lerne die Weisheit fur deine Seele. Wenn du sie findest, so wird\'s hernach wohlgehen, und deine Hoffnung wird nicht umsonst sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Laure nicht, als ein Gottloser, auf das Haus des Gerechten; verstore seine Ruhe nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Denn ein Gerechter fallt siebenmal und stehet wieder auf; aber die Gottlosen versinken in Unglück.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Freue dich des Falles deines Feindes nicht, und dein Herz sei nicht froh uber seinem Ungluck;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'es mochte der HERR sehen und ihm übel gefallen und seinen Zorn von ihm wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Erzurne dich nicht überden Bosen und eifre nicht über die Gottlosen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'denn der Bose hat nichts zu hoffen, und die Leuchte der Gottlosen wird verloschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Mein Kind, furchte den HERRN und den Konig und menge dich nicht unter die Aufruhrerischen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Denn ihr Unfall wird plotzlich entstehen; und wer weiß, wann beider Ungluck kommt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Dies kommt auch von den Weisen: Die Person ansehen im Gericht ist nicht gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Wer zum Gottlosen spricht: Du bist fromm, dem fluchen die Leute und hasset das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Welche aber strafen, die gefallen wohl, und kommt ein reicher Segen auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Eine richtige Antwort ist wie ein lieblicher Kuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Richte draußen dein Geschaft aus und arbeite deinen Acker; danach baue dein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Sei nicht Zeuge ohne Ursache wider deinen Nachsten und betrüge nicht mit deinem Munde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Sprich nicht: Wie man mir tut, so will ich wieder tun und einem jeglichen sein Werk vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Ich ging vor dem Acker des Faulen und vor dem Weinberge des Narren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'und siehe, da waren eitel Nesseln drauf und stund voll Disteln, und die Mauerwareingefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Da ich das sah, nahm ich\'s zu Herzen und schauete und lernete dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Du willst ein wenig schlafen und ein wenig schlummern und ein wenig die Hande zusammentun, daß du ruhest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'aber es wird dir deine Armut kommen wie ein Wanderer und dein Mangel wie ein gewappneter Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Dies sind auch Sprüche Salomos, die hinzugesellt haben die Manner Hiskias, des Konigs Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Es ist Gottes Ehre, eine Sache verbergen; aber der Konige Ehre ist\'s, eine Sache erforschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Der Himmel ist hoch und die Erde tief; aber der Konige Herz ist unerforschlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Man tue den Schaum vom Silber, so wird ein rein Gefaß draus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Man tue gottlos Wesen vom Konige, so wird sein Thron mit Gerechtigkeit bestatiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Prange nicht vor dem Konige und tritt nicht an den Ort der Großen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Denn es ist dir besser, daß man zu dir sage: Tritt hie herauf! denn daß du vor dem Fursten geniedriget wirst, daß deine Augen sehen müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Fahre nicht bald heraus zu zanken; denn was willst du hernach machen, wenn du deinen Nachsten geschandet hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Handle deine Sache mit deinem Nachsten und offenbare nicht eines andern Heimlichkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'auf daß dir\'s nicht übel spreche, der es horet, und dein boses Gerucht nimmer ablasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Ein Wort, geredet zu seiner Zeit, ist wie guldene Apfel in silbernen Schalen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Wereinen Weisen straft, der ihm gehorcht, das ist wie ein gulden Stirnband und gulden Halsband.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Wie die Kalte des Schnees zur Zeit der Ernte, so ist ein getreuer Bote dem, der ihn gesandt hat und erquickt seines Herrn Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Wer viel geredet und halt nicht, der ist wie Wolken und Wind ohne Regen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Durch Geduld wird ein Furst versohnet, und eine linde Zunge bricht die Hartigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Findest du Honig, so iß sein genug, daß du nicht zu satt werdest und speiest ihn aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Entzeuch deinen Fuß vom Hause deines Nachsten, er mochte dein überdrüssig und dir gram werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Wer wider seinen Nachsten falsch Zeugnis redet, der ist ein Spieß, Schwert und scharfer Pfeil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Die Hoffnung des Verachters zur Zeit der Not ist wie ein fauler Zahn und gleitender Fuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Wer einem bosen Herzen Lieder singet, das ist wie ein zerrissen Kleid im Winter und Essig auf der Kreide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Hungert deinen Feind, so speise ihn mit Brot; durstet ihn, so tranke ihn mit Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Denn du wirst Kohlen auf sein Haupt haufen; und der HERR wird dir\'s vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Der Nordwind bringet Ungewitter, und die heimliche Zunge macht sauer Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Es ist besser im Winkel auf dem Dache sitzen denn bei einem zankischen Weibe in einem Hause beisammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Ein gut Gerucht aus fernen Landen in wie kalt Wasser einer durstigen Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Ein Gerechter, der vor einem Gottlosen fallt, ist wie ein trüber Brunnen und verderbte Quelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Wer zu viel Honig isset, das ist nicht gut; und wer schwere Dinge forschet, dem wird\'s zu schwer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Ein Mann, der seinen Geist nicht halten kann, ist wie eine offene Stadt ohne Mauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Wie der Schnee im Sommer und Regen in der Emte, also reimet sich dem Narren Ehre nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Wie ein Vogel dahinfahrt und eine Schwalbe fleugt, also ein unverdienter Fluch trifft nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Dem Roft eine Geiftel und dem Esel ein Zaum; und dem Narren eine Rute auf den Rücken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Antworte dem Narren nicht mich seiner Narrheit, daß du ihm nicht auch gleich werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Antworte aber dem Narren nach seiner Narrheit, daß er sich nicht weise lasse dunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Wer eine Sache durch einen torichten Boten ausrichtet, der istwie ein Lahmeran Fuften und nimmt Schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Wie einem Kruppel das Tanzen, also stehet den Narren an, von Weisheit reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Wer einem Narren Ehre anlegt, das ist, als wenn einer einen Edelstein auf den Rabenstein würfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Ein Spruch in eines Narren Mund istwie ein Dornzweig, der in eines Trunkenen Hand sticht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Ein guter Meister macht ein Ding recht; aber wer einen Hümpler dinget, dem wird\'s verderbt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Wie ein Hund sein Gespeietes wieder friftt, also ist der Narr, der seine Narrheit wieder treibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Wenn du einen siehest, der sich weise dunket, da ist an einem Narren mehr Hoffnung denn an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Der Faule spricht: Es ist ein junger Lowe auf dem Wege und ein Lowe auf den Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Ein Fauler wendet sich im Bette wie die Tur in der Angel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Der Faule verbirgt seine Hand in dem Topf, und wird ihm sauer, daß er sie zum Munde bringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Ein Fauler dunkt sich weiserdenn sieben, die da Sitten lehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Wer vorgehet und sich menget in fremden Hader, der ist wie einer, der den Hund bei den Ohren zwacket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Wie einer heimlich mit Geschoft und Pfeilen schieftt und totet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'also tut ein falscher Mensch mit seinem Nachsten und spricht danach: Ich habe gescherzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Wenn nimmer Holz da ist, so verloscht das Feuer, und wenn der Verleumder weg ist, so horet der Hader auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Wie die Kohlen eine Glut und Holz ein Feuer, also richtet ein zankischer Mann Hader an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Die Worte des Verleumders sind wie Schlage und sie gehen durchs Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Giftiger Mund und boses Herz ist wie ein Scherben mit Silberschaum uberzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Der Feind wird erkannt bei seiner Rede, wiewohl er im Herzen falsch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Wenn er seine Stimme holdselig macht, so glaube ihm nicht; denn es sind sieben Greuel in seinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Wer den Haft heimlich halt, Schaden zu tun, des Bosheitwird vor der Gemeine offenbarwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Wer eine Grube macht, der wird dreinfallen; und wer einen Stein walzet, auf den wird er kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Eine falsche Zunge hasset, der ihn strafet; und ein Heuchelmaul richtet Verderben an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Rühme dich nicht des morgenden Tages; denn du weiftest nicht, was heute sich begeben mag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Laft dich einen andern loben und nicht deinen Mund, einen Fremden und nicht deine eigenen Lippen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Stein ist schwer und Sand ist Last; aber des Narren Zorn ist schwerer denn die beiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Zorn ist ein wutig Ding, und Grimm ist ungestum; und wer kann vor dem Neid bestehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Offentliche Strafe ist besser denn heimliche Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Die Schlage des Liebhabers meinen\'s recht gut; aber das Kussen des Hassers ist ein Gewasch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Eine voile Seele zertritt wohl Honigseim; aber einer hungrigen Seele ist alles Bittre suft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Wie ein Vogel ist, der aus seinem Nest weicht, also ist, der von seiner Statte weicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Das Herz freuet sich der Salbe und Rauchwerk; aber ein Freund ist lieblich urn Rats willen der Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Deinen Freund und deines Vaters Freund verlaft nicht. Und gehe nicht ins Haus deines Bruders, wenn dir\'s ubel gehet; denn ein Nachbar ist besser in der Nahe weder ein Bruder in der Feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sei weise, mein Sohn, so freuet sich mein Herz, so will ich antworten dem, der mich schmahet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Ein Witziger siehet das Ungluck und verbirgt sich; aber die Albernen gehen durch und leiden Schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Nimm dem sein Kleid der fur einen andern Burge wird, und pfande ihn urn der Fremden willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Werseinen Nachsten mit lauter Stimme segnet und fruh aufstehet, das wird ihm fur einen Fluch geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Ein zankisch Weib und stetiges Triefen, wenn\'s sehr regnet, werden wohl miteinander verglichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Wer sie aufhalt, der halt den Wind und will das 01 mit der Hand fassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Ein Messer wetzt das andere und ein Mann den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Werseinen Feigenbaum bewahret, derisset Fruchte davon; und wer seinen Herrn bewahret, wird geehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Wie der Schemen im Wasser ist gegen das Angesicht, also ist eines Menschen Herz gegen den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Holle und Verderbnis werden nimmer voll, und der Menschen Augen sind auch unsattig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Ein Mann wird durch den Mund des Lobers bewahret wie das Silber im Tiegel und das Gold im Ofen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Wenn du den Narren im Morser zerstieftest mit dem Stampfel wie Grutze, so ließe doch seine Narrheit nicht von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Auf deine Schafe hab acht und nimm dich deiner Herde an;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'denn Gut wahret nicht ewiglich, und die Krone wahret nicht fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Das Heu ist aufgegangen und ist da das Gras, und wird Kraut auf den Bergen gesammelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Die Lammer kleiden dich, und die Bocke geben dir das Ackergeld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Du hast Ziegenmilch genug zur Speise deines Hauses und zur Nahrung deiner Dirnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Der Gottlose fleucht, und niemand jagt ihn; der Gerechte aber ist getrost wie ein junger Lowe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Um des Landes Sunde willen werden viel Anderungen der Furstentumer; aber um der Leute willen, die verstandig und vernunftig sind, bleiben sie lange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Ein armer Mann, der die Geringen beleidigt, ist wie ein Meltau, der die Frucht verderbt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Die das Gesetz veriassen, loben den Gottlosen; die es aber bewahren, sind unwillig auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Bose Leute merken nicht aufs Recht; die aber nach dem HERRN fragen, merken auf alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Es ist besser ein Armer, der in seiner Frommigkeit gehet, denn ein Reicher, der in verkehrten Wegen gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Wer das Gesetz bewahret, ist ein verstandig Kind; wer aber Schlemmer nahret, schandet seinen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Wer sein Gut mehret mit Wucher und Ubersatz, der sammelt es zu Nutz der Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Wer sein Ohr abwendet, zu horen das Gesetz, des Gebet ist ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Wer die Frommen verfuhret auf bosem Wege, der wird in seine Grube fallen; aber die Frommen werden Gutes ererben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Ein Reicher dünkt sich weise sein; aber ein armer Verstandiger merkt ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Wenn die Gerechten uberhand haben, so gehet es sehr fein zu; wenn aber Gottlose aufkommen, wendet sich\'s unterden Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Wer seine Missetat leugnet, dem wird\'s nicht gelingen; wer sie aber bekennet und lasset, der wird Barmherzigkeit erlangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Wohl dem, der sich allewege furchtet! Wer aber halsstarrig ist, wird in Ungluck fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Ein Gottloser, der uber ein arm Volk regieret, das ist ein brullender Lowe und gieriger Bar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Wenn ein Furst ohne Verstand ist, so geschiehet viel Unrechts; wer aber den Geiz hasset, der wird lange leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ein Mensch, der am Blut einer Seele unrecht tut, der wird nicht erhalten, ob er auch in die Holle führe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Werfromm einhergehet, wird genesen; wer aber verkehrtes Weges ist, wird auf einmal zerfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Wer seinen Acker bauet, wird Brots genug haben; wer aber Mulüggang nachgehet, wird Armuts genug haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Ein treuer Mann wird viel gesegnet; wer aber eilet, reich zu werden, wird nicht unschuldig bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Person ansehen ist nicht gut; denn er tate ubel auch wohl um ein Stuck Brots.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Wer eilet zum Reichtum und ist neidisch, der weili nicht, daß ihm Unfall begegnen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Wer einen Menschen straft, wird hernach Gunst finden, denn der da heuchelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Wer seinem Vater Oder Mutter nimmt und spricht, es sei nicht Sunde, der ist des Verderbers Geselle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Ein Stolzer erweckt Zank; wer aber auf den HERRN sich verlalit, wird fett.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Wer sich auf sein Herz verlalit, ist ein Narr; wer aber mit Weisheit gehet, wird entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Wer dem Armen gibt, dem wird nicht mangeln; wer aber seine Augen abwendet, der wird sehr verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Wenn die Gottlosen aufkommen, so verbergen sich die Leute; wenn sie aber umkommen, wird der Gerechten viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Wer wider die Strafe halsstarrig, ist, der wird plotzlich verderben ohne aile Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Wenn der Gerechten viel ist, freuet sich das Volk; wenn aber der Gottlose herrschet, seufzet das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Wer Weisheit liebet, erfreuet seinen Vater; wer aber mit Huren sich nahret, kommt um sein Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Ein Konig richtet das Land auf durchs Recht; ein Geiziger aber verderbet es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Wer mit seinem Nachsten heuchelt, der breitet ein Netz zu seinen Fußtapfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Wenn ein Boser sundiget, verstrickt er sich selbst; aber ein Gerechter freuet sich und hat Wonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Der Gerechte erkennet die Sache der Armen; der Gottlose achtet keine Vernunft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Die Spotter bringen frechlich eine Stadt in Ungluck; aber die Weisen stillen den Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Wenn ein Weiser mit einem Narren zu handeln kommt, er züme Oder lache, so hat er nicht Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Die Blutgierigen hassen den Frommen; aber die Gerechten suchen seine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Ein Narr schuttet seinen Geist gar aus; aber ein Weiser halt an sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Ein Herr, der zu Lugen Lust hat, des Diener sind aile gottlos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Arme und Reiche begegnen einander; aber beider Augen erleuchtet der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Ein Konig, der die Armen treulich richtet, des Thron wird ewiglich bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rute und Strafe gibt Weisheit; aberein Knabe, ihm selbst gelassen, schandet seine Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Wo viel Gottlose sind, da sind viel Sunden; aberdie Gerechten werden ihren Fall erleben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Zuchtige deinen Sohn, so wird erdich ergotzen und wird deiner Seele sanft tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Wenn die Weissagung aus ist, wird das Volk wild und wust; wohl aber dem, der das Gesetz handhabet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Ein Knecht laftt sich mit Worten nicht zuchtigen; denn ob er\'s gleich verstehet, nimmt er sich\'s doch nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Siehest du einen schnell zu reden, da ist an einem Narren mehr Hoffnung denn an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Wenn ein Knecht von Jugend auf zartlich gehalten wird, so will er danach ein Junker sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Ein zorniger Mann richtet Hader an, und ein Grimmiger tut viel Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Die Hoffart des Menschen wird ihn sturzen; aber der Demutige wird Ehre empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Wer mit Dieben teil hat, hort fluchen und sagt\'s nicht an, der hasset sein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Vor Menschen sich scheuen, bringet zu Fall; wer sich aber auf den HERRN verlasset, wird beschutzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Viele suchen das Angesicht eines Fursten; aber eines jeglichen Gericht kommt vom FIERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Ein ungerechter Mann ist dem Gerechten ein Greuel, und wer rechtes Weges ist, der ist des Gottlosen Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Dies sind die Worte Agurs, des Sohns Jakes, Lehre und Rede des Mannes Leithiel, Leithiel und Uchal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Denn ich bin der allernarrischste, und Menschenverstand ist nicht bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Ich habe Weisheit nicht gelernet, und was heilig sei, weifi ich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Werfahret hinauf gen Himmel und herab? Wer fasset den Wind in seine Hande? Wer bindet die Wasser in ein Kleid? Wer hat alle Enden der Welt gestellet? Wie heifit er und wie heifit sein Sohn? Weifit du das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Alle Worte Gottes sind durchlautert und sind ein Schild denen, die auf ihn trauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Tue nichts zu seinen Worten, daß er dich nicht strafe, und werdest lugenhaftig erfunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Zweierlei bitte ich von dir, die wollest du mir nicht weigern, ehe denn ich sterbe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Abgotterei und Lügen laft feme von mir sein; Armut und Reichtum gib mir nicht; laft mich aber mein bescheiden Teil Speise dahinnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Ich mochte sonst, wo ich zu satt wurde, verleugnen und sagen: Wer ist der HERR? Oder wo ich zu arm wurde, mochte ich stehlen und mich an dem Namen meines Gottes vergreifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Verrate den Knecht nicht gegen seinen HERRN; er mochte dir fluchen und du die Schuld tragen müssest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Es ist eine Art, die ihrem Vater flucht und ihre Mutter nicht segnet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'eine Art, die sich rein dünkt und ist doch von ihrem Kot nicht gewaschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'eine Art, die ihre Augen hoch tragt und ihre Augenlideremporhalt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'eine Art, die Schwerter fur Zahne hat, die mit ihren Backenzahnen friftt und verzehret die Elenden im Lande und die Armen unterden Leuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Die Igel hat zwo Tochter: Bring her, bring her! Drei Dinge sind nicht zu sattigen, und das vierte spricht nicht: Es istgenug:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'die Holle, der Frauen verschlossene Mutter, die Erde wird nicht Wassers satt, und das Feuer spricht nicht: Es ist genug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Ein Auge das den Vater verspottet und verachtet, der Mutter zu gehorchen, das müssen die Raben am Bach aushacken und die jungen Adler fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Drei Dinge sind mirzuwunderlich, und das vierte weift ich nicht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'des Adlers Weg im Himmel, der Schlangen Weg auf einem Felsen, des Schiffs Weg mitten im Meer und eines Mannes Weg an einer Magd.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Also ist auch der Weg der Ehebrecherin; die verschlinget und wischet ihr Maul und spricht: Ich habe kein Ubels getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Ein Land wird durch dreierlei unruhig, und das vierte mag es nicht ertragen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'ein Knecht, wenn er Konig wird; ein Narr, wenn er zu satt ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'eine Feindselige, wenn sie geehelicht wird, und eine Magd, wenn sie ihrer Frauen Erbe wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Vier sind klein auf Erden und kluger denn die Weisen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'die Ameisen, ein schwach Volk, dennoch schaffen sie im Sommer ihre Speise;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Kaninchen, ein schwach Volk, dennoch legt es sein Haus in den Felsen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Heuschrecken haben, keinen Konig, dennoch ziehen sie aus ganz mit Haufen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'die Spinne wirkt mit ihren Handen und ist in der Konige Schlossern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Dreierlei haben einen feinen Gang, und das vierte gehetwohl:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Der Lowe, machtig unter den Tieren, und kehrt nicht urn vorjemand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'ein Wind von guten Lenden; und ein Widder; und der Konig, wider den sich niemand darf legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Hast du genarret und zu hoch gefahren und Boses vorgehabt, so lege die Hand aufs Maul.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Wenn man Milch stoftt, so macht man Butter draus; und wer die Nase hart schneuzet, zwingt Blut heraus; und wer den Zorn reizet, zwingt Hader heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Dies sind die Worte des Konigs Lamuel, die Lehre, die ihn seine Mutter lehrete:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Ach, mein Auserwahlter, ach, du Sohn meines Leibes, ach, mein gewünschter Sohn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'la ft nicht den Weibern dein Vermogen und gehe die Wege nicht, darin sich die Konige verderben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, '0, nicht den Konigen, Lamuel, gib den Konigen nicht Wein zu trinken noch den Fursten stark Getranke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Sie mochten trinken und der Rechte vergessen und verandern die Sache irgend der elenden Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Gebet stark Getranke denen, die umkommen sollen, und den Wein den betrubten Seelen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'daß sie trinken und ihres Elendes vergessen und ihres Unglucks nicht mehr gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Tu deinen Mund auf fur die Stummen und fur die Sache alter, die verlassen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Tu deinen Mund auf und richte recht und rache den Elenden und Armen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Wem ein tugendsam Weib bescheret ist, die ist viel edler denn die kostlichsten Perlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Ihres Mannes Herzdarf sich auf sie verlassen, und Nahrung wird ihm nicht mangeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Sie tut ihm Liebes und kein Leides sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Sie gehet mit Wolle und Flachs um und arbeitet gerne mitihren Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Sie istwie ein Kaufmannsschiff, das seine Nahrung von feme bringt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Sie stehet des Nachts auf und gibt Futter ihrem Flause und Essen ihren Dirnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Sie denkt nach einem Acker und kauft ihn und pflanzt einen Weinberg von den Fruchten ihrer FHande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Sie gurtet ihre Lenden fest und starkt ihre Arme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Sie merkt, wie ihr Handel Frommen bringt; ihre Leuchte verloscht des Nachts nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Sie streckt ihre Hand nach dem Rocken, und ihre Finger fassen die Spindel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Sie breitet ihre Hande aus zu dem Armen und reichet ihre Hand dem Durftigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Sie furchtet ihres Hauses nicht vor dem Schnee, denn ihr ganzes Haus hat zwiefache Kleider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Sie macht ihr selbst Decken; weifte Seide und Purpur ist ihr Kleid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Ihr Mann ist berühmt in den Toren, wenn er sitzt bei den Altesten des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Sie macht einen Rock und verkauft ihn; einen Gürtel gibt sie dem Kramer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Ihr Schmuck ist, daß sie reinlich und fleiftig ist; und wird hernach lachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Sie tut ihren Mund auf mit Weisheit, und auf ihrer Zunge ist holdselige Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Sie schauet, wie es in ihrem Hause zugehet, und isset ihr Brot nicht mit Faulheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Ihre Sohne kommen auf und preisen sie selig; ihr Mann lobt sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Viele Tochter bringen Reichtum; du aber übertriffst sie alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Lieblich und schon sein ist nichts; ein Weib, das den HERRN furchtet, soil man loben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Sie wird gerühmt werden von den Fruchten ihrer Hande; und ihre Werke werden sie loben in den Toren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Dies sind die Reden des Predigers, des Sohns Davids, des Konigs zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Es ist alles ganz eitel, sprach der Prediger, es ist alles ganz eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Was hat der Mensch mehr von all seiner Mühe, die er hat unter der Sonne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Ein Geschlecht vergehet, das andere kommt; die Erde aber bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Die Sonne gehet auf und gehet unter und lauft an ihren Ort, daß sie wieder daselbst aufgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Der Wind gehet gen Mittag und kommt herum zur Mitternacht und wieder herum an den Ort, da er anting.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Alle Wasser laufen ins Meer, noch wird das Meer nicht voller; an den Ort, da sie herfließen, flielien sie wider hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Es ist alles Tun so voll Mühe, daß niemand ausreden kann. Das Auge siehet sich nimmer satt und das Ohr horet sich nimmer satt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Was ist\'s, das geschehen ist? Eben das hernach geschehen wird. Was ist\'s, das man getan hat? Eben das man hernach wieder tun wird; und geschieht nichts Neues unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Geschieht auch etwas, davon man sagen mochte: Siehe, das ist neu? Denn es ist zuvor auch geschehen in vorigen Zeiten, die vor uns gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Man gedenkt nicht, wie es zuvor geraten ist; also auch des, das hernach kommt, wird man nicht gedenken bei denen, die hernach sein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ich, Prediger, war Konig über Israel zu Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'und begab mein Herz, zu suchen und zu forschen weislich alles, was man unter dem Himmel tut. Solche unselige Mühe hat Gott den Menschenkindern gegeben, daß sie sich drinnen müssen qualen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Ich sah an alles Tun, das unter der Sonne geschieht; und siehe, es war alles eitel und Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Krumm kann nicht schlecht werden, noch der Fehl gezahlet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Ich sprach in meinem Herzen: Siehe, ich bin herrlich worden und habe mehr Weisheit denn alle, die vor mir gewesen sind zu Jerusalem; und mein Herz hat viel gelernt und erfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Und gab auch mein Herzdrauf, daß ich lernete Weisheit und Torheit und Klugheit. Ich ward aber gewahr, daß solches auch Mühe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Denn wo viel Weisheit ist, da ist viel Gramens; und werviel lehren, mu(i, der muli viel leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Ich sprach in meinem Herzen: Wohlan, ich will wohlleben und gute Tage haben. Aber siehe, das war auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Ich sprach zum Lachen: Du bist toll und zur Freude: Was machst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Da dachte ich in meinem Herzen, meinen Leib vom Wein zu ziehen und mein Herz zur Weisheit zu ziehen, daß ich ergriffe, was Torheit ist, bis ich lernete, was den Menschen gut ware, das sie tun sollten, solange sie unter dem Himmel leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Ich tat grolie Dinge; ich bauete Hauser, pflanzte Weinberge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'ich machte mir Garten und Lustgarten und pflanzte allerlei fruchtbare Baume drein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'ich machte mir Teiche, daraus zu wassern den Wald dergrunenden Baume.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Ich hatte Knechte und Magde und Gesinde; ich hatte eine groliere Habe an Rindern und Schafen denn alle, die vor mir zu Jerusalem gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Ich sammelte mir auch Silber und Gold und von den Konigen und Landern einen Schatz. Ich schaffte mir Sanger und Sangerinnen und Wollust der Menschen, allerlei Saitenspiel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'und nahm zu über alle, die vor mir zu Jerusalem gewesen waren; auch blieb Weisheit bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Und alles, was meine Augen wünschten, das ließ ich ihnen, und wehrete meinem Herzen keine Freude, daß es frohlich war von aller meiner Arbeit; und das hielt ich fur mein Teil von aller meiner Arbeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Da ich aber ansah alle meine Werke, die meine Hand getan hatte, und Mühe, die ich gehabt hatte, siehe, da war es alles eitel und Jammer und nichts mehr unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Da wandte ich mich, zu sehen die Weisheit und Klugheit und Torheit. Denn wer weiß, was der fur ein Mensch werden wird nach dem Konige, den sie schon bereit gemacht haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Da sah ich, daß die Weisheit die Torheit übertraf, wie das Licht die Finsternis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'daß dem Weisen seine Augen im Haupt stehen; aber die Narren in Finsternis gehen, und merkte doch, daß es einem gehet wie dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Da dachte ich in meinem Herzen: Weil es denn dem Narren gehet wie mir, warum habe ich denn nach Weisheit gestanden? Da dachte ich in meinem Herzen, daß solches auch eitel sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Denn man gedenkt des Weisen nicht immerdar, ebensowenig als des Narren; und die kunftigen Tage vergessen alles; und wie der Weise stirbt, also auch der Narr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Darum verdroli mich zu leben; denn es gefiel mir ubel, was unter der Sonne geschieht, daß es so gar eitel und Mühe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Und mich verdroli alle meine Arbeit, die ich unter der Sonne hatte, daß ich dieselbe einem Menschen lassen mülite, der nach mir sein sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Denn werweili, ob er weise Oder toll sein wird? Und soil doch herrschen in aller meiner Arbeit, die ich weislich getan habe unter der Sonne. Das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Darum wandte ich mich, daß mein Herz ablielie von aller Arbeit; die ich tat unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Denn es muli ein Mensch, der seine Arbeit mit Weisheit, Vernunft und Geschicklichkeit getan hat, einem andern zum Erbteil lassen, der nicht dran gearbeitet hat. Das ist auch eitel und ein groli Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Denn was kriegt der Mensch von aller seiner Arbeit und Muhe seines Herzens, die er hat unter der Sonne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'denn alle seine Lebtage Schmerzen, mit Gramen und Leid, daß auch sein Herz des Nachts nicht ruhet? Das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Ist\'s nun nicht besser dem Menschen, essen und trinken und seine Seele guter Dinge sein in seiner Arbeit? Aber solches sah ich auch, daß von Gottes Hand kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Denn wer hat frohlicher gegessen und sich ergotzet denn ich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Denn dem Menschen, der ihm gefallt, gibt er Weisheit, Vernunft und Freude; aber dem Sunder gibt er Ungluck, daß er sammle und haufe und doch dem gegeben werde, der Gott gefallt. Darum ist das auch eitel Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Ein jegliches hat seine Zeit, und alles Vornehmen unter dem Himmel hat seine Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Geboren werden, Sterben, Pflanzen, Ausrotten, das gepflanzt ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Würgen, Heilen, Brechen, Bauen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Weinen, Lachen, Klagen, Tanzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Steine zerstreuen, Steine sammeln, Herzen, Fernen von Herzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Suchen, Verlieren, Behalten, Wegwerfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Zerreifien, Zunahen, Schweigen, Reden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Lieben, Hassen, Streit, Friede hat seine Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Man arbeite, wie man will, so kann man nicht mehr ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Dahersah ich die Muhe, die Gott den Menschen gegeben hat, daß sie drinnen geplagt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Er aber tut alles fein zu seiner Zeit und lalit ihr Herz sich angsten, wie es gehen solle in der Welt; denn der Mensch kann doch nicht treffen das Werk, das Gott tut, weder Anfang noch Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Darum merkte ich, daß nichts Besseres drinnen ist, denn frdhlich sein und ihm gutlich tun in seinem Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Denn eine jeglicher Mensch, der da isset und trinkt und hat guten Mut in all seiner Arbeit, das ist eine Gabe Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Ich merkte, daß alles, was Gott tut, das bestehet immer; man kann nichts dazutun noch abtun; und solches tut Gott, daß man sich vor ihm furchten soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Was Gott tut, das stehet da; und was er tun will, das muli werden; denn er trachtet und jagt ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Weitersah ich unter der Sonne Stattedes Gerichts, da war ein gottlos Wesen, und Statte der Gerechtigkeit, da waren Gottlose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Da dachte ich in meinem Herzen: Gott muli richten den Gerechten und Gottlosen; denn es hat ailes Vornehmen seine Zeit und alle Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Ich sprach in meinem Herzen von dem Wesen der Menschen, darin Gott anzeigt und lalit es ansehen, als waren sie unter sich selbst wie das Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Denn es gehet dem Menschen wie dem Vieh: wie dies stirbt, so stirbt er auch, und haben alle einerlei Odem; und der Mensch hat nichts mehr denn das Vieh; denn es ist alles eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Es fahret alles an einen Ort; es ist alles von Staub gemacht und wird wieder zu Staub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Wer weili, ob der Odem der Menschen aufwarts fahre und der Odem des Viehes unterwarts unter die Erde fahre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Darum sah ich, daß nichts Besseres ist, denn daß ein Mensch frohlich sei in seiner Arbeit; denn das ist sein Teil. Denn wer will ihn dahin bringen, daß er sehe was nach ihm geschehen wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Ich wandte mich und sah alle, die Unrecht leiden unter der Sonne; und siehe, da waren Tranen derer, so Unrecht litten und hatten keinen Troster; und die ihnen Unrecht taten, waren zu machtig, daß sie keinen Troster haben konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Da lobte ich die Toten, die schon gestorben waren, mehr denn die Lebendigen, die noch das Leben hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Und der noch nicht ist, ist besser denn alle beide, und des Bosen nicht inne wird, das unter der Sonne geschieht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Ich sah an Arbeit und Geschicklichkeit in alien Sachen; da neidet einer den andern. Das ist je auch eitel und Muhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Denn ein Narr schlagt die Finger ineinander und frilit sein Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Es ist besser eine Hand voll mit Ruhe denn beide Fauste voll mit Muhe und Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Ich wandte mich und sah die Eitelkeit unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Es ist ein einzelner und nicht selbander und hat weder Kind noch Bruder; noch ist seines Arbeitens kein Ende, und seine Augen werden Reichtums nicht satt. Wem arbeite ich doch und breche meiner Seele ab? Das istje auch eitel und eine bose Muhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'So ist\'s je besser zwei denn eins; denn sie genielien doch ihrer Arbeit wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Fallt ihrer einer, so hilftihm sein Gesell auf. Wehe dem, der allein ist! Wenn er fallt, so ist kein anderer da, der ihm aufhelfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Auch wenn zwei beieinander liegen, warmen sie sich; wie kann ein einzelner warm werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Einer mag uberwaltiget werden, aberzween mogen widerstehen; denn eine dreifaltige Schnur reißt nicht leicht entzwei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Ein arm Kind, das weise ist, ist besser denn ein alter Konig, der ein Narr ist und weiß sich nicht zu huten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Es kommt einer aus dem Gefangnis zum Konigreich; und einer, der in seinem Konigreich geboren ist, verarmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Und ich sah, daß alle Lebendigen unterder Sonne wandeln bei einem andern Kinde, das an jenes Statt soil aufkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Und des Volks, das vor ihm ging, war kein Ende, und des, das ihm nachging; und wurden sein doch nicht froh. Das ist je auch eitel und ein Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 17, 'Bewahre deinen Fufi, wenn du zum Hause Gottes gehest, und komm, daß du horest! Das ist besser denn der Narren Opfer; denn sie wissen nicht, was sie Boses tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Sei nicht schnell mit deinem Munde und lafi dein Herz nicht eilen, etwas zu reden vor Gott; denn Gott ist im Himmel und du auf Erden; darum laß deiner Worte wenig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Denn wo viel Sorgen ist, da kommen Traume; und wo viele Worte sind, da horet man den Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Wenn du Gott ein Gelubde tust, so verzeuch\'s nicht zu halten; denn er hat kein Gefallen an den Narren. Was du gelobest, das halte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Es ist besser, du gelobest nichts, denn daß du nicht haltst, was du gelobest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Verhange deinem Mund nicht, daß er dein Fleisch verfuhre, und sprich vor dem Engel nicht: Ich bin unschuldig. Gott mochte erzurnen über deine Stimme und verdammen alle Werke deiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Wo viel Traume sind, da ist Eitelkeit und viel Worte; aber furchte du Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Siehest du dem Armen Unrecht tun und Recht und Gerechtigkeit im Lande wegreilien, wundere dich des Vornehmens nicht; denn es ist noch ein hoher Huter über den Hohen, und sind noch Hohere über die beiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Uber das ist der Konig im ganzen Lande, das Feld zu bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Wer Geld liebt, wird Gelds nimmersatt; wer Reichtum liebt, wird keinen Nutz davon haben. Das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Denn wo viel Guts ist, da sind viele, die es essen; und was geneußt sein, der es hat, ohne daß er\'s mit Augen ansiehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Werarbeitet, dem ist der Schlaf süß, er habe wenig Oder viel gegessen; aber die Fülle des Reichen laßt ihn nicht schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Es ist eine bose Plage, die ich sah unter der Sonne, Reichtum behalten zum Schaden dem, der ihn hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Denn der Reiche kommt urn mit großem Jammer; und so er einen Sohn gezeuget hat, dem bleibt nichts in der Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Wie er nackend ist von seiner Mutter Leibe kommen, so fahrt er wieder hin, wie er kommen ist, und nimmt nichts mit sich von seiner Arbeit in seiner Hand, wenn er hinfahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Das ist eine bose Plage, da er hinfahret, wie er kommen ist. Was hilft\'s ihm denn, daß er in den Wind gearbeitet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Sein Leben, lang hat er im Finstern gegessen und in großem Gramen und Krankheit und Traurigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'So sehe ich nun das fur gut an, daß esfein sei, wenn man isset und trinket und gutes Muts ist in aller Arbeit, die einer tut unter der Sonne sein Leben lang, das ihm Gott gibt; denn das ist sein Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Denn welchem Menschen Gott Reichtum und Güter und Gewalt gibt, daß er davon isset und trinket fur sein Teil und frohlich ist in seiner Arbeit, das ist eine Gottesgabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Denn erdenkt nicht viel an das elende Leben, weil Gott sein Herz erfreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Es ist ein Ungluck, das ich sah unter der Sonne, und istgemein bei den Menschen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Einer, dem Gott Reichtum, Güter und Ehre gegeben hat, und mangelt ihm keines, das sein Herz begehrt, und Gott doch ihm nicht Macht gibt, desselben zu genießen, sondern ein anderer verzehret es; das ist eitel und eine bose Plage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Wenn ergleich hundert Kinder zeugete und hatte so langes Leben, daß erviel Jahre überlebete, und seine Seele sattigte sich des Guts nicht und bliebe ohne Grab, von dem spreche ich, daß eine unzeitige Geburt besser sei denn er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Denn in Eitelkeit kommt er und in Finsternis fahret er dahin, und sein Name bleibt in Finsternis bedeckt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'wird der Sonne nicht froh und weiß keine Ruhe weder hie noch da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Ob er auch zweitausend Jahre lebete, so hat er nimmer keinen guten Mut. Kommt\'s nicht alles an einen Ort?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Einem jeglichen Menschen ist Arbeit aufgelegt nach seinem Maße; aber das Herz kann nicht dran bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Denn was richtet ein Weiser mehr aus weder ein Narr? Was unterstehet sich der Arme, daß er unter den Lebendigen will sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Es ist besser, das gegenwartige Gut gebrauchen, denn nach anderm gedenken. Das ist auch Eitelkeit und Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Was ist\'s, wenn einer gleich hoch beruhmt ist, so weiß man doch, daß erein Mensch ist, und kann nicht hadern mit dem, das ihm zu machtig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Denn es ist des eiteln Dinges zu viel; was hat ein Mensch mehr davon?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Denn wer weili, was dem Menschen nütz ist im Leben, solange er lebet in seiner Eitelkeit, welches dahinfahret wie ein Schatten? Oder wer will dem Menschen sagen, was nach ihm kommen wird unter der Sonne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Ein gut Gerucht ist besser denn gute Salbe und der Tag des Todes weder der Tag der Geburt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Es ist besser, in das Klaghaus gehen denn in das Trinkhaus; in jenem ist das Ende aller Menschen, und der Lebendige nimmt\'s zu Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Es ist Trauern besser denn Lachen; denn durch Trauern wird das Herz gebessert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Das Herz der Weisen ist im Klaghause und das Herz der Narren im Hause der Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Es ist besser horen das Schelten des Weisen denn horen den Gesang der Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Denn das Lachen des Narren ist wie das Krachen der Dornen unter den Topfen; und das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Ein Widerspenstiger macht einen Weisen unwillig und verderbt ein mildes Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Das Ende eines Dinges ist besser denn sein Anfang. Ein geduldiger Geist ist besser denn ein hoher Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Sei nicht schnelles Gemüts zu zurnen; denn Zorn ruhet im Herzen eines Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Sprich nicht: Was ist\'s, daß die vorigen Tage besser waren denn diese? Denn du fragest solches nicht weislich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Weisheit ist gut mit einem Erbgut und hilft, daß sich einer der Sonne freuen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Denn die Weisheit beschirmet, so beschirmet Geld auch; aber die Weisheit gibt das Leben dem, der sie hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Siehe an die Werke Gottes, denn wer kann das schlecht machen, das er krummet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Am guten Tage sei guter Dinge und den bosen Tag nimm auch fur gut; denn diesen schaffet Gott neben jenem, daß der Mensch nicht wissen soli, was kunftig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Allerlei habe ich gesehen die Zeit uber meiner Eitelkeit. Da ist ein Gerechter und gehet unter in seiner Gerechtigkeit, und ist ein Gottloser, der lange lebt in seiner Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Sei nicht allzu gerecht und nicht allzu weise, daß du dich nicht verderbest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Sei nicht allzu gottlos und name nicht, daß du nicht sterbest zur Unzeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Es ist gut, daß du dies fassest und jenes auch nicht aus deiner Hand lassest; denn wer Gott furchtet, der entgehet dem allem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Die Weisheit starkt den Weisen mehr denn zehn Gewaltige, die in der Stadt sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Denn es ist kein Mensch auf Erden, der Gutes tue und nicht sündige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Nimm auch nicht zu Herzen alles, was man sagt, daß du nicht horen mussest deinen Knecht dir fluchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Denn dein Herz weili, daß du andern auch oftmals geflucht hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Solches alles habe ich versucht weislich. Ich gedachte, ich will weise sein; sie kam aber ferner von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Es ist feme; was wird\'s sein? und ist sehr tief; wer will\'s finden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Ich kehrete mein Herz, zu erfahren und zu erforschen und zu suchen Weisheit und Kunst, zu erfahren der Gottlosen Torheit und Irrtum der Tollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'und fand, daß ein solches Weib, welches Herz Netz und Strick ist und ihre Hande Bande sind, bitterer sei denn der Tod. Wer Gott gefallt, der wird ihr entrinnen; aber der Sunder wird durch sie gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Schaue, das habe ich funden, spricht der Prediger, eins nach dem andern, daß ich Kunst erfande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Und meine Seele sucht noch und hat es nicht funden. Unter tausend habe ich einen Menschen funden, aber kein Weib habe ich unter den alien funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Alleine schaue das, ich habe funden, daß Gott den Menschen hat aufrichtig gemacht; aber sie suchen viel Künste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Wer ist so weise? und wer kann das auslegen? Die Weisheit des Menschen erleuchtet sein Angesicht; wer aber frech ist, der ist feindselig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Ich halte das Wort des Konigs und den Eid Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Eile nicht, zu gehen von seinem Angesicht, und bleibe nicht in boser Sache; denn er tut, was ihn gelustet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'In des Konigs Wort ist Gewalt, und wer mag zu ihm sagen: Was machst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Wer das Gebot halt, der wird nichts Boses erfahren; aber eines Weisen Herz weili Zeit und Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Denn ein jeglich Vornehmen hat seine Zeit und Weise; denn des Unglucks des Menschen ist viel bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Denn er weili nicht, was gewesen ist; und wer will ihm sagen, was werden soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ein Mensch hat nicht Macht uber den Geist, dem Geist zu wehren; und hat nicht Macht zur Zeit des Sterbens und wird nicht losgelassen im Streit; und das gottlose Wesen errettet den Gottlosen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Das habe ich alles gesehen und gab mein Herz auf alle Werke, die unter der Sonne geschehen. Ein Mensch herrschet zuzeiten über den andern zu seinem Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Und da sah ich Gottlose, die begraben waren, die gegangen waren und gewandelt in heiliger Statte, und waren vergessen in der Stadt, daß sie so getan hatten. Das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Weil nicht bald geschieht ein Urteil fiber die bosen Werke, dadurch wird das Herz der Menschen voll, Boses zutun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Ob ein Sunder hundertmal Boses tut und doch lange lebt, so weiß ich doch, daß es wohlgehen wird denen, die Gott furchten, die sein Angesicht scheuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Denn es wird dem Gottlosen nicht wohlgehen und wie ein Schatten nicht lange leben, die sich vor Gott nicht furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Es ist eine Eitelkeit, die auf Erden geschieht. Es sind Gerechte, denen gehet es, als hatten sie Werke der Gottlosen, und sind Gottlose, denen gehet es, als hatten sie Werke der Gerechten. Ich sprach: Das ist auch eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Darum lobte ich die Freude, daß der Mensch nichts Besseres hat unter der Sonne denn essen und trinken und frohlich sein; und solches werde ihm von der Arbeit sein Leben lang, das ihm Gott gibt unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Ich gab mein Herz, zu wissen die Weisheit und zu schauen die Mühe, die auf Erden geschieht, dafi auch einer weder Tag noch Nacht den Schlaf siehet mit seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Und ich sah alle Werke Gottes. Denn ein Mensch kann das Werk nicht finden, das unter der Sonne geschieht; und je mehr der Mensch arbeitet zu suchen, je weniger er findet. Wenn er gleich spricht: Ich bin weise und weifi es, so kann er\'s doch nicht finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Denn ich habe solches alles zu Herzen genommen, zu forschen das alles, dad Gerechte und Weise sind und ihre Untertanen in Gottes Hand. Doch kennet kein Mensch weder die Liebe noch den Half, irgendeines, den er vor sich hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Es begegnet einem wie dem andern, dem Gerechten wie dem Gottlosen, dem Guten und Reinen wie dem Unreinen, dem der opfert, wie dem, der nicht opfert. Wie es dem Guten gehet, so gehet es auch dem Sunder. Wie es dem Meineidigen gehet, so gehet es auch dem, der den Eid furchtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Das ist ein boses Ding unter ailem, das unter der Sonne geschieht, daß es einem gehet wie dem andern; daher auch das Herz der Menschen voll Arges wird, und Torheit ist in ihrem Herzen, dieweil sie leben; danach müssen sie sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Denn bei alien Lebendigen ist, das man wunschet, namlich Hoffnung; denn ein lebendiger Hund ist besser weder ein toter Lowe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Denn die Lebendigen wissen, daß sie sterben werden; die Toten aber wissen nichts, sie verdienen auch nichts mehr, denn ihr Gedachtnis ist vergessen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'da(S man sie nicht mehr liebet, noch hasset, noch neidet, und haben kein Teil mehr auf der Welt in ailem, das unter der Sonne geschieht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'So gehe hin und ill dein Brot mit Freuden, trink deinen Wein mit gutem Mut; denn dein Werk gefallt Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Lali deine Kleider immer weiß sein und laß deinem Haupte Salbe nicht mangeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Brauche des Lebens mit deinem Weibe, das du lieb hast, solange du das eitle Leben hast, das dir Gott unter der Sonne gegeben hat, solange dein eitel Leben wahret; denn das ist dein Teil im Leben und in deiner Arbeit, die du tust unter der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Alles, was dir vorhanden kommt zu tun, das tue frisch; denn in der Holle, da du hinfahrest, ist weder Werk, Kunst, Vernunft noch Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Ich wandte mich und sah, wie es unter der Sonne zugehet, daß zu laufen nicht hilft schnell sein, zum Streit hilft nicht stark sein, zur Nahrung hüft nicht geschickt sein, zum Reichtum hilft nicht klug sein; daß einer angenehm sei, hüft nicht, daß er ein Ding wohl konne, sondern alles liegt es an der Zeit und Gluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Auch weiß der Mensch seine Zeit nicht, sondern wie die Fische gefangen werden mit einem schadlichen Hamen, und wie die Vogel mit einem Strick gefangen werden, so werden auch die Menschen beruckt zur bosen Zeit, wenn sie plotzlich fiber sie fallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Ich habe auch diese Weisheit gesehen unter der Sonne, die mich groß deuchte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'daß eine, kleine Stadtwar und wenig Leute drinnen, und kam ein großer Konig und belegte sie und bauete große Bollwerke drum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'und ward drinnen funden ein armerweiser Mann, der dieselbe Stadt durch seine Weisheit konnte erretten; und kein Mensch gedachte desselben armen Mannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Da sprach ich: Weisheit ist ja besser denn Starke. Noch ward des Armen Weisheit verachtet und seinen Worten nicht gehorcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Das macht der Weisen Worte gelten mehr bei den Stillen denn der Herren Schreien bei den Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Denn Weisheit ist besser denn Hamisch; aber ein einiger Bube verderbet viel Gutes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Also verderben die schadlichen Fliegen gute Salben. Darum ist zuweilen besser Torheit denn Weisheit und Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Denn des Weisen Herz ist zu seiner Rechten; aber des Narren Herz ist zu seiner Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Auch ob der Narr selbst narrisch ist in seinem Tun, noch halt er jedermann fur Narren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Darum wenn eines Gewaltigen Trotz wider deinen Willen fortgehet, laß dich nicht entrusten; denn Nachlassen stillet groß Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Es ist ein Ungluck, das ich sah unter der Sonne, namlich Unverstand, der unter den Gewaltigen gemein ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'daß ein Narr sitzt in großer Würde, und die Reichen hienieden sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Ich sah Knechte auf Rossen und Fursten zu Fuße gehen wie Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Aber wer eine Grube macht, der wird selbst dreinfallen; und wer den Zaun zerreißet, den wird eine Schlange stechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Wer Steine wegwalzet, der wird Muhe damit haben; und wer Holz spaltet, der wird davon verletzt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Wenn ein Eisen stumpf wird und an der Schneide ungeschliffen bleibet, muli man\'s mit Macht wieder scharfen; also folgt auch Weisheit dem Fleüi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Ein Wascher ist nichts besser denn eine Schlange, die unbeschworen sticht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Die Worte aus dem Munde eines Weisen sind holdselig; aberdes Narren Lippen verschlingen denselben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Der Anfang seiner Worte ist Narrheit, und das Ende ist schadliche Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Ein Narr macht viel Worte; denn der Mensch weiß nicht, was gewesen ist; und wer will ihm sagen, was nach ihm werden wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Die Arbeit der Narren wird ihnen sauer, weil man nicht weiß, in die Stadt zu gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Wehe dir, Land, des Konig ein Kind ist und des Fursten fruhe essen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Wohl dir, Land, des Konig edel ist und des Fursten zu rechter Zeit essen, zur Starke und nicht zur Lust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, '(Denn durch Faulheit sinken die Balken, und durch hinlassige Hande wird das Flaus triefend.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Das macht, sie machen Brotzum Lachen, und der Wein mult, die Lebendigen erfreuen, und das Geld muß ihnen alles zuwege bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Fluche dem Konige nicht in deinem Herzen und fluche dem Reichen nicht in deiner Schlafkammer; denn die Vogel des Himmels fuhren die Stimme, und die Fittiche haben, sagen\'s nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Laßdein Brat uber das Wasserfahren, sowirst du es finden auf lange Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Teile aus unter sieben und unter acht; denn du weißest nicht, was fur Ungluck auf Erden kommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Wenn die Wolken voll sind, so geben sie Regen auf die Erde; und wenn der Baum fallt, er falle gegen Mittag Oder Mitternacht, auf welchen Ort er fallt, da wird er liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Wer auf den Wind achtet, der saet nicht, und wer auf die Wolken siehet, der erntet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Gleichwie du nicht weüit den Weg des Windes, und wie die Gebeine in Mutterleibe bereitet werden, also kannst du auch Gottes Werk nicht wissen, das er tut uberall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Fruhe sahe deinen Samen und laß deine Hand des Abends nicht ab; denn du weißt nicht, ob dies Oder das geraten wird; und ob es beides geriete, so ware es desto besser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Es ist das Licht suli und den Augen lieblich, die Sonne zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Wenn ein Mensch lange Zeit lebet und ist frohlich in alien Dingen, so gedenkt er doch nur der bosen Tage, daß ihrer so viel ist; denn alles, was ihm begegnet ist, ist eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Sofreue dich, Jüngling, in deiner Jugend und lali dein Herz guter Dinge sein in deiner Jugend. Tue, was dein Herz lustet und deinen Augen gefallt; und wisse, daß dich Gott urn des alles wird vor Gericht fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Lali die Traurigkeit aus deinem Herzen und tue das Ubel von deinem Leibe; denn Kindheit und Jugend ist eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Gedenk an deinen Schopfer in deiner Jugend, ehe denn die bosen Tage kommen und die Jahre herzutreten, da du wirst sagen: Sie gefallen mir nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'ehe denn die Sonne und das Licht, Mond und Sterne finster werden und Wolken wiederkommen nach dem Regen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'zur Zeit, wenn die Hitter im Hause zittern, und sich krummen die Starken, und mulüg stehen die Muller, daß ihrer so wenig worden ist, und finster werden die Gesichter durch die Fenster,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'und die Turen auf der Gasse geschlossen werden, daß die Stimme der Mullerin leise wird und erwacht, wenn der Vogel singet, und sich bucken alle Tochterdes Gesangs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'daß sich auch die Hohen furchten und scheuen auf dem Wege; wenn der Mandelbaum blühet, und die Heuschrecke beladen wird, und alle Lust vergehet (denn der Mensch fahrt hin, da er ewig bleibt, und die Klager gehen umher auf der Gasse,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ehe denn dersilberne Strick wegkomme, und die guldene Quelle verlaufe, und der Eimer zerbreche am Born und das Rad zerbreche am Born.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Denn der Staub muli wieder zu der Erde kommen, wie er gewesen ist, und der Geist wieder zu Gott, der ihn gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Es ist alles ganz eitel, sprach der Prediger, ganz eitel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Derselbe Prediger war nicht allein weise, sondern lehrete auch das Volk gute Lehre und merkte und forschete und stellete viel Spruche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Ersuchte, daßerfande angenehme Worte, und schrieb recht die Worte der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Diese Worte der Weisen sind Spielie und Nagel, geschrieben durch die Meister der Versammlungen und von einem Hirten gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Hute dich, mein Sohn, vorandern mehr; denn viel Buchermachens ist kein Ende und viel Predigen macht den Leib müde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Lalit uns die Hauptsumma aller Lehre horen: Furchte Gott und halte seine Gebote; denn das Das Hohelied Salomos gehoret alien Menschen zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Denn Gott wird alle Werke vor Gericht bringen, das verborgen ist, es sei gut Oder bose. Hoheslied 1');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Das Hohelied Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Er kusse mich mit dem Kuli seines Mundes; denn deine Liebe ist lieblicher denn Wein;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'daß man deine gute Salbe rieche. Dein Name ist eine ausgeschuttete Salbe, darum lieben dich die Magde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Zeuch mich dir nach, so laufen wir. Der Konig führet mich in seine Kammer. Wir freuen uns und sind frohlich uber dir; wir gedenken an deine Liebe mehr denn an den Wein. Die Frommen lieben dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Ich bin schwarz, aber gar lieblich, ihr Tochter Jerusalems, wie die Hütten Kedars, wie die Teppiche Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Sehet mich nicht an, daß ich so schwarz bin; denn die Sonne hat mich so verbrannt. Meiner Mutter Kinder zurnen mit mir. Man hat mich zur Huterin der Weinberge gesetzt; aber meinen Weinberg, den ich hatte, habe ich nicht behutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Sage mir an, du, den meine Seele liebet, wo du weidest, wo du ruhest im Mittage, daß ich nicht hin und her gehen musse bei den Herden deiner Gesellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Kennest du dich nicht, du Schonste unter den Weibern, so gehe hinaus auf die Fulitapfen der Schafe und weide deine Bocke bei den Hirtenhausern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Ich gleiche dich, meine Freundin, meinem reisigen Zeuge an den Wagen Pharaos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Deine Backen stehen lieblich in den Spangen und dein Hals in den Ketten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Wirwollen dir guldene Spangen machen mit silbernen Pocklein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Da der Konig sich herwandte, gab meine Narde seinen Geruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Mein Freund ist mir ein Buschel Myrrhen, das zwischen meinen Brusten hanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Mein Freund ist mir eine Traube Kopherinden Weingarten zu Engeddi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Siehe, meine Freundin, du bistschon, schon bist du; deine Augen sind wie Taubenaugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Siehe, mein Freund, du bistschon und lieblich. Unser Bett grünet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Unserer Hauser Balken sind Zedern, unsere Latten sind Zypressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Ich bin eine Blume zu Saron und eine Rose im Tal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Wie eine Rose unter den Dornen, so ist meine Freundin unter den Tochtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Wie ein Apfelbaum unter den wilden Baumen, so ist mein Freund unter den Sohnen. Ich sitze unter dem Schatten, des ich begehre, und seine Frucht ist meiner Kehle süli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Erfuhret mich in den Weinkeller, und die Liebe ist sein Panier uber mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Er erquicket mich mit Blumen und labet mich mit Apfeln; denn ich bin krank vor Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Seine Linke liegt unter meinem Haupte, und seine Rechte herzet mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Ich beschwore euch, ihr Tochter Jerusalems, bei den Rehen Oder bei den Hinden auf dem Felde, dad ihr meine Freundin nicht aufwecket noch reget, bis dad ihr selbst gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Da ist die Stimme meines Freundes. Siehe, er kommt und hupfet auf den Bergen und springet auf den Hügeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Mein Freund istgleich einem Rehe oderjungen Hirsch. Siehe, er stehet hinter unserer Wand und siehet durchs Fenster und gucket durchs Gitter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Mein Freund antwortet und spricht zu mir: Stehe auf, meine Freundin, meine Schone, und komm her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Denn siehe, der Winter ist vergangen, der Regen istweg und dahin;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'die Blumen sind hervorkommen im Lande, der Lenz ist herbeikommen, und die Turteltaube lalit sich horen in unserm Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'der Feigenbaum hat Knoten gewonnen, die Weinstocke haben Augen gewonnen und geben ihren Geruch. Stehe auf, meine Freundin, und komm, meine Schone, komm her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Meine Taube in den Felslbchern, in den Steinritzen, zeige mir deine Gestalt, laß mich horen deine Stimme! Denn deine Stimme ist suß und deine Gestalt lieblich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Fahet uns die Füchse, die kleinen Fuchse, die die Weinberge verderben; denn unsere Weinberge haben Augen gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Mein Freund ist mein, und ich bin sein, der unter den Rosen weidet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'bis der Tag kühle werde und der Schatten weiche. Kehre urn, werde wie ein Reh, mein Freund, Oder wie ein junger Hirsch auf den Scheidebergen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Ich suchte des Nachts in meinem Bette, den meine Seele liebet. Ich suchte, aber ich fand ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Ich will aufstehen und in der Stadt umgehen auf den Gassen und Stralien und suchen, den meine Seele liebet. Ich suchte, aber ich fand ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Es fanden mich die Wachter, die in der Stadt umgehen: Habt ihr nicht qesehen, den meine Seele liebet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Da ich ein wenig vor ihnen uber kam, da fand ich, den meine Seele liebet. Ich halte ihn und will ihn nicht lassen, bis ich ihn bringe in meiner Mutter Haus, in meiner Mutter Kammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Ich beschwore euch, ihr Tochter zu Jerusalem, bei den Rehen Oder Hinden auf dem Felde, daß ihr meine Freundin nicht aufwecket noch reget, bis daß ihr selbst gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Wer ist die, die heraufgehet aus der Wuste, wie ein gerader Rauch, wie ein Gerauch von Myrrhen, Weihrauch und allerlei Pulver eines Apothekers?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Siehe, urn das Bette Salomos her stehen sechzig Starke aus den Starken in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Sie halten alle Schwerter und sind geschickt zu streiten. Ein jeglicher hat sein Schwert an seiner Hüfte urn der Furcht willen in der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Der Konig Salomo liefi ihm eine Sanfte machen von Holz aus Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Derselben Saulen waren silbern, die Decke gulden, der Sitz purpurn, der Boden mitten inne war lieblich gepflastert urn der Tochter willen zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Gehet heraus und schauet an, ihr Tochter Zions, den Konig Salomo in der Krone, damit ihn seine Mutter gekronet hat am Tage seiner Hochzeit und am Tage der Freude seines Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Siehe, meine Freundin, du bist schon, siehe, schon bistdu! Deine Augen sind wie Taubenaugen zwischen deinen Zopfen. Dein Haar ist wie die Ziegenherden, die beschoren sind auf dem Berge Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Deine Zahne sind wie die Herde mit beschnittener Wolle, die aus der Schwemme kommen, die allzumal Zwillinge tragen, und ist keine unter ihnen unfruchtbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Deine Lippen sind wie eine rosinfarbene Schnur, und deine Rede lieblich. Deine Wangen sind wie der Ritz am Granatapfel zwischen deinen Zopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Dein Hals ist wie der Turm Davids, mit Brustwehr gebauet, daran tausend Schilde hangen und allerlei Waffen der Starken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Deine zwo Bruste sind wie zwei junge Rehzwillinge, die unter den Rosen weiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'bis der Tag kühle werde und der Schatten weiche. Ich will zum Myrrhenberge gehen und zum Weihrauchhugel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Du bist allerdinge schon, meine Freundin, und ist kein Flecken an dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Komm, meine Braut, vom Libanon, komm vom Libanon! Gehe herein, tritt her von der Hohe Amana, von der Hohe Senir und Hermon, von den Wohnungen der Lowen, von den Bergen der Leoparden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Du hast mir das Herz genommen, meine Schwester, liebe Braut, mit deiner Augen einem und mit deiner Halsketten einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Wie schon sind deine Bruste, meine Schwester, liebe Braut! Deine Bruste sind lieblicher denn Wein, und der Geruch deiner Salben ubertrifft alle Würze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Deine Lippen, meine Braut, sind wie triefender Honigseim, Honig und Milch ist unter deiner Zunge, und deiner Kleider Geruch ist wie der Geruch Libanons.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Meine Schwester, liebe Braut, du bist ein verschlossener Garten, eine verschlossene Quelle, ein versiegelter Born.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Dein Gewachs istwie ein Lustgarten von Granatapfeln, mitedlen Fruchten, Zypern mit Narden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Narden mit Safran, Kalmus und Zinnamen, mit allerlei Baumen des Weihrauchs, Myrrhen und Aloes, mit alien besten Wurzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Wie ein Gartenbrunn, wie ein Born lebendiger Wasser, die vom Libanon flieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Stehe auf, Nordwind, und komm, Südwind, und wehe durch meinen Garten, daß seine Wurzen triefen! Mein Freund komme in seinen Garten und esse seiner edlen Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Ich komme, meine Schwester, liebe Braut, in meinen Garten. Ich habe meine Myrrhen samt meinen Wurzen abgebrochen; ich habe meines Seims samt meinem Honig gegessen; ich habe meines Weins samt meiner Milch getrunken. Esset, meine Lieben, und trinket, meine Freunde, und werdet trunken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ich schlafe, aber mein Herz wacht. Da ist die Stimme meines Freundes, der anklopfet: Tu mirauf, liebe Freundin, meine Schwester, meine Taube, meine Fromme; denn mein Haupt istvoll Taues, und meine Locken voll Nachttropfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Ich habe meinen Rock ausgezogen, wie soil ich ihn wieder anziehen? Ich habe meine Ftifte gewaschen, wie soil ich sie wieder besudeln?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Aber mein Freund steckte seine Hand durchs Loch, und mein Leib erzitterte davor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Da stund ich auf, daß ich meinem Freunde auftate; meine Hande troffen mit Myrrhen, und Myrrhen liefen uber meine Finger an dem Rieqel am Schloft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Und da ich meinem Freunde aufgetan hatte, war erweg und hingegangen. Da ging meine Seele heraus nach seinem Wort: Ich suchte ihn, aber ich fand ihn nicht; ich rief, aber er antwortete mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Es fanden mich die Hitter, die in der Stadt umgehen, die schlugen mich wund; die Hitter auf der Mauer nahmen mir meinen Schleier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Ich beschwore euch, ihr Tochter Jerusalems, findet ihr meinen Freund, so saget ihm, dati ich vor Liebe krank liege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Was ist dein Freund vor andern Freunden, o du Schonste unter den Weibern? Was ist dein Freund vor andern Freunden, daß du uns so beschworen hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Mein Freund istweift und rot, auserkoren unter viel Tausenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sein Haupt ist das feinste Gold. Seine Locken sind kraus, schwarz wie ein Rabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Seine Augen sind wie Taubenaugen an den Wasserbachen, mit Milch gewaschen, und stehen in der Fülle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Seine Backen sind wie die wachsenden Wurzgartlein der Apotheker. Seine Lippen sind wie Rosen, die mit flieftenden Myrrhen triefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Seine Hande sind wie güldene Ringe, voll Turkise. Sein Leib ist wie rein Elfenbein mit Saphiren geschmückt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Seine Beine sind wie Marmelsaulen, gegrundet auf guldenen Füften. Seine Gestalt ist wie Libanon, auserwahlt wie Zedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Seine Kehle ist süft und ganz lieblich. Ein solcher ist mein Freund; mein Freund ist ein solcher, ihr Tochter Jerusalems!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Wo ist denn dein Freund hingegangen, o du Schonste unter den Weibern? Wo hat sich dein Freund hingewandt? So wollen wir mit dir ihn suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Mein Freund ist hinabgegangen in seinen Garten, zu den Wurzgartlein, daß er sich weide unter den Garten und Rosen breche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Mein Freund ist mein, und ich bin sein, der unter den Rosen sich weidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Du bist schon, meine Freundin, wie Thirza, lieblich wie Jerusalem, schrecklich wie Heerspitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Wende deine Augen von mir, denn sie machen mich brunstig. Deine Haare sind wie eine Herde Ziegen, die auf dem Berge Gilead geschoren sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Deine Zahne sind wie eine Herde Schafe, die aus der Schwemme kommen, die allzumal Zwillinge tragen, und ist keins unfruchtbar unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Deine Wangen sind wie ein Ritz am Granatapfel zwischen deinen Zopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Sechzig ist der Koniginnen und achtzig der Kebsweiber, und der Jungfrauen ist keine Zahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Aber eine ist meine Taube, meine Fromme, eine ist ihrer Mutter die Liebste, und die Auserwahlte ihrer Mutter. Da sie die Tochter sahen, preiseten sie dieselbige selig; die Koniginnen und die Kebsweiber lobten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Wer ist, die hervorbricht wie die Morgenrote, schon wie der Mond, auserwahlt wie die Sonne, schrecklich wie die Heerspitzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Ich bin hinab in den Nuftgarten gegangen, zu schauen die Strauchlein am Bach, zu schauen, ob der Weinstock bluhete, ob die Granatapfel gruneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Meine Seele wuftte es nicht, daß er mich zum Wagen Ammi-Nadibs gesetzt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Kehre wieder, kehre wieder, o Sulamith! Kehre wieder, kehre wieder, daß wir dich schauen! Was sehet ihr an Sulamith? Den Reigen zu Mahanaim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Wie schon ist dein Gang in den Schuhen, du Furstentochter! Deine Lenden stehen gleich aneinanderwie zwo Spangen, die des Meisters Hand gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Dein Nabel istwie ein runder Becher, dem nimmer Getrank mangelt. Dein Bauch istwie ein Weizenhaufen, umsteckt mit Rosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Deine zwo Brüste sind wie zwei junge Rehzwillinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Dein Hals istwie ein elfenbeinerner Turm. Deine Augen sind wie die Teiche zu Hesbon, am Tor Bathrabbim. Deine Nase istwie der Turm auf Libanon, der gegen Damaskus siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Dein Haupt stehet auf dir wie Karmel. Das Haar auf deinem Haupt ist wie der Purpur des Konigs in Falten gebunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Wie schon und wie lieblich bist du, du Liebe in Wollusten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Deine Lange ist gleich einem Palmbaum und deine Brüste den Weintrauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Ich sprach: Ich muß auf den Palmbaum steigen und seine Zweige ergreifen. Laß deine Brüste sein wie Trauben am Weinstock und deiner Nase Geruch wie Apfel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'und deine Kehle wie guter Wein, der meinem Freunde glatt eingehe und rede von fernigem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Mein Freund ist mein und er halt sich auch zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Komm, mein Freund, lali uns aufs Feld hinausgehen und auf den Dorfern bleiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'daß wirfrühe aufstehen zu den Weinbergen, daß wir sehen, ob der Weinstock blühe und Augen gewonnen habe, ob die Granatapfelbaume ausgeschlagen sind; da will ich dir meine Brüste geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 14, 'Die Lilien geben den Geruch, und vor unserer Tür sind allerlei edle Früchte. Mein Freund, ich habe dir beide, heurige und fernige, behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O daß ich dich, mein Bruder, der du meiner Mutter Brüste saugest, draußen fande und dich küssen müßte, daß mich niemand hohnete!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Ich wollte dich führen und in meiner Mutter Haus bringen, da du mich lehren solltest; da wollte ich dich tranken mit gemachtem Wein und mit dem Most meiner Granatapfel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Seine Linke liegt unter meinem Haupt, und seine Rechte herzet mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Ich beschwore euch, Tochter Jerusalems, daß ihr meine Liebe nicht aufwecket noch reget, bis daß ihr selbst gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Wer ist die, die herauffahret von der Wüste und lehnet sich auf ihren Freund? Unter dem Apfelbaum weckte ich dich, da deine Mutter dich geboren hatte, da mit dir gelegen ist, die dich gezeuget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Setze mich wie ein Siegel auf dein Herz und wie ein Siegel auf deinen Arm. Denn Liebe ist stark wie der Tod, und Eifer ist fest wie die Holle. Ihre Glut ist feurig und eine Flamme des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'daß auch viel Wasser nicht mogen die Liebe ausloschen, noch die Strome sie ersaufen. Wenn einer alles Gut in seinem Hause urn die Liebe geben wollte, so galte es alles nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Unsere Schwester ist klein und hat keine Brüste. Was sollen wir unserer Schwester tun, wenn man sie nun soil anreden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ist sie eine Mauer, so wollen wir silbern Bollwerk drauf bauen. Ist sie eine Tür, so wollen wir sie festigen mitzedernen Bohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ich bin eine Mauer, und meine Brüste sind wie Türme. Da bin ich worden vor seinen Augen, als die Frieden findet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomo hat einen Weinberg zu Baal-Hamon. Er gab den Weinberg den Hütern, daß ein jeglicherfur seine Früchte brachte tausend Silberlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Mein Weinberg ist vor mir. Dir, Salomo, gebuhren tausend; aber den Hütern zweihundert samt seinen Früchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Die du wohnest in den Garten, laß mich deine Stimme horen; die Gesellschaften merken drauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Fleuch, mein Freund, und sei gleich einem Reh Oder jungen Hirsche auf den Würzbergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Dies ist das Gesicht Jesajas, des Sohns Amoz, welches er sah von Juda und Jerusalem zur Zeit Usias, Jothams, Ahas und Jehiskias, der Konige Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Horet, ihr Himmel, und Erde, nimm zu Ohren! Denn der HERR redet: Ich habe Kinder auferzogen und erhohet, und sie sind von mir abgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Ein Ochse kennet seinen Herrn und ein Esel die Krippe seines Herrn; aber Israel kennet es nicht, und mein Volk vernimmt es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'O wehe des sundigen Volks, des Volks von grofter Missetat, des boshaftigen Samens, der schadlichen Kinder, die den HERRN verlassen, den Heiligen in Israel lastern, weichen zuruck!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Was soli man weiter an euch schlagen, so ihr des Abweichens nur desto mehr machet? Das ganze Haupt ist krank, das ganze Herz ist matt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Von der Fuftsohle bis aufs Haupt ist nichts Gesundes an ihm, sondern Wunden und Striemen und Eiterbeulen, die nicht geheftet noch verbunden noch mit 01 gelindert sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Euer Land ist wuste, eure Stadte sind mit Feuer verbrannt; Fremde verzehren eure Acker vor euren Augen, und ist wuste, als das, so durch Fremde verheeret ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Was aber noch übrig ist von der Tochter Zion, ist wie ein Hauslein im Weinberge, wie eine Nachthutte in den Kurbisgarten, wie eine verheerte Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Wenn uns der HERR Zebaoth nicht ein weniges liefte uberbleiben, so waren wirwie Sodom und gleichwie Gomorrha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Horet des HERRN Wort, ihr Fursten von Sodom; nimm zu Ohren unsers Gottes Gesetz, du Volk von Gomorrha!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Was soil mir die Menge eurer Opfer? sprichtder HERR. Ich bin satt der Brandopfer von Widdern und des Fetten von den Gemasteten und habe keine Lust zum Blut der Farren, der Lammer und Bocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Wenn ihr hereinkommet zu erscheinen vor mir, wer fordert solches von euren Handen, daü ihr auf meinen Vorhof tretet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Bringet nicht mehr Speisopfer so vergeblich! Das Rauchwerk ist mir ein Greuei; der Neumonden und Sabbate, da ihrzusammenkommet und Mühe und Angst habt, deren mag ich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Meine Seele istfeind euren Neumonden und Jahrzeiten; ich bin derselbigen uberdrussig; ich bin\'s mude zu leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Und wenn ihrschon eure Hande ausbreitet, verberge ich doch meine Augen von euch; und ob ihr schon viel betet, hore ich euch doch nicht; denn eure Hande sind voll Bluts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Waschet, reiniget euch, tut euer boses Wesen von meinen Augen, lasset ab vom Bosen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lernet Gutes tun, trachtet nach Recht, helfet dem Unterdruckten, schaffetdem Waisen Recht und helfet der Witwen Sache!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'So kommt dann und laftt uns miteinander rechten, sprichtder HERR. Wenn teure Sünde gleich blutrot ist, soli sie doch schneeweift werden, und wenn sie gleich ist wie Rosinfarbe, soil sie doch wie Wolle werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Wollt ihr mir gehorchen, so sollt ihr des Landes Gut genieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Weigert ihr euch aber und seid ungehorsam, so sollt ihr vom Schwert gefressen werden; denn der Mund des HERRN sagt es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Wie gehet das zu, daü die fromme Stadt zur Hure worden ist? Sie war voll Rechts, Gerechtigkeit wohnete drinnen, nun aber Morder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ist Schaum worden und dein Getrank mit Wasser vermischt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Deine Fursten sind Abtrunnige und Diebsgesellen; sie nehmen alle gerne Geschenke und trachten nach Gaben; dem Waisen schaffen sie nicht Recht, und der Witwen Sache kommt nicht vor sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Darum spricht der Herr HERR Zebaoth, der Machtige in Israel: 0 weh! Ich werde mich trosten durch meine Feinde und mich rachen durch meine Feinde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'und muft meine Hand wider dich kehren und deinen Schaum aufs lauterste fegen und all dein Zinn wegtun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'und dir wieder Richter geben, wie zuvor waren, und Ratsherren wie im Anfang. Alsdann wirst du eine Stadt der Gerechtigkeit und eine fromme Stadt heiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion muft durch Recht erloset werden und ihre Gefangenen durch Gerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'dafi die Ubertreter und Sunder miteinander zerbrochen werden, und die den HERRN verlassen, umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Denn sie mussen zuschanden werden uber den Eichen, da ihr Lust zu habt, und schamrot werden uber den Garten, die ihr erwahlet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'wenn ihr sein werdet wie eine Eiche mit durren Blattern und wie ein Garten ohne Wasser;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'wenn der Schutz wird sein wie Werg und sein Tun wie ein Funke, und beides miteinander angezündet werde, daß niemand losche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Dies ist\'s, das Jesaja, der Sohn Amoz, sah von Juda und Jerusalem:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Es wird zur letzten Zeit der Berg, da des HERRN Haus ist, gewift sein, hoher denn alle Berge, und uber alle Hügel erhaben werden; und werden alle Heiden dazu laufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'und viel Vdlker hingehen und sagen: Kommt, laftt uns auf den Berg des HERRN gehen, zum Hause des Gottes Jakobs, daß er uns lehre seine Wege und wir wandeln auf seinen Steigen! Denn von Zion wird das Gesetz ausgehen und des HERRN Wort von Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Und er wird richten unter den Heiden und strafen viel Volker. Da werden sie ihre Schwerter zu Pflugscharen und ihre Spieße zu Sicheln machen. Denn es wird kein Volk wider das andere ein Schwert aufheben und werden fort nicht mehr kriegen lernen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Kommet ihr nun vom Hause Jakobs, lafit uns wandeln im Licht des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Aber du hast dein Volk, das Haus Jakobs, lassen fahren; denn sie treiben\'s mehr denn die gegen dem Aufgang und sind Tagewahler, wie die Philister, und machen der fremden Kinder viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Ihr Land ist voll Silber und Gold, und ihrer Schatze ist kein Ende; ihr Land ist voll Rosse, und ihrer Wagen ist kein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Auch ist ihr Land voll Gotzen, und beten an ihrer Hande Werk, welches ihre Finger gemacht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Da bückt sich der Pobel, da demutigen sich die Junker. Das wirst du ihnen nicht vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Gehe hin in den Felsen und verbirg dich in der Erde, vor der Furcht des HERRN und vor seiner herrlichen Majestat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Denn alle hohen Augen werden geniedriget werden, und was hohe Leute sind, wird sich bücken müssen; der HERR aber wird allein hoch sein zu der Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Denn der Tag des HERRN Zebaoth wird gehen über alles Hoffartige und Hohe und uber alles Erhabene, daß es geniedriget werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'auch uber alle hohen und erhabenen Zedern auf dem Libanon und uber alle Eichen in Basan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'uber alle hohen Berge und uber alle erhabenen Hugel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'uber alle hohen Türme und uber alle festen Mauern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'uber alle Schiffe im Meer und uber alle kostliche Arbeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'daß sich bücken muli alle Hohe der Menschen und demutigen, was hohe Leute sind, und der HERR allein hoch sei zu der Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Und mit den Gotzen wird\'s ganz aus sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Da wird man in der Felsen Hohlen gehen und in der Erde Klüfte vor der Furcht des HERRN und vor seiner herrlichen Majestat, wenn er sich aufmachen wird, zu schrecken die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Zu der Zeit wird jedermann wegwerfen seine silbernen und guldenen Gotzen, die er ihm hatte machen lassen anzubeten, in die Locher der Maulwürfe und der Fledermause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'auf daß er moge in die Steinritzen und Felsklufte kriechen vor der Furcht des HERRN und vor seiner herrlichen Majestat, wenn er sich aufmachen wird, zu schrecken die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'So lasset nun ab von dem Menschen, der Odem in der Nase hat; denn ihrwisset nicht, wie hoch er geachtet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Denn siehe, der Herr HERR Zebaoth wird von Jerusalem und Juda nehmen allerlei Vorrat, alien Vorrat des Brots und alien Vorrat des Wassers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Starke und Kriegsleute, Richter, Propheten, Wahrsager und Alteste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Hauptleute uber funfzig und ehrliche Leute, Rate und weise Werkleute und kluge Redner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Und will ihnen Junglinge zu Fursten geben, und Kindische sollen uber sie herrschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Und das Volk wird Schinderei treiben, einer uber den andern und ein jeglicher uber seinen Nachsten; und der Jungere wird stolz sein wider den Alten und ein loser Mann wider den Ehrlichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Dann wird einer seinen Bruder aus seines Vaters Haus ergreifen: Du hast Kleider; sei unser Furst, hilf du diesem Unfall!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Er aber wird zu der Zeit schworen und sagen: Ich bin kein Arzt; es ist weder Brot noch Kleid in meinem Hause; setzet mich nicht zum Fursten im Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Denn Jerusalem fallt dahin, und Juda liegt da, weil ihre Zunge und ihr Tun wider den HERRN ist, daß sie den Augen seiner Majestat widerstreben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Ihr Wesen hat sie kein Hehl und rühmen ihre Sunde, wie die zu Sodom, und verbergen sie nicht. Wehe ihrer Seele! Denn damit bringen sie sich selbst in alles Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Prediget von den Gerechten, daß sie es gut haben; denn sie werden die Frucht ihrer Werke essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Wehe aber den Gottlosen, denn sie sind boshaftig, und es wird ihnen vergolten werden, wie sie es verdienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Kinder sind Treiber meines Volks und Weiber herrschen uber sie. Mein Volk, deine Troster verfuhren dich und zerstoren den Weg, den du gehen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Aber der HERR stehet da zu rechten, und ist aufgetreten, die Volker zu richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Und der HERR kommt zu Gericht mit den Altesten seines Volks und mit seinen Fursten. Denn ihr habt den Weinberg verderbt, und der Raub von den Armen ist in eurem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Warum zertretet ihr mein Volk und zerschlaget die Person der Elenden? spricht der Herr HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Und der HERR spricht: Darum dafi die Tochter Zions stolz sind und gehen mit aufgerichtetem Halse, mit geschminkten Angesichten, treten einher und schwanzen und haben kostliche Schuhe an ihren Fufien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'so wird der HERR den Scheitel der Tochter Zions kahl machen und der HERR wird ihre Geschmeide wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Zu der Zeit wird der HERR den Schmuck an den kostlichen Schuhen wegnehmen und die Hefte, die Spangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'die Kettlein, die Armspangen, die Hauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'die Flittern, die Gebrame, die Schnurlein, die Bisamapfel, die Ohrenspangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'die Ringe, die Haarbander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'die Feierkleider, die Mantel, die Schleier, die Beutel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'die Spiegel, die Koller, die Borten, die Kittel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'und wird Gestank fur guten Geruch sein und ein loses Band fur einen Gürtel und eine Glatze fur ein kraus Flaar und fur einen weiten Mantel ein enger Sack; solches alles anstatt deiner Schone.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Dein Pobel wird durchs Schwert fallen und deine Krieger im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Und ihre Tore werden trauern und klagen, und sie wird jammerlich sitzen auf der Erde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'daß sieben Weiber werden zu der Zeit einen Mann ergreifen und sprechen: Wir wollen uns selbst nahren und kleiden; lali uns nur nach deinem Namen heifien, dafi unsere Schmach von uns genommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'In der Zeit wird des HERRN Zweig lieb und wert sein und die Frucht der Erde herrlich und schon bei denen, die behalten werden in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Und wer da wird übrig sein zu Zion und uber bleiben zu Jerusalem, der wird heilig heilien, ein jeglicher, der geschrieben ist unter die Lebendigen zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Dann wird der HERR den Unflat der Tochter Zions waschen und die Blutschulden Jerusalems vertreiben von ihr durch den Geist, der richten und ein Feuer anzunden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Und der HERR wird schaffen uber alle Wohnung des Berges Zion, und wo sie versammelt ist, Wolken und Rauch des Tages und Feuerglanz, der da brenne des Nachts. Denn es wird ein Schirm sein uber alles, was herrlich ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'und wird eine Hutte sein zum Schatten des Tages vor der Hitze und eine Zuflucht und Verbergung vor dem Wetter und Regen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Wohlan, ich will meinem Lieben ein Lied meines Vetters singen von seinem Weinberge. Mein Lieber hat einen Weinberg an einem fetten Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Und er hat ihn verzaunet und mit Steinhaufen verwahret und edle Reben drein gesenkt. Er bauete auch einen Turm drinnen und grub eine Kelter drein und wartete, dafi er Trauben brachte. Aber er brachte Herlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Nun richtet, ihr Burger zu Jerusalem und ihr Manner Judas, zwischen mirund meinem Weinberge!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Was sollte man doch mehr tun an meinem Weinberge, das ich nichtgetan habe an ihm? Warum hat er denn Herlinge gebracht, da ich wartete, daß er Trauben brachte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Wohlan, ich will euch zeigen, was ich meinem Weinberge tun will. Seine Wand soil weggenommen werden, daß er verwustet werde, und sein Zaun soil zerrissen werden, daß er zertreten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Ich will ihn wuste liegen lassen, daß er nicht geschnitten noch gehackt werde, sondern Disteln und Dornen draufwachsen; und will den Wolken gebieten, daß sie nicht drauf regnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Des HERRN Zebaoth Weinberg aber ist das Haus Israel und die Manner Judas seine zarte Feser. Er wartet auf Recht, siehe, so ist\'s Schinderei; auf Gerechtigkeit, siehe, so ist\'s Klage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Wehe denen, die ein Haus an das andere ziehen und einen Acker zum andern bringen, bis daß kein Raum mehr da sei, daß sie alleine das Land besitzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Es ist vor den Ohren des HERRN Zebaoth; was gilt\'s, wo nicht die vielen Hauser sollen wuste werden und die grolien und feinen ode stehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Denn zehn Acker Weinberges sollen nur einen Eimer geben, und ein Malter Samens soil nur einen Scheffel geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Wehe denen, die des Morgens fruhe auf sind, des Saufens sich zu fleilügen, und sitzen bis in die Nacht, daß sie der Wein erhitzt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'und haben Harfen, Psalter, Pauken, Pfeifen und Wein in ihrem Wohlleben und sehen nicht auf das Werk des HERRN und schauen nicht auf das Geschaft seiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Darum wird mein Volk müssen weggeführt werden unversehens, und werden seine Herrlichen Hunger leiden und sein Pobel Durst leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Daher hat die Holle die Seele weit aufgesperret und den Rachen aufgetan ohne alle Malie, daß hinunterfahren beide, ihre Herrlichen und Pobel, beide, ihre Reichen und Frbhlichen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'daß jedermann sich bucken müsse und jedermann gedemutiget werde, und die Augen der Hoffartigen gedemutiget werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'aber der HERR Zebaoth erhohet werde im Recht, und Gott, der Heilige, geheiliget werde in Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Da werden dann die Lammer sich weiden an jener Statt, und Fremdlinge werden sich nahren in der Wuste der Fetten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Wehe denen, die sich zusammenkoppeln mit losen Stricken, unrecht zu tun, und mit Wagenseilen, zu sundigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'und sprechen: Lali eilend und bald kommen sein Werk, daß wir\'s sehen; lali herfahren und kommen den Anschlag des Heiligen in Israel, daß wir\'s inne werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Wehe denen, die Boses gut und Gutes bose heilien, die aus Finsternis Licht und aus Licht Finsternis machen, die aus sauer sufi und aus suli sauer machen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Wehe denen, die bei sich selbst weise sind und halten sich selbst fur klug!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Wehe denen, so Helden sind, Wein zu saufen, und Krieger in Vollerei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'die den Gottlosen rechtsprechen um Geschenk willen und das Recht der Gerechten von ihnen wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Darum, wie des Feuers Flamme Stroh verzehret und die Lohe Stoppeln hinnimmt, also wird ihre Wurzel verfaulen und ihre Sprossen auffahren wie Staub. Denn sie verachten das Gesetz des HERRN Zebaoth und lastern die Rede des Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Darum ist der Zorn des HERRN ergrimmet uber sein Voik und reckt seine Hand uber sie und schlagt sie, daß die Berge beben; und ihr Leichnam ist wie Kot auf den Gassen. Und in dem allem lalit sein Zorn nicht ab, sondern seine Hand ist noch ausgereckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Denn erwird ein Panieraufwerfen feme unter den Heiden und dieselbigen locken vom Ende der Erde. Und siehe, eilend und schnell kommen sie daher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Und ist keiner unter ihnen müde Oder schwach, keiner schlummert noch schlaft; keinem gehet der Gurtel auf von seinen Lenden, und keinem zerreitßet ein Schuhriemen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Ihre Pfeile sind scharf und alle ihre Bogen gespannet. Seiner Rosse Hufe sind wie Felsen geachtet und ihre Wagenrader wie ein Sturmwind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Sie brullen wie Lowen und brullen wie junge Lowen; sie werden brausen und den Raub erhaschen und davonbringen, daß niemand erretten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Und wird uber sie brausen zu der Zeit wie das Meer. Wenn man dann das Land ansehen wird, siehe, so ist\'s finster vor Angst, und das Licht scheinet nicht mehr oben uber ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Des Jahrs, da der Konig Usia starb, sah ich den HERRN sitzen auf einem hohen und erhabenen Stuhl; und sein Saum fullete den Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphim stunden uber ihm, ein jeglicher hatte sechs Flugel; mitzween deckten sie ihr Antlitz, mit zween deckten sie ihre Fülie und mit zween flogen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Und einer riefzum andern und sprach: Heilig, heilig, heilig ist der HERR Zebaoth; alle Lande sind seiner Ehre voll!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'dal$ die Uberschwellen bebeten von der Stimme ihres Rufens, und das Haus ward voll Rauchs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Da sprach ich: Wehe mir, ich vergehe! Denn ich bin unreiner Lippen und wohne unter einem Volk von unreinen Lippen; denn ich habe den Konig, den HERRN Zebaoth, gesehen mit meinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Da flog der Seraphim einer zu mir und hatte eine glühende Kohle in der Hand, die er mit der Zange vom Altar nahm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'und ruhrete meinen Mund und sprach: Siehe, hiermit sind deine Lippen geruhret, dati deine Missetat von dir genommen werde und deine Sunde versohnet sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Und ich horete die Stimme des HERRN, daß er sprach: Wen soil ich senden? Werwill unser Bote sein? Ich aber sprach: Hie bin ich, sende mich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Und er sprach: Gehe hin und sprich zu diesem Volk: Horet es und verstehet es nicht; sehet es und merket es nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Verstocke das Herz dieses Volks und lali ihre Ohren dicke sein und blende ihre Augen, dati sie nicht sehen mit ihren Augen, noch horen mit ihren Ohren, noch verstehen mit ihrem Herzen und sich bekehren und genesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Ich aber sprach: HERR, wie lange? Er sprach: Bis daß die Stadte wüste werden ohne Einwohner und Hauser ohne Leute und das Feld ganz wüst liege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Denn der HERR wird die Leute feme wegtun, daß das Land sehr verlassen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Doch soil noch das zehnte Teil drinnen bleiben; denn es wird weggeführet und verheeret werden wie eine Eiche und Linde, welche den Stamm haben, obwohl ihre Blatter abgestoßen werden. Ein heiliger Same wird solcher Stamm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Es begab sich zur Zeit Ahas, des Sohns Jothams, des Sohns Usias, des Konigs Judas, zog herauf: Rezin, der Konig zu Syrien, und Pekah, der Sohn Remaljas, der Konig Israels, gen Jerusalem, wider sie zu streiten, konnten sie aber nicht gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Da ward dem Hause David angesagt: Die Syrer verlassen sich auf Ephraim. Da bebete ihm das Herz und das Herz seines Volks, wie die Baume im Walde beben vom Winde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Aber der HERR sprach zu Jesaja: Gehe hinaus, Ahas entgegen; du und dein Sohn Sear-Jasub, an das Ende der Wasserrohren am obern Teiche, am Wege beim Acker des Farbers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'und sprich zu ihm: Hüte dich und sei stille! Furchte dich nicht, und dein Herz sei unverzagt vor diesen zween rauchenden Loschbranden, namlich vor dem Zorn Rezins samt den Syrern und des Sohns Remaljas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'daß die Syrer wider dich einen bosen Ratschlag gemacht haben samt Ephraim und dem Sohn Remaljas und sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Wirwollen hinauf zu Juda und sie aufwecken und unter uns teilen und zum Konige drinnen machen den Sohn Tabeals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Denn also spricht der Herr HERR: Es soli nicht bestehen noch also gehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'sondern wie Damaskus das Haupt ist in Syrien, so soli Rezin das Haupt zu Damaskus sein. Und uber funfundsechzig Jahre soli es mit Ephraim aus sein, daß sie nicht mehr ein Volk seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Und wie Samaria das Haupt ist in Ephraim, so soli der Sohn Remaljas das Haupt zu Samaria sein. Glaubt ihr nicht, so bleibt ihr nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Und der HERR redete abermal zu Ahas und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Fordere dir ein Zeichen vom HERRN, deinem Gott, es sei unten in der Holle Oder droben in der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Aber Ahas sprach: Ich will\'s nichtfordern, daß ich den HERRN nicht versuche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Da sprach er: Wohlan, so horet, ihrvom Hause David: Ist\'s euch zu wenig, daß ihrdie Leute beleidiget; ihr musset auch meinen Gott beleidigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Darum so wird euch der HERR selbst ein Zeichen geben: Siehe, eine Jungfrau istschwanger und wird einen Sohn gebaren, den wird sie heißen Immanuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Butter und Honig wird eressen, daßerwisse Boses zu verwerfen und Gutes zu erwahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Denn ehe der Knabe lernet Boses verwerfen und Gutes erwahlen, wird das Land, davordirgrauet, verlassen sein von seinen zween Konigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Aber der HERR wird uber dich, fiber dein Volk und fiber deines Vaters Haus Tage kommen lassen, die nicht kommen sind, seit der Zeit, da Ephraim von Juda geschieden ist, durch den Konig zu Assyrien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'denn zu der Zeit wird der HERR zischen der Fliege am Ende der Wasser in Agypten und der Biene im Lande Assur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'daß sie kommen und alle sich legen an die trockenen Bache und in die Steinklufte und in alle Hecken und in alle Busche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Zur selbigen Zeit wird der HERR das Haupt und die Haare an Fußen abscheren und den Bart abnehmen durch ein gemietet Schermesser, namlich durch die, so jenseit des Wassers sind, als durch den Konig von Assyrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Zur selbigen Zeit wird ein Mann einen Haufen Kfihe und zwo Herden ziehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'und wird so viel zu melken haben, daß er Butter essen wird; denn Butter und Honig wird essen, wer übrig im Lande bleiben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Denn es wird zu der Zeit geschehen, daß, wo jetzt tausend Weinstocke stehen, tausend Silberlinge wert, da werden Dornen und Hecken sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'daß man mit Pfeilen und Bogen dahin gehen muß. Denn im ganzen Lande werden Dornen und Hecken sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'daß man auch zu all den Bergen, so man mit Hauen pflegt umzuhacken, nicht kann kommen vor Scheu der Dornen und Hecken, sondern man wird Ochsen daselbst gehen und Schafe drauf treten lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Und der HERR sprach zu mir: Nimm vor dich einen großen Brief und schreib darauf mit Menschengriffel: Raubebald, Eilebeute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Und ich nahm zu mir zween treue Zeugen, den Priester Uria und Sacharja, den Sohn Jeberechjas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'und ging zu einer Prophetin, die ward schwanger und gebar einen Sohn. Und der HERR sprach zu mir: Nenne ihn Raubebald, Eilebeute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Denn ehe der Knabe rufen kann: Lieber Vater, liebe Mutter! soil die Macht Damaskus und die Ausbeute Samarias weggenommen werden durch den Konig zu Assyrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Und der HERR redete weiter mit mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Weil dies Volk verachtet das Wasser zu Siloah, das stille gehet, und trostet sich des Rezin und des Sohns Remaljas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'siehe, so wird der HERR fiber sie kommen lassen starke und viel Wasser des Stroms, namlich den Konig zu Assyrien und alle seine Herrlichkeit, daß sie fiber alle ihre Bache fahren und fiber alle ihre Ufer gehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'und werden einreißen in Juda und schwemmen und überher gehen, bis daß sie an den Hals reichen, und werden ihre Flfigel ausbreiten, daß sie dein Land, o Immanuel, füllen, soweit es ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Seid bose, ihr Volker, und gebet doch die Flucht! Horet ihr\'s, alle, die ihr in fernen Landen seid: Rustet euch und gebet doch die Flucht; lieber, rustet euch und gebet doch die Flucht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Beschließet einen Rat, und werde nichts draus! Beredet euch, und es bestehe nichts; denn hie ist Immanuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Denn so spricht der HERR zu mir, als fassete er mich bei der Hand und unterweisete mich, daß ich nicht soil wandeln auf dem Wege dieses Volks, und spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ihr sollt nicht sagen: Bund. Dies Volk redet von nichts, denn von Bund. Ftirchtet ihr euch nicht also, wie sie tun, und laßt euch nicht grauen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'sondern heiligetden HERRN Zebaoth. Den laßt eure Furcht und Schrecken sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'so wird ereine Heiligung sein, aber ein Stein des Anstoßes und ein Fels des Argernisses den zweien Hausern Israels, zum Strick und Fall den Burgern zu Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'daß ihrerviel sich dran stoßen, fallen, zerbrechen, verstrickt und gefangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Binde zu das Zeugnis, versiegele das Gesetz meinen Jungern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Denn ich hoffe auf den HERRN, der sein Antlitz verborgen hat vor dem Hause Jakob; ich aber harre sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Siehe, hie bin ich und die Kinder, die mir der HERR gegeben hat, zum Zeichen und Wunder in Israel, vom HERRN Zebaoth, der auf dem Berge Zion wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Wenn sie aber zu euch sagen: Ihr musset die Wahrsager und Zeichendeuter fragen, die da schwatzen und disputieren, (so sprecht): Soil nicht ein Volk seinen Gott fragen? Oder soil man die Toten fur die Lebendigen fragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Ja, nach dem Gesetz und Zeugnis. Werden sie das nicht sagen, so werden sie die Morgenrote nicht haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'sondern werden im Lande umhergehen, hart geschlagen und hungrig. Wenn sie aber Hunger leiden, werden sie zurnen und fluchen ihrem Konige und ihrem Gott');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'und werden über sich gaffen und unter sich die Erde ansehen und nichts finden denn Trubsal und Finsternis; denn sie sind müde in Angst und gehen irre im Finstern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, 'Denn eswird wohl eine andere Mühe sein, die ihnen Angst tut, denn zur vorigen Zeit war, da es leicht zuging im Lande Sebulon und im Lande Naphthali, und hernach schwerer ward am Wege des Meers, diesseit des Jordans, in der Heiden Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Das Volk, so im Finstern wandelt, siehet ein groftes Licht, und uber die da wohnen im finstern Lande, scheinet es helle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Du machest der Heiden viel, damit machest du der Freuden nicht viel. Vor dir aber wird man sich freuen, wie man sich freuet in der Ernte, wie man frohlich ist, wenn man Beute austeilet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Denn du hast das Joch ihrer Last und die Rute ihrer Schulter und den Stecken ihres Treibers zerbrochen wie zur Zeit Midians.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Denn aller Krieg mit Ungestüm und blutig Kleid wird verbrannt und mit Feuer verzehret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Denn uns ist ein Kind geboren, ein Sohn ist uns gegeben, welches Herrschaft ist auf seiner Schulter; und er heitit Wunderbar, Rat, Kraft, Held, Ewig-Vater, Friedefurst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'auf daß seine Herrschaft graft werde und des Friedens kein Ende auf dem Stuhl Davids und seinem Konigreiche, dati er\'s zurichte und starke mit Gericht und Gerechtigkeit von nun an bis in Ewigkeit. Solches wird tun der Eifer des HERRN Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Der HERR hat ein Wort gesandt in Jakob und ist in Israel gefallen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'daß es sollen inne werden alles Volk Ephraim und die Burger zu Samaria, die da sagen in Hochmut und stolzem Sinn:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Ziegelsteine sind gefallen, aber wirwollen\'s mit Werkstücken wieder bauen; man hat Maulbeerbaume abgehauen, sowollen wir Zedern an die Statte setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Denn der HERR wird des Rezins Kriegsvolk wider sie erhohen und ihre Feinde zuhauf rotten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'die Syrervorne her und die Philister von hinten zu, daß sie Israel fressen mit vollem Maul. In dem allem laftt sein Zorn noch nicht ab, seine Hand ist noch ausgereckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'So kehret sich das Volk auch nicht zu dem, der es schlagt, und fragen nichts nach dem HERRN Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Darum wird der HERR abhauen von Israel beide, Kopf und Schwanz, beide, Ast und Stumpf, auf einen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Die alten ehrlichen Leute sind der Kopf; die Propheten aber, so falsch lehren, sind der Schwanz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Denn die Leiter dieses Volks sind Verführer, und die sich leiten lassen, sind verloren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Darum kann sich der HERR uber ihre junge Mannschaft nicht freuen, noch ihrer Waisen und Witwen erbarmen; denn sie sind allzumal Heuchler und Bose, und aller Mund redet Torheit. In dem allem laftt sein Zorn noch nicht ab, seine Hand ist noch ausgereckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Denn das gottlose Wesen istangezundet wie Feuer und verzehret Dornen und Hecken und brennet wie im dicken Walde und gibt hohen Rauch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Denn im Zorn des HERRN Zebaoth ist das Land verfinstert, daß das Volk ist wie Speise des Feuers; keiner schonet des andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Rauben sie zur Rechten, so leiden sie Hunger; essen sie zur Linken, so werden sie nicht satt. Ein jeglicher friftt das Fleisch seines Arms:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Manasse den Ephraim, Ephraim den Manasse und sie beide miteinander wider Juda. In dem allem laftt sein Zorn nicht ab, seine Hand ist noch ausgereckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Wehe den Schriftgelehrten, die unrechte Gesetze machen und die unrecht Urteil schreiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'auf daß sie die Sache der Armen beugen und Gewalt uben im Recht der Elenden unter meinem Volk, daß die Witwen ihr Raub und die Waisen ihre Beute sein müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Was wollt ihr tun am Tage der Heimsuchung und des Unglücks, das von feme kommt? Zu wem wollt ihr fliehen urn Hilfe, und wo wollt ihr eure Ehre lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'daß sie nicht unter die Gefangenen gebeuget werde und unter die Erschlagenen falle? In dem allem laftt sein Zorn nicht ab, seine Hand ist noch ausgereckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'O wehe Assur, der meines Zorns Rute und ihre Hand meines Grimms Stecken ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Ich will ihn senden wider ein Heuchelvolk und ihm Befehl tun wider das Volk meines Zorns, daß er\'s beraube und austeile und zertrete es wie Kot auf der Gasse,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'wiewohl er\'s nicht so meinet und sein Herz nicht so denket, sondern sein Herz stehet zu vertilgen und auszurotten nicht wenig Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Denn er spricht: Sind meine Fursten nicht allzumal Konige?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ist Kalno nicht wie Karchemis? Ist Hamath nicht wie Arpad? Ist nicht Samaria wie Damaskus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Wie meine Hand funden hat die Konigreiche der Gotzen, so doch ihre Gotzen starker waren, denn die zu Jerusalem und Samaria sind:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'sollte ich nicht Jerusalem tun und ihren Gotzen, wie ich Samaria und ihren Gotzen getan habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Wenn aber der HERR alle seine Werke ausgerichtet hat auf dem Berge Zion und zu Jerusalem, will ich heimsuchen die Frucht des hochmutigen Konigs zu Assyrien und die Pracht seiner hoffartigen Augen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'darum dafi erspricht: Ich habe es durch meiner Hande Kraft ausgerichtet und durch meine Weisheit, denn ich bin klug; ich habe die Lander anders geteilet und ihr Einkommen geraubt und wie ein Machtiger die Einwohner zu Boden geworfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'und meine Hand hatfunden die Volkerwie ein Vogelnest, daß ich habe alle Lande zusammengerafft, wie man Eier aufrafft, die verlassen sind, da niemand eine Feder regt Oder den Schnabel aufsperret Oder zischet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Mag sich auch eine Axt ruhmen wider den, so damit hauet, Oder eine Sage trotzen wider den, so sie zeucht, wie der ruhmen kann, der den Stecken führet und hebt und fuhret ihn so leicht, als ware er kein Holz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Darum wird der Herr HERR Zebaoth unter seine Fetten die Durre senden, und seine Herrlichkeit wird er anzünden, dafi sie brennen wird wie ein Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Und das Licht Israels wird ein Feuer sein, und sein Heiligerwird eine Flamme sein und wird seine Dornen und Hecken anzünden und verzehren auf einen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Und die Herrlichkeit seines Waldes und seines Feldes soil zunichte werden von den Seelen bis aufs Fleisch und wird zergehen und verschwinden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'daß die übrigen Baume seines Waldes mogen gezahlet werden und ein Knabe sie mag anschreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Zu der Zeit werden die Ubrigen in Israel, und die errettet werden im Hause Jakob, sich nicht mehr verlassen auf den, der sie schlagt, sondern sie werden sich verlassen auf den HERRN, den Heiligen in Israel, in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Die Ubrigen werden sich bekehren, ja die übrigen in Jakob, zu Gott, dem Starken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Denn ob dein Volk, o Israel, istwie Sand am Meer, sollen doch die Ubrigen desselben bekehret werden. Denn wenn dem Verderben gesteuert wird, so kommt die Gerechtigkeit überschwenglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Denn der Herr HERR Zebaoth wird ein Verderben gehen lassen und demselbigen doch steuern im ganzen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Darum sprichtder Herr HERR Zebaoth: Fürchte dich nicht, mein Volk, das zu Zion wohnet, vor Assur! Er wird dich mit dem Stecken schlagen und seinen Stab wider dich aufheben, wie in Agypten geschah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Denn es ist noch gar urn ein kleines zu tun, so wird die Ungnade und mein Zorn über ihre Untugend ein Ende haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Alsdann wird der HERR Zebaoth eine Geifiel über ihn erwecken wie in der Schlacht Midians auf dem Fels Oreb und wird seinen Stab, den er am Meer brauchte, aufheben wie in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Zu der Zeit wird seine Last von deiner Schulter weichen müssen und sein Joch von deinem Halse; denn das Joch wird verfaulen vor der Fette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Er kommt (lali gleich sein) gen Ajath; er zeucht durch Migran; er mustert seinen Zeug zu Michmas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Sie ziehen vor unserm Lager Geba über; Rama erschrickt, Gibeath Sauls fleucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Du Tochter Gallim, schreie laut; merke auf, Laisa, du elendes Anathoth!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena weicht; die Burger zu Gebim starken sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Man bleibt vielleicht einen Tag zu Nob; so wird er seine Hand regen wider den Berg der Tochter Zion und wider den Hügel Jerusalems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Aber siehe, der Herr HERR Zebaoth wird die Aste mit Macht verhauen, und was hoch aufgerichtet stehet, verkürzen, dafi die Hohen geniedriget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Und der dicke Wald wird mit Eisen umgehauen werden, und Libanon wird fallen durch den Machtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Und es wird eine Rute aufgehen von dem Stamm Isais, und ein Zweig aus seiner Wurzel Frucht bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Aufwelchem wird ruhen der Geistdes HERRN, der Geist der Weisheit und des Verstandes, der Geist des Rats und der Starke, der Geist der Erkenntnis und der Furcht des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Und sein Riechen wird sein in der Furcht des HERRN. Er wird nicht richten, nach dem seine Augen sehen, noch strafen, nach dem seine Ohren horen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'sondern wird mit Gerechtigkeit richten die Armen und mit Gericht strafen die Elenden im Lande und wird mit dem Stabe seines Mundes die Erde schlagen und mit dem Odem seiner Lippen den Gottlosen toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Gerechtigkeit wird der Gurt seiner Lenden sein und der Glaube der Gurt seiner Nieren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Die Wolfe werden bei den Lammern wohnen und der Pardel bei den Bdcken liegen. Ein kleiner Knabe wird Kalber und junge Lowen und Mastvieh miteinander treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Kühe und Baren werden an der Weide gehen, daß ihre Jungen beieinander liegen; und Lowen werden Stroh essen wie die Ochsen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Und ein Saugling wird seine Lust haben am Loch der Otter, und ein Entwohnter wird seine Hand stecken in die Hohle des Basilisken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Man wird nirgend verletzen noch verderben auf meinem heiligen Berge; denn das Land istvoll Erkenntnis des HERRN, wie mit Wasserdes Meers bedeckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Und wird geschehen zu der Zeit, dad die Wurzel Isais, die da stehet zum Panier den Volkern, nach der werden die Heiden fragen; und seine Ruhe wird Ehre sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Und der HERR wird zu der Zeit zum andernmal seine Hand ausstrecken, daß er das Ubrige seines Volks erkriege, so überblieben ist von den Assyrern, Agyptern, Pathros, Mohrenland, Elamiten, Sinear, Hamath und von den Inseln des Meers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'und wird ein Panier unter die Heiden aufwerfen und zusammenbringen die Verjagten Israels und die Zerstreueten aus Juda zuhauf fuhren von den vier Ortern des Erdreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Und der Neid wider Ephraim wird aufhoren, und die Feinde Judas werden ausgerottetwerden, daß Ephraim nicht neide den Juda und Juda nicht sei wider Ephraim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Sie werden aber den Philistern auf dem Halse sein gegen Abend und berauben alle die, so gegen Morgen wohnen. Edom und Moab werden ihre Hande gegen sie falten. Die Kinder Ammon werden gehorsam sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Und der HERR wird verbannen den Strom des Meers in Agypten und wird seine Hand lassen gehen uber das Wasser mit seinem starken Winde und die sieben Strome schlagen, daü man mit Schuhen da durchgehen mag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Und wird eine Bahn sein dem ubrigen seines Volks, das überblieben ist von den Assyrern, wie Israel geschah zur Zeit, da sie aus Agyptenland zogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Zu derselbigen Zeitwirstdu sagen: Ich danke dir, HERR, daß du zornig bist gewesen uber mich und dein Zorn sich gewendet hat und trostest mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Siehe Gott ist mein Heil; ich bin sicher und furchte mich nicht; denn Gott der HERR ist meine Starke und mein Psalm und ist mein Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Ihr werdet mit Freuden Wasser schopfen aus den Heilsbrunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Und werdet sagen zur selbigen Zeit: Danket dem HERRN, prediget seinen Namen, macht kund unter den Volkern sein Tun, verkundiget, wie sein Name so hoch ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Lobsinget dem HERRN, denn er hat sich herrlich beweiset; solches sei kund in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Jauchze und ruhme, du Einwohnerin zu Zion; denn der Heilige Israels ist groß bei dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Dies ist die Last uber Babel, die Jesaja, der Sohn Amoz, sah:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Werfet Panier auf auf hohen Bergen, rufet getrost wider sie, werfet die Hand auf, lafit einziehen durch die Tore der Fursten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Ich habe meinen Geheiligten geboten und meinen Starken gerufen zu meinem Zorn, die da frohlich sind in meiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Es ist ein Geschrei einer Menge auf den Bergen wie eines grofien Volks, ein Geschrei als eines Getummels der versammelten Konigreiche der Heiden. Der HERR Zebaoth rustet ein Heer zum Streit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'die aus fernen Landen kommen, vom Ende des Himmels, ja, der HERR selbst samt dem Zeuge seines Zorns, zu verderben das ganze Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Heulet, denn des HERRN Tag ist nahe; er kommt wie eine Verwustung vom Allmachtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Darum werden alle Hande lali, und aller Menschen Herz wird feige sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Schrecken, Angst und Schmerzen wird sie ankommen; es wird ihnen bange sein wie einer Gebarerin; einer wird sich vor dem andern entsetzen; feuerrot werden ihre Angesichte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Denn siehe, des HERRN Tag kommt grausam, zornig, grimmig, das Land zu verstoren und die Sunder daraus zu vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Denn die Sterne am Himmel und sein Orion scheinen nicht helle; die Sonne gehet finster auf, und der Mond scheinet dunkel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Ich will den Erdboden heimsuchen urn seiner Bosheit willen und die Gottlosen urn ihrer Untugend willen; und will des Hochmuts der Stolzen ein Ende machen und die Hoffart der Gewaltigen demutigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'daß ein Mann teurer sein soli denn fein Gold und ein Mensch werter denn Goldstucke aus Ophir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Darum will ich den Himmel bewegen, daß die Erde beben soil von ihrer Statte durch den Grimm des HERRN Zebaoth und durch den Tag seines Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Und sie soil sein wie ein verscheucht Reh und wie eine Herde ohne Hirten, daß sich ein jeglicherzu seinem Volk heimkehren und ein jeglicher in sein Land fliehen wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'darum daß, welchersich da finden lalit, erstochen wird, und welcher dabei ist, durchs Schwert fallen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Es sollen auch ihre Kinder vor ihren Augen zerschmettert, ihre Hauser geplündert und ihre Weiber geschandet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Denn siehe, ich will die Meder uber sie erwecken, die nicht Silber suchen Oder nach Gold fragen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'sondern die Junglinge mit Bogen erschieüen und sich der Frucht des Leibes nicht erbarmen noch der Kinder schonen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Also soil Babel, das schonste unter den Konigreichen, die herrliche Pracht der Chaldaer, umgekehret werden von Gott, wie Sodom und Gomorrha,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'daß man hinfort nicht mehr da wohne, noch jemand da bleibe fur und fur, daß auch die Araber keine Hütten daselbst machen, und die Hirten keine Hürden da aufschlagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'sondern Zihim werden sich da lagern und ihre Hauser voll Ohim sein, und Straulien werden da wohnen, und Feldgeister werden da hüpfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'und Eulen in ihren Palasten singen und Drachen in den lustigen Schlossern. Und ihre Zeit wird schier kommen, und ihre Tage werden sich nicht saumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Denn der HERR wird sich über Jakob erbarmen und Israel noch weiter erwahlen und sie in ihr Land setzen. Und Fremdlinge werden sich zu ihnen tun und dem Hause Jakob anhangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Und die Volker werden sie annehmen und bringen an ihren Ort, daß sie das Haus Israel besitzen wird im Lande des HERRN zu Knechten und Magden; und werden gefangen halten die, von welchen sie gefangen waren, und werden herrschen uber ihre Treiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Und zu der Zeit, wenn dir der HERR Ruhe geben wird von deinem Jammer und Leid und von dem harten Dienst darin du gewesen bist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'so wirst du ein solch Sprichwort führen wider den Konig zu Babel und sagen: Wie ist\'s mit dem Treiber so gar aus, und der Zins hat ein Ende!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Der HERR hat die Rute der Gottlosen zerbrochen, die Rute der Herrscher,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'welche die Volker schlug im Grimm ohne Aufhoren und mit Wüten herrschete uber die Heiden und verfolgete ohne Barmherzigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nun ruhet doch alle Welt und ist stille und jauchzet frohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Auch freuen sich die Tannen uber dir und die Zedern auf dem Libanon (und sagen): Weil du liegst, kommt niemand herauf, der uns abhaue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Die Holle drunten erzitterte vor dir, da du ihr entgegenkamest. Sie erwecket dir die Toten, alle Bocke der Welt, und heifit alle Konige der Heiden von ihren Stühlen aufstehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'da(S dieselbigen alle umeinander reden und sagen zu dir: Du bist auch geschlagen, gleichwie wir, und gehetdirwie uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Deine Pracht ist herunter in die Holle gefahren samt dem Klange deiner Harfen. Motten werden dein Bett sein und Würmer deine Decke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Wie bistdu vom Himmel gefallen, du schoner Morgenstern! Wie bist du zur Erde gefallet, der du die Heiden schwachtest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Gedachtestdu doch in deinem Herzen: Ich will in den Himmel steigen und meinen Stuhl uber die Sterne Gottes erhohen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'ich will mich setzen auf den Berg des Stifts, an der Seite gegen Mitternacht; ich will uber die hohen Wolken fahren und gleich sein dem Allerhochsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Ja, zur Holle fahrest du, zur Seite der Grube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Werdich siehet, wird dich schauen und ansehen (und sagen): Ist das der Mann, der die Welt zittern und die Konigreiche beben machte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'der den Erdboden zur Wuste machte und die Stadte drinnen zerbrach und gab seine Gefangenen nicht los?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Zwar alle Konige der Heiden miteinander liegen doch mit Ehren, ein jeglicher in seinem Hause;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'du aber bist verworfen von deinem Grabewie ein verachteter Zweig, wie ein Kleid der Erschlagenen, so mit dem Schwert erstochen sind, die hinunterfahren zu den Steinhaufen der Holle, wie eine zertretene Leiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Du wirst nicht wie dieselbigen begraben werden; denn du hast dein Land verderbet und dein Volk erschlagen; denn man wird der Boshaftigen Samen nimmermehrgedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Richtet zu, daß man seine Kinder schlachte urn ihrer Vater Missetat willen, daß sie nicht aufkommen, noch das Land erben, noch den Erdboden voll Stadte machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Und ich will uber sie kommen, spricht der HERR Zebaoth, und zu Babel ausrotten ihr Gedachtnis, ihre Ubrigen, Neffen und Nachkommen, spricht der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'und will sie machen zum Erbe den Igeln und zum Wassersee und will sie mit einem Besen des Verderbens kehren, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Der HERR Zebaoth hat geschworen und gesagt: Was gilt\'s, es soil gehen, wie ich denke, und soil bleiben, wie ich\'s im Sinn habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'daß Assur zerschlagen werde in meinem Lande, und ich ihn zertrete auf meinen Bergen, auf daß sein Joch von ihnen genommen werde und seine Burde von ihrem Halse komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Das ist der Anschlag, den er hat uber alle Lande, und das ist die ausgereckte Hand uber alle Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Denn der HERR Zebaoth hat\'s beschlossen; wer will\'s wehren? Und seine Hand ist ausgereckt; wer will sie wenden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Im Jahr, da der Koniq Ahas starb, war dies die Last:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Freue dich nicht, du ganz Philisterland, daß die Rute, die dich schlug, zerbrochen ist. Denn aus der Wurzel der Schlange wird ein Basilisk kommen, und ihre Frucht wird ein feuriger fliegender Drache sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Denn die Erstlinge der Dürftigen werden sich weiden und die Armen sicher ruhen; aber deine Wurzel will ich mit Hunger toten, und deine Ubrigen wird ererwürgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Heule, Tor; schreie, Stadt! Ganz Philisterland ist feige; denn von Mitternacht kommt ein Rauch, und ist kein Einsamer in seinen Gezelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Und was werden die Boten der Heiden hin und wieder sagen? Namlich: Zion hat der HERR gegründet; und daselbst werden die Elenden seines Volks Zuversicht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Dies ist die Last über Moab: Des Nachts kommt Verstorung über Ar in Moab; sie ist dahin. Des Nachts kommt Verstorung über Kir in Moab; sie ist dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Sie gehen hinauf gen Baith und Dibon zu den Altaren, daß sie weinen und heulen über Nebo und Medba in Moab. Aller Haupt ist beschoren, aller Bart ist abgeschnitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Auf ihren Gassen gehen sie mit Sacken umgurtet; auf ihren Dachern und Straften heulen sie alle und gehen weinend herab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon und Eleale schreien, dafi man\'s zu Jahza horet. Darum wehklagen die Gerusteten in Moab; denn es gehet ihrer Seele ubel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mein Herz schreiet zu Moab; ihre Fluchtigen fliehen von der dreijahrigen Kuh, bis gen Zoar; denn sie gehen gen Luhith hinan und weinen; und auf dem Wege zu Horonaim zu erhebt sich ein Jammergeschrei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Denn die Wasserzu Nimrim versiegen, dafi das Heu verdorret, und das Gras verwelket, und wachset kein grun Kraut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Denn das Gut, das sie gesammelt, und das Volk, das sie gerustet haben, führet man uber den Weidenbach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Geschrei gehet um in den Grenzen Moabs; sie heulen bis gen Eglaim und heulen bei dem Born Elim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Denn die Wasserzu Dimon sind voll Bluts. Dazu will ich uber Dimon noch mehr kommen lassen, beide über die erhalten sind in Moab des Lowen, und uber die Ubrigen im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Lieber schicket, ihr Landesherren, Lammer von Sela aus der Wuste zum Berge der Tochter Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Aber wie ein Vogel dahinfleugt, der aus dem Nest getrieben wird, so werden sein die Tochter Moabs, wenn sie vor Arnon vorüberziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Sammelt Rat, haltet Gericht; mache dir Schatten des Mittags wie eine Nacht; verbirg die Verjagten und melde die Fluchtigen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Laft meine Verjagten bei dir herbergen; liebes Moab, sei du ihr Schirm vor dem Verstorer; so wird der Treiber ein Ende haben, der Verstorer aufhoren und der Untertreter ablassen im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Es wird aber ein Stuhl bereitet werden aus Gnaden, daß einer darauf sitze in der Wahrheit, in der Hütte Davids, und richte und trachte nach Recht und fordere Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Wir horen aber von dem Hochmut Moabs, daß er fast graft ist, daß auch ihr Hochmut, Stolz und Zorn grafter ist denn ihre Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Darum wird ein Moabiter über den andern heulen, allesamt werden sie heulen. Uber die Grundfesten der Stadt Kir-Hareseth werden die Verlahmten seufzen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Denn Hesbon ist ein wüstes Feld worden, der Weinstock zu Sibma ist verderbt, die Herren unter den Heiden haben seine edlen Reben zerschlagen und sind kommen bis gen Jaeser und ziehen um in der Wuste; ihre Feser sind zerstreuet und über das Meer geführt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Darum weine ich um Jaeser und um den Weinstock zu Sibma und vergiefie viel Tranen um Hesbon und Eleale. Denn es ist ein Gesang in deinen Sommer und in deine Ernte gefallen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'daß Freude und Wonne im Felde aufhoret, und in Weinbergen jauchzet noch ruft man nicht. Man keltert keinen Wein in den Keltern; ich habe des Gesangs ein Ende gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Darum brummet mein Herz uber Moab wie eine Harfe und mein Inwendiges über Kir-Hares.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Alsdann wird\'s offenbar werden, wie Moab müde ist bei den Altaren und wie er zu seiner Kirche gegangen sei zu beten, und doch nichts ausgerichtet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Das ist\'s, das der HERR dazumal wider Moab geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Nun aber redet der HERR und spricht: In dreien Jahren, wie eines Taglohners Jahre sind, wird die Herrlichkeit Moabs geringe werden in dergroften Menge, daß gar ein wenig überbleibe und nicht viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Dies ist die Last uber Damaskus: Siehe, Damaskus wird keine Stadt mehr sein, sondern ein zerfallener Steinhaufe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Die Stadte Aroer werden verlassen sein, daß Herden daselbst weiden, die niemand scheuche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Und wird aus sein mit der Feste Ephraim; und das Konigreich zu Damaskus und das Ubrige zu Syrien wird sein wie die Herrlichkeit der Kinder Israel, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Zu der Zeit wird die Herrlichkeit Jakobs dünn sein, und sein fetter Leib wird mager sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Denn sie wird sein, alswenn einer Getreide einsammelte in der Ernte, und als wenn einer mit seinem Arm die Ahren einerntete, und als wenn einer Ahren lase im Tal Rephaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'und eine Nachernte drinnen bliebe, alswenn man einen Olbaum schuttelte, daß zwo und drei Beeren blieben oben in dem Wipfel, Oder als wenn vier Oder fünf Fruchte an den Zweigen hangen, spricht der HERR, der Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Zu der Zeit wird sich der Mensch halten zu dem, der ihn gemacht hat; und seine Augen werden auf den Heiligen in Israel schauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Und wird sich nicht halten zu den Altaren, die seine Hande gemacht haben, und nicht schauen auf das, das seine Finger gemacht haben, weder auf Haine noch Bilder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Zu der Zeit werden die Stadte ihrer Starke sein wie ein verlassener Ast und Zweig, so verlassen ward vor den Kindern Israel; und werden wuste sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Denn du hast vergessen Gottes, deines Heils, und nicht gedacht an den Fels deiner Starke. Darum wirst du lustige Pflanzen setzen, aber du wirst damit den Fremden die Feser gelegt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Zur Zeit des Pflanzens wirst du sein wohl warten, daß dein Same zeitlich wachse; aber in der Ernte, wenn du die Mandeln sollst erben, wirst du dafür Schmerzen eines Betrubten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'O wehe der Menge so graven Volks! Wie das Meerwird es brausen, und das Getümmel der Leute wird wüten, wie grolie Wasserwüten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Ja, wie grolie Wasserwüten, sowerden die Leute wüten. Aber er wird sie schelten, so werden sie feme wegfliehen; und wird sie verfolgen, wie dem Staube auf den Bergen vom Winde geschieht, und wie einem Windwirbel vom Ungewitter geschieht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Um den Abend, siehe, so ist Schrecken da; und ehe es Morgen wird, sind sie nimmer da. Das ist der Lohn unserer Rauber und das Erbe derer, die uns das Unsere nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Wehe dem Lande, das unterden Segeln im Schatten fahret, diesseit der Wasser des Mohrenlandes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'das Botschaften auf dem Meer sendet und in Rohrschiffen auf den Wassern fahret. Gehet hin, ihr schnellen Boten, zum Volk, das zerrissen und geplündert ist, zum Volk, das greulicher ist denn sonst irgendeins, zum Volk, das hie und da ausgemessen und zertreten ist, welchem die Wasserstrome sein Land einnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Alle, die ihr auf Erden wohnet und die im Lande sitzen, werdet sehen, wie man das Panier auf den Bergen aufwerfen wird, und horen, wie man die Trommeten blasen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Denn so spricht der HERR zu mir: Ich will stille halten und schauen in meinem Sitz, wie eine Hitze, die den Regen austrocknet, und wie ein Meltau in der Hitze der Ernte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Denn vor der Ernte wird das Gewachs abnehmen, und die unreife Frucht in der Blüte verdorren, dafi man die Stengel muft mit Sicheln abschneiden und die Reben wegtun und abhauen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'daß man\'s miteinander muft lassen liegen dem Gevogel auf den Bergen und den Tieren im Lande, daß des Sommers die Vogel drinnen nisten und des Winters allerlei Tiere im Lande drinnen liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Zu der Zeit wird das zerrissene und geplünderte Volk, das greulicher ist denn sonst irgendeins, das hie und da abgemessen und zertreten ist, welchem die Wasserstrome sein Land einnehmen, Geschenke bringen dem HERRN Zebaoth an den Ort, da der Name des HERRN Zebaoth ist, zum Berge Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Dies ist die Last uber Agypten: Siehe, der HERR wird auf einer schnellen Wolke fahren und nach Agypten kommen. Da werden die Gotzen in Agypten vor ihm beben, und den Agyptern wird das Herz feige werden in ihrem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Und ich will die Agypter aneinander hetzen, daß ein Bruder wider den andern, ein Freund wider den andern, eine Stadt wider die andere, ein Reich wider das andere streiten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Und der Mut soil den Agyptern unter ihnen vergehen, und will ihre Anschlage zunichte machen. Da werden sie dann fragen ihre Gotzen und Pfaffen und Wahrsager und Zeichendeuter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Aber ich will die Agypter übergeben in die Hand grausamer Herren; und ein harter Konig soil fiber sie herrschen, spricht der Herrscher, der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Und das Wasser in den Seen wird vertrocknen, dazu der Strom wird versiegen und verschwinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Und die Wasser werden verlaufen, daß die Seen an Dammen werden geringe und trocken werden, beide Rohr und Schilf verwelken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'und das Gras an den Wassern verstieben, und alle Saat am Wasser wird verwelken und zunichte werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Und die Fischer werden trauern; und alle die, so Angel ins Wasser werfen, werden klagen, und die, so Netze auswerfen aufs Wasser, werden betrubt sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Es werden mit Schanden bestehen, die da gute Game wirken und Netze stricken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Und die da Halter haben, samt alien, die Teiche um Lohn machen, werden bekümmertsein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Die Fursten zu Zoan sind Toren, die weisen Rate Pharaos sind im Rat zu Narren worden. Was sagt ihr doch von Pharao: Ich bin der Weisen Kind und komme von aiten Konigen her?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Wo sind denn nun deine Weisen? Laft sie dir\'s verkundigen und anzeigen, was der HERR Zebaoth uber Agypten beschlossen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Aber die Fursten zu Zoan sind zu Narren worden, die Fursten zu Noph sind betrogen; sie verfuhren samt Agypten den Eckstein der Geschlechter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Denn der HERR hat einen Schwindelgeist unter sie ausgegossen, daß sie Agypten verfuhren in all ihrem Tun, wie ein Trunkenbold taumelt, wenn er speiet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Und Agypten wird nichts haben das Haupt Oder Schwanz, Ast Oder Stumpf zeuge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Zu der Zeit wird Agypten sein wie Weiber und sich furchten und erschrecken, wenn der HERR Zebaoth die Hand uber sie weben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Und Agypten wird sich furchten vor dem Lande Juda, daß, wer desselbigen gedenkt, wird davor erschrecken, uber dem Rat des HERRN Zebaoth, den er uber sie beschlossen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Zu der Zeit werden fünf Stadte in Agyptenland reden nach der Sprache Kanaans und schworen bei dem HERRN Zebaoth. Eine wird heiften Irheres.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Zur selbigen Zeit wird des HERRN Altar mitten in Agyptenland sein und ein Malstein des HERRN an den Grenzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'welcherwird ein Zeichen und Zeugnis sein dem HERRN Zebaoth in Agyptenland. Denn sie werden zum HERRN schreien vor den Beleidigern; so wird er ihnen senden einen Heiland und Meister, der sie errette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Denn der HERR wird den Agyptern bekannt werden; und die Agypter werden den HERRN kennen zu der Zeit und werden ihm dienen mit Opfer und Speisopfer und werden dem HERRN geloben und halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Und der HERR wird die Agypter plagen und heilen; denn sie werden sich bekehren zum HERRN; und erwird sich erbitten lassen und sie heilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Zu der Zeit wird eine Bahn sein von Agypten in Assyrien, daß die Assyrer in Agypten und die Agypter in Assyrien kommen, und die Agypter samt den Assyrern Gott dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Zu der Zeit wird Israel selbdritte sein mit den Agyptern und Assyrern durch den Segen, so auf Erden sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Denn der HERR Zebaoth wird sie segnen und sprechen: Gesegnet bist du, Agypten, mein Volk, und du, Assur, meiner Hande Werk, und du, Israel, mein Erbe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Im Jahr, da Tharthan gen Asdod kam, als ihn gesandt hatte Sargon, der Konig zu Assyrien, und stritt wider Asdod und gewann sie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'zur selbigen Zeit redete der HERR durch Jesaja, den Sohn Amoz, und sprach: Gehe hin und zieh ab den Sack von deinen Lenden und zieh deine Schuhe aus von deinen Füßen. Und ertat also, ging nackend und barfuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Da sprach der HERR: Gleichwie mein Knecht Jesaja nackend und barfuß gehet zum Zeichen und Wunderdreier Jahre uber Agypten und Mohrenland,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'also wird der Konig zu Assyrien hintreiben das gefangene Agypten und vertriebene Mohrenland, beide jung und alt, nackend und barfufi, mit bloßer Scham, zu Schanden Agyptens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Und sie werden erschrecken und mit Schanden bestehen uber dem Mohrenlande, darauf sie sich verlielien, und wiederum das Mohrenland uber den Agyptern, welcher sie sich ruhmeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Und die Einwohner dieser Inseln werden sagen zur selbigen Zeit: 1st das unsere Zuversicht, da wir hinflohen urn Hilfe, daü wir errettet würden von dem Konige zu Assyrien? Wie fein sind wir entronnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Dies ist die Last uber die Wuste am Meer: Wie ein Wetter vom Mittag kommt, das alles umkehret, so kommt\'s aus der Wuste, aus einem grausamen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Denn mir ist ein hart Gesicht angezeigt. Ein Verachter kommt wider den andern, ein Verstorer wider den andern. Zeuch herauf, Elam; belege sie, Madai! Ich will all seines Seufzens ein Ende machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Derhalben sind meine Lenden voll Schmerzens, und Angst hat mich ergriffen, wie eine Gebarerin; ich krümme mich, wenn ich\'s hore, und erschrecke, wenn ich\'s ansehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mein Herz zittert, Grauen hat mich erschreckt; ich habe in der lieben Nacht keine Ruhe davor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Ja, richte einen Tisch zu, laß wachen auf der Warte, esset, trinket; macht euch auf, ihr Fursten, schmieret den Schild!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Denn der HERR sagt zu mir also: Gehe hin, stelle einen Wachter, der da schaue und ansage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Er siehet aber Reiter reiten und fahren auf Rossen, Eseln und Kamelen und hat mitgroßem Fleiß Achtung darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Und ein Lowe rief: HERR, ich stehe auf der Warte immerdar des Tages und stelle mich auf meine Hut alle Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Und siehe, da kommt einer, der fahret auf einem Wagen, der antwortet und spricht: Babel ist gefallen, sie ist gefallen, und alle Bilder ihrer Gotter sind zu Boden geschlagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Meine liebe Tenne, darauf ich dresche: Was ich gehort habe vom HERRN Zebaoth, dem Gott Israels, das verkundige ich euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Dies ist die Last uber Duma. Man ruft zu mir aus Seir: Hitter, ist die Nacht schier hin? Hitter, ist die Nacht schier hin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Der Hitter aber sprach: Wenn der Morgen schon kommt, so wird es doch Nacht sein. Wenn ihr schon fraget, so werdet ihr doch wiederkommen und wiederfragen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Dies ist die Last itber Arabien: Ihrwerdetim Walde in Arabien wohnen, auf dem Wege gen Dedanim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Bringetden Durstigen Wasserentgegen, die ihr wohnet im Lande Thema; bietet Brot den Flüchtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Denn siefliehen vordem Schwert, ja vordem blofien Schwert, vordem gespannten Bogen, vordem großen Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Denn also spricht der HERRzu mir: Noch in einem Jahr, wie des Tagelohners Jahre sind, soil alle Herrlichkeit Kedars untergehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'und der übrigen Schützen der Helden zu Kedar soli weniger werden; denn der HERR, der Gott Israels, hat\'s geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Dies ist die Last uber das Schautal: Was ist denn euch, daß ihr alle so auf die Dacher laufet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Du warest voll Getones, eine Stadt voll Volks, eine frohliche Stadt. Deine Erschlagenen sind nicht mit dem Schwert erschlagen und nicht im Streit gestorben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'sondern alle deine Hauptleute sind vordem Bogen weggewichen und gefangen; alle, die man in dirfunden hat, sind gefangen und fern geflohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Darum sage ich: Hebt euch von mir, laßt mich bitterlich weinen; mühet euch nicht, mich zu trosten itber der Verstorung der Tochter meines Volks!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Denn es ist ein Tag des Getummels und der Zertretung und Verwirrung vom Herm HERRN Zebaoth im Schautal um des Untergrabens willen der Mauern und des Geschreies am Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Denn Elam fahret daher mit Kocher, Wagen, Leuten und Reitern, und Kir glanzet daher mit Schilden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Und wird geschehen, daß deine auserwahlten Tale werden voll Wagen sein, und Reiter werden sich lagern vor, die Tore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Da wird der Vorhang Judas aufgedeckt werden, dad man schauen wird zu der Zeit den Zeug im Hause des Waldes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Und werdet der Risse an der Stadt Davids viel sehen und werdet das Wasser im unteren Teich sammeln mussen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Ihr werdet auch die Hauser zu Jerusalem zahlen; ja, ihr werdet die Hauser abbrechen, die Mauern zu befestigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Und werdet einen Graben machen zwischen beiden Mauern vom Wasser des alten Teichs. Noch sehet ihr nicht auf den, der solches tut, und schauet nicht auf den, der solches schaffet von feme her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Darum wird der Herr HERR Zebaoth zu der Zeit rufen lassen, dafi man weine und klage und sich beschere und Sacke anziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Wiewohl jetzt, siehe, ist\'s eitel Freude und Wonne, Ochsen wurgen, Schafe schlachten, Fleisch essen, Wein trinken (und sprechet): Lafit uns essen und trinken, wir sterben doch morgen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Solches ist vor den Ohren des HERRN Zebaoth offenbar. Was gilt\'s, ob euch diese Missetat soil vergeben werden, bis ihr sterbet? spricht der Herr HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So spricht der Herr HERR Zebaoth: Gehe hinein zum Schatzmeister Sebna, dem Hofmeister, und sprich zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Was hast du hie? Wem gehorest du an, daß du dir ein Grab hie hauen lassest, als der sein Grab in der Hohe hauen laftt, und als der seine Wohnung in den Felsen machen lafit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Siehe, der HERR wird dich wegwerfen, wie ein Starker einen wegwirft, und dich zuscharren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'und wird dich umtreiben wie eine Kugel auf weitem Lande; daselbst wirst du sterben, daselbst werden deine kostlichen Wagen bleiben mit Schmach des Hauses deines HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Und ich will dich von deinem Stande sturzen und von deinem Amt will ich dich setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Und zu der Zeit will ich rufen meinem Knecht Eliakim, dem Sohn Hilkias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'und will ihm deinen Rockanziehen und mit deinem Gürtel gurten und deine Gewalt in seine Hand geben, dafi er Vater sei derer, die zu Jerusalem wohnen, und des Hauses Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Und will die Schlussel zum Hause David auf seine Schulter legen, dafi er auftue und niemand zuschliefte, daß erzuschliefte und niemand auftue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Und will ihn zum Nagel stecken an einen festen Ort, und soil haben den Stuhl der Ehren in seines Vaters Hause,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'daß man an ihn hange alle Herrlichkeit seines Vaters Hauses; Kind und Kindeskinder, alle kleinen Gerate, beide, Trinkgefafte und allerlei Saitenspiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Zu der Zeit, spricht der HERR Zebaoth, soil der Nagel weggenommen werden, der am festen Ort steckt, daß er zerbreche und falle und seine Last umkomme. Denn der HERR sagt es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Dies ist die Last uber Tyrus: Heulet, ihr Schiffe auf dem Meer, denn sie ist zerstoret, daß kein Haus da ist, noch jemand dahin zeucht. Aus dem Lande Chittim werden sie des gewahr werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Die Einwohner der Inseln sind stille worden. Die Kaufleute zu Zidon, die durchs Meer zogen, fülleten dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Und was fur Fruchte am Sihor und Getreide am Wasser wuchs, brachte man zu ihr hinein durch grofte Wasser; und du warest der Heiden Markt worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Du magst wohl erschrecken, Zidon! Denn das Meer, ja die Feste am Meer spricht: Ich bin nicht mehr schwanger, ich gebare nicht mehr; so ziehe ich keine Junglinge auf und erziehe keine Jungfrauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Gleichwie man erschrak, da man von Agypten horete, also wird man auch erschrecken, wenn man von Tyrus horen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Fahret hin aufs Meer; heulet, ihr Einwohner der Inseln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ist das eure frohliche Stadt, die sich ihres Alters ruhmete? Ihre Fufte werden sie feme wegfuhren zu wallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Wer hatte das gemeinet, daß es Tyrus, der Krone, so gehen sollte, so doch ihre Kaufleute Fursten sind und ihre Kramer die Herrlichsten im Lande?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Der HERR Zebaoth hat\'s also gedacht, auf daß er schwachte alle Pracht der lustigen Stadt und verachtlich machte alle Herrlichen im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Fahre hin durch dein Land wie ein Strom, du Tochter des Meers; da ist kein Gurt mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Er reckt seine Hand über das Meer und erschreckt die Konigreiche. Der HERR gebeut fiber Kanaan, zu vertilgen ihre Machtigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'und spricht: Du sollst nicht mehr frohlich sein, du geschandete Jungfrau, du Tochter Zidon! 0 Chittim, mach dich auf und zeuch fort; denn du muftt da nicht bleiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'sondern in der Chaldaer Land, das nicht ein Volk war, sondern Assur hat es angerichtet zu Schiffen und haben feste Turme drinnen aufgerichtet und Palaste aufgebauet. Aber sie ist gesetzt, daß sie geschleift werden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Heulet, ihr Schiffe auf dem Meer; denn eure Macht ist zerstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Zu der Zeit wird Tyrus vergessen werden siebenzig Jahre, solange ein Konig leben mag. Aber nach siebenzig Jahren wird man von Tyrus ein Hurenlied singen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Nimm die Harfe, gehe in der Stadt urn, du vergessene Hure; mach es gut auf dem Saitenspiel und singe getrost, auf daß dein wieder gedacht werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Denn nach siebenzig Jahren wird der HERR Tyrus heimsuchen, daß sie wieder komme zu ihrem Hurenlohn und Hurerei treibe mit alien Konigreichen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Aber ihr Kaufhandel und Hurenlohn werden dem HERRN heilig sein. Man wird sie nicht zu Schatz sammeln noch verbergen, sondern dievordem HERRN wohnen, werden ihr Kaufgut haben, daß sie essen und satt werden und wohl bekleidet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Siehe, der HERR macht das Land leer und wüste und wirft urn, was drinnen ist, und zerstreuet seine Einwohner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Und gehet dem Priesterwie dem Volk, dem Herrn wie dem Knechte, der Frau wie der Magd, dem Verkaufer wie dem Kaufer, dem Leiher wie dem Borger, dem Mahnenden wie dem Schuldiger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Denn das Land wird leer und beraubt sein; denn der HERR hat solches geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Das Land stehet jammerlich und verderbt, der Erdboden nimmt ab und verdirbt; die Hochsten des Volks im Lande nehmen ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Das Land ist entheiliget von seinen Einwohnern; denn sie ubergehen das Gesetz und andern die Gebote und lassen fahren den ewigen Bund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Darum friftt der Fluch das Land; denn sie verschulden es, die drinnen wohnen. Darum verdorren die Einwohner des Landes, daß wenig Leute uberbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Der Most verschwindet, der Weinstock verschmachtet, und alle, die von Herzen frohlich waren, seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Die Freude der Pauken feiert, das Jauchzen der Frohlichen ist aus, und die Freude der Harfen hat ein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Man singet nicht beim Weintrinken; und gut Getrank ist bitter denen, so es trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Die leere Stadt istzerbrochen; alle Hauser sind zugeschlossen, daß niemand hineingehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Man klagt Wein auf den Gassen, daß alle Freude weg ist, alle Wonne des Landes dahin ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Eitel Wüstung ist in der Stadt geblieben, und die Tore stehen ode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Denn es gehet im Lande und im Voikeben, als wenn ein Olbaum abgepflückt ist, als wenn man nachlieset, so die Weinernte aus ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Dieselbigen heben ihre Stimme auf und ruhmen und jauchzen vom Meer her uber der Herrlichkeit des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'So preiset nun den HERRN in Grunden, in den Inseln des Meers den Namen des HERRN, des Gottes Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Wir horen Lobgesange vom Ende der Erde zu Ehren dem Gerechten. Und ich muft sagen: Wie bin ich aber so mager! Wie bin ich aber so mager! Wehe mir; denn die Verachter verachten, ja die Verachter verachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Darum kommt uber euch, Einwohner des Landes, Schrecken, Grube und Strick.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Und ob einer entflohe vor dem Geschrei des Schreckens, so wird er doch in die Grube fallen; kommt er aus der Grube, so wird er doch im Strick gefangen werden. Denn die Fenster in der Hohe sind aufgetan, und die Grundfesten der Erde beben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Es wird dem Lande ubel gehen und nichts gelingen und wird zerfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Das Land wird taumeln wie ein Trunkener und weggeführt wie eine Hütte; denn seine Missetat drückt es, daß es fallen muft und kann nicht stehenbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Zu der Zeit wird der HERR heimsuchen die hohe Ritterschaft, so in der Hohe sind, und die Konige der Erde, so auf Erden sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'daß sie versammelt werden in ein Bündlein zur Grube und verschlossen werden im Kerker und nach langer Zeit wieder heimgesucht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Und der Mond wird sich schamen und die Sonne mit Schanden bestehen, wenn der HERR Zebaoth Konig sein wird auf dem Berge Zion und zu Jerusalem und vor seinen Altesten in der Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'HERR, du bist mein Gott; dich preise ich. Ich lobe deinen Namen, denn du tust Wunder. Deine Vornehmen von alters her sind treu und wahrhaftig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Denn du machest die Stadt zum Steinhaufen, die feste Stadt, daß sie auf einem Haufen liegt, der Fremden Palast, daß nicht mehr eine Stadt sei und nimmer mehr gebauet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Darum ehret dich ein machtig Volk, die Stadte gewaltiger Heiden fürchten dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Denn du bist der Geringen Starke, der Armen Starke in Trubsal, eine Zuflucht vor dem Ungewitter, ein Schatten vor der Hitze, wenn die Tyrannen wüten, wie ein Ungewitter wider eine Wand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Du demütigest der Fremden Ungestum wie die Hitze in einem dürren Ort, daß die Hitze die Rebe der Tyrannen verderbe, und die Wolke dennoch Schatten gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Und der HERR Zebaoth wird alien Volkern machen auf diesem Berge ein fett Mahl, ein Mahl von reinem Wein, von Fett, von Mark, von Wein, darin keine Hefe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Und erwird auf diesem Berge das Hüllen wegtun, damit alle Volker verhullet sind, und die Decke, damit alle Heiden zugedeckt sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Denn er wird den Tod verschlingen ewiglich. Und der Herr HERR wird die Tranen von alien Angesichtern abwischen und wird aufheben die Schmach seines Volks in alien Landen; denn der HERR hat\'s gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Zu der Zeit wird man sagen: Siehe, das ist unser Gott, aufden wir harren, und erwird uns helfen; das ist der HERR, auf den wir harren, daß wir uns freuen und frohlich seien in seinem Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Denn die Hand des HERRN ruhet auf diesem Berge. Moab aberwird unter ihm zerdroschen werden, wie Stroh zerdroschen wird, und wie Kot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Und er wird seine Hande ausbreiten mitten unter sie, wie sie ein Schwimmer ausbreitet zu schwimmen; und wird ihre Pracht niedrigen mit den Armen seiner Hande');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'und die hohe Festung eurer Mauern beugen, niedrigen und in den Staub zu Boden werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Zu der Zeit wird man ein solch Lied singen im Lande Juda: Wir haben eine feste Stadt, Mauer und Wehre sind Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Tut die Tore auf, daß hereingehe das gerechte Volk, das den Glauben bewahret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Du erhaltst stets Frieden nach gewisser Zusage; denn man verlasset sich auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Darum verlasset euch auf den HERRN ewiglich; denn Gott der HERR ist ein Fels ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Und er beuget die, so in der Hohe wohnen; die hohe Stadt niedriget er, ja, er stoftet sie zu der Erde, daß sie im Staube liegt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'daß sie mit Füften zertreten wird, ja mit Fuften der Armen, mit Fersen der Geringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Aber des Gerechten Weg ist schlecht; den Steig des Gerechten machst du richtig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Denn wirwarten auf dich, HERR, im Wege deines Rechten; des Herzens Lust stehet zu deinem Namen und deinem Gedachtnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Von Herzen begehre ich dein des Nachts, dazu mit meinem Geiste in mirwache ich frühe zu dir. Denn wo dein Recht im Lande gehet, so lernen die Einwohner des Erdbodens Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Aberwenn den Gottlosen gleich Gnade angeboten wird, so lernen sie doch nicht Gerechtigkeit, sondern tun nur ubel im richtigen Lande; denn sie sehen des HERRN Herrlichkeit nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'HERR, deine Hand ist erhohet, das sehen sie nicht; wenn sie es aber sehen werden, so werden sie zuschanden werden im Eifer uber die Heiden; dazu wirst du sie mit Feuer, damit du deine Feinde verzehrest, verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Aber uns, HERR, wirst du Frieden schaffen; denn alles, was wir ausrichten, das hast du uns gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'HERR, unser Gott, es herrschen wohl andere Herren uber uns denn du; aber wir gedenken doch allein dein und deines Namens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Die Toten bleiben nicht leben, die Verstorbenen stehen nicht auf; denn du hast sie heimgesucht und vertilget und zunichte gemacht all ihr Gedachtnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Aber du, HERR, fahrest fort unter den Heiden, du fahrest immer fort unter den Heiden, beweisest deine Herrlichkeit und kommst feme bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'HERR, wenn Trubsal da ist, so suchet man dich; wenn du sie zuchtigest, so rufen sie angstiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Gleichwie eine Schwangere, wenn sie schier gebaren soil, so ist ihr angst, schreiet in ihren Schmerzen: so gehet\'s uns auch, HERR, vor deinem Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Da sind wir auch schwanger und ist uns bange, daß wir kaum Odem holen; noch konnen wir dem Lande nicht helfen, und die Einwohner auf dem Erdboden wollen nicht fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Aber deine Toten werden leben und mit dem Leichnam auferstehen. Wachet auf und rühmet, die ihr lieget unter der Erde; denn dein Tau ist ein Tau des grunen Feldes. Aber das Land der Toten wirst du sturzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Gehe hin, mein Volk, in deine Kammer und schleuft die Tür nach dir zu; verbirg dich einen kleinen Augenblick, bis der Zorn vorubergehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Denn siehe, der HERR wird ausgehen von seinem Ort, heimzusuchen die Bosheit der Einwohner des Landes uber sie, daß das Land wird offenbaren ihr Blut und nicht weiter verhehlen, die drinnen erwurget sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Zu der Zeit wird der HERR heimsuchen mit seinem harten, groften und starken Schwert beide den Leviathan, der eine schlechte Schlange, und den Leviathan, der eine krumme Schlange ist, und wird die Drachen im Meer erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Zu der Zeit wird man singen von dem Weinberge des besten Weins:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ich der HERR, behute ihn und feuchte ihn bald, daß man seiner Blatter nicht vermisse; ich will ihn Tag und Nacht behuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Gott zurnet nicht mit mir. Ach, daß ich mochte mit den Hecken und Dornen kriegen! So wollte ich unter sie reiften und sie auf einen Haufen anstecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Er wird mich erhalten bei meiner Kraft und wird mir Frieden schaffen; Frieden wird er mirdennoch schaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Es wird dennoch dazu kommen, daß Jakob wurzeln wird, und Israel bluhen und grunen wird, daß sie den Erdboden mit Fruchten erfullen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Wird erdoch nicht geschlagen, wie ihn seine Feinde schlagen, und wird nicht erwurget, wie ihn seine Feinde erwurgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'sondern mit Maften richtestdu sie und lassest sie los, wenn du sie betrubet hast mit deinem rauhen Wind, namlich mit dem Ostwind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Darum wird dadurch die Sünde Jakobs aufhoren; und das ist der Nutz davon, daß seine Sünden weggenommen werden, in dem, daß er alle Steine des Altars macht wie zerstoßene Steine, zu Asche, daß keine Haine noch Bilder mehr bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Denn die feste Stadt muß einsam werden, die schonen Hauser verstoßen und verlassen werden wie eine Wüste, daß Kalber daselbst weiden und ruhen und daselbst Reiser abfressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Ihre Zweige werden vor Durre brechen, daß die Weiber kommen und Feuer damit machen werden. Denn es ist ein unverstandig Volk; darum wird sich auch ihrer nicht erbarmen, der sie gemacht hat; und der sie geschaffen hat, wird ihnen nicht gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Zu der Zeit wird der HERR worfeln von dem Ufer des Wassers bis an den Bach Agyptens; und ihr Kinder Israel werdet versammelt werden, einer nach dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Zu der Zeit wird man mit einer grolien Posaune blasen, so werden kommen die Verlornen im Lande Assur und die Verstolienen im Lande Agypten und werden den HERRN anbeten auf dem heiligen Berge zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Wehe der prachtigen Krone der Trunkenen von Ephraim, derwelken Blume ihrer lieblichen Herrlichkeit, welche stehet oben uber einem fetten Tal derer, die vom Wein taumeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Siehe, ein Starker und Machtiger vom HERRN, wie ein Hagelsturm, wie ein schadlich Wetter, wie ein Wassersturm, die machtiglich einreißen, wird ins Land gelassen mit Gewalt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'daß die prachtige Krone der Trunkenen von Ephraim mit Fußen zertreten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Und die welke Blume ihrer lieblichen Herrlichkeit, welche stehet oben uber einem fetten Tal, wird sein gleich wie das Reife vor dem Sommer, welches verdirbt, wenn man es noch an seinem Zweige hangen siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Zu der Zeit wird der HERR Zebaoth sein eine liebliche Krone und herrlicher Kranz den Ubrigen seines Volks');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'und ein Geist des Rechts dem, der zu Gericht sitzt, und eine Starke denen, die vom Streit wiederkommen zum Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Dazu sind diese auch vom Wein toll worden und taumeln von starkem Getrank. Denn beide, Priester und Propheten, sind toll von starkem Getranke, sind in Wein ersoffen und taumeln von starkem Getranke; sie sind toll im Weissagen und kocken die Urteile heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Denn alle Tische sind voll Speiens und Unflats an alien Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Wen soil erdenn lehren Erkenntnis? Wem soil er zu verstehen geben die Predigt? Den Entwohnten von der Milch; denen, die von Brusten abgesetzt sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Denn (sie sagen): Gebeut hin, gebeut her; gebeut hin, gebeut her; harre hie, harre da; harre hie, harre da; hie ein wenig, da ein wenig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Wohlan, er wird einmal mit spottischen Lippen und mit einer andern Zunge reden zu diesem Volk, welchem jetzt dies geprediget wird:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'So hat man Ruhe, so erquickt man die Müden, so wird man stille; und wollen doch solcher Predigt nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Darum soli ihnen auch des HERRN Worteben also werden: Gebeut hin, gebeut her; gebeut hin, gebeut her; harre hie, harre da; harre hie; harre da; hie ein wenig, da ein wenig, daß sie hingehen und zurückfallen, zerbrechen, verstrickt und gefangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'So horet nun des HERRN Wort, ihr Spotter, die ihr herrschet uber dies Volk, so zu Jerusalem ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Denn ihrsprechet: Wir haben mit dem Tode einen Bund und mit der Holle einen Verstand gemacht; wenn eine Flut dahergehet, wird sie uns nicht treffen; denn wir haben die Luge zu unserer Zuflucht und Heuchelei zu unserem Schirm gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Darum spricht der Herr HERR: Siehe, ich lege in Zion einen Grundstein, einen bewahrten Stein, einen kostlichen Eckstein, der wohl gegrundet ist. Wer glaubet, derfleucht nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Und ich will das Recht zur Richtschnur und die Gerechtigkeit zum Gewicht machen; so wird der Hagel die falsche Zuflucht wegtreiben, und Wasser sollen den Schirm wegschwemnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'daß euer Bund mit dem Tode los werde und euer Verstand mit der Holle nicht bestehe; und wenn eine Flut dahergehet, wird sie euch zertreten; sobald sie dahergehet, wird sie euch wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Kommt sie des Morgens, so geschieht\'s des Morgens; also auch, sie komme des Tages Oder des Nachts. Denn alleine die Anfechtung lehret aufs Wort merken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Denn das Bett ist so enge, daß nichts ubrig ist, und die Decke so kurz, daß man sich drein schmiegen muß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Denn der HERR wird sich aufmachen wie auf dem Berge Prazim und zurnen wie im Tal Gibeon, daß er sein Werk tue auf eine andere Weise, und daß er seine Arbeit tue auf eine andere Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'So laßt nun euer Spotten, auf daß eure Bande nicht harter werden; denn ich habe ein Verderben und Steuern gehoret, so vom Herrn HERRN Zebaoth geschehen wird in aller Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nehmet zu Ohren und horet meine Stimme; merket auf und horet meine Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Pfluget Oder brachet Oder arbeitet auch ein Ackermann seinen Acker immerdar zur Saat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Ist\'s nicht also? Wenn er\'s gleich gemacht hat, so streuet er Wicken und wirft Kümmel und saet Weizen und Gerste, jegliches, wo er\'s hin haben will, und Spelt an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Also zuchtiget sie auch ihr Gott durch Recht und lehret sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Denn man drischt die Wicken nicht mit Dreschwagen, so lalit man auch nicht das Wagenrad uber den Kümmel gehen, sondern die Wicken schlagt man aus mit einem Stabe und den Kümmel mit einem Stecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Man mahlt es, dad es Brot werde, und drischt es nicht gar zunichte, wenn man\'s mit Wagenradern und Pferden ausdrischet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Solches geschieht auch vom HERRN Zebaoth; denn sein Rat ist wunderbarlich und führet es herrlich hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Wehe Ariel, Ariel, du Stadt des Lagers Davids! Ihr haltet Jahrzeiten und feiert Feste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Aber ich will den Ariel angsten, dad er traurig und jammerig sei, und soil mir ein rechter Ariel sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Denn ich will dich belagern rings umher und will dich angsten mit Bollwerk und will Walle urn dich auffuhren lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Alsdann sollst du geniedriget werden und aus der Erde reden und aus dem Staube mit deiner Rede murmeln, dad deine Stimme sei wie eines Zauberers aus der Erde und deine Rede aus dem Staube wispele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Und die Menge, die dich zerstreuen, werden so viel sein als ein dunner Staub und die Menge der Tyrannen wie eine webende Spreu; und das soil plotzlich bald geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Denn du wirst vom HERRN Zebaoth heimgesucht werden mit Wetter und Erdbeben und grodem Donner, mit Windwirbel und Ungewitter und mit Flammen des verzehrenden Feuers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Aber wie ein Nachtgesicht im Traum, so soil sein die Menge aller Heiden, so wider Ariel streiten, samt all ihrem Heer und Bollwerk, und die ihn angsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Denn gleichwie einem Hungrigen traumet, dad er esse, wenn er aber aufwacht, so ist seine Seele noch leer, und wie einem Durstigen traumet, dad er trinke, wenn er aber aufwacht, ist er matt und durstig: also sollen sein die Menge aller Heiden, die wider den Berg Zion streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Erstarret und werdet besturzt, verblendet euch und werdet trunken, doch nicht vom Wein; taumelt, doch nicht von starkem Getranke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Denn der HERR hat euch einen Geist des harten Schlafs eingeschenkt und eure Augen zugetan; eure Propheten und Fursten samt den Sehern hat er geblendet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'dad euch aller (Propheten) Gesichte sein werden wie die Worte eines versiegelten Buchs, welches, so man\'s gabe einem, der lesen kann, und sprache: Lieber, lies das! und er sprache: Ich kann nicht, denn es ist versiegelt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Oder gleich als wenn man\'s gabe dem, der nicht lesen kann, und sprache: Lieber, lies das! und er sprache: Ich kann nicht lesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Und der HERR spricht: Darum dad dies Volk zu mir nahet mit seinem Munde und mit seinen Lippen mich ehret, aber ihr Herz feme von mir ist, und mich furchten nach Menschengebot, die sie lehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'so will ich auch mit diesem Volk wunderlich umgehen, aufs wunderlichste und seltsamste, dad die Weisheit seiner Weisen untergehe und der Verstand seiner Klugen verblendet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Wehe, die verborgen sein wollen vordem HERRN, ihr Vornehmen zu verhehlen, und ihr Tun, im Finstern halten und sprechen: Wersiehet uns? und wer kennet uns?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Wie seid ihr so verkehrt! Gleich als wenn des Topfers Ton gedachte und ein Werk sprache von seinem Meister: Er hat mich nicht gemacht, und ein Gemachte sprache von seinem Topfer: Er kennet mich nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Wohlan, es ist noch urn ein klein wenig zu tun, so soil Libanon ein Feld werden, und das Feld soil ein Wald gerechnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Denn zurselbigen Zeit werden die Tauben hdren die Worte des Buchs, und die Augen der Blinden werden aus dem Dunkel und Finsternis sehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'und die Elenden werden wieder Freude haben am HERRN, und die Armen unterden Menschen werden frohlich sein in dem Heiligen Israels,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'wenn die Tyrannen ein Ende haben, und mit den Spottern aus sein wird, und vertilget sein werden alle die, so wachen, Muhe anzurichten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'welche die Leute sundigen machen durchs Predigen und stellen dem nach, der sie straft im Tor, weichen durch Lugen vom Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Darum spricht der HERR, der Abraham erloset hat, zum Hause Jakob also: Jakob soil nicht mehr zuschanden werden, und sein Antlitz soil sich nicht mehrschamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Denn wenn sie sehen werden ihre Kinder, die Werke meiner Hande unter ihnen, werden sie meinen Namen heiligen und werden den Heiligen in Jakob heiligen und den Gott Israels furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Denn die, so irrigen Geist haben, werden Verstand annehmen, und die Schwatzer werden sich lehren lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Wehe den abtrünnigen Kindern, spricht der HERR, die ohne mich ratschlagen und ohne meinen Geist Schutz suchen, zu haufen eine Sunde uber die andere,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'die hinabziehen nach Agypten und fragen meinen Mund nicht, dafi sie sich starken mit der Macht Pharaos und sich beschirmen unter dem Schatten Agyptens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Denn es soil euch die Starke Pharaos zur Schande geraten und der Schutz unter dem Schatten Agyptens zum Hohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Ihre Fursten sind wohl zu Zoan gewesen und ihre Botschaft gen Hanes kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'aber sie mussen doch alle zuschanden werden uber dem Volk, das ihnen nicht nütze sein kann, weder zur Hilfe noch sonst zu nutz, sondern nur zur Schande und Spott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Dies ist die Last uber die Tiere, so gegen Mittag ziehen, da Lowen und Lowinnen sind, ja Ottern und feurige fliegende Drachen, im Lande der Trubsal und Angst: Sie führen ihr Gut auf der Füllen Rücken und ihre Schatze auf der Kamele Hooker zum Volk, das ihnen nicht nütze sein kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Denn Agypten ist nichts, und ihr Helfen ist vergeblich. Darum predige ich davon also: Die Rahab wird stille dazu sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'So gehe nun hin und schreib es ihnen vor auf eine Tafel und zeichne es in ein Buch, daß es bleibe fur und fur ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Denn es ist ein ungehorsam Volk und verlogene Kinder, die nicht horen wollen des HERRN Gesetz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'sondern sagen zu den Sehern: Ihr sollt nicht sehen! und zu den Schauern: Ihr sollt uns nicht schauen die rechte Lehre; prediget uns aber sanft, schauet uns Tauscherei!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Weichet vom Wege, macht euch von der Bahn; laftt den Heiligen in Israel aufhoren bei uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Darum spricht der Heilige in Israel also: Weil ihr dies Wort verwerfet und verlasset euch auf Frevel und Mutwillen und trotzet darauf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'so soli euch solche Untugend sein wie ein Rift an einer hohen Mauer, wenn es beginnet zu rieseln, die plotzlich unversehens einfallt und zerschmettert,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'als wenn ein Topf zerschmettert würde, den man zerstoftt und sein nicht schonet, also daß man von seinen Stricken nicht eine Scherbe findet, darin man Feuer hole vom Herde, Oder Wasser schopfe aus einem Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Denn so spricht der Herr HERR, der Heilige in Israel: Wenn ihr stille bliebet, so würde euch geholfen; durch Stillesein und Hoffen würdet ihr stark sein. Aber ihr wollt nicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'und sprechet: Nein, sondern auf Rossen wollen wir fliehen (darum werdet ihr flüchtig sein) und auf Laufern wollen wir reiten (darum werden euch eure Verfolger übereilen).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Denn euer tausend werden fliehen vor eines einigen Schelten, ja vorfünfen werdet ihr alle fliehen; bis daß ihr uberbleibet wie ein Mastbaum oben auf einem Berge, und wie ein Panieroben auf einem Hügel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Darum harret der HERR, daß er euch gnadig sei, und hat sich aufgemacht, daß er sich euer erbarme; denn der HERR ist ein Gott des Gerichts; wohl alien, die sein harren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Denn das Volk Zions wird zu Jerusalem wohnen; du wirst nicht weinen: Erwird dir gnadig sein, wenn du rufest; erwird dir antworten, sobald er\'s horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Und der HERR wird euch in Trubsal Brot und in Angsten Wasser geben. Denn erwird deinen Lehrer nicht mehr lassen wegfliehen, sondern deine Augen werden deinen Lehrer sehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'und deine Ohren werden horen das Wort hinter dir sagen also her: Dies ist der Weg, denselbigen gehet; sonst weder zur Rechten noch zur Linken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Und ihr werdet entweihen eure ubersilberten Gotzen und die guldenen Kleider eurer Bilder und werdet sie wegwerfen wie einen Unflat und zu ihnen sagen: Hinaus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'So wird erdeinem Samen, den du auf den Acker gesaet hast, Regen geben und Brot von des Ackers Einkommen, und desselbigen voile Genüge. Und dein Vieh wird sich zu der Zeit weiden in einer weiten Aue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Die Ochsen und Fullen, so den Acker bauen, werden gemenget Futter essen, welches geworfelt ist mit der Wurfschaufel und Wanne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Und es werden auf alien groften Bergen und auf alien groften Hügeln zerteilte Wasserstrome gehen zur Zeit der groften Schlacht, wenn die Türme fallen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Und des Mondes Schein wird sein wie der Sonnen Schein, und der Sonnen Schein wird siebenmal heller sein denn jetzt, zu der Zeit, wenn der HERR den Schaden seines Volkes verbinden und seine Wunden heilen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Siehe, des HERRN Name kommt von feme, sein Zorn brennet und ist sehr schwer, seine Lippen sind voll Grimmes, und seine Zunge wie ein verzehrend Feuer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'und sein Odem wie eine Wasserflut, die bis an den Hals reicht, zu zerstreuen die Heiden, bis sie zunichte werden, und die Volker mit einem Zaum in ihren Backen hin und her treibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Da werdet ihr singen wie zu Nacht eines heiligen Festes und euch von Herzen freuen, als wenn man mit der Pfeife gehet zum Berge des HERRN, zum Hort Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Und der HERR wird seine herrliche Stimme schallen lassen, daß man sehe seinen ausgereckten Arm mitzornigem Drauen und mit Flammen des verzehrenden Feuers, mit Strahlen, mit starkem Regen und mit Hagel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Denn Assur wird erschrecken vor der Stimme des HERRN, der ihn mit der Rute schlagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Denn es wird die Rute ganz durchdringen und wohl treffen, wenn sie der HERR uber ihn führen wird, mit Pauken und Harfen, und allenthalben wider sie streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Denn die Grube ist von gestern her zugerichtet; ja, dieselbige ist auch dem Kbnige bereitet, tief und weit genug; so ist die Wohnung drinnen, Feuer und Holz die Menge. Der Odem des HERRN wird sie anzünden wie ein Schwefelstrom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Wehe denen, die hinabziehen nach Agypten um Hilfe und verlassen sich auf Rosse und hoffen auf Wagen, daß derselbigen viel sind, und auf Reiter, darum daß sie sehr stark sind, und halten sich nicht zum Heiligen in Israel und fragen nichts nach dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Er aber ist weise und bringet Unglück herzu und wendet seine Worte nicht, sondern wird sich aufmachen wider das Haus der Bosen und wider die Hilfe der Ubeltater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Denn Agypten ist Mensch und nicht Gott, und ihre Rosse sind Fleisch und nicht Geist. Und der HERR wird seine Hand ausrecken, dafi der Heifer strauchele und der, dem geholfen wird, falle, und alle miteinander umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Denn so spricht der HERR zu mir: Gleichwie ein Lowe und ein junger Lowe brullet uber seinem Raube, wenn der Hirten Menge ihn anschreiet, so erschrickt er vor ihrem Geschrei nicht und ist ihm auch nicht leid vor ihrer Menge: also wird der HERR Zebaoth herniederfahren, zu streiten auf dem Berge Zion und auf seinem Hugel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Und der HERR Zebaoth wird Jerusalem beschirmen, wie die Vogel tun mit Flugeln, schutzen, erretten, drinnen umgehen und aushelfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Kehret um, ihr Kinder Israel, die ihrsehr abgewichen seid!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Denn zu der Zeit wird ein jeglicher seine silbernen und guldenen Gotzen verwerfen, welche euch eure Hande gemacht hatten zur Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Und Assur soli fallen, nicht durch Manns Schwert, und soli verzehret werden, nicht durch Menschen Schwert; und wird doch vor dem Schwert fliehen, und seine junge Mannschaftwird zinsbar werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'und ihr Fels wird vor Furchtwegziehen, und seine Fursten werden vor dem Panier die Flucht geben, spricht der HERR, der zu Zion Feuer und zu Jerusalem einen Herd hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Siehe, es wird ein Konig regieren, Gerechtigkeit anzurichten, und Fursten werden herrschen, das Recht zu handhaben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'dafi jedermann sein wird als einer, der vor dem Winde bewahret ist, und wie einer, der vor dem Platzregen verborgen ist, wie die Wasserbache am durren Ort, wie der Schatten eines grolien Felsen im trockenen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Und der Sehenden Augen werden sich nicht blenden lassen, und die Ohren der Zuhorer werden aufmerken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'und die Unvorsichtigen werden Klugheit lernen, und der Stammelnden Zunge wird fertig und reinlich reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Es wird nicht mehr ein Narr Fürst heifien noch ein Geiziger Herr genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Denn ein Narr redet von Narrheit, und sein Herz gehet mit Unglück um, daß er Heuchelei anrichte und predige vom HERRN Irrsal, damit erdie hungrigen Seelen aushungere und den Durstigen das Trinken wehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Denn des Geizigen Regieren ist eitel Schaden; denn er erfindet Tucke, zu verderben die Elenden mit falschen Worten, wenn er des Armen Recht reden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Aber die Fursten werden furstliche Gedanken haben und drüber halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Stehet auf, ihr stolzen Frauen, horet meine Stimme; ihr Tochter, die ihr so sicher seid, nehmet zu Ohren meine Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Es ist um Jahr und Tag zu tun, so werdet ihr Sicheren zittern; denn es wird keine Weinernte, so wird auch kein Lesen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Erschrecket, ihr stolzen Frauen, zittert, ihr Sicheren! Es istvorhanden ausziehen, blolien und gürten um die Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Man wird klagen um die Acker, ja um die lieblichen Acker, um die fruchtbaren Weinstocke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Denn es werden auf dem Acker meines Volks Dornen und Hecken wachsen, dazu über alien Freudenhausern in der frohlichen Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Denn die Palaste werden verlassen sein und die Menge in der Stadt einsam sein, daß die Türme und Festungen ewige Hohlen werden und dem Wild zur Freude, den Herden zur Weide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'bis so lange, daß über uns ausgegossen werde der Geist aus der Hohe. So wird denn die Wüste zum Acker werden und der Acker fur einen Wald gerechnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Und das Recht wird in der Wüste wohnen und Gerechtigkeit auf dem Acker hausen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Und der Gerechtigkeit Fruchtwird Friede sein, und der Gerechtigkeit Nutz wird ewige Stille und Sicherheit sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'daß mein Volk in Hausern des Friedens wohnen wird, in sicheren Wohnungen und in stolzer Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Aber Hagel wird sein den Wald hinab, und die Stadt danieden wird niedrig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Wohl euch, die ihr saet allenthalben an den Wassern; denn da moget ihr die Fülie der Ochsen und Esel darauf gehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Wehe aber dir, du Verstorer! Meinest du, du werdest nicht verstoret werden? Und du Verachter! meinest du, man werde dich nicht verachten? Wenn du das Verstoren vollendet hast, so wirst du auch verstoret werden; wenn du des Verachtens ein Ende gemacht hast, so wird man dich wieder verachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'HERR, sei uns gnadig, denn auf dich harren wir; sei ihr Arm fruhe, dazu unser Heil zu der Zeit der Trübsal!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Lali fliehen die Volker vor dem grolien Getümmel, und die Heiden zerstreuetwerden, wenn du dich erhohest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Da wird man euch aufraffen als einen Raub, wie man die Heuschrecken aufrafft, und wie die Kafer zerscheucht werden, wenn man sie uberfallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Der HERR ist erhaben, denn er wohnet in der Hohe. Er hat Zion voll Gerichts und Gerechtigkeit gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Und wird zu deiner Zeit Glaube sein, und Herrschaft, Heil, Weisheit, Klugheit, Furcht des HERRN werden sein Schatz sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Siehe, ihre Boten schreien draulien, die Engel des Friedens weinen bitterlich (und sprechen):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Die Steige sind wuste, es gehet niemand mehr auf der Stralie. Er halt weder Treue noch Glauben; er verwirft die Stadte und achtet der Leute nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Das Land liegt klaglich und jammerlich, der Libanon stehet schandlich zerhauen, und Saron ist wie ein Gefilde, und Basan und Karmel ist ode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nun will ich mich aufmachen, spricht der HERR, nun will ich mich erheben, nun will ich hoch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Mit Stroh gehet ihr schwanger, Stoppeln gebaret ihr; Feuer wird euch mit euren Mut verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Denn die Volker werden zu Kalk verbrannt werden, wie man abgehauene Dornen mit Feuer ansteckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'So horet nun ihr, die ihr feme seid, was ich getan habe; und die ihr nahe seid, merket meine Starke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Die Sunder zu Zion sind erschrocken, Zittern ist die Heuchler ankommen (und sprechen): Wer ist unter uns, der bei einem verzehrenden Feuer wohnen moge? Wer ist unter uns, der bei der ewigen Glut wohne?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Wer in Gerechtigkeit wandelt und redet, was recht ist; wer Unrecht hasset samt dem Geiz und seine Hande abzeucht, daß er nicht Geschenke nehme; wer seine Ohren zustopft, daü er nicht Blutschulden hore, und seine Augen zuhalt, daß er nicht Arges sehe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'der wird in der Hohe wohnen, und Felsen werden seine Feste und Schutz sein. Sein Brot wird ihm gegeben, sein Wasser hat er gewüi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Deine Augen werden den Konig sehen in seiner Schone, du wirst das Land erweitert sehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'daß sich dein Herz sehr verwundern wird und sagen: Wo sind nun die Schriftgelehrten? Wo sind die Rate? Wo sind die Kanzler?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Dazu wirst du das starke Volk nicht sehen, das Volk von tiefer Sprache, die man nicht vernehmen kann, und von undeutlicher Zunge, die man nicht verstehen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Schaue, Zion, die Stadt unsers Stifts! Deine Augen werden Jerusalem sehen, eine sichere Wohnung, eine Hütte, die nicht weggeführt wird, welcher Nagel sollen nimmermehr ausgezogen, und ihrer Seile keins zerrissen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Denn der HERR wird machtig daselbst bei uns sein, und werden weite Wassergraben sein, daü daruber kein Schiff mit Rudern fahren noch Galeeren dahin schiffen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Denn der HERR ist unser Richter, der HERR ist unser Meister, der HERR ist unser Konig, der hilft uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Lalit sie ihre Stricke spannen, sie werden doch nicht halten; also werden sie auch das Fahnlein nicht auf den Mastbaum ausstecken. Dann wird viel kdstliches Raubs ausgeteilet werden, dafi auch die Lahmen rauben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Und kein Einwohner wird sagen: Ich bin schwach. Denn das Volk, so drinnen wohnet, wird Vergebung der Sünden haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Kommt herzu, ihr Heiden, und horet, ihr Volker, merket auf; die Erde hore zu, und was drinnen ist, der Weltkreis samt seinem Gewachse!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Denn der HERR ist zornig uber alle Heiden und grimmig uber all ihr Heer; er wird sie verbannen und zum Schlachten überantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Und ihre Erschlagenen werden hingeworfen werden, daß der Gestank von ihren Leichnamen aufgehen wird und die Berge mit ihrem Blut flielien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Und wird alles Heer: des Himmels verfaulen, und der Himmel wird eingewickelt werden wie ein Brief, und all sein Heer wird verwelken, wie ein Blatt verwelket am Weinstock und wie ein dürr Blatt am Feigenbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Denn mein Schwert ist trunken im Himmel; und siehe, es wird herniederfahren auf Edom und uber das verbannte Volk zur Strafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Des HERRN Schwert ist voll Bluts und dick von Fettem, vom Blut der Lammer und Bocke, von der Nieren Fett aus den Widdern; denn der HERR halt ein Schlachten zu Bozra und ein grofies Würgen im Lande Edom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Da werden die Einhorner samt ihnen herunter müssen und die Farren samt den gemasteten Ochsen. Denn ihr Land wird trunken werden von Blut, und ihre Erde dick werden von Fettem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Denn es ist der Tag der Rache des HERRN und das Jahr der Vergeltung, zu rachen Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Da werden ihre Bache zu Pech werden und ihre Erde zu Schwefel; ja, ihr Land wird zu brennendem Pech werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'das weder Tag noch Nacht verloschen wird, sondern ewiglich wird Rauch von ihr aufgehen, und wird fur und fur wuste sein, daß niemand dadurchgehen wird in Ewigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'sondern Rohrdommeln und Igel werden\'s inne haben, Nachteulen und Raben werden daselbst wohnen. Denn erwird eine Melischnur daruber ziehen, daß sie wuste werde, und ein Richtblei, daß sie ode sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'daß ihre Herren heilien müssen Herren ohne Land und alle ihre Fursten ein Ende haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Und werden Dornen wachsen in ihren Palasten, Nesseln und Disteln in ihren Schlossern; und wird eine Behausung sein der Drachen und Weide fur die Strauften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Da werden untereinander laufen Marder und Geier, und ein Feldteufel wird dem andern begegnen; der Kobold wird auch daselbst herbergen und seine Ruhe daselbst finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Der Igel wird auch daselbst nisten und legen, bruten und aushecken unter ihrem Schatten; auch werden die Weihen daselbst zusammenkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Suchet nun in dem Buch des HERRN und leset! Es wird nicht an einem derselbigen fehlen; man vermifit auch nicht dieses noch des. Denn er ist\'s, der durch meinen Mund gebeut, und sein Geist ist\'s, der es zusammenbringet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Er gibt das Los uber sie, und seine Hand teilt das Mali aus unter sie, daß sie darinnen erben ewiglich und darinnen bleiben fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Aber die Wüste und Einode wird lustig sein, und das Gefilde wird frohlich stehen und wird blühen wie die Lilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Sie wird blühen und frohlich stehen in aller Lust und Freude. Denn die Herrlichkeit des Libanon ist ihr gegeben, der Schmuck Karmels und Sarons. Sie sehen die Herrlichkeit des HERRN, den Schmuck unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Starket die müden Hande und erquicket die strauchelnden Kniee!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Saget den verzagten Herzen: Seid getrost, furchtet euch nicht! Sehet, euer Gott, der kommt zur Rache; Gott, der da vergilt, kommt und wird euch helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Alsdann werden der Blinden Augen aufgetan werden, und der Tauben Ohren werden geoffnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Alsdann werden die Lahmen locken wie ein Hirsch, und der Stummen Zunge wird Lob sagen. Denn es werden Wasser in der Wüste hin und wieder fliefien und Strome in den Gefilden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Und wo es zuvor trocken ist gewesen, sollen Teiche stehen; und wo es dürre gewesen ist, sollen Brunnquellen sein. Da zuvor die Schlangen gelegen haben, soil Heu und Rohr und Schilf stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Und es wird daselbst eine Bahn sein und ein Weg, welcher der heilige Weg heifien wird, dafi kein Unreiner darauf gehen wird; und derselbige wird fur sie sein, daß man darauf gehe, dafi auch die Toren nicht irren mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Es wird da kein Lowe sein, und wird kein reiftend Tier darauf treten, noch daselbst funden werden, sondern man wird frei sicher daselbst gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Die Erloseten des HERRN werden wiederkommen und gen Zion kommen mit Jauchzen; ewige Freude wird uber ihrem Haupte sein; Freude und Wonne werden sie ergreifen, und Schmerz und Seufzen wird weg müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Und es begab sich, im vierzehnten Jahr des Konigs Hiskia zog der Konig zu Assyrien, Sanherib, herauf wider alle festen Stadte Judas und gewann sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Und der Konig zu Assyrien sandte den Rabsake von Lachis gen Jerusalem zu dem Konige Hiskia mit grower Macht. Und er trat an die Wasserrohren des obern Teichs am Wege bei dem Acker des Farbers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Und es ging zu ihm heraus Eliakim, der Sohn Hilkias, der Hofmeister, und Sebena, der Kanzler, und Joah, der Sohn Assaphs, der Schreiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Und der Erzschenke sprach zu ihnen: Saget doch dem Hiskia: So spricht der grofie Konig, der Konig zu Assyrien: Was ist das fur ein Trotz, darauf du dich verlassest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Ich achte, du lassest dich bereden, daß du noch Rat und Macht wissest zu streiten. Auf wen verlassest du denn dich, daß du mir bist abfallig worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Verlassest du dich auf den zerbrochenen Rohrstab Agypten, welcher, so jemand sich darauf lehnet, gehet er ihm in die Hand und durchbohret sie? Also tut Pharao, der Konig zu Agypten, alien, die sich auf ihn verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Willst du aber mir sagen: Wir verlassen uns auf den HERRN, unsern Gott? Ist\'s denn nicht der, welches Hohen und Altare der Hiskia hat abgetan und zu Juda und Jerusalem gesagt: Vor diesem Altar sollt ihr anbeten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Wohlan, so nimm\'s an mit meinem Herm, dem Konige zu Assyrien! Ich will dir zweitausend Rosse geben; laft sehen, ob du bei dir konnest ausrichten, die darauf reiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Wie willst du denn bleiben vor einem Hauptmann, der geringsten Diener einem meines Herm? Und du verlassest dich auf Agypten urn der Wagen und Reiter willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Dazu meinest du, daß ich ohne den HERRN bin heraufgezogen in dies Land, dasselbige zu verderben? Ja, der HERR sprach zu mir: Zeuch hinauf in dies Land und verderbe es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Aber Eliakim und Sebena und Joah sprachen zum Erzschenken: Lieber, rede mit deinen Knechten auf syrisch, denn wir verstehen\'s wohl; und rede nicht auf judisch mit uns vor den Ohren des Volks, das auf der Mauer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Da sprach der Erzschenke: Meinest du, daß mein Herr mich zu deinem Herm Oder zu dir gesandt habe, solche Worte zu reden, und nicht vielmehr zu den Mannern, die auf der Mauer sitzen, daß sie samt euch ihren eigenen Mist fressen und ihren Ham saufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Und der Erzschenke stund und rief laut auf judisch und sprach: Horet die Worte des grolien Konigs, des Konigs zu Assyrien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So spricht der Konig: Lafit euch Hiskia nicht betrugen; denn er kann euch nicht erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Und lalit euch Hiskia nicht vertrosten auf den HERRN, daß ersagt: Der HERR wird uns erretten, und diese Stadt wird nicht in die Hand des Konigs zu Assyrien gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Gehorchet Hiskia nicht! Denn so spricht der Konig zu Assyrien: T ut mir zu Danke und gehet zu mir heraus, so sollt ihr ein jeglicher von seinem Weinstock und von seinem Feigenbaum essen und aus seinem Brunnen trinken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'bis dafi ich komme und hole euch in ein Land, wie euer Land ist, ein Land, da Korn und Most innen ist, ein Land, da Brot und Weinberge innen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Lalit euch Hiskia nicht bereden, daß ersagt: Der HERR wird uns erlosen. Haben auch der Heiden Gotter ein jeglicher sein Land errettet von der Hand des Konigs zu Assyrien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Wo sind die Gotter zu Hamath und Arpad? Wo sind die Gotter zu Sepharvaim? Haben sie auch Samaria errettet von meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Welcher unter alien Gottern dieser Lande hat sein Land errettet von meiner Hand, daß der HERR sollte Jerusalem erretten von meiner Hand?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Sie schwiegen aber stille und antworteten ihm nichts; denn der Konig hatte geboten und gesagt: Antwortet ihm nichts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Da kamen Eliakim, der Sohn Hilkias, der Hofmeister, und Sebena, der Kanzler, und Joah, der Sohn Assaphs, der Schreiber, mit zerrissenen Kleidern und zeigten ihm an die Worte des Erzschenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Da aber der Konig Hiskia das horete, zerrili er seine Kleider und hullete einen Sack urn sich und ging in das Hausdes HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Und sandte Eliakim, den Hofmeister; und Sebena, den Kanzler, samt den altesten Priestern, mit Sacken umhullet, zu dem Propheten Jesaja, dem Sohn Amoz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'daß sie zu ihm sprachen: So spricht Hiskia: Das ist ein Tag des Trubsals, Scheltens und Lasterns, und gehet gleich, als wenn die Kinder bis an die Geburt kommen sind, und ist keine Kraft da zu gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Dali doch der HERR, dein Gott, horen wollte die Worte des Erzschenken, welchen sein Herr, der Konig zu Assyrien, gesandt hat, zu lastern den lebendigen Gott und zu schelten mit solchen Worten, wie der HERR, dein Gott, gehort hat! Und du wollest dein Gebet erheben fur die Ubrigen, die noch vorhanden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Und die Knechte des Konigs Hiskia kamen zu Jesaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Jesaja aber sprach zu ihnen: So saget eurem Herrn: Der HERR spricht also: Furchte dich nicht vor den Worten, die du gehort hast, mit welchen mich die Knaben des Konigs zu Assyrien geschmahet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Siehe, ich will ihm einen andern Mut machen, und soil etwas horen, daß erwieder heimziehe in sein Land; und will ihn durchs Schwert fallen in seinem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Da aber der Erzschenke wiederkam, fand er den Konig zu Assyrien streiten wider Libna; denn er hatte gehort, daß er von Lachis gezogen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Denn es kam ein Gerucht von Thirhaka, der Mohren Konige, sagend: Er ist ausgezogen, wider dich zu streiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Da er nun solches horete, sandte er Boten zu Hiskia und lieli ihm sagen: Saget Hiskia, dem Konige Judas, also: Lali dich deinen Gott nicht betrugen, auf den du dich verlassest und sprichst: Jerusalem wird nicht in die Hand des Konigs zu Assyrien gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Siehe, du hast gehort, was die Konige zu Assyrien getan haben alien Landen und sie verbannet; und du solltest errettet werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Haben auch die Gotter der Heiden die Lander errettet, welche meine Vater verderbet haben, als Gosan, Haran, Rezeph und die Kinder Eden zu Thelassar?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Wo ist der Konig zu Hamath und der Konig zu Arpad und der Konig der Stadt Sepharvaim, Hena und Iwa?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Und da Hiskia den Brief von den Boten empfangen und gelesen hatte, ging er hinauf in das Haus des HERRN und breitete ihn aus vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Und Hiskia betete zum HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'HERR Zebaoth, du Gott Israels, derdu uber den Cherubim sitzest, du bist alleine Gott uber alle Konigreiche auf Erden; du hast Himmel und Erde gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'HERR, neige deine Ohren und hore doch! HERR, tue deine Augen auf und siehe doch! Hore doch alle die Worte Sanheribs, die er gesandt hat, zu schmahen den lebendigen Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Wahr ist\'s, HERR, die Konige zu Assyrien haben wüste gemacht alle Konigreiche samt ihren Landen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'und haben ihre Gotter ins Feuer geworfen; denn sie waren nicht Gotter, sondern Menschenhande Werk, Holz und Stein. Die sind umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Nun aber, HERR, unser Gott, hilf uns von seiner Hand, auf daß alle Konigreiche, auf Erden erfahren, daß du HERR seiest alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Da sandte Jesaja, der Sohn Amoz, zu Hiskia und lieli ihm sagen: So spricht der HERR, der Gott Israels: Dali du mich gebeten hast des Konigs Sanherib halben zu Assyrien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'so ist das, das der HERR von ihm redet: Die Jungfrau Tochter Zion verachtet dich und spottet dein, und die Tochter Jerusalem schüttelt das Haupt dir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Wen hast du geschmahet und gelastert? Liber wen hast du die Stimme erhoben? und hebest deine Augen empor wider den Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Durch deine Knechte hast du den HERRN geschandet und sprichst: Ich bin durch die Menge meiner Wagen herauf gezogen auf die Hohe der Berge an den Seiten Libanons und habe seine hohen Zedern abgehauen samtseinen auserwahlten Tannen und bin durch die Hohe bis ans Ende kommen, an diesen Wald auf dem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ich habe gegraben und getrunken die Wasser und habe mit meinen Fußsohlen ausgetrocknet alle verwahrten Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hast du aber nicht gehort, daß ich vorzeiten also getan habe und vor alters so gehandelt und tue jetzt auch also, dafi feste Stadte zerstoret werden zu Steinhaufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'und ihre Einwohner geschwacht und zaghaft werden und mit Schanden bestehen und werden zu Feldgras und zu grunem Kraut, als Heu auf den Dachern, welches dorret, ehe denn es reif wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Ich kenne aber deine Wohnung, deinen Auszug und Einzug und dein Toben wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Weil du denn wider mich tobest und dein Stolz herauf vor meine Ohren kommen ist, will ich dir einen Ring an die Nase legen und ein Gebiß in dein Maul und will dich des Weges wieder heimfuhren, des du kommen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Das sei dir aber das Zeichen: Iß dies Jahr, was zertreten ist, das, andere Jahr, was selbst wachset; des dritten Jahrs saet und erntet, pflanzet Weinberge und esset ihre Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Denn die Erretteten vom Hause Juda und die überbleiben werden noch wiederum unter sich wurzeln und fiber sich Frucht tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Denn von Jerusalem werden noch ausgehen, die uberblieben sind, und die Erretteten von dem Berge Zion. Solches wird tun der Eifer des HERRN Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Darum spricht der HERR also vom Konige zu Assyrien: Er soil nicht kommen in diese Stadt und soil auch keinen Pfeil daselbst hinschießen und kein Schild davor kommen und soil keinen Wall urn sie schutten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'sondern des Weges, des er kommen ist, soli er wiederkehren, daß er in diese Stadt nicht komme, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Denn ich will diese Stadt schutzen, daß ich ihr aushelfe urn, meinetwillen und urn meines Dieners Davids willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Dafuhraus der Engel des HERRN und schlug im assyrischen Lager hundertundfunfundachtzigtausend Mann. Und da sie sich des Morgens fruh aufmachten, siehe, da lag es alles eitel tote Leichname.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Und der Konig zu Assyrien, Sanherib, brach auf, zog weg und kehrete wieder heim und blieb zu Ninive.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Es begab sich auch, da er anbetete im Hause Nisrochs, seines Gottes, schlugen ihn seine Sohne Adramelech und Sarezer mit dem Schwert; und sie flohen ins Land Ararat. Und sein Sohn Assar-Haddon ward Konig an seiner Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Zu der Zeit ward Hiskia todkrank. Und der Prophet Jesaja, der Sohn Amoz, kam zu ihm und sprach zu ihm: So spricht der HERR: Bestelle dein Haus; denn du wirst sterben und nicht lebendig bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Da wendete Hiskia sein Angesicht zur Wand und betete zum HERRN');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'und sprach: Gedenke doch, HERR, wie ich vor dir gewandelt habe in der Wahrheit mit vollkommenem Herzen und habe getan, was dir gefallen hat. Und Hiskia weinete sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Da geschah das Wort des HERRN zu Jesaja und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Gehe hin und sage Hiskia: So spricht der HERR, der Gott deines Vaters David: Ich habe dein Gebet gehort und deine Tranen gesehen; siehe, ich will deinen Tagen noch funfzehn Jahre zulegen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'und will dich samt dieser Stadt erretten von der Hand des Konigs zu Assyrien; denn ich will diese Stadt wohl verteidigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Und habe dir das zum Zeichen von dem HERRN, daß der HERR solches tun wird, was er geredet hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Siehe, ich will den Schatten am Sonnenzeiger Ahas zehn Linien zuruckziehen, fiber welche er gelaufen ist, daß die Sonne zehn Linien zurücklaufen soil am Zeiger, fiber welche sie gelaufen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Dies ist die Schrift Hiskias, des Konigs Judas, da er krank gewesen und von der Krankheit gesund worden war:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Ich sprach: Nun muß ich zu der Hollen Pforte fahren, da meine Zeit aus war, da ich gedachte noch langerzu leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Ich sprach: Nun muß ich nicht mehr sehen den HERRN, ja den HERRN im Lande der Lebendigen; nun muß ich nicht mehr schauen die Menschen bei denen, die ihre Zeit leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Meine Zeit ist dahin und von mir aufgeraumet wie eines Hirten Hutte; und reiße mein Leben ab wie ein Weber. Er sauget mich dfirre aus. Du machst es mit mir ein Ende, den Tag vor Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Ich dachte: Mochte ich bis morgen leben! Aber er zerbrach mir alle meine Gebeine wie ein Lowe; denn du machst es mit mir aus, den Tag vor Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Ich winselte wie ein Kranich und wie eine Schwalbe und girrete wie eine Taube; meine Augen wollten mir brechen: HERR, ich leide Not; lindre mir\'s!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, '0 wie will ich noch reden, daß er mirzugesagt hat und tut es auch! Ich werde mich scheuen alle meine Lebtage vor solcher Betrubnis meiner Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'HERR, davon lebet man, und das Leben meines Geistes stehet gar in demselbigen; denn du liefiest mich entschlafen und machtest mich leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Siehe, um Trost war mir sehr bange. Du aber hast dich meiner Seele herzlich angenommen, daß sie nicht verdurbe; denn du wirfst alle meine Sünde hinter dich zuruck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Denn die Holle lobet dich nicht, so rühmet dich der Tod nicht, und die in die Grube fahren, warten nicht auf deine Wahrheit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'sondern allein die da leben, loben dich, wie ich jetzt tue. Der Vater wird den Kindern deine Wahrheit kundtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'HERR, hilf mir, so wollen wir meine Lieder singen, solange wir leben, in dem Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Und Jesaja hieli, man sollte ein Pflaster von Feigen nehmen und auf seine Druse legen, daß er gesund würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Hiskia aber sprach: Welch ein Zeichen ist das, daß ich hinauf zum Hause des HERRN soil gehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Zu der Zeit sandte Merodach-Baladan, der Sohn Baladans, Konig zu Babel, Briefe und Geschenke zu Hiskia; denn er hatte gehoret, daß er krank und wieder stark worden ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Des freuete sich Hiskia und zeigte ihnen das Schatzhaus, Silber und Gold und Spezerei, kostliche Salben und alle seine Zeughauser und alien Schatz, den er hatte. Nichts war, das ihnen Hiskia nicht zeigte in seinem Hause und in seiner Herrschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Da kam der Prophet Jesaja zum Konige Hiskia und sprach zu ihm: Was sagen diese Manner und von wannen kommen sie zu dir? Hiskia sprach: Sie kommen von feme zu mir, namlich von Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Er aber sprach: Was haben sie in deinem Hause gesehen? Hiskia sprach: Alles, was in meinem Hause ist, haben sie gesehen; und ist nichts, das ich ihnen nicht hatte gezeiget in meinen Schatzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Und Jesaja sprach zu Hiskia: Hore das Wort des HERRN Zebaoth!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Siehe, es kommt die Zeit, daß alles, was in deinem Hause ist und was deine Vater gesammelt haben bis auf diesen Tag, wird gen Babel gebracht werden, daü nichts bleiben wird, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Dazu werden sie deine Kinder, so von dir kommen werden und du zeugen wirst, nehmen, und müssen Kammerer sein im Hofe des Konigs zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Und Hiskia sprach zu Jesaja: Das Wort des HERRN ist gut, das du sagest. Und sprach: Es sei nur Friede und Treue, weil ich lebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Trostet, trostet mein Volk! spricht euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Redet mit Jerusalem freundlich und prediget ihr, daß ihre Ritterschaft ein Ende hat, denn ihre Missetat ist vergeben; denn sie hat Zwiefaltiges empfangen von der Hand des HERRN um alle ihre Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Es ist eine Stimme eines Predigers in der Wüste: Bereitet dem HERRN den Weg; machet auf dem Gefilde eine ebene Bahn unserm Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Alle Taler sollen erhohet werden, und alle Berge und Huge! sollen geniedriget werden, und was ungleich ist, soil eben, und was hockericht ist, soil schlicht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Denn die Herrlichkeit des HERRN soil offenbaret werden; und alles Fleisch miteinander wird sehen, daß des HERRN Mund redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Es spricht eine Stimme: Predige! Und er sprach: Was soil ich predigen? Alles Fleisch ist Heu, und alle seine Gute ist wie eine Blume auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Das Heu verdorret, die Blume verwelket; denn des HERRN Geist blaset drein. Ja, das Volk ist das Heu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Das Heu verdorret, die Blume verwelket; aber das Wort unsers Gottes bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Zion, du Predigerin, steig auf einen hohen Berg! Jerusalem, du Predigerin, hebe deine Stimme auf mit Macht, heb auf und furchte dich nicht; sage den Stadten Judas: Siehe, da ist euer Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Denn siehe, der Herr HERR kommt gewaltiglich; und sein Arm wird herrschen. Siehe, sein Lohn ist bei ihm, und seine Vergeltung ist vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Er wird seine Herde weiden wie ein Hirte; er wird die Lammer in seine Arme sammeln und in seinem Busen tragen und die Schafmutter fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Wer misset die Wasser mit der Faust und fasset den Himmel mit der Spanne und begreift die Erde miteinem Dreiling und wieget die Berge mit einem Gewicht und die Hugel mit einer Waage?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Wer unterrichtet den Geist des HERRN, und welcher Ratgeber unterweiset ihn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Wen fragt er um Rat, der ihm Verstand gebe und lehre ihn den Weg des Rechts und lehre ihn die Erkenntnis und unterweise ihn den Weg des Verstandes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Siehe, die Heiden sind geachtet wie ein Tropfen, so im Eimer bleibt, und wie ein Scherflein, so in der Wage bleibet. Siehe, die Inseln sind wie ein Staublein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Der Libanon ware zu geringe zum Feuer und seine Tiere zu geringe zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Alle Heiden sind vor ihm nichts und wie ein Nichtiges und Eitles geachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Wem wollt ihr denn Gott nachbilden, Oder was fur ein Gleichnis wollt ihr ihm zurichten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Der Meister giefit wohl ein Bild, und der Goldschmied uberguldet es und macht silberne Ketten dran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Desgleichen wer eine arme Hebe vermag, der wahlet ein Holz, das nicht fault, und sucht einen klugen Meister dazu, der ein Bild fertige, das bestandig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Wisset ihr nicht? Horet ihr nicht? Ist\'s euch nicht vormals verkundiget? Habt ihr\'s nicht verstanden von Anbeginn der Erde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Er sitzt uber dem Kreis der Erde; und die darauf wohnen, sind wie Heuschrecken. Der den Himmel ausdehnet wie ein dunn Fell und breitet sie aus wie eine Hutte, da man innen wohnet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'der die Fursten zunichte macht und die Richter auf Erden eitel macht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'als hatte ihr Stamm weder Pflanzen noch Samen noch Wurzel in der Erde, daß sie, wo ein Wind unter sie wehet, verdorren, und sie ein Windwirbel wie Stoppeln wegfuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Wem wollt ihr denn mich nachbilden, dem ich gleich sei? spricht der Heilige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Hebet eure Augen in die Hohe und sehet! Wer hat solche Dinge geschaffen und fuhret ihr Heer bei der Zahl heraus? Der sie alle mit Namen rufet; sein Vermogen und starke Kraft ist so groß, daß nicht an einem fehlen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Warum sprichst du denn, Jakob, und du, Israel, sagest: Mein Weg ist dem HERRN verborgen, und mein Recht gehet vor meinem Gott uber?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Weißt du nicht? Hast du nicht gehort? Der HERR, der ewige Gott, der die Enden der Erde geschaffen hat, wird nicht mude noch matt; sein Verstand ist unausforschlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Er gibt dem Müden Kraft und Starke genug dem Unvermogenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Die Knaben werden mude und matt, und die Junglinge fallen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'aber die auf den HERRN harren, kriegen neue Kraft, daß sie auffahren mit Flugeln wie Adler, daß sie laufen und nicht matt werden, daß sie wandeln und nicht mude werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Laß die Inseln vor mir schweigen und die Volker sich starken! Laß sie herzutreten und nun reden; laßt uns miteinander rechten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Wer hat den Gerechten vom Aufgang erweckt? Wer rief ihm, daß er ging? Wer gab die Heiden und Konige vor ihm, daß er ihrer machtig ward, und gab sie seinem Schwert wie Staub und seinem Bogen wie zerstreuete Stoppeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'daß er ihnen nachjagete und zog durch mit Frieden und ward des Weges noch nie mude?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Wer tut es und macht es und ruft alle Menschen nacheinander von Anfang her? Ich bin\'s, der HERR, beide der Erste und der Letzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Da das die Inseln sahen, furchteten sie sich, und die Enden der Erde erschraken; sie naheten und kamen herzu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Einer half dem andern und sprach zu seinem Nachsten: Sei getrost!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Der Zimmermann nahm den Goldschmied zu sich und machten mit dem Hammer das Blech glatt auf dem Amboß und sprachen: Das wird fein stehen! Und hefteten\'s mit Nageln, daß es nicht sollte wackeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Du aber, Israel, mein Knecht, Jakob, den ich erwahlet habe, du Same Abrahams, meines Geliebten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'der ich dich gestarkt habe von der Welt Ende her und habe dich berufen von ihren Gewaltigen und sprach zu dir: Du sollst mein Knecht sein, denn ich erwahle dich und verwerfe dich nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'furchte dich nicht, ich bin mit dir; weiche nicht, denn ich bin dein Gott! Ich starke dich, ich helfe dir auch, ich erhalte dich durch die rechte Hand meiner Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Siehe, sie sollen zu Spott und zuschanden werden, alle, die dir gram sind; sie sollen werden als nichts; und die Leute, so mit dir hadern, sollen umkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'daß du nach ihnen fragen mochtest und wirst sie nicht finden. Die Leute, so mit dir zanken, sollen werden als nichts, und die Leute, so wider dich streiten, sollen ein Ende haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Denn ich bin der HERR, dein Gott, der deine rechte Hand starket und zu dir spricht: Furchte dich nicht, ich helfe dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'So furchte dich nicht, du Wurmlein Jakob, ihr armer Haufe Israel! Ich helfe dir, spricht der HERR, und dein Erloser, der Heilige in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Siehe, ich habe dich zum scharfen neuen Dreschwagen gemacht, der Zacken hat, daß du sollst Berge zerdreschen und zermalmen und die Hugel wie Spreu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Du sollst sie zerstreuen, daß sie der Wind wegfuhre und der Wirbel verwebe. Du aber wirst frohlich sein am HERRN und wirst dich rühmen des Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Die Elenden und Armen suchen Wasser, und ist nichts da; ihre Zunge verdorret vor Durst. Aber ich, der HERR, will sie erhoren; ich, der Gott Israels, will sie nicht verlassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'sondern ich will Wasserflusse auf den Hohen offnen und Brunnen mitten auf den Feldern ich will die Wuste zu Wasserseen machen und das durre Land zu Wasserquellen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'ich will in der Wuste geben Zedern, Fohren, Myrten und Kiefern; ich will auf dem Gefilde geben Tannen, Buchen und Buchsbaum miteinander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'auf daß man sehe und erkenne und merke und verstehe zugleich, daß des HERRN Hand habe solches getan, und der Heilige in Israel habe solches geschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'So lasset eure Sache herkommen, spricht der HERR; bringet her, worauf ihr stehet, spricht der Konig in Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Lasset sie herzutreten und uns verkundigen, was ktinftig ist! Verkundiget uns und weissaget etwas zuvor; lasset uns mit unserm Herzen darauf achten und merken, wie es hernach gehen soil; Oder lasset uns doch horen, was zukünftig ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Verkundiget uns, was hernach kommen wird, so wollen wir merken, daß ihr Gotter seid. Trotz, tut Gutes Oder Schaden, so wollen wir davon reden und miteinanderschauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Siehe, ihr seid aus nichts, und euer T un ist auch aus nichts, und euch wahlen ist ein Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Ich aber erwecke einen von Mitternacht, und kommt vom Aufgang der Sonne. Er wird ihnen meinen Namen predigen und wird über die Gewaltigen gehen wie uber Leimen und wird den Kot treten wie ein Topfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Wer kann etwas verkündigen von Anfang? so wollen wir\'s vernehmen; Oder weissagen zuvor? so wollen wir sagen: Du redest recht. Aber da ist kein Verkundiger, keiner, der etwas horen ließe, keiner, der von euch ein Wort horen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Ich bin der Erste, der zu Zion sagt: Siehe, da ist\'s! und ich gebe Jerusalem Prediger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Dort aber schaue ich, aber da ist niemand; und sehe unter sie, aber da ist kein Ratgeber; ich frage sie, aber da antworten sie nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Siehe, es ist alles eitel Mühe und nichts mit ihrem Tun; ihre Gotzen sind Wind und eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Siehe, das ist mein Knecht, ich erhalte ihn; und mein Auserwahlter, an welchem meine Seele Wohlgefallen hat. Ich habe ihm meinen Geist gegeben; er wird das Recht unter die Heiden bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Er wird nicht schreien noch rufen, und seine Stimme wird man nicht horen auf den Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Das zerstoßene Rohr wird er nicht zerbrechen und den glimmenden Docht wird er nicht ausloschen. Erwird das Recht wahrhaftiglich halten lehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Er wird nicht murrisch noch greulich sein, auf daß er auf Erden das Recht anrichte; und die Inseln werden auf sein Gesetz warten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'So spricht Gott, der HERR, der die Himmel schaffet und ausbreitet, der die Erde machet und ihr Gewachs, der dem Volk, so darauf ist, den Odem gibt und den Geist denen, die darauf gehen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ich, der HERR, habe dich gerufen mit Gerechtigkeit und habe dich bei deiner Hand gefasset und habe dich behutet und habe dich zum Bund unter das Volk gegeben, zum Licht der Heiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'daß du sollst offnen die Augen der Blinden und die Gefangenen aus dem Gefangnis fuhren, und die da sitzen in Finsternis, aus dem Kerker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ich, der HERR, das ist mein Name, und will, meine Ehre keinem andern geben noch meinen Ruhm den Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Siehe, was kommen soil, verkundige ich zuvor und verkundige Neues; ehe denn es aufgehet, lasse ich\'s euch horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Singet dem HERRN ein neues Lied! Sein Ruhm ist an der Welt Ende; die im Meer fahren, und was drinnen ist, die Inseln, und die drinnen wohnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Rufet laut, ihr Wüsten und die Stadte drinnen samt den Dorfern, da Kedar wohnet. Es jauchzen, die in Felsen wohnen, und rufen von den Hohen der Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Lasset sie dem HERRN die Ehre geben und seinen Ruhm in den Inseln verkündigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Der HERR wird ausziehen wie ein Riese; er wird den Eifer aufwecken wie ein Kriegsmann; erwird jauchzen und tonen; erwird seinen Feinden obliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Ich schweige wohl eine Zeitlang und bin still und enthalte mich. Nun aber will ich, wie eine Gebarerin, schreien; ich will sie verwüsten und alle verschlingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Ich will Berge und Hügel verwüsten und all ihr Gras verdorren; und will die Wasserstrome zu Inseln machen und die Seen austrocknen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Aber die Bünden will ich auf dem Wege leiten, den sie nicht wissen; ich will sie fuhren auf den Steigen, die sie nicht kennen; ich will die Finsternis vor ihnen her zum Licht machen und das Hockerichte zur Ebene. Solches will ich ihnen tun und sie nicht verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Aber die sich auf Gotzen verlassen und sprechen zum gegossenen Bilde: Ihr seid unsere Gotter! die sollen zurückkehren und zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Horet, ihr Tauben und schauet her, ihr Blinden, daß ihr sehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Wer ist so blind als mein Knecht, und wer ist so taub wie mein Bote, den ich sende? Wer ist so blind als der Vollkommene und so blind als der Knecht des HERRN?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Man predigt wohl viel, aber sie halten\'s nicht; man sagt ihnen genug, aber sie wollen\'s nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Noch will ihnen der HERR wohl urn seiner Gerechtigkeit willen, daß er das Gesetz herrlich und groli mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Es ist ein beraubt und geplundert Volk; sie sind allzumal verstrickt in Hohlen und versteckt in den Kerkern; sie sind zum Raub worden, und ist kein Erretter da, geplundert, und ist niemand, der da sage: Gib sie wieder her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Wer ist unter euch, der solches zu Ohren nehme, der aufmerke und hore, das hernach kommt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Wer hat Jakob ubergeben zu plündern, und Israel den Raubern? Hat\'s nicht der HERR getan, an dem wir gesundiget haben? Und sie wollten auf seinen Wegen nicht wandeln und gehorchten seinem Gesetz nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Darum hat er über sie ausgeschuttet den Grimm seines Zorns und eine Kriegsmacht und hat sie umher angezündet aber sie merken\'s nicht; und hat sie angesteckt, aber sie nehmen\'s nicht zu Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Und nun spricht der HERR, der dich geschaffen hat, Jakob, und dich gemacht hat, Israel: Fürchte dich nicht, denn ich habe dich erloset; ich habe dich bei deinem Namen gerufen; du bist mein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Denn so du durch Wasser gehest, will ich bei dir sein, dad dich die Strome nicht sollen ersaufen, und so du ins Feuer gehest, sollst du nicht brennen, und die Flamme soil dich nicht anzunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Denn ich bin der HERR, dein Gott, der Heilige in Israel, dein Heiland. Ich habe Agypten, Mohren und Seba an deiner Statt zur Versohnung gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Weil du so wert bist vor meinen Augen geachtet, mudt du auch herrlich sein, und ich habe dich lieb; darum gebe ich Menschen an deiner Statt und Volker fur deine Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'So fürchte dich nun nicht, denn ich bin bei dir. Ich will vom Morgen deinen Samen bringen und will dich vom Abend sammeln;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'und will sagen gegen Mitternacht: Gib her! und gegen Mittag: Wehre nicht! Bringe meine Sohne von feme her und meine Tochter von der Welt Ende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'alle, die mit meinem Namen genannt sind, namlich die ich geschaffen habe zu meiner Herrlichkeit und sie zubereitet und gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'La(3> hervortreten das blinde Volk, welches doch Augen hat, und die Tauben, die doch Ohren haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Lafit alle Heiden zusammenkommen zuhaufe und sich die Volker versammeln. Welcher ist unter ihnen, der solches verkundigen moge und uns horen lasse vorhin, was geschehen soil? Ladt sie ihre Zeugen darstellen und beweisen, so wird man\'s horen und sagen: Es ist die Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ihr aber seid meine Zeugen, spricht der HERR, und mein Knecht, den ich erwahlet habe, auf dad ihr wisset und mirglaubet und verstehet, dafi ich\'s bin. Vor mir ist kein Gott gemacht, so wird auch nach mir keiner sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ich, ich bin der HERR, und ist auder mir kein Heiland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ich hab\'s verkundiget und hab auch geholfen und hab\'s euch sagen lassen; und ist kein fremder (Gott) unter euch. Ihr seid meine Zeugen, spricht der HERR; so bin ich Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Auch bin ich, ehe denn nie kein Tag war; und ist niemand, der aus meiner Hand erretten kann. Ich wirke; wer will\'s abwenden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So spricht der HERR, euer Erloser, der Heilige in Israel: Urn euretwillen habe ich gen Babel geschickt und habe die Riegel alle heruntergestoden und die klagenden Chaldaer in die Schiffe gejagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ich bin der HERR, euer Heiliger, der ich Israel geschaffen habe, euer Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So spricht der HERR, der im Meer Weg und in starken Wassern Bahn macht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'der herausbringt Wagen und Rod, Heer und Macht, dad sie auf einem Haufen daßegen und nicht aufstehen, dad sie verloschen, wie ein Docht verlischt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Gedenket nicht an das Alte und achtet nicht auf das Vorige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Denn siehe, ich will ein Neues machen; jetzt soil es aufwachsen; dad ihr erfahren werdet, dad ich Weg in der Wuste mache und Wasserstrome in der Einode,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'dad mich das Tier auf dem Felde preise, die Drachen und Strauden. Denn ich will Wasser in der Wuste und Strome in der Einode geben zu tranken mein Volk; meine Auserwahlten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Dies Volk habe ich mir zugerichtet, es soil meinen Ruhm erzahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Nicht dad du mich flattest gerufen, Jakob, Oder dad du urn mich gearbeitet flattest, Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Mir zwar hast du nicht gebracht Schafe deines Brandopfers noch mich geehret mit deinen Opfern; mich hat deines Dienstes nicht gelüstet im Speisopfer, habe auch nicht Lust an deiner Arbeit im Weihrauch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'mir hast du nicht urn Geld Kalmus gekauft; mich hast du mit dem Fetten deiner Opfer nicht gefüllet. Ja, mir hast du Arbeit gemacht in deinen Sünden und hast mir Muhe gemacht in deinen Missetaten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ich, ich tilge deine Ubertretung urn meinetwillen und gedenke deiner Sünden nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Erinnere mich, lad uns miteinander rechten; sage an, wie du gerecht willst sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Deine Voreltern haben gesundiget, und deine Lehrer haben wider mich midgehandelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Darum habe ich die Fursten des Heiligtums entheiliget und habe Jakob zum Bann gemacht und Israel zum Hohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'So hore nun, mein Knecht Jakob, und Israel, den ich erwahlet habe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So spricht der HERR, der dich gemacht und zubereitet hat und der dir beistehet von Mutterleibe an: Fürchte dich nicht, mein Knecht Jakob, und du Frommer, den ich erwahlet habe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Denn ich will Wasser gieden auf die Durstige und Strome auf die Dürre; ich will meinen Geist auf deinen Samen gieden und meinen Segen auf deine Nachkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'dad sie wachsen soilen wie Gras, wie die Weiden an den Wasserbachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Dieserwird sagen: Ich bin des HERRN, und jener wird genannt werden mit dem Namen Jakob; und dieser wird sich mit seiner Hand dem HERRN zuschreiben und wird mit dem Namen Israel genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So spricht der HERR, der Konig Israels; und sein Erloser, der HERR Zebaoth: Ich bin der Erste und ich bin der Letzte, und auder mir ist kein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Und wer ist mir gleich, der da rufe und verkundige und mir\'s zurichte, der ich von der Welt her die Volker setze? Lad sie ihnen die Zeichen, und was kommen soil, verkundigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Furchtet euch nicht und erschrecket nicht! Habe ich\'s nicht dazumal dich horen lassen und verkundiget? Denn ihr seid meine Zeugen. 1st auch ein Gott aulier mir? Es ist kein Hort, ich weili ja keinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die Gotzenmacher sind allzumal eitel, und ihr Kostliches ist kein, nutze. Sie sind ihre Zeugen und sehen nichts, merken auch nichts; darum mussen sie zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Wer sind sie, die einen Gott machen und Gotzen gieüen, der kein nutze ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Siehe, alle ihre Genossen werden zuschanden; denn es sind Meister aus Menschen. Wenn sie gleich alle zusammentreten, mussen sie dennoch sich furchten und zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Es schmiedet einer das Eisen in der Zange, arbeitet in der Glut und bereitet es mit Hammern und arbeitet daran mit ganzer Kraft seines Arms, leidet auch Hunger, bis er nimmer kann, trinket auch nicht Wasser, bis er matt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Der andere zimmert Holz und misset es mit der Schnur und zeichnet es mit Rotelstein und behauet es und zirkelt es ab und macht es wie ein Mannsbild, wie einen schonen Menschen, der im Hause wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Er gehet frisch daran unter den Baumen im Walde, daß er Zedern abhaue und nehme Buchen und Eichen, ja, eine Zeder, die gepflanzet und die vom Regen erwachsen ist');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'und die den Leuten Feuerwerk gibt, davon man nimmt, daß man sich dabei warme, und die man anzundet und Brot dabei backet. Daselbst macht er einen Gott von und betet es an; er macht einen Gotzen daraus und knieet davor nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Die Halfte verbrennet er im Feuer und uber der andern Halfte isset er Fleisch; er brat einen Braten und sattigt sich, warmet sich auch und spricht: Hoja! Ich bin warm worden; ich sehe meine Lust am Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Aber das ubrige macht er zum Gott, dafi es sein Gotze sei, davor er knieet und niederfallet und betet und spricht: Errette mich; denn du bist mein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Sie wissen nichts und verstehen nichts; denn sie sind verblendet, dafi ihre Augen nicht sehen und ihre Herzen nicht merken konnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'und gehen nicht in ihr Herz; keine Vernunft noch Witz ist da, daß sie doch dachten: Ich habe die Halfte mit Feuer verbrannt und habe auf den Kohlen Brot gebacken und Fleisch gebraten und gegessen und sollte das ubrige zum Greuel machen und sollte knieen vor einem Klotz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Es gibt Asche und tauscht das Herz, das sich zu ihm neiget, und kann seine Seele nicht erretten. Noch denket er nicht: Ist das auch Trugerei, das meine rechte Hand treibt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Daran gedenke, Jakob und Israel, denn du bist mein Knecht. Ich habe dich zubereitet, daß du mein Knecht seiest; Israel, vergili mein nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Ich Vertilge deine Missetat wie eine Wolke und deine Sunde wie den Nebel. Kehre dich zu mir; denn ich erlose dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Jauchzet, ihr Himmel, denn der HERR hat\'s getan; rufe, du Erde, herunter; ihr Berge, frohlocket mit Jauchzen; der Wald und alle Baume drinnen; denn der HERR hat Jakob erloset und ist in Israel herrlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So spricht der HERR, dein Erloser, der dich von Mutterleibe hat zubereitet: Ich bin der HERR, der alles tut, der den Himmel ausbreitete ailein und die Erde weit machte ohne Gehilfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'der die Zeichen der Wahrsager zunichte und die Weissager toll macht, der die Weisen zurückkehret und ihre Kunst zur Torheit macht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'bestatiget aber das Wort seines Knechts und den Rat seiner Boten vollfuhret, der zu Jerusalem spricht: Sei bewohnet! und zu den Stadten Judas: Seid gebauet! und der ich ihre Verwustung aufrichte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'der ich spreche zu der Tiefe: Versiege! und zu den Stromen: Vertrocknet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Der ich spreche zu Kores: Der ist mein Hirte und soil alien meinen Willen vollenden, daß man sage zu Jerusalem: Sei gebauet! und zum Tempel: Sei gegrundet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So spricht der HERR zu seinem Gesalbten, dem Kores, den ich bei seiner rechten Hand ergreife, dafi ich die Heiden vor ihm unterwerfe und den Konigen das Schwert abgürte, auf dafi vor ihm die Turen geoffnet werden und die Tore nicht verschlossen bleiben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ich will vor dir hergehen und die Hbcker eben machen; ich will die ehernen Turen zerschlagen und die eisernen Riegel zerbrechen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'und will dir geben die heimlichen Schatze und die verborgenen Kleinode, auf daß du erkennest, dafi ich, der HERR, der Gott Israels, dich bei deinem Namen genannt habe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'urn Jakobs, meines Knechts, willen und urn Israels, meines Auserwahlten, willen. Ja, ich rief dich bei deinem Namen und nannte dich, da du mich noch nicht kanntest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ich bin der HERR und sonst keiner mehr; kein Gott ist ohne ich. Ich habe dich gerustet, da du mich noch nicht kanntest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'auf daß man erfahre beide von der Sonnen Aufgang und der Sonnen Niedergang, daß aulier mir nichts sei. Ich bin der HERR und keiner mehr,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'der ich das Licht mache und schaffe die Finsternis, der ich Frieden gebe und schaffe das Ubel. Ich bin der HERR; der solches alles tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Traufelt, ihr Himmel, von oben, und die Wolken regnen die Gerechtigkeit; die Erde tue sich auf und bringe Heil, und Gerechtigkeit wachse mitzu! Ich, der HERR, schaffe es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Wehe dem, der mit seinem Schopfer hadert, namlich der Scherbe mit dem Topfer des Tons. Spricht auch der Ton zu seinem Topfer: Was machst du? Du beweisest deine Hande nicht an deinem Werke?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Wehe dem, derzum Vatersagt: Warum hast du mich gezeuget? und zum Weibe: Warum gebierest du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So spricht der HERR, der Heilige in Israel und ihr Meister: Fordert von mir die Zeichen; weiset meine Kinder und das Werk meiner Hande zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ich habe die Erde gemacht und den Menschen darauf geschaffen. Ich bin\'s, des Hande den Himmel ausgebreitet haben, und habe all seinem Heer geboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ich habe ihn erweckt in Gerechtigkeit, und alle seine Wege will ich eben machen. Er soil meine Stadt bauen und meine Gefangenen loslassen, nicht urn Geld noch urn Geschenke, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So spricht der HERR: Der Agypter Handel und der Mohren Gewerbe und der langen Leute zu Seba werden sich dirergeben und dein eigen sein; sie werden dir folgen; in Fesseln werden sie gehen und werden vor dir niederfallen und zu dir flehen; denn bei dir ist Gott, und ist sonst kein Gott nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Furwahr, du bist ein verborgener Gott, du Gott Israels, der Heiland!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Aber die Gotzenmacher müssen allesamt mit Schanden und Hohn bestehen und miteinander schamrot hingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel aberwird erlosetdurch den HERRN, durch eine ewige Erlosung, und wird nicht zuschanden noch zu Spott immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Denn so spricht der HERR, der den Himmel geschaffen hat, der Gott, der die Erde zubereitet hat und hat sie gemacht und zugerichtet und sie nicht gemacht hat, daß sie leer soli sein, sondern sie zubereitet hat, daß man darauf wohnen solle: Ich bin der HERR, und ist keiner mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Ich habe nicht ins Verborgene geredet, im finstern Odder Erde. Ich habe nicht zum Samen Jakobs vergeblich gesagt: Suchet mich! Denn ich bin der HERR, der von Gerechtigkeit redet und verkundige, das da recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Lafi sich versammeln und kommen miteinander herzu die Helden der Heiden, die nichts wissen und tragen sich mit den Klotzen ihrer Gotzen und flehen dem Gott, der nicht helfen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Verkundiget und macht euch herzu; ratschlaget miteinander! Wer hat dies lassen sagen von alters her und dazumal verkundiget? Habe ich\'s nicht getan, der HERR? Und ist sonst kein Gott ohne ich, ein gerechter Gott und Heiland; und keiner ist ohne ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Wendet euch zu mir,: so werdet ihr selig, aller Welt Ende! Denn ich bin Gott und keiner mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Ich schwore bei mir selbst, und ein Wort der Gerechtigkeit gehet aus meinem Munde, da soil es bei bleiben, namlich: Mir sollen sich alle Kniee beugen, und alle Zungen schworen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'und sagen: Im HERRN habe ich Gerechtigkeit und Starke. Solche werden auch zu ihm kommen; aber alle, die ihm widerstehen, müssen zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Denn im HERRN werden gerecht aller Same Israels und sich sein rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Der Bel ist gebeuget, der Nebo ist gefallen, ihre Gotzen sind den Tieren und Vieh zuteil worden, dafi sie sich müde tragen an eurer Last.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ja, sie fallen und beugen sich allesamt und konnen die Last nicht wegbringen, sondern ihre Seelen müssen ins Gefangnis gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Horet mir zu, ihr vom Hause Jakob und alle übrigen vom Hause Israel, die ihr von mirim Leibe getragen werdet und mir in der Mutter lieget!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Ja, ich will euch tragen bis ins Alter und bis ihr grau werdet. Ich will es tun; ich will heben und tragen und erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Nach wem bildet und wem vergleicht ihr mich denn? Gegen wen messet ihr mich, dem ich gleich sein solle?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Sie schütten das Gold aus dem Beutel und wagen dar das Silber mit der Waage und lohnen dem Goldschmied, daß er einen Gott daraus mache, vor dem sie knieen und anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie heben ihn auf die Achsel und tragen ihn und setzen ihn an seine Statte. Da stehet er und kommt von seinem Ort nicht. Schreiet einer zu ihm, so antwortet er nicht und hilft ihm nicht aus seiner Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'An solches gedenket doch und seid fest; ihr Ubertreter, gehet in euer Herz!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Gedenket des Vorigen von alters her, denn ich bin Gott, und keiner mehr, ein Gott, desgleichen nirgend ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'der ich verkundige zuvor, was hernach kommen soil, und vorhin, ehe denn es geschieht, und sage: Mein Anschlag bestehet, und ich tue alles, was mir gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Ich rufe einem Vogel vom Aufgang und einem Mann, der meinen Anschlag tue, aus fernem Lande. Was ich sage, das lasse ich kommen; was ich denke, das tue ich auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Horet mirzu, ihr von stolzem Herzen, die ihr feme seid von der Gerechtigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Ich habe meine Gerechtigkeit nahe gebracht, sie ist nicht feme, und mein Heil saumt sich nicht; denn ich will zu Zion das Heil geben und in Israel meine Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Herunter, Jungfrau, du Tochter Babel, setze dich in den Staub, setze dich auf die Erde! Denn die Tochter der Chaldaer hat keinen Stuhl mehr. Man wird dich nicht mehr nennen: Du Zarte und Lustlin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Nimm die Muhle und mahle Mehl, flicht deine Zopfe aus, entbldlie den Fuft, entdecke den Schenkel, wate durchs Wasser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'daß deine Scham aufgedeckt und deine Schande gesehen werde. Ich will mich rachen, und soil mir kein Mensch abbitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, '(Solches tut) unser Erloser, welcher heifit der HERR Zebaoth, der Heilige in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Setzte dich in das Stille, gehe in die Finsternis, du Tochter der Chaldaer; denn du sollst nicht mehr heiften: Frau uber Konigreiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Denn da ich uber mein Volk zornig war und entweihete mein Erbe, ubergab ich sie in deine Hand; aber du beweisetest ihnen keine Barmherzigkeit; auch uber die Alten machtest du dein Joch allzu schwer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'und dachtest: Ich bin eine Konigin ewiglich. Du hast solches bisher noch nicht zu Herzen gefasset noch daran gedacht, wie es mit ihnen hernach werden sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'So hore nun dies, die du in Wollust lebest und so sicher sitzest und sprichst in deinem Herzen: Ich bin\'s und keine mehr; ich werde keine Witwe werden noch unfruchtbar sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Aber es werden dir solche alle beide kommen plotzlich auf einen Tag, daß du Witwe und unfruchtbar seiest; ja, vollkommlich werden sie uber dich kommen urn der Menge willen deiner Zauberer und urn deiner Beschworer widen, deren ein grafter Haufe bei dir ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Denn du hast dich auf deine Bosheit verlassen, da du dachtest: Man siehet mich nicht; deine Weisheit und Kunst hat dich gesturzt und sprichst in deinem Herzen: Ich bin\'s und sonst keine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Darum wird uber dich ein Ungluck kommen, das du nicht weiftest, wenn es daherbricht, und wird ein Unfall auf dich fallen, den du nicht suhnen kannst; denn es wird plotzlich ein Getummel uber dich kommen, des du dich nicht versiehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'So tritt nun auf mit deinen Beschworern und mit der Menge deiner Zauberer, unter welchen du dich von deiner Jugend auf bemuhet hast, ob du dir mochtest raten, ob du mochtest dich starken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Denn du bist mude vor der Menge deiner Anschlage. Lafi hertreten und dir helfen die Meister des Himmelslaufs und die Sterngucker, die nach den Monden rechnen, was uber dich kommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Siehe, sie sind wie Stoppeln, die das Feuer verbrennet; sie konnen ihr Leben nicht erretten vor der Flamme; denn es wird nicht eine Glut sein, dabei man sich warme, Oder ein Feuer, da man urn sitzen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Also sind sie, unter welchen du dich bemuhet hast, deine Hantierer von deiner Jugend auf; ein jeglicher wird seines Ganges hie- und daher gehen, und hast keinen Heifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Horet das, ihr vom Hause Jakob, die ihr heiliet mit Namen Israel und aus dem Wasser Judas geflossen sind, die ihr schworet bei dem Namen des HERRN und gedenket des Gottes in Israel, aber nicht in der Wahrheit noch Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Denn sie nennen sich aus der heiligen Stadt und trotzen auf den Gott Israels, der da heifit der HERR Zebaoth:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Ich hab\'s zuvor verkundiget dies Zukünftige; aus meinem Munde ist\'s kommen, und ich habe es lassen sagen; ich tue es auch plotzlich, daß es kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Denn ich weift, daß du hart bist; und dein Nacken ist eine eiserne Ader, und deine Stirn ist ehern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Ich habe dir\'s verkundiget zuvor und habe dir\'s lassen sagen, ehe denn es kommen ist, auf daß du nicht sagen mogest: Mein Gotze tut\'s, und mein Bild und Gotze hat\'s befohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Solches alles horest du und siehest es und hast\'s doch nicht verkundiget. Denn ich habe dir zuvor Neues sagen lassen und Verborgenes, das du nicht wufttest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Nun aber ist\'s geschaffen, und nicht dazumal, und hast nicht einen Tag zuvor davon gehoret, auf daß du nicht sagen mogest: Siehe, das wuftte ich wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Denn du horetest es nicht und wufttest es auch nicht, und dein Ohr war dazumal nicht geoffnet; ich aber wuftte wohl, daß du verachten wurdest und von Mutterleibe an ein Ubertreter genannt bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Darum bin ich urn meines Namens willen geduldig und urn meines Ruhms willen will ich mich dir zugut enthalten, daß du nicht ausgerottet werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Siehe, ich will dich lautern, aber nicht wie Silber; sondern ich will dich auserwahlt machen im Ofen des Elendes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Urn meinetwillen, ja urn meinetwillen will ich\'s tun, daß ich nicht gelastert werde; denn ich will meine Ehre keinem andern lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Hore mirzu, Jakob, und du, Israel, mein Berufener: Ich bin\'s, ich bin der Erste, dazu auch der Letzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Meine Hand hat den Erdboden gegrundet und meine rechte Hand hat den Himmel umspannet: was ich rufe, das stehet alles da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Sammelt euch alle und horet: Wer ist unter diesen, der solches verkundigen kann? Der HERR liebet ihn; darum wird erseinen Willen an Babel und seinen Arm an den Chaldaern beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ich, ja ich habe es gesagt, ich habe ihm gerufen; ich will ihn auch kommen lassen, und sein Weg soil ihm gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Tretet her zu mir und horet dies; ich hab\'s nicht im Verborgenen zuvor geredet. Von der Zeit an, da es geredet wird, bin ich da; und nun sendet mich der Herr HERR und sein Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So spricht der HERR, dein Erloser, der Heilige in Israel: Ich bin der HERR, dein Gott, der dich lehret, was nutzlich ist, und leite dich auf dem Wege, den du gehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, '0 daß du auf meine Gebote merktest! So wurde dein Friede sein wie ein Wasserstrom und deine Gerechtigkeit wie Meereswellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'und dein Same wurde sein wie Sand und das Gewachs deines Leibes wie desselbigen Kies, des Name nicht wurde ausgerottet noch vertilget vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Gehet aus von Babel, fliehet von den Chaldaern mit frohlichem Schall; verkündiget und lasset solches horen; bringet es aus bis an der Welt Ende! Sprechet: Der HERR hat seinen Knecht Jakob erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Sie hatten keinen Durst, da er sie leitete in der Wuste; er lieli ihnen Wasser aus Felsen flielien; er rili den Fels, daß Wasser herausrann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Aber die Gottlosen, spricht der HERR, haben keinen Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Horet mir zu, ihr Inseln, und ihr Volker in der Feme, merket auf! Der HERR hat mir gerufen von Mutterleibe an; er hat meines Namens gedacht, da ich noch in Mutterleibe war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'und hat meinen Mund gemacht wie ein scharf Schwert; mit dem Schatten seiner Hand hat er mich bedeckt. Er hat mich zum reinen Pfeil gemacht und mich in seinen Kocher gesteckt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'und spricht zu mir: Du bist mein Knecht, Israel, durch welchen ich will gepreiset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Ich aber dachte, ich arbeitete vergeblich und brachte meine Kraft umsonst und unnutzlich zu, wiewohl meine Sache des HERRN und mein Amt meines Gottes ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Und nun spricht der HERR, der mich von Mutterleibe an zu seinem Knechte bereitet hat, daß ich soil Jakob zu ihm bekehren, auf daß Israel nicht weggeraffet werde; darum bin ich vor dem HERRN herrlich, und mein Gott ist meine Starke');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'und spricht: Es ist ein Geringes, daß du mein Knecht bist, die Stamme Jakobs aufzurichten und das Verwahrlosete in Israel wiederzubringen, sondern ich habe dich auch zum Licht der Heiden gemacht, dad du seiest mein Heil bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So spricht der HERR, der Erloser Israels, sein Heiliger, zu der verachteten Seele, zu dem Volk, des man Greuel hat, zu dem Knechte, der unter den Tyrannen ist: Konige sollen sehen und aufstehen, und Fursten sollen anbeten urn des HERRN willen, der treu ist, urn des Heiligen in Israel widen, der dich erwahlet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'So spricht der HERR: Ich habe dich erhoret zur gnadigen Zeit und habe dir am Tage des Heils geholfen; und habe dich behutet und zum Bund unter das Volk gestellet, daß du das Land aufrichtest und die verstorten Erbe einnehmest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'zu sagen den Gefangenen: Gehet heraus! und zu denen in Finsternis: Kommt hervor! daß sie am Wege sich weiden und auf alien Hügeln ihre Weide haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Sie werden weder hungern noch dursten, sie wird keine Hitze noch Sonne stechen; denn ihr Erbarmer wird sie führen und wird sie an die Wasserquellen leiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Ich will alle meine Berge zum Wege machen, und meine Pfade sollen gebahnet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Siehe, diese werden von feme kommen, und siehe, jene von Mitternacht und diese vom Meer und diese vom Lande Sinim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Jauchzet, ihr Himmel; freue dich, Erde; lobet, ihr Berge, mit Jauchzen! Denn der HERR hat sein Volk getrostet und erbarmet sich seiner Elenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Zion aber spricht: Der HERR hat mich verlassen, der HERR hat mein vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Kann auch ein Weib ihres Kindleins vergessen, daß sie sich nicht erbarme uber den Sohn ihres Leibes? Und ob sie desselbigen vergalie, so will ich doch dein nicht vergessen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'siehe, in die Hande habe ich dich gezeichnet. Deine Mauern sind immerdar vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Deine Baumeister werden eilen, aber deine Zerbrecher und Verstorer werden sich davonmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Hebe deine Augen auf umher und siehe! Alle diese kommen versammelt zu dir. So wahr ich lebe, spricht der HERR, du sollst mit diesen alien wie mit einem Schmuck angetan werden und wirst sie urn dich legen wie eine Braut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Denn dein wustes, verstortes und zerbrochenes Land wird dir alsdann zu enge werden, drinnen zu wohnen, wenn deine Verderber feme von dir kommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'daß die Kinder deiner Unfruchtbarkeit werden weiter sagen vor deinen Ohren: Der Raum ist mir zu enge; rücke hin, daß ich bei dir wohnen moge!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Du aber wirst sagen in deinem Herzen: Wer hat mir diese gezeuget? Ich bin unfruchtbar, einzeln, vertrieben und verstolien. Wer hat mir diese erzogen? Siehe, ich war einsam gelassen; wo waren denn diese?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'So spricht der Herr HERR: Siehe, ich will meine Hand zu den Heiden aufheben und zu den Volkern mein Panier aufwerfen, so werden sie deine Sohne in den Armen herzubringen und deine Tochter auf den Achseln hertragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Und die Konige sollen deine Pfleger und ihre Furstinnen deine Saugammen sein. Sie werden vor dir niederfallen zur Erde aufs Angesicht und deiner Fülie Staub lecken. Da wirst du erfahren, daß ich der HERR bin, an welchem nicht zuschanden werden, so auf mich harren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kann man auch einem Riesen den Raub nehmen, Oder kann man dem Gerechten seine Gefangenen losmachen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Denn so spricht der HERR: Nun sollen die Gefangenen dem Riesen genommen werden und der Raub des Starken los werden; und ich will mit deinen Haderern hadern und deinen Kindern helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Und ich will deine Schinder speisen mit ihrem eigenen Fleisch; und sollen mit ihrem eigenen Blut, wie mit suliem Wein, trunken werden; und alles Fleisch soil erfahren, daß ich bin der HERR, dein Heiland und dein Erloser, der Machtige in Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So spricht der HERR: Wo ist der Scheidebrief eurer Mutter, damit ich sie gelassen habe? Oder wer ist mein Wucherer, dem ich euch verkauft habe? Siehe, ihrseid um eurer Sünden willen verkauft, und eure Mutter ist um eures Ubertretens willen gelassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Warum kam ich, und war niemand da; ich rief, und niemand antwortete? Ist meine Hand nun so kurz worden, daü sie nicht erlosen kann, Oder ist bei mir keine Kraft zu erretten? Siehe, mit meinem Schelten mache ich das Meer trocken und mache die Wasserstrome als eine Wüste, daß ihre Fische vor Wassermangel stinken und Durst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Ich kleide den Himmel mit Dunkel und mache seine Decke als einen Sack.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Der Herr HERR hat mir eine gelehrte Zunge gegeben, daß ich wisse, mit dem Müden zu rechter Zeitzu reden. Erwecket mich alle Morgen; erwecket mir das Ohr, daß ich hore wie ein Jünger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Der Herr HERR hat mir das Ohr geoffnet; und ich bin nicht ungehorsam und gehe nicht zurück.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Ich hielt meinen Rücken dardenen, die mich schlugen, und meine Wangen denen, die mich rauften; mein Angesicht verbarg ich nicht vor Schmach und Speichel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Denn der Herr HERR hilft mir, darum werde ich nicht zuschanden. Darum habe ich mein Angesicht dargeboten als einen Kieselstein; denn ich weift, dafi ich nicht zuschanden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Er ist nahe, der mich rechtspricht; wer will mit mir hadern? Laftt uns zusammentreten; wer ist, der Recht zu mir hat? Der komme her zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Siehe, der Herr HERR hilft mir; wer ist, der mich will verdammen? Siehe, siewerden allzumal wie ein Kleid veralten, Motten werden sie fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Wer ist unter euch, der den HERRN furchtet, der seines Knechts Stimme gehorche, der im Finstern wandelt und scheinet ihm nicht? Der hoffe auf den Namen des HERRN und verlasse sich auf seinen Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Siehe, ihr alle, die ihr ein Feuer anzundet, mit Flammen gerustet: wandelt hin im Lichte eures Feuers und in Flammen, die ihr angezündet habt. Solches widerfahret euch von meiner Hand; in Schmerzen müsset ihr liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Horet mirzu, die ihr der Gerechtigkeit nachjaget, die ihr den HERRN suchet: Schauet den Fels an, davon ihr gehauen seid, und des Brunnens Gruft, daraus ihrgegraben seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Schauet Abraham an, euren Vater, und Sara, von welcher ihr geboren seid. Denn ich rief ihm, da er noch einzeln war, und segnete ihn und mehrete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Denn der HERR trostet Zion; er trostet alle ihre Wusten und macht ihre Wusten wie Lustgarten und ihre Gefüde wie einen Garten des HERRN, daß man Wonne und Freude drinnen findet, Dank und Lobgesang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Merke auf mich, mein Volk; horet mich, meine Leute! Denn von mirwird ein Gesetz ausgehen, und mein Recht will ich zum Licht der Volker gar bald stelien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Denn meine Gerechtigkeit ist nahe, mein Heil zeucht aus, und meine Arme werden die Volker richten. Die Inseln harren auf mich und warten auf meinen Arm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Hebet eure Augen auf gen Himmel und schauet unten auf die Erde! Denn der Himmel wird wie ein Rauch vergehen und die Erde wie ein Kleid veralten, und die darauf wohnen, werden dahinsterben im Nu! Aber mein Heü bleibet ewiglich, und meine Gerechtigkeit wird nicht verzagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Horet mir zu, die ihr die Gerechtigkeit kennet, du Volk, in welches Herzen mein Gesetz ist! Furchtet euch nicht, wenn euch die Leute schmahen, und entsetzet euch nicht, wenn sie euch verzagt machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Denn die Motten werden sie fressen wie ein Kleid, und Wurmer werden sie fressen wie ein wollen Tuch; aber meine Gerechtigkeit bleibet ewiglich und mein Heil fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Wohlauf, wohlauf, zeuch Macht an, du Arm des HERRN! Wohlauf, wie vorzeiten, von alters her! Bist du nicht der, so die Stolzen ausgehauen und den Drachen verwundet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Bistdu nicht, der das Meer der groften, tiefen Wasser austrocknete, der den Grund des Meers zum Wege machte, daß die Erloseten dadurchgingen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Also werden die Erloseten des HERRN wiederkehren und gen Zion kommen mit Ruhm; und ewige Freude wird auf ihrem Haupte sein. Wonne und Freude werden sie ergreifen, aber Trauern und Seufzen wird von ihnen fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ich, ich bin euer Troster. Wer bistdu denn, daß du dich vor Menschen furchtest, die doch sterben, und vor Menschenkindern, die als Heu verzehret werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'und vergissest des HERRN, der dich gemacht hat, der den Himmel ausbreitete und die Erde grundete? Du aber furchtest dich taglich den ganzen Tag vor dem Grimm des Wuterichs, wenn er vornimmt zu verderben. Wo blieb der Grimm des Wuterichs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'da er muftte eilen und umherlaufen, daß er losgabe, und sie nicht starben unter dem Verderben, auch keinen Mangel an Brot hatten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Denn ich bin der HERR, dein Gott, der das Meer bewegt, daß seine Wellen wüten; sein Name heiftt HERRZebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Ich lege mein Wort in deinen Mund und bedecke dich unter dem Schatten meiner Hande, auf daß ich den Himmel pflanze und die Erde gründe und zu Zion spreche: Du bist mein Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Wache auf, wache auf, stehe auf, Jerusalem, die du von der Hand des HERRN den Kelch seines Grimms getrunken hast! Die Hefen des Taumelkelchs hast du ausgetrunken und die Tropfen geleckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Es war niemand aus alien Kindern, die sie geboren hat, der sie leitete, niemand aus alien Kindern, die sie erzogen hat, der sie bei der Hand nahme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Diese zwei sind dir begegnet; wer trug Leid mit dir? Da war Verstorung, Schaden, Hunger und Schwert; wer sollte dich trosten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Deine Kinder waren verschmachtet; sie lagen auf alien Gassen wie ein verstrickter Hirsch, voll des Zorns vom HERRN und des Scheltens von deinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Darum hore dies, du Elende und Trunkene ohne Wein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So spricht dein Herrscher, der HERR, und dein Gott, der sein Volk rachet: Siehe, ich nehme den Taumelkelch von deiner Hand samt den Hefen des Kelchs meines Grimms; du sollst ihn nicht mehr trinken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'sondern ich will ihn deinen Schindern in die Hand geben, die zu deiner Seele sprachen: Bücke dich, daß wir uberhingehen, und lege deinen Rücken zur Erde und wie eine Gasse, daß man überhinlaufe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Mache dich auf, mache dich auf, Zion; zieh deine Starke an, schmücke dich herrlich, du heilige Stadt Jerusalem! Denn es wird hinfort kein Unbeschnittener Oder Unreiner in dir regieren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Mache dich aus dem Staube, stehe auf, du gefangene Jerusalem; mache dich los von den Banden deines Halses, du gefangene Tochter Zion!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Denn also spricht der HERR: Ihr seid umsonst verkauft, ihr sollt auch ohne Geld geloset werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Denn so spricht der Herr HERR: Mein Volk zog am ersten hinab nach Agypten, daß es daselbst ein Gast ware; und Assur hat ihm ohne Ursache Gewalt getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Aber wie tut man mir jetzt allhie? spricht der HERR. Mein Volk wird umsonst verführet; seine Herrscher machen eitel Heulen, spricht der HERR; und mein Name wird immer taglich gelastert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Darum soil mein Volk meinen Namen kennen zu derselbigen Zeit; denn siehe, ich will selbst reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Wie lieblich sind auf den Bergen die Fulie der Boten, die da Frieden verkundigen, Gutes predigen, Heil verkundigen, die da sagen zu Zion: Dein Gott ist Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Deine Wachter rufen laut mit ihrer Stimme und rühmen miteinander; denn man wird\'s mit Augen sehen, wenn der HERR Zion bekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Lasset frohlich sein und miteinander ruhmen das Wuste zu Jerusalem; denn der HERR hat sein Volk getrostet und Jerusalem erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Der HERR hat offenbaret seinen heiligen Arm vor den Augen aller Heiden, daß aller Welt Ende siehet das Heil unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Weichet, weichet! Ziehet aus von dannen und rühret kein Unreines an! Gehet aus von ihr, reiniget euch, die ihr des HERRN Gerate traget!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Denn ihr sollt nicht mit Eilen ausziehen noch mit Flucht wandeln; denn der HERR wird vor euch herziehen, und der Gott Israels wird euch sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Siehe, mein Knecht wird weislich tun und wird erhohet und sehr hoch erhaben sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'daß sich viele uber dir argern werden, weil seine Gestalt haftlicher ist denn anderer Leute und sein Ansehen denn der Menschenkinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Aber also wird erviel Heiden besprengen, daß auch Konige werden ihren Mund gegen ihm zuhalten. Denn welchen nichts davon verkundiget ist, dieselben werden\'s mit Lust sehen, und die nichts davon gehoret haben, die werden\'s merken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Aber wer glaubt unserer Predigt, und wem wird der Arm des HERRN offenbaret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Denn er schiefit auf vor ihm wie ein Reis und wie eine Wurzel aus durrem Erdreich. Er hatte keine Gestalt noch Schone; wir sahen ihn, aber da war keine Gestalt, die uns gefallen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Er war der Allerverachtetste und Unwerteste, voller Schmerzen und Krankheit. Er war so verachtet, daß man das Angesicht vor ihm verbarg; darum haben wir ihn nichts geachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Fürwahr, er trug unsere Krankheit und lud auf sich unsere Schmerzen. Wir aber hielten ihn fur den, der geplagt und von Gott geschlagen und gemartert ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Aber er ist urn unserer Missetat willen verwundet und urn unserer Sünde willen zerschlagen. Die Strafe liegt auf ihm, auf daß wir Frieden hatten, und durch seine Wunden sind wir geheilet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wir gingen alle in der Irre wie Schafe, ein jeglicher sah auf seinen Weg; aber der HERR warf unser aller Sünde auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Da er gestraft und gemartert ward, tat er seinen Mund nicht auf, wie ein Lamm, das zur Schlachtbank geführt wird, und wie ein Schaf, das verstummet vor seinem Scherer und seinen Mund nicht auftut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Er ist aber aus der Angst und Gericht genommen; wer will seines Lebens Lange ausreden? Denn er ist aus dem Lande der Lebendigen weggerissen, da er urn die Missetat meines Volks geplagt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Und er ist begraben wie die Gottlosen und gestorben wie ein Reicher, wiewohl er niemand unrecht getan hat, noch Betrug in seinem Munde gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Aber der HERR wollte ihn also zerschlagen mit Krankheit. Wenn er sein Leben zum Schuldopfer gegeben hat, so wird er Samen haben und in die Lange leben; und des HERRN Vomehmen wird durch seine Hand fortgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Darum daß seine Seele gearbeitet hat, wird er seine Lust sehen und die Fülle haben. Und durch seine Erkenntnis wird er, mein Knecht, der Gerechte, viele gerecht machen; denn er tragt ihre Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Darum will ich ihm grolie Menge zur Beute geben, und er soil die Starken zum Raube haben, darum daß er sein Leben in den Tod gegeben hat und den Ubeltatern gleich gerechnet ist und er vieler Sunde getragen hat und fur die Ubeltater gebeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Ruhme, du Unfruchtbare, die du nicht gebierest; freue dich mit Ruhm und jauchze, die du nicht schwanger bist! Denn die Einsame hat mehr Kinder, weder die den Mann hat, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Mache den Raum deiner Hutte weit und breite aus die Teppiche deiner Wohnung, spare sein nicht; dehne deine Seile lang und stecke deine Nagel fest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Denn du wirst ausbrechen zur Rechten und zur Linken; und dein Same wird die Heiden erben und in den verwüsteten Stadten wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Furchte dich nicht, denn du sollst nicht zuschanden werden; werde nicht blode, denn du sollst nicht zu Spott werden, sondern du wirst der Schande deiner Jungfrauschaft vergessen und der Schmach deiner Witwenschaft nicht mehr gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Denn der dich gemacht hat, ist dein Mann; HERR Zebaoth heilit sein Name; und dein Erloser, der Heilige in Israel, der aller Welt Gott genannt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Denn der HERR hat dich lassen im Geschrei sein, daß du seiest wie ein verlassen und von Herzen betrubt Weib und wie ein junges Weib, das verstolien ist, spricht dein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Ich habe dich einen deinen Augenblick verlassen; aber mit grofier Barmherzigkeit will ich dich sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Ich habe mein Angesicht im Augenblick des Zorns ein wenig von dir verborgen; aber mit ewiger Gnade will ich mich dein erbarmen, spricht der HERR, dein Erloser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Denn solches soil mir sein wie das Wasser Noahs, da ich schwur, daß die Wasser Noahs sollten nicht mehr über den Erdboden gehen. Also habe ich geschworen, daß ich nicht uber dich zurnen noch dich schelten will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Denn es sollen wohl Berge weichen und Hugel hinfallen; aber meine Gnade soil nicht von dir weichen, und der Bund meines Friedens soil nicht hinfallen, spricht der HERR, dein Erbarmer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Du Elende, uber die alle Wetter gehen, und du Trostlose! Siehe, ich will deine Steine wie einen Schmuck legen und will deinen Grund mit Saphiren legen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'und deine Fensteraus Kristallen machen und deine Tore von Rubinen und alle deine Grenzen von erwahlten Steinen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'und alle deine Kinder gelehrt vom HERRN und grolien Frieden deinen Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Du sollst durch Gerechtigkeit bereitet werden. Du wirst feme sein von Gewalt und Unrecht, daß du dich davor nicht durfest furchten, und von Schrecken, denn es soil nicht zu dir nahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Siehe, wer will sich wieder dich rotten und dich überfallen, so sie sich ohne mich rotten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Siehe, ich schaffe es, daß der Schmied, so die Kohlen im Feuer aufblaset, einen Zeug daraus mache zu seinem Werk; denn ich schaffe es, daß der Verderber umkommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Denn aller Zeug, der wider dich zubereitet wird, dem soil nicht, gelingen, und alle Zunge, so sich wider dich setzt, sollst du im Gericht verdammen. Das ist das Erbe der Knechte des HERRN und ihre Gerechtigkeit von mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Wohlan, alle, die ihr durstig seid, kommt her zum Wasser; und die ihr nicht Geld habt, kommt her, kaufet und esset; kommt her und kaufet ohne Geld und umsonst beides, Wein und Milch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Warum zahlet ihr Geld dar, da kein Brot ist, und eure Arbeit, da ihr nicht satt von werden konnet? Horet mir doch zu und esset das Gute, so wird eure Seele in Wollust fett werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Neiget eure Ohren her und kommt her zu mir; horet, so wird eure Seele leben! Denn ich will mit euch einen ewigen Bund machen, namlich die gewissen Gnaden Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Siehe, ich habe ihn den Leuten zum Zeugen gestellet, zum Fursten und Gebieter den Vblkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Siehe, du wirst Heiden rufen, die du nicht kennest; und Heiden, die dich nicht kennen, werden zu dir laufen urn des HERRN willen, deines Gottes, und des Heiligen in Israel, der dich preise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Suchet den HERRN, weil er zu finden ist; rufet ihn an, weil er nahe ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Der Gottlose lasse von seinem Wege und der Ubeltater seine Gedanken und bekehre sich zum HERRN, so wird ersich sein erbarmen, und zu unserm Gott, denn bei ihm ist viel Vergebung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Denn meine Gedanken sind nicht eure Gedanken, und eure Wege sind nicht meine Wege, spricht der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'sondern soviel der Himmel hoher ist denn die Erde, so sind auch meine Wege hoher denn eure Wege und meine Gedanken denn eure Gedanken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Denn gleichwie der Regen und Schnee vom Himmel fallt und nicht wieder dahin kommt, sondern feuchtet die Erde und macht sie fruchtbar und wachsend, daß sie gibt Samen zu saen und Brot zu essen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'also soil das Wort, so aus meinem Munde gehet, auch sein: Es soli nicht wieder zu mir leer kommen, sondern tun, das mir gefallt, und soli ihm gelingen, dazu ich\'s sende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Denn ihrsollt in Freuden ausziehen und im Frieden geleitet werden. Berge und FHugel sollen vor euch her frohlocken mit Ruhm und alle Baume auf dem Felde mit den Handen klappen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Es sollen Tannen fur Hecken wachsen und Myrten fur Dornen; und dem HERRN soli ein Name und ewiges Zeichen sein, das nicht ausgerottet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So spricht der HERR: Haltet das Recht und tut Gerechtigkeit; denn mein Heil ist nahe, daß es komme, und meine Gerechtigkeit, daß sie offenbart werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Wohl dem Menschen, der solches tut, und dem Menschenkind, der es festhalt, dafi er den Sabbat halte und nicht entheilige und halte seine Hand, dafi er kein Arges tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Und der Fremde, der zum HERRN sich getan hat, soil nicht sagen: Der HERR wird mich scheiden von seinem Volk. Und der Verschnittene soil nicht sagen: Siehe, ich bin ein durrer Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Denn so spricht der HERR zu den Verschnittenen, welche meine Sabbate halten und erwahlen, was mirwohlgefallt, und meinen Bund fest fassen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Ich will ihnen in meinem Hause und in meinen Mauern einen Ort geben und einen bessern Namen denn den Sohnen und Tochtern; einen ewigen Namen will ich ihnen geben, der nicht vergehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Und der Fremden Kinder, die sich zum HERRN getan haben, daß sie ihm dienen und seinen Namen lieben, auf daß sie seine Knechte seien, ein jeglicher, der den Sabbat halt, daß er ihn nicht entweihe, und meinen Bund fest halt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'dieselbigen will ich zu meinem heiligen Berge bringen und will sie erfreuen in meinem Bethause, und ihre Opfer und Brandopfer sollen mir angenehm sein auf meinem Altar; denn mein Haus heiftt ein Bethaus alien Volkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Der Herr HERR, der die Verstoftenen aus Israel sammelt, spricht: Ich will noch mehr zu dem Haufen, die versammelt sind, sammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Alle Tiere auf dem Felde, kommt und fresset, ja alle Tiere im Walde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Alle ihre Wachter sind blind, sie wissen alle nichts; stumme Hunde sind sie, die nicht strafen konnen; sind faul, liegen und schlafen gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Es sind aber starke Hunde von Leibe, die nimmer satt werden konnen. Sie, die Hirten, wissen keinen Verstand; ein jeglicher siehet auf seinen Weg, ein jeglicher geizet fur sich in seinem Stande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Kommt her, laftt uns Wein holen und vollsaufen; und soil morgen sein wie heute und noch viel mehr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Aber der Gerechte kommt urn, und niemand ist, der es zu Herzen nehme; und heilige Leute werden aufgerafft, und niemand achtet darauf. Denn die Gerechten werden weggerafft vor dem Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Und die richtig vor sich gewandelt haben, kommen zum Frieden und ruhen in ihren Kammern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Und ihr, kommt herzu, ihr Kinder der Tagwahlerin, ihr Samen des Ehebrechers und der Hure!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'An wem wollt ihr nun eure Lust haben? Uber wen wollt ihr nun das Maul aufsperren und die Zunge herausrecken? Seid ihr nicht die Kinder der Ubertretung und ein falscher Same,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'die ihr in der Brunst zu den Gotzen laufet unter alle grünen Baume und schlachtet die Kinder an den Bachen unter den Felskuppen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Dein Wesen ist an den glatten Bachsteinen; dieselbigen sind dein Teil; denselbigen schuttest du dein Trankopfer, da du Speisopfer opferst. Sollte ich mich des trosten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Du machst dein Lager auf einen hohen, erhabenen Berg und gehest daselbst auch hinauf zu opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Und hinter der Tur und Pfosten stellest du dein Gedachtnis. Denn du walzest dich von mir und gehest hinauf und machest dein Lager weit und verbindest dich mit ihnen; du liebest, ihr Lager, wo du sie ersiehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Du zeuchst mit 01 zum Konige und hast mancherlei Wurze; und sendest deine Botschaft in die Feme und bist geniedriget bis zur Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Du zerarbeitetest dich in der Menge deiner Wege und sprachest nicht: Ich lasse es, sondern weil du findest ein Leben deiner Hand, wirst du nicht müde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Vor wem bist du so sorgfaltig und furchtest also, so du doch mit Lugen umgehest und denkest an mich nicht und nimmst es nicht zu Herzen? Meinest du, ich werde allewege schweigen, daß du mich so gar nicht furchtest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ich will aber deine Gerechtigkeit anzeigen und deine Werke, daß sie dir kein nütze sein sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Wenn du rufen wirst, so laft dir deine Haufen helfen. Aber der Wind wird sie alle wegfuhren, und Eitelkeit wird sie wegnehmen. Aber wer auf mich trauet, wird das Land erben und meinen heiligen Berg besitzen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'und wird sagen: Machet Bahn, machet Bahn, raumet den Weg, hebet die Anstofte aus dem Wege meines Volks!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Denn also spricht der Hohe und Erhabene, der ewiglich wohnet, des Name heilig ist, der ich in der Hohe und im Heiligtum wohne und bei denen, so zerschlagenen und demutigen Geistes sind, auf daß ich erquicke den Geist der Gedemutigten und das Herz der Zerschlagenen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Ich will nicht immerdar hadern und nicht ewiglich zurnen, sondern es soil von meinem Angesicht ein Geistweben, und ich will Odem machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Ich warzornig uber die Untugend ihres Geizes und schlug sie, verbarg mich und zurnete; da gingen sie hin und her im Wege ihres Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Aber da ich ihre Wege ansah, heilete ich sie und leitete sie und gab ihnen wieder Trost und denen, die uberjene Leid trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Ich will Frucht der Lippen schaffen, die da predigen: Friede, Friede! beide, denen in der Feme und denen in der Nahe, spricht der HERR, und will sie heilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Aber die Gottlosen sind wie ein ungestum Meer, das nicht stille sein kann, und seine Wellen Kot und Unflat auswerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Die Gottlosen haben nicht Frieden, spricht mein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Rufe getrost, schone nicht! Erhebe deine Stimme wie eine Posaune und verkundige meinem Volk ihr Ubertreten und dem Hause Jakob ihre Sunde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Sie suchen mich taglich und wollen meine Wege wissen, als ein Volk, das Gerechtigkeit schon getan und das Recht ihres Gottes nicht verlassen hatte. Sie fordern mich zu Recht und wollen mit ihrem Gott rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Warum fasten wir, und du siehest es nicht an? Warum tun wir unserm Leibe wehe, und du wilist es nicht wissen? Siehe, wenn ihr fastet, so übet ihr euren Willen und treibet alle eure Schuldiger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Siehe, ihr fastet, daß ihr hadert, und zanket und schlaget mit der Faust ungottlich. Fastet nicht also, wie ihr jetzt tut, daß ein Geschrei von euch in der Hohe gehoret wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Sollte das ein Fasten sein, das ich erwahlen soil, daß ein Mensch seinem Leibe des Tages ubel tue, Oder seinen Kopf hange wie ein Schilf, Oder auf einem Sack und in der Asche liege? Wollt ihr das ein Fasten nennen und einen Tag dem HERRN angenehm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Das ist aber ein Fasten, das ich erwahle: Lafi los, welche du mit Unrecht verbunden hast; lafi ledig, welche du beschwerest; gib frei, welche du drangest; reili weg allerlei Last;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'brich dem Hungrigen dein Brot und die, so im Elend sind, fuhre ins Haus; so du einen nackend siehest, so kleide ihn und entzeuch dich nicht von deinem Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Alsdann wird dein Licht hervorbrechen wie die Morgenrote und deine Besserung wird schnell wachsen, und deine Gerechtigkeit wird vor dir her gehen, und die Herrlichkeit des HERRN wird dich zu sich nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Dann wirst du rufen, so wird dir der HERR antworten; wenn du wirst schreien, wird er sagen: Siehe, hie bin ich! So du niemand bei dir beschweren wirst, noch mit Fingern zeigen, noch ubel reden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'und wirst den Hungrigen lassen finden dein Herz und die elende Seele sattigen, so wird dein Licht in Finsternis aufgehen, und dein Dunkel wird sein wie der Mittag;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'und der HERR wird dich immerdar fuhren und deine Seele sattigen in der Durre und deine Gebeine starken, und wirst sein wie ein gewasserter Garten und wie eine Wasserquelle, welcher es nimmer an Wasser fehlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Und soil durch dich gebauet werden, was lange wüste gelegen ist, und wirst Grund legen, der fur und fur bleibe, und sollst heilien: Der die Lucken verzaunet und die Wege bessert, daß man da wohnen mdge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'So du deinen Fuß von dem Sabbat kehrest, daß du nicht tust, was dir gefallt an meinem heiligen Tage, so wird\'s ein lustiger Sabbat heilien, den HERRN zu heiligen und zu preisen. Denn so wirst du denselbigen preisen, wenn du nicht tust deine Wege, noch darin erfunden werde, was dir gefallt, Oder was du redest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Alsdann wirst du Lust haben am HERRN, und ich will dich uber die Hdhen auf Erden schweben lassen und will dich speisen mit dem Erbe deines Vaters Jakob; denn des HERRN Mund sagt es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Siehe, des HERRN Hand ist nicht zu kurz, daß er nicht helfen konne; und seine Ohren sind nicht dick worden, daß er nicht hore,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'sondern eure Untugenden scheiden euch und euren Gott voneinander, und eure Sunden verbergen das Angesicht von euch, daß ihr nicht gehoret werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Denn eure Hande sind mit Blut befleckt und eure Finger mit Untugend; eure Lippen reden Falsches, eure Zunge dichtet Unrechtes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Es ist niemand, der von Gerechtigkeit predige Oder treulich richte. Man vertrauet aufs Eitle und redet nichts Tuchtiges; mit Ungluck sind sie schwanger und gebaren Muhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Sie brüten Basiliskeneier und wirken Spinnwebe. Isset man von ihren Eiern, so soil man sterben; zertritt man\'s aber, so fahrt eine Otter heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Ihre Spinnwebe taugt nicht zu Kleidern, und ihr Gewirke taugt nicht zur Decke; denn ihr Werk ist Muhe und in ihren Handen ist Frevel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Ihre Füße laufen zum Bosen und sind schnell, unschuldig Blut zu vergießen; ihre Gedanken sind Muhe, ihr Weg isteitel Verderben und Schaden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'sie kennen den Weg des Friedens nicht, und ist kein Recht in ihren Gangen; sie sind verkehrt auf ihren Straßen; wer darauf gehet, der hat nimmer keinen Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Darum ist das Recht feme von uns, und wir erlangen die Gerechtigkeit nicht. Wir harren aufs Licht, siehe, so wird\'s finster, auf den Schein, siehe, so wandeln wir im Dunkeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Wir tappen nach der Wand wie die Blinden und tappen, als die keine Augen haben. Wir stoften uns im Mittage als in der Dammerung; wir sind im Dustern wie die Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Wir brummen alle wie die Baren und achzen wie die Tauben; denn wir harren aufs Recht, so ist\'s nicht da, aufs Heil, so ist\'s feme von uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Denn unserer Obertretung vordir istzu viel, und unsere Sunden antworten wider uns. Denn unsere Ubertretungen sind bei uns, und wir fühlen unsere Sunden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'mit Ubertreten und Lugen wider den HERRN und Zuruckkehren von unserm Gott und mit Reden zum Frevel und Ungehorsam, trachten und dichten falsche Worte aus dem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Darum ist auch das Recht zuruckgewichen und Gerechtigkeit feme getreten; denn die Wahrheit fallt auf der Gasse, und Recht kann nicht einhergehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'und die Wahrheit ist dahin; und wer vom Bosen weicht, der muft jedermanns Raub sein. Solches siehet der HERR und gefallt ihm übel, daß kein Recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Und er siehet, daß niemand da ist, und verwundert sich, daß niemand sie vertritt. Darum hilft er ihm selbst mit seinem Arm, und seine Gerechtigkeit erhalt ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Denn er zeucht Gerechtigkeit an wie einen Panzer und setzt einen Helm des Heils auf sein Haupt; und zeucht sich an zur Rache und kleidet sich mit Eifer wie mit einem Rock,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'als der seinen Widersachern vergelten und seinen Feinden mit Grimm bezahlen will; ja, die Inseln will er bezahlen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'daß der Name des HERRN gefurchtet werde vom Niedergang und seine Herrlichkeit vom Aufgang der Sonne, wenn er kommen wird wie ein aufgehaltener Strom, den der Wind des HERRN treibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Denn denen zu Zion wird ein Erloser kommen und denen, die sich bekehren von den Sunden in Jakob, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Und ich mache solchen Bund mit ihnen, spricht der HERR: Mein Geist, der bei dir ist, und meine Worte, die ich in deinen Mund gelegt habe, sollen von deinem Munde nicht weichen noch von dem Munde deines Samens und Kindeskindes, spricht der HERR, von nun an bis in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Mache dich auf, werde licht; denn dein Licht kommt, und die Herrlichkeit des HERRN gehet auf uber dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn siehe, Finsternis bedeckt das Erdreich und Dunkel die Volker; aber uber dir gehet auf der HERR, und seine Herrlichkeit erscheinet uber dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Und die Heiden werden in deinem Lichte wandeln und die Konige im Glanz, der uber dir aufgehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Hebe deine Augen auf und siehe umher! Diese alle versammelt kommen zu dir! Deine Sohne werden von feme kommen und deine Tochter zur Seite erzogen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Dann wirst du deine Lust sehen und ausbrechen, und dein Herz wird sich wundern und ausbreiten, wenn sich die Menge am Meer zu dir bekehret, und die Macht der Heiden zu dir kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Denn die Menge der Kamele wird dich bedecken, die Laufer aus Midian und Epha. Sie werden aus Saba alle kommen, Gold und Weihrauch bringen und des HERRN Lob verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Alle Herden in Kedar sollen zu dir versammelt werden, und die Bocke Nebajoths sollen dirdienen. Sie sollen auf meinem angenehmen Altar geopfert werden; denn ich will das Haus meiner Herrlichkeit zieren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Wer sind die, welche fliegen wie die Wolken und wie die Tauben zu ihren Fenstern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Die Inseln harren auf mich und die Schiffe im Meer vorlangst her, daß sie deine Kinder von feme herzubringen, samt ihrem Silber und Golde, dem Namen des HERRN, deines Gottes, und dem Heiligen in Israel, der dich herrlich gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Fremde werden deine Mauern bauen, und ihre Konige werden dirdienen. Denn in meinem Zorn habe ich dich geschlagen und in meiner Gnade erbarme ich mich uber dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Und deine Tore sollen stets often stehen, weder Tag noch Nacht zugeschlossen werden, daß der Heiden Macht zu dir gebracht, und ihre Konige herzugefuhret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Denn welche Heiden Oder Konigreiche dir nicht dienen wollen, die sollen umkommen, und die Heiden verwüstet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Die Herrlichkeit Libanons soil an dich kommen, Tannen, Buchen und Buchsbaum miteinander, zu schmucken den Ort meines Heiligtums; denn ich will die Statte meiner Füfte herrlich machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Es werden auch gebucktzu dir kommen, die dich unterdruckt haben; und alle, die dich gelastert haben, werden niederfallen zu deinen Füften und werden dich nennen eine Stadt des HERRN, ein Zion des Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Denn darum, daß du bist die Verlassene und Gehaftte gewesen, da niemand ging, will ich dich zur Pracht ewiglich machen und zur Freude fur und fur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'daß du sollst Milch von den Heiden saugen, und der Konige Bruste sollen dich saugen, auf daß du erfahrest, daß ich, der HERR, bin dein Heiland und ich, der Machtige in Jakob, bin dein Erloser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Ich will Gold anstatt des Erzes und Silber anstatt des Eisens bringen und Erz anstatt des Holzes und Eisen anstatt der Steine; und will machen, daß deine Vorsteher Frieden lehren sollen und deine Pfleger Gerechtigkeit predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Man soil keinen Frevel mehr horen in deinem Lande, noch Schaden Oder Verderben in deinen Grenzen, sondern deine Mauern sollen Heil und deine Tore Lob heilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Die Sonne soli nicht mehr des Tages dir scheinen, und der Glanz des Mondes soil dir nicht leuchten, sondern der HERR wird dein ewiges Licht und dein Gott wird dein Preis sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Deine Sonne wird nicht mehr untergehen, noch dein Mond den Schein verlieren, denn der HERR wird dein ewiges Licht sein, und die Tage deines Leides sollen ein Ende haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Und dein Volk soil eitel Gerechte sein und werden das Erdreich ewiglich besitzen, als die der Zweig meiner Pflanzung und ein Werk meiner Hande sind zum Preise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Aus dem Kleinsten sollen tausend werden und aus dem Geringsten ein machtig Volk. Ich, der HERR, will solches zu seiner Zeit eilend ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Der Geistdes Herrn HERRN ist uber mir, darum hat mich der HERR gesalbet. Er hat mich gesandt, den Elenden zu predigen, die zerbrochenen Herzen zu verbinden, zu predigen den Gefangenen eine Erledigung, den Gebundenen eine Offnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'zu predigen ein gnadiges Jahrdes HERRN und einen Tag der Rache unsers Gottes, zu trosten alle Traurigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'zu schaffen den Traurigen zu Zion, daß ihnen Schmuckfur Asche und Freudenol fur Traurigkeit und schone Kleider fur einen betrubten Geist gegeben werden, dafi sie genannt werden Baume der Gerechtigkeit, Pflanzen des HERRN, zum Preise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Sie werden die alten Wustungen bauen und was vorzeiten zerstoret ist, aufbringen; sie werden die verwusteten Stadte, so fur und fur zerstort gelegen sind, erneuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Fremde werden stehen und eure Herde weiden, und Auslander werden eure Ackerleute und Weingartner sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ihr aber sollt Priester des HERRN heüien, und man wird euch Diener unsers Gottes nennen; und werdet der Heiden Guter essen und uber ihrer Herrlichkeit euch rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Fur eure Schmach soil Zwiefaltiges kommen und fur die Schande sollen sie frohlich sein auf ihren Ackern. Denn sie sollen Zwiefaltiges besitzen in ihrem Lande; sie sollen ewige Freude haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Denn ich bin der HERR; der das Recht liebet, und hasse rauberische Brandopfer; und will schaffen, daß ihre Arbeit soil gewüi sein; und einen ewigen Bund will ich mit ihnen machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Und man soil ihren Samen kennen unterden Heiden und ihre Nachkommen unter den Volkern, daß, wer sie sehen wird, soil sie kennen, daü sie ein Same sind, gesegnet vom HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Ich freue mich im HERRN, und meine Seele ist frohlich in meinem Gott; denn er hat mich angezogen mit Kleidern des Heils und mit dem Rock der Gerechtigkeit gekleidet, wie einen Brautigam mit priesterlichem Schmuck gezieret, und wie eine Braut in ihrem Geschmeide bardet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Denn gleichwie Gewachs aus der Erde wachst und Same im Garten aufgeht, also wird Gerechtigkeit und Lob vor alien Heiden aufgehen aus dem Herrn HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Urn Zions willen, so will ich nicht schweigen, und urn Jerusalems willen, so will ich nicht innehalten, bis daß ihre Gerechtigkeit aufgehe wie ein Glanz, und ihr Heil entbrenne wie eine Fackel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'daß die Heiden sehen deine Gerechtigkeit und alle Konige deine Herrlichkeit; und du sollst mit einem neuen Namen genannt werden, welchen des HERRN Mund nennen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Und du wirst sein eine schone Krone in der Hand des HERRN und ein koniglicher Hut in der Hand deines Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Man soil dich nicht mehr die Verlassene noch dein Land eine Wustung heilien, sondern du sollst Meine Lust an ihr\" und dein Land \"Lieber Buhle” heilien; denn der HERR hat Lust an dir, und dein Land hat einen lieben Buhlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Denn wie ein lieber Buhle einen Buhlen liebhat, so werden dich deine Kinder liebhaben, und wie sich ein Brautigam freuet uber der Braut, so wird sich dein Gott fiber dich freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'O Jerusalem, ich will Wachter auf deine Mauern bestellen, die den ganzen Tag und die ganze Nacht nimmer stille schweigen sollen und die des HERRN gedenken sollen, auf daü bei euch kein Schweigen sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'und ihr von ihm nicht schweiget, bis daß Jerusalem gefertiget und gesetzt werde zum Lobe auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Der HERR hat geschworen bei seiner Rechten und bei dem Arm seiner Macht: Ich will dein Getreide nicht mehrdeinen Feinden zu essen geben, noch deinen Most, daran du gearbeitet hast, die Fremden trinken lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'sondern die, so es einsammeln, sollen\'s auch essen und den HERRN ruhmen, und die ihn einbringen, sollen ihn trinken in den Vorhofen meines Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Gehet hin, gehet hin durch die Tore, bereitet dem Volk den Weg; machet Bahn, machet Bahn, raumet die Steine auf; werfet ein Panier auf uber die Volker!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Siehe, der HERR lasset sich horen bis an der Welt Ende. Saget der Tochter Zion: Siehe, dein Heil kommt; siehe, sein Lohn ist bei ihm und seine Vergeltung ist vor ihm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Man wird sie nennen das heilige Volk, die Erlosten des HERRN; und dich wird man heilien die besuchte und unverlassene Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Wer ist der, so von Edom kommt, mit rotlichen Kleidern von Bazra, der so geschmückt ist in seinen Kleidern und einhertritt in seiner groüen Kraft? Ich bin\'s, der Gerechtigkeit lehret und ein Meister bin zu helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Warum ist denn dein Gewand so rotfarb und dein Kleid wie eines Keltertreters?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Ich trete die Kelter allein, und ist niemand unter den Volkern mit mir. Ich habe sie gekeltert in meinem Zorn und zertreten in meinem Grimm. Daher ist ihr Vermogen auf meine Kleider gespritzt, und ich habe all mein Gewand besudelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Denn ich habe einen Tag der Rache mir vorgenommen; das Jahr, die Meinen zu erlosen, ist kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Denn ich sah mich urn, und da war kein Heifer, und ich war im Schrecken, und niemand enthielt mich, sondern mein Arm muftte mir helfen, und mein Zorn enthielt mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Darum habe ich die Volker zertreten in meinem Zorn und habe sie trunken gemacht in meinem Grimm und ihr Vermogen zu Boden gestoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Ich will der Gute des HERRN gedenken und des Lobes des HERRN in allem, das uns der HERR getan hat, und des groften Guts an dem Hause Israel, das er ihnen getan hat durch seine Barmherzigkeit und grofte Gute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Denn er sprach: Sie sind ja mein Volk, Kinder, die nicht falsch sind. Darum war er ihr Heiland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Wer sie angstete, der angstete ihn auch; und der Engel, so vor ihm ist, half ihnen. Er erlosete sie, darum daß er sie liebete und ihrer schonete. Er nahm sie auf und trug sie allezeit von alters her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Aber sie erbitterten und entrüsteten seinen Heiligen Geist; darum ward er ihr Feind und stritt wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Und er gedachte wieder an die vorige Zeit, an den Mose, so unter seinem Volk war. Wo ist denn nun, der sie aus dem Meer fuhrete, samt dem Hirten seiner Herde? Wo ist, der seinen Heiligen Geist unter sie gab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'der Mose bei der rechten Hand fuhrete durch seinen herrlichen Arm, der die Wasser trennete vor ihnen her, auf daß er ihm einen ewigen Namen machte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'der sie fuhrete durch die Tiefe, wie die Rosse in der Wuste, die nicht straucheln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'wie das Vieh, so ins Feld hinabgehet, welches der Odem des HERRN treibet? Also hast du auch dein Volk gefuhret, auf daß du dir einen herrlichen Namen machtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'So schaue nun vom Himmel und siehe herab von deiner heiligen herrlichen Wohnung. Wo ist nun dein Eifer, deine Macht? Deine grofie herzliche Barmherzigkeit halt sich hart gegen mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Bistdu doch unser Vater. Denn Abraham weili von uns nicht, und Israel kennet uns nicht. Du aber, HERR, bist unser Vater und unser Erloser; von alters her ist das dein Name.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Warum lassestdu uns, HERR, irren von deinen Wegen und unser Herz verstocken, dati wir dich nicht furchten? Kehre wieder urn deiner Knechte willen, urn der Stamme willen deines Erbes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Sie besitzen dein heiliges Volk schier gar; deine Widersacher zertreten dein Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Wir sind gleich wie vorhin, da du nicht uber uns herrschetest, und wir nicht nach deinem Namen genanntwaren. Ach, dati du den Himmel zerrissest und fuhrest herab, dati die Berge vor dir zerflossen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'wie ein heifi Wasser vom heftigen Feuer versiedet, daß dein Name kund würde unter deinen Feinden, und die Heiden vor dir zittern müftten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'durch die Wunder, die du tust, deren man sich nicht versiehet, da du herabfuhrest und die Berge vor dir zerflossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Wie denn von der Welt her nicht gehoret ist, noch mit Ohren gehoret, hat auch kein Auge gesehen, ohne dich, Gott, was denen geschieht, die auf ihn harren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Du begegnetest den Frohlichen und denen, so Gerechtigkeit ubeten und auf deinen Wegen dein gedachten. Siehe, du zumetest wohl, da wir sundigten und lange drinnen blieben; uns ward aberdennoch geholfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Aber nun sind wir allesamt wie die Unreinen, und alle unsere Gerechtigkeit ist wie ein unflatig Kleid. Wir sind alle verwelket wie die Blatter, und unsere Sünden führen uns dahin wie ein Wind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Niemand ruft deinen Namen an Oder macht sich auf, dafi er dich halte; denn du verbirgest dein Angesicht vor uns und lassest uns in unsern Sünden verschmachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Aber nun, HERR, du bist unser Vater, wir sind ton; du bist unser Topfer, und wir alle sind deiner Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'HERR, zurne nicht zu sehr und denke nicht ewig der Sunden! Siehe doch das an, daß wir alle dein Volk sind!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Die Stadte deines Heiligtums sind zur Wuste worden; Zion ist zur Wuste worden, Jerusalem liegt zerstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Das Haus unserer Heiligkeit und Herrlichkeit, darin dich unsere Vater gelobt haben, ist mit Feuer verbrannt, und alles, was wir Schones hatten, ist zuschanden gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'HERR, willstdu so hart sein zu solchem und schweigen und uns so sehr niederschlagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Ich werde gesucht von denen, die nicht nach mir fragten; ich werde funden von denen, die mich nicht suchten, und zu den Heiden, die meinen Namen nicht anriefen, sage ich: Hie bin ich, hie bin ich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Denn ich recke meine Hande aus den ganzen Tag zu einem ungehorsamen Volk, das seinen Gedanken nachwandelt auf einem Wege, der nicht gut ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Ein Volk, das mich entrustet, ist immer vor meinem Angesicht, opfert in den Garten und rauchert auf den Ziegelsteinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'wohnet unter den Grabern und halt sich in den Hohlen, fressen Schweinefleisch und haben Greuelsuppen in ihren Topfen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'und sprechen: Bleibe daheim und ruhre mich nicht; denn ich soli dich heiligen. Solche sollen ein Rauch werden in meinem Zorn, ein Feuer, das den ganzen Tag brenne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Siehe, es stehet vor mir geschrieben: Ich will nicht schweigen, sondern bezahlen; ja, ich will sie in ihren Busen bezahlen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'beide, ihre Missetat und ihrer Vater Missetat, miteinander, spricht der HERR, die auf den Bergen gerauchert und mich auf den Hugeln geschandet haben; ich will ihnen zumessen ihr voriges Tun in ihren Busen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'So spricht der HERR: Gleich als wenn man Most in einer Traube findet und spricht: Verderbe es nicht, denn es ist ein Segen drinnen! also will ich urn meiner Knechte willen tun, daß ich es nicht alles verderbe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'sondern will aus Jakob Samen wachsen lassen und aus Juda, der meinen Berg besitze; denn meine Auserwahlten sollen ihn besitzen, und meine Knechte sollen daselbstwohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Und Saron soli ein Haus fur die Herde und das Tal Achor soil zum Viehlager werden meinem Volk, das mich suchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Aber ihr, die ihr den HERRN verlasset und meines heiligen Berges vergesset und richtet dem Gad einen Tisch und schenket voll ein vom Trankopfer dem Meni,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'wohlan, ich will euch zahlen zum Schwert, daß ihr euch alle bucken müsset zur Schlacht, darum daß ich rief und ihr antwortetet nicht, daß ich redete und ihr horetet nicht, sondern tatet, was mir übel gefiel, und erwahletet, das mir nicht gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Darum spricht der Herr HERR also: Siehe, meine Knechte sollen essen, ihr aber sollt hungern; siehe, meine Knechte sollen trinken, ihr aber sollt dursten; siehe, meine Knechte sollen frohlich sein, ihr aber sollt zuschanden werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'siehe, meine Knechte solien vor gutem Mut jauchzen, ihr aber sollt vor Herzeleid schreien und vor Jammer heulen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'und sollt euren Namen lassen meinen Auserwahlten zum Schwur; und der Herr HERR wird dich toten und seine Knechte mit einem andern Namen nennen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'daß, welchersich segnen wird auf Erden, der wird sich in dem rechten Gott segnen, und welcher schworen wird auf Erden, der wird bei dem rechten Gott schworen; denn der vorigen Angst ist vergessen, und sind von meinen Augen verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Denn siehe, ich will einen neuen Himmel und neue Erde schaffen, daß man der vorigen nicht mehr gedenken wird noch zu Herzen nehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'sondern sie werden sich ewiglich freuen und frohlich sein uber dem, das ich schaffe. Denn siehe, ich will Jerusalem schaffen zur Wonne und ihr Volk zur Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Und ich will frohlich sein uber Jerusalem und mich freuen fiber mein Volk; und soil nicht mehr drinnen gehoret werden die Stimme des Weinens noch die Stimme des Klagens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Es sollen nicht mehr da sein Kinder, die ihre Tage nicht erreichen, Oder Alte, die ihre Jahre nicht erfullen, sondern die Knaben von hundert Jahren sollen sterben, und die Sunder von hundert Jahren sollen verflucht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Sie werden Hauser bauen und bewohnen; sie werden Weinberge pflanzen und derselbigen Fruchte essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Sie sollen nicht bauen, das ein anderer bewohne, und nicht pflanzen; das ein anderer esse. Denn die Tage meines Volks werden sein wie die Tage eines Baumes, und das Werk ihrer Hande wird alt werden bei meinen Auserwahlten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Sie sollen nicht umsonst arbeiten noch unzeitige Geburt gebaren, denn sie sind der Same der Gesegneten des HERRN und ihre Nachkommen mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Und soil geschehen, ehe sie rufen, will ich antworten; wenn sie noch reden, will ich horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wolf und Lamm sollen weiden zugleich; der Lowe wird Stroh essen wie ein Rind, und die Schlange soil Erde essen. Sie werden nicht schaden noch verderben auf meinem ganzen heiligen Berge, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'So spricht der HERR: Der Himmel ist mein Stuhl und die Erde meine Fuftbank; was ist\'s denn fur ein Haus, das ihr mir bauen wollt, Oder welches ist die Statte, da ich ruhen soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Meine Hand hat alles gemacht, was da ist, spricht der HERR. Ich sehe aber an den Elenden und der zerbrochenes Geistes ist und der sich fürchtet vor meinem Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Denn wer einen Ochsen schlachtet, ist eben, als der einen Mann erschluge. Wer ein Schaf opfert, ist, als der einem Hund den Hals brache. Wer Speisopfer bringt, ist, als der Saublut opfert. Wer des Weihrauchs gedenkt, ist, als der das Unrecht lobet. Solches erwahlen sie in ihren Wegen, und ihre Seele hat Gefallen an ihren Greueln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Darum will ich auch erwahlen, das sie verspotten; und was sie scheuen, will ich uber sie kommen lassen, darum daß ich rief, und niemand antwortete, daß ich redete, und sie horeten nicht, und taten, was mir übel gefiel, und erwahleten, das mir nicht gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Horet des HERRN Wort, die ihr euch furchtet vor seinem Wort: Eure Bruder, die euch hassen und sondern euch ab um meines Namens willen, sprechen: Lasset sehen, wie herrlich der HERR sei; lasset ihn erscheinen zu eurer Freude! die sollen zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Denn man wird horen eine Stimme des Getümmels in der Stadt, eine Stimme vom Tempel, eine Stimme des HERRN, der seine Feinde bezahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Sie gebieret, ehe ihrwehe wird; sie ist genesen eines Knaben, ehe denn ihr Kindesnot kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Wer hat solches je gehort? Wer hat solches je gesehen? Kann auch, ehe denn ein Land die Wehe kriegt, ein Volk zugleich geboren werden? Nun hat doch ja Zion ihre Kinder ohne die Wehe geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Sollte ich andere lassen die Mutter brechen und selbst nicht auch gebaren? spricht der HERR. Sollte ich andere lassen gebaren und selbst verschlossen sein? spricht dein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Freuet euch mit Jerusalem und seid frohlich uber sie, alle, die ihr sie liebhabt! Freuet euch mit ihr, alle, die ihr uber sie traurig gewesen seid!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Denn dafur sollt ihr saugen und satt werden von den Brusten ihres Trostes; ihr sollt dafur saugen und euch ergotzen von der Fulle ihrer Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Denn also spricht der HERR: Siehe, ich breite aus den Frieden bei ihr wie einen Strom und die Herrlichkeit der Heiden wie einen ergossenen Bach; da werdet ihr saugen. Ihr sollt auf der Seite getragen werden, und auf den Knieen wird man euch freundlich halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Ich will euch trosten, wie einen seine Mutter trostet; ja, ihr sollt an Jerusalem ergotzet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Ihr werdet es sehen, und euer Herz wird sich freuen, und euer Gebein soil grünen wie Gras. Da wird man erkennen die Hand des HERRN an seinen Knechten und den Zorn an seinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Denn siehe, der HERR wird kommen mit Feuer und seine Wagen wie ein Wetter, daß er vergelte im Grimm seines Zorns, und sein Schelten in Feuerflammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Denn der HERR wird durchs Feuer richten und durch sein Schwert alles Fleisch; und der Getoteten vom HERRN wird viel sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Die sich heiligen und reinigen in den Garten, einer hie, der andere da, und essen Schweinefleisch, Greuel und Mause, sollen geraffet werden miteinander, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Denn ich will kommen und sammeln ihre Werke und Gedanken samt alien Heiden und Zungen, daß sie kommen und sehen meine Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Und ich will ein Zeichen unter sie geben und ihrer etliche, die errettet sind, senden zu den Heiden am Meer, gen Phul und Lud, zu den Bogenschützen, gen Thubal und Javan und in die Feme zu den Inseln, da man nichts von mir gehort hat, und die meine Herrlichkeit nicht gesehen haben, und sollen meine Herrlichkeit unter den Heiden verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Und werden alle eure Bruder aus alien Heiden herzubringen dem HERRN zum Speisopfer, auf Rossen und Wagen, auf Sanften, auf Maulern und Laufern, gen Jerusalem zu meinem heiligen Berge, spricht der HERR, gleichwie die Kinder Israel Speisopfer in reinem Gefaft bringen zum Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Und ich will aus denselbigen nehmen Priester und Leviten, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Denn gleichwie der neue Himmel und die neue Erde, so ich mache, vor mir stehen, spricht der HERR, also soli auch euer Same und Name stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Und alles Fleisch wird einen Monden nach dem andern und einen Sabbat nach dem andern kommen, anzubeten vor mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Und sie werden hinausgehen und schauen die Leichname der Leute, die an mir mifthandelt haben; denn ihr Wurm wird nicht sterben, und ihr Feuer wird nicht verloschen, und werden allem Fleisch ein Greuel sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Dies sind die Geschichten Jeremias, des Sohns Hilkias, aus den Priestern zu Anathoth, im Lande Benjamin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'zu welchem geschah das Wort des HERRN zur Zeit Josias, des Sohns Amons, des Konigs Judas, im dreizehnten Jahr seines Konigreichs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'und hernach zur Zeit des Konigs Judas Jojakim, des Sohns Josias, bis ans Ende des elften Jahrs Zedekias, des Sohns Josias, des Konigs Judas, bis aufs Gefangnis Jerusalems im fünften Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Ich kannte dich, ehe denn ich dich in Mutterleibe bereitete, und sonderte dich aus, ehe denn du von der Mutter geboren wurdest, und stellete dich zum Propheten unter die Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Ich aber sprach: Ach, Herr HERR, ich tauge nicht zu predigen, denn ich bin zu jung!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Der HERR sprach aber zu mir: Sage nicht: Ich bin zu jung; sondern du sollst gehen, wohin ich dich sende, und predigen, was ich dich heifie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Furchte dich nicht vor ihnen; denn ich bin bei dir und will dich erretten, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Und der HERR reckte seine Hand aus und ruhrete meinen Mund und sprach zu mir: Siehe, ich lege meine Worte in deinen Mund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Siehe, ich setzedich heute dieses Tages uber Volker und Konigreiche, daß du ausreilien, zerbrechen, verstoren und verderben sollst und bauen und pflanzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Und es geschah des HERRN Wortzu mir und sprach: Jeremia, was siehest du? Ich sprach: Ich sehe einen wackern Stab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Und der HERR sprach zu mir: Du hast recht gesehen; denn ich will wacker sein uber mein Wort, daß ich\'s tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Und es geschah des HERRN Wort zum andernmal zu mir und sprach: Was siehest du? Ich sprach: Ich sehe einen heilien siedenden Topf von Mitternacht her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Und der HERR sprach zu mir: Von Mitternacht wird das Unglück ausbrechen uber alle, die im Lande wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Denn siehe, ich will rufen alle Fürsten in den Konigreichen gegen Mitternacht, spricht der HERR, daß sie kommen sollen und ihre Stühle setzen vor die Tore zu Jerusalem und rings urn die Mauern her und vor alle Stadte Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Und ich will das Recht lassen über sie gehen urn aller ihrer Bosheit willen, daß sie mich verlassen und rauchern andern Gottern und beten an ihrer Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'So begürte nun deine Lenden und mache dich auf und predige ihnen alles, was ich dich heilie! Furchte dich nicht vor ihnen, als sollte ich dich abschrecken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Denn ich will dich heute zurfesten Stadt, zur eisernen Saule, zur ehernen Mauer machen im ganzen Lande wider die Konige Judas, wider ihre Fursten, wider ihre Priester, wider das Volk im Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'daß, wenn sie gleich wider dich streiten, dennoch nicht sollen wider dich siegen; denn ich bin bei dir, spricht der HERR, daß ich dich errette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Gehe hin und predige offentlich zu Jerusalem und sprich: So spricht der HERR: Ich gedenke, da du eine freundliche junge Dime und eine liebe Braut warest, da du mirfolgtest in der Wüste, im Lande, da man nichts saet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'da Israel des HERRN eigen war und seine erste Frucht. Wer sie fressen wollte, mufite Schuld haben und Ungluck über ihn kommen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Horet des HERRN Wort, ihr vom Hause Jakob und alle Geschlechter vom Hause Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So spricht der HERR: Was haben doch eure Vater Fehls an mir gehabt, daß sie von mir wichen und hingen an den unnützen Gotzen, da sie doch nichts erlangeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'und dachten nie keinmal: Wo istder HERR, der uns aus Agyptenland führete und leitete uns in der Wüste, im wilden, ungebahnten Lande, im dürren, und finstern Lande, im Lande, da niemand wandelte, noch kein Mensch wohnete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Und ich brachte euch in ein gut Land, daß ihraliet seine Früchte und Güter Und da ihr hineinkamet, verunreinigtet ihr mein Land und machtet mir mein Erbe zum Greuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Die Priester gedachten nicht: Wo ist der HERR? und die Gelehrten achteten mein nicht, und die Hirten führeten die Leute von mir, und die Propheten weissagten vom Baal und hingen an den unnützen Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Ich muli mich immer mit euch und mit euren Kindeskindern schelten, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Gehet hin in die Inseln Chittim und schauet und sendet in Kedar und merket mit Fleili und schauet, ob\'s daselbst so zugehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'ob die Heiden ihre Gotter andern, wiewohl sie doch nicht Gotter sind? Und mein Volk hat doch seine Herrlichkeit verandert urn einen unnützen Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Sollte sich doch der Himmel davor entsetzen, erschrecken und sehr erbeben, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Denn mein Volk tut eine zwiefache Sünde: mich, die lebendige Quelle, verlassen sie und machen sich hie und da ausgehauene Brunnen, die doch locherig sind und kein Wasser geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ist denn Israel ein Knecht Oder leibeigen, daß er jedermanns Raub sein muli?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Denn die Lowen brullen uber ihn und schreien und verwüsten sein Land und verbrennen seine Stadte, daß niemand drinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Dazu so zerschlagen die von Noph und Thachpanhes dir den Kopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Solches machst du dir selbst, daß du den HERRN, deinen Gott, verlassest, so oft er dich den rechten Weg leiten will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Was hilft\'s dir, daß du nach Agypten ziehst und willst des Wassers Sihor trinken? Und was hilft\'s dir, daß du gen Assyrien ziehst und willst des Wassers Phrath trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Es ist deiner Bosheit Schuld, daß du so gestaupet wirst, und deines Ungehorsams, da(S du so gestraft wirst: Also mußt du inne werden und erfahren, was fur Jammer und Herzeleid bringet, den HERRN, deinen Gott, verlassen und ihn nicht furchten, spricht der Herr HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Denn du hast immerdar dein Joch zerbrochen und deine Bande zerrissen und gesagt: Ich will nicht so unterworfen sein, sondern auf alien hohen Hügeln und unter alien grünen Baumen liefest du der Hurerei nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Ich aber hatte dich gepflanzt zu einem süißen Weinstock, einen ganz rechtschaffenen Samen. Wie bist du mir denn geraten zu einem bittern, wilden Weinstock?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Und wenn du dich gleich mit Lauge wuschest und nahmest viel Seife dazu, so gleißt doch deine Untugend desto mehr vor mir, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Wie darfst du denn sagen: Ich bin nicht unrein, ich hange nicht an Baalim? Siehe an, wie du es treibest im Tal, und bedenke, wie du es ausgerichtet hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Du laufst umher wie eine Kamelin in der Brunst, und wie ein Wild in der Wuste pflegt, wenn es vor groißer Brunst lechzet und lauft, daß niemand aufhalten kann. Wer es wissen will, darf nicht weit laufen; am Feiertage sieht man es wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Lieber, halte doch und lauf dich nicht so hellig! Aber du sprichst: Das lasse ich; ich muli mit den Fremden buhlen und ihnen nachlaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Wie ein Dieb zuschanden wird, wenn er ergriffen wird, also wird das Haus Israel zuschanden werden samt ihren Konigen, Fursten, Priestern und Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'die zum Holz sagen: Du bist mein Vater; und zum Stein: Du hast mich gezeuget. Denn sie kehren mir den Rücken zu und nicht das Angesicht. Aber wenn die Not hergehet, sprechen sie: Auf, und hilf uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Wo sind aber denn deine Gotter, die du dir gemacht hast? Heüi sie aufstehen; laft sehen, ob sie dir helfen konnen in der Not! Denn so manche Stadt, so manchen Gott hast du, Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Was wolit ihr noch recht haben wider mich? Ihr seid alle von mir abgefallen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Alle Schlage sind verloren an euren Kindern, sie lassen sich doch nicht ziehen. Denn euer Schwert frißt gleichwohl eure Propheten wie ein wutiger Lowe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Du bose Art; merke auf des HERRN Wort! Bin ich denn Israel eine Wuste Oder odes Land? Warum spricht denn mein Volk: Wir sind die Herren und müssen dir nicht nachlaufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vergisset doch eine Jungfrau ihres Schmucks nicht noch eine Braut ihres Schleiers; aber mein Volk vergisset mein ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Was schmuckest du viel dein Tun, dafi ich dir gnadig sein soil? Unter solchem Schein treibest du je mehr und mehr Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Uber das findet man Blut der armen und unschuldigen Seelen bei dir an alien Orten, und ist nicht heimlich, sondern offenbar an denselben Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Noch sprichst du: Ich bin unschuldig; erwende seinen Zorn von mir! Siehe, ich will mit dir rechten, daß du sprichst: Ich habe nicht gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Wie weichst du doch so gerne und fallst jetzt dahin, jetzt hieher! Aber du wirst an Agypten zuschanden werden, wie du an Assyrien zuschanden worden bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Denn du mulit von dannen auch wegziehen und deine Hande liberdem Hauptzusammenschlagen; denn der HERR wird deine Hoffnung fehlen lassen und wird dir bei ihnen nichts gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Und spricht: Wenn sich ein Mann von seinem Weibe scheiden lasset, und sie zeucht von ihm und nimmt einen andern Mann, darf er sie auch wieder annehmen? Ist\'s nicht also, daß das Land verunreiniget wurde? Du aber hast mit vielen Buhlern gehuret; doch komm wieder zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Hebe deine Augen auf zu den Hohen und siehe, wie du allenthalben Hurerei treibest. An den Stralien sitzest du und wartest auf sie, wie ein Araber in der Wuste, und verunreinigest das Land mit deiner Hurerei und Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Darum muli auch der Fruhregen ausbleiben und kein Spatregen kommen. Du hast eine Hurenstirn, du willst dich nicht mehr schamen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'und schreiest gleichwohl zu mir: Lieber Vater, du Meister meiner Jugend!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Willst du denn ewiglich zurnen und nicht vom Grimm lassen? Siehe, du lehrest und tust Boses und lassest dir nicht Steuern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Und der HERR sprach zu mir, zur Zeit des Konigs Josia: Hastdu auch gesehen, was Israel, die Abtrunnige, tat? Sie ging hin auf alle hohen Berge und unter alle grünen Baume und trieb daselbst Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Und ich sprach, da sie solches alles getan hatte: Bekehre dich zu mir! Aber sie bekehrete sich nicht. Und obwohl ihre Schwester Juda, die Verstockte, gesehen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'wie ich der abtrünnigen Israel Ehebruch gestraft und sie verlassen und ihr einen Scheidebrief gegeben habe, noch furchtet sich ihre Schwester, die verstockte Juda, nicht, sondern gehet hin und treibet auch Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Und von dem Geschrei ihrer Hurerei ist das Land verunreiniget; denn sie treibet Ehebruch mit Steinen und Holz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Und in diesem allem bekehret sich die verstockte Juda, ihre Schwester, nicht zu mir von ganzem Herzen, sondern heuchelt also, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Und der HERR sprach zu mir: Die abtrunnige Israel ist fromm gegen die verstockte Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Gehe hin und predige gegen der Mittemacht also und sprich: Kehre wieder, du abtrunnige Israel, spricht der HERR, so will ich mein Antlitz nicht gegen euch verstellen; denn ich bin barmherzig, spricht der HERR, und will nicht ewiglich zurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Allein erkenne deine Missetat, da(5 du wider den HERRN, deinen Gott, gesundiget hast und hin und wieder gelaufen zu den fremden Gottern unter alien grünen Baumen und habt meiner Stimme nicht gehorchet, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Bekehret euch, ihr abtrunnigen Kinder, spricht der HERR; denn ich will euch mir vertrauen und will euch holen, dati einer eine ganze Stadt und zween ein ganz Land führen sollen; und will euch bringen gen Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Und will euch Hirten geben nach meinem Herzen, die euch weiden sollen mit Lehre und Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Und soil geschehen, wenn ihr gewachsen und euer viel worden ist im Lande, so soli man, spricht der HERR, zur selbigen Zeit nicht mehr sagen von der Bundeslade des HERRN, auch derselbigen nicht mehr gedenken, noch davon predigen, noch sie besuchen, noch daselbst mehr opfern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'sondern zur selbigen Zeit wird man Jerusalem heiften: Des HERRN Thron; und werden sich dahin sammeln alle Heiden urn des HERRN Namens willen zu Jerusalem und werden nicht mehr wandeln nach den Gedanken ihres bosen Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Zu der Zeit wird das Haus Juda gehen zum Haus Israel und werden miteinander kommen von Mittemacht ins Land, das ich euren Vatern zum Erbe gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Und ich sage dirzu: Wie will ich dir so viel Kinder geben und das liebe Land, das schone Erbe, namlich das Heer der Heiden! Und ich sage dir zu: Du wirst alsdann mich nennen: Lieber Vater! und nicht von mir weichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Aber das Haus Israel achtet mein nichts, gleichwie ein Weib ihren Buhlen nicht mehr achtet, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Darum wird man ein klaglich Heulen und Weinen der Kinder Israel horen auf den Hohen, dafur daß sie übel getan und des HERRN, ihres Gottes, vergessen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'So kehret nun wieder, ihr abtrunnigen Kinder, so will ich euch heilen von eurem Ungehorsam. Siehe, wir kommen zu dir; denn du bist der HERR, unser Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Wahrlich, es ist eitel Betrug mit Hugeln und mit alien Bergen. Wahrlich, es hat Israel keine Hilfe denn am HERRN, unserm Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Und unserer Vater Arbeit, die wir von Jugend auf gehalten haben, müsse mit Schanden untergehen samt ihren Schafen, Rindern, Kindern und Tochtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Denn darauf wir uns verlieften, das ist uns jetzt eitel Schande, und des wir uns trosteten, des müssen wir uns jetzt schamen. Denn wir sundigten damit wider den HERRN, unsern Gott, beide, wir und unsere Vater, von unserer Jugend auf, auch bis auf diesen heutigen Tag, und gehorchten nicht der Stimme des HERRN, unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Willst du dich, Israel, bekehren, spricht der HERR, so bekehre dich zu mir. Und so du deine Greuel wegtust von meinem Angesicht, so sollst du nicht vertrieben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Alsdann wirst du ohne Heuchelei recht und heilig schworen: So wahr der HERR lebet! Und die Heiden werden in ihm gesegnet werden und sich sein rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Denn so spricht der HERR zu denen in Juda und zu Jerusalem: Pflüget ein Neues und saet nicht unter die Hecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Beschneidet euch dem HERRN und tut weg die Vorhaut eures Herzens, ihr Manner in Juda und ihr Leute zu Jerusalem, auf daß nicht mein Grimm ausfahre wie Feuer und brenne, dati niemand loschen moge, urn eurer Bosheit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Ja, dann verkundiget in Juda und schreiet laut zu Jerusalem und sprechet: Blaset die Trommeten im Lande! Rufet mit voller Stimme und sprechet: Sammelt euch und lasset uns in die festen Stadte ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Werfet zu Zion ein Panier auf; haufet euch und saumet nicht! Denn ich bringe ein Unglück herzu von Mittemacht und einen groften Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Es fahret daher der Lowe aus seiner Hecke, und der Verstorer der Heiden zeucht einher aus seinem Ort, daß er dein Land verwuste und deine Stadte ausbrenne, daß niemand drinnen wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Darum ziehet Sacke an, klaget und heulet; denn der grimmige Zorn des HERRN will nicht aufhoren von uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Zu der Zeit, spricht der HERR, wird dem Konige und den Fursten das Herz entfallen; die Priester werden versturzt und die Propheten erschrocken sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Ich aber sprach: Ach, Herr HERR, du hast\'s diesem Volk und Jerusalem weit fehlen lassen, da sie sagten: Es wird Friede bei euch sein, so doch das Schwert bis an die Seele reicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Zur selbigen Zeit wird man diesem Volk und Jerusalem sagen: Es kommt ein dürrer Wind uber dem Gebirge her, als aus der Wuste, des Weges zu der Tochter meines Volks zu, nicht zu worfeln noch zu schwingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Ja, ein Wind kommt, der ihnen zu stark sein wird; da will ich denn auch mit ihnen rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Siehe, erfahret daherwie Wolken, und seine Wagen sind wie ein Sturmwind, seine Rosse sind schneller denn Adler. Weh uns, wir müssen verstoret werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Sowasche nun, Jerusalem, dein Herzvon der Bosheit, auf daß dir geholfen werde. Wie lange wollen bei dir bleiben die leidigen Lehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Denn es kommt ein Geschrei von Dan her und eine bose Botschaft vom Gebirge Ephraim her,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'wie die Heiden ruhmen. Und es ist bis gen Jerusalem erschollen, dad Hüter kommen aus fernen Landen und werden schreien wider die Stadte Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Sie werden sie rings umher belagern wie die Hüter auf dem Felde; denn sie haben mich erzurnet, sprichtder HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Das hast du zu Lohn fur dein Wesen und dein Tun. Dann wird dein Herz fuhlen, wie deine Bosheit so groß ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Wie ist mirso herzlich weh! Mein Herzpocht mir im Leibe und habe keine Ruhe; denn meine Seele hort der Posaunen Hall und eine Feldschlacht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'und ein Mordgeschrei uber das andere; denn das ganze Land wird verheeret, plotzlich werden meine Hutten und meine Gezelte verstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Wie lange soil ich doch das Panier sehen und der Posaunen Hall horen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Aber mein Volk ist toll und glauben mir nicht; toricht sind sie und achten\'s nicht. Weise sind sie genug, libels zu tun; aber wohltun wolien sie nicht lernen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Ich schauete das Land an, siehe, das war wuste und ode, und den Himmel, und er war finster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Ich sah die Berge an, und siehe, die bebeten, und alle Hugel zitterten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Ich sah, und siehe, da war kein Mensch, und alles Gevogel unter dem Himmel war weggeflogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Ich sah, und siehe, das Baufeld war eine Wuste, und alle Stadte drinnen waren zerbrochen vor dem HERRN und vorseinem grimmigen Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Denn so spricht der HERR: Das ganze Land soil wuste werden, und will\'s doch nicht gar aus machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Darum wird das Land betrubt und der Himmel droben traurig sein; denn ich hab\'s geredet, ich hab\'s beschlossen und soil mich nicht reuen, will auch nicht davon ablassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Alle Stadte werden vor dem Geschrei der Reiter und Schützen fliehen und in die dicken Walder laufen und in die Felsen kriechen; alle Stadte werden verlassen stehen, dafi niemand drinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Was willst du alsdann tun, du Verstorte? Wenn du dich schon mit Purpur kleiden und mit guldenen Kleinoden schmucken und dein Angesicht schminken wurdest, so schmuckest du dich doch vergeblich; denn die dir jetzt hofieren, werden dich verachten, sie werden dir nach dem Leben trachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Denn ich hore ein Geschrei als einer Gebarerin, eine Angst als einer, die in den ersten Kindesnoten ist, ein Geschrei der Tochter Zion, die da klagt und die Hande auswirft: Ach, wehe mir, ich muß schier vergehen vor dem Wurgen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Gehet durch die Gassen zu Jerusalem und schauet und erfahret und suchet auf ihrer Straße, ob ihr jemand findet, der recht tue und nach dem Glauben frage, so will ich ihr gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Und wenn sie schon sprechen: Bei dem lebendigen Gotti so schworen sie doch falsch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'HERR, deine Augen sehen nach dem Glauben. Du schlagest sie, aber sie fühlen\'s nicht; du plagest sie, aber sie bessern sich nicht. Sie haben ein harter Angesicht denn ein Fels und wolien sich nicht bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Ich dachte aber: Wohlan, der arme Haufe ist unverstandig, weifi nichts urn des HERRN Weg und urn ihres Gottes Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Ich will zu den Gewaltigen gehen und mit ihnen reden, dieselbigen werden urn des HERRN Weg und ihres Gottes Recht wissen; aber dieselbigen allesamt hatten das Joch zerbrochen und die Seile zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Darum wird sie auch der Lowe, der aus dem Waide kommt, zerreifien, und der Wolf aus der Wuste wird sie verderben, und der Pardel wird auf ihre Stadte lauern; alle, die daselbst herausgehen, wird er fressen. Denn ihrer Sunden sind zu viel, und bieiben verstockt in ihrem Ungehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Wie soil ich dir denn gnadig sein, weil mich deine Kinder verlassen und schworen bei dem, der nicht Gott ist? Und nun ich sie gefullet habe, treiben sie Ehebruch und laufen ins Hurenhaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Ein jeglicher wiehert nach seines Nachsten Weibe, wie die vollen, müßigen Hengste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Und ich sollte sie urn solches nicht heimsuchen? spricht der HERR; und meine Seele sollte sich nicht rachen an solchem Volk, wie dies ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Sturmet ihre Mauern und werfet sie urn und macht es nicht gar aus! Fuhret ihre Reben weg; denn sie sind nicht des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'sondern sie verachten mich, beide, das Haus Israel und das Haus Juda, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Sie verleugnen den HERRN und sprechen: Das ist er nicht, und so ubel wird es uns nicht gehen, Schwert und Hunger werden wir nicht sehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'ja, die Propheten sind Wascher und haben auch Gottes Wort nicht; es gehe uber sie selbst also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Darum spricht der HERR, der Gott Zebaoth: Weil ihr solche Rede treibet, siehe, so will ich meine Worte in deinem Munde zu Feuer machen und dies Volk zu Holz, und soil sie verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Siehe, ich will uber euch vom Hause Israel, spricht der HERR, ein Volk von feme bringen, ein machtig Volk, die das erste Volk gewesen sind, ein Volk, des Sprache du nicht verstehest und nicht vernehmen kannst, was sie reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Seine Kocher sind offene Graber, es sind eitel Riesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Sie werden deine Ernte und dein Brot verzehren, sie werden deine Sohne und Tochter fressen, sie werden deine Schafe und Rinderverschlingen, sie werden deine Weinstocke und Feigenbaume verzehren; deine festen Stadte, darauf du dich verlassest, werden sie mit dem Schwert verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Und ich will\'s, spricht der HERR, zur selbigen Zeit nicht gar aus machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Und ob sie wurden sagen: Warum tut uns der HERR, unser Gott, solches alles? sollst du ihnen antworten: Wie ihr mich, verlassen und fremden Gottern dienet in eurem eigenen Lande, also sollt ihr auch Fremden dienen in einem Lande, das nicht euer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Solches sollt ihr verkundigen im Hause Jakob und predigen in Juda und sprechen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Horet zu, ihr tolles Volk, das keinen Verstand hat, die da Augen haben und sehen nicht, Ohren haben und horen nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Wollt ihr mich nicht furchten, spricht der HERR, und vor mir nicht erschrecken? Der ich dem Meer den Sand zum Ufer setze, darin es allezeit bleiben muft, daruber es nicht gehen muft; und ob es schon wallet, so vermag es doch nichts, und ob seine Wellen schon toben, so müssen sie doch nicht daruberfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Aber dies Volk hat ein abtrunniges, ungehorsames Herz, bleiben abtrunnig und gehen immerfort weg');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'und sprechen nicht einmal in ihrem Herzen: Lasset uns doch den HERRN, unsern Gott, furchten, der uns Fruhregen und Spatregen zu rechter Zeit gibt und uns die Ernte treulich und jahrlich behutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Aber eure Missetaten hindern solches und eure Sunden wenden solch Gut von euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Denn man findet unter meinem Volk Gottlose, die den Leuten nachstellen und Fallen zurichten, sie zu fangen, wie die Vogler tun mit Kloben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Und ihre Hauser sind voller Tucke, wie ein Vogelbauer voller Lockvogel ist. Daher werden sie gewaltig und reich, fett und glatt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Sie gehen mit bosen Stricken um; sie halten kein Recht, dem Waisen fordern sie seine Sache nicht, und gelinget ihnen, und helfen den Armen nicht zum Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Sollte ich denn solches nicht heimsuchen, spricht der HERR, und meine Seele sollte sich nicht rachen an solchem Volk, wie dies ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Es stehet greulich und scheufilich im Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Die Propheten lehren falsch, und die Priester herrschen in ihrem Amt, und mein Volk, hat\'s gem also. Wie will es euch zuletzt darob gehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Sammelt euch, ihr Kinder Benjamin, aus Jerusalem und blaset die Trommeten auf der Warte Thekoa und werfet auf ein Panier auf der Warte Beth- Cherem; denn es gehet daher ein Ungluck von Mitternacht und ein grafter Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Die Tochter Zion ist wie eine schone und lustige Aue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Aber es werden Hirten uber sie kommen mit ihren Herden, die werden Gezelte rings um sie her aufschlagen und weiden, ein jeglicher an seinem Ort (und sprechen):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Rustet euch zum Kriege wider sie! Wohlauf, laftt uns hinaufziehen, weil es noch hoch Tag ist! Ei, es will Abend werden, und die Schatten werden graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Wohlan, so lalit uns auf sein, und sollten wir bei Nacht hinaufziehen, und ihre Palaste verderben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Denn also spricht der HERR Zebaoth: Fallet Baume und macht Schutte wider Jerusalem; denn sie ist eine Stadt, die heimgesucht werden soli. Ist doch eitel Unrecht drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Denn gleichwie ein Born sein Wasser quillet, also quillet auch ihre Bosheit. Ihr Frevel und Gewalt schreiet uber sie; und ihr Morden und Schlagen treiben sie taglich vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Bessere dich, Jerusalem, ehe sich mein Herz von dir wende und ich dich zum wüsten Lande mache, darinnen niemand wohne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So spricht der HERR Zebaoth: Was übrig geblieben ist von Israel, das muft auch nachher abgelesen werden wie am Weinstock. Der Weinleser wird eins nach dem andern in die Butten werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Ach, mitwem soil ich doch reden und zeugen? Daft doch jemand horen wollte! Aber ihre Ohren sind unbeschnitten, sie mogen\'s nicht horen. Siehe, sie halten des HERRN Wort fur einen Spott und wollen sein nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Darum bin ich des HERRN Drauen so voll, daß ich\'s nicht lassen kann. Schutte aus, beide, uber Kinder auf den Gassen und uber die Mannschaft im Rat miteinander; denn es sollen beide, Mann und Weib, beide, Alte und der Wohlbetagte, gefangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Ihre Hauser sollen den Fremden zuteil werden samt den Ackern und Weibern; denn ich will meine Hand ausstrecken, spricht der HERR, uber des Landes Einwohner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Denn sie geizen allesamt, klein und graft, und beide Propheten und Priester lehren allesamt falschen Gottesdienst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'und trosten mein Volk in seinem Ungluck, daß Sie es gering achten sollen, und sagen: Friede, Friede! und ist doch nicht Friede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Darum werden sie mit Schanden bestehen, daß sie solche Greuel treiben, wiewohl sie wollen ungeschandet sein und wollen sich nicht schamen. Darum müssen sie fallen uber einen Haufen; und wenn ich sie heimsuchen werde, sollen sie fallen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So spricht der HERR: Tretet auf die Wege und schauet und fraget nach den vorigen Wegen, welches der gute Weg sei, und wandelt drinnen, so werdet ihr Ruhe finden fur eure Seele. Aber sie sprechen: Wir wollen\'s nicht tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Ich habe Wachter uber euch gesetzt. Merket auf die Stimme der Trommeten! Aber sie sprechen: Wir wollen\'s nicht tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Darum so horet, ihr Heiden, und merket samt euren Leuten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Du Erde, hore zu! Siehe, ich will ein Ungluck uber dies Volkbringen, namlich ihren verdienten Lohn, daß sie auf meine Worte nicht achten und mein Gesetz verwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Was frage ich nach dem Weihrauch, der aus Reicharabien, und nach den guten Zimmetrinden, die aus fernen Landen kommen? Eure Brandopfer sind mir nicht angenehm und eure Opfer gefallen mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Darum spricht der HERR also: Siehe, ich will diesem Volk ein Argernis stellen, daran sich beide, Vater und Kinder miteinander stolen, und ein Nachbar mit dem andern umkommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So spricht der HERR: Siehe, es wird ein Volk kommen von Mitternacht, und ein grofi Volk wird sich erregen hart an unserm Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'die Bogen und Schild fuhren. Es ist grausam und ohne Barmherzigkeit sie brausen daher wie ein ungestüm Meer und reiten auf Rossen, gerustet wie Kriegsleute, wider dich, du Tochter Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Wenn wir von ihnen horen werden, so werden uns die Fauste entsinken; es wird uns angst und weh werden wie einer Gebarerin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Es gehe ja niemand hinaus auf den Acker, niemand gehe uber Feld; denn es ist ailenthalben unsicher vor dem Schwert des Feindes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, '0 Tochter meines Volks, zeuch Sacke an und lege dich in die Asche; trage Leid wie urn einen einigen Sohn und kiage wie die, so hoch betrubt sind; denn der Verderber kommt uber uns plbtzlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Ich habe dich zum Schmelzer gesetzt unter mein Volk, das so hart ist, daü du ihr Wesen erfahren und prufen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Sie sind allzumal Abtrünnige und wandeln verraterisch; sie sind eitel verdorben Erz und Eisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Der Blasbalg ist verbrannt, das Blei verschwindet; das Schmelzen ist umsonst, denn das Bose ist nicht davon geschieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Darum heifien sie auch ein verworfen Silber; denn der HERR hat sie verworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Dies ist das Wort, welches geschah zu Jeremia vom HERRN, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Tritt ins Tor im Hause des HERRN und predige, daselbst dies Wort und sprich: Horet des HERRN Wort, ihr alle von Juda, die ihr zu diesen Toren eingehet, den HERRN anzubeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So spricht der HERR Zebaoth, der Gott Israels: Bessert euer Leben und Wesen, so will ich bei euch wohnen an diesem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Verlasset euch nicht auf die Lugen, wenn sie sagen: Hie ist des HERRN Tempel, hie ist des HERRN Tempel, hie ist des HERRN Tempel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Sondern bessert euer Leben und Wesen, dalj ihr recht tut einer gegen den andern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'und den Fremdlingen, Waisen und Witwen keine Gewalt tut und nicht unschuldig Blut vergiefiet an diesem Ort; und folget nicht nach andern Gottern zu eurem eigenen Schaden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'so will ich immer und ewiglich bei euch wohnen an diesem Ort, im Lande, das ich euren Vatern gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Aber nun verlasset ihr euch auf Lugen, die kein nütze sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Daneben seid ihr Diebe, Morder, Ehebrecher und Meineidige und rauchert dem Baal und foiget fremden Gottern nach, die ihr nicht kennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Danach kommt ihr denn und tretet vor mich in diesem Hause, das nach meinem Namen genannt ist, und sprechet: Es hat keine Not mit uns, weil wir solche Greuel tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Haltet ihr denn dies Haus, das nach meinem Namen genannt ist, fur eine Mordergrube? Siehe, ich sehe es wohl, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Gehet hin an meinen Ortzu Silo, da vorhin mein Name gewohnet hat, und schauet, was ich daselbst getan habe urn der Bosheit willen meines Volks Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Weil ihr denn alle solche Stücke treibet, spricht der HERR, und ich stets euch predigen lasse, und ihr wolit nicht horen, ich rufe euch, und ihr wollt nicht antworten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'so will ich dem Hause, das nach meinem Namen genannt ist, darauf ihr euch verlasset, und dem Ort, den ich euren Vatern gegeben habe, eben tun, wie ich Silo getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Und will euch von meinem Angesicht wegwerfen, wie ich weggeworfen habe alle eure Bruder, den ganzen Samen Ephraims.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Und du sollst fur dies Volk nicht bitten und sollst fur sie keine Kiage noch Gebet vorbringen, auch nicht sie vertreten vor mir; denn ich will dich nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Denn siehest du nicht, was sie tun in den Stadten Judas und auf den Gassen zu Jerusalem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Die Kinder lesen Holz, so zünden die Vater das Feueran, und die Weiber kneten den Teig, daü sie der Melecheth des Himmels Kuchen backen und Trankopfer den fremden Gottern geben, daß sie mir Verdriefi tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Aber sie sollen nicht mir damit, spricht der HERR, sondern ihnen selbst Verdriefi tun und müssen zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Darum spricht der Herr HERR: Siehe, mein Zorn und mein Grimm ist ausgeschuttet uber diesen Ort, beide, fiber Menschen und fiber Vieh fiber Baume auf dem Felde und uber Fruchte des Landes; und der soil brennen, daß niemand loschen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So spricht der HERR Zebaoth, der Gott Israels: Tut eure Brandopfer und andere Opfer zuhauf und fresset Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Denn ich habe euren Vatern des Tages, da ich sie aus Agyptenland führete, weder gesagt noch geboten von Brandopfern und andern Opfern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'sondern dies gebot ich ihnen und sprach: Gehorchet meinem Wort, so will ich euer Gott sein, und ihr sollt mein Volk sein, und wandelt auf alien Wegen; die ich euch gebiete, auf dafi es euch wohlgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Aber sie wollten nicht horen noch ihre Ohren zuneigen, sondern wandelten nach ihrem eigenen Rat und nach ihres bosen Herzens Gedünken und gingen hinter sich und nicht vor sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Ja, von dem Tage an, da ich eure Vater aus Agyptenland gefuhret habe, bis auf diesen Tag habe ich stets zu euch gesandt alle meine Knechte, die Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Aber sie wollen mich nicht horen noch ihre Ohren neigen, sondern sind halsstarrig und machen\'s arger denn ihre Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Und wenn du ihnen dies alles schon sagest, so werden sie dich doch nicht horen; rufst du ihnen, so werden sie dir nicht antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Darum sprich zu ihnen: Dies ist das Volk, das den HERRN, ihren Gott, nicht horen noch sich bessern will. Der Glaube ist untergegangen und ausgerottet von ihrem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Schneide deine Haare ab und wirf sie von dir und heule klaglich auf den Hohen; denn der HERR hat dies Geschlecht, uber das er zornig ist, verworfen und verstoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Denn die Kinder Juda tun ubel vor meinen Augen, spricht der HERR. Sie setzen ihre Greuel in das Haus, das nach meinem Namen genannt ist, daß sie es verunreinigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'und bauen die Altare Thopheth im Tal Ben- Hinnom, dafi sie ihre Sohne und Tochter verbrennen, welches ich nie geboten noch in Sinn genommen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Darum siehe, es kommt die Zeit, spricht der HERR, daß man es nicht mehr heiften soil Thopheth und das Tal Ben-Hinnom, sondern Würgetal; und man wird in Thopheth müssen begraben, weil sonst kein Raum mehr sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Und die Leichname dieses Volks sollen den Vogeln des Himmels und den Tieren auf Erden zur Speise werden, davon sie niemand scheuchen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Und will in den Stadten Judas und auf den Gassen zu Jerusalem wegnehmen das Geschrei der Freude und Wonne und die Stimme des Brautigams und der Braut; denn das Land soil wüste sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Zu derselbigen Zeit, spricht der HERR, wird man die Gebeine der Konige Judas, die Gebeine ihrer Fursten, die Gebeine der Priester, die Gebeine der Propheten, die Gebeine der Burger zu Jerusalem aus ihren Grabern werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Und werden sie zerstreuen unter der Sonne, Mond und allem Heer des Himmels, welche sie geüebet und ihnen gedienet und ihnen nachgefolget und sie gesucht und angebetet haben. Sie sollen nicht wieder aufgelesen und begraben werden, sondern Kot auf der Erdesein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Und alle übrigen von diesem bosen Volk, an welchem Ort sie sein werden, dahin ich sie verstoften habe, werden lieber tot denn lebendig sein wolien, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Darum sprich zu ihnen: So spricht der HERR: Wo ist jemand, so er fallt, der nicht gerne wieder aufstunde? Wo ist jemand, so er irre gehet, der nicht gerne wieder zurechtkame?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Noch will ja dies Volk zu Jerusalem irre gehen fur und fur. Sie halten so hart an dem falschen Gottesdienst, dafi sie sich nicht wollen abwenden lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich sehe und hore, daß sie nichts Rechtes lehren. Keiner ist, dem seine Bosheit leid ware und sprache: Was mache ich doch? Sie laufen alle ihren Lauf wie ein grimmiger Hengst im Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Ein Storch unter dem Himmel weift seine Zeit, eine Turteltaube, Kranich und Schwalbe merken ihre Zeit, wann sie wiederkommen sollen; aber mein Volk will das Recht des HERRN nicht wissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Wie moget ihr doch sagen: Wir wissen, was recht ist, und haben die heilige Schrift vor uns? Ist\'s doch eitel Lügen, was die Schriftgelehrten setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Darum müssen solche Lehrer zuschanden, erschreckt und gefangen werden; denn was konnen sie Gutes lehren, weil sie des HERRN Wort verwerfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Darum so will ich ihre Weiber den Fremden geben und ihre Acker denen, so sie verjagen werden. Denn sie geizen allesamt, beide, klein und graft, und beide, Priester und Propheten, lehren falschen Gottesdienst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'und trosten mein Volk in ihrem Unglück, daß sie es gering achten sollen, und sagen: Friede, Friede! und ist doch nicht Friede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Darum werden sie mit Schanden bestehen, daß sie solche Greuel treiben, wiewohl sie wollen ungeschandet sein und wollen sich nicht schamen. Darum müssen sie fallen uber einen Haufen, und wenn ich sie heimsuchen werde, sollen sie fallen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Ich will sie alle ablesen, spricht der HERR, dafi keine Trauben am Weinstock und keine Feigen am Feigenbaum bleiben, ja, auch die Blatter wegfallen sollen; und was ich ihnen gegeben habe, das soil ihnen genommen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Wo werden wir dann wohnen? Ja, sammelt euch dann und laftt uns in die festen Stadte ziehen und daselbst auf Hilfe harren. Denn der HERR, unser Gott, wird uns helfen mit einem bittern Trunk, dati wir so sundigen wider den HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Ja, verlasset euch darauf, es solle keine Not haben, so doch nichts Gutes vorhanden ist, und dad ihr sollt heil werden, so doch eitel Schaden vorhanden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Man horet, dad ihre Rosse bereits schnauben zu Dan und ihre Gaule schreien, dad das ganze Land davon erbebet. Und sie fahren daher und werden das Land auffressen mit allem, was drinnen ist, die Stadt samt alien, die drinnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Denn siehe, ich will Schlangen und Basilisken unter euch senden, die nicht beschworen sind; die sollen euch stechen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Da will ich mich meiner Mühe und meines Herzeleides ergotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Siehe, die Tochter meines Volks wird schreien aus fernem Lande her: Will denn der HERR nicht mehr Gott sein zu Zion, Oder soli sie keinen Konig mehr haben? Ja, warum haben sie mich so erzurnet durch ihre Bilder und fremde, unnutze Gottesdienste?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Die Ernte ist vergangen, der Sommer ist dahin, und uns ist keine Hilfe kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Mich jammed herzlich, dafi mein Volk so verderbet ist; ich grame mich und gehabe mich ubel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Ist denn keine Salbe in Gilead? Oder ist kein Arzt nicht da? Warum ist denn die Tochter meines Volks nicht geheilet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 23, 'Ach, daß ich Wassergenug hatte in meinem Haupte und meine Augen Tranenquellen waren, dati ich Tag und Nacht beweinen mochte die Erschlagenen in meinem Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Ach, dati ich eine Herberge hatte in der Wuste, so wollte ich mein Volk verlassen und von ihnen ziehen. Denn es sind eitel Ehebrecher und ein frecher Haufe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Sie schieften mit ihren Zungen eitel Lugen und keine Wahrheit und treiben\'s mit Gewalt im Lande und gehen von einer Bosheit zur andern und achten mich nicht, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Ein jeglicher hute sich vor seinem Freunde und traue auch seinem Bruder nicht; denn ein Bruder unterdruckt den andern, und ein Freund verrat den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Ein Freund tauscht den andern und reden kein wahr Wort; sie fleiftigen sich darauf, wie einer den andern betruge, und ist ihnen leid, daß sie es nicht arger machen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Es ist alienthalben eitel T rugerei unter ihnen, und vor Trugerei wollen sie mich nicht kennen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Darum spricht der HERR Zebaoth also: Siehe, ich will sie schmelzen und prufen. Denn was soil ich sonst tun, weil sich mein Volk so zieret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Ihre falschen Zungen sind morderische Pfeile; mit ihrem Munde reden sie freundlich gegen den Nachsten, aber im Herzen lauern sie auf denselben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Sollte ich nun solches nicht heimsuchen an ihnen, spricht der HERR, und meine Seele sollte sich nicht rachen an solchem Volk, als dies ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ich muft auf den Bergen weinen und heulen und bei den Hurden in der Wuste klagen; denn sie sind so gar verheeret, daß niemand da wandelt, und man auch nicht ein Vieh schreien horet. Es ist beides, Vogel des Himmels und das Vieh, alles weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Und ich will Jerusalem zum Steinhaufen und zur Drachenwohnung machen und will die Stadte Judas wuste machen, daß niemand drinnen wohnen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Wer nun weise ware und liefte ihm zu Herzen gehen und verkündigte, was des HERRN Mund zu ihm sagt, warum das Land verderbet und verheeret wird, wie eine Wuste, da niemand wandelt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Und der HERR sprach: Darum daß sie mein Gesetz verlassen, das ich ihnen vorgegeben habe, und gehorchen meiner Rede nicht, leben auch nicht danach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'sondern folgen ihres Herzens Gedunken und Baalim, wie sie ihre Vater gelehret haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'darum spricht der HERR Zebaoth, der Gott Israels, also: Siehe, ich will dies Volk mit Wermut speisen und mit Galle tranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Ich will sie unter die Heiden zerstreuen, welche weder sie noch ihre Vater kennen, und will das Schwert hinter sie schicken, bis daß es aus mit ihnen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'So spricht der HERR Zebaoth: Schaffet und bestellet Klageweiber, daß sie kommen, und schicket nach denen, die es wohl konnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'und eilend uns klagen, daß unsere Augen mit Tranen rinnen und unsere Augenlider mit Wasser flieften,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'daß man ein klaglich Geschrei hore zu Zion, namlich also: Ach, wie sind wir so gar verstoret und zuschanden worden! Wir müssen das Land raumen, denn sie haben unsere Wohnungen geschleift.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'So horet nun, ihr Weiber, des HERRN Wort und nehmet zu Ohren seines Mundes Rede; lehret eure Tochter weinen, und eine lehre die andere klagen, namlich also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Der Tod istzu unsern Fenstern hereingefallen und in unsere Palaste kommen, die Kinder zu wurgen auf der Gasse und die Jünglinge auf der Strafte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'So spricht der HERR: Sage: Der Menschen Leichname sollen liegen wie der Mist auf dem Felde und wie Garben hinter dem Schnitter, die niemand sammelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'So spricht der HERR: Ein Weiser ruhme sich nicht seiner Weisheit, ein Starker ruhme sich nicht seiner Starke, ein Reicher rühme sich nicht seines Reichtums,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'sondern wer sich rühmen will, der rühme sich des, da(S er mich wisse und kenne, daß ich der HERR bin, der Barmherzigkeit, Recht und Gerechtigkeit übet auf Erden; denn solches gefallt mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Siehe, es kommt die Zeit, spricht der HERR, daß ich heimsuchen werde alle, die Beschnittenen mit den Unbeschnittenen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'namlich Agypten, Juda, Edom, die Kinder Ammon, Moab und alle, die in den Ortern der Wüste wohnen. Denn alle Heiden haben unbeschnittene Vorhaut, aber das ganze Haus Israel hat unbeschnitten Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Horet, was der HERR zu euch vom Hause Israel redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So spricht der HERR: Ihr sollt nicht der Heiden Weise lernen und sollt euch nicht furchten vor den Zeichen des Himmels, wie die Heiden sich furchten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Denn der Heiden Gotter sind lauter nichts. Sie hauen im Lande einen Baum, und der Werkmeister macht sie mitdem Beil');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'und schmückt sie mit Silber und Gold und heftet sie mit Nageln und Hammern, daß sie nicht umfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Es sind ja nichts denn Saulen uberzogen. Sie konnen nicht reden, so muß man sie auch tragen, denn sie konnen nicht gehen. Darum sollt ihr euch nicht vor ihnen furchten, denn sie konnen weder helfen noch Schaden tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Aber dir, HERR, ist niemand gleich; du bist groß und dein Name ist groß und kannst es mit der Tat beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Wer sollte dich nicht furchten, du Konig der Heiden? Dir sollte man ja gehorchen; denn es ist unter alien Weisen der Heiden und in alien Konigreichen deinesgleichen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Sie sind allzumal Narren und Toren; denn ein Holz muß ja ein nichtiger Gottesdienst sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Silbern Blech bringt man auf dem Meer her, Gold aus Uphas, durch den Meister und Goldschmied zugerichtet; gelbe Seide und Purpur zeucht man ihm an, und ist alles der Weisen Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Aber der HERR ist ein rechter Gott, ein lebendiger Gott, ein ewiger Konig. Vor seinem Zorn bebet die Erde, und die Heiden kdnnen sein Drauen nicht ertragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'So sprechet nun zu ihnen also: Die Gotter, so den Himmel und Erde nicht gemacht haben, müssen vertilget werden von der Erde und unter dem Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Er aber hat die Erde durch seine Kraft gemacht und den Weltkreis bereitet durch seine Weisheit und den Himmel ausgebreitet durch seinen Verstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Wenn er donnert, so ist des Wassers die Menge unter dem Himmel, und zeucht die Nebel auf vom Ende der Erde; er macht die Blitze im Regen und laßt den Wind kommen aus heimlichen Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Alle Menschen sind Narren mit ihrer Kunst, und alle Goldschmiede stehen mit Schanden mit ihren Bildern; denn ihre Gotzen sind Trugerei und haben kein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Es ist eitel nichts und ein verfuhrerisch Werk; sie müssen umkommen, wenn sie heimgesucht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Aber also ist der nicht, der Jakobs Schatz ist; sondern er ist\'s, der alles geschaffen hat, und Israel ist sein Erbteil. Er heifit HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Tu dein Gewerbe weg aus dem Lande, die du wohnest in der festen Stadt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Denn so spricht der HERR: Siehe, ich will die Einwohner des Landes auf diesmal verschleudern und will sie angsten, daß sie es fühlen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Ach, meines Jammers und Herzeleids! Ich denke aber: Es ist meine Plage, ich muli sie leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Meine Hutte ist zerstoret, und alle meine Seile sind zerrissen. Meine Kinder sind weg und nicht mehr vorhanden. Niemand richtet meine Hutte wieder auf, und mein Gezelt schlagt niemand wieder auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Denn die Hirten sind zu Narren worden und fragen nach dem HERRN nicht; darum konnen sie auch nichts Rechtes lehren, sondern alle Herden sind zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Siehe, es kommt ein Geschrei daher und ein groß Beben aus dem Lande von Mitternacht, daß die Stadte Judas verwüstet und zur Drachenwohnung werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Ich weiß, HERR, daß des Menschen Tun stehet nicht in seiner Gewalt und stehet in niemands Macht, wie er wandele Oder seinen Gang richte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Zuchtige mich, HERR, doch mit Maße und nicht in deinem Grimm, auf daß du mich nicht aufreibest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Schutte aber deinen Zorn uber die Heiden, so dich nicht kennen, und uber die Geschlechter, so deinen Namen nicht anrufen. Denn sie haben Jakob aufgefressen und verschlungen; sie haben ihn aufgeraumet und seine Wohnung verwüstet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Dies ist das Wort, das zu Jeremia geschah vom HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Horet die Worte dieses Bundes, daß ihr sie denen in Juda und den Bürgern zu Jerusalem saget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Und sprich zu ihnen: So spricht der HERR, der Gott Israels: Verflucht sei, wer nicht gehorcht den Worten dieses Bundes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'den ich euren Vatern gebot des Tages, da ich sie aus Agyptenland führete, aus dem eisernen Ofen, und sprach: Gehorchet meiner Stimme und tut, wie ich euch geboten habe, so sollt ihr mein Volk sein, und ich will euer Gott sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'auf daß ich den Eid halten moge, den ich euren Vatern geschworen habe, ihnen zu geben ein Land, darin Milch und Honig fleußt, wie es denn heutigestages stehet. Ich antwortete und sprach: HERR, ja, es sei also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Und der HERR sprach zu mir: Predige alle diese Worte in den Stadten Judas und auf den Gassen zu Jerusalem und sprich: Horet die Worte dieses Bundes und tut danach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Denn ich habe eure Vater bezeuget von dem Tage an, da ich sie aus Agyptenland fuhrete, bis auf den heutigen Tag und zeugete frith und sprach: Gehorchet meiner Stimme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Aber sie gehorchten nicht, neigten auch ihre Ohren nicht, sondern ein jeglicher ging nach seines bosen Herzens Gedünken. Darum will ich auch über sie gehen lassen alle Worte dieses Bundes, den ich geboten habe zu tun und sie doch nicht danach getan haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Und der HERR sprach zu mir: Ich weiß wohl, wie sie in Juda und Jerusalem sich rotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Sie kehren sich eben zu den Sunden ihrer vorigen Vater, welche auch nicht gehorchen wollten meinen Worten und folgten auch andern Gottern nach und dieneten ihnen. Also hat das Haus Israel und das Haus Juda (immerdar) meinen Bund gebrochen, den ich mit ihren Vatern gemacht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Darum siehe, spricht der HERR, ich will ein Ungluck uber sie gehen lassen, dem sie nicht sollen entgehen mogen; und wenn sie zu mir schreien, will ich sie nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'So laß denn die Stadte Judas und die Burger zu Jerusalem hingehen und zu den Gottern schreien, denen sie gerauchert haben; aber sie werden ihnen nicht helfen in ihrer Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Denn manche Stadt, so manche Gotter hast du, Juda; und so manche Gassen zu Jerusalem sind, so manchen Schandaltar habt ihr aufgerichtet, dem Baal zu rauchern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'So bitte du nun nicht fur dies Volk und tu kein Flehen noch Gebet fur sie; denn ich will sie nicht horen, wenn sie zu mir schreien in ihrer Not.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Was haben meine Freunde in meinem Hause zu schaffen? Sie treiben alle Schalkheit und meinen, das heilige Fleisch soil es von ihnen nehmen; und wenn sie ubel tun, sind sie guter Dinge daruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Der HERR nannte dich einen grünen, schonen, fruchtbaren Olbaum; aber nun hat er mit einem großen Mordgeschrei ein Feuer urn denselbigen angezundet, daß seine Aste verderben müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Denn der HERRZebaoth, der dich gepflanzt hat, hat dir ein Ungluck gedrauet urn der Bosheit. willen des Hauses Israel und des Hauses Juda, welche sie treiben, daß sie mich erzurnen mit ihrem Rauchern, das sie dem Baal tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Der HERR hat mir\'s offenbart, daß ich\'s weiß, und zeigte mir ihr Vornehmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'namlich daß sie mich wie ein arm Schaf zur Schlachtbank führen wollen. Denn ich wußte nicht, daß sie wider mich beratschlagt hatten und gesagt: Laßt uns den Baum mit seinen Fruchten verderben und ihn aus dem Lande der Lebendigen ausrotten, daß seines Namens nimmermehr gedacht werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Aberdu, HERRZebaoth, du gerechter Richter, der du Nieren und Herzen prufest, laß mich deine Rache uber sie sehen; denn ich habe dir meine Sache befohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Darum spricht der HERR also wider die Manner zu Anathoth, die dir nach deinem Leben stehen und sprechen: Weissage uns nicht im Namen des HERRN, willst du anders nicht von unsern Handen sterben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Darum spricht der HERR Zebaoth also: Siehe, ich will sie heimsuchen; ihre junge Mannschaft sollen mit dem Schwert getotet werden und ihre Sohne und Tochter Hungers sterben, daß nichts von ihnen überbleibe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'denn ich will uber die Manner zu Anathoth Ungluck gehen lassen des Jahrs, wenn sie heimgesucht werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'HERR, wenn ich gleich mit dir rechten wollte, so behaltst du doch recht; dennoch muß ich vom Recht mit dir reden. Warum gehet es doch den Gottlosen so wohl, und die Verachter haben alles die Fulle?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du pflanzest sie, daß sie wurzeln und wachsen und bringen Frucht; du lassest sie viel von dir ruhmen und zuchtigest sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mich aber, HERR, kennest du und siehest mich und prufest mein Herz vor dir. Aber du lassest sie frei gehen wie Schafe, daß sie geschlachtet werden, und sparest sie, daß sie gewurget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Wie lange soil doch das Land so jammerlich stehen, und das Gras auf dem Felde allenthalben verdorren urn der Einwohner Bosheit willen, daß beide, Vieh und Vogel, nimmerda sind? Denn sie sprechen: Ja, er weiß viel, wie es uns gehen wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Wenn dich die müde machen, die zu Fuße gehen, wie will dir\'s gehen, wenn du mit den Reitern laufen sollst? Und so du im Lande, da es Friede ist, Sicherheit suchest, was will mit dir werden bei dem hoffartigen Jordan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Denn es verachten dich auch deine Brüder und deines Vaters Haus und schreien Zeter uber dich. Darum vertraue du ihnen nicht, wenn sie gleich freundlich mit dir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Darum habe ich mein Haus verlassen müssen und mein Erbe meiden und meine liebe Seele in der Feinde Hand geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mein Erbe ist mir worden wie ein Lowe im Walde und brullet wider mich; darum bin ich ihm gram worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Mein Erbe ist wie der sprenklige Vogel, urn welchen sich die Vogel sammeln. Wohlauf und sammelt euch, alle Feldtiere; kommet und fresset!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Es haben Hirten, und deren viel, meinen Weinberg verderbet und meinen Acker zertreten; sie haben meinen schonen Acker zur Wuste gemacht, sie haben\'s ode gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Ich sehe bereits, wie es so jammerlich verwustet ist, ja, das ganze Land ist wuste. Aber es will\'s niemand zu Herzen nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Denn die Verstorer fahren daher uber alle Hugel der Wuste, und das fressende Schwert des HERRN von einem Ende des Landes bis zum andern; und kein Fleisch wird Frieden haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Sie saen Weizen, aber Disteln werden sie ernten; sie lassen\'s ihnen sauer werden; aber sie werden\'s nicht genielien; sie werden ihres Einkommens nicht froh werden vor dem grimmigen Zorn des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So spricht der HERR wider alle meine bosen Nachbarn, so das Erbteil antasten, das ich meinem Volk Israel ausgeteilet habe: Siehe, ich will sie aus ihrem Lande ausreiften und das Haus Juda aus ihrem Mittel reitien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Und wenn ich sie nun ausgerissen habe, will ich mich wiederum uber sie erbarmen und will einen jeglichen zu seinem Erbteil und in sein Land wiederbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Und soil geschehen, wo sie von meinem Volk lernen werden, daß sie schworen bei meinem Namen: So wahr der HERR lebet, wie sie (zuvor) mein Volk gelehret haben schworen bei Baal, so sollen sie unter meinem Volk erbauet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Wo sie aber nicht horen wollen, so will ich solches Volk ausreiften und umbringen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So spricht der HERR zu mir: Gehe hin und kaufe dir einen leinenen Gürtel und gurte damit deine Lenden und mache ihn nicht naft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Und ich kaufte einen Gurtel nach dem Befehl des HERRN und gurtete ihn urn meine Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Da geschah des HERRN Wort zum andernmal zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Nimm den Gurtel, den du gekauft und urn deine Lenden gegurtet hast, und mache dich auf und gehe hin an den Phrath und verstecke ihn daselbst in einen Steinritz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Ich ging hin und versteckte ihn am Phrath, wie mir der HERR geboten hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Nach langer Zeit aber sprach der HERRzu mir: Mache dich auf und gehe hin an den Phrath und hole den Gurtel wieder, den ich dich hieli daselbst verstecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Ich ging hin an den Phrath und grub auf und nahm den Gurtel von dem Ort, dahin ich ihn versteckt hatte; und siehe, der Gurtel war verdorben, dati er nichts mehr taugte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'So spricht der HERR: Eben also will ich auch verderben die grofte Hoffart Judas und Jerusalems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Das bose Volk, das meine Worte nicht horen will, sondern gehen hin nach Gedünken ihres Herzens und folgen andern Gottern, daß sie denselbigen dienen und anbeten, sie sollen werden wie der Gürtel, der nichts mehr taugt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Denn gleichwie ein Mann den Gurtel urn seine Lenden bindet, also habe ich, spricht der HERR, das ganze Haus Israel und das ganze Haus Juda urn mich gegurtet, dafi sie mein Volk sein sollten, zu einem Namen, Lob und Ehren; aber sie wollen nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'So sage ihnen nun dies Wort: So spricht der HERR, der Gott Israels: Es sollen alle Legel mit Wein gefullet werden. So werden sie zu dir sagen: Wer weift das nicht, daß man alle Legel mit Wein füllen soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'So sprich zu ihnen: So spricht der HERR: Siehe, ich will alle, die in diesem Lande wohnen, die Konige, so auf dem Stuhl Davids sitzen, die Priester und Propheten, und alle Einwohnerzu Jerusalem füllen, daß sie trunken werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Und will einen mit dem andern, die Vater samt den Kindern, verstreuen, spricht der HERR, und will weder schonen noch übersehen, noch barmherzig sein uber ihrem Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'So horet nun und merket auf und trotzet nicht; denn der HERR hat\'s geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gebet dem HERRN, eurem Gott, die Ehre, ehe denn es finster werde, und ehe eure Futie sich an den dunklen Bergen stoften, daß ihr des Lichts wartet, so er\'s doch gar finster und dunkel machen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Wollt ihr aber solches nicht horen, so muft meine Seele doch heimlich weinen uber solche Hoffart; meine Augen müssen mit Tranen flieften, daß des HERRN Herde gefangen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Sage dem Konige und der Konigin: Setzet euch herunter, denn die Krone der Herrlichkeit ist euch von eurem Haupt gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Die Stadte gegen Mittag sind verschlossen, und ist niemand, der sie auftue; das ganze Juda ist rein weggefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Hebet eure Augen auf und sehet, wie sie von Mitternacht daherkommen. Wo ist nun die Herde, so dir befohlen war, deine herrliche Herde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Waswillstdu sagen, wenn er dich so heimsuchen wird? Denn du hast sie so gewohnet wider dich, daß sie Fursten und Haupter sein wollen. Was gilt\'s? es wird dich Angst ankommen wie ein Weib in Kindesnoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Und wenn du in deinem Herzen sagen willst: Warum begegnet doch mir solches? Urn der Menge willen deiner Missetat sind dir deine Saume aufgedeckt und deine Schenkel (mit Gewalt) gebloftet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann auch ein Mohr seine Haut wandeln Oder ein Parder seine Flecken? So konnet ihr auch Gutes tun, weil ihr des Bosen gewohnt seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Darum will ich sie zerstreuen wie Stoppeln, die vor dem Winde aus der Wuste verweht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Das soil dein Lohn sein und dein Teil, den ich dir zugemessen habe, spricht der HERR. Darum daß du mein vergessen hast und verlassest dich auf Lugen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'so will auch ich deine Saume hoch aufdecken gegen dir, daß man deine Scham wohl sehen mull.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Denn ich habe gesehen deine Ehebrecherei, deine Geilheit, deine freche Hurerei, ja deine Greuel, beide, auf Hugeln und auf Ackern. Wehe dir, Jerusalem! Wann willst du doch immer mehr gereiniget werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Dies ist das Wort, das der HERR zu Jeremia sagte von der teuren Zeit:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juda liegt jammerlich, ihre Tore stehen elend, es stehet klaglich auf dem Lande, und istzu Jerusalem eine große Durre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Die Großen schicken die Kleinen nach Wasser; aber wenn sie zum Brunnen kommen, finden sie kein Wasser und bringen ihre Gefaße leer wieder. Sie gehen traurig und betrubt und verhullen ihre Haupter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'darum daß die Erde lechzet, weil es nicht regnet auf die Erde. Die Ackerleute gehen traurig und verhullen ihre Haupter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Denn auch die Hinden, so auf dem Felde werfen, verlassen die Jungen, weil kein Gras wachst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Das Wild stehet auf den Hugeln und schnappet nach der Luft, wie die Drachen, und verschmachtet, weil kein Kraut wachst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Ach, HERR, unsere Missetaten haben\'sja verdienet; aber hilf doch urn deines Namens willen; denn unser Ungehorsam ist groß, damit wir wider dich gesundiget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du bist der Trost Israels und ihr Nothelfer; warum stellest du dich, als warest du ein Gast im Lande, und als ein Fremder, der nur uber Nacht drinnen bleibt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Warum stellest du dich als ein Held, der verzagt ist, und als ein Riese, der nicht helfen kann? Du bist doch ja unter uns, HERR, und wir heißen nach deinem Namen; verlaß uns nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'So spricht der HERR von diesem Volk: Sie laufen gerne hin und wieder und bleiben nicht gerne daheim; darum will ihrer der HERR nicht, sondern er denkt nun an ihre Missetat und will ihre Sünden heimsuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Und der HERR sprach zu mir: Du sollst nicht fur dies Volk urn Gnade bitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Denn ob sie gleich fasten, so will ich doch ihr Flehen nicht horen; und ob sie Brandopfer und Speisopfer bringen, so gefallen sie mir doch nicht, sondern ich will sie mit dem Schwert, Hunger und Pestilenz aufreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Da sprach ich: Ach, Herr HERR, siehe, die Propheten sagen ihnen: Ihrwerdet kein Schwert sehen und keine Teurung bei euch haben, sondern ich will euch guten Frieden geben an diesem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Und der HERR sprach zu mir: Die Propheten weissagen falsch in meinem Namen; ich habe sie nicht gesandt und ihnen nichts befohlen und nichts mit ihnen geredet; sie predigen euch falsche Gesichte, Deutung, Abgotterei und ihres Herzens Trugerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Darum so spricht der HERR von den Propheten, die in meinem Namen weissagen, so ich sie doch nicht gesandt habe, und sie dennoch predigen, es werde kein Schwert noch Teurung in dies Land kommen: Solche Propheten sollen sterben durch Schwert und Hunger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Und das Volk, dem sie weissagen, sollen vom Schwert und Hunger auf den Gassen zu Jerusalem hin und her liegen, daß sie niemand begraben wird; also auch ihre Weiber, Sohne und Tochter; und will ihre Bosheit tiber sie schutten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Und du sollst zu ihnen sagen dies Wort: Meine Augen fließen mit Tranen Tag und Nacht und horen nicht auf; denn die Jungfrau, die Tochter meines Volks, ist greulich zerplagt und jammerlich geschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Gehe ich hinaus aufs Feld, siehe, so liegen da Erschlagene mit dem Schwert; komme ich in die Stadt, so liegen da vor Hunger Verschmachtete. Denn es müssen auch die Propheten, dazu auch die Priester, in ein Land ziehen, das sie nicht kennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hast du denn Juda verworfen, Oder hat deine Seele einen Ekel an Zion? Warum hast du uns denn so geschlagen, daß uns niemand heilen kann? Wir hofften, es sollte Friede werden, so kommt nichts Gutes; wir hofften, wir sollten heil werden, aber siehe, so ist mehr Schadens da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'HERR, wirerkennen unser gottlos Wesen und unserer Vater Missetat; denn wir haben wider dich gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Aber urn deines Namens willen laß uns nicht geschandet werden; laß den Thron deiner Herrlichkeit nicht verspottet werden; gedenke doch und laß deinen Bund mit uns nicht aufhoren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Es ist doch ja unter der Heiden Gotzen keiner, der Regen konnte geben; so kann der Himmel auch nicht regnen. Du bist doch ja der HERR, unser Gott, auf den wir hoffen; denn du kannst solches alles tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Und der HERR sprach zu mir: Und wenngleich Mose und Samuel vor mir stunden, so haben ich doch kein Herz zu diesem Volk. Treibe sie weg von mir und laß sie hinfahren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Und wenn sie zu dir sagen: Wo sollen wir hin? so sprich zu ihnen: So spricht der HERR: Wen der Tod trifft, den treffe er; wen das Schwert trifft, den treffe es; wen der Hunger trifft, den treffe er; wen das Gefangnis trifft, den treffe es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Denn ich will sie heimsuchen mit viererlei Plagen, spricht der HERR: mit dem Schwert, daß sie erwürget werden; mit Hunden, die sie schleifen sollen; mit den Vogeln des Himmels und mit Tieren auf Erden, daß sie gefressen und verweset werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Und ich will sie in alien Konigreichen auf Erden hin und her treiben lassen um Manasses willen, des Sohns Jehiskias, des Konigs Judas, deshalben, das er zu Jerusalem begangen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Wer will denn sich dein erbarmen, Jerusalem? Werwird denn Mitleid mit dir haben? Werwird denn hingehen und dir Frieden erwerben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Du hast mich verlassen, spricht der HERR, und bist mir abgefallen; darum habe ich meine Hand ausgestreckt wider dich, daß ich dich verderben will; ich bin des Erbarmens müde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Ich will sie mit der Worfschaufel zum Lande hinaus worfeln und will mein Volk, so von seinem Wesen sich nicht bekehren will, zu eitel Waisen machen und umbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Es sollen mir mehr Witwen unter ihnen werden, denn des Sandes am Meer ist. Ich will uber die Mutter derjungen Mannschaft kommen lassen einen offenbarlichen Verderber und die Stadt damit plotzlich und unversehens uberfallen lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'daß die, so sieben, Kinder hat, soil elend sein und von Herzen seufzen. Denn ihre Sonne soli bei hohem Tage untergehen, daß beide, ihr Ruhm und Freude, ein Ende haben soil. Und die übrigen will ich ins Schwert geben vor ihren Feinden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ach, meine Mutter, daß du mich geboren hast, wider den jedermann hadert und zankt im ganzen Lande! Habe ich doch weder auf Wucher geliehen noch genommen, noch flucht mir jedermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Der HERR sprach: Wohlan, ich will euer etliche ubrig behalten, denen es soil wieder wohlgehen, und will euch zu Hilfe kommen in der Not und Angst unter den Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Meinest du nicht, daß etwa ein Eisen sei, welches konnte das Eisen und Erz von Mitternacht zerschlagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Ich will aber zuvor euer Gut und Schatze in die Rapuse geben, daß ihr nichts dafur kriegen sollt, und das um aller eurer Sunden willen, die ihr in alien euren Grenzen begangen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Und will euch zu euren Feinden bringen in ein Land, das ihr nicht kennet; denn es ist das Feuer in meinem Zorn uber euch angegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ach, HERR, du weilit es; gedenke an uns und nimm dich unser an und rache uns an unsern Verfolgern! Nimm uns auf und verzeuch nicht deinen Zorn uber sie; denn du weilit, daß wir um deinetwillen geschmahet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Indes enthalte uns dein Wort, wenn wir\'s kriegen; und dasselbe, dein Wort ist unsers Herzens Freude und Trost; denn wir sind ja nach deinem Namen genannt, HERR, Gott Zebaoth!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Wir gesellen uns nicht zu den Spottern noch freuen uns mit ihnen, sondern bleiben alleine vor deiner Hand; denn du zurnest sehr mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Warum wahret doch unser Schmerz so lange, und unsere Wunden sind so gar bose, daß sie niemand heilen kann? Du bist uns worden wie ein Born, der nicht mehr quellen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Darum spricht der HERR also: Wo du dich zu mir haltst, so will ich mich zu dir halten, und sollst mein Prediger bleiben; und wo du die Frommen lehrest sich sondern von den bosen Leuten, so sollst du mein Lehrer sein; und ehe du solltest zu ihnen fallen, so müssen sie eher zu dir fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Denn ich habe dich wider dies Volk zur festen ehernen Mauer gemacht; ob sie wider dich streiten, sollen sie dir doch nichts anhaben; denn ich bin bei dir, daß ich dir helfe und dich errette, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Und will dich auch erretten aus der Hand der Bosen und erlosen aus der Hand der Tyrannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Du sollst kein Weib nehmen und weder Sohne noch Tochterzeugen an diesem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Denn so spricht der HERR von den Sohnen und Tochtem, so an diesem Ort geboren werden, dazu von ihren Muttern, die sie gebaren, und von ihren Vatern, die sie zeugen in diesem Lande:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Sie sollen an Krankheiten sterben und weder beklagt noch begraben werden, sondern sollen Mist werden auf dem Lande, dazu durch Schwert und Hunger umkommen, und ihre Leichname sollen der Vogel des Himmels und der Here auf Erden Speise sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Denn so spricht der HERR: Du sollst nicht zum Trauerhaus gehen und sollst auch nirgendhin zu klagen gehen noch Mitleid uber sie haben; denn ich habe meinen Frieden von diesem Volk weggenommen, spricht der HERR, samt meiner Gnade und Barmherzigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'daß beide, graft und klein, sollen in diesem Lande sterben und nicht begraben noch geklaget werden, und niemand wird sich uber sie zerritzen noch kahl machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Und man wird auch nicht unter sie Brot austeilen über der Klage, sie zu trdsten uber der Leiche, und ihnen auch nicht aus dem Trostbecher zu trinken geben über Vater und Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Darum sollst du in kein Trinkhaus gehen, bei ihnen zu sitzen, weder zu essen noch zu trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Denn so spricht der HERR Zebaoth, der Gott Israels: Siehe, ich will an diesem Ort aufheben vor euren Augen und bei eurem Leben die Stimme der Freude und Wonne, die Stimme des Brautigams und der Braut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Und wenn du solches alles diesem Volk gesagt hast, und sie zu dir sprechen werden: Warum redet der HERR uber uns all dies grofte Unglück? welches ist die Missetat und Sunde, damit wir wider den HERRN, unsern Gott, gesundiget haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'sollstdu ihnen sagen: Darum daß eure Vater mich verlassen, spricht der HERR, und andern Gottern gefolget, denselbigen gedienet und sie angebetet, mich aber verlassen und mein Gesetz nicht gehalten haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'und ihrnoch arger tut denn eure Vater. Denn siehe, ein jeglicher lebt nach seines bosen Herzens Gedunken, dafi er mir nicht gehorche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Darum will ich euch aus diesem Lande stolien in ein Land, davon weder ihr noch eure Vater wissen; daselbst sollt ihr andern Gottern dienen Tag und Nacht; daselbst will ich euch keine Gnade erzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Darum siehe, es kommt die Zeit, spricht der HERR, daß man nicht mehr sagen wird: So wahr der HERR lebt, der die Kinder Israel aus Agyptenland geführet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'sondern: So wahr der HERR lebt, der die Kinder Israel geführet hat aus dem Lande der Mitternacht und aus alien Landern, dahin er sie verstoßen hatte. Denn ich will sie wiederbringen in das Land, das ich ihren Vatern gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Siehe, ich will viel Fischer aussenden, spricht der HERR, die sollen sie fischen; und danach will ich viel Jager aussenden, die sollen sie fahen auf alien Bergen und auf alien Hügeln und in alien Steinritzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Denn meine Augen sehen auf alle ihre Wege, daß sie vor mir sich nicht verhehlen konnen; und ihre Missetat ist vor meinen Augen unverborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Aber zuvor will ich ihre Missetat und Sunde zwiefach bezahlen, darum daß sie mein Land mit den Leichen ihrer Abgotterei verunreiniget und mein Erbe mit ihren Greueln voll gemacht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'HERR, du bist meine Starke und Kraft und meine Zuflucht in der Not. Die Heiden werden zu dir kommen von der Welt Ende und sagen: Unsere Vater haben falsche und nichtige Gotter gehabt, die nichts nutzen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Wie kann ein Mensch Gotter machen, die nicht Gotter sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Darum siehe, nun will ich sie lehren und meine Hand und Gewalt ihnen kundtun, daß sie erfahren sollen, ich heiße der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Die Sunde Judas ist geschrieben mit eisernen Griffeln und mit spitzigen Demanten geschrieben und auf die Tafel ihres Herzens gegraben und auf die Horner an ihren Altaren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'daß ihre Kinder gedenken sollen derselben Altare und Haine bei den grunen Baumen, auf den hohen Bergen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Aber ich will deine Hohen beide, auf Bergen und Feldern, samt deiner Habe und alien deinen Schatzen in die Rapuse geben urn der Sunde willen, in alien deinen Grenzen begangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Und du sollst aus deinem Erbe verstoßen werden, das ich dir gegeben habe, und will dich zu Knechten deiner Feinde machen in einem Lande, das du nicht kennest; denn ihr habt ein Feuer meines Zorns angezundet, das ewiglich brennen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So spricht der HERR: Verflucht ist der Mann, der sich auf Menschen verlaßt und halt Fleisch fur seinen Arm und mit seinem Herzen vom HERRN weicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Der wird sein wie die Heide in der Wuste und wird nicht sehen den zukunftigen Trost, sondern wird bleiben in der Dürre, in der Wuste, in einem unfruchtbaren Lande, da niemand wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Gesegnetaber ist der Mann, der sich auf den HERRN verlaßt, und der HERR seine Zuversicht ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Der ist wie ein Baum am Wasser gepflanzt und am Bach gewurzelt. Denn obgleich eine Hitze kommt, furchtet er sich doch nicht, sondern seine Blatter bleiben gain, und sorget nicht, wenn ein durres Jahr kommt, sondern er bringet ohne Aufhoren Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Es ist das Herz ein trotzig und verzagt Ding; wer kann es ergrunden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ich, der HERR, kann das Herz ergrunden und die Nieren prufen; und gebe einem jeglichen nach seinem Tun, nach den Fruchten seiner Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Denn gleichwie ein Vogel, der sich fiber Eier setzt und brutet sie nicht aus, also ist der, so unrecht Gut sammelt; denn er muß davon, wenn er\'s am wenigsten achtet, und muß doch zuletzt Spott dazu haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Aber die Statte unsers Heiligtums, namlich der Thron gottlicher Ehre, ist allezeit fest geblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Denn, HERR, du bist die Hoffnung Israels. Alle, die dich verlassen, müssen zuschanden werden, und die Abtrunnigen müssen in die Erde geschrieben werden; denn sie verlassen den HERRN, die Quelle des lebendigen Wassers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Heile du mich, HERR, so werde ich heil; hilf du mir, so ist mir geholfen; denn du bist mein Ruhm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Siehe, sie sprechen zu mir: Wo ist denn des HERRN Wort? Lieber, laß, hergehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Aber ich bin drum nicht von dir geflohen, mein Hirte, so habe ich Menschentage nicht begehret, das weilit du; was ich gepredigt habe, das ist recht vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Sei du mir nur nicht schrecklich, meine Zuversicht in der Not!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Lal J sie zuschanden werden, die mich verfolgen, und mich nicht; laß sie erschrecken und mich nicht; laß, den Tag des Unglucks uber sie gehen und zerschlage sie zwiefach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'So spricht der HERR zu mir: Gehe hin und tritt unter das Tor des Volks, dadurch die Konige Judas aus und ein gehen, und unter alle Tore zu Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'und sprich zu ihnen: Horet des HERRN Wort, ihr Konige Judas und ganz Juda und alle Einwohner zu Jerusalem, so zu diesem Tor eingehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So spricht der HERR: Hutet euch und traget keine Last am Sabbattage durch die Tore hinein zu Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'und führet keine Last am Sabbattage aus euren Hausern und tut keine Arbeit, sondern heiliget den Sabbattag, wie ich euren Vatern geboten habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Aber sie horen nicht und neigen ihre Ohren nicht, sondern bleiben halsstarrig, daß sie mich ja nicht horen noch sich ziehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'So ihr mich horen werdet, spricht der HERR, daß ihr keine Last traget des Sabbattages durch dieser Stadt Tore ein, sondern denselbigen heiliget, daß ihr keine Arbeit an demselbigen Tage tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'so sollen auch durch dieser Stadt Tore aus und ein gehen Konige und Fursten, die auf dem Stuhl Davids sitzen, und reiten und fahren, beide, auf Wagen und Rossen, sie und ihre Fursten, samt alien, die in Juda und zu Jerusalem wohnen; und soil diese Stadt ewiglich bewohnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Und sollen kommen aus den Stadten Judas, und die um Jerusalem her liegen, und aus dem Lande Benjamin, aus den Gründen und von den Gebirgen und vom Mittage, die da bringen Brandopfer, Opfer, Speisopfer und Weihrauch zum Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Werdet ihr mich aber nicht horen, daß ihr den Sabbattag heiliget und keine Last traget durch die Tore zu Jerusalem ein am Sabbattage, so will ich ein Feuer unter ihren Toren anstecken, das die Hauser zu Jerusalem verzehren und nicht geloscht werden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Dies ist das Wort, das geschah vom HERRN zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Mache dich auf und gehe hinab in des Topfers Haus; daselbst will ich dich meine Worte horen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Und ich ging hinab in des Topfers Haus; und siehe, er arbeitete eben auf der Scheibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Und der Topf, so er aus dem Ton machte, miftriet ihm unter den Handen. Da machte er wiederum einen andern Topf, wie es ihm gefiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Kann ich nicht auch also miteuch umgehen, ihr vom Hause Israel, wie dieser Topfer? spricht der HERR. Siehe, wie der Ton ist in des Topfers Hand, also seid auch ihr vom Hause Israel in meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Plotzlich rede ich wider ein Volk und Konigreich, daß ich\'s ausrotten, zerbrechen und verderben wolle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Wo sich\'s aber bekehret von seiner Bosheit, dawider ich rede, so soli mich auch reuen das Ungluck, das ich ihm gedachte zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Und plotzlich rede ich von einem Volk und Konigreich, daß ich\'s bauen und pflanzen wolle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'So es aber Boses tut vor meinen Augen, daß es meiner Stimme nicht gehorcht, so soli mich auch reuen das Gute, das ich ihm verheiften hatte zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'So sprich nun zu denen in Juda und zu den Burgern zu Jerusalem: So spricht der HERR: Siehe, ich bereite euch ein Ungluck zu und habe Gedanken wider euch; darum kehre sich ein jeglicher von seinem bosen Wesen und bessert euer Wesen und Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Aber sie sprechen: Da wird nichts aus! Wir wollen nach unsern Gedanken wandeln und ein jeglicher tun nach Gedunken seines bosen Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Darum spricht der HERR: Fragt doch unter den Heiden, wer hat je desgleichen gehoret, daß die Jungfrau Israel so gar greulich Ding tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Bleibtdoch derßchnee langeraufden Steinen im Feide, wenn\'s vom Libanon herab schneiet, und das Regenwasser verschieftt nicht so bald, als mein Volk mein vergiftt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Sie rauchern den Gottern und richten Argernis an auf ihren Wegen fur und fur und gehen auf ungebahnten Straften,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'auf daß ihr Land zur Wuste werde, ihnen zur ewigen Schande, daß, wer vorubergehet, sich verwundere und den Kopf schuttele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Denn ich will sie durch einen Ostwind zerstreuen vor ihren Feinden; ich will ihnen den Rücken und nicht das Antlitz zeigen, wenn sie verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Aber sie sprechen: Kommt und laftt uns wider Jeremia ratschlagen; denn die Priester konnen nicht irren im Gesetz, und die Weisen konnen nicht fehlen mit Raten, und die Propheten konnen nicht unrecht lehren. Kommt her, laftt uns ihn mit der Zunge totschlagen und nichts geben auf alle seine Rede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'HERR, habe acht auf mich und hore die Stimme meiner Widersacher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Ist\'s recht, daß man Gutes mit Bosem vergilt? Denn sie haben meiner Seele eine Grube gegraben. Gedenke doch, wie ich vor dir gestanden bin, daß ich ihr Bestes redete und deinen Grimm von ihnen wendete!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'So strafe nun ihre Kinder mit Hunger und laft sie ins Schwert fallen, daß ihre Weiber ohne Kinder und Witwen seien, und ihre Manner zu Tode geschlagen und ihre junge Mannschaft im Streit durchs Schwert erwurget werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'daß ein Geschrei aus ihren Hausern gehoret werde, wie du plotzlich habest Kriegsvolk uber sie kommen lassen. Denn sie haben eine Grube gegraben, mich zu fahen, und meinen Füften Stricke gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Und weil du, HERR, weiftt alle ihre Anschlage wider mich, daß sie mich toten wolien, so vergib ihnen ihre Missetat nicht und laft ihre Sunde vor dir nicht ausgetilget werden. Laft sie vor dir gestürzt werden und handle mit ihnen nach deinem Zorn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So spricht der HERR: Gehe hin und kaufe dir einen irdenen Krug vom Topfer samt etlichen von den Altesten des Volks und von den Altesten der Priester');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'und gehe hinaus ins Tal Ben-Hinnom, das vor dem Ziegeltor liegt, und predige daselbst die Worte, die ich dir sage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'und sprich: Horet des HERRN Wort, ihr Konige Judas und Burger zu Jerusalem! So spricht der HERR Zebaoth, der Gott Israels: Siehe, ich will ein solch Ungluck uber diese Statte gehen lassen, dais, wer es horen wird, ihm die Ohren klingen sollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'darum dafi sie mich verlassen und diese Statte einem fremden Gott gegeben haben und andern Gottern drinnen gerauchert haben, die weder sie noch ihre Vater noch die Konige Judas gekannt haben, und haben diese Statte voll unschuldigen Bluts gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Denn sie haben dem Baal Hohen gebauet, ihre Kinder zu verbrennen dem Baal zu Brandopfern, welches ich ihnen weder geboten noch davon geredet habe, dazu in mein Herz nie kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Darum siehe, es wird die Zeit kommen, spricht der HERR, daß man diese Statte nicht mehr Thopheth noch das Tal Ben-Hinnom, sondern Würgetal heilien wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Denn ich will den Gottesdienst Judas und Jerusalems dieses Orts zerstoren und will sie durchs Schwert fallen lassen vor ihren Feinden unter der Hand derer, so nach ihrem Leben stehen, und will ihre Leichname den Vogeln des Himmels und den Tieren auf Erden zu fressen geben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'und will diese Stadt wust machen und zum Spott, dad alle, die vorubergehen, werden sich verwundern uber alle ihre Plage und ihrer spotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Ich will sie lassen ihrer Sohne und Tochter Fleisch fressen, und einer soil des andern Fleisch fressen in der Not und Angst, damit sie ihre Feinde und die, so nach ihrem Leben stehen, bedrangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Und du sollst den Krug zerbrechen vor den Mannern, die mit dir gegangen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Und sprich zu ihnen: So spricht der HERR Zebaoth: Eben wie man eines Topfers Gefali zerbricht, das nicht mag wieder ganz werden, so will ich dies Volk und diese Stadt auch zerbrechen, und sollen dazu im Thopheth begraben werden, weil sonst kein Raum sein wird zu begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'So will ich mit dieser Statte, spricht der HERR, und ihren Einwohnern umgehen, dad diese Stadt werden soli gleichwie Thopheth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Dazu sollen die Hauser zu Jerusalem und die Hauser der Konige Judas ebenso unrein werden als die Statte Thopheth, ja, alle Hauser, da sie auf den Dachern gerauchert haben allem Heer des Himmels und andern Gottern Trankopfer geopfert haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Und da Jeremia wieder von Thopheth kam, dahin ihn der HERR gesandt hatte zu weissagen, trat er in den Vorhof am Hause des HERRN und sprach zu allem Volk:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'So spricht der HERR Zebaoth, der Gott Israels: Siehe, ich will uber diese Stadt und uber alle ihre Stadte all das Ungluck kommen lassen, das ich wider sie geredet habe, darum dafi sie halsstarrig sind und meine Worte nicht horen wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Da aber Pashur, ein Sohn Immers, des Priesters, so zum Obersten im Hause des HERRN gesetzt war, Jeremia horete solche Worte weissagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'schlug erden Propheten Jeremia und warf ihn ins Gewolbe unter dem Obertor Benjamin, welches am Hause des HERRN ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Und da es Morgen ward, zog Pashur Jeremia aus dem Gewolbe. Da sprach Jeremia zu ihm: Der HERR heillt dich nicht Pashur, sondern Magur urn und urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Denn so spricht der HERR: Siehe, ich will dich samt alien deinen Freunden in die Furcht geben, und sollen fallen durchs Schwert ihrer Feinde; das sollst du mit deinen Augen sehen. Und will das ganze Juda in die Hand des Konigs zu Babel ubergeben; der soil sie wegfuhren gen Babel und mit dem Schwert toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Auch will ich alle Guter dieser Stadt samt allem, das sie gearbeitet, und alle Kleinode und alle Schatze der Konige Judas in ihrer Feinde Hand geben, dafi sie dieselbigen rauben, nehmen und gen Babel bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Und du, Pashur, sollst mit alien deinen Hausgenossen gefangen gehen und gen Babel kommen; daselbst sollst du sterben und begraben werden samt alien deinen Freunden, welchen du Lügen predigest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'HERR, du hast mich uberredet, und ich habe mich uberreden lassen; du bist mir zu stark gewesen und hast gewonnen. Aber ich bin daruber zum Spott worden taglich, und jedermann verlacht mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Denn seit ich geredet, gerufen und gepredigt habe von der Plage und Verstorung, ist mir des HERRN Wort zum Hohn und Spott worden taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Da dachte ich: Wohlan, ich will sein nicht mehr gedenken und nicht mehr in seinem Namen predigen. Aber es ward in meinem Herzen wie ein brennend Feuer, in meinen Gebeinen verschlossen, daß ich\'s nicht leiden konnte, und ware schier vergangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Denn ich hore, wie mich viele schelten und allenthalben schrecken: Hui, verklaget ihn! Wir wollen ihn verklagen, sprechen alle meine Freunde und Gesellen, ob wir ihn ubervorteilen und ihm beikommen mogen und uns an ihm rachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Aber der HERR ist bei mir wie ein starker Held, darum werden meine Verfolger fallen und nicht obliegen, sondern sollen sehr zuschanden werden, darum dafi sie so toricht handeln; ewig wird die Schande sein, der man nicht vergessen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Und nun, HERR Zebaoth, derdu die Gerechten prufest, Nieren und Herz siehest, lafi mich deine Rache an ihnen sehen; denn ich habe dir meine Sache befohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Singet dem HERRN, ruhmet den HERRN, der des Armen Leben aus der Boshaftigen Handen errettet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Verflucht sei der Tag, darin ich geboren bin; der Tag müsse ungesegnet sein, darin mich meine Mutter geboren hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Verflucht sei der, so meinem Vater gute Botschaft brachte und sprach: Du hast einen jungen Sohn, daß er ihn frohlich machen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Derselbige Mann müsse sein wie die Stadte, so der HERR umgekehret und ihn nicht gereuet hat, und musse des Morgens horen ein Geschrei und des Mittags ein Heulen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Dali du mich doch nicht getotet hast in Mutterleibe! Daß meine Mutter mein Grab gewesen, und ihr Leib ewig schwanger geblieben ware!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Warum bin ich doch aus Mutterleibe hervorkommen, dad ich solchen Jammer und Herzeleid sehen mull und meine Tage mit Schanden zubringen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Dies ist das Wort, so vorn HERRN geschah zu Jeremia, da der Konig Zedekia zu ihm sandte Pashur, den Sohn Malchias, und Zephanja, den Sohn Maesejas, des Priesters, und lied ihm sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Frage doch den HERRN fur uns! Denn Nebukadnezar, der Konig zu Babel, streitet wider uns, dad der HERR doch mit uns tun wolle nach alien seinen Wundern, damit er von uns abzoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremia sprach zu ihnen: So saget Zedekia:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Das spricht der HERR, der Gott Israels: Siehe, ich will die Waffen zurückwenden, die ihr in euren Handen habt, damit ihr streitet wider den Konig zu Babel und wider die Chaldaer, welche euch drauden an der Mauer belagert haben, und will sie zuhauf sammeln mitten in der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Und ich will wider euch streiten mit ausgereckter Hand, mit starkem Arm, mit grodem Zorn, Grimm und Unbarmherzigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Und will die Burger dieser Stadt schlagen, beide, Menschen und Vieh, daß sie sterben sollen durch eine große Pestilenz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Und danach, spricht der HERR, will ich Zedekia, den Konig Judas, samt seinen Knechten und dem Volk, das in dieser Stadt vor der Pestilenz, Schwert und Hunger überbleiben wird, geben in die Hande Nebukadnezars, des Konigs zu Babel, und in die Hande ihrer Feinde und in die Hande derer, so ihnen nach dem Leben stehen, daß er sie mit der Scharfe des Schwerts also schlage, daß kein Schonen noch Gnade noch Barmherzigkeit da sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Und sage diesem Volk: So spricht der HERR: Siehe, ich lege euch vor den Weg zum Leben und den Weg zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Wer in dieser Stadt bleibt, der wird sterben müssen durchs Schwert, Hunger und Pestilenz; wer aber hinaus sich gibt zu den Chaldaern, die euch belagern, der soil lebendig bleiben und soil sein Leben als eine Ausbeute behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Denn ich habe mein Angesicht über diese Stadt gerichtet zum Unglück und zu keinem Guten, spricht der HERR. Sie soil dem Konige zu Babel ubergeben werden, daß er sie mit Feuer verbrenne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Und horetdes HERRN Wort, ihrvom Hause des Konigs Judas!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Du Haus David, so spricht der HERR: Haltet des Morgens Gericht und errettet den Beraubten aus des Frevlers Hand, auf dad mein Grimm nicht ausfahre wie ein Feuer und brenne also, dad niemand loschen moge, urn eures bosen Wesens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Siehe, spricht der HERR, ich sage dir, die du wohnest im Grunde, in dem Felsen und auf der Ebene und sprichst: Wer will uns überfallen Oder in unsere Feste kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Ich will euch heimsuchen, spricht der HERR, nach der Frucht eures Tuns; ich will ein Feuer anzünden in ihrem Walde, das soli alles umher verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So spricht der HERR: Gehe hinab in das Haus des Konigs Judas und rede daselbst dies Wort');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'und sprich: Hore des HERRN Wort, du Konig Judas, der du auf dem Stuhl Davids sitzest, beide, du und deine Knechte und dein Volk, die zu diesen Toren eingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So spricht der HERR: Haltet Recht und Gerechtigkeit und errettet den Beraubten von des Frevlers Hand und schindet nicht die Fremdlinge, Waisen und Witwen und tut niemand Gewalt und vergiedet nicht unschuldig Blut an dieser Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Werdet ihr solches tun, so sollen durch die Tore dieses Hauses einziehen Konige, die auf Davids Stuhl sitzen, beide, zu Wagen und zu Rod, samt ihren Knechten und Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Werdet ihr aber solchem nicht gehorchen, so habe ich bei mir selbst geschworen, spricht der HERR, dies Haus soli verstoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Denn so spricht der HERR von dem Hause des Konigs Judas: Gilead, du bist mir das Haupt im Libanon; was gilt\'s, ich will dich zur Wuste und die Stadte ohne Einwohner machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Denn ich habe Verderber uber dich bestellet, einen jeglichen mit seinen Waffen; die sollen deine auserwahlten Zedern umhauen und ins Feuer werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'So werden viel Heiden vor dieser Stadt vorübergehen und untereinander sagen: Warum hat der HERR mit dieser groden Stadt also gehandelt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Und man wird antworten: Darum dad sie den Bund des HERRN, ihres Gottes, verlassen und andere Gotter angebetet und denselbigen gedienet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Weinet nicht über die Toten und gramet euch nicht darum; weinet aber über den, der dahinzieht; denn erwird nimmer wiederkommen, dad er sein Vaterland sehen mochte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Denn so spricht der HERR von Sallum, dem Sohne Josias, des Konigs Judas, welcher Konig ist anstatt seines Vaters Josia, der von dieser Statte hinausgezogen ist: Er wird nicht wieder herkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'sondern muß sterben an dem Ort, dahin er gefangen gefuhret ist, und wird dies Land nicht mehr sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Wehe dem, dersein Haus mit Sunden bauet und seine Gemacher mit Unrecht, der seinen Nachsten umsonst arbeiten laßt und gibt ihm seinen Lohn nicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'und denkt: Wohlan, ich will mirein groß Haus bauen und weite Palaste; und laßt ihm Fenster drein bauen und mit Zedern tafeln und rot malen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Meinest du, du wollest Konig sein, weil du mit Zedern prangest? Hat dein Vater nicht auch gegessen und getrunken und hielt dennoch uber dem Recht und Gerechtigkeit, und ging ihm wohl?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Er half dem Elenden und Armen zum Recht, und ging ihm wohl. Ist\'s nicht also, daß solches heißt mich recht erkennen? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Aber deine Augen und dein Herz stehen nicht also, sondern auf deinem Geiz, auf unschuldig Blut zu vergießen, zu freveln und unterzustoßen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Darum spricht der HERR von Jojakim, dem Sohn Josias, dem Konige Judas: Man wird ihn nicht klagen: Ach Bruder, ach Schwester! Man wird ihn nicht klagen: Ach Herr, ach Edler!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Er soil wie ein Esel begraben werden, zerschleift und hinausgeworfen vor die Tore Jerusalems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Ja, dann gehe hinauf auf den Libanon und schreie und laß dich horen zu Basan und schreie von Abarim; denn alle deine Liebhaber sind jammerlich umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Ich habe dir\'s vorhergesagt, da es noch wohl urn dich stund; aber du sprachest: Ich will nicht horen. Also hast du dein Lebetage getan, daß du meiner Stimme nicht gehorchtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Der Wind weidet alle deine Hirten, und deine Liebhaber ziehen gefangen dahin; da mußt du doch zu Spott und zuschanden werden urn aller deiner Bosheit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Die du jetzt im Libanon wohnest und in Zedern nistest, wie schon wirst du sehen, wenn dir Schmerzen und Wehe kommen werden wie einer in Kindesnoten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'So wahr ich lebe, spricht der HERR, wenn Chanja, der Sohn Jojakims, der Konig Judas, ein Siegelring ware an meiner rechten Hand, so wollte ich dich doch abreißen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'und in die Hande geben derer, die nach deinem Leben stehen, und vorwelchen du dich furchtest, namlich in die Hande Nebukadnezars, des Konigs zu Babel, und der Chaldaer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Und will dich und deine Mutter, die dich geboren hat, in ein ander Land treiben, das nicht euer Vaterland ist; und sollst daselbst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Und in das Land, da sie von Herzen gerne wieder hin waren, sollen sie nicht wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Wie ein elender, verachteter, verstoßener Mann ist doch Chanja! ein unwert Gefaß! Ach, wie ist er doch samt seinem Samen so vertrieben und in ein unbekanntes Land geworfen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, '0 Land, Land, Land; hore des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So spricht der HERR: Schreibet an diesen Mann fur einen Verdorbenen, einen Mann, dem es sein Lebetage nicht gelinget. Denn er wird das Gluck nicht haben, daß jemand seines Samens auf dem Stuhl Davids sitze und fürder in Juda herrsche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Wehe euch Hirten, die ihr die Herde meiner Weide umbringet und zerstreuet! spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Darum spricht der HERR, der Gott Israels, von den Hirten, die mein Volk weiden: Ihr habt meine Herde zerstreuet und verstoßen und nicht besucht. Siehe, ich will euch heimsuchen urn eures bosen Wesens willen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Und ich will die übrigen meiner Herde sammeln aus alien Landern, dahin ich sie verstoßen habe, und will sie wiederbringen zu ihren Hürden, daß sie sollen wachsen und viel werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Und ich will Hirten uber sie setzen, die sie weiden sollen, daß sie sich nicht mehr sollen furchten noch erschrecken noch heimgesucht werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Siehe, es kommt die Zeit, spricht der HERR, daß ich dem David ein gerecht Gewachs erwecken will; und soil ein Konig sein, der wohl regieren wird und Recht und Gerechtigkeit auf Erden anrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Zu derselbigen Zeit soil Juda geholfen werden, und Israel sicherwohnen. Und dies wird sein Name sein, daß man ihn nennen wird: HERR, der unsere Gerechtigkeit ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Darum siehe, es wird die Zeit kommen, spricht der HERR, daß man nicht mehr sagen wird: So wahr der HERR lebt, der die Kinder Israel aus Agyptenland gefuhret hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'sondern: So wahr der HERR lebt, der den Samen des Hauses Israel hat herausgefuhret und gebracht aus dem Lande der Mitternacht und aus alien Landen, dahin ich sie verstoßen hatte, daß sie in ihrem Lande wohnen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Wider die Propheten. Mein Herz will mir in meinem Leibe brechen, alle meine Gebeine zittern; mir ist wie einem trunkenen Manne und wie einem, der vom Wein taumelt, vor dem HERRN und vor seinen heiligen Worten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'daß das Land so voll Ehebrecher ist, daß das Land so jammerlich stehet, daß es so verflucht ist, und die Auen in der Wüste verdorren; und ihr Leben ist bose, und ihr Regiment taugt nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Denn beide, Propheten und Priester, sind Schalke, und finde auch in meinem Hause ihre Bosheit, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Darum ist ihr Weg wie ein glatter Weg im Finstern, darauf sie gleiten und fallen. Denn ich will Ungluck uber sie kommen lassen, das Jahr ihrer Heimsuchung, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Zwar bei den Propheten zu Samaria sah ich Torheit, daß sie weissageten durch Baal und verfuhreten mein Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Aber bei den Propheten zu Jerusalem sehe ich Greuel, wie sie ehebrechen und gehen mit Lugen urn und starken die Boshaftigen, auf daß, sich ja niemand bekehre von seiner Bosheit. Sie sind alle vor mir gleichwie Sodom und ihre Burger wie Gomorrha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Darum spricht der HERR Zebaoth von den Propheten also: Siehe, ich will sie mit Wermut speisen und mit Galle tranken; denn von den Propheten zu Jerusalem kommt Heuchelei aus ins ganze Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'So spricht der HERR Zebaoth: Gehorchet nicht den Worten der Propheten, so euch weissagen! Sie betrugen euch; denn sie predigen ihres Herzens Gesicht und nicht aus des HERRN Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Sie sagen denen, die mich lastern: Der HERR hat\'s gesagt, es wird euch wohlgehen. Und alien, die nach ihres Herzens Dünkel wandeln, sagen sie: Es wird kein Ungluck uber euch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Denn weristim Rat des HERRN gestanden, der sein Wort gesehen und gehoret habe? Wer hat sein Wort vernommen und gehoret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Siehe, es wird ein Wetter des HERRN mit Grimm kommen und ein schrecklich Ungewitter den Gottlosen auf den Kopf alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Und des HERRN Zorn wird nicht nachlassen, bis er tue und ausrichte, was er im Sinn hat. Hernach werdet ihr\'s wohl erfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Ich sandte die Propheten nicht, noch liefen sie; ich redete nicht zu ihnen, noch weissagten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Denn wo sie bei meinem Rat blieben und hatten meine Worte meinem Volk geprediget, so flatten sie dasselbe von ihrem bosen Wesen und von ihrem bosen Leben bekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Bin ich nicht ein Gott, der nahe ist, spricht der HERR, und nicht ein Gott, der feme sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Meinest du, daß sich jemand heimlich verbergen konne, daß ich ihn nicht sehe? spricht der HERR. Bin ich\'s nicht, der Himmel und Erde fullet? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Ich hore es wohl, daß die Propheten predigen und falsch weissagen in meinem Namen und sprechen: Mir hat getraumet, mir hat getraumet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Wann wollen doch die Propheten aufhoren, die falsch weissagen und ihres Herzens Trugerei weissagen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'und wollen, daß mein Volk meines Namens vergesse uber ihren Traumen, die einer dem andern predigt, gleichwie ihre Vater meines Namens vergaften uber dem Baal?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Ein Prophet, der Traume hat, der predige Traume; wer aber mein Wort hat, der predige mein Wort recht. Wie reimen sich Stroh und Weizen zusammen? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ist mein Wort nicht wie ein Feuer, spricht der HERR, und wie ein Hammer, der Felsen zerschmeiftt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Darum siehe, ich will an die Propheten, spricht der HERR, die mein Wort stehlen einer dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Siehe, ich will an die Propheten, spricht der HERR, die ihr eigen Wortfuhren und sprechen: Er hat\'s gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Siehe, ich will an die, so falsche Traume weissagen, spricht der HERR, und predigen dieselben und verfuhren mein Volk mit ihren Lugen und losen Teidingen, so ich sie doch nicht gesandt und ihnen nichts befohlen habe, und sie auch diesem Volk nichts nutze sind, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Wenn dich dies Volk Oder ein Prophet Oder ein Priester fragen wird und sagen: Welches ist die Last des HERRN? sollst du zu ihnen sagen, was die Last sei: Ich will euch hinwerfen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Und wo ein Prophet Oder Priester Oder Volk wird sagen: Das ist die Last des HERRN, denselbigen will ich heimsuchen und sein Haus dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Also soil aber einer mit dem andern reden und untereinander sagen: Was antwortet der HERR und was sagt der HERR?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Und nennet es nicht mehr Last des HERRN; denn einem jeglichen wird sein eigen Wort eine Last sein, weil ihr also die Worte des lebendigen Gottes, des HERRN Zebaoth, unsers Gottes, verkehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Darum sollt ihrzum Propheten also sagen: Was antwortet dir der HERR und was sagt der HERR?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Weil ihr aber sprechet: Last des HERRN, darum spricht der HERR also: Nun ihr dies Wort eine Last des HERRN nennet, und ich zu euch gesandt habe und sagen lassen, ihr sollt es nicht nennen Last des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'siehe, so will ich euch hinwegnehmen und euch samt der Stadt, die ich euch und euren Vatern gegeben habe, von meinem Angesichtwegwerfen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'und will euch ewige Schande und ewige Schmach zufugen, deren nimmer vergessen soil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Siehe, der HERR zeigte mirzween Feigenkorbe, gestellt vor den Tempel des HERRN, nachdem der Konig zu Babel, Nebukadnezar, hatte weggefuhrt Jechanja, den Sohn Jojakims, den Konig Judas, samt den Fursten Judas, Zimmerleute und Schmiede von Jerusalem, und gen Babel gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'In dem einen Korbe waren sehr gute Feigen, wie die ersten reifen Feigen sind; im andern Korbe waren sehr bose Feigen, daß man sie nicht essen konnte, so bose waren sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Und der HERR sprach zu mir: Jeremia, was siehest du? Ich sprach: Feigen; die guten Feigen sind sehr gut und die bosen sind sehr bose, daß man sie nicht essen kann, so bose sind sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'So spricht der HERR, der Gott Israels: Gleichwie diese Feigen gut sind, also will ich mich gnadiglich annehmen der Gefangenen aus Juda, welche ich habe aus dieser Statte lassen ziehen in der Chaldaer Land,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'und will sie gnadiglich ansehen und will sie wieder in dies Land bringen und will sie bauen und nicht abbrechen, ich will sie pflanzen und nicht ausraufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Und will ihnen ein Herz geben, dad sie mich kennen sollen, dad ich der HERR sei. Und sie sollen mein Volk sein, so will ich ihr Gott sein; denn sie werden sich von ganzem Herzen zu mir bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Aber wie die bosen Feigen so bose sind, dad man sie nicht essen kann, spricht der HERR, also will ich dahingeben Zedekia, den Konig Judas, samt seinen Fursten, und was übrig ist zu Jerusalem und übrig in diesem Lande, und die in Agyptenland wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Ich will ihnen Ungluck zufugen und sie in keinem Konigreich auf Erden bleiben lassen, dad sie sollen zuschanden werden, zum Sprichwort, zur Fabel und zum Fluch an alien Orten, dahin ich sie verstoden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Und will Schwert, Hunger und Pestilenz unter sie schicken, bis sie umkommen von dem Lande, das ich ihnen und ihren Vatern gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Dies ist das Wort, welches zu Jeremia geschah uber das ganze Volk Juda im vierten Jahr Jojakims, des Sohns Josias, des Konigs Judas (welches ist das erste Jahr Nebukadnezars, des Konigs zu Babel),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'welches auch der Prophet Jeremia redete zu dem ganzen Volk Juda und zu alien Burgern zu Jerusalem und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Es ist von dem dreizehnten Jahr an Josias, des Sohns Amons, des Konigs Judas, des HERRN Wort zu mir geschehen bis auf diesen Tag, und habe euch nun dreiundzwanzig Jahre mit Fleiß geprediget; aber ihr habt nie hdren wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'So hat der HERR auch zu euch gesandt alle seine Knechte, die Propheten, fleilliglich; aber ihr habt nie horen wollen noch eure Ohren neigen, daß ihr gehorchet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'da er sprach: Bekehret euch, ein jeglicher von seinem bosen Wege und von eurem bosen Wesen, so sollt ihr in dem Lande, das der HERR euch und euren Vatern gegeben hat, immer und ewiglich bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Folget nicht andern Gottern, daü ihr ihnen dienet und sie anbetet, auf daß ihr mich nicht erzurnet durch eurer Hande Werk, und ich euch Ungluck zufugen müsse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Aber ihr wolltet mir nicht gehorchen, spricht der HERR, auf daü ihr mich ja wohl erzurnetet durch eurer Hande Werkzu eurem eigenen Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Darum so spricht der HERR Zebaoth: Weil ihr denn meine Worte nicht horen wollt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'siehe, so will ich ausschicken und kommen lassen alle Volker gegen Mitternacht, spricht der HERR, auch meinen Knecht Nebukadnezar, den Konig zu Babel, und will sie bringen uber dies Land und uber die, so drinnen wohnen, und uber all dieses Volk, so umherliegen, und will sie verbannen und verstoren und zum Spott und ewiger Wuste machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Und will herausnehmen alien frohlichen Gesang, die Stimme des Brautigams und der Braut, die Stimme der Muhlen und Licht der Laterne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'daß dies ganze Land wüst und zerstoret liegen soil. Und sollen diese Volker dem Konige zu Babel dienen siebenzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Wenn aber die siebenzig Jahre urn sind, will ich den Konig zu Babel heimsuchen und all dies Volk, spricht der HERR, urn ihre Missetat, dazu das Land der Chaldaer, und will es zur ewigen Wuste machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Also will ich uber dies Land bringen alie meine Worte, die ich geredet habe wider sie, namlich alles, was in diesem Buch geschrieben stehet, das Jeremia geweissaget hat uber alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Und sie solien auch dienen, ob sie gleich grolie Volker und grofie Konige sind. Also will ich ihnen vergelten nach ihrem Verdienst und nach den Werken ihrer Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Denn also spricht zu mir der HERR, der Gott Israels: Nimm diesen Becher Weins voll Zorns von meiner Hand und schenke daraus alien Volkern, zu denen ich dich sende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'da($ sie trinken, taumeln und toll werden vor dem Schwert, das ich unter sie schicken will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Und ich nahm den Becher von der Hand des HERRN und schenkte alien Volkern, zu denen mich der HERR sandte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'namlich Jerusalem, den Stadten Judas, ihren Konigen und Fursten, da(S sie wüst und zerstort liegen und ein Spott und Fluch sein sollen, wie es denn heutigestages stehet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'auch Pharao, dem Konige in Agypten, samt seinen Knechten, seinen Fursten und seinem ganzen Volk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'alien Landern gegen Abend, alien Konigen im Lande Uz, alien Konigen in der Palastiner Lande, samt Askalon, Gasa, Akaron und den übrigen zu Asdod;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'denen von Edom, denen von Moab, den Kindern Ammon;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'alien Konigen zu Tyrus, alien Kdnigen zu Zidon, den Konigen in den Inseln jenseit des Meers;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'denen von Dedan, denen von Thema, denen von Bus und alien Fursten in den Ortern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'alien Konigen in Arabien, alien Konigen gegen Abend, die in der Wuste wohnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'alien Konigen in Simri, alien Konigen in Elam, alien Konigen in Medien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'alien Konigen gegen Mitternacht, beide, in der Nahe und Feme, einem mit dem andern, und alien Kdnigen auf Erden, die auf dem Erdboden sind. Und Konig Sesach soil nach diesen trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Und sprich zu ihnen: So spricht der HERR Zebaoth, der Gott Israels: Trinket, daü ihrtrunken werdet, speiet und niederfallet und nicht aufstehen moget vor dem Schwert, das ich unter euch schicken will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Und wo sie den Becher nicht wollen von deiner Hand nehmen und trinken, so sprich zu ihnen: Also spricht der HERR Zebaoth: Nun sollt ihr trinken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Denn siehe, in der Stadt, die nach meinem Namen genannt ist, fahe ich an zu plagen, und ihr solltet ungestraft bleiben? Ihr sollt nicht ungestraft bleiben; denn ich rufe das Schwert uber alle, die auf Erden wohnen, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Und du sollst alle diese Worte ihnen weissagen und sprich zu ihnen: Der HERR wird brüllen aus der Hohe und seinen Donner horen lassen aus seiner heiligen Wohnung; er wird brüllen uber seine Hürden; er wird singen ein Lied, wie die Weintreter, uber alle Einwohner des Landes, des Hall erschallen wird bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Der HERR hat zu rechten mit den Heiden und will mit allem Fleisch Gericht halten; die Gottlosen wird er dem Schwert ubergeben, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So spricht der HERR Zeboath: Siehe, es wird eine Plage kommen von einem Volk zum andern, und ein groß Wetter wird erweckt werden von der Seite des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Da werden die Erschlagenen vom HERRN zur selbigen Zeit liegen von einem Ende der Erde bis ans andere Ende; die werden nicht geklaget noch aufgehoben noch begraben werden, sondern müssen auf dem Felde liegen und zu Mist werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Heulet nun, ihr Hirten, und schreiet; walzet euch in der Asche, ihr Gewaltigen uber die Herde! Denn die Zeit ist hie, daß ihr geschlachtet und zerstreuet werdet und zerfallen müsset, wie ein kostlich Gefaß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Und die Hirten werden nicht fliehen konnen, und die Gewaltigen uber die Herde werden nicht entrinnen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Da werden die Hirten schreien, und die Gewaltigen uber die Herde werden heulen, dafi der HERR ihre Weide so verwustet hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'und ihre Auen, die so wohl stunden, verderbet sind vor dem grimmigen Zorn des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Er hat seine Hütte verlassen, wie ein junger Lowe; und ist also ihr Land zerstoret vor dem Zorn des Tyrannen und vorseinem grimmigen Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Im Anfang des Konigreiches Jojakims, des Sohns Josias, des Konigs Judas, geschah dies Wort vom HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So spricht der HERR: Tritt in den Vorhof am Hause des HERRN und predige alien Stadten Judas, die da hereingehen anzubeten im Hause des HERRN, alle Worte, die ich dir befohlen habe, ihnen zu sagen, und tue nichts davon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'ob sie vielleicht horen wollen und sich bekehren, ein jeglicher von seinem bosen Wesen, damit mich auch reuen mochte das Ubel, das ich gedenke, ihnen zu tun, urn ihres bosen Wandels willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Und sprich zu ihnen: So spricht der HERR: Werdet ihr mir nicht gehorchen, daß ihr in meinem Gesetz wandelt, das ich euch vorgelegt habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'daü ihr horet die Worte meiner Knechte, der Propheten, welche ich stets zu euch gesandt habe, und ihr doch nicht horen wolltet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'so will ich\'s mit diesem Hause machen wie mit Silo und diese Stadt zum Fluch alien Heiden auf Erden machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Da nun die Priester, Propheten und alles Volk horeten Jeremia, daü er solche Worte redete im Hause des HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'und Jeremia nun ausgeredet hatte alles, was ihm der HERR befohlen hatte, allem Volk zu sagen, griffen ihn die Priester, Propheten und das ganze Volk und sprachen: Du mulit sterben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Warum darfst du weissagen im Namen des HERRN und sagen: Es wird diesem Hause gehen wie Silo, und diese Stadt soil so wuste werden, daü niemand mehr drinnen wohne? Und das ganze Volk sammelte sich im Hause des HERRN wider Jeremia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Da solches horeten die Fursten Judas, gingen sie aus des Konigs Hause hinauf ins Haus des HERRN und setzten sich vor das neue Tor des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Und die Priester und Propheten sprachen vor den Fursten und allem Volk: Dieser ist des Todes schuldig; denn er hat geweissagt wider diese Stadt, wie ihr mit euren Ohren gehoret habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Aber Jeremia sprach zu alien Fursten und zu allem Volk: Der HERR hat mich gesandt, daß ich solches alles, das ihr gehoret habt, sollte weissagen wider dies Haus und wider diese Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'So bessert nun euer Wesen und Wandel und gehorchet der Stimme des HERRN, eures Gottes, so wird den HERRN auch gereuen das Ubel, das er wider euch geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Siehe, ich bin in euren Handen; ihr moget es machen mit mir, wie es euch recht und gut dünkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Doch sollt ihrwissen, wo ihr mich totet, so werdet ihr unschuldig Blut laden auf euch selbst, auf diese Stadt und ihre Einwohner. Denn wahrlich, der HERR hat mich zu euch gesandt, daß ich solches alles vor euren Ohren reden sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Da sprachen die Fursten und das ganze Volk zu den Priestern und Propheten: Dieser ist des Todes nicht schuldig; denn er hat zu uns geredet im Namen des HERRN, unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Und es stunden auf etliche der Altesten im Lande und sprachen zum ganzen Haufen des Volks:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Zur Zeit Hiskias, des Konigs Judas, war ein Prophet, Micha von Maresa, und sprach zum ganzen Volk Juda: So spricht der HERR Zebaoth: Zion soil wie ein Acker gepfluget werden, und Jerusalem ein Steinhaufen werden und der Berg des Hauses (des HERRN) zum wilden Walde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Noch liefi ihn Hiskia, der Konig Judas, und das ganze Juda darum nicht toten; ja, sie furchteten vielmehrden HERRN und beteten vordem HERRN. Da reuete auch den HERRN das Libel, das er wider sie geredet hatte. Darum tun wir sehr übel wider unsere Seelen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'So war auch einer, der im Namen des HERRN weissagte, Uria, der Sohn Semajas, von Kiriath- Jearim. Derselbe weissagte wider diese Stadt und wider dies Land gleichwie Jeremia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Da aber der Konig Jojakim und alle seine Gewaltigen und die Fursten seine Worte horeten, wollte ihn der Konig toten lassen. Und Uria erfuhr das, furchtete sich und floh und zog nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Aber der Konig Jojakim schickte Leute nach Agypten, Elnathan, den Sohn Achbors, und andere mitihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Die fuhreten ihn aus Agypten und brachten ihn zum Kbnige Jojakim; der lied ihn mit dem Schwert toten und lied seinen Leichnam unter dem gemeinen Pobel begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Also war die Hand Ahikams, des Sohns Saphans, mit Jeremia, dad er nicht dem Volk in die Hande kam, daß sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Im Anfang des Konigreichs Jojakims, des Sohns Josias, des Konigs Judas, geschah dies Wort vom HERRN zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'So spricht der HERRzu mir: Mache direin Joch und hange es an deinen Hals.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Und schicke es zum Kbnige in Edom, zum Konige in Moab, zum Kbnige der Kinder Ammon, zum Kbnige zu Tyrus und zum Kbnige zu Zidon durch die Boten, so zu Zedekia, dem Kbnige Judas, gen Jerusalem kommen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Und befiehl ihnen, daß sie ihren Herren sagen: So spricht der HERR Zebaoth, der Gott Israels: So sollt ihr euren Herren sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ich habe die Erde gemacht und Menschen und Vieh, so auf Erden sind, durch meine grolie Kraft und ausgereckten Arm und gebe sie, wem ich will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Nun aber habe ich alle diese Lande gegeben in die Hand meines Knechts Nebukadnezar, des Konigs zu Babel, und habe ihm auch die wilden Tiere auf dem Felde gegeben, daß sie ihm dienen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Und sollen alle Volker dienen ihm und seinem Sohn und seines Sohnes Sohn, bis daß die Zeit seines Landes auch komme; denn es sollen ihm viel Volker und grolie Kbnige dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Welch Volk aber und Konigreich dem Kbnige zu Babel, Nebukadnezar, nicht dienen will, und wer seinen Hals nicht wird unter das Joch des Konigs zu Babel geben, solch Volk will ich heimsuchen mit Schwert, Hunger und Pestilenz, spricht der HERR, bis daß ich sie durch seine Hand umbringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Darum so gehorchet nicht euren Propheten, Weissagern, Traumdeutern, Tagewahlern und Zauberern, die euch sagen: Ihrwerdet nicht dienen mussen dem Kbnige zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Denn sie weissagen euch falsch, auf daß sie euch feme aus eurem Lande bringen, und ich euch ausstolie, und ihr umkommet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Denn welch Volk seinen Hals ergibt unter das Joch des Konigs zu Babel und dienet ihm, das will ich in seinem Lande lassen, daß es dasselbige baue und bewohne, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Und ich redete solches alles zu Zedekia, dem Kbnige Judas, und sprach: Ergebet euren Hals unter das Joch des Konigs zu Babel und dienet ihm und seinem Volk, so sollt ihr lebendig bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Warum wollt ihrsterben, du und dein Volk, durch Schwert, Hunger und Pestilenz? wie denn der HERR geredet hat liber das Volk, so dem Kbnige zu Babel nicht dienen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Darum gehorchet nicht den Worten der Propheten, die euch sagen: Ihr werdet nicht dienen mussen dem Kbnige zu Babel. Denn sie weissagen euch falsch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'und ich habe sie nicht gesandt, spricht der HERR; sondern sie weissagen falsch in meinem Namen, auf dad ich euch ausstolie, und ihr umkommet, samtden Propheten, die euch weissagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Und zu den Priestern und zu all diesem Volk redete ich und sprach: So spricht der HERR: Gehorchet nicht den Worten eurer Propheten, die euch weissagen und sprechen: Siehe, die Gefade aus dem Hause des HERRN werden nun bald von Babel wieder herkommen. Denn sie weissagen euch falsch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Gehorchet ihnen nicht, sondern dienet dem Kbnige zu Babel, so werdet ihr lebendig bleiben. Warum soil doch diese Stadt zur Wuste werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Sind sie aber Propheten und haben sie des HERRN Wort, so ladt sie den HERRN Zebaoth erbitten, dad die ubrigen Gefade im Hause des HERRN und im Hause des Konigs Judas und zu Jerusalem nicht auch gen Babel geführet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Denn also spricht, der HERR Zebaoth von den Saulen und vom Meer und von dem Gestuhle und von den Gefaden, die noch ubrig sind in dieser Stadt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'welche Nebukadnezar, der Konig zu Babel, nicht wegnahm, da er Jechanja, den Sohn Jojakims, den Konig Judas, von Jerusalem wegfuhrete gen Babel samt alien Fursten in Juda und Jerusalem;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'denn so spricht der HERR Zebaoth, der Gott Israels, von den Gefaden, die noch ubrig sind im Hause des HERRN und im Hause des Konigs Judas und zu Jerusalem:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Sie sollen gen Babel geführet werden und daselbst bleiben bis auf den Tag, da ich sie heimsuche, spricht der HERR, und ich sie wiederum herauf an diesen Ort bringen lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Und im selbigen Jahr, im Anfang des Konigreichs Zedekias, des Konigs Judas, im funften Monden des vierten Jahres, sprach Hananja, der Sohn Azurs, ein Prophet von Gibeon, zu mir im Hause des HERRN in Gegenwart der Priester und alles Volks und sagte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'So spricht der HERR Zebaoth, der Gott Israels: Ich habe das Joch des Konigs zu Babel zerbrochen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'und ehe zwei Jahre urn sind, will ich alle Gefafte des Hauses des HERRN, welche Nebukadnezar, der Konig zu Babel, hat von diesem Ort weggenommen und gen Babel gefuhrt, wiederum an diesen Ort bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Dazu Jechanja, den Sohn Jojakims, den Konig Judas, samt alien Gefangenen aus Juda, die gen Babel gefuhret sind, will ich auch wieder an diesen Ort bringen, spricht der HERR; denn ich will das Joch des Konigs zu Babel zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Da sprach der Prophet Jeremia zu dem Propheten Hananja in Gegenwart der Priester und des ganzen Volks, die im Hause des HERRN stunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'und sagte: Amen, der HERR tue also! Der HERR bestatige dein Wort, das du geweissaget hast, daß er die Gefafte aus dem Hause des HERRN von Babel wiederbringe an diesen Ort samt alien Gefangenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Aber doch hore auch dies Wort, das ich vor deinen Ohren rede und vor den Ohren des ganzen Volks:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Die Propheten, die vor mir und vor dir gewesen sind von alters her, die haben wider viel Lander und grofte Konigreiche geweissaget, von Krieg, von Ungluck und von Pestilenz;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'wenn aber ein Prophet von Friede weissaget, den wird man kennen, ob ihn der HERR wahrhaftig gesandt hat, wenn sein Wort erfullet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Da nahm der Prophet Hananja das Joch vom Halse des Propheten Jeremia und zerbrach\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Und Hananja sprach in Gegenwart des ganzen Volks: So spricht der HERR: Ebenso will ich zerbrechen das Joch Nebukadnezars, des Konigs zu Babel, ehe zwei Jahre umkommen, vom Halse aller Volker. Und der Prophet Jeremia ging seines Weges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Aber der HERRN Wort geschah zu Jeremia, nachdem der Prophet Hananja das Joch zerbrochen hatte vom Halse des Propheten Jeremia, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Gehe hin und sage Hananja: So spricht der HERR: Du hast das holzerne Joch zerbrochen; so mache nun ein eisern Joch an jenes Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Denn so spricht der HERR Zebaoth, der Gott Israels: Ein eisern Joch habe ich alien diesen Volkern an den Hals gehanget, damit sie dienen sollen Nebukadnezar, dem Konige zu Babel, und müssen ihm dienen; denn ich habe ihm auch die wilden Here gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Und der Prophet Jeremia sprach zum Propheten Hananja: Hore doch, Hananja! Der HERR hat dich nicht gesandt, und du hast gemacht, dad dies Volk auf Lugen sich verlaftt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Darum spricht der HERR also: Siehe, ich will dich vom Erdboden nehmen; dies Jahr sollst du sterben; denn du hast sie mit deiner Rede vom HERRN abgewendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Also starb der Prophet Hananja desselbigen Jahres im siebenten Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Dies sind die Worte im Briefe, den der Prophet Jeremia sandte von Jerusalem zu den übrigen Altesten die weggefuhrtwaren, und zu den Priestern und Propheten und zum ganzen Volk, das Nebukadnezar von Jerusalem hatte weggefuhrt gen Babel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(nachdem der Konig Jechanja und die Konigin mit den Kammerern und Fursten in Juda und Jerusalem samt den Zimmerleuten und Schmieden zu Jerusalem weg waren),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'durch Eleasa, den Sohn Saphans, und Gemarja, den Sohn Hilkias, welche Zedekia, der Konig Judas, sandte gen Babel zu Nebukadnezar, dem Konige zu Babel, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'So spricht der HERR Zebaoth, der Gott Israels, zu alien Gefangenen, die ich habe von Jerusalem lassen wegfuhren gen Babel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Bauet Hauser, darin ihrwohnen moget; pflanzet Garten, daraus ihr die Fruchte essen moget;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'nehmet Weiber und zeuget Sohne und Tochter; nehmet euren Sohnen Weiber und gebet euren Tochtem Manner, dafi sie Sohne und Tochter zeugen; mehret euch daselbst, daß euer nicht wenig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Suchet der Stadt Bestes, dahin ich euch habe lassen wegfuhren, und betet fur sie zum HERRN; denn wenn\'s ihrwohlgehet, so gehet es euch auch wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Denn so spricht der HERR Zebaoth, der Gott Israels: Laftt euch die Propheten, die bei euch sind, und die Wahrsager nicht betrugen und gehorchet euren Traumen nicht, die euch traumen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'denn sie weissagen euch falsch in meinem Namen. Ich habe sie nicht gesandt, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Denn so spricht der HERR: Wenn zu Babel siebenzig Jahre aus sind, so will ich euch besuchen und will mein gnadiges Wort uber euch erwecken, daß ich euch wieder an diesen Ort bringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Denn ich weift wohl, was ich fur Gedanken über euch habe, spricht der HERR, namlich Gedanken des Friedens und nicht des Leides, daß ich euch gebe das Ende, des ihr wartet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Und ihrwerdet mich anrufen und hingehen und mich bitten, und ich will euch erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Ihrwerdet mich suchen und finden. Denn so ihr mich von ganzem Herzen suchen werdet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'so will ich mich von euch finden lassen, spricht der HERR, und will euer Gefangnis wenden und euch sammeln aus alien Volkern und von alien Orten, dahin ich euch verstoften habe, spricht der HERR; und will euch wiederum an diesen Ort bringen, von dannen ich euch habe lassen wegfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Denn ihr meinet, der HERR habe euch zu Babel Propheten auferweckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Denn also spricht der HERR vom Konige, der auf Davids Stuhl sitzt, und von allem Volk, das in dieser Stadt wohnet, namlich von euren Brudern, die nicht mit euch hinaus gefangen gezogen sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'ja, also spricht der HERR Zebaoth: Siehe, ich will Schwert, Hunger und Pestilenz unter sie schicken und will mit ihnen umgehen wie mit den bosen Feigen, da einem vor ekelt zu essen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'und will hinter ihnen her sein mit Schwert, Hunger und Pestilenz; und will sie in keinem Konigreich auf Erden bleiben lassen, daß sie sollen zum Fluch, zum Wunder, zum Hohn und zum Spott unter alien Volkern werden, dahin ich sie verstoften werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'darum daß sie meinen Worten nicht gehorchen, spricht der HERR, der ich meine Knechte, die Propheten, zu euch stets gesandt habe; aber ihr wolltet nicht horen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Ihr aber alle, die ihr gefangen seid weggefuhret, die ich von Jerusalem habe gen Babel ziehen lassen, horet des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'So spricht der HERR Zebaoth, der Gott Israels, wider Ahab, den Sohn Kolajas, und wider Zedekia, den Sohn Masejas, die euch falsch weissagen in meinem Namen: Siehe, ich will sie geben in die Hande Nebukadnezars, des Kbnigs zu Babel, der soil sie schlagen lassen vor euren Augen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'daß man wird aus denselbigen einen Fluch machen unter alien Gefangenen aus Juda, die zu Babel sind, und sagen: Der HERR tue dir wie Zedekia und Ahab, welche der Konig zu Babel auf Feuer braten lieft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'darum daß sie eine Torheit in Israel begingen und trieben Ehebruch mitderandern Weibern und predigten falsch in meinem Namen, das ich ihnen nicht befohlen hatte. Solches weift ich und zeuge es, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Und wider Semaja von Nehalam sollst du sagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'So spricht der HERR Zebaoth, der Gott Israels: Darum daß du unter deinem Namen hast Briefe gesandt zu allem Volk, das zu Jerusalem ist, und zum Priester Zephanja, dem Sohn Masejas, und zu alien Priestern und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Der HERR hat dich zum Priester gesetzt anstatt des Priesters Jehojada, daß ihr sollt Aufseher sein im Hause des HERRN über alle Wahnsinnigen und Weissager, daß du sie in Kerker und Stock legest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Nun, warum strafst du denn nicht Jeremia von Anathoth, der euch weissaget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'darum daß er zu uns gen Babel geschickt hat und lassen sagen: Es wird noch lange wahren; bauet Hauser, darin ihr wohnet, und pflanzet Garten, daß ihr die Fruchte davon esset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Denn Zephanja, der Priester, hatte denselben Brief gelesen und den Propheten Jeremia lassen zuhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Darum geschah des HERRN Wort zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sende hin zu alien Gefangenen und laft ihnen sagen: So spricht der HERR wider Semaja von Nehalam: Darum daß euch Semaja weissaget, und ich habe ihn doch nicht gesandt, und macht, daß ihr auf Lügen vertrauet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'darum spricht der HERR also: Siehe, ich will Semaja von Nehalam heimsuchen samt seinem Samen, daß der Seinen keiner soil unter diesem Volk bleiben, und soli das Gute nicht sehen, das ich meinem Volk tun will, spricht der HERR; denn er hat sie mit seiner Rede vom HERRN abgewendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Dies ist das Wort, das vom HERRN geschah zu Jeremia:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So spricht der HERR, der Gott Israels: Schreibe dir alle Worte in ein Buch, die ich zu dir rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Denn siehe, es kommt die Zeit, spricht der HERR, daß ich das Gefangnis meines Volks, beide, Israels und Judas, wenden will, spricht der HERR, und will sie wiederbringen in das Land, das ich ihren Vatern gegeben habe, daß sie es besitzen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Dies sind aber die Worte, welche der HERR redetvon Israel und Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Denn so spricht der HERR: Wir horen ein Geschrei des Schreckens; es ist eitel Furcht da und kein Friede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Aber forschet doch und sehet, ob ein Mannsbild gebaren moge? Wie geht es denn zu, daß ich alle Manner sehe ihre Hande auf ihren Huften haben, wie Weiber in Kindesnoten, und alle Angesichte so bleich sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Es ist ja ein grafter Tag, und seinesgleichen ist nicht gewesen, und ist eine Zeit der Angst in Jakob; noch soli ihm daraus geholfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Es soil aber geschehen zu derselbigen Zeit, spricht der HERR Zebaoth, daß ich sein Joch von deinem Halse zerbrechen will und deine Bande zerreiften, daß er darin nicht mehr den Fremden dienen muft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'sondern dem HERRN, ihrem Gott, und ihrem Konige David, welchen ich ihnen erwecken will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Darum furchte du dich nicht, mein Knecht Jakob, spricht der HERR, und entsetze dich nicht, Israel! Denn siehe, ich will dir helfen aus fernen Landen und deinem Samen aus dem Lande ihres Gefangnisses, daß Jakob soil wiederkommen, in Frieden leben und Genuge haben; und niemand soil ihn schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Denn ich bin bei dir, spricht der HERR, daß ich dir helfe. Denn ich will\'s mit alien Heiden ein Ende machen, dahin ich dich zerstreuet habe; aber mit dir will ich’s nicht ein Ende machen; zuchtigen aber will ich dich mit Mafte, daß du dich nicht unschuldig haltest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Denn also spricht der HERR: Dein Schade ist verzweifelt bose, und deine Wunden sind unheilbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Deine Sache handelt niemand, daß er sie verbande; es kann dich niemand heilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle deine Liebhaber vergessen dein, fragen nichts danach. Ich habe dich geschlagen, wie ich einen Feind schluge, mit unbarmherziger Staupe urn deiner groften Missetat und urn deiner starken Sunden willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Was schreiest du uber deinen Schaden und uber deinen verzweifelt bosen Schmerzen? Habe ich dir doch solches getan urn deiner groften Missetat und urn deiner starken Sunden willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Darum alle, die dich gefressen haben, sollen gefressen werden, und alle, die dich geangstet haben, sollen alle gefangen werden, und die dich beraubet haben, sollen beraubet werden, und alle, die dich geplundert haben, sollen geplundert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Aber dich will ich wieder gesund machen und deine Wunden heilen, spricht der HERR, darum daß man dich nennet die Verstoftene, und Zion sei, nach der niemand frage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So spricht der HERR: Siehe, ich will das Gefangnis der Hütten Jakobs wenden und mich uber seine Wohnung erbarmen; und die Stadt soil wieder auf ihre Hugel gebauet werden, und der Tempel soli stehen nach seiner Weise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Und soil von dannen herausgehen Lob- und Freudengesang; denn ich will sie mehren und nicht mindern; ich will sie herrlich machen und nicht kleinern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Ihre Sohne sollen sein gleichwie vorhin, und ihre Gemeine vor mir gedeihen; denn ich will heimsuchen alle, die sie plagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Und ihr Furst soil aus ihnen herkommen und ihr Herrscher von ihnen ausgehen und er soil zu mir nahen; denn wer ist der, so mit willigem Herzen zu mir nahet? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Und ihr sollt mein Volk sein, und ich will euer Gottsein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Siehe, es wird ein Wetter des HERRN mit Grimm kommen, ein schrecklich Ungewitter wird den Gottlosen auf den Kopf fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Denn des HERRN grimmiger Zorn wird nicht nachlassen, bis er tue und ausrichte, was er im Sinn hat. Zur letzten Zeit werdet ihr solches erfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Zur selbigen Zeit, spricht der HERR, will ich aller Geschlechter Israels Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So spricht der HERR: Das Volk, so uberblieben ist vom Schwert, hat Gnade funden in der Wüste; Israel zeucht hin zu seiner Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Der HERR istmirerschienen von feme: Ich habe dich je und je geliebet, darum habe ich dich zu mir gezogen aus lauter Güte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Wohlan, ich will dich wiederum bauen, daß du sollst gebauet heiften. Du Jungfrau Israel, du sollst noch frohlich pauken und herausgehen an den Tanz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Du sollst wiederum Weinberge pflanzen an den Bergen Samaria; pflanzen wird man und dazu pfeifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Denn es wird die Zeit noch kommen, daß die Huter an dem Gebirge Ephraim werden rufen: Wohlauf und laftt uns hinaufgehen gen Zion zu dem HERRN, unserm Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Denn also spricht der HERR: Rufet uber Jakob mit Freuden und jauchzet uber das Haupt unter den Heiden; rufet laut, ruhmet und sprechet: HERR, hilf deinem Volk, den Ubrigen in Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Siehe, ich will sie aus dem Lande der Mitternacht bringen und will sie sammeln aus den Enden der Erde, beide, Blinde, Lahme, Schwangere und Kindbetterinnen, daß sie mitgroftem Haufen wieder hieher kommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Sie werden weinend kommen und betend, so will ich sie leiten; ich will sie leiten an den Wasserbachen auf schlechtem Wege, daß sie sich nicht stoften; denn ich bin Israels Vater, so ist Ephraim mein erstgeborner Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Horet, ihr Heiden, des HERRN Wort und verkundiget es feme in die Inseln und sprechet: Der Israel zerstreuet hat, der wird\'s auch wieder sammeln, und wird sie hüten wie ein Hirte seine Herde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Denn der HERR wird Jakob erlosen und von der Hand des Machtigen erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Und sie werden kommen und auf der Hohe zu Zion jauchzen und werden sich zu den Gaben des HERRN haufen, namlich zum Getreide, Most, 01 und jungen Schafen und Ochsen, daß ihre Seele wird sein wie ein wasserreicher Garten und nicht mehr bekümmert sein sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Alsdann werden die Jungfrauen frohlich am Reigen sein, dazu die junge Mannschaft und die Alten miteinander. Denn ich will ihr Trauern in Freude verkehren und sie trosten und sie erfreuen nach ihrer Betrubnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Und ich will der Priester Herz voll Freude machen, und mein Volk soil meiner Gaben die Fülle haben, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So spricht der HERR: Man horet eine klagliche Stimme und bitteres Weinen auf der Hohe; Rahel weinet uber ihre Kinder und will sich nicht trosten lassen uber ihre Kinder, denn es ist aus mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Aber der HERR spricht also: laft dein Schreien und Weinen und die Tranen deiner Augen; denn deine Arbeit wird wohl belohnet werden, spricht der HERR. Sie sollen wiederkommen aus dem Lande des Feindes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Und deine Nachkommen haben viel Guteszu gewarten, spricht der HERR; denn deine Kinder sollen wieder in ihre Grenze kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Ich habe wohl gehoret, wie Ephraim klagt: Du hast mich gezuchtiget, und ich bin auch gezuchtiget wie ein geil Kalb. Bekehre du mich, so werde ich bekehret; denn du, HERR, bist mein Gotti');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Da ich bekehret ward, tat ich Bufte; denn nachdem ich gewitzigt bin, schlage ich mich auf die Hufte. Denn ich bin zuschanden worden und stehe schamrot; denn ich muft leiden den Hohn meiner Jugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, '1st nicht Ephraim mein teurer Sohn und mein trautes Kind? Denn ich denke noch wohl daran, was ich ihm geredet habe; darum bricht mir mein Herz geqen ihn, daß ich mich sein erbarmen muft, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Richte dir auf Grabzeichen, setze dir Trauermale und richte dein Herz auf die gebahnte Strafte, darauf ich gewandelt habe. Kehre wieder, Jungfrau Israel; kehre dich wieder zu diesen deinen Stadten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Wie lange willst du in der Irre gehen, du abtrunnige Tochter? Denn der HERR wird ein Neues im Lande erschaffen: das Weib wird den Mann umgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So spricht der HERR Zebaoth, der Gott Israels: Man wird noch dies Wort wieder reden im Lande Juda und in seinen Stadten, wenn ich ihr Gefangnis wenden werde: Der HERR segne dich, du Wohnung der Gerechtigkeit, du heiliger Berg!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Und Juda samt alien seinen Stadten sollen drinnen wohnen, dazu Ackerleute und die mit Herden umherziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Denn ich will die müden Seelen erquicken und die bekummerten Seelen sattigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Darum bin ich aufgewacht und sah auf und habe so sanft geschlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Siehe, es kommt die Zeit, spricht der HERR, daß ich das Haus Israel und das Haus Juda besamen will, beide, mit Menschen und Vieh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Und gleichwie ich uber sie gewacht habe, auszureuten, zu reiften, abzubrechen, zu verderben und zu plagen, also will ich uber sie wachen, zu bauen und zu pflanzen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Zur selbigen Zeit wird man nicht mehr sagen: Die Vater haben Herlinge gegessen, und der Kinder Zahne sind stumpf worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'sondern ein jeglicher wird urn seiner Missetat willen sterben; und welcher Mensch Herlinge isset, dem sollen seine Zahne stumpf werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Siehe, es kommt die Zeit, spricht der HERR, da will ich mit dem Hause Israel und mit dem Hause Juda einen neuen Bund machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'nicht wie der Bund gewesen ist, den ich mit ihren Vatern machte, da ich sie bei der Hand nahm, daß ich sie aus Agyptenland fuhrete, welchen Bund sie nicht gehaiten haben, und ich sie zwingen muftte, spricht der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'sondern das soil der Bund sein, den ich mit dem Hause Israel machen will nach dieser Zeit, spricht der HERR: Ich will mein Gesetz in ihr Herz geben und in ihren Sinn schreiben; und sie sollen mein Volk sein, so will ich ihr Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Und wird keiner den andern noch ein Bruder den andern lehren und sagen: Erkenne den HERRN! sondern sie sollen mich alle kennen, beide, klein und graft, spricht der HERR. Denn ich will ihnen ihre Missetat vergeben und ihrer Sünde nimmermehr gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So spricht der HERR, der die Sonne dem Tage zum Licht gibt und den Mond und die Sterne nach ihrem Lauf der Nacht zum Licht, der das Meer bewegt, daß seine Wellen brausen, HERR Zebaoth ist sein Name:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Wenn solche Ordnungen abgehen vormir, spricht der HERR, so soil auch aufhoren der Same Israels, daß er nicht mehr ein Volk vor mir sei ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So spricht der HERR: Wenn man den Himmel oben kann messen und den Grund der Erde erforschen, so will ich auch verwerfen den ganzen Samen Israels urn alles, das sie tun, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Siehe, es kommt die Zeit, spricht der HERR, daß die Stadt des HERRN soli gebauet werden vom Turm Hananeel an bis ans Ecktor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Und die Richtschnur wird neben demselben weiter herausgehen bis an den Hugel Gareb und sich gen Gaath wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Und das ganze Tal der Leichen und der Asche samt dem ganzen Acker bis an den Bach Kidron, bis zu der Ecke am Rofttor gegen Morgen wird dem HERRN heilig sein, daß es nimmermehr zerbrochen noch abgebrochen soil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Dies ist das Wort, das vom HERRN geschah zu Jeremia im zehnten Jahr Zedekias, des Konigs Judas, welches ist das achtzehnte Jahr Nebukadnezars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Dazumal belagerte das Heer des Konigs zu Babei Jerusalem. Aber der Prophet Jeremia lag gefangen im Vorhofe des Gefangnisses am Hause des Konigs Judas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'dahin Zedekia, der Konig Judas, ihn hatte lassen verschlieften und gesagt: Warum weissagest du und sprichst: So spricht der HERR: Siehe, ich gebe diese Stadt in die Hande des Konigs zu Babel, und er soil sie gewinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'und Zedekia, der Konig Judas, soil den Chaldaern nicht entrinnen, sondern ich will ihn dem Konige zu Babel in die Hande geben, daß er mündlich mit ihm reden und mit seinen Augen ihn sehen soil;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'und erwird Zedekia gen Babel führen, da soil er auch bleiben, bis daß ich ihn heimsuche, spricht der HERR; denn ob ihr schon wider die Chaldaer streitet, soil euch doch nichts gelingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Und Jeremia sprach: Es ist des HERRN Wort geschehen zu mir und spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Siehe, Hanameel, der Sohn Sallums, deines Vetters, kommt zu dir und wird sagen: Lieber, kaufe du meinen Acker zu Anathoth; denn du hast das nachste Freundrecht dazu, daß du ihn kaufen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Also kam Hanameel, meines Vetters Sohn, wie der HERR gesagt hatte, zu mir vor den Hof des Gefangnisses und sprach zu mir: Lieber, kaufe meinen Acker zu Anathoth, der im Lande Benjamin liegt; denn du hast Erbrecht dazu und du bist der Nachste; Lieber, kaufe ihn! Da merkte ich, daß es des HERRN Wort ware,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'und kaufte den Acker von Hanameel, meines Vetters Sohn, zu Anathoth und wog ihm das Geld dar, sieben Sekel und zehn Silberlinge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'und schrieb einen Brief und versiegelte ihn und nahm Zeugen dazu und wog das Geld darauf einer Waage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Und nahm zu mir den versiegelten Kaufbrief nach dem Recht und Gewohnheit und eine offene Abschrift');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'und gab den Kaufbrief Baruch, dem Sohn Nerias, des Sohns Mahasejas, in Gegenwart Hanameels, meines Vetters, und der Zeugen, die im Kaufbriefe geschrieben stunden, und alter Juden, die am Hofe des Gefangnisses wohneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'und befahl Baruch vor ihren Augen und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'So spricht der HERR Zebaoth, der Gott Israels: Nimm diese Briefe, den versiegelten Kaufbrief samt dieser offenen Abschrift und lege sie in ein irden Gefali, daß sie lange bleiben mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Denn so spricht der HERR Zebaoth, der Gott Israels: Noch soli man Hauser, Acker und Weinberge kaufen in diesem Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Und da ich den Kaufbrief hatte Baruch, dem Sohn Nerias, gegeben, betete ich zum HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach, Herr HERR, siehe, du hast Himmel und Erde gemacht durch deine grolie Kraft und durch deinen ausgestreckten Arm, und ist kein Ding vor dir unmoglich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'der du wohltust viel Tausenden und vergiltst die Missetat der Vater in den Busen ihrer Kinder nach ihnen, du grower und starker Gott; HERR Zebaoth ist dein Name;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'groli von Rat und machtig von Tat; und deine Augen stehen often uber alle Wege der Menschenkinder, daß du einem jeglichen gebest nach seinem Wandel und nach der Frucht seines Wesens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'der du in Agyptenland hast Zeichen und Wunder getan bis auf diesen Tag, beide, an Israel und Menschen, und hast dir einen Namen gemacht, wie er heutigestages ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'und hast dein Volk Israel aus Agyptenland geführet durch Zeichen und Wunder, durch eine machtige Hand, durch ausgestreckten Arm und durch groli Schrecken');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'und hast ihnen dies Land gegeben, welches du ihren Vatern geschworen hattest, daß du es ihnen qeben wolltest, ein Land, da Milch und Honiq innen fleulit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'und da sie hineinkamen und es besalien, gehorchten sie deiner Stimme nicht, wandelten auch nicht nach deinem Gesetze, und alles, was du ihnen gebotest, daß sie tun sollten, das lielien sie, darum du auch ihnen all dies Ungluck lieliest widerfahren:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Siehe, diese Stadt ist belagert, daß sie gewonnen und vorßchwert, Hunger und Pestilenz in der Chaldaer Hande, welche wider sie streiten, gegeben werden muli; und wie du geredet hast, so gehet es, das siehest du;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'und du, Herr HERR, sprichst zu mir: Kaufe du einen Acker urn Geld und nimm Zeugen dazu, so doch die Stadt in der Chaldaer Hande gegeben wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Und des HERRN Wort geschah zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Siehe, ich, der HERR, bin ein Gott alles Fleisches. Sollte mir etwas unmoglich sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Darum so spricht der HERR also: Siehe, ich gebe diese Stadt in der Chaldaer Hande und in die Hand Nebukadnezars, des Konigs zu Babel; und er soil sie gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Und die Chaldaer so wider diese Stadt streiten, werden hereinkommen und sie mit Feuer anstecken und verbrennen samt den Hausern, da sie auf den Dachern Baal gerauchert und andern Gottern Trankopfer geopfert haben, auf daß sie mich erzurneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Denn die Kinder Israel und die Kinder Juda haben von ihrer Jugend auf getan, das mir libel gefallt, und die Kinder Israel haben mich erzurnet durch ihrer Hande Werk, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Denn seit der Zeit diese Stadt gebauet ist, bis auf diesen Tag, hat sie mich zornig und grimmig gemacht, daß ich sie muli von meinem Angesicht wegtun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'urn all der Bosheit willen der Kinder Israel und der Kinder Juda, die sie getan haben, daß sie mich erzurneten. Sie, ihre Konige, Fursten, Priester und Propheten, und die in Juda und Jerusalem wohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'haben mir den Rücken und nicht das Angesicht zugekehret, wiewohl ich sie stets lehren lieli; aber sie wollten nicht horen noch sich bessern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Dazu haben sie ihre Greuel in das Haus gesetzt, das von mir den Namen hat, daß sie es verunreinigten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'und haben die Hohen des Baal gebauet im Tal Ben-Hinnom, daß sie ihre Sohne und Tochter dem Moloch verbrenneten, davon ich ihnen nichts befohlen habe, und ist mir nie in Sinn kommen, daß sie solchen Greuel tun sollten, damit sie Juda also zu Sunden brachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Und nun, um deswillen spricht der HERR, der Gott Israels, also von dieser Stadt, davon ihr saget, daß sie werde vor Schwert, Hunger und Pestilenz in die Hande des Konigs zu Babel gegeben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Siehe, ich will sie sammeln aus alien Landen, dahin ich sie verstoße durch meinen grol Len Zorn, Grimm und Unbarmherzigkeit, und will sie wiederum an diesen Ort bringen, daß sie sollen sicher wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Und sie sollen mein Volk sein, so will ich ihr Gott sein');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'und will ihnen einerlei Herz und Wesen geben, daß sie mich furchten sollen ihr Leben lang, auf daß ihnen und ihren Kindern nach ihnen wohlgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Und will einen ewigen Bund mit ihnen machen, daß ich nicht will ablassen, ihnen Gutes zu tun, und will ihnen meine Furcht ins Herz geben, daß sie nicht von mirweichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Und soil meine Lust sein, daß ich ihnen Gutes tun soil; und ich will sie in diesem Lande pflanzen, treulich, von ganzem Herzen und von ganzer Seele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Denn so spricht der HERR: Gleichwie ich uber dies Volk habe kommen lassen all dies grotie Ungluck, also will ich auch alles Gute uber sie kommen lassen, das ich ihnen geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Und sollen noch Acker gekauft werden in diesem Lande, davon ihr saget, es werde wüst liegen, daß weder Leute noch Vieh drinnen bleibe, und werde in der Chaldaer Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Dennoch wird man Acker um Geld kaufen und verbriefen, versiegeln und bezeugen im Lande Benjamin und um Jerusalem her und in den Stadten Judas, in Stadten auf den Gebirgen, in Stadten in Grunden und in Stadten gegen Mittag. Denn ich will ihr Gefangnis wenden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Und des HERRN Wort geschah zu Jeremia zum andernmal, da er noch im Vorhof des Gefangnisses verschlossen war, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'So spricht der HERR, der solches macht, tut und ausrichtet; HERR istsein Name:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Rufe mich, so will ich dir antworten und will dir anzeigen grolie und gewaltige Dinge, die du nicht weilit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Denn so spricht der HERR, der Gott Israels, von den Hausern dieser Stadt und von den Hausern der Konige Judas, welche abgebrochen sind, Bollwerk zu machen zur Wehre,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'und von denen, so hereinkommen sind, daß sie wider die Chaldaer streiten mogen, daß sie dieselbigen füllen müssen mittoten Leichnamen, welche ich in meinem Zorn und Grimm erschlagen will; denn ich habe mein Angesicht von dieser Stadt verborgen um aller ihrer Bosheit willen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Siehe, ich will sie heilen und gesund machen und will sie des Gebets um Frieden und Treue gewahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Denn ich will das Gefangnis Judas und das Gefangnis Israels wenden und will sie bauen wie von Anfang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'und will sie reinigen von aller Missetat, damit sie wider mich gesundiget haben, und will ihnen vergeben alle Missetat, damit sie wider mich gesundigt und übertreten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Und das soil mir ein frohlicher Name, Ruhm und Preis sein unter alien Heiden auf Erden, wenn sie horen werden all das Gute, das ich ihnen tue. Und werden sich verwundern und entsetzen uber all dem Guten und uber all dem Frieden, den ich ihnen geben will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So spricht der HERR: An diesem Ort, davon ihr saget: Er ist wüst, weil weder Leute noch Vieh in den Stadten Judas und auf den Gassen zu Jerusalem bleibet, die so verwüstet sind, dad weder Leute noch Burger noch Vieh drinnen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'wird man dennoch wiederum horen Geschrei von Freude und Wonne, die Stimme des Brautigams und der Braut und die Stimme derer, so da sagen: Danket dem HERRN Zebaoth, dad er so gnadig ist und tut immerdar Gutes! und derer, so da Dankopfer bringen zum Hause des HERRN. Denn ich will des Landes Gefanqnis wenden wie von Anfang, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So spricht der HERR Zebaoth: An diesem Ort, der so wüst ist, dad weder Leute noch Vieh drinnen sind, und in alien seinen Stadten werden dennoch wiederum Hirtenhausersein, die da Herden weiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'beide, in Stadten auf den Gebirgen und in Stadten in Grunden und in Stadten gegen Mittag, im Lande Benjamin und um Jerusalem her und in Stadten Judas; es sollen dennoch wiederum die Herden gezahlet aus- und eingehen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Siehe, es kommt die Zeit, spricht der HERR, daß ich das gnadige Wort erwecken will, welches ich dem Hause Israel und dem Hause Juda geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'In denselbigen Tagen und zur selbigen Zeit will ich dem David ein gerecht Gewachs aufgehen lassen; und soil ein Konig sein, der wohl regieren wird, und soil Recht und Gerechtigkeit anrichten auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Zur selbigen Zeit soil Juda geholfen werden und Jerusalem sicher wohnen; und man wird ihn nennen: Der HERR, der unsere Gerechtigkeit ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Denn so spricht der HERR: Es soil nimmermehr fehlen, es soil einer von David sitzen auf dem Stuhl des Hauses Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Desgleichen soil\'s nimmermehr fehlen, es sollen Priester und Leviten sein vor mir, die da Brandopfer tun und Speisopfer anzünden und Opfer schlachten ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Und des HERRN Wort geschah zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'So spricht der HERR: Wenn mein Bund aufhoren wird mit dem Tage und Nacht, dafi nicht Tag und Nacht sei zu seiner Zeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'so wird auch mein Bund aufhoren mit meinem Knechte David, daß er nicht einen Sohn habe zum Konige auf seinem Stuhl, und mit den Leviten und Priestern, meinen Dienern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Wie man des Himmels Heer nicht zahlen noch den Sand am Meer nicht messen kann, also will ich mehren den Samen Davids, meines Knechts, und die Leviten, die mirdienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Und des HERRN Wort geschah zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Hast du nicht gesehen, was dies Volk redet und spricht: Hat doch der HERR auch die zwei Geschlechter verworfen, welche er auserwahlet hatte; und lastern mein Volk, als sollten sie nicht mehr mein Volksein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So spricht der HERR: Halte ich meinen Bund nicht mit Tag und Nacht noch die Ordnung des Himmels und der Erde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'so will ich auch verwerfen den Samen Jakobs und Davids, meines Knechts, daß ich nicht aus ihrem Samen nehme, die da herrschen uber den Samen Abrahams, Isaaks und Jakobs. Denn ich will ihr Gefangnis wenden und mich uber sie erbarmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Dies ist das Wort, das vom HERRN geschah zu Jeremia, da Nebukadnezar, der Konig zu Babel, samt all seinem Heer und alien Konigreichen auf Erden, so unter seiner Gewalt waren, und alien Volkern stritten wider Jerusalem und alle ihre Stadte, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'So spricht der HERR, der Gott Israels: Gehe hin und sage Zedekia, dem Konige Judas, und sprich zu ihm: So spricht der HERR: Siehe, ich will diese Stadt in die Hande des Konigs zu Babel geben, und er soil sie mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Und du sollst seiner Hand nicht entrinnen, sondern gegriffen und in seine Hand gegeben werden, daß du ihn mit Augen sehen und mündlich mit ihm reden wirst und gen Babel kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'So hore doch, Zedekia, du Konig Judas, des HERRN Wort! So spricht der HERR von dir: Du sollst nicht durchs Schwert sterben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'sondern du sollst im Frieden sterben. Und wie man uber deine Vater, die vorigen Konige, so vor dir gewesen sind, gebrannt hat, so wird man auch uber dich brennen und dich klagen: Ach, Herr! Denn ich habe es geredet, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Und der Prophet Jeremia redete alle diese Worte zu Zedekia, dem Konige Judas, zu Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'da das Heer des Konigs zu Babel schon stritt wider Jerusalem und wider alle ubrigen Stadte Judas, namlich wider Lachis und Aseka; denn diese waren, als die festen Stadte, noch uberblieben unter den Stadten Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Dies ist das Wort, so vom HERRN geschah zu Jeremia, nachdem der Konig Zedekia einen Bund gemacht hatte mit dem ganzen Volk zu Jerusalem, ein Freijahr auszurufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'daß ein jeglicher seinen Knecht und ein jeglicher seine Magd, so Ebraer und Ebraerinnen waren, sollte freigeben, daß kein Jude den andern unter denselben leibeigen hielte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Da gehorchten alle Fursten und alles Volk, die solchen Bund eingegangen waren, daß ein jeglicher sollte seinen Knecht und seine Magd freigeben und sie nicht mehr leibeigen halten, und gaben sie los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Aber danach kehreten sie sich urn und forderten die Knechte und Magde wieder zu sich, die sie freigegeben hatten, und zwangen sie, daß sie Knechte und Magde sein muftten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Da geschah des HERRN Wort zu Jeremia vom HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'So spricht der HERR, der Gott Israels: Ich habe einen Bund gemacht mit euren Vatern, da ich sie aus Agyptenland, aus dem Diensthause, führete, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Wenn sieben Jahre urn sind, so soli ein jeglicher seinen Bruder, der ein Ebraer ist und sich ihm verkauft und sechs Jahre gedienet hat, frei von sich lassen. Aber eure Vater gehorchten mir nicht und neigten ihre Ohren nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'So habt ihreuch heute bekehret und getan, das mir wohlgefiel, daß ihr ein Freijahr lieftet ausrufen, ein jeglicher seinem Nachsten, und habt des einen Bund gemacht vor mir im Hause, das nach meinem Namen genannt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Aber ihrseid umgeschlagen und entheiliget meinen Namen; und ein jeglicher fordert seinen Knecht und seine Magd wieder, die ihr hattet freigegeben, daß sie ihr selbst eigen waren, und zwinget sie nun, daß sie eure Knechte und Magde sein müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Darum spricht der HERR also: Ihrgehorchet mir nicht, daß ihr ein Freijahr ausriefet, ein jeglicher seinem Bruder und seinem Nachsten; siehe, so rufe ich, spricht der HERR, euch ein Freijahr aus zum Schwert, zur Pestilenz, zum Hunger und will euch in keinem Konigreich auf Erden bleiben lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Und will die Leute, so meinen Bund ubertreten und die Worte des Bundes, den sie vor mir gemacht haben, nicht halten, so machen wie das Kalb, das sie in zwei Stucke geteilet haben und zwischen den Teilen hingegangen sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'namlich die Fursten Judas, die Fursten Jerusalems, die Kammerer, die Priester und das ganze Volk im Lande, so zwischen des Kalbes Stricken hingegangen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Und will sie geben in ihrer Feinde Hand und derer, die ihnen nach dem Leben stehen, daß ihre Leichname sollen den Vogeln unter dem Himmel und den Tieren auf Erden zur Speise werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Und Zedekia, den Konig Judas, und seine Fursten will ich geben in die Hande ihrer Feinde und derer, die ihnen nach dem Leben stehen, und dem Heer des Konigs zu Babel, die jetzt von euch abgezogen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Denn siehe, ich will ihnen befehlen, spricht der HERR, und will sie wieder vor diese Stadt bringen, und sollen wider sie streiten und sie gewinnen und mit Feuerverbrennen; und will die Stadte Judas verwusten, dais niemand mehr da wohnen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Dies ist das Wort, das vom HERRN geschah zu Jeremia zur Zeit Jojakims, des Sohns Josias, des Konigs Judas, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Gehe hin in der Rechabiter Haus und rede mit ihnen und führe sie in des HERRN Haus in der Kapellen eine, und schenke ihnen Wein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Da nahm ich Jasanja, den Sohn Jeremias, des Sohns Habazinjas, samt seinen Brudern und alien seinen Sohnen und das ganze Haus der Rechabiter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'und führete sie in des HERRN Haus, in die Kapelle der Kinder Hanans, des Sohns Jegdaljas, des Mannes Gottes, welche neben der Fursten Kapelle ist, uber der Kapelle Masejas, des Sohns Sallums, des Torhuters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Und ich setzte den Kindern von der Rechabiter Hause Becher voll Weins und Schalen vor und sprach zu ihnen: Trinket Wein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Sie aber antworteten: Wir trinken nicht Wein; denn unser Vater Jonadab, der Sohn Rechabs, hat uns geboten und gesagt: Ihr und eure Kinder sollet nimmermehr keinen Wein trinken');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'und kein Haus bauen, keinen Samen saen, keinen Weinberg pflanzen noch haben, sondern sollet in Hütten wohnen euer Leben lang, auf daß ihr lange lebet im Lande, darin ihr wallet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Also gehorchen wir der Stimme unsers Vaters Jonadab, des Sohns Rechabs, in allem, das er uns geboten hat, daß wir keinen Wein trinken unser Leben lang, weder wir noch unsere Weiber noch Sohne noch Tochter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'und bauen auch keine Hauser, darin wir wohneten, und haben weder Weinberge noch Acker noch Samen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'sondern wohnen in Hütten und gehorchen und tun alles, wie unser Vater Jonadab geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Als aber Nebukadnezar der Konig zu Babel, herauf ins Land zog, sprachen wir: Kommt, last uns gen Jerusalem ziehen vor dem Heer der Chaldaer und Syrer; und sind also zu Jerusalem geblieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Da geschah des HERRN Wort zu Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'So spricht der HERR Zebaoth, der Gott Israels: Gehe hin und sprich zu denen in Juda und zu den Bürgem zu Jerusalem: Wollt ihreuch denn nicht bessem, daß ihr meinen Worten gehorchet? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Die Worte Jonadabs, des Sohns Rechabs, die er seinen Kindern geboten hat daß sie nicht sollen Wein trinken, werden gehalten; und trinken keinen Wein bis auf diesen Tag, darum dafi sie ihres Vaters Gebot gehorchen. Ich aber habe stets euch predigen lassen; doch gehorchet ihr mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'So habe ich auch stets zu euch gesandt alle meine Knechte, die Propheten, und lassen sagen: Bekehret euch, ein jeglicher von seinem bosen Wesen, und bessert euren Wandel und folget nicht andern Gottern nach, ihnen zu dienen, so sollt ihr im Lande bleiben, welches ich euch und euren Vatern gegeben habe. Aber ihr wolltet eure Ohren nicht neigen noch mir gehorchen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'so doch die Kinder Jonadabs, des Sohns Rechabs, haben ihres Vaters Gebot, das er ihnen geboten hat, gehalten. Aber dies Volk gehorchet mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Darum so spricht der HERR, der Gott Zebaoth und der Gott Israels: Siehe, ich will über Juda und uber alle Burger zu Jerusalem kommen lassen all das Ungluck, das ich wider sie geredet habe, darum daß ich zu ihnen geredet habe, und sie nicht wollen horen, ich habe gerufen, und sie mir nicht wollen antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Und zum Hause der Rechabiter sprach Jeremia: So spricht der HERR Zebaoth, der Gott Israels: Darum dafi ihr dem Gebot eures Vaters Jonadab habt gehorchet und alle seine Gebote gehalten und alles getan, was er euch geboten hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'darum spricht der HERR Zebaoth, der Gott Israels, also: Es soil dem Jonadab, dem Sohn Rechabs, nimmer fehlen, es soil jemand von den Seinen allezeit vor mirstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Im vierten Jahr Jojakims, des Sohns Josias, des Konigs Judas, geschah dies Wort zu Jeremia vom HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Nimm ein Buch und schreibe darein alle Reden, die ich zu dir geredet habe über Israel, über Juda und alle Volker von der Zeit an, da ich zu dir geredet habe, namlich von der Zeit Josias an bis auf diesen Tag,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'ob vielleicht das Haus Juda, wo sie horen all das Unglück, das ich ihnen gedenke zu tun, sich bekehren wollten, ein jeglicher von seinem bosen Wesen, damit ich ihnen ihre Missetat und Sünde vergeben konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Da rief Jeremia Baruch, den Sohn Nerias. Derselbige Baruch schrieb in ein Buch aus dem Munde Jeremias alle Reden des HERRN, die erzu ihm geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Und Jeremia gebot Baruch und sprach: Ich bin gefangen, daß ich nicht kann in des HERRN Haus gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Du aber gehe hinein und lies das Buch, darein du des HERRN Reden aus meinem Munde geschrieben hast, vor dem Volk im Hause des HERRN am Fasttage; und sollst sie auch lesen vor den Ohren des ganzen Juda, die aus ihren Stadten hereinkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'ob sie vielleicht sich mit Beten vor dem HERRN demutigen wollten und sich bekehren, ein jeglicher von seinem bosen Wesen; denn der Zorn und Grimm ist graft, davon der HERR wider dies Volk geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Und Baruch, der Sohn Nerias, tat alles, wie ihm der Prophet Jeremia befohlen hatte, dati er die Reden des HERRN aus dem Buch lase im Hause des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Es begab sich aber im funften Jahr Jojakims, des Sohns Josias, des Konigs Judas, im neunten Monden, dati man ein Fasten verkundigte vor dem HERRN allem Volkzu Jerusalem und allem Volk, das aus den Stadten Judas gen Jerusalem kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Und Baruch las aus dem Buch die Reden Jeremias im Hause des HERRN, in der Kapelle Gemarjas, des Sohns Saphans, des Kanzlers, im obern Vorhofe vor dem neuen Tor am Hause des HERRN, vor dem ganzen Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Da nun Michaja, der Sohn Gemarjas, des Sohns Saphans, alle Reden des HERRN gehoret hatte aus dem Buch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'ging er hinab in des Konigs Haus, in die Kanzlei. Und siehe, daselbst saften alle Fürsten: Elisama, der Kanzler, Delaja, der Sohn Semajas, Elnathan, der Sohn Achbors, Gemarja, der Sohn Saphans, und Zedekia, der Sohn Hananjas, samt alien Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Und Michaja zeigte ihnen an alle Reden, die er gehoret hatte, da Baruch las aus dem Buch vor den Ohren des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Da sandten alle Fursten Judi, den Sohn Nethanjas, des Sohns Selemjas, des Sohns Chusis, nach Baruch und lieften ihm sagen:. Nimm das Buch, daraus du vor dem Volk gelesen hast, mit dir und komm! Und Baruch, der Sohn Nerias, nahm das Buch mit sich und kam zu ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Und sie sprachen zu ihm: Setze dich und lies, daß wir\'s horen! Und Baruch las ihnen vor ihren Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Und da sie alle die Reden horeten, entsetzten sie sich einer gegen den andern und sprachen zu Baruch: Wirwollen alle diese Reden dem Konige anzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Und fragten den Baruch: Sage uns, wie hast du alle diese Reden aus seinem Munde geschrieben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruch sprach zu ihnen: Er las mir alle diese Reden aus seinem Munde, und ich schrieb sie mit Tinte ins Buch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Da sprachen die Fursten zu Baruch: Gehe hin und verbirg dich mit Jeremia, daß niemand wisse, wo ihrseid!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Sie aber gingen hinein zum Konige in den Vorhof und lieften das Buch behalten in der Kammer Elisamas, des Kanzlers, und sagten vor dem Konige an alle diese Reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Da sandte der Konig den Judi, das Buch zu holen. Derselbige nahm es aus der Kammer Elisamas, des Kanzlers. Und Judi las vor dem Konige und alien Fursten, die bei dem Konige stunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Der Konig aber saft im Winterhause, im neunten Monden, vor dem Kamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Als aber Judi drei Oder vier Blatt gelesen hatte, zerschnitt er\'s mit einem Schreibmesser und wart es ins Feuer, das im Kaminherde war, bis das Buch ganz verbrannte im Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Und niemand entsetzte sich noch zerrift seine Kleider, weder der Konig noch seine Knechte, so doch alle diese Reden gehoret hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Wiewohl Elnathan, Delaja und Gemarja baten den Konig, er wollte das Buch nicht verbrennen; aber er gehorchte ihnen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Dazu gebot noch der Konig Jerahmeel, dem Sohn Hamelechs, und Seraja, dem Sohn Asriels, und Selemja, dem Sohn Abdeels, sie sollten Baruch, den Schreiber, und Jeremia, den Propheten, greifen. Aber der HERR hatte sie verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Da geschah des HERRN Wort zu Jeremia, nachdem der Konig das Buch und die Reden, so Baruch hatte geschrieben aus dem Munde Jeremias, verbrannt hatte, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Nimm dir wiederum ein ander Buch und schreibe alle vorigen Reden darein, die im ersten Buch stunden, welches Jojakim, der Konig Judas, verbrannt hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'und sage von Jojakim, dem Konige Judas: So spricht der HERR; Du hast dies Buch verbrannt und gesagt: Warum hast du darein geschrieben, daß der Konig von Babel werde kommen und dies Land verderben und machen, daß weder Leute noch Vieh drinnen mehr sein werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Darum spricht der HERR von Jojakim, dem Konige Judas: Er soil keiner von den Seinen auf dem Stuhl Davids sitzen, und sein Leichnam soil hingeworfen des Tages in der Hitze und des Nachts in dem Frost liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Und ich will ihn und seinen Samen und seine Knechte heimsuchen urn ihrer Missetat willen. Und ich will uber sie und über die Burger zu Jerusalem und über die in Juda kommen lassen all das Unglück, das ich ihnen geredet habe, und sie doch nicht gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Da nahm Jeremia ein ander Buch und gab es Baruch, dem Sohn Nerias, dem Schreiber. Der schrieb darein aus dem Munde Jeremias alle die Reden, so in dem Buch stunden, das Jojakim, der Konig Judas, hatte mit Feuer verbrennen lassen; und über dieselbigen wurden der Reden noch viel mehr, denn jenerwaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Und Zedekia, der Sohn Josias, ward Konig anstatt Jechanjas, des Sohns Jojakims; denn Nebukadnezar, der Konig zu Babel, machte ihn zum Konige im Lande Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Aber er und seine Knechte und das Volk im Lande gehorchten nicht des HERRN Worten, die er durch den Propheten Jeremia redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Es sandte gleichwohl der Konig Zedekia Juchal, den Sohn Selemjas, und Zephanja, den Sohn Masejas, den Priester, zum Propheten Jeremia und lieli ihm sagen: Bitte den HERRN, unsern Gott, fur uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Denn Jeremia ging nun unterdem Volkaus und ein, und legte ihn niemand ins Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'So war das Heer Pharaos aus Agypten gezogen, und die Chaldaer, so vor Jerusalem gelegen, da sie solch Gerucht gehort hatten, waren von Jerusalem abgezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Und des HERRN Wort geschah zum Propheten Jeremia und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'So spricht der HERR, der Gott Israels: So saget dem Konige Judas, dereuch zu mirgesandt hat, mich zu fragen: Siehe, das Heer Pharaos, das euch zu Hilfe ist ausgezogen, wird wiederum heim nach Agypten ziehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'und die Chaldaer werden wieder kommen und wider diese Stadt streiten und sie gewinnen und mit Feuerverbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Darum spricht der HERR also: Betruget eure Seelen nicht, daß ihr denket, die Chaldaer werden von uns abziehen. Sie werden nicht abziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Und wenn ihr schon schluget das ganze Heer der Chaldaer, so wider euch streiten, und blieben ihrer etliche verwundet uber, so wurden sie doch ein jeglicher in seinem Gezelt sich aufmachen und diese Stadt mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Als nun der Chaldaer Heer von Jerusalem war abgezogen urn des Heers willen Pharaos,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'ging Jeremia aus Jerusalem und wollte ins Land Beniamin qehen, Acker zu bestellen unter dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Und da er unter das Tor Benjamin kam, da war einer bestellet zum Torhuter mit Namen Jeria, der Sohn Selemjas, des Sohns Hananjas; derselbige griff den Propheten Jeremia und sprach: Du willst zu den Chaldaern fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia sprach: Das ist nicht wahr, ich will nicht zu den Chaldaern fallen. Aber Jeria wollte ihn nicht horen, sondern griff Jeremia und brachte ihn zu den Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Und die Fursten wurden zornig uber Jeremia und liefien ihn schlagen und warfen ihn ins Gefangnis im Hause Jonathans, des Schreibers; denselbigen setzten sie zum Kerkermeister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Also ging Jeremia in die Grube und Kerker und lag lange Zeit daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Und Zedekia, der Konig, sandte hin und lieli ihn holen und fragte ihn heimlich in seinem Hause und sprach: Istauch ein Wortvom HERRN vorhanden? Jeremia sprach: Ja, denn du wirst dem Konige zu Babel in die Hande gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Und Jeremia sprach zum Konige Zedekia: Was habe ich wider dich, wider deine Knechte und wider dies Volk gesundiget, daß sie mich in den Kerker geworfen haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Wo sind nun eure Propheten, die euch weissagten und sprachen: Der Konig zu Babel wird nicht uber euch noch uber dies Land kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Und nun, mein HERR Konig, hore mich und lali meine Bitte vor dir gelten und la(3> mich nicht wieder in Jonathans, des Schreibers, Haus bringen, daß ich nicht sterbe daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Da befahl der Konig Zedekia, daß man Jeremia im Vorhofe des Gefangnisses behalten sollte, und lieli ihm des Tages ein Laiblein Brot geben aus der Backergasse, bis daß alles Brot in der Stadt auf war. Also blieb Jeremia im Vorhofe des Gefangnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Es horeten aber Saphatja, der Sohn Mathans, und Gedalja, der Sohn Pashurs, und Juchal, der Sohn Selemjas, und Pashur, der Sohn Malchias, die Rede, so Jeremia zu allem Volk redete und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'So spricht der HERR: Wer in dieser Stadt bleibet, der wird durch Schwert, Hunger und Pestilenz sterben müssen; wer aber hinausgehet zu den Chaldaern, der soil lebend bleiben und wird sein Leben wie eine Beute davonbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Denn also spricht der HERR: Diese Stadt soil ubergeben werden dem Heer des Konigs zu Babel, und sollen sie gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Da sprachen die Fursten zum Konige: Lali doch diesen Mann toten; denn mit der Weise wendet er die Kriegsleute ab, so noch übrig sind in dieser Stadt, desgleichen das ganze Volk auch, weil er solche Worte zu ihnen sagt. Denn der Mann sucht nicht, was zum Frieden diesem Volk, sondern was zum Ungluck dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Der Konig Zedekia sprach: Siehe, er ist in euren Handen; denn der Konig kann nichts wider euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Da nahmen sie Jeremia und warfen ihn in die Grube Malchias, des Sohns Hamelechs, die am Vorhofe des Gefangnisses war, und liefien ihn an Seilen hinab in die Grube, da nicht Wasser, sondern Schlamm war. Und Jeremia sank in den Schlamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Als aber Ebed-Melech, der Mohr, ein Kammerer in des Konigs Hause, horete, daß man Jeremia hatte in die Grube geworfen, und der Konig eben saß im Tor Benjamin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'da ging Ebed-Melech aus des Konigs Hause und redete mit dem Konige und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Mein HERR Konig, die Manner handeln ubel mit dem Propheten Jeremia, daß sie ihn haben in die Grube geworfen, da er muli Hungers sterben; denn es ist kein Brot mehr in der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Da befahl der Konig Ebed-Melech, dem Mohren, und sprach: Nimm dreilüg Manner mit dir von diesen und zeuch den Propheten Jeremia aus der Grube, ehe denn er sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Und Ebed-Melech nahm die Manner mit sich und ging in des Konigs Haus unter die Schatzkammer und nahm daselbst zerrissene und vertragene alte Lumpen und lieft sie an einem Seil hinab zu Jeremia in die Grube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Und Ebed-Melech, der Mohr, sprach zu Jeremia: Lege diese zerrissenen und vertragenen alten Lumpen unterdeine Achseln urn das Seil. Und Jeremia tat also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Und siezogen Jeremia herauf aus der Grube an den Stricken. Und blieb also Jeremia im Vorhofe des Gefangnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Und der Konig Zedekia sandte hin und lieli den Propheten Jeremia zu sich holen unter den dritten Eingang am Hause des HERRN. Und der Konig sprach zu Jeremia: Ich will dich etwas fragen; Lieber, verhalte mir nichts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia sprach zu Zedekia: Sage ich dir etwas, so totest du mich doch; gebe ich dir aber einen Rat, so gehorchest du mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Da schwur der Konig Zedekia dem Jeremia heimlich und sprach: So wahr der HERR lebt, der uns diese Seele gemacht hat, so will ich dich nicht toten noch den Mannern in die Hande geben, die dir nach deinem Leben stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Und Jeremia sprach zu Zedekia: So spricht der HERR, der Gott Zebaoth, der Gott Israels: Wirst du hinausgehen zu den Fursten des Konigs zu Babel, so sollst du leben bleiben, und diese Stadt soil nicht verbrannt werden, sondern du und dein Haus sollen bei Leben bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Wirst du aber nicht hinausgehen zu den Fursten des Konigs zu Babel, so wird diese Stadt den Chaldaern in die Hande gegeben, und werden sie mit Feuer verbrennen, und du wirst auch nicht ihren Handen entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Der Konig Zedekia sprach zu Jeremia: Ich besorge mich aber, daß ich den Juden, so zu den Chaldaern gefallen sind, mochte ubergeben werden, daß sie mein spotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremia sprach: Man wird dich nicht ubergeben. Lieber, gehorche doch der Stimme des HERRN, die ich dir sage, so wird dir\'s wohlgehen und du wirst lebend bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Wirst du aber nicht hinausgehen, so ist dies das Wort, das mir der HERR gezeiget hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Siehe, alle Weiber, die noch vorhanden sind in dem Hause des Konigs Judas, werden hinaus müssen zu den Fursten des Konigs zu Babel. Dieselbigen werden dann sagen: Ach, deine Troster haben dich uberredet und verfuhret und in Schlamm gefuhret und lassen dich nun stecken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Also werden dann alle deine Weiber und Kinder hinaus müssen zu den Chaldaern, und du selbst wirst ihren Handen nicht entgehen, sondern du wirst vom Konige zu Babel gegriffen, und diese Stadt wird mit Feuer verbrannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Und Zedekia sprach zu Jeremia: Siehe zu, daß niemand diese Rede erfahre, so wirst du nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Und ob es die Fursten erfuhren, daß ich mit dir geredet habe, und kamen zu dir und sprachen: Sage an, was hast du mit dem Konige geredet, leugne es uns nicht, so wollen wir dich nicht toten; und was hat der Konig mit dir geredet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'so sprich: Ich habe den Konig gebeten, daß er mich nicht wiederum liefte in Jonathans Haus fuhren; ich mochte daselbst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Da kamen alle Fursten zu Jeremia und fragten ihn; und er sagte ihnen, wie ihm der Konig befohlen hatte. Da lieften sie von ihm, weil sie nichts erfahren konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Und Jeremia blieb im Vorhofe des Gefangnisses bis auf den Tag, da Jerusalem gewonnen ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Und es geschah, daß Jerusalem gewonnen ward. Denn im neunten Jahr Zedekias, des Konigs Judas, im zehnten Monden kam Nebukadnezar, der Konig zu Babel, und all sein Heer vor Jerusalem und belagerten dieselbige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Und im elften Jahr Zedekias, am neunten Tag des vierten Monden, brach man in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Und zogen hinein alle Fursten des Konigs zu Babel und hielten unter dem Mitteltor, namlich Nergal- Sarezer, Sangar-Nebo, Sarsechim, der oberste Kammerer, Nergal-Sarezer, der Hofmeister, und alle andern Fursten des Konigs zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Als sie nun Zedekia, der Konig Judas, sah samt seinen Kriegsleuten, fiohen sie bei Nacht zur Stadt hinaus bei des Konigs Garten durchs Tor zwischen zweien Mauern und zogen durchs Feld hindurch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Aber der Chaldaer Heer jagten ihnen nach und ergriffen Zedekia im Felde bei Jericho und fingen ihn und brachten ihn zu Nebukadnezar, dem Konige zu Babel, gen Riblath, die im Lande Hemath liegt; der sprach ein Urteil fiber ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Und der Konig zu Babel lieft die Kinder Zedekias vor seinen Augen toten zu Ribiath und totete alle Fursten Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Aber Zedekia lieft er die Augen ausstechen und ihn mit Ketten binden, daß er ihn gen Babel fuhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Und die Chaldaer verbrannten beide, des Konigs Haus und der Burger Hauser, und zerbrachen die Mauern zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Was aber noch von Volk in der Stadt war und was sonst zu ihnen gefallen war, die fuhrete Nebusar- Adan, der Hofmeister, alle miteinander gen Babel gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Aber von dem geringen Volk, das nichts hatte, lieft zur selbigen Zeit Nebusar-Adan, der Hauptmann, etliche im Land Juda und gab ihnen Weinberge und Ddrflein ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Aber Nebukadnezar, der Konig zu Babel, hatte Nebusar-Adan, dem Hauptmanne, befohlen von Jeremia und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Nimm hin und laft dir ihn befohlen sein und tue ihm kein Leid, sondern wie er\'s von dir begehret, so mache es mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Da sandte hin Nebusar-Adan, der Hauptmann, und Nebu-Sasban, deroberste Kammerer, Nergal- Sarezer, der Hofmeister, und alle Fursten des Konigs zu Babel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'und lielien Jeremia holen aus dem Vorhofe des Gefangnisses und befahlen ihn Gedalja, dem Sohn Ahikams, des Sohns Saphans, daß er ihn hinaus in sein Haus fuhrete und bei dem Volk bliebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Es warauch des HERRN Wort geschehen zu Jeremia, weil er noch im Vorhofe des Gefangnisses gefangen lag, und gesprochen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Gehe hin und sage Ebed-Melech, dem Mohren: So spricht der HERR Zebaoth, der Gott Israels: Siehe, ich will meine Worte kommen lassen uber diese Stadt zum Ungluck und zu keinem Guten, und du sollst es sehen zur selbigen Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Aber dich will ich erretten zur selbigen Zeit, spricht der HERR, und sollst den Leuten nicht zuteil werden, vorwelchen du dich furchtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Denn ich will dir davon helfen, dafi du nicht durchs Schwert tallest, sondern sollst dein Leben wie eine Beute davonbringen, darum daß du mir vertrauet hast, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Dies ist das Wort, so vom HERRN geschah zu Jeremia, da ihn Nebusar-Adan, der Hauptmann, loslieli zu Rama; denn er war auch mit Ketten gebunden unter alien denen, die zu Jerusalem und in Juda gefangen waren, daß man sie gen Babel wegführen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Da nun der Hauptmann Jeremia zu sich hatte lassen holen, sprach erzu ihm: Der HERR, dein Gott, hat dies Ungluck uber diese Statte geredet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'und hat es auch kommen lassen und getan, wie er geredet hat; denn ihr habt gesundiget wider den HERRN und seiner Stimme nicht gehorchet; darum ist euch solches widerfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Nun siehe, ich habe dich heute losgemacht von den Ketten, damit deine Hande gebunden waren. Gefallt dir\'s, mit mir gen Babel zu ziehen, so komm, du sollst mir befohlen sein; gefallt dir\'s aber nicht, mit mir gen Babel zu ziehen, so lali es anstehen. Siehe, da hast du das ganze Land vor dir; wo dich\'s gut dünkt und dir gefallt, da zeuch hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Denn weiter hinaus wird kein Wiederkehren sein. Darum magst du kehren zu Gedalja, dem Sohn Ahikams, des Sohns Saphans, welchen der Konig zu Babel gesetzt hat uber die Stadte in Juda, und bei demselbigen unter dem Volk bleiben; Oder gehe, wohin dir\'s wohlgefallt. Und der Hauptmann gab ihm Zehrung und Geschenke und lieli ihn gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Also kam Jeremia zu Gedalja, dem Sohn Ahikams, gen Mizpa und blieb bei ihm unter dem Volk, das im Lande noch übrig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Da nun die Hauptleute, so auf dem Felde sich enthielten, samt ihren Leuten erfuhren, daß der Konig zu Babel hatte Gedalja, den Sohn Ahikams, uber das Land gesetzt und beide, uber Manner und Weiber, Kinder und die Geringen im Lande, welche nicht gen Babel gefuhret waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'kamen sie zu Gedalja gen Mizpa, namlich Ismael, der Sohn Nethanjas, Johanan und Jonathan, die Sohne Kareahs, und Seraja, der Sohn Thanhumeths, und die Sohne Ephai von Netophath und Jesanja, der Sohn Maachathis, samt ihren Mannern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Und Gedalja, der Sohn Ahikams, des Sohns Saphans, tat ihnen und ihren Mannern einen Eid und sprach: Furchtet euch nicht, daß ihr den Chaldaern untertan sein sollet; bleibet im Lande und seid dem Konige zu Babel untertan, so wird\'s euch wohlgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Siehe, ich wohne hie zu Mizpa, daß ich den Chaldaern diene, die zu uns kommen. Darum so sammelt ein den Wein und Feigen und Ol und leget es in eure Gefalie und wohnet in euren Stadten, die ihr bekommen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Auch alle Juden, so im Lande Moab und der Kinder Ammon und in Edom und in alien Landern waren, da sie horeten, daß der Konig zu Babel hatte lassen etliche in Juda uberbleiben und uber sie gesetzt Gedalja, den Sohn Ahikams, des Sohns Saphans,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'kamen sie alle wieder von alien Orten, dahin sie verstolien waren, ins Land Juda zu Gedalja gen Mizpa und sammelten ein sehr viel Weins und Sommerfruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Aber Johanan, der Sohn Kareahs, samt all den Hauptleuten, so auf dem Felde sich enthalten hatten, kamen zu Gedalja gen Mizpa');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'und sprachen zu ihm: Weitit du auch, daß Baalis, der Konig der Kinder Ammon, gesandt hat Ismael, den Sohn Nethanjas, daß erdich soil erschlagen? Das wollte ihnen aber Gedalja, der Sohn Ahikams, nicht glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Da sprach Johanan, der Sohn Kareahs, zu Gedalja heimlich zu Mizpa: Lieber, ich will hingehen und Ismael, den Sohn Nethanjas, schlagen, daß es niemand erfahren soil. Warum soli erdich erschlagen, daß alle Juden, so zu dir versammelt sind, zerstreuet werden und die noch aus Juda uberblieben sind, umkommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Aber Gedalja, der Sohn Ahikams, sprach zu Johanan, dem Sohn Kareahs: Du sollst das nicht tun; es ist nicht wahr, das du von Ismael sagest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Aber im siebenten Monden kam Ismael, der Sohn Nethanjas, des Sohns Elisamas, aus koniglichem Stamm, samt den Obersten des Konigs und zehn Manner mit ihm zu Gedalja, dem Sohn Ahikams, gen Mizpa und alien daselbstzu Mizpa miteinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Und Ismael, der Sohn Nethanjas, machte sich auf samt den zehn Mannern, die bei ihm waren, und schlugen Gedalja, den Sohn Ahikams, des Sohns Saphans, mit dem Schwert zu Tode, darum daß ihn der Konig zu Babel uber das Land gesetzt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Dazu alle Juden die bei Gedalja waren zu Mizpa, und die Chaldaer, die sie daselbst fanden, und alle Kriegsleute schlug Ismael.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Des andern Tages, nachdem Gedalja erschlagen war und noch niemand wußte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'kamen achtzig Manner von Sichem, von Silo und von Samaria und hatten die Barte abgeschoren und ihre Kleider zerrissen und sich zerritzt und trugen Speisopfer und Weihrauch mit sich, daß sie es brachten ins Haus des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Und Ismael, der Sohn Nethanjas, ging heraus von Mizpa, denselbigen entgegen, ging daher und weinete. Als er nun an sie kam, sprach er zu ihnen: Ihr solltzu Gedalja, dem Sohn Ahikams, kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Da sie aber mitten in die Stadt kamen, ermordete sie Ismael, der Sohn Nethanjas, und die Manner, so bei ihm waren, bei dem Brunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Aber es waren zehn. Manner darunter, die sprachen zu Ismael: Lieber, tote uns nicht; wir haben Schatze im Acker liegen von Weizen, Gerste, 01 und Honig. Also ließ er ab und totete sie nicht mit den andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Der Brunnen aber, darein Ismael die toten Leichname warf, welche er hatte erschlagen, samt dem Gedalja, ist der, den der Konig Assa machen ließ wider Baesa, den Konig Israels; den fullete Ismael, der Sohn Nethanjas, mit den Erschlagenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Und was übriges Volks warzu Mizpa, auch des Konigs Tochter, fuhrete Ismael, der Sohn Nethanjas, gefangen weg samt allem ubrigen Volkzu Mizpa, uber welche Nebusar-Adan, der Hauptmann, hatte gesetzt Gedalja, den Sohn Ahikams; und zog hin und wollte hinuber zu den Kindern Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Da aber Johanan, der Sohn Kareahs, erfuhr und alle Hauptleute des Heers, die bei ihm waren, all das Ubel, das Ismael, der Sohn Nethanjas, begangen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'nahmen sie zu sich alle Manner und zogen hin wider Ismael, den Sohn Nethanjas, zu streiten, und trafen ihn an bei dem großen Wasser an Gibeon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Da nun alles Volk, so bei Ismael war, sah den Johanan, den Sohn Kareahs, und alle die Hauptleute des Heers, die bei ihm waren, wurden sie froh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Und das ganze Volk, das Ismael hatte von Mizpa weggeführet, wandte sich urn und kehrete wiederum zu Johanan, dem Sohn Kareahs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Aber Ismael, der Sohn Nethanjas, entrann dem Johanan mitacht Mannern und zog zu den Kindern Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Und Johanan, der Sohn Kareahs, samt alien Hauptleuten des Heers, so bei ihm waren, nahmen all das librige Volk, so sie wiedergebracht hatten von Ismael, dem Sohn Nethanjas, aus Mizpa zu sich (weil Gedalja, der Sohn Ahikams, erschlagen war), namlich die Kriegsmanner, Weiber und Kinder und Kammerer, so sie von Gibeon hatten wiedergebracht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'und zogen hin und kehreten ein zum Kimham zur Herberge, der bei Bethlehem wohnete, und wollten nach Agypten ziehen vor den Chaldaern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Denn sie furchteten sich vor ihnen, weil Ismael, der Sohn Nethanjas, Gedalja, den Sohn Ahikams, erschlagen hatte, den der Konig zu Babel uber das Land gesetzt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Da traten herzu alle Hauptleute des Heers, Johanan, der Sohn Kareahs, Jesanja, der Sohn Hosajas, samt dem ganzen Volk, beide, klein und groß,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'und sprachen zum Propheten Jeremia: Lieber, laß unser Gebet vor dir gelten und bitte fur uns den HERRN, deinen Gott, urn all diese Ubrigen (denn unser ist leider wenig geblieben von vielen, wie du uns selbst siehest mit deinen Augen),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'daß uns der HERR, dein Gott, wollte anzeigen, wohin wir ziehen und was wir tun sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Und der Prophet Jeremia sprach zu ihnen: Wohlan, ich will gehorchen; und siehe, ich will den HERRN, euren Gott, bitten, wie ihrgesagt habt; und alles, was euch der HERR antworten wird, das will ich euch anzeigen und will euch nichts verhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Und sie sprachen zu Jeremia: Der HERR sei ein gewisser und wahrhaftiger Zeuge zwischen uns, wo wir nicht tun werden alles, das dir der HERR, dein Gott, an uns befehlen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Es sei Gutes Oder Boses, so wollen wir gehorchen der Stimme des HERRN, unsers Gottes, zu dem wir dich senden, auf daß uns wohlgehe, so wir der Stimme des HERRN, unsers Gottes, gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Und nach zehn Tagen geschah des HERRN Wort zu Jeremia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Da riefer Johanan, den Sohn Kareahs, und alle Hauptleute des Heers, die bei ihm waren, und alles Volk, beide, klein und groß,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'und sprach zu ihnen: So spricht der HERR, der Gott Israels, zu dem ihr mich gesandt habt, daß ich euer Gebet vor ihn sollte bringen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Werdet ihr in diesem Lande bleiben, so will, ich euch bauen und nicht zerbrechen; ich will euch pflanzen und nicht ausreuten; denn es hat mich schon gereuet das Ubel, das ich euch getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ihr sollt euch nicht furchten vor dem Konige zu Babel, vor dem ihr euch furchtet, spricht der HERR; ihr sollt euch vor ihm nicht furchten; denn ich will bei euch sein, daß ich euch helfe und von seiner Hand errette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Ich will euch Barmherzigkeit erzeigen und mich uber euch erbarmen und euch wieder in euer Land bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Werdet ihr aber sagen: Wir wollen nicht im Lande bleiben, damit ihr ja nicht gehorchet der Stimme des HERRN, eures Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'sondern sagen: Nein, wirwollen nach Agyptenland ziehen, daß wir keinen Krieg sehen noch der Posaunen Schall horen und nicht Hunger Brots halben leiden mussen; daselbst wollen wir bleiben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'nun, so horet des HERRN Wort, ihr Ubrigen aus Juda! So spricht der HERR Zebaoth, der Gott Israels: Werdet ihr euer Angesicht richten, nach Agyptenland zu ziehen, da P> ihr daselbst bleiben wollet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'so soil euch das Schwert, vor dem ihreuch fürchtet, in Agyptenland treffen; und der Hunger, des ihr euch besorget, soil stets hinter euch her sein in Agypten, und sollet daselbst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Denn sieseien, wersie wollen, die ihr Angesicht richten, daß sie nach Agypten ziehen, daselbst zu bleiben, die sollen sterben durchs Schwert, Hunger und Pestilenz; und soil keiner überbleiben noch entrinnen dem Ubel, das ich uber sie will kommen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Denn so spricht der HERR Zebaoth, der Gott Israels: Gleichwie mein Zorn und Grimm uber die Einwohner zu Jerusalem gegangen ist, so soil er auch uber euch gehen, wo ihr nach Agypten ziehet, daß ihr zum Fluch, zum Wunder, Schwur und Schande werdet und diese Statte nicht mehr sehen sollet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Das Wort des HERRN gilt euch, ihr Ubrigen aus Juda, daß ihr nicht nach Agypten ziehet. Darum so wisset, daß ich euch heute bezeuge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Ihr werdet sonst euer Leben verwahrlosen. Denn ihr habt mich gesandt zum HERRN, eurem Gott, und gesagt: Bitte den HERRN, unsern Gott, fur uns; und alles, was der HERR, unser Gott, sagen wird, das zeige uns an, so wollen wir danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Das habe ich euch heute zu wissen getan; aber ihr wollt der Stimme des HERRN, eures Gottes, nicht gehorchen noch allem dem, das er mir an euch befohlen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'So sollt ihr nun wissen, daß ihr durchs Schwert, Hunger und Pestilenz sterben musset an dem Ort, dahin ihr gedenkt zu ziehen, daß ihr daselbst wohnen wollet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Da Jeremia alle Worte des HERRN, ihres Gottes, hatte ausgeredet zu allem Volk, wie ihm denn der HERR, ihr Gott, alle diese Worte an sie befohlen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'sprach Asarja, der Sohn Hosajas, und Johanan, der Sohn Kareahs, und alle frechen Manner zu Jeremia: Du lugest! Der HERR, unser Gott, hat dich nicht zu uns gesandt noch gesagt: Ihr sollt nicht nach Agypten ziehen, daselbst zu wohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'sondern Baruch, der Sohn Nerias, beredetdich des uns zuwider, auf daß wir den Chaldaern ubergeben werden, daß sie uns toten und gen Babel wegfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Also gehorchte Johanan, der Sohn Kareahs, und alle Hauptleute des Heers samt dem ganzen Volk der Stimme des HERRN nicht, daß sie im Lande Juda waren geblieben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'sondern Johanan, der Sohn Kareahs, und alle Hauptleute des Heers nahmen zu sich alle Ubrigen aus Juda, so von alien Vblkern, dahin sie geflohen, wiederkommen waren, daß sie im Lande Juda wohneten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'namlich Mann, Weiber und Kinder, dazu des Konigs Tochter und alle Seelen, die Nebusar-Adan, der Hauptmann, bei Gedalja, dem Sohn Ahikams, des Sohns Saphans, hatte gelassen, auch den Propheten Jeremia und Baruch, den Sohn Nerias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'und zogen nach Agyptenland, denn sie wollten der Stimme des HERRN nicht gehorchen, und kamen gen Thachpanhes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Und des HERRN Wort geschah zu Jeremia zu Thachpanhes und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Nimm grolie Steine und verscharre sie im Ziegelofen, der vor der Tur am Hause Pharaos ist zu Thachpanhes, daß die Manner aus Juda zusehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'und sprich zu ihnen: So spricht der HERR Zebaoth, der Gott Israels: Siehe, ich will hinsenden und meinen Knecht Nebukadnezar, den Konig zu Babel, holen lassen und will seinen Stuhl oben auf diese Steine setzen, die ich verscharret habe; und er soil sein Gezelt daruber schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Und er soil kommen und Agyptenland schlagen und toten, wen es trifft, gefangen fuhren, wen es trifft, mit dem Schwert schlagen, wen es trifft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Und ich will die Hauser der Gotter in Agypten mit Feuer anstecken, daß er sie verbrenne und wegfuhre. Und er soil ihm Agyptenland anziehen, wie ein Hirte sein Kleid anzeucht, und mit Frieden von dannen ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Ersoll die Bildsaulen zu Beth-Semes in Agyptenland zerbrechen und die Gotzenkirchen in Agypten mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Dies ist das Wort, das zu Jeremia geschah an alle Juden, so in Agyptenland wohneten, namlich zu Migdal, zu Thachpanhes, zu Noph und die im Lande Pathros wohneten, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'So spricht der HERR Zebaoth, der Gott Israels: Ihr habt gesehen all das Ubel, das ich habe kommen lassen uber Jerusalem und uber alle Stadte in Juda; und siehe, heutigestages sind sie wüst, und wohnet niemand drinnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'und das urn ihrer Bosheit willen, die sie taten, daß sie mich erzurneten und hingingen und raucherten und dieneten andern Gottern, welche weder sie noch ihr noch eure Vater kannten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Und ich sandte stets zu euch alle meine Knechte, die Propheten, und lieli euch sagen: Tut doch nicht solche Greuel, die ich hasse!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Aber sie gehorchten nicht, neigten auch ihre Ohren von ihrer Bosheit nicht, daß sie sich bekehreten und andern Gottern nicht gerauchert hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Darum ging auch mein Zorn und Grimm an und entbrannte uber die Stadte Judas und uber die Gassen zu Jerusalem, daß sie zur Wuste und ode worden sind, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Nun, so spricht der HERR, der Gott Zebaoth, der Gott Israels: Warum tut ihr doch so groli Ubel wider euer eigen Leben, damit unter euch ausgerottet werde beide, Mann und Weib, beide, Kind und Saugling aus Juda, und nichts von euch uberbleibe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'daß ihr mich so erzumet durch eurer Hande Werk und rauchert andern Gottern in Agyptenland, dahin ihr gezogen seid, daselbst zu herbergen, auf daß ihr ausgerottet und zum Fluch und Schmach werdet unter alien Heiden auf Erden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Habt ihr vergessen des Unglucks eurer Vater, des Unglucks der Konige Judas, des Unglucks ihrer Weiber, dazu eures eigenen Unglucks und eurer Weiber Unglucks, das euch begegnet ist im Lande Juda und auf den Gassen zu Jerusalem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Noch sind sie bis auf diesen Tag nicht gedemutiget, furchten sich auch nicht und wandeln nicht in meinem Gesetz und Rechten, die ich euch und euren Vatern vorgestellet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Darum spricht der HERR Zebaoth, der Gott Israels, also: Siehe, ich will mein Angesicht wider euch richten zum Ungluck, und ganz Juda soil ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Und ich will die Ubrigen aus Juda nehmen, so ihr Angesicht gerichtet haben, nach Agyptenland zu ziehen, daß sie daselbst herbergen; es soli ein Ende mit ihnen alien werden in Agyptenland. Durchs Schwert sollen sie fallen und durch Hunger sollen sie umkommen, beide, klein und graft; sie sollen durch Schwert und Hunger sterben und sollen ein Schwur, Wunder, Fluch und Schmach werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Ich will auch die Einwohner in Agyptenland mit dem Schwert, Hunger und Pestilenz heimsuchen, gleichwie ich zu Jerusalem getan habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'daß aus den Ubrigen Judas keiner soil entrinnen noch uberbleiben, die doch darum hieher kommen sind nach Agyptenland zur Herberge, daß sie wiederum ins Land Juda kommen mochten, dahin sie gerne wollten wiederkommen und wohnen; aber es soil keiner wieder dahin kommen, ohne welche von hinnen fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Da antworteten dem Jeremia alle Manner, die da wohl wuftten, daß ihre Weiber andern Gottern raucherten, und alle Weiber, so mit groftem Haufen dastunden, samt allem Volk, die in Agyptenland wohneten und in Pathros, und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Nach dem Wort, das du im Namen des HERRN uns sagest, wollen wir dir nicht gehorchen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'sondern wir wollen tun nach all dem Wort, das aus unserm Munde gehet, und wollen Melecheth des Himmels rauchern und derselbigen Trankopfer opfern, wie wir und unsere Vater, unsere Konige und Fursten getan haben in den Stadten Judas und auf den Gassen zu Jerusalem. Da hatten wir auch Brot genug und ging uns wohl und sahen kein Ungluck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Seit der Zeit aber wir haben abgelassen, Melecheth des Himmels zu rauchern und Trankopfer zu opfern, haben wir alien Mangel gelitten und sind durch Schwert und Hunger umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Auch wenn wir Melecheth des Himmels rauchern und Trankopfer opfern, das tun wir ja nicht ohne unserer Manner Willen, daß wir derselbigen Kuchen backen und Trankopfer opfern, sie zu bekümmern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Da sprach Jeremia zum ganzen Volk, beide, Mannern und Weibern, und allem Volk, die ihm so geantwortet hatten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Ich meine ja, der HERR habe gedacht an das Rauchern, so ihr in den Stadten Judas und auf den Gassen zu Jerusalem getrieben habt, samt euren Vatern Konigen, Fursten und allem Volk im Lande, und hat\'s zu Herzen genommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'daß er nicht mehr leiden konnte euren bosen Wandel und Greuel, die ihrtatet; daher auch euer Land zur Wuste, zum Wunder und zum Fluch worden ist, daß niemand drinnen wohnet, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Darum daß ihr gerauchert habt und wider den HERRN gesundiget und der Stimme des HERRN nicht gehorchet und in seinem Gesetz, Rechten und Zeugnis nicht gewandelt habt, darum ist auch euch solch Ungluck widerfahren, wie es heutigestages stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Und Jeremia sprach zu allem Volk und zu alien Weibern: Horet des HERRN Wort, alle ihr aus Juda, so in Agyptenland sind!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So spricht der HERR Zebaoth, der Gott Israels: Ihr und eure Weiber habt mit eurem Munde geredet und mit euren Handen vollbracht, daß ihr saget: Wir wollen unsere Gelubde halten, die wir gelobet haben Melecheth des Himmels, daß wir derselbigen rauchern und Trankopfer opfern. Wohlan, ihr habt eure Gelubde erfullet und eure Gelubde gehalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'So horet nun des HERRN Wort, ihr alle aus Juda, die ihr in Agyptenland wohnet! Siehe, ich schwore bei meinem groften Namen, spricht der HERR, daß mein Name nicht mehr soil durch einiges Menschen Mund aus Juda genannt werden im ganzen Agyptenland, der da sage: So wahr der Herr HERR lebet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Siehe, ich will uber sie wachen zum Ungluck und zu keinem Guten, daß, wer aus Juda in Agyptenland ist, soil durchs Schwert und Hunger umkommen, bis es ein Ende mit ihnen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Welche aber dem Schwert entrinnen, die werden doch aus Agyptenland ins Land Juda wiederkommen müssen mitgeringem Haufen. Und also werden dann alle die Ubrigen aus Juda, so nach Agyptenland gezogen waren, daß sie daselbst herbergeten, erfahren, wes Wort wahr worden sei, meines Oder ihres.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Und zum Zeichen, spricht der HERR, daß ich euch an diesem Ort heimsuchen will, damit ihrwisset, daß mein Wort soli wahr werden uber euch zum Ungluck,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'so spricht der HERR also: Siehe, ich will Pharao Haphra, den Konig in Agypten, übergeben in die Hande seiner Feinde und derer, die ihm nach seinem Leben stehen, gleichwie ich Zedekia, den Konig Judas, ubergeben habe in die Hand Nebukadnezars, des Konigs zu Babel, seines Feindes, und der ihm nach seinem Leben stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Dies ist das Wort, so der Prophet Jeremia redete zu Baruch, dem Sohne Nerias, da er diese Rede auf ein Buch schrieb aus dem Munde Jeremias im vierten Jahr Jojakims, des Sohns Josias, des Konigs Judas, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'So spricht der HERR Zebaoth, der Gott Israels, von dir, Baruch:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Du sprichst: Wehe mir! Wie hat mir der HERR Jammer uber meinen Schmerzen zugefuget; ich seufze mich rnüde und finde keine Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Sage ihm also: So spricht der HERR: Siehe, was ich gebauet habe, das breche ich ab, und was ich gepflanzet habe, das reute ich aus samt diesem ganzen meinem eigenen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Und du begehrest dir grofte Dinge. Begehre es nicht! Denn siehe, ich will Ungluck kommen lassen uber alles Fleisch, spricht der HERR; aber deine Seele will ich dir zur Beute geben, an welchen Ort du ziehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Dies ist das Wort des HERRN, daszu dem Propheten Jeremia geschehen ist wider alle Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Wider Agypten. Wider das Heer Pharao Nechos, des Konigs in Agypten, welches lag am Wasser Phrath, zu Karchemis, das der Konig zu Babel, Nebukadnezar, schlug im vierten Jahr Jojakims, des Sohns Josias, des Konigs Judas:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Rustet Schilde und Tartschen und ziehet in den Streit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Spannet Rosse an und lasset Reiter aufsitzen! Setzet die Helme auf und scharfet die Spiefte und ziehet Panzer an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Wie kommt\'s aber, dafi ich sehe, dafi sie verzagt sind und die Flucht geben, und ihre Heiden erschlagen sind? Sie fliehen, dafi sie sich auch nicht umsehen. Schrecken ist urn und urn, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Der Schnelle kann nicht entfliehen noch der Starke entrinnen. Gegen Mitternacht am Wasser Phrath sind sie gefallen und daniedergelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Wo ist nun der, so heraufzog wie ein Strom, und seine Wellen sich erhuben wie des Wassers?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Agypten zog herauf wie ein Strom, und seine Wellen erhuben sich wie des Wassers und sprach: Ich will hinaufziehen, das Land bedecken und die Stadt verderben samt denen, die drinnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Wohlan, sitzet auf die Rosse, rennet mit den Wagen, lasset die Heiden ausziehen, die Mohren und aus Put, die den Schild fuhren, und die Schutzen aus Lydien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Denn dies ist der Tag des Herm HERRN Zebaoth, ein Tag der Rache, daß er sich an seinen Feinden rache, da das Schwert fressen und von ihrem Blutvoll und trunken werden wird. Denn sie mussen dem Herrn HERRN Zebaoth ein Schlachtopfer werden im Lande gegen Mitternacht, am Wasser Phrath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Gehe hinauf gen Gilead und hole Salbe, Jungfrau, Tochter aus Agypten! Aber es ist umsonst, daß du viel arzeneiest; du wirst doch nicht heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Deine Schande ist unterdie Heiden erschollen, deines Heuiens ist das Land voll; denn ein Held fallt uber den andern, und liegen beide miteinander danieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Dies ist das Wort des HERRN, das er zu dem Propheten Jeremia redete, da Nebukadnezar, der Konig zu Babel, daherzog, Agyptenland zu schlagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Verkundiget in Agypten und saget es an zu Migdal; saget es an zu Noph und Thachpanhes und sprechet: Stelle dich zur Wehre; denn das Schwert wird fressen, was urn dich her ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Wie geht es zu, daß deine Gewaltigen zu Boden fallen und mogen nicht bestehen? Der HERR hat sie so gesturzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Er macht, daß ihrer viele fallen, daß einer mit dem andern daniederliegt. Da sprachen sie: Wohlauf, laftt uns wieder zu unserm Volk ziehen in unser Vaterland vor dem Schwert des Tyrannen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Daselbst schrie man ihnen nach: Pharao, der Konig in Agypten, liegt; er hat sein Gezelt gelassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'So wahr als ich lebe, spricht der Konig, der HERR Zebaoth heiftt, erwird daherziehen so hoch, wie der Berg Tabor unter den Bergen ist und wie der Karmel am Meer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Nimm dein Wandergerat, du Einwohnerin, Tochter Agypten; denn Noph wird wust und verbrannt werden, daß niemand drinnen wohnen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Agypten ist ein sehr schones Kalb; aber es kommt von Mitternacht der Schlachter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Und Taglohner, so drinnen wohnen, sind auch wie gemastete Kalber; aber sie mussen sich dennoch wenden, fluchtig werden miteinander und werden nicht bestehen; denn der Tag ihres Unfalls wird uber sie kommen, namlich die Zeit ihrer Heimsuchung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Sie fahren daher, daß der Harnisch prasselt, und kommen mit Heereskraft und bringen Axte uber sie wie die Holzhauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Dieselbigen werden hauen also in ihrem Walde, spricht der HERR, daß nicht zu zahlen ist; denn ihrer ist mehr weder Heuschrecken, die niemand zahlen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Die Tochter Agyptens steht mit Schanden, denn sie ist dem Volk von Mitternacht in die Hande gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Der HERR Zebaoth, der Gott Israels, spricht: Siehe, ich will heimsuchen den Regenten zu No und den Pharao und Agypten samt seinen Gottern und Konigen, ja Pharao mit alien, die sich auf ihn verlassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'daß ich sie gebe in die Hande denen, die ihnen nach ihrem Leben stehen, und in die Hande Nebukadnezars, des Konigs zu Babel, und seiner Knechte. Und danach sollst du bewohnet werden wie vor alters, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Aber du, mein Knecht Jakob, furchte dich nicht, und du, Israel, verzage nicht! Denn siehe, ich will dir aus fernen Landen und deinem Samen aus dem Lande seines Gefangnisses helfen, daß Jakob soil wiederkommen und in Frieden sein und die Fulle haben, und niemand soil ihn schrecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Darum furchte dich nicht, du Jakob, mein Knecht, spricht der HERR; denn ich bin bei dir. Mit alien Heiden, dahin ich dich verstoften habe, will ich\'s ein Ende machen; aber mit dir will ich\'s nicht ein Ende machen, sondern ich will dich zuchtigen mit Mafte, auf daß ich dich nicht ungestraft lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Dies ist das Wort des HERRN, das zum Propheten Jeremia geschah wider die Philister, ehe denn Pharao Gaza schlug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So spricht der HERR: Siehe, es kommen Wasser herauf von Mitternacht, die eine Flut machen werden und beide, Land und was drinnen ist, beide, Stadte und die, so drinnen wohnen, wegreiften werden, daß die Leute werden schreien und alle Einwohner im Lande heulen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'vor dem Getummel ihrer starken Rosse, so dahertraben, und vor dem Rasseln ihrer Wagen und Poltern ihrer Rader, daß sich die Vater nicht werden umsehen nach den Kindern, so verzagt werden sie sein');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'vor dem Tage, so da kommt, zu verstoren alle Philister und auszureuten Tyrus und Zidon samt ihren andern Gehilfen. Denn der HERR wird die Philister, die das Ubrige sind aus der Insel Kaphthor, verstoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gaza wird kahl werden und Askalon samt den Ubrigen in ihren Grunden verderbet. Wie lange ritzest du dich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'O du Schwert des HERRN, wann willst du doch aufhoren? Fahre doch in deine Scheide und ruhe und sei still!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Aber wie kannst du aufhoren, weil der HERR dir Befehl getan hat wider Askalon, der dich wider die Anfurt am Meer bestellet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Wider Moab So spricht der HERR Zebaoth, der Gott Israels: Wehe der Stadt Nebo, denn sie ist zerstoret und liegt elend! Kiriathaim ist gewonnen; die Feste steht elend und ist zerrissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Der Trotz Moabs ist aus, den sie an Hesbon hatten; denn man gedenkt Boses wider sie, namlich: Kommt, wir wollen sie ausrotten, daß sie kein Volk mehr seien! Und du, Madmen, muftt auch verderbet werden; das Schwert wird hinter dich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Man horet ein Geschrei zu Horonaim von Verstoren und groftem Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab ist zerschlagen; man horet ihre Jungen schreien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Denn sie gehen mit Weinen den Weg hinauf gen Luhith, und die Feinde horen ein Jammergeschrei den Weg von Horonaim herab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'namlich: Hebet euch weg und errettet euer Leben! Aber du wirst sein wie die Heide in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Darum daß du dich auf deine Gebaude verlassest und auf deine Schatze, sollst du auch gewonnen werden; und Kamos muft hinaus gefangen wegziehen samt seinen Priestern und Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Denn der Verstorer wird uber alle Stadte kommen, daß nicht eine Stadt entrinnen wird. Es sollen beide, die Gründe verderbet und die Ebenen verstoret werden; denn der HERR hat\'s gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Gebet Moab Federn! Erwird ausgehen, alsfloge er; und ihre Stadte werden wuste liegen, daß niemand drinnen wohnen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Verflucht sei, der des HERRN Werk lassig tut! Verflucht sei, der sein Schwert aufhalt, daß es nicht Blut vergiefte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab ist von seiner Jugend auf sicher gewesen und auf seinen Hefen stille gelegen und ist nie aus einem Faft ins andere gegossen und nie ins Gefangnis gezogen; darum ist sein Geschmack ihm geblieben und sein Geruch nicht verandert worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Darum siehe, spricht der HERR, es kommt die Zeit, daß ich ihnen will Schroter schicken, die sie ausschroten sollen und ihre Fasser ausleeren und ihre Lagel zerschmettern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Und Moab soil uber dem Kamos zuschanden werden, gleichwie das Haus Israel uber Bethel zuschanden worden ist, darauf sie sich verlieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Wie durft ihr sagen: Wir sind die Heiden und die rechten Kriegsleute?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'so doch Moab muft verstoret und ihre Stadte erstiegen werden und ihre beste Mannschaft zur Schlachtbank herabgehen müssen, spricht der Konig, welcher heiftt der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Denn der Unfall Moabs wird schier kommen, und ihr Ungluck eilet sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Lieber, habtdoch Mitleid mit ihnen, die ihr urn sie herwohnetund ihren Namen kennet, und sprechet: Wie ist die starke Rute und der herrüche Stab so zerbrochen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Herab von der Herrlichkeit, du Tochter, die du zu Dibon wohnest, und sitze in der Durre! Denn der Verstorer Moabs wird zu dir hinaufkommen und deine Festen zerreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Trittauf die Strafie und schaue, du Einwohnerin Aroers; frage die, so da fliehen und entrinnen, und sprich: Wie geht es?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Ach, Moab ist verwüstet und verderbet, heulet und schreiet! Sagt es an zu Arnon, daß Moab verstoret sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Die Strafe ist uber das ebene Land gegangen, namlich uber Holon, Jahza, Mephaath,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Dibon, Nebo, Beth-Diblathaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kiriathaim, Beth-Gamul, Beth-Meon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Kirioth, Bazra und uber alle Stadte im Lande Moab, sie liegen feme Oder nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Das Horn Moabs ist abgehauen und ihr Arm ist zerbrochen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Machet sie trunken (denn sie hat sich wider den HERRN erhaben), daß sie speien und die Hande ringen musse, auf daß sie auch zum Gespott werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Denn Israel hat dein Gespott sein mussen, als ware er unter den Dieben gefunden; und weil du solches wider sie redest, sollst du auch weg mussen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'O ihr Einwohner in Moab, verlasset die Stadte und wohnet in den Felsen; und tut wie die Tauben, so da nisten in den hohlen Lochern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Man hat immer gesagt von dem stolzen Moab, daß ersehrstolz sei, hoffartig, hochmutig, trotzig und ubermutig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Aber der HERR spricht: Ich erkenne seinen Zorn wohl, daß er nicht so viel vermag, und untersteht sich, mehrzu tun, denn sein Vermogen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Darum muft ich uber Moab heulen und uber das ganze Moab schreien und uber die Leute zu Kir- Heres klagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Ich muft uber dich, Jaeser, du Weinstock zu Sibma, weinen, denn deine Reben sind uber das Meer gefahren und bis ans Meer Jaeser kommen. Der Verstorer ist in deine Ernte und Weinlese gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Freude und Wonne ist aus dem Felde weg und aus dem Lande Moab, und man wird keinen Wein mehr keltern, der Weintreter wird nicht mehr sein Lied singen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'von des Geschreies wegen zu Hesbon bis gen Eleale, welches bis gen Jahza erschallet, von Zoar an, der dreijahrigen Kuh, bis gen Horonaim; denn auch die Wasser Nimrim sollen versiegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Und ich will, spricht der HERR, in Moab damit ein Ende machen, daß sie nicht mehr auf den Hohen opfern und ihren Gottern rauchern sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Darum brummet mein Herz uber Moab wie eine Trommete und uber die Leute zu Kir-Heres brummet mein Herz wie eine Trommete; denn sie haben\'s ubermacht, darum mussen sie zu Boden gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Alle Kopfe werden kahl sein und alle Barte abgeschoren, aller Hande zerritzt, und jedermann wird Sacke anziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Auf alien Dachern und Gassen, allenthalben in Moab wird man klagen; denn ich habe Moab zerbrochen wie ein unwertes Gefaft, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, '0 wie ist sie verderbt, wie heulen sie! Wie schandlich hangen sie die Kopfe! Und Moab ist zum Spott und zum Schrecken worden alien, so urn sie her wohnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Denn so spricht der HERR: Siehe, er fleugt daher wie ein Adler und breitet seine Flügel aus uber Moab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kiriath ist gewonnen, und die festen Stadte sind eingenommen; und das Herz der Helden in Moab wird zur selbigen Zeit sein wie einer Frauen Herz in Kindesnoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Denn Moab muft vertilget werden, daß sie kein Volk mehr seien, darum daß es sich wider den HERRN erhaben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Furcht, Grube und Strick kommt uber dich, du Einwohner in Moab, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Wer der Furcht entfleucht, der wird in die Grube fallen, und wer aus der Grube kommt, der wird im Strick gefangen werden; denn ich will uber Moab kommen lassen ein Jahr ihrer Heimsuchung, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Die aus der Schlacht entrinnen, werden Zuflucht suchen zu Hesbon; aber es wird ein Feuer aus Hesbon und eine Flamme aus Sihon gehen, welche die Orter in Moab und die kriegerischen Leute verzehren wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Wehe dir, Moab! Verloren ist das Volk Kamos; denn man hat deine Sohne und Tochter genommen und gefangen weggefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Aber in der zukunftigen Zeit will ich das Gefangnis Moabs wenden, spricht der HERR. Das sei gesagt von der Strafe uber Moab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Wider die Kinder Ammon spricht der HERR also: Hat denn Israel nicht Kinder, Oder hat er keinen Erben? Warum besitzt denn Malchom das Land Gad und sein Volk wohnet in jener Stadten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Darum siehe, es kommt die Zeit, spricht der HERR, daß ich will ein Kriegsgeschrei erschallen lassen uber Rabbath der Kinder Ammon, daß sie soil auf einem Haufen wüst liegen und ihre Tochter mit Feuer angesteckt werden. Aber Israel soli besitzen die, von denen sie besessen waren, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Heule, o Hesbon! denn Al ist verstoret. Schreiet, ihr Tochter Rabba, und ziehet Sacke an; klaget und laufet auf den Mauern herum! Denn Malchom wird gefangen weggefuhret samt seinen Priestern und Fursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Was trotzest du auf deine Auen? Deine Auen sind versauft, du ungehorsame Tochter, die du dich auf deine Schatze verlassest und sprichst in deinem Herzen: Wer darf sich an mich machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Siehe, spricht der Herr HERR Zebaoth, ich will Furcht uber dich kommen lassen von alien, die um dich her wohnen, daü ein jeglicher seines Weges vor sich hinaus verstoften werde, und niemand sei, der die Fluchtigen sammle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Aber danach will ich wieder wenden das Gefangnis der Kinder Ammon, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Wider Edom. So spricht der HERR Zebaoth: 1st denn keine Weisheit mehr zu Theman? 1st denn kein Rat mehr bei den Klugen? 1st ihre Weisheit so lose?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fliehet, wendet euch und verkriechet euch tief, ihr Burger zu Dedan; denn ich lasse einen Unfall uber Esau kommen, die Zeit seiner Heimsuchung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Es sollen Weinleser uber dich kommen, die dir kein Nachlesen lassen; und Diebe des Nachts sollen uber dich kommen, die sollen ihnen genug verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Denn ich habe Esau entbloftet und seine heimlichen Orte geoffnet, daß er sich nicht verstecken kann; sein Same, seine Bruder und seine Nachbarn sind verstoret, daß ihrer keiner mehr da ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Doch was ubrig bleibt von deinen Waisen, denen will ich das Leben gonnen, und deine Witwen werden auf mich hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Denn so spricht der HERR: Siehe, diejenigen, so es nicht verschuldet hatten, den Kelch zu trinken, müssen trinken, und du solltest ungestraft bleiben? Du sollst nicht ungestraft bleiben, sondern du muftt auch trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Denn ich habe bei mir selbst geschworen, spricht der HERR, daß Bazra soli ein Wunder, Schmach, Wüste und Fluch werden und alle ihre Stadte eine ewige Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Ich habe gehoret vom HERRN, daß eine Botschaft unter die Heiden gesandt sei: Sammelt euch und kommet her wider sie; machet euch auf zum Streit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Denn siehe, ich habe dich gering gemacht unter den Heiden und verachtet unter den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Dein Trotz und deines Herzens Hochmut hat dich betrogen, weil du in Felsenklüften wohnest und hohe Gebirge inne hast. Wenn du denn gleich dein Nest so hoch machtest als der Adler, dennoch will ich dich von dannen herunterstürzen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Also soil Edom wuste werden, daß alle die, so vorubergehen, sich wundern und pfeifen werden uber alle ihre Plage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'gleichwie Sodom und Gomorrha samt ihren Nachbarn umgekehret ist, spricht der HERR, daß niemand daselbst wohnen noch kein Mensch drinnen hausen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Denn siehe, er kommt herauf wie ein Lowe vom stolzen Jordan her wider die feste Hütte; denn ich will ihn daselbst hereilends laufen lassen. Und werweift, wer der Jüngling ist, den ich wider sie rüsten werde? Denn wer ist mir gleich? Wer will mich meistern, und wer ist der Hirte, der mirwiderstehen kann?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'So horet nun den Ratschlag des HERRN, den er uber Edom hat, und seine Gedanken, die er uber die Einwohner in Theman hat! Was gilt\'s, ob nicht die Hirtenknaben sie schleifen werden und ihre Wohnung zerstoren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'daß die Erde beben wird, wenn es ineinanderfallt; und ihr Geschrei wird man am Schilfmeer horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Siehe, er fleugt herauf wie ein Adler und wird seine Flügel ausbreiten über Bazra. Zur selbigen Zeit wird das Herz der Heiden in Edom sein wie das Herz einer Frau in Kindesnoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Wider Damaskus. Hemath und Arpad stehen jammerlich; sie sind verzagt, denn sie horen ein boses Geschrei; die am Meer wohnen, sind so erschrocken, daß sie nicht Ruhe haben konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damaskus ist verzagt und gibt die Flucht; sie zappelt und ist Angsten und Schmerzen wie eine Frau in Kindesnoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Wie, ist sie nun nicht verlassen, die beruhmte und frohliche Stadt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Darum werden ihre junge Mannschaft auf ihren Gassen daniederliegen und alle ihre Kriegsleute untergehen zur selbigen Zeit, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Und ich will die Mauern zu Damaskus mit Feuer anstecken, daß es die Palaste Benhadads verzehren soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Wider Kedar und die Konigreiche Hazors, welche Nebukadnezar, der Konig zu Babel, schlug. So spricht der HERR: Wohlauf, ziehet herauf nach Kedar und verstoret die Kinder gegen Morgen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Man wird ihnen ihre Hutten und Herde nehmen; ihre Gezelte, alle Gerate und Kamele werden sie wegfuhren; und man wird schrecklich über sie rufen um und um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fliehet, hebet euch eilends davon! Verkriechet euch tief, ihr Einwohner in Hazor, spricht der HERR; denn Nebukadnezar, der Konig zu Babel, hat etwas im Sinn wider euch und meinet euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Wohlauf, ziehet herauf wider ein Volk, das genug hat und sicher wohnet, spricht der HERR: sie haben weder Tur noch Riegel und wohnen alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Ihre Kamele sollen geraubet und die Menge ihres Viehes genommen werden; und ich will sie zerstreuen in alle Winde, die in den Winkeln wohnen; und von alien Orten her will ich ihr Ungluck uber sie kommen lassen, spricht der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'daß Hazor soil eine Drachenwohnung und eine ewige Wuste werden, daß niemand daselbst wohne und kein Mensch drinnen hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Dies ist das Wort des HERRN, welches geschah zu Jeremia, dem Propheten, wider Elam im Anfang des Konigreichs Zedekias, des Konigs Judas, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So spricht der HERR Zebaoth: Siehe, ich will den Bogen Elams zerbrechen, ihre vornehmste Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Und will die vier Winde aus den vier Ortern des Himmels über sie kommen lassen und will sie in alle dieselbigen Winde zerstreuen, daß kein Volk sein soil, dahin nicht Vertriebene aus Elam kommen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Und ich will Elam verzagt machen vor ihren Feinden und denen, die ihnen nach ihrem Leben stehen, und Ungluck fiber sie kommen lassen mit meinem grimmigen Zorn, spricht der HERR; und will das Schwert hinter ihnen her schicken, bis ich sie aufreibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Meinen Stuhl will ich in Elam setzen und will beide, den Konig und die Fursten, daselbst umbringen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Aber in zukunftiger Zeit will ich das Gefangnis Elams wieder wenden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Dies ist das Wort, welches der HERR durch den Propheten Jeremia geredet hat wider Babel und das Land der Chaldaer:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Verkundiget unter den Heiden und lasset erschallen; werfet ein Panier auf! Lasset erschallen und verberget es nicht und sprechet: Babel ist gewonnen, Bel stehet mit Schanden, Merodach ist zerschmettert, ihre Gotzen stehen mit Schanden, und ihre Gotter sind zerschmettert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Denn es zeucht von Mitternacht ein Volk herauf wider sie, welches wird ihr Land zur Wuste machen, daß niemand drinnen wohnen wird, sondern beide, Leute und Vieh, davonfliehen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'In denselbigen Tagen und zur selbigen Zeit, spricht der HERR, werden kommen die Kinder Israel samt den Kindern Juda und weinend daherziehen und den HERRN, ihren Gott, suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Sie werden forschen nach dem Wege gen Zion, daselbst hin sich kehren: Kommt und lasset uns zum HERRN fugen mit einem ewigen Bunde, des nimmermehr vergessen werden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Denn mein Volk ist wie eine verlorne Herde; ihre Hirten haben sie verführet und auf den Bergen in der Irre gehen lassen, daß sie von Bergen auf die Hugel gegangen sind und ihrer Hurden vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Alles, was sie antraf, das fraft sie; und ihre Feinde sprachen: Wir tun nicht unrecht, darum daß sie sich haben versundiget an dem HERRN in der Wohnung der Gerechtigkeit und an dem HERRN, der ihrer Vater Hoffnung ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Fliehet aus Babel und ziehet aus der Chaldaer Lande und stellet euch als Bocke vor der Herde her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Denn siehe, ich will grofte Volker mit Haufen aus dem Lande gegen Mitternacht erwecken und wider Babel heraufbringen, die sich wider sie sollen rusten, welche sie auch sollen gewinnen; seine Pfeile sind wie eines guten Kriegers, der nicht fehlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Und das Chaldaerland soil ein Raub werden, daß alle, die sie berauben, sollen genug davon haben, spricht der HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'darum daß ihr euch des freuet und rühmet, daß ihr mein Erbteil geplundert habt, und lecket wie die geilen Kalber und wiehert wie die starken Gaule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Eure Mutter stehet mit groften Schanden, und die euch geboren hat, ist zum Spott worden; siehe, unter den Heiden ist sie die geringste, wust, durr und ode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Denn vor dem Zorn des HERRN muft sie unbewohnet und ganz wust bleiben, daß alle, so vor Babel ubergehen, werden sich verwundern und pfeifen uber alle ihre Plage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Rustet euch wider Babel umher, alle Schutzen; schieftet in sie, sparet der Pfeile nicht; denn sie hat wider den HERRN gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Jauchzet uber sie urn und urn, sie muft sich geben; ihre Grundfesten sind gefallen, ihre Mauern sind abgebrochen; denn das ist des HERRN Rache. Rachet euch an ihr; tut ihr, wie sie getan hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Rottet aus von Babel beide den Saemann und den Schnitter in der Ernte, daß ein jeglicher vor dem Schwert des Tyrannen sich kehre zu seinem Volk und ein jeglicher fliehe in sein Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel hat müssen sein eine zerstreuete Herde, die die Lowen verscheucht haben. Am ersten fraft sie der Konig zu Assyrien; danach uberwaltigte sie Nebukadnezar, der Konig zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Darum spricht der HERR Zebaoth, der Gott Israels, also: Siehe, ich will den Konig zu Babel heimsuchen und sein Land, gleichwie ich den Konig zu Assyrien heimgesucht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Israel aber will ich wieder heim zu seiner Wohnung bringen, daß sie auf Karmel und Basan weiden, und ihre Seele auf dem Gebirge Ephraim und Gilead gesattiget werden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Zur selbigen Zeit und in denselbigen Tagen wird man die Missetat Israels suchen, spricht der HERR, aber es wird keine da sein, und die Sunde Judas, aber es wird keine funden werden; denn ich will sie vergeben denen, so ich uberbleiben lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Zeuch hinauf wider das Land, das alles verbittert hat; zeuch hinauf wider die Einwohnerder Heimsuchung; verheere und verbanne ihre Nachkommen, spricht der HERR, und tue alles, was ich dir befohlen habe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Es ist ein Kriegsgeschrei im Lande und grofter Jammer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Wie geht es zu, daß der Hammer der ganzen Welt zerbrochen und zerschlagen ist? Wie geht es zu, daß Babel eine Wuste worden ist unter alien Heiden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Ich habe dir gestellet, Babel; darum bist du auch gefangen, ehe du dich\'s versahest; du bist getroffen und ergriffen, denn du hast dem HERRN getrotzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Der HERR hat seinen Schatz aufgetan und die Waffen seines Zorns hervorgebracht; denn solches hat der Herr HERR Zebaoth in der Chaldaer Lande ausgerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Kommt her wider sie, ihr vom Ende, offnet ihre Kornhauser, werfet sie in einen Haufen und verbannet sie, daß ihr nichts ubrig bleibe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Erwurget alle ihre Rinder, fuhret sie hinab zur Schlachtbank! Wehe ihnen! Denn der Tag ist kommen, die Zeit ihrer Heimsuchung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Man horet ein Geschrei der Fluchtigen und derer, so entronnen sind aus dem Lande Babel, auf daß sie verkündigen zu Zion die Rache des HERRN, unsers Gottes, und die Rache seines Tempels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Rufet vielen wider Babel, belagert sie um und um, alle Bogenschützen, und laftt keinen davonkommen. Vergeltet ihr, wie sie verdienet hat; wie sie getan, hat, so tut ihr wieder! Denn sie hat stolz gehandelt wider den HERRN, den Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Darum sollen ihre junge Mannschaft fallen auf ihren Gassen und alle ihre Kriegsleute untergehen zur selbigen Zeit, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Siehe, du Stolzer, ich will an dich, spricht der Herr HERR Zebaoth; denn dein Tag ist kommen, die Zeit deiner Heimsuchung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Da soli der Stolze sturzen und fallen, daß ihn niemand aufrichte; ich will seine Stadte mit Feuer anstecken, das soil alles, was um ihn her ist, verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So spricht der HERR Zebaoth: Siehe, die Kinder Israel samt den Kindern Juda müssen Gewalt und Unrecht leiden; alle, die sie gefangen weggeführet haben, halten sie und wollen sie nicht loslassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Aber ihr Erloser ist stark, der heilit HERR Zebaoth; der wird ihre Sache so ausführen, daß er das Land bebend und die Einwohner zu Babel zitternd mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Schwert soil kommen, spricht der HERR, uber die Chaldaer und uber die Einwohner zu Babel und uber ihre Fursten und uber ihre Weisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Schwert soil kommen uber ihre Weissager, daß sie zu Narren werden. Schwert soil kommen uber ihre Starken, daß sie verzagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Schwert soil kommen uber ihre Rosse und Wagen und alien Pobel, so drinnen ist, daß sie zu Weibern werden. Schwert soil kommen uber ihre Schatze, daß sie geplündert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Trockenheit soil kommen uber ihre Wasser, daß sie versiegen; denn es ist ein Gotzenland und trotzen auf ihre schrecklichen Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Darum sollen ungeheure Tiere und Vogel drinnen wohnen und die jungen Straulien; und soli nimmermehr bewohnet werden, und niemand drinnen hausen fur und fur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'gleichwie Gott Sodom und Gomorrha samt ihren Nachbarn umgekehret hat, spricht der HERR, daß niemand drinnen wohne, noch kein Mensch drinnen hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Siehe, es kommt ein Volk von Mitternacht her; viel Heiden und viel Konige werden von der Seite des Landes sich aufmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Die haben Bogen und Schild, sie sind grausam und unbarmherzig; ihr Geschrei ist wie das Brausen des Meers; sie reiten auf Rossen, gerustet wie Kriegsmanner wider dich, du Tochter Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Wenn der Kbnig zu Babel ihr Gerucht horen wird, so werden ihm die Fauste entsinken; ihm wird so angst und bange werden wie einer Frau in Kindesnoten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Siehe, er kommt herauf wie ein Lowe vom stolzen Jordan wider die festen Hütten; denn ich will ihn daselbst her eilends laufen lassen. Und wer weili, wer der Jungling ist, den ich wider sie rüsten werde? Denn wer. ist mir gleich? Wer will mich meistern, und wer ist der Hide, der mir widerstehen kann?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'So horet nun den Ratschlag des HERRN, den er uber Babel hat, und seine Gedanken, die er hat uber die Einwohner im Lande der Chaldaer! Was gilt\'s, ob nicht die Hirtenknaben sie schleifen werden und ihre Wohnung zerstoren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Und die Erde wird beben von dem Geschrei, und wird unter den Heiden erschallen, wenn Babel gewonnen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So spricht, der HERR: Siehe, ich will einen scharfen Wind erwecken wider Babel und wider ihre Einwohner, die sich wider mich gesetzt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Ich will auch Worfler gen Babel schicken, die sie worfeln sollen und ihr Land ausfegen, die allenthalben um sie sein werden am Tage ihres Unglucks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Denn ihre Schützen werden nicht schieüen, und ihre Geharnischten werden sich nicht wehren konnen. So verschonet nun ihrer jungen Mannschaft nicht, verbannet all ihr Heer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'daß die Erschlagenen da liegen, im Lande der Chaldaer und die Erstochenen auf ihren Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Denn Israel und Juda sollen nicht Witwen von ihrem Gott, dem HERRN Zebaoth, gelassen werden. Denn jener Land hat sich hoch verschuldet am Heiligen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fliehet aus Babel, damit ein jeglicher seine Seele errette, daß ihr nicht untergehet in ihrer Missetat! Denn dies ist die Zeit der Rache des HERRN, der ein Vergelter ist und will sie bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Der güldene Kelch zu Babel, der alle Welt trunken gemacht hat, ist in der Hand des HERRN. Alle Heiden haben von ihrem Wein getrunken, darum sind die Heiden so toll worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Wie plotzlich ist Babel gefallen und zerschmettert! Heulet uber sie; nehmet auch Salben zu ihren Wunden, ob sie vielleicht mochte heil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Wir heilen Babel; aber sie will nicht heil werden. So laftt sie fahren, und laftt uns ein jeglicher in sein Land ziehen! Denn ihre Strafe reicht bis an den Himmel und langet hinauf bis an die Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Der HERR hat unsere Gerechtigkeit hervorgebracht. Kommt, laftt uns zu Zion erzahlen die Werke des HERRN, unsers Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Ja, polieret nun die Pfeile wohl und rustet die Schilde! Der HERR hat den Mut der Konige in Medien erweckt. Denn seine Gedanken stehen wider Babel, daß er sie verderbe; denn dies ist die Rache des HERRN, die Rache seines Tempels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Ja, stecket nun Panier auf die Mauern zu Babel, nehmet die Wache ein, setzet Wachter, bestellet die Hut! Denn der HERR gedenket etwas und wird auch tun, was er wider die Einwohner zu Babel geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Die du an großen Wassern wohnest und große Schatze hast: dein Ende ist kommen, und dein Geiz ist aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Der HERR Zebaoth hatbei seiner Seele geschworen: Ich will dich mit Menschen fallen, als waren\'s Kafer, die sollen dir ein Liedlein singen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'der die Erde durch seine Kraft gemacht hat und den Weltkreis durch seine Weisheit bereitet und den Himmel ordentlich zugerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Wenn er donnert, so ist da Wasser die Menge unter dem Himmel; er zeucht die Nebel auf vom Ende der Erde; er macht die Blitze im Regen und laßt den Wind kommen aus heimlichen Ortern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Alle Menschen sind Narren mit ihrer Kunst, und alle Goldschmiede stehen mit Schanden mit ihren Bildern; denn ihre Gotzen sind Trugerei und haben kein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Es isteitel nichts und verfuhrerisch Werk; sie müssen umkommen, wenn sie heimgesucht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Aber also ist der nicht, der Jakobs Schatz ist, sondern der alle Dinge schafft, der ist\'s; und Israel ist die Rute seines Erbes. Er heifit HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Du bist mein Hammer, meine Kriegswaffe; durch dich habe ich die Heiden zerschmissen und die Konigreiche zerstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Ich will deine Rosse und Reiter zerscheitern; ich will deine Wagen und Fuhrmanner zerschmeißen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'ich will deine Manner und Weiber zerschmeißen; ich will deine Alten und Jungen zerschmeißen; ich will deine Jünglinge und Jungfrauen zerschmeißen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'ich will deine Hirten und Herde zerschmeißen; ich will deine Bauern und Joch zerschmeißen; ich will deine Fursten und Herren zerschmeißen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Denn ich will Babel und alien Einwohnern der Chaldaer vergelten alle ihre Bosheit, die sie an Zion begangen haben vor euren Augen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Siehe, ich will an dich, du schadlicher Berg, der du alle Welt verderbest, spricht der HERR; ich will meine Hand uber dich strecken und dich von den Felsen herabwalzen und will einen verbrannten Berg aus dirmachen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'daß man weder Eckstein noch Grundstein aus dir nehmen konne, sondern eine ewige Wüste sollst du sein, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Werfet Panier auf im Lande, blaset die Posaunen unter den Heiden, heiliget die Heiden wider sie; rufet wider sie die Konigreiche Ararat, Meni und Askenas; bestellet Hauptleute wider sie; bringet Rosse herauf wie flatternde Kafer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Heiliget die Heiden wider sie, namlich die Konige aus Medien samt alien ihren Fursten und Herren und das ganze Land ihrer Herrschaft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'daß das Land erbebe und erschrecke; denn die Gedanken des HERRN wollen erfullet werden wider Babel, daß er das Land Babel zur Wüste mache, darin niemand wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Die Heiden zu Babel werden nicht zu Felde ziehen durfen, sondern müssen in der Festung bleiben. Ihre Starke ist aus und sind Weiber worden; ihre Wohnungen sind angesteckt und ihre Riegel zerbrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Es lauft hie einer und da einer dem andern entgegen, und eine Botschaft begegnet hie und da der andern, dem Konige zu Babel anzusagen, daß seine Stadt gewonnen sei bis ans Ende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'und die Furt eingenommen und die Seen ausgebrannt sind, und die Kriegsleute seien blode worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Denn also spricht der HERR Zebaoth, der Gott Israels: Die Tochter Babel ist wie eine Tenne, wenn man darauf drischet; es wird ihre Ernte gar schier kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadnezar, der Konig zu Babel, hat mich gefressen und umgebracht; er hat aus mir ein leer Gefaß gemacht; er hat mich verschlungen wie ein Drache; er hat seinen Bauch gefullet mit meinem Niedlichsten; er hat mich verstoßen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Nun aberfindet sich uber Babel der Frevel an mir begangen, und mein Fleisch, spricht die Einwohnerin zu Zion, und mein Blut uber die Einwohner zu Chaldaa, spricht Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Darum spricht der HERR also: Siehe, ich will dir deine Sache ausfuhren und dich rachen; ich will ihr Meer austrocknen und ihre Brunnen versiegen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Und Babel soil zum Steinhaufen und zur Drachenwohnung werden, zum Wunder und zum Anpfeifen; daß niemand drinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Sie sollen miteinander brullen wie die Lowen und schreien wie die jungen Lowen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Ich will sie mit ihrem Trinken in die Hitze setzen und will sie trunken machen, daß sie frohlich werden und einen ewigen Schlaf schlafen, von dem sie nimmermehr aufwachen sollen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Ich will sie herunterführen wie Lammer zur Schlachtbank, wie die Widder mit den Bocken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Wie ist Sesach so gewonnen und die Berühmte in aller Welt so eingenommen! Wie ist Babel so zum Wunder worden unter den Heiden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Es ist ein Meer uber Babel gegangen; und sie ist mitdesselbigen Wellen Menge bedeckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Ihre Stadte sind zur Wüste und zu einem dürren, oden Lande worden, im Lande, da niemand innen wohnet und da kein Mensch innen wandelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Denn ich habe den Bel zu Babel heimgesucht und habe aus seinem Rachen gerissen, das er verschlungen hatte; und sollen die Heiden nicht mehr zu ihm laufen; denn es sind auch die Mauern zu Babel zerfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Ziehet heraus, mein Volk, und errette ein jeglicher seine Seele vor dem grimmigen Zorn des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Euer Herz mochte sonst weich werden und verzagen vor dem Geschrei, das man im Lande horen wird. Denn es wird ein Geschrei im Jahr gehen und nach demselbigen im andern Jahr auch ein Geschrei über Gewalt im Lande, und wird ein Furst wider den andern sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Darum siehe, es kommt die Zeit, daß ich die Gotzen zu Babel heimsuchen will, und ihr ganzes Land zuschanden werden soil, und ihre Erschlagenen drinnen liegen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Himmel und Erde und alles, was drinnen ist, werden jauchzen über Babel, dafi ihre Verstorer von Mitternacht kommen sind, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Und wie Babel in Israel die Erschlagenen gefallet hat, also sollen zu Babel die Erschlagenen gefallet werden im ganzen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'So ziehet nun hin, die ihr dem Schwert entronnen seid, und saumet euch nicht! Gedenket des HERRN in fernem Lande und last euch Jerusalem im Herzen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Wir waren zuschanden worden, da wir die Schmach horen mußten, und die Schande unser Angesicht bedeckte, da die Fremden über das Heiligtum des Hauses des HERRN kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Darum siehe, die Zeit kommt, spricht der HERR, dafi ich ihre Gotzen heimsuchen will, und im ganzen Lande sollen die todlich Verwundeten seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Und wenn Babel gen Himmel stiege und ihre Macht in der Hohe test machte, so sollen doch Verstorer von mir über sie kommen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Man hort ein Geschrei zu Babel und einen grolien Jammer in der Chaldaer Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Denn der HERR verstoret Babel; er verderbet sie mit solchem großen Geschrei und Getümmel, dafi ihre Wellen brausen wie die graven Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Denn es ist über Babel der Verstorer kommen; ihre Heiden werden gefangen, ihre Bogen werden zerbrochen; denn der Gott der Rache, der HERR, bezahlet sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Ich will ihre Fürsten, Weisen, Herren und Hauptleute und Krieger trunken machen, daß sie einen ewigen Schlaf sollen schlafen, davon sie nimmermehr aufwachen, spricht der Konig, der da heilit HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So spricht der HERR Zebaoth: Die Mauern der großen Babel sollen untergraben und ihre hohen Tore mit Feuer angesteckt werden, daß der Heiden Arbeit verloren sei und verbrannt werde, was die Volker mit Mühe erbauet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Dies ist das Wort, das der Prophet Jeremia befahl Seraja, dem Sohn Nerias, des Sohns Mahseas, da er zog mit Zedekia, dem Konige in Juda, gen Babel im vierten Jahr seines Konigreichs. Und Seraja war ein friedsamer Furst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Und Jeremia schrieb all das Unglück, so uber Babel kommen sollte, in ein Buch, namlich alle diese Worte, die wider Babel geschrieben sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Und Jeremia sprach zu Seraja: Wenn du gen Babel kommst, so schaue zu und lies alle diese Worte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'und sprich: HERR, du hast geredet wider diese Statte, daß du sie willst ausrotten, daß niemand drinnen wohne, weder Mensch noch Vieh, sondern ewiglich wüst sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Und wenn du das Buch hast ausgelesen, so binde einen Stein daran und wirfs in den Phrath');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'und sprich: Also soil Babel versenkt werden und nicht wiederaufkommen von dem Unglück, das ich über sie bringen will, sondern vergehen. So feme hat Jeremia geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedekia war einundzwanzig Jahre alt, da er Konig ward, und regierete elf Jahre zu Jerusalem. Seine Mutter hiefi Hamutal, eine Tochter Jeremias zu Libna.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Und tat, das dem HERRN übel gefiel, gleichwie Jojakim getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Denn es ging des HERRN Zorn über Jerusalem und Juda, bis er sie von seinem Angesicht verwarf. Und Zedekia fiel ab vom Konige zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Aber im neunten Jahr seines Konigreichs, am zehnten Tage des zehnten Monden, kam Nebukadnezar, der Konig zu Babel, samt all seinem Heer wider Jerusalem und belagerten sie und machten eine Schanze ringsumher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Und blieb also, die Stadt belagert bis ins elfte Jahr des Konigs Zedekia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Aber am neunten Tage des vierten Monden nahm der Hunger überhand in der Stadt, und hatte das Volk vom Lande nichts mehr zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Da brach man in die Stadt; und alle Kriegsleute gaben die Flucht und zogen zur Stadt hinaus bei der Nacht, des Weges zum Tor zwischen den zwo Mauern, zum Garten des Konigs. Aber die Chaldaer lagen urn die Stadt her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Und da diese zogen des Weges durchs Feld, jagte der Chaldaer Heer dem Konige nach und ergriffen Zedekia in dem Felde bei Jericho; da zerstreuete sich all sein Heer von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Und sie fingen den Konig und brachten ihn hinauf dem Konige zu Babel gen Riblath, die im Lande Hemath liegt; der sprach ein Urteil uber ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Allda ließ der Konig zu Babel die Kinder Zedekias vor seinen Augen erwürgen und erwürgete alle Fürsten Judas zu Riblath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Aber Zedekia liefi er die Augen ausstechen und ließ ihn mit zwo Ketten binden; und führete ihn also der Konig zu Babel gen Babel und legte ihn ins Gefangnis, bis daß er starb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Am zehnten Tag des funften Monden, welches ist das neunzehnte Jahr Nebukadnezars, des Konigs zu Babel, kam Nebusar-Adan, der Hauptmann, der stets urn den Konig zu Babel war, gen Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'und verbrannte des HERRN Haus und des Konigs Haus und alle Hauser zu Jerusalem; alle großen Hauser verbrannte er mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Und das ganze Heer, der Chaldaer, so bei dem Hauptmann war, rissen urn alle Mauern zu Jerusalem ringsumher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Aber das arme Volk und andere Volk, so noch übrig war in der Stadt, und die zum Konig zu Babel fielen, und das übrige Handwerksvolk führete Nebusar-Adan, der Hauptmann, gefangen weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Und vom armen Volk auf dem Lande lieli Nebusar-Adan, der Hauptmann, bleiben Weingartner und Ackerleute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Aber die ehernen Saulen am Hause des HERRN und das Gestuhle und das eherne Meer am Hause des HERRN zerbrachen die Chaldaer und führeten all das Erz von denselbigen gen Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Und die Kessel, Schaufeln, Messer, Becken, Kellen und alle ehernen Gefaße, die man im Gottesdienst pflegte zu brauchen, nahmen sie weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Dazu nahm der Hauptmann, was gulden und silbern war, an Bechern, Rauchtopfen, Becken, Kesseln, Leuchtern, Loffeln und Schalen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'die zwo Saulen, das einzelne Meer, die zwolf ehernen Rinder, die anstatt des Gestuhles stunden, welche der Konig Salomo hatte lassen machen zum Hause des HERRN. Dieses alles Gerates Erz war unermeßlich viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Der zwo Saulen aber war eine jegliche achtzehn Ellen hoch, und eine Schnur zwolf Ellen lang reichte urn sie her, und war vier Finger dick und inwendig hohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Und stund aufjeglicherein eherner Knauf, fünf Ellen hoch, und Reife und Granatapfel waren an jeglichem Knauf ringsumher, alles ehern; und war eine Saule wie die andere, die Granatapfel auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Es waren der Granatapfel sechsundneunzig dran, und alter Granatapfel waren hundert an einem Reif ringsumher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Und der Hauptmann nahm den Priester Seraja aus der ersten Ordnung und den Priester Zephanja aus derandern Ordnung und drei Turhuter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'und einen Kammerer aus der Stadt, welcher uber die Kriegsleute gesetzt war, und sieben Manner, welche urn den Konig sein muliten, die in der Stadt funden wurden, dazu Sopher, den Heerfursten, der das Landvolk zu mustern pflegte, dazu sechzig Mann Landvolks, so in der Stadt funden wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Diese nahm Nebusar-Adan, der Hauptmann, und brachte sie dem Konige zu Babel gen Riblath.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Und der Konig zu Babel schlug sie tot zu Riblath, die im Lande Hemath liegt. Also ward Juda aus seinem Lande weggeführet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dies ist das Volk, welches Nebukadnezar weggeführet hat, namlich im siebenten Jahr dreitausend und dreiundzwanzig Juden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'im achtzehnten Jahr aber des Nebukadnezar achthundert und zweiunddreißig Seelen aus Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Und im dreiundzwanzigsten Jahr des Nebukadnezar führete Nebusar-Adan, der Hauptmann, siebenhundert und fünfundvierzig Seelen weg aus Juda. Alter Seelen sind viertausend und sechshundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Aber im siebenunddreifügsten Jahr, nachdem Jojachin, der Konig zu Juda, weggeführet war, am fünfundzwanzigsten Tage des zwolften Monden, erhub Evil-Merodach, der Konig zu Babel, im Jahr, da er Konig ward, das Haupt Jojachins, des Konigs Judas, und liei J ihn aus dem Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Und redete freundlich mit ihm; und setzte seinen Stuhl über der Konige Stühle, die bei ihm zu Babel waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Und wandelte ihm seines Gefangnisses Kleider, daß er vor ihm ali stets sein Leben lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Und ihm ward stets seine Unterhaltung vom Konige zu Babel gegeben, wie es ihm verordnet war, sein ganzes Leben lang, bis an sein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Wie liegt die Stadt so wuste, die voll Volks war! Sie ist wie eine Witwe. Die eine Furstin unter den Heiden und eine Konigin in den Landern war, muli nun dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Sie weinet des Nachts, daß ihr die Tranen über die Backen laufen. Es ist niemand unter alien ihren Freunden, der sie troste; alle ihre Nachsten verachten sie und sind ihre Feinde worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda ist gefangen im Elend und schwerem Dienst; sie wohnet unter den Heiden und findet keine Ruhe; alle ihre Verfolger halten sie ubel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Die Straiten gen Zion liegen wuste, weil niemand auf kein Fest kommt; alle ihre Tore stehen ode; ihre Priester seufzen, ihre Jungfrauen sehen jammerlich, und sie ist betrubt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ihre Widersacher schweben empor, ihren Feinden gehet es wohl; denn der HERR hat sie voll Jammers gemacht urn ihrer groten Sünden willen; und sind ihre Kinder gefangen vor dem Feinde hingezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Es ist von der Tochter Zion aller Schmuck dahin. Ihre Fürsten sind wie die Widder, die keine Weide finden und matt vor dem Treiber hergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem denkt in dieser Zeit, wie elend und verlassen sie ist, und wieviel Gutes sie von alters her gehabt hat, weil all ihr Volk daniederliegt unter dem Feinde und ihr niemand hilft; ihre Feinde sehen ihre Lust an ihr und spotten ihrer Sabbate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem hat sich versundiget, darum muß sie sein wie ein unrein Weib. Alle, die sie ehrten, verschmahen sie jetzt, weil sie ihre Scham sehen; sie aber seufzet und ist zuruckgekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ihr Unflat klebet an ihrem Saum. Sie hatte nicht gemeinet, daß ihrzuletzt so gehen würde. Sie ist ja zu greulich heruntergestoten und hat dazu niemand, der sie trostet. Ach, HERR, siehe an mein Elend; denn der Feind pranget sehr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Der Feind hat seine Hand an alle ihre Kleinode gelegt; denn sie mulite zusehen, daß die Heiden in ihr Heiligtum gingen, davon du geboten hast, sie sollten nicht in deine Gemeine kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'All ihr Volk seufzet und gehet nach Brot; sie geben ihre Kleinode urn Speise, dafi sie die Seele laben. Ach, HERR, siehe doch und schaue, wie schnode ich worden bin!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Euch sage ich alien, die ihr vorubergehet: Schauet doch und sehet, ob irgendein Schmerz sei wie mein Schmerz, der mich getroffen hat. Denn der HERR hat mich voll Jammers gemacht am Tage seines grimmigen Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Er hat ein Feuer aus der Hohe in meine Beine gesandt und dasselbige lassen walten; er hat meinen Füten ein Netz gestellet und mich zuruckgeprellet; er hat mich zur Wuste gemacht, dafi ich taglich trauern muli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Meine schweren Sunden sind durch seine Strafe erwachet und mit Haufen mir auf den Hals kommen, daß mir alle meine Kraft vergehet. Der HERR hat mich also zugerichtet, daü ich nicht aufkommen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Der HERR hat zertreten alle meine Starken, so ich hatte; er hat über mich ein Fest ausrufen lassen, meine junge Mannschaft zu verderben. Der HERR hat der Jungfrauen Tochter Juda eine Kelter treten lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Darum weine ich so, und meine beiden Augen fliefien mit Wasser, daü der Troster, der meine Seele sollte erquicken, feme von mir ist. Meine Kinder sind dahin, denn der Feind hat die Oberhand gekriegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Zion streckt ihre Hande aus, und ist doch niemand, der sie troste; denn der HERR hat rings urn Jakob her seinen Feinden geboten, daü Jerusalem muü zwischen ihnen sein wie ein unrein Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Der HERR ist gerecht; denn ich bin seinem Munde ungehorsam gewesen. Horet, alle Volker, und schauet meinen Schmerz! Meine Jungfrauen und Junglinge sind ins Gefangnis gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Ich rief meine Freunde an, aber sie haben mich betrogen. Meine Priester und Altesten in der Stadt sind verschmachtet, denn sie gehen nach Brot, damit sie ihre Seele laben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Ach, HERR, siehe doch, wie bange ist mir, daü mir\'s im Leibe davon wehe tut! Mein Herz wallet mir in meinem Leibe; denn ich bin hochbetrubt. Drauten hat mich das Schwert und im Hause hat mich der Tod zur Witwe gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Man horet es wohl, daß ich seufze, und habe doch keinen Troster; alle meine Feinde horen mein Ungluck und freuen sich; das machst du. So lali doch den Tag kommen, den du ausrufest, daß ihnen gehen soil wie mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Lafi alle ihre Bosheit vor dich kommen und richte sie zu, wie du mich urn aller meiner Missetat willen zugerichtet hast; denn meines Seufzens istviel, und mein Herz ist betrubt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Wie hat der HERR die Tochter Zion mit seinem Zorn uberschuttet! Er hat die Herrlichkeit Israels vom Himmel auf die Erde geworfen. Er hat nicht gedacht an seinen Fulischemel am Tage seines Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Der HERR hat alle Wohnungen Jakobs ohne Barmherzigkeit vertilget; er hat die Festen der Tochter Juda abgebrochen in seinem Grimm und geschleift; er hat entweihet beide, ihr Konigreich und ihre Fürsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Er hat alles Horn Israels in seinem grimmigen Zorn zerbrochen; er hat seine rechte Hand hinter sich gezogen, da der Feind kam, und hat in Jakob ein Feuer angesteckt, das umher verzehret;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'er hat seinen Bogen gespannet wie ein Feind; seine rechte Hand hat er gefuhret wie ein Widerwartiger und hat erwurget alles, was lieblich anzusehen war, und seinen Grimm wie ein Feuer ausgeschuttet in der Hutte der Tochter Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Der HERR ist gleichwie ein Feind; er hat vertilget Israel, er hat vertilget alle ihre Palaste und hat seine Festen verderbet; er hat der Tochter Juda viel Klagens und Leides gemacht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'er hat sein Gezelt zerwuhlet wie einen Garten und seine Wohnung verderbet. Der HERR hat zu Zion beide, Feiertag und Sabbat, lassen vergessen und in seinem grimmigen Zorn beide, Konig und Priester, schanden lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Der HERR hat seinen Altar verworfen und sein Heiligtum verbannet; er hat die Mauern ihrer Palaste in des Feindes Hande gegeben, daß sie im Hause des HERRN geschrieen haben wie an einem Feiertage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Der HERR hat gedacht zu verderben die Mauern der Tochter Zion; er hat die Richtschnur darübergezogen und seine Hand nicht abgewendet, bis er sie vertilget; die Zwinger stehen klaglich, und die Mauer liegt jammerlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Ihre Tore liegen tief in der Erde; er hat ihre Riegel zerbrochen und zunichte gemacht. Ihre Konige und Fursten sind unter den Heiden, da sie das Gesetz nicht üben konnen und ihre Propheten kein Gesicht vom HERRN haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Die Altesten der Tochter Zion liegen auf der Erde und sind stille; sie werfen Staub auf ihre Haupter und haben Sacke angezogen; die Jungfrauen von Jerusalem hangen ihre Haupter zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Ich habe schier meine Augen ausgeweinet, daß mir mein Leib davon wehe tut; meine Leber ist auf die Erde ausgeschuttet uber dem Jammer der Tochter meines Volks, da die Sauglinge und Unmündigen auf den Gassen in der Stadt verschmachteten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'da sie zu ihren Muttern sprachen: Wo ist Brot und Wein? da sie auf den Gassen in der Stadt verschmachteten wie die todlich Verwundeten und in den Armen ihrer Mutter den Geist aufgaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Ach, du Tochter Jerusalem, wem soil ich dich gleichen und wofur soil ich dich rechnen, du Jungfrau Tochter Zion? Wem soil ich dich vergleichen, damit ich dich trosten mochte? Denn dein Schaden ist graft, wie ein Meer; wer kann dich heilen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Deine Propheten haben dir lose und torichte Gesichte geprediget und dir deine Missetat nicht geoffenbaret, damit sie dein Gefangnis gewehret hatten, sondern haben dir geprediget lose Predigt, damit sie dich zum Land hinaus predigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Alle, die vorubergehen, klappen mit Handen, pfeifen dich an und schutteln den Kopf uber der Tochter Jerusalem: Ist das die Stadt, von der man sagte, sie sei die allerschonste, der sich das ganze Land freuete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Alle deine Feinde sperren ihr Maul auf wider dich, pfeifen dich an, blecken die Zahne und sprechen: Heh! wir haben sie vertilget; das ist der Tag; des wir haben begehret; wir haben\'s erlanget, wir haben\'s eriebt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Der HERR hatgetan, was er vorhatte; er hat sein Wort erfullet, das er langst zuvor geboten hat; er hat ohne Barmherzigkeit zerstoret; er hat den Feind fiber dir erfreuet und deiner Widersacher Horn erhohet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Ihr Herz schrie zum HERRN. O du Mauer der Tochter Zion, laft Tag und Nacht Tranen herabflieften wie ein Bach; hore auch nicht auf, und dein Augapfel lasse nicht ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Stehe des Nachts auf und schreie; schütte dein Herz aus in der ersten Wache gegen dem HERRN wie Wasser; hebe deine Hande gegen ihn auf urn der Seelen willen deiner jungen Kinder, die vor Hunger verschmachten vorne an alien Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'HERR, schaue und siehe doch, wen du doch so verderbet hast! Sollen denn die Weiber ihres Leibes Frucht essen, die jüngsten Kindlein, einer Spanne lang? Sollen denn Propheten und Priester in dem Heiligtum des HERRN so erwurget werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Es lagen in den Gassen auf der Erde Knaben und Alte; meine Jungfrauen und Junglinge sind durchs Schwert gefallen. Du hast gewfirget am Tage deines Zorns, du hast ohne Barmherzigkeit geschiachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Du hast meinen Feinden umher gerufen wie auf einen Feiertag, daß niemand am Tage des Zorns des HERRN entronnen und uberblieben ist. Die ich ernahret und erzogen habe, die hat der Feind umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ich bin ein elender Mann, der die Rute seines Grimmes sehen muft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Er hat mich geführet und lassen gehen in die Finsternis und nicht ins Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Er hat seine Hand gewendet wider mich und handelt gar anders mit mir fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Er hat mein Fleisch und Haut alt gemacht und mein Gebein zerschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Er hat mich verbauet und mich mit Galle und Mühe umgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Er hat mich in Finsternis gelegt, wie die Toten in der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Er hat mich vermauert, daß ich nicht heraus kann, und mich in harte Fesseln gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Und wenn ich gleich schreie und rufe, so stopft er die Ohren zu vor meinem Gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Er hat meinen Weg vermauert mit Werkstücken und meinen Steig umgekehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Er hat auf mich gelauert wie ein Bar, wie ein Lowe im Verborgenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Er laftt mich des Weges fehlen. Er hat mich zerstücket und zunichte gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Er hat seinen Bogen gespannet und mich dem Pfeil zum Ziel gesteckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Er hat aus dem Kocher in meine Nieren schieften lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Ich bin ein Spott allem meinem Volk und taglich ihr Liedlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Er hat mich mit Bitterkeit gesattiget und mit Wermut getranket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Er hat meine Zahne zu kleinen Stucken zerschlagen. Er walzet mich in der Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Meine Seele ist aus dem Frieden vertrieben; ich muft des Guten vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Ich sprach: Mein Vermdgen istdahin und meine Hoffnung am HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Gedenke doch, wie ich so elend und verlassen, mit Wermut und Galle getranket bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Du wirst ja daran gedenken, denn meine Seele sagt mir\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Das nehme ich zu Herzen, darum hoffe ich noch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Die Gute des HERRN ist, daß wir nicht gar aus sind; seine Barmherzigkeit hat noch kein Ende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'sondern sie ist alle Morgen neu, und deine Treue ist graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Der HERR ist mein Teil, spricht meine Seele, darum will ich auf ihn hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Denn der HERR ist freundlich dem, der auf ihn harret, und der Seele, die nach ihm fraget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Es istein kostlich Ding, geduldig sein und auf die Hilfe des HERRN hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Es istein kostlich Ding einem Manne, daß erdas Joch in seiner Jugend trage,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'daß ein Verlassener geduldig sei, wenn ihn etwas uberfallt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'und seinen Mund in den Staub stecke und der Hoffnung erwarte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'und lasse sich auf die Backen schlagen und ihm viel Schmach anlegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Denn der HERR verstoftt nicht ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'sondern er betrubet wohl und erbarmet sich wieder nach seiner groften Gute;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'denn er nicht von Herzen die Menschen plaget und betrubet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'als wollte er alle die Gefangenen auf Erden gar unter seine Füfte zertreten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'und eines Mannes Recht vor dem Allerhochsten beugen lassen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'und eines Menschen Sache verkehren lassen, gleich als sahe es der HERR nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Wer darf denn sagen, daß solches geschehe ohne des HERRN Befehl,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'und daß weder Boses noch Gutes komme aus dem Munde des Allerhochsten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Wie murren denn die Leute im Leben also? Ein jeglicher murre wider seine Sunde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Und laftt uns forschen und suchen unser Wesen und uns zum HERRN bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Laftt uns unser Herz samt den Handen aufheben zu Gott im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Wir, wir haben gesundiget und sind ungehorsam gewesen. Darum hast du billig nicht verschonet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'sondern du hast uns mit Zorn uberschuttet und verfolget und ohne Barmherzigkeit erwurget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Du hast dich mit einer Wolke verdeckt, daß kein Gebet hindurch konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Du hast uns zu Kot und Unflat gemacht unter den Volkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Alle unsere Feinde sperren ihr Maul auf wider uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Wir werden gedrückt und geplagt mit Schrecken und Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Meine Augen rinnen mit Wasserbachen uber dem Jammer der Tochter meines Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Meine Augen flieften und konnen nicht ablassen; denn es ist kein Aufhoren da,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'bis der HERR vom Himmel herabschaue und sehe darein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mein Auge friftt mir das Leben weg urn die Tochter meiner Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Meine Feinde haben mich gehetzet, wie einen Vogel, ohne Ursache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Sie haben mein Leben in einer Grube umgebracht und Steine auf mich geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Sie haben auch mein Haupt mit Wasser uberschuttet. Da sprach ich: Nun bin ich gar dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Ich rief aber deinen Namen an, HERR, unten aus der Grube;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'und du erhoretest meine Stimme. Verbirg deine Ohren nicht vor meinem Seufzen und Schreien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Nahe dich zu mir, wenn ich dich anrufe, und sprich: Furchte dich nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Fuhre du, HERR, die Sache meiner Seele und erlose mein Leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'HERR, schaue, wie mir so unrecht geschieht, und hilf mir zu meinem Recht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du siehest alle ihre Rache und alle ihre Gedanken wider mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'HERR, du horest ihre Schmach und alle ihre Gedanken uber mich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'die Lippen meiner Widerwartigen und ihr Dichten wider mich taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Schaue doch; sie gehen nieder Oder stehen auf, so singen sie von mir Liedlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Vergilt ihnen, HERR, wie sie verdienet haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Laft ihnen das Herz erschrecken und deinen Fluch fühlen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Verfolge sie mit Grimm und vertilge sie unter dem Himmel des HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Wie ist das Gold so gar verdunkelt und das feine Gold so haftlich worden, und liegen die Steine des Heiligtums vorne auf alien Gassen zerstreuet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Die edlen Kinder Zions, dem Golde gleich geachtet, wie sind sie nun den irdenen Topfen verglichen, die ein Topfer macht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Die Drachen reichen die Bruste ihren Jungen und saugen sie; aber die Tochter meines Volks muft unbarmherzig sein, wie ein Strauft in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Dem Saugling klebt seine Zunge an seinem Gaumen vor Durst; die jungen Kinder heischen Brat, und ist niemand, der es ihnen breche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Die vorhin das Niedlichste aften, verschmachten jetzt auf den Gassen; die vorhin in Seiden erzogen sind, die müssen jetzt im Kot liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Die Missetat der Tochter meines Volks ist großer denn die Sunde Sodoms, die plotzlich umgekehret ward, und kam keine Hand dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Ihre Nazaraer waren reiner denn der Schnee und klarer denn Milch; ihre Gestalt war rotlicher denn Korallen; ihr Ansehen warwie Saphir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Nun aber ist ihre Gestalt so dunkel vor Schwarze, daß man sie auf den Gassen nicht kennet; ihre Haut hanget an den Beinen, und sind so dürre als ein Scheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Den Erwürgten durchs Schwert geschah baß wederdenen, so da Hungers starben, die verschmachteten und erstochen wurden vom Mangel der Früchte des Ackers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Es haben die barmherzigsten Weiber ihre Kinder selbst müssen kochen, daß sie zu essen hatten in dem Jammer der Tochter meines Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Der HERR hat seinen Grimm vollbracht, er hat seinen grimmigen Zorn ausgeschuttet; er hat zu Zion ein Feuer angesteckt, das auch ihre Grundfesten verzehret hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Es hatten\'s die Konige auf Erden nicht geglaubt noch alle Leute in der Welt, daß der Widerwartige und Feind sollte zum Tore Jerusalems einziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Es ist aber geschehen urn der Sunde wilien ihrer Propheten und urn der Missetat wilien ihrer Priester, die drinnen der Gerechten Blut vergossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Sie gingen hin und her auf den Gassen wie die Blinden und waren mit Blut besudelt und konnten auch jener Kleider nicht anruhren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'sondern riefen sie an: Weichet, ihr Unreinen; weichet, weichet; ruhret nichts an! Denn sie scheueten sich vorjenen und flohen sie, daß man auch unterden Heiden sagte: Sie werden nicht lange da bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Darum hat sie des HERRN Zorn zerstreuet und will sie nicht mehr ansehen, weil sie die Priester nicht ehreten und mit den Altesten keine Barmherzigkeit übten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Noch gafften unsere Augen auf die nichtige Hilfe, bis sie gleich müde wurden, da wirwarteten auf ein Volk, das uns doch nicht helfen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Man jagte uns, daß wir auf unsern Gassen nicht gehen durften. Da kam auch unser Ende; unsere Tage sind aus, unser Ende ist kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Unsere Verfolger waren schnellerdenn die Adler unterdem Himmel; auf den Bergen haben sie uns verfolget und in der Wüste auf uns gelauert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Der Gesalbte des HERRN, der unser Trost war, ist gefangen worden, da sie uns verstorten, des wir uns trosteten, wirwollten unterseinem Schatten leben unterden Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Ja, freue dich und sei frohlich, du Tochter Edom, die du wohnest im Lande Uz; denn der Kelch wird auch uber dich kommen, du mußt auch trunken und gebloßet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Aber deine Missetat hat ein Ende, du Tochter Zion; er wird dich nicht mehr lassen wegführen; aber deine Missetat, du Tochter Edom, wird er heimsuchen und deine Sünden aufdecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Gedenke, HERR, wie es uns gehet; schau und siehe an unsere Schmach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Unser Erbe ist den Fremden zuteil worden und unsere Hauser den Auslandern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Wir sind Waisen und haben keinen Vater; unsere Mutter sind wie Witwen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Unser eigen Wasser müssen wir urn Geld trinken; unser Holz muß man bezahlt bringen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Man treibt uns uber Hals, und wenn wir schon mude sind, laßt man uns doch keine Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Wir haben uns müssen Agypten und Assur ergeben, auf daß wir doch Brotsattzu essen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Unsere Vater haben gesündiget und sind nicht mehr vorhanden; und wir müssen ihre Missetat entgelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Knechte herrschen über uns, und ist niemand, der uns von ihrer Hand errette.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Wir müssen unser Brot mit Fahr unsers Lebens holen vor dem Schwert in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Unsere Haut ist verbrannt wie in einem Ofen vor dem greulichen Hunger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Sie haben die Weiber zu Zion geschwacht und die Jungfrauen in den Stadten Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Die Fürsten sind von ihnen gehenket, und die Person der Alten hat man nicht geehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Die Jünglinge haben Mühlsteine müssen tragen und die Knaben über dem Holztragen straucheln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Es sitzen die Alten nicht mehr unter dem Tor, und die Jünglinge treiben kein Saitenspiel mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Unsers Herzens Freude hat ein Ende, unser Reigen ist in Wehklagen verkehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Die Krone unsers Haupts ist abgefallen. O wehe, daß wir so gesündiget haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Darum ist auch unser Herz betrübt, und unsere Augen sind finster worden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'urn des Berges Zions wilien, daß er so wüst liegt, daß die Füchse darüberlaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Aber du, HERR, der du ewiglich bleibest und dein Thron fur und für,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'warum willst du unser so gar vergessen und uns die Lange so gar verlassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Bringe uns, HERR, wieder zu dir, daß wir wieder heimkommen; verneue unsere Tage wie vor alters!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Denn du hast uns verworfen und bist allzusehr über uns erzürnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Im dreilügsten Jahr, am funften Tage des vierten Monden, da ich war unter den Gefangenen am Wasser Chebar, tat sich der Himmel auf, und Gott zeigte mir Gesichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Derselbe fünfte Tag des Monden war eben im funften Jahr, nachdem Jojachin, der Konig Judas, war gefangen weggefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Da geschah des HERRN Wort zu Hesekiel, dem Sohne Busis, des Priesters, im Lande der Chaldaer, am Wasser Chebar; daselbst kam die Hand des HERRN uber ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Und ich sah, und siehe, es kam ein ungestümer Wind von Mitternacht her mit einer grolien Wolke voll Feuers, das allenthalben umher glanzte; und mitten in demselben Feuer war es wie lichthell.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Und drinnen war es gestaltet wie vier Tiere, und unter ihnen eins gestaltet wie ein Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Und ein jegliches hatte vier Angesichte und vier Flugel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Und ihre Beine stunden gerade, aber ihre Fulie waren qleichwie runde Fulie und qlanzten wie ein hell, glatt Erz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Und hatten Menschenhande unter ihren Flugeln an ihren vier Orten; denn sie hatten alle vier ihre Angesichte und ihre Flugel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Und derselbigen Flugel war je einer an dem andern. Und wenn sie gingen, durften sie sich nicht herumlenken, sondern wo sie hingingen, gingen sie stracks vor sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Ihre Angesichte zur rechten Seite der viere waren gleich einem Menschen und Lowen; aber zur linken Seite der viere waren Ihre Angesichte gleich einem Ochsen und Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Und ihre Angesichte und Flugel waren obenher zerteilet, daßje zween Flugel zusammenschlugen und mit zween Flugeln ihren Leib bedeckten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Wo sie hingingen, da gingen sie stracks vor sich; sie gingen aber, wohin der Wind stund; und durften sich nicht herumlenken, wenn sie gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Und die Tiere waren anzusehen wie feurige Kohlen, die da brennen, und wie Fackeln, die zwischen den Tieren gingen. Das Feuer aber gab einen Glanz von sich, und aus dem Feuer ging ein Blitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Die Tiere aber liefen hin und her wie ein Blitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Als ich die Tiere so sah, siehe, da stund ein Rad auf der Erde bei den vier Tieren und war anzusehen wie vier Rader.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Und dieselbigen Rader waren wie ein Turkis und waren alle vier eins wie das andere; und sie waren anzusehen, als ware ein Rad im andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Wenn sie gehen sollten, konnten sie in alle ihre vier Orte gehen und durften sich nicht herumlenken, wenn sie gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Ihre Felgen und Hohe waren schrecklich; und ihre Felgen waren voller Augen urn und urn an alien vier Radern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Und wenn die Tiere gingen, so gingen die Rader auch neben ihnen; und wenn die Tiere sich von der Erde emporhuben, so huben sich die Rader auch empor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Wo der Wind hinging, da gingen sie auch hin; und die Rader huben sich neben ihnen empor; denn es war ein lebendiger Wind in den Radern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Wenn sie gingen, so gingen diese auch; wenn sie stunden, so stunden diese auch; und wenn sie sich emporhuben von der Erde, so huben sich auch die Rader neben ihnen empor; denn es war ein lebendiger Wind in den Radern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Oben aber uber den Tieren war es gleich gestaltet wie der Himmel, als ein Kristall, schrecklich, gerade oben uber ihnen ausgebreitet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'daß unter dem Himmel ihre Flugel einer stracks gegen den andern stund, und eines jeglichen Leib bedeckten zween Flugel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Und ich horete die Flugel rauschen wie grolie Wasser und wie ein Geton des Allmachtigen, wenn sie gingen, und wie ein Getümmel in einem Heer. Wenn sie aber stille stunden, so liefien sie die Flugel nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Und wenn sie stille stunden und die Flugel niederlielien, so donnerte es im Himmel oben uber ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Und uber dem Himmel, so oben uber ihnen war, war es gestaltet wie ein Saphir, gleichwie ein Stuhl; und auf demselbigen Stuhl sali einer, gleichwie ein Mensch gestaltet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Und ich sah, und es war wie lichthell, und inwendig war es gestaltet wie ein Feuer urn und urn. Von seinen Lenden uber sich und unter sich, sah ich\'s wie Feuer glanzen urn und urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Gleichwie der Regenbogen stehet in den Wolken, wenn es geregnet hat, also glanzte es urn und urn. Dies war das Ansehen der Herrlichkeit des HERRN. Und da ich\'s gesehen hatte, fiel ich auf mein Angesicht und horete einen reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Und er sprach zu mir: Du Menschenkind, tritt auf deine Fulie, so will ich mit dir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Und da er so mit mir redete, ward ich wieder erquickt und trat auf meine Fulie und horete dem zu, der mit mir redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Und er sprach zu mir: Du Menschenkind, ich sende dich zu den Kindern Israel, zu dem abtrunnigen Volk, so von mir abtrunnig worden sind. Sie samt ihren Vatern haben bis auf diesen heutigen Tag wider mich getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Aber die Kinder, zu welchen ich dich sende, haben harte Kdpfe und verstockte Herzen. Zu denen sollst du sagen: So spricht der Herr HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Sie gehorchen Oder lassen\'s. Es ist wohl ein ungehorsam Haus; dennoch sollen sie wissen, daß ein Prophet unter ihnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Und du, Menschenkind, sollst dich vor ihnen nicht furchten noch vor ihren Worten furchten. Es sind wohl widerspenstige und stachlige Dornen bei dir, und du wohnest unter den Skorpionen; aber du sollst dich nicht furchten vor ihren Worten noch vor ihrem Angesicht dich entsetzen, ob sie wohl ein ungehorsam Haus sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'sondern du sollst ihnen mein Wort sagen, sie gehorchen Oder lassen\'s; denn es ist ein ungehorsam Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Aber du, Menschenkind, hore du, was ich dir sage, und sei nicht ungehorsam, wie das ungehorsame Haus ist. Tu deinen Mund auf und ift, was ich dir geben werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Und ich sah, und siehe, da war eine Hand gegen mich ausgereckt, die hatte einen zusammengelegten Brief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Den breitete sie aus vor mir, und er war beschrieben auswendig und inwendig; und stund drinnen geschrieben: Klage, Ach und Wehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Und er sprach zu mir: Du Menschenkind, ifi, was vor dir ist, namlich diesen Brief, und gehe hin und predige dem Hause Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Da tat ich meinen Mund auf, und er gab mir den Brief zu essen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'und sprach zu mir: Du Menschenkind, du mußt diesen Brief, den ich dirgebe, in deinen Leib essen und deinen Bauch damit fullen. Da aft ich ihn, und er war in meinem Mund so süft als Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Und er sprach zu mir: Du Menschenkind, gehe hin zum Hause Israel und predige ihnen mein Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Denn ich sende dich ja nicht zum Volk, das eine fremde Rede und unbekannte Sprache habe, sondern zum Hause Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ja freilich nicht zu grofien Volkern, die fremde Rede und unbekannte Sprache haben, welcher Worte du nicht verneh men konntest. Und wenn ich dich gleich zu denselbigen sendete, würden sie dich doch gerne horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Aber das Haus Israel will dich nicht horen, denn sie wollen mich selbst nicht horen, denn das ganze Haus Israel hat harte Stirnen und verstockte Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Aber doch habe ich dein Angesicht hart gemacht gegen ihr Angesicht und deine Stirn gegen ihre Stirn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Ja, ich habe deine Stirn so hart als einen Demant, der harder ist denn ein Fels, gemacht. Darum furchte dich nicht, entsetze dich auch nicht vor ihnen, daß sie so ein ungehorsam Haus sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Und er sprach zu mir: Du Menschenkind, alle meine Worte, die ich dir sage, die fasse mit Herzen und nimm sie zu Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Und gehe hin zu den Gefangenen deines Volks und predige ihnen und sprich zu ihnen: So sprichtder Herr HERR; sie horen\'s Oder lassen\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Und ein Wind hub mich auf, und ich horete hinter mir ein Geton wie eines groften Erdbebens: Gelobet sei die Herrlichkeit des HERRN an ihrem Ort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Und war ein Rauschen von den Flügeln der Tiere, die sich aneinander kusseten, und auch das Rasseln der Rader, so hart bei ihnen waren, und das Geton eines groften Erdbebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Da hub mich der Wind auf und fuhrete mich weg. Und ich fuhr dahin und erschrak sehr; aber des HERRN Hand hielt mich fest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Und ich kam zu den Gefangenen, die am Wasser Chebarwohneten, da die Mandeln stunden, im Monden Abib, und setzte mich zu ihnen, die da saften, und blieb daselbst unter ihnen sieben Tage ganz traurig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Und da die sieben Tage urn waren, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Du Menschenkind, ich habe dich zum Wachter gesetzt uber das Haus Israel; du sollst aus meinem Munde das Wort horen und sie von meinetwegen warnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Wenn ich dem Gottlosen sage: Du muftt des Todes sterben, und du warnest ihn nicht und sagst es ihm nicht, damit sich der Gottlose vor seinem gottlosen Wesen hüte, auf daß er lebendig bleibe, so wird der Gottlose urn seiner Sunde willen sterben, aber sein Blut will ich von deiner Hand fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Wo du aber den Gottlosen warnest, und er sich nicht bekehret von seinem gottlosen Wesen und Wege, so wird er urn seiner Sunde willen sterben, aber du hast deine Seele errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Und wenn sich ein Gerechter von seiner Gerechtigkeit wendet und tut Boses, so werde ich ihn lassen anlaufen, daß er muft sterben. Denn weil du ihn nicht gewarnet hast, wird er urn seiner Sunde willen sterben müssen, und seine Gerechtigkeit, die er getan hat, wird nicht angesehen werden; aber sein Blut will ich von deiner Hand fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Wo du aber den Gerechten warnest, daß er nicht sundigen soil, und er sundiget auch nicht, so soil er leben, denn er hat sich warnen lassen; und du hast deine Seele errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Und daselbst kam des HERRN Hand uber mich und sprach zu mir: Mache dich auf und gehe hinaus ins Feld; da will ich mit dir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Und ich machte mich auf und ging hinaus ins Feld; und siehe, da stund die Herrlichkeit des HERRN daselbst, gleichwie ich sie am Wasser Chebar gesehen hatte. Und ich fiel nieder auf mein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Und ich ward erquicket und trat auf meine Füfte. Und er redete mit mir und sprach zu mir: Gehe hin und verschleuft dich in deinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Und du, Menschenkind, siehe, man wird dir Stricke anlegen und dich damit binden, daß du ihnen nicht entgehen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Und ich will dir die Zunge an deinem Gaumen kleben lassen, daß du erstummen sollst und nicht mehr sie strafen mogest; denn es ist ein ungehorsam Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Wenn ich aber mit dir reden werde, will ich dir den Mund auftun, dad du zu ihnen sagen sollst: So spricht der Herr HERR! Wer es horet, der hdre es; wer es ladt, der lasse es; denn es ist ein ungehorsam Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Und du, Menschenkind, nimm einen Ziegel, den lege vor dich und entwirf darauf die Stadt Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Und mache eine Belagerung darum und baue ein Bollwerk darum und grabe einen Schutt darum und mache ein Heer darum und stelle Bocke rings um sie her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Fur dich aber nimm eine eiserne Pfanne, die lad eine eiserne Mauer sein zwischen dir und der Stadt; und richte dein Angesicht gegen sie und belagere sie. Das sei ein Zeichen dem Hause Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Du sollst dich auch auf deine linke Seite legen und die Missetat des Hauses Israel auf dieselbige legen; so viel Tage du darauf liegest, so lange sollst du auch ihre Missetat tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ich will dir aber die Jahre ihrer Missetat zur Anzahl der Tage machen, namlich dreihundertundneunzig Tage; so lange sollst du die Missetat des Hauses Israel tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Und wenn du solches ausgerichtet hast, sollst du danach dich auf deine rechte Seite legen und sollst tragen die Missetat des Hauses Juda vierzig Tage lang, denn ich gebe dir hie auch je einen Tag fur ein Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Und richte dein Angesicht und deinen bloden Arm wider das belagerte Jerusalem und weissage wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Und siehe, ich will dir Stricke anlegen, daß du dich nicht wenden mogest von einer Seite zur andern, bis du die Tage deiner Belagerung vollendet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'So nimm nun zu dir Weizen, Gerste, Bohnen, Linsen, Hirse und Spelt und tu es alles in ein Fall und mache dir so viel Brote daraus, so viele Tage du auf deiner Seite liegest, dad du dreihundertundneunzig Tage daran zu essen habest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'also dall deine Speise, die du taglich essen mudt, sei zwanzig Sekel schwer. Solches sollst du von einer Zeit zur andern essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Das Wasser sollst du auch nach dem Mad trinken, namlich das sechste Teil vom Hin; und sollst solches auch von einer Zeit zur andern trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Gerstenkuchen sollst du essen, die du vor ihren Augen mit Menschenmist backen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Und der HERR sprach: Also mussen die Kinder Israel ihr unrein Brot essen unter den Heiden, dahin ich sie verstoden habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Ich aber sprach: Ach, Herr HERR, siehe, meine Seele ist noch nie unrein worden; denn ich habe von meiner Jugend auf bis auf diese Zeit kein Aas noch Zerrissenes gegessen, und ist nie kein unrein Fleisch in meinen Mund kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Er aber sprach zu mir: Siehe, ich will dir Kuhmist fur Menschenmist zulassen, damit du dein Brot machen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Und sprach zu mir: Du Menschenkind, siehe, ich will den Vorrat des Brots zu Jerusalem wegnehmen, dad sie das Brot essen mussen nach dem Gewicht und mit Kummer und das Wasser nach dem Mad mit Kummer trinken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'darum dad an Brot und Wasser mangeln wird, und einer mit dem andern trauern und in ihrer Missetat verschmachten solien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Und du, Menschenkind, nimm ein Schwert, scharf wie ein Schermesser, und fahre damit uber dein Haupt und Bart und nimm eine Waage und teile sie damit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Das eine dritte Teil sollst du mit Feuer verbrennen mitten in der Stadt, wenn die Tage der Belagerung um sind; das andere dritte Teil nimm und schlage es mit dem Schwert ringsumher; das letzte dritte Teil streue in den Wind, dad ich das Schwert hinter ihnen her ausziehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Nimm aber ein klein wenig davon und binde es in deinen Mantelzipfel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Und nimm wiederum etliches davon und wirfs in ein Feuer und verbrenne es mit Feuer; von dem soli ein Feuer auskommen uber das ganze Haus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'So spricht der Herr HERR: Das ist Jerusalem, die ich unter die Heiden gesetzt habe, und rings um sie her Lander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Sie aber hat mein Gesetz verwandelt in gottlose Lehre mehr denn die Heiden und meine Rechte mehr denn die Lander, so rings um sie her liegen. Denn sie verwerfen mein Gesetz und wollen nicht nach meinen Rechten leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Darum spricht der Herr HERR also: Weil ihr\'s mehr machet denn die Heiden, so um euch her sind, und nach meinen Geboten nicht lebet und nach meinen Rechten nicht tut, sondern nach der Heiden Weise tut, die um euch her sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'so spricht der Herr HERR also: Siehe, ich will auch an dich und will Recht uber dich gehen lassen, dall die Heiden zusehen solien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Und will also mit dir umgehen, als ich nie getan und hinfort nicht tun werde, um aller deiner Greuel willen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'dad in dir die Vater ihre Kinder und die Kinder ihre Vater fressen solien; und will solch Recht uber dich gehen lassen, dad alle deine Ubrigen solien in alle Winde zerstreuet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Darum, so wahr als ich lebe, spricht der Herr HERR, weil du mein Heiligtum mit deinen allerlei Greueln und Gotzen verunreiniget hast, will ich dich auch zerschlagen, und mein Auge soil dein nicht schonen und will nicht gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Es soil das dritte Teil von dir an der Pestilenz sterben und durch Hunger alle werden, und das andere dritte Teil durchs Schwert fallen rings um dich her, und das letzte dritte Teil will ich in alle Winde zerstreuen und das Schwert hinter ihnen her ausziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Also soil mein Zorn vollendet und mein Grimm uber ihnen ausgerichtet werden, daß ich meinen Mut kuhle; und sie sollen erfahren, daß ich, der HERR, in meinem Eifer geredet habe, wenn ich meinen Grimm an ihnen ausgerichtet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Ich will dich zur Wüste und zur Schmach setzen vor den Heiden, so um dich her sind, vor den Augen aller, die vorübergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Und sollsteine Schmach, Hohn, Exempel und Wunder sein alien Heiden, die um dich her sind, wenn ich über dich das Recht gehen lasse mit Zorn, Grimm und zornigem Schelten (das sage ich, der HERR),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'und wenn ich bose Pfeile des Hungers untersie schießen werde, die da schadlich sein sollen, und ich sie ausschießen werde, euch zu verderben, und den Hunger über euch immer großer werden lasse und den Vorrat des Brots wegnehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ja, Hunger und bose wilde Tiere will ich unter euch schicken, die sollen euch ohne Kinder machen; und soil Pestilenz und Flut unter dir umgehen, und will das Schwert über dich bringen. Ich, der HERR, habe es gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Du Menschenkind, kehre dein Angesicht wider die Berge Israels und weissage wider sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'und sprich: Ihr Berge Israels, horet das Wort des Herrn HERRN! So spricht der Herr HERR beide, zu den Bergen und Hügeln, beide, zu den Bachen und Talern: Siehe, ich will das Schwert über euch bringen und eure Hohen umbringen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'daß eure Altare verwüstet und eure Gotzen zerbrochen sollen werden; und will eure Leichname vor den Bildern totschlagen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Ja, ich will die Leichname der Kinder Israel vor euren Bildern fallen und will eure Gebeine um eure Altare her zerstreuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Wo ihrwohnet, da sollen die Stadte wüste und die Hohen zur Einode werden. Denn man wird eure Altare wüste und zur Einode machen und eure Gotzen zerbrechen und zunichte machen und eure Bilder zerschlagen und eure Stifte vertilgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'und sollen Erschlagene unter euch daßegen, daß ihr erfahret, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Ich will aber etliche von euch überbleiben lassen, die dem Schwert entgehen unter den Heiden, wenn ich euch in die Lander zerstreuet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Dieselbigen eure Ubrigen werden dann an mich gedenken unter den Heiden, da sie gefangen sein müssen, wenn ich ihr hurisch Herz, so von mir gewichen, und ihre hurischen Augen, so nach ihren Gotzen gesehen, zerschlagen habe; und wird sie gereuen die Bosheit, die sie durch allerlei ihre Greuel begangen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Und sollen erfahren, daß ich der HERR sei und nicht umsonst geredet habe, solches Unglück ihnen zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'So spricht der Herr HERR: Schlage deine Hande zusammen und strampel mitdeinen Füßen und sprich: Wehe über alle Greuel der Bosheit im Hause Israels, darum sie durch Schwert, Hunger und Pestilenz fallen müssen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Wer feme ist, wird an der Pestilenz sterben, und wer nahe ist, wird durchs Schwert fallen; wer aber überbleibet und davor behütet ist, wird Hungers sterben. Also will ich meinen Grimm unter ihnen vollenden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'daß ihr erfahren sollt, ich sei der HERR, wenn ihre Erschlagenen unter ihren Gotzen liegen werden um ihre Altare her, oben auf alien Hügeln und oben auf alien Bergen und unter alien grünen Baumen und unter alien dicken Eichen, an welchen Orten sie allerlei Gotzen süßes Rauchopfer taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Ich will meine Hand wider sie ausstrecken und das Land wüste und ode machen, von der Wüste an bis gen Diblath, wo sie wohnen, und sollen erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Du Menschenkind, so spricht der Herr HERR vom Lande Israel: Das Ende kommt, das Ende über alle vier Orter des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nun kommt das Ende über dich; denn ich will meinen Grimm über dich senden und will dich richten, wie du verdienet hast, und will dir geben, was alien deinen Greueln gebührt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Mein Auge soil dein nicht schonen, noch übersehen, sondern ich will dir geben, wie du verdienet hast und deine Greuel soilen unter dich kommen, daß ihr erfahren sollt, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So spricht der Herr HERR: Siehe, es kommt ein Unglück fiber das andere!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Das Ende kommt, es kommt das Ende, es ist erwacht über dich; siehe, es kommt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Es gehet schon auf und bricht daher über dich, du Einwohner des Landes; die Zeit kommt, der Tag des Jammers ist nahe, da kein Singen auf den Bergen sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nun will ich bald meinen Grimm fiber dich schütten und meinen Zorn an dir vollenden; und will dich richten, wie du verdienet hast, und dir geben, was deinen Greueln alien gebührt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Mein Auge soil dein nicht schonen und will nicht gnadig sein, sondern ich will dir geben, wie du verdienet hast, und deine Greuel sollen unter dich kommen, dad ihr erfahren sollt, ich sei der HERR, der euch schlagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Siehe, der Tag, siehe, er kommt daher, erbricht an! Die Rute bluhet, und der Stolze grünet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Der Tyrann hat sich aufgemacht zur Rute uber die Gottlosen, dad nichts von ihnen, noch von ihrem Volk, noch von ihrem Haufen Trost haben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Darum kommt die Zeit, der Tag nahet herzu. Der Kaufer freue sich nicht, und der Verkaufer traure nicht; denn es kommt der Zorn uber all ihren Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Darum soil der Verkaufer zu seinem verkauften Gut nicht wieder trachten; denn wer da lebet, der wird\'s haben. Denn die Weissagung uber all ihren Haufen wird nicht zuruckkehren; keinerwird sein Leben erhalten urn seiner Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Ladt sie die Posaune nur blasen und alles zurusten! Es wird doch niemand in den Krieg ziehen; denn mein Grimm gehet uber all ihren Haufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Auf den Gassen gehet das Schwert, in den Hausern gehet Pestilenz und Hunger. Wer auf dem Felde ist, der wird vom Schwert sterben; wer aber in der Stadt ist, den wird die Pestilenz und Hunger fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Und welche unter ihnen entrinnen, die müssen auf den Gebirgen sein und wie die Tauben in Grunden, die alle untereinander girren, ein jeglicher urn seiner Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Aller Hande werden dahinsinken und aller Kniee werden so ungewift stehen wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Und werden Sacke urn sich gürten und mit Furcht uberschuttet sein, und aller Angesicht jammerlich sehen, und aller Haupter werden kahl sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Sie werden ihr Silber hinauf auf die Gassen werfen und ihr Gold als einen Unflat achten; denn ihr Silber und Gold wird sie nicht erretten am Tage des Zorns des HERRN. Und werden doch ihre Seele davon nicht sattigen noch ihren Bauch davon fullen; denn es ist ihnen gewesen ein Argernis zu ihrer Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Sie haben aus ihren edlen Kleinoden, damit sie Hoffart trieben, Bilder ihrer Greuel und Scheuel gemacht; darum will ich\'s ihnen zum Unflat machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'und will\'s Fremden in die Hande geben, daß sie es rauben, und den Gottlosen auf Erden zur Ausbeute, daß sie es entheiligen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Ich will mein Angesicht davon kehren, daß sie meinen Schatz ja wohl entheiligen; ja, Rauber sollen daruber kommen und es entheiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Mache Ketten; denn das Land istvoll Blutschulden und die Stadt voll Frevels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'So will ich die Argsten unter den Heiden kommen lassen, daß sie sollen ihre Hauser einnehmen, und will der Gewaltigen Hoffart ein Ende machen und ihre Kirchen entheiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Der Ausrotter kommt; da werden sie Frieden suchen, und wird nicht da sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Ein Unfall wird uber den andern kommen, ein Gerucht uber das andere. So werden sie dann ein Gesicht bei den Propheten suchen; aber es wird weder Gesetz bei den Priestern noch Rat bei den Alten mehr sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Der Konig wird betrubt sein, und die Fursten werden traurig gekleidet sein, und die Hande des Volks im Lande werden verzagt sein. Ich will mit ihnen umgehen, wie sie gelebet haben, und will sie richten, wie sie es verdienet haben, daß sie erfahren sollen, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Und es begab sich im sechsten Jahr, am funften Tage des sechsten Monden, daß ich saft in meinem Hause, und die Alten aus Juda saften vor mir; daselbst fiel die Hand des Herrn HERRN auf mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Und siehe, ich sah, daß von seinen Lenden herunterwarts war gleich wie Feuer; aber oben uber seinen Lenden war es lichthelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Und reckte aus gleichwie eine Hand und ergriff mich bei dem Haar meines Haupts. Da fuhrete mich ein Wind zwischen Himmel und Erde und brachte mich gen Jerusalem in einem gottlichen Gesichte zu dem innern Tor, das gegen Mitternacht stehet, da denn saft ein Bild zu Verdrieft dem Hausherm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Und siehe, da war die Herrlichkeit des Gottes Israels, wie ich sie zuvor gesehen hatte im Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Und er sprach zu mir: Du Menschenkind, hebe deine Augen auf gegen Mitternacht! Und da ich meine Augen aufhub gegen Mitternacht, siehe, da saft gegen Mitternacht das verdrieftliche Bild am Tor des Altars, eben da man hineingehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Und er sprach zu mir: Du Menschenkind, siehest du auch, was diese tun, namlich grofte Greuel, die das Haus Israel hie tut, daß sie mich ja feme von meinem Heiligtum treiben? Aber du wirst noch mehr groftere Greuel sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Und er fuhrete mich zur Tur des Vorhofs; da sah ich, und siehe, da war ein Loch in der Wand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Und er sprach zu mir: Du Menschenkind, grabe durch die Wand! Und da ich durch die Wand grub, siehe, da war eine Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Und er sprach zu mir: Gehe hinein und schaue die bosen Greuel, die sie allhie tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Und da ich hineinkam und sah, siehe, da waren allerlei Bildnisse der Würmer und Tiere, eitel Scheuel und allerlei Gotzen des Hauses Israel, allenthalben umher an der Wand gemacht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'vor welchen stunden siebenzig Manner aus den Altesten des Hauses Israel; und Jasanja, der Sohn Saphans, stund auch unter ihnen; und ein jeglicher hatte sein Rauchwerk in der Hand. Und ging ein dicker Nebel auf vom Rauchwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Und er sprach zu mir: Menschenkind, siehest du, was die Altesten des Hauses Israel tun in der Finsternis, ein jeglicher in seiner schonsten Kammer? Denn sie sagen: Der HERR siehet uns nicht, sondern der HERR hat das Land verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Und ersprach zu mir: Du sollst noch mehr großere Greuel sehen, die sie tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Und erfuhrete mich hinein zum Tor an des HERRN Hause, das gegen Mitternacht stehet; und siehe, daselbst saften Weiber, die weineten uber den Thamus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Und er sprach zu mir: Menschenkind, siehest du das? Aber du sollst noch groliere Greuel sehen, denn diese sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Und erfuhrete mich in den innern Hof am Hause des HERRN; und siehe, vor der Tur am Tempel des HERRN, zwischen der Halle und dem Altar, da waren bei funfundzwanzig Manner, die ihren Rücken gegen den Tempel des HERRN und ihr Angesicht gegen den Morgen gekehret hatten, und beteten gegen der Sonnen Aufgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Und ersprach zu mir: Menschenkind, siehest du das? Ist\'s dem Hause Juda zu wenig, daß sie alle solche Greuel hie tun? so sie doch sonst im ganzen Lande eitel Gewalt und Unrecht treiben und fahren zu und reizen mich auch; und siehe, sie halten die Weinreben an die Nasen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Darum will ich auch wider sie mit Grimm handeln, und mein Auge soil ihrer nicht verschonen, und will nicht gnadig sein. Und wenn sie gleich mit lauter Stimme vor meinen Ohren schreien, will ich sie doch nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Und er rief mit lauter Stimme vor meinen Ohren und sprach: Lafit herzukommen die Heimsuchung der Stadt, und ein jeglicher habe eine mordliche Waffe in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Und siehe, es kamen sechs Manner auf dem Wege vom Obertor her, das gegen Mitternacht stehet, und ein jeglicher hatte eine schadliche Waffe in seiner Hand. Aber es war einer unter ihnen, der hatte Leinwand an und ein Schreibzeug an seiner Seite. Und sie gingen hinein und traten neben den ehernen Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Und die Herrlichkeit des Gottes Israels erhub sich von dem Cherub, uber dem sie war, zu der Schwelle am Hause und rief dem, der die Leinwand anhatte und das Schreibzeug an seiner Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Und der HERR sprach zu ihm: Gehe durch die Stadt Jerusalem und zeichne mit einem Zeichen an die Stirn die Leute, so da seufzen und jammern uber alle Greuel, so drinnen geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Zu jenen aber sprach er, daß ich\'s horete: Gehet diesem nach durch die Stadt und schlaget drein; eure Augen sollen nicht schonen noch ubersehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Erwurget beide, Alte, Junglinge, Jungfrauen, Kinder und Weiber, alles tot; aber die das Zeichen an sich haben, derer sollt ihr keinen anruhren. Fanget aber an an meinem Heiligtum! Und sie fingen an an den alten Leuten, so vor dem Hause waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Und er sprach zu ihnen: Verunreiniget das Haus und machet die Vorhofe voll toter Leichname; gehet heraus! Und sie gingen heraus und schlugen in der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Und da sie ausgeschlagen hatten, war ich noch übrig. Und ich fiel auf mein Angesicht, schrie und sprach: Ach, Herr HERR, willst du denn alle Ubrigen in Israel verderben, daß du deinen Zorn so ausschuttest uber Jerusalem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Und er sprach zu mir: Es ist die Missetat des Hauses Israel und Juda allzusehr graft; es ist eitel Gewalt im Lande und Unrecht in der Stadt. Denn sie sprechen: Der HERR hat das Land verlassen und der HERR siehet uns nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Darum soil mein Auge auch nicht schonen, will auch nicht gnadig sein, sondern ich will ihr Tun auf ihren Kopfwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Und siehe, der Mann, der die Leinwand anhatte und das Schreibzeug an seiner Seite, antwortete und sprach: Ich habe getan, wie du mirgeboten hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Und ich sah, und siehe, am Himmel uber dem Haupt der Cherubim war es gestaltet wie ein Saphir, und uber denselbigen war es gleich anzusehen wie ein Thron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Und ersprach zu dem Manne in Leinwand: Gehe hinein zwischen die Rader unter den Cherub und fasse die Hande voll glühender Kohlen, so zwischen den Cherubim sind, und streue sie uber die Stadt. Und erging hinein, daß ich\'s sah, da derselbige hineinging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Die Cherubim aber stunden zur Rechten am Hause, und der Vorhof ward inwendig voll Nebels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Und die Herrlichkeit des HERRN erhub sich von dem Cherub zur Schwelle am Hause; und das Haus ward voll Nebels und der Vorhof voll Glanzes von der Herrlichkeit des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Und man horete die Flugel der Cherubim rauschen bis heraus vor den Vorhof, wie eine Stimme des allmachtigen Gottes, wenn er redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Und da erdem Manne in Leinwand geboten hatte und gesagt: Nimm Feuer zwischen den Radern unter den Cherubim, ging derselbige hinein und trat neben das Rad.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Und der Cherub streckte seine Hand heraus zwischen den Cherubim zum Feuer, das zwischen den Cherubim war, nahm davon und gab\'s dem Manne in Leinwand in die Hande; der empfing\'s und ging hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Und erschien an den Cherubim gleichwie eines Menschen Hand unter ihren Flugeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Und ich sah, und siehe, vier Rader stunden bei den Cherubim, bei einem jeglichen Cherub ein Rad; und die Rader waren anzusehen gleichwie ein Turkis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Und waren alle vier eins wie das andere, als ware ein Rad im andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Wenn sie gehen sollten, so konnten sie in alle ihre vier Orter gehen und durften sich nicht herumlenken, wenn sie gingen, sondern wohin das erste ging, da gingen sie hinnach, und durften sich nicht herumlenken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'samt ihrem ganzen Leibe, Rücken, Handen und Flugeln. Und die Rader waren voll Augen um und um an alien vier Radern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Und es rief zu den Radern: Galgal! daß ich\'s horete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Ein jegliches hatte vier Angesichte. Das erste Angesicht war ein Cherub, das andere ein Mensch, das dritte ein Lowe, das vierte ein Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Und die Cherubim schwebten empor. Es ist eben das Tier, das ich sah am Wasser Chebar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Wenn die Cherubim gingen, so gingen die Rader auch neben ihnen; und wenn die Cherubim ihre Flugel schwangen, daß sie sich von der Erde erhuben, so lenkten sich die Rader auch nicht von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Wenn jene stunden, so stunden diese auch; erhuben sie sich, so erhuben sich diese auch: denn es war ein lebendiger Wind in ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Und die Herrlichkeit des HERRN ging wieder aus von der Schwelle am Flause und stellete sich uber die Cherubim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Da schwangen die Cherubim ihre Flugel und erhuben sich von der Erde vor meinen Augen; und da sie ausgingen, gingen die Rader neben ihnen. Und sie traten in das Tor am Hause des HERRN gegen Morgen, und die Herrlichkeit des Gottes Israels war oben uber ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Das ist das Tier, das ich unter dem Gott Israels sah am Wasser Chebar, und merkte, daß es Cherubim waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'da ein jegliches vier Angesichte hatte und vier Flugel und unter den Flugeln gleichwie Menschenhande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Es waren ihre Angesichte gestaltet, wie ich sie am Wasser Chebar sah, und gingen stracks vor sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Und mich hub ein Wind auf und brachte mich zum Tor am Hause des HERRN, das gegen Morgen stehet; und siehe, unter dem Tor waren funfundzwanzig Manner. Und ich sah unter ihnen Jasanja, den Sohn Assurs, und Platja, den Sohn Benajas, die Fursten im Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Und er sprach zu mir: Menschenkind diese Leute haben unselige Gedanken und schadliche Ratschlage in dieser Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Denn sie sprechen: Es ist nicht so nahe, lafttuns nur Hauser bauen; sie ist der Topf, so sind wir das Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Darum sollst du, Menschenkind, wider sie weissagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Und der Geist des HERRN fiel auf mich und sprach zu mir: Sprich: So sagt der HERR: Ihr habt also geredet, ihrvom Hause Israel; und eures Geistes Gedanken kenne ich wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Ihr habt viele erschlagen in dieser Stadt, und ihre Gassen liegen voller Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Darum spricht der Herr HERR also: Die ihr drinnen getotet habt, die sind das Fleisch, und sie ist der Topf; aber ihr müsset hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Das Schwert, das ihr furchtet, das will ich uber euch kommen lassen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Ich will euch von dannen herausstoften und den Fremden in die Hand geben und will euch euer Recht tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Ihr sollt durchs Schwert fallen, in den Grenzen Israels will ich euch richten; und sollt erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Die Stadt aber soil nicht euer Topf sein, noch ihr das Fleisch drinnen, sondern in den Grenzen Israels will ich euch richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Und sollt erfahren, daß ich der HERR bin; denn ihr habt nach meinen Geboten nicht gewandelt und meine Rechte nicht gehalten, sondern getan nach der Heiden Weise, die um euch her sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Und da ich soweissagte, starb Platja, der Sohn Benajas. Da fiel ich auf mein Angesicht und schrie mit lauter Stimme und sprach: Ach, Herr HERR, du wirst\'s mit den Ubrigen Israels gar ausmachen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Du Menschenkind, deine Bruderund nahen Freunde und das ganze Haus Israel, so noch zu Jerusalem wohnen, sprechen wohl untereinander; jene sind vom HERRN feme weggeflohen, aber wir haben das Land inne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Darum sprich du: So spricht der Herr HERR: Ja, ich habe sie feme weg unter die Heiden lassen treiben und in die Lander zerstreuet; doch will ich bald ihr Heiland sein in den Landern, dahin sie kommen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Darum sprich: So sagt der Herr HERR: Ich will euch sammeln aus den Volkern und will euch sammeln aus den Landern, dahin ihr zerstreuet seid, und will euch das Land Israel geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Da sollen sie kommen und alle Scheuel und Greuel darauswegtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Ich will euch ein eintrachtig Herz geben und einen neuen Geist in euch geben; und will das steinerne Herz wegnehmen aus eurem Leibe und ein fleischern Herz geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'auf daß sie in meinen Sitten wandeln und meine Rechte halten und danach tun. Und sie sollen mein Volk sein, so will ich ihr Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Denen aber, so nach ihres Herzens Scheueln und Greueln wandeln, will ich ihr Tun auf ihren Kopf werfen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Da schwangen die Cherubim ihre Flugel, und die Rader gingen neben ihnen, und die Herrlichkeit des Gottes Israels war oben uber ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Und die Herrlichkeit des HERRN erhub sich aus der Stadt und stellete sich auf den Berg, der gegen Morgen vor der Stadt liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Und ein Wind hub mich auf und brachte mich im Gesicht und im Geist Gottes nach Chaldaa zu den Gefangenen. Und das Gesicht, so ich gesehen hatte, verschwand vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Und ich sagte den Gefangenen alle Worte des HERRN, die er mir gezeiget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Du Menschenkind, du wohnest unter einem ungehorsamen Hause, welches hatwohl Augen, daß sie sehen konnten, und wollen nichtsehen, Ohren, dafi sie horen konnten, und wollen nicht horen, sondern es ist ein ungehorsam Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Darum, du Menschenkind, nimm dein Wandergerat und zeuch am lichten Tage davon vor ihren Augen. Von deinem Ort sollst du ziehen an einen andern Ort vor ihren Augen, ob sie vielleicht merken wollten, daß sie ein ungehorsam Haus sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Und sollst dein Gerat heraustun, wie Wandergerat, bei lichtem Tage vor ihren Augen; und du sollst ausziehen des Abends vor ihren Augen, gleichwie man auszieht, wenn man wandern will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Und du sollst durch die Wand brechen vor ihren Augen und daselbst durch ausziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Und du sollst es auf deine Schulter nehmen vor ihren Augen und wenn es dunkel worden ist, heraustragen; dein Angesicht sollst du verhullen, daß du das Land nicht sehest. Denn ich habe dich dem Hause Israel zum Wunderzeichen gesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Und ich tat, wie mir befohlen war, und trug mein Gerat heraus, wie Wandergerat, bei lichtem Tage; und am Abend brach ich mit der Hand durch die Wand; und da es dunkel worden war, nahm ich\'s auf die Schulter und trug\'s heraus vor ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Und frühmorgens geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Menschenkind, hat das Haus Israel, das ungehorsame Haus, nicht zu dir gesagt: Was machst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'So sprich zu ihnen: So spricht der Herr HERR: Diese Last betrifft den Fursten zu Jerusalem und das ganze Haus Israel, das drinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sprich: Ich bin euer Wunderzeichen; wie ich getan habe, also soli euch geschehen, daß ihr wandern musset und gefangen geführetwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Ihr Furst wird auf der Schulter tragen im Dunkel und muft ausziehen durch die Wand, so sie brechen werden, dafi sie dadurch ausziehen; sein Angesicht wird verhullet werden, daß er mit keinem Auge das Land sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Ich will auch mein Netz uber ihn werfen, daß er in meiner Jagd gefangen werde, und will ihn gen Babel bringen, in der Chaldaer Land, das er doch nicht sehen wird, und soil daselbst sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Und alle, die urn ihn her sind, seine Gehilfen und all seinen Anhang will ich unter alle Winde zerstreuen und das Schwert hinter ihnen her ausziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Also sollen sie erfahren, daß ich der HERR sei, wenn ich sie unter die Heiden verstofte und in die Lander zerstreue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Aber ich will ihrer etliche wenige uberbleiben lassen vor dem Schwert, Hunger und Pestilenz; die sollen jener Greuel erzahlen unter den Heiden, dahin sie kommen werden, und sollen erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Du Menschenkind, du sollst dein Brotessen mit Beben und dein Wasser trinken mit Zittern und Sorgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Und sprich zum Volk im Lande: So spricht der Herr HERR von den Einwohnern zu Jerusalem im Lande Israel: Sie müssen ihr Brot essen in Sorgen und ihr Wasser trinken im Elend; denn das Land soil wust werden von allem, das drinnen ist, urn des Frevels willen aller Einwohner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Und die Stadte, so wohl bewohnet sind, sollen verwustet und das Land ode werden. Also sollt ihr erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Du Menschenkind, was habt ihr fur ein Sprichwort im Lande Israel und sprechet: Weil sich\'s so lange verzeucht, so wird nun fort nichts aus der Weissagung?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Darum sprich zu ihnen: So spricht der Herr HERR: Ich will das Sprichwort aufheben, daß man es nicht mehrfuhren soil in Israel. Und rede zu ihnen: Die Zeit ist nahe und alles, was geweissaget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Denn ihr sollt nun fort inne werden, daß kein Gesicht fehlen und keine Weissagung lugen wird wider das Haus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Denn ich bin der HERR; was ich rede, das soil geschehen und nicht langer verzogen werden, sondern bei eurer Zeit, ihr ungehorsames Haus, will ich tun, was ich rede, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Du Menschenkind, siehe, das Haus Israel spricht: Das Gesicht, das dieser siehet, da ist noch lange hin, und weissaget auf die Zeit, so noch feme ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Darum sprich zu ihnen: So spricht der Herr HERR: Was ich rede, soli nicht langer verzogen werden, sondern soil geschehen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Du Menschenkind, weissage wider die Propheten Israels und sprich zu denen, so aus ihrem eigenen Herzen weissagen: Horet des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'So spricht der Herr HERR: Wehe den tollen Propheten, die ihrem eigenen Geist folgen und haben doch nicht Gesichte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'O Israel, deine Propheten sind wie die Füchse in den Wfisten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Sie treten nicht vor die Lücken und machen sich nicht zur Hürde um das Haus Israel und stehen nicht im Streit am Tage des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ihr Gesicht ist nichts, und ihr Weissagen ist eitel Lügen. Sie sprechen: Der HERR hat\'s gesagt, so sie doch der HERR nicht gesandt hat, und mühen sich, daß sie ihre Dinge erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Ist\'s nicht also, daß euer Gesicht ist nichts, und euer Weissagen ist eitel Lügen? Und sprechet doch: Der HERR hat\'s geredet, so ich\'s doch nicht geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Darum spricht der Herr HERR also: Weil ihr das prediget, da nichts aus wird, und Lügen weissaget, so will ich an euch, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Und meine Hand soil kommen fiber die Propheten, so das predigen, da nichts aus wird, und Lügen weissagen. Sie sollen in der Versammlung meines Volks nicht sein und in die Zahl des Hauses Israel nicht geschrieben werden noch ins Land Israel kommen; und ihr sollt erfahren, daß ich der Herr HERR bin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'darum daß sie mein Volk verffihren und sagen: Friede! so doch kein Friede ist. Das Volk bauet die Wand, so tünchen sie dieselbe mit losem Kalk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Sprich zu den Tünchern, die mit losem Kalk tünchen, daß es abfallen wird; denn es wird ein Platzregen kommen, und werden grofte Hagel fallen, die es fallen, und ein Windwirbel wird es zerreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Siehe, so wird die Wand einfallen. Was gilt\'s, dann wird man zu euch sagen: Wo ist nun, das Getfinchte, das ihr getüncht habt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'So spricht der Herr HERR: Ich will einen Windwirbel reiften lassen in meinem Grimm und einen Platzregen in meinem Zorn und grofte Hagelsteine im Grimm, die sollen es alles umstoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Also will ich die Wand umwerfen, die ihr mit losem Kalk getüncht habt, und will sie zu Boden stoften, daß man ihren Grund sehen soil, daß sie da liege; und ihr sollt drinnen auch umkommen und erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Also will ich meinen Grimm vollenden an der Wand und an denen, die sie mit losem Kalk tünchen und zu euch sagen: Hie ist weder Wand noch Tüncher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Das sind die Propheten Israels, die Jerusalem weissagen und predigen von Friede, so doch kein Friede ist, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Und, du Menschenkind, richte dein Angesicht wider die Tochter in deinem Volk, welche weissagen aus ihrem Herzen, und weissage wider sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'und sprich: So spricht der Herr HERR: Wehe euch, die ihr Kissen machet den Leuten unter die Arme und Pfühle zu den Haupten, beide, Jungen und Alten, die Seelen zu fahen! Wenn ihr nun die Seelen gefangen habt unter meinem Volk, verheiftet ihr denselbigen das Leben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'und entheiliget mich in meinem Volk um einer Hand voll Gerste und Bissen Brots willen, damit daß ihr die Seelen zum Tode verurteilet, die doch nicht sollten sterben, und urteilet die zum Leben; die doch nicht leben sollten, durch eure Lügen unter meinem Volk, welches gerne Lfigen horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Darum spricht der Herr HERR: Siehe, ich will an eure Kissen, damit ihr die Seelen fahet und vertrostet, und will sie von euren Armen wegreiften und die Seelen, so ihr fahet und vertrostet, losmachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Und will eure Pffihle zerreiften und mein Volk aus eurer Hand erretten, daß ihr sie nicht mehr fahen sollt; und sollt erfahren, daß ich der HERR sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'darum daß ihr das Herz der Gerechten falschlich betrfibet, die ich nicht betrfibet habe, und habt gestarket die Hande der Gottlosen, daß sie sich von ihrem bosen Wesen nicht bekehren, damit sie lebendig mochten bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Darum sollt ihr nicht mehr unnfitze Lehre predigen noch weissagen, sondern ich will mein Volk aus euren Handen erretten, und ihr sollt erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Und es kamen etliche von den Altesten Israels zu mir und setzten sich vor mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Menschenkind, diese Leute hangen mit ihrem Herzen an ihren Gotzen und halten ob dem Argernis ihrer Missetat. Sollt ich denn ihnen antworten, wenn sie mich fragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Darum rede mit ihnen und sage zu ihnen: So spricht der Herr HERR: Welcher Mensch vom Hause Israel mit dem Herzen an seinen Gotzen hanget und halt ob dem Argernis seiner Missetat und kommt zum Propheten, so will ich, der HERR, demselbigen antworten, wie er verdienet hat mit seiner groften Abgotterei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'auf daß das Haus Israel betrogen werde in ihrem Herzen, darum daß sie alle von mir gewichen sind durch Abgotterei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Darum sollstdu zum Hause Israel sagen: So spricht der Herr HERR: Kehret und wendet euch von eurer Abgotterei und wendet euer Angesicht von alien euren Greueln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Denn welcher Mensch vom Hause Israel Oder Fremdling, so in Israel wohnet, von mirweichet und mit seinem Herzen an seinen Gotzen hanget und ob dem Argernis seiner Abgotterei halt und zum Propheten kommt, da(3> er durch ihn mich frage, dem will ich, der HERR, selbst antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Und will mein Angesicht wider denselbigen setzen, daß sie sollen wust und zum Zeichen und Sprichwort werden; und will sie aus meinem Volk rotten, daü ihr erfahren sollt, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Wo aber ein betrogener Prophet etwas redet, den will ich, der HERR, wiederum lassen betrogen werden und will meine Hand uber ihn ausstrecken und ihn aus meinem Volk Israel rotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Also sollen sie beide ihre Missetat tragen; wie die Missetat des Fragers, also soil auch sein die Missetat des Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'auf daß sie nicht mehr das Haus Israel verfuhren von mir und sich nicht mehr verunreinigen in allerlei ihrer Ubertretung, sondern sie sollen mein Volk sein, und ich will ihr Gott sein, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Du Menschenkind, wenn ein Land an mir sundiget und dazu mich verschmahet, so will ich meine Hand uber dasselbe ausstrecken und den Vorrat des Brots wegnehmen und will Teurung hineinschicken, daü ich beide, Menschen und Vieh, drinnen ausrotte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Und wenn dann gleich die drei Manner, Noah, Daniel und Hiob, drinnen waren, so würden sie allein ihre eigene Seeie erretten durch ihre Gerechtigkeit, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Und wenn ich bose Tiere in das Land bringen wurde, die die Leute aufraumeten und dasselbige verwusteten, daß niemand drinnen wandeln konnte vorden Tieren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'und diese drei Manner waren auch drinnen: so wahr ich lebe, spricht der Herr HERR, sie wurden weder Sohne noch Tochter erretten, sondern allein sich selbst, und das Land müftte ode werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Oder wo ich das Schwert kommen liefie uber das Land und sprache: Schwert, fahre durchs Land und wurde also beide, Menschen und Vieh, ausrotten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'und die drei Manner waren drinnen: so wahr ich lebe, spricht der Herr HERR, sie wurden weder Sohne noch Tochter erretten, sondern sie allein wurden errettet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Oder so ich Pestilenz in das Land schicken und meinen Grimm uber dasselbige ausschütten wurde und Blut sturzen, also daß ich beide, Menschen und Vieh, ausrottete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'und Noah, Daniel und Hiob waren drinnen: so wahr ich lebe, spricht der Herr HERR, wurden sie weder Sohne noch Tochter, sondern allein ihre eigene Seeie durch ihre Gerechtigkeit erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Denn so spricht der Herr HERR: So ich meine vier bosen Strafen, als Schwert, Hunger, bose Tiere und Pestilenz, uber Jerusalem schicken wurde, daß ich drinnen ausrottete beide, Menschen und Vieh,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'siehe, so sollen etliche Ubrige drinnen davonkommen, die Sohne und Tochter herausbringen werden, und zu euch anherkommen, daß ihr sehen werdet, wie es ihnen gehet, und euch trosten uber dem Ungluck, das ich uber Jerusalem habe kommen lassen, samt allem andern, das ich uber sie habe kommen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Sie werden euer Trost sein, wenn ihr sehen werdet, wie es ihnen gehet, und werdet erfahren, daß ich nicht ohne Ursache getan habe, was ich drinnen getan habe, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Du Menschenkind, was ist das Holz vom Weinstock vor anderm Holz Oder eine Rebe vor anderm Holz im Walde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Nimmt man es auch und macht etwas daraus? Oder macht man auch einen Nagel daraus, daran man etwas moge hangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Siehe, man wirft es ins Feuer, daß es verzehret wird, daß seine beiden Orte das Feuer verzehret und sein Mittelstes verbrennet. Wozu sollt es nun taugen? Taugt es denn auch zu etwas?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Siehe, da es noch ganz war, konnte man nichts daraus machen; wieviel weniger kann nun fort mehr etwas daraus gemacht werden, so es das Feuer verzehret und verbrannt hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Darum spricht der Herr HERR: Gleichwie ich das Holz vom Weinstock vor anderm Holz im Walde dem Feuer zu verzehren gebe, also will ich mit den Einwohnern zu Jerusalem auch umgehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'und will mein Angesicht wider sie setzen, daß sie dem Feuer nicht entgehen sollen, sondern das Feuer soil sie fressen. Und ihr sollt es erfahren, daß ich der HERR bin, wenn ich mein Angesicht wider sie setze');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'und das Land wuste mache, darum daß sie mich verschmahen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Du Menschenkind, offenbare der Stadt Jerusalem ihre Greuel und sprich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'So spricht der Herr HERR zu Jerusalem: Dein Geschlecht und deine Geburt ist aus der Kanaaniter Lande, dein Vater aus den Amoritern und deine Mutter aus den Hethitern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Deine Geburt ist also gewesen: Dein Nabel, da du geboren wurdest, ist nicht verschnitten; so hat man dich auch mit Wasser nicht gebadet, daß du sauber wurdest, noch mit Salz gerieben, noch in Windeln gewickelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Denn niemand jammerte dein, dafi er sich uber dich hatte erbarmet und der Stücke eins dir erzeiget, sondern du wurdest aufs Feld geworfen. Also verachtet war deine Seeie, da du geboren warest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Ich aber ging vor dir über und sah dich in deinem Blut liegen und sprach zu dir, da du so in deinem Blut lagest: Du sollst leben! Ja, zu dir sprach ich, da du so in deinem Blut lagest: Du sollst leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Und habe dich erzogen und lassen groß werden wie ein Gewachs auf dem Felde; und warest nun gewachsen und groß und schon worden. Deine Bruste waren gewachsen und hattest schon lange Haare gekriegt; aber du warest noch bloß und beschamet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Und ich ging vor dir uber und sah dich an; und siehe, es war die Zeit, urn dich zu werben. Da breitete ich meinen Geren uber dich und bedeckte deine Scham. Und ich gelobte dir\'s und begab mich mit dir in einen Bund, spricht der Herr HERR, daß du solltest mein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Und ich badete dich mit Wasser und wusch dich von deinem Blut und salbete dich mit Balsam');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'und kleidete dich mit gestickten Kleidern und zog dir samische Schuhe an; ich gab dir feine leinene Kleider und seidene Schleier');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'und zierte dich mit Kleinoden und legte Geschmeide an deine Arme und Kettlein an deinen Hals');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'und gab dir Haarband an deine Stirn und Ohrringe an deine Ohren und eine schone Krone auf dein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Summa, du warest geziert miteitel Gold und Silber und gekleidet miteitel Leinwand, Seiden und Gesticktem. Du aßest auch eitel Semmel, Honig und 01 und warest uberaus schon und bekamest das Konigreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Und dein Ruhm erscholl unterdie Heiden deiner Schone halben, welche ganz vollkommen war durch den Schmuck, so ich an dich gehanget hatte, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Aber du verließest dich auf deine Schone; und weil du so geruhmet warest, triebest du Hurerei, also daß du dich einem jeglichen, wer voruberging, gemein machtest und tatest seinen Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Und nahmest von deinen Kleidern und machtest dir bunte Altare daraus und triebest deine Hurerei darauf, als nie geschehen ist noch geschehen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Du nahmest auch dein schon Gerat, das ich dir von meinem Gold und Silber gegeben hatte, und machtest dir Mannsbilder daraus und triebest deine Hurerei mit denselben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Und nahmest deine gestickten Kleider und bedecktest sie damit; und mein 01 und Rauchwerk legtest du ihnen vor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Meine Speise, die ich dirzu essen gab, Semmel, 01, Honig, legtest du ihnen vorzum sußen Geruch. Ja, es kam dahin, spricht der Herr HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'daß du nahmest deine Sohne und Tochter, die du mir gezeuget hattest, und opfertest sie denselben zu fressen. Meinest du denn, daß ein Geringes sei urn deine Hurerei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'daß du mir meine Kinder schlachtest und lassest sie denselben verbrennen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Noch hast du in alien deinen Greueln und Hurerei nie gedacht an die Zeit deiner Jugend, wie bloß und nackend du warest und in deinem Blut lagest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Uber alle diese deine Bosheit (ach, wehe, wehe dir!), spricht der Herr HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'bauetest du dir Bergkirchen und machtest dir Bergaltare auf alien Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Und vornean auf alien Straßen bauetest du deine Bergaltare und machtest deine Schone zu eitel Greuel. Du gretetest mit deinen Beinen gegen alle, so vorubergingen, und triebest große Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Erstlich triebest du Hurerei mit den Kindern Agyptens, deinen Nachbarn, die groß Fleisch hatten, und triebest große Hurerei, mich zu reizen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Ich aber streckte meine Hand aus wider dich und steuerte solcher deiner Weise und ubergab dich in den Willen deiner Feinde, den Tochtern der Philister, welche sich schamten vor deinem verruchten Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Danach triebest du Hurerei mit den Kindern Assur und konntest des nicht satt werden; ja, da du mit ihnen Hurerei getrieben hattest, und des nicht satt werden konntest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'machtest du der Hurerei noch mehr im Lande Kanaan bis nach Chaldaa; noch konntest du damit auch nicht satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Wie soli ich dirdoch dein Herz beschneiden, spricht der Herr HERR, weil du solche Werke tust einer großen Erzhure,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'damit daß du deine Bergkirchen bauetest vornean auf alien Straßen und deine Altare machtest auf alien Gassen? Dazu warest du nicht wie eine andere Hure, die man muß mit Geld kaufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'noch wie die Ehebrecherin, die anstatt ihres Mannes andere zulaßt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Denn alien andern Huren gibt man Geld; du aber gibst alien deinen Buhlern Geld zu und schenkest ihnen, daß sie zu dir kommen allenthalben und mit dir Hurerei treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Und findet sich an dir das Widerspiel vor andern Weibern mit deiner Hurerei, weil man dir nicht nachlauft, sondern du Geld zugibst und man dir nicht Geld zugibt. Also treibest du das Widerspiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Darum, du Hure, hore des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So spricht der Herr HERR: Weil du denn so milde Geld zugibst und deine Scham durch deine Hurerei gegen deine Buhlen entbloßest und gegen alie Gotzen deiner Greuel und vergeußest das Blut deiner Kinder, welche du ihnen opferst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'darum, siehe, will ich sammeln alle deine Buhlen, mit welchen du Wollust getrieben hast, samt alien, die du fur Freunde hieltest, zu deinen Feinden; und will sie beide wider dich sammeln allenthalben und will ihnen deine Scham bloßen, daß sie deine Scham garsehen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Und will das Recht der Ehebrecherinnen und Blutvergießerinnen uber dich gehen lassen und will dein Blut sturzen mit Grimm und Eifer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Und will dich in ihre Hande geben, daß sie deine Bergkirchen abbrechen und deine Bergaltare umreilien und dir deine Kleider ausziehen und dein schon Gerat dir nehmen und dich nackend und bloli sitzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Und sollen Haufen Leute über dich bringen, die dich steinigen und mit ihren Schwertern zerhauen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'und deine Hauser mit Feuer verbrennen und dir dein Recht tun vor den Augen vieler Weiber. Also will ich deiner Hurerei ein Ende machen, daß du nicht mehr sollst Geld noch zugeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Und will meinen Mut an dir kuhlen und meinen Eifer an dir sattigen, daß ich ruhe und nicht mehr zurnen durfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Darum dafi du nicht gedacht hast an die Zeit deiner Jugend, sondern mich mit diesem allem gereizet, darum will ich auch dir all dein Tun auf den Kopf legen, spricht der Herr HERR; wiewohl ich damit nicht getan habe nach dem Laster in deinen Greueln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Siehe, alle die, so Sprichwort pflegen zu uben, werden von dir dies Sprichwort sagen: Die Tochter ist wie die Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Du bist deiner Mutter Tochter, welche ihren Mann und Kinder verstofit, und bist eine Schwester deiner Schwestern, die ihre Manner und Kinder verstolien. Eure Mutter ist eine von den Hethitern und euer Vater ein Amoriter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Samaria ist deine grotie Schwester mit ihren Tochtern, die dirzur Linken wohnet, und Sodom ist deine kleine Schwester mit ihren Tochtern, die zu deiner Rechten wohnet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'wiewohl du dennoch nicht gelebet hast nach ihrem Wesen noch getan nach ihren Greueln. Es fehlet nicht weit, daß du es arger gemacht hast denn sie in all deinem Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'So wahr ich lebe, spricht der Herr HERR, Sodom, deine Schwester, samt ihren Tochtern hat nicht so getan wie du und deine Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Siehe, das war deiner Schwester Sodom Missetat: Hoffart und alles vollauf und guter Friede, den sie und ihre Tochter hatten; aber dem Armen und Durftigen halfen sie nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'sondern waren stolz und taten Greuel vor mir; darum ich sie auch weggetan habe, da ich begann dareinzusehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'So hat auch Samaria nicht die Halfte deiner Sunden getan, sondern du hast deiner Greuel so viel mehr über sie getan, dati du deine Schwester gleich fromm gemacht hast gegen alle deine Greuel, die du getan hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'So trage auch nun deine Schande, die du deine Schwester fromm machst durch deine Sunden, in welchen du grofiere Greuel denn sie getan hast, und machst sie frommer, denn du bist. So sei nun auch du schamrot und trage deine Schande, daß du deine Schwester fromm gemacht hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Ich will aber ihr Gefangnis wenden, namlich das Gefangnis dieser Sodom und ihrer Tochter und das Gefangnis dieser Samaria und ihrer Tochter und die Gefangenen deines jetzigen Gefangnisses samt ihnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'daß du tragen mussest deine Schande und Hohn fur alles, das du getan hast, und dennoch ihr getrostet werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Und deine Schwester, diese Sodom und ihre Tochter sollen bekehret werden, wie sie vor gewesen sind, und Samaria und ihre Tochter sollen bekehret werden, wie sie vor gewesen sind, dazu du auch und deine Tochter sollet bekehret werden, wie ihr vor gewesen seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Und wirst nicht mehr dieselbige Sodom, deine Schwester, rühmen wie zur Zeit deines Hochmuts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'da deine Bosheit noch nicht entdeckt war, als zur Zeit, da dich die Tochter Syriens und die Tochter der Philister allenthalben schandeten und verachteten dich urn und urn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'da ihr mulitet eure Laster und Greuel tragen, spricht der HERR HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Denn also spricht der Herr HERR: Ich will dir tun, wie du getan hast, daß du den Eid verachtest und brichstden Bund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Ich will aber gedenken an meinen Bund, den ich mit dir gemacht habe zur Zeit deiner Jugend, und will mit dir einen ewigen Bund aufrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Da wirst du an deine Wege gedenken und dich schamen, wenn du deine grofien und kleinen Schwestern zu dir nehmen wirst, die ich dirzu Tochtern geben werde, aber nicht aus deinem Bunde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'sondern will meinen Bund mit dir aufrichten, daß du erfahren sollst, daß ich der HERR sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'auf daß du daran gedenkest und dich schamest und vor Schanden nicht mehr deinen Mund auftun durfest, wenn ich dir alles vergeben werde, was du getan hast, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Du Menschenkind, lege dem Hause Israel ein Ratsel vor und ein Gleichnis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'und sprich: So spricht der Herr HERR: Ein grolier Adler mit grolien Flugeln und langen Fittichen und voll Federn, die bunt waren, kam auf Libanon und nahm den Wipfel von der Zeder');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'und brach das oberste Reis ab und führete es ins Kramerland und setzte es in die Kaufmannsstadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Er nahm auch Samen aus demselbigen Lande und saete ihn in dasselbige gute Land, da viel Wassers ist, und setzte es lose hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Und es wuchs und ward ein ausgebreiteter Weinstock und niedriges Stammes; denn seine Reben bogen sich zu ihm, und seine Wurzeln waren unter ihm; und war also ein Weinstock, der Reben kriegte und Zweige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Und da war ein anderer grofier Adler mitgrolien Flugeln und vielen Federn; und siehe, der Weinstock hatte Verlangen an seinen Wurzeln zu diesem Adler und streckte seine Reben aus gegen ihn, daß er gewassert würde vom Platz seiner Pflanzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Und war doch auf einem guten Boden an viel Wasser gepflanzet, daß er wohl hatte konnen Zweige bringen, Frucht tragen und ein herrlicher Weinstock werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'So sprich nun: Also sagt der Herr HERR: Sollte der geraten? Ja, man wird seine Wurzel ausrotten und seine Frucht abreilien, und wird verdorren, daß all seines Gewachses Blatter verdorren werden, und wird nicht geschehen durch grolien Arm noch viel Volks, auf daß man ihn von seinen Wurzeln wegfuhre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Siehe, er ist zwar gepflanzet, abersollter geraten? Ja, sobald ihn der Ostwind ruhren wird, wird er verdorren auf dem Platz seines Gewachses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Und des HERRN Wortgeschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Lieber, sprich zu dem ungehorsamen Hause: Wisset ihr nicht, was das ist? Und sprich: Siehe, es kam der Konig zu Babel gen Jerusalem und nahm ihren Konig und ihre Fursten und fuhrete sie weg zu sich gen Babel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'und nahm von dem koniglichen Samen und machte einen Bund mit ihm und nahm einen Eid von ihm; aberdie Gewaltigen im Lande nahm erweg,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'damitdas Konigreich demutig bliebe und sich nicht erhube, auf daß sein Bund gehalten würde und bestünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Aber derselbe (Same) fiel von ihm ab und sandte seine Botschaft nach Agypten, daß man ihm Rosse und viel Volks schicken sollte. Sollt es dem geraten? Sollt er davonkommen, der solches tut? Und sollte der, so den Bund bricht, davonkommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Sowahrich lebe, sprichtder Herr HERR, an dem Ort des Konigs, der ihn zum Konige gesetzt hat, welches Eid er verachtet, und welches Bund er gebrochen hat, da soil ersterben, namlich zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Auch wird ihm Pharao nicht beistehen im Kriege mit groliem Heer und viel Volks, wenn man die Schutte aufwerfen wird und die Bollwerke bauen, daß viel Leute umgebracht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Denn weil erden Eid verachtet und den Bund gebrochen hat, darauf er seine Hand gegeben hat, und solches alles tut, wird er nicht davonkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Darum sprichtder Herr HERR also: So wahrals ich lebe, so will ich meinen Eid, den er verachtet hat, und meinen Bund, den er gebrochen hat, auf seinen Kopf bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Denn ich will mein Netz uber ihn werfen, und muli in meiner Jagd gefangen werden; und will ihn gen Babel bringen und will daselbst mit ihm rechten uber dem, daß er sich also an mir vergriffen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Und alle seine Fluchtigen, die ihm anhingen, sollen durchs Schwert fallen, und ihre Ubrigen sollen in alle Winde zerstreuet werden, und sollt es erfahren, daß ich\'s, der HERR, geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So spricht der Herr HERR: Ich will auch von dem Wipfel des hohen Zedernbaums nehmen und oben von seinen Zweigen ein zartes Reis brechen und will\'s auf einen hohen gehauften Berg pflanzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'namlich auf den hohen Berg Israel will ich\'s pflanzen, daß es Zweige gewinne und Fruchte bringe und ein herrlicher Zedernbaum werde, also daß allerlei Vogel unter ihm wohnen und allerlei Fliegendes unter dem Schatten seiner Zweige bleiben moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Und sollen alle Feldbaume erfahren, daß ich, der HERR, den hohen Baum geniedriget und den niedrigen Baum erhohet habe und den grünen Baum ausgedorret und den dürren Baum grunend gemacht habe. Ich, der HERR, rede es und tue es auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Was treibet ihr unter euch im Lande Israel dies Sprichwort und sprechet: Die Vater haben Herlinge gegessen, aber den Kindern sind die Zahne davon stumpf worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'So wahr als ich lebe, spricht der Herr HERR, solch Sprichwort soli nicht mehr unter euch gehen in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Denn siehe, alle Seelen sind mein; des Vaters Seele ist sowohl mein als des Sohnes Seele. Welche Seele sundiget, die soil sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Wenn nun einerfromm ist, der recht und wohl tut;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'der auf den Bergen nicht isset; der seine Augen nicht aufhebet zu den Gotzen des Hauses Israel und seines Nachsten Weib nicht befleckt und liegt nicht bei der Frau in ihrer Krankheit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'der niemand beschadiget; der dem Schuldner sein Pfand wiedergibt; der niemand etwas mit Gewalt nimmt; der dem Hungrigen sein Brot mitteilet und den Nackenden kleidet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'der nicht wuchert; der niemand ubersetzet; der seine Hand vom Unrechten kehret; der zwischen den Leuten recht urteilet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'der nach meinen Rechten wandelt und meine Gebote halt, daß er ernstlich danach tue: das ist ein frommer Mann; der soil das Leben haben, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Wenn er aber einen Sohn zeuget, und derselbige wird ein Morder, der Blut vergeulit Oder dieser Stucke eins tut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'und der andern Stucke keins nicht tut, sondern isset auf den Bergen und beflecket seines Nachsten Weib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'beschadiget die Armen und Elenden, mit Gewalt etwas nimmt, das Pfand nicht wiedergibt, seine Augen zu den Gotzen aufhebet, damit er einen Greuel begehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'gibtauf Wucher, ubersetzt: sollte der leben? Er soil nicht leben, sondern weil er solche Greuel alle getan hat, soil er des Todes sterben; sein Blut soil auf ihm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Wo er aber einen Sohn zeuget, der alle solche Sünde siehet, so sein Vater tut, und sich furchtet und nicht also tut:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'isset nicht auf den Bergen, hebet seine Augen nicht auf zu den Gotzen des Hauses Israel, beflecket nicht seines Nachsten Weib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'beschadiget niemand, behalt das Pfand nicht, nicht mit Gewalt etwas nimmt, teilet sein Brot mit dem Hungrigen und kleidet den Nackenden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'der seine Hand vom Unrechten kehret, keinen Wucher noch Ubersatz nimmt, sondern meine Gebote halt und nach meinen Rechten lebet: der soil nicht sterben urn seines Vaters Missetat willen, sondern leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Aber sein Vater, der Gewalt und Unrecht geubet und unter seinem Volk getan hat, das nicht taugt, siehe, derselbige soil sterben urn seiner Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'So sprechet ihr: Warum soil denn ein Sohn nicht tragen seines Vaters Missetat? Darum, daß er recht und wohl getan und alle meine Rechte gehalten und getan hat, soil er leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Denn welche Seele sundiget, die soil sterben. Der Sohn soil nicht tragen die Missetat des Vaters, und der Vater soil nicht tragen die Missetat des Sohnes, sondern des Gerechten Gerechtigkeit soil uber ihm sein, und des Ungerechten Ungerechtigkeit soil fiber ihm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Wo sich aber der Gottlose bekehret von alien seinen Sünden, die er getan hat, und halt alle meine Rechte und tut recht und wohl, so soil er leben und nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Es soli alter seiner Ubertretung, so er begangen hat, nicht gedachtwerden, sondern soil leben urn der Gerechtigkeit willen, die er tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Meinest du, daß ich Gefallen habe am Tode des Gottlosen, sprichtder Herr HERR, und nicht vielmehr, daß er sich bekehre von seinem Wesen und lebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Und wo sich der Gerechte kehret von seiner Gerechtigkeit und tut Boses und lebet nach alien Greueln, die ein Gottloser tut, sollte der leben? Ja, aller seiner Gerechtigkeit, die er getan hat, soil nicht gedacht werden, sondern in seiner Ubertretung und Sünden, die er getan hat, soil er sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Noch sprechet ihr: Der HERR handelt nicht recht. So horet nun, ihr vom Hause Israel: Ist\'s nicht also, daß ich recht habe und ihr unrecht habt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Denn wenn der Gerechte sich kehret von seiner Gerechtigkeit und tut Boses, so muft er sterben; er muft aber urn seiner Bosheit willen, die er getan hat, sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Wiederum, wenn sich der Gottlose kehret von seiner Ungerechtigkeit, die er getan hat, und tut nun recht und wohl, der wird seine Seele lebendig behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Denn weil er siehet und bekehret sich von aller seiner Bosheit, die er getan hat, so soil er leben und nicht sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Noch sprechen die vom Hause Israel: Der HERR handelt nicht recht. Sollt ich unrecht haben? Ihr vom Hause Israel habt unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Darum will ich euch richten, ihr vom Hause Israel, einen jeglichen nach seinem Wesen, spricht der Herr HERR. Darum so bekehret euch von aller eurer Ubertretung, auf daß ihr nicht fallen müsset urn der Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Werfet von euch alle eure Ubertretung, damit ihr ubertreten habt, und machet euch ein neu Herz und neuen Geist. Denn warum willst du also sterben, du Haus Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Denn ich habe keinen Gefallen am Tode des Sterbenden, spricht der Herr HERR. Darum bekehret euch, so werdet ihr leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Du aber mache eine Wehklage fiber die Fürsten Israels');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'und sprich: Warum liegt deine Mutter, die Lowin, unter den Lowinnen und erzeucht ihre Jungen unter den jungen Lowen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Derselbigen eins zog sie auf, und ward ein junger Lowe daraus; der gewohnte sich, die Leute zu reiften und fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Da das die Heiden von ihm horeten, fingen sie ihn in ihren Gruben und führeten ihn an Ketten nach Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Da nun die Mutter sah, daß ihre Hoffnung verloren war, da sie lange gehoffet hatte, nahm sie ein anderes aus ihren Jungen und machte einen jungen Lowen daraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Da der unter den Lowinnen wandelte, ward er ein junger Lowe; der gewohnte auch, die Leute zu reiften und fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Er lernte ihre Witwen kennen und verwüstete ihre Stadte, daß das Land, und was drinnen ist, vor der Stimme seines Brullens sich entsetzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Da legten sich die Heiden aus alien Landern ringsumher und warfen ein Netz fiber ihn und fingen ihn in ihren Gruben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'und stieften ihn gebunden in ein Gatter und führeten ihn zum Konige zu Babel; und man lieft ihn verwahren, daß seine Stimme nicht mehrgehoret würde auf den Bergen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Deine Mutter war wie ein Weinstock, gleichwie du, am Wasser gepflanzet, und ihre Frucht und Reben wuchsen von dem groften Wasser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'daß seine Reben so stark wurden, daß siezu Herrenzeptern gut waren, und ward hoch unter den Reben. Und da man sah, daß er so hoch und viel Reben hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'ward er im Grimm zu Boden gerissen und verworfen; der Ostwind verdorrete seine Frucht, und seine starken Reben wurden zerbrochen, daß sie verdorreten und verbrannt wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Nun aber ist sie gepflanzet in der Wuste, in einem dürren, durstigen Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'und istein Feuer ausgegangen von ihren starken Reben, das verzehret ihre Frucht, daß in ihr keine starke Rebe mehr ist zu eines Herrn Zepter. Das ist ein klaglich und jammerlich Ding.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Und es begab sich im siebenten Jahr, am zehnten Tage des funften Monden, kamen etliche aus den Altesten Israels, den FIERRN zu fragen, und setzten sich vor mir nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Da geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Du Menschenkind, sage den Altesten Israels und sprich zu ihnen: So spricht der Herr HERR: Seid ihr kommen, mich zu fragen? So wahr ich lebe, ich will von euch ungefragt sein, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Aber willst du sie strafen, du Menschenkind, so magst du sie also strafen. Zeige ihnen an die Greuel ihrer Vater');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'und sprich zu ihnen: So spricht der Herr HERR: Zu der Zeit, da ich Israel erwahiete, erhub ich meine Hand zu dem Samen des Hauses Jakob und gab mich ihnen zu erkennen in Agyptenland. Ja, ich erhub meine Hand zu ihnen und sprach: Ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Ich erhub aber zur selbigen Zeit meine Hand, daß ich sie führete aus Agyptenland in ein Land, das ich ihnen versehen hatte, das mit Milch und Honig fleufit, ein edel Land vor alien Landern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'und sprach zu ihnen: Ein jeglicher werfe weg die Greuel vor seinen Augen und verunreiniget euch nicht an den Gotzen Agyptens; denn ich bin der HERR, euer Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Sie aber waren mir ungehorsam und wollten mir nicht gehorchen, und warf ihrer keiner weg die Greuel vor seinen Augen und verlielien die Gotzen Agyptens nicht. Da dachte ich meinen Grimm uber sie auszuschutten und alien meinen Zorn uber sie gehen zu lassen noch in Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Aber ich lieli es urn meines Namens willen, daß er nicht entheiliget wurde vor den Heiden, unter denen sie waren, und vor denen ich mich ihnen hatte zu erkennen gegeben, daß ich sie aus Agyptenland führen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Und da ich sie aus Agyptenland gefuhret hatte und in die Wüste gebracht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'gab ich ihnen meine Gebote und lehrete sie meine Rechte, durch welche lebet der Mensch, der sie halt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Ich gab ihnen auch meine Sabbate zum Zeichen zwischen mir und ihnen damit sie lerneten, daß ich der HERR sei, der sie heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Aber das Haus Israel war mir ungehorsam auch in der Wüste und lebten nicht nach meinen Geboten und verachteten meine Rechte, durch welche der Mensch lebet, der sie halt, und entheiligten meine Sabbate sehr. Da gedachte ich meinen Grimm uber sie auszuschutten in der Wüste und sie gar umzubringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Aber ich lieli es urn meines Namens willen, auf daß er nicht entheiliget würde vor den Heiden, vor welchen ich sie hatte ausgeführet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Und hub auch meine Hand auf wider sie in der Wüste, daß ich sie nicht wollte bringen in das Land, so ich ihnen gegeben hatte, das mit Milch und Honig fleufit, ein edel Land vor alien Landern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'darum daß sie meine Rechte verachtet und nach meinen Geboten nicht gelebet und meine Sabbate entheiliget hatten; denn sie wandelten nach den Gotzen ihres Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Aber mein Auge verschonete ihrer, daß ich sie nicht verderbete noch gar umbrachte in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Und ich sprach zu ihren Kindern in der Wüste: Ihr sollt nach eurer Vater Geboten nicht leben und ihre Rechte nicht halten und an ihren Gdtzen euch nicht verunreinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Denn ich hin der HERR, euer Gott; nach meinen Geboten sollt ihr leben und meine Rechte sollt ihr halten und danach tun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'und meine Sabbate sollt ihr heiligen, daß sie seien ein Zeichen zwischen mir und euch, damit ihr wisset, daß ich der HERR, euer Gott, bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Aber die Kinder waren mir auch ungehorsam, lebten nach meinen Geboten nicht, hielten auch meine Rechte nicht, daß sie danach taten, durch welche der Mensch lebet, der sie halt, und entheiligten meine Sabbate. Da gedachte ich meinen Grimm uber sie auszuschutten und all meinen Zorn uber sie gehen zu lassen in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Ich wandte aber meine Hand und lieli es urn meines Namens willen, auf daß er nicht entheiliget wurde vor den Heiden, vor welchen ich sie hatte ausgeführet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Ich hub auch meine Hand auf wider sie in der Wuste, daß ich sie zerstreuete unter die Heiden und zerstaubete in die Lander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'darum daß sie meine Gebote nicht gehalten und meine Rechte verachtet und meine Sabbate entheiliget hatten und nach den Gdtzen ihrer Vater sahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Darum ubergab ich sie in die Lehre, so nicht gut ist, und in Rechte, darin sie kein Leben konnten haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'und verwarf sie mit ihrem Opfer, da sie alle Erstgeburt durchs Feuer verbrannten, damit ich sie verstorte und sie lernen muliten, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Darum rede, du Menschenkind, mit dem Hause Israel und sprich zu ihnen: So spricht der Herr HERR: Eure Vater haben mich noch weiter gelastert und getrotzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Denn da ich sie in das Land gebracht hatte, uber welches ich meine Hand aufgehoben hatte, daß ich\'s ihnen gabe: wo sie einen hohen Hugel Oder dicken Baum ersahen, daselbst opferten sie ihre Opfer und brachten dahin ihre feindseligen Gaben und raucherten daselbst ihren süßen Geruch und gossen daselbst ihre Trankopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Ich aber sprach zu ihnen: Was soil doch die Hohe, dahin ihr gehet? Und also heißt sie bis auf diesen Tag die Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Darum sprich zum Hause Israel: So spricht der Herr HERR: Ihr verunreiniget euch in dem Wesen eurer Vater und treibet Hurerei mit ihren Greueln');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'und verunreiniget euch an euren Gotzen, welchen ihr eure Gaben opfert und eure Sohne und Tochter durchs Feuer verbrennet, bis auf den heutigen Tag; und ich sollte mich euch vom Hause Israel fragen lassen? So wahr ich lebe, spricht der Herr HERR, ich will von euch ungefragt sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Dazu, daß ihr gedenket, wir wollen tun wie die Heiden und wie andere Leute in Landern, Holz und Stein anbeten, das soil euch fehlen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'So wahr ich lebe, spricht der Herr HERR, ich will uber euch herrschen mit starker Hand und ausgestrecktem Arm und mit ausgeschüttetem Grimm;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'und will euch aus den Volkern führen und aus den Landern, dahin ihr verstreuet seid, sammeln mit starker Hand, mit ausgestrecktem Arm und mit ausgeschüttetem Grimm;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'und will euch bringen in die Wüste der Volker und daselbst mit euch rechten von Angesicht zu Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Wie ich mit euren Vatern in der Wüste bei Agypten gerechtet habe, ebenso will ich auch mit euch rechten, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Ich will euch wohl unter die Rute bringen und euch in die Bande des Bundes zwingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Und will die Abtrünnigen, und so wider mich übertreten, unter euch ausfegen; ja, aus dem Lande, da ihr jetzt wohnet, will ich sie führen und ins Land Israel nicht kommen lassen, daß ihr lernen sollt, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Darum, ihr vom Hause Israel, so spricht der Herr HERR: Weil ihr denn mirja nicht wollt gehorchen, so fahret hin und diene ein jeglicher seinem Gotzen; aber meinen heiligen Namen laßt hinfort ungeschandet mit euren Opfern und Gotzen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Denn so spricht der Herr HERR: Auf meinem heiligen Berge, auf dem hohen Berge Israel, daselbst wird mirdas ganze Haus Israel und alle, die im Lande sind, dienen; daselbst werden sie mir angenehm sein, und daselbst will ich eure Hebopfer und Erstlinge eurer Opfer fordern mit allem, das ihr mir heiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Ihr werdet mir angenehm sein mit dem sülien Geruch, wenn ich euch aus den Volkern bringen und aus den Landern sammeln werde, dahin ihr verstreuet seid, und werde in euch geheiliget werden vor den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Und ihr werdet erfahren, daß ich der HERR bin, wenn ich euch ins Land Israel gebracht habe, in das Land, darüber ich meine Hand aufhub, daß ich\'s euren Vatern gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Daselbst werdet ihr gedenken an euer Wesen und an all euer Tun, darinnen ihr verunreiniget seid, und werdet Mififallen haben uber alle eure Bosheit, die ihr getan habt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'und werdet erfahren, daß ich der HERR bin, wenn ich mit euch tue urn meines Namens willen und nicht nach eurem bosen Wesen und schadlichem Tun, du Haus Israel, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Du Menschenkind, richte dein Angesicht gegen den Sudwind zu und traufe gegen den Mittag und weissage wider den Wald im Felde gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Und sprich zum Walde gegen Mittag: Hore des HERRN Wort! So spricht der Herr HERR: Siehe, ich will in dir ein Feuer anzünden, das soil beide, grüne und dürre Baume, verzehren, daß man seine Flamme nicht wird loschen konnen, sondern es soil verbrannt werden alles, was vom Mittage gegen Mitternacht stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Und alles Fleisch soil sehen, daß ich, der HERR, es angezündet habe und niemand loschen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Und ich sprach: Ach, Herr HERR, sie sagen von mir: Dieser redet eitel verdeckte Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Du Menschenkind, richte dein Angesicht wider Jerusalem und traufe wider die Heiligtümer und weissage wider das Land Israel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'und sprich zum Lande Israel: So spricht der Herr HERR: Siehe, ich will an dich; ich will mein Schwert aus der Scheide ziehen und will in dir ausrotten beide, Gerechte und Ungerechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Weil ich denn in dir beide, Gerechte und Ungerechte, ausrotte, so wird mein Schwert aus der Scheide fahren uber alles Fleisch vom Mittage her bis gen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Und soil alles Fleisch erfahren, daß ich, der HERR, mein Schwert hab\' aus seiner Scheide gezogen; und soil nicht wieder eingesteckt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Und du, Menschenkind, sollst seufzen, bis dir die Lenden weh tun; ja, bitterlich sollst du seufzen, daß sie es sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Und wenn sie zu dir sagen werden: Warum seufzest du? sollst du sagen: Urn des Geschreies willen, das da kommt, vor welchem alle Herzen verzagen und alle Hande sinken, aller Mut fallen, und alle Kniee wie Wasser gehen werden. Siehe, es kommt und wird geschehen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Du Menschenkind, weissage und sprich: So spricht der HERR: Sprich: Das Schwert, ja, das Schwert ist gescharft und gefegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Es ist gescharft, daß es schlachten soil; es ist gefegt, daß es blinken soil. 0 wie froh wollten wir sein, wenn er gleich alle Baume zu Ruten machte über die bosen Kinder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Aber er hat ein Schwert zu fegen gegeben, daß man es fassen soil; es ist gescharft und gefegt, daß man\'s dem Totschlager in die Hand gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Schreie und heule, du Menschenkind; denn es gehet uber mein Volk und uber alle Regenten in Israel, die zum Schwert samt meinem Volk versammelt sind. Darum schlage auf deine Lenden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Denn er hat sie oft gezuchtiget; was hat\'s geholfen? Es will der bosen Kinder Rute nicht helfen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Und du, Menschenkind, weissage und schlage deine Hande zusammen. Denn das Schwert wird zwiefach, ja dreifach kommen, ein Wurgeschwert, ein Schwert grafter Schlacht, das sie auch treffen wird in den Kammern, da sie hinfliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Ich will das Schwert lassen klingen, daß die Herzen verzagen und viele fallen sollen an alien ihren Toren. Ach, wie glanzet es und hauet daher zur Schlacht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Und sprechen: Haue drein, beide, zur Rechten und Linken, was vor dir ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Da will ich dann mit meinen Handen darob frohlocken und meinen Zorn gehen lassen. Ich, der HERR, hab es gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Du Menschenkind, mache zween Wege, durch welche kommen soil das Schwert des Konigs zu Babel; sie sollen aber alle beide aus einem Lande gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Und stelle ein Zeichen vorne an den Weg zur Stadt, dahin es weisen soil; und mache den Weg, daß das Schwert komme gen Rabbath der Kinder Ammon und nach Juda, zu der festen Stadt Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Denn der Konig zu Babel wird sich an die Wegscheide stellen, vorne an den zween Wegen, daß er ihm wahrsagen lasse, mit den Pfeilen urn das Los schiefte, seinen Abgott frage und schaue die Leber an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Und die Wahrsagung wird auf die rechte Seite gen Jerusalem deuten, daß er solle Bocke hinanfuhren lassen und Ldcher machen und mit groftem Geschrei sie uberfalle und morde, und daß er Bocke fuhren solle wider die Tore und da Wall schutte und Bollwerk baue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Aberes wird sie solch Wahrsagen falsch dunken, er schwore, wie teuer er will. Er aber wird denken an die Missetat, daß ersie gewinne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Darum spricht der Herr HERR also: Darum daß euer gedacht wird urn eurer Missetat und euer Ungehorsam offenbart ist, daß man eure Sunde siehet in all eurem Tun, ja darum daß euer gedacht wird, werdet ihr mit Gewalt gefangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Und du, Furst in Israel, der du verdammt und verurteilet bist, des Tag daherkommen wird, wenn die Missetat zum Ende kommen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'so spricht der Herr HERR: Tu weg den Hut und heb ab die Krone! Denn es wird weder der Hut noch die Krone bleiben, sondern der sich erhohet hat, soil geniedriget werden, und der sich niedriget, soil erhohet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Ich will die Krone zunichte, zunichte, zunichte machen, bis der komme, der sie haben soil; dem will ich sie geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'Und du, Menschenkind, weissage und sprich: So spricht der Herr HERR von den Kindern Ammon und von ihrer Schmach und sprich: Das Schwert, das Schwert ist gezuckt, daß es schlachten soil; es ist gefegt, daß es wurgen soil, und soil blinken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'darum daß du falsche Gesichte dir sagen lassest und Lugen weissagen, damit du auch ubergeben werdest unter den erschlagenen Gottlosen, welchen ihr Tag kam, da die Missetat zum Ende kommen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Und ob es schon wieder in die Scheide gesteckt würde, so will ich dich doch richten an dem Ort, da du geschaffen, und im Lande, da du geboren bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'Und will meinen Zorn über dich schutten, ich will das Feuer meines Grimms über dich aufblasen und will dich Leuten, die brennen und verderben konnen, überantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Du mufttdem Feuer zur Speise werden, und dein Blut muft im Lande vergossen werden; und man wird dein nicht mehr gedenken. Denn ich, der HERR, hab es geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Du Menschenkind, willst du nicht strafen die morderische Stadt und ihr anzeigen alle ihre Greuel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Sprich: So spricht der Herr HERR: 0 Stadt, die du der Deinen Blut vergeuftest, auf daß deine Zeit komme, und die du Gotzen bei dir machst, damit du dich verunreinigest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Du verschuldest dich an dem Blut, das Du vergeuftest, und verunreinigest dich an den Gotzen, die du machst; damit bringest du deine Tage herzu und machst, daß deine Jahre kommen müssen. Darum will ich dich zum Spott unter den Heiden und zum Hohn in alien Landern machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Beide, in der Nahe und in der Feme, sollen sie dein spotten, daß du ein schandlich Gerucht haben und graven Jammer leiden müssest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Siehe die Fursten in Israel! Ein jeglicher ist machtig bei dir, Blut zu vergielien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Vater und Mutter verachten sie; den Fremdlingen tun sie Gewalt und Unrecht; die Witwen und Waisen schinden sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Du verachtest meine Heiligtümer und entheiligest meine Sabbate.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Verrater sind in dir, auf daß sie Blut vergießen. Sie essen auf den Bergen und handeln mutwilliglich in dir;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'sie bloßen die Scham der Vater und notigen die Weiber in ihrer Krankheit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'und treiben untereinander, Freund mit Freundes Weibe, Greuel; sie schanden ihre eigene Schnur mit allem Mutwillen; sie notzuchtigen ihre eigenen Schwestern, ihres Vaters Tochter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'sie nehmen Geschenke, auf dafi sie Blut vergießen; sie wuchern und übersetzen einander und treiben ihren Geiz wider ihren Nachsten und tun einander Gewalt und vergessen mein also, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Siehe, ich schlage meine Hande zusammen fiber den Geiz, den du treibest, und über das Blut, so in dir vergossen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Meinest du aber, dein Herz moge es erleiden Oder deine Hande ertragen zu der Zeit, wenn ich\'s mit dir machen werde? Ich, der HERR, hab es geredet und will\'s auch tun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'und will dich zerstreuen unter die Heiden und dich verstolien in die Lander und will deines Unflats ein Ende machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'da(S du bei den Heiden mußt verflucht geachtet werden und erfahren, dafi ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Du Menschenkind, das Haus Israel ist mirzu Schaum worden; all ihr Erz, Zinn, Eisen und Blei ist im Ofen zu Silberschaum worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Darum spricht der Herr HERR also: Weil ihr denn alle Schaum worden seid, siehe, so will ich euch alle gen Jerusalem zusammentun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Wie man Silber, Erz, Eisen, Blei und Zinn zusammentut im Ofen, daß man ein Feuer darunter aufblase und zerschmelze es, also will ich euch auch in meinem Zorn und Grimm zusammentun, einlegen und schmelzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Ja, ich will euch sammeln und das Feuer meines Zorns unter euch aufblasen, dafi ihr drinnen zerschmelzen müsset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Wie das Silber zerschmilzet im Ofen, so sollt ihr auch drinnen zerschmelzen und erfahren, daß ich, der HERR, meinen Grimm über euch ausgeschüttet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Du Menschenkind, sprich zu ihnen: Du bist ein Land, das nicht zu reinigen ist, wie eins, das nicht beregnet wird zur Zeit des Zorns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Die Propheten, so drinnen sind, haben sich gerottet, die Seelen zu fressen, wie ein brullender Lowe, wenn er raubet; sie reifien Gut und Geld zu sich und machen der Witwen viel drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Ihre Priester verkehren mein Gesetz freventlich und entheiligen mein Heiligtum; sie halten unter dem Heiligen und Unheiligen keinen Unterschied und lehren nicht, was rein Oder unrein sei, und warten meiner Sabbate nicht; und ich werde unter ihnen entheiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ihre Fursten sind drinnen wie die reißenden Wolfe, Blut zu vergielien und Seelen umzubringen, urn ihres Geizes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Und ihre Propheten tunchen sie mit losem Kalk, predigen lose Teidinge und weissagen ihnen Lugen und sagen: So spricht der Herr HERR! so es doch der HERR nicht geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Das Volk im Lande ubet Gewalt und rauben getrost und schinden die Armen und Elenden und tun den Fremdlingen Gewalt und Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Ich suchte unter ihnen, ob jemand sich eine Mauer machte und wider den Rili stünde vor mir fur das Land, daß ich\'s nicht verderbete; aber ich fand keinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Darum schüttete ich meinen Zorn über sie und mit dem Feuer meines Grimms machte ich ihrer ein Ende und gab ihnen also ihren Verdienst auf ihren Kopf, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Du Menschenkind, es waren zwei Weiber, einer Mutter Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Die trieben Hurerei in Agypten in ihrer Jugend; daselbst lielien sie ihre Brüste begreifen und die Zitzen ihrer Jungfrauschaft betasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Die grolie heilit Ahala und ihre Schwester Ahaliba. Und ich nahm sie zur Ehe, und sie zeugeten mirßohne und Tochter. Und Ahala heilit Samaria und Ahaliba Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ahala trieb Hurerei, da ich sie genommen hatte, und brannte gegen ihre Buhlen, namlich gegen die Assyrier, die zu ihr kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'gegen die Fursten und Herren, die mit Seide gekleidet waren, und alle junge liebliche Gesellen, namlich gegen die Reiter und Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Und buhlete mit alien schonen Gesellen in Assyrien und verunreinigte sich mit alien ihren Gotzen, wo sie auf einen entbrannte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Dazu verlielj sie auch nicht ihre Hurerei mit Agypten, die bei ihr gelegen waren von ihrer Jugend auf und die Brüste ihrer Jungfrauschaft betastet und grolie Hurerei mit ihr getrieben hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Da übergab ich sie in die Hand ihrer Buhlen, den Kindern Assur, gegen welche sie brannte vor Lust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Die deckten ihre Scham auf und nahmen ihre Sohne und Tochter weg; sie aber toteten sie mit dem Schwert. Und es kam aus, dall diese Weiber gestraft waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Da es aber ihre Schwester Ahaliba sah, entbrannte sie noch viel arger denn jene und trieb der Hurerei mehr denn ihre Schwester');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'und entbrannte gegen die Kinder Assur, namlich die Fursten und Herren, die zu ihr kamen wohl gekleidet, Reiter und Wagen, und alle junge liebliche Gesellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Da sah ich, daß sie alle beide gleicherweise verunreiniget waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Aber diese trieb ihre Hurerei mehr. Denn da sie sah gemalte Manner an der Wand in rater Farbe, die Bilder der Chaldaer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'um ihre Lenden gegurtet und bunte Kogel auf ihren Kopfen, und alle gleich anzusehen wie gewaltige Leute, wie denn die Kinder Babel und die Chaldaer tragen in ihrem Vaterlande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'entbrannte sie gegen sie, sobald sie ihrer gewahr ward, und schickte Botschaft zu ihnen nach Chaldaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Als nun die Kinder Babel zu ihr kamen, bei ihr zu schlafen nach der Liebe, verunreinigten sie dieselbe mit ihrer Hurerei, und sie verunreinigte sich mit ihnen, dad sie ihrer müde ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Und da beide ihre Hurerei und Scham so gar offenbar war, ward ich ihrer auch uberdrussig, wie ich ihrer Schwester auch war müde worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Sie aber trieb ihre Hurerei immer mehr und gedachte an die Zeit ihrer Jugend, da sie in Agyptenland Hurerei getrieben hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'und entbrannte gegen ihre Buhlen, welcher Brunst war wie der Esel und der Hengste Brunst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Und bestelletest deine Unzucht wie in deiner Jugend, da die in Agypten deine Brüste begriffen und deine Zitzen betastetwurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Darum, Ahaliba, so spricht der Herr HERR: Siehe, ich will deine Buhlen, deren du müde bist worden, wider dich erwecken und will sie ringsumher wider dich bringen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'namlich die Kinder Babel und alle Chaldaer mit Hauptleuten, Fursten und Herren, und alle Assyrier mit ihnen, die schone junge Mannschaft, alle Fürsten und Herren, Ritter und Edle und allerlei Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Und werden über dich kommen, gerustet mit Wagen und Radern und mit groliem Haufen Volks, und werden dich belagern mit Tartschen, Schilden und Helmen um und um. Denen will ich das Recht befehlen, daß sie dich richten sollen nach ihrem Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Ich will meinen Eifer über dich gehen lassen, daß sie unbarmherzig mit dir handeln sollen. Sie sollen dir Nasen und Ohren abschneiden; und was ubrig bleibt, soil durchs Schwert fallen. Sie sollen deine Sohne und Tdchter wegnehmen und das Ubrige mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Sie sollen dir deine Kleiderausziehen und deinen Schmuck wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Also will ich deiner Unzucht und deiner Hurerei mit Agyptenland ein Ende machen, daß du deine Augen nicht mehr nach ihnen aufheben und Agyptens nicht mehr gedenken sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Denn so spricht der Herr HERR: Siehe, ich will dich überantworten, denen du feind worden und deren du müde bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Die sollen als Feinde mit dir umgehen und alles nehmen, was du erworben hast, und dich nackend und bloli lassen, daß deine Scham aufgedeckt werde samt deiner Unzucht und Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Solches wird dir geschehen um deiner Hurerei willen, so du mit den Heiden getrieben, an welcher Gotzen du dich verunreiniget hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Du bist auf dem Wege deiner Schwester gegangen; darum gebe ich dir auch derselbigen Kelch in deine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So spricht der Herr HERR: Du mulit den Kelch deiner Schwester trinken, so tief und weit er ist; du sollst so zu groliem Spott und Hohn werden, daß es unertraglich sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Du mulit dich des starken Tranks und Jammers voll saufen; denn der Kelch deiner Schwester Samaria ist ein Kelch des Jammers und Trauerns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Denselben mulit du rein austrinken, danach die Scherben zerwerfen und deine Brüste zerreilien; denn ich hab es geredet, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Darum so spricht der Herr HERR: Darum daß du mein vergessen und mich hinter deinen Rucken geworfen hast, so trage auch nun deine Unzucht und deine Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Und der HERR sprach zu mir: Du Menschenkind, willst du Ahala und Ahaliba strafen, so zeige ihnen an ihre Greuel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'wie sie Ehebrecherei getrieben und Blut vergossen und die Ehe gebrochen haben mit den Gotzen; dazu ihre Kinder, die sie mirgezeuget hatten, verbrannten sie denselben zum Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Uber das haben sie mir das getan: sie haben meine Heiligtumer verunreiniget dazumal und meine Sabbate entheiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Denn da sie ihre Kinder den Gotzen geschlachtet hatten, gingen sie desselbigen Tages in mein Heiligtum, dasselbige zu entheiligen. Siehe, solches haben sie in meinem Hause begangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Sie haben auch Boten geschickt nach Leuten, die aus fernen Landen kommen sollten; und siehe, da sie kamen, badetest du dich und schminktest dich und schmucktest dich mit Geschmeide, ihnen zu Ehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'und saliest auf einem herrlichen Bette, vor welchem stund ein Tisch zugerichtet; darauf rauchertest du und opfertest mein Ol darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Daselbst hub sich ein grofi Freudengeschrei; und sie gaben den Leuten, so allenthalben aus groliem Volk und aus der Wuste kommen waren, Geschmeide an ihre Arme und schone Kronen auf ihre Haupter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Ich aber gedachte: Sie ist der Ehebrecherei gewohnt von alters her, sie kann von der Hurerei nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Denn man geht zu ihr ein, wie man zu einer Hure eingeht; ebenso geht man zu Ahala und Ahaliba, den unzuchtigen Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Darum werden sie die Manner strafen, die das Recht vollbringen, wie man die Ehebrecherinnen und Blutvergielierinnen strafen soli; denn sie sind Ehebrecherinnen, und ihre Hande sind voll Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Also spricht der Herr HERR: Führe einen grolien Haufen fiber sie herauf und gib sie in die Rapuse und Raub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'die sie steinigen und mit ihren Schwertern erstechen und ihre Sohne und Tochter erwürgen und ihre Hauser mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Also will ich der Unzucht im Lande ein Ende machen, daü sich alle Weiber daran stolien sollen und nicht nach solcher Unzucht tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Und man soil eure Unzucht auf euch legen, und sollt eurer Gotzen Sunde tragen, auf daß ihr erfahret, daü ich der Herr HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Und es geschah das Wort des HERRN zu mir im neunten Jahr, am zehnten Tage des zehnten Monden, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Du Menschenkind, schreibe diesen Tag an, ja eben diesen Tag; denn der Konig zu Babel hat sich eben an diesem Tage wider Jerusalem gerustet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Und gib dem ungehorsamen Volk ein Gleichnis und sprich zu ihnen: So spricht der Herr HERR: Setze einen Topfzu; setze zu und gieli Wasser darein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Tue die Stücke zusammen darein, die hinein sollen, und die besten Stücke, die Lenden und Schultern, und fülle ihn mit den besten Markstücken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Nimm das Beste von der Herde und mache ein Feuer darunter, Markstücke zu kochen, und lali es getrost sieden und die Markstücke drinnen wohl kochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Darum spricht der Herr HERR: 0 der morderischen Stadt, die ein solcher Topf ist, da das Angebrannte drinnen klebet, und nicht abgehen will! Tue ein Stück nach dem andern heraus, und darfst nicht darum losen, welches erst heraus solle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Denn ihr Blut ist drinnen, das sie auf einen blolien Felsen und nicht auf die Erde verschuttet hat, da man\'s doch hatte mit Erde konnen zuscharren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Und ich hab auch darum sie lassen dasselbige Blut auf einen blolien Felsen schütten, daß es nicht zugescharret würde, auf daß der Grimm über sie kame und gerochen würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Darum spricht der Herr HERR also: O du morderische Stadt, welche ich will zu einem grolien Feuer machen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Trage nur viel Holz her, zünde das Feuer an, daß das Fleisch gar werde, und würze es wohl, dafi die Markstücke anbrennen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Lege auch den Topf leer auf die Glut, auf daß er heifi werde und sein Erz entbrenne, ob seine Unreinigkeit zerschmelzen und sein Angebranntes abgehen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Aber das Angebrannte, wie fast es brennet, will nicht abgehen, denn es ist zu sehr angebrannt; es muli im Feuer verschmelzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Deine Unreinigkeit ist so verhartet, daß, ob ich dich gleich gerne reinigen wollte, dennoch du nicht willst dich reinigen lassen von deiner Unreinigkeit. Darum kannst du fort nicht wieder rein werden, bis mein Grimm sich an dir gekühlet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ich, der HERR, hab es geredet; es soil kommen. Ich will\'s tun und nicht saumen; ich will nicht schonen noch mich\'s reuen lassen, sondern sie sollen dich richten, wie du gelebt und getan hast, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Du Menschenkind, siehe, ich will dir deiner Augen Lust nehmen durch eine Plage. Aber du sollst nicht klagen noch weinen, noch eine Trane lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Heimlich magst du seufzen, aber keine Totenklage führen, sondern du sollst deinen Schmuck anlegen und deine Schuhe anziehen. Du sollst deinen Mund nicht verhüllen und nicht das Trauerbrot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Und da ich des Morgens frith zum Volk redete, starb mir zu Abend mein Weib. Und ich tat des andern Morgens, wie mir befohlen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Und das Volk sprach zu mir: Willst du uns denn nicht anzeigen, was uns das bedeute, das du tust?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Und ich sprach zu ihnen: Der HERR hat mit mir geredet und gesagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Sage dem Hause Israel, daß der Herr HERR spricht also: Siehe, ich will mein Heiligtum, euren hochsten Trost, die Lust eurer Augen und eures Herzens Wunsch, entheiligen; und eure Sohne und Tochter, die ihr verlassen müsset, werden durchs Schwert fallen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'und müsset tun, wie ich getan habe: euren Mund müsset ihr nicht verhüllen und das Trauerbrot nicht essen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'sondern müsset euren Schmuck auf euer Haupt setzen und eure Schuhe anziehen. Ihrwerdet nicht klagen noch weinen, sondern über euren Sünden verschmachten und untereinander seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Und soil also Hesekiel euch ein Wunder sein, daß ihr tun müsset, wie er getan hat, wenn es nun kommen wird, damit ihr erfahret, daß ich der Herr HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Und du, Menschenkind, zu der Zeit, wenn ich wegnehmen werde von ihnen ihre Macht und Trost, die Lust ihrer Augen und ihres Herzens Wunsch, ihre Sohne und Tochter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'ja, zur selbigen Zeit wird einer, so entronnen ist, zu dir kommen und dir\'s kundtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Zur selbigen Zeit wird dein Mund aufgetan werden samtdem, derentronnen ist, daß du reden sollst und nicht mehr schweigen; denn du muftt ihr Wunder sein, daß sie erfahren, ich sei der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Du Menschenkind, richte dein Angesicht gegen die Kinder Ammon und weissage wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Und sprich zu den Kindern Ammon: Horet des Herrn HERRN Wort! So spricht der Herr HERR: Darum daß ihr uber mein Heiligtum sprechet: Heh, es ist entheiliget! und uber das Land Israel: Es ist verwüstet! und uber das Haus Juda: Es ist gefangen weggeführt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'darum siehe, ich will dich den Kindern gegen Morgen ubergeben, daß sie ihre Schldsser drinnen bauen und ihre Wohnung drinnen machen sollen; sie sollen deine Fruchte essen und deine Milch trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Und will Rabbath zum Kamelstall machen und die Kinder Ammon zurßchafhurde machen; und sollet erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Denn so spricht der Herr HERR: Darum daß du mit deinen Handen geklatschet und mit den Fuften gescharret und uber das Land Israel von ganzem Herzen so hohnisch dich gefreuet hast,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'darum siehe, ich will meine Hand uber dich ausstrecken und dich den Heiden zur Beute geben und dich aus den Volkern ausrotten und aus den Landern umbringen und dich vertilgen; und sollst erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So spricht der Herr HERR: Darum daß Moab und Seir sprechen: Siehe, das Haus Juda ist eben wie alle andern Heiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'siehe, so will ich Moab zur Seite offnen in seinen Stadten und in seinen Grenzen des edlen Landes, namlich Beth-Jesimoth, Baal-Meon und Kiriathaim,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'den Kindern gegen Morgen samt den Kindern Ammon, und will sie ihnen zum Erbe geben, daß man der Kinder Ammon nicht mehr gedenken soli unter den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Und will das Recht gehen lassen uber Moab, und sollen erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So spricht der Herr HERR: Darum daß sich Edom am Hause Juda geracht hat und damit sich verschuldet mit ihrem Rachen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'darum spricht der Herr HERR also: Ich will meine Hand ausstrecken uber Edom und will ausrotten von ihm beide, Menschen und Vieh; und will sie wüste machen von Theman bis gen Dedan und durchs Schwert fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Und will mich an Edom rachen durch mein Volk Israel, und sollen mit Edom umgehen nach meinem Zorn und Grimm, daß sie meine Rache erfahren sollen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So spricht der Herr HERR: darum daß die Philister sich geracht haben und den alten Haft gebuftet nach all ihrem Willen am Schaden (meines Volks),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'darum spricht der Herr HERR also: Siehe, ich will meine Hand ausstrecken über die Philister und die Krieger ausrotten und will die Ubrigen am Hafen des Meers umbringen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'und will grofte Rache an ihnen üben und mit Grimm sie strafen, daß sie erfahren sollen, ich sei der HERR, wenn ich meine Rache an ihnen geubet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Und es begab sich im elften Jahr, am ersten Tage des ersten Monden, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Du Menschenkind, darum daß Tyrus spricht uber Jerusalem: Heh, die Pforten der Volker sind zerbrochen, es ist zu mir gewandt; ich werde nun voll werden, weil sie wüste ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'darum spricht der Herr HERR also: Siehe, ich will an dich, Tyrus, und will viel Heiden uber dich heraufbringen, gleichwie sich ein Meer erhebt mit seinen Wellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Die sollen die Mauern zu Tyrus verderben und ihre Turme abbrechen; ja, ich will auch den Staub vor ihrwegfegen und will einen bloften Fels aus ihr machen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'und zu einem Werd im Meer, darauf man die Fischgarne ausspannet; denn ich hab es geredet, spricht der Herr HERR: und sie soil den Heiden zum Raub werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Und ihre Tochter, so auf dem Felde liegen, sollen durchs Schwert erwurget werden; und sollen erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Denn so spricht der Herr HERR: Siehe, ich will über Tyrus kommen lassen Nebukadnezar, den Konig zu Babel, von Mitternacht her, der ein Konig aller Konige ist, mit Rossen, Wagen, Reitern und mit groftem Haufen Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Der soil deine Tochter, so auf dem Felde liegen, mit dem Schwert erwurgen; aber wider dich wird er Bollwerk aufschlagen und einen Schutt machen und Schilde wider dich rüsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Er wird mit Bocken deine Mauern zerstoften und deine Turme mit seinen Waffen umreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Der Staub von der Menge seiner Pferde wird dich bedecken, so werden auch deine Mauern erbeben vor dem Getummel seiner Rosse, Rader und Reiter, wenn er zu deinen Toren einziehen wird, wie man pflegt in eine zerrissene Stadt einzuziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Er wird mit den Fuften seiner Rosse alle deine Gassen zertreten. Dein Volk wird er mit dem Schwert erwurgen und deine starken Saulen zu Boden reiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Sie werden dein Gut rauben und deinen Handel plündern. Deine Mauern werden sie abbrechen und deine feinen Hauser umreiften und werden deine Steine, Holz und Staub ins Wasser werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Also will ich mit dem Getone deines Gesangs ein Ende machen, dafi man den Klang deiner Harfen nicht mehr horen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Und ich will einen bloßen Fels aus dir machen und einen Werd, darauf man die Fischgarne ausspannet, daß du nicht mehr gebauet werdest; denn ich bin der HERR, der solches redet, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So spricht der Herr HERR wider Tyrus: Was gilt\'s, die Inseln werden erbeben, wenn du so scheuftlich zerfallen wirst und deine Verwundeten seufzen werden, so in dir sollen ermordet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Alle Fursten am Meer werden herab von ihren Stuhlen sitzen und ihre Rocke von sich tun und ihre gestickten Kleider ausziehen und werden in Trauerkleidern gehen und auf der Erde sitzen und werden erschrecken und sich entsetzen deines plotzlichen Falls.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Sie werden dich wehklagen und von dirsagen: Ach, wie bist du so gar wüste worden, du berühmte Stadt, die du am Meer lagest und so machtig warest auf dem Meer samt deinen Einwohnern, daß sich das ganze Land vor dir furchten muftte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Ach, wie entsetzen sich die Inseln fiber deinen Fall! Ja, die Inseln im Meer erschrecken fiber deinen Untergang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'So spricht der Herr HERR: Ich will dich zu einer wusten Stadt machen, wie andere Stadte, da niemand innen wohnet, und eine grofie Flut uber dich kommen lassen, daß dich grofte Wasser bedecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Und will dich hinunterstoften zu denen, die in die Grube fahren, namlich zu den Toten. Ich will dich unter die Erde hinabstoften und wie eine ewige Wuste machen mit denen, die in die Grube fahren, auf daß niemand in dirwohne. Ich will dich, du Zarte, im Lande der Lebendigen machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'ja, zum Schrecken will ich dich machen, daß du nichts mehr seiest, und wenn man nach dir fraget, daß man dich ewiglich nimmer finden konne, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Du Menschenkind, mache eine Wehklage uber Tyrus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'und sprich zu Tyrus, die da liegt vorne am Meer und mit vielen Inseln der Volker handelt: So spricht der Herr HERR: 0 Tyrus, du sprichst: Ich bin die allerschonste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Deine Grenzen sind mitten im Meer, und deine Bauleute haben dich aufs allerschonste zugerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Sie haben all dein Tafelwerk aus Zypressenholz vom Senir gemacht und die Zedern von dem Libanon führen lassen und deine Mastbaume daraus gemacht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'und deine Ruder von Eichen aus Basan und deine Banke von Elfenbein und die kostlichen Gestuhle aus den Inseln Chittim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Dein Segel war von gestickter Seide aus Agypten, daß es dein Panier ware, und deine Decken von gelber Seide und Purpur aus den Inseln Elisa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Die von Zidon und Arvad waren deine Ruderknechte, und hattest geschickte Leute zu Tyrus zu schiffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Die Altesten und Klugen von Gebal muftten deine Schiffe zimmern. Alle Schiffe im Meer und Schiffsleute fand man bei dir, die hatten ihren Handel in dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Die aus Persien, Lydien und Libyen waren dein Kriegsvolk, die ihren Schild und Helm in diraufhingen, und haben dich so schon gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Die von Arvad waren unter deinem Heer rings urn deine Mauern und Wachter auf deinen Türmen; die haben ihre Schilde allenthalben von deinen Mauern herabgehanget und dich so schon gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Du hast deinen Handel auf dem Meer gehabt und allerlei Ware, Silber, Eisen, Zinn und Blei, auf deine Markte gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Thubal und Mesech haben mit dir gehandelt und haben dir leibeigene Leute und Erz auf deine Markte gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Die von Thogarma haben dir Pferde und Wagen und Maulesel auf deine Markte gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Die von Dedan sind deine Kaufleute gewesen, und hast allenthalben in den Inseln gehandelt; die haben dir Elfenbein und Ebenholz verkauft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Die Syrer haben bei dir gehoiet deine Arbeit, was du gemacht hast; und Rubin, Purpur, Tapet, Seide und Sammet und Kristalle auf deine Markte gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda und das Land Israel haben auch mit dir gehandelt und haben dir Weizen von Minnith und Balsam und Honig und 01 und Mastix auf deine Markte gebracht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Dazu hat auch Damaskus bei dir gehoiet deine Arbeit und allerlei Ware urn starken Wein und kostliche Wolle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Dan und Javan und Mehusal haben auch auf deine Markte gebracht Eisenwerk, Kasia und Kalmus, daß du damit handeltest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan hat mit dir gehandelt mit Decken, darauf man sitzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien und alle Fursten von Kedar haben mit dir gehandelt mit Schafen Widdern und Bocken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Die Kaufleute aus Saba und Raema haben mit dir gehandelt und allerlei kostliche Spezerei und Edelstein und Gold auf deine Markte gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran und Kanne und Eden samt den Kaufleuten aus Seba, Assur und Kilmad sind auch deine Kaufleute gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Die haben alle mit dir gehandelt mit kostlichem Gewand, mit seidenen und gestickten Tuchern, welche sie in kostlichen Kasten, von Zedern gemacht und wohlverwahrt, auf deine Markte gefuhret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Aber die Meerschiffe sind die vornehmsten auf deinen Markten gewesen. Also bistdu sehr reich und prachtig worden mitten im Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Und deine Schiffsleute haben dir auf groften Wassern zugefuhret. Aber ein Ostwind wird dich mitten auf dem Meer zerbrechen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'also daß deine Ware, Kaufleute, Handler, Fergen, Schiffsherren und die, so die Schiffe machen, und deine Hantierer und alle deine Kriegsleute und alles Volk in dir mitten auf dem Meer umkommen werden zur Zeit, wenn du untergehest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'daß auch die Anfurten erbeben werden vor dem Geschrei deiner Schiffsherren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Und alle, die an den Rudern ziehen, samt den Schiffsknechten und Meistern, werden aus den Schiffen ans Land treten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'und laut uber dich schreien, bitterlich klagen und werden Staub auf ihre Haupterwerfen, und sich in der Asche walzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Sie werden sich kahl bescheren uber dir und Sacke urn sich gürten und von Herzen bitterlich urn dich weinen und trauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Es werden auch ihre Kinder uber dich klagen: Ach, wer ist jemals auf dem Meere so stille worden wie du, Tyrus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Da du deinen Handel auf dem Meer triebest, da machtest du viel Lander reich; ja, mit der Menge deiner Ware und deiner Kaufmannschaft machtest du reich die Konige auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nun aber bist du vom Meer in die recht tiefen Wasser gesturzt, daß dein Handel und all dein Volk in dir umkommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Alle, die in Inseln wohnen, erschrecken uber dir, und ihre Konige entsetzen sich und sehen jammerlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Die Kaufleute in Landern pfeifen dich an, daß du so plotzlich untergegangen bist und nicht mehr aufkommen kannst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Du Menschenkind, sage dem Fursten zu Tyrus: So spricht der Herr HERR: Darum daß sich dein Herz erhebt und spricht: Ich bin Gott, ich sitze im Thron Gottes, mitten auf dem Meer, so du doch ein Mensch und nicht Gott bist; noch erhebt sich dein Herz als ein Herz Gottes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'siehe, du haltst dich fur kluger denn Daniel, daß dir nichts verborgen sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'und habest durch deine Klugheit und Verstand solche Macht zuwegegebracht und Schatze von Gold und Silbergesammelt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'und habest durch deine grofte Weisheit und Hantierung so grofte Macht überkommen, davon bist du so stolz worden, daß du so machtig bist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'darum spricht der Herr HERR also: Weil sich denn dein Herz erhebt als ein Herz Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'darum siehe, ich will Fremde uber dich schicken, namlich die Tyrannen der Heiden; die sollen ihr Schwert zücken uber deine schone Weisheit und deine grofte Ehre zuschanden machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Sie sollen dich hinunter in die Grube stoften, daß du mitten auf dem Meer sterbest, wie die Erschlagenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Was gilt\'s, ob du dann vor deinem Totschlager werdest sagen: Ich bin Gott, so du doch nicht Gott, sondern ein Mensch und in deiner Totschlager Hand bist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Du sollst sterben wie die Unbeschnittenen, von der Hand der Fremden; denn ich hab es geredet, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Du Menschenkind, mache eine Wehklage uber den Konig zu Tyrus und sprich von ihm: So spricht der Herr HERR: Du bist ein reinlich Siegel voller Weisheit und aus der Maften schon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Du bist im Lustgarten Gottes und mit allerlei Edelsteinen geschmückt, namlich mit Sarder, Topaser, Demanten, Türkis, Onyxen, Jaspis, Saphir, Amethyst, Smaragden und Gold. Am Tage, da du geschaffen wurdest, muftten da bereit sein bei dir dein Paukenwerk und Pfeifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du bist wie ein Cherub, der sich weit ausbreitet und decket; und ich habe dich auf den heiligen Berg Gottes gesetzt, daß du unter den feurigen Steinen wandelst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'und warest ohne Wandel in deinem Tun des Tages, da du geschaffen warest, so lange, bis sich deine Missetat funden hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Denn du bist inwendig voll Frevels worden vor deiner groften Hantierung und hast dich versundiget. Darum will ich dich entheiligen von dem Berge Gottes und will dich ausgebreiteten Cherub aus den feurigen Steinen verstoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Und weil sich dein Herz erhebt, daß du so schon bist, und hast dich deine Klugheit lassen betrügen in deiner Pracht, darum will ich dich zu Boden sturzen und ein Schauspiel aus dir machen vor den Konigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Denn du hast dein Heiligtum verderbet mit deiner groften Missetat und unrechtem Handel. Darum will ich ein Feuer aus dir angehen lassen, das dich soil verzehren, und will dich zu Asche machen auf der Erde, daß alle Welt zusehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle, die dich kennen unter den Heiden, werden sich uber dir entsetzen, daß du so plotzlich bist untergegangen und nimmermehr aufkommen kannst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Du Menschenkind, richte dein Angesicht wider Zidon und weissage wider sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'und sprich: So spricht der Herr HERR: Siehe, ich will an dich, Zidon, und will an dir Ehre einlegen, daß man erfahren soil, daß ich der HERR bin, wenn ich das Recht uber sie gehen lasse und an ihr erzeige, daß ich heilig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Und ich will Pestilenz und Blutvergieften unter sie schicken auf ihren Gassen, und sollen tddlich verwundet drinnen fallen durchs Schwert, welches allenthalben uber sie gehen wird; und sollen erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Und soli forthin allenthalben um das Haus Israel, da ihre Feinde sind, kein Dorn, der da sticht, noch Stachel, der da weh tut, bleiben, daß sie erfahren sollen, daß ich der Herr HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So spricht der Herr HERR: Wenn ich das Haus Israel wieder versammeln werde von den Volkern, dahin sie zerstreuet sind, so will ich vor den Heiden an ihnen erzeigen, daß ich heilig bin. Und sie sollen wohnen in ihrem Lande, das ich meinem Knechte Jakob gegeben habe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'und sollen sicher darin wohnen und Hauser bauen und Weinberge pflanzen; ja, sicher sollen sie wohnen, wenn ich das Recht gehen lasse uber alle ihre Feinde um und um; und sollen erfahren, daß ich der HERR, ihr Gott, bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Im zehnten Jahr, am zehnten Tage des zwolften Monden, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Du Menschenkind, richte dein Angesicht wider Pharao, den Konig in Agypten, und weissage wider ihn und wider ganz Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Predige und sprich: So spricht der Herr HERR: Siehe, ich will an dich, Pharao, du Konig in Agypten, du grafter Drache, der du in deinem Wasser liegst und sprichst: Der Strom ist mein, und ich habe ihn mir gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Aber ich will dir ein Gebift ins Maul legen und die Fische in deinen Wassern an deine Schuppen hangen und will dich aus deinem Strom herausziehen samt alien Fischen in deinen Wassern, die an deinen Schuppen hangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Ich will dich mit den Fischen aus deinen Wassern in die Wüste wegwerfen: du wirst aufs Land fallen und nicht wieder aufgelesen noch gesammelt werden, sondern den Tieren auf dem Lande und den Vogeln des Himmels zum Aas werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Und alle, die in Agypten wohnen, sollen erfahren, daß ich der HERR bin, darum daß sie dem Hause Israel ein Rohrstab gewesen sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'welcher, wenn sie ihn in die Hand fafteten, so brach er und stach sie durch die Seiten, wenn sie sich aber darauf lehneten, so zerbrach er und stach sie in die Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Darum spricht der Herr HERR also: Siehe, ich will das Schwert uber dich kommen lassen und beide, Leute und Vieh, in dir ausrotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Und Agyptenland soil zur Wüste und ode werden, und sollen erfahren, daß ich der HERR sei, darum daß er spricht: Der Wasserstrom ist mein, und ich bin\'s, der es tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Darum siehe, ich will an dich und an deine Wasserstrome und will Agyptenland wrist und ode machen von dem Turm zu Syene an bis an die Grenze des Mohrenlandes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'daß weder Vieh noch Leute darin gehen Oder da wohnen sollen vierzig Jahre lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Denn ich will Agyptenland wüst machen, will ihre wüste Grenze und ihre Stadte wüst liegen lassen, wie andere wüste Stadte, vierzig Jahre lang; und will die Agypter zerstreuen unter die Heiden und in die Lander will ich sie verjagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Doch, so spricht der Herr HERR: Wenn die vierzig Jahre aus sein werden, will ich die Agypter wieder sammeln aus den Volkern, darunter sie zerstreuet sollen werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'und will das Gefangnis Agyptens wenden und sie wiederum ins Land Pathros bringen, welches ihr Vaterland ist, und sollen daselbst ein klein Konigreich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Denn sie sollen klein sein gegen andere Konigreiche und nicht mehr herrschen uber die Heiden; und ich will sie gering machen, daß sie nicht mehr uber die Heiden herrschen sollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'daß sich das Haus Israel nicht mehr auf sie verlasse und sich damit versündige, wenn sie sich an sie hangen; und sollen erfahren, daß ich der Herr HERR hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Und es begab sich im siebenundzwanzigsten Jahr, am ersten Tage des ersten Monden, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Du Menschenkind, Nebukadnezar, der Konig zu Babel, hat sein Heer mit grafter Mühe vor Tyrus geführet, daß alle Haupter kahl und alle Seiten wund gerieben waren, und ist doch weder ihm noch seinem Heer seine Arbeit vor Tyrus belohnet worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Darum spricht der Herr HERR also: Siehe, ich will Nebukadnezar, dem Konige zu Babel, Agyptenland geben, daß er all ihr Gut wegnehmen und sie berauben und plundern soil, daß er seinem Heer den Sold gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Aber das Land Agypten will ich ihm geben fur seine Arbeit, die er daran getan hat; denn sie haben mir gedienet, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Zur selbigen Zeit will ich das Horn des Hauses Israel wachsen lassen und will deinen Mund unter ihnen auftun, daß sie erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Du Menschenkind, weissage und sprich: So spricht der Herr HERR: Heulet (und sprechet): 0 weh des Tages!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Denn der Tag ist nahe, ja, des HERRN Tag ist nahe, ein finsterer Tag; die Zeit ist da, daß die Heiden kommen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Und das Schwert soil uber Agypten kommen, und Mohrenland muli erschrecken, wenn die Erschlagenen in Agypten fallen werden, und ihr Volk weggefuhret und ihre Grundfesten umgerissen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Mohrenland und Libyen und Lydien mit allerlei Pobel und Chub und die aus dem Lande des Bundes sind, sollen samt ihnen durchs Schwert fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So spricht der HERR: Die Schutzherren Agyptens müssen fallen, und die Hoffart ihrer Macht muli herunter; von dem Turm zu Syene an sollen sie durchs Schwert fallen, spricht der Herr HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'und sollen, wie ihre wüste Grenze, wüst werden, und ihre Stadte unter andern wüsten Stadten wüst liegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'daß sie erfahren, daß ich der HERR sei, wenn ich ein Feuer in Agypten mache, daß alle, die ihnen helfen, zerstoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Zur selben Zeit werden Boten von mir ausziehen in Schiffen, Mohrenland zu schrecken, das jetzt so sicher ist, und wird ein Schrecken unter ihnen sein, gleichwie es Agypten ging, da ihre Zeit kam; denn siehe, es kommt gewifilich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So spricht der Herr HERR: Ich will die Menge in Agypten wegraumen durch Nebukadnezar, den Konig zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Denn er und sein Volk mit ihm, samt den Tyrannen der Heiden, sind herzugebracht, das Land zu verderben, und werden ihre Schwerter ausziehen wider Agypten, daß das Land allenthalben voll Erschlagener liege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Und ich will die Wasserstrome trocken machen und das Land bosen Leuten verkaufen und will das Land, und was drinnen ist, durch Fremde verwüsten. Ich, der HERR, hab es geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So spricht der Herr HERR: Ich will die Gotzen zu Noph ausrotten und die Abgotter vertilgen, und Agypten soil keinen Fürsten mehr haben; und will ein Schrecken in Agyptenland schicken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Ich will Pathros wüst machen und ein Feuer zu Zoan anzunden und das Recht uber No gehen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Ich will meinen Grimm ausschütten uber Sin, welche ist eine Festung Agyptens, und will die Menge zu No ausrotten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Ich will ein Feuer in Agypten anzunden, und Sin soil angst und bange werden; und No soil zerrissen und Noph taglich geangstet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Diejunge Mannschaftzu On und Bubasto sollen durchs Schwert fallen, und die Weiber gefangen weggefuhret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Tachpanheswird einen finstern Tag haben, wenn ich das Joch Agyptens schlagen werde, daß die Hoffart ihrer Macht darinnen ein Ende habe; sie wird mit Wolken bedeckt werden, und ihre Tochter werden gefangen weggefuhret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Und ich will das Recht uber Agypten gehen lassen, daß sie erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Und es begab sich im elften Jahr, am siebenten Tage des ersten Monden, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Du Menschenkind, ich will den Arm Pharaos, des Konigs in Agypten, zerbrechen; und siehe, ersoll nicht verbunden werden, daß er heilen moge, noch mit Binden zugebunden werden, daß er stark werde und ein Schwert fassen konne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Darum spricht der Herr HERR also: Siehe, ich will an Pharao, den Konig in Agypten, und will seine Arme zerbrechen, beide, den starken und den schwachen, daß ihm das Schwert aus seiner Hand entfallen muli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Und will die Agypter unter die Heiden zerstreuen und in die Lander verjagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Aber die Arme des Konigs zu Babel will ich starken und ihm mein Schwert in seine Hand geben; und will die Arme Pharaos zerbrechen, daß er vor ihm winseln soil wie ein todlich Verwundeter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Ja, ich will die Arme des Konigs zu Babel starken, daß die Arme Pharaos dahinfallen, auf daß sie erfahren, daß ich der HERR sei, wenn ich mein Schwert dem Konige zu Babel in die Hand gebe, daß er\'s liber Agyptenland zucke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'und ich die Agypter unter die Heiden zerstreue und in die Lander verjage, daß sie erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Und es begab sich im elften Jahr, am ersten Tage des dritten Monden, geschah des HERRN Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Du Menschenkind, sage zu Pharao, dem Konige zu Agypten, und zu all seinem Volk: Wem meinest du denn, daß du gleich seiest in deiner Herrlichkeit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Siehe, Assur war wie ein Zedernbaum auf dem Libanon, von schonen Asten und dick von Laub und sehr hoch, daß sein Wipfel hoch stund unter grolien, dicken Zweigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Die Wasser machten, daß er groli ward, und die Tiefe, daß er hoch wuchs. Seine Strome gingen rings urn seinen Stamm her und seine Bache zu alien Baumen im Felde:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Darum ist er hoher worden denn alle Baume im Felde und kriegte viel Aste und lange Zweige; denn er hatte Wassers genug, sich auszubreiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Alle Vogel des Himmels nisteten auf seinen Asten, und alle Tiere im Felde hatten Junge unter seinen Zweigen; und unter seinem Schatten wohneten alle grolien Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Er hatte schone grolie und lange Aste; denn seine Wurzeln hatten viel Wassers;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'und war ihm kein Zedernbaum gleich in Gottes Garten, und die Tannenbaume waren seinen Asten nicht zu gleichen, und die Kastanienbaume waren nichts gegen seine Zweige. Ja, er war so schon als kein Baum im Garten Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Ich hab ihn so schon gemacht, daß er so viel Aste kriegte, dafi ihn alle lustigen Baume im Garten Gottes neideten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Darum sprichtder Herr HERR also: Weil erso hoch worden ist, daß sein Wipfel stund unter groüen, hohen, dicken Zweigen, und sein Herz sich erhub, daß er so hoch war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'darum gab ich ihn dem Machtigsten unter den Heiden in die Hande, der mit ihm umginge und ihn vertriebe, wie er verdienet hat mit seinem gottlosen Wesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'daß Fremde ihn ausrotten sollten, namlich die Tyrannen der Heiden, und ihn zerstreuen, und seine Aste auf den Bergen und in alien Talern liegen mußten, und seine Zweige zerbrachen an alien Bachen im Lande, daß alle Volker auf Erden von seinem Schatten wegziehen mußten und ihn verlassen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'und alle Vogel des Himmels auf seinem umgefallenen Stamm saßen, und alle Tiere im Felde legten sich auf seine Aste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'auf daß sich forthin kein Baum am Wasser seiner Hohe erhebe, daß sein Wipfel unter großen, dicken Zweigen stehe, und kein Baum am Wasser sich erhebe uber die andern; denn sie müssen alle unter die Erde und dem Tode ubergeben werden, wie andere Menschen, die in die Grube fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So spricht der Herr HERR: Zu der Zeit, da er hinunter in die Holle fuhr, da machte ich ein Trauern, daß ihn die Tiefe bedeckte, und seine Strome stillstehen mußten; und die großen Wasser nicht laufen konnten, und machte, daß der Libanon urn ihn trauerte und alle Feldbaume verdorreten uber ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Ich erschreckte die Heiden, da sie ihn horeten fallen, da ich ihn hinunterstieß zur Holle mit denen, so in die Grube fahren. Und alle lustigen Baume unter der Erde, die edelsten und besten auf dem Libanon, und alle, die am Wasser gestanden waren, gonneten es ihm wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Denn sie mußten auch mit ihm hinunter zur Holle, zu den Erschlagenen mit dem Schwert, weil sie unter dem Schatten seines Arms gewohnet hatten unter den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Wie groß meinestdu denn, daß du (Pharao) seiest mit deiner Pracht und Herrlichkeit unter den lustigen Baumen? Denn du mußt mit den lustigen Baumen unter die Erde hinabfahren und unter den Unbeschnittenen liegen, so mit dem Schwert erschlagen sind. Also soil es Pharao gehen samt all seinem Volk, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Und es begab sich im zwolften Jahr, am ersten Tage des zwolften Monden, geschah des HERRN Wort zu mirund sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Du Menschenkind, mache eine Wehklage fiber Pharao, den Konig zu Agypten, und sprich zu ihm: Du bist gleichwie ein Lowe unter den Heiden und wie ein Meerdrache und springest in deinen Stromen und trubest das Wasser mit deinen Füßen und machst seine Strome trube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So spricht der Herr HERR: Ich will mein Netz fiber dich auswerfen durch einen großen Haufen Volks, die dich sollen in mein Gam jagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Und will dich aufs Land ziehen und aufs Feld werfen, daß alle Vogel des Himmels auf dir sitzen sollen, und alle Tiere auf Erden von dir satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Und will dein Aas auf die Berge werfen und mit deiner Hohe die Taler ausfüllen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Das Land, darin du schwimmest, will ich von deinem Blut rot machen bis an die Berge hinan, daß die Bache von dir voll werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Und wenn du nun gar dahin bist, so will ich den Himmel verhullen und seine Sterne verfinstern und die Sonne mit Wolken uberziehen, und der Mond soil nicht scheinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Alle Lichter am Himmel will ich fiber dir lassen dunkel werden und will eine Finsternis in deinem Lande machen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Dazu will ich vieler Volker Herz erschreckt machen, wenn ich die Heiden deine Plage erfahren lasse und viel Lander, die du nicht kennest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Viel Volker sollen sich fiber dir entsetzen, und ihren Konigen soil vordirgrauen, wenn ich mein Schwert wider sie blinken lasse, und sollen plotzlich erschrecken, daß ihnen das Herz entfallen wird fiber deinem Fall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Denn so spricht der Herr HERR: Das Schwert des Konigs zu Babel soil dich treffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Und ich will dein Volk fallen durch das Schwert der Heiden und durch allerlei Tyrannen der Heiden; die sollen die Herrlichkeit Agyptens verheeren, daß all ihr Volk vertilget werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Und ich will alle ihre Tiere umbringen an den großen Wassern, daß sie keines Menschen Fuß und keines Tieres Klauen trube machen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Alsdann will ich ihre Wasser lauter machen, daß ihre Strome fließen wie 01 spricht der Herr HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'wenn ich das Land Agypten verwüstet und alles, was im Lande ist, ode gemacht und alle, so drinnen wohnen, erschlagen habe, daß sie erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Das wird der Jammer sein, den man wohl mag klagen; ja, viel Tochter der Heiden werden solche Klage ffihren fiber Agypten und all ihr Volk wird man klagen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Und im zwolften Jahr, am funfzehnten Tage desselbigen Monden, geschah des HERRN Wort zu mirund sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Du Menschenkind, beweine das Volk in Agypten und stoße es mit den Tochtern der starken Heiden hinab unter die Erde zu denen, die in die Grube fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Wo ist nun deine Wollust? Hinunter, und lege dich zu den Unbeschnittenen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Sie werden fallen unter den Erschlagenen mit dem Schwert. Das Schwert ist schon gefalit und gezuckt uber ihr ganzes Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Davon werden sagen in der Holle die starken Helden mit ihren Gehilfen, die alle hinuntergefahren sind und liegen da unter den Unbeschnittenen und Erschlagenen vom Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Daselbst liegt Assur mit all seinem Volk umher begraben, die alle erschlagen und durchs Schwert gefallen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Ihre Graber sind tief in der Grube, und sein Volk liegt allenthalben umher begraben, die alle erschlagen und durchs Schwert gefallen sind, da sich die ganze Welt vor furchtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Da liegt auch Elam mit all seinem Haufen umher begraben, die alle erschlagen und durchs Schwert gefallen sind und hinuntergefahren als die Unbeschnittenen unter die Erde, davorsich auch alle Welt furchtete; und müssen ihre Schande tragen mit denen, die in die Grube fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Man hat sie unter die Erschlagenen gelegt samt all ihrem Haufen, und liegen umher begraben; und sind alle wie die Unbeschnittenen und die Erschlagenen vom Schwert, vor denen sich auch alle Welt furchten muf Jte; und mussen ihre Schande tragen mit denen, die in die Grube fahren, und unter den Erschlagenen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Da liegt Mesech und Thubal mit all ihrem Haufen umher begraben, die alle unbeschnitten und mit dem Schwert erschlagen sind, vor denen sich auch die ganze Welt furchten mulite,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'und alle andern Helden, die unter den Unbeschnittenen gefallen sind und mit ihrer Kriegswehre zur Holle gefahren und ihre Schwerter unter ihre Haupter haben mussen legen, und ihre Missetat uber ihre Gebeine kommen ist, die doch auch gefurchtete Helden waren in der ganzen Welt; also mussen sie liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'So mußt du freilich auch unter den Unbeschnittenen zerschmettert werden und unter denen, die mit dem Schwert erschlagen sind, liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Da liegt Edom mit seinen Konigen und all seinen Fursten unter den Erschlagenen mit dem Schwert und unter den Unbeschnittenen, samt andern, so in die Grube fahren, die doch machtig gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ja, es mussen alle Fursten von Mitternacht dahin und alle Zidonier, die mit den Erschlagenen hinabgefahren sind, und ihre schreckliche Gewalt ist zuschanden worden, und mussen liegen unter den Unbeschnittenen und denen, so mit dem Schwert erschlagen sind, und ihre Schande tragen samt denen, so in die Grube fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Diese wird Pharao sehen und sich trosten mit all seinem Volk, die unter ihm mit dem Schwert erschlagen sind, und mit seinem ganzen Heer, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Denn es soli sich auch einmal alle Welt vor mir furchten, dafi Pharao und alle seine Menge soil liegen unter den Unbeschnittenen und mit dem Schwert Erschlagenen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Du Menschenkind, predige wider dein Volk und sprich zu ihnen: Wenn ich ein Schwert uber das Land führen würde, und das Volk im Lande nahme einen Mann unter ihnen und machten ihn zu ihrem Wachter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'und er sahe das Schwert kommen uber das Land und bliese die Trommete und warnete das Volk:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'wer nun der Trommeten Hall horete und wollte sich nichtwarnen lassen, und das Schwert kame und nahme ihn weg, desselben Blut sei auf seinem Kopf;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'denn er hat der Trommeten Hall gehoret und hat sich dennoch nichtwarnen lassen; darum sei sein Blut auf ihm. Wer sich aber warnen lalit, der wird sein Leben davonbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Wo aber der Wachter sahe das Schwert kommen und die Trommete nicht bliese noch sein Volk warnete, und das Schwert kame und nahme etliche weg: dieselben würden wohl urn ihrer Sünde willen weggenommen, aber ihr Blut will ich von des Wachters Hand fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Und nun, du Menschenkind, ich habe dich zu einem Wachter gesetzt uber das Haus Israel, wenn du etwas aus meinem Munde horest, dafi du sie von meinetwegen warnen sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Wenn ich nun zu dem Gottlosen sage: Du Gottloser mußt des Todes sterben, und du sagst ihm solches nicht, dal J sich der Gottlose warnen lasse vor seinem Wesen, so wird wohl der Gottlose urn seines gottlosen Wesens willen sterben, aber sein Blut will ich von deiner Hand fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Warnest du aber den Gottlosen vor seinem Wesen, daß ersich davon bekehre, und ersich nicht will von seinem Wesen bekehren, so wird er urn seiner Sünde willen sterben, und du hast deine Seele errettet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Darum, du Menschenkind, sage dem Hause Israel: Ihrsprechet also: Unsere Sünden und Missetaten liegen auf uns, dafi wir darunter vergehen; wie konnen wir denn leben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'So sprich zu ihnen: So wahr als ich lebe; spricht der Herr HERR, ich habe keinen Gefallen am Tode des Gottlosen, sondern daß sich der Gottlose bekehre von seinem Wesen und lebe. So bekehret euch doch nun von eurem bosen Wesen! Warum wollt ihr sterben, ihr vom Hause Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Und du, Menschenkind, sprich zu deinem Volk: Wenn ein Gerechter Boses tut, so wird\'s ihm nicht helfen, dafi erfromm gewesen ist; und wenn ein Gottloser fromm wird, so soil\'s ihm nicht schaden, daß er gottlos gewesen ist. So kann auch der Gerechte nicht leben, wenn er sundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Denn wo ich zu dem Gerechten spreche, er soli leben, und er verlalit sich auf seine Gerechtigkeit und tut Boses, so soil all seiner Frommigkeit nicht gedacht werden, sondern ersoll sterben in seiner Bosheit, die er tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Und wenn ich zum Gottlosen spreche, ersoll sterben, und er bekehret sich von seiner Sunde und tut, was recht und gut ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'also daß der Gottlose das Pfand wiedergibt und bezahlet, was er geraubet hat, und nach dem Wort des Lebens wandelt, dafi er kein Boses tut, so soil er leben und nicht sterben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'und aller seiner Sünden; die er getan hat, soli nicht gedacht werden; denn er tut nun, was recht und gut ist; darumsoller leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Noch spricht dein Volk: Der HERR urteilet nicht recht, so sie doch unrecht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Denn wo der Gerechte sich kehret von seiner Gerechtigkeit und tut Boses, so stirbt erja billig darum;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'und wo sich der Gottlose bekehret von seinem gottlosen Wesen und tut, was recht und gut ist, so soil erja billig leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Noch sprechet ihr: Der HERR urteilet nicht recht, so ich doch euch vom Hause Israel einen jeglichen nach seinem Wesen urteile.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Und es begab sich im zwolften Jahr unsers Gefangnisses, am funften Tage des zehnten Monden, kam zu mir ein Entronnener von Jerusalem und sprach: Die Stadt istgeschlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Und die Hand des HERRN war uber mir des Abends, ehe der Entronnene kam, und tat mir meinen Mund auf, bis er zu mir kam des Morgens, und tat mir meinen Mund auf, also daß ich nicht mehr schweigen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Du Menschenkind, die Einwohner dieser Wüste im Lande Israel sprechen also: Abraham war ein einiger Mann und erbte dies Land; unser aber ist viel, so haben wir ja das Land billiger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Darum sprich zu ihnen: So spricht der Herr HERR: Ihr habt Blut gefressen und eure Augen zu den Gotzen aufgehoben und Blut vergossen; und ihr meinet, ihr wollet das Land besitzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ja, ihrfahret immerfort mit Morden und ubet Greuel, und einer schandet dem andern sein Weib, und meinet, ihr wollet das Land besitzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'So sprich zu ihnen: So spricht der Herr HERR: So wahr ich lebe, sollen alle, so in den Wüsten wohnen, durchs Schwert fallen, und was auf dem Felde ist, will ich den Tieren zu fressen geben; und die in Festungen und Hohlen sind, sollen an der Pestilenz sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Denn ich will das Land gar verwusten und seiner Hoffart und Macht ein Ende machen, dafi das Gebirge Israel so wust werde, daß niemand dadurchgehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Und sollen erfahren, daß ich der HERR bin, wenn ich das Land gar verwustet habe urn aller ihrer Greuel willen, die sie uben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Und du, Menschenkind, dein Volk redet wider dich an den Wanden und unter den Hausturen und spricht je einer zum andern: Lieber, kommt und lafit uns horen, was der HERR sage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Und sie werden zu dir kommen in die Versammlung und vordirsitzen als mein Volk und werden deine Worte horen, aber nichts danach tun, sondern werden dich anpfeifen und gleichwohl fortleben nach ihrem Geiz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Und siehe, du mußt ihr Liedlein sein, das sie gerne singen und spielen werden. Also werden sie deine Worte horen und nichts danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Wenn es aber kommt, was kommen soil, siehe, so werden sie erfahren, daß ein Prophet unter ihnen gewesen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Du Menschenkind, weissage wider die Hirten Israels, weissage und sprich zu ihnen: So spricht der Herr HERR: Wehe den Hirten Israels, die sich selbst weiden! Sollen nicht die Hirten die Herde weiden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Aber ihr fresset das Fette und kleidet euch mit der Wolle und schlachtet das Gemastete; aber die Schafe wollet ihr nicht weiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Der Schwachen wartet ihr nicht und die Kranken heilet ihr nicht, das Verwundete verbindet ihr nicht, das Verirrete holet ihr nicht und das Verlorene suchet ihr nicht, sondern streng und hart herrschet ihr uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Und meine Schafe sind zerstreuet, als die keinen Hirten haben, und alien wilden Tieren zur Speise worden und gar zerstreuet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'und gehen irre hin und wieder auf den Bergen und auf den hohen Hügeln und sind auf dem ganzen Lande zerstreuet, und ist niemand, der nach ihnen frage, Oder ihrer achte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Darum horet, ihr Hirten, des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'So wahr ich lebe, spricht der Herr HERR, weil ihr meine Schafe lasset zum Raube und meine Herde alien wilden Tieren zur Speise werden, weil sie keinen Hirten haben, und meine Hirten nach meiner Herde nicht fragen, sondern sind solche Hirten, die sich selbst weiden, aber meine Schafe wollen sie nicht weiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'darum, ihr Hirten, horet des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So spricht der Herr HERR: Siehe, ich will an die Hirten und will meine Herde von ihren Handen fordern; und will\'s mit ihnen ein Ende machen, daß sie nicht mehr sollen Hirten sein und sollen sich nicht mehr selbst weiden. Ich will meine Schafe erretten aus ihrem Maul, daß sie sie forthin nicht mehr fressen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Denn so spricht der Herr HERR: Siehe, ich will mich meiner Herde selbst annehmen und sie suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Wie ein Hirte seine Schafe suchet, wenn sie von seiner Herde verirret sind, also will ich meine Schafe suchen und will sie erretten von alien Ortern, dahin sie zerstreuet waren, zur Zeit, da es trübe und finster war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Ich will sie von alien Volkern ausführen und aus alien Landern versammeln und will sie in ihr Land führen; und will sie weiden auf den Bergen Israels und in alien Auen und auf alien Angern des Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Ich will sie auf die beste Weide führen, und ihre Hürden werden auf den hohen Bergen in Israel stehen; daselbst werden sie in sanften Hürden liegen und fette Weide haben auf den Bergen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ich will selbst meine Schafe weiden und ich will sie lagern, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Ich will das Verlorne wieder suchen und das Verirrete wiederbringen und das Verwundete verbinden und des Schwachen warten; und was fett und stark ist, will ich behüten, und will ihrer pflegen, wie es recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Aber zu euch, meine Herde, spricht der Herr HERR also: Siehe, ich will richten zwischen Schaf und Schaf und zwischen Widdern und Bocken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ist\'s nicht genug, dafi ihr so gute Weide habt und so überflüssig, daß ihr’s mit Füßen tretet, und so schone Borne zu trinken, so überflüssig, daß ihr dareintretet und sie trübe machet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'daß meine Schafe essen müssen, was ihr mit euren Füßen zertreten habt, und trinken, was ihr mit euren Füßen trübe gemacht habt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Darum so spricht der Herr HERR zu ihnen: Siehe, ich will richten zwischen den fetten und magern Schafen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'darum daß ihr lecket mit den Füßen und die Schwachen von euch stoßet mit euren Hornern, bis ihr sie alle von euch zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Und ich will meiner Herde helfen, da(S sie nicht mehr sollen zum Raube werden, und will richten zwischen Schaf und Schaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Und ich will ihnen einen einigen Hirten erwecken, der sie weiden soil, namlich meinen Knecht David. Der wird sie weiden und soil ihr Hirte sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Und ich, der HERR, will ihr Gott sein; aber mein Knecht David soli der Fürst unter ihnen sein. Das sage ich, der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Und ich will einen Bund des Friedens mit ihnen machen und alle bosen Tiere aus dem Lande ausrotten, daß sie sicher wohnen sollen in der Wuste und in den Waldern schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Ich will sie und alle meine Hugel umher segnen und auf sie regnen lassen zu rechter Zeit. Das sollen gnadige Regen sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'daß die Baume auf dem Felde ihre Fruchte bringen, und das Land sein Gewachs geben wird; und sie sollen sicher auf dem Lande wohnen und sollen erfahren, da(S ich der HERR bin, wenn ich ihr Joch zerbrochen und sie errettet habe von der Hand derer, denen sie dienen mußten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Und sie sollen nicht mehr den Heiden zum Raube werden, und kein Tier auf Erden soli sie mehr fressen, sondern sollen sicher wohnen ohne alle Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Und ich will ihnen eine beruhmte Pflanze erwecken, daß sie nicht mehr sollen Hunger leiden im Lande und ihre Schmach unter den Heiden nicht mehr tragen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Und sollen erfahren, da(S ich, der HERR, ihr Gott, bei ihnen bin, und daß sie vom Hause Israel mein Volk seien, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ja, ihr Menschen sollt die Herde meiner Weide sein, und ich will euer Gott sein, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Du Menschenkind, richte dein Angesicht wider das Gebirge Seir und weissage dawider');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'und sprich zum selbigen: So spricht der Herr HERR: Siehe, ich will an dich, du Berg Seir, und meine Hand wider dich ausstrecken und will dich gar wust machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Ich will deine Stadte ode machen, daß du sollst zur Wuste werden und erfahren, daß ich der HERR bin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'darum daß ihr ewige Feindschaft traget wider die Kinder Israel und triebet sie ins Schwert, da es ihnen ubel ging und ihre Sünde ein Ende hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Darum, so wahr ich lebe, spricht der Herr HERR, will ich dich auch blutend machen, und sollst dem Blute nicht entrinnen; weil du Lust zu Blut hast, sollst du dem Blute nicht entrinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Und ich will den Berg Seir wust und ode machen, daß niemand darauf wandeln noch gehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Und will sein Gebirge und alle Hugel, Taler und alle Gründe voll Toter machen, die durchs Schwert sollen erschlagen daßegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Ja, zu einer ewigen Wuste will ich dich machen, daß niemand in deinen Stadten wohnen soil, und sollt erfahren daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Und darum da(S du sprichst: Diese beiden Volker mit beiden Landern müssen mein werden und wirwollen sie einnehmen, obgleich der HERR da wohnet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'darum, so wahr ich lebe, spricht der Herr HERR, will ich nach deinem Zorn und Haß mit dir umgehen, wie du mit ihnen umgegangen bistaus lauterm Haß und will bei ihnen bekannt werden, wenn ich dich gestraft habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'und sollst erfahren, daß ich, der HERR, all dein Lastern gehoret habe, so du geredet hast wider das Gebirge Israel und gesagt: Sie sind verwustet und uns zu verderben gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Und habt euch wider mich geruhmet und heftig wider mich geredet; das hab\' ich gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So spricht nun der Herr HERR: Ich will dich zur Wüste machen, daß sich alles Land freuen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Und wie du dich gefreuet hast uber dem Erbe des Hauses Israel, darum daß es war wüst worden, ebenso will ich mit dir tun, daß der Berg Seir wüst sein muft samt dem ganzen Edom; und sollen erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Und du, Menschenkind, weissage den Bergen Israels und sprich: Horet des HERRN Wort, ihr Berge Israels!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So spricht der Herr HERR: Darum daß der Feind uber euch rühmet: Heh, die ewigen Hdhen sind nun unser Erbe worden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'darum weissage und sprich: So spricht der Herr HERR: Weil man euch allenthalben verwustet und vertilget, und seid den ubrigen Heiden zuteil worden und seid den Leuten ins Maul kommen und ein boses Geschrei worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'darum horet, ihr Berge Israels, das Wort des Herrn HERRN! So spricht der Herr HERR beide, zu den Bergen und Hügeln, zu den Bachen und Talern, zu den oden Wüsten und verlassenen Stadten, welche den ubrigen Heiden ringsumher zum Raub und Spott worden sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'ja, so spricht der Herr HERR: Ich hab\' in meinem feurigen Eifer geredet wider die ubrigen Heiden und wider das ganze Edom, welche mein Land eingenommen haben mit Freuden von ganzem Herzen und mit Hohnlachen, dasselbige zu verheeren und plundern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Darum weissage von dem Lande Israel und sprich zu den Bergen und Hügeln, zu den Bachen und Talern: So spricht der Herr HERR: Siehe, ich hab\' in meinem Eifer und Grimm geredet, weil ihr (solche) Schmach von den Heiden tragen müsset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Darum spricht der Herr HERR also: Ich hebe meine Hand auf, daü eure Nachbarn, die Heiden umher, ihre Schande wieder tragen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Aber ihr Berge Israels sollt wieder grünen und eure Frucht bringen meinem Volk Israel; und soil in kurzem geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Denn siehe, ich will mich wieder zu euch wenden und euch ansehen, daß ihr gebauet und besaet werdet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'und will bei euch der Leute viel machen, das ganze Israel allzumal; und die Stadte sollen wieder bewohnet und die Wüsten erbauet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Ja, ich will bei euch der Leute und des Viehes viel machen, daß ihr euch mehren und wachsen sollet. Und ich will euch wieder einsetzen, da ihrvorhin wohnetet; und will euch mehr Gutes tun denn zuvor je; und sollet erfahren, daß ich der HERR sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Ich will euch Leute herzubringen, die mein Volk Israel sollen sein, die werden dich besitzen; und sollst ihr Erbteil sein und sollst nicht mehr ohne Erben sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So spricht der Herr HERR: Weil man das von euch sagt: Du hast Leute gefressen und hast dein Volk ohne Erben gemacht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'darum sollst du (nun) nicht mehr Leute fressen, noch dein Volk ohne Erben machen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Und ich will dich nicht mehr lassen horen die Schmach der Heiden; und sollst den Spott der Heiden nicht mehr tragen und sollst dein Volk nicht mehr ohne Erben machen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Und des HERRN Wort geschah weiter zu mir:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Du Menschenkind, da das Haus Israel in ihrem Lande wohneten und dasselbige verunreinigten mit ihrem Wesen und T un, daß ihr Wesen vor mir war wie die Unreinigkeit eines Weibes in ihrer Krankheit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'da schüttete ich meinen Grimm uber sie aus urn des Bluts willen, das sie im Lande vergossen und dasselbe verunreiniget hatten durch ihre Gotzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Und ich zerstreuete sie unter die Heiden und zerstaubte sie in die Lander und richtete sie nach ihrem Wesen und Tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Und hielten sich wie die Heiden, dahin sie kamen, und entheiligten meinen heiligen Namen, daß man von ihnen sagte: 1st das des HERRN Volk, das aus seinem Lande hat müssen ziehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Aber ich verschonete urn meines heiligen Namens willen, welchen das Haus Israel entheiligte unter den Heiden, dahin sie kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Darum sollst du zum Hause Israel sagen: So spricht der Herr HERR: Ich tue es nicht urn euretwillen, ihrvom Hause Israel, sondern urn meines heiligen Namens willen, welchen ihr entheiliget habt unter den Heiden, zu welchen ihr kommen seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Denn ich will meinen groften Namen, der durch euch vor den Heiden entheiliget ist, den ihr unter denselbigen entheiliget habt, heilig machen. Und die Heiden sollen erfahren, daß ich der HERR sei, spricht der Herr HERR, wenn ich mich vor ihnen an euch erzeige, daß ich heilig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Denn ich will euch aus den Heiden holen und euch aus alien Landen versammeln und wieder in euer Land führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Und will rein Wasser uber euch sprengen, daß ihr rein werdet von aller eurer Unreinigkeit, und von alien euren Gotzen will ich euch reinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Und ich will euch ein neu Herz und einen neuen Geist in euch geben; und will das steinerne Herz aus eurem Fleisch wegnehmen und euch ein fleischern Herz geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ich will meinen Geist in euch geben und will solche Leute aus euch machen, die in meinen Geboten wandeln und meine Rechte halten und danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Und ihr sollet wohnen im Lande, das ich euren Vatern gegeben habe, und sollet mein Volk sein, und ich will euer Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Ich will euch von aller eurer Unreinigkeit losmachen und will dem Korn rufen und will es mehren und will euch keine Teurung kommen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Ich will die Fruchte auf den Baumen und das Gewachs auf dem Felde mehren, daß euch die Heiden nicht mehr spotten mit der Teurung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Alsdann werdet ihr an euer boses Wesen gedenken und eures Tuns, das nicht gut war, und wird euch eure Sünde und Abgotterei gereuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Solches will ich tun, nicht urn euretwillen, spricht der Herr HERR, daß ihr es wisset, sondern ihr werdet euch müssen schamen und schamrotwerden, ihr vom Hause Israel, uber eurem Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So spricht der Herr HERR: Zu der Zeit, wenn ich euch reinigen werde von alien euren Sünden, so will ich die Stadte wieder besetzen, und die Wusten sollen wieder gebauet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Das verwustete Land soil wieder gepfluget werden, dafur, daß es verheeret war, daß es sehen sollen alle, die dadurch gehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'und sagen: Dies Land war verheeret, und jetzt ist\'s wie ein Lustgarten, und diese Stadte waren zerstoret, ode und zerrissen und stehen nun test gebauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Und die ubrigen Heiden urn euch her sollen erfahren, daß ich der HERR bin, der da bauet, was zerrissen ist, und pflanzet, was verheeret war. Ich, der HERR, sage es und tue es auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So spricht der Herr HERR: Ich will mich wieder fragen lassen vom Hause Israel, daß ich mich an ihnen erzeige; und ich will sie mehren wie eine Menschenherde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Wie eine heilige Herde, wie eine Herde zu Jerusalem auf ihren Festen; so sollen die verheerten Stadte voll Menschenherden werden; und sollen erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Und des HERRN Hand kam uber mich und fuhrete mich hinaus im Geist des HERRN und stellete mich auf ein weit Feld, das voller Beine lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Und er fuhrete mich allenthalben dadurch. Und siehe, (des Gebeins) lag sehrviel auf dem Felde; und siehe, sie waren sehr verdorret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Und er sprach zu mir: Du Menschenkind, meinest du auch, daß diese Beine wieder lebendig werden? Und ich sprach: Herr HERR, dasweilit du wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Und er sprach zu mir: Weissage von diesen Beinen und sprich zu ihnen: Ihr verdorreten Beine, hdret des HERRN Wort!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So spricht der Herr HERR von diesen Gebeinen: Siehe, ich will einen Odem in euch bringen, daß ihr sollt lebendig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Ich will euch Adern geben und Fleisch lassen liber euch wachsen und mit Haut uberziehen; und will euch Odem geben, daß ihr wieder lebendig werdet; und sollt erfahren, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Und ich weissagte, wie mir befohlen war; und siehe, da rauschte es, als ich weissagte; und siehe, es regte sich! Und die Gebeine kamen wieder zusammen, ein jegliches zu seinem Gebein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Und ich sah, und siehe, es wuchsen Adern und Fleisch darauf, und er uberzog sie mit Haut; es war aber noch kein Odem in ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Und er sprach zu mir: Weissage zum Winde; weissage, du Menschenkind, und sprich zum Winde: So spricht der Herr HERR: Wind, komm herzu aus den vier Winden und blase diese Getoteten an, daß sie wieder lebendig werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Und ich weissagte, wie er mir befohlen hatte. Da kam Odem in sie, und sie wurden wieder lebendig und richteten sich auf ihre Fuße. Und ihrer war ein sehrgroß Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Und er sprach zu mir: Du Menschenkind, diese Beine sind das ganze Haus Israel. Siehe, jetzt sprechen sie: Unsere Beine sind verdorret, und unsere Hoffnung ist verloren, und ist aus mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Darum weissage und sprich zu ihnen: So spricht der Herr HERR: Siehe, ich will eure Graber auftun und will euch, mein Volk, aus denselben herausholen und euch ins Land Israel bringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'und sollt erfahren, daß ich der HERR bin, wenn ich eure Graber geoffnet und euch, mein Volk, aus denselben, gebracht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Und ich will meinen Geist in euch geben, daß ihr wieder leben sollt; und will euch in euer Land setzen, und sollt erfahren, daß ich der HERR bin. Ich rede es und tue es auch, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Du Menschenkind, nimm dir ein Holz und schreibe darauf: Des Juda und der Kinder Israel samt ihren Zugetanen. Und nimm noch ein Holz und schreibe darauf: Des Joseph, namlich das Holz Ephraim, und des ganzen Hauses Israel samt ihren Zugetanen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'und tue eins zum andern zusammen, daß ein Holz werde in deiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'So nun dein Volk zu dir wird sagen und sprechen: Willst du uns nicht zeigen, was du damit meinest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'so sprich zu ihnen: So spricht der Herr HERR: Siehe, ich will das Holz Josephs, welches ist in Ephraims Hand, nehmen, samt ihren Zugetanen, den Stammen Israels, und will sie zu dem Holz Judas tun und ein Holz daraus machen, und sollen eins in meiner Hand sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Und sollst also die Holzer, darauf du geschrieben hast, in deiner Hand halten, daß sie zusehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Und sollst zu ihnen sagen: So spricht der Herr HERR: Siehe, ich will die Kinder Israel holen aus den Heiden, dahin sie gezogen sind, und will sie allenthalben sammeln und will sie wieder in ihr Land bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Und will ein einig Volk aus ihnen machen im Lande auf dem Gebirge Israel, und sie sollen allesamt einen einigen Konig haben; und sollen nicht mehr zwei Volker noch in zwei Konigreiche zerteilet sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'sollen sich auch nicht mehr verunreinigen mit ihren Gotzen und Greueln und allerlei Sunden. Ich will ihnen heraushelfen aus alien Orten, da sie gesundiget haben, und will sie reinigen, und sollen mein Volk sein, und ich will ihr Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Und mein Knecht David soil ihr Konig und ihrer aller einiger Hide sein. Und sollen wandeln in meinen Rechten und meine Gebote halten und danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Und sie sollen wieder im Lande wohnen, das ich meinem Knechte Jakob gegeben habe, darinnen eure Vater gewohnet haben. Sie und ihre Kinder und Kindeskinder sollen darin wohnen ewiglich; und mein Knecht David soil ewiglich ihr Furst sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Und ich will mit ihnen einen Bund des Friedens machen, das soil ein ewiger Bund sein mit ihnen; und will sie erhalten und mehren, und mein Heiligtum soil unter ihnen sein ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Und ich will unter ihnen wohnen und will ihr Gott sein, und sie sollen mein Volk sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'dad auch die Heiden sollen erfahren, dad ich der HERR bin, der Israel heilig macht, wenn mein Heiligtum ewiglich unter ihnen sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Du Menschenkind, wende dich gegen Gog, der im Lande Magog ist und der oberste Furst ist in Mesech und Thubal, und weissage von ihm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'und sprich: So spricht der Herr HERR: Siehe, ich will an dich, Gog, der du der oberste Furst bist aus den Herren in Mesech und Thubal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Siehe, ich will dich herumlenken und will dir einen Zaum ins Maul legen und will dich herausführen mit all deinem Heer, Roß und Mann, die alle wohlgekleidet sind, und ist ihrer ein groüer Haute, die alle Tartschen und Schild und Schwert führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Du fuhrest mit dir Perser, Mohren und Libyer, die alle Schild und Helme führen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'dazu Gomer und all sein Heer samt dem Hause Thogarma, so gegen Mitternacht liegt, mit all seinem Heer; ja, du fuhrest ein groß Volk mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Wohlan, rüste dich wohl, du und alle deine Haufen, so bei dir sind; und sei du ihr Hauptmann!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Nach langer Zeit sollst du heimgesucht werden. Zur letzten Zeit wirst du kommen in das Land, das vom Schwert wiedergebracht und aus vielen Volkern zusammenkommen ist, namlich auf die Berge Israels, welche lange Zeit wüst gewesen sind und nun ausgeführet aus vielen Volkern und alle sicher wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Du wirst heraufziehen und daherkommen mit großem Ungestüm und wirst sein wie eine Wolke, das Land zu bedecken, du und all dein Heer und das große Volk mit dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So spricht der Herr HERR: Zu der Zeit wirst du dir solches vornehmen und wirst\'s bose im Sinn haben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'und gedenken: Ich will das Land ohne Mauern überfallen und uber die kommen, so still und sicher wohnen, als die alle ohne Mauern dasitzen und haben weder Riegel noch Tor,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'auf daß du rauben und plündern mogest und deine Hand lassen gehen uber die Verstorten, so wieder bewohnet sind, und uber das Volk, so aus den Heiden zusammengerafft ist und sich in die Nahrung und Guter geschickt hat und mitten im Lande wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Das Reicharabien, Dedan und die Kaufleute auf dem Meer und alle Gewaltigen, die daselbst sind, werden zu dir sagen: Ich meine ja, du seiest recht kommen zu rauben, und hast deine Haufen versammelt zu plundern, auf daß du wegnehmest Silber und Gold und sammelst Vieh und Guter und großen Raub treibest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Darum so weissage, du Menschenkind, und sprich zu Gog: So spricht der Herr HERR: Ist\'s nicht also, daß du wirst merken, wenn mein Volk Israel sicher wohnen wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'So wirst du kommen aus deinem Ort, namlich von den Enden gegen Mitternacht, du und ein groß Volk mit dir, alle zu Roß, ein großer Haufe und ein machtiges Heer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Und wirst heraufziehen uber mein Volk Israel wie eine Wolke, das Land zu bedecken. Solches wird zur letzten Zeit geschehen. Ich will dich aber darum in mein Land kommen lassen, auf daß die Heiden mich erkennen, wie ich an dir, o Gog, geheiliget werde vor ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So spricht der Herr HERR: Du bist\'s, von dem ich vorzeiten gesagt habe durch meine Diener, die Propheten in Israel, die zur selbigen Zeit weissagten, daß ich dich uber sie kommen lassen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Und es wird geschehen zur Zeit, wenn Gog kommen wird uber das Land Israel, spricht der Herr HERR, wird heraufziehen mein Zorn in meinem Grimm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Und ich rede solches in meinem Eifer und im Feuer meines Zorns. Denn zur selbigen Zeit wird groß Zittern sein im Lande Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'daß vor meinem Angesicht zittern sollen die Fische im Meer, die Vogel unter dem Himmel, das Vieh auf dem Felde und alles, was sich regt und wegt auf dem Lande, und alle Menschen, so auf der Erde sind; und sollen die Berge umgekehret werden, und die Wande und alle Mauern zu Boden fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Ich will aber uber ihn rufen das Schwert auf alien meinen Bergen, spricht der Herr HERR, daß eines jeglichen Schwert soil wider den andern sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Und ich will ihn richten mit Pestilenz und Biut und will regnen lassen Platzregen mit Schlolien, Feuer und Schwefel uber ihn und sein Heer und uber das grolie Volk, das mit ihm ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Also will ich denn herrlich, heilig und bekannt werden vor vielen Heiden, dafi sie erfahren sollen, daß ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Und du, Menschenkind, weissage wider Gog und sprich: Also spricht der Herr HERR: Siehe, ich will an dich, Gog, der du der oberste Furst bist in Mesech und Thubal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Siehe, ich will dich herumlenken und locken und aus den Enden von Mitternacht bringen und auf die Berge Israels kommen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Und will dir den Bogen aus deiner linken Hand schlagen und deine Pfeile aus deiner rechten Hand werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Auf den Bergen Israels sollst du niedergelegt werden, du mit all deinem Heer und mit dem Volk, das bei dir ist. Ich will dich den Vogeln, woher sie fliegen, und den Tieren auf dem Felde zu fressen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Du sollst auf dem Felde daniederliegen; denn ich, der Herr HERR, hab es gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Und ich will Feuer werfen uber Magog und uber die, so in den Inseln sicherwohnen; und sollen\'s erfahren, dafi ich der HERR bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Denn ich will meinen heiligen Namen kundmachen unter meinem Volk Israel und will meinen heiligen Namen nicht langer schanden lassen, sondern die Heiden sollen erfahren, daß ich der HERR bin, der Heilige in Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Siehe, es ist schon kommen und geschehen, spricht der Herr HERR; das ist der Tag, davon ich geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Und die Burger in den Stadten Israels werden herausgehen und Feuer machen und verbrennen die Waffen, Schilde, Tartschen, Bogen, Pfeile, Fauststangen und langen Spielie und werden sieben Jahre lang Feuerwerk damit halten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'daß sie nicht dürfen Holz auf dem Felde holen noch im Walde hauen, sondern von den Waffen werden sie Feuer halten; und sollen rauben, von denen sie beraubt sind, und plundern, von denen sie geplundert sind, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Und soil zu der Zeit geschehen, da will ich Gog einen Ort geben zum Begrabnis in Israel, namlich das Tal, da man gehet am Meergegen Morgen, also daß die, so vorubergehen, sich davor scheuen werden, weil man daselbst Gog mit seiner Menge begraben hat; und soli heilien Gogs Haufental.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Es wird sie aber das Haus Israel begraben sieben Monden lang, damit das Land gereiniget werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Ja, alles Volkim Landewird an ihnen zu begraben haben, und werden Ruhm davon haben, daß ich des Tages meine Herrlichkeit erzeiget habe, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Und sie werden Leute aussondern, die stets im Lande umhergehen und mit denselbigen die Totengraber, zu begraben die Ubrigen auf dem Lande, auf daß es gereiniget werde; nach sieben Monden werden sie forschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Und die, so im Lande umhergehen und etwa eines Menschen Bein sehen, werden dabei ein Mai aufrichten, bis es die Totengraber auch in Gogs Haufental begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'So soil auch die Stadt heißen Hamona. Also werden sie das Land reinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Nun, du Menschenkind, so spricht der Herr HERR: Sage alien Vogeln, woher sie fliegen, und alien Tieren auf dem Felde: Sammelt euch und kommt her! Findet euch allenthalben her zuhaufzu meinem Schlachtopfer, das ich euch schlachte, ein groli Schlachtopfer auf den Bergen Israels, und fresset Fleisch und saufet Blut!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Fleisch der Starken sollt ihr fressen und Blut der Fursten auf Erden sollt ihr saufen, der Widder, der Hammel, der Bocke, der Ochsen, die allzumal feist und wohlgemastet sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Und sollt das Fette fressen, daß ihr voll werdet, und das Blut saufen, daß ihrtrunken werdet von dem Schlachtopfer, das ich euch schlachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Sattiget euch nun uber meinem Tisch von Rossen und Reitern, von Starken und allerlei Kriegsleuten, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Und ich will meine Herrlichkeit unter die Heiden bringen, daß alle Heiden sehen sollen mein Urteil, das ich habe ergehen lassen, und meine Hand, die ich an sie gelegt habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'und also das Haus Israel erfahre, daß ich, der HERR, ihr Gott bin, von dem Tage und hinfurder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'und die Heiden erfahren, wie das Haus Israel urn seiner Missetat willen sei weggefuhret, und daß sie sich an mir versundiget hatten. Darum habe ich mein Angesicht vor ihnen verborgen und habe sie ubergeben in die Hande ihrer Widersacher, daß sie allzumal durchs Schwert fallen muliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Ich habe ihnen getan, wie ihre Sunde und Ubertreten verdienet haben, und also mein Angesicht vor ihnen verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Darum so spricht der Herr HERR: Nun will ich das Gefangnis Jakobs wenden und mich des ganzen Hauses Israel erbarmen und urn meinen heiligen Namen eifern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Sie aber werden ihre Schmach und alle ihre Sunde, damit sie sich an mir versundiget haben, tragen, wenn sie nun sicher in ihrem Lande wohnen, daß sie niemand schrecke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'und ich sie wieder aus den Volkern gebracht und aus den Landen ihrer Feinde versammelt habe und ich in ihnen geheiliget worden bin vor den Augen vieler Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Also werden sie erfahren, daß ich, der HERR, ihr Gott bin, der ich sie habe lassen unter die Heiden wegfuhren und wiederum in ihr Land versammeln und nicht einen von ihnen dort gelassen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Und will mein Angesicht nicht mehr vor ihnen verbergen; denn ich habe meinen Geist uber das Haus Israel ausgegossen, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Im fünfundzwanzigsten Jahr rinsers Gefangnisses, im Anfang des Jahres, am zehnten Tage des Monden, das ist das vierzehnte Jahr, nachdem die Stadt geschlagen war, eben am selbigen Tage kam des HERRN Hand uber mich und fuhrete mich daselbst hin');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'durch gottliche Gesichte, namlich ins Land Israel, und stellete mich auf einen sehr hohen Berg, darauf war es wie eine gebauete Stadt vom Mittag herwarts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Und da er mich daselbst hingebracht hatte, siehe, da war ein Mann, des Gestalt war wie Erz; der hatte eine leinene Schnur und eine Medrute in seiner Hand und stund unter dem Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Und ersprach zu mir: Du Menschenkind, siehe und hore fleidig zu und merke eben darauf, was ich dir zeigen will! Denn darum bist du hergebracht, dad ich dir solches zeige, auf dafi du solches alles, was du hie siehest, verkundigest dem Hause Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Und siehe, es ging eine Mauer auswendig am Hause ringsumher. Und der Mann hatte die Medrute in der Hand, die war sechs Ellen lang; eine jegliche Elle war eine Handbreit langer denn eine gemeine Elie. Und er mad das Gebaude in die Breite eine Rute und in die Hohe auch eine Rute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Und er kam zum Tor, das gegen Morgen lag, und ging hinauf auf seinen Stufen und mad die Schwellen am Tor, eine jegliche Schwelle eine Rute breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Und die Gemacher, so beiderseits neben dem Torwaren, mad erauch, nach der Lange eine Rute und nach der Breite eine Rute; und der Raum zwischen den Gemachern war fünf Ellen weit. Und er mad auch die Schwellen am Tor neben der Halle von inwendig eine Rute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Und er mad die Halle am Tor von inwendig eine Rute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Und mall die Halle am Tor acht Ellen und seine Erker zwo Ellen und die Halle von inwendig des Tors.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Und der Gemacher waren auf jeglicher Seite drei am Tor gegen Morgen, je eins so weit als das andere; und stunden auf beiden Seiten Erker, die waren gleich grod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Danach mad er die Weite der Tur im Tor, namlich zehn Ellen, und die Lange des Tors dreizehn Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Und vorne an den Gemachern war Raum auf beiden Seiten, je einer Elle; aber die Gemacher waren je sechs Ellen auf beiden Seiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Dazu mad er das Tor vom Dache des Gemachs bis zu des Tors Dach, fünfundzwanzig Ellen breit; und eine Tur stund gegen der andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Ermachte auch Erker sechzig Ellen und vor jeglichem Erker einen Vorhof am Tor ringsherum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Und bis an die Halle am innern Tor, da man hineingehet, waren funfzig Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Und es waren enge Fensterlein an den Gemachern und Erkern hineinwarts, am Tor ringsumher. Also waren auch Fenster inwendig an den Hallen herum, und an den Erkern umher war Palmlaubwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Und er fuhrete mich weiterzum audern Vorhof; und siehe, da waren Kammern und ein Pflaster gemacht im Vorhof herum und dreidig Kammern auf dem Pflaster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Und es war das hohere Pflaster an den Toren, so lang die Tore waren, am niedrigen Pflaster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Und er mad die Breite des untern Tors vor dem innern Hofe, auswendig hundert Ellen, beide, gegen Morgen und Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Also mad er auch das Tor, so gegen Mitternacht lag, am audern Vorhofe, nach der Lange und Breite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Das hatte auch auf jeder Seite drei Gemacher und hatte auch seine Erker und Hallen, gleich so grod wie am vorigen Tor, funfzig Ellen die Lange und funfundzwanzig Ellen die Breite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Und hatte auch seine Fenster und seine Hallen und sein Palmlaubwerk, gleichwie das Tor gegen Morgen; und hatte sieben Stufen, da man hinaufging, und hatte seine Halle davor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Und es war das Tor am innern Vorhof gegen das Tor, so gegen Mitternacht und Morgen stund; und mad hundert Ellen von einem Tor zum andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Danach fuhrete er mich gegen Mittag, und siehe, da war auch ein Tor gegen Mittag; und er mad seine Erker und Hallen, gleich als die andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Die hatten auch Fenster und Halien umher, gleichwie jene Fenster, funfzig Ellen lang und funfundzwanzig Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Und waren auch sieben Stufen hinauf und eine Halle davor und Palmlaubwerk an seinen Erkern auf jeglicher Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Und er mad auch das Tor am innern Vorhof gegen Mittag, namlich hundert Ellen von dem einen Mittagstor zum andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Und er fuhrete mich weiter durch das Mittagstor in den innern Vorhof; und mad dasselbe Tor gegen Mittag, gleich so grod wie die andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'mit seinen Gemachern, Erkern und Hallen und mit Fenstern und Hallen daran, ebenso grod wie jene umher, funfzig Ellen lang und funfundzwanzig Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Und es ging eine Halle herum, funfundzwanzig Ellen lang und funf Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Dieselbige stund vorne gegen den audern Vorhof und hatte auch Palmlaubwerk an den Erkern; es waren aber acht Stufen hinaufzugehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Danach fuhrete er mich zum innern Tor gegen Morgen und mats dasselbige, gleich so groß wie die andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'mit seinen Gemachern, Erkern und Hallen und ihren Fenstern und Hallen umher, gleich so groß wie die andern, funfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Und hatte auch eine Halle gegen den außern Vorhof und Palmlaubwerk an den Erkern zu beiden Seiten und acht Stufen hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Danach fuhrete er mich zum Tor gegen Mitternacht; das mats er, gleich so groß wie die andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'mit seinen Gemachern, Erkern und Hallen und ihren Fenstern und Hallen umher, funfzig Ellen lang und fünfundzwanzig Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Und hatte auch eine Halle gegen den auliern Vorhof und Palmlaubwerk an den Erkern zu beiden Seiten und acht Stufen hinauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Und unten an den Erkern an jedem Tor war eine Kammer mit einer Tur, darin man das Brandopfer wusch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Aber in der Halle vor dem Tor stunden auf jeglicher Seite zween Tische, darauf man die Brandopfer, Sundopfer und Schuldopfer schlachten sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Und herauswarts zur Seite, da man hinaufgehet zum Tor, gegen Mitternacht, stunden auch zween Tische und an der andern Seite unter der Halle des Tors auch zween Tische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Also stunden auf jeder Seite vor dem Tor vier Tische; das sind acht Tische zuhauf, darauf man schlachtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Und die vier Tische, zum Brandopfer gemacht, waren aus gehauenen Steinen, je anderthalb Ellen lang und breit und einer Elle hoch, darauf man legte allerlei Gerate, damit man Brandopfer und andere Opfer schlachtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Und es gingen Leisten herum, hineinwarts gebogen, einer Querhand hoch. Und auf die Tische sollte man das Opferfleisch legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Und autien vor dem innern Tor waren Kammern fur die Sanger im innern Vorhofe: eine an der Seite, neben dem Tor zur Mitternacht, die sah gegen Mittag; die andere zur Seite gegen Morgen, die sah gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Und er sprach zu mir: Die Kammer gegen Mittag gehort den Priestern, die im Hause dienen sollen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'aber die Kammer gegen Mitternacht gehort den Priestern, so auf dem Altar dienen. Dies sind die Kinder Zadoks, welche allein unter den Kindern Levi vor den HERRN treten sollen, ihm zu dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Und er maß den Platz im Hause, namlich hundert Ellen lang und hundert Ellen breit ins Gevierte; und der Altar stund eben vorne vor dem Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Und er fuhrete mich hinein zur Halle des Tempels und maß die Halle, fünf Ellen auf jeder Seite, und das Tordrei Ellen weit auf jeder Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Aber die Halle war zwanzig Ellen lang und elf Ellen weit und hatte Stufen, da man hinaufging; und Pfeiler stunden unten an den Erkern, auf jeder Seite eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Und er fuhrete mich hinein in den Tempel und maß die Erker an den Wanden; die waren zu jeder Seite sechs Ellen weit, so weit das Haus war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Und die Tur war zehn Ellen weit, aber die Wande zu beiden Seiten an der Tur waren jede funf Ellen breit. Und er maß den Raum im Tempel; der hatte vierzig Ellen in die Lange und zwanzig Ellen in die Breite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Und er ging inwendig hinein und maß die Tur, zwo Ellen; und die Tur hatte sechs Ellen und die Weite der Tur sieben Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Und er maß zwanzig Ellen in die Lange und zwanzig Ellen in die Breite am Tempel. Und er sprach zu mir: Dies ist das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Und er maß die Wand des Hauses, sechs Ellen hoch; darauf waren Gange allenthalben herum, geteilt in Gemacher, die waren allenthalben vier Ellen weit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Und derselben Gemacher waren auf jeder Seite dreiunddreißig, je eins an dem andern; und stunden Pfeiler unten bei den Wanden am Hause allenthalben herum, die sie trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Und uber diesen waren noch mehr Gange umher, und oben waren die Gange weiter, daß man aus den untern in die mittlern und aus den mittlern in die obersten ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Und stund je einer sechs Ellen uber dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Und die Weite der obern Gange war funf Ellen, und die Pfeiler trugen die Gange am Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Und es warje von einer Wand am Hause zu der andern zwanzig Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Und es waren zwo Turen an der Schnecke hinauf, eine gegen Mitternacht, die andere gegen Mittag; und die Schnecke war funf Ellen weit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Und die Mauer gegen Abend war funfundsiebenzig Ellen breit und neunzig Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Und er maß die Lange des Hauses, die hatte durchaus hundert Ellen, die Mauer und was daran war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Und die Weite vorne am Hause gegen Morgen mit dem, was daran hing, war auch hundert Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Und er maß die Lange des Gebaudes mit allem, was daran hing, von einer Ecke bis zur andern; das war auf jeder Seite hundert Ellen mit dem innern Tempel und Hallen im Vorhofe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'samtden Türen, Fenstern, Ecken und den dreien Gangen und Tafelwerk allenthalben herum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Er maß auch, wie hoch von der Erde bis zu den Fenstern war, und wie breit die Fenster sein sollten; und maß vom Tor bis zum Allerheiligsten, auswendig und inwendig herum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Und am ganzen Hause herum, von unten an bis oben hinauf an der Tur und an den Wanden, waren Cherubim und Palmlaubwerk unterdie Cherubim gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Und ein jeder Cherub hatte zween Kopfe, auf einer Seite wie ein Menschenkopf, auf der andern Seite wie ein Lowenkopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Vom Boden an bis hinauf uber die Tur waren die Cherubim und die Palmen geschnitzet, desgleichen an der Wand des Tempels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Und die Tur im Tempel war viereckig, und war alles artig ineinandergefuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Und der hdlzeme Altar war drei Ellen hoch und zwo Ellen lang und breit; und seine Ecken und alle seine Seiten waren holzern. Und er sprach zu mir: Das ist der Tisch, dervordem HERRN stehen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Und die Tur, beide, am Tempel und am Allerheiligsten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'hatte zwei Blatter, die man auf und zu tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Und waren auch Cherubim und Palmlaubwerk daran, wie an den Wanden. Und davor waren starke Riegel, gegen der Halle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Und waren enge Fenster und viel Palmlaubwerks herum an der Halle und an den Wanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Und erfuhrete mich hinaus zum außern Vorhof gegen Mitternacht unter die Kammern, so gegen dem Gebaude, das am Tempel hing, und gegen dem Tempel zu Mitternacht lagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'welcher Platz hundert Ellen lang war von dem Tor an gegen Mitternacht und funfzig Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Zwanzig Ellen waren gegen dem innern Vorhof und gegen dem Pflaster im außern Vorhof und dreißig Ellen von einer Ecke zur andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Und inwendig vor den Kammern war ein Platz zehn Ellen breit vor den Turen der Kammern, das lag alles gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Und uber diesen Kammern waren andere, engere Kammern; denn der Raum auf den untern und mittlern Kammern war nicht groß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Denn es war drei Gemacher hoch, und hatten doch keine Pfeiler, wie die Vorhofe Pfeiler hatten, sondern sie waren schlecht aufeinandergesetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Und der außere Vorhof war umfangen mit einer Mauer, daran die Kammern stunden; die war funfzig Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Und die Kammern stunden nacheinander, auch funfzig Ellen lang, am außern Vorhofe; aber der Raum vor dem Tempel war hundert Ellen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Und unten vor den Kammern war ein Platz gegen Morgen, da man aus dem außern Vorhof ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Und an der Mauer von Morgen an waren auch Kammern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Und war auch ein Platz davor, wie vorjenen Kammern, gegen Mitternacht; und war alles gleich mit der Lange, Breite und allem, was daran war, wie droben an jenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Und gegen Mittag waren auch eben solche Kammern mit ihren Turen; und vor dem Platz war die Tur gegen Mittag, dazu man kommt von der Mauer, die gegen Morgen liegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Und er sprach zu mir: Die Kammern gegen Mitternacht und die Kammern gegen Mittag gegen dem Tempel, die gehoren zum Heiligtum, darin die Priester essen, wenn sie dem HERRN opfern das allerheiligste Opfer. Und sollen die allerheiligsten Opfer, namlich Speisopfer, Sundopfer und Schuldopfer, daselbst hineinlegen; denn es isteine heilige Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Und wenn die Priester hineingehen, sollen sie nicht wieder aus dem Heiligtum gehen in den außern Vorhof, sondern sollen zuvor ihre Kleider, darin sie gedienet haben, in denselbigen Kammern weglegen, denn sie sind heilig; und sollen ihre andern Kleider anlegen und alsdann heraus unter das Volk gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Und da erdas Haus inwendig gargemessen hatte, fuhrete er mich heraus zum Tor gegen Morgen und maß von demselbigen allenthalben herum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Gegen Morgen maß er funfhundert Ruten lang');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'und gegen Mitternacht maß er auch funfhundert Ruten lang,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'desgleichen gegen Mittag auch funfhundert Ruten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Und da erkam gegen Abend, maß er auch funfhundert Ruten lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Also hatte die Mauer, die er gemessen, ins Gevierte auf jeder Seite herum funfhundert Ruten, damit das Heilige von dem Unheiligen unterschieden ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Und erfuhrete mich wieder zum Tor gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Und siehe, die Herrlichkeit des Gottes Israels kam von Morgen und brausete, wie ein groß Wasser brauset; und es ward sehr licht auf der Erde von seiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Und war eben wie das Gesicht, das ich gesehen hatte am Wasser Chebar, da ich kam, daß die Stadt sollte zerstoret werden. Da fiel ich nieder auf mein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Und die Herrlichkeit des HERRN kam hinein zum Hause durchs Tor gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Da hub mich ein Wind auf und brachte mich in den innern Vorhof; und siehe, die Herrlichkeit des HERRN erfullete das Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Und ich horete einen mit mir reden vom Hause heraus. Und ein Mann stund neben mir,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'der sprach zu mir: Du Menschenkind, das ist der Ort meines Throns und die Statte meiner Fußsohlen, darin ich ewiglich will wohnen unter den Kindern Israel. Und das Haus Israel soil nicht mehr meinen heiligen Namen verunreinigen, weder sie noch ihre Konige, durch ihre Hurerei und durch die Leichen ihrer Konige in ihren Hohen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'welche ihre Schwelle an meine Schwelle und ihre Pfosten an meine Pfosten gesetzt haben, dafi nur eine Wand zwischen mir und ihnen war, und haben also meinen heiligen Namen verunreiniget durch ihre Greuel, die sie taten, darum ich sie auch in meinem Zorn verzehret habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nun aber sollen sie ihre Hurerei und die Leichen ihrer Konige feme von mirwegtun; und ich will ewiglich unter ihnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Und du, Menschenkind, zeige dem Hause Israel den Tempel an, dafi sie sich schamen ihrer Missetat, und laß sie ein reinlich Muster davon nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Und wenn sie sich nun alles ihres Tuns schamen, so zeige ihnen die Weise und Muster des Hauses und seinen Ausgang und Eingang und alle seine Weise und alle seine Sitten und alle seine Weise und alle seine Gesetze und schreibe es ihnen vor, daß sie alle seine Weise und alle seine Sitten halten und danach tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Das soil aber das Gesetz des Hauses sein: Auf der Hohe des Berges, soweit es umfangen hat, soli es das Allerheiligste sein; das ist das Gesetz des Hauses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Dies ist aber das Mali des Altars nach der Elle, welche einer Hand breit langer ist denn eine gemeine Elle: Sein Fufi ist eine Elle hoch und eine Elle breit; und der Altar reicht hinauf bis an den Rand, der ist eine Spanne breit umher; und das ist seine Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Und von dem Fuß auf der Erde bis an den untern Absatz sind zwo Ellen hoch und eine Elle breit; aber von demselben kleinem Absatz bis an den großern Absatz sind\'s vier Ellen hoch und eine Elle breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Und der Harel vier Ellen hoch und vom Ariel uberwarts vier Horner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Der Ariel war aber zwolf Ellen lang und zwolf Ellen breit ins Gevierte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Und der oberste Absatz war vierzehn Ellen lang und vierzehn Ellen breit ins Gevierte; und ein Rand ging allenthalben umher, einer halben Elle breit; und sein Fuß war eine Elle hoch, und seine Stufen waren gegen Morgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Und ersprach zu mir: Du Menschenkind, so spricht der Herr HERR: Dies sollen die Sitten des Altars sein des Tages, da er gemacht ist, daß man Brandopfer darauf lege und das Blut darauf sprenge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Und den Priestern von Levi aus dem Samen Zadok, die da vor mich treten, daß sie mir dienen, spricht der Herr HERR, sollst du geben einen jungen Farren zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Und von desselben Blut sollst du nehmen und seine vier Horner damit besprengen und die vier Ecken an dem obersten Absatz und urn die Leisten herum; damit sollst du ihn entsundigen und versohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Und sollst den Farren des Sundopfers nehmen und ihn verbrennen an einem Ort im Hause, das dazu verordnet ist, außerdem Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Aber am andern Tage sollst du einen Ziegenbock opfern, der ohne Wandel sei, zu einem Sundopfer und den Altar damit entsundigen, wie er mit dem Farren entsundiget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Und wenn das Entsundigen vollendet ist, sollst du einen jungen Farren opfern, der ohne Wandel sei, und einen Widder von der Herde ohne Wandel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Und sollst sie beide vor dem HERRN opfern; und die Priester sollen Salz darauf streuen und sollen sie also opfern dem HERRN zum Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Also sollst du sieben Tage nacheinander taglich einen Bock zum Sundopfer opfern; und sie sollen einen jungen Farren und einen Widder von der Herde, die beide ohne Wandel sind, opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Und sollen also sieben Tage lang den Altar versohnen und ihn reinigen und seine Hande fullen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Und nach denselben Tagen sollen die Priester am achten Tage und hernach fur und fur auf dem Altar opfern eure Brandopfer und eure Dankopfer, so will ich euch gnadig sein, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Und erfuhrete mich wiederum zu dem Tor des außern Heiligtums gegen Morgen; es war aber zugeschlossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Und der HERR sprach zu mir: Dies Tor soil zugeschlossen bleiben und nicht aufgetan werden; und soil niemand da durch gehen, ohne allein der HERR, der Gott Israels, soil dadurchgehen; und soil zugeschlossen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Doch den Fursten ausgenommen; denn der Fürst soil darunter sitzen, das Brot zu essen vor dem HERRN; durch die Halle soil er hineingehen und durch dieselbige wieder herausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Danach fuhrete er mich zum Tor gegen Mitternacht vor das Haus; und ich sah, und siehe, des HERRN Haus ward voll der Herrlichkeit des HERRN; und ich fiel auf mein Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Und der HERR sprach zu mir: Du Menschenkind, merke eben darauf und siehe und hore fleißig auf alles, was ich dir sagen will von alien Sitten und Gesetzen im Hause des HERRN; und merke eben, wie man hineingehen soil, und auf alle Ausgange des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Und sage dem ungehorsamen Hause Israel: So spricht der Herr HERR: Ihr macht\'s zu viel, ihr vom Hause Israel, mit alien euren Greueln;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'denn ihr fuhret fremde Leute, eines unbeschnittenen Herzens und unbeschnittenen Fleisches, in mein Heiligtum, dadurch ihr mein Haus entheiliget, wenn ihr mein Brot, Fettes und Blut opfert, und brechet also meinen Bund mit alien euren Greueln');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'und haltet die Sitten meines Heiligtums nicht, sondern macht euch selbst neue Sitten in meinem Heiligtum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Darum spricht der Herr HERR also: Es soil kein Fremder eines unbeschnittenen Herzens und unbeschnittenen Fleisches in mein Heiligtum kommen aus alien Fremdlingen, so unterden Kindern Israel sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'ja, auch nicht die Leviten, die von mirgewichen sind und samt Israel von mir irregegangen nach ihren Gotzen. Darum sollen sie ihre Sünde tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Sie sollen aber in meinem Heiligtum an den Amtern, den Turen des Hauses und dem Hause dienen und sollen nur das Brandopfer und andere Opfer, so das Volk herzubringet, schlachten und vor den Priestern stehen, daß sie ihnen dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Darum daß sie jenen gedienet vor ihren Gotzen und dem Hause Israel ein Argernis zur Sunde gegeben haben, darum hab ich meine Hand uber sie ausgestreckt, spricht der Herr HERR, dafi sie müssen ihre Sunde tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Und sollen nicht zu mirnahen, Priesteramt zu führen, noch kommen zu einigem meinem Heiligtum, zu dem Allerheiligsten, sondern sollen ihre Schande tragen und ihre Greuel, die sie geübt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Darum hab ich sie zu Hutern gemacht an allem Dienst des Hauses und zu allem, das man drin tun soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Aber die Priester aus den Leviten, die Kinder Zadoks, so die Sitten meines Heiligtums gehalten haben, da die Kinder Israel von mirabfielen, die sollen vor mich treten und mir dienen und vor mir stehen, daß sie mir das Fette und Blut opfern, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Und sie sollen hineingehen in mein Heiligtum und vor meinen Tisch treten, mir zu dienen und meine Sitten zu halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Und wenn siedurch die Tore des innern Vorhofs gehen wollen, sollen sie leinene Kleider anziehen und nichts Wollenes anhaben, weil sie in den Toren im innern Vorhofe dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Und sollen leinenen Schmuck auf ihrem Haupt haben und leinen Niederkleid urn ihre Lenden; und sollen sich nicht im Schweiß, gürten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Und wenn sie etwa zu einem außern Vorhof zum Volk herausgehen, sollen sie die Kleider, darin sie gedienet haben, ausziehen und dieselben in die Kammern des Heiligtums legen und andere Kleider anziehen und das Volk nicht heiligen in ihren eigenen Kleidern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ihr Haupt sollen sie nicht bescheren und sollen auch nicht die Haare frei wachsen lassen, sondern sollen die Haare umherverschneiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Und soli auch kein Priester keinen Wein trinken, wenn sie in den innern Vorhof gehen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Und sollen keine Witwe noch Verstoßene zur Ehe nehmen, sondern Jungfrauen vom Samen des Hauses Israel, Oder eines Priesters nachgelassene Witwe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Und sie sollen mein Volk lehren, daß sie wissen Unterschied zu halten zwischen Heiligem und Unheiligem und zwischen Reinem und Unreinem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Und wo eine Sache vor sie kommt, sollen sie stehen und richten und nach meinen Rechten sprechen und meine Gebote und Sitten halten und alle meine Feste halten und meine Sabbate heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Und sollen zu keinem Toten gehen und sich verunreinigen, ohne allein zu Vater und Mutter, Sohn Oder Tochter, Bruder Oder Schwester, die noch keinen Mann gehabt habe; fiber denen mogen sie sich verunreinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Und nach seiner Reinigung soil man ihm zahlen sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Und wenn er wieder hinein zum Heiligtum gehet in den innern Vorhof, dafi er im Heiligtum diene, so soil er sein Sundopfer opfern, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Aber das Erbteil, das sie haben sollen, das will ich selbst sein. Darum sollt ihr ihnen kein eigen Land geben in Israel; denn ich bin ihr Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Sie sollen ihre Nahrung haben vom Speisopfer, Sundopfer und Schuldopfer, und alles Verbannte in Israel soil ihr sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Und alle ersten Fruchte und Erstgeburt von alien Hebopfern sollen der Priester sein. Ihr sollt auch den Priestern die Erstlinge geben von allem, das man isset, damit der Segen in deinem Hause bleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Was aber ein Aas Oder zerrissen ist, es sei von Vogeln Oder Tieren, das sollen die Priester nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Wenn ihr nun das Land durchs Los austeilet, so sollt ihr ein Hebopfer vom Lande absondern, das dem HERRN heilig sein soil, fünfundzwanzigtausend (Ruten) lang und zehntausend breit. Der Platz soil heilig sein, soweit er reicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Und von diesem sollen zum Heiligtum kommen je fünfhundert (Ruten) ins Gevierte und dazu ein freier Raum umher fünfzig Ellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Und auf demselben Platz, der fünfundzwanzigtausend Ruten lang und zehntausend breit ist, soil das Heiligtum stehen und das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Das übrige aber vom geheiligten Lande soil den Priestern gehoren, die im Heiligtum dienen und vor den HERRN treten, ihm zu dienen, dafi sie Raum zu Hausern haben, und soil auch heilig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Aber die Leviten, so vor dem Hause dienen, sollen auch fünfundzwanzigtausend (Ruten) lang und zehntausend breit haben zu ihrem Teil zu zwanzig Kammern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Und der Stadt sollt ihr auch einen Platz lassen fur das ganze Haus Israel, fünftausend (Ruten) breit und fünfundzwanzigtausend lang, neben dem abgesonderten Platz des Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Dem Fursten aber sollt ihr auch einen Platz geben zu beiden Seiten zwischen dem Platz der Priester und zwischen dem Platz der Stadt, gegen Abend und gegen Morgen; und sollen beide gegen Morgen und gegen Abend gleich lang sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Das soil sein eigen Teil sein in Israel, damit meine Fursten nicht mehr meinem Volk das Ihre nehmen, sondern sollen das Land dem Hause Israel lassen fur ihre Stamme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Denn so spricht der Herr HERR: Ihr habt es lange genug gemacht, ihr Fursten Israels; lafit ab vom Frevel und Gewalt und tut, was recht und gut ist, und tut ab von meinem Volk euer Austreiben, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Ihr sollt recht Gewicht und rechte Scheffel und recht Mali haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Epha und Bath sollen gleich sein, daß ein Bath das zehnte Teil vom Homer habe und das Epha auch das zehnte Teil vom Homer; denn nach dem Homer soil man sie beide messen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Aber ein Sekel soil zwanzig Gera haben; und eine Mina macht zwanzig Sekel, fünfundzwanzig Sekel und funfzehn Sekel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Das soil nun das Hebopfer sein, das ihr heben sollt, namlich das sechste Teil eines Epha von einem Homer Weizen und das sechste Teil eines Epha von einem Homer Gerste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Und vom 01 sollt ihr geben einen Bath, namlich je den zehnten Bath vom Kor und den zehnten vom Homer; denn zehn Bath machen einen Homer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Und je ein Lamm von zweihundert Schafen aus der Herde auf der Weide Israels zum Speisopfer und Brandopfer und Dankopfer, zur Versohnung fur sie, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Alles Volk im Lande soil solch Hebopfer zum Fursten in Israel bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Und der Fürst soil sein Brandopfer, Speisopfer und Trankopfer opfern auf die Feste, Neumonden und Sabbate und auf alle hohen Feste des Hauses Israel, dazu Sundopfer und Speisopfer, Brandopfer und Dankopfer tun zur Versohnung fur das Haus Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So spricht der Herr HERR: Am ersten Tage des ersten Monden sollst du nehmen einen jungen Farren, der ohne Wandel sei, und das Heiligtum entsundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Und der Priester soli von dem Blut des Sundopfers nehmen und die Pfosten am Hause damit besprengen und die vier Ecken des Absatzes am Altar samt den Pfosten am Tor des innern Vorhofs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Also sollst du auch tun am siebenten Tage des Monden, wo jemand geirret hat Oder verfuhret ist, daß, ihr das Haus entsundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Am vierzehnten Tage des ersten Monden sollt ihr das Passah halten und sieben Tage feiern und ungesauert Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Und am selbigen Tage soil der Furst fur sich und fur alles Volk im Lande einen Farren zum Sundopfer opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Aber die sieben Tage des Festes soli er dem HERRN taglich ein Brandopfer tun, je sieben Farren und sieben Widder, die ohne Wandel seien, und je einen Ziegenbock zum Sundopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Zum Speisopfer aber soli er je ein Epha zu einem Farren und ein Epha einem Widder opfern und je ein Hin Ols zu einem Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Am fünfzehnten Tage des siebenten Monden soil er sieben Tage nacheinander feiern, gleichwie jene sieben Tage, und ebenso halten mit Sundopfer, Brandopfer, Speisopfer samt dem 01.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So spricht der Herr HERR: Das Tor am innern Vorhofe gegen morgenwarts soil die sechs Werktage zugeschlossen sein; aber am Sabbattage und am Neumonden soil man\'s auftun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Und der Fürst soil auswendig unter die Halle des Tors treten und drauften bei den Pfosten am Tor stehenbleiben. Und die Priester sollen sein Brandopfer und Dankopfer opfern; er aber soil auf der Schwelle des Tors anbeten und danach wieder hinausgehen. Das Tor aber soli offen bleiben bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Desgleichen das Volk im Lande sollen in der Tur desselben Tors anbeten vor dem HERRN an den Sabbaten und Neumonden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Das Brandopfer aber, so der Fürst vor dem HERRN opfern soil am Sabbattage, soli sein sechs Lammer, die ohne Wandel seien, und ein Widder ohne Wandel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'und je ein Epha Speisopfer zu einem Widder zum Speisopfer. Zu den Lammern aber, soviel seine Hand gibt, zum Speisopfer und je ein Hin Ols zu einem Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Am Neumonden aber soil er einen jungen Farren opfern, der ohne Wandel sei, und sechs Lammer und einen Widder, auch ohne Wandel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'und je ein Epha zum Farren und je ein Epha zum Widder zum Speisopfer. Aber zu den Lammern so viel, als er greift; und je ein Hin Ols zu einem Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Und wenn der Furst hineingehet, soil er durch die Halle des Tors hineingehen und desselben Weges wieder herausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Aber das Volk im Lande, so vor den HERRN kommt auf die hohen Feste und zum Tor gegen Mitternacht hineingehet anzubeten, das soil durch das Tor gegen Mittag wieder herausgehen; und welche zum Tor gegen Mittag hineingehen, die sollen zum Tor gegen Mitternacht wieder herausgehen und sollen nicht wieder zu dem Tor hinausgehen, dadurch sie hinein sind gegangen, sondern stracks vor sich hinausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Der Furst aber soil mit ihnen beide hinein und herausgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Aber an den Feiertagen und hohen Festen soil man zum Speisopfer je zu einem Farren ein Epha und je zu einem Widder ein Epha opfern und zu den Lammern, soviel seine Hand gibt, und je ein Hin Ols zu einem Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Wenn aber der Furst ein freiwillig Brandopfer Oder Dankopferdem HERRN tun wollte, so soil man ihm das Tor gegen morgenwarts auftun, da(5 er sein Brandopfer und Dankopfer opfere, wie er sonst am Sabbat pflegt zu opfern; und wenn erwieder herausgehet, soil man das Tor nach ihm zuschließen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Und er soil dem HERRN taglich ein Brandopfer tun, namlich ein jahriges Lamm ohne Wandel; dasselbe soil er alle Morgen opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Und soil alle Morgen das sechste Teil von einem Epha zum Speisopfer darauf tun und ein drittes Teil von einem Hin Ols, auf das Semmelmehl zu traufen, dem HERRN zum Speisopfer. Das soli ein ewiges Recht sein, vom taglichen Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Und also sollen sie das Lamm samt dem Speisopfer und 01 alle Morgen opfern zum taglichen Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So spricht der Herr HERR: Wenn der Furst seiner Sohne einem ein Geschenk gibt von seinem Erbe, dasselbe soli seinen Sohnen bleiben, und sollen es erblich besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Wo er aber seiner Knechte einem von seinem Erbteil etwas schenket, das sollen sie besitzen bis aufs Freijahr, und soil alsdann dem Fursten wieder heimfallen; denn sein Teil soil allein auf seine Sohne erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Es soli auch der Furst dem Volk nichts nehmen von seinem Erbteil, noch sie aus ihren eigenen Gutern stoßen, sondern soli sein eigen Gut auf seine Kinder erben, auf daß meines Volks nicht jemand von seinem Eigentum zerstreuet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Und er fuhrete mich unterden Eingang an der Seite des Tors gegen Mitternacht zu den Kammern des Heiligtums, so den Priestern gehorten, und siehe, daselbst war ein Raum in einer Ecke gegen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Und er sprach zu mir: Dies ist der Ort, da die Priester kochen sollen das Schuldopfer und Sundopfer und das Speisopfer backen, daß sie es nicht hinaus in den außern Vorhof tragen dürfen, das Volk zu heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Danach fuhrete er mich hinaus in den außern Vorhof und hieß mich gehen in die vier Ecken des Vorhofs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Und siehe, da war ein jeglicher der vier Ecken ein ander Vorhoflein zu rauchern, vierzig Ellen lang und dreifüg Ellen breit, alle viereinerlei Mali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Und es ging ein Mauerlein urn ein jegliches der vier; da waren Herde herum gemacht unten an den Mauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Und er sprach zu mir: Dies ist die Kuche, darin die Diener im Hause kochen sollen, was das Volk opfert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Und er fuhrete mich wieder zu der Tur des Tempels. Und siehe, da floß ein Wasser heraus unter der Schwelle des Tempels gegen Morgen; denn die Tur des Tempels war auch gegen Morgen. Und das Wasser lief an der rechten Seite des Tempels neben dem Altar hin gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Und er fuhrete mich auswendig zum Tor gegen Mitternacht vom außern Tor gegen Morgen; und siehe, das Wasser sprang heraus von der rechten Seite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Und der Mann ging heraus gegen Morgen und hatte die Melischnur in der Hand; und er maß tausend Ellen und fuhrete mich durchs Wasser, bis mir\'s an die Knochel ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Und maß abermal tausend Ellen und fuhrete mich durchs Wasser, bis mir\'s an die Kniee ging. Und maß noch tausend Ellen und ließ mich dadurch gehen, bis es mir an die Lenden ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Da maß er noch tausend Ellen, und es war so tief, daß ich nicht mehr grunden konnte; denn das Wasser war zu hoch, daß man daruber schwimmen mußte und konnte es nicht grunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Und er sprach zu mir: Du Menschenkind, das hast du ja gesehen. Und er fuhrete mich wieder zuruck am Ufer des Bachs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Und siehe, da stunden sehrviel Baume am Ufer auf beiden Seiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Und er sprach zu mir: Dies Wasser das da gegen Morgen herausfleußt, wird durchs Blachfeld fließen ins Meer und von einem Meer ins andere, und wenn es dahin ins Meer kommt, da sollen dieselbigen Wasser gesund werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Ja alles, was darin lebt und webt, dahin diese Strome kommen, das soil leben, und soil sehr viel Fische haben; und soil alles gesund werden und leben, wo dieser Strom hinkommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Und es werden die Fischer an demselben stehen; von Engeddi bis zu En-Eglaim wird man die Fischgarne aufspannen; denn es werden daselbst sehr viel Fische sein, gleichwie im großen Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Aber die Teiche und Lachen daneben werden nicht gesund werden, sondern gesalzen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Und an demselben Strom, am Ufer auf beiden Seiten, werden allerlei fruchtbare Baume wachsen; und ihre Blatter werden nicht verwelken noch ihre Fruchte verfaulen; und werden alle Monden neue Fruchte bringen, denn ihr Wasser fleußt aus dem Heiligtum. Ihre Fruchtwird zurßpeise dienen und ihre Blatter zur Arznei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So spricht der Herr HERR: Dies ist die Grenze, nach der ihr das Land sollt austeilen den zwolf Stammen Israels; denn zwei Teile gehoren dem Stamm Joseph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Und ihr sollt es gleich austeilen, einem wie dem andern; denn ich habe meine Hand aufgehoben, das Land euren Vatern und euch zum Erbteil zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Dies ist nun die Grenze des Landes gegen Mitternacht von dem großen Meer an, von Hethlon bis gen Zedad:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'namlich Hemath, Berotha, Sibraim, die mit Damaskus und Hemath grenzen; und Hazar-Tichon, die mit Haveran grenzet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Das soil die Grenze sein vom Meer an bis gen Hazar-Enon; und Damaskus und Hemath sollen das Ende sein gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Aber die Grenze gegen Morgen sollt ihr messen zwischen Haveran und Damaskus und zwischen Gilead und zwischen dem Lande Israel, am Jordan hinab bis ans Meer gegen Morgen. Das soil die Grenze gegen Morgen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Aber die Grenze gegen Mittag ist von Thamar bis ans Haderwasser zu Kades und gegen das Wasser am großen Meer. Das soli die Grenze gegen Mittag sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Und die Grenze gegen Abend ist vom großen Meer an stracks bis gen Hemath. Das sei die Grenze gegen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Also sollt ihr das Land austeilen unter die Stamme Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Und wenn ihr das Los werfet, das Land unter euch zu teilen, so sollt ihr die Fremdlinge, die bei euch wohnen und Kinder unter euch zeugen, halten gleich wie die Einheimischen unter den Kindern Israel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'und sollen auch ihren Teil am Lande haben, ein jeglicher unter dem Stamm, dabei er wohnet, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Dies sind die Namen der Stamme. Von Mitternacht, von Hethlon gegen Hemath und Hazar- Enon und von Damaskus gegen Hemath; das soil Dan fur seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Neben Dan soil Asser seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Neben Asser soil Naphthali seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Neben Naphthali soil Manasse seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Neben Manasse soil Ephraim seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Neben Ephraim soil Ruben seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Neben Ruben soil Juda seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Neben Juda aber sollt ihr einen Teil absondern vom Morgen bis gegen Abend, der fünfundzwanzigtausend Ruten breit und lang sei, ein Stuck von den Teilen, so von Morgen bis gen Abend reichen; darin soil das Heiligtum stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Und davon sollt ihr dem HERRN einen Teil absondern, funfundzwanzigtausend Ruten lang und zehntausend Ruten breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Und dasselbige heilige Teil soil der Priester sein, namlich funfundzwanzigtausend Ruten lang gegen Mitternacht und gegen Mittag und zehntausend breit gegen Morgen und gegen Abend. Und das Heiligtum des HERRN soli mitten drinnen stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Das soil geheiliget sein den Priestern, den Kindern Zadoks, welche meine Sitten gehalten haben und sind nicht abgefallen mit den Kindern Israel, wie die Leviten abgefallen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Und soil also dies abgesonderte Teil des Landes ihr eigen sein, darin das Allerheiligste ist neben der Leviten Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Die Leviten aber sollen neben der Priester Grenze auch funfundzwanzigtausend Ruten in die Lange und zehntausend in die Breite haben; denn alle Lange soil funfundzwanzigtausend und die Breite zehntausend Ruten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Und sollen nichts davon verkaufen noch verandern, damit des Landes Erstling nicht wegkomme; denn es ist dem HERRN geheiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Aber die ubrigen funftausend Ruten in die Breite gegen die funfundzwanzigtausend Ruten in die Lange, das soil unheilig sein zur Stadt, drinnen zu wohnen, und zu Vorstadten; und die Stadt soli mitten drinnen stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Und das soli ihr Maß sein: viertausend und fünfhundert Ruten gegen Mitternacht und gegen Mittag; desgleichen gegen Morgen und gegen Abend auch viertausend und fünfhundert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Die Vorstadt aber soil haben zweihundertundfünfzig Ruten gegen Mitternacht und gegen Mittag; desgleichen auch gegen Morgen und gegen Abend zweihundertundfünfzig Ruten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Aber das übrige an der Lange desselben neben dem Abgesonderten und Geheiligten, namlich zehntausend Ruten gegen Morgen und gegen Abend, das gehort zur Unterhaltung derer, die in der Stadt arbeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Und die Arbeiter sollen aus alien Stammen Israels der Stadt arbeiten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'daß die ganze Absonderung der fünfundzwanzigtausend Ruten ins Gevierte eine geheiligte Absonderung sei zu eigen der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Was aber noch übrig ist auf beiden Seiten neben dem abgesonderten heiligen Teil und neben der Stadt Teil, namlich fünfundzwanzigtausend Ruten gegen Morgen und gegen Abend, das soil alles des Fursten sein. Aber das abgesonderte heilige Teil und das Haus des Heiligtums soli mitten innen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Was aber dazwischen liegt, zwischen der Leviten Teil und zwischen der Stadt Teil und zwischen der Grenze Judas und der Grenze Benjamins, das soil des Fürsten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Danach sollen die andern Stamme sein: Benjamin soil seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Aber neben der Grenze Benjamins soil Simeon seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Neben der Grenze Simeons soil Isaschar seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Neben der Grenze Isaschars soil Sebulon seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Neben der Grenze Sebulons soil Gad seinen Teil haben von Morgen bis gen Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Aber neben Gad ist die Grenze gegen Mittag, von Thamar bis an das Haderwasser zu Kades und gegen dem Wasser am grolien Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Also soli das Land ausgeteilet werden zum Erbteil unterdie Stamme Israels; und das soil ihr Erbteil sein, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Und so weit soil die Stadt sein: viertausend und fünfhundert Ruten gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Und die Tore der Stadt sollen nach den Namen der Stamme Israels genannt werden, drei Tore gegen Mitternacht: das erste Tor Ruben, das andere Juda, das dritte Levi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Also auch gegen Morgen viertausend und fünfhundert Ruten und auch drei Tore: namlich das erste Tor Joseph, das andere Benjamin, das dritte Dan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Gegen Mittag auch also: viertausend und fünfhundert Ruten und auch drei Tore: das erste Tor Simeon, das andere Isaschar, das dritte Sebulon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Also auch gegen Abend viertausend und fünfhundert Ruten und drei Tore: ein Tor Gad, das andere Assur, das dritte Naphthali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Also soli es urn und urn achtzehntausend Ruten haben. Und alsdann soil die Stadt genannt werden: Hie ist der HERR!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Im dritten Jahr des Reichs Jojakims, des Konigs Judas, kam Nebukadnezar, der Konig zu Babel, vor Jerusalem und belagerte sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Und der HERR übergab ihm Jojakim, den Konig Judas, und etliche Gefalie aus dem Hause Gottes; die ließ erführen ins Land Sinear, in seines Gottes Haus, und tat die Gefalie in seines Gottes Schatzkasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Und der Konig sprach zu Aspenas, seinem obersten Kammerer, er sollte aus den Kindern Israel vom koniglichen Stamm und Herrenkindern wahlen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Knaben, die nicht gebrechlich waren, sondern schone, vernünftige, weise, kluge und verstandige, die da geschickt waren, zu dienen in des Konigs Hofe und zu lernen chaldaische Schrift und Sprache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Solchen verschaffte der Konig, was man ihnen taglich geben sollte von seiner Speise und von dem Wein, den er selbst trank, daß sie, also drei Jahre auferzogen, danach vor dem Konige dienen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Unter welchen waren Daniel, Hananja, Misael und Asarja von den Kindern Judas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Und der oberste Kammerer gab ihnen Namen und nannte Daniel Beltsazar und Hananja Sadrach und Misael Mesach und Asarja Abed-Nego.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Aber Daniel setzte ihm vor in seinem Herzen, daß er sich mit des Konigs Speise und mit dem Wein, den er selbst trank, nicht verunreinigen wollte, und bat den obersten Kammerer, daß er sich nicht mülite verunreinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Und Gott gab Daniel, daß ihm der oberste Kammerer gunstig und gnadig ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Derselbe sprach zu ihm: Ich furchte mich vor meinem Herm, dem Konige, der euch eure Speise und Trank verschaffet hat; wo er wurde sehen, daß eure Angesichte jammerlicher waren denn der andern Knaben eures Alters, so brachtet ihr mich bei dem Konige urn mein Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Da sprach Daniel zu Melzar, welchem der oberste Kammerer Daniel, Hananja, Misael und Asarja befohlen hatte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Versuch es doch mit deinen Knechten zehn Tage und lali uns geben Gemüse zu essen und Wasser zu trinken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Und lati dann vor dir unsere Gestalt und der Knaben, so von des Konigs Speise essen, besehen; und danach du sehen wirst, danach schaffe mit deinen Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Und ergehorchte ihnen darin und versuchte es mit ihnen zehn Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Und nach den zehn Tagen waren sieschoner und bali bei Leibe denn alle Knaben, so von des Konigs Speise alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Da tat Melzar ihre verordnete Speise und Trank weg und gab ihnen Gemüse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Aber der Gott dieser vier gab ihnen Kunst und Verstand in allerlei Schrift und Weisheit; Daniel aber gab er Verstand in alien Gesichten und Traumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Und da die Zeit um war, die der Konig bestimmt hatte, daß sie sollten hineingebracht werden, brachte sie der oberste Kammerer hinein vor Nebukadnezar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Und der Konig redete mit ihnen, und ward unter alien niemand erfunden, der Daniel, Hananja, Misael und Asarja gleich ware. Und sie wurden des Konigs Diener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Und der Konig fand sie in alien Sachen, die er sie fragte, zehnmal kluger und verstandiger denn alle Sternseher und Weisen in seinem ganzen Reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Und Daniel lebte bis ins erste Jahr des Konigs Kores.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Im andern Jahr des Reichs Nebukadnezars hatte Nebukadnezar einen Traum, davon er erschrak, dafi er aufwachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Und er hieft alle Sternseher, und Weisen und Zauberer und Chaldaer zusammenfordern, daß sie dem Konige seinen Traum sagen sollten. Und sie kamen und traten vor den Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Und der Konig sprach zu ihnen: Ich habe einen Traum gehabt, der hat mich erschreckt; und ich wollte gerne wissen, was es fur ein Traum gewesen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Da sprachen die Chaldaer zum Konige auf chaldaisch: Herr Konig, Gott verleihe dir langes Leben! Sage deinen Knechten den Traum, so wollen wirihn deuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Der Konig antwortete und sprach zu den Chaldaern: Es ist mir entfallen. Werdet ihr mirden Traum nicht anzeigen und ihn deuten, so werdet ihr gar umkommen und eure Hauser schandlich verstoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Werdet ihr mir aber den Traum anzeigen und deuten, so sollt ihr Geschenke, Gaben und grofie Ehre von mir haben. Darum so sagt mir den T raum und seine Deutung!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Sie antworteten wiederum und sprachen: Der Konig sage seinen Knechten den Traum, so wollen wir ihn deuten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Der Konig antwortete und sprach: Wahrüch, ich merke es, dafi ihr Frist suchet, weil ihr sehet, daß mir\'s entfallen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Aber werdet ihr mir nicht den T raum sagen, so gehet das Recht uber euch, als die ihr Lugen und Gedichte vor mir zu reden vorgenommen habt, bis die Zeit vorubergehe. Darum so sagt mir den Traum, so kann ich merken, daß ihr auch die Deutung treffet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Da antworteten die Chaldaer vor dem Konige und sprachen zu ihm: Es ist kein Mensch auf Erden, der sagen konne, das der Konig fordert. So ist auch kein Konig, wie graft Oder machtig er sei, der solches von irgendeinem Sternseher, Weisen Oder Chaldaer fordere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Denn das der Konig fordert, ist zu hoch, und ist auch sonst niemand, der es vor dem Konige sagen konne, ausgenommen die Gotter, die bei den Menschen nicht wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Da ward der Konig sehr zornig und befahl, alle Weisen zu Babel umzubringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Und das Urteil ging aus, daß man die Weisen toten sollte. Und Daniel samt seinen Gesellen ward auch gesucht, daß man sie totete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Da vernahm Daniel solch Urteil und Befehl von dem obersten Richter des Konigs, welcher auszog, zu toten die Weisen zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Und erfing an und sprach zu des Konigs Vogt Arioch: Warum ist so ein streng Urteil vom Konige ausgegangen? Und Arioch zeigte es dem Daniel an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Da ging Daniel hinauf und bat den Konig, daß er ihm Frist gabe, damit er die Deutung dem Konige sagen mochte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Und Daniel ging heim und zeigte solches an seinen Gesellen, Hananja, Misael und Asarja,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'daß sie Gott vom Himmel um Gnade baten solches verborgenen Dings halben, damit Daniel und seine Gesellen nicht samt den andern Weisen zu Babel umkamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Da ward Daniel solch verborgen Ding durch ein Gesicht des Nachts offenbaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daruber lobte Daniel den Gott vom Himmel, fing an und sprach: Gelobet sei der Name Gottes von Ewigkeit zu Ewigkeit; denn sein ist beides, Weisheit und Starke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Er andert Zeit und Stunde; er setzt Konige ab und setzt Konige ein; er gibt den Weisen ihre Weisheit und den Verstandigen ihren Verstand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'er offenbaret, was tief und verborgen ist; er weift, was in Finsternis liegt; denn bei ihm ist eitel Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ich danke dir und lobe dich, Gott meiner Vater, daß du mir Weisheit und Starke verleihest und jetzt offenbaret hast, darum wir dich gebeten haben; namlich du hast uns des Konigs Sache offenbaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Da ging Daniel hinauf zu Arioch, der vom Konige Befehl hatte, die Weisen zu Babel umzubringen, und sprach zu ihm also: Du sollst die Weisen zu Babel nicht umbringen, sondern fuhre mich hinauf zum Konige, ich will dem Konige die Deutung sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Arioch brachte Daniel eilends hinauf vor den Konig und sprach zu ihm also: Es ist einer funden unter den Gefangenen aus Juda, der dem Konige die Deutung sagen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Der Konig antwortete und sprach zu Daniel, den sie Beltsazar hieften: Bistdu, der mirden Traum, den ich gesehen habe und seine Deutung zeigen kann?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel fing an vor dem Konige und sprach: Das verborgene Ding, das der Konig fordert von den Weisen, Gelehrten, Sternsehern und Wahrsagern, stehet in ihrem Vermogen nicht, dem Konige zu sagen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'sondern Gott vom Himmel, der kann verborgene Dinge offenbaren; der hat dem Konige Nebukadnezar angezeiget, was in kunftigen Zeiten geschehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Dein Traum und dein Gesicht, da du schliefest, kam daher: Du, Konig, dachtest auf deinem Bette, wie es doch hernach gehen würde; und der, so verborgene Dinge offenbaret, hat dir angezeiget, wie es gehen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'So ist mir solch verborgen Ding offenbaret, nicht durch meine Weisheit, als ware sie grolier denn alter, die da leben, sondern darum, dafi dem Konige die Deutung angezeiget würde, und du deines Herzens Gedanken erführest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, Konig, sahst, und siehe, ein sehr grofi und hoch Bild stund vor dir, das war schrecklich anzusehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Desselben Bildes Haupt war von feinem Golde; seine Brust und Arme waren von Silber; sein Bauch und Lenden waren von Erz;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'seine Schenkel waren Eisen; seine Fülie waren eines Teils Eisen und eines Teils Ton.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Solches sahst du, bis daß ein Stein herabgerissen ward ohne Hande; der schlug das Bild an seine Futie, die Eisen und Ton waren, und zermalmete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Da wurden miteinander zermalmet das Eisen, Ton, Erz, Silber und Gold und wurden wie Spreu auf der Sommertenne; und der Wind verwebte sie, dafi man sie nirgends mehr finden konnte. Der Stein aber, der das Bild schlug, ward ein grolier Berg, daß er die ganze Welt fullete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Das ist der Traum. Nun wollen wir die Deutung vor dem Konige sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, Konig, bist ein Konig aller Konige, dem Gott vom Himmel Konigreich, Macht, Starke und Ehre gegeben hat');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'und alles da Leute wohnen, dazu die Tiere auf dem Felde und die Vogel unterdem Himmel in deine Hande gegeben und dir fiber alles Gewalt verliehen hat. Du bist das guldene Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Nach dirwird ein ander Konigreich aufkommen, geringerdenn deines. Danach das dritte Konigreich, das ehern ist, welches wird fiber alle Lande herrschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Das vierte wird hart sein wie Eisen. Denn gleichwie Eisen alles zermalmet und zerschlagt, ja, wie Eisen alles zerbricht, also wird es auch alles zermalmen und zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Dali du aber gesehen hast die Fulie und Zehen eines Teils Ton und eines Teils Eisen, das wird ein zerteilt Konigreich sein; doch wird von des Eisens Pflanze drinnen bleiben, wie du denn gesehen hast Eisen mit Ton vermenget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Und daß die Zehen an seinen Fülien eines Teils Eisen und eines Teils Ton sind, wird es zum Teil ein stark und zum Teil ein schwach Reich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Und daß du gesehen hast Eisen mit Ton vermenget, werden sie sich wohl nach Menschengeblut untereinander mengen, aber sie werden doch nicht aneinander halten, gleichwie sich Eisen mit Ton nicht mengen lalit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Aber zur Zeit solcher Konigreiche wird Gott vom Himmel ein Konigreich aufrichten, das nimmermehr zerstoret wird; und sein Konigreich wird auf kein ander Volk kommen. Es wird alle diese Konigreiche zermalmen und verstoren, aber es wird ewiglich bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Wie du denn gesehen hast, einen Stein ohne Hande vom Berge herabgerissen, der das Eisen, Erz, Ton, Silber und Gold zermalmet. Also hat der grofie Gott dem Konige gezeiget, wie es hernach gehen werde; und das ist gewifi der Traum, und die Deutung ist recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Da fiel der Konig Nebukadnezar auf sein Angesicht und betete an vor dem Daniel und befahl, man sollte ihm Speisopfer und Rauchopfer tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Und der Konig antwortete Daniel und sprach: Es ist kein Zweifel, euer Gott ist ein Gott uber alle Gotter und ein HERR fiber alle Konige, der da kann verborgene Dinge offenbaren, weil du dies verborgene Ding hast konnen offenbaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Und der Konig erhdhete Daniel und gab ihm grolie und viele Geschenke und machte ihn zum Ffirsten fiber das ganze Land zu Babel und setzte ihn zum Obersten fiber alle Weisen zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Und Daniel bat vom Konige, daß er fiber die Landschaften zu Babel setzen mochte Sadrach, Mesach, Abed-Nego; und er, Daniel, blieb bei dem Konige zu Hofe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Der Konig Nebukadnezar lieli ein gulden Bild machen, sechzig Ellen hoch und sechs Ellen breit, und lieli es setzen im Lande zu Babel im Tal Dura.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Und der Konig Nebukadnezar sandte nach den Ffirsten, Herren, Landpflegern, Richtern, Vogten, Raten, Amtleuten und alien Gewaltigen im Lande, daß sie zusammenkommen sollten, das Bild zu weihen, das der Konig Nebukadnezar hatte setzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Da kamen zusammen die Ffirsten, Herren, Landpfleger, Richter, Vogte, Rate, Amtleute und alle Gewaltigen im Lande, das Bild zu weihen, das der Konig Nebukadnezar hatte setzen lassen. Und sie mutiten vor das Bild treten, das Nebukadnezar hatte setzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Und der Ehrenhold rief fiberlaut: Das latit euch gesagtsein, ihr Volker, Leute und Zungen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Wenn ihr horen werdet den Schall der Posaunen, Trommeten, Harfen, Geigen, Psalter, Lauten und allerlei Saitenspiel, so sollt ihr niederfallen und das güldene Bild anbeten, das der Konig Nebukadnezar hat setzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Wer aber alsdann nicht niederfallt und anbetet, der soli von Stund an in den glfihenden Ofen geworfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Da sie nun horeten den Schall der Posaunen, Trommeten, Harfen, Geigen, Psalter und allerlei Saitenspiel, fielen nieder alle Volker, Leute und Zungen und beteten an das guldene Bild, das der Konig Nebukadnezar hatte setzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Von Stund an traten hinzu etliche chaldaische Manner und verklagten die Juden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'fingen an und sprachen zum Konige Nebukadnezar: Herr Konig, Gott verleihe dir langes Leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du hast ein Gebot lassen ausgehen, daß alle Menschen, wenn sie horen wurden den Schall der Posaunen, Trommeten, Harfen, Geigen, Psalter, Lauten und allerlei Saitenspiel, sollten sie niederfallen und das guldene Bild anbeten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'wer aber nicht niederfiele und anbetete, sollte in einen gluhenden Ofen geworfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nun sind da judische Manner, welche du fiber die Amter im Lande zu Babel gesetzet hast: Sadrach, Mesach und Abed-Nego; dieselbigen verachten dein Gebot und ehren deine Gotter nicht und beten nicht an das guldene Bild, das du hast setzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Da befahl Nebukadnezar mit Grimm und Zorn, daß man vor ihn stellete Sadrach, Mesach und Abed- Nego. Und die Manner wurden vor den Konig gestellet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Da ting Nebukadnezar an und sprach zu ihnen: Wie? wollt ihr, Sadrach, Mesach, Abed-Nego, meinen Gott nicht ehren und das guldene Bild nicht anbeten, das ich habe setzen lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Wohlan, schicket euch! Sobald ihr horen werdet den Schall der Posaunen, Trommeten, Harfen, Geigen, Psalter, Lauten und allerlei Saitenspiel, so fallet nieder und betet das Bild an, das ich habe machen lassen! Werdet ihr\'s nicht anbeten, so sollt ihr von Stund an in den gluhenden Ofen geworfen werden. Laftt sehen, wer der Gott sei, der euch aus meiner Hand erretten werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Da fingen an Sadrach, Mesach; Abed-Nego und sprachen zum Konige Nebukadnezar: Es ist nicht not, daß wir dir darauf antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Siehe, unserßott, den wir ehren, kann unswohl erretten aus dem gluhenden Ofen, dazu auch von deiner Hand erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Und wo er\'s nicht tun will, so sollst du dennoch wissen, daß wir deine Gotter nicht ehren, noch das guldene Bild, das du hast setzen lassen, anbeten wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Da ward Nebukadnezar voll Grimms und stellete sich scheuftlich wider Sadrach, Mesach und Abed- Nego und befahl, man sollte den Ofen siebenmal heifter machen, denn man sonst zu tun pflegte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Und befahl den besten Kriegsleuten, die in seinem Heer waren, daß sie Sadrach, Mesach und Abed-Nego banden und in den gluhenden Ofen würfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Also wurden diese Manner in ihren Manteln, Schuhen, Huten und andern Kleidern gebunden und in den gluhenden Ofen geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Denn des Konigs Gebot muftte man eilend tun. Und man schurete das Feuer im Ofen so sehr, daß die Manner, so den Sadrach, Mesach und Abed-Nego verbrennen sollten, verdarben von des Feuers Flammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Aber die drei Manner Sadrach, Mesach und Abed-Nego, fielen hinab in den gluhenden Ofen, wie sie gebunden waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Da entsetzte sich der Konig Nebukadnezar und fuhr eilends auf und sprach zu seinen Raten: Haben wir nicht drei Manner gebunden in das Feuer lassen werfen? Sie antworteten und sprachen zum Konige: Ja, Herr Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Er antwortete und sprach: Sehe ich doch vier Manner los im Feuer gehen, und sind unversehrt; und der vierte ist gleich, als ware er ein Sohn der Gotter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Und Nebukadnezar trat hinzu vor das Loch des gluhenden Ofens und sprach: Sadrach, Mesach, Abed-Nego, ihr Knechte Gottes des Hochsten, gehet heraus und kommt her! Da gingen Sadrach, Mesach und Abed-Nego heraus aus dem Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Und die Fursten, Herren, Vogte und Rate des Konigs kamen zusammen und sahen, daß das Feuer keine Macht am Leibe dieser Manner beweiset hatte, und ihr Haupthaar nicht versenget und ihre Mantel nicht versehrt waren; ja, man konnte keinen Brand an ihnen riechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Da fing an Nebukadnezar und sprach: Gelobet sei der Gott Sadrachs, Mesachs und Abed-Negos, der seinen Engel gesandt und seine Knechte errettet hat, die ihm vertrauet und des Konigs Gebot nicht gehalten, sondern ihren Leib dargegeben haben, daß sie keinen Gott ehren noch anbeten wollten ohne allein ihren Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'So sei nun dies mein Gebot: Welcher unter alien Volkern, Leuten und Zungen den Gott Sadrachs, Mesachs und Abed-Negos lasted, der soil umkommen, und sein Haus schandlich verstoret werden. Denn es ist kein anderer Gott, der also erretten kann als dieser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Und der Konig gab Sadrach, Mesach und Abed- Nego grofte Gewalt im Lande zu Babel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 31, 'Konig Nebukadnezar alien Volkern, Leuten und Zungen: Gott gebe euch viel Friede!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 32, 'Ich sehe es fur gut an, daß ich verkündige die Zeichen und Wunder, so Gott der Hochste an mir getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 33, 'Denn seine Zeichen sind graft, und seine Wunder sind machtig; und sein Reich ist ein ewiges Reich, und seine Herrschaft wahret fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Ich, Nebukadnezar, da ich gute Ruhe hatte in meinem Hause, und es wohl stund auf meiner Burg,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'sah ich einen Traum und erschrak, und die Gedanken, die ich auf meinem Bette hatte fiber dem Gesichte, so ich gesehen hatte, betrubten mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Und ich befahl, daß alle Weisen zu Babel vor mich heraufgebracht wurden, daß sie mir sageten, was der Traum bedeutete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Da brachte man herauf die Sternseher, Weisen, Chaldaer und Wahrsager, und ich erzahlte den Traum vor ihnen; aber sie konnten mir nicht sagen, was er bedeutete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'bis zuletzt Daniel vor mich kam, welcher Beltsazar heilit, nach dem Namen meines Gottes, der den Geist der heiligen Gotter hat. Und ich erzahlte vor ihm den Traum:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Beltsazar, du Oberster unter den Sternsehern, welchen ich weili, daß du den Geist der heiligen Gotter hast und dir nichts verborgen ist, sage das Gesicht meines Traums, den ich gesehen habe, und was er bedeutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Dies ist aber das Gesicht, das ich gesehen habe auf meinem Bette: Siehe, es stund ein Baum mitten im Lande, der war sehr hoch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'grofi und dick; seine Hohe reichte bis in Himmel und breitete sich aus bis ans Ende des ganzen Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Seine Aste waren schon und trugen viel Fruchte, davon alles zu essen hatte. Alle Tiere auf dem Felde fanden Schatten unter ihm, und die Vogel unter dem Himmel salien auf seinen Asten, und alles Fleisch nahrete sich von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Und ich sah ein Gesicht auf meinem Bette, und siehe, ein heiliger Wachter fuhr vom Himmel herab,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'der rief uberlaut und sprach also: Hauet den Baum urn und behauet ihm die Aste und streifet ihm das Laub ab und zerstreuet seine Fruchte, daß die Tiere, so unter ihm liegen, weglaufen, und die Vogel von seinen Zweigen fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Doch lafi den Stock mit seinen Wurzeln in der Erde bleiben; er aber soil in eisernen und ehernen Ketten auf dem Felde im Grase gehen; ersoll unter dem Tau des Himmels liegen und nali werden und soil sich weiden mit den Tieren von den Krautern der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Und das menschliche Herz soil von ihm genommen und ein viehisch Herz ihm gegeben werden, bis daü sieben Zeiten uber ihm urn sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Solches ist im Rat der Wachter beschlossen und im Gesprach der Heiligen beratschlaget, auf daß die Lebendigen erkennen, daß der Hochste Gewalt hat uber der Menschen Konigreiche und gibt sie, wem er will, und erhohet die Niedrigen zu denselbigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Solchen Traum habe ich, Konig Nebukadnezar, gesehen. Du aber, Beltsazar, sage, was er bedeute; denn alle Weisen in meinem Konigreich konnen mir nicht anzeigen, was er bedeute; du aber kannst es wohl, denn der Geist der heiligen Gotter ist bei dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Da entsetzte sich Daniel, der sonst Beltsazar heilit, bei einer Stunde lang, und seine Gedanken betrubten ihn. Aber der Konig sprach: Beltsazar, lali dich den Traum und seine Deutung nicht betruben! Beltsazar fing an und sprach: Ach, mein Herr, daß der Traum deinen Feinden und seine Deutung deinen Widerwartigen galte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Der Baum, den du gesehen hast, daß er groli und dick war und seine Hohe an den Himmel reichte und breitete sich uber das ganze Land,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'und seine Aste schon und seiner Fruchte viel, davon alles zu essen hatte, und die Tiere auf dem Felde unter ihm wohneten, und die Vogel des Himmels auf seinen Asten salien:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'das bistdu, Konig der du so groli und machtig bist; denn deine Macht ist groli und reichet an den Himmel, und deine Gewalt langet bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Dali aber der Konig einen heiligen Wachter gesehen hat vom Himmel herabfahren und sagen: Hauet den Baum urn und verderbet ihn, doch den Stock mit seinen Wurzeln lalit in der Erde bleiben; er aber soil in eisernen und ehernen Ketten auf dem Felde im Grase gehen und unter dem Tau des Himmels liegen und nali werden und sich mit den Tieren auf dem Felde weiden, bis uber ihm sieben Zeiten urn sind:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'das ist die Deutung, Herr Konig, und solcher Rat des Hochsten gehet uber meinen Herm Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Man wird dich von den Leuten verstolien, und mulit bei den Tieren auf dem Felde bleiben; und man wird dich Gras essen lassen wie die Ochsen; und wirst unter dem Tau des Himmels liegen und nali werden, bis uber dir sieben Zeiten urn sind, auf daß du erkennest, daß der Hochste Gewalt hat uber der Menschen Konigreiche und gibt sie, wem er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Dali aber gesagt ist, man solle dennoch den Stock mit seinen Wurzeln des Baums bleiben lassen: dein Konigreich soil dir bleiben, wenn du erkannt hast die Gewalt im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Darum, Herr Konig, lali dir meinen Rat gefallen und mache dich los von deinen Sunden durch Gerechtigkeit und ledig von deiner Missetat durch Wohltat an den Armen, so wird er Geduld haben mit deinen Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Dies alles widerfuhrdem Konige Nebukadnezar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Denn nach zwolf Monden, da der Konig auf der koniglichen Burg zu Babel ging,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'hub er an und sprach: Das ist die grolie Babel, die ich erbauet habe zum koniglichen Hause durch meine grolie Macht, zu Ehren meiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Ehe der Konig diese Worte ausgeredet hatte, fiel eine Stimme vom Himmel: Dir, Konig Nebukadnezar, wird gesagt: Dein Konigreich soil dir genommen werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'und man wird dich von den Leuten verstolien, und sollst bei den Tieren, so auf dem Felde gehen, bleiben; Gras wird man dich essen lassen, wie Ochsen, bis daß uber dir sieben Zeiten urn sind, auf daß du erkennest, daß der Hochste Gewalt hat uber der Menschen Konigreiche und gibt sie, wem er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Von Stund an ward das Wort vollbracht über Nebukadnezar, und er ward von den Leuten verstoften und er aft Gras wie Ochsen, und sein Leib lag unterdem Tau des Himmels und ward nafi, bis sein Haar wuchs, so groli als Adlersfedern, und seine Nagel wie Vogelklauen wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Nach dieser Zeit hub ich, Nebukadnezar, meine Augen auf gen Himmel und kam wiederzur Vernunft und lobte den Hochsten. Ich preisete und ehrete den, so ewiglich lebet, des Gewalt ewig ist und sein Reich fur und fur wahret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'gegen welchen alle, so auf Erden wohnen, als nichts zu rechnen sind. Er macht es, wie er will, beide, mit den Kraften im Himmel und mitdenen, so auf Erden wohnen; und niemand kann seiner Hand wehren noch zu ihm sagen: Was machst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Zur selbigen Zeit kam ich wieder zur Vernunft, auch zu meinen koniglichen Ehren, zu meiner Herrlichkeit und zu meiner Gestalt. Und meine Rate und Gewaltigen suchten mich; und ward wieder in mein Konigreich gesetzt; und ich uberkam noch groftere Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Darum lobe ich, Nebukadnezar, und ehre und preise den Konig vom Himmel. Denn all sein Tun ist Wahrheit, und seine Wege sind recht; und wer stolz ist, den kann er demutigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Konig Belsazer machte ein herrlich Mahl tausend seinen Gewaltigen und Hauptleuten und soft sich voll mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Und da er trunken war, hiefi er die guldenen und silbernen Gefafte herbringen, die sein Vater Nebukadnezar aus dem Tempel zu Jerusalem weggenommen hatte, daß der Konig mit seinen Gewaltigen, mit seinen Weibern und mit seinen Kebsweibern daraus tranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Also wurden hergebracht die guldenen Gefafte, die aus dem Tempel, aus dem Hause Gottes zu Jerusalem, genommen waren; und der Konig, seine Gewaltigen, seine Weiber und Kebsweiber tranken daraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Und da sie so soffen, lobten sie die guldenen, silbernen, ehernen, eisernen, holzernen und steinernen Gotter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Eben zur selbigen Stunde gingen hervor Finger, als einer Menschenhand, die schrieben, gegenuber dem Leuchter, auf die getunchte Wand in dem koniglichen Saal. Und der Konig ward gewahr der Hand, die da schrieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Da entfarbte sich der Konig, und seine Gedanken erschreckten ihn, daß ihm die Lenden schutterten und die Beine zitterten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Und der Konig rief uberlaut, daß man die Weisen, Chaldaer und Wahrsager heraufbringen sollte Und lieft den Weisen zu Babel sagen: Welcher Mensch diese Schrift lieset und sagen kann, was sie bedeute, der soil mit Purpur gekleidet werden und güldene Ketten am Halse tragen und der dritte Herr sein in meinem Konigreiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Da wurden alle Weisen des Konigs heraufgebracht; aber sie konnten weder die Schrift lesen noch die Deutung dem Konige anzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Des erschrak der Konig Belsazer noch harter und verlor ganz seine Gestalt, und seinen Gewaltigen ward bange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Da ging die Konigin urn solcher Sache willen des Konigs und seiner Gewaltigen hinauf in den Saal und sprach: Herr Konig, Gott verleihe dir langes Leben! Laft dich deine Gedanken nichtso erschrecken und entfarbe dich nicht also!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Es ist ein Mann in deinem Konigreich, der den Geist der heiligen Gotter hat. Denn zu deines Vaters Zeit ward bei ihm Erleuchtung erfunden, Klugheit und Weisheit, wie der Gotter Weisheit ist; und dein Vater, Konig Nebukadnezar, setzte ihn fiber die Sternseher, Weisen, Chaldaer und Wahrsager,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'darum daß ein hoher Geist bei ihm funden ward, dazu Verstand und Klugheit, Spruche zu deuten, dunkle Spruche zu erraten und verborgene Sachen zu offenbaren, namlich Daniel, den der Konig lieft Beltsazar nennen. So rufe man nun Daniel; der wird sagen, was es bedeute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Da ward Daniel hinauf vor den Konig gebracht. Und der Konig sprach zu Daniel: Bist du der Daniel, der Gefangenen einer aus Juda, die der Konig, mein Vater, aus Juda hergebracht hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Ich habe von dir horen sagen, daß du den Geist der heiligen Gotter habest, und Erleuchtung, Verstand und hohe Weisheit bei dir funden sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Nun hab ich vor mich fordern lassen die Klugen und Weisen, daß sie mir diese Schrift lesen und anzeigen sollen, was sie bedeute; und sie konnen mir nicht sagen, was solches bedeute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Von dir aber hore ich, daß du konnest die Deutung geben und das Verborgene offenbaren. Kannst du nun die Schrift lesen und mir anzeigen, was sie bedeutet, so sollst du mit Purpur gekleidet werden und güldene Ketten an deinem Halse tragen und der dritte Herr sein in meinem Konigreiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Da fing Daniel an und redete vor dem Konige: Behalte deine Gaben selbst und gib dein Geschenk einem andern; ich will dennoch die Schrift dem Konige lesen und anzeigen, was sie bedeute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Herr Konig, Gott der Hochste hat deinem Vater, Nebukadnezar, Konigreich, Macht, Ehre und Herrlichkeit gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Und vor solcher Macht, die ihm gegeben war, furchteten und scheueten sich vor ihm alle Volker, Leute und Zungen. Er totete, wen er wollte; er schlug, wen er wollte; ererhohete, wen er wollte; er demutigte, wen er wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Da sich aber sein Herz erhub und er stolz und hochmutig ward, ward er vom koniglichen Stuhl gestoßen und verlor seine Ehre;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'und ward verstoßen von den Leuten, und sein Herz ward gleich den Tieren, und mußte bei dem Wild laufen und fraß Gras wie Ochsen, und sein Leib lag unter dem Tau des Himmels und ward naß, bis daß er lernete, daß Gott der Hdchste Gewalt hat uber der Menschen Konigreiche und gibt sie, wem er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Und du, Belsazer, sein Sohn, hast dein Herz nicht gedemutiget, ob du wohl solches alles weißt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'sondern hast dich wider den HERRN des Himmels erhoben, und die Gefaße seines Hauses hat man vordich bringen müssen; und du, deine Gewaltigen, deine Weiber und deine Kebsweiber habt daraus gesoffen, dazu die silbernen, guldenen, ehernen, eisernen, holzernen, steinernen Gotter gelobet, die weder sehen, noch horen, noch fuhlen; den Gott aber, der deinen Odem und alle deine Wege in seiner Hand hat, hast du nicht geehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Darum ist von ihm gesandt diese Hand und diese Schrift, die da verzeichnet stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Das ist aber die Schrift allda verzeichnet: Mene, mene, tekel, upharsin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Und sie bedeutet dies: Mene, das ist, Gott hat dein Konigreich gezahlet und vollendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel, das ist, man hat dich in einer Waage gewogen und zu leicht funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, das ist, dein Konigreich ist zerteilet und den Medern und Persern gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Da befahl Belsazer, daß man Daniel mit Purpur kleiden sollte und guldene Ketten an den Hals geben; und ließ von ihm verkundigen, daß er der dritte Herr sei im Konigreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Aber des Nachts ward der Chaldaer Konig Belsazer getotet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Und Darius aus Medien nahm das Reich ein, da er zweiundsechzig Jahre alt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Und Darius sah es fur gut an, daß er uber das ganze Konigreich setzte hundertundzwanzig Landvogte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Uber diese setzte er drei Fursten, deren einer war Daniel, welchen die Landvogte sollten Rechnung tun, und der Konig der Mühe überhoben ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Daniel aber ubertraf die Fursten und Landvogte alle, denn es war ein hoher Geist in ihm; darum gedachte der Konig ihn fiber das ganze Konigreich zu setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Derhalben trachteten die Fursten und Landvogte danach, wie sie eine Sache zu Daniel fanden, die wider das Konigreich ware; aber sie konnten keine Sache noch Ubeltat finden, denn er war treu, daß man keine Schuld noch Ubeltat an ihm finden mochte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Da sprachen die Manner: Wir werden keine Sache zu Daniel finden ohne uber seinem Gottesdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Da kamen die Fursten und Landvogte haufig vor den Konig und sprachen zu ihm also: Herr Konig Darius, Gott verleihe dir langes Leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Es haben die Fursten des Konigreichs, die Herren, die Landvogte, die Rate und Hauptleute alle gedacht, daß man einen kdniglichen Befehl solle ausgehen lassen und ein streng Gebot stellen, daß, wer in dreißig Tagen etwas bitten wird von irgendeinem Gott Oder Menschen ohne von dir, Konig, alleine, solle zu den Lowen in den Graben geworfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Darum, lieber Konig, sollst du solch Gebot bestatigen und dich unterschreiben, auf daß nicht wieder geandert werde, nach dem Recht der Meder und Perser, welches niemand ubertreten dart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Also unterschrieb sich der Konig Darius.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Als nun Daniel erfuhr, daß solch Gebot unterschrieben ware, ging er hinauf in sein Haus (er hatte aber an seinem Sommerhause offene Fenster gegen Jerusalem). Und er fiel des Tages dreimal auf seine Kniee, betete, lobte und dankte seinem Gott, wie er denn vorhin zu tun pflegte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Da kamen diese Manner haufig und fanden Daniel beten und flehen vor seinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Und traten hinzu und redeten mit dem Konige von dem kdniglichen Gebot: Herr Konig, hast du nicht ein Gebot unterschrieben, daß, wer in dreißig Tagen etwas bitten würde von irgendeinem Gott Oder Menschen ohne von dir, Konig, alleine, solle zu den Ldwen in den Graben geworfen werden? Der Konig antwortete und sprach: Es ist wahr, und das Recht der Meder und Perser soil niemand ubertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Sie antworteten und sprachen vor dem Konige: Daniel, der Gefangenen aus Juda einer, der achtet weder dich noch dein Gebot, das du verzeichnet hast; denn er betet des Tages dreimal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Da der Konig solches horete, ward ersehr betrubt und tat großen Fleiß, daß er Daniel erlosete, und mühete sich, bis die Sonne unterging, daß er ihn errettete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Aber die Manner kamen haufig zu dem Konige und sprachen zu ihm: Du weißt, Herr Konig, daß der Meder und Perser Recht ist, daß alle Gebote und Befehle, so der Konig beschlossen hat, sollen unverandert bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Da befahl der Konig, daß man Daniel herbrachte; und warfen ihn zu den Lowen in den Graben. Der Konig aber sprach zu Daniel: Dein Gott, dem du ohne Unterlaß dienest, der helfe dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Und sie brachten einen Stein, den legten sie vor die Tur am Graben; den versiegelte der Konig mit seinem eigenen Ringe und mit dem Ringe seiner Gewaltigen, auf daß sonst niemand an Daniel Mutwillen übete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Und der Konig ging weg in seine Burg und blieb ungegessen und ließ kein Essen vor sich bringen, konnte auch nicht schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Des Morgens frith, da der Tag anbrach, stund der Konig auf und ging eilend zum Graben, da die Lowen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Und als erzum Graben kam, riefer Daniel mit klaglicher Stimme. Und der Konig sprach zu Daniel: Daniel, du Knecht des lebendigen Gottes, hat dich auch dein Gott, dem du ohn Unterlaü dienest, mogen von den Lowen erlosen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Daniel aber redete mit dem Kbnige: Herr Konig, Gott verleihe dirlanges Leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Mein Gott hat seinen Engel gesandt, der den Lowen den Rachen zugehalten hat, daß sie mir kein Leid getan haben. Denn vor ihm bin ich unschuldig erfunden, so habe ich auch wider dich, Herr Konig, nichts getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Da ward der Konig sehrfroh und lieli Daniel aus dem Graben ziehen. Und sie zogen Daniel aus dem Graben, und man spurete keinen Schaden an ihm; denn er hatte seinem Gott vertrauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Da hieß, der Konig die Manner, so Daniel verklagt hatten, herbringen und zu den Lowen in den Graben werfen samt ihren Kindern und Weibern. Und ehe sie auf den Boden hinab kamen, ergriffen sie die Lowen und zermalmeten auch ihre Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Da ließ der Konig Darius schreiben alien Volkern, Leuten und Zungen: Gott gebe euch viel Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Das ist mein Befehl, daß man in der ganzen Herrschaft meines Konigreichs den Gott Daniels furchten und scheuen soil. Denn er ist der lebendige Gott, der ewiglich bleibet; und sein Konigreich ist unverganglich, und seine Herrschaft hat kein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Er ist ein Erloser und Nothelfer, und er tut Zeichen und Wunder, beide, im Himmel und auf Erden. Der hat Daniel von den Lowen erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 29, 'Und Daniel ward gewaltig im Konigreich Darius und auch im Konigreich Kores, der Perser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Im ersten Jahr Belsazers, des Konigs zu Babel, hatte Daniel einen Traum und Gesicht auf seinem Bette; und erschrieb denselbigen Traum und verfalite ihn also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Ich, Daniel, sah ein Gesicht in der Nacht, und siehe, die vier Winde unter dem Himmel stürmeten widereinander auf dem grolien Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Und vier groüe Tiere stiegen herauf aus dem Meer, eins je anders denn das andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Das erste wie ein Lowe und hatte Flugel wie ein Adler. Ich sah zu, bis daß ihm die Flugel ausgerauft wurden; und es ward von der Erde genommen und es stund auf seinen Fufien wie ein Mensch, und ihm ward ein menschlich Herz gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Und siehe, das andere Tier hernach war gleich einem Baren und stund auf der einen Seite und hatte in seinem Maul unter seinen Zahnen drei groüe lange Zahne. Und man sprach zu ihm: Stehe auf und frili viel Fleisch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Nach diesem sah ich, und siehe, ein ander Tier, gleich einem Parden, das hatte vier Flugel, wie ein Vogel, auf seinem Rücken; und dasselbige Tier hatte vier Kopfe, und ihm ward Gewalt gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Nach diesem sah ich in diesem Gesicht in der Nacht, und siehe, das vierte Tier war greulich und schrecklich und sehr stark und hatte groüe eiserne Zahne, frafi urn sich und zermalmete, und das ubrige zertrat es mit seinen Fulien; es war auch viel anders denn die vorigen und hatte zehn Horner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Da ich aber die Horner schauete, siehe, da brach hervor zwischen denselbigen ein ander klein Horn, vor welchem der vordersten Horner drei ausgerissen wurden; und siehe, dasselbige Horn hatte Augen wie Menschenaugen und ein Maul, das redete groüe Dinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Solches sah ich, bis dafi Stuhle gesetzt wurden; und der Alte setzte sich, des Kleid war schneeweili und das Haar auf seinem Haupt wie reine Wolle; sein Stuhl war eitel Feuerflammen, und desselbigen Rader brannten mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Und von demselbigen ging aus ein langer feuriger Strahl. Tausendmal tausend dieneten ihm, und zehntausendmal zehntausend stunden vor ihm. Das Gericht ward gehalten, und die Bucher wurden aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Ich sah zu urn der grolien Rede willen, so das Horn redete; ich sah zu, bis das Tier getotet ward und sein Leib umkam und ins Feuer geworfen ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'und der andern Tiere Gewalt auch aus war; denn es war ihnen Zeit und Stunde bestimmt, wie lange ein jegliches wahren sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Ich sah in diesem Gesichte des Nachts, und siehe, es kam einer in des Himmels Wolken wie eines Menschen Sohn bis zu dem Alten und ward vor denselbigen gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Der gab ihm Gewalt, Ehre und Reich, daß ihm alle Vdlker, Leute und Zungen dienen sollten. Seine Gewalt ist ewig, die nicht vergehet, und sein Konigreich hat kein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Ich, Daniel, entsetzte mich davor, und solch Gesicht erschreckte mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Und ich ging zu deren einem, die da stunden, und bat ihn, daß er mir von dem allem gewissen Bericht gabe. Und er redete mit mir und zeigte mir, was es bedeutete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Diese vier grolien Tiere sind vier Reiche, so auf Erden kommen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Aber die Heiligen des Hochsten werden das Reich einnehmen und werden es immer und ewiglich besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Danach hatte ich gerne gewulit gewissen Bericht von dem vierten Tier, welches gar anders war denn die andern alle, sehr greulich, das eiserne Zahne und eherne Klauen hatte, das urn sich frali und zermalmete und das ubrige mit seinen Fufien zertrat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'und von den zehn Hornern auf seinem Haupt und von dem andern, das hervorbrach, vorwelchem drei abfielen, und von demselbigen Horn, das Augen hatte und ein Maul, das große Dinge redete und großer war, denn die neben ihm waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Und ich sah dasselbige Horn streiten wider die Heiligen und behielt den Sieg wider sie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'bis der Alte kam und Gericht hielt fur die Heiligen des Hdchsten; und die Zeit kam, daß die Heiligen das Reich einnahmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Er sprach also: Das vierte Tier wird das vierte Reich auf Erden sein, welches wird machtiger sein denn alle Reiche; es wird alle Lande fressen, zertreten und zermalmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Die zehn Horner bedeuten zehn Konige, so aus demselbigen Reich entstehen werden. Nach demselben aber wird ein anderer aufkommen, der wird machtiger sein denn der vorigen keiner und wird drei Konige demutigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Erwird den Hdchsten lastern und die Heiligen des Hdchsten verstoren und wird sich unterstehen, Zeit und Gesetz zu andern. Sie werden aber in seine Hand gegeben werden eine Zeit und etliche Zeiten und eine halbe Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Danach wird das Gericht gehalten werden; da wird dann seine Gewalt weggenommen werden, daß er zugrunde vertilget und umgebracht werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Aber das Reich, Gewalt und Macht unter dem ganzen Himmel wird dem heiligen Volk des Hdchsten gegeben werden, des Reich ewig ist, und alle Gewalt wird ihm dienen und gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Das war der Rede Ende. Aber ich, Daniel, ward sehr betrubt in meinen Gedanken, und meine Gestalt verfiel; doch behielt ich die Rede in meinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Im dritten Jahr des Konigreichs des Konigs Belsazer erschien mir, Daniel, ein Gesicht nach dem, so mir am ersten erschienen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Ich war aber, da ich solch Gesicht sah, zu Schloß Susan im Lande Elam am Wasser Ulai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Und ich hub meine Augen auf und sah, und siehe, ein Widder stund vor dem Wasser, der hatte zwei hohe Horner, doch eins hdher denn das andere, und das hochste wuchs am letzten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Ich sah, daß der Widder mit den Hornern stieß gegen Abend, gegen Mitternacht und gegen Mittag, und kein Tier konnte vor ihm bestehen noch von seiner Hand errettet werden, sondern er tat, was er wollte, und ward groß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Und indem ich darauf merkte, siehe, so kommt ein Ziegenbock vom Abend her uber die ganze Erde, daß er die Erde nicht ruhrete; und der Bock hatte ein ansehnlich Horn zwischen seinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Und er kam bis zu dem Widder, der zwei Horner hatte, den ich stehen sah vor dem Wasser; und er lief in seinem Zorn gewaltiglich zu ihm zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Und ich sah ihm zu, daß er hart an den Widder kam, und ergrimmete uber ihn und stieß den Widder und zerbrach ihm seine zwei Horner. Und der Widder hatte keine Kraft, daß er vor ihm hatte mogen bestehen, sondern erwarf ihn zu Boden und zertrat ihn; und niemand konnte den Widder von seiner Hand erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Und der Ziegenbock ward sehr groß. Und da er aufs starkste worden war, zerbrach das große Horn; und wuchsen an des Statt ansehnliche vier gegen die vier Winde des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Und aus derselbigen einem wuchs ein klein Horn, das ward sehr groß gegen Mittag, gegen Morgen und gegen das werte Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Und es wuchs bis an des Himmels Heer und warf etliche davon und von den Sternen zur Erde und zertrat sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ja, es wuchs bis an den Fursten des Heers und nahm von ihm weg das tagliche Opfer und verwüstete die Wohnung seines Heiligtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Es ward ihm aber solche Macht gegeben wider das tagliche Opfer urn der Sunde willen, daß er die Wahrheit zu Boden schluge und, was er tat, ihm gelingen mußte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Ich hdrete aber einen Heiligen reden; und derselbige Heilige sprach zu einem, der da redete: Wie lange soil doch wahren solch Gesicht vom taglichen Opfer und von der Sunde, urn welcher willen diese Verwustung geschieht, daß beide, das Heiligtum und das Heer, zertreten werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Und erantwortete mir: Essind zweitausend und dreihundert Tage, von Abend gegen Morgen zu rechnen, so wird das Heiligtum wieder geweihet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Und da ich, Daniel, solch Gesicht sah und hatte es gerne verstanden, siehe, da stund es vor mir wie ein Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Und ich horete zwischen Ulai eines Menschen Stimme, der rief und sprach: Gabriel, lege diesem das Gesicht aus, daß er\'s verstehe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Und er kam hartzu mir. Ich erschrak aber, da er kam, und fiel auf mein Angesicht. Er aber sprach zu mir: Merke auf, du Menschenkind; denn dies Gesicht gehort in die Zeit des Endes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Und da er mit mir redete, sank ich in eine Ohnmacht zur Erde auf mein Angesicht. Er aber ruhrete mich an und richtete mich auf, daß ich stund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Und er sprach: Siehe, ich will dirzeigen, wie es gehen wird zur Zeit des letzten Zorns; denn das Ende hat seine bestimmte Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Der Widder mit den zweien Hornern, den du gesehen hast, sind die Kdnige in Medien und Persien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Der Ziegenbock aber ist der Konig in Griechenland. Das große Horn zwischen seinen Augen ist der erste Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Daß aber vier an seiner Statt stunden, da es zerbrochen war, bedeutet, daß vier Konigreiche aus dem Volk entstehen werden, aber nicht so machtig, als er war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Nach diesen Konigreichen, wenn die Ubertreter uberhandnehmen, wird aufkommen ein frecher und tuckischer Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Derwird machtig sein, doch nicht durch seine Kraft. Er wird\'s wunderlich verwüsten; und wird ihm gelingen, daß er\'s ausrichte. Erwird die Starken samt dem heiligen Volk verstoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Und durch seine Klugheit wird ihm der Betrug geraten. Und wird sich in seinem Herzen erheben und durch Wohlfahrt wird er viele verderben und wird sich auflehnen wider den Fursten aller Fursten. Aber er wird ohne Hand zerbrochen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Dies Gesicht vom Abend und Morgen, das dir gesagt ist, das ist wahr; aber du sollst das Gesicht heimlich halten, denn es ist noch eine lange Zeit dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Und ich, Daniel, ward schwach und lag etliche Tage krank. Danach stand ich auf und richtete aus des Konigs Geschafte. Und verwunderte mich des Gesichts; und niemand war, der mir\'s berichtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Im ersten Jahr Darius, des Sohnes Ahasveros, aus der Meder Stamm, der uber das Konigreich der Chaldaer Konig ward,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'in demselbigen ersten Jahr seines Konigreichs merkte ich, Daniel, in den Buchern auf die Zahl der Jahre, davon der HERR geredet hatte zum Propheten Jeremia, daß Jerusalem sollte siebenzig Jahre wüste liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Und ich kehrete mich zu Gott dem HERRN, zu beten und zu flehen, mit Fasten, im Sack und in der Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Ich betete aberzu dem HERRN, meinem Gott, bekannte und sprach: Ach, lieber HERR, du grafter und schrecklicher Gott, der du Bund und Gnade haltst denen, die dich lieben und deine Gebote halten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'wir haben gesundigt, unrecht getan, sind gottlos gewesen und abtrunnig worden; wir sind von deinen Geboten und Rechten gewichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Wir gehorchten nicht deinen Knechten, den Propheten, die in deinem Namen unsern Konigen, Fursten, Vatern und allem Volk im Lande predigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Du, HERR, bist gerecht, wir aber müssen uns schamen, wie es denn jetzt gehet denen von Juda und denen von Jerusalem und dem ganzen Israel, beide, denen, die nahe und feme sind, in alien Landen, dahin du uns verstoften hast urn ihrer Missetat willen, die sie an dir begangen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja, HERR, wir, unsere Konige, unsere Fursten und unsere Vater mussen uns schamen, daß wir uns an dir versundiget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Dein aber, HERR, unser Gott, ist die Barmherzigkeit und Vergebung. Denn wir sind abtrunnig worden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'und gehorchten nicht der Stimme des HERRN, unsers Gottes, daß wir gewandelt hatten in seinem Gesetz welches er uns vorlegte durch seine Knechte, die Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'sondern das ganze Israel ubertrat dein Gesetz und wichen ab, daß sie deiner Stimme nicht gehorchten. Daher trifft uns auch der Fluch und Schwur, der geschrieben stehet im Gesetz Mose, des Knechtes Gottes, daß wir an ihm gesundiget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Und er hat seine Worte gehalten, die er geredet hat wider uns und unsere Richter, die uns richten sollten, daß er solch graft Ungluck uber uns hat gehen lassen, daß desgleichen unter allem Himmel nicht geschehen ist, wie uber Jerusalem geschehen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Gleichwie es geschrieben stehet im Gesetz Mose, so ist all dies grofte Ungluck uber uns gegangen. So beteten wir auch nicht vor dem HERRN, unserm Gott, daß wir uns von den Sünden bekehreten und deine Wahrheit vernahmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Darum ist der HERR auch wacker gewesen mit diesem Ungluck und hat es uber uns gehen lassen. Denn der HERR, unser Gott, ist gerecht in alien seinen Werken, die er tut; denn wir gehorchten seiner Stimme nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Und nun, HERR, unser Gott, der du dein Volk aus Agyptenland gefuhret hast mit starker Hand und hast dir einen Namen gemacht, wie er jetzt ist: wir haben ja gesundiget und sind leider gottlos gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ach HERR, urn aller deiner Gerechtigkeit willen wende ab deinen Zorn und Grimm von deiner Stadt Jerusalem und deinem heiligen Berge! Denn urn unserer Sünde willen und urn unserer Vater Missetat willen tragt Jerusalem und dein Volk Schmach bei alien, die urn uns her sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Und nun, unser Gott, hore das Gebet deines Knechts und sein Flehen und siehe gnadiglich an dein Heiligtum, das verstoret ist, urn des HERRN willen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Neige deine Ohren, mein Gott, und hore, tue deine Augen auf und siehe, wie wir verstort sind, und die Stadt, die nach deinem Namen genannt ist! Denn wir liegen vor dir mit unserm Gebet, nicht auf unsere Gerechtigkeit, sondern auf deine grofte Barmherzigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Ach HERR, hore, ach HERR, sei gnadig, ach HERR, merke auf und tue es und verzeuch nicht um dein selbst willen, mein Gott! Denn deine Stadt und dein Volk ist nach deinem Namen genannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Als ich noch so redete und betete und meine und meines Volks Israel Sünde bekannte und lag mit meinem Gebet vor dem HERRN, meinem Gott, um den heiligen Berg meines Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'eben da ich so redete in meinem Gebet, flog daher der Mann Gabriel, den ich vorhin gesehen hatte im Gesicht, und ruhrete mich an um die Zeit des Abendopfers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Und er berichtete mir und redete mit mir und sprach: Daniel, jetzt bin ich ausgegangen, dir zu berichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Denn da du anfingest zu beten, ging dieser Befehl aus, und ich komme darum, daß ich dir\'s anzeige; denn du bist lieb und wert. So merke nun darauf, daß du das Gesicht verstehest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siebenzig Wochen sind bestimmt uber dein Volk und uber deine heilige Stadt, so wird dem Ubertreten gewehret und die Sunde zugesiegelt und die Missetat versohnet und die ewige Gerechtigkeit gebracht und die Gesichte und Weissagung zugesiegelt und der Allerheiligste gesalbet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'So wisse nun und merke: Von der Zeit an, so ausgehet der Befehl, daß Jerusalem soil wiederum gebauet werden, bis auf Christum, den Fursten, sind sieben Wochen und zweiundsechzig Wochen, so werden die Gassen und Mauern wieder gebauet werden, wiewohl in kummerlicher Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Und nach den zweiundsechzig Wochen wird Christus ausgerottet werden und nichts mehr sein. Und ein Volk des Fursten wird kommen und die Stadt und das Heiligtum verstoren, dati es ein Ende nehmen wird wie durch eine Flut; und bis zum Ende des Streits wird\'s wüst bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Er wird aber vielen den Bund starken eine Woche lang. Und mitten in der Woche wird das Opfer und Speisopfer aufhoren. Und bei den Flugeln werden stehen Greuel der Verwustung; und ist beschlossen, daß bis ans Ende uber die Verwustung triefen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Im dritten Jahr des Konigs Kores aus Persien ward dem Daniel, der Beltsazar heißt, etwas offenbaret, das gewiß ist und von großen Sachen; und er merkte darauf und verstund das Gesicht wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Zurselbigen Zeit war ich, Daniel, traurig drei Wochen lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Ich aß keine niedliche Speise, Fleisch und Wein kam in meinen Mund nicht; und salbete mich auch nie, bis die drei Wochen urn waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Am vierundzwanzigsten Tage des ersten Monden war ich, bei dem großen Wasser Hiddekel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'und hub meine Augen auf und sah, und siehe, da stund ein Mann in Leinwand und hatte einen guldenen Gürtel urn seine Lenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Sein Leib war wie ein Turkis, sein Antlitz sah wie ein Blitz, seine Augen wie eine feurige Fackel, seine Arme und Fuße wie ein gluhend Erz, und seine Rede war wie ein groß Geton.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ich, Daniel, aber sah solch Gesicht alleine, und die Manner, so bei mir waren, sahen\'s nicht; doch fiel ein groß Schrecken uber sie, daß sie flohen und sich verkrochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Und ich blieb alleine und sah dies große Gesicht. Es blieb aber keine Kraft in mir, und ich ward sehr ungestalt und hatte keine Kraft mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Und ich horete seine Rede; und indem ich sie horete, sank ich nieder auf mein Angesicht zur Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Und siehe, eine Hand ruhrete mich an und half mir auf die Kniee und auf die Hande');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'und sprach zu mir: Du lieber Daniel, merke auf die Worte, die ich mit dir rede, und richte dich auf; denn ich bin jetzt zu dir gesandt. Und da er solches mit mir redete, richtete ich mich auf und zitterte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Und er sprach zu mir: Furchte dich nicht, Daniel; denn von dem ersten Tage an, da du von Herzen begehretest zu verstehen, und dich kasteietest vor deinem Gott, sind deine, Worte erhoret; und ich bin kommen urn deinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Aber der Fürst des Konigreichs in Persienland hat mireinundzwanzig Tage widerstanden; und siehe, Michael, der vornehmsten Fursten einer, kam mir zu Hilfe; da behielt ich den Sieg bei den Konigen in Persien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Nun aber komme ich, daß ich dir berichte, wie es deinem Volk hernach gehen wird; denn das Gesicht wird nach etlicher Zeit geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Und als er solches mit mir redete, schlug ich mein Angesicht nieder zur Erde und schwieg stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Und siehe, einer, gleich einem Menschen, ruhrete meine Lippen an. Da tat ich meinen Mund auf und redete und sprach zu dem, der vor mir stund: Mein Herr, meine Gelenke beben mir uber dem Gesicht, und ich habe keine Kraft mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Und wie kann der Knecht meines Herm mit meinem Herm reden, weil nun keine Kraft mehr in mir ist, und habe auch keinen Odem mehr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Da ruhrete mich abermal an einer, gleichwie ein Mensch gestaltet, und starkte mich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'und sprach: Furchte dich nicht, du lieber Mann! Friede sei mit dir; und sei getrost, sei getrost! Und als er mit mir redete, ermannete ich mich und sprach: Mein Herr, rede; denn du hast mich gestarkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Und er sprach: Weißt du auch, warum ich zu dir kommen bin? Jetzt will ich wieder hin und mit dem Fursten in Persienland streiten; aberwenn ich wegziehe, siehe, so wird der Fürst aus Griechenland kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Doch will ich diranzeigen, was geschrieben ist, das gewißlich geschehen wird. Und ist keiner, der mir hilft wider jene denn euer Fürst Michael.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Denn ich stund auch bei ihm im ersten Jahr Darius, des Meders, daß ich ihm hülfe und ihn starkete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Und nun will ich dir anzeigen, was gewiß geschehen soil. Siehe, es werden noch drei Konige in Persien stehen; der vierte aber wird großern Reichtum haben denn alle andern; und wenn er in seinem Reichtum am machtigsten ist, wird er alles wider das Konigreich in Griechenland erregen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Danach wird ein machtiger Konig aufstehen und mit großer Macht herrschen, und was er will, wird er ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Und wenn er aufs hochste kommen ist, wird sein Reich zerbrechen und sich in die vier Winde des Himmels zerteilen, nicht auf seine Nachkommen, auch nicht mit solcher Macht, wie seine gewesen ist; denn sein Reich wird ausgerottet und Fremden zuteil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Und der Konig gegen Mittag, welcher ist seiner Fursten einer, wird machtig werden; aber gegen ihn wird einer auch machtig sein und herrschen, welches FHerrschaft wird groli sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Nach etlichen Jahren aber werden sie sich miteinander befreunden; und die Tochter des Konigs gegen Mittag wird kommen zum Konige gegen Mitternacht, Einigkeit zu machen. Aber sie wird nicht bleiben bei der Macht des Arms, dazu ihr Same auch nicht stehen bleiben, sondern sie wird ubergeben samt denen, die sie gebracht haben, und mit dem Kinde und dem, der sie eine Weile machtig gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Es wird aber der Zweige einer von ihrem Stamm aufkommen, der wird kommen mit FHeereskraft und dem Konige gegen Mitternacht in seine Feste fallen; und wird\'s, ausrichten und siegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Auch wird er ihre Gotter und Bilder samt den kostlichen Kleinoden, beide, silbernen und guldenen wegfuhren nach Agypten und etliche Jahre vor dem Konige gegen Mitternacht wohl stehen bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Und wenn er durch desselbigen Konigreich gezogen ist, wird erwiederum in sein Land ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Aber seine Sohne werden erzurnen und grolie Fleere zusammenbringen; und der eine wird kommen und wie eine Flut daherfahren und jenen wiederum vor seinen Festen reizen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Da wird der Konig gegen Mittag ergrimmen und ausziehen und mit dem Konige gegen Mitternacht streiten und wird solchen grolien Haufen zusammenbringen, daß ihm jener Haufe wird in seine Hand gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Und wird denselbigen Haufen wegfuhren. Des wird sich sein Herz erheben, daß er so viel tausend daniedergelegt hat; aber damit wird er sein nicht machtig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Denn der Konig gegen Mitternacht wird wiederum einen groliern Haufen zusammenbringen, denn der vorige war; und nach etüchen Jahren wird er daherziehen mit grower Heereskraft und mit groliern Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Und zur selbigen Zeit werden sich viele wider den Konig gegen Mittag setzen; auch werden sich etliche Abtrünnige aus deinem Volk erheben und die Weissagung erfüllen und werden fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Also wird der Konig gegen Mitternacht daherziehen und Schutte machen und feste Stadte gewinnen; und die Mittagsarme werden\'s nicht konnen wehren, und sein bestes Volk werden nicht konnen widerstehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'sondern erwird, wenn er an ihn kommt, seinen Willen schaffen; und niemand wird ihm widerstehen mogen. Erwird auch in das werte Land kommen und wird\'s vollenden durch seine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Und wird sein Angesicht richten, daß er mit Macht seines ganzen Konigreichs komme. Aber er wird sich mit ihm vertragen und wird ihm seine Tochter zum Weibe geben, daß er ihn verderbe; aber es wird ihm nicht geraten, und wird nichts daraus werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Danach wird er sich kehren wider die Inseln und derselbigen viele gewinnen. Aberein Furst wird ihn lehren aufhoren mit Schmahen, daß er ihn nicht mehr schmahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Also wird er sich wiederum kehren zu den Festen seines Landes und wird sich stolien und fallen, daß man ihn nirgend finden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Und an seiner Statt wird einer aufkommen, der wird in koniglichen Ehren sitzen wie ein Scherge. Aber nach wenig Tagen wird er brechen, doch weder durch Zorn noch durch Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'An des Statt wird aufkommen ein Ungeachteter, welchem die Ehre des Konigreichs nicht bedacht war; der wird kommen, und wird ihm gelingen und das Konigreich mit sülien Worten einnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Und die Arme, die wie eine Flut daherfahren, werden vor ihm wie mit einer Flut uberfallen und zerbrochen werden, dazu auch der Furst, mit dem der Bund gemacht war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Denn nachdem er mit ihm befreundet ist, wird er listiglich gegen ihn handeln; und wird heraufziehen und mitgeringem Volk ihn uberwaltigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Und wird ihm gelingen, daß er in die besten Stadte des Landes kommen wird; und wird\'s also ausrichten, das seine Vater noch seine Voreltern nicht tun konnten mit Rauben, Plundern und Ausbeuten; und wird nach den allerfestesten Stadten trachten, und das eine Zeitlang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Und er wird seine Macht und sein Herz wider den Konig gegen Mittag erregen mit grolier Heereskraft. Da wird der Konig gegen Mittag gereizet werden zum Streit mit einer grolien, machtigen Heereskraft. Aber er wird nicht bestehen; denn es werden Verratereien wider ihn gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Und eben, die sein Brot essen, die werden ihn helfen verderben und sein Heer unterdrucken, daß gar viele erschlagen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Und beider Konige Herz wird denken, wie sie einander Schaden tun, und werden doch liber einem Tisch falschlich miteinander reden. Es wird ihnen aber fehlen; denn das Ende ist noch auf eine andere Zeit bestimmt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Danach wird erwiederum heimziehen mit groliem Gut und sein Herz richten wider den heiligen Bund; da wird er etwas ausrichten und also heim in sein Land ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Danach wird er zu gelegener Zeit wieder gegen Mittag ziehen; aber es wird ihm zum andernmal nicht geraten wie zum erstenmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Denn es werden Schiffe aus Chittim wider ihn kommen, daß erverzagen wird und umkehren muli. Da wird er wider den heiligen Bund ergrimmen und wird\'s ausrichten; und wird sich umsehen und an sich ziehen, die den heiligen Bund verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Und es werden seine Arme daselbst stehen; die werden das Heiligtum in der Feste entweihen und das tagliche Opfer abtun und einen Greuel der Wustung aufrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Und er wird heucheln und gute Worte geben den Gottlosen, so den Bund ubertreten. Aber das Volk, so ihren Gott kennen, werden sich ermannen und es ausrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Und die Verstandigen im Volk werden viel andere lehren; daruber werden sie fallen durch Schwert, Feuer, Gefangnis und Raub eine Zeitlang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Und wenn sie so fallen, wird ihnen dennoch eine kleine Hilfe geschehen. Aber viele werden sich zu ihnen tun betrüglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Und der Verstandigen werden etliche fallen, auf daß sie bewahret, rein und lauter werden, bis dati es ein Ende habe; denn es ist noch eine andere Zeit vorhanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Und der Konig wird tun, was er will, und wird sich erheben und aufwerfen wider alles, das Gott ist; und wider den Gott alter Gotter wird er greulich reden; und wird ihm gelingen, bis der Zorn aus sei; denn es ist beschlossen, wie lange es wahren soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Und seiner Vater Gott wird er nicht achten; er wird weder Frauenliebe noch einiges Gottes achten, denn erwird sich wider alles aufwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Aber an des Statt wird er seinen Gott Mauftim ehren; denn erwird einen Gott, davon seine Vater nichts gewuftt haben, ehren mit Gold, Silber, Edeistein und Kleinoden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Und wird denen, so ihm helfen starken Mauftim mit dem fremden Gott, den er erwahlet hat, grofte Ehre tun und sie zu Herren machen uber grofte Güter und ihnen das Land zu Lohn austeilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Und am Ende wird sich der Konig gegen Mittag mit ihm stoften; und der Konig gegen Mitternacht wird sich gegen ihn strauben mit Wagen, Reitern und viel Schiffen; und wird in die Lander fallen und verderben und durchziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Und wird in das werte Land fallen, und viele werden umkommen. Diese aber werden seiner Hand entrinnen: Edom, Moab und die Erstlinge der Kinder Ammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Und er wird seine Macht in die Lander schicken, und Agypten wird ihm nicht entrinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'sondern er wird durch seinen Zug herrschen uber die guldenen und silbernen Schatze und uber alle Kleinode Agyptens, Libyens und der Mohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Es wird ihn aber ein Geschrei erschrecken von Morgen und Mitternacht; und erwird mit groftem Grimm ausziehen, willens, viele zu vertilgen und zu verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Und er wird das Gezelt seines Palasts aufschlagen zwischen zweien Meeren urn den werten heiligen Berg, bis mit ihm ein Ende werde; und niemand wird ihm helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Zurselbigen Zeit wird der grofte Fürst Michael, der fur dein Volk stehet, sich aufmachen. Denn es wird eine solche trubselige Zeit sein, als sie nicht gewesen ist, seit dafi Leute gewesen sind, bis auf dieselbige Zeit. Zur selbigen Zeit wird dein Volk errettet werden, alle, die im Buch geschrieben stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Und viele, so unter der Erde schlafen liegen, werden aufwachen, etliche zum ewigen Leben, etliche zurewigen Schmach und Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Die Lehrer aber werden leuchten wie des Himmels Glanz und die, so viele zur Gerechtigkeit weisen, wie die Sterne immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Und nun, Daniel, verbirg diese Worte und versiegele diese Schrift bis auf die letzte Zeit, so werden viele druber kommen und groften Verstand finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Und ich, Daniel, sah, und siehe, es stunden zween andere da, einer an diesem Ufer des Wassers, der andere an jenem Ufer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Und ersprach zu dem in leinenen Kleidern, der oben am Wasser stund: Wann will\'s denn ein Ende sein mit solchen Wundern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Und ich horete zu dem in leinenen Kleidern, der oben am Wasser stund; und er hub seine rechte und linke Hand auf gen Himmel und schwur bei dem, so ewiglich lebet, daß es eine Zeit und etliche Zeiten und eine halbe Zeit wahren soli; und wenn die Zerstreuung des heiligen Volks ein Ende hat, soil solches alles geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Und ich horete es: aber ich verstund es nicht und sprach: Mein Herr, was wird danach werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Er aber sprach: Gehe hin, Daniel; denn es ist verborgen und versiegelt bis auf die letzte Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Viele werden gereiniget, gelautert und bewahret werden; und die Gottlosen werden gottlos Wesen führen, und die Gottlosen werden\'s nicht achten; aber die Verstandigen werden\'s achten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Und von der Zeit an, wenn das tagliche Opfer abgetan und ein Greuel der Wustung dargesetzt wird, sind tausend zweihundert und neunzig Tage:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Wohl dem, der da erwartet und erreichet tausend dreihundert und funfunddreifüg Tage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Du aber, Daniel, gehe hin, bis das Ende komme, und ruhe, daß du aufstehest in deinem Teil am Ende der Tage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Dies ist das Wort des HERRN, das geschehen ist zu Hosea, dem Sohn Beheris, zur Zeit Usias, Jothams, Ahas und Hiskias, der Konige Judas, und zu der Zeit Jerobeams, des Sohns Joas, des Konigs Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Und da der HERR anting zu reden durch Hosea, sprach erzu ihm: Gehe hin und nimm ein Hurenweib und Hurenkinder; denn das Land lauft vom HERRN der Hurerei nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Und erging hin und nahm Gomer, die Tochter Diblaims, welche ward schwanger und gebar ihm einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Und der HERR sprach zu ihm: Heiße ihn Jesreel; denn es ist noch um eine kleine Zeit, so will ich die Blutschulden in Jesreel heimsuchen uber das Haus Jehu und will\'s mit dem Konigreich des Hauses Israel ein Ende machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Zur selbigen Zeit will ich den Bogen Israels zerbrechen im Tal Jesreel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Und sie ward abermal schwanger und gebar eine Tochter. Und er sprach zu ihm: Hei Ee sie Lo-Ryhamo; denn ich will mich nicht mehr uber das Haus Israel erbarmen, sondern ich will sie wegwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Doch will ich mich erbarmen uber das Haus Juda und will ihnen helfen durch den HERRN, ihren Gott; ich will ihnen aber nicht helfen durch Bogen, Schwert, Streit, Roli Oder Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Und da sie hatte Lo-Ryhamo entwohnet, ward sie wieder schwanger und gebar einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Und er sprach: Heil Le ihn Lo-Ammi; denn ihr seid nicht mein Volk, so will ich auch nicht der Eure sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Es wird aber die Zahl der Kinder Israel sein wie der Sand am Meer, den man weder messen noch zahlen kann. Und soil geschehen an dem Ort, da man zu ihnen gesagt hat: Ihr seid nicht mein Volk, wird man zu ihnen sagen: O ihr Kinder des lebendigen Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Denn eswerden die Kinder Juda und die Kinder Israel zuhaufe kommen und werden sich miteinander an ein Haupt halten und aus dem Lande heraufziehen; denn der Tag Jesreels wird ein grower Tag sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Saget euren Brudern, sie sind mein Volk; und zu eurer Schwester, sie sei in Gnaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Sprechet das Urteil uber eure Mutter, sie sei nicht mein Weib, und ich will sie nicht haben. Hei Et sie ihre Hurerei von ihrem Angesichte wegtun und ihre Ehebrecherei von ihren Brusten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'auf daß ich sie nicht nackend ausziehe und darstelle, wie sie war, da sie geboren ward, und ich sie nicht mache wie eine Wüste und wie ein dürres Land, da E ich sie nicht Durst sterben lasse,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'und mich ihrer Kinder nicht erbarme; denn sie sind Hurenkinder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'und ihre Mutter ist eine Hure, und die sie getragen hat, halt sich schandlich und spricht: Ich will meinen Buhlen nachlaufen, die mirgeben Brot, Wasser, Wolle, Flachs, 01 und Trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Darum siehe, ich will deinen Weg mit Dornen vermachen und eine Wand davor ziehen, da E sie ihren Steig nicht finden soil,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'und wenn sie ihren Buhlen nachlauft, da E sie die nicht ergreifen, und wenn sie die suchet, nicht finden konne und sagen müsse: Ich will wiederum zu meinem vorigen Manne gehen, da mir besser war, denn mirjetzt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Denn sie will nicht wissen, da E ich es sei, der ihr gibt Korn, Most, 01 und ihr viel Silber und Gold gegeben habe, das sie haben Baal zu Ehren gebraucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Darum will ich mein Korn und Most wieder nehmen zu seiner Zeit und meine Wolle und Flachs entwenden, damit sie ihre Scham bedecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Nun will ich ihre Schande aufdecken vor den Augen ihrer Buhlen, und niemand soil sie von meiner Hand erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Und ich will\'s ein Ende machen mit alien ihren Freuden, Festen, Neumonden, Sabbaten und alien ihren Feiertagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Ich will ihre Weinstocke und Feigenbaume wüst machen, weil sie sagt: Das ist mein Lohn, den mir meine Buhlen geben. Ich will einen Wald daraus machen, da E es die wilden Tiere fressen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Also will ich heimsuchen uber sie die Tage Baalim, denen sie Rauchopfer tut, und schmückt sich mit Stirnspangen und Halsbandern und lauft ihren Buhlen nach und vergi Et mein, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Darum siehe, ich will sie locken und will sie in eine Wüste führen und freundlich mit ihr reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Da will ich ihr geben ihre Weinberge aus demselben Ort und das Tal Achor, die Hoffnung aufzutun. Und daselbst wird sie singen wie zur Zeit ihrer Jugend, da sie aus Agyptenland zog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Alsdann spricht der HERR, wirst du mich hei Een mein Mann und mich nicht mehr mein Baal hei Een.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Denn ich will die Namen der Baalim von ihrem Munde wegtun, daß man derselbigen Namen nicht mehrgedenken soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Und ich will zur selbigen Zeit ihnen einen Bund machen mit den Tieren auf dem Felde, mit den Vogeln unter dem Himmel und mit dem Gewürme auf Erden; und will Bogen, Schwert und Krieg vom Lande zerbrechen und will sie sicher wohnen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Ich will mich mit dirverloben in Ewigkeit; ich will mich mit dir vertrauen in Gerechtigkeit und Gericht, in Gnade und Barmherzigkeit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'ja, im Glauben will ich mich mit dir verloben; und du wirst den HERRN erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Zur selbigen Zeit, spricht der HERR, will ich erhoren; ich will den Himmel erhoren; und der Himmel soli die Erde erhoren');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 24, 'und die Erde soil Korn, Most und 01 erhoren; und dieselbigen sollen Jesreel erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 25, 'Und ich will mir sie auf Erden zum Samen behalten und mich erbarmen uber die, so in Ungnaden war, und sagen zu dem, das nicht mein Volk war: Du bist mein Volk; und es wird sagen: Du bist mein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Und der HERR sprach zu mir: Gehe noch eins hin und buhle urn das buhlerische und ehebrecherische Weib, wie denn der HERR urn die Kinder Israel buhlet, und sie doch sich zu fremden Gottern kehren und buhlen urn eine Kanne Weins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Und ich ward mit ihr eins urn fünfzehn Silberlinge und anderthalb Homer Gerste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Und sprach zu ihr: Halte dich mein eine Zeitlang und hure nicht und lali keinen andern zu dir; denn ich will mich auch dein halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Denn die Kinder Israel werden lange Zeit ohne Konig, ohne Fursten, ohne Opfer, ohne Altar, ohne Leibrock und ohne Heiligtum bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Danach werden sich die Kinder Israel bekehren und den HERRN, ihren Gott, und ihren Konig David suchen und werden den HERRN und seine Gnade ehren in der letzten Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Horet, ihr Kinder Israel, des HERRN Wort; denn der HERR hat Ursach, zu schelten, die im Lande wohnen. Denn es ist keine Treue, keine Liebe, kein Wort Gottes im Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'sondern Gotteslastern, Lugen, Morden, Stehlen und Ehebrechen hat uberhandgenommen, und kommt eine Blutschuld nach der andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Darum wird das Land jammerlich stehen und alien Einwohnern ubel gehen; denn es werden auch die Tiere auf dem Felde und die Vogel unter dem Himmel und die Fische im Meer weggeraffet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Doch man darf nicht schelten, noch jemand strafen; denn mein Volk ist wie die, so die Priester schelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Darum sollst du bei Tage fallen, und der Prophet des Nachts neben dir fallen; also will ich deine Mutter hinrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mein Volk ist dahin, darum daü es nicht lernen will. Denn du verwirfst Gottes Wort, darum will ich dich auch verwerfen, daß du nicht mein Priester sein sollst. Du vergissest des Gesetzes deines Gottes, darum will ich auch deiner Kinder vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Je mehr ihrer wird, je mehr sie wider mich sundigen; darum will ich ihre Ehre zuschanden machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Sie fressen die Sundopfer meines Volks und sind begierig nach ihren Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Darum soil es dem Volk gleichwie dem Priester gehen; denn ich will ihr Tun heimsuchen und ihnen vergelten, wie sie verdienen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'daß sie werden essen und nicht satt werden, Hurerei treiben, und soil ihnen nicht gelingen, darum daß sie den HERRN verlassen haben und ihn nicht achten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Hurerei, Wein und Most machen toll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mein Volkfragt sein Holz, und sein Stab soil ihm predigen; denn der Hurereigeist verfuhret sie, daß sie wider ihren Gott Hurerei treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Oben auf den Bergen opfern sie und auf den Hügeln rauchern sie, unter den Eichen, Linden und Buchen; denn die haben feine Schatten. Darum werden eure Tochter auch zu Huren und eure Braute zu Ehebrecherinnen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Und ich will\'s auch nicht wehren, wenn eure Tochter und Braute geschandet und zu Huren werden, weil ihr einen andern Gottesdienst anrichtet mit den Huren und opfert mit den Bubinnen. Denn das torichte Volk will geschlagen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Willstdu, Israel, ja huren, daß sich doch nur Juda nicht auch verschulde! Gehet nicht hin gen Gilgal und kommet nicht hinauf gen Beth-Aven und schworet nicht: So wahr der HERR lebet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Denn Israel lauftwie eine tolle Kuh, so wird sie auch der HERR weiden lassen wie ein Lamm in der Irre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Denn Ephraim hat sich zu den Gotzen gestellet; so lali ihn hinfahren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Sie haben sich in die Schwelgerei und Hurerei gegeben; ihre Herren haben Lust dazu, daß sie Schande anrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Der Wind mitseinen Flügeln wird siegebunden treiben und müssen uber ihrem Opfer zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'So horet nun dies, ihr Priester, und merke auf, du Haus Israel, und nimm zu Ohren, du Haus des Konigs; denn es wird eine Strafe uber euch gehen, die ihr ein Strick zu Mizpa und ein ausgespannet Netz zu Thabor worden seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Mit Schlachten vertiefen sie sich in ihrem Verlaufen, darum muli ich sie allesamt strafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ich kenne Ephraim wohl, und Israel ist vor mir nicht verborgen, daß Ephraim nun eine Hure ist, und Israel ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Sie denken nicht danach, daß sie sich kehreten zu ihrem Gott; denn sie haben einen Hurengeist in ihrem Herzen und lehren vom HERRN nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Darum soil die Hoffart Israels vor ihrem Angesicht gedemütiget werden, und sollen beide, Israel und Ephraim, fallen urn ihrer Missetat willen; auch soli Juda samt ihnen fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Alsdann werden sie kommen mit ihren Schafen und Rindern, den HERRN zu suchen, aber nicht finden; denn er hat sich von ihnen gewandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Sie verachten den HERRN und zeugen fremde Kinder; darum wird sie auch der Neumond fressen mit ihrem Erbteil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Ja, blaset Posaunen zu Gibea, ja, trommetet zu Rama, ja rufet zu Beth-Aven: Hinter dir, Benjamin!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Denn Ephraim soil zur Wuste werden zur Zeit, wenn ich sie strafen werde. Davor hab ich die Stamme Israels treulich gewarnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Die Fursten Judas sind gleich denen, so die Grenze verrucken; darum will ich meinen Zorn uber sie ausschutten wie Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Ephraim leidet Gewalt und wird geplagt; daran geschiehet ihm recht; denn er hat sich gegeben auf (Menschen-)Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Ich bin dem Ephraim eine Motte und dem Hause Juda eine Made.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Und da Ephraim seine Krankheit und Juda seine Wunden fuhlete, zog Ephraim hin zu Assur und schickte zum Konige zu Jareb; aber er konnte euch nicht helfen noch eure Wunden heilen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Denn ich bin dem Ephraim wie ein Lowe, und dem Hause Juda wie ein junger Lowe. Ich, ich zerreifie sie und gehe davon und führe sie weg, und niemand kann sie retten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ich will wiederum an meinen Ort gehen, bis sie ihre Schuld erkennen und mein Angesicht suchen; wenn\'s ihnen ubel gehet, so werden sie mich fruhe suchen müssen (und sagen):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Kommt, wirwollen wiederzum HERRN! Denn er hat uns zerrissen, erwird uns auch heilen; er hat uns geschlagen, erwird uns auch verbinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Er macht uns lebendig nach zween Tagen, erwird uns am dritten Tage aufrichten, daß wir vor ihm leben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Dann werden wir acht darauf haben und fleißig sein, da($ wir den HERRN erkennen. Denn erwird hervorbrechen wie die schone Morgenrote und wird zu uns kommen wie ein Regen, wie ein Spatregen, der das Land feuchtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Wie will ich dir so wohl tun, Ephraim! Wie will ich dir so wohl tun, Juda! Denn die Gnade, so ich euch erzeigen will, wird sein wie eine Tauwolke des Morgens und wie ein Tau, der frühmorgens sich ausbreitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Darum schlage ich sie durch die Propheten und tote sie durch meines Mundes Rede, dafi dein Recht ans Licht komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Denn ich habe Lust an der Liebe und nicht am Opfer und am Erkenntnis Gottes und nicht am Brandopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Aber sie ubertreten den Bund, wie Adam; darin verachten sie mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Denn Gilead ist eine Stadt voll Abgotterei und Blutschulden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Und die Priester samt ihrem Haufen sind wie die Stroter, so da lauern auf die Leute und würgen auf dem Wege, der gen Sichem gehet; denn sie tun, was sie wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Ich sehe im Hause Israel, da mir vor grauet; denn da huret Ephraim, so verunreiniget sich Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Aber Juda wird noch eine Ernte vor sich haben, wenn ich meines Volks Gefangnis wenden werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Wenn ich Israel heilen will, so findet sich erst die Sunde Ephraims und die Bosheit Samaria, wie sie Abgotterei treiben. Denn wiewohl sie unter sich selbst mit Dieben und auswendig mit Raubern geplagt sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'dennoch wollen sie nicht merken, daß ich alle ihre Bosheit merke. Ich sehe aber ihr Wesen wohl, das sie ailenthalben treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Sie vertrosten den Konig durch ihre Bosheit und die Fursten durch ihre Lugen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'und sind allesamt Ehebrecher, gleichwie ein Backofen, den der Backer heizet, wenn er hat ausgeknetet, und lafit den Teig durchsauern und aufgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Heute ist unsers Konigs Fest (sprechen sie), da fahen die Fursten an vom Wein toll zu werden; so zeucht er die Spotter zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Denn ihr Herz ist in heilier Andacht wie ein Backofen, wenn sie opfern und die Leute betrugen; aber ihr Backer schlaft die ganze Nacht, und des Morgens brennet er lichterlohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Noch sind sie so heifier Andacht wie ein Backofen. Obgleich ihre Richter aufgefressen werden und alle ihre Konige fallen, noch ist keiner unter ihnen, der mich anrufe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraim menget sich unter die Volker; Ephraim ist wie ein Kuchen, den niemand umwendet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'sondern Fremde fressen seine Kraft, noch will er\'s nicht merken. Er hat auch graue Haare gekriegt; noch will er\'s nicht merken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Und die Hoffart Israels wird vor ihren Augen gedemutiget; noch bekehren sie sich nicht zum HERRN, ihrem Gott, fragen auch nicht nach ihm in diesem allem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Denn Ephraim ist wie eine verlockte Taube, die nichts merken will. Jetzt rufen sie Agypten an, dann laufen sie zu Assur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Aber indem sie hin und her laufen, will ich mein Netz uber sie werfen und herunterrucken wie die Vogel unter dem Himmel; ich will sie strafen, wie man prediget in ihrer Sammlung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Wehe ihnen, daß sie von mirweichen! Sie müssen verstoret werden, denn sie sind abtrunnig von mir worden. Ich wollte sie wohl erlosen, wenn sie nicht wider mich Lugen lehreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'So rufen sie mich auch nicht an von Herzen, sondern loren auf ihren Lagern. Sie versammeln sich um Korn und Mosts willen und sind mir ungehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Ich lehre sie und starke ihren Arm; abersie denken Boses von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Sie bekehren sich, aber nicht recht, sondern sind wie ein falscher Bogen; darum werden ihre Fursten durchs Schwert fallen; ihr Drauen soli in Agyptenland zum Spott werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Rufe laut wie eine Posaune (und sprich): Er kommt schon fiber das Haus des HERRN wie ein Adler, darum daü sie meinen Bund ubertreten und von meinem Gesetz abtrunnig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Werden sie dann zu mir schreien: Du bist mein Gott; wir kennen dich, Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel verwirft das Gute; darum mud sie der Feind verfolgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Sie machen Konige, aber ohne mich; sie setzen Fursten, und ich mull nicht wissen. Aus ihrem Silber und Gold machen sie Gotzen, daß sie ja bald ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Dein Kalb, Samaria, verstodt er; mein Zorn ist uber sie ergrimmet; es kann nicht lange stehen, sie müssen gestraft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Denn das Kalb ist aus Israel herkommen, und ein Werkmann hat\'s gemacht, und kann ja kein Gott sein; darum soil das Kalb Samaria zerpulvert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Denn sie saen Wind und werden Ungewitter einernten; ihre Saat soil nicht aufkommen und ihr Gewachs kein Mehl geben; und ob es geben würde, sollen\'s doch Fremde fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel wird aufgefressen; die Heiden gehen mit ihnen um wie mit einem unwerten Gefad,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'darum dad sie hinauf zum Assur laufen wie ein Wild in der Irre. Ephraim schenktden Buhlern und gibt den Heiden Tribut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Dieselben Heiden will ich nun fiber sie sammeln; sie sollen der Last des Konigs und der Fursten bald mfide werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Denn Ephraim hat der Altare viel gemacht zu sundigen; so sollen auch die Altare ihm zur Sfinde geraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Wenn ich ihm gleich viel von meinem Gesetz schreibe, so wird\'s geachtet wie eine fremde Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Dad sie nun viel opfern und Fleisch herbringen und essen es, so hat doch der HERR kein Gefallen daran, sondern erwill ihrer Missetat gedenken und ihre Sfinden heimsuchen, die sich zu Agypten kehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel vergidt seines Schopfers und bauet Kirchen, so macht Juda viel fester Stadte; aber ich will Feuer in seine Stadte schicken, welches soil seine Hauser verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Du darfst dich nicht freuen, Israel, noch rfihmen wie die Volker; denn du hurest wider deinen Gott, damit du suchest Hurenlohn, dad alle Tennen voll Getreide werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Darum so sollen dich die Tennen und Kelter nicht nahren, und der Most soil dirfehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Und sollen nicht bleiben im Lande des HERRN, sondern Ephraim mud wieder nach Agypten und mud in Assyrien, das unrein ist, essen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'daselbst sie dem HERRN kein Trankopfer vom Wein noch etwas zu Gefallen tun konnen. ihr Opfer soil sein wie der Betrubten Brot, an welchem unrein werden alle, die davon essen; denn ihr Brot müssen sie fur sich selbst essen, und soil nicht in des HERRN Haus gebracht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Was wollt ihr alsdann auf den Jahrzeiten und auf den Feiertagen des HERRN tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Siehe, sie müssen weg vordem Verstorer! Agypten wird sie sammeln, und Moph wird sie begraben. Nesseln werden wachsen, da jetzt ihr liebes Gotzensilber stehet, und Dornen in ihren Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Die Zeit der Heimsuchung ist kommen, die Zeit der Vergeltung; des wird Israel inne werden. Die Propheten sind Narren, und die Rottengeister sind wahnsinnig um deiner groflen Missetat und um der groden feindseligen Abgotterei willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Die Wachter in Ephraim hielten sich etwa an meinen Gott; aber nun sind sie Propheten, die Stricke legen auf alien ihren Wegen durch die feindselige Abgotterei im Hause ihres Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Sie verderben\'s zu tief, wie zur Zeit Gibeas; darum wird er ihrer Missetat gedenken und ihre Sfinde heimsuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Ich fand Israel in der Wüste wie Trauben und sah eure Vaterwie die ersten Feigen am Feigenbaum; aber hernach gingen sie zu Baal-Peor und gelobten sich dem schandlichen Abgott und wurden ja so greulich als ihre Buhlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Darum mud die Herrlichkeit Ephraims wie ein Vogel wegfliegen, dad sie weder gebaren noch tragen noch schwanger werden sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Und ob sie ihre Kinder gleich erzogen, will ich sie doch ohne Kinder machen, dad sie nicht Leute sein sollen. Auch wehe ihnen, wenn ich von ihnen bin gewichen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, als ich es ansehe, ist gepflanzet und hübsch wie Tyrus, mud aber nun ihre Kinder herauslassen dem Totschlager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'HERR, gib ihnen! Was willst du ihnen aber geben? Gib ihnen unfruchtbare Leiber und versiegene Brfiste!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Alle ihre Bosheit geschieht zu Gilgal, daselbst bin ich ihnen feind; und ich will sie auch um ihres bosen Wesens willen aus meinem Hause stoden und nicht mehr Liebe erzeigen; denn alle ihre Fursten sind Abtrünnige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ephraim ist geschlagen; ihre Wurzel ist verdorret, dad sie keine Frucht mehr bringen konnen. Und ob sie gebaren wurden, will ich doch die liebe Frucht ihres Leibes toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mein Gottwird sie verwerfen, darum, daß sie ihn nicht horen wollen, und müssen unter den Heiden in der Irre gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel ist ein verwusteter Weinstock; seine Frucht ist eben auch also. Soviel Früchte er hatte, soviel Altare hatte er gemacht. Wo das Land am besten war, da stifteten sie die schonsten Kirchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Ihr Herz ist zertrennet; nun wird sie ihre Schuld finden. Ihre Altare sollen zerbrochen, und ihre Kirchen sollen verstoretwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Alsdann mussen sie sagen: Wir haben keinen Konig; denn wir furchten den HERRN nicht, was kann uns der Konig nun helfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Sie schwuren vergeblich und machten einen Bund; und solcher Rat grünete auf alien Furchen im Felde wie Galle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Die Einwohner zu Samaria sorgen fur die Kalber zu Beth-Aven; denn sein Volk trauert urn ihn; über welchem doch seine Kamarim sich pflegten zu freuen seiner Herrlichkeit halben; denn es ist von ihnen weggeführet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Ja, das Kalb ist nach Assyrien gebracht, zum Geschenk dem Konige zu Jareb. Also muß Ephraim mit Schanden stehen, und Israel schandlich gehen mit seinem Vornehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Denn der Konig zu Samaria ist dahin wie ein Schaum auf dem Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Die Hohen zu Aven sind vertilget, damit sich Israel versündigte; Disteln und Dornen wachsen auf ihren Altaren. Und sie werden sagen: Ihr Berge, bedecket uns, und ihr Hügel, fallet über uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Israel, du hast seit der Zeit Gibeas gesündiget, dabei sind sie auch geblieben; aberes soil sie nicht des Streits zu Gibea gleichen ergreifen, so wider die bosen Leute geschah,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'sondern ich will sie züchtigen nach meinem Wunsch, daß Volker sollen fiber sie versammelt kommen, wenn ich sie werde strafen urn ihre zwo Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ephraim ist wie ein Kalb, gewohnt, daß es gerne drischet. Ich will ihm über seinen schonen Hals fahren; ich will Ephraim reiten, Juda soil pflügen und Jakob eggen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Darum saet euch Gerechtigkeit und erntet Liebe und pflüget anders, weil es Zeit ist, den HERRN zu suchen, bis daß er komme und regne über euch Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Denn ihr pflüget Boses und erntet Ubeltat und esset Lügenfrüchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Weil du dich denn verlassest auf dein Wesen und auf die Menge deiner Heiden, so soil sich ein Getümmel erheben in deinem Volk, daß alle deine Festen verstoretwerden. Gleichwie Salman verstorete das Haus Arbeels zur Zeit des Streits, da die Mutter über den Kindern zu Trümmern ging,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'ebenso soil\'s euch zu Bethel auch gehen urn euren großen Bosheit willen, daß der Konig Israels frühe morgens untergehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Da Israel jung war, hatte ich ihn lieb und rief ihn; meinen Sohn, aus Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Aber wenn man sie jetzt ruft, so wenden sie sich davon und opfern den Baalim und rauchern den Büdern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Ich nahm Ephraim bei seinen Armen und leitete ihn; aber sie merkten\'s nicht, wie ich ihnen half.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Ich ließ sie ein menschlich Joch ziehen und in Seilen der Liebe gehen und half ihnen das Joch an ihrem Halse tragen und gab ihnen Futter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'daß er sich ja nicht wieder sollte nach Agyptenland kehren. So ist nun Assur ihr Konig worden; denn sie wollen sich nicht bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Darum soli das Schwert fiber ihre Stadte kommen und soil ihre Riegel aufreiben und fressen urn ihres Vornehmens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Mein Volk ist müde, sich zu mir zu kehren; und wie man ihnen prediget, so richtet sich keiner auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Was soil ich aus dir machen, Ephraim? Soil ich dich schützen, Israel? Soli ich nicht billig ein Adama aus dir machen und dich wie Zeboim zurichten? Aber mein Herz ist anderes Sinnes, meine Barmherzigkeit ist zu brünstig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'daß ich nicht tun will nach meinem grimmigen Zorn, noch mich kehren, Ephraim gar zu verderben; denn ich bin Gott und nicht ein Mensch und bin der Heilige unter dir. Ich will aber nicht in die Stadt kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Alsdann wird man dem HERRN nachfolgen; und erwird brüllen wie ein Lowe; und wenn erwird brüllen, so werden erschrecken die, so gegen Abend sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Und die in Agypten werden auch erschrecken wie ein Vogel, und die im Lande Assur wie Tauben; und ich will sie in ihre Hauser setzen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'In Ephraim ist allenthalben Luge wider mich und im Hause Israel falscher Gottesdienst. Aber Juda halt noch test an Gott und am rechten heiligen Gottesdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Ephraim aber weidet sich vom Winde und lauft dem Ostwinde nach und macht taglich der Abgotterei und des Schadens mehr; sie machen mit Assur einen Bund und bringen Balsam nach Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Darum wird der HERR die Sache Judas führen und Jakob heimsuchen nach seinem Wesen und ihm vergelten nach seinem Verdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Ja (sagen sie), er hat im Mutterleibe seinen Bruder untertreten und von alien Kraften mit Gott gekampfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Er kampfte mit dem Engel und siegete, denn er weinete und bat ihn; daselbst hat er ihn ja zu Bethel funden und daselbst hat er mit uns geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Aberder HERR istder Gott Zebaoth; HERR ist sein Name.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'So bekehre dich nun zu deinem Gott, halte Barmherzigkeit und Recht und hoffe stets auf deinen Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Aber der Kaufmann hat eine falsche Waage in seiner Hand und betrugt gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Denn Ephraim spricht: Ich bin reich, ich habe genug; man wird mir keine Missetat finden in aller meiner Arbeit, das Sunde sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Ich aber, der HERR, bin dein Gott aus Agyptenland her, und der ich dich noch in den Hutten wohnen lasse, wie man zur Jahrzeit pfleget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'und rede zu den Propheten; und ich bin\'s der so viel Weissagung gibt und durch die Propheten mich anzeige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'In Gilead ist\'s Abgotterei, und zu Gilgal opfern sie Ochsen vergeblich; und haben so viel Altare, als Mandeln auf dem Felde stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Jakob mußte fliehen in das Land Syrien, und Israel mußte urn ein Weib dienen, urn ein Weib mußte er hüten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Aber hernach führete der HERR Israel aus Agypten durch einen Propheten und liefi sein hüten durch einen Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Nun aber erzürnet ihn Ephraim durch ihre Gotzen; darum wird, ihr Blut über sie kommen, und der HERR wird ihnen vergelten ihre Schmach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Da Ephraim schrecklich lehrete, ward er in Israel erhoben. Danach versundigten sie sich durch Baal und wurden daruber getotet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Aber nun machen sie der Sunden viel mehr und aus ihrem Silber Bilder, wie sie es erdenken konnen, namlich Gotzen, welche doch eitel Schmiedewerk sind. Noch predigen sie von denselben: Wer die Kalber kussen will, der soil Menschen opfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Dieselbigen werden haben die Morgenwolke und den Tau, der frühe fallt, ja, wie die Spreu, die von der Tenne verweht wird, und wie der Rauch von der Feuermauer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Ich bin aber der HERR, dein Gott, aus Agyptenland her; und du solltestja keinen andern Gott kennen denn mich und keinen Heiland ohne allein mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ich nahm mich ja dein an in der Wüste, im durren Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Aber weil sie geweidet sind, daß sie satt worden sind und genug haben, erhebt sich ihr Herz; darum vergessen sie mein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'So will ich auch werden gegen sie wie ein Lowe, und wie ein Parder auf dem Wege will ich auf sie lauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Ich will ihnen begegnen wie ein Bar, dem seine Jungen genommen sind, und will ihrverstocktes Herz zerreifien und will sie daselbst wie ein Lowe fressen; die wilden Tiere sollen sie zerreilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Israel, du bringest dich in Ungluck; denn dein Heil stehet allein bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Wo ist dein Konig hin, derdirhelfen moge in alien deinen Stadten? und deine Richter, davon du sagtest: Gib mir Konige und Fursten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Wohlan, ich gab dir einen Konig in meinem Zorn und will dir ihn in meinem Grimm wegnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Die Missetat Ephraims ist zusammengebunden, und ihre Sunde ist behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Denn es soil ihnen wehe werden wie einer Gebarerin; denn es sind unvorsichtige Kinder. Es wird die Zeit kommen, daß sie nicht bleiben werden vor dem Jammer der Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Aber ich will sie erlosen aus der Holle und vom Tod erretten. Tod, ich will dir ein Gift sein; Holle, ich will dir eine Pestilenz sein! Doch ist der Trost vor meinen Augen verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Denn erwird zwischen Brudern Frucht bringen. Es wird ein Ostwind kommen; der HERR wird aus der Wüste herauffahren und ihren Brunn austrocknen und ihre Quelle versiegen und wird rauben den Schatz alles kostlichen Gerates.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Samaria wird wust werden, denn sie sind ihrem Gott ungehorsam. Sie sollen durchs Schwert fallen und ihre jungen Kinder zerschmettert und ihre schwangeren Weiber zerrissen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Bekehre dich, Israel, zu dem HERRN, deinem Gott; denn du bist gefallen urn deiner Missetat willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Nehmet diese Worte mit euch und bekehret euch zum HERRN und sprechet zu ihm: Vergib uns alle Sunde und tue uns wohl, so wollen wir opfern die Farren unserer Lippen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Assursoll uns nicht helfen, und wollen nicht mehr auf Rossen reiten, auch nicht mehr sagen zu den Werken unserer Hande: Ihr seid unser Gott; sondern la(J die Waisen bei dir Gnade finden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'so will ich ihr Abtreten wieder heilen, gerne will ich sie lieben; dann soil mein Zorn sich von ihnen wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Ich will Israel wie ein Tau sein, daß ersoll blühen wie eine Rose; und seine Wurzeln sollen ausschlagen wie Libanon,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'und seine Zweige sich ausbreiten, daß er sei so schdn als ein Olbaum; und soli so guten Ruch geben wie Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Und sollen wieder unterseinem Schatten sitzen. Von Korn sollen sie sich nahren und bluhen wie ein Weinstock; sein Gedachtnis soil sein wie der Wein am Libanon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Ephraim, was sollen mirweiter die Gotzen? Ich will ihn erhoren und fuhren; ich will sein wie eine grünende Tanne; an mir soil man deine Frucht finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 10, 'Wer istweise, derdies verstehe, und klug, der dies merke? Denn die Wege des HERRN sind richtig, und die Gerechten wandeln drinnen; aber die Ubertreter fallen drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Dies ist das Wort des HERRN, das geschehen ist zu Joel, dem Sohn Pethuels:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Horet dies, ihr Altesten, und merket auf, alle Einwohner im Lande, ob ein solches geschehen sei bei euren Zeiten Oder bei eurer Vater Zeiten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Saget euren Kindern davon und lalit es eure Kinder ihren Kindern sagen und dieselbigen Kinder ihren andern Nachkommen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'namlich: Was die Raupen lassen, das fressen die Heuschrecken; und was die Heuschrecken lassen, das fressen die Kafer; und was die Kafer lassen, das fril M das Geschmeili.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Wachetauf, ihr Trunkenen, und weinet und heulet, alle Weinsaufer, urn den Most; denn er ist euch voreurem Maul weggenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Denn es zeucht herauf in mein Land ein machtig Volk, und des ohne Zahl; das hat Zahne wie Lowen und Backenzahne wie Lowinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Dasselbige verwustet meinen Weinberg und streift meinen Feigenbaum, schalet ihn und verwirft ihn, daß seine Zweige weili dastehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Heule wie eine Jungfrau, die einen Sack anlegt urn ihren Brautigam!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Denn das Speisopfer und Trankopfer ist vom Hause des HERRN weg, und die Priester, des HERRN Diener, trauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Das Feld ist verwustet, und der Acker stehet jammerlich, das Getreide ist verdorben, der Wein stehet jammerlich und das 01 klaglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Die Ackerleute sehen jammerlich, und die Weingartner heuien urn den Weizen und urn die Gerste, dafi aus der Ernte auf dem Felde nichts werden kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'So stehet der Weinstock auch jammerlich und der Feigenbaum klaglich; dazu die Granatbaume, Palmbaume, Apfelbaume und alle Baume auf dem Felde sind verdorret; denn die Freude der Menschen istzum Jammer worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Begurtet euch und klaget, ihr Priester; heulet, ihr Diener des Altars; gehet hinein und lieget in Sacken, ihr Diener meines Gottes! Denn es ist beide, Speisopfer und Trankopfer, vom Hause eures Gottes weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Heiligetein Fasten; rufetdie Gemeine zusammen; versammelt die Altesten und alle Einwohner des Landes zum Hause des HERRN, eures Gottes, und schreiet zum HERRN!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'O wehe des Tages! Denn der Tag des HERRN ist nahe und kommt wie ein Verderben vom Allmachtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Da wird die Speise vor unsern Augen weggenommen werden und vom Hause unsers Gottes Freude und Wonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Der Same ist unter der Erde verfaulet, die Kornhauser stehen wüst, die Scheunen zerfallen; denn das Getreide ist verdorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, '0 wie seufzet das Vieh! Die Rinder sehen klaglich, denn sie haben keine Weide, und die Schafe verschmachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'HERR, dich rufe ich an; denn das Feuer hat die Auen in der Wüste verbrannt, und die Flamme hat alle Baume auf dem Acker angezündet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Es schreien auch die wilden Tiere zu dir; denn die Wasserbache sind ausgetrocknet, und das Feuer hat die Auen in der Wüste verbrannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Blaset mit der Posaune zu Zion, rufet auf meinem heiligen Berge; erzittert, alle Einwohner im Lande! Denn der Tag des HERRN kommt und ist nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Ein finstrer Tag, ein dunkler Tag, ein wolkiger Tag, ein nebliger Tag, gleichwie sich die Morgenrote ausbreitet uber die Berge, namlich ein graft und machtig Volk desgleichen vorhin nicht gewesen ist und hinfort nicht sein wird zu ewigen Zeiten fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Vor ihm her gehet ein verzehrend Feuer und nach ihm eine brennende Flamme. Das Land ist vor ihm wie ein Lustgarten, aber nach ihm wie eine wüste Einode; und niemand wird ihm entgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Sie sind gestaltet wie Rosse und rennen wie die Reiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Sie sprengen daher oben auf den Bergen, wie die Wagen rasseln, und wie eine Flamme lodert im Stroh, wie ein machtig Volk, das zum Strait gerüstet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Die Volker werden sich vor ihm entsetzen; aller Angesichte sind so bleich wie die Topfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Sie werden laufen wie die Riesen und die Mauern ersteigen wie die Krieger; ein jeglicher wird stracks vor sich daherziehen und sich nicht saumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Keinerwird den andern irren, sondern ein jeglicher wird in seiner Ordnung daherfahren; und werden durch die Waffen brechen und nicht verwundet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Sie werden in der Stadt umherreiten, auf der Mauer laufen und in die Hauser steigen und wie ein Dieb durch die Fenster hineinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Vor ihm erzittert das Land und bebet der Himmel; Sonne und Mond werden finster, und die Sterne verhalten ihren Schein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Denn der HERR wird seinen Donner vor seinem Heer lassen hergeben; denn sein Heer ist sehr graft und machtig, welches seinen Befehl wird ausrichten; denn der T ag des HERRN ist graft und sehr erschrecklich; wer kann ihn leiden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'So spricht nun der HERR: Bekehret euch zu mir von ganzem Herzen mit Fasten, mit Weinen, mit Klagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Zerreiftet eure Herzen und nicht eure Kleider und bekehret euch zu dem HERRN, eurem Gotti Denn er ist gnadig, barmherzig, geduldig und von grafter Güte und reuet ihn bald der Strafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Werweift, es mag ihn wiederum gereuen und einen Segen hinter sich lassen, zu opfern Speisopfer und Trankopferdem HERRN, eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Blaset mit Posaunen zu Zion, heiliget ein Fasten, rufet die Gemeine zusammen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Versammelt das Volk, heiliget die Gemeine, sammelt die Altesten, bringet zuhauf die jungen Kinder und die Sauglinge! Der Brautigam gehe aus seiner Kammer und die Braut aus ihrem Gemach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Laft die Priester, des HERRN Diener, weinen zwischen der Halle und Altar und sagen: HERR, schone deines Volks und laft dein Erbteil nicht zuschanden werden, daß Heiden uber sie herrschen! Warum willst du lassen unter den Volkern sagen: Wo ist nun ihr Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'So wird denn der HERR urn sein Land eifern und seines Volks verschonen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Und der HERR wird antworten und sagen zu seinem Volk: Siehe, ich will euch Getreide, Most und 01 die Fülle schicken, daß ihr genug daran haben sollt, und will euch nicht mehr lassen unter den Heiden zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Und will den von Mitternacht feme von euch treiben und ihn in ein dürr und wüst Land verstoften, namlich sein Angesicht hin zum Meer gegen Morgen und sein Ende hin zum auftersten Meer. Ersoll verfaulen und stinken; denn er hat grofte Dinge getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Furchte dich nicht, liebes Land, sondern sei frohlich und getrost; denn der HERR kann auch grofte Dinge tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Furchtet euch nicht, ihr Tiere auf dem Felde; denn die Wohnungen in der Wüste sollen grünen und die Baume ihre Früchte bringen, und die Feigenbaume und Weinstocke sollen wohl tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Und ihr, Kinder Zions, freuet euch und seid frohlich im HERRN, eurem Gott, der euch Lehrer zur Gerechtigkeit gibt und euch herabsendet Frühregen und Spatregen, wie vorhin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'daß die Tennen voll Korns und die Keltern Uberfluft von Most und 01 haben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Und ich will euch die Jahre erstatten, welche die Heuschrecken, Kafer, Geschmeift und Raupen, die mein groftes Heer waren, so ich unter euch schickte, gefressen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'daß ihr zu essen genug haben sollet und den Namen des HERRN, eures Gottes, preisen, der Wunder unter euch getan hat; und mein Volk soil nicht mehr zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Und ihr sollt es erfahren, daß ich mitten unter Israel sei und daß ich, der HERR, euer Gott sei, und keiner mehr; und mein Volk soil nicht mehr zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Und nach diesem will ich meinen Geist ausgieften uber alles Fleisch, und eure Sohne und Tochter sollen weissagen, eure Altesten sollen Traume haben, und eure Jünglinge sollen Gesichte sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Auch will ich zur selbigen Zeit beide, uber Knechte und Magde, meinen Geist ausgieften');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'und will Wunderzeichen geben im Himmel und auf Erden, namlich Blut, Feuer und Rauchdampf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Die Sonne soli in Finsternis und der Mond in Blut verwandelt werden, ehe denn der grofte und schreckliche Tag des HERRN kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Und soil geschehen, werden Namen des HERRN anrufen wird, der soil errettet werden. Denn auf dem Berge Zion und zu Jerusalem wird eine Errettung sein, wie der HERR verheiften hat, auch bei den andern ubrigen, die der HERR berufen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 1, 'Denn siehe, in den Tagen und zur selbigen Zeit, wenn ich das Gefangnis Judas und Jerusalems wenden werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 2, 'will ich alle Heiden zusammenbringen und will sie ins Tal Josaphat hinabfuhren und will mit ihnen daselbst rechten von wegen meines Volks und meines Erbteils Israel, das sie unter die Heiden zerstreuet und sich in mein Land geteilet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 3, 'und das Los um mein Volk geworfen haben und haben die Knaben um Speise gegeben und die Magdlein um Wein verkauft und vertrunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 4, 'Und ihr von Zor und Zidon und alle Grenze der Philister, was habt ihr mit mir zu tun? Wollt ihr mir trotzen? Wohlan, trotzet ihr mir, so will ich\'s euch eilend und bald wieder vergelten auf euren Kopf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 5, 'die ihr mein Silber und Gold und meine schonen Kleinode genommen und in eure Kirchen gebracht habt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 6, 'dazu auch die Kinder Judas und die Kinder Jerusalems verkauft habt den Griechen, auf daß ihr sie gar feme von ihren Grenzen brachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 7, 'Siehe, ich will sie erwecken aus dem Ort, dahin ihr sie verkauft habt, und will\'s euch vergelten auf euren Kopf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 8, 'Und will eure Sohne und eure Tochter wiederum verkaufen, durch die Kinder Judas; die sollen sie denen in Reicharabien, einem Volk in fernen Landen, verkaufen; denn der HERR hat es geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 9, 'Rufet dies aus unter den Heiden; heiliget einen Streit, erwecket die Starken, lafit herzukommen und hinaufziehen alle Kriegsleute!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 10, 'Machet aus euren Pflugscharen Schwerter und aus euren Sicheln Spiefte! Der Schwache spreche: Ich bin stark.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 11, 'Rottet euch und kommt her, alle Heiden um und um, und versammelt euch! Daselbst wird der HERR deine Starken daniederlegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 12, 'Die Heiden werden sich aufmachen und heraufkommen zum Tal Josaphat; denn daselbst will ich sitzen, zu richten alle Heiden um und um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 13, 'Schlaget die Sichel an, denn die Ernte ist reif; kommt herab, denn die Kelter ist voll und die Kelter lauft über; denn ihre Bosheit ist graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 14, 'Es werden hie und da Haufen Volks sein im Tal des Urteils; denn des HERRN Tag ist nahe im Tal des Urteils.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 15, 'Sonne und Mond werden verfinstert und die Sterne werden ihren Schein verhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 16, 'Und der HERR wird aus Zion brüllen und aus Jerusalem seine Stimme lassen horen, daß Himmel und Erde beben wird. Aber der HERR wird seinem Volk eine Zuflucht sein und eine Feste den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 17, 'Und ihr sollt es erfahren, daß ich, der HERR, euer Gott, zu Zion auf meinem heiligen Berge wohne. Alsdann wird Jerusalem heilig sein und kein Fremder mehr durch sie wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 18, 'Zur selbigen Zeit werden die Berge mit süftem Wein triefen und die Hugel mit Milch flieften, und alle Bache in Juda werden voll Wassers gehen; und wird eine Quelle vom Hause des HERRN herausgehen, die wird den Strom Sittim wassern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 19, 'Aber Agypten soil wüst werden und Edom eine wüste Einode um den Frevel, an den Kindern Judas begangen, daß sie unschuldig Blut in ihrem Lande vergossen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 20, 'Aber Juda soil ewiglich bewohnet werden und Jerusalem fur und fur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 4, 21, 'Und ich will ihr Blut nicht ungeracht lassen. Und der HERR wird wohnen zu Zion.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Dies ist\'s, das Amos, der unter den Hirten zu Thekoa war, gesehen hat über Israel zur Zeit Usias, des Konigs Judas, und Jerobeams, des Sohns Joas, des Konigs Israels, zwei Jahre vor dem Erdbeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Und sprach: Der HERR wird aus Zion brullen und seine Stimme aus Jerusalem horen lassen, daß die Auen der Hirten jammerlich stehen werden und der Karmel oben verdorren wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So spricht der HERR: Um drei und vier Laster willen Damaskus will ich ihrer nicht schonen, darum daß sie Gilead mit eisernen Zacken gedroschen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'sondern ich will ein Feuer schicken in das Haus Hasaels, das soil die Palaste Benhadads verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Und ich will die Riegel zu Damaskus zerbrechen und die Einwohner auf dem Felde Aven samt dem, der das Zepter halt, aus dem Lusthause ausrotten, daß das Volk in Syrien soil gen Kirweggefuhret werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So spricht der HERR: Um drei und vier Laster willen Gasas will ich ihrer nicht schonen, darum daß sie die Gefangenen weiter gefangen und ins Land Edom vertrieben haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'sondern ich will ein Feuer in die Mauern zu Gasa schicken, das soil ihre Palaste verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Und will die Einwohner zu Asdod samt dem, der, das Zepter halt, aus Askalon ausrotten und meine Hand wider Akron kehren, daß umkommen soil, was von den Philistern noch übrig ist, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'So spricht der HERR: Um drei und vier Laster willen der Stadt Zor will ich ihrer nicht schonen, darum daß sie die Gefangenen weiter ins Land Edom vertrieben haben und nicht gedacht an den Bund der Brüder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'sondern ich will ein Feuer in die Mauern zu Zor schicken, das soil ihre Palaste verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'So spricht der HERR: Um drei und vier Laster willen Edoms will ich sein nicht schonen, darum daß er seinen Bruder mit dem Schwert verfolget hat, und daß er ihre Schwangeren umgebracht und immer zerrissen in seinem Zorn und seinen Grimm ewig halt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'sondern ich will ein Feuer schicken gen Theman, das soil die Palaste zu Bazra verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So spricht der HERR: Um drei und vier Laster willen der Kinder Ammon will ich ihrer nicht schonen, darum daß sie die Schwangeren in Gilead zerrissen haben, damit sie ihre Grenze weiter machten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'sondern ich will ein Feuer anzunden in den Mauern Rabbas, das soil ihre Palaste verzehren, wenn man rufen wird zur Zeit des Streits, und wenn das Wetter kommen wird zur Zeit des Sturms.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Da wird dann ihr Konig samt seinen Fursten gefangen weggefuhret werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So spricht der HERR: Um drei und vier Laster willen Moabs will ich ihrer nicht schonen, darum daß sie die Gebeine des Konigs zu Edom haben zu Asche verbrannt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'sondern ich will ein Feuer schicken in Moab, das soil die Palaste zu Kirioth verzehren; und Moab soil sterben im Getummel und Geschrei und Posaunenhall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Und ich will den Richter unter ihnen ausrotten und alle ihre Fursten samt ihm erwurgen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So spricht der HERR: Um drei und vier Laster willen Judas will ich sein nicht schonen, darum daß sie des HERRN Gesetz verachten und seine Rechte nicht halten und lassen sich ihre Lugen verführen, welchen ihre Vater nachgefolget haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'sondern ich will ein Feuer in Juda schicken, das soil die Palaste zu Jerusalem verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So spricht der HERR: Um drei und vier Laster willen Israels will ich ihrer nicht schonen, darum daß sie die Gerechten um Geld und die Armen um ein Paar Schuh verkaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Sie treten den Kopf der Armen in Kot und hindern den Weg der Elenden. Es schlaft Sohn und Vater bei einer Dime, damit sie meinen heiligen Namen entheiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Und bei alien Altaren schlemmen sie von den verpfandeten Kleidern und trinken Wein in ihrer Gotter Hause von den Gebuftten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Nun hab ich ja den Amoriter vor ihnen her vertilget, der so hoch war wie die Zedern und seine Machtwie die Eichen, und ich vertilgte oben seine Frucht und unten seine Wurzel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Auch habe ich euch aus Agyptenland gefuhret und vierzig Jahre in der Wuste geleitet, daß ihr der Amoriter Land besaßet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'und hab aus euren Kindern Propheten auferwecket und Nasaraer aus euren Junglingen. Ist\'s nicht also, ihr Kinder Israel? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'So gebet ihr den Nasaraern Wein zu trinken und gebietet den Propheten und sprechet: Ihr sollt nicht weissagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Siehe, ich will\'s unter euch kirren machen, wie ein Wagen voll Garben kirret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'daß der, so schnell ist, soil nicht entfliehen, noch der Starke etwas vermogen, und der Machtige nicht soil sein Leben erretten konnen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'und die Bogenschützen sollen nicht bestehen, und der schnell laufen kann, soil nicht entlaufen, und der da reitet, soil sein Leben nicht erretten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'und der unter den Starken der mannhaftigste ist, soil nackend entfliehen müssen zu der Zeit, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Horet, was der HERR mit euch redet, ihr Kinder Israel, namlich mit alien Geschlechtern, die ich aus Agyptenland gefuhret habe, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Aus alien Geschlechtern auf Erden hab ich allein euch erkannt; darum will ich auch euch heimsuchen in all eurer Missetat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Mogen auch zween miteinanderwandeln, sie seien denn eins untereinander?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brullet auch ein Lowe im Walde, wenn er keinen Raub hat? Schreiet auch ein junger Lowe aus seiner Hohle, er habe denn etwas gefangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Fallt auch ein Vogel in den Strick auf der Erde, da kein Vogler ist? Hebt man auch den Strick auf von der Erde, der noch nichts gefangen hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Blaset man auch die Posaune in einer Stadt, da sich das Volk davor nicht entsetze? Ist auch ein Unglück in der Stadt, das der HERR nicht tue?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Denn der Herr HERR tut nichts, er offenbare denn sein Geheimnis den Propheten, seinen Knechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Der Lowe brullet; wer sollte sich nicht furchten? Der Herr HERR redet; wer sollte nicht weissagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Verkundiget in den Palasten zu Asdod und in den Palasten im Lande Agypten und sprechet: Sammelt euch auf die Berge Samaria und sehet, welch ein groß Zetergeschrei und Unrecht drinnen ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Sie achten keines Rechten, spricht der HERR, sammeln Schatze von Frevel und Raube in ihren Palasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Darum spricht der Herr HERR also: Man wird dies Land ringsumher belagern und dich von deiner Macht herunterreißen und deine Hauser plundern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So spricht der HERR: Gleichwie ein Hirt dem Lowen zwei Kniee Oder ein Ohrlapplein aus dem Maul reißet, also sollen die Kinder Israel herausgerissen werden, die zu Samaria wohnen und haben in der Ecke ein Bett und zu Damaskus eine Sponde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Horet und zeuget im Hause Jakobs, spricht der Herr HERR, der Gott Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Denn zur Zeit, wenn ich die Sunde Israels heimsuchen werde, will ich die Altare zu Bethel heimsuchen und die Horner des Altars abbrechen, daß sie zu Boden fallen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Und will beide, Winterhaus und Sommerhaus, schlagen; und sollen die elfenbeinernen Hauser untergehen und viel Hauser verderbet werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Horet dies Wort, ihr fetten Kuhe, die ihr auf dem Berge Samaria seid und den Durftigen unrecht tut und untertretet die Armen und sprechet zu euren Herren: Bringe her, laß uns saufen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Der Herr HERR hat geschworen bei seiner Heiligkeit: Siehe, es kommt die Zeit uber euch, daß man euch wird herausrücken mit Angeln und eure Nachkommen mit Fischhaklein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Und werdetzu den Lücken hinausgehen, eine jegliche vor sich hin, und gen Harmon weggeworfen werden, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Ja, kommt her gen Bethel und treibet Sunde und gen Gilgal, daß ihr der Sunden viel machet; und bringet eure Opfer des Morgens und eure Zehnten des dritten Tages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Und rauchert vom Sauerteig zum Dankopfer und prediget von freiwilligem Opfer und verkundiget es; denn so habt ihr\'s gerne, ihr Kinder Israel, spricht der Herr HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Darum hab ich euch auch in alien euren Stadten müßige Zahne gegeben und Mangel an Brot an alien euren Orten. Noch bekehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Auch hab ich den Regen uber euch verhalten, bis daß noch drei Monden waren zur Ernte; und ich ließ regnen uber eine Stadt und auf die andere ließ ich nicht regnen; ein Acker ward beregnet, und der andere Acker, der nicht beregnet ward, verdorrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Und zogen zwo, drei Stadte zu einer Stadt, daß sie Wasser trinken mochten, und konnten es nicht genug finden. Noch bekehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Ich plagte euch mit durrer Zeit und mit Brandkorn; so fraßen auch die Raupen alles, was in euren Garten, Weinbergen, Feigenbaumen und Olbaumen wuchs. Noch bekehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Ich schickte Pestilenz unter euch, gleicherweise wie in Agypten; ich totete eure junge Mannschaft durchs Schwert und ließ eure Pferde gefangen wegfuhren; ich ließ den Gestankvon eurem Heerlager in eure Nasen gehen. Noch bekehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Ich kehrete etliche unter euch urn, wie Gott Sodom und Gomorrha umkehrete, daß ihrwaretwie ein Brand, der aus dem Feuer gerissen wird. Noch kehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Darum will ich dirweiter also tun, Israel. Weil ich denn dir also tun will, so schicke dich, Israel, und begegne deinem Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Denn siehe, er ist\'s, der die Berge macht, den Wind schaffet und zeiget dem Menschen, was er reden soil. Er macht die Morgenrote und die Finsternis; er tritt auf den Hohen der Erden: er heißt HERR, Gott Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Horet, ihr vom Hause Israel, dies Wort; denn ich muß dies Klagelied uber euch machen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Die Jungfrau Israel ist gefallen, daß sie nicht wieder aufstehen wird; sie ist zu Boden gestoßen, und ist niemand, der ihr aufhelfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn so spricht der HERR Gott: Die Stadt, da tausend ausgehen, soil nur hundert ubrig behalten; und da hundert ausgehen, soil nurzehn ubrig behalten im Hause Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Darum so spricht der HERR zum Hause Israel: Suchet mich, so werdet ihr leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Suchet nicht Bethel und kommet nicht gen Gilgal und gehet nicht gen Berseba. Denn Gilgal wird gefangen weggefuhretwerden, und Bethel wird Beth- Aven werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Suchet den HERRN, so werdet ihr leben, daß nicht ein Feuer im Hause Josephs überhandnehme, das da verzehre, und niemand loschen moge zu Bethel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'die ihr das Recht in Wermut verkehret und die Gerechtigkeit zu Boden stoßet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Er macht die Glucke und Orion; der aus der Finsternis den Morgen und aus dem Tage die finstere Nacht macht; der dem Wasser im Meer ruft und schuttet es auf den Erdboden: er heifiet HERR,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'der uber den Starken eine Verstorung anrichtet und bringet eine Verstorung uber die teste Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Aber sie sind dem gram, der sie im Tor straft, und haben den fur einen Greuel, der heilsam lehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Darum, weil ihr die Armen unterdrucket und nehmet das Korn mit großen Lasten von ihnen, so sollt ihr in den Hausern nicht wohnen, die ihr von Werkstucken gebauet habt, und den Wein nicht trinken, den ihr in den feinen Weinbergen gepflanzet habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Denn ich weiß euer Gbertreten, des viel ist, und eure Sunden, die stark sind, wie ihr die Gerechten dranget und Blutgeld nehmet und die Armen im Tor unterdrucket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Darum muß der Kluge zur selbigen Zeit schweigen; denn es ist eine bose Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Suchet das Gute und nicht das Bose, auf daß ihr leben moget, so wird der HERR, der Gott Zebaoth, bei euch sein, wie ihrrühmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hasset das Bose und liebet das Gute, bestellet das Recht im Tor, so wird der HERR, der Gott Zebaoth, den ubrigen in Joseph gnadig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Darum so spricht der HERR, der Gott Zebaoth, der HERR: Es wird in alien Gassen Wehklagen sein, und auf alien Straßen wird man sagen: Wehe! wehe! Und man wird den Ackermann zum Trauern rufen und zum Wehklagen, wer da weinen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'In alien Weinbergen wird Wehklagen sein; denn ich will unter euch fahren, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Wehedenen, die des HERRN Tag begehren! Was soil er euch? Denn des HERRN Tag ist eine Finsternis und nicht ein Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Gleich als wenn jemand vor dem Lowen fldhe und ein Bar begegnete ihm, und als wenn jemand in ein Haus kame und lehnete sich mit der Hand an die Wand und eine Schlange stache ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Denn des HERR Tag wird ja finster und nicht licht sein, dunkel und nicht hell.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Ich bin euren Feiertagen gram und verachte sie und mag nicht riechen in eure Versammlung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Und ob ihr mir gleich Brandopfer und Speisopfer opfert, so hab ich keinen Gefallen daran; so mag ich auch eure feisten Dankopfer nicht ansehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Tu nur weg von mir das Geplarr deiner Lieder; denn ich mag deines Psalterspieles nicht horen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Es soil aber das Recht offenbaret werden wie Wasser und die Gerechtigkeit wie ein starker Strom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr vom Hause Israel mir in der Wuste die vierzig Jahre lang Schlachtopfer und Speisopfer geopfert? Jawohl!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Ihrtrugetden Sichuth, euren Konig, und Chiun, euer Bild, den Stern eurer Gotter, welche ihr euch selbst gemacht hattet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'So will ich euch von hinnen jenseit Damaskus wegfuhren lassen, spricht der HERR, der Gott Zebaoth heißt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Wehe den Stolzen zu Zion und denen, die sich auf den Berg Samaria verlassen, die sich rühmen die Vornehmsten uber die Heiden und gehen einher im Hause Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Gehet hin gen Kalne und schauet von dannen gen Hemath, die große Stadt, und ziehet hinab gen Gath der Philister, welche bessere Konigreiche gewesen sind denn diese und ihre Grenze großer denn eure Grenze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Die ihr euch weit vom bosen Tage achtet und trachtet immer nach Frevelregiment,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'und schlafet auf elfenbeinernen Lagern und treibet Uberfluß mit euren Betten; ihr esset die Lammer aus der Herde und die gemasteten Kalber');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'und spielet auf dem Psalter und erdichtet euch Lieder, wie David,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'und trinket Wein aus den Schalen und salbet euch mit Balsam und bekummert euch nichts urn den Schaden Josephs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Darum sollen sie nun vornean gehen unter denen, die gefangen weggefuhretwerden, und soil das Schlemmen der Pranger aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Denn der Herr HERR hat geschworen bei seiner Seele, spricht der HERR, der Gott Zebaoth: Mich verdrießt die Hoffart Jakobs und bin ihren Palasten gram; und ich will auch die Stadt ubergeben mit allem, was drinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Und wenn gleich zehn Manner in einem Hause uberblieben, sollen sie doch sterben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'daß einen jeglichen sein Vetter und sein Ohm nehmen und die Gebeine aus dem Hause tragen muß und sagen zu dem, der in den Gemachern des Hauses ist: Ist ihrer auch noch mehr da? Und der wird antworten: Sie sind alle dahin! Und wird sagen: Sei zufrieden; denn sie wollten nicht, daß man des HERRN Namens gedenken solite.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Denn siehe, der HERR hat geboten, daß man die großen Hauser schlagen soil, daß sie Ritze gewinnen, und die kleinen Hauser, daß sie Lucken gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Wer kann mit Rossen rennen Oder mit Ochsen pflugen auf Felsen? Denn ihr wandelt das Recht in Galle und die Frucht der Gerechtigkeit in Wermut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'und trostet euch des, das so gar nichts ist, und sprechet: Sind wir denn nicht stark genug mit unsern Hornern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Darum siehe, ich will uber euch vom Haus Israel ein Volk erwecken, spricht der HERR, der Gott Zebaoth, das soli euch angsten von dem Ort an, da man gen Hemath gehet, bis an den Bach in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Der Herr HERR zeigte mir ein Gesicht, und siehe, da stund einer, der machte Heuschrecken im Anfang, da das Grummet aufging; und siehe, das Grummet stund, nachdem der Konig seine Schafe hatte scheren lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Als sie nun das Kraut im Lande gar abfressen wollten, sprach ich: Ach, Herr HERR, sei gnadig! Wer will Jakob wieder aufhelfen? denn er ist ja gering.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Da reuete es den HERRN und sprach: Wohlan, es soil nicht geschehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Der Herr HERR zeigte mir ein Gesicht, und siehe, der Herr HERR rief dem Feuer, damit zu strafen; das sollte eine grotße Tiefe verzehren und frali schon ein Teil dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Da sprach ich: Ach, Herr HERR, lali ab! Wer will Jakob wieder aufhelfen? denn er ist ja gering.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Da reuete den HERRN das auch, und der Herr HERR sprach: Es soil auch nicht geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Er zeigte mir aber dies Gesicht, und siehe, der HERR stund auf einer Mauer, mit einer Bleischnur gemessen; und er hatte die Bleischnur in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Und der HERR sprach zu mir: Was siehest du, Amos? Ich sprach: Eine Bleischnur. Da sprach der HERR zu mir: Siehe, ich will eine Bleischnur ziehen mitten durch mein Volk Israel und ihm nichts mehr ubersehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'sondern die Hohen Isaaks sollen verwüstet und die Kirchen Israels verstoret werden; und ich will mit dem Schwert mich uber das Haus Jerobeams machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Da sandte Amazia, der Priesterzu Bethel, zu Jerobeam, dem Konige Israels, und lieli ihm sagen: Der Amos macht einen Aufruhr wider dich im Hause Israel; das Land kann seine Worte nicht leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Denn so spricht Amos: Jerobeam wird durchs Schwert sterben, und Israel wird aus seinem Lande gefangen weggefuhret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Und Amazia sprach zu Amos: Du Seher, gehe weg und flieh ins Land Juda und iß Brot daselbst und weissage daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Und weissage nicht mehr zu Bethel; denn es ist des Konigs Stift und des Konigreichs Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Amos antwortete und sprach zu Amazia: Ich bin kein Prophet, noch keines Propheten Sohn, sondern ich bin ein Kuhhirte, der Maulbeeren ablieset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Aber der HERR nahm mich von der Herde und sprach zu mir: Gehe hin und weissage meinem Volk Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'So hore nun des HERRN Wort! Du sprichst: Weissage nicht wider Israel und traufle nicht wider das Haus Isaak!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Darum spricht der HERR also: Dein Weib wird in der Stadt zur Hure werden, und deine Sohne und Tochter sollen durchs Schwert fallen, und dein Acker soil durch die Schnur ausgeteilet werden; du aber sollst in einem unreinen Lande sterben, und Israel soil aus seinem Lande vertrieben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Der Herr HERR zeigte mir ein Gesicht, und siehe, da stund ein Korb mit Obst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Und er sprach: Was siehest du, Amos? Ich aber antwortete: Einen Korb mit Obst. Da sprach der HERR zu mir: Das Ende ist kommen uber mein Volk Israel; ich will ihm nichts mehr ubersehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Und die Lieder in der Kirche sollen in ein Heulen verkehret werden zur selbigen Zeit, spricht der Herr HERR; es werden viel toter Leichname liegen an alien Orten, die man heimlich wegtragen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Horet dies, die ihr den Armen unterdrucket und die Elenden im Lande verderbet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'und sprechet: Wann will denn der Neumond ein Ende haben, dafi wir Getreide verkaufen, und der Sabbat, dal L wir Korn feil haben mogen und den Epha ringern und den Sekel steigern und die Waage falschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'auf dafi wir die Armen urn Geld und die Durftigen urn ein Paar Schuh unter uns bringen und Spreu fur Korn verkaufen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Der HERR hat geschworen wider die Hoffart Jakobs: Was gilt\'s, ob ich solcher ihrer Werke ewig vergessen werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Sollte nicht urn solches willen das Land erbeben müssen und alle Einwohner trauern? Ja, es soil ganz, wie mit einem Wasser, uberlaufen werden und weggefuhret und überschwemmet werden, wie mit dem Fluli in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Zur selbigen Zeit, spricht der Herr HERR, will ich die Sonne im Mittage untergehen lassen und das Land am hellen Tage lassen finster werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Ich will eure Feiertage in Trauern und alle eure Lieder in Wehklagen verwandeln; ich will uber alle Lenden den Sack bringen und alle Kopfe kahl machen und will ihnen ein Trauern schaffen, wie man uber einen einigen Sohn hat, und sollen ein jammerlich Ende nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Siehe, es kommt die Zeit, spricht der Herr HERR, daß ich einen Hunger ins Land schicken werde, nicht einen Hunger nach Brot Oder Durst nach Wasser, sondern nach dem Wort des HERRN zu horen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'dafi sie hin und her, von einem Meer zum andern, von Mitternacht gegen Morgen umlaufen und des HERRN Wort suchen und doch nicht finden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Zu der Zeit werden schone Jungfrauen und Junglinge verschmachten vor Durst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'die jetzt schworen bei dem Fluch Samaria und sprechen: So wahr dein Gott zu Dan lebet, so wahr die Weise zu Berseba lebet! Denn sie sollen also fallen, daß sie nicht wieder aufstehen mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ich sah den HERRN auf dem Altar stehen, und er sprach: Schlage an den Knauf, daß die Pfosten beben! Denn ihr Geiz soli ihnen auf ihren Kopf kommen, und will ihre Nachkommen mit dem Schwert erwurgen, daß keiner entfliehen, noch einiger davon entgehen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Und wenn sie sich gleich in die Holle vergruben, soil sie doch meine Hand von dannen holen; und wenn sie gen Himmel führen, will ich sie doch herunterstolien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'und wenn sie sich gleich versteckten oben auf dem Berge Karmel, will ich sie doch, daselbst suchen und herabholen; und wenn sie sich vor meinen Augen verbargen im Grunde des Meers, so will ich doch den Schlangen befehlen, die sie daselbst stechen sollen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'und wenn sie vor ihren Feinden hin gefangen gingen, so will ich doch dem Schwert befehlen, daß sie es daselbst erwurgen soil. Denn ich will meine Augen uber ihnen halten zum Ungluck und nicht zum Guten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Denn der Herr HERR Zebaoth ist ein solcher: wenn er ein Land anruhret, so zerschmilzet es, daß alle Einwohner trauern müssen, daß es soli ganz uber sie her laufen wie ein Wasser und uberschwemmet werden wie mit dem Fluli in Agypten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Er ist\'s, der seinen Saal in dem Himmel bauet und seine Hutte auf der Erde gründet; er ruft dem Wasser im Meer und schuttet es auf das Erdreich; er heilit HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Seid ihr Kinder Israel mir nicht gleich wie die Mohren? spricht der HERR. Hab ich nicht Israel aus Agyptenland gefuhret und die Philister aus Kaphthor und die Syrer aus Kir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Siehe, die Augen des Herm HERRN sehen auf ein sundiges Konigreich, daß ich\'s vom Erdboden ganz vertilge, wiewohl ich das Haus Jakob nicht gar vertilgen will, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Aber doch siehe, ich will befehlen und das Haus Israel unter alien Heiden sichten lassen, gleichwie man mit einem Siebe sichtet, und die Kornlein sollen nicht auf die Erde fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Alle Sunder in meinem Volk sollen durchs Schwert sterben, die da sagen: Es wird das Ungluck nicht so nahe sein noch uns begegnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Zur selbigen Zeit will ich die zerfallene Hutte Davids wieder aufrichten und ihre Lucken verzaunen, und was abgebrochen ist, wieder aufrichten; und will sie bauen, wie sie vorzeiten gewesen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'auf daß sie besitzen die ubrigen zu Edom und die ubrigen unter alien Heiden, uberwelche mein Name gepredigt sein wird, spricht der HERR, der solches tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Siehe, es kommtdie Zeit, spricht der HERR, daß man zugleich ackern und ernten und zugleich keltern und saen wird; und die Berge werden mit süliem Wein triefen, und alle Hugel werden fruchtbar sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Denn ich will das Gefangnis meines Volks Israel wenden, daß sie sollen die wusten Stadte bauen und bewohnen, Weinberge pflanzen und Wein davon trinken, Garten machen und Fruchte daraus essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Denn ich will sie in ihr Land pflanzen, daß sie nicht mehr aus ihrem Lande gerottet werden, das ich ihnen geben werde, spricht der HERR, dein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Dies ist das Gesicht Obadjas. So spricht der Herr HERR von Edom: Wir haben vom HERRN gehoret, daß eine Botschaft unter die Heiden gesandt sei: Wohlauf, und laßt uns wider sie streiten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Siehe, ich habe dich gering gemacht unter den Heiden und sehr verachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Der Hochmut deines Herzens hat dich betrogen, weil du in der Felsen Klüften wohnest, in deinen hohen Schlossern, und sprichst in deinem Herzen: Werwill mich zu Boden stoßen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Wenn du denn gleich in die Hohe fuhrestwie ein Adler und machtest dein Nest zwischen den Sternen, dennoch will ich dich von dannen heruntersturzen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Wenn Diebe Oder Verstorer zu Nacht uber dich kommen werden, wie sollst du so zunichte werden! Ja, sie sollen genug stehlen; und wenn die Weinleser uber dich kommen, so sollen sie dir kein Nachlesen uberbleiben lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Wie sollen sie den Esau ausforschen und seine Schatze suchen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Alle deine eigenen Bundesgenossen werden dich zum Lande hinausstoßen; die, Leute, auf die du deinen Trost setzest, werden dich betrugen und uberwaltigen; die dein Brot essen, werden dich verraten, ehe du es merken wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Was gilt\'s? spricht der HERR, ich will zur selbigen Zeit die Weisen zu Edom zunichte machen und die Klugheit auf dem Gebirge Esau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Denn deine Starken zu Theman sollen zagen, auf daß sie alle auf dem Gebirge Esau durch den Mord ausgerottet werden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'urn des Frevels willen, an deinem Bruder Jakob begangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Zu der Zeit, da du wider ihn stundest, da die Fremden sein Heer gefangen wegfuhreten und Auslander zu seinen Toren einzogen und uber Jerusalem das Los warfen, da warest du gleich wie derselbigen einer. Darum sollst du zu alien Schanden werden und ewiglich ausgerottet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Du sollst nicht mehr so deine Lustsehen an deinem Bruder zur Zeit seines Elendes und sollst dich nicht freuen uber die Kinder Juda zur Zeit ihres Jammers und sollst mit deinem Maul nicht so stolz reden zur Zeit ihrer Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Du sollst nicht zum Tor meines Volks einziehen zur Zeit ihres Jammers; du sollst nicht deine Lust sehen an ihrem Ungluck zur Zeit ihres Jammers; du sollst nicht wider sein Heer schicken zur Zeit seines Jammers;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'du sollst nicht stehen an den Wegscheiden, seine Entronnenen zu morden; du sollst seine Ubrigen nicht verraten zur Zeit der Angst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Denn der Tag des HERRN istnahe uber alle Heiden. Wie du getan hast, soil dirwiedergeschehen, und wie du verdienet hast, so soil dir\'s wieder auf deinen Kopf kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Denn wie ihr auf meinem heiligen Berge getrunken habt, so sollen alle Heiden taglich trinken; ja, sie sollen\'s aussaufen und verschlingen, daß es sei, ais ware nie nichts dagewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Aber auf dem Berge Zion sollen noch etliche errettet werden, die sollen Heiligtum sein; und das Haus Jakob soil seine Besitzer besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Und das Haus Jakob soil ein Feuer werden und das Haus Joseph eine Flamme, aber das Haus Esau Stroh. Das werden sie anzunden und verzehren, daß dem Hause Esau nichts überbleibe; denn der HERR hat\'s geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Und die gegen Mittag werden das Gebirge Esau und die in Grunden werden die Philister besitzen; ja, sie werden das Feld Ephraim und das Feld Samaria besitzen und Benjamin das Gebirge Gilead.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Und die Vertriebenen dieses Heers der Kinder Israel, so unter den Kanaanitern bis gen Zarpath sind, und die Vertriebenen der Stadt Jerusalem, die zu Sepharad sind, werden die Stadte gegen Mittag besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Und werden Heilande heraufkommen auf den Berg Zion, das Gebirge Esau zu richten. Also wird das Konigreich des HERRN sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Es geschah das Wort des HERRN zu Jona, dem Sohn Amithais, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Mache dich auf und gehe in die grofte Stadt Ninive und predige drinnen; denn ihre Bosheit ist heraufkommen vormich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Aber Jona machte sich auf und floh vor dem HERRN; und wollte aufs Meer und kam hinab gen Japho. Und da erein Schiff fand, das aufs Meer wollte fahren, gab er Fahrgeld und trat, darein, daß er mit ihnen aufs Meer fuhre vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Da lieft der HERR einen groften Wind aufs Meer kommen und hub sich ein groli Ungewitter auf dem Meer, daß man meinete, das Schiff wurde zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Und die Schiffsleute furchteten sich und schrieen ein jeglicher zu seinem Gott; und warfen das Gerat, das im Schiff war, ins Meer, daß es leichter wurde. Aber Jona war hinunter in das Schiff gestiegen, lag und schlief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Da trat zu ihm der Schiffsherr und sprach zu ihm: Was schlafst du? Stehe auf, rufe deinen Gott an, ob vielleicht Gott an uns gedenken wolite, daß wir nicht verdurben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Und einer sprach zum andern: Kommt, wir wollen losen, daß wir erfahren, urn welches willen es uns so ubel gehe! Und da sie loseten, traf es Jona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Da sprachen sie zu ihm: Sage uns, warum gehet es uns so ubel? Was ist dein Gewerbe, und wo kommst du her? Aus welchem Lande bist du und von welchem Volk bist du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Er sprach zu ihnen: Ich bin ein Ebraer und furchte den HERRN, Gott vom Himmel, welcher gemacht hat das Meer und das Trockene.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Da furchteten sich die Leute sehr und sprachen zu ihm: Warum hast du denn solches getan? Denn sie wuftten, daß er vor dem HERRN floh; denn er hatte es ihnen gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Da sprachen sie zu ihm: Was sollen wir denn mit dir tun, daß uns das Meer stille werde? Denn das Meerfuhr ungestüm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Er sprach zu ihnen: Nehmet mich und werfet mich ins Meer, so wird euch das Meer stille werden. Denn ich weift, daß solch graft Ungewitter ube euch kommt urn meinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Und die Leute trieben, daß sie wiederzu Lande kamen, aber sie konnten nicht; denn das Meer fuhr ungestüm wider sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Da riefen sie zu dem HERRN und sprachen: Ach, HERR, laft uns nicht verderben urn dieses Mannes Seele willen und rechne uns nicht zu unschuldig Blut; denn du, HERR, tust, wie dir\'s gefallt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Und sie nahmen Jona und warfen ihn ins Meer. Da stund das Meer stille von seinem Wüten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Und die Leute furchteten den HERRN sehr und taten dem HERRN Opfer und Gelubde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Aber der HERR verschaffte einen groften Fisch, Jona zu verschlingen. Und Jona war im Leibe des Fisches drei Tage und drei Nachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Und Jona betete zudem HERRN, seinem Gott, im Leibe des Fisches');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'und sprach: Ich rief zu dem HERRN in meiner Angst, und er antwortete mir ich schrie aus dem Bauch der Hblle, und du horetest meine Stimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Du warfst mich in die Tiefe mitten im Meer, daß die Fluten mich umgaben; alle deine Wogen und Wellen gingen uber mich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'daß ich gedachte, ich ware von deinen Augen verstoften, ich wurde deinen heiligen Tempel nicht mehrsehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Wasser umgaben mich bis an mein Leben; die Tiefe umringete mich; Schilf bedeckte mein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Ich sank hinunter zu der Berge Grunden; die Erde hatte mich verriegeit ewiglich. Aber du hast mein Leben aus dem Verderben geführet, HERR, mein Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Da meine Seele bei mir verzagte, gedachte ich an den HERRN; und mein Gebet kam zu dir in deinen heiligen Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Die da halten über dem Nichtigen, verlassen ihre Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ich aber will mit Dank opfern; meine Gelubde will ich bezahlen dem HERRN, daß er mir geholfen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'Und der HERR sprach zum Fisch, und derselbe speiete Jona aus ans Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Und es geschah das Wort des HERRN zum andernmal zu Jona und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Mache dich auf, gehe in die grofte Stadt Ninive und predige ihr die Predigt, die ich dir sage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Da machte sich Jona auf und ging hin gen Ninive, wie der HERR gesagt hatte. Ninive aber war eine grofte Stadt Gottes, drei Tagereisen graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Und da Jona anfing, hineinzugehen eine Tagereise in die Stadt, predigte er und sprach: Es sind noch vierzig Tage, so wird Ninive untergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Da glaubten die Leute zu Ninive an Gott und lieften predigen, man sollte fasten, und zogen Sacke an, beide, graft und klein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Und da das vor den Konig zu Ninive kam, stund er auf von seinem Thron und legte seinen Purpur ab und hüllete einen Sack urn sich und setzte sich in die Asche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Und lieft ausschreien und sagen zu Ninive aus Befehl des Koniges und seiner Gewaltigen also: Es soil weder Mensch noch Tier, weder Ochsen noch Schafe etwas kosten, und man soil sie nicht weiden noch Wasser trinken lassen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'und sollen Sacke um sich hüllen beide, Menschen und Tier, und zu Gott rufen heftig; und ein jeglicher bekehre sich von seinem bosen Wege und vom Frevel seiner Hande!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Wer weiß, Gott mochte sich kehren und ihn reuen und sich wenden von seinem grimmigen Zorn, da(3> wir nicht verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Da aber Gott sah ihre Werke, dafi sie sich bekehreten von ihrem bosen Wege, reuete ihn des libels, das er geredet hatte, ihnen zu tun, und tat\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Das verdroft Jona fast sehr und ward zornig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'und betete zum HERRN und sprach: Ach, HERR, das ist\'s, das ich sagte, da ich noch in meinem Lande war; darum ich auch wollte zuvorkommen, zu fliehen aufs Meer; denn ich weiß, daß du gnadig, barmherzig, langmutig und von grafter Güte bist und lassest dich des Ubels reuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'So nimm doch nun, HERR, meine Seele von mir; denn ich wollte lieber tot sein denn leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Aber der HERR sprach: Meinest du, daß du billig zurnest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Und Jona ging zur Stadt hinaus und setzte sich gegen morgenwarts der Stadt und machte sich daselbst eine Hutte; da setzte er sich unter, in den Schatten, bis er sahe, was der Stadt widerfahren würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Gott der HERR aber verschaffte einen Kürbis, der wuchs uber Jona, daß er Schatten gab über sein Haupt, und errettete ihn von seinem libel. Und Jona freuete sich sehr uber den Kürbis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Aber der HERR verschaffte einen Wurm des Morgens, da die Morgenrote anbrach; derstach den Kürbis, daß er verdorrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Als aber die Sonne aufgegangen war, verschaffte Gott einen dürren Ostwind; und die Sonne stach Jona auf den Kopf, daß er matt ward. Da wünschte er seiner Seele den Tod und sprach: Ich wollte lieber tot sein denn leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Da sprach Gott zu Jona: Meinest du, daß du billig zurnest um den Kürbis? Und er sprach: Billig züme ich bis an den Tod!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Und der HERR sprach: Dich jammed des Kürbis, daran du nicht gearbeitet hast, hast ihn auch nicht aufgezogen, welcher in einer Nacht ward und in einer Nacht verdarb,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'und mich sollte nicht jammern Ninives, solcher groften Stadt, in welcher sind mehr denn hundertundzwanzigtausend Menschen, die nicht wissen Unterschied, was rechts Oder links ist, dazu auch viel Tiere?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Dies ist das Wort des HERRN, welches geschah zu Micha von Maresa zur Zeit Jothams, Ahas, Jehiskias, der Kdnige Judas, das er gesehen hat uber Samaria, und Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Horet, alle Volker, merke auf, Land, und alles, was drinnen ist! Denn Gott der HERR hat mit euch zu reden, ja, der HERR aus seinem heiligen Tempel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Denn siehe, der HERR wird ausgehen aus seinem Ort und herabfahren und treten auf die Hohen im Lande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'daß die Berge unter ihm schmelzen und die Taler reiften werden, gleichwie Wachs vor dem Feuer verschmilzet, wie die Wasser, so unterwarts flieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Das alles um der Ubertretung willen Jakobs und um derßünde willen des Hauses Israel. Welches ist aber die Ubertretung Jakobs? Ist\'s nicht Samaria? Welches sind aber die Hohen Judas? Ist\'s nicht Jerusalem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Und ich will Samaria zum Steinhaufen im Felde machen, die man um die Weinberge legt; und will ihre Steine ins Tal schleifen und zugrunde einbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Alle ihre Gotzen sollen zerbrochen und all ihr Hurenlohn soil mit Feuer verbrannt werden, und will alle ihre Bilder verwusten; denn sie sind von Hurenlohn versammelt und sollen auch wieder Hurenlohn werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Darüber muft ich klagen und heulen; ich muft beraubt und bloft dahergehen; ich muft klagen wie die Drachen und trauern wie die Strauften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Denn ihrer Plage ist kein Rat, die bis nach Juda kommen und bis an meines Volks Tore gen Jerusalem hinanreichen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Verkundiget esja nicht zu Gath, laftteuch nicht horen weinen, sondern gehet in die Trauerkammer und sitzet in die Asche!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Du schone Stadt muftt dahin mit alien Schanden. Die Einwohnerin Zaenans wird nicht ausziehen um des Leides willen des nachsten Hauses. Er wird\'s von euch nehmen, wenn er da sich lagern wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Die betrübte Stadt vermag sich nicht zutrosten; denn es wird das Ungluck vom HERRN kommen, auch bis an das Tor Jerusalems.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Du Stadt Lachis, spanne Lauferan und fahre davon; denn du bist der Tochter Zion der Anfang zur Sünde, und in dir sind funden die Ubertretungen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Du wirst müssen Gefangene geben so wohl als Gath. Der Stadt Achsib wird\'s mit den Konigen Israels fehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Ich will dir Maresa, den rechten Erben bringen; und die Herrlichkeit Israels soil kommen bis gen Adullam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Laft die Haare abscheren und gehe kahl über deine zarten Kinder! Mache dich gar kahl wie ein Adler; denn sie sind von dir gefangen weggefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Wehe denen, die Schaden zu tun trachten und gehen mit bosen Tucken um auf ihrem Lager, dafi sie es frith, wenn es licht wird, vollbringen, weil sie die Macht haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Sie reilien zu sich Acker und nehmen Hauser, welche sie gelustet. Also treiben sie Gewalt mit eines jeden Hause und mit eines jeden Erbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Darum spricht der HERR also: Siehe, ich gedenke uber dies Geschlecht Boses, aus dem ihr euren Hals nicht ziehen und nicht so stolz dahergehen sollet; denn es soil eine bose Zeit sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Zur selbigen Zeit wird man einen Spruch von euch machen und klagen: Es ist aus, wird man sagen; wir sind verstoret. Meines Volkes Land kriegt einen fremden Herrn. Wann wird er uns die Acker wieder zuteilen, die eruns genommen hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Jawohl, ihr werdet kein Teil behalten in der Gemeine des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Sie sagen, man solle nicht traufen; denn solche Traufe trifft uns nicht; wirwerden nicht so zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Das Haus Jakob trostet sich also: Meinest du, des HERRN Geist sei verkurzt? Sollte er solches tun wollen? Es istwahr, meine Reden sind freundlich den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Aber mein Volk hat sich aufgemacht wie ein Feind; denn sie rauben beide, Rock und Mantel, denen, so sicher dahergehen, gleichwie die, so aus dem Kriege kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Ihr treibet die Weiber meines Volks aus ihren lieben Hausern und nehmet stets von ihren jungen Kindern meinen Schmuck.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Darum machet euch auf; ihr müsset davon; ihr sollt hie nicht bleiben! Um ihrer Unreinigkeit willen müssen sie unsanft zerstoret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Wenn ich ein Irrgeist ware und ein Lügenprediger und predigte, wie sie saufen und schwelgen sollten, das ware ein Prediger fur dies Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Ich will aber dich, Jakob, versammeln ganz und die ubrigen in Israel zuhauf bringen; ich will sie wie eine Herde miteinander in einen festen Stall tun und wie eine Herde in seine Hürden, dafi es von Menschen tonen soli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Es wird ein Durchbrecher vor ihnen herauffahren; sie werden durchbrechen und zum Tor aus- und einziehen; und ihr Konig wird vor ihnen hergehen, und der HERR vornean.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Und ich sprach: Horet doch, ihr Haupter im Hause Jakob und ihr Fursten im Hause Israel! Ihr solltet es billig sein, die das Recht wu fiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Aber ihr hasset das Gute und liebet das Arge; ihr schindet ihnen die Haut ab und das Fleisch von ihren Beinen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'und fresset das Fleisch meines Volks; und wenn ihr ihnen die Haut abgezogen habt, zerbrecht ihr ihnen auch die Beine und zerleget es wie in einen Topf und wie Fleisch in einen Kessel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Darum wenn ihr nun zum HERRN schreien werdet, wird er euch nicht erhoren, sondern wird sein Angesicht vor euch verbergen zur selbigen Zeit, wie ihr mit eurem bosen Wesen verdienet habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'So spricht der HERR wider die Propheten, so mein Volk verfuhren: Sie predigen, es solle wohlgehen, wo man ihnen zu fressen gebe; wo man ihnen aber nichts ins Maul gibt, da predigen sie, es müsse ein Krieg kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Darum soli euer Gesicht zur Nacht und euer Wahrsagen zur Finsternis werden. Die Sonne soil uber den Propheten untergehen und der Tag über ihnen finster werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Und die Schauer sollen zuschanden und die Wahrsager zu Spott werden, und müssen ihr Maul alle verhullen, weil da kein Gotteswort sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Ich aber bin voll Kraft und Geistes des HERRN, voll Rechts und Starke, dafi ich Jakob sein Ubertreten und Israel seine Sunde anzeigen darf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'So horet doch dies, ihr Haupter im Hause Jakob und ihr Fursten im Hause Israel, die ihr das Recht verschmahet und alles, was aufrichtig ist, verkehret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'die ihr Zion mit Blut bauet und Jerusalem mit Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Ihre Haupter richten um Geschenke, ihre Priester lehren um Lohn, und ihre Propheten wahrsagen um Geld, verlassen sich auf den HERRN und sprechen: Ist nicht der HERR unter uns? Es kann kein Unglück fiber uns kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Darum wird Zion um euretwillen wie ein Feld zerpflüget und Jerusalem zum Steinhaufen und der Berg des Tempels zu einer wilden Hohe werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'In den letzten Tagen aber wird der Berg, darauf des HERRN Haus stehet, gewiß sein, hoher denn alle Berge, und über die Hügel erhaben sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Und die Volker werden herzulaufen, und viel Heiden werden gehen und sagen: Kommt, laßt uns hinauf zum Berge des HERRN gehen und zum Hause des Gottes Jakobs, dafi er uns lehre seine Wege, und wir auf seiner Stralie wandeln! Denn aus Zion wird das Gesetz ausgehen und des HERRN Wort aus Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Er wird unter großen Volkern richten und viel Heiden strafen in fernen Landen. Sie werden ihre Schwerter zu Pflugscharen und ihre Spieße zu Sicheln machen. Es wird kein Volk wider das andere ein Schwert aufheben und werden nicht mehr kriegen lernen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Ein jeglicher wird unter seinem Weinstock und Feigenbaum wohnen ohne Scheu; denn der Mund des HERRN Zebaoth hat\'s geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Denn ein jeglich Volk wird wandeln im Namen seines Gottes; aber wir werden wandeln im Namen des HERRN, unsers Gottes, immer und ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Zur selbigen Zeit, spricht der HERR, will ich die Lahme versammeln und die Verstoßene zuhauf bringen, und die ich geplaget habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Und will die Lahme machen, dafi sie Erben haben soil, und die Verstoßene zum großen Volk machen; und der HERR wird Konig uber sie sein auf dem Berge Zion von nun an bis in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Und du Turm Eder, eine Feste der Tochter Zion, es wird deine guldene Rose kommen, die vorige Herrschaft, das Konigreich der Tochter Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Warum hangst du dich denn jetzt an andere Freunde? 1st der Konig nicht bei dir, und sind deine Ratgeber alle hinweg, daß dich also das Weh ankommen ist wie eine in Kindesnoten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Lieber, leide doch solch Weh und krachze, du Tochter Zion, wie eine in Kindesnoten! Denn du mufit zwar zur Stadt hinaus und auf dem Felde wohnen und gen Babel kommen; aber doch wirst du von dannen wieder errettet werden. Daselbst wird dich der HERR erlosen von deinen Feinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Denn es werden schier sich viel Heiden wider dich rotten und sprechen: Sie ist verbannet; wirwollen unsere Lust an Zion sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Aber sie wissen des HERRN Gedanken nicht und merken seinen Ratschlag nicht, daß er sie zuhauf gebracht hat wie Garben auf der Tenne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Darum mache dich auf und dresche, du Tochter Zion! Denn ich will direiserne Horner und eherne Klauen machen, und sollst viel Volker zerschmeilien; so will ich ihr Gut dem HERRN verbannen und ihre Habe dem Herrscher der ganzen Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 14, 'Aber nun, du Kriegerin, ruste dich! Denn man wird uns belagern und den Richter Israels mit der Rute auf den Backen schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Und du, Bethlehem Ephrata, die du klein bist unter den Tausenden in Juda, aus dir soil mir der kommen, der in Israel HERR sei, welches Ausgang von Anfang und von Ewigkeit her gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Indes lalit er sie plagen bis auf die Zeit, daß die, so gebaren soil, geboren habe. Da werden dann die ubrigen seiner Bruder wiederkommen zu den Kindern Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Er aber wird auftreten und weiden in Kraft des HERRN und im Siege des Namens seines Gottes. Und sie werden wohnen; denn er wird zur selbigen Zeit herrlich werden; soweit die Welt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Dazu werden wir auch Frieden haben vor dem Assur, der jetzt in unser Land gefallen ist und unsere Hauser zertreten hat. Denn es werden sieben Hirten und acht Fursten uber ihn erwecket werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'die das Land Assur verderben mit dem Schwert und das Land Nimrods mit ihren blolien Waffen. Also werden wir von Assur gerettet werden, der in unser Land gefallen ist und unsere Grenze zertreten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Es werden auch die Ubrigen aus Jakob unter vielen Volkern sein wie ein Tau vom HERRN und wie die Tropflein aufs Gras, das auf niemand harret noch auf Menschen wartet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Ja, die Ubrigen aus Jakob werden unter den Heiden bei vielen Volkern sein wie ein Lowe unter den Tieren im Walde, wie ein junger Lowe unter einer Herde Schafe, welchem niemand wehren kann, wenn er dadurchgehet, zertritt und zerreifiet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Denn deine Hand wird siegen wider alle deine Widerwartigen, daß alle deine Feinde müssen ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Zur selbigen Zeit, spricht der HERR, will ich deine Rosse von dir tun und deine Wagen umbringen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'und will die Stadte deines Landes ausrotten und alle deine Festen zerbrechen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'und will die Zauberer bei dir ausrotten, daß keine Zeichendeuter bei dir bleiben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Ich will deine Bilder und Gotzen von dir ausrotten, daß du nicht mehr sollst anbeten deiner Hande Werk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'und will deine Haine zerbrechen und deine Stadte vertilgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Und ich will Rache üben mit Grimm und Zorn an alien Heiden, so nicht gehorchen wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Horet doch, was der HERR sagt: Mache dich auf und schilt die Berge und lali die Hugel deine Stimme horen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Horet, ihr Berge, wie der HERR strafen will, samt den starken Grundfesten der Erde! Denn der HERR will sein Volk schelten und will Israel strafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Was hab ich dir getan, mein Volk, und womit habe ich dich beleidiget? Das sage mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Hab ich dich doch aus Agyptenland gefuhret und aus dem Diensthause erloset und vor dir hergesandt Mose, Aaron und Mirjam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Mein Volk, denke doch daran, was Balak, der Konig in Moab, vorhatte, und was ihm Bileam, der Sohn Beors, antwortete, von Sittim an bis gen Gilgal; daran ihrja merken solltet, wie der HERR euch alles Gute getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Womit soil ich den HERRN versohnen? Mit Bucken vor dem hohen Gott? Soil ich mit Brandopfern und jahrigen Kalbern ihn versohnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Meinest du, der HERR habe Gefallen an viel tausend Widdern Oder am 01, wenn es gleich unzahlige Strome voll waren? Oder soil ich meinen ersten Sohn fur meine Ubertretung geben Oder meines Leibes Frucht fur die Sünde meiner Seele?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Es ist dir gesagt, Mensch, was gut ist, und was der HERR von dir fordert, namlich Gottes Wort halten und Liebe üben und demutig sein vordeinem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Es wird des HERRN Stimme über die Stadt rufen; aber wer deinen Namen furchtet, dem wird\'s gelingen. Horet, ihr Stamme, was geprediget wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Noch bleibet unrecht Gut in des Gottlosen Hause und derfeindselige, geringe Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Oder sollt ich die unrechte Waage und falsch Gewicht im Sackel billigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'durch welche ihre Reichen viel Unrechts tun? Und ihre Einwohner gehen mit Lugen um und haben falsche Zungen in ihrem Halse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Darum will ich dich auch anfahen zu plagen und dich um deiner Sunde willen wüst machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du sollst nicht genug zu essen haben und sollst verschmachten. Und was du erhaschest, soil doch nicht davonkommen; und was davonkommt, will ich doch dem Schwert überantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Du sollst saen und nicht ernten; du sollst 01 keltern und dich mit demselben nicht salben, und Most keltern und nicht Wein trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Denn man halt die Weise Amris und alle Werke des Hauses Ahab und folgt ihrem Rat. Darum will ich dich zur Wuste machen und ihre Einwohner, daß man sie anpfeifen soil; und sollt meines Volks Schmach tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ach, es gehet mir wie einem, der im Weinberge nachlieset, da man keine Trauben findet zu essen, und wollte doch gerne der besten Fruchte haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Die frommen Leute sind weg in diesem Lande; und die Gerechten sind nicht mehr unter den Leuten. Sie lauern alle aufs Blut; ein jeglicherjagt den andern, daß er ihn verderbe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'und meinen, sie tun wohl daran, wenn sie Boses tun. Was der Furst will, das spricht der Richter, daß er ihm wieder einen Dienst tun soil. Die Gewaltigen raten nach ihrem Mutwillen, Schaden zu tun, und drehen es, wie sie wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Der Beste unter ihnen ist wie ein Dorn und der Redlichste wie eine Hecke. Aber wenn der Tag deiner Prediger kommen wird, wenn du heimgesucht sollst werden, da werden sie dann nicht wissen, wo aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Niemand glaube seinem Nachsten, niemand verlasse sich auf Fursten! Bewahre die Tür deines Mundes vor der, die in deinen Armen schlaft!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Denn der Sohn verachtet den Vater, die Tochter setzt sich wider die Mutter, die Schnur ist wider die Schwieger; und des Menschen Feinde sind sein eigen Hausgesinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Ich aber will auf den HERRN schauen und des Gottes meines Heils erwarten; mein Gott wird mich horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Freue dich nicht, meine Feindin, daß ich daniederliege! Ich werde wieder aufkommen. Und so ich im Finstern sitze, so ist doch der HERR mein Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Ich will des HERRN Zorn tragen, denn ich habe wider ihn gesundiget, bis er meine Sache ausfuhre und mir Recht schaffe. Er wird mich ans Licht bringen, daß ich meine Lust an seiner Gnade sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Meine Feindin wird\'s sehen müssen und mit aller Schande bestehen, die jetzt zu mir sagt: Wo ist der HERR, dein Gott? Meine Augen werden\'s sehen, daß sie dann wie ein Kot auf der Gasse zertreten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Zu der Zeit werden deine Mauern gebauet werden und Gottes Wort weit auskommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Und zur selbigen Zeit werden sie von Assur und von festen Stadten zu dir kommen, von den festen Stadten bis an das Wasser, von einem Meer zum andern, von einem Gebirge zum andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Denn das Land wird wüst sein seiner Einwohner halben, um der Frucht willen ihrer Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Du aberweide dein Volk mit deinem Stabe, die Herde deines Erbteils, die da wohnen beide, im Walde alleine und auf dem Felde; lati sie zu Basan und Gilead weiden wie vor alters!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Ich will sie Wunder sehen lassen, gleichwie zu der Zeit, da sie aus Agyptenland zogen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'daß die Heiden sehen, und alle ihre Gewaltigen sich schamen sollen und die Hand auf ihren Mund legen und ihre Ohren zuhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Sie sollen Staub lecken wie die Schlangen und wie das Gewürm auf Erden erzittern in ihren Lochern. Sie werden sich furchten vor dem HERRN, unserm Gott, und vor dir sich entsetzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Wo ist solch ein Gott, wie du bist? der die Sunde vergibt und erlasset die Missetat den Ubrigen seines Erbteils; der seinen Zorn nicht ewiglich behalt; denn er ist barmherzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Erwird sich unser wieder erbarmen, unsere Missetat dampfen und alle unsere Sünden in die Tiefe des Meers werfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du wirst dem Jakob die Treue und Abraham die Gnade halten, wie du unsern Vatern vorlangst geschworen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Dies ist die Last uber Ninive und das Buch der Weissagung Nahums von Elkos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Der HERR ist ein eifriger Gott und ein Racher, ja ein Racher ist der HERR und zornig; der HERR ist ein Racher wider seine Widersacher, und der es seinen Feinden nicht vergessen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Der HERR ist geduldig und von grower Kraft, vor welchem niemand unschuldig ist; er ist der HERR, des Wege im Wetter und Sturm sind und unter seinen Füften dicker Staub,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'der das Meer schilt und trocken macht und alle Wasser vertrocknet. Basan und Karmel verschmachten, und was auf dem Berge Libanon blühet, verschmachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Die Berge zittern vor ihm, und die Hugel zergehen; das Erdreich bebet vor ihm, dazu der Weltkreis und alle, die drinnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Wer kann vor seinem Zorn stehen und wer kann vor seinem Grimm bleiben? Sein Zorn brennet wie Feuer, und die Felsen zerspringen vor ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Der HERR ist gütig und eine Feste zur Zeit der Not und kennet die, so auf ihn trauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Wenn die Flut uberher lauft, so macht er\'s mit derselbigen ein Ende; aber seine Feinde verfolgt er mit Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Was gedenket ihr wider den HERRN? Er wird\'s doch ein Ende machen; es wird das Ungluck nicht zweimal kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Denn gleich als wenn die Dornen, so noch ineinanderwachsen und im besten Saft sind, verbrannt werden, wie ganz durr Stroh,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'also wird sein der Schalksrat, der von dir kommt und Boses wider den HERRN gedenket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So spricht der HERR: Sie kommen so gerustet und machtig, als sie wollen, sollen sie doch umgehauen werden und dahinfahren. Ich habe dich gedemutiget; aber ich will dich nicht wiederum demutigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Alsdann will ich sein Joch, das du tragst, zerbrechen und deine Bande zerreifien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Aber wider dich hat der HERR geboten, daß deines Namens Same keiner mehr soil bleiben. Vom Hause deines Gottes will ich dich ausrotten, die Gotzen und Bilderwill ich dirzum Grabe machen; denn du bist zunichte worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Siehe, auf den Bergen kommen Fufte eines guten Boten, der da Frieden predigt: Halte deine Feiertage, Juda, und bezahle deine Gelubde! Denn es wird der Schalk nicht mehr fiber dich kommen; er ist gar ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Es wird der Zerstreuer wider dich heraufziehen und die Feste belagern. Aber ja, berenne die Strafte wohl, niste dich aufs beste und starke dich aufs gewaltigste!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Denn der HERR wird die Hoffart Jakobs vergelten wie die Hoffart Israels; denn die Ableser werden sie ablesen und ihre Feser verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Die Schilde seiner Starken sind rot, sein Heeresvolk siehet wie Purpur, seine Wagen leuchten wie Feuer, wenn er treffen will; ihre Spiefte beben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Die Wagen rollen auf den Gassen und rasseln auf den Straften; sie blicken wie Fackeln und fahren untereinander her wie die Blitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Er aber wird an seine Gewaltigen gedenken; doch werden dieselbigen fallen, wo sie hinaus wollen; und werden eilen zur Mauer und zu dem Schirm, da sie sicher seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Aber die Tore an den Wassern werden doch geoffnet, und der Palast wird untergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Die Konigin wird gefangen weggefuhret werden; und ihre Jungfrauen werden seufzen wie die Tauben und an ihre Brust schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Denn Ninive ist wie ein Teich voll Wassers; aber dasselbige wird verflieften müssen. Stehet, stehet! (werden sie rufen); aber da wird sich niemand umwenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'So raubet nun Silber, raubet Gold! Denn hie ist der Schatze kein Ende und die Menge aller kdstlichen Kleinode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Aber nun muft sie rein abgelesen und geplundert werden, daß ihr Herz muft verzagen, die Kniee schlottern, alle Lenden zittern, und aller Angesicht bleich sehen, wie ein Topf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Wo ist nun die Wohnung der Lowen und die Weide der jungen Lowen, da der Lowe und die Lowin mit den jungen Lowen wandelten, und niemand durfte sie scheuchen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Sondern der Lowe raubete genug fur seine Jungen und würgete es seinen Lowinnen; seine Hohlen füllete er mit Raub und seine Wohnung mit dem, das er zerrissen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 14, 'Siehe, ich will an dich, spricht der HERR Zebaoth, und deine Wagen im Rauch anzünden; und das Schwert soil deine jungen Lowen fressen; und will deines Raubens ein Ende machen auf Erden, daß man deiner Boten Stimme nicht mehr horen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Wehe der morderischen Stadt, die voll Lugen und Rauberei ist und von ihrem Rauben nicht lassen will!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Denn da wird man horen die Geifteln klappen und die Rader rasseln und die Rosse schreien und die Wagen rollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Er bringet Reiter herauf mit glanzenden Schwertern und mit blitzenden Spieften. Da liegen viel Erschlagene und grofte Haufen Leichname, daß derselbigen keine Zahl ist und man uber ihre Leichname fallen muft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Das alles um der großen Hurerei willen der schonen lieben Hure, die mit Zauberei umgehet, die mit ihrer Hurerei die Heiden und mit ihrer Zauberei Land und Leute erworben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Siehe, ich will an dich, spricht der HERR Zebaoth! Ich will dir dein Gebrame aufdecken unter dein Angesicht und will den Heiden deine Bloße und den Konigreichen deine Schande zeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Ich will dich ganz greulich machen und dich schanden und ein Scheusal aus dir machen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'daß alle, die dich sehen, von dir fliehen und sagen sollen: Ninive ist verstoret; wer will Mitleid mit ihr haben, und wo soil ich dir Troster suchen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Meinest du, du seiest besser denn die Stadt No der Regenten, die da lag an den Wassern und ringsumher Wasser hatte, welcher Mauern und Feste war das Meer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Mohren und Agypten war ihre unzahlige Macht, Put und Libyen waren deine Hilfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Noch hat sie müssen vertrieben werden und gefangen wegziehen, und sind ihre Kinder auf alien Gassen erschlagen worden; und um ihre Edlen wart man das Los, und alle ihre Gewaltigen wurden in Ketten und Fesseln gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Also mußt du auch trunken werden und dich verbergen und eine Feste suchen vor dem Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Alle deine festen Stadte sind wie Feigenbaume mit reifen Feigen, wenn man sie schüttelt, daß sie dem ins Maul fallen, der sie essen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Siehe, dein Volk soil zu Weibern werden in dir, und die Tore deines Landes sollen deinen Feinden geoffnet werden; und das Feuer soil deine Riegel verzehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Schdpfe dir Wasser, denn du wirst belagert werden; bessere deine Festen; gehe in den Ton und tritt den Leimen und mache starke Ziegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Aber das Feuer wird dich fressen und das Schwert toten; es wird dich abfressen wie die Kafer, es wird dich uberfallen wie Kafer, es wird dich überfallen wie Heuschrecken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Du hast mehr Handler, denn Sterne am Himmel sind; aber nun werden sie sich ausbreiten wie Kafer und davonfliegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Deiner Herren ist so viel als der Heuschrecken und deiner Hauptleute als der Kafer, die sich an die Zaune lagern in den kalten Tagen; wenn aber die Sonne aufgehet, heben sie sich davon, daß man nicht weifi, wo sie bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Deine Hirten werden schlafen, o Konig zu Assur, deine Machtigen werden sich legen und dein Volk wird auf den Bergen zerstreuet sein, und niemand wird sie versammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Niemand wird um deinen Schaden trauern, noch sich um deine Plage kranken, sondern alle, die solches von dir horen, werden mit ihren Handen uber dich klappen. Denn uber wen ist nicht deine Bosheit ohne Unterlali gegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Dies ist die Last, welche der Prophet Habakuk gesehen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'HERR, wie lange soil ich schreien, und du willst nicht horen? Wie lange soil ich zu dir rufen uber Frevel, und du willst nicht helfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Warum lassest du mich sehen Muhe und Arbeit? Warum zeigest du mir Raub und Frevel um mich? Es gehet Gewalt uber Recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Darum gehet es gar anders denn recht und kann keine rechte Sache gewinnen; denn der Gottlose ubervorteilt den Gerechten, darum gehen verkehrte Urteile.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Schauet unter den Heiden, sehet und verwundert euch; denn ich will etwas tun zu euren Zeiten, welches ihr nicht glauben werdet, wenn man davon sagen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Denn siehe, ich will die Chaldaer erwecken, ein bitter und schnell Volk, welches ziehen wird, soweit das Land ist, Wohnungen einzunehmen, die nicht sein sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'und wird grausam und schrecklich sein, das da gebeut und zwinget, wie es will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Ihre Rosse sind schneller denn die Parden; so sind sie auch beißiger denn die Wolfe des Abends. Ihre Reiter ziehen mit großen Haufen von feme daher, als flogen sie, wie die Adler eilen zum Aas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Sie kommen aliesamt, daß sie Schaden tun; wo sie hin wollen, reilien sie hindurch wie ein Ostwind und werden Gefangene zusammenraffen wie Sand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Sie werden der Konige spotten und der Fursten werden sie lachen. Alle Festungen werden ihnen ein Scherz sein; denn sie werden Schutt machen und sie doch gewinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Alsdann werden sie einen neuen Mut nehmen, werden fortfahren und sich versundigen; dann muß ihr Sieg ihres Gottes sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Aberdu, HERR, mein Gott, mein Heiliger, derdu von Ewigkeit her bist, laß uns nicht sterben, sondern laß sie uns, o HERR, nur eine Strafe sein und laß sie, o unser Hort, uns nur zuchtigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Deine Augen sind rein, daß du Gbels nicht sehen magst, und dem Jammer kannst du nicht zusehen. Warum siehest du denn zu den Verachtern und schweigest, daß der Gottlose verschlinget den, der frommer denn er ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'und lasset die Menschen gehen wie Fische im Meer, wie Gewürm, das keinen, Herrn hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Sie ziehen\'s alles mit dem Hamen und fahen\'s mit ihrem Netze und sammeln\'s mit ihrem Gam; des freuen sie sich und sind frohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Darum opfern sie ihrem Netze und rauchern ihrem Gam, weil durch dieselbigen ihr Teil so fett und ihre Speise so vollig worden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Derhalben werfen sie ihr Netz noch immer aus und wollen nicht aufhoren, Leute zu erwurgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Hie stehe ich auf meiner Hut und trete auf meine Feste und schaue und sehe zu, was mir gesagt werde, und was ich antworten solle dem, der mich schilt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Der HERR aber antwortet mir und spricht: Schreibe das Gesicht und male es auf eine Tafel, daß es lesen konne, wer voruberlauft (namlich also):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Die Weissagung wird ja noch erfüllet werden zu seiner Zeit und wird endlich frei an Tag kommen und nicht auften bleiben. Ob sie aber verzeucht, so harre ihrer; sie wird gewiftlich kommen und nicht verziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Siehe, wer halsstarrig ist, der wird keine Ruhe in seinem Herzen haben; denn der Gerechte lebet seines Glaubens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Aber der Wein betrugt den stolzen Mann, daß er nicht bleiben kann, welcher seine Seele aufsperret wie die Holle, und ist gerade wie der Tod, der nicht zu sattigen ist, sondern rafft zu sich alle Heiden und sammelt zu sich alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Was gilt\'s aber? Dieselbigen alle werden einen Spruch von ihm machen und eine Sage und Sprichwort und werden sagen: Wehe dem, der sein Gut mehret mit fremdem Gut! Wie lange wird\'s wahren? und ladet nur viel Schlammes auf sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'O wie plotzlich werden aufwachen, die dich beiften, und erwachen, die dich wegstoften! Und du muftt ihnen zuteil werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Denn du hast viel Heiden geraubt; so werden dich wieder rauben alle ubrigen von den Volkern urn der Menschen Bluts willen und urn des Frevels willen, im Lande und in der Stadt und an alien, die drinnen wohnen, begangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Wehe dem, der da geizet zum Ungluck seines Hauses, auf daß er sein Nest in die Hohe lege, daß er dem Unfall entrinne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Aber dein Ratschlag wird zur Schande deines Hauses geraten; denn du hast zu viel Volker zerschlagen und hast mit allem Mutwillen gesundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Denn auch die Steine in der Mauer werden schreien, und die Balken am Gesperre werden ihnen antworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Wehe dem, der die Stadt mit Blut bauet und zurichtet die Stadt mit Unrecht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Ist\'s nicht also, daß vom HERRN Zebaoth geschehen wird? Was dir die Volker gearbeitet haben, muft mit Feuerverbrennen, und daran die Leute müde worden sind, muft verloren sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Denn die Erde wird voll werden von Erkenntnis der Ehre des HERRN, wie Wasser, das das Meer bedeckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Wehe dir, derdu deinem Nachsten einschenkest und mischest deinen Grimm darunter und trunken machest, daß du seine Scham sehest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Man wird dich auch sattigen mit Schande fur Ehre. So saufe du nun auch, daß du taumelst; denn dich wird umgeben der Kelch in der Rechten des HERRN, und muftt schandlich speien fur deine Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Denn der Frevel, am Libanon begangen, wird dich überfallen, und die verstorten Tiere werden dich schrecken urn der Menschen Bluts willen und urn des Frevels willen, im Lande und in der Stadt und an alien, die drinnen wohnen, begangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Was wird dann helfen das Bild, das sein Meister gebildet hat, und das falsche gegossene Bild, darauf sich verlaftt sein Meister, daß er stumme Gotzen machte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Wehe dem, der zum Holz spricht: Wache auf! und zum stummen Stein: Stehe auf! Wie sollt es lehren? Siehe, es ist mit Gold und Silber uberzogen, und ist kein Odem in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Aber der HERR ist in seinem heiligen Tempel. Es sei vor ihm stille alle Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Dies ist das Gebet des Propheten Habakuk fur die Unschuldigen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'HERR, ich habe dein Gerucht gehoret, daß ich mich entsetze. HERR, du machst dein Werk lebendig mitten in den Jahren und lassest es kund werden mitten in den Jahren. Wenn Trubsal da ist, so denkest du der Barmherzigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gott kam vom Mittage und der Heilige vom Gebirge Paran. Sela. Seines Lobes war der Himmel voll und seiner Ehre war die Erde voll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Sein Glanz war wie Licht; Glanze gingen von seinen Handen; daselbstwar heimlich seine Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Vor ihm her ging Pestilenz, und Plage ging aus, wo er hintrat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Er stund und maft das Land; er schauete und zertrennete die Heiden, daß der Welt Berge zerschmettert wurden und sich bucken muftten die Hugel in der Welt, da er ging in der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Ich sah der Mohren Hütten in Mühe und der Midianiter Gezelte betrubt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Warestdu nicht zornig, HERR, in der Flut und dein Grimm in den Wassern und dein Zorn im Meer, da du auf deinen Rossen rittest und deine Wagen den Sieg behielten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Du zogest den Bogen hervor, wie du geschworen hattest den Stammen, Sela, und teiltest die Strome ins Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Die Berge sahen dich, und ihnen ward bange; der Wasserstrom fuhr dahin, die Tiefe lieft sich horen, die Hohe hub die Hande auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Sonne und Mond stunden still. Deine Pfeile fuhren mit Glanzen dahin und deine Speere mit Blicken des Blitzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Du zertratest das Land im Zorn und zerdroschest die Heiden im Grimm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du zogest aus, deinem Volk zu helfen, zu helfen deinem Gesalbten. Du zerschmissest das Haupt im Hause des Gottlosen und entblolietest die Grundfeste bis an den Hals. Sela.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Du wolltest fluchen dem Zepter des Haupts samt seinen Flecken, die wie ein Wetter kommen, mich zu zerstreuen, und freuen sich, als fratien sie den Elenden verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Deine Pferde gehen im Meer, im Schlamm grower Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Weil ich solches hore, ist mein Bauch betrubt, meine Lippen zittern von dem Geschrei; Eiter gehet in meine Gebeine, ich bin bei mir betrubt. 0 daß ich ruhen mochte zur Zeit der Trubsal, da wir hinaufziehen zum Volk, das uns bestreitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Denn der Feigenbaum wird nicht grunen, und wird kein Gewachs sein an den Weinstocken; die Arbeit am Olbaum fehlet und die Acker bringen keine Nahrung, und Schafe werden aus den Hürden gerissen, und werden keine Rinder in den Stallen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Aber ich will mich freuen des HERRN und frohlich sein in Gott, meinem Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Denn der HERR Herr ist meine Kraft und wird meine Fufie machen wie Hirschfufie und wird mich in der Hohe führen, dafi ich singe auf meinem Saitenspiel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Dies ist das Wort des HERRN, welches geschah zu Zephanja, dem Sohn Chusis, des Sohns Gedaljas, des Sohns Amarjas, des Sohns Hiskias, zur Zeit Josias, des Sohns Amons, des Konigs Judas:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Ich will alles aus dem Lande wegnehmen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Ich will beide, Menschen und Vieh, beide, Vogel des Himmels und Fische im Meer, wegnehmen samt den Argernissen und den Gottlosen; ja, ich will die Menschen ausreuten aus dem Lande, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Ich will meine Hand ausstrecken uber Juda und uber alle, die zu Jerusalem wohnen; also will ich das übrige von Baal ausreuten, dazu den Namen der Kamarim und Priester aus diesem Ort');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'und die, so auf den Dachern des Himmels Heer anbeten, die es anbeten und schworen doch bei dem HERRN und zugleich bei Malchom,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'und die vom HERRN abfallen und die nach dem HERRN nichts fragen und ihn nicht achten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Seid stille vor dem Herrn HERRN; denn des HERRN Tag ist nahe! Denn der HERR hat ein Schlachtopfer zubereitet und seine Gaste dazu geladen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Und am Tage des Schlachtopfers des HERRN will ich heimsuchen die Fürsten und des Konigs Kinder und alle, die ein fremd Kleid tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Auch will ich zur selbigen Zeit die heimsuchen, so uber die Schwelle springen, die ihrer Herren Haus fullen mit Rauben und Trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Zur selbigen Zeit, spricht der HERR, wird sich ein laut Geschrei erheben von dem Fischtor an und ein Geheul von dem andern Tor und ein grower Jammer auf den Hügeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Heulet, die ihr in der Muhle wohnet! Denn das ganze Kramervolk ist dahin, und alle, die Geld sammeln, sind ausgerottet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Zur selbigen Zeit will ich Jerusalem mit Laternen durchsuchen und will heimsuchen die Leute, die auf ihren Hefen liegen und sprechen in ihrem Herzen: Der HERR wird weder Gutes noch Boses tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Und sollen ihre Guterzum Raube werden und ihre Hauser zur Wuste. Sie werden Hauser bauen und nicht drinnen wohnen; sie werden Weinberge pflanzen und keinen Wein davon trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Denn des HERRN grower Tag ist nahe; erist nahe und eilet sehr. Wenn das Geschrei vom Tage des HERRN kommen wird, so werden die Starken alsdann bitterlich schreien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Denn dieser Tag ist ein Tag des Grimmes, ein Tag der Trubsal und Angst, ein Tag des Wetters und Ungestüms, ein Tag der Finsternis und Dunkels, ein Tag der Wolken und Nebel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'ein Tag der Posaunen und Trommeten wider die festen Stadte und hohen Schlosser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Ich will den Leuten bange machen, daß sie umhergehen sollen wie die Blinden, darum daß sie wider den HERRN gesündiget haben. Ihr Blut soli vergossen werden, als ware es Staub, und ihr Leib, als ware es Kot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Es wird sie ihr Silber und Gold nicht erretten mogen am Tage des Zorns des HERRN, sondern das ganze Land soil durch das Feuer seines Eifers verzehret werden; denn er wird\'s plotzlich ein Ende machen mit alien, die im Lande wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Sammelt euch und kommet her, ihr feindseliges Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ehe denn das Urteil ausgehe, daß ihr, wie die Spreu bei Tage, dahinfahret, ehe denn des HERRN grimmiger Zorn über euch komme, ehe der T ag des HERRN Zorns uber euch komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Suchet den HERRN, alle ihr Elenden im Lande, die ihr seine Rechte haltet! Suchet Gerechtigkeit, suchet Demut, auf daß ihr am Tage des HERRN Zorns moget verborgen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Denn Gasa muß verlassen werden und Askalon wust werden; Asdod soil im Mittag vertrieben werden und Akaron ausgewurzelt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Wehe denen, so am Meer hinab wohnen, den Kriegern! Des HERRN Wort wird über euch kommen. Du, Kanaan, der Philister Land, ich will, dich umbringen, daß niemand mehrda wohnen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Es sollen am Meer hinab eitel Hirtenhauser und Schafhürden sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Und dasselbe soil den übrigen vom Hause Juda zuteil werden, daß sie darauf weiden sollen. Des Abends sollen sie sich in den Hausern Askalons lagern, wenn sie nun der HERR, ihr Gott, wiederum heimgesucht und ihr Gefangnis gewendet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Ich habe die Schmach Moabs und das Lastern der Kinder Ammon gehoret, damit sie mein Volk geschmahet und auf desselbigen Grenzen sich gerühmet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Wohlan, so wahr ich lebe, spricht der HERR Zebaoth, der Gott Israels: Moab soil wie Sodom und die Kinder Ammon wie Gomorrha werden, ja, wie ein Nesselstrauch und Salzgrube und eine ewige Wüstnis. Die übrigen meines Volks sollen sie rauben und die Uberbliebenen meines Volks sollen sie erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Das soil ihnen begegnen für ihre Hoffart, daß sie des HERRN Zebaoth Volk geschmahet und sich gerühmet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Schrecklich wird der HERR uber sie sein; denn er wird alle Gotter auf Erden vertilgen. Und sollen ihn anbeten alle Inseln unter den Heiden, ein jeglicher an seinem Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Auch sollt ihr Mohren durch mein Schwert erschlagen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Und erwird seine Hand strecken uber Mitternacht und Assur umbringen. Ninive wird er ode machen, dürr wie eine Wüste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'daß drinnen sich lagern werden allerlei Tiere unter den Heiden; auch Rohrdommeln und Igel werden wohnen auf ihren Türmen und werden in den Fenstern singen und die Raben auf den Balken; denn die Zedernbretter sollen abgerissen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Das ist die frohliche Stadt, die so sicher wohnete und sprach in ihrem Herzen: Ich bin\'s, und keine mehr! Wie ist sie so wüst worden, daß die Tiere drinnen wohnen! Und wer vorubergehet, pfeifet sie an und kiappet mit der Hand uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Wehe der scheußlichen, unflatigen, tyrannischen Stadt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Sie will nicht gehorchen noch sich zuchtigen lassen; sie will auf den HERRN nicht trauen noch sich zu ihrem Gott halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Ihre Fursten sind unter ihnen brullende Lowen und ihre Richter Wolfe am Abend, die nichts lassen bis auf den Morgen uberbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ihre Propheten sind leichtfertig und Verachter. Ihre Priester entweihen das Heiligtum und deuten das Gesetzfreventlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Aber der HERR, der unter ihnen ist, lehret wohl recht und tut kein Arges. Er laßt alle Morgen seine Rechte offentlich lehren und laßt nicht ab; aber die bosen Leute wollen sich nicht schamen lernen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Darum will ich diese Leute ausrotten, ihre Schlosser verwüsten und ihre Gassen so leer machen, daß niemand darauf gehen soil; ihre Stadte sollen zerstoret werden, daß niemand mehr da wohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Ich ließ dir sagen: Mich sollst du furchten und dich lassen zuchtigen, so würde ihre Wohnung nicht ausgerottet und der keines kommen, damit ich sie heimsuchen werde. Aber sie sind fleißig, allerlei Bosheit zu üben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Darum, spricht der HERR, musset ihr wiederum mein auch harren, bis ich mich aufmache zu seiner Zeit, da ich auch rechten werde und die Heiden versammeln und die Konigreiche zuhauf bringen, meinen Zorn über sie zu schutten, ja, alien Zorn meines Grimmes. Denn alle Welt soil durch meines Eifers Feuer verzehret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Alsdann will ich den Vdlkern anders predigen lassen mit freundlichen Lippen, daß sie alle sollen des HERRN Namen anrufen und ihm dienen eintrachtiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Man wird mir meine Anbeter, namlich die Zerstreuten von jenseit des Wassers im Mohrenlande, herbringen zum Geschenk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Zur selbigen Zeit wirst du dich nicht mehr schamen alles deines Tuns, damit du wider mich übertreten hast; denn ich will die stolzen Heiligen von dir tun, daß du nicht mehr sollst dich erheben urn meines heiligen Berges willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Ich will in dir lassen uberbleiben ein arm, gering Volk; die werden auf des HERRN Namen trauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Die Ubrigen in Israel werden kein Boses tun noch falsch reden, und man wird in ihrem Munde keine betrugliche Zunge finden, sondern sie sollen weiden und ruhen, ohne alle Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Jauchze, du Tochter Zion! Rufe, Israel! Freue dich und sei frohlich von ganzem Flerzen, du Tochter Jerusalem!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Dennder HERR hat deine Strafe weggenommen und deine Feinde abgewendet. Der HERR, der Konig Israels, ist bei dir, dati du dich vor keinem Unglück mehr furchten darfst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Zurselbigen Zeitwird man sprechen zu Jerusalem: Furchte dich nicht! und zu Zion: Laß, deine Hande nicht la(2> werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Denn der HERR, dein Gott, ist bei dir, ein starker Heiland; er wird sich über dich freuen und dir freundlich sein und vergeben und wird uber dir mit Schall frohlich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Die, so durch Satzungen geangstet waren, will ich wegschaffen, dati sie von dir kommen, welche Satzungen ihre Last waren, davon sie Schmach hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Siehe, ich will\'s mit alien denen ausmachen zur selbigen Zeit, die dich beleidigen; und will der Hinkenden helfen und die Verstoliene sammeln; und will sie zu Lob und Ehren machen in alien Landen, darin man sie verachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Zurselbigen Zeit will ich euch hereinbringen und euch zur selbigen Zeit versammeln. Denn ich will euch zu Lob und Ehren machen unter alien Volkern auf Erden, wenn ich euer Gefangnis wenden werde vor euren Augen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im andern Jahrdes Konigs Darius, im sechsten Monden, am ersten Tage des Monden, geschah des HERRN Wort durch den Propheten Haggai zu Serubabel, dem Sohn Sealthiels, dem Fursten Judas, und zu Josua, dem Sohn Jozadaks, dem Hohenpriester, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So spricht der HERR Zebaoth: Dies Volk spricht: Die Zeit ist noch nicht da, daß man des HERRN Haus baue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Und des HERRN Wort geschah durch den Propheten Haggai:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Aber eure Zeit ist da, daß ihr in getafelten Hausern wohnet, und dies Haus muß wüst stehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nun, so spricht der HERR Zebaoth: Schauet, wie es euch gehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr saet viel und bringet wenig ein; ihr esset und werdet doch nicht satt; ihr trinket und werdet doch nicht trunken; ihr kleidet euch und konnet euch doch nicht erwarmen; und welcher Geld verdienet, der legt, es in einen lochrigen Beutel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht der HERR Zebaoth: Schauet, wie es euch gehet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Gehet hin auf das Gebirge und holet Holz und bauet das Haus; das soil mir angenehm sein und will meine Ehre erzeigen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Denn ihr wartet wohl auf viel, und siehe, es wird wenig; und ob ihr\'s schon heimbringet, so zerstaube ich\'s doch. Warum das? spricht der HERR Zebaoth. Darum, daß mein Haus so wüst stehet, und ein jeglicher eilet auf sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Darum hat der Himmel über euch den Tau verhalten und das Erdreich sein Gewachs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Und ich habe die Dürre gerufen, beide, über Land und Berge, über Korn, Most, 01 und über alles, was aus der Erde kommt, auch über Leute und Vieh und über alle Arbeit der Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Da gehorchte Serubabel, der Sohn Sealthiels, und Josua, der Sohn Jozadaks, der Hohepriester und alle übrigen des Volks solcher Stimme des HERRN, ihres Gottes, und den Worten des Propheten Haggai, wie ihn der HERR, ihr Gott, gesandt hatte; und das Volk furchtete sich vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Da sprach Haggai, der Engel des HERRN, der die Botschaft des HERRN hatte an das Volk: Ich bin mit euch, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Und der HERR erweckte den Geist Serubabels, des Sohns Sealthiels, des Fursten Judas, und den Geist Josuas, des Sohns Jozadaks, des Hohenpriesters, und den Geist des ganzen übrigen Volks, daß sie kamen und arbeiteten am Hause des HERRN Zebaoth, ihres Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Am vierundzwanzigsten Tage des sechsten Monden, im andern Jahrdes Konigs Darius,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'am einundzwanzigsten Tage des siebenten Monden, geschah des HERRN Wort durch den Propheten Haggai und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Sage zu Serubabel, dem Sohn Sealthiels, dem Fursten Judas, und zu Josua, dem Sohn Jozadaks, dem Hohenpriester, und zum ubrigen Volk und sprich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Wer ist unter euch uberblieben, der dies Haus in seiner vorigen Herrlichkeit gesehen hat? Und wie sehet ihr\'s nun an? Ist\'s nicht also, es dunket euch nichts sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Und nun, Serubabel, sei getrost, spricht der HERR; sei getrost, Josua, du Sohn Jozadaks, du Hoherpriester; sei getrost, alles Volk im Lande, spricht der HERR, und arbeitet! Denn ich bin mit euch, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Nach dem Wort, da ich mit euch einen Bund machte, da ihr aus Agypten zoget, soli mein Geist unter euch bleiben. Furchtet euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Denn so spricht der HERR Zebaoth: Es ist noch ein Kleines dahin, daß ich Himmel und Erde und das Meer und Trockene bewegen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Ja, alle Heiden will ich bewegen. Da soli dann kommen aller Heiden Trost. Und ich will dies Haus voll Herrlichkeit machen, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Denn mein ist beides, Silber und Gold, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Es soil die Herrlichkeit dieses letzten Hauses grdfter weiden, denn des ersten gewesen ist, spricht der HERR Zebaoth; und ich will Frieden geben an diesem Ort, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Am vierundzwanzigsten Tage des neunten Monden, im andern Jahr Darius, geschah des HERRN Wortzu dem Propheten Haggai und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'So spricht der HERR Zebaoth: Frage die Priester urn das Gesetz und sprich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Wenn jemand heilig Fleisch truge in seines Kleides Geren und ruhrete danach an mit seinem Geren Brot, Gemuse, Wein, 01, Oder was es fur Speise ware, wurde es auch heilig? Und die Priester antworteten und sprachen: Nein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Haggai sprach: Wo aber ein Unreiner von einem beruhrten Aas dieser eines anruhrete, wurde es auch unrein? Die Priester antworteten und sprachen: Es wurde unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Da antwortete Haggai und sprach: Eben also sind dies Volk und diese Leute vor mir auch, spricht der HERR; und all ihrer Hande Werk, und was sie opfern, ist unrein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Und nun schauet, wie es euch gegangen ist von diesem Tage an und zuvor, ehe denn ein Stein auf den andern gelegt ward am Tempel des HERRN:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'daß, wenn einerzum Kornhaufen kam, der zwanzig Maft haben sollte, so waren kaum zehn da; kam er zur Kelter und meinete, funfzig Eimer zu schdpfen, so waren kaum zwanzig da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Denn ich plagte euch mit Durre, Brandkorn und Hagel in all eurer Arbeit; noch kehretet ihr euch nicht zu mir, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'So schauet nun darauf, von diesem Tage an und zuvor, namlich von dem vierundzwanzigsten Tage des neunten Monden bis an den Tag, da der Tempel des HERRN gegrundet ist, schauet darauf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Denn der Same liegt noch in der Scheuer und tragt noch nichts, weder Weinstdcke, Feigenbaume, Granatbaume noch Olbaume; aber von diesem Tage an will ich Segen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Und des HERRN Wort geschah zum andernmal zu Haggai, am vierundzwanzigsten Tage des Monden, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Sage Serubabel, dem Fursten Judas, und sprich: Ich will Himmel und Erde bewegen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'und will die Stuhle der Kdnigreiche umkehren und die machtigen Konigreiche der Heiden vertilgen und will beide, Wagen mit ihren Reitern, umkehren, daß beide, Roft und Mann, herunterfallen sollen, ein jeglicher durch des andern Schwert. Zur selbigen Zeit, spricht der HERR Zebaoth, will ich dich, Serubabel, du Sohn Sealthiels, meinen Knecht, nehmen, spricht der HERR, und will dich wie einen Petschaftsring halten; denn ich habe dich erwahlet, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Im achten Monden des andern Jahrs des Konigs Darius geschah dies Wort des HERRN zu Sacharja dem Sohn Berechjas, des Sohns Iddos, dem Propheten, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Der HERR ist zornig gewesen uber eure Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Und sprich zu ihnen: So spricht der HERR Zebaoth: Kehret euch zu mir, spricht der HERR Zebaoth, so will ich mich zu euch kehren, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Seid nicht wie eure Vater, welchen die vorigen Propheten predigten und sprachen: So spricht der HERR Zebaoth: Kehret euch von euren bosen Wegen und von eurem bosen Tun! Aber sie gehorchten nicht und achteten nicht auf mich, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Wo sind nun eure Vater und die Propheten? Leben sie auch noch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Ist\'s nicht also, daß meine Worte und meine Rechte, die ich durch meine Knechte, die Propheten, gebot, haben eure Vater getroffen, dafi sie sich haben müssen kehren und sagen: Gleichwie der HERR Zebaoth vorhatte, uns zu tun, danach wir gingen und taten, also hat er uns auch getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Im vierundzwanzigsten Tage des elften Monden, welcher ist der Mond Sebat, im andern Jahr (des Konigs) Darius, geschah das Wort des HERRN zu Sacharja, dem Sohn Berechjas, des Sohns Iddos, dem Propheten, und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ich sah bei der Nacht, und siehe, ein Mann saü auf einem roten Pferde und er hielt unter den Myrten in der Aue; und hinter ihm waren rote, braune und weifte Pferde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Und ich sprach: Mein Herr, wer sind diese? Und der Engel, der mit mir redete, sprach zu mir: Ich will dir zeigen, wer diese sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Und der Mann, der unter den Myrten hielt, antwortete und sprach: Diese sind, die der HERR ausgesandt hat, das Land durchzuziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Sie aber antworteten dem Engel des HERRN, der unter den Myrten hielt, und sprachen: Wir sind durchs Land gezogen; und siehe, alle Lander sitzen stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Da antwortete der Engel des HERRN und sprach: HERR Zebaoth, wie lange willst du denn dich nicht erbarmen uber Jerusalem und uber die Stadte Judas, uber welche du zornig bist gewesen diese siebenzig Jahre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Und der HERR antwortete dem Engel, der mit mir redete, freundliche Worte und trostliche Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Und der Engel, der mit mir redete, sprach zu mir: Predige und sprich: So spricht der HERR Zebaoth: Ich habe sehr geeifert uber Jerusalem und Zion;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'aber ich bin sehr zornig uber die stolzen Heiden; denn ich war nur ein wenig zornig, sie aber helfen zum Verderben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Darum so spricht der HERR: Ich will mich wieder zu Jerusalem kehren mit Barmherzigkeit, und mein Haus soli drinnen gebauet werden, spricht der HERR Zebaoth; dazu soil die Zimmerschnur in Jerusalem gezogen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Und predige weiter und sprich: So spricht der HERR Zebaoth: Es soli meinen Stadten wieder wohlgehen, und der HERR wird Zion wieder trosten und wird Jerusalem wieder erwahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Und ich hub meine Augen auf und sah, und siehe, da waren vier Horner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Und ich sprach zum Engel, der mit mir redete: Wer sind diese? Er sprach zu mir: Es sind die Horner, die Juda samt dem Israel und Jerusalem zerstreuet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Und der HERR zeigte mirviel Schmiede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Da sprach ich: Was wollen die machen? Er sprach: Die Horner, die Juda so zerstreuet haben, daß niemand sein Haupt hat mogen aufheben, dieselbigen abzuschrecken, sind diese kommen, daß sie die Horner der Heiden abstolien, welche das Horn haben uber das Land Juda gehoben, dasselbige zu zerstreuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Und ich hub meine Augen auf und sah, und siehe, ein Mann hatte eine Melischnur in der Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Und ich sprach: Wo gehest du hin? Er aber sprach zu mir: Daü ich Jerusalem messe und sehe, wie lang und weit sie sein solle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Und siehe, der Engel, der mit mir redete, ging heraus. Und ein anderer Engel ging heraus ihm entgegen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'und sprach zu ihm: Lauf hin und sage diesem Knaben und sprich: Jerusalem wird bewohnet werden ohne Mauern vor grolier Menge der Menschen und Viehes, so drinnen sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'und ich will, spricht der HERR, eine feurige Mauer umher sein und will drinnen sein und will mich herrlich drinnen erzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Hui! hui! Fliehet aus dem Mitternachtlande! spricht der HERR; denn ich hab euch in die vier Winde unter dem Himmel zerstreuet, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Hui, Zion, die du wohnest bei der Tochter Babel, entrinne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Denn so spricht der HERR Zebaoth: Er hat mich gesandt nach der Ehre zu den Heiden, die euch beraubet haben; ihre Macht hat ein Ende. Wer euch antastet, der tastet seinen Augapfel an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Denn siehe, ich will meine Hand fiber sie weben, dafi sie sollen ein Raub werden denen, die ihnen gedienet haben, daß ihr sollt erfahren, daß mich der HERR Zebaoth gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 14, 'Freue dich und sei frohlich, du Tochter Zion! Denn siehe, ich komme und will bei dirwohnen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 15, 'Und sollen zu der Zeit viel Heiden zum HERRN getan werden und sollen mein Volk sein; und ich will bei dir wohnen, daß du sollst erfahren, dad mich der HERR Zebaoth zu dir gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 16, 'Und der HERR wird Juda erben fur sein Teil in dem heiligen Lande und wird Jerusalem wieder erwahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 17, 'Alles Fleisch sei stille vordem HERRN; denn er hat sich aufqemacht aus seiner heiliqen Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Und mirward gezeiget der Hohepriester Josua, stehend vor dem Engel des HERRN; und der Satan stund zu seiner Rechten, dad er ihm widerstunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Und der HERR sprach zu dem Satan: Der HERR schelte dich, du Satan; ja, der HERR schelte dich, der Jerusalem erwahlet hat! 1st dieser nicht ein Brand, der aus dem Feuer errettet ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Und Josua hatte unreine Kleider an und stund vor dem Engel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'welcher antwortete und sprach zu denen, die vor ihm stunden: Tut die unreinen Kleider von ihm! Und er sprach zu ihm: Siehe, ich habe deine Sunde von dir genommen und habe dich mit Feierkleidern angezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Und er sprach: Setzet einen reinen Hut auf sein Haupt! Und sie setzten einen reinen Hut auf sein Haupt und zogen ihm Kleider an, und der Engel des HERRN stund da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Und der Engel des HERRN bezeugete Josua und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'So spricht der HERR Zebaoth: Wirst du in meinen Wegen wandeln und meiner Hut warten, so sollst du regieren mein Haus und meine Hofe bewahren; und ich will dir geben von diesen, die hie stehen, daß sie dich geleiten sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Hore zu, Josua, du Hoherpriester, du und deine Freunde, die vor dir wohnen; denn sie sind eitel Wunder. Denn siehe, ich will meinen Knecht Zemah kommen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Denn siehe, auf dem einigen Stein, den ich vor Josua gelegt habe, sollen sieben Augen sein. Aber siehe, ich will ihn aushauen, spricht der HERR Zebaoth, und will die Sunde desselbigen Landes wegnehmen auf einen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Zu derselbigen Zeit, spricht der HERR Zebaoth, wird einer den andern laden unter den Weinstock und unter den Feigenbaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Und der Engel, der mit mir redete, kam wieder und weckte mich auf, wie einer vom Schlaf erwecket wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'und sprach zu mir: Was siehest du? Ich aber sprach: Ich sehe; und siehe, da stund ein Leuchter ganz gulden mit einer Schale oben darauf, daran sieben Lampen waren und je sieben Kellen an einer Lampe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'und zween Olbaume dabei, einen zur Rechten der Schale, den andern zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Und ich antwortete und sprach zu dem Engel, der mit mir redete: Mein Herr, was ist das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Und der Engel, der mit mir redete, antwortete und sprach zu mir: Weifit du nicht, was das ist? Ich aber sprach: Nein, mein Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Und er antwortete und sprach zu mir: Das ist das Wort des HERRN von Serubabel: Es soil nicht durch Heer Oder Kraft, sondern durch meinen Geist geschehen, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Wer bist du, du grofier Berg, der doch vor Serubabel eine Ebene sein muft? Und er soli aufführen den ersten Stein, dafi man rufen wird: Gluck zu, Gluck zu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Und es geschah zu mir das Wort des HERRN und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Die Hande Serubabels haben dies Haus gegrundet, seine Hande sollen\'s auch vollenden, daß ihr erfahret, daß mich der HERR zu euch gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Denn wer ist, der diese geringen Tage verachte, darin man doch sich wird freuen und sehen das zinnerne Mali in Serubabels Hand, mit den Sieben, welche sind des HERRN Augen, die das ganze Land durchziehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Und ich antwortete und sprach zu ihm: Was sind die zween Olbaume zur Rechten und zur Linken des Leuchters?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Und ich antwortete zum andernmal und sprach zu ihm: Was sind die zween Zweige der Olbaume, welche stehen bei den zwo guldenen Schneuzen des guldenen Leuchters, damit man abbricht oben von dem guldenen Leuchter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Und er sprach zu mir: Weiftt du nicht, was die sind? Ich aber sprach: Nein, mein Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Und er sprach: Es sind diezwei Olkinder, welche stehen bei dem Herrscher des ganzen Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Und ich hub meine Augen abermal auf und sah, und siehe, es war ein fliegender Brief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Und er sprach zu mir: Was siehest du? Ich aber sprach: Ich sehe einen fliegenden Brief, der ist zwanzig Ellen lang und zehn Ellen breit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Und er sprach zu mir: Das ist der Fluch, welcher ausgehet uber das ganze Land; denn alle Diebe werden nach diesem Briefe fromm gesprochen, und alle Meineidigen werden nach diesem Briefe fromm gesprochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Aber ich will\'s hervorbringen, spricht der HERR Zebaoth, daß es, soil kommen uber das Haus des Diebes und uber das Haus derer, die bei meinem Namen falschlich schwdren; und soil bleiben in ihrem Hause und soil\'s verzehren samt seinem Holz und Steinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Und der Engel, der mit mir redete, ging heraus und sprach zu mir: Hebe deine Augen auf und siehe, was gehet da heraus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Und ich sprach: Was ist\'s? Er aber sprach: Ein Epha gehet heraus, und sprach: Das ist ihre Gestalt im ganzen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Und siehe, es schwebte ein Zentner Blei; und da war ein Weib, das salt, im Epha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Er aber sprach: Das ist die gottlose Lehre. Und er warf sie in den Epha und warf den Klumpen Blei oben aufs Loch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Und ich hub meine Augen auf und sah, und siehe, zwei Weiber gingen heraus und hatten Flugel, die der Wind trieb; es waren aber Flugel wie Storchflugel, und die fuhreten den Epha zwischen Erde und Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Und ich sprach zum Engel, der mit mir redete: Wo führen die den Epha hin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Er aber sprach zu mir: Dali ihm ein Haus gebauet werde im Lande Sinear und bereitet und daselbst gesetzt werde auf seinen Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Und ich hub meine Augen abermal auf und sah, und siehe, da waren vier Wagen, die gingen zwischen zween Bergen hervor; dieselbigen Berge aber waren ehern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Am ersten Wagen waren rote Rosse; am andern Wagen waren schwarze Rosse;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'am dritten Wagen waren weilie Rosse; am vierten Wagen waren scheckige starke Rosse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Und ich antwortete und sprach zum Engel, der mit mir redete: Mein Herr, wer sind diese?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Der Engel antwortete und sprach zu mir: Es sind die vier Winde unter dem Himmel, die hervorkommen, daß sie treten vor den Herrscher aller Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'An dem die schwarzen Rosse waren, die gingen gegen Mitternacht, und die weilien gingen ihnen nach; aber die scheckigen gingen gegen Mittag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Die Starken gingen und zogen urn, daß sie alle Lande durchzogen. Und er sprach: Gehet hin und ziehet durchs Land! Und sie zogen durchs Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Und er rief mich und redete mit mir und sprach: Siehe, die gegen Mitternacht ziehen, machen meinen Geist ruhen im Lande gegen Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Nimm von den Gefangenen, namlich von Heldai und von Tobia und von Jedaja, und komm du desselbigen Tages und gehe in Josia, des Sohns Zephanjas, Haus, welche von Babel kommen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Nimm aber Silber und Gold und mache Kronen und setze sie auf das Haupt Josuas, des Hohenpriesters, des Sohns Jozadaks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Und sprich zu ihm: So spricht der HERR Zebaoth: Siehe, es ist ein Mann, der heiftt Zemah; denn unter ihm wird\'s wachsen; und er wird bauen des HERRN Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja, den Tempel des HERRN wird er bauen und wird den Schmuck tragen und wird sitzen und herrschen auf seinem Thron, wird auch Priester sein auf seinem Thron; und wird Friede sein zwischen den beiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Und die Kronen sollen dem Helem, Tobia, Jedaja und Hen, dem Sohne Zephanjas, zum Gedachtnis sein im Tempel des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Und werden kommen von feme, die am Tempel des HERRN bauen werden. Da werdet ihr erfahren, daß mich der HERR Zebaoth zu euch gesandt hat. Und das soli geschehen, so ihr gehorchen werdet der Stimme des HERRN, eures Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Und es geschah im vierten Jahr des Konigs Darius, daß des HERRN Wort geschah zu Sacharja, am vierten Tage des neunten Monden, welcher heiftt Chisleu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'da Sarezer und Regem-Melech samt ihren Leuten sandten in das Haus Gottes, zu bitten vor dem HERRN,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'und lieften sagen den Priestern, die da waren urn das Haus des HERRN Zebaoth, und zu den Propheten: Muft ich auch noch weinen im fünften Monden und mich enthalten, wie ich solches getan habe nun etliche Jahre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Und des HERRN Zebaoth Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Sage allem Volk im Lande und den Priestern und sprich: Da ihrfastetet und Leid truget im funften und siebenten Monden diese siebenzig Jahre lang, habt ihr mir so gefastet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Oder da ihr aftet und tranket, habt ihr nicht fur euch selbst gegessen und getrunken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ist\'s nicht das, welches der HERR predigen lieft durch die vorigen Propheten, da Jerusalem bewohnet war und hatte die Fuile samt ihren Stadten umher, und Leute wohneten beide gegen Mittag und in Grunden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Und des HERRN Wort geschah zu Sacharja und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'So spricht der HERR Zebaoth: Richtet recht, und ein jeglicher beweise an seinem Bruder Güte und Barmherzigkeit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'und tut nicht Unrecht den Witwen, Waisen, Fremdlingen und Armen; und denke keiner wider seinen Bruder etwas Arges in seinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Aber sie wollten nicht aufmerken und kehreten mir den Rücken zu und verstockten ihre Ohren, daß sie nicht horeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'und stelleten ihre Herzen wie einen Demant, daß sie nicht horeten das Gesetz und Worte, welche der HERR Zebaoth sandte in seinem Geiste durch die vorigen Propheten, daher so grofter Zorn vom HERRN Zebaoth kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Und ist also ergangen: Gleichwie geprediget ward, und sie nicht horeten, so wollt ich auch nicht horen, da sie riefen, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Also hab ich sie zerstreuet unter alle Heiden, die sie nicht kennen, und ist das Land hinter ihnen wust geblieben, daß niemand drinnen wandelt noch wohnet, und ist das edle Land zur Wustung gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Und des HERRN Wort geschah zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'So spricht der HERR Zebaoth: Ich habe uber Zion fast sehr geeifert und habe in groliem Zorn uber sie geeifert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So spricht der HERR: Ich kehre mich wieder zu Zion und will zu Jerusalem wohnen, daß Jerusalem soil eine Stadt der Wahrheit heilien und der Berg des HERRN Zebaoth ein Berg der Heiligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So spricht der HERR Zebaoth: Es sollen noch furder wohnen in den Gassen zu Jerusalem alte Manner und Weiber, und die an Stecken gehen vor groliem Alter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Und der Stadt Gassen sollen sein voll Knablein und Magdlein, die auf ihren Gassen spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So spricht der HERR Zebaoth: Dunket sie solches unmoglich sein vor den Augen dieses ubrigen Volks zu dieser Zeit? Sollt es darum auch unmoglich sein vor meinen Augen? spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So spricht der HERR Zebaoth: Siehe, ich will mein Volk erlosen vom Lande gegen Aufgang und vom Lande gegen Niedergang der Sonne');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'und will sie herzubringen, daß sie zu Jerusalem wohnen; und sie sollen mein Volk sein, und ich will ihr Gott sein in Wahrheit und Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So spricht der HERR Zebaoth: Starket eure Hande die ihr horet diese Worte zu dieser Zeit durch der Propheten Mund, des Tages, da der Grund gelegt ist an des HERRN Zebaoth Hause, dafi der Tempel gebauet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Denn vor diesen Tagen war der Menschen Arbeit vergebens, und der Tiere Arbeit war nichts, und war kein Friede vor Trubsal denen, die aus- und einzogen, sondern ich lieli alle Menschen gehen, einen jeglichen wider seinen Nachsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Aber nun will ich nicht, wie in den vorigen Tagen, mit den ubrigen dieses Volks fahren, spricht der HERR Zebaoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'sondern sie sollen Samen des Friedens sein. Der Weinstock soil seine Frucht geben und das Land sein Gewachs geben, und der Himmel soil seinen Tau geben; und ich will die ubrigen dieses Volks solches alles besitzen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Und soli geschehen, wie ihr vom Hause Juda und vom Hause Israel seid ein Fluch gewesen unter den Heiden, so will ich euch erlosen, daß ihr sollt ein Segen sein. Furchtet euch nur nicht und starket eure Handel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'So spricht der HERR Zebaoth: Gleichwie ich gedachte euch zu plagen, da mich eure Vater erzürneten, spricht der HERR Zebaoth, und reuete mich nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'also gedenke ich nun wiederum in diesen Tagen wohlzutun Jerusalem und dem Hause Juda. Furchtet euch nur nichts!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Das ist\'s aber, das ihr tun sollt: Rede einer mit dem andern Wahrheit und richtet recht und schaffet Frieden in euren Toren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'und denke keiner kein Arges in seinem Herzen wider seinen Nachsten und liebet nicht falsche Eide; denn solches alles hasse ich, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Und es geschah des HERRN Zebaoth Wort zu mir und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'So spricht der HERR Zebaoth: Die Fasten des vierten, funften, siebenten und zehnten Monden sollen dem Hause Juda zur Freude und Wonne und zu frohlichen Jahrfesten werden. Allein liebet Wahrheit und Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So spricht der HERR Zebaoth: Weiter werden noch kommen viel Volker und vieler Stadte Burger,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'und werden die Burger von einer Stadt gehen zur andern und sagen: Lafit uns gehen, zu bitten vor dem HERRN und zu suchen den HERRN Zebaoth; wir wollen auch mit euch gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Also werden viel Volker und die Heiden mit Haufen kommen, zu suchen den HERRN Zebaoth zu Jerusalem, zu bitten vor dem HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So spricht der HERR Zebaoth: Zu der Zeit werden zehn Manner aus allerlei Sprachen der Heiden einen judischen Mann bei dem Zipfel ergreifen und sagen: Wir wollen mit euch gehen; denn wir horen, daß Gott mit euch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Dies ist die Last, davon der HERR redet uber das Land Hadrach und uber Damaskus, auf welches es sich verlasset (denn der HERR schauet auf die Menschen und auf alle Stamme Israels),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'dazu auch uber Hamath, die mit ihrgrenzet, uber Tyrus und Zidon auch, die fast weise sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Denn Tyrus bauet feste und sammelt Silber wie Sand und Gold wie Kot auf der Gasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Aber siehe, der Herr wird sie verderben und wird ihre Macht, die sie auf dem Meer hat, schlagen, daß sie wird sein, als die mit Feuer verbrannt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Wenn das Asklon sehen wird, wird sie erschrecken, und Gasa wird sehr angst werden; dazu Ekron wird betrubt werden, wenn sie solches siehet. Denn es wird aus sein mit dem Kdnige zu Gasa, und zu Asklon wird man nicht wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Zu Asdod werden Fremde wohnen, und ich will der Philister Pracht ausrotten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Und ich will ihr Blut von ihrem Munde tun und ihre Greuel von ihren Zahnen, daß sie auch sollen unserm Gott uberbleiben, daß sie werden wie Fursten in Juda und Ekron wie die Jebusiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Und ich will selbst urn mein Haus das Lager sein, daß nicht dürfe Stehens und Hinundwiedergehens, dad nicht mehr über sie fahre der Treiber; denn ich hab es nun angesehen mit meinen Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Aber du, Tochter Zion, freue dich sehr, und du, Tochter Jerusalem, jauchze! Siehe, dein Konig kommt zu dir, ein Gerechter und ein Heifer, arm, und reitet auf einem Esel und auf einem jungen Fullen der Eselin!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Denn ich will die Wagen abtun von Ephraim und die Rosse von Jerusalem, und der Streitbogen soli zerbrochen werden. Denn erwird Frieden lehren unter den Heiden, und seine Herrschaft wird sein von einem Meer bis ans andere und vom Wasser bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Du lassest auch durchs Blut deines Bundes aus deine Gefangenen aus der Grube, da kein Wasser innen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'So kehreteuch nun zur Festung, ihr, die ihrauf Hoffnung gefangen liegt; denn auch heute will ich verkundigen und dir zwiefaltiges vergelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Denn ich habe mir Juda gespannet zum Bogen und Ephraim gerustet und will deine Kinder, Zion, erwecken über deine Kinder, Griechenland; und will dich stelien als ein Schwert der Riesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Und der HERR wird über ihnen erscheinen, und seine Pfeile werden ausfahren wie der Blitz. Und der Herr HERR wird die Posaune blasen und wird einhertreten als die Wetter vom Mittage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Der HERR Zebaoth wird sie schützen, dafi sie fressen und unter sich bringen mit Schleudersteinen, daß sie trinken und rumoren als vom Wein und voll werden als das Becken und wie die Ecken des Altars.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Und der HERR, ihr Gott, wird ihnen zu der Zeit helfen wie einer Herde seines Volks; denn es werden in seinem Lande heilige Steine aufgerichtet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Denn was haben sie Gutes vor andern und was haben sie Schones vor andern? Korn, das Jünglinge, und Most, der Jungfrauen zeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'So bittet nun vom HERRN Spatregen, so wird der HERR Gewolke machen und euch Regen genug geben zu allem Gewachs auf dem Felde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Denn die Gotzen reden eitel Mühe, und die Wahrsager sehen eitel Luge und reden vergebliche Traume, und ihr T rosten istnichts; darum gehen sie in der Irre wie eine Herde und sind verschmachtet, weil kein Hide da ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Mein Zorn ist ergrimmet über die Hirten, und ich will die Bocke heimsuchen; denn der HERR Zebaoth wird seine Herde heimsuchen, namlich das Haus Juda, und wird sie zurichten wie ein geschmückt Roß zum Streit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Die Ecken, Nagel, Streitbogen und Treiber sollen aile von ihnen wegkommen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'und sollen dennoch sein wie die Riesen, die den Kot auf der Gasse treten im Streit, und sollen streiten; denn der HERR wird mit ihnen sein, dalt> die Reiter zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Und ich will das Haus Juda starken und das Haus Joseph erretten und will sie wieder einsetzen, denn ich erbarme mich ihrer; und sollen sein, wie sie waren, da ich sie nicht verstoßen hatte. Denn ich, der HERR, ihr Gott, will sie erhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Und Ephraim soil sein wie ein Riese, und ihr Herz soil frohlich werden wie vom Wein; dazu ihre Kinder sollen\'s sehen und sich freuen, daß ihr Herz am HERRN frohlich sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Ich will zu ihnen blasen und sie sammeln, denn ich will sie erlosen; und sollen sich mehren, wie sie sich zuvor gemehret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Und ich will sie unter die Volker saen, dafi sie mein gedenken in fernen Landen; und sollen mit ihren Kindern leben und wiederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Denn ich will sie wiederbringen aus Agyptenland und will sie sammeln aus Assyrien und will sie ins Land Gilead und Libanon bringen, dafi man nicht Raum fur sie finden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Und erwird durchs Meer der Angst gehen und die Wellen im Meer schlagen, dafi aile Tiefen des Wassers vertrocknen werden. Da soil denn geniedriget werden die Pracht zu Assyrien, und das Zepter in Agypten soil aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Ich will sie starken in dem HERRN, daß sie sollen wandeln in seinem Namen, spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Tue deine Tur auf, Libanon, dafi das Feuer deine Zedern verzehre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Heulet, ihr Tannen; denn die Zedern sind gefallen, und das herrliche Gebau ist verstoret. Heulet, ihr Eichen Basans; denn der feste Wald ist umgehauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Man horet die Hirten heulen, denn ihr herrlich Gebau ist verstoret; man horet die jungen Lowen brüllen, denn die Pracht des Jordans ist verstoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'So spricht der HERR, mein Gott: Hüte der Schlachtschafe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Denn ihre Herren schlachten sie und halten\'s fur keine Sünde, verkaufen sie und sprechen: Gelobet sei der HERR, ich bin nun reich; und ihre Hirten schonen ihrer nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Darum will ich auch nicht mehr schonen der Einwohner im Lande, spricht der HERR. Und siehe, ich will die Leute lassen einen jeglichen in der Hand des andern und in der Hand seines Konigs, dafi sie das Land zerschlagen, und will sie nicht erretten von ihrer Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Und ich hutete der Schlachtschafe urn der elenden Schafe willen und nahm zu mir zween Stabe: einen hieü ich Sanft, den andern hiefi ich Weh; und hutete der Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Und ich vertilgete drei Hirten in einem Monden; denn ich mochte ihrer nicht, so wollten sie mein auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Und ich sprach: Ich will euer nicht huten. Was da stirbt, das sterbe; was verschmachtet, das verschmachte; und die Ubrigen fresse ein jegliches des andern Fleisch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Und ich nahm meinen Stab Sanft und zerbrach ihn, daß ich aufhube meinen Bund, den ich mit alien Volkern gemacht hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Und erward aufgehoben des Tages. Und die elenden Schafe, die auf mich hielten, merkten dabei, daß es des HERRN Wort ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Und ich sprach zu ihnen: Gefallt es euch, so bringet her, wieviel ich gelte; wo nicht, so laftt es anstehen. Und sie wogen dar, wieviel ich gait: dreiftig Silberlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Und der HERR sprach zu mir: Wirfs hin, daß es dem Topfer gegeben werde! Ei, eine treffliche Summa, der ich wert geachtet bin von ihnen! Und ich nahm die dreiftig Silberlinge und warf sie ins Haus des HERRN, daß dem Topfer gegeben wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Und ich zerbrach meinen andern Stab Weh, daß ich aufhube die Bruderschaft zwischen Juda und Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Und der HERR sprach zu mir: Nimm abermal zu dir Gerate eines torichten Hirten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Denn siehe, ich werde Hirten im Lande aufwecken, die das Verschmachtete nicht besuchen und das Zerschlagene nicht suchen und das Zerbrochene nicht heilen und das Gesunde nicht versorgen werden; aber das Fleisch der Fetten werden sie fressen und ihre Klauen zerreiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, '0 Gotzenhirten, die die Herde lassen! Das Schwert komme auf ihren Arm und auf ihr rechtes Auge! Ihr Arm müsse verdorren und ihr rechtes Auge dunkel werden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Dies ist die Last des Worts vom HERRN uber Israel, spricht der HERR, der den Himmel ausbreitete und die Erde grundete und den Odem des Menschen in ihm machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Siehe, ich will Jerusalem zum Taumelbecher zurichten alien Volkern, die umher sind; denn es wird auch Juda gelten, wenn Jerusalem belagert wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Dennoch zur selbigen Zeit will ich Jerusalem machen zum Laststein alien Volkern. Alle, die denselbigen wegheben wollen, sollen sich daran zerschneiden; denn es werden sich alle Heiden auf Erden wider sie versammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Zu der Zeit, spricht der HERR, will ich alle Rosse scheu und ihren Reitern bange machen; aber uber Jerusalem will ich meine Augen often haben und alle Rosse der Volker mit Blindheit plagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Und die Fursten in Juda werden sagen in ihrem Herzen: Es seien mir nur die Burger zu Jerusalem getrost in dem HERRN Zebaoth, ihrem Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Zu der Zeit will ich die Fursten Judas machen zum feurigen Ofen im Holz und zur Fackel im Stroh, daß sie verzehren, beide, zur Rechten und zur Linken, alie Volker urn und urn. Und Jerusalem soil auch furder bleiben an ihrem Ortzu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Und der HERR wird die Hütten Judas erretten wie vorzeiten, auf daß sich nicht hoch rühme das Haus David noch die Burger zu Jerusalem wider Juda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Zu der Zeit wird der HERR beschirmen die Burger zu Jerusalem; und wird geschehen, daß, welcher schwach sein wird unter ihnen zu der Zeit, wird sein wie David; und das Haus David wird sein wie Gottes Haus, wie des HERRN Engel vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Und zu der Zeit werde ich gedenken zu vertilgen alle Heiden, die wider Jerusalem gezogen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Aber uber das Haus David und fiber die Burger zu Jerusalem will ich ausgieften den Geist der Gnade und des Gebets; denn sie werden mich ansehen, welchen jene zerstochen haben, und werden ihn klagen, wie man klaget ein einiges Kind, und werden sich urn ihn betruben, wie man sich betrubet urn ein erstes Kind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Zu der Zeit wird grofte Klage sein zu Jerusalem, wie die war bei Hadad-Rimon im Felde Megiddo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Und das Land wird klagen, ein jeglich Geschlecht besonders: das Geschlecht des Hauses David besonders und ihre Weiber besonders, das Geschlecht des Hauses Nathan besonders und ihre Weiber besonders,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'das Geschlecht des Hauses Levi besonders und ihre Weiber besonders, das Geschlecht Simei besonders und ihre Weiber besonders;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'also alle ubrigen Geschlechter, ein jegliches besonders und ihre Weiber auch besonders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Zu der Zeit wird das Haus David und die Burger zu Jerusalem einen freien offenen Born haben wider die Sünde und Unreinigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Zu der Zeit, spricht der HERR Zebaoth, will ich der Gotzen Namen ausrotten aus dem Lande, daß man ihrer nicht mehr gedenken soil; dazu will ich auch die Propheten und unreinen Geisteraus dem Lande treiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'daß also gehen soil: wenn jemand weiter weissaget, sollen sein Vater und Mutter, die ihn gezeuget haben, zu ihm sagen: Du sollst nicht leben, denn du redestfalsch im Namen des HERRN; und werden also Vater und Mutter, die ihn gezeuget haben, ihn zerstechen, wenn er weissaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Denn es soli zu der Zeit geschehen, daß die Propheten mit Schanden bestehen mit ihren Gesichten, wenn sie davon weissagen; und sollen nicht mehr einen rauchen Mantel anziehen, damit sie betrügen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'sondern wird müssen sagen: Ich bin kein Prophet, sondern ein Ackermann, denn ich habe Menschen gedienet von meiner Jugend auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'So man aber sagen wird zu ihm: Was sind das fur Wunden in deinen Handen? wird er sagen: So bin ich geschlagen im Hause derer, die mich lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Schwert, mache dich auf uber meinen Hirten und uber den Mann, der mir der nachste ist! spricht der HERR Zebaoth. Schlage den Hirten, so wird die Herde sich zerstreuen, so will ich meine Hand kehren zu den Kleinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Und soil geschehen, in welchem Lande, spricht der HERR, zwei Teile sind; die sollen ausgerottet werden und untergehen, und das dritte Teil soil drinnen überbleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Und will dasselbige dritte Teil durchs Feuer führen und lautern, wie man Silber lautert, und fegen, wie man Gold feget. Die werden dann meinen Namen anrufen, und ich will sie erhoren. Ich will sagen: Es ist mein Volk; und sie werden sagen: HERR, mein Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Siehe, es kommt dem HERRN die Zeit, daß man deinen Raub austeilen wird in dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Denn ich werde allerlei Heiden wider Jerusalem sammeln zum Streit. Und die Stadt wird gewonnen, die Hauser geplundert und die Weibergeschandet werden; und die Halfte der Stadt wird gefangen weggeführt werden, und das übrige Volk wird nicht aus der Stadt ausgerottet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Aber der HERR wird ausziehen und streiten wider dieselbigen Heiden, gleichwie erzu streiten pflegt zur Zeit des Streits.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Und seine Fülie werden stehen zu der Zeit auf dem Olberge, der vor Jerusalem liegt gegen Morgen. Und der Olberg wird sich mitten entzweispalten vom Aufgang bis zum Niedergang, sehrweit voneinander, daß sich eine Halfte des Berges gegen Mitternacht und die andere gegen Mittag geben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Und ihrwerdet fliehen vorsolchem Tal zwischen meinen Bergen, denn das Tal zwischen den Bergen wird nahe hinanreichen an Azal; und werdet fliehen, wie ihr vorzeiten flohet vor dem Erdbeben zur Zeit Usias, des Konigs Judas. Da wird denn kommen der HERR, mein Gott, und alle Heiligen mitdir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Zu der Zeit wird kein Licht sein, sondern Kalte und Frost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Und wird ein Tag sein, der dem HERRN bekannt ist, weder Tag noch Nacht. Und urn den Abend wird\'s licht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Zu der Zeit werden frische Wasser aus Jerusalem flielien, die Halfte gegen das Meer gegen Morgen und die andere Halfte gegen das aulierste Meer; und wird wahren beide, des Sommers und Winters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Und der HERR wird Konig sein uber alle Lande. Zu der Zeit wird der HERR nur einer sein und sein Name nur einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Und man wird gehen im ganzen Lande urn, wie auf einem Gefilde, von Gibea nach Rimon zu, gegen Mittag zu Jerusalem. Denn sie wird erhoben und bewohnet werden an ihrem Ort, vom Tor Benjamin bis an den Ort des ersten Tors, bis an das Ecktor, und vom Turm Hananeel bis an des Konigs Kelter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Und man wird drinnen wohnen, und wird kein Bann mehr sein; denn Jerusalem wird ganz sicher wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Und das wird die Plage sein, damit der HERR plagen wird alle Volker, so wider Jerusalem gestritten haben: Ihr Fleisch wird verwesen, also daß sie noch auf ihren Fulien stehen, und ihre Augen in den Lochern verwesen und ihre Zunge im Maul verwesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Zu der Zeit wird der HERR ein groli Getümmel unter ihnen anrichten, daß einer wird den andern bei der Hand fassen und seine Hand auf des andern Hand legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Denn auch Juda wird wider Jerusalem streiten, daß versammelt werden die Guter aller Heiden, die umher sind: Gold, Silber, Kleider uber die Malie viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Und da wird denn diese Plage gehen uber Rosse, Mauler, Kamele, Esel und allerlei Tiere, die in demselben Heer sind, wie jene geplagt sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Und alle ubrigen unter alien Heiden, die wider Jerusalem zogen, werden jahrlich heraufkommen, anzubeten den Konig, den HERRN Zebaoth, und zu halten das Laubhuttenfest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Welches Geschlecht aber auf Erden nicht heraufkommen wird gen Jerusalem, anzubeten den Konig, den HERRN Zebaoth, uber die wird\'s nicht regnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Und wo das Geschlecht der Agypter nicht heraufzoge und kame, so wird\'s uber sie auch nicht regnen. Das wird die Plage sein, damit der HERR plagen wird alle Heiden, die nicht heraufkommen, zu halten das Laubhuttenfest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Denn das wird eine Sünde sein der Agypter und ailer Heiden, die nicht heraufkommen, zu halten das Laubhuttenfest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Zu der Zeit wird die Rustung der Rosse dem HERRN heilig sein; und werden die Kessel im Hause des HERRN gleich sein wie die Becken vor dem Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Denn es werden alle Kessel, beide, in Jerusalem und Juda, dem HERRN Zebaoth heilig sein, also daß alle, die da opfern wollen, werden kommen und dieselbigen nehmen und drinnen kochen. Und wird kein Kanaaniter mehr sein im Hause des HERRN Zebaoth zu der Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Dies ist die Last, die der HERR redet wider Israel durch Maleachi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Ich hab euch lieb, spricht der HERR. So sprechet ihr: Womit hast du uns lieb? Ist nicht Esau Jakobs Bruder? spricht der HERR; noch hab ich Jakob lieb');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'und hasse Esau und habe sein Gebirge ode gemacht und sein Erbe den Drachen zur Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Und ob Edom sprechen würde: Wirsind verderbet, aber wir wollen das Wüste wieder erbauen, so spricht der HERR Zebaoth also: Werden sie bauen, so will ich abbrechen; und soil heilien die verdammte Grenze und ein Volk, über das, der HERR zurnet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Das sollen eure Augen sehen, und werdet sagen: Der HERR ist herrlich in den Grenzen Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ein Sohn soli seinen Vater ehren und ein Knecht seinen Herm. Bin ich nun Vater, wo ist meine Ehre? Bin ich Herr, wo furchtet man mich? spricht der HERR Zebaoth zu euch Priestern, die meinen Namen verachten. So sprechet ihr: Womit verachten wir deinen Namen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Damit, dafi ihr opfert auf meinem Altar unrein Brot. So sprechet ihr: Womit opfern wir dir Unreines? Damit, daß ihr saget: Des HERRN Tisch ist verachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Und wenn ihr ein Blindes opfert, so muß es nicht bose heitien; und wenn ihr ein Lahmes Oder Krankes opfert, so muß es auch nicht bose heilien. Bringe es deinem Fursten! Was gilt\'s, ob du ihm gefallen werdest, Oder ob er deine Person ansehen werde? spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'So bittet nun Gott, daß er uns gnadig sei! Denn solches ist geschehen von euch. Meinet ihr, er werde eure Person ansehen? spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Wer ist auch unter euch, dereine Tür zuschließe? Ihr zundet auf meinem Altar kein Feuer an umsonst. Ich habe kein Gefallen an euch, spricht der HERR Zebaoth, und das Speisopfer von euren Handen ist mir nicht angenehm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Aber vom Aufgang der Sonne bis zum Niedergang soil mein Name herrlich werden unter den Heiden, und an alien Orten soil meinem Namen gerauchert und ein rein Speisopfer geopfert werden; denn mein Name soil herrlich werden unter den Heiden, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ihr aber entheiliget ihn, damit daß ihr saget: Des HERRN Tisch ist unheilig, und sein Opfer ist verachtet samt seiner Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Und ihr sprechet: Siehe, es istnur Mühe! und schlaget es in den Wind spricht der HERR Zebaoth. Und ihr opfert, das geraubet, lahm und krank ist, und opfert dann Speisopfer her. Solite mir solches gefallen von eurer Hand? spricht der HERR.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Verflucht sei der Vorteilische, der in seiner Herde ein Mannlein hat, und wenn erein Gelubde tut, opfert er dem HERRN ein untuchtiges! Denn ich bin ein großer Konig, spricht der HERR Zebaoth, und mein Name ist schrecklich unter den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Und nun, ihr Priester, dies Gebot gilt euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Wo ihr\'s nicht horet noch zu Herzen nehmen werdet, daß ihr meinem Namen die Ehre gebet, spricht der HERR Zebaoth, so werde ich den Fluch unter euch schicken und euren Segen verfluchen, ja verfluchen werde ich ihn, weil ihr\'s nicht wollet zu Herzen nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Siehe, ich will schelten euch samt dem Samen und den Kot eurer Feiertage euch ins Angesicht werfen, und soli an euch kleben bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'So werdet ihr dann erfahren, daß ich solch Gebot zu euch gesandt habe, daß es mein Bund sein solite mit Levi, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Denn mein Bund war mit ihm zum Leben und Frieden; und ich gab ihm die Furcht, daß er mich furchtete und meinen Namen scheuete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Das Gesetz der Wahrheit war in seinem Munde, und ward kein Boses in seinen Lippen funden. Er wandelte vor mir friedsam und aufrichtig und bekehrete viele von Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Denn des Priesters Lippen sollen die Lehre bewahren, daß man aus seinem Munde das Gesetz suche; denn er ist ein Engel des HERRN Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ihr aber seid von dem Wege abgetreten und argert viele im Gesetz und habt den Bund Levis gebrochen, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Darum hab ich auch euch gemacht, daß ihr verachtet und unwert seid vor dem ganzen Volk, weil ihr meine Wege nicht haltet und sehet Personen an im Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Denn haben wir nicht alle einen Vater? Hat uns nicht ein Gott geschaffen? Warum verachten wir denn einer den andern und entheiligen den Bund, mit unsern Vatern gemacht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Denn Juda ist ein Verachter worden, und in Israel und zu Jerusalem geschehen Greuel. Denn Juda entheiliget die Heiligkeit des HERRN, die er lieb hat, und buhlet mit eines fremden Gottes Tochter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Aber der HERR wird den, so solches tut, ausrotten aus der Hutte Jakobs, beide, Meister und Schuler, samt dem, der dem HERRN Zebaoth Speisopfer bringet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Weiter tut ihr auch das, daß vor dem Altar des HERRN eitel Tranen und Weinen und Seufzen ist, daß ich nicht mehr mag das Speisopfer ansehen noch etwas Angenehmes von euren Handen empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Und so sprechet ihr: Warum das? Darum, daß der HERR zwischen dir und dem Weibe deiner Jugend gezeuget hat, die du verachtest, so sie doch deine Gesellin und ein Weib deines Bundes ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Also tat der Einige nicht und war doch eines großen Geistes. Was tat aber der Einige? Er suchte den Samen von Gott (verheifien). Darum so sehet euch vor vor eurem Geiste, und verachte keiner das Weib seiner Jugend!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Wer ihr aber gram ist, der lasse sie fahren, spricht der HERR, der Gott Israels, und gebe ihr eine Decke des Frevels von seinem Kleide, spricht der HERR Zebaoth. Darum so sehet euch vor vor eurem Geiste und verachtet sie nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Ihrmachetden HERRN unwillig durch eure Reden. So sprechet ihr: Womit machen wir ihn unwillig? Damit, dafi ihr sprechet: Wer Boses tut, der gefallt dem HERRN, und er hat Lust zu demselbigen; Oder: Wo ist der Gott, der da strafe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Siehe, ich will meinen Engel senden, der vor mir her den Weg bereiten soli. Und bald wird kommen zu seinem Tempel der HERR, den ihrsuchet, und der Engel des Bundes, des ihr begehret. Siehe, er kommt! spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Wer wird aber den Tag seiner Zukunft erleiden mogen, und wer wird bestehen, wenn erwird erscheinen? Denn er ist wie das Feuer eines Goldschmieds und wie die Seife der Wascher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Erwird sitzen und schmelzen und das Silber reinigen; erwird die Kinder Levi reinigen und lautern wie Gold und Silber. Dann werden sie dem HERRN Speisopfer bringen in Gerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'und wird dem HERRN wohlgefallen das Speisopfer Judas und Jerusalems, wie vorhin und vor langen Jahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Und ich will zu euch kommen und euch strafen und ein schnelier Zeuge sein wider die Zauberer, Ehebrecher und Meineidigen und wider die, so Gewalt und Unrecht tun den Tagelohnern, Witwen und Waisen und den Fremdling drucken und mich nicht fürchten, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Denn ich bin der HERR, der nicht lüget. Und es soil mit euch Kindern Jakobs nicht gar aus sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Ihr seid von eurer Vater Zeit an immerdar abgewichen von meinen Geboten und habt sie nicht gehalten: So bekehret euch nun zu mir, so will ich mich zu euch auch kehren, spricht der HERR Zebaoth. So sprechet ihr: Worin sollen wir uns bekehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Ist\'s recht, dafi ein Mensch Gott tauschet, wie ihr mich tauschet? So sprechet ihr: Womit tauschen wir dich? Am Zehnten und Hebopfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Darum seid ihr auch verflucht, daß euch alles unterden Handen zerrinnet; denn ihr tauschet mich allesamt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Bringet aber die Zehnten ganz in mein Kornhaus, auf dafi in meinem Hause Speise sei; und prufet mich hierin, spricht der HERR Zebaoth, ob ich euch nicht des Himmels Fenster auftun werde und Segen herabschutten die Fülle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Und ich will fur euch den Fresser schelten, daß er euch die Frucht auf dem Felde nicht verderben soil, und der Weinstock im Acker euch nicht unfruchtbar sei, spricht der HERR Zebaoth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'daß euch alle Heiden sollen selig preisen; denn ihr sollt ein wertes Land sein, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Ihr redet hart wider mich, spricht der HERR. So sprechet ihr: Was reden wir wider dich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Damit, daß ihr saget: Es ist umsonst, da(3> man Gott dienet, und: Was nutzt es, daß wir sein Gebot halten und hart Leben vor dem HERRN Zebaoth führen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Darum preisen wir die Verachter, denn die Gottlosen nehmen zu; sie versuchen Gott, und gehet ihnen alles wohl hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Aber die Gottesfurchtigen trosten sich untereinander also: Der HERR merket es und horet es, und ist vor ihm ein Denkzettel, geschrieben fur die, so den HERRN furchten und an seinen Namen gedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Sie sollen, spricht der HERR Zebaoth, des Tages, den ich machen will, mein Eigentum sein; und ich will ihrer schonen, wie ein Mann seines Sohns schonet, der ihm dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Und ihr sollt dagegen wiederum sehen, was fur ein Unterschied sei zwischen dem Gerechten und Gottlosen und zwischen dem, der Gott dienet, und dem, der ihm nicht dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 19, 'Denn siehe, es kommt ein Tag, der brennen soil wie ein Ofen; da werden alle Verachter und Gottlosen Stroh sein, und der künftige Tag wird sie anzünden, spricht der HERR Zebaoth, und wird ihnen weder Wurzel noch Zweig lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 20, 'Euch aber, die ihr meinen Namen furchtet, soil aufgehen die Sonne der Gerechtigkeit und Heil unter desselbigen Flugeln; und ihr sollt aus- und eingehen und zunehmen wie die Mastkalber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 21, 'Ihr werdet die Gottlosen zertreten; denn sie sollen Asche unter euren Fuften werden des Tages, den ich machen will, spricht der HERR Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 22, 'Gedenket des Gesetzes Moses, meines Knechts, das ich ihm befohlen habe auf dem Berge Horeb an das ganze Israel, samt den Geboten und Rechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 23, 'Siehe, ich will euch senden den Propheten Elia, ehe denn da komme der grofte und schreckliche Tag des HERRN.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 24, 'Der soil das Herz der Vater bekehren zu den Kindern und das Herz der Kinder zu ihren Vatern, daß ich nicht komme und das Erdreich mit dem Bann schlage. Das Neue Testament');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Dies ist das Buch von der Geburt Jesu Christi, der da ist ein Sohn Davids, des Sohnes Abrahams.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zeugete Isaak. Isaak zeugete Jakob. Jakob zeugete Juda und seine Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda zeugete Pharez und Saram von der Thamar. Pharez zeugete Hezron. Hezron zeugete Ram.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Ram zeugete Aminadab. Aminadab zeugete Nahasson. Nahasson zeugete Salma.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salma zeugete Boas von der Rahab. Boas zeugete Obed von der Ruth. Obed zeugete Jesse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jesse zeugete den Konig David. Der Konig David zeugete Salomo von dem Weibe des Uria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomo zeugete Roboam. Roboam zeugete Abia. Abia zeugete Assa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Assa zeugete Josaphat. Josaphat zeugete Joram. Joram zeugte Osia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Osia zeugete Jotham. Jotham zeugete Achas. Achas zeugete Ezechia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezechia zeugete Manasse. Manasse zeugete Amon. Amon zeugete Josia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josia zeugete Jechonia und seine Brüder um die Zeit der babylonischen Gefangenschaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Nach der babylonischen Gefangenschaft zeugete Jechonia Sealthiel. Sealthiel zeugete Zorobabel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel zeugete Abiud. Abiud zeugete Eliachim. Eliachim zeugete Asor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Asor zeugete Zadoch. Zadoch zeugete Achin. Achin zeugete Eliud.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud zeugete Eleasar. Eleasar zeugete Matthan. Matthan zeugete Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jakob zeugete Joseph, den Mann Marias, von welcher ist geboren Jesus, der da heiliet Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Alle Glieder von Abraham bis auf David sind vierzehn Glieder. Von David bis auf die babylonische Gefangenschaft sind vierzehn Glieder. Von der babylonischen Gefangenschaft bis auf Christum sind vierzehn Glieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Die Geburt Christi war aber also getan. Als Maria, seine Mutter, dem Joseph vertrauet war, ehe er sie heimholete, erfand sich\'s, daß sie schwanger war von dem Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Joseph aber, ihr Mann, warfromm und wollte sie nicht rügen, gedachte aber sie heimlich zu verlassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Indem er aber also gedachte, siehe, da erschien ihm ein Engel des Herm im Traum und sprach: Joseph, du Sohn Davids furchte dich nicht, Maria, dein Gemahl, zu dir zu nehmen; denn das in ihr geboren ist, das ist von dem Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Und sie wird einen Sohn gebaren, des Namen sollst du Jesus heilien; denn erwird sein Volk selig machen von ihren Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Das ist aber alles geschehen, auf daß erfullet würde, was der Herr durch den Propheten gesagt hat, der da spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Siehe, eine Jungfrau wird schwanger sein und einen Sohn gebaren, und sie werden seinen Namen Emanuel heilien, das ist verdolmetschet, Gott mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Da nun Joseph vom Schlaf erwachte, tat er, wie ihm des Herm Engel befohlen hatte, und nahm sein Gemahl zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Und erkannte sie nicht, bis sie ihren ersten Sohn gebar, und hieli seinen Namen Jesus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Da Jesus geboren war zu Bethlehem im judischen Lande, zur Zeit des Konigs Herodes; siehe, da kamen die Weisen vom Morgenland gen Jerusalem und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Wo ist der neugeborne Konig der Juden? Wir haben seinen Stern gesehen im Morgenland und sind kommen, ihn anzubeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Da das der Konig Herodes horete, erschrak er und mit ihm das ganze Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Und liefi versammeln alle Hohenpriester und Schriftgelehrten unter dem Volk und erforschete von ihnen, wo Christus sollte geboren werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Und sie sagten ihm: Zu Bethlehem im judischen Lande. Denn also stehet geschrieben durch den Propheten:.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Und du Bethlehem im judischen Lande bist mitnichten die kleinste unter den Fursten Judas; denn aus dir soil mir kommen der Herzog, der liber mein Volk Israel ein Herr sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Da berief Herodes die Weisen heimlich und erlernete mit Fleifi von ihnen, wann der Stern erschienen ware,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'und weisete sie gen Bethlehem und sprach: Ziehet hin und forschet fleilüg nach dem Kindlein; und wenn ihr\'s findet, so saget mir\'s wieder, daß ich auch komme und es anbete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Als sie nun den Konig gehort hatten, zogen sie hin. Und siehe, der Stern, den sie im Morgenland gesehen hatten, ging vor ihnen hin, bis daß er kam und stund oben liber, da das Kindlein war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Da sie den Stern sahen, wurden sie hocherfreut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'und gingen in das Haus und fanden das Kindlein mit Maria, seiner Mutter, und fielen nieder und beteten es an und taten ihre Schatze auf und schenkten ihm Gold, Weihrauch und Myrrhen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Und Gott befahl ihnen im Traum, daß sie sich nicht sollten wieder zu Herodes lenken. Und zogen durch einen andern Weg wieder in ihr Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Da sie aber hinweggezogen waren, siehe, da erschien der Engel des Herm dem Joseph im Traum und sprach: Stehe auf und nimm das Kindlein und seine Mutter zu dir und flieh nach Agyptenland und bleibe allda, bis ich dir sage; denn es ist vorhanden, daß Herodes das Kindlein suche, dasselbe umzubringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Und erstund auf und nahm das Kindlein und seine Mutter zu sich bei der Nacht und entwich nach Agyptenland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Und blieb allda bis nach dem Tod des Herodes, auf daß erfullet wurde, das der Herr durch den Propheten gesagt hat, der da spricht: Aus Agypten habe ich meinen Sohn gerufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Da Herodes nun sah, dafi ervon den Weisen betrogen war, ward er sehr zornig und schickte aus und liefi alle Kinder zu Bethlehem toten und an ihren ganzen Grenzen, die da zweijahrig und drunter waren, nach der Zeit, die er mit Fleili von den Weisen erlernet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Da ist erfullet, was gesagt ist von dem Propheten Jeremia, der da spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Auf dem Gebirge hat man ein Geschrei gehoret, viel Klagens, Weinens und Heulens; Rahel beweinete ihre Kinder und wollte sich nicht trosten lassen denn es war aus mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Da aber Herodes gestorben war, siehe, da erschien der Engel des Herrn Joseph im Traum in Agyptenland');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'und sprach:. Stehe auf und nimm das Kindlein und seine Mutter zu dir und zieh hin in das Land Israel; sie sind gestorben, die dem Kinde nach dem Leben stunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Und er stund auf und nahm das Kindlein und seine Mutter zu sich und kam in das Land Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Da er aber horete, daß Archelaus im judischen Lande Konig war anstatt seines Vaters Herodes, furchtete er sich, dahin zu kommen. Und im Traum empfing er Befehl von Gott und zog in die Oder des galilaischen Landes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'und kam und wohnete in der Stadt, die da heifit Nazareth, auf daß erfullet wurde, was da gesagt ist durch die Propheten: Ersoll Nazarenus heilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Zu der Zeit kam Johannes der Taufer und predigte in der Wuste des judischen Landes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'und sprach: Tut Bufie; das Himmelreich ist nahe herbeikommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Und er ist der, von dem der Prophet Jesaja gesagt hat und gesprochen: Es ist eine Stimme eines Predigers in der Wuste: Bereitet dem Herrn den Weg und machet richtig seine Steige!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Er aber, Johannes, hatte ein Kleid von Kamelhaaren und einen ledernen Gürtel urn seine Lenden; seine Speise aber war Heuschrecken und wilder Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Da ging zu ihm hinaus die Stadt Jerusalem und das ganze judische Land und alle Lander an dem Jordan');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'und liefien sich taufen von ihm im Jordan und bekannten ihre Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Da er nun viel Pharisaer und Sadduzaer sah zu seiner Taufe kommen, sprach erzu ihnen: Ihr Otterngezuchte, wer hat denn euch geweiset, dafi ihr dem kunftigen Zorn entrinnen werdet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Sehet zu, tut rechtschaffene Fruchte der Bulie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Denket nur nicht, daß ihr bei euch wollt sagen: Wir haben Abraham zum Vater. Ich sage euch: Gott vermag dem Abraham aus diesen Steinen Kinder zu erwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Es ist schon die Axt den Baumen an die Wurzel gelegt. Darum, welcher Baum nicht gute Fruchte bringet, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ich taufe euch mit Wasser zur Bulie; der aber nach mir kommt, ist starker denn ich, dem ich auch nicht genugsam bin, seine Schuhe zu tragen; der wird euch mit dem Heiligen Geist und mit Feuer taufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Und er hat seine Worfschaufel in der Hand; er wird seine Tenne fegen und den Weizen in seine Scheune sammeln; aber die Spreu wird er verbrennen mit ewigem Feuer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Zu der Zeit kam Jesus aus Galilaa an den Jordan zu Johannes, daß er sich von ihm taufen lielie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Aber Johannes wehrete ihm und sprach: Ich bedarf wohl, daß ich von dir getauft werde, und du kommest zu mir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jesus aber antwortete und sprach zu ihm: Lali jetzt also sein; also gebuhrt es uns, alle Gerechtigkeit zu erfullen. Da lieli er\'s ihm zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Und da Jesus getauft war, stieg er bald herauf aus dem Wasser; und siehe, da tat sich der Himmel auf uber ihm. Und Johannes sah den Geist Gottes gleich als eine Taube herabfahren und uber ihn kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Und siehe, eine Stimme vom Himmel herab sprach: Dies ist mein lieber Sohn, an welchem ich Wohlgefallen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Da ward Jesus vom Geist in die Wuste gefuhrt, auf daß er von dem Teufel versucht wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Und da er vierzig Tage und vierzig Nachte gefastet hatte, hungerte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Und der Versucher trat zu ihm und sprach: Bist du Gottes Sohn, so sprich, daß diese Steine Brot werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Und er antwortete und sprach: Es stehet geschrieben: Der Mensch lebet nicht vom Brot alleine, sondern von einem jeglichen Wort, das durch den Mund Gottes gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Da fuhrete ihn der Teufel mit sich in die heilige Stadt und stellete ihn auf die Zinne des Tempels');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'und sprach zu ihm: Bist du Gottes Sohn, so lali dich hinab; denn es stehet geschrieben: Er wird seinen Engeln uber dir Befehl tun, und sie werden dich auf den Handen tragen, auf daß du deinen Fuli nicht an einen Stein stoliest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Da sprach Jesus zu ihm: Wiederum stehet auch geschrieben: Du sollst Gott, deinen Herrn, nicht versuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Wiederum fuhrete ihn der Teufel mit sich auf einen sehr hohen Berg und zeigete ihm alle Reiche der Welt und ihre Herrlichkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'und sprach zu ihm: Das alles will ich dir geben, so du niederfallst und mich anbetest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Da sprach Jesus zu ihm: Heb\' dich weg von mir, Satan! Denn es stehet geschrieben: Du sollst anbeten Gott, deinen Herm, und ihm allein dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Da verlieli ihn der Teufel; und siehe, da traten die Engel zu ihm und dieneten ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Da nun Jesus horete, daß Johannes überantwortet war, zog er in das galilaische Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'und verlieli die Stadt Nazareth, kam und wohnete zu Kapernaum, die da liegt am Meer, an den Grenzen Zabulons und Nephthalims,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'auf daß erfullet wurde, was da gesagt istdurch den Propheten Jesaja, der da spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Das Land Zabulon und das Land Nephtalim am Wege des Meers, jenseit des Jordans, und das heidnische Galilaa,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'das Volk, das in Finsternis saü, hat ein groües Licht gesehen, und die da salien am Ort und Schatten des Todes, denen ist ein Licht aufgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Von der Zeit an fing Jesus an zu predigen und zu sagen: Tut Bulie; das Himmelreich ist nahe herbeikommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Als nun Jesus an dem Galilaischen Meer ging, sah erzwei Bruder, Simon, der da heilit Petrus, und Andreas, seinen Bruder, die warfen ihre Netze ins Meer; denn sie waren Fischer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Und er sprach zu ihnen: Folget mir nach; sich will euch zu Menschenfischern machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Bald verlielien sie ihre Netze und folgeten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Und da er von dannen furbaü ging, sah er zwei andere Bruder, Jakobus, den Sohn des Zebedaus, und Johannes, seinen Bruder, im Schiff, mit ihrem Vater Zebedaus, daß sie ihre Netze flickten; und er rief sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Bald verlielien sie das Schiff und ihren Vater und folgten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Und Jesus ging umher im ganzen galilaischen Lande, lehrete in ihren Schulen und predigte das Evangelium von dem Reich und heilete allerlei Seuche und Krankheit im Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Und sein Gerucht erscholl in das ganze Syrienland. Und sie brachten zu ihm allerlei Kranke, mit mancherlei Seuchen und Qual behaftet, die Besessenen die Mondsuchtigen und die Gichtbrüchigen; und er machte sie alle gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Und es folgete ihm nach viel Volks aus Galilaa, aus den zehn Stadten, von Jerusalem, aus dem judischen Lande und von jenseit des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Da er aber das Volk sah, ging er auf einen Berg und setzte sich, und seine Junger traten zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Und er tat seinen Mund auf, lehrete sie und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Selig sind, die da geistlich arm sind; denn das Himmelreich ist ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Selig sind, die da Leid tragen; denn sie sollen getrostet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Selig sind die Sanftmutigen; denn sie werden das Erdreich besitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Selig sind, die da hungert und durstet nach der Gerechtigkeit; denn sie sollen satt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Selig sind die Barmherzigen; denn sie werden Barmherzigkeit erlangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Selig sind, die reines Herzens sind; denn sie werden Gottschauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Selig sind die Friedfertigen; denn sie werden Gottes Kinder heilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Selig sind, die urn Gerechtigkeit willen verfolgt werden; denn das Himmelreich ist ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Selig seid ihr, wenn euch die Menschen urn meinetwillen schmahen und verfolgen und reden allerlei Ubles wider euch, so sie daran lugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Seid frohlich und getrost, es wird euch im Himmel wohl belohnt werden! Denn also haben sie verfolget die Propheten, die vor euch gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ihr seid das Salz der Erde. Wo nun das Salz dumm wird, womit soil man salzen? Es ist zu nichts hinfort nutze, denn daß man es hinausschutte und lasse es die Leute zertreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ihr seid das Licht der Welt. Es mag die Stadt, die auf einem Berge liegt, nicht verborgen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Man zündet auch nicht ein Licht an und setzt es unter einen Scheffel, sondern auf einen Leuchter, so leuchtet es denen alien, die im Hause sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Also lasset euer Licht leuchten vor den Leuten, daß sie eure guten Werke sehen und euren Vater im Himmel preisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ihr sollt nicht wahnen, daß ich kommen bin, das Gesetz Oder die Propheten aufzulosen. Ich bin nicht kommen aufzulosen, sondern zu erfullen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Denn ich sage euch: Wahrlich, bis daß Himmel und Erde vergehe, wird nicht vergehen der kleinste Buchstabe noch ein Tüttel vom Gesetz, bis daß es alles geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Wer nun eins von diesen kleinsten Geboten aufloset und lehret die Leute also, der wird der Kleinste heilien im Himmelreich; wer es aber tut und lehret, der wird groli heilien im Himmelreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Denn ich sage euch: Es sei denn eure Gerechtigkeit besser denn der Schriftgelehrten und Pharisaer, so werdet ihr nicht in das Himmelreich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ihr habt gehoret, daß zu den Alten gesagt ist: Du sollst nicht toten; wer aber totet, der soil des Gerichts schuldig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ich aber sage euch: Wer mit seinem Bruder zurnet, der ist des Gerichts schuldig; wer aber zu seinem Bruder sagt: Racha! der ist des Rats schuldig; wer aber sagt: Du Narr! der ist des hollischen Feuers schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Darum wenn du deine Gabe auf dem Altar opferst und wirst allda eindenken, daß dein Bruder etwas wider dich habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'so laft allda vor dem Altar deine Gabe und gehe zuvor hin und versohne dich mitdeinem Bruder und alsdann komm und opfere deine Gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Sei willfertig deinem Widersacher bald, dieweil du noch bei ihm auf dem Wege bist, auf dafi dich der Widersacher nicht dermaleinst uberantworte dem Richter, und der Richter uberantworte dich dem Diener, und werdest in den Kerker geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Ich sage dir: Wahrlich, du wirst nicht von dannen herauskommen, bis du auch den letzten Heller bezahlest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ihr habt gehoret, daß zu den Alten gesagt ist: Du sollst nicht ehebrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ich aber sage euch: Wer ein Weib ansiehet, ihrer zu begehren, der hat schon mit ihr die Ehe gebrochen in seinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Argert dich aber dein rechtes Auge; so reift es aus und wirfs von dir. Es ist dir besser, daß eins deiner Glieder verderbe, und nicht der ganze Leib in die Holle geworfen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Argert dich deine rechte Hand, so haue sie ab, und wirf sie von dir. Es ist dir besser, daß eins deiner Glieder verderbe, und nicht der ganze Leib in die Holle geworfen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Es ist auch gesagt: Wer sich von seinem Weibe scheidet, der soil ihrgeben einen Scheidebrief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ich aber sage euch: Wer sich von seinem Weibe scheidet (es sei denn urn Ehebruch), der macht, daß sie die Ehe bricht; und wer eine Abgeschiedene freiet, der bricht die Ehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Ihr habt weiter gehort, daß zu den Alten gesagt ist: Du sollst keinen falschen Eid tun und sollst Gott deinen Eid halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ich aber sage euch, daß ihr allerdinge nicht schworen sollt, weder bei dem Himmel, denn er ist Gottes Stuhl;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'noch bei der Erde, denn sie ist seiner Fuße Schemel; noch bei Jerusalem, denn sie isteines groften Konigs Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Auch sollst du nicht bei deinem Haupt schworen; denn du vermagst nicht ein einiges Haarweift Oder schwarz zu machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Eure Rede aber sei: Ja, ja; nein, nein; was daruber ist, das ist vom Ubel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ihr habt gehort, dafi da gesagt ist: Auge urn Auge, Zahn urn Zahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ich aber sage euch, daß ihr nicht widerstreben sollt dem Ubel, sondern so dirjemand einen Streich gibt auf deinen rechten Backen, dem biete den andern auch dar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Und so jemand mit dir rechten will und deinen Rock nehmen, dem laft auch den Mantel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Und so dich jemand notiget eine Meile, so gehe mit ihm zwo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Gib dem, der dich bittet, und wende dich nicht von dem, der dir abborgen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ihr habt gehort, daß gesagt ist: Du sollst deinen Nachsten lieben und deinen Feind hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ich aber sage euch: Liebet eure Feinde, segnet, die euch fluchen, tutwohl denen, die euch hassen, bittet fur die, so euch beleidigen und verfolgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'auf daß ihr Kinder seid eures Vaters im Himmel Denn er laftt seine Sonne aufgehen uber die Bosen und uber die Guten und lasset regnen uber Gerechte und Ungerechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Denn so ihr liebet, die euch lieben, was werdet ihr fur Lohn haben? Tun nicht dasselbe auch die Zollner?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Und so ihr euch nur zu euren Brudern freundlich tut, was tut ihr Sonderliches? Tun nicht die Zollner auch also?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Darum sollt ihr vollkommen sein, gleichwie euer Vater im Himmel vollkommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Habt acht auf eure Almosen, daß ihr die nicht gebet vor den Leuten, daß ihr von ihnen gesehen werdet; ihr habt anders keinen Lohn bei eurem Vater im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Wenn du nun Almosen gibst, sollst du nicht lassen vor dir posaunen, wie die Heuchler tun in den Schulen und auf den Gassen, auf daß sie von den Leuten gepreiset werden. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Wenn du aber Almosen gibst, so laft deine linke Hand nicht wissen, was die rechte tut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'auf daß dein Almosen verborgen, sei; und dein Vater, der in das Verborgene siehet, wird dir\'s vergelten offentlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Und wenn du betest, sollst du nicht sein wie die Heuchler, die da gerne stehen und beten in den Schulen und an den Ecken auf den Gassen, auf daß sie von den Leuten gesehen werden. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Wenn du aber betest, so gehe in dein Kammerlein und schliefte die Turzu und bete zu deinem Vater im Verborgenen; und dein Vater, der in das Verborgene siehet, wird dir\'s vergelten offentlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Und wenn ihr betet, sollt ihr nicht viel plappern wie die Heiden; denn sie meinen, sie werden erhoret, wenn sie viel Worte machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Darum sollt ihr euch ihnen nicht gleichen. Euer Vater weift, was ihr bedurfet, ehe denn ihr ihn bittet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Darum sollt ihr also beten: Unser Vater in dem Himmel! Dein Name werde geheiliget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Dein Reich komme. Dein Wille geschehe auf Erden wie im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Unser taglich Brot gib uns heute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Und vergib uns unsere Schulden, wie wir unsern Schuldigern vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Und fuhre uns nicht in Versuchung, sondern erlose uns von dem Ubel. Denn dein ist das Reich und die Kraft und die Herrlichkeit in Ewigkeit. Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Denn so ihr den Menschen ihre Fehle vergebet, so wird euch euer himmlischer Vater auch vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Wo ihr aber den Menschen ihre Fehle nicht vergebet, so wird euch euer Vater eure Fehle auch nicht vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Wenn ihr fastet, sollt ihr nicht sauer sehen wie die Heuchler; denn sie verstellen ihre Angesichte, auf daß sie vor den Leuten scheinen mit ihrem Fasten. Wahrlich, ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Wenn du aber fastest, so salbe dein Hauptund wasche dein Angesicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'auf dafi du nicht scheinest vor den Leuten mit deinem Fasten, sondern vordeinem Vater, welcher verborgen ist; und dein Vater, der in das Verborgene siehet, wird dir\'s Vergelten offentlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ihr sollt euch nicht Schatze sammeln auf Erden, da sie die Motten und der Rost fressen, und da die Diebe nach graben und stehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Sammelt euch aber Schatze im Himmel, da sie weder Motten noch Rost fressen, und da die Diebe nicht nach graben noch stehlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Denn wo euer Schatz ist, da ist auch euer Herz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Das Auge ist des Leibes Licht. Wenn dein Auge einfaltig ist, so wird dein ganzer Leib licht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Wenn aber dein Auge ein Schalk ist, so wird dein ganzer Leib finster sein. Wenn aber das Licht, das in dir ist, Finsternis ist, wie groß wird dann die Finsternis selber sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Niemand kann zweien Herren dienen. Entweder er wird einen hassen und den andern lieben, Oder wird einem anhangen und den andern verachten. Ihr konnt nicht Gott dienen und dem Mammon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Darum sage ich euch: Sorget nicht fur euer Leben, was ihr essen und trinken werdet, auch nicht fur euren Leib, was ihr anziehen werdet. Ist nicht das Leben mehr denn die Speise und der Leib mehr denn die Kleidung?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Sehet die Vogel unter dem Himmel an: sie saen nicht, sie ernten nicht, sie sammeln nicht in die Scheunen; und euer himmlischer Vater nahret sie doch. Seid ihr denn nicht viel mehr denn sie?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Wer ist unter euch, der seiner Lange eine Elle zusetzen moge, ob er gleich darum sorget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Und warum sorget ihr fur die Kleidung? Schauet die Lilien auf dem Felde, wie sie wachsen! Sie arbeiten nicht, auch spinnen sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ich sage euch, daß auch Salomo in aller seiner Herrlichkeit nicht bekleidet gewesen ist als derselbigen eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'So denn Gott das Gras auf dem Felde also kleidet, das doch heute stehet und morgen in den Ofen geworfen wird, sollt er das nicht viel mehr euch tun, o ihr Kleinglaubigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Darum sollt ihr nicht sorgen und sagen: Was werden wir essen, was werden wir trinken, womit werden wir uns kleiden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Nach solchem allem trachten die Heiden. Denn euer himmlischer Vater weiß, dafi ihr des alles bedurfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Trachtet am ersten nach dem Reich Gottes und nach seiner Gerechtigkeit, so wird euch solches alles zufallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Darum sorget nicht fur den andern Morgen; denn der morgende Tag wird fur das Seine sorgen. Es ist genug, dafi ein jeglicher Tag seine eigene Plage habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Richtet nicht, auf daß ihr nicht gerichtet werdet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Denn mit welcherlei Gerichte ihr richtet, werdet ihr gerichtet werden, und mit welcherlei Mall ihr messet, wird euch gemessen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Was siehest du aber den Splitter in deines Bruders Auge und wirst nicht gewahr des Balkens in deinem Auge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Oder wie darfst du sagen zu deinem Bruder: Halt, ich will dir den Splitter aus deinem Auge ziehen! und siehe, ein Balken ist in deinem Auge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Du Heuchler, zieh am ersten den Balken aus deinem Auge; danach besiehe, wie du den Splitter aus deines Bruders Auge ziehest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ihr sollt das Heiligtum nicht den Hunden geben und eure Perlen sollt ihr nicht vor die Saue werfen, auf daß sie dieselbigen nicht zertreten mit ihren Fülien und sich wenden und euch zerreifien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bittet, so wird euch gegeben; suchet, so werdet ihr finden; klopfet an, so wird euch aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Denn wer da bittet, der empfangt, und wer da suchet, der findet, und wer da anklopft, dem wird aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Welcher ist unter euch Menschen, so ihn sein Sohn bittet urns Brot, der ihm einen Stein biete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Oder so er ihn bittet urn einen Fisch, der ihm eine Schlange biete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'So denn ihr, die ihr doch arg seid, konnt dennoch euren Kindern gute Gaben geben, wieviel mehr wird euer Vater im Himmel Gutes geben denen, die ihn bitten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alles nun, was ihr wollet, daß euch die Leute tun sollen, das tut ihr ihnen; das ist das Gesetz und die Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Gehet ein durch die enge Pforte! Denn die Pforte ist weit, und der Weg ist breit, der zur Verdammnis abfuhret; und ihrersind viel, die daraufwandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Und die Pforte ist enge, und der Weg istschmal, der zum Leben führet; und wenig ist ihrer, die ihn finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Sehet euch vor vor den falschen Propheten, die in Schafskleidern zu euch kommen! Inwendig aber sind sie reißende Wolfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'An ihren Fruchten sollt ihr sie erkennen. Kann man auch Trauben lesen von den Dornen Oder Feigen von den Disteln?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Also ein jeglicher guter Baum bringet gute Fruchte; aber ein fauler Baum bringet arge Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ein guter Baum kann nicht arge Fruchte bringen, und ein fauler Baum kann nicht gute Fruchte bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Ein jeglicher Baum, der nicht gute Fruchte bringet, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Darum an ihren Fruchten sollt ihrsie erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Es werden nicht alle, die zu mir sagen: Herr, Herr! in das Himmelreich kommen, sondern die den Willen tun meines Vaters im Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Es werden viele zu mir sagen an jenem Tage: Herr, Herr, haben wir nicht in deinem Namen geweissaget, haben wir nicht in deinem Namen Teufel ausgetrieben, haben wir nicht in deinem Namen viel Taten getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Dann werde ich ihnen bekennen: Ich habe euch noch nie erkannt; weichet alle von mir, ihr Ubeltater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Darum wer diese meine Rede horet und tut sie, den vergleiche ich einem klugen Mann, der sein Haus auf einen Felsen bauete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Da nun ein Platzregen fiel, und ein Gewasser kam, und weheten die Winde und stielien an das Haus, fiel es doch nicht; denn es war auf einen Felsen gegrundet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Und wer diese meine Rede horet und tut sie nicht, der ist einem torichten Mann gleich, der sein Haus auf den Sand bauete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Da nun ein Platzregen fiel, und kam ein Gewasser, und weheten die Winde und stiefien an das Haus, da fiel es und tat einen grolien Fall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Und es begab sich, da Jesus diese Rede vollendet hatte, entsetzte sich das Volk uber seine Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Denn er predigte gewaltig und nicht wie die Schriftgelehrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Da er aber vom Berge herabging, folgete ihm viel Volks nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Und siehe, ein Aussatziger kam und betete ihn an und sprach: Herr, so du willst, kannst du mich wohl reinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Und Jesus streckte seine Hand aus, ruhrete ihn an und sprach: Ich will\'s tun; sei gereiniget! Und alsbald ward er von seinem Aussatz rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Und Jesus sprach zu ihm: Siehe zu, sag\'s niemand, sondern gehe hin und zeige dich dem Priester und opfere die Gabe, die Mose befohlen hat, zu einem Zeugnis uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Da aber Jesus einging zu Kapernaum, trat ein Hauptmann zu ihm, der bat ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'und sprach: Herr, mein Knecht liegtzu Hause und ist gichtbruchig und hat grolie Qual.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jesus sprach zu ihm: Ich will kommen und ihn gesund machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Der Hauptmann antwortete und sprach: Herr, ich bin nicht wert, daß du unter mein Dach gehest, sondern sprich nur ein Wort, so wird mein Knecht gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Denn ich bin ein Mensch, dazu der Obrigkeit untertan, und habe unter mir Kriegsknechte; noch wenn ich sage zu einem: Gehe hin! so gehet er, und zum andern: Komm her! so kommt er, und zu meinem Knecht: Tue das! so tut er\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Da das Jesus horete, verwunderte er sich und sprach zu denen, die ihm nachfolgeten: Wahrlich, ich sage euch, solchen Glauben habe ich in Israel nicht funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Aber ich sage euch: Viele werden kommen vom Morgen und vom Abend und mit Abraham und Isaak und Jakob im Himmelreich sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Aber die Kinder des Reichs werden ausgestolien in die aulierste Finsternis hinaus, da wird sein Heulen und Zahneklappen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Und Jesus sprach zu dem Hauptmann: Gehe hin; dirgeschehe, wie du geglaubt hast! Und sein Knecht ward gesund zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Und Jesus kam in des Petrus Haus und sah, daß seine Schwieger lag und hatte das Fieber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Da griff erihre Hand an, und das Fieber verliefi sie. Und sie stund auf und dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Am Abend aber brachten sie viel Besessene zu ihm; und er trieb die Geister aus mit Worten und machte allerlei Kranke gesund,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'auf daß erfüllet wurde, was gesagt ist durch den Propheten Jesaja, der da spricht: Er hat unsere Schwachheit auf sich, genommen und unsere Seuche hat ergetragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Und da Jesus viel Volks urn sich sah, hiefi er hinuber jenseit des Meeres fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Und es trat zu ihm ein Schriftgelehrter, der sprach zu ihm: Meister, ich will dir folgen, wo du hingehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jesus sagte zu ihm: Die Fuchse haben Gruben, und die Vogel unter dem Himmel haben Nester; aber des Menschen Sohn hat nicht, da er sein Haupt hinlege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Und ein anderer unter seinen Jungern sprach zu ihm: Herr, erlaube mir, daß ich hingehe und zuvor meinen Vater begrabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Aber Jesus sprach zu ihm: Folge du mir und lali die Toten ihre Toten begraben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Und er trat in das Schiff, und seine Jünger folgeten ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Und siehe, da erhub sich ein groli Ungestüm im Meer, also daß auch das Schifflein mit Wellen bedeckt ward; und er schüef.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Und die Junger traten zu ihm und weckten ihn auf und sprachen: Herr, hilf uns, wir verderben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Da sagte erzu ihnen: Ihr Kleinglaubigen, warum seid ihr so furchtsam? Und stund auf und bedrauete den Wind und das Meer; da ward es ganz stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Die Menschen aber verwunderten sich und sprachen: Was ist das fur ein Mann, daß ihm Wind und Meer gehorsam ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Und er kam jenseit des Meeres in die Gegend der Gergesener. Da liefen ihm entgegen zwei Besessene, die kamen aus den Totengrabern und waren sehr grimmig, also daü niemand dieselbige Stralie wandeln konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Und siehe, sie schrieen und sprachen: Ach Jesu, du Sohn Gottes, was haben wir mit dir zu tun? Bist du herkommen, uns zu qualen, ehe denn es Zeit ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Es war aber feme von ihnen eine grofie Herde Saue an der Weide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Da baten ihn die Teufel und sprachen: Willst du uns austreiben, so erlaube uns, in die Herde Saue zu fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Und er sprach: Fahret hin! Da fuhren sie aus und fuhren in die Herde Saue. Und siehe, die ganze Herde Saue sturzete sich mit einem Sturm ins Meer und ersoffen im Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Und die Hirten flohen und gingen hin in die Stadt und sagten das alles, und wie es mit den Besessenen ergangen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Und siehe, da ging die ganze Stadt heraus Jesu entgegen. Und da sie ihn sahen, baten sie ihn, daß er von ihrer Grenze weichen wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Da trat er in das Schiff und fuhr wieder heruber und kam in seine Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Und siehe, da brachten sie zu ihm einen Gichtbruchigen, der lag auf einem Bette. Da nun Jesus ihren Glauben sah, sprach er zu dem Gichtbruchigen: Sei getrost, mein Sohn; deine Sunden sind dir vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Und siehe, etliche unter den Schriftgelehrten sprachen bei sich selbst: Dieser lasted Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Da aber Jesus ihre Gedanken sah, sprach er: Warum denket ihr so Arges in euren Herzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Welches ist leichter zu sagen: Dir sind deine Sunden vergeben, Oder zu sagen: Stehe auf und wandele?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Auf daß ihr aber wisset, daß des Menschen Sohn Macht habe auf Erden, die Sunden zu vergeben, sprach er zu dem Gichtbruchigen: Stehe auf, heb\' dein Bett auf und gehe heim!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Und er stund auf und ging heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Da das Volk das sah, verwunderte es sich und preisete Gott, der solche Macht den Menschen gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Und da Jesus von dannen ging, sah er einen Menschen am Zoll sitzen, der hieli Matthaus, und sprach zu ihm: Folge mir! Und er stund auf und folgete ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Und es begab sich, da erzu Tische saß, im Hause, siehe, da kamen viel Zollner und Sunder und saüen zu Tische mit Jesu und seinen Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Da das die Pharisaer sahen, sprachen sie zu seinen Jungern: Warum isset euer Meister mit den Zdllnern und Sundern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Da das Jesus horete, sprach er zu ihnen: Die Starken bedurfen des Arztes nicht, sondern die Kranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Gehet aber hin und lemet, was das sei: Ich habe Wohlgefallen an Barmherzigkeit und nicht am Opfer. Ich bin kommen, die Sunder zur Bulie zu rufen und nicht die Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Indes kamen die Junger Johannes zu ihm und sprachen: Warum fasten wir und die Pharisaer so viel, und deine Junger fasten nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jesus sprach zu ihnen: Wie konnen die Hochzeitleute Leid tragen, solange der Brautigam bei ihnen ist? Es wird aber die Zeit kommen, dafi der Brautigam von ihnen genommen wird; alsdann werden sie fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Niemand flicktein alt Kleid mit einem Lappen von neuem Tuch; denn der Lappen reifiet doch wieder vom Kleid, und der Riß wird arger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Man fasset auch nicht Most in aite Schlauche; anders die Schlauche zerreilien, und der Most wird verschuttet, und die Schlauche kommen urn. Sondern man fasset Most in neue Schlauche, so werden sie beide miteinander behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Da er solches mit ihnen redete, siehe, da kam der Obersten einer und fiel vor ihm nieder und sprach: Herr, meine Tochter ist jetzt gestorben; aber komm und lege deine Hand auf sie, so wird sie lebendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Und Jesus stund auf und folgete ihm nach und seine Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Und siehe, ein Weib, das zwolf Jahre den Blutgang gehabt, trat von hinten zu ihm und ruhrete seines Kleides Saum an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Denn sie sprach bei sich selbst: Mocht\' ich nur sein Kleid anruhren, so würde ich gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Da wandte sich Jesus urn und sah sie und sprach: Sei getrost, meine Tochter; dein Glaube hat dir geholfen. Und das Weib ward gesund zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Und als er in des Obersten Haus kam und sah die Pfeifer und das Getümmel des Volks,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'sprach erzu ihnen: Weichet! denn das Magdlein ist nicht tot, sondern es schlaft. Und sie verlachten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Als aber das Volk ausgetrieben war, ging er hinein und ergriff sie bei der Hand. Da stund das Magdlein auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Und dies Gerucht erscholl in dasselbige ganze Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Und da Jesus von dannen furbafi ging, folgeten ihm zwei Blinde nach, die schrieen und sprachen: Ach, du Sohn Davids, erbarme dich unser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Und da er heimkam, traten die Blinden zu ihm. Und Jesus sprach zu ihnen: Glaubet ihr, daß ich euch solches tun kann? Da sprachen sie zu ihm: Herr, ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Da ruhrete er ihre Augen an und sprach: Euch geschehe nach eurem Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Und ihre Augen wurden geoffnet. Und Jesus bedrauete sie und sprach: Sehet zu, daß es niemand erfahre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Aber sie gingen aus und machten ihn ruchbar im selbigen ganzen Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Da nun diese waren hinauskommen, siehe, da brachten sie zu ihm einen Menschen, der war stumm und besessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Und da der Teufel war ausgetrieben, redete der Stumme. Und das Volk verwunderte sich und sprach: Solches ist noch nie in Israel gesehen worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Aber die Pharisaer sprachen: Er treibt die Teufel aus durch der Teufel Obersten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Und Jesus ging umher in alle Stadte und Markte, lehrete in ihren Schulen und predigte das Evangelium von dem Reich und heilete allerlei Seuche und allerlei Krankheit im Volke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Und da er das Volk sah, jammerte ihn desselbigen; denn sie waren verschmachtet und zerstreuet wie die Schafe, die keinen Hirten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Da sprach erzu seinen Jungern: Die Ernte ist grofi; aber wenig sind der Arbeiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Darum bittet den Herrn der Ernte, daß er Arbeiter in seine Ernte sende!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Und er rief seine zwolf Jünger zu sich und gab ihnen Macht uber die unsaubern Geister, daß sie dieselbigen austrieben und heileten allerlei Seuche und allerlei Krankheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Die Namen aber der zwolf Apostel sind diese: Der erste Simon, genannt Petrus, und Andreas, sein Bruder; Jakobus, des Zebedaus Sohn, und Johannes, sein Bruder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippus und Bartholomaus; Thomas und Matthaus, der Zollner; Jakobus, des Alphaus Sohn; Lebbaus mitdem Zunamen Thaddaus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon von Kana und Judas Ischariot, welcher ihn verriet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Diese zwolf sandte Jesus, gebot ihnen und sprach: Gehet nicht auf der Heiden Strafte und ziehet nicht in der Samariter Stadte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'sondern gehet hin zu den verloren Schafen aus dem Hause Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Gehet aber und prediget und sprecht: Das Himmelreich ist nahe herbeikommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Machet die Kranken gesund, reiniget die Aussatzigen, wecket die Toten auf, treibet die Teufel aus! Umsonst habt ihr\'s empfangen, umsonst gebet es auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ihr sollt nicht Gold noch Silber noch Erz in euren Gurteln haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'auch keine Taschezur Wegfahrt, auch nicht zwei Rocke, keine Schuhe, auch keinen Stecken. Denn ein Arbeiter ist seiner Speise wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Wo ihr aber in eine Stadt Oder Markt gehet, da erkundiget euch, ob jemand darinnen sei, der es wert ist; und bei demselben bleibet, bis ihr von dannen ziehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Wo ihr aber in ein Haus gehet, so grüftet dasselbige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Und so es dasselbige Haus wert ist, wird euer Friede auf sie kommen. Ist es aber nicht wert, so wird sich euer Friede wieder zu euch wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Und wo euch jemand nicht annehmen wird noch eure Rede horen, so gehet heraus von demselbigen Hause Oder Stadt und schüttelt den Staub von euren Füften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Wahrlich, ich sage euch, dem Lande der Sodomer und Gomorrer wird es ertraglicher ergehen am Jungsten Gericht denn solcher Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Siehe, ich sende euch wie Schafe mitten unter die Wolfe; darum seid klug wie die Schlangen und ohne Falsch wie die Tauben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Hutet euch aber vor den Menschen! Denn sie werden euch überantworten vor ihre Rathauser und werden euch geifteln in ihren Schulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Und man wird euch vor Fursten und Konige fuhren urn meinetwillen zum Zeugnis uber sie und liber die Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Wenn sie euch nun überantworten werden, so sorget nicht, wie Oder was ihr reden sollt; denn es soil euch zu der Stunde gegeben werden, was ihr reden sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Denn ihr seid es nicht, die da reden, sondern eures Vaters Geist ist es, der durch euch redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Es wird aber ein Bruder den andern zum Tod überantworten und der Vater den Sohn, und die Kinder werden sich emporen wider ihre Eltern und ihnen zum Tode helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Und müsset gehasset werden von jedermann urn meines Namens willen. Wer aber bis an das Ende beharret, der wird selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Wenn sie euch aber in einer Stadt verfolgen, so fliehet in eine andere. Wahrlich, ich sage euch, ihr werdet die Stadte Israels nicht ausrichten, bis des Menschen Sohn kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Der Jünger ist nicht über seinen Meister noch der Knecht über den Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Es ist dem Junger genug, daß er sei wie sein Meister und der Knecht wie sein Herr. Haben sie den Hausvater Beelzebub geheiften, wieviel mehr werden sie seine Hausgenossen also heiften!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Darum fürchtet euch nicht vor ihnen! Es ist nichts verborgen, das nicht offenbar werde, und ist nichts heimlich, das man nicht wissen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Was ich euch sage in Finsternis, das redet im Licht, und was ihr horet in das Ohr, das prediget auf den Dachern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Und fürchtet euch nicht vor denen, die den Leib toten und die Seele nicht mogen toten. Fürchtet euch aber vielmehr vor dem, der Leib und Seele verderben mag in die Holle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Kauft man nicht zwei Sperlinge urn einen Pfennig? Noch fallt derselbigen keiner auf die Erde ohne euren Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Nun aber sind auch eure Haare auf dem Haupt alle gezahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Darum fürchtet euch nicht; ihr seid besser denn viele Sperlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Darum, wer mich bekennet vor den Menschen, den will ich bekennen vor meinem himmlischen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Wer mich aber verleugnet vor den Menschen, den will ich auch verleugnen vor meinem himmlischen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ihr sollt nicht wahnen, daß ich kommen sei, Frieden zu senden auf Erden. Ich bin nicht kommen, Frieden zu senden, sondern das Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Denn ich bin kommen, den Menschen zu erregen wider seinen Vater und die Tochter wider ihre Mutter und die Schnur wider ihre Schwieger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Und des Menschen Feinde werden seine eigenen Hausgenossen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Wer Vater Oder Mutter mehr liebet denn mich, der ist mein nicht wert; und wer Sohn Oder Tochter mehr liebt denn mich, der ist mein nicht wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Und wer nicht sein Kreuz auf sich nimmt und folget mir nach, der ist mein nicht wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Wer sein Leben findet, derwird\'s verlieren; und wer sein Leben verlieret urn meinetwillen, der wird\'s finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Wer euch aufnimmt, der nimmt mich auf; und wer mich aufnimmt, der nimmt den auf, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Wereinen Propheten aufnimmt in eines Propheten Namen, derwird eines Propheten Lohn empfahen. Wereinen Gerechten aufnimmt in eines Gerechten Namen, derwird eines Gerechten Lohn empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Und wer dieser Geringsten einen nur mit einem Becher kalten Wassers tranket in eines Jungers Namen, wahrlich, ich sage euch, es wird ihm nicht unbelohnet bleiben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Und es begab sich, da Jesus solch Gebot zu seinen zwolf Jungern vollendet hatte, ging ervon dannen fürbaft, zu lehren und zu predigen in ihren Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Da aber Johannes im Gefangnis die Werke Christi horete, sandte er seiner Junger zwei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'und ließ ihm sagen: Bist du, der da kommen soil, Oder sollen wir eines andern warten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jesus antwortete und sprach zu ihnen: Gehet hin und saget Johannes wieder, was ihr sehet und horet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Die Blinden sehen, und die Lahmen gehen; die Aussatzigen werden rein, und die Tauben horen; die Toten stehen auf, und den Armen wird das Evangelium geprediget;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'und selig ist, der sich nicht an mir argert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Da die hingingen, fing Jesus an zu reden zu dem Volk von Johannes: Was seid ihr hinausgegangen in die Wuste zu sehen? Wolltet ihr ein Rohr sehen, das der Wind hin und her webt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Oder was seid ihr hinausgegangen zu sehen? Wolltet ihr einen Menschen in weichen Kleidern sehen? Siehe, die da weiche Kleider tragen, sind in der Konige Hausern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Oder was seid ihr hinausgegangen zu sehen? Wolltet ihr einen Propheten sehen? Ja, ich sage euch, der auch mehr ist denn ein Prophet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Denn dieser ist\'s, von dem geschrieben stehet: Siehe, ich sende meinen Engel vor dir her, der deinen Weg vor dir bereiten soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Wahrlich, ich sage euch, unter alien, die von Weibern geboren sind, ist nicht aufkommen, der grower sei denn Johannes der Taufer; der aber der Kleinste ist im Himmelreich, ist grower denn er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Aber von den Tagen Johannes des Taufers bis hieher leidet das Himmelreich Gewalt, und die Gewalt tun, die reiften es zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Denn alle Propheten und das Gesetz haben geweissaget bis auf Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Und (so ihr\'swolltannehmen) er ist Elias, der da soil zukunftig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Wer Ohren hatzu horen, derhore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Wem soil ich aber dies Geschlecht vergleichen? Es ist den Kindlein gleich, die an dem Markt sitzen und rufen gegen ihre Gesellen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'und sprechen: Wir haben euch gepfiffen, und ihr wolltet nicht tanzen; wir haben euch geklaget, und ihr wolltet nicht weinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Johannes ist kommen, aft nicht und trank nicht; so sagen sie: Er hat den Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Des: Menschen Sohn ist kommen, issetund trinket; so sagen sie: Siehe, wie ist der Mensch ein Fresser und ein Weinsaufer, der Zollner und der Sunder Geselle! Und die Weisheit muft sich rechtfertigen lassen von ihren Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Da fing er an die Stadte zu schelten, in weichen am meisten seiner Taten geschehen waren, und hatten sich doch nicht gebessert:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Wehe dir, Chorazin! Wehe dir, Bethsaida! Waren solche Taten zu Tyrus und Sidon geschehen, wie bei euch geschehen sind, sie hatten vorzeiten im Sack und in der Asche Bufte getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Doch ich sage euch: Es wird Tyrus und Sidon ertraglicher ergehen am Jungsten Gerichte denn euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Und du, Kapernaum, die du bist erhoben bis an den Himmel, du wirst bis in die Holle hinuntergestoften werden. Denn so zu Sodom die Taten geschehen waren, die bei dir geschehen sind, sie stunde noch heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Doch ich sage euch: Es wird der Sodomer Land ertraglicher ergehen am Jungsten Gerichte denn dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Zu derselbigen Zeit antwortete Jesus und sprach: Ich preise dich, Vater und Herr Himmels und der Erde, daß du solches den Weisen und Klugen verborgen hast und hast es den Unmundigen offenbaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Vater, denn es ist also wohlgefallig gewesen vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Alle Dinge sind mir übergeben von meinem Vater. Und niemand kennet den Sohn denn nur der Vater; und niemand kennet den Vater denn nur der Sohn, und wem es der Sohn will offenbaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommet her zu mir, alle, die ihr muhselig und beladen seid, ich will euch erquicken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Nehmet auf euch mein Joch und lernet von mir; denn ich bin sanftmutig und von Herzen demutig; so werdet ihr Ruhe finden fur eure Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Denn mein Joch ist sanft, und meine Last ist leicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Zu der Zeit ging Jesus durch die Saat am Sabbat; und seine Jünger waren hungrig, fingen an, Ahren auszuraufen, und alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Da das die Pharisaer sahen, sprachen sie zu ihm: Siehe, deine Jünger tun, was sich nicht ziemt, am Sabbat zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Er aber sprach zu ihnen: Habt ihr nicht gelesen, was David tat, da ihn und die mit ihm waren, hungerte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'wie er in das Gotteshaus ging und aft die Schaubrote, die ihm doch nicht ziemten zu essen, noch denen, die mit ihm waren, sondern allein den Priestern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Oder habt ihr nicht gelesen im Gesetz, wie die Priester am Sabbat im Tempel den Sabbat brechen und sind doch ohne Schuld?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ich sage aber euch, daß hier der ist, der auch grafter ist denn der Tempel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Wenn ihr aber wüfttet, was das sei: Ich habe Wohlgefallen an der Barmherzigkeit und nicht am Opfer, hattet ihr die Unschuldigen nicht verdammt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Des Menschen Sohn ist ein Herr auch uber den Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Und er ging von dannen fürbaft und kam in ihre Schule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Und siehe, da war ein Mensch, der hatte eine verdorrete Hand. Und sie fragten ihn und sprachen: Ist\'s auch recht am Sabbat heilen? auf dati sie eine Sache wider ihn flatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Aber er sprach zu ihnen: Welcher ist unter euch, so er ein Schaf hat, das ihm am Sabbat in eine Grube fallt, der es nicht ergreife und aufhebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Wieviel besser ist nun ein Mensch denn ein Schaf! Darum mag man wohl am Sabbat Gutes tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Da sprach er zu dem Menschen: Strecke deine Hand aus! Und er streckte sie aus; und sie ward ihm wieder gesund gleichwie die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Da gingen die Pharisaer hinaus und hielten einen Rat uber ihn, wie sie ihn umbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Aber da Jesus das erfuhr, wich er von dannen. Und ihm folgte viel Volks nach, und er heilete sie alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'und bedrauete sie, dafi sie ihn nicht meldeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'auf dati erfullet wurde, was gesagt ist durch den Propheten Jesaja, der da spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Siehe, das ist mein Knecht, den ich erwahlet habe, und mein Liebster, an dem meine Seele Wohlgefallen hat; ich will meinen Geist auf ihn legen, und er soil den Heiden das Gericht verkündigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Erwird nicht zanken noch schreien, und man wird sein Geschrei nicht horen auf den Gassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Das zerstoftene Rohr wird er nicht zerbrechen und den glimmenden Docht wird er nicht ausloschen, bis daß er ausfuhre das Gericht zum Sieg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Und die Heiden werden auf seinen Namen hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Da ward ein Besessener zu ihm gebracht, der war blind und stumm; und er heilete ihn also, daß der Blinde und Stumme beides, redete und sah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Und alles Volk entsetzte sich und sprach: Ist dieser nicht Davids Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Aber die Pharisaer, da sie es horeten, sprachen sie: Er treibet die Teufel nicht anders aus als durch Beelzebub, der Teufel Obersten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jesus vernahm aber ihre Gedanken und sprach zu ihnen: Ein jeglich Reich, so es mit sich selbst uneins wird, das wird wuste, und eine jegliche Stadt Oder Haus, so es mit sich selbst uneins wird, mag\'s nicht bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'So denn ein Satan den andern austreibt, so muft er mit sich selbst uneins sein; wie mag denn sein Reich bestehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'So ich aber die Teufel durch Beelzebub austreibe, durch wen treiben sie eure Kinder aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'So ich aber die Teufel durch den Geist Gottes austreibe, so ist je das Reich Gottes zu euch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Oder wie kann jemand in eines Starken Haus gehen und ihm seinen Hausrat rauben, es sei denn, daß er zuvor den Starken binde und alsdann ihm sein Haus beraube?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Wer nicht mit mir ist, der ist wider mich, und wer nicht mit mir sammelt, der zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Darum sage ich euch: Alle Sunde und Lasterung wird den Menschen vergeben, aber die Lasterung wider den Geist wird den Menschen nicht vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Und wer etwas redet wider des Menschen Sohn, dem wird es vergeben; aber wer etwas redet wider den Heiligen Geist, dem wird\'s nicht vergeben, weder in dieser noch in jener Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Setzet entweder einen guten Baum, so wird die Frucht gut; Oder setzet einen faulen Baum, so wird die Frucht faul; denn an der Frucht erkennet man den Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Ihr Otterngezuchte, wie konnet ihr Gutes reden, dieweil ihr bose seid? Wes das Herz voll ist, des gehet der Mund uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Ein guter Mensch bringet Gutes hervor aus seinem guten Schatz des Herzens, und ein boser Mensch bringet Boses hervor aus seinem bosen Schatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ich sage euch aber, daß die Menschen müssen Rechenschaft geben am Jungsten Gericht von einem jeglichen unnützen Wort, das sie geredet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Aus deinen Worten wirst du gerechtfertiget werden und aus deinen Worten wirst du verdammt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Da antworteten etliche unter den Schriftgelehrten und Pharisaern und sprachen: Meister, wirwollten gerne ein Zeichen von dirsehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Und er antwortete und sprach zu ihnen: Die bose und ehebrecherische Art sucht ein Zeichen, und es wird ihr kein Zeichen gegeben werden denn das Zeichen des Propheten Jona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Denn gleichwie Jona wardrei Tage und drei Nachte in des Walfisches Bauch, also wird des Menschen Sohn drei Tage und drei Nachte mitten in der Erde sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Die Leute von Ninive werden auftreten am Jungsten Gerichte mit diesem Geschlechte und werden es verdammen; denn sie taten Bufte nach der Predigt des Jona. Und siehe, hier ist mehr denn Jona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Die Konigin von Mittag wird auftreten am Jungsten Gerichte mit diesem Geschlecht und wird es verdammen; denn sie kam vom Ende der Erde, Salomos Weisheit zu horen. Und siehe, hier ist mehr denn Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Wenn der unsaubere Geist von dem Menschen ausgefahren ist, so durchwandelt er dürre Statten, suchet Ruhe und findet sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Dasprichterdenn: Ich will wieder umkehren in mein Haus, daraus ich gegangen bin. Und wenn er kommt, so findet er\'s müftig, gekehret und geschmuckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'So gehet er hin und nimmt zu sich sieben andere Geister, die arger sind denn er selbst; und wenn sie hineinkommen, wohnen sie allda, und wird mit demselben Menschen hernach arger, denn es vorhin war. Also wird\'s auch diesem argen Geschlecht gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Da er noch also zu dem Volk redete, siehe, da stunden seine Mutter und seine Brüder drauften, die wollten mit ihm reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Da sprach einer zu ihm: Siehe, deine Mutter und deine Brüder stehen drauften und wollen mit dir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Er antwortete aber und sprach zu dem, der es ihm ansagte: Wer ist meine Mutter, und wer sind meine Brüder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Und reckte die Hand aus uber seine Jünger und sprach: Siehe da, das ist meine Mutter und meine Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Denn wer den Wilien tut meines Vaters im Himmel, derselbige ist mein Bruder, Schwester und Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'An demselbigen Tage ging Jesus aus dem Hause und setzte sich an das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Und es versammelte sich viel Volks zu ihm, also daß er in das Schiff trat und saft. Und alles Volk stund am Ufer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Und er redete zu ihnen mancherlei durch Gleichnisse und sprach: Siehe, es ging ein Samann aus zu saen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Und indem ersaete, fiel etliches an den Weg; da kamen die Vogel und fraften\'s auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Etliches fiel in das Steinige; da es nicht viel Erde hatte, und ging bald auf, darum daß es nicht tiefe Erde hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Als aber die Sonne aufging, verwelkte es, und dieweil es nicht Wurzel hatte, ward es dürr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Etliches fiel unter die Dornen; und die Dornen wuchsen auf und erstickten\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Etliches fiel auf ein gut Land und trug Frucht, etliches hundertfaltig, etliches sechzigfaltig, etliches dreiftigfaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Wer Ohren hat zu horen, der hbre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Und die Jünger traten zu ihm und sprachen: Warum redest du zu ihnen durch Gleichnisse?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Er antwortete und sprach: Euch ist\'s gegeben, daß ihr, das Geheimnis des Himmelreichs vernehmet; diesen aber ist\'s nicht gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Denn wer da hat, dem wird gegeben, daß er die Fülle habe; wer aber nicht hat, von dem wird auch genommen, was er hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Darum rede ich zu ihnen durch Gleichnisse. Denn mit sehenden Augen sehen sie nicht und mit horenden Ohren horen sie nicht; denn sie verstehen es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Und uber ihnen wird die Weissagung Jesajas erfullet, die da sagt: Mit den Ohren werdet ihr horen und werdet es nicht verstehen, und mit sehenden Augen werdet ihr sehen und werdet es nicht vernehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Denn dieses Volkes Herz ist verstockt, und ihre Ohren horen libel, und ihre Augen schlummern, auf daß sie nicht dermaleinst mit den Augen sehen und mit den Ohren horen und mit dem Herzen verstehen und sich bekehren, daß ich ihnen hulfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Aber selig sind eure Augen, daß sie sehen, und eure Ohren, daß sie horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Wahrlich, ich sage euch: Viel Propheten und Gerechte haben begehrt zu sehen, was ihr sehet, und haben\'s nicht gesehen, und zu horen, was ihr horet, und haben\'s nicht gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'So horet nun ihr dieses Gleichnis von dem Samann!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Wenn jemand das Wort von dem Reich horet und nicht verstehet, so kommt der Arge und reiftet es hin, was da gesaet ist in sein Herz; und der ist\'s, der am Wege gesaet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Der aber auf das Steinige gesaet ist, der ist\'s, wenn jemand das Wort horet und dasselbige bald aufnimmt mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Aber er hat nicht Wurzel in ihm, sondern erist wetterwendisch; wenn sich Trübsal und Verfolgung erhebt um des Worts willen, so argert ersich bald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Der aber unter die Dornen gesaet ist, der ist\'s, wenn jemand das Wort horet und die Sorge dieser Welt und Betrug des Reichtums erstickt das Wort und bringet nicht Frucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Der aber in das gute Land gesaet ist, der ist\'s, wenn jemand das Wort horet und verstehet es und dann auch Frucht bringet; und etlichen tragt hundertfaltig, etlicher aber sechzigfaltig, etlicher dreil Jigfaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Er legte ihnen ein ander Gleichnis vor und sprach: Das Himmelreich istgleich einem Menschen, der guten Samen auf seinen Acker saete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Da aber die Leute schliefen, kam sein Feind und saete Unkraut zwischen den Weizen und ging davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Da nun das Kraut wuchs und Frucht brachte, da fand sich auch das Unkraut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Da traten die Knechte zu dem Hausvater und sprachen: Herr, hast du nicht guten Samen auf deinen Acker gesaet? Woher hat er denn das Unkraut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Er sprach zu ihnen: Das hat der Feind getan. Da sprachen die Knechte: Willst du denn, daü wir hingehen und es ausjaten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Er aber sprach: Nein, auf daü ihr nicht zugleich den Weizen mit ausraufet, so ihr das Unkraut ausjatet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lasset beides miteinander wachsen bis zur Ernte; und um der Ernte Zeit will ich zu den Schnittern sagen: Sammelt zuvor das Unkraut und bindet es in Bundlein, dad man es verbrenne; aber den Weizen sammelt mir in meine Scheuern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Ein ander Gleichnis legte er ihnen vor und sprach: Das Himmelreich istgleich einem Senfkorn, das ein Mensch nahm und saete auf seinen Acker,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'welches das kleinste ist unter allem Samen; wenn es aber erwachst, so ist es das grblite unter dem Kohl und wird ein Baum, dad die Vogel unter dem Himmel kommen und wohnen unter seinen Zweigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Ein ander Gleichnis redete er zu ihnen: Das Himmelreich ist einem Sauerteig gleich, den ein Weib nahm und vermengete ihn unter drei Scheffel Mehl, bis dad es gar durchsauert ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Solches alles redete Jesus durch Gleichnisse zu dem Volk und ohne Gleichnisse redete er nicht zu ihnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'auf dad erfullet wurde, was gesagt ist durch den Propheten, der da spricht: Ich will meinen Mund auftun in Gleichnissen und will aussprechen die Heimlichkeiten von Anfang der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Da lied Jesus das Volk von sich und kam heim. Und seine Junger traten zu ihm und sprachen: Deute uns dieses Gleichnis vom Unkraut auf dem Acker!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Erantwortete und sprach zu ihnen: Des Menschen Sohn ist\'s, der da guten Samen saet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Der Acker ist die Welt. Der gute Same sind die Kinder des Reichs. Das Unkraut sind die Kinder der Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Der Feind, der sie saet, ist der Teufel. Die Ernte ist das Ende der Welt. Die Schnitter sind die Engel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Gleichwie man nun das Unkraut ausjatet und mit Feuer verbrennet, so wird\'s auch am Ende dieser Welt gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Des Menschen Sohn wird seine Engel senden, und sie werden sammeln aus seinem Reich alle Argernisse und die da Unrecht tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'und werden sie in den Feuerofen werfen; da wird sein Heulen und Zahneklappen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Dann werden die Gerechten leuchten wie die Sonne in ihres Vaters Reich. Wer Ohren hat zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Abermal ist gleich das Himmelreich einem verborgenen Schatz im Acker, welchen ein Mensch fand und verbarg ihn und ging hin vor Freuden uber denselbigen und verkaufte alles, was er hatte, und kaufte den Acker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Abermal ist gleich das Himmelreich einem Kaufmann, der gute Perlen suchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Und da er eine kostliche Perle fand, ging er hin und verkaufte alles, was er hatte, und kaufte dieselbige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Abermal ist gleich das Himmelreich einem Netz, das ins Meer geworfen ist, damit man allerlei Gattung fanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Wenn es aber voll ist, so ziehen sie es heraus an das Ufer, sitzen und lesen die guten in ein Gefali zusammen; aber die faulen werfen sie weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Also wird es auch am Ende der Welt gehen. Die Engel werden ausgehen und die Bosen von den Gerechten scheiden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'und werden sie in den Feuerofen werfen; da wird Heulen und Zahneklappen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Und Jesus sprach zu ihnen: Habt ihr das alles verstanden? Sie sprachen: Ja, Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Da sprach er: Darum, ein jeglicher Schriftgelehrter, zum Himmelreich gelehrt, ist gleich einem Hausvater, der aus seinem Schatz Neues und Altes hervortragt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Und es begab sich da Jesus diese Gleichnisse vollendet hatte, ging er von dannen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'und kam in sein Vaterland und lehrete sie in ihren Schulen, also auch, dafi sie sich entsetzten und sprachen: Woher kommt diesem solche Weisheit und Taten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ist er nicht eines Zimmermanns Sohn? Heifit nicht seine Mutter Maria und seine Bruder Jakob und Joses und Simon und Judas?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Und seine Schwestern, sind sie nicht alle bei uns? Woher kommt ihm denn das alles?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Und argerten sich an ihm. Jesus aber sprach zu ihnen: Ein Prophet gilt nirgend weniger denn in seinem Vaterlande und in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Und er tat daselbst nicht viel Zeichen um ihres Unglaubens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Zu der Zeit kam das Gerucht von Jesu vor den Vierfürsten Herodes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Und er sprach zu seinen Knechten: Dieser ist Johannes der Taufer; er ist von den Toten auferstanden, darum tut er solche Taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Denn Herodes hatte Johannes gegriffen, gebunden und in das Gefangnis gelegt von wegen der Herodias, seines Bruders Philippus Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Denn Johannes hatte zu ihm gesagt: Es ist nicht recht, daß du sie habest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Und er hatte ihn gerne getotet, furchtete sich aber vor dem Volk; denn sie hielten ihn fur einen Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Da aber Herodes seinen Jahrestag beging, da tanzte die Tochter der Herodias vor ihnen. Das gefiel Herodes wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Darum verhieß, er ihr mit einem Eide, er wollte ihr geben, was sie fordern würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Und als sie zuvor von ihrer Mutter zugerichtet war, sprach sie: Gib mir her auf einer Schussel das Haupt Johannes des Taufers!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Und der Konig ward traurig; doch um des Eides willen und derer, die mit ihm zu Tische salten, befahl er\'s ihrzu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Und schickte hin und enthauptete Johannes im Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Und sein Haupt ward hergetragen in einer Schussel und dem Magdlein gegeben; und sie brachte es ihrer Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Da kamen seine Jünger und nahmen seinen Leib und begruben ihn und kamen und verkundigten das Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Da das Jesus horete, wich ervon dannen auf einem Schiff in eine Wüste allein. Und da das Volk das horete, folgte es ihm nach zu Fu(S aus den Stadten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Und Jesus ging hervor und sah das groiße Volk; und esjammerte ihn derselbigen und heilete ihre Kranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Am Abend aber traten seine Junger zu ihm und sprachen: Dies ist eine Wüste, und die Nacht fallt daher; laß das Volk von dir, dafi sie hin in die Markte gehen und ihnen Speise kaufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Aber Jesus sprach zu ihnen: Es ist nicht not, daß sie hingehen; gebt ihr ihnen zu essen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Sie sprachen: Wir haben hier nichtsdenn fünf Brote und zwei Fische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Und er sprach: Bringet mir sie her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Und er hieli das Volk sich lagern auf das Gras und nahm die fünf Brote und die zwei Fische, sah auf gen Himmel und dankte und brach\'s und gab die Brote den Jüngern, und die Junger gaben sie dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Und sie alien alle und wurden satt und huben auf, was übrigblieb von Brocken, zwolf Korbe voll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Die aber gegessen hatten, derwaren bei fünftausend Mann ohne Weiber und Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Und alsbald trieb Jesus seine Jünger, daß sie in das Schiff traten und vor ihm herüberfuhren, bis er das Volk von sich lielie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Und da er das Volk von sich gelassen hatte, stieg er auf einen Berg alleine, daß er betete. Und am Abend war er alleine daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Und das Schiff war schon mitten, auf dem Meer und litt Not von den Wellen; denn der Wind war ihnen wider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Aber in der vierten Nachtwache kam Jesus zu ihnen und ging auf dem Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Und da ihn die Jünger sahen auf dem Meer gehen, erschraken sie und sprachen: Es istein Gespenst! und schrieen vor Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Und alsbald redete Jesus mit ihnen und sprach: Seid getrost, ich bin\'s; fürchtet euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Petrus aber antwortete ihm und sprach: Herr, bist du es, so heili mich zu dir kommen auf dem Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Und er sprach: Komm her! Und Petrus trat aus dem Schiff und ging auf dem Wasser, dafi er zu Jesu kame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Er sah aber einen starken Wind. Da erschrak er und hub an zu sinken, schrie und sprach: Herr, hilf mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Jesus aber reckte bald die Hand aus und ergriff ihn und sprach zu ihm: O du Kleinglaubiger, warum zweifeltest du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Und sie traten in das Schiff, und der Wind legte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Die aber im Schiff waren, kamen und fielen vor ihm nieder und sprachen: Du bistwahrlich Gottes Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Und sie schifften hinüber und kamen in das Land Genezareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Und da die Leute am selbigen Ort sein gewahr wurden, schickten sie aus in das ganze Land umher und brachten allerlei Ungesunde zu ihm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'und baten ihn, dafi sie nur seines Kleides Saum anruhreten. Und alle, die da anruhreten, wurden gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Da kamen zu ihm die Schriftgelehrten und Pharisaer von Jerusalem und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Warum ubertreten deine Junger der Altesten Aufsatze? Sie waschen ihre Hande nicht, wenn sie Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Er antwortete und sprach zu ihnen: Warum ubertretet denn ihr Gottes Gebot um eurer Aufsatze willen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Gott hat geboten: Du sollst Vater und Mutter ehren; wer aber Vater und Mutter flucht, der soil des Todes sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Aber ihr lehret: Wer zum Vater Oder zur Mutter spricht: Wenn ich\'s opfere, so ist\'s dir viel nützer, der tut wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Damit geschiehet es, daü niemand hinfort seinen Vater Oder seine Mutter ehret; und habt also Gottes Gebot aufgehoben um eurer Aufsatze willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Ihr Heuchler, es hat wohl Jesaja von euch geweissaget und gesprochen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Dies Volk nahet sich zu mir mit seinem Munde und ehret mich mit seinen Lippen, aber ihr Herz ist feme von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Aber vergeblich dienen sie mir, dieweil sie lehren solche Lehren, die nichts denn Menschengebot sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Und er rief das Volk zu sich und sprach zu ihnen: Horet zu und vernehmet\'s!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Was zum Munde eingehet, das verunreiniget den Menschen nicht, sondern was zum Munde ausgehet, das verunreiniget den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Da traten seine Jungerzu ihm und sprachen: Weifit du auch, daß sich die Pharisaer argerten, da sie das Wort horeten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Aber er antwortete und sprach: Alle Pflanzen, die mein himmlischen Vater nicht gepflanzet, die werden ausgereutet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Lasset sie fahren! Sie sind blind und Blindenleiter. Wenn aberein Blinder den andern leitet, so fallen sie beide in die Grube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Da antwortete Petrus und sprach zu ihm: Deute uns dies Gleichnis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Und Jesus sprach zu ihnen: Seid ihr denn auch noch unverstandig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Merket ihr noch nicht, daß alles, was zum Munde eingehet, das gehet in den Bauch und wird durch den naturlichen Gang ausgeworfen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Was aber zum Munde herausgehet, das kommt aus dem Herzen, und das verunreiniget den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Denn aus dem Herzen kommen arge Gedanken: Mord, Ehebruch, Hurerei, Dieberei, falsche Zeugnisse, Lasterung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Das sind die Stücke, die den Menschen verunreinigen. Aber mit ungewaschenen Handen essen verunreiniget den Menschen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Und Jesus ging aus von dannen und entwich in die Gegend von Tyrus und Sidon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Und siehe, ein kanaanaisch Weib ging aus derselbigen Grenze und schrie ihm nach und sprach: Ach Herr, du Sohn Davids, erbarme dich mein! Meine Tochterwird vom Teufel ubel geplaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Und er antwortete ihr kein Wort. Da traten zu ihm seine Jünger, baten ihn und sprachen: Lali sie doch von dir; denn sie schreiet uns nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Er antwortete aber und sprach: Ich bin nicht gesandt, denn nur zu den verlornen Schafen von dem Hause Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Sie kam aber und fiel vor ihm nieder und sprach: Herr, hilf mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Aber er antwortete und sprach: Es ist nicht fein, daß man den Kindern ihr Brot nehme und werfe es vor die Hunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sie sprach: Ja, Herr; aber doch essen die Hündlein von den Brosamen, die von ihrer Herren Tisch fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Da antwortete Jesus und sprach zu ihr: 0 Weib, dein Glaube ist groli; dir geschehe, wie du willst! Und ihre Tochter ward gesund zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Und Jesus ging von dannen furbai J, und kam an das galilaischen Meer und ging auf einen Berg und setzte sich allda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Und es kam zu ihm viel Volks die hatten mit sich Lahme, Blinde, Stumme, Krüppel und viel andere und warfen sie Jesu vor die Fülie; und er heilete sie,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'daß sich das Volk verwunderte, da sie sahen, daß die Stummen redeten, die Kruppel gesund waren, die Lahmen gingen, die Blinden sahen, und preiseten den Gott Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Und Jesus rief seine Jünger zu sich und sprach: Es jammed mich des Volks; denn sie beharren nun wohl drei Tage bei mir und haben nichts zu essen; und ich will sie nicht ungegessen von mir lassen, auf daß sie nicht verschmachten auf dem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Da sprachen zu ihm seine Jünger: Woher mogen wir so viel Brots nehmen in der Wüste, daß wir so viel Volks sattigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Und Jesus sprach zu ihnen: Wieviel Brots habt ihr? Sie sprachen: Sieben und ein wenig Fischlein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Und er hieti das Volk sich lagern auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Und nahm die sieben Brote und die Fische, dankete, brach sie und gab sie seinen Jüngern, und die Jünger gaben sie dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Und sie alien alle und wurden satt und huben auf, was überblieb von Brocken, sieben Korbe voll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Und die da gegessen hatten, der waren viertausend Mann, ausgenommen Weiber und Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Und da er das Volk hatte von sich gelassen, trat er in ein Schiff und kam in die Grenze Magdala.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Da traten die Pharisaer und Sadduzaerzu ihm, die versuchten ihn und forderten, daß er sie ein Zeichen vom Himmel sehen lielie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Aber er antwortete und sprach: Des Abends sprechet ihr: Es wird ein schoner Tag werden, denn der Himmel ist rot;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'und des Morgens sprechet ihr: Eswird heute Ungewitter sein, denn der Himmel ist rot und trübe. Ihr Heuchler! Des Himmels Gestalt konnet ihr urteilen; konnet ihr denn nicht auch die Zeichen dieser Zeit urteilen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Diese bose und ehebrecherische Art sucht ein Zeichen, und soil ihr kein Zeichen gegeben werden denn das Zeichen des Propheten Jona. Und er lieli sie und ging davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Und da seine Jünger waren hinubergefahren, hatten sie vergessen, Brot mit sich zu nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jesus aber sprach zu ihnen: Sehet zu und hütet euch vor dem Sauerteig der Pharisaer und Sadduzaer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Da dachten sie bei sich selbst und sprachen: Das wird\'s sein, dafi wir nicht haben Brot mit uns genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Da das Jesus vernahm, sprach er zu ihnen: Ihr Kleinglaubigen, was bekümmert ihr euch doch, daß ihr nicht habt Brot mit euch genommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Vernehmet ihr noch nichts? Gedenket ihr nicht an die fünf Brote unter die Funftausend und wieviel Korbe ihr da aufhubet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Auch nicht an die sieben Brote unter die Viertausend, und wieviel Korbe ihr da aufhubet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Wie verstehet ihrdenn nicht, daß ich euch nicht sage vom Brot, wenn ich sage: Hutet euch vor dem Sauerteige der Pharisaer und Sadduzaer?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Da verstunden sie, daß er nicht gesagt hatte, daß sie sich hüten sollten vor dem Sauerteige des Brats, sondern vor der Lehre der Pharisaer und Sadduzaer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Da kam Jesus in die Gegend der Stadt Casarea Philippi und fragte seine Jünger und sprach: Wersagen die Leute, daß des Menschen Sohn sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Sie sprachen: Etliche sagen, du seiest Johannes der Taufer; die andern, du seiest Elia; etliche, du seiest Jeremia Oder der Propheten einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Er sprach zu ihnen: Wer sagt denn ihr, daß ich sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Da antwortete Simon Petrus und sprach: Du bist Christus, des lebendigen Gottes Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Und Jesus antwortete und sprach zu ihm: Selig bist du, Simon, Jonas Sohn; denn Fleisch und Blut hat dir das nicht offenbart, sondern mein Vater im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Und ich sage dir auch: Du bist Petrus, und auf diesen Felsen will ich bauen meine Gemeinde, und die Pforten der Holle sollen sie nicht uberwaltigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Und will dir des Himmelreichs Schlussel geben. Alles, was du auf Erden binden wirst, soil auch im Himmel gebunden sein, und alles, was du auf Erden losen wirst, soil auch im Himmel los sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Da verbot er seinen Jungern, daß sie niemand sagen sollten, daß er Jesus, der Christ, ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Von der Zeitan fing Jesus an und zeigte seinen Jungern, wie er mulite hin gen Jerusalem gehen und viel leiden von den Altesten und Hohenpriestern und Schriftgelehrten und getotet werden und am dritten Tage auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Und Petrus nahm ihn zu sich, fuhr ihn an und sprach: Herr, schone dein selbst; das widerfahre dir nur nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Aber erwandte sich urn und sprach zu Petrus: Heb dich, Satan, von mir! Du bist mir argerlich; denn du meinest nicht, was gottlich, sondern was menschlich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Da sprach Jesus zu seinen Jungern: Will mir jemand nachfolgen, der verleugne sich selbst und nehme sein Kreuz auf sich und folge mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Denn wer sein Leben erhalten will, der wird\'s verlieren; wer aber sein Leben verlieret urn meinetwillen, der wird\'s finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Was hülfe es dem Menschen, so er die ganze Welt gewonne und nahme doch Schaden an seiner Seele? Oder was kann der Mensch geben, damit er seine Seele wieder lose?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Denn es wird je geschehen, daß des Menschen Sohn komme in der Herrlichkeit seines Vaters mit seinen Engeln; und alsdann wird ereinem jeglichen vergelten nach seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Wahrlich, ich sage euch, es stehen etliche hier, die nicht schmecken werden den Tod, bis daß sie des Menschen Sohn kommen sehen in seinem Reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Und nach sechs Tagen nahm Jesus zu sich Petrus und Jakobus und Johannes, seinen Bruder, und fuhrete sie beiseits auf einen hohen Berg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Und ward verklaret vor ihnen, und sein Angesicht leuchtete wie die Sonne, und seine Kleider wurden weili als ein Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Und siehe, da erschienen ihnen Mose und Elia, die redeten mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Petrus aber antwortete und sprach zu Jesu: Herr, hier ist gut sein; willst du, so wollen wir hier drei Hutten machen, direine, Mose eine und Elia eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Da ernoch also redete, siehe, da uberschattete sie eine lichte Wolke. Und siehe, eine Stimme aus der Wolke sprach: Dies ist mein lieber Sohn, an welchem ich Wohlgefallen habe; den sollt ihr horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Da das die Jünger horeten, Helen sie auf ihr Angesicht und erschraken sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jesus aber trat zu ihnen, rührete sie an und sprach: Stehet auf und furchtet euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Da sie aber ihre Augen aufhuben, sahen sie niemand denn Jesus alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Und da sie vom Berge herabgingen, gebot ihnen Jesus und sprach: Ihr sollt dies Gesicht niemand sagen, bis des Menschen Sohn von den Toten auferstanden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Und seine Jünger fragten ihn und sprachen: Was sagen denn die Schriftgelehrten, Elia müsse zuvor kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jesus antwortete und sprach zu ihnen: Elia soil ja zuvor kommen und alles zurechtbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Doch ich sage euch: Es ist Elia schon kommen, und sie haben ihn nicht erkannt, sondern haben an ihm getan, was sie wollten. Also wird auch des Menschen Sohn leiden müssen von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Da verstunden die Jünger, daß er von Johannes dem Taufer zu ihnen geredet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Und da sie zu dem Volk kamen, trat zu ihm ein Mensch und fiel ihm zu Fülien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'und sprach: Herr, erbarme dich über meinen Sohn; denn er ist mondsüchtig und hat ein schweres Leiden; erfallt oft ins Feuer und oft ins Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Und ich habe ihn zu deinen Jungern gebracht, und sie konnten ihm nicht helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jesus aber antwortete und sprach: O du unglaubige und verkehrte Art, wie lange soil ich bei euch sein? Wie lange soli ich euch dulden? Bringet mirihn hieher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Und Jesus bedrauete ihn; und der Teufel fuhr aus von ihm, und der Knabe ward gesund zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Da traten zu ihm seine Junger besonders und sprachen: Warum konnten wir ihn nicht austreiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jesus aber antwortete und sprach zu ihnen: Um eures Unglaubens willen. Denn ich sage euch: Wahrlich, so ihr Glauben habt wie ein Senfkorn, so moget ihr sagen zu diesem Berge: Heb\' dich von hinnen dorthin! so wird er sich heben, und euch wird nichts unmoglich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Aber diese Art fahrt nicht aus denn durch Beten und Fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Da sie aber ihr Wesen hatten in Galilaa, sprach Jesus zu ihnen: Es ist zukunftig, dad. des Menschen Sohn uberantwortet werde in der Menschen Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Und sie werden ihn toten; und am dritten Tage wird er auferstehen. Und sie wurden sehr betrubt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Da sie nun gen Kapernaum kamen, gingen zu Petrus, die den Zinsgroschen einnahmen, und sprachen: Pflegt euer Meister nicht den Zinsgroschen zu geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Er sprach: Ja. Und als er heimkam, kam ihm Jesus zuvor und sprach: Was dunkt dich, Simon? Von wem nehmen die Konige auf Erden den Zoll Oder Zins, von ihren Kindern Oder von den Fremden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Da sprach zu ihm Petrus: Von den Fremden. Jesus sprach zu ihm: So sind die Kinder frei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Auf dafi aber wir sie nicht argern, so gehe hin an das Meer und wirf die Angel, und den ersten Fisch, der herauffahrt, den nimm; und wenn du seinen Mund auftust, wirstdu einen Stater finden. Denselbigen nimm und gib ihn fur mich und dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Zu derselbigen Stunde traten die Junger zu Jesus und sprachen: Wer ist doch der Großte im Himmelreich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Jesus rief ein Kind zu sich und stellete das mitten unter sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'und sprach: Wahrlich, ich sage euch, es sei denn, daß ihr euch umkehret und werdetwie die Kinder, so werdet ihr nicht ins Himmelreich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Wer nun sich selbst niedriget wie dies Kind, der ist der Großte im Himmelreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Und wer ein solches Kind aufnimmt in meinem Namen, der nimmt mich auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Wer aber argert dieser Geringsten einen, die an mich glauben, dem ware besser, dafi ein Muhlstein an seinen Hals gehanget, und er ersauft wurde im Meer, da es am tiefsten ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Wehe der Welt der Argernisse halben! Es muß ja Argemis kommen; doch wehe dem Menschen, durch welchen Argemis kommt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'So aber deine Hand Oder dein Fuß dich argert, so haue ihn ab und wirf ihn von dir. Es ist dir besser, daß du zum Leben lahm Oder als ein Kruppel eingehest, denn daß du zwo Hande Oder zwei Füße habest und werdest in das ewige Feuer geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Und so dich dein Auge argert, reiß es aus und wirfs von dir. Es ist dir besser, daß du einaugig zum Leben eingehest, denn daß du zwei Augen habest und werdest in das hollische Feuer geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Sehet zu, daß ihr nicht jemand von diesen Kleinen verachtet! Denn ich sage euch: Ihre Engel im Himmel sehen allezeit das Angesicht meines Vaters im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Denn des Menschen Sohn ist kommen, selig zu machen, was verloren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Was dunket euch? Wenn irgendein Mensch hundert Schafe hatte, und eins unter denselbigen sich verirrete, laßt er nicht die neunundneunzig auf den Bergen, gehet hin und suchet das verirrte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Und so sich\'s begibt, daß er\'s findet, wahrlich, ich sage euch, er freuet sich daruber mehr denn uber die neunundneunzig, die nicht verirret sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Also auch ist\'s voreurem Vater im Himmel nicht der Wille, daß jemand von diesen Kleinen verloren werde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Sundiget aber dein Bruderan dir, so gehe hin und strafe ihn zwischen dir und ihm allein. Horet er dich, so hast du deinen Bruder gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Horet er dich nicht, so nimm noch einen Oder zwei zu dir, auf daß alle Sache bestehe auf zweier Oder dreier Zeugen Mund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Horet er die nicht, so sage es der Gemeinde. Horet er die Gemeinde nicht, so halt ihn als einen Heiden und Zollner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Wahrlich, ich sage euch: Was ihr auf Erden binden werdet, soli auch im Himmel gebunden sein, und was ihr auf Erden losen werdet, soil auch im Himmel los sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Weiter sage ich euch: Wo zwei unter euch eins werden auf Erden, warum es ist, das sie bitten wollen, das soli ihnen widerfahren von meinem Vater im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Denn wo zwei Oder drei versammelt sind in meinem Namen, da bin ich mitten unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Da trat Petrus zu ihm und sprach: Herr, wie oft muß ich denn meinem Bruder, der an mir sundiget, vergeben? Ist\'s genug siebenmal?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesus sprach zu ihm: Ich sage dir, nicht siebenmal, sondern siebenzigmal siebenmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Darum ist das Himmelreich gleich einem Konige, der mit seinen Knechten rechnen woilte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Und als er anting zu rechnen, kam ihm einer vor, der war ihm zehntausend Pfund schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Da er\'s nun nicht hatte zu bezahlen, hieß der Herr verkaufen ihn und sein Weib und seine Kinder und alles, was er hatte, und bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Da fiel der Knecht nieder und betete ihn an und sprach: Herr, habe Geduld mit mir! Ich will dir\'s alles bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Da jammerte den Herm desselbigen Knechts und liefi ihn los, und die Schuld erlieli er ihm auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Da ging derselbige Knecht hinaus und fand einen seiner Mitknechte, der war ihm hundert Groschen schuldig. Und er griff ihn an und wurgete ihn und sprach: Bezahle mir, was du mir schuldig bist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Da fiel sein Mitknecht nieder und bat ihn und sprach: Habe Geduld mit mir! Ich will dir\'s alles bezahlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Er wollte aber nicht, sondern ging hin und warf ihn ins Gefangnis, bis daü er bezahlete, was er schuldig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Da aber seine Mitknechte solches sahen, wurden sie sehr betrubt und kamen und brachten vor ihren Herrn alles, was sich begeben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Da forderte ihn sein Herr vor sich und sprach zu ihm: Du Schalksknecht! Alle diese Schuld habe ich dir erlassen, dieweil du mich batest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'solltest du denn dich nicht auch erbarmen uber deinen Mitknecht, wie ich mich uber dich erbarmet habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Und sein Herr ward zornig und uberantwortete ihn den Peinigern, bis daß er bezahlete alles, was er ihm schuldig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Also wird euch mein himmlischer Vater auch tun, so ihr nicht vergebet von eurem Herzen, ein jeglicher seinem Bruder seine Fehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Und es begab sich, da Jesus diese Rede vollendet hatte, erhub er sich aus Galilaa und kam in die Grenzen des judischen Landes jenseit des Jordans.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Und es folgete ihm viel Volks nach; und er heilete sie daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Da traten zu ihm die Pharisaer, versuchten ihn und sprachen zu ihm: Ist\'s auch recht, daü sich ein Mann scheide von seinem Weibe urn irgendeine Ursache?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Er antwortete aber und sprach zu ihnen: Habt ihr nicht gelesen, daü, der im Anfang den Menschen gemacht hat, der machte, dafi ein Mann und Weib sein sollte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'und sprach: Darum wird ein Mensch Vater und Mutter verlassen und an seinem Weibe hangen, und werden die zwei ein Fleisch sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'So sind sie nun nicht zwei, sondern ein Fleisch. Was nun Gott zusammengefuget hat, das soli der Mensch nicht scheiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Da sprachen sie: Warum hat denn Mose geboten; einen Scheidebrief zu geben und sich von ihr zu scheiden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Er sprach zu ihnen: Mose hat euch erlaubt, zu scheiden von euren Weibern, von eures Herzens Hartigkeit wegen; von Anbeginn aber ist\'s nicht also gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Ich sage aber euch: Wer sich von seinem Weibe scheidet (es sei denn urn der Hurerei willen) und freiet eine andere, der bricht die Ehe. Und wer die Abgeschiedene freiet, der bricht auch die Ehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Da sprachen die Junger zu ihm: Stehet die Sache eines Mannes mit seinem Weibe also, so ist\'s nicht gut ehelich werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Er sprach aber zu ihnen: Das Wort fasset nicht jedermann, sondern denen es gegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Denn es sind etliche verschnitten, die sind aus Mutterleibe also geboren, und sind etliche verschnitten, die von Menschen verschnitten sind, und sind etliche verschnitten, die sich selbst verschnitten haben urn des Himmelreichs willen. Wer es fassen mag.derfasse es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Da wurden Kindlein zu ihm gebracht, daß erdie Hande auf sie legte und betete. Die Junger aber fuhren sie an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Aber Jesus sprach: Lasset die Kindlein und wehret ihnen nicht, zu mirzu kommen; denn solcher ist das Himmelreich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Und legte die Hande auf sie und zog von dannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Und siehe, einertratzu ihm und sprach: Guter Meister, was soil ich Gutes tun, daü ich das ewige Leben moge haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Er aber sprach zu ihm: Was heiliest du mich gut? Niemand ist gut denn der einige Gott. Willst du aberzum Leben eingehen, so halte die Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Da sprach erzu ihm: Welche? Jesus aber sprach: Du sollst nicht toten; du sollst nicht ehebrechen; du sollst nicht stehlen; du sollst nicht falsch Zeugnis geben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'ehre Vater und Mutter, und: Du sollst deinen Nachsten lieben wie dich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Da sprach der Jungling zu ihm: Das habe ich alles gehalten von meiner Jugend auf; was fehlet mir noch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesus sprach zu ihm: Willst du vollkommen sein, so gehe hin, verkaufe, was du hast, und gib\'s den Armen, so wirst du einen Schatz im Himmel haben; und komm und folge mir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Da der Jungling das Wort horete, ging er betrubt von ihm; denn er hatte viel Guter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jesus aber sprach zu seinen Jungern: Wahrlich, ich sage euch, ein Reicher wird schwerlich ins Himmelreich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Und weiter sage ich euch: Es ist leichter, daß ein Kamel durch ein Nadelohr gehe, denn daß ein Reicher ins Reich Gottes komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Da das seine Junger horeten, entsetzten sie sich sehr und sprachen: Je, wer kann denn selig werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus aber sah sie an und sprach zu ihnen: Bei den Menschen ist\'s unmoglich, aber bei Gott sind alle Dinge moglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Da antwortete Petrus und sprach zu ihm: Siehe, wir haben alles verlassen und sind dir nachgefolget; was wird uns dafur?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jesus aber sprach zu ihnen: Wahrlich, ich sage euch, daß ihr, die ihr mir seid nachgefolget, in der Wiedergeburt, da des Menschen Sohn wird sitzen auf dem Stuhl seiner Herrlichkeit, werdet ihr auch sitzen auf zwolf Stuhlen und richten die zwolf Geschlechter Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Und wer verlafit Hauser Oder Bruder Oder Schwestern Oder Vater Oder Mutter Oder Weib Oder Kinder Oder Acker um meines Namens willen, der wird\'s hundertfaltig nehmen und das ewige Leben ererben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Aberviele, die da sind die Ersten, werden die Letzten, und die Letzten werden die Ersten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Das Himmelreich ist gleich einem Hausvater, der am Morgen ausging, Arbeiterzu mieten in seinen Weinberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Und da er mit den Arbeitern eins ward um einen Groschen zum Taglohn, sandte er sie in seinen Weinberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Und ging aus um die dritte Stunde und sah andere an dem Markt müßig stehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'und sprach zu ihnen: Gehet ihr auch hin in den Weinberg; ich will euch geben, was recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Und sie gingen hin. Abermal ging er aus um die sechste und neunte Stunde und tat gleich also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Um die elfte Stunde aber ging er aus und fand andere müßig stehen und sprach zu ihnen: Was stehet ihr hier den ganzen Tag müßig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Sie sprachen zu ihm: Es hat uns niemand gedinget. Er sprach zu ihnen: Gehet ihr auch hin in den Weinberg, und was recht sein wird, soil euch werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Da es nun Abend ward, sprach der Herr des Weinbergs zu seinem Schaffner: Rufe die Arbeiter und gib ihnen den Lohn und hebe an an den letzten bis zu den ersten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Da kamen, die um die elfte Stunde gedinget waren, und empfing ein jeglicher seinen Groschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Da aber die ersten kamen, meineten sie, sie würden mehr empfahen; und sie empfingen auch ein jeglicher seinen Groschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Und da sie den empfingen, murreten sie wider den Hausvater');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'und sprachen: Diese letzten haben nur eine Stunde gearbeitet, und du hast sie uns gleich gemacht, die wir des Tages Last und Hitze getragen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Erantwortete aber und sagte zu einem unter ihnen: Mein Freund, ich tue dir nicht unrecht. Bist du nicht mit mir eins worden um einen Groschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Nimm, was dein ist, und gehe hin! Ich will aber diesem letzten geben gleichwie dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Oder habe ich nicht Macht zu tun, was ich will, mit dem Meinen? Siehest du darum scheel, daß ich so gutig bin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Also werden die Letzten die Ersten, und die Ersten die Letzten sein. Denn viele sind berufen, aber wenige sind auserwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Und erzog hinauf gen Jerusalem und nahm zu sich die zwolf Jünger besonders auf dem Wege und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Siehe, wir ziehen hinauf gen Jerusalem, und des Menschen Sohn wird den Hohenpriestern und Schriftgelehrten überantwortet werden, und sie werden ihn verdammen zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Und werden ihn überantworten den Heiden, zu verspotten und zu geißeln und zu kreuzigen. Und am dritten Tage wird er wieder auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Da trat zu ihm die Mutter der Kinder des Zebedaus mit ihren Sohnen, fiel vor ihm nieder und bat etwas von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Und er sprach zu ihr: Was willst du? Sie sprach zu ihm: Laß diese meine zwei Sohne sitzen in deinem Reiche, einen zu deiner Rechten und den andern zu deiner Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Aber Jesus antwortete und sprach: Ihr wisset nicht, was ihr bittet. Konnet ihr den Kelch trinken, den ich trinken werde, und euch taufen lassen mit der Taufe, da ich mit getauft werde? Sie sprachen zu ihm: Jawohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Und er sprach zu ihnen: Meinen Kelch sollt ihr zwar trinken und mit der Taufe, da ich mit getauft werde, sollt ihr getauft werden, aber das Sitzen zu meiner Rechten und Linken zu geben, stehet mir nicht zu, sondern denen es bereitet ist von meinem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Da das die Zehn horeten, wurden sie unwillig uber die zwei Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Aber Jesus rief sie zu sich und sprach: Ihr wisset, daß die weltlichen Fursten herrschen, und die Oberherren haben Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'So soil es nicht sein unter euch, sondern so jemand will unter euch gewaltig sein, der sei euer Diener;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'und wer da will der Vornehmste sein, der sei euer Knecht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'gleichwie des Menschen Sohn ist nicht kommen, daß er ihm dienen lasse, sondern daß er diene und gebe sein Leben zu einer Erlosung fur viele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Und da sie von Jericho auszogen, folgte ihm viel Volks nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Und siehe, zwei Blinde saßen am Wege; und da sie horeten, daß Jesus voruberging, schrieen sie und sprachen: Ach Herr, du Sohn Davids, erbarme dich unser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Aber das Volk bedrauete sie, daß sie schweigen sollten. Aber sie schrieen viel mehr und sprachen: Ach Herr, du Sohn Davids, erbarme dich unser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Jesus aber stund stille und rief sie und sprach: Was wollt ihr, daß ich euch tun soil?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Sie sprachen zu ihm: Herr, daß unsere Augen aufgetan werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Und es jammerte Jesum und ruhrete ihre Augen an. Und alsbald wurden ihre Augen wieder sehend, und sie folgten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Da sie nun nahe an Jerusalem kamen gen Bethphage an den Olberg, sandte Jesus seiner Junger zwei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'und sprach zu ihnen: Gehet hin in den Flecken, der vor euch liegt, und bald werdet ihr eine Eselin finden angebunden und ein Füllen bei ihr. Loset sie auf und führet sie zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Und so euch jemand etwas wird sagen, so sprechet: Der Herr bedarf ihrer; sobald wird er sie euch lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Das geschah aber alles, auf daß erfullet würde, was gesagt ist durch den Propheten, der da spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Saget der Tochter Zion: Siehe, dein Konig kommt zu dir sanftmutig und reitet auf einem Esel und auf einem Fullen der lastbaren Eselin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Die Junger gingen hin und taten, wie ihnen Jesus befohlen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'und brachten die Eselin und das Fullen und legten ihre Kleider darauf und setzten ihn darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Aber viel Volks breitete die Kleider auf den Weg; die andern hieben Zweige von den Baumen und streueten sie auf den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Das Volk aber, das vorging und nachfolgete, schrie und sprach: Hosianna dem Sohn Davids! Gelobet sei, der da kommt in dem Namen des Herrn! Hosianna in der Hohe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Und als erzu Jerusalem einzog, erregte sich die ganze Stadt und sprach: Wer ist der?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Das Volk aber sprach: Das ist der Jesus, der Prophet von Nazareth aus Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Und Jesus ging zum Tempel Gottes hinein und trieb heraus alle Verkaufer und Kaufer im Tempel und stieft urn der Wechsler Tische und die Stühle der Taubenkramer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Und sprach zu ihnen: Es stehetgeschrieben: Mein Haus soil ein Bethaus heiften. Ihr aber habt eine Mordergrube daraus gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Und es gingen zu ihm Blinde und Lahme im Tempel, und er heilete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Da aber die Hohenpriester und Schriftgelehrten sahen die Wunder, die er tat, und die Kinder im Tempel schreien und sagen: Hosianna dem Sohn Davids! wurden sie entrüstet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'und sprachen zu ihm: Horst du auch, was diese sagen? Jesus sprach zu ihnen: Ja! Habt ihr nie gelesen: Aus dem Munde der Unmündigen und Sauglinge hast du Lob zugerichtet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Und er lieft sie da und ging zur Stadt hinaus gen Bethanien und blieb daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Als er aber des Morgens wieder in die Stadt ging, hungerte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Und ersah einen Feigenbaum an dem Wege und ging hinzu und fand nichts daran denn allein Blatter. Und sprach zu ihm: Nun wachse auf dir hinfort nimmermehr keine Frucht! Und der Feigenbaum verdorrete alsbald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Und da das die Junger sahen, verwunderten sie sich und sprachen: Wie ist der Feigenbaum sobald verdorret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus aber antwortete und sprach zu ihnen: Wahrlich, ich sage euch, so ihr Glauben habt und nicht zweifelt, so werdet ihr nicht allein solches mit dem Feigenbaum tun, sondern so ihr werdet sagen zu diesem Berge: Heb\' dich auf und wirf dich ins Meer! so wird\'s geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Und alles, was ihr bittet im Gebet, so ihr glaubet, so werdet ihr\'s empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Und als er in den Tempel kam, traten zu ihm, als er lehrete, die Hohenpriester und die Altesten im Volk und sprachen: Aus was fur Macht tust du das, und wer hat dir die Macht gegeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen; so ihr mir das saget, will ich euch auch sagen, aus was fur Macht ich das tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Woher war die Taufe Johannes? War sie vom Himmel Oder von den Menschen? Da gedachten sie bei sich selbst und sprachen: Sagen wir, sie sei vom Himmel gewesen, so wird er zu uns sagen: Warum glaubtet ihr ihm denn nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Sagen wir aber, sie sei von Menschen gewesen, so mussen wir uns vor dem Voik furchten; denn sie hielten alle Johannes fur einen Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Und sie antworteten Jesu und sprachen: Wir wissen\'s nicht. Da sprach er zu ihnen: So sage ich euch auch nicht, aus was fur Macht ich das tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Was dunket euch aber? Es hatte ein Mann zwei Sohne und ging zu dem ersten und sprach: Mein Sohn, gehe hin und arbeite heute in meinem Weinberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Er antwortete aber und sprach: Ich will\'s nicht tun. Danach reuete es ihn und ging hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Und erging zum andern und sprach gleich also. Er antwortete aber und sprach: Herr, ja! und ging nicht hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Welcher unter den zweien hat des Vaters Willen getan? Sie sprachen zu ihm: Der erste. Jesus sprach zu ihnen: Wahrlich, ich sage euch, die Zollner und Huren mogen wohl eher ins Himmelreich kommen denn ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Johannes kam zu euch und lehrete euch den rechten Weg, und ihr glaubtet ihm nicht; aber die Zollner und Huren glaubten ihm. Und ob ihr\'s wohl sahet, tatet ihr dennoch nicht Bufte, daß ihr ihm danach auch geglaubt hattet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Horet ein ander Gleichnis! Es war ein Hausvater, der pflanzete einen Weinberg und fuhrete einen Zaun darum und grub eine Kelter darinnen und bauete einen Turm und tat ihn den Weingartnern aus und zog uber Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Da nun herbeikam die Zeit der Fruchte, sandte er seine Knechte zu den Weingartnern, daß sie seine Fruchte empfingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Da nahmen die Weingartner seine Knechte; einen staupten sie, den andern toteten sie, den dritten steinigten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Abermal sandte er andere Knechte, mehr denn der ersten waren; und sie taten ihnen gleich also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Danach sandte erseinen Sohn zu ihnen und sprach: Sie werden sich vor meinem Sohn scheuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Da aber die Weingartner den Sohn sahen, sprachen sie untereinander: Das ist der Erbe; kommt, laßt uns ihn toten und sein Erbgut an uns bringen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Und sie nahmen ihn und stieüen ihn zum Weinberge hinaus und toteten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Wenn nun der Herr des Weinbergs kommen wird, was wird er diesen Weingartnern tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Sie sprachen zu ihm: Erwird die Bosewichte ubel umbringen und seinen Weinberg andern Weingartnern austun, die ihm die Fruchte zu rechter Zeitgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jesus sprach zu ihnen: Habt ihr nie gelesen in der Schrift: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein worden; von dem Herm ist das geschehen, und es ist wunderbarlich vor unsern Augen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Darum sage ich euch: Das Reich Gottes wird von euch genommen und den Heiden gegeben werden, die seine Fruchte bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Und werauf diesen Stein fallt, der wird zerschellen; auf welchen er aber fallt, den wird er zermalmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Und da die Hohenpriester und Pharisaer seine Gleichnisse horeten, vernahmen sie, daß er von ihnen redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Und sie trachteten danach, wie sie ihn griffen; aber sie furchteten sich vor dem Volk; denn es hielt ihn fur einen Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Und Jesus antwortete und redete abermal durch Gleichnisse zu ihnen und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Das Himmelreich ist gleich einem Konige, der seinem Sohne Hochzeit machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Und sandte seine Knechte aus, daß sie die Gaste zur Hochzeit riefen; und sie wollten nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Abermal sandte er andere Knechte aus und sprach: Saget den Gasten: Siehe, meine Mahlzeit habe ich bereitet, meine Ochsen und mein Mastvieh ist geschlachtet und alles bereit; kommet zur Hochzeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Aber sie verachteten das und gingen hin, einer auf seinen Acker, der andere zu seiner Hantierung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Etliche aber griffen seine Knechte, hohneten und toteten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Da das der Konig horete, ward erzornig und schickte seine Heere aus und brachte diese Morder urn und zundete ihre Stadt an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Da sprach erzu seinen Knechten: Die Hochzeit ist zwar bereit, aber die Gaste waren es nicht wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Darum gehet hin auf die Straiten und ladet zur Hochzeit, wen ihrfindet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Und die Knechte gingen aus auf die Straiten und brachten zusammen, wen sie fanden, Bose und Gute. Und die Tische wurden alle voll.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Da ging der Konig hinein, die Gaste zu besehen, und sah allda einen Menschen, der hatte kein hochzeitlich Kleid an,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'und sprach zu ihm: Freund, wie bistdu hereinkommen und hast doch kein hochzeitlich Kleid an? Er aber verstummte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Da sprach der Konig zu seinen Dienern: Bindet ihm Hande und Fülte und werfet ihn in die auiterste Finsternis hinaus; da wird sein Heulen und Zahneklappen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'denn viele sind berufen, aberwenige sind auserwahlet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Da gingen die Pharisaer hin und hielten einen Rat, wie sie ihn fingen in seiner Rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Und sandten zu ihm ihre Jünger samt des Herodes Dienern und sprachen: Meister, wirwissen, daß du wahrhaftig bist und lehrest den Weg Gottes recht und fragest nach niemand; denn du achtest nicht das Ansehen der Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Darum sage uns, was dunket dich? Ist\'s recht, daß man dem Kaiser Zins gebe, Oder nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Da nun Jesus merkte ihre Schalkheit, sprach er: Ihr Heuchler, was versuchet ihr mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Weisetmirdie Zinsmunze! Und sie reichten ihm einen Groschen dar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Und er sprach zu ihnen: Wes ist das Bild und die Uberschrift?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Sie sprachen zu ihm: Des Kaisers. Da sprach er zu ihnen: So gebet dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Da sie das horeten, verwunderten sie sich und lielien ihn und gingen davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'An demselbigen Tage traten zu ihm die Sadduzaer, die da halten, es sei kein Auferstehen, und fragten ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'und sprachen: Meister, Mose hat gesagt: So einer stirbt und hat nicht Kinder, so soli sein Bruder sein Weib freien und seinem Bruder Samen erwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Nun sind bei uns gewesen sieben Bruder. Der erste freiete und starb, und dieweil er nicht Samen hatte, lieli er sein Weib seinem Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Desselbengleichen der andere und derdritte bis an den siebenten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Zuletzt nach alien starb auch das Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Nun in der Auferstehung, wessen Weib wird sie sein unter den sieben? Sie haben sie ja alle gehabt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus aber antwortete und sprach zu ihnen: Ihr irret und wisset die Schrift nicht noch die Kraft Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'In der Auferstehung werden sie weder freien noch sich freien lassen, sondern sie sind gleich wie die Engel Gottes im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Habt ihr aber nicht gelesen von der Toten Auferstehung, das euch gesagt ist von Gott, da er spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs? Gott aber ist nicht ein Gott der Toten, sondern der Lebendigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Und da solches das Volk horete, entsetzten sie sich fiber seine Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Da aber die Pharisaer hdreten, dais er den Sadduzaern das Maul gestopft hatte, versammelten sie sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Und einer unter ihnen, ein Schriftgelehrter, versuchte ihn und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Meister, welches ist das vornehmste Gebot im Gesetz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jesus aber sprach zu ihm: Du sollst lieben Gott, deinen Herrn, von ganzem Herzen, von ganzer Seele und von ganzem Gernüt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Dies ist das vornehmste und grolite Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Das andere aber ist dem gleich: Du sollst deinen Nachsten lieben wie dich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'In diesen zweien Geboten hanget das ganze Gesetz und die Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Da nun die Pharisaer beieinander waren, fragte sie Jesus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'und sprach: Wie dunket euch urn Christus? Wes Sohn ist er? Sie sprachen: Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Er sprach zu ihnen: Wie nennet ihn denn David im Geist einen Herrn, da er sagt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Der Herr hat gesagt zu meinem Herrn: Setze dich zu meiner Rechten, bis daß ich lege deine Feinde zum Schemel deiner Fufie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'So nun David ihn einen Herrn nennet, wie ist er denn sein Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Und niemand konnte ihm ein Wort antworten, und durfte auch niemand von dem Tage an hinfort ihn fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Da redete Jesus zu dem Volk und zu seinen Jungern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'und sprach: Auf Moses Stuhl sitzen die Schriftgelehrten und Pharisaer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Alles nun, was sie euch sagen, daß ihr halten sollet, das haltet und tut\'s; aber nach ihren Werken sollt ihr nicht tun. Sie sagen\'s wohl und tun\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Sie binden aber schwere und unertragliche Burden und legen sie den Menschen auf den Hals; aber sie wollen dieselben nicht mit einem Finger regen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Alle ihre Werke aber tun sie, dafi sie von den Leuten gesehen werden. Sie machen ihre Denkzettel breit und die Saume an ihren Kleidern grofi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Sie sitzen gem obenan uber Tisch und in den Schulen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'und haben\'s gerne, daß sie gegrufiet werden auf dem Markt und von den Menschen Rabbi genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Aber ihr sollt euch nicht Rabbi nennen lassen; denn einer, ist euer Meister, Christus; ihr aber seid alle Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Und sollet niemand Vater heüien auf Erden; denn einer ist euer Vater, der im Himmel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'und ihr sollt euch nicht lassen Meister nennen; denn einer ist euer Meister, Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Der Grdßte unter euch soil euer Diener sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Denn wer sich selbst erhohet, der wird erniedriget, und wer sich selbst erniedriget, der wird erhdhet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr das Himmelreich zuschlieftt vor den Menschen! Ihr kommet nicht hinein, und die hinein wolien, lasset ihr nicht hineingehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr der Witwen Hauser fresset und wendet lange Gebete vor! Darum werdet ihr desto mehr Verdammnis empfahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr Land und Wasser umziehet, dafi ihr einen Judengenossen machet! Und wenn er\'s worden ist, macht ihr aus ihm ein Kind der Holle, zwiefaltig mehr, denn ihr seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Wehe euch, verblendete Leiter, die ihr saget: Wer da schworet bei dem Tempel, das ist nichts; wer aber schworet bei dem Golde am Tempel, der ist schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Ihr Narren und Blinden, was ist grofier, das Gold Oder der Tempel, der das Gold heiliget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Wer da schworet bei dem Altar; das ist nichts; wer aber schworet bei dem Opfer, das droben ist, der ist schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Ihr Narren und Blinden, was ist grofier, das Opfer Oder der Altar, der das Opfer heiliget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Darum, wer da schworet bei dem Altar, der schworet bei demselben und bei allem, was droben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Und wer da schworet bei dem Tempel, der schworet bei demselbigen und bei dem, derdrinnen wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Und wer da schworet bei dem Himmel, der schworet bei dem Stuhl Gottes und bei dem, der darauf sitzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr verzehntet die Minze, Till und Kümmel und lasset dahinten das Schwerste im Gesetz, namlich das Gericht, die Barmherzigkeit und den Glauben. Dies sollte man tun und jenes nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Ihr verblendete Leiter, die ihr Mücken seihet und Kamele verschlucket!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr die Becher und Schusseln auswendig reinlich haltet, inwendig aber ist\'s voll Raubes und Frames.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Du blinder Pharisaer, reinige zum ersten das Inwendige am Becher und Schüssel, auf daß auch das Auswendige rein werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihrgleich seid wie die ubertunchten Graber, welche auswendig hübsch scheinen, aber inwendig sind sie voller Totenbeine und alles Unflats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Also auch ihr; von aulien scheinet ihr vor den Menschen fromm, aber inwendig seid ihr voller Heuchelei und Untugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Wehe euch, Schriftgelehrte und Pharisaer, ihr Heuchler, die ihr der Propheten Graber bauet und schmucket der Gerechten Graber');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'und sprechet: Waren wir zu unserer Vater Zeiten gewesen, so wollten wir nicht teilhaftig sein mit ihnen an der Propheten Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'So gebt ihr zwar uber euch selbst Zeugnis, daß ihr Kinder seid derer die, die Propheten getotet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Wohlan, erfüllet auch ihr das Mali eurer Vater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Ihr Schlangen, ihr Otterngezuchte, wie wollt ihr der hollischen Verdammnis entrinnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Darum siehe, ich sende zu euch Propheten und Weise und Schriftgelehrte; und derselbigen werdet ihr etliche toten und kreuzigen und etliche werdet ihr geilieln in euren Schulen und werdet sie verfolgen von einer Stadt zu der andern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'auf daß uber euch komme alles das gerechte Blut, das vergossen ist auf Erden, von dem Blut an des gerechten Abels bis aufs Blut Zacharias, Barachias Sohn, welchen ihr getotet habt zwischen dem Tempel und Altar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Wahrlich, ich sage euch, daß solches alles wird uber dies Geschlecht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, die du totest die Propheten und steinigest, die zu dir gesandt sind, wie oft habe ich deine Kinder versammeln wollen, wie eine Henne versammelt ihre Kuchlein unter ihre Flügel; und ihr habt nicht gewollt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Siehe, euer Haus soil euch wüste gelassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Denn ich sage euch: Ihr werdet mich von jetzt an nicht sehen, bis ihr sprechet: Gelobet sei, der da kommt im Namen des Herrn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Und Jesus ging hinweg von dem Tempel, und seine Junger traten zu ihm, daß sie ihm zeigeten des Tempels Gebau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Jesus aber sprach zu ihnen: Sehet ihr nicht das alles? Wahrlich, ich sage euch, es wird hier nicht ein Stein auf dem andern bleiben, der nicht zerbrochen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Und als er auf dem Olberge sali, traten zu ihm seine Junger besonders und sprachen: Sage uns, wann wird das geschehen, und welches wird das Zeichen sein deiner Zukunft und der Weit Ende?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Jesus aber antwortete und sprach zu ihnen: Sehet zu, daß euch nicht jemand verfuhre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Denn es werden viele kommen unter meinem Namen und sagen: Ich bin Christus! und werden viele verfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Ihr werdet horen Kriege und Geschrei von Kriegen; sehet zu und erschrecket nicht! Das muli zum ersten alles geschehen; aber es ist noch nicht das Ende da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Denn es wird sich emporen ein Volk uber das andere und ein Konigreich uber das andere, und werden sein Pestilenz und teure Zeit und Erdbeben hin und wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Da wird sich allererst die Not anheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alsdann werden sie euch überantworten in Trubsal und werden euch toten. Und ihr musset gehasset werden urn meines Namens willen von alien Volkern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Dann werden sich viele argern und werden sich untereinander verraten und werden sich untereinander hassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Und es werden sich viel falsche Propheten erheben und werden viele verfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Und dieweil die Ungerechtigkeit wird überhandnehmen, wird die Liebe in vielen erkalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Weraber beharret bis ans Ende, der wird selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Und es wird geprediget werden das Evangelium vom Reich in der ganzen Welt zu einem Zeugnis uber alle Volker; und dann wird das Ende kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Wenn ihr nun sehen werdet den Greuel der Verwustung, davon gesagt ist durch den Propheten Daniel, daß er stehet an der heiligen Statte (wer das lieset, der merke daraufl),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'alsdann fliehe auf die Berge, wer im judischen Lande ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'und wer auf dem Dach ist, der steige nicht hernieder, etwas aus seinem Hause zu holen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'und wer auf dem Felde ist, der kehre nicht urn, seine Kleiderzu holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Wehe aber den Schwangern und Saugerinnen zu der Zeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Bittet aber, daß eure Flucht nicht geschehe im Winter Oder am Sabbat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Denn eswird alsdann eine grolie Trubsal sein, als nicht gewesen ist von Anfang der Welt bisher und als auch nicht werden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Und wo diese Tage nicht würden verkurzt, so wurde kein Mensch selig; aber urn der Auserwahlten willen werden die Tage verkurzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'So alsdann jemand zu euch wird sagen: Siehe, hier ist Christus Oder da! so sollt ihr\'s nicht glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Denn es werden falsche Christi und falsche Propheten aufstehen und grofie Zeichen und Wunder tun, daß verfuhret werden in den Irrtum (wo es moglich ware) auch die Auserwahlten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Siehe, ich hab\'s euch zuvor gesagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Darum wenn sie zu euch sagen werden: Siehe, er ist in der Wüste! so gehet nicht hinaus; siehe, er ist in der Kammer! so glaubt nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Denn gleichwie der Blitz ausgehet vom Aufgang und scheinet bis zum Niedergang, also wird auch sein die Zukunft des Menschensohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Wo aber ein Aas ist, da sammeln sich die Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Bald aber nach der Trubsal derselbigen Zeit werden Sonne und Mond den Schein verlieren, und die Sterne werden vom Himmel fallen, und die Krafte der Himmel werden sich bewegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Und alsdann wird erscheinen das Zeichen des Menschensohnes am Himmel. Und alsdann werden heulen alle Geschlechter auf Erden und werden sehen kommen des Menschen Sohn in den Wolken des Himmels mit grafter Kraft und Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Und er wird senden seine Engel mit hellen Posaunen, und sie werden sammeln seine Auserwahlten von den vier Winden, von einem Ende des Himmels zu dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'An dem Feigenbaum lernet ein Gleichnis. Wenn sein Zweig jetzt saftig wird und Blatter gewinnet, so wisset ihr, dafi der Sommer nahe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Also auch, wenn ihr das alles sehet, so wisset, daß es nahe vor der Tur ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Wahrlich, ich sage euch, dies Geschlecht wird nicht vergehen, bis daß dieses alles geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Himmel und Erde werden vergehen, aber meine Worte werden nicht vergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Von dem Tage aber und von der Stunde weift niemand, auch die Engel nicht im Himmel, sondern allein mein Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Gleich aber wie es zu der Zeit Noahs war, also wird auch sein die Zukunft des Menschensohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Denn gleichwie sie waren in den Tagen vor der Sintflut: sie alien, sie tranken, sie freieten und lieften sich freien bis an den Tag, da Noah zu der Arche einging,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'und sie achteten\'s nicht, bis die Sintflut kam und nahm sie alle dahin: also wird auch sein die Zukunft des Menschensohnes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Dann werden zwei auf dem Felde sein; einer wird angenommen und der andere wird verlassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Zwo werden mahlen auf der Mühle; eine wird angenommen und die andere wird verlassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Darum wachet! Denn ihr wisset nicht, welche Stunde euer Herr kommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Das sollt ihr aber wissen: Wenn ein Hausvater wuftte, welche Stunde der Dieb kommen wollte, so wurde er ja wachen und nicht in sein Haus brechen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Darum seid ihr auch bereit; denn des Menschen Sohn wird kommen zu einer Stunde, da ihr nicht meinet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Welcher ist aber nun ein treuer und kluger Knecht, den sein Herr gesetzt hat uber sein Gesinde, daß er ihnen zu rechter Zeit Speise gebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Selig ist der Knecht, wenn sein Herr kommt und findetihn also tun!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Wahrlich, ich sage euch, erwird ihn uber alle seine Gütersetzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'So aber jener, der bose Knecht, wird in seinem Herzen sagen: Mein Herr kommt noch lange nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'und fahet an zu schlagen seine Mitknechte, isset und trinket mit den Trunkenen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'so wird der Herr desselbigen Knechts kommen an dem Tage, des er sich nicht versiehet, und zu der Stunde, die er nicht meinet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'und wird ihn zerscheitern und wird ihm seinen Lohn geben mit den Heuchlern. Da wird sein Heulen und Zahneklappen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Dann wird das Himmelreich gleich sein zehn Jungfrauen, die ihre Lampen nahmen und gingen aus dem Brautigam entgegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Aber fünf unter ihnen waren toricht, und fünf waren klug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Die torichten nahmen ihre Lampen, aber sie nahmen nicht 01 mit sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Die klugen aber nahmen 01 in ihren Gefaften samt ihren Lampen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Da nun der Brautigam verzog, wurden sie alle schlafrig und entschliefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Zur Mitternacht aber ward ein Geschrei: Siehe, der Brautigam kommt; gehet aus ihm entgegen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Da stunden diese Jungfrauen alle auf und schmuckten ihre Lampen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Die torichten aber sprachen zu den klugen: Gebt uns von eurem Ole; denn unsere Lampen verloschen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Da antworteten die klugen und sprachen: Nicht also, auf daß nicht uns und euch gebreche. Gehet aber hin zu den Kramern und kaufet fur euch selbst!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Und da sie hingingen zu kaufen, kam der Brautigam; und welche bereit waren, gingen mit ihm hinein zur Hochzeit. Und die Tur ward verschlossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Zuletzt kamen auch die andern Jungfrauen und sprachen: Herr, Herr, tu uns auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Er antwortete aber und sprach: Wahrlich, ich sage euch, ich kenne euer nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Darum wachet! Denn ihr wisset weder Tag noch Stunde, in welcher des Menschen Sohn kommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Gleichwie ein Mensch, der uber Land zog, rief seinen Knechten und tat ihnen seine Guter ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Und einem gab er funf Zentner, dem andern zwei, dem dritten einen, einem jeden nach seinem Vermogen, und zog bald hinweg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Da ging der hin, der funf Zentner empfangen hatte, und handelte mitdenselbigen und gewann andere funf Zentner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Desgleichen auch, der zwei Zentner empfangen hatte, gewann auch zwei andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Der aber einen empfangen hatte, ging hin und machte eine Grube in die Erde und verbarg seines Herrn Geld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Uber eine lange Zeit kam der Herr dieser Knechte und hielt Rechenschaft mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Da trat herzu, der fünf Zentner empfangen hatte, und legte andere funf Zentner dar und sprach: Herr, du hast mir funf Zentner getan; siehe da, ich habe damit andere funf Zentner gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Da sprach sein Herr zu ihm: Ei, du frommer und getreuer Knecht, du bist uber wenigem getreu gewesen; ich will dich uber viel setzen. Gehe ein zu deines Herrn Freude!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Da trat auch herzu, der zwei Zentner empfangen hatte, und sprach: Herr, du hast mir zwei Zentner getan; siehe da, ich habe mit denselben zwei andere gewonnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Sein Herr sprach zu ihm: Ei, du frommer und getreuer Knecht, du bist uber wenigem getreu gewesen; ich will dich uber viel setzen. Gehe ein zu deines Herrn Freude!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Da trat auch herzu, der einen Zentner empfangen hatte, und sprach: Herr, ich wuftte, daß du ein harter Mann bist: du schneidest, wo du nicht gesaet hast, und sammelst, da du nicht gestreuet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Und furchtete mich, ging hin und verbarg deinen Zentner in die Erde. Siehe, da hast du das Deine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Sein Herr aber antwortete und sprach zu ihm: Du Schalk und fauler Knecht! Wufttest du, daß ich schneide, da ich nicht gesaet habe, und sammle, da ich nicht gestreuet habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'so solltest du mein Geld zu den Wechslern getan haben, und wenn ich kommen ware, hatte ich das Meine zu mir genommen mit Wucher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Darum nehmet von ihm den Zentner und gebet\'s dem, der zehn Zentner hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Denn wer da hat, dem wird gegeben werden, und wird die Fulle haben; wer aber nicht hat, dem wird auch, was er hat, genommen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Und den unnützen Knecht werft in die aufterste Finsternis hinaus; da wird sein Heulen und Zahneklappen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Wenn aber des Menschen Sohn kommen wird in seiner Herrlichkeit und alle heiligen Engel mit ihm, dann wird er sitzen auf dem Stuhl seiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Und werden vor ihm alle Volker versammelt werden. Und erwird sie voneinanderscheiden, gleich als ein Hirte die Schafe von den Bocken scheidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Und wird die Schafe zu seiner Rechten stellen und die Bocke zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Da wird denn der Konig sagen zu denen zu seiner Rechten: Kommt her, ihr Gesegneten meines Vaters, ererbet das Reich, das euch bereitet ist von Anbeginn der Welt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Denn ich bin hungrig gewesen, und ihr habt mich gespeiset. Ich bin durstig gewesen, und ihr habt mich getranket. Ich bin ein Gast gewesen, und ihr habt mich beherberget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Ich bin nackend gewesen, und ihr habt mich bekleidet. Ich bin krank gewesen, und ihr habt mich besuchet. Ich bin gefangen gewesen, und ihr seid zu mir kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Dann werden ihm die Gerechten antworten und sagen: Herr, wann haben wir dich hungrig gesehen und haben dich gespeiset, Oder durstig und haben dich getranket?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Wann haben wir dich einen Gast gesehen und beherberget, Oder nackend und haben dich bekleidet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Wann haben wir dich krank Oder gefangen gesehen und sind zu dir kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Und der Konig wird antworten und sagen zu ihnen: Wahrlich, ich sage euch: Was ihr getan habt einem unterdiesen meinen geringsten Brudern, das habt ihr mir getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Dann wird er auch sagen zu denen zur Linken: Gehet hin von mir, ihr Verfluchten, in das ewige Feuer, das bereitet ist dem Teufel und seinen Engeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Ich bin hungrig gewesen, und ihr habt mich nicht gespeiset. Ich bin durstig gewesen, und ihr habt mich nicht getranket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Ich bin ein Gast gewesen, und ihr habt mich nicht beherberget. Ich bin nackend gewesen, und ihr habt mich nicht bekleidet. Ich bin krank und gefangen gewesen, und ihr habt mich nicht besuchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Da werden sie ihm auch antworten und sagen: Herr, wann haben wir dich gesehen hungrig Oder durstig Oder einen Gast Oder nackend Oder krank Oder gefangen und haben dir nicht gedienet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Dann wird er ihnen antworten und sagen: Wahrlich, ich sage euch: Was ihr nicht getan habt einem unter diesen Geringsten, das habt ihr mir auch nicht getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Und sie werden in die ewige Pein gehen, aber die Gerechten in das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Und es begab sich, da Jesus alle diese Reden vollendet hatte, sprach er zu seinen Jungern:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Ihrwisset, daü nach zwei Tagen Ostern wird, und des Menschen Sohn wird uberantwortet werden, daß er gekreuziget werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Da versammelten sich die Hohenpriester und Schriftgelehrten und die Altesten im Volk in dem Palast des Hohenpriesters, der da hieft Kaiphas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'und hielten Rat, wie sie Jesum mit List griffen und toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Sie sprachen aber: Ja nicht auf das Fest, auf daß nicht ein Aufruhr werde im Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Da nun Jesus war zu Bethanien im Hause Simons des Aussatzigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'trat zu ihm ein Weib, das hatte ein Glas mit kostlichem Wasser und goft es auf sein Haupt, da er zu Tisch saft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Da das seine Junger sahen, wurden sie unwillig und sprachen: Wozu dient dieser Unrat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Dieses Wasser hatte mogen teuer verkauft und den Armen gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Da das Jesus merkete, sprach erzu ihnen: Was bekummert ihr das Weib? Sie hat ein gut Werk an mirgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Ihr habt allezeit Arme bei euch; mich aber habt ihr nicht allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Dafi sie dies Wasser hat auf meinen Leib gegossen, hat sie getan, daß man mich begraben wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Wahrlich, ich sage euch, wo dies Evangelium geprediget wird in der ganzen Weit, da wird man auch sagen zu ihrem Gedachtnis, was sie getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Da ging hin der Zwolfen einer, mit Namen Judas Ischariot, zu den Hohenpriestern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'und sprach: Was wolltihr mirgeben? Ich will ihn euch verraten. Und sie boten ihm dreißig Silberlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Und von dem an suchte er Gelegenheit, daß er ihn verriete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Aber am ersten Tage dersüßen Brote traten die Jünger zu Jesu und sprachen zu ihm: Wo willst du, daß wir dir bereiten, das Osterlamm zu essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Er sprach: Gehet hin in die Stadt zu einem und sprechet zu ihm: Der Meister laßt dir sagen: Meine Zeit ist hier; ich will bei dir die Ostern halten mit meinen Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Und die Junger taten, wie ihnen Jesus befohlen hatte, und bereiteten das Osterlamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Und am Abend setzte er sich zu Tische mit den Zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Und da sie alien, sprach er: Wahrlich, ich sage euch, einer unter euch wird mich verraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Und sie wurden sehr betrubt und huben an, ein jeglicher unter ihnen, und sagten zu ihm: Herr, bin ich\'s?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Er antwortete und sprach: Der mit der Hand mit mir in die Schüssel tauchet, der wird mich verraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Des Menschen Sohn gehet zwardahin, wie von ihm geschrieben stehet; doch wehe dem Menschen, durch welchen des Menschen Sohn verraten wird! Es ware ihm besser, daß derselbige Mensch noch nie geboren ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Da antwortete Judas, der ihn verriet, und sprach: Bin ich\'s, Rabbi? Er sprach zu ihm: Du sagst es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Da sie aber alien, nahm Jesus das Brot, dankete und brach\'s und gab\'s den Jungern und sprach: Nehmet, esset; das ist mein Leib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Und er nahm den Kelch und dankete, gab ihnen den und sprach: Trinket alle daraus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Das ist mein Blut des Neuen Testaments, welches vergossen wird fur viele zur Vergebung der Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ich sage euch: Ich werde von nun an nicht mehr von diesem Gewachs des Weinstocks trinken bis an den Tag, da ich\'s neu trinken werde mit euch in meines Vaters Reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Und, da sie den Lobgesang gesprochen hatten, gingen sie hinaus an den Olberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Da sprach Jesus zu ihnen: In dieser Nacht werdet ihr euch alle argern an mir; denn es stehet geschrieben: Ich werde den Hirten schlagen, und die Schafe der Herde werden sich zerstreuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Wenn ich aber auferstehe, will ich vor euch hingehen in Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Petrus aber antwortete und sprach zu ihm: Wenn sie auch alle sich an dir argerten, so will ich doch mich nimmermehr argern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus sprach zu ihm: Wahrlich, ich sage dir, in dieser Nacht, ehe der Hahn krahet, wirst du mich dreimal verleugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Petrus sprach zu ihm: Und wenn ich mit dir sterben mußte, so will ich dich nicht verleugnen. Desgleichen sagten auch alle Jünger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Da kam Jesus mit ihnen zu einem Hof, der hieli Gethsemane, und sprach zu seinen Jungern: Setzet euch hier, bis daß ich dorthin gehe und bete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Und nahm zu sich Petrus und die zwei Sohne des Zebedaus und fing an zu trauern und zu zagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Da sprach Jesus zu ihnen: Meine Seele ist betrubt bis an den Tod; bleibet hier und wachet mit mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Und ging hin ein wenig, fiel nieder auf sein Angesicht und betete und sprach: Mein Vater, ist\'s moglich, so gehe dieser Kelch von mir; doch nicht, wie ich will, sondern wie du willst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Und er kam zu seinen Jungern und fand sie schlafend und sprach zu Petrus: Konnet ihr denn nicht eine Stunde mit mirwachen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Wachet und betet, daß ihr nicht in Anfechtung fallet. Der Geist ist willig; aber das Fleisch ist schwach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Zum andernmal ging erwieder hin, betete und sprach: Mein Vater, ist\'s nicht moglich, daß dieser Kelch von mir gehe, ich trinke ihn denn; so geschehe dein Wille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Und er kam und fand sie abermal schlafend, und ihre Augen waren voll Schlafs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Und er ließ sie und ging abermal hin und betete zum drittenmal und redete dieselbigen Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Da kam erzu seinen Jungern und sprach zu ihnen: Ach, wollt ihr nun schlafen und ruhen? Siehe, die Stunde ist hier, daß des Menschen Sohn in der Sunder Hande uberantwortet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Stehet auf, laßt uns gehen! Siehe, er ist da, der mich verrat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Und als er noch redete, siehe, da kam Judas, der Zwolfen einer, und mit ihm eine große Schar mit Schwertern und mit Stangen von den Hohenpriestern und Altesten des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Und der Verrater hatte ihnen ein Zeichen gegeben und gesagt: Welchen ich küssen werde, der ist\'s; den greifet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Und alsbald trat er zu Jesu und sprach: Gegrußet seiest du, Rabbi! und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus aber sprach zu ihm: Mein Freund, warum bist du kommen? Da traten sie hinzu und legten die Hande an Jesum und griffen ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Und siehe, einer aus denen, die mit Jesu waren, reckte die Hand aus und zog sein Schwert aus und schlug des Hohenpriesters Knecht und hieb ihm ein Ohrab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Da sprach Jesus zu ihm: Stecke dein Schwert an seinen Ort; denn wer das Schwert nimmt, der soil durchs Schwert umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Oder meinest du, daß ich nicht konnte meinen Vater bitten, daß er mir zuschickte mehr denn zwolf Legionen Engel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Wie würde aber die Schrift erfullet? Es mull also gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Zu der Stunde sprach Jesus zu den Scharen: Ihr seid ausgegangen als zu einem Morder mit Schwertern und mit Stangen, mich zu fahen; bin ich doch taglich gesessen bei euch und habe gelehret im Tempel, und ihr habt mich nicht gegriffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Aber das ist alles geschehen, daß erfullet würden die Schriften der Propheten. Da verlielien ihn alle Junger und flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Die aber Jesum gegriffen hatten, fuhreten ihn zu dem Hohenpriester Kaiphas, dahin die Schriftgelehrten und Altesten sich versammelt hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Petrus aber folgte ihm nach von feme bis in den Palast des Hohenpriesters und ging hinein und setzte sich zu den Knechten, auf daß er sahe, wo es hinaus wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Die Hohenpriester aber und Altesten und der ganze Rat suchten falsch Zeugnis wider Jesum, auf daß sie ihn toteten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'und fanden keins. Und wiewohl viel falsche Zeugen herzutraten, fanden sie doch keins. Zuletzt traten herzu zwei falsche Zeugen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'und sprachen: Er hat gesagt: Ich kann den Tempel Gottes abbrechen und in dreien Tagen denselben bauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Und der Hohepriester stund auf und sprach zu ihm: Antwortest du nichts zu dem, was diese wider dich zeugen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Aber Jesus schwieg stille. Und der Hohepriester antwortete und sprach zu ihm: Ich beschwore dich bei dem lebendigen Gott, daß du uns sagest, ob du seiest Christus, der Sohn Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesus sprach zu ihm: Du sagst es. Doch sage ich euch: Von nun an wird\'s geschehen, daß ihr sehen werdet des Menschen Sohn sitzen zur Rechten der Kraft und kommen in den Wolken des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Da zerrili der Hohepriester seine Kleider und sprach: Er hat Gott gelastert; was bedurfen wirweiter Zeugnis? Siehe, jetzt habt ihr seine Gotteslasterung gehort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Was dünkt euch? Sie antworteten und sprachen: Er ist des Todes schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Da speieten sie aus in sein Angesicht und schlugen ihn mit Fausten. Etliche aber schlugen ihn ins Angesicht');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'und sprachen: Weissage uns, Christe, wer ist\'s, der dich schlug?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Petrus aber sali draulien im Palast. Und es trat zu ihm eine Magd und sprach: Und du warest auch mit dem Jesu aus Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Er leugnete aber vor ihnen alien und sprach: Ich weili nicht, was du sagest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Als er aber zur Tür hinausging, sah ihn eine andere und sprach zu denen, die da waren: Dieser war auch mit dem Jesu von Nazareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Und er leugnete abermal und schwur dazu: Ich kenne den Menschen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Und fiber eine kleine Weile traten hinzu, die da stunden, und sprachen zu Petrus: Wahrlich, du bist auch einer von denen; denn deine Sprache verrat dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Da hub er an sich zu verfluchen und zu schworen: Ich kenne den Menschen nicht. Und alsbald krahete der Hahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Da dachte Petrus an die Worte Jesu, da er zu ihm sagte: Ehe der Hahn krahen wird, wirst du mich dreimal verleugnen. Und ging hinaus und weinte bitterlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Des Morgens aber hielten alle Hohenpriester und die Altesten des Volks einen Rat fiber Jesum, daß sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Und banden ihn, fuhreten ihn hin und überantworteten ihn dem Landpfleger Pontius Pilatus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Da das sah Judas, der ihn verraten hatte, daß er verdammt war zum Tode, gereuete es ihn und brachte herwieder die dreilüg Silberlinge den Hohenpriestern und den Altesten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'und sprach: Ich habe fibel getan, daß ich unschuldig Blut verraten habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Sie sprachen: Was gehet uns das an? Da siehe du zu! Und er warf die Silberlinge in den Tempel, hub sich davon, ging hin und erhangte sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Aber die Hohenpriester nahmen die Silberlinge und sprachen: Es taugt nicht, daß wir sie in den Gotteskasten legen; denn es ist Blutgeld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Sie hielten aber einen Rat und kauften einen Topfersacker darum zum Begrabnis der Pilger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Daher ist derselbige Acker genannt der Blutacker bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Da ist erfullet, was gesagt ist durch den Propheten Jeremia, da er spricht: Sie haben genommen dreilüg Silberlinge, damit bezahletward der Verkaufte, welchen sie kauften von den Kindern Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'und haben sie gegeben urn einen Topfersacker, als mir der Herr befohlen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jesus aber stund vor dem Landpfleger. Und der Landpfleger fragte ihn und sprach: Bist du der Juden Konig? Jesus aber sprach zu ihm: Du sagst es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Und da er verklagt ward von den Hohenpriestern und Altesten, antwortete er nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Da sprach Pilatus zu ihm: Horest du nicht, wie hart sie dich verklagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Und er antwortete ihm nicht auf ein Wort, also daß sich auch der Landpfleger sehr verwunderte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Auf das Fest aber hatte der Landpfleger die Gewohnheit, dem Volk einen Gefangenen loszugeben, welchen sie wollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Er hatte aber zu der Zeit einen Gefangenen, einen sonderlichen vor andern, der hiefi Barabbas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Und da sie versammelt waren, sprach Pilatus zu ihnen: Welchen wollt ihr, dafi ich euch losgebe, Barabbas Oder Jesus, von dem gesagt wird, er sei Christus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Denn erwulltewohl, daßsie ihn aus Neid uberantwortet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Und da er auf dem Richterstuhl sali, schickte sein Weib zu ihm und lieli ihm sagen: Habe du nichts zu schaffen mit diesem Gerechten; ich habe heute viel erlitten im Traum von seinetwegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Aber die Hohenpriester und die Altesten uberredeten das Volk, dafi sie urn Barabbas bitten sollten und Jesum umbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Da antwortete nun der Landpfleger und sprach zu ihnen: Welchen wollt ihr unter diesen zweien, den ich euch soil losgeben? Sie sprachen: Barabbas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilatus sprach zu ihnen: Was soil ich denn machen mit Jesu, von dem gesagt wird, er sei Christus? Sie sprachen alle: Laß, ihn kreuzigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Der Landpfleger sagte: Was hat er denn Ubels getan? Sie schrieen aber noch mehr und sprachen: Laß ihn kreuzigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Da aber Pilatus sah, daß, er nichts schaffete, sondern daß ein viel großer Getummel ward, nahm er Wasser und wusch die Hande vor dem Volk und sprach: Ich bin unschuldig an dem Blut dieses Gerechten; sehet ihrzu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Da antwortete das ganze Volk und sprach: Sein Blut komme uber uns und uber unsere Kinder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Da gab er ihnen Barabbas los; aber Jesum ließ er geißeln und uberantwortete ihn, daß er gekreuziget wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Da nahmen die Kriegsknechte des Landpflegers Jesum zu sich in das Richthaus und sammelten uber ihn die ganze Schar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Und zogen ihn aus und legten ihm einen Purpurmantel an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'und flochten eine Dornenkrone und setzten sie auf sein Haupt und ein Rohr in seine rechte Hand und beugten die Kniee vor ihm und verspotteten ihn und sprachen: Gegrußet seiest du, der Juden Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Und speieten ihn an und nahmen das Rohr und schlugen damit sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Und da sie ihn verspottet hatten, zogen sie ihm den Mantel aus und zogen ihm seine Kleider an und führeten ihn hin, daß sie ihn kreuzigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Und indem sie hinausgingen, fanden sie einen Menschen von Kyrene mit Namen Simon; den zwangen sie, daß er ihm sein Kreuz trug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Und da sie an die Statte kamen mit Namen Golgatha, das ist verdeutschet Schadelstatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'gaben sie ihm Essig zu trinken, mit Galle vermischt; und da el\'s schmeckte, wollte er nicht trinken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Da sie ihn aber gekreuziget hatten, teilten sie seine Kleider und warfen das Los darum, auf daß erfullet wurde, was gesagt ist durch den Propheten: Sie haben meine Kleider unter sich geteilet und uber mein Gewand haben sie das Los geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Und sie saßen allda und huteten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Und oben zu seinen Haupten hefteten sie die Ursache seines Todes beschrieben, namlich: Dies ist Jesus, der Juden Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Und da wurden zwei Morder mit ihm gekreuziget, einer zur Rechten und einer zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Die aber vorubergingen, lasterten ihn und schuttelten ihre Kopfe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'und sprachen: Der du den Tempel Gottes zerbrichst und bauest ihn in dreien Tagen, hilf dir selber! Bist du Gottes Sohn, so steig herab vom Kreuz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Desgleichen auch die Hohenpriester spotteten sein samt den Schriftgelehrten und Altesten und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Andern hat er geholfen und kann sich selber nicht helfen. Ist er der Konig Israels, so steige er nun vom Kreuz, so wollen wir ihm glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Er hat Gott vertraut, der erlose ihn nun, lustet’s ihn; denn er hat gesagt: Ich bin Gottes Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Desgleichen schmaheten ihn auch die Morder, die mit ihm gekreuziget waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Und von der sechsten Stunde an ward eine Finsternis uber das ganze Land bis zu der neunten Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Und urn die neunte Stunde schrie Jesus laut und sprach: Eli, Eli, lama asabthani? das ist: Mein Gott, mein Gott, warum hast du mich verlassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Etliche aber, die da stunden, da sie das horeten, sprachen sie: Der ruft den Elia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Und bald lief einer unter ihnen, nahm einen Schwamm und füllete ihn mit Essig und steckte ihn auf ein Rohr und trankte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Die andern aber sprachen: Halt, laß sehen, ob Elia komme und ihm helfe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Aber Jesus schrie abermal laut und verschied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Und siehe da, der Vorhang im Tempel zerriß in zwei Stucke, von oben an bis unten aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Und die Erde erbebete, und die Felsen zerrissen, und die Graber taten sich auf, und stunden auf viel Leiber der Heiligen, die da schliefen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'und gingen aus den Grabern nach seiner Auferstehung und kamen in die Heilige Stadt und erschienen vielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Aber der Hauptmann und die bei ihm waren und bewahreten Jesum, da sie sahen das Erdbeben und was da geschah, erschraken sie sehr und sprachen: Wahrlich, dieser ist Gottes Sohn gewesen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Und es waren viel Weiber da, die von feme zusahen, die da Jesu waren nachgefolget aus Galilaa und hatten ihm gedienet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'unter welchen war Maria Magdalena und Maria, die Mutter des Jakobus und Joses, und die Mutter der Kinder des Zebedaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Am Abend aber kam ein reicher Mann von Arimathia, der hieli Joseph, welcher auch ein Junger Jesu war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Der ging zu Pilatus und bat ihn urn den Leib Jesu. Da befahl Pilatus, man sollte ihm ihn geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Und Joseph nahm den Leib und wickelte ihn in eine reine Leinwand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'Und legte ihn in sein eigen neu Grab, welches er hatte lassen in einen Felsen hauen, und walzte einen graven Stein vor die Tur des Grabes und ging davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Es war aber allda Maria Magdalena und die andere Maria, die setzten sich gegen das Grab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Des andern Tages, der da folgt nach dem Rusttag, kamen die Hohenpriester und Pharisaer samtlich zu Pilatus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'und sprachen: Herr, wir haben gedacht, daß dieser Verfuhrer sprach, da er noch lebte: Ich will nach dreien Tagen auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Darum befiehl, daß man das Grab verwahre bis an den dritten Tag, auf daß nicht seine Junger kommen und stehlen ihn und sagen zum Volk: Er ist auferstanden von den Toten, und werde der letzte Betrug arger denn der erste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatus sprach zu ihnen: Da habt ihr die Hitter; gehet hin und verwahret, wie ihr wisset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Sie gingen hin und verwahreten das Grab mit Hutern und versiegelten den Stein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Am Abend aber des Sabbats, welcher anbricht am Morgen des ersten Feiertages der Sabbate, kam Maria Magdalena und die andere Maria, das Grab zu besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Und siehe, es geschah ein graft Erdbeben. Denn der Engel des Herm kam vom Himmel herab, trat hinzu und walzte den Stein von der Tur und setzte sich darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Und seine Gestalt war wie der Blitz und sein Kleid weift wie der Schnee.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Die Hüter aber erschraken vor Furcht und wurden, als waren sie tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Aber der Engel antwortete und sprach zu den Weibern: Furchtet euch nicht; ich weift, daß ihr Jesum, den Gekreuzigten, suchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Er ist nicht hier; er ist auferstanden, wie er gesagt hat. Kommt her und sehet die Statte, da der Herrgelegen hat!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Und gehet eilend hin und saget es seinen Jungern, daß er auferstanden sei von den Toten. Und siehe, erwird vor euch hingehen nach Galilaa; da werdet ihr ihn sehen. Siehe, ich hab\'s euch gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Und sie gingen eilend zum Grabe hinaus mit Furcht und grafter Freude und liefen, daß sie es seinen Jungern verkündigten. Und da sie gingen, seinen Jungern zu verkundigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'siehe, da begegnete ihnen Jesus und sprach: Seid gegrüftet! Und sie traten zu ihm und griffen an seine Füfte und fielen vor ihm nieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Da sprach Jesus zu ihnen: Furchtet euch nicht! Gehet hin und verkundiget es meinen Brudern, daß sie gehen nach Galilaa; daselbst werden sie mich sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Da sie aber hingingen, siehe, da kamen etliche von den Hutern in die Stadt und verkündigten den Hohenpriestern alles, was geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Und sie kamen zusammen mit den Altesten und hielten einen Rat und gaben den Kriegsknechten Gelds genug');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'und sprachen: Saget, seine Junger kamen des Nachts und stahlen ihn, dieweil wirschliefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Und wo es würde auskommen bei dem Landpfleger, wollen wir ihn stillen und schaffen, daß ihr sicher seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Und sie nahmen das Geld und taten, wie sie gelehret waren. Solches ist eine gemeine Rede worden bei den Juden bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Aber die elf Junger gingen nach Galilaa auf einen Berg, dahin Jesus sie beschieden hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Und da sie ihn sahen, fielen sie vor ihm nieder; etliche aber zweifelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Und Jesus trat zu ihnen, redete mit ihnen und sprach: Mir ist gegeben alle Gewalt im Himmel und auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Darum gehet hin und lehret alle Volker und taufet sie im Namen des Vaters und des Sohnes und des Heiligen Geistes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Und lehret sie halten alles, was ich euch befohlen habe! Und siehe, ich bin bei euch alle Tage bis an der Welt Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Dies ist der Anfang des Evangeliums von Jesus Christus, dem Sohn Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'wie geschrieben stehet in den Propheten: Siehe, ich sende meinen Engel vor dir her, der da bereite deinen Weg vor dir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Es ist eine Stimme eines Predigers in der Wüste: Bereitet den Weg des Herrn, machet seine Steige richtig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Johannes, der war in der Wüste, taufte und predigte von der Taufe der Bufte zur Vergebung der Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Und es ging zu ihm hinaus das ganze judische Land und die von Jerusalem und lieften sich alle von ihm tauten im Jordan und bekannten ihre Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Johannes aber war bekleidet mit Kamelhaaren und miteinem ledernen Gürtel um seine Lenden und aft Heuschrecken und wilden Honig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Und predigte und sprach: Es kommt einer nach mir, der ist starker denn ich, dem ich nicht genugsam bin, daß ich mich vor ihm bücke und die Riemen seiner Schuhe auflose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ich taufe euch mit Wasser; aber er wird euch mit dem Heiligen Geist tauten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Und es begab sich zu derselbigen Zeit, daß Jesus aus Galilaa von Nazareth kam und lieft sich tauten von Johannes im Jordan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Und alsbald stieg er aus dem Wasser und sah, daß sich der Himmel auftat, und den Geist gleichwie eine Taube herab kommen auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Und da geschah eine Stimme vom Himmel: Du bist mein lieber Sohn, an dem ich Wohlgefallen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Und bald trieb ihn der Geist in die Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Und war allda in der Wüste vierzig Tage und ward versucht von dem Satan und war bei den Tieren, und die Engel dieneten ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Nachdem aber Johannes überantwortet ward, kam Jesus nach Galilaa und predigte das Evangelium vom Reich Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'und sprach: Die Zeit ist erfüllet, und das Reich Gottes ist herbeikommen. Tut Bufte und glaubt an das Evangelium!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Da er aber an dem Galilaischen Meerging, sah er Simon und Andreas, seinen Bruder, daß sie ihre Netze ins Meer warfen; denn sie waren Fischer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Und Jesus sprach zu ihnen: Folget mir nach! Ich will euch zu Menschenfischern machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Alsbald verlieften sie ihre Netze und folgeten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Und da ervon dannen ein wenig furbaft ging, sah er Jakobus, den Sohn des Zebedaus, und Johannes, seinen Bruder, daß sie die Netze im Schiff flickten; und bald rief er sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Und sie lieften ihren Vater Zebedaus im Schiff mit den Tagelohnern und folgeten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Und siegingen gen Kapernaum; und bald an den Sabbaten ging er in die Schule und lehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Und sie entsetzten sich über seine Lehre; denn er lehrete gewaltiglich und nicht wie die Schriftgelehrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Und es war in ihrer Schule ein Mensch, besessen mit einem unsaubern Geist, der schrie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'und sprach: Halt, was haben wir mit dir zu schaffen, Jesus von Nazareth? Du bist kommen, uns zu verderben. Ich weift, wer du bist, der Heilige Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Und Jesus bedrauete ihn und sprach: Verstumme und fahre aus von ihm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Und der unsaubere Geist rift ihn und schrie laut und fuhr aus von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Und sie entsetzten sich alle, also daß sie untereinander sich befragten und sprachen: Was ist das? Was ist das fur eine neue Lehre? Er gebeut mit Gewalt den unsaubern Geistern, und sie gehorchen ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Und sein Gerucht erscholl bald umher in die Grenze Galilaas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Und sie gingen bald aus der Schule und kamen in das Haus des Simon und Andreas mit Jakobus und Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Und die Schwieger Simons lag und hatte das Fieber; und alsbald sagten sie ihm von ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Und er trat zu ihr und richtete sie auf und hielt sie bei der Hand; und das Fieber verlieft sie bald, und sie dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Am Abend aber, da die Sonne untergegangen war, brachten sie zu ihm allerlei Kranke und Besessene.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Und die ganze Stadt versammelte sich vor der Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Und er half vielen Kranken, die mit mancherlei Seuchen beladen waren, und trieb viele Teufel aus und lieft die Teufel nicht reden; denn sie kannten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Und des Morgens vor Tag stund er auf und ging hinaus. Und Jesus ging in eine wüste Statte und betete daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Und Petrus mitdenen, die bei ihm waren, eileten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Und da sie ihn fanden, sprachen sie zu ihm: Jedermann suchet dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Und er sprach zu ihnen: Laftt uns in die nachsten Stadte gehen, daß ich daselbst auch predige; denn dazu bin ich kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Und er predigte in ihren Schulen in ganz Galilaa und trieb die Teufel aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Und es kam zu ihm ein Aussatziger, der bat ihn, knieete vor ihm und sprach zu ihm: Willst du, so kannst du mich wohl reinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Und es jammerte Jesum und reckte die Hand aus, ruhrete ihn an und sprach: Ich will\'s tun; sei gereiniget!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Und als er so sprach, ging der Aussatz alsbald von ihm, und er ward rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Und Jesus bedrauete ihn und trieb ihn alsbald von sich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'und sprach zu ihm: Siehe zu, daß du niemand nichts sagest, sondern gehe hin und zeige dich dem Priester und opfere fur deine Reinigung, was Mose geboten hat, zum Zeugnis uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Er aber, da er hinauskam, hub er an und sagte viel davon und machte die Geschichte ruchbar, also daß er hinfort nicht mehr konnte offentlich in die Stadt gehen, sondern er war draußen in den wusten Ortern. Und sie kamen zu ihm von alien Enden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Und uber etliche Tage ging erwiederum gen Kapernaum; und es ward ruchbar, daß er im Hause war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Und alsbald versammelten sich viele, also daß sie nicht Raum hatten, auch draußen vor der Tür. Und er sagte ihnen das Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Und es kamen etliche zu ihm, die brachten einen Gichtbruchigen, von vieren getragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Und da sie nicht konnten zu ihm kommen vor dem Volk, deckten sie das Dach auf, da erwar, und gruben\'s auf und ließen das Bett hernieder, da der Gichtbruchige innen lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Da aber Jesus ihren Glauben sah, sprach er zu dem Gichtbruchigen: Mein Sohn, deine Sunden sind dirvergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Es waren aber etliche Schriftgelehrte, die saßen allda und gedachten in ihrem Herzen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Wie redet dieser solche Gotteslasterung? Wer kann Sunde vergeben denn allein Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Und Jesus erkannte bald in seinem Geist, daß sie also gedachten bei sich selbst, und sprach zu ihnen: Was gedenket ihr solches in euren Herzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Welches ist leichter, zu dem Gichtbruchigen zu sagen: Dir sind deine Sunden vergeben, Oder: Stehe auf, nimm dein Bett und wandele?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Auf daß ihr aber wisset, daß des Menschen Sohn Macht hat, zu vergeben die Sunden auf Erden, sprach er zu dem Gichtbruchigen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Ich sage dir, stehe auf, nimm dein Bett und gehe heim!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Und alsbald stund er auf, nahm sein Bett und ging hinaus vor alien, also daß sie sich alle entsetzten und preiseten Gott und sprachen: Wir haben solches noch nie gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Und er ging wiederum hinaus an das Meer; und alles Volk kam zu ihm, und er lehrete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Und da Jesus voruberging, sah er Levi, den Sohn des Alphaus, am Zoll sitzen und sprach zu ihm: Folge mir nach! Und er stund auf und folgte ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Und es begab sich, da erzu Tische saß in seinem Hause, setzten sich viel Zollner und Sunder zu Tische mit Jesu und seinen Jungern. Denn ihrerwar viel, die ihm nachfolgeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Und die Schriftgelehrten und Pharisaer, da sie sahen, daß er mit den Zollnern und Sundern aß, sprachen sie zu seinen Jungern: Warum isset und trinket er mit den Zollnern und Sundern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Da das Jesus horete, sprach erzu ihnen: Die Starken bedurfen keines Arztes, sondern die Kranken. Ich bin kommen, zu rufen die Sunder zur Buße und nicht die Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Und die Junger des Johannes und der Pharisaer fasteten viel; und es kamen etliche, die sprachen zu ihm: Warum fasten die Junger des Johannes und der Pharisaer, und deine Junger fasten nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Und Jesus sprach zu ihnen: Wie konnen die Hochzeitsleute fasten, dieweil der Brautigam bei ihnen ist? Alsolange der Brautigam bei ihnen ist, konnen sie nicht fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Es wird aber die Zeit kommen, daß der Brautigam von ihnen genommen wird; dann werden sie fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Niemand flicket einen Lappen von neuem Tuch an ein alt Kleid; denn der neue Lappen reißet doch vom alten, und der Riß wird arger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Und niemand fasset Most in alte Schlauche; anders zerreißet der Most die Schlauche, und der Wein wird verschuttet, und die Schlauche kommen urn. Sondern man soil Most in neue Schlauche fassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Und es begab sich, da erwandelte am Sabbat durch die Saat, und seine Junger fingen an, indem sie gingen, Ahren auszuraufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Und die Pharisaer sprachen zu ihm: Siehe zu, was tun deine Junger am Sabbat, das nicht recht ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Und er sprach zu ihnen: Habt ihr nie gelesen, was David tat, da es ihm not war und ihn hungerte samt denen, die bei ihm waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'wie er ging in das Haus Gottes zur Zeit Abjathars, des Hohenpriesters, und aß die Schaubrote, die niemand durfte essen denn die Priester, und er gab sie auch denen, die bei ihm waren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Und er sprach zu ihnen: Der Sabbat ist urn des Menschen willen gemacht und nicht der Mensch urn des Sabbats willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'So ist des Menschen Sohn ein Herr auch des Sabbats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Und er ging abermal in die Schule. Und es war da ein Mensch, der hatte eine verdorrete Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Und sie hielten auf ihn, ob er auch am Sabbat ihn heilen würde, auf daß sie eine Sache wider ihn hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Und er sprach zu dem Menschen mit der verdorreten Hand: Tritt hervor!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Und er sprach zu ihnen: Soil man am Sabbat Gutes tun Oder Boses tun, das Leben erhalten Oder toten? Sie aber schwiegen stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Und er sah sie umher an mit Zorn und war betrubet uber ihre verstockten Herzen und sprach zu dem Menschen: Strecke deine Hand aus! Und er streckte sie aus; und die Hand ward ihm gesund wie die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Und die Pharisaer gingen hinaus und hielten alsbald einen Rat mit des Herodes Dienern über ihn, wie sie ihn umbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Aber Jesus entwich mit seinen Jungern an das Meer. Und viel Volks folgte ihm nach aus Galilaa und aus Judaa');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'und von Jerusalem und aus Idumaa und von jenseit des Jordans und die urn Tyrus und Sidon wohnen, eine grolie Menge, die seine Taten horeten, und kamen zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Und er sprach zu seinen Jungern, daß sie ihm ein Schifflein hieiten urn des Volks willen, daß sie ihn nicht drangeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Denn er heilete ihrer viele, also da(3> sie ihn uberfielen, alle, die geplagt waren, auf daß sie ihn anruhreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Und wenn ihn die unsaubern Geister sahen, fielen sie vor ihm nieder, schrieen und sprachen: Du bist Gottes Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Und er bedrauete sie hart, daß sie ihn nicht offenbar machten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Und erging auf einen Berg und rief zu sich, welche erwollte, und die gingen hin zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Und erordnete die Zwolfe, daß sie bei ihm sein sollten, und daß er sie aussendete zu predigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'und daß sie Macht hatten, die Seuchen zu heilen und die Teufel auszutreiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'und gab Simon den Namen Petrus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'und Jakobus, den Sohn des Zebedaus, und Johannes, den Bruder des Jakobus, und gab ihnen den Namen Bnehargem, das istgesagt, Donnerskinder;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'und Andreas und Philippus und Bartholomaus und Matthaus und Thomas und Jakobus, des Alphaus Sohn, und Thaddaus und Simon von Kana');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'und Judas Ischariot, der ihn verriet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Und sie kamen nach Hause; und da kam abermal das Volk zusammen, also daü sie nicht Raum hatten zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Und da es horeten, die urn ihn waren, gingen sie hinaus und wollten ihn halten; denn sie sprachen: Er wird von Sinnen kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Die Schriftgelehrten aber, die von Jerusalem herabkommen waren, sprachen: Er hat den Beelzebub und durch den Obersten der Teufel treibt er die Teufel aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Und er rief sie zusammen und sprach zu ihnen in Gleichnissen: Wie kann ein Satan den andern austreiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Wenn ein Reich mit ihm selbst untereinander uneins wird, mag es nicht bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Und wenn ein Haus mit ihm selbst untereinander uneins wird, mag es nicht bestehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Setzet sich nun der Satan wider sich selbst und ist mit ihm selbst uneins, so kann er nicht bestehen, sondern es ist aus mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Es kann niemand einem Starken in sein Haus fallen und seinen Hausrat rauben, es sei denn, daß er zuvor den Starken binde und alsdann sein Haus beraube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Wahrlich, ich sage euch, alle Sunden werden vergeben den Menschenkindern, auch die Gotteslasterung, damit sie Gott lastern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'wer aber den Heiligen Geist lasted, der hat keine Vergebung ewiglich, sondern ist schuldig des ewigen Gerichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Denn sie sagten: Er hat einen unsaubern Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Und es kam seine Mutter und seine Bruder und stunden draulien, schickten zu ihm und lielien ihn rufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Und das Volk sali urn ihn. Und sie sprachen zu ihm: Siehe, deine Mutter und deine Bruder draulien fragen nach dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Und er antwortete ihnen und sprach: Wer ist meine Mutter und meine Bruder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Und er sah rings urn sich auf die Jünger, die urn ihn im Kreise salien, und sprach: Siehe, das ist meine Mutter und meine Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Denn wer Gottes Willen tut, der ist mein Bruder und meine Schwester und meine Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Und er fing abermal an zu lehren am Meer. Und es versammelte sich viel Volks zu ihm, also daß er mulite in ein Schiff treten und auf dem Wasser sitzen. Und alles Volk stund auf dem Lande am Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Und erpredigte ihnen lange durch Gleichnisse. Und in seiner Predigt sprach er zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Horet zu! Siehe, es ging ein Samann aus, zu saen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Und es begab sich, indem er sate, fiel etliches an den Weg; da kamen die Vogel unter dem Himmel und fralien\'s auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Etliches fiel in das Steinige, da es nicht viel Erde hatte, und ging bald auf, darum daß es nicht tiefe Erde hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Da nun die Sonne aufging, verwelkte es, und dieweil es nicht Wurzel hatte, verdorrete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Und etliches fiel unter die Dornen, und die Dornen wuchsen empor und erstickten\'s, und es brachte keine Frucht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Und etliches fiel auf ein gut Land und brachte Frucht, die da zunahm und wuchs; und etliches trug dreilügfaltig und etliches sechzigfaltig und etliches hundertfaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Und er sprach zu ihnen: Wer Ohren hat zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Und da er allein war, fragten ihn urn dieses Gleichnis, die urn ihn waren, samt den Zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Und er sprach zu ihnen: Euch ist\'s gegeben, das Geheimnis des Reichs Gottes zu wissen; denen aber draulien widerfahret es alles durch Gleichnisse,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'auf daß siees mitsehenden Augen sehen und doch nicht erkennen und mit horenden Ohren horen und doch nicht verstehen, auf daß sie sich nicht dermal einst bekehren, und ihre Sünden ihnen vergeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Und er sprach zu ihnen: Verstehet ihr dieses Gleichnis nicht, wie wollet ihr denn die andern alle verstehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Der Samann saet das Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Diese sind\'s aber, die an dem Wege sind, wo das Wort gesaet wird, und sie es gehoret haben; so kommt alsbald der Satan und nimmt weg das Wort, das in ihr Herz gesaet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Also auch die sind\'s, die aufs Steinige gesaet sind; wenn sie das Wort gehoret haben, nehmen sie es bald mit Freuden auf');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'und haben keine Wurzel in ihnen, sondern sind wetterwendisch; wenn sich Trubsal Oder Verfolgung urn des Worts willen erhebt, so argern sie sich alsbald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Und diese sind\'s, die unter die Dornen gesaet sind, die das Wort horen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'und die Sorge dieser Welt und der betrugliche Reichtum und viel andere Lüste gehen hinein und ersticken das Wort, und bleibet ohne Frucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Und diese sind\'s, die auf ein gut Land gesaet sind, die das Wort horen und nehmen\'s an und bringen Frucht, etlicher dreilügfaltig und etlicher sechzigfaltig und etlicher hundertfaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Und er sprach zu ihnen: Zundet man auch ein Licht an, daß man\'s unter einen Scheffel Oder unter einen Tisch setze? Mitnichten, sondern daß man\'s auf einen Leuchter setze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Denn es ist nichts verborgen, das nicht offenbar werde, und ist nichts FHeimliches, das nicht hervorkomme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Wer Ohren hat zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Und sprach zu ihnen: Sehet zu, was ihr horet! Mit welcherlei Mali ihr messet, wird man euch wieder messen; und man wird noch zugeben euch, die ihr dies horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Denn wer da hat, dem wird gegeben; und wer nicht hat, von dem wird man nehmen, auch was er hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Und er sprach: Das Reich Gottes hat sich also, als wenn ein Mensch Samen aufs Land wirft');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'und schlaft und stehet auf Nacht und Tag, und der Same gehet auf und wachset, daß er\'s nicht weili.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Denn die Erde bringt von ihr selbst zum ersten das Gras, danach die Ahren, danach den vollen Weizen in den Ahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Wenn sie aber die Frucht gebracht hat, so schicket er bald die Sichel hin; denn die Ernte ist da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Und er sprach: Wem wollen wir das Reich Gottes vergleichen und durch welch Gleichnis wollen wir es vorbilden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Gleichwie ein Senfkorn, wenn das gesaet wird aufs Land, so ist\'s das kleinste unter alien Samen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Und wenn es gesaet ist, so nimmt es zu und wird grolier denn alle Kohlkrauter und gewinnet grolie Zweige, also daß die Vogel unter dem Himmel unter seinem Schatten wohnen konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Und durch vieie solche Gleichnisse sagte er ihnen das Wort, nach dem sie es horen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Und ohne Gleichnis redete er nichts zu ihnen; aber insonderheit legte er\'s seinen Jungern alles aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Und an demselbigen Tage, des Abends, sprach erzu ihnen: Lalit uns hinuberfahren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Und sie lielien das Volk gehen und nahmen ihn, wie er im Schiff war; und es waren mehr Schiffe bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Und es erhub sich ein grolier Windwirbel und warf die Wellen in das Schiff, also daß das Schiff voll ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Und er war hinten auf dem Schiff und schlief auf einem Kissen. Und sieweckten ihn auf und sprachen zu ihm: Meister, fragst du nichts danach, daß wir verderben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Und er stund auf und bedrauete den Wind und sprach zu dem Meer: Schweig und verstumme! Und der Wind legte sich, und ward eine grolie Stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Und er sprach zu ihnen: Wie seid ihr furchtsam? Wie, daß ihr keinen Glauben habt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Und sie furchteten sich sehr und sprachen untereinander: Wer ist der? Denn Wind und Meer sind ihm gehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Und sie kamen jenseit des Meers, in die Gegend der Gadarener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Und als er aus dem Schiff trat, lief ihm alsbald entgegen aus den Grabern ein besessener Mensch mit einem unsaubern Geist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'der seine Wohnung in den Grabern hatte. Und niemand konnte ihn binden, auch nicht mit Ketten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Denn erwar oft mit Fesseln und Ketten gebunden gewesen und hatte die Ketten abgerissen und die Fesseln zerrieben, und niemand konnte ihn zahmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Und er war allezeit, Tag und Nacht, auf den Bergen und in den Grabern, schrie und schlug sich mit Steinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Da er aber Jesus sah von feme, lief er zu und fiel vor ihm nieder, schrie laut und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Was hab\' ich mit dir zu tun, o Jesu, du Sohn Gottes, des Allerhochsten,? Ich beschwore dich bei Gott, daß du mich nicht qualest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Er aber sprach zu ihm: Fahre aus, du unsauberer Geist, von dem Menschen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Und er fragte ihn: Wie heiliest du? Und er antwortete und sprach: Legion heilie ich; denn unser ist viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Und er bat ihn sehr, daß er sie nicht aus derselben Gegend triebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Und es war daselbst an den Bergen eine grolie Herde Saue auf der Weide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Und die Teufel baten ihn alle und sprachen: Lali uns in die Saue fahren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Und alsbald erlaubete ihnen Jesus. Da fuhren die unsaubern Geister aus und fuhren in die Saue und die Herde sturzte sich mit einem Sturm ins Meer (ihrer war aber bei zweitausend) und ersoffen im Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Und die Sauhirten flohen und verkündigten das in der Stadt und auf dem Lande. Und sie gingen hinaus, zu sehen, was da geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Und kamen zu Jesu und sahen den, so von den Teufeln besessen war, daß er sali und war bekleidet und vernunftig, und furchteten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Und die es gesehen hatten, sagten ihnen, was dem Besessenen widerfahren war, und von den Sauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Und sie fingen an und baten ihn, daß er aus ihrer Gegend zoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Und da er in das Schiff trat, bat ihn der Besessene, daß er mochte bei ihm sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Aber Jesus lieli es ihm nicht zu, sondern sprach zu ihm: Gehe hin in dein Haus und zu den Deinen und verkundige ihnen, wie groüe Wohltat dir der Herr getan und sich deiner erbarmet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Und er ging hin und fing an auszurufen in den zehn Stadten, wie groüe Wohltat ihm Jesus getan hatte. Und jedermann verwunderte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Und da Jesus wieder heruberfuhr im Schiff, versammelte sich viel Volks zu ihm und war an dem Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Und siehe, da kam der Obersten einer von der Schule mit Namen Jairus. Und da er ihn sah, fiel er ihm zu Fütien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'und bat ihn sehr und sprach: Meine Tochter ist in den letzten Zugen; du wollest kommen und deine Hand auf sie legen, daß sie gesund werde und lebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Und er ging hin mit ihm. Und es folgte ihm viel Volks nach, und sie drangeten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Und da war ein Weib, das hatte den Blutgang zwolf Jahre gehabt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'und viel erlitten von vielen Arzten und hatte all ihr Gut darob verzehrt; und half ihr nichts, sondern vielmehr ward es arger mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Da die von Jesu horete, kam sie im Volk von hinten zu und ruhrete sein Kleid an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Denn sie sprach: Wenn ich nur sein Kleid mochte anruhren, so würde ich gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Und alsbald vertrocknete der Brunn ihres Bluts; und sie fühlte es am Leibe, daß sie von ihrer Plage war gesund worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Und Jesus fühlete alsbald an ihm selbst die Kraft, die von ihm ausgegangen war, und wandte sich urn zum Volk und sprach: Wer hat meine Kleider angeruhret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Und die Jünger sprachen zu ihm: Du siehest, dad dich das Volk dranget, und sprichst: Wer hat mich angeruhret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Und er sah sich urn nach der, die das getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Das Weib aber furchtete sich und zitterte (denn sie wudte, was an ihr geschehen war), kam und fiel vor ihm nieder und sagte ihm die ganze Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Er sprach aber zu ihr: Meine Tochter, dein Glaube hat dich gesund gemacht. Gehe hin mit Frieden und sei gesund von deiner Plage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Da er noch also redete, kamen etliche vom Gesinde des Obersten der Schule und sprachen: Deine Tochter ist gestorben, was muhest du weiter den Meister?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jesus aber horete bald die Rede, die da gesagt ward, und sprach zu dem Obersten der Schule: Furchte dich nicht; glaube nur!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Und lieli niemand ihm nachfolgen denn Petrus und Jakobus und Johannes, den Bruder des Jakobus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Und er kam in das Haus des Obersten der Schule und sah das Getummel, und die da sehr weineten und heuleten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Und er ging hinein und sprach zu ihnen: Was tummelt und weinet ihr? Das Kind ist nicht gestorben, sondern es schlaft. Und sie verlachten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Und er trieb sie alle aus und nahm mit sich den Vater des Kindes und die Mutter und die bei ihm waren, und ging hinein, da das Kind lag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Und ergriff das Kind bei der Hand und sprach zu ihr: Talitha, kumi! das ist verdolmetschet: Magdlein, ich sage dir, stehe auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Und alsbald stund das Magdlein auf und wandelte; es war aber zwolf Jahre alt. Und sie entsetzten sich uber die Mai Jen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Und er verbot ihnen hart, daß es niemand wissen sollte, und sagte, sie sollten ihr zu essen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Und er ging aus von dannen und kam in sein Vaterland; und seine Junger folgten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Und da der Sabbat kam, hub er an zu lehren in ihrer Schule: Und viele, die es horeten, verwunderten sich seiner Lehre und sprachen: Woher kommt dem solches? und: Was fur Weisheit ist\'s, die ihm gegeben ist, und solche Taten, die durch seine Hande geschehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ist er nicht der Zimmermann, Marias Sohn, und der Bruder des Jakobus und Joses und Judas und Simon? Sind nicht auch seine Schwestern allhie bei uns? Und sie argerten sich an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Jesus aber sprach zu ihnen: Ein Prophet gilt nirgend weniger denn im Vaterland und daheim bei den Seinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Und er konnte alida nicht eine einzige Tat tun; ohne wenig Siechen legte er die Hande auf und heilete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Und er verwunderte sich ihres Unglaubens. Und er ging umher in die Flecken im Kreis und lehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Und er berief die Zwolfe und hub an und sandte sie je zwei und zwei und gab ihnen Macht uber die unsauberen Geister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Und gebot ihnen, daß sie nichts bei sich trugen auf dem Wege denn allein einen Stab, keine Tasche, kein Brot, kein Geld im Gürtel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'sondern waren geschuhet, und daß sie nicht zwei Rockeanzogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Und sprach zu ihnen: Wo ihr in ein Haus gehen werdet, da bleibet innen, bis ihr von dannen ziehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Und welche euch nicht aufnehmen noch horen, da gehet von dannen heraus und schuttelt den Staub ab von euren Fülien zu einem Zeugnis über sie. Ich sage euch: Wahrlich, eswird Sodom und Gomorra am Jungsten Gerichte ertraglicher ergehen denn solcher Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Und sie gingen aus und predigten, man sollte Bulie tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Und trieben viele Teufel aus und salbeten viele Sieche mit 01 und machten sie gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Und es kam vorden Konig Herodes (denn sein Name war nun bekannt); und er sprach: Johannes der Taufer ist von den Toten auferstanden; darum tut er solche Taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Etliche aber sprachen: Er ist Elia; etliche aber: Er ist ein Prophet Oder einer von den Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Da es aber Herodes horete, sprach er: Es ist Johannes, den ich enthauptet habe; der ist von den Toten auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Er aber, Herodes, hatte ausgesandt und Johannes gegriffen und ins Gefangnis gelegt um der Herodias willen, seines Bruders Philippus Weib; denn er hatte sie gefreiet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Johannes aber sprach zu Herodes: Es ist nicht recht, dafi du deines Bruders Weib habest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herodias aber stellete ihm nach und wollte ihn toten und konnte nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Herodes aber furchtete Johannes; denn er wulite, daß er ein frommer und heiliger Mann war; und verwahrete ihn und gehorchte ihm in vielen Sachen und horete ihn gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Und es kam ein gelegener Tag, daß Herodes auf seinen Jahrstag ein Abendmahl gab den Obersten und Hauptleuten und Vornehmsten in Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Da trat hinein die Tochter der Herodias und tanzete, und gefiel wohl dem Herodes und denen, die am Tisch salien. Da sprach der Konig zum Magdlein: Bitte von mir, was du willst; ich will dir\'s geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Und schwur ihr einen Eid: Was du wirst von mir bitten, will ich dir geben, bis an die Halfte meines Konigreichs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Sie ging hinaus und sprach zu ihrer Mutter: Was soil ich bitten? Die sprach: Das Haupt Johannes des Taufers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Und sie ging bald hinein mit Eüe zum Konige, bat und sprach: ich will, daß du mir gebest jetzt sobald auf einer Schussel das Haupt Johannes des Taufers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Der Konig ward betrubt; doch um des Eides willen und derer, die am Tische saüen, wollte er sie nicht lassen eine Fehlbitte tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Und bald schickte hin der Konig den Henker und hieli sein Haupt herbringen. Der ging hin und enthauptete ihn im Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Und trug her sein Haupt auf einer Schussel und gab\'s dem Magdlein, und das Magdlein gab\'s ihrer Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Und da das seine Junger horeten, kamen sie und nahmen seinen Leib und legten ihn in ein Grab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Und die Apostel kamen zu Jesu zusammen und verkundigten ihm das alles, und was sie getan und gelehret hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Und er sprach zu ihnen: Lasset uns besonders in eine Wuste gehen und ruhet ein wenig. Denn ihrer war viel, die ab und zu gingen, und hatten nicht Zeit genug zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Und er fuhr da in einem Schiff zu einer Wuste besonders.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Und das Volk sah sie wegfahren, und viele kannten ihn und liefen daselbst hin miteinander zu Fufi aus alien Stadten und kamen ihnen zuvor und kamen zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Und Jesus ging heraus und sah das grolie Volk; und es jammerte ihn derselben, denn sie waren wie die Schafe, die keinen Hirten haben; und fing an eine lange Predigt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Da nun der Tag fast dahin war, traten seine Junger zu ihm und sprachen: Es ist wuste hier, und der Tag ist nun dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Lati sie von dir, dafi sie hingehen umher in die Dorfer und Markte und kaufen sich Brot; denn sie haben nicht zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Jesus aber antwortete und sprach zu ihnen: Gebet ihr ihnen zu essen! Und sie sprachen zu ihm: Sollen wir denn hingehen und zweihundert Pfennig wert Brot kaufen und ihnen zu essen geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Er aber sprach zu ihnen: Wieviel Brote habt ihr? Gehet hin und sehet! Und da sie es erkundet hatten, sprachen sie: Funf und zwei Fische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Und er gebot ihnen, daß sie sich aile lagerten bei Tischen voli auf das grune Gras.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Und sie setzten sich nach Schichten, je hundert und hundert, funfzig und fünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Und er nahm die fünf Brote und zwei Fische und sah auf gen Himmel und dankete und brach die Brote und gab sie den Jungern, dafi sie ihnen vorlegten; und die zwei Fische teilete er unter sie aile.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Und sie alien aile und wurden satt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Und sie huben auf die Brocken, zwolf Korbe voli, und von den Fischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Und die da gegessen hatten, der waren funftausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Und alsbald trieb er seine Junger, daß sie in das Schiff traten und vor ihm hinüberführen gen Bethsaida, bis daß er das Volk von sich lielie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Und da er sie von sich geschafft hatte, ging er hin auf einen Berg, zu beten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Und am Abend war das Schiff mitten auf dem Meer und er auf dem Lande alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Und er sah, dati sie Not litten im Rudern; denn der Wind war ihnen entgegen. Und um die vierte Wache der Nacht kam er zu ihnen und wandelte auf dem Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Und er wollte vor ihnen ubergehen. Und da sie ihn sahen auf dem Meerwandeln, meineten sie, es ware ein Gespenst, und schrieen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Denn sie sahen ihn alle und erschraken. Aber alsbald redete er mit ihnen und sprach zu ihnen: Seid getrost; ich bin\'s furchtet euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Und trat zu ihnen ins Schiff, und der Wind legte sich. Und sie entsetzten sich und verwunderten sich uber die Maften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Denn sie waren nichts verstandiger worden über den Broten, und ihr Herz war erstarret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Und da sie hinubergefahren waren, kamen sie in das Land Genezareth und fuhren an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Und da sie aus dem Schiff traten, alsbald kannten sie ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'und liefen alle in die umliegenden Lander und huben an, die Kranken umherzuführen auf Betten, wo sie horeten, daß erwar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Und wo er in die Markte Oder Stadte Oder Dorfer einging, da legten sie die Kranken auf den Markt und baten ihn, daß sie nur den Saum seines Kleides an rühren mochten. Und alle, die ihn anruhreten, wurden gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Und es kamen zu ihm die Pharisaer und etliche von den Schriftgelehrten, die von Jerusalem kommen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Und da sie sahen etliche seiner Junger mit gemeinen, das ist, mit ungewaschenen Handen das Brat essen, versprachen sie es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Denn die Pharisaer und alle Juden essen nicht, sie waschen denn die Hande manchmal; halten also die Aufsatze der Altesten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Und wenn sie vom Markt kommen, essen sie nicht, sie waschen sich denn. Und des Dings ist viel, das sie zu halten haben angenommen, von Trinkgefaften und Krugen und ehernen Gefaften und Tischen zu waschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Da fragten ihn nun die Pharisaer und Schriftgelehrten: Warum wandeln deine Junger nicht nach den Aufsatzen der Altesten, sondern essen das Brat mit ungewaschenen Handen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Er aber antwortete und sprach zu ihnen: Wohl fein hat von euch Heuchlern Jesaja geweissagt, wie geschrieben steht: Dies Volk ehret mich mit den Lippen, aber ihr Herz ist feme von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Vergeblich aber ist\'s, daß sie mir dienen, dieweil sie lehren solche Lehre, die nichts ist denn Menschengebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Ihr verlasset Gottes Gebot und haltet der Menschen Aufsatze, von Krugen und Trinkgefaften zu waschen; und desgleichen tut ihr viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Und er sprach zu ihnen: Wohl fein habt ihr Gottes Gebot aufgehoben, auf daß ihr eure Aufsatze haltet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Denn Mose hat gesagt: Du sollst deinen Vater und deine Mutter ehren; und: Wer Vater Oder Mutter flucht, der soil des Todes sterben:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ihr aber lehret: Wenn einer spricht zum Vater Oder Mutter: Korban, das ist, wenn ich\'s opfere, so ist dir\'s viel nutzer, der tut wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Und so laftt ihr hinfort ihn nichts tun seinem Vater Oder seiner Mutter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'und hebet auf Gottes Wort durch eure Aufsatze, die ihr aufgesetzt habt; und desgleichen tut ihr viel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Und er rief zu sich das ganze Volk und sprach zu ihnen: Horet mir alle zu und vernehmet\'s!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Es ist nichts aufter dem Menschen, was ihn konnte gemein machen, so es in ihn gehet; sondern was von ihm ausgehet, das ist\'s, was den Menschen gemein macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Hat jemand Ohren zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Und da ervon dem Volk ins Haus kam, fragten ihn seine Junger um dieses Gleichnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Und er sprach zu ihnen: Seid ihr denn auch so unverstandig? Vernehmet ihr noch nicht, daß alles, was auften ist und in den Menschen gehet, das kann ihn nicht gemein machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Denn es gehet nicht in sein Herz, sondern in den Bauch und gehet aus durch den naturlichen Gang, der alle Speise ausfeget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Und er sprach: Was aus dem Menschen gehet, das macht den Menschen gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Denn von innen, aus dem Herzen der Menschen, gehen heraus bose Gedanken, Ehebruch, Hurerei, Mord,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Dieberei, Geiz, Schalkheit; List, Unzucht, Schalksauge, Gotteslasterung, Hoffart, Unvernunft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Alle diese bosen Stücke gehen von innen heraus und machen den Menschen gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Und er stund auf und ging von dannen in die Grenze von Tyrus und Sidon und ging in ein Haus und wollte es niemand wissen lassen und konnte doch nicht verborgen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Denn ein Weib hatte von ihm gehort, deren Tochterlein einen unsauberen Geist hatte. Und sie kam und fiel nieder zu seinen Füften');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '(und es war ein griechisch Weib aus Syrophonizien); und sie bat ihn, daß er den Teufel von ihrer Tochter austriebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jesus aber sprach zu ihr: Laft zuvor die Kinder satt werden! Es ist nicht fein, daß man der Kinder Brot nehme und werfe es vor die Hunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Sie antwortete aber und sprach zu ihm: Ja, Herr; aber doch essen die Hündlein unter dem Tisch von den Brosamen der Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Und er sprach zu ihr: Um des Worts willen so gehe hin; der Teufel ist von deiner Tochter ausgefahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Und sie ging hin in ihr Haus und fand, daß der Teufel war ausgefahren und die Tochter auf dem Bette liegend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Und da erwieder ausging von den Grenzen Tyrus und Sidon, kam er an das Galilaische Meer, mitten unter die Grenze der zehn Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Und sie brachten zu ihm einen Tauben, der stumm war; und sie baten ihn, daß er die Hand auf ihn legte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Und er nahm ihn von dem Volk besonders und legte ihm die Finger in die Ohren und sputzete und ruhrete seine Zunge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Und sah auf gen Himmel, seufzete und sprach zu ihm: Hephatha! das ist: Tu dich auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Und alsbald taten sich seine Ohren auf, und das Band seiner Zunge ward los und redete recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Und er verbot ihnen, sie sollten es niemand sagen. Je mehr er aber verbot, je mehr sie es ausbreiteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Und verwunderten sich fiber die Malien und sprachen: Er hat alles wohl gemacht: die Tauben macht er horend und die Sprachlosen redend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Zu der Zeit, da viel Volks da war und hatten nichts zu essen, rief Jesus seine Jünger zu sich und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Mich jammed des Volks; denn sie haben nun drei Tage bei mir beharret und haben nichts zu essen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'und wenn ich sie ungegessen von mir heim lielie gehen, würden sie auf dem Wege verschmachten. Denn etliche waren von feme kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Seine Junger antworteten ihm: Woher nehmen wir Brot hier in der Wuste, daß wir sie sattigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Und er fragte sie: Wieviel habt ihr Brots? Sie sprachen: Sieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Und er gebot dem Volk, daß sie sich auf die Erde lagerten. Und er nahm die sieben Brote und dankete und brach sie und gab sie seinen Jungern, daß sie dieselbigen vorlegten; und sie legten dem Volk vor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Und hatten ein wenig Fischlein; und erdankte und hiefi dieselbigen auch vortragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Sie alien aber und wurden satt und huben die ubrigen Brocken auf, sieben Korbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Und ihrer war bei viertausend, die da gegessen hatten; und er lieli sie von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Und alsbald trater in ein Schiff mit seinen Jungern und kam in die Gegend Dalmanuthas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Und die Pharisaer gingen heraus und fingen an, sich mit ihm zu befragen, versuchten ihn und begehrten von ihm ein Zeichen vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Und er seufzete in seinem Geist und sprach: Was sucht doch dies Geschlecht Zeichen? Wahrlich, ich sage euch, es wird diesem Geschlecht kein Zeichen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Und er lieli sie und tratwiederum in das Schiff und fuhr heruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Und sie hatten vergessen, Brot mit sich zu nehmen, und hatten nicht mehr mit sich im Schiff denn ein Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Und er gebot ihnen und sprach: Schauet zu und sehet euch vor vor dem Sauerteig der Pharisaer und vor dem Sauerteig Herodes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Und sie gedachten hin und wieder und sprachen untereinander: Das ist\'s, daß wir nicht Brot haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Und Jesus vernahm das und sprach zu ihnen: Was bekümmert ihr euch doch, daß ihr nicht Brot habt? Vernehmet ihr noch nichts und seid noch nicht verstandig? Habt ihr noch ein verstarret Herz in euch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Habt Augen und sehet nicht und habt Ohren und horet nicht und denket nicht daran,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'da ich fünf Brote brach unter funftausend, wieviel Korbe voll Brocken hubet ihr da auf? Sie sprachen: Zwdlf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Da ich aber die sieben brach unter die viertausend, wieviel Korbe voll Brocken hubet ihr da auf? Sie sprachen: Sieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Und er sprach zu ihnen: Wie vernehmet ihr denn nichts?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Und er kam gen Bethsaida. Und sie brachten zu ihm einen Blinden und baten ihn, daß er ihn anruhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Und er nahm den Blinden bei der Hand und fuhrete ihn hinaus vor den Flecken und sputzete in seine Augen und legte seine Hande auf ihn, und fragte ihn, ob er etwas sahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Und er sah auf und sprach: Ich sehe Menschen gehen, als sahe ich Baume.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Danach legte er abermal die Hande auf seine Augen und hieli ihn abermal sehen; und erward wieder zurechtgebracht, daß er alles scharf sehen konnte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Und erschickte ihn heim und sprach: Gehe nicht hinein in den Flecken und sage es auch niemand drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Und Jesus ging aus und seine Junger in die Markte der Stadt Casarea - Philippi. Und auf dem Wege fragte er seine Junger und sprach zu ihnen: Wer sagen die Leute, daß ich sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Sie antworteten: Sie sagen, du seiest Johannes der Taufer; etliche sagen, du seiest Elia; etliche, du seiest der Propheten einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Und er sprach zu ihnen: Ihr aber, wer sagt ihr, daß ich sei? Da antwortete Petrus und sprach zu ihm: Du bist Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Und er bedrauete sie, daß sie niemand von ihm sagen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Und hub an, sie zu lehren: Des Menschen Sohn muli viel leiden und verworfen werden von den Altesten und Hohenpriestern und Schriftgelehrten und getotet werden und fiber drei Tage auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Und er redete das Wort frei offenbar. Und Petrus nahm ihn zu sich, fing an, ihm zu wehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Er aber wandte sich urn und sah seine Junger an und bedrauete Petrus und sprach: Geh hinter mich, du Satan! Denn du meinest nicht, was gottlich, sondern was menschlich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Und er rief zu sich das Volk samt seinen Jungern und sprach zu ihnen: Wer mir will nach folgen, der verleugne sich selbst und nehme sein Kreuz auf sich und folge mir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Denn wer sein Leben will behalten der wird\'s verlieren; und wer sein Leben verlieret um meinet und des Evangeliums willen, der wird\'s behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Was hulfe es dem Menschen, wenn er die ganze Welt gewonne und nahme an seiner Seele Schaden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Oder was kann der Mensch geben, damit er seine Seele lose?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Wer sich aber mein und meiner Worte schamet unterdiesem ehebrecherischen und sundigen Geschlecht, des wird sich auch des Menschen Sohn schamen, wenn er kommen wird in der Herrlichkeit seines Vaters mitden heiligen Engeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Und er sprach zu ihnen: Wahrlich, ich sage euch, es stehen etliche hier, die werden den Tod nicht schmecken, bis daß sie sehen das Reich Gottes mit Kraft kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Und nach sechs Tagen nahm Jesus zu sich Petrus, Jakobus und Johannes und fuhrte sie auf einen hohen Berg besonders alleine und verklarete sich vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Und seine Kleider wurden hell und sehr weili wie der Schnee, daß sie kein Farber auf Erden kann so weili machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Und es erschien ihnen Elia mit Mose und hatten eine Rede mit Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Und Petrus antwortete und sprach zu Jesu: Rabbi, hier ist gut sein; lasset uns drei Hütten machen, dir eine, Mose eine und Elia eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Er wulite aber nicht, was er redete; denn sie waren besturzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Und es kam eine Wolke, die uberschattete sie. Und eine Stimme fiel aus der Wolke und sprach: Das ist mein lieber Sohn; den sollt ihr horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Und bald danach sahen sie um sich und sahen niemand mehr denn allein Jesum bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Da sie aber vom Berge herabgingen, verbot ihnen Jesus, daß sie niemand sagen sollten, was sie gesehen hatten, bis des Menschen Sohn auferstunde von den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Und sie behielten das Wort bei sich und befragten sich untereinander: Was ist doch das Auferstehen von den Toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Und sie fragten ihn und sprachen: Sagen doch die Schriftgelehrten, daß Elia muti zuvor kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Er antwortete aber und sprach zu ihnen: Elia soil ja zuvor kommen und alles wieder zurechtbringen; dazu des Menschen Sohn soil viel leiden und verachtet werden, wie denn geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Aber ich sage euch: Elia ist kommen, und sie haben an ihm getan, was sie wollten, nachdem von ihm geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Und, er kam zu seinen Jüngem und sah viel Volks um sie und Schriftgelehrte, die sich mit ihnen befragten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Und alsbald, da alles Volk ihn sah, entsetzten sie sich, liefen zu und grulieten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Und erfragete die Schriftgelehrten: Was befraget ihr euch mit ihnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Einer aber aus dem Volk antwortete und sprach: Meister, ich habe meinen Sohn hergebracht zu dir, der hat einen sprachlosen Geist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'und wo er ihn erwischet, so reilit er ihn und schaumet und knirschet mit den Zahnen und verdorret. Ich habe mit deinen Jüngem geredet, daß sie ihn austrieben, und sie konnen\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Er antwortete ihm aber und sprach: O du unglaubiges Geschlecht, wie lange soil ich bei euch sein? Wie lange soil ich mich mit euch leiden? Bringet ihn her zu mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Und sie brachten ihn her zu ihm. Und alsbald, da ihn der Geist sah, rili er ihn und fiel auf die Erde und walzete sich und schaumete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Und er fragte seinen Vater: Wie lange ist\'s, daß ihm das widerfahren ist? Er sprach: Von Kind auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Und oft hat er ihn in Feuer und Wasser geworfen, daß er ihn umbrachte. Kannst du aber was, so erbarme dich unser und hilf uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jesus aber sprach zu ihm: Wenn du konntet glauben! Alle Dinge sind moglich dem, der da glaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Und alsbald schrie des Kindes Vater mit Tranen und sprach: Ich glaube, lieber Herr; hilf meinem Unglauben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Da nun Jesus sah, daß das Volk zulief, bedrauete er den unsauberen Geist und sprach zu ihm: Du sprachloser und tauber Geist, ich gebiete dir, daß du von ihm ausfahrest und fahrest hinfort nicht in ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Da schrie er und rili ihn sehr und fuhr aus. Und er ward, als ware er tot, daß auch viele sagten: Er ist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Jesus aber ergriff ihn bei der Hand und richtete ihn auf; und er stund auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Und da er heimkam, fragten ihn seine Junger besonders: Warum konnten wir ihn nicht austreiben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Und er sprach: Diese Art kann mitnichten ausfahren denn durch Beten und Fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Und sie gingen von dannen hinweg und wandelten durch Galilaa; und erwollte nicht, daß es jemand wissen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Er lehrete aber seine Junger und sprach zu ihnen: Des Menschen Sohn wird uberantwortet werden in der Menschen Hande. Und sie werden ihn toten; und wenn er getotet ist, so wird er am dritten Tage auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Sie aber vernahmen das Wort nicht und furchteten sich, ihn zu fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Und er kam gen Kapernaum. Und da er daheim war, fragte er sie: Was handeltet ihr miteinander auf dem Wege?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Sie aber schwiegen; denn sie hatten miteinander auf dem Wege gehandelt, welcher der Grotite ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Und er setzte sich und rief den Zwolfen und sprach zu ihnen: So jemand will der Erste sein, der soil der Letzte sein vor alien und aller Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Und er nahm ein Kindlein und stellete es mitten unter sie und herzete dasselbige und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Wer ein solches Kindlein in meinem Namen aufnimmt, der nimmt mich auf; und wer mich aufnimmt, der nimmt nicht mich auf, sondern den, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes aber antwortete ihm und sprach: Meister, wir sahen einen, der trieb Teufel in deinem Namen aus, welcher uns nicht nachfolget; und wir verboten\'s ihm darum, daß er uns nicht nachfolget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jesus aber sprach: Ihr sollt\'s ihm nicht verbieten. Denn es ist niemand, der eine Tat tue in meinem Namen und moge bald ubel von mir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Wer nicht wider uns ist, der ist fur uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Wer aber euch tranket mit einem Becher Wassers in meinem Namen darum, daß ihr Christo angehoret, wahrlich, ich sage euch, es wird ihm nicht unvergolten bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Und wer der Kleinen einen argert, die an mich glauben, dem ware es besser, daü ihm ein Muhlstein an seinen Hals gehanget wurde, und er ins Meer geworfen wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'So dich aber deine Hand argert, so haue sie ab. Es ist dir besser, daß du als ein Kruppel zum Leben eingehest, denn daß du zwo Hande habest und fahrest in die Holle, in das ewige Feuer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'da ihr Wurm nicht stirbt und ihr Feuer nicht verlischt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Argert dich dein Fuli, so haue ihn ab. Es ist dir besser, daß du lahm zum Leben eingehest, denn daü du zwei Fuße habest und werdest in die Holle geworfen, in das ewige Feuer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'da ihr Wurm nicht stirbt und ihr Feuer nicht verlischt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Argert dich dein Auge, so wirfs von dir. Es ist dir besser, daß du einaugig in das Reich Gottes gehest, denn daß du zwei Augen habest und werdest in das hollische Feuer geworfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'da ihr Wurm nicht stirbt und ihr Feuer nicht verlischt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Es muß alles mit Feuer gesalzen werden, und alles Opfer wird mit Salz gesalzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Das Salz ist gut; so aber das Salz dumm wird, womitwird man würzen? Habt Salz bei euch und habt Frieden untereinander!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Und er machte sich auf und kam von dannen in die Orter des judischen Landes jenseit des Jordans. Und das Volk ging abermal mit Haufen zu ihm, und wie seine Gewohnheit war, lehrete er sie abermal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Und die Pharisaer traten zu ihm und fragten ihn, ob ein Mann sich scheiden moge von seinem Weibe; und versuchten ihn damit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Er antwortete aber und sprach: Was hat euch Mose geboten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Sie sprachen: Mose hat zugelassen, einen Scheidebrief zu schreiben und sich zu scheiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jesus antwortete und sprach zu ihnen: Urn eures Herzens Hartigkeit willen hat er euch solch Gebot geschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Aber von Anfang der Kreatur hat sie Gott geschaffen ein Mannlein und Fraulein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Darum wird der Mensch seinen Vater und Mutter lassen und wird seinem Weibe anhangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'und werden sein die zwei ein Fleisch. So sind sie nun nicht zwei, sondern ein Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Was denn Gott zusammengefuget hat, soil der Mensch nicht scheiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Und daheim fragten ihn abermal seine Junger urn dasselbige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Und er sprach zu ihnen: Wer sich scheidet von seinem Weibe und freiet eine andere, der bricht die Ehe an ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Und so sich ein Weib scheidet von ihrem Manne und freiet einen andern, die bricht ihre Ehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Und sie brachten Kindlein zu ihm, daü ersie anruhrete. Die Junger aber fuhren die an, die sie trugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Da es aber Jesus sah, ward er unwillig und sprach zu ihnen: Lafit die Kindlein zu mir kommen und wehret ihnen nicht; denn solcher ist das Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Wahrlich, ich sage euch, wer das Reich Gottes nicht empfanget als ein Kindlein, der wird nicht hineinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Und er herzete sie und legtedie Hande auf sie und segnete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Und da er hinausgegangen war auf den Weg, lief einer vorne vor, kniete vor ihn und fragte ihn: Guter Meister, was soil ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Aber Jesus sprach zu ihm: Was heiliest du mich gut? Niemand ist gut denn der einige Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Du weifiest ja die Gebote wohl: Du sollst nicht ehebrechen. Du sollst nicht toten. Du sollst nicht stehlen. Du sollst nicht falsch Zeugnis reden. Du sollst niemand tauschen. Ehre deinen Vater und Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Er antwortete aber und sprach zu ihm: Meister, das habe ich alles gehalten von meiner Jugend auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Und Jesus sah ihn an und liebte ihn und sprach zu ihm: Eines fehlet dir. Gehe hin, verkaufe alles, was du hast, und gib\'s den Armen, so wirst du einen Schatz im Himmel haben; und komm, folge mir nach und nimm das Kreuz auf dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Er aber ward Unmuts uber der Rede und ging traurig davon; denn er hatte viele Guter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Und Jesus sah urn sich und sprach zu seinen Jungern: Wie schwerlich werden die Reichen in das Reich Gottes kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Die Junger aber entsetzten sich uber seine Rede. Aber Jesus antwortete wiederum und sprach zu ihnen: Liebe Kinder, wie schwerlich ist\'s, daß die, so ihr Vertrauen auf Reichtum setzen, ins Reich Gottes kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Es ist leichter, daß ein Kamel durch ein Nadelohr gehe, denn daß ein Reicher ins Reich Gottes komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Sie entsetzten sich aber noch viel mehr und sprachen untereinander: Wer kann denn selig werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jesus aber sah sie an und sprach: Bei den Menschen ist\'s unmoglich, aber nicht bei Gott; denn alle Dinge sind moglich bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Da sagte Petrus zu ihm: Siehe, wir haben alles verlassen und sind dir nachgefolget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesus antwortete und sprach: Wahrlich, ich sage euch, es ist niemand, so er verlalit Haus Oder Brüder Oder Schwestern Oder Vater Oder Mutter Oder Weib Oder Kinder Oder Acker um meinetwillen und um des Evangeliumswillen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'der nicht hundertfaltig empfange jetzt in dieser Zeit Hauser und Bruder und Schwestern und Mutter und Kinder und Acker mit Verfolgungen und in der zukünftigen Welt das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Viele aber werden die Letzten sein, die die Ersten sind, und die Ersten sein, die die Letzten sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Sie waren aber auf dem Wege und gingen hinauf gen Jerusalem. Und Jesus ging vor ihnen; und sie entsetzten sich, folgeten ihm nach und furchteten sich. Und Jesus nahm abermal zu sich die Zwolfe und sagte ihnen, was ihm widerfahren würde:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Siehe, wirgehen hinauf gen Jerusalem, und des Menschen Sohn wird uberantwortet werden den Hohenpriestern und Schriftgelehrten; und sie werden ihn verdammen zum Tode und überantworten den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Die werden ihn verspotten und geilieln und verspeien und toten; und am dritten Tage wird er auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Da gingen zu ihm Jakobus und Johannes, die Sohne des Zebedaus, und sprachen: Meister, wir wollen, daß du uns tuest, was wir dich bitten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Er sprach zu ihnen: Was wolit, ihr, daß ich euch tue?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Sie sprachen zu ihm: Gib uns, daß wir sitzen, einer zu deiner Rechten und einer zu deiner Linken, in deiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jesus aber sprach zu ihnen: Ihrwisset nicht, was ihr bittet. Konnt ihr den Kelch trinken, den ich trinke, und euch taufen lassen mit der Taufe, da ich mit getauft werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Sie sprachen zu ihm: Ja, wir konnen es wohl. Jesus aber sprach zu ihnen: Zwar ihrwerdet den Kelch trinken, den ich trinke, und getauft werden mit der Taufe, da ich mit getauft werde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'zu sitzen aberzu meiner Rechten und zu meiner Linken, stehet mir nicht zu, euch zu geben, sondern welchen es bereitet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Und da das die Zehn horeten, wurden sie unwillig uber Jakobus und Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Aber Jesus rief sie und sprach zu ihnen: Ihr wisset, daß die weltlichen Fursten herrschen, und die Machtigen unter ihnen haben Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Aber also soil es unter euch nicht sein, sondern welcher will groü werden unter euch, der soil euer Diener sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'Und welcher unter euch will der Vornehmste werden, der soil aller Knecht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Denn auch des Menschen Sohn ist nicht kommen, daß ersich dienen lasse, sondern daß er diene und gebe sein Leben zur Bezahlung fur viele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Und sie kamen gen Jericho. Und da er aus Jericho ging, er und seine Jünger und ein groü Volk, da sali ein Blinder, Bartimaus, des Timaus Sohn, am Wege und bettelte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Und da er horete, daß es Jesus von Nazareth war, fing er an zu schreien und zu sagen: Jesu, du Sohn Davids, erbarme dich mein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Und viele bedraueten ihn, ersollte stillschweigen. Er aber schrie viel mehr: Du Sohn Davids, erbarme dich mein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Und Jesus stund stille und lieli ihn rufen. Und sie riefen den Blinden und sprachen zu ihm: Sei getrost, stehe auf! Er rufet dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Und erwarf sein Kleid von sich, stund auf und kam zu Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Und Jesus antwortete und sprach zu ihm: Was willst du, daß ich dir tun soil? Der Blinde sprach zu ihm: Rabuni, daß ich sehend werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus aber sprach zu ihm: Gehe hin; dein Glaube hat dir geholfen. Und alsbald ward er sehend und folgte ihm nach auf dem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Und da sie nahe zu Jerusalem kamen, gen Bethphage und Bethanien an den Olberg, sandte er seiner Jünger zwei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'und sprach zu ihnen: Gehet hin in den Flecken, der vor euch liegt, und alsbald; wenn ihr hineinkommt, werdet ihr finden ein Füllen angebunden, auf welchem nie kein Mensch gesessen ist. Loset es ab und führet es her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Und so jemand zu euch sagen wird: Warum tut ihr das? so sprechet: Der Herr bedarf sein; so wird er\'s bald hersenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Und gingen hin und fanden das Füllen gebunden an der Tür, draulien auf dem Wegscheid, und loseten es ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Und etliche, die da stunden, sprachen zu ihnen: Was machet ihr, daß ihr das Füllen abloset?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Sie sagten aber zu ihnen, wie ihnen Jesus geboten hatte; und die lielien\'s zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Und sie führeten das Füllen zu Jesu und legten ihre Kleider darauf, und er setzte sich darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Viele aber breiteten ihre Kleider auf den Weg. Etliche hieben Maien von den Baumen und streueten sie auf den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Und die vorne vorgingen, und die hernach folgeten, schrieen und sprachen: Hosianna! Gelobet sei, der da kommt in dem Namen des Herrn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Gelobet sei das Reich unsers Vaters David, das da kommt in dem Namen des Herrn! Hosianna in der Hohe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Und der Herr ging ein zu Jerusalem und in den Tempel. Und er besah alles; und am Abend ging er hinaus gen Bethanien mit den Zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Und des andern Tages, da sie von Bethanien gingen, hungerte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Und sah einen Feigenbaum von feme, der Blatter hatte. Da trat er hinzu, ob er etwas darauf fande. Und da er hinzukam, fand er nichts denn nur Blatter; denn es war noch nicht Zeit, daß Feigen sein sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Und Jesus antwortete und sprach zu ihm: Nun esse von dir niemand keine Frucht ewiglich! Und seine Jünger horeten das.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Und sie kamen gen Jerusalem. Und Jesus ging in den Tempel, fing an und trieb aus die Verkaufer und Kaufer in dem Tempel; und die Tische der Wechsler und die Stühle der T aubenkramer stieft, er urn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'und lieft nicht zu, daß jemand etwas durch den Tempel truge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Und erlehrete und sprach zu ihnen: Stehet nicht geschrieben: Mein Haus soil heiften ein Bethaus alien Vblkern? Ihr aber habt eine Mordergrube daraus gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Und es kam vordie Schriftgelehrten und Hohenpriester; und sie trachteten, wie sie ihn umbrachten. Sie furchteten sich aber vor ihm; denn alles Volk verwunderte sich seiner Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Und des Abends ging er hinaus vor die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Und am Morgen gingen sie voruber und sahen den Feigenbaum, daß er verdorret war bis auf die Wurzel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Und Petrus gedachte daran und sprach zu ihm: Rabbi, siehe, der Feigenbaum, den du verflucht hast, ist verdorret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jesus antwortete und sprach zu ihnen: Habt Glauben an Gotti');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Wahrlich, ich sage euch, werzu diesem Berge sprache: Heb\' dich und wirfdich ins Meer! und zweifelte nicht in seinem Herzen, sondern glaubte, daß es geschehen würde, was er sagt, so wird\'s ihm geschehen, was er sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Darum sage ich euch: Alles, was ihr bittet in eurem Gebet, glaubet nur, daß ihr\'s empfangen werdet, so wird\'s euch werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Und wenn ihr stehet und betet, so vergebet, wo ihr etwas wider jemand habt, auf daß auch euer Vater im Himmel euch vergebe eure Fehle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Wenn ihr aber nicht vergeben werdet, so wird auch euer Vater, der im Himmel ist, eure Fehle nicht vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Und sie kamen abermal gen Jerusalem. Und da er in den Tempel ging, kamen zu ihm die Hohenpriester und Schriftgelehrten und die Altesten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'und sprachen zu ihm: Aus was fur Macht tust du das, und wer hat dir die Macht gegeben, daß du solches tust?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen; antwortet mir, so will ich euch sagen, aus was fur Macht ich das tue:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Die Taufe Johannes, war sie vom Himmel Oder von Menschen? Antwortet mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Und sie gedachten bei sich selbst und sprachen: Sagen wir, sie war vom Himmel, so wird er sagen: Warum habt ihr denn ihm nicht geglaubet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Sagen wir aber, sie war von Menschen, so furchten wir uns vor dem Volk. Denn sie hielten alle, daß Johannes ein rechter Prophet ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Und sie antworteten und sprachen zu Jesu: Wir wissen\'s nicht. Und Jesus antwortete und sprach zu ihnen: So sage ich euch auch nicht, aus was fur Macht ich solches tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Und erfing an, zu ihnen durch Gleichnisse zu reden: Ein Mensch pflanzete einen Weinberg und führete einen Zaun darum und grub eine Kelter und bauete einen Turm und tat ihn aus den Weingartnern und zog uber Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Und sandte einen Knecht, da die Zeit kam, zu den Weingartnern, daß er von den Weingartnern nahme von der Frucht des Weinberges.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Sie nahmen ihn aber und staupten ihn und lieften ihn leer von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Abermal sandte erzu ihnen einen andern Knecht; demselben zerwarfen sie den Kopf mit Steinen und lieften ihn geschmahet von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Abermal sandte er einen andern, denselben toteten sie; und viele andere: etliche staupten sie, etliche toteten sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Da hatte er noch einen einigen Sohn, der war ihm lieb; den sandte erzum letzten auch zu ihnen und sprach: Sie werden sich vor meinem Sohn scheuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Aberdieselben Weingartner sprachen untereinander: Dies ist der Erbe; kommt, laftt uns ihn toten, so wird das Erbe unser sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Und sie nahmen ihn und toteten ihn und warfen ihn heraus vor den Weinberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Was wird nun der Herr des Weinberges tun? Er wird kommen und die Weingartner umbringen und den Weinberg andern geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Habt ihr auch nicht gelesen diese Schrift: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein worden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'von dem Herrn ist das geschehen, und es ist wunderbarlich vor unsern Augen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Und sie trachteten danach, wie sie ihn griffen, und furchteten sich doch vor dem Volk; denn sie vernahmen, daß er auf sie dieses Gleichnis geredet hatte. Und sie liefien ihn und gingen davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Und sie sandten zu ihm etliche von den Pharisaern und des Herodes Dienern, dafi sie ihn fingen in Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Und sie kamen und sprachen zu ihm: Meister, wir wissen, daß du wahrhaftig bist und fragest nach niemand; denn du achtest nicht das Ansehen der Menschen, sondern du lehrest den Weg Gottes recht. Ist\'s recht, daß man dem Kaiser Zins gebe, Oder nicht? Sollen wir ihn geben Oder nicht geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Er aber merkete ihre Heuchelei und sprach zu ihnen: Was versuchet ihr mich? Bringet mir einen Groschen, daß ich ihn sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Und sie brachten ihm. Da sprach er: Wes ist das Bild und die Uberschrift? Sie sprachen zu ihm: Des Kaisers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Da antwortete Jesus und sprach zu ihnen: So gebet dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist. Und sie verwunderten sich sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Da traten die Sadduzaerzu ihm, die da halten, es sei keine Auferstehung; die fragten ihn und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Meister, Mose hat uns geschrieben: Wenn jemands Bruder stirbt und laftt ein Weib und laftt keine Kinder, so soli sein Bruder desselbigen Weib nehmen und seinem Bruder Samen erwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Nun sind sieben Bruder gewesen. Der erste nahm ein Weib; der starb und lieft keinen Samen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Und der andere nahm sie und starb und lieft auch nicht Samen. Derdritte desselbigengleichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Und nahmen sie alle sieben und lieften nicht Samen. Zuletzt nach alien starb das Weib auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Nun in der Auferstehung, wenn sie auferstehen, wessen Weib wird sie sein unter ihnen? Denn sieben haben sie zum Weibe gehabt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Da antwortete Jesus und sprach zu ihnen: Ist\'s nicht also? Ihr irret darum, daß ihr nichts wisset von der Schrift noch von der Kraft Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Wenn sie von den Toten auferstehen werden, so werden sie nicht freien noch sich freien lassen, sondern sie sind wie die Engel im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Aber von den Toten, daß sie auferstehen werden, habt ihr nicht gelesen im Buch des Mose bei dem Busch, Wie Gott zu ihm sagte und sprach: Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Gott aber ist nicht der Toten, sondern der Lebendigen Gott. Darum irret ihr sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Und es trat zu ihm der Schriftgelehrten einer, der ihnen zugehoret hatte, wie sie sich miteinander befragten, und sah, daß er ihnen fein geantwortet hatte, und fragte ihn: Welches ist das vornehmste Gebotvor alien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jesus aber antwortete ihm: Das vornehmste Gebot vor alien Geboten ist das: Hore, Israel, der Herr, unser Gott, ist ein einiger Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Und: Du sollst Gott, deinen Herrn, lieben von ganzem Herzen, von ganzer Seele, von ganzem Gemute und von alien deinen Kraften. Das ist das vornehmste Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Und das andere ist ihm gleich: Du sollst deinen Nachsten lieben wie dich selbst; es ist kein ander grofter Gebot denn diese.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Und der Schriftgelehrte sprach zu ihm: Meister, du hast wahrlich recht geredet; denn es ist ein Gott, und ist kein anderer aufter ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Und denselbigen lieben von ganzem Herzen; von ganzem Gemute, von ganzer Seele und von alien Kraften und lieben seinen Nachsten wie sich selbst, das ist mehr denn Brandopfer und alle Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Da Jesus aber sah, daß er vernünftiglich antwortete, sprach er zu ihm: Du bist nicht feme von dem Reich Gottes. Und es durfte ihn niemand weiter fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Und Jesus antwortete und sprach, da er lehrete im Tempel: Wie sagen die Schriftgelehrten, Christus sei Davids Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Er aber, David, spricht durch den Heiligen Geist: Der Herr hat gesagt zu meinem Herrn: Setze dich zu meiner Rechten, bis daß ich lege deine Feinde zum Schemel deiner Fufte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Da heiftt ihn ja David seinen Herrn; woher ist er denn sein Sohn? Und viel Volks horete ihn gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Und er lehrete sie und sprach zu ihnen: Sehet euch vor vor den Schriftgelehrten, die in langen Kleidern gehen und lassen sich gerne auf dem Markte gruften');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'und sitzen gerne obenan in den Schulen und über Tisch im Abendmahl;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'sie fressen der Witwen Hauser und wenden langes Gebet vor: dieselben werden desto mehr Verdammnis empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Und Jesus setzte sich gegen den Gotteskasten und schauete, wie das Volk Geld einlegte in den Gotteskasten. Und viel Reiche legten viel ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Und es kam eine arme Witwe und legte zwei Scherflein ein; die machen einen Heller.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Und er rief seine Jünger zu sich und sprach zu ihnen: Wahrlich, ich sage euch, diese arme Witwe hat mehr in den Gotteskasten gelegt denn alle, die eingelegt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Denn sie haben alle von ihrem übrigen eingelegt; diese aber hat von ihrer Armut alles, was sie hatte, ihre ganze Nahrung, eingelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Und da er aus dem Tempel ging, sprach zu ihm seiner Jünger einer: Meister, siehe, welche Steine und welch ein Bau ist das!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Und Jesus antwortete und sprach zu ihm: Siehest du wohl alien diesen groften Bau? Nicht ein Stein wird auf dem andern bleiben, der nicht zerbrochen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Und da er auf dem Olberge saft gegenüber dem Tempel, fragten ihn besonders Petrus und Jakobus und Johannes und Andreas:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Sage uns, wann wird das alles geschehen, und was wird das Zeichen sein wann das alles soli vollendet werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jesus antwortete ihnen und fing an zu sagen: Sehet zu, daß euch nicht jemand verfuhre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Denn es werden viele kommen unter meinem Namen und sagen: Ich bin Christus, und werden viele verfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Wenn ihr aber horen werdet von Kriegen und Kriegsgeschrei, so furchtet euch nicht; denn es muli also geschehen. Aber das Ende ist noch nicht da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Es wird sich ein Volk über das andere emporen und ein Konigreich über das andere. Und es werden geschehen Erdbeben hin und wieder, und wird sein teure Zeit und Schrecken. Das ist der Not Anfang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ihr aber, sehet euch vor! Denn sie werden euch uberantworten vor die Rathauser und Schulen; und ihr musset gestaupet werden und vor Fursten und Konige musset ihr gefuhret werden um meinetwillen zu einem Zeugnis über sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Und das Evangelium muli zuvor geprediget werden unter alle Volker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Wenn sie euch nun führen und überantworten werden, so sorget nicht, was ihr reden sollt, und bedenket euch nicht zuvor, sondern was euch zu derselbigen Stunde gegeben wird, das redet. Denn ihr seid\'s nicht, die da reden, sondern der Heilige Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Es wird aber uberantworten ein Bruder den andern zum Tode und der Vater den Sohn, und die Kinder werden sich emporen wider die Eltern und werden sie helfen toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Und werdet gehasset sein von jedermann um meines Namens willen. Wer aber beharret bis an das Ende, der wird selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Wenn ihr aber sehen werdet den Greuel der Verwüstung, von dem der Prophet Daniel gesagt hat, daß er stehet, da er nicht soil (wer es lieset, der vernehme es!), alsdann, wer in Judaa ist, der fliehe auf die Berge;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'und wer auf dem Dache ist, dersteige nicht hernieder ins Haus und komme nicht hinein, etwas zu holen aus seinem Hause;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'und wer auf dem Felde ist, der wende sich nicht um, seine Kleider zu holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Wehe aber den Schwangern und Saugerinnen zu der Zeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Bittet aber, daß eure Flucht nicht geschehe im Winter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Denn in diesen Tagen werden solche Trubsale sein, als sie nie gewesen sind bisher vom Anfang der Kreaturen, die Gott geschaffen hat, und als auch nicht werden wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Und so der Herr diese Tage nicht verkurzt hatte, wurde kein Mensch selig; aber um der Auserwahlten willen, die er auserwahlet hat, hat er diese Tage verkurzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Wenn nun jemand zu der Zeit wird zu euch sagen: Siehe, hier ist Christus! siehe, da ist er! so glaubet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Denn es werden sich erheben falsche Christi und falsche Propheten, die Zeichen und Wunder tun, daß sie auch die Auserwahlten verfuhren, so es moglich ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Ihr aber, sehet euch vor! Siehe, ich hab\'s euch alles zuvor gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Aber zu der Zeit, nach dieser Trubsal, werden Sonne und Mond ihren Schein verlieren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Und die Sterne werden vom Himmel fallen, und die Krafte der Himmel werden sich bewegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Und dann werden sie sehen des Menschen Sohn kommen in den Wolken mit grolier Kraft und Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Und dann wird er seine Engel senden und wird versammeln seine Auserwahlten von den vier Winden, von dem Ende der Erde bis zum Ende der Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'An dem Feigenbaum lernet ein Gleichnis. Wenn jetzt seine Zweige saftig werden und Blatter gewinnen, so wisset ihr, daß der Sommer nahe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Also auch, wenn ihr sehet, daß solches geschiehet, so wisset, daß es nahe vor der Tur ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Wahrlich, ich sage euch, dies Geschlecht wird nicht vergehen, bis daß dies alles geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Himmel und Erde werden vergehen; meine Worte aber werden nicht vergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Von dem Tage aber und der Stunde weili niemand, auch die Engel nicht im Himmel, auch der Sohn nicht, sondern allein der Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Sehet zu, wachet und betet; denn ihr wisset nicht, wann es Zeit ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Gleich wie ein Mensch, der uber Land zog und lieli sein Haus und gab seinen Knechten Macht, einem jeglichen sein Werk, und gebot dem Turhuter, er sollte wachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'So wachet nun; denn ihr wisset nicht, wann der Herr des Hauses kommt, ob er kommt am Abend Oder zu Mitternacht Oder um den Hahnenschrei Oder des Morgens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'auf daß er nicht schnell komme und finde euch schlafend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Was ich aber euch sage, das sage ich alien: Wachet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Und nach zwei Tagen war Ostern und die Tage der sulien Brote. Und die Hohenpriester und Schriftgelehrten suchten, wie sie ihn mit List griffen und toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Sie sprachen aber: Ja nicht auf das Fest, daß nicht ein Aufruhr im Volk werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Und da er zu Bethanien war in Simons, des Aussatzigen, Hause und sali zu Tisch, da kam ein Weib, die hatte ein Glas mit ungefalschtem und kostlichem Nardenwasser; und sie zerbrach das Glas und goli es auf sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Da waren etliche, die wurden unwillig und sprachen: Was soil doch dieser Unrat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Man konnte das Wasser um mehr denn dreihundert Groschen verkauft haben und dasselbe den Armen geben. Und murreten uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jesus aber sprach: Lasset sie mit Frieden! Was bekümmert ihr sie? Sie hat ein gut Werk an mir getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ihr habt allezeit Arme bei euch; und wann ihr wollet, konnet ihr ihnen Gutes tun; mich aber habt ihr nicht allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Sie hat getan, was sie konnte; sie ist zuvorkommen, meinen Leichnam zu salben zu meinem Begrabnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Wahrlich, ich sage euch, wo dies Evangelium geprediget wird in aller Welt, da wird man auch das sagen zu ihrem Gedachtnis, was sie jetzt getan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Und Judas Ischariot, einervon den Zwolfen, ging hin zu den Hohenpriestern, daß er ihn verriete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Da sie das horeten, wurden sie froh und verhiefien, ihm das Geld zu geben. Und ersuchte, wie er ihn füglich verriete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Und am ersten Tagedersußen Brote, da man das Osterlamm opferte, sprachen seine Jünger zu ihm: Wo willst du, daß wir hingehen und bereiten, daß du das Osterlamm essest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Und er sandte seiner Jungerzwei und sprach zu ihnen: Gehet hin in die Stadt, und es wird euch ein Mensch begegnen, der tragt einen Krug mit Wasser; folget ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Und wo er eingehet, da sprechet zu dem Hauswirte: Der Meister laßt dir sagen: Wo ist das Gasthaus, darinnen ich das Osterlamm esse mit meinen Jungern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Und erwird euch einen großen Saal zeigen, der gepflastert und bereit ist; daselbst richtet fur uns zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Und die Jünger gingen aus und kamen in die Stadt und fanden\'s, wie er ihnen gesagt hatte; und bereiteten das Osterlamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Am Abend aber kam er mit den Zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Und als sie zu Tische saßen und aßen, sprach Jesus: Wahrlich, ich sage euch, einer untereuch, der mit mir isset, wird mich verraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Und sie wurden traurig und sagten zu ihm, einer nach dem andern: Bin ich\'s? und der andere: Bin ich\'s?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Er antwortete und sprach zu ihnen: Einer aus den Zwolfen, der mit mir in die Schüssel tauchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Zwar des Menschen Sohn gehet hin, wie von ihm geschrieben stehet; wehe aber dem Menschen, durch welchen des Menschen Sohn verraten wird! Es ware demselben Menschen besser, daß er nie geboren ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Und indem sie aßen, nahm Jesus das Brot, dankete und brach\'s und gab\'s ihnen und sprach: Nehmet, esset; das ist mein Leib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Und nahm den Kelch und dankete und gab ihnen den; und sie tranken alle daraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Und er sprach zu ihnen: Das ist mein Blut des Neuen Testaments, das fur viele vergossen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Wahrlich, ich sage euch, daß ich hinfort nicht trinken werde vom Gewachse des Weinstocks bis auf den Tag, da ich\'s neu trinke in dem Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Und da sie den Lobgesang gesprochen hatten, gingen sie hinaus an den Olberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Und Jesus sprach zu ihnen: Ihr werdet euch in dieser Nacht alle an mir argern. Denn es stehet geschrieben: Ich werde den Hirten schlagen, und die Schafe werden sich zerstreuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Aber nachdem ich auferstehe, will ich vor euch hingehen nach Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Petrus aber sagte zu ihm: Und wenn sie sich alle argerten, so wollte doch ich mich nicht argern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Und Jesus sprach zu ihm: Wahrlich, ich sage dir, heute in dieser Nacht, ehe denn der Hahn zweimal krahet, wirst du mich dreimal verleugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Er aber redete noch weiter: Ja, wenn ich mit dir auch sterben mußte, wollt\' ich dich nicht verleugnen. Desselbigengleichen sagten sie alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Und sie kamen zu dem Hofe mit Namen Gethsemane. Und er sprach zu seinen Jungern: Setzet euch hier, bis ich hingehe und bete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Und nahm zu sich Petrus und Jakobus und Johannes und fing an zu zittern und zu zagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Und sprach zu ihnen: Meine Seele ist betrubt bis an den Tod; enthaltet euch hier und wachet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Und ging ein wenig fürbaß, fiel auf die Erde und betete, daß, so es moglich ware, die Stunde voruberginge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'und sprach: Abba, mein Vater, es ist dir alles moglich, uberhebe mich dieses Kelchs; doch nicht was ich will, sondern was du willst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Und kam und fand sie schlafend und sprach zu Petrus: Simon, schlafest du? Vermochtest du nicht eine Stunde zu wachen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Wachet und betet, daß ihr nicht in Versuchung fallet! Der Geist ist willig; aber das Fleisch ist schwach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Und ging wieder hin und betete und sprach dieselbigen Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Und kam wieder und fand sie abermal schlafend; denn ihre Augen waren voll Schlafs, und wußten nicht, was sie ihm antworteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Und er kam zum drittenmal und sprach zu ihnen: Ach, wollt ihr nun schlafen und ruhen? Es ist genug; die Stunde ist kommen. Siehe, des Menschen Sohn wird uberantwortet in der Sunder Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Stehet auf, laßt uns gehen; siehe, der mich verrat, ist nahe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Und alsbald, da er noch redete, kam herzu Judas, der Zwolfen einer, und eine große Schar mit ihm, mit Schwertern und mit Stangen von den Hohenpriestern und Schriftgelehrten und Altesten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Und der Verrater hatte ihnen ein Zeichen gegeben und gesagt: Welchen ich küssen werde, der ist\'s; den greifet und führet ihn gewiß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Und da er kam, trat er bald zu ihm und sprach zu ihm: Rabbi, Rabbi! und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Die aber legten ihre Hande an ihn und griffen ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Einer aber von denen, die dabeistunden, zog sein Schwert aus und schlug des Hohenpriesters Knecht und hieb ihm ein Ohr ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Und Jesus antwortete und sprach zu ihnen: Ihr seid ausgegangen als zu einem Morder mit Schwertern und mit Stangen, mich zu fangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Ich bin taglich bei euch im Tempel gewesen und habe gelehret, und ihr habt mich nicht gegriffen; aber auf daß die Schrift erfullet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Und die Junger verlielien ihn alle und flohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Und es war ein Jungling, der folgete ihm nach, der war mit Leinwand bekleidet auf der blofien Haut; und die Junglinge griffen ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Er aber lieli die Leinwand fahren und floh bloü von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Und sie fuhreten Jesum zu dem Hohenpriester, dahin zusammenkommen waren alle Hohenpriester und Altesten und Schriftgelehrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Petrus aber folgete ihm nach von feme bis hinein in des Hohenpriesters Palast; und er war da und sali bei den Knechten und warmete sich bei dem Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Aber die Hohenpriester und der ganze Rat suchten Zeugnis wider Jesum, auf daß sie ihn zum Tode brachten, und fanden nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Viele gaben falsch Zeugnis wider ihn; aber ihr Zeugnis stimmte nicht uberein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Und etliche stunden auf und gaben falsch Zeugnis wider ihn und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Wir haben gehoret, daß er sagte: Ich will den Tempel, der mit Handen gemacht ist, abbrechen und in dreien Tagen einen andern bauen, der nicht mit Handen gemacht sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Aber ihr Zeugnis stimmete noch nicht uberein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Und der Hohepriester stund auf unter sie und fragte Jesum und sprach: Antwortest du nichts zu dem, was diese wider dich zeugen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Er aber schwieg stille und antwortete nichts. Da fragte ihn der Hohepriester abermal und sprach zu ihm: Bist du Christus, der Sohn des Hochgelobten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus aber sprach: Ich bin\'s. Und ihr werdet sehen des Menschen Sohn sitzen zur rechten Hand der Kraft und kommen mit des Himmels Wolken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Da zerrili der Hohepriester seinen Rock und sprach: Was bedurfen wir weiter Zeugen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Ihr habt gehoret die Gotteslasterung; was dünket euch? Sie aber verdammeten ihn alle, dati er des Todes schuldig ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Da fingen an etliche, ihn zu verspeien und zu verdecken sein Angesicht und mit Fausten zu schlagen und zu ihm zu sagen: Weissage uns! Und die Knechte schlugen ihn ins Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Und Petrus war danieden im Palast; da kam des Hohenpriester Magde eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Und da sie sah Petrus sich warmen, schauete sie ihn an und sprach: Und du warest auch mit Jesu von Nazareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Er leugnete aber und sprach: Ich kenne ihn nicht, weü J, auch nicht, was du sagest. Und er ging hinaus in den Vorhof; und der Hahn krahete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Und die Magd sah ihn und hub abermal an, zu sagen denen, die dabei stunden: Dieser ist der einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Und er leugnete abermal. Und nach einer kleinen Weile sprachen abermal zu Petrus, die dabeistunden: Wahrlich, du bist der einer; denn du bist ein Galilaer, und deine Sprache lautet gleich also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Er aber fing an, sich zu verfluchen und zu schworen: Ich kenne des Menschen nicht, von dem ihr saget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Und der Hahn krahete zum andernmal. Da gedachte Petrus an das Wort, das Jesus zu ihm sagte: Ehe der Hahn zweimal krahet, wirst du mich dreimal verleugnen. Und er hub an zu weinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Und bald am Morgen hielten die Hohenpriester einen Rat mit den Altesten und Schriftgelehrten, dazu der ganze Rat, und banden Jesum und fuhreten ihn hin und uberantworteten ihn Pilatus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Und Pilatus fragte ihn: Bist du ein Konig der Juden? Er antwortete aber und sprach zu ihm: Du sagst es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Und die Hohenpriester beschuldigten ihn hart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilatus aber fragte ihn abermal und sprach: Antwortest du nichts? Siehe, wie hart sie dich verklagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Jesus aber antwortete nichts mehr, also dati sich auch Pilatus verwunderte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Er pflegte aber ihnen auf das Osterfest einen Gefangenen loszugeben, welchen sie begehrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Es war aber einer, genannt Barabbas, gefangen mit den Aufrührerischen die im Aufruhr einen Mord begangen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Und das Volk ging hinauf und bat, daß er tate, wie er pflegete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilatus aber antwortete ihnen: Wollt ihr, daß ich euch den Konig der Juden losgebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Denn er wulite, daß ihn die Hohenpriester aus Neid uberantwortet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Aber die Hohenpriester reizten das Volk, daß er ihnen viel lieber den Barabbas losgabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilatus aber antwortete wiederum und sprach zu ihnen: Was wollt ihr denn, daß ich tue dem, den ihr schuldiget, er sei ein Konig der Juden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Sie schrieen abermal: Kreuzige ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilatus aber sprach zu ihnen: Was hat er Ubels getan? Aber sie schrieen noch viel mehr: Kreuzige ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilatus aber gedachte, dem Volk genugzutun, und gab ihnen Barabbas los und überantwortete ihnen Jesum, daß er gegeilielt und gekreuziget wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Die Kriegsknechte aber fuhreten ihn hinein in das Richthaus und riefen zusammen die ganze Schar;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'und zogen ihm einen Purpuran und flochten eine dornene Krone und setzten sie ihm auf;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'und fingen an, ihn zu grüften: Gegrüftet seiest du, der Juden Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Und schlugen ihm das Haupt mit dem Rohr und verspeieten ihn und fielen auf die Kniee und beteten ihn an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Und da sie ihn verspottet hatten, zogen sie ihm den Purpur aus und zogen ihm seine eigenen Kleider an und fuhreten ihn aus, daß sie ihn kreuzigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Und zwangen einen, der voruberging, mit Namen Simon von Kyrene; der vom Felde kam (der ein Vater war des Alexander und Rufus), daß er ihm das Kreuz truge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Und sie brachten ihn an die Statte Golgatha, das ist verdolmetscht: Schadelstatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Und sie gaben ihm Myrrhen im Wein zu trinken; und er nahm\'s nicht zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Und da sie ihn gekreuziget hatten, teilten sie seine Kleider und warfen das Los darum, welcherwas überkame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Und es war urn die dritte Stunde, da sie ihn kreuzigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Und es war oben uber ihn geschrieben, was man ihm schuld gab, namlich: Ein Konig der Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Und sie kreuzigten mit ihm zwei Morder, einen zu seiner Rechten und einen zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Da ward die Schrift erfullet, die da sagt: Er ist unter die Ubeltater gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Und die vorübergingen, lasterten ihn und schuttelten ihre Haupter und sprachen: Pfui dich, wie fein zerbrichst du den Tempel und bauest ihn in dreien Tagen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Hilf dir nun selber und steig herab vom Kreuz!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Desselbigengleichen die Hohenpriester verspotteten ihn untereinander samt den Schriftgelehrten und sprachen: Er hat andern geholfen und kann sich selber nicht helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Ist er Christus und Konig in Israel, so steige er nun vom Kreuze, daß wir sehen und glauben. Und die mit ihm gekreuzigt waren, schmaheten ihn auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Und nach dersechsten Stunde ward eine Finsternis uber das ganze Land bis urn die neunte Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Und urn die neunte Stunde rief Jesus laut und sprach: Eli, Eli, lama asabthani? das ist verdolmetscht: Mein Gott, mein Gott, warum hast du mich verlassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Und etliche, die dabeistunden, da sie das horeten, sprachen sie: Siehe, er rufet den Elia!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Da lief einer und fullete einen Schwamm mit Essig und steckte ihn auf ein Rohr und trankete ihn und sprach: Halt, laft sehen, ob Elia komme und ihn herabnehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Aber Jesus schrie laut und verschied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Und der Vorhang im Tempel zerrifi in zwei Stücke, von oben an bis unten aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Der Hauptmann aber, der dabeistund ihm gegenuber und sah, daß er mit solchem Geschrei verschied, sprach er: Wahrlich, dieser Mensch ist Gottes Sohn gewesen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Und es waren auch Weiber da, die von feme solches schaueten, unter welchen war Maria Magdalena und Maria, des kleinen Jakobus und des Joses Mutter, und Salome,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'die ihm auch nachgefolget, da er in Galilaa war, und gedienet hatten, und viel andere, die mit ihm hinauf gen Jerusalem gegangen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Und am Abend, dieweil es der Rusttag war, welcher ist der Vorsabbat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'kam Joseph von Arimathia, ein ehrbarer Ratsherr, welcher auch auf das Reich Gottes wartete; der wagte es und ging hinein zu Pilatus und bat urn den Leichnam Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus aber verwunderte sich, daß er schon tot war, und rief den Hauptmann und fragte ihn, ob er langst gestorben ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Und als er\'s erkundet von dem Hauptmann, gab er Joseph den Leichnam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Und er kaufte eine Leinwand und nahm ihn ab und wickelte ihn in die Leinwand und legte ihn in ein Grab, das war in einen Fels gehauen, und walzete einen Stein vor des Grabes Tur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Aber Maria Magdalena und Maria Joses schaueten zu wo er hingelegt ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Und da der Sabbat vergangen war, kauften Maria Magdalena und Maria des Jakobus und Salome Spezerei, auf daß sie kamen und salbeten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Und sie kamen zum Grabe an einem Sabbater sehrfrühe, da die Sonne aufging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Und sie sprachen untereinander: Wer walzet uns den Stein von des Grabes Tur?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Und sie sahen dahin und wurden gewahr, daß der Stein abgewalzet war; denn er war sehr graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Und sie gingen hinein in das Grab und sahen einen Jungling zur rechten Hand sitzen, der hatte ein lang weift Kleid an. Und sie entsetzten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Er aber sprach zu ihnen: Entsetzet euch nicht! Ihrsuchet Jesum von Nazareth, den Gekreuzigten; er ist auferstanden und ist nicht hier. Siehe da die Statte, da sie ihn hinlegten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Gehet aber hin und sagt\'s seinen Jungern und Petrus, daß er vor euch hingehen wird nach Galilaa; da werdet ihr ihn sehen, wie er euch gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Und sie gingen schnell heraus und flohen von dem Grabe; denn es war sie Zittern und Entsetzen ankommen. Und sagten niemand nichts; denn sie furchteten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Jesus aber, da er auferstanden war frühe am ersten Tage der Sabbater, erschien er am ersten der Maria Magdalena, von welcher er sieben Teufel ausgetrieben hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Und sie ging hin und verkundigte es denen, die mit ihm gewesen waren, die da Leid trugen und weineten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Und dieselbigen, da sie horeten, daß er lebete und ware ihrerschienen, glaubten sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Danach da zwei aus ihnen wandelten, offenbarte er sich unter einer andern Gestalt, da sie aufs Feld gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Und dieselbigen gingen auch hin und verkundigten das den andern; denen glaubten sie auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Zuletzt, da die Elfe zu Tische saften, offenbarete er sich und schalt ihren Unglauben und ihres Herzens Hartigkeit, daß sie nicht geglaubt hatten denen, die ihn gesehen hatten auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Und sprach zu ihnen: Gehet hin in alle Welt und prediget das Evangelium aller Kreatur!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Wer da glaubet und getauft wird, derwird selig werden; wer aber nicht glaubet, derwird verdammt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Die Zeichen aber, die dafolgen werden denen, die da glauben, sind die: In meinem Namen werden sie Teufel austreiben, mit neuen Zungen reden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Schlangen vertreiben, und so sie etwas Todliches trinken, wird\'s ihnen nicht schaden; auf die Kranken werden sie die Hande legen, so wird\'s besser mit ihnen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Und der Herr, nachdem er mit ihnen geredet hatte, ward er aufgehoben gen Himmel und sitzet zur rechten Hand Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Sie aber gingen aus und predigten an alien Orten. Und der Herrwirkte mit ihnen und bekraftigte das Wort durch mitfolgende Zeichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Sintemal sich\'s viele unterwunden haben, zu stellen die Rede von den Geschichten, so unter uns ergangen sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'wie uns das gegeben haben, die es von Anfang selbst gesehen und Diener des Worts gewesen sind:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'habe ich\'s auch fur gut angesehen, nachdem ich\'s alles von Anbeginn erkundet habe, daß ich\'s zu dir, mein guter Theophilus, mit Fleift ordentlich schriebe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'auf daß du gewissen. Grund erfahrest der Lehre, in welcher du unterrichtet bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Zu der Zeit Herodes, des Konigs Judaas, war ein Priester von der Ordnung Abia mit Namen Zacharias und sein Weib von den Tochtern Aarons, welche hieft Elisabeth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Sie waren aber alle beide fromm vor Gott und gingen in alien Geboten und Satzungen des Herrn untadelig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Und sie hatten kein Kind, denn Elisabeth war unfruchtbar; und waren beide wohl betaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Und es begab sich, da er Priesteramts pflegete vor Gott zur Zeit seiner Ordnung');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'nach Gewohnheit des Priestertums, und an ihm war, daß er rauchern sollte, ging er in den Tempel des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Und die ganze Menge des Volks war drauften und betete unter der Stunde des Raucherns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Es erschien ihm aber der Engel des Herrn und stund zur rechten Hand am Rauchaltar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Und als Zacharias ihn sah, erschrak er, und es kam ihn eine Furcht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Aber der Engel sprach zu ihm: Furchte dich nicht, Zacharias; denn dein Gebet ist erhoret, und dein Weib Elisabeth wird direinen Sohn gebaren, des Namen sollst du Johannes heiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Und du wirstdes Freude und Wonne haben, und viele werden sich seiner Geburt freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Denn erwird graft sein vordem Herrn. Wein und stark Getrank wird er nicht trinken und erwird noch im Mutterleibe erfullet werden mit Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Und erwird der Kinder von Israel viele zu Gott, ihrem Herrn, bekehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Und erwird vor ihm hergehen im Geist und Kraft des Elia, zu bekehren die Herzen der Vater zu den Kindern und die Unglaubigen zu der Klugheit der Gerechten, zuzurichten dem Herrn ein bereit Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Und Zacharias sprach zu dem Engel: Wobei soil ich das erkennen? Denn ich bin alt, und mein Weib ist betagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Der Engel antwortete und sprach zu ihm: Ich bin Gabriel, der vor Gott stehet, und bin gesandt, mit dir zu reden, daß ich dir solches verkundigte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Und siehe, du wirst verstummen und nicht reden konnen bis auf den Tag, da dies geschehen wird, darum daß du meinen Worten nicht geglaubet hast, welche sollen erfüllet werden zu ihrer Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Und das Volk wartete auf Zacharias und verwunderte sich, daß er so lange im Tempel verzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Und da er herausging, konnte er nicht mit ihnen reden. Und sie merkten, dafi er ein Gesicht gesehen hatte im Tempel. Und erwinkte ihnen und blieb stumm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Und es begab. sich, da die Zeit seines Amtes aus war, ging er heim in sein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Und nach den Tagen ward sein Weib Elisabeth schwanger und verbarg sich funf Monden und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Also hat mir der Herr getan in den T agen, da. er mich angesehen hat, daß er meine Schmach unter den Menschen von mir nahme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Und im sechsten Mond ward der Engel Gabriel gesandt von Gott in eine Stadt in Galilaa, die heüit Nazareth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'zu einer Jungfrau, die vertrauet war einem Manne mit Namen Joseph vom Hause David; und die Jungfrau hiefi Maria.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Und der Engel kam zu ihr hinein und sprach: Gegruliet seiest du, Holdselige! Der Herr ist mit dir, du Gebenedeiete unter den Weibern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Da sie aber ihn sah, erschrak sie uber seine Rede und gedachte: Welch ein Gruft ist das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Und der Engel sprach zu ihr: Furchte dich nicht, Maria; du hast Gnade bei Gott funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Siehe; du wirst schwanger werden im Leibe und einen Sohn gebaren, des Namen sollst du Jesus heiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Der wird graft und ein Sohn des Hochsten genannt werden, und Gott der Herr wird ihm den Stuhl seines Vaters David geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Und er wird ein Konig sein uber das Haus Jakob ewiglich, und seines Konigreichs wird kein Ende sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Da sprach Maria zu dem Engel: Wie soil das zugehen, sintemal ich von keinem Manne weift?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Der Engel antwortete und sprach zu ihr: Der Heilige Geist wird uber dich kommen, und die Kraft des Hochsten wird dich überschatten; darum auch das Heilige, das von dir geboren wird, wird Gottes Sohn genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Und siehe, Elisabeth, deine Gefreundete, ist auch schwanger mit einem Sohn in ihrem Alter und gehet jetzt im sechsten Mond, die im Geschrei ist, daü sie unfruchtbar sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Denn bei Gott ist kein Ding unmoglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Maria aber sprach: Siehe, ich bin des Herm Magd; mirgeschehe, wie du gesagt hast. Und der Engel schied von ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Maria aber stund auf in den Tagen und ging auf das Gebirge eilends zu der Stadt Juda');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'und kam in das Haus des Zacharias und gruftete Elisabeth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Und es begab sich, als Elisabeth den Gruft Marias horete, hupfete das Kind in ihrem Leibe. Und Elisabeth ward des Heiligen Geistes voll');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'und rief laut und sprach: Gebenedeiet bist du unter den Weibern, und gebenedeiet ist die Frucht deines Leibes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Und woher kommt mir das, dafi die Mutter meines Herrn zu mir kommt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Siehe, da ich die Stimme deines Gruftes horete, hupfete mit Freuden das Kind in meinem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Und o selig bistdu, die du geglaubet hast! Denn es wird vollendet werden, was dir gesagt ist von dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Und Maria sprach: Meine Seele erhebet den Herrn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'und mein Geist freuet sich Gottes, meines Heilandes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Denn er hat die Niedrigkeit seiner Magd angesehen. Siehe, von nun an werden mich selig preisen alle Kindeskinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Denn er hat grofte Dinge an mir getan, der da machtig ist, und des Name heilig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Und seine Barmherzigkeit wahret immer fur und fur bei denen, die ihn furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Er ubet Gewalt mit seinem Arm und zerstreuet, die hoffartig sind in ihres Herzens Sinn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Er stofiet die Gewaltigen vom Stuhl und erhebt die Niedrigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Die Hungrigen fillet er mit Gutern und laftt die Reichen leer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Er denket der Barmherzigkeit und hilft seinem Diener Israel auf,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'wieergeredet hat unsern Vatern, Abraham und seinem Samen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Und Maria blieb bei ihr bei drei Monden; danach kehrete sie wiederum heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Und. Elisabeth kam ihre Zeit, daß sie gebaren sollte; und sie gebar einen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Und ihre Nachbarn und Gefreundeten horeten, daß dar Herr grofte Barmherzigkeit an ihr getan hatte, und freueten sich mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Und es begab sich, am achten Tage kamen sie, zu beschneiden das Kindlein, und hieften ihn nach seinem Vater Zacharias.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Aber seine Mutter antwortete und sprach: Mitnichten, sondern er soil Johannes heiften!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Und sie sprachen zu ihr: Ist doch niemand in deiner Freundschaft, der also heifte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Und sie winkten seinem Vater wie er ihn wollte heiften lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Und erforderte ein Tafelein, schrieb und sprach: Er heiftt Johannes. Und sie verwunderten sich alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Und alsbald ward sein Mund und seine Zunge aufgetan, und redete und lobete Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Und es kam eine Furcht uber alle Nachbarn und diese Geschichte ward ruchbar auf dem ganzen judischen Gebirge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Und alle, die es horeten, nahmen\'s zu Herzen und sprachen: Was, meinest du, will aus dem Kindlein werden? Denn die Hand des Herrn war mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Und sein Vater Zacharias ward des Heiligen Geistes voll, weissagte und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Gelobet sei der Herr, der Gott Israels; denn er hat besucht und erloset sein Volk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'und hat uns aufgerichtet ein Horn des Heils in dem Hause seines Dieners David.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Als er vorzeiten geredet hat durch den Mund seiner heiligen Propheten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'daß er uns errettete von unsern Feinden und von der Hand aller, die uns hassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'und die Barmherzigkeit erzeigete unsern Vatern und gedachte an seinen heiligen Bund');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'und an den Eid, den ergeschworen hat unserm Vater Abraham, uns zu geben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'daß wir, erloset aus der Hand unserer Feinde, ihm dieneten ohne Furcht unser Leben lang');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'in Heiligkeit und Gerechtigkeit, die ihm gefallig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Und du, Kindlein, wirst ein Prophet des Hochsten heiften; du wirst vor dem Herm hergehen, daß du seinen Weg bereitest');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'und Erkenntnis des Heils gebest seinem Volk, die da ist in Vergebung ihrer Sunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'durch die herzliche Barmherzigkeit unsers Gottes, durch welche uns besucht hat der Aufgang aus der Hohe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'auf daß er erscheine denen, die da sitzen in Finsternis und Schatten des Todes und richte unsere Füfte auf den Weg des Friedens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Und das Kindlein wuchs und ward stark im Geist und war in der Wüste, bis daß er sollte hervortreten vor das Volk Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Es begab sich aber zu der Zeit, daß ein Gebot vom Kaiser Augustus ausging, daß alle Welt geschatzt wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Und diese Schatzung war die allererste und geschah zu der Zeit, da Cyrenius Landpfleger in Syrien war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Und jedermann ging, daß er sich schatzen liefte, ein. jeglicher in seine Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Da machte sich auch auf Joseph aus Galilaa, aus der Stadt Nazareth, in das judische Land zur Stadt Davids die da heiftt Bethlehem, darum daß er von dem Hause und Geschlechte Davids war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'auf daß er sich schatzen liefte mit Maria, seinem vertrauten Weibe, die war schwanger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Und als sie daselbst waren, kam die Zeit, daß sie gebaren sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Und sie gebar ihren ersten Sohn und wickelte ihn in Windeln und legte ihn in eine Krippe; denn sie hatten sonst keinen Raum in der Herberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Und es waren Hirten in derselbigen Gegend auf dem Felde bei den Hurden, die huteten des Nachts ihre Herde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'und siehe des Herm Engel trat zu ihnen, und die Klarheit des Herm leuchtete urn sie, und sie furchteten sich sehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Und der Engel sprach zu ihnen: Furchtet euch nicht! Siehe, ich verkundige euch grofte Freude, die allem Volk widerfahren wird;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'denn euch ist heute der Heiland geboren, welcher ist Christus, der Herr, in der Stadt Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Und das habtzum Zeichen: Ihrwerdetfinden das Kind in Windeln gewickelt und in einer Krippe liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Und alsbald war da bei dem Engel die Menge der himmlischen Heerscharen, die lobten Gott und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Ehre sei Gott in der Hohe und Friede auf Erden und den Menschen ein Wohlgefallen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Und da die Engel von ihnen gen Himmel fuhren, sprachen die Hirten untereinander: Laftt uns nun gehen gen Bethlehem und die Geschichte sehen, die da geschehen ist, die uns der Herr kundgetan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Und sie kamen eilend und fanden beide, Maria und Joseph, dazu das Kind in der Krippe liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Da sie es aber gesehen hatten, breiteten sie das Wort aus, welches zu ihnen von diesem Kind gesagt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Und alle, vor die es kam, wunderten sich der Rede, die ihnen die Hirten gesagt hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Maria aber behielt alle diese Worte und bewegete sie in ihrem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Und die Hirten kehreten wieder urn, preiseten und lobten Gott urn alles, was sie gehoret und gesehen hatten, wie denn zu ihnen gesagt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Und da acht Tage urn waren, daß das Kind beschnitten wurde, da ward sein Name genannt Jesus, welcher genannt war von dem Engel, ehe denn er in Mutterleibe empfangen ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Und da die Tage ihrer Reinigung nach dem Gesetz. Moses kamen, brachten sie ihn gen Jerusalem, daß sie ihn darstelleten dem Herm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(wie denn geschrieben stehet in dem Gesetz des Herm: Allerlei Mannlein, das zum ersten die Mutter bricht, soil dem Herm geheiliget heiften),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'und daß sie gaben das Opfer, nachdem gesagt ist im Gesetz des Herm, ein Paar Turteltauben Oder zwo junge Tauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Und siehe, ein Mensch war zu Jerusalem mit Namen Simeon; und derselbe Mensch war fromm und gottesfurchtig und wartete auf den Trost Israels; und der Heilige Geist war in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Und ihm war eine Antwort worden von dem Heiligen Geist, er sollte den Tod nicht sehen, er hatte denn zuvor den Christ des Herrn gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Und kam aus Anregen des Geistes in den Tempel. Und da die Eltern das Kind Jesus in den Tempel brachten, daß sie fur ihn taten, wie man pfleget nach dem Gesetz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'da nahm er ihn auf seine Arme und lobete Gott und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Herr, nun lassestdu deinen Diener im Frieden fahren, wie du gesagt hast;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'denn meine Augen haben deinen Heiland gesehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'welchen du bereitet hast vor alien Volkern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'ein Licht, zu erleuchten die Heiden, und zum Preis deines Volks Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Und sein Vater und Mutter wunderten sich des, das von ihm geredet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Und Simeon segnete sie und sprach zu Maria, seiner Mutter: Siehe, dieser wird gesetzt zu einem Fall und Auferstehen vieler in Israel und zu einem Zeichen, dem widersprochen wird');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(und es wird ein Schwert durch deine Seele dringen), auf daß vieler Herzen Gedanken offenbar werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Und es war eine Prophetin, Hanna, eine Tochter Phanuels, vom Geschlecht Asser; die warwohl betaget und hatte gelebt sieben Jahre mit ihrem Manne nach ihrer Jungfrauschaft');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'und war nun eine Witwe bei vierundachtzig Jahren; die kam nimmervom Tempel, dienete Gott mit Fasten und Beten Tag und Nacht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Dieselbige trat auch hinzu zu derselbigen Stunde und preisete den Herm und redete von ihm zu alien, die da auf die Erlosung zu Jerusalem warteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Und da sie es alles vollendet hatten nach dem Gesetz des Herm, kehrten sie wieder nach Galilaa zu ihrer Stadt Nazareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Aber das Kind wuchs und ward stark im Geist, voller Weisheit; und Gottes Gnade war bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Und seine Eltern gingen alle Jahre gen Jerusalem auf das Osterfest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Und da er zwolf Jahre alt war, gingen sie hinauf gen Jerusalem nach Gewohnheit des Festes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Und da die Tage vollendet waren, und sie wieder nach Hause gingen, blieb das Kind Jesus zu Jerusalem; und seine Eltern wußten\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Sie meineten aber, erware unter den Gefahrten, und kamen eine Tagereise und suchten ihn unter den Gefreundeten und Bekannten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Und da sie ihn nicht fanden gingen siewiederum gen Jerusalem und suchten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Und begab sich, nach dreien Tagen fanden sie ihn im Tempel sitzen mitten unter den Lehrern, daß er ihnen zuhorete und sie fragete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Und alle, die ihm zuhoreten, verwunderten sich seines Verstandes und seiner Antwort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Und da sie ihn sahen, entsetzten sie sich. Und seine Mutter sprach zu ihm: Mein Sohn, warum hast du uns das getan? Siehe, dein Vater und ich haben dich mit Schmerzen gesucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Und er sprach zu ihnen: Was ist\'s, daß ihr mich gesucht habt? Wisset ihr nicht, daß ich sein muß in dem, was meines Vaters ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Und sie verstunden das Wort nicht, das er mit ihnen redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Und er ging mit ihnen hinab und kam gen Nazareth und war ihnen untertan. Und seine Mutter behielt alle diese Worte in ihrem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Und Jesus nahm zu an Weisheit, Alter und Gnade bei Gott und den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'In dem fünfzehnten Jahr des Kaisertums Kaisers Tiberius, da Pontius Pilatus Landpfleger in Judaa war und Herodes ein Vierfurst in Galilaa und sein Bruder Philippus ein Vierfurst in Ituraa und in der Gegend Trachonitis. und Lysanias ein Vierfurst in Abilene,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'da Hannas und Kaiphas Hohepriester waren: da geschah der Befehl Gottes zu Johannes, des Zacharias Sohn, in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Und er kam in alle Gegend urn den Jordan und predigte die Taufe der Buße zur Vergebung der Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'wie geschrieben stehet in dem Buch der Reden Jesaja\'s, des Propheten, der da sagt: Es ist eine Stimme eines Predigers in der Wuste: Bereitet den Weg des Herrn und machet seine Steige richtig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Alle Taler sollen voll werden, und alle Berge und Hugel sollen erniedriget werden; und was krumm ist, soil richtig werden und was uneben ist, soil schlechter Weg werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Und alles Fleisch wird den Heiland Gottes sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Da sprach er zu dem Volk, das hinausging, daß es sich von ihm taufen ließe: Ihr Otterngezuchte, wer hat denn euch geweiset, daß ihr dem zukunftigen Zorn entrinnen werdet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Sehet zu, tut rechtschaffene Fruchte der Buße und nehmet euch nicht vorzu sagen: Wir haben Abraham zum Vater. Denn ich sage euch: Gott kann dem Abraham aus diesen Steinen Kinder erwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Es ist schon die Axt den Baumen an die Wurzel gelegt; welcher Baum nicht gute Fruchte bringet, wird abgehauen und in das Feuer geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Und das Volk fragete ihn und sprach: Was sollen wir denn tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Er antwortete und sprach zu ihnen: Wer zwei Rocke hat, der gebe dem, der keinen hat; und wer Speise hat, tue auch also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Es kamen auch die Zollner, daß sie sich taufen ließen, und sprachen zu ihm: Meister, was sollen denn wir tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Er sprach zu ihnen: Fordert nicht mehr, denn gesetzt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Da fragten ihn auch die, Kriegsleute und sprachen: Was sollen denn wir tun? Und er sprach zu ihnen: Tut niemand Gewalt noch Unrecht und lasset euch begnugen an eurem Solde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Als aber das Volk im Wahn war und dachten aile in ihren Herzen von Johannes, ob er vielleicht Christus ware');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'antwortete Johannes und sprach zu alien: Ich taufe euch mit Wasser; es kommt aber ein Starkerer nach mir, dem ich nicht genugsam bin, daß ich die Riemen seiner Schuhe auflose; der wird euch mit dem Heiligen Geist und mit Feuer taufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'In desselbigen Hand ist die Worfschaufel; und er wird seine Tenne fegen und wird den Weizen in seine Scheuer sammeln und die Spreu wird er mit ewigem Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Und viel, anderes mehr vermahnete und verkundigte er dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Herodes aber der Vierfurst, da er von ihm gestraft ward um der Herodias willen, seines Bruders Weib, und um alles Ubels willen, das Herodes tat -');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'uber das alles legte er Johannes gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Und es begab sich, da sich alles Volk tauten liefi, und Jesus auch getaufet war und betete, dal J sich der Himmel auftat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'Und der Heilige Geist fuhr hernieder in leiblicher Gestalt auf ihn wie eine Taube, und eine Stimme kam aus dem Himmel, die sprach: Du bist mein lieber Sohn, an dem ich Wohlgefallen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Und Jesus ging in das dreifügste Jahr und ward gehalten fur einen Sohn Josephs, welcher war ein Sohn Elis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'der war ein Sohn Matthats, der war ein Sohn Levis, der war ein Sohn Melchis, der war ein Sohn Jannas, der war ein Sohn Josephs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'der war ein Sohn des Mattathias, der war ein Sohn des Amos, der war ein Sohn Nahums, der war ein Sohn Eslis, der war ein Sohn Nanges,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'der war ein Sohn Maaths, der war ein Sohn des Mattathias, der war ein Sohn Semeis, der war ein Sohn Josephs, der war ein Sohn Judas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'der war ein Sohn Johannas, der war ein Sohn Resias, der war ein Sohn Zorobabels, der war ein Sohn Salathiels, der war ein Sohn Neris,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'der war ein Sohn Melchis, der war ein Sohn Addis, der war ein Sohn Kosams, der war ein Sohn Elmodams, der war ein Sohn Hers,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'der war ein Sohn Joses, der war ein Sohn Eliezers, der war ein Sohn Jorems, der war ein Sohn Matthas, der war ein Sohn Levis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'der war ein Sohn Simeons, der war ein Sohn Judas, der war ein Sohn Josephs, der war ein Sohn Jonams, der war ein Sohn Eliakims,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'der war ein Sohn Meleas, der war ein Sohn Menams der war ein Sohn Mattathans, der war ein Sohn Nathans, der war ein Sohn Davids,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'der war ein Sohn Jesses der war ein Sohn Obeds, der war ein Sohn des Boas, der war ein Sohn Salmons, der war ein Sohn Nahassons,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'der war ein Sohn Amminadabs, der war ein Sohn Arams, der war ein Sohn Esroms, der war ein Sohn des Phares, der war ein Sohn Judas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'der war ein Sohn Jakobs, der war ein Sohn Isaaks, der war ein. Sohn Abrahams, der war ein Sohn Tharas, der war ein Sohn Nahors,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'der war ein Sohn Saruchs, der war ein Sohn Ragahus, der war ein Sohn Phalegs, der war ein Sohn Ebers, der war ein Sohn Salas,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'der war ein Sohn Kainans, der war ein Sohn Arphachsads, der war ein Sohn Sems, der war ein Sohn Noahs, der war ein Sohn Lamechs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'der war ein Sohn Mathusalahs, der war ein Sohn Enochs, der war ein Sohn Jareds, der war ein Sohn Maleleels, der war ein Sohn Kainans,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'der war ein Sohn des Enos, der ein Sohn Seths, der war ein Sohn Adams, der war Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jesus aber, voll Heiligen Geistes, kam wieder von dem Jordan und ward vom Geist in die Wuste gefuhret');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'und ward vierzig Tage lang von dem Teufel versucht. Und er ali nichts in denselbigen Tagen. Und da dieselbigen ein Ende hatten, hungerte ihn danach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Der Teufel aber sprach zu ihm: Bist du Gottes Sohn, so sprich zu dem Stein, daß er Brot werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Und Jesus antwortete und sprach zu ihm: Es stehet geschrieben: Der Mensch lebt nicht allein vom Brot, sondern von einem jeglichen Wort Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Und der Teufel fuhrete ihn auf einen hohen Berg und weisete ihm alle Reiche der ganzen Welt in einem Augenblick');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'und sprach zu ihm: Alle diese Macht will ich dir geben und ihre Herrlichkeit; denn sie ist mir übergeben, und ich gebe sie, welchem ich will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'So du nun mich willst anbeten, so soil es alles dein sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jesus antwortete ihm und sprach: Heb\' dich weg von mir, Satan! Es stehet geschrieben: Du sollst Gott, deinen Herrn, anbeten und ihm allein dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Und er fuhrete ihn gen Jerusalem und stellete ihn auf des Tempels Zinne und sprach zu ihm: Bist du Gottes Sohn, so lali dich von hinnen hinunter;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'denn es stehet geschrieben: Er wird befehlen seinen Engeln von dir, daß sie dich bewahren');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'und auf den Handen tragen, auf dafi du nicht etwa deinen Fuli an einen Stein stoßest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jesus antwortete und sprach zu ihm: Es ist gesagt: Du sollst Gott, deinen Herrn, nicht versuchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Und da der Teufel alle Versuchung vollendet hatte, wich er von ihm eine Zeitlang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Und Jesus kam wieder in des Geistes Kraft nach Galilaa; und das Gerucht erscholl von ihm durch alle umliegenden Orte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Und er lehrete in ihren Schulen und ward von jedermann gepreiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Und erkam gen Nazareth, da ererzogen war, und ging in die Schule nach seiner Gewohnheit am Sabbattage und stund auf und wollte lesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Da ward ihm das Buch des Propheten Jesaja gereicht. Und da er das Buch herumwarf, fand er den Ort, da geschrieben stehet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Der Geist des Herrn ist bei mir, derhalben er mich gesalbet hat und gesandt, zu verkündigen das Evangelium den Armen, zu heilen die zerstolienen Herzen, zu predigen den Gefangenen, daß sie los sein sollen, und den Blinden das Gesicht und den Zerschlagenen, daß sie frei und ledig sein sollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'und zu predigen das angenehme Jahr des Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Und als er das Buch zutat, gab er\'s dem Diener und setzte sich. Und aller Augen, die in der Schule waren, sahen auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Und er fing an, zu sagen zu ihnen: Heute ist diese Schrift erfüllet vor euren Ohren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Und sie gaben alle Zeugnis von ihm und wunderten sich der holdseligen Worte, die aus seinem Munde gingen, und sprachen: Ist das nicht Josephs Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Und ersprach zu ihnen: Ihrwerdetfreilichzumir sagen dies Sprichwort: Arzt, hilf dir selber! Denn wie groüe Dinge haben wir gehort zu Kapernaum geschehen? Tue auch also hier in deinem Vaterlande!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Er aber sprach: Wahrlich, ich sage euch, kein Prophet ist angenehm in seinem Vaterlande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Aber in der Wahrheit sage ich euch: Es waren viel Witwen in Israel zu Elias Zeiten, da der Himmel verschlossen war drei Jahre und sechs Monden, da eine große Teurung war im ganzen Lande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'und zu der keiner ward Elia gesandt denn allein gen Sarepta der Sidonier, zu einer Witwe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Und viel Aussatzige waren in Israel zu des Propheten Elisa Zeiten; und der keiner ward gereiniget denn allein Naeman aus Syrien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Und sie wurden voll Zorns alle, die in der Schule waren, da sie das horeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'und stunden auf und stießen ihn zur Stadt hinaus und fuhreten ihn auf einen Hugel des Berges, darauf ihre Stadt gebauet war, daß sie ihn hinabsturzeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Aber er ging mitten durch sie hinweg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Und kam gen Kapernaum, in die Stadt Galilaas, und iehrete sie an den Sabbaten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Und sie verwunderten sich seiner Lehre; denn seine Rede war gewaltig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Und es war ein Mensch in der Schule, besessen mit einem unsaubern Teufel. Und der schrie laut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'und sprach: Halt, was haben wir mit dir zu schaffen, Jesus von Nazareth? Du bist kommen, uns zu verderben. Ich weili, wer du bist, namlich der Heilige Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Und Jesus bedrauete ihn und sprach: Verstumme und fahre aus von ihm! Und der Teufel warf ihn mitten unter sie und fuhr von ihm aus und tat ihm keinen Schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Und es kam eine Furcht uber sie alle, und redeten miteinander und sprachen: Was ist das fur ein Ding? Er gebeut mit Macht und Gewalt den unsaubern Geistern, und sie fahren aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Und es erscholl sein Geschrei in alle Orter des umliegenden Landes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Und er stund auf aus der Schule und kam in Simons Haus. Und Simons Schwieger war mit einem harten Fieber behaftet; und sie baten ihn fur sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Und er trat zu ihr und gebot dem Fieber, und es verließ sie. Und bald stund sie auf und dienete ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Und da die Sonne untergegangen war, alle die, so Kranke hatten mit mancherlei Seuchen, brachten sie zu ihm. Und er legte auf einen jeglichen die Hande und machte sie gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Es fuhren auch die Teufel aus von vielen, schrieen und sprachen: Du bist Christus, der Sohn Gottes. Und er bedrauete sie und ließ sie nicht reden; denn sie wußten, daß er Christus war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Da es aber Tag ward, ging er hinaus an eine wüste Statte; und das Volk suchte ihn, und kamen zu ihm und hielten ihn auf, daß er nicht von ihnen ginge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Er aber sprach. zu ihnen: Ich muß auch andern Stadten das Evangelium predigen vom Reich Gottes; denn dazu bin ich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Und er predigte in den Schulen Galilaas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Es begab, sich aber, da sich das Volk zu ihm drang, zu horen das Wort Gottes, und er stund am See Genezareth');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'und sah zwei Schiffe am See stehen; die Fischer aber waren ausgetreten und wuschen ihre Netze;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'trat er in der Schiffe eines, welches Simons war, und bat ihn, dafi er\'s ein wenig vom Lande führete. Und er setzte sich und Iehrete das Volk aus dem Schiff.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Und als er hatte aufgehort zu reden, sprach er zu Simon: Fahre auf die Hohe und werfet eure Netze aus, daß ihr einen Zug tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Und Simon antwortete und sprach zu ihm: Meister, wir haben die ganze Nacht gearbeitet und nichts gefangen; aber auf dein Wort will ich das Netz auswerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Und da sie das taten, beschlossen sie eine große Menge Fische; und ihr Netz zerriß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Und sie winkten ihren Gesellen, die im andern Schiff waren, daß sie kamen und hulfen ihnen ziehen. Und sie kamen und fülleten beide Schiffe voll, also daß sie sanken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Da das Simon Petrus sah, fiel er Jesu zu den Knieen und sprach: Herr, gehe von mir hinaus; ich bin ein sundiger Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Denn es war ihn ein Schrecken ankommen und alle, die mit ihm waren, uber diesen Fischzug, den sie miteinander getan hatten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'desselbigengleichen auch Jakobus und Johannes, die Sohne des Zebedaus, Simons Gesellen. Und Jesus sprach zu Simon: Furchte dich nicht; denn von nun an wirst du Menschen fangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Und sie fuhreten die Schiffe zu Lande und verließen alles und folgeten ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Und es begab sich, da er in einer Stadt war, siehe, da war ein Mann voll Aussatzes. Da der Jesum sah, fiel er auf sein Angesicht und bat ihn und sprach: Herr, willst du, so kannst du mich reinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Und er streckte die Hand aus und ruhrete ihn an und sprach: Ich will\'s tun; sei gereiniget! Und alsbald ging der Aussatz von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Und er gebot ihm dall, er\'s niemand sagen sollte; sondern gehe hin und zeige dich dem Priester und opfere fur deine Reinigung, wie Mose geboten hat, ihnen zum Zeugnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Es kam aberdie Sage von ihm jeweiter aus; und kam viel Volks zusammen, daß sie horeten und durch ihn gesund wurden von ihren Krankheiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Er aber entwich in die Wuste und betete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Und es begab, sich auf einen Tag, daß er lehrete, und salien da die Pharisaer und Schriftgelehrten, die da kommen waren aus alien Markten in Galilaa und Judaa und von Jerusalem. Und die Kraft des Herrn ging von ihm und half jedermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Und siehe, etliche Manner brachten einen Menschen auf einem Bette, der war gichtbruchig; und sie suchten, wie sie ihn hineinbrachten und vor ihn legten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Und da sie vor dem Volk nicht fanden, an welchem Ort sie ihn hineinbrachten, stiegen sie auf das Dach und lielien ihn durch die Ziegel hernieder mit dem Bettlein, mitten unter sie, vor Jesus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Und da er ihren Glauben sah, sprach er zu ihm: Mensch, deine Sünden sind dirvergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Und die Schriftgelehrten und Pharisaer fingen an zu denken und sprachen: Wer ist der, daß er Gotteslasterung redet? Wer kann Sünden vergeben denn allein Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Da aber Jesus ihre Gedanken merkte, antwortete er und sprach zu ihnen: Was denket ihr in euren Herzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Welches ist leichter zu sagen: Dir sind deine Sünden vergeben? oderzu sagen: Stehe auf und wandle?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Auf daß ihr aber wisset, daß des Menschen Sohn Macht hat auf Erden Sünden zu vergeben, sprach er zu dem Gichtbrüchigen: Ich sage dir, stehe auf und hebe dein Bettlein auf; und gehe heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Und alsbald stund er auf vor ihren Augen und hub das Bettlein auf, darauf er gelegen war, und ging heim und preisete Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Und sie entsetzten sich alle und preiseten Gott und wurden voil Furcht und sprachen: Wir haben heute seltsame Dinge gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Und danach ging eraus und sah einen Zollner mit Namen Levi am Zoll sitzen und sprach zu ihm: Folge mirnach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Und er verlieli alles, stund auf und folgete ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Und Levi richtete ihm ein grofi Mahl zu in seinem Hause; und viel Zollner und andere salien mit ihm zu Tisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Und die Schriftgelehrten und Pharisaer murreten wider seine Junger und sprachen: Warum esset und trinket ihr mit den Zollnern und Sundern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Und Jesus antwortete und sprach zu ihnen: Die Gesunden bedurfen des Arztes nicht, sondern die Kranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Ich bin kommen, zu rufen die Sunder zur Bulie und nicht die Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Sie aber sprachen zu ihm: Warum fasten Johannes Junger so oft und beten so viel, desselbigengleichen der Pharisaer Junger, aber deine Junger essen und trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Er sprach aber zu ihnen: Ihr moget die Hochzeitleute nicht zum Fasten treiben, solange der Brautigam bei ihnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Es wird aber die Zeit kommen, daß der Brautigam von ihnen genommen wird; dann werden sie fasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Und er sagte zu ihnen ein Gleichnis: Niemand flicket einen Lappen vom neuen Kleid auf ein alt Kleid; wo anders, so reilit das neue, und der Lappen vom neuen reimet sich nicht auf das alte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Und niemand fasset Most in alte Schlauche; wo anders, so zerreiliet der Most die Schlauche und wird verschuttet, und die Schlauche kommen urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Sondern den Most soil man in neue Schlauche fassen, so werden sie beide behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Und niemand ist, der vom alten trinkt und wolle bald des neuen; denn er spricht: Der alte ist milder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Und es begab sich an einem Sabbat, daß er durchs Getreide ging; und seine Junger rauften Ahren aus und alien und rieben sie mit den Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Etüche aber der Pharisaer sprachen zu ihnen: Warum tut ihr, was sich nicht ziemet zu tun an den Sabbaten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Und Jesus antwortete und sprach zu ihnen: Habt ihr nicht das gelesen, was David tat, da ihn hungerte, und die mit ihm waren:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'wie er zum Hause Gottes einging und nahm die Schaubrote und ali und gab auch denen, die mit ihm waren, die doch niemand durfte essen ohne die Priester alleine?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Und sprach zu ihnen: Des Menschen Sohn ist ein Herr auch des Sabbats.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Es geschah aber auf einen andern Sabbat, daß er ging in die Schule und lehrete. Und da war ein Mensch, des rechte Hand war verdorret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Aber die Schriftgelehrten und Pharisaer hielten auf ihn, ob er auch heilen wurde am Sabbat, auf daß sie eine Sache wider ihn fanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Er aber merkete ihre Gedanken und sprach zu dem Menschen mit der durren Hand: Stehe auf und tritt hervor! Und er stund auf und trat dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Da sprach Jesus zu ihnen: Ich frage euch: Was ziemet sich zu tun an den Sabbaten, Gutes Oder Boses, das Leben erhalten Oder verderben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Und ersah sie alle umher an und sprach zu dem Menschen: Strecke aus deine Hand! Und er tat\'s. Da ward ihm seine Hand wieder zurechtgebracht, gesund wie die andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Sie aber wurden ganz unsinnig und beredeten sich miteinander, was sie ihm tun wollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Es begab sich aber zu der Zeit, daß er ging auf einen Berg, zu beten; und er blieb uber Nacht in dem Gebet zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Und da es Tag ward, riefer seine Jünger und erwahlete ihrer zwolf, welche er auch Apostel nannte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, welchen er Petrus nannte, und Andreas, seinen Bruder, Jakobus und Johannes, Philippus und Bartholomaus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthaus und Thomas, Jakobus, des Alphaus Sohn, Simon, genannt Zelotes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judas, des Jakobus Sohn, und Judas Ischariot, den Verrater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Und er ging hernieder mit ihnen und trat auf einen Platz im Felde, und der Haufe seiner Junger und eine grofie Menge des Volks von allem judischen Lande und Jerusalem und Tyrus und Sidon, am Meer gelegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'die da kommen waren, ihn zu horen, und daß sie geheilet wurden von ihren Seuchen, und die von unsaubern Geistern umgetrieben wurden, die wurden gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Und alles Volk begehrete, ihn anzurühren, denn es ging Kraft von ihm; und heilete sie alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Und er hub seine Augen auf uber seine Junger und sprach: Selig seid ihr Armen; denn das Reich Gottes ist euer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Selig seid ihr, die ihr hier hungert; denn ihr sollet satt werden. Selig seid ihr, die ihr hier weinet; denn ihr werdet lachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Selig seid ihr, so euch die Menschen hassen und euch absondern und schelten euch und verwerfen euren Namen als einen boshaftigen urn des Menschensohns willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Freuet euch alsdann und hupfet; denn siehe, euer Lohn ist groü im Himmel. Desgleichen taten ihre Vater den Propheten auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Aber dagegen wehe euch Reichen! denn ihr habt euren Trost dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Wehe euch, die ihr voil seid! denn euch wird hungern. Wehe euch, die ihr hier lachet! denn ihr werdet weinen und heulen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Wehe euch, wenn euch jedermann wohl redet! Desgleichen taten ihre Vater den falschen Propheten auch:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Aber ich sage euch, die ihr zuhoret: Liebet eure Feinde; tutdenen wohl, die euch hassen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'segnet die, so euch verfluchen; bittet fur die, so euch beleidigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Und wer dich schlagt auf einen Backen, dem biete den andern auch dar; und wer dir den Mantel nimmt, dem wehre nicht auch den Rock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Wer dich bittet, dem gib; und wer dir das Deine nimmt, da fordere es nicht wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Und wie ihr wollet, daü euch die Leute tun sollen, also tut ihnen gleich auch ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Und so ihr liebet, die euch lieben, was Danks habt ihr davon? Denn die Sunder lieben auch ihre Liebhaber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Und wenn ihr euren Wohltatern wohl tut, was Danks habt ihr davon? Denn die Sunder tun dasselbige auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Und wenn ihr leihet, von denen ihr hoffet zu nehmen, was Danks habt ihr davon? Denn die Sunder leihen den Sundern auch, auf daü sie Gleiches wieder nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Doch aber liebet eure Feinde; tut wohl und leihet, daü ihr nichts dafür hoffet, so wird euer Lohn groü sein, und werdet Kinder des Allerhochsten sein. Denn er ist gütig über die Undankbaren und Boshaftigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Darum seid barmherzig, wie auch euer Vater barmherzig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Richtet nicht, so werdet ihr auch nicht gerichtet. Verdammet nicht, so werdet ihr auch nicht verdammet. Vergebet, so wird euch vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gebt, so wird euch gegeben. Ein voil, gedrückt, gerüttelt und uberflussig Mali wird man in euren Schofi geben; denn eben mit dem Mali, da ihr mit messet, wird man euch wieder messen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Und er sagte ihnen ein Gleichnis: Mag auch ein Blinder einem Blinden den Weg weisen? Werden sie nicht alle beide in die Grube fallen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Der Junger ist nicht über seinen Meister; wenn der Junger ist wie sein Meister, so ist er vollkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Was siehest du aber einen Splitter in deines Bruders Auge, und des Balkens in deinem Auge wirst du nicht gewahr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Oder wie kannst du sagen zu deinem Bruder: Halt stille, Bruder! Ich will den Splitter aus deinem Auge ziehen; und du siehest selbst nicht den Balken in deinem Auge? Du Heuchler! Zieh zuvor den Balken aus deinem Auge und besiehe dann, daü du den Splitter aus deines Bruders Auge ziehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Denn es ist kein guter Baum, derfaule Frucht trage, und kein fauler Baum, der gute Frucht trage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Ein jeglicher Baum wird an seiner eigenen Frucht erkannt. Denn man lieset nicht Feigen von den Dornen auch so lieset man nicht Trauben von den Hecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Ein guter Mensch bringt Gutes hervor aus dem guten Schatz seines Herzens; und ein boshaftiger Mensch bringt Boses hervor aus dem bosen Schatz. seines Herzens. Denn wes das Herz voil ist, des gehet der Mund über.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Was heiliet ihr mich aber Herr, Herr, und tut nicht, was ich euch sage?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Wer zu mir kommt und horet meine Rede und tut sie, den will ich euch zeigen, wem er gleich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Er ist gleich einem Menschen, der ein Haus bauete und grub tief und legte den Grund auf den Fels. Da aber Gewasser kam, da rili der Strom zum Hause zu und mochte es nicht bewegen; denn es war auf den Fels gegrundet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Wer aber horet und nicht tut, der ist gleich einem Menschen, derein Haus bauete auf die Erde ohne Grund; und der Strom rüi zu ihm zu, und es fiel bald, und das Haus gewann einen großen Rifi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Nachdem er aber vor dem Volk ausgeredet hatte, ging ergen Kapernaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Und eines Hauptmanns Knecht lag todkrank, den er wert hielt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Da er aber von Jesu horete, sandte er die Altesten der Juden zu ihm und bat ihn, daß er kame und seinen Knecht gesund machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Da sie aber zu Jesu kamen, baten sie ihn mit Fleiß und sprachen: Er ist es wert, daß du ihm das erzeigest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'denn er hat unser Volk lieb, und die Schule hat er uns erbauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus aber ging mit ihnen hin. Da sie aber nun nicht feme von dem Hause waren, sandte der Hauptmann Freunde zu ihm und ließ ihm sagen: Ach Herr, bemuhe dich nicht! Ich bin nicht wert, daß du unter mein Dach gehest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'darum ich auch mich selbst nicht wurdig geachtet habe, daß ich zu dir kame; sondern sprich ein Wort, so wird mein Knabe gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Denn auch ich bin ein Mensch, der Obrigkeit untertan, und habe Kriegsknechte unter mir und spreche zu einem: Gehe hin! so geht er hin, und zum andern: Komm her! so kommt er, und zu meinem Knecht: Tu das! so tuter\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Da aber Jesus das horete, verwunderte er sich sein und wandte sich urn und sprach zu dem Volk, das ihm nachfolgte: Ich sage euch, solchen Glauben habe ich in Israel nicht funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Und da die Gesandten wiederum nach Hause kamen, fanden sie den kranken Knecht gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Und es begab sich danach, daß er in eine Stadt mit Namen Nain ging; und seiner Junger gingen viel mit ihm und viel Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Als er aber nahe an das Stadttor kam, siehe, da trug man einen Toten heraus, der ein einiger Sohn war seiner Mutter, und sie war eine Witwe. Und viel Volks aus der Stadt ging mit ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Und da sie der Herr sah, jammerte ihn derselbigen und sprach zu ihr: Weine nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Und trat hinzu und ruhrete den Sarg an. Und die Trager stunden. Und er sprach: Jungling, ich sage dir, stehe auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Und der Tote richtete sich auf und fing an zu reden. Und er gab ihn seiner Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Und es kam sie alle eine Furcht an und preiseten Gott und sprachen: Es ist ein großer Prophet unter uns aufgestanden, und: Gott hat sein Volk heimgesucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Und diese Rede von ihm erscholl in das ganze judische Land und in alle umliegenden Lander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Und es verkundigten Johannes seine Junger das alles. Und er rief zu sich seiner Junger zwei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'und sandte sie zu Jesu und ließ ihm sagen: Bist du, der da kommen soli, Oder sollen wir eines andern warten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Da aber die Manner zu ihm kamen, sprachen sie: Johannes der Taufer hat uns zu dir gesandt und laßt dir sagen: Bist du, der da kommen soli, Oder sollen wir eines andern warten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Zu derselbigen Stunde aber machte erviele gesund von Seuchen und Plagen und bosen Geistern und viel Blinden schenkte er das Gesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Und Jesus antwortete und sprach zu ihnen: Gehet hin und verkundiget Johannes, was ihr gesehen und gehoret habt: Die Blinden sehen, die Lahmen gehen, die Aussatzigen werden rein, die Tauben horen, die Toten stehen auf, den Armen wird das Evangelium geprediget;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'und selig ist, der sich nicht argert an mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Da aber die Boten des Johannes hingingen, fing Jesus an, zu reden zu dem Volk von Johannes: Was seid ihr hinausgegangen in die Wüste zu sehen? Wolltet ihr ein Rohr sehen, das vom Winde beweget wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Oder was seid ihr hinausgegangen zu sehen? Wolltet ihr einen Menschen sehen in weichen Kleidern? Sehet, die in herrlichen Kleidern und Lusten leben, die sind in den koniglichen Hofen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Oder was seid ihr bin ausgegangen zu sehen? Wolltet ihr einen Propheten sehen? Ja, ich sage euch, der da mehr ist denn ein Prophet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Er ist\'s, von dem geschrieben stehet: Siehe, ich sende meinen Engel vordeinem Angesicht her, der da, bereiten soil deinen Weg vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Denn ich sage euch, daß unter denen, die von Weibern geboren sind, ist kein großerer Prophet denn Johannes der Taufer; der aber kleiner ist im Reich Gottes, der ist großer denn er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Und alles Volk, das ihn horete, und die Zollner gaben Gott recht und ließen sich taufen mit der Taufe des Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Aber die Pharisaer und Schriftgelehrten verachteten Gottes Rat wider sich selbst und ließen sich nicht von ihm taufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Aber der Herr sprach: Wem soil ich die Menschen dieses Geschlechts vergleichen, und wem sind sie gleich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Sie sind gleich den Kindern, die auf dem Markt sitzen und rufen gegeneinander und sprechen: Wir haben euch gepfiffen, und ihr habt nicht getanzet; wir haben euch geklaget, und ihr habt nicht geweinet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Denn Johannes der Taufer ist kommen und aß nicht Brot und trank keinen Wein, so sagt ihr: Er hat den Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Des Menschen Sohn ist kommen, isset und trinket, so sagt ihr: Siehe, der Mensch ist ein Fresser und Weinsaufer, der Zollner und Sunder Freund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Und die Weisheit muß sich rechtfertigen lassen von alien ihren Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Es bat ihn aber der Pharisaer einer, daß er mit ihm aße: Und er ging hinein in des Pharisaers Haus und setzte sich zu Tische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Und siehe, ein Weib war in der Stadt, die war eine Sünderin. Da die vernahm, dafi er zu Tische saß in des Pharisaers Hause, brachte sie ein Glas mit Salben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'und trat hinten zu seinen Fuüen und weinete und fing an, seine Fuße zu netzen mit Tranen und mit den Haaren ihres Haupts zu trocknen; und kussete seine Fuße und salbete sie mit Salben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Da aber das der Pharisaer sah, der ihn geladen hatte, sprach er bei sich selbst und sagte: Wenn dieser ein Prophet ware, so wußte er, wer und welch ein Weib das ist, die ihn anruhret; denn sie ist eine Sünderin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Jesus antwortete und sprach zu ihm: Simon, ich habe dir etwas zu sagen. Er aber sprach: Meister, sage an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Es hatte ein Wucherer zwei Schuldner. Einer war schuldig funfhundert Groschen, der andere fünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Da sie aber nicht hatten zu bezahlen, schenkte er\'s beiden. Sage an, welcher unter denen wird ihn am meisten lieben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon antwortete und sprach: Ich achte, dem er am meisten geschenket hat. Er aber sprach zu ihm: Du hast recht gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Und erwandte sich zu dem Weibe und sprach zu Simon: Siehest du dies Weib? Ich bin kommen in dein Haus, du hast mit nicht Wasser gegeben zu meinen Fußen; diese aber hat meine Fuße mit Tranen genetzet und mit den Flaaren ihres Haupts getrocknet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Du hast mir keinen Kuß gegeben; diese aber, nachdem sie hereinkommen ist, hat sie nicht abgelassen, meine Fuße zu kussen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Du hast mein Haupt nicht mit Ole gesalbet; sie aber hat meine Fuße mit Salben gesalbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Derhalben sage ich dir: Ihr sind viel Sunden vergeben, denn sie hat viel geliebet. Welchem aber wenig vergeben wird, der liebet wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Und er sprach zu ihr: Dir sind deine Sunden vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Da fingen an, die mit ihm zu Tisch saßen, und sprachen bei sich selbst: Wer ist dieser, der auch die Sunden vergibt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Er aber sprach zu dem Weibe: Dein Glaube hat dir geholfen; gehe hin mit Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Und es begab sich danach, daß er reisete durch Stadte und Markte und predigte und verkündigte das Evangelium vom Reich Gottes, und die Zwolfe mit ihm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'dazu etliche Weiber, die er gesund hatte gemacht von den bosen Geistern und Krankheiten, namlich Maria, die da Magdalena heißt, von welcher waren sieben Teufel ausgefahren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'und Johanna, das Weib Chusas, des Pflegers des Herodes, und Susanna und viel andere, die ihm Handreichung taten von ihrer Habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Da nun viel Volks beieinander war und aus den Stadten zu ihm eileten, sprach er durch ein Gleichnis:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Es ging ein Samann aus, zu saen seinen Samen; und indem er sate, fiel etliches an den Weg und ward vertreten, und die Vogel unter dem Himmel fraßen\'s auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Und etliches fiel auf den Fels; und da es aufging, verdorrete es, darum daß es nicht Saft hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Und etliches fiel mitten unter die Dornen; und die Dornen gingen mit auf und erstickten\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Und etliches fiel auf ein gut Land; und es ging auf und trug hundertfaltige Frucht. Da er das sagte, rief er: Wer Ohren hat zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Es fragten ihn aber seine Junger und sprachen, was dieses Gleichnis ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Er aber sprach: Euch ist\'s gegeben, zu wissen das Geheimnis des Reichs Gottes; den andern aber in Gleichnissen, daß sie es nicht sehen, ob sie es schon sehen, und nicht verstehen, ob sie es schon horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Das ist aber das Gleichnis: Der Same ist das Wort Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Die aber an dem Wege sind, das sind, die es horen; danach kommt der Teufel und nimmt das Wort von ihrem Herzen, auf daß sie nicht glauben und selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Die aber auf dem Fels sind die: wenn sie es horen, nehmen sie das Wort mit Freuden an. Und die haben nicht Wurzel: eine Zeitlang glauben sie und zu der Zeit der Anfechtung fallen sie ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Das aber unter die Dornen fiel, sind die, so es horen und gehen hin unter den Sorgen, Reichtum und Wollust dieses Lebens und ersticken und bringen keine Frucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Das aber auf dem guten Lande sind, die das Wort horen und behalten in einem feinen, guten Herzen und bringen Frucht in Geduld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Niemand aber zundet ein Licht an und bedeckt es mit einem Gefaß Oder setzt es unter eine Bank, sondern er setzt es auf einen Leuchter, auf daß wer hineingehet, das Licht sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Denn es ist nichts verborgen, was nicht offenbar werde, auch nichts Heimliches, was nicht kund werde und an den Tag komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'So sehet nun darauf, wie ihr zuhoret! Denn wer da hat, dem wird gegeben; wer aber nicht hat, von dem wird genommen, auch was er meinet zu haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Es gingen aber hinzu seine Mutter und Bruder und konnten vor dem Volk nicht zu ihm kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Und es ward ihm angesagt: Deine Mutter und deine Bruder stehen draußen und wollen dich sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Er aber antwortete und sprach zu ihnen: Meine Mutter und meine Bruder sind diese, die Gottes Wort horen und tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Und es begab sich auf der Tage einen, daß er in ein Schiff trat samt seinen Jungern. Und er sprach zu ihnen: Lasset uns uber den See fahren! Sie stießen vom Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Und da sie schiffeten, schlief er ein. Und es kam ein Windwirbel auf den See; und die Wellen uberfielen sie, und stunden in grower Gefahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Da traten sie zu ihm und weckten ihn auf und sprachen: Meister, Meister, wir verderben! Da stund er auf und bedrauete den Wind und die Woge des Wassers; und es liefi ab und ward eine Stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Er sprach aber zu ihnen: Wo ist euer Glaube? Sie furchteten sich aber und verwunderten sich und sprachen untereinander: Wer ist dieser? Denn er gebeut dem Wind und dem Wasser, und sie sind ihm gehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Und sie schifften fort in die Gegend der Gadarener, welche ist Galilaa gegenuber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Und als er austrat auf das Land, begegnete ihm ein Mann aus der Stadt, der hatte Teufel von langer Zeit her und tat keine Kleider an und blieb in keinem Hause, sondern in den Grabern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Da er aber Jesum sah, schrie er und fiel vor ihm nieder und rief laut und sprach: Was habe ich mit dir zu schaffen, Jesu, du Sohn Gottes, des Allerhochsten? Ich bitte dich, du wollest mich nicht qualen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Denn er gebot dem unsaubern Geist, daß er von dem Menschen ausfuhre; denn er hatte ihn lange Zeit geplaget. Und er war mit Ketten gebunden und mit Fesseln gefangen; und zerrifi die Bande und ward getrieben von dem Teufel in die Wusten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Und Jesus fragte ihn und sprach: Wie heiliest du? Er sprach: Legion. Denn es waren viel Teufel in ihn gefahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Und sie baten ihn, daß er sie nicht hiefie in die Tiefe fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Es war aber daselbst eine grolie Herde Saue auf der Weide auf dem Berge. Und sie baten ihn, daß er ihnen erlaubete, in dieselbigen zu fahren. Und er erlaubte ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Da fuhren die Teufel aus von dem Menschen und fuhren in die Saue. Und die Herde sturzte sich mit einem Sturm in den See und ersoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Da aber die Hirten sahen, was da geschah, flohen sie und verkundigten\'s in der Stadt und in den Dorfern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Da gingen sie hinaus, zu sehen, was da geschehen war; und kamen zu Jesu und fanden den Menschen, von welchem die Teufel ausgefahren waren, sitzend zu den Fülien Jesu, bekleidet und vernunftig; und erschraken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Und die es gesehen hatten, verkundigten\'s ihnen, wie der Besessene war gesund worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Und es bat ihn die ganze Menge der umliegenden Lander der Gadarener, daß ervon ihnen ginge. Denn es war sie eine grolie Furcht ankommen. Und er trat in das Schiff und wandte wieder urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Es bat ihn aber der Mann, von dem die Teufel ausgefahren waren, da(3> er bei ihm mochte sein. Aber Jesus liefi ihn von sich und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Gehe wieder heim und sage, wie grolie Dinge dir Gott getan hat. Und er ging hin und predigte durch die ganze Stadt, wie grolie Dinge ihm Jesus getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Und es begab sich, da Jesus wiederkam, nahm ihn das Volk auf; denn sie warteten alle auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Und siehe, da kam ein Mann mit Namen Jairus, der ein Oberster der Schule war, und fiel Jesu zu den Füüen und bat ihn, daß erwollte in sein Haus kommen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Denn er hatte eine einige Tochter bei zwolf Jahren, die lag in den letzten Zugen. Und da er hinging, drang ihn das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Und ein Weib hatte den Blutgang zwolf Jahre gehabt; die hatte alle ihre Nahrung an die Arzte gewandt und konnte von niemand geheilet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Die trat hinzu von hinten und rührete seines Kleides Saum an; und alsbald stund ihrder Blutgang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Und Jesus sprach: Wer hat mich angeruhret? Da sie aber alle leugneten, sprach Petrus, und die mit ihm waren: Meister, das Volk dranget und drucket dich, und du sprichst: Wer hat mich angeruhret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jesus aber sprach: Es hat mich jemand angeruhret; denn ich fühle, daß eine Kraft von mir gegangen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Da aber das Weib sah, daß es nicht verborgen war, kam sie mit Zittern und fiel vor ihm nieder und verkundigte vor allem Volk, aus was Ursach\' sie ihn hatte angeruhret, und wie sie ware alsbald gesund worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Er aber sprach zu ihr: Sei getrost, meine Tochter; dein Glaube hat dir geholfen; gehe hin mit Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Da er noch redete, kam einer vom Gesinde des Obersten der Schule und sprach zu ihm: Deine Tochter ist gestorben; bemühe den Meister nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Da aber Jesus das horete, antwortete er ihm und sprach: Furchte dich nicht! Glaube nur, so wird sie gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Da er aber in das Haus kam, lieli er niemand hineingehen denn Petrus und Jakobus und Johannes und des Kindes Vater und Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Sie weineten aber alle und klagten urn sie. Er aber sprach: Weinet nicht! Sie ist nicht gestorben, sondern sie schlaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Und sie verlachten ihn, wuliten wohl, daß sie gestorben war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Er aber trieb sie alle hinaus, nahm sie bei der Hand und rief und sprach: Kind, stehe auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Und ihr Geist kam wieder, und sie stund alsbald auf. Und er befahl, man sollte ihrzu essen geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Und ihre Eltern entsetzten sich. Er aber gebot ihnen, dad sie niemand sagten, was geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Er forderte aber die Zwolfe zusammen und gab ihnen Gewalt und Macht uber alle Teufel und daß sie Seuchen heilen konnten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Und sandte sie aus, zu predigen das Reich Gottes und zu heilen die Kranken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Und sprach zu ihnen: Ihr sollt nichts mit euch nehmen auf den Weg, weder Stab noch Tasche noch Brat noch Geld; es soli auch einer nicht zwei Rocke haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Und wo ihr in ein Haus gehet, da bleibet, bis ihr von dannen ziehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Und welche euch nicht aufnehmen, da gehet aus von derselben Stadt und schuttelt auch den Staub ab von euren Fußen zu einem Zeugnis uber sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Und sie gingen hinaus und durchzogen die Markte, predigten das Evangelium und machten gesund an alien Enden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Es kam aber vor Herodes, den Vierfursten, alles, was durch ihn geschah; und er besorgte sich, dieweil von etlichen gesagt ward: Johannes ist von den Toten auferstanden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'von etlichen aber: Elia ist erschienen; von etlichen aber: Es ist der alten Propheten einer auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Und Herodes sprach: Johannes, den habe ich enthauptet; wer ist aber dieser, von dem ich solches hore? Und begehrete, ihn zu sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Und die Apostel kamen wieder und erzahlten ihm, wie große Dinge sie getan hatten. Und er nahm sie zu sich und entwich besonders in eine Wüste bei der Stadt, die da heilit Bethsaida.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Da des das Volk inne ward, zog es ihm nach. Und er ließ sie zu sich und sagte ihnen vom Reich Gottes und machte gesund, die es bedurften. Aber der Tag ting an sich zu neigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Da traten zu ihm die Zwolfe und sprachen zu ihm: Lafi das Volk von dir, dafi sie hingehen in die Markte umher und in die Dorfer, daß sie Herberge und Speise finden; denn wir sind hier in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Er aber sprach zu ihnen: Gebt ihr ihnen zu essen. Sie sprachen: Wir haben nicht mehr denn fünf Brote und zwei Fische; es sei denn, daß wir hingehen sollen und Speise kaufen fur so groß Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, '(Denn es waren bei funftausend Mann.) Er sprach aber zu seinen Jungern: Lasset sie sich setzen bei Schichten, je funfzig und funfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Und sie taten also und setzten sich alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Da nahm er die funf Brote und zwei Fische und sah auf gen Himmel und dankete daruber, brach sie und gab sie den Jungern, daß sie dem Volk vorlegten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Und sie aßen und wurden alle satt; und wurden aufgehoben, was ihnen uber blieb von Brocken, zwolf Korbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Und es begab sich, da er allein war und betete und seine Junger bei ihm, fragte er sie und sprach: Wer sagen die Leute, daß ich sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Sie antworteten und sprachen: Sie sagen, du seiest Johannes der Tauter; etliche aber, du seiest Elia; etliche aber, es sei der alten Propheten einer auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Er aber sprach zu ihnen: Wer saget ihr aber, daß ich sei? Da antwortete Petrus und sprach: Du bist der Christ Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Und er bedrauete sie und gebot, daß sie das niemand sagten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'und sprach: Denn des Menschen Sohn muß noch viel leiden und verworfen werde von den Altesten und Hohenpriestern und Schriftgelehrten und getotet werden und am dritten Tage auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Da sprach er zu ihnen alien: Wer mir folgen will der verleugne sich selbst und nehme sein Kreuz auf sich taglich und folge mir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Denn wer sein Leben erhalten will, der wird es verlieren; wer aber sein Leben verlieret urn meinetwillen, derwird\'s erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Und was Nutz hatte der Mensch, ob er die ganze Welt gewonne und verlore sich selbst Oder beschadigte sich selbst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Wer sich aber mein und meiner Worte schamet, des wird sich des Menschen Sohn auch schamen, wenn er kommen wird in seiner Herrlichkeit und seines Vaters und der heiligen Engel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Ich sage euch aber wahrlich, daß etliche sind von denen, die hier stehen, die den Tod nicht schmecken werden, bis daß sie das Reich Gottes sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Und es begab sich nach diesen Reden bei acht Tagen, daß erzu sich nahm Petrus, Johannes und Jakobus und ging auf einen Berg, zu beten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Und da er betete, ward die Gestalt seines Angesichts anders, und sein Kleid ward weiß und glanzete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Und siehe, zwei Manner redeten mit ihm, welche waren Mose und Elia.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Die erschienen in Klarheit und redeten von dem Ausgang, welchen er sollte erfullen zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petrus aber, und die mit ihm waren, waren voll Schlafs. Da sie aber aufwachten, sahen sie seine Klarheit und die zwei Manner bei ihm stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Und es begab sich, da die von ihm wichen; sprach Petrus zu Jesu: Meister, hier ist gut sein; lasset uns drei Hütten machen, dir eine, Mose eine und Elia eine. Und wußte nicht, was er redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Da er aber solches redete, kam eine Wolke und uberschattete sie. Und sie erschraken, da sie die Wolke uberzog.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Und es fiel eine Stimme aus der Wolke, die sprach: Dieser ist mein lieber Sohn, den sollt ihr horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Und indem solche Stimme geschah, fanden sie Jesum alleine. Und sie verschwiegen und verkundigten niemand nichts in denselbigen Tagen, was sie gesehen hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Es begab sich aber den Tag hernach, da sie von dem Berge kamen, kam ihnen entgegen viel Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Und siehe, ein Mann unter dem Volk rief und sprach: Meister, ich bitte dich, besiehe doch meinen Sohn; denn er ist mein einiger Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Siehe, der Geist ergreift ihn, so schreiet er alsbald; und reiftet ihn, daß er schaumet; und mit Not weichet er von ihm, wenn er ihn gerissen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Und ich habe deine Jünger gebeten, daß sie ihn austrieben, und sie konnten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Da antwortete Jesus und sprach: O du unglaubige und verkehrte Art! Wie lange soli ich bei euch sein und euch dulden? Bringe deinen Sohn her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Und da erzu ihm kam, rift ihn der Teufel und zerrete ihn. Jesus aber bedrauete den unsaubern Geist und machte den Knaben gesund und gab ihn seinem Vater wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Und sie entsetzten sich alle uber die Herrüchkeit Gottes. Da sie sich aber alle verwunderten uber alles, was er tat, sprach er zu seinen Jungern:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Fasset ihrzu euren Ohren diese Reden! Denn des Menschen Sohn muft uberantwortet werden in der Menschen Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Aber das Wort vernahmen sie nicht, und es war vor ihnen verborgen, daß sie es nicht begriffen; und sie furchteten sich, ihn zu fragen um dasselbige Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Es kam auch ein Gedanke unter sie, welcher unter ihnen der Groftte ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Da aber Jesus den Gedanken ihres Herzens sah, ergriff erein Kind und stellete es neben sich');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'und sprach zu ihnen: Wer das Kind aufnimmt in meinem Namen, der nimmt mich auf; und wer mich aufnimmt, der nimmt den auf, der mich gesandt hat. Welcher aber der Kleinste ist unter euch alien, der wird graft sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Da antwortete Johannes und sprach: Meister, wir sahen einen, der trieb die Teufel aus in deinem Namen, und wir wehreten ihm; denn er folget dir nicht mit uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Und Jesus sprach zu ihm: Wehret ihm nicht; denn wer nicht wider uns ist, der ist fur uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Es begab sich aber, da die Zeit erfüllet war, daß er sollte von hinnen genommen werden, wandte er sein Angesicht, stracks gen Jerusalem zu wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Und er sandte Boten vor sich hin; die gingen hin und kamen in einen Markt der Samariter, daß sie ihm Herberge bestelleten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Und sie nahmen ihn nicht an, darum daß er sein Angesicht gewendet hatte, zu wandeln gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Da aber das seine Junger, Jakobus und Johannes sahen, sprachen sie: Herr, willstdu, so wollen wir sagen, daß Feuer vom Himmel falle und verzehre sie, wie Elia tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Jesus aber wandte sich und bedrauete sie und sprach: Wisset ihr nicht, welches Geistes Kinder ihr seid?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Des Menschen Sohn ist nicht kommen, der Menschen Seelen zu verderben, sondern zu erhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Und sie gingen in einen andern Markt. Es begab sich aber, da sie auf dem Wege waren, sprach einer zu ihm: Ich will dirfolgen, wo du hingehest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Und Jesus sprach zu ihm: Die Füchse haben Gruben, und die Vogel unter dem Himmel haben Nester, aber des Menschen Sohn hat nicht, da er sein Haupt hinlege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Und er sprach zu einem andern: Folge mir nach! Der sprach aber: Herr, erlaube mir, daß ich zuvor hingehe und meinen Vater begrabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Aber Jesus sprach zu ihm: Laft die Toten ihre Toten begraben; gehe du aber hin und verkundige das Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Und ein anderer sprach: Herr, ich will dir nachfolgen; aber erlaube mir zuvor, daß ich einen Abschied mache mit denen, die in meinem Hause sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jesus aber sprach zu ihm: Wer seine Hand an den Pflug leget und siehet zurück, der ist nicht geschickt zum Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Danach sonderte der Herr andere siebzig aus und sandte sie zwei und zwei vor sich her in alle Stadte und Orte, da erwollte hinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Und sprach zu ihnen: Die Ernte ist graft, der Arbeiter aber ist wenig; bittet den Herm der Ernte, daß er Arbeiter aussende in seine Ernte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Gehet hin! Siehe, ich sende euch als die Lammer mitten unter die Wolfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Traget keinen Beutel noch Tasche noch Schuhe und grüftet niemand auf der Strafte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Wo ihr in ein Haus kommt, da sprechet zuerst: Friede sei in diesem Hause!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Und so daselbst wird ein Kind des Friedens sein, so wird euer Friede auf ihm beruhen; wo aber nicht, so wird sich euer Friede wieder zu euch wenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'In demselbigen Hause aber bleibet, esset und trinket, was sie haben; denn ein Arbeiter ist seines Lohnes wert. Ihr sollt nicht von, einem Hause zum andern gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Und wo ihr in eine Stadt kommt, und sie euch aufnehmen, da esset, was euch wird vorgetragen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'und heüet die Kranken, die daselbst sind, und saget ihnen: Das Reich Gottes ist nahe zu euch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Wo ihr aber in eine Stadt kommet, da sie euch nicht aufnehmen, da gehet heraus auf ihre Gassen und sprecht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Auch den Staub, der sich an uns gehanget hat von eurer Stadt, schlagen wir ab auf euch; doch sollt ihr wissen, daß euch das Reich Gottes nahe gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Ich sage euch: Es wird Sodom ertraglicher ergehen an jenem Tage denn solcher Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Wehe dir, Chorazin! Wehe dir, Bethsaida! Denn waren solche Taten zu Tyrus und Sidon geschehen, die bei euch geschehen sind, sie hatten vorzeiten im Sack und in der Asche gesessen und Bufte getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Doch es wird Tyrus und Sidon ertraglicher ergehen am Gerichte denn euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Und du, Kapernaum, die du bis an den Himmel erhoben bist, du wirst in die Holle hinuntergestoüen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Wer euch horet, der horet mich, und wer euch verachtet, der verachtet mich; wer aber mich verachtet, der verachtet den, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Die Siebzig aber kamen wieder mit Freuden und sprachen: Herr, es sind uns auch die Teufel untertan in deinem Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Er sprach aber zu ihnen: Ich sah wohl den Satanas vom Himmel fallen als einen Blitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Sehet, ich habe euch Macht gegeben, zu treten auf Schlangen und Skorpione, und über alle Gewalt des Feindes; und nichts wird euch beschadigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Doch darin freuet euch nicht, daß euch die Geister untertan sind, freuet euch aber, daß eure Namen im Himmel geschrieben sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Zu der Stunde freuete sich Jesus im Geist und sprach: Ich preise dich, Vater und Herr Himmels und der Erde, daß du solches verborgen hast den Weisen und Klugen und hast es offenbart den Unmundigen: Ja, Vater, also war es wohlgefallig vor dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Es ist mir alles übergeben von meinem Vater. Und niemand weifi, wer der Sohn sei, denn nur der Vater, noch wer der Vater sei, denn nur der Sohn, und welchem es der Sohn will offenbaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Und erwandte sich zu seinen Jungern und sprach insonderheit: Selig sind die Augen, die da sehen, was ihr sehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Denn ich sage euch: Viel Propheten und Konige wollten sehen, was ihr sehet, und haben\'s nicht gesehen; und horen, was ihr horet, und haben\'s nicht gehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Und siehe, da stund ein Schriftgelehrter auf, versuchte ihn und sprach: Meister, was muft ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Er aber sprach zu ihm: Wie stehet im Gesetz geschrieben? Wie liesest du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Er antwortete und sprach: Du sollst Gott, deinen Herrn, lieben von ganzem Herzen, von ganzer Seele, von alien Kraften und von ganzem Gemüt und deinen Nachsten als dich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Er aber sprach zu ihm: Du hast recht geantwortet; tue das, so wirst du leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Er aber wollte sich selbst rechtfertigen und sprach zu Jesu: Wer ist denn mein Nachster?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Da antwortete Jesus und sprach: Es war ein Mensch, derging von Jerusalem hinab gen Jericho und fiel unter die Morder; die zogen ihn aus und schlugen ihn und gingen davon und lieften ihn halbtot liegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Es begab sich aber ohngefahr, daß ein Priester dieselbige Strafte hinabzog; und da er ihn sah, ging er voruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Desselbigengleichen auch ein Levit: da er kam zu der Statte und sah ihn, ging er voruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Ein Samariter aber reisete und kam dahin; und da er ihn sah, jammerte ihn sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'ging zu ihm, verband ihm seine Wunden und goft drein Ol und Wein und hub ihn auf sein Tier und fuhrete ihn in die Herberge und pflegete sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Des andern Tages reisete er und zog heraus zwei Groschen und gab sie dem Wirt und sprach zu ihm; Pflege sein; und so du was mehr wirst dartun, will ich dir\'s bezahlen, wenn ich wiederkomme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Welcher dunket dich, der unter diesen dreien der Nachste, sei gewesen dem, der unter die Morder gefallen war?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Er sprach: Der die Barmherzigkeit an ihm tat. Da sprach Jesus zu ihm: So gehe hin und tue desgleichen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Es begab sich aber, da sie wandelten, ging er in einen Markt. Da war ein Weib mit Namen Martha, die nahm ihn auf in ihr Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Und sie hatte eine Schwester, die hieft Maria; die setzte sich zu Jesu Füften und horete seiner Rede zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Martha aber machte sich viel zu schaffen, ihm zu dienen. Und sie trat hinzu und sprach: Herr, fragst du nicht danach, daß mich meine Schwester lasset alleine dienen? Sage ihr doch, daß sie es auch angreife!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Jesus aber antwortete und sprach zu ihr: Martha, Martha, du hast viel Sorge und Mühe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Eines aber ist not: Maria hat das gute Teil erwahlet; das soil nicht von ihr genommen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Und es begab sich, daß er war an einem Ort und betete. Und da er aufgehoret hatte, sprach seiner Junger einer zu ihm: Herr, lehre uns beten, wie auch Johannes seine Junger lehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Er aber sprach zu ihnen: Wenn ihr betet, sprecht: Unser Vater im Himmel, dein Name werde geheiliget. Dein Reich komme. Dein Wille geschehe auf Erden wie im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Gib uns unser taglich Brot immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Und vergib uns unsere Sunden; denn auch wir vergeben alien, die uns schuldig sind. Und führe uns nicht in Versuchung, sondern erlose uns von dem Gbel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Und er sprach zu ihnen: Welcher ist unter euch, der einen Freund hat und ginge zu ihm urn Mitternacht und sprache zu ihm: Lieber Freund, leihe mir drei Brote;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'denn es ist mein Freund zu mir kommen von der Strafte, und ich habe nicht, was ich ihm vorlege;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'und er drinnen würde antworten und sprechen: Mach\' mir keine Unruhe; die Tur ist schon zugeschlossen, und meine Kindlein sind bei mir in der Kammer; ich kann nicht aufstehen und dir geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Ich sage euch, und ob er nicht aufsteht und gibt ihm darum, daß er sein Freund ist, so wird er doch urn seines unverschamten Geilens willen aufstehen und ihm geben, wieviel er bedarf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Und ich sage euch auch: Bittet, so wird euch gegeben; suchet, so werdet ihr finden; klopfet an, so wird euch aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Denn wer da bittet, der nimmt; und werda suchet, der findet; und wer da anklopfet, dem wird aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Wo bittet unter euch ein Sohn den Vater urns Brot, der ihm einen Stein dafür biete? und so er um einen Fisch bittet, der ihm eine Schlange fur den Fisch biete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'odersoerum ein Ei bittet, der ihm einen Skorpion dafür biete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'So denn ihr, die ihr arg seid, konnet euren Kindern gute Gaben geben, wieviel mehr wird der Vater im FHimmel den FHeiligen Geist geben denen, die ihn bitten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Und er trieb einen Teufel aus, der war stumm. Und es geschah, da der Teufel ausfuhr, da redete der Stumme. Und das Volk verwunderte sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Etliche aber unter ihnen sprachen: Er treibt die Teufel aus durch Beelzebub, den Obersten der Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Die andern aber versuchten ihn und begehreten ein Zeichen von ihm vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Er aber vernahm ihre Gedanken und sprach zu ihnen: Ein jeglich Reich, so es mit ihm selbst uneins wird, das wird wilste, und ein FHaus fallt über das andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, '1st denn der Satanas auch mit ihm selbst uneins, wie will sein Reich bestehen? dieweil ihr saget, ich treibe die Teufel aus durch Beelzebub.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'So aber ich die Teufel durch Beelzebub austreibe, durch wen treiben sie eure Kinder aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'So ich aber durch Gottes Finger die Teufel austreibe, so kommt je das Reich Gottes zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Wenn ein starker Gewappneter seinen Palast bewahret, so bleibt das Seine mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Wenn aber ein Starkerer über ihn kommt und uberwindet ihn, so nimmt er ihm seinen Harnisch, darauf er sich verließ, und teilet den Raub aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Wer nicht mit mir ist, der ist wider mich; und wer nicht mit mir sammelt, der zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Wenn der unsaubere Geist von dem Menschen ausfahret, so durchwandelt er dilrre Statten, suchet Ruhe und findet sie nicht; so spricht er: Ich will wieder umkehren in mein Haus, daraus ich gegangen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Und wenn er kommt, so findet er\'s mit Besemen gekehret und geschmücket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Dann gehet er hin und nimmt sieben Geister zu sich, die arger sind denn er selbst; und wenn sie hineinkommen, wohnen sie da; und wird hernach mit demselbigen Menschen arger denn vorhin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Und es begab sich, da ersolches redete, erhub ein Weib im Volk die Stimme und sprach zu ihm: Selig ist der Leib, der dich getragen hat, und die Brilste, die du gesogen hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Er aber sprach: Ja, selig sind, die das Wort Gottes horen und bewahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Das Volk aber drang hinzu. Da fing er an und sagte: Dies ist eine arge Art; sie begehret ein Zeichen, und es wird ihr kein Zeichen gegeben denn nur das Zeichen des Propheten Jona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Denn wie Jona ein Zeichen war den Niniviten, also wird des Menschen Sohn sein diesem Geschlechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Die Konigin von Mittag wird auftreten vordem Gerichte mit den Leuten dieses Geschlechts und wird sie verdammen; denn sie kam von der Welt Ende, zu horen die Weisheit Salomos. Und siehe, hier ist mehr denn Salomo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Die Leute von Ninive werden auftreten vor dem Gerichte mit diesem Geschlecht und werden\'s verdammen; denn sie taten Bulie nach der Predigt des Jona. Und siehe, hier ist mehr denn Jona.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Niemand zundet ein Licht an und setzt es an einen heimlichen Ort, auch nicht unter einen Scheffel, sondern auf den Leuchter, auf daß, wer hineingehet, das Licht sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Das Auge ist des Leibes Licht. Wenn nun dein Auge einfaltig sein wird, so ist dein ganzer Leib licht. So aber dein Auge ein Schalk sein wird, so ist auch dein Leib finster.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'So schaue darauf, daß nicht das Licht in dir Finsternis sei!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Wenn nun dein Leib ganz licht ist, daß er kein Stuck von Finsternis hat, so wird er ganz licht sein und wird dich erleuchten wie ein heller Blitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Da er aber in der Rede war, bat ihn ein Pharisaer, daß er mit ihm das Mittagsmahl alie. Und er ging hinein und setzte sich zu Tische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Da das der Pharisaer sah, verwunderte er sich, daß er sich nicht vor dem Essen gewaschen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Der Herr aber sprach zu ihm: Ihr Pharisaer haltet die Becher und Schusseln auswendig reinlich; aber euer Inwendiges ist voll Raubes und Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Ihr Narren, meinet ihr, daß inwendig rein sei, wenn\'s auswendig rein ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Doch gebt Almosen von dem, was da ist, siehe, so ist\'s euch alles rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Aberwehe euch Pharisaern, daß ihr verzehntet die Minze und Raute und allerlei Kohl und gehet vorbei an dem Gericht und an der Liebe Gottes! Dies sollte man tun und jenes nicht lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Wehe euch Pharisaern, daß ihr gerne obenan sitzet in den Schulen und wollet gegril fit sein auf dem Markte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Wehe euch Schriftgelehrten und Pharisaern, ihr Heuchler, daß ihr seid wie die verdeckten Totengraber, darilber die Leute laufen und kennen sie nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Da antwortete einer von den Schriftgelehrten und sprach zu ihm: Meister, mit den Worten schmahest du uns auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Er aber sprach: Und wehe auch euch Schriftgelehrten! Denn ihr beladet die Menschen mit unertraglichen Lasten, und ihr rühret sie nicht mit einem Finger an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Wehe euch! Denn ihr bauet der Propheten Graber; eure Vater aber haben sie getotet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'So bezeuget ihr zwar und bewilliget in eurer Vater Werk; denn sie toteten sie, so bauet ihr ihre Graber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Darum spricht die Weisheit Gottes: Ich will Propheten und Apostel zu ihnen senden, und derselbigen werden sie etliche toten und verfolgen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'auf daß gefordert werde von diesem Geschlecht aller Propheten Blut, das vergossen ist, seit der Welt Grund gelegt ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'von Abels Blut an bis auf das Blut des Zacharias, der umkam zwischen dem Altar und Tempel. Ja, ich sage euch, es wird gefordert werden von diesem Geschlechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Wehe euch Schriftgelehrten! denn ihr den Schlüssel der Erkenntnis habt. Ihr kommt nicht hinein und wehret denen, die hinein wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Da er aber solches zu ihnen sagte, fingen an die Schriftgelehrten und Pharisaer, hart auf ihn zu dringen und ihm mit mancherlei Fragen den Mund zu stopfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'und lauerten auf ihn und suchten, ob sie etwas erjagen konnten aus seinem Munde, daß sie eine Sache wider ihn hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Es lief das Volk zu, und kamen etliche viel tausend zusammen, also daß sie sich untereinander traten. Da fing er an und sagte zu seinen Jungern: Zum ersten hutet euch vor den Sauerteig der Pharisaer, welches ist die Heuchelei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Es ist aber nichts verborgen, das nicht offenbar werde, noch heimlich, das man nicht wissen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Darum, was ihr in Finsternis saget, das wird man im Licht horen; was ihr redet ins Ohr in den Kammern, das wird man auf den Dachern predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Ich sage euch aber, meinen Freunden: Furchtet euch nicht vor denen, die den Leib toten und danach nichts mehr tun konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ich will euch aberzeigen, vorwelchem ihr euch furchten sollt: Furchtet euch vor dem, der, nachdem er getotet hat, auch Macht hat, zu werfen in die Holle. Ja, ich sage euch, vor dem furchtet euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Verkauftman nicht funf Sperlinge urn zwei Pfennige? Noch ist vor Gott derselbigen nicht einer vergessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Auch sind die Haare auf eurem Haupte alle gezahlet. Darum furchtet euch nicht; denn ihr seid besserdenn viel Sperlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Ich sage euch aber: Wer mich bekennet vor den Menschen, den wird auch des Menschen Sohn bekennen vor den Engeln Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Wer mich aber verleugnet vor den Menschen, der wird verleugnet werden vor den Engeln Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Und wer da redet ein Wort wider des Menschen Sohn, dem soli es vergeben werden; wer aber lasted den Heiligen Geist, dem soil es nicht vergeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Wenn sie euch aber führen werden in ihre Schulen und vor die Obrigkeit und vor die Gewaltigen, so sorget nicht, wie Oder was ihr antworten Oder was ihr sagen sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Denn der Heilige Geist wird euch zu derselbigen Stunde lehren, was ihr sagen sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Es sprach aber einer aus dem Volk zu ihm: Meister, sage meinem Bruder, daß er mit mir das Erbe teile.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Er aber sprach zu ihm: Mensch, wer hat mich zum Richter Oder Erbschichter über euch gesetzt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Und sprach zu ihnen: Sehet zu und hutet euch vor dem Geiz! Denn niemand lebet davon, daß er viel Guter hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'und er sagte ihnen ein Gleichnis und sprach: Es war ein reicher Mensch, des Feld hatte wohl getragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Und ergedachte bei sich selbst und sprach: Was soil ich tun? Ich habe nicht, da ich meine Fruchte hinsammle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Und sprach: Das will ich tun: ich will meine Scheunen abbrechen und grotiere bauen und will drein sammeln alles, was mir gewachsen ist, und meine Guter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Und will sagen zu meiner Seele: Liebe Seele, du hast einen grolien Vorrat auf viel Jahre; habe nun Ruhe, i(i trink und habe guten Mut!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Aber Gott sprach zu ihm: Du Narr, diese Nacht wird man deine Seele von dir fordern, und wes wird\'s sein, das du bereitet hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Also gehet es, wer sich Schatze sammelt und ist nicht reich in Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Er sprach aber zu seinen Jungern: Darum sage ich euch: Sorget nicht fur euer Leben, was ihr essen sollet; auch nicht fur euren Leib, was ihr antun sollet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Das Leben ist mehr denn die Speise und der Leib mehr denn die Kleidung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Nehmet wahr der Raben: sie saen nicht, sie ernten auch nicht, sie haben auch keinen Keller noch Scheune; und Gott nahret sie doch. Wieviel aber seid ihr besser denn die Vogel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Welcher ist unter euch, ob er schon darum sorget, der da konnte eine Elle lang seiner Grolie zusetzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'So ihr denn das Geringste nicht vermoget, warum sorget ihr fur das andere?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Nehmet wahr der Lilien auf dem Felde, wie sie wachsen; sie arbeiten nicht, so spinnen sie nicht. Ich sage euch aber, daß auch Salomo in aller seiner Herrlichkeit nicht ist bekleidet gewesen als der eine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'So denn das Gras, das heute auf dem Felde stehet. und morgen in den Ofen geworfen wird, Gott also kleidet, wieviel mehr wird er euch kleiden, ihr Kleinglaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Darum auch ihr, fraget nicht danach, was ihr essen Oder was ihr trinken sollt, und fahret nicht hoch her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Nach solchem allem trachten die Heiden in der Welt; aber euer Vater weift wohl, daß ihr des bedurfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Doch trachtet nach dem Reich Gottes, so wird euch das alles zufallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Furchte dich nicht, du kleine Herde; denn es ist eures Vaters Wohlgefallen, euch das Reich zugeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Verkaufet, was ihr habt, und gebt Almosen. Machet euch Sackel, die nicht veralten, einen Schatz, der nimmer abnimmt im Himmel, da kein Dieb zukommt, und den keine Motten fressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Denn wo euer Schatz ist, da wird auch euer Herz sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Lasset eure Lenden umgurtet sein und eure Lichter brennen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'und seid gleich den Menschen, die auf ihren Herrn warten, wenn er aufbrechen wird von der Hochzeit, auf dafi, wenn er kommt und anklopft, sie ihm bald auftun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Selig sind die Knechte, die der Herr, so er kommt, wachend findet. Wahrlich, ich sage euch, er wird sich aufschurzen und wird sie zu Tisch setzen und vor ihnen gehen und ihnen dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Und so er kommt in der andern Wache und in der dritten Wache und wird\'s also finden: selig sind diese Knechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Das sollt ihr aber wissen: Wenn ein Hausherr wuftte, zu welcher Stunde der Dieb kame, so wachete er und liefie nicht in sein Haus brechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Darum seid ihr auch bereit! Denn des Menschen Sohn wird kommen zu der Stunde, da ihr nicht meinet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Petrus aber sprach zu ihm: Herr, sagest du dies Gleichnis zu uns Oder auch zu alien?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Der Herr aber sprach: Wie ein graft Ding ist\'s urn einen treuen und klugen Haushalter, welchen der Herr setzt über sein Gesinde, daß er ihnen zu rechter Zeit ihre Gebührgebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Selig ist der Knecht, welchen sein Herr findet also tun, wenn er kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Wahrlich, ich sage euch, erwird ihn uberalle seine Güter setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'So aber derselbige Knecht in seinem Herzen sagen wird: Mein Herr verzieht zu kommen, und fanget an zu schlagen Knechte und Magde, auch zu essen und zu trinken und sich vollzusaufen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'so wird desselben Knechtes Herr kommen an dem Tage, da er sich\'s nicht versiehet, und zu der Stunde, die er nicht weift, und wird ihn zerscheitern und wird ihm seinen Lohn geben mit den Unglaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Der Knecht aber, der seines Herrn Willen weift und hat sich nicht bereitet, auch nicht nach seinem Willen getan, der wird viel Streiche leiden müssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Der es aber nicht weift, hat doch getan was der Streiche wert ist, wird wenig Streiche leiden. Denn welchem viel gegeben ist, bei dem wird man viel suchen, und welchem viel befohlen ist, von dem wird man viel fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Ich bin kommen, daß ich ein Feuer anzunde auf Erden; was wollt\' ich lieber, denn es brennete schon!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Aber ich muft mich zuvortaufen lassen mit einer Taufe; und wie ist mir so bange, bis sie vollendet werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Meinet ihr, daß ich herkommen bin, Frieden zu bringen auf Erden? Ich sage nein, sondern Zwietracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Denn von nun an werden fünf in einem Hause uneins sein: drei wider zwei und zwei wider drei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Es wird sein der Vater wider den Sohn und der Sohn wider den Vater, die Mutter wider die Tochter und die Tochter wider die Mutter, die Schwieger wider die Schnur und die Schnur wider die Schwieger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Er sprach aber zu dem Volk: Wenn ihr eine Wolke sehet aufgehen vom Abend, so sprecht ihr bald: Es kommt ein Regen; und es geschiehet also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Und wenn ihr sehet den Sudwind wehen, so sprecht ihr: Es wird, heift werden; und es geschiehet also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Ihr Heuchler, die Gestalt der Erde und des Himmels konnt ihr prüfen, wie prufet ihr aber diese Zeit nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Warum richtet ihr aber nicht an euch selber, was recht ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'So du aber mit deinem Widersacher vor den Fursten gehest, so tue Fleift auf dem Wege, daß du sein los werdest, auf daß er nicht etwa dich vor den Richter ziehe, und der Richter uberantworte dich dem Stockmeister, und der Stockmeister werfe dich ins Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Ich sage dir, du wirst von dannen nicht herauskommen, bis du den allerletzten Scherf bezahlest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Es waren aber zu derselbigen Zeit etliche dabei, die verkundigten ihm von den Galilaern, welcher Blut Püatus samt ihrem Opfer vermischt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Und Jesus antwortete und sprach zu ihnen: Meinet ihr, daß diese Galilaer vor alien Galilaern Sunder gewesen sind, die weil sie das erlitten haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Ich sage: Nein, sondern, so ihr euch nicht bessert, werdet ihr alle auch also umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Oder meinet ihr, daß die achtzehn, auf welche der Turm in Siloah fiel und erschlug sie, seien schuldig gewesen vor alien Menschen, die zu Jerusalem wohnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Ich sage: Nein, sondern so ihr euch nicht bessert, werdet ihr alle auch also umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Er sagte ihnen aber dies Gleichnis: Es hatte einer einen Feigenbaum, der war gepflanzt in seinem Weinberge; und kam und suchte Frucht darauf und fand sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Da sprach er zu dem Weingartner: Siehe, ich bin nun drei Jahre lang alle Jahre kommen und habe Frucht gesucht auf diesem Feigenbaum und finde sie nicht. Haue ihn ab; was hindert er das Land?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Er aber antwortete und sprach zu ihm: Herr, laft ihn noch dies Jahr, bis daß ich um ihn grabe und bedunge ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'ob erwollte Frucht bringen; wo nicht, so haue ihn danach ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Und er lehrete in einer Schule am Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Und siehe, ein Weib war da, das hatteeinen Geist der Krankheit achtzehn Jahre; und sie war krumm und konnte nicht wohl aufsehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Da sie aber Jesus sah, rief er sie zu sich und sprach zu ihr: Weib, sei los von deiner Krankheit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Und legte die Hande auf sie; und alsbald richtete sie sich auf und preisete Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Da antwortete der Oberste der Schule und war unwillig, daß Jesus auf den Sabbat heilete, und sprach zu dem Volk: Es sind sechs Tage, darinnen man arbeiten soil; in denselbigen kommt und laftt euch heilen und nicht am Sabbattage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Da antwortete ihm der Herr und sprach: Du Heuchler, loset nicht ein jeglicher unter euch seinen Ochsen Oder Esel von der Krippe am Sabbat und führet ihn zur Tranke?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Sollte aber nicht geloftt werden am Sabbat diese, die doch Abrahams Tochter ist, von diesem Bande, welche Satanas gebunden hatte nun wohl achtzehn Jahre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Und als er solches sagte, muftten sich schamen alle, die ihm wider gewesen waren. Und alles Volk freuete sich uber alle herrlichen Taten, die von ihm geschahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Er sprach aber: Wem ist das Reich Gottes gleich, und wem soil ich\'s vergleichen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Es ist einem Senfkorn gleich, welches ein Mensch nahm und warfs in seinen Garten; und es wuchs und ward ein grafter Baum, und die Vogel des Himmels wohneten unter seinen Zweigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Und abermal sprach er: Wem soil ich das Reich Gottes vergleichen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Es ist einem Sauerteige gleich, welchen ein Weib nahm und verbarg ihn unter drei Scheffel Mehls, bis daß es gar sauer ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Und er ging durch Stadte und Markte und lehrete und nahm seinen Weg gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Es sprach aber einer zu ihm: Herr, meinestdu, daß wenige selig werden? Er aber sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Ringet danach, daß ihr durch die enge Pforte eingehet; denn viele werden, das sage ich euch, danach trachten, wie sie hineinkommen, und werden\'s nicht tun konnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Von dem an, wenn der Hauswirt aufgestanden ist und die Tur verschlossen hat, da werdet ihr denn anfangen drauften zu stehen, und an die Tur klopfen und sagen: Herr, Herr, tu uns auf! Und er wird antworten und zu euch sagen: Ich kenne euer nicht, wo ihr her seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'So werdet ihr denn anfangen zu sagen: Wir haben vordir gegessen und getrunken, und auf den Gassen hast du uns gelehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Und erwird sagen: Ich sage euch, ich kenne euer nicht, wo ihr her seid; weichet alle von mir, ihr Ubeltater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Da wird sein Heulen und Zahneklappen, wenn ihr sehen werdet Abraham und Isaak und Jakob und alle Propheten im Reich Gottes, euch aber hinausgestoften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Und es werden kommen vom Morgen und vom Abend, von Mitternacht. und vom Mittage, die zu Tische sitzen werden im Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Und siehe, es sind Letzte, die werden die Ersten sein; und sind Erste, die werden die Letzten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'An demselben Tage kamen etliche Pharisaer und sprachen zu ihm: Heb\' dich hinaus und gehe von hinnen; denn Herodes will dich toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Und er sprach zu ihnen: Gehet hin und saget demselbigen Fuchs: Siehe, ich treibe Teufel aus und mache gesund heute und morgen und am dritten Tage werde ich ein Ende nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Doch muft ich heute und morgen und am Tage danach wandeln; denn es tut\'s nicht, daß ein Prophet umkomme aufter Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, die du totest die Propheten und steinigest, die zu dir gesandt werden, wie oft habe ich wollen deine Kinder versammeln wie eine Henne ihr Nest unter ihre Flügel; und ihr habt nicht gewollt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Sehet, euer Haus soil euch wüste gelassen werden. Denn ich sage euch: Ihr werdet mich nicht sehen, bis daß es komme, daß ihr sagen werdet: Gelobet ist, der da kommt in dem Namen des Herm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Und es begab sich, daß er kam in ein Haus eines Obersten der Pharisaer auf einen Sabbat, das Brot zu essen. Und sie hielten auf ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Und siehe, da war ein Mensch vor ihm der war wassersuchtig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Und Jesus antwortete und sagte zu den Schriftgelehrten und Pharisaern und sprach: Ist\'s auch recht, auf den Sabbat heilen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Sie aber schwiegen stille. Und er griff ihn an und heilete ihn und lieft ihn gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Und antwortete und sprach zu ihnen: Welcher ist unter euch, dem sein Ochse Oder Esel in den Brunnen fallt, und er nicht alsbald ihn herauszieht am Sabbattage?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Und sie konnten ihm darauf nicht wieder Antwort geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Er sagte aber ein Gleichnis zu den Gasten, da, er merkte, wie sie erwahleten, obenan zu sitzen, und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Wenn du von jemand geladen wirst zur Hochzeit, so setze dich nicht obenan, daß nicht etwa ein Ehrlicherer denn du von ihm geladen sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'und so dann kommt, der dich und ihn geladen hat, spreche zu dir: Weiche diesem! und du mussest dann mit Scham untenan sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Sondern wenn du geladen wirst, so gehe hin und setze dich untenan, auf daß, wenn da kommt, der dich geladen hat, spreche zu dir: Freund, rucke hinauf! Dann wirst du Ehre haben vor denen, die mit dir zu Tische sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Denn wer sich selbst erhohet, der soil erniedriget werden; und wer sich selbst erniedriget, der soli erhohet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Er sprach auch zu dem, der ihn geladen hatte: Wenn du ein Mittags -Oder Abendmahl machest, so lade nicht deine Freunde noch deine Bruder noch deine Gefreundeten noch deine Nachbarn, die da reich sind, auf dad sie dich nicht etwa wieder laden, und dir vergolten werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Sondern wenn du ein Mahl machest, lade die Armen, die Kruppel, die Lahmen, die Blinden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'so bistdu selig; denn sie haben\'s dir nicht zu vergelten; es wird dir aber vergolten werden in der Auferstehung der Gerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Da aber solches horete einer, der mit zu Tisch sad, sprach er zu ihm: Selig ist, der das Brot isset im Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Er aber sprach zu ihm: Es war ein Mensch, der machte ein grod Abendmahl und lud viele dazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Und sandte seinen Knecht aus zur Stunde des Abendmahls, zu sagen den Geladenen: Kommt, denn es ist alles bereit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Und siefingen an alle nacheinander, sich zu entschuldigen. Der erste sprach zu ihm: Ich habe einen Acker gekauft und mud hinausgehen und ihn besehen; ich bitte dich, entschuldige mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Und der andere sprach: Ich habe funf Joch Ochsen gekauft, und ich gehe jetzt hin, sie zu besehen; ich bitte dich, entschuldige mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Und der dritte sprach: Ich habe ein Weib genommen, darum kann ich nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Und der Knecht kam und sagte das seinem Flerrn wieder. Da ward der Flausherr zornig und sprach zu seinem Knechte: Gehe aus bald auf die Straden und Gassen der Stadt und führe die Armen und Kruppel und Lahmen und Blinden herein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Und der Knecht sprach: Flerr, es ist geschehen, was du befohien hast; es ist aber noch Raum da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Und der Herr sprach zu dem Knechte: Gehe aus auf die Landstraden und an die Zaune und notige sie hereinzukommen, auf dad mein Haus voll werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Ich sage euch aber, dad der Manner keiner; die geladen sind; mein Abendmahl schmecken wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Es ging aber viel Volks mit ihm. Und er wandte sich und sprach zu ihnen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'So jemand zu mir kommt und hasset nicht seinen Vater, Mutter, Weib, Kinder, Bruder, Schwestern, auch dazu sein eigen Leben, der kann nicht mein Jünger sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Und wer nicht sein Kreuz tragt und mir nachfolget, der kann nicht mein Jünger sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Wer ist aber unter euch, der einen Turm bauen will und sitzt nicht zuvor und uberschlagt die Kosten, ob er\'s habe hinauszufuhren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'auf dad nicht, wo er den Grund gelegt hat und kann\'s nicht hinausführen, alle, die es sehen, fangen an sein zu spotten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'und sagen: Dieser Mensch hub an zu bauen und kann\'s nicht hinausführen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Oder welcher Konig will sich begeben in einen Streit wider einen andern Konig und sitzt nicht zuvor und ratschlagt, ob er konnte mit zehntausend begegnen dem, der über ihn kommt mit zwanzigtausend?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Wo nicht, so schickt er Botschaft, wenn jener noch feme ist, und bittet urn Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Also auch ein jeglicher unter euch, der nicht absagt allem, was er hat, kann nicht mein Jünger sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Das Salz ist ein gut Ding; wo aber das Salz dumm wird, womit wird man würzen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Es ist weder auf das Land noch in den Mist nütze, sondern man wird\'s wegwerfen. Wer Ohren hat zu horen, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Es naheten aber zu ihm allerlei Zollner und Sünder, daß sie ihn horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Und die Pharisaer und Schriftgelehrten murreten und sprachen: Dieser nimmt die Sünder an und isset mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Er sagte aber zu ihnen dies Gleichnis und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Welcher Mensch ist unter euch, der hundert Schafe hat, und so er der eines verlieret, der nicht lasse die neunundneunzig in der Wüste und hingehe nach dem verloren, bis dal L er\'s finde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Und wenn er\'s funden hat, so legt er\'s auf seine Achseln mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Und wenn er heimkommt, ruft er seine Freunde und Nachbarn und spricht zu ihnen: Freuet euch mit mir; denn ich habe mein Schaf funden, das verloren war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Ich sage euch: Also wird auch Freude im Himmel sein über einen Sünder, der Bute tut, vor neunundneunzig Gerechten, die der Bute nicht bedurfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Oder welch Weib ist, die zehn Groschen hat, so sie der einen verlieret, die nicht ein Licht anzünde und kehre das Haus und suche mit Fleifi, bis daü sie ihn finde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Und wenn sie ihn funden hat, rufet sie ihre Freundinnen und Nachbarinnen und spricht: Freuet euch mit mir; denn ich habe meinen Groschen funden, den ich verloren hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Also auch, sage ich euch, wird Freude sein vor den Engeln Gottes uber einen Sunder, der Bute tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Und er sprach: Ein Mensch hatte zwei Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Und der jungste unter ihnen sprach zum Vater: Gib mir, Vater, das Teil der Guter, das mir gehort! Und er teilete ihnen das Gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Und nicht lange danach sammelte der jungste Sohn alles zusammen und zog feme uber Land; und daselbst brachte er sein Gut um mit Prassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Da er nun all das Seine verzehret hatte, ward eine grofte Teurung durch dasselbige ganze Land, und erfing an zu darben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Und ging hin und hangete sich an einen Burger desselbigen Landes, der schickte ihn auf seinen Acker, die Saue zu hüten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Und er begehrte seinen Bauch zu füllen mit Trebern, die die Saue alien; und niemand gab sie ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Da schlug er in sich und sprach: Wieviel Tagelohner hat mein Vater, die Brot die Fulle haben, und ich verderbe im Hunger!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Ich will mich aufmachen und zu meinem Vater gehen und zu ihm sagen: Vater, ich habe gesundiget gegen den Himmel und vor dir');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'und bin fort nicht mehrwert, daß ich dein Sohn heifte; mache mich zu einem deiner Tagelohner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Und er machte sich auf und kam zu seinem Vater. Da er aber noch feme von dannen war, sah ihn sein Vater, und jammerte ihn, lief und fiel ihm um seinen Hals und kussete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Der Sohn aber sprach zu ihm: Vater, ich habe gesundiget gegen den Himmel und vor dir; ich bin fort nicht mehrwert, daß ich dein Sohn heilie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Aber der Vater sprach zu seinen Knechten: Bringet das beste Kleid hervor und tut es ihm an; und gebet ihm einen Fingerreif an seine Hand und Schuhe an seine Fufte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'und bringet ein gemastet Kalb her und schlachtet es: lasset uns essen und frohlich sein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Denn dieser mein Sohn war tot und ist wieder lebendig worden; erwar verloren und istfunden worden. Und fingen an frohlich zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Aber der alteste Sohn war auf dem Felde, und als er nahe zum Hause kam, horete er das Gesange und den Reigen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'und rief zu sich der Knechte einen und fragte, was das ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Der aber sagte ihm: Dein Bruderistkommen, und dein Vater hat ein gemastet Kalb geschlachtet, daß, er ihn gesund wieder hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Da ward erzornig und wollte nicht hineingehen. Da ging sein Vater heraus und bat ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Er antwortete aber und sprach zum Vater: Siehe, so viel Jahre diene ich dir und habe dein Gebot noch nie ubertreten, und du hast mir nie einen Bock gegeben, daß ich mit meinen Freunden frohlich ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Nun aber dieser dein Sohn kommen ist, der sein Gut mit Huren verschlungen hat, hast du ihm ein gemastet Kalb geschlachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Er aber sprach zu ihm: Mein Sohn, du bist allezeit bei mir, und alles, was mein ist, das ist dein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Du solltest aber frohlich und gutes Muts sein; denn dieser dein Bruder war tot und ist wieder lebendig worden; er war verloren und ist wieder funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Er sprach aberauch zu seinen Jungern: Eswar ein reicher Mann, der hatte einen Haushalter; der ward vor ihm beruchtiget, als hatte er ihm seine Guter umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Und er forderte ihn und sprach zu ihm: Wie hore ich das von dir? Tu Rechnung von deinem Haushalten; denn du kannst hinfort nicht Haushalter sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Der Haushalter sprach bei sich selbst: Was soil ich tun? Mein Herr nimmt das Amt von mir; graben mag ich nicht, so schame ich mich zu betteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ich weift wohl, was ich tun will, wenn ich nun von dem Amt gesetzt werde; daß sie mich in ihre Hauser nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Und er rief zu sich alle Schuldner seines Herrn und sprach zu dem ersten: Wieviel bistdu meinem Herrn schuldig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Er sprach: Hundert Tonnen Oles. Und er sprach zu ihm: Nimm deinen Brief, setze dich und schreib flugs fünfzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Danach sprach erzu dem andern: Du aber, wieviel bistdu schuldig? Er sprach: Hundert Malter Weizen. Und er sprach zu ihm: Nimm deinen Brief und schreib achtzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Und der Herr lobete den ungerechten Haushalter, daß er kluglich getan hatte. Denn die Kinder dieser Welt sind kluger denn die Kinder des Lichts in ihrem Geschlechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Und ich sage euch auch: Machet euch Freunde mit dem ungerechten Mammon, auf daß, wenn ihr nun darbet, sie euch aufnehmen in die ewigen Hütten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Wer im Geringsten treu ist, der ist auch im Groften treu; und wer im Geringsten unrecht ist, der ist auch im Groften unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'So ihr nun in dem ungerechten Mammon nicht treu seid, wer will euch das Wahrhaftige vertrauen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Und so ihr in dem Fremden nicht treu seid, wer will euch geben dasjenige, das euer ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kein Hausknecht kann zweien Herren dienen; entweder erwird einen hassen und den andern lieben, oderwird einem anhangen und den andern verachten. Ihr konnet nicht Gott samt dem Mammon dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Das alles horeten die Pharisaer auch; die waren geizig und spotteten sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Und er sprach zu ihnen: Ihr seid\'s, die ihr euch selbst rechtfertiget vor den Menschen; aber Gott kennet eure Herzen. Denn was hoch ist unter den Menschen, das ist ein Greuel vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Das Gesetz und die Propheten weissagen bis auf Johannes; und von der Zeit an wird das Reich Gottes durchs Evangelium geprediget, und jedermann dringet mit Gewalt hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Es istaber leichter, daß Himmel und Erde vergehen, denn daß ein Tüttel vom Gesetz falle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Wersich scheidet von seinem Weibe und freiet eine andere, der bricht die Ehe; und wer die Abgeschiedene von dem Manne freiet der bricht auch die Ehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Eswaraberein reicher Mann, derkleidete sich mit Purpur und kostlicher Leinwand und lebete alle Tage herrlich und in Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Es war aber ein Armer mit Namen Lazarus, der lag vor seiner Tür voller Schwaren');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'und begehrete, sich zu sattigen von den Brosamen, die von des Reichen Tische fielen. Doch kamen die Hunde und leckten ihm seine Schwaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Es begab sich aber, daß der Arme starb und ward getragen von den Engeln in Abrahams Schoft. Der Reiche aber starb auch und ward begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Als er nun in der Holle und in der Qual war, hub er seine Augen auf und sah Abraham von feme und Lazarus in seinem Schoft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'rief und sprach: Vater Abraham, erbarme dich mein und sende Lazarus, daß er das Aufterste seines Fingers ins Wasser tauche und kühle meine Zunge; denn ich leide Pein in dieser Flamme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham aber sprach: Gedenke, Sohn, daß du dein Gutes empfangen hast in deinem Leben, und Lazarus dagegen hat Boses empfangen; nun aber wird er getrostet, und du wirst gepeiniget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Und uberdas alles istzwischen uns und euch eine grofte Kluft befestiget, daß, die da wollten von hinnen hinabfahren zu euch, konnten nicht und auch nicht von dannen zu uns heruberfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Da sprach er: So bitte ich dich, Vater, daß du ihn sendest in meines Vaters Flaus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'denn ich habe noch funf Bruder, daß er ihnen bezeuge, auf daß sie nicht auch kommen an diesen Ort der Qual.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham sprach zu ihm: Sie haben Mose und die Propheten; laft sie dieselbigen horen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Er aber sprach: Nein, Vater Abraham; sondern wenn einervon den Toten zu ihnen ginge, so würden sie Bufte tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Er sprach zu ihm: Hbren sie Mose und die Propheten nicht, so werden sie auch nicht glauben, ob jemand von den Toten aufstünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Er sprach aberzu seinen Jungern: Es ist unmoglich, daß nicht Argernisse kommen; wehe aber dem, durch welchen sie kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Es ware ihm nützer, daß man einen Muhlstein an seinen Hals hangete und würfe ihn ins Meer, denn daß er dieser Kleinen einen argert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Hutet euch! So dein Bruder an dir sundiget, so strafe ihn; und so er sich bessert, vergib ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Und wenn ersiebenmal des Tages an dir sundigen würde und siebenmal des Tages wieder kame zu dir und sprache: Es reuet mich, so sollst du ihm vergeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Und die Apostel sprachen zu dem Herm: Starke uns den Glauben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Der Herr aber sprach: Wenn ihr Glauben habt als ein Senfkorn und saget zu diesem Maulbeerbaum: Reift dich aus und versetze dich ins Meer, so wird er euch gehorsam sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Welcher ist unter euch, der einen Knecht hat, der ihm pflüget Oder das Vieh weidet, wenn er heimkommt vom Felde, daß er ihm sage: Gehe bald hin und setze dich zu Tische?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ist\'s nicht also, daß erzu ihm saget: Richte zu, daß ich zu Abend esse; schurze dich und diene mir, bis ich esse und trinke; danach sollst du auch essen und trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Danket erauch demselbigen Knechte, daß er getan hat, was ihm befohlen war? Ich meine es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Also auch ihr, wenn ihr alles getan habt, was euch befohlen ist, so sprechet: Wir sind unnutze Knechte; wir haben getan, was wir zu tun schuldig waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Und es begab sich, da er reisete gen Jerusalem, zog er mitten durch Samarien und Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Und als er in einen Markt kam, begegneten ihm zehn aussatzige Manner, die stunden von feme');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'und erhuben ihre Stimme und sprachen: Jesu, lieber Meister, erbarme dich unser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Und da er sie sah, sprach erzu ihnen: Gehet hin und zeiget euch den Priestern. Und es geschah, da sie hingingen, wurden sie rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Einer aber unter ihnen, da ersah, daß er gesund worden war, kehrete er urn und preisete Gott mit lauter Stimme');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'und fiel auf sein Angesicht zu seinen Füften und dankete ihm. Und das war ein Samariter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Jesus aber antwortete und sprach: Sind ihrer nicht zehn rein worden? Wo sind aber die Neune?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Hat sich sonst keiner funden, der wieder umkehrete und, gabe Gott die Ehre, denn dieser Fremdling?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Und er sprach zu ihm: Stehe auf, gehe hin! Dein Glaube hat dir geholfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Da er aber gefraget ward von der Pharisaern: Wann kommt das Reich Gottes? antwortete er ihnen und sprach: Das Reich Gottes kommt nicht mit aufterlichen Gebarden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Man wird nicht sagen: Siehe hier Oder da istes! Denn sehet, das Reich Gottes ist inwendig in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Er sprach aberzu den Jungern: Es wird die Zeit kommen, daß ihrwerdet begehren zu sehen einen Tag des Menschensohns, und werdet ihn nicht sehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Und sie werden zu euch sagen: Siehe hier, siehe da! Gehet nicht hin und folget auch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Denn wie der Blitz oben vom Himmel blitzet und leuchtet uber alles, was unter dem Himmel ist, also wird des Menschen Sohn an seinem Tage sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Zuvoraber muß erviel leiden und verworfen werden von diesem Geschlechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Und wie es geschah zu den Zeiten Noahs, so wird\'s auch geschehen in den Tagen des Menschensohns:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'sie alien, sie tranken, sie freieten, sie lielien sich freien bis auf den Tag, da Noah in die Arche ging, und kam die Sintflut und brachte sie alle um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Desselbigengleichen, wie es geschah zu den Zeiten Lots: sie alien, sie tranken, sie kauften, sie verkauften, sie pflanzten, sie baueten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'An dem Tage aber, da Lot aus Sodom ging, da regnete es Feuer und Schwefel vom Himmel und brachte sie alle um.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Auf diese Weise wird\'s auch gehen an dem Tage; wenn des Menschen Sohn soil offenbaret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'An demselbigen Tage, wer auf dem Dache ist und sein Hausrat in dem Hause, dersteige nicht hernieder, dasselbige zu holen. Desselbigengleichen, wer auf dem Felde ist, der wende nicht um nach dem, das hinter ihm ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Gedenket an des Lots Weib!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Wer da suchet seine Seele zu erhalten, der wird sie verlieren; und wer sie verlieren wird, der wird ihr zum Leben helfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ich sage euch: In derselbigen Nacht werden zwei auf einem Bette liegen; einerwird angenommen, der andere wird verlassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Zwo werden mahlen miteinander; eine wird angenommen, die andere wird verlassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'zwei werden auf dem Felde sein; einerwird angenommen, der andere wird verlassen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Und sie antworteten und sprachen zu ihm: Herr, wo da? Er aber sprach zu ihnen: Wo das Aas ist, da sammeln sich die Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Er sagte ihnen aber ein Gleichnis davon, daß man allezeit beten und nicht laß werden sollte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'und sprach: Es war ein Richter in einer Stadt, der furchtete sich nicht vor Gott und scheuete sich vor keinem Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Es war aber eine Witwe in derselbigen Stadt, die kam zu ihm und sprach: Rette mich von meinem Widersacher!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Und erwollte lange nicht. Danach aber dachte er bei sich selbst: Ob ich mich schon vor Gott nicht furchte, noch vor keinem Menschen scheue,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'dieweil aber mir diese Witwe so viel Muhe macht, will ich sie retten, auf daß sie nicht zuletzt komme und ubertaube mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Da sprach der Herr: Horet her, was der ungerechte Richter sagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Sollte aber Gott nicht auch retten seine Auserwahlten, die zu ihm Tag und Nacht rufen, und sollte Geduld daruber haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Ich sage euch: Er wird sie erretten in einer Kürze. Doch wenn des Menschen Sohn kommen wird, meinest du, daß er auch werde Glauben finden auf Erden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Er sagte aber zu etlichen, die sich selbst vermaßen, daß sie fromm waren, und verachteten die andern, ein solch Gleichnis:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Es gingen zwei Menschen hinauf in den Tempel, zu beten, einer ein Pharisaer, der andere ein Zollner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Der Pharisaer stund und betete bei ich selbst also: Ich danke dir, Gott, daß ich nicht bin wie die andern Leute: Rauber, Ungerechte, Ehebrecher Oder auch wie dieser Zollner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Ich faste zweimal in der Woche und gebe den Zehnten von allem, was ich habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Und der Zollner stund von feme, wollte auch seine Augen nicht aufheben gen Himmel sondern schlug an seine Brust und sprach: Gott, sei mir Sunder gnadig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ich sage euch: Dieser ging hinab gerechtfertiget in sein Haus vor jenem. Denn wer sich selbst erhohet, der wird erniedriget werden; und wer sich selbst erniedriget, der wird erhohet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Sie brachten auch junge Kindlein zu ihm daß er sie sollte anruhren. Da es aber die Junger sahen, bedraueten sie die.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Aber Jesus rief sie zu sich und sprach: Lasset die Kindlein zu mir kommen und wehret ihnen nicht; denn solcher ist das Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Wahrlich, ich sage euch, wer nicht das Reich Gottes nimmt als ein Kind, der wird nicht hineinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Und es fragte ihn ein Oberster und sprach: Guter Meister, was muß ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jesus aber sprach zu ihm: Was heißest du mich gut? Niemand ist gut denn der einige Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Du weißt die Gebote wohl: Du sollst nicht ehebrechen. Du sollst nicht toten. Du sollst nicht stehlen. Du sollst nicht falsch Zeugnis reden. Du sollst deinen Vater und deine Mutter ehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Er aber sprach: Das habe ich alles gehalten von meiner Jugend auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Da Jesus das horete, sprach erzu ihm: Es fehlt dir noch eins. Verkaufe alles, was du hast, und gib\'s den Armen, so wirst du einen Schatz im Himmel haben; und komm und folge mir nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Da erdas horete ward er traurig; denn erwar sehr reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Da aber Jesus sah, daß er traurig war worden, sprach er: Wie schwerlich werden die Reichen in das Reich Gottes kommen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Es ist leichter, daß ein Kamel gehe durch ein Nadelohr, denn daß ein Reicher in das Reich Gottes komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Da sprachen, die das horeten: Wer kann denn selig werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Er aber sprach: Was bei den Menschen unmoglich ist, das ist bei Gott moglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Da sprach Petrus: Siehe, wir haben alles verlassen und sind dir nachgefolget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Er sprach zu ihnen: Wahrlich ich sage euch es ist niemand, der ein Haus verlasset Oder Eltern Oder Bruder Oder Weib Oder Kinder um des Reichs Gottes willen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'der es nicht vielfaltig wieder empfange in dieser Zeit und in der zukunftigen Welt das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Er nahm aber zu sich die Zwolfe und sprach zu ihnen: Sehet, wir gehen hinauf gen Jerusalem, und es wird alles vollendet werden, was geschrieben ist durch die Propheten von des Menschen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Denn er wird uberantwortet werden den Heiden; und erwird verspottet und geschmahet und verspeiet werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'und sie werden ihn geilieln und toten. Und am dritten Tage wird er wieder auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Sie abervernahmen der keines, und die Rede war ihnen verborgen, und wuliten nicht, was das gesagt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Es geschah aber, da er nahe zu Jericho kam, saß ein Blinder am Wege und bettelte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Da er aber horete das Volk, das hindurchging, forschete er, was das ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Da verkundigten sie ihm, Jesus von Nazareth ginge voruber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Und er rief und sprach: Jesu, du Sohn Davids, erbarme dich mein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Die aber vorne an gingen, bedraueten ihn, er sollte schweigen. Er aber schrie viel mehr: Du Sohn Davids, erbarme dich mein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jesus aber stund stille und hiefi ihn zu sich führen. Da sie ihn aber nahe zu ihm brachten, fragte er ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'und sprach: Was willst du, daß ich dir tun soil? Er sprach: Herr, daß ich sehen moge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Und Jesus sprach zu ihm: Sei sehend! Dein Glaube hat dir geholfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Und alsbald ward er sehend und folgete ihm nach und preisete Gott. Und alles Volk, das solches sah, lobete Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Und erzog hinein und ging durch Jericho;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Und siehe, da war ein Mann, genannt Zachaus, der war ein Oberster der Zollner und war reich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Und begehrte Jesum zu sehen, wererware, und konnte nicht vor dem Volk; denn erwar klein von Person.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Und er lief vorhin und stieg auf einen Maulbeerbaum, auf daß er ihn sahe; denn allda sollte erdurchkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Und als Jesus kam an dieselbige Statte, sah er auf und ward sein gewahr und sprach zu ihm: Zachaus, steig eilend hernieder; denn ich muß heute zu deinem Hause einkehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Und er stieg eilend hernieder und nahm ihn auf mit Freuden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Da sie das sahen, murreten sie alle, daß er bei einem Sunder einkehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zachaus aber trat dar und sprach zu dem Herrn: Siehe, Herr, die Halfte meiner Guter gebe ich den Armen, und so ich jemand betrogen habe, das gebe ich vierfaltig wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jesus aber sprach zu ihm: Heute ist diesem Hause Heil widerfahren, sintemal er auch Abrahams Sohn ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'denn des Menschen Sohn ist kommen, zu suchen und selig zu machen, was verloren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Da sie nun zuhoreten, sagte er weiter ein Gleichnis, darum daß er nahe bei Jerusalem war, und sie meineten, das Reich Gottes sollte alsbald offenbart werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'und sprach: Ein Edler zog fern in ein Land, daß er ein Reich einnahme und dann wiederkame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Dieser forderte zehn seiner Knechte und gab ihnen zehn Pfund und sprach zu ihnen: Handelt, bis daß ich wiederkomme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Seine Burger aber waren ihm feind und schickten Botschaft nach ihm und lieüen ihm sagen: Wirwollen nicht, daß dieser uber uns herrsche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Und es begab sich, da erwiederkam nachdem er das Reich eingenommen hatte, hiefi er dieselbigen Knechte fordern, welchen er das Geld gegeben hatte, daß er wulite, was ein jeglicher gehandelt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Da trat herzu der erste und sprach: Herr dein Pfund hat zehn Pfund erworben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Und er sprach zu ihm: Ei du frommer Knecht! Dieweil du bist im Geringsten treu gewesen, sollst du Macht haben uber zehn Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Derandere kam auch und sprach: Herr, dein Pfund hat fünf Pfund getragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Zu dem sprach er auch: Und du sollst sein uber fünf Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Und der dritte kam und sprach: Herr, siehe da, hier ist dein Pfund, welches ich habe im Schweilituch behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Ich furchtete mich vor dir, denn du bist ein harter Mann; du nimmst, was du nicht gelegt hast, und erntest, was du nicht gesaet hart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Er sprach zu ihm: Aus deinem Munde richte ich dich, du Schalk! Wufitest du, dafi ich ein harter Mann bin, nehme, was ich nicht geleget habe, und ernte, was ich nicht gesaet habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Warum hast du denn mein Geld nicht in die Wechselbank gegeben? und wenn ich kommen ware, hatte ich\'s mit Wucher erfordert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Und er sprach zu denen, die dabei stunden: Nehmet das Pfund von ihm und gebet\'s dem, der zehn Pfund hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Und sie sprachen zu ihm: Herr, hat er doch zehn Pfund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Ich sage euch aber: Wer da hat, dem wird gegeben werden; von dem aber, der nicht hat, wird auch das genommen werden, was er hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Doch jene, meine Feinde, die nicht wollten, daß ich uber sie lierrschen sollte, bringet her und erwurget sie vor mir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Und als er solches sagte, zog er fort und reisete hinauf gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Und es begab sich, als er nahete gen Bethphage und Bethanien und kam an den Olberg, sandte er seiner Junger zwei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'und sprach: Gehet hin in den Markt, der gegenuberliegt; und wenn ihr hineinkommet, werdet ihr ein Fullen angebunden finden, auf welchem noch nie kein Mensch gesessen ist. Loset es ab und bringet es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Und so euch jemand fragt; warum ihr\'s abloset, so sagt also zu ihm: Der Herr bedarf sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Und die Gesandten gingen hin und fanden, wie er ihnen gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Da sie aber das Fullen ablbseten, sprachen seine Herren zu ihnen: Warum loset ihr das Fullen ab?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Sie aber sprachen: Der Herr bedarf sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Und sie brachten\'s zu Jesu und warfen ihre Kleider auf das Fullen und setzten Jesum darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Da er nun hinzog, breiteten sie ihre Kleider auf den Weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Und da er nahe hinzukam und zog den Olberg herab, fing an derganze Haufe seiner Junger, mit Freuden Gott zu loben mit lauter Stimme uber alle Taten, die sie gesehen hatten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'und sprachen: Gelobetsei, der da kommt, ein Konig, in dem Namen des Herm! Friede sei im Himmel und Ehre in der Hohe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Und etliche der, Pharisaer im Volk sprachen zu ihm: Meister, strafe doch deine Junger!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Er antwortete und sprach zu ihnen: Ich sage euch: Wo diese werden schweigen, so werden die Steine schreien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Und als er nahe hinzukam, sah er die Stadt an und weinete uber sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'und sprach: Wenn du es wulitest, so wurdest du auch bedenken zu dieser deiner Zeit, was zu deinem Frieden dienet. Aber nun ist\'s vor deinen Augen verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Denn es wird die Zeit uber dich kommen, daß deine Feinde werden urn dich und deine Kinder mit dir eine Wagenburg schlagen, dich belagern und an alien Orten angsten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'und werden dich schleifen und keinen Stein auf dem andern lassen, darum daß du nicht erkannt hast die Zeit, darinnen du heimgesucht bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Und er ging in den Tempel und fing an auszutreiben, die darinnen verkauften und kauften,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'und sprach zu ihnen: Es stehet geschrieben: Mein Haus ist ein Bethaus; ihr aber habt\'s gemacht zur Mordergrube.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Und lehrte taglich im Tempel. Aber die Hohenpriester und Schriftgelehrten und die Vornehmsten im Volk trachteten ihm nach, daß sie ihn umbrachten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'und fanden nicht, wie sie ihm tun sollten; denn alles Volk hing ihm an und horete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Und es begab sich der Tage einen, da er das Volk lehrete im Tempel und predigte das Evangelium, da traten zu ihm die Hohenpriester und Schriftgelehrten mit den Altesten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'und sagten zu ihm und sprachen: Sage uns, aus was fur Macht tust du das? Oder wer hat dir die Macht gegeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Er aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen, saget mir\'s:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Die Taufe des Johannes, war sie vom Himmel Oder von Menschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Sie aber gedachten bei sich selbst und sprachen: Sagen wir, vom Himmel, so wird er sagen: Warum habt ihr ihm denn nicht geglaubt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Sagen wir aber, von Menschen, so wird uns alles Volk steinigen, denn sie stehen darauf, daß Johannes ein Prophet sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Und sie antworteten, sie wuftten\'s nicht, wo sie her ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Und Jesus sprach zu ihnen: So sage ich euch auch nicht, aus was fur Macht ich das tue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Er fing aber an zu sagen dem Volk dieses Gleichnis: Ein Mensch pflanzte einen Weinberg und tat ihn den Weingartnern aus und zog uber Land eine gute Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Und zu seiner Zeit sandte er einen Knecht zu den Weingartnern, daß sie ihm gaben von der Frucht des Weinberges. Aber die Weingartner staupten ihn und lieften ihn leer von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Und uber das sandte er noch einen andern Knecht; sie aber staupten denselbigen auch und hohneten ihn und lieften ihn leer von sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Und uber das sandte erden dritten; sie aber verwundeten den auch und stieften ihn hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Da sprach der Herr des Weinberges: Was soil ich tun? Ich will meinen lieben Sohn senden; vielleicht, wenn sie den sehen, werden sie sich scheuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Da aber die Weingartner den Sohn sahen, dachten sie bei sich selbst und sprachen: Das ist der Erbe; kommt, lasset uns ihn toten, daß das Erbe unser sei!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Und sie stieften ihn hinaus vor den Weinberg und toteten ihn. Was wird nun der Herr des Weinberges denselbigen tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Erwird kommen und diese Weingartner umbringen und seinen Weinberg andern austun. Da sie das horeten, sprachen sie: Das sei feme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Er aber sah sie an und sprach: Was ist denn das, das geschrieben stehet: Der Stein, den die Bauleute verworfen haben, ist zum Eckstein worden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Welcher auf diesen Stein fallt, der wird zerschellen; aufwelchen aber er fallt den wird er zermalmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Und die Hohenpriester und Schriftgelehrten trachteten danach, wie sie die Hande an ihn legten zu derselbigen Stunde, und furchteten sich vor dem Volk; denn sie vernahmen, dafi er auf sie dieses Gleichnis gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Und sie hielten auf ihn und sandten Laurer aus, die sich stellen sollten, als waren sie fromm, auf daß sie ihn in der Rede fingen, damit sie ihn uberantworten konnten der Obrigkeit und Gewalt des Landpflegers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Und sie fragten ihn und sprachen: Meister, wir wissen, daß du aufrichtig redest und lehrest und achtest keines Menschen Ansehen, sondern du lehrest den Weg Gottes recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Ist\'s recht, daß wir dem Kaiser den Scholi geben Oder nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Er aber merkte ihre List und sprach zu ihnen: Was versuchet ihr mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Zeiget mir den Groschen; wes Bild und Uberschrift hat er? Sie antworteten und sprachen: Des Kaisers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Er aber sprach zu ihnen: So gebet dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Und sie konnten sein Wort nicht tadeln vor dem Volk und verwunderten sich seiner Antwort und schwiegen stille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Da traten zu ihm etliche der Sadduzaer, welche da halten, es sei kein Auferstehen, und fragten ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'und sprachen: Meister, Mose hat uns geschrieben: So jemands Bruder stirbt, der ein Weib hat, und stirbt erblos, so soli sein Bruder das Weib nehmen und seinem Bruder einen Samen erwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Nun waren sieben Bruder. Der erste nahm ein Weib und starb erblos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Und der andere nahm das Weib und starb auch erblos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Und der dritte nahm sie. Desselbigengleichen alle sieben und lielien keine Kinder und starben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Zuletzt nach alien starb auch das Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Nun in der Auferstehung, wessen Weib wird sie sein unter denen? Denn alle sieben haben sie zum Weibe gehabt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Und Jesus antwortete und sprach zu ihnen: Die Kinder dieser Welt freien und lassen sich freien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'welche aberwurdig sein werden, jene Welt zu erlangen und die Auferstehung von den Toten, die werden weder freien noch sich freien lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Denn sie konnen hinfort nicht sterben; denn sie sind den Engeln gleich und Gottes Kinder, dieweil sie Kinder sind der Auferstehung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Dali aber die Toten auferstehen, hat auch Mose gedeutet bei dem Busch, da er den Herrn heiliet Gott Abrahams und Gott Isaaks und Gott Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Gott aber ist nicht der Toten, sondern der Lebendigen Gott; denn sie leben ihm alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Da antworteten etliche der Schriftgelehrten und sprachen: Meister, du hast recht gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Und sie durften ihn fürder nichts mehr fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Er sprach aber zu ihnen: Wie sagen sie, Christus sei Davids Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Und er selbst, David, spricht im Psalmbuch: Der Herr hat gesagt zu meinem Herrn: Setze dich zu meiner Rechten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'bis daß ich lege deine Feinde zum Schemel deiner Fülie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David nennet ihn einen Herrn, wie ist er denn sein Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Da aber alles Volk zuhorete, sprach er zu seinen Jungern:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Hutet euch vor den Schriftgelehrten, die da wollen einhertreten in langen Kleidern und lassen sich gerne grufien auf dem Markte und sitzen gerne obenan in den Schulen und uber Tisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Sie fressen der Witwen Hauser und wenden lange Gebete vor; die werden desto schwerere Verdammnis empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Ersah aber auf und schauete die Reichen, wie sie ihre Opfer einlegten in den Gotteskasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Er sah aber auch eine arme Witwe, die legte zwei Scherflein ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Und er sprach: Wahrlich, ich sage euch, diese arme Witwe hat mehr denn sie alle eingelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Denn diese alle haben aus ihrem Uberfluli eingelegt zu dem Opfer Gottes; sie aber hat von ihrer Armut alle ihre Nahrung, die sie hatte, eingelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Und da etliche sagten von dem Tempel, daß er geschmuckt ware von feinen Steinen und Kleinoden, sprach er:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Es wird die Zeit kommen, in welcher des alles, das ihr sehet, nicht ein Stein auf dem andern gelassen wird, der nicht zerbrochen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Sie fragten ihn aber und sprachen: Meister, wann soli das werden? und welches ist das Zeichen, wann das geschehen wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Er aber sprach: Sehet zu, lasset euch nicht verführen! Denn viele werden kommen in meinem Namen und sagen, ich sei es, und: Die Zeit ist herbeikommen. Folget ihnen nicht nach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Wenn ihr aber horen werdet von Kriegen und Emporungen, so entsetzet euch nicht. Denn solches muß zuvor geschehen; aber das Ende ist noch nicht so bald da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Da sprach erzu ihnen: Ein Volk wird sich erheben uber das andere und ein Reich uber das andere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Und werden geschehen grolie Erdbebungen hin und her, teure Zeit und Pestilenz. Auch werden Schrecknisse und grolie Zeichen vom Himmel geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Aber vor diesem allem werden sie die Hande an euch legen und verfolgen und werden euch uberantworten in ihre Schulen und Gefangnisse und vor Konige und Fursten ziehen um meines Namens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Das wird euch aber widerfahren zu einem Zeugnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'So nehmet nun zu Herzen, daß ihr nicht sorget, wie ihr euch verantworten sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Denn ich will euch Mund und Weisheit geben, welcher nicht sollen widersprechen mogen noch widerstehen alle eure Widerwartigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Ihr werdet aber uberantwortet werden von den Eltern, Brudern, Gefreundeten und Freunden; und sie werden euer etliche toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Und ihr werdet gehasset sein von jedermann um meines Namens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Und ein Haar von eurem Hauptsoll nicht umkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Fasseteure Seelen mit Geduld!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Wenn ihr aber sehen werdet Jerusalem belagert mit einem Heer, so merket, daß herbeikommen ist ihre Verwustung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Alsdann wer in Judaa ist, der fliehe auf das Gebirge; und wer mitten drinnen ist, der weiche heraus; und wer auf dem Lande ist, der komme nicht hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Denn das sind die Tage der Rache, daß erfullet werde alles, was geschrieben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Wehe aber den Schwangern und Saugerinnen in denselbigen Tagen! Denn es wird grofte Not auf Erden sein und ein Zorn uber dies Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Und sie werden fallen durch des Schwertes Scharfe und gefangen gefuhrt unter alle Volker; und Jerusalem wird zertreten werden von den Heiden, bis daß der Heiden Zeit erfullet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Und es werden Zeichen geschehen an der Sonne und Mond und Sternen; und auf Erden wird den Leuten bange sein und werden zagen; und das Meer und die Wasserwogen werden brausen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Und die Menschen werden verschmachten vor Furcht und vor Warten der Dinge, die kommen sollen auf Erden; denn auch der Himmel Krafte werden sich bewegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Und alsdann werden sie sehen des Menschen Sohn kommen in der Wolke mit grafter Kraft und Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Wenn aber dieses anfanget zu geschehen, so sehet auf und hebet eure Haupter auf, darum daß sich eure Erlosung nahet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Und er sagte ihnen ein Gleichnis: Sehet an den Feigenbaum und alle Baume!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Wenn sie jetztausschlagen, so sehet ihr\'s an ihnen und merket, daß jetzt der Sommer nahe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Also auch ihr, wenn ihr dies alles sehet angehen, so wisset, daß das Reich Gottes nahe ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Wahrlich, ich sage euch, dies Geschlecht wird nicht vergehen, bis daß es alles geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Himmel und Erde werden vergehen, aber meine Worte vergehen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Aber hütet euch, daß eure Herzen nicht beschweret werden mit Fressen und Saufen und mit Sorgen der Nahrung, und komme dieser Tag schnell uber euch;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'denn wie ein Fallstrick wird er kommen uber alle, die auf Erden wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'So seid nun wacker allezeit und betet, daß ihr würdig werden moget, zu entfliehen diesem allem, was geschehen soil, und zu stehen vor des Menschen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Und er lehrete des Tages im Tempel; des Nachts aber ging er aus und blieb uber Nacht am Olberge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Und alles Volk machte sich fruhe auf zu ihm, im Tempel ihn zu horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Es war aber nahe das Fest der süften Brote, das da Ostern heiftt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Und die Hohenpriester und Schriftgelehrten trachteten, wie sie ihn toteten, und furchteten sich vor dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Es war aber der Satanas gefahren in den Judas, genannt Ischariot, der da war aus der Zahl der Zwolfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Und er ging hin und redete mit den Hohenpriestern und mit den Hauptleuten, wie erihn wollte ihnen uberantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Und sie wurden froh und gelobten, ihm Geld zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Und er versprach es und suchte Gelegenheit, daß er ihn überantwortete ohne Rumor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Es kam nun der Tag der süften Brote, auf welchen man muftte opfern das Osterlamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Und er sandte Petrus und Johannes und sprach: Gehet hin, bereitet uns das Osterlamm, auf daß wir\'s essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Sie aber sprachen zu ihm: Wo willst du, daß wir\'s bereiten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Er sprach zu ihnen: Siehe, wenn ihr hineinkommt in die Stadt, wird euch ein Mensch begegnen, der tragt einen Wasserkrug; folget ihm nach in das Haus, da er hineingehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'und saget zu dem Hausherm: Der Meister laftt dir sagen: Wo ist die Herberge, darinnen ich das Osterlamm essen moge mit meinen Jüngem?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Und erwird euch einen groften gepflasterten Saal zeigen; daselbst bereitet es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Sie gingen hin und fanden, wie er ihnen gesagt hatte, und bereiteten das Osterlamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Und da die Stunde kam, setzte er sich nieder und die zwolf Apostel mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Und er sprach zu ihnen: Mich hat herzlich verlanget, dies Osterlamm mit euch zu essen, ehe denn ich leide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Denn ich sage euch, daß ich hinfort nicht mehr davon essen werde, bis daß es erfullet werde im Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Und ernahm den Kelch, dankete und sprach: Nehmet denselbigen und teilet ihn unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Denn ich sage euch: Ich werde nicht trinken von dem Gewachse des Weinstocks, bis das Reich Gottes komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Und er nahm das Brot, dankete und brach\'s und gab\'s ihnen und sprach: Das ist mein Leib, der fur euch gegeben wird; das tutzu meinem Gedachtnis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Desselbigengleichen auch den Kelch nach dem Abendmahl und sprach: Das ist der Kelch, das neue Testament in meinem Blut, das fur euch vergossen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Doch siehe, die Hand meines Verraters ist mit mir uber Tische!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Und zwar, des Menschen Sohn gehet hin, wie es beschlossen ist; doch wehe demselbigen Menschen, durch welchen er verraten wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Und sie fingen an zu fragen unter sich selbst, welcher es doch ware unter ihnen, der das tun würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Es erhub sich auch ein Zank unter ihnen, welcher unter ihnen sollte fur den Großten gehalten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Er aber sprach zu ihnen: Die weltlichen Konige herrschen, und die Gewaltigen heifit man gnadige Herren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Ihr aber nicht also, sondern der Großte unter euch soli sein wie der Jungste und der Vornehmste wie ein Diener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Denn welcher ist der Grofite, der zu Tische sitzt, Oder der da dienet? Ist\'s nicht also, daß der zu Tische sitzt? Ich aber bin unter euch wie ein Diener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Ihr aber seid\'s, die ihr beharret habt bei mir in meinen Anfechtungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Und ich will euch das Reich bescheiden, wie mir\'s mein Vater beschieden hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'daß ihr essen und trinken sollt über meinem Tische in meinem Reich und sitzen auf Stuhlen und richten die zwolf Geschlechter Israels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Der Herr aber sprach: Simon, Simon, siehe, der Satanas hat euer begehrt, daß er euch mochte sichten wie den Weizen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Ich aber habe fur dich gebeten, daß dein Glaube nicht aufhore. Und wenn du dermaleinst dich bekehrest, so starke deine Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Er sprach aber zu ihm: Herr, ich bin bereit mit dir ins Gefangnis und in den Tod zu gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Er aber sprach: Petrus, ich sage dir, der Hahn wird heute nicht krahen, ehe denn du dreimal verleugnet hast, daß du mich kennest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Und er sprach zu ihnen: So oft ich euch gesandt habe ohne Beutel, ohne Tasche und ohne Schuhe, habt ihr auch je Mangel gehabt? Sie sprachen: Nie keinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Da sprach er zu ihnen: Aber nun, wer einen Beutel hat, der nehme ihn, desselbigengleichen auch die Tasche; wer aber nicht hat, verkaufe sein Kleid und kaufe ein Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Denn ich sage euch: Es rnuß noch das auch vollendet werden an mir, das geschrieben stehet: Er ist unter die Ubeltater gerechnet. Denn was von mir geschrieben ist, das hat ein Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Sie sprachen aber: Herr, siehe, hier sind zwei Schwerter. Er aber sprach zu ihnen: Es ist genug.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Und er ging hinaus nach seiner Gewohnheit an den Olberg. Es folgeten ihm aber seine Junger nach an denselbigen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Und als er dahin kam, sprach er zu ihnen: Betet, auf daß ihr nicht in Anfechtung fallet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Und er riß sich von ihnen bei einem Steinwurf und kniete nieder, betete');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'und sprach: Vater, willst du, so nimm diesen Kelch von mir; doch nicht mein, sondern dein Wille geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Es erschien ihm aber ein Engel vom Himmel und starkete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Und es kam, daß er mit dem Tode rang, und betete heftiger. Es ward aber sein Schweiß wie Blutstropfen, die fielen auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Und er stund auf vom Gebet und kam zu seinen Jungern und fand sie schlafend vor Traurigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Und sprach zu ihnen: Was schlafet ihr? Stehet auf und betet, auf dafi ihr nicht in Anfechtung fallet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Da er aber noch redete, siehe, die Schar und einer von den Zwolfen, genannt Judas, ging vor ihnen her und nahete sich zu Jesu, ihn zu küssen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jesus aber sprach zu ihm: Judas, verratst du des Menschen Sohn mit einem Kul J?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Da aber sahen, die urn ihn waren, was da werden wollte, sprachen sie zu ihm: Herr, sollen wir mit dem Schwert dreinschlagen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Und einer aus ihnen schlug des Hohenpriesters Knecht und hieb ihm sein rechtes Ohrab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Jesus aber antwortete und sprach: Lasset sie doch so feme machen! Und er ruhrete sein Ohr an und heilete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Jesus aber sprach zu den Hohenpriestern und Hauptleuten des Tempels und den Altesten, die über ihn kommen waren: Ihrseid, wie zu einem Morder, mit Schwertern und mit Stangen ausgegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Ich bin taglich bei euch im Tempel gewesen, und ihr habt keine Hand an mich gelegt; aber dies ist eure Stunde und die Macht der Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Sie griffen ihn aber und führeten ihn und brachten ihn in des Hohenpriesters Haus. Petrus aber folgete von feme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Da zundeten sie ein Feuer an mitten im Palast und setzten sich zusammen, und Petrus setzte sich unter sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Da sah ihn eine Magd sitzen bei dem Licht und sah eben auf ihn und sprach zu ihm: Dieser war auch mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Er aber verleugnete ihn und sprach: Weib, ich kenne ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Und über eine kleine Weile sah ihn ein anderer und sprach: Du bist auch der einer. Petrus aber sprach: Mensch, ich bin\'s nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Und liber eine Weile, bei einer Stunde, bekraftigte es ein anderer und sprach: Wahrlich, dieser war auch mit ihm; denn er ist ein Galilaer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Petrus aber sprach: Mensch, ich weiß nicht, was du sagest! Und alsbald, da er noch redete, krahete der Hahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Und der Herr wandte sich und sah Petrus an. Und Petrus gedachte an des Herrn Wort, das erzu ihm gesagt hatte: Ehe denn der Hahn krahet, wirst du mich dreimal verleugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Und Petrus ging hinaus und weinete bitterlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Die Manner aber, die Jesum hielten, verspotteten ihn und schlugen ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'verdecketen ihn und schlugen ihn ins Angesicht und fragten ihn und sprachen: Weissage, wer ist\'s, der dich schlug?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Und viel andere Lasterungen sagten sie wider ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Und als es Tag ward, sammelten sich die Altesten des Volks, die Hohenpriester und Schriftgelehrten, und fuhreten ihn hinauf vor ihren Rat');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'und sprachen: Bist du Christus? Sage es uns! Er sprach aber zu ihnen: Sage ich\'s euch, so glaubet ihr\'s nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'frage ich aber, so antwortet ihr nicht und lasset mich doch nicht los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Darum von nun an wird des Menschen Sohn sitzen zur rechten Hand der Kraft Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Da sprachen sie alle: Bist du denn Gottes Sohn? Er sprach zu ihnen: Ihr saget es, denn ich bin\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Sie aber sprachen: Was bedurfen wir weiter Zeugnis? Wir haben\'s selbst gehoret aus seinem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Und der ganze Haufe stund auf und fuhreten ihn vor Pilatus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'und fingen an, ihn zu verklagen, und sprachen: Diesen finden wir, daß er das Volk abwendet und verbietet, den Schoß dem Kaiser zu geben, und spricht, er sei Christus, ein Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilatus aberfragte ihn und sprach: Bistdu der Juden Konig? Er antwortete ihm und sprach: Du sagest es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus sprach zu den Hohenpriestern und zum Volk: Ich finde keine Ursache an diesem Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Sie aber hielten an und sprachen: Er hat das Volk erreget damit, daß er gelehret hat hin und her im ganzen judischen Lande, und hat in Galilaa angefangen bis hieher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Da aber Pilatus Galilaa horete, fragte er, ob er aus Galilaa ware,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Und als er vernahm, daß er unter des Herodes Obrigkeit gehorete, ubersandte er ihn zu Herodes, welcher in denselbigen Tagen auch zu Jerusalem war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Da aber Herodes Jesum sah, ward er sehr froh, denn er hatte ihn langst gerne gesehen; denn er hatte viel von ihm gehoret und hoffete, er würde ein Zeichen von ihm sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Und er fragte ihn mancherlei; er antwortete ihm aber nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Die Hohenpriester aber und Schriftgelehrten stunden und verklagten ihn hart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Aber Herodes mit seinem Hofgesinde verachtete und verspottete ihn, legte ihm ein weili Kleid an und sandte ihn wieder zu Pilatus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Auf den Tag wurden Pilatus und Herodes Freunde miteinander; denn zuvor waren sie einander feind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilatus aber rief die Hohenpriester und die Obersten und das Volk zusammen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'und sprach zu ihnen: Ihr habt diesen Menschen zu mir gebracht, als der das Volk abwende. Und siehe, ich habe ihn vor euch verhoret und finde an dem Menschen der Sachen keine, der ihr ihn beschuldiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Herodes auch nicht; denn ich habe euch zu ihm gesandt, und siehe, man hat nichts auf ihn gebracht, was des Todeswertsei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Darum will ich ihn zuchtigen und loslassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Denn ermutite ihnen einen nach Gewohnheit des Festes losgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Da schrie der ganze Haufe und sprach: Hinweg mit diesem und gib uns Barabbas los!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'welcher war urn eines Aufruhrs, so in der Stadt geschehen war, und urn eines Mords willen ins Gefangnis geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Da rief Pilatus abermal ihnen zu und wollte Jesum loslassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Sie riefen aber und sprachen: Kreuzige, kreuzige ihn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Er aber sprach zum drittenmal zu ihnen: Was hat denn dieser Ubels getan? Ich finde keine Ursache des Todes an ihm; darum will ich ihn zuchtigen und loslassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Aber sie lagen ihm an mit großem Geschrei und forderten, daß er gekreuziget würde. Und ihr und der Hohenpriester Geschrei nahm uberhand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilatus aber urteilete, daß ihre Bitte geschahe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'und ließ den los, der urn Aufruhrs und Mords willen war ins Gefangnis geworfen, urn welchen sie baten; aber Jesum ubergab er ihrem Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Und als sie ihn hinfuhreten, ergriffen sie einen, Simon von Kyrene, der kam vom Felde, und legten das Kreuz auf ihn, daß er\'s Jesu nachtruge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Es folgete ihm aber nach ein großer Haufe Volks und Weiber, die klageten und beweineten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jesus aber wandte sich urn zu ihnen und sprach: Ihr Tochter von Jerusalem, weinet nicht uber mich, sondern weinet über euch selbst und fiber eure Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Denn siehe, es wird die Zeit kommen, in welcher man sagen wird: Selig sind die Unfruchtbaren und die Leiber, die nicht geboren haben, und die Brfiste, die nicht gesauget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Dann werden sie anfangen zu sagen zu den Bergen: Fallet über uns! und zu den Hugeln: Decket uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Denn so man das tut am grunen Holz, was will am durren werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Es wurden aber auch hingefuhrt zwei andere Ubeltater, dad sie mit ihm abgetan wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Und als sie kamen an die Statte die da heifit Schadelstatte, kreuzigten sie ihn daselbst und die Ubeltater mit ihm, einen zur Rechten und einen zur Linken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jesus aber sprach: Vater, vergib ihnen; denn sie wissen nicht was sie tun. Und sie teileten seine Kleider und warfen das Los darum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Und das Volk stund und sah zu. Und die Obersten samt ihnen spotteten sein und sprachen: Er hat andern geholfen, er helfe sich selber, ist er Christ, der Auserwahlte Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Es verspotteten ihn auch die Kriegsknechte, traten zu ihm und brachten ihm Essig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'und sprachen: Bistdu der Juden Konig, so hilf dir selber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Es war auch oben uber ihm geschrieben die Uberschrift mit griechischen und lateinischen und ebraischen Buchstaben: Dies ist der Juden Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Aber der Ubeltater einer, die da gehenkt waren, lasterte ihn und sprach: Bist du Christus, so hilf dir selbst und uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Da antwortete der andere, strafte ihn und sprach: Und du furchtest dich auch nicht vor Gott, der du doch in gleicher Verdammnis bist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Und zwar wir sind bilüg darinnen; denn wir empfangen, was unsere Taten wert sind; dieser aber hat nichts Ungeschicktes gehandelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Und sprach zu Jesu: Herr, gedenke an mich wenn du in dein Reich kommst!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Und Jesus sprach zu ihm: Wahrlich, ich sage dir, heute wirst du mit mir im Paradies sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Und es war urn die sechste Stunde. Und es ward eine Finsternis uber das ganze Land bis an die neunte Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Und die Sonne verlor ihren Schein, und der Vorhang des Tempels zerrifi mitten entzwei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Und Jesus rief laut und sprach: Vater, ich befehle meinen Geist in deine Hande! Und als er das gesagt, verschied er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Da aber der Hauptmann sah, was da geschah; preisete er Gott und sprach: Fürwahr, dieser ist ein frommer Mensch gewesen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Und alles Volk, das dabei war und zusah, da sie sahen, was da geschah, schlugen sich an ihre Brust und wandten wieder urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Es stunden aber alle seine Verwandten von feme und die Weiber, die ihm aus Galilaa waren nachgefolget, und sahen das alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Und siehe, ein Mann mit Namen Joseph, ein Ratsherr, der war ein guter, frommer Mann;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'der hatte nicht bewilliget in ihren Rat und Handel; der war von Arimathia, der Stadt der Juden, der auch auf das Reich Gottes wartete:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'der ging zu Pilatus und bat urn den Leib Jesu');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'und nahm ihn ab, wickelte ihn in Leinwand und legte ihn in ein gehauen Grab, darinnen niemand je gelegen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Und es war der Rusttag, und der Sabbat brach an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Es folgeten aber die Weiber nach, die mit ihm kommen waren aus Galilaa, und beschaueten das Grab, und wie sein Leib gelegt ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Sie kehreten aber urn und bereiteten Spezerei und Salben. Und den Sabbat uber waren sie stille nach dem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Aber an der Sabbate einem sehr fruhe kamen sie zum Grabe und trugen die Spezerei, die sie bereitet hatten, und etliche mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Sie fanden aber den Stein abgewalzet von dem Grabe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'und gingen hinein und fanden den Leib des Herm Jesu nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Und da sie darum bekümmert waren, siehe, da traten zu ihnen zwei Manner mit glanzenden Kleidern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Und sie erschraken und schlugen ihre Angesichte nieder zu der Erde. Da sprachen die zu ihnen: Was suchet ihr den Lebendigen bei den Toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Er ist nicht hier, er ist auferstanden. Gedenket daran, wie er euch sagte, da er noch in Galilaa war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'und sprach: Des Menschen Sohn muft uberantwortet werden in die Hande der Sunder und gekreuziget werden und am dritten Tage auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Und sie gedachten an seine Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Und sie gingen wieder vom Grabe und verkundigten das alles den Elfen und den andern alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Es war aber Maria Magdalena und Johanna und Maria, des Jakobus Mutter, und andere mit ihnen, die solches den Aposteln sagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Und es deuchten sie ihre Worte eben, als waren\'s Marlein, und glaubten ihnen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Petrus aber stund auf und lief zum Grabe und buckete sich hinein und sah die leinenen Tucher ailein liegen und ging davon; und es nahm ihn wunder, wie es zuginge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Und siehe, zwei aus ihnen gingen an demselbigen Tage in einen Flecken, der war von Jerusalem sechzig Feldwegs weit, des Name heißt Emmaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Und sie redeten miteinandervon alien diesen Geschichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Und es geschah, da sie so redeten und befragten sich miteinander, nahete Jesus zu ihnen und wandelte mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Aber ihre Augen wurden gehalten, dafi sie ihn nicht kannten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Er sprach aber zu ihnen: Was sind das fur Reden, die ihrzwischen euch handelt unterwegs, und seid traurig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Da antwortete einer mit Namen Kleophas und sprach zu ihm: Bist du allein unter den Fremdlingen zu Jerusalem, der nicht wisse, was in diesen Tagen drinnen geschehen ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Und er sprach zu ihnen: Welches? Sie aber sprachen zu ihm: Das von Jesu von Nazareth, welcher war ein Prophet, machtig von Taten und Worten vor Gott und allem Volk;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'wie ihn unsere Hohenpriester und Obersten uberantwortet haben zur Verdammnis des Todes und gekreuziget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Wir aber hoffeten, er sollte Israel erlosen. Und uber das alles ist heute der dritte Tag, dafi solches geschehen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Auch haben uns erschreckt etliche Weiber der Unsern, die sind fruhe bei dem Grabe gewesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'haben seinen Leib nicht funden, kommen und sagen, sie haben ein Gesichtder Engel gesehen, welche sagen, er lebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Und etliche unter uns gingen hin zum Grabe und fanden\'s also, wie die Weiber sagten; aber ihn fanden sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Und er sprach zu ihnen: O ihr Toren und trages Herzens, zu glauben alle dem, das die Propheten geredet haben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Mul Jte nicht Christus solches leiden und zu seiner Herrlichkeit eingehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Und ting an von Mose und alien Propheten und legte ihnen alle Schriften aus, die von ihm gesagt waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Und sie kamen nahe zum Flecken, da sie hingingen. Und er stellete sich, als wollte er furder gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Und sie notigten ihn und sprachen: Bleibe bei uns; denn es will Abend werden, und der Tag hat sich geneiget. Und er ging hinein, bei ihnen zu bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Und es geschah, da er mit ihnen zu Tische saß, nahm er das Brot, dankete und brach\'s und gab\'s ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Da wurden ihre Augen geoffnet und erkannten ihn. Und er verschwand vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Und sie sprachen untereinander: Brannte nicht unser Herz in uns, da er mit uns redete auf dem Wege, als er uns die Schrift offnete?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Und sie stunden auf zu derselbigen Stunde, kehreten wieder gen Jerusalem und fanden die Elfe versammelt und die bei ihnen waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'welche sprachen: Der Herr ist wahrhaftig auferstanden und Simon erschienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Und sie erzahleten ihnen, was auf dem Wege geschehen war, und wie er von ihnen erkannt ware an dem, da erdas Brot brach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Da sie aber davon redeten, trat er selbst, Jesus, mitten unter sie und sprach zu ihnen: Friede sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Sie erschraken aber und furchteten sich, meineten, sie sahen einen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Und er sprach zu ihnen: Was seid ihr so erschrocken, und warum kommen solche Gedanken in euer Herz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Sehet meine Hande und meine Füße, ich bin\'s selber; fühlet mich und sehet; denn ein Geist hat nicht Fleisch und Bein, wie ihr sehet, daß ich habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Und da er das sagte, zeigte er ihnen Hande und Fül Je.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Da sie aber noch nicht glaubten vor Freuden und sich verwunderten, sprach erzu ihnen: Habt ihr hier etwas zu essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Und sie legten ihm vor ein Stuck von gebratenem Fisch und Honigseims.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Und ernahm\'s und ali vor ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Er aber sprach zu ihnen: Das sind die Reden, die ich zu euch sagte, da ich noch bei euch war; denn es muß alles erfullet werden, was von mir geschrieben ist im Gesetz Mose\'s, in den Propheten und in Psalmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Da offnete er ihnen das Verstandnis, daß sie die Schrift verstunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Und sprach zu ihnen: Also ist\'s geschrieben, und also mußte Christus leiden und auferstehen von den Toten am dritten Tage');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'und predigen lassen in seinem Namen Buße und Vergebung der Sunden unter alien Volkern und anheben zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Ihr aber seid des alles Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Und siehe, ich will auf euch senden die Verheifiung meines Vaters. Ihr aber sollt in der Stadt Jerusalem bleiben, bis daß ihr angetan werdet mit Kraft aus der Hohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Er fuhrete sie aber hinaus gen Bethanien und hub die Hande auf und segnete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Und es geschah, da er sie segnete, schied er von ihnen und fuhrauf gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Sie aber beteten ihn an und kehrten wieder gen Jerusalem mitgroßer Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Und waren allewege im Tempel, preiseten und lobeten Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Im Anfang war das Wort, und das Wort war bei Gott, und Gott war das Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Dasselbige war im Anfang bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Alle Dinge sind durch dasselbige gemacht, und ohne dasselbige ist nichts gemacht, was gemacht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'In ihm war das Leben, und das Leben war das Lichtder Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Und das Licht scheinet in der Finsternis, und die Finsternis hat\'s nicht begriffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Es war ein Mensch, von Gott gesandt, der hieli Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Derselbige kam zum Zeugnis, daß er von dem Licht zeugete, auf daß sie alle durch ihn glaubeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Er war nicht das Licht, sondern daß er zeugete von dem Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Das war das wahrhaftige Licht, welches alle Menschen erleuchtet die in diese Welt kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Es war in der Welt, und die Welt ist durch dasselbige gemacht, und die Welt kannte es nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Er kam in sein Eigentum, und die Seinen nahmen ihn nicht auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Wie viele ihn aber aufnahmen, denen gab er Macht, Gottes Kinder zu werden, die an seinen Namen glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Welche nicht von dem Geblut, noch von dem Willen des Fleisches, noch von dem Willen eines Mannes, sondern von Gott geboren sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Und das Wort ward Fleisch und wohnete unter uns, und wir sahen seine Herrlichkeit, eine Herrlichkeit als des eingebornen Sohnes vom Vater, voller Gnade und Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes zeuget von ihm, ruft und spricht: Dieser war es, von dem ich gesagt habe: nach mir wird kommen, der vor mir gewesen ist; denn er war eher denn ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Und von seiner Fulle haben wir alle genommen Gnade urn Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Denn das Gesetz ist durch Mose gegeben; die Gnade und Wahrheit ist durch Jesum Christum worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Niemand hat Gott jegesehen. Dereingeborne Sohn, der in des Vaters Scholi ist, der hat es uns verkundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Und dies ist das Zeugnis Johannes, da die Juden sandten von Jerusalem Priester und Leviten, daß sie ihn fragten: Wer bist du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Und er bekannte und leugnete nicht; und er bekannte: Ich bin nicht Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Und sie fragten ihn: Was denn? Bist du Elia? Er sprach: Ich bin\'s nicht. Bist du ein Prophet? Und er antwortete: Nein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Da sprachen sie zu ihm: Was bist du denn? daß wir Antwort geben denen, die uns gesandt haben. Was sagst du von dir selbst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Er sprach: Ich bin eine Stimme eines Predigers in der Wüste: Richtet den Weg des Herrn! wie der Prophet Jesaja gesagt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Und die gesandt waren, die waren von den Pharisaern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'und fragten ihn und sprachen zu ihm: Warum taufest du denn, so du nicht Christus bist noch Elia noch ein Prophet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johannes antwortete ihnen und sprach: Ich taufe mit Wasser; aber er ist mitten unter euch getreten, den ihr nicht kennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Der der nach mir kommen wird, welcher vor mir gewesen ist, des ich nicht wert bin, dad ich seine Schuhriemen auflose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dies geschah zu Bethabara, jenseit des Jordans, da Johannes taufete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Des andern Tages siehet Johannes Jesum zu ihm kommen und spricht: Siehe, das ist Gottes Lamm, welches der Welt Sünde tragt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Dieser ist\'s, von dem ich gesagt habe: Nach mir kommt ein Mann, welcher vor mir gewesen ist; denn er war eher denn ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Und ich kannte ihn nicht, sondern auf daß er offenbar würde in Israel, darum bin ich kommen, zu taufen mit Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Und Johannes zeugete und sprach: Ich sah, daß der Geist herabfuhrwie eine Taube vom Himmel und blieb auf ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'und ich kannte ihn nicht; aber der mich sandte, zu taufen mit Wasser, derselbige sprach zu mir: Uber welchen, du sehen wirst den Geist herabfahren und auf ihm bleiben, derselbige ist\'s, der mit dem Heiligen Geist taufet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Und ich sah es und zeugete, daß dieser ist Gottes Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Des andern Tags stund abermal Johannes und zwei seiner Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Und als er sah Jesum wandeln, sprach, er: Siehe, das ist Gottes Lamm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Und zwei seiner Junger horeten ihn reden und folgeten Jesu nach?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jesus aber wandte sich urn und sah sie nachfolgen und sprach zu ihnen: Was suchet ihr? Sie aber sprachen zu ihm: Rabbi (das ist verdolmetscht, Meister), wo bist du zur Herberge?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Er sprach zu ihnen: Kommt und sehet es! Sie kamen und sahen\'s und blieben denselbigen Tag bei ihm. Es war aber urn die zehnte Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Einer aus den zwei, die von Johannes horeten und Jesu nachfolgeten, war Andreas, der Bruder des Simon Petrus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Derselbige findet am ersten seinen Bruder Simon und spricht zu ihm: Wir haben den Messias funden (welches ist verdolmetscht: der Gesalbte).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Und fuhrete ihn zu Jesu. Da ihn Jesus sah, sprach er: Du bist Simon, Jonas Sohn; du sollst Kephas heilien (das wird verdolmetscht: ein Fels).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Des andern Tags wollte Jesus wieder nach Galilaa ziehen und findet Philippus und spricht zu ihm: Folge mirnach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Philippus aber war von Bethsaida, aus der Stadt des Andreas und Petrus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus findet Nathanael und spricht zu ihm: Wir haben den funden, von welchem Mose im Gesetz und die Propheten geschrieben, Jesum, Josephs Sohn, von Nazareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Und Nathanael sprach zu ihm: Was kann von Nazareth Gutes kommen? Philippus spricht zu ihm: Komm und siehe es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus sah Nathanael zu sich kommen und spricht von ihm: Siehe, ein rechter Israelit, in welchem kein Falsch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanael spricht zu ihm: Woher kennest du mich? Jesus antwortete und sprach zu ihm: Ehe denn dich Philippus rief, da du unterdem Feigenbaum warest, sah ich dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanael antwortet und spricht zu ihm: Rabbi, du bist Gottes Sohn, du bist der Konig von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus antwortete und sprach zu ihm: Du glaubest, weil ich dir gesagt habe, daß ich dich gesehen habe unter dem Feigenbaum; du wirst noch Großeres denn das sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Und spricht zu ihm: Wahrlich, wahrlich, ich sage euch, von nun an werdet ihr den Himmel offen sehen und die Engel Gottes hinauf- und herabfahren auf des Menschen Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Und am dritten Tage ward eine Hochzeitzu Kana in Galilaa; und die Mutter Jesu war da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Jesus aber und seine Junger wurden auch auf die Hochzeit geladen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Und da es an Wein gebrach, spricht die Mutter Jesu zu ihm: Sie haben nicht Wein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jesus spricht zu ihr: Weib, was habe ich mit dir zu schaffen? Meine Stunde ist noch nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Seine Mutter spricht zu den Dienern: Was er euch saget, das tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Es waren aber allda sechs steinerne Wasserkruge gesetzt nach der Weise der judischen Reinigung, und gingen in je einen zwei Oder drei Mali.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesus spricht zu ihnen: Fullet die Wasserkruge mit Wasser. Und sie fulleten sie bis obenan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Und er spricht zu ihnen: Schopfet nun und bringet\'s dem Speisemeister. Und sie brachten\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Als aber der Speisemeister kostete den Wein, der Wasser gewesen war, und wußte nicht, von wannen er kam (die Diener aber wußten\'s, die das Wasser geschopft hatten), rufet der Speisemeister den Brautigam');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'und spricht zu ihm: Jedermann gibtzum ersten guten Wein, und wenn sie trunken worden sind, alsdann den geringern; du hast den guten Wein bisher behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Das ist das erste Zeichen, das Jesus tat, geschehen zu Kana in Galilaa und offenbarte seine Herrlichkeit. Und seine Junger glaubten an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Danach zog er hinab gen Kapernaum, er, seine Mutter, seine Bruder und seine Junger, und blieben nicht lange daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Undder Juden Osternwarnahe. Und Jesus zog hinauf gen Jerusalem');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'und fand im Tempel sitzen, die da Ochsen, Schafe und Tauben feil hatten, und die Wechsler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Und er machte eine Geißel aus Stricken und trieb sie alle zum Tempel hinaus samt den Schafen und Ochsen und verschuttete den Wechslern das Geld und stieß die Tische urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Und sprach zu denen, die die Tauben feil hatten: Traget das von dannen und machet nicht meines Vaters Haus zum Kaufhause!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Seine Junger aber gedachten daran, daß geschrieben stehet: Der Eifer urn dein Haus hat mich gefressen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Da antworteten nun die Juden und sprachen zu ihm: Was zeigst du uns fur ein Zeichen, daß du solches tun mogest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus antwortete und sprach zu ihnen: Brechet diesen Tempel, und am dritten Tage will ich ihn aufrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Da sprachen die Juden: Dieser Tempel ist in sechsundvierzig Jahren erbauet, und du willst ihn in dreien Tagen aufrichten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Er aber redete von dem Tempel seines Leibes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Da er nun auferstanden war von den Toten, gedachten seine Junger daran, daß er dies gesagt hatte, und glaubten der Schrift und der Rede, die Jesus gesagt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Als er aber zu Jerusalem war in den Ostern auf dem Fest, glaubten viele an seinen Namen, da sie die Zeichen sahen, die ertat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Aber Jesus vertrauete sich ihnen nicht; denn er kannte sie alle');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'und bedurfte nicht, daß jemand Zeugnis gabe von einem Menschen; denn erwußte wohl, was im Menschen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Es war aber ein Mensch unter den Pharisaern mit Namen Nikodemus, ein Oberster unter den Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Der kam zu Jesu bei der Nacht und sprach zu ihm: Meister, wirwissen, daß du bist ein Lehrer, von Gott kommen; denn niemand kann die Zeichen tun, die du tust, es sei denn Gott mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus antwortete und sprach zu ihm: Wahrlich, wahrlich, ich sage dir: Es sei denn, daß jemand von neuem geboren werde, kann er das Reich Gottes nicht sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemus spricht zu ihm: Wie kann ein Mensch geboren werden, wenn er alt ist? Kann er auch wiederum in seiner Mutter Leib gehen und geboren werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus antwortete: Wahrlich, wahrlich, ich sage dir: Es sei denn, daß jemand geboren werde aus dem Wasser und Geist, so kann er nicht in das Reich Gottes kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Was vom Fleisch geboren wird, das ist Fleisch, und was vom Geist geboren wird, das ist Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Laß dich\'s nicht wundern, daß ich dir gesagt habe: Ihrmüssetvon neuem geboren werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Der Wind blaset, wo er will, und du horest sein Sausen wohl; aber du weißt nicht, von wannen er kommt und wohin er fahret. Also ist ein jeglicher, der aus dem Geist geboren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodemus antwortete und sprach zu ihm: Wie mag solches zugehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus antwortete und sprach zu ihm: Bist du ein Meister in Israel und weißt das nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Wahrlich, wahrlich, ich sage dir, wir reden, was wirwissen, und zeugen, was wir gesehen haben, und ihr nehmet unser Zeugnis nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Glaubt ihr nicht, wenn ich euch von irdischen Dingen sage, wie wurdet ihr glauben, wenn ich euch von himmlischen Dingen sagen würde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Und niemand fahret gen Himmel, denn der vom Himmel herniederkommen ist, namlich des Menschen Sohn, derim Himmel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Und wie Mose in der Wüste eine Schlange erhohet hat, also muß des Menschen Sohn erhohet werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'auf daß alle, die an ihn glauben, nicht verloren werden, sondern das ewige Leben haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Also hat Gott die Welt geliebet, daß er seinen eingeborenen Sohn gab, auf daß alle, die an ihn glauben, nicht verloren werden, sondern das ewige Leben haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Denn Gott hat seinen Sohn nicht gesandt in die Welt, daß er die Welt richte, sondern daß die Welt durch ihn selig werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Wer an ihn glaubet, der wird nicht gerichtet; wer aber nicht glaubet, der ist schon gerichtet; denn er glaubet nicht an den Namen des eingebornen Sohnes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Das ist aber das Gericht, daß das Licht in die Welt kommen ist, und die Menschen liebeten die Finsternis mehr denn das Licht; denn ihre Werke waren bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Wer Arges tut, der hasset das Licht und kommt nicht an das Licht, auf daß seine Werke nicht gestraft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Wer aber die Wahrheit tut, der kommt an das Licht, daß seine Werke offenbar werden; denn sie sind in Gott getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Danach kam Jesus und seine Jünger in das judische Land und hatte daselbst sein Wesen mit ihnen und taufete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Johannes aber taufete auch noch zu Enon, nahe bei Salim; denn es war viel Wassers daselbst. Und sie kamen dahin und ließen sich taufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Denn Johannes war noch nicht ins Gefangnis gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Da erhub sich eine Frage unter den Jüngern des Johannes samt den Juden uber die Reinigung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Und kamen zu Johannes und sprachen zu ihm: Meister, der bei dir war jenseit des Jordans, von dem du zeugtest, siehe, der taufet, und jedermann kommt zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes antwortete und sprach: Ein Mensch kann nichts nehmen, es werde ihm denn gegeben vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ihr selbst seid meine Zeugen, daß ich gesagt habe, ich sei nicht Christus, sondern vor ihm her gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Wer die Braut hat, der ist der Brautigam; der Freund aber des Brautigams stehet und horet ihm zu und freuet sich hoch uber des Brautigams Stimme. Dieselbige meine Freude ist nun erfüllet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Er muß wachsen, ich aber muß abnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Der von oben her kommt, ist uber alle. Wer von der Erde ist, der ist von der Erde und redet von der Erde; der vom Himmel kommt, der ist uber alle');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'und zeuget, was er gesehen und gehoret hat; und sein Zeugnis nimmt niemand an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Wer es aber annimmt, der versiegelt es, daß Gott wahrhaftig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Denn welchen Gott gesandt hat, der redet Gottes Wort; denn Gott gibt den Geist nicht nach dem Maß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Der Vater hat den Sohn lieb und hat ihm alles in seine Hand gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Wer an den Sohn glaubet, der hat das ewige Leben; wer dem Sohn nicht glaubet, der wird das Leben nicht sehen, sondern der Zorn Gottes bleibt uber ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Da nun der Herr inneward, daß vor die Pharisaer kommen war, wie Jesus mehr Jünger machte und taufte denn Johannes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(wiewohl Jesus selber nicht taufte, sondern seine Jünger),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'verließ er das Land Judaa und zog wieder nach Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Er mußte aber durch Samaria reisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Da kam er in eine Stadt Samarias, die heißt Sichar, nahe bei dem Dorflein, das Jakob seinem Sohne Joseph gab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Es war aber daselbst Jakobs Brunnen. Da nun Jesus müde war von der Reise, setzte er sich also auf den Brunnen; und es war urn die sechste Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Da kommt ein Weib von Samaria, Wasser zu schopfen. Jesus spricht zu ihr: Gib mir zu trinken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Denn seine Jünger waren in die Stadt gegangen, daß sie Speise kaufeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Spricht nun das samaritische Weib zu ihm: Wie bittest du von mir zu trinken, so du ein Jude bist und ich ein samaritisch Weib? (Denn die Juden haben keine Gemeinschaft mit den Samaritern.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus antwortete und sprach zu ihr: Wenn du erkennetest die Gabe Gottes, und wer der ist, derzu dir sagt: Gib mir zu trinken, du batest ihn, und er gabe dir lebendiges Wasser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Spricht zu ihm das Weib: Herr, hast du doch nichts, damit du schopfest, und der Brunnen ist tief; woher hast du denn lebendig Wasser?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Bistdu mehrdenn unser Vater Jakob, der uns diesen Brunnen gegeben hat, und er hat daraus getrunken und seine Kinder und sein Vieh?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus antwortete und sprach zu ihr: Wer von diesem Wasser trinket, den wird wieder dursten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'wer aber von dem Wasser trinken wird, das ich ihm gebe, den wird ewiglich nicht dursten, sondern das Wasser, das ich ihm geben werde, das wird in ihm ein Brunn des Wassers werden, das in das ewige Leben quillet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Spricht das Weib zu ihm: Herr, gib mir dasselbige Wasser, auf daß mich nicht durste, daß ich nicht herkommen müsse zu schopfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jesus spricht zu ihr: Gehe hin, rufe deinen Mann und komm her!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Das Weib antwortete und sprach zu ihm: Ich habe keinen Mann. Jesus spricht zu ihr: Du hast recht gesagt: Ich habe keinen Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Fünf Manner hast du gehabt, und den du nun hast, der ist nicht dein Mann. Da hast du recht gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Das Weib spricht zu ihm: Herr, ich sehe, daß du ein Prophet bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Unsere Vater haben auf diesem Berge angebetet, und ihr saget, zu Jerusalem sei die Statte, da man anbeten solle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesus spricht zu ihr: Weib, glaube mir, es kommt die Zeit, da ihr weder auf diesem Berge noch zu Jerusalem werdet den Vater anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ihr wisset nicht, was ihr anbetet; wir wissen aber was wir anbeten; denn das Heil kommt von den Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Aber es kommt die Zeit und ist schon jetzt, daß die wahrhaftigen Anbeter werden den Vater anbeten im Geist und in der Wahrheit; denn der Vater will auch haben, die ihn also anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gott ist ein Geist, und die ihn anbeten, die müssen ihn im Geist und in der Wahrheit anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Spricht das Weib zu ihm: Ich weili, daü der Messias kommt, der da Christus heilit. Wenn derselbige kommen wird, so wird er\'s uns alles verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jesus spricht zu ihr: Ich bin\'s, der mit dir redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Und fiber dem kamen seine Junger, und es nahm sie wunder, dafi er mit dem Weibe redete? Doch sprach niemand: Was fragest du? Oder: Was redest du mit ihr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Da lieli, das Weib ihren Krug stehen und ging hin in die Stadt und spricht zu den Leuten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Kommet, sehet einen Menschen, der mir gesagt hat ailes, was ich getan habe, ob er nicht Christus sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Da gingen sie aus der Stadt und kamen zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Indes aber ermahneten ihn die Junger und sprachen: Rabbi, ili!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Er aber sprach zu ihnen: Ich habe eine Speise zu essen, davon wisset ihr nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Da sprachen die Junger untereinander: Hat ihm jemand zu essen gebracht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus spricht zu ihnen: Meine Speise ist die, daß ich tue den Willen des, der mich gesandt hat, und vollende sein Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Saget ihr nicht selber: Es sind noch vier Monden, so kommt die Ernte? Siehe, ich sage euch: Hebet eure Augen auf und sehet in das Feld; denn es ist schon weili zur Ernte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'und wer da schneidet, der empfanget Lohn und sammelt Frucht zum ewigen Leben, auf daß sich miteinander freuen, der da saet und der da schneidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Denn hier ist der Spruch wahr: Dieser saet, der andere schneidet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ich habe euch gesandt zu schneiden, das ihr nicht habt gearbeitet; andere haben gearbeitet, und ihr seid in ihre Arbeit kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Es glaubten aber an ihn viel der Samariter aus derselbigen Stadt urn des Weibes Rede willen, welches da zeugete: Er hat mir gesagt alles, was ich getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Als nun die Samariter zu ihm kamen, baten sie ihn, daß er bei ihnen bliebe. Und er blieb zwei Tage da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Und viel mehr glaubeten urn seines Worts willen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'und sprachen zum Weibe: Wirglauben nun hinfort nicht urn deiner Rede willen; wir haben selber gehoret und erkannt, daß dieser ist wahrlich Christus, der Welt Heiland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Aber nach zwei Tagen zog er aus von dannen und zog nach Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Denn er selber, Jesus, zeugete, daß ein Prophet daheim nichts gilt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Da ernun nach Galilaa kam, nahmen ihn die Galilaer auf, die gesehen hatten alles, was erzu Jerusalem auf dem Fest getan hatte. Denn sie waren auch zum Fest kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Und Jesus kam abermal gen Kana in Galilaa, da er das Wasser hatte zu Wein gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Und es war ein Konigischer, des Sohn lag krank zu Kapernaum. Dieser horete, daß Jesus kam aus Judaa in Galilaa, und ging hin zu ihm und bat ihn, daß er hinab kame und hülfe seinem Sohn; denn er war todkrank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Und Jesus sprach zu ihm: Wenn ihr nicht Zeichen und Wunder sehet, so glaubet ihr nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Der Konigische sprach zu ihm: Herr, komm hinab, ehe denn mein Kind stirbt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesus spricht zu ihm: Gehe hin, dein Sohn lebet. Der Mensch glaubete dem Wort, das Jesus zu ihm sagte, und ging hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Und indem er hinabging, begegneten ihm seine Knechte, verkundigten ihm und sprachen: Dein Kind lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Da forschete er von ihnen die Stunde, in welcher es besser mit ihm worden war. Und sie sprachen zu ihm: Gestern um die siebente Stunde verließ, ihn das Fieber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Da merkte der Vater, daß es um die Stunde ware, in welcher Jesus zu ihm gesagt hatte: Dein Sohn lebet. Und erglaubete mitseinem ganzen Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Das ist nun das andere Zeichen, das Jesus tat, da eraus Judaa nach Galilaa kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Danach war ein Fest der Juden, und Jesus zog hinauf gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Es ist aber zu Jerusalem bei dem Schafhause ein Teich, der heißt auf ebraisch Bethesda und hat fünf Hallen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'in welchen lagen viel Kranke, Blinde, Lahme, Durre; die warteten, wenn sich das Wasser bewegte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Denn ein Engel fuhr herab zu seiner Zeit in den Teich und bewegte das Wasser. Welcher nun der erste, nachdem das Wasser beweget war, hineinstieg, der ward gesund, mit welcherlei Seuche er behaftet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Es war aber ein Mensch daselbst, achtunddreißig Jahre krank gelegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Da Jesus denselbigen sah liegen und vernahm, daß er so lange gelegen hatte, spricht er zu ihm: Willst du gesund werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Der Kranke antwortete ihm: Herr, ich habe keinen Menschen, wenn das Wasser sich beweget, der mich in den Teich lasse; und wenn ich komme, so steiget ein anderervormirhinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus spricht zu ihm: Stehe auf, nimm dein Bett und gehe hin!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Und alsbald ward der Mensch gesund und nahm sein Bett und ging hin. Es war aber desselbigen Tages der Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Da sprachen die Juden zu dem, der gesund war worden: Es ist heute Sabbat; es ziemt dir nicht, das Bett zu tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Er antwortete ihnen: Der mich gesund machte, der sprach zu mir: Nimm dein Bett und gehe hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Da fragten sie ihn: Wer ist der Mensch, der zu dir gesagt hat: Nimm dein Bett und gehe hin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Der aber gesund war worden, wulite nicht, wer er war; denn Jesus war gewichen, da so viel Volks an dem Ort war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Danach fand ihn Jesus im Tempel und sprach zu ihm: Siehe zu, du bist gesund worden; sundige hinfort nicht mehr, daß dir nicht etwas Argeres widerfahre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Der Mensch ging hin und verkundigte es den Juden, es sei Jesus, der ihn gesund gemacht habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Darum verfolgten die Juden Jesum und suchten ihn zu toten, daß er solches getan hatte auf den Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Jesus aber antwortete ihnen: Mein Vater wirket bisher, und ich wirke auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Darum trachteten ihm die Juden nun viel mehr nach, daß sie ihn toteten, daß er nicht allein den Sabbat brach, sondern sagte auch, Gott sei sein Vater, und machte sich selbst Gott gleich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Da antwortete Jesus und sprach zu ihnen: Wahrlich, wahrlich, ich sage euch, der Sohn kann nichts von ihm selber tun, denn was er siehet den Vater tun; denn was derselbige tut, das tut gleich auch der Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Der Vater aber hat den Sohn lieb und zeiget ihm alles, was er tut, und wird ihm noch groftere Werke zeigen, daß ihr euch verwundern werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Denn wie der Vater die Toten auferweckt und machet sie lebendig, also auch der Sohn machet lebendig, welche er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Denn der Vater richtet niemand, sondern alles Gericht hat er dem Sohn gegeben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'auf daß sie alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehret, der ehret den Vater nicht, der ihn gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Wahrlich, wahrlich, ich sage euch: Wer mein Wort horet und glaubet dem, der mich gesandt hat, der hat das ewige Leben und kommt nicht in das Gericht, sondern er ist vom Tode zum Leben hindurchgedrungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Wahrlich, wahrlich, ich sage euch: Es kommt die Stunde und ist schon jetzt, daß die Toten werden die Stimme des Sohnes Gottes horen; und die sie horen werden, die werden leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Denn wie der Vater das Leben hat in ihm selber, also hat er dem Sohn gegeben, das Leben zu haben in ihm selber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Und hat ihm Macht gegeben, auch das Gericht zu halten, darum daß er des Menschen Sohn ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Verwundert euch des nicht; denn es kommt die Stunde, in welcher alle, die in den Grabern sind, werden seine Stimme horen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'und werden hervorgehen, die da Gutes getan haben, zur Auferstehung des Lebens, die aber Ubels getan haben, zur Auferstehung des Gerichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ich kann nichts von mir selber tun. Wie ich hore, so richte ich, und mein Gericht ist recht; denn ich suche nicht meinen Willen, sondern des Vaters Willen, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'So ich von mir selbst zeuge, so ist mein Zeugnis nicht wahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ein anderer ist\'s, der von mir zeuget; und ich weiß, daß das Zeugnis wahr ist, das er von mir zeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ihr schicktet zu Johannes, und er zeugete von der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ich aber nehme nicht Zeugnis von Menschen, sondern solches sage ich, auf daß ihr selig werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Er war ein brennend und scheinend Licht; ihr aber wolltet eine kleine Weile frohlich sein von seinem Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ich aber habe ein grower Zeugnis denn des Johannes Zeugnis; denn die Werke, die mir der Vater gegeben hat, daß ich sie vollende, dieselbigen Werke, die ich tue, zeugen von mir, daß mich der Vater gesandt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Und der Vater, der mich gesandt hat, derselbige hat von mir gezeuget. Ihr habt nie weder seine Stimme gehoret noch seine Gestalt gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Und sein Wort habt ihr nicht in euch wohnend; denn ihr glaubet dem nicht, den er gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Suchet in der Schrift; denn ihr meinet, ihr habt das ewige Leben darinnen; und sie ist\'s, die von mir zeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Und ihrwollt nicht zu mir kommen, daß ihr das Leben haben mochtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ich nehme nicht Ehre von Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Aber ich kenne euch, daß ihr nicht Gottes Liebe in euch habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ich bin kommen in meines Vaters Namen, und ihr nehmet mich nicht an. So ein anderer wird in seinem eigenen Namen kommen, den werdet ihr annehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Wie konnet ihr glauben, die ihr Ehre voneinander nehmet? Und die Ehre, die von Gott ailein ist, suchet ihr nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ihr sollt nicht meinen, daß ich euch vor dem Vater verklagen werde. Es ist einer, der euch verklaget, der Mose, auf welchen ihr hoffet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Wenn ihr Mose glaubtet, so glaubtet ihr auch mir; denn er hat von mir geschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'So ihr aber seinen Schriften nicht glaubet, wie werdet ihr meinen Worten glauben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Danach fuhr Jesus weg uber das Meer an der Stadt Tiberias in Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Und es zog ihm viel Volks nach, darum daß sie die Zeichen sahen, die er an den Kranken tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jesus aber ging hinauf auf einen Berg und setzte sich daselbst mit seinen Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Es war aber nahe Ostern, der Juden Fest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Da hub Jesus seine Augen auf und siehet, daß viel Volks zu ihm kommt, und spricht zu Philippus: Wo kaufen wir Brot, daß diese essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '(Das sagte er aber, ihn zu versuchen; denn er wuftte wohl, was er tun wollte.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippus antwortete ihm: Fur zweihundert Pfennig Brot ist nicht genug unter sie, daß ein jeglicher unter ihnen ein wenig nehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Spricht zu ihm einer seiner Junger, Andreas, der Bruder des Simon Petrus:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Es ist ein Knabe hier, der hat fünf Gerstenbrote und zwei Fische; aber was ist das unter so viele?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jesus aber sprach: Schaffet, daß sich das Volk lagere! Es war aber viel Gras an dem Ort. Da lagerten sich bei funftausend Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jesus aber nahm die Brote, dankete und gab sie den Jungern, die Junger aber denen, die sich gelagert hatten; desselbigengleichen auch von den Fischen, wieviel er wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Da sie aber satt waren, sprach er zu seinen Jungern: Sammelt die ubrigen Brocken, daß nichts umkomme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Da sammelten sie und fülleten zwolf Korbe mit Brocken von den fünf Gerstenbroten, die uberblieben denen, die gespeiset worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Da nun die Menschen das Zeichen sahen, das Jesus tat, sprachen sie: Das ist wahrlich der Prophet, der in die Welt kommen soil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Da Jesus nun merkete, daß sie kommen würden und ihn haschen, daß sie ihn zum Konige machten, entwich er abermal auf den Berg, er selbst alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Am Abend aber gingen die Junger hinab an das Meer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'und traten in das Schiff und kamen uber das Meer gen Kapernaum. Und es war schon finster worden, und Jesus war nicht zu ihnen kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Und das Meererhub sich von einem groften Winde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Da sie nun gerudert hatten bei fünfundzwanzig Oder dreiftig Feld Wegs, sahen sie Jesum auf dem Meer dahergehen und nahe zum Schiff kommen; und sie furchteten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Er aber sprach zu ihnen: Ich bin\'s; furchtet euch nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Da wollten sie ihn in das Schiff nehmen; und alsbald war das Schiff am Lande, da sie hinfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Des andern Tages sah das Volk, das diesseits des Meeres stund, daß kein ander Schiff daselbst war denn das einige, darein seine Junger getreten waren, und daß Jesus nicht mit seinen Jungern in das Schiff getreten war, sondern ailein seine Junger waren weggefahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Es kamen aber andere Schiffe von Tiberias nahe zu der Statte, da sie das Brot gegessen hatten durch des Herm Danksagung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Da nun das Volk sah, daß Jesus nicht da war noch seine Junger, traten sie auch in die Schiffe und kamen gen Kapernaum und suchten Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Und da sie ihn fanden jenseit des Meeres, sprachen sie zu ihm: Rabbi, wann bist du herkommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus antwortete ihnen und sprach: Wahrlich, wahrlich, ich sage euch, ihr suchet mich nicht darum, daß ihr Zeichen gesehen habt, sondern daß ihr von dem Brot gegessen habt und seid satt worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Wirket Speise, nicht die verganglich ist, sondern die da bleibet in das ewige Leben, welche euch des Menschen Sohn geben wird; denn denselbigen hat Gott der Vater versiegelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Da sprachen sie zu ihm: Was sollen wir tun, daß wir Gottes Werke wirken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesus antwortete und sprach zu ihnen: Das ist Gottes Werk, daß ihr an den glaubet, den er gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Da sprachen sie zu ihm: Was tust du fur ein Zeichen, auf dafi wir sehen und glauben dir? Was wirkest du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Unsere Vater haben Manna gegessen in der Wüste, wie geschrieben stehet: Er gab ihnen Brot vom Himmel zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Da sprach Jesus zu ihnen: Wahrlich, wahrlich, ich sage euch: Mose hat euch nicht Brot vom Himmel gegeben, sondern mein Vater gibt euch das rechte Brot vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Denn dies ist das Brot Gottes, das vom Himmel kommt und gibt der Welt das Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Da sprachen sie zu ihm: Herr, gib uns allewege solch Brot!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus aber sprach zu ihnen: Ich bin das Brot des Lebens. Wer zu mir kommt, den wird nicht hungern; und wer an mich glaubet, den wird nimmermehr dursten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Aber ich hab\'s euch gesagt, dafi ihr mich gesehen habt und glaubet doch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alles, was mir mein Vater gibt, das kommt zu mir; und wer zu mir kommt, den werde ich nicht hinausstolten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Denn ich bin vom Himmel kommen, nicht daß ich meinen Willen tue, sondern des, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Das ist aber der Wille des Vaters, der mich gesandt hat, dafi ich nichts verliere von allem, was er mir gegeben hat, sondern daß ich\'s auferwecke am Jungsten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Das ist aber der Wille des, der mich gesandt hat, daß, wer den Sohn siehet und glaubet an ihn, habe das ewige Leben; und ich werde ihn auferwecken am Jungsten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Da murreten die Juden daruber, daß er sagte: Ich bin das Brot, das vom Himmel kommen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'und sprachen: Ist dieser nicht Jesus, Josephs Sohn, des Vater und Mutter wir kennen? Wie spricht erdenn: Ich bin vom Himmel kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jesus antwortete und sprach zu ihnen: Murret nicht untereinander!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Es kann niemand zu mir kommen, es sei denn, daß ihn ziehe der Vater, der mich gesandt hat; und ich werde ihn auferwecken am Jungsten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Es stehet geschrieben in den Propheten: Sie werden alle von Gott gelehret sein. Wer es nun horet vom Vater und lernet es, der kommt zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nicht daß jemand den Vater habe gesehen, außer dem, der vom Vater ist, der hat den Vater gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubet, der hat das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Eure Vater haben Manna gegessen in der Wüste und sind gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Dies ist das Brot, das vom Himmel kommt, auf daß, wer davon isset, nicht sterbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ich bin das lebendige Brot, vom Himmel kommen. Wer von diesem Brot essen wird, der wird leben in Ewigkeit. Und das Brot, das ich geben werde, ist mein Fleisch, welches ich geben werde fur das Leben der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Da zanketen die Juden untereinander und sprachen: Wie kann dieser uns sein Fleisch zu essen geben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesus sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Werdet ihr nicht essen das Fleisch des Menschensohnes und trinken sein Blut, so habt ihr kein Leben in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Wer mein Fleisch isset und trinket mein Blut, der hat das ewige Leben, und ich werde ihn am Jungsten Tage auferwecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Denn mein Fleisch ist die rechte Speise, und mein Blut ist der rechte Trank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Wer mein Fleisch isset und trinket mein Blut, der bleibt in mir und ich in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Wie mich gesandt hat der lebendige Vater, und ich lebe urn des Vaters willen, also, wer mich isset, derselbige wird auch leben urn meinetwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Dies ist das Brot, das vom Himmel kommen ist, nicht wie eure Vater haben Manna gegessen und sind gestorben. Wer dies Brot isset, der wird leben in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Solches sagte er in der Schule, da er lehrete zu Kapernaum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Viele nun seiner Jünger, die das horeten, sprachen: Das ist eine harte Rede, wer kann sie hdren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Da Jesus aber bei sich selbst merkete, daß seine Jünger daruber murreten, sprach er zu ihnen: Argert euch das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Wie, wenn ihr denn sehen werdet des Menschen Sohn auffahren dahin; da er zuvor war?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Der Geist ist\'s, der da lebendig macht; das Fleisch ist kein nütze. Die Worte, die ich rede, die sind Geist und sind Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Aber es sind etliche unter euch, die glauben nicht. Denn Jesus wulite von Anfang wohl, welche nicht glaubend waren, und welcher ihn verraten würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Und er sprach: Darum habe ich euch gesagt: Niemand kann zu mir kommen, es sei ihm denn von meinem Vater gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Von dem an gingen seiner Jünger viel hinter sich und wandelten hinfort nicht mehr mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Da sprach Jesus zu den Zwdlfen: Wollt ihr auch weggehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Da antwortete ihm Simon Petrus: Herr, wohin sollen wir gehen? Du hast Worte des ewigen Lebens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'und wir haben geglaubet und erkannt, dafi du bist Christus, der Sohn des lebendigen Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus antwortete ihm: Hab\' ich nicht euch Zwolfe erwahlet? und euer einer ist ein Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Er redete aber von dem Judas, Simons Sohn, Ischariot; derselbige verriet ihn hernach und war der Zwdlfen einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Danach zog Jesus umher in Galilaa denn er wollte nicht in Judaa umherziehen, darum daß ihm die Juden nach dem Leben stelleten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Es war aber nahe der Juden Fest, der Laubrust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Da sprachen seine Bruder zu ihm: Mache dich auf von dannen und gehe nach Judaa, auf daß auch deine Junger sehen die Werke, die du tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Niemand tut etwas im Verborgenen und will doch frei offenbar sein. Tust du solches, so offenbare dich vor der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Denn auch seine Bruder glaubten nicht an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Da spricht Jesus zu ihnen: Meine Zeit ist noch nicht hier; eure Zeit aber ist allewege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Die Welt kann euch nicht hassen; mich aber hasset sie; denn ich zeuge von ihr, daß ihre Werke bose sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Gehet ihr hinauf auf dieses Fest. Ich will noch nicht hinaufgehen auf dieses Fest; denn meine Zeit ist noch nicht erfullet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Da er aber das zu ihnen gesagt, blieb er in Galilaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Als aber seine Bruder waren hinaufgegangen, da ging erauch hinauf zu dem Fest, nicht offenbarlich, sondern gleich heimlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Da suchten ihn die Juden am Fest und sprachen: Wo ist der?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Und eswarein graft Gemurmel von ihm unter dem Volk. Etliche sprachen: Er ist, fromm. Die andern aber sprachen: Nein, sondern er verfuhret das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Niemand aber redete frei von ihm urn der Furcht willen vor den Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Aber mitten im Fest ging Jesus hinauf in den Tempel und lehrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Und die Juden verwunderten sich und sprachen: Wie kann dieser die Schrift, so er sie doch nicht gelernet hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesus antwortete ihnen und sprach: Meine Lehre ist nicht mein, sondern des, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'So jemand will des Willen tun, derwird innewerden, ob diese Lehre von Gott sei, Oder ob ich von mir selbst rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Wer von ihm selbst redet, der sucht seine eigene Ehre; wer aber suchet die Ehre des, der ihn gesandt hat, der ist wahrhaftig, und ist keine Ungerechtigkeit an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hat euch nicht Mose das Gesetz gegeben? Und niemand unter euch tut das Gesetz. Warum suchet ihr mich zu toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Das Volk antwortete und sprach: Du hast den Teufel; wer suchet dich zu toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus antwortete und sprach: Ein einiges Werk habe ich getan, und es wundert euch alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Mose hat euch darum gegeben die Beschneidung, nicht daß sie von Mose kommt, sondern von den Vatern; noch beschneidet ihr den Menschen am Sabbat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'So ein Mensch die Beschneidung annimmt am Sabbat, auf daß nicht das Gesetz Mose\'s gebrochen werde, zürnet ihr denn über mich, daß ich den ganzen Menschen habe am Sabbat gesund gemacht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Richtet nicht nach dem Ansehen sondern richtet ein recht Gericht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Da sprachen etliche von Jerusalem: Ist das nicht der, den sie suchten zu toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Und siehe zu, er redet frei, und sie sagen ihm nichts. Erkennen unsere Obersten nun gewift, daß er gewift Christus sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Doch wir wissen, von wannen dieser ist; wenn aber Christus kommen wird, so wird niemand wissen, von wannen er ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Da rief Jesus im Tempel, lehrete und sprach: Ja, ihr kennet mich und wisset, von wannen ich bin; und von mir selbst bin ich nicht kommen, sondern es ist ein Wahrhaftiger, der mich gesandt hat, welchen ihr nicht kennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ich kenne ihn aber; denn ich bin von ihm, und er hat mich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Da suchten sie ihn zu greifen. Aber niemand legte die Hand an ihn; denn seine Stunde war noch nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Aber viele vom Volk glaubten an ihn und sprachen: Wenn Christus kommen wird; wird erauch mehr Zeichen tun, denn dieser tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Und es kam vor die Pharisaer, daß das Volk solches von ihm murmelte. Da sandten die Pharisaer und Hohenpriester Knechte aus, daß sie ihn griffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Da sprach Jesus zu ihnen: Ich bin noch eine kleine Zeit bei euch, und dann gehe ich hin zu dem, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ihr werdet mich suchen und nicht finden; und da ich bin, konnet ihr nicht hinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Da sprachen die Juden untereinander: Wo will dieser hingehen, daß wir ihn nicht finden sollen? Will er unter die Griechen gehen, die hin und her zerstreuet liegen, und die Griechen lehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Was ist das fur eine Rede, daß er saget: Ihr werdet mich suchen und nicht finden, und: Wo ich bin, da konnet ihr nicht hinkommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Aber am letzten Tage des Festes, der am herrlichsten war, trat Jesus auf, rief und sprach: Wen da durstet, der komme zu mir und trinke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Wer an mich glaubet, wie die Schrift sagt, von des Leibe werden Strome des lebendigen Wassers flieften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Das sagte er aber von dem Geist, welchen empfangen sollten, die an ihn glaubten; denn der Heilige Geist war noch nicht da, denn Jesus war noch nicht verklaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Viele nun vom Volk, die diese Rede horeten, sprachen: Dieser ist ein rechter Prophet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Die andern sprachen: Er ist Christus. Etliche aber sprachen: Soli Christus aus Galilaa kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Spricht nicht die Schrift, von dem Samen Davids und aus dem Flecken Bethlehem, da David war, solle Christus kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Also ward eine Zwietracht unter dem Volk uber ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Es wollten aber etliche ihn greifen; aber niemand legte die Hand an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Die Knechte kamen zu den Hohenpriestern und Pharisaern. Und sie sprachen zu ihnen: Warum habt ihr ihn nicht gebracht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Die Knechte antworteten: Es hat nie kein Mensch also geredet wie dieser Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Da antworteten ihnen die Pharisaer: Seid ihr auch verfuhret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Glaubet auch irgendein Oberster Oder Pharisaer an ihn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Sondern das Volk, das nichts vom Gesetz weiß, ist verflucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Sprichtzu ihnen Nikodemus, der bei der Nacht zu ihm kam, welcher einer unter ihnen war:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Richtet unser Gesetz auch einen Menschen, ehe man ihn verhoret und erkennet, was er tut?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Sie antworteten und sprachen zu ihm: Bist du auch ein Galilaer? Forsche und siehe, aus Galilaa stehet kein Prophet auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Und ein jeglicher ging also heim.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jesus aber ging an den Olberg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Und fruhmorgens kam erwieder in den Tempel, und alles Volk kam zu ihm. Und er setzte sich und lehrete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Aber die Schriftgelehrten und Pharisaer brachten ein Weib zu ihm, im Ehebruch begriffen, und stelleten sie in die Mitte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'und sprachen zu ihm: Meister, dies Weib ist begriffen auf frischer Tat im Ehebruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Mose aber hat uns im Gesetz geboten, solche zu steinigen; was sagst du?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Das sprachen sie aber, ihn zu versuchen, auf dall sie eine Sache wider ihn flatten. Aber Jesus buckete sich nieder und schrieb mit dem Finger auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Als sie nun anhielten, ihn zu fragen, richtete er sich auf und sprach zu ihnen: Wer unter euch ohne Sünde ist, derwerfe den ersten Stein auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Und buckete sich wieder nieder und schrieb auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Da sie aber das horeten, gingen sie hinaus, von ihrem Gewissen uberzeugt, einer nach dem andern, von den Altesten an bis zu den Geringsten. Und Jesus ward gelassen allein und das Weib in der Mitte stehend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Jesus aber richtete sich auf; und da er niemand sah denn das Weib, sprach er zu ihr: Weib, wo sind sie, deine Verklager? Hat dich niemand verdammt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Sie aber sprach: Herr, niemand. Jesus aber sprach: So verdamme ich dich auch nicht; gehe hin und sundige hinfort nicht mehr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Da redete Jesus abermal zu ihnen und sprach: Ich bin das Licht der Welt; wer mir nachfolget, der wird nicht wandeln in Finsternis, sondern wird das Licht des Lebens haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Da sprachen die Pharisaer zu ihm: Du zeugest von dir selbst; dein Zeugnis ist nicht wahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus antwortete und sprach zu ihnen: So ich von mir selbst zeugen wurde, so ist mein Zeugnis wahr; denn ich weili, von wannen ich kommen bin und wo ich hingehe; ihr aber wisset nicht, von wannen ich komme und wo ich hingehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ihr richtet nach dem Fleisch; ich richte niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'So ich aber richte, so ist mein Gericht recht; denn ich bin nicht allein, sondern ich und der Vater, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Auch stehet in eurem Gesetze geschrieben, daß zweier Menschen Zeugnis wahr sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ich bin\'s, der ich von mir selbst zeuge; und der Vater, der mich gesandt hat, zeuget auch von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Da sprachen sie zu ihm: Wo ist dein Vater? Jesus antwortete: Ihr kennet weder mich noch meinen Vater; wenn ihr mich kennetet, so kennetet ihr auch meinen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Diese Worte redete Jesus an dem Gotteskasten, da er lehrete im Tempel; und niemand griff ihn; denn seine Stunde war noch nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Da sprach Jesus abermal zu ihnen: Ich gehe hinweg, und ihrwerdet mich suchen und in eurer Sünde sterben; wo ich hingehe, da konnet ihr nicht hinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Da sprachen die Juden: Will er sich denn selbst toten, daß er spricht: Wo ich hingehe, da konnet ihr nicht hinkommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Und er sprach zu ihnen: Ihr seid von unten her, ich bin von oben herab; ihr seid von dieser Welt, ich bin nicht von dieser Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'So hab\' ich euch gesagt, daß ihr sterben werdet in euren Sunden; denn so ihr nicht glaubet, daß ich es sei, so werdet ihr sterben in euren Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Da sprachen sie zu ihm: Wer bist du denn? Und Jesus sprach zu ihnen: Erstlich der, der ich mit euch rede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Ich habe viel von euch zu reden und zu richten; aber der mich gesandt hat, ist wahrhaftig, und was ich von ihm gehoret habe, das rede ich vor der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Sie vernahmen aber nicht, daß er ihnen von dem Vater sagete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Da sprach Jesus zu ihnen: Wenn ihr des Menschen Sohn erhohen werdet, dann werdet ihr erkennen, daß ich es sei und nichts von nur selber tue, sondern wie mich mein Vater gelehret hat, so rede ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Und der mich gesandt hat, ist mit mir. Der Vater lal?t mich nicht allein; denn ich tue allezeit, was ihm gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Da er solches redete, glaubten viele an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Da sprach nun Jesus zu den Juden, die an ihn glaubten: So ihr bleiben werdet an meiner Rede, so seid ihr meine rechten Junger');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'und werdet die Wahrheit erkennen; und die Wahrheit wird euch freimachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Da antworteten sie ihm: Wir sind Abrahams Samen, sind nie keinmal jemands Knechte gewesen; wie sprichst du denn: Ihr sollt frei werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesus antwortete ihnen und sprach: Wahrlich, wahrlich, ich sage euch, wer Sunde tut der ist der Sünde Knecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Der Knecht aber bleibet nicht ewiglich im Hause; der Sohn bleibet ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'So euch nun der Sohn freimacht, so seid ihr recht frei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Ich weili wohl, daß ihr Abrahams Samen seid; aber ihr suchet mich zu toten; denn meine Rede fanget nicht unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ich rede, was ich von meinem Vater gesehen habe; so tut ihr, was ihr von eurem Vater gesehen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Sie antworteten und sprachen zu ihm: Abraham ist unser Vater. Spricht Jesus zu ihnen: Wenn ihr Abrahams Kinder waret, so tatet ihr Abrahams Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Nun aber suchet ihr mich zu toten, einen solchen Menschen, der ich euch die Wahrheit gesagt habe, die ich von Gott gehoret habe; das hat Abraham nicht getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ihr tut eures Vaters Werke. Da sprachen sie zu ihm: Wir sind nicht unehelich geboren; wir haben einen Vater, Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus sprach zu ihnen: Ware Gott euer Vater, so liebetet ihr mich; denn ich bin ausgegangen und komme von Gott; denn ich bin nicht von mir selber kommen, sondern er hat mich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Warum kennet ihr denn meine Sprache nicht? denn ihr konnt ja mein Wort nicht horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ihr seid von dem Vater, dem Teufel, und nach eures Vaters Lust wollt ihr tun. Derselbige ist ein Morder von Anfang und ist nicht bestanden in der Wahrheit; denn die Wahrheit ist nicht in ihm. Wenn er die Lugen redet, so redet er von seinem Eigenen; denn er ist ein Lugner und ein Vater derselbigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Ich aber, weil ich die Wahrheit sage, so glaubet ihr mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Welcher unter euch kann mich einer Sünde zeihen? So ich euch aber die Wahrheit sage, warum glaubet ihr mir nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Wer von Gott ist, der horet Gottes Wort. Darum horet ihr nicht; denn ihr seid nicht von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Da antworteten die Juden und sprachen zu ihm: Sagen wir nicht recht, daß du ein Samariter bist und hast den Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus antwortete: Ich habe keinen Teufel, sondern ich ehre meinen Vater, und ihr unehret mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ich suche nicht meine Ehre; es ist aber einer, der sie suchet und richtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Wahrlich, wahrlich, ich sage euch: So jemand mein Wort wird halten, der wird den Tod nicht sehen ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Da sprachen die Juden zu ihm: Nun erkennen wir, daß du den Teufel hast. Abraham ist gestorben und die Propheten, und du sprichst: So jemand mein Wort halt, der wird den Tod nicht schmecken ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Bist du mehr denn unser Vater Abraham, welcher gestorben ist? Und die Propheten sind gestorben. Was machst du aus dir selbst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus antwortete: So ich mich selber ehre, so ist meine Ehre nichts. Es ist aber mein Vater, der mich ehret, von welchem ihr sprecht, er sei euer Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'und kennet ihn nicht. Ich aber kenne ihn. Und so ich wurde sagen, ich kenne ihn nicht, so wurde ich ein Lugner, gleichwie ihr seid. Aber ich kenne ihn und halte sein Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, euer Vater, ward froh, daß er meinen Tag sehen sollte; und ersah ihn und freuete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Da sprachen die Juden zu ihm: Du bist noch nicht fünfzig Jahre alt und hast Abraham gesehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus sprach zu ihnen: Wahrlich, wahrlich, ich sage euch: Ehe denn Abraham ward, bin ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Da huben sie Steine auf, daß sie auf ihn wurfen. Aber Jesus verbarg sich und ging zum Tempei hinaus, mitten durch sie hinstreichend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Und Jesus ging voruber und sah einen, der blind geboren war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Und seine Junger fragten ihn und sprachen: Meister, wer hat gesundiget, dieser Oder seine Eltern, daß er ist blind geboren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus antwortete: Es hat weder dieser gesundiget noch seine Eltern, sondern daß die Werke Gottes offenbar wurden an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Ich muü Wirken die Werke des, der mich gesandt hat, solange es Tag ist; es kommt die Nacht, da niemand wirken kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Dieweil ich bin in der Welt, bin ich das Licht der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Da er solches gesagt, sputzete er auf die Erde und machte einen Kot aus dem Speichel und schmierete den Kot auf des Blinden Augen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'und sprach zu ihm: Gehe hin zu dem Teich Siloah (das ist verdolmetschet: gesandt) und wasche dich. Da ging er hin und wusch sich und kam sehend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Die Nachbarn, und die ihn zuvor gesehen hatten, daß er ein Bettler war, sprachen: Ist dieser nicht, der da sali und bettelte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Etliche sprachen: Er ist\'s; etliche aber: Er ist ihm ahnlich. Er selbst aber sprach: Ich bin\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Da sprachen sie zu ihm: Wie sind deine Augen aufgetan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Er antwortete und sprach: Der Mensch, der Jesus heiliet, machte einen Kot und schmierete meine Augen und sprach: Gehe hin zu dem Teich Siloah und wasche dich. Ich ging hin und wusch mich und ward sehend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Da sprachen sie zu ihm: Wo ist derselbige? Er sprach: Ich weiß nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Da führeten sie ihn zu den Pharisaern, der weiland blind war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, '(Es war aber Sabbat, da Jesus den Kot machte und seine Augen offnete.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Da fragten sie ihn abermal, auch die Pharisaer, wie erware sehend worden. Er aber sprach zu ihnen: Kot legte er mir auf die Augen, und ich wusch mich und bin nun sehend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Da sprachen etliche der Pharisaer: Der Mensch ist nicht von Gott, dieweil er den Sabbat nicht halt. Die andern aber sprachen: Wie kann ein sundiger Mensch solche Zeichen tun? Und es ward eine Zwietracht unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Sie sprachen wieder zu dem Blinden: Was sagest du von ihm, daß er hat deine Augen aufgetan? Er aber sprach: Er ist ein Prophet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Die Juden glaubten nicht von ihm, daß er blind gewesen und sehend worden ware, bis daß sie riefen die Eltern des, der sehend war worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'fragten sie und sprachen: Ist das euer Sohn, von welchem ihr saget, er sei blind geboren? Wie ist er denn nun sehend?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Seine Eltern antworteten ihnen und sprachen: Wir wissen, daß dieser unser Sohn ist, und daü er blind geboren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Wie er aber nun sehend ist, wissen wir nicht; Oder wer ihm hat seine Augen aufgetan, wissen wir auch nicht. Er ist alt genug, fraget ihn; lasset ihn selbst fürsich reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Solches sagten seine Eltern; denn sie furchteten sich vor den Juden. Denn die Juden hatten sich schon vereiniget, so jemand ihn fur Christum bekennete, daß derselbe in Bann getan würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Darum sprachen seine Eltern: Er ist alt genug, fraget ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Da riefen sie zum andernmal den Menschen, der blind gewesen war, und sprachen zu ihm: Gib Gott die Ehre! Wir wissen, daü dieser Mensch ein Sunder ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Er antwortete und sprach: Ist er ein Sunder, das weift ich nicht; eines weift ich wohl, daß ich blind war und bin nun sehend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Da sprachen sie wieder zu ihm: Was tat er dir? Wie tat er deine Augen auf?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Er antwortete ihnen: Ich hab\'s euch jetzt gesagt; habt ihr\'s nicht gehoret? Was wollt ihr\'s abermal horen? Wollt ihr auch seine Junger werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Da fluchten sie ihm und sprachen: Du bist sein Junger; wir aber sind Mose\'s Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Wir wissen, daß Gott mit Mose geredet hat; diesen aber wissen wir nicht, von wannen er ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Der Mensch antwortete und sprach zu ihnen: Das ist ein wunderlich Ding, daß ihr nicht wisset, von wannen er sei; und er hat meine Augen aufgetan!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Wir wissen aber, daß Gott die Sunder nicht horet, sondern so jemand gottesfurchtig ist und tut seinen Willen, den horet er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Von der Welt an ist’s nicht erhoret, daü jemand einem gebornen Blinden die Augen aufgetan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Ware dieser nicht von Gott, er konnte nichts tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Sie antworteten und sprachen zu ihm: Du bist ganz in Sunden geboren und lehrest uns? Und stieften ihn hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Es kam vor Jesum, daß sie ihn ausgestoften hatten. Und da er ihn fand, sprach erzu ihm: Glaubest du an den Sohn Gottes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Er antwortete und sprach: Herr, welcher ist’s, auf daß ich an ihn glaube?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesus sprach zu ihm: Du hast ihn gesehen, und der mit dir redet, der ist\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Er aber sprach: Herr, ich glaube; und betete ihn an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Und Jesus sprach: Ich bin zum Gerichte auf diese Welt kommen, auf daß, die da nicht sehen, sehend werden, und die da sehen, blind werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Und solches horeten etliche der Pharisaer, die bei ihm waren, und sprachen zu ihm: Sind wir denn auch blind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesus sprach zu ihnen: Waret ihr blind, so hattet ihr keine Sünde; nun ihr aber sprechet: Wir sind sehend, bleibet eure Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Wahrlich, wahrlich, ich sage euch: Wer nicht zur Tur hineingehet in den Schafstall, sondern steiget anderswo hinein, der ist ein Dieb und ein Morder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Der aber zur Tur hineingehet, der ist ein Hirte der Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Demselbigen tut der Turhuter auf, und die Schafe horen seine Stimme; und er ruft seine Schafe mit Namen und führet sie aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Und wenn er seine Schafe hat ausgelassen, gehet er vor ihnen hin, und die Schafe folgen ihm nach; denn sie kennen seine Stimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Einem Fremden aber folgen sie nicht nach, sondern fliehen von ihm; denn sie kennen der Fremden Stimme nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Diesen Spruch sagte Jesus zu ihnen; sie vernahmen aber nicht, was es war, das er zu ihnen sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Da sprach Jesus wieder zu ihnen: Wahrlich, wahrlich, ich sage euch: Ich bin die Tur zu, den Schafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle, die vor mir kommen sind, die sind Diebe und Morder gewesen, aber die Schafe haben ihnen nicht gehorchet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ich bin die Tur; so jemand durch mich eingehet, der wird selig werden und wird ein und aus gehen und Weide finden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Ein Dieb kommt nicht, denn daß erstehle, wurge und umbringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ich bin kommen, daß sie das Leben und voile Genüge haben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Ich bin ein guter Hirte; ein guter Hirte lasset sein Leben fur die Schafe. Ein Mietling aber, der nicht Hirte ist, des die Schafe nicht eigen sind, siehet den Wolf kommen und verlasset die Schafe und flieht; und der Wolf erhaschet und zerstreuet die Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Der Mietling aber flieht; denn er ist ein Mietling und achtet der Schafe nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ich bin ein guter Hirte und erkenne die Meinen und bin bekannt den Meinen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'wie mich mein Vater kennet, und ich kenne den Vater. Und ich lasse mein Leben fur die Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Und ich habe andere Schafe, die sind nicht aus diesem Stalle. Und dieselben muft ich herfuhren, und sie werden meine Stimme horen, und wird eine Herde und ein Hirte werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Darum liebet mich mein Vater, daß ich mein Leben lasse, auf dafi ich\'s wieder nehme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Niemand nimmt es von mir, sondern ich lasse es von mirselber. Ich habe Macht es zu lassen und habe Macht es wiederzunehmen. Solch Gebot habe ich empfangen von meinem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Da ward aber eine Zwietracht unter den Juden uber diesen Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Viele unter ihnen sprachen: Er hat den Teufel und ist unsinnig; was horet ihr ihm zu?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Die andern sprachen: Das sind nicht Worte eines Besessenen; kann der Teufel auch der Blinden Augen auftun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Es war aber Kirchweih zu Jerusalem und war Winter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Und Jesus wandelte im Tempel, in der Halle Salomos.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Da umringten ihn die Juden und sprachen zu ihm: Wie lange haltst du unsere Seelen auf? Bist du Christus, so sage es uns frei heraus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus antwortete ihnen: Ich habe es euch gesagt, und ihr glaubet nicht. Die Werke, die ich tue in meines Vaters Namen, die zeugen von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Aber ihr glaubet nicht; denn ihr seid von meinen Schafen nicht, wie ich euch gesagt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Denn meine Schafe horen meine Stimme, und ich kenne sie, und sie folgen mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Und ich gebe ihnen das ewige Leben; und sie werden nimmermehr umkommen, und niemand wird sie mir aus meiner Hand reifien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Der Vater, der sie mirgegeben hat, ist grower denn alles; und niemand kann sie aus meines Vaters Hand reüien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ich und der Vater sind eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Da huben die Juden abermal Steine auf, daß sie ihn steinigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesus antwortete ihnen: Viel gute Werke habe ich euch erzeiget von meinem Vater; urn welches Werk unter denselbigen steiniget ihr mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Die Juden antworteten ihm und sprachen: Urn des guten Werks willen steinigen wir dich nicht, sondern urn der Gotteslasterung willen, und daß du ein Mensch bist und machest dich selbst zu einem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus antwortete ihnen: Stehet nicht geschrieben in eurem Gesetz: Ich habe gesagt, ihr seid Gotter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'So er die Gotter nennet, zu welchen das Wort Gottes geschah (und die Schrift kann doch nicht gebrochen werden),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'sprecht ihr denn zu dem, den der Vater geheiliget und in die Welt gesandt hat: Du lasterst Gott, darum daß ich sage, ich bin Gottes Sohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Tue ich nicht die Werke meines Vaters, so glaubet mir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Tue ich sie aber, glaubet doch den Werken, wollt ihr mir nicht glauben, auf daß ihr erkennet und glaubet, daß der Vater in mir ist und ich in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Sie suchten abermal, ihn zu greifen; aber er entging ihnen aus ihren Handen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'und zog hin wieder jenseit des Jordans an den Ort, da Johannes vorhin getauft hatte, und blieb ailda.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Und viele kamen zu ihm und sprachen: Johannes tat kein Zeichen; aber alles, was Johannes von diesem gesagt hat, das ist wahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Und glaubten ailda viele an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Es lag aber einer krank mit Namen Lazarus von Bethanien, in dem Flecken Marias und ihrer Schwester Martha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(Maria aber war, die den Herrn gesalbet hatte mit Salben und seine Füfte getrocknet mit ihrem Haar; derselbigen Bruder Lazarus war krank.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Da sandten seine Schwestern zu ihm und lieften ihm sagen: Herr, siehe, den du liebhast, der liegt krank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Da Jesus das horete, sprach er: Die Krankheit ist nicht zum Tode, sondern zur Ehre Gottes, daß der Sohn Gottes dadurch geehret werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus aber hatte Martha lieb und ihre Schwester und Lazarus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Als er nun horete, daß er krank war, blieb er zwei Tage an dem Ort, da er war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Danach spricht er zu seinen Jungern: Lasset uns wieder nach Judaa ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Seine Jünger sprachen zu ihm: Meister, jenesmal wollten die Juden dich steinigen, und du willst wieder dahin ziehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus antwortete: Sind nicht des Tages zwolf Stunden? Wer des Tages wandelt, der stoftet sich nicht, denn er siehet das Licht dieser Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Wer aber des Nachts wandelt, der stoftet sich, denn es ist kein Licht in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Solches sagte er, und danach spricht er zu ihnen: Lazarus, unser Freund, schlaft; aber ich gehe hin, daß ich ihn aufwecke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Da sprachen seine Junger: Herr, schlaft er, so wird\'s besser mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus aber sagte von seinem Tode; sie meineten aber, er redete vom leiblichen Schlaf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Da sagte es ihnen Jesus frei heraus: Lazarus ist gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Und ich bin froh um euretwillen, daß ich nicht dagewesen bin, auf daß ihr glaubet. Aber lasset uns zu ihm ziehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Da sprach Thomas, derda genannt ist Zwilling, zu den Jungern: Lasset uns mit ziehen, daß wir mit ihm sterben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Da kam Jesus und fand ihn, daß erschon vier Tage im Grabe gelegen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '(Bethanien aber war nahe bei Jerusalem, bei funfzehn Feldweges.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Und viel Juden waren, zu Martha und Maria kommen, sie zu trosten über ihren Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Als Martha nun horete, daß Jesus kommt, gehet sie ihm entgegen; Maria aber blieb daheim sitzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Da sprach Martha zu Jesu: Herr, warestdu hier gewesen, mein Bruder ware nicht gestorben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'aber ich weift auch noch, daß, was du bittest von Gott, das wird dir Gott geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesus spricht zu ihr: Dein Bruder soil auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Martha spricht zu ihm: Ich weift wohl, daß er auferstehen wird in der Auferstehung am Jungsten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesus spricht zu ihr: Ich bin die Auferstehung und das Leben. Wer an mich glaubet, der wird leben, ob er gleich sturbe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'und wer da lebet und glaubet an mich, der wird nimmermehr sterben. Glaubest du das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Sie spricht zu ihm: Herr, ja, ich glaube, daß du bist Christus, der Sohn Gottes, der in die Welt kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Und da sie das gesagt hatte, ging sie hin und rief ihre Schwester Maria heimlich und sprach: Der Meister ist da und rufet dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Dieselbige, als sie das horete, stund sie eilend auf und kam zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Denn Jesus war noch nicht in den Flecken kommen, sondern war noch an dem Ort, da ihm Martha war entgegenkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Die Juden, die bei ihr im Hause waren und trosteten sie, da sie sahen Maria, daß sie eilend aufstund und hinausging, folgten sie ihrnach und sprachen: Sie gehet hin zum Grabe, daß sie daselbst weine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Als nun Maria kam, da Jesus war, und sah ihn, fiel sie zu seinen Füften und sprach zu ihm: Herr, warest du hier gewesen, mein Bruder ware nicht gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Als Jesus sie sah weinen und die Juden auch weinen, die mit ihr kamen, ergrimmete er im Geist und betrubte sich selbst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'und sprach: Wo habt ihr ihn hingelegt? Sie sprachen zu ihm: Herr, komm und sieh es!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Und Jesu gingen die Augen uber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Da sprachen die Juden: Siehe, wie hat er ihn so liebgehabt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Etliche aber unterihnen sprachen: Konnte, der dem Blinden die Augen aufgetan hat, nicht verschaffen, daß auch dieser nicht sturbe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jesus aber ergrimmete abermal in sich selbst und kam zum Grabe. Es war aber eine Kluft und ein Stein darauf gelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jesus sprach: Hebet den Stein ab! Spricht zu ihm Martha, die Schwester des Verstorbenen: Herr, er stinkt schon; denn er ist vier Tage gelegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus spricht zu ihr: Hab\' ich dir nicht gesagt, so du glauben wurdest, du solltest die Herrlichkeit Gottes sehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Da huben sie den Stein ab, da der Verstorbene lag. Jesus aber hub seine Augen empor und sprach: Vater, ich danke dir, daß du mich erhoret hast!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Doch ich weift, daß du mich allezeit horest, sondern um des Volks willen, das umherstehet, sage ich\'s, daß sie glauben, du habest mich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Da er das gesagt hatte, rief er mit lauter Stimme: Lazarus, komm heraus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Und der Verstorbene kam heraus, gebunden mit Grabtüchem an Füften und Handen, und sein Angesicht verhullet mit einem Schweifttuch. Jesus spricht zu ihnen: Loset ihn auf und lasset ihn gehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Viel nun der Juden, die zu Maria kommen waren und sahen, was Jesus tat, glaubten an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Etliche aber von ihnen gingen hin zu den Pharisaern und sagten ihnen, was Jesus getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Da versammelten die Hohenpriester und die Pharisaer einen Rat und sprachen: Was tun wir? Dieser Mensch tut viel Zeichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Lassen wir ihn also, so werden sie alle an ihn glauben. So kommen dann die Romer und nehmen uns Land und Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Einer aber unter ihnen, Kaiphas, der desselben Jahres Hoherpriester war, sprach zu ihnen: Ihrwisset nichts,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'bedenket auch nichts; es ist uns besser, ein Mensch sterbe fur das Volk, denn daß das ganze Volk verderbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Solches aber redete er nicht von sich selbst, sondern, dieweil er desselbigen Jahres Hoherpriester war, weissagte er. Denn Jesus sollte sterben fur das Volk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'und nicht fur das Volk allein, sondern daß er die Kinder Gottes, die zerstreuet waren, zusammenbrachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Von dem Tage an ratschlagten sie, wie sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jesus aber wandelte nicht mehr frei unter den Juden, sondern ging von dannen in eine Gegend nahe bei der Wuste in eine Stadt, genannt Ephrem, und hatte sein Wesen daselbst mit seinen Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Es war aber nahe das Ostern der Juden; und es gingen viele hinauf gen Jerusalem aus der Gegend vor Ostern daß sie sich reinigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Da stunden sie und fragten nach Jesu und redeten miteinander im Tempel: Was dünket euch, dafi er nicht kommt auf das Fest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Es hatten aber die Hohenpriester und Pharisaer lassen ein Gebot ausgehen, so jemand wulite, wo erware, daß er\'s anzeigete, daß sie ihn griffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Sechs Tage vor Ostern kam Jesus gen Bethanien, da Lazarus war, der Verstorbene, welchen Jesus auferwecket hatte von den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Daselbst machten sie ihm ein Abendmahl, und Martha dienete; Lazarus aber war der einer, die mit ihm zu Tische salien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Da nahm Maria ein Pfund Salbe von ungefalschter, kbstlicher Narde und salbete die Fülie Jesu und trocknete mit ihrem Haar seine Fulie. Das Haus aber ward voll vom Geruch der Salbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Da sprach seiner Jünger einer, Judas, Simons Sohn, Ischariot, der ihn hernach verriet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Warum ist diese Salbe nicht verkauft um dreihundert Groschen und den Armen gegeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Das sagte er aber nicht, daß er nach den Armen fragte, sondern er war ein Dieb und hatte den Beutel und trug, was gegeben ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Da sprach Jesus: Laü sie mit Frieden! Solches hat sie behalten zum Tage meines Begrabnisses.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Denn Arme habt ihr allezeit bei euch; mich aber habt ihr nicht allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Da erfuhr viel Volks der Juden, daß er daselbst war, und kamen nicht um Jesu willen allein, sondern daß sie auch Lazarus sahen, welchen er von den Toten erweckt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Aber die Hohenpriester trachteten danach, daß sie auch Lazarus toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Denn um seinetwillen gingen viel Juden hin und glaubten an Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Des andern Tages, viel Volks, das aufs Fest kommen war, da es horete, daß Jesus kommt gen Jerusalem,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'nahmen sie Palmenzweige und gingen hinaus ihm entgegen und schrieen: Hosianna! Gelobet sei, der da kommt in dem Namen des Herrn, ein Konig von Israel!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Jesus aber überkam ein Eselein und rittdarauf, wie denn geschrieben stehet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Furchte dich nicht, du Tochter Zion; siehe, dein Konig kommt reitend auf einem Eselsfullen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Solches aber verstunden seine Jünger zuvor nicht, sondern da Jesus verklaret ward, da dachten sie daran, daß solches war von ihm geschrieben, und sie solches ihm getan hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Das Volk aber, das mit ihm war, da er Lazarus aus dem Grabe rief und von den Toten auferweckte, rühmetedie Tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Darum ging ihm auch das Volk entgegen, da sie horeten, er hatte solches Zeichen getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Die Pharisaer aber sprachen untereinander: Ihr sehet, daß ihr nichts ausrichtet; siehe, alle Welt lauft ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Es waren aber etliche Griechen unter denen, die hinaufkommen waren, daß sie anbeteten auf das Fest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Die traten zu Philippus, der von Bethsaida aus Galilaa war, baten ihn und sprachen: Herr, wirwollten Jesum gerne sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippus kommt und sagt\'s Andreas, und Philippus und Andreas sagten\'s weiter Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus aber antwortete ihnen und sprach: Die Zeit ist kommen, daß des Menschen Sohn verklaret werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Wahrlich, wahrlich, ich sage euch: Es sei denn, daß das Weizenkorn in die Erde falle und ersterbe, so bleibt\'s alleine; wo es aber erstirbt, so bringt\'s viel Fruchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Wersein Leben liebhat, der wird\'s verlieren; und wer sein Leben auf dieser Welt hasset, der wird\'s erhalten zum ewigen Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Wer mir dienen will, der folge mir nach; und wo ich bin, da soil mein Diener auch sein. Und wer mir dienen wird, den wird mein Vaterehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Jetzt ist meine Seele betrubet. Und was soil ich sagen? Vater, hilf mir aus dieser Stunde! Doch darum bin ich in diese Stunde kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Vater, verklare deinen Namen! Da kam eine Stimme vom Himmel: Ich hab\' ihn verklaret und will ihn abermal verklaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Da sprach das Volk, das dabeistund und zuhorete: Es donnerte! Die andern sprachen: Es redete ein Engel mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus antwortete und sprach: Diese Stimme ist nicht um meinetwillen geschehen, sondern um euretwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Jetzt gehet das Gericht uber die Welt; nun wird der Furst dieser Welt ausgestolien werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Und ich, wenn ich erhohet werde von der Erde, so will ich sie alle zu mir ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Das sagte er aber, zu deuten, welches Todes er sterben wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Da antwortete ihm das Volk: Wir haben gehoret im Gesetz, daß Christus ewiglich bleibe; und wie sagst du denn, des Menschen Sohn muli erhohet werden? Wer ist dieser Menschensohn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Da sprach Jesus zu ihnen: Es ist das Licht noch eine kleine Zeit bei euch. Wandelt, dieweil ihr das Licht habt, daß euch die Finsternisse nicht überfallen. Wer in Finsternis wandelt, derweili nicht, wo er hingehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Glaubet an das Licht, dieweil ihr\'s habt, auf daß ihr des Lichtes Kinder seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Solches redete Jesus und ging weg und verbarg sich vor ihnen. Und ob er wohl solche Zeichen vor ihnen tat, glaubten sie doch nicht an ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'auf daß erfullet wurde der Spruch des Propheten Jesaja, den er sagt: Herr, wer glaubet unserm Predigen, und wem ist der Arm des Herrn offenbaret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Darum konnten sie nicht glauben; denn Jesaja sagt abermal:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Er hat ihre Augen verblendet und ihr Herz verstocket, dafi sie mit den Augen nicht sehen, noch mit dem Herzen vernehmen und sich bekehren, und ich ihnen hülfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Solches sagte Jesaja, da er seine Herrlichkeit sah und redete von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Doch der Obersten glaubten viel an ihn; aber um der Pharisaer willen bekannten sie es nicht, daß sie nicht in den Bann getan wurden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'denn sie hatten lieberdie Ehre bei den Menschen denn die Ehre bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jesus aber rief und sprach: Wer an mich glaubet, der glaubet nicht an mich, sondern an den, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Und wer mich siehet, der siehet den, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ich bin kommen in die Welt ein Licht, auf daü, wer an mich glaubet, nicht in Finsternis bleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Und wer meine Worte horet und glaubet nicht, den werde ich nicht richten; denn ich bin nicht kommen; da(J ich die Welt richte, sondern dafi ich die Welt selig mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Wer mich verachtet und nimmt meine Worte nicht auf, der hat schon, der ihn richtet: das Wort, welches ich geredet habe, das wird ihn richten am Jungsten Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Denn ich habe nicht von mir selber geredet, sondern der Vater, der mich gesandt hat, der hat mir ein Gebot gegeben, was ich tun und reden soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Und ich weili, daß sein Gebot ist das ewige Leben. Darum, was ich rede, das rede ich also, wie mir der Vater gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Vor dem Fest aber der Ostern, da Jesus erkennete, daß seine Zeit kommen war, daß er aus dieser Welt ginge zum Vater: wie er hatte geliebet die Seinen, die in der Welt waren, so liebte er sie bis ans Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Und nach dem Abendessen, da schon der Teufel hatte dem Judas, Simons Sohn, dem Ischariot, ins Herz gegeben, daß er ihn verriete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'wuftte Jesus, daß ihm der Vater hatte alles in seine Hande gegeben, und daß er von Gott kommen war und zu Gottging:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'stund ervom Abendmahl auf, legte seine Kleider ab und nahm einen Schurz und umgurtete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Danach goft er Wasser in ein Becken, hub an, den Jungern die Fuße zu waschen, und trocknete sie mit dem Schurz, damit er umgurtet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Da kam erzu Simon Petrus; und derselbige sprach zu ihm: Herr, solltest du mir meine Fufte waschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus antwortete und sprach zu ihm: Was ich tue, das weiftt du jetzt nicht; du wirst\'s aber hernach erfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Da sprach Petrus zu ihm: Nimmermehr sollst du mir die Fufte waschen. Jesus antwortete ihm: Werde ich dich nicht waschen, so hast du kein Teil mit mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Sprichtzu ihm Simon Petrus: Herr, nicht die Füfte alleine, sondern auch die Hande und das Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Spricht Jesus zu ihm: Wer gewaschen ist, der bedarf nicht denn die Fufte waschen, sondern er ist ganz rein. Und ihr seid rein, aber nicht alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Denn er wuftte seinen Verraterwohl; darum sprach er: Ihr seid nicht alle rein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Da er nun ihre Fufte gewaschen hatte, nahm er seine Kleider und setzte sich wieder nieder und sprach abermal zu ihnen: Wisset ihr, was ich euch getan habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ihr heiftet mich Meister und Herr und saget recht daran; denn ich bin\'s auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'So nun ich, euer Herr und Meister, euch die Füfte gewaschen habe, so sollt ihr auch euch untereinander die Füfte waschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Ein Beispiel habe ich euch gegeben, daß ihr tut, wie ich euch getan habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Wahrlich, wahrlich, ich sage euch, der Knecht ist nicht grofter denn sein Herr noch der Apostel grofter, denn der ihn gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'So ihr solches wisset, selig seid ihr, so ihr\'s tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Nicht sage ich von euch alien, (ich weift, welche ich erwahlet habe), sondern daß die Schrift erfüllet werde: Der mein Brot isset, der tritt mich mit Füften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Jetzt sage ich\'s euch, ehe denn es geschiehet, auf daß, wenn es geschehen ist, daß ihr glaubet, daß ich\'s bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Wahrlich, wahrlich, ich sage euch: Wer aufnimmt, so ich jemand senden werde, der nimmt mich auf; wer aber mich aufnimmt, der nimmt den auf, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Da solches Jesus gesagt hatte, ward er betrubt im Geist und zeugete und sprach: Wahrlich, wahrlich, ich sage euch, einer unter euch wird mich verraten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Da sahen sich die Jünger untereinander an, und ward ihnen bange, von welchem er redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Es war aber einer unter seinen Jungern, derzu Tische saft an der Brust Jesu, welchen Jesus liebhatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Dem winkete Simon Petrus, daß erforschen sollte, wer es ware, von dem er sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Denn derselbige lag an der Brust Jesu und sprach zu ihm: Herr, wer ist\'s?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jesus antwortete: Der ist\'s, dem ich den Bissen eintauche und gebe. Und er tauchte den Bissen ein und gab ihn Judas, Simons Sohn, dem Ischariot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Und nach dem Bissen fuhr der Satan in ihn. Da sprach Jesus zu ihm: Was du tust, das tue bald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Dasselbige aber wuftte niemand über dem Tische, wozu er\'s ihm sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Etliche meineten, dieweil Judas den Beutel hatte, Jesus sprache zu ihm: Kaufe, was uns not ist auf das Fest; Oder daß er den Armen etwas gabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Da er nun den Bissen genommen hatte, ging er sobald hinaus. Und es war Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Da er aber hinausgegangen war, spricht Jesus: Nun ist des Menschen Sohn verklaret, und Gott ist verklaret in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Ist Gott verklaret in ihm, wird ihn auch Gott verklaren in ihm selbst und wird ihn bald verklaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Liebe Kindlein, ich bin noch eine kleine Weile bei euch. Ihr werdet mich suchen; und wie ich zu den Juden sagte: Wo ich hingehe; da konnt ihr nicht hinkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Und ich sage euch nun: Ein neu Gebot gebe ich euch, daß ihr euch untereinander liebet, wie ich euch geliebet habe, auf dafi auch ihr einander lieb habet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Dabei wird jedermann erkennen, dafi ihr meine Junger seid, so ihr Liebe untereinander habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Spricht Simon Petrus zu ihm: Herr, wo gehest du hin? Jesus antwortete ihm: Da ich hingehe, kannst du mir diesmal nicht folgen; aber du wirst mir hernachmalsfolgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Petrus spricht zu ihm: Herr, warum kann ich dir diesmal nicht folgen? Ich will mein Leben fur dich lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus antwortete ihm: Solltest du dein Leben fur mich lassen? Wahrlich, wahrlich, ich sage dir, der Hahn wird nicht krahen, bis du mich dreimal habest verleugnet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Und er sprach zu seinen Jungern: Euer Herz erschrecke nicht! Glaubet ihr an Gott, so glaubet ihr auch an mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'In meines Vaters Hause sind viel Wohnungen. Wenn\'s nicht so ware, so wollt\' ich zu euch sagen; ich gehe hin euch die Statte zu bereiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Und ob ich hinginge, euch die Statte zu bereiten, will ich doch wiederkommen und euch zu mir nehmen, auf daß ihr seid, wo ich bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Und wo ich hingehe, das wisset ihr, und den Weg wisset ihr auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Spricht zu ihm Thomas: Herr, wirwissen nicht, wo du hingehest; und wie konnen wir den Weg wissen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus spricht zu ihm: Ich bin der Weg und die Wahrheit und das Leben; niemand kommt zum Vater denn durch mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Wenn ihr mich kennetet, so kennetet ihr auch meinen Vater. Und von nun an kennet ihr ihn und habt ihn gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Spricht zu ihm Philippus: Herr, zeige uns den Vater, so genuget uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesus spricht zu ihm: So lange bin ich bei euch und du kennest mich nicht? Philippus, wer mich siehet, der siehet den Vater. Wie sprichst du denn: Zeige uns den Vater?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Glaubest du nicht, dafi ich im Vater und der Vater in mir ist? Die Worte, die zu euch rede, die rede ich nicht von mir selbst. Der Vater aber, der in mir wohnet, derselbige tut die Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Glaubet mir, dafi ich im Vater und der Vater in mir ist; wo nicht, so glaubet mir doch urn der Werke willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Wahrlich, wahrlich, ich sage euch: Wer an mich glaubet, der wird die Werke auch tun, die ich tue, und wird groftere denn diese tun; denn ich gehe zum Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Und was ihr bitten werdet in meinem Namen, das will ich tun, auf daß der Vater geehret werde in dem Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Was ihr bitten werdet in meinem Namen das will ich tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Liebet ihr mich, so haltet meine Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Und ich will den Vater bitten, und er soil euch einen andern Troster geben, daß er bei euch bleibe ewiglich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'den Geist der Wahrheit, welchen die Welt nicht kann empfangen; denn sie siehet ihn nicht und kennet ihn nicht. Ihr aber kennet ihn; denn er bleibet bei euch und wird in euch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ich will euch nicht Waisen lassen; ich komme zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Es ist noch urn ein kleines, so wird mich die Welt nicht mehr sehen; ihr aber sollt mich sehen: denn ich lebe, und ihr sollt auch leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'An demselbigen Tage werdet ihr erkennen, daß ich in meinem Vater bin und ihr in mir und ich in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Wer meine Gebote hat und halt sie, der ist\'s, der mich liebet. Wer mich aber liebet, der wird von meinem Vater geliebet werden, und ich werde ihn lieben und mich ihm offenbaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Spricht zu ihm Judas, nicht der Ischariot: Herr, was ist\'s, daß du uns willst dich offenbaren und nicht der Welt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus antwortete und sprach zu ihm: Wer mich liebet, der wird mein Wort halten; und mein Vater wird ihn lieben, und wir werden zu ihm kommen und Wohnung bei ihm machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Wer aber mich nicht liebet, der halt meine Worte nicht. Und das Wort, das ihr horet ist nicht mein, sondern des Vaters, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Solches hab\' ich zu euch geredet, weil ich bei euch gewesen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Aber der Troster, der Heilige Geist, welchen mein Vater senden wird in meinem Namen, derselbige wird\'s euch alles lehren und euch erinnern alles des, das ich euch gesagt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Den Frieden lasse ich euch; meinen Frieden gebe ich euch. Nicht gebe ich euch, wie die Welt gibt. Euer Herz erschrecke nicht und furchte sich nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ihr habt gehoret, daß ich euch gesagt habe: Ich gehe hin und komme wieder zu euch. Hattet ihr mich lieb, so würdet ihr euch freuen, daß ich gesagt habe: Ich gehe zum Vater; denn der Vater ist großer denn ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Und nun hab\' ich\'s euch gesagt, ehe denn es geschiehet, auf daß, wenn es nun geschehen wird, daß ihrglaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Ich werde hinfort nicht mehr viel miteuch reden; denn es kommt der Furst dieser Welt und hat nichts an mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Aber daß die Welt erkenne, daß ich den Vater liebe, und ich also tue, wie mir der Vater geboten hat, stehet auf und lasset uns von hinnen gehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ich bin ein rechter Weinstock und mein Vater ein Weingartner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Eine jegliche Rebe an mir, die nicht Frucht bringet, wird erwegnehmen, und eine jegliche, die da Frucht bringet, wird er reinigen, daß sie mehr Frucht bringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ihr seid jetzt rein urn des Worts willen, das ich zu euch geredet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Bleibt in mir und ich in euch. Gleichwie die Rebe kann keine Frucht bringen von ihr selber, sie bleibe denn am Weinstock, also auch ihr nicht, ihr bleibet denn an mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ich bin der Weinstock; ihr seid die Reben. Wer in mir bleibet und ich in ihm der bringet viel Frucht; denn ohne mich konnt ihr nichts tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Wer nicht in mir bleibet, der wird weggeworfen wie eine Rebe und verdorret, und man sammelt sie und wirft sie ins Feuer, und muß brennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'So ihr in mir bleibet, und meine Worte in euch bleiben, werdet ihr bitten, was ihrwollt, und es wird euch widerfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Darinnen wird mein Vater geehret, daß ihr viel Frucht bringet und werdet meine Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Gleichwie mich mein Vater liebet, also liebe ich euch auch. Bleibet in meiner Liebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'So ihr meine Gebote haltet, so bleibet ihr in meiner Liebe, gleichwie ich meines Vaters Gebote halte und bleibe in seiner Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Solches rede ich zu euch, auf daß meine Freude in euch bleibe, und eure Freude vollkommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Das ist mein Gebot, daß ihr euch untereinander liebet, gleichwie ich euch liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Niemand hatgroßere Liebe denn die, daß er sein Leben lasset fur seine Freunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ihr seid meine Freunde, so ihr tut, was ich euch gebiete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ich sage hinfort nicht, daß ihr Knechte seid; denn ein Knecht weiß nicht, was sein FHerr tut. Euch aber habe ich gesagt, daß ihr Freunde seid; denn alles, was ich habe von meinem Vater gehoret, hab\' ich euch kundgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ihr habet mich nicht erwahlet, sondern ich habe euch erwahlet und gesetzt, daß ihr hingehet und Frucht bringet, und eure Frucht bleibe, auf daß, so ihr den Vater bittet in meinem Namen, daß er\'s euch gebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Das gebiete ich euch, daß ihr euch untereinander liebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'So euch die Welt hasset, so wisset, daß sie mich vor euch gehasset hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Waret ihr von der Welt, so hatte die Weit das Ihre lieb; dieweil ihr aber nicht von der Welt seid, sondern ich habe euch von der Welt erwahlet, darum hasset euch die Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Gedenket an mein Wort, das ich euch gesagt habe: Der Knecht ist nicht großer denn, sein Herr. Haben sie mich verfolget, sie werden euch auch verfolgen; haben sie mein Wort gehalten, so werden sie eures auch halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Aber das alles werden sie euch tun urn meines Namens willen; denn sie kennen den nicht, der mich gesandt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Wenn ich nicht kommen ware und hatte es ihnen gesagt, hatten sie keine Sünde; nun aber konnen sie nichts vorwenden, ihre Sünde zu entschuldigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Wer mich hasset, der hasset auch meinen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Hatte ich nicht die Werke getan unter ihnen, die kein anderer getan hat, so hatten sie keine Sünde; nun aber haben sie es gesehen und hassen doch beide, mich und meinen Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Doch daß erfüllet werde der Spruch, in ihrem Gesetz geschrieben: Sie hassen mich ohn\' Ursache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Wenn aber der Troster kommen wird, welchen ich euch senden werde vom Vater, der Geist der Wahrheit, der vom Vater ausgehet, der wird zeugen von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Und ihr werdet auch zeugen; denn ihr seid von Anfang bei mirgewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Solches habe ich zu euch geredet, daß ihr euch nicht argert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Sie werden euch in den Bann tun. Es kommt aber die Zeit, daß, wer euch totet, wird meinen, er tue Gott einen Dienst daran.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Und solches werden sie euch darum tun, daß sie weder meinen Vater noch mich erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Aber solches habe ich zu euch geredet, auf daß, wenn die Zeit kommen wird, daß ihr daran gedenket, daß ich\'s euch gesagt habe. Solches aber habe ich euch von Anfang nicht gesagt; denn ich war bei euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Nun aber gehe ich hin zu dem, der mich gesandt hat; und niemand unter euch fraget mich: Wo qehest du hin?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'sondern dieweil ich solches zu euch geredet habe, ist euer Herz voll Trauerns worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Aber ich sage euch die Wahrheit: Es ist euch gut, daß ich hingehe. Denn so ich nicht hingehe, so kommt der T roster nicht zu euch; so ich abergehe, will ich ihn zu euch senden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Und wenn derselbige kommt, der wird die Welt strafen urn die Sunde und um die Gerechtigkeit und urn das Gericht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'um die Sunde, dafi sie nicht glauben an mich;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'um die Gerechtigkeit aber, daß ich zum Vater gehe, und ihr mich hinfort nicht sehet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'um das Gericht, daß der Fürst dieser Welt gerichtet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Ich habe euch noch viel zu sagen; aber ihr konnet\'s jetzt nicht tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Wenn aberjener, der Geist der Wahrheit, kommen wird, der wird euch in alle Wahrheit leiten. Denn erwird nicht von ihm selber reden, sondern was er horen wird, das wird er reden, und was zukunftig ist, wird er euch verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Derselbige wird mich verklaren; denn von dem Meinen wird er\'s nehmen und euch verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alles, was der Vater hat, das ist mein; darum hab\' ich gesagt: Er wird\'s von dem Meinen nehmen und euch verkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Uber ein kleines, so werdet ihr mich nicht sehen, und aber uber ein kleines, so werdet ihr mich sehen; denn ich gehe zum Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Da sprachen etliche unterseinen Jungern untereinander: Was ist das, was er saget zu uns: Uber ein so werdet ihr mich nicht sehen, und aber uber ein kleines, so werdet ihr mich sehen, und daü ich zum Vater gehe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Da sprachen sie: Was ist das, was er sagt: Uber ein kleines? Wir wissen nicht, was er redet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Da merkete Jesus, daß sie ihn fragen wollten, und sprach zu ihnen: Davon fraget ihr untereinander, daß ich gesagt habe: Uber ein kleines, so werdet ihr mich nicht sehen, und aber uber ein kleines, so werdet ihr mich sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Wahrlich, wahrlich, ich, sage euch: Ihr werdet weinen und heulen; aber die Welt wird sich freuen. Ihr aber werdet traurig sein; doch eure Traurigkeit soil in Freude verkehret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Ein Weib, wenn sie gebiert, so hat sie Traurigkeit; denn ihre Stunde ist kommen. Wenn sie aber das Kind geboren hat, denket sie nicht mehr an die Angst um der Freude willen, daß der Mensch zur Welt geboren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Und ihr habt auch nun Traurigkeit aber ich will euch wiedersehen, und euer Herz soil sich freuen, und eure Freude soil niemand von euch nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Und an demselbigen Tage werdet ihr mich nichts fragen. Wahrlich, wahrlich, ich sage euch: So ihr den Vater etwas bitten werdet in meinen Namen, so wird er\'s euch geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Bisher habt ihr nichts gebeten in meinem Namen. Bittet, so werdet ihr nehmen, daß eure Freude vollkommen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Solches hab\' ich zu euch durch Sprichworter geredet. Es kommt aber die Zeit, daß ich nicht mehr durch Sprichworter mit euch reden werde, sondern euch frei heraus verkundigen von meinem Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'An demselbigen Tage werdet ihr bitten in meinem Namen. Und ich sage euch nicht, daü ich den Vater fur euch bitten will;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'denn er selbst, der Vater, hat euch lieb, darum daß ihr mich liebet und glaubet, daß ich von Gott ausgegangen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ich bin vom Vater ausgegangen und kommen in die Welt; wiederum verlasse ich die Welt und gehe zum Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Sprechen zu ihm seine Junger: Siehe, nun redest du frei heraus und sagest kein Sprichwort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Nun wissen wir, daß du alle Dinge weilit und bedarfst nicht, daß dich jemand frage. Darum glauben wir, daß du von Gott ausgegangen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesus antwortete ihnen: Jetzt glaubet ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Siehe, es kommt die Stunde und ist schon kommen, daß ihr zerstreuet werdet, ein jeglicher in das Seine, und mich alleine lasset. Aber ich bin nicht alleine; denn der Vater ist bei mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Solches habe ich mit euch geredet, daß ihr in mir Frieden habet. In der Welt habt ihr Angst; aber seid getrost, ich habe die Welt uberwunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Solches redete Jesus und hub seine Augen auf gen Himmel und sprach: Vater, die Stunde ist hier, daß du deinen Sohn verklarest, auf daß dich dein Sohn auch verklare,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'gleichwie du ihm Macht hast gegeben uber alles Fleisch, auf daß er das ewige Leben gebe alien, die du ihm gegeben hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Das ist aber das ewige Leben, daß sie dich, daß du allein wahrer Gott bist, und den du gesandt hast, Jesum Christum, erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ich habe dich verklaret auf Erden und vollendet das Werk, das du mir gegeben hast, daß ich\'s tun sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Und nun verklare mich du, Vater, bei dir selbst mit der Klarheit, die ich bei dir hatte, ehe die Welt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ich habe deinen Namen offenbaret den Menschen, die du mir von der Welt gegeben hast. Sie waren dein, und du hast sie mir gegeben, und sie haben dein Wort behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nun wissen sie, daß alles, was du mir gegeben hast, sei von dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Denn die Worte, die du mir gegeben hast, hab\' ich ihnen gegeben; und sie haben\'s angenommen und erkannt wahrhaftig, daß ich von dir ausgegangen bin, und glauben, daß du mich gesandt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ich bitte fur sie und bitte nicht fur die Welt, sondern fur die, so du mir gegeben hast; denn sie sind dein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Und alles, was mein ist, das ist dein, und was dein ist, das ist mein; und ich bin in ihnen verklaret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Und ich bin nicht mehr in der Welt; sie aber sind in der Welt, und ich komme zu dir. Heiliger Vater, erhalte sie in deinem Namen, die du mirgegeben hast, daß sie eins seien gleichwie wir!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Dieweil ich bei ihnen war in der Welt, erhielt ich sie in deinem Namen. Die du mirgegeben hast, die habe ich bewahret, und ist keiner von ihnen verloren ohne das verlorne Kind, daß die Schrift erfullet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Nun aber komme ich zu dir und rede solches in der Welt, auf daß sie in ihnen haben meine Freude vollkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ich hab\' ihnen gegeben dein Wort, und die Welt hasset sie; denn sie sind nicht von der Welt, wie denn auch ich nicht von der Welt bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ich bitte nicht, daß du sie von der Welt nehmest, sondern daß du sie bewahrest vor dem Libel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Sie sind nicht von der Welt, gleichwie auch ich nicht von der Welt bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Heilige sie in deiner Wahrheit; dein Wort ist die Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Gleichwie du mich gesandt hast in die Welt, so sende ich sie auch in die Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Ich heilige mich selbst fur sie, auf daß auch sie geheiliget seien in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ich bitte aber nicht alleine fur sie, sondern auch fur die, so durch ihr Wort an mich glauben werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'auf daß sie alle eins seien gleichwie du, Vater, in mir und ich in dir, daß auch sie in uns eins seien, auf daß die Welt glaube, du habest mich gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Und ich hab\' ihnen gegeben die Herrlichkeit, die du mir gegeben hast, da(J sie eins seien, gleichwie wir eins sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'ich in ihnen und du in mir, auf dafi sie vollkommen seien in eins, und die Welt erkenne, da(5 du mich gesandt hast und liebest sie, gleichwie du mich liebest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Vater, ich will, dafi, wo ich bin, auch die bei mir seien, die du mirgegeben hast, daß sie meine Herrlichkeit sehen, die du mir gegeben hast; denn du hast mich geliebet, ehe denn die Welt gegrundet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Gerechter Vater, die Welt kennet dich nicht; ich aber kenne dich, und diese erkennen, daß du mich gesandt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Und ich habe ihnen deinen Namen kundgetan und will ihnen kundtun, auf daß die Liebe, damit du mich liebest, sei in ihnen und ich in ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Da Jesus solches geredet hatte, ging er hinaus mit seinen Jungern uber den Bach Kidron. Da war ein Garten, darein ging Jesus und seine Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Judas aber, der ihn verriet, wuißte den Ort auch; denn Jesus versammelte sich oft daselbst mit seinen Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Da nun Judas zu sich hatte genommen die Schar und der Hohenpriester und Pharisaer Diener, kommt er dahin mit Fackeln, Lampen und mit Waffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Als nun Jesus wui Jte alles, was ihm begegnen sollte, ging er hinaus und sprach zu ihnen: Wen suchet ihr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Sie antworteten ihm: Jesum von Nazareth. Jesus spricht zu ihnen: Ich bin\'s. Judas aber, der ihn verriet, stund auch bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Als nun Jesus zu ihnen sprach: Ich bin\'s, wichen sie zuruck und fielen zu Boden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Da fragte er sie abermal: Wen suchet ihr? Sie aber sprachen: Jesum von Nazareth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus antwortete: Ich hab\'s euch gesagt, daß ich es sei. Suchet ihr denn mich, so lasset diese gehen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, '(auf daß das Wort erfullet wurde, welches er sagte: Ich habe der keinen verloren, die du mir gegeben hast).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Da hatte Simon Petrus ein Schwert und zog es aus und schlug nach des Hohenpriesters Knecht und hieb ihm sein rechtes Ohr ab; und der Knecht hieli Malchus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Da sprach Jesus zu Petrus: Stecke dein Schwert in die Scheide! Soil ich den Kelch nicht trinken, den mir mein Vater gegeben hat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Die Schar aber und der Oberhauptmann und die Diener der Juden nahmen Jesum und banden ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'und führeten ihn aufs erstezu Hannas; der war des Kaiphas Schwaher, welcher des Jahrs Hoherpriester war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Es war aber Kaiphas, der den Juden riet, es ware gut, daß ein Mensch wurde umgebracht fur das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Petrus aberfolgte Jesu nach und ein anderer Junger. Derselbige Junger war dem Hohenpriester bekannt und ging mit Jesu hinein in des Hohenpriesters Palast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Petrus aber stund draulien vor der Tur. Da ging der andere Junger, der dem Hohenpriester bekannt war, hinaus und redete mit der Turhuterin und fuhrete Petrus hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Da sprach die Magd, die Turhuterin zu Petrus: Bist du nicht auch dieses Menschen Junger einer? Er sprach: Ich bin\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Es stunden aber die Knechte und Diener und hatten ein Kohlenfeuer gemacht (denn es war kalt) und warmeten sich. Petrus aber stund bei ihnen und warmete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Aber der Hohepriester fragte Jesum urn seine Junger und urn seine Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus antwortete ihm: Ich habe frei offentlich geredet vor der Welt. Ich habe allezeit geiehret in der Schule und in dem Tempel, da alle Juden zusammenkommen, und habe nichts im Verborgenen geredet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Was fragest du mich darum? Frage die darum, die gehoret haben, was ich zu ihnen geredet habe. Siehe, dieselbigen wissen, was ich gesagt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Als er aber solches redete, gab der Diener einer, die dabeistunden, Jesu einen Backenstreich und sprach: Sollst du dem Hohenpriester also antworten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus antwortete: Hab\' ich ubel geredet, so beweise es, daß es bose sei; habe ich aber recht geredet, was schlagest du mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Und Hannas sandte ihn gebunden zu dem Hohenpriester Kaiphas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petrus aber stund und warmete sich. Da sprachen sie zu ihm: Bist du nicht seiner Jünger einer? Er verleugnete aber und sprach: Ich bin\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Spricht des Hohenpriesters Knechte einer, ein Gefreundeter des, dem Petrus das Ohr abgehauen hatte: Sah ich dich nicht im Garten bei ihm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Da verleugnete Petrus abermal; und alsbald krahete der Hahn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Da fuhreten sie Jesum von Kaiphas vor das Richthaus. Und es war früh. Und sie gingen nicht in das Richthaus, auf daß sie nicht unrein würden, sondern Ostern essen mochten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Da ging Pilatus zu ihnen heraus und sprach: Was bringet ihr fur Klage wider diesen Menschen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Sie antworteten und sprachen zu ihm: Ware dieser nicht ein Ubeltater wir hatten dir ihn nicht überantwortet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Da sprach Pilatus zu ihnen: So nehmet ihr ihn hin und richtet ihn nach eurem Gesetz. Da sprachen die Juden zu ihm: Wir dürfen niemand toten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, '(auf daß erfullet wurde das Wort Jesu, welches er sagte, da er deutete, welches Todes er sterben wurde).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Da ging Pilatus wieder hinein ins Richthaus und rief Jesu und sprach zu ihm: Bist du der Juden Konig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus antwortete: Redest du das von dir selbst, Oder haben\'s dir andere von mir gesagt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus antwortete: Bin ich ein Jude? Dein Volk und die Hohenpriester haben dich mir überantwortet; was hast du getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus antwortete: Mein Reich ist nicht von dieser Welt. Ware mein Reich von dieser Welt, meine Diener würden drob kampfen, daß ich den Juden nicht überantwortet würde; aber nun ist mein Reich nicht von dannen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Da sprach Pilatus zu ihm: So bist du dennoch ein Konig? Jesus antwortete: Du sagst es, ich bin ein Konig. Ich bin dazu geboren und in die Welt kommen, daß ich die Wahrheit zeugen soil. Wer aus der Wahrheit ist, der horet meine Stimme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Spricht Pilatus zu ihm: Was ist Wahrheit? Und da er das gesagt, ging er wieder hinaus zu den Juden und spricht zu ihnen: Ich finde keine Schuld an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Ihr habt aber eine Gewohnheit, daß ich euch einen auf Ostern losgebe; wollt ihr nun, daü ich euch der Juden Konig losgebe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Da schrieen sie wieder allesamt und sprachen: Nicht diesen, sondern Barabbas. Barabbas aber war ein Morder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Da nahm Pilatus Jesum und geilielte ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Und die Kriegsknechte flochten eine Krone von Dornen und setzten sie auf sein Haupt und legten ihm ein Purpurkleid an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'und sprachen: Sei gegru üet, lieber Judenkonig! und gaben ihm Backenstreiche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Da ging Pilatus wieder heraus und sprach zu ihnen: Sehet, ich führe ihn heraus zu euch, daß ihr erkennet, daß ich keine Schuld an ihm finde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Also ging Jesus heraus und trug eine Dornenkrone und Purpurkleid. Und er spricht zu ihnen: Sehet, welch ein Mensch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Da ihn die Hohenpriester und die Diener sahen, schrieen sie und sprachen: Kreuzige, kreuzige! Pilatus spricht zu ihnen: Nehmet ihr ihn hin und kreuziget; denn ich finde keine Schuld an ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Die Juden antworteten ihm: Wir haben ein Gesetz, und nach dem Gesetz soil er sterben; denn er hat sich selbst zu Gottes Sohn gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Da Pilatus das Wort horete, furchtete er sich noch mehr');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'und ging wieder hinein in das Richthaus und spricht zu Jesu: Von wannen bist du? Aber Jesus gab ihm keine Antwort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Da sprach Pilatus zu ihm: Redest du nicht mit mir? Weilit du nicht, daß ich Macht habe, dich zu kreuzigen, und Macht habe, dich loszugeben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus antwortete: Du flattest keine Macht fiber mich, wenn sie dir nicht ware von oben herab gegeben; darum, der mich dir überantwortet hat, der hat groliere Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Von dem an trachtete Pilatus, wie er ihn loslielie. Die Juden aber schrieen und sprachen: Lassest du diesen los, so bist du des Kaisers Freund nicht; denn wer sich zum Konige macht, der ist wider den Kaiser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Da Pilatus das Wort horete, führete er Jesum heraus und setzte sich auf den Richterstuhl an der Statte, die da heilit Hochpflaster, auf ebraisch aber Gabbatha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Es war aber der Rüsttag auf Ostern urn die sechste Stunde. Und er spricht zu den Juden: Sehet, das ist euer Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Sie schrieen aber: Weg, weg mit dem, kreuzige ihn! Spricht Pilatus zu ihnen: Soil ich euren Konig kreuzigen? Die Hohenpriester antworteten: Wir haben keinen Konig denn den Kaiser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Da überantwortete er ihn ihnen, daü er gekreuzigt wurde. Sie nahmen aber Jesum und fuhreten ihn hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Und ertrug sein Kreuz und ging hinaus zur Statte die da heilit Schadelstatte, welche heilit auf ebraisch Golgatha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Allda kreuzigten sie ihn und mit ihm zwei andere zu beiden Seiten, Jesum aber mitten inne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus aber schrieb eine Uberschrift und setzte sie auf das Kreuz; und war geschrieben: Jesus von Nazareth, der Juden Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Diese Uberschrift lasen viel Juden; denn die Statte war nahe bei der Stadt, da Jesus gekreuziget ist. Und es war geschrieben auf ebraische, griechische und lateinische Sprache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Da sprachen die Hohenpriester der Juden zu Pilatus: Schreibe nicht: Der Juden Konig; sondern daß er gesagt habe: Ich bin der Juden Konig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus antwortete: Was ich geschrieben habe, das hab\' ich geschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Die Kriegsknechte aber, da sie Jesum gekreuziget hatten, nahmen sie seine Kleider und machten vier Teile, einem jeglichen Kriegsknecht ein Teil, dazu auch den Rock. Der Rock aber war ungenahet, von oben an gewirket durch und durch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Da sprachen sie untereinander: Lasset uns den nicht zerteilen, sondern darum losen, wes er sein soil (auf daß erfullet würde die Schrift, die da, sagt: Sie haben meine Kleider untersich geteilet und haben fiber meinen Rock das Los geworfen). Solches taten die Kriegsknechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Es stund aber bei dem Kreuze Jesu seine Mutter und seiner Mutter Schwester Maria, des Kleophas Weib, und Maria Magdalena.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Da nun Jesus seine Mutter sah und den Jünger dabeistehen, den er liebhatte spricht er zu seiner Mutter: Weib, siehe das ist dein Sohn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Danach spricht er zu dem Jünger siehe, das ist deine Mutter! Und von der Stunde an nahm sie der Jünger zu sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Danach, als Jesus wuftte, daß schon alles vollbracht war, daß die Schrift erfullet würde, spricht er: Mich dürstet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Da stund ein Gefaft voll Essigs. Sie aber fülleten einen Schwamm mit Essig und legten ihn um einen Ysop und hielten es ihm darzum Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Da nun Jesus den Essig genommen hatte, sprach er: Es ist vollbracht! Und neigete das Haupt und verschied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Die Juden aber; dieweil es der Rüsttag war daß nicht die Leichname am Kreuz blieben den Sabbat fiber (denn desselbigen Sabbats Tag war graft), baten sie Pilatus; daß ihre Beine gebrochen, und sie abgenommen würden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Da kamen die Kriegsknechte und brachen dem ersten die Beine und dem andern, der mit ihm gekreuziget war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Als sie aber zu Jesu kamen, da sie sahen, daß er schon gestorben war, brachen sie ihm die Beine nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'sondern der Kriegsknechte einer offnete seine Seite mit einem Speer; und alsbald ging Blut und Wasser heraus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Und der das gesehen hat, der hat es bezeuget, und sein Zeugnis ist wahr, und derselbige weift, daß er die Wahrheit saget, auf daß auch ihr glaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Denn solches ist geschehen, daß die Schrift erfullet wurde: Ihr sollt ihm kein Bein zerbrechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Und abermal spricht eine andere Schrift: Sie werden sehen, in welchen sie gestochen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Danach bat Pilatus Joseph von Arimathia, der ein Jünger Jesu war, doch heimlich, aus Furcht vor den Juden, daß er mochte abnehmen den Leichnam Jesu. Und Pilatus erlaubte es. Da kam er und nahm den Leichnam Jesu herab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Es kam aber auch Nikodemus, der vormals bei der Nacht zu Jesu kommen war, und brachte Myrrhen und Aloen untereinander bei hundert Pfunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Da nahmen sie den Leichnam Jesu und banden ihn in leinene Tücher mit Spezereien, wie die Juden pflegen zu begraben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Es war aber an der Statte, da er gekreuziget ward, ein Garten und im Garten ein neu Grab, in welches niemand je gelegt war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Daselbst hin legten sie Jesum um des Rusttages willen der Juden, dieweil das Grab nahe war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'An der Sabbate einem kommt Maria Magdalena früh, da es noch finster war, zum Grabe und siehet, daß der Stein vom Grabe hinweg war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Da lauft sie und kommt zu Simon Petrus und zu dem andern Jünger, welchen Jesus liebhatte, und spricht zu ihnen: Sie haben den Herrn weggenommen aus dem Grabe, und wir wissen nicht, wo sie ihn hingelegt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Da ging Petrus und der andere Jünger hinaus und kamen zum Grabe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Es liefen aber die zwei miteinander, und der andere Jünger lief zuvor, schneller denn Petrus, und kam am ersten zum Grabe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'gucket hinein und siehet die Leinen geleget; er ging aber nicht hinein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Da kam Simon Petrus ihm nach und ging hinein in das Grab und siehet die Leinen geleget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'und das Schweifttuch, das Jesu um das Haupt gebunden war, nicht zu den Leinen geleget, sondern beiseits, eingewickelt, an einen besondern Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Da ging auch der andere Jünger hinein, der am ersten zum Grabe kam, und sah und giaubete es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Denn sie wuftten die Schrift noch nicht, daß er von den Toten auferstehen müftte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Da gingen die Jünger wieder zusammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Maria aber stund vor dem Grabe und weinete drauften. Als sie nun weinete, guckte sie in das Grab');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'und siehet zwei Engel in weiften Kleidern sitzen, einen zu den Haupten und den andern zu den Füften, da sie den Leichnam Jesu hingelegt hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Und dieselbigen sprachen zu ihr: Weib, was weinest du? Sie spricht zu ihnen: Sie haben meinen Herrn weggenommen, und ich weift nicht, wo sie ihn hingelegt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Und als sie das sagte, wandte sie sich zurück und siehet Jesum stehen und weili nicht, daß es Jesus ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Spricht Jesus zu ihr: Weib, was weinest du? Wen suchest du? Sie meinet, es sei der Gartner, und spricht zu ihm: Herr, hast du ihn weggetragen, so sage mir, wo hast du ihn hingeleget? so will ich ihn holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Spricht Jesus zu ihr: Maria! Da wandte sie sich um und spricht zu ihm: Rabbuni, das heiftt, Meister!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Spricht Jesus zu ihr: Rühre mich nicht an; denn ich bin noch nicht aufgefahren zu meinem Vater. Gehe aber hin zu meinen Brudern und sage ihnen: Ich fahre auf zu meinem Vater und zu eurem Vater, zu meinem Gott und zu eurem Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalena kommt und verkundiget den Jungern: Ich habe den Herrn gesehen, und solches hat er zu mir gesagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Am Abend aber desselbigen Sabbats, da die Junger versammelt und die Türen verschlossen waren aus Furcht vor den Juden, kam Jesus und trat mitten ein und spricht zu ihnen: Friede sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Und als er das sagte, zeigte er ihnen die Hande und seine Seite. Da wurden die Junger froh, daß sie den Herrn sahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Da sprach Jesus abermal zu ihnen: Friede sei mit euch! Gleichwie mich der Vater gesandt hat, so sende ich euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Und da er das sagte, blies er sie an und spricht zu ihnen: Nehmet hin den Heiligen Geist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Welchen ihr die Sunden erlasset, denen sind sie erlassen, und welchen ihr sie behaltet, denen sind sie behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Thomas aber, der Zwdlfen einer, der da heiftet Zwilling, war nicht bei ihnen, da Jesus kam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Da sagten die andern Junger zu ihm: Wir haben den Herrn gesehen. Er aber sprach zu ihnen: Es sei denn, daß ich in seinen Handen sehe die Nagelmale und lege meinen Finger in die Nagelmale und lege meine Hand in seine Seite, will ich\'s nicht glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Und liber acht Tage waren abermal seine Junger drinnen und Thomas mit ihnen. Kommt Jesus, da die Türen verschlossen waren, und tritt mitten ein und spricht: Friede sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Danach spricht er zu Thomas: Reiche deinen Finger her und siehe meine Hande; und reiche deine Hand her und lege sie in meine Seite; und sei nicht unglaubig, sondern glaubig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas antwortete und sprach zu ihm: Mein Herr und mein Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Spricht Jesus zu ihm: Dieweil du mich gesehen hast, Thomas, so glaubest du. Selig sind, die nicht sehen und doch glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Auch viel andere Zeichen tat Jesus vor seinen Jungern, die nicht geschrieben sind in diesem Buch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Diese aber sind geschrieben, daß ihr glaubet, Jesus sei Christus, der Sohn Gottes, und daß ihr durch den Glauben das Leben habet in seinem Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Danach offenbarte sich Jesus abermal den Jungern an dem Meer bei Tiberias. Er offenbarte sich aber also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Es waren beieinander Simon Petrus und Thomas, der da heiftet Zwilling, und Nathanael von Kana, Galilaa, und die Sohne des Zebedaus und andere zwei seiner Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Spricht Simon Petrus zu ihnen: Ich will hin fischen gehen. Sie sprachen zu ihm: So wollen wir mit dir gehen. Sie gingen hinaus und traten in das Schiff alsbald; und in derselbigen Nachtfingen sie nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Da es aber jetzt Morgen ward, stund Jesus am Ufer; aber die Junger wuftten nicht, daß es Jesus war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Spricht Jesus zu ihnen: Kinder, habt ihr nichts zu essen? Sie antworteten ihm: Nein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Er aber sprach zu ihnen: Werfetdas Netzzur Rechten des Schiffs, so werdet ihr finden. Da warfen sie und konnten\'s nicht mehr ziehen vor der Menge der Fische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Da spricht der Junger, welchen Jesus liebhatte, zu Petrus: Es ist der Herr! Da Simon Petrus horete, daß es der Herr war, gurtete er das Hemd um sich (denn erwar nackend) und warf sich ins Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Die andern Junger aber kamen auf dem Schiffe (denn sie waren nicht fem vom Lande, sondern bei zweihundert Ellen) und zogen das Netz mit den Fischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Als sie nun austraten auf das Land sahen sie Kohlen geleget und Fische dar auf und Brot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Sprich Jesus zu ihnen: Bringet her von den Fischen, die ihr jetzt gefangen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Petrus stieg hinein und zog das Netz auf das Land voll grafter Fische, hundert und dreiundfünfzig. Und wiewohl ihrer so viel waren, zerrift doch das Netz nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Spricht Jesus zu ihnen: Kommt und haltetdas Mahl! Niemand aber unter den Jungern durfte ihn fragen: Wer bist du? Denn sie wuftten, daß es der Herr war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Da kommt Jesus und nimmtdas Brot und gibt\'s ihnen, desselbigengieichen auch die Fische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Das ist nun das dritte Mai, daß Jesus offenbaret ward seinen Jungern, nachdem er von den Toten auferstanden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Da sie nun das Mahl gehalten hatten, spricht Jesus zu Simon Petrus: Simon Johanna, hast du mich lieber, denn mich diese haben? Er spricht zu ihm: Ja, Herr, du weiftt, daß ich dich liebhabe. Spricht erzu ihm: Weide meine Lammer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Spricht erzum andernmal zu ihm: Simon Johanna, hast du mich lieb? Er spricht zu ihm: Ja, Herr, du weiftt, daß ich dich liebhabe. Spricht erzu ihm: Weide meine Schafe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Spricht erzum drittenmal zu ihm: Simon Johanna, hast du mich lieb? Petrus ward traurig, daß er zum drittenmal zu ihm sagte: Hast du mich lieb? und sprach zu ihm: Herr, du weißt alle Dinge, du weüßt, daß ich dich liebhabe. Spricht Jesus zu ihm: Weide meine Schafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wahrlich, wahrlich, ich sage dir: Da du junger warest, gurtetest du dich selbst und wandeltest, wo du hin wolltest; wenn du aber altwirst, wirst du deine Hande ausstrecken, und ein anderer wird dich gurten und fuhren, wo du nicht hin willst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Das sagte eraber, zu deuten, mitwelchem Tode er Gott preisen wurde. Da er aber das gesagt, spricht er zu ihm: Folge mir nach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petrus aberwandte sich urn und sah den Junger folgen welchen Jesus liebhatte, der auch an seiner Brust am Abendessen gelegen war und gesagt hatte: Herr, wer ist\'s, der dich verrat?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Da Petrus diesen sah, spricht erzu Jesu: Herr, was soil aber dieser?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesus spricht zu ihm: So ich will, daß er bleibe, bis ich komme, was gehet es dich an? Folge du mir nach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Da ging eine Rede aus unterden Brudern: Dieser Junger stirbt nicht. Und Jesus sprach nicht zu ihm: Er stirbet nicht, sondern: So ich will, dafi er bleibe, bis ich komme, was gehet es dich an?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Dies ist der Junger, der von diesen Dingen zeuget und hat dies geschrieben; und wirwissen, dafi sein Zeugnis wahrhaftig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Es sind auch viel andere Dinge, die Jesus getan hat, welche, so sie sollten eins nach dem andern geschrieben werden, achte ich, die Welt wurde die Bucher nicht begreifen, die zu beschreiben waren. Die Geschichte der Apostel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Die erste Rede habe ich zwar getan, lieber Theophilus, von alledem, das Jesus anting, beides, zu tun und zu lehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'bis an den Tag, da er aufgenommen ward, nachdem er den Aposteln (welche er hatte erwahlet) durch den Heiligen Geist Befehl getan hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'welchen ersich nach seinem Leiden lebendig erzeiget hatte durch mancherlei Erweisung; und lief!, sich sehen unter ihnen vierzig Tage lang und redete mit ihnen vom Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Und als er sie versammelt hatte, befahl er ihnen, daß sie nicht von Jerusalem wichen, sondern warteten auf die Verheüiung des Vaters, welche ihr habt gehoret (sprach er) von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Denn Johannes hat mit Wasser getauft; ihr aber sollt mit dem Heiligen Geiste getauft werden nicht lange nach diesen Tagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Die aber, so zusammenkommen waren, fragten ihn und sprachen: Herr, wirst du auf diese Zeit wieder aufrichten das Reich Israel?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Er sprach aber zu ihnen: Es gebuhret euch nicht, zu wissen Zeit Oder Stunde, welche der Vater seiner Macht vorbehalten hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'sondern ihr werdet die Kraft des Heiligen Geistes empfangen, welcher auf euch kommen wird; und werdet meine Zeugen sein zu Jerusalem und in ganz Judaa und Samarien und bis an das Ende der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Und da er solches gesagt, ward er aufgehoben zusehends, und eine Wolke nahm ihn auf vor ihren Augen weg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Und als sie ihm nachsahen gen Himmel fahren, siehe, da stunden bei ihnen zwei Manner in weilien Kleidern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'welche auch sagten: Ihr Manner von Galilaa, was stehet ihr und sehet gen Himmel? Dieser Jesus, welcher von euch ist aufgenommen gen Himmel, wird kommen, wie ihr ihn gesehen habt gen Himmel fahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Da wandten sie urn gen Jerusalem von dem Berge, der da heiliet der Olberg, welcher nahe ist bei Jerusalem und liegt einen Sabbatweg davon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Und als sie hineinkamen, stiegen sie auf den Soller, da denn sich aufhielten Petrus und Jakobus, Johannes und Andreas, Philippus und Thomas, Bartholomaus und Matthaus, Jakobus, des Alphaus Sohn, und Simon Zelotes und Judas, des Jakobus Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Diese alle waren stets beieinander einmutig mit Beten und Flehen samt den Weibern und Maria, der Mutter Jesu, und seinen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Und in den Tagen trat auf Petrus unter die Junger und sprach (es war aber die Schar der Namen zuhauf bei hundertundzwanzig)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Ihr Manner und Bruder, es mußte die Schrift erfullet werden, welche zuvor gesagt hat der Heilige Geist durch den Mund Davids, von Juda, der ein Vorganger war derer, die Jesum fingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Denn er war mit uns gezahlet und hatte dies Amt mitunsüberkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Dieser hat erworben den Acker urn den ungerechten Lohn und sich erhenkt und ist mitten entzweigeborsten, und alle sein Eingeweide ausgeschuttet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Und es ist kund worden alien, die zu Jerusalem wohnen, also daß derselbige Acker genannt wird auf ihre Sprache Hakeldama, das ist, ein Blutacker.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Denn es stehet geschrieben im Psalmbuch: Ihre Behausung müsse wüste werden, und sei niemand, der drinnen wohne, und sein Bistum empfange ein anderer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'So muli nun einer unter diesen Mannern, die bei uns gewesen sind die ganze Zeit uber, welche der Herr Jesus unter uns ist aus und ein gegangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'von der Taufe des Johannes an bis auf den Tag, da er von uns genommen ist, ein Zeuge seiner Auferstehung mit uns werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Und sie stelleten zwei, Joseph, genannt Barsabas, mit dem Zunamen Just, und Matthias,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'beteten und sprachen: Herr, aller Herzen Kundiger, zeige an, welchen du erwahlet hast unter diesen zwei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'daß einer empfange diesen Dienst und Apostelamt, davon Judas abgewichen ist, da(J, er hinginge an seinen Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Und sie warfen das Los uber sie; und das Los fiel auf Matthias. Und er ward zugeordnet zu den elf Aposteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Und als der Tag der Pfingsten erfullet war, waren sie alle einmutig beieinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Und es geschah schnell ein Brausen vom Himmel als eines gewaltigen Windes und erfüllete das ganze Haus, da sie salien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Und man sah an ihnen die Zungen zerteilet, als waren sie feurig. Und er setzte sich auf einen jeglichen unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Und wurden alle voll des Heiligen Geistes und fingen an, zu predigen mit andern Zungen, nachdem der Geist ihnen gab auszusprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Es waren aber Juden zu Jerusalem wohnend, die waren gottesfurchtige Manner aus allerlei Volk, das unter dem Himmel ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Da nun diese Stimme geschah, kam die Menge zusammen und wurden besturzt; denn es horete ein jeglicher, daß sie mit seiner Sprache redeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Sie entsetzten sich aber alle, verwunderten sich und sprachen untereinander: Siehe, sind nicht diese alle, die da reden, aus Galilaa?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Wie horen wir denn ein jeglicher seine Sprache, darinnen wir geboren sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parther und Meder und Elamiter, und die wir wohnen in Mesopotamien und in Judaa und Kappadozien, Pontus und Asien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Phrygien und Pamphylien, Agypten und an den Enden der Libyen bei Kyrene, und Auslander von Rom,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Juden und Judengenossen, Kreter und Araber: wir horen sie mit unsern Zungen die grolien Taten Gottes reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Sie entsetzten sich alle und wurden irre und sprachen einer zu dem andern: Was will das werden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Die andern aber hatten\'s ihren Spott und sprachen: Sie sind voll sulien Weins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Da trat Petrus auf mit den Elfen, hub auf seine Stimme und redete zu ihnen: Ihr Juden, liebe Manner, und alle, die ihr zu Jerusalem wohnet, das sei euch kundgetan, und lasset meine Worte zu euren Ohren eingehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Denn diese sind nicht trunken, wie ihrwahnet, sintemal es ist die dritte Stunde am Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Sondern das ist\'s, das durch den Propheten Joel zuvor gesagt ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Und es soil geschehen in den letzten Tagen, spricht Gott, ich will ausgielien von meinem Geist auf alles Fleisch; und eure Sohne und eure Tochter sollen weissagen, und eure Junglinge sollen Gesichte sehen, und eure Altesten sollen Traume haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Und auf meine Knechte und auf meine Magde will ich in denselbigen Tagen von meinem Geist ausgielien, und sie sollen weissagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Und ich will Wunder tun oben im Himmel und Zeichen unten auf Erden: Blut und Feuer und Rauchdampf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Die Sonne soil sich verkehren in Finsternis und der Mond in Blut, ehe denn der grolie und offenbarliche Tag des Herrn kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Und soil geschehen, wer den Namen des Herrn anrufen wird, soil selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Ihr Manner von Israel, horet diese Worte: Jesum von Nazareth, den Mann von Gott, unter euch mit Taten und Wundern und Zeichen beweiset, welche Gott durch ihn tat unter euch (wie denn auch ihr selbst wisset),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'denselbigen (nachdem er aus bedachtem Rat und Vorsehung Gottes ergeben war) habt ihr genommen durch die Hande der Ungerechten und ihn angeheftet und erwurget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Den hat Gott auferwecket und aufgeloset die Schmerzen des Todes, nachdem es unmdglich war, daß er sollte von ihm gehalten werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Denn David spricht von, ihm: Ich habe den Herrn allezeit vorgesetzet vor mein Angesicht; denn er ist an meiner Rechten, auf daß ich nicht beweget werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Darum ist mein Herz frohlich, und meine Zunge freuet sich; denn auch mein Fleisch wird ruhen in der Hoffnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Denn du wirst meine Seele nicht in der Holle lassen, auch nicht zugeben, daß dein Heiliger die Verwesung sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hast mir kundgetan die Wege des Lebens; du wirst mich erfullen mit Freuden vor deinem Angesichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Ihr Manner, liebe Bruder, lasset mich frei reden zu euch von dem Erzvater David: Er ist gestorben und begraben, und sein Grab ist bei uns bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Als er nun ein Prophet war und wulite, daß ihm Gott verheitien hatte mit einem Eide; daß die Frucht seiner Lenden sollte auf seinem Stuhl sitzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'hat er\'s zuvor gesehen und geredet von der Auferstehung Christi, daß seine Seele nicht in der Holle gelassen ist, und sein Fleisch die Verwesung nicht gesehen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Diesen Jesum hat Gott auferwecket; des sind wir alle Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Nun er durch die Rechte Gottes erhohet ist und empfangen hat die Verheiliung des Heiligen Geistes vom Vater, hat er ausgegossen dies, was ihr sehet und horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Denn David ist nicht gen FHimmel gefahren. Er spricht aber: Der Herr hat gesagt zu meinem Herrn: Setze dich zu meiner Rechten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'bis daß ich deine Feinde lege zum Schemel deiner Fülie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'So wisse nun das ganze Haus Israel gewili, daß Gott diesen Jesum, den ihr gekreuzigt habt, zu einem Herrn und Christus gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Da sie aber das horeten, ging\'s ihnen durchs Herz, und sprachen zu Petrus und zu den andern Aposteln: Ihr Manner, liebe Bruder, was sollen wir tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Petrus sprach zu ihnen: Tut Bulie, und lasse sich ein jeglicher taufen auf den Namen Jesu Christi zur Vergebung der Sunden, so werdet ihr empfangen die Gabe des Heiligen Geistes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Denn euer und eurer Kinder ist diese Verheiliung und aller, die feme sind, welche Gott, unser Herr, herzurufen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Auch mit viel andern Worten bezeugete er und ermahnete und sprach: Lasset euch helfen von diesen unartigen Leuten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Die nun sein Wort gerne annahmen, liefien sich taufen, und wurden hinzugetan an dem Tage bei dreitausend Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Sie blieben aber bestandig in der Apostel Lehre und in der Gemeinschaft und im Brotbrechen und im Gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Es kam auch alle Seelen Furcht an, und geschahen viel Wunder und Zeichen durch die Apostel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Alle aber, die glaubig waren worden, waren beieinander und hielten alle Dinge gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Ihre Guter und Habe verkauften sie und teilten sie aus unter alle, nachdem jedermann not war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Und sie waren taglich und stets beieinander einmutig im Tempel und brachen das Brot hin und her in Hausern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'nahmen die Speise und lobeten Gott mit Freuden und einfaltigem Herzen und hatten Gnade bei dem ganzen Volk. Der Herr aber tat hinzu taglich, die da selig wurden, zu der Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Petrus aber und Johannes gingen miteinander hinauf in den Tempel urn die neunte Stunde, da man pflegte zu beten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Und es war ein Mann, lahm von Mutterleibe, der lieli sich tragen. Und sie setzten ihn taglich vor des Tempels Tur, die da heiliet die schone, daß er bettelte das Almosen von denen, die in den Tempel gingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Da er nun sah Petrus und Johannes, daß sie wollten zum Tempel hineingehen, bat er urn ein Almosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Petrus aber sah ihn an mit Johannes und sprach: Siehe uns an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Und er sah sie an, wartete, daß er etwas von ihnen empfinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Petrus aber sprach: Silber und Gold habe ich nicht; was ich aber habe, das gebe ich dir: im Namen Jesu Christi von Nazareth stehe auf und wandele!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Und griff ihn bei der rechten Hand und richtete ihn auf. Alsobald stunden seine Schenkel und Knochel fest;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'sprang auf, konnte gehen und stehen und ging mit ihnen in den Tempel, wandelte und sprang und lobete Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Und es sah ihn alles Volk wandeln und Gott loben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Sie kannten ihn auch, daß er\'s war, der urn das Almosen gesessen hatte vor der schonen Tur des Tempels; und sie wurden voll Wunderns und Entsetzens uber dem, was ihm widerfahren war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Als aber dieser Lahme, der nun gesund war, sich zu Petrus und Johannes hielt, lief alles Volk zu ihnen in die Halle, die da heiliet Salomos, und wunderten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Als Petrus das sah, antwortete erdem Volk: Ihr Manner von Israel, was wundert ihr euch daruber, Oder was sehet ihr auf uns, als hatten wir diesen wandeln gemacht durch unsere eigene Kraft Oder Verdienst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Der Gott Abrahams und Isaaks und Jakobs, der Gott unserer Vater, hat sein Kind Jesum verklaret, welchen ihr uberantwortet und verleugnet habt vor Pilatus, da derselbe urteilete, ihn loszulassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Ihr aber verleugnetet den Heiligen und Gerechten und batet, daß man euch den Morder schenkte;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'aber den Fursten des Lebens habt ihr getotet. Den hat Gott auferwecket von den Toten; des sind wir Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Und durch den Glauben an seinen Namen hat er an diesem, den ihr sehet und kennet, bestatiget seinen Namen; und der Glaube durch ihn hat diesem gegeben diese Gesundheit vor euren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Nun, liebe Bruder, ich weiß, daß ihr\'s durch Unwissenheit getan habt wie auch eure Obersten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Gott aber, was er durch den Mund alter seiner Propheten zuvor verkundiget hat, wie Christus leiden sollte, hat\'s also erfullet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'So tut nun Buße und bekehret euch, daß eure Sünden vertilget werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'auf daß da komme die Zeit der Erquickung von dem Angesichte des Herrn, wenn, er senden wird den, der euch jetzt zuvor geprediget wird, Jesus Christus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'welcher muß den Himmel einnehmen bis auf die Zeit, da herwiedergebracht werde alles, was Gott geredet hat durch den Mund aller seiner heiligen Propheten von der Welt an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Denn Mose hat gesagt zu den Vatern: Einen Propheten wird euch der Herr, euer Gott, erwecken aus euren Brudern gleichwie mich, den sollt ihr horen in allem, was er zu euch sagen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Und es wird geschehen, welche Seele denselbigen Propheten nicht horen wird, die soil vertilget werden aus dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Und alle Propheten von Samuel an und hernach, wieviel ihrer geredet haben, die haben von diesen Tagen verkundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ihrseid der Propheten und des Bundes Kinder, welchen Gott gemacht hat mit euren Vatern, da er sprach zu Abraham: Durch deinen Samen sollen gesegnet werden alle Volker auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Euch zuvorderst hat Gott auferwecket sein Kind Jesum und hat ihn zu euch gesandt, euch zu segnen, daß ein jeglicher sich bekehre von seiner Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Als sie aber zum Volk redeten, traten zu ihnen die Priester und der Hauptmann des Tempels und die Sadduzaer');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, '(die verdroß, daß sie das Volk lehreten und verkundigten an Jesu die Auferstehung von den Toten)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'und legten die Hande an sie und setzten sie ein bis auf den Morgen; denn es war jetzt Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Aber viele unter denen, die dem Wort zuhoreten, wurden glaubig; und ward die Zahl der Manner bei fünftausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Als es nun kam auf den Morgen, versammelten sich ihre Obersten und Altesten und Schriftgelehrten gen Jerusalem:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Hannas, der Hohepriester, und Kaiphas und Johannes und Alexander, und wieviel ihrer waren vom Hohenpriestergeschlecht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'und stelleten sie vor sich und fragten sie: Aus welcher Gewalt Oder in welchem Namen habt ihr das getan?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Petrus, voll des Heiligen Geistes, sprach zu ihnen: Ihr Obersten des Volks und ihr Altesten von Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'so wir heute werden gerichtet uber dieser Wohltat an dem kranken Menschen, durch welche er ist gesund worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'so sei euch und allem Volk von Israel kundgetan, daß in dem Namen Jesu Christi von Nazareth, welchen ihr gekreuziget habt, den Gott von den Toten auferwecket hat, stehet dieser allhie vor euch gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Das ist der Stein, von euch Bauleuten verworfen, der zum Eckstein worden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Und ist in keinem andern Heil, ist auch kein anderer Name den Menschen gegeben, darinnen wir sollen selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Sie sahen aber an die Freudigkeit des Petrus und Johannes und verwunderten sich; denn sie waren gewiß, daß es ungelehrte Leute und Laien waren, und kannten sie auch wohl, daß sie mit Jesu gewesen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Sie sahen aber den Menschen, der gesund worden war, bei ihnen stehen und hatten nichts dawider zu reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Da hießen sie sie hinausgehen aus dem Rat und handelten miteinander und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Was wollen wir diesen Menschen tun? Denn das Zeichen, durch sie geschehen, ist kund, offenbar alien, die zu Jerusalem wohnen, und wir konnen\'s nicht leugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Aber auf daß es nicht weiter einreiße unter das Volk, lasset uns ernstlich sie bedrauen, daß sie hinfort keinem Menschen von diesem Namen sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Und riefen sie und geboten ihnen, daß sie sich allerdinge nicht horen ließen noch lehreten in dem Namen Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Petrus aber und Johannes antworteten und sprachen zu ihnen: Richtet ihr selbst, ob\'s vor Gott recht sei, daß wir euch mehr gehorchen denn Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Wir konnen\'s ja nicht lassen, daß wir nicht reden sollten, was wir gesehen und gehoret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Aber sie draueten ihnen und ließen sie gehen und fanden nicht, wie sie sie peinigten, urn des Volks willen; denn sie lobeten alle Gott uber dem, was geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Denn der Mensch war fiber vierzig Jahre alt, an welchem dies Zeichen der Gesundheit geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Und als man sie hatte lassen gehen, kamen sie zu den Ihren und verkundigten ihnen, was die Hohenpriester und Altesten zu ihnen gesagt hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Da sie das horeten, huben sie ihre Stimme auf einmutiglich zu Gott und sprachen: Herr, der du bist der Gott, der Himmel und Erde und das Meer und alles, was drinnen ist, gemacht hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'derdu durch den Mund Davids, deines Knechts, gesagt hast: Warum emporen sich die Heiden, und die Volker nehmen vor, was umsonst ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Die Konige der Erde treten zusammen, und die Fürsten versammeln sich zuhaufe wider den Herrn und wider seinen Christ:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'wahrlich ja, sie haben sich versammelt fiber dein heiliges Kind Jesum, welchen du gesalbet hast, Herodes und Pontius Pilatus mit den Heiden und dem Volk Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'zu tun, was deine Hand und dein Rat zuvor bedacht hat, das geschehen sollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Und nun, Herr, siehe an ihr Drauen und gib deinen Knechten, mit aller Freudigkeitzu reden dein Wort,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'und strecke deine Hand aus, daß Gesundheit und Zeichen und Wunder geschehen durch den Namen deines heiligen Kindes Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Und da sie gebetet hatten, bewegte sich die Statte; da sie versammelt waren; und wurden alle des Heiligen Geistes voll und redeten das Wort Gottes mit Freudigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Die Menge aber der Glaubigen war ein Herz und eine Seele; auch keiner sagte von seinen Gittern, daß sie sein waren, sondern es war ihnen alles gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Und mit großer Kraft gaben die Apostel Zeugnis von der Auferstehung des Herrn Jesu, und war große Gnade bei ihnen alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Es war auch keiner unter ihnen, der Mangel hatte; denn wieviel ihrer waren, die da Acker Oder Hauser hatten, verkauften sie dieselben und brachten das Geld des verkauften Guts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'und legten\'s zu der Apostel Fußen; und man gab einem jeglichen; was ihm not war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Joses aber, mit dem Zunamen von den Aposteln genannt Barnabas (das heißt, ein Sohn des Trostes), vom Geschlecht ein Levit aus Zypern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'der hatte einen Acker und verkaufte ihn und brachte das Geld und legte es zu der Apostel Fußen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Ein Mann aber mit Namen Ananias samt seinem Weibe Saphira verkaufte seine Güter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'und entwandte etwas vom Gelde mit Wissen seines Weibes und brachte einen Teil und legte es zu der Apostel Fußen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Petrus aber sprach: Ananias, warum hat der Satan dein Herz erfullet, daß du dem Heiligen Geist logest und entwendetest etwas vom Gelde des Ackers?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Hattest du ihn doch wohl mogen behalten, da du ihn hattest, und da er verkauft war, war es auch in deiner Gewalt. Warum hast du denn solches in deinem Herzen vorgenommen? Du hast nicht Menschen, sondern Gott gelogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Da Ananias aber diese Worte horete, fiel er nieder und gab den Geist auf. Und es kam eine große Furcht über alle, die dies horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Es stunden aber die Junglinge auf und taten ihn beiseit und trugen ihn hinaus und begruben ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Und es begab sich uber eine Weile, bei drei Stunden, kam sein Weib hinein und wußte nicht, was geschehen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Aber Petrus antwortete ihr: Sage mir, habt ihr den Acker so teuer verkauft? Sie sprach: Ja, so teuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Petrus aber sprach zu ihr: Warum seid ihr denn eins worden, zu versuchen den Geist des Herrn? Siehe, die Fitße derer, die deinen Mann begraben haben, sind vor der Tür und werden dich hinaustragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Und alsbald fiel sie zu seinen Fußen und gab den Geist auf. Da kamen die Junglinge und fanden sie tot, trugen sie hinaus und begruben sie bei ihrem Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Und es kam eine große Furcht fiber die ganze Gemeinde und fiber alle, die solches horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Es geschahen aber viel Zeichen und Wunder im Voik durch der Apostel Hande, und waren alle in der Halle Salomos einmutiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Derandern aberdurfte sich keiner zu ihnen tun, sondern das Volk hielt groß von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Es wurden aber je mehr zugetan, die da glaubeten an den Herrn, eine Menge der Manner und der Weiber,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'also daß sie die Kranken auf die Gassen heraustrugen und legeten sie auf Betten und Bahren, auf daß, wenn Petrus kame, sein Schatten ihrer etliche überschattete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Es kamen auch herzu viele von den umliegenden Stadten gen Jerusalem und brachten die Kranken, und die von unsaubern Geistern gepeiniget waren; und wurden alle gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Es stund aber auf der Hohepriester und alle, die mit ihm waren, welches ist die Sekte der Sadduzaer, und wurden voll Eifers');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'und legten die Hande an die Apostel und warfen sie in das gemeine Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Aber der Engel des Herrn tat in der Nacht die Tur des Gefangnisses auf und fuhrete sie heraus und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Gehet hin und tretet auf und redet im Tempel zum Volk alle Worte dieses Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Da sie das gehort hatten, gingen sie frith in den Tempel und lehreten. Der Hohepriester aber kam, und die mit ihm waren, und riefen zusammen den Rat und aile Altesten der Kinder von Israel und sandten hin zum Gefangnis, sie zu holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Die Diener aber kamen dar und fanden sie nicht im Gefangnis, kamen wieder und verkündigten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'und sprachen: Das Gefangnis fanden wir verschlossen mit allem Fleiß und die Hitter außen stehen vor den Türen; aber da wir auftaten, fanden wir niemand drinnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Da diese Rede horeten der Hohepriester und der Hauptmann des Tempels und andere Hohepriester, wurden sie daruber betreten, was doch das werden wollte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Da kam einer dar, der verkitndigte ihnen: Siehe, die Manner, die ihr ins Gefangnis geworfen habt, sind im Tempel, stehen und lehren das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Da ging hin der Hauptmann mit den Dienern und holeten sie, nicht mit Gewalt; denn sie fürchteten sich vor dem Volk, daß sie nicht gesteiniget wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Und als sie sie brachten, stelleten sie sie vor den Rat. Und der Hohepriester fragte sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'und sprach: Haben wir euch nicht mit Ernst geboten, daß ihr nicht sollt lehren in diesem Namen? Und sehet, ihr habt Jerusalem erfullet mit eurer Lehre und wollt dieses Menschen Blut uber uns führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Petrus aber antwortete und die Apostel und sprachen: Man muü Gott mehrgehorchen denn den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Der Gott unserer Vater hat Jesum auferwecket, welchen ihr erwurget habt und an das Holz gehanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Den hat Gott durch seine rechte Hand erhohet zu einem Fursten und Heiland, zu geben Israel Bulie und Vergebung der Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Und wir sind seine Zeugen uber diese Worte und der Heilige Geist, welchen Gott gegeben hat denen, die ihm gehorchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Da sie das horeten, ging\'s ihnen durchs Herz, und dachten sie zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Da stund aber auf im Rat ein Pharisaer mit Namen Gamaliel, ein Schriftgelehrter, wohl gehalten vor allem Volk, und hiefi die Apostel ein wenig hinaustun');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'und sprach zu ihnen: Ihr Manner von Israel, nehmet euer selbst wahr an diesen Menschen, was ihr tun sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Vor diesen Tagen stund auf Theudas und gab vor, erware etwas, und hingen an ihm eine Zahl Manner, bei vierhundert; der ist erschlagen, und alle, die ihm zufielen, sind zerstreuet und zunichte worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Danach stund auf Judas aus Galilaa in den Tagen der Schatzung und machte viel Volks abfallig ihm nach; und der ist auch umkommen, und alle, die ihm zufielen, sind zerstreuet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Und nun sage ich euch: Lasset ab von diesen Menschen und lasset sie fahren! Ist der Rat Oder das Werk aus den Menschen, so wird\'s untergehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'ist\'s aber aus Gott, so konnet ihr\'s nicht dampfen, auf daß ihr nicht erfunden werdet, als die wider Gott streiten wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Da fielen sie ihm zu und riefen den Aposteln, staupeten sie und geboten ihnen, sie sollten nicht reden in dem Namen Jesu, und lielien sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Sie gingen aber frohlich von des Rats Angesicht, daß sie würdig gewesen waren, urn seines Namens willen Schmach zu leiden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'und hdreten nicht auf alle Tage im Tempel und hin und her in Hausern zu lehren und zu predigen das Evangelium von Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'In den Tagen aber, da der Jünger viel wurden, erhub sich ein Murmeln unter den Griechen wider die Hebraer, darum daß ihre Witwen übersehen wurden in der taglichen Handreichung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Da riefen die Zwolfe die Menge der Junger zusammen und sprachen: Es taugt nicht, daß wir das Wort Gottes unterlassen und zu Tische dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Darum, ihr lieben Bruder, sehet unter euch nach sieben Mannern, die ein gut Gerucht haben und voll Heiligen Geistes und Weisheit sind, welche wir bestellen mogen zu dieser Notdurft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Wir aber wollen anhalten am Gebet und am Amt des Worts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Und die Rede gefiel derganzen Menge wohl, und erwahleten Stephanus, einen Mann voll Glaubens und Heiligen Geistes, und Philippus und Prochorus und Nikanor und Timon und Parmenas und Nikolaus, den Judengenossen von Antiochien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Diese stelleten sie vor die Apostel und beteten und legten die Hande auf sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Und das Wort Gottes nahm zu, und die Zahl der Junger ward sehr groli zu Jerusalem. Es wurden auch viel Priesterdem Glauben gehorsam.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stephanus aber, voll Glaubens und Krafte, tat Wunder und grolie Zeichen unter dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Da stunden etliche auf von der Schule, die da heiliet der Libertiner und der Kyrener und der Alexanderer und derer, die aus Zilizien und Asien waren, und befragten sich mit Stephanus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Und sie vermochten nicht, zu widerstehen der Weisheit und dem Geiste, aus welchem er redete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Da richteten sie zu etliche Manner, die sprachen: Wir haben ihn gehoret Lasterworte reden wider Mose und wider Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Und bewegten das Volk und die Altesten und die Schriftgelehrten; und traten herzu und rissen ihn hin und fuhreten ihn vor den Rat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'und stelleten falsche Zeugen dar, die sprachen: Dieser Mensch horet nicht auf, zu reden Lasterworte wider diese heilige Statte und das Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Denn wir haben ihn horen sagen: Jesus von Nazareth wird diese Statte zerstoren und andern die Sitten, die uns Mose gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Und sie sahen auf ihn alle, die im Rat salien, und sahen sein Angesicht wie eines Engels Angesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Da sprach der Hohepriester: Ist dem also?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Er aber sprach: Liebe Bruder und Vater, horet zu! Gott der Herrlichkeit erschien unserm Vater Abraham, da er noch in Mesopotamien war, ehe erwohnete in Haran,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'und er sprach zu ihm: Gehe aus deinem Lande und von deiner Freundschaft und zieh in ein Land, das ich dirzeigen will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Da ging er aus der Chaldaer Lande und wohnete in Haran. Und von dannen, da sein Vater gestorben war, brachte er ihn heruber in dies Land, darinnen ihr nun wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Und gab ihm kein Erbteil drinnen, auch nicht eines Fulies breit; und verhieli ihm, er wollte es geben ihm zu besitzen und seinem Samen nach ihm, da er noch kein Kind hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Aber Gott sprach also: Dein Same wird ein Fremdling sein in einem fremden Lande, und sie werden ihn dienstbar machen und ubel handeln vierhundert Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Und das Volk, dem sie dienen werden, will ich richten, sprach Gott; und danach werden sie ausziehen und mir dienen an dieser Statte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Und gab ihm den Bund der Beschneidung. Und er zeugete Isaak und beschnitt ihn am achten Tag und Isaak den Jakob und Jakob die zwolf Erzvater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Und die Erzvater neideten Joseph und verkauften ihn nach Agypten. Aber Gott war mit ihm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'und errettete ihn aus aller seiner Trubsal und gab ihm Gnade und Weisheit vor dem Konige Pharao in Agypten; der setzte ihn zum Fursten uber Agypten und uber sein ganzes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Es kam aber eine teure Zeit uber das ganze Land Agypten und Kanaan und eine grolie Trubsal, und unsere Vater fanden nicht Futterung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Jakob aber horete, dal L in Agypten Getreide ware, und sandte unsere Vater aus aufs erste Mai.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Und zum andernmal ward Joseph erkannt von seinen Brudern und ward Pharao Josephs Geschlecht offenbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Joseph aber sandte aus und lieli holen seinen Vater Jakob und seine ganze Freundschaft, funfundsiebzig Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Und Jakob zog hinab nach Agypten und starb, er und unsere Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Und sind herubergebracht nach Sichem und gelegt in das Grab, das Abraham gekauft hatte urns Geld von den Kindern Hemors zu Sichem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Da nun sich die Zeit der Verheiliung nahete, die Gott Abraham geschworen hatte, wuchs das Volk und mehrete sich in Agypten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'bis daß ein anderer Konig aufkam, der nichts wulite von Joseph.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Dieser trieb Hinterlist mit unserm Geschlechte und behandelte unsere Vater ubel und schaffte, dad man die jungen Kindlein hinwerfen mudte, dad sie nicht lebendig blieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Zu der Zeit ward Mose geboren und war ein fein Kind vor Gott und ward drei Monden ernahret in seines Vaters Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Als er aber hingeworfen ward, nahm ihn die Tochter Pharaos auf und zog ihn auf zu einem Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Und Mose ward gelehret in aller Weisheit der Agypter und war machtig in Werken und Worten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Da er aber vierzig Jahre alt ward, gedachte er, zu besehen seine Bruder, die Kinder von Israel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'und sah einen Unrecht leiden. Da überhalf er und rachete den, dem Leid geschah, und erschlug den Agypter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Er meinete aber, seine Bruder sollten\'s vernehmen, daß Gott durch seine Hand ihnen Heil gabe; aber sie vernahmen\'s nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Und am andern Tage kam erzu ihnen, da sie sich miteinander haderten, und handelte mit ihnen, daß sie Frieden hatten, und sprach: Liebe Manner, ihr seid Bruder, warum tut einer dem andern Unrecht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Der aber seinem Nachsten Unrecht tat, stieli ihn von sich und sprach: Wer hat dich uber uns gesetzt zum Obersten und Richter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Willst du mich auch toten, wie du gestern den Agypter totetest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Mose aber floh uber dieser Rede und ward ein Fremdling im Lande Midian. Daselbst zeugete erzwei Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Und uber vierzig Jahre erschien ihm in der Wüste auf dem Berge Sinai der Engel des Herm in einer Feuerflamme im Busch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Da es aber Mose sah, wunderte er sich des Gesichtes. Als er aber hinzuging, zu schauen, geschah die Stimme des Herrn zu ihm:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Ich bin der Gott deiner Vater, der Gott Abrahams und der Gott Isaaks und der Gott Jakobs. Mose aber ward zitternd und durfte nicht anschauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Aber der Herr sprach zu ihm: Zieh die Schuhe aus von deinen FQISen; denn die Statte, da du stehest, ist heilig Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Ich habe wohl gesehen das Leiden meines Volks, das in Agypten ist, und habe ihr Seufzen gehoret und bin herabkommen, sie zu erretten. Und nun komm her; ich will dich nach Agypten senden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Diesen Mose, welchen sie verleugneten und sprachen: Wer hat dich zum Obersten und Richter gesetzt? den sandte Gott zu einem Obersten und Erloser durch die Hand des Engels, der ihm erschien im Busch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Dieser fuhrete sie aus und tat Wunder und Zeichen in Agypten, im Roten Meer und in der Wüste vierzig Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Dies ist Mose, der zu den Kindern von Israel gesagt hat: Einen Propheten wird euch der Herr, euer Gott, erwecken aus euren Brudern gleichwie mich, den sollt ihr horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Dieser ist\'s, der in der Gemeinde in der Wüste mit dem Engel war, der mit ihm redete auf dem Berge Sinai und mit unsern Vatern; dieser empfing das lebendige Wort, uns zu geben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'welchem nicht wollten gehorsam werden eure Vater, sondern stiefien ihn von sich und wandten sich urn mit ihren Herzen gen Agypten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'und sprachen zu Aaron: Mache uns Gotter, die vor uns hingehen; denn wir wissen nicht, was diesem Mose, der uns aus dem Lande Agypten geführet hat, widerfahren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Und machten ein Kalb zu der Zeit und opferten dem Gotzen Opfer und freueten sich der Werke ihrer Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Aber Gott wandte sich und gab sie dahin, dafi sie dieneten des Himmels Heer; wie denn geschrieben stehet in dem Buch des Propheten: Habt ihrvom Hause Israel die vierzig Jahre in der Wüste mir auch je Opfer und Vieh geopfert?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Und ihr nahmet die Hütte Molochs an und das Gestirn eures Gottes Remphan, die Bilder, die ihr gemacht hattet, sie anzubeten; und ich will euch wegwerfen jenseit Babyloniens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Es hatten unsere Vater die Hütte des Zeugnisses in der Wüste, wie er ihnen das verordnet hatte, da er zu Mose redete, daß er sie machen sollte nach dem Vorbilde, das ergesehen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'welche unsere Vater auch annahmen und brachten sie mit Josua in das Land, das die Heiden innehatten, welche Gott ausstieß vor dem Angesichte unserer Vater bis zur Zeit Davids.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Der fand Gnade bei Gott und bat, daß er eine Hütte finden mochte dem Gott Jakobs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Salomo aber bauete ihm ein Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Aber der Allerhochste wohnet nicht in Tempeln, die mit Handen gemacht sind, wie der Prophet spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Der Himmel ist mein Stuhl und die Erde meiner Fuße Schemel; was wollt ihr mir denn für ein Haus bauen, spricht der Herr, Oder welches ist die Statte meiner Ruhe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hat nicht meine Hand das alles gemacht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Ihr Halsstarrigen und Unbeschnittenen an Herzen und Ohren, ihrwiderstrebet allezeit dem Heiligen Geist, wie eure Vater, also auch ihr!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Welchen Propheten haben eure Vater nicht verfolget und, sie getotet, die da zuvor verkündigten die Zukunft dieses Gerechten, dessen Verrater und Morder ihr nun worden seid?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Ihr habt das Gesetz empfangen durch der Engel Geschafte und habt\'s nicht gehalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Da sie solches horeten, ging\'s ihnen durchs Herz, und bissen die Zahne zusammen über ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Als er aber voll Heiligen Geistes war, sah er auf gen Himmel und sah die Herrlichkeit Gottes und Jesum stehen zur Rechten Gottes und sprach: Siehe, ich sehe den Himmel often und des Menschen Sohn zur Rechten Gottes stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Sie schrieen aber laut und hielten ihre Ohren zu und sturmeten einmutiglich zu ihm ein, stießen ihn zur Stadt hinaus und steinigten ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Und die Zeugen legten ab ihre Kleider zu den Fußen eines Junglings, der hieß Saulus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Und steinigten Stephanus, der anrief und sprach: Herr Jesu, nimm meinen Geist auf!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Er knieete aber nieder und schrie laut: Herr, behalt ihnen diese Sunde nicht! Und als er das gesagt, entschlief er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saulus aber hatte Wohlgefallen an seinem Tode. Es erhub sich aber zu der Zeit eine große Verfolgung uber die Gemeinde zu Jerusalem; und sie zerstreueten sich alle in die Lander Judaa und Samarien ohne die Apostel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Es bestatteten aber Stephanus gottesfurchtige Manner und hielten eine große Klage über ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saulus aber zerstorete die Gemeinde, ging hin und her in die Hauser und zog hervor Manner und Weiber und überantwortete sie ins Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Die nun zerstreuet waren, gingen urn und predigten das Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Philippus aber kam hinab in eine Stadt in Samarien und predigte ihnen von Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Das Volk aber horete einmütiglich und fleißig zu, was Philippus sagte, und sahen die Zeichen, die er tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Denn die unsaubern Geister fuhren aus vielen Besessenen mitgroßem Geschrei; auch viel Gichtbrüchige und Lahme wurden gesund gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Und ward eine große Freude in derselbigen Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Es war aber ein Mann mit Namen Simon, der zuvor in derselbigen Stadt Zauberei trieb und bezauberte das samaritische Volk und gab vor, er ware etwas Großes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Und sie sahen alle auf ihn, beide, klein und groß, und sprachen: Der ist die Kraft Gottes, die da groß ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Sie sahen aber darum auf ihn, daß er sie lange Zeit mit seiner Zauberei bezaubert hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Da sie aber den Predigten des Philippus glaubten von dem Reich Gottes und von dem Namen Jesu Christi, ließen sich tauten beide, Manner und Weiber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Da ward auch der Simon glaubig und ließ sich taufen und hielt sich zu Philippus. Und als er sah die Zeichen und Taten, die da geschahen, verwunderte er sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Da aber die Apostel horeten zu Jerusalem, daß Samarien das Wort Gottes angenommen hatte, sandten sie zu ihnen Petrus und Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Welche, da sie hinabkamen, beteten sie über sie, daß sie den Heiligen Geist empfingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(Denn erwar noch auf keinen gefallen, sondern waren allein getauft auf den Namen Christi Jesu.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Da legten sie die Hande auf sie, und sie empfingen den Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Da aber Simon sah, daß der Heilige Geist gegeben ward, wenn die Apostel die Hande aufiegten, bot er ihnen Geid an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'und sprach: Gebt mir auch die Macht, daß, so ich jemand die Hande auflege, derselbige den Heiligen Geist empfange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Petrus aber sprach zu ihm: Daß du verdammet werdest mit deinem Gelde, daß du meinest Gottes Gabe werde durch Geld erlanget!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du wirst weder Teil noch Anfall haben an diesem Wort; denn dein Herz ist nicht rechtschaffen vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Darum tue Buße für diese deine Bosheit und bitte Gott, ob dir vergeben werden mochte die Tücke deines Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Denn ich sehe, daß du bist voll bitterer Galle und verknüpft mit Ungerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Da antwortete Simon und sprach: Bittet ihr den Herm für mich, daß der keines über mich komme, davon ihr gesagt habt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Sie aber, da sie bezeuget und geredet hatten das Wort des Herrn, wandten sie wieder um gen Jerusalem und predigten das Evangelium vielen samaritischen Flecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Aber der Engel des Herrn redete zu Philippus und sprach: Stehe auf und gehe gegen Mittag auf die Stralie, die von Jerusalem hinabgehet gen Gaza, die da wuste ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Und er stund auf und ging hin. Und siehe, ein Mann aus Mohrenland, ein Kammerer und Gewaltiger der Konigin Kandaze in Mohrenland, welcherwar uber ihre ganze Schatzkammer, der war kommen gen Jerusalem, anzubeten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'und zog wieder heim und sali auf seinem Wagen und las den Propheten Jesaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Der Geist aber sprach zu Philippus: Gehe hinzu und halte dich zu diesem Wagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Da lief Philippus hinzu und horete, daß er den Propheten Jesaja las, und sprach: Verstehest du auch, was du liesest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Er aber sprach: Wie kann ich, so mich nicht jemand anleitet? Und ermahnete Philippus, daß er auftrate und setzte sich zu ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Der Inhalt aber der Schrift, die er las, war dieser: Er ist wie ein Schaf, zur Schlachtung gefuhret, und still wie ein Lamm vor seinem Scherer; also hat er nicht aufgetan seinen Mund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'In seiner Niedrigkeit ist sein Gericht aufgehoben; wer wird aber seines Lebens Lange ausreden? Denn sein Leben ist von der Erde weggenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Da antwortete der Kammerer Philippus und sprach: Ich bitte dich, von wem redet der Prophet solches, von ihm selber Oder von jemand anders?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Philippus aber tat seinen Mund auf und fing von dieser Schrift an und predigte ihm das Evangelium von Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Und als sie zogen der Stralie nach, kamen sie an ein Wasser. Und der Kammerer sprach: Siehe, da ist Wasser; was hindert\'s, daß ich mich taufen lasse?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Philippus aber sprach: Glaubest du von ganzem Herzen, so mag\'s wohl sein. Er antwortete und sprach: Ich glaube, daß Jesus Christus Gottes Sohn ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Und er hieft den Wagen halten, und stiegen hinab in das Wasser, beide, Philippus und der Kammerer; und er taufete ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Da sie aber heraufstiegen aus dem Wasser, rückte der Geist des Herrn Philippus hinweg, und der Kammerer sah ihn nicht mehr; er zog aber seine Stralie frohlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippus aber ward funden zu Asdod und wandelte umher und predigte alien Stadten das Evangelium, bis daß er kam gen Caseraa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saulus aber schnaubete noch mit Drauen und Morden wider die Junger des Herrn und ging zum Hohenpriester');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'und bat ihn um Briefe gen Damaskus an die Schulen, auf daß, so er etliche dieses Wegs fande, Manner und Weiber, er sie gebunden fuhrete gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Und da er auf dem Wege war und nahe an Damaskus kam, umleuchtete ihn plotzlich ein Licht vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Und er fiel auf die Erde und horete eine Stimme, die sprach zu ihm: Saul, Saul, was verfolgest du mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Er aber sprach: Herr, wer bist du? Der Herr sprach: Ich bin Jesus, den du verfolgest. Es wird dir schwer werden, wider den Stachel lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Und er sprach mit Zittern und Zagen: Herr, was willst du, daß ich tun soil? Der Herr sprach zu ihm: Stehe auf und gehe in die Stadt; da wird man dir sagen, was du tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Die Manner aber, die seine Gefahrten waren, stunden und waren erstarret; denn sie horeten eine Stimme und sahen niemand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saulus aber richtete sich auf von der Erde, und als er seine Augen auftat, sah er niemand. Sie nahmen ihn aber bei der Hand und fuhreten ihn gen Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Und war drei Tage nicht sehend und aft nicht und trank nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Es war aber ein Junger zu Damaskus mit Namen Ananias; zu dem sprach der Herr im Gesichte: Ananias! Und er sprach: Hier bin ich, Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Der Herr sprach zu ihm: Stehe auf und gehe hin in die Gasse, die da heiftet die Richtige, und frage in dem Hause Judas nach Saulus mit Namen von Tarsus; denn siehe, er betet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'und hat gesehen im Gesichte einen Mann mit Namen Ananias zu ihm hineinkommen und die Hand auf ihn legen, daß er wieder sehend werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias aber antwortete: Herr, ich habe von vielen gehoret von diesem Manne, wieviel Ubles er deinen Heiligen getan hat zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Und er hat allhie Macht von den Hohenpriestern; zu binden alle, die deinen Namen anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Der Herr sprach zu ihm: Gehe hin; denn dieser ist mir ein auserwahlt Rustzeug, daß er meinen Namen trage vor den Heiden und vor den Konigen und vor den Kindern von Israel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Ich will ihm zeigen, wieviel er leiden muft um meines Namens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Und Ananias ging hin und kam in das Haus und legte die Hande auf ihn und sprach: Lieber Bruder Saul, der Herr hat mich gesandt (der dir erschienen ist auf dem Wege, da du herkamest), daß du wieder sehend und mit dem Heiligen Geist erfullet werdest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Und alsobald fiel es von seinen Augen wie Schuppen; und ward wieder sehend');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'und stund auf, lieft sich taufen und nahm Speise zu sich und starkete sich. Saulus aber war etliche Tage bei den Jungern zu Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Und alsbald predigte er Christum in den Schulen, daß derselbige Gottes Sohn sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Sie entsetzten sich aber alle, die es horeten, und sprachen: 1st das nicht, der zu Jerusalem verstorete alle, die diesen Namen anrufen, und darum herkommen, daü er sie gebunden führe zu den Hohenpriestern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saulus aber ward immer kraftiger und trieb die Juden in die Enge, die zu Damaskus wohneten, und bewahrete es, daß dieser ist der Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Und nach vielen Tagen hielten die Juden einen Rat zusammen, daß sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Aber es ward Saulus kundgetan, dafi sie ihm nachstelleten. Sie huteten aber Tag und Nacht an den Toren, daß sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Da nahmen ihn die Junger bei der Nacht und taten ihn durch die Mauer und liefien ihn in einem Korbe hinab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Da aber Saulus gen Jerusalem kam, versuchte er, sich zu den Jungern zu tun; und sie furchteten sich alle vor ihm und glaubten nicht, dafi er ein Junger ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabas aber nahm ihn zu sich und fuhrete ihn zu den Aposteln und erzahlete ihnen, wie er auf der Strafte den Herm gesehen, und er mit ihm geredet, und wie er zu Damaskus den Namen Jesu frei geprediget hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Und erwar bei ihnen und ging aus und ein zu Jerusalem und predigte den Namen des Herrn Jesu frei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Er redete auch und befragte sich mit den Griechen; aber sie stelleten ihm nach, daß sie ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Da das die Bruder erfuhren, geleiteten sie ihn gen Casarea und schickten ihn gen Tarsus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'So hatte nun die Gemeinde Frieden durch ganz Judaa und Galilaa und Samarien und bauete sich und wandelte in der Furcht des Flerrn und ward erfullet mit Trost des FHeiligen Geistes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Es geschah aber, da Petrus durchzog allenthalben, daß er auch zu den Heiligen kam, die zu Lydda wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Daselbst fand er einen Mann mit Namen Aneas, acht Jahre lang auf dem Bette gelegen, der war gichtbruchig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Und Petrus sprach zu ihm: Anea, Jesus Christus macht dich gesund; stehe auf und bette dir selber. Und alsobald stund erauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Und es sahen ihn alle, die zu Lydda und zu Saron wohneten; die bekehreten sich zu dem Flerrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Zu Joppe aber war eine Jungerin mit Namen Tabea (welches verdolmetschet heiftt eine Rehe), die war voll guter Werke und Almosen, die sie tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Es begab sich aber zu derselbigen Zeit, daß sie krank ward und starb. Da wuschen sie dieselbige und legten sie auf den Soller.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Nun aber Lydda nahe bei Joppe ist, da die Junger horeten, daß Petrus daselbst war, sandten sie zwei Manner zu ihm und ermahneten ihn, daß er sich\'s nicht liefte verdrieften, zu ihnen zu kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Petrus aber stund auf und kam mit ihnen. Und als er hinkommen war, fuhreten sie ihn hinauf auf den Soller, und traten urn ihn alle Witwen, weineten und zeigten ihm die Rocke und Kleider, welche die Rehe machte, als sie bei ihnen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Und da Petrus sie alle hinausgetrieben hatte, kniete er nieder, betete und wandte sich zu dem Leichnam und sprach: Tabea, stehe auf! Und sie tat ihre Augen auf; und da sie Petrus sah, setzte sie sich wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Er aber gab ihr die Hand und richtete sie auf und rief die Heiligen und die Witwen und stellete sie lebendig dar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Und es ward kund durch ganz Joppe, und viele wurden glaubig an den Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Und es geschah, daß er lange Zeit zu Joppe blieb bei einem Simon, der ein Gerber war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Es war aber ein Mann zu Casarea mit Namen Cornelius, ein Hauptmann von der Schar, die da heiftt die welsche,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'gottselig und gottesfurchtig samt seinem ganzen Hause und gab dem Volk viel Almosen und betete immer zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Der sah in einem Gesichte offenbarlich urn die neunte Stunde am Tage einen Engel Gottes zu ihm eingehen, der sprach zu ihm: Cornelius!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Er aber sah ihn an, erschrak und sprach: Herr, was ist\'s? Er aber sprach zu ihm: Dein Gebet und deine Almosen sind hinaufkommen ins Gedachtnis vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Und nun sende Manner gen Joppe und laft fordern Simon mit dem Zunamen Petrus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'welcher ist zur Herberge bei einem Gerber Simon, des Haus am Meer liegt; der wird dir sagen, was du tun sollst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Und da der Engel, der mit Cornelius redete, hinweggegangen war, rief er zwei seiner Hausknechte und einen gottesfurchtigen Kriegsknecht von denen, die auf ihn warteten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'und erzahlete es ihnen alles und sandte sie gen Joppe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Des andern Tages, da diese auf dem Wege waren und nahe zur Stadt kamen, stieg Petrus hinauf auf den Soller, zu beten, urn die sechste Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Und als er hungrig ward, wollte er essen. Da sie ihm aber zubereiteten, ward er entzuckt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'und sah den Himmel aufgetan und herniederfahren zu ihm ein Gefaft wie ein graft leinen Tuch, an vier Zipfeln gebunden, und ward niedergelassen auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Darinnen waren allerlei vierfuftige Tiere der Erde und wilde Tiere und Gewürm und Vogel des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Und geschah eine Stimme zu ihm: Stehe auf, Petrus, schlachte und ift!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Petrus aber sprach: 0 nein, Herr; denn ich habe noch nie etwas Gemeines Oder Unreines gegessen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Und die Stimme sprach zum andernmal zu ihm: Was Gott gereiniget hat, das mache du nicht gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Und das geschah zu drei Malen; und das Gefaft ward wieder aufgenommen gen Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Als aber Petrus sich in sich selbst bekummerte, was das Gesicht ware, das er gesehen hatte, siehe, da fragten die Manner, von Cornelius gesandt, nach dem Hause Simons und stunden an der Tur,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'riefen und forscheten, ob Simon mit dem Zunamen Petrus allda zur Herberge ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Indem aber Petrus sich besinnet uber dem Gesichte, sprach der Geistzu ihm: Siehe, drei Manner suchen dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Aber stehe auf, steige hinab und zieh mit ihnen und zweifle nichts; denn ich habe sie gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Da stieg Petrus hinab zu den Mannern, die von Cornelius zu ihm gesandt waren, und sprach: Siehe, ich bin\'s, den ihr suchet; was ist die Sache, darum ihr hier seid?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Sie aber sprachen: Cornelius, der Hauptmann, ein frommer und gottesfurchtiger Mann und gutes Geruchts bei dem ganzen Volk der Juden, hat einen Befehl empfangen vom heiligen Engel, daß er dich sollte fordern lassen in sein Haus und Worte von dir horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Da riefersie hinein und herbergete sie. Des andern Tages zog Petrus aus mit ihnen, und etliche Bruder von Joppe gingen mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Und des andern Tages kamen sie gen Casarea. Cornelius aber wartete auf sie und rief zusammen seine Verwandten und Freunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Und als Petrus hineinkam, ging ihm Cornelius entgegen und fiel zu seinen Füften und betete ihn an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Petrus aber richtete ihn auf und sprach: Stehe auf; ich bin auch ein Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Und als er sich mit ihm besprochen hatte, ging er hinein und fand ihrer viel, die zusammenkommen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Und er sprach zu ihnen: Ihr wisset, wie es ein ungewohnet Ding ist einem judischen Mann, sich zu tun Oder zu kommen zu einem Fremdling; aber Gott hat mir gezeiget, keinen Menschen gemein Oder unrein zu heiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Darum habe ich mich nicht geweigert zu kommen, als ich bin hergefordert. So frage ich euch nun, warum ihr mich habt lassen fordern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Cornelius sprach: Ich habe vier Tage gefastet bis an diese Stunde, und urn die neunte Stunde betete ich in meinem Hause. Und siehe, da trat ein Mann vor mich in einem hellen Kleide');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'und sprach: Cornelius, dein Gebet ist erhoret, und deiner Almosen ist gedacht worden vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'So sende nun gen Joppe und laft herrufen einen Simon mit dem Zunamen Petrus, welcher ist zur Herberge in dem Hause des Gerbers Simon an dem Meer; der wird dir, wenn er kommt, sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Da sandte ich von Stund\' an zu dir. Und du hast wohl getan, daß du kommen bist. Nun sind wir alle hier gegenwartig vor Gott, zu horen alles, was dir von Gott befohlen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Petrus aber tat seinen Mund auf und sprach: Nun erfahre ich mit der Wahrheit, daß Gott die Person nicht ansiehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'sondern in allerlei Volk, wer ihn furchtet und recht tut, der ist ihm angenehm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Ihr wisset wohl von der Predigt, die Gott zu den Kindern Israel gesandt hat, und verkundigen lassen den Frieden durch Jesum Christum (welcher ist ein Herr fiber alles),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'die durchs ganze judische Land geschehen ist und angefangen in Galilaa nach der Taufe, die Johannes predigte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'wie Gott denselbigen Jesum von Nazareth gesalbet hat mit dem Heiligen Geiste und Kraft; der umhergezogen ist und hat wohlgetan und gesund gemacht alle, die vom Teufel überwaltiget waren; denn Gott war mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Und wir sind Zeugen alles des, was er getan hat im judischen Lande und zu Jerusalem. Den haben sie getotet und an ein Holz gehanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Denselbigen hat Gott auferwecket am dritten Tage und ihn lassen offenbar werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'nicht allem Volk, sondern uns, den vorerwahlten Zeugen von Gott, die wir mit ihm gegessen und getrunken haben, nachdem er auferstanden ist von den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Und er hat uns geboten, zu predigen dem Volk und zu zeugen, daß er ist verordnet von Gott ein Richter der Lebendigen und der Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Von diesem zeugen alle Propheten, daß durch seinen Namen alle, die an ihn glauben, Vergebung der Sünden empfangen sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Da Petrus noch diese Worte redete, fiel der Heilige Geist auf alle, die dem Wort zuhoreten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Und die Glaubigen aus der Beschneidung, die mit Petrus kommen waren, entsetzten sich, daß auch auf die Heiden die Gabe des Heiligen Geistes ausgegossen ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Denn sie horeten, daß sie mit Zungen redeten und Gott hoch preiseten. Da antwortete Petrus:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Mag auch jemand das Wasserwehren, daß diese nicht getaufet werden, die den Heiligen Geist empfangen haben gleichwie auch wir?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Und befahl, sie zu taufen in dem Namen des Herm. Da baten sie ihn, daß er etliche Tage dabliebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Es kam aber vor die Apostel und Bruder, die in dem judischen Lande waren, daß auch die Heiden hatten Gottes Wort angenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Und da Petrus hinaufkam gen Jerusalem, zankten mit ihm, die aus der Beschneidung waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'und sprachen: Du bist eingegangen zu den Mannern, die Vorhaut haben, und hast mit ihnen gegessen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Petrus aber hub an und erzahlte es ihnen nacheinander her und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Ich war in der Stadt Joppe im Gebet und war entzückt und sah ein Gesicht, namlich ein Gefaß herniederfahren wie ein groß leinen Tuch mit vier Zipfeln und niedergelassen vom Himmel, und kam bis zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Darein sah ich und ward gewahr und sah vierfußige Tiere der Erde und wilde Tiere und Gewürm und Vogel des Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Ich horete aber eine Stimme, die sprach zu mir: Stehe auf, Petrus, schlachte und iß!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Ich aber sprach: 0 nein, Herr; denn es ist nie kein Gemeines noch Unreines in meinen Mund gegangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Aber die Stimme antwortete mir zum andernmal vom Himmel: Was Gott gereiniget hat, das mache du nicht gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Dasgeschah aberdreimal; und ward alles wieder hinauf gen Himmel gezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Und siehe, von Stund\' an stunden drei Manner vor dem Hause, darinnen ich war, gesandt von Casarea zu mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Der Geist aber sprach zu mir, ich sollte mit ihnen gehen und nicht zweifeln. Es kamen aber mit mir diese sechs Bruder, und wir gingen in des Mannes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Und er verkundigte uns, wie ergesehen hatte einen Engel in seinem Hause stehen, derzu ihm gesprochen hatte: Sende Manner gen Joppe und laß fordern den Simon mit dem Zunamen Petrus;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'derwird dir Wortesagen, dadurch du selig werdest und dein ganzes Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Indem aber ich anting zu reden, fiel der Heilige Geist auf sie gleichwie auf uns am ersten Anfang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Da dachte ich an das Wort des Herrn, als er sagte: Johannes hat mit Wasser getauft; ihr aber sollt mit dem Heiligen Geist getauft werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'So nun Gott ihnen gleiche Gaben gegeben hat wie auch uns, die da glauben an den Herrn Jesus Christus, werwar ich, daß ich konnte Gottwehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Da sie das horeten, schwiegen sie stille und lobeten Gott und sprachen: So hat Gott auch den Heiden Buße gegeben zum Leben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Die aber zerstreuet waren in der Trubsal, so sich uber Stephanus erhub, gingen umher bis gen Phonizien und Zypern und Antiochien und redeten das Wort zu niemand denn allein zu den Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Es waren aber etliche unter ihnen, Manner von Zypern und Kyrene, die kamen gen Antiochien und redeten auch zu den Griechen und predigten das Evangelium vom Herrn Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Und die Hand des Herrn war mit ihnen, und eine große Zahl ward glaubig und bekehrete sich zu dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Es kam aber diese Rede von ihnen vor die Ohren der Gemeinde zu Jerusalem; und sie sandten Barnabas, daß er hinginge bis gen Antiochien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'welcher, da er hinkommen war und sah die Gnade Gottes, ward er froh und ermahnete sie alle, daß sie mit festem Herzen an dem Herrn bleiben woliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Denn er war ein frommer Mann, voll Heiligen Geistes und Glaubens. Und es ward ein groß Volk dem Herrn zugetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Barnabas aber zog aus gen Tarsus, Saulus wieder zu suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Und da er ihn fand, führete er ihn gen Antiochien. Und sie blieben bei der Gemeinde ein ganzes Jahr und lehreten viel Volks; daher die Junger am ersten zu Antiochien Christen genannt wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'In denselbigen Tagen kamen Propheten von Jerusalem gen Antiochien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Und einer unter ihnen, mit Namen Agabus, stund auf und deutete durch den Geist eine große Teurung, die da kommen sollte uber den ganzen Kreis der Erde, welche geschah unter dem Kaiser Claudius.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Aber unter den Jungern beschloß ein jeglicher, nachdem ervermochte, zu senden eine Handreichung den Brudern, die in Judaa wohneten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'wie sie denn auch taten und schickten\'s zu den Altesten durch die Hand Barnabas und Saulus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Urn dieselbige Zeit legte der Konig Herodes die Hande an etliche von der Gemeinde, sie zu peinigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Er totete aber Jakobus, den Bruder des Johannes, mit dem Schwert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Und da er sah, daß es den Juden gefiel, fuhr er fort und fing Petrus auch. Es waren aber eben die Tage der süßen Brote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Da er ihn nun griff, legte er ihn ins Gefangnis und uberantwortete ihn vier Vierteilen Kriegsknechten, ihn zu bewahren, und gedachte, ihn nach Ostern dem Volkvorzustellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Und Petrus ward zwar im Gefangnis gehalten; aber die Gemeinde betete ohne Aufhoren fur ihn zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Und da ihn Herodes wollte vorstellen, in derselbigen Nacht schlief Petrus zwischen zwei Kriegsknechten, gebunden mit zwo Ketten, und die Hüter vor der Tur huteten das Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Und siehe, der Engel des Herrn kam daher, und ein Licht schien in dem Gemach; und schlug Petrus an die Seite und weckte ihn auf und sprach: Stehe behende auf! Und die Ketten fielen ihm von seinen Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Und der Engel sprach zu ihm: Gurte dich und tu deine Schuhe an! Und er tat also. Und er sprach zu ihm: Wirf deinen Mantel urn dich und folge mir nach!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Und er ging hinaus und folgte ihm und wußte nicht, daß ihm wahrhaftig solches geschahe durch den Engel, sondern es deuchte ihn, ersahe ein Gesicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Sie gingen aberdurch die erste und andere Hut und kamen zu der eisernen Tur, welche zur Stadt tub ret; die tat sich ihnen von selber auf. Und traten hinaus und gingen hin eine Gasse lang; und also bald schied der Engel von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Und da Petrus zu sich selber kam, sprach er: Nun weili ich wahrhaftig, daß der Herr seinen Engel gesandt hat und mich errettet aus der Hand des Herodes und von allem Warten des judischen Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Und alser sich besann, kam er vor das Haus Marias, der Mutter des Johannes, der mit dem Zunamen Markus hieli, da viele beieinanderwaren und beteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Als aber Petrus an die Tur klopfete des Tores, trat hervor eine Magd, zu horchen, mit Namen Rhode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Und als sie des Petrus Stimme erkannte, tat sie das Tor nicht auf vor Freuden, lief aber hinein und verkundigte es ihnen, Petrus stunde vor dem Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Sie abersprachen zu ihr: Du bist unsinnig. Sie aber bestand darauf, es ware also. Sie sprachen: Es istsein Engel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Petrus aber klopfete weiter an. Da sie aber auftaten, sahen sie ihn und entsetzten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Er aber winkete ihnen mit der Hand, zu schweigen, und erzahlte ihnen, wie ihn der Herr hatte aus dem Gefangnis gefuhret, und sprach: Verkundiget dies Jakobus und den Brudern. Und ging hinaus und zog an einen andern Ort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Da es aber Tag ward, ward nicht eine kleine Bekummernis unter den Kriegsknechten, wie es doch mit Petrus gegangen ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herodes aber, da er ihn forderte und nicht fand, liefi er die Hüter rechtfertigen und hieli sie wegfuhren und zog von Judaa hinab gen Casarea und hielt allda sein Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Denn ergedachte, wider die von Tyrus und Sidon zu kriegen. Sie aber kamen einmutiglich zu ihm und uberredeten des Konigs Kammerer, Blastus, und baten urn Frieden, darum daß ihre Lande sich nahren muliten von des Konigs Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Aber auf einen bestimmten Tag tat Herodes das konigliche Kleid an, setzte sich auf den Richterstuhl und tat eine Rede zu ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Das Volk aber rief zu: Das ist Gottes Stimme und nicht eines Menschen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Alsbald schlug ihn der Engel des Herrn, darum daß er die Ehre nicht Gott gab, und ward gefressen von den Wurmern und gab den Geist auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Das Wort Gottes aber wuchs und mehrete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas aber und Saulus kamen wieder gen Jerusalem und uberantworteten die Handreichung und nahmen mit sich Johannes mit dem Zunamen Markus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Es waren aber zu Antiochien in der Gemeinde Propheten und Lehrer, namlich Barnabas und Simon, genannt Niger, und Lucius von Kyrene und Manahen, mit Herodes dem Vierfursten erzogen, und Saulus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Da sie aber dem Herrn dieneten und fasteten, sprach der Heilige Geist: Sondert miraus Barnabas und Saulus zu dem Werk, dazu ich sie berufen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Da fasteten sie und beteten und legten die Hande auf sie und lielien sie gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Und wie sie ausgesandt waren vom Heiligen Geist, kamen sie gen Seleucia, und von dannen schifften sie gen Zypern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Und da sie in die Stadt Salamis kamen, verkundigten sie das Wort Gottes in der Juden Schulen; sie hatten aber auch Johannes zum Diener.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Und da sie die Insel durchzogen bis zu der Stadt Paphos, fanden sie einen Zauberer und falschen Propheten, einen Juden, der hieli Bar - Jehu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Der war bei Sergius Paulus dem Landvogt, einem verstandigen Mann. Derselbige rief zu sich Barnabas und Saulus und begehrete, das Wort Gottes zu horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Da stund ihnen wider der Zauberer Elymas (denn also wird sein Name gedeutet) und trachtete, daß er den Landvogt vom Glauben wendete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saulus aber, der auch Paulus heilit, voll Heiligen Geistes, sah ihn an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'und sprach: O du Kind des Teufels, voll aller List und aller Schalkheit und Feind aller Gerechtigkeit! Du horest nicht auf, abzuwenden die rechten Wege des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Und nun siehe, die Hand des Herrn kommt uber dich, und sollst blind sein und die Sonne eine Zeitlang nicht sehen. Und von Stund\' an fiel auf ihn Dunkelheit und Finsternis; und ging umher und suchte Handleiter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Als der Landvogt die Geschichte sah, glaubte er und verwunderte sich der Lehre des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Da aber Paulus, und die urn ihn waren, von Paphos schifften, kamen sie gen Perge im Lande Pamphylien. Johannes aberwich von ihnen und zog wieder gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Sie aberzogen durch von Perge und kamen gen Antiochien im Lande Pisidien und gingen in die Schule am Sabbattage und setzten sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Nach der Lektion aber des Gesetzes und der Propheten sandten die Obersten der Schule zu ihnen und lielien ihnen sagen: Liebe Bruder, wollt ihr etwas reden und das Volk ermahnen, so saget an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Da stund Paulus auf und winkete mit der Hand und sprach: Ihr Manner von Israel, und die ihr Gott furchtet, horet zu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Der Gott dieses Volks hat erwahlet unsere Vater und erhohet das Volk, da sie Fremdlinge waren im Lande Agypten, und mit einem hohen Arm fuhrete er sie aus demselbigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Und vierzig Jahre lang duldete er ihre Weise in der Wüste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Und vertilgete sieben Volker in dem Lande Kanaan und teilete unter sie nach dem Los jener Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Danach gab er ihnen Richter vierhundertundfünfzig Jahre lang, bis auf den Propheten Samuel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Und von da an baten sie um einen Konig. Und Gott gab ihnen Saul, den Sohn des Kis, einen Mann aus dem Geschlechte Benjamin, vierzig Jahre lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Und da er denselbigen wegtat, richtete er auf uber sie David zum Konige, von welchem er zeugete: Ich habe funden David, den Sohn Jesses, einen Mann nach meinem Herzen, der soil tun alien meinen Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Aus dieses Samen hat Gott, wie er verheiften hat, gezeugt Jesum dem Volk Israel zum Heiland,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'als denn Johannes zuvor dem Volk Israel predigte die Taufe der Bufte, ehe denn er anfing.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Als aber Johannes seinen Lauf erfüllete, sprach er: Ich bin nicht der, dafür ihr mich haltet; aber siehe, er kommt nach mir, des ich nicht wert bin, daß ich ihm die Schuhe seiner Fufie auflose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Ihr Manner, Hebe Brüder, ihr Kinder des Geschlechtes Abraham, und die unter euch Gott fürchten, euch ist das Wort dieses Heils gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Denn die zu Jerusalem wohnen, und ihre Obersten, dieweil sie diesen nicht kenneten noch die Stimme der Propheten (welche auf alle Sabbate gelesen werden), haben sie dieselben mit ihrem Urteilen erfullet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Und wiewohl sie keine Ursache des Todes an ihm fanden, baten sie doch Pilatus ihn zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Und als sie alles vollendet hatten, was von ihm geschrieben ist, nahmen sie ihn von dem Holz und legten ihn in ein Grab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Aber Gott hat ihn auferweckt von den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Und er ist erschienen viele Tage denen, die mit ihm hinauf von Galilaa gen Jerusalem gegangen waren, welche sind seine Zeugen an das Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Und wirauch verkundigen euch die Verheifiung, die zu unsern Vatern geschehen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'daß dieselbige Gott uns, ihren Kindern, erfullet hat in dem, daß er Jesum auferwecket hat, wie denn im andern Psalm geschrieben stehet: Du bist mein Sohn; heute habe ich dich gezeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Daft er ihn aber hat von den Toten auferweckt, daß er fort nicht mehr soil verwesen, spricht er also: Ich will euch die Gnade, David verheiften, treulich halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Darum spricht er auch am andern Ort: Du wirst es nicht zugeben, daß dein Heiliger die Verwesung sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Denn David, da erzu seiner Zeit gedienet hatte dem Willen Gottes, ist er entschlafen und zu seinen Vatern getan und hat die Verwesung gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Den aber Gott auferweckt hat, der hat die Verwesung nicht gesehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'So sei es nun euch kund, liebe Brüder, daß euch verkundiget wird Vergebung der Sünden durch diesen und von dem allem, durch welches ihr nicht konntet im Gesetz Mose\'s gerecht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Wer aber an diesen glaubet, der ist gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Sehet nun zu, daß nicht über euch komme, was in den Propheten gesagt ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Sehet, ihr Verachter, und verwundert euch und werdet zunichte; denn ich tue ein Werk zu euren Zeiten, welches ihr nicht glauben werdet, so es euch jemand erzahlen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Da aber die Juden aus der Schule gingen, baten die Heiden, daß sie zwischen Sabbats ihnen die Worte sagten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Und als die Gemeinde der Schule voneinander ging, folgeten Paulus und Barnabas nach viel Juden und gottesfurchtige Judengenossen. Sie aber sagten ihnen und vermahneten sie, daß sie bleiben sollten in der Gnade Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Am folgenden Sabbat aber kam zusammen fast die ganze Stadt, das Wort Gottes zu horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Da aber die Juden das Volk sahen wurden sie voll Neides und widersprachen dem, was von Paulus gesagt ward, widersprachen und lasterten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paulus aber und Barnabas sprachen frei offentlich: Euch muftte zuerst das Wort Gottes gesagt werden; nun ihr es aber von euch stoftet und achtet euch selbst nicht wert des ewigen Lebens, siehe, so wenden wir uns zu den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Denn also hat uns der Herr geboten: Ich habe dich den Heiden zum Licht gesetzt, daß du das Heil seiest bis an das Ende der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Da es aber die Heiden horeten, wurden sie froh und preiseten das Wort des Herm, und wurden glaubig, wieviel ihrer zum ewigen Leben verordnet waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Und das Wort des Herm ward ausgebreitet durch die ganze Gegend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Aber die Juden bewegten die andachtigen und ehrbaren Weiber und der Stadt Obersten und erweckten eine Verfolgung über Paulus und Barnabas und stieften sie zu ihren Grenzen hinaus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Sie aber schüttelten den Staub von ihren Füften über sie und kamen gen Ikonien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Die Jünger aber wurden voll Freuden und Heiligen Geistes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Es geschah aber zu Ikonien, daß sie zusammenkamen und predigten in der Juden Schule, also daß eine grofte Menge der Juden und der Griechen glaubig ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Die unglaubigen Juden aber erweckten und entrüsteten die Seelen der Heiden wider die Brüder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'So hatten sie nun ihr Wesen daselbst eine lange Zeit und lehreten frei im Herm, welcher bezeugete das Wort seiner Gnade und lieft Zeichen und Wunder geschehen durch ihre Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Die Menge aber der Stadt spaltete sich; etliche hielten\'s mit den Juden und etliche mit den Aposteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Da sich aber ein Sturm erhub der Heiden und der Juden und ihrer Obersten, sie zu schmahen und zu steinigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'wurden sie des inne und entflohen in die Stadte des Landes Lykaonien, gen Lystra und Derbe und in die Gegend umher');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'und predigten daselbst das Evangelium.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Und eswarein Mann zu Lystra, der muftte sitzen; denn er hatte bose Füfte und war lahm von Mutterleibe, der noch nie gewandelt hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Der horete Paulus reden. Und als er ihn ansah und merkte, daß er glaubte, ihm mochte geholfen werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'sprach er mit lauter Stimme: Stehe aufrichtig aufdeine Fufte! Und er sprang auf und wandelte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Da aber das Volk sah, was Paulus getan hatte, huben sie ihre Stimme auf und sprachen auf lykaonisch: Die Gottersind den Menschen gleich worden und zu uns herniederkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Und nenneten Barnabas Jupiter und Paulus Mercurius, dieweil er das Wort fuhrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Der Priester aber Jupiters, der vor ihrer Stadt war, brachte Ochsen und Kranze vor das Tor und wollte opfern samt dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Da das die Apostel, Barnabas und Paulus, horeten, zerrissen sie ihre Kleider und sprangen unter das Volk, schrieen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'und sprachen: Ihr Manner, was machetihr da? Wir sind auch sterbliche Menschen gleichwie ihr und predigen euch das Evangelium, daß ihreuch bekehren sollt von diesen falschen zu dem lebendigen Gott, welcher gemacht hat Himmel und Erde und das Meer und alles, was drinnen ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'der in vergangenen Zeiten hat lassen alle FHeiden wandeln ihre eigenen Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Und zwar hat er sich selbst nicht unbezeuget gelassen, hat uns viel Gutes getan und vom Himmel Regen und fruchtbare Zeiten gegeben, unsere Herzen erfullet mit Speise und Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Und da sie das sagten, stilleten sie kaum das Volk, daß sie ihnen nicht opferten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Es kamen aber dahin Juden von Antiochien und Ikonien und uberredeten das Volk und steinigten Paulus und schleiften ihn zur Stadt hinaus, meineten, erware gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Da ihn aber die Junger umringeten, stund er auf und ging in die Stadt. Und auf den andern Tag ging er aus mit Barnabas gen Derbe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Und predigten derselbigen Stadt das Evangelium und unterweiseten ihrer viel und zogen wieder gen Lystra und Ikonien und Antiochien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'starketen die Seelen der Junger und ermahneten sie, daß sie im Glauben blieben, und daß wir durch viel Trubsal mussen in das Reich Gottes gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Und sie ordneten ihnen hin und her Alteste in den Gemeinden, beteten und fasteten und befahlen sie dem Herrn, an den sie glaubig worden waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Und zogen durch Pisidien und kamen nach Pamphylien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Und redeten das Wort zu Perge und zogen hinab gen Attalien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Und von dannen schifften sie gen Antiochien, von dannen sie verordnet waren durch die Gnade Gottes zu dem Werk, das sie hatten ausgerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Da sie aber hinkamen, versammelten sie die Gemeinde und verkundigten, wie viel Gott mit ihnen getan hatte, und wie er den Heiden hatte die Tur des Glaubens aufgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Sie hatten aber ihr Wesen allda nicht eine kleine Zeit bei den Jungern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Und etliche kamen herab von Judaa und lehreten die Bruder: Wo ihr euch nicht beschneiden lasset nach der Weise Mose\'s, so konnet ihr nicht selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Da sich nun ein Aufruhr erhub, und Paulus und Barnabas nicht einen geringen Zank mit ihnen hatten, ordneten sie, daß Paulus und Barnabas und etliche andere aus ihnen hinaufzogen gen Jerusalem zu den Aposteln und Altesten urn dieser Frage willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Und sie wurden von der Gemeinde geleitet und zogen durch Phonizien und Samarien und erzahleten den Wandel der Heiden und machten grofte Freude alien Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Da sie aber hinkamen gen Jerusalem wurden sie empfangen von der Gemeinde und von den Aposteln und von den Altesten. Und sie verkundigten, wieviel Gott mit ihnen getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Da traten auf etliche von der Pharisaer Sekte, die glaubig waren worden und sprachen: Man muft sie beschneiden und gebieten, zu halten das Gesetz Mose\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Aber die Apostel und die Altesten kamen zusammen, diese Rede zu besehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Da man sich aber lange gezanket hatte, stund Petrus auf und sprach zu ihnen: Ihr Manner, liebe Bruder, ihr wisset, daß Gott lang vor dieser Zeit unter uns erwahlet hat, daß durch meinen Mund die Heiden das Wort des Evangeliums horeten und glaubeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Und Gott, der Herzenskündiger, zeugete uber sie und gab ihnen den Heiligen Geist gleichwie auch uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Und machte keinen Unterschied zwischen uns und ihnen und reinigte ihre Herzen durch den Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Was versucht ihr denn nun Gott mit Auflegen des Jochs auf der Junger Halse welches weder unsere Vater noch wir haben mogen tragen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Sondern wir glauben, durch die Gnade des Herrn Jesu Christi selig zu werden gleicherweise wie auch sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Da schwieg die ganze Menge stille und horete zu Paulus und Barnabas, die da erzahleten, wie grofte Zeichen und Wunder Gott durch sie getan hatte unter den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Danach, als, sie geschwiegen hatten, antwortete Jakobus und sprach: Ihr Manner, liebe Bruder, horet mirzu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon hat erzahlet, wie aufs erste Gott heimgesucht hat und angenommen ein Volk aus den Heiden zu seinem Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Und damit stimmen der Propheten Reden, als geschrieben stehet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Danach will ich wiederkommen und will wieder bauen die Hutte Davids, die zerfallen ist, und ihre Lucken will ich wieder bauen und will sie aufrichten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'auf daß, was ubrig ist von Menschen, nach dem Herrn frage, dazu alle Heiden, uber welche mein Name genennet ist, spricht der Herr, der das alles tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Gott sind alle seine Werke bewulit von der Welt her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Darum beschlielie ich, daß man denen, so aus den Heiden zu Gott sich bekehren; nicht Unruhe mache,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'sondern schreibe ihnen, daß sie sich enthalten von Unsauberkeit der Abgotter und von Hurerei und vom Erstickten und vom Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Denn Mose hat von langen Zeiten her in alien Stadten, die ihn predigen, und wird alle Sabbattage in den Schulen gelesen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Und es deuchte gut die Apostel und Altesten samt der ganzen Gemeinde, aus ihnen Manner zu erwahlen und zu senden gen Antiochien mit Paulus und Barnabas, namlich Judas, mit dem Zunamen Barsabas, und Silas, welche Manner Lehrer waren unter den Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Und sie gaben Schrift in ihre Hand also: Wir, die Apostel und Altesten und Bruder, wunschen Heil den Brudern aus den Heiden, die zu Antiochien und Syrien und Zilizien sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Dieweil wir gehoret haben, daß etliche von den Unsern sind ausgegangen und haben euch mit Lehren irregemacht und eure Seelen zerruttet und sagen, ihr sollt euch beschneiden lassen und das Gesetz halten welchen wir nichts befohlen haben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'hat es uns gut gedeucht, einmutiglich versammelt, Manner zu erwahlen und zu euch zu senden mit unsern Liebsten; Barnabas und Paulus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'welche Menschen ihre Seelen dargegeben haben fur den Namen unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'So haben wir gesandt Judas und Silas, welche auch mit Worten dasselbige verkundigen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Denn es gefallt dem Heiligen Geiste und uns, euch keine Beschwerung mehr aufzulegen denn nur diese notigen Stücke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'daß ihr euch enthaltet vom Gotzenopfer und vom Blut und vom Erstickten und von Hurerei, von welchen, so ihr euch enthaltet, tut ihr recht. Gehabt euch wohl!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Da diese abgefertigt waren, kamen sie gen Antiochien und versammelten die Menge und überantworteten den Brief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Da sie den lasen, wurden sie des Trostes froh.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas aber und Silas, die auch Propheten waren, ermahneten die Bruder mitvielen Reden und starketen sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Und da sie verzogen eine Zeitlang, wurden sie von den Brudern mit Frieden abgefertiget zu den Aposteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Es gefiel aber Silas, daß er dabliebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paulus aber und Barnabas hatten ihr Wesen zu Antiochien, lehreten und predigten des Herrn Wort samt vielen andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Nach etlichen Tagen aber sprach Paulus zu Barnabas: Lali uns wiederum ziehen und unsere Bruder besehen durch alle Stadte, in welchen wir des Herrn Wort verkundiget haben, wie sie sich halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas aber gab Rat, daß sie mit sich nahmen Johannes, mit dem Zunamen Markus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Paulus aber achtete es bülig, daß sie nicht mit sich nahmen einen solchen, der von ihnen gewichen war in Pamphylien und war nicht mit ihnen gezogen zu dem Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Und sie kamen scharf aneinander, also daß sie voneinander zogen, und Barnabas zu sich nahm Markus und schiffte nach Zypern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paulus aber wahlte Silas und zog hin, der Gnade Gottes befohlen von den Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Er zog aber durch Syrien und Zilizien und starkte die Gemeinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Er kam aber gen Derbe und Lystra; und siehe, ein Junger war daselbst mit Namen Timotheus, eines judischen Weibes Sohn, die war glaubig, aber eines griechischen Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Der hatte ein gut Gerucht bei den Brudern unter den Lystranern und zu Ikonien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Diesen wollte Paulus lassen mit sich ziehen und nahm und beschnitt ihn urn der Juden willen, die an demselbigen Ort waren; denn sie wuliten alle, daß sein Vater war ein Grieche gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Als sie aber durch die Stadte zogen, überantworteten sie ihnen, zu halten den Spruch, welcher von den Aposteln und den Altesten zu Jerusalem beschlossen war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Da wurden die Gemeinden im Glauben befestiget und nahmen zu an der Zahl taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Da sie aber durch Phrygien und das Land Galatien zogen, ward ihnen gewehret von dem Heiligen Geist, zu reden das Wort in Asien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Als sie aber kamen an Mysien, versuchten sie, durch Bithynien zu reisen; und der Geist lieli es ihnen nicht zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Da sie aber an Mysien voruberzogen, kamen sie hinab gen Troas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Und Paulus erschien ein Gesicht bei der Nacht; das war ein Mann aus Mazedonien, der stund und bat ihn und sprach: Komm hernieder nach Mazedonien und hilf uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Alseraberdas Gesicht gesehen hatte, da trachteten wir alsobald zu reisen nach Mazedonien, gewili, daß uns der Herr dahin berufen hatte, ihnen das Evangelium zu predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Da fuhren wir aus von Troas, und stracks Laufs kamen wir gen Samothrazien, des andern Tages gen Neapolis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'und von dannen gen Philippi, welches ist die Hauptstadt des Landes Mazedonien und eine Freistadt. Wir hatten aber in dieser Stadt unser Wesen etliche Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Am Tage des Sabbats gingen wir hinaus vor die Stadt an das Wasser, da man pflegte zu beten, und setzten uns und redeten zu den Weibern, die da zusammenkamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Und ein gottesfurchtig Weib mit Namen Lydia, eine Purpurkramerin aus der Stadt der Thyatirer, horete zu; welcher tat der Herr das Herz auf, daß sie darauf achthatte, was von Paulus geredet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Als sie aber und ihr Hausgetauftward, ermahnete sie uns und sprach: So ihr mich achtet, daß ich glaubig bin an den Herrn, so kommet in mein Haus und bleibet allda. Und sie zwang uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Esgeschah aber, da wirzu dem Gebet gingen, daß eine Magd uns begegnete, die hatte einen Wahrsagergeist und trug ihren Herren viel Genieli zu mit Wahrsagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Dieselbige folgte allenthalben Paulus und uns nach, schrie und sprach: Diese Menschen sind Knechte Gottes, des Allerhochsten, die euch den Weg der Seligkeit verkundigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Solches tat sie manchen Tag. Paulus aber tat das weh, und wandte sich urn und sprach zu dem Geist: Ich gebiete dir in dem Namen Jesu Christi, daß du von ihr ausfahrest! Und er fuhr aus zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Da aber ihre Herren sahen, daß die Hoffnung ihres Genielies war ausgefahren, nahmen sie Paulus und Silas, zogen sie auf den Markt vor die Obersten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'und fuhreten sie zu den Hauptleuten und sprachen: Diese Menschen machen unsere Stadt irre und sind Juden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'und verkundigen eine Weise, welche uns nicht ziemet anzunehmen noch zu tun, weil wir Rdmer sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Und das Volk ward erregt wider sie. Und die Hauptleute lielien ihnen die Kleider abreilien und hielien sie staupen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Und da sie sie wohl gestaupet hatten, warfen sie sie ins Gefangnis und geboten dem Kerkermeister, daß er sie wohl bewahrete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Der nahm solch Gebot an und warf sie in das innerste Gefangnis und legte ihre Füfie in den Stock.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Urn die Mitternacht aber beteten Paulus und Silas und lobeten Gott. Und es horeten sie die Gefangenen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Schnell aber ward ein groties Erdbeben, also daß sich bewegeten die Grundfesten des Gefangnisses. Und von Stund\' an wurden alle Turen aufgetan und aller Bande los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Als aber der Kerkermeister aus dem Schlafe fuhr und sah die Turen des Gefangnisses aufgetan, zog er das Schwert aus und wollte sich selbst erwurgen; denn er meinete, die Gefangenen waren entflohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Paulus aber rief laut und sprach: Tue dir nichts Ubles; denn wir sind alle hier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Er forderte aber ein Licht und sprang hinein und ward zitternd und fiel Paulus und Silas zu den Fülien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'und führete sie heraus und sprach: Liebe Herren, was soil ich tun, dati ich selig werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Sie sprachen:. Glaube an den Herrn Jesum Christum, so wirst du und dein Haus selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Und sie sagten ihm das Wort des Herrn und alien, die in seinem Hause waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Und er nahm sie zu sich in derselbigen Stunde der Nacht und wusch ihnen die Striemen ab; und er lieli sich taufen und alle die Seinen alsobald.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Und führete sie in sein Haus und setzte ihnen einen Tisch und freuete sich mit seinem ganzen Hause, daß er an Gott glaubig worden war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Und da es Tag ward, sandten die Hauptleute Stadtdiener und sprachen: Lali die Menschen gehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Und der Kerkermeister verkundigte diese Rede Paulus: Die Hauptleute haben hergesandt, daß ihr los sein sollt. Nun ziehet aus und gehet hin mit Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Paulus aber sprach zu ihnen: Sie haben uns ohne Recht und Urteil offentlich gestaupet, die wir doch Rdmer sind, und in das Gefangnis geworfen und sollten uns nun heimlich ausstolien? Nicht also, sondern lasset sie selbst kommen und uns hinausfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Die Stadtdiener verkündigten diese Worte den Hauptleuten; und sie furchteten sich, da sie horeten, daß sie Rdmer waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'und kamen und ermahneten sie und fuhreten sie heraus und baten sie, daß sie auszogen aus der Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Da gingen sie aus dem Gefangnis und gingen zu der Lydia. Und da sie die Brüder gesehen hatten und getrostet, zogen sie aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Da sie aber durch Amphipolis und Apollonia reiseten, kamen sie gen Thessalonich. Da war eine Judenschule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Nachdem nun Paulus gewohnet war ging erzu ihnen hinein und redete mit ihnen an drei Sabbaten aus der Schrift,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'tat sie ihnen auf und legte es ihnen vor, daß Christus mulite leiden und auferstehen von den Toten, und daß, dieser Jesus, den ich (sprach er) euch verkundige, ist der Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Und etliche unter ihnen fielen ihm zu und geselleten sich zu Paulus und Silas, auch der gottesfurchtigen Griechen eine große Menge, dazu der vornehmsten Weiber nicht wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Aber die halsstarrigen Juden neideten und nahmen zu sich etliche boshaftige Manner Pobelvolks, machten eine Rotte und richteten einen Aufruhr in der Stadt an und traten vor das Haus Jasons und suchten sie zu fuhren unter das gemeine Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Da sie aber sie nicht fanden, schleiften sie den Jason und etliche Brüder vor die Obersten der Stadt und schrieen: Diese, die den ganzen Weltkreis erregen, sind auch herkommen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'die herberget Jason; und diese alle handeln wider des Kaisers Gebot, sagen, ein anderer sei der Konig, namlich Jesus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Sie bewegeten aber das Volk und die Obersten der Stadt, die solches horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Und da sie Verantwortung von Jason und den andern empfangen hatten, lieüen sie sie los.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Die Brüder aber fertigten alsobald ab bei der Nacht Paulus und Silas gen Beroa. Da sie dahinkamen, gingen sie in die Judenschule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Denn sie waren die edelsten unter denen zu Thessalonich; die nahmen das Wort auf ganz williglich und forscheten taglich in der Schrift, ob sich\'s also verhielte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'So glaubten nun viel aus ihnen, auch der griechischen ehrbaren Weiber und Manner nicht wenig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Als aber die Juden zu Thessalonich erfuhren, daß auch zu Beroa das Wort Gottes von Paulus verkundiget würde, kamen sie und bewegten auch aildadas Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Aber da fertigten die Brüder Paulus alsobald ab, da(S er ging bis an das Meer; Silas aber und Timotheus blieben da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Die aber Paulus geleiteten, fuhreten ihn bis gen Athen. Und als sie Befehl empfingen an den Silas und Timotheus, daß sie aufs schierste zu ihm kamen, zogen sie hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Da aber Paulus ihrer zu Athen wartete, ergrimmete sein Geist in ihm, da er sah die Stadt so gar abgottisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Und er redete zwarzu den Juden und Gottesfurchtigen in der Schule, auch auf dem Markt alle Tage zu denen, die sich herzufanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Etliche aber der Epikurer und Stoiker Philosophen zankten mit ihm; und etliche sprachen: Was will dieser Lotterbube sagen? Etliche aber: Es siehet, als wollte er neue Gotter verkündigen. Das machte, er hatte das Evangelium von Jesu und von der Auferstehung ihnen verkundigt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Sie nahmen ihn aber und fuhreten ihn auf den Richtplatz und sprachen: Konnen wirauch erfahren, was das fur eine neue Lehre sei, die du lehrest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Denn du bringest etwas Neues vor unsere Ohren; so wollten wir gerne wissen, was das sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Die Athener aber alle, auch die Auslander und Gaste, waren gerichtet auf nichts anderes, denn etwas Neues zu sagen Oder zu horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paulus aber stund mitten auf dem Richtplatz und sprach: Ihr Manner von Athen, ich sehe euch, daß ihr in alien Stricken allzu aberglaubisch seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Ich bin herdurchgegangen und habe gesehen eure Gottesdienste und fand einen Altar, darauf war geschrieben: Dem unbekannten Gott. Nun verkündige ich euch denselbigen, dem ihr unwissend Gottesdienst tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Gott, der die Welt gemacht hat und alles, was drinnen ist, sintemal erein Herr ist Himmels und der Erde, wohnet er nicht in Tempeln mit Handen gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Sein wird auch nicht von Menschenhanden gepfleget, als der jemandes bedürfe, so er selber jedermann Leben und Odem allenthalben gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Und hat gemacht, daß von einem Blut aller Menschen Geschlechter auf dem ganzen Erdboden wohnen, und hat Ziel gesetzt, zuvor versehen, wie lang und weit sie wohnen sollen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'daß sie den Herrn suchen sollten, ob sie doch ihn fühlen und finden mochten. Und zwar er ist nicht feme von einem jeglichen unter uns;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'denn in ihm leben, weben und sind wir, als auch etliche Poeten bei euch gesagt haben: Wir sind seines Geschlechts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'So wir denn gottliches Geschlechts sind, sollen wir nicht meinen, die Gottheit sei gleich den guldenen, silbernen und steinernen Bildern, durch menschliche Gedanken gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Und zwar hat Gott die Zeit der Unwissenheit übersehen; nun aber gebeut er alien Menschen an alien Enden, Buße zu tun,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'darum daß er einen Tag gesetzt hat, auf welchen er richten will den Kreis des Erdbodens mit Gerechtigkeit durch einen Mann, in welchem er’s beschlossen hat, und jedermann vorhalt den Glauben, nachdem er ihn hat von den Toten auferweckt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Da sie horeten die Auferstehung der Toten, da hatten’s etliche ihren Spott; etliche aber sprachen: Wir wollen dich davon weiter horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Also ging Paulus von ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Etliche Manner aber hingen ihm an und wurden glaubig, unter welchen war Dionysius, einer aus dem Rat, und ein Weib mit Namen Damaris und andere mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Danach schied Paulus von Athen und kam gen Korinth');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'und fand einen Juden mit Namen Aquila, der Geburt aus Pontus, welcher war neulich aus Welschland kommen, samtseinem Weibe Priscilla, darum daß der Kaiser Claudius geboten hatte alien Juden, zu weichen aus Rom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Zu denselbigen ging erein; und dieweil er gleiches Handwerks war, blieb er bei ihnen und arbeitete; sie waren aber des Handwerks Teppichmacher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Und er lehrete in der Schule an alien Sabbaten und beredete beide, Juden und Griechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Da aber Silas und Timotheus aus Mazedonien kamen, drang Paulus der Geist, zu bezeugen den Juden Jesum, daß er der Christus sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Da sie aber widerstrebten und lasterten, schuttelte er die Kleider aus und sprach zu ihnen: Euer Blut sei uber euer Haupt! Ich gehe von nun an rein zu den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Und machte sich von dannen und kam in ein Haus eines mit Namen Just, der gottesfurchtig war, und desselbigen Haus war zunachst an der Schule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Crispus aber, der Oberste der Schule, glaubte an den Herrn mit seinem ganzen Hause; und viel Korinther, die zuhoreten, wurden glaubig und lielien sich tauten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Es sprach aber der Herr durch ein Gesicht in der Nacht zu Paulus: Furchte dich nicht, sondern rede und schweige nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Denn ich bin mit dir und niemand soil sich unterstehen, dirzu schaden; denn ich habe ein grofi Volk in dieser Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Er sali aber daselbst ein Jahr und sechs Monden und lehrete sie das Wort Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Da aber Gallion Landvogt war in Achaja, emporten sich die Juden einmutiglich wider Paulus und fuhreten ihn vor den Richterstuhl');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'und sprachen: Dieser uberredet die Leute, Gott zu dienen, dem Gesetze zuwider.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Da aber Paulus wollte den Mund auftun, sprach Gallion zu den Juden: Wenn es ein Frevel Oder Schalkheit ware, liebe Juden, so horete ich euch billig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'weil es aber eine Frage ist von der Lehre und von den Worten und von dem Gesetze unter euch, so sehet ihr selber zu; ich gedenke daruber nicht Richter zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Und trieb sie von dem Richterstuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Da ergriffen alle Griechen Sostenes, den Obersten der Schule, und schlugen ihn vor dem Richterstuhl; und Gallion nahm sich\'s nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Paulus aber blieb noch lange daselbst. Danach machte erseinen Abschied mit den Brüdem und wollte nach Syrien schiffen und mit ihm Priscilla und Aquila. Und er beschor sein Haupt zu Kenchrea; denn er hatte ein Gelubde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Und kam hinab gen Ephesus und liefi sie daselbst. Er aber ging in die Schule und redete mit den Juden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Sie baten ihn aber, dafi er langere Zeit bei ihnen bliebe. Und erwilligte nicht ein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'sondern machte seinen Abschied mit ihnen und sprach: Ich muli allerdinge das kunftige Fest zu Jerusalem halten; will\'s Gott, so will ich wieder zu euch kommen. Und fuhrweg von Ephesus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Und kam gen Casarea und ging hinauf und grülite die Gemeinde und zog hinab gen Antiochien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Und verzog etliche Zeit und reisete aus und durchwandelte nacheinander das galatische Land und Phrygien und starkte alle Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Es kam aber gen Ephesus ein Jude mit Namen Apollos, der Geburt von Alexandrien, ein beredter Mann und machtig in der Schrift.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Dieser war unterweiset den Weg des Herrn und redete mit brunstigem Geist und lehrete mit Fleili von dem Herrn und wulite allein von der Taufe des Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Dieser ting an, frei zu predigen in der Schule. Da ihn aber Aquila und Priscilla horeten, nahmen sie ihn zu sich und legten ihm den Weg Gottes noch fleüüger aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Da er aber wollte nach Achaja reisen, schrieben die Bruder und vermahneten die Junger, daß sie ihn aufnahmen. Und als erdahinkommen war, half er viel denen, die glaubig waren worden durch die Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Denn er uberwand die Juden bestandiglich und erweisete offentlich durch die Schrift, daß Jesus der Christus sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Es geschah aber, da Apollos zu Korinth war, daß Paulus durchwandelte die obern Lander und kam gen Ephesus und fand etliche Junger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Zu denen sprach er: Habt ihr den Heiligen Geist empfangen, da ihr glaubig worden seid? Sie sprachen zu ihm: Wir haben auch nie gehort, ob ein Heiliger Geist sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Und er sprach zu ihnen: Worauf seid ihr denn getauft? Sie sprachen: Auf die Taufe des Johannes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paulus aber sprach: Johannes hat getauft mit der Taufe der Buüe und sagte dem Volk, daü sie sollten glauben an den, der nach ihm kommen sollte, das ist, an Jesum, daü der Christus sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Da sie das horeten, lielien sie sich taufen auf den Namen des Herrn Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Und da Paulus die Hande auf sie legete, kam der Heilige Geist auf sie und redeten mit Zungen und weissageten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Und aller der Manner waren bei zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Er ging aber in die Schule und predigte frei drei Monden lang, lehrete und beredete sie von dem Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Da aber etliche verstockt waren und nicht glaubten und ubel redeten von dem Wege vor der Menge, wich er von ihnen und sonderte ab die Junger und redete taglich in der Schule eines, der hiefi Tyrannus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Und dasselbige geschah zwei Jahre lang, also daß alle, die in Asien wohneten, das Wort des Herrn Jesu horeten, beide, Juden und Griechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Und Gottwirkete nicht geringe Taten durch die Hande des Paulus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'also daß sie auch von seiner Haut die Schweilituchlein und Koller über die Kranken hielten, und die Seuchen von ihnen wichen, und die bosen Geister von ihnen ausfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Es unterwanden sich aber etliche der umlaufenden Juden, die da Beschworer waren, den Namen des Herrn Jesu zu nennen uber die da bose Geister hatten, und sprachen: Wir beschworen euch bei Jesu, den Paulus prediget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Es waren ihrer aber sieben Sohne eines Juden, Skeva, des Hohenpriesters, die solches taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Aber der bose Geist antwortete und sprach: Jesum kenne ich wohl, und Paulus weili ich wohl; wer seid ihr aber?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Und der Mensch, in dem der bose Geist war, sprang auf sie und ward ihrer machtig und warf sie unter sich, also daß sie nackend und verwundet aus demselbigen Hause entflohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Dasselbige aber ward kund alien, die zu Ephesus wohneten, beide, Juden und Griechen; und fiel eine Furcht uber sie alle, und der Name des Herrn Jesu ward hochgelobet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Es kamen auch viel derer, die glaubig waren worden, und bekannten und verkundigten, was sie ausgerichtet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Viele aber, die da vorwitzige Kunst getrieben hatten, brachten die Bucher zusammen und verbrannten sie offentlich und uberrechneten, was sie wert waren, und fanden des Geldes fünfzigtausend Groschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Also machtig wuchs das Wort des Herrn und nahm uberhand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Da das ausgerichtet war, setzte sich Paulus vor im Geiste, durch Mazedonien und Achaja zu reisen und gen Jerusalem zu wandeln, und sprach: Nach dem, wenn ich daselbst gewesen bin, muli ich auch Rom sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Und sandte zwei, die ihm dieneten, Timotheus und Erastus, nach Mazedonien; eraber verzog eine Weile in Asien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Es erhub sich aber urn dieselbige Zeit eine nicht kleine Bewegung uber diesem Wege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Denn einer mit Namen Demetrius, ein Goldschmied, der machte der Diana silberne Tempel und wandte denen vom Handwerk nicht geringen Gewinst zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Dieselbigen versammelte er und die Beiarbeiter desselbigen Handwerks und sprach: Liebe Manner, ihr wisset, daß wir grolien Zugang von diesem Handel haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Und ihr sehet und horet, daß nicht allein zu Ephesus, sondern auch fast in ganz Asien dieser Paulus viel Volks abfallig macht, uberredet und spricht: Es sind nicht Gotter, welche von Handen gemacht sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Aber es will nicht allein unserm Handel dahin geraten, daß er nichts gelte, sondern auch der Tempel der grolien Gottin Diana wird fur nichts geachtet, und wird dazu ihre Majestat untergehen, welcher doch ganz Asien und der Weltkreis Gottesdienst erzeiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Als sie das horeten, wurden sie voll Zorns, schrieen und sprachen: Groli ist die Diana der Epheser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Und die ganze Stadtward voll Getummels. Sie sturmeten aber einmutiglich zu dem Schauplatz und ergriffen Gajus und Aristarchus aus Mazedonien, des Paulus Gefahrten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Da aber Paulus wollte unter das Volk gehen, lielien\'s ihm die Junger nicht zu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Auch etliche der Obersten in Asien, die des Paulus gute Freunde waren, sandten zu ihm und ermahneten ihn, daß ersich nicht begabe auf den Schauplatz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Etliche schrieen so, etliche ein anderes, und war die Gemeinde irre, und die meisten wuliten nicht, warum sie zusammenkommen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Etliche aber vom Volk zogen Alexander hervor, da ihn die Juden hervorstielien. Alexander aber winkete mit der Hand und wollte sich vor dem Volk verantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Da sie aber innewurden, daß er ein Jude war, erhub sich eine Stimme von alien und schrieen bei zwo Stunden: Groli ist die Diana der Epheser!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Da aber der Kanzler das Volk gestillet hatte, sprach er: Ihr Manner von Ephesus, welcher Mensch ist, der nicht wisse, daß die Stadt Ephesus sei eine Pflegerin der grolien Gottin Diana und des himmlischen Bildes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Weil nun das unwidersprechlich ist, so sollt ihr ja stille sein und nichts Unbedachtiges handeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Ihr habt diese Menschen hergefuhret, die weder Kirchenrauber noch Lasterer eurer Gottin sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Hat aber Demetrius, und die mit ihm sind vom Handwerk, an jemand einen Anspruch, so halt man Gericht, und sind Landvogte da; lasset sie sich untereinander verklagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Wollet ihr aber etwas anderes handeln, so mag man es ausrichten in einer ordentlichen Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Denn wir stehen in der Gefahr, daß wir urn diese heutige Emporung verklaget mochten werden, und doch keine Sache vorhanden ist, damit wir uns solches Aufruhrs entschuldigen mochten. Und da er solches gesagt, lieli erdie Gemeinde gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Da nun die Emporung aufgehoret, rief Paulus die Junger zu sich und segnete sie und ging aus, zu reisen nach Mazedonien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Und da er dieselbigen Lander durchzog und sie ermahnet hatte mit vielen Worten, kam er nach Griechenland und verzog allda drei Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Da aber ihm die Juden nachstelleten, als er nach Syrien wollte fahren, ward er zu Rat, wieder umzuwenden durch Mazedonien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Es zogen aber mit ihm bis nach Asien Sopater von Beroa, von Thessalonich aber Aristarchus und Sekundus und Gajus von Derbe und Timotheus, aus Asien aber Tychikus und Trophimus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Diese gingen voran und harreten unser zu Troas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Wir aber schiffeten nach den Ostertagen von Philippi bis an den funften Tag und kamen zu ihnen gen Troas und hatten da unser Wesen sieben Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Auf einen Sabbat aber, da die Junger zusammenkamen, das Brot zu brechen, predigte ihnen Paulus und wollte des andern Tages ausreisen und verzog das Wort bis zu Mitternacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Und es waren viel Fackeln auf dem Soller, da sie versammelt waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Es safi aber ein Jüngling mit Namen Eutychus in einem Fenster und sank in einen tiefen Schlaf, dieweil Paulus so lange redete, und ward vom Schlaf uberwogen und fiel hinunter vom dritten Soller und ward tot aufgehoben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Paulus aber ging hinab und fiel auf ihn, umfing ihn und sprach: Machet kein Getümmel; denn seine Seele ist in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Da ging er hinauf und brach das Brot und aß und redete viel mit ihnen, bis der Tag anbrach; und also zog er aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Sie brachten aber den Knaben lebendig und wurden nicht wenig getrostet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Wir aber zogen voran auf dem Schiff und fuhren gen Assos und wollten daselbst Paulus zu uns nehmen; denn er hatte es also befohlen, und er wollte zu Fuße gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Als er nun zu uns schlug zu Assos, nahmen wir ihn zu uns und kamen gen Mitylene.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Und von dannen schifften wir und kamen des andern Tages hin gen Chios; und des folgenden Tages stießen wir an Samos und blieben in Trogyllion; und des nachsten Tages kamen wir gen Milet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Denn Paulus hatte beschlossen, an Ephesus voruberzuschiffen, daß er nicht mußte in Asien Zeit zubringen; denn ereilete, auf den Pfingsttag zu Jerusalem zu sein, so es ihm moglich ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Aber von Milet sandte er gen Ephesus und ließ fordern die Altesten von der Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Als aber die zu ihm kamen, sprach erzu ihnen. Ihr wisset von dem ersten Tage an, da ich bin nach Asien kommen, wie ich allezeit bin bei euch gewesen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'und dem Herm gedienet mit aller Demut und mit viel Tranen und Anfechtungen, die mirsind widerfahren von den Juden, so mir nachstelleten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'wie ich nichts verhalten habe, das da nutzlich ist, daß ich euch nicht verkundiget hatte und euch gelehret offentlich und sonderlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Und habe bezeuget beiden, den Juden und Griechen, die Buße zu Gott und den Glauben an unsern Herm Jesum Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Und nun siehe, ich, im Geist gebunden, fahre hin gen Jerusalem, weiß nicht, was mir daselbst begegnen wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'ohne daß der Heilige Geist in alien Stadten bezeuget und spricht: Bande und Trubsal warten mein daselbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Aber ich achte der keines; ich halte mein Leben auch nicht selbst teuer, auf daß ich vollende meinen Lauf mit Freuden und das Amt, das ich empfangen habe von dem Herm Jesu, zu bezeugen das Evangelium von der Gnade Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Und nun siehe, ich weiß, daß ihr mein Angesicht nicht mehr sehen werdet, alle die, durch welche ich gezogen bin und geprediget habe das Reich Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Darum zeuge ich euch an diesem heutigen Tage, daß ich rein bin von aller Blut;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'denn ich habe euch nichts verhalten, daß ich nicht verkundiget hatte alle den Rat Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'So habt nun acht auf euch selbst und auf die ganze Herde, unter welche euch der Heilige Geist gesetzet hat zu Bischofen, zu weiden die Gemeinde Gottes, welche er durch sein eigen Blut erworben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Denn das weiß ich, daß nach meinem Abschied werden unter euch kommen greuliche Wolfe, die die Herde nicht verschonen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Auch aus euch selbst werden aufstehen Manner, die da verkehrte Lehren reden, die Junger an sich zu ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Darum seid wacker und denket daran, daß ich nicht abgelassen habe drei Jahre, Tag und Nacht einen jeglichen mit Tranen zu vermahnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Und nun, liebe Bruder, ich befehle euch Gott und dem Wort seiner Gnade, der da machtig ist, euch zu erbauen und zu geben das Erbe unter alien, die geheiliget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Ich habe euer keines Silber noch Gold noch Kleid begehrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Denn ihr wisset selber, daß mir diese Hande zu meiner Notdurft und derer, die mit mir gewesen sind, gedienet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Ich habe es euch alles gezeiget, daß man also arbeiten rnüsse und die Schwachen aufnehmen und gedenken an das Wort des Herm Jesu, das er gesagt hat: Geben ist seliger denn Nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Und als er solches gesagt, kniete er nieder und betete mit ihnen alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Es ward aber viel Weinens unter ihnen alien, und fielen Paulus urn den Hals und kusseten ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'am allermeisten betrubt uber dem Wort, das er sagte, sie wurden sein Angesicht nicht mehr sehen. Und geleiteten ihn in das Schiff.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Als es nun geschah, daß wir, von ihnen gewandt, dahinfuhren, kamen wir stracks Laufs gen Kos und am folgenden Tage gen Rhodus und von dannen gen Patara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Und als wir ein Schiff fanden, das nach Phonizien fuhr, traten wir darein und fuhren hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Als wir aber Zypern ansichtig wurden, liefien wir sie zur linken Hand und schifften nach Syrien und kamen an zu Tyrus; denn daselbst sollte das Schiff die Ware niederlegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Und als wir Jünger fanden, blieben wir daselbst sieben Tage. Die sagten Paulus durch den Geist, er sollte nicht hinauf gen Jerusalem ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Und es geschah, da wir die Tage zugebracht hatten, zogen wiraus und wandelten. Und sie geleiteten uns alle mit Weibern und Kindern bis hinaus vor die Stadt und knieten nieder am Ufer und beteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Und als wir einander gesegnet, traten wir ins Schiff; jene aberwandten sich wiederzu dem Ihren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Wir aber vollzogen die Schiffahrt von Tyrus und kamen gen Ptolemais und grufiten die Brüder und blieben einen Tag bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Des andern Tages zogen wir aus, die wir urn Paulus waren, und kamen gen Casarea und gingen in das Haus Philippus, des Evangelisten, der einer von den Sieben war, und blieben bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Derselbige hatte vier Tochter, die waren Jungfrauen und weissageten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Und als wir mehr Tage dablieben, reisete herab ein Prophet aus Judaa mit Namen Agabus und kam zu uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Der nahm den Gürtel des Paulus und band seine Hande und Fufie und sprach: Das saget der Heilige Geist: Den Mann, des der Gürtel ist, werden die Juden also binden zu Jerusalem und überantworten in der Heiden Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Als wir aber solches horeten, baten wirihn, und die desselbigen Orts waren, daß er nicht hinauf gen Jerusalem zoge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Paulus aber antwortete: Was machet ihr, daß ihr weinet und brechet mir mein Herz? Denn ich bin bereit, nicht allein mich binden zu lassen, sondern auch zu sterben zu Jerusalem urn des Namens willen des Herrn Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Da er aber sich nicht uberreden lieft, schwiegen wir und sprachen: Des Herrn Wille geschehe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Und nach denselbigen Tagen entledigten wir uns und zogen hinauf gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Es kamen aber mit uns auch etliche Jünger von Casarea und führeten uns zu einem mit Namen Mnason aus Zypern, der ein alter Jünger war, bei dem wir herbergen sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Da wir nun gen Jerusalem kamen, nahmen uns die Brüder gerne auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Des andern Tages aber ging Paulus mit uns ein zu Jakobus, und kamen die Altesten alle dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Und als er sie gegrüftet hatte, erzahlte ereins nach dem andern, was Gott getan hatte unter den Heiden durch sein Amt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Da sie aber das horeten, lobeten sie den Herrn und sprachen zu ihm: Bruder, du siehest, wieviel tausend Juden sind, die glaubig worden sind, und sind alle Eiferer über dem Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Sie sind aber berichtet worden wider dich, daß du lehrest von Mose abfallen alle Juden, die unter den Heiden sind, und sagest, sie sollen ihre Kinder nicht beschneiden, auch nicht nach desselbigen Weise wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Was ist\'s denn nun? Allerdinge muft die Menge zusammenkommen; denn es wird vor sie kommen, daß du kommen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'So tu nun das, waswirdirsagen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Wir haben vier Manner, die haben ein Gelubde auf sich; dieselbigen nimm zu dir und laft dich reinigen mit ihnen und wage die Kosten an sie, daß sie ihr Haupt bescheren, und alle vernehmen, daß nicht sei, wes sie wider dich berichtet sind, sondern daß du auch einhergehest und hattest das Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Denn den Glaubigen aus den Heiden haben wir geschrieben und beschlossen, daß sie der keines halten sollen, denn nur sich bewahren vor dem Gotzenopfer, vor Blut, vor Ersticktem und vor Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Da nahm Paulus die Manner zu sich und lieft sich des andern Tages samt ihnen reinigen und ging in den Tempel und lieft sich sehen, wie eraushielte die Tage der Reinigung, bis daß fur einen jeglichen unter ihnen das Opfer geopfert ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Als aber die sieben Tage sollten vollendet werden, sahen ihn die Juden aus Asien im Tempel und erregten das ganze Volk, legten die Hande an ihn und schrieen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Ihr Manner von Israel, helft! Dies ist der Mensch, der alle Menschen an alien Enden lehret wider dies Volk, wider das Gesetz und wider diese Statte; auch dazu hat er die Griechen in den Tempel gefuhret und diese heilige Statte gemein gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Denn sie hatten mit ihm in der Stadt Trophimus, den Epheser, gesehen; denselbigen meineten sie, Paulus hatte ihn in den Tempel gefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Und die ganze Stadt ward beweget, und ward ein Zulauf des Volks. Sie griffen aber Paulus und zogen ihn zum Tempel hinaus; und alsbald wurden die Turen zugeschlossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Da sie ihn aber toten wollten, kam das Geschrei hinauf vor den obersten Hauptmann der Schar, wie das ganze Jerusalem sich emporete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Der nahm von Stund\' an die Kriegsknechte und Hauptleute zu sich und lief unter sie. Da sie aber den Hauptmann und die Kriegsknechte sahen, horeten sie auf, Paulus zu schlagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Als aber der Hauptmann nahe herzukam, nahm er ihn an sich und hieft ihn binden mit zwo Ketten und fragte, wer er ware, und was er getan hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Einer aber rief dies, der andere das im Volk. Da er aber nichts Gewisses erfahren konnte urn des Getümmels willen, hieft er ihn in das Lager fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Und als eran die Stufen kam, muftten ihn die Kriegsknechte tragen vor Gewalt des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Denn es folgte viel Volks nach und schrie: Weg mit ihm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Als aber Paulus jetzt zum Lager eingefuhret ward, sprach er zu dem Hauptmann: Dart ich mit dir reden? Er aber sprach: Kannst du Griechisch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Bist du nicht der Agypter, der vor diesen Tagen einen Aufruhr gemacht hat und fuhretest in die Wuste hinaus viertausend Meuchelmorder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paulus aber sprach: Ich bin ein judischer Mann von Tarsus, ein Burger einer namhaftigen Stadt in Zilizien; ich bitte dich, erlaube mir, zu reden zu dem Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Als er aber ihm erlaubte, trat Paulus auf die Stufen und winkte dem Volk mit der Hand. Da nun eine grofte Stille ward, redete erzu ihnen auf ebraisch und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Ihr Manner, Hebe Bruder und Vater, horet mein Verantworten an euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Da sie aber horeten, daß er auf ebraisch zu ihnen redete, wurden sie noch stiller. Und er sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Ich bin ein judischer Mann, geboren zu Tarsus in Zilizien und erzogen in dieser Stadt zu den Füften Gamaliels, gelehret mit allem Fleift im vaterlichen Gesetz und war ein Eiferer urn Gott, gleichwie ihr alle seid heutigestages.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Und habe diesen Weg verfolget bis an den Tod. Ich band sie und uberantwortete sie ins Gefangnis, beide, Mann und Weib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'wie mir auch der Hohepriester und der ganze Haufe der Altesten Zeugnis gibt, von welchen ich Briefe nahm an die Bruder, und reisete gen Damaskus, daß ich, die daselbst waren, gebunden fuhrete gen Jerusalem, daß sie gepeiniget wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Es geschah aber, da ich hinzog und nahe an Damaskus kam, urn den Mittag, umblickte mich schnell ein grofies Licht vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Und ich fiel zum Erdboden und horete eine Stimme, die sprach zu mir: Saul, Saul, was verfolgest du mich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Ich antwortete aber: Herr, wer bist du? Und er sprach zu mir: Ich bin Jesus von Nazareth, den du verfolgest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Die aber mit mir waren, sahen das Licht und erschraken; die Stimme aber des, der mit mir redete, horeten sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Ich sprach aber: Herr, was soil ich tun? Der Herr aber sprach zu mir: Stehe auf und gehe gen Damaskus; da wird man dir sagen von allem, was dir zu tun verordnet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Als ich aber vor Klarheit dieses Lichtes nicht sehen konnte, ward ich bei der Hand geleitet von denen, die mit mir waren, und kam gen Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Es war aber ein gottesfurchtiger Mann nach dem Gesetz, Ananias, der ein gut Gerucht hatte bei alien Juden, die daselbst wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Der kam zu mir und trat vor mich hin und sprach zu mir: Saul, lieber Bruder, siehe auf! Und ich sah ihn an zu derselbigen Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Er aber sprach: Der Gott unserer Vater hat dich verordnet, dafi du seinen Willen erkennen solltest und sehen den Gerechten und horen, die Stimme aus seinem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Denn du wirstsein Zeuge zu alien Menschen sein des, das du gesehen und gehoret hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Und nun, was verziehstdu? Stehe auf und laft dich taufen und abwaschen deine Sünden und rufe an den Namen des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Es geschah aber, da ich wieder gen Jerusalem kam und betete im Tempel, dafi ich entzucket ward und sah ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Da sprach erzu mir: Eile und mache dich behend von Jerusalem hinaus: denn sie werden nicht aufnehmen dein Zeugnis von mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Und ich sprach: Herr, sie wissen selbst, daß ich gefangenlegte und staupte die, so an dich glaubten, in den Schulen hin und wieder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Und da das Blut des Stephanus, deines Zeugen, vergossen ward, stund ich auch daneben und hatte Wohlgefallen an seinem Tode und verwahrete denen die Kleider, die ihn toteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Und er sprach zu mir: Gehe hin; denn ich will dich feme unter die Heiden senden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Sie horeten ihm aber zu bis auf dies Wort und huben ihre Stimme auf und sprachen: Hinweg mit solchem von der Erde; denn es ist nicht billig, daß er leben soil!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Da sie aber schrieen und ihre Kleider abwarfen und den Staub in die Luft warfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'hieft ihn der Hauptmann in das Lager führen und sagte, daß man ihn staupen und ertragen solite, daß er erfuhre urn weicher Ursache willen sie also uber ihn riefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Als er ihn aber mit Riemen anband, sprach Paulus zu dem Unterhauptmann, der dabeistund: Ist\'s auch recht bei euch, einen romischen Menschen ohne Urteil und Recht geifteln?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Da das der Unterhauptmann horete, ging er zu dem Oberhauptmann und verkundigte ihm und sprach: Was willst du machen? Dieser Mensch ist romisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Da kam zu ihm der Oberhauptmann und sprach zu ihm: Sage mir, bist du romisch? Er aber sprach: Ja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Und der Oberhauptmann antwortete: Ich habe dies Burgerrecht mit grofter Summe zuwege gebracht. Paulus aber sprach: Ich aber bin auch romisch geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Da traten alsbald von ihm ab, die ihn befragen sollten. Und der Oberhauptmann furchtete sich, da er vernahm, daß er romisch war, und er ihn gebunden hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Des andern Tages wollte er gewift erkunden, warum er verklaget würde von den Juden, und losete ihn von den Banden und hieft die Hohenpriester und ihren ganzen Rat kommen und fuhrete Paulus hervor und stellete ihn unter sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paulus aber sah den Rat an und sprach: Ihr Manner, liebe Bruder, ich habe mitallem guten Gewissen gewandelt vor Gott bis auf diesen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Der Hohepriester aber, Ananias, befahl denen, die um ihn stunden, daß sie ihn aufs Maul schlugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Da sprach Paulus zu ihm: Gottwird dich schlagen, du getunchte Wand! Sitzest du und richtest mich nach dem Gesetze und heiftest mich schlagen wider das Gesetz?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Die aber umherstunden, sprachen: Schiltst du den Hohenpriester Gottes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Und Paulus sprach: Liebe Bruder, ich wuftte es nicht, daß er der Hohepriester ist. Denn es stehet geschrieben: Dem Obersten deines Volks sollst du nicht fluchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Als aber Paulus wuftte, daß ein Teil Sadduzaer war und der andere Teil Pharisaer, rief er im Rat: Ihr Manner, liebe Bruder ich bin ein Pharisaer und eines Pharisaers Sohn; ich werde angeklagt um der Hoffnung und Auferstehung willen der Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Da er aber das sagte, ward ein Aufruhr unter den Pharisaern und Sadduzaern, und die Menge zerspaltete sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Denn die Sadduzaer sagen, es sei keine Auferstehung noch Engel noch Geist; die Pharisaer aber bekennen\'s beides.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Es ward aber ein graft Geschrei. Und die Schriftgelehrten, der Pharisaer Teil, stunden auf, stritten und sprachen: Wir finden nichts Arges an diesem Menschen; hat aber ein Geist Oder ein Engel mit ihm geredet, so konnen wir mit Gott nicht straiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Da aber der Aufruhr graft ward, besorgtesich der oberste Hauptmann, sie mochten Paulus zerreiften, und hieft das Kriegsvolk hinabgehen und ihn von ihnen reiften und in das Lager fuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Des andern Tages aber in der Nacht stund der Herr bei ihm und sprach: Sei getrost, Paulus; denn wie du von mir zu Jerusalem gezeuget hast, also muftt du auch zu Rom zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Da es aber Tag ward, schlugen sich etliche Juden zusammen und verbanneten sich, weder zu essen noch zu trinken, bis daß sie Paulus getotet hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Ihrer aber waren mehrdenn vierzig, die solchen Bund machten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Die traten zu den Hohenpriestern und Altesten und sprachen: Wir haben uns hart verbannet, nichts zu essen, bis wir Paulus getotet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'So tut nun kund dem Oberhauptmann und dem Rat, daß er ihn morgen zu euch führe, als wolltet ihr ihn besser verhoren; wir aber sind bereit, ihn zu toten, ehe denn er vor euch kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Da aber des Paulus Schwestersohn den Anschlag horete, ging er hin und kam in das Lager und verkündigte es Paulus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Paulus aber rief zu sich einen von den Unterhauptleuten und sprach: Diesen Jungling fuhre hin zu dem Oberhauptmann; denn er hat ihm etwas zu sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Der nahm ihn an und fuhrete ihn zum Oberhauptmann und sprach: Dergebundene Paulus rief mich zu sich und bat mich, diesen Jungling zu dir zu fuhren, der dir etwas zu sagen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Da nahm ihn der Oberhauptmann bei der Hand und wich an einen besondern Ort und fragte ihn: Was ist\'s, das du mir zu sagen hast?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Er aber sprach: Die Juden sind eins worden, dich zu bitten, daß du morgen Paulus vor den Rat bringen lassest, als wollten sie ihn besser verhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Du aber traue ihnen nicht; denn es halten auf ihn mehr denn vierzig Manner unter ihnen, die haben sich verbannet, weder zu essen noch zu trinken, bis sie Paulus toten; und sind jetzt bereit und warten auf deine Verheiftung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Da lieft der Oberhauptmann den Jungling von sich und gebot ihm, daß er niemand sagte, daß er ihm solches eroffnet hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Und rief zu sich zwei Unterhauptleute und sprach: Rüstet zweihundert Kriegsknechte, daß sie gen Casarea ziehen, und siebzig Reiter und zweihundert Schutzen auf die dritte Stunde der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Und die Tiere richtet zu, daß sie Paulus draufsetzen und bringen ihn bewahret zu Felix, dem Landpfleger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Und schrieb einen Brief, der lautete also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claudius Lysias dem teuren Landpfleger Felix Freude zuvor!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Diesen Mann hatten die Juden gegriffen und wollten ihn getotet haben. Da kam ich mit dem Kriegsvolk dazu und rift ihn von ihnen und erfuhr, daß er ein Romer ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Da ich mich aber wollte erkundigen der Ursache, darum sie ihn beschuldigten, fuhrete ich ihn in ihren Rat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Da befand ich, daß er beschuldiget ward von den Fragen ihres Gesetzes, aber keine Anklage hatte, des Todes Oder der Bande wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Und da vor mich kam, daß etliche Juden auf ihn hielten, sandte ich ihn von Stund\' an zu dir und entbot den Klagern auch, daß sie vor dir sagten, was sie wider ihn hatten. Gehab dich wohl!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Die Kriegsknechte, wie ihnen befohlen war, nahmen Paulus und fuhreten ihn bei der Nacht gen Antipatris.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Des andern Tages aber lieften sie die Reiter mit ihm ziehen und wandten wieder um zum Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Da die gen Casarea kamen, überantworteten sie den Brief dem Landpfleger und stelleten ihm Paulus auch dar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Da der Landpfleger den Brief las, fragte er, aus welchem Lande erware. Und da er erkundet, daß er aus Zilizien ware, sprach er:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Ich will dich verhoren, wenn deine Verklager auch da sind. Und hieli ihn verwahren in dem Richthause des Herodes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Uber funf Tage zog hinab der Hohepriester Ananias mit den Altesten und mit dem Redner Tertullus; die erschienen vordem Landpfleger wider Paulus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Da er aber herbeigerufen ward, fing an Tertullus zu verklagen und sprach:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Dali wir in groliem Frieden leben unter dir, und viel redliche Taten diesem Volk widerfahren durch deine Vorsichtigkeit, allerteuerster Felix, das nehmen wir an allewege und allenthalben mit aller Dankbarkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Auf daß ich aber dich nicht zu lange aufhalte, bitte ich dich, du wolltest uns kurzlich horen nach deiner Gelindigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Wir haben diesen Mann funden schadlich, und der Aufruhr erreget alien Juden auf dem ganzen Erdboden, und einen Vornehmsten der Sekte der Nazarener,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'der auch versuchet hat, den Tempel zu entweihen; welchen wir auch griffen und wollten ihn gerichtet haben nach unserm Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Aber Lysias, der Flauptmann, unterkam das und fuhrete ihn mit grolier Gewalt aus unsern Handen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'und hieli seine Verklager zu dir kommen, von welchem du kannst, so du es erforschen willst, dich des alles erkundigen, urn was wir ihn verklagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Die Juden aber redeten auch dazu und sprachen, es verhielte sich also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Paulus aber, da ihm der Landpfleger winkete zu reden, antwortete: Dieweil ich weili, daß du in diesem Volk nun viele Jahre ein Richter bist, will ich unerschrocken mich verantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Denn du kannst erkennen, dafi nicht mehr denn zwolf Tage sind, daß ich bin hinauf gen Jerusalem kommen, anzubeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Auch haben sie mich nicht funden im Tempel mit jemand reden Oder einen Aufruhr machen im Volk noch in den Schulen noch in den Stadten:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Sie konnen mir auch nicht beibringen, des sie mich verklagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Das bekenne ich aber dir; daß ich nach diesem Wege, den sie eine Sekte heilien, diene also dem Gott meiner Vater, daß ich glaube allem, was geschrieben stehet im Gesetz und in den Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Und habe die Hoffnung zu Gott, auf welche auch sie selbst warten, namlich dafi zukunftig sei die Auferstehung der Toten, beide, der Gerechten und Ungerechten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'In demselbigen aber ube ich mich, zu haben ein unverletzt Gewissen allenthalben beide, gegen Gott und die Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Aber nach vielen Jahren bin ich kommen und habe ein Almosen gebracht meinem Volk und Opfer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Darüberfanden sie mich, daß ich mich reinigen lieli im Tempel ohne alien Rumor und Getümmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Das waren aber etliche Juden aus Asien, welche sollten hier sein vor dir und mich verklagen, so sie etwas wider mich hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Oder lafi diese selbst sagen, ob sie etwas Unrechtes an mir funden haben, dieweil ich stehe vor dem Rat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'ohne urn des einigen Worts willen, da ich unter ihnen stund und rief: Uber der Auferstehung der Toten werde ich von euch heute angeklaget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Da aber Felix solches horete; zog er sie auf; denn erwufite fastwohl urn diesen Weg und sprach: Wenn Lysias, der Hauptmann, herabkommt, so will ich mich eures Dinges erkundigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Er befahl aber dem Unterhauptmann, Paulus zu behalten und lassen Ruhe haben, und niemand von den Seinen wehren, ihm zu dienen Oder zu ihm zu kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Nach etlichen Tagen aber kam Felix mit seinem Weibe Drusilla, die eine Judin war, und forderte Paulus und horete ihn von dem Glauben an Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Da aber Paulus redete von der Gerechtigkeit und von der Keuschheit und von dem zukunftigen Gerichte, erschrak Felix und antwortete: Gehe hin auf diesmal; wenn ich gelegene Zeit habe, will ich dich her lassen rufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Er hoffte aber daneben, daß ihm von Paulus sollte Geld gegeben werden, daß er ihn losgabe; darum er ihn auch oft fordern lieli und besprach sich mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Da aber zwei Jahre urn waren, kam Portius Festus an Felix Statt. Felix aber wollte den Juden eine Wohltat erzeigen und lieli Paulus hinter sich gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Da nun Festus ins Land kommen war, zog er liber drei Tage hinauf von Casarea gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Da erschienen vor ihm die Hohenpriester und die Vornehmsten der Juden wider Paulus und ermahneten ihn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'und baten urn Gunst wider ihn, daß er ihn fordern lielie gen Jerusalem, und stelleten ihm nach, daß sie ihn unterwegs umbrachten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Da antwortete Festus, Paulus wurde ja behalten zu Casarea; aber er wurde in kurzem wieder dahin ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Welche nun unter euch (sprach er) konnen, die lasset mit hinabziehen und den Mann Verklagen, so etwas an ihm ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Da er aber bei ihnen mehr denn zehn Tage gewesen war, zog er hinab gen Casarea; und des andern Tages setzte ersich auf den Richterstuhl und hieli Paulus holen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Da derselbige aber vor ihn kam, traten umher die Juden, die von Jerusalem herabkommen waren, und brachten auf viel und schwere Klagen wider Paulus, welche sie nicht mochten beweisen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'dieweil er sich verantwortete: Ich habe weder an der Juden Gesetz noch an dem Tempel noch an dem Kaiser mich versundiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus aberwollte den Juden eine Gunst erzeigen und antwortete Paulus und sprach: Willst du hinauf gen Jerusalem und daselbst über diesem dich vor mir richten lassen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Paulus aber sprach: Ich stehe vor des Kaisers Gericht, da soil ich mich lassen richten; den Juden habe ich kein Leid getan, wie auch du aufs beste weißt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Habe ich aber jemand Leid getan und des Todes wert gehandelt, so weigere ich mich nicht zu sterben; ist aber der keines nicht, des sie mich verklagen, so kann mich ihnen niemand ergeben. Ich berufe mich auf den Kaiser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Da besprach sich Festus mit dem Rat und antwortete: Auf den Kaiser hast du dich berufen, zum Kaiser sollst du ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Aber nach etlichen Tagen kamen der Konig Agrippa und Bernice gen Casarea, Festus zu empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Und da sie viel Tage daselbst gewesen waren, legte Festus dem Konige den Handel von Paulus vor und sprach: Es ist ein Mann, von Felix hinterlassen gefangen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'urn welches willen die Hohenpriester und Altesten der Juden vor mir erschienen, da ich zu Jerusalem war, und baten, ich sollte ihn richten lassen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'welchen ich antwortete: Es ist der Romer Weise nicht, daß ein Mensch ergeben werde umzubringen, ehe denn der Verklagte habe seine Klager gegenwartig und Raum empfange, sich der Anklage zu verantworten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Da sie aber her zusammenkamen, machte ich keinen Aufschub und hielt des andern Tages Gericht und hieü den Mann vorbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Von welchem, da die Verklager auftraten, brachten sie der Ursachen keine auf, der ich mich versah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Sie hatten aber etliche Fragen wider ihn von ihrem Aberglauben und von einem verstorbenen Jesus, von welchem Paulus sagte, er lebete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Da ich aber mich der Frage nicht verstund, sprach ich, ob erwollte gen Jerusalem reisen und daselbst sich daruber lassen richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Da aber Paulus sich berief, daß er auf des Kaisers Erkenntnis behalten wurde, hieß ich ihn behalten, bis daß ich ihn zum Kaiser sende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa aber sprach zu Festus: Ich mochte den Menschen auch gerne horen. Er aber sprach: Morgen sollst du ihn horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Und am andern Tage, da Agrippa und Bernice kamen mit großem Geprange und gingen in das Richthaus mit den Hauptleuten und vornehmsten Mannern der Stadt, und da es Festus hieß, ward Paulus gebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Und Festus sprach: Lieber Konig Agrippa und alle ihr Manner, die ihr mit uns hier seid, da sehet ihr den, urn welchen mich die ganze Menge der Juden angelanget hat, beide, zu Jerusalem und auch hier, und schrieen, er solle nicht langer leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Ich aber, da ich vernahm, daü er nichts getan hatte, was des Todes wert sei, und er auch selber sich auf den Kaiser berief, habe ich beschlossen, ihn zu senden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'von welchem ich nichts Gewisses habe, das ich dem Herrn schreibe. Darum habe ich ihn lassen hervorbringen vor euch, allermeist aber vor dich Konig Agrippa, auf daß ich nach geschehener Erforschung haben moge, was ich schreibe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'denn es dünkt mich ungeschickt Ding sein, einen Gefangenen zu schicken und keine Ursache wider ihn anzeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa aber sprach zu Paulus: Es ist dir eriaubt, fur dich zu reden. Da verantwortete sich Paulus und reckte die Hand aus:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Es ist mir sehr lieb, lieber Konig Agrippa, daß ich mich heute vor dir verantworten soil alles, des ich von den Juden beschuldigt werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'allermeist weil du weißt alle Sitten und Fragen der Juden. Darum bitte ich dich du wollest mich geduldiglich horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Zwar mein Leben von Jugend auf, wie das von Anfang unter diesem Volk zu Jerusalem zugebracht ist, wissen alle Juden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'die mich vorhin gekannt haben, wenn sie wollten bezeugen. Denn ich bin ein Pharisaer gewesen, welche ist die strengste Sekte unsers Gottesdienstes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Und nun stehe ich und werde angeklagt uber der Hoffnung an die Verheißung, so geschehen ist von Gott zu unsern Vatern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Zu welcher hoffen die zwolf Geschlechter der Unsern zu kommen mit Gottesdienst Tag und Nacht emsiglich. Dieser Hoffnung halben werde ich, lieber Konig Agrippa, von den Juden beschuidiget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Warum wird das fur unglaublich bei euch gerichtet, daß Gott Tote auferweckt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Zwar ich meinete auch bei mir selbst, ich müßte viel zuwidertun dem Namen Jesu von Nazareth,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'wie ich denn auch zu Jerusalem getan habe, da ich viel Heilige in das Gefangnis verschloß, daruber ich Macht von den Hohenpriestern empfing; und wenn sie erwurget wurden, half ich das Urteil sprechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Und durch alle Schulen peinigte ich sie oft und zwang sie zu lastern und war uberaus unsinnig auf sie, verfolgte sie auch bis in die fremden Stadte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Uber welchem, da ich auch gen Damaskus reisete mit Macht und Befehl von den Hohenpriestern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'mitten am Tage, lieber Konig, sah ich auf dem Wege, daß ein Licht vom Himmel, heller denn der Sonne Glanz, mich und die mit mir reiseten, umleuchtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Da wiraber allezur Erde niederfielen, horete ich eine Stimme reden zu mir, die sprach auf ebraisch: Saul, Saul, was verfolgest du mich? Es wird dir schwer sein, wider den Stachel zu lecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Ich aber sprach: Herrwerbistdu? Er sprach: Ich bin Jesus, den du verfolgest; aber stehe auf und tritt auf deine Fuße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Denn dazu bin ich dir erschienen, daß ich dich ordne zum Diener und Zeugen des, das du gesehen hast, und das ich dir noch will erscheinen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Und will dich erretten von dem Volk und von den Heiden, unter welche ich dich jetzt sende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'aufzutun ihre Augen, daß sie sich bekehren von der Finsternis zu dem Licht und von der Gewalt des Satans zu Gott, zu empfangen Vergebung der Sunden und das Erbe samt denen, die geheiliget werden durch den Glauben an mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Daher, lieber Konig Agrippa, war ich der himmlischen Erscheinung nicht unglaubig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'sondern verkündigte zuerst denen zu Damaskus und zu Jerusalem und in alle Gegend judischen Landes, auch den Fleiden, daß sie Buße taten und sich bekehreten zu Gott und taten rechtschaffene Werke der Buße.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Urn deswillen haben mich die Juden im Tempel gegriffen und unterstanden, mich zu toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Aber durch Hilfe Gottes ist es mir gelungen und stehe bis auf diesen Tag und zeuge beiden, dem Kleinen und Großen, und sage nichts außer dem, was die Propheten gesagt haben, daß es geschehen sollte, und Mose:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'daß Christus sollte leiden und der Erste sein aus der Auferstehung von den Toten und verkundigen ein Licht dem Volk und den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Da er aber solches zur Verantwortung gab, sprach Festus mit lauter Stimme: Paulus, du rasest; die große Kunst macht dich rasend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Er aber sprach: Mein teurer Festus, ich rase nicht, sondern ich rede wahre und vernünftige Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Denn der Konig weiß solches wohl, zu welchem ich freudig rede; denn ich achte, ihm sei der keines nicht verborgen, denn solches ist nicht im Winkel geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Glaubest du, Konig Agrippa; den Propheten? Ich weiß, daß du glaubest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa aber sprach zu Paulus: Es fehlet nicht viel, du uberredest mich, daß ich ein Christ würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paulus aber sprach: Ich wunschte vor Gott, es fehlte an viel Oder an wenig, daß nicht alleine du, sondern alle, die mich heute horen, solche wurden, wie ich bin, ausgenommen diese Bande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Und da er das gesagt, stund der Konig auf und der Landpfleger und Bernice, und die mit ihnen saßen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'und entwichen beiseits, redeten miteinander und sprachen: Dieser Mensch hat nichts getan, was des Todes Oder der Bande wert sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa aber sprach zu Festus: Dieser Mensch hatte konnen losgegeben werden, wenn er sich nicht auf den Kaiser berufen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Da es aber beschlossen war, daß wir nach Welschland schiffen sollten, ubergaben sie Paulus und etliche andere Gefangene dem Unterhauptmann mit Namen Julius von der kaiserlichen Schar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Da wiraber in ein adramyttisch Schifftraten, daß wir an Asien hin schiffen sollten, fuhren wir vom Lande; und es war mit uns Aristarchus aus Mazedonien von Thessalonich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Und kamen des andern Tages an zu Sidon. Und Julius hielt sich freundlich gegen Paulus, erlaubte ihm, zu seinen guten Freunden zu gehen und seiner zu pflegen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Und von dannen stießen wir ab und schifften unter Zypern hin, darum daß uns die Winde entgegen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Und schiffeten auf dem Meer vor Zilizien und Pamphylien uber und kamen gen Myra in Lyzien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Und daselbstfand der Unterhauptmann ein Schiff von Alexandrien; das schiffte nach Welschland und lud uns darauf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Da wir aber langsam schifften und in viel Tagen kaum gegen Knidus kamen (denn der Wind wehrete uns), schifften wir unter Kreta hin nach der Stadt Salmone.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Und zogen kaum voruber, da kamen wir an eine Statte, die da heißet Gutfurt; dabei war nahe die Stadt Lasaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Da nun viel Zeit vergangen war, und nunmehr gefahrlich war zu schiffen, darum daß auch das Fasten schon voruber war, vermahnete sie Paulus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'und sprach zu ihnen: Liebe Manner, ich sehe, daß die Schiffahrt will mit Beleidigung und großem Schaden ergehen, nicht allein der Last und des Schiffes, sondern auch unsers Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Aber der Unterhauptmann glaubte dem Schiffsherm und dem Schiffsmann mehr denn dem, was Paulus sagte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Und da die Anfurt ungelegen war zu wintern, bestunden ihrerdas mehrere Teil auf dem Rat, von dannen zu fahren, ob sie konnten kommen gen Phonix zu wintern, welches ist eine Anfurt an Kreta, gegen den Wind Südwest und Nordwest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Da aber der Sudwind wehete, und sie meineten, sie hatten nun ihr Vornehmen, erhuben sie sich gen Assos und fuhren an Kreta hin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Nicht lange aber danach erhub sich wider ihr Vornehmen, eine Windsbraut, die man nennet Nordost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Und da das Schiff ergriffen ward und konnte sich nicht wider den Wind richten, gaben wir\'s dahin und schwebeten also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Wir kamen aber an eine Insel, die heißet Klauda; da konnten wir kaum einen Kahn ergreifen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Den huben wir auf und brauchten der Hilfe und banden ihn unten an das Schiff; denn wir fürchteten, es mochte in die Syrte fallen, und lieften das Gefaft hinunter und fuhren also.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Und da wir graft Ungewitter erlitten hatten, da taten sie des nachsten Tages einen Auswurf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Und am dritten Tage warfen wir mit unsern Handen aus die Bereitschaft im Schiffe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Da aber in vielen Tagen weder Sonne noch Gestirn erschien, und nicht ein klein Ungewitter uns wider war, war alle Hoffnung unsers Lebens dahin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Und da man lange nicht gegessen hatte, trat Paulus mitten unter sie und sprach: Liebe Manner, man sollte mir gehorchet und nicht von Kreta aufgebrochen haben und uns dieses Leides und Schadens überhoben haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Und nun ermahne ich euch, daß ihr unverzagt seid; denn keines Leben aus uns wird umkommen ohne das Schiff.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Denn diese Nacht ist bei mir gestanden der Engel Gottes, des ich bin, und dem ich diene,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'und sprach: Furchte dich nicht, Paulus; du muftt vor den Kaiser gestellet werden; und siehe, Gott hat dir geschenkt alle, die mit dir schiffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Darum, liebe Manner, seid unverzagt; denn ich glaube Gott, es wird also geschehen, wie mir gesagt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Wir müssen aber anfahren an eine Insel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Da aber die vierzehnte Nacht kam, und wir in Adria fuhren urn die Mitternacht, wahneten die Schiffsleute, sie kamen etwa an ein Land.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Und sie senkten den Bleiwurf ein und fanden zwanzig Klafter tief. Und uber ein wenig von dannen senkten sie abermal und fanden funfzehn Klafter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Da fürchteten sie sich, sie würden an harte Orte anstoften, und warfen hinten vom Schiffe vier Anker und wünschten, daß es Tag wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Da aber die Schiffsleute die Flucht suchten aus dem Schiffe und den Kahn niederlieften in das Meer und gaben vor, sie wollten die Anker vorne aus dem Schiffe lassen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'sprach Paulus zu dem Unterhauptmann und zu den Kriegsknechten: Wenn diese nicht im Schiff bleiben, so konnt ihr nicht beim Leben bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Da hieben die Kriegsknechte die Stricke ab von dem Kahn und lieften ihn fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Und da es anfing licht zu werden, ermahnete sie Paulus alle, daß sie Speise nahmen, und sprach: Es ist heute der vierzehnte Tag, daß ihr wartet und ungegessen geblieben seid und habt nichts zu euch genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Darum ermahne ich euch, Speise zu nehmen, euch zu laben; denn es wird euer keinem ein Haar von dem Haupt entfallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Und da er das gesagt, nahm er das Brat, dankete Gott vor ihnen alien und brach\'s und fing an zu essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Da wurden sie alle gutes Muts und nahmen auch Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Unserwaren aber alle zusammen im Schiff zweihundert und sechsundsiebenzig Seelen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Und da sie satt wurden, erleichterten sie das Schiff und warfen das Getreide in das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Da es aber Tag ward, kannten sie das Land nicht. Einer Anfurt aber wurden sie gewahr, die hatte ein Ufer; dahinan wollten sie das Schiff treiben, wo es moglich ware.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Und da sie die Anker aufgehoben, lieften sie sich dem Meer und loseten die Ruderbande auf und richteten den Segelbaum nach dem Winde und trachteten nach dem Ufer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Und da wir fuhren an einen Ort, der auf beiden Seiten Meer hatte, stieft sich das Schiff an, und das Vorderteil blieb fest stehen unbeweglich; aber das Hinterteil zerbrach von der Gewalt der Wellen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Die Kriegsknechte aber hatten einen Rat, die Gefangenen zu toten, daß nicht jemand, so herausschwomme, entflohe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Aber der Unterhauptmann wollte Paulus erhalten und wehrete ihrem Vornehmen und hieft, die da schwimmen konnten, sich zuerst in das Meer lassen und entrinnen an das Land,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'die andern aber, etliche auf den Brettern, etliche auf dem, was vom Schiffe war. Und also geschah es, daß sie alle erhalten zu Lande kamen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Und da wir auskamen, erfuhren wir, daß die Insel Melite hieft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Die Leutlein aber erzeigten uns nicht geringe Freundschaft, zündeten ein Feuer an und nahmen uns alle auf urn des Regens, der uber uns kommen war, und urn der Kalte willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Da aber Paulus einen Haufen Reiser zusammenraffte und legte es aufs Feuer, kam eine Otter von der Hitze und fuhr Paulus an seine Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Da aber die Leutlein sahen das Tier an seiner Hand hangen, sprachen sie untereinander: Dieser Mensch muft ein Morder sein, welchen die Rache nicht leben laftt, ob er gleich dem Meer entgangen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Er aber schlenkerte das Tier ins Feuer, und ihm widerfuhr nichts Ubles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Sie aber warteten, wenn er schwellen wurde Oder tot niederfallen. Da sie aber lange warteten und sahen, daß ihm nichts Ungeheures widerfuhr, verwandten sie sich und sprachen, erware ein Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'An denselbigen Ortern aber hatte der Oberste in der Insel mit Namen Publius ein Vorwerk; der nahm uns auf und herbergte uns drei Tage freundlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Es geschah aber, daß der Vater des Publius am Fieber und an der Ruhr lag. Zu dem ging Paulus hinein und betete und legte die Hand auf ihn und machte ihn gesund.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Da das geschah, kamen auch die andern auf der Insel herzu, die Krankheiten hatten, und lielien sich gesund machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Und sie taten uns grolie Ehre, und da wir auszogen, luden sie auf, was uns not war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Nach dreien Monden aber schifften wir aus in einem Schiffe von Alexandrien, welches bei der Insel gewintert hatte und hatte ein Panier der Zwillinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Und da wir gen Syrakus kamen, blieben wir drei Tage da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Und da wir umschifften, kamen wir gen Rhegion; und nach einem Tage, da der Sudwind sich erhub, kamen wirdes andern Tages gen Puteoli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Da fanden wir Bruder und wurden von ihnen gebeten, daß wir sieben Tage dablieben. Und also kamen wir gen Rom.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Und von dannen, da die Bruder von uns horeten, gingen sie aus uns entgegen bis gen Appifor und Tretabern. Da die Paulus sah, dankete er Gott und gewann eine Zuversicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Da wir aber gen Rom kamen, uber antwortete der Unterhauptmann die Gefangenen dem obersten Hauptmann. Aber Paulus ward erlaubt zu bleiben, wo er wollte, mit einem Kriegsknechte, der sein hütete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Es geschah aber nach dreien Tagen, daß Paulus zusammenrief die Vornehmsten der Juden. Da dieselbigen zusammen kamen, sprach erzu ihnen: Ihr Manner liebe Bruder, ich habe nichts getan wider unser Volk noch wider vaterliche Sitten und bin doch gefangen aus Jerusalem ubergeben in der Romer Hande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'welche, da sie mich verhoret hatten, wollten sie mich losgeben, dieweil keine Ursache des Todes an mirwar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Da aber die Juden dawider redeten, ward ich genotiget, mich auf den Kaiser zu berufen; nicht, als hatte ich mein Volk urn etwas zu verklagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Urn der Ursache willen habe ich euch gebeten, daß ich euch sehen und ansprechen mochte; denn urn der Hoffnung willen Israels bin ich mit dieser Kette umgeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Sie aber sprachen zu ihm: Wir haben weder Schrift empfangen aus Judaa deinethalben, noch kein Bruder ist kommen, der von dir etwas Arges verkundiget Oder gesagt habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Doch wollen wir von dir horen, was du haltst. Denn von dieser Sekte ist uns kund, daß ihr wird an alien Enden widersprochen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Und da sie ihm einen Tag bestimmten, kamen viele zu ihm in die Herberge, welchen er auslegte und bezeugete das Reich Gottes und predigte ihnen von Jesu aus dem Gesetze Mose\'s und aus den Propheten vom fruhen Morgen an bis an den Abend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Und etliche fielen zu dem, was er sagte; etliche aber glaubten nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Da sie aber untereinander milihellig waren, gingen sie weg, als Paulus ein Wort redete, das wohl der Heilige Geist gesagt hat durch den Propheten Jesaja zu unsern Vatern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'und gesprochen: Gehe hin zu diesem Volk und sprich: Mit den Ohren werdet ihr\'s horen und nicht verstehen, und mit den Augen werdet ihr\'s sehen und nicht erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Denn das Herz dieses Volks ist verstockt, und sie horen schwerlich mit Ohren und schlummern mit ihren Augen, auf daß sie nicht dermaleinst sehen mit den Augen und horen mit den Ohren und verstandig werden im Herzen und sich bekehren, daß ich ihnen hulfe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'So sei es euch kundgetan, daß den Heiden gesandt ist dies Heil Gottes; und sie werden\'s horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Und da er solches redete, gingen die Juden hin und hatten viel Fragens unter sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Paulus aber blieb zwei Jahre in seinem eignen Gedinge und nahm auf alle, die zu ihm kamen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'predigte das Reich Gottes und lehrete von dem Herm Jesu mit aller Freudigkeit unverboten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, ein Knecht Jesu Christi, berufen zum Apostel, ausgesondert, zu predigen das Evangelium Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'welches er zuvor verheiften hat durch seine Prapheten in der Heiligen Schrift,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'von seinem Sohn, der geboren ist von dem Samen Davids nach dem Fleisch');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'und kraftiglich erweiset ein Sohn Gottes nach dem Geist, der da heiliget, seit der Zeit er auferstanden ist von den Toten, namlich Jesus Christus, unser Herr');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, '(durch welchen wir haben empfangen Gnade und Apostelamt, unter alien Heiden den Gehorsam des Glaubens aufzurichten unter seinem Namen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'welcher ihr zum Teil auch seid, die da berufen sind von Jesu Christo):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Allen, die zu Rom sind, den Liebsten Gottes und berufenen Heiligen: Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesus Christus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Aufs erste danke ich meinem Gott durch Jesum Christum euer aller halben, daß man von eurem Glauben in aller Welt saget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Denn Gott ist mein Zeuge, welchem ich diene in meinem Geist am Evangelium von seinem Sohn, daß ich ohne Unterlali euer gedenke');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'und allezeit in meinem Gebet flehe, ob sich\'s einmal zutragen wollte, daß ich zu euch kame durch Gottes Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Denn mich verlanget, euch zu sehen, auf daß ich euch mitteile etwas geistlicher Gabe, euch zu starken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'das ist, daß ich samteuch getrostet wurde durch euren und meinen Glauben, den wir untereinander haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Ich will euch aber nichtverhalten, liebe Bruder, daß ich mir oft habe vorgesetzt, zu euch zu kommen (bin aber verhindert bisher), daß ich auch unter euch Frucht schaffete gleichwie unter andern Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Ich bin ein Schuldnerbeide, derßriechen und der Ungriechen, beide, der Weisen und der Unweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Darum, soviel an mir ist bin ich geneigt, auch euch zu Rom das Evangelium zu predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Denn ich schame mich des Evangeliums von Christo nicht; denn es ist eine Kraft Gottes, die da selig machet alle, die daran glauben, die Juden vomehmlich und auch die Griechen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'sintemal darinnen offenbaret wird die Gerechtigkeit, die vor Gott gilt, weiche kommt aus Glauben in Glauben; wie denn geschrieben stehet: Der Gerechte wird seines Glaubens leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Denn Gottes Zorn vom Himmel wird offenbart uber alles gottlose Wesen und Ungerechtigkeit der Menschen, die die Wahrheit in Ungerechtigkeit aufhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Denn daß man weili, daß Gott sei, istihnen offenbar; denn Gott hat es ihnen offenbart');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'damit, daß Gottes unsichtbares Wesen, das ist, seine ewige Kraft und Gottheit, wird ersehen, so man des wahmimmt an den Werken, namlich an der Schopfung der Welt, also daß sie keine Entschuldigung haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'dieweil siewuliten, daß ein Gott ist, und haben ihn nicht gepreiset als einen Gott noch gedanket, sondern sind in ihrem Dichten eitel worden, und ihr unverstandiges Herz ist verfinstert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Da sie sich fur weise hieiten, sind sie zu Narren worden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'und haben verwandelt die Herrlichkeit des unverganglichen Gottes in ein Bild gleich dem verganglichen Menschen und der Vogel und der vierfülügen und der kriechenden Tiere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Darum hat sie auch Gott dahingegeben in ihrer Herzen Geluste, in Unreinigkeit, zu schanden ihre eigenen Leiber an sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Die Gottes Wahrheit haben verwandelt in die Luge und haben geehret und gedienet dem Geschopfe mehr denn dem Schopfer, der da gelobet ist in Ewigkeit. Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Darum hat sie Gott auch dahingegeben in schandliche Luste. Denn ihre Weiber haben verwandelt den naturlichen Brauch in den unnatürlichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Desselbigengleichen auch die Manner haben verlassen den naturlichen Brauch des Weibes und sind aneinander erhitzet in ihren Lusten, und haben Mann mit Mann Schande gewirket und den Lohn ihres Irrtums (wie es denn sein sollte) an sich selbst empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Und gleichwie sie nicht geachtet haben, daß sie Gott erkenneten, hat sie Gott auch dahingegeben in verkehrten Sinn, zu tun, was nicht taugt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'voll alles Ungerechten, Hurerei, Schalkheit, Geizes, Bosheit, voll Hasses, Mordes, Haders, List, giftig, Ohrenblaser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Verleumder, Gottesverachter, Frevler, hoffartig, ruhmredig, Schadliche, den Eltern ungehorsam,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Unvernünftige, Treulose, storrig, unversohnlich, unbarmherzig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'die Gottes Gerechtigkeit Wissen (daß, die solches tun, des Todes würdig sind), tun sie es nicht allein, sondern haben auch Gefallen an denen, die es tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Darum, o Mensch, kannst du dich nicht entschuldigen, wer du bist, der da richtet; denn worinnen du einen andern richtest, verdammst du dich selbst, sintemal du eben dasselbige tust, was du richtest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Denn wir wissen, daß Gottes Urteil ist recht uber die, so solches tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Denkest du aber, o Mensch, der du richtest die, so solches tun, und tust auch dasselbige, daß du dem Urteil Gottes entrinnen werdest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Oder verachtest du den Reichtum seiner Güte, Geduld und Langmutigkeit? Weiftt du nicht, daß dich Gottes Güte zur Bufte leitet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Du aber nach deinem verstockten und unbuftfertigen Herzen haufest dir selbst den Zorn auf den Tag des Zorns und der Offenbarung des gerechten Gerichtes Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'welcher geben wird einem jeglichen nach seinen Werken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'namlich Preis und Ehre und, unvergangliches Wesen denen, die mit Geduid in guten Werken trachten nach dem ewigen Leben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'aber denen, die da zankisch sind und der Wahrheit nicht gehorchen, gehorchen aber dem Ungerechten, Ungnade und Zorn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Trubsal und Angst uber alle Seelen der Menschen, die da Boses tun, vomehmlich der Juden und auch der Griechen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Preis aber und Ehre und Friede alien denen, die da Gutes tun, vomehmlich den Juden und auch den Griechen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Denn es ist kein Ansehen der Person vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Welche ohne Gesetz gesündigt haben, die werden auch ohne Gesetz verloren werden; und welche am Gesetz gesündiget haben, die werden durchs Gesetz verurteilt werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'sintemal vor Gott nicht, die das Gesetz horen, gerecht sind, sondern die das Gesetz tun, werden gerechtsein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Denn so die Heiden, die das Gesetz nicht haben und doch von Natur tun des Gesetzes Werk, dieselbigen, dieweil sie das Gesetz nicht haben, sind sie sich selbst ein Gesetz');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'damit, daß sie beweisen, des Gesetzes Werk sei beschrieben in ihrem Herzen, sintemal ihr Gewissen sie bezeuget, dazu auch die Gedanken, die sich untereinander verklagen Oder entschuldigen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'auf den Tag, da Gott das Verborgene der Menschen durch Jesum Christum richten wird laut meines Evangeliums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Siehe aberzu, du heiftest ein Jude und verlassest dich aufs Gesetz und ruhmest dich Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'und weiftt seinen Willen, und weil du aus dem Gesetz unterrichtet bist, prufest du, was das Beste zu tun sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'und vermissest dich, zu sein ein Leiterder Blinden ein Licht derer, die in Finsternis sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'ein Zuchtiger der Torichten, ein Lehrer der Einfaltigen, hast die Form, was zu wissen und recht ist im Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Nun lehrest du andere und lehrest dich selber nicht. Du predigest, man solle nicht stehlen, und du stiehlst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Du sprichst, man solle nicht ehebrechen, und du brichst die Ehe. Dir greuelt vor den Gotzen und raubest Gott, was sein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Du ruhmest dich des Gesetzes und schandest Gott durch Ubertretung des Gesetzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Denn eurethalben wird Gottes Name gelastert unter den Heiden, als geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Die Beschneidung istwohl nutzwenn du das Gesetz haltst; haltst du aber das Gesetz nicht, so ist deine Beschneidung schon eine Vorhaut worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'So nun die Vorhaut das Recht im Gesetz halt, meinest du nicht, daß seine Vorhaut werde fur eine Beschneidung gerechnet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Und wird also, was von Natur eine Vorhaut ist und das Gesetz vollbringet, dich richten, der du unter dem Buchstaben und Beschneidung bist und das Gesetz ubertrittst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Denn das ist nicht ein Jude, der auswendig ein Jude ist, auch ist das nicht eine Beschneidung, die auswendig im Fleisch geschieht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'sondern das ist ein Jude, der inwendig verborgen ist, und die Beschneidung des Herzens ist eine Beschneidung, die im Geist und nicht im Buchstaben geschieht, welches Lob ist nicht aus Menschen, sondern aus Gott');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Was haben denn die Juden Vorteils, Oder was nutzt die Beschneidung?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Zwar fast viel. Zum ersten, ihnen ist vertrauet, was Gott geredet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Daft aber etliche nicht glauben an dasselbige, was liegt daran? Sollte ihr Unglaube Gottes Glauben aufheben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Das sei feme! Es bleibe vielmehr also, daß Gott sei wahrhaftig und alle Menschen falsch; wie geschrieben steht: Auf daß du gerecht seiest in deinen Worten und uberwindest, wenn du gerichtet wirst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Ist\'s aber also, daß unsere Ungerechtigkeit Gottes Gerechtigkeit preiset, was wollen wir sagen? Ist denn Gott auch ungerecht, daß er daruber zurnet? (Ich rede also auf Menschenweise.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Das sei feme! Wie konnte sonst Gott die Welt richten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Denn so die Wahrheit Gottes durch meine Luge herrlicher wird zu seinem Preis, warum sollte ich denn noch als ein Sunder gerichtet werden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'und nicht vielmehr also tun, wie wir gelastert werden, und wie etliche sprechen, daß wir sagen sollen: Lasset uns Libel tun, auf daß Gutes daraus komme? Welcher Verdammnis ist ganz recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Was sagen wir denn nun? Haben wir einen Vorteil? Gar keinen. Denn wir haben droben bewiesen daß beide, Juden und Griechen, alle unter der Sünde sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'wie denn geschrieben stehet: Da ist nicht, der gerecht sei, auch nicht einer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'da ist nicht, der verstandig sei; da ist nicht, der nach Gottfrage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Sie sind alle abgewichen und allesamt untuchtig worden; da ist nicht, der Gutes tue, auch nicht einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Ihrßchlund istein offen Grab; mit ihren Zungen handeln sie truglich; Otterngift ist unter ihren Lippen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'ihr Mund ist voll Fluchens und Bitterkeit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'ihre Fuße sind eilend, Blut zu vergiefien;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'in ihren Wegen ist eitel Unfall und Herzeleid');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'und den Weg des Friedens wissen sie nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Es ist keine Furcht Gottes vor ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Wir wissen aber, daß, was das Gesetz, sagt, das sagt es denen, die unter dem Gesetz sind, auf daß aller Mund verstopfet werde, und alle Welt Gott schuldig sei');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'darum, daß kein Fleisch durch des Gesetzes Werke vor ihm gerecht sein mag; denn durch das Gesetz kommt Erkenntnis der Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Nun aber ist ohne Zutun des Gesetzes die Gerechtigkeit, die vor Gott gilt, offenbaret und bezeuget durch das Gesetz und die Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Ich sage aber von solcher Gerechtigkeit vor Gott, die da kommt durch den Glauben an Jesum Christum zu alien und auf alle, die da glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Denn es ist hier kein Unterschied; sie sind allzumal Sunder und mangeln des Ruhms, den sie an Gott haben sollten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'und werden ohne Verdienst gerecht aus seiner Gnade durch die Erlosung, so durch Christum Jesum geschehen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'welchen Gott hat vorgestellt zu einem Gnadenstuhl durch den Glauben in seinem Blut.damit er die Gerechtigkeit, die vor ihm gilt, darbiete, in dem, daß er Sünde vergibt, welche bis anher geblieben war unter gbttlicher Geduld,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'auf daß er zu diesen Zeiten darbote die Gerechtigkeit, die vor ihm gilt, auf daß er allein gerecht sei und gerecht mache den, der da ist des Glaubens an Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Wo bleibt nun der Ruhm? Er ist aus. Durch welches Gesetz? durch der Werke Gesetz? Nicht also, sondern durch des Glaubens Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'So halten wir es nun, daß der Mensch gerecht werde ohne des Gesetzes Werke, allein durch den Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Oder ist Gott allein der Juden Gott? Ist er nicht auch der Heiden Gott? Ja freilich, auch der Heiden Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Sintemal es ist ein einiger Gott, der da gerecht macht die Beschneidung aus dem Glauben und die Vorhaut durch den Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Wie? heben wir denn das Gesetz auf durch den Glauben? Das sei feme! sondern wir richten das Gesetz auf.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Was sagen wir denn von unserm Vater Abraham, daß ergefunden habe nach dem Fleisch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Das sagen wir: Ist Abraham durch die Werke gerecht, so hat erwohl Ruhm, aber nicht vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Was sagt denn die Schrift? Abraham hat Gott geglaubet, und das ist ihm zur Gerechtigkeit gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Dem aber, der mit Werken umgehet, wird der Lohn nicht aus Gnade zugerechnet, sondern aus Pflicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Dem aber, der nicht mit Werken umgehet, glaubet aber an den, der die Gottlosen gerecht macht, dem wird sein Glaube gerechnet zur Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Nach welcher Weise auch David sagt, daß die Seligkeit sei allein des Menschen, welchem Gott zurechnet die Gerechtigkeit ohne Zutun der Werke, da er spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Selig sind die, welchen ihre Ungerechtigkeiten vergeben sind, und welchen ihre Sunden bedecket sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Selig ist der Mann, welchem Gott keine Sünde zurechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Nun, diese Seligkeit, gehet sie uber die Beschneidung Oder uber die Vorhaut? Wir mussen je sagen, daß Abraham sei sein Glaube zur Gerechtigkeit gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Wie ist er ihm denn zugerechnet, in der Beschneidung Oder in der Vorhaut? Ohne Zweifel nicht in der Beschneidung, sondern in der Vorhaut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Das Zeichen aber der Beschneidung empfing er zum Siegel der Gerechtigkeit des Glaubens, welchen er noch in der Vorhaut hatte, auf daß er würde ein Vater aller, die da glauben in der Vorhaut, daß denselbigen solches auch gerechnet werde zur Gerechtigkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'und würde auch ein Vater der Beschneidung, nicht allein derer, die von der Beschneidung sind, sondern auch derer, die wandeln in den Fufttapfen des Glaubens, welcher war in der Vorhaut unsers Vaters Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Denn die Verheiftung, daß er sollte sein der Welt Erbe, ist nicht geschehen Abraham Oder seinem Samen durchs Gesetz, sondern durch die Gerechtigkeit des Glaubens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Denn wo die vom Gesetz Erben sind, so ist der Glaube nichts, und die Verheißung ist ab.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Sintemal das Gesetz richtet nur Zorn an; denn wo das Gesetz nicht ist, da ist auch keine Ubertretung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Derhalben muiß die Gerechtigkeit durch den Glauben kommen, auf daß sie sei aus Gnaden, und die Verheiftung test bleibe allem Samen, nicht dem alleine, der unter dem Gesetz ist, sondern auch dem, der des Glaubens Abrahams ist, welcher ist unser aller Vater,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'wie geschrieben stehet: Ich habe dich gesetzt zum Vater vieler Heiden vor Gott, dem du geglaubet hast, der da lebendig machet die Toten und rufet dem, das nicht ist, daß es sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Und er hat geglaubet auf Hoffnung, da nichts zu hoffen war, auf daß er würde ein Vater vieler Heiden, wie denn zu ihm gesagt ist: Also soli dein Same sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Und erward nichtschwach imßlauben, sah auch nicht an seinen eigenen Leib, welcher schon erstorben war, weil er fast hundertjahrig war, auch nicht den erstorbenen Leib der Sara.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Denn er zweifelte nicht an der Verheiliung Gottes durch Unglauben, sondern ward stark im Glauben und gab Gott die Ehre');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'und wuftte aufs allergewisseste, dad, was Gott verheiftet, das kann er auch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Darum ist\'s ihm auch zur Gerechtigkeit gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Das ist aber nicht geschrieben allein urn seinetwillen, dad es ihm zugerechnet ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'sondern auch um unsertwillen, welchen es soli zugerechnet werden, so wir glauben an den, der unsern Herrn Jesum auferwecket hat von den Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'welcher ist um unserer Sünden willen dahingegeben und um unserer Gerechtigkeit willen auferwecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Nun wir denn sind gerecht worden durch den Glauben, so haben wir Frieden mit Gott durch unsern Herrn Jesum Christum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'durch welchen wir auch einen Zugang haben im Glauben zu dieser Gnade darinnen wir stehen, und ruhmen uns der Hoffnung der zukunftigen Herrlichkeit die Gott geben soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Nicht allein aber das, sondern wir ruhmen uns auch der Trubsale dieweil wirwissen, dad Trubsal Geduld bringet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Geduld aber bringet Erfahrung, Erfahrung aber bringet Hoffnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Hoffnung aber laftt nicht zuschanden werden. Denn die Liebe Gottes ist ausgegossen in unser Herz durch den Heiligen Geist, welcher uns gegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Denn auch Christus, da wir noch schwach waren nach der Zeit, ist fur uns Gottlose gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Nun stirbt kaum jemand um des Rechtes willen; um etwas Gutes willen dürfte vielleicht jemand sterben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Darum preiset Gott seine Liebe gegen uns, dad Christus fur uns gestorben ist, da wir noch Sunder waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'So werden wir je viel mehr durch ihn behalten werden vor dem Zorn, nachdem wir durch sein Blut gerecht worden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Denn so wir Gott versohnet sind durch den Tod seines Sohns, da wir noch Feinde waren, viel mehr werden wir selig werden durch sein Leben, so wir nun versohnet sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Nicht aliein aber das, sondern wir ruhmen uns auch Gottes durch unsern Herrn Jesum Christum, durch welchen wir nun die Versohnung empfangen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Derhaiben, wie durch einen Menschen die Sunde ist kommen in die Welt und der Tod durch die Sunde, und ist also der Tod zu alien Menschen durchgedrungen, dieweil sie alle gesundiget haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '(denn die Sunde warwohl in der Welt bisauf das Gesetz; aber wo kein Gesetz ist, da achtet man der Sunde nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'sondern der Tod herrschte von Adam an bis auf Mose, auch uber die, die nicht gesundiget haben mit gieicher Ubertretung wie Adam, welcher ist ein Bild des, der zukunftig war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Aber nicht halt sich\'s mit der Gabe wie mit der Sunde. Denn so an eines Sunde viele gestorben sind, so ist viel mehr Gottes Gnade und Gabe vielen reichlich widerfahren durch die Gnade des einigen Menschen, Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Und nicht ist die Gabe allein uber eine Sunde wie durch des einigen Sunders einige Sunde alles Verderben. Denn das Urteil ist kommen aus einer Sunde zur Verdammnis; die Gabe aber hilftauch aus vielen Sünden zur Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Denn so um des einigen Sunde willen der Tod geherrschet hat durch den einen, viel mehr werden die, so da empfangen die Fülle der Gnade und der Gabe zur Gerechtigkeit, herrschen im Leben durch einen, Jesum Christum):');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'wie nun durch eines Sunde die Verdammnis uber alle Menschen kommen ist, also ist auch durch eines Gerechtigkeit die Rechtfertigung des Lebens über alle Menschen kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Denn gleichwie durch eines Menschen Ungehorsam viel Sunder worden sind, also auch durch eines Gehorsam werden viel Gerechte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Das Gesetz aber ist neben einkommen, auf dati die Sunde machtiger würde. Wo aber die Sunde machtig worden ist, da ist doch die Gnade viel machtiger worden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'auf daß, gleichwie die Sunde geherrschet hat zu dem Tode, also auch herrsche die Gnade durch die Gerechtigkeit zum ewigen Leben durch Jesum Christum, unsern Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Was wollen wir hiezu sagen? Sollen wir denn in der Sunde beharren, auf daß die Gnade desto machtiger werde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Das sei feme! Wie sollten wir in der Sunde wollen leben, der wir abgestorben sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Wisset ihr nicht, daß alle, die wir in Jesum Christum getauft sind, die sind in seinen Tod getauft?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'So sind wirje mit ihm begraben durch die Taufe in den Tod, auf daß, gleichwie Christus ist auferweckt von den Toten durch die Herrlichkeit des Vaters, also sollen auch wir in einem neuen Leben wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'So wir aber samt ihm gepflanzet werden zu gleichem Tode, so werden wir auch der Auferstehung gleich sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'dieweil wir wissen, daß unser alter Mensch samt ihm gekreuziget ist, auf daß der sündliche Leib aufhore, da(3> wir hinfort der Sunde nicht dienen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Denn wer gestorben ist, der ist gerechtfertiget von der Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Sind wir aber mit Christo gestorben, so glauben wir, daß wir auch mit ihm leben werden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'und wissen, daß Christus, von den Toten erwecket, hinfort nicht stirbt; der Tod wird hinfort uber ihn nicht herrschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Denn das er gestorben ist; das ist er der Sunde gestorben zu einem Mai; das er aber lebet, das lebet er Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Also auch ihr, haltet euch dafür, daß ihr der Sunde gestorben seid und lebet Gott in Christo Jesu, unserm Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'So lasset nun die Sunde nicht herrschen in eurem sterblichen Leibe, ihm Gehorsam zu leisten in seinen Lüsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Auch begebet nicht der Sunde eure Glieder zu Waffen der Ungerechtigkeit, sondern begebet euch selbst Gott, als die da aus den Toten lebendig sind, und eure Glieder Gott zu Waffen der Gerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Denn die Sunde wird nicht herrschen konnen fiber euch, sintemal ihr nicht unter dem Gesetze seid, sondern unter der Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Wie nun? sollen wir sündigen, dieweil wir nicht unter dem Gesetz, sondern unter der Gnade sind? Das sei feme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Wisset ihr nicht, welchem ihr euch begebet zu Knechten in Gehorsam, des Knechte seid ihr, dem ihr gehorsam seid, es sei der Sunde zum Tode Oder dem Gehorsam zur Gerechtigkeit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Gott sei aber gedanket, daß ihr Knechte der Sunde gewesen seid, aber nun gehorsam worden von Herzen dem Vorbilde der Lehre, welchem ihr ergeben seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Denn nun ihr frei worden seid von der Sunde, seid ihr Knechte worden der Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Ich muft menschlich davon reden urn der Schwachheit willen eures Fleisches. Gleichwie ihr eure Glieder begeben habt zu Dienste der Unreinigkeit und von einer Ungerechtigkeit zu der andern, also begebet nun auch eure Glieder zu Dienste der Gerechtigkeit, daß sie heilig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Denn da ihr der Sunde Knechte waret, da waret ihr frei von der Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Was hattet ihr nun zu der Zeit fur Frucht? Welcher ihr euch jetzt schamet; denn das Ende derselbigen ist der Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Nun ihr aber seid von der Sunde frei und Gottes Knechte worden, habt ihr eure Frucht, daß ihr heilig werdet, das Ende aber das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Denn der Tod ist der Sunde Sold; aber die Gabe Gottes ist das ewige Leben in Christo Jesu, unserm Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Wisset ihr nicht, liebe Brüder (denn ich rede mit denen, die das Gesetz wissen), daß das Gesetz herrschet fiber den Menschen, solange er lebet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Denn ein Weib, das unter dem Manne ist, dieweil der Mann lebet, ist sie gebunden an das Gesetz; so aber der Mann stirbt, so ist sie los vom Gesetz, das den Mann betrifft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Wo sie nun bei einem andern Manne ist, weil der Mann lebet, wird sie eine Ehebrecherin geheiften; so aber der Mann stirbt, ist sie frei vom Gesetz, daß sie nicht eine Ehebrecherin ist, wo sie bei einem andern Manne ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Also auch, meine Brüder, ihr seid getotet dem Gesetz durch den Leib Christi, daß ihr bei einem andern seid, namlich bei dem, der von den Toten auferwecket ist, auf daß wir Gott Frucht bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Denn da wir im Fleisch waren, da waren die sündlichen Lüste, welche durchs Gesetz sich erregten, kraftig in unsern Gliedern, dem Tode Frucht zu bringe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Nun aber sind wir vom Gesetz los und ihm abgestorben, das uns gefangenhielt, also daß wir dienen sollen im neuen Wesen des Geistes und nicht im alten Wesen des Buchstabens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Was wollen wir denn nun sagen? Ist das Gesetz Sunde? Das sei feme! Aber die Sunde erkannte ich nicht ohne durchs Gesetz. Denn ich wuftte nichts von der Lust, wo das Gesetz nicht hatte gesagt: Laft dich nicht gelüsten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Da nahm aber die Sunde Ursache am Gebot und erregte in mir allerlei Lust. Denn ohne das Gesetz war die Sunde tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Ich aber lebte etwa ohne Gesetz. Da aber das Gebot kam, ward die Sunde wieder lebendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Ich aber starb; und es befand sich, daß das Gebot mir zum Tode gereichte, das mir doch zum Leben gegeben war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Denn die Sunde nahm Ursache am Gebot und betrog mich und totete mich durch dasselbige Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Das Gesetz istje heilig, und das Gebot ist heilig, recht und gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ist denn, was da gut ist, mir ein Tod worden? Das sei feme! Aber die Sunde, auf daß sie erscheine, wie sie Sunde ist, hat sie mir durch das Gute den Tod gewirket, auf daß die Sunde würde uberaus sündig durchs Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Denn wirwissen, daß das Gesetz geistlich ist; ich aber bin fleischlich, unter die Sunde verkauft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Denn ich weift nicht, was, ich tue; denn ich tue nicht, was ich will, sondern was ich hasse, das tue ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'So ich aber das tue, was ich nicht will, so willige ich, daß das Gesetz gut sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'So tue nun ich dasselbige nicht, sondern die Sunde, die in mirwohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Denn ich weift, daß in mir, das ist, in meinem Fleische, wohnet nichts Gutes. Wollen habe ich wohl, aber vollbringen das Gute finde ich nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Denn das Gute, das ich will, das tue ich nicht, sondern das Bose, das ich nicht will, das tue ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'So ich aber tue, was ich nicht will, so tue ich dasselbige nicht, sondern die Sunde, die in mir wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'So finde ich mir nun ein Gesetz, der ich will das Gute tun, daü mir das Bose anhanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Denn ich habe Lust an Gottes Gesetz nach dem inwendigen Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Ich sehe aber ein ander Gesetz in meinen Gliedern, das da widerstreitet dem Gesetz in meinem Gemüte und nimmt mich gefangen in der Sunde Gesetz, welches ist in meinen Gliedern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ich elender Mensch, wer wird mich erlosen von dem Leibe dieses Todes?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Ich danke Gott durch Jesum Christum, unsern Herrn. So diene ich nun mit dem Gemute dem Gesetz Gottes, aber mit dem Fleisch dem Gesetze der Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'So ist nun nichts Verdammliches an denen, die in Christo Jesu sind, die nicht nach dem Fleisch wandeln, sondern nach dem Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Denn das Gesetz des Geistes der da lebendig macht in Christo Jesu, hat mich freigemacht von dem Gesetz der Sunde und des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Denn was dem Gesetz unmoglich war (sintemal es durch das Fleisch geschwachet ward), das tat Gott und sandte seinen Sohn in der Gestalt des sundlichen Fleisches und verdammte die Sunde im Fleisch durch Sunde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'auf daß die Gerechtigkeit, vom Gesetz erfordert, in uns erfullet wurde, die wir nun nicht nach dem Fleische wandeln sondern nach dem Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Denn die da fleischlich sind, die sind fleischlich gesinnet; die abergeistlich sind, die sind geistlich gesinnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Aber fleischlich gesinnet sein ist der Tod, und geistlich gesinnet sein ist Leben und Friede.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Denn fleischlich gesinnet sein ist eine Feindschaft wider Gott, sintemal es dem Gesetze Gottes nicht untertan ist; denn es vermag es auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Die aber fleischlich sind, mogen Gott nicht gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Ihr aber seid nicht fleischlich, sondern geistlich, so anders Gottes Geist in euch wohnet. Wer aber Christi Geist nicht hat der ist nicht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'So aber Christus in euch ist so ist der Leib zwar tot urn der Sunde willen; der Geist aber ist das Leben urn der Gerechtigkeit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'So nun der Geist des, der Jesum von den Toten auferwecket hat, in euch wohnet, so wird auch derselbige, der Christum von den Toten auferwecket hat, eure sterblichen Leiber lebendig machen urn deswillen, daß sein Geist in euch wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'So sind wir nun, liebe Bruder, Schuldner nicht dem Fleisch, daß wir nach dem Fleisch leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Denn wo ihr nach dem Fleisch lebet, so werdet ihr sterben müssen; wo ihr aber durch den Geist des Fleisches Geschafte totet, so werdet ihr leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Denn welche der Geist Gottes treibet, die sind Gottes Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Denn ihr habt nicht einen knechtischen Geist empfangen, daß ihr euch abermal furchten mul Jtet, sondern ihr habt einen kindlichen Geist empfangen, durch welchen wir rufen: Abba, lieber Vater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Derselbige Geist gibt Zeugnis unserm Geist, dafi wir Gottes Kinder sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Sind wir denn Kinder, so sind wir auch Erben, namlich Gottes Erben und Miterben Christi, so wir anders mit leiden, auf daß wir auch mit zur Herrlichkeit erhoben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Denn ich halte es dafur, dafi dieser Zeit Leiden der Herrlichkeit nicht wert sei, die an uns soil offenbaret werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Denn das angstliche Harren der Kreatur wartet auf die Offenbarung der Kinder Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'sintemal die Kreatur unterworfen ist der Eitelkeit ohne ihren Willen, sondern urn deswillen, dersie unterworfen hat auf Hoffnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Denn auch die Kreatur frei werden wird von dem Dienst des verganglichen Wesens zu der herrlichen Freiheit der Kinder Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Denn wirwissen, daß aile Kreatur sehnet sich mit uns und angstet sich noch immerdar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Nicht allein aber sie, sondern auch wir selbst, die wir haben des Geistes Erstlinge, sehnen uns auch bei uns selbst nach der Kindschaft und warten auf unsers Leibes Erlosung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Denn wir sind wohl selig, doch in der Hoffnung. Die Hoffnung aber, die man siehet, ist nicht Hoffnung; denn wie kann man des, hoffen, das man siehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'So wir aber des hoffen, das wir nicht sehen, so warten wir sein durch Geduld.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Desselbigengleichen auch der Geist hüft unserer Schwachheit auf. Denn wir wissen nicht, was wir beten sollen, wie sich\'s gebuhret, sondern der Geist selbst vertritt uns aufs beste mit unaussprechlichem Seufzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Der aber die Herzen forschet, der weifi, was des Geistes Sinn sei; denn er vertritt die Heiligen nach dem, was Gott gefallt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Wirwissen aber, dafi denen, die Gott lieben, aile Dinge zum besten dienen, die nach dem Vorsatz berufen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Denn welche er zuvor versehen hat, die hat er auch verordnet, daß sie gleich sein sollten dem Ebenbilde seines Sohns, auf dafi derselbige der Erstgeborne sei untervielen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Welche er aber verordnet hat, die hat er auch berufen; welche er aber berufen hat, die hat er auch gerecht gemacht; welche er aber hat gerecht gemacht, die hat er auch herrüch gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Was wollen wir denn hiezu sagen? Ist Gott fur uns, wer mag wider uns sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Welcher auch seines eigenen Sohnes nicht hat verschont, sondern hat ihn fur uns aile dahingegeben, wie sollte er uns mit ihm nicht alles schenken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Wer will die Auserwahlten Gottes beschuldigen? Gott ist hier, der da gerecht macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Wer will verdammen? Christus ist hier, der gestorben ist, ja vielmehr, der auch auferwecket ist, welcher ist zur Rechten Gottes und vertritt uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Wer will uns scheiden von der Liebe Gottes? T rübsal Oder Angst Oder Verfolgung Oder Hunger Oder Blofie Oder Fahrlichkeit Oder Schwert?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Wie geschrieben stehet: Um deinetwillen werden wir getotet den ganzen Tag; wir sind geachtet fur Schlachtschafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Aber in dem allem überwinden wir weit um deswillen, der uns geliebet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Denn ich bin gewili, daß weder Tod noch Leben, weder Engel noch Furstentum noch Gewalt, weder Gegenwartiges noch Zukunftiges,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'weder Hohes noch Tiefes noch keine andere Kreatur mag uns scheiden von der Liebe Gottes, die in Christo Jesu ist, unserm Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Ich sage die Wahrheit in Christo und luge nicht, des mir Zeugnis gibt mein Gewissen in dem Heiligen Geist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'daß ich grolie Traurigkeit und Schmerzen ohne Unterlali in meinem Herzen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Ich habe gewunschet, verbannet zu sein von Christo fur meine Bruder, die meine Gefreundeten sind nach dem Fleisch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'die da sind von Israel, welchen gehort die Kindschaft und die Herrlichkeit und der Bund und das Gesetz und der Gottesdienst und die Verheiliung;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'welcher auch sind die Vater, aus welchen Christus herkommt nach dem Fleische, der da ist Gott uber alles, gelobet in Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Aber nicht sage ich solches, daß Gottes Wort darum aus sei. Denn es sind nicht alle Israelites die von Israel sind;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'auch nicht alle, die Abrahams Same sind, sind darum auch Kinder, sondern: In Isaak soli dir der Same genannt sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Das ist, nicht sind das Gottes Kinder, die nach dem Fleisch Kinder sind, sondern die Kinder der Verheiliung werden fur Samen gerechnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Denn dies ist ein Wort der Verheifiung, da er spricht: Um diese Zeit will ich kommen, und Sara soil einen Sohn haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Nicht allein aber ist\'s mit dem also, sondern auch, da Rebecka von dem einigen Isaak, unserm Vater, schwanger ward;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'ehe die Kinder geboren waren und weder Gutes noch Boses getan hatten, auf daß der Vorsatz Gottes bestunde nach der Wahl, ward zu ihr gesagt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'nicht aus Verdienst der Werke, sondern aus Gnaden des Berufes, also: Der Groliere soil dienstbar werden dem Kleinern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'wie denn geschrieben stehet: Jakob habe ich geliebet, aber Esau habe ich gehasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Was wollen wir denn hiersagen? Ist denn Gott ungerecht? Das sei feme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Denn er spricht zu Mose: Welchem ich gnadig bin, dem bin ich gnadig, und welches ich mich erbarme, des erbarme ich mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'So liegt es nun nicht an jemandes Wollen Oder Laufen, sondern an Gottes Erbarmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Denn die Schrift sagt zu Pharao: Eben darum hab\' ich dich erweckt, daß ich an dir meine Macht erzeige, auf daß mein Name verkundiget werde in alien Landen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'So erbarmet er sich nun; welches er will, und verstocket, welchen er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'So sagest du zu mir: Was schuldiget er denn uns? Wer kann seinem Willen widerstehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Ja, lieber Mensch, wer bist du denn, daß du mit Gott rechten willst? Spricht auch ein Werk zu seinem Meister: Warum machst du mich also?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Hat nicht ein Topfer Macht, aus einem Klumpen zu machen ein Fali zu Ehren und das andere zu Unehren?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Derhalben, da Gott wollte Zorn erzeigen und kundtun seine Macht, hat er mit grolier Geduld getragen die Gefalie des Zorns, die da zugerichtet sind zur Verdammnis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'auf daß er kundtate den Reichtum seiner Herrlichkeit an den Gefalien der Barmherzigkeit, die er bereitet hat zur Herrlichkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'welche er berufen hat, namlich uns, nicht allein aus den Juden, sondern auch aus den Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Wie er denn auch durch Hosea spricht: Ich will das mein Volk heilien, das nicht mein Volk war, und meine Liebe, die nicht die Liebe war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Und soli geschehen, an dem Ort, da zu ihnen gesagt ward: Ihr seid nicht mein Volk, sollen sie Kinder des lebendigen Gottes genannt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Jesaja aber schreiet fur Israel: Wenn die Zahl der Kinder von Israel würde sein wie der Sand am Meer, so wird doch das Ubrige selig werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Denn es wird ein Verderben und Steuern geschehen zur Gerechtigkeit, und der Herr wird dasselbige Steuern tun auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Und wie Jesaja davor sagt: Wenn uns nicht der Herr Zebaoth hatte lassen Samen überbleiben, so waren wir wie Sodom worden und gleichwie Gomorra.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Was wollen wir nun hier sagen? Das wollen wir sagen: Die Heiden, die nicht haben nach der Gerechtigkeit gestanden, haben die Gerechtigkeit erlanget; ich sage aber von der Gerechtigkeit, die aus dem Glauben kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Israel aber hat dem Gesetz der Gerechtigkeit nachgestanden und hat das Gesetz der Gerechtigkeit nicht überkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Warum das? Darum, daß sie es nicht aus dem Glauben, sondern als aus den Werken des Gesetzes suchen. Denn sie haben sich gestolien an den Stein des Anlaufens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'wie geschrieben stehet: Siehe da, ich lege in Zion einen Stein des Anlaufens und einen Fels des Argernisses; und wer an ihn glaubet, der soil nicht zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Liebe Bruder, meines Herzens Wunsch ist, und flehe auch zu Gott fur Israel, dafi sie selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Denn ich gebe ihnen das Zeugnis, daß sie eifern um Gott, aber mit Unverstand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Denn sie erkennen die Gerechtigkeit nicht, die vor Gott gilt, und trachten, ihre eigene Gerechtigkeit aufzurichten, und sind also der Gerechtigkeit, die vor Gott gilt, nicht untertan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Denn Christus ist des Gesetzes Ende; wer an den glaubet, der ist gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Mose schreibt wohl von der Gerechtigkeit, die aus dem Gesetz kommt: Welcher Mensch dies tut, der wird darinnen leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Aber die Gerechtigkeit aus dem Glauben spricht also: Sprich nicht in deinem Herzen: Wer will hinauf gen Himmel fahren? (Das ist nichts anderes, denn Christum herabholen.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Oder: Wer will hinab in die Tiefe fahren? (Das ist nichts anderes, denn Christum von den Toten holen.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Aber was sagt sie? Das Wort ist dir nahe, namlich in deinem Munde und in deinem Herzen. Dies ist das Wort vom Glauben, das wir predigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Denn so du mit deinem Munde bekennest Jesum, daß er der Herr sei, und glaubest in deinem Herzen, daß ihn Gott von den Toten auferweckt hat, so wirst du selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Denn so man von Herzen glaubet, so wird man gerecht, und so man mit dem Munde bekennet, so wird man selig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Denn die Schrift spricht: Wer an ihn glaubet, wird nicht zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Es ist hier kein Unterschied unter Juden und Griechen; es ist aller zumal ein Herr, reich über alle, die ihn anrufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Denn wer den Namen des Herrn wird anrufen, soil selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Wie sollen sie aber anrufen, an den sie nicht glauben? Wie sollen sie aber glauben, von dem sie nichts gehoret haben? Wie sollen sie aber horen ohne Prediger?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Wie sollen sie aber predigen, wo sie nicht gesandt werden? wie denn geschrieben stehet: Wie lieblich sind die Fufie derer, die den Frieden verkundigen, die das Gute verkundigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Aber sie sind nicht alle dem Evangelium gehorsam. Denn Jesaja spricht: Herr, wer glaubet unserm Predigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'So kommt der Glaube aus der Predigt, das Predigen aber durch das Wort Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Ich sage aber: Haben sie es nicht gehorte? Zwar es ist je in alle Lande ausgegangen ihr Schall und in alle Welt ihre Worte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ich sage aber: Hat es Israel nicht erkannt? Der erste Mose spricht: Ich will euch eifern machen über dem, das nicht mein Volk ist, und über einem unverstandigen Volk will ich euch erzurnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Jesaja aber darf wohl so sagen: Ich bin erfunden von denen, die mich nicht gesucht haben, und bin erschienen denen die nicht nach mir gefragt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Zu Israel aber spricht er: Den ganzen Tag habe ich meine Hande ausgestrecket zu dem Volk, das sich nicht sagen lasset und widerspricht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'So sage ich nun: Hat denn Gott sein Volk verstoften? Das sei feme! Denn ich bin auch ein Israelit von dem Samen Abrahams, aus dem Geschlecht Benjamin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gott hat sein Volk nicht verstoften, welches er zuvor versehen hat. Oder wisset ihr nicht, was die Schrift sagt von Elia, wie er tritt vor Gott wider Israel und spricht:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Herr, sie haben deine Propheten getotet und haben deine Altare ausgegraben; und ich bin allein uberblieben, und sie stehen mir nach meinem Leben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Aber was sagt ihm die gdttliche Antwort? Ich habe mir lassen uberbleiben siebentausend Mann, die nicht haben ihre Kniee gebeuget vor dem Baal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Also gehet\'s auch jetzt zu dieser Zeit mit diesen Uberbliebenen nach der Wahl der Gnaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Ist\'s aber aus Gnaden, so ist\'s nicht aus Verdienst der Werke, sonstwurde Gnade nicht Gnade sein. Ist\'s aber aus Verdienst der Werke, so ist die Gnade nichts, sonst ware Verdienst nicht Verdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Wie denn nun? Was Israel sucht, das erlangt es nicht; die Wahl aber erlanget es. Die andern sind verstockt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'wie geschrieben stehet: Gott hat ihnen gegeben einen erbitterten Geist, Augen, daß sie nicht sehen, und Ohren, daß sie nicht horen, bis auf den heutigen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Und David spricht: Laft ihren Tisch zu einem Strick werden und zu einer Beruckung und zum Argernis und ihnen zur Vergeltung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Verblende ihre Augen, daß sie nicht sehen, und beuge ihren Rücken allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'So sage ich nun: Sind siedarum angelaufen, daß sie fallen sollten? Das sei feme! Sondern aus ihrem Fall ist den Heiden das Heil widerfahren, auf daß sie denen nacheifern sollten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Denn so ihr Fall der Welt Reichtum ist, und ihr Schade ist der Heiden Reichtum, wieviel mehr, wenn ihre Zahl voll würde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Mit euch Heiden rede ich; denn dieweil ich der Heiden Apostel bin, will ich mein Amt preisen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'ob ich mochte die, so mein Fleisch sind, zu eifern reizen und ihrer etliche selig machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Denn so ihr Verlust der Welt Versohnung ist, was ware das anders, denn das Leben von den Toten nehmen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ist der Anbruch heilig, so istauch der Teig heilig, und so die Wurzel heilig ist, so sind auch die Zweige heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Ob aber nun etliche von den Zweigen zerbrochen sind, und du, da du ein wilder Olbaum warest, bist unter sie gepfropfet und teilhaftig worden der Wurzel und des Safts im Olbaum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'so rühme dich nicht wider die Zweige. Ruhmest du dich aber wider sie, so sollst du wissen, daß du die Wurzel nicht tragest, sondern die Wurzel traget dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Sosprichstdu: Die Zweige sind zerbrochen, daß ich hineingepfropfet wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Ist wohl geredet. Sie sind zerbrochen um ihres Unglaubens willen; du stehest aber durch den Glauben. Sei nicht stolz, sondern furchte dich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Hat Gott der naturlichen Zweige nicht verschonet, daß er vielleicht dein auch nicht verschone.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Darum schaue die Gute und den Ernst Gottes: den Ernst an denen, die gefallen sind, die Gute aber an dir, soferne du an der Gute bleibest; sonst wirst du auch abgehauen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Und jene, so sie nicht bleiben in dem Unglauben, werden sie eingepfropfet werden; Gott kann sie wohl wieder ein pfropfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Denn so du aus dem Olbaum, der von Natur wild war, bist ausgehauen und wider die Natur in den guten Olbaum gepfropfet, wieviel mehr werden die naturlichen eingepfropfet in ihren eigenen Olbaum!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Ich will euch nicht verhalten, liebe Brüder, dieses Geheimnis, auf daß ihr nicht stolz seid. Blindheit ist Israel einesteils widerfahren, so lange, bis die Fülle der Heiden eingegangen sei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'und also das ganze Israel selig werde, wie geschrieben stehet: Es wird kommen aus Zion, der da erlose und abwende das gottlose Wesen von Jakob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Und dies ist mein Testament mit ihnen, wenn ich ihre Sünden werde weg nehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Nach dem Evangelium halte ich sie fur Feinde um euretwillen; aber nach der Wahl habe ich sie lieb um der Vater willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Gottes Gaben und Berufung mogen ihn nicht gereuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Denn gleicherweise, wie auch ihr nicht habt geglaubet an Gott, nun aber habt ihr Barmherzigkeit überkommen uber ihrem Unglauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'also auch jene haben jetzt nicht wollen glauben an die Barmherzigkeit, die euch widerfahren ist, auf daß sie auch Barmherzigkeit uberkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Denn Gott hat alles beschlossen unter den Unglauben, auf daß er sich aller erbarme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, '0 welch eine Tiefe des Reichtums, beide, der Weisheit und Erkenntnis Gottes! Wie gar unbegreiflich sind seine Gerichte und unerforschlich seine Wege!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Denn wer hat des Herrn Sinn erkannt? Oder wer ist sein Ratgeber gewesen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Oder wer hat ihm etwas zuvor gegeben, das ihm werde wieder vergolten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Denn von ihm und durch ihn und zu ihm sind alle Dinge. Ihm sei Ehre in Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Ich ermahne euch, liebe Bruder, durch die Barmherzigkeit Gottes, daß ihr eure Leiber begebet zum Opfer, das da lebendig, heilig und Gott wohlgefallig sei, welches sei euer vernunftiger Gottesdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Und stellet euch nicht dieser Welt gleich, sondern verandert euch durch Erneuerung eures Sinnes, auf daß ihr prufen moget, welches da sei der gute, der wohlgefallige und der vollkommene Gotteswille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Denn ich sage durch die Gnade, die mir gegeben ist, jedermann unter euch, daß niemand weiter von sich halte, denn sich\'s gebuhrt zu halten, sondern daß von sich maßiglich halte, ein jeglicher nachdem Gott ausgeteilet hat das Maß des Glaubens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Denn gleicherweise, als wir in einem Leibe viel Glieder haben, aber alle Glieder nicht einerlei Geschaft haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'also sind wir viele ein Leib in Christo; aber untereinander ist einer des andern Glied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Und haben mancherlei Gaben nach der Gnade, die uns gegeben ist.Hat jemand Weissagung, so sei sie dem Glauben ahnlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Hat jemand ein Amt so warte er des Amts. Lehret jemand, so warte er der Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Ermahnet jemand, so warte er des Ermahnens. Gibt jemand, so gebe er einfaltiglich. Regieret jemand, so sei er sorgfaltig. Ubet jemand Barmherzigkeit, so tu er\'s mit Lust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Die Liebe sei nicht falsch. Hasset das Arge, hanget dem Guten an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Die bruderliche Liebe untereinander sei herzlich. Einer komme dem andern mit Ehrerbietung zuvor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Seid nicht trage, was ihr tun sollt. Seid brunstig im Geiste. Schicket euch in die Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Seid frohlich in Hoffnung; geduldig in Trubsal, haltet an am Gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Nehmet euch der Heiligen Notdurft an. Herberget gerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Segnet, die euch verfolgen; segnet, und fluchet nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Freuet euch mit den Frohlichen und weinet mit den Weinenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Habt einerlei Sinn untereinander. Trachtet nicht nach hohen Dingen, sondern haltet euch herunter zu den Niedrigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Haltet euch nicht selbst fur klug. Vergeltet niemand Boses mit Bosem. Fleißiget euch der Ehrbarkeit gegen jedermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, '1st es mbglich, soviel an euch ist, so habt mit alien Menschen Frieden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Racheteuch selber nicht, meine Liebsten, sondern gebet Raum dem Zorn; denn es stehet geschrieben: Die Rache ist mein; ich will vergelten, spricht der Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'So nun deinen Feind hungert, so speise ihn; durstet ihn, so tranke ihn. Wenn du das tust, so wirst dufeurige Kohlen aufsein Hauptsammeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Laß dich nicht das Bose uberwinden, sondern uberwinde das Bose mit Gutem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Jedermann sei untertan der Obrigkeit, die Gewalt fiber ihn hat. Denn es ist keine Obrigkeit ohne von Gott; wo aber Obrigkeit ist, die ist von Gott verordnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Wer sich nun wider die Obrigkeit setzet, der widerstrebet Gottes Ordnung; die aber widerstreben, werden uber sich ein Urteil empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Denn die Gewaltigen sind nicht den guten Werken, sondern den bosen zu furchten. Willst du dich aber nicht furchten vor der Obrigkeit, so tue Gutes, so wirst du Lob von derselbigen haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'denn sie ist Gottes Dienerin dirzu gut. Tust du aber Boses, so furchte dich; denn sie tragt das Schwert nicht umsonst; sie ist Gottes Dienerin, eine Racherin zur Strafe uber den, der Boses tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'So seid nun aus Not untertan, nicht allein um der Strafe willen, sondern auch um des Gewissens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Derhalben müsset ihr auch Schofi geben; denn sie sind Gottes Diener, die solchen Schutz sollen handhaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'So gebet nun jedermann, was ihr schuldig seid: Schofie dem der Scholi gebuhrt; Zoll, dem der Zoll gebuhrt; Furcht dem die Furcht gebuhrt; Ehre, dem die Ehre gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Seid niemand nichts schuldig, denn daß ihr euch untereinander liebet; denn wer den andern liebet, der hat das Gesetz erfullet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Denn das da gesagt ist: Du sollst nicht ehebrechen; du sollst nicht toten; du sollst nicht stehlen; du sollst nicht falsch Zeugnis geben; dich soil nichts gelusten, und so ein ander Gebot mehr ist, das wird in diesem Wort verfasset: Du sollst deinen Nachsten lieben wie dich selbst:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Die Liebe tut dem Nachsten nichts Boses. So ist nun die Liebe des Gesetzes Erfullung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Und weil wir solches wissen, namlich die Zeit, daß die Stunde da ist, aufzustehen vom Schiaf, sintemal unser Heil jetzt naher ist, denn da wir\'s glaubten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'die Nachtistvergangen, der Tag aber herbeikommen: so lasset uns ablegen die Werke der Finsternis und anlegen die Waffen des Lichtes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Lasset uns ehrbarlich wandeln, ais am Tage, nicht in Fressen und Saufen, nicht in Kammern und Unzucht, nicht in Hader und Neid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'sondern ziehet an den Herrn Jesum Christum und wartet des Leibes, doch also, daß er nicht geil werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Den Schwachen im Glauben nehmet auf und verwirret die Gewissen nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Einer glaubt, er moge allerlei essen; welcher aber schwach ist, der isset Kraut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Welcher isset, der verachte den nicht, der da nicht isset; und welcher nicht isset, der richte den nicht, der da isset; denn Gott hat ihn aufgenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Wer bist du, daß du einen fremden Knecht richtest? Er stehet Oder fallet seinem Herrn. Er mag aber wohl aufgerichtet werden; denn Gott kann ihn Wohl aufrichten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Einer halt einen Tag vor dem andern; der andere aber halt alle Tage gleich. Ein jeglicher sei seiner Meinung gewifi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Welcher auf die Tage halt, der tut\'s dem Herrn; und welcher nichts darauf halt, der tut\'s auch dem Herrn. Welcher isset, der isset dem Herrn; denn er danket Gott. Welcher nicht isset, der isset dem Herrn nicht und danket Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Denn unser keiner lebt sich selber, und keiner stirbt sich selber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Leben wir, so leben wir dem Herrn; sterben wir, so sterben wir dem Herrn. Darum, wir leben Oder sterben, so sind wir des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Denn dazu ist Christus auch gestorben und auferstanden und wieder lebendig worden, daß er fiber Tote und Lebendige Herr sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Du aber, was richtest du deinen Bruder? Oder du anderer, was verachtest du deinen Bruder? Wir werden alle vor dem Richterstuhi Christi dargestellt werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'nachdem geschrieben stehet: So wahr ais ich lebe, spricht der Herr, mir sollen alle Kniee gebeuget werden, und alle Zungen sollen Gott bekennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'So wird nun ein jeglicher fur sich selbst Gott Rechenschaft geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Darum lasset uns nicht mehr einer den andern richten, sondern das richtet vielmehr, daß niemand seinem Bruder einen Anstoü Oder Argernis darstelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Ich weili und bin\'s gewifi in dem Herrn Jesu, daß nichts gemein ist an sich selbst; ohne der es rechnet fur gemein, demselbigen ist\'s gemein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'So aber dein Bruder uber deine Speise betrubet wird, so wandelst du schon nicht nach der Liebe. Lieber, verderbe den nicht mit deiner Speise, um welchen willen Christus gestorben ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Darum schaffet, daß euer Schatz nicht verlastert werde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Denn das Reich Gottes ist nicht Essen und Trinken, sondern Gerechtigkeit und Friede und Freude in dem Heiligen Geiste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Wer darinnen Christo dienet, der ist Gott gefallig und den Menschen wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Darum lasset uns dem nachstreben, was zum Frieden dienet, und was zur Besserung untereinander dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Lieber, verstore nicht um der Speise willen Gottes Werk! Es ist zwar alles rein, aber es ist nicht gut dem, der es isset mit einem Anstoß seines Gewissens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Es ist besser, du essest kein Fleisch und trinkest keinen Wein Oder das, daran sich dein Bruder stoßet Oder argert Oder schwach wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Hast du den Glauben, so habe ihn bei dir selbst vor Gott. Selig ist, der sich selbst kein Gewissen macht in dem, was er annimmt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Wer aber daruber zweifelt und isset doch, der ist verdammt; denn es gehet nicht aus dem Glauben. Was aber nicht aus dem Glauben gehet, das ist Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Wiraber, die wir stark sind, sollen der Schwachen Gebrechlichkeit tragen und nicht Gefallen an uns selber haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Es stelle sich aber ein jeglicher unter uns also, daß er seinem Nachsten gefalle zum Guten, zur Besserung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Denn auch Christus nicht an sich selber Gefallen hatte, sondern wie geschrieben stehet: Die Schmahungen derer, die dich schmahen, sind uber mich gefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Was aber zuvor geschrieben ist, das ist uns zur Lehre geschrieben, auf daß wir durch Geduld und Trost der Schrift Hoffnung haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Gott aber der Geduld und des Trostes gebe euch, daß ihreinerlei gesinnet seid untereinander nach Jesu Christo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'auf daß ihr einmutiglich mit einem Munde lobet Gott und den Vater unsers Herm Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Darum nehmet euch untereinander auf, gleichwie euch Christus hat aufgenommen zu Gottes Lobe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Ich sage aber, daß Jesus Christus sei ein Diener gewesen der Beschneidung um der Wahrheit willen Gottes, zu bestatigen die Verheißung, den Vatern geschehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'daß die Heiden aber Gott loben um der Barmherzigkeit willen, wie geschrieben stehet: Darum will ich dich loben unter den Heiden und deinem Namen singen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Und abermal spricht er: Freuet euch, ihr Heiden, mit seinem Volk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Und abermal: Lobet den Herm, alle Heiden, und preiset ihn, alle Volker!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Und abermal spricht Jesaja: Es wird sein die Wurzel Jesse, und der auferstehen wird, zu herrschen uber die Heiden; auf den werden die Heiden hoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Gott aber der Hoffnung erfulle euch mitaller Freude und Frieden im Glauben, daß ihr vollige Hoffnung habet durch die Kraft des Heiligen Geistes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Ich weiß aber fast wohl von euch, liebe Bruder, daß ihr selbst voll Gütigkeit seid, erfullet mit alter Erkenntnis, daß ihr euch untereinander konnet ermahnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Ich hab\'s aber dennoch gewagt und euch etwas wollen schreiben, liebe Bruder, euch zu erinnern, um der Gnade willen, die mir von Gott gegeben ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'daß ich soil sein ein Diener Christi unter den Heiden zu opfern das Evangelium Gottes, auf daß die Heiden ein Opfer werden, Gott angenehm, geheiliget durch den Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Darum kann ich mich ruhmen in Jesu Christo, daß ich Gott diene.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Denn ich dürfte nicht etwas reden, wo dasselbige Christus nicht durch mich wirkte, die Heiden zum Gehorsam zu bringen durch Wort und Werk,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'durch Kraft der Zeichen und Wunder und durch Kraft des Geistes Gottes, also daß ich von Jerusalem an und umher bis an lllyrikum alles mit dem Evangelium Christi erfullet habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'und mich sonderlich geflissen, das Evangelium zu predigen, wo Christi Name nicht bekannt war, auf daß ich nicht auf einen fremden Grund bauete');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'sondern wie geschrieben stehet: Welchen nicht ist von ihm verkundiget, die sollen\'s sehen, und welche nicht gehoret haben, sollen\'s verstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Das ist auch die Sache, darum ich vielmal verhindert bin, zu euch zu kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nun ich aber nicht mehr Raum habe in diesen Landern, habe aber Verlangen, zu euch zu kommen, von vielen Jahren her:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'wenn ich reisen werde nach Spanien, will ich zu euch kommen. Denn ich hoffe, daß ich da durchreisen und euch sehen werde und von euch dorthin geleitet werden moge, so doch, daß ich zuvor mich ein wenig mit euch ergotze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Nun aber fahre ich hin gen Jerusalem den Heiligen zu Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Denn die aus Mazedonien und Achaja haben williglich eine gemeine Steuer zusammengelegt den armen Heiligen zu Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Sie haben\'s williglich getan und sind auch ihre Schuldner. Denn so die Heiden sind ihrer geistlichen Güter teilhaftig worden, ist\'s billig, daß sie ihnen auch in leiblichen Gutern Dienst beweisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Wenn ich nun solches ausgerichtet und ihnen diese Frucht versiegelt habe, will ich durch euch nach Spanien ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Ich weiß aber, wenn ich zu euch komme, daß ich mit vollem Segen des Evangeliums Christi kommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Ich ermahne euch aber, liebe Bruder, durch unsern Herrn Jesum Christum und durch die Liebe des Geistes, daß ihr mir helfet kampfen mit Beten fur mich zu Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'auf dafi ich errettet werde von den Unglaubigen in Judaa, und daß mein Dienst, den ich gen Jerusalem tue, angenehm werde den Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'auf daß ich mit Freuden zu euch komme durch den Willen Gottes und mich mit euch erquicke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Der Gott aber des Friedens sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Ich befehle euch aber unsere Schwester Phobe, welche ist am Dienste der Gemeinde zu Kenchrea,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'daß ihrsie aufnehmet in dem Herrn, wie sich\'s ziemet den Heiligen, und tut ihr Beistand in allem Geschafte, darinnen sie euer bedarf. Denn sie hat auch vielen Beistand getan, auch mir selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Gruliet die Priscilla und den Aquila, meine Gehilfen in Christo Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'welche haben fur mein Leben ihre Halse dargegeben, welchen nicht allein ich danke, sondern alle Gemeinden unterden Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Auch gruliet die Gemeinde in ihrem Hause. Gruliet Epanetum, meinen Liebsten, welcher ist der Erstling unter denen aus Achaja in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Gruliet Maria, welche viel Mühe und Arbeit mit uns gehabt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Gruliet den Andronikus und den Junias, meine Gefreundeten und meine Mitgefangenen, welche sind beruhmte Apostel und vor mir gewesen in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Gruliet Amplias, meinen Lieben in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Gruliet Urban, unsern Gehilfen in Christo und Stachys, meinen Lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Gruliet Apelles, den Bewahrten in Christo. Gruliet, die da sind von des Aristobulus Gesinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Gruliet Herodionus, meinen Gefreundeten. Gruliet, die da sind von des Narcissus Gesinde in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Gruliet die Tryphana und die Tryphosa, welche in dem Herrn gearbeitet haben. Gruliet die Persida, meine Liebe, welche in dem Herrn viel gearbeitet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Gruliet Rufus, den Auserwahlten in dem Herrn, und seine und meine Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Gruliet Asynkritus und Phlegon, Hermas, Patrobas, Hermes und die Bruder bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Gruliet Philologus und die Julia, Nereus und seine Schwester und Olympas und alle Heiligen bei ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Gruliet euch untereinander mit dem heiligen Kuli. Es grufien euch die Gemeinden Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Ich ermahne aber euch, liebe Bruder, daß ihr aufsehet auf die, die da Zertrennung und Argernis anrichten neben der Lehre, die ihr gelernet habt, und weichet von denselbigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Denn solche dienen nicht dem Herr Jesu Christo, sondern ihrem Bauche; und durch sülie Worte und prachtige Rede verfuhren sie die unschuldigen Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Denn euer Gehorsam ist unter jedermann auskommen. Derhalben freue ich mich uber euch. Ich will aber, daß ihr weise seid aufs Gute, aber einfaltig aufs Bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Aber der Gott des Friedens zertrete den Satan unter eure Fülie in kurzem! Die Gnade unsers Herrn Jesu Christi sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Es grufien euch Timotheus, mein Gehilfe, und Lucius und Jason und Sosipater, meine Gefreundeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Ich, Tertius, grulie euch, der ich diesen Brief geschrieben habe, in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Es gruliet euch Gajus, mein und derganzen Gemeinde Wirt. Es gruliet euch Erastus, der Stadt Rentmeister, und Quartus, der Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Die Gnade unsers Herrn Jesu Christi sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Dem aber, der euch starken kann laut meines Evangeliums und Predigt von Jesu Christo, durch welche das Geheimnis offenbaret ist, das von der Welt her verschwiegen gewesen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'nun aber offenbaret, auch kundgemacht durch der Propheten Schriften aus Befehl des ewigen Gottes, den Gehorsam des Glaubens aufzurichten unter alien Heiden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'demselbigen Gott, der allein weise ist, sei Ehre durch Jesum Christum in Ewigkeit! Amen. Der erste Brief des Paulus an die Korinther');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, berufen zum Apostel Jesu Christi durch den Willen Gottes, und Bruder Sosthenes:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Der Gemeinde Gottes zu Korinth, den Geheiligten in Christo Jesu, den berufenen Heiligen samt alien denen, die anrufen den Namen unsers Herrn Jesu Christi an alien ihren und unsern Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Gnade sei miteuch und Friede von Gott, unserm Vater, und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Ich danke meinem Gott aliezeit eurethalben fur die Gnade Gottes, die euch gegeben ist in Christo Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'daß ihr seid durch ihn an alien Stricken reich gemacht, an alter Lehre und in aller Erkenntnis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'wie denn die Predigt von Christo in euch kraftig worden ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'also daß ihr keinen Mangel habt an irgendeiner Gabe und wartet nur auf die Offenbarung unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'welcher auch wird euch test behalten bis ans Ende, daß ihr unstraflich seid auf den Tag unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Denn Gott ist treu, durch welchen ihr berufen seid zur Gemeinschaft seines Sohnes Jesu Christi, unsers Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Ich ermahne euch aber, liebe Bruder, durch den Namen unsers Herrn Jesu Christi; daß ihr allzumal einerlei Rede fuhret und lasset nicht Spaltungen unter euch sein, sondern haltet fest aneinander in einem Sinn und in einerlei Meinung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Denn miristvorkommen, liebe Bruder, durch die aus Chloes Gesinde von euch, daß Zank unter euch sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ich sage aber davon, daß unter euch einer spricht: Ich bin paulisch; derandere: Ich bin apollisch; der dritte: Ich bin kephisch; der vierte: Ich bin christisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Wie? ist Christus nun zertrennet? Ist denn Paulus fur euch gekreuziget, Oder seid ihr auf des Paulus Namen getauft?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Ich danke Gott, daß ich niemand unter euch getauft habe aufter Crispus und Gajus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'daß nicht jemand sagen moge, ich hatte auf meinen Namen getauft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Ich habe aber auch getauft des Stephanas Hausgesinde; danach weift ich nicht, ob ich etliche andere getauft habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Denn Christus hat mich nicht gesandt zu taufen, sondern das Evangelium zu predigen, nicht mit klugen Worten, auf daß nicht das Kreuz Christi zunichte werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Denn das Wort vom Kreuz isteine Torheit denen, die verloren werden; uns aber, die wir selig werden, ist es eine Gotteskraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Denn es stehet geschrieben: Ich will zunichte machen die Weisheit der Weisen, und den Verstand der Verstandigen will ich verwerfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Wo sind die Klugen? Wo sind die Schriftgelehrten? Wo sind die Weltweisen? Hat nicht Gott die Weisheit dieser Welt zur Torheit gemacht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Denn dieweil die Welt durch ihre Weisheit Gott in seiner Weisheit nicht erkannte, gefiel es Gott wohl, durch torichte Predigt selig zu machen die, so daran glauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'sintemal die Juden Zeichen fordern, und die Griechen nach Weisheit fragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Wir aber predigen den gekreuzigten Christum, den Juden ein Argernis und den Griechen eine Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Denen aber, die berufen sind, beide, Juden und Griechen, predigen wir Christum gottliche Kraft und gdttliche Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Denn die gottliche Torheit ist weiser, denn die Menschen sind, und die gottliche Schwachheit ist starker, denn die Menschen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Sehet an, liebe Bruder, euren Beruf: nicht viel Weise nach dem Fleisch, nicht viel Gewaltige, nicht viel Edle sind berufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'sondern was toricht ist vor der Welt, das hat Gott erwahlet, daß er die Weisen zuschanden machte; und was schwach ist vor der Welt, das hat Gott erwahlet, daß er zuschanden machte, was stark ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'und das Unedle vor der Welt und das Verachtete hat Gott erwahlet, und das da nichts ist, daß er zunichte machte, was etwas ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'auf daß sich vor ihm kein Fleisch ruhme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Von welchem auch ihr herkommt in Christo Jesu, welcher uns gemacht ist von Gott zur Weisheit und zur Gerechtigkeit und zur Heiligung und zur Erlosung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'auf daß (wie geschrieben stehet), wer sich rühmet, der ruhme sich des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Und ich, liebe Bruder, da ich zu euch kam, kam ich nicht mit hohen Worten Oder hoher Weisheit, euch zu verkundigen die gottliche Predigt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Denn ich hielt mich nicht dafür, daß ich etwas wüftte unter euch ohne allein Jesum Christum, den Gekreuzigten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Und ich war bei euch mit Schwachheit und mit Furcht und mitgroftem Zittern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Und mein Wort und meine Predigt war nicht in vernunftigen Reden menschlicher Weisheit, sondern in Beweisung des Geistes und der Kraft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'auf daß euer Glaube bestehe nicht auf Menschenweisheit, sondern auf Gottes Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Wovon wir aber reden, das ist dennoch Weisheit bei den Vollkommenen; nicht eine Weisheit dieser Weit, auch nicht der Obersten dieser Welt, welche vergehen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'sondern wir reden von der heimlichen, verborgenen Weisheit Gottes, welche Gott verordnet hat vor der Welt zu unserer Herrlichkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'welche keiner von den Obersten dieser Welt erkannt hat; denn wo sie die erkannt hatten, hatten sie den Herrn der Herrlichkeit nicht gekreuziget;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'sondern wie geschrieben stehet: Das kein Auge gesehen hat und kein Ohr gehoret hat und in keines Menschen Herz kommen ist, das Gott bereitet hat denen, die ihn lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Uns aber hat es Gott offenbaret durch seinen Geist; denn der Geist erforschet alle Dinge, auch die Tiefen der Gottheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Denn welcher Mensch weili, was im Menschen ist, ohne der Geist des Menschen, der in ihm ist? Also auch weili niemand, was in Gott ist, ohne der Geist Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Wiraberhaben nicht empfangen den Geist der Welt, sondern den Geist aus Gott, daß wir wissen konnen, was uns von Gott gegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Welches wir auch reden, nicht mit Worten, welche menschliche Weisheit lehren kann, sondern mit Worten, die der Heilige Geist lehret, und richten geistliche Sachen geistlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Der naturliche Mensch abervernimmt nichts vom Geist Gottes; es ist ihm eine Torheit, und kann es nicht erkennen; denn es muli geistlich gerichtet sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Der Geistliche aber richtet alles und wird von niemand gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Denn wer hat des Herrn Sinn erkannt, oderwer will ihn unterweisen? Wir aber haben Christi Sinn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Und ich, liebe Bruder, konnte nicht mit euch reden als mit Geistlichen, sondern als mit Fleischlichen, wie mitjungen Kindern in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Milch habe ich euch zu trinken gegeben und nicht Speise; denn ihr konntet noch nicht; auch konnt ihr noch jetzt nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'dieweil ihr noch fleischlich seid. Denn sintemal Eifer und Zank und Zwietracht unter euch sind, seid ihr denn nicht fleischlich und wandelt nach menschlicher Weise?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Denn so einer sagt: Ich bin paulisch, der andere aber: Ich bin apollisch, seid ihr denn nicht fleischlich?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Wer ist nun Paulus? Wer ist Apollo? Diener sind sie, durch welche ihr seid glaubig worden, und dasselbige, wie der Herr einem jeglichen gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ich habe gepflanzet, Apollo hat begossen, aber Gott hat das Gedeihen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'So ist nun weder der da pflanzet, noch der da begielit, etwas, sondern Gott, der das Gedeihen gibt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Der aber pflanzet und der da begielit, ist einer wie der andere. Ein jeglicher aber wird seinen Lohn empfangen nach seiner Arbeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Denn wir sind Gottes Mitarbeiter; ihr seid Gottes Ackerwerk und Gottes Gebau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Ich von Gottes Gnaden, die mir gegeben ist, habe den Grund geiegt als ein weiser Baumeister; ein anderer bauet darauf. Ein jeglicher aber sehe zu, wie er darauf baue.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Einen andern Grund kann zwar niemand legen aulier dem, der geiegt ist, welcher ist Jesus Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'So aberjemand auf diesen Grund bauet Gold, Silber, Edelsteine, Holz, Heu, Stoppeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'so wird eines jeglichen Werk offenbar werden; der Tag wird\'s klar machen. Denn es wird durchs Feuer offenbar werden, und welcherlei eines jeglichen Werk sei, wird das Feuer bewahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Wird jemandes Werk bleiben, das er darauf gebauet hat, so wird er Lohn empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Wird aber jemandes Werk verbrennen, so wird er des Schaden leiden; er selbst aber wird selig werden, so doch wie durchs Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Wisset ihr nicht, daß ihr Gottes Tempel seid, und der Geist Gottes in euch wohnet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'So jemand den Tempel Gottes verderbet, den wird Gott verderben; denn der Tempel Gottes ist heilig; der seid ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Niemand betruge sich selbst! Welcher sich unter euch dünkt, weise zu sein, der werde ein Narr in dieser Welt, dafi er moge weise sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Denn dieser Welt Weisheit ist Torheit bei Gott. Denn es stehet geschrieben: Die Weisen erhaschet er in ihrer Klugheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Und abermal: Der Herr weili der Weisen Gedanken, daß sie eitel sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Darum ruhme sich niemand eines Menschen! Es ist alles euer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'es sei Paulus Oder Apollo, es sei Kephas Oder die Welt, es sei das Leben Oder der Tod, es sei das Gegenwartige Oder das Zukunftige: alles ist euer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Ihr aber seid Christi; Christus aber ist Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Dafur halte uns jedermann, namlich fur Christi Diener und Haushalter uber Gottes Geheimnisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Nun sucht man nicht mehr an den Haushaltern, denn daß sie treu erfunden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mir aber ist\'s ein Geringes, daß ich von euch gerichtet werde Oder von einem menschlichen Tage; auch richte ich mich selbst nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Ich bin mirwohl nichts bewulit, aberdarinnen bin ich nicht gerechtfertiget; der Herr ist\'s aber, der mich richtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Darum richtet nicht vor der Zeit, bis der Herr komme, welcher auch wird ans Licht bringen, was im Finstern verborgen ist, und den Rat der Herzen offenbaren; alsdann wird einem jeglichen von Gott Lob widerfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Solches aber, liebe Bruder, habe ich auf mich und Apollo gedeutet urn euretwillen, daß ihr an uns lernet, daß niemand hoher von sich halte, denn jetzt geschrieben ist, auf daß sich nicht einer wider den andern urn jemandes willen aufblase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Denn wer hat dich vorgezogen? Was hast du aber, das du nicht empfangen hast? So du es aber empfangen hast, was ruhmest du dich denn, als der es nicht empfangen hatte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Ihr seid schon satt worden; ihr seid schon reich worden; ihr herrschet ohne uns. Und wollte Gott, ihr herrschet, auf daß auch wir mit euch herrschen mochten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Ich halte aber, Gott habe uns Apostel fur die Allergeringsten dargestellet, als dem Tode ubergeben. Denn wir sind ein Schauspiel worden der Welt und den Engeln und den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Wir sind Narren um Christi willen, ihr aber seid klug in Christo; wir schwach, ihr aber stark; ihr herrlich, wir aber verachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Bis auf diese Stunde leiden wir Hunger und Durst und sind nackend und werden geschlagen und haben keine gewisse Statte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'und arbeiten und wirken mit unsern eigenen Handen. Man schilt uns, so segnen wir; man verfolgt uns, so dulden wir\'s, man lasted uns, so flehen wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Wir sind stets als ein Fluch der Welt und ein Fegopfer aller Leute.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Nicht schreibe ich solches, daß ich euch beschame, sondern ich ermahne euch als meine lieben Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Denn ob ihrgleich zehntausend Zuchtmeister hattet in Christo, so habt ihr doch nicht viele Vater. Denn ich habe euch gezeuget in Christo Jesu durch das Evangelium.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Darum ermahne ich euch: Seid meine Nachfolger!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Aus derselben Ursache habe ich Timotheus zu euch gesandt, welcher ist mein lieber und getreuer Sohn in dem Herm, dafi ereuch erinnere meiner Wege, die da in Christo sind, gleichwie ich an alien Enden in alien Gemeinden lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Es blahen sich etliche auf, als wurde ich nicht zu euch kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ich will aber gar kurzlich zu euch kommen, so der Herr will, und erlernen nicht die Wode der Aufgeblasenen, sondern die Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Denn das Reich Gottes stehet nicht in Woden, sondern in Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Was wollet ihr? Soil ich mit der Rute zu euch kommen Oder mit Liebe und sanftmutigem Geist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Es gehet ein gemein Geschrei, daß Hurerei unter euch ist, und eine solche Hurerei, da auch die Heiden nicht von zu sagen wissen, daß einer seines Vaters Weib habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Und ihr seid aufgeblasen und habt nicht vielmehr Leid getragen, auf daß, der das Werk getan hat, von euch getan wurde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Ich zwar, als der ich mit dem Leibe nicht da bin, doch mit dem Geist gegenwartig, habe schon als gegenwartig beschlossen uber den, den solches also getan hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'in dem Namen unsers Herrn Jesu Christi, in eurer Versammlung mit meinem Geist und mit der Kraft unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'ihn zu ubergeben dem Satan zum Verderben des Fleisches, auf daß der Geist selig werde am Tage des Herrn Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Euer Ruhm ist nicht fein. Wisset ihr nicht, daß ein wenig Sauerteig den ganzen Teig versaued?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Darum feget den alten Sauedeig aus, auf daß ihr ein neuer Teig seid, gleichwie ihr ungesaued seid. Denn wir haben auch ein Osterlamm, das ist Christus, fur uns geopferi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Darum lasset uns Ostern halten, nicht im alten Sauedeig, auch nicht im Sauerteig der Bosheit und Schalkheit, sondern in dem Suliteig der Lauterkeit und der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Ich habe euch geschrieben in dem Briefe, daß ihr nichts sollet zu schaffen haben mit den Hurern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Das meine ich gar nicht von den Hurern in dieser Welt Oder von den Geizigen Oder von den Raubern Oder von den Abgottischen; sonst mufitet ihr die Welt raumen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Nun aber habe ich euch geschrieben, ihr sollet nichts mit ihnen zu schaffen haben; namlich, so jemand ist, der sich lasset einen Bruder nennen, und ist ein Hurer Oder ein Geiziger Oder ein Abgottischer Oder ein Lasterer Oder ein Trunkenbold Oder ein Rauber, mit demselbigen sollet ihr auch nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Denn was gehen mich die draulien an, daß ich sie sollte richten? Richtet ihr nicht, die da drinnen sind?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Gott aber wird, die draulien sind, richten. Tut von euch selbst hinaus, wer da bose ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Wie darf jemand unter euch, so er einen Handel hat mit einem andern, hadern vor den Ungerechten und nicht vor den Heiligen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Wisset ihr nicht, daß die Heiligen die Welt richten werden? So denn nun die Welt soil von euch gerichtet werden, seid ihr denn nicht gut genug, geringere Sachen zu richten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Wisset ihr nicht, daß wir uber die Engel richten werden? wieviel mehr uber die zeitlichen Güter!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Ihr aber, wenn ihr uber zeitlichen Gutern Sachen habt, so nehmet ihr die, so bei der Gemeinde verachtet sind, und setzet sie zu Richtern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Euch zur Schande muli ich das sagen. Ist so gar kein Weiser unter euch Oder doch nicht einer, der da konnte richten zwischen Bruder und Bruder?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Sondern ein Bruder mit dem andern hadert, dazu vor den Unglaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Es ist schon ein Fehl unter euch, daß ihr miteinander rechtet. Warum lasset ihr euch nicht viel lieber unrecht tun? Warum lasset ihr euch nicht viel lieber ubervorteilen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Sondern ihr tut unrecht und ubervorteilet, und solches an den Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Wisset ihr nicht, daß die Ungerechten werden das Reich Gottes nicht ererben? Lasset euch nicht verfuhren: weder die Hurer noch die Abgottischen noch die Ehebrecher noch die Weichlinge noch die Knabenschander');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'noch die Diebe noch die Geizigen noch die Trunkenbolde noch die Lasterer noch die Rauber werden das Reich Gottes ererben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Und solche sind euer etliche gewesen; aber ihr seid abgewaschen, ihr seid geheiliget, ihr seid gerecht worden durch den Namen des Herrn Jesu und durch den Geist unsers Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Ich hab\' es alles Macht; es frommet aber nicht alles. Ich hab\' es alles Macht; es soil mich aber nichts gefangennehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Die Speise dem Bauche und der Bauch der Speise; aber Gott wird diesen und jene hinrichten. Der Leib aber nicht der Hurerei, sondern dem Herrn und der Herr dem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Gott aber hat den Herrn auferwecket und wird uns auch auferwecken durch seine Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Wisset ihr nicht, daß eure Leiber Christi Glieder sind? Sollte ich nun die Glieder Christi nehmen und Hurengliederdaraus machen? Das sei feme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Oder wisset ihr nicht, daß, wer an der Hure hanget, der ist ein Leib mit ihr? Denn sie werden (spricht er) zwei in einem Fleische sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Wer aber dem Herrn anhanget, der ist ein Geist mit ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fliehet die Hurerei! Alle Sünden, die der Mensch tut, sind aufter seinem Leibe; wer aber huret, der sundiget an seinem eigenen Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Oder wisset ihr nicht, daß euer Leib ein Tempel des Heiligen Geistes ist, der in euch ist, welchen ihr habt von Gott, und seid nicht euer selbst?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Denn ihr seid teuer erkauft. Darum so preiset Gott an eurem Leibe und in eurem Geiste, welche sind Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Von dem ihr aber mir geschrieben habt, antworte ich: Es ist dem Menschen gut, daß er kein Weib beruhre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Aber urn der Hurerei willen habe ein jeglicher sein eigen Weib, und eine jegliche habe ihren eigenen Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Der Mann leiste dem Weibe die schuldige Freundschaft, desselbigengleichen das Weib dem Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Das Weib ist ihres Leibes nicht machtig, sondern der Mann. Desselbigengleichen der Mann ist seines Leibes nicht machtig, sondern das Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Entziehe sich nicht eins dem andern, es sei denn aus beider Bewilligung eine Zeitlang, daß ihrzum Fasten und Beten Mufte habet; und kommet wiederum zusammen; auf daß euch der Satan nicht versuche urn eurer Unkeuschheit willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Solches sage ich aber aus Vergunst und nicht aus Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Ich wollte aber lieber, alle Menschen waren, wie ich bin; aber ein jeglicher hat seine eigene Gabe von Gott, einer so, der andere so.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Ich sage zwarden Ledigen und Witwen: Es ist ihnen gut, wenn sie auch bleiben wie ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'So sie aber sich nicht enthalten, so laft sie freien; es ist besser freien, denn Brunst leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Den Ehelichen aber gebiete nicht ich, sondern der Herr, daß das Weib sich nicht scheide von dem Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'So sie sich aber scheidet, daß sie ohne Ehe bleibe Oder sich mit dem Manne versohne, und daß der Mann das Weib nicht von sich lasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Den andern aber sage ich, nicht der Herr: So ein Bruder ein unglaubig Weib hat, und dieselbige laftt es sich gefallen, bei ihm zu wohnen, der scheide sich nicht von ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Und so ein Weib einen unglaubigen Mann hat, und er laftt es sich gefallen, bei ihr zu wohnen, die scheide sich nicht von ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Denn der unglaubige Mann ist geheiliget durch das Weib, und das unglaubige Weib wird geheiliget durch den Mann. Sonst waren eure Kinder unrein; nun aber sind sie heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'So aber der Unglaubige sich scheidet, so laft ihn sich scheiden. Es ist der Bruder Oder die Schwester nicht gefangen in solchen Fallen. Im Frieden aber hat uns Gott berufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Was weiftt du aber, du Weib, ob du den Mann werdest selig machen? Oder du Mann was weiftt du, ob du das Weib werdest selig machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Doch wie einem jeglichen Gott hat ausgeteilet. Ein jeglicher, wie ihn der Herr berufen hat, also wandele er. Und also schaffe ich\'s in alien Gemeinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Istjemand beschnitten berufen, derzeuge keine Vorhaut. Istjemand berufen in der Vorhaut, der lasse sich nicht beschneiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Die Beschneidung ist nichts, und die Vorhaut ist nichts, sondern Gottes Gebote halten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ein jeglicher bleibe in dem Beruf, darinnen er berufen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Bist du als Knecht berufen, sorge dich nicht; doch kannst du frei werden, so brauche des viel lieber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Denn wer als Knecht berufen ist in dem Herrn, der ist ein Gefreiter des Herrn; desselbigengleichen, wer als Freier berufen ist, der ist ein Knecht Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Ihr seid teuer erkauft; werdet nicht der Menschen Knechte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Ein jeglicher, liebe Bruder, worinnen er berufen ist, darinnen bleibe er bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Von den Jungfrauen aber habe ich kein Gebot des Herrn; ich sage aber meine Meinung, als ich Barmherzigkeit erlanget habe von dem Herrn, treu zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'So meine ich nun, solches sei gut um der gegenwartigen Not willen, daß es dem Menschen gut sei, also zu sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Bist du an ein Weib gebunden, so suche nicht los zu werden; bist du aber los vom Weibe, so suche kein Weib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'So du aber freiest, sündigest du nicht; und so eine Jungfrau freiet, sundiget sie nicht; doch werden solche leibliche Trubsal haben. Ich verschone aber euergerne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Das sage ich aber, liebe Brüder: Die Zeit ist kurz. Weiter ist das die Meinung: Die da Weiber haben, daß sie seien, als flatten sie keine, und die da weinen, als weineten sie nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'und die sich freuen, als freueten sie sich nicht, und die da kaufen, als besaften sie es nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'und die diese Welt gebrauchen, dafi sie dieselbige nicht miftbrauchen; denn das Wesen dieser Welt vergehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Ich wollte aber, daß ihr ohne Sorge waret. Wer ledig ist, der sorget, was dem Herrn angehoret, wie er dem Herrn gefalle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Wer aber freiet, der sorget, was der Welt angehoret, wie er dem Weibe gefalle. Es ist ein Unterschied zwischen einem Weibe und einer Jungfrau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Welche nicht freiet, die sorget, was dem Herrn angehoret, daß sie heilig sei, beide, am Leibe und auch am Geist; die aber freiet, die sorget, was der Welt angehoret, wie sie dem Manne gefalle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Solches aber sage ich zu eurem Nutz; nicht daß ich euch einen Strick an den Hals werfe, sondern dazu, daß es fein ist, und ihr stets und unverhindert dem Herrn dienen konnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'So aber jemand sich lasset dunken, es wolle sich nicht schicken mit seiner Jungfrau, weil sie eben wohl mannbar ist, und es will nicht anders sein, so tue er, was er will; er sundiget nicht, er lasse sie freien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Wenn einer aber sich fest vornimmt, weil er ungezwungen ist und seinen freien Willen hat, und beschlieftt solches in seinem Herzen, seine Jungfrau also bleiben zu lassen, der tut wohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Endlich, welcher verheiratet, der tut wohl; welcher aber nicht verheiratet, der tut besser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Ein Weib ist gebunden an das Gesetz, solange ihr Mann lebet; so aber ihr Mann entschlaft, ist sie frei, sich zu verheiraten, welchem sie will; allein, daß es in dem Herrn geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Seliger ist sie aber, wo sie also bleibet, nach meiner Meinung. Ich halte aber, ich habe auch den Geist Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Von dem Gotzenopfer aber wissen wir; denn wir haben alle das Wissen. Das Wissen blaset auf; aber die Liebe bessert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'So aber sich jemand dunken lasset, er wisse etwas, der weift noch nichts, wie er wissen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'So aber jemand Gott liebet, derselbige ist von ihm erkannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'So wissen wir nun von der Speise des Gdtzenopfers, daß ein Gotze nichts in der Welt sei, und daß kein anderer Gott sei ohne der einige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Und wiewohl es sind, die Gotter genannt werden, es sei, im Himmel Oder auf Erden, sintemal es sind viel Gotter und viel Herren:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'so haben wir doch nur einen Gott, den Vater, von welchem alle Dinge sind und wir in ihm, und einen Herrn, Jesum Christum, durch welchen alle Dinge sind und wir durch ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Es hat aber nicht jedermann das Wissen. Denn etliche machen sich noch ein Gewissen fiber dem Gdtzen und essen es fur Gotzenopfer; damit wird ihr Gewissen, weil es so schwach ist, beflecket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Aber die Speise fordert uns nicht vor Gott. Essen wir, so werden wir darum nicht besser sein; essen wir nicht, so werden wir darum nichts weniger sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Sehet aber zu, daß diese eure Freiheit nicht gerate zu einem Anstoft der Schwachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Denn so dich, der du die Erkenntnis hast, jemand sahe zu Tische sitzen im Gotzenhause, wird nicht sein Gewissen dieweil er schwach ist, verursacht, das Gotzenopfer zu essen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Und wird also fiber deiner Erkenntnis der schwache Bruder umkommen, um welches willen doch Christus gestorben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Wenn ihr aber also sundiget an den Brüdem und schlaget ihr schwaches Gewissen, so sundiget ihr an Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Darum, so die Speise meinen Bruder argert, wollte ich nimmermehr Fleisch essen, auf daß ich meinen Bruder nicht argerte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Bin ich nicht ein Apostel? Bin ich nicht frei? Habe ich nicht unsern Herrn Jesum Christum gesehen? Seid nicht ihr mein Werk in dem Herrn?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Bin ich andern nicht ein Apostel, so bin ich doch euer Apostel; denn das Siegel meines Apostelamts seid ihr in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Wenn man mich fragt, so antworte ich also:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Haben wir nicht Macht zu essen und zu trinken?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Haben wir nicht auch Macht, eine Schwester zum Weibe mit umherzuführen wie die andern Apostel und des Herrn Bruder und Kephas?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Oder haben allein ich und Barnaba nicht Macht, solches zu tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Welcher ziehtjemals in den Krieg auf seinen eigenen Sold? Welcher pflanzet einen Weinberg und isset nicht von seiner Frucht, Oder welcher weidet eine Herde und isset nicht von der Milch der Herde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Rede ich aber solches auf Menschenweise? Sagt nicht solches das Gesetz auch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Denn im Gesetz Mose\'s stehet geschrieben: Du sollst dem Ochsen nicht das Maul verbinden, der da drischet. Sorget Gott fur die Ochsen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Odersagter\'s nicht allerdinge um unsertwillen? Denn es istja um unsertwillen geschrieben. Denn der da pfluget, soli auf Hoffnung pflugen, und der da drischt, soil auf Hoffnung dreschen, daß er seiner Hoffnung teilhaftig werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'So wir euch das Geistliche saen, ist\'s ein groß Ding, ob wir euer Leibliches ernten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'So aber andere dieser Macht an euch teilhaftig sind, warum nicht viel mehr wir? Aber wir haben solche Macht nicht gebraucht, sondern wir vertragen allerlei, daß wir nicht dem Evangelium Christi ein Hindernis machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Wisset ihr nicht, daß, die da opfern essen vom Opfer, und die des Altars pflegen, genießen des Altars?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Also hat auch der Herr befohlen daß, die das Evangelium verkundigen; sollen sich vom Evangelium nahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Ich aber habe der keines gebraucht. Ich schreibe auch nicht darum davon, daß es mit mir also sollte gehalten werden. Es ware mir lieber, ich sturbe, denn daß mirjemand meinen Ruhm sollte zunichte machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Denn daß ich das Evangelium predige, darf ich mich nicht ruhmen; denn ich muß es tun. Und wehe mir, wenn ich das Evangelium nicht predigte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Tue ich\'s gerne, so wird mirgelohnet; tue ich\'s aber ungerne, so ist mir das Amt doch befohlen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Was ist denn nun mein Lohn? Namlich daß ich predige das Evangelium Christi und tue dasselbige frei, umsonst, auf daß ich nicht meiner Freiheit mißbrauche am Evangelium.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Denn wiewohl ich frei bin von jedermann, hab 1 ich mich doch selbst jedermann zum Knechte gemacht, auf daß ich ihrer viel gewinne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Den Juden bin ich worden als ein Jude, auf daß ich die Juden gewinne. Denen, die unter dem Gesetz sind, bin ich worden als unter dem Gesetz, auf daß ich, die, so unter dem Gesetz sind, gewinne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Denen, die ohne Gesetz sind, bin ich als ohne Gesetz worden (so ich doch nicht ohne Gesetz bin vor Gott, sondern bin in dem Gesetz Christi), auf daß ich die, so ohne Gesetz sind, gewinne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Den Schwachen bin ich worden als ein Schwacher, auf daß ich die Schwachen gewinne. Ich bin jedermann allerlei worden, auf daß ich allenthalben ja etliche selig mache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Solches aber tue ich um des Evangeliums wülen, auf daß ich sein teilhaftig werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Wisset ihr nicht, daß die, so in den Schranken laufen, die laufen alle, aber einer erlanget das Kleinod? Laufet nun also, daß ihr es ergreifet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Ein jeglicher aber, der da kampfet, enthalt sich alles Dinges: jene also, daß sie eine vergangliche Krone empfangen, wir aber eine unvergangliche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ich laufe aber also, nicht als aufs Ungewisse; ich fechte also, nicht als, der in die Luft streichet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'sondern ich betaube meinen Leib und zahme ihn, daß ich nicht den andern predige und selbst verwerflich werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ich will euch aber, liebe Brüder, nicht verhalten, daß unsere Vater sind alle unter der Wolke gewesen und sind alle durchs Meer gegangen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'und sind alle unter Mose getauft mit der Wolke und mit dem Meer;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'und haben alle einerlei geistliche Speise gegessen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'und haben alle einerlei geistlichen Trank getrunken; sie tranken aber von dem geistlichen Fels, der mitfolgte, welcher war Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Aber an ihrer vielen hatte Gott kein Wohlgefallen; denn sie sind niedergeschlagen in der Wuste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Das ist aber uns zum Vorbilde geschehen, daß wir uns nicht gelusten lassen des Bosen, gleichwie jene gelüstet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Werdet auch nicht Abgottische, gleichwie jener etliche wurden, als geschrieben stehet: Das Volk setzte sich nieder, zu essen und zu trinken, und stund auf, zu spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Auch lasset uns nicht Hurerei treiben, wie etliche unter jenen Hurerei trieben, und fielen auf einen Tag dreiundzwanzigtausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Lasset uns aber auch Christum nicht versuchen, wie etliche von jenen ihn versuchten und wurden von, den Schlangen umgebracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Murretauch nicht, gleichwie jener etliche murreten und wurden umgebracht durch den Verderber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Solches alles widerfuhr ihnen zum Vorbilde; es ist aber geschrieben uns zur Warnung, auf welche das Ende der Welt kommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Darum wer, sich lasset dunken, er stehe, mag wohl zusehen, daß er nicht falle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Es hat euch noch keine denn menschliche Versuchung betreten; aber Gott ist getreu, der euch nicht lasset versuchen uber euer Vermogen, sondern machet, daß die Versuchung so ein Ende gewinne, daß ihds konnet ertragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Darum, meine Liebsten; fliehet von dem Gotzendienst!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Als mit den Klugen rede ich; richtet ihr, was ich sage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Dergesegnete Kelch, welchen wir segnen, ist der nicht die Gemeinschaft des Blutes Christi? Das Brot, das wir brechen, ist das nicht die Gemeinschaft des Leibes Christi?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Denn ein Brot ist\'s; so sind wirviele ein Leib, dieweil wir alle eines Brotes teilhaftig sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Sehet an den Israel nach dem Fleisch. Welche die Opfer essen, sind die nicht in der Gemeinschaft des Altars?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Was soli ich denn nun sagen? Soil ich sagen, daß der Gotze etwas sei, Oder daß das Gotzenopfer etwas sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Aber ich sage, daß die Heiden, was sie opfern, das opfern sie den Teufeln und nicht Gott. Nun will ich nicht, daß ihr in der Teufel Gemeinschaft sein sollet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ihr konnt nicht zugleich trinken des Herrn Kelch und der Teufel Kelch; ihr konnt nicht zugleich teilhaftig sein des Tisches des Herrn und des Tisches der Teufel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Oder wollen wir dem Herrn trotzen? Sind wir starker denn er?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Ich habe es zwar alles Macht; aber es frommet nicht alles. Ich habe es alles Macht; aber es bessert nicht alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Niemand suche was sein ist, sondern ein jeglicher, was des andern ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Alles was feil ist auf dem Fleischmarkt, das esset und forschet nichts, auf daß ihr des Gewissens verschonet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Denn die Erde ist des Herrn, und was darinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'So aber jemand von den Unglaubigen euch ladet, und ihr wollt hingehen, so esset alles, was euch vorgetragen wird, und forschet nichts, auf dafi ihr des Gewissens verschonet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Wo aber jemand wurde zu euch sagen: Das ist Gotzenopfer, so esset nicht, urn deswilien, der es anzeigte, auf daß ihr des Gewissens verschonet. Die Erde ist des Herrn, und was darinnen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Ich sage aber vom Gewissen nicht dein selbst, sondern des andern. Denn warum sollte ich meine Freiheit lassen urteilen von eines andern Gewissen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Denn so ich\'s mit Danksagung genielie, was sollte ich denn verlastert werden uber dem, dafur ich danke?,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ihr esset nun Oder trinket, Oder was ihr tut, so tut es alles zu Gottes Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Seid nicht argerlich wederden Juden noch den Griechen noch der Gemeinde Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'gleichwie ich auch jedermann in allerlei mich gefallig mache und suche nicht, was mir, sondern was vielen frommet, daß sie selig werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Seid meine Nachfolger, gleichwie ich Christi!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Ich lobe euch, liebe Bruder, daß ihr an mich gedenket in alien Stricken und haltet die Weise, gleichwie ich euch gegeben habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Ich lasse euch aber wissen, daß Christus ist eines jeglichen Mannes Haupt, der Mann aber ist des Weibes Haupt; Gott aber ist Christi Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Ein jeglicher Mann, der da betet Oder weissaget und hat etwas auf dem Haupt, der schandet sein Haupt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Ein Weib aber, das da betet Oder weissaget mit unbedecktem Haupt, die schandet ihr Haupt; denn es ist ebensoviel, als ware sie beschoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Will sie sich nicht bedecken, so schneide man ihr auch das Haar ab. Nun es aber libel stehet, daß ein Weib verschnitten Haar habe Oder beschoren sei, so lasset sie das Haupt bedecken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Der Mann aber soil das Haupt nicht bedecken, sintemal er ist Gottes Bild und Ehre; das Weib aber ist des Mannes Ehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Denn der Mann ist nicht vom Weibe, sondern das Weib ist vom Manne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Und der Mann ist nicht geschaffen urn des Weibes willen; sondern das Weib urn des Mannes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Darum soil das Weib eine Macht auf dem Haupt haben urn der Engel willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Doch ist weder der Mann ohne das Weib, noch das Weib ohne den Mann in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Denn wie das Weib von dem Manne, also kommt auch der Mann durch das Weib, aber alles kommt von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Richtet bei euch selbst, ob es wohl stehet, daß ein Weib unbedeckt vor Gott bete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Oder lehret euch auch nicht die Natur, daß einem Manne eine Unehre ist, so er lange Haare zeuget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'und dem Weibe eine Ehre, so sie lange Haare zeuget? Das Haar ist ihr zur Decke gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Ist aber jemand unter euch, der Lust zu zanken hat, der wisse, daß wir solche Weise nicht haben, die Gemeinden Gottes auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Ich muli aber dies befehlen: Ich kann\'s nicht loben, daß ihr nicht auf bessere Weise, sondern auf argere Weise zusammenkommet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Zum ersten, wenn ihrzusammen kommt in der Gemeinde, hore ich, es seien Spaltungen unter euch; und zum Teil glaube ich\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Denn es müssen Rotten unter euch sein, auf daß die, so rechtschaffen sind, offenbar unter euch werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Wenn ihr nun zusammenkommet, so halt man da nicht des Herrn Abendmahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Denn so man das Abendmahl halten soil, nimmt ein jeglicher sein eigenes vorhin, und einer ist hungrig, der andere ist trunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Habt ihr aber nicht Hauser, da ihr essen und trinken moget? Oder verachtet ihr die Gemeinde Gottes und beschamet die, so da nichts haben? Was soil ich euch sagen? Soil ich euch loben? Hierinnen lobe ich euch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Ich habe von dem Herrn empfangen, das ich euch gegeben habe. Denn der Herr Jesus in der Nacht, da er verraten ward, nahm er das Brot,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'dankete und brach\'s und sprach: Nehmet, esset; das ist mein Leib der fur euch gebrochen wird. Solches tut zu meinem Gedachtnis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Desselbigengleichen auch den Kelch nach dem Abendmahl und sprach: Dieser Kelch ist das neue Testament in meinem Blut. Solches tut, so oft ihr\'s trinket, zu meinem Gedachtnis!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Denn so oft ihr von diesem Brot esset und von diesem Kelch trinket, sollt ihr des Herrn Tod verkundigen, bis da(3> er kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Welcher nun unwurdig von diesem Brot isset Oder von dem Kelch des Herrn trinket, der ist schuldig an dem Leib und Blut des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Der Mensch prufe aber sich selbst und also esse er von diesem Brot und trinke von diesem Kelch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Denn welcher unwurdig isset und trinket, der isset und trinket ihm selber das Gericht damit, da(J er nicht unterscheidet den Leib des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Darum sind auch so viel Schwache und Kranke unter euch, und ein gut Teil schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Denn so wir uns selber richteten, so würden wir nicht gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Wenn wir aber gerichtet werden, sowerden wir von dem Herrn gezuchtiget, auf dati wir nicht samt der Welt verdammet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Darum, meine lieben Bruder, wenn ihr zusammenkommet, zu essen, so harre einer des andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Hungert aber jemand, der esse daheim, auf daß ihr nicht zum Gerichte zusammenkommet. Das andere will ich ordnen, wenn ich komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Von den geistlichen Gaben aber will ich euch, liebe Bruder, nicht verhalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Ihr wisset, dafi ihr Heiden seid gewesen und hingegangen zu den stummen Gotzen, wie ihr gefuhrt wurdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Darum tue ich euch kund, daß niemand Jesum verfluchet, der durch den Geist Gottes redet; und niemand kann Jesum einen Herrn heüien ohne durch den Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Es sind mancherlei Gaben, aber es ist ein Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Und es sind mancherlei Amter, aber es ist ein Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Und es sind mancherlei Krafte, aber es ist ein Gott, der da wirket alles in alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'In einem jeglichen erzeigen sich die Gaben des Geistes zum gemeinen Nutzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Einem wird gegeben durch den Geist, zu reden von der Weisheit; dem andern wird gegeben, zu reden von der Erkenntnis nach demselbigen Geist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'einem andern der Glaube in demselbigen Geist; einem andern die Gabe, gesund zu machen, in demselbigen Geist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'einem andern, Wunderzu tun; einem andern Weissagung; einem andern, Geisterzu unterscheiden; einem andern mancherlei Sprachen; einem andern, die Sprachen auszulegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Dies aber alles wirket derselbige einige Geist und teilet einem jeglichen seines zu, nachdem er will.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Denn gleichwie ein Leib ist und hat doch viel Glieder, alle Glieder aber eines Leibes, wiewohl ihrer viel sind, sind sie doch ein Leib: also auch Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Denn wir sind durch einen Geist alle zu einem Leibe getauft, wir seien Juden Oder Griechen, Knechte Oder Freie, und sind alle zu einem Geist getranket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Denn auch der Leib ist nicht ein Glied, sondern viele.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'So aber der Fuß sprache: Ich bin keine Hand, darum bin ich des Leibes Glied nicht, sollte er urn deswillen nicht des Leibes Glied sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Und so das Ohr sprache: Ich bin kein Auge, darum bin ich nicht des Leibes Glied, sollte es urn deswillen nicht des Leibes Glied sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Wenn der ganze Leib Auge ware, wo bliebe das Gehor? So er ganz Gehor ware, wo bliebe der Geruch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Nun aber hat Gott die Glieder gesetzt, ein jegliches sonderlich am Leibe, wie er gewollt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'So aber alle Glieder ein Glied waren, wo bliebe der Leib?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Nun aber sind der Glieder viele, aber der Leib ist einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Es kann das Auge nicht sagen zu der Hand: Ich bedarf dein nicht; Oder wiederum das Haupt zu den Fufien: Ich bedarf euer nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'sondern vielmehr, die Glieder des Leibes, die uns dünken, die schwachsten zu sein, sind die notigsten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'und die uns dünken, die unehrlichsten sein, denselbigen legen wir am meisten Ehre an, und die uns Libel anstehen, die schmücket man am meisten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Denn die uns wohl anstehen, die bedurfen\'s nicht. Aber Gott hat den Leib also vermenget und dem durftigen Glied am meisten Ehre gegeben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'auf daß nicht eine Spaltung im Leibe sei, sondern die Glieder fureinander gleich sorgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Und so ein Glied leidet, so leiden alle Glieder mit; und so ein Glied wird herrlich gehalten, so freuen sich alle Glieder, mit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Ihr seid aber der Leib Christi und Glieder, ein jeglicher nach seinem Teil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Und Gott hat gesetzt in der Gemeinde aufs erste die Apostel, aufs andere die Propheten, aufs dritte die Lehrer, danach die Wundertater, danach die Gaben, gesund zu machen, Heifer, Regierer, mancherlei Sprachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Sind sie alle Apostel? Sind sie alle Propheten? Sind sie alle Lehrer? Sind sie alle Wundertater?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Haben sie alle Gaben gesund zu machen? Reden sie alle mit mancherlei Sprachen? Konnen sie alle auslegen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Strebet aber nach den besten Gaben! Und ich will euch noch einen kostlichern Weg zeigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Wenn ich mit Menschen- und mit Engelzungen redete und hatte der Liebe nicht, so ware ich ein tonend Erz Oder eine klingende Schelle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Und wenn ich weissagen konnte und wulite alle Geheimnisse und alle Erkenntnis und hatte alien Glauben, also dafi ich Berge versetzte, und hatte der Liebe nicht, so ware ich nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Und wenn ich alle meine Habe den Armen gabe und lielie meinen Leib brennen und hatte der Liebe nicht, so ware mir\'s nichts nütze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Die Liebe ist langmütig und freundlich; die Liebe eifert nicht; die Liebe treibt nicht Mutwillen; sie blahet sich nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'sie stellet sich nicht ungebardig; sie suchet nicht das Ihre; sie lasset sich nicht erbittern; sie trachtet nicht nach Schaden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'sie freuet sich nicht der Ungerechtigkeit; sie freuet sich aber der Wahrheit;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'sie vertraget alles, sie glaubet alles, sie hoffet alles, sie duldet alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Die Liebe horet nimmer auf, so doch die Weissagungen aufhoren werden, und die Sprachen aufhoren werden, und die Erkenntnis aufhoren wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Denn unser Wissen ist Stuckwerk, und unser Weissagen ist Stuckwerk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Wenn aber kommen wird das Vollkommene, so wird das Stuckwerk aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Da ich ein Kind war, da redete ich wie ein Kind und war klug wie ein Kind und hatte kindische Anschlage; da ich aber ein Mann ward, tat ich ab, was kindisch war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Wir sehen jetzt durch einen Spiegel in einem dunklen Wort, dann aber von Angesicht zu Angesichte. Jetzt erkenne ich\'s stuckweise; dann aber werde ich erkennen, gieichwie ich erkannt bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nun aber bleibt Glaube, Hoffnung, Liebe, diese drei; aber die Liebe ist die großte unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Strebet nach der Liebe! Fleißiget euch der geistlichen Gaben, am meisten aber, daß ihr weissagen moget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Denn der mit der Zunge redet, der redet nicht den Menschen, sondern Gott. Denn ihm horet niemand zu; im Geist aber redet er die Geheimnisse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Wer aber weissaget, der redet den Menschen zur Besserung und zur Ermahnung und zur T rostung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Wer mit Zungen redet, der bessert sich selbst; wer aber weissaget, der bessert die Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Ich wollte, daß ihr alle mit Zungen reden konntet, aber viel mehr, daü ihr weissagetet. Denn der da weissaget, ist großer, denn der mit Zungen redet, es sei denn, daß er es auch auslege, daß die Gemeinde davon gebessert werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Nun aber, liebe Bruder, wenn ich zu euch kame und redete mit Zungen, was ware ich euch nütze, so ich nicht mit euch redete entweder durch Offenbarung Oder durch Erkenntnis Oder durch Weissagung Oder durch Lehre?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Halt sich\'s doch auch also in den Dingen, die da lauten und doch nicht leben, es sei eine Pfeife Oder eine Harfe; wenn sie nicht unterschiedliche Stimmen von sich geben, wie kann man wissen, was gepfiffen Oder geharfet ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Und so die Posaune einen undeutlichen Ton gibt, wer will sich zum Streit rusten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Also auch ihr, wenn ihr mit Zungen redet, so ihr nicht eine deutliche Rede gebet, wie kann man wissen, was geredet ist? Denn ihr werdet in den Wind reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Zwar es ist mancherlei Art der Stimmen in der Welt, und derselbigen ist doch keine undeutlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'So ich nun nicht weiß der Stimme Deutung, werde ich undeutsch sein dem, der da redet, und der da redet, wird mir undeutsch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Also auch ihr, sintemal ihr euch fleißigetder geistlichen Gaben, trachtet danach, daß ihr die Gemeinde bessert, auf daß ihr alles reichlich habet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Darum, welcher mit Zungen redet, der bete also, daß er\'s auch auslege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'So ich aber mit Zungen bete, so betet mein Geist; aber mein Sinn bringet niemand Frucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Wie soil es aber denn sein? Namlich also: Ich will beten mit dem Geist und will beten auch im Sinn; ich will Psalmen singen im Geist und will auch Psalmen singen mit dem Sinn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Wenn du aber segnest im Geist, wie soil der, so anstatt des Laien stehet, Amen sagen auf deine Danksagung, sintemal er nicht weiß, was du sagest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Du danksagest wohl fein; aber der andere wird nicht davon gebessert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Ich danke meinem Gott, daß ich mehr mit Zungen rede denn ihr alle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Aber ich will in der Gemeinde lieber funf Worte reden mit meinem Sinn, auf daß ich auch andere unterweise, denn sonst zehntausend Worte mit Zungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Liebe Bruder, werdet nicht Kinder an dem Verstandnis, sondern an der Bosheit seid Kinder; an dem Verstandnis aber seid voilkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Im Gesetz stehet geschrieben: Ich will mit andern Zungen und mit andern Lippen reden zu diesem Volk, und sie werden mich auch also nicht horen, spricht der Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Darum so sind die Zungen zum Zeichen, nicht den Glaubigen, sondern den Unglaubigen; die Weissagung aber nicht den Unglaubigen, sondern den Glaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Wenn nun die ganze Gemeinde zusammenkame an einem Ort und redeten alle mit Zungen, es kamen aber hinein Laien Oder Unglaubige, würden sie nicht sagen, ihrwaret unsinnig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'So sie aber alle weissageten und kame dann ein Unglaubiger Oder Laie hinein, der würde von denselbigen alien gestraft und von alien gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Und also würde das Verborgene seines Herzens offenbar, und er würde also fallen auf sein Angesicht, Gott anbeten und bekennen, daß Gott wahrhaftig in euch sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Wie ist ihm denn nun, Hebe Bruder? Wenn ihr zusammenkommt, so hat ein jeglicher Psalmen, er hat eine Lehre, er hat Zungen, er hat Offenbarung, er hat Auslegung. Lasset es alles geschehen zur Besserung!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'So jemand mit der Zunge redet Oder zween Oder aufs meiste\' drei, eins urns andere; so lege es einer aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ist er aber nicht ein Ausleger, so schweige er unter der Gemeinde, rede aber sich selber, und Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Die Weissager aber lasset reden, zween Oder drei, und die andern lasset richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'So aber eine Offenbarung geschieht einem andern, der da sitzet, so schweige der erste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Ihr konnet wohl alle weissagen, einer nach dem andern, auf daß sie alle lernen und alle ermahnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Und die Geister der Propheten sind den Propheten untertan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Denn Gott ist, nicht ein Gott der Unordnung, sondern des Friedens wie in alien Gemeinden der Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Eure Weiber lasset schweigen unter der Gemeinde; denn es soli ihnen nicht zugelassen werden, dafi sie reden, sondern untertan sein, wie auch das Gesetz sagt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Wollen sie aber etwas lernen, so lasset sie daheim ihre Manner fragen. Es stehet den Weibern ubel an, unter der Gemeinde reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Oder ist das Wort Gottes von euch auskommen, Oder ist\'s allein zu euch kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'So sich jemand lasset dünken, er sei ein Prophet Oder geistlich, der erkenne, was ich euch schreibe; denn es sind des Herrn Gebote.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Ist aber jemand unwissend, der sei, unwissend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Darum, liebe Bruder, fleilüget euch des Weissagens und wehret nicht, mit Zungen zu reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Lasset alles ehrlich und ordentlich zugehen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Ich erinnere euch, aber, liebe Bruder, des Evangeliums, das ich euch verkundiget habe, welches ihr auch angenommen habt, in welchem ihr auch stehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'durch welches ihr auch selig werdet, welcher Gestalt ich es euch verkundiget habe, so ihr\'s behalten habt, es ware, denn, dad ihr\'s umsonst geglaubet hattet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Denn ich habe euch zuvorderst gegeben, welches ich auch empfangen habe, dad Christus gestorben sei fur unsere Sünden nach der Schrift,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'und dad er begraben sei, und dad er auferstanden sei am dritten Tage nach der Schrift,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'und dad er gesehen worden ist von Kephas, danach von den Zwolfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Danach ist er gesehen worden von mehr denn funfhundert Brudern auf einmal, deren noch viel leben, etliche aber sind entschlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Danach ist er gesehen worden von Jakobus, danach von alien Aposteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Am letzten nach alien ist er auch von mir, als einer unzeitigen Geburt, gesehen worden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'denn ich bin der geringste unter den Aposteln, als der ich nicht wert bin, dad ich ein Apostei heide, darum dad ich die Gemeinde Gottes verfolget habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Aber von Gottes Gnaden bin ich, das ich bin, und seine Gnade an mir ist nicht vergeblich gewesen, sondern ich habe viel mehr gearbeitet denn sie alle, nicht aber ich, sondern Gottes Gnade, die mit mir ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Es sei nun ich oderjene, also predigen wir, und also habt ihr geglaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'So aber Christus gepredigetwird, dad er sei von den Toten auferstanden, wie sagen denn etliche unter euch, die Auferstehung der Toten sei nichts?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Ist aber die Auferstehung der Toten nichts, so ist auch Christus nicht auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Ist aber Christus nicht auferstanden, so ist unsere Predigt vergeblich, so ist auch euer Glaube vergeblich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Wirwurden aber auch erfunden falsche Zeugen Gottes, dad wir wider Gott gezeuget hatten, er hatte Christum auferwecket, den er nicht auferwecket hatte, sintemal die Toten nicht auferstehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Denn so die Toten nicht auferstehen, so ist Christus auch nicht auferstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Ist Christus aber nicht auferstanden, so ist euer Glaube eitel, so seid ihr noch in euren Sünden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'so sind auch die, so in Christo entschlafen sind, verloren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Hoffen wir allein in diesem Leben auf Christum, so sind wir die elendesten unter alien Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Nun aber ist Christus auferstanden von den Toten und der Erstling worden unter denen, die da schlafen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'sintemal durch einen Menschen der Tod und durch einen Menschen die Auferstehung der Toten kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Denn gleichwie sie in Adam alle sterben, also werden sie in Christo alle lebendig gemacht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ein jeglicher aber in seiner Ordnung. Der Erstling Christus, danach die Christo angehoren, wenn er kommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Danach das Ende, wenn erdas Reich Gott und dem Vater überantworten wird, wenn er aufheben wird alle Herrschaft und alle Obrigkeit und Gewalt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Er muli aber herrschen, bis daß er alle seine Feinde unter seine Fulie lege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Der letzte Feind, der aufgehoben wird, ist der Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Denn er hat ihm alles unter seine Fulie getan. Wenn er aber sagt; daß es alles untertan sei, ist\'s offenbar, daß ausgenommen ist, der ihm alles untertan hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Wenn aber alles ihm untertan sein wird, alsdann wird auch der Sohn selbst untertan sein dem, der ihm alles untertan hat, auf dafi Gott sei alles in alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Was machen sonst, die sich taufen lassen uber den Toten, so allerdinge die Toten nicht auferstehen? Was lassen sie sich taufen uber den Toten?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Und was stehen wir alle Stunde in der Gefahr?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Bei unserm Ruhm den ich habe in Christo Jesu, unserm Herrn, ich sterbe taglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Hab 1 ich menschlicher Meinung zu Ephesus mit den wilden Tieren gefochten, was hilft\'s mir, so die Toten nicht auferstehen? Lasset uns essen und trinken; denn morgen sind wir tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Lasset euch nicht verfuhren! Bose Geschwatze verderben gute Sitten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Werdet doch einmal recht nuchtern und sundiget nicht; denn etliche wissen nichts von Gott, das sage ich euch zur Schande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mochte aber jemand, sagen: Wie werden die Toten auferstehen; und mit welcherlei Leibe werden sie kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Du Narr, was du saest, wird nicht lebendig, es sterbe denn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Und was du saest, ist ja nicht der Leib, der werden soli, sondern ein bloßes Korn, namlich Weizen Oder der andern eines.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Gott aber gibt ihm einen Leib, wie er will, und einem jeglichen von den Samen seinen eigenen Leib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nicht ist alles Fleisch einerlei Fleisch, sondern ein ander Fleisch ist der Menschen, ein anderes des Viehes, ein anderes der Fische, ein anderes der Vogel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Und es sind himmlische Korper und irdische Korper. Aber eine andere Herrlichkeit haben die himmlischen und eine andere die irdischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Eine andere Klarheit hat die Sonne, eine andere Klarheit hat der Mond, eine andere Klarheit haben die Sterne; denn ein Stern ubertrifft den andern an Klarheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Also auch die Auferstehung der Toten. Es wird gesaet verweslich und wird auferstehen unverweslich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Es wird gesaet in Unehre und wird auferstehen in Herrlichkeit. Es wird gesaet in Schwachheit und wird auferstehen in Kraft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Es wird gesaet ein natürlicher Leib, und wird auferstehen ein geistlicher Leib. Hat man einen natürlichen Leib, so hat man auch einen geistlichen Leib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'wie es geschrieben stehet: Der erste Mensch, Adam, ist gemacht ins natürliche Leben und der letzte Adam ins geistliche Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Aber der geistliche Leib ist nicht erste, sondern der natürliche, danach der geistliche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Der erste Mensch ist von der Erde und irdisch; der andere Mensch ist der Herr vom Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Welcherlei der irdische ist, solcherlei sind auch die irdischen; und welcherlei der himmlische ist, solcherlei sind auch die himmlischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Und wie wir getragen haben das Bild des irdischen, also werden wir auch tragen das Bild des himmlischen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Davon sage ich aber, liebe Bruder, daß Fleisch und Blut nicht konnen das Reich Gottes ererben; auch wird das Verwesliche nicht erben das Unverwesliche,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Siehe, ich sage euch ein Geheimnis: Wir werden nicht alle entschlafen wir werden aber alle verwandelt werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'und dasselbige plotzlich, in einem Augenblick, zu der Zeit der letzten Posaune. Denn es wird die Posaune schallen und die Toten werden auferstehen unverweslich, und wir werden verwandelt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Denn dies Verwesliche muß anziehen das Unverwesliche, und dies Sterbliche muß anziehen die Unsterblichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Wenn aber dies Verwesliche wird anziehen das Unverwesliche, und dies Sterbliche wird anziehen die Unsterblichkeit, dann wird erfullet werden das Wort, das geschrieben stehet:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Der Tod ist verschlungen in den Sieg. Tod, wo ist dein Stachel? Holle, wo ist dein Sieg?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Aber der Stachel des Todes ist die Sünde; die Kraft aber der Sünde ist das Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Gott aber sei Dank, der uns den Sieg gegeben hat durch unsern Herrn Jesum Christum!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Darum, meine lieben Bruder, seid fest, unbeweglich und nehmet immer zu in dem Werk des Herrn, sintemal ihr wisset, daß eure Arbeit nicht vergeblich ist in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Von der Steuer aber, die den Heiligen geschieht, wie ich den Gemeinden in Galatien geordnet habe, also tut auch ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Auf je der Sabbate einen lege bei sich selbst ein jeglicher unter euch und sammle, was ihn gut dunkt, auf daß nicht, wenn ich komme, dann allererst die Steuer zu sammeln sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Wenn ich aber darkommen bin, welche ihr durch Briefe dafür ansehet, die will ich senden, daß sie hinbringen eure Wohltat gen Jerusalem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'So es aber wert ist, daß ich auch hinreise, sollen sie mit mir reisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Ich will aber zu euch kommen, wenn ich durch Mazedonien ziehe; denn durch Mazedonien werde ich ziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Bei euch aber werde ich vielleicht bleiben Oder auch wintern, auf daß ihr mich geleitet, wo ich hinziehen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Ich will euch jetzt nicht sehen im Voruberziehen; denn ich hoffe, ich wolle etliche Zeit bei euch bleiben, so es der Herr zulaßt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Ich werde aberzu Ephesus bleiben bis Pfingsten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Denn mir ist eine große Tur aufgetan, die viele Frucht wirket, und sind viel Widerwartige da.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'So Timotheus kommt, so sehet zu, daß erohne Furcht bei euch sei; denn er treibet auch das Werk des Herm wie ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Daß ihn nun nichtjemand verachte! Geleitet ihn aber im Frieden, daß er zu mir komme; denn ich warte sein mit den Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Von Apollos, dem Bruder, aberwisset, da(S ich ihn sehrviel ermahnet habe, daß erzu euch kame mit den Brudern, und eswarallerdinge sein Wille nicht, daß er jetzt kame; er wird aber kommen, wenn es ihm gelegen sein wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Wachet, stehet im Glauben, seid mannlich und seid stark!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Alle eure Dinge lasset in der Liebe geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Ich ermahne euch aber, liebe Bruder, ihr kennet das Haus Stephanas, daß sie sind die Erstlinge in Achaja und haben sich selbst verordnet zum Dienstden Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'auf daß auch ihr solchen untertan seietund alien, die mitwirken und arbeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Ich freue mich uber die Zukunft Stephanas und Fortunatus und Achaicus; denn wo ich euer Mangel hatte, das haben sie erstattet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Sie haben erquicket meinen und euren Geist. Erkennet, die solche sind!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Esgrußen euch die Gemeinden in Asien. Es grüßen euch sehr in dem Herm Aquila und Priscilla samt der Gemeinde in ihrem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Es grußen euch alle Bruder. Grußet euch untereinander mit dem heiligen Kuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Ich, Paulus, gruße euch mit meiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'So jemand den Herm Jesum Christum nicht liebhat, der sei Anathema, Maharam Motha.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Die Gnade des Herrn Jesu Christi sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Meine Liebe sei mit euch alien in Christo Jesu! Amen. Der zweite Brief des Paulus an die Korinther');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, und Bruder Timotheus: Der Gemeinde Gottes zu Korinth samt alien Heiligen in ganz Achaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Gelobet sei Gott und der Vater unsers Herrn Jesu Christi, der Vater der Barmherzigkeit und Gott alles Trostes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'der uns trostet in aller unserer Trubsal, daß wir auch trosten konnen, die da sind in allerlei Trubsal, mit dem Trost, damit wir getrostet werden von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Denn gleichwie wir des Leidens Christi viel haben, also werden wir auch reichlich getrostet durch Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Wir haben aber Trubsal Oder Trost, so geschieht es euch zugut. Ist\'s Trubsal, so geschieht es euch zu Trost und Heil; welches Heil beweiset sich, so ihr leidet mit Geduld dermaßen, wie wir leiden. Ist\'s Trost, so geschieht es euch auch zu Trost und Heil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Und stehet unsere Hoffnung test fur euch, dieweil wirwissen, daß, wie ihr des Leidens teilhaftig seid, so werdet ihr auch des Trostes teilhaftig sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Denn wir wollen euch nicht verhalten, liebe Bruder, unsere Trubsal, die uns in Asien widerfahren ist da wir uber die Maßen beschweret waren und uber Macht, also daß wir auch am Leben verzagten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'und bei uns beschlossen hatten, wir müßten sterben. Das geschah aber darum, daß wir unser Vertrauen nicht auf uns selbst stelleten, sondern auf Gott, der die Toten auferwecket,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'welcher uns von solchem Tode erloset hat und noch taglich erloset; und hoffen auf ihn, er werde uns auch hinfort erlosen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'durch Hilfe eurer Furbitte fur uns, auf daß uber uns fur die Gabe, die uns gegeben ist, durch viel Personen viel Danks geschehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Denn unser Ruhm ist der, namlich das Zeugnis unsers Gewissens, daß wir in Einfaltigkeit und gottlicher Lauterkeit, nicht in fleischlicher Weisheit, sondern in der Gnade Gottes auf der Welt gewandelt haben, allermeist aber bei euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Denn wirschreiben euch nichts anderes, denn was ihr leset und auch befindet. Ich hoffe aber, ihr werdet uns auch bis ans Ende also befinden, gleichwie ihr uns zum Teil befunden habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Denn wir sind euer Ruhm, gleichwie auch ihr unser Ruhm seid auf des Herrn Jesu Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Und auf solch Vertrauen gedachte ich jenes Mai zu euch zu kommen, auf daß ihr abermal eine Wohltat empfinget,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'und ich durch euch nach Mazedonien reisete und wiederum aus Mazedonien zu euch kame und von euch geleitet wurde nach Judaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Hab\' ich aber eine Leichtfertigkeit gebrauchet, da ich solches gedachte, Oder sind meine Anschlage fleischlich? Nicht also, sondern bei mir ist Ja Ja, und Nein ist Nein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Aber, o ein treuer Gott, dall unser Wort an euch nicht Ja und Nein gewesen ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Denn der Sohn Gottes, Jesus Christus, der unter euch durch uns geprediget ist, durch mich und Silvanus und Timotheus, der war nicht Ja und Nein, sondern es war Ja in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Denn alle Gottesverheiliungen sind Ja in ihm und sind Amen in ihm Gott zu Lobe durch uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Gott ist\'s aber, deruns befestiget samt euch in Christum und uns gesalbet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'und versiegelt und in unsere Herzen das Pfand, den Geist, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Ich rufe aber Gott an zum Zeugen auf meine Seele, daß ich euer verschonet habe in dem, dafi ich nicht wieder gen Korinth kommen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nicht daß wir Herren seien über euren Glauben, sondern wir sind Gehilfen eurer Freude; denn ihr stehet im Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Ich dachte aber solches bei mir, daß ich nicht abermal in Traurigkeit zu euch kame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Denn so ich euch traurig mache, wer ist, der mich frohlich mache, ohne der da von mir betrubet wird?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Und dasselbige habe ich euch geschrieben, daß ich nicht, wenn ich kame, traurig sein mulite, über welche ich mich billig sollte freuen, sintemal ich mich des zu euch alien versehe, dafi meine Freude euer aller Freude sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Denn ich schrieb euch in grolier Trubsal und Angst des Herzens mitviel Tranen, nicht dafi ihr solltet betrubet werden, sondern auf, daß ihr die Liebe erkennetet, welche ich habe sonderlich zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'So aber jemand eine Betrubnis hat angerichtet, der hat nicht mich betrubet, ohne zum Teil, auf daß ich nicht euch alle beschwere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Es ist aber genug, dafi derselbige von vielen also gestraft ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'daß ihr nun hinfort ihm desto mehr vergebet und trostet, auf daß er nicht in allzu große Traurigkeit versinke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Darum ermahne ich euch, daß ihr die Liebe an ihm beweiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Denn darum habe ich euch auch geschrieben, daß ich erkennete, ob ihr rechtschaffen seid, gehorsam zu sein in alien Stricken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Welchem aber ihr etwas vergebet, dem vergebe ich auch. Denn auch ich, so ich etwas vergebe jemandem, das vergebe ich urn euretwillen an Christi Statt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'auf daß wir nicht übervorteilt werden vom Satan; denn uns ist nicht unbewußt, was er im Sinn hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Da ich aber gen Troas kam, zu predigen das Evangelium Christi, und mir eine Tur aufgetan war in dem Herrn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'hatte ich keine Ruhe in meinem Geist, da ich Titus, meinen Bruder, nicht fand, sondern ich machte meinen Abschied mit ihnen und fuhr aus nach Mazedonien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Aber Gott sei gedankt, der uns allezeit Sieg gibt in Christo und offenbaret den Geruch seiner Erkenntnis durch uns an alien Orten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Denn wir sind Gott ein guter Geruch Christi, beide, unter denen, die selig werden, und unter denen, die verloren werden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'diesen ein Geruch des Todes zum Tode, jenen aber ein Geruch des Lebens zum Leben. Und wer ist hiezu tuchtig?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Denn wir sind nicht wie etliche viele, die das Wort Gottes verfalschen, sondern als aus Lauterkeit und als aus Gott, vor Gott reden wir in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Heben wir denn abermal an, uns selbst zu preisen? Oder bedurfen wir, wie etliche, der Lobebriefe an euch Oder Lobebriefe von euch?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Ihr seid unser Brief, in unser Herz geschrieben, der erkannt und gelesen wird von alien Menschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'die ihr offenbar worden seid, daß ihr ein Brief Christi seid, durch unser Predigtamt zubereitet und durch uns geschrieben, nicht mit Tinte, sondern mit dem Geist des lebendigen Gottes, nicht in steinerne Tafeln, sondern in fleischerne Tafeln des Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Ein solch Vertrauen aber haben wir durch Christum zu Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nicht daß wir tuchtig sind von uns selber, etwas zu denken als von uns selber, sondern daß wir tuchtig sind, ist von Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'welcher auch uns tuchtig gemacht hat, das Amt zu führen des Neuen Testaments, nicht des Buchstabens, sondern des Geistes. Denn der Buchstabe totet, aber der Geist macht lebendig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'So aber das Amt, das durch die Buchstaben totet und in die Steine ist gebildet, Klarheit hatte, also daß die Kinder Israel nicht konnten ansehen das Angesicht Mose\'s urn der Klarheit willen seines Angesichtes, die doch aufhoret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'wie sollte nicht viel mehr das Amt, das den Geist gibt, Klarheit haben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Denn so das Amt, das die Verdammnis prediget, Klarheit hat, viel mehr hat das Amt, das die Gerechtigkeit prediget, uberschwengliche Klarheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Denn auch jenes Teil, das verklaret war, ist nicht fur Klarheit zu achten gegen diese uberschwengliche Klarheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Denn so das Klarheit hatte, das da aufhoret, viel mehr wird das Klarheit haben, das da bleibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Dieweil wir nun solche Hoffnung haben, brauchen wir grolie Freudigkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'und tun nicht wie Mose, der die Decke vor sein Angesicht hing, daß die Kinder Israel nicht ansehen konnten das Ende des, der aufhoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Sondern ihre Sinne sind verstockt; denn bis auf den heutigen Tag bleibt dieselbige Decke unaufgedeckt uber dem Alten Testament, wenn sie es lesen, welche in Christo aufhoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Aber bis auf den heutigen Tag, wenn Mose gelesen wird, hangt die Decke vor ihrem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Wenn es aber sich bekehrete zu dem Herm, so wurde die Decke abgetan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Denn der Herr ist der Geist. Wo aber der Geist des Herm ist, da ist Freiheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Nun aber spiegelt sich in uns alien des Herm Klarheit mit aufgedecktem Angesichte; und wir werden verklaret in dasselbige Bild von einer Klarheit zu der andern als vom Geist des Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Darum, dieweil wir ein solch Amt haben, nachdem uns Barmherzigkeit widerfahren ist, so werden wir nicht müde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'sondern meiden auch heimliche Schande und gehen nicht mit Schalkheit urn, falschen auch nicht Gottes Wort, sondern mit Offenbarung der Wahrheit und beweisen unswohl gegen alter Menschen Gewissen vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Ist nun unser Evangelium verdeckt, so ist\'s in denen, die verloren werden, verdeckt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'bei welchen der Gott dieser Welt der Unglaubigen Sinn verblendet hat, dad sie nicht sehen das helle Licht des Evangeliums von der Klarheit Christi, welcher ist das Ebenbild Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Denn wir predigen nicht uns selbst, sondern Jesum Christ, daß er sei der Herr, wir aber eure Knechte urn Jesu willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Denn Gott, der da hied das Licht aus der Finsternis hervorleuchten, der hat einen hellen Schein in unsere Herzen gegeben, dafi (durch uns) entstunde die Erleuchtung von der Erkenntnis der Klarheit Gottes in dem Angesichte Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Wir haben aber solchen Schatz in irdischen Gefaden, auf dad die uberschwengliche Kraft sei Gottes und nicht von uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Wir haben allenthalben Trubsal, aber wir angsten uns nicht; uns ist bange, aber wir verzagen nicht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'wir leiden Verfolgung, aber wir werden nicht verlassen; wir werden unterdruckt, aber wir kommen nicht urn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Und tragen urn allezeit das Sterben des Herrn Jesu an unserm Leibe, auf dad auch das Leben des Herrn Jesu an unserm Leibe offenbarwerde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Denn wir, die wir leben, werden immerdar in den Tod gegeben urn Jesu willen, auf dad auch das Leben Jesu offenbar werde an unserm sterblichen Fleische.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Darum so ist nun der Tod machtig in uns, aber das Leben in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Dieweil wir aber denselbigen Geist des Glaubens haben (nachdem geschrieben stehet: Ich glaube, darum rede ich), so glauben wir auch, darum so reden wir auch');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'und wissen, dad der, so den Herrn Jesum hat auferweckt, wird uns auch auferwecken durch Jesum und wird uns darstellen samt euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Denn es geschiehet alles urn euretwillen, auf dad die uberschwengliche Gnade durch vieler Danksagen Gott reichlich preise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Darum werden wir nicht müde, sondern ob unser auderlicher Mensch verweset, so wird doch der innerliche von Tag zu Tag erneuert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Denn unsere Trubsal, die zeitlich und leicht ist, schaffet eine ewige und uber alle Maden wichtige Herrlichkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'uns, die wir nicht sehen auf das Sichtbare, sondern auf das Unsichtbare. Denn was sichtbar ist, das ist zeitlich; was aber unsichtbar ist, das ist ewig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Wir wissen aber, so unser irdisch Haus dieser Hütte zerbrochen wird, dad wir einen Bau haben, von Gott erbauet, ein Haus, nicht mit Handen gemacht, das ewig ist, im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Und uber demselbigen sehnen wir uns auch nach unserer Behausung, die vom Himmel ist, und uns verlanget, dad wir damit uberkleidet werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'So doch, wo wir bekleidet und nicht blod erfunden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Denn dieweil wir in der Hütte sind, sehnen wir uns und sind beschweret, sintemal wirwollten lieber nicht entkleidet, sondern uberkleidet werden, auf dad das Sterbliche wurde verschlungen von dem Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Der uns aber zu demselbigen bereitet, das ist Gott, der uns das Pfand, den Geist gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Wir sind aber getrost allezeit und wissen, dad, dieweil wir im Leibe wohnen, so wallen wir dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Denn wirwandeln im Glauben und nicht im Schauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Wir sind aber getrost und haben vielmehr Lust, auder dem Leibe zu wallen und daheim zu sein bei dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Darum fleidigen wir uns auch, wir sind daheim Oder wallen, dad wir ihm wohlgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Denn wir müssen alle offenbar werden vor dem Richterstuhl Christi, auf dad ein jeglicher empfange, nachdem ergehandelt hat bei Leibesleben, es sei gut Oder bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Dieweil wir denn wissen, dad der Herr zu furchten ist, fahren wir schon mit den Leuten; aber Gott sind wir offenbar. Ich hoffe aber, dad wir auch in eurem Gewissen offenbar sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Dad wir uns nicht abermal loben, sondern euch eine Ursache geben, zu rühmen von uns, auf dad ihr habet zu ruhmen wider die, so sich nach dem Ansehen ruhmen und nicht nach dem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Denn tun wir zu viel, so tun wir\'s Gott; sind wir mal Jig, so sind wir euch mafüg.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Denn die Liebe Christi dringet uns also, sintemal wir halten, dafi, so einer fur alle gestorben ist, so sind sie alle gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Und er ist darum fur sie alle gestorben, auf dafi die, so da leben, hinfort nicht ihnen selbst leben, sondern dem, der fur sie gestorben und auferstanden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Darum von nun an kennen wir niemand nach dem Fleisch; und ob wirauch Christum gekannt haben nach dem Fleisch, so kennen wir ihn doch jetzt nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Darum, ist jemand in Christo, so ist er eine neue Kreatur. Das Alte ist vergangen; siehe, es ist alles neu worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Aber das alles von Gott, der uns mit ihm selber versohnet hat durch Jesum Christum und das Amt gegeben, das die Versohnung prediget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Denn Gott war in Christo und versohnete die Welt mit ihm selber und rechnete ihnen ihre Sunden nicht zu und hat unter uns aufgerichtet das Wort von der Versohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'So sind wir nun Botschafter an Christi Statt; denn Gott vermahnet durch uns. So bitten wir nun an Christi Statt: Lasset euch versohnen mit Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Denn er hat den, der von keiner Sunde wulite, fur uns zur Sunde gemacht, auf dafi wir würden in ihm die Gerechtigkeit, die vor Gott gilt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Wir ermahnen aber euch als Mithelfer, daü ihr nicht vergeblich die Gnade Gottes empfanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Denn er spricht: Ich habe dich in der angenehmen Zeit erhoret und habe dir am Tage des Heils geholfen. Sehet, jetzt ist die angenehme Zeit, jetzt ist der Tag des Heils.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Lasset uns aber niemand irgendein Argernis geben, auf daü unser Amt nicht verlastert werde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'sondern in alien Dingen lasset uns beweisen als die Diener Gottes: in großer Geduld, in Trübsalen, in Noten, in Angsten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'in Schlagen, in Gefangnissen, in Aufruhren, in Arbeit, in Wachen, in Fasten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'in Keuschheit, in Erkenntnis, in Langmut, in Freundlichkeit, in dem Heiligen Geist, in ungefarbter Liebe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'in dem Wort der Wahrheit, in der Kraft Gottes, durch Waffen der Gerechtigkeit zur Rechten und zur Linken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'durch Ehre und Schande, durch bose Geruchte und gute Geruchte; als die Verführer und doch wahrhaftig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'als die Unbekannten und doch bekannt; als die Sterbenden, und siehe, wir leben; als die Gezüchtigten und doch nicht ertotet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'als die Traurigen, aber allezeit frohlich; als die Armen, aber die doch viele reich machen; ais die nichts innehaben und doch alles haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'O ihr Korinther, unser Mund hat sich zu euch aufgetan; unser Herz ist getrost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Unserthalben dürft ihr euch nicht angsten. Dali ihr euch aber angstet, das tut ihr aus herzlicher Meinung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Ich rede mit euch als mit meinen Kindern, dafi ihr euch auch also gegen mich stellet und seiet auch getrost.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ziehet nicht am fremden Joch mit den Unglaubigen! Denn was hat die Gerechtigkeit fur Geniefi mit der Ungerechtigkeit? Was hat das Licht fur Gemeinschaft mit der Finsternis?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Wie stimmt Christus mit Belial? Oder was fur ein Teil hat der Glaubige mit dem Unglaubigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Was hat der Tempel Gottes fur Gleichheit mit den Gotzen? Ihr aber seid der Tempel des lebendigen Gottes, wie denn Gott spricht: Ich will in ihnen wohnen und in ihnen wandeln und will ihr Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Darum gehet aus von ihnen und sondert euch ab, spricht der Herr, und rühret kein Unreines an, so will ich euch annehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'und euer Vater sein, und ihr sollet meine Sohne und Tochter sein, spricht der allmachtige Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Dieweil wir nun solche Verheüiung haben, meine Liebsten, so lasset uns von aller Befleckung des Fleisches und des Geistes uns reinigen und fortfahren mit der Heiligung in der Furcht Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Fasset uns! Wir haben niemand Leid getan; wir haben niemand verletzt; wir haben niemand ubervorteilet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nicht sage ich solches, euch zu verdammen; denn ich habe droben zuvor gesagt, daü ihr in unserm Herzen seid, mitzusterben und mitzuleben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Ich rede mit grower Freudigkeit zu euch; ich rühme viel von euch; ich bin erfüllet mit Trost; ich bin überschwenglich in Freuden in aller unserer Trübsal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Denn da wir nach Mazedonien kamen, hatte unser Fleisch keine Ruhe, sondern allenthalben waren wir in Trübsal: auswendig Streit, inwendig Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Aber Gott, der die Geringen trostet, der trostete uns durch die Ankunft des Titus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Nicht allein aber durch seine Ankunft, sondern auch durch den Trost, damit er getrostet war an euch, und verkündigte uns euer Verlangen, euer Weinen, euren Eifer urn mich, also dafi ich mich noch mehr freuete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Denn dafi ich euch durch den Brief habe traurig gemacht, reuet mich nicht. Und ob\'s mich reuete, so ich aber sehe, daß der Brief vielleicht eine Weile euch betrübt hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'so freue ich mich doch nun, nicht daruber, daß ihr seid betrübt worden, sondern daß ihr seid betrübt worden zur Reue. Denn ihr seid gottlich betrübt worden, daß ihr von uns ja keinen Schaden irgend worinnen nehmet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Denn die gottliche Traurigkeit wirket zur Seligkeit eine Reue, die niemand gereuet; die Traurigkeit aber der Welt wirket den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Siehe, dasselbige, dafi ihr gottlich seid betrubt worden, welchen Fleil J hat es in euch gewirket, dazu Verantwortung, Zorn, Furcht, Verlangen, Eifer, Rachel Ihr habt euch beweiset in alien Stricken, dafi ihr rein seid an der Tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Darum, ob ich euch geschrieben habe, so ist\'s doch nicht geschehen um deswillen, der beleidiget hat, auch nicht um deswillen, der beleidiget ist, sondern um deswillen, daß euer Fleift gegen uns offenbar würde bei euch vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Derhalben sind wir getrostet worden, daü ihr getrostet seid. Uberschwenglicher aber haben wir uns noch mehr gefreuet uber die Freude des Titus; denn sein Geist ist erquicket an euch alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Denn was ich vor ihm von euch gerühmet habe, bin ich nicht zuschanden worden; sondern gleichwie alles wahr ist, was ich mit euch geredet habe, also ist auch unser Ruhmen vor Titus wahr worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Und er ist uberaus herzlich wohl an euch, wenn er gedenket an euer aller Gehorsam, wie ihr ihn mit Furcht und Zittern habt aufgenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Ich freue mich, daß ich mich zu euch alles versehen dart.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Ich tue euch kund, liebe Bruder, die Gnade Gottes, die in den Gemeinden in Mazedonien gegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Denn ihre Freude war da überschwenglich, da sie durch viel Trubsal arm waren, haben sie doch reichlich gegeben in aller Einfaltigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Denn nach allem Vermogen (das zeuge ich) und uber Vermogen waren sie selbst willig');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'und fleheten uns mit vielem Ermahnen, daß wir aufnahmen die Wohltat und Gemeinschaft der Handreichung, die da geschieht den Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Und nicht, wie wir hofften, sondern ergaben sich selbst zuerst dem Herrn und danach uns durch den Willen Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'da(S wir muliten Titus ermahnen, auf dafi er, wie er zuvor hatte angefangen, also auch unter euch solche Wohltat ausrichtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Aber gleichwie ihr in alien Stricken reich seid, im Glauben und im Wort und in der Erkenntnis und in allerlei Fleifi und in eurer Liebe zu uns, also schaffet, daß ihr auch in dieser Wohltat reich seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nicht sage ich, daü ich etwas gebiete, sondern dieweil andere so fleilüg sind, versuche ich auch eure Liebe, ob sie rechter Art sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Denn ihr wisset die Gnade unsers Herrn Jesu Christi, daß, ob erwohl reich ist, ward er doch arm um euretwillen, auf dafi ihr durch seine Armut reich würdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Und mein Wohlmeinen hierinnen gebe ich. Denn solches ist euch nutzlich, die ihr angefangen habt vor dem Jahre her, nicht allein das Tun, sondern auch das Wollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Nun aber vollbringet auch das Tun, auf daß, gleichwie da ist ein geneigt Gemut zu wollen, so sei auch da ein geneigt Gemut zu tun von dem, was ihr habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Denn so einer willig ist, so ister angenehm, nachdem er hat, nicht nachdem er nicht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Nicht geschieht das der Meinung, daß die andern Ruhe haben und ihr Trubsal, sondern daßes gleich sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'So diene euer Uberfluli ihrem Mangel diese (teure) Zeit lang, auf daß auch ihr Uberschwang hernach diene eurem Mangel, und geschehe, was gleich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Wie geschrieben stehet: Der viel sammelte, hatte nicht Uberfluli,, und der wenig sammelte, hatte nicht Mangel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Gott aber sei Dank, der solchen Fleili fur euch gegeben hat in das Herz des Titus!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Denn er nahm zwar die Ermahnung an; aber dieweil er so sehr fleilüg war, ist er von selber zu euch gereiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Wir haben aber einen Bruder mit ihm gesandt; der das Lob hat am Evangelium durch alle Gemeinden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'nicht allein aber das, sondern er ist auch verordnet von den Gemeinden zum Gefahrten unserer Fahrt in dieser Wohltat, welche durch uns ausgerichtet wird dem Herrn zu Ehren und (zum Preis) eures guten Willens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Und verhuten das, daß uns nicht jemand übel nachreden moge solcher reichen Steuer halben, die durch uns ausgerichtet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'und sehen darauf, daß es redlich zugehe, nicht allein vor dem Herrn, sondern auch vor den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Auch haben wir mit ihnen gesandt unsern Bruder, den wir oft gespuret haben in vielen Stricken, daß er fleilüg sei, nun aber viel fleilüger.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Und wir sind grolier Zuversicht zu euch, es sei des Titus halben, welcher mein Geselle und Gehilfe unter euch ist, Oder unserer Bruder halben, welche Apostel sind der Gemeinden und eine Ehre Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Erzeiget nun die Beweisung eurer Liebe und unsers Ruhms von euch an diesen, auch offentlich vor den Gemeinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Denn von solcher Steuer, die den Heiligen geschieht, ist mir nicht not, euch zu schreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Denn ich weili euren guten Willen, davon ich rühme bei denen aus Mazedonien (und sage): Achaja ist vor dem Jahr bereit gewesen. Und euer Exempel hat viele gereizet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Ich habe aber diese Brüder darum gesandt, daß nicht unser Ruhm von euch zunichte wurde in dem Stücke, und daß ihr bereit seid, gleichwie ich von euch gesagt habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'auf dati nicht, so die aus Mazedonien mit mir kamen und euch unbereitet fanden, wir (will nicht sagen ihr) zuschanden würden mit solchem Rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Ich habe es aber fur notig angesehen, die Brüder zu ermahnen, daß sie voranzogen zu euch, zu verfertigen diesen zuvorverheilienen Segen, daß er bereitet sei, also dati es sei ein Segen und nicht ein Geiz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ich meine aber das: Wer da karglich saet, der wird auch karglich ernten; und wer da saet im Segen, der wird auch ernten im Segen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Ein jeglicher nach seiner Willkur, nicht mit Unwillen Oder aus Zwang; denn einen frohlichen Geber hat Gott lieb.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Gott aber kann machen, daß allerlei Gnade unter euch reichlich sei, daß ihr in alien Dingen voile Genüge habet und reich seid zu allerlei guten Werken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'wie geschrieben stehet: Er hat ausgestreuet und gegeben den Armen; seine Gerechtigkeit bleibet in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Der aber Samen reichet beim Saemann, der wird je auch das Brot reichen zur Speise und wird vermehren euren Samen und wachsen lassen das Gewachs eurer Gerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'daß ihr reich seid in alien Dingen mit aller Einfaltigkeit, welche wirket durch uns Danksagung Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Denn die Handreichung dieser Steuer erfullet nicht allein den Mangel der Heiligen, sondern istauch überschwenglich darinnen, daß viele Gott danken fur diesen unsern treuen Dienst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'und preisen Gott uber eurem untertanigen Bekenntnis des Evangeliums Christi und fiber eurer einfaltigen Steuer an sie und an alle');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'und fiber ihrem Gebet fur euch, welche verlanget nach euch, um der überschwenglichen Gnade Gottes willen in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Gott aber sei Dank fur seine unaussprechliche Gabe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Ich aber, Paulus, ermahne euch durch die Sanftmütigkeit und Lindigkeit Christi, der ich gegenwartig unter euch gering bin, im Abwesen aber bin ich turstig gegen euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Ich bitte aber, daß mir nicht not sei, gegenwartig turstig zu handeln und der Kuhnheit zu brauchen, die man mirzumisset, gegen etliche, die uns schatzen, als wandelten wir fleischlicherweise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Denn ob wirwohl im Fleisch wandeln, so streiten wir doch nicht fleischlicherweise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Denn die Waffen unserer Ritterschaft sind nicht fleischlich, sondern machtig vor Gott, zu zerstoren die Befestungen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'damit wir zerstoren die Anschlage und alle Hohe, die sich erhebet wider die Erkenntnis Gottes und nehmen gefangen alle Vernunft unter den Gehorsam Christi');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'und sind bereit, zu rachen alien Ungehorsam, wenn euer Gehorsam erfullet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Richtet ihr nach dem Ansehen? Verlatit sich jemand darauf, daß er Christo angehore, der denke solches, auch wieder um bei ihm, daß, gleichwie er Christo angehoret, also gehoren wir auch Christo an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Und so ich auch etwas weiter, mich ruhmete von unserer Gewalt, welche uns der Herr gegeben hat, euch zu bessern und nicht zu verderben, wollte ich nicht zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, '(Das sage ich aber,) daß ihr nicht euch dünken lasset, als hatte ich euch wollen schrecken mit Briefen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Denn die Briefe (sprechen, sie) sind schwer und stark; aber die Gegenwartigkeit des Leibes ist schwach und die Rede verachtlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Wer ein solcher ist, der denke, daß wie wir sind mit Worten in den Briefen im Abwesen, so dürfen wir auch wohl sein mit der Tat gegenwartig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Denn wir dürfen uns nicht unter die rechnen Oder zahlen, so sich selbst loben; aber dieweil sie sich bei sich selbst messen und halten allein von sich selbst, verstehen sie nichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Wir aber rühmen uns nicht fiber das Ziel, sondern nur nach dem Ziel der Regel, damit uns Gott abgemessen hat das Ziel, zu gelangen auch bis an euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Denn wirfahren nicht zu weit, als waren wir nicht gelanget bis zu euch; denn wir sind ja auch bis zu euch kommen mit dem Evangelium Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Und rühmen uns nicht fiber das Ziel in fremder Arbeit und haben Hoffnung, wenn nun euer Glaube in euch gewachsen, daß wir unserer Regel nach wollen weiter kommen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'und das Evangelium auch predigen denen, die jenseit euch wohnen, und uns nicht rühmen in dem, was mit fremder Regel bereitet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Wer sich aber rühmet, derrühme sich des Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Denn darum ist einer nicht tüchtig, daß er sich selbst lobet, sondern daß ihn der Herr lobet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Wollte Gott, ihr hieltet mir ein wenig Torheit zugut! Doch ihr haltet mir\'s wohl zugut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Denn ich eifere um euch mit gottlichem Eifer. Denn ich habe euch vertrauet einem Manne, daß ich eine reine Jungfrau Christo zubrachte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ich fürchte aber, daß nicht, wie die Schlange Eva verfuhrete mit ihrer Schalkheit, also auch eure Sinne verrucket werden von der Einfaltigkeit in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Denn so, der da zu euch kommt, einen andern Jesum predigte, den wir nicht geprediget haben, Oder ihr einen andern Geist empfinget, den ihr nicht empfangen habt, Oder ein ander Evangelium, das ihr nicht angenommen habt, so vertrüget ihr\'s.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Denn ich achte, ich sei nicht weniger, denn die hohen Apostel sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Und ob ich albern bin mit Reden, so bin ich doch nicht albern in der Erkenntnis. Doch, ich bin bei euch allenthalben wohlbekannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Oder habe ich gesundiget, daß ich mich erniedriget habe, auf daß ihr erhohet wurdet? Denn ich habe euch das Evangelium umsonst verkundigt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'und habe andere Gemeinden beraubet und Sold von ihnen genommen, daß ich euch predigte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Und da ich bei euch war gegenwartig und Mangel hatte, war ich niemand beschwerlich (denn meinen Mangel erstatteten die Bruder, die aus Mazedonien kamen); und habe mich in alien Stricken euch unbeschwerlich gehalten und will auch noch mich also halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'So gewift die Wahrheit Christi in mir ist, so soil mir dieser Ruhm in den Landern Achajas nicht gestopfetwerden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Warum das? Daft ich euch nicht sollte liebhaben? Gott weift es.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Was ich aber tue und tun will, das tue ich darum, daß ich die Ursache abhaue denen, die Ursache suchen, daß sie rühmen mochten, sie seien wie wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Denn solche falsche Apostel und trugliche Arbeiter verstellen sich zu Christi Aposteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Und das ist auch kein Wunder; denn erselbst, der Satan, verstellet sich zum Engel des Lichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Darum istes nicht ein Groftes, ob sich auch seine Diener verstellen als Prediger der Gerechtigkeit; welcher Ende sein wird nach ihren Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Ich sage abermal, daß nicht jemand wahne, ich sei toricht; wo aber nicht, so nehmet mich an als einen Torichten, daß ich mich auch ein wenig rühme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Was ich jetzt rede, das rede ich nicht ais im Herrn, sondern als in der Torheit, dieweil wir in das Rühmen kommen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Sintemal viele sich rühmen nach dem Fleisch, will ich mich auch rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Denn ihr vertraget gerne die Narren, dieweil ihr klug seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Ihr vertraget, so euch jemand zu Knechten macht, so euch jemand schindet, so euch jemand nimmt, so jemand euch trotzet, so euch jemand in das Angesicht streicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Das sage ich nach der Unehre, als waren wir schwach worden. Worauf nun jemand kühn ist (ich rede in Torheit), darauf bin ich auch kühn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Sie sind Hebraer, ich auch. Sie sind Israelites ich auch. Sie sind Abrahams Same, ich auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Sie sind Diener Christi; (ich rede toricht) ich bin wohl mehr. Ich habe mehr gearbeitet, ich habe mehr Schlage erlitten, ich bin ofter gefangen, oft in Todesnoten gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Von den Juden habe ich fünfmal empfangen vierzig Streiche weniger eines.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Ich bin dreimal gestaupet, einmal gesteiniget, dreimal habe ich Schiffbruch erlitten, Tag und Nacht habe ich zugebracht in der Tiefe (des Meers).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Ich bin oft gereiset; ich bin in Gefahr gewesen zu Wasser, in Gefahr unter den Mordern, in Gefahr unter den Juden, in Gefahr unter den Heiden, in Gefahr in den Stadten, in Gefahr in der Wuste, in Gefahr auf dem Meer, in Gefahr unter den falschen Brüdern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'in Mühe und Arbeit, in viel Wachen, in Hunger und Durst, in viel Fasten, in Frost und Blofte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'ohne was sich sonst zutragt, namlich daß ich taglich werde angelaufen und trage Sorge fur alle Gemeinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Wer ist schwach, und ich werde nicht schwach? Wer wird geargert, und ich brenne nicht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'So ich mich je rühmen soil, will ich mich meiner Schwachheit rühmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Gottund der Vater unsers Herrn Jesu Christi, welcher sei gelobet in Ewigkeit, weift, daß ich nicht luge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Zu Damaskus, der Landpfleger des Konigs Aretas verwahrete die Stadt der Damasker und wollte mich greifen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'und ich ward einem Korbe zum Fenster aus durch die Mauer niedergelassen und entrann aus seinen Handen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Es ist mir ja das Rühmen nichts nütze; doch will ich kommen auf die Gesichte und Offenbarungen des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Ich kenne einen Menschen in Christo vor vierzehn Jahren (ist er in dem Leibe gewesen, so weift ich\'s nicht, Oder ist er aufter dem Leibe gewesen, so weift ich\'s auch nicht; Gott weift es); derselbige ward entzückt bis in den dritten Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Und ich kenne denselbigen Menschen (ob er in dem Leibe Oder aufter dem Leibe gewesen ist, weift ich nicht; Gott weift es).');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Er ward entzückt in das Paradies und horete unaussprechliche Worte, welche kein Mensch sagen kann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Davon will ich mich rühmen; von mir selbst aber will ich mich nichts rühmen ohne meiner Schwachheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Und so ich mich rühmen wollte, tate ich darum nicht toricht; denn ich wollte die Wahrheit sagen. Ich enthalte mich aber des, auf daß nicht jemand mich hoher achte, denn er an mir siehet, Oder von mir horet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Und auf daß ich mich nicht der hoher Offenbarung überhebe, ist mir gegeben ein Pfahl ins Fleisch, namlich des Satanas Engel, der mich mit Fausten schlage, auf daß ich mich nicht überhebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Dafür ich dreimal zum Herrn geflehet habe, daß ervon mirwiche;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'und er hat zu mir gesagt: La(i dir an meiner Gnade genugen; denn meine Kraft ist in den Schwachen machtig. Darum will ich mich am allerliebsten ruhmen meiner Schwachheit, auf daß die Kraft Christi bei mirwohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Darum bin ich gutes Muts in Schwachheiten, in Schmachen, in Noten, in Verfolgungen, in Angsten urn Christi willen. Denn wenn ich schwach bin, so bin ich stark.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ich bin ein Narr worden uber den Ruhmen; dazu habt ihr mich gezwungen. Denn ich sollte von euch gelobet werden, sintemal ich nichts weniger bin, denn die hohen Apostel sind; wiewohl ich nichts bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Denn es sind ja eines Apostels Zeichen unter euch geschehen mit aller Geduld; mit Zeichen und mit Wundern und mit Taten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Welches ist\'s, darinnen ihr geringerseid denn die andern Gemeinden, ohne daß ich selbst euch nicht habe beschweret? Vergebet mir diese Sunde!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Siehe, ich bin bereit, zum drittenmal zu euch zu kommen, und will euch nicht beschweren; denn ich suche nicht das Eure, sondern euch. Denn es sollen nicht die Kinder den Eltern Schatze sammeln, sondern die Eltern den Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Ich will aber fast gerne darlegen und dargelegt werden fur eure Seelen; wiewohl ich euch fast sehr liebe und doch wenig geliebt werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Aber laß also sein, daß ich euch nicht habe beschweret, sondern dieweil ich tuckisch war, habe ich euch mit Hinterlist gefangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Habe ich aber auch jemand ubervorteilet durch deren etliche, die ich zu euch gesandt habe?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Ich habe Titus ermahnet und mit ihm gesandt einen Bruder. Hat euch auch Titus ubervorteilet? Haben wir nicht in einem Geist gewandelt? Sind wir nicht in eineriei Fufitapfen gegangen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Lasset ihr euch abermal dünken, wir verantworten uns? Wir reden in Christo vor Gott; aber das alles geschieht, meine Liebsten, euch zur Besserung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Denn ich furchte, wenn ich komme, daß ich euch nicht finde, wie ich will, und ihr mich auch nicht findet, wie ihrwollet: daß nicht Hader, Neid, Zorn, Zank, Afterreden, Ohrenblasen, Aufblahen, Aufruhr da sei;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'daß ich nicht abermal komme, und mich mein Gott demutige bei euch, und musse Leid tragen uber viele, die zuvor gesündiget und nicht Bulie getan haben fur die Unreinigkeit und Hurerei und Unzucht, die sie getrieben haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Komme ich zum drittenmal zu euch, so soil in zweier Oder dreier Zeugen Munde bestehen allerlei Sache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Ich hab es euch zuvor gesagt und sage es euch zuvor als gegenwartig zum andernmal und schreibe es nun im Abwesen denen, die zuvor gesündiget haben, und den andern alien: Wenn ich abermal komme, so will ich nicht schonen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Sintemal ihrsuchet, daß ihreinmal gewahr werdet des, der in mir redet, namlich Christi, welcher unter euch nicht schwach ist, sondern ist machtig unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Und ob erwohl gekreuziget ist in der Schwachheit, so lebet er doch in der Kraft Gottes. Und ob wir auch schwach sind in ihm, so leben wir doch mit ihm in der Kraft Gottes unter euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Versuchet euch selbst, ob ihr im Glauben seid, prufet euch selbst! Oder erkennet ihr euch selbst nicht, daß Jesus Christus in euch ist? Es sei denn, daß ihr untüchtig seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Ich hoffe aber, ihr erkennet, daß wir nicht untüchtig sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Ich bitte aber Gott, daß ihr nichts Ubles tut, nicht auf daß wir tüchtig gesehen werden, sondern auf daß ihr das Gute tut, und wir wie die Untuchtigen seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Denn wir konnen nichts wider die Wahrheit, sondern fur die Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Wirfreuen uns aber, wenn wir schwach sind, und ihr machtig seid. Und dasselbige wünschen wir auch namlich eure Vollkommenheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Derhalben ich auch solches abwesend schreibe, auf daß ich nicht, wenn ich gegenwartig bin, Scharfe brauchen musse nach der Macht, welche mir der Herr, zu bessern und nicht zu verderben, gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Zuletzt, liebe Bruder, freuet euch, seid vollkommen, trostet euch, habt eineriei Sinn, seid friedsam, so wird Gott der Liebe und des Friedens mit euch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Grülieteuch untereinander mitdem heiligen Kufi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Es grulien euch alle Heiligen. Die Gnade unsers Herm Jesu Christi und die Liebe Gottes und die Gemeinschaft des Heiligen Geistes sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus, ein Apostel (nicht von Menschen, auch nicht durch Menschen, sondern durch Jesum Christum und Gott den Vater, der ihn auferwecket hat von den Toten),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'und alle Bruder, die bei mirsind: Den Gemeinden in Galatien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Gnade sei mit euch und Friede von Gott dem Vater und unserm Herrn Jesu Christo,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'dersich selbst fur unsere Sunden gegeben hat, daß er uns errettete von dieser gegenwartigen argen Welt nach dem Willen Gottes und unsers Vaters,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'welchem sei Ehre von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Mich wundert, daß ihr euch so bald abwenden lasset von dem, der euch berufen hat in die Gnade Christi, auf ein ander Evangelium,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'so doch kein anderes ist; ohne daß etliche sind, die euch verwirren und wollen das Evangelium Christi verkehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Aber so auch wir Oder ein Engel vom Himmel euch wurde Evangelium predigen anders, denn das wir euch geprediget haben, der sei verflucht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Wie wir jetzt gesagt haben, so sagen wir auch abermal: So jemand euch Evangelium prediget anders, denn das ihrempfangen habt, der sei verflucht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Predige ich denn jetzt Menschen Oder Gott zu Dienst? Oder gedenke ich, Menschen gefallig zu sein? Wenn ich den Menschen noch gefallig ware, so ware ich Christi Knecht nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Ich tue euch aber kund, liebe Bruder, daß das Evangelium, das von mir geprediget ist, nicht menschlich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Denn ich hab\' es von keinem Menschen empfangen noch gelernet, sondern durch die Offenbarung Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Denn ihr habt je wohl gehoret meinen Wandel weiland im Judentum, wie ich liber die Malien die Gemeinde Gottes verfolgte und verstorete sie');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'und nahm zu im Judentum liber viele meinesgleichen in meinem Geschlecht und eiferte liber die Malien urn das vaterliche Gesetz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Da es aber Gott wohlgefiel, der mich von meiner Mutter Leibe hat ausgesondert und berufen durch seine Gnade,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'daß erseinen Sohn offenbarete in mir, daß ich ihn durchs Evangelium verkündigen sollte unter den Heiden, alsobald fuhr ich zu und besprach mich nicht darüber mit Fleisch und Blut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'kam auch nicht gen Jerusalem zu denen, die vor mir Apostel waren, sondern zog hin nach Arabien und kam wiederum gen Damaskus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Danach liber drei Jahre kam ich gen Jerusalem, Petrus zu schauen, und blieb fünfzehn Tage bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Der andern Apostel aber sah ich keinen ohne Jakobus, des Herrn Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Was ich euch aber schreibe, siehe, Gott weili, ich luge nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Danach kam ich in die Lander Syrien und Zilizien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Ich war aber unbekannt von Angesicht den christlichen Gemeinden in Judaa.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Sie hatten aber allein gehoret, daß, der uns weiland verfolgte, der prediget jetzt den Glauben, welchen er weiland verstorete;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'und preiseten Gott liber mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Danach liber vierzehn Jahre zog ich abermal hinauf gen Jerusalem mit Barnabas und nahm Titus auch mit mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Ich zog aber hinauf aus einer Offenbarung und besprach mich mit ihnen liber dem Evangelium, das ich predige unter den Heiden, besonders aber mit denen, die das Ansehen hatten, auf daß ich nicht vergeblich liefe Oder gelaufen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Aber es ward auch Titus nicht gezwungen, sich zu beschneiden, der mit mir war, ob er wohl ein Grieche war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Denn da etliche falsche Brüder sich mit eingedrungen und neben eingeschlichen waren, zu verkundschaften unsere Freiheit, die wir haben in Christo Jesu, daß sie uns gefangennahmen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'wichen wirdenselbigen nicht eine Stunde, untertan zu sein, auf daß die Wahrheit des Evangeliums bei euch bestunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Von denen aber, die das Ansehen hatten, welcherlei sie weiland gewesen sind, da liegt mir nichts an; denn Gott achtet das Ansehen der Menschen nicht. Mich aber haben die, so das Ansehen hatten, nichts anderes gelehret,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'sondern wiederum, da sie sahen, daß mir vertrauet war das Evangelium an die Vorhaut, gleichwie Petrus das Evangelium an die Beschneidung');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(denn der mit Petrus kraftig ist gewesen zum Apostelamt unter die Beschneidung, der ist mit mir auch kraftig gewesen unter die Heiden),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'und erkannten die Gnade, die mir gegeben war, Jakobus und Kephas und Johannes, die fur Saulen angesehen waren, gaben sie mir und Barnabas die rechte Hand und wurden mit uns eins, daß wir unter die Heiden, sie aber unter der Beschneidung predigten;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'allein daß wir der Armen gedachten, welches ich auch fleilüg bin gewesen zu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Da aber Petrus gen Antiochien kam, widerstund ich ihm unter Augen; denn es war Klage liber ihn kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Denn zuvor, ehe etliche von Jakobus kamen, ali er mit den Heiden; da sie aber kamen, entzog er sich und sonderte sich, darum daß er die von der Beschneidung fürchtete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Und heuchelten mit ihm die andern Juden, also daß auch Barnabas verfuhret ward, mit ihnen zu heucheln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Aber da ich sah, daß sie nicht richtig wandelten nach der Wahrheit des Evangeliums, sprach ich zu Petrus vor alien offentlich: So du, der du ein Jude bist, heidnisch lebest und nicht judisch, warum zwingest du denn die Heiden, judisch zu leben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Wiewohl wir von Natur Juden und nicht Sunder aus den Heiden sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'doch, weil wirwissen, daß der Mensch durch des Gesetzes Werke nicht gerecht wird, sondern durch den Glauben an Jesum Christum, so glauben wir auch an Christum Jesum, auf daß wir gerecht werden durch den Glauben an Christum und nicht durch des Gesetzes Werke; denn durch des Gesetzes Werke wird kein Fleisch gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Sollten wir aber, die da suchen durch Christum gerecht zu werden, auch noch selbst als Sunder erfunden werden, so ware Christus ein Sündendiener. Das sei feme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Wenn ich aber das, so ich zerbrochen habe, wiederum baue, so mache ich mich selbst zu einem Ubertreter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Ich bin aber durchs Gesetz dem Gesetz gestorben auf daß ich Gott lebe; ich bin mit Christo gekreuziget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Ich lebe aber, doch nun nicht ich, sondern Christus lebet in mir. Denn was ich jetzt lebe im Fleisch, das lebe ich in dem Glauben des Sohnes Gottes, der mich geliebet hat und sich selbst fur mich dargegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Ich werfe nicht weg die Gnade Gottes; denn so durch das Gesetz die Gerechtigkeit kommt, so ist Christus vergeblich gestorben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O ihr unverstandigen Galater, wer hat euch bezaubert, daß ihr der Wahrheit nicht gehorchet? welchen Christus Jesus vor die Augen gemalet war, und jetzt unter euch gekreuziget ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Das will ich allein von euch lernen: Habt ihr den Geist empfangen durch des Gesetzes Werke Oder durch die Predigt vom Glauben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Seid ihr so unverstandig? Im Geist habt ihr angefangen, wollt ihr\'s denn nun im Fleisch vollenden?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Habt ihr denn so viel umsonst erlitten? Ist\'s anders umsonst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Der euch nun den Geist reichet und tut solche Taten unter euch, tut er\'s durch des Gesetzes Werke Oder durch die Predigt vom Glauben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Gleichwie Abraham hat Gott geglaubet, und ist ihm gerechnet zur Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'So erkennet ihr ja nun, daß, die des Glaubens sind, das sind Abrahams Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Die Schrift aber hat es zuvor ersehen, daß Gott die Heiden durch den Glauben gerecht macht. Darum verkundigte sie dem Abraham: In dir sollen alle Heiden gesegnet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Also werden nun, die des Glaubens sind, gesegnet mit dem glaubigen Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Denn die mit des Gesetzes Werken umgehen, die sind unter dem Fluch; denn es stehet geschrieben: Verflucht sei jedermann, der nicht bleibet in alledem, das geschrieben stehet in dem Buch des Gesetzes, daß er\'s tue!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Daft aber durchs Gesetz niemand gerecht wird vor Gott, ist offenbar; denn der Gerechte wird seines Glaubens leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Das Gesetz aber ist nicht des Glaubens, sondern der Mensch, der es tut, wird dadurch leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christus aber hat uns erloset von dem Fluch des Gesetzes, da erward ein Fluch fur uns (denn es stehet geschrieben: Verflucht sei jedermann, der am Holz hangeti),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'auf daß der Segen Abrahams unter die Heiden kame in Christo Jesu, und wir also den verheiftenen Geist empfingen durch den Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Liebe Bruder, ich will nach menschlicher Weise reden: Verachtet man doch eines Menschen Testament nicht, wenn es bestatiget ist, und tut auch nichtsdazu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Nun istje die Verheiftung Abraham und seinem Samen zugesagt. Erspricht nicht: durch die Samen, als durch viele, sondern als durch einen, durch deinen Samen, welcher ist Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ich sage aber davon: Das Testament, das von Gott zuvor bestatiget ist auf Christum, wird nicht aufgehoben, daß die Verheiftung sollte durchs Gesetz aufhoren, welches gegeben ist über vierhundertunddreiftig Jahre hernach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Denn so das Erbe durch das Gesetz erworben würde, so wurde es nicht durch Verheiftung gegeben. Gott aber hat es Abraham durch Verheiftung frei geschenkt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Was soil denn das Gesetz? Es ist dazukommen urn der Sünde willen, bis der Same kame, dem die Verheiftung geschehen ist, und ist gestellet von den Engeln durch die Hand des Mittlers.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ein Mittler aber ist nicht eines einigen Mittler; Gott aber ist einig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Wie? Ist denn das Gesetz wider Gottes Verheiftungen? Das sei feme! Wenn aber ein Gesetz gegeben ware, das da konnte lebendig machen, so kame die Gerechtigkeit wahrhaftig aus dem Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Aber die Schrift hat es alles beschlossen unter die Sünde, auf daß die Verheiftung kame durch den Glauben an Jesum Christum, gegeben denen, die da glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Ehe denn aber der Glaube kam, wurden wir unter dem Gesetz verwahret und verschlossen auf den Glauben, der da sollte offenbart werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Also ist das Gesetz unser Zuchtmeister gewesen auf Christum, daß wir durch den Glauben gerecht würden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Nun aber der Glaube kommen ist, sind wir nicht mehr unter dem Zuchtmeister.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Denn ihr seid alle Gottes Kinder durch den Glauben an Christum Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Denn wieviel euer getauft sind, die haben Christum angezogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Hier ist kein Jude noch Grieche, hier ist kein Knecht noch Freier, hier ist kein Mann noch Weib; denn ihr seid allzumal einer in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Seid ihr aber Christi, so seid ihr ja Abrahams Samen und nach der Verheiftung Erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Ich sage aber, solange der Erbe ein Kind ist, so ist unter ihm und einem Knechte kein Unterschied, ob er wohl ein Herr ist aller Guter,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'sondern er ist unter den Vormundern und Pflegern bis auf die bestimmte Zeit vom Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Also auch wir, da wir Kinder waren, waren wir gefangen unter den aufierlichen Satzungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Da aber die Zeit erfullet ward, sandte Gott seinen Sohn, geboren von einem Weibe und unter das Gesetz getan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'auf daß er die, so unter dem Gesetz waren, erlosete, daü wir die Kindschaft empfingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Weil ihr denn Kinder seid, hat Gott gesandt den Geist seines Sohnes in eure Herzen, der schreiet: Abba, lieber Vater!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Also ist nun hier kein Knecht mehr, sondern eitel Kinder. Sind\'s aber Kinder, so sind’s auch Erben Gottes durch Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Aber zu der Zeit, da ihr Gott nicht erkanntet, dientet ihr denen, die von Natur nicht Gotter sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Nun ihr aber Gott erkannt habt, ja vielmehr von Gott erkannt seid, wie wendet ihr euch denn urn wieder zu den schwachen und durftigen Satzungen, welchen ihr von neuem an dienen wollt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Ihr haltet Tage und Monden und Feste und Jahrzeiten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Ich furchte fur euch, daß ich nicht vielleicht umsonst habe an euch gearbeitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Seid doch wie ich, denn ich bin wie ihr. Liebe Bruder, ich bitte euch, ihr habt mir kein Leid getan.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Denn ihrwisset, daß ich euch in Schwachheit nach dem Fleisch das Evangelium geprediget habe zum erstenmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Und meine Anfechtungen, die ich leide nach dem Fleisch, habt ihr nicht verachtet noch verschmahet, sondern als einen Engel Gottes nahmet ihr mich auf, ja als Christum Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Wie waret ihr dazumal so selig! Ich bin euer Zeuge, daß, wenn es moglich gewesen ware, ihr hattet eure Augen ausgerissen und mirgegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Bin ich denn also euer Feind worden, daß ich euch die Wahrheit vorhalte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Sie eifern urn euch nicht fein, sondern sie wollen euch von mir abfallig machen, daß ihr urn sie sollt eifern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Eifern ist gut, wenn\'s immerdar geschiehet urn das Gute und nicht allein, wenn ich gegenwartig bei euch bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Meine lieben Kinder, welche ich abermal mit Angsten gebare, bis daß Christus in euch eine Gestalt gewinne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Ich wollte aber, daß ich jetzt bei euch ware, und meine Stimme wandeln konnte, denn ich bin irre an euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Saget mir, die ihr unter dem Gesetz sein wolit: Habt ihr das Gesetz nicht gehoret?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Denn es stehet geschrieben, daß Abraham zween Sohne hatte, einen von der Magd, den andern von der Freien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Aber der von der Magd war, ist nach dem Fleisch geboren; der aber von der Freien, ist durch die Verheiftung geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Die Worte bedeuten etwas. Denn das sind die zwei Testamente, eines von dem Berge Sinai, das zur Knechtschaft gebieret, welches ist die Hagar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Denn Hagar heiftet in Arabien der Berg Sinai und langet bis gen Jerusalem, das zu dieser Zeit ist, und ist dienstbar mit seinen Kindern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Aber das Jerusalem, das droben ist, das ist die Freie, die ist unser aller Mutter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Denn es stehet geschrieben: Sei frohlich, du Unfruchtbare, die du nicht gebierest, und brich hervor und rufe, die du nicht schwanger bist! Denn die Einsame hat viel mehr Kinder, denn die den Mann hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Wir aber, liebe Bruder, sind Isaak nach der Verheiftung Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Aber gleichwie zu der Zeit, der nach dem Fleisch geboren war, verfolgete den, der nach dem Geist geboren war, also gehet es jetzt auch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Aber was spricht die Schrift? Stoft die Magd hinaus mit ihrem Sohn! Denn der Magd Sohn soli nicht erben mit dem Sohn der Freien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'So sind wir nun, liebe Bruder, nicht der Magd Kinder, sondern der Freien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'So bestehet nun in der Freiheit, damit uns Christus befreiet hat, und lasset euch nicht wiederum in das knechtische Joch fangen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Siehe, ich, Paulus, sage euch: Wo ihr euch beschneiden lasset, so ist euch Christus kein nütze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Ich zeuge abermal einem jeden, der sich beschneiden laftt, daß er noch das ganze Gesetz schuldig istzu tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Ihr habt Christum verloren, die ihr durch das Gesetz gerecht werden wollt, und seid von der Gnade gefalien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Wir aber warten im Geist durch den Glauben der Gerechtigkeit, der man hoffen muß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Denn in Christo Jesu gilt weder Beschneidung noch Vorhaut etwas, sondern der Glaube, der durch die Liebe tatig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Ihr liefet fein. Wer hat euch aufgehalten, der Wahrheit nicht zu gehorchen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Solch Uberreden ist nicht von dem, der euch berufen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Ein wenig Sauerteig versauert den ganzen Teig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ich versehe mich zu euch in dem Herm, ihr werdet nicht anders gesinnet sein. Wer euch aber irremacht, der wird sein Urteil tragen, er sei, wer er wolle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Ich aber, liebe Bruder, so ich die Beschneidung noch predige, warum leide ich denn Verfolgung? So hatte das Argernis des Kreuzes aufgehoret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Wollte Gott, daß sie auch ausgerottet wurden, die euch verstoren!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Ihr aber, liebe Bruder, seid zur Freiheit berufen Aliein sehet zu, daß ihr durch die Freiheit dem Fleisch nicht Raum gebet, sondern durch die Liebe diene einer dem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Denn alle Gesetze werden in einem Wort erfüllet, in dem: Liebe deinen Nachsten wie dich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'So ihr euch aber untereinander beißet und fresset, so sehet zu, daß ihr nicht untereinander verzehret werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Ich sage aber: Wandelt im Geist, so werdet ihr die Luste des Fleisches nicht vollbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Denn das Fleisch gelustet wider den Geist und den Geist wider das Fleisch. Dieselbigen sind wider einander, daß ihr nicht tut, was ihr wollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Regieret euch aber der Geist, so seid ihr nicht unter dem Gesetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Offenbar sind aber die Werke des Fleisches, als da sind: Ehebruch, FHurerei, Unreinigkeit, Unzucht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Abgotterei, Zauberei, Feindschaft, Hader, Neid, Zorn, Zank, Zwietracht, Rotten, Haß, Mord,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Saufen, Fressen und dergleichen; von welchen ich euch habe zuvor gesagt und sage noch zuvor, daß, die solches tun, werden das Reich Gottes nicht erben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Die Frucht aber des Geistes ist: Liebe, Freude, Friede, Geduld, Freundlichkeit, Gütigkeit, Glaube, Sanftmut, Keuschheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Wider solche ist das Gesetz nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Welche aber Christo angehoren, die kreuzigen ihr Fleisch samt den Lusten und Begierden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'So wir im Geist leben, so lasset uns auch im Geist wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Lasset uns nicht eitler Ehre geizig sein, untereinander zu entrusten und zu hassen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Liebe Bruder, so ein Mensch etwa von einem Fehl ubereilet würde, so helfet ihm wieder zurecht mit sanftmutigem Geist, die ihrgeistlich seid. Und siehe auf dich selbst, daß du nicht auch versucht werdest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Einer trage des andern Last, so werdet ihr das Gesetz Christi erfullen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'So aber sich jemand lasset dunken, er sei etwas, so er doch nichts ist, der betruget sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Ein jeglicher aber prufe sein selbst Werk, und alsdann wird eran sich selber Ruhm haben und nicht an einem andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Denn ein jeglicher wird seine Last tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Der aber unterrichtet wird mit dem Wort, der teile mit allerlei Gutes dem, der ihn unterrichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Irret euch nicht; Gott laßt sich nicht spotten! Denn was der Mensch saet, das wird er emten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Wer auf sein Fleisch saet, der wird von dem Fleisch das Verderben emten; wer aber auf den Geist saet, der wird von dem Geist das ewige Leben emten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Lasset uns aber Gutes tun und nicht müde werden; denn zu seiner Zeit werden wir auch emten ohne Aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Als wir denn nun Zeit haben, so lasset uns Gutes tun an jedermann, allermeist aber an des Glaubens Genossen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Sehet, mit wie vielen Worten hab\' ich euch geschrieben mit eigener Hand!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Die sich wollen angenehm machen nach dem Fleisch, die zwingen euch zu beschneiden, aliein daß sie nicht mit dem Kreuz Christi verfolget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Denn auch sie selbst, die sich beschneiden lassen, halten das Gesetz nicht, sondern sie wollen, daß ihr euch beschneiden lasset, auf daß sie sich von eurem Fleisch rühmen mogen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Es sei aber feme von mir rühmen denn aliein von dem Kreuz unsers Herrn Jesu Christi, durch welchen mir die Welt gekreuziget ist und ich der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Denn in Christo Jesu gilt weder Beschneidung noch Vorhaut etwas, sondern eine neue Kreatur.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Und wieviel nach dieser Regel einhergehen, uber die sei Friede und Barmherzigkeit und über den Israel Gottes!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Hinfort mache mir niemand weiter Mühe; denn ich trage die Malzeichen des Herrn Jesu an meinem Leibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Die Gnade unsers Herrn Jesu Christi sei mit eurem Geist, liebe Bruder! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes: Den Heiligen zu Ephesus und Glaubigen an Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Gelobet sei Gott und der Vater unsers Herrn Jesu Christi, der uns gesegnet hat mit allerlei geistlichem Segen in himmlischen Gutern durch Christum;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'wie er uns denn erwahlet hat durch denselbigen, ehe der Welt Grund gelegt war, daß wir sollten sein heilig und unstraflich vor ihm in der Liebe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'und hat uns verordnet zur Kindschaft gegen ihn selbst durch Jesum Christum, nach dem Wohlgefallen seines Willens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'zu Lob seiner herrlichen Gnade, durch welche er uns hat angenehm gemacht in dem Geliebten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'an welchem wir haben die Erlosung durch sein Blut, namlich die Vergebung der Sünden, nach dem Reichtum seiner Gnade,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'welche uns reichlich widerfahren ist durch allerlei Weisheit und Klugheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Und hat uns wissen lassen das Geheimnis seines Willens nach seinem Wohlgefallen und hat dasselbige hervorgebracht durch ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'daß es geprediget würde, da die Zeit erfullet war, auf daß alle Dinge zusammengefassetwürden in Christo, beide, das im Himmel und auch auf Erden ist, durch ihn selbst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'durch welchen wir auch zum Erbteil kommen sind, die wir zuvor verordnet sind nach dem Vorsatz des, der alle Dinge wirket nach dem Rat seines Willens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'auf daß wir etwas seien zu Lob seiner Herrlichkeit, die wir zuvor auf Christum hoffen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'durch welchen auch ihr gehoret habtdas Wort der Wahrheit, namlich das Evangelium von eurer Seligkeit; durch welchen ihr auch, da ihrglaubetet, versiegelt worden seid mit dem Heiligen Geist der Verheiliung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'welcher ist das Pfand unsers Erbes zu unserer Erlosung, daß wir sein Eigentum würden zu Lob seiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Darum auch ich, nachdem ich gehoret habe von dem Glauben bei euch an den Herrn Jesum und von eurer Liebe zu alien Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'hore ich nichtauf, zu danken fur euch, und gedenke euer in meinem Gebet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'daß der Gott unsers Herrn Jesu Christi, der Vater der Herrlichkeit, gebe euch den Geist der Weisheit und der Offenbarung zu seiner selbst Erkenntnis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'und erleuchtete Augen eures Verstandnisses, daß ihr erkennen moget, welche da sei die Hoffnung eurer Berufung, und welcher sei der Reichtum seines herrlichen Erbes an seinen Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'und welche da sei die uberschwengliche Grolie seiner Kraft an uns, die wir glauben nach der Wirkung seiner machtigen Starke,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'welche er gewirket hat in Christo, da er ihn von den Toten auferwecket hat und gesetzt zu seiner Rechten im Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'uber alle Furstentümer, Gewalt, Macht, Herrschaft und ailes, was genannt mag werden, nicht allein in dieser Welt, sondern auch in derzukunftigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Und hat alle Dinge unter seine Fülie getan und hat ihn gesetzt zum Haupt der Gemeinde uber ailes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'welche da ist sein Leib, namlich die Fülle des, der ailes in alien erfullet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Und auch euch, da ihr tot waret durch Ubertretungen und Sunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'in welchen ihrweiland gewandelt habt nach dem Lauf dieser Welt und nach dem Fursten, der in der Luft herrschet, namlich nach dem Geist, der zu dieser Zeit sein Werk hat in den Kindern des Unglaubens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'unter welchen wir auch alle weiland unsern Wandel gehabt haben in den Lusten unsers Fleisches, und taten den Willen des Fleisches und der Vernunft und waren auch Kinder des Zorns von Natur, gleichwie auch die andern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'aber Gott, der da reich ist von Barmherzigkeit, durch seine grolie Liebe, damit er uns geliebet hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'da wir tot waren in den Sunden, hat er uns samt Christo lebendig gemacht (denn aus Gnaden seid ihr selig worden)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'und hat uns samt ihm auferwecket und samt ihm in das himmlische Wesen gesetzt in Christo Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'auf dafi er erzeigete in den zukünftigen Zeiten den uberschwenglichen Reichtum seiner Gnade durch seine Güte uber uns in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Denn aus Gnaden seid ihr selig worden durch den Glauben, und dasselbige nicht aus euch, Gottes Gabe ist es;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'nicht aus den Werken, auf daß sich nicht jemand rühme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Denn wir sind sein Werk, geschaffen in Christo Jesu zu guten Werken, zu welchen Gott uns zuvor bereitet hat, daü wir darinnen wandeln sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Darum gedenket daran, daß ihr, die ihr weiland nach dem Fleisch Heiden gewesen seid und die Vorhaut genannt wurdet von denen, die genannt sind die Beschneidung nach dem Fleisch, die mit der Hand geschieht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'daß ihr zu derselbigen Zeit waret ohne Christum, fremd und aulier der Burgerschaft Israels und fremd von den Testamenten der Verheiliung; daher ihr keine Hoffnung hattet und waret ohne Gott in der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Nun aber, die ihr in Christo Jesu seid und weiland feme gewesen, seid nun nahe worden durch das Blut Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Denn er ist unser Friede, der aus beiden eins hat gemacht und hat abgebrochen den Zaun, der dazwischen war, in dem, daß erdurch sein Fleisch wegnahm die Feindschaft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'namlich das Gesetz, so in Geboten gestellet war, auf daß er aus zweien einen neuen Menschen in ihm selber schaffete und Frieden machete,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'und daß er beide versohnete mit Gott in einem Leibe durch das Kreuz; und hat die Feindschaft getotet durch sich selbst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'und ist kommen, hat verkundiget im Evangelium den Frieden euch, die ihr feme waret, und denen, die nahewaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Denn durch ihn haben wirden Zugang alle beide in einem Geiste zum Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'So seid ihr nun nicht mehr Gaste und Fremdlinge, sondern Burger mit den Heiligen und Gottes Hausgenossen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'erbauetaufden Grund der Apostel und Propheten, da Jesus Christus der Eckstein ist');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'auf welchem derganze Bau, ineinandergefuget, wachset zu, einem heiligen Tempel in dem Herrn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'auf welchem auch ihr mit erbauet werdet zu einer Behausung Gottes. im Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Derhalben ich, Paulus, der Gefangene Christi Jesu fur euch Heiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'nachdem ihr gehoret habt von dem Amt der Gnade Gottes, die mir an euch gegeben ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'daß mir ist kund worden dieses Geheimnis durch Offenbarung, wie ich droben aufs kurzeste geschrieben habe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'daran ihr, so ihr\'s leset, merken konnet meinen Verstand an dem Geheimnis Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'welches nicht kundgetan ist in den vorigen Zeiten den Menschenkindern, als es nun offenbart ist seinen heiligen Aposteln und Propheten durch den Geist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'namlich daß die Heiden Miterben seien und mit eingeleibet und Mitgenossen seiner Verheiftung in Christo durch das Evangelium,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'des ich ein Diener worden bin nach der Gabe aus der Gnade Gottes, die mir nach seiner machtigen Kraft gegeben ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'mir, dem allergeringsten unter alien Heiligen, ist gegeben diese Gnade, unter den Heiden zu verkundigen den unausforschlichen Reichtum Christi');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'und zu erleuchten jedermann, welche da sei die Gemeinschaft des Geheimnisses, das von der Welt her in Gott verborgen gewesen ist, der alle Dinge geschaffen hat durch Jesum Christum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'auf daß jetzt kund wurde den Furstentumern und Herrschaften in dem Himmel an der Gemeinde die mannigfaltige Weisheit Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'nach dem Vorsatz von der Welt her, welche er beweiset hat in Christo Jesu, unserm Herrn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'durch welchen wir haben Freudigkeit und Zugang in aller Zuversicht durch den Glauben an ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Darum bitte ich, daß ihr nicht mude werdet urn meiner Trubsal willen, die ich fur euch leide, welche euch eine Ehre sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Derhalben beuge ich meine Kniee gegen den Vater unsers Herrn Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'der der rechte Vater ist über alles, was da Kinder heiftt im Himmel und auf Erden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'daß er euch Kraft gebe nach dem Reichtum seiner Herrlichkeit, stark zu werden durch seinen Geist an dem inwendigen Menschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'und Christum zu wohnen durch den Glauben in euren Herzen, und durch die Liebe eingewurzelt und gegrundet zu werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'auf daß ihr begreifen moget mit alien Heiligen, welches da sei die Breite und die Lange und die Tiefe und die Hohe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'auch erkennen, daß Christum liebhaben viel besser ist denn alles Wissen, auf daß ihr erfullet werdet mit allerlei Gottesfulle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Dem aber, der überschwenglich tun kann uber alles, was wir bitten Oder verstehen, nach der Kraft, die da in uns wirket,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'dem sei Ehre in der Gemeinde, die in Christo Jesu ist, zu aller Zeit, von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'So ermahne nun euch ich Gefangener in dem Herrn, daß ihr wandelt, wie sich\'s gebuhrt eurer Berufung, darinnen ihr berufen seid,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'mit aller Demut und Sanftmut, mit Geduld und vertraget einer den andern in der Liebe');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'und seid fleiftig, zu halten die Einigkeit im Geist durch das Band des Friedens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Ein Leib und ein Geist, wie ihr auch berufen seid auf einerlei Hoffnung eurer Berufung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Ein Herr, ein Glaube, eine Taufe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'ein Gott und Vater (unser) aller, der da ist fiber euch alle und durch euch alle und in euch alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Einem jeglichen aber unter uns ist gegeben die Gnade nach dem Maft der Gabe Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Darum spricht er: Er ist aufgefahren in die Hohe und hat das Gefangnis gefangen gefuhret und hat den Menschen Gaben gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Daft er aber aufgefahren ist, was ist\'s, denn daß er zuvor ist hinuntergefahren in die untersten Orter der Erde?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Der hinuntergefahren ist, das ist derselbige, der aufgefahren ist über alle Himmel, auf daß er alles erfullete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Und er hat etliche zu Aposteln gesetzt, etliche aberzu Propheten, etliche zu Evangelisten, etliche zu Hirten und Lehrern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'daß die Heiligen zugerichtet werden zum Werk des Amts, dadurch der Leib Christi erbauet werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'bis daß wir alle hinankommen zu einerlei Glauben und Erkenntnis des Sohnes Gottes und ein vollkommener Mann werden, der da sei im Maße des vollkommenen Alters Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'auf daß wir nicht mehr Kinder seien und uns wagen und wiegen lassen von allerlei Wind der Lehre durch Schalkheit der Menschen und Tauscherei, damit sie uns erschleichen zu verfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Lasset uns aber rechtschaffen sein in der Liebe und wachsen in alien Stricken an dem, der das Haupt ist, Christus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'aus welchem der ganze Leib zusammengefuget, und ein Glied am andern hanget durch alle Gelenke, dadurch eines dem andern Handreichung tut nach dem Werk eines jeglichen Gliedes in seinem Maße und machet, dafi der Leib wachset zu seiner selbst Besserung; und das alles in der Liebe:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'So sage ich nun und zeuge in dem Herrn, dati ihr nicht mehr wandelt, wie die andern Heiden wandeln der Eitelkeit ihres Sinnes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'welcher Verstand verfinstert ist, und sind entfremdet von dem Leben, das aus Gott ist, durch die Unwissenheit, so in ihnen ist, durch die Blindheit ihres Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'welche ruchlos sind und ergeben sich der Unzucht und treiben allerlei Unreinigkeit samt dem Geiz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ihr aber habt Christum nicht also gelernet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'so ihr anders von ihm gehoret habt und in ihm gelehret seid, wie in Jesu ein rechtschaffen Wesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'So leget nun von euch ab nach dem vorigen Wandel den alten Menschen, der durch Lüste in Irrtum sich verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Erneuert euch aber im Geist eures Gemüts');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'und ziehet den neuen Menschen an, der nach Gott geschaffen ist in rechtschaffener Gerechtigkeit und Heiligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Darum leget die Luge ab und redet die Wahrheit, ein jeglicher mit seinem Nachsten, sintemal wir untereinander Glieder sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Zürnet, und sundiget nicht; lasset die Sonne nicht uber eurem Zorn untergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Gebet auch nicht Raum dem Lasterer!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Wer gestohlen hat, der stehle nicht mehr, sondern arbeite und schaffe mit den Handen etwas Gutes, auf daß er habe, zu geben dem Dürftigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Lasset kein faul Geschwatz aus eurem Munde gehen, sondern was nutzlich zur Besserung ist, da es not tut, daß es holdselig sei zu horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Und betrubet nicht den Heiligen Geist Gottes, damit ihr versiegelt seid auf den Tag der Erlosung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Alle Bitterkeit und Grimm und Zorn und Geschrei und Lasterung sei feme von euch samt aller Bosheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Seid aber untereinander freundlich, herzlich und vergebet einer dem andern, gleichwie Gott euch vergeben hat in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'So seid nun Gottes Nachfolger als die lieben Kinder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Und wandelt in der Liebe, gleichwie Christus uns hat geliebet und sich selbst dargegeben fur uns zur Gabe und Opfer, Gott zu einem süßen Geruch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Hurerei aber und alle Unreinigkeit Oder Geiz lasset nicht von euch gesagt werden, wie den Heiligen zustehet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'auch schandbare Worte und Narrenteidinge Oder Scherz, welche euch nicht ziemen, sondern vielmehr Danksagung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Denn das sollt ihr wissen, dafi kein Hurer Oder Unreiner Oder Geiziger (welcher ist ein Gotzendiener) Erbe hat an dem Reich Christi und Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Lasset euch niemand verfuhren mit vergeblichen Worten! Denn urn dieser willen kommt der Zorn Gottes über die Kinder des Unglaubens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Darum seid nicht ihre Mitgenossen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Denn ihrwaretweiland Finsternis; nun aber seid ihr ein Licht in, dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Wandelt wie die Kinder des Lichts! Die Frucht des Geistes ist allerlei Gütigkeit und Gerechtigkeit und Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Und prüfet, was da sei wohlgefallig dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Und habt nicht Gemeinschaft mit den unfruchtbaren Werken der Finsternis; strafet sie aber vielmehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Denn was heimlich von ihnen geschieht, das ist auch schandlich zu sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Das alles aber wird offenbar, wenn es vom Licht gestraft wird. Denn alles, was offenbar wird, das ist Licht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Darum spricht er: Wache auf, der du schlafest, und stehe auf von den Toten, so wird dich Christus erleuchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'So sehet nun zu, wie ihrvorsichtiglich wandelt, nicht als die Unweisen, sondern als die Weisen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Und schicket euch in die Zeit; denn es ist bose Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Darum werdet nicht unverstandig, sondern verstandig, was da sei des Herrn Wille.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Und saufeteuch nicht voll Weins, daraus ein unordentlich Wesen folget, sondern werdet voll Geistes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'und redet untereinander von Psalmen und Lobgesangen und geistlichen Liedern; singet und spielet dem Herrn in euren Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Und saget Dank allezeit fur alles Gott und dem Vater in dem Namen unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Und seid untereinander untertan in der Furcht Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Die Weiber seien untertan ihren Mannern als dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Denn der Mann ist des Weibes Haupt, gleichwie auch Christus das Haupt ist der Gemeinde, und er ist seines Leibes Heiland.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Aber wie nun die Gemeinde ist Christo untertan, also auch die Weiber ihren Mannern in alien Dingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Ihr Manner, liebet eure Weiber, gleichwie Christus auch geliebet hat die Gemeinde und hat sich selbst fur sie gegeben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'auf daß er sie heiligte, und hat sie gereiniget durch das Wasserbad im Wort,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'auf daß er sie sich selbst darstellete als eine Gemeinde, die herrlich sei, die nicht habe einen Flecken Oder Runzel Oder des etwas, sondern dafi sie heilig sei und unstraflich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Also sollen auch die Manner ihre Weiber lieben als ihre eigenen Leiber. Wersein Weib liebet, der liebet sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Denn niemand hat jemals sein eigen Fleisch gehasset, sondern er nahret es und pfleget sein, gleichwie auch der Herr die Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Denn wir sind Glieder seines Leibes, von seinem Fleisch und von seinem Gebeine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Urn deswillen wird ein Mensch verlassen Vater und Mutter und seinem Weibe anhangen, und werden zwei ein Fleisch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Das Geheimnis ist groß; ich sage aber von Christo und der Gemeinde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Doch auch ihr, ja ein jeglicher habe lieb sein Weib als sich selbst; das Weib aber furchte den Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Ihr Kinder, seid gehorsam euren Eltern in dem Herm; denn das ist billig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Ehre Vater und Mutter; das ist das erste Gebot, das Verheifiung hat:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Auf daß dir\'s wohl gehe, und du lange lebest auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Und ihr Vater, reizet eure Kinder nicht zum Zorn, sondern ziehet sie auf in der Zucht und Vermahnung zu dem Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Ihr Knechte, seid gehorsam euren leiblichen Herren mit Furcht und Zittern, in Einfaltigkeit eures Herzens, als Christo;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'nicht mit Dienst allein vor Augen, als den Menschen zu gefallen, sondern als die Knechte Christi, daß ihr solchen Willen Gottes tut von Herzen, mitgutem Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Lasset euch dunken, daß ihr dem Herm dienet und nicht den Menschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'und wisset, was ein jeglicher Gutes tun wird, das wird er von dem Herm empfangen, er sei ein Knecht Oder ein Freier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Und ihr Herren, tut auch dasselbige gegen sie und lasset das Drauen; und wisset, daß auch euer Herr im Himmel ist, und ist bei ihm kein Ansehen der Person.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Zuletzt meine Bruder, seid stark in dem Herm und in der Macht seiner Starke!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ziehet an den Harnisch Gottes, daß ihr bestehen konnet gegen die listigen Anlaufe des Teufels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Denn wir haben nicht mit Fleisch und Blut zu kampfen, sondern mit Fursten und Gewaltigen, namlich mit den Herren der Welt, die in der Finsternis dieser Welt herrschen, mit den bosen Geistern unter dem Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Urn deswillen so ergreifet den Harnisch Gottes, auf da(S ihr an dem bosen Tage Widerstand tun und alles wohl ausrichten und das Feld behalten moget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'So stehet nun, umgurtet an euren Lenden mit Wahrheit und angezogen mit dem Krebs der Gerechtigkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'und an den Beinen gestiefelt, als fertig, zu treiben das Evangelium des Friedens, damit ihr bereitet seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Vor alien Dingen aber ergreifet den Schild des Glaubens, mit welchem ihr ausloschen konnt alle feurigen Pfeile des Bosewichts.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Und nehmet den Helm des Heils und das Schwert des Geistes, welches ist das Wort Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Und betet stets in allem Anliegen mit Bitten und Flehen im Geist und wachet dazu mit allem Anhalten und Flehen fur alle Heiligen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'und fur mich, auf daß mir gegeben werde das Wort mit freudigem Auftun meines Mundes, daß ich moge kundmachen das Geheimnis des Evangeliums,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'welches Bote ich bin in der Kette, auf daß ich darinnen freudig handeln moge und reden, wie sich\'s gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Auf daß aber ihr auch wisset, wie es urn mich stehet, und was ich schaffe, wird\'s euch alles kundtun Tychikus, mein lieber Bruder und getreuer Diener in dem Herrn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'welchen ich gesandt habe zu euch urn desselbigenwillen, daß ihr erfahret, wie es urn mich stehet, und daß er eure Herzen troste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Friede sei den Brudern und Liebe mit Glauben von Gott dem Vater und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Gnade sei mit alien, die da liebhaben unsern Herrn Jesum Christum unverruckt! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus und Timotheus, Knechte Jesu Christi: Allen Heiligen in Christo Jesu zu Philippi samtden Bischofen und Dienern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ich danke meinem Gott, so oft ich euer gedenke');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, '(welches ich allezeit tue in allem meinem Gebet fur euch alle, und tue das Gebet mit Freuden),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'uber eurer Gemeinschaft am Evangelium vom ersten Tage an bis her.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Und bin desselbigen in guter Zuversicht, daß, der in euch angefangen hat das gute Werk, der wird\'s auch vollfuhren bis an den Tag Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Wie es denn mir bilüg ist, daß ich dermaüen von euch alien halte, darum daß ich euch in meinem Herzen habe in diesem meinem Gefangnis, darin ich das Evangelium verantworte und bekraftige, als die ihr alle mit mir der Gnade teilhaftig seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Denn Gott ist mein Zeuge, wie mich nach euch alien verlanget von Herzensgrund in Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Und darum bete ich, daü eure Liebe je mehr und mehr reich werde in allerlei Erkenntnis und Erfahrung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'daß ihr prufen moget, was das Beste sei, auf daß ihr seid lauter und unanstofüg bis auf den Tag Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'erfullet mit Fruchten der Gerechtigkeit, diedurch Jesum Christum geschehen (in euch) zu Ehre und Lobe Gottes.]');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Ich lasse euch aberwissen, liebe Brüder, daü, wie es urn mich stehet, das ist nur mehr zur Forderung des Evangeliums geraten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'also daß meine Bande offenbar worden sind in Christo in dem ganzen Richthause und bei den andern alien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'und viel Brüder in dem Herrn aus meinen Banden Zuversicht gewonnen, desto turstiger worden sind, das Wort zu reden ohne Scheu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Etliche zwar predigen Christum auch urn Hasses und Haders willen, etliche aber aus guter Meinung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Jene verkundigen Christum aus Zank und nicht lauter; denn sie meinen, sie wollen eine Trübsal zuwenden meinen Banden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Diese aber aus Liebe; denn sie wissen, daü ich zur Verantwortung des Evangeliums hier liege.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Was ist ihm aber denn? Daü nur Christus verkundiget werde allerlei Weise, es geschehe Zufalles Oder rechter Weise; so freue ich mich doch darinnen und will mich auch freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Denn ich weili, daß mir dasselbige gelingetzur Seligkeit durch euer Gebet und durch Handreichung des Geistes Jesu Christi');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'wie ich endlich warte und hoffe, daß ich in keinerlei Stuck zuschanden werde, sondern daü mit aller Freudigkeit, gleichwie sonst allezeit, also auch jetzt, Christus hoch gepreiset werde an meinem Leibe, es sei durch Leben Oder durch Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Denn Christus ist mein Leben, und Sterben ist mein Gewinn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Sintemal aber im Fleisch leben dienet, mehr Frucht zu schaffen, so weüi ich nicht, welches ich erwahlen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Denn es liegt mir beides hart an: Ich habe Lust abzuscheiden und bei Christo zu sein, welches auch viel besser ware:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Aberes ist notiger, im Fleisch bleiben urn euretwilien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Und in guter Zuversicht weüi ich, daß ich bleiben und bei euch alien sein werde euch zur Forderung und zur Freude des Glaubens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'auf daü ihr euch sehr ruhmen moget in Christo Jesu an mir durch meine Ankunft wieder zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Wandelt nur wurdiglich dem Evangelium Christi, auf daß, ob ich komme und sehe euch Oder abwesend von, euch hore, daü ihr stehet in einem Geist und einer Seele und samt uns kampfet fur den Glauben des Evangeliums');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'und euch in keinem Wege erschrecken lasset von den Widersachern, welches ist ein Anzeichen, ihnen der Verdammnis euch aber der Seligkeit, und dasselbige von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Denn euch ist gegeben, urn Christi willen zu tun, daß ihr nicht allein an ihn glaubet, sondern auch urn seinetwillen leidet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'und habet denselbigen Kampf, welchen ihr an mir gesehen habt und nun von mir horet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Ist nun bei euch Ermahnung in Christo, ist Trost der Liebe, ist Gemeinschaft des Geistes, ist herzliche Liebe und Barmherzigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'so erfullet meine Freude, daß ihr eines Sinnes seid, gleiche Liebe habet, einmutig und einhellig seid,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'nichts tut durch Zank Oder eitle Ehre, sondern durch Demut achtet euch untereinander einer den andern hoher denn sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Und ein jeglicher sehe nicht auf das Seine, sondern auf das, was des andern ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Ein jeglicher sei gesinnet, wie Jesus Christus auch war,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'welcher, ob er wohl in gottlicher Gestalt war, hielt er\'s nicht fur einen Raub, Gott gleich sein,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'sondern entauüerte sich selbst und nahm Knechtsgestalt an, ward gleich wie ein anderer Mensch und an Gebarden als ein Mensch erfunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'erniedrigte sich selbst und ward gehorsam bis zum Tode, ja zum Tode am Kreuz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Darum hat ihn auch Gott erhohet und hat ihm einen Namen gegeben, der uber alle Namen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'daü in dem Namen Jesu sich beugen sollen alle derer Kniee, die im Himmel und auf Erden und unter der Erde sind,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'und alle Zungen bekennen sollen, dafi Jesus Christus der Herr sei, zur Ehre Gottes des Vaters.]');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Also, meine Liebsten, wie ihr allezeit seid gehorsam gewesen, nicht allein in meiner Gegenwart, sondern auch nun viel mehr in meiner Abwesenheit: Schaffet, daß ihrselig werdet, mit Furcht und Zittern!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Denn Gott ist\'s, der in euch wirket beides, das Wollen und das Vollbringen, nach seinem Wohlgefallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Tut alles ohne Murmeln und ohne Zweifel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'auf daß ihr seid ohne Tadel und lauter und Gottes Kinder, unstraflich mitten unter dem unschlachtigen und verkehrten Geschlecht, unter welchem ihr scheinet als Lichter in der Welt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'damit, daß ihr haltet ob dem Wort des Lebens, mir zu einem Ruhm an dem Tage Christi, als der ich nicht vergeblich gelaufen noch vergeblich gearbeitet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Und ob ich geopfert werde uber dem Opfer und Gottesdienst eures Glaubens, so freue ich mich und freue mich mit euch alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Desselbigen sollt ihr euch auch freuen und sollt euch mit mir freuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Ich hoffe aber in dem Herm Jesu, daß ich Timotheus bald werde zu euch senden, daß ich auch erquicket werde, wenn ich erfahre, wie es urn euch stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Denn ich habe keinen, der so gar meines Sinnes sei, der so herzüch fur euch sorget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Denn sie suchen alle das Ihre, nicht das Christi Jesu ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ihr aber wisset, daß er rechtschaffen ist; denn wie ein Kind dem Vater hat er mit mir gedienet am Evangelium.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Denselbigen, hoffe ich, werde ich senden von Stund\' an, wenn ich erfahren habe, wie es urn mich stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ich vertraue aber in dem Herrn, daß auch ich selbst bald kommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Ich hab\'s aber fur notig angesehen, den Bruder Epaphroditus zu euch zu senden, der mein Gehilfe und Mitstreiter und euer Apostel und meiner Notdurft Diener ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'sintemal er nach euch alien Verlangen hatte und war hoch bekümmert darum, daß ihr gehoret hattet, daß er krank war gewesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Und er war zwar todkrank, aber Gott hat sich uber ihn erbarmet, nicht allein aber uber ihn, sondern auch uber mich, auf daß ich, nicht eine Traurigkeit uber die andere hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Ich habe ihn aber desto eilender gesandt, auf daß ihr ihn sehet und wieder frohlich werdet, und ich auch der Traurigkeit weniger habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'So nehmet ihn nun auf in dem Herrn mit alien Freuden und habt solche in Ehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Denn urn des Werks Christi willen ist er dem Tode so nahe kommen, da ersein Leben gering bedachte, auf daß er mir dienete an eurer Statt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Weiter, liebe Bruder, freuet euch in dem Herrn! Daft ich euch immer einerlei schreibe, verdrieftt mich nicht und macht euch desto gewisser.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Sehet auf die Hunde, sehet auf die bosen Arbeiter, sehet auf die Zerschneidung!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Denn wir sind die Beschneidung; die wir Gott im Geist dienen und ruhmen uns von Christo Jesu und verlassen uns nicht auf Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Wiewohl ich auch habe, daß ich mich Fleisches ruhmen mochte. So ein anderer sich dünken lasset, er moge sich Fleisches ruhmen, ich viel mehr,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'der ich am achten Tage beschnitten bin, einer aus dem Volk von Israel, des Geschlechts Benjamin, ein Ebraer aus den Ebraern und nach dem Gesetz ein Pharisaer,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'nach dem Eifer ein Verfolger der Gemeinde, nach der Gerechtigkeit im Gesetz gewesen unstraflich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Aber was mir Gewinn war, das habe ich urn Christi willen fur Schaden geachtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Denn ich achte es alles fur Schaden gegen die überschwengliche Erkenntnis Christi Jesu, meines Herrn, urn welches willen ich alles habe fur Schaden gerechnet und achte es fur Dreck, auf daß ich Christum gewinne');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'und in ihm erfunden werde, daß ich nicht habe meine Gerechtigkeit, die aus dem Gesetz, sondern die durch den Glauben an Christum kommt, namlich die Gerechtigkeit, die von Gott dem Glauben zugerechnet wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'zu erkennen ihn und die Kraft seiner Auferstehung und die Gemeinschaft seiner Leiden, daß ich seinem Tode ahnlich werde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'damit ich entgegenkomme zur Auferstehung der Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nicht daß ich\'s schon ergriffen habe oderschon vollkommen sei; ich jage ihm aber nach, ob ich\'s auch ergreifen mochte, nachdem ich von Christo Jesu ergriffen bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Meine Bruder, ich schatze mich selbst noch nicht, daß ich\'s ergriffen habe. Eines aber sage ich: Ich vergesse, was dahinten ist, und strecke mich zu dem, das da vorne ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'und jage nach dem vorgesteckten Ziel, nach dem Kleinod, welches vorhalt die himmlische Berufung Gottes in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Wieviel nun unser vollkommen sind, die lasset uns also gesinnet sein. Und sollt ihr sonst etwas halten, das lasset euch Gott offenbaren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'doch so feme, daß wir nach einer Regel, darein wir kommen sind, wandeln und gleichgesinnet seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Folget mir, liebe Bruder, und sehet auf die, die also wandeln, wie ihr uns habt zum Vorbilde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Denn viele wandeln, von welchen ich euch oft gesagt habe, nun aber sage ich auch mit Weinen: Die Feinde des Kreuzes Christi;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'welcher Ende ist die Verdammnis, welchen der Bauch ihr Gott ist, und ihre Ehre zuschanden wird, derer, die irdisch gesinnet sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Unser Wandel aber ist im Himmel von dannen wir auch warten des Heilandes Jesu Christi, des Herrn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'welcher unsern nichtigen Leib verklaren wird, daß er ahnlich werde seinem verklarten Leibe, nach der Wirkung, damit er kann auch alle Dinge ihm untertanig machen.]');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Also, meine lieben und gewünschten Bruder, meine Freude und meine Krone, bestehet also in dem Herrn, ihr Lieben!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Die Evodia ermahne ich, und die Syntyche ermahne ich, daß sie eines Sinnes seien in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, ich bitte auch dich, mein treuer Geselle, stehe ihnen bei, die samt mir uber dem Evangelium gekampft haben mit Clemens und den andern meinen Gehilfen, welcher Namen sind in dem Buch des Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Freuet euch in dem Herrn allewege; und abermal sage ich: Freuet euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Eure Lindigkeit lasset kund sein alien Menschen. Der Herr ist nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Sorget nichts, sondern in alien Dingen lasset eure Bitte im Gebet und Flehen mit Danksagung vor Gott kund werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Und der Friede Gottes, welcher hoher ist denn alle Vernunft, bewahre eure Herzen und Sinne in Christo Jesu!]');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Weiter, liebe Bruder, was wahrhaftig ist, was ehrbar, was gerecht, was keusch, was lieblich, was wohl lautet, ist etwa eine Tugend, ist etwa ein Lob, dem denket nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Welches ihr auch gelernet und empfangen und gehoret und gesehen habt an mir, das tut, so wird der Herr des Friedens mit euch sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Ich bin aber hoch erfreuet in dem Herrn, daß ihr wieder wacker worden seid, fur mich zu sorgen, wiewohl ihr allewege gesorget habt; aber die Zeit hat\'s nichtwollen leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nicht sage ich das des Mangels halben; denn ich habe gelernet, bei welchen ich bin, mir genugen lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Ich kann niedrig sein und kann hoch sein; ich bin in alien Dingen und bei alien geschickt, beide, satt sein und hungern, beide, übrig haben und Mangel leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Ich vermag alles durch den, der mich machtig macht, Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Doch ihr habt wohl getan, daß ihr euch meiner Trubsal angenommen habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Ihr aber von Philippi wisset, daß von Anfang des Evangeliums, da ich auszog aus Mazedonien, keine Gemeinde mit mir geteilet hat nach der Rechnung der Ausgabe und Einnahme denn ihr alleine.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Denn gen Thessalonich sandtet ihr zu meiner Notdurft einmal und danach abereinmal.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nicht, daß ich das Geschenk suche, sondern ich suche die Frucht daß sie uberflussig in eurer Rechnung sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Denn ich habe alles und habe uberflussig. Ich bin erfullet, da ich empfing durch Epaphroditus, was von euch kam, ein sillier Geruch, ein angenehm Opfer, Gott gefallig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mein Gott aber erfulle alle eure Notdurft nach seinem Reichtum in der Herrlichkeit in Christo Jesu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Dem Gott aber und unserm Vater sei Ehre von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Grutiet alle Heiligen in Christo Jesu. Es grutien euch die Bruder, die bei mir sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Es grülien euch alle Heiligen, sonderlich aber die von des Kaisers Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Die Gnade unsers Herrn Jesu Christi sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, und Bruder Timotheus:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Den Heiligen zu Kolossa und den glaubigen Brndern in Christo. Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herm Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Wir danken Gott und dem Vater unsers Herm Jesu Christi und beten allezeit fur euch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'nachdem wir gehoret haben von eurem Glauben an Christum Jesum und von der Liebe zu alien Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'um der Hoffnung willen, die euch beigelegt ist im Himmel, von welcher ihr zuvor gehoret habt durch das Wort der Wahrheit im Evangelium,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'das zu euch kommen ist wie auch in alle Welt und ist fruchtbar wie auch in euch von dem Tage an, da ihr\'s gehoret habt und erkannt die Gnade Gottes in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Wie ihr denn gelernet habt von Epaphras, unserm lieben Mitdiener, welcher ist ein treuer Diener Christi fur euch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'der uns auch eroffnet hat eure Liebe im Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Derhalben auch wir von dem Tage an, da wir\'s gehoret haben, horen wir nicht auf, fur euch zu beten und zu bitten, daß ihr erfullet werdet mit Erkenntnis seines Willens in allerlei geistlicher Weisheit und Verstand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'daß ihr wandelt wurdiglich dem Herm zu allem Gefallen und fruchtbar seid in alien guten Werken');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'und wachset in der Erkenntnis Gottes und gestarket werdet mit aller Kraft nach seiner herrlichen Macht in aller Geduld und Langmutigkeit mit Freuden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'und danksaget dem Vater, der uns tuchtig gemacht hat zu dem Erbteil der Heiligen im Licht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'welcher uns errettet hat von der Obrigkeit der Finsternis und hat uns versetzt in das Reich seines lieben Sohnes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'an welchem wir haben die Erlosung durch sein Blut, namlich die Vergebung der Sunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'welcher ist das Ebenbild des unsichtbaren Gottes, der Erstgeborene vor alien Kreaturen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Denn durch ihn ist alles geschaffen, was im Himmel und auf Erden ist, das Sichtbare und Unsichtbare, beide, die Thronen und Herrschaften und Furstentumer und Obrigkeiten; es ist alles durch ihn und zu ihm geschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Und er ist vor alien; und es bestehet alles in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Und er ist das Haupt des Leibes, namlich der Gemeinde; welcher ist der Anfang und der Erstgeborene von den Toten, auf daß, er in alien Dingen den Vorrang habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Denn es ist das Wohlgefallen gewesen, daß in ihm alle Fülle wohnen sollte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'und alles durch ihn versohnet würde zu ihm selbst, es sei auf Erden Oder im Himmel, damit, dafi er Frieden machte durch das Blut an seinem Kreuz durch sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Und euch, die ihrweiland Fremde und Feinde waret durch die Vernunft in bosen Werken,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'nun aber hat er euch versohnet mit dem Leibe seines Fleisches durch den Tod, auf daß ereuch darstellete heilig und unstraflich und ohne Tadel vor ihm selbst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'so ihr anders bleibet im Glauben gegrundet und fest und unbeweglich von der Hoffnung des Evangeliums, welches ihr gehoret habt, welches geprediget ist unter aller Kreatur, die unter dem Himmel ist, welches ich, Paulus, Diener worden bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nun freue ich mich in meinem Leiden, das ich fur euch leide, und erstatte an meinem Fleisch, was noch mangelt an T rubsalen in Christo fur seinen Leib, welcher ist die Gemeinde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'welcher ich ein Diener worden bin nach dem gottlichen Predigtamt, das mir gegeben ist unter euch, daß ich das Wort Gottes reichlich predigen soli,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'namlich das Geheimnis, das verborgen gewesen ist von der Welt her und von den Zeiten her, nun aber offenbaret ist seinen Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'welchen Gott gewollt hat kundtun, welcher da sei der herrliche Reichtum dieses Geheimnisses unter den Heiden, welches ist Christus in euch, der da ist die Hoffnung der Herrlichkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'den wir verkundigen, und vermahnen alle Menschen und lehren alle Menschen mit aller Weisheit, auf daß wir darstellen einen jeglichen Menschen vollkommen in Christo Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'daran ich auch arbeite und ringe nach der Wirkung des, der in mir kraftiglich wirket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Ich lasse euch aber wissen, welch einen Kampf ich habe um euch und um die zu Laodicea und alle, die meine Person im Fleisch nicht gesehen haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'auf daß ihre Herzen ermahnet und zusammengefasset werden in der Liebe zu allem Reichtum des gewissen Verstandes, zu erkennen das Geheimnis Gottes und des Vaters und Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'in welchem verborgen liegen alle Schatze der Weisheit und der Erkenntnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Ich sage aber davon, daß euch niemand betruge mit vernunftigen Reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Denn ob ich wohl nach dem Fleisch nicht da bin, so bin ich aber im Geist bei euch, freue mich und sehe eure Ordnung und euren festen Glauben an Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Wie ihr nun angenommen habt den Herm Christum Jesum, so wandelt in ihm');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'und seid gewurzelt und erbauet in ihm und seid fest im Glauben, wie ihr gelehret seid, und seid in demselbigen reichlich dankbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Sehet zu, daß euch niemand beraube durch die Philosophie und lose Verfuhrung nach der Menschen Lehre und nach der Welt Satzungen und nicht nach Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Denn in ihm wohnet die ganze Fulle der Gottheit leibhaftig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Und ihr seid vollkommen in ihm, welcher ist das Haupt aller Furstentumer und Obrigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'in welchem ihr auch beschnitten seid mit der Beschneidung ohne Hande, durch Ablegung des sündlichen Leibes im Fleisch, namlich mit der Beschneidung Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'in dem, daß ihr mit ihm begraben seid durch die Taufe; in welchem ihr auch seid auferstanden durch den Glauben, den Gottwirket, welcher ihn auferweckt hat von den Toten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'und hat euch auch mit ihm lebendig gemacht, da ihr tot waret in den Sunden und in der Vorhaut eures Fleisches, und hat uns geschenket alle Sunden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'und ausgetilget die Handschrift, so wider uns war, welche durch Satzungen entstund und uns entgegen war, und hat sie aus dem Mittel getan und an das Kreuz geheftet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Und hat ausgezogen die Furstentumer und die Gewaltigen und sie Schau getragen offentlich und einen Triumph aus ihnen gemacht durch sich selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'So lasset nun niemand euch Gewissen machen uber Speise Oder uber Trank Oder uber bestimmte Feiertage Oder Neumonde Oder Sabbate,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'welches ist der Schatten von dem, was zukunftig war; aber der Korper selbst ist in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Lasset euch niemand das Ziel verrucken, der nach eigener Wahl einhergehet in Demut und Geistlichkeit der Engel, des er nie keines gesehen hat, und ist ohne Sache aufgeblasen in seinem fleischlichen Sinn');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'und halt sich nicht an dem Haupt, aus welchem der ganze Leib durch Gelenk und Fugen Handreichung empfanget, und aneinander sich enthalt und also wachset zur gottlichen Grolie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'So ihr denn nun abgestorben seid mit Christo den Satzungen der Welt, was lasset ihr euch denn fanqen mit Satzungen, als lebetet ihr noch in der Welt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Die da sagen: Du sollst das nicht angreifen, du sollst das nicht kosten, du sollst das nicht anruhren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'welches sich doch alles, unter Handen verzehret, und ist Menschengebot und - lehre;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'welche haben einen Schein der Weisheit durch selbsterwahlte Geistlichkeit und Demut und dadurch, daß sie des Leibes nicht verschonen und dem Fleisch nicht seine Ehre tun zu seiner Notdurft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Seid ihr nun mit Christo auferstanden, so suchet, was droben ist, da Christus ist, sitzend zu der Rechten Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Trachtet nach dem, was droben ist, und nicht nach dem, was auf Erden ist!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Denn ihr seid gestorben, und euer Leben ist verborgen mit Christo in Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Wenn aber Christus, euer Leben, sich offenbaren wird, dann werdet ihr auch offenbar werden mit ihm in der Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'So totet nun eure Glieder, die auf Erden sind: Hurerei, Unreinigkeit, schandliche Brunst, bose Lust und den Geiz, welcher ist Abgotterei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'urn welcher willen kommt der Zorn Gottes uber die Kinder des Unglaubens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'in welchen auch ihrweiland gewandelt habt, da ihr darin lebetet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Nun aber leget alles ab von euch: den Zorn, Grimm, Bosheit, Lasterung, schandbare Worte aus eurem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Luget nicht untereinander! Ziehet den alten Menschen mit seinen Werken aus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'und ziehet den neuen an, der da erneuert wird zu der Erkenntnis nach dem Ebenbilde des, der ihn geschaffen hat,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'da nicht ist Grieche, Jude, Beschneidung, Vorhaut, Ungrieche, Scythe, Knecht, Freier, sondern alles und in alien Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'So ziehet nun an, als die Auserwahlten Gottes, Heiligen und Geliebten, herzliches Erbarmen, Freundlichkeit, Demut, Sanftmut, Geduld');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'und vertrage einer den andern, und vergebet euch untereinander, so jemand Klage hat wider den andern; gleichwie Christus euch vergeben hat, also auch ihr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Uber alles aber ziehet an die Liebe, die da ist das Band der Vollkommenheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Und der Friede Gottes regiere in euren Herzen, zu welchem ihr auch berufen seid in einem Leibe; und seid dankbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Lasset das Wort Christi unter euch reichlich wohnen in aller Weisheit. Lehret und vermahnet euch selbst mit Psalmen und Lobgesangen und geistlichen lieblichen Liedern und singet dem Herrn in eurem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Und alles, was ihr tut mit Worten Oder mit Werken, das tut alles in dem Namen des Herrn Jesu und danket Gott und dem Vater durch ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ihr Weiber, seid untertan euren Mannern in dem Herrn, wie sich\'s gebuhrt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Ihr Manner, liebet eure Weiber und seid nicht bitter gegen sie!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Ihr Kinder, seid gehorsam den Eltern in alien Dingen; denn das ist dem Herrn gefallig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ihr Vater, erbittert eure Kinder nicht, auf daß sie nicht scheu werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Ihr Knechte, seid gehorsam in alien Dingen euren leiblichen Herren, nicht mit Dienst vor Augen, als den Menschen zu gefallen, sondern mit Einfaltigkeit des Herzens und mit Gottesfurcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Alles, was ihr tut, das tut von Herzen, als dem Herrn und nicht den Menschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'und wisset, daß ihr von dem Herrn empfangen werdet die Vergeltung des Erbes; denn ihr dienet dem Herm Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Wer aber unrecht tut, derwird empfangen; was er unrecht getan hat; und gilt kein Ansehen der Person.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Ihr Herren, was recht und gleich ist, das beweiset den Knechten und wisset, daß ihr auch einen Herm im Himmel habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Haltet an am Gebet und wachet in demselbigen mit Danksagung!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Und betet zugleich auch fur uns, auf daß Gott uns die Tür des Worts auftue, zu reden das Geheimnis Christi, darum ich auch gebunden bin,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'auf daß ich dasselbige offenbare, wie ich soil reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Wandelt weislich gegen die, die drauften sind, und schicket euch in die Zeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Eure Rede sei allezeit lieblich und mit Salz gewürzet, daß ihr wisset, wie ihr einem jeglichen antworten sollt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Wie es urn mich stehet, wird euch alles kundtun Tychikus, der liebe Bruder und getreue Diener und Mitknecht in dem Herm,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'welchen ich habe darum zu euch gesandt, daß er erfahre, wie es sich mit euch verhalt, und daß er eure Herzen ermahne,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'samt Onesimus, dem getreuen und lieben Bruder, welcher von den Euren ist. Alles, wie es hier zustehet, werden sie euch kundtun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Es grüftet euch Aristarchus, mein Mitgefangener, und Markus, der Neffe Barnabas, von welchem ihr etliche Befehle empfangen habt (so er zu euch kommt, nehmet ihn auf);');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Und Jesus, der da heiftt Just, die aus der Beschneidung sind. Diese sind allein meine Gehilfen am Reich Gottes, die mir ein Trost worden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Es grüftet euch Epaphras, der von den Euren ist, ein Knecht Christi, und allezeit ringet fur euch mit Gebeten, auf daß ihr bestehet vollkommen und erfullet mit allem Willen Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Ich gebe ihm Zeugnis, daß ergroften Fleift hat urn euch und urn die zu Laodicea und zu Hierapolis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Es grüftet euch Lukas, der Arzt, der Geliebte, und Demas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Grüftet die Bruder zu Laodicea und den, Nymphas und die Gemeinde in seinem Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Und wenn der Brief bei euch gelesen ist, so schaffet, daß er auch in der Gemeinde zu Laodicea gelesen werde, und daß ihr den von Laodicea leset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Und saget dem Archippus: Siehe auf das Amt, das du empfangen hast in dem Herrn, daß du dasselbige ausrichtest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Mein Gruft mit meiner, des Paulus, Hand. Gedenket meiner Bande! Die Gnade sei mit euch! Amen. Der erste Brief des Paulus an die Thessalonicher');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus und Silvanus und Timotheus: der Gemeinde zu Thessalonich, in Gott dem Vater und dem Herrn Jesu Christo. Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Wir danken Gott allezeit fur euch alle und gedenken euer in unserm Gebet ohne Unterlaft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Und denken an euer Werk im Glauben und an eure Arbeit in der Liebe und an eure Geduld in der Hoffnung, welche ist unser Herr Jesus Christus vor Gott und unserm Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Denn, liebe Bruder, von Gott geliebet, wir wissen, wie ihr auserwahlet seid,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'daß unser Evangelium ist bei euch gewesen nicht allein im Wort, sondern beide, in der Kraft und in dem Heiligen Geist und in grafter Gewiftheit; wie ihr wisset, welcherlei wir gewesen sind unter euch um euretwillen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Und ihr seid unsere Nachfolger worden und des Herrn und habt das Wort aufgenommen unter vielen Trubsalen mit Freuden im Heiligen Geist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'also daß ihr worden seid ein Vorbild alien Glaubigen in Mazedonien und Achaja.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Denn von euch ist auserschollen das Wort des Herrn nicht allein in Mazedonien und Achaja, sondern an alien Orten ist auch euer Glaube an Gott ausgebrochen, also daß nicht not ist, euch etwas zu sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Denn sie selbst verkundigen von euch, was fur einen Eingang wir zu euch gehabt haben, und wie ihr bekehret seid zu Gott von den Abgottern, zu dienen dem lebendigen und wahren Gott');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'und zu warten seines Sohns vom Himmel, welchen er auferwecket hat von den Toten, Jesum, der uns von dem zukünftigen Zorn erloset hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Denn auch ihr wisset, liebe Bruder, von unserm Eingange zu euch, daß er nicht vergeblich gewesen ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'sondern als wir zuvor gelitten hatten und geschmahet gewesen waren zu Philippi, wie ihr wisset, waren wir dennoch freudig in unserm Gott, bei euch zu sagen das Evangelium Gottes mit groftem Kampfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Denn unsere Ermahnung ist nicht gewesen zu Irrtum noch zu Unreinigkeit noch mit List,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'sondern wie wir von Gott bewahret sind, daß uns das Evangelium vertrauet istzu predigen, also reden wir, nicht als wollten wir den Menschen gefallen, sondern Gott, der unser Herz prufet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Denn wir sind nie mit Schmeichelworten umgegangen, wie ihrwisset, noch dem Geiz gestellet, Gott ist des Zeuge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Haben auch nicht Ehre gesucht von den Leuten, weder von euch noch von andern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Hatten euch auch mogen schwer sein als Christi Apostel; sondern wirsind mutterlich gewesen bei euch, gleichwie eine Amme ihrer Kinder pfleget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Also hatten wir Herzenslust an euch und waren willig, euch mitzuteilen nicht allein das Evangelium Gottes, sondern auch unser Leben, darum dafi wir euch liebgewonnen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Ihrseid wohl eingedenk, liebe Bruder, unserer Arbeit und unserer Muhe; denn Tag und Nacht arbeiteten wir, daß wir niemand unter euch beschwerlich waren, und predigten unter euch das Evangelium Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Des seid ihr Zeugen und Gott, wie heilig und gerecht und unstraflich wir bei euch, die ihr glaubig waret, gewesen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Wie ihr denn wisset, daß wir, als ein Vater seine Kinder, einen jeglichen unter euch ermahnet und getrostet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'und bezeuget haben, daß ihrwandeln solltet wurdiglich vor Gott, der euch berufen hat zu seinem Reich und zu seiner Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Darum auch wirohne Unterlaß Gottdanken, daß ihr, da ihr empfinget von uns das Wort gottlicher Predigt, nahmet ihr\'s auf nicht als Menschenwort, sondern (wie es denn wahrhaftig ist) als Gottes Wort; welcher auch wirket in euch, die ihr glaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Denn ihrseid Nachfolger worden, liebe Bruder, der Gemeinden Gottes in Judaa in Christo Jesu, daß ihr ebendasselbige erlitten habt von euren Blutsfreunden, das jene von den Juden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'welche auch den Herrn Jesum getotet haben und ihre eigenen Propheten und haben uns verfolget und gefallen Gott nicht und sind alien Menschen wider,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'wehren uns, zu sagen den Heiden, damit sie selig wurden, auf daß sie ihre Sünden erfullen allewege; denn der Zorn ist schon endlich uber sie kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Wir aber, liebe Bruder, nachdem wir euer eine Weile beraubet gewesen sind nach dem Angesichte, nicht nach dem Herzen, haben wir desto mehr geeilet.euer Angesicht zu sehen, mit großem Verlangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Darum haben wirwollen zu euch kommen (ich, Paulus) zweimal; und Satanas hat uns verhindert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Denn wer ist unsere Hoffnung Oder Freude Oder Krone des Ruhms? Seid nicht auch ihr\'s vor unserm Herrn Jesu Christo zu seiner Zukunft?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Ihr seid ja unsere Ehre und Freude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Darum haben wir\'s nicht weiter wollen vertragen und haben uns lassen wohlgefallen, daß wir zu Athen allein gelassen wurden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'und haben Timotheus gesandt, unsern Bruder und Diener Gottes und unsern Gehilfen am Evangelium Christi, euch zu starken und zu ermahnen in eurem Glauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'daß nicht jemand weich würde in diesen Trubsalen; denn ihrwisset, daß wirdazu gesetztsind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Und da wir bei euch waren, sagten wir\'s euch zuvor, wir wurden Trubsal haben müssen; wie denn auch geschehen ist, und ihrwisset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Darum ich\'s auch nicht langer vertragen, hab\' ich ausgesandt, daß ich erführe euren Glauben, auf daß nicht euch vielleicht versucht hatte der Versucher, und unsere Arbeit vergeblich würde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Nun aber, so Timotheus zu uns von euch kommen ist und uns verkundiget hat euren Glauben und Liebe, und daß ihr unser gedenket allezeit zum besten und verlanget nach uns zu sehen, wie denn auch uns nach euch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'da sind wir, liebe Bruder, getrostet worden an euch in aller unserer Trubsal und Not durch euren Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Denn nun sind wir lebendig, dieweil ihr stehet in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Denn was fur einen Dank konnen wir Gott vergelten urn euch fur alle diese Freude, die wir haben von euch vor unserm Gott?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Wir bitten Tag und Nacht fast sehr, daß wir sehen mogen euer Angesicht und erstatten, so etwas mangelt an eurem Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Er aber, Gott, unser Vater, und unser Herr Jesus Christus schicke unsern Weg zu euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Euch aber vermehre der Herr und lasse die Liebe vollig werden untereinander und gegen jedermann (wie denn auch wirsind gegen euch),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'daß eure Herzen, gestarket, unstraflich seien in der Heiligkeit vor Gott und unserm Vater auf die Zukunft unsers Herrn Jesu Christi samt alien seinen Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Weiter, liebe Bruder, bitten wir euch und ermahnen in dem Herrn Jesu (nachdem ihr von uns empfangen habt, wie ihr sollet wandeln und Gott gefallen), daß ihr immer volliger werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Denn ihr wisset, welche Gebote wir euch gegeben haben durch den Herrn Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Denn das ist der Wille Gottes, eure Heiligung, daß ihrmeidetdie Hurerei,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'und ein jeglicher unter euch wisse sein Faß zu behalten in Heiligung und Ehren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'nicht in der Lustseuche wie die Heiden, die von Gott nichts wissen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'und daß niemand zu weit greife noch ubervorteile seinen Bruder im Handel; denn der Herr ist der Racher uber das alles, wie wir euch zuvor gesagt und bezeuget haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Denn Gott hat uns nicht berufen zur Unreinigkeit, sondern zur Heiligung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Wer nun verachtet, der verachtet nicht Menschen, sondern Gott, der seinen Heiligen Geist gegeben hat in euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Von der bruderlichen Liebe aber ist nicht not, euch zu schreiben; denn ihr seid selbst von Gott gelehret euch untereinander zu lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Und das tut ihr auch an alien Brudern, die in ganz Mazedonien sind. Wirermahnen euch aber, liebe Brüder, daß ihr noch volliger werdet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Und ringet danach, daß ihr stille seid und das Eure schaffet und arbeitet mit euren eigenen Handen, wie wir euch geboten haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'auf dafi ihr ehrbarlich wandelt gegen die, die draulien sind, und ihrer keines bedurfet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Wirwollen euch aber, liebe Brüder, nicht verhalten von denen, die da schlafen, auf dafi ihr nicht traurig seid wie die andern, die keine Hoffnung haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Denn so wir glauben, dafi Jesus gestorben und auferstanden ist, also wird Gott auch, die da entschlafen sind durch Jesum, mit ihm führen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Denn das sagen wir euch als ein Wort des Herrn, daß wir, die wir leben und uberbleiben in der Zukunft des Herrn, werden denen nicht zuvorkommen, die da schlafen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Denn er selbst, der Herr, wird mit einem Feldgeschrei und Stimme des Erzengels und mit der Posaune Gottes herniederkommen vom Himmel, und die Toten in Christo werden auferstehen zuerst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Danach wir, die wir leben und uberbleiben, werden zugleich mit denselbigen hingerückt werden in den Wolken dem Herrn entgegen in der Luft; und werden also bei dem Herrn sein allezeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'So trostet euch nun mit diesen Worten untereinander!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Von den Zeiten aber und Stunden, liebe Bruder, ist nicht not, euch zu schreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Denn ihr selbst wisset gewiß, daß der Tag des Herrn wird kommen wie ein Dieb in der Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Denn wenn sie werden sagen: Es ist Friede, es hat keine Gefahr! so wird sie das Verderben schnell überfallen, gleich wie der Schmerz ein schwanger Weib, und werden nicht entfliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Ihr aber, liebe Bruder, seid nicht in der Finsternis, dafi euch der Tag wie ein Dieb ergreife.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Ihr seid allzumal Kinder des Lichts und Kinder des Tages; wir sind nicht von der Nacht noch von der Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'So lasset uns nun nicht schlafen wie die andern, sondern lasset uns wachen und nuchtern sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Denn die da schlafen, die schlafen des Nachts, und die da trunken sind, die sind des Nachts trunken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Wir aber, die wir des Tages sind, sollen nuchtern sein, angetan mit dem Krebs des Glaubens und der Liebe und mit dem Helm der Hoffnung zur Seligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Denn Gott hat uns nicht gesetzt zum Zorn, sondern die Seligkeit zu besitzen durch unsern Herrn Jesum Christum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'der fur uns gestorben ist, auf daß, wir wachen Oder schlafen, wir zugleich mit ihm leben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Darum ermahnet euch untereinander und bauet einer den andern, wie ihr denn tut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Wir bitten euch aber, liebe Bruder, dafi ihr erkennet, die an euch arbeiten und euch vorstehen in dem Herrn und euch vermahnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Habt sie desto lieber urn ihres Werks willen und seidfriedsam mit ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Wirermahnen euch aber, liebe Bruder, vermahnet die Ungezogenen, trostet die Kleinmutigen, traget die Schwachen, seid geduldig gegen jedermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Sehet zu, daß niemand Boses mit Bosem jemand vergelte, sondern allezeit jaget dem Guten nach, beide, untereinander und gegen jedermann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Seid allezeit frohlich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Betet ohne Unterlafi!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Seid dankbar in alien Dingen; denn das ist der Wille Gottes in Christo Jesu an euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Den Geist dampfet nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Die Weissagung verachtet nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'prufet aber alles und das Gute behaltet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Meidet alien bosen Schein!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Er aber, der Gott des Friedens, heilige euch durch und durch, und euer Geist ganz samt der Seele und Leib müsse behalten werden unstraflich auf die Zukunft unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Getreu ist er, der euch rufet, welcher wird\'s auch tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Liebe Bruder, betet fur uns!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Grußet alle Bruder mit dem heiligen Kuß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Ich beschwore euch bei dem Herrn, daß ihr diesen Brief lesen lasset alien heiligen Brudern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Die Gnade unsers Herrn Jesu Christi sei mit euch! Amen. Der zweite Brief des Paulus an die Thessalonicher');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus und Silvanus und Timotheus: Der Gemeinde zu Thessalonich in Gott, unserm Vater, und dem Herm Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Herm Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Wir sollen Gott danken allezeit um euch, liebe Bruder, wie es billig ist. Denn euer Glaube wachset sehr, und die Liebe eines jeglichen unter euch alien nimmt zu gegeneinander,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'also daß wir uns euer ruhmen unter den Gemeinden Gottes von eurer Geduld und Glauben in alien euren Verfolqunqen und Trubsalen, die ihr duldet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'welches anzeiget, daß Gott recht richten wird, und ihr wurdig werdet zum Reich Gottes, uber welchem ihr auch leidet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'nachdem es recht ist bei Gott, zu vergelten Trubsal denen, die euch Trubsal anlegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'euch aber, die ihr Trubsal leidet, Ruhe mit uns, wenn nun der Herr Jesus wird offenbart werden vom Himmel samt den Engeln seiner Kraft');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'und mit Feuerflammen, Rache zu geben uber die, so Gott nicht erkennen, und uber die, so nicht gehorsam sind dem Evangelium unsers Herm Jesu Christi;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'welche werden Pein leiden, das ewige Verderben, von dem Angesichte des Herm und von seiner herrlichen Macht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'wenn er kommen wird, daß er herrlich erscheine mit seinen Heiligen und wunderbar mit alien Glaubigen. Denn unser Zeugnis an euch von demselbigen Tage habt ihrgeglaubet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Und derhalben beten wir auch allezeit fur euch, daß unser Gott euch wurdig mache der Berufung und erfulle alles Wohlgefallen der Güte und das Werk des Glaubens in der Kraft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'auf daß an euch gepreiset werde der Name unsers Herm Jesu Christi und ihr an ihm nach der Gnade unsers Gottes und des Herm Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Aber der Zukunft halben unseres Herm Jesu Christi und unserer Versammlung zu ihm bitten wir euch, liebe Bruder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'daß ihr euch nicht bald bewegen lasset von eurem Sinn noch erschrecken, weder durch Geist noch durch Wort noch durch Briefe, als von uns gesandt, daß der Tag Christi vorhanden sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Lasset euch niemand verfuhren in keinerlei Weise! Denn er kommt nicht, es sei denn, daß zuvor der Abfall komme, und offenbaret werde der Mensch der Sunde und das Kind des Verderbens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'der da ist ein Widerwartiger und sich uberhebet uber alles, was Gott Oder Gottesdienst heiftet, also daß er sich setzt in den Tempel Gottes als ein Gott und gibt sich vor, er sei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Gedenket ihr nicht daran, daß ich euch solches sagte, da ich noch bei euch war?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Und was es noch aufhalt, wisset ihr, daß er offenbaret werde zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Denn es reget sich schon bereits die Bosheit heimlich, ohne daß, der es jetzt aufhalt, muft hinweggetan werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Und alsdann wird der Boshaftige offenbaret werden, welchen der Herr umbringen wird mit dem Geist seines Mundes, und wird sein ein Ende machen durch die Erscheinung seiner Zukunft,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'des, welches Zukunft geschieht nach der Wirkung des Satans mit allerlei lugenhaftigen Kraften und Zeichen und Wundern');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'und mit allerlei Verfuhrung zur Ungerechtigkeit unter denen, die verloren werden, dafur, daß sie die Liebe zur Wahrheit nicht haben angenommen, daß sie selig würden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Darum wird ihnen Gott kraftige Irrtumer senden, daß sie glauben der Luge,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'auf daß gerichtet werden alle, die der Wahrheit nicht glauben, sondern haben Lust an der Ungerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Wir aber sollen Gott danken allezeit um euch, geliebte Bruder von dem Herm, daß euch Gott erwahlet hat von Anfang zur Seligkeit in der Heiligung des Geistes und im Glauben der Wahrheit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'darein ereuch berufen hat durch unser Evangelium zum herrlichen Eigentum unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'So stehet nun, liebe Bruder, und haltet an den Satzungen, die ihr gelehret seid, es sei durch unser Wort Oder Brief.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Eraber, unser Herr Jesus Christus, und Gott und unser Vater, der uns hat geliebet und gegeben einen ewigen Trost und eine gute Hoffnung durch Gnade,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'der ermahne eure Herzen und starke euch in allerlei Lehre und gutem Werk!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Weiter, liebe Bruder, betet fur uns, daß das Wort des Herrn laufe und gepreiset werde wie bei euch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'und daß wir erloset werden von den unartigen und argen Menschen. Denn der Glaube ist nicht jedermanns Ding.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Aber der Herr ist treu; der wird euch starken und bewahren vor dem Argen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Wirversehen uns aberzu euch in dem Herrn, daß ihr tut und tun werdet, was wir euch gebieten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Der Herr aber richte eure Herzen zu der Liebe Gottes und zu der Geduld Christi!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Wir gebieten euch aber, liebe Bruder, in dem Namen unsers Herrn Jesu Christi, daß ihr euch entziehet von jedem Bruder, der da unordentlich wandelt und nicht nach der Satzung, die er von uns empfangen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Denn ihrwisset, wie ihr uns sollt nachfolgen. Denn wir sind nicht unordentlich unter euch gewesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'haben auch nicht umsonst das Brot genommen von jemand, sondern mit Arbeit und Muhe Tag und Nacht haben wir gewirket, daß wir nicht jemand unter euch beschwerlich waren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'nicht darum, daß wir des nicht Macht haben, sondern daß wir uns selbst zum Vorbilde euch geben, uns nachzufolgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Und da wir bei euch waren, geboten wir euch solches, daß, so jemand nicht will arbeiten, der soil auch nicht essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Denn wir horen, daß etliche unter euch wandeln unordentlich und arbeiten nichts, sondern treiben Vorwitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Solchen aber gebieten wir und ermahnen sie durch unsern Herrn Jesum Christum, daß sie mit stillem Wesen arbeiten und ihr eigen Brot essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Ihr aber, liebe Bruder, werdet nicht verdrossen, Gutes zu tun!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'So aber jemand nicht gehorsam ist unserm Wort, den zeichnet an durch einen Brief und habt nichts mit ihm zu schaffen, auf daß er schamrot werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Doch haltet ihn nicht als einen Feind, sondern vermahnet ihn als einen Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Er aber, der Herr des Friedens, gebe euch Frieden allenthalben und auf allerlei Weise. Der Herr sei mit euch alien!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Der Gruli mit meiner, des Paulus, Hand. Das ist das Zeichen in alien Briefen; also schreibe ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Die Gnade unsers Herrn Jesu Christi sei mit euch alien! Amen. Der erste Brief des Paulus an Timotheus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, ein Apostel Jesu Christi, nach dem Befehl Gottes, unsers Heilandes, und des Herrn Jesu Christi, der unsere Hoffnung ist:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timotheus, meinem rechtschaffenen Sohn im Glauben. Gnade, Barmherzigkeit, Friede von Gott, unserm Vater, und unserm Herrn Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Wie ich dich ermahnet habe, daß du zu Ephesus bliebest, da ich nach Mazedonien zog, und gebotest etlichen, daß sie nicht anders lehreten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'auch nicht achthatten auf die Fabeln und der Geschlechtsregister, die kein Ende haben, und bringen Fragen auf, mehr denn Besserung zu Gott im Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Denn die Hauptsumme des Gebots ist Liebe von reinem Herzen und von gutem Gewissen und von ungefarbtem Glauben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'welcher haben etliche gefehlet und sind umgewandt zu unnutzem Geschwatz,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'wollen der Schrift Meister sein und verstehen nicht, was sie sagen, Oder was sie setzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Wirwissen aber, daß das Gesetz gut ist, so sein jemand recht brauchet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'und weili solches, daß dem Gerechten kein Gesetz gegeben ist, sondern den Ungerechten und Ungehorsamen, den Gottlosen und Sundern, den Unheiligen und Ungeistlichen, den Vatermordern und Muttermordern, den Totschlagern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'den Hurern, den Knabenschandern, den Menschendieben, den Lugnern, den Meineidigen, und so etwas mehr der heilsamen Lehre wider ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'nach dem herrlichen Evangelium des seligen Gottes, welches mir vertrauet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Und ich danke unserm Herrn Christo Jesu, der mich stark gemacht und treu geachtet hat und gesetzt in das Amt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'der ich zuvorwar ein Lasterer und ein Verfolger und ein Schmaher. Aber mir ist Barmherzigkeit widerfahren; denn ich hab\'s unwissend getan, im Unglauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Es ist aber desto reicher gewesen die Gnade unsers Herrn samt dem Glauben und der Liebe, die in Christo Jesu ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Denn das istjegewililich wahr und ein teuer wertes Wort, daß Christus Jesus kommen ist in die Welt, die Sunder selig zu machen, unter welchen ich der vornehmste bin.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Aber darum ist mir Barmherzigkeit widerfahren, auf daß an mir vornehmlich Jesus Christus erzeigete alle Geduld zum Exempel denen, die an ihn glauben sollten zum ewigen Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Aber Gott, dem ewigen Konige, dem Unverganglichen und Unsichtbaren und allein Weisen, sei Ehre und Preis in Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Dies Gebot befehle ich dir, mein Sohn Timotheus, nach den vorigen Weissagungen fiber dir, daß du in denselbigen eine gute Ritterschaft ubest');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'und habest den Glauben und gut Gewissen, welches etliche von sich gestoften und am Glauben Schiffbruch erlitten haben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'unter welchen ist Hymenaus und Alexander, welche ich habe dem Satan ubergeben, daß sie gezuchtiget werden, nicht mehr zu lastern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'So ermahne ich nun, daß man vor alien Dingen zuerst tue Bitte, Gebet, Furbitte und Danksagung fur alle Menschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'fur die Konige und fur alle Obrigkeit, auf daß wir ein ruhig und stilles Leben fuhren mogen in aller Gottseligkeit und Ehrbarkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Denn solches ist gut, dazu auch angenehm vor Gott, unserm Heilande,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'welcher will, daß alien Menschen geholfen werde, und zur Erkenntnis der Wahrheit kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Denn es ist ein Gott und ein Mittler zwischen Gott und den Menschen, namlich der Mensch Christus Jesus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'der sich selbst gegeben hat fur alle zur Erlosung, daß solches zu seiner Zeit geprediget würde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'dazu ich gesetzt bin ein Prediger und Apostel (ich sage die Wahrheit in Christo und luge nicht), ein Lehrer der Heiden im Glauben und in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'So will ich nun, daß die Manner beten an alien Orten und aufheben heilige Hande, ohne Zorn und Zweifel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Desselbigengleichen die Weiber, daß sie in zierlichem Kleide mit Scham und Zucht sich schmucken, nicht mit Zopfen Oder Gold Oder Perlen Oder kostlichem Gewand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'sondern wie sich\'s ziemet den Weibern, die da Gottseligkeit beweisen durch gute Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Ein Weib lerne in der Stille mit aller Untertanigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Einem Weibe aber gestatte ich nicht, daß sie lehre, auch nicht, daß sie des Mannes Herr sei, sondern stille sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Denn Adam ist am ersten gemacht, danach Eva.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Und Adam ward nicht verfuhret; das Weib aber ward verfuhret und hat die Ubertretung eingefuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Sie wird aber selig werden durch Kinderzeugen, so sie bleiben im Glauben und in der Liebe und in der Heiligung samt der Zucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Das ist je gewililich wahr, so jemand ein Bischofsamt begehret, der begehret ein kostlich Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Es soil aber ein Bischof unstraflich sein, eines Weibes Mann, nüchtem, malüg, sittig, gastfrei, lehrhaftig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'nicht ein Weinsaufer, nicht pochen, nicht unehrliche Hantierung treiben, sondern gelinde, nicht haderhaftig, nicht geizig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'der seinem eigenen Hause wohl vorstehe, der gehorsame Kinder habe mit aller Ehrbarkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(so aber jemand seinem eigenen Hause nicht weili vorzustehen, wie wird er die Gemeinde Gottes versorgen?),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'nicht ein Neuling, auf daß er sich nicht aufblase und dem Lasterer ins Urteil falle.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Er muli aber auch ein gut Zeugnis haben von denen, die draulien sind, auf daß er nicht faile dem Lasterer in die Schmach und Strick.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Desselbigengleichen die Diener sollen ehrbar sein, nicht zweizungig, nicht Weinsaufer, nicht unehrliche Hantierung treiben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'die das Geheimnis des Glaubens in reinem Gewissen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Und dieselbigen lasse man zuvor versuchen; danach lasse man sie dienen, wenn sie unstraflich sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Desselbigengleichen ihre Weiber sollen ehrbar sein, nicht Lasterinnen, nuchtern, treu in alien Dingen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Die Diener laft einen jeglichen sein eines Weibes Mann, die ihren Kindern wohl vorstehen und ihren eigenen Hausern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Welche aber wohl dienen, die erwerben sich selbst eine gute Stufe und eine grofte Freudigkeit im Glauben in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Solches schreibe ich dir und hoffe, aufs schierste zu dirzu kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'So ich aberverzoge, daß du wissest, wie du wandeln sollst in dem Hause Gottes, welches ist die Gemeinde des lebendigen Gottes, ein Pfeiler und Grundfeste der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Und kundlich graft ist das gottselige Geheimnis: Gott ist offenbaret im Fleisch, gerechtfertiget im Geist, erschienen den Engeln, geprediget den Heiden, geglaubet von der Welt, aufgenommen in die Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Der Geist aber sagt deutlich, daß in den letzten Zeiten werden etliche von dem Glauben abtreten und anhangen den verfuhrerischen Geistern und Lehren der Teufel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'durch die, so in Gleisnerei Lugenredner sind und Brandmal in ihrem Gewissen haben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'und verbieten, ehelich zu werden und zu meiden die Speisen, die Gott geschaffen hat, zu nehmen mit Danksagung, den Glaubigen und denen, die die Wahrheit erkennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Denn alle Kreatur Gottes ist gut und nichts verwerflich, was mit Danksagung empfangen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Denn es wird geheiliget durch das Wort Gottes und Gebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Wenn du den Brudern solches vorhaltst, so wirst du ein guter Diener Jesu Christi sein, auferzogen in den Worten des Glaubens und der guten Lehre, bei welcher du immerdar gewesen bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Der ungeistlichen aber und altvettelischen Fabeln entschlage dich. Ube dich selbst aber an der Gottseligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Denn die leibliche Obung istwenig nutz; aber die Gottseligkeit ist zu alien Dingen nutz und hat die Verheiftung dieses und des zukunftigen Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Das ist je aewiftlich wahr und ein teuer wertes Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Denn dahin arbeiten wir auch und werden geschmahet, daß wir auf den lebendigen Gott gehoffet haben, welcher ist der Heiland aller Menschen, sonderlich aber der Glaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Solches gebiete und lehre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Niemand verachte deine Jugend, sondern sei ein Vorbild den Glaubigen im Wort, im Wandel, in der Liebe, im Geist, im Glauben, in der Keuschheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Halt an mit Lesen, mit Ermahnen, mit Lehren, bis ich komme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Lafi nichtaus der Acht die Gabe, die dir gegeben ist durch die Weissagung mit Handauflegung der Altesten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Solches warte, damit gehe urn auf dati dein Zunehmen in alien Dingen offenbar sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Hab acht auf dich selbst und auf die Lehre; beharre in diesen Stricken! Denn wo du solches tust, wirst du dich selbst selig machen, und die dich horen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Einen Alten schilt nicht, sondern ermahne ihn als einen Vater, die Jungen als die Bruder,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'die alten Weiber als die Mutter, die jungen als die Schwestern mit aller Keuschheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Ehre die Witwen, welche rechte Witwen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'So aber eine Witwe Kinder Oder Neffen hat, solche laft zuvor lernen ihre eigenen Hauser gbttlich regieren und den Eltern Gleiches vergelten; denn das ist wohl getan und angenehm vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Das ist aber eine rechte Witwe, die einsam ist, die ihre Hoffnung auf Gott stellet und bleibet am Gebet und Flehen Tag und Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Welche aber in Wollusten lebet, die ist lebendig tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Solches gebiete, auf daß sie untadelig seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'So aber jemand die Seinen, sonderlich seine Hausgenossen, nicht versorget, der hat den Glauben verleugnet und ist arger denn ein Heide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Lafi keine Witwe erwahlet werden unter sechzig Jahren, und die da gewesen sei eines Mannes Weib,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'und die ein Zeugnis habe guter Werke, so sie Kinder aufgezogen hat, so sie gastfrei gewesen ist, so sie der Heiligen Füfte gewaschen hat, so sie den Trubseligen Handreichung getan hat, so sie allem guten Werk nachkommen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Der jungen Witwen aber entschlage dich; denn wenn sie geil worden sind wider Christum, so wollen sie freien');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'und haben ihr Urteil, daß sie den ersten Glauben gebrochen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Daneben sind sie faul und lernen umlaufen durch die Hauser; nicht allein aber sind sie faul, sondern auch schwatzig und vorwitzig und reden, was nicht sein soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'So will ich nun, daß die jungen Witwen freien, Kinder zeugen, haushalten, dem Widersacher keine Ursache geben zu schelten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Denn es sind schon etliche umgewandt dem Satan nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'So aber ein Glaubiger Oder Glaubigin Witwen hat, der versorge dieselbigen und lasse die Gemeinde nicht beschweret werden, auf daß die, so rechte Witwen sind, mogen genug haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Die Altesten, die wohl vorstehen, die halte man zwiefacher Ehre wert, sonderlich die da arbeiten im Wort und in der Lehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Denn es spricht die Schrift: Du sollst nicht dem Ochsen das Maul verbinden, der da drischt, und: Ein Arbeiter ist seines Lohnes wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Wider einen Altesten nimm keine Klage auf aufter zweien Oder dreien Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Die da sundigen, die strafe vor alien, auf daß sich auch die andern furchten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ich bezeuge vor Gott und dem Herrn Jesu Christo und den auserwahlten Engeln, daß du solches haltest ohne eigen Gutdunken und nichts tuest nach Gunst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Die Hande lege niemand baid auf; mache dich auch nicht teilhaftig fremder Sünden. Halte dich selber keusch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'T rinke nicht mehr Wasser, sondern brauche ein wenig Wein urn deines Magens willen, und daß du oft krank bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Etlicher Menschen Sunden sind offenbar, daß man sie vorhin richten kann; etlicher aber werden hernach offenbar.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Desselbigengleichen auch etlicher gute Werkes sind zuvor offenbar; und die andern bleiben auch nicht verborgen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Die Knechte, so unter dem Joch sind, sollen ihre Herren aller Ehren wert halten, auf daß nicht der Name Gottes und die Lehre verlastert werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Welche aber glaubige Herren haben, sollen dieselbigen nicht verachten (mit dem Schein), daß sie Bruder sind, sondern sollen vielmehr dienstbar sein, dieweil sie glaubig und geliebt und der Wohltat teilhaftig sind. Solches lehre und ermahne!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'So jemand anders lehret und bleibet nicht bei den heilsamen Worten unsers Herrn Jesu Christi und bei der Lehre von der Gottseligkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'der ist verdustert und weift nichts, sondern ist seuchtig in Fragen und Wortkriegen, aus welchen entspringet Neid, Hader, Lasterung, boser Argwohn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Schulgezanke solcher Menschen, die zerruttete Sinne haben und der Wahrheit beraubt sind, die da meinen, Gottseligkeit sei ein Gewerbe. Tue dich von solchen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Es ist aber ein grolier Gewinn, wer gottselig ist und lasset sich genugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Denn wir haben nichts in die Welt gebracht, darum offenbar ist, wirwerden auch nichts hinausbringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Wenn wir aber Nahrung und Kleider haben, so lasset uns begnugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Denn die da reich werden wollen, die fallen in Versuchung und Stricke und viel torichter und schadlicher Lüste, welche versenken die Menschen ins Verderben und Verdammnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Denn Geiz ist eine Wurzel alles Ubels, welches hat etliche gelustet, und sind vom Glauben irregegangen und machen sich selbst viel Schmerzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Aber du, Gottesmensch, flieh solches! Jage aber nach der Gerechtigkeit, der Gottseligkeit, dem Glauben, der Liebe, der Geduld, der Sanftmut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kampfe den guten Kampf des Glaubens; ergreife das ewige Leben, dazu du auch berufen bist und bekannt hast ein gut Bekenntnis vor vielen Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Ich gebiete dir vor Gott, der alle Dinge lebendig macht, und vor Christo Jesu, der unter Pontius Pilatus bezeuget hat ein gut Bekenntnis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'daß du haltest das Gebot ohne Flecken, untadelig, bis auf die Erscheinung unsers Herm Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'welche wird zeigen zu seiner Zeit der Selige und allein Gewaltige, der Konig alter Konige, und Herr aller Herren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'der allein Unsterblichkeit hat; der da wohnet in einem Licht, da niemand zukommen kann; welchen kein Mensch gesehen hat noch sehen kann: dem sei Ehre und ewiges Reich! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Den Reichen von dieser Welt gebeut, daß sie nicht stolz seien, auch nicht hoffen auf den ungewissen Reichtum, sondern auf den lebendigen Gott, der uns dar gibt reichlich, allerlei zu genielien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'daß sie Gutes tun, reich werden an guten Werken, gerne geben, behilflich seien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Schatze sammeln, sich selbst einen guten Grund aufs Zukunftige, daß sie ergreifen das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, '0 Timotheus, bewahre, was dir vertrauet ist, und meide die ungeistlichen losen Geschwatze und das Gezanke der falschberuhmten Kunst,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'welche etliche vorgeben und fehlen des Glaubens. Die Gnade sei mir dir! Amen. Der zweite Brief des Paulus an Timotheus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes nach der Verheüiung des Lebens in Christo Jesu:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Meinem lieben Sohn Timotheus Gnade, Barmherzigkeit, Friede von Gott dem Vater und Christo Jesu, unserm Herm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Ich danke Gott dem ich diene von meinen Voreltern her in reinem Gewissen, daß ich ohne Unterlali dein gedenke in meinem Gebet Tag und Nacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Und mich verlanget, dich zu sehen, wenn ich denke an deine Tranen, auf daß ich mit Freuden erfullet werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Und erinnere mich des ungefarbten Glaubens in dir, welcher zuvor gewohnet hat in deiner Grolimutter Lois und in deiner Mutter Eunike, bin abergewili, daß auch in dir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Urn welcher Sache willen ich dich erinnere, daß du erweckest die Gabe Gottes, die in dir ist durch die Auflegung meiner Hande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Denn Gott hat uns nicht gegeben den Geist der Furcht, sondern der Kraft und der Liebe und der Zucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Darum so schame dich nicht des Zeugnisses unsers Herm noch meiner, der ich sein Gebundener bin, sondern leide dich mit dem Evangelium wie ich nach der Kraft Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'der uns hat selig gemacht und berufen mit einem heiligen Ruf, nicht nach unsern Werken, sondern nach seinem Vorsatz und Gnade, die uns gegeben ist in Christo Jesu vor der Zeit der Welt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'jetzt aber offenbart durch die Erscheinung unsers Heilandes Jesu Christi, der dem Tode die Macht hat genommen und das Leben und ein unverganglich Wesen ans Licht gebracht durch das Evangelium,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'zuwelchem ich gesetzt bin ein Predigerund Apostel und Lehrerder Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Urn welcher Sache willen ich solches leide, aber ich schame mich\'s nicht; denn ich weili, an wen ich glaube, und bin gewili, daß er kann mir meine Beilage bewahren bis an jenen Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Halt an dem Vorbilde der heilsamen Worte, die du von mir gehort hast, vom Glauben und von der Liebe in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Diese gute Beilage bewahre durch den Heiligen Geist, der in uns wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Das weilit du, daß sich gewendet haben von mir aüe, die in Asien sind, unter welchen ist Phygellus und Hermogenes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Der Herr gebe Barmherzigkeit dem Hause Onesiphorus; denn er hat mich oft erquicket und hat sich meiner Ketten nicht geschamet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'sondern da er zu Rom war, suchte er mich aufs fleißigste und fand mich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Der Herr gebe ihm, daß erfinde Barmherzigkeit bei dem Herrn an jenem T age! Und wieviel er mir zu Ephesus gedienet hat, weifit du am besten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'So sei nun stark, mein Sohn, durch die Gnade in Christo Jesu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Und was du von mir gehoret hast durch viel Zeugen, das befiehl treuen Menschen, die da tuchtig sind, auch andere zu lehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Leide dich als ein guter Streiter Jesu Christi!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Kein Kriegsmann flicht sich in Handel der Nahrung, auf daß er gefalle dem, der ihn angenommen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Und sojemand auch kampfet, wird erdoch nicht gekronet, er kampfe denn recht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Es soli aber der Ackermann, der den Acker bauet, der Fruchte am ersten genießen. Merke, was ich sage!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Der Herr aber wird dir in alien Dingen Verstand geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Halt im Gedachtnis Jesum Christum, der auferstanden ist von den Toten, aus dem Samen Davids, nach meinem Evangelium,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'uber welchem ich leide bis an die Bande als ein Gbeltater. Aber Gottes Wort ist nicht gebunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Darum dulde ich alles um der Auserwahlten willen, auf daß auch sie die Seligkeit erlangen in Christo Jesu mit ewiger Herrlichkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Das ist je gewißlich wahr: Sterben wir mit, so werden wir mitleben;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'dulden wir, so werden wir mitherrschen; verleugnen wir, so wird er uns auch verleugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Glauben wir nicht, so bleibet er treu; er kann sich selbst nicht leugnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Solches erinnere sie und bezeuge vordem Herrn, daß sie nicht um Worte zanken, welches nichts nütze ist, denn zu verkehren, die da zuhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Befleilüge dich, Gott zu erzeigen einen rechtschaffenen, unstraflichen Arbeiter, der da recht teile das Wort der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Des ungeistlichen; losen Geschwatzes entschlage dich; denn es hilft viel zum ungottlichen Wesen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Und ihr Wort frifit um sich wie der Krebs, unter welchen ist Hymenaus und Philetus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'welche der Wahrheit gefehlet haben und sagen, die Auferstehung sei schon geschehen, und haben etlicher Glauben verkehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Aber der feste Grund Gottes bestehet und hat dieses Siegel: Der Herr kennet die Seinen, und: Es trete ab von Ungerechtigkeit, wer den Namen Christi nennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'In einem grolien Hause aber sind nicht allein guldene und silberne Gefalie, sondern auch holzerne und irdene und etliche zu Ehren, etliche aberzu Unehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'So nun jemand sich reiniget von solchen Leuten, der wird ein geheiliget Fali sein zu Ehren, dem Hausherrn brauchlich und zu allem guten Werk bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Flieh die Luste der Jugend! Jage aber nach der Gerechtigkeit, dem Glauben, der Liebe, dem Frieden mit alien, die den Herrn anrufen von reinem Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Aber der torichten und unnützen Fragen entschlage dich; denn du weißt, daß sie nur Zank gebaren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Ein Knecht aber des Herrn soil nicht zankisch sein, sondern freundlich gegen jedermann, lehrhaftig, der die Bosen tragen kann mit Sanftmut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'und strafe die Widerspenstigen, ob ihnen Gott dermaleinst Buße gabe die Wahrheit zu erkennen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'und wieder nuchtern wurden aus des Teufels Strick, von dem sie gefangen sind zu seinem Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Das sollst du aber wissen, daß in den letzten Tagen werden greuliche Zeiten kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Denn es werden Menschen sein, die von sich selbst halten, geizig, ruhmredig, hoffartig, Lasterer, den Eltern ungehorsam, undankbar, ungeistlich,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'storrig, unversohnlich, Schander, unkeusch, wild, ungutig,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Verrater, Frevler, aufgeblasen, die mehr lieben Wollust denn Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'die da haben den Schein eines gottseligen Wesens, aber seine Kraft verleugnen sie. Und solche meide!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Aus denselbigen sind, die hin und her in die Hauser schleichen und führen die Weiblein gefangen, die mit Sünden beladen sind und mit mancherlei Lusten fahren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'lernen immerdar und konnen nimmerzur Erkenntnis der Wahrheit kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Gleicherweise aber, wie Jannes und Jambres dem Mose widerstunden, also widerstehen auch diese der Wahrheit; es sind Menschen von zerrutteten Sinnen, untuchtig zum Glauben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Aber sie werden\'s die Lange nicht treiben; denn ihre Torheit wird offenbar werden jedermann, gleichwie auch jener war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Du aber hast erfahren meine Lehre, meine Weise, meine Meinung, meinen Glauben, meine Langmut, meine Liebe, meine Geduld,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'meine Verfolgung, meine Leiden, welche mir widerfahren sind zu Antiochien, zu Ikonien, zu Lystra, welche Verfolgung ich da ertrug: und aus alien hat mich der Herr erloset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Und alle, die gottselig leben wollen in Christo Jesu, müssen Verfolgung leiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mit den bosen Menschen aber und verfuhrerischen wird\'s je langer, je arger, verfuhren und werden verfuhret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Du aber bleibe in dem, was du gelernet hast und dir vertrauet ist, sintemal du weilit, von wem du gelernet hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Und weil du von Kind auf die Heilige Schrift weilit, kann dich dieselbige unterweisen zurßeligkeit durch den Glauben an Christum Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Denn alle Schrift, von Gott eingegeben, ist nutze zur Lehre, zur Strafe, zur Besserung, zur Zuchtigung in der Gerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'daß ein Mensch Gottes sei vollkommen, zu allem guten Werk geschickt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'So bezeuge ich nun vor Gott und dem Herm Jesu Christo, der da zukünftig ist, zu richten die Lebendigen und die Toten, mit seiner Erscheinung und mit seinem Reich:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Predige das Wort; halt an, es sei zu rechter Zeit Oder zur Unzeit; strafe, draue, ermahne mit aller Geduld und Lehre!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Denn es wird eine Zeit sein, da sie die heilsame Lehre nicht leiden werden, sondern nach ihren eigenen Lüsten werden sie sich selbst Lehrer aufladen, nach dem ihnen die Ohren jucken;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'und werden die Ohren von der Wahrheit wenden und sich zu den Fabeln kehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Du aber sei nuchtern allenthalben. Leide dich, tu das Werk eines evangelischen Predigers, richte dein Amt redlich aus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Denn ich werde schon geopfert, und die Zeit meines Abscheidens ist vorhanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Ich habe einen guten Kampf gekampfet; ich habe den Lauf vollendet; ich habe Glauben gehalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Hinfort ist mir beigelegt die Krone der Gerechtigkeit, welche mir der Herr an jenem Tage, der gerechte Richter, geben wird, nicht mir aber allein, sondern auch alien, die seine Erscheinung liebhaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Fleilüge dich, daß du bald zu mir kommest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Denn Demas hat mich verlassen und diese Welt liebgewonnen und ist gen Thessalonich gezogen, Krescens nach Galatien, Titus nach Dalmatien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukas ist allein bei mir. Markus nimm zu dir und bringe ihn mit dir; denn er ist mir nutzlich zum Dienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychikus habe ich gen Ephesus gesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Den Mantel, den ich zu Troas lieli bei Karpo, bringe mit, wenn du kommst und die Bucher, sonderlich aber das Pergament.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander, der Schmied hat mirviel Boses beweiset; der Herr bezahle ihm nach seinen Werken!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Vorwelchem hüte du dich auch; denn erhat unsern Worten sehrwiderstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'In meiner ersten Verantwortung stund niemand bei mir, sondern sie verlielien mich alle. Es sei ihnen nicht zugerechnet!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Der Herr aber stund mir bei und starkte mich, auf daß durch mich die Predigt bestatiget wurde, und alle Heiden horeten. Und ich bin erloset von des Lowen Rachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Der Herr aber wird mich erlosen von allem Ubel und aushelfen zu seinem himmlischen Reich; welchem sei Ehre von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Grülie Priska und Aquila und das Haus Onesiphorus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blieb zu Korinth; Trophimus aber lieli ich zu Milet krank.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Tu Fleili, daß du vor dem Winter kommest. Es gruliet dich Eubulus und Pudens und Linus und Klaudia und alle Bruder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Der Herr Jesus Christus sei mit deinem Geiste! Die Gnade sei mit euch! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, ein Knecht Gottes, aber ein Apostel Jesu Christi nach dem Glauben der Auserwahlten Gottes und der Erkenntnis der Wahrheit zur Gottseligkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'auf Hoffnung des ewigen Lebens, welches verheiften hat, der nicht luget, Gott, vor den Zeiten der Welt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'hat aber offenbaret zu seiner Zeit sein Wort durch die Predigt, die mir vertrauet ist nach dem Befehl Gottes, unsers Heilandes:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titus, meinem rechtschaffenen Sohn, nach unser beider Glauben: Gnade, Barmherzigkeit, Friede von Gott dem Vater und dem Herrn Jesu Christo, unserm Heilande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Derhalben lieft ich dich in Kreta, dafi du solltest vollends anrichten, da ich\'s gelassen habe und besetzen die Stadte hin und her mit Altesten, wie ich dir befohlen habe;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'wo einer ist untadelig, eines Weibes Mann, der glaubige Kinder habe, nicht beruchtiget, daß sie Schwelger und ungehorsam sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Denn ein Bischof soil untadelig sein, als ein Haushalter Gottes, nicht eigensinnig, nicht zornig, nicht ein Weinsaufer, nicht pochen, nicht unehrliche Hantierung treiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'sondern gastfrei, gutig, zuchtig, gerecht, heilig, keusch');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'und halte ob dem Wort, das gewift ist und lehren kann, auf daß er machtig sei, zu ermahnen durch die heilsame Lehre und zu strafen die Widersprecher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Denn es sind viele freche und unnutze Schwatzer und Verführer, sonderlich die aus der Beschneidung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'welchen man muft das Maul stopfen, die da ganze Hauser verkehren und lehren, was nicht taugt, urn schandliches Gewinns willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Es hat einer aus ihnen gesagt, ihreigener Prophet: Die Kreter sind immer Lugner, bose Tiere und faule Bauche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Dies Zeugnis ist wahr. Urn der Sache willen strafe sie scharf, auf daß sie gesund seien im Glauben');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'und nicht achten auf die judischen Fabeln und Menschengebote, welche sich von der Wahrheit abwenden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Den Reinen ist alles rein; den Unreinen aber und Unglaubigen ist nichts rein, sondern unrein ist beides, ihr Sinn und Gewissen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Sie sagen, sie erkennen Gott; aber mit den Werken verleugnen sie es, sintemal sie sind, an welchen Gott Greuel hat, und gehorchen nicht und sind zu allem guten Werk untuchtig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Du aber rede, wie sich\'s ziemet nach der heüsamen Lehre:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'den Alten, daß sie nuchtern seien, ehrbar, zuchtig, gesund im Glauben, in der Liebe, in der Geduld;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'den alten Weibern desselbigengleichen, daß sie sich stellen, wie den Heiligen ziemet, nicht Lasterinnen seien, nicht Weinsauferinnen, gute Lehrerinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'daß sie die jungen Weiber lehren zuchtig sein, ihre Manner lieben, Kinder lieben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'sittig sein, keusch, hauslich, gutig, ihren Mannern untertan, auf daß nicht das Wort Gottes verlastert werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Desselbigengleichen die jungen Manner ermahne, daß sie zuchtig seien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Allenthalben aber stelle dich selbst zum Vorbilde guter Werke mit unverfalschter Lehre, mit Ehrbarkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'mit heilsamem und untadeligem Wort, auf daß der Widerwartige sich schame und nichts habe, daß er von uns moge Boses sagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Den Knechten daß sie ihren Herren untertanig seien, in alien Dingen zu Gefallen tun, nicht widerbellen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'nicht veruntreuen, sondern alle gute Treue erzeigen, auf daß sie die Lehre Gottes, unsers Heilandes, zieren in alien Stricken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Denn es ist erschienen die heilsame Gnade Gottes alien Menschen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'und zuchtiget uns, daß wir sollen verleugnen das ungottliche Wesen und die weltlichen Luste und zuchtig, gerecht und gottselig leben in dieser Welt');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'und warten auf die selige Hoffnung und Erscheinung der Herrlichkeit des groften Gottes und unsers Heilandes Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'der sich selbst fur uns gegeben bat, auf daß er uns erlosete von aller Ungerechtigkeit und reinigte sich selbst ein Volk zum Eigentum, das fleiftig ware zu guten Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Solches rede und ermahne und strafe mit ganzem Ernst. Laft dich niemand verachten!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Erinnere sie, daß sie den Fursten und der Obrigkeit untertan und gehorsam seien, zu allem guten Werk bereit seien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'niemand lastern, nicht hadern, gelinde seien, alle Sanftmutigkeit beweisen gegen alle Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Denn wir waren auch weiland unweise, ungehorsam, irrig, dienend den Lusten und mancherlei Wollusten und wandelten in Bosheit und Neid und hasseten uns untereinander.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Da aber erschien die Freundlichkeit und Leutseligkeit Gottes, unsers Heilandes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'nicht urn der Werke willen der Gerechtigkeit, die wir getan hatten, sondern nach seiner Barmherzigkeit machte er uns selig durch das Bad der Wiedergeburt und Erneuerung des Heiligen Geistes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'welchen er.ausgegossen hat uber uns reichlich durch Jesum Christum, unsern Heiland,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'auf dafi wir durch desselbigen Gnade gerecht und Erben seien des ewigen Lebens nach der Hoffnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Das ist je gewifilich wahr. Solches will ich, dafi du test lehrest, auf daß die, so an Gott glaubig sind worden, in einem Stand guter Werke funden werden. Solches ist gut und nütze den Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Der torichten Fragen aber, der Geschlechtsregister, des Zankes und Streites uber dem Gesetz entschlage dich; denn sie sind unnütz und eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Einen ketzerischen Menschen meide, wenn er einmal und abermal ermahnet ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'und wisse, daß ein solcher verkehrt ist und sundiget, als der sich selbst verurteilet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Wenn ich zu dir senden werde Artemas Oder Tychikus, so komm eilend zu mirgen Nikopolis; denn daselbst habe ich beschlossen, den Winter zu bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenas, den Schriftgelehrten, und Apollos fertige ab mit Fleift, auf daß ihnen nichts gebreche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Laft aber auch die Unsern lernen, daß sie im Stand guter Werke sich finden lassen, wo man ihrer bedarf, auf daß sie nicht unfruchtbar seien:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Es gruften dich alle, die mit mirsind. Grufte alle, die uns lieben im Glauben. Die Gnade sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus, der Gebundene Christi Jesu, und Timotheus, der Bruder: Philemon, dem Lieben und unserm Gehilfen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'und Appia, der Lieben, und Archippus, unserm Streitgenossen, und der Gemeinde in deinem Flause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gnade sei mit euch und Friede von Gott, unserm Vater, und dem Flerrn Jesu Christo!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Ich danke meinem Gott und gedenke dein allezeit in meinem Gebet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'nachdem ich hore von der Liebe und dem Glauben, welchen du hast an den Flerrn Jesum und gegen alle Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'daß dein Glaube, den wir miteinander haben, in dir kraftig werde durch Erkenntnis alles des Guten, das ihr habt in Christo Jesu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Wir haben abergrofte Freude und Trostan deiner Liebe; denn die Herzen der Heiligen sind erquicket durch dich, lieber Bruder..');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Darum, wiewohl ich habe grofte Freudigkeit in Christo, dirzu gebieten, was dirziemet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'so will ich doch urn der Liebe willen nur vermahnen, der ich ein solcher bin, namlich ein alter Paulus, nun aber auch ein Gebundener Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'So ermahne ich dich urn meines Sohnes willen, Onesimus, den ich gezeuget habe in meinen Banden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'welcher weiland dir unnutze, nun aber dir und mirwohl nütze ist: den habe ich wiedergesandt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Du aberwollest ihn, das ist, mein eigen Herz, annehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Denn ich wollte ihn bei mir behalten, daß er mir an deiner Statt dienete in den Banden des Evangeliums;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'aber ohne deinen Willen wollte ich nichts tun, auf daß dein Gutes nicht ware genotiget, sondern freiwillig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Vielleicht aber ist er darum eine Zeitlang von dir kommen, daß du ihn ewig wieder hattest,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'nun nicht mehr als einen Knecht, sondern mehr denn einen Knecht, einen lieben Bruder, sonderlich mir; wie viel mehr aber dir, beide, nach dem Fleisch und in dem Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'So du nun mich haltst fur deinen Gesellen, so wollest du ihn als mich selbst annehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'So er aber dir etwas Schaden getan hat Oder schuldig ist, das rechne mirzu.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ich, Paulus, hab\' es geschrieben mitmeiner Hand; ich will\'s bezahlen. Ich schweige, daß du dich selbst mir schuldig bist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ja, lieber Bruder, gonne mir, daß ich mich an dir erqotze in dem Herrn; erquicke mein Herz in dem Herrn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ich hab\' aus Zuversicht deines Gehorsams dir geschrieben; denn ich weift, du wirst mehr tun, denn ich sage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Daneben bereite mir die Herberge; denn ich hoffe, daß ich durch euer Gebet euch geschenket werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Es gruliet dich Epaphras, mein Mitgefangener in Christo Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Markus, Aristarchus, Demas, Lukas, meine Gehilfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Die Gnade unsers Herrn Jesu Christi sei mit eurem Geist! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Nachdem vorzeiten Gott manchmal und mancherlei Weise geredet hat zu den Vatern durch die Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'hat er am letzten in diesen Tagen zu uns geredet durch den Sohn, welchen er gesetzt hat zum Erben uber alles, durch welchen er auch die Welt qemacht hat;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'welcher, sintemal er ist der Glanz seiner Herrlichkeit und das Ebenbild seines Wesens und tragt alle Dinge mit seinem kraftigen Wort und hat gemacht die Reinigung unserer Sünden durch sich selbst, hat er sich gesetzt zu der Rechten der Majestat in der Hohe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'so viel besser worden denn die Engel, so gar viel einen hohern Namen er vor ihnen ererbet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Denn zu welchem Engel haterjemals gesagt: Du bist mein Sohn, heute habe ich dich gezeuget? Und abermal: Ich werde sein Vater sein, und er wird mein Sohn sein?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Und abermal, da er einfuhret den Erstgeborenen in die Welt, spricht er: Und es sollen ihn alle Gottesengel anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Von den Engeln spricht er zwar: Er macht seine Engel Geister und seine Diener Feuerflammen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'aber von dem Sohn: Gott, dein Stuhl wahret von Ewigkeit zu Ewigkeit; das Zepter deines Reichs ist ein richtiges Zepter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du hast geliebet die Gerechtigkeit und gehasset die Ungerechtigkeit; darum hat dich, o Gott, gesalbet dein Gott mit dem Ole der Freuden uber deine Genossen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'und: Du, Herr, hast von Anfang die Erde gegrundet, und die Himmel sind deiner Hande Werk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Dieselbigen werden vergehen, du aberwirst bleiben; und sie werden alle veralten wie ein Kleid,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'und wie ein Gewand wirstdu sie wandeln, und sie werden sich verwandeln. Du aber bist derselbige, und deine Jahre werden nicht aufhoren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Zu welchem Engel aber haterjemals gesagt: Setze dich zu meiner Rechten, bis ich lege deine Feinde zum Schemel deiner Füße?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Sind sie nicht allzumal dienstbare Geister, ausgesandt zum Dienst urn derer willen, die ererben sollen die Seligkeit?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Darum sollen wir desto mehr wahrnehmen des Worts, das wir horen, daß wir nicht dahinfahren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Denn so das Wort test worden ist, das durch die Engel geredet ist, und eine jegliche Ubertretung und Ungehorsam hat empfangen seinen rechten Lohn:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'wie wollen wir entfliehen, so wir eine solche Seligkeit nicht achten? welche, nachdem sie erstlich geprediget ist durch den Herrn, ist sie auf uns kommen durch die, so es gehoret haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Und Gott hat ihr Zeugnis gegeben mit Zeichen, Wundern und mancherlei Kraften und mit Austeilung des Heiligen Geistes nach seinem Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Denn er hat nicht den Engeln untertan die zukunftige Welt, davon wir reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Es bezeuget aber einer an einem Ort und spricht: Was ist der Mensch, daß du sein gedenkest, und des Menschen Sohn, daß du ihn heimsuchest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Du hast ihn eine kleine Zeit der Engel mangeln lassen; mit Preis und Ehren hast du ihn gekronet und hast ihn gesetzt uber die Werke deiner Hande;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'alles hast du untertan zu seinen Fulien. In dem, daß er ihm alles hat untertan, hat er nichts gelassen, das ihm nicht untertan sei; jetzt aber sehen wir noch nicht, daß ihm alles untertan sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Den aber, der eine kleine Zeit der Engel gemangelt hat, sehen wir, daß es Jesus ist, durch Leiden des Todes gekronet mit Preis und Ehren, auf daß er von Gottes Gnaden fur alle den Tod schmeckete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Denn es ziemete dem, urn deswillen alle Dinge sind, und durch den alle Dinge sind, der da viel Kinder hat zur Herrlichkeit geführet, daß er den Herzog ihrer Seligkeit durch Leiden vollkommen machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Sintemal sie alle von einem kommen, beide, der da heiliget, und die da geheiliget werden. Darum schamet er sich auch nicht, sie Brüder zu heilien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'und spricht: Ich will verkundigen deinen Namen meinen Brudern und mitten in der Gemeinde dir Lob singen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Und abermal: Ich will mein Vertrauen auf ihn setzen. Und abermal: Siehe da, ich und die Kinder, welche mir Gott gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Nachdem nun die Kinder Fleisch und Blut haben, ist er\'s gleichermalien teilhaftig worden, auf daß er durch den Tod die Macht nahme dem, der des Todes Gewalt hatte, das ist, dem Teufel,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'und erlosete die, so durch Furcht des Todes im ganzen Leben Knechte sein muliten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Denn er nimmt nirgend die Engel an sich, sondern den Samen Abrahams nimmt er an sich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Daher mulite er allerdinge seinen Brudern gleich werden, auf daß er barmherzig würde und ein treuer Hoherpriester vor Gott, zu versohnen die Sünde des Volks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Denn darinnen ergelitten hat und versuchtist, kann er helfen denen, die versucht werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Derhalben, ihr heiligen Brüder, die ihr mit berufen seid durch die himmlische Berufung, nehmet wahr des Apostels und Hohenpriesters, den wir bekennen, Christi Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'der da treu ist dem, der ihn gemacht hat (wie auch Mose) in seinem ganzen Hause.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Dieser aber ist grolierer Ehre wert denn Mose, nachdem der eine groliere Ehre am Hause hat, der es bereitet, denn das Haus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Denn ein jeglich Haus wird von jemand bereitet; der aber alles bereitet, das ist Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Und Mose zwar war treu in seinem ganzen Hause als ein Knecht zum Zeugnis des, das gesagt sollte werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Christus aber als ein Sohn uber sein Haus; welches Haus sind wir, so wir anders das Vertrauen und den Ruhm der Hoffnung bis ans Ende test behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Darum, wie der Heilige Geist spricht: Heute, so ihr horen werdet seine Stimme,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'so verstocket eure Herzen nicht, als geschah in der Verbitterung, am Tage der Versuchung in der Wüste,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'da mich eure Vater versuchten; sie pruften mich und sahen meine Werke vierzig Jahre lang;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'darum ich entrustet ward uber dies Geschlecht und sprach: Immerdar irren sie mit dem Herzen, aber sie wuliten meine Wege nicht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'daß ich auch schwur in meinem Zorn, sie sollten zu meiner Ruhe nicht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Sehet zu, üebe Bruder, daß nicht jemand unter euch ein arges, unglaubiges Herz habe, das da abtrete von dem lebendigen Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'sondern ermahnet euch selbst alle Tage, solange es heute heilit, daß nicht jemand unter euch verstocket werde durch Betrug der Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Denn wir sind Christi teilhaftig worden, so wir anders das angefangene Wesen bis ans Ende fest behalten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'solange gesagt wird: Heute, so ihr seine Stimme horen werdet, so verstocket eure Herzen nicht, wie in der Verbitterung geschah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Denn etliche, da sie horeten, richteten eine Verbitterung an, aber nicht alle, die von Agypten ausgingen durch Mose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Uber welche aber ward er entrustet vierzig Jahre lang? Ist\'s nicht also, daß uber die, so da sundigten, deren Leiber in der Wüste verfielen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Welchen schwur er aber, daß sie nicht zu seiner Ruhe kommen sollten, denn den Unglaubigen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Und wir sehen, daß sie nicht haben konnen hineinkommen urn des Unglaubens willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'So lasset uns nun furchten, daß wir die Verheiliung, einzukommen zu seiner Ruhe, nicht versaumen, und unser keiner dahintenbleibe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Denn es ist uns auch verkundiget gleichwie jenen; aber das Wort der Predigt half jenen nichts, da nicht glaubeten die, so es horeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Denn wir, die wir glauben, gehen in die Ruhe, wie er spricht: Dali ich schwur in meinem Zorn, sie sollten zu meiner Ruhe nicht kommen. Und zwar, da die Werke von Anbeginn der Welt waren gemacht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'sprach er an einem Ort von dem siebenten Tage also: Und Gott ruhete am siebenten Tage von alien seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Und hier an diesem Ort abermal: Sie sollen nicht kommen zu meiner Ruhe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Nachdem es nun noch vorhanden ist, daß etliche sollen zu derselbigen kommen, und die, denen es zuerst verkündiget ist, sind nicht dazu kommen urn des Unglaubens willen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'bestimmte er abermal einen Tag nach solcher langen Zeit und sagte durch David: Heute, wie gesagt ist, heute, so ihr seine Stimme horen werdet, so verstocket eure Herzen nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Denn so Josua sie hatte zur Ruhe gebracht, würde er nicht hernach von einem andern Tage gesagt haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Darum ist noch eine Ruhe vorhanden dem Volk Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Denn werzu seiner Ruhe kommen ist, der ruhet auch von seinen Werken, gleich wie Gott von seinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'So lasset uns nun Fleili tun, einzukommen zu dieser Ruhe, auf daß nicht jemand falle in dasselbige Exempel des Unglaubens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Denn das Wort Gottes ist lebendig und kraftig und scharfer denn kein zweischneidig Schwert und durchdringet, bis daß es scheidet Seele und Geist, auch Mark und Bein, und ist ein Richter der Gedanken und Sinne des Herzens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Und ist keine Kreatur vor ihm unsichtbar; es ist aber alles bloft und entdeckt vor seinen Augen; von dem reden wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Dieweil wir denn einen groften Hohenpriester haben, Jesum, den Sohn Gottes, der gen Himmel gefahren ist, so lasset uns halten an dem Bekenntnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Denn wir haben nicht einen Hohenpriester, der nicht konnte Mitleid haben mit unserer Schwachheit, sondern der versucht ist allenthalben gleich wie wir, doch ohne Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Darum lasset uns hinzutreten mit Freudigkeit zu dem Gnadenstuhl, auf daß wir Barmherzigkeit empfangen und Gnade finden auf die Zeit, wenn uns Hilfe not seinwird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Denn ein jeglicher Hoherpriester, der aus den Menschen genommen wird, der wird gesetzt fur die Menschen gegen Gott, auf daß eropfere Gaben und Opfer fur die Sünden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'der da konnte mitleiden uber die, so unwissend sind und irren, nachdem er auch selbst umgeben ist mit Schwachheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Darum muft er auch, gleichwie fur das Volk, also auch fur sich selbst opfern fur die Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Und niemand nimmt sich selbst die Ehre, sondern der auch berufen sei von Gott gleichwie Aaron.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Also auch Christus hat sich nicht selbst in die Ehre gesetzt, daß er Hoherpriester würde, sondern der zu ihm gesagt hat: Du bist mein Sohn; heute habe ich dich gezeuget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Wie er auch am andern Ort spricht: Du bist ein Priester in Ewigkeit nach der Ordnung Melchisedeks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Und er hat in den Tagen seines Fleisches Gebet und Flehen mit starkem Geschrei und Tranen geopfert zu dem, der ihm von dem Tode konnte aushelfen; und ist auch erhoret, darum daß er Gott in Ehren hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Und wiewohl er Gottes Sohn war, hat er doch an dem, was er litt, Gehorsam gelernet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Und da er ist vollendet, ist er worden alien, die ihm gehorsam sind, eine Ursache zur ewigen Seligkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'genannt von Gott ein Hoherpriester nach der Ordnung Melchisedeks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Davon hatten wir wohl viel zu reden; aber es ist schwer, weil ihr so unverstandig seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Und die ihr solltet langst Meister sein, bedurfet ihrwiederum, daß man euch die ersten Buchstaben der gottlichen Worte lehre, und daß man euch Milch gebe und nicht starke Speise.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Denn wem man noch Milch geben muft, der ist unerfahren in dem Wort der Gerechtigkeit; denn er ist ein junges Kind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Den Vollkommenen aber gehort starke Speise, die durch Gewohnheit haben geubte Sinne zum Unterschied des Guten und des Bosen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Darum wollen wir die Lehre vom Anfang christliches Lebens jetzt lassen und zur Vollkommenheit fahren, nicht abermal Grund legen von Bufte der toten Werke, vom Glauben an Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'von der Taufe, von der Lehre, vom Handeauflegen, von der Toten Auferstehung und vom ewigen Gerichte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Und das wollen wir tun, so es Gott anders zulasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Denn es ist unmdglich, daß die, so einmal erleuchtet sind und geschmeckt haben die himmlische Gabe und teilhaftig worden sind des Heiligen Geistes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'und geschmeckt haben das gütige Wort Gottes und die Krafte der zukunftigen Welt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'wo sie abfallen und wiederum sich selbst den Sohn Gottes kreuzigen und fur Spott halten, daß sie sollten wiederum erneuert werden zur Bufte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Denn die Erde, die den Regen trinkt, der oft uber sie kommt, und bequem Kraut traget denen, die sie bauen, empfanget Segen von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Welche aber Dornen und Disteln traget, die ist untuchtig und dem Fluch nahe, welche man zuietzt verbrennet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Wir versehen uns aber, ihr Liebsten, Besseres zu euch, und daß die Seligkeit naher sei, ob wir wohl also reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Denn Gott ist nicht ungerecht, daß er vergesse eures Werks und Arbeit der Liebe, die ihr beweiset habt an seinem Namen, da ihr den Heiligen dientet und noch dienet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Wir begehren aber, daß euer jeglicher denselbigen Fleifi beweise, die Hoffnung festzuhalten bis ans Ende,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'daß ihr nicht trage werdet, sondern Nachfolger derer, die durch den Glauben und Geduld ererben die Verheiftungen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Denn als Gott Abraham verhieft, da er bei keinem Grofteren zu schworen hatte, schwur er bei sich selbst');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'und sprach: Wahrlich, ich will dich segnen und vermehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Und also trug er Geduld und erlangte die Verheiftung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Die Menschen schworen wohl bei einem Grofteren, denn sie sind; und der Eid macht ein Ende alles Haders, dabei es fest bleibt unter ihnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Aber Gott, da erwollte den Erben der Verheiftung uberschwenglich beweisen, daß sein Rat nicht wankete, hat er einen Eid dazugetan,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'auf daß wir durch zwei Stucke, die nicht wanken (denn es ist unmoglich, daß Gott luge), einen starken Trost haben, die wir Zuflucht haben und halten an der angebotenen Hoffnung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'welche wir haben als einen sicheren und festen Anker unserer Seele, der auch hineingehet in das Inwendige des Vorhangs,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'dahin der Vorlaufer fur uns eingegangen, Jesus, ein Hoherpriester worden in Ewigkeit nach der Ordnung Melchisedeks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Dieser Melchisedek aber war ein Konig zu Salem, ein Priester Gottes, des Allerhochsten, der Abraham entgegenging, da ervon der Konige Schlacht wiederkam, und segnete ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'welchem auch Abraham gab den Zehnten aller Güter. Aufs erste wird er verdolmetscht ein Konig der Gerechtigkeit; danach aber ist er auch ein Konig Salem, das ist, ein Konig des Friedens;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'ohne Vater, ohne Mutter, ohne Geschlecht; und hat weder Anfang der Tage noch Ende des Lebens. Er ist aber verglichen dem Sohn Gottes und bleibet Priester in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Schauet aber, wie graft ist der, dem auch Abraham, der Patriarch, den Zehnten gibt von der eroberten Beute!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Zwar die Kinder Levi, da sie das Priestertum empfangen, haben sie ein Gebot, den Zehnten vom Volk, das ist, von ihren Brudern, zu nehmen nach dem Gesetz, wiewohl auch dieselben aus den Lenden Abrahams kommen sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Aber der, des Geschlecht nicht genannt wird unter ihnen, der nahm den Zehnten von Abraham und segnete den, der die Verheiftung hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Nun ist\'s ohne alles Widersprechen also, daß das Geringere von dem Besseren gesegnet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Und hier nehmen den Zehnten die sterbenden Menschen; aber dort bezeuget er, daß er lebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Und daß ich also sage, es ist auch Levi, der den Zehnten nimmt, verzehntet durch Abraham.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Denn er war je noch in den Lenden des Vaters, da ihm Melchisedek entgegenging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Ist nun die Vollkommenheit durch das levitische Priestertum geschehen (denn unter demselbigen hat das Volk das Gesetz empfangen), was ist denn weiter not zu sagen, daß ein anderer Priester aufkommen solle nach der Ordnung Melchisedeks und nicht nach der Ordnung Aarons?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Denn wo das Priestertum verandert wird, da muft auch das Gesetz verandert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Denn von dem solches gesagt ist, der ist von einem andern Geschlecht, aus welchem nie keiner des Altars gepfleget hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Denn es ist ja offenbar, daß von Juda aufgegangen ist unser Herr; zu welchem Geschlecht Mose nicht geredet hat vom Priestertum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Und es ist noch viel klarer, so nach der Weise Melchisedeks ein anderer Priester aufkommt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'welcher nicht nach dem Gesetz des fleischlichen Gebots gemacht ist, sondern nach der Kraft des unendlichen Lebens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Denn er bezeuget: Du bist ein Priester ewiglich nach der Ordnung Melchisedeks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Denn damit wird das vorige Gesetz aufgehoben, darum daß es zu schwach und nicht nütze war');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(denn das Gesetz konnte nichts vollkommen machen), und wird eingefuhret eine bessere Hoffnung, durch welche wirzu Gott nahen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'und dazu, das viel ist, nicht ohne Eid. Denn jene sind ohne Eid Priester worden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'dieser aber mit dem Eid durch den, der zu ihm spricht: Der Herr hat geschworen, und wird ihn nicht gereuen: Du bist ein Priester in Ewigkeit nach der Ordnung Melchisedeks.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Also eines so viel besseren Testaments Ausrichter ist Jesus worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Und jener sind viel, die Priester wurden, darum daß sie der Tod nicht bleiben lieft;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'dieser aber darum, daß er bleibet ewiglich, hat er ein unverganglich Priestertum;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'dahererauch selig machen kann immerdar, die durch ihn zu Gott kommen, und lebet immerdar und bittet fur sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Denn einen solchen Hohenpriester sollten wir haben, der da ware heilig, unschuldig, unbefleckt, von den Sundern abgesondert und hoher, denn der Himmel ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'dem nicht taglich not ware wie jenen Hohenpriestern, zuerst fur eigene Sünden Opfer zu tun, danach fur des Volks Sünden; denn das hat er getan einmal, da er sich selbst opferte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Denn das Gesetz macht Menschen zu Hohenpriestern, die da Schwachheit haben; dies Wort aber des Eides, das nach dem Gesetz gesagt ist, setzet den Sohn ewig und vollkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Das ist nun die Summa, davon wir reden: Wir haben einen solchen Hohenpriester, der da sitzet zu der Rechten auf dem Stuhl der Majestat im Himmel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'und ist ein Pfleger der heiligen Güter und der wahrhaftigen Hutte, welche Gott aufgerichtet hat und kein Mensch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Denn ein jeglicher Hoherpriester wird eingesetzt, zu opfern Gaben und Opfer. Darum muß auch dieser etwas haben, das er opfere.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Wenn er nun auf Erden ware, so ware er nicht Priester, dieweil da Priester sind, die nach dem Gesetz die Gaben opfern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'welche dienen dem Vorbilde und dem Schatten der himmlischen Guter; wie die gottliche Antwort zu Mose sprach, da ersollte die Hutte vollenden: Schaue zu, sprach er, daß du machest alles nach dem Bilde, das dir auf dem Berge gezeiget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Nun aber hat er ein besser Amt erlanget, als der eines besseren Testaments Mittler ist, welches auch auf besseren Verheißungen stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Denn so jenes, das erste, untadelig gewesen ware, wurde nicht Raum zu einem andern gesucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Denn er tadelt sie und sagt: Siehe, es kommen die Tage, spricht der Herr, dafi ich uber das Haus Israel und uber das Haus Juda ein neu Testament machen will;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'nicht nach dem Testament, das ich gemacht habe mit ihren Vatern an dem Tage, da ich ihre Hand ergriff, sie auszuführen aus Agyptenland. Denn sie sind nicht geblieben in meinem Testament; so habe ich ihrer auch nicht wollen achten, spricht der Herr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Denn das ist das Testament, das ich machen will dem Hause Israel nach diesen Tagen, spricht der Herr: Ich will geben meine Gesetze in ihren Sinn, und in ihr Herz will ich sie schreiben, und will ihr Gott sein, und sie sollen mein Volk sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Und soil nicht lehren jemand seinen Nachsten noch jemand seinen Bruder und sagen: Erkenne den Herm! Denn sie sollen mich alle kennen, von dem Kleinsten an bis zu dem Großten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Denn ich will gnadig sein ihrer Untugend und ihren Sünden, und ihrer Ungerechtigkeit will ich nicht mehrgedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Indem er sagt: Ein neues, macht er das erste alt. Was aber alt und uberjahret ist, das ist nahe bei seinem Ende.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Es hatte zwar auch das erste seine Rechte des Gottesdienstes und aul Jerliche Heiligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Denn es war da aufgerichtet das Vorderteil der Hutte, darinnen war der Leuchter und der Tisch und die Schaubrote; und diese heißt das Heilige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Hinter dem andern Vorhang aber war die Hutte, die da heilit das Allerheiligste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Die hatte das guldene Rauchfal J und die Lade des Testaments, allenthalben mit Gold überzogen, in welcher war die guldene Gelte, die das Himmelbrot hatte, und die Rute Aarons, die gegrunet hatte, und die Tafeln des Testaments.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Oben drüber aber waren die Cherubim der Herrlichkeit, die uberschatteten den Gnadenstuhl; von welchem jetzt nicht zu sagen ist insonderheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Da nun soiches also zugerichtet war gingen die Priester allezeit in die vorderste Hutte und richteten aus den Gottesdienst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'In die andere aber ging nur einmal im Jahr allein der Hohepriester, nicht ohne Blut, dafi er opferte fur sein selbst und des Volks Unwissenheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Damit der Heilige Geist deutete, daß noch nicht offenbart ware der Weg zur Heiligkeit, solange die erste Hutte stunde,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'welche mußte zu derselbigen Zeit ein Vorbild sein, in welcher Gaben und Opfer geopfert wurden, und konnten nicht vollkommen machen nach dem Gewissen den, der da Gottesdienst tut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'allein mit Speise und Trank und mancherlei Taufen und außerlicher Heiligkeit, die bis auf die Zeit der Besserung sind aufgelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Christus aber ist kommen, daß er sei ein Hoherpriester der zukunftigen Guter, durch eine groi Jere und vollkommenere Hutte, die nicht mit der Hand gemacht ist, das ist, die nicht also gebauet ist;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Auch nicht durch der Bocke Oder Kalber Blut, sondern er ist durch sein eigen Blut einmal in das Heilige eingegangen und hat eine ewige Erlosung erfunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Denn so der Ochsen und der Bocke Blut und die Asche, von der Kuh gesprenget, heiliget die Unreinen zu der leiblichen Reinigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'wieviel mehr wird das Blut Christi, der sich selbst ohne alien Wandel durch den Heiligen Geist Gott geopfert hat, unser Gewissen reinigen von den toten Werken, zu dienen dem lebendigen Gott!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Und darum ist er auch ein Mittler des Neuen Testaments, auf dafi durch den Tod, so geschehen ist zur Erlosung von den Ubertretungen, die unter dem ersten Testament waren, die, so berufen sind, das verheifiene ewige Erbe empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Denn wo ein Testament ist, da mult, der Tod geschehen des, der das Testament machte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Denn ein Testament wird test durch den Tod, anders hat es noch nicht Macht, wenn der noch lebet, der es gemacht hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Daher auch das erste nicht ohne Blut gestiftet ward.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Denn als Mose ausgeredet hatte von alien Geboten nach dem Gesetz zu allem Volk, nahm er Kalber - und Bocksblut mit Wasser und Purpurwolle und Ysop und besprengete das Buch und alles Volk.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Und sprach: Das ist das Blut des Testaments, das Gott euch geboten hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Und die Hutte und alles Gerate des Gottesdienstes besprengete er desselbigengleichen mit Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Und wird fast alles mit Blut gereiniget nach dem Gesetz. Und ohne Blutvergießen geschieht keine Vergebung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'So mußten nun der himmlischen Dinge Vorbilder mit solchem gereiniget werden; aber sie selbst, die himmlischen, mussen bessere Opfer haben, denn jene waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Denn Christus ist nicht eingegangen in das Heilige, so mit Handen gemacht ist (welches ist ein Gegenbild des rechtschaffenen), sondern in den Himmel selbst, nun zu erscheinen vor dem Angesichte Gottes fur uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Auch nicht, daß er sich oftmals opfere, gleichwie der Hohepriester gehet alle Jahr in das Heilige mit fremdem Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Sonst hatte er oft mussen leiden von Anfang der Welt her. Nun aber am Ende der Welt ist er einmal erschienen, durch sein eigen Opfer die Sünde aufzuheben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Und wie den Menschen ist gesetzt, einmal zu sterben, danach aber das Gericht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'also ist Christus einmal geopfert, wegzunehmen vieler Sünden. Zum andernmal aber wird er ohne Sünde erscheinen denen, die auf ihn warten, zur Seligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Denn das Gesetz hat den Schatten von den zukunftigen Gütern, nicht das Wesen der Güter selbst. Alle Jahr muß man opfern immer einerlei Opfer und kann nicht, die da opfern, vollkommen machen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'sonst hatte das Opfern aufgehoret, wo die, so am Gottesdienst sind, kein Gewissen mehr hatten von den Sünden, wenn sie 1 einmal gereiniget waren;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'sondern es geschieht nur durch dieselbigen ein Gedachtnis der Sünden alle Jahr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Denn es ist unmoglich, durch Ochsen - und Bocksblut Sunden wegzunehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Darum, da er in die Welt kommt, spricht er: Opfer und Gaben hast du nicht gewollt; den Leib aber hastdu mir zubereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Brandopfer und Sündopfer gefallen dir nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Da sprach ich: Siehe, ich komme; im Buch stehet vornehmlich von mir geschrieben, daß ich tun soil, Gott, deinen Willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Droben, als er gesagt hatte: Opfer und Gaben, Brandopfer und Sündopfer hast du nicht gewollt; sie gefallen dir auch nicht (welche nach dem Gesetz geopfert werden),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'da sprach er: Siehe, ich komme zu tun, Gott, deinen Willen. Da hebt er das erste auf, daß er das andere einsetze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'In welchem Willen wir sind geheiliget, einmal geschehen durch das Opfer des Leibes Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Und ein jeglicher Priester ist eingesetzt, daß er aüe Tage Gottesdienst pflege und oftmals einerlei Opfer tue, welche nimmermehr konnen die Sünden abnehmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Dieser aber, da er hat ein Opfer für die Sunden geopfert, das ewiglich gilt, sitzt er nun zur Rechten Gottes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'und wartet hinfort, bis daß seine Feinde zum Schemel seiner Füße gelegt werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Denn miteinem Opfer hater in Ewigkeit vollendet, die geheiliget werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Es bezeuget uns aber das auch der Heilige Geist. Denn nachdem er zuvor gesagt hatte:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Das ist das Testament, das ich ihnen machen will nach diesen Tagen, spricht der Herr: Ich will mein Gesetz in ihr Herz geben, und in ihre Sinne will ich es schreiben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'und ihrer Sünden und ihrer Ungerechtigkeit will ich nicht mehrgedenken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Wo aber derselbigen Vergebung ist, da ist nicht mehr Opfer fur die Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'So wir denn nun haben, liebe Brüder, die Freudigkeit zum Eingang in das Heilige durch das Blut Jesu,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'welchen er uns zubereitet hat zum neuen und lebendigen Wege durch den Vorhang, das ist, durch sein Fleisch,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'und haben einen Hohenpriester über das Haus Gottes:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'so lasset uns hinzugehen mit wahrhaftigem Herzen, in volligem Glauben, besprenget in unsern Herzen und los von dem bosen Gewissen und gewaschen am Leibe mit reinem Wasser;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'und lasset uns halten an dem Bekenntnis der Hoffnung und nicht wanken denn er ist treu, der sie verheißen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Und lasset uns untereinander unser selbst wahrnehmen mit Reizen zur Liebe und guten Werken');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'und nicht verlassen unsere Versammlung, wie etliche pflegen, sondern untereinander ermahnen, und das viel mehr, soviel ihr sehet, daß sich der Tag nahet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Denn so wir mutwillig sündigen, nachdem wir die Erkenntnis der Wahrheit empfangen haben, haben wir furder kein ander Opfer mehr fur die Sunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'sondern ein schrecklich Warten des Gerichts und des Feuereifers, der die Widerwartigen verzehren wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Wenn jemand das Gesetz Mose\'s bricht, der muß sterben ohne Barmherzigkeit durch zween Oder drei Zeugen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Wieviel meinet ihr, argere Strafe wird der verdienen, der den Sohn Gottes mit Fußen tritt und das Blut des Testaments unrein achtet, durch welches er geheiliget ist, und den Geist der Gnaden schmahet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Denn wir wissen den, der da sagte: Die Rache ist mein; ich will vergelten, spricht der Herr. Und abermal: Der Herr wird sein Volk richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Schrecklich ist\'s, in die Hande des lebendigen Gottes zu fallen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Gedenket aber an die vorigen Tage, in welchen ihr, erleuchtet, erduldet habt einen großen Kampf des Leidens,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'zum Teil selbst durch Schmach und Trubsal ein Schauspiel worden, zum Teil Gemeinschaft gehabt mit denen, denen es also gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Denn ihr habt mit meinen Banden Mitleid gehabt und den Raub eurer Güter mit Freuden erduldet, als die ihr wisset, daß ihr bei euch selbst eine bessere und bleibende Habe im Himmel habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Werfet euer Vertrauen nichtweg, welches eine grotie Belohnung hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Geduld aber ist euch not, auf dafi ihr den Willen Gottes tut und die Verheißung empfanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Denn noch uber eine kleine Weile, so wird kommen, der da kommen soil, und nicht verziehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Der Gerechte aber wird des Glaubens leben. Wer aber weichen wird, an dem wird meine Seele kein Gefallen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Wir aber sind nicht von denen, die da weichen und verdammtwerden, sondern von denen, die da glauben und die Seele erretten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Es ist aber der Glaube eine gewisse Zuversicht des, das man hoffet, und nicht zweifeln an dem, das man nicht siehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Durch den haben die Alten Zeugnis überkommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Durch den Glauben merken wir, daß die Welt durch Gottes Wort fertig ist, dafi alles, was man siehet, aus nichts worden ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Durch den Glauben hat Abel Gott ein großer Opfer getan denn Kain, durch weichen er Zeugnis überkommen hat, daß er gerecht sei, da Gott zeugete von seiner Gabe; und durch denselbigen redet er noch, wiewohl er gestorben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Durch den Glauben ward Enoch weggenommen, dafi er den Tod nicht sahe, und ward nicht gefunden, darum daß ihn Gott wegnahm; denn vor seinem Wegnehmen hat er Zeugnis gehabt, daß er Gott gefallen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Aberohne Glauben ist\'s unmoglich, Gott gefallen; denn wer zu Gott kommen will, der muß glauben, daß er sei und denen, die ihn suchen, ein Vergelter sein werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Durch den Glauben hat Noah Gott geehret und die Arche zubereitet zum Heil seines Hauses, da er einen gottlichen Befehl empfing von dem das man noch nicht sah; durch weichen er verdammte die Welt und hat ererbet die Gerechtigkeit, die durch den Glauben kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Durch den Glauben ward gehorsam Abraham, da er berufen ward, auszugehen in das Land, das er ererben sollte; und ging aus und wußte nicht, wo er hinkame.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Durch den Glauben ist er ein Fremdling gewesen in dem verheißenen Lande als in einem fremden und wohnete in Hütten mit Isaak und Jakob, den Miterben derselbigen Verheißung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Denn er wartete auf eine Stadt, die einen Grund hat, welcher Baumeister und Schopfer Gott ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Durch den Glauben empfing auch Sara Kraft, daß sie schwanger ward, und gebar fiber die Zeit ihres Alters; denn sie achtete ihn treu, der es verheißen hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Darum sind auch von einem, wie wohl erstorbenen Leibes, viele geboren wie die Sterne am Himmel und wie der Sand am Rande des Meeres, der unzahlig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Diese alle sind gestorben im Glauben und haben die Verheißung nicht empfangen, sondern sie von feme gesehen und sich der vertrostet und wohl genügen lassen und bekannt, daß sie Gaste und Fremdlinge auf Erden sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Denn diesolches sagen, die geben zu verstehen, daß sie ein Vaterland suchen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Und zwar, wo sie dasgemeinet hatten, von welchem sie waren ausgezogen, hatten sie ja Zeit, wieder umzukehren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Nun aber begehren sie eines besseren, namlich eines himmlischen. Darum schamet sich Gott ihrer nicht, zu heißen ihr Gott; denn er hat ihnen eine Stadt zubereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Durch den Glauben opferte Abraham den Isaak, da er versucht ward, und gab dahin den Eingebornen, da er schon die Verheißung empfangen hatte,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'von welchem gesagt war: In Isaak wird dir dein Same geheißen werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'und dachte: Gott kann auch wohl von den Toten erwecken; daher er auch ihn zum Vorbilde wieder nahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Durch den Glauben segnete Isaak von den zukunftigen Dingen den Jakob und Esau.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Durch den Glauben segnete Jakob, da er starb, beide Sohne Josephs und neigete sich gegen seines Zepters Spitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Durch den Glauben redete Joseph vom Auszug der Kinder Israel, da er starb, und tat Befehl von seinen Gebeinen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Durch den Glauben ward Mose, da er geboren war, drei Monden verborgen von seinen Eltern, darum daß sie sahen, wie er ein schon Kind war, und furchteten sich nicht vor des Konigs Gebot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Durch den Glauben wollte Mose, da er groß ward, nicht mehr ein Sohn heißen der Tochter Pharaos');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'und erwahlete viel lieber, mit dem Volk Gottes Ungemach zu leiden, denn die zeitliche Ergotzung der Sunde zu haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'und achtete die Schmach Christi fur grotieren Reichtum denn die Schatze Agyptens; denn er sah an die Belohnung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Durch den Glauben verlieli er Agypten und furchtete nicht des Konigs Grimm; denn er hielt sich an den, den er nicht sah, als sahe er ihn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Durch den Glauben hielt er Ostern und das Blutvergiefien, auf daß, der die Erstgeburten wurgete, sie nicht trafe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Durch den Glauben gingen sie durch das Rote Meer als durch trocken Land; welches die Agypter auch versuchten und ersoffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Durch den Glauben fielen die Mauern Jerichos, da sie sieben Tage umhergegangen waren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Durch den Glauben ward die Hure Rahab nicht verloren mitden Unglaubigen, da sie die Kundschafter freundlich aufnahm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Und was soli ich mehr sagen? Die Zeit wurde mir zu kurz, wenn ich sollte erzahlen von Gideon und Barak und Simson und Jephthah und David und Samuel und den Propheten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'welche haben durch den Glauben Konigreiche bezwungen, Gerechtigkeit gewirket, die Verheifiung erlanget, der Lowen Rachen verstopfet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'des Feuers Kraft ausgeloscht, sind des Schwerts Scharfe entronnen, sind kraftig worden aus der Schwachheit, sind stark worden im Streit, haben der Fremden Fleer daniedergelegt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Die Weiber haben ihre Toten von der Auferstehung wieder genommen; die andern aber sind zerschlagen und haben keine Erlosung angenommen, auf daß sie die Auferstehung, die besser ist, erlangeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Etliche haben Spott und Geilieln erlitten, dazu Bande und Gefangnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Sie sind gesteiniget, zerhackt, zerstochen, durchs Schwert getotet; sie sind umhergegangen in Pelzen und Ziegenfellen, mit Mangel, mit Trubsal, mit Ungemach');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(deren die Welt nicht wert war) und sind im Elend gegangen in den Wusten, auf den Bergen und in den Kluften und Lochern der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Diese alle haben durch den Glauben Zeugnis uberkommen und nicht empfangen die Verheifiung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'darum daß Gott etwas Besseres fur uns zuvor versehen hat, daß sie nicht ohne uns vollendet wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Darum auch wir, dieweil wir solchen Flaufen Zeugen urn uns haben, lasset uns ablegen die Sunde, so uns immer anklebt und trage macht, und lasset uns laufen durch Geduld in dem Kampf, der uns verordnet ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'und aufsehen auf Jesum, den Anfanger und Vollender des Glaubens, welcher, da er wohl hatte mogen Freude haben, erduldete er das Kreuz und achtete der Schande nicht und ist gesessen zur Rechten auf dem Stuhl Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Gedenketanden,dereinsolches Widersprechen von den Sundern wider sich erduldet hat, daß ihr nicht in eurem Mut matt werdet und ablasset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Denn ihr habt noch nicht bis aufs Blut widerstanden uber dem Kampfen wider die Sunde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'und habt bereits vergessen des Trostes, der zu euch redet als zu den Kindern: Mein Sohn, achte nicht gering die Zuchtigung des Herm und verzage nicht, wenn du von ihm gestraft wirst;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'denn welchen der Herr liebhat, den zuchtiget er; er staupt aber einen jeglichen Sohn, den er aufnimmt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'So ihr die Zuchtigung erduldet, so erbeut sich euch Gott als Kindern; denn wo ist ein Sohn, den der Vater nicht zuchtiget?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Seid ihr aber ohne Zuchtigung, welcher sie alle sind teilhaftig worden, so seid ihr Bastarde und nicht Kinder.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Auch so wir haben unsere leiblichen Vater zu Zuchtigern gehabt und sie gescheuet, sollten wir denn nicht viel mehr untertan sein dem geistlichen Vater, daß wir leben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Und jene zwar haben uns gezuchtiget wenige Tage nach ihrem Dunken, dieser aber zu Nutz, auf daß wir seine Heiligung erlangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Alle Zuchtigung aber, wenn sie da ist, dunktsie uns nicht Freude, sondern Traurigkeit sein; aber danach wird sie geben eine friedsame Frucht der Gerechtigkeit denen, die dadurch geubet sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Darum richtet wieder auf die lassigen Hande und die muden Kniee');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'und tutgewissen Tritt miteuren Fütien, daß nicht jemand strauchele wie ein Lahmer, sondern vielmehr gesund werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Jaget nach dem Frieden gegen jedermann und der Heiligung, ohne welche wird niemand den Herm sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Und sehet darauf, daß nicht jemand Gottes Gnade versaume, daß nicht etwa eine bittere Wurzel aufwachse und Unfrieden anrichte, und viele durch dieselbige verunreiniget werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'daß nicht jemand seiein Hurer Oder ein Gottloser wie Esau, der urn einer Speise willen seine Erstgeburt verkaufte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Wisset aber, daß er hernach, da er den Segen ererben wollte, verworfen ist; denn er fand keinen Raum zur Bulie, wiewohl ersie mit Tranen suchte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Denn ihr seid nicht kommen zu dem Berge, den man anruhren konnte, und mit Feuer brannte, noch zu dem Dunkel und Finsternis und Ungewitter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'noch zu dem Flail der Posaune und zur Stimme der Worte, welcher sich weigerten, die sie horeten, daß ihnen das Wort ja nicht gesagt wurde');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(denn sie mochten\'s nicht ertragen, was da gesagt ward. Und wenn ein Tier den Berg anrührete, sollte es gesteiniget Oder mit einem Geschoft erschossen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Und also erschrecklich war das Gesicht, daß Mose sprach: Ich bin erschrocken und zittere),');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'sondern ihr seid kommen zu dem Berge Zion und zu der Stadt des lebendigen Gottes, zu dem himmlischen Jerusalem, und zu der Menge vieler tausend Engel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'und zu der Gemeinde der Erstgebornen, die im Himmel angeschrieben sind, und zu Gott, dem Richter uber alle, und zu den Geistern der vollkommenen Gerechten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'und zu dem Mittlerdes Neuen Testaments, Jesus, und zu dem Blut der Besprengung, das da besser redet denn Abels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sehet zu, daß ihr euch des nicht weigert, der da redet! Denn jene nicht entflohen sind, die sich weigerten, da er auf Erden redete, viel weniger wir, so wir uns des weigern, der vom Himmel redet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'welches Stimme zu der Zeit die Erde bewegete. Nun aber verheiftet er und spricht: Noch einmal will ich bewegen nicht allein die Erde, sondern auch den Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Aber solches \"Noch einmal\" zeigt an, daß das Bewegliche soil verandert werden, als das gemacht ist, auf daß da bleibe das Unbewegliche.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Darum, dieweil wir empfangen ein unbeweglich Reich, haben wir Gnade, durch welche wir sollen Gott dienen, ihm zu gefallen, mit Zucht und Furcht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Denn unser Gott ist ein verzehrend Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Bleibet fest in der bruderlichen Liebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Gastfrei zu sein vergesset nicht; denn durch dasselbige haben etliche ohne ihr Wissen Engel beherberget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Gedenket der Gebundenen als die Mitgebundenen und derer, die Trubsal leiden, als die ihr auch noch im Leibe lebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Die Ehe soil ehrlich gehalten werden bei alien und das Ehebett unbefleckt; die Hurer aber und Ehebrecher wird Gott richten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Der Wandel sei ohne Geiz; und lasset euch begnügen an dem, was da ist. Denn er hat gesagt: Ich will dich nicht verlassen noch versaumen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'also daß wir dürfen sagen: Der Herr ist mein Heifer, und will mich nicht furchten; was sollte mir ein Mensch tun?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Gedenket an eure Lehrer, die euch das Wort Gottes gesagt haben, welcher Ende schauet an und folget ihrem Glauben nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus gestern und heute und derselbe auch in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Lasset euch nicht mit mancherlei und fremden Lehren umtreiben; denn es ist ein kostlich Ding, daß das Herz fest werde, welches geschieht durch Gnade, nicht durch Speisen, davon keinen Nutzen haben, so damit umgehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Wir haben einen Altar, davon nicht Macht haben zu essen, die der Hutte pflegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Denn welcher Tiere Blut getragen wird durch den Hohenpriester in das Heilige fur die Sünde, derselbigen Leichname werden verbrannt aufter dem Lager.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Darum auch Jesus, auf daß er heiligte das Volk durch sein eigen Blut, hat er gelitten auften vor dem Tor.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'So lasset uns nun zu ihm hinausgehen aufter dem Lager und seine Schmach tragen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Denn wir haben hier keine bleibende Stadt, sondern die zukünftige suchen wir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'So lasset uns nun opfern durch ihn das Lobopfer Gott allezeit, das ist, die Frucht der Lippen, die seinen Namen bekennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Wohlzutun und mitzuteilen vergesset nicht; denn solche Opfer gefallen Gottwohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Gehorchet euren Lehrern und folget ihnen; denn sie wachen über eure Seelen, als die da Rechenschaft dafur geben sollen, auf daß sie das mit Freuden tun und nicht mit Seufzen; denn das ist euch nicht gut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Betet fur uns! Unser Trost ist der, daß wir ein gut Gewissen haben und fleiftigen uns, guten Wandel zu führen bei alien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Ich ermahne euch aberzum Uberfluft, solches zu tun, auf daß ich aufs schierste wieder zu euch komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Gott aber des Friedens, der von den Toten ausgeführet hat den groften Hirten der Schafe durch das Blut des ewigen Testaments, unsern Herrn Jesum,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'der mache euch fertig in allem guten Werk, zu tun seinen Willen, und schaffe in euch, was vor ihm gefallig ist, durch Jesum Christum, welchem sei Ehre von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ich ermahne euch aber, liebe Bruder, haltet das Wort der Ermahnung zugute; denn ich habe euch kurz geschrieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wisset, daß der Bruder Timotheus wieder ledig ist, mit welchem, so er bald kommt, will ich euch sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Gruftet alle eure Lehrer und alle Heiligen. Es grüften euch die Bruder aus Italien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Die Gnade sei mit euch alien! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobus, eir Knecht Gottes und des Herrn Jesu Christi, den zwolf Geschlechtern, die da sind hin und her: Freude zuvor!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Meine lieben Bruder, achtet es eitel Freude, wenn ihr in mancherlei Anfechtung fallet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'und wisset, dafi euer Glaube, so er rechtschaffen ist, Geduld wirket.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Die Geduld aber soil festbleiben bis ans Ende, auf daß ihrseid vollkommen und ganz und keinen Mangel habet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'So aber jemand unter euch Weisheit mangelt, der bitte von Gott, der da gibt einfaltiglich jedermann und rucket es niemand auf; so wird sie ihm gegeben werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Er bitte aber im Glauben und zweifle nicht; denn wer da zweifelt, der ist gleich wie die Meereswoge, die vom Winde getrieben und gewebet wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Solcher Mensch denke nicht, dati er etwas von dem Herrn empfangen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Ein Zweifler ist unbestandig in alien seinen Wegen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Ein Bruder aber, der niedrig ist, rühme sich seiner Hohe,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'und der da reich ist, ruhme sich seiner Niedrigkeit; denn wie eine Blume des Grases wird er vergehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Die Sonne gehet auf mit der Hitze, und das Gras verwelket, und die Blume fallt ab und seine schone Gestalt verdirbet; also wird der Reiche in seiner Habe verwelken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Selig ist der Mann, der die Anfechtung erduldet; denn nachdem er bewahret ist, wird er die Krone des Lebens empfangen, welche Gott verheifien hat denen, die ihn liebhaben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Niemand sage, wenn erversuchetwird, daß er von Gott versucht werde; denn Gott ist nicht ein Versucher zum Bosen; er versuchet niemand;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'sondern ein jeglicher wird versucht, wenn ervon seiner eigenen Lust gereizet und gelocket wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Danach, wenn die Lust empfangen hat, gebieret sie die Sünde; die Sünde aber, wenn sie vollendet ist, gebieret sie den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Irret nicht, liebe Bruder!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Alle gute Gabe und alle vollkommene Gabe kommt von oben herab, von dem Vater des Lichts, bei welchem ist keine Veranderung noch Wechsel des Lichts und Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Er hat uns gezeuget nach seinem Willen durch das Wort der Wahrheit, auf daß wir waren Erstlinge seiner Kreaturen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Darum, liebe Bruder, ein jeglicher Mensch sei schnell zu horen, langsam aberzu reden und langsam zum Zorn;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'denn des Menschen Zorn tut nicht, was vor Gott recht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Darum so leget ab alle Unsauberkeit und alle Bosheit und nehmet das Wort an mit Sanftmut, das in euch gepflanzet ist, welches kann eure Seelen selig machen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Seid aber Tater des Worts und nicht Horer allein, damit ihr euch selbst betruget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Denn so jemand ist ein Horer des Worts und nicht ein Tater, der ist gleich einem Mann, der sein leiblich Angesicht im Spiegel beschauet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'denn nachdem er sich beschauet hat, gehet er von Stund\' an davon und vergisset, wie er gestaltet war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Wer aber durchschauet in das voll kommene Gesetz der Freiheit und darinnen beharret und ist nicht ein vergelilicher Horer, sondern ein Tater, derselbige wird selig sein in seiner Tat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'So aber sich jemand unter euch lasset dunken, er diene Gott, und halt seine Zunge nicht im Zaum, sondern verfuhret sein Herz, des Gottesdienst ist eitel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Ein reinerund unbefleckter Gottesdienst vor Gott dem Vater ist der: die Waisen und Witwen in ihrer Trubsal besuchen und sich von der Welt unbefleckt behalten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Liebe Bruder, haltet nicht dafur, daß der Glaube an Jesum Christum, unsern Herrn der Herrlichkeit, Ansehen der Person leide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Denn so in eure Versammlung kame ein Mann mit einem güldenen Ringe und mit einem herrlichen Kleide, es kame aber auch ein Armer mit einem unsauberen Kleide,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'und ihr sahet auf den, der das herrliche Kleid traget, und sprachet zu ihm: Setze du dich her aufs beste, und sprachet zu dem Armen: Stehe du dort Oder setze dich her zu meinen Fulien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'und bedenket es nicht recht, sondern ihrwerdet Richter und machet bosen Unterschied.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Horet zu, meine lieben Bruder! Hat nicht Gott die Armen auf dieser Welt, die am Glauben reich sind und Erben des Reichs, welches er verheifien hat denen, die ihn liebhaben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ihr aber habt dem Armen Unehre getan. Sind nicht die Reichen die, die Gewalt an euch üben und ziehen euch vor Gericht?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Verlastern sie nicht den guten Namen, davon ihr genannt seid?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'So ihr das konigliche Gesetz vollendet nach der Schrift: Liebe deinen Nachsten wie dich selbst, so tut ihrwohl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'So ihr aber die Person ansehet, tut ihr Sünde und werdet gestraft vom Gesetz als die Ubertreter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Denn jemand das ganze Gesetz halt und sundiget an einem, der ist\'s ganz schuldig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Denn der da gesagt hat: Du sollst nicht ehebrechen, der hat auch gesagt: Du sollst nicht toten. So du nun nicht ehebrichst, totest aber, bist du ein Ubertreter des Gesetzes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Also redet und also tut, als die da sollen durchs Gesetz der Freiheit gerichtet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Es wird aber ein unbarmherzig Gericht uber den gehen, der nicht Barmherzigkeit getan hat; und die Barmherzigkeit rühmet sich wider das Gericht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Was hilft\'s, liebe Bruder, so jemand sagt, er habe den Glauben, und hat doch die Werke nicht? Kann auch der Glaube ihn selig machen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'So aber ein Bruder Oder Schwester bloft ware und Mangel hatte der taglichen Nahrung,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'und jemand unter euch sprache zu ihnen: Gott berate euch, warmet euch und sattiget euch! gabet ihnen aber nicht, was des Leibes Notdurft ist, was hülfe ihnen das?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Also auch der Glaube, wenn er nicht Werke hat, ist er tot an ihm selber.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Aber es mochte jemand sagen: Du hast den Glauben, und ich habe die Werke; zeige mirdeinen Glauben mit deinen Werken, so will ich auch meinen Glauben dirzeigen mit meinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du glaubest, daß ein einiger Gott ist; du tust wohl daran; die Teufel glauben\'s auch und zittern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Willst du aber wissen, du eitler Mensch, daß der Glaube ohne Werke tot sei?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ist nicht Abraham, unser Vater, durch die Werke gerecht worden, da er seinen Sohn Isaak auf dem Altar opferte?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Da siehest du, daß der Glaube mitgewirket hat an seinen Werken, und durch die Werke ist der Glaube vollkommen worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Und ist die Schrift erfüllet, die da spricht: Abraham hat Gott geglaubet, und ist ihm zur Gerechtigkeit gerechnet, und ist ein Freund Gottes geheiften.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'So sehet ihr nun, daß der Mensch durch die Werke gerecht wird, nicht durch den Glauben allein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Desselbigengleichen die Hure Rahab, ist sie nicht durch die Werke gerecht worden, da sie die Boten aufnahm und lieft sie einen andern Weg hinaus?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Denn gleichwie der Leib ohne Geist tot ist, also auch der Glaube ohne Werke ist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Liebe Bruder, unterwinde sich nicht jedermann, Lehrer zu sein; und wisset, daß wir desto mehr Urteil empfangen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Denn wir fehlen alle mannigfaltiglich. Wer aber auch in keinem Wort fehlet, der ist ein vollkommener Mann und kann auch den ganzen Leib im Zaum halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Siehe, die Pferde halten wir in Zaumen, daß sie uns gehorchen, und lenken den ganzen Leib.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Siehe, die Schiffe, ob sie wohl so graft sind und von starken Winden getrieben werden, werden sie doch gelenkt mit einem kleinen Ruder, wo der hin will, der es regieret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Also ist auch die Zunge ein klein Glied und richtet grofte Dinge an. Siehe, ein klein Feuer, welch einen Wald zundet\'s an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Und die Zunge ist auch ein Feuer, eine Welt voll Ungerechtigkeit. Also ist die Zunge unter unsern Gliedern und befleckt den ganzen Leib und zundet an alien unsern Wandel, wenn sie von der Holle entzundet ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Denn alle Natur der Tiere und der Vogel und der Schlangen und der Meerwunder werden gezahmet und sind gezahmet von der menschlichen Natur;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'aber die Zunge kann kein Mensch zahmen, das unruhige Ubel voll todlichen Giftes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Durch sie loben wir Gott den Vater, und durch sie fluchen wir den Menschen, nach dem Bilde Gottes gemacht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Aus einem Munde gehet Loben und Fluchen. Es soil nicht, liebe Bruder, also sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Quillet auch ein Brunnen aus einem Loche süft und bitter?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Kann auch, liebe Bruder, ein Feigenbaum 01 Oder ein Weinstock Feigen tragen? Also kann auch ein Brunnen nicht salzig und süft Wasser geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Wer istweise und klug unter euch? Der erzeige mit seinem guten Wandel seine Werke in der Sanftmut und Weisheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Habt ihr aber bitteren Neid und Zank in eurem Herzen, so rühmet euch nicht und lüget nicht wider die Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Denn das ist nicht die Weisheit, die von oben herab kommt, sondern irdisch, menschlich und teuflisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Denn wo Neid und Zank ist, da ist Unordnung und eitel boses Ding.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Die Weisheit aber von oben her ist aufs erste keusch, danach friedsam, gelinde, lasset sich sagen, voll Barmherzigkeit und guter Früchte, unparteüsch, ohne Heuchelei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Die Frucht aber der Gerechtigkeit wird gesaet im Frieden denen, die den Frieden halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Woher kommt Streit und Krieg unter euch? Kommt\'s nicht daher, aus euren Wollüsten, die da streiten in euren Gliedern?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ihr seid begierig und erlanget es damit nicht; ihr hasset und neidet und gewinnet damit nichts; ihr streitet und krieget. Ihr habt nicht, darum daß ihr nicht bittet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Ihr bittet und krieget nicht, darum daß ihr ubel bittet, namlich dahin, daß ihr\'s mit euren Wollüsten verzehret.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ihr Ehebrecher und Ehebrecherinnen, wisset ihr nicht, daß der Welt Freundschaft Gottes Feindschaft ist? Wer der Welt Freund sein will, der wird Gottes Feind sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Oder lasset ihr euch dunken, die Schrift sage umsonst: Den Geist, der in euch wohnet, gelüstet wider den Hafi?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Und gibt reichlich Gnade, sintemal die Schrift sagt: Gott widerstehet den Hoffartigen, aber den Demutigen gibt er Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'So seid nun Gott untertanig. Wider stehet dem Teufel, so flieht er von euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Nahet euch zu Gott, so nahet er sich zu euch. Reiniget die Hande, ihr Sunder, und machet eure Herzen keusch, ihr Wankelmütigen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Seid elend und traget Leid und weinet! Euer Lachen verkehre sich in Weinen und eure Freude in Traurigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Demutiget euch vor Gott, so wird er euch erhohen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Afterredet nicht untereinander, liebe Bruder! Wer seinem Bruder afterredet und urteilet seinen Bruder, der afterredet dem Gesetz und urteilet das Gesetz. Urteilest du aber das Gesetz, so bist du nicht ein Tater des Gesetzes, sondern ein Richter.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Es istein einiger Gesetzgeber, der kann selig machen und verdammen. Wer bist du, der du einen andern urteilest?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Wohlan, die ihr nun saget: Heute Oder morgen wollen wir gehen in die Oder die Stadt und wollen ein Jahrda liegen und hantieren und gewinnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'die ihr nicht wisset, was morgen sein wird. Denn was ist euer Leben? Ein Dampf ist\'s, der eine kleine Zeit wahret, danach aber verschwindet er.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Dafür ihr sagen solltet: So der Herr will, und wir leben, wollen wir dies Oder das tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Nun aber rühmet ihr euch in eurem Hochmut. Aller solcher Ruhm ist bose.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Denn wer da weiß, Gutes zu tun, und tut’s nicht, dem ist\'s Sunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Wohlan nun, ihr Reichen, weinet und heulet uber euer Elend, das fiber euch kommen wird!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Euer Reichtum ist verfaulet; eure Kleider sind mottenfraßig worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Euer Gold und Silber ist verrostet, und ihr Rost wird euch zum Zeugnis sein und wird euer Fleisch fressen wie ein Feuer. Ihr habt euch Schatze gesammelt an den letzten Tagen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Siehe, der Arbeiter Lohn, die euer Land eingeerntet haben, und von euch abgebrochen ist, der schreiet; und das Rufen der Ernter ist kommen vor die Ohren des Herrn Zebaoth.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ihr habt wohlgelebet auf Erden und eure Wollust gehabt und eure Herzen geweidet als auf einen Schlachttag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Ihr habt verurteilet den Gerechten und getotet, und er hat euch nicht widerstanden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'So seid nun geduldig, liebe Bruder, bis auf die Zukunft des Herrn! Siehe, ein Ackermann wartet auf die kostliche Frucht der Erde und ist geduldig darüber, bis daß er empfange den Morgenregen und Abendregen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Seid ihr auch geduldig und starket eure Herzen; denn die Zukunft des Herrn ist nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Seufzet nicht widereinander, liebe Bruder, auf daß ihr nicht verdammet werdet! Siehe, der Richter ist vor der Tür!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Nehmet, meine lieben Bruder, zum Exempel des Leidens und der Geduld die Propheten, die zu euch geredet haben in dem Namen des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Siehe, wir preisen selig, die erduldet haben. Die Geduld Hiobs habt ihrgehoret, und das Ende des Herrn habt ihr gesehen; denn der Herr ist barmherzig und ein Erbarmer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Vor alien Dingen aber, meine Bruder, schworet nicht, weder bei dem Himmel noch bei der Erde noch mit keinem andern Eide. Es sei aber euer Wort: Ja, das ja ist; und: Nein, das nein ist, auf daß ihr nicht in Heuchelei fallet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Leidetjemand untereuch, derbete; istjemand gutes Muts, der singe Psalmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Istjemand krank, der rufe zu sich die Altesten von der Gemeinde und lasse sie fiber sich beten und salben mit 01 in dem Namen des Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Und das Gebet des Glaubens wird dem Kranken helfen, und der Herr wird ihn aufrichten; und so er hat Sünden getan, werden sie ihm vergeben sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekenne einerdem andern seine Sünden und betet ffireinander, daß ihr gesund werdet. Des Gerechten Gebet vermag viel, wenn es ernstlich ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elia war ein Mensch gleich wie wir, und er betete ein Gebet, daß es nicht regnen sollte; und es regnete nicht auf Erden drei Jahre und sechs Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Und er betete abermal, und der Himmel gab den Regen, und die Erde brachte ihre Frucht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Liebe Bruder, sojemand untereuch irren wfirde von der Wahrheit, und jemand bekehrete ihn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'der soil wissen, daß, wer den Sunder bekehret hat von dem Irrtum seines Weges, der hat einer Seele vom Tode geholfen und wird bedecken die Menge der Sünden. Der erste Brief des Petrus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, ein Apostel Jesu Christi: Den erwahlten Fremdlingen hin und her in Pontus, Galatien, Kappadozien, Asien und Bithynien,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'nach der Versehung Gottes des Vaters, durch die Heiligung des Geistes, zum Gehorsam und zur Besprengung des Blutes Jesu Christi. Gott gebe euch viel Gnade und Frieden!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gelobet sei Gott und der Vater unsers Herrn Jesu Christi, der uns nach seiner groften Barmherzigkeit wiedergeboren hat zu einer lebendigen Hoffnung durch die Auferstehung Jesu Christi von den Toten');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'zu einem unverganglichen und unbefleckten und unverwelklichen Erbe, das behalten wird im Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'euch, die ihr aus Gottes Macht durch den Glauben bewahret werdet zur Seligkeit, welche zubereitet ist, daß sie offenbar werde zu der letzten Zeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'in welcher ihr euch freuen werdet, die ihr jetzt eine kleine Zeit (wo es sein soil) traurig seid in mancherlei Anfechtungen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'auf daß euer Glaube rechtschaffen und viel kostlicher erfunden werde denn das vergangliche Gold, das durchs Feuer bewahret wird, zu Lobe, Preis und Ehren, wenn nun offenbaret wird Jesus Christus,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'welchen ihr nicht gesehen und doch liebhabt und nun an ihn glaubet, wiewohl ihr ihn nicht sehet; so werdet ihr euch freuen mit unaussprechlicher und herrlicher Freude,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'und das Ende eures Glaubens davonbringen, namlich der Seelen Seligkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Nach welcher Seligkeit haben gesucht und geforschet die Propheten, die von der zukunftigen Gnade auf euch geweissaget haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'und haben geforschet, auf welche und welcherlei Zeit deutete der Geist Christi, der in ihnen war, und zuvor bezeuget hat die Leiden, die in Christo sind, und die Herrlichkeit danach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'welchen es offenbaret ist. Denn sie haben\'s nicht sich selbst, sondern uns dargetan, welches euch nun verkundiget ist durch die, so euch das Evangelium verkundiget haben, durch den Heiligen Geist vom Himmel gesandt, welches auch die Engel gelustet zu schauen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Darum so begurtet die Lenden eures Gemutes, seid nuchtern und setzet eure Hoffnung ganz auf die Gnade, die euch angeboten wird durch die Offenbarung Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'als gehorsame Kinder; und stellet euch nicht gleich wie vorhin, da ihr in Unwissenheit nach den Lusten lebetet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'sondern nach dem, der euch berufen hat und heilig ist, seid auch ihr heilig in allem eurem Wandel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Denn es stehet geschrieben: Ihr sollt heilig sein; denn ich bin heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Und sintemal ihr den zum Vater anrufet, der ohne Ansehen der Person richtet nach eines jeglichen Werk, so fuhret euren Wandel, solange ihr hier wallet, mit Furcht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'und wisset, dafi ihr nicht mit verganglichem Silber Oder Gold erloset seid von eurem eitlen Wandel nach vaterlicher Weise,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'sondern mit dem teuren Blut Christi, als eines unschuldigen und unbefleckten Lammes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'der zwar zuvor versehen ist, ehe der Welt Grund gelegt ward, aber offenbaret zu den letzten Zeiten um euretwillen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'die ihr durch ihn glaubet an Gott, der ihn auferwecket hat von den Toten und ihm die Herrlichkeit gegeben, auf daß ihr Glauben und Hoffnung zu Gott haben mochtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Und machet keusch eure Seelen im Gehorsam der Wahrheit durch den Geist zu ungefarbter Bruderliebe und habt euch untereinander brunstig lieb aus reinem Herzen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'als die da wiederum geboren sind, nicht aus verganglichem, sondern aus unverganglichem Samen, namlich aus dem lebendigen Wort Gottes, das da ewiglich bleibet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Denn alles Fleisch ist wie Gras und aile Herrlichkeit der Menschen wie des Grases Blume. Das Gras ist verdorret, und die Blume abgefailen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'aber des Herrn Wort bleibet in Ewigkeit. Das ist das Wort, welches unter euch verkundiget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'So leget nun ab aile Bosheit und alien Betrug und Heuchelei und Neid und alles Afterreden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'und seid gierig nach der vernunftigen lautern Milch als die jetzt gebornen Kindlein, auf daß ihr durch dieselbige zunehmet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'so ihr anders geschmecket habt, daß der Herr freundlich ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'zu welchem ihr kommen seid als zu dem lebendigen Stein, der von den Menschen verworfen, aber bei Gott ist er auserwahlet und kdstlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Und auch ihr, als die lebendigen Steine, bauet euch zum geistlichen Hause und zum heiligen Priestertum, zu opfern geistliche Opfer, die Gott angenehm sind durch Jesum Christum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Darum stehet in der Schrift: Siehe da, ich lege einen auserwahlten, kostlichen Eckstein in Zion; und wer an ihn glaubet, der soil nicht zuschanden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Euch nun, die ihr glaubet, ist er kostlich; den Unglaubigen aber ist der Stein, den die Bauleute verworfen haben, und zum Eckstein worden ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'ein Stein des Anstoftens und ein Fels des Argernisses, die sich stoften an dem Wort und glauben nicht daran, darauf sie gesetzt sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ihr aber seid das auserwahlte Geschlecht, das konigliche Priestertum, das heilige Volk, das Volk des Eigentums, daß ihr verkundigen sollt die Tugenden des, der euch berufen hat von der Finsternis zu seinem wunderbaren Licht,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'die ihrweiland nichtein Volk waret, nun aber Gottes Volk seid, und weiland nicht in Gnaden waret, nun aber in Gnaden seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Liebe Bruder, ich ermahne euch, als die Fremdlinge und Pilgrime, enthaltet euch von fleischlichen Lusten, welche wider die Seele streiten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'und führet einen guten Wandel unter den FHeiden, auf daß die, so von euch afterreden als von Ubeltatern, eure guten Werke sehen und Gott preisen, wenn es nun an den Tag kommen wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Seid untertan aller menschlichen Ordnung um des Herm willen, es sei dem Kdnige, als dem Obersten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Oder den FHauptleuten, als den Gesandten von ihm zur Rache uber die Ubeltater und zu Lobe den Frommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Denn das ist der Wille Gottes, daß ihr mit Wohltun verstopfet die Unwissenheit der torichten Menschen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'als die Freien, und nicht als hattet ihr die Freiheit zum Deckel der Bosheit, sondern als die Knechte Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Tut Ehre jedermann! Habt die Bruder lieb! Furchtet Gott! Ehret den Konig!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Ihr Knechte, seid untertan mit aller Furchtden Herren, nicht allein den gutigen und gelinden, sondern auch den wunderlichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Denn das ist Gnade, so jemand um des Gewissens willen zu Gott das Ubel vertragt und leidet das Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Denn was ist das fur ein Ruhm, so ihr um Missetat willen Streiche leidet? Aber wenn ihr um Wohltat willen leidet und erduldet, das ist Gnade bei Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Denn dazu seid ihr berufen, sintemal auch Christus gelitten hat fur uns und uns ein Vorbild gelassen, daß ihr sollt nachfolgen seinen Fußtapfen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'welcher keine Sünde getan hat, ist auch kein Betrug in seinem Munde erfunden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'welcher nicht wiederschalt, da er gescholten ward, nicht drauete, da er lift; er stellete es aber dem heim, der da recht richtet;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'welcher unsere Sunden selbst geopfert hat an seinem Leibe auf dem Holz, auf daßwir, der Sunde abgestorben, der Gerechtigkeit leben; durch welches Wunden ihr seid heil worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Denn ihr waret wie die irrenden Schafe; aber ihr seid nun bekehret zu dem Hirten und Bischof eurer Seelen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Desselbigengleichen sollen die Weiber ihren Mannern untertan sein, auf daß auch die, so nicht glauben an das Wort, durch der Weiber Wandel ohne Wort gewonnen werden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'wenn sie ansehen euren keuschen Wandel in der Furcht;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'welcher Schmuck soil nicht auswendig sein mit Haarflechten und Goldumhangen Oder Kleideranlegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'sondern der verborgene Mensch des Flerzens unverrückt mit sanftem und stillem Geiste; das ist kostlich vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Denn also haben sich auch vorzeiten die heiligen Weiber geschmuckt, die ihre Hoffnung auf Gott setzten und ihren Mannern untertan waren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'wie die Sara Abraham gehorsam war und hieß ihn Herr, welcher Tdchter ihr worden seid, so ihr wohl tut und nicht so schuchtern seid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Desselbigengleichen, ihr Manner, wohnet bei ihnen mit Vernunft und gebet dem weiblichen als dem schwachsten Werkzeuge seine Ehre, als auch Miterben der Gnade des Lebens, auf daß eure Gebete nicht verhindert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Endlich aber seid allesamt gleichgesinnet, mitleidig, bruderlich, barmherzig, freundlich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Vergeltet nicht Boses mit Bosem Oder Scheltwort mit Scheltwort, sondern dagegen segnet und wisset, daß ihr dazu berufen seid, daß ihr den Segen erbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Denn wer leben will und gute Tage sehen, der schweige seine Zunge, daß sie nichts Boses rede, und seine Lippen, daß sie nicht trugen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'er wende sich vom Bosen und tue Gutes; er suche Frieden und jage ihm nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Denn die Augen des Herm sehen auf die Gerechten und seine Ohren auf ihr Gebet; das Angesicht aber des Herm siehet auf die, so Boses tun.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Und wer ist, der euch schaden konnte, so ihr dem Guten nachkommet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Und ob ihr auch leidet um Gerechtigkeit willen, so seid ihr doch selig. Furchtet euch aber vor ihrem Trotzen nicht und erschrecket nicht!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Heiligetaber Gott den Herm in euren Herzen. Seid aber allezeit bereit zur Verantwortung jedermann, der Grund fordert der Hoffnung, die in euch ist,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'und das mit Sanftmutigkeit und Furcht; und habt ein gut Gewissen, auf daß die, so von euch afterreden als von Ubeltatern, zuschanden werden, daß sie geschmahet haben euren guten Wandel in Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Denn es ist besser, so es Gottes Wille ist, daß ihr von Wohltat wegen leidet denn von Ubeltat wegen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'sintemal auch Christus einmal fur unsere Sunden gelitten hat, der Gerechte fur die Ungerechten, auf daß er uns Gott opferte; und ist getotet nach dem Fleisch, aber lebendig gemacht nach dem Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'In demselbigen ist er auch hingegangen und hat geprediget den Geistern im Gefangnis,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'die etwa nicht glaubeten, da Gott einstmals harrete und Geduld hatte zu den Zeiten Noahs, da man die Arche zurustete, in welcher wenig, das ist, acht Seelen, behalten wurden durchs Wasser,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'welches nun auch uns selig macht in der Taufe, die durch jenes bedeutet ist, nicht das Abtun des Unflats am Fleisch, sondern der Bund eines guten Gewissens mit Gott durch die Auferstehung Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'welcher ist zur Rechten Gottes in den Himmel gefahren, und sind ihm untertan die Engel und die Gewaltigen und die Krafte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Weil nun Christus im Fleisch fur uns gelitten hat, so wappnet euch auch mit demselbigen Sinn: denn wer am Fleisch leidet, der horet auf von Sünden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'daiß er hinfort, was noch hinterstelliger Zeit im Fleisch ist, nicht der Menschen Lüsten, sondern dem Willen Gottes lebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Denn es ist genug, daß wir die vergangene Zeit des Lebens zugebracht haben nach heidnischem Willen, da wirwandelten in Unzucht, Lüsten, Trunkenheit, Fresserei, Sauferei und greulichen Abgottereien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Das befremdet sie, dafi ihr nicht mit ihnen laufet in dasselbige wüste, unordentliche Wesen, und lastern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'welche werden Rechenschaft geben dem, der bereit ist, zu richten die Lebendigen und die Toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Denn dazu ist auch den Toten das Evangelium verkundiget, auf dafi sie gerichtet werden nach dem Menschen am Fleisch, aber im Geist Gott leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Es ist aber nahe kommen das Ende aller Dinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'So seid nun mafüg und nuchtern zum Gebet. Vor alien Dingen aber habt untereinander eine brunstige Liebe; denn die Liebe decket auch der Sünden Menge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Seid gastfrei untereinander ohne Murmeln!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Und dienet einander, ein jeglicher mit der Gabe, die er empfangen hat, als die guten Haushalter der mancherlei Gnade Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'So jemand redet, dafi er\'s rede als Gottes Wort; so jemand ein Amt hat, dafi er\'s tue als aus dem Vermogen, das Gott darreichet, auf daß in alien Dingen Gott gepreiset werde durch Jesum Christum, welchem sei Ehre und Gewalt von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Ihr Lieben, lasset euch die Hitze, so euch begegnet, nicht befremden (die euch widerfahret, daü ihr versucht werdet), als widerfuhre euch etwas Seltsames,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'sondern freuet euch, dafi ihr mit Christo leidet, auf daü ihr auch zu der Zeit der Offenbarung seiner Herrlichkeit Freude und Wonne haben moget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Selig seid ihr, wenn ihr geschmahet werdet uber dem Namen Christi; denn der Geist, der ein Geist der Herrlichkeit und Gottes ist, ruhet auf euch. Bei ihnen ist er verlastert, aber bei euch ist er gepreiset.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Niemand aber untereuch leide als ein Morder Oder Dieb Oder Ubeltater Oder der in ein fremd Amt greifet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Leidet er aber als ein Christ, so schame er sich nicht; er ehre aber Gott in solchem Fall.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Denn es ist Zeit, daü anfange das Gericht an dem Hause Gottes. So aber zuerst an uns, was will\'s fur ein Ende werden mit denen, die dem Evangelium Gottes nicht glauben?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Und so der Gerechte kaum erhalten wird, wo will der Gottiose und Sunder erscheinen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Darum, welche da leiden nach Gottes Willen, die sollen ihm ihre Seelen befehlen als dem treuen Schopfer in guten Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Die Altesten, so unter euch sind, ermahne ich, der Mitalteste und Zeuge der Leiden, die in Christo sind, und teilhaftiq der Herrlichkeit, die offenbaret werden soil:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Weidet die Herde Christi, so euch befohlen ist, und sehetwohl zu, nicht gezwungen, sondern williglich, nicht urn schandlichen Gewinns willen, sondern von Herzensgrund,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'nicht als die uber das Volk herrschen, sondern werdet Vorbilder der Herde;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'so werdet ihr, wenn erscheinen wird der Erzhirte, die unverwelkliche Krone der Ehren empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Desselbigengleichen, ihr Jungen, seid untertan den Altesten. Allesamt seid untereinander untertan und haltet test an der Demut; denn Gott widerstehet den Hoffartigen, aber den Demütigen gibt er Gnade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'So demutiget euch nun unter die gewaltige Hand Gottes, daß er euch erhohe zu seiner Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Alle eure Sorge werfet auf ihn; denn er sorget fur euch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Seid nuchtern und wachet; denn euer Widersacher, der Teufel, gehet umher wie ein brullender Lowe und suchet, welchen er verschlinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Dem widerstehet fest im Glauben und wisset, daß eben dieselbigen Leiden uber eure Bruder in der Welt gehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Der Gott aber aller Gnade, der uns berufen hat zu seiner ewigen Herrlichkeit in Christo Jesu, derselbige wird euch, die ihr eine kleine Zeit leidet, vollbereiten, starken, kraftigen, grunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Demselbigen sei Ehre und Macht von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Durch euren treuen Bruder Silvanus (als ich achte) habe ich euch ein wenig geschrieben, zu ermahnen und zu bezeugen, daü das die rechte Gnade Gottes ist, darinnen ihr stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Es gruften euch, die samt euch auserwahlt sind zu Babylon, und mein Sohn Markus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Gruf Jet euch untereinander mit dem Kuft der Liebe. Friede sei mit alien, die in Christo Jesu sind! Amen. Der zweite Brief des Petrus');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petrus, ein Knecht und Apostel Jesu Christi: Denen, die mit uns eben denselbigen teuren Glauben überkommen haben in der Gerechtigkeit, die unser Gott gibt und der Heiland Jesus Christus.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Gott gebe euch viel Gnade und Frieden durch die Erkenntnis Gottes und Jesu Christi, unsers Herrn!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Nachdem allerlei seiner gottlichen Kraft (was zum Leben und gottlichen Wandel dienet) uns geschenket ist durch die Erkenntnis des, der uns berufen hat durch seine Herrlichkeit und Tugend,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'durch welche uns die teuren und allergroßten Verheiliungen geschenket sind, namlich dafi ihr durch dasselbige teilhaftig werdet der gottlichen Natur, so ihr fliehet die vergangliche Lust der Welt:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'so wendet alien euren Fleiß daran und reichet dar in eurem Glauben Tugend und in der Tugend Bescheidenheit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'und in der Bescheidenheit Maßigkeit und in der Mafügkeit Geduld und in der Geduld Gottseligkeit');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'und in der Gottseligkeit bruderliche Liebe und in der bruderlichen Liebe gemeine Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Denn wo solches reichlich bei euch ist, wird\'s euch nicht faul noch unfruchtbar sein lassen in der Erkenntis unsers Herrn Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Welcher aber solches nicht hat, der ist blind und tappet mit der Hand und vergifit der Reinigung seiner vorigen Sunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Darum, liebe Bruder, tutdesto mehr Fleifi, eure Berufung und Erwahlung festzumachen. Denn wo ihr solches tut, werdet ihr nicht straucheln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Und alsowird euch reichlich dargereicht werden der Eingang zu dem ewigen Reich unsers Herrn und Heilandes Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Darum will ich\'s nicht lassen, euch allezeit solches zu erinnern, wiewohl ihr\'s wisset und gestarkt seid in der gegenwartigen Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Denn ich achte es billig sein, solange ich in dieser Hütte bin, euch zu erwecken und zu erinnern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Denn ich weifi, daß ich meine Hütte bald ablegen muli, wie mir denn auch unser Herr Jesus Christus eroffnet hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ich will aber Fleili tun, daß ihr allenthalben habet nach meinem Abschied, solches im Gedachtnis zu halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Denn wir haben nicht den klugen Fabein gefolget, da wir euch kundgetan haben die Kraft und Zukunft unsers Herrn Jesu Christi, sondern wir haben seine Herrlichkeit selber gesehen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'da er empfing von Gott dem Vater Ehre und Preis durch eine Stimme, die zu ihm geschah von der grolien Herrlichkeit dermaüen: Dies ist mein lieber Sohn, an dem ich Wohlgefallen habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Und diese Stimme haben wir gehoret vom Himmel gebracht, da wir mit ihm waren auf dem heiligen Berge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Wir haben ein festes prophetisches Wort, und ihr tut wohl, daß ihr darauf achtet als auf ein Licht, das da scheinet in einem dunkeln Ort, bis der Tag anbreche, und der Morgenstern aufgehe in euren Herzen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Und das sollt ihr fur das erste wissen, dafi keine Weissagung in der Schrift geschieht aus eigener Auslegung;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'denn es ist noch nie keine Weissagung aus menschlichem Willen hervorgebracht; sondern die heiligen Menschen Gottes haben geredet, getrieben von dem Heiligen Geist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Es waren aber auch falsche Propheten unter dem Volk, wie auch unter euch sein werden falsche Lehrer, die neben einfuhren werden verderbliche Sekten und verleugnen den Herrn, dersie erkauft hat, und werden uber sich selbst führen eine schnelle Verdammnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Und viele werden nachfolgen ihrem Verderben; durch welche wird der Weg der Wahrheit verlastert werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Und durch Geiz mit erdichteten Worten werden sie an euch hantieren; von welchen das Urteil von lange her nicht saumig ist, und ihre Verdammnis schlaft nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Denn so Gott der Engel, die gesundiget haben, nicht verschonet hat, sondern hat sie mit Ketten der Finsternis zur Holle verstoi Len und ubergeben, dafi sie zum Gerichte behalten werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'und hat nicht verschonet der vorigen Welt, sondern bewahrete Noah, den Prediger der Gerechtigkeit, selbachte und fuhrete die Sintflut uber die Welt der Gottlosen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'und hat die Stadte Sodom und Gomorra zu Asche gemacht, umgekehret und verdammt, damit ein Exempel gesetzt den Gottlosen, die hernach kommen wurden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'und hat erloset den gerechten Lot, welchem die schandlichen Leute alles Leid taten mit ihrem unzüchtigen Wandel;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'denn dieweil er gerecht war und unter ihnen wohnete, daß er\'s sehen und horen mulite, qualten sie die gerechte Seele von Tag zu Tage mit ihren ungerechten Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Der Herr weü J die Gottseligen aus der Versuchung zu erlosen, die Ungerechten aber zu behalten zum Tage des Gerichtes, zu peinigen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'allermeist aber die, so da wandeln nach dem Fleisch in der unreinen Lust und die Herrschaft verachten, turstig, eigensinnig, nicht erzittern, die Majestaten zu lastern,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'so doch die Engel, die groliere Starke und Macht haben, nicht ertragen das lasterliche Gericht wider sich vom Herrn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Aber sie sind wie die unvemünftigen Tiere, die von Natur dazu geboren sind, dafi sie gefangen und geschlachtet werden, lastern, da sie nichts von wissen, und werden in ihrem verderblichen Wesen umkommen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'und den Lohn der Ungerechtigkeit davonbringen. Sie achten fur Wollust das zeitliche Wohlleben; sie sind Schande und Laster, prangen von euren Almosen, prassen mit dem Euren,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'haben Augen voll Ehebruchs, lassen sich die Sünde nichtwehren, locken an sich die leichtfertigen Seelen, haben ein Herz, durchtrieben mit Geiz, verfluchte Leute,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'verlassen den richtigen Weg und gehen irre und folgen nach dem Wege Bileams, des Sohns Bosors, welchem geliebete der Lohn der Ungerechtigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'hatte aber eine Strafe seiner Ubertretung, namlich das stumme lastbare Tier redete mit Menschenstimme und wehrete des Propheten Torheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Das sind Brunnen ohne Wasser und Wolken, vom Windwirbel umgetrieben; welchen behalten ist eine dunkle Finsternis in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Denn sie reden stolze Worte, da nichts hinter ist, und reizen durch Unzucht zur fleischlichen Lust diejenigen, die recht entronnen waren und nun im Irrtum wandeln,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'und verheißen ihnen Freiheit, so sie selbst Knechte des Verderbens sind. Denn von welchem jemand überwunden ist, des Knecht ist er worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Denn so sie entflohen sind dem Unflat der Welt durch die Erkenntnis des Herrn und Heilandes Jesu Christi, werden aber wiederum in denselbigen geflochten und überwunden, ist mit ihnen das Letzte arger worden denn das Erste.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Denn es ware ihnen besser, daß sie den Weg der Gerechtigkeit nicht erkannt batten, denn daß sie ihn erkennen und sich kehren von dem heiligen Gebot, das ihnen gegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Es ist ihnen widerfahren das wahre Sprichwort: Der Hund frisset wieder, was er gespeiet hat, und: Die Sau walzet sich nach der Schwemme wieder im Kot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Dies ist die andere Epistel, die ich euch schreibe, ihr Lieben, in welcher ich erwecke und erinnere euren lautem Sinn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'daß ihr gedenket an die Worte, die euch zuvor gesagt sind von den heiligen Propheten, und an unser Gebot, die wir sind Apostel des Herrn und Heilandes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Und wisset das aufs erste, daß in den letzten Tagen kommen werden Spotter, die nach ihren eigenen Lusten wandeln');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'und sagen: Wo ist die Verheißung seiner Zukunft? Denn nachdem die Vater entschlafen sind, bleibt es alles, wie es von Anfang der Kreatur gewesen ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Aber mutwillens wollen sie nicht wissen, daß der Himmel vorzeiten auch war, dazu die Erde aus Wasser und im Wasser bestanden durch Gottes Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Dennoch ward zu der Zeit die Welt durch dieselbigen mit der Sintflut verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Also auch der Himmel jetzt und die Erde werden durch sein Wort gesparet, daß sie zum Feuer behalten werden am Tage des Gerichts und Verdammnis der gottlosen Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Eines aber sei euch unverhalten, ihr Lieben, daß ein Tag vor dem Herrn ist wie tausend Jahre und tausend Jahre wie ein Tag.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Der Herr verzieht nicht die Verheißung, wie es etliche fur einen Verzug achten, sondern er hat Geduld mit uns und will nicht, daß jemand verloren werde, sondern daß sich jedermann zur Buße kehre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Es wird aber des Herrn Tag kommen als ein Dieb in der Nacht, in welchem die Himmel zergehen werden mit großem Krachen, die Elemente aber werden vor Hitze schmelzen, und die Erde und die Werke, die drinnen sind, werden verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'So nun das alles soil zergehen, wie sollt ihr denn geschickt sein mit heiligem Wandel und gottseligem Wesen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'daß ihr wartet und eiletzu der Zukunft des Tages des Herrn, in welchem die Himmel vom Feuer zergehen, und die Elemente vor Hitze zerschmelzen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Wir warten aber eines neuen Himmels und einer neuen Erde nach seiner Verheißung, in welchen Gerechtigkeit wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Darum, meine Lieben, dieweil ihr darauf warten sollet, so tut Fleiß, daß ihr vor ihm unbefleckt und unstraflich im Frieden erfunden werdet.]');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Und die Geduld unsers Herrn achtet fur eure Seligkeit, als auch unser lieber Bruder Paulus nach der Weisheit, die ihm gegeben ist, euch geschrieben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Wie er auch in alien Briefen davon redet, in welchen sind etliche Dinge schwer zu verstehen, welche verwirren die Ungelehrigen und Leichtfertigen wie auch die andern Schriften zu ihrer eigenen Verdammnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ihr aber, meine Lieben, weil ihr das zuvor wisset, so verwahret euch, daß ihr nicht durch Irrtum der ruchlosen Leute samt ihnen verfuhret werdet und entfallet aus eurer eigenen Festung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Wachset aber in der Gnade und Erkenntnis unsers Herrn und Heilandes Jesu Christi. Demselbigen sei Ehre nun und zu ewigen Zeiten! Amen. Der erste Brief des Johannes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Das da von Anfang war, das wir gehoret haben, das wir gesehen haben mit unsern Augen, das wir beschauet haben, und unsere Hande betastet haben, vom Wort des Lebens');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(und das Leben ist erschienen, und wir haben gesehen und zeugen und verkundigen euch das Leben, das ewig ist, welches war bei dem Vater und ist uns erschienen);');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'was wir gesehen und gehoret haben: das verkundigen wir euch, auf daß auch ihr mit uns Gemeinschaft habet, und unsere Gemeinschaft sei mit dem Vater und mit Sohn, Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Und solches schreiben wir euch, auf daß eure Freude vollig sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Und das ist die Verkundigung, die wir von ihm gehoret haben und euch verkundigen, dafi Gott ein Licht ist, und in ihm keine Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'So wir sagen, daß wir Gemeinschaft mit ihm haben, und wandeln in Finsternis, so lugen wir und tun nicht die Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'So wir aber im Licht wandeln, wie er im Lichte ist, so haben wir Gemeinschaft untereinander, und das Blut Jesu Christi, seines Sohnes, macht uns rein von aller Sünde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'So wir sagen, wir haben keine Sünde, so verfuhren wir uns selbst, und die Wahrheit ist nicht in uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'So wir aber unsere Sünde bekennen, so ist er treu und gerecht, daß er uns die Sünde vergibt und reiniget uns von aller Untugend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'So wir sagen, wir haben nicht gesündiget, so machen wir ihn zum Lügner, und sein Wort ist nicht in uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meine Kindlein, solches schreibe ich euch, auf daß ihr nicht sundiget. Und ob jemand sündiget, so haben wir einen Fürsprecher bei dem Vater, Jesum Christum, der gerecht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Und derselbige ist die Versohnung für unsere Sünde, nicht allein aber für die unsere, sondern auch für die der ganzen Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Und an dem merken wir, daß wir ihn kennen, so wir seine Gebote halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Wer da sagt: Ich kenne ihn, und halt seine Gebote nicht, der ist ein Lügner, und in solchem ist keine Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Wer aber sein Wort halt, in solchem ist wahrlich die Liebe Gottes vollkommen. Daran erkennen wir, daß wir in ihm sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Wer da sagt, daß er in ihm bleibet, der soil auch wandeln, gleichwie er gewandelt hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Brüder, ich schreibe euch nicht ein neu Gebot, sondern das alte Gebot, das ihr habt von Anfang gehabt. Das alte Gebot ist das Wort, das ihr von Anfang gehoret habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Wiederum ein neu Gebot schreibe ich euch, das da wahrhaftig ist bei ihm und bei euch; denn die Finsternis ist vergangen, und das wahre Licht scheinet jetzt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Wer da sagt, er sei im Licht, und hasset seinen Bruder, der ist noch in Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Wer seinen Bruder liebet, der bleibet Licht, und ist kein Argernis bei ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Wer aber seinen Bruder hasset, der ist in Finsternis und wandelt in Finsternis und weift nicht, wo er hingehet; denn die Finsternis hat seine Augen verblendet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Liebe Kindlein, ich schreibe euch, daß euch die Sünden vergeben werden durch seinen Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ich schreibe euch Vatern; denn ihr kennet den, der von Anfang ist. Ich schreibe euch Junglingen; denn ihr habt den Bosewicht überwunden. Ich schreibe euch Kindern; denn ihr kennet den Vater.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ich habe euch Vatern geschrieben, daß ihr den kennet, der von Anfang ist. Ich habe euch Junglingen geschrieben, daß ihr stark seid, und das Wort Gottes bei euch bleibet, und den Bosewicht überwunden habt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Habt nicht lieb die Welt, noch was in der Welt ist. So jemand die Welt liebhat, in dem ist nicht die Liebe des Vaters.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Denn alles, was in der Welt ist (namlich des Fleisches Lust und der Augen Lust und hoffartiges Leben), ist nicht vom Vater, sondern von der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Und die Welt vergehet mit ihrer Lust; wer aber den Willen Gottes tut, der bleibet in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Kinder, es ist die letzte Stunde; und wie ihr gehoret habt, daß der Widerchrist kommt, und nun sind viel Widerchristen worden; daher erkennen wir, daß die letzte Stunde ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Sie sind von uns ausgegangen, aber sie waren nicht von uns. Denn wo sie von uns gewesen waren, so waren sie ja bei uns geblieben; aber auf daß sie offenbar würden, daß sie nicht alle von uns sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Und ihr habt die Salbung von dem, der heilig ist; und wisset alles.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Ich habe euch nicht geschrieben, als wüfttet ihr die Wahrheit nicht, sondern ihr wisset sie und wisset, daß keine Luge aus der Wahrheit kommt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Wer ist ein Lügner, ohne der da leugnet, daß Jesus der Christus sei? Das ist der Widerchrist, der den Vater und den Sohn leugnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Wer den Sohn leugnet, der hat auch den Vater nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Was ihr nun gehoret habt von Anfang, das bleibe bei euch. So bei euch bleibet, was ihr von Anfang gehoret habt, so werdet ihr auch bei dem Sohn und Vater bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Und das ist die Verheiftung, die er uns verheiften hat: das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Solches habe ich euch geschrieben von denen, die euch verfuhren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Und die Salbung, die ihr von ihm empfangen habt, bleibet bei euch, und durfet nicht, daß euch jemand lehre, sondern wie euch die Salbung allerlei lehret, so ist\'s wahr, und ist keine Luge; und wie sie euch gelehret hat, so bleibet bei demselbigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Und nun, Kindlein, bleibet bei ihm, auf daß, wenn er offenbaret wird, daß wir Freudigkeit haben und nicht zuschanden werden vor ihm in seiner Zukunft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'So ihrwisset, daß er gerecht ist, so erkennet auch, daß, wer recht tut, der ist von ihm geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Sehet, welch eine Liebe hat uns der Vater erzeiget, daß wir Gottes Kinder sollen heilien! Darum kennet euch die Welt nicht, denn sie kennet ihn nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Meine Lieben, wirsind nun Gottes Kinder, und ist noch nicht erschienen, was wir sein werden. Wir wissen aber, wenn es erscheinen wird, daß wir ihm gleich sein werden; denn wir werden ihn sehen, wie er ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Und ein jeglicher, der solche Hoffnung hat zu ihm, der reiniget sich, gleichwie er auch rein ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Wer Sunde tut, der tut auch Unrecht; und die Sünde ist das Unrecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Und ihr wisset, daß er ist erschienen, auf daß er unsere Sunden wegnehme; und ist keine Sünde in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Wer in ihm bleibet, der sundiget nicht; wer da sundiget, der hat ihn nicht gesehen noch erkannt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kindlein, lasset euch niemand verfuhren! Wer recht tut, der ist gerecht, gleichwie er gerecht ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Wer Sünde tut, der ist vom Teufel; denn der Teufel sundiget von Anfang. Dazu ist erschienen der Sohn Gottes, daß er die Werke des Teufels zerstore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Wer aus Gott geboren ist, der tut nicht Sunde; denn sein Same bleibet bei ihm, und kann nicht sündigen; denn er ist von Gott geboren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Daran wird\'s offenbar, welche die Kinder Gottes und die Kinder des Teufels sind. Wer nicht recht tut, der ist nicht von Gott, und wer nicht seinen Bruder liebhat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Denn das ist die Botschaft, die ihr gehoret habt von Anfang, daß wir uns untereinander lieben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nicht wie Kain, der von dem Argen war und erwurgete seinen Bruder. Und warum erwurgete er ihn? Dali seine Werke bose waren und seines Binders gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Verwundert euch nicht, meine Bruder, ob euch die Welt hasset!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Wir wissen, daß wir aus dem Tode in das Leben kommen sind; denn wir lieben die Bruder. Wer den Bruder nicht liebet, der bleibet im Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Wer seinen Bruder hasset, der ist ein Totschlager; und ihrwisset, daß ein Totschlager nicht hat das ewige Leben bei ihm bleibend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Daran haben wir erkannt die Liebe, daß er sein Leben fur uns gelassen hat; und wir sollen auch das Leben fur die Bruder lassen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Wenn aber jemand dieser Welt Guter hat und siehet seinen Bruder darben und schlielit sein Herz vor ihm zu: wie bleibet die Liebe Gottes bei ihm?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Meine Kindlein, lasset uns nicht lieben mit Worten noch mit der Zunge, sondern mit der Tat und mit der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Daran erkennen wir, daß wir aus der Wahrheit sind, und konnen unser Herz vor ihm stillen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'dati, so uns unser Herz verdammt, daß Gott grolier ist denn unser Herz und erkennet alle Dinge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Ihr Lieben, so uns unser Herz nicht verdammt, so haben wir eine Freudigkeit zu Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'und was wir bitten, werden wir von ihm nehmen; denn wir halten seine Gebote und tun, was vor ihm gefallig ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Und das ist sein Gebot, daß wir glauben an den Namen seines Sohnes Jesu Christi und lieben uns untereinander, wie er uns ein Gebot gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Und wer seine Gebote halt, der bleibet in ihm und er in ihm. Und daran erkennen wir, daß er in uns bleibet: an dem Geist, den er uns gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Ihr Lieben, glaubet nicht einem jeglichen Geist, sondern prufet die Geister, ob sie von Gott sind; denn es sind viel falsche Propheten ausgegangen in die Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Daran sollt ihr den Geist Gottes erkennen: Ein jeglicher Geist, der da bekennet, daß Jesus Christus ist in das Fleisch kommen, der ist von Gott;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'und ein jeglicher Geist, der da nicht bekennet, daß Jesus Christus ist in das Fleisch kommen, der ist nicht von Gott. Und das ist der Geist des Widerchrists, von welchem ihr habt gehoret, daß er kommen werde, und ist jetzt schon in der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Kindlein, ihrseid von Gott und habtjene überwunden; denn der in euch ist, ist grolier, denn der in der Welt ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Sie sind von der Welt; darum reden sie von der Welt, und die Welt horet sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Wir sind von Gott, und wer Gott erkennet, der horet uns; welcher nicht von Gott ist, der horet uns nicht. Daran erkennen wir den Geist der Wahrheit und den Geist des Irrtums.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Ihr Lieben, lasset uns untereinander liebhaben; denn die Liebe ist von Gott; und wer liebhat, der ist von Gott geboren und kennet Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Wer nicht liebhat, der kennet Gott nicht; denn Gott ist die Liebe:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Daran ist erschienen die Liebe Gottes gegen uns, daß Gott seinen eingebornen Sohn gesandt hat in die Welt, daß wir durch ihn leben sollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Darinnen stehet die Liebe, nicht daß wir Gott geliebet haben, sondern dad er uns geliebet hat und gesandt seinen Sohn zur Versohnung fur unsere Sünden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Ihr Lieben, hat uns Gottalso geliebet, sosollen wir uns auch untereinander lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Niemand hatßottjemals gesehen. So wir uns untereinander lieben, so bleibet Gott in uns, und seine Liebe ist vollig in uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Daran erkennen wir, daß wir in ihm bleiben und er in uns, dad er uns von seinem Geist gegeben hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Und wir haben gesehen und zeugen, dad der Vater den Sohn gesandt hat zum Heiland der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Welcher nun bekennet, dad Jesus Gottes Sohn ist, in dem bleibet Gott und er in Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Und wir haben erkannt und geglaubet die Liebe, die Gott zu uns hat. Gott ist die Liebe; und wer in der Liebe bleibet, der bleibet in Gott und Gott in ihm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Daran ist die Liebe vollig bei uns, auf dad wir eine Freudigkeit haben am Tage des Gerichts; denn gleichwie er ist, so sind auch wir in dieser Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Furcht ist nicht in der Liebe, sondern die vollige Liebe treibet die Furcht aus; denn die Furcht hat Pein. Wer sich aber furchtet, der ist nicht vollig in der Liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Lasset uns ihn lieben; denn er hat uns erst geliebet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'So jemand spricht: Ich liebe Gott, und hasset seinen Bruder, der ist ein Lugner; denn wer seinen Bruder nicht liebet, den er siehet, wie kann er Gott lieben, den er nicht siehet?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Und dies Gebot haben wir von ihm, dad, wer Gott liebet, dad der auch seinen Bruder liebe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Wer da glaubet, dad Jesus sei der Christus, der ist von Gott geboren. Und wer da liebet den, der ihn geboren hat, der liebet auch den, der von ihm geboren ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Daran erkennen wir, dad wir Gottes Kinder lieben, wenn wir Gott lieben und seine Gebote halten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Denn das ist die Liebe zu Gott, dad wir seine Gebote halten; und seine Gebote sind nicht schwer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Denn alles, was von Gott geboren ist, uberwindet die Welt; und unser Glaube ist der Sieg, der die Welt uberwunden hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Wer ist aber, der die Welt uberwindet ohne der da glaubet, dad Jesus Gottes Sohn ist?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Dieser ist\'s, der da kommt mit Wasser und Blut, Jesus Christus, nicht mit Wasser allein, sondern mit Wasser und Blut. Und der Geist ist\'s, der da zeuget, dad Geist Wahrheit ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Denn drei sind, die da zeugen im Himmel: der Vater, das Wort und der Heilige Geist; und diese drei sind eins.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Und drei sind, die da zeugen auf Erden: der Geist und das Wasser und das Blut; und die drei sind beisammen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'So wir der Menschen Zeugnis annehmen, so ist Gottes Zeugnis grafter; denn Gottes Zeugnis ist das, das er gezeuget hat von seinem Sohne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Wer da glaubet an den Sohn Gottes, der hat solch Zeugnis bei sich. Wer Gott nicht glaubet, der macht ihn zum Lugner; denn er glaubet nicht dem Zeugnis, das Gott zeuget von seinem Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Und das ist das Zeugnis, daß uns Gott das ewige Leben hat gegeben, und solches Leben ist in seinem Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wer den Sohn Gottes hat, der hat das Leben; wer den Sohn Gottes nicht hat, der hat das Leben nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Solches hab\' ich euch geschrieben, die ihr glaubet an den Namen des Sohnes Gottes, auf daß ihr wisset, daß ihr das ewige Leben habet, und daß ihr glaubet an den Namen des Sohnes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Und das ist die Freudigkeit, die wir haben zu ihm, daß, so wir etwas bitten nach seinem Willen, so horet er uns.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Und so wir wissen, daß er uns horet, was wir bitten, so wissen wir, daß wir die Bitten haben, die wir von ihm gebeten haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'So jemand siehet seinen Bruder sundigen, eine Sunde nicht zum Tode, der mag bitten; so wird er geben das Leben denen, die da sundigen nicht zum Tode. Es ist eine Sunde zum Tode; dafür sage ich nicht, daß jemand bitte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Alle Untugend ist Sunde; und es ist etliche Sunde nicht zum Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wir wissen, daß, wer von Gott geboren ist, der sundiget nicht, sondern wer von Gott geboren ist, der bewahret sich, und der Arge wird ihn nicht antasten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wir wissen, daß wir von Gott sind; und die ganze Welt liegt im Argen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Wir wissen aber, daß der Sohn Gottes kommen ist und hat uns einen Sinn gegeben, daß wir erkennen den Wahrhaftigen und sind in dem Wahrhaftigen, in seinem Sohn Jesu Christo. Dieser ist der wahrhaftige Gott und das ewige Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kindlein, hütet euch vor den Abgottern! Amen. Der zweite Brief des Johannes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Der Alteste: der auserwahlten Frau und ihren Kindern, die ich liebhabe in der Wahrheit, und nicht allein ich, sondern auch alle, die die Wahrheit erkannt haben,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'um der Wahrheit willen, die in uns bleibet und bei uns sein wird in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Gnade, Barmherzigkeit, Friede von Gottdem Vater und von dem Herrn Jesu Christo, dem Sohn des Vaters, in der Wahrheit und in der Liebe sei mit euch!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Ich bin sehr erfreuet, daß ich funden habe unter deinen Kindern, die in der Wahrheit wandeln, wie denn wir ein Gebot vom Vater empfangen haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Und nun bitte ich dich, Frau (nicht als ein neu Gebot schreibe ich dir, sondern das wir gehabt haben von Anfang), daß wir uns untereinander lieben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Und das ist die Liebe, daß wir wandeln nach seinem Gebot. Das ist das Gebot, wie ihr gehoret habt von Anfang, auf dati ihr daselbst innen wandelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Denn viel Verfuhrer sind in die Welt kommen, die nicht bekennen Jesum Christum, daß er in das Fleisch kommen ist. Dieser ist der Verfuhrer und der Widerchrist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Sehet euch vor, daß wir nicht verlieren, was wir erarbeitet haben, sondern vollen Lohn empfangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Wer ubertritt und bleibet nicht in der Lehre Christi, der hat keinen Gott; wer in der Lehre Christi bleibet, der hat beide, den Vater und den Sohn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'So jemand zu euch kommt und bringet diese Lehre nicht, den nehmet nicht zu Hause und gruliet ihn auch nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Denn wer ihn gruliet, der macht sich teilhaftig seiner bosen Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Ich hatte euch viel zu schreiben, aber ich wollte nicht mit Briefen und Tinte, sondern ich hoffe, zu euch zu kommen und mundlich mit euch zu reden, auf daß unsere Freude vollkommen sei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Es grülien dich die Kinder deiner Schwester, der Auserwahlten. Amen. Der dritte Brief des Johannes');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Der Alteste: Gajus, dem Lieben, den ich liebhabe in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Mein Lieber, ich wunsche in alien Stricken, daß dir\'s wohl gehe, und gesund seiest, wie es denn deiner Seele wohl gehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Ich bin aber sehr erfreuet, da die Bruder kamen und zeugeten von deiner Wahrheit, wie denn du wandelst in der Wahrheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Ich habe keine grofiere Freude denn die, daß ich hore meine Kinder in der Wahrheit wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Mein Lieber, du tust treulich, was du tust an den Brudern und Gasten,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'die von deiner Liebe gezeuget haben vor der Gemeinde; und du hast wohl getan, daß du sie abgefertiget hast wurdiglich vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Denn um seines Namens willen sind sie ausgezogen und haben von den Heiden nichts genommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'So sollen wir nun solche aufnehmen, auf daß wir der Wahrheit Gehilfen werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ich habe der Gemeinde geschrieben; aber Diotrephes, der unter ihnen will hochgehalten sein, nimmtuns nicht an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Darum, wenn ich komme, will ich ihn erinnern seiner Werke, die er tut, und plaudert mit bosen Worten wider uns und lasset sich an dem nicht genugen. Er selbst nimmt die Bruder nicht an und wehret denen, die es tun wollen, und stofiet sie aus der Gemeinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Mein Lieber, folge nicht nach dem Bosen, sondern dem Guten! Wer Gutes tut, der ist von Gott; wer Boses tut, der siehet Gott nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrius hat Zeugnisvon jedermann und von der Wahrheit selbst; und wir zeugen auch, und ihr wisset, daß unser Zeugnis wahr ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Ich hatte viel zu schreiben; aber ich wollte nicht mit Tinte und Feder an dich schreiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Ich hoffe aber, dich bald zu sehen, so wollen wir mundlich miteinander reden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Friede sei mit dir! Es grulien dich die Freunde. Grülie die Freunde mit Namen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, ein Knecht Jesu Christi, aber ein Bruder des Jakobus: den Berufenen, die da geheiliget sind in Gott dem Vater und behalten in Jesu Christo.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Gott gebe euch viel Barmherzigkeit und Frieden und Liebe!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Ihr Lieben, nachdem ich vorhatte, euch zu schreiben von unser aller Heil, hielt ich\'s fur notig, euch mit Schriften zu ermahnen, daß ihr ob dem Glauben kampfet, der einmal den Heiligen vorgegeben ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Denn es sind etliche Menschen nebeneingeschlichen, von denen vorzeiten geschrieben ist, zu solcher Strafe; die sind Gottlose und ziehen die Gnade unsers Gottes auf Mutwillen und verleugnen Gott und unsern Herrn Jesum Christum, den einigen Herrscher.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ich will euch aber erinnern, daß ihr wisset auf einmal dies, daß der Herr, da er dem Volk aus Agypten half, zum andernmal brachte er urn, die da nichtglaubten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Auch Engel, die ihr Fürstentum nicht behielten, sondern verlielien ihre Behausung, hat er behalten zum Gericht des grolien Tages mit ewigen Banden in Finsternis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Wie auch Sodom und Gomorra und die umliegenden Stadte, die gleicherweise wie diese ausgehuret haben und nach einem andern Fleisch gegangen sind, zum Exempel gesetzt sind und leiden des ewigen Feuers Pein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Desselbigengleichen sind auch diese Traumer, die das Fleisch beflecken, die Herrschaften aber verachten und die Majestaten lastern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'aber, der Erzengel, da er mit dem Teufel zankete und mit ihm redete uber den Leichnam Mose\'s, durfte er das Urteil der Lasterung nicht fallen, sondern sprach: Der Herr strafe dich!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Diese aber lastern, da sie nichts von wissen; was sie aber naturlich erkennen, darinnen verderben sie wie die unvernunftigen Here.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Wehe ihnen! denn sie gehen den Weg Kains und fallen in den Irrtum des Bileam urn Genielies willen und kommen urn in dem Aufruhr Korahs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Diese Unflater prassen von euren Almosen ohne Scheu, weiden sich selbst; sie sind Wolken ohne Wasser, von dem Winde umgetrieben, kahle, unfruchtbare Baume, zweimal erstorben und ausgewurzelt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'wilde Wellen des Meeres, die ihre eigene Schande ausschaumen, irrige Sterne, welchen behalten ist das Dunkel der Finsternis in Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Es hat aber auch von solchen geweissaget Henoch, der Siebente von Adam, und gesprochen: Siehe, der Herr kommt mit viel tausend Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Gericht zu halten uber alle und zu strafen alle ihre Gottlosen urn alle Werke ihres gottlosen Wandels, damit sie gottlos gewesen sind, und urn alie das Harte, das die gottlosen Sunder wider ihn geredet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Diese murmeln und klagen immerdar, die nach ihren Lüsten wandeln; und ihr Mund redet stolze Worte und achten das Ansehen der Person urn Nutzes willen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ihr aber, meine Lieben, erinnert euch der Worte, die zuvor gesagt sind von den Aposteln unsers Herrn Jesu Christi,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'da sie euch sagten, daß zu der letzten Zeit werden Spotter sein, die nach ihren eigenen Lüsten des gottlosen Wesens wandeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Diese sind, die da Rotten machen, Fleischliche, die da keinen Geist haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ihr aber, meine Lieben, erbauet euch auf euren allerheiligsten Glauben durch den Heiligen Geist und betet');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'und behaltet euch in der Liebe Gottes und wartet auf die Barmherzigkeit unsers Herrn Jesu Christi zum ewigen Leben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Und haltet diesen Unterschied, daß ihr euch etlicher erbarmet,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'etliche aber mit Furcht selig machet und rücket sie aus dem Feuer; und hasset den befleckten Rock des Fleisches.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Dem aber, der euch kann behuten ohne Fehl und stellen vor das Angesicht seiner Herrlichkeit unstraflich mit Freuden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'dem Gott, der allein weise ist, unserm Heilande, sei Ehre und Majestat und Gewalt und Macht nun und zu aller Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Dies ist die Offenbarung Jesu Christi, die ihm Gott gegeben hat, seinen Knechten zu zeigen, was in der Kürze geschehen soil; und hat sie gedeutet und gesandt durch seinen Engel zu seinem Knecht Johannes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'der bezeuget hat das Wort Gottes und das Zeugnis von Jesu Christo, was er gesehen hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Selig ist, der da lieset, und die da horen die Worte der Weissagung und behalten, was darinnen geschrieben ist; denn die Zeit ist nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes den sieben Gemeinden in Asien: Gnade sei mit euch und Friede von dem, der da ist, und der da war, und der da kommt, und von den sieben Geistern, die da sind vor seinem Stuhl,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'und von Jesu Christo, welcher ist der treue Zeuge und Erstgeborne von den Toten und ein Furst der Konige auf Erden; der uns geliebet hat und gewaschen von den Sunden mit seinem Blut');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'und hat uns zu Konigen und Priestern gemacht vor Gott und seinem Vater: demselbigen sei Ehre und Gewalt von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Siehe, er kommt mit den Wolken; und es werden ihn sehen alle Augen, und die ihn gestochen haben; und werden heulen alle Geschlechter der Erde. Ja, Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ich bin das A und das 0, der Anfang und das Ende, spricht der Herr, der da ist, und der da war, und der da kommt, der Allmachtige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ich, Johannes, der auch euer Bruder und Mitgenosse an der Trubsal ist und am Reich und an der Geduld Jesu Christi, war auf der Insel, die da heifit Patmos, urn des Wortes Gottes willen und des Zeugnisses Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Ich war im Geist an des Herrn Tag und horete hinter mir eine große Stimme als einer Posaune,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'die sprach: Ich bin das A und das 0, der Erste und der Letzte; und was du siehest, das schreibe in ein Buch und sende es zu den Gemeinden in Asien, gen Ephesus und gen Smyrna und gen Pergamus und gen Thyatira und gen Sardes und gen Philadelphia und gen Laodicea.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Und ich wandte mich urn, zu sehen nach der Stimme, die mit mir redete. Und als ich mich wandte, sah ich sieben guldene Leuchter');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'und mitten unterden sieben Leuchtern einen, der war eines Menschen Sohn gleich, der war angetan mit einem Kittel und begurtet um die Brust mit einem guldenen Gürtel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sein Hauptaber und sein Haar war weiß wie weiße Wolle, wie der Schnee, und seine Augen wie eine Feuerflamme');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'und seine Füße gleich wie Messing, das im Ofen glühet, und seine Stimme wie groß Wasserrauschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'und hatte sieben Sterne in seiner rechten Hand, und aus seinem Munde ging ein scharf, zweischneidig Schwert, und sein Angesicht leuchtete wie die helle Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Und als ich ihn sah, fiel ich zu seinen Fußen wie ein Toter. Und er legte seine rechte Hand auf mich und sprach zu mir: Furchte dich nicht! Ich bin der Erste und der Letzte');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'und der Lebendige. Ich war tot; und siehe, ich bin lebendig von Ewigkeit zu Ewigkeit und habe die Schlüssel der Holle und des Todes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Schreibe, was du gesehen hast, und was da ist, und was geschehen soil danach,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'das Geheimnis der sieben Sterne, die du gesehen hast in meiner rechten Hand, und die sieben guldenen Leuchter. Die sieben Sterne sind Engel der sieben Gemeinden, und die sieben Leuchter, die du gesehen hast, sind sieben Gemeinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Und dem Engel der Gemeinde zu Ephesus schreibe: Das saget, der da halt die sieben Sterne in seiner Rechten, der da wandelt mitten unter den sieben guldenen Leuchtern:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Ich weiß deine Werke und deine Arbeit und deine Geduld, und daß du die Bdsen nicht tragen kannst und hast versucht die, so da sagen, sie seien Apostel, und sind\'s nicht, und hast sie Lugner erfunden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'und vertragest und hast Geduld, und um meines Namens willen arbeitest du und bist nicht mude worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Aber ich habe wider dich, daß du die erste Liebe verlassest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Gedenke, wovon du gefallen bist, und tu Buße und tu die ersten Werke! Wo aber nicht, werde ich dir kommen bald und deinen Leuchter wegstoßen von seiner Statte, wo du nicht Buße tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Aber das hast du, daß du die Werke der Nikolaiten hassest, welche ich auch hasse.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt: Wer uberwindet, dem will ich zu essen geben von dem Holz des Lebens, das im Paradies Gottes ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Und dem Engel der Gemeinde zu Smyrna schreibe: Das saget der Erste und der Letzte, der tot war und ist lebendig worden:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Ich weiß deine Werke und deine Trubsal und deine Armut (du bist aber reich) und die Lasterung von denen die da sagen, sie sind Juden, und sind\'s nicht, sondern sind des Satans Schule.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Furchte dich vor der keinem, das du leiden wirst. Siehe, der Teufel wird etliche von euch ins Gefangnis werfen, auf daß ihr versucht werdet; und werdet Trubsal haben zehn Tage. Sei getreu bis an den Tod, so will ich dir die Krone des Lebens geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt: Wer uberwindet, dem soil kein Leid geschehen von dem andern Tode.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Und dem Engel der Gemeinde zu Pergamus schreibe: Das saget, der da hat das scharfe, zweischneidige Schwert:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Ich weifi, was du tust, und wo du wohnest, da des Satans Stuhl ist, und haltst an meinem Namen und hast meinen Glauben nicht verleugnet, auch in den Tagen, in welchen Antipas, mein treuer Zeuge, bei euch getotet ist, da der Satan wohnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Aber ich habe ein Kleines wider dich, dad du daselbst hast, die an der Lehre Bileams halten, welcher lehrete durch den Balak ein Argernis aufrichten vor den Kindern Israel, zu essen der Gdtzenopfer und Hurerei treiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Also hast du auch, die an der Lehre der Nikolaiten halten. Das hasse ich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Tu Buße; wo aber nicht, so werde ich dir bald kommen und mit ihnen kriegen durch das Schwert meines Mundes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt: Wer uberwindet, dem will ich zu essen geben von dem verborgenen Manna und will ihm geben ein gut Zeugnis und mit dem Zeugnis einen neuen Namen geschrieben, weichen niemand kennet, denn der ihn empfanget.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Und dem Engel der Gemeinde zu Thyatira schreibe: Das saget der Sohn Gottes, der Augen hat wie die Feuerflamme und seine Fufie gleich wie Messing:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ich weüi deine Werke und deine Liebe und deinen Dienst und deinen Glauben und deine Geduid, und da(5 du je langer je mehr tust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Aber ich habe ein Kleines wider dich, dad du lassest das Weib Isebel, die da spricht, sie sei eine Prophetin, lehren und verfuhren meine Knechte, Hurerei treiben und Gotzenopfer essen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Und ich habe ihr Zeit gegeben, dad sie sollte Bude tun fur ihre Hurerei; und sie tut nicht Bude.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Siehe, ich werfe sie in ein Bett, und die mit ihr die Ehe gebrochen haben, in grade Trubsal, wo sie nicht Bude tun fur ihre Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Und ihre Kinder will ich zu Tode schlagen. Und sollen erkennen alle Gemeinden, dad ich bin, der die Nieren und Herzen erforschet; und werde geben einem jeglichen unter euch nach euren Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Euch aber sage ich und den andern, die zu Thyatira sind, die nicht haben solche Lehre, und die nicht erkannt haben die Tiefen des Satans (als sie sagen): Ich will nicht auf euch werfen eine andere Last.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Doch was ihr habt, das haltet, bis dad ich komme.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Und wer da uberwindet und halt meine Werke bis ans Ende, dem will ich Macht geben uber die Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Und er soil sie weiden mit einer eisernen Rute, und wie eines Topfers Gefad soil er sie zerschmeiden,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'wie ich von meinem Vater empfangen habe; und will ihm geben den Morgenstern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Und dem Engel der Gemeinde zu Sardes schreibe: Das saget, der die Geister Gottes hat und die sieben Sterne: Ich weid deine Werke; denn du hast den Namen, dad du lebest, und bist tot.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sei wacker und starke das andere, das sterben will; denn ich habe deine Werke nicht vollig erfunden vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'So gedenke nun, wie du empfangen und gehoret hast, und halte es und tu Bude! So du nicht wirst wachen, werde ich uber dich kommen wie ein Dieb, und wirst nicht wissen, welche Stunde ich uber dich kommen werde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Du hast auch wenig Namen zu Sardes, die nicht ihre Kleider besudelt haben; und sie werden mit mir wandeln in weiden Kleidern; denn sie sind\'s wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Wer uberwindet, der soil mit weiden Kleidern angelegt werden, und ich werde seinen Namen nicht austilgen aus dem Buch des Lebens, und ich will seinen Namen bekennen vor meinem Vater und vor seinen Engeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Und dem Engel der Gemeinde zu Philadelphia schreibe: Das saget der Heilige, der Wahrhaftige, der da hat den Schlussel Davids, der auftut und niemand zuschließet, der zuschließet und niemand auftut:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Ich weiß deine Werke. Siehe, ich habe vor dir gegeben eine offene Tur, und niemand kann sie zuschließen; denn du hast eine kleine Kraft und hast mein Wort behalten und hast meinen Namen nicht verleugnet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Siehe, ich werde geben aus des Satanas Schule, die da sagen, sind Juden, und sind\'s nicht, sondern lügen. Siehe, ich will sie machen, daß sie kommen sollen und anbeten zu deinen Fußen und erkennen, daß ich dich geliebet habe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Dieweil du hast behalten das Wort meiner Geduid, will ich auch dich behalten vor der Stunde der Versuchung, die kommen wird uber den ganzen Weltkreis, zu versuchen, die da wohnen auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Siehe, ich komme bald! Halte, was du hast, daß niemand deine Krone nehme!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Wer uberwindet den will ich machen zum Pfeiler in dem Tempel meines Gottes, und soil nicht mehr hinausgehen. Und will auf ihn schreiben den Namen meines Gottes und den Namen des neuen Jerusalem, der Stadt meines Gottes, die vom Himmel herniederkommt, von meinem Gott, und meinen Namen, den neuen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Und dem Engel der Gemeinde zu Laodicea schreibe: Das saget Amen, der treue und wahrhaftige Zeuge, der Anfang der Kreatur Gottes:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Ich weift deine Werke, daß du weder kalt noch warm bist. Ach, daß du kalt Oder warm warest!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Weil du aber lau bist und weder kalt noch warm, werde ich dich ausspeien aus meinem Munde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Du sprichst: Ich bin reich und habe garsattund bedarf nichts, und weiftt nicht, daß du bist elend und jammerlich, arm, blind und bloli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Ich rate dir, daß du Gold von mir kaufest, das mit Feuer durchlautert ist, daß du reich werdest, und weifte Kleider, daß du dich antust, und nicht offenbaret werde die Schande deiner Blofte; und salbe deine Augen mit Augensalbe, daß du sehen mogest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Welche ich liebhabe, die strafe und züchtige ich. So sei nun fleiftig und tu Bufte!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Siehe, ich stehe vor der Tür und klopfe an. So jemand meine Stimme horen wird und die Tur auftun, zu dem werde ich eingehen und das Abendmahl mit ihm halten und ermit mir.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Wer überwindet, dem will ich geben, mit mir auf meinem Stuhl zu sitzen; wie ich überwunden habe und bin gesessen mit meinem Vater auf seinem Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Wer Ohren hat, der hore, was der Geist den Gemeinden sagt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Danach sah ich, und siehe, eine Tur ward aufgetan im Himmel; und die erste Stimme, die ich gehoret hatte mit mir reden als eine Posaune, die sprach: Steig her; ich will dir zeigen, was nach diesem geschehen soil.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Und alsobald war ich im Geist. Und siehe, ein Stuhl ward gesetzt im Himmel, und auf dem Stuhl saft einer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Und der da saft, war gleich anzusehen wie der Stein Jaspis und Sardis; und ein Regenbogen war urn den Stuhl, gleich anzusehen wie ein Smaragd.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Und urn den Stuhl waren vierundzwanzig Stühle; und auf den Stühlen saften vierundzwanzig Alteste, mit weiften Kleidern angetan, und hatten auf ihren Hauptern güldene Kronen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Und von dem Stuhl gingen aus Blitze, Donner und Stimmen; und sieben Fackeln mit Feuer brannten vor dem Stuhl, welches sind die sieben Geister Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Und vor dem Stuhl war ein glasern Meer gleich dem Kristall und mitten im Stuhl und urn den Stuhl vier Tiere voll Augen, vorne und hinten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Und das erste Tier war gleich einem Lowen, und das andere Tier war gleich einem Kalbe, und das dritte hatte ein Antlitz wie ein Mensch und das vierte Tier gleich einem fliegenden Adler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Und ein jegliches der vier Tiere hatte sechs Flugel umher, und waren inwendig voll Augen; und hatten keine Ruhe Tag und Nacht und sprachen: Heilig, heilig, heilig ist Gott, der Herr, der Allmachtige, der da war, und der da ist, und der da kommt!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Und da die Tiere gaben Preis und Ehre und Dank dem, der auf dem Stuhl saft, der da lebet von Ewigkeit zu Ewigkeit,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'fielen die vierundzwanzig Altesten vor den, der auf dem Stuhl saft, und beteten an den, der da lebet von Ewigkeit zu Ewigkeit, und warfen ihre Kronen vor den Stuhl und sprachen:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Herr, du bist würdig, zu nehmen Preis und Ehre und Kraft; denn du hast alle Dinge geschaffen, und durch deinen Willen haben sie das Wesen und sind geschaffen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Und ich sah in der rechten Hand des, der auf dem Stuhl saft, ein Buch, geschrieben inwendig und auswendig, versiegelt mit sieben Siegeln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Und ich sah einen starken Engel predigen mit grofter Stimme: Wer ist würdig, das Buch aufzutun und seine Siegel zu brechen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Und niemand im Himmel noch auf Erden noch unter der Erde konnte das Buch auftun und hineinsehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Und ich weinete sehr, daß niemand würdig erfunden ward, das Buch aufzutun und zu lesen noch hineinzusehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Und einer von den Altesten spricht zu mir: Weine nicht! Siehe, es hat überwunden der Lowe, der da ist vom Geschlecht Judas, die Wurzel Davids, aufzutun das Buch und zu brechen seine sieben Siegel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Und ich sah, und siehe, mitten im Stuhl und den vier Tieren und mitten unter den Altesten stund ein Lamm, wie es erwürget ware, und hatte sieben Horner und sieben Augen, welches sind die sieben Geister Gottes, gesandt in alle Lande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Und es kam und nahm das Buch aus der rechten Hand des, der auf dem Stuhl saft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Und da es das Buch nahm, da fielen die vier Tiere und die vierundzwanzig Altesten vor das Lamm und hatten ein jeglicher Harfen und guldene Schalen voll Rauchwerks, welches sind die Gebete der Heiligen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'und sangen ein neu Lied und sprachen: Du bist würdig, zu nehmen das Buch und aufzutun seine Siegel; denn du bist erwürget und hast uns Gott erkauft mit deinem Blut aus allerlei Geschlecht und Zungen und Volk und Heiden');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'und hast uns unserm Gott zu Konigen und Priestern gemacht, und wir werden Konige sein auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Und ich sah und horete eine Stimme vieler Engel urn den Stuhl und urn die Tiere und urn die Altesten her; und ihre Zahl war viel tausendmal tausend.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Und sprachen mit grofter Stimme: Das Lamm, das erwürget ist, ist würdig, zu nehmen Kraft und Reichtum und Weisheit und Starke und Ehre und Preis und Lob.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Und alle Kreatur, die im Himmel ist und auf Erden und unter der Erde und im Meer, und alles, was drinnen ist, horete ich sagen zu dem, der auf dem Stuhl sali, und zu dem Lamm: Lob und Ehre und Preis und Gewalt von Ewigkeit zu Ewigkeit!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Und die vier Tiere sprachen: Amen. Und die vierundzwanzig Altesten fielen nieder und beteten an den, der da lebet von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Und ich sah, daß das Lamm der Siegel eins auftat. Und ich horete der vier Tiere eines sagen als mit einer Donnerstimme: Komm und siehe zu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Und ich sah, und siehe, ein weili Pferd, und der daraufsali, hatte einen Bogen; und ihm ward gegeben eine Krone; und er zog aus zu uberwinden, und daß er siegete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Und da es das andere Siegel auftat, horete ich das andere Tier sagen: Komm und siehe zu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Und es ging heraus ein ander Pferd, das war rot; und dem, der daraufsali, ward gegeben, den Frieden zu nehmen von der Erde, und dafi sie sich untereinander erwurgten; und ihm ward ein grofi Schwert gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Und da es das dritte Siegel auftat, horete ich das dritte Tier sagen: Komm und siehe zu! Und ich sah, und siehe, ein schwarz Pferd, und der daraufsali, hatte eine Waage in seiner Hand.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Und ich horete eine Stimme unterden vier Tieren sagen: Ein Mali Weizen urn einen Groschen und drei Mali Gerste urn einen Groschen; und dem Ole und Wein tu kein Leid.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Und da es das vierte Siegel auftat, horete ich die Stimme des vierten Tieres sagen: Komm und siehe zu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Und siehe, und ich sah ein fahl Pferd, und der daraufsali, des Name hieli Tod, und die Holle folgte ihm nach. Und ihnen ward Macht gegeben, zu toten das vierte Teil auf der Erde mit dem Schwert und Hunger und mit dem Tod und durch die Tiere auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Und da es das fünfte Siegel auftat, sah ich unter dem Altar die Seelen derer, die erwurget waren urn des Wortes Gottes willen und urn des Zeugnisses willen, das sie hatten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Und sie schrieen mit grolier Stimme und sprachen: Herr, du Heiliger und Wahrhaftiger, wie lange richtest du und rachst nicht unser Blut an denen, die auf der Erde wohnen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Und ihnen wurde gegeben einem jeglichen ein weili Kleid; und ward zu ihnen gesagt, daß sie ruhten noch eine kleine Zeit, bis daß vollends dazukamen ihre Mitknechte und Bruder, die auch sollten noch getotet werden gleich wie sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Und ich sah, daß es das sechste Siegel auftat; und siehe, da ward ein grolies Erdbeben, und die Sonne ward schwarz wie ein harener Sack, und der Mond ward wie Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Und die Sterne des Himmels fielen auf die Erde, gieichwie ein Feigenbaum seine Feigen abwirft, wenn er von groliem Winde bewegt wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Und der Himmel entwich wie ein eingewickelt Buch; und alle Berge und Inseln wurden bewegt aus ihren Ortern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Und die Konige auf Erden und die Obersten und die Reichen und die Hauptleute und die Gewaltigen und alle Knechte und alle Freien verbargen sich in den Kluften und Felsen an den Bergen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'und sprachen zu den Bergen und Felsen: Fallet auf uns und verbergt uns vor dem Angesichte des, der auf dem Stuhl sitzt, und vor dem Zorn des Lammes;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'denn es ist kommen der grolie Tag seines Zorns, und wer kann bestehen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Und danach sah ich vier Engel stehen auf den vier Ecken der Erde, die hielten die vier Winde der Erde, auf daß kein Wind uber die Erde bliese noch liber das Meer noch uber einigen Baum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Und ich sah einen andern Engel aufsteigen von der Sonne Aufgang, der hatte das Siegel des lebendigen Gottes und schrie mit grolier Stimme zu den vier Engeln, welchen gegeben ist, zu beschadigen die Erde und das Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Und er sprach: Beschadiget die Erde nicht noch das Meer noch die Baume, bis daß wir versiegeln die Knechte unsers Gottes an ihren Stirnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Und ich horete die Zahl derer, die versiegelt wurden, hundertvierundvierzigtausend, die versiegelt waren von alien Geschlechtern der Kinder Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'von dem Geschlechte Juda zwolftausend versiegelt; von dem Geschlechte Ruben zwolftausend versiegelt; von dem Geschlechte Gad zwolftausend versiegelt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'von dem Geschlechte Asser zwolftausend versiegelt; von dem Geschlechte Naphthali zwolftausend versiegelt; von dem Geschlechte Manasse zwolftausend versiegelt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'von dem Geschlechte Simeon zwolftausend versiegelt; von dem Geschlechte Levi zwolftausend versiegelt; von dem Geschlechte Isaschar zwolftausend versiegelt;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'von dem Geschlechte Sebulon zwolftausend versiegelt; von dem Geschlechte Joseph zwolftausend versiegelt; von dem Geschlechte Benjamin zwolftausend versiegelt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Danach sah ich, und siehe, eine grofie Schar, welche niemand zahlen konnte, aus alien Heiden und Volkern und Sprachen vor dem Stuhl stehend und vor dem Lamm, angetan mitweilien Kleidern und Palmen in ihren Handen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'schrieen mit grolier Stimme und sprachen: Heil sei dem, der auf dem Stuhl sitzt, unserm Gott, und dem Lamm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Und alle Engel stunden urn den Stuhl und urn die Altesten und urn die vier Tiere und fielen vor dem Stuhl auf ihr Angesicht und beteten Gott an');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'und sprachen: Amen! Lob und Ehre und Weisheit und Dank und Preis und Kraft und Starke sei unserm Gott von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Und es antwortete der Altesten einer und sprach zu mir: Wer sind diese, mit den weißen Kleidern angetan, und woher sind sie kommen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Und ich sprach zu ihm: Herr, du weilit es. Und er sprach zu mir: Diese sind\'s, die kommen sind aus grower Trubsal und haben ihre Kleider gewaschen und haben ihre Kleider hell gemacht im Blut des Lammes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Darum sind sie vordem Stuhl Gottes und dienen ihm Tag und Nacht in seinem Tempel. Und der auf dem Stuhl sitzt, wird uber ihnen wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Sie wird nicht mehr hungern noch dursten; es wird auch nicht auf sie fallen die Sonne Oder irgend eine Hitze.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Denn das Lamm mitten im Stuhl wird sieweiden und leiten zu den lebendigen Wasserbrunnen; und Gott wird abwischen alle Tranen von ihren Augen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Und da es das siebente Siegel auftat, ward eine Stille in dem Himmel bei einer halben Stunde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Und ich sah sieben Engel, die da traten vor Gott, und ihnen wurden sieben Posaunen gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Und ein anderer Engel kam und trat an den Altar und hatte ein gulden Rauchfaß; und ihm ward viel Rauchwerks gegeben, daß er gabe zum Gebet aller Heiligen auf den guldenen Altar vor dem Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Und der Rauch des Rauchwerks vom Gebet der Heiligen ging auf von der Hand des Engels vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Und der Engel nahm das Rauchfali und füllete es mit Feuer vom Altar und schuttete es auf die Erde. Und da geschahen Stimmen und Donner und Blitze und Erdbeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Und die sieben Engel mit den sieben Posaunen hatten sich gerustet zu posaunen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Und der erste Engel posaunete. Und es ward ein Hagel und Feuer, mit Blut gemenget, und fiel auf die Erde. Und das dritte Teil der Baume verbrannte, und alles grune Gras verbrannte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Und der andere Engel posaunete. Und es fuhr wie ein großer Berg mit Feuer brennend ins Meer. Und das dritte Teil des Meeres ward Blut,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'und das dritte Teil der lebendigen Kreaturen im Meer starb, und das dritte Teil der Schiffe wurde verderbet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Und der dritte Engel posaunete. Und es fiel ein großer Stern vom Himmel; der brannte wie eine Fackel und fiel auf das dritte Teil der Wasserstrome und uber die Wasserbrunnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Und der Name des Sterns heilit Wermut; und das dritte Teil ward Wermut. Und viel Menschen starben von den Wassern, daß sie waren so bitter worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Und der vierte Engel posaunete. Und esward geschlagen das dritte Teil der Sonne und das dritte Teil des Mondes und das dritte Teil der Sterne, daß ihr drittes Teil verfinstert ward, und der Tag das dritte Teil nicht schien und die Nacht desselbigengleichen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Und ich sah und horete einen Engel fliegen mitten durch den Himmel und sagen mit großer Stimme: Wehe, wehe, wehe denen, die auf Erden wohnen, vor den andern Stimmen der Posaune der drei Engel, die noch posaunen sollen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Und der funfte Engel posaunete. Und ich sah einen Stern, gefallen vom Himmel auf die Erde, und ihm ward der Schlussel zum Brunnen des Abgrunds gegeben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Und er tat den Brunnen des Abgrunds auf. Und es ging auf ein Rauch aus dem Brunnen wie ein Rauch eines großen Ofens; und es ward verfinstert die Sonne und die Luftvon dem Rauch des Brunnens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Und aus dem Rauch kamen Heuschrecken auf die Erde. Und ihnen ward Macht gegeben, wie die Skorpione auf Erden Macht haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Und es ward zu ihnen gesagt, daß sie nicht beleidigten das Gras auf Erden noch kein Grünes noch keinen Baum, sondern allein die Menschen, die nicht haben das Siegel Gottes an ihren Stirnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Und es ward ihnen gegeben, daß sie nicht toteten, sondern sie qualeten fünf Monden lang; und ihre Qual war wie eine Qual vom Skorpion, wenn er einen Menschen hauet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Und in denselbigen Tagen werden die Menschen den Tod suchen und nicht finden; werden begehren zu sterben, und der Tod wird von ihnen fliehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Und die Heuschrecken sind gleich den Rossen, die zum Kriege bereit sind; und auf ihrem Haupt wie Kronen dem Golde gleich und ihr Antlitz gleich der Menschen Antlitz.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Und hatten Haar wie Weiberhaar, und ihre Zahne waren wie der Lowen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Und hatten Panzer wie eiserne Panzer; und das Rasseln ihrer Flugel wie das Rasseln an den Wagen vieler Rosse, die in den Krieg laufen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Und hatten Schwanze gleich den Skorpionen, und es waren Stacheln an ihren Schwanzen; und ihre Macht war, zu beleidigen die Menschen fünf Monden lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Und hatten uber sich einen Konig, einen Engel aus dem Abgrund; des Name heißt auf hebraisch Abaddon, und auf griechisch hat erden Namen Apollyon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Ein Wehe ist dahin; siehe, es kommen noch zwei Wehe nach dem.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Und dersechste Engel posaunete. Und ich horete eine Stimme aus den vier Ecken des guldenen Altars vor Gott,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'die sprach zu dem sechsten Engel, der die Posaune hatte: Lose auf die vier Engel, gebunden an dem großen Wasserstrom Euphrat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Und eswurden die vier Engel los, die bereit waren auf eine Stunde und auf einen Tag und auf einen Monden und auf ein Jahr, daß sie toteten das dritte Teil der Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Und die Zahl des reisigen Zeuges war viel tausendmal tausend; und ich horete ihre Zahl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Und also sah ich die Rosse im Gesichte, und die daraufsaßen, daß sie hatten feurige und gelbe und schwefelige Panzer; und die Haupter der Rosse wie die Haupter der Lowen; und aus ihrem Munde ging Feuer und Rauch und Schwefel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Von diesen dreien ward getotet der dritte Teil der Menschen von dem Feuer und Rauch und Schwefel, der aus ihrem Munde ging.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Denn ihre Macht war in ihrem Munde, und ihre Schwanze waren den Schlangen gleich, und hatten Haupter, und mit denselbigen taten sie Schaden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Und blieben noch Leute, die nicht getotet wurden von diesen Plagen noch, Buße taten fur die Werke ihrer Hande, daß sie nicht anbeteten die Teufel und die guldenen, silbernen, ehernen, steinernen und holzernen Gotzen, welche weder sehen noch horen noch wandeln konnen,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'die auch nicht Buße taten fur ihre Morde, Zauberei, Hurerei und Dieberei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Und ich sah einen andern starken Engel vom Himmel herabkommen, der war mit einer Wolke bekleidet, und ein Regenbogen auf seinem Haupt und sein Antlitz wie die Sonne und seine Füße wie die Feuerpfeiler.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Und er hatte in seiner Hand ein Buchlein aufgetan; und er setzte seinen rechten Fuß auf das Meer und den linken auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Und er schrie mit großer Stimme wie ein Lowe brullet; und da er schrie, redeten sieben Donner ihre Stimmen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Und da die sieben Donner ihre Stimmen geredet hatten, wollte ich sie schreiben. Da horete ich eine Stimme vom Himmel sagen zu mir: Versiegle, was die sieben Donner geredet haben; dieselbigen schreibe nicht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Und der Engel, den ich sah stehen auf dem Meer und auf der Erde, hub seine Hand auf gen Himmel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'und schwur bei dem Lebendigen von Ewigkeit zu Ewigkeit, der den Himmel geschaffen hat, und was darinnen ist, und die Erde, und was darinnen ist, und das Meer, und was darinnen ist, daß hinfort keine Zeit mehr sein soil,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'sondern in den Tagen der Stimme des siebenten Engels, wenn er posaunen wird, so soil vollendet werden das Geheimnis Gottes, wie er hat verkundiget seinen Knechten und Propheten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Und ich horete eine Stimme vom Himmel abermal mit mir reden und sagen: Gehe hin, nimm das offene Buchlein von der Hand des Engels, der auf dem Meer und auf der Erde stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Und ich ging hin zum Engel und sprach zu ihm: Gib mir das Buchlein! Und er sprach zu mir: Nimm hin und verschlinge es; und es wird dich im Bauch grimmen, aber in deinem Munde wird\'s suß sein wie Honig;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Und ich nahm das Buchlein von der Hand des Engels und verschlang es; und es war suß in meinem Munde wie Honig; und da ich\'s gegessen hatte, grimmete mich\'s im Bauch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Und er sprach zu mir: Du mußt abermal weissagen den Volkern und Heiden und Sprachen und vielen Konigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Und es ward mir ein Rohr gegeben, einem Stecken gleich, und sprach: Stehe auf und miß den Tempel Gottes und den Altar, und die darinnen anbeten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Aber den innern Chor des Tempels wirf hinaus und miß ihn nicht; denn er ist den Heiden gegeben; und die heilige Stadt werden sie zertreten zweiundvierzig Monden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Und ich will meine zween Zeugen geben, und sie sollen weissagen tausend zweihundertundsechzig Tage, angetan mit Sacken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Diese sind zween Olbaume und zwo Fackeln, stehend vor dem Gott der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Und so jemand sie will beleidigen, so gehet das Feuer aus ihrem Munde und verzehret ihre Feinde; und so jemand sie will beleidigen, der muß also getotet werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Diese haben Macht, den Himmel zu verschließen, daß es nicht regne in den Tagen ihrer Weissagung; und haben Macht uber das Wasser, zu wandeln in Blut und zu schlagen die Erde mit allerlei Plage, sooftsiewollen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Und wenn sie ihr Zeugnis geendet haben, so wird das Tier, das aus dem Abgrund aufsteiget, mit ihnen einen Streit halten und wird sie überwinden und wird sie toten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Und ihre Leichname werden liegen auf der Gasse der großen Stadt, die da heißt geistlich die Sodom und Agypten, da unser Herr gekreuziget ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Und es werden ihre Leichname etliche von den Volkern und Geschlechtern und Sprachen drei Tage und einen halben sehen; und werden ihre Leichname nicht lassen in Graber legen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Und die auf Erden wohnen, werden sich freuen uber sie und wohlleben und Geschenke untereinander senden; denn diese zween Propheten qualeten; die auf Erden wohneten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Und nach dreien Tagen und einem halben fuhr in sie der Geist des Lebens von Gott, und sie traten auf ihre Fufie; und eine grade Furcht fiel über die, so sie sahen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Und sie horeten eine grade Stimme vom Himmel zu ihnen sagen: Steiget herauf! Und sie stiegen auf in den Himmel in einer Wolke; und es sahen sie ihre Feinde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Und zu derselbigen Stunde ward ein grad Erdbeben, und das zehnte Teil der Stadt fiel; und wurden getotet in dem Erdbeben siebentausend Namen der Menschen; und die andern erschraken und gaben Ehre dem Gottdes Himmels.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Das andere Wehe istdahin; siehe, das dritte Wehe kommt schnell!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Und dersiebente Engel posaunete. Und es wurden grade Stimmen im Himmel, die sprachen: Es sind die Reiche der Welt unsers Herrn und seines Christus worden; und er wird regieren von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Und die vierundzwanzig Altesten, die vor Gott auf ihren Stühlen saden fielen auf ihr Angesicht und beteten Gott an.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Und sprachen: Wir danken dir, Herr, allmachtiger Gott, der du bist und warst und kunftig bist, dad du hast angenommen deine grade Kraft und herrschest.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Und die Heiden sind zornig worden, und es ist kommen dein Zorn und die Zeit der Toten, zu richten und zu geben den Lohn deinen Knechten, den Propheten, und den Heiligen und denen, die deinen Namen furchten, den Kleinen und den Groden, und zu verderben, die die Erde verderbet haben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Und der Tempel Gottes ward aufgetan im Himmel, und die Arche seines Testaments ward in seinem Tempel gesehen; und es geschahen Blitze und Stimmen und Donner und Erdbeben und ein grader Hagel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Und es erschien ein grod Zeichen im Himmel: ein Weib, mit der Sonne bekleidet, und der Mond unter ihren Füden und auf ihrem Haupt eine Krone von zwolf Sternen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Und sie war schwanger und schrie und war in Kindesnoten und hatte grade Qual zurßeburt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Und es erschien ein ander Zeichen im Himmel; und siehe, ein grader, rater Drache, der hatte sieben Haupter und zehn Horner und auf seinen Hauptern sieben Kronen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Und sein Schwanz zog den dritten Teil der Sterne und warf sie auf die Erde. Und der Drache trat vor das Weib, die gebaren sollte, auf dad, wenn sie geboren hatte, er ihr Kind trade.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Und sie gebar einen Sohn, ein Knablein, der alle Heiden sollte weiden mit der eisernen Rute; und ihr Kind ward entrückt zu Gott und seinem Stuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Und das Weib entfloh in die Wuste, da sie hatte einen Ort bereit von Gott, dad sie daselbst ernahret würde tausend zweihundertundsechzig Tage.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Und es erhub sich ein Strait im Himmel: Michael und seine Engel stritten mit dem Drachen. Und der Drache stritt und seine Engel');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'und siegeten nicht; auch ward ihre Statte nicht mehrfunden im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Und es ward ausgeworfen der grade Drache, die alte Schlange, die da heidt der Teufel und Satanas, der die ganze Welt verführet; und ward geworfen auf die Erde; und seine Engel wurden auch dahin geworfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Und ich horete eine grade Stimme, die sprach im Himmel: Nun ist das Heil und die Kraft und das Reich und die Macht unsers Gottes, seines Christus worden, weil der Verklager unserer Bruder verworfen ist, der sie verklaget Tag und Nacht vor Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Und sie haben ihn überwunden durch des Lammes Blut und durch das Wort ihres Zeugnisses; und haben ihr Leben nicht geliebet bis an den Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Darum freuet euch, ihr Himmel, und die darinnen wohnen! Wehe denen, die auf Erden wohnen und auf dem Meer; denn der Teufel kommt zu euch hinab und hat einen grolien Zorn und weili, daß er wenig Zeit hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Und da der Drache sah, daß er verworfen war auf die Erde, verfolgete er das Weib, die das Knablein geboren hatte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Und es wurden dem Weibe zween Flugel gegeben wie eines grolien Adlers, daß sie in die Wuste floge an ihren Ort, da sie ernahret würde eine Zeit und zwo Zeiten und eine halbe Zeit vor dem Angesichte der Schlange.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Und die Schlange scholi nach dem Weibe aus ihrem Munde ein Wasser wie ein Strom, daß er sie ersaufete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Aber die Erde half dem Weibe und tat ihren Mund auf und verschlang den Strom, den der Drache aus seinem Munde scholi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Und der Drache ward zomig über das Weib und ging hin, zu straiten mit den übrigen von ihrem Samen, die da Gottes Gebote halten und haben das Zeugnis Jesu Christi.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, '');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Und ich trat an den Sand des Meeres. Und sah ein Tier aus dem Meer steigen, das hatte sieben Haupter und zehn Horner und auf seinen Hornern zehn Kronen und auf seinen Hauptern Namen der Lasterung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Und das Tier, das ich sah, wargleich einem Pardel und seine Fülie als Barenfülie und sein Mund eines Ldwen Mund. Und der Drache gab ihm seine Kraft und seinen Stuhl und grolie Macht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Und ich sah seiner Haupter eines, als ware es todlich wund; und seine todliche Wunde ward heil. Und der ganze Erdboden verwunderte sich des Tieres.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Und beteten den Drachen an, der dem Tier die Macht gab, und beteten das Tier an und sprachen: Wer ist dem Tier gleich? und wer kann mit ihm kriegen?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Und esward ihm gegeben ein Mund, zu reden große Dinge und Lasterung; und ward ihm gegeben, daß es mit ihm wahrete zweiundvierzig Monden lang.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Und es tat seinen Mund auf zur Lasterung gegen Gott, zu lastern seinen Namen und seine Hutte, und die im Himmel wohnen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Und ward ihm gegeben, zu streiten mit den Heiligen und sie zu uberwinden. Und ihm ward gegeben Macht uber alle Geschlechter und Sprachen und Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Und alle, die auf Erden wohnen, beten es an, deren Namen nicht geschrieben sind in dem lebendigen Buch des Lammes, das erwurget ist von Anfang der Welt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Hat jemand Ohren, der hore!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'So jemand in das Gefangnis führet, derwird in das Gefangnis gehen; so jemand mit dem Schwert totet, der muß mit dem Schwert getotet werden. Hier ist Geduld und Glaube der Heiligen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Und ich sah ein ander Tier aufsteigen von der Erde; und hatte zwei Horner gleichwie das Lamm und redete wie der Drache.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Und es tut alle Macht des ersten Tieres vor ihm; und es macht, daß die Erde, und die darauf wohnen, anbeten das erste Tier, welches todliche Wunde heil worden war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Und tut grolie Zeichen, daß es auch macht Feuer vom Himmel fallen vor den Menschen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'und verführet, die auf Erden wohnen, urn der Zeichen willen, die ihm gegeben sind, zu tun vor dem Tier; und sagt denen, die auf Erden wohnen, daß sie dem Tier ein Bild machen sollen, das die Wunde vom Schwert hatte und lebendig worden war.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Und esward ihm gegeben, daß es dem Bilde des Tieres den Geist gab, daß des Tieres Bild redete; und daß es machte, daß, welche nicht des Tieres Bild anbeteten, ertotet wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Und machte allesamt, die Kleinen und Grolien, die Reichen und Armen, die Freien und Knechte, daß es ihnen ein Malzeichen gab an ihre rechte Hand Oder an ihre Stirn,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'daß niemand kaufen Oder verkaufen kann, er habe denn das Malzeichen Oder den Namen des Tieres Oder die Zahl seines Namens.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Hier ist Weisheit. Wer Verstand hat, der uberlege die Zahl des Tieres; denn es ist eines Menschen Zahl, und seine Zahl ist sechshundert und sechsundsechzig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Und ich sah ein Lamm stehen auf dem Berge Zion und mit ihm hundertvierundvierzigtausend, die hatten den Namen seines Vaters geschrieben an ihrer Stirn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Und horete eine Stimme vom Himmel als eines grolien Wassers und wie eine Stimme eines grolien Donners; und die Stimme, die ich horete, war als der Harfenspieler, die auf ihren Harfen spielen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Und sangen wie ein neu Lied vor dem Stuhl und vor den vier Tieren und den Altesten; und niemand konnte das Lied lernen ohne die hundertvierundvierzigtausend, die erkauft sind von der Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Diese sind\'s, die mit Weibern nicht befleckt sind; denn sie sind Jungfrauen und folgen dem Lamm nach, wo es hingehet. Diese sind erkauft aus den Menschen zu Erstlingen Gott und dem Lamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Und in ihrem Munde ist kein Falsches funden; denn sie sind unstraflich vor dem Stuhl Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Und ich sah einen Engel fliegen mitten durch den Himmel, der hatte ein ewig Evangelium, zu verkundigen denen, die auf Erden sitzen und wohnen, und alien Heiden und Geschlechtern und Sprachen und Volkern;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'und sprach mit großer Stimme: Furchtet Gott und gebet ihm die Ehre; denn die Zeit seines Gerichts ist kommen; und betet an den, der gemacht hat Himmel und Erde und Meer und die Wasserbrunnen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Und ein anderer Engel folgete nach, der sprach: Sie ist gefallen, sie ist gefallen, Babylon, die große Stadt; denn sie hat mit dem Wein ihrer Hurerei getranket alle Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Und der dritte Engel folgete diesem nach und sprach mit großer Stimme: So jemand das Tier anbetet und sein Bild und nimmt das Malzeichen an seine Stirn Oder an seine Hand,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'derwird von dem Wein der Zornes Gottes trinken, der eingeschenket und lauter ist in seines Zornes Kelch; und wird gequalet werden mit Feuer und Schwefel vor den heiligen Engeln und vor dem Lamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Und der Rauch ihrer Qual wird aufsteigen von Ewigkeit zu Ewigkeit; und sie haben keine Ruhe Tag und Nacht, die das Tier haben angebetet und sein Bild, und so jemand hat das Malzeichen seines Namens angenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Hier ist Geduld der Heiligen; hier sind, die da halten die Gebote Gottes und den Glauben an Jesum.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Und ich horete eine Stimme vom Himmel zu mir sagen: Schreibe: Selig sind die Toten, die in dem Herm sterben, von nun an. Ja, der Geist spricht, daß sie ruhen von ihrer Arbeit; denn ihre Werke folgen ihnen nach.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Und ich sah, und siehe, eine weiße Wolke, und auf der Wolke sitzen einen, der gleich war eines Menschen Sohn; der hatte eine guldene Krone auf seinem Haupt und in seiner Hand eine scharfe Sichel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Und ein anderer Engel ging aus dem Tempel und schrie mit großer Stimme zu dem, der auf der Wolke saß: Schlage an mit deiner Sichel und ernte; denn die Zeit zu ernten ist kommen; denn die Ernte der Erde ist durre worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Und der auf der Wolke saft, schlug an mit seiner Sichel an die Erde; und die Erde ward geerntet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Und ein anderer Engel ging aus dem Tempel im Himmel, der hatte eine scharfe Hippe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Und ein anderer Engel ging aus dem Altar, der hatte Macht über das Feuer und rief mit groftem Geschrei zu dem, der die scharfe Hippe hatte, und sprach: Schlag an mit deiner scharfen Hippe und schneide die Trauben auf Erden; denn ihre Beeren sind reif.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Und der Engel schlug an mit seiner Hippe an die Erde und schnitt die Reben der Erde und warf sie in die grolie Kelter des Zornes Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Und die Kelter ward aufter der Stadt gekeltert; und das Blut ging von der Kelter bis an die Zaume der Pferde, durch tausend sechshundert Feldwegs.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Und ich sah ein ander Zeichen im Himmel, das war graft und wundersam: sieben Engel, die hatten die letzten sieben Plagen; denn mit denselbigen ist vollendet der Zorn Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Und sah als ein glasern Meer, mit Feuer gemenget; und die den Sieg behalten hatten an dem Tier und seinem Bilde und seinem Malzeichen und seines Namens Zahl, daß sie stunden an dem glasernen Meer und hatten Gottes Harfen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Und sangen das Lied Mose\'s, des Knechts Gottes, und das Lied des Lammes und sprachen: Graft und wundersam sind deine Werke, Herr, allmachtiger Gott; gerecht und wahrhaftig sind deine Wege, du Konig der Heiligen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Wer soil dich nicht filrchten, Herr, und deinen Namen preisen? Denn du bistallein heilig. Denn alle Heiden werden kommen und anbeten vordir; denn deine Urteile sind offenbar worden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Danach sah ich, und siehe, da ward aufgetan der Tempel der Hutte des Zeugnisses im Himmel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Und gingen aus dem Tempel die sieben Engel, die die sieben Plagen hatten, angetan mit reiner, heller Leinwand, und umgurtet an ihren Brusten mit guldenen Gurteln.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Und eines der vier Tiere gab den sieben Engeln sieben güldene Schalen voll Zornes Gottes, der da lebet von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Und der Tempel ward voll Rauchs vorder Herrlichkeit Gottes und vor seiner Kraft; und niemand konnte in den Tempel gehen, bis daß die sieben Plagen der sieben Engel vollendet wurden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Und ich horete eine grofte Stimme aus dem Tempel, die sprach zu den sieben Engeln: Gehet hin und qieftet aus die Schaien des Zornes Gottes auf die Erde.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Und dererste ging hin und goft seine Schale aus auf die Erde. Und es ward eine bose und arge Druse an den Menschen, die das Malzeichen des Tieres hatten, und die sein Bild anbeteten.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Und der andere Engel goft aus seine Schale ins Meer. Und es ward Blut, als eines Toten; und alle lebendigen Seelen starben in dem Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Und der dritte Engel goft aus seine Schale in die Wasserstrome und in die Wasserbrunnen. Und es ward Blut.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Und ich horete den Engel sagen: Herr, du bist gerecht, der da ist, und der da war, und heilig, daß du solches geurteilt hast.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Denn sie haben das Blut der Heiligen und der Propheten vergossen, und Blut hast du ihnen zu trinken gegeben; denn sie sind\'s wert.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Und ich horete einen andern Engel aus dem Altar sagen: Ja, Herr, allmachtiger Gott, deine Gerichte sind wahrhaftig und gerecht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Und der vierte Engel goft aus seine Schale in die Sonne, und ward ihm gegeben, den Menschen heift zu machen mit Feuer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Und den Menschen ward heift vor grafter Hitze, und lasterten den Namen Gottes, der Macht hat fiber diese Plagen; und taten nicht Bufte, ihm die Ehre zu geben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Und der funfte Engel goft aus seine Schale auf den Stuhl des Tieres. Und sein Reich ward verfinstert; und sie zerbissen ihre Zungen vor Schmerzen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'und lasterten Gott im Himmel vor ihren Schmerzen und vor ihren Drüsen; und taten nicht Bufte fur ihre Werke.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Und der sechste Engel goft aus seine Schale auf den groften Wasserstrom Euphrat; und das Wasser vertrocknete, auf daß bereitet würde der Weg den Konigen vom Aufgang der Sonne.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Und ich sah aus dem Munde des Drachen und aus dem Munde des Tieres und aus dem Munde des falschen Propheten drei unreine Geister gehen gleich den Froschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Und sind Geister der Teufel; die tun Zeichen und gehen aus zu den Konigen auf Erden und auf den ganzen Kreis der Welt, sie zu versammeln in den Streit auf jenen groften Tag Gottes, des Allmachtigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Siehe, ich komme wie ein Dieb! Selig ist, der da wachet und halt seine Kleider, daß er nicht bloft wandele, und man nicht seine Schande sehe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Und er hat sie versammelt an einen Ort, der da heiftt auf hebraisch Harmageddon.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Und der siebente Engel goft aus seine Schale in die Luft. Und es ging aus eine Stimme vom Himmel aus dem Stuhl, die sprach: Es ist geschehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Und es wurden Stimmen und Donner und Blitze; und ward ein groftes Erdbeben, daß solches nicht gewesen ist, seit der Zeit Menschen auf Erden gewesen sind, solches Erdbeben also graft.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Und aus der groften Stadt wurden drei Teile, und die Stadte der Heiden fielen. Und Babylon, der grolien, ward gedacht vor Gott, ihr zu geben den Kelch des Weins von seinem grimmigen Zorn.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Und alle Inseln entflohen, und keine Berge wurden funden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Und ein grower Hagel als ein Zentner fiel vom Himmel auf die Menschen. Und die Menschen lasterten Gott uber der Plage des Hagels; denn seine Plage ist sehrgroli.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Und es kam einervon den sieben Engeln, die die sieben Schalen hatten, redete mit mir und sprach zu mir: Komm, ich will dir zeigen das Urteil der grolien Hure, die da auf vielen Wassern sitzt,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'mit welcher gehuret haben die Konige auf Erden, und die da wohnen auf Erden, trunken worden sind von dem Wein ihrer Hurerei.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Und er brachte mich im Geist in die Wuste. Und ich sah das Weib sitzen auf einem rosinfarbenen Tier; das war voll Namen der Lasterung und hatte sieben Haupter und zehn Horner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Und das Weib war bekleidet mit Scharlach und Rosinfarbe und ubergüldet mit Golde und Edelgestein und Perlen und hatte einen güldenen Becher in der Hand voll Greuels und Unsauberkeit ihrer Hurerei;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'und an ihrer Stirn geschrieben den Namen, das Geheimnis: Die grolie Babylon, die Mutter der Hurerei und alter Greuel auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Und ich sah das Weib trunken von dem Blut der Heiligen und von dem Blut der Zeugen Jesu. Und ich verwunderte mich sehr, da ich sie sah.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Und der Engel sprach zu mir: Warum verwunderst du dich? Ich will dir sagen das Geheimnis von dem Weibe und von dem Tier, das sie tragt, und hat sieben Haupter und zehn Horner.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Das Tier, das du gesehen hast, ist gewesen und ist nicht und wird wiederkommen aus dem Abgrund und wird fahren in die Verdammnis, und werden sich verwundern, die auf Erden wohnen (deren Namen nicht geschrieben stehen in dem Buch des Lebens von Anfang der Welt), wenn sie sehen das Tier, daß es gewesen ist und nicht ist, wiewohl es doch ist.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Und hier ist der Sinn, da Weisheit zu gehoret. Die sieben Haupter sind sieben Berge, aufwelchen das Weib sitzt, und sind sieben Konige.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Funf sind gefallen, und einer ist, und der andere ist noch nicht kommen, und wenn er kommt, mufi er eine kleine Zeit bleiben.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Und das Tier, das gewesen ist und nicht ist, das ist der achte und ist von den sieben und fahrt in die Verdammnis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Und die zehn Horner, die du gesehen hast, das sind zehn Konige, die das Reich noch nicht empfangen haben; aberwie Konige werden sie eine Zeit Macht empfangen mit dem Tier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Diese haben eine Meinung und werden ihre Kraft und Macht geben dem Tier.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Diese werden streiten mit dem Lamm, und das Lamm wird sie uberwinden; denn es ist der Herr aller Herren und der Konig aller Konige; und mit ihm die Berufenen und Auserwahlten und Glaubigen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Und er sprach zu mir: Die Wasser, die du gesehen hast, da die Hure sitzt, sind Volker und Scharen und Heiden und Sprachen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Und die zehn Horner, die du gesehen hast auf dem Tier, die werden die Hure hassen und werden sie wuste machen und blofi und werden ihr Fleisch essen und werden sie mit Feuer verbrennen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Denn Gott hat\'s ihnen gegeben in ihr Herz, zu tun seine Meinung und zu tun einerlei Meinung und zu geben ihr Reich dem Tier, bis dafi vollendet werden die Worte Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Und das Weib, das du gesehen hast, ist die grolie Stadt, die das Reich hat uber die Konige auf Erden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Und danach sah ich einen andern Engel niederfahren vom Himmel, der hatte eine grofie Macht, und die Erde ward erleuchtet von seiner Klarheit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Und schrie aus Macht mit grolier Stimme und sprach: Sie ist gefallen, sie ist gefallen, Babylon, die grolie, und eine Behausung der Teufel worden und ein Behaltnis aller unreinen Geister und ein Behaltnis aller unreinen und feindseligen Vogel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Denn von dem Wein des Zorns ihrer Hurerei haben alle Heiden getrunken; und die Konige auf Erden haben mit ihr Hurerei getrieben, und ihre Kaufleute sind reich worden von ihrer grolien Wollust.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Und ich horete eine andere Stimme vom Himmel, die sprach: Gehet aus von ihr, mein Volk, daß ihr nicht teilhaftig werdet ihrer Sünden, auf daß ihr nicht empfanget etwas von ihren Plagen;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Denn ihre Sünden reichen bis in den Himmel, und Gott denkt an ihren Frevel.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Bezahlet sie, wie sie euch bezahlet hat, und macht\'s ihr zwiefaltig nach ihren Werken; und mit welchem Kelch sie euch eingeschenket hat, schenket ihr zwiefaltig ein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Wieviel sie sich herrlich gemacht und ihren Mutwillen gehabt hat, so viel schenket ihr Qual und Leid ein. Denn sie spricht in ihrem Herzen: Ich sitze und bin eine Konigin und werde keine Witwe sein, und Leid werde ich nicht sehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Darum werden ihre Plagen auf einen Tag kommen, der Tod, Leid und Hunger; mit Feuer wird sie verbrannt werden. Denn stark ist Gott der Herr, der sie richten wird.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Und es werden sie beweinen und sich uber sie beklagen die Konige auf Erden, die mit ihr gehuret und Mutwillen getrieben haben, wenn sie sehen werden den Rauch von ihrem Brande.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Und werden von feme stehen vor Furcht ihrer Qual und sprechen: Wehe, wehe, die grofte Stadt Babylon, die starke Stadt! Auf eine Stunde ist dein Gericht kommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Und die Kaufleute auf Erden werden weinen und Leid tragen bei sich selbst, dafi ihre Ware niemand mehr kaufen wird,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'die Ware des Goldes und Silbers und Edelgesteins und die Perlen und Seide und Purpur und Scharlach und allerlei Thinenholz und allerlei Gefaft von Elfenbein und allerlei Gefaft von kostlichem Holz und von Erz und von Eisen und von Marmor');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'und Zimt und Thymian und Salben und Weihrauch und Wein und 01 und Semmeln und Weizen und Vieh und Schafe und Pferde und Wagen und Leichname und Seelen der Menschen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Und das Obst, daran deine Seele Lust hatte, ist von dir gewichen; und alles, was vollig und herrlich war, ist von dir gewichen; und du wirst solches nicht mehrfinden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Die Kaufleute solcher Ware, die von ihr sind reich worden, werden von feme stehen vor Furcht ihrer Qual, weinen und klagen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'und sagen: Wehe, wehe! die grofte Stadt, die bekleidet war mit Seide und Purpur und Scharlach und uberguldet war mit Golde und Edelgestein und Perlen!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Denn in einer Stunde ist verwustet solcher Reichtum. Und alle Schiffsherren und der Haufe, die auf den Schiffen hantieren, und Schiffsleute, die auf dem Meer hantieren, stunden von feme');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'und schrieen, da sie den Rauch von ihrem Brande sahen, und sprachen: Wer ist gleich der groften Stadt?');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Und sie warfen Staub auf ihre Haupter und schrieen, weineten und klagten und sprachen: Wehe, wehe! die grolie Stadt, in welcher reich worden sind alle, die da Schiffe im Meer hatten, von ihrer Ware! Denn in einer Stunde ist sie verwustet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Freue dich uber sie, Himmel und ihr heiligen Apostel und Propheten! Denn Gott hat euer Urteü an ihr gerichtet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Und ein starker Engel hub einen groften Stein auf als einen Muhlstein warf ihn ins Meer und sprach: Also wird mit einem Sturm verworfen die grofte Stadt Babylon und nicht mehr erfunden werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Und die Stimme der Sanger und Saitenspieler, Pfeifer und Posaunen soil nicht mehr in dir gehoret werden; und kein Handwerksmann einiges Handwerks soil mehr in dir erfunden werden; und die Stimme der Mühle soil nicht mehr in dir gehoret werden;');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'und das Licht der Leuchte soil nicht mehr in dir leuchten; und die Stimme des Brautigams und der Braut soil nicht mehr in dir gehoret werden; denn deine Kaufleute waren Fursten auf Erden; denn durch deine Zauberei sind verirret worden alle Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Und das Blut der Propheten und der Heiligen ist in ihr erfunden worden und aller derer, die auf Erden erwurget sind.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Danach horete ich eine Stimme grafter Scharen im Himmel, die sprachen: Halleluja! Heil und Preis, Ehre und Kraft sei Gott, unserm Herm!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Denn wahrhaftig und gerecht sind seine Gerichte, dafi er die grofte Hure verurteilet hat, welche die Erde mit ihrer Hurerei verderbet, und hat das Blut seiner Knechte von ihrer Hand geracht.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Und sprachen zum andernmal: Halleluja! Und der Rauch gehet auf ewiglich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Und die vierundzwanzig Altesten und die vier Tiere fielen nieder und beteten an Gott, der auf dem Stuhl saft, und sprachen: Amen Halleluja!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Und eine Stimme ging von dem Stuhl: Lobet unsern Gott, alle seine Knechte, und die ihn furchten, beide, klein und graft!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Und ich horete eine Stimme einer groften Schar und wie eine Stimme grafter Wasser und wie eine Stimme starker Donner, die sprachen: Halleluja! Denn der allmachtige Gott hat das Reich eingenommen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Lasset uns freuen und frohlich sein und ihm die Ehre geben; denn die Hochzeit des Lammes ist kommen, und sein Weib hat sich bereitet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Und es ward ihr gegeben, sich anzutun mit reiner und schoner Seide. (Die Seide aber ist die Gerechtigkeit der Heiligen.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Und er sprach zu mir: Schreibe: Selig sind, die zum Abendmahl des Lammes berufen sind. Und er sprach zu mir: Dies sind wahrhaftige Worte Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Und ich fiel vor ihn zu seinen Füften, ihn anzubeten. Und er sprach zu mir: Siehe zu, tu es nicht; ich bin dein Mitknecht und deiner Bruder und derer, die das Zeugnis Jesu haben. Bete Gott an! (Das Zeugnis aber Jesu ist der Geist der Weissagung.)');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Und ich sah den Himmel aufgetan; und siehe, ein weift Pferd, und der darauf saft, hieft Treu und Wahrhaftig und richtet und streitet mit Gerechtigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Und seine Augen sind wie eine Feuerflamme, und auf seinem Hauptviel Kronen; und hatte einen Namen geschrieben den niemand wuftte denn er selbst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Und warangetan mit einem Kleide, das mit Blut besprenget war; und sein Name heiftt Gottes Wort.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Und ihm folgete nach das Heer im Himmel auf weiften Pferden, angetan mitweifter und reiner Seide.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Und aus seinem Munde ging ein scharf Schwert, daß er damit die Heiden schluge; und er wird sie regieren mit dereisernen Rute. Und ertrittdie Kelter des Weins des grimmigen Zornes des allmachtigen Gottes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Und hat einen Namen geschrieben auf seinem Kleid und auf seiner Hüfte also: Ein Konig aller Konige und ein Herr aller Herren.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Und ich sah einen Engel in der Sonne stehen; und er schrie mit grafter Stimme und sprach zu alien Vogeln, die unter dem Himmel fliegen: Kommet und versammelt euch zu dem Abendmahl des grolien Gottes,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'dad ihr esset das Fleisch der Konige und der Hauptieute und das Fleisch derßtarken und der Pferde und derer, die daraufsitzen, und das Fleisch alter Freien und Knechte, beide, der Kleinen und der Grolien.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Und ich sah das Tier und die Konige auf Erden und ihre Heere versammelt, Streit zu halten mit dem, der auf dem Pferde sali, und mit seinem Fleer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Und das Tier ward gegriffen und mit ihm der falsche Prophet, der die Zeichen tat vor ihm, durch welche er verfuhrete, die das Malzeichen des Tieres nahmen, und die das Bild des Tieres anbeteten; lebendig wurden diese beide in den feurigen Pfuhl geworfen, der mit Schwefel brannte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Und die andern wurden erwurget mit dem Schwert des, der auf dem Pferde sali, das aus seinem Munde ging. Und alle Vogel wurden satt von ihrem Fleisch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Und ich sah einen Engel vom Himmel fahren, der hatte den Schlüssel zum Abgrund und eine grolie Kette in seiner Hand');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'und ergriff den Drachen, die alte Schlange, welche ist der Teufel und der Satan, und band ihn tausend Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Und warf ihn in den Abgrund und verschloli ihn und versiegelte oben darauf, daß er nicht verführen sollte die Heiden, bis daß vollendet wurden tausend Jahre; und danach muli er los werden eine kleine Zeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Und ich sah Stuhle, und sie setzten sich darauf, und ihnen ward gegeben das Gericht; und die Seelen der Enthaupteten urn des Zeugnisses Jesu und urn des Wortes Gottes willen, und die nicht angebetet hatten das Tier noch sein Bild und nicht genommen hatten sein Malzeichen an ihre Stirn und auf ihre Hand: diese lebten und regierten mit Christo tausend Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Die andern Toten aber wurden nicht wieder lebendig, bis daß tausend Jahre vollendet wurden. Dies ist die erste Auferstehung.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Selig ist der und heilig, der teilhat an der ersten Auferstehung; uber solche hat der andere Tod keine Macht, sondern sie werden Priester Gottes und Christi sein und mit ihm regieren tausend Jahre.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Und wenn tausend Jahre vollendet sind, wird der Satanas los werden aus seinem Gefangnis');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'und wird ausgehen, zu verführen die Heiden in den vier Vrtern der Erde, den Gog und Magog, sie zu versammeln in einen Streit, welcher Zahl ist wie der Sand am Meer.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Und sie traten auf die Breite der Erde und umringeten das Heerlagerder Heüigen und die geliebte Stadt. Und es fiel das Feuer von Gott aus dem Himmel und verzehrete sie.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Und der Teufel, der sie verfuhrete, ward geworfen in den feurigen Pfuhl und Schwefel, da das Tier und der falsche Prophet war; und werden gequalet werden Tag und Nacht von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Und ich sah einen großen weilien Stuhl und den, der darauf sali, vor welches Angesicht floh die Erde und der Himmel; und ihnen ward keine Statte gefunden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Und ich sah die Toten, beide, groli und klein, stehen vor Gott. Und die Bucher wurden aufgetan; und ein ander Buch ward aufgetan, welches ist des Lebens. Und die Toten wurden gerichtet nach der Schrift in den Büchern, nach ihren Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Und das Meer gab die Toten, die darinnen waren; und der Tod und die Holle gaben die Toten, die darinnen waren. Und sie wurden gerichtet, ein jeglicher nach seinen Werken.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Und der Tod und die Holle wurden geworfen in den feurigen Pfuhl. Das ist der andere Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Und so jemand nicht ward erfunden geschrieben in dem Buch des Lebens, der ward geworfen in den feurigen Pfuhl.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Und ich sah einen neuen Himmel und eine neue Erde. Denn der erste Himmel und die erste Erde verging, und das Meer ist nicht mehr.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Und ich, Johannes, sah die heilige Stadt, das neue Jerusalem, von Gott aus dem Himmel herabfahren, zubereitet als eine geschmückte Braut ihrem Mann.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Und horete eine große Stimme von dem Stuhl, die sprach: Siehe da, eine Hütte Gottes bei den Menschen! Und erwird bei ihnen wohnen; und sie werden sein Volk sein, und er selbst, Gott mit ihnen, wird ihr Gott sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Und Gott wird abwischen alle Tranen von ihren Augen. Und der Tod wird nicht mehr sein, noch Leid noch Geschrei noch Schmerzen wird mehr sein; denn das Erste ist vergangen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Und der auf dem Stuhl saß, sprach: Siehe, ich mache alles neu. Und er spricht zu mir: Schreibe; denn diese Worte sind wahrhaftig und gewif L');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Und er sprach zu mir: Es istgeschehen. Ich bin das A und das O der Anfang und das Ende. Ich will dem Durstigen geben von dem Brunn des lebendigen Wassers umsonst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Wer überwindet der wird\'s alles ererben; und ich werde sein Gott sein, und er wird mein Sohn sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Den Verzagten aber und Unglaubigen, den Greulichen und Totschlagern und Hurern und Zauberern und Abgottischen und alien Lugnern, deren Teil wird sein in dem Pfuhl, der mit Feuer und Schwefel brennet, welches ist der andere Tod.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Und es kam zu mir einer von den sieben Engeln, welche die sieben Schalen voll hatten der letzten sieben Plagen, und redete mit mir und sprach: Komm, ich will dir das Weib zeigen, die Braut des Lammes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Und fuhrete mich hin im Geist auf einen großen und hohen Berg und zeigte mir die große Stadt, das heilige Jerusalem, herniederfahren aus dem Himmel von Gott.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Und hatte die Herrlichkeit Gottes; und ihr Licht war gleich dem alleredelsten Stein, einem hellen Jaspis.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Und hatte große und hohe Mauern und hatte zwolf Tore und auf den Toren zwolf Engel und Namen geschrieben, welche sind die zwolf Geschlechter der Kinder Israel:');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'vom Morgen drei Tore, von Mitternacht drei Tore, vom Mittag drei Tore, vom Abend drei Tore.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Und die Mauer der Stadt hatte zwolf Grunde und in denselbigen die Namen der zwolf Apostel des Lammes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Und der mit mir redete, hatte ein gulden Rohr, daß er die Stadt messen sollte und ihre Tore und Mauern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Und die Stadt liegt viereckig, und ihre Lange ist so groß als die Breite. Und er maß die Stadt mit dem Rohr auf zwolftausend Feldwegs. Die Lange und die Breite und die Hohe der Stadt sind gleich.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Und er maß ihre Mauern, hundertvierundvierzig Ellen, nach dem Maß eines Menschen, das der Engel hat.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Und der Bau ihrer Mauern war von Jaspis und die Stadt von lauterem Golde gleich dem reinen Glase.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Und die Grunde der Mauern und der Stadt waren geschmuckt mit allerlei Edelsteinen. Der erste Grund war ein Jaspis; der andere ein Saphir, der dritte ein Chalzedonier, der vierte ein Smaragd,');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'der funfte ein Sardonich, der sechste ein Sardis, der siebente ein Chrysolith, der achte ein Beryli, der neunte ein Topasier, der zehnte ein Chrysopras, der elfte ein Hyazinth, der zwolfte ein Amethyst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Und die zwolf Tore waren zwolf Perlen, und ein jeglich Tor war von einer Perle. Und die Gassen der Stadt waren lauter Gold, als ein durchscheinend Glas.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Und ich sah keinen Tempel darinnen; denn der Herr, der allmachtige Gott, ist ihr Tempel und das Lamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Und die Stadt bedarf keiner Sonne noch des Mondes, daß sie ihrscheinen; denn die Herrlichkeit Gottes erleuchtet sie, und ihre Leuchte ist das Lamm.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Und die Heiden, die da selig werden, wandeln in demselbigen Licht. Und die Konige auf Erden werden ihre Herrlichkeit in dieselbige bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Und ihre Tore werden nicht verschlossen des Tages; denn da wird keine Nacht sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Und man wird die Herrlichkeit und die Ehre der Heiden in sie bringen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Und wird nicht hineingehen irgendein Gemeines, und das da Greuel tut und Lugen, sondern die geschrieben sind in dem lebendigen Buch des Lammes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Und er zeigte mir einen lauteren Strom des lebendigen Wassers, klarwie ein Kristall; der ging von dem Stuhl Gottes und des Lammes.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Mitten auf ihrer Gasse und auf beiden Seiten des Stromes stund Holz des Lebens, das trug zwblferlei Fruchte und brachte seine Fruchte alle Monden; und die Blatter des Holzes dieneten zu der Gesundheit der Heiden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Und wird kein Verbannetes mehr sein; und der Stuhl Gottes und des Lammes wird darinnen sein; und seine Knechte werden ihm dienen');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'und sehen sein Angesicht; und sein Name wird an ihren Stirnen sein.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Und wird keine Nacht da sein, und nicht bedurfen einer Leuchte Oder des Lichts der Sonne; denn Gott der Herr wird sie erleuchten, und sie werden regieren von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Und er sprach zu mir: Diese Worte sind gewiß und wahrhaftig. Und Gott, der Herr der heiligen Propheten, hat seinen Engel gesandt, zu zeigen seinen Knechten, was bald geschehen muß.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Siehe, ich komme bald! Selig ist, der da halt die Worte der Weissagung in diesem Buch.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Und ich bin Johannes, der solches gesehen und gehoret hat. Und da ich es gehoret und gesehen, fiel ich nieder, anzubeten zu den Fußen des Engels, der mir solches zeigete.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Und er spricht zu mir: Siehe zu, tu es nicht; denn ich bin dein Mitknecht und deiner Bruder, der Propheten, und derer, die da halten die Worte dieses Buchs; bete Gott an!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Und er spricht zu mir: versiegle nicht die Worte der Weissagung in diesem Buch; denn die Zeit ist nahe.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Wer bose ist, der sei immerhin bose; und wer unrein ist, der sei immerhin unrein. Aber wer fromm ist, der sei immerhin fromm; und wer heilig ist, der sei immerhin heilig.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Und siehe, ich komme bald und mein Lohn mit mir, zu geben einem jeglichen, wie seine Werke sein werden.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ich bin das A und das 0, der Anfang und das Ende, der Erste und der Letzte.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Selig sind, die seine Gebote halten, auf daß ihre Macht sei an dem Holz des Lebens, und zu den Toren eingehen in die Stadt.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Denn draußen sind die Hunde und die Zauberer und die Hurer und die Totschlager und die Abgottischen und alle, die liebhaben und tun die Luge.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ich, Jesus, habe gesandt meinen Engel, solches euch zu zeugen an die Gemeinden. Ich bin die Wurzel des Geschlechts Davids, ein helier Morgenstern.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Und der Geist und die Braut sprechen: Komm! Und wer es horet, der spreche: Komm! Und wen durstet, der komme; und wer da will, der nehme das Wasser des Lebens umsonst.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Ich bezeuge aber alien, die da horen die Worte der Weissagung in diesem Buch: So jemand dazusetzt, so wird Gott zusetzen auf ihn die Plagen, die in diesem Buch geschrieben stehen.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Und so jemand davontut von den Worten des Buchs dieser Weissagung, so wird Gott abtun sein Teil vom Buch des Lebens und von der heiligen Stadt und von dem, was in diesem Buch geschrieben stehet.');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Es spricht, der solches zeuget: Ja, ich komme bald. Amen. Ja komm, Herr Jesu!');
INSERT INTO `GerBoLut_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Die Gnade unsers Herrn Jesu Christi sei mit euch alien! Amen.');
